        , (N'USP_OSInformation',N'Betriebssystem und Uptime','SERVER',N'CPU, Memory, Worker und Server Health','FOLLOW_UP','SERVER','LIVE_SNAPSHOT','LOW','SERVER_HEALTH_CURRENT',0,0,0,'CORE',NULL,N'Zeigt Betriebssystem, Virtualisierung, Speicher, Zeit, Uptime und Plattformgrenzen.',N'Plattformcontext ergänzt, ersetzt aber keine Host-, Hypervisor- oder Cloudmetriken.',N'EXEC [monitor].[USP_OSInformation] @ResultSetArt = ''CONSOLE'';',N'Documentation/Analysis_Guides/Procedures/USP_OSInformation.md',NULL)
        , (N'USP_ServerSecurityConfiguration',N'Sicherheitskonfiguration prüfen','SERVER',N'CPU, Memory, Worker und Server Health','ENTRY','SERVER','CATALOG_CONFIGURATION','LOW','SECURITY_CONFIGURATION_CURRENT',0,0,0,'CORE',NULL,N'Erzeugt Sicherheits-Reviewbefunde zu relevanten Serveroptionen.',N'Nur Konfigurationssicht; Berechtigungen, Identitäten und externe Sicherheitskontrollen separat prüfen.',N'EXEC [monitor].[USP_ServerSecurityConfiguration] @ResultSetArt = ''CONSOLE'';',N'Documentation/Analysis_Guides/Procedures/USP_ServerSecurityConfiguration.md',NULL)
        , (N'USP_AuditConfigurationAnalysis',N'SQL-Auditkonfiguration prüfen','SERVER',N'Konfiguration und Sicherheit','ENTRY','MULTI_DATABASE','CATALOG_CONFIGURATION','LOW','SECURITY_CONFIGURATION_CURRENT',0,0,0,'CORE',NULL,N'Inventarisiert sichtbare SQL-Audits, Spezifikationen und Runtimezustand ohne Auditpayloads.',N'Auditereignisse, Dateiinhalte und Zielpfade bleiben ausgeschlossen; fehlende Sicht ist kein Abwesenheitsbeweis.',N'EXEC [monitor].[USP_AuditConfigurationAnalysis] @ResultSetArt = ''CONSOLE'';',N'Documentation/Analysis_Guides/Procedures/USP_AuditConfigurationAnalysis.md',NULL)
