-- BEGIN SOURCE: Code/01_Common/030_VW_AnalyseAccessPolicy.sql
/*
===============================================================================
Objekt       : monitor.VW_AnalyseAccessPolicy
Version      : 1.0.0
Stand        : 2026-07-14
Typ          : View
Zweck        : Stellt die rein lesende Policyquelle für eine oder mehrere
               AD-Gruppen je ressourcenintensiver Analyseklasse bereit.
Standard     : Die ausgelieferte View enthält keine Zeilen. Solange keine aktive
               Gruppendefinition vorhanden ist, sind alle Analyseklassen erlaubt.
Policy       : Sobald mindestens eine aktive Definition vorhanden ist, sind
               gruppengeschützte Analyseklassen nur für passende Gruppen erlaubt.
               Ein Eintrag mit AnalysisClass='*' gilt für alle geschützten Klassen.
Sysadmin     : sysadmin wird unabhängig von Gruppenregeln immer zugelassen.
Fallback     : Die effektive Prüfung verwendet zuerst sys.login_token und danach
               IS_MEMBER als Fallback.
Parameter    : Keine.
Resultset    : AnalysisClass, ADGroupName, IsEnabled, ValidFromUtc, ValidToUtc,
               Priority, Comment.
Berechtigung : SELECT auf der View; keinerlei GRANT/DENY/REVOKE im Framework.
Änderung     : Gruppen werden später durch CREATE OR ALTER VIEW gepflegt.
Beispiel     : Siehe kommentierte VALUES-Vorlage am Dateiende.
Änderungen   : 1.0.0 - Erstfassung Phase 1A.
===============================================================================
*/
CREATE OR ALTER VIEW [monitor].[VW_AnalyseAccessPolicy]
AS
    SELECT
        [p].[AnalysisClass],
        [p].[ADGroupName],
        [p].[IsEnabled],
        [p].[ValidFromUtc],
        [p].[ValidToUtc],
        [p].[Priority],
        [p].[Comment]
    FROM
    (
        VALUES
        (
            CAST(NULL AS varchar(64)),
            CAST(NULL AS nvarchar(256)),
            CAST(NULL AS bit),
            CAST(NULL AS datetime2(0)),
            CAST(NULL AS datetime2(0)),
            CAST(NULL AS smallint),
            CAST(NULL AS nvarchar(1000))
        )
    ) AS [p]
    (
        [AnalysisClass],
        [ADGroupName],
        [IsEnabled],
        [ValidFromUtc],
        [ValidToUtc],
        [Priority],
        [Comment]
    )
    WHERE 1 = 0;
GO

/*
Beispiel für eine spätere, bewusst manuell gepflegte Policy-View:

CREATE OR ALTER VIEW monitor.VW_AnalyseAccessPolicy
AS
    SELECT
        p.AnalysisClass,
        p.ADGroupName,
        p.IsEnabled,
        p.ValidFromUtc,
        p.ValidToUtc,
        p.Priority,
        p.Comment
    FROM
    (
        VALUES
          (CAST('PLAN_CACHE_DEEP' AS varchar(64)), CAST(N'CONTOSO\\SQL_Monitor_Deep' AS nvarchar(256)), CAST(1 AS bit), CAST(NULL AS datetime2(0)), CAST(NULL AS datetime2(0)), CAST(100 AS smallint), CAST(N'Plan-Cache Deep Analysis' AS nvarchar(1000))),
          (CAST('SHOWPLAN_XML_DEEP' AS varchar(64)), CAST(N'CONTOSO\\SQL_Monitor_Deep' AS nvarchar(256)), CAST(1 AS bit), CAST(NULL AS datetime2(0)), CAST(NULL AS datetime2(0)), CAST(100 AS smallint), CAST(N'Showplan XML Deep Analysis' AS nvarchar(1000))),
          (CAST('*' AS varchar(64)), CAST(N'CONTOSO\\SQL_Server_Admins' AS nvarchar(256)), CAST(1 AS bit), CAST(NULL AS datetime2(0)), CAST(NULL AS datetime2(0)), CAST(10 AS smallint), CAST(N'Alle geschützten Analyseklassen' AS nvarchar(1000)))
    ) AS [p]
    (
        [AnalysisClass],
        [ADGroupName],
        [IsEnabled],
        [ValidFromUtc],
        [ValidToUtc],
        [Priority],
        [Comment]
    );
GO
*/
-- END SOURCE: Code/01_Common/030_VW_AnalyseAccessPolicy.sql

-- BEGIN SOURCE: Code/01_Common/040_VW_AnalyseAccessCurrent.sql
/*
===============================================================================
Objekt       : monitor.VW_AnalyseAccessCurrent
Version      : 1.0.0
Stand        : 2026-07-14
Typ          : View
Zweck        : Ermittelt den effektiven Zugriff des aktuellen Logins auf jede
               Analyseklasse.
Priorität    : 1. ungeschützte Klasse, 2. sysadmin-Bypass, 3. offene Policy bei
               null aktiven Regeln, 4. Match über sys.login_token, 5. IS_MEMBER.
Parameter    : Keine.
Resultset    : Login-/Policy-/Matchinformationen und IsAllowed je Analyseklasse.
Berechtigung : Benötigt Lesbarkeit der Framework-Views und der für den aktuellen
               Login verfügbaren Tokeninformationen. Keine Rechtevergabe.
Eigenlast    : Sehr gering; liest nur kleine konstante Views, sys.login_token
               und führt IS_MEMBER ausschließlich für aktive Policyzeilen aus.
Locking      : Keine Benutzerobjekte; keine persistierenden Schreibzugriffe.
Hinweis      : AD-Tokenänderungen werden erst bei einer neuen Anmeldung sicher
               sichtbar. IS_MEMBER liefert bei SQL Logins typischerweise NULL.
Aufruf       : SELECT * FROM monitor.VW_AnalyseAccessCurrent;
Änderungen   : 1.0.0 - Erstfassung Phase 1A.
===============================================================================
*/
CREATE OR ALTER VIEW [monitor].[VW_AnalyseAccessCurrent]
AS
    WITH ActivePolicy AS
    (
        SELECT
            [p].[AnalysisClass],
            [p].[ADGroupName],
            [p].[Priority]
        FROM [monitor].[VW_AnalyseAccessPolicy] AS [p]
        WHERE [p].[IsEnabled] = 1
          AND ([p].[ValidFromUtc] IS NULL OR [p].[ValidFromUtc] <= SYSUTCDATETIME())
          AND ([p].[ValidToUtc]   IS NULL OR [p].[ValidToUtc]   >  SYSUTCDATETIME())
          AND NULLIF(LTRIM(RTRIM([p].[AnalysisClass])), '') IS NOT NULL
          AND NULLIF(LTRIM(RTRIM([p].[ADGroupName])), '') IS NOT NULL
    ),
    PolicyState AS
    (
        SELECT COUNT_BIG(*) AS [ActivePolicyCount]
        FROM [ActivePolicy]
    ),
    LoginTokenMatches AS
    (
        SELECT DISTINCT
            [p].[AnalysisClass],
            [p].[ADGroupName]
        FROM [ActivePolicy] AS [p]
        INNER JOIN [sys].[login_token] AS [lt] WITH (NOLOCK)
            ON UPPER(CONVERT(nvarchar(256), [lt].[name])) COLLATE Latin1_General_100_CI_AS
             = UPPER([p].[ADGroupName]) COLLATE Latin1_General_100_CI_AS
        WHERE [lt].[type] = N'WINDOWS GROUP'
    ),
    IsMemberMatches AS
    (
        SELECT DISTINCT
            [p].[AnalysisClass],
            [p].[ADGroupName]
        FROM [ActivePolicy] AS [p]
        WHERE IS_MEMBER([p].[ADGroupName]) = 1
    ),
    MatchRollup AS
    (
        SELECT
            [m].[AnalysisClass],
            COUNT_BIG(*) AS [MatchCount],
            MAX(CASE WHEN [m].[MatchSource] = 'LOGIN_TOKEN' THEN 1 ELSE 0 END) AS [HasLoginTokenMatch],
            MAX(CASE WHEN [m].[MatchSource] = 'IS_MEMBER'   THEN 1 ELSE 0 END) AS [HasIsMemberMatch]
        FROM
        (
            SELECT [ltm].[AnalysisClass], [ltm].[ADGroupName], CAST('LOGIN_TOKEN' AS varchar(20)) AS [MatchSource]
            FROM [LoginTokenMatches] AS [ltm]
            UNION ALL
            SELECT [imm].[AnalysisClass], [imm].[ADGroupName], CAST('IS_MEMBER' AS varchar(20)) AS [MatchSource]
            FROM [IsMemberMatches] AS [imm]
            WHERE NOT EXISTS
            (
                SELECT 1
                FROM [LoginTokenMatches] AS [ltm]
                WHERE [ltm].[AnalysisClass] = [imm].[AnalysisClass]
                  AND UPPER([ltm].[ADGroupName]) COLLATE Latin1_General_100_CI_AS
                    = UPPER([imm].[ADGroupName]) COLLATE Latin1_General_100_CI_AS
            )
        ) AS [m]
        GROUP BY [m].[AnalysisClass]
    )
    SELECT
        [c].[AnalysisClass],
        [c].[AnalysisLevel],
        [c].[RequiresGroupGate],
        ORIGINAL_LOGIN() AS [OriginalLoginName],
        SUSER_SNAME() AS [EffectiveLoginName],
        CAST(CASE WHEN IS_SRVROLEMEMBER(N'sysadmin') = 1 THEN 1 ELSE 0 END AS bit) AS [IsSysadmin],
        [ps].[ActivePolicyCount],
        CAST
        (
            (
                SELECT COUNT_BIG(*)
                FROM [ActivePolicy] AS [p]
                WHERE [p].[AnalysisClass] IN ([c].[AnalysisClass], '*')
            ) AS bigint
        ) AS [RelevantPolicyCount],
        CAST
        (
            CASE
                WHEN [c].[RequiresGroupGate] = 0 THEN 1
                WHEN IS_SRVROLEMEMBER(N'sysadmin') = 1 THEN 1
                WHEN [ps].[ActivePolicyCount] = 0 THEN 1
                WHEN EXISTS
                (
                    SELECT 1
                    FROM [MatchRollup] AS [mr]
                    WHERE [mr].[AnalysisClass] IN ([c].[AnalysisClass], '*')
                      AND [mr].[MatchCount] > 0
                ) THEN 1
                ELSE 0
            END
            AS bit
        ) AS [IsAllowed],
        CAST
        (
            CASE
                WHEN [c].[RequiresGroupGate] = 0 THEN 'NOT_REQUIRED'
                WHEN IS_SRVROLEMEMBER(N'sysadmin') = 1 THEN 'SYSADMIN'
                WHEN [ps].[ActivePolicyCount] = 0 THEN 'OPEN_POLICY'
                WHEN EXISTS
                (
                    SELECT 1
                    FROM [MatchRollup] AS [mr]
                    WHERE [mr].[AnalysisClass] IN ([c].[AnalysisClass], '*')
                      AND [mr].[HasLoginTokenMatch] = 1
                ) THEN 'LOGIN_TOKEN'
                WHEN EXISTS
                (
                    SELECT 1
                    FROM [MatchRollup] AS [mr]
                    WHERE [mr].[AnalysisClass] IN ([c].[AnalysisClass], '*')
                      AND [mr].[HasIsMemberMatch] = 1
                ) THEN 'IS_MEMBER'
                ELSE 'NO_MATCH'
            END
            AS varchar(20)
        ) AS [AccessReason],
        CAST
        (
            COALESCE
            (
                (
                    SELECT SUM([mr].[MatchCount])
                    FROM [MatchRollup] AS [mr]
                    WHERE [mr].[AnalysisClass] IN ([c].[AnalysisClass], '*')
                ),
                0
            ) AS bigint
        ) AS [MatchedGroupCount]
    FROM [monitor].[VW_AnalyseClassCatalog] AS [c]
    CROSS JOIN [PolicyState] AS [ps];
GO
-- END SOURCE: Code/01_Common/040_VW_AnalyseAccessCurrent.sql

-- BEGIN SOURCE: Code/01_Common/050_USP_CheckAnalyseAccess.sql
/*
===============================================================================
Objekt       : monitor.USP_CheckAnalyseAccess
Version      : 2.0.0
Stand        : 2026-07-15
Typ          : Stored Procedure
Zweck        : Prüft die effektive Analyseklassen- und AD-Gruppenpolicy.
Ausgabe      : RAW, CONSOLE, TABLE oder NONE; optional JSON mit access und policies.
===============================================================================
*/
CREATE OR ALTER PROCEDURE [monitor].[USP_CheckAnalyseAccess]
      @AnalyseKlasse   varchar(64)    = NULL
    , @NurGesperrte    bit            = 0
    , @ResultSetArt    varchar(16)     = 'CONSOLE'
    , @ResultTablesJson               nvarchar(max) = NULL
    , @JsonErzeugen    bit             = 0
    , @Json             nvarchar(max)  = NULL OUTPUT
    , @PrintMeldungen  bit             = 1
    , @Hilfe            bit             = 0
AS
BEGIN
    SET NOCOUNT ON;
    SET LOCK_TIMEOUT 0;
    SET @Json = NULL;

    DECLARE @ResultSetArtNormalisiert varchar(16) = UPPER(LTRIM(RTRIM(COALESCE(@ResultSetArt, ''))));
    DECLARE @TableResultRequested bit = CASE WHEN @ResultSetArtNormalisiert = 'TABLE' THEN 1 ELSE 0 END;
    DECLARE @ConsoleResultRequested bit = CASE WHEN @ResultSetArtNormalisiert = 'CONSOLE' THEN 1 ELSE 0 END;
    DECLARE @TableTarget sysname=NULL;
    IF @TableResultRequested=0 AND NULLIF(LTRIM(RTRIM(COALESCE(@ResultTablesJson,N''))),N'') IS NOT NULL THROW 51011,N'@ResultTablesJson ist ausschließlich mit @ResultSetArt=TABLE zulässig.',1;
    IF @TableResultRequested=1 EXEC [monitor].[InternalPrepareSingleResultTable] @ResultTablesJson=@ResultTablesJson,@ResultName=N'access',@TargetTable=@TableTarget OUTPUT,@ThrowOnError=1;
    IF @TableResultRequested = 1 OR @ConsoleResultRequested = 1 SET @ResultSetArtNormalisiert = 'NONE';
    DECLARE @StatusCode varchar(40) = 'AVAILABLE';
    DECLARE @ErrorNumber int = NULL;
    DECLARE @ErrorMessage nvarchar(2048) = NULL;
    DECLARE @CollectionTimeUtc datetime2(3) = SYSUTCDATETIME();

    IF @Hilfe = 1
    BEGIN
        PRINT N'monitor.USP_CheckAnalyseAccess';
        PRINT N'@AnalyseKlasse=NULL liefert alle Analyseklassen; sonst exakter case-sensitiver Code.';
        PRINT N'@ResultSetArt=RAW, CONSOLE, TABLE oder NONE; Wert wird case-insensitiv verarbeitet.';
        PRINT N'@JsonErzeugen=1 liefert @Json mit meta, access, policies und warnings.';
        RETURN;
    END;

    CREATE TABLE [#CheckAnalyseAccess_Access]
    (
          [AnalysisClass] varchar(64) NOT NULL
        , [AnalysisLevel] varchar(16) NOT NULL
        , [RequiresGroupGate] bit NOT NULL
        , [OriginalLoginName] sysname NULL
        , [EffectiveLoginName] sysname NULL
        , [IsSysadmin] bit NULL
        , [ActivePolicyCount] bigint NULL
        , [RelevantPolicyCount] bigint NULL
        , [IsAllowed] bit NOT NULL
        , [AccessReason] varchar(20) NULL
        , [MatchedGroupCount] bigint NULL
        , [StatusCode] varchar(40) NOT NULL
    );

    CREATE TABLE [#CheckAnalyseAccess_Policies]
    (
          [AnalysisClass] varchar(64) NOT NULL
        , [ADGroupName] nvarchar(256) NOT NULL
        , [Priority] int NOT NULL
        , [ValidFromUtc] datetime2(3) NULL
        , [ValidToUtc] datetime2(3) NULL
        , [MatchesLoginToken] bit NOT NULL
        , [MatchesIsMember] bit NOT NULL
        , [Comment] nvarchar(1000) NULL
    );

    CREATE TABLE [#CheckAnalyseAccess_Warnings]
    (
          [WarningCode] varchar(40) NOT NULL
        , [WarningMessage] nvarchar(2048) NOT NULL
    );

    IF @ResultSetArtNormalisiert NOT IN ('RAW', 'CONSOLE', 'NONE')
    BEGIN
        SET @StatusCode = 'INVALID_PARAMETER';
        SET @ErrorMessage = N'@ResultSetArt muss CONSOLE, RAW, TABLE oder NONE enthalten.';
    END;
    ELSE IF @AnalyseKlasse IS NOT NULL
        AND NOT EXISTS
        (
            SELECT 1
            FROM [monitor].[VW_AnalyseClassCatalog] AS [c]
            WHERE [c].[AnalysisClass] = @AnalyseKlasse
        )
    BEGIN
        SET @StatusCode = 'INVALID_PARAMETER';
        SET @ErrorMessage = N'Die Analyseklasse ist nicht in monitor.VW_AnalyseClassCatalog definiert.';
    END;

    IF @StatusCode = 'AVAILABLE'
    BEGIN TRY
        INSERT [#CheckAnalyseAccess_Access]
        (
              [AnalysisClass], [AnalysisLevel], [RequiresGroupGate]
            , [OriginalLoginName], [EffectiveLoginName], [IsSysadmin]
            , [ActivePolicyCount], [RelevantPolicyCount], [IsAllowed]
            , [AccessReason], [MatchedGroupCount], [StatusCode]
        )
        SELECT
              [a].[AnalysisClass], [a].[AnalysisLevel], [a].[RequiresGroupGate]
            , [a].[OriginalLoginName], [a].[EffectiveLoginName], [a].[IsSysadmin]
            , [a].[ActivePolicyCount], [a].[RelevantPolicyCount], [a].[IsAllowed]
            , [a].[AccessReason], [a].[MatchedGroupCount]
            , CASE WHEN [a].[IsAllowed] = 1 THEN 'AVAILABLE' ELSE 'DENIED_GROUP' END
        FROM [monitor].[VW_AnalyseAccessCurrent] AS [a]
        WHERE (@AnalyseKlasse IS NULL OR [a].[AnalysisClass] = @AnalyseKlasse)
          AND (@NurGesperrte = 0 OR [a].[IsAllowed] = 0);

        ;WITH [ActivePolicy] AS
        (
            SELECT
                  [p].[AnalysisClass], [p].[ADGroupName], [p].[Priority]
                , [p].[ValidFromUtc], [p].[ValidToUtc], [p].[Comment]
            FROM [monitor].[VW_AnalyseAccessPolicy] AS [p]
            WHERE [p].[IsEnabled] = 1
              AND ([p].[ValidFromUtc] IS NULL OR [p].[ValidFromUtc] <= SYSUTCDATETIME())
              AND ([p].[ValidToUtc] IS NULL OR [p].[ValidToUtc] > SYSUTCDATETIME())
              AND (@AnalyseKlasse IS NULL OR [p].[AnalysisClass] IN (@AnalyseKlasse, '*'))
        )
        INSERT [#CheckAnalyseAccess_Policies]
        (
              [AnalysisClass], [ADGroupName], [Priority], [ValidFromUtc]
            , [ValidToUtc], [MatchesLoginToken], [MatchesIsMember], [Comment]
        )
        SELECT
              [p].[AnalysisClass], [p].[ADGroupName], [p].[Priority]
            , [p].[ValidFromUtc], [p].[ValidToUtc]
            , CONVERT(bit, CASE WHEN EXISTS
              (
                  SELECT 1
                  FROM [sys].[login_token] AS [lt] WITH (NOLOCK)
                  WHERE [lt].[type] = N'WINDOWS GROUP'
                    AND UPPER(CONVERT(nvarchar(256), [lt].[name])) COLLATE Latin1_General_100_CI_AS
                      = UPPER([p].[ADGroupName]) COLLATE Latin1_General_100_CI_AS
              ) THEN 1 ELSE 0 END)
            , CONVERT(bit, CASE WHEN IS_MEMBER([p].[ADGroupName]) = 1 THEN 1 ELSE 0 END)
            , [p].[Comment]
        FROM [ActivePolicy] AS [p];

        IF EXISTS (SELECT 1 FROM [#CheckAnalyseAccess_Access] WHERE [IsAllowed] = 0)
        BEGIN
            INSERT [#CheckAnalyseAccess_Warnings] VALUES ('DENIED_GROUP', N'Mindestens eine Analyseklasse ist durch die aktuelle Gruppenpolicy gesperrt.');
            SET @StatusCode = 'AVAILABLE_LIMITED';
        END;
    END TRY
    BEGIN CATCH
        SET @StatusCode = 'ERROR_HANDLED';
        SET @ErrorNumber = ERROR_NUMBER();
        SET @ErrorMessage = ERROR_MESSAGE();
        INSERT [#CheckAnalyseAccess_Warnings] VALUES (@StatusCode, @ErrorMessage);
    END CATCH;

    IF @PrintMeldungen = 1 AND @ErrorMessage IS NOT NULL
    BEGIN
        DECLARE @PrintMessage nvarchar(2048) = FORMATMESSAGE(N'%s: %s', @StatusCode, @ErrorMessage);
        RAISERROR(N'%s', 10, 1, @PrintMessage) WITH NOWAIT;
    END;

    IF @ResultSetArtNormalisiert <> 'NONE'
    BEGIN
        SELECT
              CAST('2.0' AS varchar(16)) AS [ContractVersion]
            , @CollectionTimeUtc AS [CollectionTimeUtc]
            , N'monitor.USP_CheckAnalyseAccess' AS [ModuleName]
            , @StatusCode AS [StatusCode]
            , CONVERT(bit, CASE WHEN @StatusCode = 'AVAILABLE' THEN 0 ELSE 1 END) AS [IsPartial]
            , @ErrorNumber AS [ErrorNumber]
            , @ErrorMessage AS [ErrorMessage];

        IF @ResultSetArtNormalisiert = 'RAW'
        BEGIN
            SELECT * FROM [#CheckAnalyseAccess_Access] ORDER BY [RequiresGroupGate], [AnalysisLevel], [AnalysisClass];
            SELECT * FROM [#CheckAnalyseAccess_Policies] ORDER BY [Priority], [AnalysisClass], [ADGroupName];
            SELECT * FROM [#CheckAnalyseAccess_Warnings] ORDER BY [WarningCode], [WarningMessage];
        END;
        ELSE
        BEGIN
            SELECT
                  N'Analysezugriff' AS [Ergebnis]
                , [AnalysisClass] AS [Analyseklasse]
                , [AnalysisLevel] AS [Stufe]
                , [IsAllowed] AS [erlaubt]
                , [AccessReason] AS [Begründung]
                , [MatchedGroupCount] AS [passende Gruppen]
                , [StatusCode] AS [Status]
            FROM [#CheckAnalyseAccess_Access]
            ORDER BY [RequiresGroupGate], [AnalysisLevel], [AnalysisClass];

            SELECT
                  N'Aktive Zugriffspolicy' AS [Ergebnis]
                , [AnalysisClass] AS [Analyseklasse]
                , [ADGroupName] AS [AD-Gruppe]
                , [Priority] AS [Priorität]
                , [MatchesLoginToken] AS [im Login-Token]
                , [MatchesIsMember] AS [IS_MEMBER]
                , [Comment] AS [Kommentar]
            FROM [#CheckAnalyseAccess_Policies]
            ORDER BY [Priority], [AnalysisClass], [ADGroupName];

            SELECT N'Warnung' AS [Ergebnis], [WarningCode] AS [Code], [WarningMessage] AS [Meldung]
            FROM [#CheckAnalyseAccess_Warnings]
            ORDER BY [WarningCode], [WarningMessage];
        END;
    END;

    IF @JsonErzeugen = 1
    BEGIN
        DECLARE @MetaJson nvarchar(max) =
        (
            SELECT
                  N'CheckAnalyseAccess' AS [resultName]
                , 1 AS [schemaVersion]
                , @CollectionTimeUtc AS [generatedAtUtc]
                , @StatusCode AS [statusCode]
                , @ErrorNumber AS [errorNumber]
                , @ErrorMessage AS [errorMessage]
            FOR JSON PATH, WITHOUT_ARRAY_WRAPPER, INCLUDE_NULL_VALUES
        );
        DECLARE @AccessJson nvarchar(max) = (SELECT * FROM [#CheckAnalyseAccess_Access] ORDER BY [RequiresGroupGate], [AnalysisLevel], [AnalysisClass] FOR JSON PATH, INCLUDE_NULL_VALUES);
        DECLARE @PoliciesJson nvarchar(max) = (SELECT * FROM [#CheckAnalyseAccess_Policies] ORDER BY [Priority], [AnalysisClass], [ADGroupName] FOR JSON PATH, INCLUDE_NULL_VALUES);
        DECLARE @WarningsJson nvarchar(max) = (SELECT * FROM [#CheckAnalyseAccess_Warnings] ORDER BY [WarningCode], [WarningMessage] FOR JSON PATH, INCLUDE_NULL_VALUES);
        SET @Json = CONCAT(N'{"meta":', COALESCE(@MetaJson, N'{}'), N',"access":', COALESCE(@AccessJson, N'[]'), N',"policies":', COALESCE(@PoliciesJson, N'[]'), N',"warnings":', COALESCE(@WarningsJson, N'[]'), N'}');
    END;
    IF @ConsoleResultRequested = 1
    BEGIN
        EXEC [monitor].[InternalEmitConsoleResult]
              @SourceTable=N'#CheckAnalyseAccess_Access'
            , @ResultLabel=N'CheckAnalyseAccess'
            , @EmptyMessage=N'Keine fachlichen Ergebnisse';
    END;
    IF @TableResultRequested = 1
    BEGIN
        EXEC [monitor].[InternalWriteResultTable]
              @SourceTable = N'#CheckAnalyseAccess_Access'
            , @TargetTable=@TableTarget
            , @ThrowOnError = 1;
    END;
END;
GO
-- END SOURCE: Code/01_Common/050_USP_CheckAnalyseAccess.sql

-- BEGIN SOURCE: Code/01_Common/060_VW_FrameworkFeatureCatalog.sql
/*
===============================================================================
Objekt       : monitor.VW_FrameworkFeatureCatalog
Version      : 1.7.0
Stand        : 2026-07-14
Typ          : View
Zweck        : Stellt den deklarativen Katalog prüfbarer Monitoring-
               Datenquellen und Framework-Funktionsklassen für SQL Server 2019
               und neuer bereit.
Parameter    : Keine.
Resultset    : Feature-, Versions-, Berechtigungs-, Kosten- und Probe-Metadaten.
Berechtigung : SELECT auf der View. Die genannten Berechtigungen sind Hinweise;
               das Framework führt niemals GRANT, DENY oder REVOKE aus.
Sicherheit   : ProbeSqlTemplate enthält ausschließlich statische Framework-
               Definitionen. Der Datenbank-Platzhalter wird in der Prüf-USP mit QUOTENAME ersetzt.
Eigenlast    : Die View selbst ist konstant. Die Probe-Statements verwenden TOP(0)
               beziehungsweise reine Statusabfragen und führen keine Deep-Scans aus.
Aufruf       : SELECT * FROM monitor.VW_FrameworkFeatureCatalog;
Änderungen   : 1.7.0 - Maschinenlesbare PermissionCheckType-/PermissionName-Spalten ergänzt; freie Hinweistexte werden nur noch per Probe geprüft.
               1.6.0 - Phase-6-Quellen für Agent, Resource Governor, HA/DR, Backup, Replication, CDC und Change Tracking ergänzt.
               1.5.0 - Extended-Events-Katalog, Targetruntime, Filezugriff, Deadlocks und Blocked-Process-Reports differenziert.
               1.4.0 - Query-Store-Status, Runtime, Waits, Pläne, Forced Plans und SQL-2022-Hints getrennt katalogisiert.
               1.3.0 - Plan-Cache-, Planattribut-, Showplan-, Last-Actual- und Live-Plan-Capabilities präzisiert.
               1.2.0 - Index Operational Stats und In-Memory-OLTP-Indexnutzung ergänzt.
               1.1.0 - Phase-2-Objekt-, Statistik-, Partitions- und Columnstore-Quellen ergänzt.
               1.0.0 - Erstfassung Phase 1A.
===============================================================================
*/
CREATE OR ALTER VIEW [monitor].[VW_FrameworkFeatureCatalog]
AS
    SELECT
        [f].[FeatureOrdinal],
        [f].[FeatureCode],
        [f].[FeatureName],
        [f].[ScopeType],
        [f].[AnalysisClass],
        [f].[AnalysisLevel],
        [f].[IsResourceIntensive],
        [f].[MinimumMajorVersion],
        [f].[PermissionScopeBeforeSql2022],
        [f].[PermissionScopeFromSql2022],
        [f].[PermissionBeforeSql2022],
        [f].[PermissionFromSql2022],
        CAST(CASE WHEN [f].[PermissionBeforeSql2022] IN
          (N'VIEW SERVER STATE',N'VIEW SERVER PERFORMANCE STATE',N'VIEW DATABASE STATE',N'VIEW DATABASE PERFORMANCE STATE',N'VIEW ANY DEFINITION',N'VIEW ANY DATABASE',N'VIEW DEFINITION')
          THEN 'HAS_PERMS_BY_NAME' ELSE 'PROBE_ONLY' END AS varchar(24)) AS [PermissionCheckTypeBeforeSql2022],
        CAST(CASE WHEN [f].[PermissionBeforeSql2022] IN
          (N'VIEW SERVER STATE',N'VIEW SERVER PERFORMANCE STATE',N'VIEW DATABASE STATE',N'VIEW DATABASE PERFORMANCE STATE',N'VIEW ANY DEFINITION',N'VIEW ANY DATABASE',N'VIEW DEFINITION')
          THEN [f].[PermissionBeforeSql2022] END AS sysname) AS [PermissionNameBeforeSql2022],
        [f].[PermissionBeforeSql2022] AS [PermissionDisplayTextBeforeSql2022],
        CAST(CASE WHEN [f].[PermissionFromSql2022] IN
          (N'VIEW SERVER STATE',N'VIEW SERVER PERFORMANCE STATE',N'VIEW DATABASE STATE',N'VIEW DATABASE PERFORMANCE STATE',N'VIEW ANY DEFINITION',N'VIEW ANY DATABASE',N'VIEW DEFINITION')
          THEN 'HAS_PERMS_BY_NAME' ELSE 'PROBE_ONLY' END AS varchar(24)) AS [PermissionCheckTypeFromSql2022],
        CAST(CASE WHEN [f].[PermissionFromSql2022] IN
          (N'VIEW SERVER STATE',N'VIEW SERVER PERFORMANCE STATE',N'VIEW DATABASE STATE',N'VIEW DATABASE PERFORMANCE STATE',N'VIEW ANY DEFINITION',N'VIEW ANY DATABASE',N'VIEW DEFINITION')
          THEN [f].[PermissionFromSql2022] END AS sysname) AS [PermissionNameFromSql2022],
        [f].[PermissionFromSql2022] AS [PermissionDisplayTextFromSql2022],
        [f].[ExpectedWithoutPermission],
        [f].[ProbeSqlTemplate],
        [f].[EnablementSqlTemplate],
        [f].[Description]
    FROM
