/* Wait-Type-Katalog: kuratierter Seed-Teil 04 von 04. */
DECLARE @Seed TABLE
([WaitType] nvarchar(120),[WaitGroup] nvarchar(64),[Severity] tinyint,[IsGenerallyBenign] bit,[Meaning] nvarchar(1000),
 [TypicalOccurrence] nvarchar(1200),[HighWaitImpact] nvarchar(1200),[RecommendedChecks] nvarchar(1500),
 [DescriptionSource] varchar(40),[DescriptionQuality] varchar(40));
INSERT @Seed VALUES
(N'RESOURCE_SEMAPHORE_SMALL_QUERY',N'MEMORY',2,0,N'Eine kleine Abfrage erhält ihren Speicher wegen konkurrierender Abfragen nicht sofort; nach wenigen Sekunden wechselt die Anforderung in den Hauptpool für Abfragespeicher.',N'Speicherzuteilung, Memory Grants oder interne Memory-Manager.',N'Hohe Werte verzögern Start oder Ausführung von Abfragen.',N'Pending Grants, Grantgrößen, Cardinality, Spills und max server memory prüfen.',N'FRAMEWORK_CURATED',N'FRAMEWORK_CURATED'),
(N'SECURITY_MUTEX',N'OTHER_OR_NEW',2,0,N'Occurs when there is a wait for mutexes that control access to the global list of Extensible Key Management (EKM) cryptographic providers and the session-scoped list of EKM sessions.',N'Spezialisierter, interner oder neuer SQL-Server-Wait-Type.',N'Hohe Werte sind nur im Delta- und Workload-Kontext bewertbar.',N'Aktive Tasks, Ressource, Version, Microsoft-Referenz und Versionskontext prüfen.',N'FRAMEWORK_CURATED',N'FRAMEWORK_CURATED'),
(N'SEC_DROP_TEMP_KEY',N'OTHER_OR_NEW',2,0,N'Occurs after a failed attempt to drop a temporary security key before a retry attempt.',N'Spezialisierter, interner oder neuer SQL-Server-Wait-Type.',N'Hohe Werte sind nur im Delta- und Workload-Kontext bewertbar.',N'Aktive Tasks, Ressource, Version, Microsoft-Referenz und Versionskontext prüfen.',N'FRAMEWORK_CURATED',N'FRAMEWORK_CURATED'),
(N'SEQUENTIAL_GUID',N'OTHER_OR_NEW',2,0,N'Occurs while a new sequential GUID is being obtained.',N'Spezialisierter, interner oder neuer SQL-Server-Wait-Type.',N'Hohe Werte sind nur im Delta- und Workload-Kontext bewertbar.',N'Aktive Tasks, Ressource, Version, Microsoft-Referenz und Versionskontext prüfen.',N'FRAMEWORK_CURATED',N'FRAMEWORK_CURATED'),
(N'SERVER_IDLE_CHECK',N'BENIGN_BACKGROUND',0,1,N'Occurs during synchronization of SQL Server instance idle status when a resource monitor is attempting to declare a SQL Server instance as idle or trying to wake up.',N'Normaler Idle-, Timer-, Queue- oder Hintergrundzustand.',N'Hohe kumulative Werte sind in der Regel erwartbar und kein Engpassbeweis.',N'Standardmäßig aus Top-Ranking ausblenden; nur bei passender Funktionsstörung untersuchen.',N'FRAMEWORK_CURATED',N'FRAMEWORK_CURATED'),
(N'SHUTDOWN',N'OTHER_OR_NEW',2,0,N'Dieser Wartetyp weist darauf hin, dass ein SHUTDOWN-Befehl durch die SPID ausgegeben wurde und dass die SPID darauf wartet, dass aktive Abfragen abgeschlossen werden. (Occurs while a shutdown statement waits for active connections to exit.)',N'Spezialisierter, interner oder neuer SQL-Server-Wait-Type.',N'Hohe Werte sind nur im Delta- und Workload-Kontext bewertbar.',N'Aktive Tasks, Ressource, Version, Microsoft-Referenz und Versionskontext prüfen.',N'FRAMEWORK_CURATED',N'FRAMEWORK_CURATED'),
(N'SLEEP_BPOOL_FLUSH',N'BENIGN_BACKGROUND',0,1,N'Occurs when a checkpoint is throttling the issuance of new I/Os in order to avoid flooding the disk subsystem.',N'Normaler Idle-, Timer-, Queue- oder Hintergrundzustand.',N'Hohe kumulative Werte sind in der Regel erwartbar und kein Engpassbeweis.',N'Standardmäßig aus Top-Ranking ausblenden; nur bei passender Funktionsstörung untersuchen.',N'FRAMEWORK_CURATED',N'FRAMEWORK_CURATED'),
(N'SLEEP_DBSTARTUP',N'BENIGN_BACKGROUND',0,1,N'Occurs during database startup while waiting for all databases to recover.',N'Normaler Idle-, Timer-, Queue- oder Hintergrundzustand.',N'Hohe kumulative Werte sind in der Regel erwartbar und kein Engpassbeweis.',N'Standardmäßig aus Top-Ranking ausblenden; nur bei passender Funktionsstörung untersuchen.',N'FRAMEWORK_CURATED',N'FRAMEWORK_CURATED'),
(N'SLEEP_DCOMSTARTUP',N'BENIGN_BACKGROUND',0,1,N'Occurs once at most during SQL Server instance startup while waiting for DCOM initialization to complete.',N'Normaler Idle-, Timer-, Queue- oder Hintergrundzustand.',N'Hohe kumulative Werte sind in der Regel erwartbar und kein Engpassbeweis.',N'Standardmäßig aus Top-Ranking ausblenden; nur bei passender Funktionsstörung untersuchen.',N'FRAMEWORK_CURATED',N'FRAMEWORK_CURATED'),
(N'SLEEP_MSDBSTARTUP',N'BENIGN_BACKGROUND',0,1,N'Occurs when SQL Trace waits for the msdb database to complete startup.',N'Normaler Idle-, Timer-, Queue- oder Hintergrundzustand.',N'Hohe kumulative Werte sind in der Regel erwartbar und kein Engpassbeweis.',N'Standardmäßig aus Top-Ranking ausblenden; nur bei passender Funktionsstörung untersuchen.',N'FRAMEWORK_CURATED',N'FRAMEWORK_CURATED'),
(N'SLEEP_SYSTEMTASK',N'BENIGN_BACKGROUND',0,1,N'Occurs during the start of a background task while waiting for tempdb to complete startup.',N'Normaler Idle-, Timer-, Queue- oder Hintergrundzustand.',N'Hohe kumulative Werte sind in der Regel erwartbar und kein Engpassbeweis.',N'Standardmäßig aus Top-Ranking ausblenden; nur bei passender Funktionsstörung untersuchen.',N'FRAMEWORK_CURATED',N'FRAMEWORK_CURATED'),
