-- BEGIN SOURCE: Code/01_Common/075_TVF_WaitTypeInfo.sql
/* Kataloggestützte Wait-Taxonomie mit exaktem Lookup und regelbasiertem Fallback anhand der Wait Group. */
CREATE OR ALTER FUNCTION [monitor].[TVF_WaitTypeInfo](@WaitType nvarchar(120))
RETURNS TABLE
AS
RETURN
(
    SELECT
          @WaitType AS [WaitType]
        , COALESCE([c].[WaitGroup], [f].[WaitGroup]) AS [WaitGroup]
        , COALESCE([c].[Severity], [f].[Severity]) AS [Severity]
        , COALESCE([c].[IsGenerallyBenign], [f].[IsGenerallyBenign]) AS [IsGenerallyBenign]
        , COALESCE([c].[Meaning], [f].[Meaning]) AS [Meaning]
        , COALESCE([c].[TypicalOccurrence], [f].[TypicalOccurrence]) AS [TypicalOccurrence]
        , COALESCE([c].[HighWaitImpact], [f].[HighWaitImpact]) AS [HighWaitImpact]
        , COALESCE([c].[RecommendedChecks], [f].[RecommendedChecks]) AS [RecommendedChecks]
        , COALESCE([c].[DefaultAssessment], CASE WHEN [f].[IsGenerallyBenign]=1 THEN 'EXPECTED_OR_IDLE' ELSE 'CONTEXT_DEPENDENT' END) AS [DefaultAssessment]
        , COALESCE([c].[AssessmentBasis], N'Fallback anhand der Wait Group: Erst aktiven Task, Ressource, Delta und Workloadwirkung bestätigen.') AS [AssessmentBasis]
        , COALESCE([c].[CommonCauses], [f].[TypicalOccurrence]) AS [CommonCauses]
        , COALESCE([c].[PerformanceImpact], [f].[HighWaitImpact]) AS [PerformanceImpact]
        , COALESCE([c].[Mitigation], N'Nicht den Wait Type unterdrücken; die nachgewiesene Ressourcen- oder Komponentenursache beheben.') AS [Mitigation]
        , COALESCE([c].[CounterEvidence], N'Kein aktiver Task und kein reproduzierbares Lastdelta sprechen gegen einen aktuellen Engpass.') AS [CounterEvidence]
        , [c].[RelatedWaitTypes] AS [RelatedWaitTypes]
        , COALESCE([c].[MeasurementGuidance], N'Aktive Tasks und ein belastungsbezogenes Delta gemeinsam bewerten.') AS [MeasurementGuidance]
        , COALESCE([c].[AnalysisConfidence], 'FAMILY_INFERENCE') AS [AnalysisConfidence]
        , COALESCE([c].[HelpUrl], CASE WHEN @WaitType IS NOT NULL THEN N'https://www.sqlskills.com/help/waits/' + @WaitType END) AS [HelpUrl]
        , COALESCE([c].[DescriptionSource], 'FAMILY_FALLBACK') AS [DescriptionSource]
        , COALESCE([c].[DescriptionQuality], 'GENERIC') AS [DescriptionQuality]
        , [c].[SourceReference] AS [SourceReference]
        , CONVERT(int,(SELECT COUNT_BIG(*) FROM [monitor].[WaitTypeCatalogSource] AS [src] WITH (NOLOCK) WHERE [src].[WaitType]=[c].[WaitType])) AS [SourceCount]
        , CONVERT
          (
              nvarchar(400)
            , CASE
                  WHEN [c].[WaitType] IS NOT NULL THEN N'Exakter Katalogtreffer; DescriptionQuality beachten.'
                  ELSE N'Fallback anhand der Wait Group; Detailseite und Workload-Kontext prüfen.'
              END
          ) AS [InterpretationScope]
        , CONVERT(varchar(20), CASE WHEN [c].[WaitType] IS NOT NULL THEN 'EXACT' ELSE 'FAMILY_FALLBACK' END) AS [CatalogMatchType]
    FROM (VALUES (1)) AS [v]([n])
    OUTER APPLY
    (
        SELECT TOP (1) *
        FROM [monitor].[WaitTypeCatalog] WITH (NOLOCK)
        WHERE [WaitType] = @WaitType
    ) AS [c]
    CROSS APPLY
    (
        SELECT
              CONVERT
              (
                  nvarchar(64)
                , CASE
                      WHEN @WaitType IS NULL THEN N'KEIN_WAIT'
                      WHEN @WaitType LIKE N'LCK[_]%' THEN N'LOCKING'
                      WHEN @WaitType LIKE N'PAGEIOLATCH[_]%' OR @WaitType LIKE N'IO[_]%' OR @WaitType LIKE N'%IO_COMPLETION%' THEN N'STORAGE_DATA_IO'
                      WHEN @WaitType LIKE N'WRITELOG%' OR @WaitType LIKE N'LOGBUFFER%' OR @WaitType LIKE N'LOG_RATE_GOVERNOR%' THEN N'TRANSACTION_LOG'
                      WHEN @WaitType LIKE N'PAGELATCH[_]%' THEN N'IN_MEMORY_LATCH'
                      WHEN @WaitType LIKE N'LATCH[_]%' OR @WaitType = N'CMEMTHREAD' THEN N'INTERNAL_SYNCHRONIZATION'
                      WHEN @WaitType IN (N'SOS_SCHEDULER_YIELD', N'THREADPOOL') OR @WaitType LIKE N'SOS_WORK_DISPATCHER%' THEN N'CPU_SCHEDULER'
                      WHEN @WaitType LIKE N'CX%' OR @WaitType = N'EXCHANGE' THEN N'PARALLELISM'
                      WHEN @WaitType LIKE N'RESOURCE_SEMAPHORE%' OR @WaitType LIKE N'MEMORY_ALLOCATION%' THEN N'MEMORY'
                      WHEN @WaitType LIKE N'ASYNC_NETWORK_IO%' OR @WaitType LIKE N'NET[_]%' OR @WaitType = N'NETWORK_IO' THEN N'NETWORK_CLIENT'
                      WHEN @WaitType LIKE N'HADR[_]%' OR @WaitType LIKE N'DBMIRROR[_]%' OR @WaitType LIKE N'PWAIT_HADR%' THEN N'HA_REPLICATION'
                      WHEN @WaitType LIKE N'BACKUP%' OR @WaitType LIKE N'RESTORE%' THEN N'BACKUP_RESTORE'
                      WHEN @WaitType LIKE N'QDS[_]%' OR @WaitType LIKE N'QUERY_STORE%' THEN N'QUERY_STORE'
                      WHEN @WaitType LIKE N'XTP[_]%' OR @WaitType LIKE N'WAIT_XTP%' THEN N'IN_MEMORY_OLTP'
                      WHEN @WaitType LIKE N'FT[_]%' THEN N'FULLTEXT'
                      WHEN @WaitType LIKE N'CLR[_]%' THEN N'CLR'
                      WHEN @WaitType LIKE N'PREEMPTIVE[_]%' OR @WaitType IN (N'OLEDB', N'REMOTE_QUERY', N'EXTERNAL_SCRIPT_NETWORK_IO') THEN N'EXTERNAL_OR_PREEMPTIVE'
                      WHEN @WaitType LIKE N'XE[_]%' OR @WaitType LIKE N'SQLTRACE[_]%' THEN N'TRACING_XEVENTS'
                      WHEN @WaitType LIKE N'BROKER[_]%' THEN N'SERVICE_BROKER'
                      WHEN @WaitType LIKE N'REPL[_]%' THEN N'REPLICATION'
                      WHEN @WaitType LIKE N'SLEEP%'
                        OR @WaitType IN
                           (
                               N'HADR_WORK_QUEUE', N'HADR_TIMER_TASK', N'QDS_PERSIST_TASK_MAIN_LOOP_SLEEP'
                             , N'QDS_CLEANUP_STALE_QUERIES_TASK_MAIN_LOOP_SLEEP', N'LAZYWRITER_SLEEP'
                             , N'DIRTY_PAGE_POLL', N'REQUEST_FOR_DEADLOCK_SEARCH', N'SERVER_IDLE_CHECK'
                             , N'WAITFOR', N'ONDEMAND_TASK_QUEUE', N'RESOURCE_QUEUE'
                             , N'DISPATCHER_QUEUE_SEMAPHORE', N'LOGMGR_QUEUE', N'SP_SERVER_DIAGNOSTICS_SLEEP'
                             , N'XE_DISPATCHER_WAIT', N'XE_DISPATCHER_JOIN', N'XE_TIMER_EVENT'
                           ) THEN N'BENIGN_BACKGROUND'
                      WHEN @WaitType LIKE N'%STATISTICS%' THEN N'STATISTICS'
                      ELSE N'OTHER_OR_NEW'
                  END
              ) AS [WaitGroup]
            , CONVERT
              (
                  tinyint
                , CASE
                      WHEN @WaitType = N'THREADPOOL' THEN 5
                      WHEN @WaitType LIKE N'LCK[_]%'
                        OR @WaitType LIKE N'RESOURCE_SEMAPHORE%'
                        OR @WaitType = N'SOS_SCHEDULER_YIELD' THEN 4
                      WHEN @WaitType LIKE N'SLEEP%' THEN 0
                      ELSE 2
                  END
              ) AS [Severity]
            , CONVERT
              (
                  bit
                , CASE
                      WHEN @WaitType LIKE N'SLEEP%'
                        OR @WaitType IN
                           (
                               N'HADR_WORK_QUEUE', N'HADR_TIMER_TASK', N'QDS_PERSIST_TASK_MAIN_LOOP_SLEEP'
                             , N'QDS_CLEANUP_STALE_QUERIES_TASK_MAIN_LOOP_SLEEP', N'LAZYWRITER_SLEEP'
                             , N'DIRTY_PAGE_POLL', N'REQUEST_FOR_DEADLOCK_SEARCH', N'SERVER_IDLE_CHECK'
                             , N'WAITFOR', N'ONDEMAND_TASK_QUEUE', N'RESOURCE_QUEUE'
                             , N'DISPATCHER_QUEUE_SEMAPHORE', N'LOGMGR_QUEUE', N'SP_SERVER_DIAGNOSTICS_SLEEP'
                             , N'XE_DISPATCHER_WAIT', N'XE_DISPATCHER_JOIN', N'XE_TIMER_EVENT'
                           ) THEN 1
                      ELSE 0
                  END
              ) AS [IsGenerallyBenign]
            , CONVERT
              (
                  nvarchar(1000)
                , CASE
                      WHEN @WaitType IS NULL THEN N'Der Request wartet aktuell nicht.'
                      WHEN @WaitType LIKE N'LCK[_]%' THEN N'Warten auf einen inkompatiblen Lock.'
                      WHEN @WaitType LIKE N'PAGEIOLATCH[_]%' THEN N'Warten auf das Lesen einer Datenseite vom Storage.'
                      WHEN @WaitType LIKE N'PAGELATCH[_]%' THEN N'In-Memory-Seitenlatch; kein physischer I/O-Wait.'
                      WHEN @WaitType LIKE N'WRITELOG%' THEN N'Warten auf dauerhaftes Schreiben ins Transaktionslog.'
                      ELSE N'Spezialisierter oder neuer Wait Type.'
                  END
              ) AS [Meaning]
            , CONVERT(nvarchar(1200), N'Auftreten anhand der zugeordneten Komponente, aktueller Tasks und Delta-Messung bewerten.') AS [TypicalOccurrence]
            , CONVERT
              (
                  nvarchar(1200)
                , CASE
                      WHEN @WaitType LIKE N'SLEEP%' THEN N'Hohe kumulative Werte sind meist erwartbar.'
                      ELSE N'Hohe Delta-Werte können Latenz oder Durchsatz beeinträchtigen.'
                  END
              ) AS [HighWaitImpact]
            , CONVERT(nvarchar(1500), N'Delta, aktive Requests, resource_description, Ausführungsplan und SQLskills-Detailseite prüfen.') AS [RecommendedChecks]
    ) AS [f]
);
GO
-- END SOURCE: Code/01_Common/075_TVF_WaitTypeInfo.sql

-- BEGIN SOURCE: Code/01_Common/075a_TVF_WaitTypeSources.sql
/* Quellen und Aussagezweck eines Wait Types. Unbekannte Waits erhalten einen
   transparenten generischen Quellenfallback, aber keine erfundene Detailquelle. */
CREATE OR ALTER FUNCTION [monitor].[TVF_WaitTypeSources]
(
 @WaitType nvarchar(120)
)
RETURNS TABLE
AS
RETURN
(
    SELECT
          [s].[WaitType]
        , [s].[SourceOrdinal]
        , [s].[SourceType]
        , [s].[Publisher]
        , [s].[SourceTitle]
        , [s].[SourceUrl]
        , [s].[SupportsFields]
        , [s].[EvidenceLevel]
        , [s].[SourceNotes]
        , CONVERT(varchar(20),'EXACT') AS [CatalogMatchType]
        , [s].[LastVerifiedUtc]
    FROM [monitor].[WaitTypeCatalogSource] AS [s] WITH (NOLOCK)
    WHERE [s].[WaitType]=@WaitType

    UNION ALL

    SELECT
          @WaitType
        , [f].[SourceOrdinal]
        , [f].[SourceType]
        , [f].[Publisher]
        , [f].[SourceTitle]
        , [f].[SourceUrl]
        , [f].[SupportsFields]
        , [f].[EvidenceLevel]
        , [f].[SourceNotes]
        , CONVERT(varchar(20),'GENERIC_FALLBACK')
        , CONVERT(datetime2(0),NULL)
    FROM
    (
        VALUES
          (CONVERT(tinyint,1),'DEFINITION',N'Microsoft',
           N'sys.dm_os_wait_stats – Types of Waits',
           N'https://learn.microsoft.com/en-us/sql/relational-databases/system-dynamic-management-objects/sys-dm-os-wait-stats-transact-sql?view=sql-server-ver17',
           N'WaitType, Meaning, Versionshinweise','PRIMARY_VENDOR',
           N'Generische Definitionsquelle; ein fehlender exakter Katalogeintrag bleibt fachlich zu recherchieren.'),
          (CONVERT(tinyint,2),'MEASUREMENT',N'Microsoft',
           N'Troubleshoot slow-running queries – diagnose waits or bottlenecks',
           N'https://learn.microsoft.com/en-us/troubleshoot/sql/database-engine/performance/troubleshoot-slow-running-queries',
           N'AssessmentBasis, MeasurementGuidance, CounterEvidence','PRIMARY_VENDOR',
           N'Allgemeine Messmethodik, keine wait-spezifische Ursachenbehauptung.'),
          (CONVERT(tinyint,3),'INTERPRETATION',N'SQLskills',
           CONCAT(N'SQL Server Wait Types Library: ',@WaitType),
           CONCAT(N'https://www.sqlskills.com/help/waits/',@WaitType),
           N'TypicalOccurrence, AssessmentBasis, RelatedWaitTypes','SPECIALIST_REFERENCE',
           N'Externe Spezialistenreferenz; Inhalt wird nicht in das Repository kopiert.')
    ) AS [f]
    (
      [SourceOrdinal],[SourceType],[Publisher],[SourceTitle],[SourceUrl],
      [SupportsFields],[EvidenceLevel],[SourceNotes]
    )
    WHERE @WaitType IS NOT NULL
      AND NOT EXISTS
          (
            SELECT 1
            FROM [monitor].[WaitTypeCatalogSource] AS [x] WITH (NOLOCK)
            WHERE [x].[WaitType]=@WaitType
          )
);
GO
-- END SOURCE: Code/01_Common/075a_TVF_WaitTypeSources.sql

-- BEGIN SOURCE: Code/01_Common/076_TVF_QueryStoreWaitCategoryInfo.sql
CREATE OR ALTER FUNCTION [monitor].[TVF_QueryStoreWaitCategoryInfo](@WaitCategoryDesc nvarchar(128))
RETURNS TABLE
AS
RETURN
(
    SELECT
          CONVERT(nvarchar(64), UPPER(REPLACE(COALESCE(@WaitCategoryDesc, N'Unknown'), N' ', N'_'))) AS [WaitGroup]
        , CONVERT
          (
              nvarchar(1000)
            , CASE @WaitCategoryDesc
                  WHEN N'CPU' THEN N'CPU-Verbrauch oder Schedulerzeit während der Queryausführung.'
                  WHEN N'Worker Thread' THEN N'Warten auf verfügbare Workerthreads.'
                  WHEN N'Lock' THEN N'Warten auf inkompatible Locks.'
                  WHEN N'Latch' THEN N'Interne Synchronisationslatches.'
                  WHEN N'Buffer Latch' THEN N'Latches auf Seiten im Buffer Pool, häufig Hot-Page-Contention.'
                  WHEN N'Buffer IO' THEN N'Warten auf Daten-I/O für Seiten.'
                  WHEN N'Tran Log IO' THEN N'Warten auf Transaktionslog-I/O.'
                  WHEN N'Network IO' THEN N'Warten auf Netzwerk oder Clientabnahme.'
                  WHEN N'Parallelism' THEN N'Synchronisation paralleler Ausführungszweige.'
                  WHEN N'Memory' THEN N'Warten auf Query- oder interne Speicherressourcen.'
                  WHEN N'Other Disk IO' THEN N'Sonstiger persistenter I/O außerhalb Buffer- und Log-I/O.'
                  ELSE N'Query-Store-Wait-Kategorie für eine interne oder externe Ressource.'
              END
          ) AS [Meaning]
        , CONVERT
          (
              nvarchar(1200)
            , CASE @WaitCategoryDesc
                  WHEN N'CPU' THEN N'CPU-intensive Pläne, Scans, Sorts, Hashes oder hohe Parallelität.'
                  WHEN N'Lock' THEN N'Konkurrierende oder lange Transaktionen.'
                  WHEN N'Buffer IO' THEN N'Cache Misses, große Reads oder langsamer Storage.'
                  WHEN N'Tran Log IO' THEN N'Commit-intensive Workloads oder langsames Log-I/O.'
                  WHEN N'Memory' THEN N'Große Memory Grants oder viele konkurrierende Queries.'
                  ELSE N'Abhängig von Plan, Workload und betroffener Ressource.'
              END
          ) AS [TypicalOccurrence]
        , CONVERT
          (
              nvarchar(1200)
            , CASE @WaitCategoryDesc
                  WHEN N'CPU' THEN N'Durchsatz und Antwortzeit werden durch CPU limitiert.'
                  WHEN N'Worker Thread' THEN N'Queries können verzögert starten oder die Instanz wirkt blockiert.'
                  WHEN N'Lock' THEN N'Blocking, Timeouts und lange Antwortzeiten.'
                  WHEN N'Buffer IO' THEN N'Queries warten auf Seiten vom Storage.'
                  WHEN N'Tran Log IO' THEN N'Commit-Latenz und Schreibdurchsatz verschlechtern sich.'
                  ELSE N'Hohe Werte zeigen einen relevanten Stall-Punkt der Queryausführung; mit Runtime Stats und Plan korrelieren.'
              END
          ) AS [HighWaitImpact]
        , CONVERT
          (
              nvarchar(1500)
            , CASE @WaitCategoryDesc
                  WHEN N'CPU' THEN N'Top CPU Queries, Pläne, Scheduler und Parallelität prüfen.'
                  WHEN N'Lock' THEN N'Blocking, offene Transaktionen, Indizes und Isolation prüfen.'
                  WHEN N'Buffer IO' THEN N'File-Latenz, Reads, Scans, Buffer Pool und Indizes prüfen.'
                  WHEN N'Tran Log IO' THEN N'Log-Latenz, Growth, Commit-Rate und AG-Pfad prüfen.'
                  WHEN N'Memory' THEN N'Memory Grants, Cardinality und Sort-/Hash-Operatoren prüfen.'
                  ELSE N'Query Store Runtime Stats, Planwechsel und betroffene Query/Plan-Kombination prüfen.'
              END
          ) AS [RecommendedChecks]
);
GO
-- END SOURCE: Code/01_Common/076_TVF_QueryStoreWaitCategoryInfo.sql

-- BEGIN SOURCE: Code/01_Common/077_FrameworkVersion.sql
/*
===============================================================================
Objekt       : monitor.FrameworkVersion
Version      : 1.1.0-special.20
Stand        : 2026-07-27
Zweck        : Liefert eine kompakte Versionsinformation für das installierte
               Ad-hoc-Analysepaket. Die Tabelle bildet weder eine
               Installationshistorie noch ein Deployment-Framework ab.
Seiteneffekte: Eine Zeile wird bei Installation oder Upgrade aktualisiert.
===============================================================================
*/
IF NOT EXISTS
(
    SELECT 1
    FROM [sys].[tables] AS [t] WITH (NOLOCK)
    JOIN [sys].[schemas] AS [s] WITH (NOLOCK) ON [s].[schema_id]=[t].[schema_id]
    WHERE [s].[name]=N'monitor' AND [t].[name]=N'FrameworkVersion'
)
BEGIN
    CREATE TABLE [monitor].[FrameworkVersion]
    (
        [FrameworkName] sysname NOT NULL CONSTRAINT PK_FrameworkVersion PRIMARY KEY,
        [FrameworkVersion] varchar(32) NOT NULL,
        [ReleaseDate] date NOT NULL,
        [MinimumProductMajorVersion] int NOT NULL,
        [ContractVersion] varchar(16) NOT NULL,
        [LastInstalledUtc] datetime2(0) NOT NULL,
        [ReleaseNotes] nvarchar(2000) NULL
    );
END;
GO

UPDATE [monitor].[FrameworkVersion]
SET [FrameworkVersion]='1.1.0-special.20',
    [ReleaseDate]='20260727',
    [MinimumProductMajorVersion]=15,
    [ContractVersion]='1.24',
    [LastInstalledUtc]=SYSUTCDATETIME(),
    [ReleaseNotes]=N'API 1.24: SQL25-005 ergänzt Query Store um capability-adaptive Replica-Rollen-, Runtime-, Wait- und Plan-Forcing-Evidenz.'
WHERE [FrameworkName]=N'SQLServerMonitoringFramework';

IF @@ROWCOUNT=0
BEGIN
    INSERT [monitor].[FrameworkVersion]
    (
        [FrameworkName],[FrameworkVersion],[ReleaseDate],[MinimumProductMajorVersion],
        [ContractVersion],[LastInstalledUtc],[ReleaseNotes]
    )
    VALUES
    (
        N'SQLServerMonitoringFramework','1.1.0-special.20','20260727',15,
        '1.24',SYSUTCDATETIME(),
        N'API 1.24: SQL25-005 ergänzt Query Store um capability-adaptive Replica-Rollen-, Runtime-, Wait- und Plan-Forcing-Evidenz.'
    );
END;
GO
-- END SOURCE: Code/01_Common/077_FrameworkVersion.sql

-- BEGIN SOURCE: Code/01_Common/078_TVF_ParsePipeList.sql
/*
===============================================================================
Objekt       : monitor.TVF_ParsePipeList
Version      : 1.1.0
Stand        : 2026-07-15
Typ          : Multi-statement Table-valued Function
Zweck        : Zerlegt eine Pipe-Liste. Das Zeichen | trennt ausschließlich
               außerhalb bracket-quotierter Bereiche. Innerhalb von [...] ist
               | Bestandteil des Werts; ]] maskiert eine schließende Klammer.
SQL-Version  : SQL Server 2019 oder neuer.
Parameter    : @List nvarchar(max).
Resultset    : ItemOrdinal, ItemText, IsBracketQuoted, IsValid, ErrorCode,
               ErrorMessage.
Collation    : Werte werden unter SQL_Latin1_General_CP1_CS_AS zurückgegeben.
Hinweis      : Die Funktion validiert die Listenstruktur. Die fachliche Prüfung
               als sysname, Zahl, Hash oder Multipart-Identifier erfolgt beim
               jeweiligen Verbraucher.
Beispiele    : SELECT * FROM monitor.TVF_ParsePipeList(N'dbo|monitor');
               SELECT * FROM monitor.TVF_ParsePipeList(
                   N'[Das ist | ein komischer Objektname]|[der auch]|der_auch');
Änderungen   : 1.1.0 - Nicht maskierte schließende Klammern, leere Elemente und
                         überlange Listenelemente werden zuverlässig erkannt.
===============================================================================
*/
CREATE OR ALTER FUNCTION [monitor].[TVF_ParsePipeList]
(
    @List nvarchar(max)
)
RETURNS @Items TABLE
(
      [ItemOrdinal]      int             NOT NULL
    , [ItemText]         nvarchar(4000)  COLLATE SQL_Latin1_General_CP1_CS_AS NULL
    , [IsBracketQuoted]  bit             NOT NULL
    , [IsValid]          bit             NOT NULL
    , [ErrorCode]        varchar(40)     COLLATE SQL_Latin1_General_CP1_CS_AS NULL
    , [ErrorMessage]     nvarchar(4000)  COLLATE SQL_Latin1_General_CP1_CS_AS NULL
)
AS
BEGIN
    IF @List IS NULL
        RETURN;

    DECLARE @Length int = DATALENGTH(@List) / 2;
    DECLARE @Position int = 1;
    DECLARE @StartPosition int = 1;
    DECLARE @ItemOrdinal int = 0;
    DECLARE @InBracket bit = 0;
    DECLARE @ItemHasSyntaxError bit = 0;
    DECLARE @Character nchar(1);
    DECLARE @NextCharacter nchar(1);

    IF @Length = 0
    BEGIN
        INSERT @Items
        (
              [ItemOrdinal], [ItemText], [IsBracketQuoted], [IsValid]
            , [ErrorCode], [ErrorMessage]
        )
        VALUES
        (
              1, N'', 0, 0
            , 'EMPTY_LIST', N'Die Liste darf nicht leer sein.'
        );
        RETURN;
    END;

    WHILE @Position <= @Length + 1
    BEGIN
        SET @Character = CASE WHEN @Position <= @Length
                              THEN SUBSTRING(@List, @Position, 1)
                         END;
        SET @NextCharacter = CASE WHEN @Position < @Length
                                  THEN SUBSTRING(@List, @Position + 1, 1)
                             END;

        IF @Position <= @Length AND @InBracket = 1
        BEGIN
            IF @Character = N']'
            BEGIN
                IF @NextCharacter = N']'
                    SET @Position += 1;
                ELSE
                    SET @InBracket = 0;
            END;
        END
        ELSE IF @Position <= @Length AND @Character = N'['
        BEGIN
            SET @InBracket = 1;
        END
        ELSE IF @Position <= @Length AND @Character = N']'
        BEGIN
            SET @ItemHasSyntaxError = 1;
        END
        ELSE IF @Position = @Length + 1 OR @Character = N'|'
        BEGIN
            DECLARE @RawLength int = @Position - @StartPosition;
            DECLARE @RawItem nvarchar(4000) =
                CASE WHEN @RawLength <= 4000
                     THEN CONVERT(nvarchar(4000), SUBSTRING(@List, @StartPosition, @RawLength))
                END;
            DECLARE @ItemText nvarchar(4000) = LTRIM(RTRIM(@RawItem));
            DECLARE @IsBracketQuoted bit = CONVERT
            (
                bit,
                CASE WHEN @ItemText IS NOT NULL
                           AND LEFT(@ItemText, 1) = N'['
                           AND RIGHT(@ItemText, 1) = N']'
                     THEN 1 ELSE 0 END
            );
            DECLARE @ErrorCode varchar(40) =
                CASE WHEN @RawLength > 4000 THEN 'ITEM_TOO_LONG'
                     WHEN @ItemText = N'' THEN 'EMPTY_ITEM'
                     WHEN @ItemHasSyntaxError = 1 OR @InBracket = 1 THEN 'INVALID_BRACKET_SYNTAX'
                END;

            SET @ItemOrdinal += 1;

            INSERT @Items
            (
                  [ItemOrdinal], [ItemText], [IsBracketQuoted], [IsValid]
                , [ErrorCode], [ErrorMessage]
            )
            VALUES
            (
                  @ItemOrdinal
                , @ItemText
                , @IsBracketQuoted
                , CONVERT(bit, CASE WHEN @ErrorCode IS NULL THEN 1 ELSE 0 END)
                , @ErrorCode
                , CASE @ErrorCode
                      WHEN 'ITEM_TOO_LONG' THEN N'Ein Listenelement darf höchstens 4000 Zeichen enthalten.'
                      WHEN 'EMPTY_ITEM' THEN N'Ein Listenelement darf nicht leer sein.'
                      WHEN 'INVALID_BRACKET_SYNTAX' THEN N'Die bracket-quotierte Schreibweise ist syntaktisch ungültig oder nicht abgeschlossen.'
                  END
            );

            SET @StartPosition = @Position + 1;
            SET @ItemHasSyntaxError = 0;
        END;

        SET @Position += 1;
    END;

    RETURN;
END;
GO
-- END SOURCE: Code/01_Common/078_TVF_ParsePipeList.sql

-- BEGIN SOURCE: Code/01_Common/079_TVF_ParsePattern.sql
/*
===============================================================================
Objekt       : monitor.TVF_ParsePattern
Version      : 1.0.0
Stand        : 2026-07-15
Typ          : Inline Table-valued Function
Zweck        : Normalisiert einen textuellen Patternvertrag. Präfixe werden
               case-insensitiv verarbeitet; der Patterninhalt selbst bleibt
               unverändert und damit case-sensitive auswertbar.
SQL-Version  : SQL Server 2019 oder neuer.
Parameter    : @Pattern nvarchar(4000).
Modi         : LIKE (Default oder like:), REGEX (regex:), REGEXI (regexi:),
               NONE bei NULL.
Hinweis      : REGEX/REGEXI benötigen SQL Server 2025 und Compatibility Level
               170. Die eigentliche REGEXP_LIKE-Ausführung muss versionsadaptiv
               über dynamisches SQL erfolgen, damit SQL Server 2019/2022 die
               Module weiterhin kompilieren können.
===============================================================================
*/
CREATE OR ALTER FUNCTION [monitor].[TVF_ParsePattern]
(
    @Pattern nvarchar(4000)
)
RETURNS TABLE
AS
RETURN
(
    WITH [P] AS
    (
        SELECT [TrimmedPattern] = CASE WHEN @Pattern IS NULL THEN NULL
                                       ELSE LTRIM(RTRIM(@Pattern)) END
    ),
    [N] AS
    (
        SELECT
              [PatternMode] = CONVERT(varchar(8),
                  CASE WHEN [TrimmedPattern] IS NULL THEN 'NONE'
                       WHEN UPPER(LEFT([TrimmedPattern], 7)) = 'REGEXI:' THEN 'REGEXI'
                       WHEN UPPER(LEFT([TrimmedPattern], 6)) = 'REGEX:'  THEN 'REGEX'
                       WHEN UPPER(LEFT([TrimmedPattern], 5)) = 'LIKE:'   THEN 'LIKE'
                       ELSE 'LIKE' END)
            , [PatternValue] = CONVERT(nvarchar(4000),
                  CASE WHEN [TrimmedPattern] IS NULL THEN NULL
                       WHEN UPPER(LEFT([TrimmedPattern], 7)) = 'REGEXI:' THEN SUBSTRING([TrimmedPattern], 8, 4000)
                       WHEN UPPER(LEFT([TrimmedPattern], 6)) = 'REGEX:'  THEN SUBSTRING([TrimmedPattern], 7, 4000)
                       WHEN UPPER(LEFT([TrimmedPattern], 5)) = 'LIKE:'   THEN SUBSTRING([TrimmedPattern], 6, 4000)
                       ELSE [TrimmedPattern] END)
        FROM [P]
    )
    SELECT
          [PatternMode]
        , [PatternValue] COLLATE SQL_Latin1_General_CP1_CS_AS AS [PatternValue]
        , CONVERT(varchar(8), CASE WHEN [PatternMode] = 'REGEXI' THEN 'i'
                                   WHEN [PatternMode] = 'REGEX' THEN 'c'
                              END) AS [RegexFlags]
        , CONVERT(bit, CASE WHEN [PatternMode] IN ('REGEX', 'REGEXI') THEN 1 ELSE 0 END) AS [IsRegex]
        , CONVERT(bit, CASE WHEN [PatternMode] = 'NONE' THEN 1
                            WHEN NULLIF([PatternValue], N'') IS NULL THEN 0
                            ELSE 1 END) AS [IsValid]
        , CONVERT(varchar(40), CASE WHEN [PatternMode] <> 'NONE' AND NULLIF([PatternValue], N'') IS NULL
                                    THEN 'EMPTY_PATTERN' END) AS [ErrorCode]
        , CONVERT(nvarchar(4000), CASE WHEN [PatternMode] <> 'NONE' AND NULLIF([PatternValue], N'') IS NULL
                                       THEN N'Das Pattern darf nach dem Präfix nicht leer sein.' END) AS [ErrorMessage]
    FROM [N]
);
GO
-- END SOURCE: Code/01_Common/079_TVF_ParsePattern.sql

-- BEGIN SOURCE: Code/01_Common/080_TVF_ParseSqlNameList.sql
/*
===============================================================================
Objekt       : monitor.TVF_ParseSqlNameList
Version      : 1.0.0
Stand        : 2026-07-15
Typ          : Inline Table-valued Function
Zweck        : Validiert eine bracket-aware Pipe-Liste aus einteiligen SQL-
               Namen und liefert die entquoteten sysname-Werte.
Beispiele    : SELECT * FROM monitor.TVF_ParseSqlNameList(
                   N'[ColumnOne]|[Column With Spaces]|[Column|WithPipe]');
===============================================================================
*/
CREATE OR ALTER FUNCTION [monitor].[TVF_ParseSqlNameList]
(
    @List nvarchar(max)
)
RETURNS TABLE
AS
RETURN
(
    SELECT
          [l].[ItemOrdinal]
        , [l].[ItemText]
        , [NameValue] = CONVERT(sysname, PARSENAME([l].[ItemText], 1))
        , [IsValid] = CONVERT(bit,
              CASE WHEN [l].[IsValid] = 1
                     AND PARSENAME([l].[ItemText], 1) IS NOT NULL
                     AND PARSENAME([l].[ItemText], 2) IS NULL
                     AND LEN(PARSENAME([l].[ItemText], 1)) <= 128
                   THEN 1 ELSE 0 END)
        , [ErrorCode] = CONVERT(varchar(40),
              CASE WHEN [l].[IsValid] = 0 THEN [l].[ErrorCode]
                   WHEN PARSENAME([l].[ItemText], 1) IS NULL THEN 'INVALID_SQL_NAME'
                   WHEN PARSENAME([l].[ItemText], 2) IS NOT NULL THEN 'MULTIPART_NAME_NOT_ALLOWED'
                   WHEN LEN(PARSENAME([l].[ItemText], 1)) > 128 THEN 'SQL_NAME_TOO_LONG'
              END)
        , [ErrorMessage] = CONVERT(nvarchar(4000),
              CASE WHEN [l].[IsValid] = 0 THEN [l].[ErrorMessage]
                   WHEN PARSENAME([l].[ItemText], 1) IS NULL THEN N'Das Listenelement ist kein gültiger SQL-Name.'
                   WHEN PARSENAME([l].[ItemText], 2) IS NOT NULL THEN N'Für diesen Parameter ist nur ein einteiliger SQL-Name zulässig.'
                   WHEN LEN(PARSENAME([l].[ItemText], 1)) > 128 THEN N'Der SQL-Name überschreitet die sysname-Länge von 128 Zeichen.'
              END)
    FROM [monitor].[TVF_ParsePipeList](@List) AS [l]
);
GO
-- END SOURCE: Code/01_Common/080_TVF_ParseSqlNameList.sql

-- BEGIN SOURCE: Code/01_Common/081_TVF_ParseFullObjectNameList.sql
/*
===============================================================================
Objekt       : monitor.TVF_ParseFullObjectNameList
Version      : 1.0.0
Stand        : 2026-07-15
Typ          : Inline Table-valued Function
Zweck        : Validiert eine bracket-aware Pipe-Liste aus ein-, zwei- oder
               dreiteiligen Objektbezügen: Objekt, Schema.Objekt oder
               Datenbank.Schema.Objekt. Vierteilige Linked-Server-Namen werden
               bewusst nicht unterstützt.
Beispiele    : SELECT * FROM monitor.TVF_ParseFullObjectNameList(
                   N'[DeineDatenbank].dbo.[IrgendeinObjekt]|und.noch.eines');
===============================================================================
*/
CREATE OR ALTER FUNCTION [monitor].[TVF_ParseFullObjectNameList]
(
    @List nvarchar(max)
)
RETURNS TABLE
AS
RETURN
(
    SELECT
          [l].[ItemOrdinal]
        , [l].[ItemText]
        , [DatabaseName] = CONVERT(sysname, PARSENAME([l].[ItemText], 3))
        , [SchemaName]   = CONVERT(sysname, PARSENAME([l].[ItemText], 2))
        , [ObjectName]   = CONVERT(sysname, PARSENAME([l].[ItemText], 1))
        , [PartCount]    = CONVERT(tinyint,
              CASE WHEN PARSENAME([l].[ItemText], 3) IS NOT NULL THEN 3
                   WHEN PARSENAME([l].[ItemText], 2) IS NOT NULL THEN 2
                   WHEN PARSENAME([l].[ItemText], 1) IS NOT NULL THEN 1
                   ELSE 0 END)
        , [IsValid] = CONVERT(bit,
              CASE WHEN [l].[IsValid] = 1
                     AND PARSENAME([l].[ItemText], 1) IS NOT NULL
                     AND PARSENAME([l].[ItemText], 4) IS NULL
                     AND NOT (PARSENAME([l].[ItemText], 3) IS NOT NULL
                              AND PARSENAME([l].[ItemText], 2) IS NULL)
                     AND LEN(PARSENAME([l].[ItemText], 1)) <= 128
                     AND COALESCE(LEN(PARSENAME([l].[ItemText], 2)), 0) <= 128
                     AND COALESCE(LEN(PARSENAME([l].[ItemText], 3)), 0) <= 128
                   THEN 1 ELSE 0 END)
        , [ErrorCode] = CONVERT(varchar(40),
              CASE WHEN [l].[IsValid] = 0 THEN [l].[ErrorCode]
                   WHEN PARSENAME([l].[ItemText], 1) IS NULL THEN 'INVALID_OBJECT_REFERENCE'
                   WHEN PARSENAME([l].[ItemText], 4) IS NOT NULL THEN 'FOUR_PART_NAME_NOT_ALLOWED'
                   WHEN PARSENAME([l].[ItemText], 3) IS NOT NULL
                    AND PARSENAME([l].[ItemText], 2) IS NULL THEN 'SCHEMA_NAME_REQUIRED'
                   WHEN LEN(PARSENAME([l].[ItemText], 1)) > 128
                     OR COALESCE(LEN(PARSENAME([l].[ItemText], 2)), 0) > 128
                     OR COALESCE(LEN(PARSENAME([l].[ItemText], 3)), 0) > 128 THEN 'SQL_NAME_TOO_LONG'
              END)
        , [ErrorMessage] = CONVERT(nvarchar(4000),
              CASE WHEN [l].[IsValid] = 0 THEN [l].[ErrorMessage]
                   WHEN PARSENAME([l].[ItemText], 1) IS NULL THEN N'Der Objektbezug ist syntaktisch ungültig.'
                   WHEN PARSENAME([l].[ItemText], 4) IS NOT NULL THEN N'Vierteilige Linked-Server-Namen werden nicht unterstützt.'
                   WHEN PARSENAME([l].[ItemText], 3) IS NOT NULL
                    AND PARSENAME([l].[ItemText], 2) IS NULL THEN N'Bei einem dreiteiligen Objektbezug ist das Schema erforderlich.'
                   WHEN LEN(PARSENAME([l].[ItemText], 1)) > 128
                     OR COALESCE(LEN(PARSENAME([l].[ItemText], 2)), 0) > 128
                     OR COALESCE(LEN(PARSENAME([l].[ItemText], 3)), 0) > 128 THEN N'Mindestens ein Namensbestandteil überschreitet die sysname-Länge von 128 Zeichen.'
              END)
    FROM [monitor].[TVF_ParsePipeList](@List) AS [l]
);
GO
-- END SOURCE: Code/01_Common/081_TVF_ParseFullObjectNameList.sql

-- BEGIN SOURCE: Code/01_Common/082_TVF_DatabaseCandidates.sql
/*
===============================================================================
Objekt       : monitor.TVF_DatabaseCandidates
Version      : 3.0.0
Stand        : 2026-07-20
Typ          : Inline Table-valued Function
Zweck        : Liefert alle sichtbaren, zugreifbaren und online befindlichen
               Benutzerdatenbanken oder eine explizit eingeschränkte Menge.
SQL-Version  : SQL Server 2019 oder neuer.
Datenquellen : master.sys.databases, monitor.TVF_ParseSqlNameList,
               monitor.TVF_ParsePattern.
Semantik     : NULL, N'' und Leerzeichen bedeuten keine Einschränkung.
               Systemdatenbanken sind ausschließlich per Opt-in enthalten.
               Die Kandidatenmenge wird niemals vorab mengenmäßig begrenzt.
Vertrag      : Die Kandidatenmenge wird erst nach vollständiger Ermittlung und
               ohne willkürliche Vorabbegrenzung an den Aufrufer zurückgegeben.
===============================================================================
*/
CREATE OR ALTER FUNCTION [monitor].[TVF_DatabaseCandidates]
(
      @DatabaseNames                    nvarchar(max)  = NULL
    , @SystemdatenbankenEinbeziehen     bit            = 0
    , @DatabaseNamePattern              nvarchar(4000) = NULL
)
RETURNS TABLE
AS
RETURN
(
    WITH [Parameters] AS
    (
        SELECT [EffectiveDatabaseNames] = CONVERT
        (
            nvarchar(max),
            CASE
                WHEN NULLIF(LTRIM(RTRIM(COALESCE(@DatabaseNames, N''))), N'') IS NULL
                    THEN NULL
                ELSE @DatabaseNames
            END
        )
    ),
    [ExactNames] AS
    (
        SELECT
              [l].[ItemOrdinal]
            , [DatabaseName] = CONVERT(sysname, [l].[NameValue])
        FROM [Parameters] AS [p]
        CROSS APPLY [monitor].[TVF_ParseSqlNameList]([p].[EffectiveDatabaseNames]) AS [l]
        WHERE [l].[IsValid] = 1
    ),
    [Pattern] AS
    (
        SELECT [PatternMode], [PatternValue], [IsValid]
        FROM [monitor].[TVF_ParsePattern](@DatabaseNamePattern)
    )
    SELECT
          [d].[database_id] AS [DatabaseId]
        , [d].[name] COLLATE SQL_Latin1_General_CP1_CS_AS AS [DatabaseName]
        , [d].[state_desc] AS [StateDesc]
        , [d].[user_access_desc] AS [UserAccessDesc]
        , [d].[is_read_only] AS [IsReadOnly]
        , [d].[compatibility_level] AS [CompatibilityLevel]
        , [d].[collation_name] AS [CollationName]
        , [d].[recovery_model_desc] AS [RecoveryModelDesc]
        , CONVERT(bit, CASE WHEN [d].[database_id] <= 4 THEN 1 ELSE 0 END) AS [IsSystemDatabase]
        , [e].[ItemOrdinal] AS [RequestedOrdinal]
    FROM [master].[sys].[databases] AS [d] WITH (NOLOCK)
    CROSS JOIN [Parameters] AS [p]
    CROSS JOIN [Pattern] AS [pt]
    LEFT JOIN [ExactNames] AS [e]
      ON [e].[DatabaseName] COLLATE SQL_Latin1_General_CP1_CS_AS
       = [d].[name] COLLATE SQL_Latin1_General_CP1_CS_AS
    WHERE [pt].[IsValid] = 1
      AND [d].[source_database_id] IS NULL
      AND [d].[state] = 0
      AND HAS_DBACCESS([d].[name]) = 1
      AND (@SystemdatenbankenEinbeziehen = 1 OR [d].[database_id] > 4)
      AND ([p].[EffectiveDatabaseNames] IS NULL OR [e].[DatabaseName] IS NOT NULL)
      AND
      (
          [pt].[PatternMode] IN ('NONE', 'REGEX', 'REGEXI')
          OR [d].[name] COLLATE SQL_Latin1_General_CP1_CS_AS
             LIKE [pt].[PatternValue] COLLATE SQL_Latin1_General_CP1_CS_AS
      )
);
GO
-- END SOURCE: Code/01_Common/082_TVF_DatabaseCandidates.sql

-- BEGIN SOURCE: Code/01_Common/083a_USP_InternalCheckAnalysisPath.sql
/*
===============================================================================
Objekt       : monitor.InternalCheckAnalysisPath
Version      : 1.1.0
Stand        : 2026-07-21
Typ          : Interne Stored Procedure
Zweck        : Prüft einen tatsächlich aktivierten Analysepfad auf bekannte
               Klasse, High-Impact-Bestätigung und aktuelle Freigabe, bevor
               fachliche DMV-, Cache-, Query-Store- oder Katalogzugriffe
               beginnen.
Fallback     : Kann der serverseitige Login-Token unter EXECUTE AS USER oder
               einem vergleichbaren datenbankgebundenen Kontext nicht gelesen
               werden, bleiben ungeschützte Klassen, sysadmin und offene Policy
               erlaubt. Eine aktive gruppengeschützte Policy wird konservativ
               als DENIED_GROUP behandelt; sie wird niemals still umgangen.
===============================================================================
*/
CREATE OR ALTER PROCEDURE [monitor].[InternalCheckAnalysisPath]
      @AnalysisClass        varchar(64)
    , @HighImpactConfirmed  bit
    , @StatusCode           varchar(40)    OUTPUT
    , @ErrorMessage         nvarchar(2048) OUTPUT
AS
BEGIN
    SET NOCOUNT ON;
    SET LOCK_TIMEOUT 0;

    SELECT @StatusCode='AVAILABLE',@ErrorMessage=NULL;

    IF NULLIF(@AnalysisClass,'') IS NULL
       OR @HighImpactConfirmed IS NULL
       OR @HighImpactConfirmed NOT IN (0,1)
    BEGIN
        SET @StatusCode='INVALID_PARAMETER';
        SET @ErrorMessage=N'Analyseklasse oder High-Impact-Bestätigung ist ungültig.';
        RETURN;
    END;

    DECLARE
          @RequiresHighImpact bit=0
        , @Allowed bit=0
        , @UsedDatabaseOnlyFallback bit=0
        , @IsSysadmin bit=CONVERT(bit,CASE WHEN IS_SRVROLEMEMBER(N'sysadmin')=1 THEN 1 ELSE 0 END);

    BEGIN TRY
        SELECT
              @RequiresHighImpact=COALESCE(MAX(CONVERT(tinyint,[c].[RequiresGroupGate])),0)
            , @Allowed=COALESCE(MAX(CONVERT(tinyint,[a].[IsAllowed])),0)
        FROM [monitor].[VW_AnalyseClassCatalog] AS [c]
        LEFT JOIN [monitor].[VW_AnalyseAccessCurrent] AS [a]
          ON [a].[AnalysisClass]=[c].[AnalysisClass]
        WHERE [c].[AnalysisClass]=@AnalysisClass;
    END TRY
    BEGIN CATCH
        IF ERROR_NUMBER() NOT IN (229,371,916)
            THROW;

        SET @UsedDatabaseOnlyFallback=1;

        SELECT @RequiresHighImpact=COALESCE(MAX(CONVERT(tinyint,[c].[RequiresGroupGate])),0)
        FROM [monitor].[VW_AnalyseClassCatalog] AS [c]
        WHERE [c].[AnalysisClass]=@AnalysisClass;

        SET @Allowed=CONVERT(bit,CASE
              WHEN @RequiresHighImpact=0 THEN 1
              WHEN @IsSysadmin=1 THEN 1
              WHEN NOT EXISTS
                   (
                       SELECT 1
                       FROM [monitor].[VW_AnalyseAccessPolicy] AS [p]
                       WHERE [p].[IsEnabled]=1
                         AND ([p].[ValidFromUtc] IS NULL OR [p].[ValidFromUtc]<=SYSUTCDATETIME())
                         AND ([p].[ValidToUtc] IS NULL OR [p].[ValidToUtc]>SYSUTCDATETIME())
                         AND NULLIF(LTRIM(RTRIM([p].[AnalysisClass])),N'') IS NOT NULL
                         AND NULLIF(LTRIM(RTRIM([p].[ADGroupName])),N'') IS NOT NULL
                   ) THEN 1
              ELSE 0 END);
    END CATCH;

    IF NOT EXISTS
       (
           SELECT 1
           FROM [monitor].[VW_AnalyseClassCatalog]
           WHERE [AnalysisClass]=@AnalysisClass
       )
    BEGIN
        SET @StatusCode='INVALID_PARAMETER';
        SET @ErrorMessage=CONCAT(N'Unbekannte Analyseklasse: ',@AnalysisClass,N'.');
        RETURN;
    END;

    IF @RequiresHighImpact=1 AND @HighImpactConfirmed<>1
    BEGIN
        SET @StatusCode='HIGH_IMPACT_CONFIRMATION_REQUIRED';
        SET @ErrorMessage=CONCAT(N'Der aktivierte Analysepfad ',@AnalysisClass,N' erfordert @HighImpactConfirmed=1.');
        RETURN;
    END;

    IF @Allowed<>1
    BEGIN
        SET @StatusCode='DENIED_GROUP';
        SET @ErrorMessage=CASE WHEN @UsedDatabaseOnlyFallback=1
                              THEN CONCAT(@AnalysisClass,N' ist nicht freigegeben; der serverseitige Gruppentoken war im aktuellen Datenbankkontext nicht lesbar.')
                              ELSE CONCAT(@AnalysisClass,N' ist nicht freigegeben.') END;
    END;
END;
GO
-- END SOURCE: Code/01_Common/083a_USP_InternalCheckAnalysisPath.sql

-- BEGIN SOURCE: Code/01_Common/083_USP_PrepareDatabaseCandidates.sql
/*
===============================================================================
Objekt       : monitor.USP_PrepareDatabaseCandidates
Version      : 2.0.0
Stand        : 2026-07-20
Typ          : Interne Stored Procedure
Zweck        : Validiert die frameworkweite Datenbankauswahl, prüft den
               tatsächlich aktivierten Analysepfad und befüllt lokale
               Kandidaten- und Warning-Temp-Tabellen des Aufrufers.
Semantik     : Ohne explizite Einschränkung alle sichtbaren, online befindlichen
               Benutzerdatenbanken. Kein CURRENT-Scope und keine Vorabbegrenzung.
High Impact  : Nur eine tatsächlich aktivierte Analyseklasse mit
               RequiresGroupGate=1 verlangt @HighImpactConfirmed=1.
Vertrag      : Die Procedure kennt keine Datenbank-Mengenbegrenzung.
===============================================================================
*/
CREATE OR ALTER PROCEDURE [monitor].[USP_PrepareDatabaseCandidates]
      @DatabaseNames                    nvarchar(max)  = NULL
    , @SystemdatenbankenEinbeziehen     bit            = 0
    , @DatabaseNamePattern              nvarchar(4000) = NULL
    , @AnalysisClass                    varchar(64)    = NULL
    , @HighImpactConfirmed              bit            = 0
    , @StatusCode                       varchar(40)    OUTPUT
    , @ErrorMessage                     nvarchar(2048) OUTPUT
    , @CrossDatabaseRequested           bit            OUTPUT
    , @CandidateTable                   sysname        = N'#PrepareDatabaseCandidates_Result'
    , @WarningTable                     sysname        = NULL
AS
BEGIN
    SET NOCOUNT ON;
    SET LOCK_TIMEOUT 0;

    SELECT
          @StatusCode = 'AVAILABLE'
        , @ErrorMessage = NULL
        , @CrossDatabaseRequested = 0;

    DECLARE @EffectiveDatabaseNames nvarchar(max) =
        CASE WHEN NULLIF(LTRIM(RTRIM(COALESCE(@DatabaseNames, N''))), N'') IS NULL
             THEN NULL ELSE @DatabaseNames END;
    DECLARE @PatternMode varchar(8);
    DECLARE @PatternValue nvarchar(4000);
    DECLARE @RegexFlags varchar(8);
    DECLARE @PatternIsValid bit;
    DECLARE @DatabaseListCount int = 0;
    DECLARE @Sql nvarchar(max);
    DECLARE @CandidateTableQuoted nvarchar(258);
    DECLARE @WarningTableQuoted nvarchar(258);

    IF @SystemdatenbankenEinbeziehen IS NULL
       OR @SystemdatenbankenEinbeziehen NOT IN (0,1)
       OR @HighImpactConfirmed IS NULL
       OR @HighImpactConfirmed NOT IN (0,1)
       OR @CandidateTable IS NULL
       OR LEFT(@CandidateTable,1) <> N'#'
       OR LEFT(@CandidateTable,2) = N'##'
       OR LEN(@CandidateTable) > 116
       OR
       (
           @WarningTable IS NOT NULL
           AND
           (
               LEFT(@WarningTable,1) <> N'#'
               OR LEFT(@WarningTable,2) = N'##'
               OR LEN(@WarningTable) > 116
           )
       )
    BEGIN
        SET @StatusCode = 'INVALID_PARAMETER';
        SET @ErrorMessage = N'Ungültige Auswahl-, Bestätigungs- oder interne Temp-Tabellenparameter.';
        RETURN;
    END;

    SELECT
          @CandidateTableQuoted = QUOTENAME(@CandidateTable)
        , @WarningTableQuoted = QUOTENAME(@WarningTable);

    CREATE TABLE [#PrepareDatabaseCandidates_Work]
    (
          [DatabaseId] int NOT NULL
        , [DatabaseName] sysname COLLATE SQL_Latin1_General_CP1_CS_AS NOT NULL
        , [StateDesc] nvarchar(60) NULL
        , [UserAccessDesc] nvarchar(60) NULL
        , [IsReadOnly] bit NULL
        , [CompatibilityLevel] tinyint NULL
        , [CollationName] sysname NULL
        , [RecoveryModelDesc] nvarchar(60) NULL
        , [IsSystemDatabase] bit NULL
        , [RequestedOrdinal] int NULL
    );

    CREATE TABLE [#PrepareDatabaseCandidates_RequestedNames]
    (
          [NameValue] sysname COLLATE SQL_Latin1_General_CP1_CS_AS NULL
        , [IsValid] bit NOT NULL
    );

    IF @EffectiveDatabaseNames IS NOT NULL
        INSERT [#PrepareDatabaseCandidates_RequestedNames]([NameValue],[IsValid])
        SELECT [NameValue],[IsValid]
        FROM [monitor].[TVF_ParseSqlNameList](@EffectiveDatabaseNames);

    BEGIN TRY
        SET @Sql = N'DECLARE @DatabaseId int,@DatabaseName sysname;
SELECT TOP (0) @DatabaseId=[DatabaseId],@DatabaseName=[DatabaseName]
FROM ' + @CandidateTableQuoted + N';';
        EXEC [sys].[sp_executesql] @Sql;
    END TRY
    BEGIN CATCH
        SET @StatusCode = 'INTERNAL_ERROR';
        SET @ErrorMessage = N'Die Kandidaten-Temp-Tabelle wurde nicht mit dem erwarteten Schema angelegt.';
        RETURN;
    END CATCH;

    SELECT
          @PatternMode = [PatternMode]
        , @PatternValue = [PatternValue]
        , @RegexFlags = [RegexFlags]
        , @PatternIsValid = [IsValid]
    FROM [monitor].[TVF_ParsePattern](@DatabaseNamePattern);

    IF @EffectiveDatabaseNames IS NOT NULL
        SELECT @DatabaseListCount = COUNT(*)
        FROM [#PrepareDatabaseCandidates_RequestedNames]
        WHERE [IsValid] = 1;

    SET @CrossDatabaseRequested = CONVERT
    (
        bit,
        CASE WHEN @EffectiveDatabaseNames IS NULL OR @DatabaseListCount > 1
             THEN 1 ELSE 0 END
    );

    IF @PatternIsValid = 0
       OR
       (
           @EffectiveDatabaseNames IS NOT NULL
           AND EXISTS
           (
               SELECT 1
               FROM [#PrepareDatabaseCandidates_RequestedNames]
               WHERE [IsValid] = 0
           )
       )
       OR (@EffectiveDatabaseNames IS NOT NULL AND @DatabaseNamePattern IS NOT NULL)
       OR
       (
           @EffectiveDatabaseNames IS NOT NULL
           AND EXISTS
           (
               SELECT [NameValue]
               FROM [#PrepareDatabaseCandidates_RequestedNames]
               WHERE [IsValid] = 1
               GROUP BY [NameValue] COLLATE SQL_Latin1_General_CP1_CS_AS
               HAVING COUNT(*) > 1
           )
       )
    BEGIN
        SET @StatusCode = 'INVALID_PARAMETER';
        SET @ErrorMessage = N'Ungültige oder doppelte Datenbankliste beziehungsweise ungültiges Pattern. Exakte Liste und Pattern sind gegenseitig exklusiv.';
        RETURN;
    END;

    IF NULLIF(@AnalysisClass, '') IS NOT NULL
    BEGIN
        EXEC [monitor].[InternalCheckAnalysisPath]
              @AnalysisClass=@AnalysisClass
            , @HighImpactConfirmed=@HighImpactConfirmed
            , @StatusCode=@StatusCode OUTPUT
            , @ErrorMessage=@ErrorMessage OUTPUT;

        IF @StatusCode<>'AVAILABLE'
            RETURN;
    END;

    INSERT [#PrepareDatabaseCandidates_Work]
    (
          [DatabaseId],[DatabaseName],[StateDesc],[UserAccessDesc],[IsReadOnly]
        , [CompatibilityLevel],[CollationName],[RecoveryModelDesc]
        , [IsSystemDatabase],[RequestedOrdinal]
    )
    SELECT
          [DatabaseId],[DatabaseName],[StateDesc],[UserAccessDesc],[IsReadOnly]
        , [CompatibilityLevel],[CollationName],[RecoveryModelDesc]
        , [IsSystemDatabase],[RequestedOrdinal]
    FROM [monitor].[TVF_DatabaseCandidates]
    (
          @EffectiveDatabaseNames
        , @SystemdatenbankenEinbeziehen
        , @DatabaseNamePattern
    );

    SET @Sql = N'INSERT ' + @CandidateTableQuoted + N'
(
      [DatabaseId],[DatabaseName],[StateDesc],[UserAccessDesc],[IsReadOnly]
    , [CompatibilityLevel],[CollationName],[RecoveryModelDesc]
    , [IsSystemDatabase],[RequestedOrdinal]
)
SELECT
      [DatabaseId],[DatabaseName],[StateDesc],[UserAccessDesc],[IsReadOnly]
    , [CompatibilityLevel],[CollationName],[RecoveryModelDesc]
    , [IsSystemDatabase],[RequestedOrdinal]
FROM [#PrepareDatabaseCandidates_Work];';
    EXEC [sys].[sp_executesql] @Sql;

    DECLARE @WarningTableAvailable bit = 0;
    IF @WarningTable IS NOT NULL
    BEGIN
        BEGIN TRY
            SET @Sql = N'SELECT TOP (0) [RequestedName],[StatusCode],[ErrorMessage] FROM ' + @WarningTableQuoted + N';';
            EXEC [sys].[sp_executesql] @Sql;
            SET @WarningTableAvailable = 1;
        END TRY
        BEGIN CATCH
            SET @WarningTableAvailable = 0;
        END CATCH;
    END;

    IF @WarningTableAvailable = 1 AND @EffectiveDatabaseNames IS NOT NULL
    BEGIN
        SET @Sql = N'INSERT ' + @WarningTableQuoted + N' ([RequestedName],[StatusCode],[ErrorMessage])
SELECT
      [n].[NameValue]
    , CASE
          WHEN @IncludeSystem = 0
           AND [n].[NameValue] COLLATE SQL_Latin1_General_CP1_CS_AS
               IN (N''master'',N''tempdb'',N''model'',N''msdb'')
              THEN ''SYSTEM_DATABASE_EXCLUDED''
          ELSE ''DATABASE_UNAVAILABLE''
      END
    , CASE
          WHEN @IncludeSystem = 0
           AND [n].[NameValue] COLLATE SQL_Latin1_General_CP1_CS_AS
               IN (N''master'',N''tempdb'',N''model'',N''msdb'')
              THEN N''Die explizit angeforderte Systemdatenbank ist ohne Opt-in ausgeschlossen.''
          ELSE N''Die explizit angeforderte Datenbank ist nicht vorhanden, nicht online oder für den aktuellen Login nicht zugreifbar.''
      END
FROM [#PrepareDatabaseCandidates_RequestedNames] AS [n]
WHERE [n].[IsValid] = 1
  AND NOT EXISTS
      (
          SELECT 1
          FROM ' + @CandidateTableQuoted + N' AS [c]
          WHERE [c].[DatabaseName] COLLATE SQL_Latin1_General_CP1_CS_AS
              = [n].[NameValue] COLLATE SQL_Latin1_General_CP1_CS_AS
      );';

        EXEC [sys].[sp_executesql]
              @Sql
            , N'@IncludeSystem bit'
            , @IncludeSystem = @SystemdatenbankenEinbeziehen;
    END;

    IF @PatternMode IN ('REGEX', 'REGEXI')
    BEGIN
        IF TRY_CONVERT(int, SERVERPROPERTY(N'ProductMajorVersion')) < 17
           OR NOT EXISTS
              (
                  SELECT 1
                  FROM [master].[sys].[databases] AS [d] WITH (NOLOCK)
                  WHERE [d].[database_id] = DB_ID()
                    AND [d].[compatibility_level] >= 170
              )
        BEGIN
            SET @Sql = N'DELETE FROM ' + @CandidateTableQuoted + N';';
            EXEC [sys].[sp_executesql] @Sql;
            SET @StatusCode = 'UNAVAILABLE_FEATURE';
            SET @ErrorMessage = N'Regex benötigt SQL Server 2025 und Compatibility Level 170 für die Installationsdatenbank.';
            RETURN;
        END;

        SET @Sql = N'DELETE [c]
FROM ' + @CandidateTableQuoted + N' AS [c]
WHERE NOT REGEXP_LIKE([c].[DatabaseName], @Pattern, @Flags);';

        EXEC [sys].[sp_executesql]
              @Sql
            , N'@Pattern nvarchar(4000), @Flags varchar(8)'
            , @Pattern = @PatternValue
            , @Flags = @RegexFlags;
    END;
END;
GO
-- END SOURCE: Code/01_Common/083_USP_PrepareDatabaseCandidates.sql

-- BEGIN SOURCE: Code/01_Common/084_USP_PrepareNameFilters.sql
/*
===============================================================================
Objekt       : monitor.USP_PrepareNameFilters
Version      : 1.0.0
Stand        : 2026-07-15
Typ          : Interne Stored Procedure
Zweck        : Validiert bracket-aware Pipe-Listen für einteilige SQL-Namen und
               vollständige Objektbezüge und befüllt die vom Aufrufer benannte
               Temp-Tabelle.
Voraussetzung: @FilterTable(FilterType, ItemOrdinal, NameValue, DatabaseName,
               SchemaName, ObjectName).
Hinweis      : Werte werden exakt case-sensitiv unter
               SQL_Latin1_General_CP1_CS_AS behandelt.
===============================================================================
*/
CREATE OR ALTER PROCEDURE [monitor].[USP_PrepareNameFilters]
      @SchemaNames       nvarchar(max)  = NULL
    , @ObjectNames       nvarchar(max)  = NULL
    , @FullObjectNames   nvarchar(max)  = NULL
    , @IndexNames        nvarchar(max)  = NULL
    , @StatisticsNames   nvarchar(max)  = NULL
    , @ColumnNames       nvarchar(max)  = NULL
    , @StatusCode        varchar(40)    OUTPUT
    , @ErrorMessage      nvarchar(2048) OUTPUT
    , @FilterTable       sysname        = N'#PrepareNameFilters_Result'
AS
BEGIN
    SET NOCOUNT ON;
    SET LOCK_TIMEOUT 0;
    SET @StatusCode = 'AVAILABLE';
    SET @ErrorMessage = NULL;

    IF @FilterTable IS NULL
       OR LEFT(@FilterTable,1)<>N'#'
       OR LEFT(@FilterTable,2)=N'##'
       OR LEN(@FilterTable)>116
    BEGIN
        SET @StatusCode = 'INVALID_PARAMETER';
        SET @ErrorMessage = N'@FilterTable muss einen gültigen lokalen #Temp-Tabellennamen enthalten.';
        RETURN;
    END;

    DECLARE @FilterTableQuoted nvarchar(258)=QUOTENAME(@FilterTable);
    DECLARE @Sql nvarchar(max);

    CREATE TABLE [#PrepareNameFilters_Work]
    (
          [FilterType] varchar(20) COLLATE SQL_Latin1_General_CP1_CS_AS NOT NULL
        , [ItemOrdinal] int NOT NULL
        , [NameValue] sysname COLLATE SQL_Latin1_General_CP1_CS_AS NULL
        , [DatabaseName] sysname COLLATE SQL_Latin1_General_CP1_CS_AS NULL
        , [SchemaName] sysname COLLATE SQL_Latin1_General_CP1_CS_AS NULL
        , [ObjectName] sysname COLLATE SQL_Latin1_General_CP1_CS_AS NULL
        , [IsValid] bit NOT NULL
    );

    BEGIN TRY
        SET @Sql=N'SELECT TOP (0) [FilterType],[ItemOrdinal],[NameValue],[DatabaseName],[SchemaName],[ObjectName] FROM '+@FilterTableQuoted+N';';
        EXEC [sys].[sp_executesql] @Sql;
    END TRY
    BEGIN CATCH
        SET @StatusCode = 'INTERNAL_ERROR';
        SET @ErrorMessage = N'Die über @FilterTable benannte Temp-Tabelle wurde nicht angelegt.';
        RETURN;
    END CATCH;

    IF @FullObjectNames IS NOT NULL
       AND (@SchemaNames IS NOT NULL OR @ObjectNames IS NOT NULL)
    BEGIN
        SET @StatusCode = 'INVALID_PARAMETER';
        SET @ErrorMessage = N'@FullObjectNames ist mit @SchemaNames und @ObjectNames gegenseitig exklusiv.';
        RETURN;
    END;

    BEGIN TRY
        INSERT [#PrepareNameFilters_Work]
        ([FilterType],[ItemOrdinal],[NameValue],[DatabaseName],[SchemaName],[ObjectName],[IsValid])
        SELECT 'SCHEMA',[ItemOrdinal],[NameValue],NULL,NULL,NULL,[IsValid]
        FROM [monitor].[TVF_ParseSqlNameList](@SchemaNames)
        UNION ALL
        SELECT 'OBJECT',[ItemOrdinal],[NameValue],NULL,NULL,NULL,[IsValid]
        FROM [monitor].[TVF_ParseSqlNameList](@ObjectNames)
        UNION ALL
        SELECT 'INDEX',[ItemOrdinal],[NameValue],NULL,NULL,NULL,[IsValid]
        FROM [monitor].[TVF_ParseSqlNameList](@IndexNames)
        UNION ALL
        SELECT 'STATISTICS',[ItemOrdinal],[NameValue],NULL,NULL,NULL,[IsValid]
        FROM [monitor].[TVF_ParseSqlNameList](@StatisticsNames)
        UNION ALL
        SELECT 'COLUMN',[ItemOrdinal],[NameValue],NULL,NULL,NULL,[IsValid]
        FROM [monitor].[TVF_ParseSqlNameList](@ColumnNames);

        INSERT [#PrepareNameFilters_Work]
        ([FilterType],[ItemOrdinal],[NameValue],[DatabaseName],[SchemaName],[ObjectName],[IsValid])
        SELECT 'FULL_OBJECT',[ItemOrdinal],NULL,[DatabaseName],[SchemaName],[ObjectName],[IsValid]
        FROM [monitor].[TVF_ParseFullObjectNameList](@FullObjectNames);
    END TRY
    BEGIN CATCH
        SET @StatusCode = CASE WHEN ERROR_NUMBER()=1222 THEN 'TIMEOUT'
                               WHEN ERROR_NUMBER() IN(229,262,297,300,371,916) THEN 'DENIED_PERMISSION'
                               ELSE 'ERROR_HANDLED' END;
        SET @ErrorMessage = ERROR_MESSAGE();
        RETURN;
    END CATCH;

    IF EXISTS(SELECT 1 FROM [#PrepareNameFilters_Work] WHERE [IsValid]=0)
    BEGIN
        SET @StatusCode = 'INVALID_PARAMETER';
        SET @ErrorMessage = N'Mindestens eine Namensliste ist syntaktisch ungültig.';
        RETURN;
    END;

    DECLARE @HasDuplicates bit=0;
    SELECT @HasDuplicates=CONVERT(bit,CASE WHEN EXISTS
    (
        SELECT 1 FROM [#PrepareNameFilters_Work] WHERE [IsValid]=1
        GROUP BY [FilterType],
                 [NameValue] COLLATE SQL_Latin1_General_CP1_CS_AS,
                 [DatabaseName] COLLATE SQL_Latin1_General_CP1_CS_AS,
                 [SchemaName] COLLATE SQL_Latin1_General_CP1_CS_AS,
                 [ObjectName] COLLATE SQL_Latin1_General_CP1_CS_AS
        HAVING COUNT(*) > 1
    ) THEN 1 ELSE 0 END);

    IF @HasDuplicates=1
    BEGIN
        SET @StatusCode = 'INVALID_PARAMETER';
        SET @ErrorMessage = N'Eine Namensliste enthält case-sensitiv doppelte Werte.';
        RETURN;
    END;

    SET @Sql=N'INSERT '+@FilterTableQuoted+N'
([FilterType],[ItemOrdinal],[NameValue],[DatabaseName],[SchemaName],[ObjectName])
SELECT [FilterType],[ItemOrdinal],[NameValue],[DatabaseName],[SchemaName],[ObjectName]
FROM [#PrepareNameFilters_Work]
WHERE [IsValid]=1;';
    EXEC [sys].[sp_executesql] @Sql;
END;
GO
-- END SOURCE: Code/01_Common/084_USP_PrepareNameFilters.sql

-- BEGIN SOURCE: Code/01_Common/085_TVF_ParseBigintList.sql
/*
===============================================================================
Objekt       : monitor.TVF_ParseBigintList
Version      : 1.1.0
Stand        : 2026-07-18
Typ          : Inline Table-valued Function
Zweck        : Validiert eine mit Pipe, Beistrich oder Strichpunkt getrennte
               Liste ganzzahliger bigint-Werte. Die Trennzeichen dürfen gemischt
               verwendet werden. Diese Funktion ist für Session-, Query-,
               Index- und andere numerische ID-Listen vorgesehen und verwendet
               bewusst keinen Identifier-Parser.
SQL-Version  : SQL Server 2019 oder neuer.
Beispiele    : SELECT * FROM monitor.TVF_ParseBigintList(N'57|61');
               SELECT * FROM monitor.TVF_ParseBigintList(N'57, 61;72');
Aenderungen  : 1.1.0 - Beistrich und Strichpunkt als weitere Trennzeichen.
===============================================================================
*/
CREATE OR ALTER FUNCTION [monitor].[TVF_ParseBigintList]
(
    @List nvarchar(max)
)
RETURNS TABLE
AS
RETURN
(
    SELECT
          [l].[ItemOrdinal]
        , [l].[ItemText]
        , [NumberValue] = TRY_CONVERT(bigint, LTRIM(RTRIM([l].[ItemText])))
        , [IsValid] = CONVERT(bit,
              CASE WHEN [l].[IsValid] = 1
                     AND TRY_CONVERT(bigint, LTRIM(RTRIM([l].[ItemText]))) IS NOT NULL
                   THEN 1 ELSE 0 END)
        , [ErrorCode] = CONVERT(varchar(40),
              CASE WHEN [l].[IsValid] = 0 THEN [l].[ErrorCode]
                   WHEN TRY_CONVERT(bigint, LTRIM(RTRIM([l].[ItemText]))) IS NULL
                   THEN 'INVALID_BIGINT' END)
        , [ErrorMessage] = CONVERT(nvarchar(4000),
              CASE WHEN [l].[IsValid] = 0 THEN [l].[ErrorMessage]
                   WHEN TRY_CONVERT(bigint, LTRIM(RTRIM([l].[ItemText]))) IS NULL
                   THEN N'Das Listenelement ist keine gültige bigint-Ganzzahl.' END)
    FROM [monitor].[TVF_ParsePipeList]
         (TRANSLATE(@List, N',;', N'||')) AS [l]
);
GO
-- END SOURCE: Code/01_Common/085_TVF_ParseBigintList.sql

-- BEGIN SOURCE: Code/01_Common/086_TVF_ParseStringList.sql
/*
===============================================================================
Objekt       : monitor.TVF_ParseStringList
Version      : 1.0.0
Stand        : 2026-07-15
Typ          : Inline Table-valued Function
Zweck        : Liefert aus einer bracket-aware Pipe-Liste allgemeine Textwerte.
               Ein Punkt besitzt hier keine Sonderbedeutung. Äußere Brackets
               werden entfernt; ]] wird zu ].
Beispiele    : SELECT * FROM monitor.TVF_ParseStringList(
                   N'[Microsoft SQL Server Management Studio]|Sample.Loader');
===============================================================================
*/
CREATE OR ALTER FUNCTION [monitor].[TVF_ParseStringList]
(
    @List nvarchar(max)
)
RETURNS TABLE
AS
RETURN
(
    SELECT
          [l].[ItemOrdinal]
        , [l].[ItemText]
        , [StringValue] = CONVERT
          (
              nvarchar(4000),
              CASE WHEN [l].[IsBracketQuoted] = 1
                   THEN REPLACE(SUBSTRING([l].[ItemText], 2, LEN([l].[ItemText]) - 2), N']]', N']')
                   ELSE [l].[ItemText]
              END
          ) COLLATE SQL_Latin1_General_CP1_CS_AS
        , [IsValid] = CONVERT
          (
              bit,
              CASE WHEN [l].[IsValid] = 1
                      AND NULLIF
                          (
                              CASE WHEN [l].[IsBracketQuoted] = 1
                                   THEN REPLACE(SUBSTRING([l].[ItemText], 2, LEN([l].[ItemText]) - 2), N']]', N']')
                                   ELSE [l].[ItemText]
                              END,
                              N''
                          ) IS NOT NULL
                   THEN 1 ELSE 0 END
          )
        , [ErrorCode] = CONVERT
          (
              varchar(40),
              CASE WHEN [l].[IsValid] = 0 THEN [l].[ErrorCode]
                   WHEN NULLIF
                        (
                            CASE WHEN [l].[IsBracketQuoted] = 1
                                 THEN REPLACE(SUBSTRING([l].[ItemText], 2, LEN([l].[ItemText]) - 2), N']]', N']')
                                 ELSE [l].[ItemText]
                            END,
                            N''
                        ) IS NULL THEN 'EMPTY_VALUE'
              END
          )
        , [ErrorMessage] = CONVERT
          (
              nvarchar(4000),
              CASE WHEN [l].[IsValid] = 0 THEN [l].[ErrorMessage]
                   WHEN NULLIF
                        (
                            CASE WHEN [l].[IsBracketQuoted] = 1
                                 THEN REPLACE(SUBSTRING([l].[ItemText], 2, LEN([l].[ItemText]) - 2), N']]', N']')
                                 ELSE [l].[ItemText]
                            END,
                            N''
                        ) IS NULL THEN N'Der Listenwert darf nicht leer sein.'
              END
          )
    FROM [monitor].[TVF_ParsePipeList](@List) AS [l]
);
GO
-- END SOURCE: Code/01_Common/086_TVF_ParseStringList.sql

-- BEGIN SOURCE: Code/01_Common/086a_TVF_ParseBlockingResource.sql
/*
===============================================================================
Objekt       : monitor.TVF_ParseBlockingResource
Version      : 1.0.0
Stand        : 2026-07-20
Typ          : Multi-statement Table-valued Function
Zweck        : Zerlegt die von Requests und Waiting Tasks gelieferten
               Blocking-Ressourcen ohne Katalog- oder DMV-Zugriff. Die Funktion
               liefert ausschließlich syntaktische IDs und bewahrt den Rohwert.
SQL-Version  : SQL Server 2019 oder neuer.
Eigenlast    : Sehr gering; maximal vier numerische Bestandteile werden gelesen.
Hinweis      : Namen werden bewusst erst vom aufrufenden Modul für die bereits
               begrenzte und deduplizierte Kandidatenmenge aufgelöst.
===============================================================================
*/
CREATE OR ALTER FUNCTION [monitor].[TVF_ParseBlockingResource]
(
    @WaitResource nvarchar(3072)
)
RETURNS @Result TABLE
(
      [RawResource]       nvarchar(3072) NULL
    , [ResourceType]      nvarchar(60)   NULL
    , [FormatCode]        varchar(40)    NOT NULL
    , [DatabaseId]        int            NULL
    , [EntityId]          bigint         NULL
    , [SubEntityId]       bigint         NULL
    , [FileId]            int            NULL
    , [PageId]            bigint         NULL
    , [RowId]             int            NULL
    , [MetadataSubtype]   nvarchar(60)   NULL
    , [ResourceQualifier] nvarchar(512)  NULL
    , [ParseStatus]       varchar(40)    NOT NULL
)
AS
BEGIN
    DECLARE @Raw nvarchar(3072) = NULLIF(LTRIM(RTRIM(@WaitResource)), N'');

    IF @Raw IS NULL
    BEGIN
        INSERT @Result ([RawResource], [FormatCode], [ParseStatus])
        VALUES (@WaitResource, 'EMPTY', 'EMPTY');
        RETURN;
    END;

    DECLARE @Upper nvarchar(3072) = UPPER(@Raw);
    DECLARE @Compact nvarchar(3072) = REPLACE(@Upper, N' ', N'');
    DECLARE @ResourceType nvarchar(60) = NULL;
    DECLARE @FormatCode varchar(40) = 'PREFIXED';
    DECLARE @DatabaseId int = NULL;
    DECLARE @EntityId bigint = NULL;
    DECLARE @SubEntityId bigint = NULL;
    DECLARE @FileId int = NULL;
    DECLARE @PageId bigint = NULL;
    DECLARE @RowId int = NULL;
    DECLARE @MetadataSubtype nvarchar(60) = NULL;
    DECLARE @Qualifier nvarchar(512) = NULL;
    DECLARE @ParseStatus varchar(40) = 'UNRECOGNIZED';
    DECLARE @Start int;
    DECLARE @NumericSegment nvarchar(128);
    DECLARE @NumericSegmentLength int;

    IF LEFT(@Compact, 9) = N'METADATA:'
    BEGIN
        SET @ResourceType = N'METADATA';
        SET @FormatCode = 'METADATA';
        SET @MetadataSubtype =
            CASE WHEN CHARINDEX(N'STATS(', @Compact) > 0 THEN N'STATS'
                 WHEN CHARINDEX(N'SCHEMA(', @Compact) > 0 THEN N'SCHEMA'
                 WHEN CHARINDEX(N'AUDIT(', @Compact) > 0 THEN N'AUDIT'
                 WHEN CHARINDEX(N'SECURITY_CACHE(', @Compact) > 0 THEN N'SECURITY_CACHE'
                 WHEN CHARINDEX(N'METADATA_CACHE(', @Compact) > 0 THEN N'METADATA_CACHE'
                 WHEN CHARINDEX(N'QDS_STATEMENT_STABILITY(', @Compact) > 0 THEN N'QDS_STATEMENT_STABILITY'
                 ELSE N'OTHER' END;

        SET @Start = CHARINDEX(N'DATABASE_ID=', @Compact);
        IF @Start > 0
        BEGIN
            SET @NumericSegment = SUBSTRING(@Compact, @Start + LEN(N'DATABASE_ID='), 128);
            SET @NumericSegmentLength = PATINDEX(N'%[^0-9]%', @NumericSegment + N'X') - 1;
            SET @DatabaseId = TRY_CONVERT(int, LEFT(@NumericSegment, @NumericSegmentLength));
        END;

        IF @MetadataSubtype = N'STATS'
        BEGIN
            SET @Start = CHARINDEX(N'OBJECT_ID=', @Compact);
            IF @Start > 0
            BEGIN
                SET @NumericSegment = SUBSTRING(@Compact, @Start + LEN(N'OBJECT_ID='), 128);
                SET @NumericSegmentLength = PATINDEX(N'%[^0-9]%', @NumericSegment + N'X') - 1;
                SET @EntityId = TRY_CONVERT(bigint, LEFT(@NumericSegment, @NumericSegmentLength));
            END;

            SET @Start = CHARINDEX(N'STATS_ID=', @Compact);
            IF @Start > 0
            BEGIN
                SET @NumericSegment = SUBSTRING(@Compact, @Start + LEN(N'STATS_ID='), 128);
                SET @NumericSegmentLength = PATINDEX(N'%[^0-9]%', @NumericSegment + N'X') - 1;
                SET @SubEntityId = TRY_CONVERT(bigint, LEFT(@NumericSegment, @NumericSegmentLength));
            END;
        END;
        ELSE IF @MetadataSubtype = N'SCHEMA'
        BEGIN
            SET @Start = CHARINDEX(N'SCHEMA_ID=', @Compact);
            IF @Start > 0
            BEGIN
                SET @NumericSegment = SUBSTRING(@Compact, @Start + LEN(N'SCHEMA_ID='), 128);
                SET @NumericSegmentLength = PATINDEX(N'%[^0-9]%', @NumericSegment + N'X') - 1;
                SET @EntityId = TRY_CONVERT(bigint, LEFT(@NumericSegment, @NumericSegmentLength));
            END;
        END;
        ELSE IF @MetadataSubtype = N'AUDIT'
        BEGIN
            SET @Start = CHARINDEX(N'AUDIT_ID=', @Compact);
            IF @Start > 0
            BEGIN
                SET @NumericSegment = SUBSTRING(@Compact, @Start + LEN(N'AUDIT_ID='), 128);
                SET @NumericSegmentLength = PATINDEX(N'%[^0-9]%', @NumericSegment + N'X') - 1;
                SET @EntityId = TRY_CONVERT(bigint, LEFT(@NumericSegment, @NumericSegmentLength));
            END;
        END;

        SET @Qualifier = LEFT(@Raw, 512);
        SET @ParseStatus = CASE WHEN @DatabaseId IS NULL THEN 'PARTIAL' ELSE 'PARSED' END;
    END;
    ELSE
    BEGIN
        DECLARE @Payload nvarchar(3072);
        DECLARE @FirstColon int = CHARINDEX(N':', @Raw);

        IF TRY_CONVERT(int, LEFT(@Raw, 1)) IS NOT NULL
        BEGIN
            SET @ResourceType = N'PAGE';
            SET @FormatCode = 'NUMERIC_PAGE';
            SET @Payload = @Raw;
        END;
        ELSE IF @FirstColon > 0
        BEGIN
            SET @ResourceType = LEFT(UPPER(LTRIM(RTRIM(LEFT(@Raw, @FirstColon - 1)))), 60);
            SET @Payload = LTRIM(SUBSTRING(@Raw, @FirstColon + 1, 3072));
        END;
        ELSE
        BEGIN
            DECLARE @NameEnd int = NULLIF(CHARINDEX(N' ', @Raw + N' '), 0);
            DECLARE @Paren int = NULLIF(CHARINDEX(N'(', @Raw), 0);
            IF @Paren IS NOT NULL AND (@NameEnd IS NULL OR @Paren < @NameEnd)
                SET @NameEnd = @Paren;

            SET @ResourceType = LEFT(UPPER(LEFT(@Raw, COALESCE(@NameEnd - 1, LEN(@Raw)))), 60);
            SET @FormatCode = 'NAMED_RESOURCE';
            SET @Qualifier = LEFT(@Raw, 512);
            SET @ParseStatus = 'RAW_ONLY';
        END;

        IF @Payload IS NOT NULL
        BEGIN
            DECLARE @Parts TABLE
            (
                  [Ordinal] int NOT NULL PRIMARY KEY
                , [Value] nvarchar(128) NULL
            );
            DECLARE @Ordinal int = 1;
            DECLARE @Colon int;
            DECLARE @Space int;
            DECLARE @OpenParen int;
            DECLARE @OpenBracket int;
            DECLARE @End int;

            WHILE @Ordinal <= 4 AND NULLIF(LTRIM(@Payload), N'') IS NOT NULL
            BEGIN
                SET @Payload = LTRIM(@Payload);
                SET @Colon = NULLIF(CHARINDEX(N':', @Payload), 0);
                SET @Space = NULLIF(CHARINDEX(N' ', @Payload), 0);
                SET @OpenParen = NULLIF(CHARINDEX(N'(', @Payload), 0);
                SET @OpenBracket = NULLIF(CHARINDEX(N'[', @Payload), 0);

                SELECT @End = MIN([Position])
                FROM (VALUES (@Colon), (@Space), (@OpenParen), (@OpenBracket)) AS [d]([Position])
                WHERE [Position] IS NOT NULL;

                INSERT @Parts ([Ordinal], [Value])
                VALUES
                (
                      @Ordinal
                    , NULLIF(LTRIM(RTRIM(CASE WHEN @End IS NULL THEN @Payload
                                               ELSE LEFT(@Payload, @End - 1) END)), N'')
                );

                IF @End IS NULL
                    SET @Payload = N'';
                ELSE IF @Colon = @End
                    SET @Payload = SUBSTRING(@Payload, @End + 1, 3072);
                ELSE
                BEGIN
                    SET @Qualifier = LEFT(LTRIM(SUBSTRING(@Payload, @End, 3072)), 512);
                    SET @Payload = N'';
                END;

                SET @Ordinal += 1;
            END;

            DECLARE @Part1 nvarchar(128) = (SELECT [Value] FROM @Parts WHERE [Ordinal] = 1);
            DECLARE @Part2 nvarchar(128) = (SELECT [Value] FROM @Parts WHERE [Ordinal] = 2);
            DECLARE @Part3 nvarchar(128) = (SELECT [Value] FROM @Parts WHERE [Ordinal] = 3);
            DECLARE @Part4 nvarchar(128) = (SELECT [Value] FROM @Parts WHERE [Ordinal] = 4);

            IF @ResourceType IN
               (
                   N'OBJECT', N'KEY', N'HOBT', N'OIB', N'ALLOCATION_UNIT',
                   N'DATABASE', N'FILE', N'PAGE', N'RID', N'EXTENT',
                   N'APPLICATION', N'XACT'
               )
            BEGIN
                SET @DatabaseId = TRY_CONVERT(int, @Part1);
                SET @EntityId = CASE WHEN @ResourceType IN (N'OBJECT', N'KEY', N'HOBT', N'OIB', N'ALLOCATION_UNIT')
                                     THEN TRY_CONVERT(bigint, @Part2) END;
                SET @SubEntityId = CASE WHEN @ResourceType = N'OBJECT'
                                        THEN TRY_CONVERT(bigint, @Part3) END;
                SET @FileId = CASE WHEN @ResourceType IN (N'FILE', N'PAGE', N'RID', N'EXTENT')
                                   THEN TRY_CONVERT(int, @Part2) END;
                SET @PageId = CASE WHEN @ResourceType IN (N'PAGE', N'RID', N'EXTENT')
                                   THEN TRY_CONVERT(bigint, @Part3) END;
                SET @RowId = CASE WHEN @ResourceType = N'RID'
                                  THEN TRY_CONVERT(int, @Part4) END;
                IF @ResourceType IN (N'APPLICATION', N'XACT')
                    SET @Qualifier = LEFT(LTRIM(SUBSTRING(@Raw, CHARINDEX(N':', @Raw) + 1, 3072)), 512);
                SET @ParseStatus =
                    CASE WHEN @DatabaseId IS NULL THEN 'INVALID_FORMAT'
                         WHEN @ResourceType IN (N'OBJECT', N'KEY', N'HOBT', N'OIB', N'ALLOCATION_UNIT')
                              AND @EntityId IS NULL THEN 'INVALID_FORMAT'
                         WHEN @ResourceType IN (N'PAGE', N'RID', N'EXTENT')
                              AND (@FileId IS NULL OR @PageId IS NULL) THEN 'INVALID_FORMAT'
                         WHEN @ResourceType = N'FILE' AND @FileId IS NULL THEN 'PARTIAL'
                         WHEN @ResourceType IN (N'APPLICATION', N'XACT') THEN 'PARTIAL'
                         ELSE 'PARSED' END;
            END;
            ELSE
            BEGIN
                SET @Qualifier = LEFT(COALESCE(@Qualifier, @Raw), 512);
                SET @ParseStatus = 'RAW_ONLY';
            END;
        END;
    END;

    INSERT @Result
    (
          [RawResource], [ResourceType], [FormatCode], [DatabaseId]
        , [EntityId], [SubEntityId], [FileId], [PageId], [RowId]
        , [MetadataSubtype], [ResourceQualifier], [ParseStatus]
    )
    VALUES
    (
          @Raw, @ResourceType, @FormatCode, @DatabaseId
        , @EntityId, @SubEntityId, @FileId, @PageId, @RowId
        , @MetadataSubtype, @Qualifier, @ParseStatus
    );

    RETURN;
END;
GO
-- END SOURCE: Code/01_Common/086a_TVF_ParseBlockingResource.sql

-- BEGIN SOURCE: Code/01_Common/087_TVF_StatementText.sql
/*
===============================================================================
Objekt       : monitor.TVF_StatementText
Version      : 1.0.0
Stand        : 2026-07-16
Typ          : Inline Table-valued Function
Zweck        : Ermittelt aus einem SQL-Batch und den Byte-Offsets eines Requests
               das exakt laufende Statement sowie transparente Zeichen- und
               Zeilenpositionen.
Hinweis      : statement_start_offset und statement_end_offset sind Byte-
               Positionen innerhalb eines nvarchar-Texts. NULL bedeutet, dass
               kein Statement-Offset verfügbar ist; -1 beim Ende bedeutet das
               Ende des Batches beziehungsweise persistenten Moduls.
===============================================================================
*/
CREATE OR ALTER FUNCTION [monitor].[TVF_StatementText]
(
      @BatchText                  nvarchar(max)
    , @StatementStartOffsetBytes  int
    , @StatementEndOffsetBytes    int
)
RETURNS TABLE
AS
RETURN
(
    WITH [Normalized] AS
    (
        SELECT
              [BatchText] = @BatchText
            , [BatchLengthBytes] = DATALENGTH(@BatchText)
            , [HasOffsets] = CONVERT(bit, CASE WHEN @StatementStartOffsetBytes IS NULL THEN 0 ELSE 1 END)
            , [StartOffsetBytes] =
                CASE
                    WHEN @BatchText IS NULL THEN NULL
                    WHEN @StatementStartOffsetBytes IS NULL THEN 0
                    ELSE @StatementStartOffsetBytes
                END
            , [EndOffsetBytes] =
                CASE
                    WHEN @BatchText IS NULL THEN NULL
                    WHEN @StatementEndOffsetBytes IS NULL OR @StatementEndOffsetBytes = -1
                        THEN DATALENGTH(@BatchText)
                    ELSE @StatementEndOffsetBytes
                END
    ),
    [Validated] AS
    (
        SELECT
              [BatchText]
            , [BatchLengthBytes]
            , [HasOffsets]
            , [StartOffsetBytes]
            , [EndOffsetBytes]
            , [IsOffsetValid] = CONVERT
              (
                  bit,
                  CASE
                      WHEN [BatchText] IS NULL THEN 0
                      WHEN [StartOffsetBytes] IS NULL OR [EndOffsetBytes] IS NULL THEN 0
                      WHEN [StartOffsetBytes] < 0 OR [EndOffsetBytes] < 0 THEN 0
                      WHEN [StartOffsetBytes] > [EndOffsetBytes] THEN 0
                      WHEN [StartOffsetBytes] > [BatchLengthBytes] THEN 0
                      WHEN [EndOffsetBytes] > [BatchLengthBytes] THEN 0
                      WHEN [StartOffsetBytes] % 2 <> 0 OR [EndOffsetBytes] % 2 <> 0 THEN 0
                      ELSE 1
                  END
              )
        FROM [Normalized]
    ),
    [Extracted] AS
    (
        SELECT
              [BatchText]
            , [BatchLengthBytes]
            , [HasOffsets]
            , [StartOffsetBytes]
            , [EndOffsetBytes]
            , [IsOffsetValid]
            , [StatementText] =
                CASE
                    WHEN [BatchText] IS NULL THEN NULL
                    WHEN [IsOffsetValid] = 0 THEN NULL
                    ELSE SUBSTRING
                    (
                          [BatchText]
                        , ([StartOffsetBytes] / 2) + 1
                        , (([EndOffsetBytes] - [StartOffsetBytes]) / 2) + 1
                    )
                END
        FROM [Validated]
    ),
    [Measured] AS
    (
        SELECT
              [BatchText]
            , [BatchLengthBytes]
            , [HasOffsets]
            , [StartOffsetBytes]
            , [EndOffsetBytes]
            , [IsOffsetValid]
            , [StatementText]
            , [StatementLengthBytes] = DATALENGTH([StatementText])
            , [StatementStartCharacter] =
                CASE WHEN [IsOffsetValid] = 1 THEN ([StartOffsetBytes] / 2) + 1 END
            , [StatementStartLine] =
                CASE
                    WHEN [IsOffsetValid] = 0 THEN NULL
                    ELSE 1
                       + LEN(LEFT([BatchText], [StartOffsetBytes] / 2))
                       - LEN(REPLACE(LEFT([BatchText], [StartOffsetBytes] / 2), NCHAR(10), N''))
                END
        FROM [Extracted]
    )
    SELECT
          [HasStatementOffsets] = [HasOffsets]
        , [IsStatementOffsetValid] = [IsOffsetValid]
        , [StatementStartOffsetBytes] = CASE WHEN [HasOffsets] = 1 THEN [StartOffsetBytes] END
        , [StatementEndOffsetBytes] =
            CASE
                WHEN [HasOffsets] = 0 THEN NULL
                WHEN @StatementEndOffsetBytes IS NULL OR @StatementEndOffsetBytes = -1 THEN -1
                ELSE [EndOffsetBytes]
            END
        , [StatementStartCharacter]
        , [StatementEndCharacter] =
            CASE
                WHEN [StatementLengthBytes] IS NULL OR [StatementLengthBytes] = 0 THEN NULL
                ELSE [StatementStartCharacter] + ([StatementLengthBytes] / 2) - 1
            END
        , [StatementStartLine]
        , [StatementEndLine] =
            CASE
                WHEN [StatementText] IS NULL THEN NULL
                ELSE [StatementStartLine]
                   + LEN([StatementText])
                   - LEN(REPLACE([StatementText], NCHAR(10), N''))
            END
        , [StatementCharacterCount] = CASE WHEN [StatementLengthBytes] IS NULL THEN NULL ELSE [StatementLengthBytes] / 2 END
        , [BatchCharacterCount] = CASE WHEN [BatchLengthBytes] IS NULL THEN NULL ELSE [BatchLengthBytes] / 2 END
        , [StatementText]
    FROM [Measured]
);
GO
-- END SOURCE: Code/01_Common/087_TVF_StatementText.sql

-- BEGIN SOURCE: Code/01_Common/087a_ToolBackgroundQueryPattern.sql
/*
===============================================================================
Objekt       : monitor.ToolBackgroundQueryPattern
Version      : 1.0.0
Stand        : 2026-07-21
Typ          : Steuertabelle
Zweck        : Stellt erweiterbare LIKE-Muster zur diagnostischen Klassifikation
               von Tool-Hintergrundabfragen anhand des clientseitigen
               program_name bereit.
Vertrag      : Kein Sicherheitsmerkmal. Höhere Priority gewinnt; bei gleicher
               Priority entscheidet RuleCode deterministisch.
===============================================================================
*/
IF NOT EXISTS
(
    SELECT 1
    FROM [sys].[tables] AS [t] WITH (NOLOCK)
    JOIN [sys].[schemas] AS [s] WITH (NOLOCK)
      ON [s].[schema_id] = [t].[schema_id]
    WHERE [s].[name] = N'monitor'
      AND [t].[name] = N'ToolBackgroundQueryPattern'
)
BEGIN
    CREATE TABLE [monitor].[ToolBackgroundQueryPattern]
    (
          [RuleCode] varchar(64) NOT NULL
        , [Priority] smallint NOT NULL
        , [IsEnabled] bit NOT NULL
            CONSTRAINT [DF_ToolBackgroundQueryPattern_IsEnabled] DEFAULT (1)
        , [ProgramNameLikePattern] nvarchar(256) COLLATE Latin1_General_100_CI_AS NOT NULL
        , [ToolBackgroundCategory] varchar(40) NOT NULL
        , [ToolBackgroundDetection] varchar(40) NOT NULL
        , [ToolBackgroundConfidence] varchar(16) NOT NULL
        , [SourceUrl] nvarchar(1000) NULL
        , [SourceNotes] nvarchar(1000) NULL
        , [IsFrameworkDefault] bit NOT NULL
            CONSTRAINT [DF_ToolBackgroundQueryPattern_IsFrameworkDefault] DEFAULT (0)
        , [LastVerifiedUtc] datetime2(0) NOT NULL
            CONSTRAINT [DF_ToolBackgroundQueryPattern_LastVerifiedUtc] DEFAULT (SYSUTCDATETIME())
        , CONSTRAINT [PK_ToolBackgroundQueryPattern]
            PRIMARY KEY CLUSTERED ([RuleCode])
        , CONSTRAINT [CK_ToolBackgroundQueryPattern_Priority]
            CHECK ([Priority] BETWEEN 1 AND 32767)
        , CONSTRAINT [CK_ToolBackgroundQueryPattern_Confidence]
            CHECK ([ToolBackgroundConfidence] IN ('HIGH','MEDIUM','LOW'))
    );
END;
GO
-- END SOURCE: Code/01_Common/087a_ToolBackgroundQueryPattern.sql

-- BEGIN SOURCE: Code/01_Common/087b_ToolBackgroundQueryPattern_Seed.sql
/* Framework-Seed. Lokale Regeln mit IsFrameworkDefault=0 bleiben erhalten. */
DECLARE @Seed TABLE
(
      [RuleCode] varchar(64) NOT NULL
    , [Priority] smallint NOT NULL
    , [ProgramNameLikePattern] nvarchar(256) COLLATE Latin1_General_100_CI_AS NOT NULL
    , [ToolBackgroundCategory] varchar(40) NOT NULL
    , [ToolBackgroundDetection] varchar(40) NOT NULL
    , [ToolBackgroundConfidence] varchar(16) NOT NULL
    , [SourceUrl] nvarchar(1000) NULL
    , [SourceNotes] nvarchar(1000) NULL
);

INSERT @Seed
(
      [RuleCode], [Priority], [ProgramNameLikePattern]
    , [ToolBackgroundCategory], [ToolBackgroundDetection]
    , [ToolBackgroundConfidence], [SourceUrl], [SourceNotes]
)
VALUES
(
      'SSMS_GITHUB_COPILOT', 1000
    , N'Microsoft SQL Server Management Studio - GitHub Copilot'
    , 'SSMS_GITHUB_COPILOT', 'DOCUMENTED_CLIENT_APP_NAME', 'HIGH'
    , N'https://learn.microsoft.com/en-us/ssms/github-copilot/troubleshoot'
    , N'Der Client-App-Name ist in der Microsoft-Problembehandlung dokumentiert.'
),
(
      'SSMS_COPILOT_COMPLETIONS', 1000
    , N'Microsoft SQL Server Management Studio - Copilot Completions'
    , 'SSMS_COPILOT_COMPLETIONS', 'DOCUMENTED_CLIENT_APP_NAME', 'HIGH'
    , N'https://learn.microsoft.com/en-us/ssms/github-copilot/troubleshoot'
    , N'Der Client-App-Name ist in der Microsoft-Problembehandlung dokumentiert.'
),
(
      'SSMS_OBJECT_EXPLORER', 800
    , N'Microsoft SQL Server Management Studio - Object Explorer%'
    , 'SSMS_OBJECT_EXPLORER', 'PROGRAM_NAME_HEURISTIC', 'MEDIUM'
    , N'https://learn.microsoft.com/en-us/ssms/object/open-and-configure-object-explorer'
    , N'Object Explorer ist dokumentiert; das program_name-Muster bleibt eine versionsabhängige Heuristik.'
),
(
      'RED_GATE_SQL_PROMPT', 700
    , N'Red Gate SQL Prompt%'
    , 'REDGATE_SQL_PROMPT', 'PROGRAM_NAME_HEURISTIC', 'MEDIUM'
    , N'https://documentation.red-gate.com/sp11/managing-sql-prompt-behavior/managing-connections-and-memory'
    , N'SQL Prompt und seine Verbindungen sind dokumentiert; der konkrete program_name ist kein stabiler Herstellervertrag.'
),
(
      'REDGATE_SQL_PROMPT', 700
    , N'Redgate SQL Prompt%'
    , 'REDGATE_SQL_PROMPT', 'PROGRAM_NAME_HEURISTIC', 'MEDIUM'
    , N'https://documentation.red-gate.com/sp11/managing-sql-prompt-behavior/managing-connections-and-memory'
    , N'Alternative beobachtete Herstellerschreibweise.'
),
(
      'REDGATE_DOT_SQLPROMPT', 700
    , N'Redgate.SQLPrompt%'
    , 'REDGATE_SQL_PROMPT', 'PROGRAM_NAME_HEURISTIC', 'MEDIUM'
    , N'https://documentation.red-gate.com/sp11/managing-sql-prompt-behavior/managing-connections-and-memory'
    , N'Alternative beobachtete Herstellerschreibweise.'
);

UPDATE [target]
SET
      [Priority] = [source].[Priority]
    , [ProgramNameLikePattern] = [source].[ProgramNameLikePattern]
    , [ToolBackgroundCategory] = [source].[ToolBackgroundCategory]
    , [ToolBackgroundDetection] = [source].[ToolBackgroundDetection]
    , [ToolBackgroundConfidence] = [source].[ToolBackgroundConfidence]
    , [SourceUrl] = [source].[SourceUrl]
    , [SourceNotes] = [source].[SourceNotes]
    , [IsFrameworkDefault] = 1
    , [LastVerifiedUtc] = SYSUTCDATETIME()
FROM [monitor].[ToolBackgroundQueryPattern] AS [target]
JOIN @Seed AS [source]
  ON [source].[RuleCode] = [target].[RuleCode]
WHERE [target].[IsFrameworkDefault] = 1;

INSERT [monitor].[ToolBackgroundQueryPattern]
(
      [RuleCode], [Priority], [IsEnabled], [ProgramNameLikePattern]
    , [ToolBackgroundCategory], [ToolBackgroundDetection]
    , [ToolBackgroundConfidence], [SourceUrl], [SourceNotes]
    , [IsFrameworkDefault]
)
SELECT
      [source].[RuleCode], [source].[Priority], 1, [source].[ProgramNameLikePattern]
    , [source].[ToolBackgroundCategory], [source].[ToolBackgroundDetection]
    , [source].[ToolBackgroundConfidence], [source].[SourceUrl], [source].[SourceNotes]
    , 1
FROM @Seed AS [source]
WHERE NOT EXISTS
(
    SELECT 1
    FROM [monitor].[ToolBackgroundQueryPattern] AS [target]
    WHERE [target].[RuleCode] = [source].[RuleCode]
);
GO
-- END SOURCE: Code/01_Common/087b_ToolBackgroundQueryPattern_Seed.sql

-- BEGIN SOURCE: Code/01_Common/087c_TVF_ToolBackgroundQueryInfo.sql
/*
===============================================================================
Objekt       : monitor.TVF_ToolBackgroundQueryInfo
Version      : 1.1.0
Stand        : 2026-07-21
Typ          : Inline Table-valued Function
Zweck        : Wertet aktivierte LIKE-Regeln aus ToolBackgroundQueryPattern aus.
Vertrag      : Heuristik für die Diagnoseausgabe, kein Sicherheitsmerkmal.
Eigenlast    : Kein DMV-, SQL-Text- oder fremder Datenbankzugriff.
===============================================================================
*/
CREATE OR ALTER FUNCTION [monitor].[TVF_ToolBackgroundQueryInfo]
(
    @ProgramName nvarchar(128)
)
RETURNS TABLE
AS
RETURN
(
    SELECT
          [IsToolBackgroundQuery] = CONVERT
            (
                bit,
                CASE WHEN [rule].[RuleCode] IS NULL THEN 0 ELSE 1 END
            )
        , [ToolBackgroundRuleCode] = [rule].[RuleCode]
        , [rule].[ToolBackgroundCategory]
        , [rule].[ToolBackgroundDetection]
        , [rule].[ToolBackgroundConfidence]
    FROM (VALUES (CONVERT(bit, 1))) AS [seed]([Value])
    OUTER APPLY
    (
        SELECT TOP (1)
              [p].[RuleCode]
            , [p].[ToolBackgroundCategory]
            , [p].[ToolBackgroundDetection]
            , [p].[ToolBackgroundConfidence]
        FROM [monitor].[ToolBackgroundQueryPattern] AS [p] WITH (NOLOCK)
        WHERE [p].[IsEnabled] = 1
          AND @ProgramName COLLATE Latin1_General_100_CI_AS
              LIKE [p].[ProgramNameLikePattern] COLLATE Latin1_General_100_CI_AS
        ORDER BY [p].[Priority] DESC, [p].[RuleCode]
    ) AS [rule]
);
GO
-- END SOURCE: Code/01_Common/087c_TVF_ToolBackgroundQueryInfo.sql

-- BEGIN SOURCE: Code/01_Common/087d_TVF_ProjectUnicodeText.sql
/*
===============================================================================
Objekt       : monitor.TVF_ProjectUnicodeText
Version      : 1.0.0
Stand        : 2026-07-21
Typ          : Inline Table-Valued Function
Zweck        : Projiziert einen bereits materialisierten Unicode-MAX-Wert mit
               messbarer, aufhebbarer und Surrogate-sicherer Begrenzung.
Semantik     : NULL oder 0 als Grenze bedeutet unbegrenzt; negative Grenzen
               validiert die aufrufende Procedure vor Verwendung der Funktion.
Unicode      : Latin1_General_100_CI_AS_SC zählt und schneidet UTF-16-
               Surrogate-Paare als ein Zeichen. Ein angehängtes Nicht-Leerzeichen
               sorgt dafür, dass abschließende Leerzeichen mitgezählt werden.
Nebenwirkung : Keine. Die Funktion liest keine System- oder Benutzerdaten.
===============================================================================
*/
CREATE OR ALTER FUNCTION [monitor].[TVF_ProjectUnicodeText]
(
      @Value         nvarchar(max)
    , @MaxCharacters int
)
RETURNS TABLE
AS
RETURN
(
    SELECT
          [OriginalCharacters] =
              CASE WHEN @Value IS NULL THEN CONVERT(bigint,NULL)
                   ELSE [m].[CharacterCount] END
        , [OriginalBytes] = CONVERT(bigint,DATALENGTH(@Value))
        , [IsTruncated] = CONVERT
          (
              bit,
              CASE WHEN @Value IS NOT NULL
                         AND @MaxCharacters IS NOT NULL
                         AND @MaxCharacters > 0
                         AND [m].[CharacterCount] > @MaxCharacters
                   THEN 1 ELSE 0 END
          )
        , [ProjectedValue] = CONVERT
          (
              nvarchar(max),
              CASE WHEN @Value IS NULL THEN NULL
                   WHEN @MaxCharacters IS NULL OR @MaxCharacters = 0 THEN @Value
                   WHEN [m].[CharacterCount] <= @MaxCharacters THEN @Value
                   ELSE LEFT(@Value COLLATE Latin1_General_100_CI_AS_SC,@MaxCharacters)
              END
          )
    FROM
    (
        SELECT [CharacterCount] = CONVERT
        (
            bigint,
            LEN((@Value + NCHAR(1)) COLLATE Latin1_General_100_CI_AS_SC) - 1
        )
    ) AS [m]
);
GO
-- END SOURCE: Code/01_Common/087d_TVF_ProjectUnicodeText.sql

-- BEGIN SOURCE: Code/01_Common/087e_TVF_ClassifyErrorLogEvent.sql
/* Reine Klassifizierung; liest und persistiert selbst keine Errorlogdaten. */
CREATE OR ALTER FUNCTION [monitor].[TVF_ClassifyErrorLogEvent]
(
      @ProductName varchar(32)
    , @RuleCategory varchar(80)
    , @MessageText nvarchar(max)
)
RETURNS TABLE
AS
RETURN
(
    SELECT CONVERT(varchar(80),
        CASE
          WHEN @ProductName='SQL_AGENT' THEN 'AGENT_ERROR'
          WHEN @MessageText COLLATE SQL_Latin1_General_CP1_CI_AS LIKE N'%Error: 823%'
            OR @MessageText COLLATE SQL_Latin1_General_CP1_CI_AS LIKE N'%Error: 824%'
            OR @MessageText COLLATE SQL_Latin1_General_CP1_CI_AS LIKE N'%Error: 825%' THEN 'IO_ERROR'
          WHEN @MessageText COLLATE SQL_Latin1_General_CP1_CI_AS LIKE N'%taking longer than 15 seconds%' THEN 'LONG_IO'
          WHEN (@MessageText COLLATE SQL_Latin1_General_CP1_CI_AS LIKE N'%Backup%'
             OR @MessageText COLLATE SQL_Latin1_General_CP1_CI_AS LIKE N'%Restore%')
           AND (@MessageText COLLATE SQL_Latin1_General_CP1_CI_AS LIKE N'%fail%'
             OR @MessageText COLLATE SQL_Latin1_General_CP1_CI_AS LIKE N'%error%') THEN 'BACKUP_RESTORE'
          WHEN @MessageText COLLATE SQL_Latin1_General_CP1_CI_AS LIKE N'%cachestore flush%'
            OR @MessageText COLLATE SQL_Latin1_General_CP1_CI_AS LIKE N'%FlushCache%' THEN 'CACHE_FLUSH'
          WHEN @MessageText COLLATE SQL_Latin1_General_CP1_CI_AS LIKE N'%Autogrow%' THEN 'AUTOGROWTH'
          WHEN @MessageText COLLATE SQL_Latin1_General_CP1_CI_AS LIKE N'%Stack Dump%'
            OR @MessageText COLLATE SQL_Latin1_General_CP1_CI_AS LIKE N'%Assertion%' THEN 'DUMP_ASSERTION'
          WHEN @MessageText COLLATE SQL_Latin1_General_CP1_CI_AS LIKE N'%Login failed%'
            OR @MessageText COLLATE SQL_Latin1_General_CP1_CI_AS LIKE N'%17830%' THEN 'LOGIN_CONNECTIVITY'
          WHEN @MessageText COLLATE SQL_Latin1_General_CP1_CI_AS LIKE N'%Log Shipping%' THEN 'LOG_SHIPPING'
          WHEN @MessageText COLLATE SQL_Latin1_General_CP1_CI_AS LIKE N'%Replication%' THEN 'REPLICATION'
          ELSE COALESCE(@RuleCategory,'UNCLASSIFIED')
        END) AS [Category]
);
GO
-- END SOURCE: Code/01_Common/087e_TVF_ClassifyErrorLogEvent.sql

-- BEGIN SOURCE: Code/01_Common/098_USP_InternalProjectUnicodeTextColumn.sql
/*
===============================================================================
Objekt       : monitor.InternalProjectUnicodeTextColumn
Version      : 1.0.0
Stand        : 2026-07-21
Typ          : Interne Stored Procedure
Zweck        : Projiziert eine bereits materialisierte nvarchar(max)-Spalte
               Unicode-sicher und befüllt deren Längen-/Kürzungsmetadaten.
Grenze       : Liest ausschließlich die übergebene lokale Temp-Tabelle; kein
               erneuter Zugriff auf die fachliche Systemquelle.
===============================================================================
*/
CREATE OR ALTER PROCEDURE [monitor].[InternalProjectUnicodeTextColumn]
      @SourceTable               sysname
    , @TextColumn                sysname
    , @CharactersColumn          sysname
    , @BytesColumn               sysname
    , @IsTruncatedColumn         sysname
    , @MaxCharacters             int
    , @TruncatedValueCount       bigint OUTPUT
    , @LargestRequiredCharacters bigint OUTPUT
AS
BEGIN
    SET NOCOUNT ON;
    SET LOCK_TIMEOUT 0;

    IF @SourceTable IS NULL OR LEFT(@SourceTable,1)<>N'#'
       OR LEFT(@SourceTable,2)=N'##'
       OR @TextColumn IS NULL OR @CharactersColumn IS NULL
       OR @BytesColumn IS NULL OR @IsTruncatedColumn IS NULL
       OR @MaxCharacters<0
        THROW 51021,N'InternalProjectUnicodeTextColumn benötigt eine lokale Temp-Tabelle, gültige Spalten und einen nichtnegativen Grenzwert.',1;

    DECLARE @Sql nvarchar(max)=N'
UPDATE [source]
SET '+QUOTENAME(@CharactersColumn)+N'=[projection].[OriginalCharacters],
    '+QUOTENAME(@BytesColumn)+N'=[projection].[OriginalBytes],
    '+QUOTENAME(@IsTruncatedColumn)+N'=[projection].[IsTruncated],
    '+QUOTENAME(@TextColumn)+N'=[projection].[ProjectedValue]
FROM '+QUOTENAME(@SourceTable)+N' AS [source]
CROSS APPLY [monitor].[TVF_ProjectUnicodeText]([source].'+QUOTENAME(@TextColumn)+N',@Limit) AS [projection];

SELECT @Count=COUNT_BIG(*),@Largest=MAX('+QUOTENAME(@CharactersColumn)+N')
FROM '+QUOTENAME(@SourceTable)+N'
WHERE '+QUOTENAME(@IsTruncatedColumn)+N'=1;';

    SET @TruncatedValueCount=0;
    SET @LargestRequiredCharacters=NULL;
    EXEC [sys].[sp_executesql]
          @Sql
        , N'@Limit int,@Count bigint OUTPUT,@Largest bigint OUTPUT'
        , @Limit=@MaxCharacters
        , @Count=@TruncatedValueCount OUTPUT
        , @Largest=@LargestRequiredCharacters OUTPUT;
END;
GO
-- END SOURCE: Code/01_Common/098_USP_InternalProjectUnicodeTextColumn.sql

-- BEGIN SOURCE: Code/01_Common/088_TVF_InterpretPerformanceCounter.sql
/*
===============================================================================
Objekt       : monitor.TVF_InterpretPerformanceCounter
Version      : 1.0.0
Stand        : 2026-07-18
Zweck        : Interpretiert ein Performance-Counter-Paar deterministisch und
               ohne Seiteneffekte einschließlich Reset- und
               Basiscountervertrag.
Grenzen      : Keine DMV-Abfrage, keine Persistenz und keine Alarmgrenzen.
===============================================================================
*/
CREATE OR ALTER FUNCTION [monitor].[TVF_InterpretPerformanceCounter]
(
      @CounterType      int
    , @BeforeValue      bigint
    , @AfterValue       bigint
    , @BaseBeforeValue  bigint
    , @BaseAfterValue   bigint
    , @SampleSeconds    decimal(19,6)
)
RETURNS TABLE
WITH SCHEMABINDING
AS
RETURN
(
    SELECT
          CASE
              WHEN @CounterType = 65792 THEN 'RAW_SNAPSHOT'
              WHEN @CounterType IN (272696320, 272696576) THEN 'RATE_PER_SECOND'
              WHEN @CounterType = 537003264 THEN 'FRACTION_DELTA_PERCENT'
              WHEN @CounterType = 1073874176 THEN 'AVERAGE_DELTA_RATIO'
              ELSE 'RAW_UNINTERPRETED'
          END AS [Interpretation]
        , CONVERT(decimal(38,6),
          CASE
              WHEN @CounterType = 65792
                  THEN CONVERT(decimal(38,6), @AfterValue)
              WHEN @CounterType IN (272696320, 272696576)
               AND @SampleSeconds > 0
               AND @AfterValue >= @BeforeValue
                  THEN (CONVERT(decimal(38,6), @AfterValue)
                       -CONVERT(decimal(38,6), @BeforeValue)) / NULLIF(@SampleSeconds, 0)
              WHEN @CounterType = 537003264
               AND @SampleSeconds > 0
               AND @AfterValue >= @BeforeValue
               AND @BaseAfterValue > @BaseBeforeValue
                  THEN 100.0 * (CONVERT(decimal(38,6), @AfterValue)
                               -CONVERT(decimal(38,6), @BeforeValue))
                       / NULLIF(CONVERT(decimal(38,6), @BaseAfterValue)
                               -CONVERT(decimal(38,6), @BaseBeforeValue), 0)
              WHEN @CounterType = 1073874176
               AND @SampleSeconds > 0
               AND @AfterValue >= @BeforeValue
               AND @BaseAfterValue > @BaseBeforeValue
                  THEN (CONVERT(decimal(38,6), @AfterValue)
                       -CONVERT(decimal(38,6), @BeforeValue))
                       / NULLIF(CONVERT(decimal(38,6), @BaseAfterValue)
                               -CONVERT(decimal(38,6), @BaseBeforeValue), 0)
              WHEN @CounterType IN (272696320, 272696576, 537003264, 1073874176)
                  THEN NULL
              ELSE CONVERT(decimal(38,6), @AfterValue)
          END) AS [MetricValue]
        , CASE
              WHEN @CounterType IN (272696320, 272696576) THEN 'PER_SECOND'
              WHEN @CounterType = 537003264 THEN 'PERCENT'
              WHEN @CounterType = 1073874176 THEN 'AVERAGE'
              WHEN @CounterType = 65792 THEN 'RAW_VALUE'
              ELSE 'RAW_UNINTERPRETED'
          END AS [MetricUnit]
        , CASE
              WHEN @CounterType IN (272696320, 272696576, 537003264, 1073874176)
               AND COALESCE(@SampleSeconds, 0) <= 0 THEN 'SAMPLE_REQUIRED_FOR_DELTA_METRIC'
              WHEN @CounterType IN (272696320, 272696576, 537003264, 1073874176)
               AND @AfterValue < @BeforeValue THEN 'COUNTER_RESET_DURING_SAMPLE'
              WHEN @CounterType IN (537003264, 1073874176)
               AND (@BaseBeforeValue IS NULL OR @BaseAfterValue IS NULL) THEN 'BASE_COUNTER_MISSING'
              WHEN @CounterType IN (537003264, 1073874176)
               AND @BaseAfterValue < @BaseBeforeValue THEN 'BASE_COUNTER_RESET_DURING_SAMPLE'
              WHEN @CounterType IN (537003264, 1073874176)
               AND @BaseAfterValue = @BaseBeforeValue THEN 'BASE_COUNTER_DELTA_ZERO'
              WHEN @CounterType NOT IN
                   (65792, 272696320, 272696576, 537003264, 1073874176)
                  THEN 'COUNTER_TYPE_NOT_AUTOMATICALLY_INTERPRETED'
              ELSE 'VALUE_AVAILABLE'
          END AS [FindingCode]
);
GO
-- END SOURCE: Code/01_Common/088_TVF_InterpretPerformanceCounter.sql

-- BEGIN SOURCE: Code/01_Common/089_TVF_InterpretContentionCounter.sql
/*
===============================================================================
Objekt       : monitor.TVF_InterpretContentionCounter
Zweck        : Stellt den Rechenvertrag für monotone Latch-/Spinlockzähler
               ohne Seiteneffekte bereit.
Datenschutz  : Verarbeitet ausschließlich übergebene technische Zahlenwerte.
Grenzen      : Ein fallender Wert kennzeichnet einen Reset; die betroffene
               Differenz und Rate bleiben NULL.
===============================================================================
*/
CREATE OR ALTER FUNCTION [monitor].[TVF_InterpretContentionCounter]
(
      @BeforeValue            bigint
    , @AfterValue             bigint
    , @RequestedSampleSeconds tinyint
    , @ActualSampleSeconds    decimal(19,6)
)
RETURNS TABLE
WITH SCHEMABINDING
AS
RETURN
(
    SELECT
          CASE
              WHEN @RequestedSampleSeconds=0 THEN @AfterValue
              WHEN @AfterValue>=@BeforeValue THEN @AfterValue-@BeforeValue
          END AS [CounterValue]
        , CASE
              WHEN @RequestedSampleSeconds>0 AND @AfterValue>=@BeforeValue
              THEN CONVERT(decimal(19,4),
                   1.0*(@AfterValue-@BeforeValue)/NULLIF(@ActualSampleSeconds,0))
          END AS [RatePerSecond]
        , CONVERT(bit,CASE
              WHEN @RequestedSampleSeconds>0 AND @AfterValue<@BeforeValue THEN 1
              ELSE 0
          END) AS [CounterResetDetected]
);
GO
-- END SOURCE: Code/01_Common/089_TVF_InterpretContentionCounter.sql

-- BEGIN SOURCE: Code/01_Common/090_TVF_InterpretAvailabilityDatabaseState.sql
/*
===============================================================================
Objekt       : monitor.TVF_InterpretAvailabilityDatabaseState
Version      : 1.0.0
Stand        : 2026-07-18
Typ          : Inline Table-valued Function
Zweck        : Klassifiziert den Zustand einer AG-Datenbank ohne Seiteneffekte.
Datenschutz  : Verarbeitet ausschließlich übergebene technische Status- und
               Zählerwerte; keine Namen, Texte oder Umgebungswerte.
Grenzen      : Momentaufnahme. Queue- und Lag-Grenzen sind Sichtungswerte und
               beweisen weder Ursache noch zukünftige Catch-up-Zeit.
===============================================================================
*/
CREATE OR ALTER FUNCTION [monitor].[TVF_InterpretAvailabilityDatabaseState]
(
      @IsSuspended                  bit
    , @SynchronizationHealthDesc    nvarchar(60)
    , @SynchronizationStateDesc     nvarchar(60)
    , @LogSendQueueSizeKb           bigint
    , @RedoQueueSizeKb              bigint
    , @SecondaryLagSeconds          bigint
    , @QueueWarnMb                  bigint
    , @SecondaryLagWarnSeconds      int
)
RETURNS TABLE
WITH SCHEMABINDING
AS
RETURN
(
    SELECT
          [FindingCode] = CONVERT(varchar(100),
              CASE WHEN @IsSuspended = 1 THEN 'DATA_MOVEMENT_SUSPENDED'
                   WHEN @SynchronizationHealthDesc = N'NOT_HEALTHY' THEN 'DATABASE_NOT_HEALTHY'
                   WHEN @SynchronizationStateDesc = N'NOT_SYNCHRONIZING' THEN 'DATABASE_NOT_SYNCHRONIZING'
                   WHEN CONVERT(decimal(38,0),COALESCE(@LogSendQueueSizeKb,0)) >= CONVERT(decimal(38,0),@QueueWarnMb)*1024 THEN 'LOG_SEND_QUEUE_THRESHOLD'
                   WHEN CONVERT(decimal(38,0),COALESCE(@RedoQueueSizeKb,0)) >= CONVERT(decimal(38,0),@QueueWarnMb)*1024 THEN 'REDO_QUEUE_THRESHOLD'
                   WHEN COALESCE(@SecondaryLagSeconds,0) >= @SecondaryLagWarnSeconds THEN 'SECONDARY_LAG_THRESHOLD'
                   ELSE 'DATABASE_STATE_ACCEPTABLE' END)
        , [FindingSeverity] = CONVERT(varchar(16),
              CASE WHEN @IsSuspended = 1
                         OR @SynchronizationHealthDesc = N'NOT_HEALTHY'
                         OR @SynchronizationStateDesc = N'NOT_SYNCHRONIZING' THEN 'HIGH'
                   WHEN CONVERT(decimal(38,0),COALESCE(@LogSendQueueSizeKb,0)) >= CONVERT(decimal(38,0),@QueueWarnMb)*1024
                         OR CONVERT(decimal(38,0),COALESCE(@RedoQueueSizeKb,0)) >= CONVERT(decimal(38,0),@QueueWarnMb)*1024
                         OR COALESCE(@SecondaryLagSeconds,0) >= @SecondaryLagWarnSeconds THEN 'MEDIUM'
                   ELSE 'INFO' END)
);
GO
-- END SOURCE: Code/01_Common/090_TVF_InterpretAvailabilityDatabaseState.sql

-- BEGIN SOURCE: Code/01_Common/091_TVF_InterpretAvailabilitySeedingState.sql
/*
===============================================================================
Objekt       : monitor.TVF_InterpretAvailabilitySeedingState
Version      : 1.0.0
Stand        : 2026-07-18
Typ          : Inline Table-valued Function
Zweck        : Berechnet und klassifiziert den Zustand eines physischen
               Seedings ohne Seiteneffekte.
Datenschutz  : Verarbeitet ausschließlich übergebene technische Zahlen- und
               Zeitwerte; freie Fehlermeldungen werden nicht benötigt.
Grenzen      : Fortschritt basiert auf sichtbaren Bytezählern. Kompression,
               Momentaufnahme und aktuelle Transferrate begrenzen die Aussage.
===============================================================================
*/
CREATE OR ALTER FUNCTION [monitor].[TVF_InterpretAvailabilitySeedingState]
(
      @FailureCode                   int
    , @TransferredSizeBytes          bigint
    , @DatabaseSizeBytes             bigint
    , @TransferRateBytesPerSecond    bigint
    , @EndTimeUtc                    datetime
)
RETURNS TABLE
WITH SCHEMABINDING
AS
RETURN
(
    SELECT
          [ProgressPercent] = CONVERT(decimal(9,4),
              CASE WHEN COALESCE(@DatabaseSizeBytes,0) <= 0 THEN NULL
                   WHEN COALESCE(@TransferredSizeBytes,0) <= 0 THEN 0
                   WHEN @TransferredSizeBytes >= @DatabaseSizeBytes THEN 100
                   ELSE CONVERT(decimal(38,6),@TransferredSizeBytes)*100.0
                        /NULLIF(CONVERT(decimal(38,6),@DatabaseSizeBytes),0) END)
        , [RemainingBytes] = CONVERT(bigint,
              CASE WHEN COALESCE(@DatabaseSizeBytes,0) <= COALESCE(@TransferredSizeBytes,0) THEN 0
                   ELSE @DatabaseSizeBytes-COALESCE(@TransferredSizeBytes,0) END)
        , [FindingCode] = CONVERT(varchar(100),
              CASE WHEN COALESCE(@FailureCode,0) <> 0 THEN 'SEEDING_FAILED'
                   WHEN @EndTimeUtc IS NOT NULL
                        AND COALESCE(@TransferredSizeBytes,0) >= COALESCE(@DatabaseSizeBytes,0) THEN 'SEEDING_COMPLETED'
                   WHEN @EndTimeUtc IS NULL
                        AND COALESCE(@DatabaseSizeBytes,0) > COALESCE(@TransferredSizeBytes,0)
                        AND COALESCE(@TransferRateBytesPerSecond,0) = 0 THEN 'SEEDING_NO_CURRENT_THROUGHPUT'
                   WHEN @EndTimeUtc IS NULL THEN 'SEEDING_IN_PROGRESS'
                   ELSE 'SEEDING_STATE_REVIEW' END)
        , [FindingSeverity] = CONVERT(varchar(16),
              CASE WHEN COALESCE(@FailureCode,0) <> 0 THEN 'HIGH'
                   WHEN @EndTimeUtc IS NULL
                        AND COALESCE(@DatabaseSizeBytes,0) > COALESCE(@TransferredSizeBytes,0)
                        AND COALESCE(@TransferRateBytesPerSecond,0) = 0 THEN 'MEDIUM'
                   WHEN @EndTimeUtc IS NOT NULL
                        AND COALESCE(@TransferredSizeBytes,0) < COALESCE(@DatabaseSizeBytes,0) THEN 'MEDIUM'
                   ELSE 'INFO' END)
);
GO
-- END SOURCE: Code/01_Common/091_TVF_InterpretAvailabilitySeedingState.sql

-- BEGIN SOURCE: Code/01_Common/092_TVF_InterpretAgentAlertRoute.sql
/*
===============================================================================
Objekt       : monitor.TVF_InterpretAgentAlertRoute
Version      : 1.0.0
Stand        : 2026-07-18
Typ          : Inline Table-valued Function
Zweck        : Klassifiziert die Aktion eines Agent-Alerts ohne Seiteneffekte.
Datenschutz  : Verarbeitet nur Schalter und aggregierte Anzahl; keine Operator-
               oder Empfängerdaten.
===============================================================================
*/
CREATE OR ALTER FUNCTION [monitor].[TVF_InterpretAgentAlertRoute]
(
      @IsEnabled          bit
    , @HasJobAction       bit
    , @NotificationCount  bigint
)
RETURNS TABLE
WITH SCHEMABINDING
AS
RETURN
(
    SELECT
          [FindingCode] = CONVERT(varchar(100),
              CASE WHEN @IsEnabled=1 AND COALESCE(@HasJobAction,0)=0
                         AND COALESCE(@NotificationCount,0)=0 THEN 'ENABLED_ALERT_WITHOUT_ACTION'
                   WHEN @IsEnabled=0 THEN 'ALERT_DISABLED'
                   ELSE 'ALERT_ROUTE_PRESENT' END)
        , [FindingSeverity] = CONVERT(varchar(16),
              CASE WHEN @IsEnabled=1 AND COALESCE(@HasJobAction,0)=0
                         AND COALESCE(@NotificationCount,0)=0 THEN 'HIGH'
                   ELSE 'INFO' END)
);
GO
-- END SOURCE: Code/01_Common/092_TVF_InterpretAgentAlertRoute.sql

-- BEGIN SOURCE: Code/01_Common/093_TVF_InterpretAgentJobState.sql
/*
===============================================================================
Objekt       : monitor.TVF_InterpretAgentJobState
Version      : 1.0.0
Stand        : 2026-07-18
Typ          : Inline Table-valued Function
Zweck        : Klassifiziert den letzten Jobstatus und die zugehörigen
               Zeitpläne ohne Seiteneffekte.
Datenschutz  : Verarbeitet nur technische Status-, Zeit- und Anzahlwerte; keine
               Jobschritte, Befehle oder Meldungstexte.
===============================================================================
*/
CREATE OR ALTER FUNCTION [monitor].[TVF_InterpretAgentJobState]
(
      @IsEnabled             tinyint
    , @LatestRunStatus       int
    , @LatestRunDateTime     datetime
    , @CutoffLocal           datetime
    , @ScheduleCount         bigint
    , @EnabledScheduleCount  bigint
)
RETURNS TABLE
WITH SCHEMABINDING
AS
RETURN
(
    SELECT
          [FindingCode] = CONVERT(varchar(100),
              CASE WHEN @IsEnabled=1 AND @LatestRunStatus=0
                         AND @LatestRunDateTime>=@CutoffLocal THEN 'LATEST_JOB_RUN_FAILED_IN_WINDOW'
                   WHEN @IsEnabled=1 AND COALESCE(@ScheduleCount,0)>0
                         AND COALESCE(@EnabledScheduleCount,0)=0 THEN 'ALL_ATTACHED_SCHEDULES_DISABLED'
                   WHEN @IsEnabled=1 AND COALESCE(@ScheduleCount,0)=0 THEN 'ENABLED_JOB_WITHOUT_SCHEDULE'
                   ELSE 'JOB_STATE_INFORMATIONAL' END)
        , [FindingSeverity] = CONVERT(varchar(16),
              CASE WHEN @IsEnabled=1 AND @LatestRunStatus=0
                         AND @LatestRunDateTime>=@CutoffLocal THEN 'HIGH'
                   WHEN @IsEnabled=1 AND COALESCE(@ScheduleCount,0)>0
                         AND COALESCE(@EnabledScheduleCount,0)=0 THEN 'MEDIUM'
                   ELSE 'INFO' END)
);
GO
-- END SOURCE: Code/01_Common/093_TVF_InterpretAgentJobState.sql

-- BEGIN SOURCE: Code/01_Common/094_TVF_InterpretDatabaseMailStatus.sql
/*
===============================================================================
Objekt       : monitor.TVF_InterpretDatabaseMailStatus
Version      : 1.0.0
Stand        : 2026-07-18
Typ          : Inline Table-valued Function
Zweck        : Klassifiziert aggregierte Database-Mail-Status ohne
               Seiteneffekte.
Datenschutz  : Verarbeitet ausschließlich den technischen Versandstatus; keine
               Adresse, Empfänger, Betreffzeile oder Nachricht.
===============================================================================
*/
CREATE OR ALTER FUNCTION [monitor].[TVF_InterpretDatabaseMailStatus]
(
    @SentStatus varchar(8)
)
RETURNS TABLE
WITH SCHEMABINDING
AS
RETURN
(
    SELECT
          [FindingCode] = CONVERT(varchar(100),
              CASE WHEN @SentStatus='failed' THEN 'DATABASE_MAIL_FAILED_IN_WINDOW'
                   WHEN @SentStatus IN ('unsent','retrying') THEN 'DATABASE_MAIL_PENDING_IN_WINDOW'
                   ELSE 'DATABASE_MAIL_STATUS_INFORMATIONAL' END)
        , [FindingSeverity] = CONVERT(varchar(16),
              CASE WHEN @SentStatus='failed' THEN 'HIGH'
                   WHEN @SentStatus IN ('unsent','retrying') THEN 'MEDIUM'
                   ELSE 'INFO' END)
);
GO
-- END SOURCE: Code/01_Common/094_TVF_InterpretDatabaseMailStatus.sql

-- BEGIN SOURCE: Code/01_Common/095_USP_InternalWriteResultTable.sql
/*
===============================================================================
Objekt       : monitor.InternalWriteResultTable
Version      : 1.1.0
Stand        : 2026-07-19
Typ          : Interne Stored Procedure
Zweck        : Kopiert genau ein bereits materialisiertes Analyseergebnis in
               eine lokale Temp-Tabelle des Aufrufers. Eine leere Tabelle mit
               genau einer beliebigen Dummy-Spalte wird sicher an die native
               Quellstruktur angepasst; eine bereits passende Struktur wird
               zum Anhängen verwendet.
Sicherheit   : Ausschließlich lokale #Temp-Tabellen. Globale ##Temp-Tabellen
               und permanente Tabellen sind bewusst nicht zugelassen.
Locking      : Katalogauflösung ausschließlich über tempdb.sys.* WITH (NOLOCK)
               und LOCK_TIMEOUT 0; keine blockierenden Metadatenfunktionen.
===============================================================================
*/
SET ANSI_NULLS ON;
GO
SET QUOTED_IDENTIFIER ON;
GO

CREATE OR ALTER PROCEDURE [monitor].[InternalWriteResultTable]
      @SourceTable  sysname
    , @TargetTable  sysname
    , @InsertedRows bigint         = NULL OUTPUT
    , @StatusCode   varchar(40)    = NULL OUTPUT
    , @ErrorNumber  int            = NULL OUTPUT
    , @ErrorMessage nvarchar(2048) = NULL OUTPUT
    , @ThrowOnError bit            = 0
AS
BEGIN
    SET NOCOUNT ON;

    -- Diese lokalen Tabellen entstehen vor LOCK_TIMEOUT 0. Der No-Wait-
    -- Vertrag gilt für die fremden Quell-/Ziel-Temp-Tabellen, nicht für die
    -- eigene tempdb-Metadatenanlage des Writers.
    CREATE TABLE [#InternalWriteResultTable_SourceSchema]
    (
          [ColumnId] int NOT NULL
        , [ColumnName] sysname NOT NULL
        , [TypeName] sysname NOT NULL
        , [SystemTypeId] tinyint NOT NULL
        , [MaxLength] smallint NOT NULL
        , [Precision] tinyint NOT NULL
        , [Scale] tinyint NOT NULL
        , [CollationName] sysname NULL
        , [IsNullable] bit NOT NULL
        , [IsIdentity] bit NOT NULL
        , [IsComputed] bit NOT NULL
        , [IsUserDefined] bit NOT NULL
        , [IsAssemblyType] bit NOT NULL
        , [XmlCollectionId] int NOT NULL
    );

    CREATE TABLE [#InternalWriteResultTable_TargetSchema]
    (
          [ColumnId] int NOT NULL
        , [ColumnName] sysname NOT NULL
        , [TypeName] sysname NOT NULL
        , [SystemTypeId] tinyint NOT NULL
        , [MaxLength] smallint NOT NULL
        , [Precision] tinyint NOT NULL
        , [Scale] tinyint NOT NULL
        , [CollationName] sysname NULL
        , [IsNullable] bit NOT NULL
        , [IsIdentity] bit NOT NULL
        , [IsComputed] bit NOT NULL
        , [IsUserDefined] bit NOT NULL
        , [IsAssemblyType] bit NOT NULL
        , [XmlCollectionId] int NOT NULL
    );

    SET LOCK_TIMEOUT 0;

    DECLARE @TableThrowMessage nvarchar(2048);

    SELECT
          @InsertedRows = 0
        , @StatusCode = 'AVAILABLE'
        , @ErrorNumber = NULL
        , @ErrorMessage = NULL;

    IF @ThrowOnError IS NULL OR @ThrowOnError NOT IN (0,1)
    BEGIN
        SELECT
              @StatusCode = 'INVALID_PARAMETER'
            , @ErrorMessage = N'@ThrowOnError muss 0 oder 1 enthalten.';
        GOTO TableWriteFailed;
    END;

    IF @SourceTable IS NULL
       OR LEFT(@SourceTable, 1) <> N'#'
       OR LEFT(@SourceTable, 2) = N'##'
       OR @TargetTable IS NULL
       OR LEFT(@TargetTable, 1) <> N'#'
       OR LEFT(@TargetTable, 2) = N'##'
       OR LEN(@SourceTable) > 116
       OR LEN(@TargetTable) > 116
       OR @TargetTable LIKE N'#Monitor%' COLLATE Latin1_General_100_CI_AS
    BEGIN
        SELECT
              @StatusCode = 'INVALID_PARAMETER'
            , @ErrorMessage = N'@SourceTable und @TargetTable müssen lokale #Temp-Tabellen bezeichnen; ##Temp-, permanente Tabellen und das reservierte Präfix #Monitor sind nicht zulässig.';
        GOTO TableWriteFailed;
    END;

    IF @SourceTable = @TargetTable COLLATE Latin1_General_100_CI_AS
    BEGIN
        SELECT
              @StatusCode = 'INVALID_PARAMETER'
            , @ErrorMessage = N'Quell- und Zieltabelle dürfen nicht identisch sein.';
        GOTO TableWriteFailed;
    END;

    DECLARE @SourceObjectId int = NULL;
    DECLARE @TargetObjectId int = NULL;
    DECLARE @SourceMarker sysname = N'__MonitorResolveSource_' + REPLACE(CONVERT(nvarchar(36), NEWID()), N'-', N'');
    DECLARE @TargetMarker sysname = N'__MonitorResolveTarget_' + REPLACE(CONVERT(nvarchar(36), NEWID()), N'-', N'');
    DECLARE @ResolveSql nvarchar(max);

    BEGIN TRY
        SET @ResolveSql = N'ALTER TABLE ' + QUOTENAME(@SourceTable)
                        + N' ADD ' + QUOTENAME(@SourceMarker) + N' bit NULL;';
        EXEC [sys].[sp_executesql] @ResolveSql;
    END TRY
    BEGIN CATCH
        SELECT
              @StatusCode = CASE WHEN ERROR_NUMBER() = 1222 THEN 'LOCK_TIMEOUT' ELSE 'SOURCE_NOT_FOUND' END
            , @ErrorNumber = ERROR_NUMBER()
            , @ErrorMessage = N'Die interne Quelltabelle des ausgewählten Resultsets konnte nicht aufgelöst werden: ' + ERROR_MESSAGE();
        GOTO TableWriteFailed;
    END CATCH;

    SELECT @SourceObjectId = [c].[object_id]
    FROM [tempdb].[sys].[columns] AS [c] WITH (NOLOCK)
    JOIN [tempdb].[sys].[tables] AS [t] WITH (NOLOCK)
      ON [t].[object_id] = [c].[object_id]
    WHERE [c].[name] = @SourceMarker;

    BEGIN TRY
        SET @ResolveSql = N'ALTER TABLE ' + QUOTENAME(@SourceTable)
                        + N' DROP COLUMN ' + QUOTENAME(@SourceMarker) + N';';
        EXEC [sys].[sp_executesql] @ResolveSql;
    END TRY
    BEGIN CATCH
        SELECT
              @StatusCode = CASE WHEN ERROR_NUMBER() = 1222 THEN 'LOCK_TIMEOUT' ELSE 'TABLE_WRITE_ERROR' END
            , @ErrorNumber = ERROR_NUMBER()
            , @ErrorMessage = N'Die temporäre Quellmarkierung konnte nicht entfernt werden: ' + ERROR_MESSAGE();
        GOTO TableWriteFailed;
    END CATCH;

    IF @SourceObjectId IS NULL
    BEGIN
        SELECT
              @StatusCode = 'METADATA_NOT_VISIBLE'
            , @ErrorMessage = N'Die interne Quelltabelle ist vorhanden, ihre Katalogzeile war jedoch ohne Warten nicht sichtbar.';
        GOTO TableWriteFailed;
    END;

    BEGIN TRY
        SET @ResolveSql = N'ALTER TABLE ' + QUOTENAME(@TargetTable)
                        + N' ADD ' + QUOTENAME(@TargetMarker) + N' bit NULL;';
        EXEC [sys].[sp_executesql] @ResolveSql;
    END TRY
    BEGIN CATCH
        SELECT
              @StatusCode = CASE WHEN ERROR_NUMBER() = 1222 THEN 'LOCK_TIMEOUT' ELSE 'TARGET_NOT_FOUND' END
            , @ErrorNumber = ERROR_NUMBER()
            , @ErrorMessage = N'@TargetTable konnte nicht aufgelöst werden: ' + ERROR_MESSAGE();
        GOTO TableWriteFailed;
    END CATCH;

    SELECT @TargetObjectId = [c].[object_id]
    FROM [tempdb].[sys].[columns] AS [c] WITH (NOLOCK)
    JOIN [tempdb].[sys].[tables] AS [t] WITH (NOLOCK)
      ON [t].[object_id] = [c].[object_id]
    WHERE [c].[name] = @TargetMarker;

    BEGIN TRY
        SET @ResolveSql = N'ALTER TABLE ' + QUOTENAME(@TargetTable)
                        + N' DROP COLUMN ' + QUOTENAME(@TargetMarker) + N';';
        EXEC [sys].[sp_executesql] @ResolveSql;
    END TRY
    BEGIN CATCH
        SELECT
              @StatusCode = CASE WHEN ERROR_NUMBER() = 1222 THEN 'LOCK_TIMEOUT' ELSE 'TABLE_WRITE_ERROR' END
            , @ErrorNumber = ERROR_NUMBER()
            , @ErrorMessage = N'Die temporäre Zielmarkierung konnte nicht entfernt werden: ' + ERROR_MESSAGE();
        GOTO TableWriteFailed;
    END CATCH;

    IF @TargetObjectId IS NULL
    BEGIN
        SELECT
              @StatusCode = 'METADATA_NOT_VISIBLE'
            , @ErrorMessage = N'@TargetTable ist vorhanden, ihre Katalogzeile war jedoch ohne Warten nicht sichtbar.';
        GOTO TableWriteFailed;
    END;

    INSERT [#InternalWriteResultTable_SourceSchema]
    (
          [ColumnId], [ColumnName], [TypeName], [SystemTypeId], [MaxLength]
        , [Precision], [Scale], [CollationName], [IsNullable], [IsIdentity]
        , [IsComputed], [IsUserDefined], [IsAssemblyType], [XmlCollectionId]
    )
    SELECT
          CONVERT(int, ROW_NUMBER() OVER (ORDER BY [c].[column_id]))
        , [c].[name]
        , [t].[name]
        , [c].[system_type_id]
        , [c].[max_length]
        , [c].[precision]
        , [c].[scale]
        , [c].[collation_name]
        , [c].[is_nullable]
        , [c].[is_identity]
        , [c].[is_computed]
        , [t].[is_user_defined]
        , [t].[is_assembly_type]
        , [c].[xml_collection_id]
    FROM [tempdb].[sys].[columns] AS [c] WITH (NOLOCK)
    JOIN [tempdb].[sys].[types] AS [t] WITH (NOLOCK)
      ON [t].[user_type_id] = [c].[user_type_id]
    WHERE [c].[object_id] = @SourceObjectId;

    IF NOT EXISTS (SELECT 1 FROM [#InternalWriteResultTable_SourceSchema])
    BEGIN
        SELECT
              @StatusCode = 'UNSUPPORTED_SOURCE_SCHEMA'
            , @ErrorMessage = N'Das ausgewählte Resultset besitzt keine exportierbaren Spalten.';
        GOTO TableWriteFailed;
    END;

    IF EXISTS
    (
        SELECT 1
        FROM [#InternalWriteResultTable_SourceSchema]
        WHERE [IsComputed] = 1
           OR [IsUserDefined] = 1
           OR [IsAssemblyType] = 1
           OR [XmlCollectionId] <> 0
           OR [TypeName] IN (N'timestamp', N'rowversion')
    )
    BEGIN
        SELECT
              @StatusCode = 'UNSUPPORTED_SOURCE_SCHEMA'
            , @ErrorMessage = N'Das ausgewählte Resultset enthält einen nicht sicher reproduzierbaren Datentyp oder eine berechnete Spalte.';
        GOTO TableWriteFailed;
    END;

    INSERT [#InternalWriteResultTable_TargetSchema]
    (
          [ColumnId], [ColumnName], [TypeName], [SystemTypeId], [MaxLength]
        , [Precision], [Scale], [CollationName], [IsNullable], [IsIdentity]
        , [IsComputed], [IsUserDefined], [IsAssemblyType], [XmlCollectionId]
    )
    SELECT
          CONVERT(int, ROW_NUMBER() OVER (ORDER BY [c].[column_id]))
        , [c].[name]
        , [t].[name]
        , [c].[system_type_id]
        , [c].[max_length]
        , [c].[precision]
        , [c].[scale]
        , [c].[collation_name]
        , [c].[is_nullable]
        , [c].[is_identity]
        , [c].[is_computed]
        , [t].[is_user_defined]
        , [t].[is_assembly_type]
        , [c].[xml_collection_id]
    FROM [tempdb].[sys].[columns] AS [c] WITH (NOLOCK)
    JOIN [tempdb].[sys].[types] AS [t] WITH (NOLOCK)
      ON [t].[user_type_id] = [c].[user_type_id]
    WHERE [c].[object_id] = @TargetObjectId;

    DECLARE @TargetColumnCount int;
    DECLARE @TargetHasRows bit = 0;
    DECLARE @DummyColumnName sysname;
    DECLARE @TargetNeedsAdaptation bit = 0;

    SELECT
          @TargetColumnCount = COUNT(*)
        , @DummyColumnName = MAX([ColumnName])
    FROM [#InternalWriteResultTable_TargetSchema];

    IF EXISTS
    (
        SELECT
              [ColumnId], [ColumnName], [SystemTypeId], [MaxLength], [Precision]
            , [Scale], [CollationName], [IsNullable]
        FROM [#InternalWriteResultTable_SourceSchema]
        EXCEPT
        SELECT
              [ColumnId], [ColumnName], [SystemTypeId], [MaxLength], [Precision]
            , [Scale], [CollationName], [IsNullable]
        FROM [#InternalWriteResultTable_TargetSchema]
    )
    OR EXISTS
    (
        SELECT
              [ColumnId], [ColumnName], [SystemTypeId], [MaxLength], [Precision]
            , [Scale], [CollationName], [IsNullable]
        FROM [#InternalWriteResultTable_TargetSchema]
        EXCEPT
        SELECT
              [ColumnId], [ColumnName], [SystemTypeId], [MaxLength], [Precision]
            , [Scale], [CollationName], [IsNullable]
        FROM [#InternalWriteResultTable_SourceSchema]
    )
    OR EXISTS
    (
        SELECT 1
        FROM [#InternalWriteResultTable_TargetSchema]
        WHERE [IsIdentity] = 1
           OR [IsComputed] = 1
           OR [IsUserDefined] = 1
           OR [IsAssemblyType] = 1
           OR [XmlCollectionId] <> 0
    )
        SET @TargetNeedsAdaptation = 1;

    IF @TargetNeedsAdaptation = 1
    BEGIN
        IF @TargetColumnCount <> 1
        BEGIN
            SELECT
                  @StatusCode = 'TARGET_SCHEMA_MISMATCH'
                , @ErrorMessage = N'Eine abweichende Zieltabelle wird nur dann automatisch angepasst, wenn sie leer ist und genau eine beliebige Dummy-Spalte besitzt.';
            GOTO TableWriteFailed;
        END;

        DECLARE @HasRowsSql nvarchar(max) =
            N'SELECT @HasRows = CONVERT(bit, CASE WHEN EXISTS (SELECT 1 FROM '
            + QUOTENAME(@TargetTable)
            + N') THEN 1 ELSE 0 END);';

        BEGIN TRY
            EXEC [sys].[sp_executesql]
                  @HasRowsSql
                , N'@HasRows bit OUTPUT'
                , @HasRows = @TargetHasRows OUTPUT;
        END TRY
        BEGIN CATCH
            SELECT
                  @StatusCode = CASE WHEN ERROR_NUMBER() = 1222 THEN 'LOCK_TIMEOUT' ELSE 'TABLE_WRITE_ERROR' END
                , @ErrorNumber = ERROR_NUMBER()
                , @ErrorMessage = ERROR_MESSAGE();
            GOTO TableWriteFailed;
        END CATCH;

        IF @TargetHasRows = 1
        BEGIN
            SELECT
                  @StatusCode = 'TARGET_SCHEMA_MISMATCH'
                , @ErrorMessage = N'Die Zieltabelle muss leer sein, bevor ihre einzelne Dummy-Spalte ersetzt werden kann.';
            GOTO TableWriteFailed;
        END;

        DECLARE @ColumnDefinitions nvarchar(max);

        SELECT @ColumnDefinitions = STUFF
        (
            (
                SELECT
                      N', '
                    + QUOTENAME([s].[ColumnName])
                    + N' '
                    + CASE
                          WHEN [s].[TypeName] IN (N'varchar', N'char', N'varbinary', N'binary')
                              THEN QUOTENAME([s].[TypeName]) + N'(' + CASE WHEN [s].[MaxLength] = -1 THEN N'MAX' ELSE CONVERT(nvarchar(10), [s].[MaxLength]) END + N')'
                          WHEN [s].[TypeName] IN (N'nvarchar', N'nchar')
                              THEN QUOTENAME([s].[TypeName]) + N'(' + CASE WHEN [s].[MaxLength] = -1 THEN N'MAX' ELSE CONVERT(nvarchar(10), [s].[MaxLength] / 2) END + N')'
                          WHEN [s].[TypeName] IN (N'decimal', N'numeric')
                              THEN QUOTENAME([s].[TypeName]) + N'(' + CONVERT(nvarchar(10), [s].[Precision]) + N',' + CONVERT(nvarchar(10), [s].[Scale]) + N')'
                          WHEN [s].[TypeName] IN (N'datetime2', N'datetimeoffset', N'time')
                              THEN QUOTENAME([s].[TypeName]) + N'(' + CONVERT(nvarchar(10), [s].[Scale]) + N')'
                          WHEN [s].[TypeName] = N'float'
                              THEN QUOTENAME([s].[TypeName]) + N'(' + CONVERT(nvarchar(10), [s].[Precision]) + N')'
                          ELSE QUOTENAME([s].[TypeName])
                      END
                    + CASE WHEN [s].[CollationName] IS NULL THEN N'' ELSE N' COLLATE ' + [s].[CollationName] END
                    + CASE WHEN [s].[IsNullable] = 1 THEN N' NULL' ELSE N' NOT NULL' END
                FROM [#InternalWriteResultTable_SourceSchema] AS [s]
                ORDER BY [s].[ColumnId]
                FOR XML PATH(N''), TYPE
            ).value(N'.', N'nvarchar(max)')
            , 1
            , 2
            , N''
        );

        DECLARE @BridgeColumnName sysname = N'__MonitorBridge_' + REPLACE(CONVERT(nvarchar(36), NEWID()), N'-', N'');
        WHILE EXISTS (SELECT 1 FROM [#InternalWriteResultTable_SourceSchema] WHERE [ColumnName] = @BridgeColumnName)
           OR EXISTS (SELECT 1 FROM [#InternalWriteResultTable_TargetSchema] WHERE [ColumnName] = @BridgeColumnName)
            SET @BridgeColumnName = N'__MonitorBridge_' + REPLACE(CONVERT(nvarchar(36), NEWID()), N'-', N'');

        BEGIN TRY
            DECLARE @AlterSql nvarchar(max) =
                  N'ALTER TABLE ' + QUOTENAME(@TargetTable) + N' ADD ' + QUOTENAME(@BridgeColumnName) + N' bit NULL;'
                + N' ALTER TABLE ' + QUOTENAME(@TargetTable) + N' DROP COLUMN ' + QUOTENAME(@DummyColumnName) + N';'
                + N' ALTER TABLE ' + QUOTENAME(@TargetTable) + N' ADD ' + @ColumnDefinitions + N';'
                + N' ALTER TABLE ' + QUOTENAME(@TargetTable) + N' DROP COLUMN ' + QUOTENAME(@BridgeColumnName) + N';';

            EXEC [sys].[sp_executesql] @AlterSql;
        END TRY
        BEGIN CATCH
            SELECT
                  @StatusCode = CASE WHEN ERROR_NUMBER() = 1222 THEN 'LOCK_TIMEOUT' ELSE 'TABLE_WRITE_ERROR' END
                , @ErrorNumber = ERROR_NUMBER()
                , @ErrorMessage = ERROR_MESSAGE();
            GOTO TableWriteFailed;
        END CATCH;

        DELETE FROM [#InternalWriteResultTable_TargetSchema];

        INSERT [#InternalWriteResultTable_TargetSchema]
        (
              [ColumnId], [ColumnName], [TypeName], [SystemTypeId], [MaxLength]
            , [Precision], [Scale], [CollationName], [IsNullable], [IsIdentity]
            , [IsComputed], [IsUserDefined], [IsAssemblyType], [XmlCollectionId]
        )
        SELECT
              CONVERT(int, ROW_NUMBER() OVER (ORDER BY [c].[column_id]))
            , [c].[name]
            , [t].[name]
            , [c].[system_type_id]
            , [c].[max_length]
            , [c].[precision]
            , [c].[scale]
            , [c].[collation_name]
            , [c].[is_nullable]
            , [c].[is_identity]
            , [c].[is_computed]
            , [t].[is_user_defined]
            , [t].[is_assembly_type]
            , [c].[xml_collection_id]
        FROM [tempdb].[sys].[columns] AS [c] WITH (NOLOCK)
        JOIN [tempdb].[sys].[types] AS [t] WITH (NOLOCK)
          ON [t].[user_type_id] = [c].[user_type_id]
        WHERE [c].[object_id] = @TargetObjectId;
    END;

    IF EXISTS
    (
        SELECT
              [ColumnId], [ColumnName], [SystemTypeId], [MaxLength], [Precision]
            , [Scale], [CollationName], [IsNullable]
        FROM [#InternalWriteResultTable_SourceSchema]
        EXCEPT
        SELECT
              [ColumnId], [ColumnName], [SystemTypeId], [MaxLength], [Precision]
            , [Scale], [CollationName], [IsNullable]
        FROM [#InternalWriteResultTable_TargetSchema]
    )
    OR EXISTS
    (
        SELECT
              [ColumnId], [ColumnName], [SystemTypeId], [MaxLength], [Precision]
            , [Scale], [CollationName], [IsNullable]
        FROM [#InternalWriteResultTable_TargetSchema]
        EXCEPT
        SELECT
              [ColumnId], [ColumnName], [SystemTypeId], [MaxLength], [Precision]
            , [Scale], [CollationName], [IsNullable]
        FROM [#InternalWriteResultTable_SourceSchema]
    )
    OR EXISTS
    (
        SELECT 1
        FROM [#InternalWriteResultTable_TargetSchema]
        WHERE [IsIdentity] = 1
           OR [IsComputed] = 1
           OR [IsUserDefined] = 1
           OR [IsAssemblyType] = 1
           OR [XmlCollectionId] <> 0
    )
    BEGIN
        SELECT
              @StatusCode = 'TARGET_SCHEMA_MISMATCH'
            , @ErrorMessage = N'Die vorhandene Struktur von @TargetTable stimmt nicht exakt mit dem ausgewählten Resultset überein.';
        GOTO TableWriteFailed;
    END;

    DECLARE @ColumnList nvarchar(max);

    SELECT @ColumnList = STUFF
    (
        (
            SELECT N', ' + QUOTENAME([s].[ColumnName])
            FROM [#InternalWriteResultTable_SourceSchema] AS [s]
            ORDER BY [s].[ColumnId]
            FOR XML PATH(N''), TYPE
        ).value(N'.', N'nvarchar(max)')
        , 1
        , 2
        , N''
    );

    BEGIN TRY
        DECLARE @InsertSql nvarchar(max) =
              N'INSERT ' + QUOTENAME(@TargetTable) + N' (' + @ColumnList + N')'
            + N' SELECT ' + @ColumnList + N' FROM ' + QUOTENAME(@SourceTable) + N';'
            + N' SET @Rows = @@ROWCOUNT;';

        EXEC [sys].[sp_executesql]
              @InsertSql
            , N'@Rows bigint OUTPUT'
            , @Rows = @InsertedRows OUTPUT;
    END TRY
    BEGIN CATCH
        SELECT
              @StatusCode = 'TABLE_WRITE_ERROR'
            , @ErrorNumber = ERROR_NUMBER()
            , @ErrorMessage = ERROR_MESSAGE();
    END CATCH;

    IF @StatusCode <> 'AVAILABLE'
        GOTO TableWriteFailed;

    RETURN;

TableWriteFailed:
    IF @ThrowOnError = 1
    BEGIN
        SET @TableThrowMessage = CONCAT
        (
              N'TABLE-Ausgabe fehlgeschlagen ('
            , COALESCE(@StatusCode, N'UNKNOWN')
            , N'): '
            , COALESCE(@ErrorMessage, N'Unbekannter Fehler.')
        );
        THROW 51010, @TableThrowMessage, 1;
    END;
END;
GO
-- END SOURCE: Code/01_Common/095_USP_InternalWriteResultTable.sql

-- BEGIN SOURCE: Code/01_Common/096_USP_InternalPrepareResultTables.sql
/*
===============================================================================
Objekt       : monitor.InternalPrepareResultTables
Version      : 1.0.0
Stand        : 2026-07-20
Typ          : Interne Stored Procedure
Zweck        : Validiert eine benannte TABLE-Mehrfachzuordnung vollständig vor
               dem ersten fachlichen Systemzugriff und befüllt eine lokale
               Mapping-Temp-Tabelle des Aufrufers.
Sicherheit   : Nur vorhandene, leere lokale #Temp-Tabellen mit genau einer
               Seed-Spalte. Doppelte Ziele und unbekannte Resultsetnamen werden
               atomar abgelehnt. Keine fachlichen Datenquellen werden gelesen.
===============================================================================
*/
CREATE OR ALTER PROCEDURE [monitor].[InternalPrepareResultTables]
      @ResultTablesJson    nvarchar(max)
    , @AllowedResultNames  nvarchar(max)
    , @MappingTable        sysname
    , @StatusCode          varchar(40)    = NULL OUTPUT
    , @ErrorMessage        nvarchar(2048) = NULL OUTPUT
    , @ThrowOnError        bit            = 0
AS
BEGIN
    SET NOCOUNT ON;

    -- Lokale Metadatenobjekte werden vor dem bewussten No-Wait-Vertrag
    -- angelegt, damit eine kurzzeitige tempdb-DDL-Kollision nicht schon den
    -- rein internen Arbeitsbereich mit Fehler 1222 abbrechen lässt.
    CREATE TABLE [#InternalPrepareResultTables_Allowed]
    (
          [ResultName] sysname COLLATE SQL_Latin1_General_CP1_CS_AS NOT NULL
        , [ResultNameBinary] varbinary(256) NOT NULL PRIMARY KEY
    );

    CREATE TABLE [#InternalPrepareResultTables_Parsed]
    (
          [ResultName] sysname COLLATE SQL_Latin1_General_CP1_CS_AS NOT NULL
        , [TargetTable] sysname COLLATE SQL_Latin1_General_CP1_CS_AS NOT NULL
        , [JsonType] int NOT NULL
    );

    SET LOCK_TIMEOUT 0;

    SELECT
          @StatusCode = 'AVAILABLE'
        , @ErrorMessage = NULL;

    IF @ThrowOnError IS NULL OR @ThrowOnError NOT IN (0,1)
    BEGIN
        SET @StatusCode = 'INVALID_PARAMETER';
        SET @ErrorMessage = N'@ThrowOnError muss 0 oder 1 enthalten.';
        GOTO PreflightFailed;
    END;

    IF @MappingTable IS NULL
       OR LEFT(@MappingTable,1) <> N'#'
       OR LEFT(@MappingTable,2) = N'##'
       OR LEN(@MappingTable) > 116
    BEGIN
        SET @StatusCode = 'INVALID_PARAMETER';
        SET @ErrorMessage = N'@MappingTable muss eine gültige lokale #Temp-Tabelle bezeichnen.';
        GOTO PreflightFailed;
    END;

    IF @ResultTablesJson IS NULL
       OR ISJSON(@ResultTablesJson) <> 1
       OR LEFT(LTRIM(@ResultTablesJson),1) <> N'{'
       OR RIGHT(RTRIM(@ResultTablesJson),1) <> N'}'
    BEGIN
        SET @StatusCode = 'INVALID_RESULT_TABLE_MAPPING';
        SET @ErrorMessage = N'@ResultTablesJson muss ein gültiges JSON-Objekt enthalten.';
        GOTO PreflightFailed;
    END;

    INSERT [#InternalPrepareResultTables_Allowed]([ResultName],[ResultNameBinary])
    SELECT
          CONVERT(sysname, LTRIM(RTRIM([value])))
        , CONVERT(varbinary(256), CONVERT(sysname, LTRIM(RTRIM([value]))))
    FROM STRING_SPLIT(COALESCE(@AllowedResultNames,N''),N'|')
    WHERE NULLIF(LTRIM(RTRIM([value])),N'') IS NOT NULL;

    BEGIN TRY
        INSERT [#InternalPrepareResultTables_Parsed]([ResultName],[TargetTable],[JsonType])
        SELECT
              CONVERT(sysname,[key])
            , CONVERT(sysname,[value])
            , [type]
        FROM OPENJSON(@ResultTablesJson);
    END TRY
    BEGIN CATCH
        SET @StatusCode = 'INVALID_RESULT_TABLE_MAPPING';
        SET @ErrorMessage = N'@ResultTablesJson enthält einen nicht unterstützten Namen oder Zielwert.';
        GOTO PreflightFailed;
    END CATCH;

    IF NOT EXISTS (SELECT 1 FROM [#InternalPrepareResultTables_Parsed])
       OR EXISTS
          (
              SELECT 1
              FROM [#InternalPrepareResultTables_Parsed]
              WHERE [JsonType] <> 1
                 OR NULLIF(LTRIM(RTRIM([ResultName])),N'') IS NULL
                 OR NULLIF(LTRIM(RTRIM([TargetTable])),N'') IS NULL
          )
       OR EXISTS
          (
              SELECT 1
              FROM [#InternalPrepareResultTables_Parsed]
              GROUP BY CONVERT(varbinary(256),[ResultName])
              HAVING COUNT(*) > 1
          )
       OR EXISTS
          (
              SELECT 1
              FROM [#InternalPrepareResultTables_Parsed]
              GROUP BY [TargetTable] COLLATE Latin1_General_100_CI_AS
              HAVING COUNT(*) > 1
          )
       OR EXISTS
          (
              SELECT 1
              FROM [#InternalPrepareResultTables_Parsed] AS [p]
              WHERE NOT EXISTS
                    (
                        SELECT 1
                        FROM [#InternalPrepareResultTables_Allowed] AS [a]
                        WHERE [a].[ResultNameBinary] = CONVERT(varbinary(256),[p].[ResultName])
                    )
          )
       OR EXISTS
          (
              SELECT 1
              FROM [#InternalPrepareResultTables_Parsed]
              WHERE LEFT([TargetTable],1) <> N'#'
                 OR LEFT([TargetTable],2) = N'##'
                 OR LEN([TargetTable]) > 116
                 OR [TargetTable] LIKE N'#Monitor%' COLLATE Latin1_General_100_CI_AS
          )
    BEGIN
        SET @StatusCode = 'INVALID_RESULT_TABLE_MAPPING';
        SET @ErrorMessage = N'Die TABLE-Zuordnung enthält unbekannte oder doppelte Resultsetnamen, doppelte Ziele oder unzulässige Temp-Tabellennamen.';
        GOTO PreflightFailed;
    END;

    DECLARE @MappingTableQuoted nvarchar(258) = QUOTENAME(@MappingTable);
    DECLARE @Sql nvarchar(max);

    BEGIN TRY
        SET @Sql = N'DECLARE @ResultName sysname,@TargetTable sysname;
SELECT TOP (0) @ResultName=[ResultName],@TargetTable=[TargetTable]
FROM ' + @MappingTableQuoted + N';';
        EXEC [sys].[sp_executesql] @Sql;
    END TRY
    BEGIN CATCH
        SET @StatusCode = 'INTERNAL_ERROR';
        SET @ErrorMessage = N'Die Mapping-Temp-Tabelle wurde nicht mit dem erwarteten Schema angelegt.';
        GOTO PreflightFailed;
    END CATCH;

    DECLARE @TargetTable sysname;
    DECLARE @TargetTableQuoted nvarchar(258);
    DECLARE @HasRows bit;
    DECLARE @Marker sysname;
    DECLARE @MarkerAdded bit;
    DECLARE @ColumnCount int;

    DECLARE [TargetCursor] CURSOR LOCAL FAST_FORWARD FOR
        SELECT [TargetTable]
        FROM [#InternalPrepareResultTables_Parsed]
        ORDER BY [ResultName];

    OPEN [TargetCursor];
    FETCH NEXT FROM [TargetCursor] INTO @TargetTable;
    WHILE @@FETCH_STATUS = 0
    BEGIN
        SELECT
              @TargetTableQuoted = QUOTENAME(@TargetTable)
            , @HasRows = NULL
            , @Marker = N'__MonitorPreflight_' + REPLACE(CONVERT(nvarchar(36),NEWID()),N'-',N'')
            , @MarkerAdded = 0
            , @ColumnCount = NULL;

        BEGIN TRY
            SET @Sql = N'SELECT @HasRows = CONVERT(bit,CASE WHEN EXISTS(SELECT 1 FROM '
                     + @TargetTableQuoted + N') THEN 1 ELSE 0 END);';
            EXEC [sys].[sp_executesql] @Sql,N'@HasRows bit OUTPUT',@HasRows=@HasRows OUTPUT;

            IF @HasRows = 1
            BEGIN
                SET @StatusCode = 'INVALID_RESULT_TABLE_TARGET';
                SET @ErrorMessage = N'Alle TABLE-Ziele müssen vor dem Aufruf leer sein.';
                CLOSE [TargetCursor];
                DEALLOCATE [TargetCursor];
                GOTO PreflightFailed;
            END;

            SET @Sql = N'ALTER TABLE ' + @TargetTableQuoted
                     + N' ADD ' + QUOTENAME(@Marker) + N' bit NULL;';
            EXEC [sys].[sp_executesql] @Sql;
            SET @MarkerAdded = 1;

            SELECT @ColumnCount = COUNT(*)
            FROM [tempdb].[sys].[columns] AS [c] WITH (NOLOCK)
            INNER JOIN [tempdb].[sys].[tables] AS [t] WITH (NOLOCK)
              ON [t].[object_id] = [c].[object_id]
            WHERE EXISTS
                  (
                      SELECT 1
                      FROM [tempdb].[sys].[columns] AS [m] WITH (NOLOCK)
                      WHERE [m].[object_id] = [t].[object_id]
                        AND [m].[name] = @Marker
                  );

            SET @Sql = N'ALTER TABLE ' + @TargetTableQuoted
                     + N' DROP COLUMN ' + QUOTENAME(@Marker) + N';';
            EXEC [sys].[sp_executesql] @Sql;
            SET @MarkerAdded = 0;

            IF @ColumnCount <> 2
            BEGIN
                SET @StatusCode = 'INVALID_RESULT_TABLE_TARGET';
                SET @ErrorMessage = N'Jedes neue TABLE-Ziel muss genau eine Seed-Spalte besitzen.';
                CLOSE [TargetCursor];
                DEALLOCATE [TargetCursor];
                GOTO PreflightFailed;
            END;
        END TRY
        BEGIN CATCH
            IF @MarkerAdded = 1
            BEGIN TRY
                SET @Sql = N'ALTER TABLE ' + @TargetTableQuoted
                         + N' DROP COLUMN ' + QUOTENAME(@Marker) + N';';
                EXEC [sys].[sp_executesql] @Sql;
            END TRY
            BEGIN CATCH
            END CATCH;

            SET @StatusCode = 'INVALID_RESULT_TABLE_TARGET';
            SET @ErrorMessage = N'Mindestens eine angeforderte lokale Ziel-Temp-Tabelle ist nicht vorhanden oder nicht sicher validierbar.';
            CLOSE [TargetCursor];
            DEALLOCATE [TargetCursor];
            GOTO PreflightFailed;
        END CATCH;

        FETCH NEXT FROM [TargetCursor] INTO @TargetTable;
    END;
    CLOSE [TargetCursor];
    DEALLOCATE [TargetCursor];

    SET @Sql = N'INSERT ' + @MappingTableQuoted + N'([ResultName],[TargetTable])
SELECT [ResultName],[TargetTable]
FROM [#InternalPrepareResultTables_Parsed];';
    EXEC [sys].[sp_executesql] @Sql;
    RETURN;

PreflightFailed:
    IF @ThrowOnError = 1
        THROW 51011, @ErrorMessage, 1;
END;
GO
-- END SOURCE: Code/01_Common/096_USP_InternalPrepareResultTables.sql

-- BEGIN SOURCE: Code/01_Common/097_USP_InternalPrepareSingleResultTable.sql
/*
===============================================================================
Objekt       : monitor.InternalPrepareSingleResultTable
Version      : 1.0.0
Stand        : 2026-07-20
Typ          : Interne Stored Procedure
Zweck        : Führt den benannten TABLE-Preflight für eine Procedure mit genau
               einem exportierbaren Resultset aus und gibt das validierte lokale
               Ziel zurück. Fachliche Systemquellen werden nicht gelesen.
===============================================================================
*/
CREATE OR ALTER PROCEDURE [monitor].[InternalPrepareSingleResultTable]
      @ResultTablesJson  nvarchar(max)
    , @ResultName        sysname
    , @TargetTable       sysname        OUTPUT
    , @ThrowOnError      bit            = 1
AS
BEGIN
    SET NOCOUNT ON;
    SET LOCK_TIMEOUT 0;
    SET @TargetTable=NULL;

    CREATE TABLE [#InternalPrepareSingleResultTable_Map]
    (
          [ResultName] sysname COLLATE SQL_Latin1_General_CP1_CS_AS NOT NULL PRIMARY KEY
        , [TargetTable] sysname COLLATE SQL_Latin1_General_CP1_CS_AS NOT NULL UNIQUE
    );

    DECLARE @StatusCode varchar(40),@ErrorMessage nvarchar(2048);
    EXEC [monitor].[InternalPrepareResultTables]
          @ResultTablesJson=@ResultTablesJson
        , @AllowedResultNames=@ResultName
        , @MappingTable=N'#InternalPrepareSingleResultTable_Map'
        , @StatusCode=@StatusCode OUTPUT
        , @ErrorMessage=@ErrorMessage OUTPUT
        , @ThrowOnError=@ThrowOnError;

    IF @StatusCode='AVAILABLE'
        SELECT @TargetTable=[TargetTable]
        FROM [#InternalPrepareSingleResultTable_Map]
        WHERE [ResultName]=@ResultName COLLATE SQL_Latin1_General_CP1_CS_AS;
END;
GO
-- END SOURCE: Code/01_Common/097_USP_InternalPrepareSingleResultTable.sql

-- BEGIN SOURCE: Code/01_Common/098_USP_InternalEmitConsoleResult.sql
/*
===============================================================================
Objekt       : monitor.InternalEmitConsoleResult
Version      : 1.0.0
Stand        : 2026-07-20
Typ          : Interne Stored Procedure
Zweck        : Rendert genau ein menschenlesbares CONSOLE-Resultset aus einer
               bereits im Aufrufer materialisierten lokalen Temp-Tabelle.
Vertrag      : Keine fachlichen Systemzugriffe. Nicht leere Quellen liefern
               eine beschriftete Fachansicht. Leere Quellen liefern genau eine
               verständliche Console-Zeile; RAW und TABLE verwenden den Helper
               nicht und erhalten deshalb keine künstlichen Datenzeilen.
===============================================================================
*/
CREATE OR ALTER PROCEDURE [monitor].[InternalEmitConsoleResult]
      @SourceTable    sysname
    , @ResultLabel    nvarchar(200)
    , @EmptyMessage   nvarchar(200)
    , @StatusCode     varchar(40)    = NULL
    , @StatusMessage  nvarchar(2048) = NULL
AS
BEGIN
    SET NOCOUNT ON;
    SET LOCK_TIMEOUT 0;

    IF @SourceTable IS NULL
       OR LEFT(@SourceTable,1)<>N'#'
       OR LEFT(@SourceTable,2)=N'##'
       OR LEN(@SourceTable)>116
        THROW 51012,N'@SourceTable muss eine lokale #Temp-Tabelle des Aufrufers bezeichnen.',1;

    SET @ResultLabel=COALESCE(NULLIF(LTRIM(RTRIM(@ResultLabel)),N''),N'Ergebnis');
    SET @EmptyMessage=COALESCE(NULLIF(LTRIM(RTRIM(@EmptyMessage)),N''),N'Keine Ergebnisse');

    DECLARE @Sql nvarchar(max)=
          N'IF EXISTS (SELECT 1 FROM '+QUOTENAME(@SourceTable)+N')'
        + N' SELECT @Label AS [Ergebnis],[src].* FROM '+QUOTENAME(@SourceTable)+N' AS [src];'
        + N' ELSE SELECT @Empty AS [Ergebnis],@Status AS [Status],@Message AS [Hinweis];';

    EXEC [sys].[sp_executesql]
          @Sql
        , N'@Label nvarchar(200),@Empty nvarchar(200),@Status varchar(40),@Message nvarchar(2048)'
        , @Label=@ResultLabel
        , @Empty=@EmptyMessage
        , @Status=@StatusCode
        , @Message=@StatusMessage;
END;
GO
-- END SOURCE: Code/01_Common/098_USP_InternalEmitConsoleResult.sql

-- BEGIN SOURCE: Code/01_Common/099_USP_InternalEmitTruncationWarning.sql
/*
===============================================================================
Objekt       : monitor.InternalEmitTruncationWarning
Version      : 1.0.0
Stand        : 2026-07-21
Typ          : Interne Stored Procedure
Zweck        : Gibt höchstens eine technische Severity-10-Warning für alle im
               Aufruf sichtbar gekürzten Werte aus.
Resultsets   : Keine.
Nebenwirkung : Ausschließlich RAISERROR Severity 10 WITH NOWAIT, wenn die
               Ausgabe aktiviert und mindestens ein Wert gekürzt ist.
===============================================================================
*/
CREATE OR ALTER PROCEDURE [monitor].[InternalEmitTruncationWarning]
      @TruncatedValueCount       bigint
    , @ParameterName             sysname
    , @ParameterValue            int
    , @LargestRequiredCharacters bigint
    , @PrintMeldungen            bit = 1
AS
BEGIN
    SET NOCOUNT ON;
    SET LOCK_TIMEOUT 0;

    IF COALESCE(@PrintMeldungen,0) <> 1
       OR COALESCE(@TruncatedValueCount,0) <= 0
        RETURN;

    DECLARE @Message nvarchar(2048) = LEFT
    (
        CONCAT
        (
              N'OUTPUT_VALUE_TRUNCATED: '
            , CONVERT(nvarchar(30),@TruncatedValueCount)
            , N' Wert(e) wurden durch '
            , COALESCE(@ParameterName,N'<unbekannter Parameter>')
            , N'='
            , COALESCE(CONVERT(nvarchar(30),@ParameterValue),N'NULL')
            , N' gekürzt. Der größte Wert benötigt '
            , COALESCE(CONVERT(nvarchar(30),@LargestRequiredCharacters),N'NULL')
            , N' Zeichen. Verwenden Sie '
            , COALESCE(@ParameterName,N'den begrenzenden Parameter')
            , N'='
            , COALESCE(CONVERT(nvarchar(30),@LargestRequiredCharacters),N'0')
            , N' oder 0 für eine vollständige Ausgabe.'
        ),
        2048
    );

    RAISERROR(N'%s',10,1,@Message) WITH NOWAIT;
END;
GO
-- END SOURCE: Code/01_Common/099_USP_InternalEmitTruncationWarning.sql

-- BEGIN SOURCE: Code/01_Common/099a_USP_InternalParseXmlText.sql
/*
===============================================================================
Objekt       : monitor.InternalParseXmlText
Version      : 1.0.0
Stand        : 2026-07-21
Typ          : Interne Stored Procedure
Zweck        : Konvertiert einen vollständigen nvarchar(max)-Quellwert ohne
               vorherige Kürzung in natives xml und klassifiziert Ausfälle.
Resultsets   : Keine; ausschließlich OUTPUT-Parameter.
Grenze       : Die aufrufende Procedure materialisiert den Quelltext genau
               einmal und entscheidet, ob ein Textfallback exportiert wird.
===============================================================================
*/
CREATE OR ALTER PROCEDURE [monitor].[InternalParseXmlText]
      @XmlText       nvarchar(max)
    , @XmlValue      xml            = NULL OUTPUT
    , @StatusCode    varchar(40)    = NULL OUTPUT
    , @ErrorNumber   int            = NULL OUTPUT
    , @ErrorMessage  nvarchar(2048) = NULL OUTPUT
AS
BEGIN
    SET NOCOUNT ON;
    SET LOCK_TIMEOUT 0;

    SELECT @XmlValue=NULL,@ErrorNumber=NULL,@ErrorMessage=NULL,
           @StatusCode=CASE WHEN @XmlText IS NULL THEN 'SOURCE_NULL' ELSE 'PENDING' END;

    IF @XmlText IS NULL RETURN;

    BEGIN TRY
        SET @XmlValue=CONVERT(xml,@XmlText);
        SET @StatusCode=CASE
            WHEN NULLIF(LTRIM(RTRIM(@XmlText)),N'') IS NULL THEN 'XML_EMPTY'
            ELSE 'AVAILABLE' END;
    END TRY
    BEGIN CATCH
        SELECT @ErrorNumber=ERROR_NUMBER(),@ErrorMessage=ERROR_MESSAGE(),
               @StatusCode=CASE
                   WHEN ERROR_NUMBER() IN(6335,6336,6337) THEN 'XML_UNAVAILABLE_LIMIT'
                   ELSE 'XML_INVALID' END;
    END CATCH;
END;
GO
-- END SOURCE: Code/01_Common/099a_USP_InternalParseXmlText.sql

-- BEGIN SOURCE: Code/01_Common/070_USP_CheckFrameworkCapabilities.sql
/*
===============================================================================
Objekt       : monitor.USP_CheckFrameworkCapabilities
Version      : 2.0.1
Stand        : 2026-07-16
Zweck        : Prüft Framework-Capabilities serverweit und je ausgewählter DB.
Datenbanken  : @DatabaseNames bracket-aware Pipe-Liste; NULL/N''=alle.
Ausgabe      : RAW, CONSOLE, TABLE oder NONE; optional JSON mit capabilities, summary,
               databaseStatus und warnings.
Änderungen   : 2.0.1 - SQL-Literal-Escaping für Datenbanknamen korrigiert.
===============================================================================
*/
CREATE OR ALTER PROCEDURE [monitor].[USP_CheckFrameworkCapabilities]
      @DatabaseNames                    nvarchar(max)  = NULL
    , @SystemdatenbankenEinbeziehen     bit            = 0
    , @DatabaseNamePattern              nvarchar(4000) = NULL
    , @HighImpactConfirmed              bit            = 0
    , @AnalyseKlasse                    varchar(64)     = NULL
    , @NurNichtVerfuegbar               bit            = 0
    , @MitGruppenpruefung               bit            = 1
    , @ResultSetArt                     varchar(16)     = 'CONSOLE'
    , @ResultTablesJson               nvarchar(max) = NULL
    , @JsonErzeugen                     bit             = 0
    , @Json                              nvarchar(max)  = NULL OUTPUT
    , @PrintMeldungen                   bit             = 1
    , @Hilfe                             bit             = 0
AS
BEGIN
    SET NOCOUNT ON;
    SET @Json = NULL;

    DECLARE @ResultSetArtNormalisiert varchar(16) = UPPER(LTRIM(RTRIM(COALESCE(@ResultSetArt, ''))));
    DECLARE @TableResultRequested bit = CASE WHEN @ResultSetArtNormalisiert = 'TABLE' THEN 1 ELSE 0 END;
    DECLARE @ConsoleResultRequested bit = CASE WHEN @ResultSetArtNormalisiert = 'CONSOLE' THEN 1 ELSE 0 END;
    DECLARE @TableTarget sysname=NULL;
    IF @TableResultRequested=0 AND NULLIF(LTRIM(RTRIM(COALESCE(@ResultTablesJson,N''))),N'') IS NOT NULL THROW 51011,N'@ResultTablesJson ist ausschließlich mit @ResultSetArt=TABLE zulässig.',1;
    IF @TableResultRequested=1 EXEC [monitor].[InternalPrepareSingleResultTable] @ResultTablesJson=@ResultTablesJson,@ResultName=N'capabilities',@TargetTable=@TableTarget OUTPUT,@ThrowOnError=1;
    IF @TableResultRequested = 1 OR @ConsoleResultRequested = 1 SET @ResultSetArtNormalisiert = 'NONE';
    DECLARE @Major int = TRY_CONVERT(int, SERVERPROPERTY(N'ProductMajorVersion'));
    DECLARE @ProductVersion nvarchar(128) = CONVERT(nvarchar(128), SERVERPROPERTY(N'ProductVersion'));
    DECLARE @CollectionTimeUtc datetime2(3) = SYSUTCDATETIME();
    DECLARE @OverallStatus varchar(40) = 'AVAILABLE';
    DECLARE @OverallError nvarchar(2048) = NULL;
    DECLARE @CrossDatabaseRequested bit = 0;

    IF @Hilfe = 1
    BEGIN
        PRINT N'monitor.USP_CheckFrameworkCapabilities';
        PRINT N'@DatabaseNames: bracket-aware Pipe-Liste; NULL/leer=alle sichtbaren Online-Benutzerdatenbanken.';
        PRINT N'@DatabaseNamePattern: like:, regex: oder regexi:; exakte Liste und Pattern sind exklusiv.';
        PRINT N'@ResultSetArt=RAW, CONSOLE, TABLE oder NONE; optional JSON.';
        RETURN;
    END;

    CREATE TABLE [#CheckFrameworkCapabilities_DatabaseCandidates]
    (
          [DatabaseId] int NOT NULL
        , [DatabaseName] sysname COLLATE SQL_Latin1_General_CP1_CS_AS NOT NULL
        , [StateDesc] nvarchar(60) NULL
        , [UserAccessDesc] nvarchar(60) NULL
        , [IsReadOnly] bit NULL
        , [CompatibilityLevel] tinyint NULL
        , [CollationName] sysname NULL
        , [RecoveryModelDesc] nvarchar(60) NULL
        , [IsSystemDatabase] bit NOT NULL
        , [RequestedOrdinal] int NULL
    );
    CREATE TABLE [#CheckFrameworkCapabilities_DatabaseCandidateWarnings]
    (
          [RequestedName] sysname COLLATE SQL_Latin1_General_CP1_CS_AS NULL
        , [StatusCode] varchar(40) NOT NULL
        , [ErrorMessage] nvarchar(2048) NOT NULL
    );
    CREATE TABLE [#CheckFrameworkCapabilities_Capabilities]
    (
          [FeatureOrdinal] smallint NOT NULL
        , [FeatureCode] varchar(64) NOT NULL
        , [FeatureName] nvarchar(200) NOT NULL
        , [ScopeType] varchar(16) NOT NULL
        , [AnalysisClass] varchar(64) NOT NULL
        , [AnalysisLevel] varchar(16) NOT NULL
        , [IsResourceIntensive] bit NOT NULL
        , [DatabaseName] sysname NULL
        , [ServerMajorVersion] int NULL
        , [ServerProductVersion] nvarchar(128) NULL
        , [MinimumMajorVersion] tinyint NOT NULL
        , [VersionSupported] bit NOT NULL
        , [GroupCheckApplied] bit NOT NULL
        , [GroupAccessAllowed] bit NULL
        , [AccessReason] varchar(20) NULL
        , [RequiredPermissionScope] varchar(16) NOT NULL
        , [PermissionCheckType] varchar(24) NOT NULL
        , [RequiredPermission] sysname NULL
        , [PermissionDisplayText] nvarchar(128) NULL
        , [HasRequiredPermission] bit NULL
        , [IsQueryable] bit NOT NULL
        , [IsFeatureEnabled] bit NULL
        , [IsUsable] bit NOT NULL
        , [StatusCode] varchar(40) NOT NULL
        , [ErrorNumber] int NULL
        , [ErrorMessage] nvarchar(2048) NULL
        , [Description] nvarchar(1000) NULL
    );

    IF @ResultSetArtNormalisiert NOT IN ('RAW', 'CONSOLE', 'NONE')
    BEGIN
        SET @OverallStatus = 'INVALID_PARAMETER';
        SET @OverallError = N'@ResultSetArt muss CONSOLE, RAW, TABLE oder NONE enthalten.';
    END;
    ELSE IF @AnalyseKlasse IS NOT NULL
        AND NOT EXISTS (SELECT 1 FROM [monitor].[VW_AnalyseClassCatalog] WHERE [AnalysisClass] = @AnalyseKlasse)
    BEGIN
        SET @OverallStatus = 'INVALID_PARAMETER';
        SET @OverallError = N'Unbekannte Analyseklasse.';
    END;

    IF @OverallStatus = 'AVAILABLE'
    BEGIN
        EXEC [monitor].[USP_PrepareDatabaseCandidates]
              @DatabaseNames = @DatabaseNames
            , @SystemdatenbankenEinbeziehen = @SystemdatenbankenEinbeziehen
            , @DatabaseNamePattern = @DatabaseNamePattern,@HighImpactConfirmed=@HighImpactConfirmed

            , @AnalysisClass = NULL
            , @StatusCode = @OverallStatus OUTPUT
            , @ErrorMessage = @OverallError OUTPUT
            , @CrossDatabaseRequested = @CrossDatabaseRequested OUTPUT,@CandidateTable=N'#CheckFrameworkCapabilities_DatabaseCandidates',@WarningTable=N'#CheckFrameworkCapabilities_DatabaseCandidateWarnings';
    END;

    DECLARE @Features TABLE
    (
          [RowNo] int IDENTITY(1,1) NOT NULL PRIMARY KEY
        , [FeatureOrdinal] smallint NOT NULL
        , [FeatureCode] varchar(64) NOT NULL
        , [FeatureName] nvarchar(200) NOT NULL
        , [ScopeType] varchar(16) NOT NULL
        , [AnalysisClass] varchar(64) NOT NULL
        , [AnalysisLevel] varchar(16) NOT NULL
        , [IsResourceIntensive] bit NOT NULL
        , [MinimumMajorVersion] tinyint NOT NULL
        , [RequiredPermissionScope] varchar(16) NOT NULL
        , [PermissionCheckType] varchar(24) NOT NULL
        , [RequiredPermission] sysname NULL
        , [PermissionDisplayText] nvarchar(128) NULL
        , [ExpectedWithoutPermission] varchar(32) NULL
        , [ProbeSqlTemplate] nvarchar(2000) NOT NULL
        , [EnablementSqlTemplate] nvarchar(2000) NULL
        , [Description] nvarchar(1000) NULL
        , [DatabaseName] sysname NULL
    );

    /* Eigene tempdb-/Tabellenvariablen-DDL bleibt außerhalb des No-Wait-Vertrags. */
    SET LOCK_TIMEOUT 0;

    IF @OverallStatus = 'AVAILABLE'
    BEGIN
        INSERT @Features
        (
              [FeatureOrdinal], [FeatureCode], [FeatureName], [ScopeType]
            , [AnalysisClass], [AnalysisLevel], [IsResourceIntensive]
            , [MinimumMajorVersion], [RequiredPermissionScope]
            , [PermissionCheckType], [RequiredPermission], [PermissionDisplayText]
            , [ExpectedWithoutPermission], [ProbeSqlTemplate]
            , [EnablementSqlTemplate], [Description], [DatabaseName]
        )
        SELECT
              [f].[FeatureOrdinal], [f].[FeatureCode], [f].[FeatureName], [f].[ScopeType]
            , [f].[AnalysisClass], [f].[AnalysisLevel], [f].[IsResourceIntensive]
            , [f].[MinimumMajorVersion]
            , CASE WHEN @Major >= 16 THEN [f].[PermissionScopeFromSql2022] ELSE [f].[PermissionScopeBeforeSql2022] END
            , CASE WHEN @Major >= 16 THEN [f].[PermissionCheckTypeFromSql2022] ELSE [f].[PermissionCheckTypeBeforeSql2022] END
            , CASE WHEN @Major >= 16 THEN [f].[PermissionNameFromSql2022] ELSE [f].[PermissionNameBeforeSql2022] END
            , CASE WHEN @Major >= 16 THEN [f].[PermissionDisplayTextFromSql2022] ELSE [f].[PermissionDisplayTextBeforeSql2022] END
            , [f].[ExpectedWithoutPermission], [f].[ProbeSqlTemplate]
            , [f].[EnablementSqlTemplate], [f].[Description], NULL
        FROM [monitor].[VW_FrameworkFeatureCatalog] AS [f]
        WHERE [f].[ScopeType] = 'SERVER'
          AND (@AnalyseKlasse IS NULL OR [f].[AnalysisClass] = @AnalyseKlasse)
        UNION ALL
        SELECT
              [f].[FeatureOrdinal], [f].[FeatureCode], [f].[FeatureName], [f].[ScopeType]
            , [f].[AnalysisClass], [f].[AnalysisLevel], [f].[IsResourceIntensive]
            , [f].[MinimumMajorVersion]
            , CASE WHEN @Major >= 16 THEN [f].[PermissionScopeFromSql2022] ELSE [f].[PermissionScopeBeforeSql2022] END
            , CASE WHEN @Major >= 16 THEN [f].[PermissionCheckTypeFromSql2022] ELSE [f].[PermissionCheckTypeBeforeSql2022] END
            , CASE WHEN @Major >= 16 THEN [f].[PermissionNameFromSql2022] ELSE [f].[PermissionNameBeforeSql2022] END
            , CASE WHEN @Major >= 16 THEN [f].[PermissionDisplayTextFromSql2022] ELSE [f].[PermissionDisplayTextBeforeSql2022] END
            , [f].[ExpectedWithoutPermission], [f].[ProbeSqlTemplate]
            , [f].[EnablementSqlTemplate], [f].[Description], [d].[DatabaseName]
        FROM [monitor].[VW_FrameworkFeatureCatalog] AS [f]
        CROSS JOIN [#CheckFrameworkCapabilities_DatabaseCandidates] AS [d]
        WHERE [f].[ScopeType] = 'DATABASE'
          AND (@AnalyseKlasse IS NULL OR [f].[AnalysisClass] = @AnalyseKlasse);
    END;

    DECLARE
          @i int = 1
        , @n int = (SELECT MAX([RowNo]) FROM @Features)
        , @FeatureOrdinal smallint
        , @FeatureCode varchar(64)
        , @FeatureName nvarchar(200)
        , @ScopeType varchar(16)
        , @Class varchar(64)
        , @Level varchar(16)
        , @Intensive bit
        , @MinVersion tinyint
        , @PermissionScope varchar(16)
        , @PermissionCheckType varchar(24)
        , @Permission sysname
        , @PermissionText nvarchar(128)
        , @Expected varchar(32)
        , @Probe nvarchar(2000)
        , @Enable nvarchar(2000)
        , @Description nvarchar(1000)
        , @DatabaseName sysname
        , @QuotedDatabaseName nvarchar(258)
        , @DatabaseLiteral nvarchar(260)
        , @GroupAllowed bit
        , @AccessReason varchar(20)
        , @HasPermission bit
        , @Queryable bit
        , @Enabled bit
        , @Usable bit
        , @Status varchar(40)
        , @ErrorNumber int
        , @ErrorMessage nvarchar(2048)
        , @Sql nvarchar(max);

    WHILE @OverallStatus = 'AVAILABLE' AND @i <= COALESCE(@n, 0)
    BEGIN
        SELECT
              @FeatureOrdinal = [FeatureOrdinal], @FeatureCode = [FeatureCode]
            , @FeatureName = [FeatureName], @ScopeType = [ScopeType]
            , @Class = [AnalysisClass], @Level = [AnalysisLevel]
            , @Intensive = [IsResourceIntensive], @MinVersion = [MinimumMajorVersion]
            , @PermissionScope = [RequiredPermissionScope]
            , @PermissionCheckType = [PermissionCheckType]
            , @Permission = [RequiredPermission], @PermissionText = [PermissionDisplayText]
            , @Expected = [ExpectedWithoutPermission], @Probe = [ProbeSqlTemplate]
            , @Enable = [EnablementSqlTemplate], @Description = [Description]
            , @DatabaseName = [DatabaseName]
        FROM @Features
        WHERE [RowNo] = @i;

        SELECT
              @QuotedDatabaseName = CASE WHEN @DatabaseName IS NULL THEN NULL ELSE QUOTENAME(@DatabaseName) END
            , @DatabaseLiteral = CASE WHEN @DatabaseName IS NULL THEN NULL ELSE REPLACE(@DatabaseName, N'''', N'''''') END
            , @GroupAllowed = 1, @AccessReason = 'OPEN', @HasPermission = NULL
            , @Queryable = 0, @Enabled = NULL, @Usable = 0
            , @Status = 'ERROR_HANDLED', @ErrorNumber = NULL, @ErrorMessage = NULL;

        IF @MitGruppenpruefung = 1
        BEGIN TRY
            SELECT @GroupAllowed = [IsAllowed], @AccessReason = [AccessReason]
            FROM [monitor].[VW_AnalyseAccessCurrent]
            WHERE [AnalysisClass] = @Class;
        END TRY
        BEGIN CATCH
            SELECT @GroupAllowed = 0, @AccessReason = 'CHECK_ERROR', @ErrorNumber = ERROR_NUMBER(), @ErrorMessage = ERROR_MESSAGE();
        END CATCH;

        IF @Major < @MinVersion
            SELECT @Status = 'UNAVAILABLE_VERSION', @ErrorMessage = CONCAT(N'Mindest-Major-Version ', @MinVersion, N'; erkannt ', COALESCE(CONVERT(nvarchar(20), @Major), N'unbekannt'), N'.');
        ELSE IF COALESCE(@GroupAllowed, 0) = 0
            SELECT @Status = 'DENIED_GROUP', @ErrorMessage = COALESCE(@ErrorMessage, N'Analyseklasse nicht freigegeben.');
        ELSE
        BEGIN
            IF @PermissionCheckType = 'HAS_PERMS_BY_NAME' AND @Permission IS NOT NULL
            BEGIN TRY
                IF @PermissionScope = 'SERVER'
                    SELECT @HasPermission = CONVERT(bit, HAS_PERMS_BY_NAME(NULL, NULL, @Permission));
                ELSE IF @PermissionScope = 'DATABASE'
                BEGIN
                    SET @Sql = N'USE ' + @QuotedDatabaseName + N'; SELECT @x=CONVERT(bit,HAS_PERMS_BY_NAME((SELECT [name] FROM [master].[sys].[databases] WITH (NOLOCK) WHERE [database_id] = DB_ID()),N''DATABASE'',@p));';
                    EXEC [sys].[sp_executesql] @Sql, N'@p sysname,@x bit OUTPUT', @p = @Permission, @x = @HasPermission OUTPUT;
                END;
            END TRY
            BEGIN CATCH
                SELECT @HasPermission = NULL, @ErrorNumber = ERROR_NUMBER(), @ErrorMessage = CONCAT(N'Berechtigungsprobe: ', ERROR_MESSAGE());
            END CATCH;

            BEGIN TRY
                SET @Sql = REPLACE(@Probe, N'' + N'$' + N'(DATABASE)', COALESCE(@QuotedDatabaseName, QUOTENAME((SELECT [name] FROM [master].[sys].[databases] WITH (NOLOCK) WHERE [database_id] = DB_ID()))));
                EXEC [sys].[sp_executesql] @Sql;
                SET @Queryable = 1;

                IF @Enable IS NOT NULL
                BEGIN
                    SET @Sql = REPLACE(REPLACE(@Enable, N'' + N'$' + N'(DATABASE)', COALESCE(@QuotedDatabaseName, QUOTENAME((SELECT [name] FROM [master].[sys].[databases] WITH (NOLOCK) WHERE [database_id] = DB_ID())))), N'' + N'$' + N'(DATABASENAME)', COALESCE(@DatabaseLiteral, REPLACE((SELECT [name] FROM [master].[sys].[databases] WITH (NOLOCK) WHERE [database_id] = DB_ID()), N'''', N'''''')));
                    EXEC [sys].[sp_executesql] @Sql, N'@IsEnabledOut bit OUTPUT', @IsEnabledOut = @Enabled OUTPUT;
                END;

                IF @Enabled = 0
                    SELECT @Status = 'AVAILABLE_DISABLED', @Usable = 0;
                ELSE IF @PermissionCheckType = 'PROBE_ONLY'
                    SELECT @Status = 'AVAILABLE_UNVERIFIED', @Usable = 1;
                ELSE IF @HasPermission = 0
                    SELECT @Status = CASE WHEN @Expected = 'LIMITED' THEN 'AVAILABLE_LIMITED' ELSE 'AVAILABLE_UNVERIFIED' END, @Usable = 1;
                ELSE
                    SELECT @Status = 'AVAILABLE', @Usable = 1;
            END TRY
            BEGIN CATCH
                SELECT
                      @Queryable = 0, @Usable = 0
                    , @ErrorNumber = ERROR_NUMBER(), @ErrorMessage = ERROR_MESSAGE()
                    , @Status = CASE
                        WHEN ERROR_NUMBER() IN (229,230,297,300,371,916,15151) THEN 'DENIED_PERMISSION'
                        WHEN ERROR_NUMBER() IN (911,924,927,942,976,978) THEN 'DATABASE_UNAVAILABLE'
                        WHEN ERROR_NUMBER() IN (207,208,195,2812,4121) THEN 'UNAVAILABLE_OBJECT'
                        WHEN ERROR_NUMBER() = 1222 THEN 'TIMEOUT'
                        ELSE 'ERROR_HANDLED' END;
            END CATCH;
        END;

        INSERT [#CheckFrameworkCapabilities_Capabilities]
        (
              [FeatureOrdinal], [FeatureCode], [FeatureName], [ScopeType]
            , [AnalysisClass], [AnalysisLevel], [IsResourceIntensive]
            , [DatabaseName], [ServerMajorVersion], [ServerProductVersion]
            , [MinimumMajorVersion], [VersionSupported], [GroupCheckApplied]
            , [GroupAccessAllowed], [AccessReason], [RequiredPermissionScope]
            , [PermissionCheckType], [RequiredPermission], [PermissionDisplayText]
            , [HasRequiredPermission], [IsQueryable], [IsFeatureEnabled]
            , [IsUsable], [StatusCode], [ErrorNumber], [ErrorMessage], [Description]
        )
        VALUES
        (
              @FeatureOrdinal, @FeatureCode, @FeatureName, @ScopeType
            , @Class, @Level, @Intensive, @DatabaseName, @Major, @ProductVersion
            , @MinVersion, CONVERT(bit, CASE WHEN @Major >= @MinVersion THEN 1 ELSE 0 END)
            , @MitGruppenpruefung, @GroupAllowed, @AccessReason, @PermissionScope
            , @PermissionCheckType, @Permission, @PermissionText, @HasPermission
            , @Queryable, @Enabled, @Usable, @Status, @ErrorNumber, @ErrorMessage
            , @Description
        );

        SET @i += 1;
    END;

    IF @OverallStatus = 'AVAILABLE'
       AND EXISTS (SELECT 1 FROM [#CheckFrameworkCapabilities_Capabilities] WHERE [IsUsable] = 0)
        SET @OverallStatus = 'AVAILABLE_LIMITED';

    IF @PrintMeldungen = 1 AND (@OverallError IS NOT NULL OR EXISTS (SELECT 1 FROM [#CheckFrameworkCapabilities_Capabilities] WHERE [IsUsable] = 0))
    BEGIN
        DECLARE @PrintMessage nvarchar(2048) = COALESCE(@OverallError, N'Mindestens eine Capability ist nicht vollständig nutzbar.');
        RAISERROR(N'%s', 10, 1, @PrintMessage) WITH NOWAIT;
    END;

    IF @ResultSetArtNormalisiert <> 'NONE'
    BEGIN
        SELECT
              CAST('2.0' AS varchar(16)) AS [ContractVersion]
            , @CollectionTimeUtc AS [CollectionTimeUtc]
            , N'monitor.USP_CheckFrameworkCapabilities' AS [ModuleName]
            , @OverallStatus AS [StatusCode]
            , CONVERT(bit, CASE WHEN @OverallStatus = 'AVAILABLE' THEN 0 ELSE 1 END) AS [IsPartial]
            , @OverallError AS [ErrorMessage];

        IF @ResultSetArtNormalisiert = 'RAW'
        BEGIN
            SELECT * FROM [#CheckFrameworkCapabilities_Capabilities]
            WHERE @NurNichtVerfuegbar = 0 OR [IsUsable] = 0
            ORDER BY [FeatureOrdinal], [DatabaseName];
            SELECT [StatusCode], COUNT_BIG(*) AS [FeatureCount], SUM(CONVERT(bigint,[IsQueryable])) AS [QueryableCount], SUM(CONVERT(bigint,[IsUsable])) AS [UsableCount]
            FROM [#CheckFrameworkCapabilities_Capabilities] GROUP BY [StatusCode] ORDER BY [StatusCode];
            SELECT * FROM [#CheckFrameworkCapabilities_DatabaseCandidateWarnings] ORDER BY [RequestedName];
        END;
        ELSE
        BEGIN
            SELECT
                  N'Framework-Capability' AS [Ergebnis]
                , [FeatureCode] AS [Feature]
                , [DatabaseName] AS [Datenbank]
                , [StatusCode] AS [Status]
                , [IsUsable] AS [nutzbar]
                , [PermissionDisplayText] AS [Berechtigung]
                , [ErrorMessage] AS [Hinweis]
            FROM [#CheckFrameworkCapabilities_Capabilities]
            WHERE @NurNichtVerfuegbar = 0 OR [IsUsable] = 0
            ORDER BY [FeatureOrdinal], [DatabaseName];

            SELECT N'Capability-Status' AS [Ergebnis], [StatusCode] AS [Status], COUNT_BIG(*) AS [Anzahl]
            FROM [#CheckFrameworkCapabilities_Capabilities] GROUP BY [StatusCode] ORDER BY [StatusCode];

            SELECT N'Datenbankwarnung' AS [Ergebnis], [RequestedName] AS [Datenbank], [StatusCode] AS [Status], [ErrorMessage] AS [Meldung]
            FROM [#CheckFrameworkCapabilities_DatabaseCandidateWarnings] ORDER BY [RequestedName];
        END;
    END;

    IF @JsonErzeugen = 1
    BEGIN
        DECLARE @MetaJson nvarchar(max) = (SELECT N'CheckFrameworkCapabilities' AS [resultName], 1 AS [schemaVersion], @CollectionTimeUtc AS [generatedAtUtc], @OverallStatus AS [statusCode], @OverallError AS [errorMessage] FOR JSON PATH, WITHOUT_ARRAY_WRAPPER, INCLUDE_NULL_VALUES);
        DECLARE @CapabilitiesJson nvarchar(max) = (SELECT * FROM [#CheckFrameworkCapabilities_Capabilities] WHERE @NurNichtVerfuegbar = 0 OR [IsUsable] = 0 ORDER BY [FeatureOrdinal], [DatabaseName] FOR JSON PATH, INCLUDE_NULL_VALUES);
        DECLARE @SummaryJson nvarchar(max) = (SELECT [StatusCode], COUNT_BIG(*) AS [FeatureCount], SUM(CONVERT(bigint,[IsQueryable])) AS [QueryableCount], SUM(CONVERT(bigint,[IsUsable])) AS [UsableCount] FROM [#CheckFrameworkCapabilities_Capabilities] GROUP BY [StatusCode] ORDER BY [StatusCode] FOR JSON PATH, INCLUDE_NULL_VALUES);
        DECLARE @WarningsJson nvarchar(max) = (SELECT * FROM [#CheckFrameworkCapabilities_DatabaseCandidateWarnings] ORDER BY [RequestedName] FOR JSON PATH, INCLUDE_NULL_VALUES);
        SET @Json = CONCAT(N'{"meta":', COALESCE(@MetaJson,N'{}'), N',"capabilities":', COALESCE(@CapabilitiesJson,N'[]'), N',"summary":', COALESCE(@SummaryJson,N'[]'), N',"warnings":', COALESCE(@WarningsJson,N'[]'), N'}');
    END;
    IF @ConsoleResultRequested = 1
    BEGIN
        EXEC [monitor].[InternalEmitConsoleResult]
              @SourceTable=N'#CheckFrameworkCapabilities_Capabilities'
            , @ResultLabel=N'CheckFrameworkCapabilities'
            , @EmptyMessage=N'Keine fachlichen Ergebnisse';
    END;
    IF @TableResultRequested = 1
    BEGIN
        EXEC [monitor].[InternalWriteResultTable]
              @SourceTable = N'#CheckFrameworkCapabilities_Capabilities'
            , @TargetTable=@TableTarget
            , @ThrowOnError = 1;
    END;
END;
GO
-- END SOURCE: Code/01_Common/070_USP_CheckFrameworkCapabilities.sql

-- BEGIN SOURCE: Code/01_Common/100_USP_AnalysisNavigator.sql
/*
===============================================================================
Objekt       : monitor.USP_AnalysisNavigator
Version      : 1.0.0
Stand        : 2026-07-21
Typ          : Stored Procedure
Zweck        : Findet priorisierte Analyse-Procedures nach Symptom, Ziel,
               Fachbegriff, Themenbereich, Scope oder Navigationsrolle.
SQL-Version  : SQL Server 2019 oder neuer.
Datenquellen : monitor.VW_AnalysisCatalog,
               monitor.VW_AnalysisSearchTerm,
               monitor.VW_AnalysisRelation,
               monitor.VW_AnalyseClassCatalog,
               sys.schemas, sys.procedures.
Sicherheit   : Führt keine gefundene Procedure aus. Liest keine produktiven
               DMVs, Benutzerkataloge, Querytexte, Pläne oder Ereignisdaten.
Suche        : Explizit case- und accent-insensitiv; unabhängig von der
               Datenbankcollation. Deutsch- und englischsprachige Begriffe.
Resultsets   : RAW: Modulstatus und navigation. CONSOLE: navigation oder eine
               verständliche Leerzeile. TABLE: navigation. NONE: keine.
JSON         : meta, navigation.
Berechtigung : Nur lesender Zugriff auf Framework- und lokale Systemmetadaten.
Eigenlast    : Gering; ausschließlich konstanter Katalog und lokale
               Installationsprüfung.
Locking      : LOCK_TIMEOUT 0; Systemkatalogzugriffe WITH (NOLOCK).
===============================================================================
*/
CREATE OR ALTER PROCEDURE [monitor].[USP_AnalysisNavigator]
      @Suchbegriff       nvarchar(4000) = NULL
    , @Bereich           varchar(40)    = NULL
    , @Scope             varchar(40)    = NULL
    , @Navigationsrolle  varchar(24)    = NULL
    , @NurInstallierte   bit            = 0
    , @MaxZeilen         int            = 12
    , @ResultSetArt      varchar(16)    = 'CONSOLE'
    , @ResultTablesJson  nvarchar(max)  = NULL
    , @JsonErzeugen      bit            = 0
    , @Json              nvarchar(max)  = NULL OUTPUT
    , @PrintMeldungen    bit            = 1
    , @Hilfe             bit            = 0
AS
BEGIN
    SET NOCOUNT ON;

    SET @Json = NULL;

    DECLARE @ResultSetArtNormalisiert varchar(16) =
        UPPER(LTRIM(RTRIM(COALESCE(@ResultSetArt, ''))));
    DECLARE @TableResultRequested bit =
        CASE WHEN @ResultSetArtNormalisiert = 'TABLE' THEN 1 ELSE 0 END;
    DECLARE @ConsoleResultRequested bit =
        CASE WHEN @ResultSetArtNormalisiert = 'CONSOLE' THEN 1 ELSE 0 END;
    DECLARE @TableTarget sysname = NULL;

    IF @TableResultRequested = 0
       AND NULLIF(LTRIM(RTRIM(COALESCE(@ResultTablesJson, N''))), N'') IS NOT NULL
        THROW 51011, N'@ResultTablesJson ist ausschließlich mit @ResultSetArt=TABLE zulässig.', 1;

    IF @TableResultRequested = 1
        EXEC [monitor].[InternalPrepareSingleResultTable]
              @ResultTablesJson = @ResultTablesJson
            , @ResultName = N'navigation'
            , @TargetTable = @TableTarget OUTPUT
            , @ThrowOnError = 1;

    IF @TableResultRequested = 1 OR @ConsoleResultRequested = 1
        SET @ResultSetArtNormalisiert = 'NONE';

    IF @Hilfe = 1
    BEGIN
        PRINT N'monitor.USP_AnalysisNavigator';
        PRINT N'Die Procedure dient als Wegweiser und führt keine gefundene Analyse aus.';
        PRINT N'Ohne Filter werden priorisierte, sichere Einstiege angezeigt.';
        PRINT N'@Suchbegriff: deutsches oder englisches Symptom, Ziel, Objektname oder Fachbegriff; maximal 400 Zeichen.';
        PRINT N'@Bereich: Code aus VW_AnalysisCatalog.PrimaryAreaCode, zum Beispiel LIVE, PLAN, OBJECT, OPERATIONS oder SERVER.';
        PRINT N'@Scope: Code aus VW_AnalysisCatalog.ScopeCode, zum Beispiel SERVER, DATABASE, SESSION_REQUEST oder PLAN_XML.';
        PRINT N'@Navigationsrolle: ENTRY, FOLLOW_UP, TARGETED, SETUP oder SUPPORT.';
        PRINT N'@NurInstallierte=0 zeigt auch optionale, nicht installierte Pakete; 1 beschränkt auf lokal vorhandene Procedures.';
        PRINT N'@MaxZeilen: NULL oder 0 vollständig, sonst 1 bis 100; Default 12.';
        PRINT N'@ResultSetArt: CONSOLE (Default), RAW, TABLE oder NONE; TABLE erwartet {"navigation":"#Zieltabelle"}.';
        PRINT N'@JsonErzeugen=1 setzt @Json OUTPUT mit meta und navigation.';
        PRINT N'Beispiel: EXEC [monitor].[USP_AnalysisNavigator] @Suchbegriff=N''Benutzer warten'';';
        RETURN;
    END;

    DECLARE @CollectionTimeUtc datetime2(3) = SYSUTCDATETIME();
    DECLARE @StatusCode varchar(40) = 'AVAILABLE';
    DECLARE @IsPartial bit = 0;
    DECLARE @ErrorNumber int = NULL;
    DECLARE @ErrorMessage nvarchar(2048) = NULL;

    DECLARE @SuchbegriffNormalisiert nvarchar(4000) =
        NULLIF(LTRIM(RTRIM(COALESCE(@Suchbegriff, N''))), N'');
    DECLARE @SuchbegriffVergleich nvarchar(4000) = @SuchbegriffNormalisiert;
    DECLARE @BereichNormalisiert varchar(40) =
        NULLIF(UPPER(LTRIM(RTRIM(COALESCE(@Bereich, '')))), '');
    DECLARE @ScopeNormalisiert varchar(40) =
        NULLIF(UPPER(LTRIM(RTRIM(COALESCE(@Scope, '')))), '');
    DECLARE @RolleNormalisiert varchar(24) =
        NULLIF(UPPER(LTRIM(RTRIM(COALESCE(@Navigationsrolle, '')))), '');
    DECLARE @HasSearch bit = CASE WHEN @SuchbegriffNormalisiert IS NULL THEN 0 ELSE 1 END;
    DECLARE @HasFilter bit = CASE
        WHEN @BereichNormalisiert IS NOT NULL
          OR @ScopeNormalisiert IS NOT NULL
          OR @RolleNormalisiert IS NOT NULL THEN 1 ELSE 0 END;
    DECLARE @MaxZeilenEffektiv int = CASE
        WHEN @MaxZeilen IS NULL OR @MaxZeilen = 0 THEN 2147483647
        ELSE @MaxZeilen
    END;

    IF @SuchbegriffVergleich IS NOT NULL
    BEGIN
        SET @SuchbegriffVergleich = REPLACE(REPLACE(@SuchbegriffVergleich, N'[', N''), N']', N'');
        IF LEFT(@SuchbegriffVergleich, 8) COLLATE Latin1_General_100_CI_AI = N'monitor.'
            SET @SuchbegriffVergleich = SUBSTRING(@SuchbegriffVergleich, 9, 4000);
    END;

    CREATE TABLE [#AnalysisNavigator_SearchToken]
    (
        [Token] nvarchar(200) COLLATE Latin1_General_100_CI_AI NOT NULL PRIMARY KEY
    );

    CREATE TABLE [#AnalysisNavigator_Navigation]
    (
          [Rank]                              int             NOT NULL
        , [RelevanceScore]                    int             NOT NULL
        , [ProcedureName]                     sysname         NOT NULL
        , [DisplayName]                       nvarchar(160)   NOT NULL
        , [NavigationRole]                    varchar(24)     NOT NULL
        , [PrimaryAreaCode]                   varchar(40)     NOT NULL
        , [PrimaryAreaName]                   nvarchar(160)   NOT NULL
        , [ScopeCode]                         varchar(40)     NOT NULL
        , [EvidenceType]                      varchar(40)     NOT NULL
        , [CostRangeCode]                     varchar(32)     NOT NULL
        , [RepresentativeAnalysisClass]       varchar(64)     NULL
        , [AnalysisLevel]                     varchar(16)     NULL
        , [RequiresGroupGate]                 bit             NULL
        , [WhyMatched]                        nvarchar(500)   NOT NULL
        , [Purpose]                           nvarchar(1000)  NOT NULL
        , [PrerequisiteSummary]               nvarchar(1000)  NOT NULL
        , [RequiresKnownTarget]               bit             NOT NULL
        , [RequiresHighImpactForSafeStart]    bit             NOT NULL
        , [HighImpactPathAvailable]           bit             NOT NULL
        , [PackageCode]                       varchar(32)     NOT NULL
        , [IsInstalled]                       bit             NOT NULL
        , [SafeCall]                          nvarchar(2000)  NOT NULL
        , [NextProcedureName]                 sysname         NULL
        , [RelationType]                      varchar(24)     NULL
        , [NextStep]                          nvarchar(700)   NULL
        , [RunbookPath]                       nvarchar(400)   NULL
        , [DocumentationPath]                 nvarchar(400)   NOT NULL
    );

    IF @ResultSetArtNormalisiert NOT IN ('RAW', 'CONSOLE', 'NONE')
    BEGIN
        SELECT
              @StatusCode = 'INVALID_PARAMETER'
            , @IsPartial = 1
            , @ErrorMessage = N'@ResultSetArt muss CONSOLE, RAW, TABLE oder NONE enthalten.';
    END;
    ELSE IF @MaxZeilen < 0 OR @MaxZeilen > 100
    BEGIN
        SELECT
              @StatusCode = 'INVALID_PARAMETER'
            , @IsPartial = 1
            , @ErrorMessage = N'@MaxZeilen muss NULL, 0 oder ein Wert zwischen 1 und 100 sein.';
    END;
    ELSE IF @NurInstallierte IS NULL
    BEGIN
        SELECT
              @StatusCode = 'INVALID_PARAMETER'
            , @IsPartial = 1
            , @ErrorMessage = N'@NurInstallierte darf nicht NULL sein.';
    END;
    ELSE IF @SuchbegriffNormalisiert IS NOT NULL AND LEN(@SuchbegriffNormalisiert) > 400
    BEGIN
        SELECT
              @StatusCode = 'INVALID_PARAMETER'
            , @IsPartial = 1
            , @ErrorMessage = N'@Suchbegriff darf höchstens 400 Zeichen enthalten.';
    END;
    ELSE IF @BereichNormalisiert IS NOT NULL
        AND NOT EXISTS
        (
            SELECT 1
            FROM [monitor].[VW_AnalysisCatalog] AS [c]
            WHERE [c].[PrimaryAreaCode] COLLATE Latin1_General_100_CI_AI =
                  @BereichNormalisiert COLLATE Latin1_General_100_CI_AI
        )
    BEGIN
        SELECT
              @StatusCode = 'INVALID_PARAMETER'
            , @IsPartial = 1
            , @ErrorMessage = N'@Bereich ist unbekannt. Gültige Codes stehen in monitor.VW_AnalysisCatalog.PrimaryAreaCode.';
    END;
    ELSE IF @ScopeNormalisiert IS NOT NULL
        AND NOT EXISTS
        (
            SELECT 1
            FROM [monitor].[VW_AnalysisCatalog] AS [c]
            WHERE [c].[ScopeCode] COLLATE Latin1_General_100_CI_AI =
                  @ScopeNormalisiert COLLATE Latin1_General_100_CI_AI
        )
    BEGIN
        SELECT
              @StatusCode = 'INVALID_PARAMETER'
            , @IsPartial = 1
            , @ErrorMessage = N'@Scope ist unbekannt. Gültige Codes stehen in monitor.VW_AnalysisCatalog.ScopeCode.';
    END;
    ELSE IF @RolleNormalisiert IS NOT NULL
        AND @RolleNormalisiert NOT IN ('ENTRY', 'FOLLOW_UP', 'TARGETED', 'SETUP', 'SUPPORT')
    BEGIN
        SELECT
              @StatusCode = 'INVALID_PARAMETER'
            , @IsPartial = 1
            , @ErrorMessage = N'@Navigationsrolle muss ENTRY, FOLLOW_UP, TARGETED, SETUP oder SUPPORT enthalten.';
    END;

    SET LOCK_TIMEOUT 0;

    IF @StatusCode = 'AVAILABLE' AND @HasSearch = 1
    BEGIN
        INSERT [#AnalysisNavigator_SearchToken]([Token])
        SELECT DISTINCT
            CONVERT(nvarchar(200), LEFT(LTRIM(RTRIM([s].[value])), 200))
                COLLATE Latin1_General_100_CI_AI
        FROM STRING_SPLIT(@SuchbegriffNormalisiert, N' ') AS [s]
        WHERE LEN(LTRIM(RTRIM([s].[value]))) >= 3
          AND LTRIM(RTRIM([s].[value])) COLLATE Latin1_General_100_CI_AI NOT IN
              (N'der',N'die',N'das',N'den',N'dem',N'des',N'ein',N'eine',N'einer',N'einem',N'und',N'oder',N'mit',N'von',N'ist',N'sind',N'bei',N'für',N'was',N'wie',N'the',N'and',N'for',N'with',N'from',N'use');
    END;

    DECLARE @TokenCount int =
        (SELECT COUNT(*) FROM [#AnalysisNavigator_SearchToken]);

    IF @StatusCode = 'AVAILABLE'
    BEGIN TRY
        ;WITH [Candidate] AS
        (
            SELECT
                  [c].[ProcedureName]
                , [c].[DisplayName]
                , [c].[NavigationRole]
                , [c].[PrimaryAreaCode]
                , [c].[PrimaryAreaName]
                , [c].[ScopeCode]
                , [c].[EvidenceType]
                , [c].[CostRangeCode]
                , [c].[RepresentativeAnalysisClass]
                , [ac].[AnalysisLevel]
                , [ac].[RequiresGroupGate]
                , [c].[Purpose]
                , [c].[PrerequisiteSummary]
                , [c].[RequiresKnownTarget]
                , [c].[RequiresHighImpactForSafeStart]
                , [c].[HighImpactPathAvailable]
                , [c].[PackageCode]
                , CONVERT(bit, CASE WHEN [p].[object_id] IS NULL THEN 0 ELSE 1 END) AS [IsInstalled]
                , [c].[SafeCall]
                , [nr].[ToProcedureName] AS [NextProcedureName]
                , [nr].[RelationType]
                , [nr].[ConditionSummary] AS [NextStep]
                , [c].[RunbookPath]
                , [c].[DocumentationPath]
                , CONVERT(nvarchar(500),
                    CASE
                        WHEN @HasSearch = 0 AND @HasFilter = 0
                            THEN N'Priorisierter, sicherer Einstieg in die Frameworkanalyse.'
                        WHEN @HasSearch = 0
                            THEN CONCAT(N'Passend zu Bereich, Scope oder Navigationsrolle: ', [c].[PrimaryAreaName], N'.')
                        WHEN [c].[ProcedureName] COLLATE Latin1_General_100_CI_AI =
                             @SuchbegriffVergleich COLLATE Latin1_General_100_CI_AI
                            THEN N'Der Suchbegriff entspricht dem technischen Procedurenamen.'
                        WHEN [c].[DisplayName] COLLATE Latin1_General_100_CI_AI =
                             @SuchbegriffNormalisiert COLLATE Latin1_General_100_CI_AI
                            THEN N'Der Suchbegriff entspricht dem fachlichen Anzeigenamen.'
                        WHEN [tm].[MatchReason] IS NOT NULL THEN [tm].[MatchReason]
                        WHEN [tk].[TokenMatchCount] > 0
                            THEN CONCAT([tk].[TokenMatchCount], N' wesentliche Suchbegriffe passen zu Zweck, Scope oder Synonymen.')
                        ELSE N'Der Suchbegriff passt zu den fachlichen Katalogmetadaten.'
                    END) AS [WhyMatched]
                , CONVERT(int,
                    CASE
                        WHEN @HasSearch = 0 AND @HasFilter = 0
                            THEN 2000 - COALESCE([c].[DefaultRank], 1000)
                        WHEN @HasSearch = 0
                            THEN CASE [c].[NavigationRole]
                                    WHEN 'ENTRY' THEN 800
                                    WHEN 'FOLLOW_UP' THEN 700
                                    WHEN 'TARGETED' THEN 600
                                    WHEN 'SETUP' THEN 500
                                    ELSE 400
                                 END
                        ELSE
                              CASE
                                  WHEN [c].[ProcedureName] COLLATE Latin1_General_100_CI_AI =
                                       @SuchbegriffVergleich COLLATE Latin1_General_100_CI_AI THEN 2400
                                  WHEN [c].[DisplayName] COLLATE Latin1_General_100_CI_AI =
                                       @SuchbegriffNormalisiert COLLATE Latin1_General_100_CI_AI THEN 2300
                                  WHEN CHARINDEX(@SuchbegriffVergleich COLLATE Latin1_General_100_CI_AI,
                                                 [c].[ProcedureName] COLLATE Latin1_General_100_CI_AI) > 0 THEN 900
                                  WHEN CHARINDEX(@SuchbegriffNormalisiert COLLATE Latin1_General_100_CI_AI,
                                                 [c].[DisplayName] COLLATE Latin1_General_100_CI_AI) > 0 THEN 850
                                  WHEN CHARINDEX(@SuchbegriffNormalisiert COLLATE Latin1_General_100_CI_AI,
                                                 [c].[Purpose] COLLATE Latin1_General_100_CI_AI) > 0 THEN 700
                                  WHEN CHARINDEX(@SuchbegriffNormalisiert COLLATE Latin1_General_100_CI_AI,
                                                 [c].[PrerequisiteSummary] COLLATE Latin1_General_100_CI_AI) > 0 THEN 600
                                  ELSE 0
                              END
                            + COALESCE([tm].[TermMatchScore], 0)
                            + COALESCE([tk].[TokenMatchCount], 0) * 80
                            + CASE WHEN @TokenCount > 0 AND [tk].[TokenMatchCount] = @TokenCount THEN 300 ELSE 0 END
                            + CASE [c].[NavigationRole]
                                  WHEN 'ENTRY' THEN 50
                                  WHEN 'FOLLOW_UP' THEN 35
                                  WHEN 'TARGETED' THEN 20
                                  WHEN 'SETUP' THEN 10
                                  ELSE 0
                              END
                    END) AS [RelevanceScore]
            FROM [monitor].[VW_AnalysisCatalog] AS [c]
            LEFT JOIN [monitor].[VW_AnalyseClassCatalog] AS [ac]
              ON [ac].[AnalysisClass] = [c].[RepresentativeAnalysisClass]
            LEFT JOIN [sys].[schemas] AS [s] WITH (NOLOCK)
              ON [s].[name] = N'monitor'
            LEFT JOIN [sys].[procedures] AS [p] WITH (NOLOCK)
              ON [p].[schema_id] = [s].[schema_id]
             AND [p].[name] = [c].[ProcedureName]
            OUTER APPLY
            (
                SELECT TOP (1)
                      [st].[MatchReason]
                    , CONVERT(int,
                        CASE
                            WHEN [st].[SearchTerm] COLLATE Latin1_General_100_CI_AI =
                                 @SuchbegriffNormalisiert COLLATE Latin1_General_100_CI_AI
                                THEN 1500 + [st].[SearchWeight]
                            WHEN CHARINDEX(@SuchbegriffNormalisiert COLLATE Latin1_General_100_CI_AI,
                                           [st].[SearchTerm] COLLATE Latin1_General_100_CI_AI) > 0
                                THEN 1200 + [st].[SearchWeight]
                            WHEN LEN([st].[SearchTerm]) >= 4
                             AND CHARINDEX([st].[SearchTerm] COLLATE Latin1_General_100_CI_AI,
                                           @SuchbegriffNormalisiert COLLATE Latin1_General_100_CI_AI) > 0
                                THEN 1100 + [st].[SearchWeight]
                            ELSE 0
                        END) AS [TermMatchScore]
                FROM [monitor].[VW_AnalysisSearchTerm] AS [st]
                WHERE @HasSearch = 1
                  AND [st].[ProcedureName] = [c].[ProcedureName]
                  AND
                  (
                      [st].[SearchTerm] COLLATE Latin1_General_100_CI_AI =
                          @SuchbegriffNormalisiert COLLATE Latin1_General_100_CI_AI
                      OR CHARINDEX(@SuchbegriffNormalisiert COLLATE Latin1_General_100_CI_AI,
                                   [st].[SearchTerm] COLLATE Latin1_General_100_CI_AI) > 0
                      OR
                      (
                          LEN([st].[SearchTerm]) >= 4
                          AND CHARINDEX([st].[SearchTerm] COLLATE Latin1_General_100_CI_AI,
                                        @SuchbegriffNormalisiert COLLATE Latin1_General_100_CI_AI) > 0
                      )
                  )
                ORDER BY [TermMatchScore] DESC, [st].[SearchWeight] DESC, [st].[SearchTerm]
            ) AS [tm]
            OUTER APPLY
            (
                SELECT CONVERT(int, COUNT(*)) AS [TokenMatchCount]
                FROM [#AnalysisNavigator_SearchToken] AS [t]
                WHERE CHARINDEX([t].[Token], [c].[ProcedureName] COLLATE Latin1_General_100_CI_AI) > 0
                   OR CHARINDEX([t].[Token], [c].[DisplayName] COLLATE Latin1_General_100_CI_AI) > 0
                   OR CHARINDEX([t].[Token], [c].[PrimaryAreaName] COLLATE Latin1_General_100_CI_AI) > 0
                   OR CHARINDEX([t].[Token], [c].[Purpose] COLLATE Latin1_General_100_CI_AI) > 0
                   OR EXISTS
                      (
                          SELECT 1
                          FROM [monitor].[VW_AnalysisSearchTerm] AS [st]
                          WHERE [st].[ProcedureName] = [c].[ProcedureName]
                            AND CHARINDEX([t].[Token], [st].[SearchTerm] COLLATE Latin1_General_100_CI_AI) > 0
                      )
            ) AS [tk]
            OUTER APPLY
            (
                SELECT TOP (1)
                      [r].[ToProcedureName]
                    , [r].[RelationType]
                    , [r].[ConditionSummary]
                FROM [monitor].[VW_AnalysisRelation] AS [r]
                WHERE [r].[FromProcedureName] = [c].[ProcedureName]
                ORDER BY
                      CASE [r].[RelationType]
                          WHEN 'REFINE_WITH' THEN 1
                          WHEN 'CONFIRM_WITH' THEN 2
                          WHEN 'PREPARE_WITH' THEN 3
                          ELSE 4
                      END
                    , [r].[RelationPriority]
                    , [r].[ToProcedureName]
            ) AS [nr]
            WHERE [c].[ProcedureName] <> N'USP_AnalysisNavigator'
              AND (@BereichNormalisiert IS NULL OR
                   [c].[PrimaryAreaCode] COLLATE Latin1_General_100_CI_AI =
                   @BereichNormalisiert COLLATE Latin1_General_100_CI_AI)
              AND (@ScopeNormalisiert IS NULL OR
                   [c].[ScopeCode] COLLATE Latin1_General_100_CI_AI =
                   @ScopeNormalisiert COLLATE Latin1_General_100_CI_AI)
              AND (@RolleNormalisiert IS NULL OR
                   [c].[NavigationRole] COLLATE Latin1_General_100_CI_AI =
                   @RolleNormalisiert COLLATE Latin1_General_100_CI_AI)
              AND (@NurInstallierte = 0 OR [p].[object_id] IS NOT NULL)
              AND (@HasSearch = 1 OR @HasFilter = 1 OR [c].[DefaultRank] IS NOT NULL)
        ),
        [Limited] AS
        (
            SELECT TOP (@MaxZeilenEffektiv) *
            FROM [Candidate]
            WHERE @HasSearch = 0 OR [RelevanceScore] > 0
            ORDER BY
                  [RelevanceScore] DESC
                , CASE [NavigationRole]
                      WHEN 'ENTRY' THEN 1
                      WHEN 'FOLLOW_UP' THEN 2
                      WHEN 'TARGETED' THEN 3
                      WHEN 'SETUP' THEN 4
                      ELSE 5
                  END
                , [DisplayName]
                , [ProcedureName]
        )
        INSERT [#AnalysisNavigator_Navigation]
        (
              [Rank], [RelevanceScore], [ProcedureName], [DisplayName]
            , [NavigationRole], [PrimaryAreaCode], [PrimaryAreaName], [ScopeCode]
            , [EvidenceType], [CostRangeCode], [RepresentativeAnalysisClass]
            , [AnalysisLevel], [RequiresGroupGate], [WhyMatched], [Purpose]
            , [PrerequisiteSummary], [RequiresKnownTarget]
            , [RequiresHighImpactForSafeStart], [HighImpactPathAvailable]
            , [PackageCode], [IsInstalled], [SafeCall], [NextProcedureName]
            , [RelationType], [NextStep], [RunbookPath], [DocumentationPath]
        )
        SELECT
              CONVERT(int, ROW_NUMBER() OVER
              (
                  ORDER BY
                        [RelevanceScore] DESC
                      , CASE [NavigationRole]
                            WHEN 'ENTRY' THEN 1
                            WHEN 'FOLLOW_UP' THEN 2
                            WHEN 'TARGETED' THEN 3
                            WHEN 'SETUP' THEN 4
                            ELSE 5
                        END
                      , [DisplayName]
                      , [ProcedureName]
              )) AS [Rank]
            , [RelevanceScore], [ProcedureName], [DisplayName]
            , [NavigationRole], [PrimaryAreaCode], [PrimaryAreaName], [ScopeCode]
            , [EvidenceType], [CostRangeCode], [RepresentativeAnalysisClass]
            , [AnalysisLevel], [RequiresGroupGate], [WhyMatched], [Purpose]
            , [PrerequisiteSummary], [RequiresKnownTarget]
            , [RequiresHighImpactForSafeStart], [HighImpactPathAvailable]
            , [PackageCode], [IsInstalled], [SafeCall], [NextProcedureName]
            , [RelationType], [NextStep], [RunbookPath], [DocumentationPath]
        FROM [Limited];

        IF NOT EXISTS (SELECT 1 FROM [#AnalysisNavigator_Navigation])
        BEGIN
            SELECT
                  @StatusCode = 'NO_MATCH'
                , @IsPartial = 0
                , @ErrorMessage = N'Für die gewählte Suche und die aktiven Filter wurde kein Katalogtreffer gefunden.';
        END;
    END TRY
    BEGIN CATCH
        SELECT
              @StatusCode = CASE WHEN ERROR_NUMBER() = 1222 THEN 'LOCK_TIMEOUT' ELSE 'ERROR_HANDLED' END
            , @IsPartial = 1
            , @ErrorNumber = ERROR_NUMBER()
            , @ErrorMessage = ERROR_MESSAGE();

        IF @PrintMeldungen = 1
            RAISERROR(N'Der Analysis Navigator konnte den Katalog nicht vollständig auswerten: %s', 10, 1, @ErrorMessage) WITH NOWAIT;
    END CATCH;

    IF @ResultSetArtNormalisiert <> 'NONE'
    BEGIN
        SELECT
              @CollectionTimeUtc AS [CollectionTimeUtc]
            , CAST(N'monitor.USP_AnalysisNavigator' AS nvarchar(256)) AS [ModuleName]
            , @StatusCode AS [StatusCode]
            , @IsPartial AS [IsPartial]
            , @ErrorNumber AS [ErrorNumber]
            , @ErrorMessage AS [ErrorMessage]
            , @SuchbegriffNormalisiert AS [SearchTerm]
            , @BereichNormalisiert AS [AreaFilter]
            , @ScopeNormalisiert AS [ScopeFilter]
            , @RolleNormalisiert AS [RoleFilter]
            , @NurInstallierte AS [InstalledOnly]
            , @MaxZeilen AS [MaxRows];

        IF @ResultSetArtNormalisiert = 'RAW'
        BEGIN
            SELECT
                  [Rank], [RelevanceScore], [ProcedureName], [DisplayName]
                , [NavigationRole], [PrimaryAreaCode], [PrimaryAreaName], [ScopeCode]
                , [EvidenceType], [CostRangeCode], [RepresentativeAnalysisClass]
                , [AnalysisLevel], [RequiresGroupGate], [WhyMatched], [Purpose]
                , [PrerequisiteSummary], [RequiresKnownTarget]
                , [RequiresHighImpactForSafeStart], [HighImpactPathAvailable]
                , [PackageCode], [IsInstalled], [SafeCall], [NextProcedureName]
                , [RelationType], [NextStep], [RunbookPath], [DocumentationPath]
            FROM [#AnalysisNavigator_Navigation]
            ORDER BY [Rank];
        END;
        ELSE
        BEGIN
            SELECT
                  [Rank], [RelevanceScore], [ProcedureName], [DisplayName]
                , [NavigationRole], [PrimaryAreaCode], [PrimaryAreaName], [ScopeCode]
                , [EvidenceType], [CostRangeCode], [RepresentativeAnalysisClass]
                , [AnalysisLevel], [RequiresGroupGate], [WhyMatched], [Purpose]
                , [PrerequisiteSummary], [RequiresKnownTarget]
                , [RequiresHighImpactForSafeStart], [HighImpactPathAvailable]
                , [PackageCode], [IsInstalled], [SafeCall], [NextProcedureName]
                , [RelationType], [NextStep], [RunbookPath], [DocumentationPath]
            FROM [#AnalysisNavigator_Navigation]
            ORDER BY [Rank];
        END;
    END;

    IF @JsonErzeugen = 1
    BEGIN
        DECLARE @MetaJson nvarchar(max) =
        (
            SELECT
                  N'AnalysisNavigator' AS [resultName]
                , 1 AS [schemaVersion]
                , @CollectionTimeUtc AS [generatedAtUtc]
                , @StatusCode AS [statusCode]
                , @IsPartial AS [isPartial]
                , @ErrorNumber AS [errorNumber]
                , @ErrorMessage AS [errorMessage]
                , @SuchbegriffNormalisiert AS [searchTerm]
                , @BereichNormalisiert AS [areaFilter]
                , @ScopeNormalisiert AS [scopeFilter]
                , @RolleNormalisiert AS [roleFilter]
                , @NurInstallierte AS [installedOnly]
                , @MaxZeilen AS [maxRows]
            FOR JSON PATH, WITHOUT_ARRAY_WRAPPER, INCLUDE_NULL_VALUES
        );

        DECLARE @NavigationJson nvarchar(max) =
        (
            SELECT
                  [Rank], [RelevanceScore], [ProcedureName], [DisplayName]
                , [NavigationRole], [PrimaryAreaCode], [PrimaryAreaName], [ScopeCode]
                , [EvidenceType], [CostRangeCode], [RepresentativeAnalysisClass]
                , [AnalysisLevel], [RequiresGroupGate], [WhyMatched], [Purpose]
                , [PrerequisiteSummary], [RequiresKnownTarget]
                , [RequiresHighImpactForSafeStart], [HighImpactPathAvailable]
                , [PackageCode], [IsInstalled], [SafeCall], [NextProcedureName]
                , [RelationType], [NextStep], [RunbookPath], [DocumentationPath]
            FROM [#AnalysisNavigator_Navigation]
            ORDER BY [Rank]
            FOR JSON PATH, INCLUDE_NULL_VALUES
        );

        SET @Json = CONCAT
        (
              N'{"meta":', COALESCE(@MetaJson, N'{}')
            , N',"navigation":', COALESCE(@NavigationJson, N'[]')
            , N'}'
        );
    END;

    IF @ConsoleResultRequested = 1
    BEGIN
        EXEC [monitor].[InternalEmitConsoleResult]
              @SourceTable = N'#AnalysisNavigator_Navigation'
            , @ResultLabel = N'Analysis Navigator'
            , @EmptyMessage = N'Keine passende Analyse gefunden'
            , @StatusCode = @StatusCode
            , @StatusMessage = @ErrorMessage;
    END;

    IF @TableResultRequested = 1
    BEGIN
        EXEC [monitor].[InternalWriteResultTable]
              @SourceTable = N'#AnalysisNavigator_Navigation'
            , @TargetTable = @TableTarget
            , @ThrowOnError = 1;
    END;
END;
GO
-- END SOURCE: Code/01_Common/100_USP_AnalysisNavigator.sql

-- BEGIN SOURCE: Code/02_CurrentState/005_InternalCaptureCurrentStateSnapshot.sql
/*
===============================================================================
Objekt       : monitor.InternalCaptureCurrentStateSnapshot
Version      : 2.1.0
Stand        : 2026-07-23
Typ          : Interne Stored Procedure
Zweck        : Schreibt die vom aufrufenden Orchestrator angelegten lokalen
               Snapshot-Tabellen. Jede aktivierte Systemquelle wird genau
               einmal gelesen; nicht angeforderte Quellen werden nicht berührt.
               SQL25-003 ergänzt den vorhandenen Workload-Group-Snapshot
               versions- und capability-adaptiv.
Lebensdauer  : Der Aufrufer besitzt die lokalen Temp-Tabellen. Sie verschwinden
               mit dessen Procedure-Scope und können von einem späteren
               Einzelaufruf nicht wiederverwendet werden.
Sicherheit   : Read-only. Keine Konfiguration, Persistenz oder Rechtevergabe.
===============================================================================
*/
CREATE OR ALTER PROCEDURE [monitor].[InternalCaptureCurrentStateSnapshot]
      @SnapshotId              uniqueidentifier
    , @CaptureSessions         bit = 0
    , @CaptureRequests         bit = 0
    , @CaptureConnections      bit = 0
    , @CaptureWaitingTasks     bit = 0
    , @CaptureMemoryGrants     bit = 0
    , @CaptureResourceGovernor bit = 0
    , @CaptureTasks            bit = 0
    , @CaptureSchedulers       bit = 0
    , @CaptureTransactions     bit = 0
    , @CaptureTempDbUsage      bit = 0
    , @CaptureSqlText          bit = 0
    , @MaxSqlTextHandles       int = 1000
AS
BEGIN
    SET NOCOUNT ON;
    SET LOCK_TIMEOUT 0;

    IF @SnapshotId IS NULL
        THROW 51020, N'@SnapshotId darf nicht NULL sein.', 1;

    IF @CaptureSessions IS NULL OR @CaptureSessions NOT IN (0,1)
       OR @CaptureRequests IS NULL OR @CaptureRequests NOT IN (0,1)
       OR @CaptureConnections IS NULL OR @CaptureConnections NOT IN (0,1)
       OR @CaptureWaitingTasks IS NULL OR @CaptureWaitingTasks NOT IN (0,1)
       OR @CaptureMemoryGrants IS NULL OR @CaptureMemoryGrants NOT IN (0,1)
       OR @CaptureResourceGovernor IS NULL OR @CaptureResourceGovernor NOT IN (0,1)
       OR @CaptureTasks IS NULL OR @CaptureTasks NOT IN (0,1)
       OR @CaptureSchedulers IS NULL OR @CaptureSchedulers NOT IN (0,1)
       OR @CaptureTransactions IS NULL OR @CaptureTransactions NOT IN (0,1)
       OR @CaptureTempDbUsage IS NULL OR @CaptureTempDbUsage NOT IN (0,1)
       OR @CaptureSqlText IS NULL OR @CaptureSqlText NOT IN (0,1)
       OR @MaxSqlTextHandles IS NULL OR @MaxSqlTextHandles < 0
        THROW 51020, N'Ungültiger Current-State-Snapshot-Parameter.', 1;

    BEGIN TRY
        EXEC [sys].[sp_executesql] N'
            DECLARE @Probe int;
            SELECT @Probe=0 FROM [#CurrentOverview_CurrentStateSnapshot_Context] WHERE 1=0;
            SELECT @Probe=0 FROM [#CurrentOverview_CurrentStateSnapshot_SourceStatus] WHERE 1=0;
            SELECT @Probe=0 FROM [#CurrentOverview_CurrentStateSnapshot_Sessions] WHERE 1=0;
            SELECT @Probe=0 FROM [#CurrentOverview_CurrentStateSnapshot_Requests] WHERE 1=0;
            SELECT @Probe=0 FROM [#CurrentOverview_CurrentStateSnapshot_Connections] WHERE 1=0;
            SELECT @Probe=0 FROM [#CurrentOverview_CurrentStateSnapshot_WaitingTasks] WHERE 1=0;
            SELECT @Probe=0 FROM [#CurrentOverview_CurrentStateSnapshot_MemoryGrants] WHERE 1=0;
            SELECT @Probe=0 FROM [#CurrentOverview_CurrentStateSnapshot_ResourceSemaphores] WHERE 1=0;
            SELECT @Probe=0 FROM [#CurrentOverview_CurrentStateSnapshot_WorkloadGroups] WHERE 1=0;
            SELECT @Probe=0 FROM [#CurrentOverview_CurrentStateSnapshot_ResourcePools] WHERE 1=0;
            SELECT @Probe=0 FROM [#CurrentOverview_CurrentStateSnapshot_Tasks] WHERE 1=0;
            SELECT @Probe=0 FROM [#CurrentOverview_CurrentStateSnapshot_Schedulers] WHERE 1=0;
            SELECT @Probe=0 FROM [#CurrentOverview_CurrentStateSnapshot_SessionTransactions] WHERE 1=0;
            SELECT @Probe=0 FROM [#CurrentOverview_CurrentStateSnapshot_ActiveTransactions] WHERE 1=0;
            SELECT @Probe=0 FROM [#CurrentOverview_CurrentStateSnapshot_DatabaseTransactions] WHERE 1=0;
            SELECT @Probe=0 FROM [#CurrentOverview_CurrentStateSnapshot_TempDbSessionUsage] WHERE 1=0;
            SELECT @Probe=0 FROM [#CurrentOverview_CurrentStateSnapshot_TempDbTaskUsage] WHERE 1=0;
            SELECT @Probe=0 FROM [#CurrentOverview_CurrentStateSnapshot_SqlText] WHERE 1=0;';
    END TRY
    BEGIN CATCH
        THROW 51020, N'Der aufrufende Snapshot-Owner hat den Temp-Table-Vertrag nicht vollständig angelegt.', 1;
    END CATCH;

    IF EXISTS
    (
        SELECT 1
        FROM [#CurrentOverview_CurrentStateSnapshot_Context]
        WHERE [SnapshotId] = @SnapshotId
    )
        THROW 51020, N'Diese Snapshot-ID wurde im aktuellen Aufruf bereits verwendet.', 1;

    INSERT [#CurrentOverview_CurrentStateSnapshot_Context]
    (
        [SnapshotId],[OwnerSessionId],[CreatedAtUtc],[ContractVersion]
    )
    VALUES
    (
        @SnapshotId,CONVERT(smallint,@@SPID),SYSUTCDATETIME(),2
    );

    DECLARE @HasFullView bit =
        CASE
            WHEN IS_SRVROLEMEMBER(N'sysadmin') = 1 THEN 1
            WHEN TRY_CONVERT(int,SERVERPROPERTY(N'ProductMajorVersion')) >= 16
                THEN COALESCE(HAS_PERMS_BY_NAME(NULL,N'SERVER',N'VIEW SERVER PERFORMANCE STATE'),0)
            ELSE COALESCE(HAS_PERMS_BY_NAME(NULL,N'SERVER',N'VIEW SERVER STATE'),0)
        END;
    DECLARE @CapturedAtUtc datetime2(3);
    DECLARE @CompletedAtUtc datetime2(3);
    DECLARE @RowCount bigint;
    DECLARE @ErrorNumber int;
    DECLARE @ErrorMessage nvarchar(2048);
    DECLARE @StatusCode varchar(40);
    DECLARE @IsPartial bit;
    DECLARE @BaseStatusCode varchar(40)=CASE WHEN @HasFullView=1 THEN 'AVAILABLE' ELSE 'AVAILABLE_LIMITED' END;
    DECLARE @BaseIsPartial bit=CASE WHEN @HasFullView=1 THEN 0 ELSE 1 END;

    IF @CaptureSessions=1
    BEGIN
        SET @CapturedAtUtc=SYSUTCDATETIME();
        BEGIN TRY
            INSERT [#CurrentOverview_CurrentStateSnapshot_Sessions]
            (
                [SnapshotId],[CapturedAtUtc],[session_id],[is_user_process],[status],
                [login_name],[original_login_name],[host_name],[program_name],
                [client_interface_name],[login_time],[last_request_start_time],
                [last_request_end_time],[open_transaction_count],
                [transaction_isolation_level],[cpu_time],[reads],[writes],
                [logical_reads],[memory_usage],[row_count]
            )
            SELECT
                @SnapshotId,@CapturedAtUtc,[s].[session_id],[s].[is_user_process],[s].[status],
                [s].[login_name],[s].[original_login_name],[s].[host_name],[s].[program_name],
                [s].[client_interface_name],[s].[login_time],[s].[last_request_start_time],
                [s].[last_request_end_time],[s].[open_transaction_count],
                [s].[transaction_isolation_level],[s].[cpu_time],[s].[reads],[s].[writes],
                [s].[logical_reads],[s].[memory_usage],[s].[row_count]
            FROM [sys].[dm_exec_sessions] AS [s] WITH (NOLOCK);

            SELECT @RowCount=COUNT_BIG(*)
            FROM [#CurrentOverview_CurrentStateSnapshot_WorkloadGroups]
            WHERE [SnapshotId]=@SnapshotId;
            SET @CompletedAtUtc=SYSUTCDATETIME();
            INSERT [#CurrentOverview_CurrentStateSnapshot_SourceStatus]
            VALUES
            (@SnapshotId,10,'SESSIONS',N'sys.dm_exec_sessions',@CapturedAtUtc,@CompletedAtUtc,
             @BaseStatusCode,@BaseIsPartial,@RowCount,NULL,NULL);
        END TRY
        BEGIN CATCH
            SELECT @ErrorNumber=ERROR_NUMBER(),@ErrorMessage=ERROR_MESSAGE(),@CompletedAtUtc=SYSUTCDATETIME();
            INSERT [#CurrentOverview_CurrentStateSnapshot_SourceStatus]
            VALUES
            (@SnapshotId,10,'SESSIONS',N'sys.dm_exec_sessions',@CapturedAtUtc,@CompletedAtUtc,
             CASE WHEN @ErrorNumber=1222 THEN 'TIMEOUT' WHEN @ErrorNumber IN(229,262,297,300,371,916) THEN 'DENIED_PERMISSION' ELSE 'ERROR_HANDLED' END,
             1,0,@ErrorNumber,@ErrorMessage);
        END CATCH;
    END;

    IF @CaptureRequests=1
    BEGIN
        SET @CapturedAtUtc=SYSUTCDATETIME();
        BEGIN TRY
            INSERT [#CurrentOverview_CurrentStateSnapshot_Requests]
            (
                [SnapshotId],[CapturedAtUtc],[session_id],[request_id],[status],[command],
                [start_time],[sql_handle],[statement_start_offset],[statement_end_offset],
                [plan_handle],[database_id],[connection_id],[blocking_session_id],
                [wait_type],[wait_time],[last_wait_type],[wait_resource],
                [open_transaction_count],[open_resultset_count],[transaction_id],
                [context_info],[percent_complete],[estimated_completion_time],
                [cpu_time],[total_elapsed_time],[scheduler_id],[task_address],
                [reads],[writes],[logical_reads],[transaction_isolation_level],
                [row_count],[nest_level],[executing_managed_code],[group_id],
                [query_hash],[query_plan_hash],[statement_sql_handle],
                [statement_context_id],[dop],[parallel_worker_count],[is_resumable]
            )
            SELECT
                @SnapshotId,@CapturedAtUtc,[r].[session_id],[r].[request_id],[r].[status],[r].[command],
                [r].[start_time],[r].[sql_handle],[r].[statement_start_offset],[r].[statement_end_offset],
                [r].[plan_handle],[r].[database_id],[r].[connection_id],[r].[blocking_session_id],
                [r].[wait_type],[r].[wait_time],[r].[last_wait_type],[r].[wait_resource],
                [r].[open_transaction_count],[r].[open_resultset_count],[r].[transaction_id],
                [r].[context_info],[r].[percent_complete],[r].[estimated_completion_time],
                [r].[cpu_time],[r].[total_elapsed_time],[r].[scheduler_id],[r].[task_address],
                [r].[reads],[r].[writes],[r].[logical_reads],[r].[transaction_isolation_level],
                [r].[row_count],[r].[nest_level],[r].[executing_managed_code],[r].[group_id],
                [r].[query_hash],[r].[query_plan_hash],[r].[statement_sql_handle],
                [r].[statement_context_id],[r].[dop],[r].[parallel_worker_count],[r].[is_resumable]
            FROM [sys].[dm_exec_requests] AS [r] WITH (NOLOCK);

            SET @RowCount=@@ROWCOUNT;
            SET @CompletedAtUtc=SYSUTCDATETIME();
            INSERT [#CurrentOverview_CurrentStateSnapshot_SourceStatus]
            VALUES
            (@SnapshotId,20,'REQUESTS',N'sys.dm_exec_requests',@CapturedAtUtc,@CompletedAtUtc,
             @BaseStatusCode,@BaseIsPartial,@RowCount,NULL,NULL);
        END TRY
        BEGIN CATCH
            SELECT @ErrorNumber=ERROR_NUMBER(),@ErrorMessage=ERROR_MESSAGE(),@CompletedAtUtc=SYSUTCDATETIME();
            INSERT [#CurrentOverview_CurrentStateSnapshot_SourceStatus]
            VALUES
            (@SnapshotId,20,'REQUESTS',N'sys.dm_exec_requests',@CapturedAtUtc,@CompletedAtUtc,
             CASE WHEN @ErrorNumber=1222 THEN 'TIMEOUT' WHEN @ErrorNumber IN(229,262,297,300,371,916) THEN 'DENIED_PERMISSION' ELSE 'ERROR_HANDLED' END,
             1,0,@ErrorNumber,@ErrorMessage);
        END CATCH;
    END;

    IF @CaptureConnections=1
    BEGIN
        SET @CapturedAtUtc=SYSUTCDATETIME();
        BEGIN TRY
            INSERT [#CurrentOverview_CurrentStateSnapshot_Connections]
            (
                [SnapshotId],[CapturedAtUtc],[session_id],[connection_id],
                [most_recent_sql_handle],[client_net_address],[net_transport],
                [protocol_type],[encrypt_option],[auth_scheme],[connect_time]
            )
            SELECT
                @SnapshotId,@CapturedAtUtc,[c].[session_id],[c].[connection_id],
                [c].[most_recent_sql_handle],[c].[client_net_address],[c].[net_transport],
                [c].[protocol_type],[c].[encrypt_option],[c].[auth_scheme],[c].[connect_time]
            FROM [sys].[dm_exec_connections] AS [c] WITH (NOLOCK);

            SET @RowCount=@@ROWCOUNT;
            SET @CompletedAtUtc=SYSUTCDATETIME();
            INSERT [#CurrentOverview_CurrentStateSnapshot_SourceStatus]
            VALUES
            (@SnapshotId,30,'CONNECTIONS',N'sys.dm_exec_connections',@CapturedAtUtc,@CompletedAtUtc,
             @BaseStatusCode,@BaseIsPartial,@RowCount,NULL,NULL);
        END TRY
        BEGIN CATCH
            SELECT @ErrorNumber=ERROR_NUMBER(),@ErrorMessage=ERROR_MESSAGE(),@CompletedAtUtc=SYSUTCDATETIME();
            INSERT [#CurrentOverview_CurrentStateSnapshot_SourceStatus]
            VALUES
            (@SnapshotId,30,'CONNECTIONS',N'sys.dm_exec_connections',@CapturedAtUtc,@CompletedAtUtc,
             CASE WHEN @ErrorNumber=1222 THEN 'TIMEOUT' WHEN @ErrorNumber IN(229,262,297,300,371,916) THEN 'DENIED_PERMISSION' ELSE 'ERROR_HANDLED' END,
             1,0,@ErrorNumber,@ErrorMessage);
        END CATCH;
    END;

    IF @CaptureWaitingTasks=1
    BEGIN
        SET @CapturedAtUtc=SYSUTCDATETIME();
        BEGIN TRY
            INSERT [#CurrentOverview_CurrentStateSnapshot_WaitingTasks]
            (
                [SnapshotId],[CapturedAtUtc],[waiting_task_address],[session_id],
                [exec_context_id],[wait_duration_ms],[wait_type],[resource_address],
                [blocking_task_address],[blocking_session_id],
                [blocking_exec_context_id],[resource_description]
            )
            SELECT
                @SnapshotId,@CapturedAtUtc,[w].[waiting_task_address],[w].[session_id],
                [w].[exec_context_id],[w].[wait_duration_ms],[w].[wait_type],[w].[resource_address],
                [w].[blocking_task_address],[w].[blocking_session_id],
                [w].[blocking_exec_context_id],[w].[resource_description]
            FROM [sys].[dm_os_waiting_tasks] AS [w] WITH (NOLOCK);

            SET @RowCount=@@ROWCOUNT;
            SET @CompletedAtUtc=SYSUTCDATETIME();
            INSERT [#CurrentOverview_CurrentStateSnapshot_SourceStatus]
            VALUES
            (@SnapshotId,40,'WAITING_TASKS',N'sys.dm_os_waiting_tasks',@CapturedAtUtc,@CompletedAtUtc,
             @BaseStatusCode,@BaseIsPartial,@RowCount,NULL,NULL);
        END TRY
        BEGIN CATCH
            SELECT @ErrorNumber=ERROR_NUMBER(),@ErrorMessage=ERROR_MESSAGE(),@CompletedAtUtc=SYSUTCDATETIME();
            INSERT [#CurrentOverview_CurrentStateSnapshot_SourceStatus]
            VALUES
            (@SnapshotId,40,'WAITING_TASKS',N'sys.dm_os_waiting_tasks',@CapturedAtUtc,@CompletedAtUtc,
             CASE WHEN @ErrorNumber=1222 THEN 'TIMEOUT' WHEN @ErrorNumber IN(229,262,297,300,371,916) THEN 'DENIED_PERMISSION' ELSE 'ERROR_HANDLED' END,
             1,0,@ErrorNumber,@ErrorMessage);
        END CATCH;
    END;

    IF @CaptureMemoryGrants=1
    BEGIN
        SET @CapturedAtUtc=SYSUTCDATETIME();
        BEGIN TRY
            INSERT [#CurrentOverview_CurrentStateSnapshot_MemoryGrants]
            (
                [SnapshotId],[CapturedAtUtc],[session_id],[request_id],
                [scheduler_id],[dop],[request_time],[grant_time],[wait_time_ms],
                [requested_memory_kb],[required_memory_kb],[granted_memory_kb],
                [used_memory_kb],[max_used_memory_kb],[ideal_memory_kb],
                [resource_semaphore_id],[queue_id],[wait_order],[is_next_candidate],
                [is_small],[plan_handle],[sql_handle],[group_id],[pool_id],
                [reserved_worker_count],[used_worker_count],[max_used_worker_count]
            )
            SELECT
                @SnapshotId,@CapturedAtUtc,[g].[session_id],[g].[request_id],
                [g].[scheduler_id],[g].[dop],[g].[request_time],[g].[grant_time],[g].[wait_time_ms],
                [g].[requested_memory_kb],[g].[required_memory_kb],[g].[granted_memory_kb],
                [g].[used_memory_kb],[g].[max_used_memory_kb],[g].[ideal_memory_kb],
                [g].[resource_semaphore_id],[g].[queue_id],[g].[wait_order],[g].[is_next_candidate],
                [g].[is_small],[g].[plan_handle],[g].[sql_handle],[g].[group_id],[g].[pool_id],
                [g].[reserved_worker_count],[g].[used_worker_count],[g].[max_used_worker_count]
            FROM [sys].[dm_exec_query_memory_grants] AS [g] WITH (NOLOCK);

            SET @RowCount=@@ROWCOUNT;
            SET @CompletedAtUtc=SYSUTCDATETIME();
            INSERT [#CurrentOverview_CurrentStateSnapshot_SourceStatus]
            VALUES
            (@SnapshotId,50,'MEMORY_GRANTS',N'sys.dm_exec_query_memory_grants',@CapturedAtUtc,@CompletedAtUtc,
             @BaseStatusCode,@BaseIsPartial,@RowCount,NULL,NULL);
        END TRY
        BEGIN CATCH
            SELECT @ErrorNumber=ERROR_NUMBER(),@ErrorMessage=ERROR_MESSAGE(),@CompletedAtUtc=SYSUTCDATETIME();
            INSERT [#CurrentOverview_CurrentStateSnapshot_SourceStatus]
            VALUES
            (@SnapshotId,50,'MEMORY_GRANTS',N'sys.dm_exec_query_memory_grants',@CapturedAtUtc,@CompletedAtUtc,
             CASE WHEN @ErrorNumber=1222 THEN 'TIMEOUT' WHEN @ErrorNumber IN(229,262,297,300,371,916) THEN 'DENIED_PERMISSION' ELSE 'ERROR_HANDLED' END,
             1,0,@ErrorNumber,@ErrorMessage);
        END CATCH;

        SET @CapturedAtUtc=SYSUTCDATETIME();
        BEGIN TRY
            INSERT [#CurrentOverview_CurrentStateSnapshot_ResourceSemaphores]
            (
                [SnapshotId],[CapturedAtUtc],[pool_id],[resource_semaphore_id],
                [target_memory_kb],[max_target_memory_kb],[total_memory_kb],
                [available_memory_kb],[granted_memory_kb],[used_memory_kb],
                [grantee_count],[waiter_count]
            )
            SELECT
                @SnapshotId,@CapturedAtUtc,[s].[pool_id],[s].[resource_semaphore_id],
                [s].[target_memory_kb],[s].[max_target_memory_kb],[s].[total_memory_kb],
                [s].[available_memory_kb],[s].[granted_memory_kb],[s].[used_memory_kb],
                [s].[grantee_count],[s].[waiter_count]
            FROM [sys].[dm_exec_query_resource_semaphores] AS [s] WITH (NOLOCK);

            SET @RowCount=@@ROWCOUNT;
            SET @CompletedAtUtc=SYSUTCDATETIME();
            INSERT [#CurrentOverview_CurrentStateSnapshot_SourceStatus]
            VALUES
            (@SnapshotId,55,'RESOURCE_SEMAPHORES',N'sys.dm_exec_query_resource_semaphores',
             @CapturedAtUtc,@CompletedAtUtc,@BaseStatusCode,@BaseIsPartial,@RowCount,NULL,NULL);
        END TRY
        BEGIN CATCH
            SELECT @ErrorNumber=ERROR_NUMBER(),@ErrorMessage=ERROR_MESSAGE(),@CompletedAtUtc=SYSUTCDATETIME();
            INSERT [#CurrentOverview_CurrentStateSnapshot_SourceStatus]
            VALUES
            (@SnapshotId,55,'RESOURCE_SEMAPHORES',N'sys.dm_exec_query_resource_semaphores',
             @CapturedAtUtc,@CompletedAtUtc,
             CASE WHEN @ErrorNumber=1222 THEN 'TIMEOUT' WHEN @ErrorNumber IN(229,262,297,300,371,916) THEN 'DENIED_PERMISSION' ELSE 'ERROR_HANDLED' END,
             1,0,@ErrorNumber,@ErrorMessage);
        END CATCH;
    END;

    IF @CaptureResourceGovernor=1
    BEGIN
        DECLARE @ProductMajorVersion int=TRY_CONVERT(int,SERVERPROPERTY(N'ProductMajorVersion'));
        DECLARE @CatalogTempdbColumnsValid bit=0;
        DECLARE @RuntimeTempdbColumnsValid bit=0;
        DECLARE @TempdbGovernanceStatus varchar(40)=
            CASE WHEN @ProductMajorVersion IS NULL OR @ProductMajorVersion<17
                 THEN 'UNAVAILABLE_VERSION' ELSE 'AVAILABLE' END;
        DECLARE @TempdbGovernanceErrorNumber int=NULL;
        DECLARE @TempdbGovernanceErrorMessage nvarchar(2048)=NULL;
        DECLARE @TempdbMaximumSizeMb decimal(19,2)=NULL;
        DECLARE @TempdbFileStatus varchar(40)='NOT_APPLICABLE';
        DECLARE @TempdbFileErrorNumber int=NULL;
        DECLARE @TempdbFileErrorMessage nvarchar(2048)=NULL;
        DECLARE @IsResourceGovernorEnabled bit=NULL;
        DECLARE @ReconfigurationPending bit=NULL;
        DECLARE @ResourceGovernorSql nvarchar(max);

        IF @ProductMajorVersion>=17
        BEGIN TRY
            SELECT
                  @CatalogTempdbColumnsValid=CONVERT
                  (
                      bit,
                      CASE WHEN SUM(CASE WHEN [o].[name]=N'resource_governor_workload_groups'
                                          AND [c].[name] IN
                                              (N'group_max_tempdb_data_mb',N'group_max_tempdb_data_percent')
                                        THEN 1 ELSE 0 END)=2
                           THEN 1 ELSE 0 END
                  )
                , @RuntimeTempdbColumnsValid=CONVERT
                  (
                      bit,
                      CASE WHEN SUM(CASE WHEN [o].[name]=N'dm_resource_governor_workload_groups'
                                          AND [c].[name] IN
                                              (N'tempdb_data_space_kb',N'peak_tempdb_data_space_kb',
                                               N'total_tempdb_data_limit_violation_count')
                                        THEN 1 ELSE 0 END)=3
                           THEN 1 ELSE 0 END
                  )
            FROM [sys].[all_columns] AS [c] WITH (NOLOCK)
            INNER JOIN [sys].[all_objects] AS [o] WITH (NOLOCK)
              ON [o].[object_id]=[c].[object_id]
            INNER JOIN [sys].[schemas] AS [s] WITH (NOLOCK)
              ON [s].[schema_id]=[o].[schema_id]
            WHERE [s].[name]=N'sys'
              AND [o].[name] IN
                  (N'resource_governor_workload_groups',N'dm_resource_governor_workload_groups');

            IF @CatalogTempdbColumnsValid=0 OR @RuntimeTempdbColumnsValid=0
                SET @TempdbGovernanceStatus='UNAVAILABLE_SOURCE_SCHEMA';
        END TRY
        BEGIN CATCH
            SELECT
                  @TempdbGovernanceErrorNumber=ERROR_NUMBER()
                , @TempdbGovernanceErrorMessage=ERROR_MESSAGE()
                , @TempdbGovernanceStatus=CASE WHEN ERROR_NUMBER()=1222 THEN 'TIMEOUT'
                     WHEN ERROR_NUMBER() IN (229,262,297,300,371,916) THEN 'DENIED_PERMISSION'
                     ELSE 'ERROR_HANDLED' END;
        END CATCH;

        SET @CapturedAtUtc=SYSUTCDATETIME();
        BEGIN TRY
            DECLARE @RuntimeProjection nvarchar(max)=
                CASE WHEN @ProductMajorVersion>=17 AND @RuntimeTempdbColumnsValid=1
                     THEN N',CONVERT(decimal(19,2),[g].[tempdb_data_space_kb]/1024.0)
                             ,CONVERT(decimal(19,2),[g].[peak_tempdb_data_space_kb]/1024.0)
                             ,CONVERT(decimal(9,2),NULL)
                             ,CONVERT(bigint,[g].[total_tempdb_data_limit_violation_count])
                             ,CONVERT(bit,CASE WHEN [g].[total_tempdb_data_limit_violation_count]>0 THEN 1 ELSE 0 END)'
                     ELSE N',CONVERT(decimal(19,2),NULL),CONVERT(decimal(19,2),NULL)
                             ,CONVERT(decimal(9,2),NULL),CONVERT(bigint,NULL),CONVERT(bit,NULL)' END;

            SET @ResourceGovernorSql=N'
INSERT [#CurrentOverview_CurrentStateSnapshot_WorkloadGroups]
(
      [SnapshotId],[CapturedAtUtc],[group_id],[name],[pool_id]
    , [request_max_memory_grant_percent_numeric],[max_request_grant_memory_kb]
    , [configured_group_max_tempdb_data_mb],[configured_group_max_tempdb_data_percent]
    , [tempdb_maximum_size_mb],[effective_group_max_tempdb_data_mb]
    , [effective_limit_source],[is_percent_limit_effective]
    , [tempdb_data_space_mb],[peak_tempdb_data_space_mb]
    , [effective_limit_utilization_percent]
    , [total_tempdb_data_limit_violation_count],[has_recorded_limit_violation]
    , [statistics_start_time],[is_resource_governor_enabled],[reconfiguration_pending]
    , [tempdb_governance_status_code],[tempdb_governance_is_partial]
    , [tempdb_governance_evidence_limit]
)
SELECT
      @SnapshotId,@CapturedAtUtc,[g].[group_id],[g].[name],[g].[pool_id]
    , CONVERT(decimal(9,4),[g].[request_max_memory_grant_percent_numeric])
    , [g].[max_request_grant_memory_kb]
    , CONVERT(decimal(19,2),NULL),CONVERT(decimal(9,4),NULL)
    , CONVERT(decimal(19,2),NULL),CONVERT(decimal(19,2),NULL)
    , CONVERT(varchar(40),''UNAVAILABLE''),CONVERT(bit,NULL)'
    +@RuntimeProjection+
N'
    , [g].[statistics_start_time],CONVERT(bit,NULL),CONVERT(bit,NULL)
    , @TempdbStatus
    , CONVERT(bit,CASE WHEN @TempdbStatus=''AVAILABLE'' THEN 0 ELSE 1 END)
    , CASE WHEN @TempdbStatus=''UNAVAILABLE_VERSION''
           THEN N''TempDB Resource Governance beginnt mit SQL Server 2025 (17.x).''
           WHEN @TempdbStatus<>''AVAILABLE''
           THEN N''Die SQL-Server-2025-Quelle ist nicht vollständig verfügbar.''
           ELSE N''Workload-Group-Zähler sind nicht direkt mit Sessionzählern addierbar; Version Store und TempDB-Log sind nicht umfasst.'' END
FROM [sys].[dm_resource_governor_workload_groups] AS [g] WITH (NOLOCK);';

            EXEC [sys].[sp_executesql]
                  @ResourceGovernorSql
                , N'@SnapshotId uniqueidentifier,@CapturedAtUtc datetime2(3),@TempdbStatus varchar(40)'
                , @SnapshotId=@SnapshotId
                , @CapturedAtUtc=@CapturedAtUtc
                , @TempdbStatus=@TempdbGovernanceStatus;

            SET @RowCount=@@ROWCOUNT;
            SET @CompletedAtUtc=SYSUTCDATETIME();
            INSERT [#CurrentOverview_CurrentStateSnapshot_SourceStatus]
            VALUES
            (
                 @SnapshotId,60,'WORKLOAD_GROUPS',N'sys.dm_resource_governor_workload_groups'
                ,@CapturedAtUtc,@CompletedAtUtc,@BaseStatusCode,@BaseIsPartial,@RowCount,NULL,NULL
            );
        END TRY
        BEGIN CATCH
            SELECT @ErrorNumber=ERROR_NUMBER(),@ErrorMessage=ERROR_MESSAGE(),@CompletedAtUtc=SYSUTCDATETIME();
            INSERT [#CurrentOverview_CurrentStateSnapshot_SourceStatus]
            VALUES
            (
                 @SnapshotId,60,'WORKLOAD_GROUPS',N'sys.dm_resource_governor_workload_groups'
                ,@CapturedAtUtc,@CompletedAtUtc
                ,CASE WHEN @ErrorNumber=1222 THEN 'TIMEOUT'
                      WHEN @ErrorNumber IN(229,262,297,300,371,916) THEN 'DENIED_PERMISSION'
                      ELSE 'ERROR_HANDLED' END
                ,1,0,@ErrorNumber,@ErrorMessage
            );
            SELECT
                  @TempdbGovernanceStatus=CASE WHEN @ErrorNumber=1222 THEN 'TIMEOUT'
                       WHEN @ErrorNumber IN(229,262,297,300,371,916) THEN 'DENIED_PERMISSION'
                       ELSE 'ERROR_HANDLED' END
                , @TempdbGovernanceErrorNumber=@ErrorNumber
                , @TempdbGovernanceErrorMessage=@ErrorMessage;
        END CATCH;

        IF @ProductMajorVersion>=17
           AND EXISTS
               (
                   SELECT 1
                   FROM [#CurrentOverview_CurrentStateSnapshot_WorkloadGroups]
                   WHERE [SnapshotId]=@SnapshotId
               )
        BEGIN
            IF @CatalogTempdbColumnsValid=1
            BEGIN TRY
                SET @ResourceGovernorSql=N'
UPDATE [target]
SET
      [configured_group_max_tempdb_data_mb]=
          CONVERT(decimal(19,2),[source].[group_max_tempdb_data_mb])
    , [configured_group_max_tempdb_data_percent]=
          CONVERT(decimal(9,4),[source].[group_max_tempdb_data_percent])
FROM [#CurrentOverview_CurrentStateSnapshot_WorkloadGroups] AS [target]
INNER JOIN [sys].[resource_governor_workload_groups] AS [source] WITH (NOLOCK)
  ON [source].[group_id]=[target].[group_id]
WHERE [target].[SnapshotId]=@SnapshotId;';

                EXEC [sys].[sp_executesql]
                      @ResourceGovernorSql
                    , N'@SnapshotId uniqueidentifier'
                    , @SnapshotId=@SnapshotId;
            END TRY
            BEGIN CATCH
                SELECT
                      @TempdbGovernanceErrorNumber=ERROR_NUMBER()
                    , @TempdbGovernanceErrorMessage=ERROR_MESSAGE()
                    , @TempdbGovernanceStatus=CASE WHEN ERROR_NUMBER()=1222 THEN 'TIMEOUT'
                         WHEN ERROR_NUMBER() IN(229,262,297,300,371,916) THEN 'DENIED_PERMISSION'
                         ELSE 'ERROR_HANDLED' END;
            END CATCH;

            BEGIN TRY
                SELECT
                      @IsResourceGovernorEnabled=[stored].[is_enabled]
                    , @ReconfigurationPending=[effective].[is_reconfiguration_pending]
                FROM [sys].[resource_governor_configuration] AS [stored] WITH (NOLOCK)
                CROSS JOIN [sys].[dm_resource_governor_configuration] AS [effective] WITH (NOLOCK);
            END TRY
            BEGIN CATCH
                SELECT
                      @TempdbGovernanceErrorNumber=ERROR_NUMBER()
                    , @TempdbGovernanceErrorMessage=ERROR_MESSAGE()
                    , @TempdbGovernanceStatus=CASE WHEN ERROR_NUMBER()=1222 THEN 'TIMEOUT'
                         WHEN ERROR_NUMBER() IN(229,262,297,300,371,916) THEN 'DENIED_PERMISSION'
                         ELSE 'ERROR_HANDLED' END;
            END CATCH;

            IF @TempdbGovernanceStatus='AVAILABLE'
               AND EXISTS
                   (
                       SELECT 1
                       FROM [#CurrentOverview_CurrentStateSnapshot_WorkloadGroups]
                       WHERE [SnapshotId]=@SnapshotId
                         AND [configured_group_max_tempdb_data_mb] IS NULL
                         AND [configured_group_max_tempdb_data_percent] IS NOT NULL
                   )
            BEGIN
                SET @TempdbFileStatus='AVAILABLE';
                BEGIN TRY
                    SELECT @TempdbMaximumSizeMb=
                        CASE
                            WHEN COUNT_BIG(*)>0
                             AND
                             (
                                 SUM(CASE WHEN [f].[max_size]<>-1 AND [f].[growth]>0 THEN 1 ELSE 0 END)=COUNT_BIG(*)
                                 OR
                                 SUM(CASE WHEN [f].[max_size]=-1 AND [f].[growth]=0 THEN 1 ELSE 0 END)=COUNT_BIG(*)
                             )
                            THEN CONVERT
                                 (
                                     decimal(19,2),
                                     SUM(CASE WHEN [f].[growth]=0 THEN CONVERT(bigint,[f].[size])
                                              ELSE CONVERT(bigint,[f].[max_size]) END)*8.0/1024.0
                                 )
                        END
                    FROM [master].[sys].[master_files] AS [f] WITH (NOLOCK)
                    WHERE [f].[database_id]=2 AND [f].[type]=0;
                END TRY
                BEGIN CATCH
                    SELECT
                          @TempdbFileErrorNumber=ERROR_NUMBER()
                        , @TempdbFileErrorMessage=ERROR_MESSAGE()
                        , @TempdbFileStatus=CASE WHEN ERROR_NUMBER()=1222 THEN 'TIMEOUT'
                             WHEN ERROR_NUMBER() IN(229,262,297,300,371,916) THEN 'DENIED_PERMISSION'
                             ELSE 'ERROR_HANDLED' END;
                END CATCH;
            END;

            UPDATE [g]
            SET
                  [tempdb_maximum_size_mb]=@TempdbMaximumSizeMb
                , [effective_group_max_tempdb_data_mb]=CONVERT
                  (
                      decimal(19,2),
                      CASE
                          WHEN @TempdbGovernanceStatus<>'AVAILABLE' THEN NULL
                          WHEN [g].[configured_group_max_tempdb_data_mb] IS NULL
                           AND [g].[configured_group_max_tempdb_data_percent] IS NULL THEN NULL
                          WHEN @ReconfigurationPending=1 OR COALESCE(@IsResourceGovernorEnabled,0)=0 THEN NULL
                          WHEN [g].[configured_group_max_tempdb_data_mb] IS NOT NULL
                              THEN [g].[configured_group_max_tempdb_data_mb]
                          WHEN @TempdbFileStatus<>'AVAILABLE' THEN NULL
                          WHEN @TempdbMaximumSizeMb IS NOT NULL
                              THEN [g].[configured_group_max_tempdb_data_percent]*@TempdbMaximumSizeMb/100.0
                      END
                  )
                , [effective_limit_source]=CASE
                      WHEN @TempdbGovernanceStatus<>'AVAILABLE' THEN 'UNAVAILABLE'
                      WHEN [g].[configured_group_max_tempdb_data_mb] IS NULL
                       AND [g].[configured_group_max_tempdb_data_percent] IS NULL THEN 'NO_LIMIT_CONFIGURED'
                      WHEN @ReconfigurationPending=1 THEN 'RECONFIGURATION_PENDING'
                      WHEN COALESCE(@IsResourceGovernorEnabled,0)=0 THEN 'RESOURCE_GOVERNOR_DISABLED'
                      WHEN [g].[configured_group_max_tempdb_data_mb] IS NOT NULL THEN 'FIXED_MB_EFFECTIVE'
                      WHEN @TempdbFileStatus<>'AVAILABLE' THEN 'UNAVAILABLE'
                      WHEN @TempdbMaximumSizeMb IS NOT NULL THEN 'PERCENT_EFFECTIVE'
                      ELSE 'PERCENT_NOT_EFFECTIVE'
                  END
                , [is_percent_limit_effective]=CASE
                      WHEN [g].[configured_group_max_tempdb_data_percent] IS NULL THEN NULL
                      WHEN [g].[configured_group_max_tempdb_data_mb] IS NOT NULL THEN CONVERT(bit,0)
                      WHEN @ReconfigurationPending=1 OR COALESCE(@IsResourceGovernorEnabled,0)=0 THEN CONVERT(bit,0)
                      WHEN @TempdbFileStatus<>'AVAILABLE' THEN NULL
                      WHEN @TempdbMaximumSizeMb IS NOT NULL THEN CONVERT(bit,1)
                      ELSE CONVERT(bit,0)
                  END
                , [effective_limit_utilization_percent]=CONVERT
                  (
                      decimal(9,2),
                      100.0*[g].[tempdb_data_space_mb]
                      /NULLIF
                       (
                           CASE
                               WHEN @ReconfigurationPending=0 AND COALESCE(@IsResourceGovernorEnabled,0)=1
                                AND [g].[configured_group_max_tempdb_data_mb] IS NOT NULL
                                   THEN [g].[configured_group_max_tempdb_data_mb]
                               WHEN @ReconfigurationPending=0 AND COALESCE(@IsResourceGovernorEnabled,0)=1
                                AND [g].[configured_group_max_tempdb_data_mb] IS NULL
                                AND @TempdbMaximumSizeMb IS NOT NULL
                                   THEN [g].[configured_group_max_tempdb_data_percent]*@TempdbMaximumSizeMb/100.0
                           END
                       ,0)
                  )
                , [is_resource_governor_enabled]=@IsResourceGovernorEnabled
                , [reconfiguration_pending]=@ReconfigurationPending
                , [tempdb_governance_status_code]=CASE
                      WHEN @TempdbGovernanceStatus='AVAILABLE'
                       AND [g].[configured_group_max_tempdb_data_mb] IS NULL
                       AND [g].[configured_group_max_tempdb_data_percent] IS NOT NULL
                       AND @TempdbFileStatus<>'AVAILABLE'
                          THEN @TempdbFileStatus
                      WHEN @TempdbGovernanceStatus='AVAILABLE'
                       AND @ReconfigurationPending=1
                       AND
                         (
                             [g].[configured_group_max_tempdb_data_mb] IS NOT NULL
                             OR [g].[configured_group_max_tempdb_data_percent] IS NOT NULL
                         )
                          THEN 'AVAILABLE_LIMITED'
                      ELSE @TempdbGovernanceStatus
                  END
                , [tempdb_governance_is_partial]=CONVERT
                  (
                      bit,
                      CASE
                          WHEN @TempdbGovernanceStatus<>'AVAILABLE' THEN 1
                          WHEN [g].[configured_group_max_tempdb_data_mb] IS NULL
                           AND [g].[configured_group_max_tempdb_data_percent] IS NOT NULL
                           AND @TempdbFileStatus<>'AVAILABLE' THEN 1
                          WHEN @ReconfigurationPending=1
                           AND
                             (
                                 [g].[configured_group_max_tempdb_data_mb] IS NOT NULL
                                 OR [g].[configured_group_max_tempdb_data_percent] IS NOT NULL
                             )
                              THEN 1
                          ELSE 0
                      END
                  )
                , [tempdb_governance_evidence_limit]=CASE
                      WHEN @TempdbGovernanceStatus<>'AVAILABLE'
                          THEN COALESCE(@TempdbGovernanceErrorMessage,N'Die SQL-Server-2025-Quelle ist nicht vollständig verfügbar.')
                      WHEN [g].[configured_group_max_tempdb_data_mb] IS NULL
                       AND [g].[configured_group_max_tempdb_data_percent] IS NOT NULL
                       AND @TempdbFileStatus<>'AVAILABLE'
                          THEN COALESCE(@TempdbFileErrorMessage,N'Die TempDB-Dateikonfiguration ist im aktuellen Sicherheitskontext nicht auswertbar.')
                      WHEN @ReconfigurationPending=1
                          THEN N'Die gespeicherte Konfiguration kann von der aktiven Konfiguration abweichen, bis RECONFIGURE abgeschlossen ist.'
                      WHEN [g].[configured_group_max_tempdb_data_mb] IS NULL
                       AND [g].[configured_group_max_tempdb_data_percent] IS NOT NULL
                       AND @TempdbMaximumSizeMb IS NULL
                          THEN N'Das gespeicherte Prozentlimit ist wegen der TempDB-Dateikonfiguration nicht wirksam.'
                      ELSE N'Workload-Group-Zähler sind nicht direkt mit Sessionzählern addierbar; Version Store und TempDB-Log sind nicht umfasst.'
                  END
            FROM [#CurrentOverview_CurrentStateSnapshot_WorkloadGroups] AS [g]
            WHERE [g].[SnapshotId]=@SnapshotId;

            SET @CompletedAtUtc=SYSUTCDATETIME();
            SELECT @RowCount=COUNT_BIG(*)
            FROM [#CurrentOverview_CurrentStateSnapshot_WorkloadGroups]
            WHERE [SnapshotId]=@SnapshotId;

            DECLARE @TempdbSnapshotStatus varchar(40)=CASE
                WHEN @TempdbGovernanceStatus<>'AVAILABLE' THEN @TempdbGovernanceStatus
                WHEN @TempdbFileStatus NOT IN ('AVAILABLE','NOT_APPLICABLE')
                    THEN 'AVAILABLE_LIMITED'
                ELSE 'AVAILABLE' END;

            INSERT [#CurrentOverview_CurrentStateSnapshot_SourceStatus]
            VALUES
            (
                 @SnapshotId,61,'TEMPDB_GOVERNANCE'
                ,N'sys.resource_governor_workload_groups | sys.dm_resource_governor_workload_groups | master.sys.master_files'
                ,@CapturedAtUtc,@CompletedAtUtc
                ,@TempdbSnapshotStatus
                ,CONVERT(bit,CASE WHEN @TempdbSnapshotStatus='AVAILABLE' THEN 0 ELSE 1 END)
                ,@RowCount
                ,COALESCE(@TempdbGovernanceErrorNumber,@TempdbFileErrorNumber)
                ,COALESCE(@TempdbGovernanceErrorMessage,@TempdbFileErrorMessage)
            );
        END;

        SET @CapturedAtUtc=SYSUTCDATETIME();
        BEGIN TRY
            INSERT [#CurrentOverview_CurrentStateSnapshot_ResourcePools]
            (
                [SnapshotId],[CapturedAtUtc],[pool_id],[name],
                [max_memory_kb],[target_memory_kb],[used_memory_kb]
            )
            SELECT
                @SnapshotId,@CapturedAtUtc,[p].[pool_id],[p].[name],
                [p].[max_memory_kb],[p].[target_memory_kb],[p].[used_memory_kb]
            FROM [sys].[dm_resource_governor_resource_pools] AS [p] WITH (NOLOCK);

            SET @RowCount=@@ROWCOUNT;
            SET @CompletedAtUtc=SYSUTCDATETIME();
            INSERT [#CurrentOverview_CurrentStateSnapshot_SourceStatus]
            VALUES
            (@SnapshotId,70,'RESOURCE_POOLS',N'sys.dm_resource_governor_resource_pools',@CapturedAtUtc,@CompletedAtUtc,
             @BaseStatusCode,@BaseIsPartial,@RowCount,NULL,NULL);
        END TRY
        BEGIN CATCH
            SELECT @ErrorNumber=ERROR_NUMBER(),@ErrorMessage=ERROR_MESSAGE(),@CompletedAtUtc=SYSUTCDATETIME();
            INSERT [#CurrentOverview_CurrentStateSnapshot_SourceStatus]
            VALUES
            (@SnapshotId,70,'RESOURCE_POOLS',N'sys.dm_resource_governor_resource_pools',@CapturedAtUtc,@CompletedAtUtc,
             CASE WHEN @ErrorNumber=1222 THEN 'TIMEOUT' WHEN @ErrorNumber IN(229,262,297,300,371,916) THEN 'DENIED_PERMISSION' ELSE 'ERROR_HANDLED' END,
             1,0,@ErrorNumber,@ErrorMessage);
        END CATCH;
    END;

    IF @CaptureTasks=1
    BEGIN
        SET @CapturedAtUtc=SYSUTCDATETIME();
        BEGIN TRY
            INSERT [#CurrentOverview_CurrentStateSnapshot_Tasks]
            (
                [SnapshotId],[CapturedAtUtc],[task_address],[task_state],
                [session_id],[request_id],[exec_context_id],[scheduler_id],
                [worker_address],[parent_task_address]
            )
            SELECT
                @SnapshotId,@CapturedAtUtc,[t].[task_address],[t].[task_state],
                [t].[session_id],[t].[request_id],[t].[exec_context_id],[t].[scheduler_id],
                [t].[worker_address],[t].[parent_task_address]
            FROM [sys].[dm_os_tasks] AS [t] WITH (NOLOCK)
            WHERE EXISTS
            (
                SELECT 1
                FROM [#CurrentOverview_CurrentStateSnapshot_Requests] AS [r]
                WHERE [r].[SnapshotId]=@SnapshotId
                  AND [r].[session_id]=[t].[session_id]
                  AND [r].[request_id]=[t].[request_id]
            );

            SET @RowCount=@@ROWCOUNT;
            SET @CompletedAtUtc=SYSUTCDATETIME();
            INSERT [#CurrentOverview_CurrentStateSnapshot_SourceStatus]
            VALUES
            (@SnapshotId,90,'TASKS',N'sys.dm_os_tasks',@CapturedAtUtc,@CompletedAtUtc,
             @BaseStatusCode,@BaseIsPartial,@RowCount,NULL,NULL);
        END TRY
        BEGIN CATCH
            SELECT @ErrorNumber=ERROR_NUMBER(),@ErrorMessage=ERROR_MESSAGE(),@CompletedAtUtc=SYSUTCDATETIME();
            INSERT [#CurrentOverview_CurrentStateSnapshot_SourceStatus]
            VALUES
            (@SnapshotId,90,'TASKS',N'sys.dm_os_tasks',@CapturedAtUtc,@CompletedAtUtc,
             CASE WHEN @ErrorNumber=1222 THEN 'TIMEOUT' WHEN @ErrorNumber IN(229,262,297,300,371,916) THEN 'DENIED_PERMISSION' ELSE 'ERROR_HANDLED' END,
             1,0,@ErrorNumber,@ErrorMessage);
        END CATCH;
    END;

    IF @CaptureSchedulers=1
    BEGIN
        SET @CapturedAtUtc=SYSUTCDATETIME();
        BEGIN TRY
            INSERT [#CurrentOverview_CurrentStateSnapshot_Schedulers]
            (
                [SnapshotId],[CapturedAtUtc],[scheduler_address],[scheduler_id],
                [parent_node_id],[status],[is_online],[is_idle],
                [current_tasks_count],[runnable_tasks_count],[current_workers_count],
                [active_workers_count],[work_queue_count],[pending_disk_io_count],[load_factor]
            )
            SELECT
                @SnapshotId,@CapturedAtUtc,[s].[scheduler_address],[s].[scheduler_id],
                [s].[parent_node_id],[s].[status],[s].[is_online],[s].[is_idle],
                [s].[current_tasks_count],[s].[runnable_tasks_count],[s].[current_workers_count],
                [s].[active_workers_count],[s].[work_queue_count],[s].[pending_disk_io_count],[s].[load_factor]
            FROM [sys].[dm_os_schedulers] AS [s] WITH (NOLOCK)
            WHERE [s].[scheduler_id] < 1048576
              AND
              (
                  EXISTS
                  (
                      SELECT 1
                      FROM [#CurrentOverview_CurrentStateSnapshot_Requests] AS [r]
                      WHERE [r].[SnapshotId]=@SnapshotId
                        AND [r].[scheduler_id]=[s].[scheduler_id]
                  )
                  OR EXISTS
                  (
                      SELECT 1
                      FROM [#CurrentOverview_CurrentStateSnapshot_Tasks] AS [t]
                      WHERE [t].[SnapshotId]=@SnapshotId
                        AND [t].[scheduler_id]=[s].[scheduler_id]
                  )
              );

            SET @RowCount=@@ROWCOUNT;
            SET @CompletedAtUtc=SYSUTCDATETIME();
            INSERT [#CurrentOverview_CurrentStateSnapshot_SourceStatus]
            VALUES
            (@SnapshotId,100,'SCHEDULERS',N'sys.dm_os_schedulers',@CapturedAtUtc,@CompletedAtUtc,
             @BaseStatusCode,@BaseIsPartial,@RowCount,NULL,NULL);
        END TRY
        BEGIN CATCH
            SELECT @ErrorNumber=ERROR_NUMBER(),@ErrorMessage=ERROR_MESSAGE(),@CompletedAtUtc=SYSUTCDATETIME();
            INSERT [#CurrentOverview_CurrentStateSnapshot_SourceStatus]
            VALUES
            (@SnapshotId,100,'SCHEDULERS',N'sys.dm_os_schedulers',@CapturedAtUtc,@CompletedAtUtc,
             CASE WHEN @ErrorNumber=1222 THEN 'TIMEOUT' WHEN @ErrorNumber IN(229,262,297,300,371,916) THEN 'DENIED_PERMISSION' ELSE 'ERROR_HANDLED' END,
             1,0,@ErrorNumber,@ErrorMessage);
        END CATCH;
    END;

    IF @CaptureTransactions=1
    BEGIN
        SET @CapturedAtUtc=SYSUTCDATETIME();
        BEGIN TRY
            INSERT [#CurrentOverview_CurrentStateSnapshot_SessionTransactions]
            (
                [SnapshotId],[CapturedAtUtc],[session_id],[transaction_id],
                [transaction_descriptor],[enlist_count],[is_user_transaction],
                [is_local],[is_enlisted],[is_bound],[open_transaction_count]
            )
            SELECT
                @SnapshotId,@CapturedAtUtc,[t].[session_id],[t].[transaction_id],
                [t].[transaction_descriptor],[t].[enlist_count],[t].[is_user_transaction],
                [t].[is_local],[t].[is_enlisted],[t].[is_bound],[t].[open_transaction_count]
            FROM [sys].[dm_tran_session_transactions] AS [t] WITH (NOLOCK)
            WHERE EXISTS
            (
                SELECT 1
                FROM [#CurrentOverview_CurrentStateSnapshot_Sessions] AS [s]
                WHERE [s].[SnapshotId]=@SnapshotId
                  AND [s].[session_id]=[t].[session_id]
            );

            SET @RowCount=@@ROWCOUNT;
            SET @CompletedAtUtc=SYSUTCDATETIME();
            INSERT [#CurrentOverview_CurrentStateSnapshot_SourceStatus]
            VALUES
            (@SnapshotId,110,'SESSION_TRANSACTIONS',N'sys.dm_tran_session_transactions',
             @CapturedAtUtc,@CompletedAtUtc,@BaseStatusCode,@BaseIsPartial,@RowCount,NULL,NULL);
        END TRY
        BEGIN CATCH
            SELECT @ErrorNumber=ERROR_NUMBER(),@ErrorMessage=ERROR_MESSAGE(),@CompletedAtUtc=SYSUTCDATETIME();
            INSERT [#CurrentOverview_CurrentStateSnapshot_SourceStatus]
            VALUES
            (@SnapshotId,110,'SESSION_TRANSACTIONS',N'sys.dm_tran_session_transactions',
             @CapturedAtUtc,@CompletedAtUtc,
             CASE WHEN @ErrorNumber=1222 THEN 'TIMEOUT' WHEN @ErrorNumber IN(229,262,297,300,371,916) THEN 'DENIED_PERMISSION' ELSE 'ERROR_HANDLED' END,
             1,0,@ErrorNumber,@ErrorMessage);
        END CATCH;

        SET @CapturedAtUtc=SYSUTCDATETIME();
        BEGIN TRY
            INSERT [#CurrentOverview_CurrentStateSnapshot_ActiveTransactions]
            (
                [SnapshotId],[CapturedAtUtc],[transaction_id],[name],
                [transaction_begin_time],[transaction_type],[transaction_uow],
                [transaction_state],[transaction_status]
            )
            SELECT
                @SnapshotId,@CapturedAtUtc,[t].[transaction_id],[t].[name],
                [t].[transaction_begin_time],[t].[transaction_type],[t].[transaction_uow],
                [t].[transaction_state],[t].[transaction_status]
            FROM [sys].[dm_tran_active_transactions] AS [t] WITH (NOLOCK)
            WHERE EXISTS
            (
                SELECT 1
                FROM [#CurrentOverview_CurrentStateSnapshot_SessionTransactions] AS [st]
                WHERE [st].[SnapshotId]=@SnapshotId
                  AND [st].[transaction_id]=[t].[transaction_id]
            );

            SET @RowCount=@@ROWCOUNT;
            SET @CompletedAtUtc=SYSUTCDATETIME();
            INSERT [#CurrentOverview_CurrentStateSnapshot_SourceStatus]
            VALUES
            (@SnapshotId,120,'ACTIVE_TRANSACTIONS',N'sys.dm_tran_active_transactions',
             @CapturedAtUtc,@CompletedAtUtc,@BaseStatusCode,@BaseIsPartial,@RowCount,NULL,NULL);
        END TRY
        BEGIN CATCH
            SELECT @ErrorNumber=ERROR_NUMBER(),@ErrorMessage=ERROR_MESSAGE(),@CompletedAtUtc=SYSUTCDATETIME();
            INSERT [#CurrentOverview_CurrentStateSnapshot_SourceStatus]
            VALUES
            (@SnapshotId,120,'ACTIVE_TRANSACTIONS',N'sys.dm_tran_active_transactions',
             @CapturedAtUtc,@CompletedAtUtc,
             CASE WHEN @ErrorNumber=1222 THEN 'TIMEOUT' WHEN @ErrorNumber IN(229,262,297,300,371,916) THEN 'DENIED_PERMISSION' ELSE 'ERROR_HANDLED' END,
             1,0,@ErrorNumber,@ErrorMessage);
        END CATCH;

        SET @CapturedAtUtc=SYSUTCDATETIME();
        BEGIN TRY
            INSERT [#CurrentOverview_CurrentStateSnapshot_DatabaseTransactions]
            (
                [SnapshotId],[CapturedAtUtc],[transaction_id],[database_id],
                [database_transaction_begin_time],[database_transaction_type],
                [database_transaction_state],[database_transaction_log_record_count],
                [database_transaction_log_bytes_used],[database_transaction_log_bytes_reserved],
                [database_transaction_log_bytes_used_system],
                [database_transaction_log_bytes_reserved_system]
            )
            SELECT
                @SnapshotId,@CapturedAtUtc,[t].[transaction_id],[t].[database_id],
                [t].[database_transaction_begin_time],[t].[database_transaction_type],
                [t].[database_transaction_state],[t].[database_transaction_log_record_count],
                [t].[database_transaction_log_bytes_used],[t].[database_transaction_log_bytes_reserved],
                [t].[database_transaction_log_bytes_used_system],
                [t].[database_transaction_log_bytes_reserved_system]
            FROM [sys].[dm_tran_database_transactions] AS [t] WITH (NOLOCK)
            WHERE EXISTS
            (
                SELECT 1
                FROM [#CurrentOverview_CurrentStateSnapshot_SessionTransactions] AS [st]
                WHERE [st].[SnapshotId]=@SnapshotId
                  AND [st].[transaction_id]=[t].[transaction_id]
            );

            SET @RowCount=@@ROWCOUNT;
            SET @CompletedAtUtc=SYSUTCDATETIME();
            INSERT [#CurrentOverview_CurrentStateSnapshot_SourceStatus]
            VALUES
            (@SnapshotId,130,'DATABASE_TRANSACTIONS',N'sys.dm_tran_database_transactions',
             @CapturedAtUtc,@CompletedAtUtc,@BaseStatusCode,@BaseIsPartial,@RowCount,NULL,NULL);
        END TRY
        BEGIN CATCH
            SELECT @ErrorNumber=ERROR_NUMBER(),@ErrorMessage=ERROR_MESSAGE(),@CompletedAtUtc=SYSUTCDATETIME();
            INSERT [#CurrentOverview_CurrentStateSnapshot_SourceStatus]
            VALUES
            (@SnapshotId,130,'DATABASE_TRANSACTIONS',N'sys.dm_tran_database_transactions',
             @CapturedAtUtc,@CompletedAtUtc,
             CASE WHEN @ErrorNumber=1222 THEN 'TIMEOUT' WHEN @ErrorNumber IN(229,262,297,300,371,916) THEN 'DENIED_PERMISSION' ELSE 'ERROR_HANDLED' END,
             1,0,@ErrorNumber,@ErrorMessage);
        END CATCH;
    END;

    IF @CaptureTempDbUsage=1
    BEGIN
        SET @CapturedAtUtc=SYSUTCDATETIME();
        BEGIN TRY
            EXEC [sys].[sp_executesql] N'
                USE [tempdb];
                INSERT [#CurrentOverview_CurrentStateSnapshot_TempDbSessionUsage]
                (
                    [SnapshotId],[CapturedAtUtc],[session_id],
                    [user_objects_alloc_page_count],[user_objects_dealloc_page_count],
                    [internal_objects_alloc_page_count],[internal_objects_dealloc_page_count]
                )
                SELECT
                    @SnapshotId,@CapturedAtUtc,[u].[session_id],
                    [u].[user_objects_alloc_page_count],[u].[user_objects_dealloc_page_count],
                    [u].[internal_objects_alloc_page_count],[u].[internal_objects_dealloc_page_count]
                FROM [sys].[dm_db_session_space_usage] AS [u] WITH (NOLOCK)
                WHERE EXISTS
                (
                    SELECT 1
                    FROM [#CurrentOverview_CurrentStateSnapshot_Sessions] AS [s]
                    WHERE [s].[SnapshotId]=@SnapshotId
                      AND [s].[session_id]=[u].[session_id]
                );',
                N'@SnapshotId uniqueidentifier,@CapturedAtUtc datetime2(3)',
                @SnapshotId=@SnapshotId,@CapturedAtUtc=@CapturedAtUtc;

            SET @RowCount=
                (SELECT COUNT_BIG(*) FROM [#CurrentOverview_CurrentStateSnapshot_TempDbSessionUsage]
                 WHERE [SnapshotId]=@SnapshotId);
            SET @CompletedAtUtc=SYSUTCDATETIME();
            INSERT [#CurrentOverview_CurrentStateSnapshot_SourceStatus]
            VALUES
            (@SnapshotId,140,'TEMPDB_SESSION_USAGE',N'tempdb.sys.dm_db_session_space_usage',
             @CapturedAtUtc,@CompletedAtUtc,@BaseStatusCode,@BaseIsPartial,@RowCount,NULL,NULL);
        END TRY
        BEGIN CATCH
            SELECT @ErrorNumber=ERROR_NUMBER(),@ErrorMessage=ERROR_MESSAGE(),@CompletedAtUtc=SYSUTCDATETIME();
            INSERT [#CurrentOverview_CurrentStateSnapshot_SourceStatus]
            VALUES
            (@SnapshotId,140,'TEMPDB_SESSION_USAGE',N'tempdb.sys.dm_db_session_space_usage',
             @CapturedAtUtc,@CompletedAtUtc,
             CASE WHEN @ErrorNumber=1222 THEN 'TIMEOUT' WHEN @ErrorNumber IN(229,262,297,300,371,916) THEN 'DENIED_PERMISSION' ELSE 'ERROR_HANDLED' END,
             1,0,@ErrorNumber,@ErrorMessage);
        END CATCH;

        SET @CapturedAtUtc=SYSUTCDATETIME();
        BEGIN TRY
            EXEC [sys].[sp_executesql] N'
                USE [tempdb];
                INSERT [#CurrentOverview_CurrentStateSnapshot_TempDbTaskUsage]
                (
                    [SnapshotId],[CapturedAtUtc],[session_id],[request_id],[exec_context_id],
                    [user_objects_alloc_page_count],[user_objects_dealloc_page_count],
                    [internal_objects_alloc_page_count],[internal_objects_dealloc_page_count]
                )
                SELECT
                    @SnapshotId,@CapturedAtUtc,[u].[session_id],[u].[request_id],[u].[exec_context_id],
                    [u].[user_objects_alloc_page_count],[u].[user_objects_dealloc_page_count],
                    [u].[internal_objects_alloc_page_count],[u].[internal_objects_dealloc_page_count]
                FROM [sys].[dm_db_task_space_usage] AS [u] WITH (NOLOCK)
                WHERE EXISTS
                (
                    SELECT 1
                    FROM [#CurrentOverview_CurrentStateSnapshot_Requests] AS [r]
                    WHERE [r].[SnapshotId]=@SnapshotId
                      AND [r].[session_id]=[u].[session_id]
                      AND [r].[request_id]=[u].[request_id]
                );',
                N'@SnapshotId uniqueidentifier,@CapturedAtUtc datetime2(3)',
                @SnapshotId=@SnapshotId,@CapturedAtUtc=@CapturedAtUtc;

            SET @RowCount=
                (SELECT COUNT_BIG(*) FROM [#CurrentOverview_CurrentStateSnapshot_TempDbTaskUsage]
                 WHERE [SnapshotId]=@SnapshotId);
            SET @CompletedAtUtc=SYSUTCDATETIME();
            INSERT [#CurrentOverview_CurrentStateSnapshot_SourceStatus]
            VALUES
            (@SnapshotId,150,'TEMPDB_TASK_USAGE',N'tempdb.sys.dm_db_task_space_usage',
             @CapturedAtUtc,@CompletedAtUtc,@BaseStatusCode,@BaseIsPartial,@RowCount,NULL,NULL);
        END TRY
        BEGIN CATCH
            SELECT @ErrorNumber=ERROR_NUMBER(),@ErrorMessage=ERROR_MESSAGE(),@CompletedAtUtc=SYSUTCDATETIME();
            INSERT [#CurrentOverview_CurrentStateSnapshot_SourceStatus]
            VALUES
            (@SnapshotId,150,'TEMPDB_TASK_USAGE',N'tempdb.sys.dm_db_task_space_usage',
             @CapturedAtUtc,@CompletedAtUtc,
             CASE WHEN @ErrorNumber=1222 THEN 'TIMEOUT' WHEN @ErrorNumber IN(229,262,297,300,371,916) THEN 'DENIED_PERMISSION' ELSE 'ERROR_HANDLED' END,
             1,0,@ErrorNumber,@ErrorMessage);
        END CATCH;
    END;

    IF @CaptureSqlText=1
    BEGIN
        SET @CapturedAtUtc=SYSUTCDATETIME();
        BEGIN TRY
            CREATE TABLE [#InternalCaptureCurrentStateSnapshot_SqlHandleCandidate]
            (
                [SqlHandle] varbinary(64) NOT NULL PRIMARY KEY
            );

            INSERT [#InternalCaptureCurrentStateSnapshot_SqlHandleCandidate]([SqlHandle])
            SELECT [h].[SqlHandle]
            FROM
            (
                SELECT [r].[sql_handle] AS [SqlHandle]
                FROM [#CurrentOverview_CurrentStateSnapshot_Requests] AS [r]
                WHERE [r].[SnapshotId]=@SnapshotId
                  AND [r].[sql_handle] IS NOT NULL
                UNION
                SELECT [c].[most_recent_sql_handle]
                FROM [#CurrentOverview_CurrentStateSnapshot_Connections] AS [c]
                WHERE [c].[SnapshotId]=@SnapshotId
                  AND [c].[most_recent_sql_handle] IS NOT NULL
            ) AS [h];

            DECLARE @SqlTextCandidateCount bigint=
                (SELECT COUNT_BIG(*) FROM [#InternalCaptureCurrentStateSnapshot_SqlHandleCandidate]);

            IF @MaxSqlTextHandles>0 AND @SqlTextCandidateCount>@MaxSqlTextHandles
            BEGIN
                ;WITH [Limited] AS
                (
                    SELECT
                        [SqlHandle],
                        [RowNumber]=ROW_NUMBER() OVER(ORDER BY [SqlHandle])
                    FROM [#InternalCaptureCurrentStateSnapshot_SqlHandleCandidate]
                )
                DELETE FROM [Limited]
                WHERE [RowNumber]>@MaxSqlTextHandles;
            END;

            INSERT [#CurrentOverview_CurrentStateSnapshot_SqlText]
            (
                [SnapshotId],[CapturedAtUtc],[SqlHandle],[Text],[DatabaseId],
                [ObjectId],[ObjectNumber],[IsEncrypted],[EvidenceStatus]
            )
            SELECT
                @SnapshotId,@CapturedAtUtc,[h].[SqlHandle],[t].[text],[t].[dbid],
                [t].[objectid],[t].[number],[t].[encrypted],
                CONVERT(varchar(40),CASE WHEN [t].[text] IS NULL THEN 'TEXT_UNAVAILABLE' ELSE 'AVAILABLE' END)
            FROM [#InternalCaptureCurrentStateSnapshot_SqlHandleCandidate] AS [h]
            OUTER APPLY [sys].[dm_exec_sql_text]([h].[SqlHandle]) AS [t];

            SET @RowCount=@@ROWCOUNT;
            SET @CompletedAtUtc=SYSUTCDATETIME();
            SET @IsPartial=CASE WHEN @MaxSqlTextHandles>0 AND @SqlTextCandidateCount>@MaxSqlTextHandles THEN 1 ELSE @BaseIsPartial END;
            SET @StatusCode=CASE WHEN @IsPartial=1 THEN 'AVAILABLE_LIMITED' ELSE 'AVAILABLE' END;
            INSERT [#CurrentOverview_CurrentStateSnapshot_SourceStatus]
            VALUES
            (@SnapshotId,80,'SQL_TEXT',N'sys.dm_exec_sql_text',@CapturedAtUtc,@CompletedAtUtc,
             @StatusCode,@IsPartial,@RowCount,NULL,
             CASE WHEN @MaxSqlTextHandles>0 AND @SqlTextCandidateCount>@MaxSqlTextHandles
                  THEN N'Die Zahl unterschiedlicher SQL-Handles überschritt @MaxSqlTextHandles.'
                  ELSE NULL END);
        END TRY
        BEGIN CATCH
            SELECT @ErrorNumber=ERROR_NUMBER(),@ErrorMessage=ERROR_MESSAGE(),@CompletedAtUtc=SYSUTCDATETIME();
            INSERT [#CurrentOverview_CurrentStateSnapshot_SourceStatus]
            VALUES
            (@SnapshotId,80,'SQL_TEXT',N'sys.dm_exec_sql_text',@CapturedAtUtc,@CompletedAtUtc,
             CASE WHEN @ErrorNumber=1222 THEN 'TIMEOUT' WHEN @ErrorNumber IN(229,262,297,300,371,916) THEN 'DENIED_PERMISSION' ELSE 'ERROR_HANDLED' END,
             1,0,@ErrorNumber,@ErrorMessage);
        END CATCH;
    END;

END;
GO
-- END SOURCE: Code/02_CurrentState/005_InternalCaptureCurrentStateSnapshot.sql

-- BEGIN SOURCE: Code/02_CurrentState/010_USP_CurrentSessions.sql
/*
===============================================================================
Objekt       : monitor.USP_CurrentSessions
Version      : 2.2.0
Stand        : 2026-07-22
Typ          : Stored Procedure
Zweck        : Liefert aktuelle Sessions mit exakten Mehrfachfiltern, Pattern-
               Filtern und RAW-, CONSOLE- oder JSON-Ausgabe.
SQL-Version  : SQL Server 2019 oder neuer; Regex ab SQL Server 2025 und
               Compatibility Level 170.
Listen       : | trennt außerhalb von [...]. Werte bleiben case-sensitiv.
Steuerwerte  : werden getrimmt und case-insensitiv normalisiert.
Resultsets   : RAW: Status, Sessions. CONSOLE: lesbare Status-/Sessionansicht.
               NONE: keine Resultsets. JSON: meta, sessions, warnings.
===============================================================================
*/
CREATE OR ALTER PROCEDURE [monitor].[USP_CurrentSessions]
      @SessionIds                   nvarchar(max)  = NULL
    , @EigeneSessionsModus          varchar(16)    = 'ALLE'
    , @AktuelleSessionEinbeziehen   bit            = 0
    , @SystemSessionsEinbeziehen    bit            = 0
    , @ToolHintergrundabfragenEinbeziehen bit       = 0
    , @InaktiveSessionsEinbeziehen  bit            = 1
    , @LoginNames                   nvarchar(max)  = NULL
    , @LoginNamePattern             nvarchar(4000) = NULL
    , @HostNames                    nvarchar(max)  = NULL
    , @HostNamePattern              nvarchar(4000) = NULL
    , @ProgramNames                 nvarchar(max)  = NULL
    , @ProgramNamePattern           nvarchar(4000) = NULL
    , @DatabaseNames                nvarchar(max)  = NULL
    , @DatabaseNamePattern          nvarchar(4000) = NULL
    , @HighImpactConfirmed              bit            = 0
    , @MitSqlText                   bit            = 0
    , @MaxSqlTextZeichen            int            = 2000
    , @MaxZeilen                    int            = 500
    , @Sortierung                   varchar(32)    = 'CPU'
    , @ResultSetArt                 varchar(16)    = 'CONSOLE'
    , @ResultTablesJson               nvarchar(max) = NULL
    , @JsonErzeugen                 bit            = 0
    , @Json                         nvarchar(max)  = NULL OUTPUT
    , @PrintMeldungen               bit            = 1
    , @Hilfe                        bit            = 0
    , @ParentCurrentStateSnapshotId uniqueidentifier = NULL
AS
BEGIN
    SET NOCOUNT ON;
    SET LOCK_TIMEOUT 0;
    SET @Json = NULL;

    DECLARE @ModuleName sysname = N'USP_CurrentSessions';
    DECLARE @CollectionTimeUtc datetime2(3) = SYSUTCDATETIME();
    DECLARE @StatusCode varchar(40) = 'AVAILABLE';
    DECLARE @IsPartial bit = 0;
    DECLARE @RowCount bigint = 0;
    DECLARE @HasMoreRows bit = 0;
    DECLARE @ErrorNumber int = NULL;
    DECLARE @ErrorMessage nvarchar(2048) = NULL;
    DECLARE @Detail nvarchar(2000) = NULL;
    DECLARE @RequiredPermission nvarchar(256) = CASE WHEN TRY_CONVERT(int, SERVERPROPERTY(N'ProductMajorVersion')) >= 16 THEN N'VIEW SERVER PERFORMANCE STATE' ELSE N'VIEW SERVER STATE' END;
    DECLARE @HasFullView bit = CASE WHEN IS_SRVROLEMEMBER(N'sysadmin') = 1 THEN 1 WHEN TRY_CONVERT(int, SERVERPROPERTY(N'ProductMajorVersion')) >= 16 THEN COALESCE(HAS_PERMS_BY_NAME(NULL,N'SERVER',N'VIEW SERVER PERFORMANCE STATE'),0) ELSE COALESCE(HAS_PERMS_BY_NAME(NULL,N'SERVER',N'VIEW SERVER STATE'),0) END;
    DECLARE @ResultSetArtNormalisiert varchar(16) = UPPER(LTRIM(RTRIM(COALESCE(@ResultSetArt,''))));
    DECLARE @TableResultRequested bit = CASE WHEN @ResultSetArtNormalisiert = 'TABLE' THEN 1 ELSE 0 END;
    DECLARE @ConsoleResultRequested bit = CASE WHEN @ResultSetArtNormalisiert = 'CONSOLE' THEN 1 ELSE 0 END;
    DECLARE @TableTarget sysname=NULL;
    IF @TableResultRequested=0 AND NULLIF(LTRIM(RTRIM(COALESCE(@ResultTablesJson,N''))),N'') IS NOT NULL THROW 51011,N'@ResultTablesJson ist ausschließlich mit @ResultSetArt=TABLE zulässig.',1;
    IF @TableResultRequested=1 EXEC [monitor].[InternalPrepareSingleResultTable] @ResultTablesJson=@ResultTablesJson,@ResultName=N'sessions',@TargetTable=@TableTarget OUTPUT,@ThrowOnError=1;
    IF @TableResultRequested = 1 OR @ConsoleResultRequested = 1 SET @ResultSetArtNormalisiert = 'NONE';
    DECLARE @EffectiveMaxZeilen bigint = CASE WHEN @MaxZeilen IS NULL OR @MaxZeilen = 0 THEN CONVERT(bigint,9223372036854775807) ELSE CONVERT(bigint,@MaxZeilen) END;
    DECLARE @CandidateMaxZeilen bigint;
    DECLARE @EvidenceSnapshotStartedAtUtc datetime2(3)=@CollectionTimeUtc;
    DECLARE @ParentSnapshotIsPartial bit=0;
    DECLARE @MonitorPrintMessage nvarchar(2048);

    SET @EigeneSessionsModus = UPPER(LTRIM(RTRIM(COALESCE(@EigeneSessionsModus,'ALLE'))));
    SET @Sortierung = UPPER(LTRIM(RTRIM(COALESCE(@Sortierung,'CPU'))));

    IF @Hilfe = 1
    BEGIN
        PRINT N'monitor.USP_CurrentSessions';
        PRINT N'@SessionIds: Pipe-Liste, z. B. N''57|61''.';
        PRINT N'@ToolHintergrundabfragenEinbeziehen=0 blendet erkannte Object-Explorer-, Copilot- und SQL-Prompt-Hintergrundsessions standardmäßig aus; 1 zeigt sie samt Klassifikation.';
        PRINT N'@LoginNames/@HostNames/@ProgramNames/@DatabaseNames: exakte bracket-aware Pipe-Listen.';
        PRINT N'Die jeweiligen ...Pattern-Parameter akzeptieren LIKE, like:, regex: oder regexi: und sind mit der exakten Liste gegenseitig exklusiv.';
        PRINT N'@MaxZeilen: positiv begrenzt; NULL/0 = unbegrenzt; negativ = INVALID_PARAMETER.';
        PRINT N'@MaxSqlTextZeichen: positiv begrenzt die Darstellung; NULL/0 liefert vollständige Texte.';
        PRINT N'@ResultSetArt: CONSOLE (Default), RAW, TABLE oder NONE; Groß-/Kleinschreibung ist egal.';
        PRINT N'@ParentCurrentStateSnapshotId ist ausschließlich für den laufinternen Overview-Consumer bestimmt; NULL erzwingt einen frischen Einzelread.';
        PRINT N'@JsonErzeugen=1 erzeugt ein JSON-Envelope in @Json OUTPUT.';
        RETURN;
    END;

    CREATE TABLE [#CurrentSessions_SessionIdFilter]
    (
        [SessionId] smallint NOT NULL PRIMARY KEY
    );
    CREATE TABLE [#CurrentSessions_StringFilter]
    (
          [FilterType] varchar(20) COLLATE SQL_Latin1_General_CP1_CS_AS NOT NULL
        , [StringValue] nvarchar(4000) COLLATE SQL_Latin1_General_CP1_CS_AS NOT NULL
        , PRIMARY KEY ([FilterType],[StringValue])
    );

    DECLARE @LoginMode varchar(8), @LoginPattern nvarchar(4000), @LoginFlags varchar(8), @LoginValid bit;
    DECLARE @HostMode varchar(8), @HostPattern nvarchar(4000), @HostFlags varchar(8), @HostValid bit;
    DECLARE @ProgramMode varchar(8), @ProgramPattern nvarchar(4000), @ProgramFlags varchar(8), @ProgramValid bit;
    DECLARE @DatabaseMode varchar(8), @DatabasePattern nvarchar(4000), @DatabaseFlags varchar(8), @DatabaseValid bit;

    BEGIN TRY
        SELECT @LoginMode=[PatternMode],@LoginPattern=[PatternValue],@LoginFlags=[RegexFlags],@LoginValid=[IsValid] FROM [monitor].[TVF_ParsePattern](@LoginNamePattern);
        SELECT @HostMode=[PatternMode],@HostPattern=[PatternValue],@HostFlags=[RegexFlags],@HostValid=[IsValid] FROM [monitor].[TVF_ParsePattern](@HostNamePattern);
        SELECT @ProgramMode=[PatternMode],@ProgramPattern=[PatternValue],@ProgramFlags=[RegexFlags],@ProgramValid=[IsValid] FROM [monitor].[TVF_ParsePattern](@ProgramNamePattern);
        SELECT @DatabaseMode=[PatternMode],@DatabasePattern=[PatternValue],@DatabaseFlags=[RegexFlags],@DatabaseValid=[IsValid] FROM [monitor].[TVF_ParsePattern](@DatabaseNamePattern);
    END TRY
    BEGIN CATCH
        SELECT @ErrorNumber=ERROR_NUMBER(),@ErrorMessage=ERROR_MESSAGE(),@IsPartial=1,
               @StatusCode=CASE WHEN ERROR_NUMBER()=1222 THEN 'TIMEOUT'
                                WHEN ERROR_NUMBER() IN(229,262,297,300,371,916) THEN 'DENIED_PERMISSION'
                                ELSE 'ERROR_HANDLED' END;
    END CATCH;

    IF @StatusCode='AVAILABLE' AND @SessionIds IS NOT NULL
    BEGIN
        IF EXISTS (SELECT 1 FROM [monitor].[TVF_ParseBigintList](@SessionIds) WHERE [IsValid]=0 OR [NumberValue] NOT BETWEEN 1 AND 32767)
            SET @StatusCode='INVALID_PARAMETER';
        ELSE
            INSERT [#CurrentSessions_SessionIdFilter]([SessionId])
            SELECT CONVERT(smallint,[NumberValue]) FROM [monitor].[TVF_ParseBigintList](@SessionIds)
            GROUP BY [NumberValue];
    END;

    IF @StatusCode='AVAILABLE'
       AND ((@LoginNames IS NOT NULL AND @LoginNamePattern IS NOT NULL)
         OR (@HostNames IS NOT NULL AND @HostNamePattern IS NOT NULL)
         OR (@ProgramNames IS NOT NULL AND @ProgramNamePattern IS NOT NULL)
         OR (@DatabaseNames IS NOT NULL AND @DatabaseNamePattern IS NOT NULL)
         OR @LoginValid=0 OR @HostValid=0 OR @ProgramValid=0 OR @DatabaseValid=0)
        SET @StatusCode='INVALID_PARAMETER';

    IF @StatusCode='AVAILABLE'
       AND ((@LoginNames IS NOT NULL AND EXISTS(SELECT 1 FROM [monitor].[TVF_ParseStringList](@LoginNames) WHERE [IsValid]=0 OR LEN([StringValue])>128))
         OR (@HostNames IS NOT NULL AND EXISTS(SELECT 1 FROM [monitor].[TVF_ParseStringList](@HostNames) WHERE [IsValid]=0 OR LEN([StringValue])>128))
         OR (@ProgramNames IS NOT NULL AND EXISTS(SELECT 1 FROM [monitor].[TVF_ParseStringList](@ProgramNames) WHERE [IsValid]=0 OR LEN([StringValue])>128))
         OR (@DatabaseNames IS NOT NULL AND EXISTS(SELECT 1 FROM [monitor].[TVF_ParseSqlNameList](@DatabaseNames) WHERE [IsValid]=0)))
        SET @StatusCode='INVALID_PARAMETER';

    IF @StatusCode='AVAILABLE'
    BEGIN
        INSERT [#CurrentSessions_StringFilter]([FilterType],[StringValue]) SELECT 'LOGIN',[StringValue] FROM [monitor].[TVF_ParseStringList](@LoginNames) WHERE [IsValid]=1 GROUP BY [StringValue];
        INSERT [#CurrentSessions_StringFilter]([FilterType],[StringValue]) SELECT 'HOST',[StringValue] FROM [monitor].[TVF_ParseStringList](@HostNames) WHERE [IsValid]=1 GROUP BY [StringValue];
        INSERT [#CurrentSessions_StringFilter]([FilterType],[StringValue]) SELECT 'PROGRAM',[StringValue] FROM [monitor].[TVF_ParseStringList](@ProgramNames) WHERE [IsValid]=1 GROUP BY [StringValue];
        INSERT [#CurrentSessions_StringFilter]([FilterType],[StringValue]) SELECT 'DATABASE',[NameValue] FROM [monitor].[TVF_ParseSqlNameList](@DatabaseNames) WHERE [IsValid]=1 GROUP BY [NameValue];
    END;

    DECLARE @HasRegex bit = CASE WHEN @LoginMode IN('REGEX','REGEXI') OR @HostMode IN('REGEX','REGEXI') OR @ProgramMode IN('REGEX','REGEXI') OR @DatabaseMode IN('REGEX','REGEXI') THEN 1 ELSE 0 END;
    IF @StatusCode='AVAILABLE' AND @HasRegex=1
       AND (TRY_CONVERT(int,SERVERPROPERTY(N'ProductMajorVersion'))<17 OR COALESCE((SELECT [compatibility_level] FROM [master].[sys].[databases] WITH (NOLOCK) WHERE [database_id]=DB_ID()),0)<170)
    BEGIN
        SET @StatusCode='UNAVAILABLE_FEATURE';
        SET @ErrorMessage=N'Regex benötigt SQL Server 2025 und Compatibility Level 170 für die Installationsdatenbank.';
    END;

    IF @StatusCode='AVAILABLE'
       AND (@EigeneSessionsModus NOT IN('ALLE','NUR','AUSSCHLIESSEN') OR @Sortierung NOT IN('CPU','READS','WRITES','LOGIN','SESSION') OR @ResultSetArtNormalisiert NOT IN('RAW','CONSOLE','NONE') OR @MaxZeilen<0 OR @MaxSqlTextZeichen<0 OR @ToolHintergrundabfragenEinbeziehen IS NULL OR @ToolHintergrundabfragenEinbeziehen NOT IN(0,1))
    BEGIN
        SET @StatusCode='INVALID_PARAMETER';
        SET @ErrorMessage=N'Mindestens ein Steuerparameter ist ungültig.';
    END;

    IF @StatusCode='INVALID_PARAMETER' AND @ErrorMessage IS NULL
        SET @ErrorMessage=N'Ungültige Liste, Kombination oder Patternangabe.';

    CREATE TABLE [#CurrentSessions_Result]
    (
          [SessionId] smallint NOT NULL, [RequestId] int NULL, [IsUserProcess] bit NOT NULL
        , [SessionStatus] nvarchar(30) NULL, [RequestStatus] nvarchar(30) NULL
        , [LoginName] nvarchar(128) NULL, [OriginalLoginName] nvarchar(128) NULL
        , [HostName] nvarchar(128) NULL, [ProgramName] nvarchar(128) NULL
        , [IsToolBackgroundQuery] bit NOT NULL
        , [ToolBackgroundRuleCode] varchar(64) NULL
        , [ToolBackgroundCategory] varchar(40) NULL
        , [ToolBackgroundDetection] varchar(40) NULL
        , [ToolBackgroundConfidence] varchar(16) NULL
        , [ClientInterfaceName] nvarchar(32) NULL, [LoginTime] datetime NULL
        , [LastRequestStartTime] datetime NULL, [LastRequestEndTime] datetime NULL
        , [DatabaseId] smallint NULL, [DatabaseName] sysname NULL
        , [OpenTransactionCount] int NULL, [TransactionIsolationLevel] nvarchar(40) NULL
        , [SessionCpuMs] int NULL, [SessionReads] bigint NULL, [SessionWrites] bigint NULL
        , [SessionLogicalReads] bigint NULL, [SessionMemoryMb] decimal(19,2) NULL
        , [SessionRowCount] bigint NULL, [RequestCpuMs] int NULL, [RequestElapsedMs] int NULL
        , [RequestLogicalReads] bigint NULL, [RequestReads] bigint NULL, [RequestWrites] bigint NULL
        , [BlockingSessionId] smallint NULL, [WaitType] nvarchar(120) NULL, [WaitTimeMs] int NULL
        , [WaitResource] nvarchar(256) NULL, [PercentComplete] real NULL
        , [ClientNetAddress] varchar(48) NULL, [NetTransport] nvarchar(40) NULL
        , [ProtocolType] nvarchar(40) NULL, [EncryptOption] nvarchar(40) NULL
        , [AuthScheme] nvarchar(40) NULL
        , [CurrentStatementCharacters] bigint NULL, [CurrentStatementBytes] bigint NULL
        , [CurrentStatementIsTruncated] bit NOT NULL DEFAULT(0), [CurrentStatement] nvarchar(max) NULL
        , [BatchTextCharacters] bigint NULL, [BatchTextBytes] bigint NULL
        , [BatchTextIsTruncated] bit NOT NULL DEFAULT(0), [BatchText] nvarchar(max) NULL
    );

    CREATE TABLE [#CurrentSessions_SourceSessions]
    (
          [session_id] smallint NOT NULL PRIMARY KEY
        , [is_user_process] bit NOT NULL
        , [status] nvarchar(30) NOT NULL
        , [login_name] nvarchar(128) NOT NULL
        , [original_login_name] nvarchar(128) NOT NULL
        , [host_name] nvarchar(128) NULL
        , [program_name] nvarchar(128) NULL
        , [client_interface_name] nvarchar(32) NULL
        , [login_time] datetime NOT NULL
        , [last_request_start_time] datetime NOT NULL
        , [last_request_end_time] datetime NULL
        , [open_transaction_count] int NOT NULL
        , [transaction_isolation_level] smallint NOT NULL
        , [cpu_time] int NOT NULL
        , [reads] bigint NOT NULL
        , [writes] bigint NOT NULL
        , [logical_reads] bigint NOT NULL
        , [memory_usage] int NOT NULL
        , [row_count] bigint NOT NULL
    );
    CREATE TABLE [#CurrentSessions_SourceRequests]
    (
          [session_id] smallint NOT NULL
        , [request_id] int NOT NULL
        , [status] nvarchar(30) NOT NULL
        , [database_id] smallint NOT NULL
        , [cpu_time] int NOT NULL
        , [total_elapsed_time] int NOT NULL
        , [logical_reads] bigint NOT NULL
        , [reads] bigint NOT NULL
        , [writes] bigint NOT NULL
        , [blocking_session_id] smallint NULL
        , [wait_type] nvarchar(60) NULL
        , [wait_time] int NOT NULL
        , [wait_resource] nvarchar(256) NOT NULL
        , [percent_complete] real NOT NULL
        , [sql_handle] varbinary(64) NULL
        , [statement_start_offset] int NULL
        , [statement_end_offset] int NULL
        , PRIMARY KEY ([session_id],[request_id])
    );
    CREATE TABLE [#CurrentSessions_SourceConnections]
    (
          [session_id] int NULL
        , [connection_id] uniqueidentifier NOT NULL PRIMARY KEY
        , [most_recent_sql_handle] varbinary(64) NULL
        , [client_net_address] varchar(48) NULL
        , [net_transport] nvarchar(40) NOT NULL
        , [protocol_type] nvarchar(40) NULL
        , [encrypt_option] nvarchar(40) NOT NULL
        , [auth_scheme] nvarchar(40) NOT NULL
    );
    CREATE INDEX [IX_CurrentSessions_SourceConnections_SessionId]
        ON [#CurrentSessions_SourceConnections]([session_id]);
    CREATE TABLE [#CurrentSessions_SourceSqlText]
    (
          [SqlHandle] varbinary(64) NOT NULL PRIMARY KEY
        , [text] nvarchar(max) NULL
        , [dbid] int NULL
        , [objectid] int NULL
        , [number] smallint NULL
        , [encrypted] bit NULL
    );

    IF @StatusCode='AVAILABLE' AND @ParentCurrentStateSnapshotId IS NOT NULL
    BEGIN
        BEGIN TRY
            EXEC [sys].[sp_executesql] N'
                DECLARE @Probe int;
                SELECT @Probe=0 FROM [#CurrentOverview_CurrentStateSnapshot_Context] WHERE 1=0;
                SELECT @Probe=0 FROM [#CurrentOverview_CurrentStateSnapshot_SourceStatus] WHERE 1=0;
                SELECT @Probe=0 FROM [#CurrentOverview_CurrentStateSnapshot_Sessions] WHERE 1=0;
                SELECT @Probe=0 FROM [#CurrentOverview_CurrentStateSnapshot_Requests] WHERE 1=0;
                SELECT @Probe=0 FROM [#CurrentOverview_CurrentStateSnapshot_Connections] WHERE 1=0;
                SELECT @Probe=0 FROM [#CurrentOverview_CurrentStateSnapshot_SqlText] WHERE 1=0;';

            IF NOT EXISTS
            (
                SELECT 1
                FROM [#CurrentOverview_CurrentStateSnapshot_Context]
                WHERE [SnapshotId]=@ParentCurrentStateSnapshotId
                  AND [OwnerSessionId]=CONVERT(smallint,@@SPID)
                  AND [ContractVersion]=2
            )
            BEGIN
                SET @StatusCode='INVALID_PARENT_SNAPSHOT';
                SET @IsPartial=1;
                SET @ErrorMessage=N'Die Parent-Snapshot-ID gehört nicht zum aktuellen Aufruf.';
            END
            ELSE
            BEGIN
                INSERT [#CurrentSessions_SourceSessions]
                SELECT
                      [session_id],[is_user_process],[status],[login_name],[original_login_name]
                    , [host_name],[program_name],[client_interface_name],[login_time]
                    , [last_request_start_time],[last_request_end_time],[open_transaction_count]
                    , [transaction_isolation_level],[cpu_time],[reads],[writes],[logical_reads]
                    , [memory_usage],[row_count]
                FROM [#CurrentOverview_CurrentStateSnapshot_Sessions]
                WHERE [SnapshotId]=@ParentCurrentStateSnapshotId;

                INSERT [#CurrentSessions_SourceRequests]
                SELECT
                      [session_id],[request_id],[status],[database_id],[cpu_time]
                    , [total_elapsed_time],[logical_reads],[reads],[writes]
                    , [blocking_session_id],[wait_type],[wait_time],[wait_resource]
                    , [percent_complete],[sql_handle],[statement_start_offset],[statement_end_offset]
                FROM [#CurrentOverview_CurrentStateSnapshot_Requests]
                WHERE [SnapshotId]=@ParentCurrentStateSnapshotId;

                INSERT [#CurrentSessions_SourceConnections]
                SELECT
                      [session_id],[connection_id],[most_recent_sql_handle],[client_net_address]
                    , [net_transport],[protocol_type],[encrypt_option],[auth_scheme]
                FROM [#CurrentOverview_CurrentStateSnapshot_Connections]
                WHERE [SnapshotId]=@ParentCurrentStateSnapshotId;

                IF @MitSqlText=1
                    INSERT [#CurrentSessions_SourceSqlText]
                    SELECT [SqlHandle],[Text],[DatabaseId],[ObjectId],[ObjectNumber],[IsEncrypted]
                    FROM [#CurrentOverview_CurrentStateSnapshot_SqlText]
                    WHERE [SnapshotId]=@ParentCurrentStateSnapshotId;

                SELECT
                      @EvidenceSnapshotStartedAtUtc=MIN([CapturedAtUtc])
                    , @ParentSnapshotIsPartial=CONVERT(bit,MAX(CONVERT(int,[IsPartial])))
                FROM [#CurrentOverview_CurrentStateSnapshot_SourceStatus]
                WHERE [SnapshotId]=@ParentCurrentStateSnapshotId
                  AND [SourceCode] IN ('SESSIONS','REQUESTS','CONNECTIONS','SQL_TEXT');
            END;
        END TRY
        BEGIN CATCH
            SELECT
                  @ErrorNumber=ERROR_NUMBER()
                , @ErrorMessage=ERROR_MESSAGE()
                , @IsPartial=1
                , @StatusCode=CASE WHEN ERROR_NUMBER()=1222 THEN 'TIMEOUT'
                    WHEN ERROR_NUMBER() IN(229,262,297,300,371,916) THEN 'DENIED_PERMISSION'
                    ELSE 'INVALID_PARENT_SNAPSHOT' END;
        END CATCH;
    END
    ELSE IF @StatusCode='AVAILABLE'
    BEGIN TRY
        SET @EvidenceSnapshotStartedAtUtc=SYSUTCDATETIME();

        INSERT [#CurrentSessions_SourceSessions]
        SELECT
              [session_id],[is_user_process],[status],[login_name],[original_login_name]
            , [host_name],[program_name],[client_interface_name],[login_time]
            , [last_request_start_time],[last_request_end_time],[open_transaction_count]
            , [transaction_isolation_level],[cpu_time],[reads],[writes],[logical_reads]
            , [memory_usage],[row_count]
        FROM [sys].[dm_exec_sessions] WITH (NOLOCK);

        INSERT [#CurrentSessions_SourceRequests]
        SELECT
              [session_id],[request_id],[status],[database_id],[cpu_time]
            , [total_elapsed_time],[logical_reads],[reads],[writes]
            , [blocking_session_id],[wait_type],[wait_time],[wait_resource]
            , [percent_complete],[sql_handle],[statement_start_offset],[statement_end_offset]
        FROM [sys].[dm_exec_requests] WITH (NOLOCK);

        INSERT [#CurrentSessions_SourceConnections]
        SELECT
              [session_id],[connection_id],[most_recent_sql_handle],[client_net_address]
            , [net_transport],[protocol_type],[encrypt_option],[auth_scheme]
        FROM [sys].[dm_exec_connections] WITH (NOLOCK);

        IF @MitSqlText=1
        BEGIN
            INSERT [#CurrentSessions_SourceSqlText]
            (
                [SqlHandle],[text],[dbid],[objectid],[number],[encrypted]
            )
            SELECT
                  [h].[SqlHandle],[t].[text],[t].[dbid],[t].[objectid],[t].[number],[t].[encrypted]
            FROM
            (
                SELECT [sql_handle] AS [SqlHandle]
                FROM [#CurrentSessions_SourceRequests]
                WHERE [sql_handle] IS NOT NULL
                UNION
                SELECT [most_recent_sql_handle]
                FROM [#CurrentSessions_SourceConnections]
                WHERE [most_recent_sql_handle] IS NOT NULL
            ) AS [h]
            OUTER APPLY [sys].[dm_exec_sql_text]([h].[SqlHandle]) AS [t];
        END;
    END TRY
    BEGIN CATCH
        SELECT
              @ErrorNumber=ERROR_NUMBER()
            , @ErrorMessage=ERROR_MESSAGE()
            , @IsPartial=1
            , @StatusCode=CASE WHEN ERROR_NUMBER()=1222 THEN 'TIMEOUT'
                WHEN ERROR_NUMBER() IN(229,262,297,300,371,916) THEN 'DENIED_PERMISSION'
                ELSE 'ERROR_HANDLED' END;
    END CATCH;

    SET @CandidateMaxZeilen = CASE WHEN @HasRegex=1 OR @MaxZeilen IS NULL OR @MaxZeilen=0 THEN CONVERT(bigint,9223372036854775807) ELSE CONVERT(bigint,@MaxZeilen)+1 END;

    IF @StatusCode='AVAILABLE'
    BEGIN TRY
        INSERT [#CurrentSessions_Result]
        SELECT TOP (@CandidateMaxZeilen)
              [s].[session_id],[r].[request_id],[s].[is_user_process],[s].[status],[r].[status]
            , [s].[login_name],[s].[original_login_name],[s].[host_name],[s].[program_name]
            , [tool].[IsToolBackgroundQuery],[tool].[ToolBackgroundRuleCode]
            , [tool].[ToolBackgroundCategory]
            , [tool].[ToolBackgroundDetection],[tool].[ToolBackgroundConfidence]
            , [s].[client_interface_name]
            , [s].[login_time],[s].[last_request_start_time],[s].[last_request_end_time],[r].[database_id],[d].[name]
            , [s].[open_transaction_count]
            , CASE [s].[transaction_isolation_level] WHEN 0 THEN N'Unspecified' WHEN 1 THEN N'ReadUncommitted' WHEN 2 THEN N'ReadCommitted' WHEN 3 THEN N'RepeatableRead' WHEN 4 THEN N'Serializable' WHEN 5 THEN N'Snapshot' END
            , [s].[cpu_time],[s].[reads],[s].[writes],[s].[logical_reads],CONVERT(decimal(19,2),[s].[memory_usage]*8.0/1024.0),[s].[row_count]
            , [r].[cpu_time],[r].[total_elapsed_time],[r].[logical_reads],[r].[reads],[r].[writes],NULLIF([r].[blocking_session_id],0)
            , [r].[wait_type],[r].[wait_time],[r].[wait_resource],[r].[percent_complete]
            , [c].[client_net_address],[c].[net_transport],[c].[protocol_type],[c].[encrypt_option],[c].[auth_scheme]
            , NULL,NULL,CONVERT(bit,0),CASE WHEN @MitSqlText=1 THEN [st].[StatementText] END
            , NULL,NULL,CONVERT(bit,0),CASE WHEN @MitSqlText=1 THEN [t].[text] END
        FROM [#CurrentSessions_SourceSessions] AS [s]
        LEFT JOIN [#CurrentSessions_SourceConnections] AS [c] ON [c].[session_id]=[s].[session_id]
        OUTER APPLY (SELECT TOP (1) [rr].* FROM [#CurrentSessions_SourceRequests] AS [rr] WHERE [rr].[session_id]=[s].[session_id] ORDER BY [rr].[request_id]) AS [r]
        LEFT JOIN [sys].[databases] AS [d] WITH (NOLOCK) ON [d].[database_id]=[r].[database_id]
        LEFT JOIN [#CurrentSessions_SourceSqlText] AS [t] ON [t].[SqlHandle]=CASE WHEN @MitSqlText=1 THEN COALESCE([r].[sql_handle],[c].[most_recent_sql_handle]) END
        OUTER APPLY [monitor].[TVF_StatementText]([t].[text],[r].[statement_start_offset],[r].[statement_end_offset]) AS [st]
        CROSS APPLY [monitor].[TVF_ToolBackgroundQueryInfo]([s].[program_name]) AS [tool]
        WHERE (NOT EXISTS(SELECT 1 FROM [#CurrentSessions_SessionIdFilter]) OR EXISTS(SELECT 1 FROM [#CurrentSessions_SessionIdFilter] AS [f] WHERE [f].[SessionId]=[s].[session_id]))
          AND (@AktuelleSessionEinbeziehen=1 OR [s].[session_id]<>@@SPID)
          AND (@SystemSessionsEinbeziehen=1 OR [s].[is_user_process]=1)
          AND (@ToolHintergrundabfragenEinbeziehen=1 OR [tool].[IsToolBackgroundQuery]=0)
          AND (@InaktiveSessionsEinbeziehen=1 OR [r].[session_id] IS NOT NULL OR [s].[open_transaction_count]>0)
          AND (@EigeneSessionsModus='ALLE' OR (@EigeneSessionsModus='NUR' AND [s].[original_login_name]=ORIGINAL_LOGIN()) OR (@EigeneSessionsModus='AUSSCHLIESSEN' AND ISNULL([s].[original_login_name],N'')<>ORIGINAL_LOGIN()))
          AND (NOT EXISTS(SELECT 1 FROM [#CurrentSessions_StringFilter] WHERE [FilterType]='LOGIN') OR EXISTS(SELECT 1 FROM [#CurrentSessions_StringFilter] AS [f] WHERE [f].[FilterType]='LOGIN' AND [f].[StringValue]=[s].[login_name] COLLATE SQL_Latin1_General_CP1_CS_AS))
          AND (NOT EXISTS(SELECT 1 FROM [#CurrentSessions_StringFilter] WHERE [FilterType]='HOST') OR EXISTS(SELECT 1 FROM [#CurrentSessions_StringFilter] AS [f] WHERE [f].[FilterType]='HOST' AND [f].[StringValue]=[s].[host_name] COLLATE SQL_Latin1_General_CP1_CS_AS))
          AND (NOT EXISTS(SELECT 1 FROM [#CurrentSessions_StringFilter] WHERE [FilterType]='PROGRAM') OR EXISTS(SELECT 1 FROM [#CurrentSessions_StringFilter] AS [f] WHERE [f].[FilterType]='PROGRAM' AND [f].[StringValue]=[s].[program_name] COLLATE SQL_Latin1_General_CP1_CS_AS))
          AND (NOT EXISTS(SELECT 1 FROM [#CurrentSessions_StringFilter] WHERE [FilterType]='DATABASE') OR EXISTS(SELECT 1 FROM [#CurrentSessions_StringFilter] AS [f] WHERE [f].[FilterType]='DATABASE' AND [f].[StringValue]=[d].[name] COLLATE SQL_Latin1_General_CP1_CS_AS))
          AND (@LoginMode<>'LIKE' OR [s].[login_name] COLLATE SQL_Latin1_General_CP1_CS_AS LIKE @LoginPattern COLLATE SQL_Latin1_General_CP1_CS_AS)
          AND (@HostMode<>'LIKE' OR [s].[host_name] COLLATE SQL_Latin1_General_CP1_CS_AS LIKE @HostPattern COLLATE SQL_Latin1_General_CP1_CS_AS)
          AND (@ProgramMode<>'LIKE' OR [s].[program_name] COLLATE SQL_Latin1_General_CP1_CS_AS LIKE @ProgramPattern COLLATE SQL_Latin1_General_CP1_CS_AS)
          AND (@DatabaseMode<>'LIKE' OR [d].[name] COLLATE SQL_Latin1_General_CP1_CS_AS LIKE @DatabasePattern COLLATE SQL_Latin1_General_CP1_CS_AS)
        ORDER BY CASE WHEN @Sortierung='CPU' THEN COALESCE([r].[cpu_time],[s].[cpu_time]) END DESC,
                 CASE WHEN @Sortierung='READS' THEN COALESCE([r].[logical_reads],[s].[logical_reads]) END DESC,
                 CASE WHEN @Sortierung='WRITES' THEN COALESCE([r].[writes],[s].[writes]) END DESC,
                 CASE WHEN @Sortierung='LOGIN' THEN DATEDIFF_BIG(SECOND,'20000101',[s].[login_time]) END DESC,
                 CASE WHEN @Sortierung='SESSION' THEN [s].[session_id] END,[s].[session_id];

        IF @HasRegex=1
        BEGIN
            DECLARE @Sql nvarchar(max)=N'';
            IF @LoginMode IN('REGEX','REGEXI') SET @Sql+=N'DELETE FROM [#CurrentSessions_Result] WHERE [LoginName] IS NULL OR NOT REGEXP_LIKE([LoginName],@LoginPattern,@LoginFlags);';
            IF @HostMode IN('REGEX','REGEXI') SET @Sql+=N'DELETE FROM [#CurrentSessions_Result] WHERE [HostName] IS NULL OR NOT REGEXP_LIKE([HostName],@HostPattern,@HostFlags);';
            IF @ProgramMode IN('REGEX','REGEXI') SET @Sql+=N'DELETE FROM [#CurrentSessions_Result] WHERE [ProgramName] IS NULL OR NOT REGEXP_LIKE([ProgramName],@ProgramPattern,@ProgramFlags);';
            IF @DatabaseMode IN('REGEX','REGEXI') SET @Sql+=N'DELETE FROM [#CurrentSessions_Result] WHERE [DatabaseName] IS NULL OR NOT REGEXP_LIKE([DatabaseName],@DatabasePattern,@DatabaseFlags);';
            EXEC [sys].[sp_executesql] @Sql,N'@LoginPattern nvarchar(4000),@LoginFlags varchar(8),@HostPattern nvarchar(4000),@HostFlags varchar(8),@ProgramPattern nvarchar(4000),@ProgramFlags varchar(8),@DatabasePattern nvarchar(4000),@DatabaseFlags varchar(8)',@LoginPattern,@LoginFlags,@HostPattern,@HostFlags,@ProgramPattern,@ProgramFlags,@DatabasePattern,@DatabaseFlags;
        END;

        IF @MaxZeilen IS NOT NULL AND @MaxZeilen>0
        BEGIN
            IF (SELECT COUNT_BIG(*) FROM [#CurrentSessions_Result])>@MaxZeilen SET @HasMoreRows=1;
            ;WITH [R] AS
            (
                SELECT [rn]=ROW_NUMBER() OVER(ORDER BY CASE WHEN @Sortierung='CPU' THEN COALESCE([RequestCpuMs],[SessionCpuMs]) END DESC,CASE WHEN @Sortierung='READS' THEN COALESCE([RequestLogicalReads],[SessionLogicalReads]) END DESC,CASE WHEN @Sortierung='WRITES' THEN COALESCE([RequestWrites],[SessionWrites]) END DESC,CASE WHEN @Sortierung='LOGIN' THEN DATEDIFF_BIG(SECOND,'20000101',[LoginTime]) END DESC,[SessionId]),*
                FROM [#CurrentSessions_Result]
            )
            DELETE FROM [R] WHERE [rn]>@MaxZeilen;
        END;

        DECLARE @TruncatedValueCount bigint=0,@LargestRequiredCharacters bigint=NULL;
        DECLARE @ColumnTruncatedCount bigint=0,@ColumnLargestCharacters bigint=NULL;
        EXEC [monitor].[InternalProjectUnicodeTextColumn]
              @SourceTable=N'#CurrentSessions_Result',@TextColumn=N'CurrentStatement'
            , @CharactersColumn=N'CurrentStatementCharacters',@BytesColumn=N'CurrentStatementBytes'
            , @IsTruncatedColumn=N'CurrentStatementIsTruncated',@MaxCharacters=@MaxSqlTextZeichen
            , @TruncatedValueCount=@ColumnTruncatedCount OUTPUT,@LargestRequiredCharacters=@ColumnLargestCharacters OUTPUT;
        SELECT @TruncatedValueCount=@TruncatedValueCount+@ColumnTruncatedCount,
               @LargestRequiredCharacters=CASE WHEN @LargestRequiredCharacters IS NULL OR @ColumnLargestCharacters>@LargestRequiredCharacters THEN @ColumnLargestCharacters ELSE @LargestRequiredCharacters END;
        EXEC [monitor].[InternalProjectUnicodeTextColumn]
              @SourceTable=N'#CurrentSessions_Result',@TextColumn=N'BatchText'
            , @CharactersColumn=N'BatchTextCharacters',@BytesColumn=N'BatchTextBytes'
            , @IsTruncatedColumn=N'BatchTextIsTruncated',@MaxCharacters=@MaxSqlTextZeichen
            , @TruncatedValueCount=@ColumnTruncatedCount OUTPUT,@LargestRequiredCharacters=@ColumnLargestCharacters OUTPUT;
        SELECT @TruncatedValueCount=@TruncatedValueCount+@ColumnTruncatedCount,
               @LargestRequiredCharacters=CASE WHEN @LargestRequiredCharacters IS NULL OR @ColumnLargestCharacters>@LargestRequiredCharacters THEN @ColumnLargestCharacters ELSE @LargestRequiredCharacters END;
        EXEC [monitor].[InternalEmitTruncationWarning]
              @TruncatedValueCount=@TruncatedValueCount,@ParameterName=N'@MaxSqlTextZeichen'
            , @ParameterValue=@MaxSqlTextZeichen,@LargestRequiredCharacters=@LargestRequiredCharacters
            , @PrintMeldungen=@PrintMeldungen;

        SELECT @RowCount=COUNT_BIG(*) FROM [#CurrentSessions_Result];
        IF @HasFullView=0 OR @ParentSnapshotIsPartial=1
        BEGIN
            SET @StatusCode='AVAILABLE_LIMITED';
            SET @IsPartial=1;
            SET @Detail=N'Mindestens eine Current-State-Quelle war nur eingeschränkt verfügbar.';
        END
        ELSE SET @Detail=N'Current-State-Sessions aus einer frischen laufinternen Evidenzbasis gelesen.';
    END TRY
    BEGIN CATCH
        SET @ErrorNumber=ERROR_NUMBER();SET @ErrorMessage=ERROR_MESSAGE();SET @IsPartial=1;
        SET @StatusCode=CASE WHEN @ErrorNumber IN(229,262,297,300,371,916) THEN 'DENIED_PERMISSION' WHEN @ErrorNumber=1222 THEN 'TIMEOUT' WHEN @ErrorNumber IN(207,208,4121) THEN 'UNAVAILABLE_OBJECT' ELSE 'ERROR_HANDLED' END;
    END CATCH;

    IF @PrintMeldungen=1 AND @StatusCode NOT IN('AVAILABLE')
    BEGIN
        SET @MonitorPrintMessage=FORMATMESSAGE(N'WARNUNG %s: %s',@StatusCode,COALESCE(@ErrorMessage,@Detail,N'eingeschränkte Sicht'));
        RAISERROR(N'%s',10,1,@MonitorPrintMessage) WITH NOWAIT;
    END;

    IF @JsonErzeugen=1
    BEGIN
        DECLARE @MetaJson nvarchar(max)=(SELECT @ModuleName AS [resultName], 3 AS [schemaVersion],@CollectionTimeUtc AS [generatedAtUtc],@EvidenceSnapshotStartedAtUtc AS [evidenceSnapshotStartedAtUtc],@ParentCurrentStateSnapshotId AS [evidenceSnapshotId],@StatusCode AS [statusCode],@IsPartial AS [isPartial],@ErrorNumber AS [errorNumber],@MaxZeilen AS [requestedMaxRows],@RowCount AS [returnedRows],@HasMoreRows AS [hasMoreRows],@ToolHintergrundabfragenEinbeziehen AS [toolBackgroundQueriesIncluded] FOR JSON PATH,WITHOUT_ARRAY_WRAPPER,INCLUDE_NULL_VALUES);
        DECLARE @SessionsJson nvarchar(max)=(SELECT [r].*,[wi].[WaitGroup] AS [waitGroup],[wi].[Severity] AS [waitSeverity],[wi].[Meaning] AS [waitMeaning] FROM [#CurrentSessions_Result] AS [r] CROSS APPLY [monitor].[TVF_WaitTypeInfo]([r].[WaitType]) AS [wi] ORDER BY [SessionId] FOR JSON PATH,INCLUDE_NULL_VALUES);
        SET @Json=CONCAT(N'{"meta":',COALESCE(@MetaJson,N'{}'),N',"sessions":',COALESCE(@SessionsJson,N'[]'),N',"warnings":',CASE WHEN @ErrorMessage IS NULL AND @Detail IS NULL THEN N'[]' ELSE (SELECT @StatusCode AS [code],COALESCE(@ErrorMessage,@Detail) AS [message] FOR JSON PATH,INCLUDE_NULL_VALUES) END,N'}');
    END;

    IF @ResultSetArtNormalisiert='RAW'
    BEGIN
        SELECT @ModuleName AS [ModuleName],@CollectionTimeUtc AS [CollectionTimeUtc],@EvidenceSnapshotStartedAtUtc AS [EvidenceSnapshotStartedAtUtc],@ParentCurrentStateSnapshotId AS [EvidenceSnapshotId],@StatusCode AS [StatusCode],@IsPartial AS [IsPartial],@RowCount AS [RowCount],@MaxZeilen AS [RequestedMaxRows],@HasMoreRows AS [HasMoreRows],@RequiredPermission AS [RequiredPermission],@ErrorNumber AS [ErrorNumber],@ErrorMessage AS [ErrorMessage],@Detail AS [Detail];
        SELECT [r].*,[wi].[WaitGroup],[wi].[Severity] AS [WaitSeverity],[wi].[IsGenerallyBenign],[wi].[Meaning] AS [WaitMeaning],[wi].[TypicalOccurrence] AS [WaitTypicalOccurrence],[wi].[HighWaitImpact],[wi].[RecommendedChecks],[wi].[HelpUrl] AS [WaitHelpUrl],[wi].[InterpretationScope],[wi].[CatalogMatchType]
        FROM [#CurrentSessions_Result] AS [r] CROSS APPLY [monitor].[TVF_WaitTypeInfo]([r].[WaitType]) AS [wi]
        ORDER BY CASE WHEN @Sortierung='CPU' THEN COALESCE([RequestCpuMs],[SessionCpuMs]) END DESC,CASE WHEN @Sortierung='READS' THEN COALESCE([RequestLogicalReads],[SessionLogicalReads]) END DESC,CASE WHEN @Sortierung='WRITES' THEN COALESCE([RequestWrites],[SessionWrites]) END DESC,CASE WHEN @Sortierung='LOGIN' THEN DATEDIFF_BIG(SECOND,'20000101',[LoginTime]) END DESC,[SessionId];
    END
    ELSE IF @ResultSetArtNormalisiert='CONSOLE'
    BEGIN
        SELECT N'Modulstatus' AS [Ergebnis],@ModuleName AS [Modul],@StatusCode AS [Status],CASE WHEN @IsPartial=1 THEN N'Ja' ELSE N'Nein' END AS [Teilergebnis],@RowCount AS [Zeilen],@Detail AS [Hinweis],@ErrorMessage AS [Fehler];
        SELECT N'Aktuelle Session' AS [Ergebnis],[SessionId] AS [Session],[RequestId] AS [Request],[LoginName] AS [Login],[HostName] AS [Host],[ProgramName] AS [Programm],[DatabaseName] AS [Datenbank],[SessionStatus] AS [Sessionstatus],[RequestStatus] AS [Requeststatus],CONCAT(CONVERT(decimal(19,2),COALESCE([RequestElapsedMs],0)/1000.0),N' s') AS [Laufzeit],COALESCE([RequestCpuMs],[SessionCpuMs]) AS [CPU_ms],COALESCE([RequestLogicalReads],[SessionLogicalReads]) AS [Logical_Reads],COALESCE([RequestWrites],[SessionWrites]) AS [Writes],[SessionId] AS [Session_Wait],[WaitType] AS [Wait],[WaitTimeMs] AS [Wait_ms],[BlockingSessionId] AS [Blockiert_durch],[CurrentStatement] AS [Aktuelles_Statement]
        FROM [#CurrentSessions_Result]
        ORDER BY CASE WHEN @Sortierung='CPU' THEN COALESCE([RequestCpuMs],[SessionCpuMs]) END DESC,CASE WHEN @Sortierung='READS' THEN COALESCE([RequestLogicalReads],[SessionLogicalReads]) END DESC,CASE WHEN @Sortierung='WRITES' THEN COALESCE([RequestWrites],[SessionWrites]) END DESC,[SessionId];
    END;
    IF @ConsoleResultRequested = 1
    BEGIN
        EXEC [monitor].[InternalEmitConsoleResult]
              @SourceTable=N'#CurrentSessions_Result'
            , @ResultLabel=N'Aktuelle Sessions'
            , @EmptyMessage=N'Keine aktiven Sessions';
    END;
    IF @TableResultRequested = 1
    BEGIN
        EXEC [monitor].[InternalWriteResultTable]
              @SourceTable = N'#CurrentSessions_Result'
            , @TargetTable=@TableTarget
            , @ThrowOnError = 1;
    END;
END;
GO
-- END SOURCE: Code/02_CurrentState/010_USP_CurrentSessions.sql

-- BEGIN SOURCE: Code/02_CurrentState/020_USP_CurrentRequests.sql
/*
===============================================================================
Objekt       : monitor.USP_CurrentRequests
Version      : 4.0.0
Stand        : 2026-07-23
Typ          : Stored Procedure
Zweck        : Liefert aktive Requests mit Session-, Wait-, Memory-Grant-,
               Modul- und exakt abgegrenztem SQL-Statement- sowie Ausführungs-
               und Verschachtelungskontext.
Filter       : Session-ID-Liste, exakte bracket-aware Textlisten und getrennte
               LIKE-/Regex-Patterns.
SQL-Text     : Das laufende Statement wird über statement_start_offset und
               statement_end_offset aus dem Batch beziehungsweise persistenten
               Modul extrahiert. Optional sind vollständiger Batch-/Modultext,
               Input Buffer und Modulauflösung verfügbar.
Ausgabe      : CONSOLE (Default), RAW, TABLE, NONE sowie optionales JSON-Envelope
               mit requests (Legacy), requestContext, snapshotStatus,
               statements, batches, inputBuffers und warnings.
===============================================================================
*/
CREATE OR ALTER PROCEDURE [monitor].[USP_CurrentRequests]
      @SessionIds                    nvarchar(max)  = NULL
    , @EigeneSessionsModus           varchar(16)    = 'ALLE'
    , @AktuelleSessionEinbeziehen    bit            = 0
    , @SystemSessionsEinbeziehen     bit            = 0
    , @ToolHintergrundabfragenEinbeziehen bit        = 0
    , @NurBlockierte                 bit            = 0
    , @NurMitWait                    bit            = 0
    , @MinLaufzeitSekunden           int            = NULL
    , @MinCpuMs                      bigint         = NULL
    , @MinLogicalReads               bigint         = NULL
    , @LoginNames                    nvarchar(max)  = NULL
    , @LoginNamePattern              nvarchar(4000) = NULL
    , @HostNames                     nvarchar(max)  = NULL
    , @HostNamePattern               nvarchar(4000) = NULL
    , @ProgramNames                  nvarchar(max)  = NULL
    , @ProgramNamePattern            nvarchar(4000) = NULL
    , @DatabaseNames                 nvarchar(max)  = NULL
    , @DatabaseNamePattern           nvarchar(4000) = NULL
    , @HighImpactConfirmed              bit            = 0
    , @TextPattern                   nvarchar(4000) = NULL
    , @MitSqlText                    bit            = 1
    , @GesamtenSqlTextEinbeziehen    bit            = 0
    , @InputBufferEinbeziehen        bit            = 0
    , @ModulInfoEinbeziehen          bit            = 1
    , @MaxSqlTextZeichen             int            = 4000
    , @MaxZeilen                     int            = 500
    , @Sortierung                    varchar(32)    = 'RELEVANZ'
    , @ResultSetArt                  varchar(16)    = 'CONSOLE'
    , @ResultTablesJson               nvarchar(max) = NULL
    , @JsonErzeugen                  bit            = 0
    , @Json                          nvarchar(max)  = NULL OUTPUT
    , @PrintMeldungen                bit            = 1
    , @Hilfe                         bit            = 0
    , @ParentCurrentStateSnapshotId  uniqueidentifier = NULL
AS
BEGIN
    SET NOCOUNT ON;
    SET LOCK_TIMEOUT 0;
    SET @Json = NULL;

    DECLARE @ModuleName sysname = N'USP_CurrentRequests';
    DECLARE @CollectionTimeUtc datetime2(3) = SYSUTCDATETIME();
    DECLARE @StatusCode varchar(40) = 'AVAILABLE';
    DECLARE @IsPartial bit = 0;
    DECLARE @RowCount bigint = 0;
    DECLARE @HasMoreRows bit = 0;
    DECLARE @ErrorNumber int = NULL;
    DECLARE @ErrorMessage nvarchar(2048) = NULL;
    DECLARE @Detail nvarchar(2000) = NULL;
    DECLARE @ResultSetArtNormalisiert varchar(16) = UPPER(LTRIM(RTRIM(COALESCE(@ResultSetArt, ''))));
    DECLARE @TableResultRequested bit = CASE WHEN @ResultSetArtNormalisiert = 'TABLE' THEN 1 ELSE 0 END;
    DECLARE @ConsoleResultRequested bit = CASE WHEN @ResultSetArtNormalisiert = 'CONSOLE' THEN 1 ELSE 0 END;
    IF @TableResultRequested=0 AND NULLIF(LTRIM(RTRIM(COALESCE(@ResultTablesJson,N''))),N'') IS NOT NULL THROW 51011,N'@ResultTablesJson ist ausschließlich mit @ResultSetArt=TABLE zulässig.',1;
    IF @TableResultRequested = 1 OR @ConsoleResultRequested = 1 SET @ResultSetArtNormalisiert = 'NONE';
    DECLARE @RequiredPermission nvarchar(256) =
        CASE
            WHEN TRY_CONVERT(int, SERVERPROPERTY(N'ProductMajorVersion')) >= 16
                THEN N'VIEW SERVER PERFORMANCE STATE'
            ELSE N'VIEW SERVER STATE'
        END;
    DECLARE @HasFullView bit =
        CASE
            WHEN IS_SRVROLEMEMBER(N'sysadmin') = 1 THEN 1
            WHEN TRY_CONVERT(int, SERVERPROPERTY(N'ProductMajorVersion')) >= 16
                THEN COALESCE(HAS_PERMS_BY_NAME(NULL, N'SERVER', N'VIEW SERVER PERFORMANCE STATE'), 0)
            ELSE COALESCE(HAS_PERMS_BY_NAME(NULL, N'SERVER', N'VIEW SERVER STATE'), 0)
        END;
    DECLARE @MonitorPrintMessage nvarchar(2048);
    DECLARE @CandidateMaxZeilen bigint;
    DECLARE @SqlTextErforderlich bit;
    DECLARE @StatementTextErforderlich bit;
    DECLARE @BatchTextErforderlich bit;
    DECLARE @EvidenceSnapshotStartedAtUtc datetime2(3)=@CollectionTimeUtc;
    DECLARE @EvidenceSnapshotId uniqueidentifier=COALESCE(@ParentCurrentStateSnapshotId,NEWID());
    DECLARE @ParentSnapshotIsPartial bit=0;

    SET @EigeneSessionsModus = UPPER(LTRIM(RTRIM(COALESCE(@EigeneSessionsModus, 'ALLE'))));
    SET @Sortierung = UPPER(LTRIM(RTRIM(COALESCE(@Sortierung, 'RELEVANZ'))));
    SET @StatementTextErforderlich =
        CASE WHEN @MitSqlText = 1 OR @TextPattern IS NOT NULL THEN 1 ELSE 0 END;
    SET @BatchTextErforderlich =
        CASE WHEN @GesamtenSqlTextEinbeziehen = 1 OR @TextPattern IS NOT NULL THEN 1 ELSE 0 END;
    SET @SqlTextErforderlich =
        CASE
            WHEN @StatementTextErforderlich = 1
              OR @BatchTextErforderlich = 1
              OR @ModulInfoEinbeziehen = 1
                THEN 1
            ELSE 0
        END;

    IF @Hilfe = 1
    BEGIN
        PRINT N'monitor.USP_CurrentRequests';
        PRINT N'@SessionIds: Pipe-Liste. Exakte Namenslisten und die zugehörigen ...Pattern sind gegenseitig exklusiv.';
        PRINT N'@ToolHintergrundabfragenEinbeziehen=0 blendet erkannte Object-Explorer-, Copilot- und SQL-Prompt-Hintergrundrequests standardmäßig aus; 1 zeigt sie samt Klassifikation.';
        PRINT N'Pattern: LIKE (Default/like:), regex: oder regexi:. @TextPattern prüft das aktuelle Statement und den vollständigen Batch-/Modultext.';
        PRINT N'@MitSqlText=1 gibt das exakt über die Request-Offsets ermittelte Statement aus.';
        PRINT N'@GesamtenSqlTextEinbeziehen=1 gibt zusätzlich den vollständigen Batch beziehungsweise persistenten Modultext aus.';
        PRINT N'@InputBufferEinbeziehen=1 ergänzt den ursprünglich an SQL Server übergebenen Befehl, z. B. EXEC/RPC-Aufruf.';
        PRINT N'@ModulInfoEinbeziehen=1 löst dbid/objectid über die Systemtabellen der jeweiligen Datenbank auf.';
        PRINT N'@MaxSqlTextZeichen: positiver Wert kürzt die Darstellung; NULL/0 gibt den jeweiligen Text vollständig aus.';
        PRINT N'@MaxZeilen: positiver Wert begrenzt; NULL/0 unbegrenzt. @ResultSetArt CONSOLE (Default), RAW, TABLE oder NONE; optional @Json OUTPUT.';
        PRINT N'TABLE-Namen: requests (Legacy), requestContext, snapshotStatus, statements, batches, inputBuffers und warnings.';
        PRINT N'@ParentCurrentStateSnapshotId ist ausschließlich für den laufinternen Overview-Consumer bestimmt; NULL erzwingt einen frischen Einzelread.';
        RETURN;
    END;

    CREATE TABLE [#CurrentRequests_ResultTableMap]
    (
          [ResultName] sysname COLLATE SQL_Latin1_General_CP1_CS_AS NOT NULL PRIMARY KEY
        , [TargetTable] sysname COLLATE SQL_Latin1_General_CP1_CS_AS NOT NULL UNIQUE
    );

    CREATE TABLE [#CurrentRequests_SessionIdFilter]
    (
        [SessionId] smallint NOT NULL PRIMARY KEY
    );

    CREATE TABLE [#CurrentRequests_StringFilter]
    (
          [FilterType] varchar(20) COLLATE SQL_Latin1_General_CP1_CS_AS NOT NULL
        , [StringValue] nvarchar(4000) COLLATE SQL_Latin1_General_CP1_CS_AS NOT NULL
        , PRIMARY KEY ([FilterType], [StringValue])
    );

    CREATE TABLE [#CurrentRequests_Warnings]
    (
          [WarningId] int IDENTITY(1,1) NOT NULL PRIMARY KEY
        , [SessionId] smallint NULL
        , [RequestId] int NULL
        , [DatabaseName] sysname NULL
        , [Code] varchar(40) NOT NULL
        , [Message] nvarchar(2048) NOT NULL
    );

    DECLARE @LoginMode varchar(8), @LoginPattern nvarchar(4000), @LoginFlags varchar(8), @LoginValid bit;
    DECLARE @HostMode varchar(8), @HostPattern nvarchar(4000), @HostFlags varchar(8), @HostValid bit;
    DECLARE @ProgramMode varchar(8), @ProgramPattern nvarchar(4000), @ProgramFlags varchar(8), @ProgramValid bit;
    DECLARE @DatabaseMode varchar(8), @DatabasePattern nvarchar(4000), @DatabaseFlags varchar(8), @DatabaseValid bit;
    DECLARE @TextMode varchar(8), @TextPatternValue nvarchar(4000), @TextFlags varchar(8), @TextValid bit;

    SELECT @LoginMode = [PatternMode], @LoginPattern = [PatternValue], @LoginFlags = [RegexFlags], @LoginValid = [IsValid]
    FROM [monitor].[TVF_ParsePattern](@LoginNamePattern);

    SELECT @HostMode = [PatternMode], @HostPattern = [PatternValue], @HostFlags = [RegexFlags], @HostValid = [IsValid]
    FROM [monitor].[TVF_ParsePattern](@HostNamePattern);

    SELECT @ProgramMode = [PatternMode], @ProgramPattern = [PatternValue], @ProgramFlags = [RegexFlags], @ProgramValid = [IsValid]
    FROM [monitor].[TVF_ParsePattern](@ProgramNamePattern);

    SELECT @DatabaseMode = [PatternMode], @DatabasePattern = [PatternValue], @DatabaseFlags = [RegexFlags], @DatabaseValid = [IsValid]
    FROM [monitor].[TVF_ParsePattern](@DatabaseNamePattern);

    SELECT @TextMode = [PatternMode], @TextPatternValue = [PatternValue], @TextFlags = [RegexFlags], @TextValid = [IsValid]
    FROM [monitor].[TVF_ParsePattern](@TextPattern);

    IF @SessionIds IS NOT NULL
    BEGIN
        IF EXISTS
        (
            SELECT 1
            FROM [monitor].[TVF_ParseBigintList](@SessionIds)
            WHERE [IsValid] = 0
               OR [NumberValue] NOT BETWEEN 1 AND 32767
        )
        BEGIN
            SET @StatusCode = 'INVALID_PARAMETER';
        END;
        ELSE
        BEGIN
            INSERT [#CurrentRequests_SessionIdFilter] ([SessionId])
            SELECT CONVERT(smallint, [NumberValue])
            FROM [monitor].[TVF_ParseBigintList](@SessionIds)
            GROUP BY [NumberValue];
        END;
    END;

    IF @StatusCode = 'AVAILABLE'
       AND
       (
              (@LoginNames IS NOT NULL AND @LoginNamePattern IS NOT NULL)
           OR (@HostNames IS NOT NULL AND @HostNamePattern IS NOT NULL)
           OR (@ProgramNames IS NOT NULL AND @ProgramNamePattern IS NOT NULL)
           OR (@DatabaseNames IS NOT NULL AND @DatabaseNamePattern IS NOT NULL)
           OR @LoginValid = 0
           OR @HostValid = 0
           OR @ProgramValid = 0
           OR @DatabaseValid = 0
           OR @TextValid = 0
       )
    BEGIN
        SET @StatusCode = 'INVALID_PARAMETER';
    END;

    IF @StatusCode = 'AVAILABLE'
       AND
       (
              (@LoginNames IS NOT NULL AND EXISTS
               (SELECT 1 FROM [monitor].[TVF_ParseStringList](@LoginNames) WHERE [IsValid] = 0 OR LEN([StringValue]) > 128))
           OR (@HostNames IS NOT NULL AND EXISTS
               (SELECT 1 FROM [monitor].[TVF_ParseStringList](@HostNames) WHERE [IsValid] = 0 OR LEN([StringValue]) > 128))
           OR (@ProgramNames IS NOT NULL AND EXISTS
               (SELECT 1 FROM [monitor].[TVF_ParseStringList](@ProgramNames) WHERE [IsValid] = 0 OR LEN([StringValue]) > 128))
           OR (@DatabaseNames IS NOT NULL AND EXISTS
               (SELECT 1 FROM [monitor].[TVF_ParseSqlNameList](@DatabaseNames) WHERE [IsValid] = 0))
       )
    BEGIN
        SET @StatusCode = 'INVALID_PARAMETER';
    END;

    IF @StatusCode = 'AVAILABLE'
    BEGIN
        INSERT [#CurrentRequests_StringFilter] ([FilterType], [StringValue])
        SELECT 'LOGIN', [StringValue]
        FROM [monitor].[TVF_ParseStringList](@LoginNames)
        WHERE [IsValid] = 1
        GROUP BY [StringValue];

        INSERT [#CurrentRequests_StringFilter] ([FilterType], [StringValue])
        SELECT 'HOST', [StringValue]
        FROM [monitor].[TVF_ParseStringList](@HostNames)
        WHERE [IsValid] = 1
        GROUP BY [StringValue];

        INSERT [#CurrentRequests_StringFilter] ([FilterType], [StringValue])
        SELECT 'PROGRAM', [StringValue]
        FROM [monitor].[TVF_ParseStringList](@ProgramNames)
        WHERE [IsValid] = 1
        GROUP BY [StringValue];

        INSERT [#CurrentRequests_StringFilter] ([FilterType], [StringValue])
        SELECT 'DATABASE', [NameValue]
        FROM [monitor].[TVF_ParseSqlNameList](@DatabaseNames)
        WHERE [IsValid] = 1
        GROUP BY [NameValue];
    END;

    DECLARE @HasRegex bit =
        CASE
            WHEN @LoginMode IN ('REGEX', 'REGEXI')
              OR @HostMode IN ('REGEX', 'REGEXI')
              OR @ProgramMode IN ('REGEX', 'REGEXI')
              OR @DatabaseMode IN ('REGEX', 'REGEXI')
              OR @TextMode IN ('REGEX', 'REGEXI')
                THEN 1
            ELSE 0
        END;

    IF @StatusCode = 'AVAILABLE'
       AND @HasRegex = 1
       AND
       (
           TRY_CONVERT(int, SERVERPROPERTY(N'ProductMajorVersion')) < 17
           OR
           (
               SELECT [compatibility_level]
               FROM [master].[sys].[databases] WITH (NOLOCK)
               WHERE [database_id] = DB_ID()
           ) < 170
       )
    BEGIN
        SET @StatusCode = 'UNAVAILABLE_FEATURE';
        SET @ErrorMessage = N'Regex benötigt SQL Server 2025 und Compatibility Level 170.';
    END;

    IF @StatusCode = 'AVAILABLE'
       AND
       (
              @EigeneSessionsModus NOT IN ('ALLE', 'NUR', 'AUSSCHLIESSEN')
           OR @Sortierung NOT IN ('RELEVANZ', 'CPU', 'READS', 'DAUER', 'SESSION')
           OR @ResultSetArtNormalisiert NOT IN ('RAW', 'CONSOLE', 'NONE')
           OR @MaxZeilen < 0
           OR @MaxSqlTextZeichen < 0
           OR COALESCE(@MinLaufzeitSekunden, 0) < 0
           OR COALESCE(@MinCpuMs, 0) < 0
           OR COALESCE(@MinLogicalReads, 0) < 0
           OR @MitSqlText IS NULL OR @MitSqlText NOT IN (0, 1)
           OR @GesamtenSqlTextEinbeziehen IS NULL OR @GesamtenSqlTextEinbeziehen NOT IN (0, 1)
           OR @InputBufferEinbeziehen IS NULL OR @InputBufferEinbeziehen NOT IN (0, 1)
           OR @ModulInfoEinbeziehen IS NULL OR @ModulInfoEinbeziehen NOT IN (0, 1)
           OR @ToolHintergrundabfragenEinbeziehen IS NULL OR @ToolHintergrundabfragenEinbeziehen NOT IN (0, 1)
           OR @JsonErzeugen IS NULL OR @JsonErzeugen NOT IN (0, 1)
       )
    BEGIN
        SET @StatusCode = 'INVALID_PARAMETER';
    END;

    IF @StatusCode = 'INVALID_PARAMETER'
    BEGIN
        SET @ErrorMessage = COALESCE(@ErrorMessage, N'Ungültige Liste, Kombination, Pattern- oder Steuerangabe.');
    END;

    IF @StatusCode='AVAILABLE' AND @TableResultRequested=1
    BEGIN
        EXEC [monitor].[InternalPrepareResultTables]
              @ResultTablesJson=@ResultTablesJson
            , @AllowedResultNames=N'requests|requestContext|snapshotStatus|statements|batches|inputBuffers|warnings'
            , @MappingTable=N'#CurrentRequests_ResultTableMap'
            , @StatusCode=@StatusCode OUTPUT
            , @ErrorMessage=@ErrorMessage OUTPUT
            , @ThrowOnError=1;
    END;

    CREATE TABLE [#CurrentRequests_Result]
    (
          [SessionId] smallint NOT NULL
        , [RequestId] int NOT NULL
        , [RequestStatus] nvarchar(30) NULL
        , [Command] nvarchar(32) NULL
        , [DatabaseId] smallint NULL
        , [DatabaseName] sysname NULL
        , [LoginName] nvarchar(128) NULL
        , [OriginalLoginName] nvarchar(128) NULL
        , [HostName] nvarchar(128) NULL
        , [ProgramName] nvarchar(128) NULL
        , [IsToolBackgroundQuery] bit NOT NULL
        , [ToolBackgroundRuleCode] varchar(64) NULL
        , [ToolBackgroundCategory] varchar(40) NULL
        , [ToolBackgroundDetection] varchar(40) NULL
        , [ToolBackgroundConfidence] varchar(16) NULL
        , [StartTime] datetime NULL
        , [ElapsedMs] int NULL
        , [CpuMs] int NULL
        , [LogicalReads] bigint NULL
        , [Reads] bigint NULL
        , [Writes] bigint NULL
        , [RowCount] bigint NULL
        , [PercentComplete] real NULL
        , [EstimatedCompletionTimeMs] bigint NULL
        , [BlockingSessionId] smallint NULL
        , [WaitType] nvarchar(120) NULL
        , [WaitTimeMs] int NULL
        , [LastWaitType] nvarchar(120) NULL
        , [WaitResource] nvarchar(256) NULL
        , [WaitingTaskCount] int NULL
        , [MaxTaskWaitMs] bigint NULL
        , [TaskWaitTypes] nvarchar(max) NULL
        , [RequestedMemoryMb] decimal(19,2) NULL
        , [GrantedMemoryMb] decimal(19,2) NULL
        , [UsedMemoryMb] decimal(19,2) NULL
        , [IdealMemoryMb] decimal(19,2) NULL
        , [Dop] smallint NULL
        , [ParallelWorkerCount] int NULL
        , [TransactionIsolationLevel] nvarchar(40) NULL
        , [OpenTransactionCount] int NULL
        , [OpenResultsetCount] int NULL
        , [TransactionId] bigint NULL
        , [ConnectionId] uniqueidentifier NULL
        , [SchedulerId] int NULL
        , [TaskAddress] varbinary(8) NULL
        , [NestLevel] int NULL
        , [WorkloadGroupId] int NULL
        , [WorkloadGroupName] sysname NULL
        , [ResourcePoolId] int NULL
        , [ResourcePoolName] sysname NULL
        , [StatementSqlHandle] varbinary(64) NULL
        , [StatementContextId] bigint NULL
        , [IsResumable] bit NULL
        , [ExecutingManagedCode] bit NULL
        , [ContextInfo] varbinary(128) NULL
        , [ClientNetAddress] varchar(48) NULL
        , [QueryHash] binary(8) NULL
        , [QueryPlanHash] binary(8) NULL
        , [SqlHandle] varbinary(64) NULL
        , [PlanHandle] varbinary(64) NULL
        , [SqlTextDatabaseId] int NULL
        , [SqlTextObjectId] int NULL
        , [SqlTextObjectNumber] smallint NULL
        , [SqlTextIsEncrypted] bit NULL
        , [ExecutionContextType] varchar(20) NULL
        , [ModuleDatabaseName] sysname NULL
        , [ModuleSchemaName] sysname NULL
        , [ModuleObjectName] sysname NULL
        , [ModuleType] char(2) NULL
        , [ModuleTypeDescription] nvarchar(60) NULL
        , [ModuleFullName] nvarchar(776) NULL
        , [HasStatementOffsets] bit NULL
        , [IsStatementOffsetValid] bit NULL
        , [StatementStartOffsetBytes] int NULL
        , [StatementEndOffsetBytes] int NULL
        , [StatementStartCharacter] int NULL
        , [StatementEndCharacter] int NULL
        , [StatementStartLine] int NULL
        , [StatementEndLine] int NULL
        , [CurrentStatementCharacterCount] bigint NULL
        , [CurrentStatementBytes] bigint NULL
        , [CurrentStatementIsTruncated] bit NULL
        , [BatchTextCharacterCount] bigint NULL
        , [BatchTextBytes] bigint NULL
        , [BatchTextIsTruncated] bit NULL
        , [CurrentStatement] nvarchar(max) NULL
        , [BatchText] nvarchar(max) NULL
        , [InputBufferEventType] nvarchar(256) NULL
        , [InputBufferParameterCount] smallint NULL
        , [InputBufferCharacterCount] bigint NULL
        , [InputBufferBytes] bigint NULL
        , [InputBufferIsTruncated] bit NULL
        , [InputBufferText] nvarchar(max) NULL
        , PRIMARY KEY ([SessionId], [RequestId])
    );

    CREATE TABLE [#CurrentRequests_SnapshotStatus]
    (
          [SourceOrdinal] int NOT NULL
        , [SnapshotId] uniqueidentifier NOT NULL
        , [SourceCode] varchar(40) NOT NULL
        , [SourceObject] nvarchar(256) NOT NULL
        , [CapturedAtUtc] datetime2(3) NOT NULL
        , [CompletedAtUtc] datetime2(3) NOT NULL
        , [StatusCode] varchar(40) NOT NULL
        , [IsPartial] bit NOT NULL
        , [CapturedRowCount] bigint NOT NULL
        , [ErrorNumber] int NULL
        , [ErrorMessage] nvarchar(2048) NULL
        , PRIMARY KEY ([SourceCode])
    );

    CREATE TABLE [#CurrentRequests_SourceSessions]
    (
          [session_id] smallint NOT NULL PRIMARY KEY
        , [is_user_process] bit NOT NULL
        , [login_name] nvarchar(128) NOT NULL
        , [original_login_name] nvarchar(128) NOT NULL
        , [host_name] nvarchar(128) NULL
        , [program_name] nvarchar(128) NULL
    );
    CREATE TABLE [#CurrentRequests_SourceRequests]
    (
          [session_id] smallint NOT NULL
        , [request_id] int NOT NULL
        , [status] nvarchar(30) NOT NULL
        , [command] nvarchar(32) NOT NULL
        , [database_id] smallint NOT NULL
        , [start_time] datetime NOT NULL
        , [total_elapsed_time] int NOT NULL
        , [cpu_time] int NOT NULL
        , [logical_reads] bigint NOT NULL
        , [reads] bigint NOT NULL
        , [writes] bigint NOT NULL
        , [row_count] bigint NOT NULL
        , [percent_complete] real NOT NULL
        , [estimated_completion_time] bigint NOT NULL
        , [blocking_session_id] smallint NULL
        , [wait_type] nvarchar(60) NULL
        , [wait_time] int NOT NULL
        , [last_wait_type] nvarchar(60) NOT NULL
        , [wait_resource] nvarchar(256) NOT NULL
        , [dop] int NOT NULL
        , [parallel_worker_count] int NULL
        , [transaction_isolation_level] smallint NOT NULL
        , [open_transaction_count] int NOT NULL
        , [open_resultset_count] int NOT NULL
        , [transaction_id] bigint NOT NULL
        , [scheduler_id] int NULL
        , [task_address] varbinary(8) NULL
        , [nest_level] int NOT NULL
        , [group_id] int NOT NULL
        , [statement_sql_handle] varbinary(64) NULL
        , [statement_context_id] bigint NULL
        , [is_resumable] bit NOT NULL
        , [executing_managed_code] bit NOT NULL
        , [context_info] varbinary(128) NULL
        , [query_hash] binary(8) NULL
        , [query_plan_hash] binary(8) NULL
        , [sql_handle] varbinary(64) NULL
        , [plan_handle] varbinary(64) NULL
        , [statement_start_offset] int NULL
        , [statement_end_offset] int NULL
        , PRIMARY KEY ([session_id],[request_id])
    );
    CREATE TABLE [#CurrentRequests_SourceConnections]
    (
          [session_id] int NULL
        , [connection_id] uniqueidentifier NOT NULL PRIMARY KEY
        , [client_net_address] varchar(48) NULL
        , [net_transport] nvarchar(40) NOT NULL
        , [protocol_type] nvarchar(40) NULL
        , [encrypt_option] nvarchar(40) NOT NULL
        , [auth_scheme] nvarchar(40) NOT NULL
    );
    CREATE INDEX [IX_CurrentRequests_SourceConnections_SessionId]
        ON [#CurrentRequests_SourceConnections]([session_id]);
    CREATE TABLE [#CurrentRequests_SourceWaitingTasks]
    (
          [waiting_task_address] varbinary(8) NOT NULL
        , [session_id] smallint NULL
        , [exec_context_id] int NULL
        , [wait_duration_ms] bigint NOT NULL
        , [wait_type] nvarchar(60) NOT NULL
        , [blocking_session_id] smallint NULL
        , [resource_description] nvarchar(3072) NULL
    );
    CREATE INDEX [IX_CurrentRequests_SourceWaitingTasks_SessionId]
        ON [#CurrentRequests_SourceWaitingTasks]([session_id]);
    CREATE TABLE [#CurrentRequests_SourceMemoryGrants]
    (
          [session_id] smallint NOT NULL
        , [request_id] int NOT NULL
        , [requested_memory_kb] bigint NOT NULL
        , [granted_memory_kb] bigint NULL
        , [used_memory_kb] bigint NULL
        , [ideal_memory_kb] bigint NULL
    );
    CREATE INDEX [IX_CurrentRequests_SourceMemoryGrants_Request]
        ON [#CurrentRequests_SourceMemoryGrants]([session_id],[request_id]);
    CREATE TABLE [#CurrentRequests_SourceTasks]
    (
          [task_address] varbinary(8) NOT NULL PRIMARY KEY
        , [task_state] nvarchar(60) NOT NULL
        , [session_id] smallint NULL
        , [request_id] int NULL
        , [exec_context_id] int NULL
        , [scheduler_id] int NULL
        , [worker_address] varbinary(8) NULL
    );
    CREATE INDEX [IX_CurrentRequests_SourceTasks_Request]
        ON [#CurrentRequests_SourceTasks]([session_id],[request_id]);
    CREATE TABLE [#CurrentRequests_SourceSchedulers]
    (
          [scheduler_id] int NOT NULL PRIMARY KEY
        , [scheduler_address] varbinary(8) NOT NULL
        , [parent_node_id] int NOT NULL
        , [status] nvarchar(60) NOT NULL
        , [is_online] bit NOT NULL
        , [is_idle] bit NOT NULL
        , [current_tasks_count] int NOT NULL
        , [runnable_tasks_count] int NOT NULL
        , [current_workers_count] int NOT NULL
        , [active_workers_count] int NOT NULL
        , [work_queue_count] bigint NOT NULL
        , [pending_disk_io_count] int NOT NULL
        , [load_factor] int NOT NULL
    );
    CREATE TABLE [#CurrentRequests_SourceSessionTransactions]
    (
          [session_id] int NOT NULL
        , [transaction_id] bigint NOT NULL
        , [is_user_transaction] bit NOT NULL
        , [is_local] bit NOT NULL
        , [is_enlisted] bit NOT NULL
        , [is_bound] bit NOT NULL
        , [open_transaction_count] int NOT NULL
        , PRIMARY KEY ([session_id],[transaction_id])
    );
    CREATE TABLE [#CurrentRequests_SourceActiveTransactions]
    (
          [transaction_id] bigint NOT NULL PRIMARY KEY
        , [transaction_begin_time] datetime NOT NULL
        , [transaction_type] int NOT NULL
        , [transaction_state] int NOT NULL
    );
    CREATE TABLE [#CurrentRequests_SourceDatabaseTransactions]
    (
          [transaction_id] bigint NOT NULL
        , [database_id] int NOT NULL
        , [database_transaction_log_bytes_used] bigint NOT NULL
        , [database_transaction_log_bytes_reserved] bigint NOT NULL
    );
    CREATE INDEX [IX_CurrentRequests_SourceDatabaseTransactions]
        ON [#CurrentRequests_SourceDatabaseTransactions]([transaction_id],[database_id]);
    CREATE TABLE [#CurrentRequests_SourceTempDbSessionUsage]
    (
          [session_id] smallint NOT NULL PRIMARY KEY
        , [user_objects_alloc_page_count] bigint NOT NULL
        , [user_objects_dealloc_page_count] bigint NOT NULL
        , [internal_objects_alloc_page_count] bigint NOT NULL
        , [internal_objects_dealloc_page_count] bigint NOT NULL
    );
    CREATE TABLE [#CurrentRequests_SourceTempDbTaskUsage]
    (
          [session_id] smallint NOT NULL
        , [request_id] int NOT NULL
        , [exec_context_id] int NOT NULL
        , [user_objects_alloc_page_count] bigint NOT NULL
        , [user_objects_dealloc_page_count] bigint NOT NULL
        , [internal_objects_alloc_page_count] bigint NOT NULL
        , [internal_objects_dealloc_page_count] bigint NOT NULL
    );
    CREATE INDEX [IX_CurrentRequests_SourceTempDbTaskUsage]
        ON [#CurrentRequests_SourceTempDbTaskUsage]([session_id],[request_id]);
    CREATE TABLE [#CurrentRequests_SourceWorkloadGroups]
    (
          [group_id] int NOT NULL PRIMARY KEY
        , [name] sysname NOT NULL
        , [pool_id] int NOT NULL
    );
    CREATE TABLE [#CurrentRequests_SourceResourcePools]
    (
          [pool_id] int NOT NULL PRIMARY KEY
        , [name] sysname NOT NULL
    );
    CREATE TABLE [#CurrentRequests_SourceSqlText]
    (
          [SqlHandle] varbinary(64) NOT NULL PRIMARY KEY
        , [text] nvarchar(max) NULL
        , [dbid] int NULL
        , [objectid] int NULL
        , [number] smallint NULL
        , [encrypted] bit NULL
    );
    CREATE TABLE [#CurrentRequests_SourceInputBuffer]
    (
          [session_id] smallint NOT NULL
        , [request_id] int NOT NULL
        , [event_type] nvarchar(256) NULL
        , [parameters] smallint NULL
        , [event_info] nvarchar(max) NULL
        , PRIMARY KEY ([session_id],[request_id])
    );
    CREATE TABLE [#CurrentRequests_RequestContext]
    (
          [SnapshotId] uniqueidentifier NOT NULL
        , [CapturedAtUtc] datetime2(3) NOT NULL
        , [SessionId] smallint NOT NULL
        , [RequestId] int NOT NULL
        , [RequestStatus] nvarchar(30) NULL
        , [Command] nvarchar(32) NULL
        , [DatabaseId] smallint NULL
        , [DatabaseName] sysname NULL
        , [StartTime] datetime NULL
        , [ElapsedMs] int NULL
        , [CpuMs] int NULL
        , [LogicalReads] bigint NULL
        , [Reads] bigint NULL
        , [Writes] bigint NULL
        , [RowCount] bigint NULL
        , [PercentComplete] real NULL
        , [EstimatedCompletionTimeMs] bigint NULL
        , [BlockingSessionId] smallint NULL
        , [WaitType] nvarchar(120) NULL
        , [WaitTimeMs] bigint NULL
        , [WaitResource] nvarchar(3072) NULL
        , [ConnectionId] uniqueidentifier NULL
        , [ClientNetAddress] varchar(48) NULL
        , [NetTransport] nvarchar(40) NULL
        , [ProtocolType] nvarchar(40) NULL
        , [EncryptOption] nvarchar(40) NULL
        , [AuthScheme] nvarchar(40) NULL
        , [TaskCount] int NULL
        , [WorkerCount] int NULL
        , [ExecutionContextCount] int NULL
        , [RunnableTaskCount] int NULL
        , [SuspendedTaskCount] int NULL
        , [SchedulerId] int NULL
        , [SchedulerStatus] nvarchar(60) NULL
        , [SchedulerParentNodeId] int NULL
        , [SchedulerRunnableTaskCount] int NULL
        , [SchedulerWorkQueueCount] bigint NULL
        , [SchedulerPendingDiskIoCount] int NULL
        , [SchedulerLoadFactor] int NULL
        , [TransactionId] bigint NULL
        , [TransactionBeginTime] datetime NULL
        , [TransactionAgeSeconds] bigint NULL
        , [TransactionType] int NULL
        , [TransactionState] int NULL
        , [IsUserTransaction] bit NULL
        , [IsLocalTransaction] bit NULL
        , [IsEnlistedTransaction] bit NULL
        , [IsBoundTransaction] bit NULL
        , [TransactionLogBytesUsed] bigint NULL
        , [TransactionLogBytesReserved] bigint NULL
        , [RequestedMemoryMb] decimal(19,2) NULL
        , [GrantedMemoryMb] decimal(19,2) NULL
        , [UsedMemoryMb] decimal(19,2) NULL
        , [IdealMemoryMb] decimal(19,2) NULL
        , [TempDbSessionNetMb] decimal(19,2) NULL
        , [TempDbRequestNetMb] decimal(19,2) NULL
        , [Dop] smallint NULL
        , [ParallelWorkerCount] int NULL
        , [WorkloadGroupId] int NULL
        , [WorkloadGroupName] sysname NULL
        , [ResourcePoolId] int NULL
        , [ResourcePoolName] sysname NULL
        , [QueryHash] binary(8) NULL
        , [QueryPlanHash] binary(8) NULL
        , [SqlHandle] varbinary(64) NULL
        , [PlanHandle] varbinary(64) NULL
        , [StatementSqlHandle] varbinary(64) NULL
        , [StatementContextId] bigint NULL
        , [ModuleFullName] nvarchar(776) NULL
        , [IsCurrent] bit NOT NULL
        , [StatusCode] varchar(40) NOT NULL
        , [IsPartial] bit NOT NULL
        , [EvidenceBoundary] nvarchar(512) NULL
        , PRIMARY KEY ([SessionId],[RequestId])
    );
    CREATE TABLE [#CurrentRequests_Statements]
    (
          [SnapshotId] uniqueidentifier NOT NULL
        , [SessionId] smallint NOT NULL
        , [RequestId] int NOT NULL
        , [SourceCode] varchar(40) NOT NULL
        , [CapturedAtUtc] datetime2(3) NOT NULL
        , [HasStatementOffsets] bit NULL
        , [IsStatementOffsetValid] bit NULL
        , [StartOffsetBytes] int NULL
        , [EndOffsetBytes] int NULL
        , [StartCharacter] int NULL
        , [EndCharacter] int NULL
        , [StartLine] int NULL
        , [EndLine] int NULL
        , [CharacterCount] bigint NULL
        , [Bytes] bigint NULL
        , [IsTruncated] bit NOT NULL
        , [StatusCode] varchar(40) NOT NULL
        , [OmissionReason] nvarchar(512) NULL
        , [Text] nvarchar(max) NULL
        , PRIMARY KEY ([SessionId],[RequestId])
    );
    CREATE TABLE [#CurrentRequests_Batches]
    (
          [SnapshotId] uniqueidentifier NOT NULL
        , [SessionId] smallint NOT NULL
        , [RequestId] int NOT NULL
        , [SourceCode] varchar(40) NOT NULL
        , [CapturedAtUtc] datetime2(3) NOT NULL
        , [SqlTextDatabaseId] int NULL
        , [SqlTextObjectId] int NULL
        , [SqlTextObjectNumber] smallint NULL
        , [IsEncrypted] bit NULL
        , [CharacterCount] bigint NULL
        , [Bytes] bigint NULL
        , [IsTruncated] bit NOT NULL
        , [StatusCode] varchar(40) NOT NULL
        , [OmissionReason] nvarchar(512) NULL
        , [Text] nvarchar(max) NULL
        , PRIMARY KEY ([SessionId],[RequestId])
    );
    CREATE TABLE [#CurrentRequests_InputBuffers]
    (
          [SnapshotId] uniqueidentifier NOT NULL
        , [SessionId] smallint NOT NULL
        , [RequestId] int NOT NULL
        , [SourceCode] varchar(40) NOT NULL
        , [CapturedAtUtc] datetime2(3) NOT NULL
        , [EventType] nvarchar(256) NULL
        , [ParameterCount] smallint NULL
        , [CharacterCount] bigint NULL
        , [Bytes] bigint NULL
        , [IsTruncated] bit NOT NULL
        , [StatusCode] varchar(40) NOT NULL
        , [OmissionReason] nvarchar(512) NULL
        , [Text] nvarchar(max) NULL
        , PRIMARY KEY ([SessionId],[RequestId])
    );

    IF @StatusCode='AVAILABLE' AND @ParentCurrentStateSnapshotId IS NOT NULL
    BEGIN
        BEGIN TRY
            EXEC [sys].[sp_executesql] N'
                DECLARE @Probe int;
                SELECT @Probe=0 FROM [#CurrentOverview_CurrentStateSnapshot_Context] WHERE 1=0;
                SELECT @Probe=0 FROM [#CurrentOverview_CurrentStateSnapshot_SourceStatus] WHERE 1=0;
                SELECT @Probe=0 FROM [#CurrentOverview_CurrentStateSnapshot_Sessions] WHERE 1=0;
                SELECT @Probe=0 FROM [#CurrentOverview_CurrentStateSnapshot_Requests] WHERE 1=0;
                SELECT @Probe=0 FROM [#CurrentOverview_CurrentStateSnapshot_Connections] WHERE 1=0;
                SELECT @Probe=0 FROM [#CurrentOverview_CurrentStateSnapshot_WaitingTasks] WHERE 1=0;
                SELECT @Probe=0 FROM [#CurrentOverview_CurrentStateSnapshot_MemoryGrants] WHERE 1=0;
                SELECT @Probe=0 FROM [#CurrentOverview_CurrentStateSnapshot_Tasks] WHERE 1=0;
                SELECT @Probe=0 FROM [#CurrentOverview_CurrentStateSnapshot_Schedulers] WHERE 1=0;
                SELECT @Probe=0 FROM [#CurrentOverview_CurrentStateSnapshot_SessionTransactions] WHERE 1=0;
                SELECT @Probe=0 FROM [#CurrentOverview_CurrentStateSnapshot_ActiveTransactions] WHERE 1=0;
                SELECT @Probe=0 FROM [#CurrentOverview_CurrentStateSnapshot_DatabaseTransactions] WHERE 1=0;
                SELECT @Probe=0 FROM [#CurrentOverview_CurrentStateSnapshot_TempDbSessionUsage] WHERE 1=0;
                SELECT @Probe=0 FROM [#CurrentOverview_CurrentStateSnapshot_TempDbTaskUsage] WHERE 1=0;
                SELECT @Probe=0 FROM [#CurrentOverview_CurrentStateSnapshot_WorkloadGroups] WHERE 1=0;
                SELECT @Probe=0 FROM [#CurrentOverview_CurrentStateSnapshot_ResourcePools] WHERE 1=0;
                SELECT @Probe=0 FROM [#CurrentOverview_CurrentStateSnapshot_SqlText] WHERE 1=0;';

            IF NOT EXISTS
            (
                SELECT 1
                FROM [#CurrentOverview_CurrentStateSnapshot_Context]
                WHERE [SnapshotId]=@ParentCurrentStateSnapshotId
                  AND [OwnerSessionId]=CONVERT(smallint,@@SPID)
                  AND [ContractVersion]=2
            )
            BEGIN
                SET @StatusCode='INVALID_PARENT_SNAPSHOT';
                SET @IsPartial=1;
                SET @ErrorMessage=N'Die Parent-Snapshot-ID gehört nicht zum aktuellen Aufruf.';
            END
            ELSE
            BEGIN
                INSERT [#CurrentRequests_SourceSessions]
                SELECT [session_id],[is_user_process],[login_name],[original_login_name],[host_name],[program_name]
                FROM [#CurrentOverview_CurrentStateSnapshot_Sessions]
                WHERE [SnapshotId]=@ParentCurrentStateSnapshotId;

                INSERT [#CurrentRequests_SourceRequests]
                SELECT
                      [session_id],[request_id],[status],[command],[database_id],[start_time]
                    , [total_elapsed_time],[cpu_time],[logical_reads],[reads],[writes],[row_count]
                    , [percent_complete],[estimated_completion_time],[blocking_session_id]
                    , [wait_type],[wait_time],[last_wait_type],[wait_resource],[dop]
                    , [parallel_worker_count],[transaction_isolation_level]
                    , [open_transaction_count],[open_resultset_count],[transaction_id]
                    , [scheduler_id],[task_address],[nest_level],[group_id]
                    , [statement_sql_handle],[statement_context_id],[is_resumable]
                    , [executing_managed_code],[context_info],[query_hash],[query_plan_hash]
                    , [sql_handle],[plan_handle],[statement_start_offset],[statement_end_offset]
                FROM [#CurrentOverview_CurrentStateSnapshot_Requests]
                WHERE [SnapshotId]=@ParentCurrentStateSnapshotId;

                INSERT [#CurrentRequests_SourceConnections]
                SELECT
                      [session_id],[connection_id],[client_net_address]
                    , [net_transport],[protocol_type],[encrypt_option],[auth_scheme]
                FROM [#CurrentOverview_CurrentStateSnapshot_Connections]
                WHERE [SnapshotId]=@ParentCurrentStateSnapshotId;

                INSERT [#CurrentRequests_SourceWaitingTasks]
                SELECT
                      [waiting_task_address],[session_id],[exec_context_id]
                    , [wait_duration_ms],[wait_type],[blocking_session_id],[resource_description]
                FROM [#CurrentOverview_CurrentStateSnapshot_WaitingTasks]
                WHERE [SnapshotId]=@ParentCurrentStateSnapshotId;

                INSERT [#CurrentRequests_SourceMemoryGrants]
                SELECT [session_id],[request_id],[requested_memory_kb],[granted_memory_kb],[used_memory_kb],[ideal_memory_kb]
                FROM [#CurrentOverview_CurrentStateSnapshot_MemoryGrants]
                WHERE [SnapshotId]=@ParentCurrentStateSnapshotId;

                INSERT [#CurrentRequests_SourceTasks]
                SELECT
                      [task_address],[task_state],[session_id],[request_id]
                    , [exec_context_id],[scheduler_id],[worker_address]
                FROM [#CurrentOverview_CurrentStateSnapshot_Tasks]
                WHERE [SnapshotId]=@ParentCurrentStateSnapshotId;

                INSERT [#CurrentRequests_SourceSchedulers]
                SELECT
                      [scheduler_id],[scheduler_address],[parent_node_id],[status]
                    , [is_online],[is_idle],[current_tasks_count],[runnable_tasks_count]
                    , [current_workers_count],[active_workers_count],[work_queue_count]
                    , [pending_disk_io_count],[load_factor]
                FROM [#CurrentOverview_CurrentStateSnapshot_Schedulers]
                WHERE [SnapshotId]=@ParentCurrentStateSnapshotId;

                INSERT [#CurrentRequests_SourceSessionTransactions]
                SELECT
                      [session_id],[transaction_id],[is_user_transaction],[is_local]
                    , [is_enlisted],[is_bound],[open_transaction_count]
                FROM [#CurrentOverview_CurrentStateSnapshot_SessionTransactions]
                WHERE [SnapshotId]=@ParentCurrentStateSnapshotId;

                INSERT [#CurrentRequests_SourceActiveTransactions]
                SELECT
                      [transaction_id],[transaction_begin_time],[transaction_type],[transaction_state]
                FROM [#CurrentOverview_CurrentStateSnapshot_ActiveTransactions]
                WHERE [SnapshotId]=@ParentCurrentStateSnapshotId;

                INSERT [#CurrentRequests_SourceDatabaseTransactions]
                SELECT
                      [transaction_id],[database_id],[database_transaction_log_bytes_used]
                    , [database_transaction_log_bytes_reserved]
                FROM [#CurrentOverview_CurrentStateSnapshot_DatabaseTransactions]
                WHERE [SnapshotId]=@ParentCurrentStateSnapshotId;

                INSERT [#CurrentRequests_SourceTempDbSessionUsage]
                SELECT
                      [session_id],[user_objects_alloc_page_count],[user_objects_dealloc_page_count]
                    , [internal_objects_alloc_page_count],[internal_objects_dealloc_page_count]
                FROM [#CurrentOverview_CurrentStateSnapshot_TempDbSessionUsage]
                WHERE [SnapshotId]=@ParentCurrentStateSnapshotId;

                INSERT [#CurrentRequests_SourceTempDbTaskUsage]
                SELECT
                      [session_id],[request_id],[exec_context_id]
                    , [user_objects_alloc_page_count],[user_objects_dealloc_page_count]
                    , [internal_objects_alloc_page_count],[internal_objects_dealloc_page_count]
                FROM [#CurrentOverview_CurrentStateSnapshot_TempDbTaskUsage]
                WHERE [SnapshotId]=@ParentCurrentStateSnapshotId;

                INSERT [#CurrentRequests_SourceWorkloadGroups]
                SELECT [group_id],[name],[pool_id]
                FROM [#CurrentOverview_CurrentStateSnapshot_WorkloadGroups]
                WHERE [SnapshotId]=@ParentCurrentStateSnapshotId;

                INSERT [#CurrentRequests_SourceResourcePools]
                SELECT [pool_id],[name]
                FROM [#CurrentOverview_CurrentStateSnapshot_ResourcePools]
                WHERE [SnapshotId]=@ParentCurrentStateSnapshotId;

                IF @SqlTextErforderlich=1
                    INSERT [#CurrentRequests_SourceSqlText]
                    SELECT [SqlHandle],[Text],[DatabaseId],[ObjectId],[ObjectNumber],[IsEncrypted]
                    FROM [#CurrentOverview_CurrentStateSnapshot_SqlText]
                    WHERE [SnapshotId]=@ParentCurrentStateSnapshotId;

                INSERT [#CurrentRequests_SnapshotStatus]
                (
                      [SourceOrdinal],[SnapshotId],[SourceCode],[SourceObject]
                    , [CapturedAtUtc],[CompletedAtUtc],[StatusCode],[IsPartial]
                    , [CapturedRowCount],[ErrorNumber],[ErrorMessage]
                )
                SELECT
                      [SourceOrdinal],[SnapshotId],[SourceCode],[SourceObject]
                    , [CapturedAtUtc],[CompletedAtUtc],[StatusCode],[IsPartial]
                    , [CapturedRowCount],[ErrorNumber],[ErrorMessage]
                FROM [#CurrentOverview_CurrentStateSnapshot_SourceStatus]
                WHERE [SnapshotId]=@ParentCurrentStateSnapshotId
                  AND [SourceCode] IN
                      ('SESSIONS','REQUESTS','CONNECTIONS','WAITING_TASKS','MEMORY_GRANTS',
                       'TASKS','SCHEDULERS','SESSION_TRANSACTIONS','ACTIVE_TRANSACTIONS',
                       'DATABASE_TRANSACTIONS','TEMPDB_SESSION_USAGE','TEMPDB_TASK_USAGE',
                       'WORKLOAD_GROUPS','RESOURCE_POOLS','SQL_TEXT');

                SELECT
                      @EvidenceSnapshotStartedAtUtc=MIN([CapturedAtUtc])
                    , @ParentSnapshotIsPartial=CONVERT(bit,MAX(CONVERT(int,[IsPartial])))
                FROM [#CurrentRequests_SnapshotStatus];
            END;
        END TRY
        BEGIN CATCH
            SELECT
                  @ErrorNumber=ERROR_NUMBER()
                , @ErrorMessage=ERROR_MESSAGE()
                , @IsPartial=1
                , @StatusCode=CASE WHEN ERROR_NUMBER()=1222 THEN 'TIMEOUT'
                    WHEN ERROR_NUMBER() IN(229,262,297,300,371,916) THEN 'DENIED_PERMISSION'
                    ELSE 'INVALID_PARENT_SNAPSHOT' END;
        END CATCH;
    END
    ELSE IF @StatusCode='AVAILABLE'
    BEGIN TRY
        SET @EvidenceSnapshotStartedAtUtc=SYSUTCDATETIME();

        INSERT [#CurrentRequests_SourceSessions]
        SELECT [session_id],[is_user_process],[login_name],[original_login_name],[host_name],[program_name]
        FROM [sys].[dm_exec_sessions] WITH (NOLOCK);

        INSERT [#CurrentRequests_SourceRequests]
        SELECT
              [session_id],[request_id],[status],[command],[database_id],[start_time]
            , [total_elapsed_time],[cpu_time],[logical_reads],[reads],[writes],[row_count]
            , [percent_complete],[estimated_completion_time],[blocking_session_id]
            , [wait_type],[wait_time],[last_wait_type],[wait_resource],[dop]
            , [parallel_worker_count],[transaction_isolation_level]
            , [open_transaction_count],[open_resultset_count],[transaction_id]
            , [scheduler_id],[task_address],[nest_level],[group_id]
            , [statement_sql_handle],[statement_context_id],[is_resumable]
            , [executing_managed_code],[context_info],[query_hash],[query_plan_hash]
            , [sql_handle],[plan_handle],[statement_start_offset],[statement_end_offset]
        FROM [sys].[dm_exec_requests] WITH (NOLOCK);

        INSERT [#CurrentRequests_SourceConnections]
        SELECT
              [session_id],[connection_id],[client_net_address]
            , [net_transport],[protocol_type],[encrypt_option],[auth_scheme]
        FROM [sys].[dm_exec_connections] WITH (NOLOCK);

        INSERT [#CurrentRequests_SourceWaitingTasks]
        SELECT
              [waiting_task_address],[session_id],[exec_context_id]
            , [wait_duration_ms],[wait_type],[blocking_session_id],[resource_description]
        FROM [sys].[dm_os_waiting_tasks] WITH (NOLOCK);

        INSERT [#CurrentRequests_SourceMemoryGrants]
        SELECT [session_id],[request_id],[requested_memory_kb],[granted_memory_kb],[used_memory_kb],[ideal_memory_kb]
        FROM [sys].[dm_exec_query_memory_grants] WITH (NOLOCK);

        INSERT [#CurrentRequests_SourceWorkloadGroups]
        SELECT [group_id],[name],[pool_id]
        FROM [sys].[dm_resource_governor_workload_groups] WITH (NOLOCK);

        INSERT [#CurrentRequests_SourceResourcePools]
        SELECT [pool_id],[name]
        FROM [sys].[dm_resource_governor_resource_pools] WITH (NOLOCK);

        INSERT [#CurrentRequests_SourceTasks]
        SELECT
              [t].[task_address],[t].[task_state],[t].[session_id],[t].[request_id]
            , [t].[exec_context_id],[t].[scheduler_id],[t].[worker_address]
        FROM [sys].[dm_os_tasks] AS [t] WITH (NOLOCK)
        WHERE EXISTS
        (
            SELECT 1
            FROM [#CurrentRequests_SourceRequests] AS [r]
            WHERE [r].[session_id]=[t].[session_id]
              AND [r].[request_id]=[t].[request_id]
        );

        INSERT [#CurrentRequests_SourceSchedulers]
        SELECT
              [s].[scheduler_id],[s].[scheduler_address],[s].[parent_node_id],[s].[status]
            , [s].[is_online],[s].[is_idle],[s].[current_tasks_count],[s].[runnable_tasks_count]
            , [s].[current_workers_count],[s].[active_workers_count],[s].[work_queue_count]
            , [s].[pending_disk_io_count],[s].[load_factor]
        FROM [sys].[dm_os_schedulers] AS [s] WITH (NOLOCK)
        WHERE [s].[scheduler_id] < 1048576
          AND
          (
              EXISTS
              (
                  SELECT 1 FROM [#CurrentRequests_SourceRequests] AS [r]
                  WHERE [r].[scheduler_id]=[s].[scheduler_id]
              )
              OR EXISTS
              (
                  SELECT 1 FROM [#CurrentRequests_SourceTasks] AS [t]
                  WHERE [t].[scheduler_id]=[s].[scheduler_id]
              )
          );

        INSERT [#CurrentRequests_SourceSessionTransactions]
        SELECT
              [st].[session_id],[st].[transaction_id],[st].[is_user_transaction]
            , [st].[is_local],[st].[is_enlisted],[st].[is_bound],[st].[open_transaction_count]
        FROM [sys].[dm_tran_session_transactions] AS [st] WITH (NOLOCK)
        WHERE EXISTS
        (
            SELECT 1 FROM [#CurrentRequests_SourceRequests] AS [r]
            WHERE [r].[session_id]=[st].[session_id]
        );

        INSERT [#CurrentRequests_SourceActiveTransactions]
        SELECT
              [at].[transaction_id],[at].[transaction_begin_time]
            , [at].[transaction_type],[at].[transaction_state]
        FROM [sys].[dm_tran_active_transactions] AS [at] WITH (NOLOCK)
        WHERE EXISTS
        (
            SELECT 1 FROM [#CurrentRequests_SourceSessionTransactions] AS [st]
            WHERE [st].[transaction_id]=[at].[transaction_id]
        );

        INSERT [#CurrentRequests_SourceDatabaseTransactions]
        SELECT
              [dt].[transaction_id],[dt].[database_id]
            , [dt].[database_transaction_log_bytes_used]
            , [dt].[database_transaction_log_bytes_reserved]
        FROM [sys].[dm_tran_database_transactions] AS [dt] WITH (NOLOCK)
        WHERE EXISTS
        (
            SELECT 1 FROM [#CurrentRequests_SourceSessionTransactions] AS [st]
            WHERE [st].[transaction_id]=[dt].[transaction_id]
        );

        EXEC [sys].[sp_executesql] N'
            USE [tempdb];
            INSERT [#CurrentRequests_SourceTempDbSessionUsage]
            SELECT
                  [u].[session_id],[u].[user_objects_alloc_page_count]
                , [u].[user_objects_dealloc_page_count]
                , [u].[internal_objects_alloc_page_count]
                , [u].[internal_objects_dealloc_page_count]
            FROM [sys].[dm_db_session_space_usage] AS [u] WITH (NOLOCK)
            WHERE EXISTS
            (
                SELECT 1 FROM [#CurrentRequests_SourceRequests] AS [r]
                WHERE [r].[session_id]=[u].[session_id]
            );

            INSERT [#CurrentRequests_SourceTempDbTaskUsage]
            SELECT
                  [u].[session_id],[u].[request_id],[u].[exec_context_id]
                , [u].[user_objects_alloc_page_count]
                , [u].[user_objects_dealloc_page_count]
                , [u].[internal_objects_alloc_page_count]
                , [u].[internal_objects_dealloc_page_count]
            FROM [sys].[dm_db_task_space_usage] AS [u] WITH (NOLOCK)
            WHERE EXISTS
            (
                SELECT 1 FROM [#CurrentRequests_SourceRequests] AS [r]
                WHERE [r].[session_id]=[u].[session_id]
                  AND [r].[request_id]=[u].[request_id]
            );';

        IF @SqlTextErforderlich=1
        BEGIN
            INSERT [#CurrentRequests_SourceSqlText]
            ([SqlHandle],[text],[dbid],[objectid],[number],[encrypted])
            SELECT
                  [h].[SqlHandle],[t].[text],[t].[dbid],[t].[objectid],[t].[number],[t].[encrypted]
            FROM
            (
                SELECT [sql_handle] AS [SqlHandle]
                FROM [#CurrentRequests_SourceRequests]
                WHERE [sql_handle] IS NOT NULL
                GROUP BY [sql_handle]
            ) AS [h]
            OUTER APPLY [sys].[dm_exec_sql_text]([h].[SqlHandle]) AS [t];
        END;

        INSERT [#CurrentRequests_SnapshotStatus]
        (
              [SourceOrdinal],[SnapshotId],[SourceCode],[SourceObject]
            , [CapturedAtUtc],[CompletedAtUtc],[StatusCode],[IsPartial]
            , [CapturedRowCount],[ErrorNumber],[ErrorMessage]
        )
        SELECT
              [v].[SourceOrdinal],@EvidenceSnapshotId,[v].[SourceCode],[v].[SourceObject]
            , @EvidenceSnapshotStartedAtUtc,SYSUTCDATETIME(),'AVAILABLE',CONVERT(bit,0)
            , [v].[CapturedRowCount],NULL,NULL
        FROM
        (
            VALUES
              (10,'SESSIONS',N'sys.dm_exec_sessions',CONVERT(bigint,(SELECT COUNT_BIG(*) FROM [#CurrentRequests_SourceSessions])))
            , (20,'REQUESTS',N'sys.dm_exec_requests',CONVERT(bigint,(SELECT COUNT_BIG(*) FROM [#CurrentRequests_SourceRequests])))
            , (30,'CONNECTIONS',N'sys.dm_exec_connections',CONVERT(bigint,(SELECT COUNT_BIG(*) FROM [#CurrentRequests_SourceConnections])))
            , (40,'WAITING_TASKS',N'sys.dm_os_waiting_tasks',CONVERT(bigint,(SELECT COUNT_BIG(*) FROM [#CurrentRequests_SourceWaitingTasks])))
            , (50,'MEMORY_GRANTS',N'sys.dm_exec_query_memory_grants',CONVERT(bigint,(SELECT COUNT_BIG(*) FROM [#CurrentRequests_SourceMemoryGrants])))
            , (60,'WORKLOAD_GROUPS',N'sys.dm_resource_governor_workload_groups',CONVERT(bigint,(SELECT COUNT_BIG(*) FROM [#CurrentRequests_SourceWorkloadGroups])))
            , (70,'RESOURCE_POOLS',N'sys.dm_resource_governor_resource_pools',CONVERT(bigint,(SELECT COUNT_BIG(*) FROM [#CurrentRequests_SourceResourcePools])))
            , (90,'TASKS',N'sys.dm_os_tasks',CONVERT(bigint,(SELECT COUNT_BIG(*) FROM [#CurrentRequests_SourceTasks])))
            , (100,'SCHEDULERS',N'sys.dm_os_schedulers',CONVERT(bigint,(SELECT COUNT_BIG(*) FROM [#CurrentRequests_SourceSchedulers])))
            , (110,'SESSION_TRANSACTIONS',N'sys.dm_tran_session_transactions',CONVERT(bigint,(SELECT COUNT_BIG(*) FROM [#CurrentRequests_SourceSessionTransactions])))
            , (120,'ACTIVE_TRANSACTIONS',N'sys.dm_tran_active_transactions',CONVERT(bigint,(SELECT COUNT_BIG(*) FROM [#CurrentRequests_SourceActiveTransactions])))
            , (130,'DATABASE_TRANSACTIONS',N'sys.dm_tran_database_transactions',CONVERT(bigint,(SELECT COUNT_BIG(*) FROM [#CurrentRequests_SourceDatabaseTransactions])))
            , (140,'TEMPDB_SESSION_USAGE',N'tempdb.sys.dm_db_session_space_usage',CONVERT(bigint,(SELECT COUNT_BIG(*) FROM [#CurrentRequests_SourceTempDbSessionUsage])))
            , (150,'TEMPDB_TASK_USAGE',N'tempdb.sys.dm_db_task_space_usage',CONVERT(bigint,(SELECT COUNT_BIG(*) FROM [#CurrentRequests_SourceTempDbTaskUsage])))
            , (160,'SQL_TEXT',N'sys.dm_exec_sql_text',CONVERT(bigint,(SELECT COUNT_BIG(*) FROM [#CurrentRequests_SourceSqlText])))
        ) AS [v]([SourceOrdinal],[SourceCode],[SourceObject],[CapturedRowCount]);
    END TRY
    BEGIN CATCH
        SELECT
              @ErrorNumber=ERROR_NUMBER()
            , @ErrorMessage=ERROR_MESSAGE()
            , @IsPartial=1
            , @StatusCode=CASE WHEN ERROR_NUMBER()=1222 THEN 'TIMEOUT'
                WHEN ERROR_NUMBER() IN(229,262,297,300,371,916) THEN 'DENIED_PERMISSION'
                ELSE 'ERROR_HANDLED' END;
    END CATCH;

    IF NOT EXISTS
    (
        SELECT 1 FROM [#CurrentRequests_SnapshotStatus]
        WHERE [SourceCode]='SQL_TEXT'
    )
    BEGIN
        INSERT [#CurrentRequests_SnapshotStatus]
        VALUES
        (
              160,@EvidenceSnapshotId,'SQL_TEXT',N'sys.dm_exec_sql_text'
            , @CollectionTimeUtc,SYSUTCDATETIME()
            , CASE WHEN @SqlTextErforderlich=0 THEN 'NOT_COLLECTED' ELSE @StatusCode END
            , CASE WHEN @SqlTextErforderlich=0 THEN 0 ELSE 1 END
            , 0,@ErrorNumber
            , CASE WHEN @SqlTextErforderlich=0
                   THEN N'SQL-Text wurde für diesen Aufruf nicht benötigt.'
                   ELSE @ErrorMessage END
        );
    END;

    IF @SqlTextErforderlich=0
    BEGIN
        UPDATE [#CurrentRequests_SnapshotStatus]
        SET [StatusCode]='NOT_COLLECTED',[IsPartial]=0,[ErrorNumber]=NULL,
            [ErrorMessage]=N'SQL-Text wurde für diesen Aufruf nicht benötigt.'
        WHERE [SourceCode]='SQL_TEXT';
    END;

    IF @StatusCode<>'AVAILABLE'
       AND NOT EXISTS (SELECT 1 FROM [#CurrentRequests_SnapshotStatus])
    BEGIN
        INSERT [#CurrentRequests_SnapshotStatus]
        VALUES
        (
              1,@EvidenceSnapshotId,'CURRENT_REQUESTS_SNAPSHOT'
            , N'CurrentRequests source materialization',@EvidenceSnapshotStartedAtUtc
            , SYSUTCDATETIME(),@StatusCode,1,0,@ErrorNumber,@ErrorMessage
        );
    END;

    SET @CandidateMaxZeilen =
        CASE
            WHEN @HasRegex = 1 OR @MaxZeilen IS NULL OR @MaxZeilen = 0
                THEN CONVERT(bigint, 9223372036854775807)
            ELSE CONVERT(bigint, @MaxZeilen) + 1
        END;

    IF @StatusCode = 'AVAILABLE'
    BEGIN TRY
        INSERT [#CurrentRequests_Result]
        (
              [SessionId], [RequestId], [RequestStatus], [Command]
            , [DatabaseId], [DatabaseName], [LoginName], [OriginalLoginName]
            , [HostName], [ProgramName]
            , [IsToolBackgroundQuery], [ToolBackgroundRuleCode]
            , [ToolBackgroundCategory]
            , [ToolBackgroundDetection], [ToolBackgroundConfidence]
            , [StartTime], [ElapsedMs], [CpuMs]
            , [LogicalReads], [Reads], [Writes], [RowCount], [PercentComplete]
            , [EstimatedCompletionTimeMs], [BlockingSessionId], [WaitType]
            , [WaitTimeMs], [LastWaitType], [WaitResource], [WaitingTaskCount]
            , [MaxTaskWaitMs], [TaskWaitTypes], [RequestedMemoryMb]
            , [GrantedMemoryMb], [UsedMemoryMb], [IdealMemoryMb], [Dop]
            , [ParallelWorkerCount], [TransactionIsolationLevel]
            , [OpenTransactionCount], [OpenResultsetCount], [TransactionId]
            , [ConnectionId], [SchedulerId], [TaskAddress], [NestLevel]
            , [WorkloadGroupId], [WorkloadGroupName], [ResourcePoolId], [ResourcePoolName]
            , [StatementSqlHandle], [StatementContextId], [IsResumable]
            , [ExecutingManagedCode], [ContextInfo], [ClientNetAddress], [QueryHash]
            , [QueryPlanHash], [SqlHandle], [PlanHandle]
            , [SqlTextDatabaseId], [SqlTextObjectId], [SqlTextObjectNumber]
            , [SqlTextIsEncrypted], [ExecutionContextType]
            , [HasStatementOffsets], [IsStatementOffsetValid]
            , [StatementStartOffsetBytes], [StatementEndOffsetBytes]
            , [StatementStartCharacter], [StatementEndCharacter]
            , [StatementStartLine], [StatementEndLine]
            , [CurrentStatementCharacterCount], [CurrentStatementBytes], [CurrentStatementIsTruncated]
            , [BatchTextCharacterCount], [BatchTextBytes], [BatchTextIsTruncated]
            , [CurrentStatement], [BatchText]
            , [InputBufferEventType], [InputBufferParameterCount]
            , [InputBufferCharacterCount], [InputBufferBytes], [InputBufferIsTruncated]
            , [InputBufferText]
        )
        SELECT TOP (@CandidateMaxZeilen)
              [r].[session_id]
            , [r].[request_id]
            , [r].[status]
            , [r].[command]
            , [r].[database_id]
            , [d].[name]
            , [s].[login_name]
            , [s].[original_login_name]
            , [s].[host_name]
            , [s].[program_name]
            , [tool].[IsToolBackgroundQuery]
            , [tool].[ToolBackgroundRuleCode]
            , [tool].[ToolBackgroundCategory]
            , [tool].[ToolBackgroundDetection]
            , [tool].[ToolBackgroundConfidence]
            , [r].[start_time]
            , [r].[total_elapsed_time]
            , [r].[cpu_time]
            , [r].[logical_reads]
            , [r].[reads]
            , [r].[writes]
            , [r].[row_count]
            , [r].[percent_complete]
            , [r].[estimated_completion_time]
            , NULLIF([r].[blocking_session_id], 0)
            , [r].[wait_type]
            , [r].[wait_time]
            , [r].[last_wait_type]
            , [r].[wait_resource]
            , CONVERT(int, [wt].[WaitingTaskCount])
            , [wt].[MaxTaskWaitMs]
            , [wt].[TaskWaitTypes]
            , CONVERT(decimal(19,2), [mg].[requested_memory_kb] / 1024.0)
            , CONVERT(decimal(19,2), [mg].[granted_memory_kb] / 1024.0)
            , CONVERT(decimal(19,2), [mg].[used_memory_kb] / 1024.0)
            , CONVERT(decimal(19,2), [mg].[ideal_memory_kb] / 1024.0)
            , [r].[dop]
            , [r].[parallel_worker_count]
            , CASE [r].[transaction_isolation_level]
                  WHEN 0 THEN N'Unspecified'
                  WHEN 1 THEN N'ReadUncommitted'
                  WHEN 2 THEN N'ReadCommitted'
                  WHEN 3 THEN N'RepeatableRead'
                  WHEN 4 THEN N'Serializable'
                  WHEN 5 THEN N'Snapshot'
              END
            , [r].[open_transaction_count]
            , [r].[open_resultset_count]
            , [r].[transaction_id]
            , [c].[connection_id]
            , [r].[scheduler_id]
            , [r].[task_address]
            , [r].[nest_level]
            , [r].[group_id]
            , [wg].[name]
            , [rp].[pool_id]
            , [rp].[name]
            , [r].[statement_sql_handle]
            , [r].[statement_context_id]
            , [r].[is_resumable]
            , [r].[executing_managed_code]
            , [r].[context_info]
            , [c].[client_net_address]
            , [r].[query_hash]
            , [r].[query_plan_hash]
            , [r].[sql_handle]
            , [r].[plan_handle]
            , [txt].[dbid]
            , [txt].[objectid]
            , [txt].[number]
            , [txt].[encrypted]
            , CASE
                  WHEN [txt].[objectid] IS NOT NULL AND [txt].[objectid] > 0 THEN 'MODULE'
                  WHEN [txt].[text] IS NOT NULL THEN 'BATCH'
                  ELSE 'UNAVAILABLE'
              END
            , [st].[HasStatementOffsets]
            , [st].[IsStatementOffsetValid]
            , [st].[StatementStartOffsetBytes]
            , [st].[StatementEndOffsetBytes]
            , [st].[StatementStartCharacter]
            , [st].[StatementEndCharacter]
            , [st].[StatementStartLine]
            , [st].[StatementEndLine]
            , [st].[StatementCharacterCount]
            , NULL
            , CONVERT(bit, 0)
            , [st].[BatchCharacterCount]
            , NULL
            , CONVERT(bit, 0)
            , CASE WHEN @StatementTextErforderlich = 1 THEN [st].[StatementText] END
            , CASE WHEN @BatchTextErforderlich = 1 THEN [txt].[text] END
            , NULL
            , NULL
            , NULL
            , NULL
            , CONVERT(bit, 0)
            , NULL
        FROM [#CurrentRequests_SourceRequests] AS [r]
        JOIN [#CurrentRequests_SourceSessions] AS [s]
          ON [s].[session_id] = [r].[session_id]
        CROSS APPLY [monitor].[TVF_ToolBackgroundQueryInfo]([s].[program_name]) AS [tool]
        LEFT JOIN [#CurrentRequests_SourceConnections] AS [c]
          ON [c].[session_id] = [r].[session_id]
        LEFT JOIN [sys].[databases] AS [d] WITH (NOLOCK)
          ON [d].[database_id] = [r].[database_id]
        OUTER APPLY
        (
            SELECT
                  [WaitingTaskCount] = COUNT_BIG(*)
                , [MaxTaskWaitMs] = MAX(CONVERT(bigint, [w].[wait_duration_ms]))
                , [TaskWaitTypes] = STRING_AGG(CONVERT(nvarchar(max), [w].[wait_type]), N',')
                    WITHIN GROUP (ORDER BY [w].[wait_type])
            FROM [#CurrentRequests_SourceWaitingTasks] AS [w]
            WHERE [w].[session_id] = [r].[session_id]
        ) AS [wt]
        LEFT JOIN [#CurrentRequests_SourceMemoryGrants] AS [mg]
          ON [mg].[session_id] = [r].[session_id]
         AND [mg].[request_id] = [r].[request_id]
        LEFT JOIN [#CurrentRequests_SourceWorkloadGroups] AS [wg]
          ON [wg].[group_id] = [r].[group_id]
        LEFT JOIN [#CurrentRequests_SourceResourcePools] AS [rp]
          ON [rp].[pool_id] = [wg].[pool_id]
        LEFT JOIN [#CurrentRequests_SourceSqlText] AS [txt]
          ON [txt].[SqlHandle]=CASE WHEN @SqlTextErforderlich=1 THEN [r].[sql_handle] END
        OUTER APPLY [monitor].[TVF_StatementText]
        (
              [txt].[text]
            , [r].[statement_start_offset]
            , [r].[statement_end_offset]
        ) AS [st]
        WHERE
              (NOT EXISTS (SELECT 1 FROM [#CurrentRequests_SessionIdFilter])
               OR EXISTS
                  (SELECT 1 FROM [#CurrentRequests_SessionIdFilter] AS [f] WHERE [f].[SessionId] = [r].[session_id]))
          AND (@AktuelleSessionEinbeziehen = 1 OR [r].[session_id] <> @@SPID)
          AND (@SystemSessionsEinbeziehen = 1 OR [s].[is_user_process] = 1)
          AND (@ToolHintergrundabfragenEinbeziehen = 1 OR [tool].[IsToolBackgroundQuery] = 0)
          AND
          (
              @EigeneSessionsModus = 'ALLE'
              OR (@EigeneSessionsModus = 'NUR' AND [s].[original_login_name] = ORIGINAL_LOGIN())
              OR (@EigeneSessionsModus = 'AUSSCHLIESSEN' AND ISNULL([s].[original_login_name], N'') <> ORIGINAL_LOGIN())
          )
          AND (@NurBlockierte = 0 OR [r].[blocking_session_id] <> 0)
          AND (@NurMitWait = 0 OR [r].[wait_type] IS NOT NULL OR [wt].[WaitingTaskCount] > 0)
          AND (@MinLaufzeitSekunden IS NULL OR [r].[total_elapsed_time] >= @MinLaufzeitSekunden * 1000)
          AND (@MinCpuMs IS NULL OR [r].[cpu_time] >= @MinCpuMs)
          AND (@MinLogicalReads IS NULL OR [r].[logical_reads] >= @MinLogicalReads)
          AND
          (
              NOT EXISTS (SELECT 1 FROM [#CurrentRequests_StringFilter] WHERE [FilterType] = 'LOGIN')
              OR EXISTS
                 (
                     SELECT 1
                     FROM [#CurrentRequests_StringFilter] AS [f]
                     WHERE [f].[FilterType] = 'LOGIN'
                       AND [f].[StringValue] = [s].[login_name] COLLATE SQL_Latin1_General_CP1_CS_AS
                 )
          )
          AND
          (
              NOT EXISTS (SELECT 1 FROM [#CurrentRequests_StringFilter] WHERE [FilterType] = 'HOST')
              OR EXISTS
                 (
                     SELECT 1
                     FROM [#CurrentRequests_StringFilter] AS [f]
                     WHERE [f].[FilterType] = 'HOST'
                       AND [f].[StringValue] = [s].[host_name] COLLATE SQL_Latin1_General_CP1_CS_AS
                 )
          )
          AND
          (
              NOT EXISTS (SELECT 1 FROM [#CurrentRequests_StringFilter] WHERE [FilterType] = 'PROGRAM')
              OR EXISTS
                 (
                     SELECT 1
                     FROM [#CurrentRequests_StringFilter] AS [f]
                     WHERE [f].[FilterType] = 'PROGRAM'
                       AND [f].[StringValue] = [s].[program_name] COLLATE SQL_Latin1_General_CP1_CS_AS
                 )
          )
          AND
          (
              NOT EXISTS (SELECT 1 FROM [#CurrentRequests_StringFilter] WHERE [FilterType] = 'DATABASE')
              OR EXISTS
                 (
                     SELECT 1
                     FROM [#CurrentRequests_StringFilter] AS [f]
                     WHERE [f].[FilterType] = 'DATABASE'
                       AND [f].[StringValue] = [d].[name] COLLATE SQL_Latin1_General_CP1_CS_AS
                 )
          )
          AND (@LoginMode <> 'LIKE' OR [s].[login_name] COLLATE SQL_Latin1_General_CP1_CS_AS LIKE @LoginPattern COLLATE SQL_Latin1_General_CP1_CS_AS)
          AND (@HostMode <> 'LIKE' OR [s].[host_name] COLLATE SQL_Latin1_General_CP1_CS_AS LIKE @HostPattern COLLATE SQL_Latin1_General_CP1_CS_AS)
          AND (@ProgramMode <> 'LIKE' OR [s].[program_name] COLLATE SQL_Latin1_General_CP1_CS_AS LIKE @ProgramPattern COLLATE SQL_Latin1_General_CP1_CS_AS)
          AND (@DatabaseMode <> 'LIKE' OR [d].[name] COLLATE SQL_Latin1_General_CP1_CS_AS LIKE @DatabasePattern COLLATE SQL_Latin1_General_CP1_CS_AS)
          AND
          (
              @TextMode <> 'LIKE'
              OR [st].[StatementText] COLLATE SQL_Latin1_General_CP1_CS_AS LIKE @TextPatternValue COLLATE SQL_Latin1_General_CP1_CS_AS
              OR [txt].[text] COLLATE SQL_Latin1_General_CP1_CS_AS LIKE @TextPatternValue COLLATE SQL_Latin1_General_CP1_CS_AS
          )
        ORDER BY
              CASE
                  WHEN @Sortierung = 'RELEVANZ'
                      THEN CASE
                               WHEN [r].[blocking_session_id] <> 0 THEN 3
                               WHEN [r].[wait_type] IS NOT NULL THEN 2
                               ELSE 1
                           END
              END DESC
            , CASE WHEN @Sortierung = 'CPU' THEN [r].[cpu_time] END DESC
            , CASE WHEN @Sortierung = 'READS' THEN [r].[logical_reads] END DESC
            , CASE WHEN @Sortierung = 'DAUER' THEN [r].[total_elapsed_time] END DESC
            , [r].[session_id]
            , [r].[request_id];

        IF @HasRegex = 1
        BEGIN
            DECLARE @Sql nvarchar(max) = N'';

            IF @LoginMode IN ('REGEX', 'REGEXI')
                SET @Sql += N'DELETE FROM [#CurrentRequests_Result] WHERE [LoginName] IS NULL OR NOT REGEXP_LIKE([LoginName],@LoginPattern,@LoginFlags);';
            IF @HostMode IN ('REGEX', 'REGEXI')
                SET @Sql += N'DELETE FROM [#CurrentRequests_Result] WHERE [HostName] IS NULL OR NOT REGEXP_LIKE([HostName],@HostPattern,@HostFlags);';
            IF @ProgramMode IN ('REGEX', 'REGEXI')
                SET @Sql += N'DELETE FROM [#CurrentRequests_Result] WHERE [ProgramName] IS NULL OR NOT REGEXP_LIKE([ProgramName],@ProgramPattern,@ProgramFlags);';
            IF @DatabaseMode IN ('REGEX', 'REGEXI')
                SET @Sql += N'DELETE FROM [#CurrentRequests_Result] WHERE [DatabaseName] IS NULL OR NOT REGEXP_LIKE([DatabaseName],@DatabasePattern,@DatabaseFlags);';
            IF @TextMode IN ('REGEX', 'REGEXI')
                SET @Sql += N'DELETE FROM [#CurrentRequests_Result] WHERE COALESCE([CurrentStatement],[BatchText]) IS NULL OR (NOT REGEXP_LIKE(COALESCE([CurrentStatement],N''''),@TextPattern,@TextFlags) AND NOT REGEXP_LIKE(COALESCE([BatchText],N''''),@TextPattern,@TextFlags));';

            EXEC [sys].[sp_executesql]
                  @Sql
                , N'@LoginPattern nvarchar(4000),@LoginFlags varchar(8),@HostPattern nvarchar(4000),@HostFlags varchar(8),@ProgramPattern nvarchar(4000),@ProgramFlags varchar(8),@DatabasePattern nvarchar(4000),@DatabaseFlags varchar(8),@TextPattern nvarchar(4000),@TextFlags varchar(8)'
                , @LoginPattern
                , @LoginFlags
                , @HostPattern
                , @HostFlags
                , @ProgramPattern
                , @ProgramFlags
                , @DatabasePattern
                , @DatabaseFlags
                , @TextPatternValue
                , @TextFlags;
        END;

        IF @MaxZeilen IS NOT NULL AND @MaxZeilen > 0
        BEGIN
            IF (SELECT COUNT_BIG(*) FROM [#CurrentRequests_Result]) > @MaxZeilen
            BEGIN
                SET @HasMoreRows = 1;
            END;

            ;WITH [Ranked] AS
            (
                SELECT
                      [RowNumber] = ROW_NUMBER() OVER
                        (
                            ORDER BY
                                  CASE
                                      WHEN @Sortierung = 'RELEVANZ'
                                          THEN CASE
                                                   WHEN [BlockingSessionId] IS NOT NULL THEN 3
                                                   WHEN [WaitType] IS NOT NULL THEN 2
                                                   ELSE 1
                                               END
                                  END DESC
                                , CASE WHEN @Sortierung = 'CPU' THEN [CpuMs] END DESC
                                , CASE WHEN @Sortierung = 'READS' THEN [LogicalReads] END DESC
                                , CASE WHEN @Sortierung = 'DAUER' THEN [ElapsedMs] END DESC
                                , [SessionId]
                                , [RequestId]
                        )
                    , *
                FROM [#CurrentRequests_Result]
            )
            DELETE FROM [Ranked]
            WHERE [RowNumber] > @MaxZeilen;
        END;


        IF @ModulInfoEinbeziehen = 1
        BEGIN
            CREATE TABLE [#CurrentRequests_ModuleLookup]
            (
                  [SqlTextDatabaseId] int NOT NULL
                , [SqlTextObjectId] int NOT NULL
                , [ModuleDatabaseName] sysname NULL
                , [ModuleSchemaName] sysname NULL
                , [ModuleObjectName] sysname NULL
                , [ModuleType] char(2) NULL
                , [ModuleTypeDescription] nvarchar(60) NULL
                , [ModuleFullName] nvarchar(776) NULL
                , PRIMARY KEY ([SqlTextDatabaseId], [SqlTextObjectId])
            );

            INSERT [#CurrentRequests_ModuleLookup] ([SqlTextDatabaseId], [SqlTextObjectId])
            SELECT DISTINCT [SqlTextDatabaseId], [SqlTextObjectId]
            FROM [#CurrentRequests_Result]
            WHERE [SqlTextDatabaseId] IS NOT NULL
              AND [SqlTextObjectId] IS NOT NULL
              AND [SqlTextObjectId] > 0;

            DECLARE @LookupDatabaseId int;
            DECLARE @LookupDatabaseName sysname;
            DECLARE @LookupSql nvarchar(max);

            DECLARE [ModuleDatabaseCursor] CURSOR LOCAL FAST_FORWARD FOR
                SELECT DISTINCT [d].[database_id], [d].[name]
                FROM [#CurrentRequests_ModuleLookup] AS [m]
                JOIN [master].[sys].[databases] AS [d] WITH (NOLOCK)
                  ON [d].[database_id] = [m].[SqlTextDatabaseId]
                WHERE [d].[state] = 0
                ORDER BY [d].[database_id];

            OPEN [ModuleDatabaseCursor];
            FETCH NEXT FROM [ModuleDatabaseCursor] INTO @LookupDatabaseId, @LookupDatabaseName;

            WHILE @@FETCH_STATUS = 0
            BEGIN
                BEGIN TRY
                    SET @LookupSql =
                        N'USE ' + QUOTENAME(@LookupDatabaseName) + N';
                          UPDATE [m]
                          SET [ModuleDatabaseName] = @DatabaseName,
                              [ModuleSchemaName] = [s].[name],
                              [ModuleObjectName] = [o].[name],
                              [ModuleType] = [o].[type],
                              [ModuleTypeDescription] = [o].[type_desc],
                              [ModuleFullName] = QUOTENAME(@DatabaseName) + N''.'' + QUOTENAME([s].[name]) + N''.'' + QUOTENAME([o].[name])
                          FROM [#CurrentRequests_ModuleLookup] AS [m]
                          JOIN [sys].[objects] AS [o] WITH (NOLOCK)
                            ON [o].[object_id] = [m].[SqlTextObjectId]
                          JOIN [sys].[schemas] AS [s] WITH (NOLOCK)
                            ON [s].[schema_id] = [o].[schema_id]
                          WHERE [m].[SqlTextDatabaseId] = @DatabaseId;';

                    EXEC [sys].[sp_executesql]
                          @LookupSql
                        , N'@DatabaseId int, @DatabaseName sysname'
                        , @DatabaseId = @LookupDatabaseId
                        , @DatabaseName = @LookupDatabaseName;
                END TRY
                BEGIN CATCH
                    INSERT [#CurrentRequests_Warnings]
                    (
                          [DatabaseName], [Code], [Message]
                    )
                    VALUES
                    (
                          @LookupDatabaseName
                        , CASE
                              WHEN ERROR_NUMBER() IN (229, 262, 297, 300, 371, 916) THEN 'MODULE_LOOKUP_DENIED'
                              WHEN ERROR_NUMBER() = 1222 THEN 'MODULE_LOOKUP_TIMEOUT'
                              ELSE 'MODULE_LOOKUP_FAILED'
                          END
                        , ERROR_MESSAGE()
                    );

                    SET @IsPartial = 1;
                END CATCH;

                FETCH NEXT FROM [ModuleDatabaseCursor] INTO @LookupDatabaseId, @LookupDatabaseName;
            END;

            CLOSE [ModuleDatabaseCursor];
            DEALLOCATE [ModuleDatabaseCursor];

            UPDATE [r]
            SET
                  [ModuleDatabaseName] = [m].[ModuleDatabaseName]
                , [ModuleSchemaName] = [m].[ModuleSchemaName]
                , [ModuleObjectName] = [m].[ModuleObjectName]
                , [ModuleType] = [m].[ModuleType]
                , [ModuleTypeDescription] = [m].[ModuleTypeDescription]
                , [ModuleFullName] = [m].[ModuleFullName]
            FROM [#CurrentRequests_Result] AS [r]
            JOIN [#CurrentRequests_ModuleLookup] AS [m]
              ON [m].[SqlTextDatabaseId] = [r].[SqlTextDatabaseId]
             AND [m].[SqlTextObjectId] = [r].[SqlTextObjectId];
        END;

        INSERT [#CurrentRequests_SnapshotStatus]
        (
              [SourceOrdinal],[SnapshotId],[SourceCode],[SourceObject]
            , [CapturedAtUtc],[CompletedAtUtc],[StatusCode],[IsPartial]
            , [CapturedRowCount],[ErrorNumber],[ErrorMessage]
        )
        SELECT
              180,@EvidenceSnapshotId,'MODULE_CATALOG',N'<database>.sys.objects|sys.schemas'
            , @CollectionTimeUtc,SYSUTCDATETIME()
            , CASE
                  WHEN @ModulInfoEinbeziehen=0 THEN 'NOT_COLLECTED'
                  WHEN EXISTS
                       (
                           SELECT 1 FROM [#CurrentRequests_Warnings]
                           WHERE [Code] LIKE 'MODULE_LOOKUP_%'
                       ) THEN 'PARTIAL_RESULT'
                  ELSE 'AVAILABLE'
              END
            , CONVERT(bit,CASE WHEN EXISTS
              (
                  SELECT 1 FROM [#CurrentRequests_Warnings]
                  WHERE [Code] LIKE 'MODULE_LOOKUP_%'
              ) THEN 1 ELSE 0 END)
            , CONVERT(bigint,(SELECT COUNT_BIG(*) FROM [#CurrentRequests_Result] WHERE [ModuleFullName] IS NOT NULL))
            , NULL
            , CASE WHEN @ModulInfoEinbeziehen=0 THEN N'Die Modulauflösung wurde nicht angefordert.' END;

        IF @InputBufferEinbeziehen = 1
        BEGIN
            DECLARE @InputBufferCapturedAtUtc datetime2(3)=SYSUTCDATETIME();
            BEGIN TRY
                INSERT [#CurrentRequests_SourceInputBuffer]
                (
                    [session_id],[request_id],[event_type],[parameters],[event_info]
                )
                SELECT
                      [r].[SessionId],[r].[RequestId]
                    , [ib].[event_type],[ib].[parameters],[ib].[event_info]
                FROM [#CurrentRequests_Result] AS [r]
                OUTER APPLY [sys].[dm_exec_input_buffer]
                (
                      [r].[SessionId]
                    , [r].[RequestId]
                ) AS [ib];

                UPDATE [r]
                SET
                      [InputBufferEventType]=[ib].[event_type]
                    , [InputBufferParameterCount]=[ib].[parameters]
                    , [InputBufferText]=[ib].[event_info]
                FROM [#CurrentRequests_Result] AS [r]
                LEFT JOIN [#CurrentRequests_SourceInputBuffer] AS [ib]
                  ON [ib].[session_id]=[r].[SessionId]
                 AND [ib].[request_id]=[r].[RequestId];

                INSERT [#CurrentRequests_SnapshotStatus]
                VALUES
                (
                      170,@EvidenceSnapshotId,'INPUT_BUFFER',N'sys.dm_exec_input_buffer'
                    , @InputBufferCapturedAtUtc,SYSUTCDATETIME(),'AVAILABLE',0
                    , (SELECT COUNT_BIG(*) FROM [#CurrentRequests_SourceInputBuffer]),NULL,NULL
                );
            END TRY
            BEGIN CATCH
                INSERT [#CurrentRequests_SnapshotStatus]
                VALUES
                (
                      170,@EvidenceSnapshotId,'INPUT_BUFFER',N'sys.dm_exec_input_buffer'
                    , @InputBufferCapturedAtUtc,SYSUTCDATETIME()
                    , CASE
                          WHEN ERROR_NUMBER()=1222 THEN 'TIMEOUT'
                          WHEN ERROR_NUMBER() IN(229,262,297,300,371,916) THEN 'DENIED_PERMISSION'
                          ELSE 'ERROR_HANDLED'
                      END
                    , 1,0,ERROR_NUMBER(),ERROR_MESSAGE()
                );
                SET @IsPartial=1;
            END CATCH;
        END
        ELSE
        BEGIN
            INSERT [#CurrentRequests_SnapshotStatus]
            VALUES
            (
                  170,@EvidenceSnapshotId,'INPUT_BUFFER',N'sys.dm_exec_input_buffer'
                , @CollectionTimeUtc,SYSUTCDATETIME(),'NOT_COLLECTED',0,0,NULL
                , N'Der Input Buffer wurde nicht angefordert.'
            );
        END;

        UPDATE [r]
        SET [CurrentStatement]=CASE WHEN @MitSqlText=1 THEN [CurrentStatement] END,
            [BatchText]=CASE WHEN @GesamtenSqlTextEinbeziehen=1 THEN [BatchText] END,
            [InputBufferText]=CASE WHEN @InputBufferEinbeziehen=1 THEN [InputBufferText] END
        FROM [#CurrentRequests_Result] AS [r];

        DECLARE @TruncatedValueCount bigint=0,@LargestRequiredCharacters bigint=NULL;
        DECLARE @ColumnTruncatedCount bigint=0,@ColumnLargestCharacters bigint=NULL;
        EXEC [monitor].[InternalProjectUnicodeTextColumn]
              @SourceTable=N'#CurrentRequests_Result',@TextColumn=N'CurrentStatement'
            , @CharactersColumn=N'CurrentStatementCharacterCount',@BytesColumn=N'CurrentStatementBytes'
            , @IsTruncatedColumn=N'CurrentStatementIsTruncated',@MaxCharacters=@MaxSqlTextZeichen
            , @TruncatedValueCount=@ColumnTruncatedCount OUTPUT,@LargestRequiredCharacters=@ColumnLargestCharacters OUTPUT;
        SELECT @TruncatedValueCount=@TruncatedValueCount+@ColumnTruncatedCount,
               @LargestRequiredCharacters=CASE WHEN @LargestRequiredCharacters IS NULL OR @ColumnLargestCharacters>@LargestRequiredCharacters THEN @ColumnLargestCharacters ELSE @LargestRequiredCharacters END;
        EXEC [monitor].[InternalProjectUnicodeTextColumn]
              @SourceTable=N'#CurrentRequests_Result',@TextColumn=N'BatchText'
            , @CharactersColumn=N'BatchTextCharacterCount',@BytesColumn=N'BatchTextBytes'
            , @IsTruncatedColumn=N'BatchTextIsTruncated',@MaxCharacters=@MaxSqlTextZeichen
            , @TruncatedValueCount=@ColumnTruncatedCount OUTPUT,@LargestRequiredCharacters=@ColumnLargestCharacters OUTPUT;
        SELECT @TruncatedValueCount=@TruncatedValueCount+@ColumnTruncatedCount,
               @LargestRequiredCharacters=CASE WHEN @LargestRequiredCharacters IS NULL OR @ColumnLargestCharacters>@LargestRequiredCharacters THEN @ColumnLargestCharacters ELSE @LargestRequiredCharacters END;
        EXEC [monitor].[InternalProjectUnicodeTextColumn]
              @SourceTable=N'#CurrentRequests_Result',@TextColumn=N'InputBufferText'
            , @CharactersColumn=N'InputBufferCharacterCount',@BytesColumn=N'InputBufferBytes'
            , @IsTruncatedColumn=N'InputBufferIsTruncated',@MaxCharacters=@MaxSqlTextZeichen
            , @TruncatedValueCount=@ColumnTruncatedCount OUTPUT,@LargestRequiredCharacters=@ColumnLargestCharacters OUTPUT;
        SELECT @TruncatedValueCount=@TruncatedValueCount+@ColumnTruncatedCount,
               @LargestRequiredCharacters=CASE WHEN @LargestRequiredCharacters IS NULL OR @ColumnLargestCharacters>@LargestRequiredCharacters THEN @ColumnLargestCharacters ELSE @LargestRequiredCharacters END;
        EXEC [monitor].[InternalEmitTruncationWarning]
              @TruncatedValueCount=@TruncatedValueCount,@ParameterName=N'@MaxSqlTextZeichen'
            , @ParameterValue=@MaxSqlTextZeichen,@LargestRequiredCharacters=@LargestRequiredCharacters
            , @PrintMeldungen=@PrintMeldungen;

        INSERT [#CurrentRequests_RequestContext]
        (
              [SnapshotId],[CapturedAtUtc],[SessionId],[RequestId],[RequestStatus],[Command]
            , [DatabaseId],[DatabaseName],[StartTime],[ElapsedMs],[CpuMs],[LogicalReads]
            , [Reads],[Writes],[RowCount],[PercentComplete],[EstimatedCompletionTimeMs]
            , [BlockingSessionId],[WaitType],[WaitTimeMs],[WaitResource]
            , [ConnectionId],[ClientNetAddress],[NetTransport],[ProtocolType],[EncryptOption],[AuthScheme]
            , [TaskCount],[WorkerCount],[ExecutionContextCount],[RunnableTaskCount],[SuspendedTaskCount]
            , [SchedulerId],[SchedulerStatus],[SchedulerParentNodeId],[SchedulerRunnableTaskCount]
            , [SchedulerWorkQueueCount],[SchedulerPendingDiskIoCount],[SchedulerLoadFactor]
            , [TransactionId],[TransactionBeginTime],[TransactionAgeSeconds],[TransactionType]
            , [TransactionState],[IsUserTransaction],[IsLocalTransaction],[IsEnlistedTransaction]
            , [IsBoundTransaction],[TransactionLogBytesUsed],[TransactionLogBytesReserved]
            , [RequestedMemoryMb],[GrantedMemoryMb],[UsedMemoryMb],[IdealMemoryMb]
            , [TempDbSessionNetMb],[TempDbRequestNetMb],[Dop],[ParallelWorkerCount]
            , [WorkloadGroupId],[WorkloadGroupName],[ResourcePoolId],[ResourcePoolName]
            , [QueryHash],[QueryPlanHash],[SqlHandle],[PlanHandle],[StatementSqlHandle]
            , [StatementContextId],[ModuleFullName],[IsCurrent],[StatusCode],[IsPartial],[EvidenceBoundary]
        )
        SELECT
              @EvidenceSnapshotId
            , COALESCE
              (
                  (SELECT [CapturedAtUtc] FROM [#CurrentRequests_SnapshotStatus] WHERE [SourceCode]='REQUESTS')
                , @EvidenceSnapshotStartedAtUtc
              )
            , [r].[SessionId],[r].[RequestId],[r].[RequestStatus],[r].[Command]
            , [r].[DatabaseId],[r].[DatabaseName],[r].[StartTime],[r].[ElapsedMs],[r].[CpuMs]
            , [r].[LogicalReads],[r].[Reads],[r].[Writes],[r].[RowCount],[r].[PercentComplete]
            , [r].[EstimatedCompletionTimeMs],[r].[BlockingSessionId],[r].[WaitType]
            , COALESCE([wt].[MaxTaskWaitMs],[r].[WaitTimeMs])
            , COALESCE([wt].[WaitResource],[r].[WaitResource])
            , [c].[connection_id],[c].[client_net_address],[c].[net_transport]
            , [c].[protocol_type],[c].[encrypt_option],[c].[auth_scheme]
            , CONVERT(int,[task].[TaskCount]),CONVERT(int,[task].[WorkerCount])
            , CONVERT(int,[task].[ExecutionContextCount]),CONVERT(int,[task].[RunnableTaskCount])
            , CONVERT(int,[task].[SuspendedTaskCount])
            , [r].[SchedulerId],[sch].[status],[sch].[parent_node_id],[sch].[runnable_tasks_count]
            , [sch].[work_queue_count],[sch].[pending_disk_io_count],[sch].[load_factor]
            , [r].[TransactionId],[at].[transaction_begin_time]
            , CASE WHEN [at].[transaction_begin_time] IS NULL THEN NULL
                   ELSE DATEDIFF_BIG(SECOND,[at].[transaction_begin_time],@CollectionTimeUtc) END
            , [at].[transaction_type],[at].[transaction_state],[st].[is_user_transaction]
            , [st].[is_local],[st].[is_enlisted],[st].[is_bound]
            , [dt].[LogBytesUsed],[dt].[LogBytesReserved]
            , [r].[RequestedMemoryMb],[r].[GrantedMemoryMb],[r].[UsedMemoryMb],[r].[IdealMemoryMb]
            , CONVERT(decimal(19,2),
                (
                    COALESCE([ts].[user_objects_alloc_page_count],0)
                  - COALESCE([ts].[user_objects_dealloc_page_count],0)
                  + COALESCE([ts].[internal_objects_alloc_page_count],0)
                  - COALESCE([ts].[internal_objects_dealloc_page_count],0)
                )*8.0/1024.0)
            , CONVERT(decimal(19,2),COALESCE([tt].[NetPages],0)*8.0/1024.0)
            , CONVERT(smallint,[r].[Dop]),[r].[ParallelWorkerCount]
            , [r].[WorkloadGroupId],[r].[WorkloadGroupName],[r].[ResourcePoolId],[r].[ResourcePoolName]
            , [r].[QueryHash],[r].[QueryPlanHash],[r].[SqlHandle],[r].[PlanHandle]
            , [r].[StatementSqlHandle],[r].[StatementContextId],[r].[ModuleFullName]
            , CONVERT(bit,1)
            , CASE WHEN @ParentSnapshotIsPartial=1 OR @IsPartial=1 THEN 'AVAILABLE_LIMITED' ELSE 'AVAILABLE' END
            , CONVERT(bit,CASE WHEN @ParentSnapshotIsPartial=1 OR @IsPartial=1 THEN 1 ELSE 0 END)
            , CASE
                  WHEN @ParentCurrentStateSnapshotId IS NULL
                      THEN N'Frische, aufruflokale Quellen; Quellzeitpunkte sind nicht transaktional atomar.'
                  ELSE N'Gemeinsamer Overview-Snapshot; Quellzeitpunkte sind je DMV ausgewiesen und nicht transaktional atomar.'
              END
        FROM [#CurrentRequests_Result] AS [r]
        LEFT JOIN [#CurrentRequests_SourceConnections] AS [c]
          ON [c].[connection_id]=[r].[ConnectionId]
        LEFT JOIN [#CurrentRequests_SourceSchedulers] AS [sch]
          ON [sch].[scheduler_id]=[r].[SchedulerId]
        LEFT JOIN [#CurrentRequests_SourceSessionTransactions] AS [st]
          ON [st].[session_id]=[r].[SessionId]
         AND [st].[transaction_id]=[r].[TransactionId]
        LEFT JOIN [#CurrentRequests_SourceActiveTransactions] AS [at]
          ON [at].[transaction_id]=[r].[TransactionId]
        LEFT JOIN [#CurrentRequests_SourceTempDbSessionUsage] AS [ts]
          ON [ts].[session_id]=[r].[SessionId]
        OUTER APPLY
        (
            SELECT
                  [TaskCount]=COUNT_BIG(*)
                , [WorkerCount]=COUNT_BIG(DISTINCT [t].[worker_address])
                , [ExecutionContextCount]=COUNT_BIG(DISTINCT [t].[exec_context_id])
                , [RunnableTaskCount]=SUM(CASE WHEN [t].[task_state]=N'RUNNABLE' THEN CONVERT(bigint,1) ELSE CONVERT(bigint,0) END)
                , [SuspendedTaskCount]=SUM(CASE WHEN [t].[task_state]=N'SUSPENDED' THEN CONVERT(bigint,1) ELSE CONVERT(bigint,0) END)
            FROM [#CurrentRequests_SourceTasks] AS [t]
            WHERE [t].[session_id]=[r].[SessionId]
              AND [t].[request_id]=[r].[RequestId]
        ) AS [task]
        OUTER APPLY
        (
            SELECT
                  [MaxTaskWaitMs]=MAX([w].[wait_duration_ms])
                , [WaitResource]=MAX([w].[resource_description])
            FROM [#CurrentRequests_SourceWaitingTasks] AS [w]
            LEFT JOIN [#CurrentRequests_SourceTasks] AS [t]
              ON [t].[task_address]=[w].[waiting_task_address]
            WHERE [w].[session_id]=[r].[SessionId]
              AND ([t].[request_id]=[r].[RequestId] OR [t].[request_id] IS NULL)
        ) AS [wt]
        OUTER APPLY
        (
            SELECT
                  [LogBytesUsed]=SUM([d].[database_transaction_log_bytes_used])
                , [LogBytesReserved]=SUM([d].[database_transaction_log_bytes_reserved])
            FROM [#CurrentRequests_SourceDatabaseTransactions] AS [d]
            WHERE [d].[transaction_id]=[r].[TransactionId]
        ) AS [dt]
        OUTER APPLY
        (
            SELECT [NetPages]=SUM
            (
                  [u].[user_objects_alloc_page_count]-[u].[user_objects_dealloc_page_count]
                + [u].[internal_objects_alloc_page_count]-[u].[internal_objects_dealloc_page_count]
            )
            FROM [#CurrentRequests_SourceTempDbTaskUsage] AS [u]
            WHERE [u].[session_id]=[r].[SessionId]
              AND [u].[request_id]=[r].[RequestId]
        ) AS [tt];

        INSERT [#CurrentRequests_Statements]
        SELECT
              @EvidenceSnapshotId,[r].[SessionId],[r].[RequestId],'SQL_TEXT'
            , COALESCE((SELECT [CapturedAtUtc] FROM [#CurrentRequests_SnapshotStatus] WHERE [SourceCode]='SQL_TEXT'),@EvidenceSnapshotStartedAtUtc)
            , [r].[HasStatementOffsets],[r].[IsStatementOffsetValid]
            , [r].[StatementStartOffsetBytes],[r].[StatementEndOffsetBytes]
            , [r].[StatementStartCharacter],[r].[StatementEndCharacter]
            , [r].[StatementStartLine],[r].[StatementEndLine]
            , [r].[CurrentStatementCharacterCount],[r].[CurrentStatementBytes]
            , COALESCE([r].[CurrentStatementIsTruncated],0)
            , CASE
                  WHEN @MitSqlText=0 THEN 'NOT_COLLECTED'
                  WHEN [r].[SqlTextIsEncrypted]=1 THEN 'ENCRYPTED'
                  WHEN [r].[HasStatementOffsets]=1 AND [r].[IsStatementOffsetValid]=0 THEN 'INVALID_OFFSETS'
                  WHEN [r].[CurrentStatement] IS NULL THEN 'TEXT_UNAVAILABLE'
                  WHEN [r].[CurrentStatementIsTruncated]=1 THEN 'TEXT_TRUNCATED'
                  ELSE 'AVAILABLE'
              END
            , CASE
                  WHEN @MitSqlText=0 THEN N'Der Statementtext wurde nicht angefordert.'
                  WHEN [r].[SqlTextIsEncrypted]=1 THEN N'Der SQL-Text ist verschlüsselt.'
                  WHEN [r].[HasStatementOffsets]=1 AND [r].[IsStatementOffsetValid]=0 THEN N'Die Request-Offsets sind für den gelesenen Batch ungültig.'
                  WHEN [r].[CurrentStatement] IS NULL THEN N'Für den erfassten Request war kein Statementtext verfügbar.'
              END
            , [r].[CurrentStatement]
        FROM [#CurrentRequests_Result] AS [r];

        INSERT [#CurrentRequests_Batches]
        SELECT
              @EvidenceSnapshotId,[r].[SessionId],[r].[RequestId],'SQL_TEXT'
            , COALESCE((SELECT [CapturedAtUtc] FROM [#CurrentRequests_SnapshotStatus] WHERE [SourceCode]='SQL_TEXT'),@EvidenceSnapshotStartedAtUtc)
            , [r].[SqlTextDatabaseId],[r].[SqlTextObjectId],[r].[SqlTextObjectNumber]
            , [r].[SqlTextIsEncrypted],[r].[BatchTextCharacterCount],[r].[BatchTextBytes]
            , COALESCE([r].[BatchTextIsTruncated],0)
            , CASE
                  WHEN @GesamtenSqlTextEinbeziehen=0 THEN 'NOT_COLLECTED'
                  WHEN [r].[SqlTextIsEncrypted]=1 THEN 'ENCRYPTED'
                  WHEN [r].[BatchText] IS NULL THEN 'TEXT_UNAVAILABLE'
                  WHEN [r].[BatchTextIsTruncated]=1 THEN 'TEXT_TRUNCATED'
                  ELSE 'AVAILABLE'
              END
            , CASE
                  WHEN @GesamtenSqlTextEinbeziehen=0 THEN N'Der Batchtext wurde nicht angefordert.'
                  WHEN [r].[SqlTextIsEncrypted]=1 THEN N'Der SQL-Text ist verschlüsselt.'
                  WHEN [r].[BatchText] IS NULL THEN N'Für den erfassten Request war kein Batchtext verfügbar.'
              END
            , [r].[BatchText]
        FROM [#CurrentRequests_Result] AS [r];

        INSERT [#CurrentRequests_InputBuffers]
        SELECT
              @EvidenceSnapshotId,[r].[SessionId],[r].[RequestId],'INPUT_BUFFER'
            , COALESCE((SELECT [CapturedAtUtc] FROM [#CurrentRequests_SnapshotStatus] WHERE [SourceCode]='INPUT_BUFFER'),@CollectionTimeUtc)
            , [r].[InputBufferEventType],[r].[InputBufferParameterCount]
            , [r].[InputBufferCharacterCount],[r].[InputBufferBytes]
            , COALESCE([r].[InputBufferIsTruncated],0)
            , CASE
                  WHEN @InputBufferEinbeziehen=0 THEN 'NOT_COLLECTED'
                  WHEN [ibs].[StatusCode] NOT IN ('AVAILABLE') THEN [ibs].[StatusCode]
                  WHEN [r].[InputBufferText] IS NULL THEN 'REQUEST_FINISHED'
                  WHEN [r].[InputBufferIsTruncated]=1 THEN 'TEXT_TRUNCATED'
                  ELSE 'AVAILABLE'
              END
            , CASE
                  WHEN @InputBufferEinbeziehen=0 THEN N'Der Input Buffer wurde nicht angefordert.'
                  WHEN [ibs].[StatusCode] NOT IN ('AVAILABLE') THEN [ibs].[ErrorMessage]
                  WHEN [r].[InputBufferText] IS NULL THEN N'Der Request war beim späteren Input-Buffer-Lesezeitpunkt nicht mehr verfügbar.'
              END
            , [r].[InputBufferText]
        FROM [#CurrentRequests_Result] AS [r]
        LEFT JOIN [#CurrentRequests_SnapshotStatus] AS [ibs]
          ON [ibs].[SourceCode]='INPUT_BUFFER';

        SELECT @RowCount = COUNT_BIG(*)
        FROM [#CurrentRequests_Result];

        IF @HasFullView=0 OR @ParentSnapshotIsPartial=1
        BEGIN
            SET @StatusCode='AVAILABLE_LIMITED';
            SET @IsPartial=1;
            SET @Detail=N'Mindestens eine Current-State-Quelle war nur eingeschränkt verfügbar.';
        END;
        ELSE IF @IsPartial=1
        BEGIN
            SET @StatusCode='PARTIAL_RESULT';
            SET @Detail=N'Requests wurden gelesen; mindestens eine optionale Modulauflösung war nicht vollständig möglich.';
        END;
        ELSE
        BEGIN
            SET @Detail=N'Aktive Requests aus einer frischen laufinternen Evidenzbasis gelesen.';
        END;
    END TRY
    BEGIN CATCH
        SET @ErrorNumber = ERROR_NUMBER();
        SET @ErrorMessage = ERROR_MESSAGE();
        SET @IsPartial = 1;
        SET @StatusCode =
            CASE
                WHEN @ErrorNumber IN (229, 262, 297, 300, 371, 916) THEN 'DENIED_PERMISSION'
                WHEN @ErrorNumber = 1222 THEN 'TIMEOUT'
                WHEN @ErrorNumber IN (207, 208, 4121) THEN 'UNAVAILABLE_OBJECT'
                ELSE 'ERROR_HANDLED'
            END;
    END CATCH;

    IF @PrintMeldungen = 1 AND @StatusCode <> 'AVAILABLE'
    BEGIN
        SET @MonitorPrintMessage = FORMATMESSAGE
        (
              N'WARNUNG %s: %s'
            , @StatusCode
            , COALESCE(@ErrorMessage, @Detail, N'eingeschränkte Sicht')
        );
        RAISERROR(N'%s', 10, 1, @MonitorPrintMessage) WITH NOWAIT;
    END;

    IF @JsonErzeugen = 1
    BEGIN
        DECLARE @MetaJson nvarchar(max) =
        (
            SELECT
                  @ModuleName AS [resultName]
                , 4 AS [schemaVersion]
                , @CollectionTimeUtc AS [generatedAtUtc]
                , @EvidenceSnapshotStartedAtUtc AS [evidenceSnapshotStartedAtUtc]
                , @EvidenceSnapshotId AS [evidenceSnapshotId]
                , @StatusCode AS [statusCode]
                , @IsPartial AS [isPartial]
                , @MaxZeilen AS [requestedMaxRows]
                , @RowCount AS [returnedRows]
                , @HasMoreRows AS [hasMoreRows]
                , @MitSqlText AS [statementTextIncluded]
                , @GesamtenSqlTextEinbeziehen AS [batchTextIncluded]
                , @InputBufferEinbeziehen AS [inputBufferIncluded]
                , @ModulInfoEinbeziehen AS [moduleInfoIncluded]
                , @MaxSqlTextZeichen AS [maxSqlTextCharacters]
                , @ToolHintergrundabfragenEinbeziehen AS [toolBackgroundQueriesIncluded]
            FOR JSON PATH, WITHOUT_ARRAY_WRAPPER, INCLUDE_NULL_VALUES
        );

        DECLARE @RequestsJson nvarchar(max) =
        (
            SELECT
                  [r].[SessionId] AS [sessionId]
                , [r].[RequestId] AS [requestId]
                , [r].[RequestStatus] AS [requestStatus]
                , [r].[Command] AS [command]
                , [r].[DatabaseId] AS [databaseId]
                , [r].[DatabaseName] AS [databaseName]
                , [r].[LoginName] AS [loginName]
                , [r].[HostName] AS [hostName]
                , [r].[ProgramName] AS [programName]
                , [r].[IsToolBackgroundQuery] AS [isToolBackgroundQuery]
                , [r].[ToolBackgroundRuleCode] AS [toolBackgroundRuleCode]
                , [r].[ToolBackgroundCategory] AS [toolBackgroundCategory]
                , [r].[ToolBackgroundDetection] AS [toolBackgroundDetection]
                , [r].[ToolBackgroundConfidence] AS [toolBackgroundConfidence]
                , [r].[StartTime] AS [startTime]
                , [r].[ElapsedMs] AS [elapsedMs]
                , [r].[CpuMs] AS [cpuMs]
                , [r].[LogicalReads] AS [logicalReads]
                , [r].[Writes] AS [writes]
                , [r].[BlockingSessionId] AS [blockingSessionId]
                , [r].[WaitType] AS [waitType]
                , [wi].[WaitGroup] AS [waitGroup]
                , [wi].[Severity] AS [waitSeverity]
                , [r].[WaitTimeMs] AS [waitTimeMs]
                , [r].[RequestedMemoryMb] AS [requestedMemoryMb]
                , [r].[GrantedMemoryMb] AS [grantedMemoryMb]
                , [r].[UsedMemoryMb] AS [usedMemoryMb]
                , [r].[Dop] AS [dop]
                , [r].[ParallelWorkerCount] AS [parallelWorkerCount]
                , [r].[SchedulerId] AS [schedulerId]
                , [r].[TaskAddress] AS [taskAddress]
                , [r].[NestLevel] AS [nestLevel]
                , [r].[OpenTransactionCount] AS [openTransactionCount]
                , [r].[OpenResultsetCount] AS [openResultsetCount]
                , [r].[TransactionId] AS [transactionId]
                , [r].[ConnectionId] AS [connectionId]
                , [r].[WorkloadGroupId] AS [workloadGroupId]
                , [r].[WorkloadGroupName] AS [workloadGroupName]
                , [r].[ResourcePoolId] AS [resourcePoolId]
                , [r].[ResourcePoolName] AS [resourcePoolName]
                , [r].[StatementSqlHandle] AS [statementSqlHandle]
                , [r].[StatementContextId] AS [statementContextId]
                , [r].[IsResumable] AS [isResumable]
                , [r].[ExecutingManagedCode] AS [executingManagedCode]
                , [r].[ContextInfo] AS [contextInfo]
                , [r].[ModuleFullName] AS [moduleFullName]
                , [r].[ModuleTypeDescription] AS [moduleTypeDescription]
                , [r].[ExecutionContextType] AS [executionContextType]
                , [r].[QueryHash] AS [queryHash]
                , [r].[QueryPlanHash] AS [queryPlanHash]
                , [r].[SqlHandle] AS [sqlHandle]
                , [r].[PlanHandle] AS [planHandle]
            FROM [#CurrentRequests_Result] AS [r]
            CROSS APPLY [monitor].[TVF_WaitTypeInfo]([r].[WaitType]) AS [wi]
            ORDER BY [r].[SessionId], [r].[RequestId]
            FOR JSON PATH, INCLUDE_NULL_VALUES
        );

        DECLARE @RequestContextJson nvarchar(max) =
        (
            SELECT *
            FROM [#CurrentRequests_RequestContext]
            ORDER BY [SessionId],[RequestId]
            FOR JSON PATH, INCLUDE_NULL_VALUES
        );

        DECLARE @SnapshotStatusJson nvarchar(max) =
        (
            SELECT *
            FROM [#CurrentRequests_SnapshotStatus]
            ORDER BY [SourceOrdinal]
            FOR JSON PATH, INCLUDE_NULL_VALUES
        );

        DECLARE @StatementsJson nvarchar(max) =
        (
            SELECT *
            FROM [#CurrentRequests_Statements]
            ORDER BY [SessionId],[RequestId]
            FOR JSON PATH, INCLUDE_NULL_VALUES
        );

        DECLARE @BatchesJson nvarchar(max) =
        (
            SELECT *
            FROM [#CurrentRequests_Batches]
            ORDER BY [SessionId],[RequestId]
            FOR JSON PATH, INCLUDE_NULL_VALUES
        );

        DECLARE @InputBuffersJson nvarchar(max) =
        (
            SELECT *
            FROM [#CurrentRequests_InputBuffers]
            ORDER BY [SessionId],[RequestId]
            FOR JSON PATH, INCLUDE_NULL_VALUES
        );

        DECLARE @WarningsJson nvarchar(max) =
        (
            SELECT
                  [w].[SessionId] AS [sessionId]
                , [w].[RequestId] AS [requestId]
                , [w].[DatabaseName] AS [databaseName]
                , [w].[Code] AS [code]
                , [w].[Message] AS [message]
            FROM [#CurrentRequests_Warnings] AS [w]
            ORDER BY [w].[WarningId]
            FOR JSON PATH, INCLUDE_NULL_VALUES
        );

        SET @Json = CONCAT
        (
              N'{"meta":', COALESCE(@MetaJson, N'{}')
            , N',"requests":', COALESCE(@RequestsJson, N'[]')
            , N',"requestContext":', COALESCE(@RequestContextJson,N'[]')
            , N',"snapshotStatus":', COALESCE(@SnapshotStatusJson,N'[]')
            , N',"statements":', COALESCE(@StatementsJson, N'[]')
            , N',"batches":', COALESCE(@BatchesJson, N'[]')
            , N',"inputBuffers":', COALESCE(@InputBuffersJson, N'[]')
            , N',"warnings":', COALESCE(@WarningsJson, N'[]')
            , N'}'
        );
    END;

    IF @ResultSetArtNormalisiert = 'RAW'
    BEGIN
        SELECT
              @ModuleName AS [ModuleName]
            , @CollectionTimeUtc AS [CollectionTimeUtc]
            , @EvidenceSnapshotStartedAtUtc AS [EvidenceSnapshotStartedAtUtc]
            , @EvidenceSnapshotId AS [EvidenceSnapshotId]
            , @StatusCode AS [StatusCode]
            , @IsPartial AS [IsPartial]
            , @RowCount AS [RowCount]
            , @MaxZeilen AS [RequestedMaxRows]
            , @HasMoreRows AS [HasMoreRows]
            , @RequiredPermission AS [RequiredPermission]
            , @ErrorNumber AS [ErrorNumber]
            , @ErrorMessage AS [ErrorMessage]
            , @Detail AS [Detail];

        SELECT
              [r].*
            , [wi].[WaitGroup]
            , [wi].[Severity] AS [WaitSeverity]
            , [wi].[IsGenerallyBenign]
            , [wi].[Meaning] AS [WaitMeaning]
            , [wi].[TypicalOccurrence] AS [WaitTypicalOccurrence]
            , [wi].[HighWaitImpact]
            , [wi].[RecommendedChecks]
            , [wi].[HelpUrl] AS [WaitHelpUrl]
            , [wi].[InterpretationScope]
            , [wi].[CatalogMatchType]
            , [lwi].[WaitGroup] AS [LastWaitGroup]
            , [lwi].[Meaning] AS [LastWaitMeaning]
        FROM [#CurrentRequests_Result] AS [r]
        CROSS APPLY [monitor].[TVF_WaitTypeInfo]([r].[WaitType]) AS [wi]
        CROSS APPLY [monitor].[TVF_WaitTypeInfo]([r].[LastWaitType]) AS [lwi]
        ORDER BY
              CASE WHEN @Sortierung = 'CPU' THEN [r].[CpuMs] END DESC
            , CASE WHEN @Sortierung = 'READS' THEN [r].[LogicalReads] END DESC
            , CASE WHEN @Sortierung = 'DAUER' THEN [r].[ElapsedMs] END DESC
            , CASE
                  WHEN @Sortierung = 'RELEVANZ'
                      THEN CASE
                               WHEN [r].[BlockingSessionId] IS NOT NULL THEN 3
                               WHEN [r].[WaitType] IS NOT NULL THEN 2
                               ELSE 1
                           END
              END DESC
            , [r].[SessionId]
            , [r].[RequestId];

        SELECT * FROM [#CurrentRequests_RequestContext] ORDER BY [SessionId],[RequestId];
        SELECT * FROM [#CurrentRequests_SnapshotStatus] ORDER BY [SourceOrdinal];
        SELECT * FROM [#CurrentRequests_Statements] ORDER BY [SessionId],[RequestId];
        SELECT * FROM [#CurrentRequests_Batches] ORDER BY [SessionId],[RequestId];
        SELECT * FROM [#CurrentRequests_InputBuffers] ORDER BY [SessionId],[RequestId];

        SELECT
              [w].[WarningId]
            , [w].[SessionId]
            , [w].[RequestId]
            , [w].[DatabaseName]
            , [w].[Code]
            , [w].[Message]
        FROM [#CurrentRequests_Warnings] AS [w]
        ORDER BY [w].[WarningId];
    END
    ELSE IF @ResultSetArtNormalisiert = 'CONSOLE'
    BEGIN
        SELECT
              N'Modulstatus' AS [Ergebnis]
            , @ModuleName AS [Modul]
            , @StatusCode AS [Status]
            , @RowCount AS [Zeilen]
            , @Detail AS [Hinweis]
            , @ErrorMessage AS [Fehler];

        SELECT
              N'Aktiver Request' AS [Ergebnis]
            , [r].[SessionId] AS [Session]
            , [r].[RequestId] AS [Request]
            , COALESCE([r].[ModuleFullName], N'Ad-hoc/Prepared Batch') AS [Ausfuehrung]
            , [r].[ModuleTypeDescription] AS [Modultyp]
            , [r].[LoginName] AS [Login]
            , [r].[HostName] AS [Host]
            , [r].[ProgramName] AS [Programm]
            , [r].[DatabaseName] AS [Datenbank]
            , [r].[Command] AS [Befehl]
            , [r].[RequestStatus] AS [Status]
            , CONCAT(CONVERT(decimal(19,2), [r].[ElapsedMs] / 1000.0), N' s') AS [Laufzeit]
            , [r].[CpuMs] AS [CPU_ms]
            , [r].[LogicalReads] AS [Logical_Reads]
            , [r].[Writes] AS [Writes]
            , [r].[SessionId] AS [Session_Wait]
            , [r].[WaitType] AS [Wait]
            , [r].[WaitTimeMs] AS [Wait_ms]
            , [r].[BlockingSessionId] AS [Blockiert_durch]
            , [r].[RequestedMemoryMb] AS [Memory_angefordert_MB]
            , [r].[GrantedMemoryMb] AS [Memory_gewaehrt_MB]
            , [r].[UsedMemoryMb] AS [Memory_verwendet_MB]
            , CASE
                  WHEN [r].[StatementStartLine] IS NULL THEN NULL
                  WHEN [r].[StatementEndLine] = [r].[StatementStartLine]
                      THEN CONVERT(varchar(20), [r].[StatementStartLine])
                  ELSE CONCAT([r].[StatementStartLine], N'-', [r].[StatementEndLine])
              END AS [Statement_Zeile]
            , CONCAT
              (
                    COALESCE(CONVERT(varchar(20), [r].[StatementStartOffsetBytes]), N'?')
                  , N'-'
                  , CASE
                        WHEN [r].[StatementEndOffsetBytes] = -1 THEN N'Batch-Ende'
                        ELSE COALESCE(CONVERT(varchar(20), [r].[StatementEndOffsetBytes]), N'?')
                    END
              ) AS [Statement_Offset_Bytes]
            , [r].[CurrentStatementIsTruncated] AS [Statement_gekuerzt]
            , [r].[CurrentStatement] AS [Aktuelles_Statement]
        FROM [#CurrentRequests_Result] AS [r]
        ORDER BY
              CASE
                  WHEN @Sortierung = 'RELEVANZ'
                      THEN CASE
                               WHEN [r].[BlockingSessionId] IS NOT NULL THEN 3
                               WHEN [r].[WaitType] IS NOT NULL THEN 2
                               ELSE 1
                           END
              END DESC
            , CASE WHEN @Sortierung = 'CPU' THEN [r].[CpuMs] END DESC
            , CASE WHEN @Sortierung = 'READS' THEN [r].[LogicalReads] END DESC
            , CASE WHEN @Sortierung = 'DAUER' THEN [r].[ElapsedMs] END DESC
            , [r].[SessionId]
            , [r].[RequestId];

        SELECT
              N'SQL-Kontext' AS [Ergebnis]
            , [r].[SessionId] AS [Session]
            , [r].[RequestId] AS [Request]
            , [r].[ExecutionContextType] AS [Kontextart]
            , [r].[ModuleFullName] AS [Modul]
            , [r].[ModuleTypeDescription] AS [Modultyp]
            , [r].[NestLevel] AS [Verschachtelungsebene]
            , [r].[ConnectionId] AS [ConnectionId]
            , [r].[TransactionId] AS [TransactionId]
            , [r].[SchedulerId] AS [SchedulerId]
            , [r].[TaskAddress] AS [TaskAddress]
            , [r].[WorkloadGroupId] AS [WorkloadGroupId]
            , [r].[WorkloadGroupName] AS [WorkloadGroup]
            , [r].[ResourcePoolId] AS [ResourcePoolId]
            , [r].[ResourcePoolName] AS [ResourcePool]
            , [r].[StatementSqlHandle] AS [StatementSqlHandle]
            , [r].[StatementContextId] AS [StatementContextId]
            , [r].[IsResumable] AS [Ist_fortsetzbar]
            , [r].[ExecutingManagedCode] AS [Fuehrt_CLR_aus]
            , [r].[ContextInfo] AS [ContextInfo]
            , [r].[SqlTextDatabaseId] AS [SQLText_DatabaseId]
            , [r].[SqlTextObjectId] AS [SQLText_ObjectId]
            , [r].[SqlTextObjectNumber] AS [SQLText_ObjectNumber]
            , [r].[SqlTextIsEncrypted] AS [SQLText_verschluesselt]
            , [r].[HasStatementOffsets] AS [Offsets_vorhanden]
            , [r].[IsStatementOffsetValid] AS [Offsets_gueltig]
            , [r].[StatementStartOffsetBytes] AS [Statement_Start_Byte]
            , [r].[StatementEndOffsetBytes] AS [Statement_Ende_Byte]
            , [r].[StatementStartCharacter] AS [Statement_Start_Zeichen]
            , [r].[StatementEndCharacter] AS [Statement_Ende_Zeichen]
            , [r].[StatementStartLine] AS [Statement_Start_Zeile]
            , [r].[StatementEndLine] AS [Statement_Ende_Zeile]
            , [r].[CurrentStatementCharacterCount] AS [Statement_Zeichen]
            , [r].[BatchTextCharacterCount] AS [Batch_Zeichen]
            , [r].[QueryHash] AS [QueryHash]
            , [r].[QueryPlanHash] AS [QueryPlanHash]
            , [r].[SqlHandle] AS [SqlHandle]
            , [r].[PlanHandle] AS [PlanHandle]
        FROM [#CurrentRequests_Result] AS [r]
        ORDER BY [r].[SessionId], [r].[RequestId];

        IF @GesamtenSqlTextEinbeziehen = 1
        BEGIN
            SELECT
                  N'Gesamter SQL-Batch/Modultext' AS [Ergebnis]
                , [r].[SessionId] AS [Session]
                , [r].[RequestId] AS [Request]
                , COALESCE([r].[ModuleFullName], N'Ad-hoc/Prepared Batch') AS [Ausfuehrung]
                , [r].[BatchTextCharacterCount] AS [Zeichen_gesamt]
                , [r].[BatchTextIsTruncated] AS [Text_gekuerzt]
                , [r].[BatchText] AS [Gesamter_SQL_Text]
            FROM [#CurrentRequests_Result] AS [r]
            WHERE [r].[BatchText] IS NOT NULL
            ORDER BY [r].[SessionId], [r].[RequestId];
        END;

        IF @InputBufferEinbeziehen = 1
        BEGIN
            SELECT
                  N'Input Buffer' AS [Ergebnis]
                , [r].[SessionId] AS [Session]
                , [r].[RequestId] AS [Request]
                , [r].[InputBufferEventType] AS [Ereignistyp]
                , [r].[InputBufferParameterCount] AS [Parameteranzahl]
                , [r].[InputBufferCharacterCount] AS [Zeichen_gesamt]
                , [r].[InputBufferIsTruncated] AS [Text_gekuerzt]
                , [r].[InputBufferText] AS [Uebergebener_Befehl]
            FROM [#CurrentRequests_Result] AS [r]
            WHERE [r].[InputBufferText] IS NOT NULL
            ORDER BY [r].[SessionId], [r].[RequestId];
        END;

        IF EXISTS (SELECT 1 FROM [#CurrentRequests_Warnings])
        BEGIN
            SELECT
                  N'Warnung' AS [Ergebnis]
                , [w].[SessionId] AS [Session]
                , [w].[RequestId] AS [Request]
                , [w].[DatabaseName] AS [Datenbank]
                , [w].[Code] AS [Code]
                , [w].[Message] AS [Hinweis]
            FROM [#CurrentRequests_Warnings] AS [w]
            ORDER BY [w].[WarningId];
        END;
    END;
    IF @ConsoleResultRequested = 1
    BEGIN
        EXEC [monitor].[InternalEmitConsoleResult]
              @SourceTable=N'#CurrentRequests_Result'
            , @ResultLabel=N'Aktuelle Requests'
            , @EmptyMessage=N'Keine aktiven Requests';
    END;
    IF @TableResultRequested = 1
    BEGIN
        DECLARE @ExportResultName sysname;
        DECLARE @ExportTargetTable sysname;
        DECLARE @ExportSourceTable sysname;
        DECLARE [CurrentRequestsExportCursor] CURSOR LOCAL FAST_FORWARD FOR
            SELECT [ResultName],[TargetTable]
            FROM [#CurrentRequests_ResultTableMap]
            ORDER BY [ResultName];

        OPEN [CurrentRequestsExportCursor];
        FETCH NEXT FROM [CurrentRequestsExportCursor]
            INTO @ExportResultName,@ExportTargetTable;
        WHILE @@FETCH_STATUS=0
        BEGIN
            SET @ExportSourceTable=
                CASE @ExportResultName
                    WHEN N'requests' THEN N'#CurrentRequests_Result'
                    WHEN N'requestContext' THEN N'#CurrentRequests_RequestContext'
                    WHEN N'snapshotStatus' THEN N'#CurrentRequests_SnapshotStatus'
                    WHEN N'statements' THEN N'#CurrentRequests_Statements'
                    WHEN N'batches' THEN N'#CurrentRequests_Batches'
                    WHEN N'inputBuffers' THEN N'#CurrentRequests_InputBuffers'
                    WHEN N'warnings' THEN N'#CurrentRequests_Warnings'
                END;

            EXEC [monitor].[InternalWriteResultTable]
                  @SourceTable=@ExportSourceTable
                , @TargetTable=@ExportTargetTable
                , @ThrowOnError=1;

            FETCH NEXT FROM [CurrentRequestsExportCursor]
                INTO @ExportResultName,@ExportTargetTable;
        END;
        CLOSE [CurrentRequestsExportCursor];
        DEALLOCATE [CurrentRequestsExportCursor];
    END;
END;
GO
-- END SOURCE: Code/02_CurrentState/020_USP_CurrentRequests.sql

-- BEGIN SOURCE: Code/02_CurrentState/030_USP_CurrentBlocking.sql
/*
===============================================================================
Objekt       : monitor.USP_CurrentBlocking
Version      : 3.0.0
Stand        : 2026-07-23
Typ          : Stored Procedure
Zweck        : Ermittelt aktuelle Blocking-Ketten, löst deren Ressourcen
               begrenzt auf Datenbank-, Objekt-, Index-, Partitions- und
               Seitenkontext auf und liefert optional die zugehörigen Locks.
SQL-Version  : SQL Server 2019 oder neuer.
Parameter    : @SessionIds = NULL oder z. B. N'57|61'; @MaxZeilen > 0
               begrenzt, NULL/0 ist unbegrenzt. @ResultSetArt akzeptiert
               RAW, CONSOLE, TABLE oder NONE case-insensitiv. JSON wird als Envelope
               mit blockingChains, locks und warnings geliefert.
Berechtigung : VIEW SERVER STATE bis SQL Server 2019 beziehungsweise
               VIEW SERVER PERFORMANCE STATE ab SQL Server 2022. Lockdetails
               benötigen zusätzlich die freigegebene Analyseklasse LOCKS_DEEP.
Eigenlast    : Standard gering. Ressourcen werden dedupliziert und nur bis
               @MaxObjektAufloesungen einzeln mit LOCK_TIMEOUT 0 aufgelöst.
               sys.dm_tran_locks wird nur bei expliziter Anforderung und nur
               für beteiligte Sessions gelesen.
===============================================================================
*/
CREATE OR ALTER PROCEDURE [monitor].[USP_CurrentBlocking]
      @SessionIds                 nvarchar(max)  = NULL
    , @MinWaitMs                  bigint         = 0
    , @SystemSessionsEinbeziehen  bit            = 0
    , @ToolHintergrundabfragenEinbeziehen bit     = 0
    , @MitSqlText                 bit            = 1
    , @MaxSqlTextZeichen          int            = 3000
    , @BlockingObjektTiefe        varchar(16)    = 'STANDARD'
    , @MaxObjektAufloesungen      int            = 100
    , @MitLockDetails             bit            = 0
    , @HighImpactConfirmed        bit            = 0
    , @MaxZeilen                  int            = 1000
    , @ResultSetArt               varchar(16)     = 'CONSOLE'
    , @ResultTablesJson               nvarchar(max) = NULL
    , @JsonErzeugen               bit             = 0
    , @Json                       nvarchar(max)   = NULL OUTPUT
    , @PrintMeldungen             bit             = 1
    , @Hilfe                      bit             = 0
    , @ParentCurrentStateSnapshotId uniqueidentifier = NULL
AS
BEGIN
    SET NOCOUNT ON;
    SET @Json = NULL;

    DECLARE @ResultSetArtNormalisiert varchar(16) = UPPER(LTRIM(RTRIM(COALESCE(@ResultSetArt, ''))));
    DECLARE @BlockingObjektTiefeNormalisiert varchar(16) =
        UPPER(LTRIM(RTRIM(COALESCE(@BlockingObjektTiefe, ''))));
    DECLARE @TableResultRequested bit = CASE WHEN @ResultSetArtNormalisiert = 'TABLE' THEN 1 ELSE 0 END;
    DECLARE @ConsoleResultRequested bit = CASE WHEN @ResultSetArtNormalisiert = 'CONSOLE' THEN 1 ELSE 0 END;
    DECLARE @TableTarget sysname=NULL;
    IF @TableResultRequested=0 AND NULLIF(LTRIM(RTRIM(COALESCE(@ResultTablesJson,N''))),N'') IS NOT NULL THROW 51011,N'@ResultTablesJson ist ausschließlich mit @ResultSetArt=TABLE zulässig.',1;
    IF @TableResultRequested=1 EXEC [monitor].[InternalPrepareSingleResultTable] @ResultTablesJson=@ResultTablesJson,@ResultName=N'blockingChains',@TargetTable=@TableTarget OUTPUT,@ThrowOnError=1;
    IF @TableResultRequested = 1 OR @ConsoleResultRequested = 1 SET @ResultSetArtNormalisiert = 'NONE';
    DECLARE @EffectiveMaxZeilen bigint =
        CASE WHEN @MaxZeilen IS NULL OR @MaxZeilen = 0 THEN CONVERT(bigint, 9223372036854775807)
             WHEN @MaxZeilen > 0 THEN CONVERT(bigint, @MaxZeilen)
             ELSE CONVERT(bigint, 0) END;
    DECLARE @CandidateRows bigint =
        CASE WHEN @MaxZeilen IS NULL OR @MaxZeilen = 0 THEN CONVERT(bigint, 9223372036854775807)
             WHEN @MaxZeilen < 2147483647 THEN CONVERT(bigint, @MaxZeilen) + 1
             ELSE CONVERT(bigint, @MaxZeilen) END;

    IF @Hilfe = 1
    BEGIN
        PRINT N'monitor.USP_CurrentBlocking';
        PRINT N'@SessionIds: exakte Session-IDs als Pipe-Liste, z. B. N''57|61''; NULL = keine Einschränkung.';
        PRINT N'@ToolHintergrundabfragenEinbeziehen=0 blendet Ketten mit erkanntem Tool-Hintergrundrequest als Blatt standardmäßig aus; 1 zeigt sie. Ein Tool-Blocker einer normalen Abfrage bleibt immer in deren Kette sichtbar.';
        PRINT N'@BlockingObjektTiefe: NONE, STANDARD oder DEEP. DEEP aktiviert zusätzlich Lockdetails und benötigt LOCKS_DEEP plus @HighImpactConfirmed=1.';
        PRINT N'@MaxObjektAufloesungen begrenzt Katalog- und Page-Auflösungen auf 1 bis 1000 Kandidaten.';
        PRINT N'Jede Namens-/Objektanreicherung läuft einzeln mit LOCK_TIMEOUT 0; ein Timeout betrifft nur diesen Kandidaten.';
        PRINT N'@MitLockDetails=1 aktiviert die gruppengeschützte LOCKS_DEEP-Auswertung.';
        PRINT N'@MaxZeilen: positive Werte begrenzen; NULL/0 = unbegrenzt; negative Werte sind ungültig.';
        PRINT N'@ResultSetArt: CONSOLE (Default), RAW, TABLE oder NONE; Groß-/Kleinschreibung wird ignoriert.';
        PRINT N'@JsonErzeugen=1 liefert blockingChains, locks und warnings in @Json OUTPUT.';
        RETURN;
    END;

    DECLARE @CollectionTimeUtc datetime2(3) = SYSUTCDATETIME();
    DECLARE @StatusCode varchar(40) = 'AVAILABLE';
    DECLARE @IsPartial bit = 0;
    DECLARE @ErrorNumber int = NULL;
    DECLARE @ErrorMessage nvarchar(2048) = NULL;
    DECLARE @RequiredPermission nvarchar(256) =
        CASE WHEN TRY_CONVERT(int, SERVERPROPERTY(N'ProductMajorVersion')) >= 16
             THEN N'VIEW SERVER PERFORMANCE STATE' ELSE N'VIEW SERVER STATE' END;
    DECLARE @LockStatusCode varchar(40) = 'SKIPPED';
    DECLARE @ObjectResolutionStatusCode varchar(40) =
        CASE WHEN @BlockingObjektTiefeNormalisiert <> 'NONE' THEN 'AVAILABLE' ELSE 'SKIPPED' END;
    DECLARE @MainCandidateCount bigint = 0;
    DECLARE @LockCandidateCount bigint = 0;
    DECLARE @ObjectResolutionCandidateCount bigint = 0;
    DECLARE @ObjectResolutionTotalCount bigint = 0;
    DECLARE @ObjectResolutionHasMoreRows bit = 0;
    DECLARE @ObjectResolutionResolvedCount bigint = 0;
    DECLARE @ObjectResolutionPartialCount bigint = 0;
    DECLARE @ObjectResolutionRawOnlyCount bigint = 0;
    DECLARE @ObjectResolutionTimeoutCount bigint = 0;
    DECLARE @ObjectResolutionDeniedCount bigint = 0;
    DECLARE @ObjectResolutionErrorCount bigint = 0;
    DECLARE @ObjectResolutionSkippedLimitCount bigint = 0;
    DECLARE @HasMoreRows bit = 0;
    DECLARE @Message nvarchar(2048);
    DECLARE @EvidenceSnapshotId uniqueidentifier=COALESCE(@ParentCurrentStateSnapshotId,NEWID());
    DECLARE @EvidenceSnapshotStartedAtUtc datetime2(3)=@CollectionTimeUtc;

    CREATE TABLE [#CurrentBlocking_SessionFilter]
    (
        [SessionId] smallint NOT NULL PRIMARY KEY
    );

    CREATE TABLE [#CurrentBlocking_Edges]
    (
          [BlockedSessionId]  smallint      NOT NULL
        , [BlockingSessionId] smallint      NOT NULL
        , [WaitType]          nvarchar(120) NULL
        , [WaitTimeMs]        bigint        NULL
        , [WaitResource]      nvarchar(3072) NULL
        , [SourceCode]        varchar(24)   NOT NULL
        , PRIMARY KEY ([BlockedSessionId], [BlockingSessionId])
    );

    CREATE TABLE [#CurrentBlocking_BlockingChains]
    (
          [LeafSessionId]         smallint       NOT NULL
        , [BlockedSessionId]      smallint       NOT NULL
        , [BlockingSessionId]     smallint       NOT NULL
        , [RootBlockingSessionId] smallint       NULL
        , [BlockingOwnerType]     varchar(40)    NULL
        , [BlockingOwnerDescription] nvarchar(512) NULL
        , [BlockingChain]          nvarchar(4000) NULL
        , [ChainDepth]            int            NOT NULL
        , [IsCycle]               bit            NOT NULL
        , [WaitType]              nvarchar(120)  NULL
        , [WaitTimeMs]            bigint         NULL
        , [WaitResource]          nvarchar(3072) NULL
        , [BlockingResourceType]             nvarchar(60)   NULL
        , [BlockingResourceDatabaseId]       int            NULL
        , [BlockingResourceDatabaseName]     sysname        NULL
        , [BlockingResourceSchemaName]       sysname        NULL
        , [BlockingResourceObjectId]         int            NULL
        , [BlockingResourceObjectName]       sysname        NULL
        , [BlockingResourceIndexId]          int            NULL
        , [BlockingResourceIndexName]        sysname        NULL
        , [BlockingResourcePartitionId]      bigint         NULL
        , [BlockingResourcePartitionNumber]  int            NULL
        , [BlockingResourceFileId]           int            NULL
        , [BlockingResourcePageId]           bigint         NULL
        , [BlockingResourceRowId]            int            NULL
        , [BlockingResourceMetadataSubtype]  nvarchar(60)   NULL
        , [BlockingResourceMetadataName]     sysname        NULL
        , [BlockingResourcePageTypeDesc]     nvarchar(60)   NULL
        , [BlockingResourceName]             nvarchar(1024) NULL
        , [BlockingResourceResolutionStatus] varchar(40)    NULL
        , [BlockedLoginName]      nvarchar(128)  NULL
        , [BlockedHostName]       nvarchar(128)  NULL
        , [BlockedProgramName]    nvarchar(128)  NULL
        , [BlockedIsToolBackgroundQuery] bit      NOT NULL
        , [BlockedToolBackgroundRuleCode] varchar(64) NULL
        , [BlockedToolBackgroundCategory] varchar(40) NULL
        , [BlockedToolBackgroundDetection] varchar(40) NULL
        , [BlockedToolBackgroundConfidence] varchar(16) NULL
        , [BlockerLoginName]      nvarchar(128)  NULL
        , [BlockerHostName]       nvarchar(128)  NULL
        , [BlockerProgramName]    nvarchar(128)  NULL
        , [RootBlockerLoginName]  nvarchar(128)  NULL
        , [RootBlockerHostName]   nvarchar(128)  NULL
        , [RootBlockerProgramName] nvarchar(128) NULL
        , [RootBlockerSessionStatus] nvarchar(30) NULL
        , [RootBlockerRequestStatus] nvarchar(30) NULL
        , [RootBlockerOpenTransactionCount] int NULL
        , [RootBlockerLastRequestStartTime] datetime NULL
        , [RootBlockerLastRequestEndTime] datetime NULL
        , [RootIsToolBackgroundQuery] bit NOT NULL
        , [RootToolBackgroundRuleCode] varchar(64) NULL
        , [RootToolBackgroundCategory] varchar(40) NULL
        , [RootToolBackgroundDetection] varchar(40) NULL
        , [RootToolBackgroundConfidence] varchar(16) NULL
        , [BlockedStatementCharacters] bigint NULL
        , [BlockedStatementBytes] bigint NULL
        , [BlockedStatementIsTruncated] bit NOT NULL DEFAULT(0)
        , [BlockedStatement]      nvarchar(max)  NULL
        , [BlockerStatementCharacters] bigint NULL
        , [BlockerStatementBytes] bigint NULL
        , [BlockerStatementIsTruncated] bit NOT NULL DEFAULT(0)
        , [BlockerStatement]      nvarchar(max)  NULL
        , [RootBlockerStatementSource] varchar(32) NULL
        , [RootBlockerStatementCharacters] bigint NULL
        , [RootBlockerStatementBytes] bigint NULL
        , [RootBlockerStatementIsTruncated] bit NOT NULL DEFAULT(0)
        , [RootBlockerStatement]  nvarchar(max)  NULL
    );

    CREATE TABLE [#CurrentBlocking_RetainedSessions]
    (
        [SessionId] smallint NOT NULL PRIMARY KEY
    );

    CREATE TABLE [#CurrentBlocking_Locks]
    (
          [SessionId]             smallint       NULL
        , [ResourceType]          nvarchar(60)   NULL
        , [ResourceDatabaseId]    int            NULL
        , [ResourceDatabaseName]  sysname        NULL
        , [ResourceDescription]   nvarchar(256)  NULL
        , [ResourceSubtype]       nvarchar(60)   NULL
        , [ResourceAssociatedEntityId] bigint    NULL
        , [ResourceLockPartition] int            NULL
        , [RequestMode]           nvarchar(60)   NULL
        , [RequestStatus]         nvarchar(60)   NULL
        , [RequestOwnerType]      nvarchar(60)   NULL
        , [RequestReferenceCount] smallint       NULL
        , [LockOwnerAddress]      varbinary(8)   NULL
        , [ResolvedResourceType]  nvarchar(60)   NULL
        , [ResolvedSchemaName]    sysname        NULL
        , [ResolvedObjectId]      int            NULL
        , [ResolvedObjectName]    sysname        NULL
        , [ResolvedIndexId]       int            NULL
        , [ResolvedIndexName]     sysname        NULL
        , [ResolvedPartitionId]   bigint         NULL
        , [ResolvedPartitionNumber] int          NULL
        , [ResolvedResourceName]  nvarchar(1024) NULL
        , [ResourceResolutionStatus] varchar(40) NULL
    );

    CREATE TABLE [#CurrentBlocking_ResourceResolution]
    (
          [CandidateId]       int IDENTITY(1,1) NOT NULL PRIMARY KEY
        , [SourceCode]        varchar(24)       NOT NULL
        , [WaitResource]      nvarchar(3072)    NULL
        , [ResourceType]      nvarchar(60)      NULL
        , [FormatCode]        varchar(40)       NOT NULL
        , [DatabaseId]        int               NULL
        , [DatabaseName]      sysname           NULL
        , [EntityId]          bigint            NULL
        , [SubEntityId]       bigint            NULL
        , [FileId]            int               NULL
        , [FileName]          sysname           NULL
        , [PageId]            bigint            NULL
        , [RowId]             int               NULL
        , [MetadataSubtype]   nvarchar(60)      NULL
        , [MetadataName]      sysname           NULL
        , [ResourceQualifier] nvarchar(512)     NULL
        , [SchemaName]        sysname           NULL
        , [ObjectId]          int               NULL
        , [ObjectName]        sysname           NULL
        , [IndexId]           int               NULL
        , [IndexName]         sysname           NULL
        , [PartitionId]       bigint            NULL
        , [PartitionNumber]   int               NULL
        , [PageTypeDesc]      nvarchar(60)      NULL
        , [ResourceName]      nvarchar(1024)    NULL
        , [ResolutionStatus]  varchar(40)       NOT NULL
    );

    CREATE TABLE [#CurrentBlocking_Warnings]
    (
          [ScopeName]    nvarchar(128)  NULL
        , [StatusCode]   varchar(40)    NOT NULL
        , [ErrorNumber]  int            NULL
        , [ErrorMessage] nvarchar(2048) NULL
    );
    CREATE TABLE [#CurrentBlocking_SourceSessions]
    (
          [session_id] smallint NOT NULL PRIMARY KEY
        , [is_user_process] bit NOT NULL
        , [status] nvarchar(30) NOT NULL
        , [login_name] nvarchar(128) NOT NULL
        , [host_name] nvarchar(128) NULL
        , [program_name] nvarchar(128) NULL
        , [open_transaction_count] int NOT NULL
        , [last_request_start_time] datetime NOT NULL
        , [last_request_end_time] datetime NULL
    );
    CREATE TABLE [#CurrentBlocking_SourceRequests]
    (
          [session_id] smallint NOT NULL
        , [request_id] int NOT NULL
        , [status] nvarchar(30) NOT NULL
        , [blocking_session_id] smallint NULL
        , [wait_type] nvarchar(60) NULL
        , [wait_time] int NOT NULL
        , [wait_resource] nvarchar(256) NOT NULL
        , [sql_handle] varbinary(64) NULL
        , [statement_start_offset] int NULL
        , [statement_end_offset] int NULL
        , PRIMARY KEY([session_id],[request_id])
    );
    CREATE TABLE [#CurrentBlocking_SourceWaitingTasks]
    (
          [session_id] smallint NULL
        , [wait_duration_ms] bigint NOT NULL
        , [wait_type] nvarchar(60) NOT NULL
        , [blocking_session_id] smallint NULL
        , [resource_description] nvarchar(3072) NULL
    );
    CREATE TABLE [#CurrentBlocking_SourceConnections]
    (
          [session_id] int NULL
        , [connection_id] uniqueidentifier NOT NULL PRIMARY KEY
        , [most_recent_sql_handle] varbinary(64) NULL
        , [connect_time] datetime NOT NULL
    );
    CREATE INDEX [IX_CurrentBlocking_SourceConnections_Session]
        ON [#CurrentBlocking_SourceConnections]([session_id]);
    CREATE TABLE [#CurrentBlocking_SourceSqlText]
    (
          [SqlHandle] varbinary(64) NOT NULL PRIMARY KEY
        , [Text] nvarchar(max) NULL
    );

    IF @SessionIds IS NOT NULL
    BEGIN
        IF EXISTS
        (
            SELECT 1
            FROM [monitor].[TVF_ParseBigintList](@SessionIds)
            WHERE [IsValid] = 0 OR [NumberValue] NOT BETWEEN 0 AND 32767
        )
        OR EXISTS
        (
            SELECT [NumberValue]
            FROM [monitor].[TVF_ParseBigintList](@SessionIds)
            WHERE [IsValid] = 1
            GROUP BY [NumberValue]
            HAVING COUNT(*) > 1
        )
        BEGIN
            SET @StatusCode = 'INVALID_PARAMETER';
            SET @ErrorMessage = N'@SessionIds enthält ungültige, doppelte oder außerhalb des smallint-Bereichs liegende Werte.';
        END;
        ELSE
        BEGIN
            INSERT [#CurrentBlocking_SessionFilter]([SessionId])
            SELECT CONVERT(smallint, [NumberValue])
            FROM [monitor].[TVF_ParseBigintList](@SessionIds)
            WHERE [IsValid] = 1;
        END;
    END;

    IF @StatusCode = 'AVAILABLE'
       AND
       (
           COALESCE(@MinWaitMs, -1) < 0
           OR @MaxZeilen < 0
           OR @MaxSqlTextZeichen < 0
           OR @BlockingObjektTiefeNormalisiert NOT IN ('NONE', 'STANDARD', 'DEEP')
           OR @MaxObjektAufloesungen IS NULL
           OR @MaxObjektAufloesungen NOT BETWEEN 1 AND 1000
           OR @ResultSetArtNormalisiert NOT IN ('RAW', 'CONSOLE', 'NONE')
           OR @SystemSessionsEinbeziehen IS NULL
           OR @ToolHintergrundabfragenEinbeziehen IS NULL
           OR @ToolHintergrundabfragenEinbeziehen NOT IN (0,1)
           OR @MitSqlText IS NULL
           OR @MitLockDetails IS NULL
           OR @HighImpactConfirmed IS NULL
           OR @JsonErzeugen IS NULL
           OR @PrintMeldungen IS NULL
       )
    BEGIN
        SET @StatusCode = 'INVALID_PARAMETER';
        SET @ErrorMessage = N'Mindestens ein Parameter besitzt einen ungültigen Wert.';
    END;

    IF @StatusCode = 'AVAILABLE' AND @BlockingObjektTiefeNormalisiert = 'DEEP'
        SET @MitLockDetails = 1;

    IF @StatusCode = 'AVAILABLE'
       AND @MitLockDetails=1
        EXEC [monitor].[InternalCheckAnalysisPath]
              @AnalysisClass='LOCKS_DEEP'
            , @HighImpactConfirmed=@HighImpactConfirmed
            , @StatusCode=@StatusCode OUTPUT
            , @ErrorMessage=@ErrorMessage OUTPUT;

    IF @StatusCode = 'AVAILABLE'
    BEGIN TRY
        IF @ParentCurrentStateSnapshotId IS NOT NULL
        BEGIN
            EXEC [sys].[sp_executesql] N'
                DECLARE @Probe int;
                SELECT @Probe=0 FROM [#CurrentOverview_CurrentStateSnapshot_Context] WHERE 1=0;
                SELECT @Probe=0 FROM [#CurrentOverview_CurrentStateSnapshot_SourceStatus] WHERE 1=0;
                SELECT @Probe=0 FROM [#CurrentOverview_CurrentStateSnapshot_Sessions] WHERE 1=0;
                SELECT @Probe=0 FROM [#CurrentOverview_CurrentStateSnapshot_Requests] WHERE 1=0;
                SELECT @Probe=0 FROM [#CurrentOverview_CurrentStateSnapshot_WaitingTasks] WHERE 1=0;
                SELECT @Probe=0 FROM [#CurrentOverview_CurrentStateSnapshot_Connections] WHERE 1=0;
                SELECT @Probe=0 FROM [#CurrentOverview_CurrentStateSnapshot_SqlText] WHERE 1=0;';

            IF NOT EXISTS
            (
                SELECT 1
                FROM [#CurrentOverview_CurrentStateSnapshot_Context]
                WHERE [SnapshotId]=@ParentCurrentStateSnapshotId
                  AND [OwnerSessionId]=CONVERT(smallint,@@SPID)
                  AND [ContractVersion]=2
            )
                THROW 51020,N'Die Parent-Snapshot-ID gehört nicht zum aktuellen Aufruf.',1;

            INSERT [#CurrentBlocking_SourceSessions]
            SELECT
                  [session_id],[is_user_process],[status],[login_name],[host_name],[program_name]
                , [open_transaction_count],[last_request_start_time],[last_request_end_time]
            FROM [#CurrentOverview_CurrentStateSnapshot_Sessions]
            WHERE [SnapshotId]=@ParentCurrentStateSnapshotId;

            INSERT [#CurrentBlocking_SourceRequests]
            SELECT
                  [session_id],[request_id],[status],[blocking_session_id],[wait_type]
                , [wait_time],[wait_resource],[sql_handle]
                , [statement_start_offset],[statement_end_offset]
            FROM [#CurrentOverview_CurrentStateSnapshot_Requests]
            WHERE [SnapshotId]=@ParentCurrentStateSnapshotId;

            INSERT [#CurrentBlocking_SourceWaitingTasks]
            SELECT
                  [session_id],[wait_duration_ms],[wait_type]
                , [blocking_session_id],[resource_description]
            FROM [#CurrentOverview_CurrentStateSnapshot_WaitingTasks]
            WHERE [SnapshotId]=@ParentCurrentStateSnapshotId;

            INSERT [#CurrentBlocking_SourceConnections]
            SELECT [session_id],[connection_id],[most_recent_sql_handle],[connect_time]
            FROM [#CurrentOverview_CurrentStateSnapshot_Connections]
            WHERE [SnapshotId]=@ParentCurrentStateSnapshotId;

            IF @MitSqlText=1
                INSERT [#CurrentBlocking_SourceSqlText]
                SELECT [SqlHandle],[Text]
                FROM [#CurrentOverview_CurrentStateSnapshot_SqlText]
                WHERE [SnapshotId]=@ParentCurrentStateSnapshotId;

            SELECT
                  @EvidenceSnapshotStartedAtUtc=MIN([CapturedAtUtc])
                , @IsPartial=CONVERT(bit,MAX(CONVERT(int,[IsPartial])))
            FROM [#CurrentOverview_CurrentStateSnapshot_SourceStatus]
            WHERE [SnapshotId]=@ParentCurrentStateSnapshotId
              AND [SourceCode] IN
                  ('SESSIONS','REQUESTS','WAITING_TASKS','CONNECTIONS','SQL_TEXT');
        END
        ELSE
        BEGIN
            SET @EvidenceSnapshotStartedAtUtc=SYSUTCDATETIME();
            INSERT [#CurrentBlocking_SourceSessions]
            SELECT
                  [session_id],[is_user_process],[status],[login_name],[host_name],[program_name]
                , [open_transaction_count],[last_request_start_time],[last_request_end_time]
            FROM [sys].[dm_exec_sessions] WITH (NOLOCK);

            INSERT [#CurrentBlocking_SourceRequests]
            SELECT
                  [session_id],[request_id],[status],[blocking_session_id],[wait_type]
                , [wait_time],[wait_resource],[sql_handle]
                , [statement_start_offset],[statement_end_offset]
            FROM [sys].[dm_exec_requests] WITH (NOLOCK);

            INSERT [#CurrentBlocking_SourceWaitingTasks]
            SELECT
                  [session_id],[wait_duration_ms],[wait_type]
                , [blocking_session_id],[resource_description]
            FROM [sys].[dm_os_waiting_tasks] WITH (NOLOCK);

            INSERT [#CurrentBlocking_SourceConnections]
            SELECT [session_id],[connection_id],[most_recent_sql_handle],[connect_time]
            FROM [sys].[dm_exec_connections] WITH (NOLOCK);

            IF @MitSqlText=1
                INSERT [#CurrentBlocking_SourceSqlText]
                SELECT [h].[SqlHandle],[t].[text]
                FROM
                (
                    SELECT [sql_handle] AS [SqlHandle]
                    FROM [#CurrentBlocking_SourceRequests]
                    WHERE [sql_handle] IS NOT NULL
                    UNION
                    SELECT [most_recent_sql_handle]
                    FROM [#CurrentBlocking_SourceConnections]
                    WHERE [most_recent_sql_handle] IS NOT NULL
                ) AS [h]
                OUTER APPLY [sys].[dm_exec_sql_text]([h].[SqlHandle]) AS [t];
        END;

        INSERT [#CurrentBlocking_Edges]
        (
              [BlockedSessionId], [BlockingSessionId], [WaitType]
            , [WaitTimeMs], [WaitResource], [SourceCode]
        )
        SELECT
              [r].[session_id]
            , [r].[blocking_session_id]
            , MAX([r].[wait_type])
            , MAX(CONVERT(bigint, [r].[wait_time]))
            , MAX(CONVERT(nvarchar(3072), [r].[wait_resource]))
            , 'REQUEST'
        FROM [#CurrentBlocking_SourceRequests] AS [r]
        INNER JOIN [#CurrentBlocking_SourceSessions] AS [s]
          ON [s].[session_id] = [r].[session_id]
        WHERE [r].[blocking_session_id] <> 0
          AND [r].[blocking_session_id] <> [r].[session_id]
          AND (@SystemSessionsEinbeziehen = 1 OR [s].[is_user_process] = 1)
          AND COALESCE([r].[wait_time], 0) >= @MinWaitMs
        GROUP BY [r].[session_id], [r].[blocking_session_id];

        INSERT [#CurrentBlocking_Edges]
        (
              [BlockedSessionId], [BlockingSessionId], [WaitType]
            , [WaitTimeMs], [WaitResource], [SourceCode]
        )
        SELECT
              [w].[session_id]
            , [w].[blocking_session_id]
            , MAX([w].[wait_type])
            , MAX(CONVERT(bigint, [w].[wait_duration_ms]))
            , MAX(CONVERT(nvarchar(3072), [w].[resource_description]))
            , 'WAITING_TASK'
        FROM [#CurrentBlocking_SourceWaitingTasks] AS [w]
        LEFT JOIN [#CurrentBlocking_SourceSessions] AS [s]
          ON [s].[session_id] = [w].[session_id]
        WHERE [w].[blocking_session_id] <> 0
          AND [w].[blocking_session_id] <> [w].[session_id]
          AND COALESCE([w].[wait_duration_ms], 0) >= @MinWaitMs
          AND (@SystemSessionsEinbeziehen = 1 OR COALESCE([s].[is_user_process], 1) = 1)
          AND NOT EXISTS
              (
                  SELECT 1
                  FROM [#CurrentBlocking_Edges] AS [e]
                  WHERE [e].[BlockedSessionId] = [w].[session_id]
                    AND [e].[BlockingSessionId] = [w].[blocking_session_id]
              )
        GROUP BY [w].[session_id], [w].[blocking_session_id];

        ;WITH [Chain] AS
        (
            SELECT
                  [e].[BlockedSessionId] AS [LeafSessionId]
                , [e].[BlockedSessionId]
                , [e].[BlockingSessionId]
                , 1 AS [ChainDepth]
                , CONVERT(varchar(4000), CONCAT('|', [e].[BlockedSessionId], '|', [e].[BlockingSessionId], '|')) AS [Path]
                , CONVERT(nvarchar(4000), CONCAT([e].[BlockedSessionId], N' <- ', [e].[BlockingSessionId])) AS [BlockingChain]
                , CONVERT(bit, 0) AS [IsCycle]
            FROM [#CurrentBlocking_Edges] AS [e]

            UNION ALL

            SELECT
                  [c].[LeafSessionId]
                , [e].[BlockedSessionId]
                , [e].[BlockingSessionId]
                , [c].[ChainDepth] + 1
                , CONVERT(varchar(4000), CONCAT([c].[Path], [e].[BlockingSessionId], '|'))
                , CONVERT(nvarchar(4000), CONCAT([c].[BlockingChain], N' <- ', [e].[BlockingSessionId]))
                , CONVERT
                  (
                      bit,
                      CASE WHEN [c].[Path] LIKE CONCAT('%|', [e].[BlockingSessionId], '|%')
                           THEN 1 ELSE 0 END
                  )
            FROM [Chain] AS [c]
            INNER JOIN [#CurrentBlocking_Edges] AS [e]
              ON [e].[BlockedSessionId] = [c].[BlockingSessionId]
            WHERE [c].[ChainDepth] < 32
              AND [c].[IsCycle] = 0
        ),
        [Root] AS
        (
            SELECT
                  [c].*
                , ROW_NUMBER() OVER
                  (
                      PARTITION BY [c].[LeafSessionId]
                      ORDER BY [c].[ChainDepth] DESC, [c].[Path]
                  ) AS [RowNumber]
            FROM [Chain] AS [c]
        )
        INSERT [#CurrentBlocking_BlockingChains]
        (
              [LeafSessionId], [BlockedSessionId], [BlockingSessionId]
            , [RootBlockingSessionId], [BlockingOwnerType], [BlockingOwnerDescription]
            , [BlockingChain], [ChainDepth], [IsCycle]
            , [WaitType], [WaitTimeMs], [WaitResource]
            , [BlockedLoginName], [BlockedHostName], [BlockedProgramName]
            , [BlockedIsToolBackgroundQuery], [BlockedToolBackgroundRuleCode]
            , [BlockedToolBackgroundCategory], [BlockedToolBackgroundDetection]
            , [BlockedToolBackgroundConfidence]
            , [BlockerLoginName], [BlockerHostName], [BlockerProgramName]
            , [RootBlockerLoginName], [RootBlockerHostName], [RootBlockerProgramName]
            , [RootBlockerSessionStatus], [RootBlockerRequestStatus]
            , [RootBlockerOpenTransactionCount]
            , [RootBlockerLastRequestStartTime], [RootBlockerLastRequestEndTime]
            , [RootIsToolBackgroundQuery], [RootToolBackgroundRuleCode]
            , [RootToolBackgroundCategory], [RootToolBackgroundDetection]
            , [RootToolBackgroundConfidence]
            , [BlockedStatementCharacters], [BlockedStatementBytes], [BlockedStatementIsTruncated], [BlockedStatement]
            , [BlockerStatementCharacters], [BlockerStatementBytes], [BlockerStatementIsTruncated], [BlockerStatement]
            , [RootBlockerStatementSource]
            , [RootBlockerStatementCharacters], [RootBlockerStatementBytes], [RootBlockerStatementIsTruncated], [RootBlockerStatement]
        )
        SELECT TOP (@CandidateRows)
              [r].[LeafSessionId]
            , [e].[BlockedSessionId]
            , [e].[BlockingSessionId]
            , [r].[BlockingSessionId]
            , CASE [r].[BlockingSessionId]
                  WHEN -2 THEN 'ORPHAN_DTC'
                  WHEN -3 THEN 'DEFERRED_RECOVERY'
                  WHEN -4 THEN 'LATCH_OWNER_TRANSIENT'
                  WHEN -5 THEN 'LATCH_OWNER_UNTRACKED'
                  ELSE 'SESSION' END
            , CASE [r].[BlockingSessionId]
                  WHEN -2 THEN N'Verwaiste verteilte Transaktion ohne zugeordnete Session.'
                  WHEN -3 THEN N'Verzögerte Recovery-Transaktion hält die Ressource.'
                  WHEN -4 THEN N'Der Latch-Besitzer war während der Momentaufnahme nicht bestimmbar.'
                  WHEN -5 THEN N'Der Latch-Besitzer wird für diesen Ressourcentyp nicht verfolgt.'
                  ELSE N'Blockierende SQL-Server-Session.' END
            , [r].[BlockingChain]
            , [r].[ChainDepth]
            , [r].[IsCycle]
            , [e].[WaitType]
            , [e].[WaitTimeMs]
            , [e].[WaitResource]
            , [blockedSession].[login_name]
            , [blockedSession].[host_name]
            , [blockedSession].[program_name]
            , [blockedTool].[IsToolBackgroundQuery]
            , [blockedTool].[ToolBackgroundRuleCode]
            , [blockedTool].[ToolBackgroundCategory]
            , [blockedTool].[ToolBackgroundDetection]
            , [blockedTool].[ToolBackgroundConfidence]
            , [blockerSession].[login_name]
            , [blockerSession].[host_name]
            , [blockerSession].[program_name]
            , [rootSession].[login_name]
            , [rootSession].[host_name]
            , [rootSession].[program_name]
            , [rootSession].[status]
            , [rootRequest].[status]
            , [rootSession].[open_transaction_count]
            , [rootSession].[last_request_start_time]
            , [rootSession].[last_request_end_time]
            , [rootTool].[IsToolBackgroundQuery]
            , [rootTool].[ToolBackgroundRuleCode]
            , [rootTool].[ToolBackgroundCategory]
            , [rootTool].[ToolBackgroundDetection]
            , [rootTool].[ToolBackgroundConfidence]
            , NULL,NULL,CONVERT(bit,0),CASE WHEN @MitSqlText = 1 THEN [blockedStatement].[StatementText] END
            , NULL,NULL,CONVERT(bit,0),CASE WHEN @MitSqlText = 1 THEN [blockerStatement].[StatementText] END
            , CASE
                  WHEN @MitSqlText = 0 THEN 'NOT_REQUESTED'
                  WHEN [rootRequest].[sql_handle] IS NOT NULL THEN 'ACTIVE_REQUEST'
                  WHEN [rootConnection].[most_recent_sql_handle] IS NOT NULL THEN 'MOST_RECENT_CONNECTION'
                  ELSE 'UNAVAILABLE'
              END
            , NULL,NULL,CONVERT(bit,0),CASE WHEN @MitSqlText = 1 THEN [rootStatement].[StatementText] END
        FROM [Root] AS [r]
        INNER JOIN [#CurrentBlocking_Edges] AS [e]
          ON [e].[BlockedSessionId] = [r].[LeafSessionId]
        LEFT JOIN [#CurrentBlocking_SourceSessions] AS [blockedSession]
          ON [blockedSession].[session_id] = [e].[BlockedSessionId]
        LEFT JOIN [#CurrentBlocking_SourceSessions] AS [blockerSession]
          ON [blockerSession].[session_id] = [e].[BlockingSessionId]
        LEFT JOIN [#CurrentBlocking_SourceSessions] AS [rootSession]
          ON [rootSession].[session_id] = [r].[BlockingSessionId]
        OUTER APPLY
        (
            SELECT TOP (1) [request].*
            FROM [#CurrentBlocking_SourceRequests] AS [request]
            WHERE [request].[session_id] = [e].[BlockedSessionId]
            ORDER BY [request].[request_id]
        ) AS [blockedRequest]
        OUTER APPLY
        (
            SELECT TOP (1) [request].*
            FROM [#CurrentBlocking_SourceRequests] AS [request]
            WHERE [request].[session_id] = [e].[BlockingSessionId]
            ORDER BY [request].[request_id]
        ) AS [blockerRequest]
        OUTER APPLY
        (
            SELECT TOP (1) [request].*
            FROM [#CurrentBlocking_SourceRequests] AS [request]
            WHERE [request].[session_id] = [r].[BlockingSessionId]
            ORDER BY [request].[request_id]
        ) AS [rootRequest]
        OUTER APPLY
        (
            SELECT TOP (1) [connection].[most_recent_sql_handle]
            FROM [#CurrentBlocking_SourceConnections] AS [connection]
            WHERE [connection].[session_id] = [r].[BlockingSessionId]
            ORDER BY [connection].[connect_time] DESC
        ) AS [rootConnection]
        CROSS APPLY [monitor].[TVF_ToolBackgroundQueryInfo]([blockedSession].[program_name]) AS [blockedTool]
        CROSS APPLY [monitor].[TVF_ToolBackgroundQueryInfo]([rootSession].[program_name]) AS [rootTool]
        LEFT JOIN [#CurrentBlocking_SourceSqlText] AS [blockedText]
          ON [blockedText].[SqlHandle]=CASE WHEN @MitSqlText=1 THEN [blockedRequest].[sql_handle] END
        OUTER APPLY [monitor].[TVF_StatementText]
        (
              [blockedText].[Text]
            , [blockedRequest].[statement_start_offset]
            , [blockedRequest].[statement_end_offset]
        ) AS [blockedStatement]
        LEFT JOIN [#CurrentBlocking_SourceSqlText] AS [blockerText]
          ON [blockerText].[SqlHandle]=CASE WHEN @MitSqlText=1 THEN [blockerRequest].[sql_handle] END
        OUTER APPLY [monitor].[TVF_StatementText]
        (
              [blockerText].[Text]
            , [blockerRequest].[statement_start_offset]
            , [blockerRequest].[statement_end_offset]
        ) AS [blockerStatement]
        LEFT JOIN [#CurrentBlocking_SourceSqlText] AS [rootText]
          ON [rootText].[SqlHandle]=CASE WHEN @MitSqlText=1
               THEN COALESCE([rootRequest].[sql_handle],[rootConnection].[most_recent_sql_handle]) END
        OUTER APPLY [monitor].[TVF_StatementText]
        (
              [rootText].[Text]
            , CASE WHEN [rootRequest].[sql_handle] IS NOT NULL
                   THEN [rootRequest].[statement_start_offset] END
            , CASE WHEN [rootRequest].[sql_handle] IS NOT NULL
                   THEN [rootRequest].[statement_end_offset] END
        ) AS [rootStatement]
        WHERE [r].[RowNumber] = 1
          AND
          (
              @SessionIds IS NULL
              OR EXISTS
                 (
                     SELECT 1
                     FROM [#CurrentBlocking_SessionFilter] AS [filter]
                     WHERE [r].[Path] LIKE CONCAT('%|', [filter].[SessionId], '|%')
                 )
          )
          AND
          (
              @ToolHintergrundabfragenEinbeziehen = 1
              OR [blockedTool].[IsToolBackgroundQuery] = 0
          )
        ORDER BY [e].[WaitTimeMs] DESC, [e].[BlockedSessionId]
        OPTION (MAXRECURSION 32);

        ;WITH [RetainedChain] AS
        (
            SELECT
                  [e].[BlockedSessionId]
                , [e].[BlockingSessionId]
                , 1 AS [ChainDepth]
                , CONVERT(varchar(4000), CONCAT('|', [e].[BlockedSessionId], '|', [e].[BlockingSessionId], '|')) AS [Path]
            FROM [#CurrentBlocking_Edges] AS [e]
            JOIN [#CurrentBlocking_BlockingChains] AS [retained]
              ON [retained].[LeafSessionId] = [e].[BlockedSessionId]

            UNION ALL

            SELECT
                  [e].[BlockedSessionId]
                , [e].[BlockingSessionId]
                , [chain].[ChainDepth] + 1
                , CONVERT(varchar(4000), CONCAT([chain].[Path], [e].[BlockingSessionId], '|'))
            FROM [RetainedChain] AS [chain]
            JOIN [#CurrentBlocking_Edges] AS [e]
              ON [e].[BlockedSessionId] = [chain].[BlockingSessionId]
            WHERE [chain].[ChainDepth] < 32
              AND [chain].[Path] NOT LIKE CONCAT('%|', [e].[BlockingSessionId], '|%')
        ),
        [RetainedSessions] AS
        (
            SELECT [BlockedSessionId] AS [SessionId]
            FROM [RetainedChain]
            WHERE [BlockedSessionId] > 0
            UNION
            SELECT [BlockingSessionId]
            FROM [RetainedChain]
            WHERE [BlockingSessionId] > 0
        )
        INSERT [#CurrentBlocking_RetainedSessions]([SessionId])
        SELECT [SessionId]
        FROM [RetainedSessions]
        OPTION (MAXRECURSION 32);

        SELECT @MainCandidateCount = COUNT_BIG(*) FROM [#CurrentBlocking_BlockingChains];
        SET @HasMoreRows = CONVERT
        (
            bit,
            CASE WHEN @EffectiveMaxZeilen < 9223372036854775807
                       AND @MainCandidateCount > @EffectiveMaxZeilen
                 THEN 1 ELSE 0 END
        );

        IF @MitLockDetails = 1
        BEGIN
            DECLARE @LockAllowed bit = 1;

            IF @LockAllowed = 0
            BEGIN
                SET @LockStatusCode = 'DENIED_GROUP';
                SET @IsPartial = 1;
                INSERT [#CurrentBlocking_Warnings]([ScopeName], [StatusCode], [ErrorMessage])
                VALUES (N'Locks', 'DENIED_GROUP', N'Die Analyseklasse LOCKS_DEEP ist nicht freigegeben.');
            END;
            ELSE
            BEGIN TRY
                INSERT [#CurrentBlocking_Locks]
                (
                      [SessionId], [ResourceType], [ResourceDatabaseId]
                    , [ResourceDatabaseName], [ResourceDescription], [ResourceSubtype]
                    , [ResourceAssociatedEntityId], [ResourceLockPartition]
                    , [RequestMode], [RequestStatus], [RequestOwnerType]
                    , [RequestReferenceCount], [LockOwnerAddress]
                )
                SELECT TOP (@CandidateRows)
                      CONVERT(smallint, [l].[request_session_id])
                    , [l].[resource_type]
                    , [l].[resource_database_id]
                    , CONVERT(sysname, NULL)
                    , [l].[resource_description]
                    , [l].[resource_subtype]
                    , [l].[resource_associated_entity_id]
                    , [l].[resource_lock_partition]
                    , [l].[request_mode]
                    , [l].[request_status]
                    , [l].[request_owner_type]
                    , [l].[request_reference_count]
                    , [l].[lock_owner_address]
                FROM [sys].[dm_tran_locks] AS [l] WITH (NOLOCK)
                WHERE EXISTS
                      (
                          SELECT 1
                          FROM [#CurrentBlocking_RetainedSessions] AS [retained]
                          WHERE [retained].[SessionId] = [l].[request_session_id]
                      )
                ORDER BY
                      [l].[request_session_id]
                    , [l].[resource_database_id]
                    , [l].[resource_type]
                    , [l].[request_mode];

                SELECT @LockCandidateCount = COUNT_BIG(*) FROM [#CurrentBlocking_Locks];
                SET @LockStatusCode = 'AVAILABLE';
            END TRY
            BEGIN CATCH
                SET @LockStatusCode = CASE WHEN ERROR_NUMBER() IN (229, 262, 297, 300, 371, 916)
                                           THEN 'DENIED_PERMISSION'
                                           WHEN ERROR_NUMBER() = 1222 THEN 'TIMEOUT'
                                           ELSE 'ERROR_HANDLED' END;
                SET @IsPartial = 1;
                INSERT [#CurrentBlocking_Warnings]([ScopeName], [StatusCode], [ErrorNumber], [ErrorMessage])
                VALUES (N'Locks', @LockStatusCode, ERROR_NUMBER(), ERROR_MESSAGE());
            END CATCH;
        END;

        IF @BlockingObjektTiefeNormalisiert <> 'NONE'
        BEGIN
            SELECT @ObjectResolutionTotalCount = COUNT_BIG(*)
            FROM
            (
                SELECT DISTINCT [WaitResource]
                FROM [#CurrentBlocking_BlockingChains]
                WHERE NULLIF(LTRIM(RTRIM([WaitResource])), N'') IS NOT NULL
            ) AS [r];

            IF @MitLockDetails = 1
            BEGIN
                DECLARE @DistinctLockResources bigint;
                SELECT @DistinctLockResources = COUNT_BIG(*)
                FROM
                (
                    SELECT DISTINCT
                          [ResourceType], [ResourceDatabaseId]
                        , [ResourceAssociatedEntityId], [ResourceDescription], [ResourceSubtype]
                    FROM [#CurrentBlocking_Locks]
                ) AS [l];
                SET @ObjectResolutionTotalCount += COALESCE(@DistinctLockResources, 0);
            END;

            ;WITH [ParsedWaitResources] AS
            (
                SELECT
                      [c].[WaitResource]
                    , [p].[ResourceType], [p].[FormatCode], [p].[DatabaseId]
                    , [p].[EntityId], [p].[SubEntityId], [p].[FileId]
                    , [p].[PageId], [p].[RowId], [p].[MetadataSubtype]
                    , [p].[ResourceQualifier], [p].[ParseStatus]
                    , MAX(COALESCE([c].[WaitTimeMs], 0)) OVER
                      (PARTITION BY [c].[WaitResource]) AS [MaximumWaitTimeMs]
                    , ROW_NUMBER() OVER
                      (PARTITION BY [c].[WaitResource] ORDER BY [c].[BlockedSessionId]) AS [DuplicateOrdinal]
                FROM [#CurrentBlocking_BlockingChains] AS [c]
                CROSS APPLY [monitor].[TVF_ParseBlockingResource]([c].[WaitResource]) AS [p]
                WHERE NULLIF(LTRIM(RTRIM([c].[WaitResource])), N'') IS NOT NULL
            )
            INSERT [#CurrentBlocking_ResourceResolution]
            (
                  [SourceCode], [WaitResource], [ResourceType], [FormatCode]
                , [DatabaseId], [EntityId], [SubEntityId], [FileId], [PageId]
                , [RowId], [MetadataSubtype], [ResourceQualifier], [ResolutionStatus]
            )
            SELECT TOP (@MaxObjektAufloesungen)
                  'WAIT_RESOURCE', [p].[WaitResource], [p].[ResourceType], [p].[FormatCode]
                , [p].[DatabaseId], [p].[EntityId], [p].[SubEntityId], [p].[FileId]
                , [p].[PageId], [p].[RowId], [p].[MetadataSubtype]
                , [p].[ResourceQualifier], [p].[ParseStatus]
            FROM [ParsedWaitResources] AS [p]
            WHERE [p].[DuplicateOrdinal] = 1
            ORDER BY [p].[MaximumWaitTimeMs] DESC, [p].[WaitResource];

            SELECT @ObjectResolutionCandidateCount = COUNT_BIG(*)
            FROM [#CurrentBlocking_ResourceResolution];

            IF @MitLockDetails = 1
               AND @ObjectResolutionCandidateCount < @MaxObjektAufloesungen
            BEGIN
                DECLARE @RemainingResolutionRows int =
                    @MaxObjektAufloesungen - CONVERT(int, @ObjectResolutionCandidateCount);

                INSERT [#CurrentBlocking_ResourceResolution]
                (
                      [SourceCode], [WaitResource], [ResourceType], [FormatCode]
                    , [DatabaseId], [EntityId], [MetadataSubtype]
                    , [ResourceQualifier], [ResolutionStatus]
                )
                SELECT TOP (@RemainingResolutionRows)
                      'LOCK_DMV', NULL, UPPER([l].[ResourceType]), 'LOCK_DMV'
                    , [l].[ResourceDatabaseId], [l].[ResourceAssociatedEntityId]
                    , [l].[ResourceSubtype]
                    , [l].[ResourceDescription]
                    , CASE WHEN [l].[ResourceType] IS NULL THEN 'INVALID_FORMAT'
                           ELSE 'PARSED' END
                FROM
                (
                    SELECT DISTINCT
                          [ResourceType], [ResourceDatabaseId]
                        , [ResourceAssociatedEntityId], [ResourceDescription], [ResourceSubtype]
                    FROM [#CurrentBlocking_Locks]
                ) AS [l]
                ORDER BY [l].[ResourceDatabaseId], [l].[ResourceType], [l].[ResourceAssociatedEntityId];

                SELECT @ObjectResolutionCandidateCount = COUNT_BIG(*)
                FROM [#CurrentBlocking_ResourceResolution];
            END;

            UPDATE [r]
            SET
                  [EntityId] = COALESCE([p].[EntityId], [r].[EntityId])
                , [SubEntityId] = COALESCE([p].[SubEntityId], [r].[SubEntityId])
            FROM [#CurrentBlocking_ResourceResolution] AS [r]
            CROSS APPLY [monitor].[TVF_ParseBlockingResource]
            (
                CONCAT
                (
                      N'METADATA: database_id = ', [r].[DatabaseId], N' '
                    , COALESCE([r].[MetadataSubtype], N'OTHER'), N'('
                    , COALESCE([r].[ResourceQualifier], N''), N')'
                )
            ) AS [p]
            WHERE [r].[FormatCode] = 'LOCK_DMV'
              AND [r].[ResourceType] = N'METADATA';

            IF @ObjectResolutionTotalCount > @ObjectResolutionCandidateCount
            BEGIN
                SET @ObjectResolutionHasMoreRows = 1;
                SET @ObjectResolutionStatusCode = 'AVAILABLE_LIMITED';
                SET @IsPartial = 1;
                INSERT [#CurrentBlocking_Warnings]
                ([ScopeName], [StatusCode], [ErrorMessage])
                VALUES
                (
                      N'BlockingResourceResolution'
                    , 'ROW_LIMIT_APPLIED'
                    , CONCAT
                      (
                            N'Die Objektauflösung wurde auf '
                          , CONVERT(nvarchar(20), @MaxObjektAufloesungen)
                          , N' deduplizierte Ressourcen begrenzt; Rohressourcen bleiben vollständig erhalten.'
                      )
                );
            END;

            UPDATE [r]
            SET [FileId] = COALESCE
                           (
                               TRY_CONVERT(int, NULLIF([r].[ResourceQualifier], N'')),
                               TRY_CONVERT(int, [r].[EntityId])
                           )
            FROM [#CurrentBlocking_ResourceResolution] AS [r]
            WHERE [r].[FormatCode] = 'LOCK_DMV'
              AND [r].[ResourceType] = N'FILE';

            UPDATE [r]
            SET
                  [FileId] = TRY_CONVERT
                             (
                                 int,
                                 PARSENAME
                                 (
                                     REPLACE([r].[ResourceQualifier], N':', N'.'),
                                     CASE WHEN LEN([r].[ResourceQualifier]) - LEN(REPLACE([r].[ResourceQualifier], N':', N'')) >= 2
                                          THEN 3 ELSE 2 END
                                 )
                             )
                , [PageId] = TRY_CONVERT
                             (
                                 bigint,
                                 PARSENAME
                                 (
                                     REPLACE([r].[ResourceQualifier], N':', N'.'),
                                     CASE WHEN LEN([r].[ResourceQualifier]) - LEN(REPLACE([r].[ResourceQualifier], N':', N'')) >= 2
                                          THEN 2 ELSE 1 END
                                 )
                             )
                , [RowId] = CASE WHEN [r].[ResourceType] = N'RID'
                                 THEN TRY_CONVERT(int, PARSENAME(REPLACE([r].[ResourceQualifier], N':', N'.'), 1)) END
            FROM [#CurrentBlocking_ResourceResolution] AS [r]
            WHERE [r].[FormatCode] = 'LOCK_DMV'
              AND [r].[ResourceType] IN (N'PAGE', N'RID', N'EXTENT')
              AND [r].[ResourceQualifier] LIKE N'%:%';

            DECLARE @ResolutionCandidateId int;
            DECLARE @ResolutionResourceType nvarchar(60);
            DECLARE @ResolutionFormatCode varchar(40);
            DECLARE @ResolutionDatabaseId int;
            DECLARE @ResolutionDatabaseName sysname;
            DECLARE @ResolutionDatabaseState tinyint;
            DECLARE @ResolutionEntityId bigint;
            DECLARE @ResolutionSubEntityId bigint;
            DECLARE @ResolutionFileId int;
            DECLARE @ResolutionFileName sysname;
            DECLARE @ResolutionPageId bigint;
            DECLARE @ResolutionPageIdInt int;
            DECLARE @ResolutionRowId int;
            DECLARE @ResolutionMetadataSubtype nvarchar(60);
            DECLARE @ResolutionQualifier nvarchar(512);
            DECLARE @ResolutionSchemaName sysname;
            DECLARE @ResolutionObjectId int;
            DECLARE @ResolutionObjectName sysname;
            DECLARE @ResolutionIndexId int;
            DECLARE @ResolutionIndexName sysname;
            DECLARE @ResolutionPartitionId bigint;
            DECLARE @ResolutionPartitionNumber int;
            DECLARE @ResolutionPageTypeDesc nvarchar(60);
            DECLARE @ResolutionMetadataName sysname;
            DECLARE @ResolutionResourceName nvarchar(1024);
            DECLARE @ResolutionSql nvarchar(max);
            DECLARE @ResolutionFirstErrorNumber int;
            DECLARE @ResolutionFirstErrorMessage nvarchar(2048);
            DECLARE @ResolutionFirstErrorScope nvarchar(128);

            -- Der Kern-Snapshot ist vollständig materialisiert. Jeder Kandidat
            -- wird in eigenen Child-Batches angereichert, damit LOCK_TIMEOUT 0
            -- und Fehlerstatus niemals auf den nächsten Kandidaten übergreifen.
            DECLARE [CurrentBlocking_ResolutionCandidateCursor] CURSOR LOCAL FAST_FORWARD FOR
                SELECT
                      [CandidateId], [ResourceType], [FormatCode], [DatabaseId]
                    , [DatabaseName], [EntityId], [SubEntityId], [FileId], [FileName]
                    , [PageId], [RowId], [MetadataSubtype], [ResourceQualifier]
                    , [SchemaName], [ObjectId], [ObjectName], [IndexId], [IndexName]
                    , [PartitionId], [PartitionNumber], [PageTypeDesc], [MetadataName]
                    , [ResourceName]
                FROM [#CurrentBlocking_ResourceResolution]
                ORDER BY [CandidateId];

            OPEN [CurrentBlocking_ResolutionCandidateCursor];
            FETCH NEXT FROM [CurrentBlocking_ResolutionCandidateCursor]
            INTO
                  @ResolutionCandidateId, @ResolutionResourceType, @ResolutionFormatCode
                , @ResolutionDatabaseId, @ResolutionDatabaseName, @ResolutionEntityId
                , @ResolutionSubEntityId, @ResolutionFileId, @ResolutionFileName
                , @ResolutionPageId, @ResolutionRowId, @ResolutionMetadataSubtype
                , @ResolutionQualifier, @ResolutionSchemaName, @ResolutionObjectId
                , @ResolutionObjectName, @ResolutionIndexId, @ResolutionIndexName
                , @ResolutionPartitionId, @ResolutionPartitionNumber
                , @ResolutionPageTypeDesc, @ResolutionMetadataName
                , @ResolutionResourceName;

            WHILE @@FETCH_STATUS = 0
            BEGIN
                SELECT
                      @ResolutionDatabaseState = NULL
                    , @ResolutionPageIdInt = TRY_CONVERT(int, @ResolutionPageId)
                    , @ResolutionFirstErrorNumber = NULL
                    , @ResolutionFirstErrorMessage = NULL
                    , @ResolutionFirstErrorScope = NULL;

                IF @ResolutionDatabaseId IS NOT NULL
                BEGIN TRY
                    EXEC [sys].[sp_executesql]
                          N'SET LOCK_TIMEOUT 0;
                            SELECT
                                  @DatabaseName = [d].[name]
                                , @DatabaseState = CONVERT(tinyint, [d].[state])
                            FROM [master].[sys].[databases] AS [d] WITH (NOLOCK)
                            WHERE [d].[database_id] = @DatabaseId;'
                        , N'@DatabaseId int, @DatabaseName sysname OUTPUT, @DatabaseState tinyint OUTPUT'
                        , @DatabaseId = @ResolutionDatabaseId
                        , @DatabaseName = @ResolutionDatabaseName OUTPUT
                        , @DatabaseState = @ResolutionDatabaseState OUTPUT;
                END TRY
                BEGIN CATCH
                    IF @ResolutionFirstErrorNumber IS NULL
                    BEGIN
                        SELECT
                              @ResolutionFirstErrorNumber = ERROR_NUMBER()
                            , @ResolutionFirstErrorMessage = ERROR_MESSAGE()
                            , @ResolutionFirstErrorScope = N'DATABASE';
                    END;
                END CATCH;

                IF @ResolutionDatabaseId IS NOT NULL
                   AND @ResolutionFileId IS NOT NULL
                BEGIN TRY
                    EXEC [sys].[sp_executesql]
                          N'SET LOCK_TIMEOUT 0;
                            SELECT @FileName = [f].[name]
                            FROM [master].[sys].[master_files] AS [f] WITH (NOLOCK)
                            WHERE [f].[database_id] = @DatabaseId
                              AND [f].[file_id] = @FileId;'
                        , N'@DatabaseId int, @FileId int, @FileName sysname OUTPUT'
                        , @DatabaseId = @ResolutionDatabaseId
                        , @FileId = @ResolutionFileId
                        , @FileName = @ResolutionFileName OUTPUT;
                END TRY
                BEGIN CATCH
                    IF @ResolutionFirstErrorNumber IS NULL
                    BEGIN
                        SELECT
                              @ResolutionFirstErrorNumber = ERROR_NUMBER()
                            , @ResolutionFirstErrorMessage = ERROR_MESSAGE()
                            , @ResolutionFirstErrorScope = N'FILE';
                    END;
                END CATCH;

                IF @ResolutionFormatCode = 'NAMED_RESOURCE'
                BEGIN TRY
                    EXEC [sys].[sp_executesql]
                          N'SET LOCK_TIMEOUT 0;
                            SELECT TOP (1)
                                  @ResourceType = N''LINKED_SERVER''
                                , @ResourceName = CONCAT(N''Linked Server '', QUOTENAME([s].[name]))
                            FROM [sys].[servers] AS [s] WITH (NOLOCK)
                            WHERE LEFT(@Qualifier, LEN([s].[name])) = [s].[name]
                              AND
                              (
                                  LEN(@Qualifier) = LEN([s].[name])
                                  OR SUBSTRING(@Qualifier, LEN([s].[name]) + 1, 1) IN (N'' '', N''('')
                              )
                            ORDER BY LEN([s].[name]) DESC, [s].[server_id];'
                        , N'@Qualifier nvarchar(512), @ResourceType nvarchar(60) OUTPUT, @ResourceName nvarchar(1024) OUTPUT'
                        , @Qualifier = @ResolutionQualifier
                        , @ResourceType = @ResolutionResourceType OUTPUT
                        , @ResourceName = @ResolutionResourceName OUTPUT;
                END TRY
                BEGIN CATCH
                    IF @ResolutionFirstErrorNumber IS NULL
                    BEGIN
                        SELECT
                              @ResolutionFirstErrorNumber = ERROR_NUMBER()
                            , @ResolutionFirstErrorMessage = ERROR_MESSAGE()
                            , @ResolutionFirstErrorScope = N'LINKED_SERVER';
                    END;
                END CATCH;

                IF @ResolutionResourceType IN (N'PAGE', N'RID', N'EXTENT')
                   AND @ResolutionDatabaseId IS NOT NULL
                   AND @ResolutionFileId IS NOT NULL
                   AND @ResolutionPageId IS NOT NULL
                BEGIN TRY
                    EXEC [sys].[sp_executesql]
                          N'SET LOCK_TIMEOUT 0;
                            SELECT
                                  @ObjectId = [p].[object_id]
                                , @IndexId = [p].[index_id]
                                , @PartitionId = [p].[partition_id]
                                , @PageTypeDesc = [p].[page_type_desc]
                            FROM [sys].[dm_db_page_info]
                            (
                                  @DatabaseId
                                , @FileId
                                , @PageId
                                , ''LIMITED''
                            ) AS [p];'
                        , N'@DatabaseId int, @FileId int, @PageId int,
                            @ObjectId int OUTPUT, @IndexId int OUTPUT,
                            @PartitionId bigint OUTPUT, @PageTypeDesc nvarchar(60) OUTPUT'
                        , @DatabaseId = @ResolutionDatabaseId
                        , @FileId = @ResolutionFileId
                        , @PageId = @ResolutionPageIdInt
                        , @ObjectId = @ResolutionObjectId OUTPUT
                        , @IndexId = @ResolutionIndexId OUTPUT
                        , @PartitionId = @ResolutionPartitionId OUTPUT
                        , @PageTypeDesc = @ResolutionPageTypeDesc OUTPUT;
                END TRY
                BEGIN CATCH
                    IF @ResolutionFirstErrorNumber IS NULL
                    BEGIN
                        SELECT
                              @ResolutionFirstErrorNumber = ERROR_NUMBER()
                            , @ResolutionFirstErrorMessage = ERROR_MESSAGE()
                            , @ResolutionFirstErrorScope = N'PAGE';
                    END;
                END CATCH;

                SET @ResolutionSql = NULL;

                IF @ResolutionDatabaseName IS NOT NULL
                   AND @ResolutionDatabaseState = 0
                BEGIN
                    IF @ResolutionResourceType = N'OBJECT'
                        SET @ResolutionSql = N'
                            SELECT
                                  @SchemaName = [s].[name]
                                , @ObjectId = [o].[object_id]
                                , @ObjectName = [o].[name]
                            FROM ' + QUOTENAME(@ResolutionDatabaseName) + N'.[sys].[objects] AS [o] WITH (NOLOCK)
                            JOIN ' + QUOTENAME(@ResolutionDatabaseName) + N'.[sys].[schemas] AS [s] WITH (NOLOCK)
                              ON [s].[schema_id] = [o].[schema_id]
                            WHERE [o].[object_id] = TRY_CONVERT(int, @EntityId);';
                    ELSE IF @ResolutionResourceType IN (N'KEY', N'HOBT', N'OIB', N'XACT')
                            OR
                            (
                                @ResolutionResourceType IN (N'PAGE', N'RID', N'EXTENT')
                                AND @ResolutionObjectId IS NULL
                                AND @ResolutionEntityId IS NOT NULL
                            )
                        SET @ResolutionSql = N'
                            SELECT TOP (1)
                                  @SchemaName = [s].[name]
                                , @ObjectId = [o].[object_id]
                                , @ObjectName = [o].[name]
                                , @IndexId = [i].[index_id]
                                , @IndexName = [i].[name]
                                , @PartitionId = [p].[partition_id]
                                , @PartitionNumber = [p].[partition_number]
                            FROM ' + QUOTENAME(@ResolutionDatabaseName) + N'.[sys].[partitions] AS [p] WITH (NOLOCK)
                            JOIN ' + QUOTENAME(@ResolutionDatabaseName) + N'.[sys].[objects] AS [o] WITH (NOLOCK)
                              ON [o].[object_id] = [p].[object_id]
                            JOIN ' + QUOTENAME(@ResolutionDatabaseName) + N'.[sys].[schemas] AS [s] WITH (NOLOCK)
                              ON [s].[schema_id] = [o].[schema_id]
                            LEFT JOIN ' + QUOTENAME(@ResolutionDatabaseName) + N'.[sys].[indexes] AS [i] WITH (NOLOCK)
                              ON [i].[object_id] = [p].[object_id]
                             AND [i].[index_id] = [p].[index_id]
                            WHERE [p].[hobt_id] = @EntityId;';
                    ELSE IF @ResolutionResourceType IN (N'PAGE', N'RID', N'EXTENT')
                            AND @ResolutionObjectId IS NOT NULL
                        SET @ResolutionSql = N'
                            SELECT
                                  @SchemaName = [s].[name]
                                , @ObjectName = [o].[name]
                                , @IndexName = [i].[name]
                                , @PartitionNumber = [p].[partition_number]
                            FROM ' + QUOTENAME(@ResolutionDatabaseName) + N'.[sys].[objects] AS [o] WITH (NOLOCK)
                            JOIN ' + QUOTENAME(@ResolutionDatabaseName) + N'.[sys].[schemas] AS [s] WITH (NOLOCK)
                              ON [s].[schema_id] = [o].[schema_id]
                            LEFT JOIN ' + QUOTENAME(@ResolutionDatabaseName) + N'.[sys].[indexes] AS [i] WITH (NOLOCK)
                              ON [i].[object_id] = @PageObjectId
                             AND [i].[index_id] = @PageIndexId
                            LEFT JOIN ' + QUOTENAME(@ResolutionDatabaseName) + N'.[sys].[partitions] AS [p] WITH (NOLOCK)
                              ON [p].[partition_id] = @PagePartitionId
                            WHERE [o].[object_id] = @PageObjectId;';
                    ELSE IF @ResolutionResourceType = N'ALLOCATION_UNIT'
                        SET @ResolutionSql = N'
                            SELECT TOP (1)
                                  @SchemaName = [s].[name]
                                , @ObjectId = [o].[object_id]
                                , @ObjectName = [o].[name]
                                , @IndexId = [i].[index_id]
                                , @IndexName = [i].[name]
                                , @PartitionId = [p].[partition_id]
                                , @PartitionNumber = [p].[partition_number]
                            FROM ' + QUOTENAME(@ResolutionDatabaseName) + N'.[sys].[allocation_units] AS [a] WITH (NOLOCK)
                            LEFT JOIN ' + QUOTENAME(@ResolutionDatabaseName) + N'.[sys].[partitions] AS [p] WITH (NOLOCK)
                              ON [a].[container_id] = CASE WHEN [a].[type] = 2 THEN [p].[partition_id] ELSE [p].[hobt_id] END
                            LEFT JOIN ' + QUOTENAME(@ResolutionDatabaseName) + N'.[sys].[objects] AS [o] WITH (NOLOCK)
                              ON [o].[object_id] = [p].[object_id]
                            LEFT JOIN ' + QUOTENAME(@ResolutionDatabaseName) + N'.[sys].[schemas] AS [s] WITH (NOLOCK)
                              ON [s].[schema_id] = [o].[schema_id]
                            LEFT JOIN ' + QUOTENAME(@ResolutionDatabaseName) + N'.[sys].[indexes] AS [i] WITH (NOLOCK)
                              ON [i].[object_id] = [p].[object_id]
                             AND [i].[index_id] = [p].[index_id]
                            WHERE [a].[allocation_unit_id] = @EntityId;';
                    ELSE IF @ResolutionResourceType = N'METADATA'
                            AND @ResolutionMetadataSubtype = N'STATS'
                        SET @ResolutionSql = N'
                            SELECT
                                  @SchemaName = [s].[name]
                                , @ObjectId = [o].[object_id]
                                , @ObjectName = [o].[name]
                                , @MetadataName = [st].[name]
                            FROM ' + QUOTENAME(@ResolutionDatabaseName) + N'.[sys].[objects] AS [o] WITH (NOLOCK)
                            JOIN ' + QUOTENAME(@ResolutionDatabaseName) + N'.[sys].[schemas] AS [s] WITH (NOLOCK)
                              ON [s].[schema_id] = [o].[schema_id]
                            LEFT JOIN ' + QUOTENAME(@ResolutionDatabaseName) + N'.[sys].[stats] AS [st] WITH (NOLOCK)
                              ON [st].[object_id] = [o].[object_id]
                             AND [st].[stats_id] = TRY_CONVERT(int, @SubEntityId)
                            WHERE [o].[object_id] = TRY_CONVERT(int, @EntityId);';
                    ELSE IF @ResolutionResourceType = N'METADATA'
                            AND @ResolutionMetadataSubtype = N'SCHEMA'
                        SET @ResolutionSql = N'
                            SELECT @SchemaName = [s].[name]
                            FROM ' + QUOTENAME(@ResolutionDatabaseName) + N'.[sys].[schemas] AS [s] WITH (NOLOCK)
                            WHERE [s].[schema_id] = TRY_CONVERT(int, @EntityId);';
                END;

                IF @ResolutionSql IS NOT NULL
                BEGIN TRY
                    SET @ResolutionSql = N'SET LOCK_TIMEOUT 0;' + @ResolutionSql;
                    EXEC [sys].[sp_executesql]
                          @ResolutionSql
                        , N'@EntityId bigint, @SubEntityId bigint,
                            @PageObjectId int, @PageIndexId int, @PagePartitionId bigint,
                            @SchemaName sysname OUTPUT, @ObjectId int OUTPUT,
                            @ObjectName sysname OUTPUT, @IndexId int OUTPUT,
                            @IndexName sysname OUTPUT, @PartitionId bigint OUTPUT,
                            @PartitionNumber int OUTPUT, @MetadataName sysname OUTPUT'
                        , @EntityId = @ResolutionEntityId
                        , @SubEntityId = @ResolutionSubEntityId
                        , @PageObjectId = @ResolutionObjectId
                        , @PageIndexId = @ResolutionIndexId
                        , @PagePartitionId = @ResolutionPartitionId
                        , @SchemaName = @ResolutionSchemaName OUTPUT
                        , @ObjectId = @ResolutionObjectId OUTPUT
                        , @ObjectName = @ResolutionObjectName OUTPUT
                        , @IndexId = @ResolutionIndexId OUTPUT
                        , @IndexName = @ResolutionIndexName OUTPUT
                        , @PartitionId = @ResolutionPartitionId OUTPUT
                        , @PartitionNumber = @ResolutionPartitionNumber OUTPUT
                        , @MetadataName = @ResolutionMetadataName OUTPUT;
                END TRY
                BEGIN CATCH
                    IF @ResolutionFirstErrorNumber IS NULL
                    BEGIN
                        SELECT
                              @ResolutionFirstErrorNumber = ERROR_NUMBER()
                            , @ResolutionFirstErrorMessage = ERROR_MESSAGE()
                            , @ResolutionFirstErrorScope = N'CATALOG';
                    END;
                END CATCH;

                UPDATE [r]
                SET
                      [ResourceType] = @ResolutionResourceType
                    , [DatabaseName] = @ResolutionDatabaseName
                    , [FileName] = @ResolutionFileName
                    , [SchemaName] = @ResolutionSchemaName
                    , [ObjectId] = @ResolutionObjectId
                    , [ObjectName] = @ResolutionObjectName
                    , [IndexId] = @ResolutionIndexId
                    , [IndexName] = @ResolutionIndexName
                    , [PartitionId] = @ResolutionPartitionId
                    , [PartitionNumber] = @ResolutionPartitionNumber
                    , [PageTypeDesc] = @ResolutionPageTypeDesc
                    , [MetadataName] = @ResolutionMetadataName
                    , [ResourceName] = @ResolutionResourceName
                    , [ResolutionStatus] =
                        CASE
                            WHEN @ResolutionFirstErrorNumber IS NULL THEN [r].[ResolutionStatus]
                            WHEN @ResolutionFirstErrorNumber IN (229, 262, 297, 300, 371, 916)
                                THEN 'DENIED_PERMISSION'
                            WHEN @ResolutionFirstErrorNumber = 1222 THEN 'TIMEOUT'
                            ELSE 'ERROR_HANDLED'
                        END
                FROM [#CurrentBlocking_ResourceResolution] AS [r]
                WHERE [r].[CandidateId] = @ResolutionCandidateId;

                IF @ResolutionFirstErrorNumber IS NOT NULL
                BEGIN
                    SET @ObjectResolutionStatusCode = 'AVAILABLE_LIMITED';
                    SET @IsPartial = 1;

                    INSERT [#CurrentBlocking_Warnings]
                    ([ScopeName], [StatusCode], [ErrorNumber], [ErrorMessage])
                    VALUES
                    (
                          CONCAT(N'BlockingResource:', @ResolutionCandidateId, N':', @ResolutionFirstErrorScope)
                        , CASE WHEN @ResolutionFirstErrorNumber IN (229, 262, 297, 300, 371, 916)
                               THEN 'DENIED_PERMISSION'
                               WHEN @ResolutionFirstErrorNumber = 1222 THEN 'TIMEOUT'
                               ELSE 'ERROR_HANDLED' END
                        , @ResolutionFirstErrorNumber
                        , @ResolutionFirstErrorMessage
                    );
                END;

                FETCH NEXT FROM [CurrentBlocking_ResolutionCandidateCursor]
                INTO
                      @ResolutionCandidateId, @ResolutionResourceType, @ResolutionFormatCode
                    , @ResolutionDatabaseId, @ResolutionDatabaseName, @ResolutionEntityId
                    , @ResolutionSubEntityId, @ResolutionFileId, @ResolutionFileName
                    , @ResolutionPageId, @ResolutionRowId, @ResolutionMetadataSubtype
                    , @ResolutionQualifier, @ResolutionSchemaName, @ResolutionObjectId
                    , @ResolutionObjectName, @ResolutionIndexId, @ResolutionIndexName
                    , @ResolutionPartitionId, @ResolutionPartitionNumber
                    , @ResolutionPageTypeDesc, @ResolutionMetadataName
                    , @ResolutionResourceName;
            END;

            CLOSE [CurrentBlocking_ResolutionCandidateCursor];
            DEALLOCATE [CurrentBlocking_ResolutionCandidateCursor];

            UPDATE [r]
            SET
                  [ResourceName] =
                    CASE
                        WHEN [r].[ResourceName] IS NOT NULL THEN [r].[ResourceName]
                        WHEN [r].[ResourceType] = N'DATABASE' AND [r].[DatabaseName] IS NOT NULL
                            THEN QUOTENAME([r].[DatabaseName])
                        WHEN [r].[ResourceType] = N'FILE' AND [r].[DatabaseName] IS NOT NULL
                            THEN CONCAT(QUOTENAME([r].[DatabaseName]), N' / FILE ', [r].[FileId],
                                        CASE WHEN [r].[FileName] IS NOT NULL THEN CONCAT(N' ', QUOTENAME([r].[FileName])) ELSE N'' END)
                        WHEN [r].[FormatCode] = 'LOCK_DMV' AND [r].[ResourceType] = N'XACT'
                             AND [r].[ObjectName] IS NOT NULL
                            THEN CONCAT
                                 (
                                      QUOTENAME([r].[DatabaseName]), N'.'
                                    , QUOTENAME([r].[SchemaName]), N'.', QUOTENAME([r].[ObjectName])
                                    , CASE WHEN [r].[IndexName] IS NOT NULL
                                           THEN CONCAT(N' / INDEX ', QUOTENAME([r].[IndexName])) ELSE N'' END
                                    , N' / XACT ', COALESCE([r].[ResourceQualifier], N'')
                                    , N' / underlying HOBT ', [r].[EntityId]
                                 )
                        WHEN [r].[ObjectName] IS NOT NULL
                            THEN CONCAT
                                 (
                                      QUOTENAME([r].[DatabaseName]), N'.'
                                    , QUOTENAME([r].[SchemaName]), N'.', QUOTENAME([r].[ObjectName])
                                    , CASE WHEN [r].[IndexName] IS NOT NULL
                                           THEN CONCAT(N' / INDEX ', QUOTENAME([r].[IndexName])) ELSE N'' END
                                    , CASE WHEN [r].[MetadataName] IS NOT NULL
                                           THEN CONCAT(N' / STATISTICS ', QUOTENAME([r].[MetadataName])) ELSE N'' END
                                    , CASE WHEN [r].[PartitionNumber] IS NOT NULL
                                           THEN CONCAT(N' / PARTITION ', [r].[PartitionNumber]) ELSE N'' END
                                    , CASE WHEN [r].[PageId] IS NOT NULL
                                           THEN CONCAT(N' / PAGE ', [r].[FileId], N':', [r].[PageId]) ELSE N'' END
                                    , CASE WHEN [r].[PageTypeDesc] IS NOT NULL
                                           THEN CONCAT(N' / ', [r].[PageTypeDesc]) ELSE N'' END
                                    , CASE WHEN [r].[RowId] IS NOT NULL
                                           THEN CONCAT(N' / ROW ', [r].[RowId]) ELSE N'' END
                                 )
                        WHEN [r].[ResourceType] = N'METADATA' AND [r].[MetadataSubtype] = N'SCHEMA'
                             AND [r].[SchemaName] IS NOT NULL
                            THEN CONCAT(QUOTENAME([r].[DatabaseName]), N'.', QUOTENAME([r].[SchemaName]), N' / METADATA SCHEMA')
                        WHEN [r].[ResourceType] IN (N'PAGE', N'RID', N'EXTENT') AND [r].[DatabaseName] IS NOT NULL
                            THEN CONCAT
                                 (
                                      QUOTENAME([r].[DatabaseName]), N' / PAGE ', [r].[FileId], N':', [r].[PageId]
                                    , CASE WHEN [r].[PageTypeDesc] IS NOT NULL THEN CONCAT(N' / ', [r].[PageTypeDesc]) ELSE N'' END
                                    , CASE WHEN [r].[RowId] IS NOT NULL THEN CONCAT(N' / ROW ', [r].[RowId]) ELSE N'' END
                                 )
                        WHEN [r].[ResourceType] = N'APPLICATION'
                            THEN CONCAT(COALESCE(QUOTENAME([r].[DatabaseName]) + N' / ', N''), N'APPLICATION ', COALESCE([r].[ResourceQualifier], N''))
                        WHEN [r].[ResourceType] = N'XACT'
                            THEN CONCAT
                                 (
                                      COALESCE(QUOTENAME([r].[DatabaseName]) + N' / ', N'')
                                    , N'XACT ', COALESCE([r].[ResourceQualifier], N'')
                                    , CASE WHEN COALESCE([r].[EntityId], 0) <> 0
                                           THEN CONCAT(N' / underlying HOBT ', [r].[EntityId]) ELSE N'' END
                                 )
                        WHEN [r].[ResourceType] = N'METADATA'
                            THEN CONCAT(COALESCE(QUOTENAME([r].[DatabaseName]) + N' / ', N''), N'METADATA ', COALESCE([r].[MetadataSubtype], N'OTHER'),
                                        CASE WHEN [r].[ResourceQualifier] IS NOT NULL THEN CONCAT(N' / ', [r].[ResourceQualifier]) ELSE N'' END)
                        WHEN [r].[DatabaseName] IS NOT NULL
                            THEN CONCAT(QUOTENAME([r].[DatabaseName]), N' / ', COALESCE([r].[ResourceType], N'RESOURCE'),
                                        CASE WHEN [r].[EntityId] IS NOT NULL THEN CONCAT(N' ', [r].[EntityId]) ELSE N'' END)
                        ELSE [r].[ResourceQualifier]
                    END
                , [ResolutionStatus] =
                    CASE
                        WHEN [r].[ResolutionStatus] IN
                             ('EMPTY', 'INVALID_FORMAT', 'TIMEOUT', 'DENIED_PERMISSION', 'ERROR_HANDLED')
                            THEN [r].[ResolutionStatus]
                        WHEN [r].[ResolutionStatus] = 'RAW_ONLY' AND [r].[ResourceName] IS NULL THEN 'RAW_ONLY'
                        WHEN [r].[ResourceType] = N'LINKED_SERVER' THEN 'RESOLVED'
                        WHEN [r].[ResourceType] IN (N'DATABASE', N'FILE') AND [r].[DatabaseName] IS NOT NULL THEN 'RESOLVED'
                        WHEN [r].[ResourceType] = N'XACT'
                             AND [r].[ResourceQualifier] IS NOT NULL THEN 'PARTIAL'
                        WHEN [r].[ObjectName] IS NOT NULL THEN 'RESOLVED'
                        WHEN [r].[ResourceType] = N'METADATA' AND [r].[MetadataSubtype] = N'SCHEMA'
                             AND [r].[SchemaName] IS NOT NULL THEN 'RESOLVED'
                        WHEN [r].[ResourceType] IN (N'PAGE', N'RID', N'EXTENT') AND [r].[PageTypeDesc] IS NOT NULL THEN 'RESOLVED'
                        WHEN [r].[ResourceType] = N'APPLICATION'
                             AND [r].[ResourceQualifier] IS NOT NULL THEN 'PARTIAL'
                        WHEN [r].[DatabaseName] IS NOT NULL OR [r].[ResourceType] IS NOT NULL THEN 'PARTIAL'
                        ELSE [r].[ResolutionStatus]
                    END
            FROM [#CurrentBlocking_ResourceResolution] AS [r];

            SELECT
                  @ObjectResolutionResolvedCount = COALESCE(SUM(CASE WHEN [ResolutionStatus] = 'RESOLVED' THEN CONVERT(bigint, 1) ELSE 0 END), 0)
                , @ObjectResolutionPartialCount = COALESCE(SUM(CASE WHEN [ResolutionStatus] = 'PARTIAL' THEN CONVERT(bigint, 1) ELSE 0 END), 0)
                , @ObjectResolutionRawOnlyCount = COALESCE(SUM(CASE WHEN [ResolutionStatus] IN ('RAW_ONLY', 'INVALID_FORMAT', 'EMPTY') THEN CONVERT(bigint, 1) ELSE 0 END), 0)
                , @ObjectResolutionTimeoutCount = COALESCE(SUM(CASE WHEN [ResolutionStatus] = 'TIMEOUT' THEN CONVERT(bigint, 1) ELSE 0 END), 0)
                , @ObjectResolutionDeniedCount = COALESCE(SUM(CASE WHEN [ResolutionStatus] = 'DENIED_PERMISSION' THEN CONVERT(bigint, 1) ELSE 0 END), 0)
                , @ObjectResolutionErrorCount = COALESCE(SUM(CASE WHEN [ResolutionStatus] = 'ERROR_HANDLED' THEN CONVERT(bigint, 1) ELSE 0 END), 0)
            FROM [#CurrentBlocking_ResourceResolution];

            SET @ObjectResolutionSkippedLimitCount =
                CASE WHEN @ObjectResolutionTotalCount > @ObjectResolutionCandidateCount
                     THEN @ObjectResolutionTotalCount - @ObjectResolutionCandidateCount ELSE 0 END;

            UPDATE [c]
            SET
                  [BlockingResourceType] = [r].[ResourceType]
                , [BlockingResourceDatabaseId] = [r].[DatabaseId]
                , [BlockingResourceDatabaseName] = [r].[DatabaseName]
                , [BlockingResourceSchemaName] = [r].[SchemaName]
                , [BlockingResourceObjectId] = [r].[ObjectId]
                , [BlockingResourceObjectName] = [r].[ObjectName]
                , [BlockingResourceIndexId] = [r].[IndexId]
                , [BlockingResourceIndexName] = [r].[IndexName]
                , [BlockingResourcePartitionId] = [r].[PartitionId]
                , [BlockingResourcePartitionNumber] = [r].[PartitionNumber]
                , [BlockingResourceFileId] = [r].[FileId]
                , [BlockingResourcePageId] = [r].[PageId]
                , [BlockingResourceRowId] = [r].[RowId]
                , [BlockingResourceMetadataSubtype] = [r].[MetadataSubtype]
                , [BlockingResourceMetadataName] = [r].[MetadataName]
                , [BlockingResourcePageTypeDesc] = [r].[PageTypeDesc]
                , [BlockingResourceName] = [r].[ResourceName]
                , [BlockingResourceResolutionStatus] = [r].[ResolutionStatus]
            FROM [#CurrentBlocking_BlockingChains] AS [c]
            JOIN [#CurrentBlocking_ResourceResolution] AS [r]
              ON [r].[SourceCode] = 'WAIT_RESOURCE'
             AND [r].[WaitResource] = [c].[WaitResource];

            UPDATE [c]
            SET [BlockingResourceResolutionStatus] =
                CASE WHEN NULLIF(LTRIM(RTRIM([c].[WaitResource])), N'') IS NULL THEN 'EMPTY'
                     ELSE 'SKIPPED_LIMIT' END
            FROM [#CurrentBlocking_BlockingChains] AS [c]
            WHERE [c].[BlockingResourceResolutionStatus] IS NULL;

            UPDATE [l]
            SET
                  [ResourceDatabaseName] = [r].[DatabaseName]
                , [ResolvedResourceType] = [r].[ResourceType]
                , [ResolvedSchemaName] = [r].[SchemaName]
                , [ResolvedObjectId] = [r].[ObjectId]
                , [ResolvedObjectName] = [r].[ObjectName]
                , [ResolvedIndexId] = [r].[IndexId]
                , [ResolvedIndexName] = [r].[IndexName]
                , [ResolvedPartitionId] = [r].[PartitionId]
                , [ResolvedPartitionNumber] = [r].[PartitionNumber]
                , [ResolvedResourceName] = [r].[ResourceName]
                , [ResourceResolutionStatus] = [r].[ResolutionStatus]
            FROM [#CurrentBlocking_Locks] AS [l]
            CROSS APPLY
            (
                SELECT TOP (1) [x].*
                FROM [#CurrentBlocking_ResourceResolution] AS [x]
                WHERE [x].[SourceCode] = 'LOCK_DMV'
                  AND COALESCE([x].[ResourceType], N'') = COALESCE(UPPER([l].[ResourceType]), N'')
                  AND COALESCE([x].[DatabaseId], -1) = COALESCE([l].[ResourceDatabaseId], -1)
                  AND COALESCE([x].[EntityId], -1) = COALESCE([l].[ResourceAssociatedEntityId], -1)
                  AND COALESCE([x].[MetadataSubtype], N'') = COALESCE([l].[ResourceSubtype], N'')
                  AND COALESCE([x].[ResourceQualifier], N'') = COALESCE([l].[ResourceDescription], N'')
                ORDER BY [x].[CandidateId]
            ) AS [r];

            UPDATE [l]
            SET [ResourceResolutionStatus] = 'SKIPPED_LIMIT'
            FROM [#CurrentBlocking_Locks] AS [l]
            WHERE [l].[ResourceResolutionStatus] IS NULL;
        END;
        ELSE
        BEGIN
            UPDATE [#CurrentBlocking_BlockingChains]
            SET [BlockingResourceResolutionStatus] = 'SKIPPED';

            UPDATE [#CurrentBlocking_Locks]
            SET [ResourceResolutionStatus] = 'SKIPPED';
        END;

        DECLARE @TruncatedValueCount bigint=0,@LargestRequiredCharacters bigint=NULL;
        DECLARE @ColumnTruncatedCount bigint=0,@ColumnLargestCharacters bigint=NULL;
        EXEC [monitor].[InternalProjectUnicodeTextColumn]
              @SourceTable=N'#CurrentBlocking_BlockingChains',@TextColumn=N'BlockedStatement'
            , @CharactersColumn=N'BlockedStatementCharacters',@BytesColumn=N'BlockedStatementBytes'
            , @IsTruncatedColumn=N'BlockedStatementIsTruncated',@MaxCharacters=@MaxSqlTextZeichen
            , @TruncatedValueCount=@ColumnTruncatedCount OUTPUT,@LargestRequiredCharacters=@ColumnLargestCharacters OUTPUT;
        SELECT @TruncatedValueCount=@TruncatedValueCount+@ColumnTruncatedCount,
               @LargestRequiredCharacters=CASE WHEN @LargestRequiredCharacters IS NULL OR @ColumnLargestCharacters>@LargestRequiredCharacters THEN @ColumnLargestCharacters ELSE @LargestRequiredCharacters END;
        EXEC [monitor].[InternalProjectUnicodeTextColumn]
              @SourceTable=N'#CurrentBlocking_BlockingChains',@TextColumn=N'BlockerStatement'
            , @CharactersColumn=N'BlockerStatementCharacters',@BytesColumn=N'BlockerStatementBytes'
            , @IsTruncatedColumn=N'BlockerStatementIsTruncated',@MaxCharacters=@MaxSqlTextZeichen
            , @TruncatedValueCount=@ColumnTruncatedCount OUTPUT,@LargestRequiredCharacters=@ColumnLargestCharacters OUTPUT;
        SELECT @TruncatedValueCount=@TruncatedValueCount+@ColumnTruncatedCount,
               @LargestRequiredCharacters=CASE WHEN @LargestRequiredCharacters IS NULL OR @ColumnLargestCharacters>@LargestRequiredCharacters THEN @ColumnLargestCharacters ELSE @LargestRequiredCharacters END;
        EXEC [monitor].[InternalProjectUnicodeTextColumn]
              @SourceTable=N'#CurrentBlocking_BlockingChains',@TextColumn=N'RootBlockerStatement'
            , @CharactersColumn=N'RootBlockerStatementCharacters',@BytesColumn=N'RootBlockerStatementBytes'
            , @IsTruncatedColumn=N'RootBlockerStatementIsTruncated',@MaxCharacters=@MaxSqlTextZeichen
            , @TruncatedValueCount=@ColumnTruncatedCount OUTPUT,@LargestRequiredCharacters=@ColumnLargestCharacters OUTPUT;
        SELECT @TruncatedValueCount=@TruncatedValueCount+@ColumnTruncatedCount,
               @LargestRequiredCharacters=CASE WHEN @LargestRequiredCharacters IS NULL OR @ColumnLargestCharacters>@LargestRequiredCharacters THEN @ColumnLargestCharacters ELSE @LargestRequiredCharacters END;
        EXEC [monitor].[InternalEmitTruncationWarning]
              @TruncatedValueCount=@TruncatedValueCount,@ParameterName=N'@MaxSqlTextZeichen'
            , @ParameterValue=@MaxSqlTextZeichen,@LargestRequiredCharacters=@LargestRequiredCharacters
            , @PrintMeldungen=@PrintMeldungen;
    END TRY
    BEGIN CATCH
        SET @ErrorNumber = ERROR_NUMBER();
        SET @ErrorMessage = ERROR_MESSAGE();
        SET @IsPartial = 1;
        SET @StatusCode = CASE WHEN @ErrorNumber IN (229, 262, 297, 300, 371, 916)
                               THEN 'DENIED_PERMISSION'
                               WHEN @ErrorNumber = 1222 THEN 'TIMEOUT'
                               WHEN @ParentCurrentStateSnapshotId IS NOT NULL
                                AND @ErrorNumber IN (208, 51020) THEN 'INVALID_PARENT_SNAPSHOT'
                               ELSE 'ERROR_HANDLED' END;
    END CATCH;

    IF @IsPartial = 1 AND @StatusCode = 'AVAILABLE'
        SET @StatusCode = 'AVAILABLE_LIMITED';

    IF @PrintMeldungen = 1 AND @StatusCode NOT IN ('AVAILABLE', 'AVAILABLE_LIMITED')
    BEGIN
        SET @Message = FORMATMESSAGE(N'WARNUNG USP_CurrentBlocking [%s]: %s', @StatusCode, COALESCE(@ErrorMessage, N'Unbekannter Fehler.'));
        RAISERROR(N'%s', 10, 1, @Message) WITH NOWAIT;
    END;

    IF @ResultSetArtNormalisiert <> 'NONE'
    BEGIN
        SELECT
              N'USP_CurrentBlocking' AS [ModuleName]
            , @CollectionTimeUtc AS [CollectionTimeUtc]
            , @EvidenceSnapshotStartedAtUtc AS [EvidenceSnapshotStartedAtUtc]
            , @EvidenceSnapshotId AS [EvidenceSnapshotId]
            , @StatusCode AS [StatusCode]
            , @IsPartial AS [IsPartial]
            , CASE WHEN @MainCandidateCount > @EffectiveMaxZeilen
                   THEN @EffectiveMaxZeilen ELSE @MainCandidateCount END AS [ReturnedRowCount]
            , @HasMoreRows AS [HasMoreRows]
            , @ToolHintergrundabfragenEinbeziehen AS [ToolBackgroundQueriesIncluded]
            , @LockStatusCode AS [LockStatusCode]
            , @BlockingObjektTiefeNormalisiert AS [BlockingObjectDepth]
            , @ObjectResolutionStatusCode AS [ObjectResolutionStatusCode]
            , @ObjectResolutionCandidateCount AS [ObjectResolutionCandidateCount]
            , @ObjectResolutionTotalCount AS [ObjectResolutionTotalCount]
            , @ObjectResolutionHasMoreRows AS [ObjectResolutionHasMoreRows]
            , @ObjectResolutionResolvedCount AS [ObjectResolutionResolvedCount]
            , @ObjectResolutionPartialCount AS [ObjectResolutionPartialCount]
            , @ObjectResolutionRawOnlyCount AS [ObjectResolutionRawOnlyCount]
            , @ObjectResolutionTimeoutCount AS [ObjectResolutionTimeoutCount]
            , @ObjectResolutionDeniedCount AS [ObjectResolutionDeniedCount]
            , @ObjectResolutionErrorCount AS [ObjectResolutionErrorCount]
            , @ObjectResolutionSkippedLimitCount AS [ObjectResolutionSkippedLimitCount]
            , @RequiredPermission AS [RequiredPermission]
            , @ErrorNumber AS [ErrorNumber]
            , @ErrorMessage AS [ErrorMessage];

        IF @ResultSetArtNormalisiert = 'RAW'
        BEGIN
            SELECT TOP (@EffectiveMaxZeilen)
                  [LeafSessionId], [BlockedSessionId], [BlockingSessionId]
                , [RootBlockingSessionId], [BlockingOwnerType], [BlockingOwnerDescription]
                , [BlockingChain], [ChainDepth], [IsCycle]
                , [WaitType], [WaitTimeMs], [WaitResource]
                , [BlockingResourceType], [BlockingResourceDatabaseId], [BlockingResourceDatabaseName]
                , [BlockingResourceSchemaName], [BlockingResourceObjectId], [BlockingResourceObjectName]
                , [BlockingResourceIndexId], [BlockingResourceIndexName]
                , [BlockingResourcePartitionId], [BlockingResourcePartitionNumber]
                , [BlockingResourceFileId], [BlockingResourcePageId], [BlockingResourceRowId]
                , [BlockingResourceMetadataSubtype], [BlockingResourceMetadataName]
                , [BlockingResourcePageTypeDesc]
                , [BlockingResourceName], [BlockingResourceResolutionStatus]
                , [BlockedLoginName], [BlockedHostName], [BlockedProgramName]
                , [BlockedIsToolBackgroundQuery], [BlockedToolBackgroundRuleCode]
                , [BlockedToolBackgroundCategory], [BlockedToolBackgroundDetection]
                , [BlockedToolBackgroundConfidence]
                , [BlockerLoginName], [BlockerHostName], [BlockerProgramName]
                , [RootBlockerLoginName], [RootBlockerHostName], [RootBlockerProgramName]
                , [RootBlockerSessionStatus], [RootBlockerRequestStatus]
                , [RootBlockerOpenTransactionCount]
                , [RootBlockerLastRequestStartTime], [RootBlockerLastRequestEndTime]
                , [RootIsToolBackgroundQuery], [RootToolBackgroundRuleCode]
                , [RootToolBackgroundCategory], [RootToolBackgroundDetection]
                , [RootToolBackgroundConfidence]
                , [BlockedStatementCharacters], [BlockedStatementBytes], [BlockedStatementIsTruncated], [BlockedStatement]
                , [BlockerStatementCharacters], [BlockerStatementBytes], [BlockerStatementIsTruncated], [BlockerStatement]
                , [RootBlockerStatementSource]
                , [RootBlockerStatementCharacters], [RootBlockerStatementBytes], [RootBlockerStatementIsTruncated], [RootBlockerStatement]
            FROM [#CurrentBlocking_BlockingChains]
            ORDER BY [WaitTimeMs] DESC, [BlockedSessionId];

            IF @MitLockDetails = 1
            BEGIN
                SELECT TOP (@EffectiveMaxZeilen)
                      [SessionId], [ResourceType], [ResourceDatabaseId]
                    , [ResourceDatabaseName], [ResourceDescription], [ResourceSubtype]
                    , [ResourceAssociatedEntityId], [ResourceLockPartition]
                    , [RequestMode], [RequestStatus], [RequestOwnerType]
                    , [RequestReferenceCount], [LockOwnerAddress]
                    , [ResolvedResourceType], [ResolvedSchemaName]
                    , [ResolvedObjectId], [ResolvedObjectName]
                    , [ResolvedIndexId], [ResolvedIndexName]
                    , [ResolvedPartitionId], [ResolvedPartitionNumber]
                    , [ResolvedResourceName], [ResourceResolutionStatus]
                FROM [#CurrentBlocking_Locks]
                ORDER BY [SessionId], [ResourceDatabaseId], [ResourceType], [RequestMode];
            END;
        END
        ELSE
        BEGIN
            SELECT TOP (@EffectiveMaxZeilen)
                  N'Blocking-Kette' AS [Ergebnis]
                , [BlockedSessionId] AS [Blockierte Session]
                , [BlockingSessionId] AS [Blockierende Session]
                , [RootBlockingSessionId] AS [Root Blocker]
                , [BlockingChain] AS [Blocker-Kette]
                , [BlockingOwnerType] AS [Blocker-Typ]
                , [BlockingOwnerDescription] AS [Blocker-Typbeschreibung]
                , [ChainDepth] AS [Kettentiefe]
                , CASE WHEN [IsCycle] = 1 THEN N'Ja' ELSE N'Nein' END AS [Zyklus]
                , [WaitType] AS [Wait]
                , CONCAT(CONVERT(varchar(30), [WaitTimeMs]), N' ms') AS [Wartezeit]
                , [WaitResource] AS [Wait-Ressource]
                , [BlockingResourceType] AS [Aufgelöster Ressourcentyp]
                , [BlockingResourceName] AS [Aufgelöste Blocking-Ressource]
                , [BlockingResourceResolutionStatus] AS [Auflösungsstatus]
                , [BlockedLoginName] AS [Blockierter Login]
                , [BlockedHostName] AS [Blockierter Host]
                , [BlockedProgramName] AS [Blockiertes Programm]
                , [BlockerLoginName] AS [Blocker Login]
                , [BlockerHostName] AS [Blocker Host]
                , [BlockerProgramName] AS [Blocker Programm]
                , [RootBlockerLoginName] AS [Root-Blocker Login]
                , [RootBlockerHostName] AS [Root-Blocker Host]
                , [RootBlockerProgramName] AS [Root-Blocker Programm]
                , [RootBlockerSessionStatus] AS [Root-Blocker Sessionstatus]
                , [RootBlockerRequestStatus] AS [Root-Blocker Requeststatus]
                , [RootBlockerOpenTransactionCount] AS [Root-Blocker offene Transaktionen]
                , [BlockedSessionId] AS [Session_SQL]
                , [BlockedStatement] AS [Blockiertes Statement]
                , [BlockerStatement] AS [Blocker Statement]
                , [RootBlockerStatementSource] AS [Root-Blocker Statementquelle]
                , [RootBlockerStatement] AS [Root-Blocker Statement]
            FROM [#CurrentBlocking_BlockingChains]
            ORDER BY [WaitTimeMs] DESC, [BlockedSessionId];

            IF @MitLockDetails = 1
            BEGIN
                SELECT TOP (@EffectiveMaxZeilen)
                      N'Lock der Blocking-Kette' AS [Ergebnis]
                    , [SessionId] AS [Session]
                    , [ResourceDatabaseName] AS [Datenbank]
                    , [ResourceType] AS [Ressourcentyp]
                    , [ResourceSubtype] AS [Ressourcenuntertyp]
                    , [ResourceDescription] AS [Ressource]
                    , [ResourceAssociatedEntityId] AS [Entitäts-ID]
                    , [ResolvedResourceName] AS [Aufgelöste Ressource]
                    , [ResourceResolutionStatus] AS [Auflösungsstatus]
                    , [RequestMode] AS [Lock-Modus]
                    , [RequestStatus] AS [Status]
                    , [RequestOwnerType] AS [Owner]
                    , [RequestReferenceCount] AS [Referenzen]
                FROM [#CurrentBlocking_Locks]
                ORDER BY [SessionId], [ResourceDatabaseId], [ResourceType], [RequestMode];
            END;
        END;

        SELECT [ScopeName], [StatusCode], [ErrorNumber], [ErrorMessage]
        FROM [#CurrentBlocking_Warnings]
        ORDER BY [ScopeName], [StatusCode];
    END;

    IF @JsonErzeugen = 1
    BEGIN
        DECLARE @MetaJson nvarchar(max) =
        (
            SELECT
                  N'CurrentBlocking' AS [resultName]
                , 3 AS [schemaVersion]
                , @CollectionTimeUtc AS [generatedAtUtc]
                , @EvidenceSnapshotStartedAtUtc AS [evidenceSnapshotStartedAtUtc]
                , @EvidenceSnapshotId AS [evidenceSnapshotId]
                , @IsPartial AS [isPartial]
                , @StatusCode AS [statusCode]
                , @MaxZeilen AS [requestedMaxRows]
                , CASE WHEN @MainCandidateCount > @EffectiveMaxZeilen
                       THEN @EffectiveMaxZeilen ELSE @MainCandidateCount END AS [returnedRows]
                , @HasMoreRows AS [hasMoreRows]
                , @LockStatusCode AS [lockStatusCode]
                , @BlockingObjektTiefeNormalisiert AS [blockingObjectDepth]
                , @ObjectResolutionStatusCode AS [objectResolutionStatusCode]
                , @ObjectResolutionCandidateCount AS [objectResolutionCandidateCount]
                , @ObjectResolutionTotalCount AS [objectResolutionTotalCount]
                , @ObjectResolutionHasMoreRows AS [objectResolutionHasMoreRows]
                , @ObjectResolutionResolvedCount AS [objectResolutionResolvedCount]
                , @ObjectResolutionPartialCount AS [objectResolutionPartialCount]
                , @ObjectResolutionRawOnlyCount AS [objectResolutionRawOnlyCount]
                , @ObjectResolutionTimeoutCount AS [objectResolutionTimeoutCount]
                , @ObjectResolutionDeniedCount AS [objectResolutionDeniedCount]
                , @ObjectResolutionErrorCount AS [objectResolutionErrorCount]
                , @ObjectResolutionSkippedLimitCount AS [objectResolutionSkippedLimitCount]
                , @ToolHintergrundabfragenEinbeziehen AS [toolBackgroundQueriesIncluded]
            FOR JSON PATH, WITHOUT_ARRAY_WRAPPER, INCLUDE_NULL_VALUES
        );
        DECLARE @ChainsJson nvarchar(max) =
        (
            SELECT TOP (@EffectiveMaxZeilen) *
            FROM [#CurrentBlocking_BlockingChains]
            ORDER BY [WaitTimeMs] DESC, [BlockedSessionId]
            FOR JSON PATH, INCLUDE_NULL_VALUES
        );
        DECLARE @LocksJson nvarchar(max) =
        (
            SELECT TOP (@EffectiveMaxZeilen) *
            FROM [#CurrentBlocking_Locks]
            ORDER BY [SessionId], [ResourceDatabaseId], [ResourceType], [RequestMode]
            FOR JSON PATH, INCLUDE_NULL_VALUES
        );
        DECLARE @WarningsJson nvarchar(max) =
        (
            SELECT *
            FROM [#CurrentBlocking_Warnings]
            ORDER BY [ScopeName], [StatusCode]
            FOR JSON PATH, INCLUDE_NULL_VALUES
        );

        SET @Json = CONCAT
        (
              N'{"meta":', COALESCE(@MetaJson, N'{}')
            , N',"blockingChains":', COALESCE(@ChainsJson, N'[]')
            , N',"locks":', COALESCE(@LocksJson, N'[]')
            , N',"warnings":', COALESCE(@WarningsJson, N'[]')
            , N'}'
        );
    END;
    IF @ConsoleResultRequested = 1
    BEGIN
        EXEC [monitor].[InternalEmitConsoleResult]
              @SourceTable=N'#CurrentBlocking_BlockingChains'
            , @ResultLabel=N'Blocking-Ketten'
            , @EmptyMessage=N'Keine Blocking-Ketten';
    END;
    IF @TableResultRequested = 1
    BEGIN
        EXEC [monitor].[InternalWriteResultTable]
              @SourceTable = N'#CurrentBlocking_BlockingChains'
            , @TargetTable=@TableTarget
            , @ThrowOnError = 1;
    END;
END;
GO
-- END SOURCE: Code/02_CurrentState/030_USP_CurrentBlocking.sql

-- BEGIN SOURCE: Code/02_CurrentState/040_USP_CurrentWaits.sql
/*
===============================================================================
Objekt       : monitor.USP_CurrentWaits
Version      : 4.0.0
Stand        : 2026-07-23
Zweck        : Liefert aktuelle Waiting Tasks sowie kumulativen oder
               gesampelten instanzweiten Wait-Kontext mit Listen- und
               Patternfiltern.
Ausgabe      : RAW, CONSOLE, NONE und optionales JSON mit currentTasks,
               instanceWaits und warnings.
===============================================================================
*/
CREATE OR ALTER PROCEDURE [monitor].[USP_CurrentWaits]
      @SessionIds                    nvarchar(max)  = NULL
    , @MinWaitMs                    bigint         = 0
    , @WaitTypes                    nvarchar(max)  = NULL
    , @WaitTypePattern              nvarchar(4000) = NULL
    , @WaitGroups                   nvarchar(max)  = NULL
    , @WaitGroupPattern             nvarchar(4000) = NULL
    , @SystemSessionsEinbeziehen    bit            = 0
    , @ToolHintergrundabfragenEinbeziehen bit       = 0
    , @MitSqlText                   bit            = 1
    , @MaxSqlTextZeichen            int            = 2000
    , @SampleSeconds                tinyint        = 0
    , @UnkritischeWaitsEinbeziehen  bit            = 0
    , @TopWaitPercentage            decimal(5,2)   = 95.00
    , @MaxZeilen                    int            = 1000
    , @ResultSetArt                 varchar(16)    = 'CONSOLE'
    , @ResultTablesJson               nvarchar(max) = NULL
    , @JsonErzeugen                 bit            = 0
    , @Json                         nvarchar(max)  = NULL OUTPUT
    , @PrintMeldungen               bit            = 1
    , @Hilfe                        bit            = 0
    , @ParentCurrentStateSnapshotId uniqueidentifier = NULL
AS
BEGIN
    SET NOCOUNT ON;
    SET LOCK_TIMEOUT 0;
    SET @Json=NULL;
    DECLARE @ModuleName sysname=N'USP_CurrentWaits',@CollectionTimeUtc datetime2(3)=SYSUTCDATETIME(),@MeasurementStartUtc datetime2(3)=NULL,@MeasurementEndUtc datetime2(3)=NULL;
    DECLARE @StatusCode varchar(40)='AVAILABLE',@IsPartial bit=0,@TaskRowCount bigint=0,@InstanceRowCount bigint=0,@ErrorNumber int=NULL,@ErrorMessage nvarchar(2048)=NULL,@Detail nvarchar(2000)=NULL,@DeltaStatus varchar(40)=CASE WHEN @SampleSeconds=0 THEN 'CUMULATIVE_CONTEXT' ELSE 'SKIPPED' END,@DeltaDetail nvarchar(2000)=NULL;
    DECLARE @RequiredPermission nvarchar(256)=CASE WHEN TRY_CONVERT(int,SERVERPROPERTY(N'ProductMajorVersion'))>=16 THEN N'VIEW SERVER PERFORMANCE STATE' ELSE N'VIEW SERVER STATE' END;
    DECLARE @ResultSetArtNormalisiert varchar(16)=UPPER(LTRIM(RTRIM(COALESCE(@ResultSetArt,''))));
    DECLARE @TableResultRequested bit = CASE WHEN @ResultSetArtNormalisiert = 'TABLE' THEN 1 ELSE 0 END;
    DECLARE @ConsoleResultRequested bit = CASE WHEN @ResultSetArtNormalisiert = 'CONSOLE' THEN 1 ELSE 0 END;
    DECLARE @TableTarget sysname=NULL;
    IF @TableResultRequested=0 AND NULLIF(LTRIM(RTRIM(COALESCE(@ResultTablesJson,N''))),N'') IS NOT NULL THROW 51011,N'@ResultTablesJson ist ausschließlich mit @ResultSetArt=TABLE zulässig.',1;
    IF @TableResultRequested=1 EXEC [monitor].[InternalPrepareSingleResultTable] @ResultTablesJson=@ResultTablesJson,@ResultName=N'currentTasks',@TargetTable=@TableTarget OUTPUT,@ThrowOnError=1;
    IF @TableResultRequested = 1 OR @ConsoleResultRequested = 1 SET @ResultSetArtNormalisiert = 'NONE';
    DECLARE @EffectiveMaxZeilen bigint=CASE WHEN @MaxZeilen IS NULL OR @MaxZeilen=0 THEN CONVERT(bigint,9223372036854775807) WHEN @MaxZeilen>0 THEN CONVERT(bigint,@MaxZeilen) ELSE CONVERT(bigint,0) END;
    DECLARE @CandidateMaxZeilen bigint,@MonitorPrintMessage nvarchar(2048),@StartBefore datetime,@StartAfter datetime;
    DECLARE @EvidenceSnapshotId uniqueidentifier=COALESCE(@ParentCurrentStateSnapshotId,NEWID());
    DECLARE @EvidenceSnapshotStartedAtUtc datetime2(3)=@CollectionTimeUtc;

    IF @Hilfe=1
    BEGIN
        PRINT N'monitor.USP_CurrentWaits';
        PRINT N'@SessionIds, @WaitTypes und @WaitGroups akzeptieren bracket-aware Pipe-Listen.';
        PRINT N'@ToolHintergrundabfragenEinbeziehen=0 blendet erkannte Object-Explorer-, Copilot- und SQL-Prompt-Waiting-Tasks standardmäßig aus; 1 zeigt sie samt Klassifikation.';
        PRINT N'@WaitTypePattern/@WaitGroupPattern: LIKE (Default/like:), regex: oder regexi:; Liste und Pattern sind gegenseitig exklusiv.';
        PRINT N'@SampleSeconds=0 liefert kumulative Instanzwerte; 1..60 liefert ein Delta.';
        PRINT N'@MaxZeilen positiv begrenzt; NULL/0 unbegrenzt. @ResultSetArt CONSOLE (Default), RAW, TABLE oder NONE; optional @Json OUTPUT.';
        RETURN;
    END;

    CREATE TABLE [#CurrentWaits_SessionIdFilter]([SessionId] smallint NOT NULL PRIMARY KEY);
    CREATE TABLE [#CurrentWaits_WaitTypeFilter]([WaitType] nvarchar(120) COLLATE SQL_Latin1_General_CP1_CS_AS NOT NULL PRIMARY KEY);
    CREATE TABLE [#CurrentWaits_WaitGroupFilter]([WaitGroup] nvarchar(64) COLLATE SQL_Latin1_General_CP1_CS_AS NOT NULL PRIMARY KEY);
    DECLARE @WaitTypeMode varchar(8),@WaitTypeValue nvarchar(4000),@WaitTypeFlags varchar(8),@WaitTypeValid bit;
    DECLARE @WaitGroupMode varchar(8),@WaitGroupValue nvarchar(4000),@WaitGroupFlags varchar(8),@WaitGroupValid bit;
    SELECT @WaitTypeMode=[PatternMode],@WaitTypeValue=[PatternValue],@WaitTypeFlags=[RegexFlags],@WaitTypeValid=[IsValid] FROM [monitor].[TVF_ParsePattern](@WaitTypePattern);
    SELECT @WaitGroupMode=[PatternMode],@WaitGroupValue=[PatternValue],@WaitGroupFlags=[RegexFlags],@WaitGroupValid=[IsValid] FROM [monitor].[TVF_ParsePattern](@WaitGroupPattern);

    IF @SessionIds IS NOT NULL
    BEGIN
        IF EXISTS(SELECT 1 FROM [monitor].[TVF_ParseBigintList](@SessionIds) WHERE [IsValid]=0 OR [NumberValue] NOT BETWEEN 1 AND 32767) SET @StatusCode='INVALID_PARAMETER';
        ELSE INSERT [#CurrentWaits_SessionIdFilter] SELECT CONVERT(smallint,[NumberValue]) FROM [monitor].[TVF_ParseBigintList](@SessionIds) GROUP BY [NumberValue];
    END;
    IF @StatusCode='AVAILABLE' AND ((@WaitTypes IS NOT NULL AND @WaitTypePattern IS NOT NULL) OR (@WaitGroups IS NOT NULL AND @WaitGroupPattern IS NOT NULL) OR @WaitTypeValid=0 OR @WaitGroupValid=0) SET @StatusCode='INVALID_PARAMETER';
    IF @StatusCode='AVAILABLE' AND ((@WaitTypes IS NOT NULL AND EXISTS(SELECT 1 FROM [monitor].[TVF_ParseStringList](@WaitTypes) WHERE [IsValid]=0 OR LEN([StringValue])>120)) OR (@WaitGroups IS NOT NULL AND EXISTS(SELECT 1 FROM [monitor].[TVF_ParseStringList](@WaitGroups) WHERE [IsValid]=0 OR LEN([StringValue])>64))) SET @StatusCode='INVALID_PARAMETER';
    IF @StatusCode='AVAILABLE'
    BEGIN
        INSERT [#CurrentWaits_WaitTypeFilter] SELECT CONVERT(nvarchar(120),[StringValue]) FROM [monitor].[TVF_ParseStringList](@WaitTypes) WHERE [IsValid]=1 GROUP BY [StringValue];
        INSERT [#CurrentWaits_WaitGroupFilter] SELECT CONVERT(nvarchar(64),[StringValue]) FROM [monitor].[TVF_ParseStringList](@WaitGroups) WHERE [IsValid]=1 GROUP BY [StringValue];
    END;
    DECLARE @HasRegex bit=CASE WHEN @WaitTypeMode IN('REGEX','REGEXI') OR @WaitGroupMode IN('REGEX','REGEXI') THEN 1 ELSE 0 END;
    IF @StatusCode='AVAILABLE' AND @HasRegex=1 AND (TRY_CONVERT(int,SERVERPROPERTY(N'ProductMajorVersion'))<17 OR (SELECT [compatibility_level] FROM [master].[sys].[databases] WITH(NOLOCK) WHERE [database_id]=DB_ID())<170) BEGIN SET @StatusCode='UNAVAILABLE_FEATURE';SET @ErrorMessage=N'Regex benötigt SQL Server 2025 und Compatibility Level 170.';END;
    IF @StatusCode='AVAILABLE' AND (@MinWaitMs<0 OR @SampleSeconds>60 OR @TopWaitPercentage<=0 OR @TopWaitPercentage>100 OR @MaxZeilen<0 OR @MaxSqlTextZeichen<0 OR @ResultSetArtNormalisiert NOT IN('RAW','CONSOLE','NONE') OR @ToolHintergrundabfragenEinbeziehen IS NULL OR @ToolHintergrundabfragenEinbeziehen NOT IN(0,1)) SET @StatusCode='INVALID_PARAMETER';
    IF @StatusCode='INVALID_PARAMETER' SET @ErrorMessage=COALESCE(@ErrorMessage,N'Ungültige Liste, Kombination, Pattern- oder Steuerangabe.');

    CREATE TABLE [#CurrentWaits_Tasks]
    (
        [SessionId] smallint NULL,[ExecContextId] int NULL,[WaitDurationMs] bigint NULL,[WaitType] nvarchar(120) NULL,[BlockingSessionId] smallint NULL,[ResourceDescription] nvarchar(3072) NULL,[SessionStatus] nvarchar(30) NULL,[RequestStatus] nvarchar(30) NULL,[LoginName] nvarchar(128) NULL,[HostName] nvarchar(128) NULL,[ProgramName] nvarchar(128) NULL,[IsToolBackgroundQuery] bit NOT NULL,[ToolBackgroundRuleCode] varchar(64) NULL,[ToolBackgroundCategory] varchar(40) NULL,[ToolBackgroundDetection] varchar(40) NULL,[ToolBackgroundConfidence] varchar(16) NULL,[DatabaseId] smallint NULL,[Command] nvarchar(32) NULL,[CurrentStatementCharacters] bigint NULL,[CurrentStatementBytes] bigint NULL,[CurrentStatementIsTruncated] bit NOT NULL DEFAULT(0),[CurrentStatement] nvarchar(max) NULL,[WaitGroup] nvarchar(64) NULL,[WaitSeverity] tinyint NULL,[IsGenerallyBenign] bit NULL,[WaitMeaning] nvarchar(1000) NULL,[WaitTypicalOccurrence] nvarchar(1200) NULL,[HighWaitImpact] nvarchar(1200) NULL,[RecommendedChecks] nvarchar(1500) NULL,[WaitHelpUrl] nvarchar(500) NULL,[DescriptionSource] varchar(40) NULL,[DescriptionQuality] varchar(40) NULL,[CatalogMatchType] varchar(20) NULL
    );
    CREATE TABLE [#CurrentWaits_A]([WaitType] nvarchar(120) PRIMARY KEY,[WaitingTasksCount] bigint,[WaitTimeMs] bigint,[SignalWaitTimeMs] bigint);
    CREATE TABLE [#CurrentWaits_B]([WaitType] nvarchar(120) PRIMARY KEY,[WaitingTasksCount] bigint,[WaitTimeMs] bigint,[SignalWaitTimeMs] bigint);
    CREATE TABLE [#CurrentWaits_RawInstance]([WaitType] nvarchar(120) NOT NULL,[WaitingTasksCount] bigint NULL,[WaitTimeMs] bigint NULL,[SignalWaitTimeMs] bigint NULL,[ResourceWaitTimeMs] bigint NULL,[SampleSeconds] int NULL,[MeasurementType] varchar(30) NOT NULL);
    CREATE TABLE [#CurrentWaits_Instance]
    (
        [WaitType] nvarchar(120) NOT NULL,[WaitingTasksCount] bigint NULL,[WaitTimeMs] bigint NULL,[SignalWaitTimeMs] bigint NULL,[ResourceWaitTimeMs] bigint NULL,[SampleSeconds] int NULL,[MeasurementType] varchar(30) NOT NULL,[WaitGroup] nvarchar(64) NULL,[WaitSeverity] tinyint NULL,[IsGenerallyBenign] bit NULL,[WaitMeaning] nvarchar(1000) NULL,[WaitTypicalOccurrence] nvarchar(1200) NULL,[HighWaitImpact] nvarchar(1200) NULL,[RecommendedChecks] nvarchar(1500) NULL,[WaitHelpUrl] nvarchar(500) NULL,[DescriptionSource] varchar(40) NULL,[DescriptionQuality] varchar(40) NULL,[CatalogMatchType] varchar(20) NULL,[WaitPercentage] decimal(9,4) NULL,[CumulativePercentage] decimal(9,4) NULL,[AverageWaitMs] decimal(19,4) NULL,[AverageResourceWaitMs] decimal(19,4) NULL,[AverageSignalWaitMs] decimal(19,4) NULL
    );
    CREATE TABLE [#CurrentWaits_Warnings]([WarningCode] varchar(40) NOT NULL,[WarningMessage] nvarchar(2048) NOT NULL);
    CREATE TABLE [#CurrentWaits_SourceWaitingTasks]
    (
          [waiting_task_address] varbinary(8) NOT NULL
        , [session_id] smallint NULL
        , [exec_context_id] int NULL
        , [wait_duration_ms] bigint NOT NULL
        , [wait_type] nvarchar(60) NOT NULL
        , [blocking_session_id] smallint NULL
        , [resource_description] nvarchar(3072) NULL
    );
    CREATE TABLE [#CurrentWaits_SourceSessions]
    (
          [session_id] smallint NOT NULL PRIMARY KEY
        , [is_user_process] bit NOT NULL
        , [status] nvarchar(30) NOT NULL
        , [login_name] nvarchar(128) NOT NULL
        , [host_name] nvarchar(128) NULL
        , [program_name] nvarchar(128) NULL
    );
    CREATE TABLE [#CurrentWaits_SourceRequests]
    (
          [session_id] smallint NOT NULL
        , [request_id] int NOT NULL
        , [status] nvarchar(30) NOT NULL
        , [database_id] smallint NOT NULL
        , [command] nvarchar(32) NOT NULL
        , [sql_handle] varbinary(64) NULL
        , [statement_start_offset] int NULL
        , [statement_end_offset] int NULL
        , PRIMARY KEY([session_id],[request_id])
    );
    CREATE TABLE [#CurrentWaits_SourceSqlText]
    (
          [SqlHandle] varbinary(64) NOT NULL PRIMARY KEY
        , [Text] nvarchar(max) NULL
    );
    SET @CandidateMaxZeilen=CASE WHEN @HasRegex=1 OR @MaxZeilen IS NULL OR @MaxZeilen=0 THEN CONVERT(bigint,9223372036854775807) ELSE CONVERT(bigint,@MaxZeilen)+1 END;

    IF @StatusCode='AVAILABLE'
    BEGIN
        BEGIN TRY
            IF @ParentCurrentStateSnapshotId IS NOT NULL
            BEGIN
                EXEC [sys].[sp_executesql] N'
                    DECLARE @Probe int;
                    SELECT @Probe=0 FROM [#CurrentOverview_CurrentStateSnapshot_Context] WHERE 1=0;
                    SELECT @Probe=0 FROM [#CurrentOverview_CurrentStateSnapshot_SourceStatus] WHERE 1=0;
                    SELECT @Probe=0 FROM [#CurrentOverview_CurrentStateSnapshot_WaitingTasks] WHERE 1=0;
                    SELECT @Probe=0 FROM [#CurrentOverview_CurrentStateSnapshot_Sessions] WHERE 1=0;
                    SELECT @Probe=0 FROM [#CurrentOverview_CurrentStateSnapshot_Requests] WHERE 1=0;
                    SELECT @Probe=0 FROM [#CurrentOverview_CurrentStateSnapshot_SqlText] WHERE 1=0;';

                IF NOT EXISTS
                (
                    SELECT 1
                    FROM [#CurrentOverview_CurrentStateSnapshot_Context]
                    WHERE [SnapshotId]=@ParentCurrentStateSnapshotId
                      AND [OwnerSessionId]=CONVERT(smallint,@@SPID)
                      AND [ContractVersion]=2
                )
                    THROW 51020,N'Die Parent-Snapshot-ID gehört nicht zum aktuellen Aufruf.',1;

                INSERT [#CurrentWaits_SourceWaitingTasks]
                SELECT
                      [waiting_task_address],[session_id],[exec_context_id],[wait_duration_ms]
                    , [wait_type],[blocking_session_id],[resource_description]
                FROM [#CurrentOverview_CurrentStateSnapshot_WaitingTasks]
                WHERE [SnapshotId]=@ParentCurrentStateSnapshotId;

                INSERT [#CurrentWaits_SourceSessions]
                SELECT [session_id],[is_user_process],[status],[login_name],[host_name],[program_name]
                FROM [#CurrentOverview_CurrentStateSnapshot_Sessions]
                WHERE [SnapshotId]=@ParentCurrentStateSnapshotId;

                INSERT [#CurrentWaits_SourceRequests]
                SELECT
                      [session_id],[request_id],[status],[database_id],[command],[sql_handle]
                    , [statement_start_offset],[statement_end_offset]
                FROM [#CurrentOverview_CurrentStateSnapshot_Requests]
                WHERE [SnapshotId]=@ParentCurrentStateSnapshotId;

                IF @MitSqlText=1
                    INSERT [#CurrentWaits_SourceSqlText]
                    SELECT [SqlHandle],[Text]
                    FROM [#CurrentOverview_CurrentStateSnapshot_SqlText]
                    WHERE [SnapshotId]=@ParentCurrentStateSnapshotId;

                SELECT
                      @EvidenceSnapshotStartedAtUtc=MIN([CapturedAtUtc])
                    , @IsPartial=CONVERT(bit,MAX(CONVERT(int,[IsPartial])))
                FROM [#CurrentOverview_CurrentStateSnapshot_SourceStatus]
                WHERE [SnapshotId]=@ParentCurrentStateSnapshotId
                  AND [SourceCode] IN ('WAITING_TASKS','SESSIONS','REQUESTS','SQL_TEXT');
            END
            ELSE
            BEGIN
                SET @EvidenceSnapshotStartedAtUtc=SYSUTCDATETIME();
                INSERT [#CurrentWaits_SourceWaitingTasks]
                SELECT
                      [waiting_task_address],[session_id],[exec_context_id],[wait_duration_ms]
                    , [wait_type],[blocking_session_id],[resource_description]
                FROM [sys].[dm_os_waiting_tasks] WITH (NOLOCK);

                INSERT [#CurrentWaits_SourceSessions]
                SELECT [session_id],[is_user_process],[status],[login_name],[host_name],[program_name]
                FROM [sys].[dm_exec_sessions] WITH (NOLOCK);

                INSERT [#CurrentWaits_SourceRequests]
                SELECT
                      [session_id],[request_id],[status],[database_id],[command],[sql_handle]
                    , [statement_start_offset],[statement_end_offset]
                FROM [sys].[dm_exec_requests] WITH (NOLOCK);

                IF @MitSqlText=1
                    INSERT [#CurrentWaits_SourceSqlText]
                    SELECT [h].[SqlHandle],[t].[text]
                    FROM
                    (
                        SELECT [sql_handle] AS [SqlHandle]
                        FROM [#CurrentWaits_SourceRequests]
                        WHERE [sql_handle] IS NOT NULL
                        GROUP BY [sql_handle]
                    ) AS [h]
                    OUTER APPLY [sys].[dm_exec_sql_text]([h].[SqlHandle]) AS [t];
            END;
        END TRY
        BEGIN CATCH
            SET @ErrorNumber=ERROR_NUMBER();
            SET @ErrorMessage=ERROR_MESSAGE();
            SET @IsPartial=1;
            SET @StatusCode=CASE
                WHEN @ErrorNumber=1222 THEN 'TIMEOUT'
                WHEN @ErrorNumber IN(229,262,297,300,371,916) THEN 'DENIED_PERMISSION'
                WHEN @ParentCurrentStateSnapshotId IS NOT NULL
                 AND @ErrorNumber IN(208,51020) THEN 'INVALID_PARENT_SNAPSHOT'
                ELSE 'ERROR_HANDLED' END;
            INSERT [#CurrentWaits_Warnings] VALUES(@StatusCode,@ErrorMessage);
        END CATCH;

        BEGIN TRY
            INSERT [#CurrentWaits_Tasks]
            SELECT TOP(@CandidateMaxZeilen) [w].[session_id],[w].[exec_context_id],[w].[wait_duration_ms],[w].[wait_type],NULLIF([w].[blocking_session_id],0),[w].[resource_description],[s].[status],[r].[status],[s].[login_name],[s].[host_name],[s].[program_name],[tool].[IsToolBackgroundQuery],[tool].[ToolBackgroundRuleCode],[tool].[ToolBackgroundCategory],[tool].[ToolBackgroundDetection],[tool].[ToolBackgroundConfidence],[r].[database_id],[r].[command],NULL,NULL,CONVERT(bit,0),CASE WHEN @MitSqlText=1 THEN [st].[StatementText] END,[wi].[WaitGroup],[wi].[Severity],[wi].[IsGenerallyBenign],[wi].[Meaning],[wi].[TypicalOccurrence],[wi].[HighWaitImpact],[wi].[RecommendedChecks],[wi].[HelpUrl],[wi].[DescriptionSource],[wi].[DescriptionQuality],[wi].[CatalogMatchType]
            FROM [#CurrentWaits_SourceWaitingTasks] AS [w]
            LEFT JOIN [#CurrentWaits_SourceSessions] AS [s] ON [s].[session_id]=[w].[session_id]
            LEFT JOIN [#CurrentWaits_SourceRequests] AS [r] ON [r].[session_id]=[w].[session_id]
            CROSS APPLY [monitor].[TVF_ToolBackgroundQueryInfo]([s].[program_name]) AS [tool]
            LEFT JOIN [#CurrentWaits_SourceSqlText] AS [t]
              ON [t].[SqlHandle]=CASE WHEN @MitSqlText=1 THEN [r].[sql_handle] END
            OUTER APPLY [monitor].[TVF_StatementText]([t].[Text],[r].[statement_start_offset],[r].[statement_end_offset]) AS [st]
            CROSS APPLY [monitor].[TVF_WaitTypeInfo]([w].[wait_type]) AS [wi]
            WHERE (NOT EXISTS(SELECT 1 FROM [#CurrentWaits_SessionIdFilter]) OR EXISTS(SELECT 1 FROM [#CurrentWaits_SessionIdFilter] AS [f] WHERE [f].[SessionId]=[w].[session_id]))
              AND [w].[wait_duration_ms]>=@MinWaitMs AND (@SystemSessionsEinbeziehen=1 OR COALESCE([s].[is_user_process],1)=1)
              AND (@ToolHintergrundabfragenEinbeziehen=1 OR [tool].[IsToolBackgroundQuery]=0)
              AND (NOT EXISTS(SELECT 1 FROM [#CurrentWaits_WaitTypeFilter]) OR EXISTS(SELECT 1 FROM [#CurrentWaits_WaitTypeFilter] AS [f] WHERE [f].[WaitType]=[w].[wait_type] COLLATE SQL_Latin1_General_CP1_CS_AS))
              AND (NOT EXISTS(SELECT 1 FROM [#CurrentWaits_WaitGroupFilter]) OR EXISTS(SELECT 1 FROM [#CurrentWaits_WaitGroupFilter] AS [f] WHERE [f].[WaitGroup]=[wi].[WaitGroup] COLLATE SQL_Latin1_General_CP1_CS_AS))
              AND (@WaitTypeMode<>'LIKE' OR [w].[wait_type] COLLATE SQL_Latin1_General_CP1_CS_AS LIKE @WaitTypeValue COLLATE SQL_Latin1_General_CP1_CS_AS)
              AND (@WaitGroupMode<>'LIKE' OR [wi].[WaitGroup] COLLATE SQL_Latin1_General_CP1_CS_AS LIKE @WaitGroupValue COLLATE SQL_Latin1_General_CP1_CS_AS)
            ORDER BY [w].[wait_duration_ms] DESC,[w].[session_id];
            SET @Detail=CASE WHEN @@ROWCOUNT=0 THEN N'Aktuell keine passende wartende Task sichtbar.' ELSE N'Aktuelle Waiting Tasks erfolgreich gelesen.' END;
        END TRY
        BEGIN CATCH
            SET @ErrorNumber=ERROR_NUMBER();SET @ErrorMessage=ERROR_MESSAGE();SET @IsPartial=1;SET @StatusCode=CASE WHEN @ErrorNumber IN(229,262,297,300,371,916) THEN 'DENIED_PERMISSION' WHEN @ErrorNumber=1222 THEN 'TIMEOUT' ELSE 'ERROR_HANDLED' END;INSERT [#CurrentWaits_Warnings] VALUES(@StatusCode,@ErrorMessage);
        END CATCH;

        IF @SampleSeconds=0
        BEGIN TRY
            SET @MeasurementStartUtc=SYSUTCDATETIME();
            INSERT [#CurrentWaits_RawInstance] SELECT [wait_type],[waiting_tasks_count],[wait_time_ms],[signal_wait_time_ms],[wait_time_ms]-[signal_wait_time_ms],NULL,'INSTANCE_CUMULATIVE' FROM [sys].[dm_os_wait_stats] WITH (NOLOCK) WHERE [waiting_tasks_count]>0;
            SET @MeasurementEndUtc=SYSUTCDATETIME();SET @DeltaStatus='CUMULATIVE_CONTEXT';SET @DeltaDetail=N'Kumulativ seit SQL-Server-Start oder letztem Reset.';
        END TRY BEGIN CATCH SET @DeltaStatus='ERROR_HANDLED';SET @DeltaDetail=ERROR_MESSAGE();SET @IsPartial=1;INSERT [#CurrentWaits_Warnings] VALUES(@DeltaStatus,@DeltaDetail);END CATCH;
        ELSE
        BEGIN TRY
            SET @MeasurementStartUtc=SYSUTCDATETIME();SELECT @StartBefore=[sqlserver_start_time] FROM [sys].[dm_os_sys_info] WITH (NOLOCK);INSERT [#CurrentWaits_A] SELECT [wait_type],[waiting_tasks_count],[wait_time_ms],[signal_wait_time_ms] FROM [sys].[dm_os_wait_stats] WITH (NOLOCK);DECLARE @Delay char(8)=CONVERT(char(8),DATEADD(SECOND,@SampleSeconds,CONVERT(datetime,'19000101',112)),108);WAITFOR DELAY @Delay;SELECT @StartAfter=[sqlserver_start_time] FROM [sys].[dm_os_sys_info] WITH (NOLOCK);INSERT [#CurrentWaits_B] SELECT [wait_type],[waiting_tasks_count],[wait_time_ms],[signal_wait_time_ms] FROM [sys].[dm_os_wait_stats] WITH (NOLOCK);SET @MeasurementEndUtc=SYSUTCDATETIME();
            IF @StartBefore<>@StartAfter OR EXISTS(SELECT 1 FROM [#CurrentWaits_A] AS [a] JOIN [#CurrentWaits_B] AS [b] ON [b].[WaitType]=[a].[WaitType] WHERE [b].[WaitTimeMs]<[a].[WaitTimeMs] OR [b].[WaitingTasksCount]<[a].[WaitingTasksCount] OR [b].[SignalWaitTimeMs]<[a].[SignalWaitTimeMs]) BEGIN SET @DeltaStatus='MEASUREMENT_RESET';SET @DeltaDetail=N'Serverneustart oder Wait-Zählerreset während des Messfensters erkannt.';SET @IsPartial=1;INSERT [#CurrentWaits_Warnings] VALUES(@DeltaStatus,@DeltaDetail);END
            ELSE BEGIN INSERT [#CurrentWaits_RawInstance] SELECT [b].[WaitType],[b].[WaitingTasksCount]-COALESCE([a].[WaitingTasksCount],0),[b].[WaitTimeMs]-COALESCE([a].[WaitTimeMs],0),[b].[SignalWaitTimeMs]-COALESCE([a].[SignalWaitTimeMs],0),([b].[WaitTimeMs]-COALESCE([a].[WaitTimeMs],0))-([b].[SignalWaitTimeMs]-COALESCE([a].[SignalWaitTimeMs],0)),@SampleSeconds,'INSTANCE_DELTA' FROM [#CurrentWaits_B] AS [b] LEFT JOIN [#CurrentWaits_A] AS [a] ON [a].[WaitType]=[b].[WaitType] WHERE [b].[WaitTimeMs]-COALESCE([a].[WaitTimeMs],0)>0;SET @DeltaStatus='AVAILABLE';SET @DeltaDetail=CONCAT(N'Gültiges Wait-Delta über ',@SampleSeconds,N' Sekunden.');END;
        END TRY BEGIN CATCH SET @DeltaStatus='ERROR_HANDLED';SET @DeltaDetail=ERROR_MESSAGE();SET @IsPartial=1;INSERT [#CurrentWaits_Warnings] VALUES(@DeltaStatus,@DeltaDetail);END CATCH;

        INSERT [#CurrentWaits_Instance]
        SELECT [x].[WaitType],[x].[WaitingTasksCount],[x].[WaitTimeMs],[x].[SignalWaitTimeMs],[x].[ResourceWaitTimeMs],[x].[SampleSeconds],[x].[MeasurementType],[wi].[WaitGroup],[wi].[Severity],[wi].[IsGenerallyBenign],[wi].[Meaning],[wi].[TypicalOccurrence],[wi].[HighWaitImpact],[wi].[RecommendedChecks],[wi].[HelpUrl],[wi].[DescriptionSource],[wi].[DescriptionQuality],[wi].[CatalogMatchType],CONVERT(decimal(9,4),100.0*[x].[WaitTimeMs]/NULLIF(SUM([x].[WaitTimeMs]) OVER(),0)),NULL,CONVERT(decimal(19,4),1.0*[x].[WaitTimeMs]/NULLIF([x].[WaitingTasksCount],0)),CONVERT(decimal(19,4),1.0*[x].[ResourceWaitTimeMs]/NULLIF([x].[WaitingTasksCount],0)),CONVERT(decimal(19,4),1.0*[x].[SignalWaitTimeMs]/NULLIF([x].[WaitingTasksCount],0))
        FROM [#CurrentWaits_RawInstance] AS [x] CROSS APPLY [monitor].[TVF_WaitTypeInfo]([x].[WaitType]) AS [wi]
        WHERE (@UnkritischeWaitsEinbeziehen=1 OR [wi].[IsGenerallyBenign]=0)
          AND (NOT EXISTS(SELECT 1 FROM [#CurrentWaits_WaitTypeFilter]) OR EXISTS(SELECT 1 FROM [#CurrentWaits_WaitTypeFilter] AS [f] WHERE [f].[WaitType]=[x].[WaitType] COLLATE SQL_Latin1_General_CP1_CS_AS))
          AND (NOT EXISTS(SELECT 1 FROM [#CurrentWaits_WaitGroupFilter]) OR EXISTS(SELECT 1 FROM [#CurrentWaits_WaitGroupFilter] AS [f] WHERE [f].[WaitGroup]=[wi].[WaitGroup] COLLATE SQL_Latin1_General_CP1_CS_AS))
          AND (@WaitTypeMode<>'LIKE' OR [x].[WaitType] COLLATE SQL_Latin1_General_CP1_CS_AS LIKE @WaitTypeValue COLLATE SQL_Latin1_General_CP1_CS_AS)
          AND (@WaitGroupMode<>'LIKE' OR [wi].[WaitGroup] COLLATE SQL_Latin1_General_CP1_CS_AS LIKE @WaitGroupValue COLLATE SQL_Latin1_General_CP1_CS_AS);

        IF @HasRegex=1
        BEGIN
            DECLARE @Sql nvarchar(max)=N'';
            IF @WaitTypeMode IN('REGEX','REGEXI') SET @Sql=N'DELETE FROM [#CurrentWaits_Tasks] WHERE [WaitType] IS NULL OR NOT REGEXP_LIKE([WaitType],@WaitType,@WaitTypeFlags);DELETE FROM [#CurrentWaits_Instance] WHERE NOT REGEXP_LIKE([WaitType],@WaitType,@WaitTypeFlags);';
            IF @WaitGroupMode IN('REGEX','REGEXI') SET @Sql+=N'DELETE FROM [#CurrentWaits_Tasks] WHERE [WaitGroup] IS NULL OR NOT REGEXP_LIKE([WaitGroup],@WaitGroup,@WaitGroupFlags);DELETE FROM [#CurrentWaits_Instance] WHERE [WaitGroup] IS NULL OR NOT REGEXP_LIKE([WaitGroup],@WaitGroup,@WaitGroupFlags);';
            EXEC [sys].[sp_executesql] @Sql,N'@WaitType nvarchar(4000),@WaitTypeFlags varchar(8),@WaitGroup nvarchar(4000),@WaitGroupFlags varchar(8)',@WaitTypeValue,@WaitTypeFlags,@WaitGroupValue,@WaitGroupFlags;
        END;

        ;WITH [C] AS (SELECT [WaitType],CONVERT(decimal(9,4),SUM([WaitPercentage]) OVER(ORDER BY [WaitTimeMs] DESC,[WaitType] ROWS UNBOUNDED PRECEDING)) AS [Cum] FROM [#CurrentWaits_Instance]) UPDATE [i] SET [CumulativePercentage]=[c].[Cum] FROM [#CurrentWaits_Instance] AS [i] JOIN [C] AS [c] ON [c].[WaitType]=[i].[WaitType];
        DELETE FROM [#CurrentWaits_Instance] WHERE [CumulativePercentage]-[WaitPercentage]>=@TopWaitPercentage;
        IF @MaxZeilen IS NOT NULL AND @MaxZeilen>0
        BEGIN
            ;WITH [T] AS (SELECT ROW_NUMBER() OVER(ORDER BY [WaitDurationMs] DESC,[SessionId]) AS [rn],* FROM [#CurrentWaits_Tasks]) DELETE FROM [T] WHERE [rn]>@MaxZeilen;
            ;WITH [I] AS (SELECT ROW_NUMBER() OVER(ORDER BY [WaitTimeMs] DESC,[WaitType]) AS [rn],* FROM [#CurrentWaits_Instance]) DELETE FROM [I] WHERE [rn]>@MaxZeilen;
        END;
        DECLARE @TruncatedValueCount bigint=0,@LargestRequiredCharacters bigint=NULL;
        EXEC [monitor].[InternalProjectUnicodeTextColumn]
              @SourceTable=N'#CurrentWaits_Tasks',@TextColumn=N'CurrentStatement'
            , @CharactersColumn=N'CurrentStatementCharacters',@BytesColumn=N'CurrentStatementBytes'
            , @IsTruncatedColumn=N'CurrentStatementIsTruncated',@MaxCharacters=@MaxSqlTextZeichen
            , @TruncatedValueCount=@TruncatedValueCount OUTPUT,@LargestRequiredCharacters=@LargestRequiredCharacters OUTPUT;
        EXEC [monitor].[InternalEmitTruncationWarning]
              @TruncatedValueCount=@TruncatedValueCount,@ParameterName=N'@MaxSqlTextZeichen'
            , @ParameterValue=@MaxSqlTextZeichen,@LargestRequiredCharacters=@LargestRequiredCharacters
            , @PrintMeldungen=@PrintMeldungen;
        SELECT @TaskRowCount=COUNT_BIG(*) FROM [#CurrentWaits_Tasks];SELECT @InstanceRowCount=COUNT_BIG(*) FROM [#CurrentWaits_Instance];
        IF @IsPartial=1 AND @StatusCode='AVAILABLE' SET @StatusCode='AVAILABLE_LIMITED';
    END;

    IF @PrintMeldungen=1 AND @StatusCode NOT IN('AVAILABLE') BEGIN SET @MonitorPrintMessage=FORMATMESSAGE(N'WARNUNG %s: %s',@StatusCode,COALESCE(@ErrorMessage,@DeltaDetail,@Detail,N'eingeschränkte Sicht'));RAISERROR(N'%s',10,1,@MonitorPrintMessage) WITH NOWAIT;END;
    IF @JsonErzeugen=1
    BEGIN
        DECLARE @Meta nvarchar(max)=(SELECT @ModuleName AS [resultName],3 AS [schemaVersion],@CollectionTimeUtc AS [generatedAtUtc],@EvidenceSnapshotStartedAtUtc AS [evidenceSnapshotStartedAtUtc],@EvidenceSnapshotId AS [evidenceSnapshotId],@MeasurementStartUtc AS [measurementStartUtc],@MeasurementEndUtc AS [measurementEndUtc],@StatusCode AS [statusCode],@IsPartial AS [isPartial],@DeltaStatus AS [measurementStatusCode],@TaskRowCount AS [currentTaskRows],@InstanceRowCount AS [instanceWaitRows],@ToolHintergrundabfragenEinbeziehen AS [toolBackgroundQueriesIncluded] FOR JSON PATH,WITHOUT_ARRAY_WRAPPER,INCLUDE_NULL_VALUES),@Tasks nvarchar(max)=(SELECT * FROM [#CurrentWaits_Tasks] ORDER BY [WaitDurationMs] DESC,[SessionId] FOR JSON PATH,INCLUDE_NULL_VALUES),@Instance nvarchar(max)=(SELECT * FROM [#CurrentWaits_Instance] ORDER BY [WaitTimeMs] DESC,[WaitType] FOR JSON PATH,INCLUDE_NULL_VALUES),@Warnings nvarchar(max)=(SELECT [WarningCode] AS [code],[WarningMessage] AS [message] FROM [#CurrentWaits_Warnings] FOR JSON PATH,INCLUDE_NULL_VALUES);SET @Json=CONCAT(N'{"meta":',COALESCE(@Meta,N'{}'),N',"currentTasks":',COALESCE(@Tasks,N'[]'),N',"instanceWaits":',COALESCE(@Instance,N'[]'),N',"warnings":',COALESCE(@Warnings,N'[]'),N'}');
    END;
    IF @ResultSetArtNormalisiert='RAW'
    BEGIN
        SELECT N'2.0' AS [ContractVersion],@ModuleName AS [ModuleName],@CollectionTimeUtc AS [CollectionTimeUtc],@EvidenceSnapshotStartedAtUtc AS [EvidenceSnapshotStartedAtUtc],@EvidenceSnapshotId AS [EvidenceSnapshotId],@MeasurementStartUtc AS [MeasurementStartUtc],@MeasurementEndUtc AS [MeasurementEndUtc],@StatusCode AS [StatusCode],@IsPartial AS [IsPartial],@TaskRowCount AS [CurrentTaskRowCount],@InstanceRowCount AS [InstanceWaitRowCount],@RequiredPermission AS [RequiredPermission],@ErrorNumber AS [ErrorNumber],@ErrorMessage AS [ErrorMessage],@Detail AS [Detail],@DeltaStatus AS [DeltaStatusCode],@DeltaDetail AS [DeltaDetail],@StartBefore AS [ServerStartTimeBefore],@StartAfter AS [ServerStartTimeAfter];
        SELECT * FROM [#CurrentWaits_Tasks] ORDER BY [WaitDurationMs] DESC,[SessionId];SELECT * FROM [#CurrentWaits_Instance] ORDER BY [WaitTimeMs] DESC,[WaitType];SELECT * FROM [#CurrentWaits_Warnings] ORDER BY [WarningCode];
    END
    ELSE IF @ResultSetArtNormalisiert='CONSOLE'
    BEGIN
        SELECT N'Wait-Analyse' AS [Ergebnis],@StatusCode AS [Status],@DeltaStatus AS [Messstatus],@TaskRowCount AS [Aktuelle_Tasks],@InstanceRowCount AS [Instanz_Waits],@DeltaDetail AS [Messhinweis],@ErrorMessage AS [Fehler];
        SELECT N'Aktuelle wartende Task' AS [Ergebnis],[SessionId] AS [Session],[ExecContextId] AS [Exec_Context],[LoginName] AS [Login],[HostName] AS [Host],[ProgramName] AS [Programm],[Command] AS [Befehl],[WaitType] AS [Wait],CONCAT(CONVERT(varchar(40),[WaitDurationMs]),N' ms') AS [Wartezeit],[BlockingSessionId] AS [Blockiert_durch],[WaitGroup] AS [Wait_Gruppe],[WaitMeaning] AS [Bedeutung],[CurrentStatement] AS [Aktuelles_Statement] FROM [#CurrentWaits_Tasks] ORDER BY [WaitDurationMs] DESC,[SessionId];
        SELECT N'Instanzweite Wait-Messung' AS [Ergebnis],[WaitType] AS [Wait],[WaitGroup] AS [Wait_Gruppe],[MeasurementType] AS [Messart],[WaitingTasksCount] AS [Tasks],CONCAT(CONVERT(varchar(40),[WaitTimeMs]),N' ms') AS [Wartezeit],CONCAT(CONVERT(varchar(40),[WaitPercentage]),N' %') AS [Anteil],CONCAT(CONVERT(varchar(40),[AverageWaitMs]),N' ms') AS [Durchschnitt],[WaitMeaning] AS [Bedeutung],[RecommendedChecks] AS [Empfohlene_Pruefung] FROM [#CurrentWaits_Instance] ORDER BY [WaitTimeMs] DESC,[WaitType];
    END;
    IF @ConsoleResultRequested = 1
    BEGIN
        EXEC [monitor].[InternalEmitConsoleResult]
              @SourceTable=N'#CurrentWaits_Tasks'
            , @ResultLabel=N'Aktuelle Waits'
            , @EmptyMessage=N'Keine aktiven Waits';
    END;
    IF @TableResultRequested = 1
    BEGIN
        EXEC [monitor].[InternalWriteResultTable]
              @SourceTable = N'#CurrentWaits_Tasks'
            , @TargetTable=@TableTarget
            , @ThrowOnError = 1;
    END;
END;
GO
-- END SOURCE: Code/02_CurrentState/040_USP_CurrentWaits.sql

-- BEGIN SOURCE: Code/02_CurrentState/050_USP_CurrentTransactions.sql
/*
===============================================================================
Objekt       : monitor.USP_CurrentTransactions
Version      : 3.0.0
Stand        : 2026-07-23
Zweck        : Zeigt aktive Transaktionen einschließlich Session-, Request- und
               Logverbrauchsinformationen. Unterstützt Sessionlisten sowie
               RAW-, CONSOLE- und JSON-Ausgabe.
===============================================================================
*/
CREATE OR ALTER PROCEDURE [monitor].[USP_CurrentTransactions]
      @SessionIds                 nvarchar(max) = NULL
    , @MinAlterSekunden           int           = 0
    , @NurSleeping                bit           = 0
    , @SystemSessionsEinbeziehen  bit           = 0
    , @MitSqlText                 bit           = 1
    , @MaxSqlTextZeichen          int           = 3000
    , @MaxZeilen                  int           = 1000
    , @ResultSetArt               varchar(16)    = 'CONSOLE'
    , @ResultTablesJson               nvarchar(max) = NULL
    , @JsonErzeugen               bit            = 0
    , @Json                       nvarchar(max)  = NULL OUTPUT
    , @PrintMeldungen             bit            = 1
    , @Hilfe                      bit            = 0
    , @ParentCurrentStateSnapshotId uniqueidentifier = NULL
AS
BEGIN
    SET NOCOUNT ON;
    SET LOCK_TIMEOUT 0;
    SET @Json = NULL;

    DECLARE @OutputMode varchar(16) = UPPER(LTRIM(RTRIM(COALESCE(@ResultSetArt, ''))));
    DECLARE @TableResultRequested bit = CASE WHEN @OutputMode = 'TABLE' THEN 1 ELSE 0 END;
    DECLARE @ConsoleResultRequested bit = CASE WHEN @OutputMode = 'CONSOLE' THEN 1 ELSE 0 END;
    DECLARE @TableTarget sysname=NULL;
    IF @TableResultRequested=0 AND NULLIF(LTRIM(RTRIM(COALESCE(@ResultTablesJson,N''))),N'') IS NOT NULL THROW 51011,N'@ResultTablesJson ist ausschließlich mit @ResultSetArt=TABLE zulässig.',1;
    IF @TableResultRequested=1 EXEC [monitor].[InternalPrepareSingleResultTable] @ResultTablesJson=@ResultTablesJson,@ResultName=N'transactions',@TargetTable=@TableTarget OUTPUT,@ThrowOnError=1;
    IF @TableResultRequested = 1 OR @ConsoleResultRequested = 1 SET @OutputMode = 'NONE';
    DECLARE @Limit bigint = CASE WHEN @MaxZeilen IS NULL OR @MaxZeilen = 0 THEN CONVERT(bigint, 9223372036854775807)
                                 WHEN @MaxZeilen > 0 THEN CONVERT(bigint, @MaxZeilen) ELSE 0 END;
    DECLARE @Candidates bigint = CASE WHEN @MaxZeilen IS NULL OR @MaxZeilen = 0 THEN CONVERT(bigint, 9223372036854775807)
                                      WHEN @MaxZeilen < 2147483647 THEN CONVERT(bigint, @MaxZeilen) + 1 ELSE CONVERT(bigint, @MaxZeilen) END;

    IF @Hilfe = 1
    BEGIN
        PRINT N'monitor.USP_CurrentTransactions';
        PRINT N'@SessionIds = N''57|61''; NULL = keine Einschränkung.';
        PRINT N'@MaxZeilen positiv = begrenzt, NULL/0 = unbegrenzt.';
        PRINT N'@ResultSetArt = CONSOLE (Default)|RAW|TABLE|NONE; Steuerwert case-insensitiv.';
        PRINT N'@JsonErzeugen=1 liefert transactions und warnings in @Json OUTPUT.';
        RETURN;
    END;

    DECLARE @Now datetime2(3) = SYSUTCDATETIME();
    DECLARE @StatusCode varchar(40) = 'AVAILABLE';
    DECLARE @ErrorNumber int = NULL;
    DECLARE @ErrorMessage nvarchar(2048) = NULL;
    DECLARE @RowCount bigint = 0;
    DECLARE @HasMoreRows bit = 0;
    DECLARE @Message nvarchar(2048);
    DECLARE @EvidenceSnapshotId uniqueidentifier=COALESCE(@ParentCurrentStateSnapshotId,NEWID());
    DECLARE @EvidenceSnapshotStartedAtUtc datetime2(3)=@Now;
    DECLARE @EvidenceIsPartial bit=0;

    CREATE TABLE [#CurrentTransactions_SessionFilter]([SessionId] smallint NOT NULL PRIMARY KEY);
    CREATE TABLE [#CurrentTransactions_Result]
    (
          [SessionId]                smallint       NOT NULL
        , [TransactionId]            bigint         NOT NULL
        , [TransactionBeginTimeUtc]  datetime       NULL
        , [TransactionAgeSeconds]    bigint         NULL
        , [TransactionType]          int            NULL
        , [TransactionState]         int            NULL
        , [OpenTransactionCount]     int            NULL
        , [LoginName]                nvarchar(128)  NULL
        , [HostName]                 nvarchar(128)  NULL
        , [ProgramName]              nvarchar(128)  NULL
        , [SessionStatus]            nvarchar(30)   NULL
        , [RequestStatus]            nvarchar(30)   NULL
        , [DatabaseId]               int            NULL
        , [DatabaseName]             sysname        NULL
        , [LogBytesUsed]             bigint         NULL
        , [LogBytesReserved]         bigint         NULL
        , [StatementTextCharacters]  bigint         NULL
        , [StatementTextBytes]       bigint         NULL
        , [StatementTextIsTruncated] bit            NOT NULL DEFAULT(0)
        , [StatementText]            nvarchar(max)  NULL
    );
    CREATE TABLE [#CurrentTransactions_Warnings]
    (
          [StatusCode] varchar(40) NOT NULL
        , [ErrorNumber] int NULL
        , [ErrorMessage] nvarchar(2048) NULL
    );
    CREATE TABLE [#CurrentTransactions_SourceSessionTransactions]
    (
          [session_id] int NOT NULL
        , [transaction_id] bigint NOT NULL
        , PRIMARY KEY([session_id],[transaction_id])
    );
    CREATE TABLE [#CurrentTransactions_SourceActiveTransactions]
    (
          [transaction_id] bigint NOT NULL PRIMARY KEY
        , [transaction_begin_time] datetime NULL
        , [transaction_type] int NULL
        , [transaction_state] int NULL
    );
    CREATE TABLE [#CurrentTransactions_SourceDatabaseTransactions]
    (
          [transaction_id] bigint NOT NULL
        , [database_id] int NOT NULL
        , [database_transaction_log_bytes_used] bigint NOT NULL
        , [database_transaction_log_bytes_reserved] bigint NOT NULL
    );
    CREATE TABLE [#CurrentTransactions_SourceSessions]
    (
          [session_id] smallint NOT NULL PRIMARY KEY
        , [is_user_process] bit NOT NULL
        , [status] nvarchar(30) NOT NULL
        , [open_transaction_count] int NOT NULL
        , [login_name] nvarchar(128) NOT NULL
        , [host_name] nvarchar(128) NULL
        , [program_name] nvarchar(128) NULL
    );
    CREATE TABLE [#CurrentTransactions_SourceRequests]
    (
          [session_id] smallint NOT NULL
        , [request_id] int NOT NULL
        , [status] nvarchar(30) NOT NULL
        , [database_id] smallint NOT NULL
        , [sql_handle] varbinary(64) NULL
        , [statement_start_offset] int NULL
        , [statement_end_offset] int NULL
        , PRIMARY KEY([session_id],[request_id])
    );
    CREATE TABLE [#CurrentTransactions_SourceSqlText]
    (
          [SqlHandle] varbinary(64) NOT NULL PRIMARY KEY
        , [Text] nvarchar(max) NULL
    );

    IF @SessionIds IS NOT NULL
    BEGIN
        IF EXISTS
        (
            SELECT 1 FROM [monitor].[TVF_ParseBigintList](@SessionIds)
            WHERE [IsValid] = 0 OR [NumberValue] NOT BETWEEN 0 AND 32767
        )
        OR EXISTS
        (
            SELECT [NumberValue]
            FROM [monitor].[TVF_ParseBigintList](@SessionIds)
            WHERE [IsValid] = 1
            GROUP BY [NumberValue]
            HAVING COUNT(*) > 1
        )
        BEGIN
            SET @StatusCode = 'INVALID_PARAMETER';
            SET @ErrorMessage = N'@SessionIds ist ungültig oder enthält Duplikate.';
        END
        ELSE
        BEGIN
            INSERT [#CurrentTransactions_SessionFilter]([SessionId])
            SELECT CONVERT(smallint, [NumberValue])
            FROM [monitor].[TVF_ParseBigintList](@SessionIds)
            WHERE [IsValid] = 1;
        END;
    END;

    IF @StatusCode = 'AVAILABLE'
       AND
       (
           COALESCE(@MinAlterSekunden, -1) < 0
           OR @MaxZeilen < 0
           OR @MaxSqlTextZeichen < 0
           OR @OutputMode NOT IN ('RAW', 'CONSOLE', 'NONE')
           OR @JsonErzeugen IS NULL
       )
    BEGIN
        SET @StatusCode = 'INVALID_PARAMETER';
        SET @ErrorMessage = N'Mindestens ein Parameter besitzt einen ungültigen Wert.';
    END;

    IF @StatusCode = 'AVAILABLE'
    BEGIN TRY
        IF @ParentCurrentStateSnapshotId IS NOT NULL
        BEGIN
            EXEC [sys].[sp_executesql] N'
                DECLARE @Probe int;
                SELECT @Probe=0 FROM [#CurrentOverview_CurrentStateSnapshot_Context] WHERE 1=0;
                SELECT @Probe=0 FROM [#CurrentOverview_CurrentStateSnapshot_SourceStatus] WHERE 1=0;
                SELECT @Probe=0 FROM [#CurrentOverview_CurrentStateSnapshot_SessionTransactions] WHERE 1=0;
                SELECT @Probe=0 FROM [#CurrentOverview_CurrentStateSnapshot_ActiveTransactions] WHERE 1=0;
                SELECT @Probe=0 FROM [#CurrentOverview_CurrentStateSnapshot_DatabaseTransactions] WHERE 1=0;
                SELECT @Probe=0 FROM [#CurrentOverview_CurrentStateSnapshot_Sessions] WHERE 1=0;
                SELECT @Probe=0 FROM [#CurrentOverview_CurrentStateSnapshot_Requests] WHERE 1=0;
                SELECT @Probe=0 FROM [#CurrentOverview_CurrentStateSnapshot_SqlText] WHERE 1=0;';

            IF NOT EXISTS
            (
                SELECT 1
                FROM [#CurrentOverview_CurrentStateSnapshot_Context]
                WHERE [SnapshotId]=@ParentCurrentStateSnapshotId
                  AND [OwnerSessionId]=CONVERT(smallint,@@SPID)
                  AND [ContractVersion]=2
            )
                THROW 51020,N'Die Parent-Snapshot-ID gehört nicht zum aktuellen Aufruf.',1;

            INSERT [#CurrentTransactions_SourceSessionTransactions]
            SELECT [session_id],[transaction_id]
            FROM [#CurrentOverview_CurrentStateSnapshot_SessionTransactions]
            WHERE [SnapshotId]=@ParentCurrentStateSnapshotId;

            INSERT [#CurrentTransactions_SourceActiveTransactions]
            SELECT [transaction_id],[transaction_begin_time],[transaction_type],[transaction_state]
            FROM [#CurrentOverview_CurrentStateSnapshot_ActiveTransactions]
            WHERE [SnapshotId]=@ParentCurrentStateSnapshotId;

            INSERT [#CurrentTransactions_SourceDatabaseTransactions]
            SELECT
                  [transaction_id],[database_id],[database_transaction_log_bytes_used]
                , [database_transaction_log_bytes_reserved]
            FROM [#CurrentOverview_CurrentStateSnapshot_DatabaseTransactions]
            WHERE [SnapshotId]=@ParentCurrentStateSnapshotId;

            INSERT [#CurrentTransactions_SourceSessions]
            SELECT
                  [session_id],[is_user_process],[status],[open_transaction_count]
                , [login_name],[host_name],[program_name]
            FROM [#CurrentOverview_CurrentStateSnapshot_Sessions]
            WHERE [SnapshotId]=@ParentCurrentStateSnapshotId;

            INSERT [#CurrentTransactions_SourceRequests]
            SELECT
                  [session_id],[request_id],[status],[database_id],[sql_handle]
                , [statement_start_offset],[statement_end_offset]
            FROM [#CurrentOverview_CurrentStateSnapshot_Requests]
            WHERE [SnapshotId]=@ParentCurrentStateSnapshotId;

            IF @MitSqlText=1
                INSERT [#CurrentTransactions_SourceSqlText]
                SELECT [SqlHandle],[Text]
                FROM [#CurrentOverview_CurrentStateSnapshot_SqlText]
                WHERE [SnapshotId]=@ParentCurrentStateSnapshotId;

            SELECT
                  @EvidenceSnapshotStartedAtUtc=MIN([CapturedAtUtc])
                , @EvidenceIsPartial=CONVERT(bit,MAX(CONVERT(int,[IsPartial])))
            FROM [#CurrentOverview_CurrentStateSnapshot_SourceStatus]
            WHERE [SnapshotId]=@ParentCurrentStateSnapshotId
              AND [SourceCode] IN
                  ('SESSION_TRANSACTIONS','ACTIVE_TRANSACTIONS','DATABASE_TRANSACTIONS',
                   'SESSIONS','REQUESTS','SQL_TEXT');
        END
        ELSE
        BEGIN
            SET @EvidenceSnapshotStartedAtUtc=SYSUTCDATETIME();
            INSERT [#CurrentTransactions_SourceSessionTransactions]
            SELECT [session_id],[transaction_id]
            FROM [sys].[dm_tran_session_transactions] WITH (NOLOCK);

            INSERT [#CurrentTransactions_SourceActiveTransactions]
            SELECT [transaction_id],[transaction_begin_time],[transaction_type],[transaction_state]
            FROM [sys].[dm_tran_active_transactions] WITH (NOLOCK);

            INSERT [#CurrentTransactions_SourceDatabaseTransactions]
            SELECT
                  [transaction_id],[database_id],[database_transaction_log_bytes_used]
                , [database_transaction_log_bytes_reserved]
            FROM [sys].[dm_tran_database_transactions] WITH (NOLOCK);

            INSERT [#CurrentTransactions_SourceSessions]
            SELECT
                  [session_id],[is_user_process],[status],[open_transaction_count]
                , [login_name],[host_name],[program_name]
            FROM [sys].[dm_exec_sessions] WITH (NOLOCK);

            INSERT [#CurrentTransactions_SourceRequests]
            SELECT
                  [session_id],[request_id],[status],[database_id],[sql_handle]
                , [statement_start_offset],[statement_end_offset]
            FROM [sys].[dm_exec_requests] WITH (NOLOCK);

            IF @MitSqlText=1
                INSERT [#CurrentTransactions_SourceSqlText]
                SELECT [h].[SqlHandle],[t].[text]
                FROM
                (
                    SELECT [sql_handle] AS [SqlHandle]
                    FROM [#CurrentTransactions_SourceRequests]
                    WHERE [sql_handle] IS NOT NULL
                    GROUP BY [sql_handle]
                ) AS [h]
                OUTER APPLY [sys].[dm_exec_sql_text]([h].[SqlHandle]) AS [t];
        END;

        INSERT [#CurrentTransactions_Result]
        (
              [SessionId], [TransactionId], [TransactionBeginTimeUtc]
            , [TransactionAgeSeconds], [TransactionType], [TransactionState]
            , [OpenTransactionCount], [LoginName], [HostName], [ProgramName]
            , [SessionStatus], [RequestStatus], [DatabaseId], [DatabaseName]
            , [LogBytesUsed], [LogBytesReserved]
            , [StatementTextCharacters], [StatementTextBytes], [StatementTextIsTruncated], [StatementText]
        )
        SELECT TOP (@Candidates)
              [st].[session_id]
            , [at].[transaction_id]
            , [at].[transaction_begin_time]
            , DATEDIFF_BIG(SECOND, [at].[transaction_begin_time], GETDATE())
            , [at].[transaction_type]
            , [at].[transaction_state]
            , [s].[open_transaction_count]
            , [s].[login_name]
            , [s].[host_name]
            , [s].[program_name]
            , [s].[status]
            , [r].[status]
            , COALESCE([r].[database_id], [dt].[database_id])
            , [d].[name]
            , [dt].[database_transaction_log_bytes_used]
            , [dt].[database_transaction_log_bytes_reserved]
            , NULL,NULL,CONVERT(bit,0),CASE WHEN @MitSqlText = 1 THEN [statementText].[StatementText] END
        FROM [#CurrentTransactions_SourceSessionTransactions] AS [st]
        INNER JOIN [#CurrentTransactions_SourceActiveTransactions] AS [at]
          ON [at].[transaction_id] = [st].[transaction_id]
        INNER JOIN [#CurrentTransactions_SourceSessions] AS [s]
          ON [s].[session_id] = [st].[session_id]
        LEFT JOIN [#CurrentTransactions_SourceRequests] AS [r]
          ON [r].[session_id] = [st].[session_id]
        LEFT JOIN [#CurrentTransactions_SourceDatabaseTransactions] AS [dt]
          ON [dt].[transaction_id] = [st].[transaction_id]
        LEFT JOIN [master].[sys].[databases] AS [d] WITH (NOLOCK)
          ON [d].[database_id] = COALESCE([r].[database_id], [dt].[database_id])
        LEFT JOIN [#CurrentTransactions_SourceSqlText] AS [sqlText]
          ON [sqlText].[SqlHandle]=CASE WHEN @MitSqlText=1 THEN [r].[sql_handle] END
        OUTER APPLY [monitor].[TVF_StatementText]
        (
              [sqlText].[Text]
            , [r].[statement_start_offset]
            , [r].[statement_end_offset]
        ) AS [statementText]
        WHERE (@SystemSessionsEinbeziehen = 1 OR [s].[is_user_process] = 1)
          AND (@NurSleeping = 0 OR [s].[status] = N'sleeping')
          AND DATEDIFF_BIG(SECOND, [at].[transaction_begin_time], GETDATE()) >= @MinAlterSekunden
          AND
          (
              @SessionIds IS NULL
              OR EXISTS
                 (
                     SELECT 1 FROM [#CurrentTransactions_SessionFilter] AS [f]
                     WHERE [f].[SessionId] = [st].[session_id]
                 )
          )
        ORDER BY
              DATEDIFF_BIG(SECOND, [at].[transaction_begin_time], GETDATE()) DESC
            , [st].[session_id]
            , [at].[transaction_id];

        DECLARE @TruncatedValueCount bigint=0,@LargestRequiredCharacters bigint=NULL;
        EXEC [monitor].[InternalProjectUnicodeTextColumn]
              @SourceTable=N'#CurrentTransactions_Result',@TextColumn=N'StatementText'
            , @CharactersColumn=N'StatementTextCharacters',@BytesColumn=N'StatementTextBytes'
            , @IsTruncatedColumn=N'StatementTextIsTruncated',@MaxCharacters=@MaxSqlTextZeichen
            , @TruncatedValueCount=@TruncatedValueCount OUTPUT,@LargestRequiredCharacters=@LargestRequiredCharacters OUTPUT;
        EXEC [monitor].[InternalEmitTruncationWarning]
              @TruncatedValueCount=@TruncatedValueCount,@ParameterName=N'@MaxSqlTextZeichen'
            , @ParameterValue=@MaxSqlTextZeichen,@LargestRequiredCharacters=@LargestRequiredCharacters
            , @PrintMeldungen=@PrintMeldungen;

        SELECT @RowCount = COUNT_BIG(*) FROM [#CurrentTransactions_Result];
        SET @HasMoreRows = CONVERT(bit, CASE WHEN @Limit < 9223372036854775807 AND @RowCount > @Limit THEN 1 ELSE 0 END);
        IF @EvidenceIsPartial=1 SET @StatusCode='AVAILABLE_LIMITED';
    END TRY
    BEGIN CATCH
        SET @ErrorNumber = ERROR_NUMBER();
        SET @ErrorMessage = ERROR_MESSAGE();
        SET @StatusCode = CASE WHEN @ErrorNumber IN (229, 262, 297, 300, 371, 916) THEN 'DENIED_PERMISSION'
                               WHEN @ErrorNumber = 1222 THEN 'TIMEOUT'
                               WHEN @ParentCurrentStateSnapshotId IS NOT NULL
                                AND @ErrorNumber IN (208, 51020) THEN 'INVALID_PARENT_SNAPSHOT'
                               ELSE 'ERROR_HANDLED' END;
        INSERT [#CurrentTransactions_Warnings] VALUES (@StatusCode, @ErrorNumber, @ErrorMessage);
    END CATCH;

    IF @PrintMeldungen = 1 AND @StatusCode <> 'AVAILABLE'
    BEGIN
        SET @Message = FORMATMESSAGE(N'WARNUNG USP_CurrentTransactions [%s]: %s', @StatusCode, COALESCE(@ErrorMessage, N'Unbekannter Fehler.'));
        RAISERROR(N'%s', 10, 1, @Message) WITH NOWAIT;
    END;

    IF @OutputMode <> 'NONE'
    BEGIN
        SELECT
              N'USP_CurrentTransactions' AS [ModuleName]
            , @Now AS [CollectionTimeUtc]
            , @EvidenceSnapshotStartedAtUtc AS [EvidenceSnapshotStartedAtUtc]
            , @EvidenceSnapshotId AS [EvidenceSnapshotId]
            , @StatusCode AS [StatusCode]
            , CONVERT(bit, CASE WHEN @StatusCode = 'AVAILABLE' THEN 0 ELSE 1 END) AS [IsPartial]
            , CASE WHEN @RowCount > @Limit THEN @Limit ELSE @RowCount END AS [ReturnedRowCount]
            , @HasMoreRows AS [HasMoreRows]
            , @ErrorNumber AS [ErrorNumber]
            , @ErrorMessage AS [ErrorMessage];

        IF @OutputMode = 'RAW'
        BEGIN
            SELECT TOP (@Limit) *
            FROM [#CurrentTransactions_Result]
            ORDER BY [TransactionAgeSeconds] DESC, [SessionId], [TransactionId];
        END
        ELSE
        BEGIN
            SELECT TOP (@Limit)
                  N'Aktive Transaktion' AS [Ergebnis]
                , [SessionId] AS [Session]
                , [TransactionId] AS [Transaktion]
                , [DatabaseName] AS [Datenbank]
                , [LoginName] AS [Login]
                , [HostName] AS [Host]
                , [ProgramName] AS [Programm]
                , [SessionStatus] AS [Session-Status]
                , [RequestStatus] AS [Request-Status]
                , CONCAT(CONVERT(varchar(30), [TransactionAgeSeconds]), N' s') AS [Alter]
                , CONVERT(decimal(19, 2), [LogBytesUsed] / 1048576.0) AS [Log verwendet MB]
                , CONVERT(decimal(19, 2), [LogBytesReserved] / 1048576.0) AS [Log reserviert MB]
                , [SessionId] AS [Session_SQL]
                , [StatementText] AS [SQL-Text]
            FROM [#CurrentTransactions_Result]
            ORDER BY [TransactionAgeSeconds] DESC, [SessionId], [TransactionId];
        END;

        SELECT * FROM [#CurrentTransactions_Warnings] ORDER BY [StatusCode];
    END;

    IF @JsonErzeugen = 1
    BEGIN
        DECLARE @Meta nvarchar(max) =
        (
            SELECT
                  N'CurrentTransactions' AS [resultName]
                , 2 AS [schemaVersion]
                , @Now AS [generatedAtUtc]
                , @EvidenceSnapshotStartedAtUtc AS [evidenceSnapshotStartedAtUtc]
                , @EvidenceSnapshotId AS [evidenceSnapshotId]
                , @StatusCode AS [statusCode]
                , CONVERT(bit,CASE WHEN @StatusCode='AVAILABLE' THEN 0 ELSE 1 END) AS [isPartial]
                , @MaxZeilen AS [requestedMaxRows]
                , CASE WHEN @RowCount > @Limit THEN @Limit ELSE @RowCount END AS [returnedRows]
                , @HasMoreRows AS [hasMoreRows]
            FOR JSON PATH, WITHOUT_ARRAY_WRAPPER, INCLUDE_NULL_VALUES
        );
        DECLARE @Data nvarchar(max) =
        (
            SELECT TOP (@Limit) *
            FROM [#CurrentTransactions_Result]
            ORDER BY [TransactionAgeSeconds] DESC, [SessionId], [TransactionId]
            FOR JSON PATH, INCLUDE_NULL_VALUES
        );
        DECLARE @Warnings nvarchar(max) =
        (
            SELECT * FROM [#CurrentTransactions_Warnings] ORDER BY [StatusCode]
            FOR JSON PATH, INCLUDE_NULL_VALUES
        );
        SET @Json = CONCAT(N'{"meta":', COALESCE(@Meta, N'{}'), N',"transactions":', COALESCE(@Data, N'[]'), N',"warnings":', COALESCE(@Warnings, N'[]'), N'}');
    END;
    IF @ConsoleResultRequested = 1
    BEGIN
        EXEC [monitor].[InternalEmitConsoleResult]
              @SourceTable=N'#CurrentTransactions_Result'
            , @ResultLabel=N'Aktuelle Transaktionen'
            , @EmptyMessage=N'Keine aktiven Transaktionen';
    END;
    IF @TableResultRequested = 1
    BEGIN
        EXEC [monitor].[InternalWriteResultTable]
              @SourceTable = N'#CurrentTransactions_Result'
            , @TargetTable=@TableTarget
            , @ThrowOnError = 1;
    END;
END;
GO
-- END SOURCE: Code/02_CurrentState/050_USP_CurrentTransactions.sql

-- BEGIN SOURCE: Code/02_CurrentState/060_USP_CurrentMemoryGrants.sql
/*
===============================================================================
Objekt       : monitor.USP_CurrentMemoryGrants
Version      : 3.0.0
Stand        : 2026-07-23
Typ          : Stored Procedure
Zweck        : Liefert aktuell wartende und gewährte Query Memory Grants sowie
               Resource-Governor-, Pool- und Semaphore-Grenzen.
SQL-Version  : SQL Server 2019 oder neuer.
Datenquellen : sys.dm_exec_query_memory_grants, sys.dm_exec_sessions,
               sys.dm_exec_requests, sys.dm_exec_sql_text, sys.databases,
               sys.dm_resource_governor_workload_groups,
               sys.dm_resource_governor_resource_pools,
               sys.dm_exec_query_resource_semaphores.
Parameter    : @SessionIds, @AktuelleSessionEinbeziehen, @NurWartende,
               @MinRequestedMb, @MinGrantedMb, @MitSqlText,
               @MaxSqlTextZeichen, @MaxZeilen, @ResultSetArt,
               @JsonErzeugen, @Json OUTPUT, @PrintMeldungen, @Hilfe.
Ausgabe      : RAW = stabile technische Resultsets; CONSOLE = formatierte,
               menschenlesbare Darstellung; NONE = keine Resultsets.
               @JsonErzeugen=1 erzeugt unabhängig davon ein JSON-Envelope.
Berechtigung : VIEW SERVER STATE (2019) bzw. VIEW SERVER PERFORMANCE STATE.
Eigenlast    : Gering; die DMV enthält nur aktuelle Grants/Anforderungen.
Locking      : Keine Benutzerobjekte.
Partial      : Fehlender SQL-Text oder nicht auflösbare Zusatzmetadaten bleiben
               NULL; Fehler werden strukturiert ausgegeben.
Beispiele    : EXEC monitor.USP_CurrentMemoryGrants;
               EXEC monitor.USP_CurrentMemoryGrants
                    @NurWartende=1,@ResultSetArt='console';
               DECLARE @J nvarchar(max);
               EXEC monitor.USP_CurrentMemoryGrants
                    @ResultSetArt='none',@JsonErzeugen=1,@Json=@J OUTPUT;
               SELECT @J AS [Json];
Änderungen   : 2.0.0 - Resource-Governor-Grenzen und Prozentkennzahlen ergänzt;
                         RAW/CONSOLE/NONE sowie JSON-Envelope eingeführt.
               1.0.0 - Erstfassung Phase 1B.
===============================================================================
*/
CREATE OR ALTER PROCEDURE [monitor].[USP_CurrentMemoryGrants]
      @SessionIds                   nvarchar(max)  = NULL
    , @AktuelleSessionEinbeziehen   bit            = 0
    , @NurWartende                  bit            = 0
    , @MinRequestedMb               decimal(19,2)  = NULL
    , @MinGrantedMb                 decimal(19,2)  = NULL
    , @MitSqlText                   bit            = 1
    , @MaxSqlTextZeichen            int            = 3000
    , @MaxZeilen                    int            = 1000
    , @ResultSetArt                 varchar(16)    = 'CONSOLE'
    , @ResultTablesJson               nvarchar(max) = NULL
    , @JsonErzeugen                 bit            = 0
    , @Json                         nvarchar(max)  = NULL OUTPUT
    , @PrintMeldungen               bit            = 1
    , @Hilfe                        bit            = 0
    , @ParentCurrentStateSnapshotId uniqueidentifier = NULL
AS
BEGIN
    SET NOCOUNT ON;
    SET LOCK_TIMEOUT 0;

    SET @Json = NULL;

    DECLARE @ResultSetArtNormalisiert varchar(16) =
        UPPER(LTRIM(RTRIM(COALESCE(@ResultSetArt, ''))));
    DECLARE @TableResultRequested bit = CASE WHEN @ResultSetArtNormalisiert = 'TABLE' THEN 1 ELSE 0 END;
    DECLARE @ConsoleResultRequested bit = CASE WHEN @ResultSetArtNormalisiert = 'CONSOLE' THEN 1 ELSE 0 END;
    DECLARE @TableTarget sysname=NULL;
    IF @TableResultRequested=0 AND NULLIF(LTRIM(RTRIM(COALESCE(@ResultTablesJson,N''))),N'') IS NOT NULL THROW 51011,N'@ResultTablesJson ist ausschließlich mit @ResultSetArt=TABLE zulässig.',1;
    IF @TableResultRequested=1 EXEC [monitor].[InternalPrepareSingleResultTable] @ResultTablesJson=@ResultTablesJson,@ResultName=N'memoryGrants',@TargetTable=@TableTarget OUTPUT,@ThrowOnError=1;
    IF @TableResultRequested = 1 OR @ConsoleResultRequested = 1 SET @ResultSetArtNormalisiert = 'NONE';
    DECLARE @EffectiveMaxZeilen bigint =
        CASE WHEN @MaxZeilen IS NULL OR @MaxZeilen = 0
             THEN CONVERT(bigint, 9223372036854775807)
             WHEN @MaxZeilen > 0 THEN CONVERT(bigint, @MaxZeilen)
             ELSE CONVERT(bigint, 0) END;
    DECLARE @CandidateMaxZeilen bigint =
        CASE WHEN @MaxZeilen IS NULL OR @MaxZeilen = 0
             THEN CONVERT(bigint, 9223372036854775807)
             WHEN @MaxZeilen > 0 AND @MaxZeilen < 2147483647
             THEN CONVERT(bigint, @MaxZeilen) + 1
             WHEN @MaxZeilen > 0 THEN CONVERT(bigint, @MaxZeilen)
             ELSE CONVERT(bigint, 0) END;
    DECLARE @MonitorPrintMessage nvarchar(2048);

    IF @Hilfe = 1
    BEGIN
        PRINT N'monitor.USP_CurrentMemoryGrants';
        PRINT N'Die Procedure liefert aktuell wartende und gewährte Query Memory Grants einschließlich der Resource-Governor-Grenzen.';
        PRINT N'@SessionIds=NULL (Pipe-Liste); @AktuelleSessionEinbeziehen=0; @NurWartende=0; @MinRequestedMb/@MinGrantedMb=NULL.';
        PRINT N'@MitSqlText=1; @MaxSqlTextZeichen positiv begrenzt, NULL/0 liefert vollständigen Text; @MaxZeilen positiv begrenzt, NULL/0 unbegrenzt.';
        PRINT N'@ResultSetArt=CONSOLE (Default)|RAW|TABLE|NONE; Steuerwert wird case-insensitiv verarbeitet.';
        PRINT N'@JsonErzeugen=1 setzt @Json OUTPUT auf ein Envelope mit meta, memoryGrants und warnings.';
        PRINT N'RequestMaxMemoryGrantPercent ist decimal(9,4); der Datentyp ist nicht Bestandteil des Spaltennamens.';
        RETURN;
    END;

    DECLARE @CollectionTimeUtc datetime2(3) = SYSUTCDATETIME();
    DECLARE @StatusCode varchar(40) = 'AVAILABLE';
    DECLARE @IsPartial bit = 0;
    DECLARE @CandidateRowCount bigint = 0;
    DECLARE @RowCount bigint = 0;
    DECLARE @HasMoreRows bit = 0;
    DECLARE @ErrorNumber int = NULL;
    DECLARE @ErrorMessage nvarchar(2048) = NULL;
    DECLARE @Detail nvarchar(2000) = NULL;
    DECLARE @RequiredPermission nvarchar(256) =
        CASE WHEN TRY_CONVERT(int, SERVERPROPERTY(N'ProductMajorVersion')) >= 16
             THEN N'VIEW SERVER PERFORMANCE STATE'
             ELSE N'VIEW SERVER STATE' END;
    DECLARE @EvidenceSnapshotId uniqueidentifier=COALESCE(@ParentCurrentStateSnapshotId,NEWID());
    DECLARE @EvidenceSnapshotStartedAtUtc datetime2(3)=@CollectionTimeUtc;

    CREATE TABLE [#CurrentMemoryGrants_SessionIdFilter]
    (
        [SessionId] smallint NOT NULL PRIMARY KEY
    );

    IF @SessionIds IS NOT NULL
    BEGIN
        IF EXISTS
        (
            SELECT 1
            FROM [monitor].[TVF_ParseBigintList](@SessionIds)
            WHERE [IsValid] = 0 OR [NumberValue] NOT BETWEEN 1 AND 32767
        )
        BEGIN
            SET @StatusCode = 'INVALID_PARAMETER';
            SET @ErrorMessage = N'@SessionIds enthält einen ungültigen Session-Identifier.';
        END
        ELSE
            INSERT [#CurrentMemoryGrants_SessionIdFilter]([SessionId])
            SELECT CONVERT(smallint,[NumberValue])
            FROM [monitor].[TVF_ParseBigintList](@SessionIds)
            GROUP BY [NumberValue];
    END;

    CREATE TABLE [#CurrentMemoryGrants_Result]
    (
          [SessionId]                              smallint       NULL
        , [RequestId]                              int            NULL
        , [SchedulerId]                            int            NULL
        , [Dop]                                    smallint       NULL
        , [RequestTime]                            datetime       NULL
        , [GrantTime]                              datetime       NULL
        , [WaitTimeMs]                             bigint         NULL
        , [IsWaiting]                              bit            NOT NULL
        , [IsSmall]                                bit            NULL
        , [RequestedMemoryMb]                      decimal(19,2)  NULL
        , [RequiredMemoryMb]                       decimal(19,2)  NULL
        , [GrantedMemoryMb]                        decimal(19,2)  NULL
        , [UsedMemoryMb]                           decimal(19,2)  NULL
        , [MaxUsedMemoryMb]                        decimal(19,2)  NULL
        , [IdealMemoryMb]                          decimal(19,2)  NULL
        , [GroupId]                                int            NULL
        , [WorkloadGroupName]                      sysname        NULL
        , [PoolId]                                 int            NULL
        , [PoolName]                               sysname        NULL
        , [ResourceSemaphoreId]                    smallint       NULL
        , [RequestMaxMemoryGrantPercent]           decimal(9,4)   NULL
        , [PoolMaxWorkspaceMemoryMb]               decimal(19,2)  NULL
        , [PoolTargetWorkspaceMemoryMb]            decimal(19,2)  NULL
        , [PoolUsedWorkspaceMemoryMb]              decimal(19,2)  NULL
        , [ConfiguredRequestMaxGrantMemoryMb]      decimal(19,2)  NULL
        , [TargetRequestMaxGrantMemoryMb]          decimal(19,2)  NULL
        , [HistoricalMaxRequestGrantMemoryMb]      decimal(19,2)  NULL
        , [RequestedOfRequestMaxPercent]        decimal(9,2)   NULL
        , [GrantedOfRequestMaxPercent]          decimal(9,2)   NULL
        , [UsedOfRequestMaxPercent]             decimal(9,2)   NULL
        , [MaxUsedOfRequestMaxPercent]          decimal(9,2)   NULL
        , [IdealOfRequestMaxPercent]            decimal(9,2)   NULL
        , [RequestedOfTargetMaxPercent]            decimal(9,2)   NULL
        , [GrantedOfTargetMaxPercent]              decimal(9,2)   NULL
        , [UsedOfGrantedPercent]                   decimal(9,2)   NULL
        , [MaxUsedOfGrantedPercent]                decimal(9,2)   NULL
        , [SemaphoreTargetMemoryMb]                decimal(19,2)  NULL
        , [SemaphoreMaxTargetMemoryMb]             decimal(19,2)  NULL
        , [SemaphoreTotalMemoryMb]                 decimal(19,2)  NULL
        , [SemaphoreAvailableMemoryMb]             decimal(19,2)  NULL
        , [SemaphoreGrantedMemoryMb]               decimal(19,2)  NULL
        , [SemaphoreUsedMemoryMb]                  decimal(19,2)  NULL
        , [SemaphoreGranteeCount]                  int            NULL
        , [SemaphoreWaiterCount]                   int            NULL
        , [ReservedWorkerCount]                    bigint         NULL
        , [UsedWorkerCount]                        bigint         NULL
        , [MaxUsedWorkerCount]                     bigint         NULL
        , [QueueId]                                smallint       NULL
        , [WaitOrder]                              int            NULL
        , [LoginName]                              nvarchar(128)  NULL
        , [HostName]                               nvarchar(128)  NULL
        , [ProgramName]                            nvarchar(128)  NULL
        , [DatabaseId]                             smallint       NULL
        , [DatabaseName]                           sysname        NULL
        , [RequestStatus]                          nvarchar(30)   NULL
        , [Command]                                nvarchar(32)   NULL
        , [ElapsedMs]                              int            NULL
        , [CpuMs]                                  int            NULL
        , [LogicalReads]                           bigint         NULL
        , [CurrentStatementCharacters]             bigint         NULL
        , [CurrentStatementBytes]                  bigint         NULL
        , [CurrentStatementIsTruncated]            bit            NOT NULL DEFAULT(0)
        , [CurrentStatement]                       nvarchar(max)  NULL
    );

    CREATE TABLE [#CurrentMemoryGrants_Warnings]
    (
          [WarningCode]    varchar(40)     NOT NULL
        , [WarningMessage] nvarchar(2048)  NOT NULL
    );
    CREATE TABLE [#CurrentMemoryGrants_SourceGrants]
    (
          [session_id] smallint NOT NULL
        , [request_id] int NOT NULL
        , [scheduler_id] int NULL
        , [dop] smallint NULL
        , [request_time] datetime NULL
        , [grant_time] datetime NULL
        , [wait_time_ms] bigint NULL
        , [requested_memory_kb] bigint NOT NULL
        , [required_memory_kb] bigint NULL
        , [granted_memory_kb] bigint NULL
        , [used_memory_kb] bigint NULL
        , [max_used_memory_kb] bigint NULL
        , [ideal_memory_kb] bigint NULL
        , [resource_semaphore_id] smallint NULL
        , [queue_id] smallint NULL
        , [wait_order] int NULL
        , [is_small] bit NULL
        , [sql_handle] varbinary(64) NULL
        , [group_id] int NULL
        , [pool_id] int NULL
        , [reserved_worker_count] bigint NULL
        , [used_worker_count] bigint NULL
        , [max_used_worker_count] bigint NULL
    );
    CREATE TABLE [#CurrentMemoryGrants_SourceSessions]
    (
          [session_id] smallint NOT NULL PRIMARY KEY
        , [login_name] nvarchar(128) NOT NULL
        , [host_name] nvarchar(128) NULL
        , [program_name] nvarchar(128) NULL
    );
    CREATE TABLE [#CurrentMemoryGrants_SourceRequests]
    (
          [session_id] smallint NOT NULL
        , [request_id] int NOT NULL
        , [database_id] smallint NOT NULL
        , [status] nvarchar(30) NOT NULL
        , [command] nvarchar(32) NOT NULL
        , [total_elapsed_time] int NOT NULL
        , [cpu_time] int NOT NULL
        , [logical_reads] bigint NOT NULL
        , [statement_start_offset] int NULL
        , [statement_end_offset] int NULL
        , PRIMARY KEY([session_id],[request_id])
    );
    CREATE TABLE [#CurrentMemoryGrants_SourceWorkloadGroups]
    (
          [group_id] int NOT NULL PRIMARY KEY
        , [name] sysname NOT NULL
        , [pool_id] int NOT NULL
        , [request_max_memory_grant_percent_numeric] decimal(9,4) NULL
        , [max_request_grant_memory_kb] bigint NULL
    );
    CREATE TABLE [#CurrentMemoryGrants_SourceResourcePools]
    (
          [pool_id] int NOT NULL PRIMARY KEY
        , [name] sysname NOT NULL
        , [max_memory_kb] bigint NULL
        , [target_memory_kb] bigint NULL
        , [used_memory_kb] bigint NULL
    );
    CREATE TABLE [#CurrentMemoryGrants_SourceSemaphores]
    (
          [pool_id] int NOT NULL
        , [resource_semaphore_id] smallint NOT NULL
        , [target_memory_kb] bigint NOT NULL
        , [max_target_memory_kb] bigint NULL
        , [total_memory_kb] bigint NOT NULL
        , [available_memory_kb] bigint NOT NULL
        , [granted_memory_kb] bigint NOT NULL
        , [used_memory_kb] bigint NOT NULL
        , [grantee_count] int NOT NULL
        , [waiter_count] int NOT NULL
        , PRIMARY KEY([pool_id],[resource_semaphore_id])
    );
    CREATE TABLE [#CurrentMemoryGrants_SourceSqlText]
    (
          [SqlHandle] varbinary(64) NOT NULL PRIMARY KEY
        , [Text] nvarchar(max) NULL
    );

    IF @StatusCode = 'AVAILABLE'
       AND (COALESCE(@MinRequestedMb, 0) < 0
       OR COALESCE(@MinGrantedMb, 0) < 0
       OR @MaxZeilen < 0
       OR @MaxSqlTextZeichen < 0
       OR @ResultSetArtNormalisiert NOT IN ('RAW', 'CONSOLE', 'NONE'))
    BEGIN
        SET @StatusCode = 'INVALID_PARAMETER';
        SET @ErrorMessage = N'Ungültiger Parameterwert. @ResultSetArt erlaubt CONSOLE (Default), RAW, TABLE oder NONE; die Schreibweise ist case-insensitiv.';
    END;

    IF @StatusCode = 'AVAILABLE'
    BEGIN TRY
        IF @ParentCurrentStateSnapshotId IS NOT NULL
        BEGIN
            EXEC [sys].[sp_executesql] N'
                DECLARE @Probe int;
                SELECT @Probe=0 FROM [#CurrentOverview_CurrentStateSnapshot_Context] WHERE 1=0;
                SELECT @Probe=0 FROM [#CurrentOverview_CurrentStateSnapshot_SourceStatus] WHERE 1=0;
                SELECT @Probe=0 FROM [#CurrentOverview_CurrentStateSnapshot_MemoryGrants] WHERE 1=0;
                SELECT @Probe=0 FROM [#CurrentOverview_CurrentStateSnapshot_ResourceSemaphores] WHERE 1=0;
                SELECT @Probe=0 FROM [#CurrentOverview_CurrentStateSnapshot_Sessions] WHERE 1=0;
                SELECT @Probe=0 FROM [#CurrentOverview_CurrentStateSnapshot_Requests] WHERE 1=0;
                SELECT @Probe=0 FROM [#CurrentOverview_CurrentStateSnapshot_WorkloadGroups] WHERE 1=0;
                SELECT @Probe=0 FROM [#CurrentOverview_CurrentStateSnapshot_ResourcePools] WHERE 1=0;
                SELECT @Probe=0 FROM [#CurrentOverview_CurrentStateSnapshot_SqlText] WHERE 1=0;';

            IF NOT EXISTS
            (
                SELECT 1
                FROM [#CurrentOverview_CurrentStateSnapshot_Context]
                WHERE [SnapshotId]=@ParentCurrentStateSnapshotId
                  AND [OwnerSessionId]=CONVERT(smallint,@@SPID)
                  AND [ContractVersion]=2
            )
                THROW 51020,N'Die Parent-Snapshot-ID gehört nicht zum aktuellen Aufruf.',1;

            INSERT [#CurrentMemoryGrants_SourceGrants]
            SELECT
                  [session_id],[request_id],[scheduler_id],[dop],[request_time],[grant_time]
                , [wait_time_ms],[requested_memory_kb],[required_memory_kb],[granted_memory_kb]
                , [used_memory_kb],[max_used_memory_kb],[ideal_memory_kb]
                , [resource_semaphore_id],[queue_id],[wait_order],[is_small],[sql_handle]
                , [group_id],[pool_id],[reserved_worker_count],[used_worker_count],[max_used_worker_count]
            FROM [#CurrentOverview_CurrentStateSnapshot_MemoryGrants]
            WHERE [SnapshotId]=@ParentCurrentStateSnapshotId;

            INSERT [#CurrentMemoryGrants_SourceSemaphores]
            SELECT
                  [pool_id],[resource_semaphore_id],[target_memory_kb],[max_target_memory_kb]
                , [total_memory_kb],[available_memory_kb],[granted_memory_kb],[used_memory_kb]
                , [grantee_count],[waiter_count]
            FROM [#CurrentOverview_CurrentStateSnapshot_ResourceSemaphores]
            WHERE [SnapshotId]=@ParentCurrentStateSnapshotId;

            INSERT [#CurrentMemoryGrants_SourceSessions]
            SELECT [session_id],[login_name],[host_name],[program_name]
            FROM [#CurrentOverview_CurrentStateSnapshot_Sessions]
            WHERE [SnapshotId]=@ParentCurrentStateSnapshotId;

            INSERT [#CurrentMemoryGrants_SourceRequests]
            SELECT
                  [session_id],[request_id],[database_id],[status],[command]
                , [total_elapsed_time],[cpu_time],[logical_reads]
                , [statement_start_offset],[statement_end_offset]
            FROM [#CurrentOverview_CurrentStateSnapshot_Requests]
            WHERE [SnapshotId]=@ParentCurrentStateSnapshotId;

            INSERT [#CurrentMemoryGrants_SourceWorkloadGroups]
            SELECT
                  [group_id],[name],[pool_id],[request_max_memory_grant_percent_numeric]
                , [max_request_grant_memory_kb]
            FROM [#CurrentOverview_CurrentStateSnapshot_WorkloadGroups]
            WHERE [SnapshotId]=@ParentCurrentStateSnapshotId;

            INSERT [#CurrentMemoryGrants_SourceResourcePools]
            SELECT [pool_id],[name],[max_memory_kb],[target_memory_kb],[used_memory_kb]
            FROM [#CurrentOverview_CurrentStateSnapshot_ResourcePools]
            WHERE [SnapshotId]=@ParentCurrentStateSnapshotId;

            IF @MitSqlText=1
                INSERT [#CurrentMemoryGrants_SourceSqlText]
                SELECT [SqlHandle],[Text]
                FROM [#CurrentOverview_CurrentStateSnapshot_SqlText]
                WHERE [SnapshotId]=@ParentCurrentStateSnapshotId;

            SELECT
                  @EvidenceSnapshotStartedAtUtc=MIN([CapturedAtUtc])
                , @IsPartial=CONVERT(bit,MAX(CONVERT(int,[IsPartial])))
            FROM [#CurrentOverview_CurrentStateSnapshot_SourceStatus]
            WHERE [SnapshotId]=@ParentCurrentStateSnapshotId
              AND [SourceCode] IN
                  ('MEMORY_GRANTS','RESOURCE_SEMAPHORES','SESSIONS','REQUESTS',
                   'WORKLOAD_GROUPS','RESOURCE_POOLS','SQL_TEXT');
        END
        ELSE
        BEGIN
            SET @EvidenceSnapshotStartedAtUtc=SYSUTCDATETIME();
            INSERT [#CurrentMemoryGrants_SourceGrants]
            SELECT
                  [session_id],[request_id],[scheduler_id],[dop],[request_time],[grant_time]
                , [wait_time_ms],[requested_memory_kb],[required_memory_kb],[granted_memory_kb]
                , [used_memory_kb],[max_used_memory_kb],[ideal_memory_kb]
                , [resource_semaphore_id],[queue_id],[wait_order],[is_small],[sql_handle]
                , [group_id],[pool_id],[reserved_worker_count],[used_worker_count],[max_used_worker_count]
            FROM [sys].[dm_exec_query_memory_grants] WITH (NOLOCK);

            INSERT [#CurrentMemoryGrants_SourceSemaphores]
            SELECT
                  [pool_id],[resource_semaphore_id],[target_memory_kb],[max_target_memory_kb]
                , [total_memory_kb],[available_memory_kb],[granted_memory_kb],[used_memory_kb]
                , [grantee_count],[waiter_count]
            FROM [sys].[dm_exec_query_resource_semaphores] WITH (NOLOCK);

            INSERT [#CurrentMemoryGrants_SourceSessions]
            SELECT [session_id],[login_name],[host_name],[program_name]
            FROM [sys].[dm_exec_sessions] WITH (NOLOCK);

            INSERT [#CurrentMemoryGrants_SourceRequests]
            SELECT
                  [session_id],[request_id],[database_id],[status],[command]
                , [total_elapsed_time],[cpu_time],[logical_reads]
                , [statement_start_offset],[statement_end_offset]
            FROM [sys].[dm_exec_requests] WITH (NOLOCK);

            INSERT [#CurrentMemoryGrants_SourceWorkloadGroups]
            SELECT
                  [group_id],[name],[pool_id],[request_max_memory_grant_percent_numeric]
                , [max_request_grant_memory_kb]
            FROM [sys].[dm_resource_governor_workload_groups] WITH (NOLOCK);

            INSERT [#CurrentMemoryGrants_SourceResourcePools]
            SELECT [pool_id],[name],[max_memory_kb],[target_memory_kb],[used_memory_kb]
            FROM [sys].[dm_resource_governor_resource_pools] WITH (NOLOCK);

            IF @MitSqlText=1
                INSERT [#CurrentMemoryGrants_SourceSqlText]
                SELECT [h].[SqlHandle],[t].[text]
                FROM
                (
                    SELECT [sql_handle] AS [SqlHandle]
                    FROM [#CurrentMemoryGrants_SourceGrants]
                    WHERE [sql_handle] IS NOT NULL
                    GROUP BY [sql_handle]
                ) AS [h]
                OUTER APPLY [sys].[dm_exec_sql_text]([h].[SqlHandle]) AS [t];
        END;

        INSERT [#CurrentMemoryGrants_Result]
        (
              [SessionId], [RequestId], [SchedulerId], [Dop], [RequestTime], [GrantTime]
            , [WaitTimeMs], [IsWaiting], [IsSmall], [RequestedMemoryMb], [RequiredMemoryMb]
            , [GrantedMemoryMb], [UsedMemoryMb], [MaxUsedMemoryMb], [IdealMemoryMb]
            , [GroupId], [WorkloadGroupName], [PoolId], [PoolName], [ResourceSemaphoreId]
            , [RequestMaxMemoryGrantPercent], [PoolMaxWorkspaceMemoryMb]
            , [PoolTargetWorkspaceMemoryMb], [PoolUsedWorkspaceMemoryMb]
            , [ConfiguredRequestMaxGrantMemoryMb], [TargetRequestMaxGrantMemoryMb]
            , [HistoricalMaxRequestGrantMemoryMb], [RequestedOfRequestMaxPercent]
            , [GrantedOfRequestMaxPercent], [UsedOfRequestMaxPercent]
            , [MaxUsedOfRequestMaxPercent], [IdealOfRequestMaxPercent]
            , [RequestedOfTargetMaxPercent], [GrantedOfTargetMaxPercent]
            , [UsedOfGrantedPercent], [MaxUsedOfGrantedPercent]
            , [SemaphoreTargetMemoryMb], [SemaphoreMaxTargetMemoryMb]
            , [SemaphoreTotalMemoryMb], [SemaphoreAvailableMemoryMb]
            , [SemaphoreGrantedMemoryMb], [SemaphoreUsedMemoryMb]
            , [SemaphoreGranteeCount], [SemaphoreWaiterCount]
            , [ReservedWorkerCount], [UsedWorkerCount], [MaxUsedWorkerCount]
            , [QueueId], [WaitOrder], [LoginName], [HostName], [ProgramName]
            , [DatabaseId], [DatabaseName], [RequestStatus], [Command]
            , [ElapsedMs], [CpuMs], [LogicalReads]
            , [CurrentStatementCharacters], [CurrentStatementBytes], [CurrentStatementIsTruncated], [CurrentStatement]
        )
        SELECT TOP (@CandidateMaxZeilen)
              [g].[session_id]
            , [g].[request_id]
            , [g].[scheduler_id]
            , [g].[dop]
            , [g].[request_time]
            , [g].[grant_time]
            , [g].[wait_time_ms]
            , CONVERT(bit, CASE WHEN [g].[grant_time] IS NULL THEN 1 ELSE 0 END)
            , [g].[is_small]
            , CONVERT(decimal(19,2), [g].[requested_memory_kb] / 1024.0)
            , CONVERT(decimal(19,2), [g].[required_memory_kb] / 1024.0)
            , CONVERT(decimal(19,2), [g].[granted_memory_kb] / 1024.0)
            , CONVERT(decimal(19,2), [g].[used_memory_kb] / 1024.0)
            , CONVERT(decimal(19,2), [g].[max_used_memory_kb] / 1024.0)
            , CONVERT(decimal(19,2), [g].[ideal_memory_kb] / 1024.0)
            , [g].[group_id]
            , [wg].[name]
            , [g].[pool_id]
            , [rp].[name]
            , [g].[resource_semaphore_id]
            , [calc].[RequestMaxMemoryGrantPercent]
            , [calc].[PoolMaxWorkspaceMemoryMb]
            , [calc].[PoolTargetWorkspaceMemoryMb]
            , [calc].[PoolUsedWorkspaceMemoryMb]
            , [calc].[ConfiguredRequestMaxGrantMemoryMb]
            , [calc].[TargetRequestMaxGrantMemoryMb]
            , CONVERT(decimal(19,2), [wg].[max_request_grant_memory_kb] / 1024.0)
            , CONVERT(decimal(9,2), 100.0 * [g].[requested_memory_kb]
                / NULLIF([calc].[ConfiguredRequestMaxGrantMemoryKb], 0))
            , CONVERT(decimal(9,2), 100.0 * [g].[granted_memory_kb]
                / NULLIF([calc].[ConfiguredRequestMaxGrantMemoryKb], 0))
            , CONVERT(decimal(9,2), 100.0 * [g].[used_memory_kb]
                / NULLIF([calc].[ConfiguredRequestMaxGrantMemoryKb], 0))
            , CONVERT(decimal(9,2), 100.0 * [g].[max_used_memory_kb]
                / NULLIF([calc].[ConfiguredRequestMaxGrantMemoryKb], 0))
            , CONVERT(decimal(9,2), 100.0 * [g].[ideal_memory_kb]
                / NULLIF([calc].[ConfiguredRequestMaxGrantMemoryKb], 0))
            , CONVERT(decimal(9,2), 100.0 * [g].[requested_memory_kb]
                / NULLIF([calc].[TargetRequestMaxGrantMemoryKb], 0))
            , CONVERT(decimal(9,2), 100.0 * [g].[granted_memory_kb]
                / NULLIF([calc].[TargetRequestMaxGrantMemoryKb], 0))
            , CONVERT(decimal(9,2), 100.0 * [g].[used_memory_kb]
                / NULLIF([g].[granted_memory_kb], 0))
            , CONVERT(decimal(9,2), 100.0 * [g].[max_used_memory_kb]
                / NULLIF([g].[granted_memory_kb], 0))
            , CONVERT(decimal(19,2), [sem].[target_memory_kb] / 1024.0)
            , CONVERT(decimal(19,2), [sem].[max_target_memory_kb] / 1024.0)
            , CONVERT(decimal(19,2), [sem].[total_memory_kb] / 1024.0)
            , CONVERT(decimal(19,2), [sem].[available_memory_kb] / 1024.0)
            , CONVERT(decimal(19,2), [sem].[granted_memory_kb] / 1024.0)
            , CONVERT(decimal(19,2), [sem].[used_memory_kb] / 1024.0)
            , [sem].[grantee_count]
            , [sem].[waiter_count]
            , [g].[reserved_worker_count]
            , [g].[used_worker_count]
            , [g].[max_used_worker_count]
            , [g].[queue_id]
            , [g].[wait_order]
            , [s].[login_name]
            , [s].[host_name]
            , [s].[program_name]
            , [r].[database_id]
            , [d].[name]
            , [r].[status]
            , [r].[command]
            , [r].[total_elapsed_time]
            , [r].[cpu_time]
            , [r].[logical_reads]
            , NULL,NULL,CONVERT(bit,0)
            , CASE WHEN @MitSqlText = 1 THEN [statementText].[StatementText] END
        FROM [#CurrentMemoryGrants_SourceGrants] AS [g]
        LEFT JOIN [#CurrentMemoryGrants_SourceSessions] AS [s]
          ON [s].[session_id] = [g].[session_id]
        LEFT JOIN [#CurrentMemoryGrants_SourceRequests] AS [r]
          ON [r].[session_id] = [g].[session_id]
         AND [r].[request_id] = [g].[request_id]
        LEFT JOIN [sys].[databases] AS [d] WITH (NOLOCK)
          ON [d].[database_id] = [r].[database_id]
        LEFT JOIN [#CurrentMemoryGrants_SourceWorkloadGroups] AS [wg]
          ON [wg].[group_id] = [g].[group_id]
        LEFT JOIN [#CurrentMemoryGrants_SourceResourcePools] AS [rp]
          ON [rp].[pool_id] = [g].[pool_id]
        LEFT JOIN [#CurrentMemoryGrants_SourceSemaphores] AS [sem]
          ON [sem].[pool_id] = [g].[pool_id]
         AND [sem].[resource_semaphore_id] = [g].[resource_semaphore_id]
        LEFT JOIN [#CurrentMemoryGrants_SourceSqlText] AS [t]
          ON [t].[SqlHandle]=CASE WHEN @MitSqlText=1 THEN [g].[sql_handle] END
        OUTER APPLY [monitor].[TVF_StatementText]
        (
              [t].[Text]
            , [r].[statement_start_offset]
            , [r].[statement_end_offset]
        ) AS [statementText]
        OUTER APPLY
        (
            SELECT
                  [RequestMaxMemoryGrantPercent] = CONVERT(decimal(9,4), [wg].[request_max_memory_grant_percent_numeric])
                , [PoolMaxWorkspaceMemoryMb] = CONVERT(decimal(19,2), [rp].[max_memory_kb] / 1024.0)
                , [PoolTargetWorkspaceMemoryMb] = CONVERT(decimal(19,2), [rp].[target_memory_kb] / 1024.0)
                , [PoolUsedWorkspaceMemoryMb] = CONVERT(decimal(19,2), [rp].[used_memory_kb] / 1024.0)
                , [ConfiguredRequestMaxGrantMemoryKb] =
                    CONVERT(decimal(38,4), [rp].[max_memory_kb])
                    * CONVERT(decimal(38,4), [wg].[request_max_memory_grant_percent_numeric]) / 100.0
                , [TargetRequestMaxGrantMemoryKb] =
                    CONVERT(decimal(38,4), [rp].[target_memory_kb])
                    * CONVERT(decimal(38,4), [wg].[request_max_memory_grant_percent_numeric]) / 100.0
                , [ConfiguredRequestMaxGrantMemoryMb] = CONVERT
                  (
                      decimal(19,2),
                      CONVERT(decimal(38,4), [rp].[max_memory_kb])
                      * CONVERT(decimal(38,4), [wg].[request_max_memory_grant_percent_numeric]) / 100.0 / 1024.0
                  )
                , [TargetRequestMaxGrantMemoryMb] = CONVERT
                  (
                      decimal(19,2),
                      CONVERT(decimal(38,4), [rp].[target_memory_kb])
                      * CONVERT(decimal(38,4), [wg].[request_max_memory_grant_percent_numeric]) / 100.0 / 1024.0
                  )
        ) AS [calc]
        WHERE (NOT EXISTS (SELECT 1 FROM [#CurrentMemoryGrants_SessionIdFilter]) OR EXISTS (SELECT 1 FROM [#CurrentMemoryGrants_SessionIdFilter] AS [sf] WHERE [sf].[SessionId] = [g].[session_id]))
          AND (@AktuelleSessionEinbeziehen = 1 OR [g].[session_id] <> @@SPID)
          AND (@NurWartende = 0 OR [g].[grant_time] IS NULL)
          AND (@MinRequestedMb IS NULL OR [g].[requested_memory_kb] >= @MinRequestedMb * 1024.0)
          AND (@MinGrantedMb IS NULL OR [g].[granted_memory_kb] >= @MinGrantedMb * 1024.0)
        ORDER BY
              CASE WHEN [g].[grant_time] IS NULL THEN 1 ELSE 0 END DESC
            , [g].[requested_memory_kb] DESC
            , [g].[wait_time_ms] DESC
            , [g].[session_id]
            , [g].[request_id];

        DECLARE @TruncatedValueCount bigint=0,@LargestRequiredCharacters bigint=NULL;
        EXEC [monitor].[InternalProjectUnicodeTextColumn]
              @SourceTable=N'#CurrentMemoryGrants_Result',@TextColumn=N'CurrentStatement'
            , @CharactersColumn=N'CurrentStatementCharacters',@BytesColumn=N'CurrentStatementBytes'
            , @IsTruncatedColumn=N'CurrentStatementIsTruncated',@MaxCharacters=@MaxSqlTextZeichen
            , @TruncatedValueCount=@TruncatedValueCount OUTPUT,@LargestRequiredCharacters=@LargestRequiredCharacters OUTPUT;
        EXEC [monitor].[InternalEmitTruncationWarning]
              @TruncatedValueCount=@TruncatedValueCount,@ParameterName=N'@MaxSqlTextZeichen'
            , @ParameterValue=@MaxSqlTextZeichen,@LargestRequiredCharacters=@LargestRequiredCharacters
            , @PrintMeldungen=@PrintMeldungen;

        SELECT @CandidateRowCount = COUNT_BIG(*) FROM [#CurrentMemoryGrants_Result];
        SET @HasMoreRows = CONVERT(bit, CASE WHEN @CandidateRowCount > @EffectiveMaxZeilen THEN 1 ELSE 0 END);
        SET @RowCount = CASE WHEN @CandidateRowCount > @EffectiveMaxZeilen
                             THEN @EffectiveMaxZeilen ELSE @CandidateRowCount END;
        SET @Detail = CASE WHEN @RowCount = 0
                           THEN N'Aktuell keine passende Memory-Grant-Anforderung sichtbar.'
                           ELSE N'Memory Grants einschließlich Resource-Governor- und Semaphore-Kontext erfolgreich gelesen.' END;
        IF @IsPartial=1 SET @StatusCode='AVAILABLE_LIMITED';
    END TRY
    BEGIN CATCH
        SET @ErrorNumber = ERROR_NUMBER();
        SET @ErrorMessage = ERROR_MESSAGE();
        SET @IsPartial = 1;
        SET @StatusCode = CASE WHEN @ErrorNumber IN (229, 262, 297, 300, 371, 916) THEN 'DENIED_PERMISSION'
                               WHEN @ErrorNumber = 1222 THEN 'TIMEOUT'
                               WHEN @ParentCurrentStateSnapshotId IS NOT NULL
                                AND @ErrorNumber IN (208, 51020) THEN 'INVALID_PARENT_SNAPSHOT'
                               ELSE 'ERROR_HANDLED' END;
        SET @Detail = N'Memory-Grant-Abfrage fehlgeschlagen.';
        INSERT [#CurrentMemoryGrants_Warnings] VALUES(@StatusCode, COALESCE(@ErrorMessage, @Detail));
    END CATCH;

    IF @PrintMeldungen = 1 AND @StatusCode <> 'AVAILABLE'
    BEGIN
        SET @MonitorPrintMessage = FORMATMESSAGE
        (
            N'WARNUNG %s: %s',
            @StatusCode,
            COALESCE(@ErrorMessage, @Detail)
        );
        RAISERROR(N'%s', 10, 1, @MonitorPrintMessage) WITH NOWAIT;
    END;

    IF @JsonErzeugen = 1
    BEGIN
        DECLARE @MetaJson nvarchar(max);
        DECLARE @DataJson nvarchar(max);
        DECLARE @WarningsJson nvarchar(max);

        SET @MetaJson =
        (
            SELECT
                  N'CurrentMemoryGrants' AS [resultName]
                , 2 AS [schemaVersion]
                , @CollectionTimeUtc AS [generatedAtUtc]
                , @EvidenceSnapshotStartedAtUtc AS [evidenceSnapshotStartedAtUtc]
                , @EvidenceSnapshotId AS [evidenceSnapshotId]
                , @StatusCode AS [statusCode]
                , @IsPartial AS [isPartial]
                , @MaxZeilen AS [requestedMaxRows]
                , @RowCount AS [returnedRows]
                , @HasMoreRows AS [resultLimited]
                , @HasMoreRows AS [hasMoreRows]
                , @RequiredPermission AS [requiredPermission]
                , @ErrorNumber AS [errorNumber]
                , @ErrorMessage AS [errorMessage]
                , @Detail AS [detail]
            FOR JSON PATH, WITHOUT_ARRAY_WRAPPER, INCLUDE_NULL_VALUES
        );

        SET @DataJson =
        (
            SELECT TOP (@EffectiveMaxZeilen) [r].*
            FROM [#CurrentMemoryGrants_Result] AS [r]
            ORDER BY [r].[IsWaiting] DESC, [r].[RequestedMemoryMb] DESC,
                     [r].[WaitTimeMs] DESC, [r].[SessionId], [r].[RequestId]
            FOR JSON PATH, INCLUDE_NULL_VALUES
        );

        SET @WarningsJson =
        (
            SELECT [WarningCode] AS [code], [WarningMessage] AS [message]
            FROM [#CurrentMemoryGrants_Warnings]
            ORDER BY [WarningCode]
            FOR JSON PATH, INCLUDE_NULL_VALUES
        );

        SET @Json = CONCAT
        (
              N'{"meta":', COALESCE(@MetaJson, N'{}')
            , N',"memoryGrants":', COALESCE(@DataJson, N'[]')
            , N',"warnings":', COALESCE(@WarningsJson, N'[]')
            , N'}'
        );
    END;

    IF @ResultSetArtNormalisiert = 'RAW'
    BEGIN
        SELECT
              N'USP_CurrentMemoryGrants' AS [ModuleName]
            , @CollectionTimeUtc AS [CollectionTimeUtc]
            , @EvidenceSnapshotStartedAtUtc AS [EvidenceSnapshotStartedAtUtc]
            , @EvidenceSnapshotId AS [EvidenceSnapshotId]
            , @StatusCode AS [StatusCode]
            , @IsPartial AS [IsPartial]
            , @RowCount AS [RowCount]
            , @HasMoreRows AS [ResultLimited]
            , @RequiredPermission AS [RequiredPermission]
            , @ErrorNumber AS [ErrorNumber]
            , @ErrorMessage AS [ErrorMessage]
            , @Detail AS [Detail];

        SELECT TOP (@EffectiveMaxZeilen) [r].*
        FROM [#CurrentMemoryGrants_Result] AS [r]
        ORDER BY [r].[IsWaiting] DESC, [r].[RequestedMemoryMb] DESC,
                 [r].[WaitTimeMs] DESC, [r].[SessionId], [r].[RequestId];
    END
    ELSE IF @ResultSetArtNormalisiert = 'CONSOLE'
    BEGIN
        SELECT
              N'Query Memory Grants' AS [Ergebnis]
            , @CollectionTimeUtc AS [Stand_UTC]
            , @StatusCode AS [Status]
            , @RowCount AS [Zeilen]
            , @HasMoreRows AS [Ergebnis_begrenzt]
            , @Detail AS [Hinweis];

        SELECT TOP (@EffectiveMaxZeilen)
              CASE WHEN [r].[IsWaiting] = 1
                   THEN N'Wartender Memory Grant'
                   ELSE N'Gewährter Memory Grant' END AS [Ergebnis]
            , [r].[SessionId] AS [Session]
            , [r].[RequestId] AS [Request]
            , [r].[LoginName] AS [Login]
            , [r].[HostName] AS [Host]
            , [r].[ProgramName] AS [Programm]
            , [r].[DatabaseName] AS [Datenbank]
            , [r].[RequestStatus] AS [Request_Status]
            , [r].[Command] AS [Command]
            , CASE WHEN [r].[IsWaiting] = 1
                   THEN CONCAT(CONVERT(varchar(30), [r].[WaitTimeMs]), N' ms')
                   ELSE N'läuft' END AS [Grant_Status]

            , [r].[SessionId] AS [Session_Memory]
            , CONCAT(CONVERT(varchar(40), [r].[RequestedMemoryMb]), N' MB') AS [Angefordert]
            , CONCAT(CONVERT(varchar(40), [r].[RequiredMemoryMb]), N' MB') AS [Mindestens_erforderlich]
            , CONCAT(CONVERT(varchar(40), [r].[GrantedMemoryMb]), N' MB') AS [Gewährt]
            , CONCAT(CONVERT(varchar(40), [r].[UsedMemoryMb]), N' MB') AS [Verwendet]
            , CONCAT(CONVERT(varchar(40), [r].[MaxUsedMemoryMb]), N' MB') AS [Maximal_verwendet]
            , CONCAT(CONVERT(varchar(40), [r].[IdealMemoryMb]), N' MB') AS [Ideal]
            , CONCAT(CONVERT(varchar(40), [r].[UsedOfGrantedPercent]), N' %') AS [Verwendet_vom_Grant]
            , CONCAT(CONVERT(varchar(40), [r].[MaxUsedOfGrantedPercent]), N' %') AS [Maximal_verwendet_vom_Grant]

            , [r].[SessionId] AS [Session_ResourceGovernor]
            , [r].[WorkloadGroupName] AS [Workload_Group]
            , [r].[PoolName] AS [Resource_Pool]
            , CONCAT(CONVERT(varchar(40), [r].[RequestMaxMemoryGrantPercent]), N' %') AS [Max_Request_Grant_Prozent]
            , CONCAT(CONVERT(varchar(40), [r].[ConfiguredRequestMaxGrantMemoryMb]), N' MB') AS [Konfiguriertes_Request_Maximum]
            , CONCAT(CONVERT(varchar(40), [r].[TargetRequestMaxGrantMemoryMb]), N' MB') AS [Aktuelles_Target_Request_Maximum]
            , CONCAT(CONVERT(varchar(40), [r].[RequestedOfRequestMaxPercent]), N' %') AS [Angefordert_vom_konfigurierten_Maximum]
            , CONCAT(CONVERT(varchar(40), [r].[GrantedOfRequestMaxPercent]), N' %') AS [Gewährt_vom_konfigurierten_Maximum]
            , CONCAT(CONVERT(varchar(40), [r].[UsedOfRequestMaxPercent]), N' %') AS [Verwendet_vom_konfigurierten_Maximum]
            , CONCAT(CONVERT(varchar(40), [r].[SemaphoreAvailableMemoryMb]), N' MB') AS [Semaphore_aktuell_verfügbar]
            , [r].[SemaphoreWaiterCount] AS [Semaphore_Wartende]
            , [r].[CurrentStatement] AS [Aktuelles_Statement]
        FROM [#CurrentMemoryGrants_Result] AS [r]
        ORDER BY [r].[IsWaiting] DESC, [r].[RequestedMemoryMb] DESC,
                 [r].[WaitTimeMs] DESC, [r].[SessionId], [r].[RequestId];
    END;
    IF @ConsoleResultRequested = 1
    BEGIN
        EXEC [monitor].[InternalEmitConsoleResult]
              @SourceTable=N'#CurrentMemoryGrants_Result'
            , @ResultLabel=N'Aktuelle Memory Grants'
            , @EmptyMessage=N'Keine aktiven Memory Grants';
    END;
    IF @TableResultRequested = 1
    BEGIN
        EXEC [monitor].[InternalWriteResultTable]
              @SourceTable = N'#CurrentMemoryGrants_Result'
            , @TargetTable=@TableTarget
            , @ThrowOnError = 1;
    END;
END;
GO
-- END SOURCE: Code/02_CurrentState/060_USP_CurrentMemoryGrants.sql

-- BEGIN SOURCE: Code/02_CurrentState/070_USP_CurrentTempDB.sql
/*
===============================================================================
Objekt       : monitor.USP_CurrentTempDB
Version      : 4.0.0
Stand        : 2026-07-23
Zweck        : Zeigt aktuellen TempDB-Verbrauch je Session, optional Dateien
               und SQL-Server-2025-TempDB-Governance je Workload Group.
SQL-Version  : SQL Server 2019 oder neuer; Governance ab 2025 (17.x).
Datenquellen : sys.dm_exec_sessions, tempdb.sys.dm_db_session_space_usage,
               tempdb.sys.database_files, Resource-Governor-Katalog/DMV und
               master.sys.master_files; im Parentpfad gemeinsame Materialisierung.
Output       : sessions, tempdbFiles, tempdbGovernance und warnings;
               RAW, CONSOLE, NONE, JSON und benannte TABLE-Ziele.
Locking      : LOCK_TIMEOUT 0 für Quellen; vorheriger Sessionwert wird
               auch nach TABLE- und CONSOLE-Ausgabe wiederhergestellt.
Datenschutz  : Laufzeitwerte werden nur ausgegeben, nicht persistiert.
Änderungen   : 4.0.0 - SQL25-003 TempDB Resource Governance.
===============================================================================
*/
CREATE OR ALTER PROCEDURE [monitor].[USP_CurrentTempDB]
      @SessionIds                    nvarchar(max) = NULL
    , @AktuelleSessionEinbeziehen    bit           = 0
    , @MinNettoMb                    decimal(19,2)  = 0
    , @SystemSessionsEinbeziehen     bit           = 0
    , @MitDateien                    bit           = 1
    , @MaxZeilen                     int           = 1000
    , @ResultSetArt                  varchar(16)    = 'CONSOLE'
    , @ResultTablesJson              nvarchar(max) = NULL
    , @JsonErzeugen                  bit           = 0
    , @Json                          nvarchar(max)  = NULL OUTPUT
    , @PrintMeldungen                bit           = 1
    , @Hilfe                         bit           = 0
    , @ParentCurrentStateSnapshotId  uniqueidentifier = NULL
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @OriginalLockTimeout int=@@LOCK_TIMEOUT;
    DECLARE @RestoreLockTimeoutSql nvarchar(100);
    SET @Json=NULL;

    DECLARE @OutputMode varchar(16)=UPPER(LTRIM(RTRIM(COALESCE(@ResultSetArt,''))));
    DECLARE @TableResultRequested bit=CASE WHEN @OutputMode='TABLE' THEN 1 ELSE 0 END;
    DECLARE @ConsoleResultRequested bit=CASE WHEN @OutputMode='CONSOLE' THEN 1 ELSE 0 END;
    DECLARE @Limit bigint=CASE WHEN @MaxZeilen IS NULL OR @MaxZeilen=0
                              THEN CONVERT(bigint,9223372036854775807)
                              WHEN @MaxZeilen>0 THEN CONVERT(bigint,@MaxZeilen)
                              ELSE CONVERT(bigint,0) END;
    DECLARE @Candidates bigint=CASE WHEN @MaxZeilen IS NULL OR @MaxZeilen=0
                                   THEN CONVERT(bigint,9223372036854775807)
                                   WHEN @MaxZeilen<2147483647 THEN CONVERT(bigint,@MaxZeilen)+1
                                   ELSE CONVERT(bigint,@MaxZeilen) END;

    IF @Hilfe=1
    BEGIN
        PRINT N'monitor.USP_CurrentTempDB';
        PRINT N'@SessionIds=N''57|61''; NULL = keine Einschränkung.';
        PRINT N'@MitDateien=1 liefert tempdbFiles.';
        PRINT N'@MaxZeilen positiv = begrenzt; NULL/0 = unbegrenzt.';
        PRINT N'@ResultSetArt=CONSOLE (Default)|RAW|TABLE|NONE; JSON über @JsonErzeugen=1.';
        PRINT N'TABLE erlaubt sessions und tempdbGovernance.';
        PRINT N'tempdbGovernance trennt Limit, Wirksamkeit, aktuelle Nutzung, Peak und Verletzungszähler.';
        RETURN;
    END;

    DECLARE @Now datetime2(3)=SYSUTCDATETIME();
    DECLARE @ProductMajorVersion int=TRY_CONVERT(int,SERVERPROPERTY(N'ProductMajorVersion'));
    DECLARE @StatusCode varchar(40)='AVAILABLE';
    DECLARE @ErrorNumber int=NULL;
    DECLARE @ErrorMessage nvarchar(2048)=NULL;
    DECLARE @RowCount bigint=0;
    DECLARE @HasMoreRows bit=0;
    DECLARE @EvidenceSnapshotId uniqueidentifier=COALESCE(@ParentCurrentStateSnapshotId,NEWID());
    DECLARE @EvidenceSnapshotStartedAtUtc datetime2(3)=@Now;
    DECLARE @EvidenceIsPartial bit=0;
    DECLARE @TablePreflightStatus varchar(40);
    DECLARE @TablePreflightError nvarchar(2048);
    DECLARE @Sql nvarchar(max);

    CREATE TABLE [#CurrentTempDB_ResultTableMap]
    (
          [ResultName] sysname COLLATE SQL_Latin1_General_CP1_CS_AS NOT NULL PRIMARY KEY
        , [TargetTable] sysname COLLATE SQL_Latin1_General_CP1_CS_AS NOT NULL UNIQUE
    );

    CREATE TABLE [#CurrentTempDB_SessionFilter]([SessionId] smallint NOT NULL PRIMARY KEY);
    CREATE TABLE [#CurrentTempDB_Sessions]
    (
          [SessionId] smallint NOT NULL
        , [LoginName] nvarchar(128) NULL
        , [HostName] nvarchar(128) NULL
        , [ProgramName] nvarchar(128) NULL
        , [SessionStatus] nvarchar(30) NULL
        , [UserObjectsAllocatedMb] decimal(19,2) NOT NULL
        , [UserObjectsDeallocatedMb] decimal(19,2) NOT NULL
        , [UserObjectsNetMb] decimal(19,2) NOT NULL
        , [InternalObjectsAllocatedMb] decimal(19,2) NOT NULL
        , [InternalObjectsDeallocatedMb] decimal(19,2) NOT NULL
        , [InternalObjectsNetMb] decimal(19,2) NOT NULL
        , [TotalNetMb] decimal(19,2) NOT NULL
    );

    CREATE TABLE [#CurrentTempDB_Files]
    (
          [FileId] int NOT NULL
        , [LogicalName] sysname NOT NULL
        , [PhysicalName] nvarchar(260) NOT NULL
        , [FileTypeDesc] nvarchar(60) NOT NULL
        , [SizeMb] decimal(19,2) NOT NULL
        , [UsedMb] decimal(19,2) NULL
        , [FreeMb] decimal(19,2) NULL
        , [UsedPercent] decimal(9,2) NULL
        , [GrowthMb] decimal(19,2) NULL
        , [IsPercentGrowth] bit NOT NULL
    );

    CREATE TABLE [#CurrentTempDB_TempdbGovernance]
    (
          [GroupId] int NULL
        , [GroupName] sysname NULL
        , [PoolId] int NULL
        , [PoolName] sysname NULL
        , [ConfiguredGroupMaxTempdbDataMb] decimal(19,2) NULL
        , [ConfiguredGroupMaxTempdbDataPercent] decimal(9,4) NULL
        , [TempdbMaximumSizeMb] decimal(19,2) NULL
        , [EffectiveGroupMaxTempdbDataMb] decimal(19,2) NULL
        , [EffectiveLimitSource] varchar(40) NOT NULL
        , [IsPercentLimitEffective] bit NULL
        , [TempdbDataSpaceMb] decimal(19,2) NULL
        , [PeakTempdbDataSpaceMb] decimal(19,2) NULL
        , [EffectiveLimitUtilizationPercent] decimal(9,2) NULL
        , [TotalTempdbDataLimitViolationCount] bigint NULL
        , [HasRecordedLimitViolation] bit NULL
        , [StatisticsStartTime] datetime NULL
        , [IsResourceGovernorEnabled] bit NULL
        , [ReconfigurationPending] bit NULL
        , [SourceStatusCode] varchar(40) NOT NULL
        , [IsPartial] bit NOT NULL
        , [EvidenceLimit] nvarchar(1000) NULL
    );

    CREATE TABLE [#CurrentTempDB_Warnings]
    (
          [StatusCode] varchar(40) NOT NULL
        , [ErrorNumber] int NULL
        , [ErrorMessage] nvarchar(2048) NULL
    );

    CREATE TABLE [#CurrentTempDB_SourceSessions]
    (
          [session_id] smallint NOT NULL PRIMARY KEY
        , [is_user_process] bit NOT NULL
        , [status] nvarchar(30) NOT NULL
        , [login_name] nvarchar(128) NOT NULL
        , [host_name] nvarchar(128) NULL
        , [program_name] nvarchar(128) NULL
    );

    CREATE TABLE [#CurrentTempDB_SourceSessionUsage]
    (
          [session_id] smallint NOT NULL PRIMARY KEY
        , [user_objects_alloc_page_count] bigint NOT NULL
        , [user_objects_dealloc_page_count] bigint NOT NULL
        , [internal_objects_alloc_page_count] bigint NOT NULL
        , [internal_objects_dealloc_page_count] bigint NOT NULL
    );

    CREATE TABLE [#CurrentTempDB_SourceGroupCatalog]
    (
          [GroupId] int NOT NULL PRIMARY KEY
        , [GroupName] sysname NOT NULL
        , [PoolId] int NOT NULL
        , [ConfiguredGroupMaxTempdbDataMb] decimal(19,2) NULL
        , [ConfiguredGroupMaxTempdbDataPercent] decimal(9,4) NULL
    );

    CREATE TABLE [#CurrentTempDB_SourceGroupRuntime]
    (
          [GroupId] int NOT NULL PRIMARY KEY
        , [GroupName] sysname NOT NULL
        , [PoolId] int NOT NULL
        , [StatisticsStartTime] datetime NULL
        , [TempdbDataSpaceKb] bigint NULL
        , [PeakTempdbDataSpaceKb] bigint NULL
        , [TotalTempdbDataLimitViolationCount] bigint NULL
    );

    CREATE TABLE [#CurrentTempDB_SourcePools]
    (
          [PoolId] int NOT NULL PRIMARY KEY
        , [PoolName] sysname NOT NULL
    );

    CREATE TABLE [#CurrentTempDB_TempdbConfigFiles]
    (
          [FileId] int NOT NULL PRIMARY KEY
        , [SizePages] bigint NOT NULL
        , [MaxSizePages] bigint NOT NULL
        , [GrowthPagesOrPercent] bigint NOT NULL
    );

    IF @SessionIds IS NOT NULL
    BEGIN
        IF EXISTS
           (
               SELECT 1
               FROM [monitor].[TVF_ParseBigintList](@SessionIds)
               WHERE [IsValid]=0 OR [NumberValue] NOT BETWEEN 0 AND 32767
           )
           OR EXISTS
              (
                  SELECT [NumberValue]
                  FROM [monitor].[TVF_ParseBigintList](@SessionIds)
                  WHERE [IsValid]=1
                  GROUP BY [NumberValue]
                  HAVING COUNT(*)>1
              )
        BEGIN
            SET @StatusCode='INVALID_PARAMETER';
            SET @ErrorMessage=N'@SessionIds ist ungültig oder enthält Duplikate.';
        END
        ELSE
            INSERT [#CurrentTempDB_SessionFilter]([SessionId])
            SELECT CONVERT(smallint,[NumberValue])
            FROM [monitor].[TVF_ParseBigintList](@SessionIds)
            WHERE [IsValid]=1;
    END;

    IF @StatusCode='AVAILABLE'
       AND
       (
           @MinNettoMb<0
           OR @MaxZeilen<0
           OR @AktuelleSessionEinbeziehen IS NULL
           OR @SystemSessionsEinbeziehen IS NULL
           OR @MitDateien IS NULL
           OR @JsonErzeugen IS NULL
           OR @OutputMode NOT IN ('RAW','CONSOLE','TABLE','NONE')
           OR (@OutputMode<>'TABLE' AND NULLIF(LTRIM(RTRIM(COALESCE(@ResultTablesJson,N''))),N'') IS NOT NULL)
       )
    BEGIN
        SET @StatusCode='INVALID_PARAMETER';
        SET @ErrorMessage=N'Mindestens ein Parameter besitzt einen ungültigen Wert.';
    END;

    IF @StatusCode='AVAILABLE' AND @TableResultRequested=1
    BEGIN
        EXEC [monitor].[InternalPrepareResultTables]
              @ResultTablesJson=@ResultTablesJson
            , @AllowedResultNames=N'sessions|tempdbGovernance'
            , @MappingTable=N'#CurrentTempDB_ResultTableMap'
            , @StatusCode=@TablePreflightStatus OUTPUT
            , @ErrorMessage=@TablePreflightError OUTPUT
            , @ThrowOnError=0;

        SET @RestoreLockTimeoutSql=N'SET LOCK_TIMEOUT '+CONVERT(nvarchar(20),@OriginalLockTimeout)+N';';
        EXEC [sys].[sp_executesql] @RestoreLockTimeoutSql;

        IF @TablePreflightStatus<>'AVAILABLE'
        BEGIN
            SET @StatusCode=@TablePreflightStatus;
            SET @ErrorMessage=@TablePreflightError;
        END;
    END;

    IF @StatusCode<>'AVAILABLE'
    BEGIN
        SET @RestoreLockTimeoutSql=N'SET LOCK_TIMEOUT '+CONVERT(nvarchar(20),@OriginalLockTimeout)+N';';
        EXEC [sys].[sp_executesql] @RestoreLockTimeoutSql;
        THROW 51011,@ErrorMessage,1;
    END;

    SET LOCK_TIMEOUT 0;

    BEGIN TRY
        IF @ParentCurrentStateSnapshotId IS NOT NULL
        BEGIN
            EXEC [sys].[sp_executesql] N'
                DECLARE @Probe int;
                SELECT @Probe=0 FROM [#CurrentOverview_CurrentStateSnapshot_Context] WHERE 1=0;
                SELECT @Probe=0 FROM [#CurrentOverview_CurrentStateSnapshot_SourceStatus] WHERE 1=0;
                SELECT @Probe=0 FROM [#CurrentOverview_CurrentStateSnapshot_Sessions] WHERE 1=0;
                SELECT @Probe=0 FROM [#CurrentOverview_CurrentStateSnapshot_TempDbSessionUsage] WHERE 1=0;
                SELECT @Probe=0 FROM [#CurrentOverview_CurrentStateSnapshot_WorkloadGroups] WHERE 1=0;
                SELECT @Probe=0 FROM [#CurrentOverview_CurrentStateSnapshot_ResourcePools] WHERE 1=0;';

            IF NOT EXISTS
               (
                   SELECT 1
                   FROM [#CurrentOverview_CurrentStateSnapshot_Context]
                   WHERE [SnapshotId]=@ParentCurrentStateSnapshotId
                     AND [OwnerSessionId]=CONVERT(smallint,@@SPID)
                     AND [ContractVersion]=2
               )
                THROW 51020,N'Die Parent-Snapshot-ID gehört nicht zum aktuellen Aufruf.',1;

            INSERT [#CurrentTempDB_SourceSessions]
            SELECT [session_id],[is_user_process],[status],[login_name],[host_name],[program_name]
            FROM [#CurrentOverview_CurrentStateSnapshot_Sessions]
            WHERE [SnapshotId]=@ParentCurrentStateSnapshotId;

            INSERT [#CurrentTempDB_SourceSessionUsage]
            SELECT
                  [session_id],[user_objects_alloc_page_count],[user_objects_dealloc_page_count]
                , [internal_objects_alloc_page_count],[internal_objects_dealloc_page_count]
            FROM [#CurrentOverview_CurrentStateSnapshot_TempDbSessionUsage]
            WHERE [SnapshotId]=@ParentCurrentStateSnapshotId;

            INSERT [#CurrentTempDB_TempdbGovernance]
            (
                  [GroupId],[GroupName],[PoolId],[PoolName]
                , [ConfiguredGroupMaxTempdbDataMb],[ConfiguredGroupMaxTempdbDataPercent]
                , [TempdbMaximumSizeMb],[EffectiveGroupMaxTempdbDataMb]
                , [EffectiveLimitSource],[IsPercentLimitEffective]
                , [TempdbDataSpaceMb],[PeakTempdbDataSpaceMb],[EffectiveLimitUtilizationPercent]
                , [TotalTempdbDataLimitViolationCount],[HasRecordedLimitViolation]
                , [StatisticsStartTime],[IsResourceGovernorEnabled],[ReconfigurationPending]
                , [SourceStatusCode],[IsPartial],[EvidenceLimit]
            )
            SELECT
                  [g].[group_id],[g].[name],[g].[pool_id],[p].[name]
                , [g].[configured_group_max_tempdb_data_mb]
                , [g].[configured_group_max_tempdb_data_percent]
                , [g].[tempdb_maximum_size_mb]
                , [g].[effective_group_max_tempdb_data_mb]
                , [g].[effective_limit_source]
                , [g].[is_percent_limit_effective]
                , [g].[tempdb_data_space_mb]
                , [g].[peak_tempdb_data_space_mb]
                , [g].[effective_limit_utilization_percent]
                , [g].[total_tempdb_data_limit_violation_count]
                , [g].[has_recorded_limit_violation]
                , [g].[statistics_start_time]
                , [g].[is_resource_governor_enabled]
                , [g].[reconfiguration_pending]
                , [g].[tempdb_governance_status_code]
                , [g].[tempdb_governance_is_partial]
                , [g].[tempdb_governance_evidence_limit]
            FROM [#CurrentOverview_CurrentStateSnapshot_WorkloadGroups] AS [g]
            LEFT JOIN [#CurrentOverview_CurrentStateSnapshot_ResourcePools] AS [p]
              ON [p].[SnapshotId]=[g].[SnapshotId]
             AND [p].[pool_id]=[g].[pool_id]
            WHERE [g].[SnapshotId]=@ParentCurrentStateSnapshotId;

            IF NOT EXISTS (SELECT 1 FROM [#CurrentTempDB_TempdbGovernance])
            BEGIN
                DECLARE @ParentGovernanceStatus varchar(40)=
                (
                    SELECT TOP (1) [StatusCode]
                    FROM [#CurrentOverview_CurrentStateSnapshot_SourceStatus]
                    WHERE [SnapshotId]=@ParentCurrentStateSnapshotId
                      AND [SourceCode] IN ('TEMPDB_GOVERNANCE','WORKLOAD_GROUPS')
                    ORDER BY CASE WHEN [SourceCode]='TEMPDB_GOVERNANCE' THEN 0 ELSE 1 END
                );
                DECLARE @ParentGovernanceErrorNumber int=
                (
                    SELECT TOP (1) [ErrorNumber]
                    FROM [#CurrentOverview_CurrentStateSnapshot_SourceStatus]
                    WHERE [SnapshotId]=@ParentCurrentStateSnapshotId
                      AND [SourceCode] IN ('TEMPDB_GOVERNANCE','WORKLOAD_GROUPS')
                    ORDER BY CASE WHEN [SourceCode]='TEMPDB_GOVERNANCE' THEN 0 ELSE 1 END
                );
                DECLARE @ParentGovernanceErrorMessage nvarchar(2048)=
                (
                    SELECT TOP (1) [ErrorMessage]
                    FROM [#CurrentOverview_CurrentStateSnapshot_SourceStatus]
                    WHERE [SnapshotId]=@ParentCurrentStateSnapshotId
                      AND [SourceCode] IN ('TEMPDB_GOVERNANCE','WORKLOAD_GROUPS')
                    ORDER BY CASE WHEN [SourceCode]='TEMPDB_GOVERNANCE' THEN 0 ELSE 1 END
                );

                INSERT [#CurrentTempDB_TempdbGovernance]
                (
                      [GroupId],[GroupName],[PoolId],[PoolName]
                    , [ConfiguredGroupMaxTempdbDataMb],[ConfiguredGroupMaxTempdbDataPercent]
                    , [TempdbMaximumSizeMb],[EffectiveGroupMaxTempdbDataMb]
                    , [EffectiveLimitSource],[IsPercentLimitEffective]
                    , [TempdbDataSpaceMb],[PeakTempdbDataSpaceMb],[EffectiveLimitUtilizationPercent]
                    , [TotalTempdbDataLimitViolationCount],[HasRecordedLimitViolation]
                    , [StatisticsStartTime],[IsResourceGovernorEnabled],[ReconfigurationPending]
                    , [SourceStatusCode],[IsPartial],[EvidenceLimit]
                )
                VALUES
                (
                      NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'UNAVAILABLE',NULL
                    , NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL
                    , COALESCE(@ParentGovernanceStatus,
                        CASE WHEN @ProductMajorVersion<17 THEN 'UNAVAILABLE_VERSION'
                             ELSE 'AVAILABLE_EMPTY_OR_RESTRICTED' END)
                    , 1
                    , COALESCE
                      (
                          @ParentGovernanceErrorMessage,
                          CASE WHEN @ProductMajorVersion<17
                               THEN N'TempDB Resource Governance beginnt mit SQL Server 2025 (17.x).'
                               ELSE N'Keine sichtbare Workload Group war für die TempDB-Governance auswertbar.' END
                      )
                );

                IF @ParentGovernanceErrorNumber IS NOT NULL
                    INSERT [#CurrentTempDB_Warnings]
                    VALUES(COALESCE(@ParentGovernanceStatus,'AVAILABLE_LIMITED'),
                           @ParentGovernanceErrorNumber,@ParentGovernanceErrorMessage);
            END;

            SELECT
                  @EvidenceSnapshotStartedAtUtc=MIN([CapturedAtUtc])
                , @EvidenceIsPartial=CONVERT(bit,MAX(CONVERT(int,[IsPartial])))
            FROM [#CurrentOverview_CurrentStateSnapshot_SourceStatus]
            WHERE [SnapshotId]=@ParentCurrentStateSnapshotId
              AND [SourceCode] IN ('SESSIONS','TEMPDB_SESSION_USAGE');

            IF @ProductMajorVersion>=17
               AND EXISTS
                   (
                       SELECT 1
                       FROM [#CurrentTempDB_TempdbGovernance]
                       WHERE [SourceStatusCode] NOT IN ('AVAILABLE','AVAILABLE_EMPTY_OR_RESTRICTED')
                   )
            BEGIN
                SET @EvidenceIsPartial=1;
                IF @StatusCode='AVAILABLE' SET @StatusCode='AVAILABLE_LIMITED';
            END;
        END
        ELSE
        BEGIN
            SET @EvidenceSnapshotStartedAtUtc=SYSUTCDATETIME();

            INSERT [#CurrentTempDB_SourceSessions]
            SELECT [session_id],[is_user_process],[status],[login_name],[host_name],[program_name]
            FROM [sys].[dm_exec_sessions] WITH (NOLOCK);

            EXEC [sys].[sp_executesql] N'
                USE [tempdb];
                INSERT [#CurrentTempDB_SourceSessionUsage]
                SELECT
                      [session_id],[user_objects_alloc_page_count],[user_objects_dealloc_page_count]
                    , [internal_objects_alloc_page_count],[internal_objects_dealloc_page_count]
                FROM [sys].[dm_db_session_space_usage] WITH (NOLOCK);';

            IF @ProductMajorVersion IS NULL OR @ProductMajorVersion<17
            BEGIN
                INSERT [#CurrentTempDB_TempdbGovernance]
                (
                      [GroupId],[GroupName],[PoolId],[PoolName]
                    , [ConfiguredGroupMaxTempdbDataMb],[ConfiguredGroupMaxTempdbDataPercent]
                    , [TempdbMaximumSizeMb],[EffectiveGroupMaxTempdbDataMb]
                    , [EffectiveLimitSource],[IsPercentLimitEffective]
                    , [TempdbDataSpaceMb],[PeakTempdbDataSpaceMb],[EffectiveLimitUtilizationPercent]
                    , [TotalTempdbDataLimitViolationCount],[HasRecordedLimitViolation]
                    , [StatisticsStartTime],[IsResourceGovernorEnabled],[ReconfigurationPending]
                    , [SourceStatusCode],[IsPartial],[EvidenceLimit]
                )
                VALUES
                (
                      NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'UNAVAILABLE',NULL
                    , NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL
                    , 'UNAVAILABLE_VERSION',1
                    , N'TempDB Resource Governance beginnt mit SQL Server 2025 (17.x).'
                );
            END
            ELSE
            BEGIN
                DECLARE @CatalogColumnsValid bit=0,@RuntimeColumnsValid bit=0;
                DECLARE @GovernanceStatus varchar(40)='AVAILABLE';
                DECLARE @GovernanceErrorNumber int=NULL;
                DECLARE @GovernanceErrorMessage nvarchar(2048)=NULL;
                DECLARE @TempdbMaximumSizeMb decimal(19,2)=NULL;
                DECLARE @TempdbFileStatus varchar(40)='NOT_APPLICABLE';
                DECLARE @TempdbFileErrorNumber int=NULL;
                DECLARE @TempdbFileErrorMessage nvarchar(2048)=NULL;
                DECLARE @IsResourceGovernorEnabled bit=NULL;
                DECLARE @ReconfigurationPending bit=NULL;

                BEGIN TRY
                    SELECT
                          @CatalogColumnsValid=CONVERT
                          (
                              bit,
                              CASE WHEN SUM(CASE WHEN [o].[name]=N'resource_governor_workload_groups'
                                                  AND [c].[name] IN
                                                      (N'group_max_tempdb_data_mb',N'group_max_tempdb_data_percent')
                                                THEN 1 ELSE 0 END)=2
                                   THEN 1 ELSE 0 END
                          )
                        , @RuntimeColumnsValid=CONVERT
                          (
                              bit,
                              CASE WHEN SUM(CASE WHEN [o].[name]=N'dm_resource_governor_workload_groups'
                                                  AND [c].[name] IN
                                                      (N'tempdb_data_space_kb',N'peak_tempdb_data_space_kb',
                                                       N'total_tempdb_data_limit_violation_count')
                                                THEN 1 ELSE 0 END)=3
                                   THEN 1 ELSE 0 END
                          )
                    FROM [sys].[all_columns] AS [c] WITH (NOLOCK)
                    INNER JOIN [sys].[all_objects] AS [o] WITH (NOLOCK)
                      ON [o].[object_id]=[c].[object_id]
                    INNER JOIN [sys].[schemas] AS [s] WITH (NOLOCK)
                      ON [s].[schema_id]=[o].[schema_id]
                    WHERE [s].[name]=N'sys'
                      AND [o].[name] IN
                          (N'resource_governor_workload_groups',N'dm_resource_governor_workload_groups');

                    IF @CatalogColumnsValid=0 OR @RuntimeColumnsValid=0
                        SET @GovernanceStatus='UNAVAILABLE_SOURCE_SCHEMA';
                END TRY
                BEGIN CATCH
                    SELECT
                          @GovernanceErrorNumber=ERROR_NUMBER()
                        , @GovernanceErrorMessage=ERROR_MESSAGE()
                        , @GovernanceStatus=CASE WHEN ERROR_NUMBER()=1222 THEN 'TIMEOUT'
                             WHEN ERROR_NUMBER() IN (229,262,297,300,371,916) THEN 'DENIED_PERMISSION'
                             ELSE 'ERROR_HANDLED' END;
                END CATCH;

                BEGIN TRY
                    SELECT
                          @IsResourceGovernorEnabled=[stored].[is_enabled]
                        , @ReconfigurationPending=[effective].[is_reconfiguration_pending]
                    FROM [sys].[resource_governor_configuration] AS [stored] WITH (NOLOCK)
                    CROSS JOIN [sys].[dm_resource_governor_configuration] AS [effective] WITH (NOLOCK);
                END TRY
                BEGIN CATCH
                    SELECT
                          @GovernanceErrorNumber=ERROR_NUMBER()
                        , @GovernanceErrorMessage=ERROR_MESSAGE()
                        , @GovernanceStatus=CASE WHEN ERROR_NUMBER()=1222 THEN 'TIMEOUT'
                             WHEN ERROR_NUMBER() IN (229,262,297,300,371,916) THEN 'DENIED_PERMISSION'
                             ELSE 'ERROR_HANDLED' END;
                END CATCH;

                IF @CatalogColumnsValid=1
                BEGIN TRY
                    EXEC [sys].[sp_executesql] N'
                        INSERT [#CurrentTempDB_SourceGroupCatalog]
                        (
                              [GroupId],[GroupName],[PoolId]
                            , [ConfiguredGroupMaxTempdbDataMb]
                            , [ConfiguredGroupMaxTempdbDataPercent]
                        )
                        SELECT
                              [g].[group_id],[g].[name],[g].[pool_id]
                            , CONVERT(decimal(19,2),[g].[group_max_tempdb_data_mb])
                            , CONVERT(decimal(9,4),[g].[group_max_tempdb_data_percent])
                        FROM [sys].[resource_governor_workload_groups] AS [g] WITH (NOLOCK);';
                END TRY
                BEGIN CATCH
                    SELECT
                          @GovernanceErrorNumber=ERROR_NUMBER()
                        , @GovernanceErrorMessage=ERROR_MESSAGE()
                        , @GovernanceStatus=CASE WHEN ERROR_NUMBER()=1222 THEN 'TIMEOUT'
                             WHEN ERROR_NUMBER() IN (229,262,297,300,371,916) THEN 'DENIED_PERMISSION'
                             ELSE 'ERROR_HANDLED' END;
                END CATCH;

                IF @RuntimeColumnsValid=1
                BEGIN TRY
                    EXEC [sys].[sp_executesql] N'
                        INSERT [#CurrentTempDB_SourceGroupRuntime]
                        (
                              [GroupId],[GroupName],[PoolId],[StatisticsStartTime]
                            , [TempdbDataSpaceKb],[PeakTempdbDataSpaceKb]
                            , [TotalTempdbDataLimitViolationCount]
                        )
                        SELECT
                              [g].[group_id],[g].[name],[g].[pool_id],[g].[statistics_start_time]
                            , CONVERT(bigint,[g].[tempdb_data_space_kb])
                            , CONVERT(bigint,[g].[peak_tempdb_data_space_kb])
                            , CONVERT(bigint,[g].[total_tempdb_data_limit_violation_count])
                        FROM [sys].[dm_resource_governor_workload_groups] AS [g] WITH (NOLOCK);';

                    INSERT [#CurrentTempDB_SourcePools]
                    SELECT [p].[pool_id],[p].[name]
                    FROM [sys].[dm_resource_governor_resource_pools] AS [p] WITH (NOLOCK);
                END TRY
                BEGIN CATCH
                    SELECT
                          @GovernanceErrorNumber=ERROR_NUMBER()
                        , @GovernanceErrorMessage=ERROR_MESSAGE()
                        , @GovernanceStatus=CASE WHEN ERROR_NUMBER()=1222 THEN 'TIMEOUT'
                             WHEN ERROR_NUMBER() IN (229,262,297,300,371,916) THEN 'DENIED_PERMISSION'
                             ELSE 'ERROR_HANDLED' END;
                END CATCH;

                IF @GovernanceStatus='AVAILABLE'
                   AND EXISTS
                       (
                           SELECT 1
                           FROM [#CurrentTempDB_SourceGroupCatalog]
                           WHERE [ConfiguredGroupMaxTempdbDataMb] IS NULL
                             AND [ConfiguredGroupMaxTempdbDataPercent] IS NOT NULL
                       )
                BEGIN
                    SET @TempdbFileStatus='AVAILABLE';
                    BEGIN TRY
                        INSERT [#CurrentTempDB_TempdbConfigFiles]
                        SELECT
                              [f].[file_id],CONVERT(bigint,[f].[size])
                            , CONVERT(bigint,[f].[max_size]),CONVERT(bigint,[f].[growth])
                        FROM [master].[sys].[master_files] AS [f] WITH (NOLOCK)
                        WHERE [f].[database_id]=2 AND [f].[type]=0;

                        SELECT @TempdbMaximumSizeMb=
                            CASE
                                WHEN COUNT_BIG(*)>0
                                 AND
                                 (
                                     SUM(CASE WHEN [MaxSizePages]<>-1 AND [GrowthPagesOrPercent]>0 THEN 1 ELSE 0 END)=COUNT_BIG(*)
                                     OR
                                     SUM(CASE WHEN [MaxSizePages]=-1 AND [GrowthPagesOrPercent]=0 THEN 1 ELSE 0 END)=COUNT_BIG(*)
                                 )
                                THEN CONVERT
                                     (
                                         decimal(19,2),
                                         SUM(CASE WHEN [GrowthPagesOrPercent]=0 THEN [SizePages] ELSE [MaxSizePages] END)
                                         *8.0/1024.0
                                     )
                            END
                        FROM [#CurrentTempDB_TempdbConfigFiles];
                    END TRY
                    BEGIN CATCH
                        SELECT
                              @TempdbFileErrorNumber=ERROR_NUMBER()
                            , @TempdbFileErrorMessage=ERROR_MESSAGE()
                            , @TempdbFileStatus=CASE WHEN ERROR_NUMBER()=1222 THEN 'TIMEOUT'
                                 WHEN ERROR_NUMBER() IN (229,262,297,300,371,916) THEN 'DENIED_PERMISSION'
                                 ELSE 'ERROR_HANDLED' END;
                        INSERT [#CurrentTempDB_Warnings]
                        VALUES(@TempdbFileStatus,@TempdbFileErrorNumber,@TempdbFileErrorMessage);
                    END CATCH;
                END;

                INSERT [#CurrentTempDB_TempdbGovernance]
                SELECT TOP (@Limit)
                      COALESCE([g].[GroupId],[d].[GroupId])
                    , COALESCE([g].[GroupName],[d].[GroupName])
                    , COALESCE([g].[PoolId],[d].[PoolId])
                    , [p].[PoolName]
                    , [g].[ConfiguredGroupMaxTempdbDataMb]
                    , [g].[ConfiguredGroupMaxTempdbDataPercent]
                    , @TempdbMaximumSizeMb
                    , CONVERT
                      (
                          decimal(19,2),
                          CASE
                              WHEN @GovernanceStatus<>'AVAILABLE' THEN NULL
                              WHEN [g].[ConfiguredGroupMaxTempdbDataMb] IS NULL
                               AND [g].[ConfiguredGroupMaxTempdbDataPercent] IS NULL THEN NULL
                              WHEN @ReconfigurationPending=1 OR COALESCE(@IsResourceGovernorEnabled,0)=0 THEN NULL
                              WHEN [g].[ConfiguredGroupMaxTempdbDataMb] IS NOT NULL
                                  THEN [g].[ConfiguredGroupMaxTempdbDataMb]
                              WHEN @TempdbFileStatus<>'AVAILABLE' THEN NULL
                              WHEN @TempdbMaximumSizeMb IS NOT NULL
                                  THEN [g].[ConfiguredGroupMaxTempdbDataPercent]*@TempdbMaximumSizeMb/100.0
                          END
                      )
                    , CASE
                          WHEN @GovernanceStatus<>'AVAILABLE' THEN 'UNAVAILABLE'
                          WHEN [g].[ConfiguredGroupMaxTempdbDataMb] IS NULL
                           AND [g].[ConfiguredGroupMaxTempdbDataPercent] IS NULL THEN 'NO_LIMIT_CONFIGURED'
                          WHEN @ReconfigurationPending=1 THEN 'RECONFIGURATION_PENDING'
                          WHEN COALESCE(@IsResourceGovernorEnabled,0)=0 THEN 'RESOURCE_GOVERNOR_DISABLED'
                          WHEN [g].[ConfiguredGroupMaxTempdbDataMb] IS NOT NULL THEN 'FIXED_MB_EFFECTIVE'
                          WHEN @TempdbFileStatus<>'AVAILABLE' THEN 'UNAVAILABLE'
                          WHEN @TempdbMaximumSizeMb IS NOT NULL THEN 'PERCENT_EFFECTIVE'
                          ELSE 'PERCENT_NOT_EFFECTIVE'
                      END
                    , CASE
                          WHEN [g].[ConfiguredGroupMaxTempdbDataPercent] IS NULL THEN NULL
                          WHEN [g].[ConfiguredGroupMaxTempdbDataMb] IS NOT NULL THEN CONVERT(bit,0)
                          WHEN @ReconfigurationPending=1 OR COALESCE(@IsResourceGovernorEnabled,0)=0 THEN CONVERT(bit,0)
                          WHEN @TempdbFileStatus<>'AVAILABLE' THEN NULL
                          WHEN @TempdbMaximumSizeMb IS NOT NULL THEN CONVERT(bit,1)
                          ELSE CONVERT(bit,0)
                      END
                    , CONVERT(decimal(19,2),[d].[TempdbDataSpaceKb]/1024.0)
                    , CONVERT(decimal(19,2),[d].[PeakTempdbDataSpaceKb]/1024.0)
                    , CONVERT
                      (
                          decimal(9,2),
                          100.0*CONVERT(decimal(38,4),[d].[TempdbDataSpaceKb]/1024.0)
                          /NULLIF
                           (
                               CASE
                                   WHEN @ReconfigurationPending=0 AND COALESCE(@IsResourceGovernorEnabled,0)=1
                                    AND [g].[ConfiguredGroupMaxTempdbDataMb] IS NOT NULL
                                       THEN [g].[ConfiguredGroupMaxTempdbDataMb]
                                   WHEN @ReconfigurationPending=0 AND COALESCE(@IsResourceGovernorEnabled,0)=1
                                    AND [g].[ConfiguredGroupMaxTempdbDataMb] IS NULL
                                    AND @TempdbMaximumSizeMb IS NOT NULL
                                       THEN [g].[ConfiguredGroupMaxTempdbDataPercent]*@TempdbMaximumSizeMb/100.0
                               END
                           ,0)
                      )
                    , [d].[TotalTempdbDataLimitViolationCount]
                    , CASE WHEN [d].[TotalTempdbDataLimitViolationCount] IS NULL THEN NULL
                           WHEN [d].[TotalTempdbDataLimitViolationCount]>0 THEN CONVERT(bit,1)
                           ELSE CONVERT(bit,0) END
                    , [d].[StatisticsStartTime]
                    , @IsResourceGovernorEnabled
                    , @ReconfigurationPending
                    , CASE
                          WHEN @GovernanceStatus='AVAILABLE'
                           AND [g].[ConfiguredGroupMaxTempdbDataMb] IS NULL
                           AND [g].[ConfiguredGroupMaxTempdbDataPercent] IS NOT NULL
                           AND @TempdbFileStatus<>'AVAILABLE'
                              THEN @TempdbFileStatus
                          WHEN @GovernanceStatus='AVAILABLE'
                           AND @ReconfigurationPending=1
                           AND
                             (
                                 [g].[ConfiguredGroupMaxTempdbDataMb] IS NOT NULL
                                 OR [g].[ConfiguredGroupMaxTempdbDataPercent] IS NOT NULL
                             )
                              THEN 'AVAILABLE_LIMITED'
                          ELSE @GovernanceStatus
                      END
                    , CONVERT
                      (
                          bit,
                          CASE
                              WHEN @GovernanceStatus<>'AVAILABLE' THEN 1
                              WHEN [g].[ConfiguredGroupMaxTempdbDataMb] IS NULL
                               AND [g].[ConfiguredGroupMaxTempdbDataPercent] IS NOT NULL
                               AND @TempdbFileStatus<>'AVAILABLE' THEN 1
                              WHEN @ReconfigurationPending=1
                               AND
                                 (
                                     [g].[ConfiguredGroupMaxTempdbDataMb] IS NOT NULL
                                     OR [g].[ConfiguredGroupMaxTempdbDataPercent] IS NOT NULL
                                 )
                                  THEN 1
                              ELSE 0
                          END
                      )
                    , CASE
                          WHEN @GovernanceStatus<>'AVAILABLE'
                              THEN COALESCE(@GovernanceErrorMessage,N'Die SQL-Server-2025-Quelle ist nicht vollständig verfügbar.')
                          WHEN [g].[ConfiguredGroupMaxTempdbDataMb] IS NULL
                           AND [g].[ConfiguredGroupMaxTempdbDataPercent] IS NOT NULL
                           AND @TempdbFileStatus<>'AVAILABLE'
                              THEN COALESCE(@TempdbFileErrorMessage,N'Die TempDB-Dateikonfiguration ist im aktuellen Sicherheitskontext nicht auswertbar.')
                          WHEN @ReconfigurationPending=1
                              THEN N'Die gespeicherte Konfiguration kann von der aktiven Konfiguration abweichen, bis RECONFIGURE abgeschlossen ist.'
                          WHEN [g].[ConfiguredGroupMaxTempdbDataMb] IS NULL
                           AND [g].[ConfiguredGroupMaxTempdbDataPercent] IS NOT NULL
                           AND @TempdbMaximumSizeMb IS NULL
                              THEN N'Das gespeicherte Prozentlimit ist wegen der TempDB-Dateikonfiguration nicht wirksam.'
                          ELSE N'Workload-Group-Zähler sind nicht direkt mit Sessionzählern addierbar; Version Store und TempDB-Log sind nicht umfasst.'
                      END
                FROM [#CurrentTempDB_SourceGroupCatalog] AS [g]
                FULL OUTER JOIN [#CurrentTempDB_SourceGroupRuntime] AS [d]
                  ON [d].[GroupId]=[g].[GroupId]
                LEFT JOIN [#CurrentTempDB_SourcePools] AS [p]
                  ON [p].[PoolId]=COALESCE([g].[PoolId],[d].[PoolId])
                ORDER BY COALESCE([g].[GroupId],[d].[GroupId]);

                IF NOT EXISTS (SELECT 1 FROM [#CurrentTempDB_TempdbGovernance])
                    INSERT [#CurrentTempDB_TempdbGovernance]
                    (
                          [GroupId],[GroupName],[PoolId],[PoolName]
                        , [ConfiguredGroupMaxTempdbDataMb],[ConfiguredGroupMaxTempdbDataPercent]
                        , [TempdbMaximumSizeMb],[EffectiveGroupMaxTempdbDataMb]
                        , [EffectiveLimitSource],[IsPercentLimitEffective]
                        , [TempdbDataSpaceMb],[PeakTempdbDataSpaceMb],[EffectiveLimitUtilizationPercent]
                        , [TotalTempdbDataLimitViolationCount],[HasRecordedLimitViolation]
                        , [StatisticsStartTime],[IsResourceGovernorEnabled],[ReconfigurationPending]
                        , [SourceStatusCode],[IsPartial],[EvidenceLimit]
                    )
                    VALUES
                    (
                          NULL,NULL,NULL,NULL,NULL,NULL,@TempdbMaximumSizeMb,NULL
                        , 'UNAVAILABLE',NULL,NULL,NULL,NULL,NULL,NULL,NULL
                        , @IsResourceGovernorEnabled,@ReconfigurationPending
                        , CASE WHEN @GovernanceStatus='AVAILABLE'
                               THEN 'AVAILABLE_EMPTY_OR_RESTRICTED' ELSE @GovernanceStatus END
                        , 1
                        , COALESCE(@GovernanceErrorMessage,N'Keine sichtbare Workload Group war für die TempDB-Governance auswertbar.')
                    );

                IF EXISTS
                   (
                       SELECT 1
                       FROM [#CurrentTempDB_TempdbGovernance]
                       WHERE [SourceStatusCode] NOT IN ('AVAILABLE','AVAILABLE_EMPTY_OR_RESTRICTED')
                   )
                BEGIN
                    SET @EvidenceIsPartial=1;
                    IF @StatusCode='AVAILABLE' SET @StatusCode='AVAILABLE_LIMITED';
                END;
            END;
        END;

        INSERT [#CurrentTempDB_Sessions]
        (
              [SessionId],[LoginName],[HostName],[ProgramName],[SessionStatus]
            , [UserObjectsAllocatedMb],[UserObjectsDeallocatedMb],[UserObjectsNetMb]
            , [InternalObjectsAllocatedMb],[InternalObjectsDeallocatedMb],[InternalObjectsNetMb]
            , [TotalNetMb]
        )
        SELECT TOP (@Candidates)
              [su].[session_id],[s].[login_name],[s].[host_name],[s].[program_name],[s].[status]
            , CONVERT(decimal(19,2),[su].[user_objects_alloc_page_count]*8.0/1024.0)
            , CONVERT(decimal(19,2),[su].[user_objects_dealloc_page_count]*8.0/1024.0)
            , CONVERT(decimal(19,2),([su].[user_objects_alloc_page_count]-[su].[user_objects_dealloc_page_count])*8.0/1024.0)
            , CONVERT(decimal(19,2),[su].[internal_objects_alloc_page_count]*8.0/1024.0)
            , CONVERT(decimal(19,2),[su].[internal_objects_dealloc_page_count]*8.0/1024.0)
            , CONVERT(decimal(19,2),([su].[internal_objects_alloc_page_count]-[su].[internal_objects_dealloc_page_count])*8.0/1024.0)
            , CONVERT
              (
                  decimal(19,2),
                  (
                      [su].[user_objects_alloc_page_count]-[su].[user_objects_dealloc_page_count]
                      +[su].[internal_objects_alloc_page_count]-[su].[internal_objects_dealloc_page_count]
                  )*8.0/1024.0
              )
        FROM [#CurrentTempDB_SourceSessionUsage] AS [su]
        LEFT JOIN [#CurrentTempDB_SourceSessions] AS [s]
          ON [s].[session_id]=[su].[session_id]
        WHERE (@AktuelleSessionEinbeziehen=1 OR [su].[session_id]<>@@SPID)
          AND (@SystemSessionsEinbeziehen=1 OR COALESCE([s].[is_user_process],1)=1)
          AND
          (
              @SessionIds IS NULL
              OR EXISTS
                 (
                     SELECT 1
                     FROM [#CurrentTempDB_SessionFilter] AS [f]
                     WHERE [f].[SessionId]=[su].[session_id]
                 )
          )
          AND
          (
              [su].[user_objects_alloc_page_count]-[su].[user_objects_dealloc_page_count]
              +[su].[internal_objects_alloc_page_count]-[su].[internal_objects_dealloc_page_count]
          )*8.0/1024.0>=@MinNettoMb
        ORDER BY
          (
              [su].[user_objects_alloc_page_count]-[su].[user_objects_dealloc_page_count]
              +[su].[internal_objects_alloc_page_count]-[su].[internal_objects_dealloc_page_count]
          ) DESC,
          [su].[session_id];

        IF @MitDateien=1
        BEGIN
            SET @Sql=N'USE [tempdb];
INSERT [#CurrentTempDB_Files]
(
      [FileId],[LogicalName],[PhysicalName],[FileTypeDesc]
    , [SizeMb],[UsedMb],[FreeMb],[UsedPercent],[GrowthMb],[IsPercentGrowth]
)
SELECT
      [df].[file_id],[df].[name],[df].[physical_name],[df].[type_desc]
    , CONVERT(decimal(19,2),[df].[size]*8.0/1024.0)
    , CONVERT(decimal(19,2),FILEPROPERTY([df].[name],N''SpaceUsed'')*8.0/1024.0)
    , CONVERT(decimal(19,2),([df].[size]-FILEPROPERTY([df].[name],N''SpaceUsed''))*8.0/1024.0)
    , CONVERT(decimal(9,2),100.0*FILEPROPERTY([df].[name],N''SpaceUsed'')/NULLIF([df].[size],0))
    , CONVERT(decimal(19,2),CASE WHEN [df].[is_percent_growth]=0 THEN [df].[growth]*8.0/1024.0 END)
    , [df].[is_percent_growth]
FROM [sys].[database_files] AS [df] WITH (NOLOCK)
ORDER BY [df].[file_id];';
            EXEC [sys].[sp_executesql] @Sql;
        END;

        SELECT @RowCount=COUNT_BIG(*) FROM [#CurrentTempDB_Sessions];
        SET @HasMoreRows=CONVERT(bit,CASE WHEN @Limit<9223372036854775807 AND @RowCount>@Limit THEN 1 ELSE 0 END);
        IF @EvidenceIsPartial=1 AND @StatusCode='AVAILABLE' SET @StatusCode='AVAILABLE_LIMITED';
    END TRY
    BEGIN CATCH
        SET @ErrorNumber=ERROR_NUMBER();
        SET @ErrorMessage=ERROR_MESSAGE();
        SET @StatusCode=CASE WHEN @ErrorNumber IN (229,262,297,300,371,916) THEN 'DENIED_PERMISSION'
                             WHEN @ErrorNumber=1222 THEN 'TIMEOUT'
                             WHEN @ParentCurrentStateSnapshotId IS NOT NULL
                              AND @ErrorNumber IN (208,51020) THEN 'INVALID_PARENT_SNAPSHOT'
                             ELSE 'ERROR_HANDLED' END;
        SET @EvidenceIsPartial=1;
        INSERT [#CurrentTempDB_Warnings] VALUES(@StatusCode,@ErrorNumber,@ErrorMessage);
    END CATCH;

    IF @PrintMeldungen=1 AND @StatusCode<>'AVAILABLE'
    BEGIN
        DECLARE @Message nvarchar(2048)=FORMATMESSAGE
        (
            N'WARNUNG USP_CurrentTempDB [%s]: %s',
            @StatusCode,
            COALESCE(@ErrorMessage,N'Teilergebnis oder eingeschränkte Sicht.')
        );
        RAISERROR(N'%s',10,1,@Message) WITH NOWAIT;
    END;

    IF @JsonErzeugen=1
    BEGIN
        DECLARE @Meta nvarchar(max)=
        (
            SELECT
                  N'CurrentTempDB' AS [resultName]
                , 3 AS [schemaVersion]
                , @Now AS [generatedAtUtc]
                , @EvidenceSnapshotStartedAtUtc AS [evidenceSnapshotStartedAtUtc]
                , @EvidenceSnapshotId AS [evidenceSnapshotId]
                , @StatusCode AS [statusCode]
                , CONVERT(bit,CASE WHEN @StatusCode='AVAILABLE' THEN 0 ELSE 1 END) AS [isPartial]
                , @ProductMajorVersion AS [productMajorVersion]
                , @MaxZeilen AS [requestedMaxRows]
                , CASE WHEN @RowCount>@Limit THEN @Limit ELSE @RowCount END AS [returnedRows]
                , @HasMoreRows AS [hasMoreRows]
            FOR JSON PATH,WITHOUT_ARRAY_WRAPPER,INCLUDE_NULL_VALUES
        );
        DECLARE @SessionsJson nvarchar(max)=
        (
            SELECT TOP (@Limit) *
            FROM [#CurrentTempDB_Sessions]
            ORDER BY [TotalNetMb] DESC,[SessionId]
            FOR JSON PATH,INCLUDE_NULL_VALUES
        );
        DECLARE @FilesJson nvarchar(max)=
        (
            SELECT *
            FROM [#CurrentTempDB_Files]
            ORDER BY [FileId]
            FOR JSON PATH,INCLUDE_NULL_VALUES
        );
        DECLARE @GovernanceJson nvarchar(max)=
        (
            SELECT *
            FROM [#CurrentTempDB_TempdbGovernance]
            ORDER BY [GroupId]
            FOR JSON PATH,INCLUDE_NULL_VALUES
        );
        DECLARE @WarningsJson nvarchar(max)=
        (
            SELECT *
            FROM [#CurrentTempDB_Warnings]
            ORDER BY [StatusCode],[ErrorNumber]
            FOR JSON PATH,INCLUDE_NULL_VALUES
        );
        SET @Json=CONCAT
        (
              N'{"meta":',COALESCE(@Meta,N'{}')
            , N',"sessions":',COALESCE(@SessionsJson,N'[]')
            , N',"tempdbFiles":',COALESCE(@FilesJson,N'[]')
            , N',"tempdbGovernance":',COALESCE(@GovernanceJson,N'[]')
            , N',"warnings":',COALESCE(@WarningsJson,N'[]')
            , N'}'
        );
    END;

    IF @OutputMode='RAW'
    BEGIN
        SELECT
              N'USP_CurrentTempDB' AS [ModuleName]
            , @Now AS [CollectionTimeUtc]
            , @EvidenceSnapshotStartedAtUtc AS [EvidenceSnapshotStartedAtUtc]
            , @EvidenceSnapshotId AS [EvidenceSnapshotId]
            , @StatusCode AS [StatusCode]
            , CONVERT(bit,CASE WHEN @StatusCode='AVAILABLE' THEN 0 ELSE 1 END) AS [IsPartial]
            , CASE WHEN @RowCount>@Limit THEN @Limit ELSE @RowCount END AS [ReturnedRowCount]
            , @HasMoreRows AS [HasMoreRows]
            , @ErrorNumber AS [ErrorNumber]
            , @ErrorMessage AS [ErrorMessage];

        SELECT TOP (@Limit) *
        FROM [#CurrentTempDB_Sessions]
        ORDER BY [TotalNetMb] DESC,[SessionId];

        IF @MitDateien=1
            SELECT * FROM [#CurrentTempDB_Files] ORDER BY [FileId];

        SELECT * FROM [#CurrentTempDB_TempdbGovernance] ORDER BY [GroupId];
        SELECT * FROM [#CurrentTempDB_Warnings] ORDER BY [StatusCode],[ErrorNumber];
    END;

    BEGIN TRY
        IF @ConsoleResultRequested=1
        BEGIN
            EXEC [monitor].[InternalEmitConsoleResult]
                  @SourceTable=N'#CurrentTempDB_Sessions'
                , @ResultLabel=N'Aktuelle TempDB-Nutzung'
                , @EmptyMessage=N'Keine aktive TempDB-Nutzung';
            IF @MitDateien=1
                EXEC [monitor].[InternalEmitConsoleResult]
                      @SourceTable=N'#CurrentTempDB_Files'
                    , @ResultLabel=N'TempDB-Dateien'
                    , @EmptyMessage=N'Keine sichtbaren TempDB-Dateien';
            EXEC [monitor].[InternalEmitConsoleResult]
                  @SourceTable=N'#CurrentTempDB_TempdbGovernance'
                , @ResultLabel=N'TempDB Resource Governance'
                , @EmptyMessage=N'Keine TempDB-Governance-Evidenz';
        END;

        IF @TableResultRequested=1
        BEGIN
            DECLARE @TableTarget sysname;
            SELECT @TableTarget=[TargetTable] FROM [#CurrentTempDB_ResultTableMap] WHERE [ResultName]=N'sessions';
            IF @TableTarget IS NOT NULL
                EXEC [monitor].[InternalWriteResultTable]
                      @SourceTable=N'#CurrentTempDB_Sessions'
                    , @TargetTable=@TableTarget
                    , @ThrowOnError=1;

            SET @TableTarget=NULL;
            SELECT @TableTarget=[TargetTable] FROM [#CurrentTempDB_ResultTableMap] WHERE [ResultName]=N'tempdbGovernance';
            IF @TableTarget IS NOT NULL
                EXEC [monitor].[InternalWriteResultTable]
                      @SourceTable=N'#CurrentTempDB_TempdbGovernance'
                    , @TargetTable=@TableTarget
                    , @ThrowOnError=1;
        END;
    END TRY
    BEGIN CATCH
        SET @RestoreLockTimeoutSql=N'SET LOCK_TIMEOUT '+CONVERT(nvarchar(20),@OriginalLockTimeout)+N';';
        EXEC [sys].[sp_executesql] @RestoreLockTimeoutSql;
        THROW;
    END CATCH;

    SET @RestoreLockTimeoutSql=N'SET LOCK_TIMEOUT '+CONVERT(nvarchar(20),@OriginalLockTimeout)+N';';
    EXEC [sys].[sp_executesql] @RestoreLockTimeoutSql;
END;
GO
-- END SOURCE: Code/02_CurrentState/070_USP_CurrentTempDB.sql

-- BEGIN SOURCE: Code/02_CurrentState/080_USP_CurrentIO.sql
/*
===============================================================================
Objekt       : monitor.USP_CurrentIO
Version      : 4.0.0
Stand        : 2026-07-23
Zweck        : Führt eine leichtgewichtige serverweite Datei-I/O-Analyse mit
               optionalem Delta-Sampling und expliziter
               Datenbankeinschränkung durch.
Datenbanken  : Standardmäßig alle sichtbaren, online befindlichen
               Benutzerdatenbanken; kein CURRENT-Scope und keine Vorabgrenze.
DMV-Zugriff  : sys.dm_io_virtual_file_stats(NULL,NULL) genau einmal je
               Messzeitpunkt; keine Wiederholung pro Datenbank.
Pending I/O  : Optional zwei Beobachtungen derselben aktuell ausstehenden
               Requestadresse. Scheduler-/Taskbezug ist Kontext, keine kausale
               1:1-Zuordnung. io_pending_ms_ticks ist informational/internal.
Ausgabe      : CONSOLE ein gemeinsames Evidenz-Grid; RAW und TABLE verwenden
               moduleStatus, sourceStatus, files, pendingIo und warnings.
===============================================================================
*/
CREATE OR ALTER PROCEDURE [monitor].[USP_CurrentIO]
      @DatabaseNames                  nvarchar(max)  = NULL
    , @SystemdatenbankenEinbeziehen   bit            = 0
    , @DatabaseNamePattern            nvarchar(4000) = NULL
    , @HighImpactConfirmed              bit            = 0
    , @MinLatencyMs                   decimal(19,3)  = 0
    , @SampleSeconds                  tinyint         = 0
    , @PendingIoEinbeziehen           bit             = 1
    , @NurWiederholtPending           bit             = 0
    , @MinPendingIoMs                 bigint          = 0
    , @PhysischePfadeEinbeziehen      bit             = 0
    , @MaxZeilen                      int             = 1000
    , @ResultSetArt                   varchar(16)     = 'CONSOLE'
    , @ResultTablesJson               nvarchar(max)   = NULL
    , @JsonErzeugen                   bit             = 0
    , @Json                           nvarchar(max)   = NULL OUTPUT
    , @PrintMeldungen                 bit             = 1
    , @Hilfe                          bit             = 0
    , @ParentCurrentStateSnapshotId   uniqueidentifier = NULL
AS
BEGIN
    SET NOCOUNT ON;
    SET @Json = NULL;

    DECLARE @OutputMode varchar(16) = UPPER(LTRIM(RTRIM(COALESCE(@ResultSetArt,N''))));
    DECLARE @Limit bigint =
        CASE WHEN @MaxZeilen IS NULL OR @MaxZeilen = 0
             THEN CONVERT(bigint,9223372036854775807)
             WHEN @MaxZeilen > 0 THEN CONVERT(bigint,@MaxZeilen)
             ELSE CONVERT(bigint,0) END;
    DECLARE @CandidateLimit bigint =
        CASE WHEN @MaxZeilen IS NULL OR @MaxZeilen = 0
             THEN CONVERT(bigint,9223372036854775807)
             WHEN @MaxZeilen BETWEEN 1 AND 2147483646
             THEN CONVERT(bigint,@MaxZeilen) + 1
             WHEN @MaxZeilen > 0 THEN CONVERT(bigint,@MaxZeilen)
             ELSE CONVERT(bigint,0) END;

    IF @Hilfe = 1
    BEGIN
        PRINT N'monitor.USP_CurrentIO';
        PRINT N'Ohne Datenbankfilter werden alle sichtbaren, online befindlichen Benutzerdatenbanken verarbeitet.';
        PRINT N'@DatabaseNames enthält eine exakte Liste; @DatabaseNamePattern ist eine alternative explizite Einschränkung.';
        PRINT N'@SystemdatenbankenEinbeziehen=1 aktiviert Systemdatenbanken.';
        PRINT N'@SampleSeconds=0 liefert kumulative Dateizähler und einen Pending-I/O-Snapshot; 1..60 liefert Datei-Deltas und zwei Pending-I/O-Beobachtungen.';
        PRINT N'@PendingIoEinbeziehen=1 ergänzt aktuell ausstehende Datenbankdatei-I/Os; @NurWiederholtPending=1 benötigt ein Sample.';
        PRINT N'@MinPendingIoMs filtert den informational/internal Pending-Zähler. Ein Einzelwert beweist keinen Storagefehler.';
        PRINT N'@PhysischePfadeEinbeziehen=1 gibt Pfade nur im expliziten Detailresultset pendingIo frei.';
        PRINT N'@ResultSetArt=CONSOLE|RAW|TABLE|NONE; TABLE verwendet moduleStatus, sourceStatus, files, pendingIo und warnings.';
        PRINT N'USP_CurrentIO ist leichtgewichtig und benötigt keine High-Impact-Bestätigung.';
        RETURN;
    END;

    DECLARE @CollectionTimeUtc datetime2(3) = SYSUTCDATETIME();
    DECLARE @StatusCode varchar(40) = 'AVAILABLE';
    DECLARE @IsPartial bit = 0;
    DECLARE @ErrorNumber int = NULL;
    DECLARE @ErrorMessage nvarchar(2048) = NULL;
    DECLARE @CrossDatabaseRequested bit = 0;
    DECLARE @RowCount bigint = 0;
    DECLARE @WarningCount bigint = 0;
    DECLARE @PendingRowCount bigint = 0;
    DECLARE @PendingHasMoreRows bit = 0;
    DECLARE @FileSourceStatus varchar(40) = 'NOT_EXECUTED';
    DECLARE @FileSourceErrorNumber int = NULL;
    DECLARE @FileSourceErrorMessage nvarchar(2048) = NULL;
    DECLARE @PendingSourceStatus varchar(40) = 'NOT_REQUESTED';
    DECLARE @PendingSourceErrorNumber int = NULL;
    DECLARE @PendingSourceErrorMessage nvarchar(2048) = NULL;
    DECLARE @PendingContextStatus varchar(40) = 'NOT_REQUESTED';
    DECLARE @PendingContextErrorNumber int = NULL;
    DECLARE @PendingContextErrorMessage nvarchar(2048) = NULL;
    DECLARE @HasMoreRows bit = 0;
    DECLARE @Message nvarchar(2048);
    DECLARE @Delay char(8);
    DECLARE @EvidenceSnapshotId uniqueidentifier=COALESCE(@ParentCurrentStateSnapshotId,NEWID());
    DECLARE @EvidenceSnapshotStartedAtUtc datetime2(3)=@CollectionTimeUtc;

    CREATE TABLE [#CurrentIO_ResultTableMap]
    (
          [ResultName] sysname COLLATE SQL_Latin1_General_CP1_CS_AS NOT NULL PRIMARY KEY
        , [TargetTable] sysname COLLATE SQL_Latin1_General_CP1_CS_AS NOT NULL UNIQUE
    );

    CREATE TABLE [#CurrentIO_DatabaseCandidates]
    (
          [DatabaseId] int NOT NULL PRIMARY KEY
        , [DatabaseName] sysname COLLATE SQL_Latin1_General_CP1_CS_AS NOT NULL
        , [StateDesc] nvarchar(60) NULL
        , [UserAccessDesc] nvarchar(60) NULL
        , [IsReadOnly] bit NULL
        , [CompatibilityLevel] tinyint NULL
        , [CollationName] sysname NULL
        , [RecoveryModelDesc] nvarchar(60) NULL
        , [IsSystemDatabase] bit NULL
        , [RequestedOrdinal] int NULL
    );

    CREATE TABLE [#CurrentIO_DatabaseCandidateWarnings]
    (
          [RequestedName] sysname COLLATE SQL_Latin1_General_CP1_CS_AS NULL
        , [StatusCode] varchar(40) NOT NULL
        , [ErrorMessage] nvarchar(2048) NULL
    );

    CREATE TABLE [#CurrentIO_Before]
    (
          [DatabaseId] int NOT NULL
        , [FileId] int NOT NULL
        , [SampleMs] bigint NULL
        , [Reads] bigint NOT NULL
        , [ReadStallMs] bigint NOT NULL
        , [ReadBytes] bigint NOT NULL
        , [Writes] bigint NOT NULL
        , [WriteStallMs] bigint NOT NULL
        , [WriteBytes] bigint NOT NULL
        , [SizeOnDiskBytes] bigint NOT NULL
        , [FileHandle] varbinary(8) NULL
        , PRIMARY KEY ([DatabaseId],[FileId])
    );

    CREATE TABLE [#CurrentIO_After]
    (
          [DatabaseId] int NOT NULL
        , [FileId] int NOT NULL
        , [SampleMs] bigint NULL
        , [Reads] bigint NOT NULL
        , [ReadStallMs] bigint NOT NULL
        , [ReadBytes] bigint NOT NULL
        , [Writes] bigint NOT NULL
        , [WriteStallMs] bigint NOT NULL
        , [WriteBytes] bigint NOT NULL
        , [SizeOnDiskBytes] bigint NOT NULL
        , [FileHandle] varbinary(8) NULL
        , PRIMARY KEY ([DatabaseId],[FileId])
    );

    CREATE TABLE [#CurrentIO_Result]
    (
          [DatabaseId] int NOT NULL
        , [DatabaseName] sysname COLLATE SQL_Latin1_General_CP1_CS_AS NOT NULL
        , [FileId] int NOT NULL
        , [LogicalName] sysname NULL
        , [PhysicalName] nvarchar(260) NULL
        , [FileTypeDesc] nvarchar(60) NULL
        , [SampleSeconds] int NOT NULL
        , [Reads] bigint NOT NULL
        , [ReadBytes] bigint NOT NULL
        , [ReadStallMs] bigint NOT NULL
        , [Writes] bigint NOT NULL
        , [WriteBytes] bigint NOT NULL
        , [WriteStallMs] bigint NOT NULL
        , [ReadLatencyMs] decimal(19,3) NULL
        , [WriteLatencyMs] decimal(19,3) NULL
        , [OverallLatencyMs] decimal(19,3) NULL
        , [ReadThroughputMbPerSecond] decimal(19,3) NULL
        , [WriteThroughputMbPerSecond] decimal(19,3) NULL
        , [SizeOnDiskMb] decimal(19,2) NULL
    );

    CREATE TABLE [#CurrentIO_PendingBefore]
    (
          [RequestAddress] varbinary(8) NOT NULL PRIMARY KEY
        , [IoType] nvarchar(60) NOT NULL
        , [PendingDurationMs] bigint NOT NULL
        , [IoPending] int NOT NULL
        , [SchedulerAddress] varbinary(8) NOT NULL
        , [IoHandle] varbinary(8) NULL
        , [IoOffset] bigint NOT NULL
        , [IoHandlePath] nvarchar(256) NULL
    );

    CREATE TABLE [#CurrentIO_PendingAfter]
    (
          [RequestAddress] varbinary(8) NOT NULL PRIMARY KEY
        , [IoType] nvarchar(60) NOT NULL
        , [PendingDurationMs] bigint NOT NULL
        , [IoPending] int NOT NULL
        , [SchedulerAddress] varbinary(8) NOT NULL
        , [IoHandle] varbinary(8) NULL
        , [IoOffset] bigint NOT NULL
        , [IoHandlePath] nvarchar(256) NULL
    );

    CREATE TABLE [#CurrentIO_SchedulerContext]
    (
          [SchedulerAddress] varbinary(8) NOT NULL PRIMARY KEY
        , [SchedulerId] int NOT NULL
        , [RequestCountOnScheduler] int NOT NULL
        , [IoWaitTaskCountOnScheduler] int NOT NULL
    );
    CREATE TABLE [#CurrentIO_SourceRequests]
    (
          [session_id] smallint NOT NULL
        , [request_id] int NOT NULL
        , [scheduler_id] int NULL
        , PRIMARY KEY([session_id],[request_id])
    );
    CREATE TABLE [#CurrentIO_SourceTasks]
    (
          [task_address] varbinary(8) NOT NULL PRIMARY KEY
        , [scheduler_id] int NULL
    );
    CREATE TABLE [#CurrentIO_SourceWaitingTasks]
    (
          [waiting_task_address] varbinary(8) NOT NULL
        , [wait_type] nvarchar(60) NOT NULL
    );
    CREATE TABLE [#CurrentIO_SourceSchedulers]
    (
          [scheduler_address] varbinary(8) NOT NULL PRIMARY KEY
        , [scheduler_id] int NOT NULL
    );

    CREATE TABLE [#CurrentIO_PendingResult]
    (
          [CapturedAtUtc] datetime2(3) NOT NULL
        , [RequestAddress] varbinary(8) NOT NULL
        , [DatabaseId] int NULL
        , [DatabaseName] sysname NULL
        , [FileId] int NULL
        , [LogicalName] sysname NULL
        , [FileTypeDesc] nvarchar(60) NULL
        , [PhysicalPath] nvarchar(256) NULL
        , [IoType] nvarchar(60) NOT NULL
        , [PendingLayer] varchar(32) NOT NULL
        , [PendingDurationMs] bigint NOT NULL
        , [SchedulerId] int NULL
        , [RequestCountOnScheduler] int NULL
        , [IoWaitTaskCountOnScheduler] int NULL
        , [WasPresentInFirstSample] bit NOT NULL
        , [ObservationCount] tinyint NOT NULL
        , [FirstSamplePendingMs] bigint NULL
        , [IoOffset] bigint NOT NULL
        , [FindingCode] varchar(80) NOT NULL
        , [CorrelationScope] nvarchar(256) NOT NULL
    );

    CREATE TABLE [#CurrentIO_SourceStatus]
    (
          [SourceOrdinal] int NOT NULL PRIMARY KEY
        , [SourceName] sysname NOT NULL
        , [SourceObject] nvarchar(256) NOT NULL
        , [CapturedAtUtc] datetime2(3) NOT NULL
        , [StatusCode] varchar(40) NOT NULL
        , [IsPartial] bit NOT NULL
        , [ReturnedRowCount] bigint NOT NULL
        , [ErrorNumber] int NULL
        , [ErrorMessage] nvarchar(2048) NULL
        , [EvidenceLimit] nvarchar(1000) NOT NULL
    );

    CREATE TABLE [#CurrentIO_ModuleStatus]
    (
          [ModuleName] sysname NOT NULL
        , [CollectionTimeUtc] datetime2(3) NOT NULL
        , [StatusCode] varchar(40) NOT NULL
        , [IsPartial] bit NOT NULL
        , [ReturnedRowCount] bigint NOT NULL
        , [HasMoreRows] bit NOT NULL
        , [CrossDatabaseRequested] bit NOT NULL
        , [SampleSeconds] tinyint NOT NULL
        , [PendingIoRequested] bit NOT NULL
        , [PendingIoRowCount] bigint NOT NULL
        , [PendingIoHasMoreRows] bit NOT NULL
        , [ErrorNumber] int NULL
        , [ErrorMessage] nvarchar(2048) NULL
    );

    /* TempDB-DDL bleibt außerhalb des bewussten No-Wait-Quellzugriffs. */
    SET LOCK_TIMEOUT 0;

    IF @MaxZeilen < 0
       OR @MinLatencyMs IS NULL OR @MinLatencyMs < 0
       OR @SampleSeconds IS NULL OR @SampleSeconds > 60
       OR @PendingIoEinbeziehen IS NULL OR @NurWiederholtPending IS NULL
       OR @PhysischePfadeEinbeziehen IS NULL OR @MinPendingIoMs IS NULL OR @MinPendingIoMs < 0
       OR @SystemdatenbankenEinbeziehen IS NULL OR @PrintMeldungen IS NULL
       OR (@NurWiederholtPending = 1 AND @SampleSeconds = 0)
       OR @OutputMode NOT IN ('RAW','CONSOLE','TABLE','NONE')
       OR @JsonErzeugen IS NULL OR @JsonErzeugen NOT IN (0,1)
       OR (@OutputMode <> 'TABLE' AND NULLIF(LTRIM(RTRIM(COALESCE(@ResultTablesJson,N''))),N'') IS NOT NULL)
    BEGIN
        SET @StatusCode = 'INVALID_PARAMETER';
        SET @ErrorMessage = N'Mindestens ein Parameter besitzt einen ungültigen Wert.';
    END;

    IF @StatusCode = 'AVAILABLE' AND @OutputMode = 'TABLE'
    BEGIN
        EXEC [monitor].[InternalPrepareResultTables]
              @ResultTablesJson = @ResultTablesJson
            , @AllowedResultNames = N'moduleStatus|sourceStatus|files|pendingIo|warnings'
            , @MappingTable = N'#CurrentIO_ResultTableMap'
            , @StatusCode = @StatusCode OUTPUT
            , @ErrorMessage = @ErrorMessage OUTPUT
            , @ThrowOnError = 1;
    END;

    IF @StatusCode='AVAILABLE' AND @ParentCurrentStateSnapshotId IS NOT NULL
    BEGIN
        BEGIN TRY
            EXEC [sys].[sp_executesql] N'
                DECLARE @Probe int;
                SELECT @Probe=0
                FROM [#CurrentOverview_CurrentStateSnapshot_Context]
                WHERE 1=0;';

            IF NOT EXISTS
            (
                SELECT 1
                FROM [#CurrentOverview_CurrentStateSnapshot_Context]
                WHERE [SnapshotId]=@ParentCurrentStateSnapshotId
                  AND [OwnerSessionId]=CONVERT(smallint,@@SPID)
                  AND [ContractVersion]=2
            )
                THROW 51020,N'Die Parent-Snapshot-ID gehört nicht zum aktuellen Aufruf.',1;
        END TRY
        BEGIN CATCH
            SET @StatusCode='INVALID_PARENT_SNAPSHOT';
            SET @IsPartial=1;
            SET @ErrorNumber=ERROR_NUMBER();
            SET @ErrorMessage=ERROR_MESSAGE();
        END CATCH;
    END;

    IF @StatusCode = 'AVAILABLE'
    BEGIN
        EXEC [monitor].[USP_PrepareDatabaseCandidates]
              @DatabaseNames = @DatabaseNames
            , @SystemdatenbankenEinbeziehen = @SystemdatenbankenEinbeziehen
            , @DatabaseNamePattern = @DatabaseNamePattern
            , @AnalysisClass = 'STANDARD_CURRENT'
            , @StatusCode = @StatusCode OUTPUT
            , @ErrorMessage = @ErrorMessage OUTPUT
            , @CrossDatabaseRequested = @CrossDatabaseRequested OUTPUT
            , @CandidateTable = N'#CurrentIO_DatabaseCandidates'
            , @WarningTable = N'#CurrentIO_DatabaseCandidateWarnings';
    END;

    IF @StatusCode = 'AVAILABLE'
    BEGIN TRY
        INSERT [#CurrentIO_Before]
        (
              [DatabaseId],[FileId],[SampleMs],[Reads],[ReadStallMs]
            , [ReadBytes],[Writes],[WriteStallMs],[WriteBytes],[SizeOnDiskBytes]
            , [FileHandle]
        )
        SELECT
              [v].[database_id],[v].[file_id],[v].[sample_ms]
            , [v].[num_of_reads],[v].[io_stall_read_ms],[v].[num_of_bytes_read]
            , [v].[num_of_writes],[v].[io_stall_write_ms],[v].[num_of_bytes_written]
            , [v].[size_on_disk_bytes],[v].[file_handle]
        FROM [sys].[dm_io_virtual_file_stats](NULL,NULL) AS [v]
        INNER JOIN [#CurrentIO_DatabaseCandidates] AS [c]
          ON [c].[DatabaseId] = [v].[database_id];

        SET @FileSourceStatus='AVAILABLE';

        IF @PendingIoEinbeziehen=1
        BEGIN TRY
            INSERT [#CurrentIO_PendingBefore]
            (
                  [RequestAddress],[IoType],[PendingDurationMs],[IoPending]
                , [SchedulerAddress],[IoHandle],[IoOffset],[IoHandlePath]
            )
            SELECT
                  [p].[io_completion_request_address],[p].[io_type]
                , [p].[io_pending_ms_ticks],[p].[io_pending]
                , [p].[scheduler_address],[p].[io_handle],[p].[io_offset]
                , [p].[io_handle_path]
            FROM [sys].[dm_io_pending_io_requests] AS [p] WITH (NOLOCK);
            SET @PendingSourceStatus='AVAILABLE';
        END TRY
        BEGIN CATCH
            SELECT @PendingSourceStatus=CASE
                       WHEN ERROR_NUMBER() IN(229,262,297,300,371) THEN 'DENIED_PERMISSION'
                       WHEN ERROR_NUMBER()=1222 THEN 'TIMEOUT' ELSE 'ERROR_HANDLED' END,
                   @PendingSourceErrorNumber=ERROR_NUMBER(),
                   @PendingSourceErrorMessage=ERROR_MESSAGE();
        END CATCH;

        IF @SampleSeconds > 0
        BEGIN
            SET @Delay = CONVERT(char(8),DATEADD(SECOND,@SampleSeconds,CONVERT(time(0),'00:00:00')),108);
            WAITFOR DELAY @Delay;

            INSERT [#CurrentIO_After]
            (
                  [DatabaseId],[FileId],[SampleMs],[Reads],[ReadStallMs]
                , [ReadBytes],[Writes],[WriteStallMs],[WriteBytes],[SizeOnDiskBytes]
                , [FileHandle]
            )
            SELECT
                  [v].[database_id],[v].[file_id],[v].[sample_ms]
                , [v].[num_of_reads],[v].[io_stall_read_ms],[v].[num_of_bytes_read]
                , [v].[num_of_writes],[v].[io_stall_write_ms],[v].[num_of_bytes_written]
                , [v].[size_on_disk_bytes],[v].[file_handle]
            FROM [sys].[dm_io_virtual_file_stats](NULL,NULL) AS [v]
            INNER JOIN [#CurrentIO_DatabaseCandidates] AS [c]
              ON [c].[DatabaseId] = [v].[database_id];

            IF @PendingSourceStatus='AVAILABLE'
            BEGIN TRY
                INSERT [#CurrentIO_PendingAfter]
                (
                      [RequestAddress],[IoType],[PendingDurationMs],[IoPending]
                    , [SchedulerAddress],[IoHandle],[IoOffset],[IoHandlePath]
                )
                SELECT
                      [p].[io_completion_request_address],[p].[io_type]
                    , [p].[io_pending_ms_ticks],[p].[io_pending]
                    , [p].[scheduler_address],[p].[io_handle],[p].[io_offset]
                    , [p].[io_handle_path]
                FROM [sys].[dm_io_pending_io_requests] AS [p] WITH (NOLOCK);
            END TRY
            BEGIN CATCH
                SELECT @PendingSourceStatus=CASE
                           WHEN ERROR_NUMBER() IN(229,262,297,300,371) THEN 'DENIED_PERMISSION'
                           WHEN ERROR_NUMBER()=1222 THEN 'TIMEOUT' ELSE 'ERROR_HANDLED' END,
                       @PendingSourceErrorNumber=ERROR_NUMBER(),
                       @PendingSourceErrorMessage=ERROR_MESSAGE();
            END CATCH;
        END
        ELSE
        BEGIN
            INSERT [#CurrentIO_After]
            SELECT * FROM [#CurrentIO_Before];

            IF @PendingSourceStatus='AVAILABLE'
                INSERT [#CurrentIO_PendingAfter]
                SELECT * FROM [#CurrentIO_PendingBefore];
        END;

        INSERT [#CurrentIO_Result]
        (
              [DatabaseId],[DatabaseName],[FileId],[LogicalName],[PhysicalName]
            , [FileTypeDesc],[SampleSeconds],[Reads],[ReadBytes],[ReadStallMs]
            , [Writes],[WriteBytes],[WriteStallMs],[ReadLatencyMs]
            , [WriteLatencyMs],[OverallLatencyMs],[ReadThroughputMbPerSecond]
            , [WriteThroughputMbPerSecond],[SizeOnDiskMb]
        )
        SELECT TOP (@CandidateLimit)
              [b].[DatabaseId]
            , [c].[DatabaseName]
            , [b].[FileId]
            , [mf].[name]
            , [mf].[physical_name]
            , [mf].[type_desc]
            , @SampleSeconds
            , CASE WHEN @SampleSeconds > 0 THEN [a].[Reads]-[b].[Reads] ELSE [a].[Reads] END
            , CASE WHEN @SampleSeconds > 0 THEN [a].[ReadBytes]-[b].[ReadBytes] ELSE [a].[ReadBytes] END
            , CASE WHEN @SampleSeconds > 0 THEN [a].[ReadStallMs]-[b].[ReadStallMs] ELSE [a].[ReadStallMs] END
            , CASE WHEN @SampleSeconds > 0 THEN [a].[Writes]-[b].[Writes] ELSE [a].[Writes] END
            , CASE WHEN @SampleSeconds > 0 THEN [a].[WriteBytes]-[b].[WriteBytes] ELSE [a].[WriteBytes] END
            , CASE WHEN @SampleSeconds > 0 THEN [a].[WriteStallMs]-[b].[WriteStallMs] ELSE [a].[WriteStallMs] END
            , CONVERT(decimal(19,3),
                (CASE WHEN @SampleSeconds > 0 THEN [a].[ReadStallMs]-[b].[ReadStallMs] ELSE [a].[ReadStallMs] END)*1.0
                / NULLIF(CASE WHEN @SampleSeconds > 0 THEN [a].[Reads]-[b].[Reads] ELSE [a].[Reads] END,0))
            , CONVERT(decimal(19,3),
                (CASE WHEN @SampleSeconds > 0 THEN [a].[WriteStallMs]-[b].[WriteStallMs] ELSE [a].[WriteStallMs] END)*1.0
                / NULLIF(CASE WHEN @SampleSeconds > 0 THEN [a].[Writes]-[b].[Writes] ELSE [a].[Writes] END,0))
            , CONVERT(decimal(19,3),
                (CASE WHEN @SampleSeconds > 0
                      THEN ([a].[ReadStallMs]-[b].[ReadStallMs])+([a].[WriteStallMs]-[b].[WriteStallMs])
                      ELSE [a].[ReadStallMs]+[a].[WriteStallMs] END)*1.0
                / NULLIF(CASE WHEN @SampleSeconds > 0
                              THEN ([a].[Reads]-[b].[Reads])+([a].[Writes]-[b].[Writes])
                              ELSE [a].[Reads]+[a].[Writes] END,0)) AS [OverallLatencyMs]
            , CONVERT(decimal(19,3),CASE WHEN @SampleSeconds > 0
                     THEN ([a].[ReadBytes]-[b].[ReadBytes])/1048576.0/NULLIF(@SampleSeconds,0) END)
            , CONVERT(decimal(19,3),CASE WHEN @SampleSeconds > 0
                     THEN ([a].[WriteBytes]-[b].[WriteBytes])/1048576.0/NULLIF(@SampleSeconds,0) END)
            , CONVERT(decimal(19,2),[a].[SizeOnDiskBytes]/1048576.0)
        FROM [#CurrentIO_Before] AS [b]
        INNER JOIN [#CurrentIO_After] AS [a]
          ON [a].[DatabaseId]=[b].[DatabaseId]
         AND [a].[FileId]=[b].[FileId]
        INNER JOIN [#CurrentIO_DatabaseCandidates] AS [c]
          ON [c].[DatabaseId]=[b].[DatabaseId]
        LEFT JOIN [master].[sys].[master_files] AS [mf] WITH (NOLOCK)
          ON [mf].[database_id]=[b].[DatabaseId]
         AND [mf].[file_id]=[b].[FileId]
        WHERE CONVERT(decimal(19,3),
                (CASE WHEN @SampleSeconds > 0
                      THEN ([a].[ReadStallMs]-[b].[ReadStallMs])+([a].[WriteStallMs]-[b].[WriteStallMs])
                      ELSE [a].[ReadStallMs]+[a].[WriteStallMs] END)*1.0
                / NULLIF(CASE WHEN @SampleSeconds > 0
                              THEN ([a].[Reads]-[b].[Reads])+([a].[Writes]-[b].[Writes])
                              ELSE [a].[Reads]+[a].[Writes] END,0)) >= @MinLatencyMs
        ORDER BY
              [OverallLatencyMs] DESC
            , [c].[DatabaseName]
            , [b].[FileId];

        SELECT @RowCount=COUNT_BIG(*) FROM [#CurrentIO_Result];

        IF @PendingIoEinbeziehen=1 AND @PendingSourceStatus='AVAILABLE'
        BEGIN
            BEGIN TRY
                IF @ParentCurrentStateSnapshotId IS NOT NULL
                BEGIN
                    EXEC [sys].[sp_executesql] N'
                        DECLARE @Probe int;
                        SELECT @Probe=0 FROM [#CurrentOverview_CurrentStateSnapshot_Context] WHERE 1=0;
                        SELECT @Probe=0 FROM [#CurrentOverview_CurrentStateSnapshot_SourceStatus] WHERE 1=0;
                        SELECT @Probe=0 FROM [#CurrentOverview_CurrentStateSnapshot_Requests] WHERE 1=0;
                        SELECT @Probe=0 FROM [#CurrentOverview_CurrentStateSnapshot_Tasks] WHERE 1=0;
                        SELECT @Probe=0 FROM [#CurrentOverview_CurrentStateSnapshot_WaitingTasks] WHERE 1=0;
                        SELECT @Probe=0 FROM [#CurrentOverview_CurrentStateSnapshot_Schedulers] WHERE 1=0;';

                    IF NOT EXISTS
                    (
                        SELECT 1
                        FROM [#CurrentOverview_CurrentStateSnapshot_Context]
                        WHERE [SnapshotId]=@ParentCurrentStateSnapshotId
                          AND [OwnerSessionId]=CONVERT(smallint,@@SPID)
                          AND [ContractVersion]=2
                    )
                        THROW 51020,N'Die Parent-Snapshot-ID gehört nicht zum aktuellen Aufruf.',1;

                    INSERT [#CurrentIO_SourceRequests]
                    SELECT [session_id],[request_id],[scheduler_id]
                    FROM [#CurrentOverview_CurrentStateSnapshot_Requests]
                    WHERE [SnapshotId]=@ParentCurrentStateSnapshotId;

                    INSERT [#CurrentIO_SourceTasks]
                    SELECT [task_address],[scheduler_id]
                    FROM [#CurrentOverview_CurrentStateSnapshot_Tasks]
                    WHERE [SnapshotId]=@ParentCurrentStateSnapshotId;

                    INSERT [#CurrentIO_SourceWaitingTasks]
                    SELECT [waiting_task_address],[wait_type]
                    FROM [#CurrentOverview_CurrentStateSnapshot_WaitingTasks]
                    WHERE [SnapshotId]=@ParentCurrentStateSnapshotId;

                    INSERT [#CurrentIO_SourceSchedulers]
                    SELECT [scheduler_address],[scheduler_id]
                    FROM [#CurrentOverview_CurrentStateSnapshot_Schedulers]
                    WHERE [SnapshotId]=@ParentCurrentStateSnapshotId;

                    SELECT @EvidenceSnapshotStartedAtUtc=MIN([CapturedAtUtc])
                    FROM [#CurrentOverview_CurrentStateSnapshot_SourceStatus]
                    WHERE [SnapshotId]=@ParentCurrentStateSnapshotId
                      AND [SourceCode] IN ('REQUESTS','TASKS','WAITING_TASKS','SCHEDULERS');

                    IF EXISTS
                    (
                        SELECT 1
                        FROM [#CurrentOverview_CurrentStateSnapshot_SourceStatus]
                        WHERE [SnapshotId]=@ParentCurrentStateSnapshotId
                          AND [SourceCode] IN ('REQUESTS','TASKS','WAITING_TASKS','SCHEDULERS')
                          AND ([IsPartial]=1 OR [StatusCode]<>'AVAILABLE')
                    )
                        SET @PendingContextStatus='AVAILABLE_LIMITED';
                END
                ELSE
                BEGIN
                    SET @EvidenceSnapshotStartedAtUtc=SYSUTCDATETIME();
                    INSERT [#CurrentIO_SourceRequests]
                    SELECT [session_id],[request_id],[scheduler_id]
                    FROM [sys].[dm_exec_requests] WITH (NOLOCK);

                    INSERT [#CurrentIO_SourceTasks]
                    SELECT [task_address],[scheduler_id]
                    FROM [sys].[dm_os_tasks] WITH (NOLOCK);

                    INSERT [#CurrentIO_SourceWaitingTasks]
                    SELECT [waiting_task_address],[wait_type]
                    FROM [sys].[dm_os_waiting_tasks] WITH (NOLOCK);

                    INSERT [#CurrentIO_SourceSchedulers]
                    SELECT [scheduler_address],[scheduler_id]
                    FROM [sys].[dm_os_schedulers] WITH (NOLOCK);
                END;
            END TRY
            BEGIN CATCH
                SELECT @PendingContextStatus=CASE
                           WHEN ERROR_NUMBER() IN(229,262,297,300,371,916) THEN 'DENIED_PERMISSION'
                           WHEN ERROR_NUMBER()=1222 THEN 'TIMEOUT'
                           WHEN ERROR_NUMBER()=51020 THEN 'INVALID_PARENT_SNAPSHOT'
                           ELSE 'ERROR_HANDLED' END,
                       @PendingContextErrorNumber=ERROR_NUMBER(),
                       @PendingContextErrorMessage=ERROR_MESSAGE();
            END CATCH;

            BEGIN TRY
                ;WITH [RequestCounts] AS
                (
                    SELECT [r].[scheduler_id],COUNT_BIG(*) AS [RequestCount]
                    FROM [#CurrentIO_SourceRequests] AS [r]
                    WHERE [r].[scheduler_id] IS NOT NULL AND [r].[session_id]<>@@SPID
                    GROUP BY [r].[scheduler_id]
                ),
                [IoWaitCounts] AS
                (
                    SELECT [t].[scheduler_id],COUNT_BIG(*) AS [IoWaitTaskCount]
                    FROM [#CurrentIO_SourceTasks] AS [t]
                    INNER JOIN [#CurrentIO_SourceWaitingTasks] AS [w]
                      ON [w].[waiting_task_address]=[t].[task_address]
                    WHERE [w].[wait_type] LIKE N'PAGEIOLATCH[_]%'
                       OR [w].[wait_type] IN
                          (N'WRITELOG',N'IO_COMPLETION',N'ASYNC_IO_COMPLETION',N'BACKUPIO',N'ASYNC_DISKPOOL_LOCK')
                    GROUP BY [t].[scheduler_id]
                )
                INSERT [#CurrentIO_SchedulerContext]
                SELECT [s].[scheduler_address],[s].[scheduler_id],
                       TRY_CONVERT(int,COALESCE([r].[RequestCount],0)),
                       TRY_CONVERT(int,COALESCE([w].[IoWaitTaskCount],0))
                FROM [#CurrentIO_SourceSchedulers] AS [s]
                LEFT JOIN [RequestCounts] AS [r] ON [r].[scheduler_id]=[s].[scheduler_id]
                LEFT JOIN [IoWaitCounts] AS [w] ON [w].[scheduler_id]=[s].[scheduler_id];
                IF @PendingContextStatus='NOT_REQUESTED'
                    SET @PendingContextStatus='AVAILABLE';
            END TRY
            BEGIN CATCH
                SELECT @PendingContextStatus=CASE
                           WHEN ERROR_NUMBER() IN(229,262,297,300,371) THEN 'DENIED_PERMISSION'
                           WHEN ERROR_NUMBER()=1222 THEN 'TIMEOUT' ELSE 'ERROR_HANDLED' END,
                       @PendingContextErrorNumber=ERROR_NUMBER(),
                       @PendingContextErrorMessage=ERROR_MESSAGE();
            END CATCH;

            INSERT [#CurrentIO_PendingResult]
            (
                  [CapturedAtUtc],[RequestAddress],[DatabaseId],[DatabaseName]
                , [FileId],[LogicalName],[FileTypeDesc],[PhysicalPath],[IoType]
                , [PendingLayer],[PendingDurationMs],[SchedulerId]
                , [RequestCountOnScheduler],[IoWaitTaskCountOnScheduler]
                , [WasPresentInFirstSample],[ObservationCount],[FirstSamplePendingMs]
                , [IoOffset],[FindingCode],[CorrelationScope]
            )
            SELECT TOP(@CandidateLimit)
                  SYSUTCDATETIME(),[p].[RequestAddress],[v].[DatabaseId],[c].[DatabaseName]
                , [v].[FileId],[mf].[name],[mf].[type_desc]
                , CASE WHEN @PhysischePfadeEinbeziehen=1
                       THEN COALESCE([mf].[physical_name],[p].[IoHandlePath]) END
                , [p].[IoType]
                , CASE [p].[IoPending] WHEN 1 THEN 'PENDING_OS' ELSE 'PENDING_SQL_SERVER' END
                , [p].[PendingDurationMs],[sc].[SchedulerId]
                , [sc].[RequestCountOnScheduler],[sc].[IoWaitTaskCountOnScheduler]
                , CONVERT(bit,CASE WHEN [b].[RequestAddress] IS NULL THEN 0 ELSE 1 END)
                , CONVERT(tinyint,CASE WHEN @SampleSeconds>0 AND [b].[RequestAddress] IS NOT NULL THEN 2 ELSE 1 END)
                , [b].[PendingDurationMs],[p].[IoOffset]
                , CASE
                    WHEN @SampleSeconds>0 AND [b].[RequestAddress] IS NOT NULL THEN 'REPEATED_PENDING_IO_REVIEW'
                    ELSE 'POINT_IN_TIME_PENDING_IO' END
                , N'File handle maps the database file; scheduler request/wait counts are concurrent context and do not prove a causal request mapping.'
            FROM [#CurrentIO_PendingAfter] AS [p]
            LEFT JOIN [#CurrentIO_PendingBefore] AS [b]
              ON [b].[RequestAddress]=[p].[RequestAddress]
            INNER JOIN [#CurrentIO_After] AS [v]
              ON [v].[FileHandle]=[p].[IoHandle]
            INNER JOIN [#CurrentIO_DatabaseCandidates] AS [c]
              ON [c].[DatabaseId]=[v].[DatabaseId]
            LEFT JOIN [master].[sys].[master_files] AS [mf] WITH (NOLOCK)
              ON [mf].[database_id]=[v].[DatabaseId] AND [mf].[file_id]=[v].[FileId]
            LEFT JOIN [#CurrentIO_SchedulerContext] AS [sc]
              ON [sc].[SchedulerAddress]=[p].[SchedulerAddress]
            WHERE [p].[PendingDurationMs]>=@MinPendingIoMs
              AND (@NurWiederholtPending=0 OR [b].[RequestAddress] IS NOT NULL)
            ORDER BY [p].[PendingDurationMs] DESC,[c].[DatabaseName],[v].[FileId],[p].[IoOffset];

            SELECT @PendingRowCount=COUNT_BIG(*) FROM [#CurrentIO_PendingResult];
            SET @PendingHasMoreRows=CONVERT(bit,CASE WHEN @Limit<9223372036854775807 AND @PendingRowCount>@Limit THEN 1 ELSE 0 END);
        END;

        SELECT @WarningCount=COUNT_BIG(*) FROM [#CurrentIO_DatabaseCandidateWarnings];
        SET @HasMoreRows=CONVERT(bit,CASE WHEN @Limit<9223372036854775807 AND @RowCount>@Limit THEN 1 ELSE 0 END);

        IF @WarningCount > 0
        BEGIN
            SET @StatusCode = 'AVAILABLE_LIMITED';
            SET @IsPartial = 1;
        END;

        IF @PendingIoEinbeziehen=1 AND @PendingSourceStatus<>'AVAILABLE'
        BEGIN
            SET @StatusCode='AVAILABLE_LIMITED';
            SET @IsPartial=1;
        END;

        IF @PendingIoEinbeziehen=1
           AND @PendingContextStatus='INVALID_PARENT_SNAPSHOT'
        BEGIN
            SET @StatusCode='INVALID_PARENT_SNAPSHOT';
            SET @IsPartial=1;
            SET @ErrorNumber=@PendingContextErrorNumber;
            SET @ErrorMessage=@PendingContextErrorMessage;
        END
        ELSE IF @PendingIoEinbeziehen=1 AND @PendingContextStatus<>'AVAILABLE'
        BEGIN
            SET @StatusCode='AVAILABLE_LIMITED';
            SET @IsPartial=1;
        END;
    END TRY
    BEGIN CATCH
        SET @ErrorNumber = ERROR_NUMBER();
        SET @ErrorMessage = ERROR_MESSAGE();
        SET @StatusCode = CASE
            WHEN @ErrorNumber IN (229,262,297,300,371,916) THEN 'DENIED_PERMISSION'
            WHEN @ErrorNumber = 1222 THEN 'TIMEOUT'
            ELSE 'ERROR_HANDLED' END;
        SET @IsPartial = 1;
        SET @FileSourceStatus=@StatusCode;
        SET @FileSourceErrorNumber=@ErrorNumber;
        SET @FileSourceErrorMessage=@ErrorMessage;
    END CATCH;

    IF @StatusCode <> 'AVAILABLE' AND @StatusCode <> 'AVAILABLE_LIMITED'
        SET @IsPartial = 1;

    INSERT [#CurrentIO_SourceStatus]
    (
          [SourceOrdinal],[SourceName],[SourceObject],[CapturedAtUtc],[StatusCode]
        , [IsPartial],[ReturnedRowCount],[ErrorNumber],[ErrorMessage],[EvidenceLimit]
    )
    VALUES
    (
          1,N'fileStatistics',N'sys.dm_io_virtual_file_stats',@CollectionTimeUtc
        , @FileSourceStatus,CONVERT(bit,CASE WHEN @FileSourceStatus='AVAILABLE' THEN 0 ELSE 1 END)
        , @RowCount,@FileSourceErrorNumber,@FileSourceErrorMessage
        , N'Kumulative Zähler seit Engine-Start oder Delta aus zwei Beobachtungen; Dateikatalog und DMV können sich zwischen den Beobachtungen ändern.'
    ),
    (
          2,N'pendingIo',N'sys.dm_io_pending_io_requests',@CollectionTimeUtc
        , @PendingSourceStatus,CONVERT(bit,CASE WHEN @PendingSourceStatus IN('AVAILABLE','NOT_REQUESTED') THEN 0 ELSE 1 END)
        , @PendingRowCount,@PendingSourceErrorNumber,@PendingSourceErrorMessage
        , N'Aktueller, flüchtiger Zustand. io_pending_ms_ticks ist informational/internal; ein einzelner Request beweist keinen Storagefehler.'
    ),
    (
          3,N'pendingIoContext',N'sys.dm_os_schedulers|sys.dm_exec_requests|sys.dm_os_tasks|sys.dm_os_waiting_tasks',@CollectionTimeUtc
        , @PendingContextStatus,CONVERT(bit,CASE WHEN @PendingContextStatus IN('AVAILABLE','NOT_REQUESTED') THEN 0 ELSE 1 END)
        , (SELECT COUNT_BIG(*) FROM [#CurrentIO_SchedulerContext])
        , @PendingContextErrorNumber,@PendingContextErrorMessage
        , N'Schedulerbezogene Request- und I/O-Wait-Anzahlen sind gleichzeitiger Kontext, keine kausale Zuordnung zu einer Pending-I/O-Adresse.'
    );

    INSERT [#CurrentIO_ModuleStatus]
    (
          [ModuleName],[CollectionTimeUtc],[StatusCode],[IsPartial]
        , [ReturnedRowCount],[HasMoreRows],[CrossDatabaseRequested]
        , [SampleSeconds],[PendingIoRequested],[PendingIoRowCount]
        , [PendingIoHasMoreRows],[ErrorNumber],[ErrorMessage]
    )
    VALUES
    (
          N'USP_CurrentIO',@CollectionTimeUtc,@StatusCode,@IsPartial
        , CASE WHEN @RowCount>@Limit THEN @Limit ELSE @RowCount END
        , @HasMoreRows,@CrossDatabaseRequested,@SampleSeconds,@PendingIoEinbeziehen
        , CASE WHEN @PendingRowCount>@Limit THEN @Limit ELSE @PendingRowCount END
        , @PendingHasMoreRows,@ErrorNumber,@ErrorMessage
    );

    IF @PrintMeldungen = 1 AND @StatusCode NOT IN ('AVAILABLE','AVAILABLE_LIMITED')
    BEGIN
        SET @Message = FORMATMESSAGE(N'WARNUNG USP_CurrentIO [%s]: %s',@StatusCode,COALESCE(@ErrorMessage,N'Keine Detailmeldung verfügbar.'));
        RAISERROR(N'%s',10,1,@Message) WITH NOWAIT;
    END;

    IF @PrintMeldungen = 1 AND @WarningCount > 0
    BEGIN
        SET @Message = FORMATMESSAGE(N'HINWEIS USP_CurrentIO: %I64d explizit angeforderte Datenbank(en) konnten nicht verarbeitet werden.',@WarningCount);
        RAISERROR(N'%s',10,1,@Message) WITH NOWAIT;
    END;

    IF @PrintMeldungen=1 AND @PendingIoEinbeziehen=1 AND @PendingSourceStatus<>'AVAILABLE'
    BEGIN
        SET @Message=FORMATMESSAGE(N'HINWEIS USP_CurrentIO pendingIo [%s]: %s',@PendingSourceStatus,COALESCE(@PendingSourceErrorMessage,N'Quelle nicht verfügbar.'));
        RAISERROR(N'%s',10,1,@Message) WITH NOWAIT;
    END;

    IF @OutputMode = 'CONSOLE'
    BEGIN
        IF @RowCount > 0 OR @PendingRowCount > 0
        BEGIN
            ;WITH [ConsoleRows] AS
            (
                SELECT CONVERT(int,2) AS [SortGroup],[OverallLatencyMs] AS [SortMetric],
                       N'Datei-I/O' AS [Evidenzart],[DatabaseName] AS [Datenbank],
                       [FileId] AS [Datei-ID],[LogicalName] AS [Logischer Name],
                       [FileTypeDesc] AS [Dateityp],N'Gesamtlatenz je I/O' AS [Metrik],
                       [OverallLatencyMs] AS [Wert],N'ms' AS [Einheit],
                       CONVERT(varchar(80),CASE WHEN @SampleSeconds=0 THEN 'CUMULATIVE_SINCE_START' ELSE 'SAMPLE_DELTA' END) AS [Bewertung],
                       CONVERT(nvarchar(1000),CONCAT(N'Reads=',[Reads],N'; Writes=',[Writes],N'; SampleSeconds=',[SampleSeconds])) AS [Kontext]
                FROM [#CurrentIO_Result]
                UNION ALL
                SELECT 1,CONVERT(decimal(19,3),[PendingDurationMs]),N'Pending I/O',
                       [DatabaseName],[FileId],[LogicalName],[FileTypeDesc],N'Pending-Dauer',
                       CONVERT(decimal(19,3),[PendingDurationMs]),N'ms',[FindingCode],
                       CONVERT(nvarchar(1000),CONCAT(N'Layer=',[PendingLayer],N'; Beobachtungen=',[ObservationCount],N'; Scheduler=',COALESCE(CONVERT(varchar(20),[SchedulerId]),N'NULL')))
                FROM [#CurrentIO_PendingResult]
            )
            SELECT TOP(@Limit) [Evidenzart],[Datenbank],[Datei-ID],[Logischer Name],
                   [Dateityp],[Metrik],[Wert],[Einheit],[Bewertung],[Kontext]
            FROM [ConsoleRows]
            ORDER BY [SortGroup],[SortMetric] DESC,[Datenbank],[Datei-ID];
        END
        ELSE
        BEGIN
            SELECT
                  CASE WHEN @StatusCode IN ('AVAILABLE','AVAILABLE_LIMITED')
                       THEN N'Keine Datei-I/O-Daten entsprechen den Filtern.'
                       ELSE N'Die Datei-I/O-Analyse ist nicht verfügbar.' END AS [Ergebnis]
                , @StatusCode AS [Status]
                , @ErrorMessage AS [Hinweis];
        END;
    END
    ELSE IF @OutputMode = 'RAW'
    BEGIN
        SELECT * FROM [#CurrentIO_ModuleStatus];

        SELECT * FROM [#CurrentIO_SourceStatus] ORDER BY [SourceOrdinal];

        SELECT TOP (@Limit) *
        FROM [#CurrentIO_Result]
        ORDER BY [OverallLatencyMs] DESC,[DatabaseName],[FileId];

        SELECT TOP(@Limit) *
        FROM [#CurrentIO_PendingResult]
        ORDER BY [PendingDurationMs] DESC,[DatabaseName],[FileId],[IoOffset];

        SELECT [RequestedName],[StatusCode],[ErrorMessage]
        FROM [#CurrentIO_DatabaseCandidateWarnings]
        ORDER BY [RequestedName];
    END;

    IF @JsonErzeugen = 1
    BEGIN
        DECLARE @Meta nvarchar(max)=
        (
            SELECT
                  N'CurrentIO' AS [resultName]
                , 3 AS [schemaVersion]
                , @CollectionTimeUtc AS [generatedAtUtc]
                , @EvidenceSnapshotStartedAtUtc AS [evidenceSnapshotStartedAtUtc]
                , @EvidenceSnapshotId AS [evidenceSnapshotId]
                , @StatusCode AS [statusCode]
                , @IsPartial AS [isPartial]
                , @MaxZeilen AS [requestedMaxRows]
                , CASE WHEN @RowCount>@Limit THEN @Limit ELSE @RowCount END AS [returnedRows]
                , @HasMoreRows AS [hasMoreRows]
                , @SampleSeconds AS [sampleSeconds]
                , @PendingIoEinbeziehen AS [pendingIoRequested]
                , CASE WHEN @PendingRowCount>@Limit THEN @Limit ELSE @PendingRowCount END AS [pendingIoReturnedRows]
                , @PendingHasMoreRows AS [pendingIoHasMoreRows]
            FOR JSON PATH,WITHOUT_ARRAY_WRAPPER,INCLUDE_NULL_VALUES
        );
        DECLARE @Data nvarchar(max)=
        (
            SELECT TOP (@Limit) *
            FROM [#CurrentIO_Result]
            ORDER BY [OverallLatencyMs] DESC,[DatabaseName],[FileId]
            FOR JSON PATH,INCLUDE_NULL_VALUES
        );
        DECLARE @Warnings nvarchar(max)=
        (
            SELECT [RequestedName],[StatusCode],[ErrorMessage]
            FROM [#CurrentIO_DatabaseCandidateWarnings]
            ORDER BY [RequestedName]
            FOR JSON PATH,INCLUDE_NULL_VALUES
        );
        DECLARE @SourceStatusJson nvarchar(max)=
        (
            SELECT * FROM [#CurrentIO_SourceStatus] ORDER BY [SourceOrdinal]
            FOR JSON PATH,INCLUDE_NULL_VALUES
        );
        DECLARE @PendingJson nvarchar(max)=
        (
            SELECT TOP(@Limit) * FROM [#CurrentIO_PendingResult]
            ORDER BY [PendingDurationMs] DESC,[DatabaseName],[FileId],[IoOffset]
            FOR JSON PATH,INCLUDE_NULL_VALUES
        );
        SET @Json=CONCAT(N'{"meta":',COALESCE(@Meta,N'{}'),N',"sourceStatus":',COALESCE(@SourceStatusJson,N'[]'),N',"files":',COALESCE(@Data,N'[]'),N',"pendingIo":',COALESCE(@PendingJson,N'[]'),N',"warnings":',COALESCE(@Warnings,N'[]'),N'}');
    END;

    IF @OutputMode = 'TABLE'
    BEGIN
        DECLARE @TargetTable sysname;

        SELECT @TargetTable=[TargetTable]
        FROM [#CurrentIO_ResultTableMap]
        WHERE [ResultName]=N'moduleStatus';
        IF @TargetTable IS NOT NULL
            EXEC [monitor].[InternalWriteResultTable]
                  @SourceTable=N'#CurrentIO_ModuleStatus'
                , @TargetTable=@TargetTable
                , @ThrowOnError=1;

        SET @TargetTable=NULL;
        SELECT @TargetTable=[TargetTable]
        FROM [#CurrentIO_ResultTableMap]
        WHERE [ResultName]=N'sourceStatus';
        IF @TargetTable IS NOT NULL
            EXEC [monitor].[InternalWriteResultTable]
                  @SourceTable=N'#CurrentIO_SourceStatus'
                , @TargetTable=@TargetTable
                , @ThrowOnError=1;

        SET @TargetTable=NULL;
        SELECT @TargetTable=[TargetTable]
        FROM [#CurrentIO_ResultTableMap]
        WHERE [ResultName]=N'files';
        IF @TargetTable IS NOT NULL
            EXEC [monitor].[InternalWriteResultTable]
                  @SourceTable=N'#CurrentIO_Result'
                , @TargetTable=@TargetTable
                , @ThrowOnError=1;

        SET @TargetTable=NULL;
        SELECT @TargetTable=[TargetTable]
        FROM [#CurrentIO_ResultTableMap]
        WHERE [ResultName]=N'pendingIo';
        IF @TargetTable IS NOT NULL
            EXEC [monitor].[InternalWriteResultTable]
                  @SourceTable=N'#CurrentIO_PendingResult'
                , @TargetTable=@TargetTable
                , @ThrowOnError=1;

        SET @TargetTable=NULL;
        SELECT @TargetTable=[TargetTable]
        FROM [#CurrentIO_ResultTableMap]
        WHERE [ResultName]=N'warnings';
        IF @TargetTable IS NOT NULL
            EXEC [monitor].[InternalWriteResultTable]
                  @SourceTable=N'#CurrentIO_DatabaseCandidateWarnings'
                , @TargetTable=@TargetTable
                , @ThrowOnError=1;
    END;
END;
GO
-- END SOURCE: Code/02_CurrentState/080_USP_CurrentIO.sql

-- BEGIN SOURCE: Code/02_CurrentState/090_USP_CurrentLog.sql
/*
===============================================================================
Objekt       : monitor.USP_CurrentLog
Version      : 2.0.0
Stand        : 2026-07-15
Typ          : Stored Procedure
Zweck        : Liefert den aktuellen Transaktionslogzustand einer expliziten
               Datenbankliste oder aller zulässigen Datenbanken. Fehler einer
               Datenbank brechen die übrigen Abfragen nicht ab.
SQL-Version  : SQL Server 2019 oder neuer.
Datenquellen : master.sys.databases, sys.dm_db_log_space_usage,
               sys.dm_db_log_stats, optional sys.dm_db_log_info,
               optional sys.dm_tran_persistent_version_store_stats.
Parameter    : @DatabaseNames, @DatabaseNamePattern,
               @SystemdatenbankenEinbeziehen, @MinUsedPercent,
               @MitVlfInformationen, @MitPersistentVersionStore,
               @MaxZeilen, @ResultSetArt,
               @JsonErzeugen, @Json OUTPUT, @PrintMeldungen, @Hilfe.
Semantik     : @DatabaseNames enthält eine bracket-aware Pipe-Liste exakter
               Namen. NULL bedeutet alle zulässigen Datenbanken; N'' ist
               absichtlich ungültig. Exakte Liste und Pattern sind exklusiv.
Ausgabe      : RAW = stabiler technischer Vertrag; CONSOLE = formatierte
               Darstellung; NONE = kein Resultset. JSON enthält meta, logs,
               databaseStatus und warnings als benannte Arrays.
Berechtigung : Je Datenquelle VIEW SERVER STATE/VIEW SERVER PERFORMANCE STATE
               bzw. VIEW DATABASE PERFORMANCE STATE ab SQL Server 2022.
Gruppengate  : Cross-Database über CROSS_DATABASE_DEEP; VLF über LOG_VLF_DEEP.
Eigenlast    : Standard moderat; automatische Datenbankauswahl ist durch
               keine Datenbank-Vorabbegrenzung.
Locking      : Datenbankliste READUNCOMMITTED; System-DMVs je Datenbank.
Beispiele    : EXEC [monitor].[USP_CurrentLog]
                    @DatabaseNames=N'[DeineDatenbank]|[BeispielDatenbankB]';
               EXEC [monitor].[USP_CurrentLog]
                    @DatabaseNames=NULL,@DatabaseNamePattern=N'like:Database_%';
               DECLARE @J nvarchar(max);
               EXEC [monitor].[USP_CurrentLog] @DatabaseNames=N'[DeineDatenbank]',
                    @ResultSetArt='none',@JsonErzeugen=1,@Json=@J OUTPUT;
               SELECT @J AS [Json];
Änderungen   : 2.0.0 - @AlleDatenbanken entfernt; Listen-/Patternvertrag,
                         RAW/CONSOLE/NONE und JSON-Envelope eingeführt.
               1.0.0 - Erstfassung Phase 1B.
===============================================================================
*/
CREATE OR ALTER PROCEDURE [monitor].[USP_CurrentLog]
      @DatabaseNames                    nvarchar(max)  = NULL
    , @SystemdatenbankenEinbeziehen     bit            = 0
    , @DatabaseNamePattern              nvarchar(4000) = NULL
    , @HighImpactConfirmed              bit            = 0
    , @MinUsedPercent                   decimal(5,2)   = NULL
    , @MitVlfInformationen              bit            = 0
    , @MitPersistentVersionStore        bit            = 0
    , @MaxZeilen                        int            = 1000
    , @ResultSetArt                     varchar(16)    = 'CONSOLE'
    , @ResultTablesJson               nvarchar(max) = NULL
    , @JsonErzeugen                     bit            = 0
    , @Json                             nvarchar(max)  = NULL OUTPUT
    , @PrintMeldungen                   bit            = 1
    , @Hilfe                            bit            = 0
AS
BEGIN
    SET NOCOUNT ON;
    SET LOCK_TIMEOUT 0;
    SET @Json = NULL;

    DECLARE @ResultSetArtNormalisiert varchar(16) = UPPER(LTRIM(RTRIM(COALESCE(@ResultSetArt, ''))));
    DECLARE @TableResultRequested bit = CASE WHEN @ResultSetArtNormalisiert = 'TABLE' THEN 1 ELSE 0 END;
    DECLARE @ConsoleResultRequested bit = CASE WHEN @ResultSetArtNormalisiert = 'CONSOLE' THEN 1 ELSE 0 END;
    DECLARE @TableTarget sysname=NULL;
    IF @TableResultRequested=0 AND NULLIF(LTRIM(RTRIM(COALESCE(@ResultTablesJson,N''))),N'') IS NOT NULL THROW 51011,N'@ResultTablesJson ist ausschließlich mit @ResultSetArt=TABLE zulässig.',1;
    IF @TableResultRequested=1 EXEC [monitor].[InternalPrepareSingleResultTable] @ResultTablesJson=@ResultTablesJson,@ResultName=N'logs',@TargetTable=@TableTarget OUTPUT,@ThrowOnError=1;
    IF @TableResultRequested = 1 OR @ConsoleResultRequested = 1 SET @ResultSetArtNormalisiert = 'NONE';
    DECLARE @EffectiveMaxZeilen bigint =
        CASE WHEN @MaxZeilen IS NULL OR @MaxZeilen = 0 THEN CONVERT(bigint, 9223372036854775807)
             WHEN @MaxZeilen > 0 THEN CONVERT(bigint, @MaxZeilen)
             ELSE CONVERT(bigint, 0) END;
    DECLARE @CandidateMaxZeilen bigint =
        CASE WHEN @MaxZeilen IS NULL OR @MaxZeilen = 0 THEN CONVERT(bigint, 9223372036854775807)
             WHEN @MaxZeilen BETWEEN 1 AND 2147483646 THEN CONVERT(bigint, @MaxZeilen) + 1
             WHEN @MaxZeilen > 0 THEN CONVERT(bigint, @MaxZeilen)
             ELSE CONVERT(bigint, 0) END;
    DECLARE @MonitorPrintMessage nvarchar(2048);

    IF @Hilfe = 1
    BEGIN
        PRINT N'monitor.USP_CurrentLog';
        PRINT N'@DatabaseNames=N''[Db1]|[Db2]''; NULL=alle zulässigen Datenbanken; N'''' bedeutet keine Einschränkung.';
        PRINT N'@DatabaseNamePattern: ein Pattern mit like:, regex: oder regexi:; exklusiv zu @DatabaseNames.';
        PRINT N'Die Datenbankauswahl wird nicht vorab begrenzt.';
        PRINT N'@MaxZeilen: positiv begrenzt; NULL/0=unbegrenzt; negativ=INVALID_PARAMETER.';
        PRINT N'@ResultSetArt=CONSOLE (Default)|RAW|TABLE|NONE (case-insensitiv); @JsonErzeugen=1 erzeugt @Json OUTPUT.';
        PRINT N'@MitVlfInformationen=1 erfordert LOG_VLF_DEEP.';
        RETURN;
    END;

    DECLARE @CollectionTimeUtc datetime2(3) = SYSUTCDATETIME();
    DECLARE @StatusCode varchar(40) = 'AVAILABLE';
    DECLARE @IsPartial bit = 0;
    DECLARE @RowCount bigint = 0;
    DECLARE @CandidateRowCount bigint = 0;
    DECLARE @HasMoreRows bit = 0;
    DECLARE @ErrorNumber int = NULL;
    DECLARE @ErrorMessage nvarchar(2048) = NULL;
    DECLARE @Detail nvarchar(2000) = NULL;
    DECLARE @CrossDatabaseRequested bit = 0;
    DECLARE @VlfAllowed bit = 0;
    DECLARE @VlfStatus varchar(40) = 'SKIPPED';
    DECLARE @RequiredPermission nvarchar(256) =
        CASE WHEN TRY_CONVERT(int, SERVERPROPERTY(N'ProductMajorVersion')) >= 16
             THEN N'VIEW SERVER PERFORMANCE STATE / VIEW DATABASE PERFORMANCE STATE'
             ELSE N'VIEW SERVER STATE' END;

    CREATE TABLE [#CurrentLog_DatabaseCandidates]
    (
          [DatabaseId] int NOT NULL
        , [DatabaseName] sysname COLLATE SQL_Latin1_General_CP1_CS_AS NOT NULL
        , [StateDesc] nvarchar(60) NULL
        , [UserAccessDesc] nvarchar(60) NULL
        , [IsReadOnly] bit NULL
        , [CompatibilityLevel] tinyint NULL
        , [CollationName] sysname NULL
        , [RecoveryModelDesc] nvarchar(60) NULL
        , [IsSystemDatabase] bit NULL
        , [RequestedOrdinal] int NULL
    );

    CREATE TABLE [#CurrentLog_DatabaseCandidateWarnings]
    (
          [RequestedName] sysname COLLATE SQL_Latin1_General_CP1_CS_AS NULL
        , [StatusCode] varchar(40) NOT NULL
        , [ErrorMessage] nvarchar(2048) NOT NULL
    );

    CREATE TABLE [#CurrentLog_Result]
    (
          [DatabaseId] int NOT NULL
        , [DatabaseName] sysname COLLATE SQL_Latin1_General_CP1_CS_AS NOT NULL
        , [RecoveryModel] nvarchar(60) NULL
        , [LogReuseWaitDesc] nvarchar(60) NULL
        , [TotalLogSizeMb] decimal(19,2) NULL
        , [UsedLogSizeMb] decimal(19,2) NULL
        , [UsedLogPercent] decimal(19,4) NULL
        , [LogSinceLastBackupMb] decimal(19,2) NULL
        , [ActiveVlfCount] bigint NULL
        , [TotalVlfCount] bigint NULL
        , [LogTruncationHoldupReason] nvarchar(60) NULL
        , [LogBackupTime] datetime NULL
        , [LogRecoverySizeMb] decimal(19,2) NULL
        , [IsAdrEnabled] bit NULL
        , [PersistentVersionStoreMb] decimal(19,2) NULL
        , [SpaceStatus] varchar(40) NOT NULL
        , [StatsStatus] varchar(40) NOT NULL
        , [VlfStatus] varchar(40) NOT NULL
        , [PvsStatus] varchar(40) NOT NULL
    );

    CREATE TABLE [#CurrentLog_Errors]
    (
          [DatabaseName] sysname COLLATE SQL_Latin1_General_CP1_CS_AS NULL
        , [SubModule] varchar(40) NOT NULL
        , [StatusCode] varchar(40) NOT NULL
        , [ErrorNumber] int NULL
        , [ErrorMessage] nvarchar(2048) NULL
    );

    IF @MaxZeilen < 0
       OR (@MinUsedPercent IS NOT NULL AND (@MinUsedPercent < 0 OR @MinUsedPercent > 100))
       OR @ResultSetArtNormalisiert NOT IN ('RAW', 'CONSOLE', 'NONE')
    BEGIN
        SET @StatusCode = 'INVALID_PARAMETER';
        SET @ErrorMessage = N'Ungültige Mengen-, Prozent- oder Ausgabeparameter.';
    END;

    IF @StatusCode = 'AVAILABLE'
    BEGIN
        EXEC [monitor].[USP_PrepareDatabaseCandidates]
              @DatabaseNames = @DatabaseNames
            , @SystemdatenbankenEinbeziehen = @SystemdatenbankenEinbeziehen
            , @DatabaseNamePattern = @DatabaseNamePattern,@HighImpactConfirmed=@HighImpactConfirmed

            , @AnalysisClass = 'STANDARD_CURRENT'
            , @StatusCode = @StatusCode OUTPUT
            , @ErrorMessage = @ErrorMessage OUTPUT
            , @CrossDatabaseRequested = @CrossDatabaseRequested OUTPUT,@CandidateTable=N'#CurrentLog_DatabaseCandidates',@WarningTable=N'#CurrentLog_DatabaseCandidateWarnings';
    END;

    IF @StatusCode = 'AVAILABLE' AND @MitVlfInformationen = 1
    BEGIN
        EXEC [monitor].[InternalCheckAnalysisPath]
              @AnalysisClass='LOG_VLF_DEEP'
            , @HighImpactConfirmed=@HighImpactConfirmed
            , @StatusCode=@StatusCode OUTPUT
            , @ErrorMessage=@ErrorMessage OUTPUT;
        SET @VlfStatus=@StatusCode;
        SET @VlfAllowed=CONVERT(bit,CASE WHEN @StatusCode='AVAILABLE' THEN 1 ELSE 0 END);
        IF @StatusCode<>'AVAILABLE' SET @IsPartial=1;
    END;

    IF @StatusCode = 'AVAILABLE'
    BEGIN
        INSERT [#CurrentLog_Result]
        (
              [DatabaseId], [DatabaseName], [RecoveryModel], [LogReuseWaitDesc]
            , [IsAdrEnabled], [SpaceStatus], [StatsStatus], [VlfStatus], [PvsStatus]
        )
        SELECT
              [d].[database_id]
            , [d].[name]
            , [d].[recovery_model_desc]
            , [d].[log_reuse_wait_desc]
            , [d].[is_accelerated_database_recovery_on]
            , 'PENDING'
            , 'PENDING'
            , CASE WHEN @MitVlfInformationen = 0 THEN 'SKIPPED' ELSE @VlfStatus END
            , CASE WHEN @MitPersistentVersionStore = 0 THEN 'SKIPPED' ELSE 'PENDING' END
        FROM [master].[sys].[databases] AS [d] WITH (NOLOCK)
        INNER JOIN [#CurrentLog_DatabaseCandidates] AS [c]
          ON [c].[DatabaseId] = [d].[database_id];

        DECLARE @DbName sysname;
        DECLARE @DbId int;
        DECLARE @Sql nvarchar(max);
        DECLARE @Total decimal(19,2);
        DECLARE @Used decimal(19,2);
        DECLARE @Pct decimal(19,4);
        DECLARE @Since decimal(19,2);
        DECLARE @ActiveVlf bigint;
        DECLARE @TotalVlf bigint;
        DECLARE @Holdup nvarchar(60);
        DECLARE @Backup datetime;
        DECLARE @Recovery decimal(19,2);
        DECLARE @Cnt bigint;

        DECLARE [DatabaseCursor] CURSOR LOCAL FAST_FORWARD FOR
        SELECT [DatabaseId], [DatabaseName]
        FROM [#CurrentLog_DatabaseCandidates]
        ORDER BY COALESCE([RequestedOrdinal], [DatabaseId]), [DatabaseId];

        OPEN [DatabaseCursor];
        FETCH NEXT FROM [DatabaseCursor] INTO @DbId, @DbName;

        WHILE @@FETCH_STATUS = 0
        BEGIN
            BEGIN TRY
                SET @Total = NULL; SET @Used = NULL; SET @Pct = NULL; SET @Since = NULL;
                SET @Sql = N'USE ' + QUOTENAME(@DbName) + N';
SELECT
      @Total = CONVERT(decimal(19,2), [total_log_size_in_bytes] / 1048576.0)
    , @Used  = CONVERT(decimal(19,2), [used_log_space_in_bytes] / 1048576.0)
    , @Pct   = CONVERT(decimal(19,4), [used_log_space_in_percent])
    , @Since = CONVERT(decimal(19,2), [log_space_in_bytes_since_last_backup] / 1048576.0)
FROM [sys].[dm_db_log_space_usage] WITH (NOLOCK);';
                EXEC [sys].[sp_executesql] @Sql,
                    N'@Total decimal(19,2) OUTPUT,@Used decimal(19,2) OUTPUT,@Pct decimal(19,4) OUTPUT,@Since decimal(19,2) OUTPUT',
                    @Total OUTPUT, @Used OUTPUT, @Pct OUTPUT, @Since OUTPUT;
                UPDATE [#CurrentLog_Result]
                SET [TotalLogSizeMb] = @Total, [UsedLogSizeMb] = @Used,
                    [UsedLogPercent] = @Pct, [LogSinceLastBackupMb] = @Since,
                    [SpaceStatus] = 'AVAILABLE'
                WHERE [DatabaseId] = @DbId;
            END TRY
            BEGIN CATCH
                UPDATE [#CurrentLog_Result]
                SET [SpaceStatus] = CASE WHEN ERROR_NUMBER() IN (229,262,297,300,371,916) THEN 'DENIED_PERMISSION'
                                         WHEN ERROR_NUMBER() = 1222 THEN 'TIMEOUT' ELSE 'ERROR_HANDLED' END
                WHERE [DatabaseId] = @DbId;
                INSERT [#CurrentLog_Errors] VALUES(@DbName, 'LOG_SPACE',
                    CASE WHEN ERROR_NUMBER() IN (229,262,297,300,371,916) THEN 'DENIED_PERMISSION'
                         WHEN ERROR_NUMBER() = 1222 THEN 'TIMEOUT' ELSE 'ERROR_HANDLED' END,
                    ERROR_NUMBER(), ERROR_MESSAGE());
                SET @IsPartial = 1;
            END CATCH;

            BEGIN TRY
                SET @ActiveVlf = NULL; SET @TotalVlf = NULL; SET @Holdup = NULL;
                SET @Backup = NULL; SET @Recovery = NULL;
                SET @Sql = N'USE ' + QUOTENAME(@DbName) + N';
SELECT
      @ActiveVlf = [active_vlf_count]
    , @TotalVlf = [total_vlf_count]
    , @Holdup = [log_truncation_holdup_reason]
    , @Backup = [log_backup_time]
    , @Recovery = CONVERT(decimal(19,2), [log_recovery_size_mb])
FROM [sys].[dm_db_log_stats](DB_ID());';
                EXEC [sys].[sp_executesql] @Sql,
                    N'@ActiveVlf bigint OUTPUT,@TotalVlf bigint OUTPUT,@Holdup nvarchar(60) OUTPUT,@Backup datetime OUTPUT,@Recovery decimal(19,2) OUTPUT',
                    @ActiveVlf OUTPUT, @TotalVlf OUTPUT, @Holdup OUTPUT, @Backup OUTPUT, @Recovery OUTPUT;
                UPDATE [#CurrentLog_Result]
                SET [ActiveVlfCount] = @ActiveVlf, [TotalVlfCount] = @TotalVlf,
                    [LogTruncationHoldupReason] = @Holdup, [LogBackupTime] = @Backup,
                    [LogRecoverySizeMb] = @Recovery, [StatsStatus] = 'AVAILABLE'
                WHERE [DatabaseId] = @DbId;
            END TRY
            BEGIN CATCH
                UPDATE [#CurrentLog_Result]
                SET [StatsStatus] = CASE WHEN ERROR_NUMBER() IN (229,262,297,300,371,916) THEN 'DENIED_PERMISSION'
                                         WHEN ERROR_NUMBER() = 1222 THEN 'TIMEOUT' ELSE 'ERROR_HANDLED' END
                WHERE [DatabaseId] = @DbId;
                INSERT [#CurrentLog_Errors] VALUES(@DbName, 'LOG_STATS',
                    CASE WHEN ERROR_NUMBER() IN (229,262,297,300,371,916) THEN 'DENIED_PERMISSION'
                         WHEN ERROR_NUMBER() = 1222 THEN 'TIMEOUT' ELSE 'ERROR_HANDLED' END,
                    ERROR_NUMBER(), ERROR_MESSAGE());
                SET @IsPartial = 1;
            END CATCH;

            IF @MitVlfInformationen = 1 AND @VlfAllowed = 1
            BEGIN
                BEGIN TRY
                    SET @Cnt = NULL;
                    SET @Sql = N'USE ' + QUOTENAME(@DbName) + N';
SELECT @Cnt = COUNT_BIG(*) FROM [sys].[dm_db_log_info](DB_ID());';
                    EXEC [sys].[sp_executesql] @Sql, N'@Cnt bigint OUTPUT', @Cnt OUTPUT;
                    UPDATE [#CurrentLog_Result]
                    SET [TotalVlfCount] = COALESCE([TotalVlfCount], @Cnt), [VlfStatus] = 'AVAILABLE'
                    WHERE [DatabaseId] = @DbId;
                END TRY
                BEGIN CATCH
                    UPDATE [#CurrentLog_Result]
                    SET [VlfStatus] = CASE WHEN ERROR_NUMBER() IN (229,262,297,300,371,916) THEN 'DENIED_PERMISSION'
                                           WHEN ERROR_NUMBER() = 1222 THEN 'TIMEOUT' ELSE 'ERROR_HANDLED' END
                    WHERE [DatabaseId] = @DbId;
                    INSERT [#CurrentLog_Errors] VALUES(@DbName, 'LOG_INFO',
                        CASE WHEN ERROR_NUMBER() IN (229,262,297,300,371,916) THEN 'DENIED_PERMISSION'
                             WHEN ERROR_NUMBER() = 1222 THEN 'TIMEOUT' ELSE 'ERROR_HANDLED' END,
                        ERROR_NUMBER(), ERROR_MESSAGE());
                    SET @IsPartial = 1;
                END CATCH;
            END;

            FETCH NEXT FROM [DatabaseCursor] INTO @DbId, @DbName;
        END;

        CLOSE [DatabaseCursor];
        DEALLOCATE [DatabaseCursor];

        IF @MitPersistentVersionStore = 1
        BEGIN
            BEGIN TRY
                ;WITH [Pvs] AS
                (
                    SELECT [database_id], SUM([persistent_version_store_size_kb]) AS [PersistentVersionStoreSizeKb]
                    FROM [sys].[dm_tran_persistent_version_store_stats] WITH (NOLOCK)
                    GROUP BY [database_id]
                )
                UPDATE [r]
                SET [PersistentVersionStoreMb] = CONVERT(decimal(19,2), COALESCE([p].[PersistentVersionStoreSizeKb], 0) / 1024.0),
                    [PvsStatus] = 'AVAILABLE'
                FROM [#CurrentLog_Result] AS [r]
                LEFT JOIN [Pvs] AS [p] ON [p].[database_id] = [r].[DatabaseId]
                WHERE [r].[IsAdrEnabled] = 1;

                UPDATE [#CurrentLog_Result]
                SET [PvsStatus] = 'NOT_APPLICABLE'
                WHERE [IsAdrEnabled] = 0 AND [PvsStatus] = 'PENDING';
            END TRY
            BEGIN CATCH
                INSERT [#CurrentLog_Errors] VALUES(NULL, 'ADR_PVS',
                    CASE WHEN ERROR_NUMBER() IN (229,262,297,300,371,916) THEN 'DENIED_PERMISSION' ELSE 'ERROR_HANDLED' END,
                    ERROR_NUMBER(), ERROR_MESSAGE());
                UPDATE [#CurrentLog_Result]
                SET [PvsStatus] = CASE WHEN ERROR_NUMBER() IN (229,262,297,300,371,916) THEN 'DENIED_PERMISSION' ELSE 'ERROR_HANDLED' END
                WHERE [PvsStatus] = 'PENDING';
                SET @IsPartial = 1;
            END CATCH;
        END;

        DELETE FROM [#CurrentLog_Result]
        WHERE @MinUsedPercent IS NOT NULL
          AND COALESCE([UsedLogPercent], -1) < @MinUsedPercent;

        SELECT @CandidateRowCount = COUNT_BIG(*) FROM [#CurrentLog_Result];
        SET @HasMoreRows = CONVERT(bit, CASE WHEN @CandidateRowCount > @EffectiveMaxZeilen THEN 1 ELSE 0 END);
        SET @RowCount = CASE WHEN @CandidateRowCount > @EffectiveMaxZeilen THEN @EffectiveMaxZeilen ELSE @CandidateRowCount END;

        IF EXISTS(SELECT 1 FROM [#CurrentLog_Errors]) OR EXISTS(SELECT 1 FROM [#CurrentLog_DatabaseCandidateWarnings]) OR @VlfStatus = 'DENIED_GROUP'
        BEGIN
            SET @StatusCode = CASE WHEN @RowCount > 0 THEN 'PARTIAL_RESULT' ELSE 'ERROR_HANDLED' END;
            SET @IsPartial = 1;
        END;

        SET @Detail = CONCAT
        (
              N'Datenbanken=', (SELECT COUNT(*) FROM [#CurrentLog_DatabaseCandidates])
            , N'; Ergebniszeilen=', @RowCount
            , N'; Fehler=', (SELECT COUNT(*) FROM [#CurrentLog_Errors])
            , N'; nicht verfügbare explizite Datenbanken=', (SELECT COUNT(*) FROM [#CurrentLog_DatabaseCandidateWarnings])
            , N'; VLF=', CASE WHEN @MitVlfInformationen = 0 THEN N'aus' ELSE @VlfStatus END
            , N'.'
        );
    END;

    IF @StatusCode <> 'AVAILABLE' AND @PrintMeldungen = 1
    BEGIN
        SET @MonitorPrintMessage = FORMATMESSAGE(N'WARNUNG USP_CurrentLog %s: %s', @StatusCode, COALESCE(@ErrorMessage, @Detail));
        RAISERROR(N'%s', 10, 1, @MonitorPrintMessage) WITH NOWAIT;
    END;

    IF @JsonErzeugen = 1
    BEGIN
        DECLARE @JsonMeta nvarchar(max) =
        (
            SELECT
                  N'CurrentLog' AS [resultName]
                , 1 AS [schemaVersion]
                , @CollectionTimeUtc AS [generatedAtUtc]
                , @StatusCode AS [statusCode]
                , @IsPartial AS [isPartial]
                , @MaxZeilen AS [requestedMaxRows]
                , @RowCount AS [returnedRows]
                , @HasMoreRows AS [resultLimited]
                , @HasMoreRows AS [hasMoreRows]
                , @RequiredPermission AS [requiredPermission]
                , @ErrorNumber AS [errorNumber]
                , @ErrorMessage AS [errorMessage]
                , @Detail AS [detail]
            FOR JSON PATH, WITHOUT_ARRAY_WRAPPER, INCLUDE_NULL_VALUES
        );
        DECLARE @JsonLogs nvarchar(max) =
        (
            SELECT TOP (@EffectiveMaxZeilen) [r].*
            FROM [#CurrentLog_Result] AS [r]
            ORDER BY [r].[UsedLogPercent] DESC, [r].[DatabaseName]
            FOR JSON PATH, INCLUDE_NULL_VALUES
        );
        DECLARE @JsonStatus nvarchar(max) =
        (
            SELECT [DatabaseName], [SubModule], [StatusCode], [ErrorNumber], [ErrorMessage]
            FROM [#CurrentLog_Errors]
            ORDER BY [DatabaseName], [SubModule]
            FOR JSON PATH, INCLUDE_NULL_VALUES
        );
        DECLARE @JsonWarnings nvarchar(max) =
        (
            SELECT [RequestedName] AS [databaseName], [StatusCode] AS [code], [ErrorMessage] AS [message]
            FROM [#CurrentLog_DatabaseCandidateWarnings]
            ORDER BY [RequestedName]
            FOR JSON PATH, INCLUDE_NULL_VALUES
        );
        SET @Json = CONCAT
        (
              N'{"meta":', COALESCE(@JsonMeta, N'{}')
            , N',"logs":', COALESCE(@JsonLogs, N'[]')
            , N',"databaseStatus":', COALESCE(@JsonStatus, N'[]')
            , N',"warnings":', COALESCE(@JsonWarnings, N'[]')
            , N'}'
        );
    END;

    IF @ResultSetArtNormalisiert = 'RAW'
    BEGIN
        SELECT
              N'USP_CurrentLog' AS [ModuleName]
            , @CollectionTimeUtc AS [CollectionTimeUtc]
            , @StatusCode AS [StatusCode]
            , @IsPartial AS [IsPartial]
            , @RowCount AS [RowCount]
            , @HasMoreRows AS [ResultLimited]
            , @RequiredPermission AS [RequiredPermission]
            , @ErrorNumber AS [ErrorNumber]
            , @ErrorMessage AS [ErrorMessage]
            , @Detail AS [Detail];

        SELECT TOP (@EffectiveMaxZeilen) [r].*
        FROM [#CurrentLog_Result] AS [r]
        ORDER BY [r].[UsedLogPercent] DESC, [r].[DatabaseName];

        SELECT [DatabaseName], [SubModule], [StatusCode], [ErrorNumber], [ErrorMessage]
        FROM [#CurrentLog_Errors]
        ORDER BY [DatabaseName], [SubModule];
    END
    ELSE IF @ResultSetArtNormalisiert = 'CONSOLE'
    BEGIN
        SELECT
              N'Transaktionslog-Analyse' AS [Ergebnis]
            , @CollectionTimeUtc AS [Stand_UTC]
            , @StatusCode AS [Status]
            , @RowCount AS [Zeilen]
            , @HasMoreRows AS [Ergebnis_begrenzt]
            , @Detail AS [Hinweis];

        SELECT TOP (@EffectiveMaxZeilen)
              N'Transaktionslog' AS [Ergebnis]
            , [r].[DatabaseName] AS [Datenbank]
            , [r].[RecoveryModel] AS [Recovery_Model]
            , [r].[LogReuseWaitDesc] AS [Log_Reuse_Wait]
            , CONCAT(CONVERT(varchar(40), [r].[TotalLogSizeMb]), N' MB') AS [Loggröße]
            , CONCAT(CONVERT(varchar(40), [r].[UsedLogSizeMb]), N' MB') AS [Verwendet]
            , CONCAT(CONVERT(varchar(40), [r].[UsedLogPercent]), N' %') AS [Verwendet_Prozent]
            , [r].[LogTruncationHoldupReason] AS [Truncation_Holdup]
            , [r].[ActiveVlfCount] AS [Aktive_VLF]
            , [r].[TotalVlfCount] AS [VLF_Gesamt]
            , CASE WHEN [r].[PersistentVersionStoreMb] IS NULL THEN NULL
                   ELSE CONCAT(CONVERT(varchar(40), [r].[PersistentVersionStoreMb]), N' MB') END AS [Persistent_Version_Store]
            , [r].[SpaceStatus] AS [Space_Status]
            , [r].[StatsStatus] AS [Stats_Status]
            , [r].[VlfStatus] AS [VLF_Status]
            , [r].[PvsStatus] AS [PVS_Status]
        FROM [#CurrentLog_Result] AS [r]
        ORDER BY [r].[UsedLogPercent] DESC, [r].[DatabaseName];

        SELECT
              N'Datenbank-/Teilmodulwarnung' AS [Ergebnis]
            , [DatabaseName] AS [Datenbank]
            , [SubModule] AS [Teilmodul]
            , [StatusCode] AS [Status]
            , [ErrorNumber] AS [Fehlernummer]
            , [ErrorMessage] AS [Fehlermeldung]
        FROM [#CurrentLog_Errors]
        ORDER BY [DatabaseName], [SubModule];
    END;
    IF @ConsoleResultRequested = 1
    BEGIN
        EXEC [monitor].[InternalEmitConsoleResult]
              @SourceTable=N'#CurrentLog_Result'
            , @ResultLabel=N'Transaktionsprotokolle'
            , @EmptyMessage=N'Keine Protokollergebnisse';
    END;
    IF @TableResultRequested = 1
    BEGIN
        EXEC [monitor].[InternalWriteResultTable]
              @SourceTable = N'#CurrentLog_Result'
            , @TargetTable=@TableTarget
            , @ThrowOnError = 1;
    END;
END;
GO
-- END SOURCE: Code/02_CurrentState/090_USP_CurrentLog.sql

-- BEGIN SOURCE: Code/02_CurrentState/100_USP_CurrentOverview.sql
/*
===============================================================================
Objekt       : monitor.USP_CurrentOverview
Version      : 4.1.0
Stand        : 2026-07-23
Zweck        : Orchestriert jedes aktivierte Current-State-Child genau einmal,
               übernimmt dessen expliziten Status und materialisiert Daten für
               CONSOLE, JSON und benannte TABLE-Exporte ohne erneute Systemlese.
CONSOLE      : SUMMARY ist der Default. RELEVANT und ALL ergänzen ausschließlich
               nicht leere Childdetails; Children erhalten niemals CONSOLE.
TABLE-Namen  : moduleStatus, snapshotStatus, sessions, requests, requestContext,
               statements, batches, inputBuffers, blocking, waits, transactions,
               memoryGrants, tempdbSessions, tempdbGovernance, io, logs und warnings.
===============================================================================
*/
CREATE OR ALTER PROCEDURE [monitor].[USP_CurrentOverview]
      @SessionIds                    nvarchar(max)  = NULL
    , @DatabaseNames                 nvarchar(max)  = NULL
    , @SystemdatenbankenEinbeziehen  bit            = 0
    , @DatabaseNamePattern           nvarchar(4000) = NULL
    , @HighImpactConfirmed              bit            = 0
    , @ToolHintergrundabfragenEinbeziehen bit          = 0
    , @Detailgrad                    varchar(16)     = 'SUMMARY'
    , @MitSessions                   bit             = 1
    , @MitRequests                   bit             = 1
    , @MitBlocking                   bit             = 1
    , @BlockingObjektTiefe           varchar(16)     = 'STANDARD'
    , @MaxObjektAufloesungen         int             = 100
    , @MitWaits                      bit             = 1
    , @MitTransactions               bit             = 1
    , @MitMemoryGrants               bit             = 1
    , @MitTempDB                     bit             = 1
    , @MitIO                         bit             = 1
    , @MitLog                        bit             = 1
    , @MitSqlText                    bit             = 1
    , @GesamtenSqlTextEinbeziehen    bit             = 0
    , @InputBufferEinbeziehen        bit             = 0
    , @ModulInfoEinbeziehen          bit             = 1
    , @MaxSqlTextZeichen             int             = 4000
    , @SampleSeconds                 tinyint         = 0
    , @MaxZeilen                     int             = 500
    , @ResultSetArt                  varchar(16)     = 'CONSOLE'
    , @ResultTablesJson              nvarchar(max)   = NULL
    , @JsonErzeugen                  bit             = 0
    , @Json                          nvarchar(max)   = NULL OUTPUT
    , @PrintMeldungen                bit             = 1
    , @Hilfe                         bit             = 0
AS
BEGIN
    SET NOCOUNT ON;
    DECLARE @OriginalLockTimeout int=@@LOCK_TIMEOUT;
    DECLARE @RestoreLockTimeoutSql nvarchar(100);
    SET LOCK_TIMEOUT 0;
    SET @Json = NULL;

    DECLARE @OutputMode varchar(16)=UPPER(LTRIM(RTRIM(COALESCE(@ResultSetArt,N''))));
    DECLARE @DetailMode varchar(16)=UPPER(LTRIM(RTRIM(COALESCE(@Detailgrad,N''))));
    DECLARE @BlockingObjectDepth varchar(16)=UPPER(LTRIM(RTRIM(COALESCE(@BlockingObjektTiefe,N''))));

    IF @Hilfe = 1
    BEGIN
        PRINT N'monitor.USP_CurrentOverview';
        PRINT N'Ohne Datenbankfilter werden alle sichtbaren, online befindlichen Benutzerdatenbanken berücksichtigt.';
        PRINT N'@ToolHintergrundabfragenEinbeziehen=0 blendet erkannte Tool-Hintergrundaktivität in Sessions, Requests, Blocking-Blättern und aktuellen Waiting Tasks aus; 1 zeigt sie samt Klassifikation.';
        PRINT N'@Detailgrad=SUMMARY (Default)|RELEVANT|ALL. Leere Childdetails erzeugen kein Grid.';
        PRINT N'@BlockingObjektTiefe=NONE|STANDARD|DEEP; DEEP benötigt LOCKS_DEEP und @HighImpactConfirmed=1.';
        PRINT N'@MaxObjektAufloesungen begrenzt die Blocking-Ressourcenauflösung auf 1 bis 1000 Kandidaten.';
        PRINT N'Children werden genau einmal und nie mit CONSOLE aufgerufen.';
        PRINT N'@ResultSetArt=CONSOLE|RAW|TABLE|NONE; TABLE verwendet ausschließlich @ResultTablesJson.';
        PRINT N'TABLE-Namen: moduleStatus, snapshotStatus, sessions, requests, requestContext, statements, batches, inputBuffers, blocking, waits, transactions, memoryGrants, tempdbSessions, tempdbGovernance, io, logs, warnings.';
        SET @RestoreLockTimeoutSql=N'SET LOCK_TIMEOUT '+CONVERT(nvarchar(20),@OriginalLockTimeout)+N';';
        EXEC [sys].[sp_executesql] @RestoreLockTimeoutSql;
        RETURN;
    END;

    DECLARE @StartedAtUtc datetime2(3)=SYSUTCDATETIME();
    DECLARE @StatusCode varchar(40)='AVAILABLE';
    DECLARE @ErrorMessage nvarchar(2048)=NULL;
    DECLARE @ExecutedModules int=0;
    DECLARE @FailedModules int=0;
    DECLARE @PartialModules int=0;
    DECLARE @Message nvarchar(2048);
    DECLARE @ChildJson nvarchar(max);
    DECLARE @ChildStartedAtUtc datetime2(3);
    DECLARE @ChildDurationMs bigint;
    DECLARE @CurrentStateSnapshotId uniqueidentifier=NULL;
    DECLARE @SnapshotConsumerId uniqueidentifier=NULL;
    DECLARE @SnapshotPartial bit=0;
    DECLARE @CaptureSessions bit=0;
    DECLARE @CaptureRequests bit=0;
    DECLARE @CaptureConnections bit=0;
    DECLARE @CaptureWaitingTasks bit=0;
    DECLARE @CaptureMemoryGrants bit=0;
    DECLARE @CaptureResourceGovernor bit=0;
    DECLARE @CaptureTasks bit=0;
    DECLARE @CaptureSchedulers bit=0;
    DECLARE @CaptureTransactions bit=0;
    DECLARE @CaptureTempDbUsage bit=0;
    DECLARE @CaptureSqlText bit=0;
    DECLARE @MaxSqlTextHandles int=0;

    CREATE TABLE [#CurrentOverview_ResultTableMap]
    (
          [ResultName] sysname COLLATE SQL_Latin1_General_CP1_CS_AS NOT NULL PRIMARY KEY
        , [TargetTable] sysname COLLATE SQL_Latin1_General_CP1_CS_AS NOT NULL UNIQUE
    );

    CREATE TABLE [#CurrentOverview_ModulePayload]
    (
          [ModuleOrdinal] int NOT NULL PRIMARY KEY
        , [ResultName] sysname COLLATE SQL_Latin1_General_CP1_CS_AS NOT NULL
        , [ModuleName] sysname COLLATE SQL_Latin1_General_CP1_CS_AS NOT NULL
        , [SourceTable] sysname COLLATE SQL_Latin1_General_CP1_CS_AS NOT NULL
        , [IsEnabled] bit NOT NULL
        , [IsRelevant] bit NOT NULL
        , [IsMaterialized] bit NOT NULL
        , [DurationMs] bigint NOT NULL
        , [JsonValue] nvarchar(max) COLLATE SQL_Latin1_General_CP1_CS_AS NULL
        , [ExecutionError] nvarchar(2048) COLLATE SQL_Latin1_General_CP1_CS_AS NULL
    );

    CREATE TABLE [#CurrentOverview_ModuleStatus]
    (
          [ModuleOrdinal] int NOT NULL
        , [ResultName] sysname COLLATE SQL_Latin1_General_CP1_CS_AS NOT NULL
        , [ModuleName] sysname COLLATE SQL_Latin1_General_CP1_CS_AS NOT NULL
        , [StatusCode] varchar(40) COLLATE SQL_Latin1_General_CP1_CS_AS NOT NULL
        , [IsPartial] bit NOT NULL
        , [ReturnedRowCount] bigint NOT NULL
        , [DurationMs] bigint NOT NULL
        , [ErrorMessage] nvarchar(2048) COLLATE SQL_Latin1_General_CP1_CS_AS NULL
        , PRIMARY KEY ([ModuleOrdinal])
    );

    CREATE TABLE [#CurrentOverview_Warnings]
    (
          [ModuleName] sysname COLLATE SQL_Latin1_General_CP1_CS_AS NOT NULL
        , [StatusCode] varchar(40) COLLATE SQL_Latin1_General_CP1_CS_AS NOT NULL
        , [Message] nvarchar(2048) COLLATE SQL_Latin1_General_CP1_CS_AS NULL
    );

    CREATE TABLE [#CurrentOverview_Sessions]([Seed] bit NULL);
    CREATE TABLE [#CurrentOverview_Requests]([Seed] bit NULL);
    CREATE TABLE [#CurrentOverview_RequestContext]([Seed] bit NULL);
    CREATE TABLE [#CurrentOverview_Statements]([Seed] bit NULL);
    CREATE TABLE [#CurrentOverview_Batches]([Seed] bit NULL);
    CREATE TABLE [#CurrentOverview_InputBuffers]([Seed] bit NULL);
    CREATE TABLE [#CurrentOverview_RequestSnapshotStatus]([Seed] bit NULL);
    CREATE TABLE [#CurrentOverview_Blocking]([Seed] bit NULL);
    CREATE TABLE [#CurrentOverview_Waits]([Seed] bit NULL);
    CREATE TABLE [#CurrentOverview_Transactions]([Seed] bit NULL);
    CREATE TABLE [#CurrentOverview_MemoryGrants]([Seed] bit NULL);
    CREATE TABLE [#CurrentOverview_TempDBSessions]([Seed] bit NULL);
    CREATE TABLE [#CurrentOverview_TempDBGovernance]([Seed] bit NULL);
    CREATE TABLE [#CurrentOverview_IO]([Seed] bit NULL);
    CREATE TABLE [#CurrentOverview_Logs]([Seed] bit NULL);

    CREATE TABLE [#CurrentOverview_SnapshotStatus]
    (
          [SourceOrdinal] int NOT NULL
        , [SnapshotId] uniqueidentifier NOT NULL
        , [SourceCode] varchar(40) COLLATE SQL_Latin1_General_CP1_CS_AS NOT NULL
        , [SourceObject] nvarchar(256) COLLATE SQL_Latin1_General_CP1_CS_AS NOT NULL
        , [CapturedAtUtc] datetime2(3) NOT NULL
        , [CompletedAtUtc] datetime2(3) NOT NULL
        , [StatusCode] varchar(40) COLLATE SQL_Latin1_General_CP1_CS_AS NOT NULL
        , [IsPartial] bit NOT NULL
        , [CapturedRowCount] bigint NOT NULL
        , [ErrorNumber] int NULL
        , [ErrorMessage] nvarchar(2048) COLLATE SQL_Latin1_General_CP1_CS_AS NULL
        , PRIMARY KEY ([SourceOrdinal])
    );

    CREATE TABLE [#CurrentOverview_CurrentStateSnapshot_Context]
    (
          [SnapshotId] uniqueidentifier NOT NULL PRIMARY KEY
        , [OwnerSessionId] smallint NOT NULL
        , [CreatedAtUtc] datetime2(3) NOT NULL
        , [ContractVersion] smallint NOT NULL
    );
    CREATE TABLE [#CurrentOverview_CurrentStateSnapshot_SourceStatus]
    (
          [SnapshotId] uniqueidentifier NOT NULL
        , [SourceOrdinal] int NOT NULL
        , [SourceCode] varchar(40) NOT NULL
        , [SourceObject] nvarchar(256) NOT NULL
        , [CapturedAtUtc] datetime2(3) NOT NULL
        , [CompletedAtUtc] datetime2(3) NOT NULL
        , [StatusCode] varchar(40) NOT NULL
        , [IsPartial] bit NOT NULL
        , [CapturedRowCount] bigint NOT NULL
        , [ErrorNumber] int NULL
        , [ErrorMessage] nvarchar(2048) NULL
        , PRIMARY KEY ([SnapshotId],[SourceCode])
    );
    CREATE TABLE [#CurrentOverview_CurrentStateSnapshot_Sessions]
    (
          [SnapshotId] uniqueidentifier NOT NULL
