        , [internal_objects_dealloc_page_count] bigint NOT NULL
    );
    CREATE TABLE [#CurrentOverview_CurrentStateSnapshot_SqlText]
    (
          [SnapshotId] uniqueidentifier NOT NULL
        , [CapturedAtUtc] datetime2(3) NOT NULL
        , [SqlHandle] varbinary(64) NOT NULL
        , [Text] nvarchar(max) NULL
        , [DatabaseId] int NULL
        , [ObjectId] int NULL
        , [ObjectNumber] smallint NULL
        , [IsEncrypted] bit NULL
        , [EvidenceStatus] varchar(40) NOT NULL
        , PRIMARY KEY ([SnapshotId],[SqlHandle])
    );
    IF @OutputMode NOT IN ('RAW','CONSOLE','TABLE','NONE')
       OR @DetailMode NOT IN ('SUMMARY','RELEVANT','ALL')
       OR @BlockingObjectDepth NOT IN ('NONE','STANDARD','DEEP')
       OR @MaxObjektAufloesungen IS NULL OR @MaxObjektAufloesungen NOT BETWEEN 1 AND 1000
       OR @SampleSeconds > 60
       OR @MaxZeilen < 0
       OR @MaxSqlTextZeichen < 0
       OR @JsonErzeugen IS NULL OR @JsonErzeugen NOT IN (0,1)
       OR @SystemdatenbankenEinbeziehen IS NULL OR @SystemdatenbankenEinbeziehen NOT IN (0,1)
       OR @MitSessions IS NULL OR @MitSessions NOT IN (0,1)
       OR @MitRequests IS NULL OR @MitRequests NOT IN (0,1)
       OR @MitBlocking IS NULL OR @MitBlocking NOT IN (0,1)
       OR @MitWaits IS NULL OR @MitWaits NOT IN (0,1)
       OR @MitTransactions IS NULL OR @MitTransactions NOT IN (0,1)
       OR @MitMemoryGrants IS NULL OR @MitMemoryGrants NOT IN (0,1)
       OR @MitTempDB IS NULL OR @MitTempDB NOT IN (0,1)
       OR @MitIO IS NULL OR @MitIO NOT IN (0,1)
       OR @MitLog IS NULL OR @MitLog NOT IN (0,1)
       OR @MitSqlText IS NULL OR @MitSqlText NOT IN (0,1)
       OR @HighImpactConfirmed IS NULL OR @HighImpactConfirmed NOT IN (0,1)
       OR @ToolHintergrundabfragenEinbeziehen IS NULL OR @ToolHintergrundabfragenEinbeziehen NOT IN (0,1)
       OR @GesamtenSqlTextEinbeziehen IS NULL OR @GesamtenSqlTextEinbeziehen NOT IN (0,1)
       OR @InputBufferEinbeziehen IS NULL OR @InputBufferEinbeziehen NOT IN (0,1)
       OR @ModulInfoEinbeziehen IS NULL OR @ModulInfoEinbeziehen NOT IN (0,1)
       OR (@OutputMode<>'TABLE' AND NULLIF(LTRIM(RTRIM(COALESCE(@ResultTablesJson,N''))),N'') IS NOT NULL)
    BEGIN
        SET @StatusCode='INVALID_PARAMETER';
        SET @ErrorMessage=N'Mindestens ein Parameter besitzt einen ungültigen Wert.';
    END;

    IF @StatusCode='AVAILABLE' AND @OutputMode='TABLE'
    BEGIN
        EXEC [monitor].[InternalPrepareResultTables]
              @ResultTablesJson=@ResultTablesJson
            , @AllowedResultNames=N'moduleStatus|snapshotStatus|sessions|requests|requestContext|statements|batches|inputBuffers|blocking|waits|transactions|memoryGrants|tempdbSessions|tempdbGovernance|io|logs|warnings'
            , @MappingTable=N'#CurrentOverview_ResultTableMap'
            , @StatusCode=@StatusCode OUTPUT
            , @ErrorMessage=@ErrorMessage OUTPUT
            , @ThrowOnError=1;
    END;

    IF @StatusCode<>'AVAILABLE'
    BEGIN
        INSERT [#CurrentOverview_ModuleStatus]
        VALUES(0,N'moduleStatus',N'USP_CurrentOverview',@StatusCode,1,0,0,@ErrorMessage);
        GOTO BuildOutputs;
    END;

    SET @CaptureSessions=CASE WHEN @MitSessions=1 OR @MitRequests=1 OR @MitBlocking=1
        OR @MitWaits=1 OR @MitTransactions=1 OR @MitMemoryGrants=1 OR @MitTempDB=1 THEN 1 ELSE 0 END;
    SET @CaptureRequests=CASE WHEN @MitSessions=1 OR @MitRequests=1 OR @MitBlocking=1
        OR @MitWaits=1 OR @MitTransactions=1 OR @MitMemoryGrants=1 OR @MitIO=1 THEN 1 ELSE 0 END;
    SET @CaptureConnections=CASE WHEN @MitSessions=1 OR @MitRequests=1 OR @MitBlocking=1 THEN 1 ELSE 0 END;
    SET @CaptureWaitingTasks=CASE WHEN @MitRequests=1 OR @MitBlocking=1 OR @MitWaits=1 OR @MitIO=1 THEN 1 ELSE 0 END;
    SET @CaptureMemoryGrants=CASE WHEN @MitRequests=1 OR @MitMemoryGrants=1 THEN 1 ELSE 0 END;
    SET @CaptureResourceGovernor=CASE WHEN @MitRequests=1 OR @MitMemoryGrants=1 OR @MitTempDB=1 THEN 1 ELSE 0 END;
    SET @CaptureTasks=CASE WHEN @MitRequests=1 OR @MitIO=1 THEN 1 ELSE 0 END;
    SET @CaptureSchedulers=CASE WHEN @MitRequests=1 OR @MitIO=1 THEN 1 ELSE 0 END;
    SET @CaptureTransactions=CASE WHEN @MitRequests=1 OR @MitTransactions=1 THEN 1 ELSE 0 END;
    SET @CaptureTempDbUsage=CASE WHEN @MitRequests=1 OR @MitTempDB=1 THEN 1 ELSE 0 END;
    SET @CaptureSqlText=CASE
        WHEN @MitSessions=1 AND @MitSqlText=1 THEN 1
        WHEN @MitRequests=1 AND (@MitSqlText=1 OR @GesamtenSqlTextEinbeziehen=1 OR @ModulInfoEinbeziehen=1) THEN 1
        WHEN @MitBlocking=1 AND @MitSqlText=1 THEN 1
        WHEN @MitWaits=1 AND @MitSqlText=1 THEN 1
        WHEN @MitTransactions=1 AND @MitSqlText=1 THEN 1
        WHEN @MitMemoryGrants=1 AND @MitSqlText=1 THEN 1
        ELSE 0 END;
    SET @MaxSqlTextHandles=CASE
        WHEN @MaxZeilen IS NULL OR @MaxZeilen=0 THEN 0
        WHEN @MaxZeilen>=1073741800 THEN 2147483647
        ELSE @MaxZeilen*2+32 END;

    IF @CaptureSessions=1 OR @CaptureRequests=1 OR @CaptureWaitingTasks=1
       OR @CaptureMemoryGrants=1 OR @CaptureTasks=1 OR @CaptureTransactions=1
       OR @CaptureTempDbUsage=1
    BEGIN
        SET @CurrentStateSnapshotId=NEWID();
        BEGIN TRY
            EXEC [monitor].[InternalCaptureCurrentStateSnapshot]
                  @SnapshotId=@CurrentStateSnapshotId
                , @CaptureSessions=@CaptureSessions
                , @CaptureRequests=@CaptureRequests
                , @CaptureConnections=@CaptureConnections
                , @CaptureWaitingTasks=@CaptureWaitingTasks
                , @CaptureMemoryGrants=@CaptureMemoryGrants
                , @CaptureResourceGovernor=@CaptureResourceGovernor
                , @CaptureTasks=@CaptureTasks
                , @CaptureSchedulers=@CaptureSchedulers
                , @CaptureTransactions=@CaptureTransactions
                , @CaptureTempDbUsage=@CaptureTempDbUsage
                , @CaptureSqlText=@CaptureSqlText
                , @MaxSqlTextHandles=@MaxSqlTextHandles;

            INSERT [#CurrentOverview_SnapshotStatus]
            (
                  [SourceOrdinal],[SnapshotId],[SourceCode],[SourceObject],[CapturedAtUtc]
                , [CompletedAtUtc],[StatusCode],[IsPartial],[CapturedRowCount]
                , [ErrorNumber],[ErrorMessage]
            )
            SELECT
                  [SourceOrdinal],@CurrentStateSnapshotId,[SourceCode],[SourceObject],[CapturedAtUtc]
                , [CompletedAtUtc],[StatusCode],[IsPartial],[CapturedRowCount]
                , [ErrorNumber],[ErrorMessage]
            FROM [#CurrentOverview_CurrentStateSnapshot_SourceStatus]
            WHERE [SnapshotId]=@CurrentStateSnapshotId;

            SET @SnapshotConsumerId=@CurrentStateSnapshotId;
        END TRY
        BEGIN CATCH
            INSERT [#CurrentOverview_SnapshotStatus]
            VALUES
            (
                  0,@CurrentStateSnapshotId,'SNAPSHOT_OWNER',N'monitor.InternalCaptureCurrentStateSnapshot'
                , @StartedAtUtc,SYSUTCDATETIME(),'ERROR_HANDLED',1,0
                , ERROR_NUMBER(),ERROR_MESSAGE()
            );
            SET @SnapshotConsumerId=NULL;
        END CATCH;
    END;

    SET @SnapshotPartial=CASE WHEN EXISTS
    (
        SELECT 1
        FROM [#CurrentOverview_SnapshotStatus]
        WHERE [IsPartial]=1 OR [StatusCode] NOT IN ('AVAILABLE')
    ) THEN 1 ELSE 0 END;

    /* Sessions */
    SET @ChildJson=NULL;SET @ChildStartedAtUtc=SYSUTCDATETIME();
    IF @MitSessions=1
    BEGIN
        SET @ExecutedModules+=1;
        BEGIN TRY
            EXEC [monitor].[USP_CurrentSessions]
                  @SessionIds=@SessionIds
                , @ToolHintergrundabfragenEinbeziehen=@ToolHintergrundabfragenEinbeziehen
                , @MitSqlText=@MitSqlText
                , @MaxSqlTextZeichen=@MaxSqlTextZeichen
                , @MaxZeilen=@MaxZeilen
                , @ResultSetArt='TABLE'
                , @ResultTablesJson=N'{"sessions":"#CurrentOverview_Sessions"}'
                , @JsonErzeugen=1
                , @Json=@ChildJson OUTPUT
                , @PrintMeldungen=@PrintMeldungen
                , @ParentCurrentStateSnapshotId=@SnapshotConsumerId;
            SET @ChildDurationMs=DATEDIFF_BIG(MILLISECOND,@ChildStartedAtUtc,SYSUTCDATETIME());
            INSERT [#CurrentOverview_ModulePayload] VALUES(10,N'sessions',N'USP_CurrentSessions',N'#CurrentOverview_Sessions',1,0,1,@ChildDurationMs,@ChildJson,NULL);
        END TRY
        BEGIN CATCH
            SET @ChildDurationMs=DATEDIFF_BIG(MILLISECOND,@ChildStartedAtUtc,SYSUTCDATETIME());
            INSERT [#CurrentOverview_ModulePayload] VALUES(10,N'sessions',N'USP_CurrentSessions',N'#CurrentOverview_Sessions',1,0,0,@ChildDurationMs,@ChildJson,ERROR_MESSAGE());
        END CATCH;
    END
    ELSE INSERT [#CurrentOverview_ModulePayload] VALUES(10,N'sessions',N'USP_CurrentSessions',N'#CurrentOverview_Sessions',0,0,0,0,NULL,NULL);

    /* Requests */
    SET @ChildJson=NULL;SET @ChildStartedAtUtc=SYSUTCDATETIME();
    IF @MitRequests=1
    BEGIN
        SET @ExecutedModules+=1;
        BEGIN TRY
            EXEC [monitor].[USP_CurrentRequests]
                  @SessionIds=@SessionIds
                , @ToolHintergrundabfragenEinbeziehen=@ToolHintergrundabfragenEinbeziehen
                , @MitSqlText=@MitSqlText
                , @GesamtenSqlTextEinbeziehen=@GesamtenSqlTextEinbeziehen
                , @InputBufferEinbeziehen=@InputBufferEinbeziehen
                , @ModulInfoEinbeziehen=@ModulInfoEinbeziehen
                , @MaxSqlTextZeichen=@MaxSqlTextZeichen
                , @MaxZeilen=@MaxZeilen
                , @ResultSetArt='TABLE'
                , @ResultTablesJson=N'{
                      "requests":"#CurrentOverview_Requests",
                      "requestContext":"#CurrentOverview_RequestContext",
                      "snapshotStatus":"#CurrentOverview_RequestSnapshotStatus",
                      "statements":"#CurrentOverview_Statements",
                      "batches":"#CurrentOverview_Batches",
                      "inputBuffers":"#CurrentOverview_InputBuffers"
                  }'
                , @JsonErzeugen=1
                , @Json=@ChildJson OUTPUT
                , @PrintMeldungen=@PrintMeldungen
                , @ParentCurrentStateSnapshotId=@SnapshotConsumerId;

            INSERT [#CurrentOverview_SnapshotStatus]
            (
                  [SourceOrdinal],[SnapshotId],[SourceCode],[SourceObject],[CapturedAtUtc]
                , [CompletedAtUtc],[StatusCode],[IsPartial],[CapturedRowCount]
                , [ErrorNumber],[ErrorMessage]
            )
            SELECT
                  [r].[SourceOrdinal],[r].[SnapshotId],[r].[SourceCode],[r].[SourceObject]
                , [r].[CapturedAtUtc],[r].[CompletedAtUtc],[r].[StatusCode],[r].[IsPartial]
                , [r].[CapturedRowCount],[r].[ErrorNumber],[r].[ErrorMessage]
            FROM [#CurrentOverview_RequestSnapshotStatus] AS [r]
            WHERE NOT EXISTS
            (
                SELECT 1
                FROM [#CurrentOverview_SnapshotStatus] AS [s]
                WHERE [s].[SourceCode]=[r].[SourceCode]
            );
            SET @ChildDurationMs=DATEDIFF_BIG(MILLISECOND,@ChildStartedAtUtc,SYSUTCDATETIME());
            INSERT [#CurrentOverview_ModulePayload] VALUES(20,N'requests',N'USP_CurrentRequests',N'#CurrentOverview_Requests',1,1,1,@ChildDurationMs,@ChildJson,NULL);
        END TRY
        BEGIN CATCH
            SET @ChildDurationMs=DATEDIFF_BIG(MILLISECOND,@ChildStartedAtUtc,SYSUTCDATETIME());
            INSERT [#CurrentOverview_ModulePayload] VALUES(20,N'requests',N'USP_CurrentRequests',N'#CurrentOverview_Requests',1,1,0,@ChildDurationMs,@ChildJson,ERROR_MESSAGE());
        END CATCH;
    END
    ELSE INSERT [#CurrentOverview_ModulePayload] VALUES(20,N'requests',N'USP_CurrentRequests',N'#CurrentOverview_Requests',0,1,0,0,NULL,NULL);

    /* Blocking */
    SET @ChildJson=NULL;SET @ChildStartedAtUtc=SYSUTCDATETIME();
    IF @MitBlocking=1
    BEGIN
        SET @ExecutedModules+=1;
        BEGIN TRY
            EXEC [monitor].[USP_CurrentBlocking]
                  @SessionIds=@SessionIds
                , @ToolHintergrundabfragenEinbeziehen=@ToolHintergrundabfragenEinbeziehen
                , @MitSqlText=@MitSqlText
                , @MaxSqlTextZeichen=@MaxSqlTextZeichen
                , @BlockingObjektTiefe=@BlockingObjectDepth
                , @MaxObjektAufloesungen=@MaxObjektAufloesungen
                , @HighImpactConfirmed=@HighImpactConfirmed
                , @MaxZeilen=@MaxZeilen
                , @ResultSetArt='TABLE'
                , @ResultTablesJson=N'{"blockingChains":"#CurrentOverview_Blocking"}'
                , @JsonErzeugen=1
                , @Json=@ChildJson OUTPUT
                , @PrintMeldungen=@PrintMeldungen
                , @ParentCurrentStateSnapshotId=@SnapshotConsumerId;
            SET @ChildDurationMs=DATEDIFF_BIG(MILLISECOND,@ChildStartedAtUtc,SYSUTCDATETIME());
            INSERT [#CurrentOverview_ModulePayload] VALUES(30,N'blocking',N'USP_CurrentBlocking',N'#CurrentOverview_Blocking',1,1,1,@ChildDurationMs,@ChildJson,NULL);
        END TRY
        BEGIN CATCH
            SET @ChildDurationMs=DATEDIFF_BIG(MILLISECOND,@ChildStartedAtUtc,SYSUTCDATETIME());
            INSERT [#CurrentOverview_ModulePayload] VALUES(30,N'blocking',N'USP_CurrentBlocking',N'#CurrentOverview_Blocking',1,1,0,@ChildDurationMs,@ChildJson,ERROR_MESSAGE());
        END CATCH;
    END
    ELSE INSERT [#CurrentOverview_ModulePayload] VALUES(30,N'blocking',N'USP_CurrentBlocking',N'#CurrentOverview_Blocking',0,1,0,0,NULL,NULL);

    /* Waits */
    SET @ChildJson=NULL;SET @ChildStartedAtUtc=SYSUTCDATETIME();
    IF @MitWaits=1
    BEGIN
        SET @ExecutedModules+=1;
        BEGIN TRY
            EXEC [monitor].[USP_CurrentWaits]
                  @SessionIds=@SessionIds
                , @ToolHintergrundabfragenEinbeziehen=@ToolHintergrundabfragenEinbeziehen
                , @MitSqlText=@MitSqlText
                , @MaxSqlTextZeichen=@MaxSqlTextZeichen
                , @SampleSeconds=@SampleSeconds
                , @MaxZeilen=@MaxZeilen
                , @ResultSetArt='TABLE'
                , @ResultTablesJson=N'{"currentTasks":"#CurrentOverview_Waits"}'
                , @JsonErzeugen=1
                , @Json=@ChildJson OUTPUT
                , @PrintMeldungen=@PrintMeldungen
                , @ParentCurrentStateSnapshotId=@SnapshotConsumerId;
            SET @ChildDurationMs=DATEDIFF_BIG(MILLISECOND,@ChildStartedAtUtc,SYSUTCDATETIME());
            INSERT [#CurrentOverview_ModulePayload] VALUES(40,N'waits',N'USP_CurrentWaits',N'#CurrentOverview_Waits',1,1,1,@ChildDurationMs,@ChildJson,NULL);
        END TRY
        BEGIN CATCH
            SET @ChildDurationMs=DATEDIFF_BIG(MILLISECOND,@ChildStartedAtUtc,SYSUTCDATETIME());
            INSERT [#CurrentOverview_ModulePayload] VALUES(40,N'waits',N'USP_CurrentWaits',N'#CurrentOverview_Waits',1,1,0,@ChildDurationMs,@ChildJson,ERROR_MESSAGE());
        END CATCH;
    END
    ELSE INSERT [#CurrentOverview_ModulePayload] VALUES(40,N'waits',N'USP_CurrentWaits',N'#CurrentOverview_Waits',0,1,0,0,NULL,NULL);

    /* Transactions */
    SET @ChildJson=NULL;SET @ChildStartedAtUtc=SYSUTCDATETIME();
    IF @MitTransactions=1
    BEGIN
        SET @ExecutedModules+=1;
        BEGIN TRY
            EXEC [monitor].[USP_CurrentTransactions]
                  @SessionIds=@SessionIds
                , @MitSqlText=@MitSqlText
                , @MaxSqlTextZeichen=@MaxSqlTextZeichen
                , @MaxZeilen=@MaxZeilen
                , @ResultSetArt='TABLE'
                , @ResultTablesJson=N'{"transactions":"#CurrentOverview_Transactions"}'
                , @JsonErzeugen=1
                , @Json=@ChildJson OUTPUT
                , @PrintMeldungen=@PrintMeldungen
                , @ParentCurrentStateSnapshotId=@SnapshotConsumerId;
            SET @ChildDurationMs=DATEDIFF_BIG(MILLISECOND,@ChildStartedAtUtc,SYSUTCDATETIME());
            INSERT [#CurrentOverview_ModulePayload] VALUES(50,N'transactions',N'USP_CurrentTransactions',N'#CurrentOverview_Transactions',1,1,1,@ChildDurationMs,@ChildJson,NULL);
        END TRY
        BEGIN CATCH
            SET @ChildDurationMs=DATEDIFF_BIG(MILLISECOND,@ChildStartedAtUtc,SYSUTCDATETIME());
            INSERT [#CurrentOverview_ModulePayload] VALUES(50,N'transactions',N'USP_CurrentTransactions',N'#CurrentOverview_Transactions',1,1,0,@ChildDurationMs,@ChildJson,ERROR_MESSAGE());
        END CATCH;
    END
    ELSE INSERT [#CurrentOverview_ModulePayload] VALUES(50,N'transactions',N'USP_CurrentTransactions',N'#CurrentOverview_Transactions',0,1,0,0,NULL,NULL);

    /* Memory grants */
    SET @ChildJson=NULL;SET @ChildStartedAtUtc=SYSUTCDATETIME();
    IF @MitMemoryGrants=1
    BEGIN
        SET @ExecutedModules+=1;
        BEGIN TRY
            EXEC [monitor].[USP_CurrentMemoryGrants]
                  @SessionIds=@SessionIds
                , @MitSqlText=@MitSqlText
                , @MaxSqlTextZeichen=@MaxSqlTextZeichen
                , @MaxZeilen=@MaxZeilen
                , @ResultSetArt='TABLE'
                , @ResultTablesJson=N'{"memoryGrants":"#CurrentOverview_MemoryGrants"}'
                , @JsonErzeugen=1
                , @Json=@ChildJson OUTPUT
                , @PrintMeldungen=@PrintMeldungen
                , @ParentCurrentStateSnapshotId=@SnapshotConsumerId;
            SET @ChildDurationMs=DATEDIFF_BIG(MILLISECOND,@ChildStartedAtUtc,SYSUTCDATETIME());
            INSERT [#CurrentOverview_ModulePayload] VALUES(60,N'memoryGrants',N'USP_CurrentMemoryGrants',N'#CurrentOverview_MemoryGrants',1,1,1,@ChildDurationMs,@ChildJson,NULL);
        END TRY
        BEGIN CATCH
            SET @ChildDurationMs=DATEDIFF_BIG(MILLISECOND,@ChildStartedAtUtc,SYSUTCDATETIME());
            INSERT [#CurrentOverview_ModulePayload] VALUES(60,N'memoryGrants',N'USP_CurrentMemoryGrants',N'#CurrentOverview_MemoryGrants',1,1,0,@ChildDurationMs,@ChildJson,ERROR_MESSAGE());
        END CATCH;
    END
    ELSE INSERT [#CurrentOverview_ModulePayload] VALUES(60,N'memoryGrants',N'USP_CurrentMemoryGrants',N'#CurrentOverview_MemoryGrants',0,1,0,0,NULL,NULL);

    /* TempDB */
    SET @ChildJson=NULL;SET @ChildStartedAtUtc=SYSUTCDATETIME();
    IF @MitTempDB=1
    BEGIN
        SET @ExecutedModules+=1;
        BEGIN TRY
            EXEC [monitor].[USP_CurrentTempDB]
                  @SessionIds=@SessionIds
                , @MaxZeilen=@MaxZeilen
                , @ResultSetArt='TABLE'
                , @ResultTablesJson=N'{"sessions":"#CurrentOverview_TempDBSessions","tempdbGovernance":"#CurrentOverview_TempDBGovernance"}'
                , @JsonErzeugen=1
                , @Json=@ChildJson OUTPUT
                , @PrintMeldungen=@PrintMeldungen
                , @ParentCurrentStateSnapshotId=@SnapshotConsumerId;
            SET @ChildDurationMs=DATEDIFF_BIG(MILLISECOND,@ChildStartedAtUtc,SYSUTCDATETIME());
            INSERT [#CurrentOverview_ModulePayload] VALUES(70,N'tempdbSessions',N'USP_CurrentTempDB',N'#CurrentOverview_TempDBSessions',1,1,1,@ChildDurationMs,@ChildJson,NULL);
        END TRY
        BEGIN CATCH
            SET @ChildDurationMs=DATEDIFF_BIG(MILLISECOND,@ChildStartedAtUtc,SYSUTCDATETIME());
            INSERT [#CurrentOverview_ModulePayload] VALUES(70,N'tempdbSessions',N'USP_CurrentTempDB',N'#CurrentOverview_TempDBSessions',1,1,0,@ChildDurationMs,@ChildJson,ERROR_MESSAGE());
        END CATCH;
    END
    ELSE INSERT [#CurrentOverview_ModulePayload] VALUES(70,N'tempdbSessions',N'USP_CurrentTempDB',N'#CurrentOverview_TempDBSessions',0,1,0,0,NULL,NULL);

    /* I/O */
    SET @ChildJson=NULL;SET @ChildStartedAtUtc=SYSUTCDATETIME();
    IF @MitIO=1
    BEGIN
        SET @ExecutedModules+=1;
        BEGIN TRY
            EXEC [monitor].[USP_CurrentIO]
                  @DatabaseNames=@DatabaseNames
                , @SystemdatenbankenEinbeziehen=@SystemdatenbankenEinbeziehen
                , @DatabaseNamePattern=@DatabaseNamePattern,@HighImpactConfirmed=@HighImpactConfirmed
                , @SampleSeconds=@SampleSeconds
                , @MaxZeilen=@MaxZeilen
                , @ResultSetArt='TABLE'
                , @ResultTablesJson=N'{"files":"#CurrentOverview_IO"}'
                , @JsonErzeugen=1
                , @Json=@ChildJson OUTPUT
                , @PrintMeldungen=@PrintMeldungen
                , @ParentCurrentStateSnapshotId=@SnapshotConsumerId;
            SET @ChildDurationMs=DATEDIFF_BIG(MILLISECOND,@ChildStartedAtUtc,SYSUTCDATETIME());
            INSERT [#CurrentOverview_ModulePayload] VALUES(80,N'io',N'USP_CurrentIO',N'#CurrentOverview_IO',1,1,1,@ChildDurationMs,@ChildJson,NULL);
        END TRY
        BEGIN CATCH
            SET @ChildDurationMs=DATEDIFF_BIG(MILLISECOND,@ChildStartedAtUtc,SYSUTCDATETIME());
            INSERT [#CurrentOverview_ModulePayload] VALUES(80,N'io',N'USP_CurrentIO',N'#CurrentOverview_IO',1,1,0,@ChildDurationMs,@ChildJson,ERROR_MESSAGE());
        END CATCH;
    END
    ELSE INSERT [#CurrentOverview_ModulePayload] VALUES(80,N'io',N'USP_CurrentIO',N'#CurrentOverview_IO',0,1,0,0,NULL,NULL);

    /* Transaction log */
    SET @ChildJson=NULL;SET @ChildStartedAtUtc=SYSUTCDATETIME();
    IF @MitLog=1
    BEGIN
        SET @ExecutedModules+=1;
        BEGIN TRY
            EXEC [monitor].[USP_CurrentLog]
                  @DatabaseNames=@DatabaseNames
                , @SystemdatenbankenEinbeziehen=@SystemdatenbankenEinbeziehen
                , @DatabaseNamePattern=@DatabaseNamePattern,@HighImpactConfirmed=@HighImpactConfirmed
                , @MaxZeilen=@MaxZeilen
                , @ResultSetArt='TABLE'
                , @ResultTablesJson=N'{"logs":"#CurrentOverview_Logs"}'
                , @JsonErzeugen=1
                , @Json=@ChildJson OUTPUT
                , @PrintMeldungen=@PrintMeldungen;
            SET @ChildDurationMs=DATEDIFF_BIG(MILLISECOND,@ChildStartedAtUtc,SYSUTCDATETIME());
            INSERT [#CurrentOverview_ModulePayload] VALUES(90,N'logs',N'USP_CurrentLog',N'#CurrentOverview_Logs',1,1,1,@ChildDurationMs,@ChildJson,NULL);
        END TRY
        BEGIN CATCH
            SET @ChildDurationMs=DATEDIFF_BIG(MILLISECOND,@ChildStartedAtUtc,SYSUTCDATETIME());
            INSERT [#CurrentOverview_ModulePayload] VALUES(90,N'logs',N'USP_CurrentLog',N'#CurrentOverview_Logs',1,1,0,@ChildDurationMs,@ChildJson,ERROR_MESSAGE());
        END CATCH;
    END
    ELSE INSERT [#CurrentOverview_ModulePayload] VALUES(90,N'logs',N'USP_CurrentLog',N'#CurrentOverview_Logs',0,1,0,0,NULL,NULL);

    SET @SnapshotPartial=CASE WHEN EXISTS
    (
        SELECT 1
        FROM [#CurrentOverview_SnapshotStatus]
        WHERE [IsPartial]=1
           OR [StatusCode] NOT IN ('AVAILABLE','NOT_COLLECTED')
    ) THEN 1 ELSE 0 END;

    INSERT [#CurrentOverview_ModuleStatus]
    (
          [ModuleOrdinal],[ResultName],[ModuleName],[StatusCode],[IsPartial]
        , [ReturnedRowCount],[DurationMs],[ErrorMessage]
    )
    SELECT
          [p].[ModuleOrdinal]
        , [p].[ResultName]
        , [p].[ModuleName]
        , [x].[StatusCode]
        , CONVERT(bit,CASE
              WHEN [p].[IsEnabled]=0 THEN 0
              WHEN [x].[StatusCode]='AVAILABLE'
               AND COALESCE(JSON_VALUE([p].[JsonValue],N'$.meta.isPartial'),N'false')=N'false'
                  THEN 0
              ELSE 1 END)
        , [x].[ReturnedRows]
        , [p].[DurationMs]
        , COALESCE([p].[ExecutionError],JSON_VALUE([p].[JsonValue],N'$.warnings[0].message'))
    FROM [#CurrentOverview_ModulePayload] AS [p]
    CROSS APPLY
    (
        SELECT
              [StatusCode]=CONVERT(varchar(40),CASE
                    WHEN [p].[IsEnabled]=0 THEN 'SKIPPED'
                    WHEN [p].[ExecutionError] IS NOT NULL THEN 'ERROR_HANDLED'
                    WHEN ISJSON([p].[JsonValue])<>1 THEN 'STATUS_UNAVAILABLE'
                    WHEN JSON_VALUE([p].[JsonValue],N'$.meta.statusCode') IS NULL THEN 'STATUS_UNAVAILABLE'
                    WHEN COALESCE
                         (
                             TRY_CONVERT(bigint,JSON_VALUE([p].[JsonValue],N'$.meta.returnedRows')),
                             TRY_CONVERT(bigint,JSON_VALUE([p].[JsonValue],N'$.meta.currentTaskRows'))
                         ) IS NULL THEN 'STATUS_UNAVAILABLE'
                    ELSE JSON_VALUE([p].[JsonValue],N'$.meta.statusCode') END)
            , [ReturnedRows]=CONVERT(bigint,CASE
                    WHEN [p].[IsEnabled]=0 THEN 0
                    ELSE COALESCE
                         (
                             TRY_CONVERT(bigint,JSON_VALUE([p].[JsonValue],N'$.meta.returnedRows')),
                             TRY_CONVERT(bigint,JSON_VALUE([p].[JsonValue],N'$.meta.currentTaskRows')),
                             0
                         ) END)
    ) AS [x];

    INSERT [#CurrentOverview_Warnings]([ModuleName],[StatusCode],[Message])
    SELECT [ModuleName],[StatusCode],[ErrorMessage]
    FROM [#CurrentOverview_ModuleStatus]
    WHERE [IsPartial]=1 OR [StatusCode] NOT IN ('AVAILABLE','SKIPPED');

    INSERT [#CurrentOverview_Warnings]([ModuleName],[StatusCode],[Message])
    SELECT
          N'CurrentStateSnapshot'
        , [StatusCode]
        , COALESCE([ErrorMessage],CONCAT(N'Quelle ',[SourceCode],N' wurde nur teilweise materialisiert.'))
    FROM [#CurrentOverview_SnapshotStatus]
    WHERE [IsPartial]=1 OR [StatusCode] NOT IN ('AVAILABLE','NOT_COLLECTED');

    SELECT
          @FailedModules=COALESCE(SUM(CASE WHEN [StatusCode] NOT IN ('AVAILABLE','AVAILABLE_LIMITED','SKIPPED') THEN 1 ELSE 0 END),0)
        , @PartialModules=COALESCE(SUM(CASE WHEN [IsPartial]=1 THEN 1 ELSE 0 END),0)
    FROM [#CurrentOverview_ModuleStatus];

    SET @StatusCode=CASE
        WHEN @ExecutedModules=0 THEN 'AVAILABLE'
        WHEN @FailedModules=0 AND @PartialModules=0 AND @SnapshotPartial=0 THEN 'AVAILABLE'
        WHEN @FailedModules<@ExecutedModules OR @SnapshotPartial=1 THEN 'AVAILABLE_LIMITED'
        ELSE 'ERROR_HANDLED' END;

BuildOutputs:
    IF @PrintMeldungen=1 AND (@FailedModules>0 OR @PartialModules>0)
    BEGIN
        SET @Message=FORMATMESSAGE(N'HINWEIS USP_CurrentOverview: %d Modul(e) fehlgeschlagen, %d Modul(e) partiell; %d aktiviert.',@FailedModules,@PartialModules,@ExecutedModules);
        RAISERROR(N'%s',10,1,@Message) WITH NOWAIT;
    END;

    IF @OutputMode IN ('CONSOLE','RAW')
    BEGIN
        SELECT
              [ModuleName]
            , [StatusCode]
            , [IsPartial]
            , [ReturnedRowCount]
            , [DurationMs]
            , [ErrorMessage]
        FROM [#CurrentOverview_ModuleStatus]
        ORDER BY [ModuleOrdinal];
    END;

    IF @OutputMode='RAW'
    BEGIN
        SELECT
              [SourceOrdinal],[SnapshotId],[SourceCode],[SourceObject],[CapturedAtUtc],[CompletedAtUtc]
            , [StatusCode],[IsPartial],[CapturedRowCount],[ErrorNumber],[ErrorMessage]
        FROM [#CurrentOverview_SnapshotStatus]
        ORDER BY [SourceOrdinal];

        SELECT [ModuleName],[StatusCode],[Message]
        FROM [#CurrentOverview_Warnings]
        ORDER BY [ModuleName];
    END;

    IF @OutputMode='CONSOLE' AND @DetailMode IN ('RELEVANT','ALL')
    BEGIN
        DECLARE @DetailSourceTable sysname;
        DECLARE @DetailSql nvarchar(max);

        DECLARE [DetailCursor] CURSOR LOCAL FAST_FORWARD FOR
            SELECT [p].[SourceTable]
            FROM [#CurrentOverview_ModulePayload] AS [p]
            INNER JOIN [#CurrentOverview_ModuleStatus] AS [s]
              ON [s].[ModuleOrdinal]=[p].[ModuleOrdinal]
            WHERE [p].[IsEnabled]=1
              AND [p].[IsMaterialized]=1
              AND [s].[ReturnedRowCount]>0
              AND [s].[StatusCode] IN ('AVAILABLE','AVAILABLE_LIMITED')
              AND (@DetailMode='ALL' OR [p].[IsRelevant]=1)
            ORDER BY [p].[ModuleOrdinal];

        OPEN [DetailCursor];
        FETCH NEXT FROM [DetailCursor] INTO @DetailSourceTable;
        WHILE @@FETCH_STATUS=0
        BEGIN
            SET @DetailSql=N'SELECT * FROM '+QUOTENAME(@DetailSourceTable)+N';';
            EXEC [sys].[sp_executesql] @DetailSql;
            FETCH NEXT FROM [DetailCursor] INTO @DetailSourceTable;
        END;
        CLOSE [DetailCursor];
        DEALLOCATE [DetailCursor];
    END;

    IF @JsonErzeugen=1
    BEGIN
        DECLARE @MetaJson nvarchar(max)=
        (
            SELECT
                  N'CurrentOverview' AS [resultName]
                , 4 AS [schemaVersion]
                , @StartedAtUtc AS [generatedAtUtc]
                , @StatusCode AS [statusCode]
                , @CurrentStateSnapshotId AS [evidenceSnapshotId]
                , CONVERT(bit,CASE WHEN @PartialModules>0 OR @FailedModules>0 OR @SnapshotPartial=1 THEN 1 ELSE 0 END) AS [isPartial]
                , @ExecutedModules AS [executedModules]
                , @FailedModules AS [failedModules]
                , @PartialModules AS [partialModules]
                , @ToolHintergrundabfragenEinbeziehen AS [toolBackgroundQueriesIncluded]
            FOR JSON PATH,WITHOUT_ARRAY_WRAPPER,INCLUDE_NULL_VALUES
        );
        DECLARE @ModuleStatusJson nvarchar(max)=
        (
            SELECT [ResultName],[ModuleName],[StatusCode],[IsPartial],[ReturnedRowCount],[DurationMs],[ErrorMessage]
            FROM [#CurrentOverview_ModuleStatus]
            ORDER BY [ModuleOrdinal]
            FOR JSON PATH,INCLUDE_NULL_VALUES
        );
        DECLARE @SnapshotStatusJson nvarchar(max)=
        (
            SELECT
                  [SourceOrdinal],[SnapshotId],[SourceCode],[SourceObject],[CapturedAtUtc],[CompletedAtUtc]
                , [StatusCode],[IsPartial],[CapturedRowCount],[ErrorNumber],[ErrorMessage]
            FROM [#CurrentOverview_SnapshotStatus]
            ORDER BY [SourceOrdinal]
            FOR JSON PATH,INCLUDE_NULL_VALUES
        );
        DECLARE @WarningsJson nvarchar(max)=
        (
            SELECT [ModuleName],[StatusCode],[Message]
            FROM [#CurrentOverview_Warnings]
            ORDER BY [ModuleName]
            FOR JSON PATH,INCLUDE_NULL_VALUES
        );
        DECLARE @ChildProperties nvarchar(max)=
        (
            SELECT STRING_AGG
            (
                CONVERT(nvarchar(max),CONCAT
                (
                      N'"'
                    , STRING_ESCAPE([ResultName] COLLATE SQL_Latin1_General_CP1_CS_AS,'json')
                    , N'":'
                    , CASE WHEN ISJSON([JsonValue])=1
                           THEN [JsonValue] COLLATE SQL_Latin1_General_CP1_CS_AS
                           ELSE N'null' END
                )) COLLATE SQL_Latin1_General_CP1_CS_AS,
                N','
            ) WITHIN GROUP (ORDER BY [ModuleOrdinal])
            FROM [#CurrentOverview_ModulePayload]
            WHERE [IsEnabled]=1
        );

        SET @Json=CONCAT
        (
              N'{"meta":',COALESCE(@MetaJson,N'{}')
            , N',"moduleStatus":',COALESCE(@ModuleStatusJson,N'[]')
            , N',"snapshotStatus":',COALESCE(@SnapshotStatusJson,N'[]')
            , CASE WHEN NULLIF(@ChildProperties,N'') IS NULL THEN N'' ELSE N','+@ChildProperties END
            , N',"warnings":',COALESCE(@WarningsJson,N'[]'),N'}'
        );
    END;

    IF @OutputMode='TABLE'
    BEGIN
        DECLARE @ExportResultName sysname;
        DECLARE @ExportTargetTable sysname;
        DECLARE @ExportSourceTable sysname;
        DECLARE @CanExport bit;

        DECLARE [ExportCursor] CURSOR LOCAL FAST_FORWARD FOR
            SELECT [ResultName],[TargetTable]
            FROM [#CurrentOverview_ResultTableMap]
            ORDER BY [ResultName];

        OPEN [ExportCursor];
        FETCH NEXT FROM [ExportCursor] INTO @ExportResultName,@ExportTargetTable;
        WHILE @@FETCH_STATUS=0
        BEGIN
            SELECT
                  @ExportSourceTable=CASE
                      WHEN @ExportResultName=N'moduleStatus' THEN N'#CurrentOverview_ModuleStatus'
                      WHEN @ExportResultName=N'snapshotStatus' THEN N'#CurrentOverview_SnapshotStatus'
                      WHEN @ExportResultName=N'requestContext' THEN N'#CurrentOverview_RequestContext'
                      WHEN @ExportResultName=N'statements' THEN N'#CurrentOverview_Statements'
                      WHEN @ExportResultName=N'batches' THEN N'#CurrentOverview_Batches'
                      WHEN @ExportResultName=N'inputBuffers' THEN N'#CurrentOverview_InputBuffers'
                      WHEN @ExportResultName=N'tempdbGovernance' THEN N'#CurrentOverview_TempDBGovernance'
                      WHEN @ExportResultName=N'warnings' THEN N'#CurrentOverview_Warnings'
                      ELSE NULL END
                , @CanExport=CASE
                    WHEN @ExportResultName=N'tempdbGovernance' THEN @MitTempDB
                    WHEN @ExportResultName IN
                         (N'moduleStatus',N'snapshotStatus',N'requestContext',
                          N'statements',N'batches',N'inputBuffers',N'warnings')
                        THEN 1
                    ELSE 0
                  END;

            IF @ExportSourceTable IS NULL
                SELECT
                      @ExportSourceTable=[SourceTable]
                    , @CanExport=[IsMaterialized]
                FROM [#CurrentOverview_ModulePayload]
                WHERE [ResultName]=@ExportResultName;

            IF @CanExport=1
                EXEC [monitor].[InternalWriteResultTable]
                      @SourceTable=@ExportSourceTable
                    , @TargetTable=@ExportTargetTable
                    , @ThrowOnError=1;

            FETCH NEXT FROM [ExportCursor] INTO @ExportResultName,@ExportTargetTable;
        END;
        CLOSE [ExportCursor];
        DEALLOCATE [ExportCursor];
    END;

    SET @RestoreLockTimeoutSql=N'SET LOCK_TIMEOUT '+CONVERT(nvarchar(20),@OriginalLockTimeout)+N';';
    EXEC [sys].[sp_executesql] @RestoreLockTimeoutSql;
END;
GO
-- END SOURCE: Code/02_CurrentState/100_USP_CurrentOverview.sql

-- BEGIN SOURCE: Code/02_CurrentState/110_USP_CurrentCursorAnalysis.sql
/* OPS-007: bounded, session-scoped cursor evidence; opt-in only. */
CREATE OR ALTER PROCEDURE [monitor].[USP_CurrentCursorAnalysis]
      @IncludeCursorDetails bit            = 0
    , @SessionIds          nvarchar(max)  = NULL
    , @MaxZeilen           int            = 200
    , @ResultSetArt        varchar(16)    = 'CONSOLE'
    , @ResultTablesJson    nvarchar(max)  = NULL
    , @JsonErzeugen        bit            = 0
    , @Json                nvarchar(max)  = NULL OUTPUT
    , @PrintMeldungen      bit            = 1
    , @Hilfe               bit            = 0
    , @StatusCodeOut       varchar(40)    = NULL OUTPUT
    , @IsPartialOut        bit            = NULL OUTPUT
    , @ErrorNumberOut      int            = NULL OUTPUT
    , @ErrorMessageOut     nvarchar(2048) = NULL OUTPUT
AS
BEGIN
 SET NOCOUNT ON; SET @Json=NULL;
 DECLARE @Status varchar(40)='NOT_EXECUTED',@Partial bit=0,@Mode varchar(16)=UPPER(LTRIM(RTRIM(COALESCE(@ResultSetArt,''))));
 DECLARE @ErrorNumber int=NULL,@ErrorMessage nvarchar(2048)=NULL,@TargetSessionId int=@@SPID;
 IF @Hilfe=1 BEGIN PRINT N'monitor.USP_CurrentCursorAnalysis'; PRINT N'Cursor-Details sind opt-in und auf genau eine Session sowie @MaxZeilen begrenzt.'; RETURN; END;
 DECLARE @PreviousLockTimeout int=@@LOCK_TIMEOUT,@RestoreLockTimeoutSql nvarchar(100); SET LOCK_TIMEOUT 0;
 DECLARE @TableResultRequested bit=CASE WHEN @Mode='TABLE' THEN 1 ELSE 0 END,@ConsoleResultRequested bit=CASE WHEN @Mode='CONSOLE' THEN 1 ELSE 0 END,@TableTarget sysname=NULL;
 IF @TableResultRequested=0 AND NULLIF(LTRIM(RTRIM(COALESCE(@ResultTablesJson,N''))),N'') IS NOT NULL THROW 51011,N'@ResultTablesJson ist ausschließlich mit @ResultSetArt=TABLE zulässig.',1;
 IF @TableResultRequested=1 BEGIN EXEC [monitor].[InternalPrepareSingleResultTable] @ResultTablesJson=@ResultTablesJson,@ResultName=N'cursors',@TargetTable=@TableTarget OUTPUT,@ThrowOnError=1; END;
 IF @TableResultRequested=1 OR @ConsoleResultRequested=1 SET @Mode='NONE';
 CREATE TABLE [#CurrentCursorAnalysis_Cursors]
 (
      [SessionId] int
    , [CursorId] int
    , [CursorName] nvarchar(256) COLLATE SQL_Latin1_General_CP1_CS_AS
    , [Properties] nvarchar(256) COLLATE SQL_Latin1_General_CP1_CS_AS
    , [CreationTime] datetime
    , [IsOpen] bit
    , [FetchStatus] int
    , [WorkerTime] bigint
    , [Reads] bigint
    , [Writes] bigint
    , [DormantDuration] bigint
    , [FindingContext] varchar(40) COLLATE SQL_Latin1_General_CP1_CS_AS
 );
 IF NULLIF(LTRIM(RTRIM(COALESCE(@SessionIds,N''))),N'') IS NOT NULL
 BEGIN
   DECLARE @SessionSelection TABLE([NumberValue] bigint NULL,[IsValid] bit NOT NULL);
   INSERT @SessionSelection([NumberValue],[IsValid])
   SELECT [NumberValue],[IsValid] FROM [monitor].[TVF_ParseBigintList](@SessionIds);
   IF (SELECT COUNT_BIG(*) FROM @SessionSelection)<>1
      OR EXISTS(SELECT 1 FROM @SessionSelection WHERE [IsValid]=0 OR [NumberValue] NOT BETWEEN 1 AND 32767)
     SELECT @Status='INVALID_PARAMETER',@Partial=1,@ErrorMessage=N'@SessionIds muss genau eine gültige Session-ID enthalten.';
   ELSE
     SELECT @TargetSessionId=CONVERT(int,[NumberValue]) FROM @SessionSelection;
 END;
 IF @Status='NOT_EXECUTED' AND (@MaxZeilen<0 OR @Mode NOT IN('CONSOLE','RAW','NONE') OR @IncludeCursorDetails IS NULL) SELECT @Status='INVALID_PARAMETER',@Partial=1,@ErrorMessage=N'Ungültiger Parameter.';
 ELSE IF @Status='NOT_EXECUTED' AND @IncludeCursorDetails=1 BEGIN TRY
   INSERT [#CurrentCursorAnalysis_Cursors] SELECT TOP(CASE WHEN @MaxZeilen=0 THEN 2147483647 ELSE @MaxZeilen END) [session_id],[cursor_id],[name],[properties],[creation_time],[is_open],[fetch_status],[worker_time],[reads],[writes],[dormant_duration],CASE WHEN [is_open]=1 AND [dormant_duration]>60000 THEN 'DORMANT_CONTEXT' WHEN [is_open]=1 AND ([worker_time]>0 OR [reads]>0 OR [writes]>0) THEN 'RESOURCE_CONTEXT' ELSE 'INVENTORY_ONLY' END FROM [sys].[dm_exec_cursors](@TargetSessionId) ORDER BY [worker_time] DESC,[reads] DESC,[cursor_id];
   SET @Status=CASE WHEN EXISTS(SELECT 1 FROM [#CurrentCursorAnalysis_Cursors]) THEN 'AVAILABLE' ELSE 'AVAILABLE_EMPTY' END;
 END TRY BEGIN CATCH SELECT @Status=CASE WHEN ERROR_NUMBER() IN (229,297,300,371,916) THEN 'DENIED_PERMISSION' ELSE 'SOURCE_UNAVAILABLE' END,@Partial=1,@ErrorNumber=ERROR_NUMBER(),@ErrorMessage=ERROR_MESSAGE(); END CATCH;
 IF @JsonErzeugen=1 SELECT @Json=COALESCE((SELECT * FROM [#CurrentCursorAnalysis_Cursors] ORDER BY [WorkerTime] DESC,[CursorId] FOR JSON PATH),N'[]');
 IF @Mode IN('CONSOLE','RAW') BEGIN SELECT @Status [StatusCode],@Partial [IsPartial],@TargetSessionId [SessionId],COUNT_BIG(*) [CursorCount],@ErrorMessage [ErrorMessage] FROM [#CurrentCursorAnalysis_Cursors]; IF @IncludeCursorDetails=1 SELECT * FROM [#CurrentCursorAnalysis_Cursors] ORDER BY [WorkerTime] DESC,[CursorId]; END;
 IF @PrintMeldungen=1 AND @Mode='NONE' PRINT CONCAT(N'Status: ',@Status);
 IF @ConsoleResultRequested=1 EXEC [monitor].[InternalEmitConsoleResult] @SourceTable=N'#CurrentCursorAnalysis_Cursors',@ResultLabel=N'cursors',@EmptyMessage=N'Keine sichtbaren Cursor im gewählten Scope';
 IF @TableResultRequested=1 EXEC [monitor].[InternalWriteResultTable] @SourceTable=N'#CurrentCursorAnalysis_Cursors',@TargetTable=@TableTarget,@ThrowOnError=1;
 SET @RestoreLockTimeoutSql=N'SET LOCK_TIMEOUT '+CONVERT(nvarchar(20),@PreviousLockTimeout)+N';'; EXEC [sys].[sp_executesql] @RestoreLockTimeoutSql; SELECT @StatusCodeOut=@Status,@IsPartialOut=@Partial,@ErrorNumberOut=@ErrorNumber,@ErrorMessageOut=@ErrorMessage;
END;
GO
-- END SOURCE: Code/02_CurrentState/110_USP_CurrentCursorAnalysis.sql

-- BEGIN SOURCE: Code/03_ObjectIndex/010_USP_ObjectInventory.sql
/*
===============================================================================
Objekt       : monitor.USP_ObjectInventory
Version      : 1.1.0
Stand        : 2026-07-23
Typ          : Stored Procedure
Zweck        : Liefert ein fehlertolerantes Objekt- und Indexinventar
               einschließlich Größe, Zeilen, Kompression, Partitionierung,
               optionalen Spaltenlisten sowie versionsadaptiven
               SQL-Server-2025-JSON-Index- und Pfadmetadaten.
SQL-Version  : SQL Server 2019 oder neuer.
Datenquellen : master.sys.databases sowie je Zieldatenbank sys.objects,
               sys.tables, sys.schemas, sys.indexes, sys.index_columns,
               sys.columns, sys.partitions, sys.allocation_units,
               sys.data_spaces und capability-abhängig sys.json_indexes
               sowie sys.json_index_paths.
Parameter    :
  @DatabaseName                  sysname        = NULL  - Zieldatenbank; bei Einzelmodus Pflicht.
  @CrossDatabaseRequestedInternal               bit            = 0     - sichtbare Online-Datenbanken analysieren.
  @SystemdatenbankenEinbeziehen  bit            = 0     - master/model/msdb/tempdb einbeziehen.
  @DatenbankNameLike             nvarchar(256)  = NULL  - Filter im Cross-Database-Modus.
  @SchemaNamePattern                nvarchar(256)  = NULL  - LIKE-Filter auf Schema.
  @ObjectNamePattern                nvarchar(256)  = NULL  - LIKE-Filter auf Objekt.
  @MaxZeilen                     int            = 5000  - positive Werte begrenzen; NULL/0 = unbegrenzt.
  @LockTimeoutMs                 int            = 0     - 0 = nicht auf Metadatenlocks warten.
  @PrintMeldungen                bit            = 1     - Warnungen via RAISERROR 10.
  @Hilfe                         bit            = 0     - Hilfe via PRINT, keine Analyse.
  @ObjectType varchar(16) = 'TABLE' - TABLE|VIEW|ALLE.
  @AnalyseModus varchar(16) = 'GEZIELT' - GEZIELT benötigt Filter; VOLL prüft CATALOG_DEEP.
  @MitIndizes bit = 1 - Indexdetails; 0 liefert je Objekt eine Summenzeile.
  @MitSpaltenlisten bit = 1 - Key-/Include-Spaltenlisten erzeugen.
Resultsets   : 1. Modulstatus. 2. Status je Datenbank. 3. Objekt-/Indexinventar.
Berechtigung : Katalogsicht gemäß Metadata Visibility; Cross-Database zusätzlich Gruppenpolicy. Keine Rechtevergabe.
Eigenlast    : Gezielte Einzel-Datenbank-Abfrage gering bis moderat; Cross-Database und Spaltenlisten begrenzt durch TOP.
Locking      : READUNCOMMITTED/NOLOCK auf Systemkatalogen und konfigurierbares
               LOCK_TIMEOUT; der vorherige Sessionwert wird wiederhergestellt.
Partial      : Fehler je Datenbank bzw. Teilquelle werden isoliert; vorhandene
               Teilergebnisse bleiben erhalten. Das Framework vergibt keine Rechte.
Beispiele    :
  EXEC monitor.USP_ObjectInventory @DatabaseNames=N'[SampleDatabase]', @ObjectNamePattern=N'like:Fact%';
  EXEC monitor.USP_ObjectInventory @DatabaseNames=N'[SampleDatabase]', @SchemaNames=N'[dbo]', @ObjectNamePattern=N'like:Fact%';
  EXEC monitor.USP_ObjectInventory @CrossDatabaseRequestedInternal=0, @AnalyseModus='VOLL', @MaxZeilen=20000;
  EXEC monitor.USP_ObjectInventory @Hilfe=1;
Änderungen   : 1.1.0 - SQL25-002: JSON-Indizes und aggregierte SQL/JSON-Pfade
                         ohne Lesen von JSON-Dokumentwerten ergänzt.
               1.0.0 - Erstfassung Phase 2.
===============================================================================
*/
CREATE OR ALTER PROCEDURE [monitor].[USP_ObjectInventory]
      @DatabaseNames                  nvarchar(max)  = NULL
    , @SystemdatenbankenEinbeziehen   bit            = 0
    , @DatabaseNamePattern            nvarchar(4000) = NULL
    , @HighImpactConfirmed              bit            = 0
    , @SchemaNames                    nvarchar(max)  = NULL
    , @SchemaNamePattern              nvarchar(4000) = NULL
    , @ObjectNames                    nvarchar(max)  = NULL
    , @ObjectNamePattern              nvarchar(4000) = NULL
    , @FullObjectNames                nvarchar(max)  = NULL
    , @ObjectType                     varchar(16)   = 'TABLE'
    , @AnalyseModus                   varchar(16)   = 'GEZIELT'
    , @MitIndizes                     bit           = 1
    , @MitSpaltenlisten               bit           = 1
    , @MaxZeilen                      int           = 5000
    , @LockTimeoutMs                  int           = 0
    , @ResultSetArt                  varchar(16)    = 'CONSOLE'
    , @ResultTablesJson               nvarchar(max) = NULL
    , @JsonErzeugen                  bit            = 0
    , @Json                          nvarchar(max)  = NULL OUTPUT
    , @PrintMeldungen                 bit           = 1
    , @Hilfe                          bit           = 0
AS
BEGIN
    SET NOCOUNT ON;

    SET @Json = NULL;
    DECLARE @OriginalLockTimeout int=@@LOCK_TIMEOUT;
    DECLARE @LockTimeoutSql nvarchar(64);
    DECLARE @ResultSetArtNormalisiert varchar(16)=UPPER(LTRIM(RTRIM(COALESCE(@ResultSetArt,''))));
    DECLARE @TableResultRequested bit = CASE WHEN @ResultSetArtNormalisiert = 'TABLE' THEN 1 ELSE 0 END;
    DECLARE @ConsoleResultRequested bit = CASE WHEN @ResultSetArtNormalisiert = 'CONSOLE' THEN 1 ELSE 0 END;
    DECLARE @TableTarget sysname=NULL;
    IF @TableResultRequested=0 AND NULLIF(LTRIM(RTRIM(COALESCE(@ResultTablesJson,N''))),N'') IS NOT NULL THROW 51011,N'@ResultTablesJson ist ausschließlich mit @ResultSetArt=TABLE zulässig.',1;
    IF @TableResultRequested=1 EXEC [monitor].[InternalPrepareSingleResultTable] @ResultTablesJson=@ResultTablesJson,@ResultName=N'objects',@TargetTable=@TableTarget OUTPUT,@ThrowOnError=1;
    IF @TableResultRequested = 1 OR @ConsoleResultRequested = 1 SET @ResultSetArtNormalisiert = 'NONE';
    DECLARE @DatabaseName sysname=NULL,@CrossDatabaseRequestedInternal bit=0,@DatenbankNameLike nvarchar(4000)=NULL;
    DECLARE @SchemaNameLike nvarchar(4000)=NULL,@ObjectNameLike nvarchar(4000)=NULL;
    DECLARE @SchemaPatternMode varchar(8),@SchemaPatternValue nvarchar(4000),@SchemaRegexFlags varchar(8),@SchemaPatternValid bit;
    DECLARE @ObjectPatternMode varchar(8),@ObjectPatternValue nvarchar(4000),@ObjectRegexFlags varchar(8),@ObjectPatternValid bit;
    SELECT @SchemaPatternMode=[PatternMode],@SchemaPatternValue=[PatternValue],@SchemaRegexFlags=[RegexFlags],@SchemaPatternValid=[IsValid] FROM [monitor].[TVF_ParsePattern](@SchemaNamePattern);
    SELECT @ObjectPatternMode=[PatternMode],@ObjectPatternValue=[PatternValue],@ObjectRegexFlags=[RegexFlags],@ObjectPatternValid=[IsValid] FROM [monitor].[TVF_ParsePattern](@ObjectNamePattern);
    IF @SchemaPatternMode='LIKE' SET @SchemaNameLike=@SchemaPatternValue;
    IF @ObjectPatternMode='LIKE' SET @ObjectNameLike=@ObjectPatternValue;
    DECLARE @IndexPatternMode varchar(8)='NONE',@IndexPatternValue nvarchar(4000)=NULL,@IndexRegexFlags varchar(8)=NULL,@IndexPatternValid bit=1;
    DECLARE @StatisticsPatternMode varchar(8)='NONE',@StatisticsPatternValue nvarchar(4000)=NULL,@StatisticsRegexFlags varchar(8)=NULL,@StatisticsPatternValid bit=1;
    DECLARE @DatabaseListCount int=0;
    IF @DatabaseNames IS NOT NULL AND NULLIF(LTRIM(RTRIM(@DatabaseNames)),N'') IS NOT NULL
        SELECT @DatabaseListCount=COUNT(*),@DatabaseName=MIN([NameValue]) FROM [monitor].[TVF_ParseSqlNameList](@DatabaseNames) WHERE [IsValid]=1;
    SET @CrossDatabaseRequestedInternal=CONVERT(bit,CASE WHEN @DatabaseNames IS NULL OR @DatabaseNamePattern IS NOT NULL OR @DatabaseListCount>1 THEN 1 ELSE 0 END);
    SELECT @DatenbankNameLike=CASE WHEN [PatternMode]='LIKE' THEN [PatternValue] END FROM [monitor].[TVF_ParsePattern](@DatabaseNamePattern);
    CREATE TABLE [#ObjectInventory_NameFilters]([FilterType] varchar(20) COLLATE SQL_Latin1_General_CP1_CS_AS NOT NULL,[ItemOrdinal] int NOT NULL,[NameValue] sysname COLLATE SQL_Latin1_General_CP1_CS_AS NULL,[DatabaseName] sysname COLLATE SQL_Latin1_General_CP1_CS_AS NULL,[SchemaName] sysname COLLATE SQL_Latin1_General_CP1_CS_AS NULL,[ObjectName] sysname COLLATE SQL_Latin1_General_CP1_CS_AS NULL);
    CREATE TABLE [#ObjectInventory_DatabaseCandidates]([DatabaseId] int NOT NULL,[DatabaseName] sysname NOT NULL,[StateDesc] nvarchar(60),[UserAccessDesc] nvarchar(60),[IsReadOnly] bit,[CompatibilityLevel] tinyint,[CollationName] sysname,[RecoveryModelDesc] nvarchar(60),[IsSystemDatabase] bit,[RequestedOrdinal] int);
    DECLARE @FilterStatus varchar(40)='AVAILABLE',@FilterError nvarchar(2048)=NULL,@CrossDatabaseRequested bit=0;
    EXEC [monitor].[USP_PrepareNameFilters] @SchemaNames=@SchemaNames,@ObjectNames=@ObjectNames,@FullObjectNames=@FullObjectNames,@IndexNames=NULL,@StatisticsNames=NULL,@ColumnNames=NULL,@StatusCode=@FilterStatus OUTPUT,@ErrorMessage=@FilterError OUTPUT,@FilterTable=N'#ObjectInventory_NameFilters';
    IF @FilterStatus='AVAILABLE' EXEC [monitor].[USP_PrepareDatabaseCandidates] @DatabaseNames=@DatabaseNames,@SystemdatenbankenEinbeziehen=@SystemdatenbankenEinbeziehen,@DatabaseNamePattern=@DatabaseNamePattern,@HighImpactConfirmed=@HighImpactConfirmed,@AnalysisClass='OBJECT_ANALYSIS_CURRENT',@StatusCode=@FilterStatus OUTPUT,@ErrorMessage=@FilterError OUTPUT,@CrossDatabaseRequested=@CrossDatabaseRequested OUTPUT,@CandidateTable=N'#ObjectInventory_DatabaseCandidates';
    IF @FilterStatus='AVAILABLE' AND UPPER(LTRIM(RTRIM(COALESCE(@AnalyseModus,''))))='VOLL'
        EXEC [monitor].[InternalCheckAnalysisPath] @AnalysisClass='CATALOG_DEEP',@HighImpactConfirmed=@HighImpactConfirmed,@StatusCode=@FilterStatus OUTPUT,@ErrorMessage=@FilterError OUTPUT;
    DECLARE @SchemaPredicateS nvarchar(max),@SchemaPredicateSch nvarchar(max),@ObjectPredicateO nvarchar(max),@FullObjectPredicateSO nvarchar(max),@IndexPredicateI nvarchar(max),@StatisticsPredicateSt nvarchar(max);
    SET @SchemaPredicateS=N' AND (NOT EXISTS(SELECT 1 FROM [#ObjectInventory_NameFilters] WHERE [FilterType]=''SCHEMA'') OR EXISTS(SELECT 1 FROM [#ObjectInventory_NameFilters] [f] WHERE [f].[FilterType]=''SCHEMA'' AND [f].[NameValue]=[s].[name] COLLATE SQL_Latin1_General_CP1_CS_AS))';
    SET @SchemaPredicateSch=REPLACE(@SchemaPredicateS,N'[s].[name]',N'[sch].[name]');
    SET @ObjectPredicateO=N' AND (NOT EXISTS(SELECT 1 FROM [#ObjectInventory_NameFilters] WHERE [FilterType]=''OBJECT'') OR EXISTS(SELECT 1 FROM [#ObjectInventory_NameFilters] [f] WHERE [f].[FilterType]=''OBJECT'' AND [f].[NameValue]=[o].[name] COLLATE SQL_Latin1_General_CP1_CS_AS))';
    SET @FullObjectPredicateSO=N' AND (NOT EXISTS(SELECT 1 FROM [#ObjectInventory_NameFilters] WHERE [FilterType]=''FULL_OBJECT'') OR EXISTS(SELECT 1 FROM [#ObjectInventory_NameFilters] [f] WHERE [f].[FilterType]=''FULL_OBJECT'' AND ([f].[DatabaseName] IS NULL OR [f].[DatabaseName]=@pDatabaseName COLLATE SQL_Latin1_General_CP1_CS_AS) AND ([f].[SchemaName] IS NULL OR [f].[SchemaName]=[s].[name] COLLATE SQL_Latin1_General_CP1_CS_AS) AND [f].[ObjectName]=[o].[name] COLLATE SQL_Latin1_General_CP1_CS_AS))';
    SET @IndexPredicateI=N' AND (NOT EXISTS(SELECT 1 FROM [#ObjectInventory_NameFilters] WHERE [FilterType]=''INDEX'') OR EXISTS(SELECT 1 FROM [#ObjectInventory_NameFilters] [f] WHERE [f].[FilterType]=''INDEX'' AND [f].[NameValue]=[i].[name] COLLATE SQL_Latin1_General_CP1_CS_AS))';
    SET @StatisticsPredicateSt=N' AND (NOT EXISTS(SELECT 1 FROM [#ObjectInventory_NameFilters] WHERE [FilterType]=''STATISTICS'') OR EXISTS(SELECT 1 FROM [#ObjectInventory_NameFilters] [f] WHERE [f].[FilterType]=''STATISTICS'' AND [f].[NameValue]=[st].[name] COLLATE SQL_Latin1_General_CP1_CS_AS))';
    IF @SchemaPatternMode='LIKE' BEGIN SET @SchemaPredicateS+=N' AND [s].[name] COLLATE SQL_Latin1_General_CP1_CS_AS LIKE N'''+REPLACE(@SchemaPatternValue,N'''',N'''''')+N''' COLLATE SQL_Latin1_General_CP1_CS_AS';SET @SchemaPredicateSch+=N' AND [sch].[name] COLLATE SQL_Latin1_General_CP1_CS_AS LIKE N'''+REPLACE(@SchemaPatternValue,N'''',N'''''')+N''' COLLATE SQL_Latin1_General_CP1_CS_AS';END;
    IF @SchemaPatternMode IN('REGEX','REGEXI') BEGIN SET @SchemaPredicateS+=N' AND REGEXP_LIKE([s].[name],N'''+REPLACE(@SchemaPatternValue,N'''',N'''''')+N''','''+@SchemaRegexFlags+N''')';SET @SchemaPredicateSch+=N' AND REGEXP_LIKE([sch].[name],N'''+REPLACE(@SchemaPatternValue,N'''',N'''''')+N''','''+@SchemaRegexFlags+N''')';END;
    IF @ObjectPatternMode='LIKE' SET @ObjectPredicateO+=N' AND [o].[name] COLLATE SQL_Latin1_General_CP1_CS_AS LIKE N'''+REPLACE(@ObjectPatternValue,N'''',N'''''')+N''' COLLATE SQL_Latin1_General_CP1_CS_AS';
    IF @ObjectPatternMode IN('REGEX','REGEXI') SET @ObjectPredicateO+=N' AND REGEXP_LIKE([o].[name],N'''+REPLACE(@ObjectPatternValue,N'''',N'''''')+N''','''+@ObjectRegexFlags+N''')';
    IF @IndexPatternMode='LIKE' SET @IndexPredicateI+=N' AND [i].[name] COLLATE SQL_Latin1_General_CP1_CS_AS LIKE N'''+REPLACE(@IndexPatternValue,N'''',N'''''')+N''' COLLATE SQL_Latin1_General_CP1_CS_AS';
    IF @IndexPatternMode IN('REGEX','REGEXI') SET @IndexPredicateI+=N' AND REGEXP_LIKE([i].[name],N'''+REPLACE(@IndexPatternValue,N'''',N'''''')+N''','''+@IndexRegexFlags+N''')';
    IF @StatisticsPatternMode='LIKE' SET @StatisticsPredicateSt+=N' AND [st].[name] COLLATE SQL_Latin1_General_CP1_CS_AS LIKE N'''+REPLACE(@StatisticsPatternValue,N'''',N'''''')+N''' COLLATE SQL_Latin1_General_CP1_CS_AS';
    IF @StatisticsPatternMode IN('REGEX','REGEXI') SET @StatisticsPredicateSt+=N' AND REGEXP_LIKE([st].[name],N'''+REPLACE(@StatisticsPatternValue,N'''',N'''''')+N''','''+@StatisticsRegexFlags+N''')';
    DECLARE @EffectiveMaxZeilen bigint = CASE WHEN @MaxZeilen IS NULL OR @MaxZeilen=0 THEN CONVERT(bigint,9223372036854775807) ELSE CONVERT(bigint,@MaxZeilen) END;
    DECLARE @MonitorPrintMessage nvarchar(2048);
    SET @ObjectType = UPPER(LTRIM(RTRIM(COALESCE(@ObjectType,'TABLE'))));
    SET @AnalyseModus = UPPER(LTRIM(RTRIM(COALESCE(@AnalyseModus,'GEZIELT'))));

    IF @Hilfe = 1
    BEGIN
        PRINT N'monitor.USP_ObjectInventory';        PRINT N'@DatabaseNames: exakter Name oder bracket-aware Pipe-Liste; NULL = alle zulässigen Datenbanken; N'''' = keine Einschränkung.';        PRINT N'@SystemdatenbankenEinbeziehen bit = 0: Systemdatenbanken einbeziehen.';        PRINT N'Exakte Listen und ...NamePattern sind gegenseitig exklusiv. Pattern: LIKE (Default/like:), regex: oder regexi:.';
        PRINT N'Datenbankauswahl ohne Vorabbegrenzung; @MaxZeilen int: harte Ergebnismengenbegrenzung.';
        PRINT N'@LockTimeoutMs int = 0: Metadatenzugriff wartet standardmäßig nicht auf Locks.';
        PRINT N'@PrintMeldungen bit = 1: strukturierte Warnungen zusätzlich in der Console.';
        PRINT N'Die Procedure liefert ein Objekt-, Größen-, Partitions-, Kompressions- und Indexinventar.';
        PRINT N'Ab SQL Server 2025 werden sichtbare JSON-Indizes und SQL/JSON-Pfade nach Objekt- und Spaltenprüfung ergänzt; JSON-Dokumentwerte werden nicht gelesen.';
        PRINT N'@ObjectType varchar(16) = TABLE: TABLE, VIEW oder ALLE.';
        PRINT N'@AnalyseModus varchar(16) = GEZIELT: GEZIELT benötigt Schema-/Objektfilter; VOLL prüft CATALOG_DEEP.';
        PRINT N'@MitIndizes bit = 1: 0 liefert nur Objektsummen.';
        PRINT N'@MitSpaltenlisten bit = 1: Key- und Include-Spaltenlisten ergänzen.';
        PRINT N'Beispiel: EXEC monitor.USP_ObjectInventory @DatabaseNames=N''[DWH]'', @ObjectNamePattern=N''like:Fact%'';';
        PRINT N'@Hilfe bit = 0: 1 zeigt diese Hilfe und führt keine Analyse aus.';
        RETURN;
    END;

    DECLARE @ModuleName sysname = N'USP_ObjectInventory';
    DECLARE @CollectionTimeUtc datetime2(3) = SYSUTCDATETIME();
    DECLARE @ProductMajorVersion int = TRY_CONVERT(int,SERVERPROPERTY(N'ProductMajorVersion'));

    DECLARE @OverallStatus varchar(40) = 'AVAILABLE';
    DECLARE @IsPartial bit = 0;
    DECLARE @TotalRows bigint = 0;
    DECLARE @ErrorNumber int = NULL;
    DECLARE @ErrorMessage nvarchar(2048) = NULL;
    DECLARE @Detail nvarchar(2000) = NULL;

    CREATE TABLE [#ObjectInventory_DatabaseStatus]
    (
          [DatabaseName]       sysname        NULL
        , [StatusCode]         varchar(40)    NOT NULL
        , [IsPartial]          bit            NOT NULL
        , [RowCount]           bigint         NOT NULL
        , [RequiredPermission] nvarchar(256)  NULL
        , [ErrorNumber]        int            NULL
        , [ErrorMessage]       nvarchar(2048) NULL
        , [Detail]             nvarchar(2000) NULL
        , [JsonIndexStatusCode] varchar(40)   NOT NULL
        , [JsonIndexRowCount]  bigint         NOT NULL
        , [JsonPathRowCount]   bigint         NOT NULL
        , [JsonIndexErrorNumber] int          NULL
        , [JsonIndexErrorMessage] nvarchar(2048) NULL
        , [JsonIndexEvidenceLimit] nvarchar(1000) NOT NULL
    );

    IF @FilterStatus<>'AVAILABLE' BEGIN SET @OverallStatus=@FilterStatus;SET @ErrorMessage=@FilterError;END;
    IF @ResultSetArtNormalisiert NOT IN('RAW','CONSOLE','NONE') BEGIN SET @OverallStatus='INVALID_PARAMETER';SET @ErrorMessage=N'@ResultSetArt muss CONSOLE, RAW, TABLE oder NONE enthalten.';END;
    IF @SchemaPatternValid=0 OR @ObjectPatternValid=0 OR @IndexPatternValid=0 OR @StatisticsPatternValid=0 OR (@SchemaNames IS NOT NULL AND @SchemaNamePattern IS NOT NULL) OR (@ObjectNames IS NOT NULL AND @ObjectNamePattern IS NOT NULL) BEGIN SET @OverallStatus='INVALID_PARAMETER';SET @ErrorMessage=N'Exakte Liste und Pattern derselben Eigenschaft sind gegenseitig exklusiv.';END;
IF @MaxZeilen<0 OR @LockTimeoutMs NOT BETWEEN 0 AND 60000
    BEGIN
        SET @OverallStatus = 'INVALID_PARAMETER';
        SET @ErrorMessage = N'Ungültiger Parameter: @MaxZeilen oder @LockTimeoutMs außerhalb des zulässigen Bereichs.';
    END


    IF @OverallStatus <> 'AVAILABLE'
    BEGIN
        INSERT [#ObjectInventory_DatabaseStatus]
        (
              [DatabaseName],[StatusCode],[IsPartial],[RowCount]
            , [RequiredPermission],[ErrorNumber],[ErrorMessage],[Detail]
            , [JsonIndexStatusCode],[JsonIndexRowCount],[JsonPathRowCount]
            , [JsonIndexErrorNumber],[JsonIndexErrorMessage],[JsonIndexEvidenceLimit]
        )
        VALUES
        (
              @DatabaseName,@OverallStatus,1,0
            , NULL,NULL,@ErrorMessage,N'Keine Datenbankanalyse ausgeführt.'
            , 'NOT_COLLECTED',0,0,NULL,NULL
            , N'Die Objektinventur wurde vor dem optionalen JSON-Index-Pfad beendet.'
        );
        SET @IsPartial = 1;
    END
    ELSE
    BEGIN
        SET @LockTimeoutSql=N'SET LOCK_TIMEOUT '+CONVERT(nvarchar(20),@LockTimeoutMs)+N';';
        EXEC [sys].[sp_executesql] @LockTimeoutSql;
    END;

    DECLARE @CatalogAllowed bit = 1;
    IF @AnalyseModus = 'VOLL'
        SELECT @CatalogAllowed = COALESCE(MAX(CONVERT(tinyint, [IsAllowed])), 0)
        FROM [monitor].[VW_AnalyseAccessCurrent]
        WHERE [AnalysisClass] = 'CATALOG_DEEP';

    CREATE TABLE [#ObjectInventory_Result]
    (
          [DatabaseName]                sysname         NOT NULL
        , [SchemaName]                  sysname         NOT NULL
        , [ObjectName]                  sysname         NOT NULL
        , [ObjectType]                  varchar(20)     NOT NULL
        , [ObjectId]                    int             NOT NULL
        , [IsMsShipped]                 bit             NOT NULL
        , [IsMemoryOptimized]           bit             NULL
        , [TemporalTypeDesc]            nvarchar(60)    NULL
        , [DurabilityDesc]              nvarchar(60)    NULL
        , [CreateDate]                  datetime        NULL
        , [ModifyDate]                  datetime        NULL
        , [ObjectRowCount]              bigint          NULL
        , [ObjectReservedMb]            decimal(19,2)   NULL
        , [ObjectUsedMb]                decimal(19,2)   NULL
        , [IndexId]                     int             NULL
        , [IndexName]                   sysname         NULL
        , [IndexTypeDesc]               nvarchar(60)    NULL
        , [IsUnique]                    bit             NULL
        , [IsPrimaryKey]                bit             NULL
        , [IsUniqueConstraint]          bit             NULL
        , [IsDisabled]                  bit             NULL
        , [IsHypothetical]              bit             NULL
        , [HasFilter]                   bit             NULL
        , [FilterDefinition]            nvarchar(max)   NULL
        , [FillFactor]                  tinyint         NULL
        , [AllowRowLocks]               bit             NULL
        , [AllowPageLocks]              bit             NULL
        , [OptimizeForSequentialKey]    bit             NULL
        , [DataSpaceName]               sysname         NULL
        , [PartitionCount]              int             NULL
        , [IndexRowCount]               bigint          NULL
        , [IndexReservedMb]             decimal(19,2)   NULL
        , [IndexUsedMb]                 decimal(19,2)   NULL
        , [MinCompressionDesc]          nvarchar(60)    NULL
        , [MaxCompressionDesc]          nvarchar(60)    NULL
        , [HasMixedCompression]         bit             NULL
        , [KeyColumns]                  nvarchar(max)   NULL
        , [IncludedColumns]             nvarchar(max)   NULL
        , [IsJsonIndex]                 bit             NULL
        , [OptimizeForArraySearch]      bit             NULL
        , [JsonPathCount]               bigint          NULL
        , [JsonPaths]                   nvarchar(max)   NULL
        , [JsonIndexStatusCode]         varchar(40)     NULL
        , [JsonIndexEvidenceLimit]      nvarchar(1000)  NULL
    );

    CREATE TABLE [#ObjectInventory_JsonIndexes]
    (
          [DatabaseName]           sysname COLLATE SQL_Latin1_General_CP1_CS_AS NOT NULL
        , [ObjectId]               int NOT NULL
        , [IndexId]                int NOT NULL
        , [OptimizeForArraySearch] bit NULL
        , PRIMARY KEY ([DatabaseName],[ObjectId],[IndexId])
    );

    CREATE TABLE [#ObjectInventory_JsonPathAgg]
    (
          [DatabaseName] sysname COLLATE SQL_Latin1_General_CP1_CS_AS NOT NULL
        , [ObjectId]     int NOT NULL
        , [IndexId]      int NOT NULL
        , [JsonPathCount] bigint NOT NULL
        , [JsonPaths]    nvarchar(max) NULL
        , PRIMARY KEY ([DatabaseName],[ObjectId],[IndexId])
    );

    IF @OverallStatus = 'AVAILABLE' AND @ObjectType NOT IN ('TABLE','VIEW','ALLE')
    BEGIN
        SET @OverallStatus='INVALID_PARAMETER';
        SET @ErrorMessage=N'@ObjectType muss TABLE, VIEW oder ALLE sein.';
        INSERT [#ObjectInventory_DatabaseStatus]
        (
              [DatabaseName],[StatusCode],[IsPartial],[RowCount]
            , [RequiredPermission],[ErrorNumber],[ErrorMessage],[Detail]
            , [JsonIndexStatusCode],[JsonIndexRowCount],[JsonPathRowCount]
            , [JsonIndexErrorNumber],[JsonIndexErrorMessage],[JsonIndexEvidenceLimit]
        )
        VALUES(@DatabaseName,@OverallStatus,1,0,NULL,NULL,@ErrorMessage,NULL,
               'NOT_COLLECTED',0,0,NULL,NULL,N'Parameterprüfung fehlgeschlagen.');
    END
    ELSE IF @OverallStatus = 'AVAILABLE' AND @AnalyseModus NOT IN ('GEZIELT','VOLL')
    BEGIN
        SET @OverallStatus='INVALID_PARAMETER';
        SET @ErrorMessage=N'@AnalyseModus muss GEZIELT oder VOLL sein.';
        INSERT [#ObjectInventory_DatabaseStatus]
        (
              [DatabaseName],[StatusCode],[IsPartial],[RowCount]
            , [RequiredPermission],[ErrorNumber],[ErrorMessage],[Detail]
            , [JsonIndexStatusCode],[JsonIndexRowCount],[JsonPathRowCount]
            , [JsonIndexErrorNumber],[JsonIndexErrorMessage],[JsonIndexEvidenceLimit]
        )
        VALUES(@DatabaseName,@OverallStatus,1,0,NULL,NULL,@ErrorMessage,NULL,
               'NOT_COLLECTED',0,0,NULL,NULL,N'Parameterprüfung fehlgeschlagen.');
    END
    ELSE IF @OverallStatus = 'AVAILABLE' AND @AnalyseModus='GEZIELT' AND NOT EXISTS(SELECT 1 FROM [#ObjectInventory_NameFilters]) AND @SchemaNamePattern IS NULL AND @ObjectNamePattern IS NULL
    BEGIN
        SET @OverallStatus='INVALID_PARAMETER';
        SET @ErrorMessage=N'GEZIELT erfordert eine exakte Namensliste, @FullObjectNames oder ein Schema-/Objekt-Pattern. Für einen vollständigen Kataloglauf @AnalyseModus=''VOLL'' verwenden.';
        INSERT [#ObjectInventory_DatabaseStatus]
        (
              [DatabaseName],[StatusCode],[IsPartial],[RowCount]
            , [RequiredPermission],[ErrorNumber],[ErrorMessage],[Detail]
            , [JsonIndexStatusCode],[JsonIndexRowCount],[JsonPathRowCount]
            , [JsonIndexErrorNumber],[JsonIndexErrorMessage],[JsonIndexEvidenceLimit]
        )
        VALUES(@DatabaseName,@OverallStatus,1,0,NULL,NULL,@ErrorMessage,NULL,
               'NOT_COLLECTED',0,0,NULL,NULL,N'Für GEZIELT wurde kein Objekt-Scope geliefert.');
    END
    ELSE IF @OverallStatus = 'AVAILABLE' AND @AnalyseModus='VOLL' AND @CatalogAllowed=0
    BEGIN
        SET @OverallStatus='DENIED_GROUP';
        SET @ErrorMessage=N'CATALOG_DEEP ist für die vollständige Objektinventur nicht freigegeben.';
        INSERT [#ObjectInventory_DatabaseStatus]
        (
              [DatabaseName],[StatusCode],[IsPartial],[RowCount]
            , [RequiredPermission],[ErrorNumber],[ErrorMessage],[Detail]
            , [JsonIndexStatusCode],[JsonIndexRowCount],[JsonPathRowCount]
            , [JsonIndexErrorNumber],[JsonIndexErrorMessage],[JsonIndexEvidenceLimit]
        )
        VALUES(@DatabaseName,@OverallStatus,1,0,NULL,NULL,@ErrorMessage,NULL,
               'NOT_COLLECTED',0,0,NULL,NULL,N'CATALOG_DEEP wurde nicht freigegeben.');
    END
    ELSE IF @OverallStatus = 'AVAILABLE'
    BEGIN
        DECLARE @DbId int, @DbName sysname, @Sql nvarchar(max), @Rows bigint;
        DECLARE @JsonProbeSql nvarchar(max);
        DECLARE @HasJsonIndexes bit,@HasJsonIndexPaths bit;
        DECLARE @JsonIndexesSchemaValid bit,@JsonIndexPathsSchemaValid bit;
        DECLARE @JsonIndexStatusCode varchar(40),@JsonIndexSourcePartial bit;
        DECLARE @JsonIndexRowCount bigint,@JsonPathRowCount bigint;
        DECLARE @JsonIndexErrorNumber int,@JsonIndexErrorMessage nvarchar(2048);
        DECLARE @JsonIndexEvidenceLimit nvarchar(1000);
        DECLARE dbcur CURSOR LOCAL FAST_FORWARD FOR
            SELECT [DatabaseId], [DatabaseName]
            FROM [#ObjectInventory_DatabaseCandidates];
        OPEN dbcur;
        FETCH NEXT FROM dbcur INTO @DbId,@DbName;
        WHILE @@FETCH_STATUS=0
        BEGIN
            SELECT
                  @HasJsonIndexes=0
                , @HasJsonIndexPaths=0
                , @JsonIndexesSchemaValid=0
                , @JsonIndexPathsSchemaValid=0
                , @JsonIndexStatusCode='NOT_COLLECTED'
                , @JsonIndexSourcePartial=0
                , @JsonIndexRowCount=0
                , @JsonPathRowCount=0
                , @JsonIndexErrorNumber=NULL
                , @JsonIndexErrorMessage=NULL
                , @JsonIndexEvidenceLimit=N'JSON-Index-Metadaten wurden nicht angefordert.';

            IF @MitIndizes=0
            BEGIN
                SET @JsonIndexEvidenceLimit=N'@MitIndizes=0 unterdrückt sämtliche Indexdetails einschließlich JSON-Index-Metadaten.';
            END
            ELSE IF @ObjectType='VIEW'
            BEGIN
                SET @JsonIndexStatusCode='NOT_APPLICABLE';
                SET @JsonIndexEvidenceLimit=N'JSON-Indizes gelten für Tabellen; der angeforderte Scope enthält ausschließlich Views.';
            END
            ELSE IF @ProductMajorVersion IS NULL OR @ProductMajorVersion<17
            BEGIN
                SET @JsonIndexStatusCode='UNAVAILABLE_VERSION';
                SET @JsonIndexEvidenceLimit=N'sys.json_indexes und sys.json_index_paths werden vor SQL Server 2025 nicht referenziert.';
            END
            ELSE
            BEGIN
                BEGIN TRY
                    SET @JsonProbeSql=N'USE '+QUOTENAME(@DbName)+N';
SELECT
      @pHasJsonIndexesOut=CONVERT(bit,CASE WHEN EXISTS
      (
          SELECT 1
          FROM [sys].[all_objects] AS [o] WITH (NOLOCK)
          INNER JOIN [sys].[schemas] AS [s] WITH (NOLOCK)
             ON [s].[schema_id]=[o].[schema_id]
          WHERE [s].[name]=N''sys'' AND [o].[name]=N''json_indexes''
      ) THEN 1 ELSE 0 END)
    , @pHasJsonIndexPathsOut=CONVERT(bit,CASE WHEN EXISTS
      (
          SELECT 1
          FROM [sys].[all_objects] AS [o] WITH (NOLOCK)
          INNER JOIN [sys].[schemas] AS [s] WITH (NOLOCK)
             ON [s].[schema_id]=[o].[schema_id]
          WHERE [s].[name]=N''sys'' AND [o].[name]=N''json_index_paths''
      ) THEN 1 ELSE 0 END);

SELECT @pJsonIndexesSchemaValidOut=CONVERT(bit,CASE
    WHEN @pHasJsonIndexesOut=1 AND
         (
             SELECT COUNT(DISTINCT [c].[name])
             FROM [sys].[all_columns] AS [c] WITH (NOLOCK)
             INNER JOIN [sys].[all_objects] AS [o] WITH (NOLOCK)
                ON [o].[object_id]=[c].[object_id]
             INNER JOIN [sys].[schemas] AS [s] WITH (NOLOCK)
                ON [s].[schema_id]=[o].[schema_id]
             WHERE [s].[name]=N''sys'' AND [o].[name]=N''json_indexes''
               AND [c].[name] IN (N''object_id'',N''index_id'',N''optimize_for_array_search'')
         )=3 THEN 1 ELSE 0 END);

SELECT @pJsonIndexPathsSchemaValidOut=CONVERT(bit,CASE
    WHEN @pHasJsonIndexPathsOut=1 AND
         (
             SELECT COUNT(DISTINCT [c].[name])
             FROM [sys].[all_columns] AS [c] WITH (NOLOCK)
             INNER JOIN [sys].[all_objects] AS [o] WITH (NOLOCK)
                ON [o].[object_id]=[c].[object_id]
             INNER JOIN [sys].[schemas] AS [s] WITH (NOLOCK)
                ON [s].[schema_id]=[o].[schema_id]
             WHERE [s].[name]=N''sys'' AND [o].[name]=N''json_index_paths''
               AND [c].[name] IN (N''object_id'',N''index_id'',N''path'')
         )=3 THEN 1 ELSE 0 END);';

                    EXEC [sys].[sp_executesql]
                          @JsonProbeSql
                        , N'@pHasJsonIndexesOut bit OUTPUT,@pHasJsonIndexPathsOut bit OUTPUT,
                            @pJsonIndexesSchemaValidOut bit OUTPUT,@pJsonIndexPathsSchemaValidOut bit OUTPUT'
                        , @pHasJsonIndexesOut=@HasJsonIndexes OUTPUT
                        , @pHasJsonIndexPathsOut=@HasJsonIndexPaths OUTPUT
                        , @pJsonIndexesSchemaValidOut=@JsonIndexesSchemaValid OUTPUT
                        , @pJsonIndexPathsSchemaValidOut=@JsonIndexPathsSchemaValid OUTPUT;
                END TRY
                BEGIN CATCH
                    SELECT
                          @JsonIndexStatusCode=CASE
                              WHEN ERROR_NUMBER() IN (229,262,297,300,371,916) THEN 'DENIED_PERMISSION'
                              WHEN ERROR_NUMBER()=1222 THEN 'TIMEOUT'
                              ELSE 'ERROR_HANDLED' END
                        , @JsonIndexSourcePartial=1
                        , @JsonIndexErrorNumber=ERROR_NUMBER()
                        , @JsonIndexErrorMessage=ERROR_MESSAGE()
                        , @JsonIndexEvidenceLimit=N'Die JSON-Index-Capability-Prüfung scheiterte; die allgemeine Objektinventur wird unabhängig fortgesetzt.';
                END CATCH;

                IF @JsonIndexStatusCode='NOT_COLLECTED'
                BEGIN
                    IF @HasJsonIndexes=0
                    BEGIN
                        SET @JsonIndexStatusCode='UNAVAILABLE_FEATURE';
                        SET @JsonIndexEvidenceLimit=N'Der konkrete SQL-Server-2025-Build stellt sys.json_indexes nicht bereit.';
                    END
                    ELSE IF @JsonIndexesSchemaValid=0
                    BEGIN
                        SELECT
                              @JsonIndexStatusCode='UNAVAILABLE_SOURCE_SCHEMA'
                            , @JsonIndexSourcePartial=1
                            , @JsonIndexEvidenceLimit=N'sys.json_indexes ist vorhanden, aber das benötigte Pflichtschema weicht ab.';
                    END
                    ELSE
                    BEGIN TRY
                        SET @Sql=N'USE '+QUOTENAME(@DbName)+N';
INSERT [#ObjectInventory_JsonIndexes]
(
      [DatabaseName],[ObjectId],[IndexId],[OptimizeForArraySearch]
)
SELECT
      @pDatabaseName,[ji].[object_id],[ji].[index_id]
    , [ji].[optimize_for_array_search]
FROM [sys].[json_indexes] AS [ji] WITH (NOLOCK)
INNER JOIN [sys].[objects] AS [o] WITH (NOLOCK)
   ON [o].[object_id]=[ji].[object_id]
INNER JOIN [sys].[schemas] AS [s] WITH (NOLOCK)
   ON [s].[schema_id]=[o].[schema_id]
WHERE [o].[type]=''U''
'+@SchemaPredicateS+@ObjectPredicateO+@FullObjectPredicateSO+N';';
                        EXEC [sys].[sp_executesql]
                              @Sql
                            , N'@pDatabaseName sysname'
                            , @pDatabaseName=@DbName;
                        SELECT @JsonIndexRowCount=COUNT_BIG(*)
                        FROM [#ObjectInventory_JsonIndexes]
                        WHERE [DatabaseName]=@DbName;
                    END TRY
                    BEGIN CATCH
                        SELECT
                              @JsonIndexStatusCode=CASE
                                  WHEN ERROR_NUMBER() IN (229,262,297,300,371,916) THEN 'DENIED_PERMISSION'
                                  WHEN ERROR_NUMBER()=1222 THEN 'TIMEOUT'
                                  ELSE 'ERROR_HANDLED' END
                            , @JsonIndexSourcePartial=1
                            , @JsonIndexErrorNumber=ERROR_NUMBER()
                            , @JsonIndexErrorMessage=ERROR_MESSAGE()
                            , @JsonIndexEvidenceLimit=N'sys.json_indexes konnte nicht gelesen werden; die allgemeine Objektinventur wird unabhängig fortgesetzt.';
                    END CATCH;

                    IF @JsonIndexStatusCode='NOT_COLLECTED'
                    BEGIN
                        IF @HasJsonIndexPaths=0
                        BEGIN
                            SELECT
                                  @JsonIndexStatusCode='AVAILABLE_LIMITED'
                                , @JsonIndexSourcePartial=1
                                , @JsonIndexEvidenceLimit=N'JSON-Indizes sind sichtbar; der konkrete Build stellt sys.json_index_paths jedoch nicht bereit.';
                        END
                        ELSE IF @JsonIndexPathsSchemaValid=0
                        BEGIN
                            SELECT
                                  @JsonIndexStatusCode='AVAILABLE_LIMITED'
                                , @JsonIndexSourcePartial=1
                                , @JsonIndexEvidenceLimit=N'JSON-Indizes sind sichtbar; das Pflichtschema von sys.json_index_paths weicht jedoch ab.';
                        END
                        ELSE IF @JsonIndexRowCount=0
                        BEGIN
                            SELECT
                                  @JsonIndexStatusCode='AVAILABLE_EMPTY_OR_RESTRICTED'
                                , @JsonIndexEvidenceLimit=N'Keine JSON-Indexzeile ist im angeforderten Scope sichtbar; der Pfadkatalog wurde deshalb nicht gelesen. Metadata Visibility unterscheidet leeren Scope und verborgene Objekte nicht sicher.';
                        END
                        ELSE
                        BEGIN TRY
                            SET @Sql=N'USE '+QUOTENAME(@DbName)+N';
INSERT [#ObjectInventory_JsonPathAgg]
(
      [DatabaseName],[ObjectId],[IndexId],[JsonPathCount],[JsonPaths]
)
SELECT
      @pDatabaseName,[jp].[object_id],[jp].[index_id],COUNT_BIG(*)
    , STRING_AGG(CONVERT(nvarchar(max),[jp].[path]),N'' | '')
        WITHIN GROUP (ORDER BY [jp].[path])
FROM [sys].[json_index_paths] AS [jp] WITH (NOLOCK)
INNER JOIN [#ObjectInventory_JsonIndexes] AS [ji]
   ON [ji].[DatabaseName]=@pDatabaseName
  AND [ji].[ObjectId]=[jp].[object_id]
  AND [ji].[IndexId]=[jp].[index_id]
GROUP BY [jp].[object_id],[jp].[index_id];';
                            EXEC [sys].[sp_executesql]
                                  @Sql
                                , N'@pDatabaseName sysname'
                                , @pDatabaseName=@DbName;
                            SELECT @JsonPathRowCount=COALESCE(SUM([JsonPathCount]),0)
                            FROM [#ObjectInventory_JsonPathAgg]
                            WHERE [DatabaseName]=@DbName;
                            SELECT
                                  @JsonIndexStatusCode='AVAILABLE'
                                , @JsonIndexEvidenceLimit=N'JSON-Index- und Pfadkatalog wurden je Datenbank und Procedure-Aufruf höchstens einmal gelesen. SQL/JSON-Pfade sind Schemametadaten; JSON-Dokumentwerte wurden nicht gelesen.';
                        END TRY
                        BEGIN CATCH
                            SELECT
                                  @JsonIndexStatusCode='AVAILABLE_LIMITED'
                                , @JsonIndexSourcePartial=1
                                , @JsonIndexErrorNumber=ERROR_NUMBER()
                                , @JsonIndexErrorMessage=ERROR_MESSAGE()
                                , @JsonIndexEvidenceLimit=N'JSON-Indizes sind sichtbar, der Pfadkatalog konnte jedoch nicht vollständig gelesen werden.';
                        END CATCH;
                    END;
                END;
            END;

            BEGIN TRY
                SET @Sql = N'SET LOCK_TIMEOUT ' + CONVERT(nvarchar(11), @LockTimeoutMs) + N'; USE ' + QUOTENAME(@DbName) + N';
;WITH PartitionBase AS
(
    SELECT [p].[object_id],[p].[index_id],COUNT_BIG(*) AS [PartitionCount],SUM([p].[rows]) AS [IndexRowCount],
           MIN([p].[data_compression_desc]) AS [MinCompressionDesc],
           MAX([p].[data_compression_desc]) AS [MaxCompressionDesc]
    FROM sys.partitions AS [p] WITH (NOLOCK)
    GROUP BY [p].[object_id],[p].[index_id]
),
AllocationAgg AS
(
    SELECT [p].[object_id],[p].[index_id],
           SUM(CONVERT(bigint,[au].[total_pages])) AS [ReservedPages],
           SUM(CONVERT(bigint,[au].[used_pages])) AS [UsedPages]
    FROM sys.partitions AS [p] WITH (NOLOCK)
    LEFT JOIN sys.allocation_units AS [au] WITH (NOLOCK)
      ON [au].[container_id] = CASE WHEN [au].[type] = 2 THEN [p].[partition_id] ELSE [p].[hobt_id] END
    GROUP BY [p].[object_id],[p].[index_id]
),
IndexAgg AS
(
    SELECT [pb].[object_id],[pb].[index_id],[pb].[PartitionCount],[pb].[IndexRowCount],
           [aa].[ReservedPages],[aa].[UsedPages],[pb].[MinCompressionDesc],[pb].[MaxCompressionDesc]
    FROM PartitionBase AS [pb]
    LEFT JOIN AllocationAgg AS [aa] ON [aa].[object_id]=[pb].[object_id] AND [aa].[index_id]=[pb].[index_id]
),
ObjectAgg AS
(
    SELECT [ia].[object_id],
           SUM(CASE WHEN [ia].[index_id] IN (0,1) THEN [ia].[IndexRowCount] ELSE 0 END) AS [ObjectRowCount],
           SUM([ia].[ReservedPages]) AS [ReservedPages],
           SUM([ia].[UsedPages]) AS [UsedPages]
    FROM IndexAgg AS [ia]
    GROUP BY [ia].[object_id]
)
INSERT #ObjectInventory_Result
SELECT TOP (@pMaxRows)
       @pDatabaseName, [s].[name], [o].[name],
       CASE [o].[type] WHEN ''U'' THEN ''TABLE'' WHEN ''V'' THEN ''VIEW'' ELSE [o].[type_desc] END,
       [o].[object_id],[o].[is_ms_shipped],[t].[is_memory_optimized],[t].[temporal_type_desc],[t].[durability_desc],
       [o].[create_date],[o].[modify_date],
       [oa].[ObjectRowCount],CONVERT(decimal(19,2),[oa].[ReservedPages]/128.0),CONVERT(decimal(19,2),[oa].[UsedPages]/128.0),
       CASE WHEN @pMitIndizes=1 THEN [i].[index_id] END,
       CASE WHEN @pMitIndizes=1 THEN [i].[name] END,
       CASE WHEN @pMitIndizes=1 THEN [i].[type_desc] END,
       CASE WHEN @pMitIndizes=1 THEN [i].[is_unique] END,
       CASE WHEN @pMitIndizes=1 THEN [i].[is_primary_key] END,
       CASE WHEN @pMitIndizes=1 THEN [i].[is_unique_constraint] END,
       CASE WHEN @pMitIndizes=1 THEN [i].[is_disabled] END,
       CASE WHEN @pMitIndizes=1 THEN [i].[is_hypothetical] END,
       CASE WHEN @pMitIndizes=1 THEN [i].[has_filter] END,
       CASE WHEN @pMitIndizes=1 THEN [i].[filter_definition] END,
       CASE WHEN @pMitIndizes=1 THEN [i].[fill_factor] END,
       CASE WHEN @pMitIndizes=1 THEN [i].[allow_row_locks] END,
       CASE WHEN @pMitIndizes=1 THEN [i].[allow_page_locks] END,
       CASE WHEN @pMitIndizes=1 THEN [i].[optimize_for_sequential_key] END,
       CASE WHEN @pMitIndizes=1 THEN [ds].[name] END,
       CASE WHEN @pMitIndizes=1 THEN CONVERT(int,[ia].[PartitionCount]) END,
       CASE WHEN @pMitIndizes=1 THEN [ia].[IndexRowCount] END,
       CASE WHEN @pMitIndizes=1 THEN CONVERT(decimal(19,2),[ia].[ReservedPages]/128.0) END,
       CASE WHEN @pMitIndizes=1 THEN CONVERT(decimal(19,2),[ia].[UsedPages]/128.0) END,
       CASE WHEN @pMitIndizes=1 THEN [ia].[MinCompressionDesc] END,
       CASE WHEN @pMitIndizes=1 THEN [ia].[MaxCompressionDesc] END,
       CASE WHEN @pMitIndizes=1 THEN CONVERT(bit,CASE WHEN [ia].[MinCompressionDesc]<>[ia].[MaxCompressionDesc] THEN 1 ELSE 0 END) END,
       CASE WHEN @pMitIndizes=1 AND @pMitSpaltenlisten=1 THEN [kc].[KeyColumns] END,
       CASE WHEN @pMitIndizes=1 AND @pMitSpaltenlisten=1 THEN [ic].[IncludedColumns] END,
       CASE WHEN @pMitIndizes=1 THEN CONVERT(bit,CASE WHEN [ji].[ObjectId] IS NULL THEN 0 ELSE 1 END) END,
       CASE WHEN @pMitIndizes=1 THEN [ji].[OptimizeForArraySearch] END,
       CASE
           WHEN @pMitIndizes=1 AND [ji].[ObjectId] IS NOT NULL
                AND @pJsonIndexStatusCode=''AVAILABLE''
           THEN COALESCE([jp].[JsonPathCount],CONVERT(bigint,0))
           WHEN @pMitIndizes=1 THEN [jp].[JsonPathCount]
       END,
       CASE WHEN @pMitIndizes=1 THEN [jp].[JsonPaths] END,
       CASE
           WHEN @pMitIndizes=0 THEN NULL
           WHEN [ji].[ObjectId] IS NOT NULL AND @pJsonIndexStatusCode=''AVAILABLE_EMPTY_OR_RESTRICTED'' THEN ''AVAILABLE''
           WHEN [ji].[ObjectId] IS NOT NULL THEN @pJsonIndexStatusCode
           WHEN @pJsonIndexStatusCode IN
                (''AVAILABLE'',''AVAILABLE_LIMITED'',''AVAILABLE_EMPTY_OR_RESTRICTED'')
           THEN ''NOT_APPLICABLE''
           ELSE @pJsonIndexStatusCode
       END,
       CASE WHEN @pMitIndizes=1 THEN @pJsonIndexEvidenceLimit END
FROM sys.objects AS [o] WITH (NOLOCK)
JOIN sys.schemas AS [s] WITH (NOLOCK) ON [s].[schema_id]=[o].[schema_id]
LEFT JOIN sys.tables AS [t] WITH (NOLOCK) ON [t].[object_id]=[o].[object_id]
LEFT JOIN ObjectAgg AS [oa] ON [oa].[object_id]=[o].[object_id]
LEFT JOIN sys.indexes AS [i] WITH (NOLOCK) ON [i].[object_id]=[o].[object_id] AND @pMitIndizes=1
LEFT JOIN IndexAgg AS [ia] ON [ia].[object_id]=[i].[object_id] AND [ia].[index_id]=[i].[index_id]
LEFT JOIN sys.data_spaces AS [ds] WITH (NOLOCK) ON [ds].[data_space_id]=[i].[data_space_id]
LEFT JOIN [#ObjectInventory_JsonIndexes] AS [ji]
  ON [ji].[DatabaseName]=@pDatabaseName
 AND [ji].[ObjectId]=[i].[object_id]
 AND [ji].[IndexId]=[i].[index_id]
LEFT JOIN [#ObjectInventory_JsonPathAgg] AS [jp]
  ON [jp].[DatabaseName]=@pDatabaseName
 AND [jp].[ObjectId]=[i].[object_id]
 AND [jp].[IndexId]=[i].[index_id]
OUTER APPLY
(
    SELECT STUFF((SELECT N'', ''+QUOTENAME([c].[name])+CASE WHEN [ic2].[is_descending_key]=1 THEN N'' DESC'' ELSE N'''' END
                  FROM sys.index_columns AS [ic2] WITH (NOLOCK)
                  JOIN sys.columns AS [c] WITH (NOLOCK) ON [c].[object_id]=[ic2].[object_id] AND [c].[column_id]=[ic2].[column_id]
                  WHERE @pMitIndizes=1 AND @pMitSpaltenlisten=1 AND [ic2].[object_id]=[i].[object_id] AND [ic2].[index_id]=[i].[index_id] AND [ic2].[key_ordinal]>0
                  ORDER BY [ic2].[key_ordinal] FOR XML PATH(''''),TYPE).value(''.'',''nvarchar(max)''),1,2,N'''') AS [KeyColumns]
) AS [kc]
OUTER APPLY
(
    SELECT STUFF((SELECT N'', ''+QUOTENAME([c].[name])
                  FROM sys.index_columns AS [ic2] WITH (NOLOCK)
                  JOIN sys.columns AS [c] WITH (NOLOCK) ON [c].[object_id]=[ic2].[object_id] AND [c].[column_id]=[ic2].[column_id]
                  WHERE @pMitIndizes=1 AND @pMitSpaltenlisten=1 AND [ic2].[object_id]=[i].[object_id] AND [ic2].[index_id]=[i].[index_id] AND [ic2].[is_included_column]=1
                  ORDER BY [ic2].[index_column_id] FOR XML PATH(''''),TYPE).value(''.'',''nvarchar(max)''),1,2,N'''') AS [IncludedColumns]
) AS [ic]
WHERE [o].[type] IN (''U'',''V'')
  AND (@pObjectType=''ALLE'' OR (@pObjectType=''TABLE'' AND [o].[type]=''U'') OR (@pObjectType=''VIEW'' AND [o].[type]=''V''))
'+@SchemaPredicateS+@ObjectPredicateO+@FullObjectPredicateSO+N'
  AND (@pMitIndizes=0 OR [o].[type]=''V'' OR [i].[index_id] IS NOT NULL)
ORDER BY [oa].[ReservedPages] DESC,[o].[object_id],[i].[index_id]
OPTION (MAXDOP 1, RECOMPILE);';
                EXEC [sys].[sp_executesql] @Sql,
                    N'@pDatabaseName sysname,@pMaxRows bigint,@pObjectType varchar(16),@pSchemaLike nvarchar(256),@pObjectLike nvarchar(256),@pMitIndizes bit,@pMitSpaltenlisten bit,@pJsonIndexStatusCode varchar(40),@pJsonIndexEvidenceLimit nvarchar(1000)',
                    @pDatabaseName=@DbName,@pMaxRows=@EffectiveMaxZeilen,@pObjectType=@ObjectType,@pSchemaLike=@SchemaNameLike,@pObjectLike=@ObjectNameLike,@pMitIndizes=@MitIndizes,@pMitSpaltenlisten=@MitSpaltenlisten,
                    @pJsonIndexStatusCode=@JsonIndexStatusCode,@pJsonIndexEvidenceLimit=@JsonIndexEvidenceLimit;
                SELECT @Rows=COUNT_BIG(*) FROM [#ObjectInventory_Result] WHERE [DatabaseName]=@DbName;
                INSERT [#ObjectInventory_DatabaseStatus]
                (
                      [DatabaseName],[StatusCode],[IsPartial],[RowCount]
                    , [RequiredPermission],[ErrorNumber],[ErrorMessage],[Detail]
                    , [JsonIndexStatusCode],[JsonIndexRowCount],[JsonPathRowCount]
                    , [JsonIndexErrorNumber],[JsonIndexErrorMessage],[JsonIndexEvidenceLimit]
                )
                VALUES
                (
                      @DbName
                    , CASE WHEN @JsonIndexSourcePartial=1 THEN 'AVAILABLE_LIMITED' ELSE 'AVAILABLE' END
                    , @JsonIndexSourcePartial,@Rows
                    , N'Metadata Visibility / VIEW DEFINITION für vollständige Metadaten'
                    , NULL,NULL
                    , N'Systemkatalog erfolgreich gelesen; unsichtbare Objekte werden nicht als Fehler gewertet.'
                    , @JsonIndexStatusCode,@JsonIndexRowCount,@JsonPathRowCount
                    , @JsonIndexErrorNumber,@JsonIndexErrorMessage,@JsonIndexEvidenceLimit
                );
            END TRY
            BEGIN CATCH
                INSERT [#ObjectInventory_DatabaseStatus]
                (
                      [DatabaseName],[StatusCode],[IsPartial],[RowCount]
                    , [RequiredPermission],[ErrorNumber],[ErrorMessage],[Detail]
                    , [JsonIndexStatusCode],[JsonIndexRowCount],[JsonPathRowCount]
                    , [JsonIndexErrorNumber],[JsonIndexErrorMessage],[JsonIndexEvidenceLimit]
                )
                VALUES
                (
                      @DbName
                    , CASE WHEN ERROR_NUMBER() IN (229,262,297,300,371,916) THEN 'DENIED_PERMISSION'
                           WHEN ERROR_NUMBER()=1222 THEN 'TIMEOUT'
                           WHEN ERROR_NUMBER() IN (207,208,4121) THEN 'UNAVAILABLE_OBJECT'
                           ELSE 'ERROR_HANDLED' END
                    , 1,0,N'Metadata Visibility / VIEW DEFINITION'
                    , ERROR_NUMBER(),ERROR_MESSAGE(),N'Datenbankfehler isoliert.'
                    , @JsonIndexStatusCode,@JsonIndexRowCount,@JsonPathRowCount
                    , @JsonIndexErrorNumber,@JsonIndexErrorMessage,@JsonIndexEvidenceLimit
                );
            END CATCH;
            FETCH NEXT FROM dbcur INTO @DbId,@DbName;
        END;
        CLOSE dbcur; DEALLOCATE dbcur;
        IF NOT EXISTS(SELECT 1 FROM [#ObjectInventory_DatabaseStatus])
            INSERT [#ObjectInventory_DatabaseStatus]
            (
                  [DatabaseName],[StatusCode],[IsPartial],[RowCount]
                , [RequiredPermission],[ErrorNumber],[ErrorMessage],[Detail]
                , [JsonIndexStatusCode],[JsonIndexRowCount],[JsonPathRowCount]
                , [JsonIndexErrorNumber],[JsonIndexErrorMessage],[JsonIndexEvidenceLimit]
            )
            VALUES
            (
                  @DatabaseName,'DATABASE_UNAVAILABLE',1,0,NULL,NULL
                , N'Keine sichtbare Online-Zieldatenbank gefunden.',NULL
                , 'NOT_COLLECTED',0,0,NULL,NULL
                , N'Keine sichtbare Online-Zieldatenbank wurde für die JSON-Index-Prüfung erreicht.'
            );
    END;



    SELECT @TotalRows = COUNT_BIG(*) FROM [#ObjectInventory_Result];

    IF @OverallStatus = 'AVAILABLE'
    BEGIN
        IF EXISTS (SELECT 1 FROM [#ObjectInventory_DatabaseStatus] WHERE [StatusCode] NOT IN ('AVAILABLE','AVAILABLE_LIMITED','SKIPPED','NOT_APPLICABLE'))
        BEGIN
            SET @OverallStatus = CASE WHEN @TotalRows > 0 THEN 'PARTIAL' ELSE (SELECT TOP (1) [StatusCode] FROM [#ObjectInventory_DatabaseStatus] WHERE [StatusCode] NOT IN ('AVAILABLE','AVAILABLE_LIMITED','SKIPPED','NOT_APPLICABLE') ORDER BY [DatabaseName]) END;
            SET @IsPartial = 1;
        END
        ELSE IF EXISTS (SELECT 1 FROM [#ObjectInventory_DatabaseStatus] WHERE [StatusCode] IN ('AVAILABLE_LIMITED','SKIPPED','NOT_APPLICABLE'))
        BEGIN
            SET @OverallStatus = CASE WHEN @TotalRows > 0 THEN 'AVAILABLE_LIMITED' ELSE 'SKIPPED' END;
            SET @IsPartial = 1;
        END;
    END;

    IF @PrintMeldungen = 1 AND @OverallStatus <> 'AVAILABLE'
        BEGIN
    SET @MonitorPrintMessage = FORMATMESSAGE(N'WARNUNG %s: %s', @OverallStatus, COALESCE(@ErrorMessage, @Detail, N'Teilergebnis oder eingeschränkte Sicht'));
    RAISERROR(N'%s', 10, 1, @MonitorPrintMessage) WITH NOWAIT;
END;

    SET @LockTimeoutSql=N'SET LOCK_TIMEOUT '+CONVERT(nvarchar(20),@OriginalLockTimeout)+N';';
    EXEC [sys].[sp_executesql] @LockTimeoutSql;

    IF @ResultSetArtNormalisiert<>'NONE' BEGIN
        SELECT @ModuleName [ModuleName],@CollectionTimeUtc [CollectionTimeUtc],@OverallStatus [StatusCode],@IsPartial [IsPartial],@TotalRows [RowCount],@ErrorNumber [ErrorNumber],@ErrorMessage [ErrorMessage],@Detail [Detail];
        SELECT
              [DatabaseName],[StatusCode],[IsPartial],[RowCount]
            , [RequiredPermission],[ErrorNumber],[ErrorMessage],[Detail]
            , [JsonIndexStatusCode],[JsonIndexRowCount],[JsonPathRowCount]
            , [JsonIndexErrorNumber],[JsonIndexErrorMessage],[JsonIndexEvidenceLimit]
        FROM [#ObjectInventory_DatabaseStatus]
        ORDER BY [DatabaseName];
        IF @ResultSetArtNormalisiert='RAW' SELECT * FROM [#ObjectInventory_Result] ORDER BY [ObjectReservedMb] DESC,[DatabaseName],[SchemaName],[ObjectName],[IndexId]; ELSE SELECT N'Objekt-/Indexinventar' [Ergebnis],[r].* FROM [#ObjectInventory_Result] [r] ORDER BY [ObjectReservedMb] DESC,[DatabaseName],[SchemaName],[ObjectName],[IndexId];
    END;
    IF @JsonErzeugen=1 BEGIN
        DECLARE @JsonMeta nvarchar(max)=(SELECT @ModuleName [resultName],1 [schemaVersion],@CollectionTimeUtc [generatedAtUtc],@OverallStatus [statusCode],@IsPartial [isPartial],@TotalRows [rowCount] FOR JSON PATH,WITHOUT_ARRAY_WRAPPER,INCLUDE_NULL_VALUES);
        DECLARE @JsonDatabaseStatus nvarchar(max)=(SELECT * FROM [#ObjectInventory_DatabaseStatus] ORDER BY [DatabaseName] FOR JSON PATH,INCLUDE_NULL_VALUES);
        DECLARE @JsonData1 nvarchar(max)=(SELECT * FROM [#ObjectInventory_Result] ORDER BY [ObjectReservedMb] DESC,[DatabaseName],[SchemaName],[ObjectName],[IndexId] FOR JSON PATH,INCLUDE_NULL_VALUES);
        SET @Json=CONCAT(N'{"meta":',COALESCE(@JsonMeta,N'{}'),N',"objects":',COALESCE(@JsonData1,N'[]'),N',"databaseStatus":',COALESCE(@JsonDatabaseStatus,N'[]'),N'}');
    END;
    IF @ConsoleResultRequested = 1
    BEGIN
        EXEC [monitor].[InternalEmitConsoleResult]
              @SourceTable=N'#ObjectInventory_Result'
            , @ResultLabel=N'ObjectInventory'
            , @EmptyMessage=N'Keine fachlichen Ergebnisse';
    END;
    IF @TableResultRequested = 1
    BEGIN
        EXEC [monitor].[InternalWriteResultTable]
              @SourceTable = N'#ObjectInventory_Result'
            , @TargetTable=@TableTarget
            , @ThrowOnError = 1;
    END;
END;
GO
-- END SOURCE: Code/03_ObjectIndex/010_USP_ObjectInventory.sql

-- BEGIN SOURCE: Code/03_ObjectIndex/020_USP_IndexUsage.sql
/*
===============================================================================
Objekt       : monitor.USP_IndexUsage
Version      : 1.1.0
Stand        : 2026-07-14
Typ          : Stored Procedure
Zweck        : Liefert kumulative Indexnutzung seit dem letzten DMV-Reset und klassifiziert gelesene, schreiblastige sowie seit Reset ungenutzte Indizes.
SQL-Version  : SQL Server 2019 oder neuer.
Datenquellen : sys.dm_db_index_usage_stats, sys.dm_db_xtp_index_stats,
               sys.dm_os_sys_info sowie je Datenbank sys.objects, sys.tables,
               sys.schemas, sys.indexes, sys.hash_indexes und sys.partitions.
Parameter    :
  @DatabaseName                  sysname        = NULL  - Zieldatenbank; bei Einzelmodus Pflicht.
  @CrossDatabaseRequestedInternal               bit            = 0     - sichtbare Online-Datenbanken analysieren.
  @SystemdatenbankenEinbeziehen  bit            = 0     - master/model/msdb/tempdb einbeziehen.
  @DatenbankNameLike             nvarchar(256)  = NULL  - Filter im Cross-Database-Modus.
  @SchemaNamePattern                nvarchar(256)  = NULL  - LIKE-Filter auf Schema.
  @ObjectNamePattern                nvarchar(256)  = NULL  - LIKE-Filter auf Objekt.
  @MaxZeilen                     int            = 5000  - positive Werte begrenzen; NULL/0 = unbegrenzt.
  @LockTimeoutMs                 int            = 0     - 0 = nicht auf Metadatenlocks warten.
  @PrintMeldungen                bit            = 1     - Warnungen via RAISERROR 10.
  @Hilfe                         bit            = 0     - Hilfe via PRINT, keine Analyse.
  @AnalyseModus varchar(16) = 'GEZIELT' - GEZIELT benötigt Filter; VOLL prüft CATALOG_DEEP.
  @NurUngenutzt bit = 0 - nur seit Reset nicht gelesene Indizes.
  @MinUserUpdates bigint = 0 - Mindestzahl User-Updates.
  @PrimaryUndUniqueEinbeziehen bit = 1 - Constraint-Indizes einbeziehen.
  @MitMemoryOptimized bit = 1 - separaten In-Memory-OLTP-Resultset versuchen.
Resultsets   : 1. Modulstatus. 2. Status je Datenbank und Quelle.
               3. Rowstore-/Columnstore-/Spatial-Indexnutzung.
               4. In-Memory-OLTP-Indexnutzung.
Berechtigung : SQL Server 2019 VIEW SERVER STATE; SQL Server 2022+ VIEW SERVER PERFORMANCE STATE. Metadaten zusätzlich gemäß Sichtbarkeit.
Eigenlast    : Moderate DMV-/Katalogabfrage; keine Physical-Stats-Scans.
Locking      : DMV plus READUNCOMMITTED-Kataloge; LOCK_TIMEOUT konfigurierbar.
Partial      : Fehler je Datenbank bzw. Teilquelle werden isoliert; vorhandene
               Teilergebnisse bleiben erhalten. Das Framework vergibt keine Rechte.
Beispiele    :
  EXEC monitor.USP_IndexUsage @DatabaseNames=N'[SampleDatabase]', @ObjectNamePattern=N'like:Fact%';
  EXEC monitor.USP_IndexUsage @DatabaseNames=N'SampleDatabase', @AnalyseModus='VOLL', @NurUngenutzt=1, @MinUserUpdates=1000;
  EXEC monitor.USP_IndexUsage @Hilfe=1;
Änderungen   : 1.1.0 - Indexed Views, Spatial-Kennzeichnung und isolierter
               In-Memory-OLTP-Resultset ergänzt.
               1.0.0 - Erstfassung Phase 2.
===============================================================================
*/
CREATE OR ALTER PROCEDURE [monitor].[USP_IndexUsage]
      @DatabaseNames                  nvarchar(max)  = NULL
    , @SystemdatenbankenEinbeziehen   bit            = 0
    , @DatabaseNamePattern            nvarchar(4000) = NULL
    , @HighImpactConfirmed              bit            = 0
    , @SchemaNames                    nvarchar(max)  = NULL
    , @SchemaNamePattern              nvarchar(4000) = NULL
    , @ObjectNames                    nvarchar(max)  = NULL
    , @ObjectNamePattern              nvarchar(4000) = NULL
    , @FullObjectNames                nvarchar(max)  = NULL
    , @AnalyseModus                  varchar(16)   = 'GEZIELT'
    , @NurUngenutzt                   bit           = 0
    , @MinUserUpdates                 bigint        = 0
    , @PrimaryUndUniqueEinbeziehen    bit           = 1
    , @MitMemoryOptimized              bit           = 1
    , @MaxZeilen                      int           = 5000
    , @LockTimeoutMs                  int           = 0
    , @ResultSetArt                  varchar(16)    = 'CONSOLE'
    , @ResultTablesJson               nvarchar(max) = NULL
    , @JsonErzeugen                  bit            = 0
    , @Json                          nvarchar(max)  = NULL OUTPUT
    , @PrintMeldungen                 bit           = 1
    , @Hilfe                          bit           = 0
AS
BEGIN
    SET NOCOUNT ON;

    SET @Json = NULL;
    DECLARE @ResultSetArtNormalisiert varchar(16)=UPPER(LTRIM(RTRIM(COALESCE(@ResultSetArt,''))));
    DECLARE @TableResultRequested bit = CASE WHEN @ResultSetArtNormalisiert = 'TABLE' THEN 1 ELSE 0 END;
    DECLARE @ConsoleResultRequested bit = CASE WHEN @ResultSetArtNormalisiert = 'CONSOLE' THEN 1 ELSE 0 END;
    DECLARE @TableTarget sysname=NULL;
    IF @TableResultRequested=0 AND NULLIF(LTRIM(RTRIM(COALESCE(@ResultTablesJson,N''))),N'') IS NOT NULL THROW 51011,N'@ResultTablesJson ist ausschließlich mit @ResultSetArt=TABLE zulässig.',1;
    IF @TableResultRequested=1 EXEC [monitor].[InternalPrepareSingleResultTable] @ResultTablesJson=@ResultTablesJson,@ResultName=N'rowstoreIndexes',@TargetTable=@TableTarget OUTPUT,@ThrowOnError=1;
    IF @TableResultRequested = 1 OR @ConsoleResultRequested = 1 SET @ResultSetArtNormalisiert = 'NONE';
    DECLARE @DatabaseName sysname=NULL,@CrossDatabaseRequestedInternal bit=0,@DatenbankNameLike nvarchar(4000)=NULL;
    DECLARE @SchemaNameLike nvarchar(4000)=NULL,@ObjectNameLike nvarchar(4000)=NULL;
    DECLARE @SchemaPatternMode varchar(8),@SchemaPatternValue nvarchar(4000),@SchemaRegexFlags varchar(8),@SchemaPatternValid bit;
    DECLARE @ObjectPatternMode varchar(8),@ObjectPatternValue nvarchar(4000),@ObjectRegexFlags varchar(8),@ObjectPatternValid bit;
    SELECT @SchemaPatternMode=[PatternMode],@SchemaPatternValue=[PatternValue],@SchemaRegexFlags=[RegexFlags],@SchemaPatternValid=[IsValid] FROM [monitor].[TVF_ParsePattern](@SchemaNamePattern);
    SELECT @ObjectPatternMode=[PatternMode],@ObjectPatternValue=[PatternValue],@ObjectRegexFlags=[RegexFlags],@ObjectPatternValid=[IsValid] FROM [monitor].[TVF_ParsePattern](@ObjectNamePattern);
    IF @SchemaPatternMode='LIKE' SET @SchemaNameLike=@SchemaPatternValue;
    IF @ObjectPatternMode='LIKE' SET @ObjectNameLike=@ObjectPatternValue;
    DECLARE @IndexPatternMode varchar(8)='NONE',@IndexPatternValue nvarchar(4000)=NULL,@IndexRegexFlags varchar(8)=NULL,@IndexPatternValid bit=1;
    DECLARE @StatisticsPatternMode varchar(8)='NONE',@StatisticsPatternValue nvarchar(4000)=NULL,@StatisticsRegexFlags varchar(8)=NULL,@StatisticsPatternValid bit=1;
    DECLARE @DatabaseListCount int=0;
    IF @DatabaseNames IS NOT NULL AND NULLIF(LTRIM(RTRIM(@DatabaseNames)),N'') IS NOT NULL
        SELECT @DatabaseListCount=COUNT(*),@DatabaseName=MIN([NameValue]) FROM [monitor].[TVF_ParseSqlNameList](@DatabaseNames) WHERE [IsValid]=1;
    SET @CrossDatabaseRequestedInternal=CONVERT(bit,CASE WHEN @DatabaseNames IS NULL OR @DatabaseNamePattern IS NOT NULL OR @DatabaseListCount>1 THEN 1 ELSE 0 END);
    SELECT @DatenbankNameLike=CASE WHEN [PatternMode]='LIKE' THEN [PatternValue] END FROM [monitor].[TVF_ParsePattern](@DatabaseNamePattern);
    CREATE TABLE [#IndexUsage_NameFilters]([FilterType] varchar(20) COLLATE SQL_Latin1_General_CP1_CS_AS NOT NULL,[ItemOrdinal] int NOT NULL,[NameValue] sysname COLLATE SQL_Latin1_General_CP1_CS_AS NULL,[DatabaseName] sysname COLLATE SQL_Latin1_General_CP1_CS_AS NULL,[SchemaName] sysname COLLATE SQL_Latin1_General_CP1_CS_AS NULL,[ObjectName] sysname COLLATE SQL_Latin1_General_CP1_CS_AS NULL);
    CREATE TABLE [#IndexUsage_DatabaseCandidates]([DatabaseId] int NOT NULL,[DatabaseName] sysname NOT NULL,[StateDesc] nvarchar(60),[UserAccessDesc] nvarchar(60),[IsReadOnly] bit,[CompatibilityLevel] tinyint,[CollationName] sysname,[RecoveryModelDesc] nvarchar(60),[IsSystemDatabase] bit,[RequestedOrdinal] int);
    DECLARE @FilterStatus varchar(40)='AVAILABLE',@FilterError nvarchar(2048)=NULL,@CrossDatabaseRequested bit=0;
    EXEC [monitor].[USP_PrepareNameFilters] @SchemaNames=@SchemaNames,@ObjectNames=@ObjectNames,@FullObjectNames=@FullObjectNames,@IndexNames=NULL,@StatisticsNames=NULL,@ColumnNames=NULL,@StatusCode=@FilterStatus OUTPUT,@ErrorMessage=@FilterError OUTPUT,@FilterTable=N'#IndexUsage_NameFilters';
    IF @FilterStatus='AVAILABLE' EXEC [monitor].[USP_PrepareDatabaseCandidates] @DatabaseNames=@DatabaseNames,@SystemdatenbankenEinbeziehen=@SystemdatenbankenEinbeziehen,@DatabaseNamePattern=@DatabaseNamePattern,@HighImpactConfirmed=@HighImpactConfirmed,@AnalysisClass='OBJECT_ANALYSIS_CURRENT',@StatusCode=@FilterStatus OUTPUT,@ErrorMessage=@FilterError OUTPUT,@CrossDatabaseRequested=@CrossDatabaseRequested OUTPUT,@CandidateTable=N'#IndexUsage_DatabaseCandidates';
    IF @FilterStatus='AVAILABLE' AND UPPER(LTRIM(RTRIM(COALESCE(@AnalyseModus,''))))='VOLL'
        EXEC [monitor].[InternalCheckAnalysisPath] @AnalysisClass='CATALOG_DEEP',@HighImpactConfirmed=@HighImpactConfirmed,@StatusCode=@FilterStatus OUTPUT,@ErrorMessage=@FilterError OUTPUT;
    DECLARE @SchemaPredicateS nvarchar(max),@SchemaPredicateSch nvarchar(max),@ObjectPredicateO nvarchar(max),@FullObjectPredicateSO nvarchar(max),@IndexPredicateI nvarchar(max),@StatisticsPredicateSt nvarchar(max);
    SET @SchemaPredicateS=N' AND (NOT EXISTS(SELECT 1 FROM [#IndexUsage_NameFilters] WHERE [FilterType]=''SCHEMA'') OR EXISTS(SELECT 1 FROM [#IndexUsage_NameFilters] [f] WHERE [f].[FilterType]=''SCHEMA'' AND [f].[NameValue]=[s].[name] COLLATE SQL_Latin1_General_CP1_CS_AS))';
    SET @SchemaPredicateSch=REPLACE(@SchemaPredicateS,N'[s].[name]',N'[sch].[name]');
    SET @ObjectPredicateO=N' AND (NOT EXISTS(SELECT 1 FROM [#IndexUsage_NameFilters] WHERE [FilterType]=''OBJECT'') OR EXISTS(SELECT 1 FROM [#IndexUsage_NameFilters] [f] WHERE [f].[FilterType]=''OBJECT'' AND [f].[NameValue]=[o].[name] COLLATE SQL_Latin1_General_CP1_CS_AS))';
    SET @FullObjectPredicateSO=N' AND (NOT EXISTS(SELECT 1 FROM [#IndexUsage_NameFilters] WHERE [FilterType]=''FULL_OBJECT'') OR EXISTS(SELECT 1 FROM [#IndexUsage_NameFilters] [f] WHERE [f].[FilterType]=''FULL_OBJECT'' AND ([f].[DatabaseName] IS NULL OR [f].[DatabaseName]=@pDbName COLLATE SQL_Latin1_General_CP1_CS_AS) AND ([f].[SchemaName] IS NULL OR [f].[SchemaName]=[s].[name] COLLATE SQL_Latin1_General_CP1_CS_AS) AND [f].[ObjectName]=[o].[name] COLLATE SQL_Latin1_General_CP1_CS_AS))';
    SET @IndexPredicateI=N' AND (NOT EXISTS(SELECT 1 FROM [#IndexUsage_NameFilters] WHERE [FilterType]=''INDEX'') OR EXISTS(SELECT 1 FROM [#IndexUsage_NameFilters] [f] WHERE [f].[FilterType]=''INDEX'' AND [f].[NameValue]=[i].[name] COLLATE SQL_Latin1_General_CP1_CS_AS))';
    SET @StatisticsPredicateSt=N' AND (NOT EXISTS(SELECT 1 FROM [#IndexUsage_NameFilters] WHERE [FilterType]=''STATISTICS'') OR EXISTS(SELECT 1 FROM [#IndexUsage_NameFilters] [f] WHERE [f].[FilterType]=''STATISTICS'' AND [f].[NameValue]=[st].[name] COLLATE SQL_Latin1_General_CP1_CS_AS))';
    IF @SchemaPatternMode='LIKE' BEGIN SET @SchemaPredicateS+=N' AND [s].[name] COLLATE SQL_Latin1_General_CP1_CS_AS LIKE N'''+REPLACE(@SchemaPatternValue,N'''',N'''''')+N''' COLLATE SQL_Latin1_General_CP1_CS_AS';SET @SchemaPredicateSch+=N' AND [sch].[name] COLLATE SQL_Latin1_General_CP1_CS_AS LIKE N'''+REPLACE(@SchemaPatternValue,N'''',N'''''')+N''' COLLATE SQL_Latin1_General_CP1_CS_AS';END;
    IF @SchemaPatternMode IN('REGEX','REGEXI') BEGIN SET @SchemaPredicateS+=N' AND REGEXP_LIKE([s].[name],N'''+REPLACE(@SchemaPatternValue,N'''',N'''''')+N''','''+@SchemaRegexFlags+N''')';SET @SchemaPredicateSch+=N' AND REGEXP_LIKE([sch].[name],N'''+REPLACE(@SchemaPatternValue,N'''',N'''''')+N''','''+@SchemaRegexFlags+N''')';END;
    IF @ObjectPatternMode='LIKE' SET @ObjectPredicateO+=N' AND [o].[name] COLLATE SQL_Latin1_General_CP1_CS_AS LIKE N'''+REPLACE(@ObjectPatternValue,N'''',N'''''')+N''' COLLATE SQL_Latin1_General_CP1_CS_AS';
    IF @ObjectPatternMode IN('REGEX','REGEXI') SET @ObjectPredicateO+=N' AND REGEXP_LIKE([o].[name],N'''+REPLACE(@ObjectPatternValue,N'''',N'''''')+N''','''+@ObjectRegexFlags+N''')';
    IF @IndexPatternMode='LIKE' SET @IndexPredicateI+=N' AND [i].[name] COLLATE SQL_Latin1_General_CP1_CS_AS LIKE N'''+REPLACE(@IndexPatternValue,N'''',N'''''')+N''' COLLATE SQL_Latin1_General_CP1_CS_AS';
    IF @IndexPatternMode IN('REGEX','REGEXI') SET @IndexPredicateI+=N' AND REGEXP_LIKE([i].[name],N'''+REPLACE(@IndexPatternValue,N'''',N'''''')+N''','''+@IndexRegexFlags+N''')';
    IF @StatisticsPatternMode='LIKE' SET @StatisticsPredicateSt+=N' AND [st].[name] COLLATE SQL_Latin1_General_CP1_CS_AS LIKE N'''+REPLACE(@StatisticsPatternValue,N'''',N'''''')+N''' COLLATE SQL_Latin1_General_CP1_CS_AS';
    IF @StatisticsPatternMode IN('REGEX','REGEXI') SET @StatisticsPredicateSt+=N' AND REGEXP_LIKE([st].[name],N'''+REPLACE(@StatisticsPatternValue,N'''',N'''''')+N''','''+@StatisticsRegexFlags+N''')';
    DECLARE @EffectiveMaxZeilen bigint = CASE WHEN @MaxZeilen IS NULL OR @MaxZeilen=0 THEN CONVERT(bigint,9223372036854775807) ELSE CONVERT(bigint,@MaxZeilen) END;
    DECLARE @MonitorPrintMessage nvarchar(2048);
    SET @AnalyseModus=UPPER(LTRIM(RTRIM(COALESCE(@AnalyseModus,'GEZIELT'))));
    IF @Hilfe=1
    BEGIN
        PRINT N'monitor.USP_IndexUsage';        PRINT N'@DatabaseNames: exakter Name oder bracket-aware Pipe-Liste; NULL = alle zulässigen Datenbanken; N'''' = keine Einschränkung.';        PRINT N'@SystemdatenbankenEinbeziehen bit = 0: Systemdatenbanken einbeziehen.';        PRINT N'Exakte Listen und ...NamePattern sind gegenseitig exklusiv. Pattern: LIKE (Default/like:), regex: oder regexi:.';
        PRINT N'Datenbankauswahl ohne Vorabbegrenzung; @MaxZeilen int: harte Ergebnismengenbegrenzung.';
        PRINT N'@LockTimeoutMs int = 0: Metadatenzugriff wartet standardmäßig nicht auf Locks.';
        PRINT N'@PrintMeldungen bit = 1: strukturierte Warnungen zusätzlich in der Console.';
        PRINT N'Die Procedure liefert die kumulative Indexnutzung seit dem DMV-Reset und keine Ausführungshistorie.';
        PRINT N'@AnalyseModus varchar(16) = GEZIELT: GEZIELT benötigt Schema-/Objektfilter; VOLL prüft CATALOG_DEEP.';
        PRINT N'@NurUngenutzt bit = 0: nur Indizes ohne User Seek/Scan/Lookup seit Reset.';
        PRINT N'@MinUserUpdates bigint = 0: Mindestanzahl Schreiboperationen.';
        PRINT N'@PrimaryUndUniqueEinbeziehen bit = 1: PK-/Unique-Constraint-Indizes einbeziehen.';
        PRINT N'@MitMemoryOptimized bit = 1: sys.dm_db_xtp_index_stats als isolierten vierten Resultset ausgeben.';
        PRINT N'@MinUserUpdates ist auf den Rowstore-Resultset beschränkt; die XTP-DMV besitzt keinen vergleichbaren Update-Counter.';
        PRINT N'Beispiel: EXEC monitor.USP_IndexUsage @DatabaseNames=N''[DWH]'', @ObjectNamePattern=N''like:Fact%'', @NurUngenutzt=1;';
        PRINT N'@Hilfe bit = 0: 1 zeigt diese Hilfe und führt keine Analyse aus.';
        RETURN;
    END;

    DECLARE @ModuleName sysname = N'USP_IndexUsage';
    DECLARE @CollectionTimeUtc datetime2(3) = SYSUTCDATETIME();

    DECLARE @OverallStatus varchar(40) = 'AVAILABLE';
    DECLARE @IsPartial bit = 0;
    DECLARE @TotalRows bigint = 0;
    DECLARE @ErrorNumber int = NULL;
    DECLARE @ErrorMessage nvarchar(2048) = NULL;
    DECLARE @Detail nvarchar(2000) = NULL;

    CREATE TABLE [#IndexUsage_DatabaseStatus]
    (
          [DatabaseName]       sysname        NULL
        , [StatusCode]         varchar(40)    NOT NULL
        , [IsPartial]          bit            NOT NULL
        , [RowCount]           bigint         NOT NULL
        , [RequiredPermission] nvarchar(256)  NULL
        , [ErrorNumber]        int            NULL
        , [ErrorMessage]       nvarchar(2048) NULL
        , [Detail]             nvarchar(2000) NULL
    );

    IF @FilterStatus<>'AVAILABLE' BEGIN SET @OverallStatus=@FilterStatus;SET @ErrorMessage=@FilterError;END;
    IF @ResultSetArtNormalisiert NOT IN('RAW','CONSOLE','NONE') BEGIN SET @OverallStatus='INVALID_PARAMETER';SET @ErrorMessage=N'@ResultSetArt muss CONSOLE, RAW, TABLE oder NONE enthalten.';END;
    IF @SchemaPatternValid=0 OR @ObjectPatternValid=0 OR @IndexPatternValid=0 OR @StatisticsPatternValid=0 OR (@SchemaNames IS NOT NULL AND @SchemaNamePattern IS NOT NULL) OR (@ObjectNames IS NOT NULL AND @ObjectNamePattern IS NOT NULL) BEGIN SET @OverallStatus='INVALID_PARAMETER';SET @ErrorMessage=N'Exakte Liste und Pattern derselben Eigenschaft sind gegenseitig exklusiv.';END;
IF @MaxZeilen<0 OR @LockTimeoutMs NOT BETWEEN 0 AND 60000
    BEGIN
        SET @OverallStatus = 'INVALID_PARAMETER';
        SET @ErrorMessage = N'Ungültiger Parameter: @MaxZeilen oder @LockTimeoutMs außerhalb des zulässigen Bereichs.';
    END


    IF @OverallStatus <> 'AVAILABLE'
    BEGIN
        INSERT [#IndexUsage_DatabaseStatus]([DatabaseName], [StatusCode], [IsPartial], [RowCount], [RequiredPermission], [ErrorNumber], [ErrorMessage], [Detail])
        VALUES(@DatabaseName, @OverallStatus, 1, 0, NULL, NULL, @ErrorMessage, N'Keine Datenbankanalyse ausgeführt.');
        SET @IsPartial = 1;
    END
    ELSE
    BEGIN
        SET LOCK_TIMEOUT 0;
    END;

    DECLARE @CatalogAllowed bit=1;
    IF @AnalyseModus='VOLL'
        SELECT @CatalogAllowed=COALESCE(MAX(CONVERT(tinyint,[IsAllowed])),0)
        FROM [monitor].[VW_AnalyseAccessCurrent]
        WHERE [AnalysisClass]='CATALOG_DEEP';

    CREATE TABLE [#IndexUsage_Result]
    (
          [DatabaseName]           sysname        NOT NULL
        , [SchemaName]             sysname        NOT NULL
        , [ObjectName]             sysname        NOT NULL
        , [ObjectId]               int            NOT NULL
        , [IndexId]                int            NOT NULL
        , [IndexName]              sysname        NULL
        , [IndexTypeDesc]          nvarchar(60)   NULL
        , [IsMemoryOptimized]      bit            NOT NULL
        , [IsSpatialIndex]         bit            NOT NULL
        , [IsPrimaryKey]           bit            NULL
        , [IsUniqueConstraint]     bit            NULL
        , [IsDisabled]             bit            NULL
        , [RowCount]               bigint         NULL
        , [UserSeeks]              bigint         NOT NULL
        , [UserScans]              bigint         NOT NULL
        , [UserLookups]            bigint         NOT NULL
        , [UserUpdates]            bigint         NOT NULL
        , [TotalUserReads]         bigint         NOT NULL
        , [ReadWriteRatio]         decimal(19,4)  NULL
        , [LastUserSeek]           datetime       NULL
        , [LastUserScan]           datetime       NULL
        , [LastUserLookup]         datetime       NULL
        , [LastUserUpdate]         datetime       NULL
        , [SystemSeeks]            bigint         NOT NULL
        , [SystemScans]            bigint         NOT NULL
        , [SystemLookups]          bigint         NOT NULL
        , [SystemUpdates]          bigint         NOT NULL
        , [DmvResetTimeServerLocal]  datetime2(3)   NULL
        , [UsageClassification]    varchar(48)    NOT NULL
    );

    CREATE TABLE [#IndexUsage_XtpResult]
    (
          [DatabaseName]           sysname        NOT NULL
        , [SchemaName]             sysname        NOT NULL
        , [ObjectName]             sysname        NOT NULL
        , [ObjectId]               int            NOT NULL
        , [IndexId]                int            NOT NULL
        , [IndexName]              sysname        NULL
        , [IndexTypeDesc]          nvarchar(60)   NULL
        , [IsPrimaryKey]           bit            NULL
        , [IsUniqueConstraint]     bit            NULL
        , [BucketCount]            bigint         NULL
        , [ScansStarted]           bigint         NOT NULL
        , [ScansRetries]           bigint         NOT NULL
        , [RowsReturned]           bigint         NOT NULL
        , [RowsTouched]            bigint         NOT NULL
        , [RowsReturnedPerScan]    decimal(28,4)  NULL
        , [RowsTouchedPerReturned] decimal(28,4)  NULL
        , [RetryPercent]           decimal(19,4)  NULL
        , [CounterScope]           nvarchar(200)  NOT NULL
        , [UsageClassification]    varchar(48)    NOT NULL
    );

    IF @OverallStatus='AVAILABLE' AND @MinUserUpdates < 0
    BEGIN SET @OverallStatus='INVALID_PARAMETER'; SET @ErrorMessage=N'@MinUserUpdates darf nicht negativ sein.'; INSERT [#IndexUsage_DatabaseStatus] VALUES(@DatabaseName,@OverallStatus,1,0,NULL,NULL,@ErrorMessage,NULL); END
    ELSE IF @OverallStatus='AVAILABLE' AND @AnalyseModus NOT IN ('GEZIELT','VOLL')
    BEGIN SET @OverallStatus='INVALID_PARAMETER'; SET @ErrorMessage=N'@AnalyseModus muss GEZIELT oder VOLL sein.'; INSERT [#IndexUsage_DatabaseStatus] VALUES(@DatabaseName,@OverallStatus,1,0,NULL,NULL,@ErrorMessage,NULL); END
    ELSE IF @OverallStatus='AVAILABLE' AND @AnalyseModus='GEZIELT' AND NOT EXISTS(SELECT 1 FROM [#IndexUsage_NameFilters]) AND @SchemaNamePattern IS NULL AND @ObjectNamePattern IS NULL
    BEGIN SET @OverallStatus='INVALID_PARAMETER'; SET @ErrorMessage=N'GEZIELT erfordert eine exakte Namensliste, @FullObjectNames oder ein Schema-/Objekt-Pattern. Für den vollständigen Lauf @AnalyseModus=''VOLL'' verwenden.'; INSERT [#IndexUsage_DatabaseStatus] VALUES(@DatabaseName,@OverallStatus,1,0,NULL,NULL,@ErrorMessage,NULL); END
    ELSE IF @OverallStatus='AVAILABLE' AND @AnalyseModus='VOLL' AND @CatalogAllowed=0
    BEGIN SET @OverallStatus='DENIED_GROUP'; SET @ErrorMessage=N'CATALOG_DEEP ist für die vollständige Index-Usage-Analyse nicht freigegeben.'; INSERT [#IndexUsage_DatabaseStatus] VALUES(@DatabaseName,@OverallStatus,1,0,NULL,NULL,@ErrorMessage,NULL); END
    ELSE IF @OverallStatus='AVAILABLE'
    BEGIN
        DECLARE @DbId int,@DbName sysname,@Sql nvarchar(max),@Rows bigint;
        DECLARE dbcur CURSOR LOCAL FAST_FORWARD FOR SELECT [DatabaseId],[DatabaseName] FROM [#IndexUsage_DatabaseCandidates];
        OPEN dbcur; FETCH NEXT FROM dbcur INTO @DbId,@DbName;
        WHILE @@FETCH_STATUS=0
        BEGIN
            BEGIN TRY
                SET @Sql = N'SET LOCK_TIMEOUT ' + CONVERT(nvarchar(11), @LockTimeoutMs) + N'; USE ' + QUOTENAME(@DbName) + N';
;WITH BaseRows AS
(
 SELECT [p].[object_id],[p].[index_id],SUM([p].[rows]) AS [RowCount]
 FROM sys.partitions AS [p] WITH (NOLOCK)
 GROUP BY [p].[object_id],[p].[index_id]
)
INSERT #IndexUsage_Result
SELECT TOP (@pMaxRows)
 @pDbName,[s].[name],[o].[name],[o].[object_id],[i].[index_id],[i].[name],[i].[type_desc],
 CONVERT(bit,COALESCE([t].[is_memory_optimized],0)),CONVERT(bit,CASE WHEN [i].[type]=4 THEN 1 ELSE 0 END),
 [i].[is_primary_key],[i].[is_unique_constraint],[i].[is_disabled],[br].[RowCount],
 COALESCE([u].[user_seeks],0),COALESCE([u].[user_scans],0),COALESCE([u].[user_lookups],0),COALESCE([u].[user_updates],0),
 COALESCE([u].[user_seeks],0)+COALESCE([u].[user_scans],0)+COALESCE([u].[user_lookups],0),
 CONVERT(decimal(19,4),(COALESCE([u].[user_seeks],0)+COALESCE([u].[user_scans],0)+COALESCE([u].[user_lookups],0))*1.0/NULLIF(COALESCE([u].[user_updates],0),0)),
 [u].[last_user_seek],[u].[last_user_scan],[u].[last_user_lookup],[u].[last_user_update],
 COALESCE([u].[system_seeks],0),COALESCE([u].[system_scans],0),COALESCE([u].[system_lookups],0),COALESCE([u].[system_updates],0),
 [osi].[sqlserver_start_time],
 CASE WHEN [i].[is_disabled]=1 THEN ''DISABLED''
      WHEN [i].[type]=4 THEN ''SPATIAL_NOT_IN_USAGE_DMV''
      WHEN [u].[index_id] IS NULL THEN ''NO_DMV_ROW''
      WHEN COALESCE([u].[user_seeks],0)+COALESCE([u].[user_scans],0)+COALESCE([u].[user_lookups],0)=0 AND COALESCE([u].[user_updates],0)>0 THEN ''WRITE_ONLY_SINCE_RESET''
      WHEN COALESCE([u].[user_seeks],0)+COALESCE([u].[user_scans],0)+COALESCE([u].[user_lookups],0)=0 THEN ''UNUSED_SINCE_RESET''
      WHEN COALESCE([u].[user_updates],0)=0 THEN ''READ_ONLY_SINCE_RESET'' ELSE ''READ_AND_WRITE'' END
FROM sys.objects AS [o] WITH (NOLOCK)
JOIN sys.schemas AS [s] WITH (NOLOCK) ON [s].[schema_id]=[o].[schema_id]
LEFT JOIN sys.tables AS [t] WITH (NOLOCK) ON [t].[object_id]=[o].[object_id]
JOIN sys.indexes AS [i] WITH (NOLOCK) ON [i].[object_id]=[o].[object_id]
LEFT JOIN BaseRows AS [br] ON [br].[object_id]=[i].[object_id] AND [br].[index_id]=[i].[index_id]
LEFT JOIN sys.dm_db_index_usage_stats AS [u] WITH (NOLOCK) ON [u].[database_id]=@pDbId AND [u].[object_id]=[i].[object_id] AND [u].[index_id]=[i].[index_id]
CROSS JOIN sys.dm_os_sys_info AS [osi] WITH (NOLOCK)
WHERE [o].[type] IN (''U'',''V'') AND [o].[is_ms_shipped]=0 AND [i].[index_id]>0 AND [i].[is_hypothetical]=0
  AND COALESCE([t].[is_memory_optimized],0)=0
'+@SchemaPredicateS+@ObjectPredicateO+@FullObjectPredicateSO+N'
  AND (@pIncludeConstraints=1 OR ([i].[is_primary_key]=0 AND [i].[is_unique_constraint]=0))
  AND COALESCE([u].[user_updates],0)>=@pMinUpdates
  AND (@pOnlyUnused=0 OR COALESCE([u].[user_seeks],0)+COALESCE([u].[user_scans],0)+COALESCE([u].[user_lookups],0)=0)
ORDER BY COALESCE([u].[user_updates],0) DESC,[br].[RowCount] DESC
OPTION (MAXDOP 1, RECOMPILE);';
                EXEC [sys].[sp_executesql] @Sql,N'@pDbName sysname,@pDbId int,@pMaxRows bigint,@pSchemaLike nvarchar(256),@pObjectLike nvarchar(256),@pIncludeConstraints bit,@pMinUpdates bigint,@pOnlyUnused bit',@pDbName=@DbName,@pDbId=@DbId,@pMaxRows=@EffectiveMaxZeilen,@pSchemaLike=@SchemaNameLike,@pObjectLike=@ObjectNameLike,@pIncludeConstraints=@PrimaryUndUniqueEinbeziehen,@pMinUpdates=@MinUserUpdates,@pOnlyUnused=@NurUngenutzt;
                SELECT @Rows=COUNT_BIG(*) FROM [#IndexUsage_Result] WHERE [DatabaseName]=@DbName; INSERT [#IndexUsage_DatabaseStatus] VALUES(@DbName,'AVAILABLE',0,@Rows,CASE WHEN TRY_CONVERT([int],SERVERPROPERTY(N'ProductMajorVersion'))>=16 THEN N'VIEW SERVER PERFORMANCE STATE' ELSE N'VIEW SERVER STATE' END,NULL,NULL,N'Kumulative Werte; Resetzeit näherungsweise SQL-Server-Start.');
            END TRY
            BEGIN CATCH
                INSERT [#IndexUsage_DatabaseStatus] VALUES(@DbName,CASE WHEN ERROR_NUMBER() IN (229,262,297,300,371,916) THEN 'DENIED_PERMISSION' WHEN ERROR_NUMBER()=1222 THEN 'TIMEOUT' ELSE 'ERROR_HANDLED' END,1,0,CASE WHEN TRY_CONVERT([int],SERVERPROPERTY(N'ProductMajorVersion'))>=16 THEN N'VIEW SERVER PERFORMANCE STATE' ELSE N'VIEW SERVER STATE' END,ERROR_NUMBER(),ERROR_MESSAGE(),N'DMV-/Katalogfehler isoliert.');
            END CATCH;

            IF @MitMemoryOptimized = 1
            BEGIN
                BEGIN TRY
                    SET @Sql = N'SET LOCK_TIMEOUT ' + CONVERT(nvarchar(11), @LockTimeoutMs) + N'; USE ' + QUOTENAME(@DbName) + N';
INSERT #IndexUsage_XtpResult
SELECT TOP (@pMaxRows)
       @pDbName,[s].[name],[o].[name],[o].[object_id],[i].[index_id],[i].[name],[i].[type_desc],
       [i].[is_primary_key],[i].[is_unique_constraint],[hi].[bucket_count],
       [xs].[scans_started],[xs].[scans_retries],[xs].[rows_returned],[xs].[rows_touched],
       CONVERT(decimal(28,4),[xs].[rows_returned]*1.0/NULLIF([xs].[scans_started],0)),
       CONVERT(decimal(28,4),[xs].[rows_touched]*1.0/NULLIF([xs].[rows_returned],0)),
       CONVERT(decimal(19,4),[xs].[scans_retries]*100.0/NULLIF([xs].[scans_started],0)),
       N''Seit Datenbankneustart beziehungsweise seit Erzeugung der Tabelle; nicht persistent.'',
       CASE WHEN [xs].[scans_started]=0 THEN ''NO_SCANS_SINCE_DB_RESTART''
            WHEN [xs].[scans_retries]>0 THEN ''SCAN_RETRIES_OCCURRED''
            WHEN [xs].[rows_touched]>[xs].[rows_returned]*10 AND [xs].[rows_returned]>0 THEN ''HIGH_ROWS_TOUCHED_RATIO''
            ELSE ''ACTIVE'' END
FROM sys.dm_db_xtp_index_stats AS [xs] WITH (NOLOCK)
JOIN sys.objects AS [o] WITH (NOLOCK) ON [o].[object_id]=CONVERT(int,[xs].[object_id])
JOIN sys.schemas AS [s] WITH (NOLOCK) ON [s].[schema_id]=[o].[schema_id]
JOIN sys.tables AS [tb] WITH (NOLOCK) ON [tb].[object_id]=[o].[object_id] AND [tb].[is_memory_optimized]=1
JOIN sys.indexes AS [i] WITH (NOLOCK) ON [i].[object_id]=[o].[object_id] AND [i].[index_id]=CONVERT(int,[xs].[index_id])
LEFT JOIN sys.hash_indexes AS [hi] WITH (NOLOCK) ON [hi].[object_id]=[i].[object_id] AND [hi].[index_id]=[i].[index_id]
WHERE 1=1'+@SchemaPredicateS+@ObjectPredicateO+@FullObjectPredicateSO+N'
  AND (@pIncludeConstraints=1 OR ([i].[is_primary_key]=0 AND [i].[is_unique_constraint]=0))
  AND (@pOnlyUnused=0 OR [xs].[scans_started]=0)
ORDER BY [xs].[scans_started] DESC,[xs].[rows_touched] DESC
OPTION (MAXDOP 1,RECOMPILE);';
                    EXEC [sys].[sp_executesql] @Sql,
                         N'@pDbName sysname,@pMaxRows bigint,@pSchemaLike nvarchar(256),@pObjectLike nvarchar(256),@pIncludeConstraints bit,@pOnlyUnused bit',
                         @pDbName=@DbName,@pMaxRows=@EffectiveMaxZeilen,@pSchemaLike=@SchemaNameLike,@pObjectLike=@ObjectNameLike,
                         @pIncludeConstraints=@PrimaryUndUniqueEinbeziehen,@pOnlyUnused=@NurUngenutzt;
                    SELECT @Rows=COUNT_BIG(*) FROM [#IndexUsage_XtpResult] WHERE [DatabaseName]=@DbName;
                    INSERT [#IndexUsage_DatabaseStatus] VALUES(@DbName,'AVAILABLE',0,@Rows,
                         CASE WHEN TRY_CONVERT([int],SERVERPROPERTY(N'ProductMajorVersion'))>=16 THEN N'VIEW DATABASE PERFORMANCE STATE' ELSE N'VIEW DATABASE STATE' END,
                         NULL,NULL,N'Quelle XTP_INDEX_USAGE erfolgreich gelesen.');
                END TRY
                BEGIN CATCH
                    INSERT [#IndexUsage_DatabaseStatus] VALUES(@DbName,
                         CASE WHEN ERROR_NUMBER() IN (229,262,297,300,371,916) THEN 'DENIED_PERMISSION' WHEN ERROR_NUMBER()=1222 THEN 'TIMEOUT' WHEN ERROR_NUMBER() IN (207,208,4121) THEN 'UNAVAILABLE_OBJECT' ELSE 'ERROR_HANDLED' END,
                         1,0,CASE WHEN TRY_CONVERT([int],SERVERPROPERTY(N'ProductMajorVersion'))>=16 THEN N'VIEW DATABASE PERFORMANCE STATE' ELSE N'VIEW DATABASE STATE' END,
                         ERROR_NUMBER(),ERROR_MESSAGE(),N'Quelle XTP_INDEX_USAGE fehlgeschlagen; Rowstore-Ergebnis bleibt erhalten.');
                END CATCH;
            END;

            FETCH NEXT FROM dbcur INTO @DbId,@DbName;
        END; CLOSE dbcur; DEALLOCATE dbcur;
        IF NOT EXISTS(SELECT 1 FROM [#IndexUsage_DatabaseStatus]) INSERT [#IndexUsage_DatabaseStatus] VALUES(@DatabaseName,'DATABASE_UNAVAILABLE',1,0,NULL,NULL,N'Keine sichtbare Online-Zieldatenbank gefunden.',NULL);
    END;



    SELECT @TotalRows=(SELECT COUNT_BIG(*) FROM [#IndexUsage_Result])+(SELECT COUNT_BIG(*) FROM [#IndexUsage_XtpResult]);

    IF @OverallStatus = 'AVAILABLE'
    BEGIN
        IF EXISTS (SELECT 1 FROM [#IndexUsage_DatabaseStatus] WHERE [StatusCode] NOT IN ('AVAILABLE','AVAILABLE_LIMITED','SKIPPED','NOT_APPLICABLE'))
        BEGIN
            SET @OverallStatus = CASE WHEN @TotalRows > 0 THEN 'PARTIAL' ELSE (SELECT TOP (1) [StatusCode] FROM [#IndexUsage_DatabaseStatus] WHERE [StatusCode] NOT IN ('AVAILABLE','AVAILABLE_LIMITED','SKIPPED','NOT_APPLICABLE') ORDER BY [DatabaseName]) END;
            SET @IsPartial = 1;
        END
        ELSE IF EXISTS (SELECT 1 FROM [#IndexUsage_DatabaseStatus] WHERE [StatusCode] IN ('AVAILABLE_LIMITED','SKIPPED','NOT_APPLICABLE'))
        BEGIN
            SET @OverallStatus = CASE WHEN @TotalRows > 0 THEN 'AVAILABLE_LIMITED' ELSE 'SKIPPED' END;
            SET @IsPartial = 1;
        END;
    END;

    IF @PrintMeldungen = 1 AND @OverallStatus <> 'AVAILABLE'
        BEGIN
    SET @MonitorPrintMessage = FORMATMESSAGE(N'WARNUNG %s: %s', @OverallStatus, COALESCE(@ErrorMessage, @Detail, N'Teilergebnis oder eingeschränkte Sicht'));
    RAISERROR(N'%s', 10, 1, @MonitorPrintMessage) WITH NOWAIT;
END;

    IF @ResultSetArtNormalisiert<>'NONE' BEGIN
        SELECT @ModuleName [ModuleName],@CollectionTimeUtc [CollectionTimeUtc],@OverallStatus [StatusCode],@IsPartial [IsPartial],@TotalRows [RowCount],@ErrorNumber [ErrorNumber],@ErrorMessage [ErrorMessage],@Detail [Detail];
        SELECT [DatabaseName],[StatusCode],[IsPartial],[RowCount],[RequiredPermission],[ErrorNumber],[ErrorMessage],[Detail] FROM [#IndexUsage_DatabaseStatus] ORDER BY [DatabaseName];
        IF @ResultSetArtNormalisiert='RAW' SELECT * FROM [#IndexUsage_Result] ORDER BY [UserUpdates] DESC,[TotalUserReads] ASC,[DatabaseName],[SchemaName],[ObjectName],[IndexId]; ELSE SELECT N'Indexnutzung' [Ergebnis],[r].* FROM [#IndexUsage_Result] [r] ORDER BY [UserUpdates] DESC,[TotalUserReads] ASC,[DatabaseName],[SchemaName],[ObjectName],[IndexId];
        IF @ResultSetArtNormalisiert='RAW' SELECT * FROM [#IndexUsage_XtpResult] ORDER BY [ScansStarted] DESC,[RowsTouched] DESC,[DatabaseName],[SchemaName],[ObjectName],[IndexId]; ELSE SELECT N'Indexnutzung' [Ergebnis],[r].* FROM [#IndexUsage_XtpResult] [r] ORDER BY [ScansStarted] DESC,[RowsTouched] DESC,[DatabaseName],[SchemaName],[ObjectName],[IndexId];
    END;
    IF @JsonErzeugen=1 BEGIN
        DECLARE @JsonMeta nvarchar(max)=(SELECT @ModuleName [resultName],1 [schemaVersion],@CollectionTimeUtc [generatedAtUtc],@OverallStatus [statusCode],@IsPartial [isPartial],@TotalRows [rowCount] FOR JSON PATH,WITHOUT_ARRAY_WRAPPER,INCLUDE_NULL_VALUES);
        DECLARE @JsonDatabaseStatus nvarchar(max)=(SELECT * FROM [#IndexUsage_DatabaseStatus] ORDER BY [DatabaseName] FOR JSON PATH,INCLUDE_NULL_VALUES);
        DECLARE @JsonData1 nvarchar(max)=(SELECT * FROM [#IndexUsage_Result] ORDER BY [UserUpdates] DESC,[TotalUserReads] ASC,[DatabaseName],[SchemaName],[ObjectName],[IndexId] FOR JSON PATH,INCLUDE_NULL_VALUES);
        DECLARE @JsonData2 nvarchar(max)=(SELECT * FROM [#IndexUsage_XtpResult] ORDER BY [ScansStarted] DESC,[RowsTouched] DESC,[DatabaseName],[SchemaName],[ObjectName],[IndexId] FOR JSON PATH,INCLUDE_NULL_VALUES);
        SET @Json=CONCAT(N'{"meta":',COALESCE(@JsonMeta,N'{}'),N',"rowstoreIndexes":',COALESCE(@JsonData1,N'[]'),N',"memoryOptimizedIndexes":',COALESCE(@JsonData2,N'[]'),N',"databaseStatus":',COALESCE(@JsonDatabaseStatus,N'[]'),N'}');
    END;
    IF @ConsoleResultRequested = 1
    BEGIN
        EXEC [monitor].[InternalEmitConsoleResult]
              @SourceTable=N'#IndexUsage_Result'
            , @ResultLabel=N'IndexUsage'
            , @EmptyMessage=N'Keine fachlichen Ergebnisse';
    END;
    IF @TableResultRequested = 1
    BEGIN
        EXEC [monitor].[InternalWriteResultTable]
              @SourceTable = N'#IndexUsage_Result'
            , @TargetTable=@TableTarget
            , @ThrowOnError = 1;
    END;
END;
GO
-- END SOURCE: Code/03_ObjectIndex/020_USP_IndexUsage.sql

-- BEGIN SOURCE: Code/03_ObjectIndex/025_USP_IndexOperationalStats.sql
SET QUOTED_IDENTIFIER ON;
GO

/*
===============================================================================
Objekt       : monitor.USP_IndexOperationalStats
Version      : 1.1.0
Stand        : 2026-07-14
Typ          : Stored Procedure
Zweck        : Analysiert aktuelle kumulative Zugriffs-, Lock-, Latch-, I/O-
               Latch-, Page-Split- und Lock-Eskalationszähler je Indexpartition.
SQL-Version  : SQL Server 2019 oder neuer.
Datenquellen : sys.dm_db_index_operational_stats sowie sys.objects, sys.schemas,
               sys.indexes und sys.tables der jeweiligen Zieldatenbank.
Parameter    :
  @DatabaseNames nvarchar(max) = NULL - Zieldatenbank; im Einzelmodus Pflicht.
  @CrossDatabaseRequestedInternal bit = 0 - Cross-Database; CROSS_DATABASE_DEEP erforderlich.
  @SystemdatenbankenEinbeziehen bit = 0 - Systemdatenbanken einbeziehen.
  @DatenbankNameLike nvarchar(256) = NULL - Datenbank-LIKE-Filter.
  @SchemaNamePattern nvarchar(256) = NULL - GEZIELT: exakter Schemaname (Equality); VOLL: LIKE.
  @ObjectNamePattern nvarchar(256) = NULL - GEZIELT: exakter Objektname (Equality); VOLL: LIKE.
  @IndexNamePattern nvarchar(256) = NULL - optionaler Index-LIKE-Filter.
  @AnalyseModus varchar(16) = 'GEZIELT' - GEZIELT genau ein Objekt; VOLL
               prüft INDEX_OPERATIONAL_DEEP und kann die Datenbank breit lesen.
  @PartitionNumber int = NULL - nur GEZIELT; NULL = alle Partitionen des Objekts.
  @NurMitAktivitaet bit = 1 - nur Zeilen mit wenigstens einem relevanten Counter.
  @MinLeafPageAllocations bigint = 0 - Mindestzahl Leaf-Page-Allokationen.
  @MinLockWaitMs bigint = 0 - Mindestwartezeit aus Row- und Page-Locks.
  @MaxZeilen int = 5000 - positive Werte begrenzen; NULL/0 = unbegrenzt; begrenzt Ausgabe, nicht DMF-Arbeit.
  @LockTimeoutMs int = 0 - 0 bis 60000; begrenzt Lock-Wartezeit.
  @PrintMeldungen bit = 1 - Warnungen via RAISERROR Severity 10.
  @Hilfe bit = 0 - Hilfe via PRINT; keine Analyse.
Resultsets   : 1. Modulstatus. 2. Status je Datenbank. 3. Operational Stats.
Berechtigung : GEZIELT: CONTROL auf dem Objekt oder ausreichender Database-State-
               Zugriff. VOLL: SQL 2019 VIEW DATABASE STATE, SQL 2022+
               VIEW DATABASE PERFORMANCE STATE. Keine Rechtevergabe.
Eigenlast    : GEZIELT ruft die DMF für genau ein zuvor sicher aufgelöstes Objekt
               auf. VOLL kann alle Heap-/B-Tree-/Columnstore-Rowsets lesen und ist
               deshalb explizit gruppengeschützt. TOP reduziert nicht zwingend
               die DMF-Arbeit.
Locking      : Rein lesend, kann Metadaten-/Objektzugriffe auslösen; LOCK_TIMEOUT
               begrenzt Warten. Memory-optimized Indizes sind nicht enthalten und
               werden über USP_IndexUsage/XTP separat analysiert.
Partial      : Datenbankfehler werden isoliert. Ein nicht auflösbares Zielobjekt
               wird niemals als NULL-Wildcard an die DMF übergeben.
Beispiele    :
  EXEC monitor.USP_IndexOperationalStats @DatabaseNames=N'SampleDatabase',
       @SchemaNamePattern=N'dbo', @ObjectNamePattern=N'FactSales';
  EXEC monitor.USP_IndexOperationalStats @DatabaseNames=N'SampleDatabase',
       @AnalyseModus='VOLL', @ObjectNamePattern=N'Fact%', @MaxZeilen=10000;
  EXEC monitor.USP_IndexOperationalStats @Hilfe=1;
Änderungen   : 1.1.0 - Exakte Equality-Auflösung erlaubt Unterstriche und andere reguläre Namenszeichen.
               1.0.0 - Erstfassung Phase 2.
===============================================================================
*/
CREATE OR ALTER PROCEDURE [monitor].[USP_IndexOperationalStats]
      @DatabaseNames                  nvarchar(max)  = NULL
    , @SystemdatenbankenEinbeziehen   bit            = 0
    , @DatabaseNamePattern            nvarchar(4000) = NULL
    , @HighImpactConfirmed              bit            = 0
    , @SchemaNames                    nvarchar(max)  = NULL
    , @SchemaNamePattern              nvarchar(4000) = NULL
    , @ObjectNames                    nvarchar(max)  = NULL
    , @ObjectNamePattern              nvarchar(4000) = NULL
    , @FullObjectNames                nvarchar(max)  = NULL
    , @IndexNames                     nvarchar(max)  = NULL
    , @IndexNamePattern               nvarchar(4000) = NULL
    , @AnalyseModus                varchar(16)   = 'GEZIELT'
    , @PartitionNumber             int           = NULL
    , @NurMitAktivitaet            bit           = 1
    , @MinLeafPageAllocations      bigint        = 0
    , @MinLockWaitMs               bigint        = 0
    , @MaxZeilen                   int           = 5000
    , @LockTimeoutMs               int           = 0
    , @ResultSetArt                  varchar(16)    = 'CONSOLE'
    , @ResultTablesJson               nvarchar(max) = NULL
    , @JsonErzeugen                  bit            = 0
    , @Json                          nvarchar(max)  = NULL OUTPUT
    , @PrintMeldungen              bit           = 1
    , @Hilfe                       bit           = 0
AS
BEGIN
    SET NOCOUNT ON;

    SET @Json = NULL;
    DECLARE @ResultSetArtNormalisiert varchar(16)=UPPER(LTRIM(RTRIM(COALESCE(@ResultSetArt,''))));
    DECLARE @TableResultRequested bit = CASE WHEN @ResultSetArtNormalisiert = 'TABLE' THEN 1 ELSE 0 END;
    DECLARE @ConsoleResultRequested bit = CASE WHEN @ResultSetArtNormalisiert = 'CONSOLE' THEN 1 ELSE 0 END;
    DECLARE @TableTarget sysname=NULL;
    IF @TableResultRequested=0 AND NULLIF(LTRIM(RTRIM(COALESCE(@ResultTablesJson,N''))),N'') IS NOT NULL THROW 51011,N'@ResultTablesJson ist ausschließlich mit @ResultSetArt=TABLE zulässig.',1;
    IF @TableResultRequested=1 EXEC [monitor].[InternalPrepareSingleResultTable] @ResultTablesJson=@ResultTablesJson,@ResultName=N'indexOperationalStats',@TargetTable=@TableTarget OUTPUT,@ThrowOnError=1;
    IF @TableResultRequested = 1 OR @ConsoleResultRequested = 1 SET @ResultSetArtNormalisiert = 'NONE';
    DECLARE @DatabaseName sysname=NULL,@CrossDatabaseRequestedInternal bit=0,@DatenbankNameLike nvarchar(4000)=NULL;
    DECLARE @SchemaNameLike nvarchar(4000)=NULL,@ObjectNameLike nvarchar(4000)=NULL;
    DECLARE @IndexNameLike nvarchar(4000)=NULL;
    DECLARE @SchemaPatternMode varchar(8),@SchemaPatternValue nvarchar(4000),@SchemaRegexFlags varchar(8),@SchemaPatternValid bit;
    DECLARE @ObjectPatternMode varchar(8),@ObjectPatternValue nvarchar(4000),@ObjectRegexFlags varchar(8),@ObjectPatternValid bit;
    SELECT @SchemaPatternMode=[PatternMode],@SchemaPatternValue=[PatternValue],@SchemaRegexFlags=[RegexFlags],@SchemaPatternValid=[IsValid] FROM [monitor].[TVF_ParsePattern](@SchemaNamePattern);
    SELECT @ObjectPatternMode=[PatternMode],@ObjectPatternValue=[PatternValue],@ObjectRegexFlags=[RegexFlags],@ObjectPatternValid=[IsValid] FROM [monitor].[TVF_ParsePattern](@ObjectNamePattern);
    IF @SchemaPatternMode='LIKE' SET @SchemaNameLike=@SchemaPatternValue;
    IF @ObjectPatternMode='LIKE' SET @ObjectNameLike=@ObjectPatternValue;
    DECLARE @IndexPatternMode varchar(8),@IndexPatternValue nvarchar(4000),@IndexRegexFlags varchar(8),@IndexPatternValid bit;
    SELECT @IndexPatternMode=[PatternMode],@IndexPatternValue=[PatternValue],@IndexRegexFlags=[RegexFlags],@IndexPatternValid=[IsValid] FROM [monitor].[TVF_ParsePattern](@IndexNamePattern);
    IF @IndexPatternMode='LIKE' SET @IndexNameLike=@IndexPatternValue;
    DECLARE @StatisticsPatternMode varchar(8)='NONE',@StatisticsPatternValue nvarchar(4000)=NULL,@StatisticsRegexFlags varchar(8)=NULL,@StatisticsPatternValid bit=1;
    DECLARE @DatabaseListCount int=0;
    IF @DatabaseNames IS NOT NULL AND NULLIF(LTRIM(RTRIM(@DatabaseNames)),N'') IS NOT NULL
        SELECT @DatabaseListCount=COUNT(*),@DatabaseName=MIN([NameValue]) FROM [monitor].[TVF_ParseSqlNameList](@DatabaseNames) WHERE [IsValid]=1;
    SET @CrossDatabaseRequestedInternal=CONVERT(bit,CASE WHEN @DatabaseNames IS NULL OR @DatabaseNamePattern IS NOT NULL OR @DatabaseListCount>1 THEN 1 ELSE 0 END);
    SELECT @DatenbankNameLike=CASE WHEN [PatternMode]='LIKE' THEN [PatternValue] END FROM [monitor].[TVF_ParsePattern](@DatabaseNamePattern);
    CREATE TABLE [#IndexOperationalStats_NameFilters]([FilterType] varchar(20) COLLATE SQL_Latin1_General_CP1_CS_AS NOT NULL,[ItemOrdinal] int NOT NULL,[NameValue] sysname COLLATE SQL_Latin1_General_CP1_CS_AS NULL,[DatabaseName] sysname COLLATE SQL_Latin1_General_CP1_CS_AS NULL,[SchemaName] sysname COLLATE SQL_Latin1_General_CP1_CS_AS NULL,[ObjectName] sysname COLLATE SQL_Latin1_General_CP1_CS_AS NULL);
    CREATE TABLE [#IndexOperationalStats_DatabaseCandidates]([DatabaseId] int NOT NULL,[DatabaseName] sysname NOT NULL,[StateDesc] nvarchar(60),[UserAccessDesc] nvarchar(60),[IsReadOnly] bit,[CompatibilityLevel] tinyint,[CollationName] sysname,[RecoveryModelDesc] nvarchar(60),[IsSystemDatabase] bit,[RequestedOrdinal] int);
    DECLARE @FilterStatus varchar(40)='AVAILABLE',@FilterError nvarchar(2048)=NULL,@CrossDatabaseRequested bit=0;
    EXEC [monitor].[USP_PrepareNameFilters] @SchemaNames=@SchemaNames,@ObjectNames=@ObjectNames,@FullObjectNames=@FullObjectNames,@IndexNames=@IndexNames,@StatisticsNames=NULL,@ColumnNames=NULL,@StatusCode=@FilterStatus OUTPUT,@ErrorMessage=@FilterError OUTPUT,@FilterTable=N'#IndexOperationalStats_NameFilters';
    IF @FilterStatus='AVAILABLE' EXEC [monitor].[USP_PrepareDatabaseCandidates] @DatabaseNames=@DatabaseNames,@SystemdatenbankenEinbeziehen=@SystemdatenbankenEinbeziehen,@DatabaseNamePattern=@DatabaseNamePattern,@HighImpactConfirmed=@HighImpactConfirmed,@AnalysisClass='OBJECT_ANALYSIS_CURRENT',@StatusCode=@FilterStatus OUTPUT,@ErrorMessage=@FilterError OUTPUT,@CrossDatabaseRequested=@CrossDatabaseRequested OUTPUT,@CandidateTable=N'#IndexOperationalStats_DatabaseCandidates';
    IF @FilterStatus='AVAILABLE' AND UPPER(LTRIM(RTRIM(COALESCE(@AnalyseModus,''))))='VOLL'
        EXEC [monitor].[InternalCheckAnalysisPath] @AnalysisClass='INDEX_OPERATIONAL_DEEP',@HighImpactConfirmed=@HighImpactConfirmed,@StatusCode=@FilterStatus OUTPUT,@ErrorMessage=@FilterError OUTPUT;
    DECLARE @SchemaPredicateS nvarchar(max),@SchemaPredicateSch nvarchar(max),@ObjectPredicateO nvarchar(max),@FullObjectPredicateSO nvarchar(max),@IndexPredicateI nvarchar(max),@StatisticsPredicateSt nvarchar(max);
    SET @SchemaPredicateS=N' AND (NOT EXISTS(SELECT 1 FROM [#IndexOperationalStats_NameFilters] WHERE [FilterType]=''SCHEMA'') OR EXISTS(SELECT 1 FROM [#IndexOperationalStats_NameFilters] [f] WHERE [f].[FilterType]=''SCHEMA'' AND [f].[NameValue]=[s].[name] COLLATE SQL_Latin1_General_CP1_CS_AS))';
    SET @SchemaPredicateSch=REPLACE(@SchemaPredicateS,N'[s].[name]',N'[sch].[name]');
    SET @ObjectPredicateO=N' AND (NOT EXISTS(SELECT 1 FROM [#IndexOperationalStats_NameFilters] WHERE [FilterType]=''OBJECT'') OR EXISTS(SELECT 1 FROM [#IndexOperationalStats_NameFilters] [f] WHERE [f].[FilterType]=''OBJECT'' AND [f].[NameValue]=[o].[name] COLLATE SQL_Latin1_General_CP1_CS_AS))';
    SET @FullObjectPredicateSO=N' AND (NOT EXISTS(SELECT 1 FROM [#IndexOperationalStats_NameFilters] WHERE [FilterType]=''FULL_OBJECT'') OR EXISTS(SELECT 1 FROM [#IndexOperationalStats_NameFilters] [f] WHERE [f].[FilterType]=''FULL_OBJECT'' AND ([f].[DatabaseName] IS NULL OR [f].[DatabaseName]=@pDbName COLLATE SQL_Latin1_General_CP1_CS_AS) AND ([f].[SchemaName] IS NULL OR [f].[SchemaName]=[s].[name] COLLATE SQL_Latin1_General_CP1_CS_AS) AND [f].[ObjectName]=[o].[name] COLLATE SQL_Latin1_General_CP1_CS_AS))';
    SET @IndexPredicateI=N' AND (NOT EXISTS(SELECT 1 FROM [#IndexOperationalStats_NameFilters] WHERE [FilterType]=''INDEX'') OR EXISTS(SELECT 1 FROM [#IndexOperationalStats_NameFilters] [f] WHERE [f].[FilterType]=''INDEX'' AND [f].[NameValue]=[i].[name] COLLATE SQL_Latin1_General_CP1_CS_AS))';
    SET @StatisticsPredicateSt=N' AND (NOT EXISTS(SELECT 1 FROM [#IndexOperationalStats_NameFilters] WHERE [FilterType]=''STATISTICS'') OR EXISTS(SELECT 1 FROM [#IndexOperationalStats_NameFilters] [f] WHERE [f].[FilterType]=''STATISTICS'' AND [f].[NameValue]=[st].[name] COLLATE SQL_Latin1_General_CP1_CS_AS))';
    IF @SchemaPatternMode='LIKE' BEGIN SET @SchemaPredicateS+=N' AND [s].[name] COLLATE SQL_Latin1_General_CP1_CS_AS LIKE N'''+REPLACE(@SchemaPatternValue,N'''',N'''''')+N''' COLLATE SQL_Latin1_General_CP1_CS_AS';SET @SchemaPredicateSch+=N' AND [sch].[name] COLLATE SQL_Latin1_General_CP1_CS_AS LIKE N'''+REPLACE(@SchemaPatternValue,N'''',N'''''')+N''' COLLATE SQL_Latin1_General_CP1_CS_AS';END;
    IF @SchemaPatternMode IN('REGEX','REGEXI') BEGIN SET @SchemaPredicateS+=N' AND REGEXP_LIKE([s].[name],N'''+REPLACE(@SchemaPatternValue,N'''',N'''''')+N''','''+@SchemaRegexFlags+N''')';SET @SchemaPredicateSch+=N' AND REGEXP_LIKE([sch].[name],N'''+REPLACE(@SchemaPatternValue,N'''',N'''''')+N''','''+@SchemaRegexFlags+N''')';END;
    IF @ObjectPatternMode='LIKE' SET @ObjectPredicateO+=N' AND [o].[name] COLLATE SQL_Latin1_General_CP1_CS_AS LIKE N'''+REPLACE(@ObjectPatternValue,N'''',N'''''')+N''' COLLATE SQL_Latin1_General_CP1_CS_AS';
    IF @ObjectPatternMode IN('REGEX','REGEXI') SET @ObjectPredicateO+=N' AND REGEXP_LIKE([o].[name],N'''+REPLACE(@ObjectPatternValue,N'''',N'''''')+N''','''+@ObjectRegexFlags+N''')';
    IF @IndexPatternMode='LIKE' SET @IndexPredicateI+=N' AND [i].[name] COLLATE SQL_Latin1_General_CP1_CS_AS LIKE N'''+REPLACE(@IndexPatternValue,N'''',N'''''')+N''' COLLATE SQL_Latin1_General_CP1_CS_AS';
    IF @IndexPatternMode IN('REGEX','REGEXI') SET @IndexPredicateI+=N' AND REGEXP_LIKE([i].[name],N'''+REPLACE(@IndexPatternValue,N'''',N'''''')+N''','''+@IndexRegexFlags+N''')';
    IF @StatisticsPatternMode='LIKE' SET @StatisticsPredicateSt+=N' AND [st].[name] COLLATE SQL_Latin1_General_CP1_CS_AS LIKE N'''+REPLACE(@StatisticsPatternValue,N'''',N'''''')+N''' COLLATE SQL_Latin1_General_CP1_CS_AS';
    IF @StatisticsPatternMode IN('REGEX','REGEXI') SET @StatisticsPredicateSt+=N' AND REGEXP_LIKE([st].[name],N'''+REPLACE(@StatisticsPatternValue,N'''',N'''''')+N''','''+@StatisticsRegexFlags+N''')';
    DECLARE @EffectiveMaxZeilen bigint = CASE WHEN @MaxZeilen IS NULL OR @MaxZeilen=0 THEN CONVERT(bigint,9223372036854775807) ELSE CONVERT(bigint,@MaxZeilen) END;
    DECLARE @MonitorPrintMessage nvarchar(2048);
    SET @AnalyseModus=UPPER(LTRIM(RTRIM(COALESCE(@AnalyseModus,'GEZIELT'))));

    IF @Hilfe=1
    BEGIN
        PRINT N'monitor.USP_IndexOperationalStats';
        PRINT N'Die Procedure liefert kumulative Zugriffs-, Lock-, Latch-, I/O-Latch-, Page-Split- und Eskalationszähler je Indexpartition.';
        PRINT N'@DatabaseNames nvarchar(max) = NULL: im Einzelmodus Pflicht.';        PRINT N'@SystemdatenbankenEinbeziehen bit = 0; @DatenbankNameLike nvarchar(256) = NULL.';
        PRINT N'@SchemaNamePattern/@ObjectNamePattern: GEZIELT benötigt beide und vergleicht per Equality; Zeichen wie Unterstrich sind zulässig. VOLL behandelt sie als LIKE-Filter.';
        PRINT N'@IndexNamePattern nvarchar(256) = NULL: optionaler LIKE-Filter.';
        PRINT N'@AnalyseModus varchar(16) = GEZIELT: VOLL erfordert INDEX_OPERATIONAL_DEEP.';
        PRINT N'@PartitionNumber int = NULL: nur im GEZIELT-Modus.';
        PRINT N'@NurMitAktivitaet bit = 1; @MinLeafPageAllocations bigint = 0; @MinLockWaitMs bigint = 0.';
        PRINT N'Datenbankauswahl ohne Vorabbegrenzung; @MaxZeilen int = 5000; @LockTimeoutMs int = 0.';
        PRINT N'@PrintMeldungen bit = 1; @Hilfe bit = 0.';
        PRINT N'Beispiel: EXEC monitor.USP_IndexOperationalStats @DatabaseNames=N''DWH'', @SchemaNamePattern=N''dbo'', @ObjectNamePattern=N''FactSales'';';
        RETURN;
    END;

    DECLARE @ModuleName sysname=N'USP_IndexOperationalStats',
            @CollectionTimeUtc datetime2(3)=SYSUTCDATETIME(),
            @OverallStatus varchar(40)='AVAILABLE',
            @IsPartial bit=0,
            @TotalRows bigint=0,
            @ErrorNumber int=NULL,
            @ErrorMessage nvarchar(2048)=NULL,
            @Detail nvarchar(2000)=NULL,
            @OperationalDeepAllowed bit=1;

    CREATE TABLE [#IndexOperationalStats_DatabaseStatus]
    (
          [DatabaseName] sysname NULL, [StatusCode] varchar(40) NOT NULL,
          [IsPartial] bit NOT NULL, [RowCount] bigint NOT NULL,
          [RequiredPermission] nvarchar(256) NULL, [ErrorNumber] int NULL,
          [ErrorMessage] nvarchar(2048) NULL, [Detail] nvarchar(2000) NULL
    );

    CREATE TABLE [#IndexOperationalStats_Result]
    (
          [DatabaseName] sysname NOT NULL, [SchemaName] sysname NULL,
          [ObjectName] sysname NULL, [ObjectId] int NOT NULL,
          [IsMemoryOptimized] bit NULL, [IndexId] int NOT NULL,
          [IndexName] sysname NULL, [IndexTypeDesc] nvarchar(60) NULL,
          [PartitionNumber] int NOT NULL, [HobtId] bigint NULL,
          [LeafInsertCount] bigint NOT NULL, [LeafDeleteCount] bigint NOT NULL,
          [LeafUpdateCount] bigint NOT NULL, [LeafGhostCount] bigint NOT NULL,
          [LeafPageAllocationCount] bigint NOT NULL, [NonleafPageAllocationCount] bigint NOT NULL,
          [LeafPageMergeCount] bigint NOT NULL, [RangeScanCount] bigint NOT NULL,
          [SingletonLookupCount] bigint NOT NULL, [ForwardedFetchCount] bigint NOT NULL,
          [LobFetchPages] bigint NOT NULL, [RowOverflowFetchPages] bigint NOT NULL,
          [RowLockCount] bigint NOT NULL, [RowLockWaitCount] bigint NOT NULL,
          [RowLockWaitMs] bigint NOT NULL, [PageLockCount] bigint NOT NULL,
          [PageLockWaitCount] bigint NOT NULL, [PageLockWaitMs] bigint NOT NULL,
          [LockPromotionAttemptCount] bigint NOT NULL, [LockPromotionCount] bigint NOT NULL,
          [PageLatchWaitCount] bigint NOT NULL, [PageLatchWaitMs] bigint NOT NULL,
          [PageIoLatchWaitCount] bigint NOT NULL, [PageIoLatchWaitMs] bigint NOT NULL,
          [TreePageLatchWaitCount] bigint NOT NULL, [TreePageLatchWaitMs] bigint NOT NULL,
          [PageCompressionAttemptCount] bigint NOT NULL, [PageCompressionSuccessCount] bigint NOT NULL,
          [LeafAllocationsPerInsert] decimal(19,6) NULL,
          [LockWaitMsPerWait] decimal(19,4) NULL,
          [PageLatchWaitMsPerWait] decimal(19,4) NULL,
          [PageIoLatchWaitMsPerWait] decimal(19,4) NULL,
          [UsageClassification] varchar(48) NOT NULL
    );
    IF @AnalyseModus='VOLL'
        SELECT @OperationalDeepAllowed=COALESCE(MAX(CONVERT(tinyint,[IsAllowed])),0)
        FROM [monitor].[VW_AnalyseAccessCurrent] WHERE [AnalysisClass]='INDEX_OPERATIONAL_DEEP';

    IF @FilterStatus<>'AVAILABLE' BEGIN SET @OverallStatus=@FilterStatus;SET @ErrorMessage=@FilterError;END;
    IF @ResultSetArtNormalisiert NOT IN('RAW','CONSOLE','NONE') BEGIN SET @OverallStatus='INVALID_PARAMETER';SET @ErrorMessage=N'@ResultSetArt muss CONSOLE, RAW, TABLE oder NONE enthalten.';END;
    IF @SchemaPatternValid=0 OR @ObjectPatternValid=0 OR @IndexPatternValid=0 OR @StatisticsPatternValid=0 OR (@SchemaNames IS NOT NULL AND @SchemaNamePattern IS NOT NULL) OR (@ObjectNames IS NOT NULL AND @ObjectNamePattern IS NOT NULL) OR (@IndexNames IS NOT NULL AND @IndexNamePattern IS NOT NULL) BEGIN SET @OverallStatus='INVALID_PARAMETER';SET @ErrorMessage=N'Exakte Liste und Pattern derselben Eigenschaft sind gegenseitig exklusiv.';END;
    IF @MaxZeilen<0 OR @LockTimeoutMs NOT BETWEEN 0 AND 60000
       OR @MinLeafPageAllocations<0 OR @MinLockWaitMs<0 OR (@PartitionNumber IS NOT NULL AND @PartitionNumber<1)
    BEGIN SET @OverallStatus='INVALID_PARAMETER'; SET @ErrorMessage=N'Numerischer Parameter außerhalb des zulässigen Bereichs.'; END
    ELSE IF @AnalyseModus NOT IN ('GEZIELT','VOLL')
    BEGIN SET @OverallStatus='INVALID_PARAMETER'; SET @ErrorMessage=N'@AnalyseModus muss GEZIELT oder VOLL sein.'; END
    ELSE IF @AnalyseModus='GEZIELT'
         AND NOT EXISTS(SELECT 1 FROM [#IndexOperationalStats_NameFilters] WHERE [FilterType]='FULL_OBJECT')
         AND (NOT EXISTS(SELECT 1 FROM [#IndexOperationalStats_NameFilters] WHERE [FilterType]='SCHEMA')
              OR NOT EXISTS(SELECT 1 FROM [#IndexOperationalStats_NameFilters] WHERE [FilterType]='OBJECT'))
    BEGIN SET @OverallStatus='INVALID_PARAMETER'; SET @ErrorMessage=N'GEZIELT benötigt @FullObjectNames oder exakte @SchemaNames und @ObjectNames.'; END
    ELSE IF @AnalyseModus='VOLL' AND @OperationalDeepAllowed=0
    BEGIN SET @OverallStatus='DENIED_GROUP'; SET @ErrorMessage=N'INDEX_OPERATIONAL_DEEP ist nicht freigegeben.'; END
    ELSE IF @AnalyseModus='VOLL' AND @PartitionNumber IS NOT NULL
    BEGIN SET @OverallStatus='INVALID_PARAMETER'; SET @ErrorMessage=N'@PartitionNumber ist nur im GEZIELT-Modus zulässig.'; END;

    IF @OverallStatus<>'AVAILABLE'
    BEGIN
        INSERT [#IndexOperationalStats_DatabaseStatus] VALUES(@DatabaseName,@OverallStatus,1,0,NULL,NULL,@ErrorMessage,N'Keine DMF-Abfrage ausgeführt.');
        SET @IsPartial=1;
    END
    ELSE
    BEGIN
        SET LOCK_TIMEOUT 0;
        DECLARE @DbId int,@DbName sysname,@Sql nvarchar(max),@Rows bigint;
        DECLARE dbcur CURSOR LOCAL FAST_FORWARD FOR
            SELECT [DatabaseId],[DatabaseName]
            FROM [#IndexOperationalStats_DatabaseCandidates];
        OPEN dbcur; FETCH NEXT FROM dbcur INTO @DbId,@DbName;
        WHILE @@FETCH_STATUS=0
        BEGIN
            BEGIN TRY
                SET @Sql = N'SET LOCK_TIMEOUT ' + CONVERT(nvarchar(11), @LockTimeoutMs) + N'; USE ' + QUOTENAME(@DbName) + N';
DECLARE @ObjectIdFilter int=NULL;
IF @pMode=''GEZIELT''
BEGIN
    SELECT @ObjectIdFilter=[o].[object_id]
    FROM sys.objects AS [o] WITH (NOLOCK)
    JOIN sys.schemas AS [s] WITH (NOLOCK) ON [s].[schema_id]=[o].[schema_id]
    WHERE [o].[type] IN (''U'',''V'')'+@SchemaPredicateS+@ObjectPredicateO+@FullObjectPredicateSO+N';
    IF @ObjectIdFilter IS NULL THROW 50001,N''Zielobjekt nicht gefunden oder nicht sichtbar; die DMF wird nicht mit NULL-Wildcard aufgerufen.'',1;
END;
INSERT #IndexOperationalStats_Result
SELECT TOP (@pMaxRows)
       @pDbName,[s].[name],[o].[name],[os].[object_id],[t].[is_memory_optimized],[os].[index_id],[i].[name],[i].[type_desc],
       [os].[partition_number],[os].[hobt_id],
       [os].[leaf_insert_count],[os].[leaf_delete_count],[os].[leaf_update_count],[os].[leaf_ghost_count],
       [os].[leaf_allocation_count],[os].[nonleaf_allocation_count],[os].[leaf_page_merge_count],
       [os].[range_scan_count],[os].[singleton_lookup_count],[os].[forwarded_fetch_count],
       [os].[lob_fetch_in_pages],[os].[row_overflow_fetch_in_pages],
       [os].[row_lock_count],[os].[row_lock_wait_count],[os].[row_lock_wait_in_ms],
       [os].[page_lock_count],[os].[page_lock_wait_count],[os].[page_lock_wait_in_ms],
       [os].[index_lock_promotion_attempt_count],[os].[index_lock_promotion_count],
       [os].[page_latch_wait_count],[os].[page_latch_wait_in_ms],
       [os].[page_io_latch_wait_count],[os].[page_io_latch_wait_in_ms],
       [os].[tree_page_latch_wait_count],[os].[tree_page_latch_wait_in_ms],
       [os].[page_compression_attempt_count],[os].[page_compression_success_count],
       CONVERT(decimal(19,6),[os].[leaf_allocation_count]*1.0/NULLIF([os].[leaf_insert_count],0)),
       CONVERT(decimal(19,4),([os].[row_lock_wait_in_ms]+[os].[page_lock_wait_in_ms])*1.0/NULLIF([os].[row_lock_wait_count]+[os].[page_lock_wait_count],0)),
       CONVERT(decimal(19,4),[os].[page_latch_wait_in_ms]*1.0/NULLIF([os].[page_latch_wait_count],0)),
       CONVERT(decimal(19,4),[os].[page_io_latch_wait_in_ms]*1.0/NULLIF([os].[page_io_latch_wait_count],0)),
       CASE WHEN [os].[index_lock_promotion_count]>0 THEN ''LOCK_ESCALATIONS''
            WHEN [os].[page_io_latch_wait_in_ms]>0 THEN ''PAGE_IO_LATCH_WAITS''
            WHEN [os].[page_latch_wait_in_ms]>0 THEN ''PAGE_LATCH_WAITS''
            WHEN [os].[row_lock_wait_in_ms]+[os].[page_lock_wait_in_ms]>0 THEN ''LOCK_WAITS''
            WHEN [os].[leaf_allocation_count]>0 THEN ''LEAF_PAGE_ALLOCATIONS''
            ELSE ''ACTIVITY_WITHOUT_CLASSIFIED_WAIT'' END
FROM sys.dm_db_index_operational_stats(@pDbId,@ObjectIdFilter,NULL,@pPartition) AS [os]
LEFT JOIN sys.objects AS [o] WITH (NOLOCK) ON [o].[object_id]=[os].[object_id]
LEFT JOIN sys.schemas AS [s] WITH (NOLOCK) ON [s].[schema_id]=[o].[schema_id]
LEFT JOIN sys.tables AS [t] WITH (NOLOCK) ON [t].[object_id]=[o].[object_id]
LEFT JOIN sys.indexes AS [i] WITH (NOLOCK) ON [i].[object_id]=[os].[object_id] AND [i].[index_id]=[os].[index_id]
WHERE 1=1'+@SchemaPredicateS+@ObjectPredicateO+@FullObjectPredicateSO+@IndexPredicateI+N'
  AND [os].[leaf_allocation_count]>=@pMinLeafAlloc
  AND [os].[row_lock_wait_in_ms]+[os].[page_lock_wait_in_ms]>=@pMinLockWaitMs
  AND (@pOnlyActivity=0 OR
       [os].[leaf_insert_count]+[os].[leaf_delete_count]+[os].[leaf_update_count]+[os].[leaf_ghost_count]+
       [os].[range_scan_count]+[os].[singleton_lookup_count]+[os].[row_lock_count]+[os].[page_lock_count]+
       [os].[page_latch_wait_count]+[os].[page_io_latch_wait_count]>0)
ORDER BY [os].[page_io_latch_wait_in_ms] DESC,[os].[page_latch_wait_in_ms] DESC,
         [os].[row_lock_wait_in_ms]+[os].[page_lock_wait_in_ms] DESC,[os].[leaf_allocation_count] DESC
OPTION (MAXDOP 1,RECOMPILE);';
                EXEC [sys].[sp_executesql] @Sql,
                     N'@pDbName sysname,@pDbId int,@pMode varchar(16),@pSchemaLike nvarchar(256),@pObjectLike nvarchar(256),@pIndexLike nvarchar(256),@pPartition int,@pMaxRows bigint,@pOnlyActivity bit,@pMinLeafAlloc bigint,@pMinLockWaitMs bigint',
                     @pDbName=@DbName,@pDbId=@DbId,@pMode=@AnalyseModus,@pSchemaLike=@SchemaNameLike,@pObjectLike=@ObjectNameLike,
                     @pIndexLike=@IndexNameLike,@pPartition=@PartitionNumber,@pMaxRows=@EffectiveMaxZeilen,@pOnlyActivity=@NurMitAktivitaet,
                     @pMinLeafAlloc=@MinLeafPageAllocations,@pMinLockWaitMs=@MinLockWaitMs;
                SELECT @Rows=COUNT_BIG(*) FROM [#IndexOperationalStats_Result] WHERE [DatabaseName]=@DbName;
                INSERT [#IndexOperationalStats_DatabaseStatus] VALUES(@DbName,'AVAILABLE',0,@Rows,
                    CASE WHEN @AnalyseModus='GEZIELT' THEN N'CONTROL am Zielobjekt oder Database-State-Recht'
                         WHEN TRY_CONVERT([int],SERVERPROPERTY(N'ProductMajorVersion'))>=16 THEN N'VIEW DATABASE PERFORMANCE STATE'
                         ELSE N'VIEW DATABASE STATE' END,
                    NULL,NULL,N'Kumulative Operational Stats erfolgreich gelesen; Counter können bei Metadata-Cache-Eviction zurückgesetzt werden.');
            END TRY
            BEGIN CATCH
                INSERT [#IndexOperationalStats_DatabaseStatus] VALUES(@DbName,
                    CASE WHEN ERROR_NUMBER()=50001 THEN 'UNAVAILABLE_OBJECT'
                         WHEN ERROR_NUMBER() IN (229,262,297,300,371,916) THEN 'DENIED_PERMISSION'
                         WHEN ERROR_NUMBER()=1222 THEN 'TIMEOUT'
                         WHEN ERROR_NUMBER() IN (207,208,4121) THEN 'UNAVAILABLE_OBJECT'
                         ELSE 'ERROR_HANDLED' END,
                    1,0,CASE WHEN @AnalyseModus='GEZIELT' THEN N'CONTROL am Zielobjekt oder Database-State-Recht'
                             WHEN TRY_CONVERT([int],SERVERPROPERTY(N'ProductMajorVersion'))>=16 THEN N'VIEW DATABASE PERFORMANCE STATE'
                             ELSE N'VIEW DATABASE STATE' END,
                    ERROR_NUMBER(),ERROR_MESSAGE(),N'Datenbank-/Objektfehler isoliert.');
            END CATCH;
            FETCH NEXT FROM dbcur INTO @DbId,@DbName;
        END;
        CLOSE dbcur; DEALLOCATE dbcur;
        IF NOT EXISTS(SELECT 1 FROM [#IndexOperationalStats_DatabaseStatus])
            INSERT [#IndexOperationalStats_DatabaseStatus] VALUES(@DatabaseName,'DATABASE_UNAVAILABLE',1,0,NULL,NULL,N'Keine sichtbare Online-Zieldatenbank gefunden.',NULL);
    END;


    SELECT @TotalRows=COUNT_BIG(*) FROM [#IndexOperationalStats_Result];
    IF @OverallStatus='AVAILABLE'
    BEGIN
        IF EXISTS(SELECT 1 FROM [#IndexOperationalStats_DatabaseStatus] WHERE [StatusCode] NOT IN ('AVAILABLE','AVAILABLE_LIMITED','SKIPPED','NOT_APPLICABLE'))
        BEGIN SET @OverallStatus=CASE WHEN @TotalRows>0 THEN 'PARTIAL' ELSE (SELECT TOP(1) [StatusCode] FROM [#IndexOperationalStats_DatabaseStatus] WHERE [StatusCode] NOT IN ('AVAILABLE','AVAILABLE_LIMITED','SKIPPED','NOT_APPLICABLE') ORDER BY [DatabaseName]) END; SET @IsPartial=1; END
        ELSE IF EXISTS(SELECT 1 FROM [#IndexOperationalStats_DatabaseStatus] WHERE [StatusCode] IN ('AVAILABLE_LIMITED','SKIPPED','NOT_APPLICABLE'))
        BEGIN SET @OverallStatus=CASE WHEN @TotalRows>0 THEN 'AVAILABLE_LIMITED' ELSE 'SKIPPED' END; SET @IsPartial=1; END;
    END;
    IF @PrintMeldungen=1 AND @OverallStatus<>'AVAILABLE'
        BEGIN
    SET @MonitorPrintMessage = FORMATMESSAGE(N'WARNUNG %s: %s', @OverallStatus, COALESCE(@ErrorMessage,@Detail,N'Teilergebnis oder eingeschränkte Sicht'));
    RAISERROR(N'%s', 10, 1, @MonitorPrintMessage) WITH NOWAIT;
END;

    IF @ResultSetArtNormalisiert<>'NONE' BEGIN
        SELECT @ModuleName [ModuleName],@CollectionTimeUtc [CollectionTimeUtc],@OverallStatus [StatusCode],@IsPartial [IsPartial],@TotalRows [RowCount],@ErrorNumber [ErrorNumber],@ErrorMessage [ErrorMessage],@Detail [Detail];
        SELECT [DatabaseName],[StatusCode],[IsPartial],[RowCount],[RequiredPermission],[ErrorNumber],[ErrorMessage],[Detail] FROM [#IndexOperationalStats_DatabaseStatus] ORDER BY [DatabaseName];
        IF @ResultSetArtNormalisiert='RAW' SELECT * FROM [#IndexOperationalStats_Result] ORDER BY [LeafPageAllocationCount] DESC,[PageLockWaitMs] DESC,[DatabaseName],[SchemaName],[ObjectName],[IndexId],[PartitionNumber]; ELSE SELECT N'Index Operational Stats' [Ergebnis],[r].* FROM [#IndexOperationalStats_Result] [r] ORDER BY [LeafPageAllocationCount] DESC,[PageLockWaitMs] DESC,[DatabaseName],[SchemaName],[ObjectName],[IndexId],[PartitionNumber];
    END;
    IF @JsonErzeugen=1 BEGIN
        DECLARE @JsonMeta nvarchar(max)=(SELECT @ModuleName [resultName],1 [schemaVersion],@CollectionTimeUtc [generatedAtUtc],@OverallStatus [statusCode],@IsPartial [isPartial],@TotalRows [rowCount] FOR JSON PATH,WITHOUT_ARRAY_WRAPPER,INCLUDE_NULL_VALUES);
        DECLARE @JsonDatabaseStatus nvarchar(max)=(SELECT * FROM [#IndexOperationalStats_DatabaseStatus] ORDER BY [DatabaseName] FOR JSON PATH,INCLUDE_NULL_VALUES);
        DECLARE @JsonData1 nvarchar(max)=(SELECT * FROM [#IndexOperationalStats_Result] ORDER BY [LeafPageAllocationCount] DESC,[PageLockWaitMs] DESC,[DatabaseName],[SchemaName],[ObjectName],[IndexId],[PartitionNumber] FOR JSON PATH,INCLUDE_NULL_VALUES);
        SET @Json=CONCAT(N'{"meta":',COALESCE(@JsonMeta,N'{}'),N',"indexOperationalStats":',COALESCE(@JsonData1,N'[]'),N',"databaseStatus":',COALESCE(@JsonDatabaseStatus,N'[]'),N'}');
    END;
    IF @ConsoleResultRequested = 1
    BEGIN
        EXEC [monitor].[InternalEmitConsoleResult]
              @SourceTable=N'#IndexOperationalStats_Result'
            , @ResultLabel=N'IndexOperationalStats'
            , @EmptyMessage=N'Keine fachlichen Ergebnisse';
    END;
    IF @TableResultRequested = 1
    BEGIN
        EXEC [monitor].[InternalWriteResultTable]
              @SourceTable = N'#IndexOperationalStats_Result'
            , @TargetTable=@TableTarget
            , @ThrowOnError = 1;
    END;
END;
GO
-- END SOURCE: Code/03_ObjectIndex/025_USP_IndexOperationalStats.sql

-- BEGIN SOURCE: Code/03_ObjectIndex/030_USP_MissingIndexes.sql
/*
===============================================================================
Objekt       : monitor.USP_MissingIndexes
Version      : 1.0.0
Stand        : 2026-07-14
Typ          : Stored Procedure
Zweck        : Liefert aktuelle Missing-Index-Hinweise aus den flüchtigen SQL-Server-DMVs, bewertet Nutzenindikatoren und erzeugt nur einen prüfpflichtigen DDL-Entwurf.
SQL-Version  : SQL Server 2019 oder neuer.
Datenquellen : sys.dm_db_missing_index_details, sys.dm_db_missing_index_groups, sys.dm_db_missing_index_group_stats sowie je Datenbank sys.objects, sys.schemas und sys.tables.
Parameter    :
  @DatabaseName                  sysname        = NULL  - Zieldatenbank; bei Einzelmodus Pflicht.
  @CrossDatabaseRequestedInternal               bit            = 0     - sichtbare Online-Datenbanken analysieren.
  @SystemdatenbankenEinbeziehen  bit            = 0     - master/model/msdb/tempdb einbeziehen.
  @DatenbankNameLike             nvarchar(256)  = NULL  - Filter im Cross-Database-Modus.
  @SchemaNamePattern                nvarchar(256)  = NULL  - LIKE-Filter auf Schema.
  @ObjectNamePattern                nvarchar(256)  = NULL  - LIKE-Filter auf Objekt.
  @MaxZeilen                     int            = 5000  - positive Werte begrenzen; NULL/0 = unbegrenzt.
  @LockTimeoutMs                 int            = 0     - 0 = nicht auf Metadatenlocks warten.
  @PrintMeldungen                bit            = 1     - Warnungen via RAISERROR 10.
  @Hilfe                         bit            = 0     - Hilfe via PRINT, keine Analyse.
  @MinUserReads bigint = 1 - Mindestanzahl Seeks+Scans.
  @MinAvgUserImpact decimal(9,2) = 0 - Mindestwirkung in Prozent.
  @MinImprovementMeasure decimal(28,2) = 0 - Mindest-Nutzenindikator.
Resultsets   : 1. Modulstatus. 2. Status je Datenbank. 3. Missing-Index-Hinweise.
Berechtigung : SQL Server 2019 VIEW SERVER STATE; SQL Server 2022+ VIEW SERVER PERFORMANCE STATE; Metadatensicht kann zusätzlich begrenzt sein.
Eigenlast    : DMV-Menge ist intern begrenzt; Join und Sortierung werden durch TOP begrenzt.
Locking      : Server-DMVs und READUNCOMMITTED-Kataloge; keine DDL-Ausführung.
Partial      : Fehler je Datenbank bzw. Teilquelle werden isoliert; vorhandene
               Teilergebnisse bleiben erhalten. Das Framework vergibt keine Rechte.
Beispiele    :
  EXEC monitor.USP_MissingIndexes @DatabaseNames=N'SampleDatabase';
  EXEC monitor.USP_MissingIndexes @DatabaseNames=N'SampleDatabase', @MinUserReads=100, @MinAvgUserImpact=50;
  EXEC monitor.USP_MissingIndexes @Hilfe=1;
Änderungen   : 1.0.0 - Erstfassung Phase 2.
===============================================================================
*/
CREATE OR ALTER PROCEDURE [monitor].[USP_MissingIndexes]
      @DatabaseNames                  nvarchar(max)  = NULL
    , @SystemdatenbankenEinbeziehen   bit            = 0
    , @DatabaseNamePattern            nvarchar(4000) = NULL
    , @HighImpactConfirmed              bit            = 0
    , @SchemaNames                    nvarchar(max)  = NULL
    , @SchemaNamePattern              nvarchar(4000) = NULL
    , @ObjectNames                    nvarchar(max)  = NULL
    , @ObjectNamePattern              nvarchar(4000) = NULL
    , @FullObjectNames                nvarchar(max)  = NULL
    , @MinUserReads                   bigint        = 1
    , @MinAvgUserImpact               decimal(9,2)  = 0
    , @MinImprovementMeasure          decimal(28,2) = 0
    , @MaxZeilen                      int           = 5000
    , @LockTimeoutMs                  int           = 0
    , @ResultSetArt                  varchar(16)    = 'CONSOLE'
    , @ResultTablesJson               nvarchar(max) = NULL
    , @JsonErzeugen                  bit            = 0
    , @Json                          nvarchar(max)  = NULL OUTPUT
    , @PrintMeldungen                 bit           = 1
    , @Hilfe                          bit           = 0
AS
BEGIN
 SET NOCOUNT ON;

    SET @Json = NULL;
    DECLARE @ResultSetArtNormalisiert varchar(16)=UPPER(LTRIM(RTRIM(COALESCE(@ResultSetArt,''))));
    DECLARE @TableResultRequested bit = CASE WHEN @ResultSetArtNormalisiert = 'TABLE' THEN 1 ELSE 0 END;
    DECLARE @ConsoleResultRequested bit = CASE WHEN @ResultSetArtNormalisiert = 'CONSOLE' THEN 1 ELSE 0 END;
    DECLARE @TableTarget sysname=NULL;
    IF @TableResultRequested=0 AND NULLIF(LTRIM(RTRIM(COALESCE(@ResultTablesJson,N''))),N'') IS NOT NULL THROW 51011,N'@ResultTablesJson ist ausschließlich mit @ResultSetArt=TABLE zulässig.',1;
    IF @TableResultRequested=1 EXEC [monitor].[InternalPrepareSingleResultTable] @ResultTablesJson=@ResultTablesJson,@ResultName=N'missingIndexes',@TargetTable=@TableTarget OUTPUT,@ThrowOnError=1;
    IF @TableResultRequested = 1 OR @ConsoleResultRequested = 1 SET @ResultSetArtNormalisiert = 'NONE';
    DECLARE @DatabaseName sysname=NULL,@CrossDatabaseRequestedInternal bit=0,@DatenbankNameLike nvarchar(4000)=NULL;
    DECLARE @SchemaNameLike nvarchar(4000)=NULL,@ObjectNameLike nvarchar(4000)=NULL;
    DECLARE @SchemaPatternMode varchar(8),@SchemaPatternValue nvarchar(4000),@SchemaRegexFlags varchar(8),@SchemaPatternValid bit;
    DECLARE @ObjectPatternMode varchar(8),@ObjectPatternValue nvarchar(4000),@ObjectRegexFlags varchar(8),@ObjectPatternValid bit;
    SELECT @SchemaPatternMode=[PatternMode],@SchemaPatternValue=[PatternValue],@SchemaRegexFlags=[RegexFlags],@SchemaPatternValid=[IsValid] FROM [monitor].[TVF_ParsePattern](@SchemaNamePattern);
    SELECT @ObjectPatternMode=[PatternMode],@ObjectPatternValue=[PatternValue],@ObjectRegexFlags=[RegexFlags],@ObjectPatternValid=[IsValid] FROM [monitor].[TVF_ParsePattern](@ObjectNamePattern);
    IF @SchemaPatternMode='LIKE' SET @SchemaNameLike=@SchemaPatternValue;
    IF @ObjectPatternMode='LIKE' SET @ObjectNameLike=@ObjectPatternValue;
    DECLARE @IndexPatternMode varchar(8)='NONE',@IndexPatternValue nvarchar(4000)=NULL,@IndexRegexFlags varchar(8)=NULL,@IndexPatternValid bit=1;
    DECLARE @StatisticsPatternMode varchar(8)='NONE',@StatisticsPatternValue nvarchar(4000)=NULL,@StatisticsRegexFlags varchar(8)=NULL,@StatisticsPatternValid bit=1;
    DECLARE @DatabaseListCount int=0;
    IF @DatabaseNames IS NOT NULL AND NULLIF(LTRIM(RTRIM(@DatabaseNames)),N'') IS NOT NULL
        SELECT @DatabaseListCount=COUNT(*),@DatabaseName=MIN([NameValue]) FROM [monitor].[TVF_ParseSqlNameList](@DatabaseNames) WHERE [IsValid]=1;
    SET @CrossDatabaseRequestedInternal=CONVERT(bit,CASE WHEN @DatabaseNames IS NULL OR @DatabaseNamePattern IS NOT NULL OR @DatabaseListCount>1 THEN 1 ELSE 0 END);
    SELECT @DatenbankNameLike=CASE WHEN [PatternMode]='LIKE' THEN [PatternValue] END FROM [monitor].[TVF_ParsePattern](@DatabaseNamePattern);
    CREATE TABLE [#MissingIndexes_NameFilters]([FilterType] varchar(20) COLLATE SQL_Latin1_General_CP1_CS_AS NOT NULL,[ItemOrdinal] int NOT NULL,[NameValue] sysname COLLATE SQL_Latin1_General_CP1_CS_AS NULL,[DatabaseName] sysname COLLATE SQL_Latin1_General_CP1_CS_AS NULL,[SchemaName] sysname COLLATE SQL_Latin1_General_CP1_CS_AS NULL,[ObjectName] sysname COLLATE SQL_Latin1_General_CP1_CS_AS NULL);
    CREATE TABLE [#MissingIndexes_DatabaseCandidates]([DatabaseId] int NOT NULL,[DatabaseName] sysname NOT NULL,[StateDesc] nvarchar(60),[UserAccessDesc] nvarchar(60),[IsReadOnly] bit,[CompatibilityLevel] tinyint,[CollationName] sysname,[RecoveryModelDesc] nvarchar(60),[IsSystemDatabase] bit,[RequestedOrdinal] int);
    DECLARE @FilterStatus varchar(40)='AVAILABLE',@FilterError nvarchar(2048)=NULL,@CrossDatabaseRequested bit=0;
    EXEC [monitor].[USP_PrepareNameFilters] @SchemaNames=@SchemaNames,@ObjectNames=@ObjectNames,@FullObjectNames=@FullObjectNames,@IndexNames=NULL,@StatisticsNames=NULL,@ColumnNames=NULL,@StatusCode=@FilterStatus OUTPUT,@ErrorMessage=@FilterError OUTPUT,@FilterTable=N'#MissingIndexes_NameFilters';
    IF @FilterStatus='AVAILABLE' EXEC [monitor].[USP_PrepareDatabaseCandidates] @DatabaseNames=@DatabaseNames,@SystemdatenbankenEinbeziehen=@SystemdatenbankenEinbeziehen,@DatabaseNamePattern=@DatabaseNamePattern,@HighImpactConfirmed=@HighImpactConfirmed,@AnalysisClass='MISSING_INDEX_CURRENT',@StatusCode=@FilterStatus OUTPUT,@ErrorMessage=@FilterError OUTPUT,@CrossDatabaseRequested=@CrossDatabaseRequested OUTPUT,@CandidateTable=N'#MissingIndexes_DatabaseCandidates';
    DECLARE @SchemaPredicateS nvarchar(max),@SchemaPredicateSch nvarchar(max),@ObjectPredicateO nvarchar(max),@FullObjectPredicateSO nvarchar(max),@IndexPredicateI nvarchar(max),@StatisticsPredicateSt nvarchar(max);
    SET @SchemaPredicateS=N' AND (NOT EXISTS(SELECT 1 FROM [#MissingIndexes_NameFilters] WHERE [FilterType]=''SCHEMA'') OR EXISTS(SELECT 1 FROM [#MissingIndexes_NameFilters] [f] WHERE [f].[FilterType]=''SCHEMA'' AND [f].[NameValue]=[s].[name] COLLATE SQL_Latin1_General_CP1_CS_AS))';
    SET @SchemaPredicateSch=REPLACE(@SchemaPredicateS,N'[s].[name]',N'[sch].[name]');
    SET @ObjectPredicateO=N' AND (NOT EXISTS(SELECT 1 FROM [#MissingIndexes_NameFilters] WHERE [FilterType]=''OBJECT'') OR EXISTS(SELECT 1 FROM [#MissingIndexes_NameFilters] [f] WHERE [f].[FilterType]=''OBJECT'' AND [f].[NameValue]=[o].[name] COLLATE SQL_Latin1_General_CP1_CS_AS))';
    SET @FullObjectPredicateSO=N' AND (NOT EXISTS(SELECT 1 FROM [#MissingIndexes_NameFilters] WHERE [FilterType]=''FULL_OBJECT'') OR EXISTS(SELECT 1 FROM [#MissingIndexes_NameFilters] [f] WHERE [f].[FilterType]=''FULL_OBJECT'' AND ([f].[DatabaseName] IS NULL OR [f].[DatabaseName]=@pDbName COLLATE SQL_Latin1_General_CP1_CS_AS) AND ([f].[SchemaName] IS NULL OR [f].[SchemaName]=[s].[name] COLLATE SQL_Latin1_General_CP1_CS_AS) AND [f].[ObjectName]=[o].[name] COLLATE SQL_Latin1_General_CP1_CS_AS))';
    SET @IndexPredicateI=N' AND (NOT EXISTS(SELECT 1 FROM [#MissingIndexes_NameFilters] WHERE [FilterType]=''INDEX'') OR EXISTS(SELECT 1 FROM [#MissingIndexes_NameFilters] [f] WHERE [f].[FilterType]=''INDEX'' AND [f].[NameValue]=[i].[name] COLLATE SQL_Latin1_General_CP1_CS_AS))';
    SET @StatisticsPredicateSt=N' AND (NOT EXISTS(SELECT 1 FROM [#MissingIndexes_NameFilters] WHERE [FilterType]=''STATISTICS'') OR EXISTS(SELECT 1 FROM [#MissingIndexes_NameFilters] [f] WHERE [f].[FilterType]=''STATISTICS'' AND [f].[NameValue]=[st].[name] COLLATE SQL_Latin1_General_CP1_CS_AS))';
    IF @SchemaPatternMode='LIKE' BEGIN SET @SchemaPredicateS+=N' AND [s].[name] COLLATE SQL_Latin1_General_CP1_CS_AS LIKE N'''+REPLACE(@SchemaPatternValue,N'''',N'''''')+N''' COLLATE SQL_Latin1_General_CP1_CS_AS';SET @SchemaPredicateSch+=N' AND [sch].[name] COLLATE SQL_Latin1_General_CP1_CS_AS LIKE N'''+REPLACE(@SchemaPatternValue,N'''',N'''''')+N''' COLLATE SQL_Latin1_General_CP1_CS_AS';END;
    IF @SchemaPatternMode IN('REGEX','REGEXI') BEGIN SET @SchemaPredicateS+=N' AND REGEXP_LIKE([s].[name],N'''+REPLACE(@SchemaPatternValue,N'''',N'''''')+N''','''+@SchemaRegexFlags+N''')';SET @SchemaPredicateSch+=N' AND REGEXP_LIKE([sch].[name],N'''+REPLACE(@SchemaPatternValue,N'''',N'''''')+N''','''+@SchemaRegexFlags+N''')';END;
    IF @ObjectPatternMode='LIKE' SET @ObjectPredicateO+=N' AND [o].[name] COLLATE SQL_Latin1_General_CP1_CS_AS LIKE N'''+REPLACE(@ObjectPatternValue,N'''',N'''''')+N''' COLLATE SQL_Latin1_General_CP1_CS_AS';
    IF @ObjectPatternMode IN('REGEX','REGEXI') SET @ObjectPredicateO+=N' AND REGEXP_LIKE([o].[name],N'''+REPLACE(@ObjectPatternValue,N'''',N'''''')+N''','''+@ObjectRegexFlags+N''')';
    IF @IndexPatternMode='LIKE' SET @IndexPredicateI+=N' AND [i].[name] COLLATE SQL_Latin1_General_CP1_CS_AS LIKE N'''+REPLACE(@IndexPatternValue,N'''',N'''''')+N''' COLLATE SQL_Latin1_General_CP1_CS_AS';
    IF @IndexPatternMode IN('REGEX','REGEXI') SET @IndexPredicateI+=N' AND REGEXP_LIKE([i].[name],N'''+REPLACE(@IndexPatternValue,N'''',N'''''')+N''','''+@IndexRegexFlags+N''')';
    IF @StatisticsPatternMode='LIKE' SET @StatisticsPredicateSt+=N' AND [st].[name] COLLATE SQL_Latin1_General_CP1_CS_AS LIKE N'''+REPLACE(@StatisticsPatternValue,N'''',N'''''')+N''' COLLATE SQL_Latin1_General_CP1_CS_AS';
    IF @StatisticsPatternMode IN('REGEX','REGEXI') SET @StatisticsPredicateSt+=N' AND REGEXP_LIKE([st].[name],N'''+REPLACE(@StatisticsPatternValue,N'''',N'''''')+N''','''+@StatisticsRegexFlags+N''')';
    DECLARE @EffectiveMaxZeilen bigint = CASE WHEN @MaxZeilen IS NULL OR @MaxZeilen=0 THEN CONVERT(bigint,9223372036854775807) ELSE CONVERT(bigint,@MaxZeilen) END;
    DECLARE @MonitorPrintMessage nvarchar(2048);
 IF @Hilfe=1
 BEGIN
        PRINT N'monitor.USP_MissingIndexes';        PRINT N'@DatabaseNames: exakter Name oder bracket-aware Pipe-Liste; NULL = alle zulässigen Datenbanken; N'''' = keine Einschränkung.';        PRINT N'@SystemdatenbankenEinbeziehen bit = 0: Systemdatenbanken einbeziehen.';        PRINT N'Exakte Listen und ...NamePattern sind gegenseitig exklusiv. Pattern: LIKE (Default/like:), regex: oder regexi:.';
        PRINT N'Datenbankauswahl ohne Vorabbegrenzung; @MaxZeilen int: harte Ergebnismengenbegrenzung.';
        PRINT N'@LockTimeoutMs int = 0: Metadatenzugriff wartet standardmäßig nicht auf Locks.';
        PRINT N'@PrintMeldungen bit = 1: strukturierte Warnungen zusätzlich in der Console.';
        PRINT N'Die Procedure liefert flüchtige Missing-Index-Hinweise und führt keine CREATE-INDEX-Anweisung aus.';
        PRINT N'@MinUserReads bigint = 1: Mindestwert user_seeks + user_scans.';
        PRINT N'@MinAvgUserImpact decimal(9,2) = 0: Mindestwirkung laut DMV.';
        PRINT N'@MinImprovementMeasure decimal(28,2) = 0: avg_total_user_cost * avg_user_impact * reads.';
        PRINT N'DDL-Entwurf muss mit bestehenden Indizes, Write-Kosten, Selectivity und Workload geprüft werden.';
        PRINT N'@Hilfe bit = 0: 1 zeigt diese Hilfe und führt keine Analyse aus.';
        RETURN;
 END;

    DECLARE @ModuleName sysname = N'USP_MissingIndexes';
    DECLARE @CollectionTimeUtc datetime2(3) = SYSUTCDATETIME();

    DECLARE @OverallStatus varchar(40) = 'AVAILABLE';
    DECLARE @IsPartial bit = 0;
    DECLARE @TotalRows bigint = 0;
    DECLARE @ErrorNumber int = NULL;
    DECLARE @ErrorMessage nvarchar(2048) = NULL;
    DECLARE @Detail nvarchar(2000) = NULL;

    CREATE TABLE [#MissingIndexes_DatabaseStatus]
    (
          [DatabaseName]       sysname        NULL
        , [StatusCode]         varchar(40)    NOT NULL
        , [IsPartial]          bit            NOT NULL
        , [RowCount]           bigint         NOT NULL
        , [RequiredPermission] nvarchar(256)  NULL
        , [ErrorNumber]        int            NULL
        , [ErrorMessage]       nvarchar(2048) NULL
        , [Detail]             nvarchar(2000) NULL
    );

    IF @FilterStatus<>'AVAILABLE' BEGIN SET @OverallStatus=@FilterStatus;SET @ErrorMessage=@FilterError;END;
    IF @ResultSetArtNormalisiert NOT IN('RAW','CONSOLE','NONE') BEGIN SET @OverallStatus='INVALID_PARAMETER';SET @ErrorMessage=N'@ResultSetArt muss CONSOLE, RAW, TABLE oder NONE enthalten.';END;
    IF @SchemaPatternValid=0 OR @ObjectPatternValid=0 OR @IndexPatternValid=0 OR @StatisticsPatternValid=0 OR (@SchemaNames IS NOT NULL AND @SchemaNamePattern IS NOT NULL) OR (@ObjectNames IS NOT NULL AND @ObjectNamePattern IS NOT NULL) BEGIN SET @OverallStatus='INVALID_PARAMETER';SET @ErrorMessage=N'Exakte Liste und Pattern derselben Eigenschaft sind gegenseitig exklusiv.';END;
IF @MaxZeilen<0 OR @LockTimeoutMs NOT BETWEEN 0 AND 60000
    BEGIN
        SET @OverallStatus = 'INVALID_PARAMETER';
        SET @ErrorMessage = N'Ungültiger Parameter: @MaxZeilen oder @LockTimeoutMs außerhalb des zulässigen Bereichs.';
    END


    IF @OverallStatus <> 'AVAILABLE'
    BEGIN
        INSERT [#MissingIndexes_DatabaseStatus]([DatabaseName], [StatusCode], [IsPartial], [RowCount], [RequiredPermission], [ErrorNumber], [ErrorMessage], [Detail])
        VALUES(@DatabaseName, @OverallStatus, 1, 0, NULL, NULL, @ErrorMessage, N'Keine Datenbankanalyse ausgeführt.');
        SET @IsPartial = 1;
    END
    ELSE
    BEGIN
        SET LOCK_TIMEOUT 0;
    END;

 CREATE TABLE [#MissingIndexes_Result]
 (
   [DatabaseName] sysname NOT NULL, [SchemaName] sysname NULL, [ObjectName] sysname NULL, [ObjectId] int NULL,
   [IndexHandle] int NOT NULL, [IndexGroupHandle] int NOT NULL, [UniqueCompiles] bigint NULL,
   [UserSeeks] bigint NULL, [UserScans] bigint NULL, [TotalUserReads] bigint NULL, [LastUserSeek] datetime NULL, [LastUserScan] datetime NULL,
   [AvgTotalUserCost] float NULL, [AvgUserImpact] float NULL, [ImprovementMeasure] decimal(28,2) NULL,
   [EqualityColumns] nvarchar(4000) NULL, [InequalityColumns] nvarchar(4000) NULL, [IncludedColumns] nvarchar(4000) NULL,
   [StatementName] nvarchar(4000) NULL, [ProposedIndexName] sysname NULL, [ProposedCreateIndex] nvarchar(max) NULL,
   [WarningText] nvarchar(1000) NOT NULL
 );
 IF @OverallStatus='AVAILABLE' AND (@MinUserReads<0 OR @MinAvgUserImpact<0 OR @MinAvgUserImpact>100 OR @MinImprovementMeasure<0)
 BEGIN SET @OverallStatus='INVALID_PARAMETER'; SET @ErrorMessage=N'Ungültiger Mindestfilter.'; INSERT [#MissingIndexes_DatabaseStatus] VALUES(@DatabaseName,@OverallStatus,1,0,NULL,NULL,@ErrorMessage,NULL); END
 ELSE IF @OverallStatus='AVAILABLE'
 BEGIN
  DECLARE @DbId int,@DbName sysname,@Sql nvarchar(max),@Rows bigint;
  DECLARE dbcur CURSOR LOCAL FAST_FORWARD FOR SELECT [DatabaseId],[DatabaseName] FROM [#MissingIndexes_DatabaseCandidates];
  OPEN dbcur; FETCH NEXT FROM dbcur INTO @DbId,@DbName;
  WHILE @@FETCH_STATUS=0
  BEGIN
   BEGIN TRY
    SET @Sql = N'SET LOCK_TIMEOUT ' + CONVERT(nvarchar(11), @LockTimeoutMs) + N'; USE ' + QUOTENAME(@DbName) + N';
INSERT #MissingIndexes_Result
SELECT TOP (@pMaxRows)
 @pDbName,[s].[name],[o].[name],[d].[object_id],[d].[index_handle],[g].[index_group_handle],[gs].[unique_compiles],
 [gs].[user_seeks],[gs].[user_scans],[gs].[user_seeks]+[gs].[user_scans],[gs].[last_user_seek],[gs].[last_user_scan],
 [gs].[avg_total_user_cost],[gs].[avg_user_impact],
 CONVERT(decimal(28,2),[gs].[avg_total_user_cost]*[gs].[avg_user_impact]*([gs].[user_seeks]+[gs].[user_scans])),
 [d].[equality_columns],[d].[inequality_columns],[d].[included_columns],[d].[statement],
 CONVERT(sysname,LEFT(N''IX_Missing_''+CONVERT(nvarchar(20),[d].[object_id])+N''_''+CONVERT(nvarchar(20),[d].[index_handle]),128)),
 N''CREATE INDEX ''+QUOTENAME(LEFT(N''IX_Missing_''+CONVERT(nvarchar(20),[d].[object_id])+N''_''+CONVERT(nvarchar(20),[d].[index_handle]),128))+N'' ON ''+QUOTENAME(@pDbName)+N''.''+QUOTENAME([s].[name])+N''.''+QUOTENAME([o].[name])+N'' (''+
 COALESCE([d].[equality_columns],N'''')+CASE WHEN [d].[equality_columns] IS NOT NULL AND [d].[inequality_columns] IS NOT NULL THEN N'', '' ELSE N'''' END+COALESCE([d].[inequality_columns],N'''')+N'')''+
 CASE WHEN [d].[included_columns] IS NOT NULL THEN N'' INCLUDE (''+[d].[included_columns]+N'')'' ELSE N'''' END+N'';'',
 N''Hinweis aus flüchtigen DMVs; vor Umsetzung auf Überlappung, Schlüsselbreite, Selectivity, Write-Kosten und reale Pläne prüfen.''
FROM sys.dm_db_missing_index_details AS [d] WITH (NOLOCK)
JOIN sys.dm_db_missing_index_groups AS [g] WITH (NOLOCK) ON [g].[index_handle]=[d].[index_handle]
JOIN sys.dm_db_missing_index_group_stats AS [gs] WITH (NOLOCK) ON [gs].[group_handle]=[g].[index_group_handle]
LEFT JOIN sys.objects AS [o] WITH (NOLOCK) ON [o].[object_id]=[d].[object_id]
LEFT JOIN sys.schemas AS [s] WITH (NOLOCK) ON [s].[schema_id]=[o].[schema_id]
WHERE [d].[database_id]=@pDbId
'+@SchemaPredicateS+@ObjectPredicateO+@FullObjectPredicateSO+N'
 AND [gs].[user_seeks]+[gs].[user_scans]>=@pMinReads
 AND [gs].[avg_user_impact]>=@pMinImpact
 AND [gs].[avg_total_user_cost]*[gs].[avg_user_impact]*([gs].[user_seeks]+[gs].[user_scans])>=@pMinMeasure
ORDER BY [gs].[avg_total_user_cost]*[gs].[avg_user_impact]*([gs].[user_seeks]+[gs].[user_scans]) DESC
OPTION (MAXDOP 1, RECOMPILE);';
    EXEC [sys].[sp_executesql] @Sql,N'@pDbName sysname,@pDbId int,@pMaxRows bigint,@pSchemaLike nvarchar(256),@pObjectLike nvarchar(256),@pMinReads bigint,@pMinImpact decimal(9,2),@pMinMeasure decimal(28,2)',@pDbName=@DbName,@pDbId=@DbId,@pMaxRows=@EffectiveMaxZeilen,@pSchemaLike=@SchemaNameLike,@pObjectLike=@ObjectNameLike,@pMinReads=@MinUserReads,@pMinImpact=@MinAvgUserImpact,@pMinMeasure=@MinImprovementMeasure;
    SELECT @Rows=COUNT_BIG(*) FROM [#MissingIndexes_Result] WHERE [DatabaseName]=@DbName; INSERT [#MissingIndexes_DatabaseStatus] VALUES(@DbName,'AVAILABLE',0,@Rows,CASE WHEN TRY_CONVERT([int],SERVERPROPERTY(N'ProductMajorVersion'))>=16 THEN N'VIEW SERVER PERFORMANCE STATE' ELSE N'VIEW SERVER STATE' END,NULL,NULL,N'Missing-Index-DMVs erfolgreich gelesen; Inhalte sind flüchtig und nicht vollständig.');
   END TRY
   BEGIN CATCH
    INSERT [#MissingIndexes_DatabaseStatus] VALUES(@DbName,CASE WHEN ERROR_NUMBER() IN (229,262,297,300,371,916) THEN 'DENIED_PERMISSION' WHEN ERROR_NUMBER()=1222 THEN 'TIMEOUT' ELSE 'ERROR_HANDLED' END,1,0,CASE WHEN TRY_CONVERT([int],SERVERPROPERTY(N'ProductMajorVersion'))>=16 THEN N'VIEW SERVER PERFORMANCE STATE' ELSE N'VIEW SERVER STATE' END,ERROR_NUMBER(),ERROR_MESSAGE(),N'Fehler isoliert.');
   END CATCH;
   FETCH NEXT FROM dbcur INTO @DbId,@DbName;
  END; CLOSE dbcur; DEALLOCATE dbcur;
  IF NOT EXISTS(SELECT 1 FROM [#MissingIndexes_DatabaseStatus]) INSERT [#MissingIndexes_DatabaseStatus] VALUES(@DatabaseName,'DATABASE_UNAVAILABLE',1,0,NULL,NULL,N'Keine sichtbare Online-Zieldatenbank gefunden.',NULL);
 END;



    SELECT @TotalRows = COUNT_BIG(*) FROM [#MissingIndexes_Result];

    IF @OverallStatus = 'AVAILABLE'
    BEGIN
        IF EXISTS (SELECT 1 FROM [#MissingIndexes_DatabaseStatus] WHERE [StatusCode] NOT IN ('AVAILABLE','AVAILABLE_LIMITED','SKIPPED','NOT_APPLICABLE'))
        BEGIN
            SET @OverallStatus = CASE WHEN @TotalRows > 0 THEN 'PARTIAL' ELSE (SELECT TOP (1) [StatusCode] FROM [#MissingIndexes_DatabaseStatus] WHERE [StatusCode] NOT IN ('AVAILABLE','AVAILABLE_LIMITED','SKIPPED','NOT_APPLICABLE') ORDER BY [DatabaseName]) END;
            SET @IsPartial = 1;
        END
        ELSE IF EXISTS (SELECT 1 FROM [#MissingIndexes_DatabaseStatus] WHERE [StatusCode] IN ('AVAILABLE_LIMITED','SKIPPED','NOT_APPLICABLE'))
        BEGIN
            SET @OverallStatus = CASE WHEN @TotalRows > 0 THEN 'AVAILABLE_LIMITED' ELSE 'SKIPPED' END;
            SET @IsPartial = 1;
        END;
    END;

    IF @PrintMeldungen = 1 AND @OverallStatus <> 'AVAILABLE'
        BEGIN
    SET @MonitorPrintMessage = FORMATMESSAGE(N'WARNUNG %s: %s', @OverallStatus, COALESCE(@ErrorMessage, @Detail, N'Teilergebnis oder eingeschränkte Sicht'));
    RAISERROR(N'%s', 10, 1, @MonitorPrintMessage) WITH NOWAIT;
END;

    IF @ResultSetArtNormalisiert<>'NONE' BEGIN
        SELECT @ModuleName [ModuleName],@CollectionTimeUtc [CollectionTimeUtc],@OverallStatus [StatusCode],@IsPartial [IsPartial],@TotalRows [RowCount],@ErrorNumber [ErrorNumber],@ErrorMessage [ErrorMessage],@Detail [Detail];
        SELECT [DatabaseName],[StatusCode],[IsPartial],[RowCount],[RequiredPermission],[ErrorNumber],[ErrorMessage],[Detail] FROM [#MissingIndexes_DatabaseStatus] ORDER BY [DatabaseName];
        IF @ResultSetArtNormalisiert='RAW' SELECT * FROM [#MissingIndexes_Result] ORDER BY [ImprovementMeasure] DESC,[DatabaseName],[SchemaName],[ObjectName]; ELSE SELECT N'Missing Index' [Ergebnis],[r].* FROM [#MissingIndexes_Result] [r] ORDER BY [ImprovementMeasure] DESC,[DatabaseName],[SchemaName],[ObjectName];
    END;
    IF @JsonErzeugen=1 BEGIN
        DECLARE @JsonMeta nvarchar(max)=(SELECT @ModuleName [resultName],1 [schemaVersion],@CollectionTimeUtc [generatedAtUtc],@OverallStatus [statusCode],@IsPartial [isPartial],@TotalRows [rowCount] FOR JSON PATH,WITHOUT_ARRAY_WRAPPER,INCLUDE_NULL_VALUES);
        DECLARE @JsonDatabaseStatus nvarchar(max)=(SELECT * FROM [#MissingIndexes_DatabaseStatus] ORDER BY [DatabaseName] FOR JSON PATH,INCLUDE_NULL_VALUES);
        DECLARE @JsonData1 nvarchar(max)=(SELECT * FROM [#MissingIndexes_Result] ORDER BY [ImprovementMeasure] DESC,[DatabaseName],[SchemaName],[ObjectName] FOR JSON PATH,INCLUDE_NULL_VALUES);
        SET @Json=CONCAT(N'{"meta":',COALESCE(@JsonMeta,N'{}'),N',"missingIndexes":',COALESCE(@JsonData1,N'[]'),N',"databaseStatus":',COALESCE(@JsonDatabaseStatus,N'[]'),N'}');
    END;
    IF @ConsoleResultRequested = 1
    BEGIN
        EXEC [monitor].[InternalEmitConsoleResult]
              @SourceTable=N'#MissingIndexes_Result'
            , @ResultLabel=N'MissingIndexes'
            , @EmptyMessage=N'Keine fachlichen Ergebnisse';
    END;
    IF @TableResultRequested = 1
    BEGIN
        EXEC [monitor].[InternalWriteResultTable]
              @SourceTable = N'#MissingIndexes_Result'
            , @TargetTable=@TableTarget
            , @ThrowOnError = 1;
    END;
END;
GO
-- END SOURCE: Code/03_ObjectIndex/030_USP_MissingIndexes.sql

-- BEGIN SOURCE: Code/03_ObjectIndex/040_USP_Statistics.sql
/*
===============================================================================
Objekt       : monitor.USP_Statistics
Version      : 1.2.0
Stand        : 2026-07-23
Typ          : Stored Procedure
Zweck        : Analysiert Statistikdefinitionen, letzte Aktualisierung,
               Stichprobe, Modification Counter sowie versionsadaptiv die
               Herkunft persistierter Statistiken auf lesbaren Replikaten;
               vollständige ungezielte Scans sind gruppengeschützt.
SQL-Version  : SQL Server 2019 oder neuer.
Datenquellen : Je Datenbank sys.stats, sys.stats_columns, sys.columns,
               sys.objects, sys.tables, sys.schemas,
               sys.dm_db_stats_properties, sys.fn_hadr_is_primary_replica,
               auf SQL Server 2025 capability-geprüfte sys.stats-Spalten sowie
               optional sys.dm_db_incremental_stats_properties.
Parameter    :
  @DatabaseName                  sysname        = NULL  - Zieldatenbank; bei Einzelmodus Pflicht.
  @CrossDatabaseRequestedInternal               bit            = 0     - sichtbare Online-Datenbanken analysieren.
  @SystemdatenbankenEinbeziehen  bit            = 0     - master/model/msdb/tempdb einbeziehen.
  @DatenbankNameLike             nvarchar(256)  = NULL  - Filter im Cross-Database-Modus.
  @SchemaNamePattern                nvarchar(256)  = NULL  - LIKE-Filter auf Schema.
  @ObjectNamePattern                nvarchar(256)  = NULL  - LIKE-Filter auf Objekt.
  @MaxZeilen                     int            = 5000  - positive Werte begrenzen; NULL/0 = unbegrenzt.
  @LockTimeoutMs                 int            = 0     - 0 = nicht auf Metadatenlocks warten.
  @PrintMeldungen                bit            = 1     - Warnungen via RAISERROR 10.
  @Hilfe                         bit            = 0     - Hilfe via PRINT, keine Analyse.
  @AnalyseModus varchar(16) = 'GEZIELT' - GEZIELT|VOLL; VOLL benötigt CATALOG_DEEP.
  @StatisticsNamePattern nvarchar(256)=NULL - Statistikfilter.
  @MinModificationPercent decimal(9,2)=0 - Mindeständerungsanteil.
  @MinAlterTage int=0 - Mindestalter der letzten Aktualisierung.
  @MitIncrementellenDetails bit=0 - Partitionsdetails für inkrementelle Statistiken.
Resultsets   : 1. Modulstatus. 2. Status je Datenbank. 3. Statistikübersicht. 4. optionale inkrementelle Partitionsdetails.
Berechtigung : Metadata Visibility und SELECT auf Statistikspalten bzw. Eigentum/db_owner/db_ddladmin/sysadmin für dm_db_stats_properties.
Eigenlast    : Gezielte Abfrage moderat; VOLL und inkrementelle Details durch CATALOG_DEEP/Cross-Database geschützt und begrenzt.
Locking      : READUNCOMMITTED-Kataloge, LOCK_TIMEOUT und je Datenbank isolierter dynamischer Batch.
Partial      : Fehler je Datenbank bzw. Teilquelle werden isoliert; vorhandene
               Teilergebnisse bleiben erhalten. Das Framework vergibt keine Rechte.
Beispiele    :
  EXEC monitor.USP_Statistics @DatabaseNames=N'SampleDatabase', @SchemaNamePattern=N'dbo', @ObjectNamePattern=N'FactSales';
  EXEC monitor.USP_Statistics @DatabaseNames=N'SampleDatabase', @AnalyseModus='VOLL', @MinModificationPercent=10;
  EXEC monitor.USP_Statistics @Hilfe=1;
Änderungen   : 1.2.0 - SQL25-004 erhält IsTemporary, aktuelle Replica-Rolle
                         und die Herkunftsfelder replica_role_id,
                         replica_role_desc und replica_name versionsadaptiv.
                         Der äußere LOCK_TIMEOUT bleibt unverändert; jeder
                         Datenbankread setzt ihn nur im isolierten Dynamic SQL.
               1.1.0 - Inkrementelle Partitionsdetails werden bei aktiviertem
                         Schalter auch als Resultset und JSON-Array veröffentlicht.
               1.0.0 - Erstfassung Phase 2.
===============================================================================
*/
CREATE OR ALTER PROCEDURE [monitor].[USP_Statistics]
      @DatabaseNames                  nvarchar(max)  = NULL
    , @SystemdatenbankenEinbeziehen   bit            = 0
    , @DatabaseNamePattern            nvarchar(4000) = NULL
    , @HighImpactConfirmed              bit            = 0
    , @SchemaNames                    nvarchar(max)  = NULL
    , @SchemaNamePattern              nvarchar(4000) = NULL
    , @ObjectNames                    nvarchar(max)  = NULL
    , @ObjectNamePattern              nvarchar(4000) = NULL
    , @FullObjectNames                nvarchar(max)  = NULL
    , @StatisticsNames                nvarchar(max)  = NULL
    , @StatisticsNamePattern          nvarchar(4000) = NULL
    , @AnalyseModus                   varchar(16)   = 'GEZIELT'
    , @MinModificationPercent         decimal(9,2)  = 0
    , @MinAlterTage                   int           = 0
    , @MitIncrementellenDetails       bit           = 0
    , @MaxZeilen                      int           = 10000
    , @LockTimeoutMs                  int           = 0
    , @ResultSetArt                  varchar(16)    = 'CONSOLE'
    , @ResultTablesJson               nvarchar(max) = NULL
    , @JsonErzeugen                  bit            = 0
    , @Json                          nvarchar(max)  = NULL OUTPUT
    , @PrintMeldungen                 bit           = 1
    , @Hilfe                          bit           = 0
AS
BEGIN
 SET NOCOUNT ON;

    DECLARE @OriginalLockTimeout int = @@LOCK_TIMEOUT;
    DECLARE @ProductMajorVersion int =
        TRY_CONVERT(int, SERVERPROPERTY('ProductMajorVersion'));

    SET @Json = NULL;
    DECLARE @ResultSetArtNormalisiert varchar(16)=UPPER(LTRIM(RTRIM(COALESCE(@ResultSetArt,''))));
    DECLARE @TableResultRequested bit = CASE WHEN @ResultSetArtNormalisiert = 'TABLE' THEN 1 ELSE 0 END;
    DECLARE @ConsoleResultRequested bit = CASE WHEN @ResultSetArtNormalisiert = 'CONSOLE' THEN 1 ELSE 0 END;
    DECLARE @TableTarget sysname=NULL;
    IF @TableResultRequested=0 AND NULLIF(LTRIM(RTRIM(COALESCE(@ResultTablesJson,N''))),N'') IS NOT NULL THROW 51011,N'@ResultTablesJson ist ausschließlich mit @ResultSetArt=TABLE zulässig.',1;
    IF @TableResultRequested=1 EXEC [monitor].[InternalPrepareSingleResultTable] @ResultTablesJson=@ResultTablesJson,@ResultName=N'statistics',@TargetTable=@TableTarget OUTPUT,@ThrowOnError=1;
    IF @TableResultRequested = 1 OR @ConsoleResultRequested = 1 SET @ResultSetArtNormalisiert = 'NONE';
    DECLARE @DatabaseName sysname=NULL,@CrossDatabaseRequestedInternal bit=0,@DatenbankNameLike nvarchar(4000)=NULL;
    DECLARE @SchemaNameLike nvarchar(4000)=NULL,@ObjectNameLike nvarchar(4000)=NULL;
    DECLARE @StatisticsNameLike nvarchar(4000)=NULL;
    DECLARE @SchemaPatternMode varchar(8),@SchemaPatternValue nvarchar(4000),@SchemaRegexFlags varchar(8),@SchemaPatternValid bit;
    DECLARE @ObjectPatternMode varchar(8),@ObjectPatternValue nvarchar(4000),@ObjectRegexFlags varchar(8),@ObjectPatternValid bit;
    SELECT @SchemaPatternMode=[PatternMode],@SchemaPatternValue=[PatternValue],@SchemaRegexFlags=[RegexFlags],@SchemaPatternValid=[IsValid] FROM [monitor].[TVF_ParsePattern](@SchemaNamePattern);
    SELECT @ObjectPatternMode=[PatternMode],@ObjectPatternValue=[PatternValue],@ObjectRegexFlags=[RegexFlags],@ObjectPatternValid=[IsValid] FROM [monitor].[TVF_ParsePattern](@ObjectNamePattern);
    IF @SchemaPatternMode='LIKE' SET @SchemaNameLike=@SchemaPatternValue;
    IF @ObjectPatternMode='LIKE' SET @ObjectNameLike=@ObjectPatternValue;
    DECLARE @IndexPatternMode varchar(8)='NONE',@IndexPatternValue nvarchar(4000)=NULL,@IndexRegexFlags varchar(8)=NULL,@IndexPatternValid bit=1;
    DECLARE @StatisticsPatternMode varchar(8),@StatisticsPatternValue nvarchar(4000),@StatisticsRegexFlags varchar(8),@StatisticsPatternValid bit;
    SELECT @StatisticsPatternMode=[PatternMode],@StatisticsPatternValue=[PatternValue],@StatisticsRegexFlags=[RegexFlags],@StatisticsPatternValid=[IsValid] FROM [monitor].[TVF_ParsePattern](@StatisticsNamePattern);
    IF @StatisticsPatternMode='LIKE' SET @StatisticsNameLike=@StatisticsPatternValue;
    DECLARE @DatabaseListCount int=0;
    IF @DatabaseNames IS NOT NULL AND NULLIF(LTRIM(RTRIM(@DatabaseNames)),N'') IS NOT NULL
        SELECT @DatabaseListCount=COUNT(*),@DatabaseName=MIN([NameValue]) FROM [monitor].[TVF_ParseSqlNameList](@DatabaseNames) WHERE [IsValid]=1;
    SET @CrossDatabaseRequestedInternal=CONVERT(bit,CASE WHEN @DatabaseNames IS NULL OR @DatabaseNamePattern IS NOT NULL OR @DatabaseListCount>1 THEN 1 ELSE 0 END);
    SELECT @DatenbankNameLike=CASE WHEN [PatternMode]='LIKE' THEN [PatternValue] END FROM [monitor].[TVF_ParsePattern](@DatabaseNamePattern);
    CREATE TABLE [#Statistics_NameFilters]([FilterType] varchar(20) COLLATE SQL_Latin1_General_CP1_CS_AS NOT NULL,[ItemOrdinal] int NOT NULL,[NameValue] sysname COLLATE SQL_Latin1_General_CP1_CS_AS NULL,[DatabaseName] sysname COLLATE SQL_Latin1_General_CP1_CS_AS NULL,[SchemaName] sysname COLLATE SQL_Latin1_General_CP1_CS_AS NULL,[ObjectName] sysname COLLATE SQL_Latin1_General_CP1_CS_AS NULL);
    CREATE TABLE [#Statistics_DatabaseCandidates]([DatabaseId] int NOT NULL,[DatabaseName] sysname NOT NULL,[StateDesc] nvarchar(60),[UserAccessDesc] nvarchar(60),[IsReadOnly] bit,[CompatibilityLevel] tinyint,[CollationName] sysname,[RecoveryModelDesc] nvarchar(60),[IsSystemDatabase] bit,[RequestedOrdinal] int);
    DECLARE @FilterStatus varchar(40)='AVAILABLE',@FilterError nvarchar(2048)=NULL,@CrossDatabaseRequested bit=0;
    EXEC [monitor].[USP_PrepareNameFilters] @SchemaNames=@SchemaNames,@ObjectNames=@ObjectNames,@FullObjectNames=@FullObjectNames,@IndexNames=NULL,@StatisticsNames=@StatisticsNames,@ColumnNames=NULL,@StatusCode=@FilterStatus OUTPUT,@ErrorMessage=@FilterError OUTPUT,@FilterTable=N'#Statistics_NameFilters';
    IF @FilterStatus='AVAILABLE' EXEC [monitor].[USP_PrepareDatabaseCandidates] @DatabaseNames=@DatabaseNames,@SystemdatenbankenEinbeziehen=@SystemdatenbankenEinbeziehen,@DatabaseNamePattern=@DatabaseNamePattern,@HighImpactConfirmed=@HighImpactConfirmed,@AnalysisClass='STATISTICS_TARGETED',@StatusCode=@FilterStatus OUTPUT,@ErrorMessage=@FilterError OUTPUT,@CrossDatabaseRequested=@CrossDatabaseRequested OUTPUT,@CandidateTable=N'#Statistics_DatabaseCandidates';
    IF @FilterStatus='AVAILABLE' AND (UPPER(LTRIM(RTRIM(COALESCE(@AnalyseModus,''))))='VOLL' OR @MitIncrementellenDetails=1)
        EXEC [monitor].[InternalCheckAnalysisPath] @AnalysisClass='CATALOG_DEEP',@HighImpactConfirmed=@HighImpactConfirmed,@StatusCode=@FilterStatus OUTPUT,@ErrorMessage=@FilterError OUTPUT;
    DECLARE @SchemaPredicateS nvarchar(max),@SchemaPredicateSch nvarchar(max),@ObjectPredicateO nvarchar(max),@FullObjectPredicateSO nvarchar(max),@IndexPredicateI nvarchar(max),@StatisticsPredicateSt nvarchar(max);
    SET @SchemaPredicateS=N' AND (NOT EXISTS(SELECT 1 FROM [#Statistics_NameFilters] WHERE [FilterType]=''SCHEMA'') OR EXISTS(SELECT 1 FROM [#Statistics_NameFilters] [f] WHERE [f].[FilterType]=''SCHEMA'' AND [f].[NameValue]=[s].[name] COLLATE SQL_Latin1_General_CP1_CS_AS))';
    SET @SchemaPredicateSch=REPLACE(@SchemaPredicateS,N'[s].[name]',N'[sch].[name]');
    SET @ObjectPredicateO=N' AND (NOT EXISTS(SELECT 1 FROM [#Statistics_NameFilters] WHERE [FilterType]=''OBJECT'') OR EXISTS(SELECT 1 FROM [#Statistics_NameFilters] [f] WHERE [f].[FilterType]=''OBJECT'' AND [f].[NameValue]=[o].[name] COLLATE SQL_Latin1_General_CP1_CS_AS))';
    SET @FullObjectPredicateSO=N' AND (NOT EXISTS(SELECT 1 FROM [#Statistics_NameFilters] WHERE [FilterType]=''FULL_OBJECT'') OR EXISTS(SELECT 1 FROM [#Statistics_NameFilters] [f] WHERE [f].[FilterType]=''FULL_OBJECT'' AND ([f].[DatabaseName] IS NULL OR [f].[DatabaseName]=@pDbName COLLATE SQL_Latin1_General_CP1_CS_AS) AND ([f].[SchemaName] IS NULL OR [f].[SchemaName]=[s].[name] COLLATE SQL_Latin1_General_CP1_CS_AS) AND [f].[ObjectName]=[o].[name] COLLATE SQL_Latin1_General_CP1_CS_AS))';
    SET @IndexPredicateI=N' AND (NOT EXISTS(SELECT 1 FROM [#Statistics_NameFilters] WHERE [FilterType]=''INDEX'') OR EXISTS(SELECT 1 FROM [#Statistics_NameFilters] [f] WHERE [f].[FilterType]=''INDEX'' AND [f].[NameValue]=[i].[name] COLLATE SQL_Latin1_General_CP1_CS_AS))';
    SET @StatisticsPredicateSt=N' AND (NOT EXISTS(SELECT 1 FROM [#Statistics_NameFilters] WHERE [FilterType]=''STATISTICS'') OR EXISTS(SELECT 1 FROM [#Statistics_NameFilters] [f] WHERE [f].[FilterType]=''STATISTICS'' AND [f].[NameValue]=[st].[name] COLLATE SQL_Latin1_General_CP1_CS_AS))';
    IF @SchemaPatternMode='LIKE' BEGIN SET @SchemaPredicateS+=N' AND [s].[name] COLLATE SQL_Latin1_General_CP1_CS_AS LIKE N'''+REPLACE(@SchemaPatternValue,N'''',N'''''')+N''' COLLATE SQL_Latin1_General_CP1_CS_AS';SET @SchemaPredicateSch+=N' AND [sch].[name] COLLATE SQL_Latin1_General_CP1_CS_AS LIKE N'''+REPLACE(@SchemaPatternValue,N'''',N'''''')+N''' COLLATE SQL_Latin1_General_CP1_CS_AS';END;
    IF @SchemaPatternMode IN('REGEX','REGEXI') BEGIN SET @SchemaPredicateS+=N' AND REGEXP_LIKE([s].[name],N'''+REPLACE(@SchemaPatternValue,N'''',N'''''')+N''','''+@SchemaRegexFlags+N''')';SET @SchemaPredicateSch+=N' AND REGEXP_LIKE([sch].[name],N'''+REPLACE(@SchemaPatternValue,N'''',N'''''')+N''','''+@SchemaRegexFlags+N''')';END;
    IF @ObjectPatternMode='LIKE' SET @ObjectPredicateO+=N' AND [o].[name] COLLATE SQL_Latin1_General_CP1_CS_AS LIKE N'''+REPLACE(@ObjectPatternValue,N'''',N'''''')+N''' COLLATE SQL_Latin1_General_CP1_CS_AS';
    IF @ObjectPatternMode IN('REGEX','REGEXI') SET @ObjectPredicateO+=N' AND REGEXP_LIKE([o].[name],N'''+REPLACE(@ObjectPatternValue,N'''',N'''''')+N''','''+@ObjectRegexFlags+N''')';
    IF @IndexPatternMode='LIKE' SET @IndexPredicateI+=N' AND [i].[name] COLLATE SQL_Latin1_General_CP1_CS_AS LIKE N'''+REPLACE(@IndexPatternValue,N'''',N'''''')+N''' COLLATE SQL_Latin1_General_CP1_CS_AS';
    IF @IndexPatternMode IN('REGEX','REGEXI') SET @IndexPredicateI+=N' AND REGEXP_LIKE([i].[name],N'''+REPLACE(@IndexPatternValue,N'''',N'''''')+N''','''+@IndexRegexFlags+N''')';
    IF @StatisticsPatternMode='LIKE' SET @StatisticsPredicateSt+=N' AND [st].[name] COLLATE SQL_Latin1_General_CP1_CS_AS LIKE N'''+REPLACE(@StatisticsPatternValue,N'''',N'''''')+N''' COLLATE SQL_Latin1_General_CP1_CS_AS';
    IF @StatisticsPatternMode IN('REGEX','REGEXI') SET @StatisticsPredicateSt+=N' AND REGEXP_LIKE([st].[name],N'''+REPLACE(@StatisticsPatternValue,N'''',N'''''')+N''','''+@StatisticsRegexFlags+N''')';
    DECLARE @EffectiveMaxZeilen bigint = CASE WHEN @MaxZeilen IS NULL OR @MaxZeilen=0 THEN CONVERT(bigint,9223372036854775807) ELSE CONVERT(bigint,@MaxZeilen) END;
    DECLARE @MonitorPrintMessage nvarchar(2048); SET @AnalyseModus=UPPER(LTRIM(RTRIM(COALESCE(@AnalyseModus,'GEZIELT'))));
 IF @Hilfe=1
 BEGIN
        PRINT N'monitor.USP_Statistics';        PRINT N'@DatabaseNames: exakter Name oder bracket-aware Pipe-Liste; NULL = alle zulässigen Datenbanken; N'''' = keine Einschränkung.';        PRINT N'@SystemdatenbankenEinbeziehen bit = 0: Systemdatenbanken einbeziehen.';        PRINT N'Exakte Listen und ...NamePattern sind gegenseitig exklusiv. Pattern: LIKE (Default/like:), regex: oder regexi:.';
        PRINT N'Datenbankauswahl ohne Vorabbegrenzung; @MaxZeilen int: harte Ergebnismengenbegrenzung.';
        PRINT N'@LockTimeoutMs int = 0: Metadatenzugriff wartet standardmäßig nicht auf Locks.';
        PRINT N'@PrintMeldungen bit = 1: strukturierte Warnungen zusätzlich in der Console.';
        PRINT N'Die Procedure liefert Statistikalter, Stichprobenumfang, Zeilenanzahl und Modification Counter.';
        PRINT N'Ab SQL Server 2025 werden Herkunftsrolle und Replikatname aus sys.stats ausgegeben; CurrentReplicaRole bezeichnet davon getrennt die aktuelle Datenbankrolle.';
        PRINT N'@AnalyseModus = GEZIELT: Schema- oder Objektfilter ist erforderlich; VOLL prüft CATALOG_DEEP.';
        PRINT N'@StatisticsNamePattern: optionaler Statistikname-Filter.';
        PRINT N'@MinModificationPercent: 0 bis 100; nur entsprechende Statistiken.';
        PRINT N'@MinAlterTage: Mindestalter seit last_updated; 0 deaktiviert.';
        PRINT N'@MitIncrementellenDetails: zusätzliche Partitionswerte inkrementeller Statistiken.';
        PRINT N'@Hilfe bit = 0: 1 zeigt diese Hilfe und führt keine Analyse aus.';
        RETURN;
 END;

    DECLARE @ModuleName sysname = N'USP_Statistics';
    DECLARE @CollectionTimeUtc datetime2(3) = SYSUTCDATETIME();

    DECLARE @OverallStatus varchar(40) = 'AVAILABLE';
    DECLARE @IsPartial bit = 0;
    DECLARE @TotalRows bigint = 0;
    DECLARE @ErrorNumber int = NULL;
    DECLARE @ErrorMessage nvarchar(2048) = NULL;
    DECLARE @Detail nvarchar(2000) = NULL;

    CREATE TABLE [#Statistics_DatabaseStatus]
    (
          [DatabaseName]       sysname        NULL
        , [StatusCode]         varchar(40)    NOT NULL
        , [IsPartial]          bit            NOT NULL
        , [RowCount]           bigint         NOT NULL
        , [RequiredPermission] nvarchar(256)  NULL
        , [ErrorNumber]        int            NULL
        , [ErrorMessage]       nvarchar(2048) NULL
        , [Detail]             nvarchar(2000) NULL
    );

    IF @FilterStatus<>'AVAILABLE' BEGIN SET @OverallStatus=@FilterStatus;SET @ErrorMessage=@FilterError;END;
    IF @ResultSetArtNormalisiert NOT IN('RAW','CONSOLE','NONE') BEGIN SET @OverallStatus='INVALID_PARAMETER';SET @ErrorMessage=N'@ResultSetArt muss CONSOLE, RAW, TABLE oder NONE enthalten.';END;
    IF @SchemaPatternValid=0 OR @ObjectPatternValid=0 OR @IndexPatternValid=0 OR @StatisticsPatternValid=0 OR (@SchemaNames IS NOT NULL AND @SchemaNamePattern IS NOT NULL) OR (@ObjectNames IS NOT NULL AND @ObjectNamePattern IS NOT NULL) OR (@StatisticsNames IS NOT NULL AND @StatisticsNamePattern IS NOT NULL) BEGIN SET @OverallStatus='INVALID_PARAMETER';SET @ErrorMessage=N'Exakte Liste und Pattern derselben Eigenschaft sind gegenseitig exklusiv.';END;
IF @MaxZeilen<0 OR @LockTimeoutMs NOT BETWEEN 0 AND 60000
    BEGIN
        SET @OverallStatus = 'INVALID_PARAMETER';
        SET @ErrorMessage = N'Ungültiger Parameter: @MaxZeilen oder @LockTimeoutMs außerhalb des zulässigen Bereichs.';
    END


    IF @OverallStatus <> 'AVAILABLE'
    BEGIN
        INSERT [#Statistics_DatabaseStatus]([DatabaseName], [StatusCode], [IsPartial], [RowCount], [RequiredPermission], [ErrorNumber], [ErrorMessage], [Detail])
        VALUES(@DatabaseName, @OverallStatus, 1, 0, NULL, NULL, @ErrorMessage, N'Keine Datenbankanalyse ausgeführt.');
        SET @IsPartial = 1;
    END

 DECLARE @CatalogAllowed bit=1;
 IF @AnalyseModus='VOLL' OR @MitIncrementellenDetails=1 SELECT @CatalogAllowed=COALESCE(MAX(CONVERT(tinyint,[IsAllowed])),0) FROM [monitor].[VW_AnalyseAccessCurrent] WHERE [AnalysisClass]='CATALOG_DEEP';
 CREATE TABLE [#Statistics_Result]
 (
  [DatabaseName] sysname NOT NULL,[SchemaName] sysname NOT NULL,[ObjectName] sysname NOT NULL,[ObjectId] int NOT NULL,
  [StatisticsId] int NOT NULL,[StatisticsName] sysname NOT NULL,[IsIndexStatistics] bit NOT NULL,[IsAutoCreated] bit NULL,[IsUserCreated] bit NULL,
  [IsFiltered] bit NULL,[FilterDefinition] nvarchar(max) NULL,[NoRecompute] bit NULL,[IsIncremental] bit NULL,[HasPersistedSample] bit NULL,
  [IsTemporary] bit NULL,[CurrentReplicaRole] varchar(40) NULL,[CurrentReplicaRoleStatus] varchar(40) NOT NULL,
  [ReplicaRoleId] tinyint NULL,[ReplicaRoleDesc] nvarchar(60) NULL,
  [ReplicaName] sysname NULL,[ReplicaMetadataStatus] varchar(40) NOT NULL,
  [StatisticsColumns] nvarchar(max) NULL,[LastUpdated] datetime2 NULL,[Rows] bigint NULL,[RowsSampled] bigint NULL,[SamplePercent] decimal(9,4) NULL,
  [Steps] int NULL,[UnfilteredRows] bigint NULL,[ModificationCounter] bigint NULL,[ModificationPercent] decimal(19,4) NULL,
  [PersistedSamplePercent] float NULL,[DaysSinceLastUpdate] int NULL,[VisibilityOrState] varchar(40) NOT NULL
 );
 CREATE TABLE [#Statistics_Incremental]
 (
  [DatabaseName] sysname NOT NULL,[SchemaName] sysname NOT NULL,[ObjectName] sysname NOT NULL,[StatisticsId] int NOT NULL,[StatisticsName] sysname NOT NULL,
  [PartitionNumber] int NOT NULL,[LastUpdated] datetime2 NULL,[Rows] bigint NULL,[RowsSampled] bigint NULL,[Steps] int NULL,
  [UnfilteredRows] bigint NULL,[ModificationCounter] bigint NULL,[ModificationPercent] decimal(19,4) NULL
 );
 IF @OverallStatus='AVAILABLE' AND (@AnalyseModus NOT IN ('GEZIELT','VOLL') OR @MinModificationPercent<0 OR @MinModificationPercent>100 OR @MinAlterTage<0)
 BEGIN SET @OverallStatus='INVALID_PARAMETER'; SET @ErrorMessage=N'Ungültige Statistikparameter.'; INSERT [#Statistics_DatabaseStatus] VALUES(@DatabaseName,@OverallStatus,1,0,NULL,NULL,@ErrorMessage,NULL); END
 ELSE IF @OverallStatus='AVAILABLE' AND @AnalyseModus='GEZIELT' AND NOT EXISTS(SELECT 1 FROM [#Statistics_NameFilters]) AND @SchemaNamePattern IS NULL AND @ObjectNamePattern IS NULL
 BEGIN SET @OverallStatus='INVALID_PARAMETER'; SET @ErrorMessage=N'GEZIELT erfordert eine exakte Namensliste, @FullObjectNames oder ein Schema-/Objekt-Pattern.'; INSERT [#Statistics_DatabaseStatus] VALUES(@DatabaseName,@OverallStatus,1,0,NULL,NULL,@ErrorMessage,NULL); END
 ELSE IF @OverallStatus='AVAILABLE' AND (@AnalyseModus='VOLL' OR @MitIncrementellenDetails=1) AND @CatalogAllowed=0
 BEGIN SET @OverallStatus='DENIED_GROUP'; SET @ErrorMessage=N'CATALOG_DEEP ist für VOLL bzw. inkrementelle Details nicht freigegeben.'; INSERT [#Statistics_DatabaseStatus] VALUES(@DatabaseName,@OverallStatus,1,0,NULL,NULL,@ErrorMessage,NULL); END
 ELSE IF @OverallStatus='AVAILABLE'
 BEGIN
  DECLARE
        @DbId int
      , @DbName sysname
      , @Sql nvarchar(max)
      , @Rows bigint
      , @ReplicaMetadataColumnsAvailable bit
      , @ReplicaMetadataCapabilityStatus varchar(40)
      , @ReplicaProjection nvarchar(max)
      , @ReplicaCapabilitySql nvarchar(max)
      , @CurrentReplicaIsPrimary bit
      , @CurrentReplicaRole varchar(40)
      , @CurrentReplicaRoleStatus varchar(40)
      , @CurrentReplicaSql nvarchar(max);
  DECLARE dbcur CURSOR LOCAL FAST_FORWARD FOR SELECT [DatabaseId],[DatabaseName] FROM [#Statistics_DatabaseCandidates];
  OPEN dbcur; FETCH NEXT FROM dbcur INTO @DbId,@DbName;
  WHILE @@FETCH_STATUS=0
   BEGIN
   BEGIN TRY
    SET @CurrentReplicaIsPrimary=NULL;
    SET @CurrentReplicaRole=NULL;
    SET @CurrentReplicaRoleStatus='NOT_APPLICABLE';

    IF COALESCE(CONVERT(int,SERVERPROPERTY('IsHadrEnabled')),0)<>1
        SET @CurrentReplicaRole='HADR_DISABLED';
    ELSE
    BEGIN
     BEGIN TRY
      SET @CurrentReplicaSql =
          N'SET LOCK_TIMEOUT ' + CONVERT(nvarchar(11), @LockTimeoutMs)
        + N'; USE ' + QUOTENAME(@DbName) + N';
SELECT @pIsPrimary=sys.fn_hadr_is_primary_replica(@pDbName);';

      EXEC [sys].[sp_executesql]
            @CurrentReplicaSql
          , N'@pDbName sysname,@pIsPrimary bit OUTPUT'
          , @pDbName=@DbName
          , @pIsPrimary=@CurrentReplicaIsPrimary OUTPUT;

      SET @CurrentReplicaRole=
          CASE
              WHEN @CurrentReplicaIsPrimary=1 THEN 'PRIMARY'
              WHEN @CurrentReplicaIsPrimary=0 THEN 'SECONDARY'
              ELSE 'NOT_IN_AG_OR_UNKNOWN'
          END;
      SET @CurrentReplicaRoleStatus='AVAILABLE';
     END TRY
     BEGIN CATCH
      SET @CurrentReplicaRole=NULL;
      SET @CurrentReplicaRoleStatus=
          CASE
              WHEN ERROR_NUMBER() IN (229,262,297,300,371,916)
                  THEN 'DENIED_PERMISSION'
              WHEN ERROR_NUMBER()=1222
                  THEN 'TIMEOUT'
              ELSE 'ERROR_HANDLED'
          END;
     END CATCH;
    END;

    SET @ReplicaMetadataColumnsAvailable=0;
    SET @ReplicaMetadataCapabilityStatus=
        CASE
            WHEN COALESCE(@ProductMajorVersion,0)<17 THEN 'UNAVAILABLE_VERSION'
            ELSE 'UNAVAILABLE_COLUMNS'
        END;

    IF COALESCE(@ProductMajorVersion,0)>=17
    BEGIN
     BEGIN TRY
      SET @ReplicaCapabilitySql =
          N'SET LOCK_TIMEOUT ' + CONVERT(nvarchar(11), @LockTimeoutMs)
        + N'; USE ' + QUOTENAME(@DbName) + N';
SELECT @pAvailable =
       CONVERT(bit,CASE WHEN COUNT_BIG(*)=3 THEN 1 ELSE 0 END)
FROM sys.all_views AS [v] WITH (NOLOCK)
JOIN sys.schemas AS [s] WITH (NOLOCK)
  ON [s].[schema_id]=[v].[schema_id]
JOIN sys.all_columns AS [c] WITH (NOLOCK)
  ON [c].[object_id]=[v].[object_id]
WHERE [s].[name]=N''sys''
  AND [v].[name]=N''stats''
  AND [c].[name] IN
      (N''replica_role_id'',N''replica_role_desc'',N''replica_name'');';

      EXEC [sys].[sp_executesql]
            @ReplicaCapabilitySql
          , N'@pAvailable bit OUTPUT'
          , @pAvailable=@ReplicaMetadataColumnsAvailable OUTPUT;

      SET @ReplicaMetadataCapabilityStatus=
          CASE
              WHEN @ReplicaMetadataColumnsAvailable=1 THEN 'AVAILABLE'
              ELSE 'UNAVAILABLE_COLUMNS'
          END;
     END TRY
     BEGIN CATCH
      SET @ReplicaMetadataColumnsAvailable=0;
      SET @ReplicaMetadataCapabilityStatus=
          CASE
              WHEN ERROR_NUMBER() IN (229,262,297,300,371,916)
                  THEN 'DENIED_METADATA'
              WHEN ERROR_NUMBER()=1222
                  THEN 'TIMEOUT'
              ELSE 'CAPABILITY_ERROR'
          END;
     END CATCH;
    END;

    SET @ReplicaProjection =
        CASE
            WHEN @ReplicaMetadataColumnsAvailable=1
            THEN N'
 [st].[is_temporary],
 @pCurrentReplicaRole,@pCurrentReplicaRoleStatus,
 [st].[replica_role_id],[st].[replica_role_desc],[st].[replica_name],
 CASE
      WHEN [st].[replica_role_id] IS NULL
       AND [st].[replica_role_desc] IS NULL
       AND [st].[replica_name] IS NULL
          THEN ''NOT_RECORDED''
      WHEN [st].[replica_role_id] BETWEEN 1 AND 4
       AND [st].[replica_role_desc] COLLATE Latin1_General_100_CI_AI=
           CASE [st].[replica_role_id]
                WHEN 1 THEN N''Primary''
                WHEN 2 THEN N''Secondary''
                WHEN 3 THEN N''Geo Secondary''
                WHEN 4 THEN N''Geo HA Secondary''
           END
       AND ([st].[replica_role_id]=1 OR [st].[replica_name] IS NOT NULL)
          THEN ''AVAILABLE''
      ELSE ''PARTIAL_METADATA''
 END'
            ELSE N'
 [st].[is_temporary],
 @pCurrentReplicaRole,@pCurrentReplicaRoleStatus,
 CONVERT(tinyint,NULL),CONVERT(nvarchar(60),NULL),CONVERT(sysname,NULL),
 @pReplicaMetadataStatus'
        END;

    SET @Sql = N'SET LOCK_TIMEOUT ' + CONVERT(nvarchar(11), @LockTimeoutMs) + N'; USE ' + QUOTENAME(@DbName) + N';
INSERT #Statistics_Result
SELECT TOP (@pMaxRows)
 @pDbName,[sch].[name],[o].[name],[o].[object_id],[st].[stats_id],[st].[name],CONVERT(bit,CASE WHEN [ix].[index_id] IS NULL THEN 0 ELSE 1 END),
 [st].[auto_created],[st].[user_created],[st].[has_filter],[st].[filter_definition],[st].[no_recompute],[st].[is_incremental],[st].[has_persisted_sample],
 '+@ReplicaProjection+N',
 [cols].[StatisticsColumns],[sp].[last_updated],[sp].[rows],[sp].[rows_sampled],
 CONVERT(decimal(9,4),[sp].[rows_sampled]*100.0/NULLIF([sp].[rows],0)),[sp].[steps],[sp].[unfiltered_rows],[sp].[modification_counter],
 CONVERT(decimal(19,4),[sp].[modification_counter]*100.0/NULLIF([sp].[rows],0)),[sp].[persisted_sample_percent],
 CASE WHEN [sp].[last_updated] IS NULL THEN NULL ELSE DATEDIFF(DAY,[sp].[last_updated],SYSDATETIME()) END,
 CASE WHEN [sp].[last_updated] IS NULL AND [sp].[rows] IS NULL THEN ''NOT_VISIBLE_OR_NOT_MATERIALIZED''
      WHEN [sp].[rows]=0 THEN ''EMPTY_OR_FILTER_NO_ROWS''
      ELSE ''VISIBLE'' END
FROM sys.stats AS [st] WITH (NOLOCK)
JOIN sys.objects AS [o] WITH (NOLOCK) ON [o].[object_id]=[st].[object_id]
JOIN sys.schemas AS [sch] WITH (NOLOCK) ON [sch].[schema_id]=[o].[schema_id]
LEFT JOIN sys.indexes AS [ix] WITH (NOLOCK) ON [ix].[object_id]=[st].[object_id] AND [ix].[index_id]=[st].[stats_id]
OUTER APPLY sys.dm_db_stats_properties([st].[object_id],[st].[stats_id]) AS [sp]
OUTER APPLY
(
 SELECT STUFF((SELECT N'', ''+QUOTENAME([c].[name])
               FROM sys.stats_columns AS [sc] WITH (NOLOCK)
               JOIN sys.columns AS [c] WITH (NOLOCK) ON [c].[object_id]=[sc].[object_id] AND [c].[column_id]=[sc].[column_id]
               WHERE [sc].[object_id]=[st].[object_id] AND [sc].[stats_id]=[st].[stats_id]
               ORDER BY [sc].[stats_column_id] FOR XML PATH(''''),TYPE).value(''.'',''nvarchar(max)''),1,2,N'''') AS [StatisticsColumns]
) AS [cols]
WHERE [o].[type] IN (''U'',''V'') AND [o].[is_ms_shipped]=0
'+@SchemaPredicateSch+@ObjectPredicateO+REPLACE(@FullObjectPredicateSO,N'[s].[name]',N'[sch].[name]')+N'
'+@StatisticsPredicateSt+N'
 AND (COALESCE([sp].[modification_counter]*100.0/NULLIF([sp].[rows],0),0)>=@pMinModPct)
 AND (@pMinAge=0 OR [sp].[last_updated] IS NULL OR DATEDIFF(DAY,[sp].[last_updated],SYSDATETIME())>=@pMinAge)
ORDER BY COALESCE([sp].[modification_counter]*100.0/NULLIF([sp].[rows],0),0) DESC,[sp].[last_updated]
OPTION (MAXDOP 1, RECOMPILE);
IF @pWithIncremental=1
BEGIN
 BEGIN TRY
  INSERT #Statistics_Incremental
  SELECT TOP (@pMaxRows) @pDbName,[base].[SchemaName],[base].[ObjectName],[base].[StatisticsId],[base].[StatisticsName],[ip].[partition_number],[ip].[last_updated],[ip].[rows],[ip].[rows_sampled],[ip].[steps],[ip].[unfiltered_rows],[ip].[modification_counter],
         CONVERT(decimal(19,4),[ip].[modification_counter]*100.0/NULLIF([ip].[rows],0))
  FROM #Statistics_Result AS [base]
  CROSS APPLY sys.dm_db_incremental_stats_properties([base].[ObjectId],[base].[StatisticsId]) AS [ip]
  WHERE [base].[DatabaseName]=@pDbName
    AND [base].[IsIncremental]=1
  ORDER BY [ip].[modification_counter]*100.0/NULLIF([ip].[rows],0) DESC;
 END TRY
 BEGIN CATCH
  INSERT #Statistics_DatabaseStatus VALUES(@pDbName,
   CASE WHEN ERROR_NUMBER() IN (229,262,297,300,371,916) THEN ''DENIED_PERMISSION'' WHEN ERROR_NUMBER()=1222 THEN ''TIMEOUT'' WHEN ERROR_NUMBER() IN (207,208,4121) THEN ''UNAVAILABLE_OBJECT'' ELSE ''ERROR_HANDLED'' END,
   1,0,N''SELECT auf Statistikspalten oder geeignete Rolle/Eigentum'',ERROR_NUMBER(),ERROR_MESSAGE(),N''Quelle STATS_INCREMENTAL fehlgeschlagen; Basisstatistiken bleiben erhalten.'');
 END CATCH;
END;';
    EXEC [sys].[sp_executesql]
          @Sql
        , N'@pDbName sysname,@pMaxRows bigint,@pSchemaLike nvarchar(256),@pObjectLike nvarchar(256),@pStatsLike nvarchar(256),@pMinModPct decimal(9,2),@pMinAge int,@pWithIncremental bit,@pCurrentReplicaRole varchar(40),@pCurrentReplicaRoleStatus varchar(40),@pReplicaMetadataStatus varchar(40)'
        , @pDbName=@DbName
        , @pMaxRows=@EffectiveMaxZeilen
        , @pSchemaLike=@SchemaNameLike
        , @pObjectLike=@ObjectNameLike
        , @pStatsLike=@StatisticsNameLike
        , @pMinModPct=@MinModificationPercent
        , @pMinAge=@MinAlterTage
        , @pWithIncremental=@MitIncrementellenDetails
        , @pCurrentReplicaRole=@CurrentReplicaRole
        , @pCurrentReplicaRoleStatus=@CurrentReplicaRoleStatus
        , @pReplicaMetadataStatus=@ReplicaMetadataCapabilityStatus;

    SET @Rows=
        (SELECT COUNT_BIG(*)
         FROM [#Statistics_Result]
         WHERE [DatabaseName]=@DbName);

    INSERT [#Statistics_DatabaseStatus]
    VALUES
    (
          @DbName
        , CASE
              WHEN @Rows>0
               AND @ReplicaMetadataCapabilityStatus IN
                   ('AVAILABLE','UNAVAILABLE_VERSION','UNAVAILABLE_COLUMNS')
               AND @CurrentReplicaRoleStatus IN ('AVAILABLE','NOT_APPLICABLE')
               AND NOT EXISTS
                   (
                       SELECT 1
                       FROM [#Statistics_Result]
                       WHERE [DatabaseName]=@DbName
                         AND [ReplicaMetadataStatus]='PARTIAL_METADATA'
                   )
                  THEN 'AVAILABLE'
              ELSE 'AVAILABLE_LIMITED'
          END
        , CONVERT(bit,CASE
              WHEN @Rows>0
               AND @ReplicaMetadataCapabilityStatus IN
                   ('AVAILABLE','UNAVAILABLE_VERSION','UNAVAILABLE_COLUMNS')
               AND @CurrentReplicaRoleStatus IN ('AVAILABLE','NOT_APPLICABLE')
               AND NOT EXISTS
                   (
                       SELECT 1
                       FROM [#Statistics_Result]
                       WHERE [DatabaseName]=@DbName
                         AND [ReplicaMetadataStatus]='PARTIAL_METADATA'
                   )
                  THEN 0
              ELSE 1
          END)
        , @Rows
        , N'SELECT [auf] [Statistikspalten] oder [Eigentum]/[db_owner]/[db_ddladmin]/[sysadmin]'
        , NULL
        , NULL
        , CONCAT
          (
              N'ReplicaMetadataStatus=',@ReplicaMetadataCapabilityStatus,
              N'; CurrentReplicaRoleStatus=',@CurrentReplicaRoleStatus,
              N'; RowScope=',CASE WHEN @Rows=0
                                  THEN N'EMPTY_OR_RESTRICTED'
                                  ELSE N'VISIBLE' END,
              N'; NULL-Werte können fehlende Sichtbarkeit, nicht aufgezeichnete Herkunft oder noch nicht materialisierte Statistiken bedeuten.'
          )
    );
   END TRY
   BEGIN CATCH
    INSERT [#Statistics_DatabaseStatus] VALUES(@DbName,CASE WHEN ERROR_NUMBER() IN (229,262,297,300,371,916) THEN 'DENIED_PERMISSION' WHEN ERROR_NUMBER()=1222 THEN 'TIMEOUT' ELSE 'ERROR_HANDLED' END,1,0,N'SELECT [auf] [Statistikspalten] oder [geeignete] [Rolle]/[Eigentum]',ERROR_NUMBER(),ERROR_MESSAGE(),N'Statistikfehler isoliert.');
   END CATCH;
   FETCH NEXT FROM dbcur INTO @DbId,@DbName;
  END; CLOSE dbcur; DEALLOCATE dbcur;
  IF NOT EXISTS(SELECT 1 FROM [#Statistics_DatabaseStatus]) INSERT [#Statistics_DatabaseStatus] VALUES(@DatabaseName,'DATABASE_UNAVAILABLE',1,0,NULL,NULL,N'Keine sichtbare Online-Zieldatenbank gefunden.',NULL);
 END;

    IF @@LOCK_TIMEOUT<>@OriginalLockTimeout
        THROW 51012,N'USP_Statistics hat den äußeren LOCK_TIMEOUT verändert.',1;

    IF @OverallStatus<>'AVAILABLE' SET @IsPartial=1;

    SELECT @TotalRows=(SELECT COUNT_BIG(*) FROM [#Statistics_Result])+(SELECT COUNT_BIG(*) FROM [#Statistics_Incremental]);

    IF @OverallStatus = 'AVAILABLE'
    BEGIN
        IF EXISTS (SELECT 1 FROM [#Statistics_DatabaseStatus] WHERE [StatusCode] NOT IN ('AVAILABLE','AVAILABLE_LIMITED','SKIPPED','NOT_APPLICABLE'))
        BEGIN
            SET @OverallStatus = CASE WHEN @TotalRows > 0 THEN 'PARTIAL' ELSE (SELECT TOP (1) [StatusCode] FROM [#Statistics_DatabaseStatus] WHERE [StatusCode] NOT IN ('AVAILABLE','AVAILABLE_LIMITED','SKIPPED','NOT_APPLICABLE') ORDER BY [DatabaseName]) END;
            SET @IsPartial = 1;
        END
        ELSE IF EXISTS (SELECT 1 FROM [#Statistics_DatabaseStatus] WHERE [StatusCode] IN ('AVAILABLE_LIMITED','SKIPPED','NOT_APPLICABLE'))
        BEGIN
            SET @OverallStatus = CASE WHEN @TotalRows > 0 THEN 'AVAILABLE_LIMITED' ELSE 'SKIPPED' END;
            SET @IsPartial = 1;
        END;
    END;

    IF @PrintMeldungen = 1 AND @OverallStatus <> 'AVAILABLE'
        BEGIN
    SET @MonitorPrintMessage = FORMATMESSAGE(N'WARNUNG %s: %s', @OverallStatus, COALESCE(@ErrorMessage, @Detail, N'Teilergebnis oder eingeschränkte Sicht'));
    RAISERROR(N'%s', 10, 1, @MonitorPrintMessage) WITH NOWAIT;
END;

    IF @ResultSetArtNormalisiert<>'NONE' BEGIN
        SELECT @ModuleName [ModuleName],@CollectionTimeUtc [CollectionTimeUtc],@OverallStatus [StatusCode],@IsPartial [IsPartial],@TotalRows [RowCount],@ErrorNumber [ErrorNumber],@ErrorMessage [ErrorMessage],@Detail [Detail];
        SELECT [DatabaseName],[StatusCode],[IsPartial],[RowCount],[RequiredPermission],[ErrorNumber],[ErrorMessage],[Detail] FROM [#Statistics_DatabaseStatus] ORDER BY [DatabaseName];
        IF @ResultSetArtNormalisiert='RAW'
            SELECT * FROM [#Statistics_Result] ORDER BY [ModificationPercent] DESC,[DatabaseName],[SchemaName],[ObjectName],[StatisticsName];
        ELSE
            SELECT N'Statistik' [Ergebnis],[r].* FROM [#Statistics_Result] [r] ORDER BY [ModificationPercent] DESC,[DatabaseName],[SchemaName],[ObjectName],[StatisticsName];

        IF @MitIncrementellenDetails=1
        BEGIN
            IF @ResultSetArtNormalisiert='RAW'
                SELECT * FROM [#Statistics_Incremental] ORDER BY [ModificationPercent] DESC,[DatabaseName],[SchemaName],[ObjectName],[StatisticsName],[PartitionNumber];
            ELSE
                SELECT N'Inkrementelle Statistikpartition' [Ergebnis],[i].* FROM [#Statistics_Incremental] [i] ORDER BY [ModificationPercent] DESC,[DatabaseName],[SchemaName],[ObjectName],[StatisticsName],[PartitionNumber];
        END;
    END;
    IF @JsonErzeugen=1 BEGIN
        DECLARE @JsonMeta nvarchar(max)=(SELECT @ModuleName [resultName],2 [schemaVersion],@CollectionTimeUtc [generatedAtUtc],@OverallStatus [statusCode],@IsPartial [isPartial],@TotalRows [rowCount] FOR JSON PATH,WITHOUT_ARRAY_WRAPPER,INCLUDE_NULL_VALUES);
        DECLARE @JsonDatabaseStatus nvarchar(max)=(SELECT * FROM [#Statistics_DatabaseStatus] ORDER BY [DatabaseName] FOR JSON PATH,INCLUDE_NULL_VALUES);
        DECLARE @JsonData1 nvarchar(max)=(SELECT * FROM [#Statistics_Result] ORDER BY [ModificationPercent] DESC,[DatabaseName],[SchemaName],[ObjectName],[StatisticsName] FOR JSON PATH,INCLUDE_NULL_VALUES);
        DECLARE @JsonIncremental nvarchar(max)=(SELECT * FROM [#Statistics_Incremental] ORDER BY [ModificationPercent] DESC,[DatabaseName],[SchemaName],[ObjectName],[StatisticsName],[PartitionNumber] FOR JSON PATH,INCLUDE_NULL_VALUES);
        SET @Json=CONCAT(N'{"meta":',COALESCE(@JsonMeta,N'{}'),N',"statistics":',COALESCE(@JsonData1,N'[]'),N',"incrementalStatistics":',COALESCE(@JsonIncremental,N'[]'),N',"databaseStatus":',COALESCE(@JsonDatabaseStatus,N'[]'),N'}');
    END;
    IF @ConsoleResultRequested = 1
    BEGIN
        EXEC [monitor].[InternalEmitConsoleResult]
              @SourceTable=N'#Statistics_Result'
            , @ResultLabel=N'Statistics'
            , @EmptyMessage=N'Keine fachlichen Ergebnisse';
    END;
    IF @TableResultRequested = 1
    BEGIN
        EXEC [monitor].[InternalWriteResultTable]
              @SourceTable = N'#Statistics_Result'
            , @TargetTable=@TableTarget
            , @ThrowOnError = 1;
    END;
END;
GO
-- END SOURCE: Code/03_ObjectIndex/040_USP_Statistics.sql

-- BEGIN SOURCE: Code/03_ObjectIndex/045_USP_StatisticsDistributionAnalysis.sql
/*
===============================================================================
Objekt       : monitor.USP_StatisticsDistributionAnalysis
Version      : 1.0.0
Stand        : 2026-07-17
Typ          : Stored Procedure
Zweck        : Analysiert begrenzt und opt-in die Verteilung sichtbarer
               Statistikhistogramme sowie die Änderungsvariation inkrementeller
               Statistikpartitionen.
SQL-Version  : SQL Server 2019 oder neuer.
Datenquellen : monitor.USP_Statistics, sys.stats_columns, sys.columns,
               sys.types und sys.dm_db_stats_histogram.
Methodik     : Die Kandidatenmenge wird je Datenbank vor dem Histogrammzugriff
               begrenzt. Bewertet werden ausschließlich numerische Verteilungs-
               kennzahlen; konkrete Histogrammgrenzwerte sind für diese
               Auswertung nicht erforderlich.
Grenzen      : Skew, Tail-Konzentration und Änderungen seit dem Statistikstand
               sind Prüfhinweise, kein Beweis für einen schlechten Plan oder
               Werte außerhalb des Histogramms. Query-/Prädikatkontext und
               tatsächliche Kardinalitätsabweichungen müssen separat korreliert
               werden. Es werden keine Statistiken aktualisiert und keine Daten
               aus Benutzertabellen gelesen.
Kosten       : HIGH_OPT_IN. CATALOG_DEEP-Freigabe, gezielter Scope oder bewusst
               gewählter VOLL-Modus sowie eine harte Kandidatengrenze.
===============================================================================
*/
CREATE OR ALTER PROCEDURE [monitor].[USP_StatisticsDistributionAnalysis]
      @DatabaseNames                       nvarchar(max)  = NULL
    , @SystemdatenbankenEinbeziehen        bit            = 0
    , @DatabaseNamePattern                 nvarchar(4000) = NULL
    , @HighImpactConfirmed              bit            = 0
    , @SchemaNames                         nvarchar(max)  = NULL
    , @SchemaNamePattern                   nvarchar(4000) = NULL
    , @ObjectNames                         nvarchar(max)  = NULL
    , @ObjectNamePattern                   nvarchar(4000) = NULL
    , @FullObjectNames                     nvarchar(max)  = NULL
    , @StatisticsNames                     nvarchar(max)  = NULL
    , @StatisticsNamePattern               nvarchar(4000) = NULL
    , @AnalyseModus                        varchar(16)     = 'GEZIELT'
    , @MaxVerteilungsStatistiken           int             = 50
    , @MinVerteilungsZeilen                bigint          = 1000
    , @SkewWarnFaktor                      decimal(19,4)   = 10
    , @DominanterSchrittWarnPercent        decimal(9,4)    = 50
    , @ModificationWarnPercent             decimal(9,4)    = 20
    , @PartitionSpreadWarnPercent          decimal(9,4)    = 20
    , @MaxZeilen                           int             = 1000
    , @LockTimeoutMs                       int             = 0
    , @ResultSetArt                        varchar(16)     = 'CONSOLE'
    , @ResultTablesJson               nvarchar(max) = NULL
    , @JsonErzeugen                        bit             = 0
    , @Json                                nvarchar(max)   = NULL OUTPUT
    , @PrintMeldungen                      bit             = 1
    , @Hilfe                               bit             = 0
    , @StatusCodeOut                       varchar(40)     = NULL OUTPUT
    , @IsPartialOut                        bit             = NULL OUTPUT
    , @ErrorNumberOut                      int             = NULL OUTPUT
    , @ErrorMessageOut                     nvarchar(2048)  = NULL OUTPUT
AS
BEGIN
    SET NOCOUNT ON;
    SET LOCK_TIMEOUT 0;
    SET @Json = NULL;

    DECLARE @OutputMode varchar(16)=UPPER(LTRIM(RTRIM(COALESCE(@ResultSetArt,''))));
    DECLARE @TableResultRequested bit = CASE WHEN @OutputMode = 'TABLE' THEN 1 ELSE 0 END;
    DECLARE @ConsoleResultRequested bit = CASE WHEN @OutputMode = 'CONSOLE' THEN 1 ELSE 0 END;
    DECLARE @TableTarget sysname=NULL;
    IF @TableResultRequested=0 AND NULLIF(LTRIM(RTRIM(COALESCE(@ResultTablesJson,N''))),N'') IS NOT NULL THROW 51011,N'@ResultTablesJson ist ausschließlich mit @ResultSetArt=TABLE zulässig.',1;
    IF @TableResultRequested=1 EXEC [monitor].[InternalPrepareSingleResultTable] @ResultTablesJson=@ResultTablesJson,@ResultName=N'findings',@TargetTable=@TableTarget OUTPUT,@ThrowOnError=1;
    IF @TableResultRequested = 1 OR @ConsoleResultRequested = 1 SET @OutputMode = 'NONE';
    DECLARE @Mode varchar(16)=UPPER(LTRIM(RTRIM(COALESCE(@AnalyseModus,''))));
    DECLARE @Now datetime2(3)=SYSUTCDATETIME();
    DECLARE @StatusCode varchar(40)='AVAILABLE';
    DECLARE @IsPartial bit=0;
    DECLARE @ErrorNumber int=NULL;
    DECLARE @ErrorMessage nvarchar(2048)=NULL;
    DECLARE @PrintMessage nvarchar(2048);
    DECLARE @Limit bigint=CASE WHEN @MaxZeilen IS NULL OR @MaxZeilen=0
                               THEN CONVERT(bigint,9223372036854775807)
                               ELSE CONVERT(bigint,@MaxZeilen) END;
    DECLARE @CandidatePoolRows int=CASE WHEN @MaxVerteilungsStatistiken BETWEEN 1 AND 250
                                        THEN @MaxVerteilungsStatistiken*4 ELSE 1000 END;
    IF @CandidatePoolRows>1000 SET @CandidatePoolRows=1000;

    IF @Hilfe=1
    BEGIN
        PRINT N'monitor.USP_StatisticsDistributionAnalysis';
        PRINT N'Die Procedure führt eine optionale Verteilungsanalyse sichtbarer Statistikhistogramme durch und verändert weder Daten noch Konfiguration.';
        PRINT N'@AnalyseModus=GEZIELT erfordert Objekt-/Schema-/Statistikfilter; VOLL benötigt CATALOG_DEEP.';
        PRINT N'@MaxVerteilungsStatistiken=1..250 begrenzt den Histogrammzugriff je Datenbank vor der Analyse.';
        PRINT N'@MinVerteilungsZeilen, @SkewWarnFaktor, @DominanterSchrittWarnPercent, @ModificationWarnPercent und @PartitionSpreadWarnPercent steuern Hinweise.';
        PRINT N'@MaxZeilen positiv begrenzt Resultsets; NULL/0 bedeutet unbegrenzt. @ResultSetArt=CONSOLE|RAW|TABLE|NONE; TABLE verwendet @ResultTablesJson.';
        PRINT N'Verteilungsindikatoren beweisen weder schlechte Pläne noch Out-of-Range-Werte; Query- und Laufzeitkontext separat prüfen.';
        RETURN;
    END;

    IF @Mode NOT IN ('GEZIELT','VOLL')
       OR @OutputMode NOT IN ('RAW','CONSOLE','NONE')
       OR @MaxVerteilungsStatistiken IS NULL OR @MaxVerteilungsStatistiken NOT BETWEEN 1 AND 250
       OR @MinVerteilungsZeilen IS NULL OR @MinVerteilungsZeilen<0
       OR @SkewWarnFaktor IS NULL OR @SkewWarnFaktor<1 OR @SkewWarnFaktor>100000
       OR @DominanterSchrittWarnPercent IS NULL OR @DominanterSchrittWarnPercent<0 OR @DominanterSchrittWarnPercent>100
       OR @ModificationWarnPercent IS NULL OR @ModificationWarnPercent<0 OR @ModificationWarnPercent>100
       OR @PartitionSpreadWarnPercent IS NULL OR @PartitionSpreadWarnPercent<0 OR @PartitionSpreadWarnPercent>100
 OR @MaxZeilen<0 OR @LockTimeoutMs NOT BETWEEN 0 AND 60000
    BEGIN
        SELECT @StatusCode='INVALID_PARAMETER',@IsPartial=1,
               @ErrorMessage=N'Ungültiger Modus, Grenzwert-, Mengen-, Lock-Timeout- oder Ausgabeparameter.';
    END;

    IF @StatusCode='AVAILABLE'
        EXEC [monitor].[InternalCheckAnalysisPath]
              @AnalysisClass='CATALOG_DEEP'
            , @HighImpactConfirmed=@HighImpactConfirmed
            , @StatusCode=@StatusCode OUTPUT
            , @ErrorMessage=@ErrorMessage OUTPUT;
    IF @StatusCode<>'AVAILABLE' SET @IsPartial=1;

    DECLARE @CurrentCompatibilityLevel int=NULL;
    IF @StatusCode='AVAILABLE'
        SELECT @CurrentCompatibilityLevel=[compatibility_level]
        FROM [sys].[databases] WITH (NOLOCK)
        WHERE [database_id]=DB_ID();
    IF @StatusCode='AVAILABLE' AND @CurrentCompatibilityLevel<130
    BEGIN
        SELECT @StatusCode='UNAVAILABLE_FEATURE',@IsPartial=1,
               @ErrorMessage=N'Die Verteilungsanalyse benötigt Compatibility Level 130 oder höher für OPENJSON.';
    END;

    CREATE TABLE [#StatisticsDistributionAnalysis_Candidates]
    (
          [DatabaseName] sysname NOT NULL
        , [SchemaName] sysname NOT NULL
        , [ObjectName] sysname NOT NULL
        , [ObjectId] int NOT NULL
        , [StatisticsId] int NOT NULL
        , [StatisticsName] sysname NOT NULL
        , [Rows] bigint NULL
        , [RowsSampled] bigint NULL
        , [SamplePercent] decimal(9,4) NULL
        , [Steps] int NULL
        , [ModificationCounter] bigint NULL
        , [ModificationPercent] decimal(19,4) NULL
        , [DaysSinceLastUpdate] int NULL
        , [IsFiltered] bit NULL
        , [IsIncremental] bit NULL
        , [HasPersistedSample] bit NULL
        , [PersistedSamplePercent] float NULL
        , [CandidateOrdinal] int NULL
    );
    CREATE TABLE [#StatisticsDistributionAnalysis_Incremental]
    (
          [DatabaseName] sysname NOT NULL
        , [SchemaName] sysname NOT NULL
        , [ObjectName] sysname NOT NULL
        , [StatisticsId] int NOT NULL
        , [StatisticsName] sysname NOT NULL
        , [PartitionNumber] int NOT NULL
        , [Rows] bigint NULL
        , [RowsSampled] bigint NULL
        , [ModificationCounter] bigint NULL
        , [ModificationPercent] decimal(19,4) NULL
    );
    CREATE TABLE [#StatisticsDistributionAnalysis_DistributionDatabaseStatus]
    (
          [DatabaseName] sysname NULL
        , [StatusCode] varchar(40) NOT NULL
        , [IsPartial] bit NOT NULL
        , [CandidateCount] bigint NOT NULL
        , [HistogramVisibleCount] bigint NOT NULL
        , [RequiredPermission] nvarchar(256) NULL
        , [ErrorNumber] int NULL
        , [ErrorMessage] nvarchar(2048) NULL
        , [Detail] nvarchar(2000) NULL
    );
    CREATE TABLE [#StatisticsDistributionAnalysis_Distribution]
    (
          [DatabaseName] sysname NOT NULL
        , [SchemaName] sysname NOT NULL
        , [ObjectName] sysname NOT NULL
        , [ObjectId] int NOT NULL
        , [StatisticsId] int NOT NULL
        , [StatisticsName] sysname NOT NULL
        , [CandidateOrdinal] int NOT NULL
        , [LeadingColumnName] sysname NULL
        , [LeadingTypeName] sysname NULL
        , [Rows] bigint NULL
        , [RowsSampled] bigint NULL
        , [SamplePercent] decimal(9,4) NULL
        , [ModificationCounter] bigint NULL
        , [ModificationPercent] decimal(19,4) NULL
        , [DaysSinceLastUpdate] int NULL
        , [IsFiltered] bit NULL
        , [IsIncremental] bit NULL
        , [HasPersistedSample] bit NULL
        , [PersistedSamplePercent] float NULL
        , [HistogramSteps] int NOT NULL
        , [HistogramEstimatedRows] decimal(38,4) NULL
        , [MaxEqualRows] decimal(38,4) NULL
        , [MaxRangeRows] decimal(38,4) NULL
        , [MaxStepRows] decimal(38,4) NULL
        , [DominantStepPercent] decimal(19,4) NULL
        , [EqualRowsSkewRatio] decimal(19,4) NULL
        , [AverageRangeRowsSkewRatio] decimal(19,4) NULL
        , [TailStepRows] decimal(38,4) NULL
        , [TailStepPercent] decimal(19,4) NULL
        , [TailVsAverageStepRatio] decimal(19,4) NULL
        , [AnalysisState] varchar(40) NOT NULL
        , [EvidenceLimit] nvarchar(1000) NOT NULL
    );
    CREATE TABLE [#StatisticsDistributionAnalysis_PartitionVariation]
    (
          [DatabaseName] sysname NOT NULL
        , [SchemaName] sysname NOT NULL
        , [ObjectName] sysname NOT NULL
        , [StatisticsId] int NOT NULL
        , [StatisticsName] sysname NOT NULL
        , [PartitionCount] int NOT NULL
        , [PartitionsWithRows] int NOT NULL
        , [TotalRows] bigint NULL
        , [TotalModificationCounter] bigint NULL
        , [WeightedModificationPercent] decimal(19,4) NULL
        , [MinModificationPercent] decimal(19,4) NULL
        , [MaxModificationPercent] decimal(19,4) NULL
        , [ModificationSpreadPercentPoints] decimal(19,4) NULL
    );
    CREATE TABLE [#StatisticsDistributionAnalysis_Findings]
    (
          [FindingOrdinal] bigint IDENTITY(1,1) NOT NULL
        , [DatabaseName] sysname NULL
        , [SchemaName] sysname NULL
        , [ObjectName] sysname NULL
        , [StatisticsName] sysname NULL
        , [Severity] varchar(16) NOT NULL
        , [Confidence] varchar(16) NOT NULL
        , [FindingCode] varchar(120) NOT NULL
        , [MetricName] varchar(80) NOT NULL
        , [MetricValue] decimal(38,4) NULL
        , [ThresholdValue] decimal(38,4) NULL
        , [Evidence] nvarchar(1000) NOT NULL
        , [EvidenceLimit] nvarchar(1000) NOT NULL
        , [RecommendedNextCheck] nvarchar(1000) NOT NULL
    );

    DECLARE @StatisticsJson nvarchar(max)=NULL;
    IF @StatusCode='AVAILABLE'
    BEGIN TRY
        EXEC [monitor].[USP_Statistics]
              @DatabaseNames=@DatabaseNames
            , @SystemdatenbankenEinbeziehen=@SystemdatenbankenEinbeziehen
            , @DatabaseNamePattern=@DatabaseNamePattern,@HighImpactConfirmed=@HighImpactConfirmed
            , @SchemaNames=@SchemaNames,@SchemaNamePattern=@SchemaNamePattern
            , @ObjectNames=@ObjectNames,@ObjectNamePattern=@ObjectNamePattern
            , @FullObjectNames=@FullObjectNames
            , @StatisticsNames=@StatisticsNames,@StatisticsNamePattern=@StatisticsNamePattern
            , @AnalyseModus=@Mode,@MinModificationPercent=0,@MinAlterTage=0
            , @MitIncrementellenDetails=1
            , @MaxZeilen=@CandidatePoolRows,@LockTimeoutMs=@LockTimeoutMs
            , @ResultSetArt='NONE',@JsonErzeugen=1,@Json=@StatisticsJson OUTPUT
            , @PrintMeldungen=@PrintMeldungen;

        SET @StatusCode=COALESCE(JSON_VALUE(@StatisticsJson,'$.meta.statusCode'),'ERROR_HANDLED');
        SET @IsPartial=CASE JSON_VALUE(@StatisticsJson,'$.meta.isPartial')
                           WHEN 'true' THEN 1 WHEN 'false' THEN 0
                           ELSE COALESCE(TRY_CONVERT(bit,JSON_VALUE(@StatisticsJson,'$.meta.isPartial')),1) END;

        INSERT [#StatisticsDistributionAnalysis_Candidates]
        (
              [DatabaseName],[SchemaName],[ObjectName],[ObjectId],[StatisticsId],[StatisticsName]
            , [Rows],[RowsSampled],[SamplePercent],[Steps],[ModificationCounter],[ModificationPercent]
            , [DaysSinceLastUpdate],[IsFiltered],[IsIncremental],[HasPersistedSample],[PersistedSamplePercent]
        )
        SELECT [DatabaseName],[SchemaName],[ObjectName],[ObjectId],[StatisticsId],[StatisticsName]
             , [Rows],[RowsSampled],[SamplePercent],[Steps],[ModificationCounter],[ModificationPercent]
             , [DaysSinceLastUpdate],[IsFiltered],[IsIncremental],[HasPersistedSample],[PersistedSamplePercent]
        FROM OPENJSON(COALESCE(@StatisticsJson,N'{}'),'$.statistics') WITH
        (
              [DatabaseName] sysname, [SchemaName] sysname, [ObjectName] sysname
            , [ObjectId] int, [StatisticsId] int, [StatisticsName] sysname
            , [Rows] bigint, [RowsSampled] bigint, [SamplePercent] decimal(9,4), [Steps] int
            , [ModificationCounter] bigint, [ModificationPercent] decimal(19,4)
            , [DaysSinceLastUpdate] int, [IsFiltered] bit, [IsIncremental] bit
            , [HasPersistedSample] bit, [PersistedSamplePercent] float
        );

        INSERT [#StatisticsDistributionAnalysis_Incremental]
        SELECT [DatabaseName],[SchemaName],[ObjectName],[StatisticsId],[StatisticsName]
             , [PartitionNumber],[Rows],[RowsSampled],[ModificationCounter],[ModificationPercent]
        FROM OPENJSON(COALESCE(@StatisticsJson,N'{}'),'$.incrementalStatistics') WITH
        (
              [DatabaseName] sysname, [SchemaName] sysname, [ObjectName] sysname
            , [StatisticsId] int, [StatisticsName] sysname, [PartitionNumber] int
            , [Rows] bigint, [RowsSampled] bigint, [ModificationCounter] bigint
            , [ModificationPercent] decimal(19,4)
        );

        INSERT [#StatisticsDistributionAnalysis_DistributionDatabaseStatus]
        (
              [DatabaseName],[StatusCode],[IsPartial],[CandidateCount],[HistogramVisibleCount]
            , [RequiredPermission],[ErrorNumber],[ErrorMessage],[Detail]
        )
        SELECT [DatabaseName],[StatusCode],[IsPartial],0,0,[RequiredPermission],[ErrorNumber],[ErrorMessage],[Detail]
        FROM OPENJSON(COALESCE(@StatisticsJson,N'{}'),'$.databaseStatus') WITH
        (
              [DatabaseName] sysname, [StatusCode] varchar(40), [IsPartial] bit
            , [RequiredPermission] nvarchar(256), [ErrorNumber] int
            , [ErrorMessage] nvarchar(2048), [Detail] nvarchar(2000)
        );
    END TRY
    BEGIN CATCH
        SELECT @StatusCode=CASE WHEN ERROR_NUMBER() IN (229,262,297,300,371,916) THEN 'DENIED_PERMISSION'
                                WHEN ERROR_NUMBER()=1222 THEN 'TIMEOUT' ELSE 'ERROR_HANDLED' END,
               @IsPartial=1,@ErrorNumber=ERROR_NUMBER(),@ErrorMessage=ERROR_MESSAGE();
    END CATCH;

    IF @StatusCode IN ('AVAILABLE','AVAILABLE_LIMITED','PARTIAL','AVAILABLE_WITH_FINDING')
    BEGIN
        ;WITH [ranked] AS
        (
            SELECT [RankOrdinal]=ROW_NUMBER() OVER
                   (
                       PARTITION BY [DatabaseName]
                       ORDER BY CASE WHEN [IsIncremental]=1 THEN 0 WHEN [IsFiltered]=1 THEN 1 ELSE 2 END,
                                COALESCE([Rows],0) DESC,COALESCE([ModificationPercent],0) DESC,
                                [SchemaName],[ObjectName],[StatisticsName]
                   ),[DatabaseName],[ObjectId],[StatisticsId]
            FROM [#StatisticsDistributionAnalysis_Candidates]
        )
        UPDATE [c]
        SET [CandidateOrdinal]=[r].[RankOrdinal]
        FROM [#StatisticsDistributionAnalysis_Candidates] [c]
        JOIN [ranked] [r]
          ON [r].[DatabaseName]=[c].[DatabaseName] AND [r].[ObjectId]=[c].[ObjectId]
         AND [r].[StatisticsId]=[c].[StatisticsId];

        DELETE FROM [#StatisticsDistributionAnalysis_Candidates] WHERE [CandidateOrdinal]>@MaxVerteilungsStatistiken;
        DELETE [i]
        FROM [#StatisticsDistributionAnalysis_Incremental] [i]
        WHERE NOT EXISTS
        (
            SELECT 1 FROM [#StatisticsDistributionAnalysis_Candidates] [c]
            WHERE [c].[DatabaseName]=[i].[DatabaseName]
              AND [c].[StatisticsId]=[i].[StatisticsId]
              AND [c].[SchemaName]=[i].[SchemaName]
              AND [c].[ObjectName]=[i].[ObjectName]
        );

        UPDATE [d]
        SET [CandidateCount]=(SELECT COUNT_BIG(*) FROM [#StatisticsDistributionAnalysis_Candidates] [c] WHERE [c].[DatabaseName]=[d].[DatabaseName])
        FROM [#StatisticsDistributionAnalysis_DistributionDatabaseStatus] [d];

        DECLARE @DbName sysname,@Sql nvarchar(max);
        DECLARE dbcur CURSOR LOCAL FAST_FORWARD FOR
            SELECT DISTINCT [DatabaseName] FROM [#StatisticsDistributionAnalysis_Candidates] ORDER BY [DatabaseName];
        OPEN dbcur; FETCH NEXT FROM dbcur INTO @DbName;
        WHILE @@FETCH_STATUS=0
        BEGIN
            BEGIN TRY
                SET @Sql=N'SET LOCK_TIMEOUT '+CONVERT(nvarchar(11),@LockTimeoutMs)+N'; USE '+QUOTENAME(@DbName)+N';
INSERT [#StatisticsDistributionAnalysis_Distribution]
(
      [DatabaseName],[SchemaName],[ObjectName],[ObjectId],[StatisticsId],[StatisticsName],[CandidateOrdinal]
    , [LeadingColumnName],[LeadingTypeName],[Rows],[RowsSampled],[SamplePercent]
    , [ModificationCounter],[ModificationPercent],[DaysSinceLastUpdate]
    , [IsFiltered],[IsIncremental],[HasPersistedSample],[PersistedSamplePercent]
    , [HistogramSteps],[HistogramEstimatedRows],[MaxEqualRows],[MaxRangeRows],[MaxStepRows]
    , [DominantStepPercent],[EqualRowsSkewRatio],[AverageRangeRowsSkewRatio]
    , [TailStepRows],[TailStepPercent],[TailVsAverageStepRatio],[AnalysisState],[EvidenceLimit]
)
SELECT [c].[DatabaseName],[c].[SchemaName],[c].[ObjectName],[c].[ObjectId],[c].[StatisticsId],[c].[StatisticsName],[c].[CandidateOrdinal]
     , [lead].[LeadingColumnName],[lead].[LeadingTypeName],[c].[Rows],[c].[RowsSampled],[c].[SamplePercent]
     , [c].[ModificationCounter],[c].[ModificationPercent],[c].[DaysSinceLastUpdate]
     , [c].[IsFiltered],[c].[IsIncremental],[c].[HasPersistedSample],[c].[PersistedSamplePercent]
     , COALESCE([h].[HistogramSteps],0),[h].[HistogramEstimatedRows],[h].[MaxEqualRows],[h].[MaxRangeRows],[h].[MaxStepRows]
     , CONVERT(decimal(19,4),CONVERT(float,[h].[MaxStepRows])*100.0/NULLIF(CONVERT(float,[h].[HistogramEstimatedRows]),0))
     , CONVERT(decimal(19,4),CONVERT(float,[h].[MaxEqualRows])/NULLIF(CONVERT(float,[h].[AveragePositiveEqualRows]),0))
     , CONVERT(decimal(19,4),CONVERT(float,[h].[MaxAverageRangeRows])/NULLIF(CONVERT(float,[h].[AveragePositiveRangeRows]),0))
     , [tail].[TailStepRows]
     , CONVERT(decimal(19,4),CONVERT(float,[tail].[TailStepRows])*100.0/NULLIF(CONVERT(float,[h].[HistogramEstimatedRows]),0))
     , CONVERT(decimal(19,4),CONVERT(float,[tail].[TailStepRows])/
           NULLIF(CONVERT(float,[h].[HistogramEstimatedRows])/NULLIF(CONVERT(float,[h].[HistogramSteps]),0),0))
     , CASE WHEN COALESCE([h].[HistogramSteps],0)=0 THEN ''HISTOGRAM_NOT_VISIBLE''
            WHEN COALESCE([h].[HistogramEstimatedRows],0)<@pMinRows THEN ''SMALL_HISTOGRAM_CONTEXT''
            ELSE ''EVIDENCE_AVAILABLE'' END
     , N''Histogrammkennzahlen betreffen nur die erste Statistikspalte und den letzten materialisierten Statistikstand; sie enthalten keinen Query-/Prädikatkontext.''
FROM [#StatisticsDistributionAnalysis_Candidates] [c]
OUTER APPLY
(
    SELECT TOP (1) [col].[name] [LeadingColumnName],[typ].[name] [LeadingTypeName]
    FROM [sys].[stats_columns] [sc] WITH (NOLOCK)
    JOIN [sys].[columns] [col] WITH (NOLOCK)
      ON [col].[object_id]=[sc].[object_id] AND [col].[column_id]=[sc].[column_id]
    JOIN [sys].[types] [typ] WITH (NOLOCK) ON [typ].[user_type_id]=[col].[user_type_id]
    WHERE [sc].[object_id]=[c].[ObjectId] AND [sc].[stats_id]=[c].[StatisticsId]
    ORDER BY [sc].[stats_column_id]
) [lead]
OUTER APPLY
(
    SELECT COUNT(*) [HistogramSteps]
         , SUM(CONVERT(decimal(38,4),COALESCE([x].[equal_rows],0))+CONVERT(decimal(38,4),COALESCE([x].[range_rows],0))) [HistogramEstimatedRows]
         , MAX(CONVERT(decimal(38,4),[x].[equal_rows])) [MaxEqualRows]
         , MAX(CONVERT(decimal(38,4),[x].[range_rows])) [MaxRangeRows]
         , MAX(CONVERT(decimal(38,4),COALESCE([x].[equal_rows],0))+CONVERT(decimal(38,4),COALESCE([x].[range_rows],0))) [MaxStepRows]
         , AVG(NULLIF(CONVERT(decimal(38,4),[x].[equal_rows]),0)) [AveragePositiveEqualRows]
         , MAX(CONVERT(decimal(38,4),[x].[average_range_rows])) [MaxAverageRangeRows]
         , AVG(NULLIF(CONVERT(decimal(38,4),[x].[average_range_rows]),0)) [AveragePositiveRangeRows]
    FROM [sys].[dm_db_stats_histogram]([c].[ObjectId],[c].[StatisticsId]) [x]
) [h]
OUTER APPLY
(
    SELECT TOP (1)
           CONVERT(decimal(38,4),COALESCE([x].[equal_rows],0))+CONVERT(decimal(38,4),COALESCE([x].[range_rows],0)) [TailStepRows]
    FROM [sys].[dm_db_stats_histogram]([c].[ObjectId],[c].[StatisticsId]) [x]
    ORDER BY [x].[step_number] DESC
) [tail]
WHERE [c].[DatabaseName]=@pDbName;';

                EXEC [sys].[sp_executesql] @Sql,N'@pDbName sysname,@pMinRows bigint',
                     @pDbName=@DbName,@pMinRows=@MinVerteilungsZeilen;
            END TRY
            BEGIN CATCH
                UPDATE [#StatisticsDistributionAnalysis_DistributionDatabaseStatus]
                SET [StatusCode]=CASE WHEN ERROR_NUMBER() IN (229,262,297,300,371,916) THEN 'DENIED_PERMISSION'
                                      WHEN ERROR_NUMBER()=1222 THEN 'TIMEOUT'
                                      WHEN ERROR_NUMBER() IN (207,208,4121) THEN 'UNAVAILABLE_OBJECT'
                                      ELSE 'ERROR_HANDLED' END,
                    [IsPartial]=1,[ErrorNumber]=ERROR_NUMBER(),[ErrorMessage]=ERROR_MESSAGE(),
                    [Detail]=N'Histogrammzugriff fehlgeschlagen; andere Datenbanken und Basisstatistiken bleiben erhalten.'
                WHERE [DatabaseName]=@DbName;
            END CATCH;
            FETCH NEXT FROM dbcur INTO @DbName;
        END;
        CLOSE dbcur; DEALLOCATE dbcur;

        UPDATE [d]
        SET [HistogramVisibleCount]=
            (SELECT COUNT_BIG(*) FROM [#StatisticsDistributionAnalysis_Distribution] [x]
             WHERE [x].[DatabaseName]=[d].[DatabaseName] AND [x].[HistogramSteps]>0)
        FROM [#StatisticsDistributionAnalysis_DistributionDatabaseStatus] [d];

        UPDATE [#StatisticsDistributionAnalysis_DistributionDatabaseStatus]
        SET [StatusCode]='NOT_APPLICABLE',[Detail]=N'Keine sichtbare Statistik im begrenzten Kandidatenpool.'
        WHERE [CandidateCount]=0 AND [StatusCode]='AVAILABLE';

        UPDATE [#StatisticsDistributionAnalysis_DistributionDatabaseStatus]
        SET [StatusCode]='AVAILABLE_LIMITED',[IsPartial]=1,
            [Detail]=N'Kandidaten waren sichtbar, aber kein Histogramm war sichtbar; Metadatenberechtigung und Materialisierung prüfen.'
        WHERE [CandidateCount]>0 AND [HistogramVisibleCount]=0 AND [StatusCode]='AVAILABLE';

        INSERT [#StatisticsDistributionAnalysis_PartitionVariation]
        SELECT [i].[DatabaseName],[i].[SchemaName],[i].[ObjectName],[i].[StatisticsId],[i].[StatisticsName]
             , COUNT(*) [PartitionCount]
             , SUM(CASE WHEN COALESCE([i].[Rows],0)>0 THEN 1 ELSE 0 END) [PartitionsWithRows]
             , SUM([i].[Rows]) [TotalRows],SUM([i].[ModificationCounter]) [TotalModificationCounter]
             , CONVERT(decimal(19,4),CONVERT(float,SUM([i].[ModificationCounter]))*100.0/
                       NULLIF(CONVERT(float,SUM([i].[Rows])),0)) [WeightedModificationPercent]
             , MIN([i].[ModificationPercent]),MAX([i].[ModificationPercent])
             , CONVERT(decimal(19,4),MAX([i].[ModificationPercent])-MIN([i].[ModificationPercent]))
        FROM [#StatisticsDistributionAnalysis_Incremental] [i]
        GROUP BY [i].[DatabaseName],[i].[SchemaName],[i].[ObjectName],[i].[StatisticsId],[i].[StatisticsName];

        INSERT [#StatisticsDistributionAnalysis_Findings]
        ([DatabaseName],[SchemaName],[ObjectName],[StatisticsName],[Severity],[Confidence],[FindingCode],[MetricName],[MetricValue],[ThresholdValue],[Evidence],[EvidenceLimit],[RecommendedNextCheck])
        SELECT [DatabaseName],[SchemaName],[ObjectName],[StatisticsName],'LOW','LOW','HISTOGRAM_NOT_VISIBLE','HistogramSteps',0,NULL,
               N'Für den begrenzten Kandidaten war kein sichtbarer Histogrammschritt verfügbar.',[EvidenceLimit],
               N'Metadatensichtbarkeit, Statistikmaterialisierung und den gezielten Scope prüfen.'
        FROM [#StatisticsDistributionAnalysis_Distribution] WHERE [HistogramSteps]=0
        UNION ALL
        SELECT [DatabaseName],[SchemaName],[ObjectName],[StatisticsName],'MEDIUM','MEDIUM','DOMINANT_HISTOGRAM_STEP_REVIEW','DominantStepPercent',[DominantStepPercent],@DominanterSchrittWarnPercent,
               CONCAT(N'Der größte Histogrammschritt umfasst ',[DominantStepPercent],N' Prozent der sichtbaren Histogrammzeilen.'),[EvidenceLimit],
               N'Mit tatsächlicher Prädikatselektivität, Kardinalitätsabweichung und Planvarianten korrelieren.'
        FROM [#StatisticsDistributionAnalysis_Distribution]
        WHERE [HistogramEstimatedRows]>=@MinVerteilungsZeilen AND [DominantStepPercent]>=@DominanterSchrittWarnPercent
        UNION ALL
        SELECT [DatabaseName],[SchemaName],[ObjectName],[StatisticsName],'MEDIUM','MEDIUM','EQUALITY_FREQUENCY_SKEW_REVIEW','EqualRowsSkewRatio',[EqualRowsSkewRatio],@SkewWarnFaktor,
               CONCAT(N'Maximale Gleichheitsfrequenz zu durchschnittlicher positiver Gleichheitsfrequenz: Faktor ',[EqualRowsSkewRatio],N'.'),[EvidenceLimit],
               N'Abfrageprädikate, Parameterwerte und geschätzte gegen tatsächliche Zeilen prüfen.'
        FROM [#StatisticsDistributionAnalysis_Distribution]
        WHERE [HistogramEstimatedRows]>=@MinVerteilungsZeilen AND [EqualRowsSkewRatio]>=@SkewWarnFaktor
        UNION ALL
        SELECT [DatabaseName],[SchemaName],[ObjectName],[StatisticsName],'MEDIUM','MEDIUM','RANGE_DENSITY_SKEW_REVIEW','AverageRangeRowsSkewRatio',[AverageRangeRowsSkewRatio],@SkewWarnFaktor,
               CONCAT(N'Maximale zu durchschnittlicher positiver Range-Dichte: Faktor ',[AverageRangeRowsSkewRatio],N'.'),[EvidenceLimit],
               N'Range-Prädikate und tatsächliche Kardinalitäten für diese führende Statistikspalte prüfen.'
        FROM [#StatisticsDistributionAnalysis_Distribution]
        WHERE [HistogramEstimatedRows]>=@MinVerteilungsZeilen AND [AverageRangeRowsSkewRatio]>=@SkewWarnFaktor
        UNION ALL
        SELECT [DatabaseName],[SchemaName],[ObjectName],[StatisticsName],'MEDIUM','LOW','TAIL_CONCENTRATION_REVIEW','TailVsAverageStepRatio',[TailVsAverageStepRatio],@SkewWarnFaktor,
               CONCAT(N'Letzter Histogrammschritt zu durchschnittlichem Schritt: Faktor ',[TailVsAverageStepRatio],N'; Tail-Anteil ',[TailStepPercent],N' Prozent.'),[EvidenceLimit],
               N'Zeitbezug, Insert-Muster und Querywerte prüfen; Tail-Konzentration beweist keine Ascending-Key-Problematik.'
        FROM [#StatisticsDistributionAnalysis_Distribution]
        WHERE [HistogramEstimatedRows]>=@MinVerteilungsZeilen AND [TailVsAverageStepRatio]>=@SkewWarnFaktor
        UNION ALL
        SELECT [DatabaseName],[SchemaName],[ObjectName],[StatisticsName],'MEDIUM','LOW','OUT_OF_RANGE_NOT_MEASURABLE_REVIEW','ModificationPercent',[ModificationPercent],@ModificationWarnPercent,
               CONCAT(N'Seit dem Statistikstand wurden ',[ModificationPercent],N' Prozent relativ zur sichtbaren Statistikzeilenzahl geändert.'),[EvidenceLimit],
               N'Neue Werte, Queryliterale und tatsächliche Kardinalitäten kontrolliert prüfen; der Modification Counter enthält keine Wertverteilung.'
        FROM [#StatisticsDistributionAnalysis_Distribution]
        WHERE [HistogramSteps]>0 AND [Rows]>=@MinVerteilungsZeilen AND [ModificationPercent]>=@ModificationWarnPercent;

        INSERT [#StatisticsDistributionAnalysis_Findings]
        ([DatabaseName],[SchemaName],[ObjectName],[StatisticsName],[Severity],[Confidence],[FindingCode],[MetricName],[MetricValue],[ThresholdValue],[Evidence],[EvidenceLimit],[RecommendedNextCheck])
        SELECT [DatabaseName],[SchemaName],[ObjectName],[StatisticsName],'MEDIUM','MEDIUM','PARTITION_MODIFICATION_SKEW_REVIEW','ModificationSpreadPercentPoints',[ModificationSpreadPercentPoints],@PartitionSpreadWarnPercent,
               CONCAT(N'Änderungsanteile inkrementeller Statistikpartitionen streuen um ',[ModificationSpreadPercentPoints],N' Prozentpunkte; gewichteter Anteil ',[WeightedModificationPercent],N' Prozent.'),
               N'Partitionswerte stammen aus dem aktuellen inkrementellen Statistikstatus; Retention, Partitionswechsel und Statistikupdates beeinflussen die Evidenz.',
               N'Betroffene Partitionen, Ladefenster und den beabsichtigten inkrementellen Statistikpflegepfad prüfen.'
        FROM [#StatisticsDistributionAnalysis_PartitionVariation]
        WHERE [TotalRows]>=@MinVerteilungsZeilen AND [ModificationSpreadPercentPoints]>=@PartitionSpreadWarnPercent;

        IF EXISTS(SELECT 1 FROM [#StatisticsDistributionAnalysis_DistributionDatabaseStatus]
                  WHERE [StatusCode] NOT IN ('AVAILABLE','NOT_APPLICABLE'))
        BEGIN
            SET @IsPartial=1;
            IF EXISTS(SELECT 1 FROM [#StatisticsDistributionAnalysis_Distribution]) SET @StatusCode='AVAILABLE_LIMITED';
            ELSE SELECT TOP (1) @StatusCode=[StatusCode],@ErrorNumber=[ErrorNumber],@ErrorMessage=[ErrorMessage]
                 FROM [#StatisticsDistributionAnalysis_DistributionDatabaseStatus] WHERE [StatusCode] NOT IN ('AVAILABLE','NOT_APPLICABLE') ORDER BY [DatabaseName];
        END
        ELSE IF EXISTS(SELECT 1 FROM [#StatisticsDistributionAnalysis_Findings])
            SET @StatusCode='AVAILABLE_WITH_FINDING';
        ELSE IF NOT EXISTS(SELECT 1 FROM [#StatisticsDistributionAnalysis_Distribution])
            SET @StatusCode='NOT_APPLICABLE';
        ELSE
            SET @StatusCode='AVAILABLE';
    END;

    IF NOT EXISTS(SELECT 1 FROM [#StatisticsDistributionAnalysis_DistributionDatabaseStatus])
       AND @StatusCode<>'AVAILABLE'
        INSERT [#StatisticsDistributionAnalysis_DistributionDatabaseStatus]
        VALUES(NULL,@StatusCode,1,0,0,N'CATALOG_DEEP und Statistik-Metadatensichtbarkeit',@ErrorNumber,@ErrorMessage,N'Keine Verteilungsanalyse ausgeführt.');

    SELECT @StatusCodeOut=@StatusCode,@IsPartialOut=@IsPartial,
           @ErrorNumberOut=@ErrorNumber,@ErrorMessageOut=@ErrorMessage;

    IF @PrintMeldungen=1 AND @StatusCode NOT IN ('AVAILABLE','AVAILABLE_WITH_FINDING','NOT_APPLICABLE')
    BEGIN
        SET @PrintMessage=FORMATMESSAGE(N'WARNUNG USP_StatisticsDistributionAnalysis %s: %s',@StatusCode,COALESCE(@ErrorMessage,N'Teilergebnis oder Evidenzlücke.'));
        RAISERROR(N'%s',10,1,@PrintMessage) WITH NOWAIT;
    END;

    IF @JsonErzeugen=1
    BEGIN
        DECLARE @MetaJson nvarchar(max)=
            (SELECT N'StatisticsDistributionAnalysis' [resultName],1 [schemaVersion],@Now [generatedAtUtc],
                    @StatusCode [statusCode],@IsPartial [isPartial],@MaxVerteilungsStatistiken [maxStatisticsPerDatabase],
                    @MinVerteilungsZeilen [minimumDistributionRows],
                    (SELECT COUNT_BIG(*) FROM [#StatisticsDistributionAnalysis_Distribution]) [distributionCount],
                    (SELECT COUNT_BIG(*) FROM [#StatisticsDistributionAnalysis_Findings]) [findingCount]
             FOR JSON PATH,WITHOUT_ARRAY_WRAPPER,INCLUDE_NULL_VALUES);
        DECLARE @DatabaseJson nvarchar(max)=(SELECT * FROM [#StatisticsDistributionAnalysis_DistributionDatabaseStatus] ORDER BY [DatabaseName] FOR JSON PATH,INCLUDE_NULL_VALUES);
        DECLARE @DistributionJson nvarchar(max)=(SELECT TOP (@Limit) * FROM [#StatisticsDistributionAnalysis_Distribution] ORDER BY [DatabaseName],[CandidateOrdinal] FOR JSON PATH,INCLUDE_NULL_VALUES);
        DECLARE @PartitionJson nvarchar(max)=(SELECT TOP (@Limit) * FROM [#StatisticsDistributionAnalysis_PartitionVariation] ORDER BY [ModificationSpreadPercentPoints] DESC,[DatabaseName],[SchemaName],[ObjectName],[StatisticsName] FOR JSON PATH,INCLUDE_NULL_VALUES);
        DECLARE @FindingsJson nvarchar(max)=(SELECT TOP (@Limit) * FROM [#StatisticsDistributionAnalysis_Findings] ORDER BY CASE [Severity] WHEN 'HIGH' THEN 1 WHEN 'MEDIUM' THEN 2 WHEN 'LOW' THEN 3 ELSE 4 END,[FindingOrdinal] FOR JSON PATH,INCLUDE_NULL_VALUES);
        SET @Json=CONCAT(N'{"meta":',COALESCE(@MetaJson,N'{}'),N',"databaseStatus":',COALESCE(@DatabaseJson,N'[]'),
                         N',"distribution":',COALESCE(@DistributionJson,N'[]'),N',"partitionVariation":',COALESCE(@PartitionJson,N'[]'),
                         N',"findings":',COALESCE(@FindingsJson,N'[]'),N'}');
    END;

    IF @OutputMode='RAW'
    BEGIN
        SELECT N'USP_StatisticsDistributionAnalysis' [ModuleName],@Now [CollectionTimeUtc],@StatusCode [StatusCode],@IsPartial [IsPartial],
               (SELECT COUNT_BIG(*) FROM [#StatisticsDistributionAnalysis_Distribution]) [DistributionCount],(SELECT COUNT_BIG(*) FROM [#StatisticsDistributionAnalysis_Findings]) [FindingCount],
               @ErrorNumber [ErrorNumber],@ErrorMessage [ErrorMessage],
               N'Begrenzte Histogramm- und Partitionsverteilung; Indikatoren sind keine Planursache.' [Detail];
        SELECT * FROM [#StatisticsDistributionAnalysis_DistributionDatabaseStatus] ORDER BY [DatabaseName];
        SELECT TOP (@Limit) * FROM [#StatisticsDistributionAnalysis_Distribution] ORDER BY [DatabaseName],[CandidateOrdinal];
        SELECT TOP (@Limit) * FROM [#StatisticsDistributionAnalysis_PartitionVariation] ORDER BY [ModificationSpreadPercentPoints] DESC,[DatabaseName],[SchemaName],[ObjectName],[StatisticsName];
        SELECT TOP (@Limit) * FROM [#StatisticsDistributionAnalysis_Findings] ORDER BY CASE [Severity] WHEN 'HIGH' THEN 1 WHEN 'MEDIUM' THEN 2 WHEN 'LOW' THEN 3 ELSE 4 END,[FindingOrdinal];
    END
    ELSE IF @OutputMode='CONSOLE'
    BEGIN
        SELECT N'Statistikverteilung' [Ergebnis],@Now [Stand_UTC],@StatusCode [Status],@IsPartial [Teilergebnis],
               (SELECT COUNT_BIG(*) FROM [#StatisticsDistributionAnalysis_Distribution]) [Analysierte_Statistiken],(SELECT COUNT_BIG(*) FROM [#StatisticsDistributionAnalysis_Findings]) [Befunde],@ErrorMessage [Hinweis];
        SELECT N'Datenbankstatus Statistikverteilung' [Ergebnis],[DatabaseName] [Datenbank],[StatusCode] [Status],[CandidateCount] [Kandidaten],
               [HistogramVisibleCount] [Histogramme_sichtbar],[IsPartial] [Teilweise],[Detail] [Hinweis]
        FROM [#StatisticsDistributionAnalysis_DistributionDatabaseStatus] ORDER BY [DatabaseName];
        SELECT TOP (@Limit) N'Histogrammverteilung' [Ergebnis],[d].* FROM [#StatisticsDistributionAnalysis_Distribution] [d] ORDER BY [DatabaseName],[CandidateOrdinal];
        SELECT TOP (@Limit) N'Inkrementelle Partitionsvariation' [Ergebnis],[p].* FROM [#StatisticsDistributionAnalysis_PartitionVariation] [p]
        ORDER BY [ModificationSpreadPercentPoints] DESC,[DatabaseName],[SchemaName],[ObjectName],[StatisticsName];
        SELECT TOP (@Limit) N'Statistikverteilungsbefund' [Ergebnis],[f].* FROM [#StatisticsDistributionAnalysis_Findings] [f]
        ORDER BY CASE [Severity] WHEN 'HIGH' THEN 1 WHEN 'MEDIUM' THEN 2 WHEN 'LOW' THEN 3 ELSE 4 END,[FindingOrdinal];
    END;
    IF @ConsoleResultRequested = 1
    BEGIN
        EXEC [monitor].[InternalEmitConsoleResult]
              @SourceTable=N'#StatisticsDistributionAnalysis_Findings'
            , @ResultLabel=N'StatisticsDistributionAnalysis'
            , @EmptyMessage=N'Keine fachlichen Ergebnisse';
    END;
    IF @TableResultRequested = 1
    BEGIN
        EXEC [monitor].[InternalWriteResultTable]
              @SourceTable = N'#StatisticsDistributionAnalysis_Findings'
            , @TargetTable=@TableTarget
            , @ThrowOnError = 1;
    END;
END;
GO
-- END SOURCE: Code/03_ObjectIndex/045_USP_StatisticsDistributionAnalysis.sql

-- BEGIN SOURCE: Code/03_ObjectIndex/050_USP_Partitions.sql
/*
===============================================================================
Objekt       : monitor.USP_Partitions
Version      : 1.0.0
Stand        : 2026-07-14
Typ          : Stored Procedure
Zweck        : Liefert Partitionierung, Grenzwerte, Filegroups, Zeilen, Größe und Datenkompression; ungezielte Vollanalyse ist gruppengeschützt.
SQL-Version  : SQL Server 2019 oder neuer.
Datenquellen : Je Datenbank sys.objects, sys.schemas, sys.indexes, sys.partitions, sys.allocation_units, sys.data_spaces, sys.partition_schemes, sys.partition_functions und sys.partition_range_values.
Parameter    :
  @DatabaseName                  sysname        = NULL  - Zieldatenbank; bei Einzelmodus Pflicht.
  @CrossDatabaseRequestedInternal               bit            = 0     - sichtbare Online-Datenbanken analysieren.
  @SystemdatenbankenEinbeziehen  bit            = 0     - master/model/msdb/tempdb einbeziehen.
  @DatenbankNameLike             nvarchar(256)  = NULL  - Filter im Cross-Database-Modus.
  @SchemaNamePattern                nvarchar(256)  = NULL  - LIKE-Filter auf Schema.
  @ObjectNamePattern                nvarchar(256)  = NULL  - LIKE-Filter auf Objekt.
  @MaxZeilen                     int            = 5000  - positive Werte begrenzen; NULL/0 = unbegrenzt.
  @LockTimeoutMs                 int            = 0     - 0 = nicht auf Metadatenlocks warten.
  @PrintMeldungen                bit            = 1     - Warnungen via RAISERROR 10.
  @Hilfe                         bit            = 0     - Hilfe via PRINT, keine Analyse.
  @AnalyseModus varchar(16)='GEZIELT' - GEZIELT|VOLL; VOLL benötigt CATALOG_DEEP.
  @NurPartitionierte bit=0 - nur Objekte mit mehr als einer Partition.
  @NurGemischteKompression bit=0 - nur Indizes mit mehreren Kompressionsarten.
Resultsets   : 1. Modulstatus. 2. Status je Datenbank. 3. Partitionen und Kompression.
Berechtigung : Metadata Visibility; sys.dm_db_partition_stats wird nicht benötigt.
Eigenlast    : Katalog- und Allocation-Unit-Aggregation; VOLL ist gruppengeschützt und begrenzt.
Locking      : READUNCOMMITTED-Systemkataloge und LOCK_TIMEOUT.
Partial      : Fehler je Datenbank bzw. Teilquelle werden isoliert; vorhandene
               Teilergebnisse bleiben erhalten. Das Framework vergibt keine Rechte.
Beispiele    :
  EXEC monitor.USP_Partitions @DatabaseNames=N'SampleDatabase', @ObjectNamePattern=N'FactSales';
  EXEC monitor.USP_Partitions @DatabaseNames=N'SampleDatabase', @AnalyseModus='VOLL', @NurPartitionierte=1;
  EXEC monitor.USP_Partitions @Hilfe=1;
Änderungen   : 1.0.0 - Erstfassung Phase 2.
===============================================================================
*/
CREATE OR ALTER PROCEDURE [monitor].[USP_Partitions]
      @DatabaseNames                  nvarchar(max)  = NULL
    , @SystemdatenbankenEinbeziehen   bit            = 0
    , @DatabaseNamePattern            nvarchar(4000) = NULL
    , @HighImpactConfirmed              bit            = 0
    , @SchemaNames                    nvarchar(max)  = NULL
    , @SchemaNamePattern              nvarchar(4000) = NULL
    , @ObjectNames                    nvarchar(max)  = NULL
    , @ObjectNamePattern              nvarchar(4000) = NULL
    , @FullObjectNames                nvarchar(max)  = NULL
    , @AnalyseModus                   varchar(16)   = 'GEZIELT'
    , @NurPartitionierte              bit           = 0
    , @NurGemischteKompression        bit           = 0
    , @MaxZeilen                      int           = 10000
    , @LockTimeoutMs                  int           = 0
    , @ResultSetArt                  varchar(16)    = 'CONSOLE'
    , @ResultTablesJson               nvarchar(max) = NULL
    , @JsonErzeugen                  bit            = 0
    , @Json                          nvarchar(max)  = NULL OUTPUT
    , @PrintMeldungen                 bit           = 1
    , @Hilfe                          bit           = 0
AS
BEGIN
 SET NOCOUNT ON;

    SET @Json = NULL;
    DECLARE @ResultSetArtNormalisiert varchar(16)=UPPER(LTRIM(RTRIM(COALESCE(@ResultSetArt,''))));
    DECLARE @TableResultRequested bit = CASE WHEN @ResultSetArtNormalisiert = 'TABLE' THEN 1 ELSE 0 END;
    DECLARE @ConsoleResultRequested bit = CASE WHEN @ResultSetArtNormalisiert = 'CONSOLE' THEN 1 ELSE 0 END;
    DECLARE @TableTarget sysname=NULL;
    IF @TableResultRequested=0 AND NULLIF(LTRIM(RTRIM(COALESCE(@ResultTablesJson,N''))),N'') IS NOT NULL THROW 51011,N'@ResultTablesJson ist ausschließlich mit @ResultSetArt=TABLE zulässig.',1;
    IF @TableResultRequested=1 EXEC [monitor].[InternalPrepareSingleResultTable] @ResultTablesJson=@ResultTablesJson,@ResultName=N'partitions',@TargetTable=@TableTarget OUTPUT,@ThrowOnError=1;
    IF @TableResultRequested = 1 OR @ConsoleResultRequested = 1 SET @ResultSetArtNormalisiert = 'NONE';
    DECLARE @DatabaseName sysname=NULL,@CrossDatabaseRequestedInternal bit=0,@DatenbankNameLike nvarchar(4000)=NULL;
    DECLARE @SchemaNameLike nvarchar(4000)=NULL,@ObjectNameLike nvarchar(4000)=NULL;
    DECLARE @SchemaPatternMode varchar(8),@SchemaPatternValue nvarchar(4000),@SchemaRegexFlags varchar(8),@SchemaPatternValid bit;
    DECLARE @ObjectPatternMode varchar(8),@ObjectPatternValue nvarchar(4000),@ObjectRegexFlags varchar(8),@ObjectPatternValid bit;
    SELECT @SchemaPatternMode=[PatternMode],@SchemaPatternValue=[PatternValue],@SchemaRegexFlags=[RegexFlags],@SchemaPatternValid=[IsValid] FROM [monitor].[TVF_ParsePattern](@SchemaNamePattern);
    SELECT @ObjectPatternMode=[PatternMode],@ObjectPatternValue=[PatternValue],@ObjectRegexFlags=[RegexFlags],@ObjectPatternValid=[IsValid] FROM [monitor].[TVF_ParsePattern](@ObjectNamePattern);
    IF @SchemaPatternMode='LIKE' SET @SchemaNameLike=@SchemaPatternValue;
    IF @ObjectPatternMode='LIKE' SET @ObjectNameLike=@ObjectPatternValue;
    DECLARE @IndexPatternMode varchar(8)='NONE',@IndexPatternValue nvarchar(4000)=NULL,@IndexRegexFlags varchar(8)=NULL,@IndexPatternValid bit=1;
    DECLARE @StatisticsPatternMode varchar(8)='NONE',@StatisticsPatternValue nvarchar(4000)=NULL,@StatisticsRegexFlags varchar(8)=NULL,@StatisticsPatternValid bit=1;
    DECLARE @DatabaseListCount int=0;
    IF @DatabaseNames IS NOT NULL AND NULLIF(LTRIM(RTRIM(@DatabaseNames)),N'') IS NOT NULL
        SELECT @DatabaseListCount=COUNT(*),@DatabaseName=MIN([NameValue]) FROM [monitor].[TVF_ParseSqlNameList](@DatabaseNames) WHERE [IsValid]=1;
    SET @CrossDatabaseRequestedInternal=CONVERT(bit,CASE WHEN @DatabaseNames IS NULL OR @DatabaseNamePattern IS NOT NULL OR @DatabaseListCount>1 THEN 1 ELSE 0 END);
    SELECT @DatenbankNameLike=CASE WHEN [PatternMode]='LIKE' THEN [PatternValue] END FROM [monitor].[TVF_ParsePattern](@DatabaseNamePattern);
    CREATE TABLE [#Partitions_NameFilters]([FilterType] varchar(20) COLLATE SQL_Latin1_General_CP1_CS_AS NOT NULL,[ItemOrdinal] int NOT NULL,[NameValue] sysname COLLATE SQL_Latin1_General_CP1_CS_AS NULL,[DatabaseName] sysname COLLATE SQL_Latin1_General_CP1_CS_AS NULL,[SchemaName] sysname COLLATE SQL_Latin1_General_CP1_CS_AS NULL,[ObjectName] sysname COLLATE SQL_Latin1_General_CP1_CS_AS NULL);
    CREATE TABLE [#Partitions_DatabaseCandidates]([DatabaseId] int NOT NULL,[DatabaseName] sysname NOT NULL,[StateDesc] nvarchar(60),[UserAccessDesc] nvarchar(60),[IsReadOnly] bit,[CompatibilityLevel] tinyint,[CollationName] sysname,[RecoveryModelDesc] nvarchar(60),[IsSystemDatabase] bit,[RequestedOrdinal] int);
    DECLARE @FilterStatus varchar(40)='AVAILABLE',@FilterError nvarchar(2048)=NULL,@CrossDatabaseRequested bit=0;
    EXEC [monitor].[USP_PrepareNameFilters] @SchemaNames=@SchemaNames,@ObjectNames=@ObjectNames,@FullObjectNames=@FullObjectNames,@IndexNames=NULL,@StatisticsNames=NULL,@ColumnNames=NULL,@StatusCode=@FilterStatus OUTPUT,@ErrorMessage=@FilterError OUTPUT,@FilterTable=N'#Partitions_NameFilters';
    IF @FilterStatus='AVAILABLE' EXEC [monitor].[USP_PrepareDatabaseCandidates] @DatabaseNames=@DatabaseNames,@SystemdatenbankenEinbeziehen=@SystemdatenbankenEinbeziehen,@DatabaseNamePattern=@DatabaseNamePattern,@HighImpactConfirmed=@HighImpactConfirmed,@AnalysisClass='OBJECT_ANALYSIS_CURRENT',@StatusCode=@FilterStatus OUTPUT,@ErrorMessage=@FilterError OUTPUT,@CrossDatabaseRequested=@CrossDatabaseRequested OUTPUT,@CandidateTable=N'#Partitions_DatabaseCandidates';
    IF @FilterStatus='AVAILABLE' AND UPPER(LTRIM(RTRIM(COALESCE(@AnalyseModus,''))))='VOLL'
        EXEC [monitor].[InternalCheckAnalysisPath] @AnalysisClass='CATALOG_DEEP',@HighImpactConfirmed=@HighImpactConfirmed,@StatusCode=@FilterStatus OUTPUT,@ErrorMessage=@FilterError OUTPUT;
    DECLARE @SchemaPredicateS nvarchar(max),@SchemaPredicateSch nvarchar(max),@ObjectPredicateO nvarchar(max),@FullObjectPredicateSO nvarchar(max),@IndexPredicateI nvarchar(max),@StatisticsPredicateSt nvarchar(max);
    SET @SchemaPredicateS=N' AND (NOT EXISTS(SELECT 1 FROM [#Partitions_NameFilters] WHERE [FilterType]=''SCHEMA'') OR EXISTS(SELECT 1 FROM [#Partitions_NameFilters] [f] WHERE [f].[FilterType]=''SCHEMA'' AND [f].[NameValue]=[s].[name] COLLATE SQL_Latin1_General_CP1_CS_AS))';
    SET @SchemaPredicateSch=REPLACE(@SchemaPredicateS,N'[s].[name]',N'[sch].[name]');
    SET @ObjectPredicateO=N' AND (NOT EXISTS(SELECT 1 FROM [#Partitions_NameFilters] WHERE [FilterType]=''OBJECT'') OR EXISTS(SELECT 1 FROM [#Partitions_NameFilters] [f] WHERE [f].[FilterType]=''OBJECT'' AND [f].[NameValue]=[o].[name] COLLATE SQL_Latin1_General_CP1_CS_AS))';
    SET @FullObjectPredicateSO=N' AND (NOT EXISTS(SELECT 1 FROM [#Partitions_NameFilters] WHERE [FilterType]=''FULL_OBJECT'') OR EXISTS(SELECT 1 FROM [#Partitions_NameFilters] [f] WHERE [f].[FilterType]=''FULL_OBJECT'' AND ([f].[DatabaseName] IS NULL OR [f].[DatabaseName]=@pDbName COLLATE SQL_Latin1_General_CP1_CS_AS) AND ([f].[SchemaName] IS NULL OR [f].[SchemaName]=[s].[name] COLLATE SQL_Latin1_General_CP1_CS_AS) AND [f].[ObjectName]=[o].[name] COLLATE SQL_Latin1_General_CP1_CS_AS))';
    SET @IndexPredicateI=N' AND (NOT EXISTS(SELECT 1 FROM [#Partitions_NameFilters] WHERE [FilterType]=''INDEX'') OR EXISTS(SELECT 1 FROM [#Partitions_NameFilters] [f] WHERE [f].[FilterType]=''INDEX'' AND [f].[NameValue]=[i].[name] COLLATE SQL_Latin1_General_CP1_CS_AS))';
    SET @StatisticsPredicateSt=N' AND (NOT EXISTS(SELECT 1 FROM [#Partitions_NameFilters] WHERE [FilterType]=''STATISTICS'') OR EXISTS(SELECT 1 FROM [#Partitions_NameFilters] [f] WHERE [f].[FilterType]=''STATISTICS'' AND [f].[NameValue]=[st].[name] COLLATE SQL_Latin1_General_CP1_CS_AS))';
    IF @SchemaPatternMode='LIKE' BEGIN SET @SchemaPredicateS+=N' AND [s].[name] COLLATE SQL_Latin1_General_CP1_CS_AS LIKE N'''+REPLACE(@SchemaPatternValue,N'''',N'''''')+N''' COLLATE SQL_Latin1_General_CP1_CS_AS';SET @SchemaPredicateSch+=N' AND [sch].[name] COLLATE SQL_Latin1_General_CP1_CS_AS LIKE N'''+REPLACE(@SchemaPatternValue,N'''',N'''''')+N''' COLLATE SQL_Latin1_General_CP1_CS_AS';END;
    IF @SchemaPatternMode IN('REGEX','REGEXI') BEGIN SET @SchemaPredicateS+=N' AND REGEXP_LIKE([s].[name],N'''+REPLACE(@SchemaPatternValue,N'''',N'''''')+N''','''+@SchemaRegexFlags+N''')';SET @SchemaPredicateSch+=N' AND REGEXP_LIKE([sch].[name],N'''+REPLACE(@SchemaPatternValue,N'''',N'''''')+N''','''+@SchemaRegexFlags+N''')';END;
    IF @ObjectPatternMode='LIKE' SET @ObjectPredicateO+=N' AND [o].[name] COLLATE SQL_Latin1_General_CP1_CS_AS LIKE N'''+REPLACE(@ObjectPatternValue,N'''',N'''''')+N''' COLLATE SQL_Latin1_General_CP1_CS_AS';
    IF @ObjectPatternMode IN('REGEX','REGEXI') SET @ObjectPredicateO+=N' AND REGEXP_LIKE([o].[name],N'''+REPLACE(@ObjectPatternValue,N'''',N'''''')+N''','''+@ObjectRegexFlags+N''')';
    IF @IndexPatternMode='LIKE' SET @IndexPredicateI+=N' AND [i].[name] COLLATE SQL_Latin1_General_CP1_CS_AS LIKE N'''+REPLACE(@IndexPatternValue,N'''',N'''''')+N''' COLLATE SQL_Latin1_General_CP1_CS_AS';
    IF @IndexPatternMode IN('REGEX','REGEXI') SET @IndexPredicateI+=N' AND REGEXP_LIKE([i].[name],N'''+REPLACE(@IndexPatternValue,N'''',N'''''')+N''','''+@IndexRegexFlags+N''')';
    IF @StatisticsPatternMode='LIKE' SET @StatisticsPredicateSt+=N' AND [st].[name] COLLATE SQL_Latin1_General_CP1_CS_AS LIKE N'''+REPLACE(@StatisticsPatternValue,N'''',N'''''')+N''' COLLATE SQL_Latin1_General_CP1_CS_AS';
    IF @StatisticsPatternMode IN('REGEX','REGEXI') SET @StatisticsPredicateSt+=N' AND REGEXP_LIKE([st].[name],N'''+REPLACE(@StatisticsPatternValue,N'''',N'''''')+N''','''+@StatisticsRegexFlags+N''')';
    DECLARE @EffectiveMaxZeilen bigint = CASE WHEN @MaxZeilen IS NULL OR @MaxZeilen=0 THEN CONVERT(bigint,9223372036854775807) ELSE CONVERT(bigint,@MaxZeilen) END;
    DECLARE @MonitorPrintMessage nvarchar(2048); SET @AnalyseModus=UPPER(LTRIM(RTRIM(COALESCE(@AnalyseModus,'GEZIELT'))));
 IF @Hilfe=1
 BEGIN
        PRINT N'monitor.USP_Partitions';        PRINT N'@DatabaseNames: exakter Name oder bracket-aware Pipe-Liste; NULL = alle zulässigen Datenbanken; N'''' = keine Einschränkung.';        PRINT N'@SystemdatenbankenEinbeziehen bit = 0: Systemdatenbanken einbeziehen.';        PRINT N'Exakte Listen und ...NamePattern sind gegenseitig exklusiv. Pattern: LIKE (Default/like:), regex: oder regexi:.';
        PRINT N'Datenbankauswahl ohne Vorabbegrenzung; @MaxZeilen int: harte Ergebnismengenbegrenzung.';
        PRINT N'@LockTimeoutMs int = 0: Metadatenzugriff wartet standardmäßig nicht auf Locks.';
        PRINT N'@PrintMeldungen bit = 1: strukturierte Warnungen zusätzlich in der Console.';
        PRINT N'Die Procedure liefert Partitionen, Grenzwerte, Filegroups, Größe und Kompression.';
        PRINT N'@AnalyseModus=GEZIELT: Schema- oder Objektfilter erforderlich; VOLL prüft CATALOG_DEEP.';
        PRINT N'@NurPartitionierte: nur Indizes/Heaps mit mehr als einer Partition.';
        PRINT N'@NurGemischteKompression: nur Objekte mit unterschiedlichen data_compression_desc-Werten.';
        PRINT N'@Hilfe bit = 0: 1 zeigt diese Hilfe und führt keine Analyse aus.';
        RETURN;
 END;

    DECLARE @ModuleName sysname = N'USP_Partitions';
    DECLARE @CollectionTimeUtc datetime2(3) = SYSUTCDATETIME();

    DECLARE @OverallStatus varchar(40) = 'AVAILABLE';
    DECLARE @IsPartial bit = 0;
    DECLARE @TotalRows bigint = 0;
    DECLARE @ErrorNumber int = NULL;
    DECLARE @ErrorMessage nvarchar(2048) = NULL;
    DECLARE @Detail nvarchar(2000) = NULL;

    CREATE TABLE [#Partitions_DatabaseStatus]
    (
          [DatabaseName]       sysname        NULL
        , [StatusCode]         varchar(40)    NOT NULL
        , [IsPartial]          bit            NOT NULL
        , [RowCount]           bigint         NOT NULL
        , [RequiredPermission] nvarchar(256)  NULL
        , [ErrorNumber]        int            NULL
        , [ErrorMessage]       nvarchar(2048) NULL
        , [Detail]             nvarchar(2000) NULL
    );

    IF @FilterStatus<>'AVAILABLE' BEGIN SET @OverallStatus=@FilterStatus;SET @ErrorMessage=@FilterError;END;
    IF @ResultSetArtNormalisiert NOT IN('RAW','CONSOLE','NONE') BEGIN SET @OverallStatus='INVALID_PARAMETER';SET @ErrorMessage=N'@ResultSetArt muss CONSOLE, RAW, TABLE oder NONE enthalten.';END;
    IF @SchemaPatternValid=0 OR @ObjectPatternValid=0 OR @IndexPatternValid=0 OR @StatisticsPatternValid=0 OR (@SchemaNames IS NOT NULL AND @SchemaNamePattern IS NOT NULL) OR (@ObjectNames IS NOT NULL AND @ObjectNamePattern IS NOT NULL) BEGIN SET @OverallStatus='INVALID_PARAMETER';SET @ErrorMessage=N'Exakte Liste und Pattern derselben Eigenschaft sind gegenseitig exklusiv.';END;
IF @MaxZeilen<0 OR @LockTimeoutMs NOT BETWEEN 0 AND 60000
    BEGIN
        SET @OverallStatus = 'INVALID_PARAMETER';
        SET @ErrorMessage = N'Ungültiger Parameter: @MaxZeilen oder @LockTimeoutMs außerhalb des zulässigen Bereichs.';
    END


    IF @OverallStatus <> 'AVAILABLE'
    BEGIN
        INSERT [#Partitions_DatabaseStatus]([DatabaseName], [StatusCode], [IsPartial], [RowCount], [RequiredPermission], [ErrorNumber], [ErrorMessage], [Detail])
        VALUES(@DatabaseName, @OverallStatus, 1, 0, NULL, NULL, @ErrorMessage, N'Keine Datenbankanalyse ausgeführt.');
        SET @IsPartial = 1;
    END
    ELSE
    BEGIN
        SET LOCK_TIMEOUT 0;
    END;

 DECLARE @CatalogAllowed bit=1; IF @AnalyseModus='VOLL' SELECT @CatalogAllowed=COALESCE(MAX(CONVERT(tinyint,[IsAllowed])),0) FROM [monitor].[VW_AnalyseAccessCurrent] WHERE [AnalysisClass]='CATALOG_DEEP';
 CREATE TABLE [#Partitions_Result]
 (
  [DatabaseName] sysname NOT NULL,[SchemaName] sysname NOT NULL,[ObjectName] sysname NOT NULL,[ObjectId] int NOT NULL,
  [IndexId] int NOT NULL,[IndexName] sysname NULL,[IndexTypeDesc] nvarchar(60) NULL,[PartitionNumber] int NOT NULL,[PartitionCount] int NOT NULL,
  [PartitionId] bigint NOT NULL,[HobtId] bigint NULL,[RowCount] bigint NULL,[ReservedMb] decimal(19,2) NULL,[UsedMb] decimal(19,2) NULL,
  [DataCompressionDesc] nvarchar(60) NULL,[XmlCompressionDesc] varchar(3) NULL,[DataSpaceName] sysname NULL,[DestinationFilegroupName] sysname NULL,
  [PartitionSchemeName] sysname NULL,[PartitionFunctionName] sysname NULL,[BoundaryOnRight] bit NULL,
  [LowerBoundaryValue] nvarchar(4000) NULL,[LowerBoundaryInclusive] bit NULL,[UpperBoundaryValue] nvarchar(4000) NULL,[UpperBoundaryInclusive] bit NULL,
  [HasMixedCompression] bit NOT NULL
 );
 IF @OverallStatus='AVAILABLE' AND @AnalyseModus NOT IN ('GEZIELT','VOLL')
 BEGIN SET @OverallStatus='INVALID_PARAMETER'; SET @ErrorMessage=N'@AnalyseModus muss GEZIELT oder VOLL sein.'; INSERT [#Partitions_DatabaseStatus] VALUES(@DatabaseName,@OverallStatus,1,0,NULL,NULL,@ErrorMessage,NULL); END
 ELSE IF @OverallStatus='AVAILABLE' AND @AnalyseModus='GEZIELT' AND NOT EXISTS(SELECT 1 FROM [#Partitions_NameFilters]) AND @SchemaNamePattern IS NULL AND @ObjectNamePattern IS NULL
 BEGIN SET @OverallStatus='INVALID_PARAMETER'; SET @ErrorMessage=N'GEZIELT erfordert eine exakte Namensliste, @FullObjectNames oder ein Schema-/Objekt-Pattern.'; INSERT [#Partitions_DatabaseStatus] VALUES(@DatabaseName,@OverallStatus,1,0,NULL,NULL,@ErrorMessage,NULL); END
 ELSE IF @OverallStatus='AVAILABLE' AND @AnalyseModus='VOLL' AND @CatalogAllowed=0
 BEGIN SET @OverallStatus='DENIED_GROUP'; SET @ErrorMessage=N'CATALOG_DEEP ist nicht freigegeben.'; INSERT [#Partitions_DatabaseStatus] VALUES(@DatabaseName,@OverallStatus,1,0,NULL,NULL,@ErrorMessage,NULL); END
 ELSE IF @OverallStatus='AVAILABLE'
 BEGIN
  DECLARE @DbId int,@DbName sysname,@Sql nvarchar(max),@Rows bigint,@XmlExpr nvarchar(200);
  SET @XmlExpr=CASE WHEN TRY_CONVERT([int],SERVERPROPERTY(N'ProductMajorVersion'))>=16 THEN N'[p].[xml_compression_desc]' ELSE N'CONVERT(varchar(3),NULL)' END;
  DECLARE dbcur CURSOR LOCAL FAST_FORWARD FOR SELECT [DatabaseId],[DatabaseName] FROM [#Partitions_DatabaseCandidates];
  OPEN dbcur; FETCH NEXT FROM dbcur INTO @DbId,@DbName;
  WHILE @@FETCH_STATUS=0
  BEGIN
   BEGIN TRY
    SET @Sql = N'SET LOCK_TIMEOUT ' + CONVERT(nvarchar(11), @LockTimeoutMs) + N'; USE ' + QUOTENAME(@DbName) + N';
;WITH [P] AS
(
    SELECT
          [p].*
        , COUNT(*) OVER (PARTITION BY [p].[object_id], [p].[index_id]) AS [PartitionCount]
        , MIN([p].[data_compression_desc]) OVER (PARTITION BY [p].[object_id], [p].[index_id]) AS [MinCompression]
        , MAX([p].[data_compression_desc]) OVER (PARTITION BY [p].[object_id], [p].[index_id]) AS [MaxCompression]
    FROM [sys].[partitions] AS [p] WITH (NOLOCK)
),
[A] AS
(
    SELECT
          [p].[partition_id]
        , SUM(CONVERT(bigint, [au].[total_pages])) AS [ReservedPages]
        , SUM(CONVERT(bigint, [au].[used_pages])) AS [UsedPages]
    FROM [sys].[partitions] AS [p] WITH (NOLOCK)
    LEFT JOIN [sys].[allocation_units] AS [au] WITH (NOLOCK)
      ON [au].[container_id] = CASE WHEN [au].[type] = 2 THEN [p].[partition_id] ELSE [p].[hobt_id] END
    GROUP BY [p].[partition_id]
)
INSERT [#Partitions_Result]
(
      [DatabaseName], [SchemaName], [ObjectName], [ObjectId], [IndexId], [IndexName], [IndexTypeDesc]
    , [PartitionNumber], [PartitionCount], [PartitionId], [HobtId], [RowCount], [ReservedMb], [UsedMb]
    , [DataCompressionDesc], [XmlCompressionDesc], [DataSpaceName], [DestinationFilegroupName]
    , [PartitionSchemeName], [PartitionFunctionName], [BoundaryOnRight]
    , [LowerBoundaryValue], [LowerBoundaryInclusive], [UpperBoundaryValue], [UpperBoundaryInclusive]
    , [HasMixedCompression]
)
SELECT TOP (@pMaxRows)
      @pDbName
    , [s].[name]
    , [o].[name]
    , [o].[object_id]
    , [i].[index_id]
    , [i].[name]
    , [i].[type_desc]
    , [p].[partition_number]
    , [p].[PartitionCount]
    , [p].[partition_id]
    , [p].[hobt_id]
    , [p].[rows]
    , CONVERT(decimal(19,2), [a].[ReservedPages] / 128.0)
    , CONVERT(decimal(19,2), [a].[UsedPages] / 128.0)
    , [p].[data_compression_desc]
    , ' + @XmlExpr + N'
    , [ds].[name]
    , [fg].[name]
    , [ps].[name]
    , [pf].[name]
    , [pf].[boundary_value_on_right]
    , CONVERT(nvarchar(4000), [lo].[value])
    , CASE WHEN [lo].[value] IS NULL THEN NULL WHEN [pf].[boundary_value_on_right] = 1 THEN 1 ELSE 0 END
    , CONVERT(nvarchar(4000), [hi].[value])
    , CASE WHEN [hi].[value] IS NULL THEN NULL WHEN [pf].[boundary_value_on_right] = 1 THEN 0 ELSE 1 END
    , CONVERT(bit, CASE WHEN [p].[MinCompression] <> [p].[MaxCompression] THEN 1 ELSE 0 END)
FROM [P] AS [p]
JOIN [sys].[objects] AS [o] WITH (NOLOCK)
  ON [o].[object_id] = [p].[object_id]
JOIN [sys].[schemas] AS [s] WITH (NOLOCK)
  ON [s].[schema_id] = [o].[schema_id]
JOIN [sys].[indexes] AS [i] WITH (NOLOCK)
  ON [i].[object_id] = [p].[object_id]
 AND [i].[index_id] = [p].[index_id]
LEFT JOIN [A] AS [a]
  ON [a].[partition_id] = [p].[partition_id]
LEFT JOIN [sys].[data_spaces] AS [ds] WITH (NOLOCK)
  ON [ds].[data_space_id] = [i].[data_space_id]
LEFT JOIN [sys].[partition_schemes] AS [ps] WITH (NOLOCK)
  ON [ps].[data_space_id] = [i].[data_space_id]
LEFT JOIN [sys].[partition_functions] AS [pf] WITH (NOLOCK)
  ON [pf].[function_id] = [ps].[function_id]
LEFT JOIN [sys].[destination_data_spaces] AS [dds] WITH (NOLOCK)
  ON [dds].[partition_scheme_id] = [ps].[data_space_id]
 AND [dds].[destination_id] = [p].[partition_number]
LEFT JOIN [sys].[data_spaces] AS [fg] WITH (NOLOCK)
  ON [fg].[data_space_id] = [dds].[data_space_id]
LEFT JOIN [sys].[partition_range_values] AS [lo] WITH (NOLOCK)
  ON [lo].[function_id] = [pf].[function_id]
 AND [lo].[boundary_id] = [p].[partition_number] - 1
LEFT JOIN [sys].[partition_range_values] AS [hi] WITH (NOLOCK)
  ON [hi].[function_id] = [pf].[function_id]
 AND [hi].[boundary_id] = [p].[partition_number]
WHERE [o].[type] IN (''U'', ''V'')
  AND [o].[is_ms_shipped] = 0
'+@SchemaPredicateS+@ObjectPredicateO+@FullObjectPredicateSO+N'
  AND (@pOnlyPartitioned = 0 OR [p].[PartitionCount] > 1)
  AND (@pOnlyMixed = 0 OR [p].[MinCompression] <> [p].[MaxCompression])
ORDER BY [a].[ReservedPages] DESC, [o].[object_id], [i].[index_id], [p].[partition_number]
OPTION (MAXDOP 1, RECOMPILE);';
        EXEC [sys].[sp_executesql] @Sql,N'@pDbName sysname,@pMaxRows bigint,@pSchemaLike nvarchar(256),@pObjectLike nvarchar(256),@pOnlyPartitioned bit,@pOnlyMixed bit',@pDbName=@DbName,@pMaxRows=@EffectiveMaxZeilen,@pSchemaLike=@SchemaNameLike,@pObjectLike=@ObjectNameLike,@pOnlyPartitioned=@NurPartitionierte,@pOnlyMixed=@NurGemischteKompression;
    SELECT @Rows=COUNT_BIG(*) FROM [#Partitions_Result] WHERE [DatabaseName]=@DbName; INSERT [#Partitions_DatabaseStatus] VALUES(@DbName,'AVAILABLE',0,@Rows,N'Metadata Visibility',NULL,NULL,N'Partitionen und Allocation Units erfolgreich gelesen.');
   END TRY
   BEGIN CATCH
    INSERT [#Partitions_DatabaseStatus] VALUES(@DbName,CASE WHEN ERROR_NUMBER() IN (229,262,297,300,371,916) THEN 'DENIED_PERMISSION' WHEN ERROR_NUMBER()=1222 THEN 'TIMEOUT' ELSE 'ERROR_HANDLED' END,1,0,N'Metadata Visibility',ERROR_NUMBER(),ERROR_MESSAGE(),N'Partitionsfehler isoliert.');
   END CATCH;
   FETCH NEXT FROM dbcur INTO @DbId,@DbName;
  END; CLOSE dbcur; DEALLOCATE dbcur;
  IF NOT EXISTS(SELECT 1 FROM [#Partitions_DatabaseStatus]) INSERT [#Partitions_DatabaseStatus] VALUES(@DatabaseName,'DATABASE_UNAVAILABLE',1,0,NULL,NULL,N'Keine sichtbare Online-Zieldatenbank gefunden.',NULL);
 END;



    SELECT @TotalRows = COUNT_BIG(*) FROM [#Partitions_Result];

    IF @OverallStatus = 'AVAILABLE'
    BEGIN
        IF EXISTS (SELECT 1 FROM [#Partitions_DatabaseStatus] WHERE [StatusCode] NOT IN ('AVAILABLE','AVAILABLE_LIMITED','SKIPPED','NOT_APPLICABLE'))
        BEGIN
            SET @OverallStatus = CASE WHEN @TotalRows > 0 THEN 'PARTIAL' ELSE (SELECT TOP (1) [StatusCode] FROM [#Partitions_DatabaseStatus] WHERE [StatusCode] NOT IN ('AVAILABLE','AVAILABLE_LIMITED','SKIPPED','NOT_APPLICABLE') ORDER BY [DatabaseName]) END;
            SET @IsPartial = 1;
        END
        ELSE IF EXISTS (SELECT 1 FROM [#Partitions_DatabaseStatus] WHERE [StatusCode] IN ('AVAILABLE_LIMITED','SKIPPED','NOT_APPLICABLE'))
        BEGIN
            SET @OverallStatus = CASE WHEN @TotalRows > 0 THEN 'AVAILABLE_LIMITED' ELSE 'SKIPPED' END;
            SET @IsPartial = 1;
        END;
    END;

    IF @PrintMeldungen = 1 AND @OverallStatus <> 'AVAILABLE'
        BEGIN
    SET @MonitorPrintMessage = FORMATMESSAGE(N'WARNUNG %s: %s', @OverallStatus, COALESCE(@ErrorMessage, @Detail, N'Teilergebnis oder eingeschränkte Sicht'));
    RAISERROR(N'%s', 10, 1, @MonitorPrintMessage) WITH NOWAIT;
END;

    IF @ResultSetArtNormalisiert<>'NONE' BEGIN
        SELECT @ModuleName [ModuleName],@CollectionTimeUtc [CollectionTimeUtc],@OverallStatus [StatusCode],@IsPartial [IsPartial],@TotalRows [RowCount],@ErrorNumber [ErrorNumber],@ErrorMessage [ErrorMessage],@Detail [Detail];
        SELECT [DatabaseName],[StatusCode],[IsPartial],[RowCount],[RequiredPermission],[ErrorNumber],[ErrorMessage],[Detail] FROM [#Partitions_DatabaseStatus] ORDER BY [DatabaseName];
        IF @ResultSetArtNormalisiert='RAW' SELECT * FROM [#Partitions_Result] ORDER BY [ReservedMb] DESC,[DatabaseName],[SchemaName],[ObjectName],[IndexId],[PartitionNumber]; ELSE SELECT N'Partition' [Ergebnis],[r].* FROM [#Partitions_Result] [r] ORDER BY [ReservedMb] DESC,[DatabaseName],[SchemaName],[ObjectName],[IndexId],[PartitionNumber];
    END;
    IF @JsonErzeugen=1 BEGIN
        DECLARE @JsonMeta nvarchar(max)=(SELECT @ModuleName [resultName],1 [schemaVersion],@CollectionTimeUtc [generatedAtUtc],@OverallStatus [statusCode],@IsPartial [isPartial],@TotalRows [rowCount] FOR JSON PATH,WITHOUT_ARRAY_WRAPPER,INCLUDE_NULL_VALUES);
        DECLARE @JsonDatabaseStatus nvarchar(max)=(SELECT * FROM [#Partitions_DatabaseStatus] ORDER BY [DatabaseName] FOR JSON PATH,INCLUDE_NULL_VALUES);
        DECLARE @JsonData1 nvarchar(max)=(SELECT * FROM [#Partitions_Result] ORDER BY [ReservedMb] DESC,[DatabaseName],[SchemaName],[ObjectName],[IndexId],[PartitionNumber] FOR JSON PATH,INCLUDE_NULL_VALUES);
        SET @Json=CONCAT(N'{"meta":',COALESCE(@JsonMeta,N'{}'),N',"partitions":',COALESCE(@JsonData1,N'[]'),N',"databaseStatus":',COALESCE(@JsonDatabaseStatus,N'[]'),N'}');
    END;
    IF @ConsoleResultRequested = 1
    BEGIN
        EXEC [monitor].[InternalEmitConsoleResult]
              @SourceTable=N'#Partitions_Result'
            , @ResultLabel=N'Partitions'
            , @EmptyMessage=N'Keine fachlichen Ergebnisse';
    END;
    IF @TableResultRequested = 1
    BEGIN
        EXEC [monitor].[InternalWriteResultTable]
              @SourceTable = N'#Partitions_Result'
            , @TargetTable=@TableTarget
            , @ThrowOnError = 1;
    END;
END;
GO
-- END SOURCE: Code/03_ObjectIndex/050_USP_Partitions.sql

-- BEGIN SOURCE: Code/03_ObjectIndex/060_USP_Columnstore.sql
/*
===============================================================================
Objekt       : monitor.USP_Columnstore
Version      : 1.0.0
Stand        : 2026-07-14
Typ          : Stored Procedure
Zweck        : Analysiert Columnstore-Indizes, Rowgroups und Deleted Rows; Physical Stats, Segmente und Dictionaries sind explizite gruppengeschützte Vertiefungen.
SQL-Version  : SQL Server 2019 oder neuer.
Datenquellen : Je Datenbank sys.column_store_row_groups, optional sys.dm_db_column_store_row_group_physical_stats, sys.column_store_segments, sys.column_store_dictionaries sowie Systemkataloge.
Parameter    :
  @DatabaseName                  sysname        = NULL  - Zieldatenbank; bei Einzelmodus Pflicht.
  @CrossDatabaseRequestedInternal               bit            = 0     - sichtbare Online-Datenbanken analysieren.
  @SystemdatenbankenEinbeziehen  bit            = 0     - master/model/msdb/tempdb einbeziehen.
  @DatenbankNameLike             nvarchar(256)  = NULL  - Filter im Cross-Database-Modus.
  @SchemaNamePattern                nvarchar(256)  = NULL  - LIKE-Filter auf Schema.
  @ObjectNamePattern                nvarchar(256)  = NULL  - LIKE-Filter auf Objekt.
  @MaxZeilen                     int            = 5000  - positive Werte begrenzen; NULL/0 = unbegrenzt.
  @LockTimeoutMs                 int            = 0     - 0 = nicht auf Metadatenlocks warten.
  @PrintMeldungen                bit            = 1     - Warnungen via RAISERROR 10.
  @Hilfe                         bit            = 0     - Hilfe via PRINT, keine Analyse.
  @AnalyseModus varchar(16) = 'GEZIELT' - GEZIELT benötigt Filter; VOLL prüft CATALOG_DEEP.
  @MitPhysicalStats bit=0 - zusätzliche Physical Rowgroup Stats; benötigt COLUMNSTORE_DEEP.
  @MitSegmenten bit=0 - Spaltensegmente; benötigt COLUMNSTORE_DEEP.
  @MitDictionaries bit=0 - Dictionaries; benötigt COLUMNSTORE_DEEP.
  @MinDeletedPercent decimal(9,2)=0 - Rowgroup-Filter.
  @NurProblematisch bit=0 - OPEN/CLOSED/TOMBSTONE oder Deleted Rows.
Resultsets   : 1. Modulstatus. 2. Status je Datenbank. 3. Katalog-Rowgroups. 4. Physical Rowgroups. 5. Segmente. 6. Dictionaries.
Berechtigung : Basis gemäß Metadata Visibility/VIEW DEFINITION; Physical Stats SQL 2019 VIEW DATABASE STATE plus CONTROL, SQL 2022+ VIEW DATABASE PERFORMANCE STATE; Detailwerte können SELECT erfordern.
Eigenlast    : Basis moderat; Segmentanzahl entspricht Rowgroups × Spalten und ist daher nur opt-in, gruppengeschützt und TOP-begrenzt.
Locking      : READUNCOMMITTED-Kataloge, LOCK_TIMEOUT; keine Wartungs-DDL.
Partial      : Fehler je Datenbank bzw. Teilquelle werden isoliert; vorhandene
               Teilergebnisse bleiben erhalten. Das Framework vergibt keine Rechte.
Beispiele    :
  EXEC monitor.USP_Columnstore @DatabaseNames=N'[SampleDatabase]', @ObjectNamePattern=N'like:Fact%';
  EXEC monitor.USP_Columnstore @DatabaseNames=N'[SampleDatabase]', @ObjectNamePattern=N'like:Fact%', @MinDeletedPercent=10, @NurProblematisch=1;
  EXEC monitor.USP_Columnstore @DatabaseNames=N'SampleDatabase', @AnalyseModus='VOLL', @MitPhysicalStats=1, @MitSegmenten=1;
  EXEC monitor.USP_Columnstore @Hilfe=1;
Änderungen   : 1.0.0 - Erstfassung Phase 2.
===============================================================================
*/
CREATE OR ALTER PROCEDURE [monitor].[USP_Columnstore]
      @DatabaseNames                  nvarchar(max)  = NULL
    , @SystemdatenbankenEinbeziehen   bit            = 0
    , @DatabaseNamePattern            nvarchar(4000) = NULL
    , @HighImpactConfirmed              bit            = 0
    , @SchemaNames                    nvarchar(max)  = NULL
    , @SchemaNamePattern              nvarchar(4000) = NULL
    , @ObjectNames                    nvarchar(max)  = NULL
    , @ObjectNamePattern              nvarchar(4000) = NULL
    , @FullObjectNames                nvarchar(max)  = NULL
    , @AnalyseModus                  varchar(16)   = 'GEZIELT'
    , @MitPhysicalStats               bit           = 0
    , @MitSegmenten                   bit           = 0
    , @MitDictionaries                bit           = 0
    , @MinDeletedPercent              decimal(9,2)  = 0
    , @NurProblematisch               bit           = 0
    , @MaxZeilen                      int           = 10000
    , @LockTimeoutMs                  int           = 0
    , @ResultSetArt                  varchar(16)    = 'CONSOLE'
    , @ResultTablesJson               nvarchar(max) = NULL
    , @JsonErzeugen                  bit            = 0
    , @Json                          nvarchar(max)  = NULL OUTPUT
    , @PrintMeldungen                 bit           = 1
    , @Hilfe                          bit           = 0
AS
BEGIN
 SET NOCOUNT ON;

    SET @Json = NULL;
    DECLARE @ResultSetArtNormalisiert varchar(16)=UPPER(LTRIM(RTRIM(COALESCE(@ResultSetArt,''))));
    DECLARE @TableResultRequested bit = CASE WHEN @ResultSetArtNormalisiert = 'TABLE' THEN 1 ELSE 0 END;
    DECLARE @ConsoleResultRequested bit = CASE WHEN @ResultSetArtNormalisiert = 'CONSOLE' THEN 1 ELSE 0 END;
    DECLARE @TableTarget sysname=NULL;
    IF @TableResultRequested=0 AND NULLIF(LTRIM(RTRIM(COALESCE(@ResultTablesJson,N''))),N'') IS NOT NULL THROW 51011,N'@ResultTablesJson ist ausschließlich mit @ResultSetArt=TABLE zulässig.',1;
    IF @TableResultRequested=1 EXEC [monitor].[InternalPrepareSingleResultTable] @ResultTablesJson=@ResultTablesJson,@ResultName=N'rowgroups',@TargetTable=@TableTarget OUTPUT,@ThrowOnError=1;
    IF @TableResultRequested = 1 OR @ConsoleResultRequested = 1 SET @ResultSetArtNormalisiert = 'NONE';
    DECLARE @DatabaseName sysname=NULL,@CrossDatabaseRequestedInternal bit=0,@DatenbankNameLike nvarchar(4000)=NULL;
    DECLARE @SchemaNameLike nvarchar(4000)=NULL,@ObjectNameLike nvarchar(4000)=NULL;
    DECLARE @SchemaPatternMode varchar(8),@SchemaPatternValue nvarchar(4000),@SchemaRegexFlags varchar(8),@SchemaPatternValid bit;
    DECLARE @ObjectPatternMode varchar(8),@ObjectPatternValue nvarchar(4000),@ObjectRegexFlags varchar(8),@ObjectPatternValid bit;
    SELECT @SchemaPatternMode=[PatternMode],@SchemaPatternValue=[PatternValue],@SchemaRegexFlags=[RegexFlags],@SchemaPatternValid=[IsValid] FROM [monitor].[TVF_ParsePattern](@SchemaNamePattern);
    SELECT @ObjectPatternMode=[PatternMode],@ObjectPatternValue=[PatternValue],@ObjectRegexFlags=[RegexFlags],@ObjectPatternValid=[IsValid] FROM [monitor].[TVF_ParsePattern](@ObjectNamePattern);
    IF @SchemaPatternMode='LIKE' SET @SchemaNameLike=@SchemaPatternValue;
    IF @ObjectPatternMode='LIKE' SET @ObjectNameLike=@ObjectPatternValue;
    DECLARE @IndexPatternMode varchar(8)='NONE',@IndexPatternValue nvarchar(4000)=NULL,@IndexRegexFlags varchar(8)=NULL,@IndexPatternValid bit=1;
    DECLARE @StatisticsPatternMode varchar(8)='NONE',@StatisticsPatternValue nvarchar(4000)=NULL,@StatisticsRegexFlags varchar(8)=NULL,@StatisticsPatternValid bit=1;
    DECLARE @DatabaseListCount int=0;
    IF @DatabaseNames IS NOT NULL AND NULLIF(LTRIM(RTRIM(@DatabaseNames)),N'') IS NOT NULL
        SELECT @DatabaseListCount=COUNT(*),@DatabaseName=MIN([NameValue]) FROM [monitor].[TVF_ParseSqlNameList](@DatabaseNames) WHERE [IsValid]=1;
    SET @CrossDatabaseRequestedInternal=CONVERT(bit,CASE WHEN @DatabaseNames IS NULL OR @DatabaseNamePattern IS NOT NULL OR @DatabaseListCount>1 THEN 1 ELSE 0 END);
    SELECT @DatenbankNameLike=CASE WHEN [PatternMode]='LIKE' THEN [PatternValue] END FROM [monitor].[TVF_ParsePattern](@DatabaseNamePattern);
    CREATE TABLE [#Columnstore_NameFilters]([FilterType] varchar(20) COLLATE SQL_Latin1_General_CP1_CS_AS NOT NULL,[ItemOrdinal] int NOT NULL,[NameValue] sysname COLLATE SQL_Latin1_General_CP1_CS_AS NULL,[DatabaseName] sysname COLLATE SQL_Latin1_General_CP1_CS_AS NULL,[SchemaName] sysname COLLATE SQL_Latin1_General_CP1_CS_AS NULL,[ObjectName] sysname COLLATE SQL_Latin1_General_CP1_CS_AS NULL);
    CREATE TABLE [#Columnstore_DatabaseCandidates]([DatabaseId] int NOT NULL,[DatabaseName] sysname NOT NULL,[StateDesc] nvarchar(60),[UserAccessDesc] nvarchar(60),[IsReadOnly] bit,[CompatibilityLevel] tinyint,[CollationName] sysname,[RecoveryModelDesc] nvarchar(60),[IsSystemDatabase] bit,[RequestedOrdinal] int);
    DECLARE @FilterStatus varchar(40)='AVAILABLE',@FilterError nvarchar(2048)=NULL,@CrossDatabaseRequested bit=0;
    EXEC [monitor].[USP_PrepareNameFilters] @SchemaNames=@SchemaNames,@ObjectNames=@ObjectNames,@FullObjectNames=@FullObjectNames,@IndexNames=NULL,@StatisticsNames=NULL,@ColumnNames=NULL,@StatusCode=@FilterStatus OUTPUT,@ErrorMessage=@FilterError OUTPUT,@FilterTable=N'#Columnstore_NameFilters';
    IF @FilterStatus='AVAILABLE' EXEC [monitor].[USP_PrepareDatabaseCandidates] @DatabaseNames=@DatabaseNames,@SystemdatenbankenEinbeziehen=@SystemdatenbankenEinbeziehen,@DatabaseNamePattern=@DatabaseNamePattern,@HighImpactConfirmed=@HighImpactConfirmed,@AnalysisClass='COLUMNSTORE_CURRENT',@StatusCode=@FilterStatus OUTPUT,@ErrorMessage=@FilterError OUTPUT,@CrossDatabaseRequested=@CrossDatabaseRequested OUTPUT,@CandidateTable=N'#Columnstore_DatabaseCandidates';
    IF @FilterStatus='AVAILABLE' AND (@MitPhysicalStats=1 OR @MitSegmenten=1 OR @MitDictionaries=1)
        EXEC [monitor].[InternalCheckAnalysisPath] @AnalysisClass='COLUMNSTORE_DEEP',@HighImpactConfirmed=@HighImpactConfirmed,@StatusCode=@FilterStatus OUTPUT,@ErrorMessage=@FilterError OUTPUT;
    IF @FilterStatus='AVAILABLE' AND UPPER(LTRIM(RTRIM(COALESCE(@AnalyseModus,''))))='VOLL'
        EXEC [monitor].[InternalCheckAnalysisPath] @AnalysisClass='CATALOG_DEEP',@HighImpactConfirmed=@HighImpactConfirmed,@StatusCode=@FilterStatus OUTPUT,@ErrorMessage=@FilterError OUTPUT;
    DECLARE @SchemaPredicateS nvarchar(max),@SchemaPredicateSch nvarchar(max),@ObjectPredicateO nvarchar(max),@FullObjectPredicateSO nvarchar(max),@IndexPredicateI nvarchar(max),@StatisticsPredicateSt nvarchar(max);
    SET @SchemaPredicateS=N' AND (NOT EXISTS(SELECT 1 FROM [#Columnstore_NameFilters] WHERE [FilterType]=''SCHEMA'') OR EXISTS(SELECT 1 FROM [#Columnstore_NameFilters] [f] WHERE [f].[FilterType]=''SCHEMA'' AND [f].[NameValue]=[s].[name] COLLATE SQL_Latin1_General_CP1_CS_AS))';
    SET @SchemaPredicateSch=REPLACE(@SchemaPredicateS,N'[s].[name]',N'[sch].[name]');
    SET @ObjectPredicateO=N' AND (NOT EXISTS(SELECT 1 FROM [#Columnstore_NameFilters] WHERE [FilterType]=''OBJECT'') OR EXISTS(SELECT 1 FROM [#Columnstore_NameFilters] [f] WHERE [f].[FilterType]=''OBJECT'' AND [f].[NameValue]=[o].[name] COLLATE SQL_Latin1_General_CP1_CS_AS))';
    SET @FullObjectPredicateSO=N' AND (NOT EXISTS(SELECT 1 FROM [#Columnstore_NameFilters] WHERE [FilterType]=''FULL_OBJECT'') OR EXISTS(SELECT 1 FROM [#Columnstore_NameFilters] [f] WHERE [f].[FilterType]=''FULL_OBJECT'' AND ([f].[DatabaseName] IS NULL OR [f].[DatabaseName]=@pDbName COLLATE SQL_Latin1_General_CP1_CS_AS) AND ([f].[SchemaName] IS NULL OR [f].[SchemaName]=[s].[name] COLLATE SQL_Latin1_General_CP1_CS_AS) AND [f].[ObjectName]=[o].[name] COLLATE SQL_Latin1_General_CP1_CS_AS))';
    SET @IndexPredicateI=N' AND (NOT EXISTS(SELECT 1 FROM [#Columnstore_NameFilters] WHERE [FilterType]=''INDEX'') OR EXISTS(SELECT 1 FROM [#Columnstore_NameFilters] [f] WHERE [f].[FilterType]=''INDEX'' AND [f].[NameValue]=[i].[name] COLLATE SQL_Latin1_General_CP1_CS_AS))';
    SET @StatisticsPredicateSt=N' AND (NOT EXISTS(SELECT 1 FROM [#Columnstore_NameFilters] WHERE [FilterType]=''STATISTICS'') OR EXISTS(SELECT 1 FROM [#Columnstore_NameFilters] [f] WHERE [f].[FilterType]=''STATISTICS'' AND [f].[NameValue]=[st].[name] COLLATE SQL_Latin1_General_CP1_CS_AS))';
    IF @SchemaPatternMode='LIKE' BEGIN SET @SchemaPredicateS+=N' AND [s].[name] COLLATE SQL_Latin1_General_CP1_CS_AS LIKE N'''+REPLACE(@SchemaPatternValue,N'''',N'''''')+N''' COLLATE SQL_Latin1_General_CP1_CS_AS';SET @SchemaPredicateSch+=N' AND [sch].[name] COLLATE SQL_Latin1_General_CP1_CS_AS LIKE N'''+REPLACE(@SchemaPatternValue,N'''',N'''''')+N''' COLLATE SQL_Latin1_General_CP1_CS_AS';END;
    IF @SchemaPatternMode IN('REGEX','REGEXI') BEGIN SET @SchemaPredicateS+=N' AND REGEXP_LIKE([s].[name],N'''+REPLACE(@SchemaPatternValue,N'''',N'''''')+N''','''+@SchemaRegexFlags+N''')';SET @SchemaPredicateSch+=N' AND REGEXP_LIKE([sch].[name],N'''+REPLACE(@SchemaPatternValue,N'''',N'''''')+N''','''+@SchemaRegexFlags+N''')';END;
    IF @ObjectPatternMode='LIKE' SET @ObjectPredicateO+=N' AND [o].[name] COLLATE SQL_Latin1_General_CP1_CS_AS LIKE N'''+REPLACE(@ObjectPatternValue,N'''',N'''''')+N''' COLLATE SQL_Latin1_General_CP1_CS_AS';
    IF @ObjectPatternMode IN('REGEX','REGEXI') SET @ObjectPredicateO+=N' AND REGEXP_LIKE([o].[name],N'''+REPLACE(@ObjectPatternValue,N'''',N'''''')+N''','''+@ObjectRegexFlags+N''')';
    IF @IndexPatternMode='LIKE' SET @IndexPredicateI+=N' AND [i].[name] COLLATE SQL_Latin1_General_CP1_CS_AS LIKE N'''+REPLACE(@IndexPatternValue,N'''',N'''''')+N''' COLLATE SQL_Latin1_General_CP1_CS_AS';
    IF @IndexPatternMode IN('REGEX','REGEXI') SET @IndexPredicateI+=N' AND REGEXP_LIKE([i].[name],N'''+REPLACE(@IndexPatternValue,N'''',N'''''')+N''','''+@IndexRegexFlags+N''')';
    IF @StatisticsPatternMode='LIKE' SET @StatisticsPredicateSt+=N' AND [st].[name] COLLATE SQL_Latin1_General_CP1_CS_AS LIKE N'''+REPLACE(@StatisticsPatternValue,N'''',N'''''')+N''' COLLATE SQL_Latin1_General_CP1_CS_AS';
    IF @StatisticsPatternMode IN('REGEX','REGEXI') SET @StatisticsPredicateSt+=N' AND REGEXP_LIKE([st].[name],N'''+REPLACE(@StatisticsPatternValue,N'''',N'''''')+N''','''+@StatisticsRegexFlags+N''')';
    DECLARE @EffectiveMaxZeilen bigint = CASE WHEN @MaxZeilen IS NULL OR @MaxZeilen=0 THEN CONVERT(bigint,9223372036854775807) ELSE CONVERT(bigint,@MaxZeilen) END;
    DECLARE @MonitorPrintMessage nvarchar(2048); SET @AnalyseModus=UPPER(LTRIM(RTRIM(COALESCE(@AnalyseModus,'GEZIELT'))));
 IF @Hilfe=1
 BEGIN
        PRINT N'monitor.USP_Columnstore';        PRINT N'@DatabaseNames: exakter Name oder bracket-aware Pipe-Liste; NULL = alle zulässigen Datenbanken; N'''' = keine Einschränkung.';        PRINT N'@SystemdatenbankenEinbeziehen bit = 0: Systemdatenbanken einbeziehen.';        PRINT N'Exakte Listen und ...NamePattern sind gegenseitig exklusiv. Pattern: LIKE (Default/like:), regex: oder regexi:.';
        PRINT N'Datenbankauswahl ohne Vorabbegrenzung; @MaxZeilen int: harte Ergebnismengenbegrenzung.';
        PRINT N'@LockTimeoutMs int = 0: Metadatenzugriff wartet standardmäßig nicht auf Locks.';
        PRINT N'@PrintMeldungen bit = 1: strukturierte Warnungen zusätzlich in der Console.';
        PRINT N'Die Procedure liefert Rowgroups, Deleted Rows, Delta Stores sowie optionale Physical-, Segment- und Dictionary-Details.';
        PRINT N'@AnalyseModus varchar(16) = GEZIELT: GEZIELT benötigt Schema-/Objektfilter; VOLL prüft CATALOG_DEEP.';
        PRINT N'@MitPhysicalStats/@MitSegmenten/@MitDictionaries: jeweils opt-in und COLUMNSTORE_DEEP-geschützt.';
        PRINT N'@MinDeletedPercent: Filter 0 bis 100.';
        PRINT N'@NurProblematisch: Rowgroups mit Status ungleich COMPRESSED oder gelöschten Zeilen.';
        PRINT N'@Hilfe bit = 0: 1 zeigt diese Hilfe und führt keine Analyse aus.';
        RETURN;
 END;

    DECLARE @ModuleName sysname = N'USP_Columnstore';
    DECLARE @CollectionTimeUtc datetime2(3) = SYSUTCDATETIME();

    DECLARE @OverallStatus varchar(40) = 'AVAILABLE';
    DECLARE @IsPartial bit = 0;
    DECLARE @TotalRows bigint = 0;
    DECLARE @ErrorNumber int = NULL;
    DECLARE @ErrorMessage nvarchar(2048) = NULL;
    DECLARE @Detail nvarchar(2000) = NULL;

    CREATE TABLE [#Columnstore_DatabaseStatus]
    (
          [DatabaseName]       sysname        NULL
        , [StatusCode]         varchar(40)    NOT NULL
        , [IsPartial]          bit            NOT NULL
        , [RowCount]           bigint         NOT NULL
        , [RequiredPermission] nvarchar(256)  NULL
        , [ErrorNumber]        int            NULL
        , [ErrorMessage]       nvarchar(2048) NULL
        , [Detail]             nvarchar(2000) NULL
    );

    IF @FilterStatus<>'AVAILABLE' BEGIN SET @OverallStatus=@FilterStatus;SET @ErrorMessage=@FilterError;END;
    IF @ResultSetArtNormalisiert NOT IN('RAW','CONSOLE','NONE') BEGIN SET @OverallStatus='INVALID_PARAMETER';SET @ErrorMessage=N'@ResultSetArt muss CONSOLE, RAW, TABLE oder NONE enthalten.';END;
    IF @SchemaPatternValid=0 OR @ObjectPatternValid=0 OR @IndexPatternValid=0 OR @StatisticsPatternValid=0 OR (@SchemaNames IS NOT NULL AND @SchemaNamePattern IS NOT NULL) OR (@ObjectNames IS NOT NULL AND @ObjectNamePattern IS NOT NULL) BEGIN SET @OverallStatus='INVALID_PARAMETER';SET @ErrorMessage=N'Exakte Liste und Pattern derselben Eigenschaft sind gegenseitig exklusiv.';END;
IF @MaxZeilen<0 OR @LockTimeoutMs NOT BETWEEN 0 AND 60000
    BEGIN
        SET @OverallStatus = 'INVALID_PARAMETER';
        SET @ErrorMessage = N'Ungültiger Parameter: @MaxZeilen oder @LockTimeoutMs außerhalb des zulässigen Bereichs.';
    END


    IF @OverallStatus <> 'AVAILABLE'
    BEGIN
        INSERT [#Columnstore_DatabaseStatus]([DatabaseName], [StatusCode], [IsPartial], [RowCount], [RequiredPermission], [ErrorNumber], [ErrorMessage], [Detail])
        VALUES(@DatabaseName, @OverallStatus, 1, 0, NULL, NULL, @ErrorMessage, N'Keine Datenbankanalyse ausgeführt.');
        SET @IsPartial = 1;
    END
    ELSE
    BEGIN
        SET LOCK_TIMEOUT 0;
    END;

 DECLARE @CatalogAllowed bit=1;
 IF @AnalyseModus='VOLL' SELECT @CatalogAllowed=COALESCE(MAX(CONVERT(tinyint,[IsAllowed])),0) FROM [monitor].[VW_AnalyseAccessCurrent] WHERE [AnalysisClass]='CATALOG_DEEP';
 DECLARE @ColumnstoreDeepAllowed bit=1;
 IF @MitPhysicalStats=1 OR @MitSegmenten=1 OR @MitDictionaries=1 SELECT @ColumnstoreDeepAllowed=COALESCE(MAX(CONVERT(tinyint,[IsAllowed])),0) FROM [monitor].[VW_AnalyseAccessCurrent] WHERE [AnalysisClass]='COLUMNSTORE_DEEP';
 CREATE TABLE [#Columnstore_Result]
 (
  [DatabaseName] sysname NOT NULL,[SchemaName] sysname NOT NULL,[ObjectName] sysname NOT NULL,[ObjectId] int NOT NULL,[IndexId] int NOT NULL,[IndexName] sysname NULL,[IndexTypeDesc] nvarchar(60) NULL,
  [PartitionNumber] int NOT NULL,[RowGroupId] int NOT NULL,[StateDesc] nvarchar(60) NULL,[TotalRows] bigint NULL,[DeletedRows] bigint NULL,[ActiveRows] bigint NULL,
  [DeletedPercent] decimal(9,4) NULL,[FullnessPercent] decimal(9,4) NULL,[SizeMb] decimal(19,2) NULL,[DeltaStoreHobtId] bigint NULL,
  [TrimReasonDesc] nvarchar(60) NULL,[TransitionToCompressedStateDesc] nvarchar(60) NULL,[HasVertipaqOptimization] bit NULL,[Generation] bigint NULL,[CreatedTime] datetime2 NULL,[ClosedTime] datetime2 NULL,
  [Assessment] varchar(60) NOT NULL
 );
 CREATE TABLE [#Columnstore_Physical]
 (
  [DatabaseName] sysname NOT NULL,[SchemaName] sysname NOT NULL,[ObjectName] sysname NOT NULL,[ObjectId] int NOT NULL,[IndexId] int NOT NULL,[IndexName] sysname NULL,[IndexTypeDesc] nvarchar(60) NULL,
  [PartitionNumber] int NOT NULL,[RowGroupId] int NOT NULL,[StateDesc] nvarchar(60) NULL,[TotalRows] bigint NULL,[DeletedRows] bigint NULL,[ActiveRows] bigint NULL,
  [DeletedPercent] decimal(9,4) NULL,[SizeMb] decimal(19,2) NULL,[DeltaStoreHobtId] bigint NULL,[TrimReasonDesc] nvarchar(60) NULL,
  [TransitionToCompressedStateDesc] nvarchar(60) NULL,[HasVertipaqOptimization] bit NULL,[Generation] bigint NULL,[CreatedTime] datetime2 NULL,[ClosedTime] datetime2 NULL,[Assessment] varchar(60) NOT NULL
 );
 CREATE TABLE [#Columnstore_Segments]
 (
  [DatabaseName] sysname NOT NULL,[SchemaName] sysname NOT NULL,[ObjectName] sysname NOT NULL,[IndexId] int NOT NULL,[PartitionNumber] int NOT NULL,[ColumnId] int NOT NULL,[ColumnName] sysname NULL,
  [RowGroupId] int NOT NULL,[EncodingType] int NULL,[EncodingTypeDesc] varchar(40) NULL,[RowCount] int NULL,[HasNulls] int NULL,[PrimaryDictionaryId] int NULL,[SecondaryDictionaryId] int NULL,[OnDiskSizeMb] decimal(19,4) NULL
 );
 CREATE TABLE [#Columnstore_Dictionaries]
 (
  [DatabaseName] sysname NOT NULL,[SchemaName] sysname NOT NULL,[ObjectName] sysname NOT NULL,[IndexId] int NOT NULL,[PartitionNumber] int NOT NULL,[ColumnId] int NOT NULL,[ColumnName] sysname NULL,
  [DictionaryId] int NOT NULL,[DictionaryType] int NULL,[DictionaryTypeDesc] varchar(40) NULL,[EntryCount] bigint NULL,[OnDiskSizeMb] decimal(19,4) NULL
 );
 IF @OverallStatus='AVAILABLE' AND (@MinDeletedPercent<0 OR @MinDeletedPercent>100)
 BEGIN SET @OverallStatus='INVALID_PARAMETER'; SET @ErrorMessage=N'@MinDeletedPercent muss zwischen 0 und 100 liegen.'; INSERT [#Columnstore_DatabaseStatus] VALUES(@DatabaseName,@OverallStatus,1,0,NULL,NULL,@ErrorMessage,NULL); END
 ELSE IF @OverallStatus='AVAILABLE' AND @AnalyseModus NOT IN ('GEZIELT','VOLL')
 BEGIN SET @OverallStatus='INVALID_PARAMETER'; SET @ErrorMessage=N'@AnalyseModus muss GEZIELT oder VOLL sein.'; INSERT [#Columnstore_DatabaseStatus] VALUES(@DatabaseName,@OverallStatus,1,0,NULL,NULL,@ErrorMessage,NULL); END
 ELSE IF @OverallStatus='AVAILABLE' AND @AnalyseModus='GEZIELT' AND NOT EXISTS(SELECT 1 FROM [#Columnstore_NameFilters]) AND @SchemaNamePattern IS NULL AND @ObjectNamePattern IS NULL
 BEGIN SET @OverallStatus='INVALID_PARAMETER'; SET @ErrorMessage=N'GEZIELT erfordert eine exakte Namensliste, @FullObjectNames oder ein Schema-/Objekt-Pattern. Für den vollständigen Lauf @AnalyseModus=''VOLL'' verwenden.'; INSERT [#Columnstore_DatabaseStatus] VALUES(@DatabaseName,@OverallStatus,1,0,NULL,NULL,@ErrorMessage,NULL); END
 ELSE IF @OverallStatus='AVAILABLE' AND @AnalyseModus='VOLL' AND @CatalogAllowed=0
 BEGIN SET @OverallStatus='DENIED_GROUP'; SET @ErrorMessage=N'CATALOG_DEEP ist für die vollständige Columnstore-Basisanalyse nicht freigegeben.'; INSERT [#Columnstore_DatabaseStatus] VALUES(@DatabaseName,@OverallStatus,1,0,NULL,NULL,@ErrorMessage,NULL); END
 ELSE IF @OverallStatus='AVAILABLE' AND (@MitPhysicalStats=1 OR @MitSegmenten=1 OR @MitDictionaries=1) AND @ColumnstoreDeepAllowed=0
 BEGIN SET @OverallStatus='DENIED_GROUP'; SET @ErrorMessage=N'COLUMNSTORE_DEEP ist für die angeforderte Vertiefung nicht freigegeben.'; INSERT [#Columnstore_DatabaseStatus] VALUES(@DatabaseName,@OverallStatus,1,0,NULL,NULL,@ErrorMessage,NULL); END
 ELSE IF @OverallStatus='AVAILABLE'
 BEGIN
  DECLARE @DbId int,@DbName sysname,@Sql nvarchar(max),@Rows bigint;
  DECLARE dbcur CURSOR LOCAL FAST_FORWARD FOR
   SELECT [DatabaseId],[DatabaseName]
   FROM [#Columnstore_DatabaseCandidates];
  OPEN dbcur; FETCH NEXT FROM dbcur INTO @DbId,@DbName;
  WHILE @@FETCH_STATUS=0
  BEGIN
   BEGIN TRY
    SET @Sql = N'SET LOCK_TIMEOUT ' + CONVERT(nvarchar(11), @LockTimeoutMs) + N'; USE ' + QUOTENAME(@DbName) + N';
INSERT #Columnstore_Result
SELECT TOP (@pMaxRows) @pDbName,[s].[name],[o].[name],[o].[object_id],[i].[index_id],[i].[name],[i].[type_desc],[rg].[partition_number],[rg].[row_group_id],[rg].[state_description],
 [rg].[total_rows],[rg].[deleted_rows],[rg].[total_rows]-COALESCE([rg].[deleted_rows],0),CONVERT(decimal(9,4),[rg].[deleted_rows]*100.0/NULLIF([rg].[total_rows],0)),
 CONVERT(decimal(9,4),([rg].[total_rows]-COALESCE([rg].[deleted_rows],0))*100.0/1048576.0),CONVERT(decimal(19,2),[rg].[size_in_bytes]/1048576.0),[rg].[delta_store_hobt_id],
 NULL,NULL,NULL,NULL,NULL,NULL,
 CASE WHEN [rg].[state_description]=''TOMBSTONE'' THEN ''TOMBSTONE'' WHEN [rg].[state_description]=''CLOSED'' THEN ''CLOSED_WAITING_FOR_TUPLE_MOVER'' WHEN [rg].[state_description]=''OPEN'' THEN ''OPEN_DELTA_STORE''
      WHEN [rg].[deleted_rows]*100.0/NULLIF([rg].[total_rows],0)>=20 THEN ''HIGH_DELETED_ROWS'' WHEN [rg].[total_rows]<102400 AND [rg].[state_description]=''COMPRESSED'' THEN ''SMALL_COMPRESSED_ROWGROUP'' ELSE ''NORMAL'' END
FROM sys.column_store_row_groups AS [rg] WITH (NOLOCK)
JOIN sys.objects AS [o] WITH (NOLOCK) ON [o].[object_id]=[rg].[object_id]
JOIN sys.schemas AS [s] WITH (NOLOCK) ON [s].[schema_id]=[o].[schema_id]
JOIN sys.indexes AS [i] WITH (NOLOCK) ON [i].[object_id]=[rg].[object_id] AND [i].[index_id]=[rg].[index_id]
WHERE 1=1'+@SchemaPredicateS+@ObjectPredicateO+@FullObjectPredicateSO+N'
 AND COALESCE([rg].[deleted_rows]*100.0/NULLIF([rg].[total_rows],0),0)>=@pMinDeleted
 AND (@pOnlyProblems=0 OR [rg].[state_description]<>''COMPRESSED'' OR COALESCE([rg].[deleted_rows],0)>0)
ORDER BY COALESCE([rg].[deleted_rows]*100.0/NULLIF([rg].[total_rows],0),0) DESC,[rg].[total_rows] ASC
OPTION (MAXDOP 1,RECOMPILE);';
    EXEC [sys].[sp_executesql] @Sql,N'@pDbName sysname,@pMaxRows bigint,@pSchemaLike nvarchar(256),@pObjectLike nvarchar(256),@pMinDeleted decimal(9,2),@pOnlyProblems bit',
      @pDbName=@DbName,@pMaxRows=@EffectiveMaxZeilen,@pSchemaLike=@SchemaNameLike,@pObjectLike=@ObjectNameLike,@pMinDeleted=@MinDeletedPercent,@pOnlyProblems=@NurProblematisch;
    SELECT @Rows=COUNT_BIG(*) FROM [#Columnstore_Result] WHERE [DatabaseName]=@DbName;
    INSERT [#Columnstore_DatabaseStatus] VALUES(@DbName,'AVAILABLE',0,@Rows,N'VIEW DEFINITION / Metadata Visibility',NULL,NULL,N'Quelle COLUMNSTORE_CATALOG erfolgreich gelesen.');
   END TRY
   BEGIN CATCH
    INSERT [#Columnstore_DatabaseStatus] VALUES(@DbName,CASE WHEN ERROR_NUMBER() IN (229,262,297,300,371,916) THEN 'DENIED_PERMISSION' WHEN ERROR_NUMBER()=1222 THEN 'TIMEOUT' WHEN ERROR_NUMBER() IN (207,208) THEN 'UNAVAILABLE_OBJECT' ELSE 'ERROR_HANDLED' END,1,0,N'VIEW DEFINITION / Metadata Visibility',ERROR_NUMBER(),ERROR_MESSAGE(),N'Quelle COLUMNSTORE_CATALOG fehlgeschlagen; optionale Teilquellen werden dennoch versucht.');
   END CATCH;

   IF @MitPhysicalStats=1
   BEGIN
    BEGIN TRY
     SET @Sql = N'SET LOCK_TIMEOUT ' + CONVERT(nvarchar(11), @LockTimeoutMs) + N'; USE ' + QUOTENAME(@DbName) + N';
INSERT #Columnstore_Physical
SELECT TOP (@pMaxRows) @pDbName,[s].[name],[o].[name],[o].[object_id],[i].[index_id],[i].[name],[i].[type_desc],[rg].[partition_number],[rg].[row_group_id],[rg].[state_desc],
 [rg].[total_rows],[rg].[deleted_rows],[rg].[total_rows]-COALESCE([rg].[deleted_rows],0),CONVERT(decimal(9,4),[rg].[deleted_rows]*100.0/NULLIF([rg].[total_rows],0)),
 CONVERT(decimal(19,2),[rg].[size_in_bytes]/1048576.0),[rg].[delta_store_hobt_id],[rg].[trim_reason_desc],[rg].[transition_to_compressed_state_desc],
 [rg].[has_vertipaq_optimization],[rg].[generation],[rg].[created_time],[rg].[closed_time],
 CASE WHEN [rg].[state_desc]=''TOMBSTONE'' THEN ''TOMBSTONE'' WHEN [rg].[state_desc]=''CLOSED'' THEN ''CLOSED_WAITING_FOR_TUPLE_MOVER'' WHEN [rg].[state_desc]=''OPEN'' THEN ''OPEN_DELTA_STORE''
      WHEN [rg].[deleted_rows]*100.0/NULLIF([rg].[total_rows],0)>=20 THEN ''HIGH_DELETED_ROWS'' WHEN [rg].[total_rows]<102400 AND [rg].[state_desc]=''COMPRESSED'' THEN ''SMALL_COMPRESSED_ROWGROUP'' ELSE ''NORMAL'' END
FROM sys.dm_db_column_store_row_group_physical_stats AS [rg] WITH (NOLOCK)
JOIN sys.objects AS [o] WITH (NOLOCK) ON [o].[object_id]=[rg].[object_id]
JOIN sys.schemas AS [s] WITH (NOLOCK) ON [s].[schema_id]=[o].[schema_id]
JOIN sys.indexes AS [i] WITH (NOLOCK) ON [i].[object_id]=[rg].[object_id] AND [i].[index_id]=[rg].[index_id]
WHERE 1=1'+@SchemaPredicateS+@ObjectPredicateO+@FullObjectPredicateSO+N'
 AND COALESCE([rg].[deleted_rows]*100.0/NULLIF([rg].[total_rows],0),0)>=@pMinDeleted
 AND (@pOnlyProblems=0 OR [rg].[state_desc]<>''COMPRESSED'' OR COALESCE([rg].[deleted_rows],0)>0)
ORDER BY COALESCE([rg].[deleted_rows]*100.0/NULLIF([rg].[total_rows],0),0) DESC,[rg].[total_rows] ASC
OPTION (MAXDOP 1,RECOMPILE);';
     EXEC [sys].[sp_executesql] @Sql,N'@pDbName sysname,@pMaxRows bigint,@pSchemaLike nvarchar(256),@pObjectLike nvarchar(256),@pMinDeleted decimal(9,2),@pOnlyProblems bit',
      @pDbName=@DbName,@pMaxRows=@EffectiveMaxZeilen,@pSchemaLike=@SchemaNameLike,@pObjectLike=@ObjectNameLike,@pMinDeleted=@MinDeletedPercent,@pOnlyProblems=@NurProblematisch;
     SELECT @Rows=COUNT_BIG(*) FROM [#Columnstore_Physical] WHERE [DatabaseName]=@DbName;
     INSERT [#Columnstore_DatabaseStatus] VALUES(@DbName,'AVAILABLE',0,@Rows,CASE WHEN TRY_CONVERT([int],SERVERPROPERTY(N'ProductMajorVersion'))>=16 THEN N'VIEW DATABASE PERFORMANCE STATE' ELSE N'VIEW DATABASE STATE plus CONTROL/geeignete Objektrechte' END,NULL,NULL,N'Quelle COLUMNSTORE_PHYSICAL erfolgreich gelesen.');
    END TRY
    BEGIN CATCH
     INSERT [#Columnstore_DatabaseStatus] VALUES(@DbName,CASE WHEN ERROR_NUMBER() IN (229,262,297,300,371,916) THEN 'DENIED_PERMISSION' WHEN ERROR_NUMBER()=1222 THEN 'TIMEOUT' WHEN ERROR_NUMBER() IN (207,208) THEN 'UNAVAILABLE_OBJECT' ELSE 'ERROR_HANDLED' END,1,0,CASE WHEN TRY_CONVERT([int],SERVERPROPERTY(N'ProductMajorVersion'))>=16 THEN N'VIEW DATABASE PERFORMANCE STATE' ELSE N'VIEW DATABASE STATE plus CONTROL/geeignete Objektrechte' END,ERROR_NUMBER(),ERROR_MESSAGE(),N'Quelle COLUMNSTORE_PHYSICAL fehlgeschlagen; Katalogergebnis bleibt erhalten.');
    END CATCH;
   END;

   IF @MitSegmenten=1
   BEGIN
    BEGIN TRY
     SET @Sql = N'SET LOCK_TIMEOUT ' + CONVERT(nvarchar(11), @LockTimeoutMs) + N'; USE ' + QUOTENAME(@DbName) + N';
INSERT #Columnstore_Segments
SELECT TOP (@pMaxRows) @pDbName,[sch].[name],[o].[name],[i].[index_id],[p].[partition_number],[sg].[column_id],[c].[name],[sg].[segment_id],[sg].[encoding_type],
 CASE [sg].[encoding_type] WHEN 1 THEN ''VALUE_BASED'' WHEN 2 THEN ''VALUE_HASH_BASED'' WHEN 3 THEN ''STRING_HASH_BASED'' WHEN 4 THEN ''STORE_BY_VALUE_BASED'' WHEN 5 THEN ''STRING_STORE_BY_VALUE_BASED'' ELSE ''UNKNOWN'' END,
 [sg].[row_count],[sg].[has_nulls],[sg].[primary_dictionary_id],[sg].[secondary_dictionary_id],CONVERT(decimal(19,4),[sg].[on_disk_size]/1048576.0)
FROM sys.column_store_segments AS [sg] WITH (NOLOCK)
JOIN sys.partitions AS [p] WITH (NOLOCK) ON [p].[hobt_id]=[sg].[hobt_id] AND [p].[partition_id]=[sg].[partition_id]
JOIN sys.objects AS [o] WITH (NOLOCK) ON [o].[object_id]=[p].[object_id]
JOIN sys.schemas AS [sch] WITH (NOLOCK) ON [sch].[schema_id]=[o].[schema_id]
JOIN sys.indexes AS [i] WITH (NOLOCK) ON [i].[object_id]=[p].[object_id] AND [i].[index_id]=[p].[index_id]
LEFT JOIN sys.columns AS [c] WITH (NOLOCK) ON [c].[object_id]=[p].[object_id] AND [c].[column_id]=[sg].[column_id]
WHERE 1=1'+@SchemaPredicateSch+@ObjectPredicateO+REPLACE(@FullObjectPredicateSO,N'[s].[name]',N'[sch].[name]')+N'
ORDER BY [sg].[on_disk_size] DESC OPTION (MAXDOP 1,RECOMPILE);';
     EXEC [sys].[sp_executesql] @Sql,N'@pDbName sysname,@pMaxRows bigint,@pSchemaLike nvarchar(256),@pObjectLike nvarchar(256)',@pDbName=@DbName,@pMaxRows=@EffectiveMaxZeilen,@pSchemaLike=@SchemaNameLike,@pObjectLike=@ObjectNameLike;
     SELECT @Rows=COUNT_BIG(*) FROM [#Columnstore_Segments] WHERE [DatabaseName]=@DbName;
     INSERT [#Columnstore_DatabaseStatus] VALUES(@DbName,'AVAILABLE',0,@Rows,N'VIEW DEFINITION; Detailspalten teilweise SELECT-abhängig',NULL,NULL,N'Quelle COLUMNSTORE_SEGMENTS erfolgreich gelesen.');
    END TRY
    BEGIN CATCH
     INSERT [#Columnstore_DatabaseStatus] VALUES(@DbName,CASE WHEN ERROR_NUMBER() IN (229,262,297,300,371,916) THEN 'DENIED_PERMISSION' WHEN ERROR_NUMBER()=1222 THEN 'TIMEOUT' WHEN ERROR_NUMBER() IN (207,208) THEN 'UNAVAILABLE_OBJECT' ELSE 'ERROR_HANDLED' END,1,0,N'VIEW DEFINITION',ERROR_NUMBER(),ERROR_MESSAGE(),N'Quelle COLUMNSTORE_SEGMENTS fehlgeschlagen; andere Teilquellen bleiben verwendbar.');
    END CATCH;
   END;

   IF @MitDictionaries=1
   BEGIN
    BEGIN TRY
     SET @Sql = N'SET LOCK_TIMEOUT ' + CONVERT(nvarchar(11), @LockTimeoutMs) + N'; USE ' + QUOTENAME(@DbName) + N';
INSERT #Columnstore_Dictionaries
SELECT TOP (@pMaxRows) @pDbName,[sch].[name],[o].[name],[i].[index_id],[p].[partition_number],[d].[column_id],[c].[name],[d].[dictionary_id],[d].[type],
 CASE [d].[type] WHEN 1 THEN ''INT_HASH'' WHEN 3 THEN ''STRING_HASH'' WHEN 4 THEN ''FLOAT_HASH'' ELSE ''UNKNOWN'' END,
 [d].[entry_count],CONVERT(decimal(19,4),[d].[on_disk_size]/1048576.0)
FROM sys.column_store_dictionaries AS [d] WITH (NOLOCK)
JOIN sys.partitions AS [p] WITH (NOLOCK) ON [p].[hobt_id]=[d].[hobt_id] AND [p].[partition_id]=[d].[partition_id]
JOIN sys.objects AS [o] WITH (NOLOCK) ON [o].[object_id]=[p].[object_id]
JOIN sys.schemas AS [sch] WITH (NOLOCK) ON [sch].[schema_id]=[o].[schema_id]
JOIN sys.indexes AS [i] WITH (NOLOCK) ON [i].[object_id]=[p].[object_id] AND [i].[index_id]=[p].[index_id]
LEFT JOIN sys.columns AS [c] WITH (NOLOCK) ON [c].[object_id]=[p].[object_id] AND [c].[column_id]=[d].[column_id]
WHERE 1=1'+@SchemaPredicateSch+@ObjectPredicateO+REPLACE(@FullObjectPredicateSO,N'[s].[name]',N'[sch].[name]')+N'
ORDER BY [d].[on_disk_size] DESC OPTION (MAXDOP 1,RECOMPILE);';
     EXEC [sys].[sp_executesql] @Sql,N'@pDbName sysname,@pMaxRows bigint,@pSchemaLike nvarchar(256),@pObjectLike nvarchar(256)',@pDbName=@DbName,@pMaxRows=@EffectiveMaxZeilen,@pSchemaLike=@SchemaNameLike,@pObjectLike=@ObjectNameLike;
     SELECT @Rows=COUNT_BIG(*) FROM [#Columnstore_Dictionaries] WHERE [DatabaseName]=@DbName;
     INSERT [#Columnstore_DatabaseStatus] VALUES(@DbName,'AVAILABLE',0,@Rows,N'VIEW DEFINITION; EntryCount zusätzlich SELECT-abhängig',NULL,NULL,N'Quelle COLUMNSTORE_DICTIONARIES erfolgreich gelesen.');
    END TRY
    BEGIN CATCH
     INSERT [#Columnstore_DatabaseStatus] VALUES(@DbName,CASE WHEN ERROR_NUMBER() IN (229,262,297,300,371,916) THEN 'DENIED_PERMISSION' WHEN ERROR_NUMBER()=1222 THEN 'TIMEOUT' WHEN ERROR_NUMBER() IN (207,208) THEN 'UNAVAILABLE_OBJECT' ELSE 'ERROR_HANDLED' END,1,0,N'VIEW DEFINITION',ERROR_NUMBER(),ERROR_MESSAGE(),N'Quelle COLUMNSTORE_DICTIONARIES fehlgeschlagen; andere Teilquellen bleiben verwendbar.');
    END CATCH;
   END;

   FETCH NEXT FROM dbcur INTO @DbId,@DbName;
  END;
  CLOSE dbcur; DEALLOCATE dbcur;
  IF NOT EXISTS(SELECT 1 FROM [#Columnstore_DatabaseStatus])
   INSERT [#Columnstore_DatabaseStatus] VALUES(@DatabaseName,'DATABASE_UNAVAILABLE',1,0,NULL,NULL,N'Keine sichtbare Online-Zieldatenbank gefunden.',NULL);
 END;



    SELECT @TotalRows=(SELECT COUNT_BIG(*) FROM [#Columnstore_Result])+(SELECT COUNT_BIG(*) FROM [#Columnstore_Physical])+(SELECT COUNT_BIG(*) FROM [#Columnstore_Segments])+(SELECT COUNT_BIG(*) FROM [#Columnstore_Dictionaries]);

    IF @OverallStatus = 'AVAILABLE'
    BEGIN
        IF EXISTS (SELECT 1 FROM [#Columnstore_DatabaseStatus] WHERE [StatusCode] NOT IN ('AVAILABLE','AVAILABLE_LIMITED','SKIPPED','NOT_APPLICABLE'))
        BEGIN
            SET @OverallStatus = CASE WHEN @TotalRows > 0 THEN 'PARTIAL' ELSE (SELECT TOP (1) [StatusCode] FROM [#Columnstore_DatabaseStatus] WHERE [StatusCode] NOT IN ('AVAILABLE','AVAILABLE_LIMITED','SKIPPED','NOT_APPLICABLE') ORDER BY [DatabaseName]) END;
            SET @IsPartial = 1;
        END
        ELSE IF EXISTS (SELECT 1 FROM [#Columnstore_DatabaseStatus] WHERE [StatusCode] IN ('AVAILABLE_LIMITED','SKIPPED','NOT_APPLICABLE'))
        BEGIN
            SET @OverallStatus = CASE WHEN @TotalRows > 0 THEN 'AVAILABLE_LIMITED' ELSE 'SKIPPED' END;
            SET @IsPartial = 1;
        END;
    END;

    IF @PrintMeldungen = 1 AND @OverallStatus <> 'AVAILABLE'
        BEGIN
    SET @MonitorPrintMessage = FORMATMESSAGE(N'WARNUNG %s: %s', @OverallStatus, COALESCE(@ErrorMessage, @Detail, N'Teilergebnis oder eingeschränkte Sicht'));
    RAISERROR(N'%s', 10, 1, @MonitorPrintMessage) WITH NOWAIT;
END;

    IF @ResultSetArtNormalisiert<>'NONE' BEGIN
        SELECT @ModuleName [ModuleName],@CollectionTimeUtc [CollectionTimeUtc],@OverallStatus [StatusCode],@IsPartial [IsPartial],@TotalRows [RowCount],@ErrorNumber [ErrorNumber],@ErrorMessage [ErrorMessage],@Detail [Detail];
        SELECT [DatabaseName],[StatusCode],[IsPartial],[RowCount],[RequiredPermission],[ErrorNumber],[ErrorMessage],[Detail] FROM [#Columnstore_DatabaseStatus] ORDER BY [DatabaseName];
        IF @ResultSetArtNormalisiert='RAW' SELECT * FROM [#Columnstore_Result] ORDER BY [DeletedPercent] DESC,[DatabaseName],[SchemaName],[ObjectName],[IndexId],[PartitionNumber],[RowGroupId]; ELSE SELECT N'Columnstore Rowgroup' [Ergebnis],[r].* FROM [#Columnstore_Result] [r] ORDER BY [DeletedPercent] DESC,[DatabaseName],[SchemaName],[ObjectName],[IndexId],[PartitionNumber],[RowGroupId];
        IF @ResultSetArtNormalisiert='RAW' SELECT * FROM [#Columnstore_Physical] ORDER BY [DeletedPercent] DESC,[DatabaseName],[SchemaName],[ObjectName],[IndexId],[PartitionNumber],[RowGroupId]; ELSE SELECT N'Columnstore Rowgroup' [Ergebnis],[r].* FROM [#Columnstore_Physical] [r] ORDER BY [DeletedPercent] DESC,[DatabaseName],[SchemaName],[ObjectName],[IndexId],[PartitionNumber],[RowGroupId];
        IF @ResultSetArtNormalisiert='RAW' SELECT * FROM [#Columnstore_Segments] ORDER BY [OnDiskSizeMb] DESC,[DatabaseName],[SchemaName],[ObjectName],[IndexId],[PartitionNumber],[RowGroupId],[ColumnId]; ELSE SELECT N'Columnstore Rowgroup' [Ergebnis],[r].* FROM [#Columnstore_Segments] [r] ORDER BY [OnDiskSizeMb] DESC,[DatabaseName],[SchemaName],[ObjectName],[IndexId],[PartitionNumber],[RowGroupId],[ColumnId];
        IF @ResultSetArtNormalisiert='RAW' SELECT * FROM [#Columnstore_Dictionaries] ORDER BY [OnDiskSizeMb] DESC,[DatabaseName],[SchemaName],[ObjectName],[IndexId],[PartitionNumber],[ColumnId],[DictionaryId]; ELSE SELECT N'Columnstore Rowgroup' [Ergebnis],[r].* FROM [#Columnstore_Dictionaries] [r] ORDER BY [OnDiskSizeMb] DESC,[DatabaseName],[SchemaName],[ObjectName],[IndexId],[PartitionNumber],[ColumnId],[DictionaryId];
    END;
    IF @JsonErzeugen=1 BEGIN
        DECLARE @JsonMeta nvarchar(max)=(SELECT @ModuleName [resultName],1 [schemaVersion],@CollectionTimeUtc [generatedAtUtc],@OverallStatus [statusCode],@IsPartial [isPartial],@TotalRows [rowCount] FOR JSON PATH,WITHOUT_ARRAY_WRAPPER,INCLUDE_NULL_VALUES);
        DECLARE @JsonDatabaseStatus nvarchar(max)=(SELECT * FROM [#Columnstore_DatabaseStatus] ORDER BY [DatabaseName] FOR JSON PATH,INCLUDE_NULL_VALUES);
        DECLARE @JsonData1 nvarchar(max)=(SELECT * FROM [#Columnstore_Result] ORDER BY [DeletedPercent] DESC,[DatabaseName],[SchemaName],[ObjectName],[IndexId],[PartitionNumber],[RowGroupId] FOR JSON PATH,INCLUDE_NULL_VALUES);
        DECLARE @JsonData2 nvarchar(max)=(SELECT * FROM [#Columnstore_Physical] ORDER BY [DeletedPercent] DESC,[DatabaseName],[SchemaName],[ObjectName],[IndexId],[PartitionNumber],[RowGroupId] FOR JSON PATH,INCLUDE_NULL_VALUES);
        DECLARE @JsonData3 nvarchar(max)=(SELECT * FROM [#Columnstore_Segments] ORDER BY [OnDiskSizeMb] DESC,[DatabaseName],[SchemaName],[ObjectName],[IndexId],[PartitionNumber],[RowGroupId],[ColumnId] FOR JSON PATH,INCLUDE_NULL_VALUES);
        DECLARE @JsonData4 nvarchar(max)=(SELECT * FROM [#Columnstore_Dictionaries] ORDER BY [OnDiskSizeMb] DESC,[DatabaseName],[SchemaName],[ObjectName],[IndexId],[PartitionNumber],[ColumnId],[DictionaryId] FOR JSON PATH,INCLUDE_NULL_VALUES);
        SET @Json=CONCAT(N'{"meta":',COALESCE(@JsonMeta,N'{}'),N',"rowgroups":',COALESCE(@JsonData1,N'[]'),N',"physicalStats":',COALESCE(@JsonData2,N'[]'),N',"segments":',COALESCE(@JsonData3,N'[]'),N',"dictionaries":',COALESCE(@JsonData4,N'[]'),N',"databaseStatus":',COALESCE(@JsonDatabaseStatus,N'[]'),N'}');
    END;
    IF @ConsoleResultRequested = 1
    BEGIN
        EXEC [monitor].[InternalEmitConsoleResult]
              @SourceTable=N'#Columnstore_Result'
            , @ResultLabel=N'Columnstore'
            , @EmptyMessage=N'Keine fachlichen Ergebnisse';
    END;
    IF @TableResultRequested = 1
    BEGIN
        EXEC [monitor].[InternalWriteResultTable]
              @SourceTable = N'#Columnstore_Result'
            , @TargetTable=@TableTarget
            , @ThrowOnError = 1;
    END;
END;
GO
-- END SOURCE: Code/03_ObjectIndex/060_USP_Columnstore.sql

-- BEGIN SOURCE: Code/03_ObjectIndex/070_USP_IndexPhysicalStats.sql
/*
===============================================================================
Objekt       : monitor.USP_IndexPhysicalStats
Version      : 1.1.0
Stand        : 2026-07-14
Typ          : Stored Procedure
Zweck        : Führt eine bewusst aktivierte und gruppengeschützte Physical-Stats-Analyse für Rowstore-Indizes/Heaps durch; LIMITED ist Default, SAMPLED/DETAILED sind explizit.
SQL-Version  : SQL Server 2019 oder neuer.
Datenquellen : sys.dm_db_index_physical_stats sowie je Datenbank sys.objects, sys.schemas und sys.indexes.
Parameter    :
  @DatabaseName                  sysname        = NULL  - Zieldatenbank; bei Einzelmodus Pflicht.
  @CrossDatabaseRequestedInternal               bit            = 0     - sichtbare Online-Datenbanken analysieren.
  @SystemdatenbankenEinbeziehen  bit            = 0     - master/model/msdb/tempdb einbeziehen.
  @DatenbankNameLike             nvarchar(256)  = NULL  - Filter im Cross-Database-Modus.
  @SchemaNamePattern                nvarchar(256)  = NULL  - GEZIELT: exakter Schemaname; VOLL: LIKE.
  @ObjectNamePattern                nvarchar(256)  = NULL  - GEZIELT: exakter Objektname; VOLL: LIKE.
  @MaxZeilen                     int            = 10000 - positive Werte begrenzen; NULL/0 = unbegrenzt.
  @LockTimeoutMs                 int            = 0     - 0 = nicht auf Metadatenlocks warten.
  @PrintMeldungen                bit            = 1     - Warnungen via RAISERROR 10.
  @Hilfe                         bit            = 0     - Hilfe via PRINT, keine Analyse.
  @AnalyseModus varchar(16)='GEZIELT' - GEZIELT genau ein Objekt; VOLL erlaubt LIKE-/Breitenscan.
  @ScanMode varchar(16)='LIMITED' - LIMITED|SAMPLED|DETAILED.
  @IndexNamePattern nvarchar(256)=NULL - Indexfilter.
  @MinPageCount bigint=1000 - kleine Strukturen ausblenden.
  @MinFragmentationPercent decimal(9,2)=0 - Filter.
  @PartitionNumber int=NULL - einzelne Partition.
  @IndexId int=NULL - einzelner Index.
Resultsets   : 1. Modulstatus. 2. Status je Datenbank. 3. Physical-Stats-Ergebnisse.
Berechtigung : Immer PHYSICAL_STATS_DEEP; Cross-Database zusätzlich CROSS_DATABASE_DEEP. SQL 2019 VIEW DATABASE STATE bzw. CONTROL am Objekt; SQL 2022+ VIEW DATABASE PERFORMANCE STATE.
Eigenlast    : GEZIELT übergibt genau eine sicher aufgelöste object_id. VOLL kann breit lesen. LIMITED kann bereits relevant sein; SAMPLED/DETAILED können hohe I/O-/CPU-Kosten erzeugen. TOP filtert erst nach DMF-Ausführung.
Locking      : DMF kann IS-Locks auf Metadaten/Objekten anfordern; LOCK_TIMEOUT begrenzt Warten. Keine automatische Wartung.
Partial      : Fehler je Datenbank bzw. Teilquelle werden isoliert; vorhandene
               Teilergebnisse bleiben erhalten. Das Framework vergibt keine Rechte.
Beispiele    :
  EXEC monitor.USP_IndexPhysicalStats @DatabaseNames=N'SampleDatabase', @SchemaNamePattern=N'dbo', @ObjectNamePattern=N'FactSales';
  EXEC monitor.USP_IndexPhysicalStats @DatabaseNames=N'SampleDatabase', @AnalyseModus='VOLL', @ObjectNamePattern=N'Fact%', @ScanMode='SAMPLED', @MinPageCount=10000;
  EXEC monitor.USP_IndexPhysicalStats @Hilfe=1;
Änderungen   : 1.1.0 - GEZIELT als sicherer Default; fehlende exakte Objektauflösung löst keinen Datenbank-Wildcardscan aus.
               1.0.0 - Erstfassung Phase 2.
===============================================================================
*/
CREATE OR ALTER PROCEDURE [monitor].[USP_IndexPhysicalStats]
      @DatabaseNames                  nvarchar(max)  = NULL
    , @SystemdatenbankenEinbeziehen   bit            = 0
    , @DatabaseNamePattern            nvarchar(4000) = NULL
    , @HighImpactConfirmed              bit            = 0
    , @SchemaNames                    nvarchar(max)  = NULL
    , @SchemaNamePattern              nvarchar(4000) = NULL
    , @ObjectNames                    nvarchar(max)  = NULL
    , @ObjectNamePattern              nvarchar(4000) = NULL
    , @FullObjectNames                nvarchar(max)  = NULL
    , @IndexNames                     nvarchar(max)  = NULL
    , @IndexNamePattern               nvarchar(4000) = NULL
    , @AnalyseModus                   varchar(16)   = 'GEZIELT'
    , @ScanMode                       varchar(16)   = 'LIMITED'
    , @IndexId                        int           = NULL
    , @PartitionNumber                int           = NULL
    , @MinPageCount                   bigint        = 1000
    , @MinFragmentationPercent        decimal(9,2)  = 0
    , @MaxZeilen                      int           = 10000
    , @LockTimeoutMs                  int           = 0
    , @ResultSetArt                  varchar(16)    = 'CONSOLE'
    , @ResultTablesJson               nvarchar(max) = NULL
    , @JsonErzeugen                  bit            = 0
    , @Json                          nvarchar(max)  = NULL OUTPUT
    , @PrintMeldungen                 bit           = 1
    , @Hilfe                          bit           = 0
AS
BEGIN
 SET NOCOUNT ON;

    SET @Json = NULL;
    DECLARE @ResultSetArtNormalisiert varchar(16)=UPPER(LTRIM(RTRIM(COALESCE(@ResultSetArt,''))));
    DECLARE @TableResultRequested bit = CASE WHEN @ResultSetArtNormalisiert = 'TABLE' THEN 1 ELSE 0 END;
    DECLARE @ConsoleResultRequested bit = CASE WHEN @ResultSetArtNormalisiert = 'CONSOLE' THEN 1 ELSE 0 END;
    DECLARE @TableTarget sysname=NULL;
    IF @TableResultRequested=0 AND NULLIF(LTRIM(RTRIM(COALESCE(@ResultTablesJson,N''))),N'') IS NOT NULL THROW 51011,N'@ResultTablesJson ist ausschließlich mit @ResultSetArt=TABLE zulässig.',1;
    IF @TableResultRequested=1 EXEC [monitor].[InternalPrepareSingleResultTable] @ResultTablesJson=@ResultTablesJson,@ResultName=N'indexPhysicalStats',@TargetTable=@TableTarget OUTPUT,@ThrowOnError=1;
    IF @TableResultRequested = 1 OR @ConsoleResultRequested = 1 SET @ResultSetArtNormalisiert = 'NONE';
    DECLARE @DatabaseName sysname=NULL,@CrossDatabaseRequestedInternal bit=0,@DatenbankNameLike nvarchar(4000)=NULL;
    DECLARE @SchemaNameLike nvarchar(4000)=NULL,@ObjectNameLike nvarchar(4000)=NULL;
    DECLARE @IndexNameLike nvarchar(4000)=NULL;
    DECLARE @SchemaPatternMode varchar(8),@SchemaPatternValue nvarchar(4000),@SchemaRegexFlags varchar(8),@SchemaPatternValid bit;
    DECLARE @ObjectPatternMode varchar(8),@ObjectPatternValue nvarchar(4000),@ObjectRegexFlags varchar(8),@ObjectPatternValid bit;
    SELECT @SchemaPatternMode=[PatternMode],@SchemaPatternValue=[PatternValue],@SchemaRegexFlags=[RegexFlags],@SchemaPatternValid=[IsValid] FROM [monitor].[TVF_ParsePattern](@SchemaNamePattern);
    SELECT @ObjectPatternMode=[PatternMode],@ObjectPatternValue=[PatternValue],@ObjectRegexFlags=[RegexFlags],@ObjectPatternValid=[IsValid] FROM [monitor].[TVF_ParsePattern](@ObjectNamePattern);
    IF @SchemaPatternMode='LIKE' SET @SchemaNameLike=@SchemaPatternValue;
    IF @ObjectPatternMode='LIKE' SET @ObjectNameLike=@ObjectPatternValue;
    DECLARE @IndexPatternMode varchar(8),@IndexPatternValue nvarchar(4000),@IndexRegexFlags varchar(8),@IndexPatternValid bit;
    SELECT @IndexPatternMode=[PatternMode],@IndexPatternValue=[PatternValue],@IndexRegexFlags=[RegexFlags],@IndexPatternValid=[IsValid] FROM [monitor].[TVF_ParsePattern](@IndexNamePattern);
    IF @IndexPatternMode='LIKE' SET @IndexNameLike=@IndexPatternValue;
    DECLARE @StatisticsPatternMode varchar(8)='NONE',@StatisticsPatternValue nvarchar(4000)=NULL,@StatisticsRegexFlags varchar(8)=NULL,@StatisticsPatternValid bit=1;
    DECLARE @DatabaseListCount int=0;
    IF @DatabaseNames IS NOT NULL AND NULLIF(LTRIM(RTRIM(@DatabaseNames)),N'') IS NOT NULL
        SELECT @DatabaseListCount=COUNT(*),@DatabaseName=MIN([NameValue]) FROM [monitor].[TVF_ParseSqlNameList](@DatabaseNames) WHERE [IsValid]=1;
    SET @CrossDatabaseRequestedInternal=CONVERT(bit,CASE WHEN @DatabaseNames IS NULL OR @DatabaseNamePattern IS NOT NULL OR @DatabaseListCount>1 THEN 1 ELSE 0 END);
    SELECT @DatenbankNameLike=CASE WHEN [PatternMode]='LIKE' THEN [PatternValue] END FROM [monitor].[TVF_ParsePattern](@DatabaseNamePattern);
    CREATE TABLE [#IndexPhysicalStats_NameFilters]([FilterType] varchar(20) COLLATE SQL_Latin1_General_CP1_CS_AS NOT NULL,[ItemOrdinal] int NOT NULL,[NameValue] sysname COLLATE SQL_Latin1_General_CP1_CS_AS NULL,[DatabaseName] sysname COLLATE SQL_Latin1_General_CP1_CS_AS NULL,[SchemaName] sysname COLLATE SQL_Latin1_General_CP1_CS_AS NULL,[ObjectName] sysname COLLATE SQL_Latin1_General_CP1_CS_AS NULL);
    CREATE TABLE [#IndexPhysicalStats_DatabaseCandidates]([DatabaseId] int NOT NULL,[DatabaseName] sysname NOT NULL,[StateDesc] nvarchar(60),[UserAccessDesc] nvarchar(60),[IsReadOnly] bit,[CompatibilityLevel] tinyint,[CollationName] sysname,[RecoveryModelDesc] nvarchar(60),[IsSystemDatabase] bit,[RequestedOrdinal] int);
    DECLARE @FilterStatus varchar(40)='AVAILABLE',@FilterError nvarchar(2048)=NULL,@CrossDatabaseRequested bit=0;
    EXEC [monitor].[USP_PrepareNameFilters] @SchemaNames=@SchemaNames,@ObjectNames=@ObjectNames,@FullObjectNames=@FullObjectNames,@IndexNames=@IndexNames,@StatisticsNames=NULL,@ColumnNames=NULL,@StatusCode=@FilterStatus OUTPUT,@ErrorMessage=@FilterError OUTPUT,@FilterTable=N'#IndexPhysicalStats_NameFilters';
    IF @FilterStatus='AVAILABLE' EXEC [monitor].[USP_PrepareDatabaseCandidates] @DatabaseNames=@DatabaseNames,@SystemdatenbankenEinbeziehen=@SystemdatenbankenEinbeziehen,@DatabaseNamePattern=@DatabaseNamePattern,@HighImpactConfirmed=@HighImpactConfirmed,@AnalysisClass='PHYSICAL_STATS_DEEP',@StatusCode=@FilterStatus OUTPUT,@ErrorMessage=@FilterError OUTPUT,@CrossDatabaseRequested=@CrossDatabaseRequested OUTPUT,@CandidateTable=N'#IndexPhysicalStats_DatabaseCandidates';
    DECLARE @SchemaPredicateS nvarchar(max),@SchemaPredicateSch nvarchar(max),@ObjectPredicateO nvarchar(max),@FullObjectPredicateSO nvarchar(max),@IndexPredicateI nvarchar(max),@StatisticsPredicateSt nvarchar(max);
    SET @SchemaPredicateS=N' AND (NOT EXISTS(SELECT 1 FROM [#IndexPhysicalStats_NameFilters] WHERE [FilterType]=''SCHEMA'') OR EXISTS(SELECT 1 FROM [#IndexPhysicalStats_NameFilters] [f] WHERE [f].[FilterType]=''SCHEMA'' AND [f].[NameValue]=[s].[name] COLLATE SQL_Latin1_General_CP1_CS_AS))';
    SET @SchemaPredicateSch=REPLACE(@SchemaPredicateS,N'[s].[name]',N'[sch].[name]');
    SET @ObjectPredicateO=N' AND (NOT EXISTS(SELECT 1 FROM [#IndexPhysicalStats_NameFilters] WHERE [FilterType]=''OBJECT'') OR EXISTS(SELECT 1 FROM [#IndexPhysicalStats_NameFilters] [f] WHERE [f].[FilterType]=''OBJECT'' AND [f].[NameValue]=[o].[name] COLLATE SQL_Latin1_General_CP1_CS_AS))';
    SET @FullObjectPredicateSO=N' AND (NOT EXISTS(SELECT 1 FROM [#IndexPhysicalStats_NameFilters] WHERE [FilterType]=''FULL_OBJECT'') OR EXISTS(SELECT 1 FROM [#IndexPhysicalStats_NameFilters] [f] WHERE [f].[FilterType]=''FULL_OBJECT'' AND ([f].[DatabaseName] IS NULL OR [f].[DatabaseName]=@pDbName COLLATE SQL_Latin1_General_CP1_CS_AS) AND ([f].[SchemaName] IS NULL OR [f].[SchemaName]=[s].[name] COLLATE SQL_Latin1_General_CP1_CS_AS) AND [f].[ObjectName]=[o].[name] COLLATE SQL_Latin1_General_CP1_CS_AS))';
    SET @IndexPredicateI=N' AND (NOT EXISTS(SELECT 1 FROM [#IndexPhysicalStats_NameFilters] WHERE [FilterType]=''INDEX'') OR EXISTS(SELECT 1 FROM [#IndexPhysicalStats_NameFilters] [f] WHERE [f].[FilterType]=''INDEX'' AND [f].[NameValue]=[i].[name] COLLATE SQL_Latin1_General_CP1_CS_AS))';
    SET @StatisticsPredicateSt=N' AND (NOT EXISTS(SELECT 1 FROM [#IndexPhysicalStats_NameFilters] WHERE [FilterType]=''STATISTICS'') OR EXISTS(SELECT 1 FROM [#IndexPhysicalStats_NameFilters] [f] WHERE [f].[FilterType]=''STATISTICS'' AND [f].[NameValue]=[st].[name] COLLATE SQL_Latin1_General_CP1_CS_AS))';
    IF @SchemaPatternMode='LIKE' BEGIN SET @SchemaPredicateS+=N' AND [s].[name] COLLATE SQL_Latin1_General_CP1_CS_AS LIKE N'''+REPLACE(@SchemaPatternValue,N'''',N'''''')+N''' COLLATE SQL_Latin1_General_CP1_CS_AS';SET @SchemaPredicateSch+=N' AND [sch].[name] COLLATE SQL_Latin1_General_CP1_CS_AS LIKE N'''+REPLACE(@SchemaPatternValue,N'''',N'''''')+N''' COLLATE SQL_Latin1_General_CP1_CS_AS';END;
    IF @SchemaPatternMode IN('REGEX','REGEXI') BEGIN SET @SchemaPredicateS+=N' AND REGEXP_LIKE([s].[name],N'''+REPLACE(@SchemaPatternValue,N'''',N'''''')+N''','''+@SchemaRegexFlags+N''')';SET @SchemaPredicateSch+=N' AND REGEXP_LIKE([sch].[name],N'''+REPLACE(@SchemaPatternValue,N'''',N'''''')+N''','''+@SchemaRegexFlags+N''')';END;
    IF @ObjectPatternMode='LIKE' SET @ObjectPredicateO+=N' AND [o].[name] COLLATE SQL_Latin1_General_CP1_CS_AS LIKE N'''+REPLACE(@ObjectPatternValue,N'''',N'''''')+N''' COLLATE SQL_Latin1_General_CP1_CS_AS';
    IF @ObjectPatternMode IN('REGEX','REGEXI') SET @ObjectPredicateO+=N' AND REGEXP_LIKE([o].[name],N'''+REPLACE(@ObjectPatternValue,N'''',N'''''')+N''','''+@ObjectRegexFlags+N''')';
    IF @IndexPatternMode='LIKE' SET @IndexPredicateI+=N' AND [i].[name] COLLATE SQL_Latin1_General_CP1_CS_AS LIKE N'''+REPLACE(@IndexPatternValue,N'''',N'''''')+N''' COLLATE SQL_Latin1_General_CP1_CS_AS';
    IF @IndexPatternMode IN('REGEX','REGEXI') SET @IndexPredicateI+=N' AND REGEXP_LIKE([i].[name],N'''+REPLACE(@IndexPatternValue,N'''',N'''''')+N''','''+@IndexRegexFlags+N''')';
    IF @StatisticsPatternMode='LIKE' SET @StatisticsPredicateSt+=N' AND [st].[name] COLLATE SQL_Latin1_General_CP1_CS_AS LIKE N'''+REPLACE(@StatisticsPatternValue,N'''',N'''''')+N''' COLLATE SQL_Latin1_General_CP1_CS_AS';
    IF @StatisticsPatternMode IN('REGEX','REGEXI') SET @StatisticsPredicateSt+=N' AND REGEXP_LIKE([st].[name],N'''+REPLACE(@StatisticsPatternValue,N'''',N'''''')+N''','''+@StatisticsRegexFlags+N''')';
    DECLARE @EffectiveMaxZeilen bigint = CASE WHEN @MaxZeilen IS NULL OR @MaxZeilen=0 THEN CONVERT(bigint,9223372036854775807) ELSE CONVERT(bigint,@MaxZeilen) END;
    DECLARE @MonitorPrintMessage nvarchar(2048); SET @AnalyseModus=UPPER(LTRIM(RTRIM(COALESCE(@AnalyseModus,'GEZIELT')))); SET @ScanMode=UPPER(LTRIM(RTRIM(COALESCE(@ScanMode,'LIMITED'))));
 IF @Hilfe=1
 BEGIN
        PRINT N'monitor.USP_IndexPhysicalStats';        PRINT N'@DatabaseNames: exakter Name oder bracket-aware Pipe-Liste; NULL = alle zulässigen Datenbanken; N'''' = keine Einschränkung.';        PRINT N'@SystemdatenbankenEinbeziehen bit = 0: Systemdatenbanken einbeziehen.';
        PRINT N'@DatenbankNameLike: optionaler Cross-Database-LIKE-Filter.';
        PRINT N'@SchemaNamePattern/@ObjectNamePattern: GEZIELT beide als exakte Equality-Namen; VOLL als optionale LIKE-Filter.';
        PRINT N'Datenbankauswahl ohne Vorabbegrenzung; @MaxZeilen int = 10000: harte Ergebnismengenbegrenzung.';
        PRINT N'@LockTimeoutMs int = 0: Metadatenzugriff wartet standardmäßig nicht auf Locks.';
        PRINT N'@PrintMeldungen bit = 1: strukturierte Warnungen zusätzlich in der Console.';
        PRINT N'Die Procedure liefert Physical Stats für Rowstore-Indizes und Heaps, führt jedoch keine Wartungsaktion aus.';
        PRINT N'@IndexNamePattern nvarchar(256) = NULL: optionaler Indexfilter.';
        PRINT N'@AnalyseModus varchar(16) = GEZIELT: exakt ein Objekt; VOLL erlaubt LIKE-/Breitenscan. Beide Modi prüfen PHYSICAL_STATS_DEEP.';
        PRINT N'@ScanMode: LIMITED, SAMPLED oder DETAILED. DETAILED ist besonders kostenintensiv.';
        PRINT N'@IndexId/@PartitionNumber: optionale technische Eingrenzung.';
        PRINT N'@MinPageCount: Default 1000; Filter wird auf DMF-Ergebnis angewandt.';
        PRINT N'@MinFragmentationPercent: 0 bis 100.';
        PRINT N'Immer PHYSICAL_STATS_DEEP; Cross-Database prüft zusätzlich CROSS_DATABASE_DEEP.';
        PRINT N'@Hilfe bit = 0: 1 zeigt diese Hilfe und führt keine Analyse aus.';
        RETURN;
 END;

    DECLARE @ModuleName sysname = N'USP_IndexPhysicalStats';
    DECLARE @CollectionTimeUtc datetime2(3) = SYSUTCDATETIME();

    DECLARE @OverallStatus varchar(40) = 'AVAILABLE';
    DECLARE @IsPartial bit = 0;
    DECLARE @TotalRows bigint = 0;
    DECLARE @ErrorNumber int = NULL;
    DECLARE @ErrorMessage nvarchar(2048) = NULL;
    DECLARE @Detail nvarchar(2000) = NULL;

    CREATE TABLE [#IndexPhysicalStats_DatabaseStatus]
    (
          [DatabaseName]       sysname        NULL
        , [StatusCode]         varchar(40)    NOT NULL
        , [IsPartial]          bit            NOT NULL
        , [RowCount]           bigint         NOT NULL
        , [RequiredPermission] nvarchar(256)  NULL
        , [ErrorNumber]        int            NULL
        , [ErrorMessage]       nvarchar(2048) NULL
        , [Detail]             nvarchar(2000) NULL
    );

    IF @FilterStatus<>'AVAILABLE' BEGIN SET @OverallStatus=@FilterStatus;SET @ErrorMessage=@FilterError;END;
    IF @ResultSetArtNormalisiert NOT IN('RAW','CONSOLE','NONE') BEGIN SET @OverallStatus='INVALID_PARAMETER';SET @ErrorMessage=N'@ResultSetArt muss CONSOLE, RAW, TABLE oder NONE enthalten.';END;
    IF @SchemaPatternValid=0 OR @ObjectPatternValid=0 OR @IndexPatternValid=0 OR @StatisticsPatternValid=0 OR (@SchemaNames IS NOT NULL AND @SchemaNamePattern IS NOT NULL) OR (@ObjectNames IS NOT NULL AND @ObjectNamePattern IS NOT NULL) OR (@IndexNames IS NOT NULL AND @IndexNamePattern IS NOT NULL) BEGIN SET @OverallStatus='INVALID_PARAMETER';SET @ErrorMessage=N'Exakte Liste und Pattern derselben Eigenschaft sind gegenseitig exklusiv.';END;
IF @MaxZeilen<0 OR @LockTimeoutMs NOT BETWEEN 0 AND 60000
    BEGIN
        SET @OverallStatus = 'INVALID_PARAMETER';
        SET @ErrorMessage = N'Ungültiger Parameter: @MaxZeilen oder @LockTimeoutMs außerhalb des zulässigen Bereichs.';
    END


    IF @OverallStatus <> 'AVAILABLE'
    BEGIN
        INSERT [#IndexPhysicalStats_DatabaseStatus]([DatabaseName], [StatusCode], [IsPartial], [RowCount], [RequiredPermission], [ErrorNumber], [ErrorMessage], [Detail])
        VALUES(@DatabaseName, @OverallStatus, 1, 0, NULL, NULL, @ErrorMessage, N'Keine Datenbankanalyse ausgeführt.');
        SET @IsPartial = 1;
    END
    ELSE
    BEGIN
        SET LOCK_TIMEOUT 0;
    END;

 DECLARE @PhysicalAllowed bit=0; SELECT @PhysicalAllowed=COALESCE(MAX(CONVERT(tinyint,[IsAllowed])),0) FROM [monitor].[VW_AnalyseAccessCurrent] WHERE [AnalysisClass]='PHYSICAL_STATS_DEEP';
 CREATE TABLE [#IndexPhysicalStats_Result]
 (
  [DatabaseName] sysname NOT NULL,[SchemaName] sysname NULL,[ObjectName] sysname NULL,[ObjectId] int NOT NULL,[IndexId] int NOT NULL,[IndexName] sysname NULL,[IndexTypeDesc] nvarchar(60) NULL,
  [PartitionNumber] int NULL,[IndexLevel] tinyint NULL,[AllocationUnitTypeDesc] nvarchar(60) NULL,[IndexDepth] tinyint NULL,[IndexTypeDescPhysical] nvarchar(60) NULL,
  [AvgFragmentationPercent] float NULL,[FragmentCount] bigint NULL,[AvgFragmentSizePages] float NULL,[PageCount] bigint NULL,[AvgPageSpaceUsedPercent] float NULL,
  [RecordCount] bigint NULL,[GhostRecordCount] bigint NULL,[VersionGhostRecordCount] bigint NULL,[MinRecordSizeBytes] int NULL,[MaxRecordSizeBytes] int NULL,[AvgRecordSizeBytes] float NULL,
  [ForwardedRecordCount] bigint NULL,[CompressedPageCount] bigint NULL,[ScanMode] varchar(16) NOT NULL
 );
 IF @OverallStatus='AVAILABLE' AND (@AnalyseModus NOT IN ('GEZIELT','VOLL') OR @ScanMode NOT IN ('LIMITED','SAMPLED','DETAILED') OR @MinPageCount<0 OR @MinFragmentationPercent<0 OR @MinFragmentationPercent>100 OR (@IndexId IS NOT NULL AND @IndexId<0) OR (@PartitionNumber IS NOT NULL AND @PartitionNumber<1))
 BEGIN SET @OverallStatus='INVALID_PARAMETER'; SET @ErrorMessage=N'Ungültige Physical-Stats-Parameter.'; INSERT [#IndexPhysicalStats_DatabaseStatus] VALUES(@DatabaseName,@OverallStatus,1,0,NULL,NULL,@ErrorMessage,NULL); END
 ELSE IF @OverallStatus='AVAILABLE' AND @AnalyseModus='GEZIELT' AND NOT EXISTS(SELECT 1 FROM [#IndexPhysicalStats_NameFilters] WHERE [FilterType]='FULL_OBJECT') AND (NOT EXISTS(SELECT 1 FROM [#IndexPhysicalStats_NameFilters] WHERE [FilterType]='SCHEMA') OR NOT EXISTS(SELECT 1 FROM [#IndexPhysicalStats_NameFilters] WHERE [FilterType]='OBJECT'))
 BEGIN SET @OverallStatus='INVALID_PARAMETER'; SET @ErrorMessage=N'GEZIELT benötigt exakte @SchemaNameLike- und @ObjectNameLike-Werte.'; INSERT [#IndexPhysicalStats_DatabaseStatus] VALUES(@DatabaseName,@OverallStatus,1,0,NULL,NULL,@ErrorMessage,NULL); END
 ELSE IF @OverallStatus='AVAILABLE' AND @PhysicalAllowed=0
 BEGIN SET @OverallStatus='DENIED_GROUP'; SET @ErrorMessage=N'PHYSICAL_STATS_DEEP ist nicht freigegeben.'; INSERT [#IndexPhysicalStats_DatabaseStatus] VALUES(@DatabaseName,@OverallStatus,1,0,NULL,NULL,@ErrorMessage,NULL); END
 ELSE IF @OverallStatus='AVAILABLE'
 BEGIN
  DECLARE @DbId int,@DbName sysname,@Sql nvarchar(max),@Rows bigint;
  DECLARE dbcur CURSOR LOCAL FAST_FORWARD FOR SELECT [DatabaseId],[DatabaseName] FROM [#IndexPhysicalStats_DatabaseCandidates];
  OPEN dbcur; FETCH NEXT FROM dbcur INTO @DbId,@DbName;
  WHILE @@FETCH_STATUS=0
  BEGIN
   BEGIN TRY
    SET @Sql = N'SET LOCK_TIMEOUT ' + CONVERT(nvarchar(11), @LockTimeoutMs) + N'; USE ' + QUOTENAME(@DbName) + N';
DECLARE @ObjectIdFilter int=NULL;
IF @pMode=''GEZIELT''
BEGIN
 SELECT @ObjectIdFilter=[o].[object_id]
 FROM sys.objects AS [o] WITH (NOLOCK)
 JOIN sys.schemas AS [s] WITH (NOLOCK) ON [s].[schema_id]=[o].[schema_id]
 WHERE [o].[type] IN (''U'',''V'')'+@SchemaPredicateS+@ObjectPredicateO+@FullObjectPredicateSO+N';
 IF @ObjectIdFilter IS NULL THROW 50001,N''Zielobjekt nicht gefunden oder nicht sichtbar; Physical Stats werden nicht mit NULL-Wildcard aufgerufen.'',1;
END;
INSERT #IndexPhysicalStats_Result
SELECT TOP (@pMaxRows) @pDbName,[s].[name],[o].[name],[ps].[object_id],[ps].[index_id],[i].[name],[i].[type_desc],[ps].[partition_number],[ps].[index_level],[ps].[alloc_unit_type_desc],[ps].[index_depth],[ps].[index_type_desc],
 [ps].[avg_fragmentation_in_percent],[ps].[fragment_count],[ps].[avg_fragment_size_in_pages],[ps].[page_count],[ps].[avg_page_space_used_in_percent],[ps].[record_count],[ps].[ghost_record_count],[ps].[version_ghost_record_count],
 [ps].[min_record_size_in_bytes],[ps].[max_record_size_in_bytes],[ps].[avg_record_size_in_bytes],[ps].[forwarded_record_count],[ps].[compressed_page_count],@pScanMode
FROM sys.dm_db_index_physical_stats(@pDbId,@ObjectIdFilter,@pIndexId,@pPartition,@pScanMode) AS [ps]
LEFT JOIN sys.objects AS [o] WITH (NOLOCK) ON [o].[object_id]=[ps].[object_id]
LEFT JOIN sys.schemas AS [s] WITH (NOLOCK) ON [s].[schema_id]=[o].[schema_id]
LEFT JOIN sys.indexes AS [i] WITH (NOLOCK) ON [i].[object_id]=[ps].[object_id] AND [i].[index_id]=[ps].[index_id]
WHERE [ps].[page_count]>=@pMinPages AND [ps].[avg_fragmentation_in_percent]>=@pMinFrag'+@SchemaPredicateS+@ObjectPredicateO+@FullObjectPredicateSO+@IndexPredicateI+N'
ORDER BY [ps].[page_count] DESC,[ps].[avg_fragmentation_in_percent] DESC
OPTION (MAXDOP 1,RECOMPILE);';
    EXEC [sys].[sp_executesql] @Sql,N'@pDbName sysname,@pDbId int,@pMode varchar(16),@pMaxRows bigint,@pSchemaLike nvarchar(256),@pObjectLike nvarchar(256),@pIndexLike nvarchar(256),@pScanMode varchar(16),@pIndexId int,@pPartition int,@pMinPages bigint,@pMinFrag decimal(9,2)',@pDbName=@DbName,@pDbId=@DbId,@pMode=@AnalyseModus,@pMaxRows=@EffectiveMaxZeilen,@pSchemaLike=@SchemaNameLike,@pObjectLike=@ObjectNameLike,@pIndexLike=@IndexNameLike,@pScanMode=@ScanMode,@pIndexId=@IndexId,@pPartition=@PartitionNumber,@pMinPages=@MinPageCount,@pMinFrag=@MinFragmentationPercent;
    SELECT @Rows=COUNT_BIG(*) FROM [#IndexPhysicalStats_Result] WHERE [DatabaseName]=@DbName; INSERT [#IndexPhysicalStats_DatabaseStatus] VALUES(@DbName,'AVAILABLE',0,@Rows,CASE WHEN TRY_CONVERT([int],SERVERPROPERTY(N'ProductMajorVersion'))>=16 THEN N'VIEW DATABASE PERFORMANCE STATE oder CONTROL am Objekt' ELSE N'VIEW DATABASE STATE oder CONTROL am Objekt' END,NULL,NULL,N'Physical Stats erfolgreich; ScanMode='+@ScanMode+N'.');
   END TRY
   BEGIN CATCH
    INSERT [#IndexPhysicalStats_DatabaseStatus] VALUES(@DbName,CASE WHEN ERROR_NUMBER()=50001 THEN 'UNAVAILABLE_OBJECT' WHEN ERROR_NUMBER() IN (229,262,297,300,371,916) THEN 'DENIED_PERMISSION' WHEN ERROR_NUMBER()=1222 THEN 'TIMEOUT' ELSE 'ERROR_HANDLED' END,1,0,CASE WHEN TRY_CONVERT([int],SERVERPROPERTY(N'ProductMajorVersion'))>=16 THEN N'VIEW DATABASE PERFORMANCE STATE oder CONTROL' ELSE N'VIEW DATABASE STATE oder CONTROL' END,ERROR_NUMBER(),ERROR_MESSAGE(),N'Physical-Stats-Fehler isoliert; übrige Datenbanken laufen weiter.');
   END CATCH;
   FETCH NEXT FROM dbcur INTO @DbId,@DbName;
  END; CLOSE dbcur; DEALLOCATE dbcur;
  IF NOT EXISTS(SELECT 1 FROM [#IndexPhysicalStats_DatabaseStatus]) INSERT [#IndexPhysicalStats_DatabaseStatus] VALUES(@DatabaseName,'DATABASE_UNAVAILABLE',1,0,NULL,NULL,N'Keine sichtbare Online-Zieldatenbank gefunden.',NULL);
 END;



    SELECT @TotalRows = COUNT_BIG(*) FROM [#IndexPhysicalStats_Result];

    IF @OverallStatus = 'AVAILABLE'
    BEGIN
        IF EXISTS (SELECT 1 FROM [#IndexPhysicalStats_DatabaseStatus] WHERE [StatusCode] NOT IN ('AVAILABLE','AVAILABLE_LIMITED','SKIPPED','NOT_APPLICABLE'))
        BEGIN
            SET @OverallStatus = CASE WHEN @TotalRows > 0 THEN 'PARTIAL' ELSE (SELECT TOP (1) [StatusCode] FROM [#IndexPhysicalStats_DatabaseStatus] WHERE [StatusCode] NOT IN ('AVAILABLE','AVAILABLE_LIMITED','SKIPPED','NOT_APPLICABLE') ORDER BY [DatabaseName]) END;
            SET @IsPartial = 1;
        END
        ELSE IF EXISTS (SELECT 1 FROM [#IndexPhysicalStats_DatabaseStatus] WHERE [StatusCode] IN ('AVAILABLE_LIMITED','SKIPPED','NOT_APPLICABLE'))
        BEGIN
            SET @OverallStatus = CASE WHEN @TotalRows > 0 THEN 'AVAILABLE_LIMITED' ELSE 'SKIPPED' END;
            SET @IsPartial = 1;
        END;
    END;

    IF @PrintMeldungen = 1 AND @OverallStatus <> 'AVAILABLE'
        BEGIN
    SET @MonitorPrintMessage = FORMATMESSAGE(N'WARNUNG %s: %s', @OverallStatus, COALESCE(@ErrorMessage, @Detail, N'Teilergebnis oder eingeschränkte Sicht'));
    RAISERROR(N'%s', 10, 1, @MonitorPrintMessage) WITH NOWAIT;
END;

    IF @ResultSetArtNormalisiert<>'NONE' BEGIN
        SELECT @ModuleName [ModuleName],@CollectionTimeUtc [CollectionTimeUtc],@OverallStatus [StatusCode],@IsPartial [IsPartial],@TotalRows [RowCount],@ErrorNumber [ErrorNumber],@ErrorMessage [ErrorMessage],@Detail [Detail];
        SELECT [DatabaseName],[StatusCode],[IsPartial],[RowCount],[RequiredPermission],[ErrorNumber],[ErrorMessage],[Detail] FROM [#IndexPhysicalStats_DatabaseStatus] ORDER BY [DatabaseName];
        IF @ResultSetArtNormalisiert='RAW' SELECT * FROM [#IndexPhysicalStats_Result] ORDER BY [PageCount] DESC,[AvgFragmentationPercent] DESC,[DatabaseName],[SchemaName],[ObjectName],[IndexId],[PartitionNumber]; ELSE SELECT N'Index Physical Stats' [Ergebnis],[r].* FROM [#IndexPhysicalStats_Result] [r] ORDER BY [PageCount] DESC,[AvgFragmentationPercent] DESC,[DatabaseName],[SchemaName],[ObjectName],[IndexId],[PartitionNumber];
    END;
    IF @JsonErzeugen=1 BEGIN
        DECLARE @JsonMeta nvarchar(max)=(SELECT @ModuleName [resultName],1 [schemaVersion],@CollectionTimeUtc [generatedAtUtc],@OverallStatus [statusCode],@IsPartial [isPartial],@TotalRows [rowCount] FOR JSON PATH,WITHOUT_ARRAY_WRAPPER,INCLUDE_NULL_VALUES);
        DECLARE @JsonDatabaseStatus nvarchar(max)=(SELECT * FROM [#IndexPhysicalStats_DatabaseStatus] ORDER BY [DatabaseName] FOR JSON PATH,INCLUDE_NULL_VALUES);
        DECLARE @JsonData1 nvarchar(max)=(SELECT * FROM [#IndexPhysicalStats_Result] ORDER BY [PageCount] DESC,[AvgFragmentationPercent] DESC,[DatabaseName],[SchemaName],[ObjectName],[IndexId],[PartitionNumber] FOR JSON PATH,INCLUDE_NULL_VALUES);
        SET @Json=CONCAT(N'{"meta":',COALESCE(@JsonMeta,N'{}'),N',"indexPhysicalStats":',COALESCE(@JsonData1,N'[]'),N',"databaseStatus":',COALESCE(@JsonDatabaseStatus,N'[]'),N'}');
    END;
    IF @ConsoleResultRequested = 1
    BEGIN
        EXEC [monitor].[InternalEmitConsoleResult]
              @SourceTable=N'#IndexPhysicalStats_Result'
            , @ResultLabel=N'IndexPhysicalStats'
            , @EmptyMessage=N'Keine fachlichen Ergebnisse';
    END;
    IF @TableResultRequested = 1
    BEGIN
        EXEC [monitor].[InternalWriteResultTable]
              @SourceTable = N'#IndexPhysicalStats_Result'
            , @TargetTable=@TableTarget
            , @ThrowOnError = 1;
    END;
END;
GO
-- END SOURCE: Code/03_ObjectIndex/070_USP_IndexPhysicalStats.sql

-- BEGIN SOURCE: Code/03_ObjectIndex/075_USP_VectorIndexAnalysis.sql
/*
===============================================================================
Objekt       : monitor.USP_VectorIndexAnalysis
Version      : 1.0.0
Stand        : 2026-07-23
Typ          : Stored Procedure
Zweck        : Inventarisiert sichtbare Vector-Indizes und korreliert deren
               aktuellen Hintergrundwartungszustand auf SQL Server 2025.
SQL-Version  : SQL Server 2019 oder neuer; Vector-Quellen ab Version 17.
Datenquellen : sys.vector_indexes und sys.dm_db_vector_indexes. Beide Quellen
               werden je Zieldatenbank höchstens einmal gelesen und erst nach
               einer versions- und schemasicheren Katalogprüfung referenziert.
Abgrenzung   : Keine Vector-Nutzdaten, keine internen build_parameters, keine
               DDL-, Rebuild-, Such- oder Wartungsaktion. Staleness ist ein
               flüchtiger Reviewindikator und kein alleiniger Rebuildnachweis.
Kosten       : LOW_TO_HIGH_OPT_IN. Kleine datenbanklokale Katalog-/DMV-Scans;
               breite Cross-Database-Scopes können High Impact werden.
===============================================================================
*/
CREATE OR ALTER PROCEDURE [monitor].[USP_VectorIndexAnalysis]
      @DatabaseNames                  nvarchar(max)  = NULL
    , @SystemdatenbankenEinbeziehen   bit            = 0
    , @DatabaseNamePattern            nvarchar(4000) = NULL
    , @HighImpactConfirmed            bit            = 0
    , @SchemaNames                    nvarchar(max)  = NULL
    , @SchemaNamePattern              nvarchar(4000) = NULL
    , @ObjectNames                    nvarchar(max)  = NULL
    , @ObjectNamePattern              nvarchar(4000) = NULL
    , @FullObjectNames                nvarchar(max)  = NULL
    , @IndexNames                     nvarchar(max)  = NULL
    , @IndexNamePattern               nvarchar(4000) = NULL
    , @StalenessReviewPercent         decimal(5,2)  = 15.00
    , @MaxZeilen                      int            = 2000
    , @LockTimeoutMs                  int            = 0
    , @ResultSetArt                   varchar(16)    = 'CONSOLE'
    , @ResultTablesJson               nvarchar(max)  = NULL
    , @JsonErzeugen                   bit            = 0
    , @Json                           nvarchar(max)  = NULL OUTPUT
    , @PrintMeldungen                 bit            = 1
    , @Hilfe                          bit            = 0
    , @StatusCodeOut                  varchar(40)    = NULL OUTPUT
    , @IsPartialOut                   bit            = NULL OUTPUT
    , @ErrorNumberOut                 int            = NULL OUTPUT
    , @ErrorMessageOut                nvarchar(2048) = NULL OUTPUT
AS
BEGIN
    SET NOCOUNT ON;
    SET @Json=NULL;

    DECLARE @CapturedAtUtc datetime2(3)=SYSUTCDATETIME();
    DECLARE @ProductMajorVersion int=TRY_CONVERT(int,SERVERPROPERTY(N'ProductMajorVersion'));
    DECLARE @OutputMode varchar(16)=UPPER(LTRIM(RTRIM(COALESCE(@ResultSetArt,''))));
    DECLARE @ConsoleResultRequested bit=CASE WHEN @OutputMode='CONSOLE' THEN 1 ELSE 0 END;
    DECLARE @StatusCode varchar(40)='AVAILABLE';
    DECLARE @IsPartial bit=0;
    DECLARE @ErrorNumber int=NULL;
    DECLARE @ErrorMessage nvarchar(2048)=NULL;
    DECLARE @CrossDatabaseRequested bit=0;
    DECLARE @Limit bigint=CASE WHEN @MaxZeilen IS NULL OR @MaxZeilen=0
                               THEN CONVERT(bigint,9223372036854775807)
                               ELSE CONVERT(bigint,@MaxZeilen) END;
    DECLARE @OriginalLockTimeout int = @@LOCK_TIMEOUT;
    DECLARE @LockTimeoutSql nvarchar(64);

    IF @Hilfe=1
    BEGIN
        PRINT N'monitor.USP_VectorIndexAnalysis';
        PRINT N'Ohne Datenbankfilter werden alle sichtbaren ONLINE-Benutzerdatenbanken geprüft.';
        PRINT N'Exakte Schema-, Objekt- und Indexfilter sind bracket-aware Pipe-Listen; Pattern verwenden like:, regex: oder regexi:.';
        PRINT N'@StalenessReviewPercent ist ein konfigurierbarer Review-Grenzwert von 0 bis 100; NULL deaktiviert nur dieses Finding.';
        PRINT N'Die Procedure liest keine Vector-Werte und führt weder Suche, Rebuild, DDL noch Wartung aus.';
        PRINT N'@ResultSetArt=CONSOLE|RAW|TABLE|NONE; TABLE-Namen: moduleStatus, vectorIndexes, maintenance, findings, sourceStatus, warnings.';
        RETURN;
    END;

    CREATE TABLE [#VectorIndexAnalysis_ResultTableMap]
    (
          [ResultName] sysname COLLATE SQL_Latin1_General_CP1_CS_AS NOT NULL PRIMARY KEY
        , [TargetTable] sysname COLLATE SQL_Latin1_General_CP1_CS_AS NOT NULL UNIQUE
    );
    CREATE TABLE [#VectorIndexAnalysis_DatabaseCandidates]
    (
          [DatabaseId] int NOT NULL PRIMARY KEY
        , [DatabaseName] sysname COLLATE SQL_Latin1_General_CP1_CS_AS NOT NULL
        , [StateDesc] nvarchar(60) NULL
        , [UserAccessDesc] nvarchar(60) NULL
        , [IsReadOnly] bit NULL
        , [CompatibilityLevel] tinyint NULL
        , [CollationName] sysname NULL
        , [RecoveryModelDesc] nvarchar(60) NULL
        , [IsSystemDatabase] bit NULL
        , [RequestedOrdinal] int NULL
    );
    CREATE TABLE [#VectorIndexAnalysis_CandidateWarnings]
    (
          [RequestedName] sysname COLLATE SQL_Latin1_General_CP1_CS_AS NULL
        , [StatusCode] varchar(40) NOT NULL
        , [ErrorMessage] nvarchar(2048) NULL
    );
    CREATE TABLE [#VectorIndexAnalysis_NameFilters]
    (
          [FilterType] varchar(20) COLLATE SQL_Latin1_General_CP1_CS_AS NOT NULL
        , [ItemOrdinal] int NOT NULL
        , [NameValue] sysname COLLATE SQL_Latin1_General_CP1_CS_AS NULL
        , [DatabaseName] sysname COLLATE SQL_Latin1_General_CP1_CS_AS NULL
        , [SchemaName] sysname COLLATE SQL_Latin1_General_CP1_CS_AS NULL
        , [ObjectName] sysname COLLATE SQL_Latin1_General_CP1_CS_AS NULL
    );
    CREATE TABLE [#VectorIndexAnalysis_VectorIndexes]
    (
          [CapturedAtUtc] datetime2(3) NOT NULL
        , [DatabaseId] int NOT NULL
        , [DatabaseName] sysname NOT NULL
        , [CompatibilityLevel] tinyint NULL
        , [PreviewFeaturesEnabled] bit NULL
        , [SchemaName] sysname NOT NULL
        , [ObjectId] int NOT NULL
        , [ObjectName] sysname NOT NULL
        , [IndexId] int NOT NULL
        , [IndexName] sysname NOT NULL
        , [VectorIndexType] varchar(20) NULL
        , [DistanceMetric] varchar(20) NULL
        , [IsDisabled] bit NOT NULL
        , [CatalogStatusCode] varchar(40) NOT NULL
        , [EvidenceLimit] nvarchar(1000) NOT NULL
        , PRIMARY KEY ([DatabaseId],[ObjectId],[IndexId])
    );
    CREATE TABLE [#VectorIndexAnalysis_RuntimeRaw]
    (
          [DatabaseId] int NOT NULL
        , [ObjectId] int NOT NULL
        , [IndexId] int NOT NULL
        , [ApproximateStalenessPercent] decimal(10,2) NULL
        , [QuantizedKeysUsedPercent] decimal(10,2) NULL
        , [LastBackgroundTaskTime] datetime2(7) NULL
        , [LastBackgroundTaskSucceeded] bit NULL
        , [LastBackgroundTaskDurationSeconds] bigint NULL
        , [LastBackgroundTaskProcessedInserts] bigint NULL
        , [LastBackgroundTaskProcessedDeletes] bigint NULL
        , [LastBackgroundTaskErrorMessage] nvarchar(max) NULL
        , PRIMARY KEY ([DatabaseId],[ObjectId],[IndexId])
    );
    CREATE TABLE [#VectorIndexAnalysis_Maintenance]
    (
          [CapturedAtUtc] datetime2(3) NOT NULL
        , [DatabaseId] int NOT NULL
        , [DatabaseName] sysname NOT NULL
        , [SchemaName] sysname NOT NULL
        , [ObjectId] int NOT NULL
        , [ObjectName] sysname NOT NULL
        , [IndexId] int NOT NULL
        , [IndexName] sysname NOT NULL
        , [ApproximateStalenessPercent] decimal(10,2) NULL
        , [QuantizedKeysUsedPercent] decimal(10,2) NULL
        , [LastBackgroundTaskTime] datetime2(7) NULL
        , [LastBackgroundTaskSucceeded] bit NULL
        , [LastBackgroundTaskDurationSeconds] bigint NULL
        , [LastBackgroundTaskProcessedInserts] bigint NULL
        , [LastBackgroundTaskProcessedDeletes] bigint NULL
        , [LastBackgroundTaskErrorMessage] nvarchar(max) NULL
        , [StatusCode] varchar(40) NOT NULL
        , [EvidenceLimit] nvarchar(1000) NOT NULL
        , PRIMARY KEY ([DatabaseId],[ObjectId],[IndexId])
    );
    CREATE TABLE [#VectorIndexAnalysis_Findings]
    (
          [FindingOrdinal] bigint IDENTITY(1,1) NOT NULL PRIMARY KEY
        , [DatabaseName] sysname NULL
        , [SchemaName] sysname NULL
        , [ObjectName] sysname NULL
        , [IndexName] sysname NULL
        , [Severity] varchar(16) NOT NULL
        , [Confidence] varchar(16) NOT NULL
        , [FindingCode] varchar(120) NOT NULL
        , [MetricName] varchar(80) NOT NULL
        , [MetricValue] decimal(38,4) NULL
        , [ThresholdValue] decimal(38,4) NULL
        , [Evidence] nvarchar(1000) NOT NULL
        , [EvidenceLimit] nvarchar(1000) NOT NULL
        , [RecommendedNextCheck] nvarchar(1000) NOT NULL
    );
    CREATE TABLE [#VectorIndexAnalysis_SourceStatus]
    (
          [SourceOrdinal] int IDENTITY(1,1) NOT NULL PRIMARY KEY
        , [DatabaseId] int NULL
        , [DatabaseName] sysname NULL
        , [SourceName] sysname NOT NULL
        , [SourceObject] nvarchar(256) NOT NULL
        , [CapturedAtUtc] datetime2(3) NOT NULL
        , [StatusCode] varchar(40) NOT NULL
        , [IsPartial] bit NOT NULL
        , [ReturnedRowCount] bigint NOT NULL
        , [RequiredPermission] nvarchar(256) NULL
        , [ErrorNumber] int NULL
        , [ErrorMessage] nvarchar(2048) NULL
        , [EvidenceLimit] nvarchar(1000) NOT NULL
    );
    CREATE TABLE [#VectorIndexAnalysis_Warnings]
    (
          [WarningOrdinal] int IDENTITY(1,1) NOT NULL PRIMARY KEY
        , [DatabaseName] sysname NULL
        , [SourceName] sysname NOT NULL
        , [StatusCode] varchar(40) NOT NULL
        , [ErrorNumber] int NULL
        , [Message] nvarchar(2048) NOT NULL
    );
    CREATE TABLE [#VectorIndexAnalysis_ModuleStatus]
    (
          [ModuleName] sysname NOT NULL
        , [CapturedAtUtc] datetime2(3) NOT NULL
        , [StatusCode] varchar(40) NOT NULL
        , [IsPartial] bit NOT NULL
        , [ProductMajorVersion] int NULL
        , [CrossDatabaseRequested] bit NOT NULL
        , [DatabaseCount] int NOT NULL
        , [VectorIndexRowCount] bigint NOT NULL
        , [MaintenanceRowCount] bigint NOT NULL
        , [FindingRowCount] bigint NOT NULL
        , [HasMoreVectorIndexRows] bit NOT NULL
        , [HasMoreMaintenanceRows] bit NOT NULL
        , [HasMoreFindingRows] bit NOT NULL
        , [ErrorNumber] int NULL
        , [ErrorMessage] nvarchar(2048) NULL
    );

    DECLARE
          @SchemaPatternMode varchar(8),@SchemaPatternValue nvarchar(4000),@SchemaRegexFlags varchar(8),@SchemaPatternValid bit
        , @ObjectPatternMode varchar(8),@ObjectPatternValue nvarchar(4000),@ObjectRegexFlags varchar(8),@ObjectPatternValid bit
        , @IndexPatternMode varchar(8),@IndexPatternValue nvarchar(4000),@IndexRegexFlags varchar(8),@IndexPatternValid bit;
    SELECT @SchemaPatternMode=[PatternMode],@SchemaPatternValue=[PatternValue],@SchemaRegexFlags=[RegexFlags],@SchemaPatternValid=[IsValid]
    FROM [monitor].[TVF_ParsePattern](@SchemaNamePattern);
    SELECT @ObjectPatternMode=[PatternMode],@ObjectPatternValue=[PatternValue],@ObjectRegexFlags=[RegexFlags],@ObjectPatternValid=[IsValid]
    FROM [monitor].[TVF_ParsePattern](@ObjectNamePattern);
    SELECT @IndexPatternMode=[PatternMode],@IndexPatternValue=[PatternValue],@IndexRegexFlags=[RegexFlags],@IndexPatternValid=[IsValid]
    FROM [monitor].[TVF_ParsePattern](@IndexNamePattern);

    IF @MaxZeilen<0 OR @LockTimeoutMs NOT BETWEEN 0 AND 60000
       OR @SystemdatenbankenEinbeziehen IS NULL OR @HighImpactConfirmed IS NULL
       OR @JsonErzeugen IS NULL OR @PrintMeldungen IS NULL
       OR @OutputMode NOT IN('CONSOLE','RAW','TABLE','NONE')
       OR (@OutputMode<>'TABLE' AND NULLIF(LTRIM(RTRIM(COALESCE(@ResultTablesJson,N''))),N'') IS NOT NULL)
       OR (@SchemaNames IS NOT NULL AND @SchemaNamePattern IS NOT NULL)
       OR (@ObjectNames IS NOT NULL AND @ObjectNamePattern IS NOT NULL)
       OR (@IndexNames IS NOT NULL AND @IndexNamePattern IS NOT NULL)
       OR COALESCE(@SchemaPatternValid,0)=0 OR COALESCE(@ObjectPatternValid,0)=0 OR COALESCE(@IndexPatternValid,0)=0
       OR (@StalenessReviewPercent IS NOT NULL AND @StalenessReviewPercent NOT BETWEEN 0 AND 100)
    BEGIN
        SELECT @StatusCode='INVALID_PARAMETER',@IsPartial=1,
               @ErrorMessage=N'Ungültiger Filter-, Grenzwert-, Lock-Timeout- oder Ausgabeparameter.';
    END;

    IF @StatusCode='AVAILABLE' AND @OutputMode='TABLE'
        EXEC [monitor].[InternalPrepareResultTables]
              @ResultTablesJson=@ResultTablesJson
            , @AllowedResultNames=N'moduleStatus|vectorIndexes|maintenance|findings|sourceStatus|warnings'
            , @MappingTable=N'#VectorIndexAnalysis_ResultTableMap'
            , @StatusCode=@StatusCode OUTPUT
            , @ErrorMessage=@ErrorMessage OUTPUT
            , @ThrowOnError=1;

    IF @StatusCode='AVAILABLE'
        EXEC [monitor].[USP_PrepareNameFilters]
              @SchemaNames=@SchemaNames
            , @ObjectNames=@ObjectNames
            , @FullObjectNames=@FullObjectNames
            , @IndexNames=@IndexNames
            , @StatisticsNames=NULL
            , @ColumnNames=NULL
            , @StatusCode=@StatusCode OUTPUT
            , @ErrorMessage=@ErrorMessage OUTPUT
            , @FilterTable=N'#VectorIndexAnalysis_NameFilters';

    IF @StatusCode='AVAILABLE'
        EXEC [monitor].[USP_PrepareDatabaseCandidates]
              @DatabaseNames=@DatabaseNames
            , @SystemdatenbankenEinbeziehen=@SystemdatenbankenEinbeziehen
            , @DatabaseNamePattern=@DatabaseNamePattern
            , @HighImpactConfirmed=@HighImpactConfirmed
            , @AnalysisClass='OBJECT_ANALYSIS_CURRENT'
            , @StatusCode=@StatusCode OUTPUT
            , @ErrorMessage=@ErrorMessage OUTPUT
            , @CrossDatabaseRequested=@CrossDatabaseRequested OUTPUT
            , @CandidateTable=N'#VectorIndexAnalysis_DatabaseCandidates'
            , @WarningTable=N'#VectorIndexAnalysis_CandidateWarnings';

    DECLARE @SchemaPredicate nvarchar(max)=N'';
    DECLARE @ObjectPredicate nvarchar(max)=N'';
    DECLARE @IndexPredicate nvarchar(max)=N'';

    SET @SchemaPredicate=N'
      AND (NOT EXISTS(SELECT 1 FROM [#VectorIndexAnalysis_NameFilters] WHERE [FilterType]=''SCHEMA'')
           OR EXISTS(SELECT 1 FROM [#VectorIndexAnalysis_NameFilters] AS [f]
                     WHERE [f].[FilterType]=''SCHEMA''
                       AND [f].[NameValue]=[s].[name] COLLATE SQL_Latin1_General_CP1_CS_AS))';
    SET @ObjectPredicate=N'
      AND (NOT EXISTS(SELECT 1 FROM [#VectorIndexAnalysis_NameFilters] WHERE [FilterType]=''OBJECT'')
           OR EXISTS(SELECT 1 FROM [#VectorIndexAnalysis_NameFilters] AS [f]
                     WHERE [f].[FilterType]=''OBJECT''
                       AND [f].[NameValue]=[o].[name] COLLATE SQL_Latin1_General_CP1_CS_AS))
      AND (NOT EXISTS(SELECT 1 FROM [#VectorIndexAnalysis_NameFilters] WHERE [FilterType]=''FULL_OBJECT'')
           OR EXISTS(SELECT 1 FROM [#VectorIndexAnalysis_NameFilters] AS [f]
                     WHERE [f].[FilterType]=''FULL_OBJECT''
                       AND ([f].[DatabaseName] IS NULL OR [f].[DatabaseName]=@pDatabaseName COLLATE SQL_Latin1_General_CP1_CS_AS)
                       AND ([f].[SchemaName] IS NULL OR [f].[SchemaName]=[s].[name] COLLATE SQL_Latin1_General_CP1_CS_AS)
                       AND [f].[ObjectName]=[o].[name] COLLATE SQL_Latin1_General_CP1_CS_AS))';
    SET @IndexPredicate=N'
      AND (NOT EXISTS(SELECT 1 FROM [#VectorIndexAnalysis_NameFilters] WHERE [FilterType]=''INDEX'')
           OR EXISTS(SELECT 1 FROM [#VectorIndexAnalysis_NameFilters] AS [f]
                     WHERE [f].[FilterType]=''INDEX''
                       AND [f].[NameValue]=[v].[name] COLLATE SQL_Latin1_General_CP1_CS_AS))';

    IF @SchemaPatternMode='LIKE'
        SET @SchemaPredicate+=N' AND [s].[name] COLLATE SQL_Latin1_General_CP1_CS_AS LIKE @pSchemaPattern COLLATE SQL_Latin1_General_CP1_CS_AS';
    ELSE IF @SchemaPatternMode IN('REGEX','REGEXI')
        SET @SchemaPredicate+=N' AND REGEXP_LIKE([s].[name],@pSchemaPattern,@pSchemaFlags)';
    IF @ObjectPatternMode='LIKE'
        SET @ObjectPredicate+=N' AND [o].[name] COLLATE SQL_Latin1_General_CP1_CS_AS LIKE @pObjectPattern COLLATE SQL_Latin1_General_CP1_CS_AS';
    ELSE IF @ObjectPatternMode IN('REGEX','REGEXI')
        SET @ObjectPredicate+=N' AND REGEXP_LIKE([o].[name],@pObjectPattern,@pObjectFlags)';
    IF @IndexPatternMode='LIKE'
        SET @IndexPredicate+=N' AND [v].[name] COLLATE SQL_Latin1_General_CP1_CS_AS LIKE @pIndexPattern COLLATE SQL_Latin1_General_CP1_CS_AS';
    ELSE IF @IndexPatternMode IN('REGEX','REGEXI')
        SET @IndexPredicate+=N' AND REGEXP_LIKE([v].[name],@pIndexPattern,@pIndexFlags)';

    IF @StatusCode='AVAILABLE'
    BEGIN
        SET @LockTimeoutSql=N'SET LOCK_TIMEOUT '+CONVERT(nvarchar(20),@LockTimeoutMs)+N';';
        EXEC [sys].[sp_executesql] @LockTimeoutSql;

        DECLARE
              @DatabaseId int
            , @DatabaseName sysname
            , @CompatibilityLevel tinyint
            , @PreviewFeaturesEnabled bit
            , @HasVectorCatalog bit
            , @HasVectorRuntime bit
            , @VectorCatalogSchemaValid bit
            , @VectorRuntimeSchemaValid bit
            , @ProbeSql nvarchar(max)
            , @CatalogSql nvarchar(max)
            , @RuntimeSql nvarchar(max)
            , @CatalogRows bigint
            , @RuntimeRows bigint;

        DECLARE [DatabaseCursor] CURSOR LOCAL FAST_FORWARD FOR
            SELECT [DatabaseId],[DatabaseName],[CompatibilityLevel]
            FROM [#VectorIndexAnalysis_DatabaseCandidates]
            ORDER BY COALESCE([RequestedOrdinal],[DatabaseId]),[DatabaseId];
        OPEN [DatabaseCursor];
        FETCH NEXT FROM [DatabaseCursor] INTO @DatabaseId,@DatabaseName,@CompatibilityLevel;
        WHILE @@FETCH_STATUS=0
        BEGIN
            IF @ProductMajorVersion IS NULL OR @ProductMajorVersion<17
            BEGIN
                INSERT [#VectorIndexAnalysis_SourceStatus]
                VALUES
                  (@DatabaseId,@DatabaseName,N'vectorCatalog',N'sys.vector_indexes',@CapturedAtUtc,'UNAVAILABLE_VERSION',0,0,N'Metadata Visibility',NULL,NULL,N'Vector-Indizes werden erst ab SQL Server 2025 referenziert.')
                , (@DatabaseId,@DatabaseName,N'vectorRuntime',N'sys.dm_db_vector_indexes',@CapturedAtUtc,'UNAVAILABLE_VERSION',0,0,N'VIEW DATABASE STATE',NULL,NULL,N'Die Runtime-DMV wird erst ab SQL Server 2025 referenziert.');
            END
            ELSE IF (@SchemaPatternMode IN('REGEX','REGEXI') OR @ObjectPatternMode IN('REGEX','REGEXI') OR @IndexPatternMode IN('REGEX','REGEXI'))
                    AND COALESCE(@CompatibilityLevel,0)<170
            BEGIN
                INSERT [#VectorIndexAnalysis_SourceStatus]
                VALUES
                  (@DatabaseId,@DatabaseName,N'vectorCatalog',N'sys.vector_indexes',@CapturedAtUtc,'UNAVAILABLE_PATTERN_CAPABILITY',1,0,N'Metadata Visibility',NULL,NULL,N'Regexfilter benötigen SQL Server 2025 und Compatibility Level 170.')
                , (@DatabaseId,@DatabaseName,N'vectorRuntime',N'sys.dm_db_vector_indexes',@CapturedAtUtc,'NOT_COLLECTED',1,0,N'VIEW DATABASE STATE',NULL,NULL,N'Die Runtimequelle wurde wegen des nicht ausführbaren Filters nicht gelesen.');
            END
            ELSE
            BEGIN
                SELECT
                      @PreviewFeaturesEnabled=NULL
                    , @HasVectorCatalog=0
                    , @HasVectorRuntime=0
                    , @VectorCatalogSchemaValid=0
                    , @VectorRuntimeSchemaValid=0;

                SET @ProbeSql=N'USE '+QUOTENAME(@DatabaseName)+N';
SELECT @pPreviewFeaturesEnabled=CONVERT(bit,MAX(CASE WHEN [name]=N''PREVIEW_FEATURES'' AND TRY_CONVERT(bit,[value])=1 THEN 1 ELSE 0 END))
FROM [sys].[database_scoped_configurations] WITH (NOLOCK);

SELECT @pHasVectorCatalog=CONVERT(bit,CASE WHEN EXISTS
(
    SELECT 1
    FROM [sys].[all_objects] AS [o] WITH (NOLOCK)
    INNER JOIN [sys].[schemas] AS [s] WITH (NOLOCK) ON [s].[schema_id]=[o].[schema_id]
    WHERE [s].[name]=N''sys'' AND [o].[name]=N''vector_indexes''
) THEN 1 ELSE 0 END);

SELECT @pHasVectorRuntime=CONVERT(bit,CASE WHEN EXISTS
(
    SELECT 1
    FROM [sys].[all_objects] AS [o] WITH (NOLOCK)
    INNER JOIN [sys].[schemas] AS [s] WITH (NOLOCK) ON [s].[schema_id]=[o].[schema_id]
    WHERE [s].[name]=N''sys'' AND [o].[name]=N''dm_db_vector_indexes''
) THEN 1 ELSE 0 END);

SELECT @pVectorCatalogSchemaValid=CONVERT(bit,CASE WHEN COUNT(DISTINCT [c].[name])=6 THEN 1 ELSE 0 END)
FROM [sys].[all_objects] AS [o] WITH (NOLOCK)
INNER JOIN [sys].[schemas] AS [s] WITH (NOLOCK) ON [s].[schema_id]=[o].[schema_id]
INNER JOIN [sys].[all_columns] AS [c] WITH (NOLOCK) ON [c].[object_id]=[o].[object_id]
WHERE [s].[name]=N''sys'' AND [o].[name]=N''vector_indexes''
  AND [c].[name] IN(N''object_id'',N''index_id'',N''name'',N''vector_index_type'',N''distance_metric'',N''is_disabled'');

SELECT @pVectorRuntimeSchemaValid=CONVERT(bit,CASE WHEN COUNT(DISTINCT [c].[name])=10 THEN 1 ELSE 0 END)
FROM [sys].[all_objects] AS [o] WITH (NOLOCK)
INNER JOIN [sys].[schemas] AS [s] WITH (NOLOCK) ON [s].[schema_id]=[o].[schema_id]
INNER JOIN [sys].[all_columns] AS [c] WITH (NOLOCK) ON [c].[object_id]=[o].[object_id]
WHERE [s].[name]=N''sys'' AND [o].[name]=N''dm_db_vector_indexes''
  AND [c].[name] IN
      (N''object_id'',N''index_id'',N''approximate_staleness_percent'',N''quantized_keys_used_percent'',
       N''last_background_task_time'',N''last_background_task_succeeded'',
       N''last_background_task_duration_seconds'',N''last_background_task_processed_inserts'',
       N''last_background_task_processed_deletes'',N''last_background_task_error_message'');';

                BEGIN TRY
                    EXEC [sys].[sp_executesql]
                          @ProbeSql
                        , N'@pPreviewFeaturesEnabled bit OUTPUT,@pHasVectorCatalog bit OUTPUT,@pHasVectorRuntime bit OUTPUT,@pVectorCatalogSchemaValid bit OUTPUT,@pVectorRuntimeSchemaValid bit OUTPUT'
                        , @pPreviewFeaturesEnabled=@PreviewFeaturesEnabled OUTPUT
                        , @pHasVectorCatalog=@HasVectorCatalog OUTPUT
                        , @pHasVectorRuntime=@HasVectorRuntime OUTPUT
                        , @pVectorCatalogSchemaValid=@VectorCatalogSchemaValid OUTPUT
                        , @pVectorRuntimeSchemaValid=@VectorRuntimeSchemaValid OUTPUT;
                END TRY
                BEGIN CATCH
                    INSERT [#VectorIndexAnalysis_SourceStatus]
                    VALUES
                      (@DatabaseId,@DatabaseName,N'vectorCatalog',N'sys.vector_indexes',@CapturedAtUtc,
                       CASE WHEN ERROR_NUMBER() IN(229,262,297,300,371,916) THEN 'DENIED_PERMISSION' WHEN ERROR_NUMBER()=1222 THEN 'TIMEOUT' ELSE 'ERROR_HANDLED' END,
                       1,0,N'Metadata Visibility',ERROR_NUMBER(),ERROR_MESSAGE(),N'Die Feature- und Schemaprüfung ist fehlgeschlagen; die versionsspezifische Quelle wurde nicht referenziert.')
                    , (@DatabaseId,@DatabaseName,N'vectorRuntime',N'sys.dm_db_vector_indexes',@CapturedAtUtc,'NOT_COLLECTED',1,0,N'VIEW DATABASE STATE',NULL,NULL,N'Die Runtimequelle wurde nach fehlgeschlagener Featureprüfung nicht gelesen.');
                    SELECT @HasVectorCatalog=0,@HasVectorRuntime=0,@VectorCatalogSchemaValid=0,@VectorRuntimeSchemaValid=0;
                END CATCH;

                IF @HasVectorCatalog=1 AND @VectorCatalogSchemaValid=1
                BEGIN
                    SET @CatalogSql=N'USE '+QUOTENAME(@DatabaseName)+N';
INSERT [#VectorIndexAnalysis_VectorIndexes]
([CapturedAtUtc],[DatabaseId],[DatabaseName],[CompatibilityLevel],[PreviewFeaturesEnabled],
 [SchemaName],[ObjectId],[ObjectName],[IndexId],[IndexName],[VectorIndexType],
 [DistanceMetric],[IsDisabled],[CatalogStatusCode],[EvidenceLimit])
SELECT @pCapturedAtUtc,@pDatabaseId,@pDatabaseName,@pCompatibilityLevel,@pPreviewFeaturesEnabled,
       [s].[name],[o].[object_id],[o].[name],[v].[index_id],[v].[name],
       CONVERT(varchar(20),[v].[vector_index_type]),CONVERT(varchar(20),[v].[distance_metric]),
       CONVERT(bit,[v].[is_disabled]),''AVAILABLE'',
       N''Sichtbarer Katalogzustand. Interne build_parameters und Vector-Nutzwerte werden nicht gelesen.''
FROM [sys].[vector_indexes] AS [v] WITH (NOLOCK)
INNER JOIN [sys].[objects] AS [o] WITH (NOLOCK) ON [o].[object_id]=[v].[object_id]
INNER JOIN [sys].[schemas] AS [s] WITH (NOLOCK) ON [s].[schema_id]=[o].[schema_id]
WHERE [o].[is_ms_shipped]=0'
                        +@SchemaPredicate+@ObjectPredicate+@IndexPredicate+N'
OPTION (MAXDOP 1,RECOMPILE);';
                    BEGIN TRY
                        EXEC [sys].[sp_executesql]
                              @CatalogSql
                            , N'@pCapturedAtUtc datetime2(3),@pDatabaseId int,@pDatabaseName sysname,@pCompatibilityLevel tinyint,@pPreviewFeaturesEnabled bit,@pSchemaPattern nvarchar(4000),@pSchemaFlags varchar(8),@pObjectPattern nvarchar(4000),@pObjectFlags varchar(8),@pIndexPattern nvarchar(4000),@pIndexFlags varchar(8)'
                            , @pCapturedAtUtc=@CapturedAtUtc,@pDatabaseId=@DatabaseId,@pDatabaseName=@DatabaseName
                            , @pCompatibilityLevel=@CompatibilityLevel,@pPreviewFeaturesEnabled=@PreviewFeaturesEnabled
                            , @pSchemaPattern=@SchemaPatternValue,@pSchemaFlags=@SchemaRegexFlags
                            , @pObjectPattern=@ObjectPatternValue,@pObjectFlags=@ObjectRegexFlags
                            , @pIndexPattern=@IndexPatternValue,@pIndexFlags=@IndexRegexFlags;
                        SELECT @CatalogRows=COUNT_BIG(*) FROM [#VectorIndexAnalysis_VectorIndexes] WHERE [DatabaseId]=@DatabaseId;
                        INSERT [#VectorIndexAnalysis_SourceStatus]
                        VALUES(@DatabaseId,@DatabaseName,N'vectorCatalog',N'sys.vector_indexes',@CapturedAtUtc,
                               CASE WHEN @CatalogRows=0 AND @PreviewFeaturesEnabled=0 THEN 'NOT_ENABLED'
                                    WHEN @CatalogRows=0 THEN 'AVAILABLE_EMPTY' ELSE 'AVAILABLE' END,
                               0,@CatalogRows,N'Metadata Visibility',NULL,NULL,
                               N'Eine Zeile je sichtbarem Vector-Index; Nullzeilen beweisen bei eingeschränkter Metadatensicht keine serverweite Abwesenheit.');
                    END TRY
                    BEGIN CATCH
                        INSERT [#VectorIndexAnalysis_SourceStatus]
                        VALUES(@DatabaseId,@DatabaseName,N'vectorCatalog',N'sys.vector_indexes',@CapturedAtUtc,
                               CASE WHEN ERROR_NUMBER() IN(229,262,297,300,371,916) THEN 'DENIED_PERMISSION' WHEN ERROR_NUMBER()=1222 THEN 'TIMEOUT' ELSE 'ERROR_HANDLED' END,
                               1,0,N'Metadata Visibility',ERROR_NUMBER(),ERROR_MESSAGE(),N'Der Katalogfehler ist auf diese Datenbank begrenzt.');
                    END CATCH;
                END
                ELSE IF NOT EXISTS
                (
                    SELECT 1 FROM [#VectorIndexAnalysis_SourceStatus]
                    WHERE [DatabaseId]=@DatabaseId AND [SourceName]=N'vectorCatalog'
                )
                    INSERT [#VectorIndexAnalysis_SourceStatus]
                    VALUES(@DatabaseId,@DatabaseName,N'vectorCatalog',N'sys.vector_indexes',@CapturedAtUtc,
                           CASE WHEN @HasVectorCatalog=0 THEN 'UNAVAILABLE_FEATURE' ELSE 'UNAVAILABLE_SOURCE_SCHEMA' END,
                           CONVERT(bit,CASE WHEN @HasVectorCatalog=1 THEN 1 ELSE 0 END),
                           0,N'Metadata Visibility',NULL,NULL,N'Die Quelle oder ihr dokumentiertes Pflichtschema ist auf diesem SQL-Server-2025-Build nicht verfügbar.');

                IF @HasVectorRuntime=1 AND @VectorRuntimeSchemaValid=1
                BEGIN
                    SET @RuntimeSql=N'USE '+QUOTENAME(@DatabaseName)+N';
INSERT [#VectorIndexAnalysis_RuntimeRaw]
([DatabaseId],[ObjectId],[IndexId],[ApproximateStalenessPercent],[QuantizedKeysUsedPercent],
 [LastBackgroundTaskTime],[LastBackgroundTaskSucceeded],[LastBackgroundTaskDurationSeconds],
 [LastBackgroundTaskProcessedInserts],[LastBackgroundTaskProcessedDeletes],[LastBackgroundTaskErrorMessage])
SELECT @pDatabaseId,[object_id],[index_id],[approximate_staleness_percent],[quantized_keys_used_percent],
       [last_background_task_time],[last_background_task_succeeded],[last_background_task_duration_seconds],
       [last_background_task_processed_inserts],[last_background_task_processed_deletes],
       [last_background_task_error_message]
FROM [sys].[dm_db_vector_indexes] WITH (NOLOCK)
OPTION (MAXDOP 1,RECOMPILE);';
                    BEGIN TRY
                        EXEC [sys].[sp_executesql] @RuntimeSql,N'@pDatabaseId int',@pDatabaseId=@DatabaseId;
                        SELECT @RuntimeRows=COUNT_BIG(*) FROM [#VectorIndexAnalysis_RuntimeRaw] WHERE [DatabaseId]=@DatabaseId;
                        SELECT @CatalogRows=COUNT_BIG(*) FROM [#VectorIndexAnalysis_VectorIndexes] WHERE [DatabaseId]=@DatabaseId;
                        INSERT [#VectorIndexAnalysis_SourceStatus]
                        VALUES(@DatabaseId,@DatabaseName,N'vectorRuntime',N'sys.dm_db_vector_indexes',@CapturedAtUtc,
                               CASE WHEN @RuntimeRows=0 THEN 'AVAILABLE_EMPTY' ELSE 'AVAILABLE' END,
                               CONVERT(bit,CASE WHEN @CatalogRows>0 AND @RuntimeRows=0 THEN 1 ELSE 0 END),
                               @RuntimeRows,N'VIEW DATABASE STATE',NULL,NULL,
                               N'Flüchtiger aktueller Wartungszustand. Staleness, Taskstatus und Zähler besitzen keinen langfristigen Verlauf.');
                    END TRY
                    BEGIN CATCH
                        INSERT [#VectorIndexAnalysis_SourceStatus]
                        VALUES(@DatabaseId,@DatabaseName,N'vectorRuntime',N'sys.dm_db_vector_indexes',@CapturedAtUtc,
                               CASE WHEN ERROR_NUMBER() IN(229,262,297,300,371,916) THEN 'DENIED_PERMISSION' WHEN ERROR_NUMBER()=1222 THEN 'TIMEOUT' ELSE 'ERROR_HANDLED' END,
                               1,0,N'VIEW DATABASE STATE',ERROR_NUMBER(),ERROR_MESSAGE(),N'Der Runtimefehler ist auf diese Datenbank begrenzt; Katalogevidenz kann weiterhin gültig sein.');
                    END CATCH;
                END
                ELSE IF NOT EXISTS
                (
                    SELECT 1 FROM [#VectorIndexAnalysis_SourceStatus]
                    WHERE [DatabaseId]=@DatabaseId AND [SourceName]=N'vectorRuntime'
                )
                BEGIN
                    SELECT @CatalogRows=COUNT_BIG(*) FROM [#VectorIndexAnalysis_VectorIndexes] WHERE [DatabaseId]=@DatabaseId;
                    INSERT [#VectorIndexAnalysis_SourceStatus]
                    VALUES(@DatabaseId,@DatabaseName,N'vectorRuntime',N'sys.dm_db_vector_indexes',@CapturedAtUtc,
                           CASE WHEN @HasVectorRuntime=0 THEN 'UNAVAILABLE_FEATURE' ELSE 'UNAVAILABLE_SOURCE_SCHEMA' END,
                           CONVERT(bit,CASE WHEN @HasVectorRuntime=1 OR @CatalogRows>0 THEN 1 ELSE 0 END),
                           0,N'VIEW DATABASE STATE',NULL,NULL,N'Die Runtimequelle oder ihr dokumentiertes Pflichtschema ist auf diesem Build nicht verfügbar.');
                END;
            END;

            FETCH NEXT FROM [DatabaseCursor] INTO @DatabaseId,@DatabaseName,@CompatibilityLevel;
        END;
        CLOSE [DatabaseCursor];
        DEALLOCATE [DatabaseCursor];
    END;

    INSERT [#VectorIndexAnalysis_Maintenance]
    SELECT
          [v].[CapturedAtUtc],[v].[DatabaseId],[v].[DatabaseName],[v].[SchemaName]
        , [v].[ObjectId],[v].[ObjectName],[v].[IndexId],[v].[IndexName]
        , [r].[ApproximateStalenessPercent],[r].[QuantizedKeysUsedPercent]
        , [r].[LastBackgroundTaskTime],[r].[LastBackgroundTaskSucceeded]
        , [r].[LastBackgroundTaskDurationSeconds],[r].[LastBackgroundTaskProcessedInserts]
        , [r].[LastBackgroundTaskProcessedDeletes],[r].[LastBackgroundTaskErrorMessage]
        , CASE WHEN [r].[ObjectId] IS NOT NULL THEN 'AVAILABLE'
               WHEN [ss].[StatusCode] IN('AVAILABLE','AVAILABLE_EMPTY') THEN 'NOT_RETURNED'
               ELSE COALESCE([ss].[StatusCode],'NOT_COLLECTED') END
        , N'Runtimeevidenz ist eine Momentaufnahme. Eine fehlende Zeile, einzelne Stalenessmessung oder ein Taskfehler beweist weder dauerhafte Suchqualitäts- noch Storageprobleme.'
    FROM [#VectorIndexAnalysis_VectorIndexes] AS [v]
    LEFT JOIN [#VectorIndexAnalysis_RuntimeRaw] AS [r]
      ON [r].[DatabaseId]=[v].[DatabaseId]
     AND [r].[ObjectId]=[v].[ObjectId]
     AND [r].[IndexId]=[v].[IndexId]
    OUTER APPLY
    (
        SELECT TOP(1) [s].[StatusCode]
        FROM [#VectorIndexAnalysis_SourceStatus] AS [s]
        WHERE [s].[DatabaseId]=[v].[DatabaseId] AND [s].[SourceName]=N'vectorRuntime'
        ORDER BY [s].[SourceOrdinal] DESC
    ) AS [ss];

    INSERT [#VectorIndexAnalysis_Findings]
    ([DatabaseName],[SchemaName],[ObjectName],[IndexName],[Severity],[Confidence],[FindingCode],
     [MetricName],[MetricValue],[ThresholdValue],[Evidence],[EvidenceLimit],[RecommendedNextCheck])
    SELECT [DatabaseName],[SchemaName],[ObjectName],[IndexName],'INFO','HIGH','VECTOR_INDEX_DISABLED',
           'IS_DISABLED',1,NULL,N'Der sichtbare Vector-Index ist deaktiviert.',
           N'Der Katalogzustand ist aktuell, enthält aber keine Betriebsabsicht und keinen Nachweis zur Ursache der Deaktivierung.',
           N'Änderungshistorie, Deploymentzustand und beabsichtigte Nutzung prüfen; keine automatische Aktivierung ableiten.'
    FROM [#VectorIndexAnalysis_VectorIndexes]
    WHERE [IsDisabled]=1;

    INSERT [#VectorIndexAnalysis_Findings]
    ([DatabaseName],[SchemaName],[ObjectName],[IndexName],[Severity],[Confidence],[FindingCode],
     [MetricName],[MetricValue],[ThresholdValue],[Evidence],[EvidenceLimit],[RecommendedNextCheck])
    SELECT [DatabaseName],[SchemaName],[ObjectName],[IndexName],'WARN','HIGH','VECTOR_BACKGROUND_TASK_FAILED',
           'LAST_BACKGROUND_TASK_SUCCEEDED',0,1,N'Die letzte sichtbare Hintergrundwartung meldet einen Fehler.',
           N'Es handelt sich um den letzten sichtbaren Taskstatus. Wiederholung, aktueller Backlog und Suchwirkung werden nicht historisch gemessen.',
           N'Fehlermeldung, nachfolgende Taskläufe, Stalenessverlauf sowie messbare Recall- oder Performanceänderung gemeinsam prüfen.'
    FROM [#VectorIndexAnalysis_Maintenance]
    WHERE [StatusCode]='AVAILABLE' AND [LastBackgroundTaskSucceeded]=0;

    INSERT [#VectorIndexAnalysis_Findings]
    ([DatabaseName],[SchemaName],[ObjectName],[IndexName],[Severity],[Confidence],[FindingCode],
     [MetricName],[MetricValue],[ThresholdValue],[Evidence],[EvidenceLimit],[RecommendedNextCheck])
    SELECT [DatabaseName],[SchemaName],[ObjectName],[IndexName],'WARN','MEDIUM','VECTOR_STALENESS_REVIEW',
           'APPROXIMATE_STALENESS_PERCENT',[ApproximateStalenessPercent],@StalenessReviewPercent,
           N'Die aktuelle ungefähre Staleness erreicht den konfigurierten Review-Grenzwert.',
           N'Für Staleness existiert kein universeller Fehlergrenzwert. Batchloads können vorübergehend deutlich erhöhte Werte erzeugen; ein Einzelwert ist kein Rebuildnachweis.',
           N'Wert über Zeit, DML-Rate, Abschluss der Hintergrundwartung sowie messbare Recall- und Performanceentwicklung korrelieren.'
    FROM [#VectorIndexAnalysis_Maintenance]
    WHERE [StatusCode]='AVAILABLE'
      AND @StalenessReviewPercent IS NOT NULL
      AND [ApproximateStalenessPercent]>=@StalenessReviewPercent;

    INSERT [#VectorIndexAnalysis_Warnings]([DatabaseName],[SourceName],[StatusCode],[ErrorNumber],[Message])
    SELECT [DatabaseName],[SourceName],[StatusCode],[ErrorNumber],COALESCE([ErrorMessage],N'Quelle unvollständig oder nicht verfügbar.')
    FROM [#VectorIndexAnalysis_SourceStatus]
    WHERE [IsPartial]=1;

    INSERT [#VectorIndexAnalysis_Warnings]([DatabaseName],[SourceName],[StatusCode],[ErrorNumber],[Message])
    SELECT [RequestedName],N'databaseCandidates',[StatusCode],NULL,COALESCE([ErrorMessage],N'Datenbank nicht verarbeitet.')
    FROM [#VectorIndexAnalysis_CandidateWarnings];

    IF @StatusCode='AVAILABLE'
    BEGIN
        IF @ProductMajorVersion IS NULL OR @ProductMajorVersion<17
            SET @StatusCode='UNAVAILABLE_VERSION';
        ELSE IF EXISTS(SELECT 1 FROM [#VectorIndexAnalysis_Warnings])
        BEGIN
            SET @StatusCode='AVAILABLE_LIMITED';
            SET @IsPartial=1;
        END
        ELSE IF NOT EXISTS
        (
            SELECT 1 FROM [#VectorIndexAnalysis_SourceStatus]
            WHERE [SourceName]=N'vectorCatalog' AND [StatusCode] IN('AVAILABLE','AVAILABLE_EMPTY','NOT_ENABLED')
        )
        BEGIN
            SELECT TOP(1) @StatusCode=[StatusCode],@ErrorNumber=[ErrorNumber],@ErrorMessage=[ErrorMessage]
            FROM [#VectorIndexAnalysis_SourceStatus]
            WHERE [SourceName]=N'vectorCatalog'
            ORDER BY [SourceOrdinal];
            SET @StatusCode=COALESCE(@StatusCode,'UNAVAILABLE_FEATURE');
        END
        ELSE IF EXISTS(SELECT 1 FROM [#VectorIndexAnalysis_Findings] WHERE [Severity]='WARN')
            SET @StatusCode='AVAILABLE_WITH_FINDING';
        ELSE IF NOT EXISTS(SELECT 1 FROM [#VectorIndexAnalysis_VectorIndexes])
            SET @StatusCode='NOT_APPLICABLE';
    END;

    IF @StatusCode NOT IN('AVAILABLE','AVAILABLE_WITH_FINDING','NOT_APPLICABLE','UNAVAILABLE_VERSION','UNAVAILABLE_FEATURE')
        SET @IsPartial=1;

    IF @ErrorMessage IS NULL
        SELECT TOP(1) @ErrorNumber=[ErrorNumber],@ErrorMessage=[Message]
        FROM [#VectorIndexAnalysis_Warnings]
        ORDER BY [WarningOrdinal];

    DECLARE @VectorRows bigint=(SELECT COUNT_BIG(*) FROM [#VectorIndexAnalysis_VectorIndexes]);
    DECLARE @MaintenanceRows bigint=(SELECT COUNT_BIG(*) FROM [#VectorIndexAnalysis_Maintenance]);
    DECLARE @FindingRows bigint=(SELECT COUNT_BIG(*) FROM [#VectorIndexAnalysis_Findings]);

    INSERT [#VectorIndexAnalysis_ModuleStatus]
    VALUES
    (
          N'USP_VectorIndexAnalysis',@CapturedAtUtc,@StatusCode,@IsPartial,@ProductMajorVersion
        , @CrossDatabaseRequested,(SELECT COUNT(*) FROM [#VectorIndexAnalysis_DatabaseCandidates])
        , CASE WHEN @VectorRows>@Limit THEN @Limit ELSE @VectorRows END
        , CASE WHEN @MaintenanceRows>@Limit THEN @Limit ELSE @MaintenanceRows END
        , CASE WHEN @FindingRows>@Limit THEN @Limit ELSE @FindingRows END
        , CONVERT(bit,CASE WHEN @Limit<9223372036854775807 AND @VectorRows>@Limit THEN 1 ELSE 0 END)
        , CONVERT(bit,CASE WHEN @Limit<9223372036854775807 AND @MaintenanceRows>@Limit THEN 1 ELSE 0 END)
        , CONVERT(bit,CASE WHEN @Limit<9223372036854775807 AND @FindingRows>@Limit THEN 1 ELSE 0 END)
        , @ErrorNumber,@ErrorMessage
    );

    IF @JsonErzeugen=1
    BEGIN
        DECLARE @MetaJson nvarchar(max)=
        (
            SELECT N'VectorIndexAnalysis' [resultName],1 [schemaVersion],@CapturedAtUtc [generatedAtUtc],
                   @StatusCode [statusCode],@IsPartial [isPartial],@ProductMajorVersion [productMajorVersion],
                   @StalenessReviewPercent [stalenessReviewPercent],
                   CASE WHEN @VectorRows>@Limit THEN @Limit ELSE @VectorRows END [vectorIndexRowCount],
                   CASE WHEN @MaintenanceRows>@Limit THEN @Limit ELSE @MaintenanceRows END [maintenanceRowCount],
                   CASE WHEN @FindingRows>@Limit THEN @Limit ELSE @FindingRows END [findingRowCount],
                   CONVERT(bit,CASE WHEN @Limit<9223372036854775807 AND @VectorRows>@Limit THEN 1 ELSE 0 END) [hasMoreVectorIndexRows],
                   CONVERT(bit,CASE WHEN @Limit<9223372036854775807 AND @MaintenanceRows>@Limit THEN 1 ELSE 0 END) [hasMoreMaintenanceRows],
                   CONVERT(bit,CASE WHEN @Limit<9223372036854775807 AND @FindingRows>@Limit THEN 1 ELSE 0 END) [hasMoreFindingRows],
                   @ErrorNumber [errorNumber],@ErrorMessage [errorMessage]
            FOR JSON PATH,WITHOUT_ARRAY_WRAPPER,INCLUDE_NULL_VALUES
        );
        DECLARE @VectorIndexesJson nvarchar(max)=
        (
            SELECT TOP(@Limit) * FROM [#VectorIndexAnalysis_VectorIndexes]
            ORDER BY [DatabaseName],[SchemaName],[ObjectName],[IndexName]
            FOR JSON PATH,INCLUDE_NULL_VALUES
        );
        DECLARE @MaintenanceJson nvarchar(max)=
        (
            SELECT TOP(@Limit) * FROM [#VectorIndexAnalysis_Maintenance]
            ORDER BY [DatabaseName],[SchemaName],[ObjectName],[IndexName]
            FOR JSON PATH,INCLUDE_NULL_VALUES
        );
        DECLARE @FindingsJson nvarchar(max)=
        (
            SELECT TOP(@Limit) * FROM [#VectorIndexAnalysis_Findings]
            ORDER BY CASE [Severity] WHEN 'WARN' THEN 1 ELSE 2 END,[FindingOrdinal]
            FOR JSON PATH,INCLUDE_NULL_VALUES
        );
        DECLARE @SourceStatusJson nvarchar(max)=
        (
            SELECT * FROM [#VectorIndexAnalysis_SourceStatus]
            ORDER BY [SourceOrdinal]
            FOR JSON PATH,INCLUDE_NULL_VALUES
        );
        DECLARE @WarningsJson nvarchar(max)=
        (
            SELECT * FROM [#VectorIndexAnalysis_Warnings]
            ORDER BY [WarningOrdinal]
            FOR JSON PATH,INCLUDE_NULL_VALUES
        );
        SET @Json=CONCAT
        (
              N'{"meta":',COALESCE(@MetaJson,N'{}')
            , N',"vectorIndexes":',COALESCE(@VectorIndexesJson,N'[]')
            , N',"maintenance":',COALESCE(@MaintenanceJson,N'[]')
            , N',"findings":',COALESCE(@FindingsJson,N'[]')
            , N',"sourceStatus":',COALESCE(@SourceStatusJson,N'[]')
            , N',"warnings":',COALESCE(@WarningsJson,N'[]')
            , N'}'
        );
    END;

    SET @LockTimeoutSql=N'SET LOCK_TIMEOUT '+CONVERT(nvarchar(20),@OriginalLockTimeout)+N';';
    EXEC [sys].[sp_executesql] @LockTimeoutSql;

    IF @ConsoleResultRequested=1
        EXEC [monitor].[InternalEmitConsoleResult]
              @SourceTable=N'#VectorIndexAnalysis_Findings'
            , @ResultLabel=N'Vector-Index-Wartung'
            , @EmptyMessage=N'Keine Vector-Index-Wartungsauffälligkeit im sichtbaren Scope';
    ELSE IF @OutputMode='RAW'
    BEGIN
        SELECT * FROM [#VectorIndexAnalysis_ModuleStatus];
        SELECT TOP(@Limit) * FROM [#VectorIndexAnalysis_VectorIndexes]
        ORDER BY [DatabaseName],[SchemaName],[ObjectName],[IndexName];
        SELECT TOP(@Limit) * FROM [#VectorIndexAnalysis_Maintenance]
        ORDER BY [DatabaseName],[SchemaName],[ObjectName],[IndexName];
        SELECT TOP(@Limit) * FROM [#VectorIndexAnalysis_Findings]
        ORDER BY CASE [Severity] WHEN 'WARN' THEN 1 ELSE 2 END,[FindingOrdinal];
        SELECT * FROM [#VectorIndexAnalysis_SourceStatus] ORDER BY [SourceOrdinal];
        SELECT * FROM [#VectorIndexAnalysis_Warnings] ORDER BY [WarningOrdinal];
    END
    ELSE IF @OutputMode='TABLE'
    BEGIN
        DECLARE @ResultName sysname,@TargetTable sysname,@SourceTable sysname;
        DECLARE [ResultCursor] CURSOR LOCAL FAST_FORWARD FOR
            SELECT [ResultName],[TargetTable]
            FROM [#VectorIndexAnalysis_ResultTableMap]
            ORDER BY [ResultName];
        OPEN [ResultCursor];
        FETCH NEXT FROM [ResultCursor] INTO @ResultName,@TargetTable;
        WHILE @@FETCH_STATUS=0
        BEGIN
            SET @SourceTable=CASE @ResultName
                WHEN N'moduleStatus' THEN N'#VectorIndexAnalysis_ModuleStatus'
                WHEN N'vectorIndexes' THEN N'#VectorIndexAnalysis_VectorIndexes'
                WHEN N'maintenance' THEN N'#VectorIndexAnalysis_Maintenance'
                WHEN N'findings' THEN N'#VectorIndexAnalysis_Findings'
                WHEN N'sourceStatus' THEN N'#VectorIndexAnalysis_SourceStatus'
                WHEN N'warnings' THEN N'#VectorIndexAnalysis_Warnings' END;
            EXEC [monitor].[InternalWriteResultTable]
                  @SourceTable=@SourceTable
                , @TargetTable=@TargetTable
                , @ThrowOnError=1;
            FETCH NEXT FROM [ResultCursor] INTO @ResultName,@TargetTable;
        END;
        CLOSE [ResultCursor];
        DEALLOCATE [ResultCursor];
    END;

    IF @PrintMeldungen=1 AND @StatusCode NOT IN('AVAILABLE','AVAILABLE_WITH_FINDING','NOT_APPLICABLE')
    BEGIN
        DECLARE @PrintMessage nvarchar(2048)=LEFT(CONCAT(N'USP_VectorIndexAnalysis: ',@StatusCode,N'. ',COALESCE(@ErrorMessage,N'Siehe sourceStatus und warnings.')),2048);
        RAISERROR(N'%s',10,1,@PrintMessage) WITH NOWAIT;
    END;

    SELECT @StatusCodeOut=@StatusCode,@IsPartialOut=@IsPartial,
           @ErrorNumberOut=@ErrorNumber,@ErrorMessageOut=@ErrorMessage;
END;
GO
-- END SOURCE: Code/03_ObjectIndex/075_USP_VectorIndexAnalysis.sql

-- BEGIN SOURCE: Code/03_ObjectIndex/090_USP_SchemaDesignAnalysis.sql
/*
===============================================================================
Objekt       : monitor.USP_SchemaDesignAnalysis
Version      : 1.0.0
Stand        : 2026-07-17
Zweck        : Findet belastbare Schema-/Designindikatoren je Datenbank.
Datenquellen : sys.foreign_keys, sys.foreign_key_columns,
               sys.check_constraints, sys.indexes, sys.index_columns,
               sys.identity_columns, sys.sequences, sys.objects und sys.schemas.
Prüfungen    : deaktivierte/nicht vertrauenswürdige Constraints,
               fehlender FK-Stützindex, hypothetische/deaktivierte und exakt
               gleiche Indizes sowie Identity-/Sequence-Wertebereich.
Grenzen      : Kein DDL und keine automatische Lösch-/Indexempfehlung. Nutzung,
               Workload, Filtersemantik und Änderungsrisiko separat prüfen.
===============================================================================
*/
CREATE OR ALTER PROCEDURE [monitor].[USP_SchemaDesignAnalysis]
      @DatabaseNames                nvarchar(max)  = NULL
    , @SystemdatenbankenEinbeziehen bit            = 0
    , @DatabaseNamePattern          nvarchar(4000) = NULL
    , @HighImpactConfirmed              bit            = 0
    , @IdentityWarnPercent          decimal(5,2)   = 80.00
    , @MaxZeilen                    int            = 1000
    , @ResultSetArt                 varchar(16)    = 'CONSOLE'
    , @ResultTablesJson               nvarchar(max) = NULL
    , @JsonErzeugen                 bit            = 0
    , @Json                         nvarchar(max)  = NULL OUTPUT
    , @PrintMeldungen               bit            = 1
    , @Hilfe                        bit            = 0
    , @StatusCodeOut                varchar(40)    = NULL OUTPUT
    , @IsPartialOut                 bit            = NULL OUTPUT
    , @ErrorNumberOut               int            = NULL OUTPUT
    , @ErrorMessageOut              nvarchar(2048) = NULL OUTPUT
AS
BEGIN
    SET NOCOUNT ON;
    SET @Json = NULL;

    DECLARE @OutputMode varchar(16) = UPPER(LTRIM(RTRIM(COALESCE(@ResultSetArt, ''))));
    DECLARE @TableResultRequested bit = CASE WHEN @OutputMode = 'TABLE' THEN 1 ELSE 0 END;
    DECLARE @ConsoleResultRequested bit = CASE WHEN @OutputMode = 'CONSOLE' THEN 1 ELSE 0 END;
    DECLARE @TableTarget sysname=NULL;
    IF @TableResultRequested=0 AND NULLIF(LTRIM(RTRIM(COALESCE(@ResultTablesJson,N''))),N'') IS NOT NULL THROW 51011,N'@ResultTablesJson ist ausschließlich mit @ResultSetArt=TABLE zulässig.',1;
    IF @TableResultRequested=1 EXEC [monitor].[InternalPrepareSingleResultTable] @ResultTablesJson=@ResultTablesJson,@ResultName=N'findings',@TargetTable=@TableTarget OUTPUT,@ThrowOnError=1;
    IF @TableResultRequested = 1 OR @ConsoleResultRequested = 1 SET @OutputMode = 'NONE';
    DECLARE @Limit bigint = CASE WHEN @MaxZeilen IS NULL OR @MaxZeilen = 0
                                 THEN CONVERT(bigint, 9223372036854775807)
                                 ELSE CONVERT(bigint, @MaxZeilen) END;

    IF @Hilfe = 1
    BEGIN
        PRINT N'monitor.USP_SchemaDesignAnalysis';
        PRINT N'Die Procedure führt eine rein lesende Strukturprüfung durch und erzeugt oder ändert keine Constraints und Indizes.';
        PRINT N'@DatabaseNames: bracket-aware Pipe-Liste; N''''/NULL = keine Datenbankeinschränkung.';
        PRINT N'Ein gleicher Index oder fehlender FK-Stützindex ist ein Prüfauftrag, keine automatische DDL-Anweisung.';
        RETURN;
    END;

    DECLARE @Now datetime2(3) = SYSUTCDATETIME();
    DECLARE @StatusCode varchar(40) = 'AVAILABLE';
    DECLARE @IsPartial bit = 0;
    DECLARE @ErrorNumber int = NULL;
    DECLARE @ErrorMessage nvarchar(2048) = NULL;
    DECLARE @CrossDatabaseRequested bit = 0;
    DECLARE @Db sysname;
    DECLARE @Sql nvarchar(max);

    CREATE TABLE [#SchemaDesignAnalysis_DatabaseCandidates]
    (
          [DatabaseId] int NOT NULL PRIMARY KEY
        , [DatabaseName] sysname NOT NULL
        , [StateDesc] nvarchar(60) NULL
        , [UserAccessDesc] nvarchar(60) NULL
        , [IsReadOnly] bit NULL
        , [CompatibilityLevel] tinyint NULL
        , [CollationName] sysname NULL
        , [RecoveryModelDesc] nvarchar(60) NULL
        , [IsSystemDatabase] bit NULL
        , [RequestedOrdinal] int NULL
    );
    CREATE TABLE [#SchemaDesignAnalysis_DatabaseCandidateWarnings]
    (
          [RequestedName] sysname NULL
        , [StatusCode] varchar(40) NOT NULL
        , [ErrorMessage] nvarchar(2048) NULL
    );
    CREATE TABLE [#SchemaDesignAnalysis_Findings]
    (
          [DatabaseId] int NOT NULL
        , [DatabaseName] sysname NOT NULL
        , [FindingCode] varchar(100) NOT NULL
        , [Severity] varchar(16) NOT NULL
        , [ObjectType] nvarchar(60) NULL
        , [SchemaName] sysname NULL
        , [ObjectName] sysname NULL
        , [RelatedObjectName] sysname NULL
        , [MetricValue] decimal(38,4) NULL
        , [Evidence] nvarchar(1000) NOT NULL
        , [EvidenceLimit] nvarchar(1000) NOT NULL
    );
    CREATE TABLE [#SchemaDesignAnalysis_Errors]
    (
          [DatabaseName] sysname NULL
        , [StatusCode] varchar(40) NOT NULL
        , [ErrorNumber] int NULL
        , [ErrorMessage] nvarchar(2048) NULL
    );

    IF @MaxZeilen < 0
       OR @IdentityWarnPercent < 0 OR @IdentityWarnPercent > 100
       OR @OutputMode NOT IN ('RAW', 'CONSOLE', 'NONE')
    BEGIN
        SELECT @StatusCode = 'INVALID_PARAMETER', @IsPartial = 1,
               @ErrorMessage = N'Ungültiger Datenbank-, Grenzwert-, Zeilen- oder Ausgabeparameter.';
    END;

    IF @StatusCode = 'AVAILABLE'
    BEGIN
        EXEC [monitor].[USP_PrepareDatabaseCandidates]
              @DatabaseNames = @DatabaseNames
            , @SystemdatenbankenEinbeziehen = @SystemdatenbankenEinbeziehen
            , @DatabaseNamePattern = @DatabaseNamePattern,@HighImpactConfirmed=@HighImpactConfirmed

            , @AnalysisClass = 'CATALOG_DEEP'
            , @StatusCode = @StatusCode OUTPUT
            , @ErrorMessage = @ErrorMessage OUTPUT
            , @CrossDatabaseRequested = @CrossDatabaseRequested OUTPUT,@CandidateTable=N'#SchemaDesignAnalysis_DatabaseCandidates',@WarningTable=N'#SchemaDesignAnalysis_DatabaseCandidateWarnings';
    END;

    SET LOCK_TIMEOUT 0;

    IF @StatusCode = 'AVAILABLE'
    BEGIN
        DECLARE [database_cursor] CURSOR LOCAL FAST_FORWARD FOR
            SELECT [DatabaseName] FROM [#SchemaDesignAnalysis_DatabaseCandidates]
            ORDER BY COALESCE([RequestedOrdinal], [DatabaseId]), [DatabaseId];
        OPEN [database_cursor];
        FETCH NEXT FROM [database_cursor] INTO @Db;

        WHILE @@FETCH_STATUS = 0
        BEGIN
            BEGIN TRY
                SET @Sql = N'USE ' + QUOTENAME(@Db) + N';
DECLARE @DatabaseId int = DB_ID();
DECLARE @DatabaseName sysname = (SELECT [name] FROM [master].[sys].[databases] WITH (NOLOCK) WHERE [database_id] = DB_ID());

INSERT [#SchemaDesignAnalysis_Findings]
SELECT @DatabaseId, @DatabaseName,
       CASE WHEN [fk].[is_disabled] = 1 THEN ''FOREIGN_KEY_DISABLED'' ELSE ''FOREIGN_KEY_NOT_TRUSTED'' END,
       CASE WHEN [fk].[is_disabled] = 1 THEN ''HIGH'' ELSE ''MEDIUM'' END,
       N''FOREIGN_KEY'', [s].[name], [t].[name], [fk].[name], NULL,
       CONCAT(N''is_disabled='', [fk].[is_disabled], N''; is_not_trusted='', [fk].[is_not_trusted]),
       N''Aktivierung beziehungsweise WITH CHECK erfordert fachliche Prüfung und ist nicht Bestandteil dieser Analyse.''
FROM [sys].[foreign_keys] AS [fk] WITH (NOLOCK)
JOIN [sys].[tables] AS [t] WITH (NOLOCK) ON [t].[object_id] = [fk].[parent_object_id]
JOIN [sys].[schemas] AS [s] WITH (NOLOCK) ON [s].[schema_id] = [t].[schema_id]
WHERE [fk].[is_disabled] = 1 OR [fk].[is_not_trusted] = 1;

INSERT [#SchemaDesignAnalysis_Findings]
SELECT @DatabaseId, @DatabaseName,
       CASE WHEN [cc].[is_disabled] = 1 THEN ''CHECK_CONSTRAINT_DISABLED'' ELSE ''CHECK_CONSTRAINT_NOT_TRUSTED'' END,
       CASE WHEN [cc].[is_disabled] = 1 THEN ''HIGH'' ELSE ''MEDIUM'' END,
       N''CHECK_CONSTRAINT'', [s].[name], [t].[name], [cc].[name], NULL,
       CONCAT(N''is_disabled='', [cc].[is_disabled], N''; is_not_trusted='', [cc].[is_not_trusted]),
       N''Constraintdefinition und Datenqualität vor einer Änderung separat validieren.''
FROM [sys].[check_constraints] AS [cc] WITH (NOLOCK)
JOIN [sys].[tables] AS [t] WITH (NOLOCK) ON [t].[object_id] = [cc].[parent_object_id]
JOIN [sys].[schemas] AS [s] WITH (NOLOCK) ON [s].[schema_id] = [t].[schema_id]
WHERE [cc].[is_disabled] = 1 OR [cc].[is_not_trusted] = 1;

INSERT [#SchemaDesignAnalysis_Findings]
SELECT @DatabaseId, @DatabaseName, ''FOREIGN_KEY_WITHOUT_SUPPORTING_INDEX'', ''MEDIUM'',
       N''FOREIGN_KEY'', [s].[name], [t].[name], [fk].[name],
       CONVERT(decimal(38,4), COUNT_BIG([fkc].[constraint_column_id])),
       N''Kein aktiver Index beginnt in gleicher Reihenfolge mit allen referenzierenden FK-Spalten.'',
       N''Workload, Selektivität, Schreibkosten und ein eventuell breiterer geeigneter Index müssen separat geprüft werden.''
FROM [sys].[foreign_keys] AS [fk] WITH (NOLOCK)
JOIN [sys].[tables] AS [t] WITH (NOLOCK) ON [t].[object_id] = [fk].[parent_object_id]
JOIN [sys].[schemas] AS [s] WITH (NOLOCK) ON [s].[schema_id] = [t].[schema_id]
JOIN [sys].[foreign_key_columns] AS [fkc] WITH (NOLOCK) ON [fkc].[constraint_object_id] = [fk].[object_id]
WHERE [fk].[is_disabled] = 0
  AND NOT EXISTS
  (
      SELECT 1
      FROM [sys].[indexes] AS [i] WITH (NOLOCK)
      WHERE [i].[object_id] = [fk].[parent_object_id]
        AND [i].[index_id] > 0 AND [i].[is_disabled] = 0 AND [i].[is_hypothetical] = 0
        AND [i].[has_filter] = 0
        AND NOT EXISTS
        (
            SELECT 1
            FROM [sys].[foreign_key_columns] AS [fc] WITH (NOLOCK)
            LEFT JOIN [sys].[index_columns] AS [ic] WITH (NOLOCK)
              ON [ic].[object_id] = [i].[object_id] AND [ic].[index_id] = [i].[index_id]
             AND [ic].[key_ordinal] = [fc].[constraint_column_id]
            WHERE [fc].[constraint_object_id] = [fk].[object_id]
              AND ([ic].[column_id] IS NULL OR [ic].[column_id] <> [fc].[parent_column_id])
        )
  )
GROUP BY [s].[name], [t].[name], [fk].[name];

INSERT [#SchemaDesignAnalysis_Findings]
SELECT @DatabaseId, @DatabaseName,
       CASE WHEN [i].[is_hypothetical] = 1 THEN ''HYPOTHETICAL_INDEX'' ELSE ''INDEX_DISABLED'' END,
       CASE WHEN [i].[is_hypothetical] = 1 THEN ''INFO'' ELSE ''MEDIUM'' END,
       N''INDEX'', [s].[name], [t].[name], [i].[name], NULL,
       CONCAT(N''index_id='', [i].[index_id]),
       N''Nicht automatisch löschen oder aktivieren; Ursprung, Abhängigkeiten und Wartungsabsicht prüfen.''
FROM [sys].[indexes] AS [i] WITH (NOLOCK)
JOIN [sys].[tables] AS [t] WITH (NOLOCK) ON [t].[object_id] = [i].[object_id]
JOIN [sys].[schemas] AS [s] WITH (NOLOCK) ON [s].[schema_id] = [t].[schema_id]
WHERE [i].[index_id] > 0 AND ([i].[is_hypothetical] = 1 OR [i].[is_disabled] = 1);

INSERT [#SchemaDesignAnalysis_Findings]
SELECT @DatabaseId, @DatabaseName, ''EXACT_INDEX_DEFINITION_DUPLICATE'', ''MEDIUM'',
       N''INDEX'', [s].[name], [t].[name], CONCAT([i1].[name], N'' | '', [i2].[name]), NULL,
       N''Schlüssel-/Include-Spalten, Sortierung, Eindeutigkeit und Filterdefinition sind katalogseitig gleich.'',
       N''Nutzung, Abhängigkeiten, Constraints, Kompression und betriebliche Anforderungen vor einer Änderung prüfen.''
FROM [sys].[indexes] AS [i1] WITH (NOLOCK)
JOIN [sys].[indexes] AS [i2] WITH (NOLOCK)
  ON [i2].[object_id] = [i1].[object_id] AND [i2].[index_id] > [i1].[index_id]
JOIN [sys].[tables] AS [t] WITH (NOLOCK) ON [t].[object_id] = [i1].[object_id]
JOIN [sys].[schemas] AS [s] WITH (NOLOCK) ON [s].[schema_id] = [t].[schema_id]
WHERE [i1].[index_id] > 0
  AND [i1].[type] IN (1, 2) AND [i2].[type] = [i1].[type]
  AND [i1].[is_hypothetical] = 0 AND [i2].[is_hypothetical] = 0
  AND [i1].[is_disabled] = 0 AND [i2].[is_disabled] = 0
  AND [i1].[is_unique] = [i2].[is_unique]
  AND COALESCE([i1].[filter_definition], N'''') = COALESCE([i2].[filter_definition], N'''')
  AND NOT EXISTS
  (
      SELECT [column_id], [key_ordinal], [is_descending_key], [is_included_column]
      FROM [sys].[index_columns] WITH (NOLOCK) WHERE [object_id] = [i1].[object_id] AND [index_id] = [i1].[index_id]
      EXCEPT
      SELECT [column_id], [key_ordinal], [is_descending_key], [is_included_column]
      FROM [sys].[index_columns] WITH (NOLOCK) WHERE [object_id] = [i2].[object_id] AND [index_id] = [i2].[index_id]
  )
  AND NOT EXISTS
  (
      SELECT [column_id], [key_ordinal], [is_descending_key], [is_included_column]
      FROM [sys].[index_columns] WITH (NOLOCK) WHERE [object_id] = [i2].[object_id] AND [index_id] = [i2].[index_id]
      EXCEPT
      SELECT [column_id], [key_ordinal], [is_descending_key], [is_included_column]
      FROM [sys].[index_columns] WITH (NOLOCK) WHERE [object_id] = [i1].[object_id] AND [index_id] = [i1].[index_id]
  );

;WITH [IdentityRange] AS
(
    SELECT [ic].[object_id], [ic].[name], [ic].[system_type_id],
           TRY_CONVERT(decimal(38,0), [ic].[last_value]) AS [CurrentValue],
           TRY_CONVERT(decimal(38,0), [ic].[increment_value]) AS [IncrementValue],
           CONVERT(decimal(38,0), CASE [ic].[system_type_id]
                    WHEN 48 THEN 0 WHEN 52 THEN -32768 WHEN 56 THEN -2147483648
                    WHEN 127 THEN -9223372036854775808 END) AS [TypeMin],
           CONVERT(decimal(38,0), CASE [ic].[system_type_id]
                    WHEN 48 THEN 255 WHEN 52 THEN 32767 WHEN 56 THEN 2147483647
                    WHEN 127 THEN 9223372036854775807 END) AS [TypeMax]
    FROM [sys].[identity_columns] AS [ic] WITH (NOLOCK)
    WHERE [ic].[system_type_id] IN (48, 52, 56, 127) AND [ic].[last_value] IS NOT NULL
),
[IdentityUsage] AS
(
    SELECT [r].*, CONVERT(decimal(38,4),
           CASE WHEN [r].[IncrementValue] >= 0
                THEN 100.0 * ([r].[CurrentValue] - [r].[TypeMin]) / NULLIF([r].[TypeMax] - [r].[TypeMin], 0)
                ELSE 100.0 * ([r].[TypeMax] - [r].[CurrentValue]) / NULLIF([r].[TypeMax] - [r].[TypeMin], 0) END) AS [UsedPercent]
    FROM [IdentityRange] AS [r]
)
INSERT [#SchemaDesignAnalysis_Findings]
SELECT @DatabaseId, @DatabaseName, ''IDENTITY_TYPE_RANGE_USAGE'',
       CASE WHEN [u].[UsedPercent] >= 95 THEN ''HIGH'' ELSE ''MEDIUM'' END,
       N''IDENTITY_COLUMN'', [s].[name], [t].[name], [u].[name], [u].[UsedPercent],
       CONCAT(N''Typwertebereich genutzt: '', CONVERT(nvarchar(60), [u].[UsedPercent]), N'' Prozent.''),
       N''Berechnung nutzt den vollständigen numerischen Typwertebereich; Seed, Reseed, Zyklen und Fachsemantik separat prüfen.''
FROM [IdentityUsage] AS [u]
JOIN [sys].[tables] AS [t] WITH (NOLOCK) ON [t].[object_id] = [u].[object_id]
JOIN [sys].[schemas] AS [s] WITH (NOLOCK) ON [s].[schema_id] = [t].[schema_id]
WHERE [u].[UsedPercent] >= @IdentityWarnPercent;

INSERT [#SchemaDesignAnalysis_Findings]
SELECT @DatabaseId, @DatabaseName, ''SEQUENCE_RANGE_USAGE'',
       CASE WHEN [q].[is_exhausted] = 1 OR [x].[UsedPercent] >= 95 THEN ''HIGH'' ELSE ''MEDIUM'' END,
       N''SEQUENCE'', [s].[name], [q].[name], NULL, [x].[UsedPercent],
       CONCAT(N''is_exhausted='', [q].[is_exhausted], N''; Typwertebereich genutzt: '',
              CONVERT(nvarchar(60), [x].[UsedPercent]), N'' Prozent.''),
       N''Cache, CYCLE, Sprünge und fachlich erlaubte Wertebereiche separat prüfen.''
FROM [sys].[sequences] AS [q] WITH (NOLOCK)
JOIN [sys].[schemas] AS [s] WITH (NOLOCK) ON [s].[schema_id] = [q].[schema_id]
CROSS APPLY
(
    SELECT CONVERT(decimal(38,4),
           CASE WHEN TRY_CONVERT(decimal(38,0), [q].[increment]) >= 0
                THEN 100.0 * (TRY_CONVERT(decimal(38,0), [q].[current_value]) - TRY_CONVERT(decimal(38,0), [q].[minimum_value]))
                   / NULLIF(TRY_CONVERT(decimal(38,0), [q].[maximum_value]) - TRY_CONVERT(decimal(38,0), [q].[minimum_value]), 0)
                ELSE 100.0 * (TRY_CONVERT(decimal(38,0), [q].[maximum_value]) - TRY_CONVERT(decimal(38,0), [q].[current_value]))
                   / NULLIF(TRY_CONVERT(decimal(38,0), [q].[maximum_value]) - TRY_CONVERT(decimal(38,0), [q].[minimum_value]), 0) END) AS [UsedPercent]
) AS [x]
WHERE [q].[is_exhausted] = 1 OR [x].[UsedPercent] >= @IdentityWarnPercent;';

                EXEC [sys].[sp_executesql]
                      @Sql
                    , N'@IdentityWarnPercent decimal(5,2)'
                    , @IdentityWarnPercent = @IdentityWarnPercent;
            END TRY
            BEGIN CATCH
                INSERT [#SchemaDesignAnalysis_Errors]
                VALUES (@Db,
                        CASE WHEN ERROR_NUMBER() IN (229, 262, 297, 300, 371, 916)
                             THEN 'DENIED_PERMISSION' ELSE 'ERROR_HANDLED' END,
                        ERROR_NUMBER(), ERROR_MESSAGE());
                SET @IsPartial = 1;
            END CATCH;

            FETCH NEXT FROM [database_cursor] INTO @Db;
        END;
        CLOSE [database_cursor];
        DEALLOCATE [database_cursor];

        INSERT [#SchemaDesignAnalysis_Errors]
        SELECT [RequestedName], [StatusCode], NULL, [ErrorMessage]
        FROM [#SchemaDesignAnalysis_DatabaseCandidateWarnings];
        IF EXISTS (SELECT 1 FROM [#SchemaDesignAnalysis_Errors]) SET @IsPartial = 1;

        IF NOT EXISTS (SELECT 1 FROM [#SchemaDesignAnalysis_DatabaseCandidates])
            SELECT @StatusCode = 'DATABASE_UNAVAILABLE', @IsPartial = 1;
        ELSE IF @IsPartial = 1
            SET @StatusCode = 'AVAILABLE_LIMITED';
        ELSE IF EXISTS (SELECT 1 FROM [#SchemaDesignAnalysis_Findings])
            SET @StatusCode = 'AVAILABLE_WITH_FINDING';
    END;

    SELECT @StatusCodeOut = @StatusCode, @IsPartialOut = @IsPartial,
           @ErrorNumberOut = @ErrorNumber, @ErrorMessageOut = @ErrorMessage;

    IF @JsonErzeugen = 1
    BEGIN
        DECLARE @MetaJson nvarchar(max) =
            (SELECT N'SchemaDesignAnalysis' AS [resultName], 1 AS [schemaVersion],
                    @Now AS [generatedAtUtc], @StatusCode AS [statusCode], @IsPartial AS [isPartial],
                    @IdentityWarnPercent AS [identityWarnPercent]
             FOR JSON PATH, WITHOUT_ARRAY_WRAPPER);
        DECLARE @FindingsJson nvarchar(max) =
            (SELECT TOP (@Limit) * FROM [#SchemaDesignAnalysis_Findings]
             ORDER BY CASE [Severity] WHEN 'HIGH' THEN 1 WHEN 'MEDIUM' THEN 2 ELSE 3 END,
                      [DatabaseId], [SchemaName], [ObjectName], [FindingCode]
             FOR JSON PATH, INCLUDE_NULL_VALUES);
        DECLARE @WarningsJson nvarchar(max) =
            (SELECT * FROM [#SchemaDesignAnalysis_Errors] ORDER BY [DatabaseName] FOR JSON PATH, INCLUDE_NULL_VALUES);
        SET @Json = CONCAT(N'{"meta":', COALESCE(@MetaJson, N'{}'),
                           N',"findings":', COALESCE(@FindingsJson, N'[]'),
                           N',"warnings":', COALESCE(@WarningsJson, N'[]'), N'}');
    END;

    IF @OutputMode = 'RAW'
    BEGIN
        SELECT N'USP_SchemaDesignAnalysis' AS [ModuleName], @Now AS [CollectionTimeUtc],
               @StatusCode AS [StatusCode], @IsPartial AS [IsPartial],
               @ErrorNumber AS [ErrorNumber], @ErrorMessage AS [ErrorMessage],
               N'Read-only; Befunde sind Prüfaufträge, keine DDL-Anweisungen.' AS [Detail];
        SELECT TOP (@Limit) * FROM [#SchemaDesignAnalysis_Findings]
        ORDER BY CASE [Severity] WHEN 'HIGH' THEN 1 WHEN 'MEDIUM' THEN 2 ELSE 3 END,
                 [DatabaseId], [SchemaName], [ObjectName], [FindingCode];
        SELECT * FROM [#SchemaDesignAnalysis_Errors] ORDER BY [DatabaseName];
    END
    ELSE IF @OutputMode = 'CONSOLE'
    BEGIN
        SELECT N'Schema- und Designkorrektheit' AS [Ergebnis], @Now AS [Stand_UTC],
               @StatusCode AS [Status], (SELECT COUNT_BIG(*) FROM [#SchemaDesignAnalysis_Findings]) AS [Befunde],
               @ErrorMessage AS [Hinweis];
        SELECT TOP (@Limit) N'Schema-Befund' AS [Ergebnis], [DatabaseName] AS [Datenbank],
               [SchemaName] AS [Schema], [ObjectName] AS [Objekt],
               [RelatedObjectName] AS [Bezug], [FindingCode] AS [Befund],
               [Severity] AS [Prioritaet], [MetricValue] AS [Messwert],
               [Evidence] AS [Evidenz], [EvidenceLimit] AS [Grenze]
        FROM [#SchemaDesignAnalysis_Findings]
        ORDER BY CASE [Severity] WHEN 'HIGH' THEN 1 WHEN 'MEDIUM' THEN 2 ELSE 3 END,
                 [DatabaseId], [SchemaName], [ObjectName], [FindingCode];
        SELECT N'Schema-Warnung' AS [Ergebnis], [DatabaseName] AS [Datenbank],
               [StatusCode] AS [Status], [ErrorNumber] AS [Fehlernummer], [ErrorMessage] AS [Meldung]
        FROM [#SchemaDesignAnalysis_Errors] ORDER BY [DatabaseName];
    END;
    IF @ConsoleResultRequested = 1
    BEGIN
        EXEC [monitor].[InternalEmitConsoleResult]
              @SourceTable=N'#SchemaDesignAnalysis_Findings'
            , @ResultLabel=N'SchemaDesignAnalysis'
            , @EmptyMessage=N'Keine fachlichen Ergebnisse';
    END;
    IF @TableResultRequested = 1
    BEGIN
        EXEC [monitor].[InternalWriteResultTable]
              @SourceTable = N'#SchemaDesignAnalysis_Findings'
            , @TargetTable=@TableTarget
            , @ThrowOnError = 1;
    END;
END;
GO
-- END SOURCE: Code/03_ObjectIndex/090_USP_SchemaDesignAnalysis.sql

-- BEGIN SOURCE: Code/03_ObjectIndex/080_USP_ObjectAnalysis.sql
/*
===============================================================================
Objekt       : monitor.USP_ObjectAnalysis
Version      : 2.4.0
Stand        : 2026-07-23
Typ          : Stored Procedure
Zweck        : Orchestriert die Objekt-, Index-, Statistik-, Partition-,
               Columnstore-, Vector-Index- und Physical-Stats-Analysen mit
               einem einheitlichen Listen-, Pattern- und Ausgabevertrag.
               Das ObjectInventory ergänzt capability-adaptiv sichtbare
               SQL-Server-2025-JSON-Indizes und deren SQL/JSON-Pfade.
SQL-Version  : SQL Server 2019 oder neuer.
Parameter    : @DatabaseNames, @DatabaseNamePattern, @SchemaNames,
               @SchemaNamePattern, @ObjectNames, @ObjectNamePattern,
               @FullObjectNames, @IndexNames, @IndexNamePattern,
               @StatisticsNames, @StatisticsNamePattern, Modulschalter,
               @MaxZeilen, @ResultSetArt,
               @JsonErzeugen, @Json OUTPUT, @PrintMeldungen, @Hilfe.
Semantik     : Exakte Listen sind bracket-aware Pipe-Listen; Pattern sind
               einzelne LIKE-/Regex-Ausdrücke. Exakte Liste und Pattern
               derselben Eigenschaft sind gegenseitig exklusiv.
Ausgabe      : Aktivierte Teilmodule liefern RAW oder CONSOLE. NONE unterdrückt
               fachliche Resultsets. JSON enthält die Teilmodul-Envelopes unter
               benannten Eigenschaften und einen Orchestratorstatus.
Locking      : Der angeforderte LOCK_TIMEOUT gilt für den Childlauf; der
               vorherige Sessionwert wird vor der Ausgabe wiederhergestellt.
Änderungen   : 2.4.0 - SQL25-002-JSON-Indexmetadaten über das bestehende
                         ObjectInventory in den Orchestratorvertrag aufgenommen.
               2.3.0 - SQL-Server-2025-Vector-Index-Laufzeitanalyse als
                          capability-adaptives opt-in Teilmodul integriert.
               2.2.0 - Begrenzte Statistikverteilungsanalyse als opt-in
                         Teilmodul integriert.
               2.1.0 - Schema-/Designkorrektheit als opt-in Teilmodul.
               2.0.0 - Mehrfachfilter, getrennte Pattern, Cross-Database-Scope,
                         RAW/CONSOLE/NONE und JSON-Orchestrierung.
               1.3.0 - Vorheriger Stand.
===============================================================================
*/
CREATE OR ALTER PROCEDURE [monitor].[USP_ObjectAnalysis]
      @DatabaseNames                    nvarchar(max)  = NULL
    , @SystemdatenbankenEinbeziehen     bit            = 0
    , @DatabaseNamePattern              nvarchar(4000) = NULL
    , @HighImpactConfirmed              bit            = 0
    , @SchemaNames                      nvarchar(max)  = NULL
    , @SchemaNamePattern                nvarchar(4000) = NULL
    , @ObjectNames                      nvarchar(max)  = NULL
    , @ObjectNamePattern                nvarchar(4000) = NULL
    , @FullObjectNames                  nvarchar(max)  = NULL
    , @IndexNames                       nvarchar(max)  = NULL
    , @IndexNamePattern                 nvarchar(4000) = NULL
    , @StatisticsNames                  nvarchar(max)  = NULL
    , @StatisticsNamePattern            nvarchar(4000) = NULL
    , @Vollanalyse                      bit            = 0
    , @MitObjectInventory               bit            = 1
    , @MitIndexUsage                    bit            = 1
    , @MitMissingIndexes                bit            = 1
    , @MitOperationalStats              bit            = 0
    , @MitStatistics                    bit            = 0
    , @MitStatisticsDistribution        bit            = 0
    , @MitPartitions                    bit            = 0
    , @MitColumnstore                   bit            = 0
    , @MitPhysicalStats                 bit            = 0
    , @MitVectorIndexes                 bit            = 0
    , @MitSchemaDesign                  bit            = 0
    , @MaxZeilen                        int            = 2000
    , @LockTimeoutMs                    int            = 0
    , @ResultSetArt                     varchar(16)    = 'CONSOLE'
    , @ResultTablesJson               nvarchar(max) = NULL
    , @JsonErzeugen                     bit            = 0
    , @Json                             nvarchar(max)  = NULL OUTPUT
    , @PrintMeldungen                   bit            = 1
    , @Hilfe                            bit            = 0
AS
BEGIN
    SET NOCOUNT ON;
    SET @Json = NULL;
    DECLARE @OriginalLockTimeout int=@@LOCK_TIMEOUT;
    DECLARE @LockTimeoutSql nvarchar(64);

    DECLARE @ResultSetArtNormalisiert varchar(16) = UPPER(LTRIM(RTRIM(COALESCE(@ResultSetArt, ''))));
    DECLARE @TableResultRequested bit = CASE WHEN @ResultSetArtNormalisiert = 'TABLE' THEN 1 ELSE 0 END;
    DECLARE @ConsoleResultRequested bit = CASE WHEN @ResultSetArtNormalisiert = 'CONSOLE' THEN 1 ELSE 0 END;
    DECLARE @TableTarget sysname=NULL;
    IF @TableResultRequested=0 AND NULLIF(LTRIM(RTRIM(COALESCE(@ResultTablesJson,N''))),N'') IS NOT NULL THROW 51011,N'@ResultTablesJson ist ausschließlich mit @ResultSetArt=TABLE zulässig.',1;
    IF @TableResultRequested=1 EXEC [monitor].[InternalPrepareSingleResultTable] @ResultTablesJson=@ResultTablesJson,@ResultName=N'moduleStatus',@TargetTable=@TableTarget OUTPUT,@ThrowOnError=1;
    IF @TableResultRequested = 1 OR @ConsoleResultRequested = 1 SET @ResultSetArtNormalisiert = 'NONE';
    DECLARE @AnalyseModus varchar(16) = CASE WHEN @Vollanalyse = 1 THEN 'VOLL' ELSE 'GEZIELT' END;
    DECLARE @CollectionTimeUtc datetime2(3) = SYSUTCDATETIME();
    DECLARE @StatusCode varchar(40) = 'AVAILABLE';
    DECLARE @IsPartial bit = 0;
    DECLARE @ErrorMessage nvarchar(2048) = NULL;
    DECLARE @MonitorPrintMessage nvarchar(2048);

    IF @Hilfe = 1
    BEGIN
        PRINT N'monitor.USP_ObjectAnalysis';
        PRINT N'@DatabaseNames=N''[Db1]|[Db2]''; NULL=alle; @DatabaseNamePattern separat.';
        PRINT N'@SchemaNames/@ObjectNames/@IndexNames/@StatisticsNames sind bracket-aware Pipe-Listen.';
        PRINT N'@FullObjectNames unterstützt Objekt, Schema.Objekt oder Datenbank.Schema.Objekt.';
        PRINT N'Pattern unterstützen like:, regex:, regexi: und werden nicht an Pipe getrennt.';
        PRINT N'@Vollanalyse=0 nutzt GEZIELT; ressourcenintensive Teilmodule bleiben zusätzlich gruppengeschützt.';
        PRINT N'@MitStatisticsDistribution=1 aktiviert die begrenzte, CATALOG_DEEP-geschützte Histogramm-/Partitionsverteilung.';
        PRINT N'@MitObjectInventory=1 ergänzt ab SQL Server 2025 sichtbare JSON-Indizes und SQL/JSON-Pfade; JSON-Dokumentwerte werden nicht gelesen.';
        PRINT N'@MitVectorIndexes=1 aktiviert die versionsadaptive Vector-Index-Katalog- und Wartungsanalyse; auf älteren Versionen bleibt der Childstatus explizit UNAVAILABLE_VERSION.';
        PRINT N'@ResultSetArt=CONSOLE (Default)|RAW|TABLE|NONE (case-insensitiv); @JsonErzeugen=1 erzeugt benannte Teilmodule in @Json.';
        RETURN;
    END;

    CREATE TABLE [#ObjectAnalysis_ModuleStatus]
    (
          [ModuleName] sysname NOT NULL
        , [StatusCode] varchar(40) NOT NULL
        , [ErrorNumber] int NULL
        , [ErrorMessage] nvarchar(2048) NULL
    );

    IF @MaxZeilen < 0 OR @LockTimeoutMs NOT BETWEEN 0 AND 60000
       OR @ResultSetArtNormalisiert NOT IN ('RAW','CONSOLE','NONE')
    BEGIN
        SET @StatusCode = 'INVALID_PARAMETER';
        SET @ErrorMessage = N'Ungültige Mengen-, Lock-Timeout- oder Ausgabeparameter.';
    END;

    IF @StatusCode = 'AVAILABLE'
       AND @FullObjectNames IS NOT NULL
       AND (@SchemaNames IS NOT NULL OR @ObjectNames IS NOT NULL OR @SchemaNamePattern IS NOT NULL OR @ObjectNamePattern IS NOT NULL)
    BEGIN
        SET @StatusCode = 'INVALID_PARAMETER';
        SET @ErrorMessage = N'@FullObjectNames ist zu separaten Schema-/Objektfiltern gegenseitig exklusiv.';
    END;

    IF @StatusCode='AVAILABLE'
    BEGIN
        SET @LockTimeoutSql=N'SET LOCK_TIMEOUT '+CONVERT(nvarchar(20),@LockTimeoutMs)+N';';
        EXEC [sys].[sp_executesql] @LockTimeoutSql;
    END;

    IF @StatusCode = 'AVAILABLE'
       AND ((@SchemaNames IS NOT NULL AND @SchemaNamePattern IS NOT NULL)
         OR (@ObjectNames IS NOT NULL AND @ObjectNamePattern IS NOT NULL)
         OR (@IndexNames IS NOT NULL AND @IndexNamePattern IS NOT NULL)
         OR (@StatisticsNames IS NOT NULL AND @StatisticsNamePattern IS NOT NULL))
    BEGIN
        SET @StatusCode = 'INVALID_PARAMETER';
        SET @ErrorMessage = N'Exakte Liste und Pattern derselben Eigenschaft sind gegenseitig exklusiv.';
    END;

    DECLARE @JsonObjectInventory nvarchar(max) = NULL;
    DECLARE @JsonIndexUsage nvarchar(max) = NULL;
    DECLARE @JsonMissingIndexes nvarchar(max) = NULL;
    DECLARE @JsonOperationalStats nvarchar(max) = NULL;
    DECLARE @JsonStatistics nvarchar(max) = NULL;
    DECLARE @JsonStatisticsDistribution nvarchar(max) = NULL;
    DECLARE @JsonPartitions nvarchar(max) = NULL;
    DECLARE @JsonColumnstore nvarchar(max) = NULL;
    DECLARE @JsonPhysicalStats nvarchar(max) = NULL;
    DECLARE @JsonVectorIndexes nvarchar(max) = NULL;
    DECLARE @JsonSchemaDesign nvarchar(max) = NULL;
    DECLARE @StatisticsDistributionStatus varchar(40) = NULL;
    DECLARE @StatisticsDistributionPartial bit = NULL;
    DECLARE @StatisticsDistributionErrorNumber int = NULL;
    DECLARE @StatisticsDistributionErrorMessage nvarchar(2048) = NULL;
    DECLARE @VectorIndexStatus varchar(40) = NULL;
    DECLARE @VectorIndexPartial bit = NULL;
    DECLARE @VectorIndexErrorNumber int = NULL;
    DECLARE @VectorIndexErrorMessage nvarchar(2048) = NULL;
    DECLARE @SchemaDesignStatus varchar(40) = NULL;
    DECLARE @SchemaDesignPartial bit = NULL;
    DECLARE @SchemaDesignErrorNumber int = NULL;
    DECLARE @SchemaDesignErrorMessage nvarchar(2048) = NULL;

    IF @StatusCode = 'AVAILABLE' AND @MitObjectInventory = 1
    BEGIN TRY
        EXEC [monitor].[USP_ObjectInventory]
              @DatabaseNames=@DatabaseNames,@SystemdatenbankenEinbeziehen=@SystemdatenbankenEinbeziehen,@DatabaseNamePattern=@DatabaseNamePattern,@HighImpactConfirmed=@HighImpactConfirmed
            , @SchemaNames=@SchemaNames,@SchemaNamePattern=@SchemaNamePattern,@ObjectNames=@ObjectNames,@ObjectNamePattern=@ObjectNamePattern,@FullObjectNames=@FullObjectNames
            , @AnalyseModus=@AnalyseModus,@MaxZeilen=@MaxZeilen,@LockTimeoutMs=@LockTimeoutMs
            , @ResultSetArt=@ResultSetArtNormalisiert,@JsonErzeugen=@JsonErzeugen,@Json=@JsonObjectInventory OUTPUT,@PrintMeldungen=@PrintMeldungen;
        INSERT [#ObjectAnalysis_ModuleStatus] VALUES(N'USP_ObjectInventory',COALESCE(JSON_VALUE(@JsonObjectInventory,'$.meta.statusCode'),'EXECUTED'),NULL,NULL);
    END TRY BEGIN CATCH INSERT [#ObjectAnalysis_ModuleStatus] VALUES(N'USP_ObjectInventory','ERROR_HANDLED',ERROR_NUMBER(),ERROR_MESSAGE()); SET @IsPartial=1; END CATCH;

    IF @StatusCode = 'AVAILABLE' AND @MitIndexUsage = 1
    BEGIN TRY
        EXEC [monitor].[USP_IndexUsage]
              @DatabaseNames=@DatabaseNames,@SystemdatenbankenEinbeziehen=@SystemdatenbankenEinbeziehen,@DatabaseNamePattern=@DatabaseNamePattern,@HighImpactConfirmed=@HighImpactConfirmed
            , @SchemaNames=@SchemaNames,@SchemaNamePattern=@SchemaNamePattern,@ObjectNames=@ObjectNames,@ObjectNamePattern=@ObjectNamePattern,@FullObjectNames=@FullObjectNames
            , @AnalyseModus=@AnalyseModus,@MaxZeilen=@MaxZeilen,@LockTimeoutMs=@LockTimeoutMs
            , @ResultSetArt=@ResultSetArtNormalisiert,@JsonErzeugen=@JsonErzeugen,@Json=@JsonIndexUsage OUTPUT,@PrintMeldungen=@PrintMeldungen;
        INSERT [#ObjectAnalysis_ModuleStatus] VALUES(N'USP_IndexUsage',COALESCE(JSON_VALUE(@JsonIndexUsage,'$.meta.statusCode'),'EXECUTED'),NULL,NULL);
    END TRY BEGIN CATCH INSERT [#ObjectAnalysis_ModuleStatus] VALUES(N'USP_IndexUsage','ERROR_HANDLED',ERROR_NUMBER(),ERROR_MESSAGE()); SET @IsPartial=1; END CATCH;

    IF @StatusCode = 'AVAILABLE' AND @MitMissingIndexes = 1
    BEGIN TRY
        EXEC [monitor].[USP_MissingIndexes]
              @DatabaseNames=@DatabaseNames,@SystemdatenbankenEinbeziehen=@SystemdatenbankenEinbeziehen,@DatabaseNamePattern=@DatabaseNamePattern,@HighImpactConfirmed=@HighImpactConfirmed
            , @SchemaNames=@SchemaNames,@SchemaNamePattern=@SchemaNamePattern,@ObjectNames=@ObjectNames,@ObjectNamePattern=@ObjectNamePattern,@FullObjectNames=@FullObjectNames
            ,@MaxZeilen=@MaxZeilen,@LockTimeoutMs=@LockTimeoutMs
            , @ResultSetArt=@ResultSetArtNormalisiert,@JsonErzeugen=@JsonErzeugen,@Json=@JsonMissingIndexes OUTPUT,@PrintMeldungen=@PrintMeldungen;
        INSERT [#ObjectAnalysis_ModuleStatus] VALUES(N'USP_MissingIndexes',COALESCE(JSON_VALUE(@JsonMissingIndexes,'$.meta.statusCode'),'EXECUTED'),NULL,NULL);
    END TRY BEGIN CATCH INSERT [#ObjectAnalysis_ModuleStatus] VALUES(N'USP_MissingIndexes','ERROR_HANDLED',ERROR_NUMBER(),ERROR_MESSAGE()); SET @IsPartial=1; END CATCH;

    IF @StatusCode = 'AVAILABLE' AND @MitOperationalStats = 1
    BEGIN TRY
        EXEC [monitor].[USP_IndexOperationalStats]
              @DatabaseNames=@DatabaseNames,@SystemdatenbankenEinbeziehen=@SystemdatenbankenEinbeziehen,@DatabaseNamePattern=@DatabaseNamePattern,@HighImpactConfirmed=@HighImpactConfirmed
            , @SchemaNames=@SchemaNames,@SchemaNamePattern=@SchemaNamePattern,@ObjectNames=@ObjectNames,@ObjectNamePattern=@ObjectNamePattern,@FullObjectNames=@FullObjectNames
            , @IndexNames=@IndexNames,@IndexNamePattern=@IndexNamePattern,@AnalyseModus=@AnalyseModus
            ,@MaxZeilen=@MaxZeilen,@LockTimeoutMs=@LockTimeoutMs
            , @ResultSetArt=@ResultSetArtNormalisiert,@JsonErzeugen=@JsonErzeugen,@Json=@JsonOperationalStats OUTPUT,@PrintMeldungen=@PrintMeldungen;
        INSERT [#ObjectAnalysis_ModuleStatus] VALUES(N'USP_IndexOperationalStats',COALESCE(JSON_VALUE(@JsonOperationalStats,'$.meta.statusCode'),'EXECUTED'),NULL,NULL);
    END TRY BEGIN CATCH INSERT [#ObjectAnalysis_ModuleStatus] VALUES(N'USP_IndexOperationalStats','ERROR_HANDLED',ERROR_NUMBER(),ERROR_MESSAGE()); SET @IsPartial=1; END CATCH;

    IF @StatusCode = 'AVAILABLE' AND @MitStatistics = 1
    BEGIN TRY
        EXEC [monitor].[USP_Statistics]
              @DatabaseNames=@DatabaseNames,@SystemdatenbankenEinbeziehen=@SystemdatenbankenEinbeziehen,@DatabaseNamePattern=@DatabaseNamePattern,@HighImpactConfirmed=@HighImpactConfirmed
            , @SchemaNames=@SchemaNames,@SchemaNamePattern=@SchemaNamePattern,@ObjectNames=@ObjectNames,@ObjectNamePattern=@ObjectNamePattern,@FullObjectNames=@FullObjectNames
            , @StatisticsNames=@StatisticsNames,@StatisticsNamePattern=@StatisticsNamePattern,@AnalyseModus=@AnalyseModus
            ,@MaxZeilen=@MaxZeilen,@LockTimeoutMs=@LockTimeoutMs
            , @ResultSetArt=@ResultSetArtNormalisiert,@JsonErzeugen=@JsonErzeugen,@Json=@JsonStatistics OUTPUT,@PrintMeldungen=@PrintMeldungen;
        INSERT [#ObjectAnalysis_ModuleStatus] VALUES(N'USP_Statistics',COALESCE(JSON_VALUE(@JsonStatistics,'$.meta.statusCode'),'EXECUTED'),NULL,NULL);
    END TRY BEGIN CATCH INSERT [#ObjectAnalysis_ModuleStatus] VALUES(N'USP_Statistics','ERROR_HANDLED',ERROR_NUMBER(),ERROR_MESSAGE()); SET @IsPartial=1; END CATCH;

    IF @StatusCode = 'AVAILABLE' AND @MitStatisticsDistribution = 1
    BEGIN TRY
        EXEC [monitor].[USP_StatisticsDistributionAnalysis]
              @DatabaseNames=@DatabaseNames,@SystemdatenbankenEinbeziehen=@SystemdatenbankenEinbeziehen,@DatabaseNamePattern=@DatabaseNamePattern,@HighImpactConfirmed=@HighImpactConfirmed
            , @SchemaNames=@SchemaNames,@SchemaNamePattern=@SchemaNamePattern,@ObjectNames=@ObjectNames,@ObjectNamePattern=@ObjectNamePattern,@FullObjectNames=@FullObjectNames
            , @StatisticsNames=@StatisticsNames,@StatisticsNamePattern=@StatisticsNamePattern,@AnalyseModus=@AnalyseModus
            ,@MaxZeilen=@MaxZeilen,@LockTimeoutMs=@LockTimeoutMs
            , @ResultSetArt=@ResultSetArtNormalisiert,@JsonErzeugen=@JsonErzeugen,@Json=@JsonStatisticsDistribution OUTPUT,@PrintMeldungen=@PrintMeldungen
            , @StatusCodeOut=@StatisticsDistributionStatus OUTPUT,@IsPartialOut=@StatisticsDistributionPartial OUTPUT
            , @ErrorNumberOut=@StatisticsDistributionErrorNumber OUTPUT,@ErrorMessageOut=@StatisticsDistributionErrorMessage OUTPUT;
        INSERT [#ObjectAnalysis_ModuleStatus] VALUES(N'USP_StatisticsDistributionAnalysis',COALESCE(@StatisticsDistributionStatus,'ERROR_HANDLED'),@StatisticsDistributionErrorNumber,@StatisticsDistributionErrorMessage);
    END TRY BEGIN CATCH INSERT [#ObjectAnalysis_ModuleStatus] VALUES(N'USP_StatisticsDistributionAnalysis','ERROR_HANDLED',ERROR_NUMBER(),ERROR_MESSAGE()); SET @IsPartial=1; END CATCH;

    IF @StatusCode = 'AVAILABLE' AND @MitPartitions = 1
    BEGIN TRY
        EXEC [monitor].[USP_Partitions]
              @DatabaseNames=@DatabaseNames,@SystemdatenbankenEinbeziehen=@SystemdatenbankenEinbeziehen,@DatabaseNamePattern=@DatabaseNamePattern,@HighImpactConfirmed=@HighImpactConfirmed
            , @SchemaNames=@SchemaNames,@SchemaNamePattern=@SchemaNamePattern,@ObjectNames=@ObjectNames,@ObjectNamePattern=@ObjectNamePattern,@FullObjectNames=@FullObjectNames
            , @AnalyseModus=@AnalyseModus,@MaxZeilen=@MaxZeilen,@LockTimeoutMs=@LockTimeoutMs
            , @ResultSetArt=@ResultSetArtNormalisiert,@JsonErzeugen=@JsonErzeugen,@Json=@JsonPartitions OUTPUT,@PrintMeldungen=@PrintMeldungen;
        INSERT [#ObjectAnalysis_ModuleStatus] VALUES(N'USP_Partitions',COALESCE(JSON_VALUE(@JsonPartitions,'$.meta.statusCode'),'EXECUTED'),NULL,NULL);
    END TRY BEGIN CATCH INSERT [#ObjectAnalysis_ModuleStatus] VALUES(N'USP_Partitions','ERROR_HANDLED',ERROR_NUMBER(),ERROR_MESSAGE()); SET @IsPartial=1; END CATCH;

    IF @StatusCode = 'AVAILABLE' AND @MitColumnstore = 1
    BEGIN TRY
        EXEC [monitor].[USP_Columnstore]
              @DatabaseNames=@DatabaseNames,@SystemdatenbankenEinbeziehen=@SystemdatenbankenEinbeziehen,@DatabaseNamePattern=@DatabaseNamePattern,@HighImpactConfirmed=@HighImpactConfirmed
            , @SchemaNames=@SchemaNames,@SchemaNamePattern=@SchemaNamePattern,@ObjectNames=@ObjectNames,@ObjectNamePattern=@ObjectNamePattern,@FullObjectNames=@FullObjectNames
            , @AnalyseModus=@AnalyseModus,@MaxZeilen=@MaxZeilen,@LockTimeoutMs=@LockTimeoutMs
            , @ResultSetArt=@ResultSetArtNormalisiert,@JsonErzeugen=@JsonErzeugen,@Json=@JsonColumnstore OUTPUT,@PrintMeldungen=@PrintMeldungen;
        INSERT [#ObjectAnalysis_ModuleStatus] VALUES(N'USP_Columnstore',COALESCE(JSON_VALUE(@JsonColumnstore,'$.meta.statusCode'),'EXECUTED'),NULL,NULL);
    END TRY BEGIN CATCH INSERT [#ObjectAnalysis_ModuleStatus] VALUES(N'USP_Columnstore','ERROR_HANDLED',ERROR_NUMBER(),ERROR_MESSAGE()); SET @IsPartial=1; END CATCH;

    IF @StatusCode = 'AVAILABLE' AND @MitPhysicalStats = 1
    BEGIN TRY
        EXEC [monitor].[USP_IndexPhysicalStats]
              @DatabaseNames=@DatabaseNames,@SystemdatenbankenEinbeziehen=@SystemdatenbankenEinbeziehen,@DatabaseNamePattern=@DatabaseNamePattern,@HighImpactConfirmed=@HighImpactConfirmed
            , @SchemaNames=@SchemaNames,@SchemaNamePattern=@SchemaNamePattern,@ObjectNames=@ObjectNames,@ObjectNamePattern=@ObjectNamePattern,@FullObjectNames=@FullObjectNames
            , @IndexNames=@IndexNames,@IndexNamePattern=@IndexNamePattern,@AnalyseModus=@AnalyseModus
            ,@MaxZeilen=@MaxZeilen,@LockTimeoutMs=@LockTimeoutMs
            , @ResultSetArt=@ResultSetArtNormalisiert,@JsonErzeugen=@JsonErzeugen,@Json=@JsonPhysicalStats OUTPUT,@PrintMeldungen=@PrintMeldungen;
        INSERT [#ObjectAnalysis_ModuleStatus] VALUES(N'USP_IndexPhysicalStats',COALESCE(JSON_VALUE(@JsonPhysicalStats,'$.meta.statusCode'),'EXECUTED'),NULL,NULL);
    END TRY BEGIN CATCH INSERT [#ObjectAnalysis_ModuleStatus] VALUES(N'USP_IndexPhysicalStats','ERROR_HANDLED',ERROR_NUMBER(),ERROR_MESSAGE()); SET @IsPartial=1; END CATCH;

    IF @StatusCode = 'AVAILABLE' AND @MitVectorIndexes = 1
    BEGIN TRY
        EXEC [monitor].[USP_VectorIndexAnalysis]
              @DatabaseNames=@DatabaseNames,@SystemdatenbankenEinbeziehen=@SystemdatenbankenEinbeziehen,@DatabaseNamePattern=@DatabaseNamePattern,@HighImpactConfirmed=@HighImpactConfirmed
            , @SchemaNames=@SchemaNames,@SchemaNamePattern=@SchemaNamePattern,@ObjectNames=@ObjectNames,@ObjectNamePattern=@ObjectNamePattern,@FullObjectNames=@FullObjectNames
            , @IndexNames=@IndexNames,@IndexNamePattern=@IndexNamePattern,@MaxZeilen=@MaxZeilen,@LockTimeoutMs=@LockTimeoutMs
            , @ResultSetArt=@ResultSetArtNormalisiert,@JsonErzeugen=@JsonErzeugen,@Json=@JsonVectorIndexes OUTPUT,@PrintMeldungen=@PrintMeldungen
            , @StatusCodeOut=@VectorIndexStatus OUTPUT,@IsPartialOut=@VectorIndexPartial OUTPUT
            , @ErrorNumberOut=@VectorIndexErrorNumber OUTPUT,@ErrorMessageOut=@VectorIndexErrorMessage OUTPUT;
        INSERT [#ObjectAnalysis_ModuleStatus] VALUES(N'USP_VectorIndexAnalysis',COALESCE(@VectorIndexStatus,'ERROR_HANDLED'),@VectorIndexErrorNumber,@VectorIndexErrorMessage);
    END TRY BEGIN CATCH INSERT [#ObjectAnalysis_ModuleStatus] VALUES(N'USP_VectorIndexAnalysis','ERROR_HANDLED',ERROR_NUMBER(),ERROR_MESSAGE()); SET @IsPartial=1; END CATCH;

    IF @StatusCode = 'AVAILABLE' AND @MitSchemaDesign = 1
    BEGIN TRY
        EXEC [monitor].[USP_SchemaDesignAnalysis]
              @DatabaseNames=@DatabaseNames,@SystemdatenbankenEinbeziehen=@SystemdatenbankenEinbeziehen,@DatabaseNamePattern=@DatabaseNamePattern,@HighImpactConfirmed=@HighImpactConfirmed
            ,@MaxZeilen=@MaxZeilen
            , @ResultSetArt=@ResultSetArtNormalisiert,@JsonErzeugen=@JsonErzeugen,@Json=@JsonSchemaDesign OUTPUT,@PrintMeldungen=@PrintMeldungen
            , @StatusCodeOut=@SchemaDesignStatus OUTPUT,@IsPartialOut=@SchemaDesignPartial OUTPUT
            , @ErrorNumberOut=@SchemaDesignErrorNumber OUTPUT,@ErrorMessageOut=@SchemaDesignErrorMessage OUTPUT;
        INSERT [#ObjectAnalysis_ModuleStatus] VALUES(N'USP_SchemaDesignAnalysis',COALESCE(@SchemaDesignStatus,'ERROR_HANDLED'),@SchemaDesignErrorNumber,@SchemaDesignErrorMessage);
    END TRY BEGIN CATCH INSERT [#ObjectAnalysis_ModuleStatus] VALUES(N'USP_SchemaDesignAnalysis','ERROR_HANDLED',ERROR_NUMBER(),ERROR_MESSAGE()); SET @IsPartial=1; END CATCH;

    IF EXISTS(SELECT 1 FROM [#ObjectAnalysis_ModuleStatus]
              WHERE [StatusCode] NOT IN ('EXECUTED','AVAILABLE','AVAILABLE_WITH_FINDING','NOT_APPLICABLE','UNAVAILABLE_VERSION','UNAVAILABLE_FEATURE','NOT_ENABLED'))
    BEGIN
        SET @StatusCode = 'PARTIAL_RESULT';
        SET @IsPartial = 1;
    END
    ELSE IF EXISTS(SELECT 1 FROM [#ObjectAnalysis_ModuleStatus] WHERE [StatusCode] = 'AVAILABLE_WITH_FINDING')
        SET @StatusCode = 'AVAILABLE_WITH_FINDING';

    IF @StatusCode <> 'AVAILABLE' AND @PrintMeldungen = 1
    BEGIN
        SET @MonitorPrintMessage = FORMATMESSAGE(N'WARNUNG USP_ObjectAnalysis %s: %s',@StatusCode,COALESCE(@ErrorMessage,N'Mindestens ein Teilmodul lieferte kein vollständiges Ergebnis.'));
        RAISERROR(N'%s',10,1,@MonitorPrintMessage) WITH NOWAIT;
    END;

    SET @LockTimeoutSql=N'SET LOCK_TIMEOUT '+CONVERT(nvarchar(20),@OriginalLockTimeout)+N';';
    EXEC [sys].[sp_executesql] @LockTimeoutSql;

    IF @JsonErzeugen = 1
    BEGIN
        DECLARE @JsonMeta nvarchar(max)=(SELECT N'ObjectAnalysis' [resultName],1 [schemaVersion],@CollectionTimeUtc [generatedAtUtc],@StatusCode [statusCode],@IsPartial [isPartial],@ErrorMessage [errorMessage] FOR JSON PATH,WITHOUT_ARRAY_WRAPPER,INCLUDE_NULL_VALUES);
        DECLARE @JsonModuleStatus nvarchar(max)=(SELECT * FROM [#ObjectAnalysis_ModuleStatus] ORDER BY [ModuleName] FOR JSON PATH,INCLUDE_NULL_VALUES);
        SET @Json=CONCAT
        (
              N'{"meta":',COALESCE(@JsonMeta,N'{}')
            ,N',"moduleStatus":',COALESCE(@JsonModuleStatus,N'[]')
            ,N',"objectInventory":',COALESCE(@JsonObjectInventory,N'null')
            ,N',"indexUsage":',COALESCE(@JsonIndexUsage,N'null')
            ,N',"missingIndexes":',COALESCE(@JsonMissingIndexes,N'null')
            ,N',"indexOperationalStats":',COALESCE(@JsonOperationalStats,N'null')
            ,N',"statistics":',COALESCE(@JsonStatistics,N'null')
            ,N',"statisticsDistribution":',COALESCE(@JsonStatisticsDistribution,N'null')
            ,N',"partitions":',COALESCE(@JsonPartitions,N'null')
            ,N',"columnstore":',COALESCE(@JsonColumnstore,N'null')
            ,N',"indexPhysicalStats":',COALESCE(@JsonPhysicalStats,N'null')
            ,N',"vectorIndexAnalysis":',COALESCE(@JsonVectorIndexes,N'null')
            ,N',"schemaDesign":',COALESCE(@JsonSchemaDesign,N'null')
            ,N'}'
        );
    END;

    IF @ResultSetArtNormalisiert <> 'NONE'
    BEGIN
        IF @ResultSetArtNormalisiert = 'RAW'
            SELECT @CollectionTimeUtc [CollectionTimeUtc],N'monitor.USP_ObjectAnalysis' [ModuleName],@StatusCode [StatusCode],@IsPartial [IsPartial],@ErrorMessage [ErrorMessage];
        ELSE
            SELECT N'Objekt-/Indexanalyse' [Ergebnis],@CollectionTimeUtc [Stand_UTC],@StatusCode [Status],@IsPartial [Teilergebnis],@ErrorMessage [Hinweis];

        IF @ResultSetArtNormalisiert = 'RAW'
            SELECT * FROM [#ObjectAnalysis_ModuleStatus] ORDER BY [ModuleName];
        ELSE
            SELECT N'Teilmodulstatus' [Ergebnis],[ModuleName] [Modul],[StatusCode] [Status],[ErrorNumber] [Fehlernummer],[ErrorMessage] [Fehlermeldung] FROM [#ObjectAnalysis_ModuleStatus] ORDER BY [ModuleName];
    END;
    IF @ConsoleResultRequested = 1
    BEGIN
        EXEC [monitor].[InternalEmitConsoleResult]
              @SourceTable=N'#ObjectAnalysis_ModuleStatus'
            , @ResultLabel=N'ObjectAnalysis'
            , @EmptyMessage=N'Keine fachlichen Ergebnisse';
    END;
    IF @TableResultRequested = 1
    BEGIN
        EXEC [monitor].[InternalWriteResultTable]
              @SourceTable = N'#ObjectAnalysis_ModuleStatus'
            , @TargetTable=@TableTarget
            , @ThrowOnError = 1;
    END;
END;
GO
-- END SOURCE: Code/03_ObjectIndex/080_USP_ObjectAnalysis.sql

-- BEGIN SOURCE: Code/04_PlanCache/010_USP_QueryStats.sql
/*
===============================================================================
Objekt       : monitor.USP_QueryStats
Version      : 2.1.0
Stand        : 2026-07-19
Zweck        : Liefert kumulative Statement-Statistiken des aktuellen Plan
               Cache. Datenbanknamen unterstützen bracket-aware Pipe-Listen
               und LIKE-/Regex-Patterns. RAW, CONSOLE und JSON verwenden
               dieselbe intern materialisierte Datenbasis.
SQL-Version  : SQL Server 2019 oder neuer; Regex nur ab SQL Server 2025 und
               Compatibility Level 170.
===============================================================================
*/
CREATE OR ALTER PROCEDURE [monitor].[USP_QueryStats]
      @DatabaseNames                  nvarchar(max)  = NULL
    , @SystemdatenbankenEinbeziehen   bit            = 0
    , @DatabaseNamePattern            nvarchar(4000) = NULL
    , @HighImpactConfirmed              bit            = 0
    , @QueryHash                      binary(8)      = NULL
    , @QueryPlanHash                  binary(8)      = NULL
    , @SqlHandle                      varbinary(64)  = NULL
    , @PlanHandle                     varbinary(64)  = NULL
    , @TextPattern                    nvarchar(4000) = NULL
    , @Sortierung                     varchar(32)    = 'CPU_TOTAL'
    , @AnalyseModus                   varchar(16)    = 'TOP'
    , @MinExecutionCount              bigint         = 1
    , @VonUtc                         datetime2(7)    = NULL
    , @MaxZeilen                      int            = 100
    , @MaxSqlTextZeichen              int            = 4000
    , @ParentQueryStatsSnapshot       bit            = 0
    , @ResultSetArt                   varchar(16)    = 'CONSOLE'
    , @ResultTablesJson               nvarchar(max) = NULL
    , @JsonErzeugen                   bit            = 0
    , @Json                           nvarchar(max)  = NULL OUTPUT
    , @PrintMeldungen                 bit            = 1
    , @Hilfe                          bit            = 0
AS
BEGIN
    SET NOCOUNT ON;
    SET LOCK_TIMEOUT 0;
    SET @Json = NULL;

    DECLARE @OutputMode varchar(16) = UPPER(LTRIM(RTRIM(COALESCE(@ResultSetArt, ''))));
    DECLARE @TableResultRequested bit = CASE WHEN @OutputMode = 'TABLE' THEN 1 ELSE 0 END;
    DECLARE @ConsoleResultRequested bit = CASE WHEN @OutputMode = 'CONSOLE' THEN 1 ELSE 0 END;
    DECLARE @TableTarget sysname=NULL;
    IF @TableResultRequested=0 AND NULLIF(LTRIM(RTRIM(COALESCE(@ResultTablesJson,N''))),N'') IS NOT NULL THROW 51011,N'@ResultTablesJson ist ausschließlich mit @ResultSetArt=TABLE zulässig.',1;
    IF @TableResultRequested=1 EXEC [monitor].[InternalPrepareSingleResultTable] @ResultTablesJson=@ResultTablesJson,@ResultName=N'queries',@TargetTable=@TableTarget OUTPUT,@ThrowOnError=1;
    IF @TableResultRequested = 1 OR @ConsoleResultRequested = 1 SET @OutputMode = 'NONE';
    DECLARE @Mode varchar(16) = UPPER(LTRIM(RTRIM(COALESCE(@AnalyseModus, 'TOP'))));
    DECLARE @Order varchar(32) = UPPER(LTRIM(RTRIM(COALESCE(@Sortierung, 'CPU_TOTAL'))));
    DECLARE @Limit bigint = CASE WHEN @MaxZeilen IS NULL OR @MaxZeilen = 0 THEN CONVERT(bigint, 9223372036854775807)
                                 WHEN @MaxZeilen > 0 THEN CONVERT(bigint, @MaxZeilen) ELSE 0 END;
    DECLARE @CandidateRows bigint = CASE WHEN @MaxZeilen IS NULL OR @MaxZeilen = 0 THEN CONVERT(bigint, 9223372036854775807)
                                         WHEN @MaxZeilen < 2147483647 THEN CONVERT(bigint, @MaxZeilen) + 1 ELSE CONVERT(bigint, @MaxZeilen) END;

    IF @Hilfe = 1
    BEGIN
        PRINT N'monitor.USP_QueryStats';
        PRINT N'@DatabaseNames: Pipe-Liste; N''''/NULL = keine Datenbankeinschränkung.';
        PRINT N'@DatabaseNamePattern: ein like:/regex:/regexi:-Pattern; nicht mit einer exakten Liste kombinieren.';
        PRINT N'@TextPattern: ein LIKE-/Regex-Pattern für SQL-Text; Pattern wird nicht als Pipe-Liste zerlegt.';
        PRINT N'@Sortierung: CPU_TOTAL, CPU_AVG, ELAPSED_TOTAL, ELAPSED_AVG, READS_TOTAL, READS_AVG, WRITES_TOTAL, WRITES_AVG, EXECUTIONS, GRANT_MAX, SPILLS_TOTAL, ROWS_TOTAL, LAST_EXECUTION.';
        PRINT N'@MaxZeilen positiv = begrenzt, NULL/0 = unbegrenzt; VOLL oder mehr als 1000 Zeilen benötigt PLAN_CACHE_DEEP.';
        PRINT N'@MaxSqlTextZeichen positiv = gekürzt; NULL/0 = vollständiger Statement- und Batchtext.';
        PRINT N'@ParentQueryStatsSnapshot ist nur für die laufinterne Wiederverwendung durch USP_PlanCacheAnalysis bestimmt; 0 liest frisch.';
        PRINT N'@ResultSetArt = CONSOLE (Default)|RAW|TABLE|NONE; Steuerwerte sind case-insensitiv.';
        RETURN;
    END;

    DECLARE @Now datetime2(3) = SYSUTCDATETIME();
    DECLARE @StatusCode varchar(40) = 'AVAILABLE';
    DECLARE @IsPartial bit = 0;
    DECLARE @ErrorNumber int = NULL;
    DECLARE @ErrorMessage nvarchar(2048) = NULL;
    DECLARE @CrossDatabaseRequested bit = 0;
    DECLARE @Allowed bit = 1;
    DECLARE @RowCount bigint = 0;
    DECLARE @HasMoreRows bit = 0;
    DECLARE @Message nvarchar(2048);
    DECLARE @Sql nvarchar(max);
    DECLARE @OrderExpression nvarchar(256);
    DECLARE @TextMode varchar(8);
    DECLARE @TextValue nvarchar(4000);
    DECLARE @TextRegexFlags varchar(8);
    DECLARE @TextPatternValid bit;

    CREATE TABLE [#QueryStats_DatabaseCandidates]
    (
          [DatabaseId] int NOT NULL PRIMARY KEY
        , [DatabaseName] sysname NOT NULL
        , [StateDesc] nvarchar(60) NULL
        , [UserAccessDesc] nvarchar(60) NULL
        , [IsReadOnly] bit NULL
        , [CompatibilityLevel] tinyint NULL
        , [CollationName] sysname NULL
        , [RecoveryModelDesc] nvarchar(60) NULL
        , [IsSystemDatabase] bit NULL
        , [RequestedOrdinal] int NULL
    );
    CREATE TABLE [#QueryStats_DatabaseCandidateWarnings]
    (
          [RequestedName] sysname NULL
        , [StatusCode] varchar(40) NOT NULL
        , [ErrorMessage] nvarchar(2048) NULL
    );
    CREATE TABLE [#QueryStats_Result]
    (
          [QueryHash] binary(8) NULL
        , [QueryPlanHash] binary(8) NULL
        , [PlanHandle] varbinary(64) NOT NULL
        , [SqlHandle] varbinary(64) NOT NULL
        , [StatementStartOffset] int NOT NULL
        , [StatementEndOffset] int NOT NULL
        , [PlanGenerationNumber] bigint NOT NULL
        , [DatabaseId] int NULL
        , [DatabaseName] sysname NULL
        , [ObjectId] int NULL
        , [StatementTextCharacters] bigint NULL
        , [StatementTextBytes] bigint NULL
        , [StatementTextIsTruncated] bit NOT NULL DEFAULT(0)
        , [StatementText] nvarchar(max) NULL
        , [BatchTextCharacters] bigint NULL
        , [BatchTextBytes] bigint NULL
        , [BatchTextIsTruncated] bit NOT NULL DEFAULT(0)
        , [BatchText] nvarchar(max) NULL
        , [CreationTime] datetime NOT NULL
        , [LastExecutionTime] datetime NOT NULL
        , [ExecutionCount] bigint NOT NULL
        , [TotalCpuMs] decimal(38,3) NULL
        , [LastCpuMs] decimal(38,3) NULL
        , [MinCpuMs] decimal(38,3) NULL
        , [MaxCpuMs] decimal(38,3) NULL
        , [AvgCpuMs] decimal(38,3) NULL
        , [TotalElapsedMs] decimal(38,3) NULL
        , [LastElapsedMs] decimal(38,3) NULL
        , [MinElapsedMs] decimal(38,3) NULL
        , [MaxElapsedMs] decimal(38,3) NULL
        , [AvgElapsedMs] decimal(38,3) NULL
        , [TotalLogicalReads] bigint NOT NULL
        , [LastLogicalReads] bigint NOT NULL
        , [AvgLogicalReads] decimal(38,3) NULL
        , [TotalLogicalWrites] bigint NOT NULL
        , [LastLogicalWrites] bigint NOT NULL
        , [AvgLogicalWrites] decimal(38,3) NULL
        , [TotalPhysicalReads] bigint NOT NULL
        , [LastPhysicalReads] bigint NOT NULL
        , [TotalRows] bigint NOT NULL
        , [LastRows] bigint NOT NULL
        , [MinRows] bigint NOT NULL
        , [MaxRows] bigint NOT NULL
        , [LastDop] bigint NOT NULL
        , [MinDop] bigint NOT NULL
        , [MaxDop] bigint NOT NULL
        , [MaxGrantKb] bigint NOT NULL
        , [LastGrantKb] bigint NOT NULL
        , [LastUsedGrantKb] bigint NOT NULL
        , [LastIdealGrantKb] bigint NOT NULL
        , [TotalSpilledPages] bigint NOT NULL
        , [LastSpilledPages] bigint NOT NULL
        , [CacheObjectType] nvarchar(60) NULL
        , [ObjectType] nvarchar(60) NULL
        , [PlanUseCounts] int NULL
        , [PlanSizeBytes] bigint NULL
        , [ResourcePoolId] int NULL
        , [SetOptions] int NULL
        , [CompileUserId] int NULL
        , [SortValue] decimal(38,4) NULL
    );

    SELECT
          @TextMode = [PatternMode]
        , @TextValue = [PatternValue]
        , @TextRegexFlags = [RegexFlags]
        , @TextPatternValid = [IsValid]
    FROM [monitor].[TVF_ParsePattern](@TextPattern);

    SET @OrderExpression = CASE @Order
        WHEN 'CPU_TOTAL' THEN N'[qs].[total_worker_time]'
        WHEN 'CPU_AVG' THEN N'[qs].[total_worker_time] * 1.0 / NULLIF([qs].[execution_count], 0)'
        WHEN 'ELAPSED_TOTAL' THEN N'[qs].[total_elapsed_time]'
        WHEN 'ELAPSED_AVG' THEN N'[qs].[total_elapsed_time] * 1.0 / NULLIF([qs].[execution_count], 0)'
        WHEN 'READS_TOTAL' THEN N'[qs].[total_logical_reads]'
        WHEN 'READS_AVG' THEN N'[qs].[total_logical_reads] * 1.0 / NULLIF([qs].[execution_count], 0)'
        WHEN 'WRITES_TOTAL' THEN N'[qs].[total_logical_writes]'
        WHEN 'WRITES_AVG' THEN N'[qs].[total_logical_writes] * 1.0 / NULLIF([qs].[execution_count], 0)'
        WHEN 'EXECUTIONS' THEN N'[qs].[execution_count]'
        WHEN 'GRANT_MAX' THEN N'[qs].[max_grant_kb]'
        WHEN 'SPILLS_TOTAL' THEN N'[qs].[total_spills]'
        WHEN 'ROWS_TOTAL' THEN N'[qs].[total_rows]'
        WHEN 'LAST_EXECUTION' THEN N'DATEDIFF_BIG(MILLISECOND, ''20000101'', [qs].[last_execution_time])'
    END;

    IF @Mode NOT IN ('TOP', 'VOLL')
       OR @OrderExpression IS NULL
       OR @MaxZeilen < 0

       OR @MinExecutionCount < 0
       OR @MaxSqlTextZeichen < 0
       OR @OutputMode NOT IN ('RAW', 'CONSOLE', 'NONE')
       OR @TextPatternValid = 0
       OR @JsonErzeugen IS NULL
       OR @ParentQueryStatsSnapshot IS NULL
    BEGIN
        SET @StatusCode = 'INVALID_PARAMETER';
        SET @ErrorMessage = N'Mindestens ein Parameter besitzt einen ungültigen Wert.';
    END;

    IF @StatusCode = 'AVAILABLE'
    BEGIN
        EXEC [monitor].[USP_PrepareDatabaseCandidates]
              @DatabaseNames = @DatabaseNames
            , @SystemdatenbankenEinbeziehen = @SystemdatenbankenEinbeziehen
            , @DatabaseNamePattern = @DatabaseNamePattern,@HighImpactConfirmed=@HighImpactConfirmed

            , @AnalysisClass = 'PLAN_CACHE_CURRENT'
            , @StatusCode = @StatusCode OUTPUT
            , @ErrorMessage = @ErrorMessage OUTPUT
            , @CrossDatabaseRequested = @CrossDatabaseRequested OUTPUT,@CandidateTable=N'#QueryStats_DatabaseCandidates',@WarningTable=N'#QueryStats_DatabaseCandidateWarnings';
    END;

    IF @StatusCode = 'AVAILABLE'
       AND (@Mode = 'VOLL' OR @Limit > 1000 OR @Limit = 9223372036854775807)
    BEGIN
        EXEC [monitor].[InternalCheckAnalysisPath]
              @AnalysisClass='PLAN_CACHE_DEEP'
            , @HighImpactConfirmed=@HighImpactConfirmed
            , @StatusCode=@StatusCode OUTPUT
            , @ErrorMessage=@ErrorMessage OUTPUT;
    END;

    IF @StatusCode = 'AVAILABLE'
       AND @TextMode IN ('REGEX', 'REGEXI')
       AND
       (
           TRY_CONVERT(int, SERVERPROPERTY(N'ProductMajorVersion')) < 17
           OR NOT EXISTS
              (
                  SELECT 1
                  FROM [master].[sys].[databases] AS [d] WITH (NOLOCK)
                  WHERE [d].[database_id] = DB_ID()
                    AND [d].[compatibility_level] >= 170
              )
       )
    BEGIN
        SET @StatusCode = 'UNAVAILABLE_FEATURE';
        SET @ErrorMessage = N'Regex benötigt SQL Server 2025 und Compatibility Level 170 für die Installationsdatenbank.';
    END;

    IF @StatusCode = 'AVAILABLE'
    BEGIN TRY
        SET @Sql = CONVERT(nvarchar(max),N'') + N'
INSERT [#QueryStats_Result]
(
      [QueryHash], [QueryPlanHash], [PlanHandle], [SqlHandle]
    , [StatementStartOffset], [StatementEndOffset], [PlanGenerationNumber]
    , [DatabaseId], [DatabaseName], [ObjectId]
    , [StatementTextCharacters], [StatementTextBytes], [StatementTextIsTruncated], [StatementText]
    , [BatchTextCharacters], [BatchTextBytes], [BatchTextIsTruncated], [BatchText]
    , [CreationTime], [LastExecutionTime], [ExecutionCount]
    , [TotalCpuMs], [LastCpuMs], [MinCpuMs], [MaxCpuMs], [AvgCpuMs]
    , [TotalElapsedMs], [LastElapsedMs], [MinElapsedMs], [MaxElapsedMs], [AvgElapsedMs]
    , [TotalLogicalReads], [LastLogicalReads], [AvgLogicalReads]
    , [TotalLogicalWrites], [LastLogicalWrites], [AvgLogicalWrites]
    , [TotalPhysicalReads], [LastPhysicalReads]
    , [TotalRows], [LastRows], [MinRows], [MaxRows]
    , [LastDop], [MinDop], [MaxDop]
    , [MaxGrantKb], [LastGrantKb], [LastUsedGrantKb], [LastIdealGrantKb]
    , [TotalSpilledPages], [LastSpilledPages]
    , [CacheObjectType], [ObjectType], [PlanUseCounts], [PlanSizeBytes]
    , [ResourcePoolId], [SetOptions], [CompileUserId], [SortValue]
)
SELECT TOP (@CandidateRows)
      [qs].[query_hash]
    , [qs].[query_plan_hash]
    , [qs].[plan_handle]
    , [qs].[sql_handle]
    , [qs].[statement_start_offset]
    , [qs].[statement_end_offset]
    , [qs].[plan_generation_num]
    , [resolved].[DatabaseId]
    , [dbc].[DatabaseName]
    , [st].[objectid]
    , NULL,NULL,CONVERT(bit,0),[statementText].[StatementText]
    , NULL,NULL,CONVERT(bit,0),[st].[text]
    , [qs].[creation_time]
    , [qs].[last_execution_time]
    , [qs].[execution_count]
    , CONVERT(decimal(38,3), [qs].[total_worker_time] / 1000.0)
    , CONVERT(decimal(38,3), [qs].[last_worker_time] / 1000.0)
    , CONVERT(decimal(38,3), [qs].[min_worker_time] / 1000.0)
    , CONVERT(decimal(38,3), [qs].[max_worker_time] / 1000.0)
    , CONVERT(decimal(38,3), [qs].[total_worker_time] / NULLIF([qs].[execution_count],0) / 1000.0)
    , CONVERT(decimal(38,3), [qs].[total_elapsed_time] / 1000.0)
    , CONVERT(decimal(38,3), [qs].[last_elapsed_time] / 1000.0)
    , CONVERT(decimal(38,3), [qs].[min_elapsed_time] / 1000.0)
    , CONVERT(decimal(38,3), [qs].[max_elapsed_time] / 1000.0)
    , CONVERT(decimal(38,3), [qs].[total_elapsed_time] / NULLIF([qs].[execution_count],0) / 1000.0)
    , [qs].[total_logical_reads]
    , [qs].[last_logical_reads]
    , CONVERT(decimal(38,3), [qs].[total_logical_reads] * 1.0 / NULLIF([qs].[execution_count],0))
    , [qs].[total_logical_writes]
    , [qs].[last_logical_writes]
    , CONVERT(decimal(38,3), [qs].[total_logical_writes] * 1.0 / NULLIF([qs].[execution_count],0))
    , [qs].[total_physical_reads]
    , [qs].[last_physical_reads]
    , [qs].[total_rows]
    , [qs].[last_rows]
    , [qs].[min_rows]
    , [qs].[max_rows]
    , [qs].[last_dop]
    , [qs].[min_dop]
    , [qs].[max_dop]
    , [qs].[max_grant_kb]
    , [qs].[last_grant_kb]
    , [qs].[last_used_grant_kb]
    , [qs].[last_ideal_grant_kb]
    , [qs].[total_spills]
    , [qs].[last_spills]
    , [cp].[cacheobjtype]
    , [cp].[objtype]
    , [cp].[usecounts]
    , [cp].[size_in_bytes]
    , [cp].[pool_id]
    , TRY_CONVERT(int, [setOptions].[value])
    , TRY_CONVERT(int, [compileUser].[value])
    , CONVERT(decimal(38,4), ' + @OrderExpression + N')
FROM ' + CASE WHEN @ParentQueryStatsSnapshot=1
              THEN N'[#PlanCacheAnalysis_QueryStatsSnapshot] AS [qs]'
              ELSE N'[sys].[dm_exec_query_stats] AS [qs] WITH (NOLOCK)' END + N'
OUTER APPLY [sys].[dm_exec_sql_text]([qs].[sql_handle]) AS [st]
OUTER APPLY [monitor].[TVF_StatementText]
(
      [st].[text]
    , [qs].[statement_start_offset]
    , [qs].[statement_end_offset]
) AS [statementText]
OUTER APPLY
(
    SELECT TOP (1) TRY_CONVERT(int, [pa].[value]) AS [DatabaseId]
    FROM [sys].[dm_exec_plan_attributes]([qs].[plan_handle]) AS [pa]
    WHERE [pa].[attribute] = ''dbid''
) AS [planDb]
CROSS APPLY
(
    SELECT COALESCE([st].[dbid], [planDb].[DatabaseId]) AS [DatabaseId]
) AS [resolved]
INNER JOIN [#QueryStats_DatabaseCandidates] AS [dbc]
  ON [dbc].[DatabaseId] = [resolved].[DatabaseId]
LEFT JOIN [sys].[dm_exec_cached_plans] AS [cp] WITH (NOLOCK)
  ON [cp].[plan_handle] = [qs].[plan_handle]
OUTER APPLY
(
    SELECT TOP (1) [pa].[value]
    FROM [sys].[dm_exec_plan_attributes]([qs].[plan_handle]) AS [pa]
    WHERE [pa].[attribute] = ''set_options''
) AS [setOptions]
OUTER APPLY
(
    SELECT TOP (1) [pa].[value]
    FROM [sys].[dm_exec_plan_attributes]([qs].[plan_handle]) AS [pa]
    WHERE [pa].[attribute] = ''user_id''
) AS [compileUser]
WHERE [qs].[execution_count] >= @MinExecutions
  AND (@Since IS NULL OR [qs].[last_execution_time] >= @Since)
  AND (@QH IS NULL OR [qs].[query_hash] = @QH)
  AND (@QPH IS NULL OR [qs].[query_plan_hash] = @QPH)
  AND (@SH IS NULL OR [qs].[sql_handle] = @SH)
  AND (@PH IS NULL OR [qs].[plan_handle] = @PH)
  AND (@TextMode IN (''NONE'', ''REGEX'', ''REGEXI'') OR [st].[text] COLLATE SQL_Latin1_General_CP1_CS_AS LIKE @TextValue COLLATE SQL_Latin1_General_CP1_CS_AS)'
  + CASE WHEN @TextMode IN ('REGEX', 'REGEXI')
         THEN N'
  AND REGEXP_LIKE([st].[text], @TextValue, @TextFlags)'
         ELSE N'' END
  + N'
ORDER BY ' + @OrderExpression + N' DESC, [qs].[last_execution_time] DESC
OPTION (RECOMPILE, MAXDOP 1);';

        EXEC [sys].[sp_executesql]
              @Sql
            , N'@CandidateRows bigint, @TextChars int, @MinExecutions bigint, @Since datetime2(7), @QH binary(8), @QPH binary(8), @SH varbinary(64), @PH varbinary(64), @TextMode varchar(8), @TextValue nvarchar(4000), @TextFlags varchar(8)'
            , @CandidateRows = @CandidateRows
            , @TextChars = @MaxSqlTextZeichen
            , @MinExecutions = @MinExecutionCount
            , @Since = @VonUtc
            , @QH = @QueryHash
            , @QPH = @QueryPlanHash
            , @SH = @SqlHandle
            , @PH = @PlanHandle
            , @TextMode = @TextMode
            , @TextValue = @TextValue
            , @TextFlags = @TextRegexFlags;

        DECLARE @TruncatedValueCount bigint=0,@LargestRequiredCharacters bigint=NULL;
        DECLARE @ColumnTruncatedCount bigint=0,@ColumnLargestCharacters bigint=NULL;
        EXEC [monitor].[InternalProjectUnicodeTextColumn]
              @SourceTable=N'#QueryStats_Result',@TextColumn=N'StatementText'
            , @CharactersColumn=N'StatementTextCharacters',@BytesColumn=N'StatementTextBytes'
            , @IsTruncatedColumn=N'StatementTextIsTruncated',@MaxCharacters=@MaxSqlTextZeichen
            , @TruncatedValueCount=@ColumnTruncatedCount OUTPUT,@LargestRequiredCharacters=@ColumnLargestCharacters OUTPUT;
        SELECT @TruncatedValueCount=@TruncatedValueCount+@ColumnTruncatedCount,
               @LargestRequiredCharacters=CASE WHEN @LargestRequiredCharacters IS NULL OR @ColumnLargestCharacters>@LargestRequiredCharacters THEN @ColumnLargestCharacters ELSE @LargestRequiredCharacters END;
        EXEC [monitor].[InternalProjectUnicodeTextColumn]
              @SourceTable=N'#QueryStats_Result',@TextColumn=N'BatchText'
            , @CharactersColumn=N'BatchTextCharacters',@BytesColumn=N'BatchTextBytes'
            , @IsTruncatedColumn=N'BatchTextIsTruncated',@MaxCharacters=@MaxSqlTextZeichen
            , @TruncatedValueCount=@ColumnTruncatedCount OUTPUT,@LargestRequiredCharacters=@ColumnLargestCharacters OUTPUT;
        SELECT @TruncatedValueCount=@TruncatedValueCount+@ColumnTruncatedCount,
               @LargestRequiredCharacters=CASE WHEN @LargestRequiredCharacters IS NULL OR @ColumnLargestCharacters>@LargestRequiredCharacters THEN @ColumnLargestCharacters ELSE @LargestRequiredCharacters END;
        EXEC [monitor].[InternalEmitTruncationWarning]
              @TruncatedValueCount=@TruncatedValueCount,@ParameterName=N'@MaxSqlTextZeichen'
            , @ParameterValue=@MaxSqlTextZeichen,@LargestRequiredCharacters=@LargestRequiredCharacters
            , @PrintMeldungen=@PrintMeldungen;

        SELECT @RowCount = COUNT_BIG(*) FROM [#QueryStats_Result];
        SET @HasMoreRows = CONVERT(bit, CASE WHEN @Limit < 9223372036854775807 AND @RowCount > @Limit THEN 1 ELSE 0 END);
    END TRY
    BEGIN CATCH
        SET @ErrorNumber = ERROR_NUMBER();
        SET @ErrorMessage = ERROR_MESSAGE();
        SET @IsPartial = 1;
        SET @StatusCode = CASE WHEN @ErrorNumber IN (229,262,297,300,371,916) THEN 'DENIED_PERMISSION'
                               WHEN @ErrorNumber = 1222 THEN 'TIMEOUT' ELSE 'ERROR_HANDLED' END;
    END CATCH;

    IF @PrintMeldungen = 1 AND @StatusCode <> 'AVAILABLE'
    BEGIN
        SET @Message = FORMATMESSAGE(N'WARNUNG USP_QueryStats [%s]: %s', @StatusCode, COALESCE(@ErrorMessage, N'Keine Details.'));
        RAISERROR(N'%s', 10, 1, @Message) WITH NOWAIT;
    END;

    IF @OutputMode <> 'NONE'
    BEGIN
        SELECT
              N'USP_QueryStats' AS [ModuleName]
            , @Now AS [CollectionTimeUtc]
            , @StatusCode AS [StatusCode]
            , @IsPartial AS [IsPartial]
            , CASE WHEN @RowCount > @Limit THEN @Limit ELSE @RowCount END AS [ReturnedRowCount]
            , @HasMoreRows AS [HasMoreRows]
            , @CrossDatabaseRequested AS [CrossDatabaseRequested]
            , @ErrorNumber AS [ErrorNumber]
            , @ErrorMessage AS [ErrorMessage];

        IF @OutputMode = 'RAW'
        BEGIN
            SELECT TOP (@Limit)
                  [QueryHash], [QueryPlanHash], [PlanHandle], [SqlHandle]
                , [StatementStartOffset], [StatementEndOffset], [PlanGenerationNumber]
                , [DatabaseId], [DatabaseName], [ObjectId]
                , [StatementTextCharacters], [StatementTextBytes], [StatementTextIsTruncated], [StatementText]
                , [BatchTextCharacters], [BatchTextBytes], [BatchTextIsTruncated], [BatchText]
                , [CreationTime], [LastExecutionTime], [ExecutionCount]
                , [TotalCpuMs], [LastCpuMs], [MinCpuMs], [MaxCpuMs], [AvgCpuMs]
                , [TotalElapsedMs], [LastElapsedMs], [MinElapsedMs], [MaxElapsedMs], [AvgElapsedMs]
                , [TotalLogicalReads], [LastLogicalReads], [AvgLogicalReads]
                , [TotalLogicalWrites], [LastLogicalWrites], [AvgLogicalWrites]
                , [TotalPhysicalReads], [LastPhysicalReads]
                , [TotalRows], [LastRows], [MinRows], [MaxRows]
                , [LastDop], [MinDop], [MaxDop]
                , [MaxGrantKb], [LastGrantKb], [LastUsedGrantKb], [LastIdealGrantKb]
                , [TotalSpilledPages], [LastSpilledPages]
                , [CacheObjectType], [ObjectType], [PlanUseCounts], [PlanSizeBytes]
                , [ResourcePoolId], [SetOptions], [CompileUserId]
            FROM [#QueryStats_Result]
            ORDER BY [SortValue] DESC, [LastExecutionTime] DESC;
        END
        ELSE
        BEGIN
            SELECT TOP (@Limit)
                  N'Plan-Cache Statement' AS [Ergebnis]
                , [DatabaseName] AS [Datenbank]
                , [ExecutionCount] AS [Ausführungen]
                , CONCAT(CONVERT(varchar(30), [TotalCpuMs]), N' ms') AS [CPU gesamt]
                , CONCAT(CONVERT(varchar(30), [AvgCpuMs]), N' ms') AS [CPU je Ausführung]
                , CONCAT(CONVERT(varchar(30), [TotalElapsedMs]), N' ms') AS [Laufzeit gesamt]
                , CONCAT(CONVERT(varchar(30), [AvgElapsedMs]), N' ms') AS [Laufzeit je Ausführung]
                , [TotalLogicalReads] AS [Logical Reads gesamt]
                , [AvgLogicalReads] AS [Logical Reads je Ausführung]
                , CONCAT(CONVERT(varchar(30), [MaxGrantKb] / 1024.0), N' MB') AS [Maximaler Grant]
                , [TotalSpilledPages] AS [Spill-Seiten]
                , [LastExecutionTime] AS [Letzte Ausführung]
                , [DatabaseName] AS [Datenbank_SQL]
                , [StatementText] AS [Statement]
                , [BatchText] AS [Batch]
            FROM [#QueryStats_Result]
            ORDER BY [SortValue] DESC, [LastExecutionTime] DESC;
        END;

        SELECT [RequestedName], [StatusCode], [ErrorMessage]
        FROM [#QueryStats_DatabaseCandidateWarnings]
        ORDER BY [RequestedName];
    END;

    IF @JsonErzeugen = 1
    BEGIN
        DECLARE @Meta nvarchar(max) =
        (
            SELECT N'QueryStats' AS [resultName], 1 AS [schemaVersion], @Now AS [generatedAtUtc],
                   @StatusCode AS [statusCode], @MaxZeilen AS [requestedMaxRows],
                   CASE WHEN @RowCount > @Limit THEN @Limit ELSE @RowCount END AS [returnedRows],
                   @HasMoreRows AS [hasMoreRows], @Order AS [sortBy],
                   @ErrorNumber AS [errorNumber], @ErrorMessage AS [errorMessage]
            FOR JSON PATH, WITHOUT_ARRAY_WRAPPER, INCLUDE_NULL_VALUES
        );
        DECLARE @Data nvarchar(max) =
        (
            SELECT TOP (@Limit)
                  [QueryHash], [QueryPlanHash], [PlanHandle], [SqlHandle]
                , [StatementStartOffset], [StatementEndOffset], [PlanGenerationNumber]
                , [DatabaseId], [DatabaseName], [ObjectId]
                , [StatementTextCharacters], [StatementTextBytes], [StatementTextIsTruncated], [StatementText]
                , [BatchTextCharacters], [BatchTextBytes], [BatchTextIsTruncated], [BatchText]
                , [CreationTime], [LastExecutionTime], [ExecutionCount]
                , [TotalCpuMs], [LastCpuMs], [MinCpuMs], [MaxCpuMs], [AvgCpuMs]
                , [TotalElapsedMs], [LastElapsedMs], [MinElapsedMs], [MaxElapsedMs], [AvgElapsedMs]
                , [TotalLogicalReads], [LastLogicalReads], [AvgLogicalReads]
                , [TotalLogicalWrites], [LastLogicalWrites], [AvgLogicalWrites]
                , [TotalPhysicalReads], [LastPhysicalReads]
                , [TotalRows], [LastRows], [MinRows], [MaxRows]
                , [LastDop], [MinDop], [MaxDop]
                , [MaxGrantKb], [LastGrantKb], [LastUsedGrantKb], [LastIdealGrantKb]
                , [TotalSpilledPages], [LastSpilledPages]
                , [CacheObjectType], [ObjectType], [PlanUseCounts], [PlanSizeBytes]
                , [ResourcePoolId], [SetOptions], [CompileUserId]
            FROM [#QueryStats_Result]
            ORDER BY [SortValue] DESC, [LastExecutionTime] DESC
            FOR JSON PATH, INCLUDE_NULL_VALUES
        );
        DECLARE @Warnings nvarchar(max) =
        (
            SELECT [RequestedName], [StatusCode], [ErrorMessage]
            FROM [#QueryStats_DatabaseCandidateWarnings]
            ORDER BY [RequestedName]
            FOR JSON PATH, INCLUDE_NULL_VALUES
        );
        SET @Json = CONCAT(N'{"meta":',COALESCE(@Meta,N'{}'),N',"queries":',COALESCE(@Data,N'[]'),N',"warnings":',COALESCE(@Warnings,N'[]'),N'}');
    END;
    IF @ConsoleResultRequested = 1
    BEGIN
        EXEC [monitor].[InternalEmitConsoleResult]
              @SourceTable=N'#QueryStats_Result'
            , @ResultLabel=N'QueryStats'
            , @EmptyMessage=N'Keine fachlichen Ergebnisse';
    END;
    IF @TableResultRequested = 1
    BEGIN
        EXEC [monitor].[InternalWriteResultTable]
              @SourceTable = N'#QueryStats_Result'
            , @TargetTable=@TableTarget
            , @ThrowOnError = 1;
    END;
END;
GO
-- END SOURCE: Code/04_PlanCache/010_USP_QueryStats.sql

-- BEGIN SOURCE: Code/04_PlanCache/020_USP_QueryHashAnalysis.sql
/*
===============================================================================
Objekt       : monitor.USP_QueryHashAnalysis
Version      : 2.1.0
Stand        : 2026-07-19
Typ          : Stored Procedure
Zweck        : Aggregiert gecachte Statement-Statistiken je query_hash und zeigt
               Planvielfalt, Recompiles und kumulative Ressourcenanteile.
SQL-Version  : SQL Server 2019 oder neuer.
Datenquellen : sys.dm_exec_query_stats, sys.dm_exec_sql_text.
Parameter    : @QueryHash, @Sortierung, @AnalyseModus, @MinExecutionCount,
               @MinPlanVarianten, @MaxZeilen, @MaxSqlTextZeichen,
               @ParentQueryStatsSnapshot,
               @PrintMeldungen, @Hilfe.
Resultsets   : 1. Modulstatus. 2. Query-Hash-Aggregate mit Beispielstatement.
Berechtigung : VIEW SERVER STATE beziehungsweise SQL Server 2022+
               VIEW SERVER PERFORMANCE STATE. Keine Rechtevergabe.
Eigenlast    : Gruppiert sys.dm_exec_query_stats. Ohne konkreten @QueryHash sowie
               im Modus VOLL wird PLAN_CACHE_DEEP geprüft. Text wird nur für
               gewählte Hashes geladen.
Locking      : Keine Benutzerobjekte.
Partial      : Cache-Eviction kann Beispieltexte zwischen Auswahl und Ausgabe entfernen.
Beispiele    : EXEC monitor.USP_QueryHashAnalysis @MinPlanVarianten=2;
               EXEC monitor.USP_QueryHashAnalysis @Sortierung='READS_TOTAL';
               EXEC monitor.USP_QueryHashAnalysis @Hilfe=1;
Änderungen   : 2.1.0 - Query-Stats je Aufruf einmal gelesen oder vom laufgebundenen
                         Parent-Snapshot übernommen.
               1.1.0 - Breite Aggregation ohne @QueryHash gruppengeschützt.
               1.0.0 - Erstfassung Phase 3.
===============================================================================
*/
CREATE OR ALTER PROCEDURE [monitor].[USP_QueryHashAnalysis]
      @QueryHash           binary(8)   = NULL
    , @Sortierung              varchar(32) = 'CPU_TOTAL'
    , @AnalyseModus        varchar(16) = 'TOP'
    , @MinExecutionCount   bigint      = 1
    , @MinPlanVarianten    int         = 1
    , @MaxZeilen           int         = 100
    , @MaxSqlTextZeichen   int         = 4000
    , @ParentQueryStatsSnapshot bit    = 0
    , @HighImpactConfirmed bit         = 0
    , @ResultSetArt        varchar(16) = 'CONSOLE'
    , @ResultTablesJson               nvarchar(max) = NULL
    , @JsonErzeugen        bit         = 0
    , @Json                 nvarchar(max) = NULL OUTPUT
    , @PrintMeldungen      bit         = 1
    , @Hilfe               bit         = 0
AS
BEGIN
    SET NOCOUNT ON;
    SET LOCK_TIMEOUT 0;
    SET @Json = NULL;
    DECLARE @ResultSetArtNormalisiert varchar(16)=UPPER(LTRIM(RTRIM(COALESCE(@ResultSetArt,''))));
    DECLARE @TableResultRequested bit = CASE WHEN @ResultSetArtNormalisiert = 'TABLE' THEN 1 ELSE 0 END;
    DECLARE @ConsoleResultRequested bit = CASE WHEN @ResultSetArtNormalisiert = 'CONSOLE' THEN 1 ELSE 0 END;
    DECLARE @TableTarget sysname=NULL;
    IF @TableResultRequested=0 AND NULLIF(LTRIM(RTRIM(COALESCE(@ResultTablesJson,N''))),N'') IS NOT NULL THROW 51011,N'@ResultTablesJson ist ausschließlich mit @ResultSetArt=TABLE zulässig.',1;
    IF @TableResultRequested=1 EXEC [monitor].[InternalPrepareSingleResultTable] @ResultTablesJson=@ResultTablesJson,@ResultName=N'queryHashes',@TargetTable=@TableTarget OUTPUT,@ThrowOnError=1;
    IF @TableResultRequested = 1 OR @ConsoleResultRequested = 1 SET @ResultSetArtNormalisiert = 'NONE';
    DECLARE @EffectiveMaxZeilen bigint = CASE WHEN @MaxZeilen IS NULL OR @MaxZeilen=0 THEN CONVERT(bigint,9223372036854775807) ELSE CONVERT(bigint,@MaxZeilen) END;
    DECLARE @MonitorPrintMessage nvarchar(2048);
    SET @Sortierung=UPPER(LTRIM(RTRIM(COALESCE(@Sortierung,'CPU_TOTAL'))));
    SET @AnalyseModus=UPPER(LTRIM(RTRIM(COALESCE(@AnalyseModus,'TOP'))));
    IF @Hilfe=1
    BEGIN
        PRINT N'monitor.USP_QueryHashAnalysis';
        PRINT N'@QueryHash binary(8)=NULL: optional exakt auf einen Query Hash begrenzen.';
        PRINT N'@Sortierung: CPU_TOTAL, ELAPSED_TOTAL, READS_TOTAL, WRITES_TOTAL, EXECUTIONS, PLAN_VARIANTS, SPILLS_TOTAL.';
        PRINT N'@AnalyseModus TOP oder VOLL; VOLL sowie ein Lauf ohne konkreten @QueryHash prüfen PLAN_CACHE_DEEP.';
        PRINT N'@MinExecutionCount bigint=1; @MinPlanVarianten int=1; @MaxZeilen int=100.';
        PRINT N'@MaxSqlTextZeichen positiv = gekürzt; NULL/0 = vollständiger Beispielstatementtext.';
        PRINT N'@ParentQueryStatsSnapshot ist nur für die laufinterne Wiederverwendung durch USP_PlanCacheAnalysis bestimmt; 0 liest frisch.';
        PRINT N'@ResultSetArt RAW|CONSOLE|TABLE|NONE; @JsonErzeugen=1 setzt @Json OUTPUT; Steuerwerte sind case-insensitiv.';
        PRINT N'@PrintMeldungen bit=1; @Hilfe bit=0. Die Auswertung ist cachegebunden und keine Historie.';
        RETURN;
    END;

    DECLARE @CollectionTimeUtc datetime2(3)=SYSUTCDATETIME(),@StatusCode varchar(40)='AVAILABLE',@IsPartial bit=0,@RowCount bigint=0,
            @ErrorNumber int=NULL,@ErrorMessage nvarchar(2048)=NULL,@Detail nvarchar(2000)=NULL,@Allowed bit=1,
            @RequiredPermission nvarchar(256)=CASE WHEN TRY_CONVERT([int],SERVERPROPERTY(N'ProductMajorVersion'))>=16 THEN N'VIEW SERVER PERFORMANCE STATE' ELSE N'VIEW SERVER STATE' END;

    CREATE TABLE [#QueryHashAnalysis_Hash]
    (
        [QueryHash] binary(8) NOT NULL,[PlanVariantCount] int NOT NULL,[PlanHandleCount] int NOT NULL,[CompilationCount] bigint NOT NULL,
        [ExecutionCount] bigint NOT NULL,[TotalCpuUs] bigint NOT NULL,[TotalElapsedUs] bigint NOT NULL,[TotalReads] bigint NOT NULL,
        [TotalWrites] bigint NOT NULL,[TotalSpills] bigint NOT NULL,[MaxGrantKb] bigint NOT NULL,[FirstCreationTime] datetime NULL,
        [LastExecutionTime] datetime NULL,[SampleSqlHandle] varbinary(64) NULL,[SampleStartOffset] int NULL,[SampleEndOffset] int NULL
    );
    CREATE TABLE [#QueryHashAnalysis_QueryStatsSource]
    (
          [query_hash] binary(8) NULL
        , [query_plan_hash] binary(8) NULL
        , [plan_handle] varbinary(64) NULL
        , [sql_handle] varbinary(64) NULL
        , [statement_start_offset] int NULL
        , [statement_end_offset] int NULL
        , [execution_count] bigint NULL
        , [total_worker_time] bigint NULL
        , [total_elapsed_time] bigint NULL
        , [total_logical_reads] bigint NULL
        , [total_logical_writes] bigint NULL
        , [total_spills] bigint NULL
        , [max_grant_kb] bigint NULL
        , [creation_time] datetime NULL
        , [last_execution_time] datetime NULL
    );

    IF @Sortierung NOT IN('CPU_TOTAL','ELAPSED_TOTAL','READS_TOTAL','WRITES_TOTAL','EXECUTIONS','PLAN_VARIANTS','SPILLS_TOTAL')
    BEGIN SET @StatusCode='INVALID_PARAMETER';SET @ErrorMessage=N'Unbekannter Wert für @Sortierung.';END;
    IF @StatusCode='AVAILABLE' AND (@AnalyseModus NOT IN('TOP','VOLL') OR @MaxZeilen<0 OR @ResultSetArtNormalisiert NOT IN('RAW','CONSOLE','NONE') OR @MaxSqlTextZeichen < 0 OR @MinPlanVarianten<1 OR @MinExecutionCount<0 OR @ParentQueryStatsSnapshot IS NULL)
    BEGIN SET @StatusCode='INVALID_PARAMETER';SET @ErrorMessage=N'Ungültiger Parameterwert.';END;
    IF @StatusCode='AVAILABLE' AND (@AnalyseModus='VOLL' OR @QueryHash IS NULL OR @EffectiveMaxZeilen>1000)
        EXEC [monitor].[InternalCheckAnalysisPath] @AnalysisClass='PLAN_CACHE_DEEP',@HighImpactConfirmed=@HighImpactConfirmed,@StatusCode=@StatusCode OUTPUT,@ErrorMessage=@ErrorMessage OUTPUT;

    IF @StatusCode='AVAILABLE'
    BEGIN TRY
        IF @ParentQueryStatsSnapshot=1
        BEGIN
            EXEC [sys].[sp_executesql] N'
INSERT [#QueryHashAnalysis_QueryStatsSource]
SELECT [query_hash],[query_plan_hash],[plan_handle],[sql_handle],[statement_start_offset],[statement_end_offset],
       [execution_count],[total_worker_time],[total_elapsed_time],[total_logical_reads],[total_logical_writes],
       [total_spills],[max_grant_kb],[creation_time],[last_execution_time]
FROM [#PlanCacheAnalysis_QueryStatsSnapshot]
WHERE @QueryHash IS NULL OR [query_hash]=@QueryHash;',
                N'@QueryHash binary(8)',
                @QueryHash=@QueryHash;
        END
        ELSE
        BEGIN
            INSERT [#QueryHashAnalysis_QueryStatsSource]
            SELECT [query_hash],[query_plan_hash],[plan_handle],[sql_handle],[statement_start_offset],[statement_end_offset],
                   [execution_count],[total_worker_time],[total_elapsed_time],[total_logical_reads],[total_logical_writes],
                   [total_spills],[max_grant_kb],[creation_time],[last_execution_time]
            FROM [sys].[dm_exec_query_stats] WITH (NOLOCK)
            WHERE @QueryHash IS NULL OR [query_hash]=@QueryHash;
        END;
    END TRY
    BEGIN CATCH
        SET @ErrorNumber=ERROR_NUMBER();SET @ErrorMessage=ERROR_MESSAGE();SET @IsPartial=1;
        SET @StatusCode=CASE WHEN @ErrorNumber IN(229,262,297,300,371,916) THEN 'DENIED_PERMISSION'
                             WHEN @ErrorNumber=1222 THEN 'TIMEOUT' ELSE 'ERROR_HANDLED' END;
    END CATCH;

    IF @StatusCode='AVAILABLE'
    BEGIN TRY
        ;WITH G AS
        (
            SELECT [qs].[query_hash],COUNT(DISTINCT [qs].[query_plan_hash]) AS [PlanVariantCount],COUNT(DISTINCT [qs].[plan_handle]) AS [PlanHandleCount],
                   COUNT_BIG(*) AS [CompilationCount],SUM([qs].[execution_count]) AS [ExecutionCount],SUM([qs].[total_worker_time]) AS [TotalCpuUs],
                   SUM([qs].[total_elapsed_time]) AS [TotalElapsedUs],SUM([qs].[total_logical_reads]) AS [TotalReads],SUM([qs].[total_logical_writes]) AS [TotalWrites],
                   SUM([qs].[total_spills]) AS [TotalSpills],MAX([qs].[max_grant_kb]) AS [MaxGrantKb],MIN([qs].[creation_time]) AS [FirstCreationTime],
                   MAX([qs].[last_execution_time]) AS [LastExecutionTime]
            FROM [#QueryHashAnalysis_QueryStatsSource] AS qs
            WHERE [qs].[query_hash] IS NOT NULL AND (@QueryHash IS NULL OR [qs].[query_hash]=@QueryHash)
            GROUP BY [qs].[query_hash]
            HAVING SUM([qs].[execution_count])>=@MinExecutionCount AND COUNT(DISTINCT [qs].[query_plan_hash])>=@MinPlanVarianten
        ), R AS
        (
            SELECT TOP (@EffectiveMaxZeilen) *,ROW_NUMBER() OVER(ORDER BY
                CASE @Sortierung WHEN 'CPU_TOTAL' THEN [TotalCpuUs] WHEN 'ELAPSED_TOTAL' THEN [TotalElapsedUs] WHEN 'READS_TOTAL' THEN [TotalReads]
                    WHEN 'WRITES_TOTAL' THEN [TotalWrites] WHEN 'EXECUTIONS' THEN [ExecutionCount] WHEN 'PLAN_VARIANTS' THEN [PlanVariantCount]
                    WHEN 'SPILLS_TOTAL' THEN [TotalSpills] END DESC,[LastExecutionTime] DESC) AS [rn]
            FROM [G]
            WHERE @Sortierung IN('CPU_TOTAL','ELAPSED_TOTAL','READS_TOTAL','WRITES_TOTAL','EXECUTIONS','PLAN_VARIANTS','SPILLS_TOTAL')
        )
        INSERT [#QueryHashAnalysis_Hash]
        SELECT [r].[query_hash],[r].[PlanVariantCount],[r].[PlanHandleCount],[r].[CompilationCount],[r].[ExecutionCount],[r].[TotalCpuUs],[r].[TotalElapsedUs],
               [r].[TotalReads],[r].[TotalWrites],[r].[TotalSpills],[r].[MaxGrantKb],[r].[FirstCreationTime],[r].[LastExecutionTime],[s].[sql_handle],[s].[statement_start_offset],[s].[statement_end_offset]
        FROM [R] AS r
        OUTER APPLY
        (
            SELECT TOP(1) [qs].[sql_handle],[qs].[statement_start_offset],[qs].[statement_end_offset]
            FROM [#QueryHashAnalysis_QueryStatsSource] AS qs WHERE [qs].[query_hash]=[r].[query_hash] ORDER BY [qs].[total_worker_time] DESC
        ) AS s
        OPTION(RECOMPILE,MAXDOP 1);
        SET @RowCount=@@ROWCOUNT;SET @Detail=N'Query-Hash-Aggregation erfolgreich.';
    END TRY
    BEGIN CATCH
        SET @ErrorNumber=ERROR_NUMBER();SET @ErrorMessage=ERROR_MESSAGE();SET @IsPartial=1;
        SET @StatusCode=CASE WHEN @ErrorNumber IN(229,262,297,300,371,916) THEN 'DENIED_PERMISSION' ELSE 'ERROR_HANDLED' END;
    END CATCH;

    IF @PrintMeldungen=1 AND @StatusCode<>'AVAILABLE' BEGIN
    SET @MonitorPrintMessage = FORMATMESSAGE(N'WARNUNG USP_QueryHashAnalysis: %s - %s', @StatusCode, COALESCE(@ErrorMessage,N''));
    RAISERROR(N'%s', 10, 1, @MonitorPrintMessage) WITH NOWAIT;
END;
    CREATE TABLE [#QueryHashAnalysis_Output]
    (
          [QueryHash] binary(8) NOT NULL
        , [PlanVariantCount] int NOT NULL
        , [PlanHandleCount] int NOT NULL
        , [CompilationCount] bigint NOT NULL
        , [ExecutionCount] bigint NOT NULL
        , [TotalCpuMs] decimal(38,3) NULL
        , [AvgCpuMs] decimal(38,3) NULL
        , [TotalElapsedMs] decimal(38,3) NULL
        , [AvgElapsedMs] decimal(38,3) NULL
        , [TotalReads] bigint NOT NULL
        , [AvgReads] decimal(38,3) NULL
        , [TotalWrites] bigint NOT NULL
        , [TotalSpills] bigint NOT NULL
        , [MaxGrantKb] bigint NOT NULL
        , [FirstCreationTime] datetime NULL
        , [LastExecutionTime] datetime NULL
        , [SampleStatementTextCharacters] bigint NULL
        , [SampleStatementTextBytes] bigint NULL
        , [SampleStatementTextIsTruncated] bit NOT NULL DEFAULT(0)
        , [SampleStatementText] nvarchar(max) NULL
    );

    INSERT [#QueryHashAnalysis_Output]
    SELECT [h].[QueryHash],[h].[PlanVariantCount],[h].[PlanHandleCount],[h].[CompilationCount],[h].[ExecutionCount],
           CONVERT(decimal(38,3),[h].[TotalCpuUs]/1000.0),CONVERT(decimal(38,3),[h].[TotalCpuUs]/NULLIF([h].[ExecutionCount],0)/1000.0),
           CONVERT(decimal(38,3),[h].[TotalElapsedUs]/1000.0),CONVERT(decimal(38,3),[h].[TotalElapsedUs]/NULLIF([h].[ExecutionCount],0)/1000.0),
           [h].[TotalReads],CONVERT(decimal(38,3),[h].[TotalReads]*1.0/NULLIF([h].[ExecutionCount],0)),[h].[TotalWrites],[h].[TotalSpills],[h].[MaxGrantKb],
           [h].[FirstCreationTime],[h].[LastExecutionTime],
           NULL,NULL,CONVERT(bit,0),[statementText].[StatementText]
    FROM [#QueryHashAnalysis_Hash] AS [h]
    OUTER APPLY [sys].[dm_exec_sql_text]([h].[SampleSqlHandle]) AS [st]
    OUTER APPLY [monitor].[TVF_StatementText]
    (
          [st].[text]
        , [h].[SampleStartOffset]
        , [h].[SampleEndOffset]
    ) AS [statementText];

    DECLARE @TruncatedValueCount bigint=0,@LargestRequiredCharacters bigint=NULL;
    EXEC [monitor].[InternalProjectUnicodeTextColumn]
          @SourceTable=N'#QueryHashAnalysis_Output',@TextColumn=N'SampleStatementText'
        , @CharactersColumn=N'SampleStatementTextCharacters',@BytesColumn=N'SampleStatementTextBytes'
        , @IsTruncatedColumn=N'SampleStatementTextIsTruncated',@MaxCharacters=@MaxSqlTextZeichen
        , @TruncatedValueCount=@TruncatedValueCount OUTPUT,@LargestRequiredCharacters=@LargestRequiredCharacters OUTPUT;
    EXEC [monitor].[InternalEmitTruncationWarning]
          @TruncatedValueCount=@TruncatedValueCount,@ParameterName=N'@MaxSqlTextZeichen'
        , @ParameterValue=@MaxSqlTextZeichen,@LargestRequiredCharacters=@LargestRequiredCharacters
        , @PrintMeldungen=@PrintMeldungen;

    IF @ResultSetArtNormalisiert <> 'NONE'
    BEGIN
        SELECT N'USP_QueryHashAnalysis' [ModuleName],@CollectionTimeUtc [CollectionTimeUtc],@StatusCode [StatusCode],@IsPartial [IsPartial],@RowCount [RowCount],
               @RequiredPermission [RequiredPermission],@ErrorNumber [ErrorNumber],@ErrorMessage [ErrorMessage],@Detail [Detail];
        IF @ResultSetArtNormalisiert='RAW'
            SELECT * FROM [#QueryHashAnalysis_Output]
            ORDER BY CASE @Sortierung WHEN 'CPU_TOTAL' THEN [TotalCpuMs] WHEN 'ELAPSED_TOTAL' THEN [TotalElapsedMs] WHEN 'READS_TOTAL' THEN [TotalReads]
                WHEN 'WRITES_TOTAL' THEN [TotalWrites] WHEN 'EXECUTIONS' THEN [ExecutionCount] WHEN 'PLAN_VARIANTS' THEN [PlanVariantCount]
                WHEN 'SPILLS_TOTAL' THEN [TotalSpills] END DESC,[LastExecutionTime] DESC;
        ELSE
            SELECT N'Query-Hash-Aggregat' AS [Ergebnis],[QueryHash] AS [Query Hash],[PlanVariantCount] AS [Planvarianten],[ExecutionCount] AS [Ausführungen],
                   CONCAT(CONVERT(varchar(40),CONVERT(decimal(19,2),[TotalCpuMs])),N' ms') AS [CPU gesamt],
                   CONCAT(CONVERT(varchar(40),CONVERT(decimal(19,2),[AvgCpuMs])),N' ms') AS [CPU Ø],
                   [TotalReads] AS [Logical Reads],[TotalSpills] AS [Spills],[LastExecutionTime] AS [letzte Ausführung],[QueryHash] AS [Query Hash SQL],[SampleStatementText] AS [Beispielstatement]
            FROM [#QueryHashAnalysis_Output]
            ORDER BY CASE @Sortierung WHEN 'CPU_TOTAL' THEN [TotalCpuMs] WHEN 'ELAPSED_TOTAL' THEN [TotalElapsedMs] WHEN 'READS_TOTAL' THEN [TotalReads]
                WHEN 'WRITES_TOTAL' THEN [TotalWrites] WHEN 'EXECUTIONS' THEN [ExecutionCount] WHEN 'PLAN_VARIANTS' THEN [PlanVariantCount]
                WHEN 'SPILLS_TOTAL' THEN [TotalSpills] END DESC,[LastExecutionTime] DESC;
    END;
    IF @JsonErzeugen=1
    BEGIN
        DECLARE @MetaJson nvarchar(max)=(SELECT N'QueryHashAnalysis' [resultName],1 [schemaVersion],@CollectionTimeUtc [generatedAtUtc],@StatusCode [statusCode],@IsPartial [isPartial],@RowCount [returnedRows],@Sortierung [sortOrder],@ErrorNumber [errorNumber],@ErrorMessage [errorMessage] FOR JSON PATH,WITHOUT_ARRAY_WRAPPER,INCLUDE_NULL_VALUES);
        DECLARE @DataJson nvarchar(max)=(SELECT * FROM [#QueryHashAnalysis_Output] ORDER BY CASE @Sortierung WHEN 'CPU_TOTAL' THEN [TotalCpuMs] WHEN 'ELAPSED_TOTAL' THEN [TotalElapsedMs] WHEN 'READS_TOTAL' THEN [TotalReads] WHEN 'WRITES_TOTAL' THEN [TotalWrites] WHEN 'EXECUTIONS' THEN [ExecutionCount] WHEN 'PLAN_VARIANTS' THEN [PlanVariantCount] WHEN 'SPILLS_TOTAL' THEN [TotalSpills] END DESC,[LastExecutionTime] DESC FOR JSON PATH,INCLUDE_NULL_VALUES);
        SET @Json=CONCAT(N'{"meta":',COALESCE(@MetaJson,N'{}'),N',"queryHashes":',COALESCE(@DataJson,N'[]'),N',"warnings":[]}');
    END;
    IF @ConsoleResultRequested = 1
    BEGIN
        EXEC [monitor].[InternalEmitConsoleResult]
              @SourceTable=N'#QueryHashAnalysis_Output'
            , @ResultLabel=N'QueryHashAnalysis'
            , @EmptyMessage=N'Keine fachlichen Ergebnisse';
    END;
    IF @TableResultRequested = 1
    BEGIN
        EXEC [monitor].[InternalWriteResultTable]
              @SourceTable = N'#QueryHashAnalysis_Output'
            , @TargetTable=@TableTarget
            , @ThrowOnError = 1;
    END;
END;
GO
-- END SOURCE: Code/04_PlanCache/020_USP_QueryHashAnalysis.sql

-- BEGIN SOURCE: Code/04_PlanCache/030_USP_PlanCacheHealth.sql
/*
===============================================================================
Objekt       : monitor.USP_PlanCacheHealth
Version      : 2.0.0
Stand        : 2026-07-15
Typ          : Stored Procedure
Zweck        : Bewertet Größe, Wiederverwendung und Zusammensetzung des aktuellen
               Plan Cache ohne Showplan-XML.
SQL-Version  : SQL Server 2019 oder neuer.
Datenquellen : sys.dm_exec_cached_plans, sys.dm_exec_sql_text,
               sys.dm_exec_plan_attributes, sys.configurations.
Parameter    : @AnalyseModus, @MitDatenbankVerteilung, @MitSingleUseDetails,
               @MaxZeilen, @MaxSqlTextZeichen, @PrintMeldungen, @Hilfe.
Resultsets   : 1. Modulstatus. 2. Gesamtkennzahlen. 3. Verteilung nach Cache-/Objekttyp.
               4. optionale Datenbankverteilung. 5. optionale Single-use-Details.
Berechtigung : VIEW SERVER STATE bzw. SQL Server 2022+ VIEW SERVER PERFORMANCE STATE.
Eigenlast    : Basis gruppiert die Plan-Cache-DMV. Datenbankverteilung und Details
               sind opt-in und PLAN_CACHE_DEEP-geschützt.
Locking      : Keine Benutzerobjekte.
Partial      : Optionale Resultsets werden unabhängig behandelt.
Beispiele    : EXEC monitor.USP_PlanCacheHealth;
               EXEC monitor.USP_PlanCacheHealth @AnalyseModus='VOLL',@MitDatenbankVerteilung=1,@MitSingleUseDetails=1;
               EXEC monitor.USP_PlanCacheHealth @Hilfe=1;
Änderungen   : 1.0.1 - Stabile Summenzeile auch bei leerem Zwischenergebnis.
               1.0.0 - Erstfassung Phase 3.
===============================================================================
*/
CREATE OR ALTER PROCEDURE [monitor].[USP_PlanCacheHealth]
      @AnalyseModus               varchar(16) = 'SUMMARY'
    , @MitDatenbankVerteilung     bit         = 0
    , @MitSingleUseDetails        bit         = 0
    , @MaxZeilen                  int         = 100
    , @HighImpactConfirmed        bit         = 0
    , @MaxSqlTextZeichen          int         = 4000
    , @ResultSetArt               varchar(16) = 'CONSOLE'
    , @ResultTablesJson               nvarchar(max) = NULL
    , @JsonErzeugen               bit         = 0
    , @Json                        nvarchar(max) = NULL OUTPUT
    , @PrintMeldungen             bit         = 1
    , @Hilfe                      bit         = 0
AS
BEGIN
    SET NOCOUNT ON;
    SET LOCK_TIMEOUT 0;
    SET @Json=NULL;
    DECLARE @ResultSetArtNormalisiert varchar(16)=UPPER(LTRIM(RTRIM(COALESCE(@ResultSetArt,''))));
    DECLARE @TableResultRequested bit = CASE WHEN @ResultSetArtNormalisiert = 'TABLE' THEN 1 ELSE 0 END;
    DECLARE @ConsoleResultRequested bit = CASE WHEN @ResultSetArtNormalisiert = 'CONSOLE' THEN 1 ELSE 0 END;
    DECLARE @TableTarget sysname=NULL;
    IF @TableResultRequested=0 AND NULLIF(LTRIM(RTRIM(COALESCE(@ResultTablesJson,N''))),N'') IS NOT NULL THROW 51011,N'@ResultTablesJson ist ausschließlich mit @ResultSetArt=TABLE zulässig.',1;
    IF @TableResultRequested=1 EXEC [monitor].[InternalPrepareSingleResultTable] @ResultTablesJson=@ResultTablesJson,@ResultName=N'overview',@TargetTable=@TableTarget OUTPUT,@ThrowOnError=1;
    IF @TableResultRequested = 1 OR @ConsoleResultRequested = 1 SET @ResultSetArtNormalisiert = 'NONE';
    DECLARE @EffectiveMaxZeilen bigint = CASE WHEN @MaxZeilen IS NULL OR @MaxZeilen=0 THEN CONVERT(bigint,9223372036854775807) ELSE CONVERT(bigint,@MaxZeilen) END;
    DECLARE @MonitorPrintMessage nvarchar(2048);
    SET @AnalyseModus=UPPER(LTRIM(RTRIM(COALESCE(@AnalyseModus,'SUMMARY'))));
    IF @Hilfe=1
    BEGIN
        PRINT N'monitor.USP_PlanCacheHealth';
        PRINT N'@AnalyseModus SUMMARY oder VOLL. VOLL prüft PLAN_CACHE_DEEP.';
        PRINT N'@MitDatenbankVerteilung bit=0: wertet dbid-Planattribute aus; benötigt VOLL.';
        PRINT N'@MitSingleUseDetails bit=0: liefert begrenzte Texte großer Single-use-Pläne; benötigt VOLL.';
        PRINT N'@MaxZeilen int=100; @MaxSqlTextZeichen positiv = gekürzt, NULL/0 = vollständig; @ResultSetArt CONSOLE (Default)|RAW|TABLE|NONE; optional @Json OUTPUT.';
        PRINT N'@PrintMeldungen bit=1; @Hilfe bit=0.';
        PRINT N'usecounts kann durch Showplan-Nutzung beeinflusst werden; Resultate sind eine Momentaufnahme.';
        RETURN;
    END;

    DECLARE @CollectionTimeUtc datetime2(3)=SYSUTCDATETIME(),@StatusCode varchar(40)='AVAILABLE',@IsPartial bit=0,@RowCount bigint=0,
            @ErrorNumber int=NULL,@ErrorMessage nvarchar(2048)=NULL,@Detail nvarchar(2000)=NULL,@Allowed bit=1,
            @RequiredPermission nvarchar(256)=CASE WHEN TRY_CONVERT([int],SERVERPROPERTY(N'ProductMajorVersion'))>=16 THEN N'VIEW SERVER PERFORMANCE STATE' ELSE N'VIEW SERVER STATE' END;
    CREATE TABLE [#PlanCacheHealth_Summary]([CacheObjectType] nvarchar(34),[ObjectType] nvarchar(16),[PlanCount] bigint,[TotalSizeBytes] bigint,[SingleUsePlanCount] bigint,[SingleUseSizeBytes] bigint,[TotalUseCounts] bigint,[AverageUseCount] decimal(19,4));
    CREATE TABLE [#PlanCacheHealth_Db]([DatabaseId] int NULL,[DatabaseName] sysname NULL,[PlanCount] bigint,[TotalSizeBytes] bigint,[SingleUsePlanCount] bigint);
    CREATE TABLE [#PlanCacheHealth_Single]([PlanHandle] varbinary(64),[CacheObjectType] nvarchar(34),[ObjectType] nvarchar(16),[UseCounts] int,[SizeBytes] int,[DatabaseId] int NULL,[DatabaseName] sysname NULL,[SqlTextCharacters] bigint NULL,[SqlTextBytes] bigint NULL,[SqlTextIsTruncated] bit NOT NULL DEFAULT(0),[SqlText] nvarchar(max));

    IF @AnalyseModus NOT IN('SUMMARY','VOLL') OR @MaxZeilen<0 OR @ResultSetArtNormalisiert NOT IN('RAW','CONSOLE','NONE') OR @MaxSqlTextZeichen < 0
    BEGIN SET @StatusCode='INVALID_PARAMETER';SET @ErrorMessage=N'Ungültiger Parameterwert.';END;
    IF @StatusCode='AVAILABLE' AND (@AnalyseModus='VOLL' OR @MitDatenbankVerteilung=1 OR @MitSingleUseDetails=1)
        EXEC [monitor].[InternalCheckAnalysisPath] @AnalysisClass='PLAN_CACHE_DEEP',@HighImpactConfirmed=@HighImpactConfirmed,@StatusCode=@StatusCode OUTPUT,@ErrorMessage=@ErrorMessage OUTPUT;
    IF @StatusCode='AVAILABLE' AND @AnalyseModus='SUMMARY' AND (@MitDatenbankVerteilung=1 OR @MitSingleUseDetails=1)
    BEGIN SET @StatusCode='INVALID_PARAMETER';SET @ErrorMessage=N'Detailresultsets erfordern @AnalyseModus=VOLL.';END;

    IF @StatusCode='AVAILABLE'
    BEGIN TRY
        INSERT [#PlanCacheHealth_Summary]
        SELECT [cp].[cacheobjtype],[cp].[objtype],COUNT_BIG(*),SUM(CONVERT(bigint,[cp].[size_in_bytes])),
               SUM(CASE WHEN [cp].[usecounts]<=1 THEN CONVERT(bigint,1) ELSE 0 END),SUM(CASE WHEN [cp].[usecounts]<=1 THEN CONVERT(bigint,[cp].[size_in_bytes]) ELSE 0 END),
               SUM(CONVERT(bigint,[cp].[usecounts])),CONVERT(decimal(19,4),AVG(CONVERT(decimal(19,4),[cp].[usecounts])))
        FROM [sys].[dm_exec_cached_plans] AS cp WITH (NOLOCK)
        GROUP BY [cp].[cacheobjtype],[cp].[objtype] OPTION(MAXDOP 1);
        SET @RowCount=@@ROWCOUNT;SET @Detail=N'Plan-Cache-Zusammenfassung erfolgreich.';
    END TRY
    BEGIN CATCH
        SET @ErrorNumber=ERROR_NUMBER();SET @ErrorMessage=ERROR_MESSAGE();SET @IsPartial=1;
        SET @StatusCode=CASE WHEN @ErrorNumber IN(229,262,297,300,371,916) THEN 'DENIED_PERMISSION' ELSE 'ERROR_HANDLED' END;
    END CATCH;

    IF @StatusCode='AVAILABLE' AND @MitDatenbankVerteilung=1
    BEGIN TRY
        INSERT [#PlanCacheHealth_Db]
        SELECT TRY_CONVERT([int],[pa].[value]),[d].[name],COUNT_BIG(*),SUM(CONVERT(bigint,[cp].[size_in_bytes])),SUM(CASE WHEN [cp].[usecounts]<=1 THEN CONVERT(bigint,1) ELSE 0 END)
        FROM [sys].[dm_exec_cached_plans] AS cp WITH (NOLOCK)
        OUTER APPLY (SELECT TOP(1) [value] FROM sys.dm_exec_plan_attributes([cp].[plan_handle]) WHERE [attribute]='dbid') AS pa
        LEFT JOIN [master].[sys].[databases] AS [d] WITH (NOLOCK)
          ON [d].[database_id]=TRY_CONVERT([int],[pa].[value])
        GROUP BY TRY_CONVERT([int],[pa].[value]),[d].[name] OPTION(MAXDOP 1);
    END TRY BEGIN CATCH SET @IsPartial=1;SET @StatusCode='PARTIAL';IF @ErrorMessage IS NULL BEGIN SET @ErrorNumber=ERROR_NUMBER();SET @ErrorMessage=ERROR_MESSAGE();END;END CATCH;

    IF @StatusCode IN('AVAILABLE','PARTIAL') AND @MitSingleUseDetails=1
    BEGIN TRY
        ;WITH C AS
        (
            SELECT TOP (@EffectiveMaxZeilen) [cp].[plan_handle],[cp].[cacheobjtype],[cp].[objtype],[cp].[usecounts],[cp].[size_in_bytes]
            FROM [sys].[dm_exec_cached_plans] AS cp WITH (NOLOCK) WHERE [cp].[usecounts]<=1 ORDER BY [cp].[size_in_bytes] DESC
        )
        INSERT [#PlanCacheHealth_Single]
        SELECT [c].[plan_handle],[c].[cacheobjtype],[c].[objtype],[c].[usecounts],[c].[size_in_bytes],TRY_CONVERT([int],[pa].[value]),[d].[name],NULL,NULL,CONVERT(bit,0),[st].[text]
        FROM [C] AS c OUTER APPLY sys.dm_exec_sql_text([c].[plan_handle]) AS st
        OUTER APPLY (SELECT TOP(1) [value] FROM sys.dm_exec_plan_attributes([c].[plan_handle]) WHERE [attribute]='dbid') AS pa
        LEFT JOIN [master].[sys].[databases] AS [d] WITH (NOLOCK)
          ON [d].[database_id]=TRY_CONVERT([int],[pa].[value]);

        DECLARE @TruncatedValueCount bigint=0,@LargestRequiredCharacters bigint=NULL;
        EXEC [monitor].[InternalProjectUnicodeTextColumn]
              @SourceTable=N'#PlanCacheHealth_Single',@TextColumn=N'SqlText'
            , @CharactersColumn=N'SqlTextCharacters',@BytesColumn=N'SqlTextBytes'
            , @IsTruncatedColumn=N'SqlTextIsTruncated',@MaxCharacters=@MaxSqlTextZeichen
            , @TruncatedValueCount=@TruncatedValueCount OUTPUT,@LargestRequiredCharacters=@LargestRequiredCharacters OUTPUT;
        EXEC [monitor].[InternalEmitTruncationWarning]
              @TruncatedValueCount=@TruncatedValueCount,@ParameterName=N'@MaxSqlTextZeichen'
            , @ParameterValue=@MaxSqlTextZeichen,@LargestRequiredCharacters=@LargestRequiredCharacters
            , @PrintMeldungen=@PrintMeldungen;
    END TRY BEGIN CATCH SET @IsPartial=1;SET @StatusCode='PARTIAL';IF @ErrorMessage IS NULL BEGIN SET @ErrorNumber=ERROR_NUMBER();SET @ErrorMessage=ERROR_MESSAGE();END;END CATCH;

    IF @PrintMeldungen=1 AND @StatusCode NOT IN('AVAILABLE') BEGIN
    SET @MonitorPrintMessage = FORMATMESSAGE(N'WARNUNG USP_PlanCacheHealth: %s - %s', @StatusCode, COALESCE(@ErrorMessage,N''));
    RAISERROR(N'%s', 10, 1, @MonitorPrintMessage) WITH NOWAIT;
END;
    IF @ResultSetArtNormalisiert<>'NONE'
    BEGIN
        SELECT N'USP_PlanCacheHealth' [ModuleName],@CollectionTimeUtc [CollectionTimeUtc],@StatusCode [StatusCode],@IsPartial [IsPartial],@RowCount [RowCount],
               @RequiredPermission [RequiredPermission],@ErrorNumber [ErrorNumber],@ErrorMessage [ErrorMessage],@Detail [Detail];
        IF @ResultSetArtNormalisiert='RAW'
        BEGIN
            SELECT COALESCE(SUM([PlanCount]),0) AS [PlanCount],COALESCE(SUM([TotalSizeBytes]),0) AS [TotalSizeBytes],CONVERT(decimal(19,2),COALESCE(SUM([TotalSizeBytes]),0)/1048576.0) AS [TotalSizeMb],COALESCE(SUM([SingleUsePlanCount]),0) AS [SingleUsePlanCount],COALESCE(SUM([SingleUseSizeBytes]),0) AS [SingleUseSizeBytes],CONVERT(decimal(9,2),100.0*SUM([SingleUseSizeBytes])/NULLIF(SUM([TotalSizeBytes]),0)) AS [SingleUseMemoryPercent],(SELECT TOP(1) [value_in_use] FROM [sys].[configurations] WITH (NOLOCK) WHERE [name]='optimize for ad hoc workloads') AS [OptimizeForAdHocWorkloads] FROM [#PlanCacheHealth_Summary];
            SELECT * FROM [#PlanCacheHealth_Summary] ORDER BY [TotalSizeBytes] DESC,[PlanCount] DESC;
            IF @MitDatenbankVerteilung=1 SELECT * FROM [#PlanCacheHealth_Db] ORDER BY [TotalSizeBytes] DESC,[PlanCount] DESC;
            IF @MitSingleUseDetails=1 SELECT * FROM [#PlanCacheHealth_Single] ORDER BY [SizeBytes] DESC,[PlanHandle];
        END
        ELSE
        BEGIN
            SELECT N'Plan-Cache Übersicht' AS [Ergebnis],COALESCE(SUM([PlanCount]),0) AS [Pläne],CONCAT(CONVERT(varchar(40),CONVERT(decimal(19,2),COALESCE(SUM([TotalSizeBytes]),0)/1048576.0)),N' MB') AS [Größe],COALESCE(SUM([SingleUsePlanCount]),0) AS [Single-use-Pläne],CONCAT(CONVERT(varchar(40),CONVERT(decimal(9,2),100.0*SUM([SingleUseSizeBytes])/NULLIF(SUM([TotalSizeBytes]),0))),N' %') AS [Single-use-Speicher],(SELECT TOP(1) [value_in_use] FROM [sys].[configurations] WITH (NOLOCK) WHERE [name]='optimize for ad hoc workloads') AS [Optimize for ad hoc] FROM [#PlanCacheHealth_Summary];
            SELECT N'Plan-Cache Kategorie' AS [Ergebnis],[CacheObjectType] AS [Cacheobjekt],[ObjectType] AS [Objekttyp],[PlanCount] AS [Pläne],CONCAT(CONVERT(varchar(40),CONVERT(decimal(19,2),[TotalSizeBytes]/1048576.0)),N' MB') AS [Größe],[SingleUsePlanCount] AS [Single-use],[AverageUseCount] AS [Ø Verwendung] FROM [#PlanCacheHealth_Summary] ORDER BY [TotalSizeBytes] DESC,[PlanCount] DESC;
            IF @MitDatenbankVerteilung=1 SELECT N'Plan-Cache Datenbank' AS [Ergebnis],[DatabaseId] AS [Datenbank-ID],[DatabaseName] AS [Datenbank],[PlanCount] AS [Pläne],CONCAT(CONVERT(varchar(40),CONVERT(decimal(19,2),[TotalSizeBytes]/1048576.0)),N' MB') AS [Größe],[SingleUsePlanCount] AS [Single-use] FROM [#PlanCacheHealth_Db] ORDER BY [TotalSizeBytes] DESC,[PlanCount] DESC;
            IF @MitSingleUseDetails=1 SELECT N'Single-use Plan' AS [Ergebnis],[DatabaseName] AS [Datenbank],[UseCounts] AS [Verwendungen],CONCAT(CONVERT(varchar(40),CONVERT(decimal(19,2),[SizeBytes]/1048576.0)),N' MB') AS [Größe],[PlanHandle] AS [Planhandle],[DatabaseName] AS [Datenbank SQL],[SqlText] AS [SQL-Text] FROM [#PlanCacheHealth_Single] ORDER BY [SizeBytes] DESC,[PlanHandle];
        END;
    END;
    IF @JsonErzeugen=1
    BEGIN
        DECLARE @MetaJson nvarchar(max)=(SELECT N'PlanCacheHealth' [resultName],1 [schemaVersion],@CollectionTimeUtc [generatedAtUtc],@StatusCode [statusCode],@IsPartial [isPartial],@ErrorNumber [errorNumber],@ErrorMessage [errorMessage] FOR JSON PATH,WITHOUT_ARRAY_WRAPPER,INCLUDE_NULL_VALUES);
        DECLARE @OverviewJson nvarchar(max)=(SELECT COALESCE(SUM([PlanCount]),0) [planCount],COALESCE(SUM([TotalSizeBytes]),0) [totalSizeBytes],CONVERT(decimal(19,2),COALESCE(SUM([TotalSizeBytes]),0)/1048576.0) [totalSizeMb],COALESCE(SUM([SingleUsePlanCount]),0) [singleUsePlanCount],COALESCE(SUM([SingleUseSizeBytes]),0) [singleUseSizeBytes],CONVERT(decimal(9,2),100.0*SUM([SingleUseSizeBytes])/NULLIF(SUM([TotalSizeBytes]),0)) [singleUseMemoryPercent] FROM [#PlanCacheHealth_Summary] FOR JSON PATH,WITHOUT_ARRAY_WRAPPER,INCLUDE_NULL_VALUES);
        DECLARE @CategoriesJson nvarchar(max)=(SELECT * FROM [#PlanCacheHealth_Summary] ORDER BY [TotalSizeBytes] DESC,[PlanCount] DESC FOR JSON PATH,INCLUDE_NULL_VALUES),@DatabasesJson nvarchar(max)=(SELECT * FROM [#PlanCacheHealth_Db] ORDER BY [TotalSizeBytes] DESC,[PlanCount] DESC FOR JSON PATH,INCLUDE_NULL_VALUES),@SingleJson nvarchar(max)=(SELECT * FROM [#PlanCacheHealth_Single] ORDER BY [SizeBytes] DESC,[PlanHandle] FOR JSON PATH,INCLUDE_NULL_VALUES);
        SET @Json=CONCAT(N'{"meta":',COALESCE(@MetaJson,N'{}'),N',"overview":',COALESCE(@OverviewJson,N'{}'),N',"categories":',COALESCE(@CategoriesJson,N'[]'),N',"databases":',COALESCE(@DatabasesJson,N'[]'),N',"singleUsePlans":',COALESCE(@SingleJson,N'[]'),N',"warnings":[]}');
    END;
    IF @ConsoleResultRequested = 1
    BEGIN
        EXEC [monitor].[InternalEmitConsoleResult]
              @SourceTable=N'#PlanCacheHealth_Summary'
            , @ResultLabel=N'PlanCacheHealth'
            , @EmptyMessage=N'Keine fachlichen Ergebnisse';
    END;
    IF @TableResultRequested = 1
    BEGIN
        EXEC [monitor].[InternalWriteResultTable]
              @SourceTable = N'#PlanCacheHealth_Summary'
            , @TargetTable=@TableTarget
            , @ThrowOnError = 1;
    END;
END;
GO
-- END SOURCE: Code/04_PlanCache/030_USP_PlanCacheHealth.sql

-- BEGIN SOURCE: Code/04_PlanCache/040_USP_PlanDetails.sql
/*
===============================================================================
Objekt       : monitor.USP_PlanDetails
Version      : 2.0.0
Stand        : 2026-07-15
Typ          : Stored Procedure
Zweck        : Liefert gezielt SQL-Text, Planattribute, kompilierten Showplan,
               Text-Showplan, letzten bekannten Actual Plan oder Live-Plan.
SQL-Version  : SQL Server 2019 oder neuer.
Datenquellen : sys.dm_exec_requests, sys.dm_exec_query_stats,
               sys.dm_exec_sql_text, sys.dm_exec_plan_attributes,
               sys.dm_exec_query_plan, sys.dm_exec_text_query_plan,
               sys.dm_exec_query_plan_stats, sys.dm_exec_query_statistics_xml.
Parameter    : @SessionIds, @PlanHandle, @SqlHandle, @QueryHash,
               @MitPlanAttributes, @MitCompilePlan, @MitTextPlan,
               @MitLastActualPlan, @MitLivePlan, @MaxAnalyseobjekte,
               @MaxSqlTextZeichen, @PrintMeldungen, @Hilfe.
Resultsets   : 1. Modulstatus. 2. Kandidaten und SQL-Text. 3. Planattribute.
               4. angeforderte Pläne mit SourceType und Status.
Berechtigung : VIEW SERVER STATE bzw. SQL Server 2022+ VIEW SERVER PERFORMANCE STATE.
Eigenlast    : Zielgerichtet und auf @MaxAnalyseobjekte begrenzt. Mehr als 20 Pläne
               prüft PLAN_CACHE_DEEP. Das Framework aktiviert keine Profilingoption.
Locking      : Keine Benutzerobjekte.
Partial      : Jede Planquelle wird je Kandidat isoliert; fehlende oder evictete
               Pläne lassen andere Quellen und Kandidaten bestehen.
Beispiele    : EXEC monitor.USP_PlanDetails @SessionIds=N57,@MitLivePlan=1;
               EXEC monitor.USP_PlanDetails @PlanHandle=0x...;
               EXEC monitor.USP_PlanDetails @QueryHash=0x...,@MitLastActualPlan=1;
               EXEC monitor.USP_PlanDetails @Hilfe=1;
Änderungen   : 1.1.0 - Deep-Gate ab mehr als 20 Plänen.
               1.0.0 - Erstfassung Phase 3.
===============================================================================
*/
CREATE OR ALTER PROCEDURE [monitor].[USP_PlanDetails]
      @SessionIds            nvarchar(max)  = NULL
    , @PlanHandle            varbinary(64)  = NULL
    , @SqlHandle             varbinary(64)  = NULL
    , @QueryHash             binary(8)      = NULL
    , @MitPlanAttributes     bit            = 1
    , @MitCompilePlan        bit            = 1
    , @MitTextPlan           bit            = 0
    , @MitLastActualPlan     bit            = 0
    , @MitLivePlan           bit            = 0
    , @MaxAnalyseobjekte      int            = 20
    , @HighImpactConfirmed   bit            = 0
    , @MaxSqlTextZeichen     int            = 8000
    , @ResultSetArt          varchar(16)    = 'CONSOLE'
    , @ResultTablesJson               nvarchar(max) = NULL
    , @JsonErzeugen          bit            = 0
    , @Json                   nvarchar(max)  = NULL OUTPUT
    , @PrintMeldungen        bit            = 1
    , @Hilfe                 bit            = 0
AS
BEGIN
    SET NOCOUNT ON;
    SET @Json=NULL;
    DECLARE @ResultSetArtNormalisiert varchar(16)=UPPER(LTRIM(RTRIM(COALESCE(@ResultSetArt,''))));
    DECLARE @TableResultRequested bit = CASE WHEN @ResultSetArtNormalisiert = 'TABLE' THEN 1 ELSE 0 END;
    DECLARE @ConsoleResultRequested bit = CASE WHEN @ResultSetArtNormalisiert = 'CONSOLE' THEN 1 ELSE 0 END;
    CREATE TABLE [#PlanDetails_ResultTableMap]
    (
          [ResultName] sysname COLLATE SQL_Latin1_General_CP1_CS_AS NOT NULL
        , [TargetTable] sysname COLLATE SQL_Latin1_General_CP1_CS_AS NOT NULL
    );
    IF @TableResultRequested=0 AND NULLIF(LTRIM(RTRIM(COALESCE(@ResultTablesJson,N''))),N'') IS NOT NULL THROW 51011,N'@ResultTablesJson ist ausschließlich mit @ResultSetArt=TABLE zulässig.',1;
    IF @TableResultRequested=1
    BEGIN
        DECLARE @TablePreflightStatus varchar(40),@TablePreflightError nvarchar(2048);
        EXEC [monitor].[InternalPrepareResultTables]
              @ResultTablesJson=@ResultTablesJson
            , @AllowedResultNames=N'candidates|attributes|plans'
            , @MappingTable=N'#PlanDetails_ResultTableMap'
            , @StatusCode=@TablePreflightStatus OUTPUT
            , @ErrorMessage=@TablePreflightError OUTPUT
            , @ThrowOnError=1;
    END;
    IF @TableResultRequested = 1 OR @ConsoleResultRequested = 1 SET @ResultSetArtNormalisiert = 'NONE';
    DECLARE @SingleSessionId smallint=NULL;
    DECLARE @EffectiveMaxAnalyseobjekte bigint = CASE WHEN @MaxAnalyseobjekte IS NULL OR @MaxAnalyseobjekte=0 THEN CONVERT(bigint,9223372036854775807) ELSE CONVERT(bigint,@MaxAnalyseobjekte) END;
    DECLARE @MonitorPrintMessage nvarchar(2048);
    IF @Hilfe=1
    BEGIN
        PRINT N'monitor.USP_PlanDetails';
        PRINT N'Mindestens einer der Selektoren @SessionIds, @PlanHandle, @SqlHandle oder @QueryHash ist erforderlich.';
        PRINT N'@MitPlanAttributes bit=1; @MitCompilePlan bit=1; @MitTextPlan bit=0; @MitLastActualPlan bit=0; @MitLivePlan bit=0.';
        PRINT N'@MaxAnalyseobjekte int=20: positive Werte begrenzen; NULL/0 = unbegrenzt. Mehr als 20 oder unbegrenzt prüft PLAN_CACHE_DEEP.';
        PRINT N'@MaxSqlTextZeichen int=8000: positiv = gekürzt; NULL/0 = vollständiger Statement- und Batchtext; @PrintMeldungen bit=1; @Hilfe bit=0.';
        PRINT N'LAST_QUERY_PLAN_STATS und Live-Profiling werden nur gelesen, niemals aktiviert. NULL kann bedeuten: deaktiviert, Plan evictet, nicht cachebar oder nicht verfügbar.';
        RETURN;
    END;

    DECLARE @CollectionTimeUtc datetime2(3)=SYSUTCDATETIME(),@StatusCode varchar(40)='AVAILABLE',@IsPartial bit=0,@RowCount bigint=0,
            @ErrorNumber int=NULL,@ErrorMessage nvarchar(2048)=NULL,@Detail nvarchar(2000)=NULL,@Allowed bit=1,
            @RequiredPermission nvarchar(256)=CASE WHEN TRY_CONVERT([int],SERVERPROPERTY(N'ProductMajorVersion'))>=16 THEN N'VIEW SERVER PERFORMANCE STATE' ELSE N'VIEW SERVER STATE' END;

    CREATE TABLE [#PlanDetails_SessionIdFilter]([SessionId] smallint NOT NULL PRIMARY KEY);
    IF @SessionIds IS NOT NULL
    BEGIN
        IF EXISTS(SELECT 1 FROM [monitor].[TVF_ParseBigintList](@SessionIds) WHERE [IsValid]=0 OR [NumberValue] NOT BETWEEN 1 AND 32767)
        BEGIN SET @StatusCode='INVALID_PARAMETER';SET @ErrorMessage=N'@SessionIds enthält einen ungültigen Wert.';END
        ELSE INSERT [#PlanDetails_SessionIdFilter] SELECT CONVERT(smallint,[NumberValue]) FROM [monitor].[TVF_ParseBigintList](@SessionIds) GROUP BY [NumberValue];
        IF (SELECT COUNT_BIG(*) FROM [#PlanDetails_SessionIdFilter])=1 SELECT @SingleSessionId=MIN([SessionId]) FROM [#PlanDetails_SessionIdFilter];
    END;

    CREATE TABLE [#PlanDetails_Candidate]
    (
        [CandidateId] int IDENTITY(1,1) PRIMARY KEY,[SessionId] smallint NULL,[RequestId] int NULL,[PlanHandle] varbinary(64) NULL,
        [SqlHandle] varbinary(64) NULL,[QueryHash] binary(8) NULL,[QueryPlanHash] binary(8) NULL,[StatementStartOffset] int NULL,
        [StatementEndOffset] int NULL,[CreationTime] datetime NULL,[LastExecutionTime] datetime NULL,[ExecutionCount] bigint NULL
    );
    CREATE TABLE [#PlanDetails_Attributes]([CandidateId] int,[AttributeName] varchar(128),[AttributeValue] nvarchar(4000),[IsCacheKey] bit);
    CREATE TABLE [#PlanDetails_Plans]([CandidateId] int,[SourceType] varchar(24),[StatusCode] varchar(40),[DatabaseId] int NULL,[ObjectId] int NULL,[IsEncrypted] bit NULL,[QueryPlanXml] xml NULL,[QueryPlanText] nvarchar(max) NULL,[ErrorNumber] int NULL,[ErrorMessage] nvarchar(2048) NULL);

    SET LOCK_TIMEOUT 0;

    IF @SessionIds IS NULL AND @PlanHandle IS NULL AND @SqlHandle IS NULL AND @QueryHash IS NULL
    BEGIN SET @StatusCode='INVALID_PARAMETER';SET @ErrorMessage=N'Mindestens ein Selektor ist erforderlich.';END;
    IF @MaxAnalyseobjekte<0 OR @MaxSqlTextZeichen < 0 OR @ResultSetArtNormalisiert NOT IN('RAW','CONSOLE','NONE')
    BEGIN SET @StatusCode='INVALID_PARAMETER';SET @ErrorMessage=N'@MaxAnalyseobjekte oder @MaxSqlTextZeichen darf nicht negativ sein.';END;
    IF @StatusCode='AVAILABLE' AND @EffectiveMaxAnalyseobjekte>20
        EXEC [monitor].[InternalCheckAnalysisPath] @AnalysisClass='PLAN_CACHE_DEEP',@HighImpactConfirmed=@HighImpactConfirmed,@StatusCode=@StatusCode OUTPUT,@ErrorMessage=@ErrorMessage OUTPUT;

    IF @StatusCode='AVAILABLE'
    BEGIN TRY
        IF @SessionIds IS NOT NULL
        BEGIN
            INSERT [#PlanDetails_Candidate]([SessionId],[RequestId],[PlanHandle],[SqlHandle],[QueryHash],[QueryPlanHash],[StatementStartOffset],[StatementEndOffset],[CreationTime],[LastExecutionTime],[ExecutionCount])
            SELECT TOP (@EffectiveMaxAnalyseobjekte) [r].[session_id],[r].[request_id],[r].[plan_handle],[r].[sql_handle],[r].[query_hash],[r].[query_plan_hash],[r].[statement_start_offset],[r].[statement_end_offset],NULL,[r].[start_time],NULL
            FROM [sys].[dm_exec_requests] AS [r] WITH (NOLOCK) JOIN [#PlanDetails_SessionIdFilter] AS [sf] ON [sf].[SessionId]=[r].[session_id] ORDER BY [r].[session_id],[r].[request_id];
        END;
        IF @PlanHandle IS NOT NULL AND NOT EXISTS(SELECT 1 FROM [#PlanDetails_Candidate] WHERE [PlanHandle]=@PlanHandle)
            INSERT [#PlanDetails_Candidate]([PlanHandle]) VALUES(@PlanHandle);
        IF @SqlHandle IS NOT NULL
            INSERT [#PlanDetails_Candidate]([PlanHandle],[SqlHandle],[QueryHash],[QueryPlanHash],[StatementStartOffset],[StatementEndOffset],[CreationTime],[LastExecutionTime],[ExecutionCount])
            SELECT TOP (@EffectiveMaxAnalyseobjekte) [qs].[plan_handle],[qs].[sql_handle],[qs].[query_hash],[qs].[query_plan_hash],[qs].[statement_start_offset],[qs].[statement_end_offset],[qs].[creation_time],[qs].[last_execution_time],[qs].[execution_count]
            FROM [sys].[dm_exec_query_stats] AS qs WITH (NOLOCK) WHERE [qs].[sql_handle]=@SqlHandle AND NOT EXISTS(SELECT 1 FROM [#PlanDetails_Candidate] c WHERE [c].[PlanHandle]=[qs].[plan_handle] AND COALESCE([c].[StatementStartOffset],-1)=COALESCE([qs].[statement_start_offset],-1))
            ORDER BY [qs].[total_worker_time] DESC;
        IF @QueryHash IS NOT NULL
            INSERT [#PlanDetails_Candidate]([PlanHandle],[SqlHandle],[QueryHash],[QueryPlanHash],[StatementStartOffset],[StatementEndOffset],[CreationTime],[LastExecutionTime],[ExecutionCount])
            SELECT TOP (@EffectiveMaxAnalyseobjekte) [qs].[plan_handle],[qs].[sql_handle],[qs].[query_hash],[qs].[query_plan_hash],[qs].[statement_start_offset],[qs].[statement_end_offset],[qs].[creation_time],[qs].[last_execution_time],[qs].[execution_count]
            FROM [sys].[dm_exec_query_stats] AS qs WITH (NOLOCK) WHERE [qs].[query_hash]=@QueryHash AND NOT EXISTS(SELECT 1 FROM [#PlanDetails_Candidate] c WHERE [c].[PlanHandle]=[qs].[plan_handle] AND COALESCE([c].[StatementStartOffset],-1)=COALESCE([qs].[statement_start_offset],-1))
            ORDER BY [qs].[total_worker_time] DESC;
        DELETE [c] FROM [#PlanDetails_Candidate] AS c WHERE [c].[CandidateId] NOT IN(SELECT TOP (@EffectiveMaxAnalyseobjekte) [CandidateId] FROM [#PlanDetails_Candidate] ORDER BY [CandidateId]);
        SELECT @RowCount=COUNT_BIG(*) FROM [#PlanDetails_Candidate];SET @Detail=CASE WHEN @RowCount=0 THEN N'Kein passender Planhandle sichtbar.' ELSE N'Kandidaten erfolgreich ermittelt.' END;
    END TRY
    BEGIN CATCH
        SET @ErrorNumber=ERROR_NUMBER();SET @ErrorMessage=ERROR_MESSAGE();SET @IsPartial=1;
        SET @StatusCode=CASE WHEN @ErrorNumber IN(229,262,297,300,371,916) THEN 'DENIED_PERMISSION' ELSE 'ERROR_HANDLED' END;
    END CATCH;

    IF @StatusCode='AVAILABLE' AND @MitPlanAttributes=1
    BEGIN TRY
        INSERT [#PlanDetails_Attributes]
        SELECT [c].[CandidateId],[pa].[attribute],CONVERT(nvarchar(4000),[pa].[value]),[pa].[is_cache_key]
        FROM [#PlanDetails_Candidate] AS c CROSS APPLY sys.dm_exec_plan_attributes([c].[PlanHandle]) AS pa;
    END TRY BEGIN CATCH SET @IsPartial=1;SET @StatusCode='PARTIAL';IF @ErrorMessage IS NULL BEGIN SET @ErrorNumber=ERROR_NUMBER();SET @ErrorMessage=ERROR_MESSAGE();END;END CATCH;

    IF @StatusCode IN('AVAILABLE','PARTIAL') AND @MitCompilePlan=1
    BEGIN TRY
        INSERT [#PlanDetails_Plans]
        SELECT [c].[CandidateId],'COMPILE_XML',CASE WHEN [qp].[query_plan] IS NULL THEN 'UNAVAILABLE_OBJECT' ELSE 'AVAILABLE' END,[qp].[dbid],[qp].[objectid],[qp].[encrypted],[qp].[query_plan],NULL,NULL,CASE WHEN [qp].[query_plan] IS NULL THEN N'Plan nicht mehr im Cache oder XML-Tiefenlimit erreicht.' END
        FROM [#PlanDetails_Candidate] AS c OUTER APPLY sys.dm_exec_query_plan([c].[PlanHandle]) AS qp;
    END TRY BEGIN CATCH INSERT [#PlanDetails_Plans] SELECT [CandidateId],'COMPILE_XML','ERROR_HANDLED',NULL,NULL,NULL,NULL,NULL,ERROR_NUMBER(),ERROR_MESSAGE() FROM [#PlanDetails_Candidate];SET @IsPartial=1;SET @StatusCode='PARTIAL';END CATCH;

    IF @StatusCode IN('AVAILABLE','PARTIAL') AND @MitTextPlan=1
    BEGIN TRY
        INSERT [#PlanDetails_Plans]
        SELECT [c].[CandidateId],'COMPILE_TEXT',CASE WHEN [tp].[query_plan] IS NULL THEN 'UNAVAILABLE_OBJECT' ELSE 'AVAILABLE' END,[tp].[dbid],[tp].[objectid],[tp].[encrypted],NULL,[tp].[query_plan],NULL,CASE WHEN [tp].[query_plan] IS NULL THEN N'Textplan nicht verfügbar.' END
        FROM [#PlanDetails_Candidate] AS c OUTER APPLY sys.dm_exec_text_query_plan([c].[PlanHandle],COALESCE([c].[StatementStartOffset],0),COALESCE([c].[StatementEndOffset],-1)) AS tp;
    END TRY BEGIN CATCH INSERT [#PlanDetails_Plans] SELECT [CandidateId],'COMPILE_TEXT','ERROR_HANDLED',NULL,NULL,NULL,NULL,NULL,ERROR_NUMBER(),ERROR_MESSAGE() FROM [#PlanDetails_Candidate];SET @IsPartial=1;SET @StatusCode='PARTIAL';END CATCH;

    IF @StatusCode IN('AVAILABLE','PARTIAL') AND @MitLastActualPlan=1
    BEGIN TRY
        INSERT [#PlanDetails_Plans]
        SELECT [c].[CandidateId],'LAST_ACTUAL_XML',CASE WHEN [qp].[query_plan] IS NULL THEN 'AVAILABLE_DISABLED' ELSE 'AVAILABLE' END,[qp].[dbid],[qp].[objectid],[qp].[encrypted],[qp].[query_plan],NULL,NULL,
               CASE WHEN [qp].[query_plan] IS NULL THEN N'LAST_QUERY_PLAN_STATS nicht aktiviert, Plan nicht geeignet, nicht cachebar oder bereits evictet.' END
        FROM [#PlanDetails_Candidate] AS c OUTER APPLY sys.dm_exec_query_plan_stats([c].[PlanHandle]) AS qp;
    END TRY BEGIN CATCH INSERT [#PlanDetails_Plans] SELECT [CandidateId],'LAST_ACTUAL_XML','ERROR_HANDLED',NULL,NULL,NULL,NULL,NULL,ERROR_NUMBER(),ERROR_MESSAGE() FROM [#PlanDetails_Candidate];SET @IsPartial=1;SET @StatusCode='PARTIAL';END CATCH;

    IF @StatusCode IN('AVAILABLE','PARTIAL') AND @MitLivePlan=1
    BEGIN TRY
        IF @SingleSessionId IS NULL
            INSERT [#PlanDetails_Plans] VALUES(NULL,'LIVE_XML','INVALID_PARAMETER',NULL,NULL,NULL,NULL,NULL,NULL,N'@MitLivePlan erfordert genau eine Session in @SessionIds.');
        ELSE
            INSERT [#PlanDetails_Plans]
            SELECT [c].[CandidateId],'LIVE_XML',CASE WHEN [qx].[query_plan] IS NULL THEN 'UNAVAILABLE_OBJECT' ELSE 'AVAILABLE' END,NULL,NULL,NULL,[qx].[query_plan],NULL,NULL,
                   CASE WHEN [qx].[query_plan] IS NULL THEN N'Request nicht mehr aktiv oder Live-Plan nicht verfügbar.' END
            FROM [sys].[dm_exec_query_statistics_xml](@SingleSessionId) AS [qx]
            LEFT JOIN [#PlanDetails_Candidate] AS c ON [c].[SessionId]=[qx].[session_id] AND ([c].[RequestId]=[qx].[request_id] OR [c].[RequestId] IS NULL);
    END TRY BEGIN CATCH INSERT [#PlanDetails_Plans] VALUES(NULL,'LIVE_XML','ERROR_HANDLED',NULL,NULL,NULL,NULL,NULL,ERROR_NUMBER(),ERROR_MESSAGE());SET @IsPartial=1;SET @StatusCode='PARTIAL';END CATCH;

    IF @PrintMeldungen=1 AND @StatusCode NOT IN('AVAILABLE') BEGIN
    SET @MonitorPrintMessage = FORMATMESSAGE(N'WARNUNG USP_PlanDetails: %s - %s', @StatusCode, COALESCE(@ErrorMessage,N''));
    RAISERROR(N'%s', 10, 1, @MonitorPrintMessage) WITH NOWAIT;
END;
    CREATE TABLE [#PlanDetails_CandidatesOutput]
    (
          [CandidateId] int,[SessionId] smallint NULL,[RequestId] int NULL,[PlanHandle] varbinary(64) NULL,[SqlHandle] varbinary(64) NULL
        , [QueryHash] binary(8) NULL,[QueryPlanHash] binary(8) NULL,[StatementStartOffset] int NULL,[StatementEndOffset] int NULL
        , [CreationTime] datetime NULL,[LastExecutionTime] datetime NULL,[ExecutionCount] bigint NULL
        , [StatementTextCharacters] bigint NULL,[StatementTextBytes] bigint NULL,[StatementTextIsTruncated] bit NOT NULL DEFAULT(0),[StatementText] nvarchar(max) NULL
        , [BatchTextCharacters] bigint NULL,[BatchTextBytes] bigint NULL,[BatchTextIsTruncated] bit NOT NULL DEFAULT(0),[BatchText] nvarchar(max) NULL
        , [SqlTextDatabaseId] int NULL,[SqlTextDatabaseName] sysname NULL,[SqlTextObjectId] int NULL
    );
    INSERT [#PlanDetails_CandidatesOutput]
    SELECT [c].[CandidateId],[c].[SessionId],[c].[RequestId],[c].[PlanHandle],[c].[SqlHandle],[c].[QueryHash],[c].[QueryPlanHash],[c].[StatementStartOffset],[c].[StatementEndOffset],[c].[CreationTime],[c].[LastExecutionTime],[c].[ExecutionCount],
           NULL,NULL,CONVERT(bit,0),[statementText].[StatementText],
           NULL,NULL,CONVERT(bit,0),[st].[text],[st].[dbid],(SELECT [name] FROM [master].[sys].[databases] WITH (NOLOCK) WHERE [database_id] = [st].[dbid]),[st].[objectid]
    FROM [#PlanDetails_Candidate] AS [c]
    OUTER APPLY [sys].[dm_exec_sql_text](COALESCE([c].[SqlHandle],[c].[PlanHandle])) AS [st]
    OUTER APPLY [monitor].[TVF_StatementText]
    (
          [st].[text]
        , [c].[StatementStartOffset]
        , [c].[StatementEndOffset]
    ) AS [statementText];

    DECLARE @TruncatedValueCount bigint=0,@LargestRequiredCharacters bigint=NULL;
    DECLARE @ColumnTruncatedCount bigint=0,@ColumnLargestCharacters bigint=NULL;
    EXEC [monitor].[InternalProjectUnicodeTextColumn]
          @SourceTable=N'#PlanDetails_CandidatesOutput',@TextColumn=N'StatementText'
        , @CharactersColumn=N'StatementTextCharacters',@BytesColumn=N'StatementTextBytes'
        , @IsTruncatedColumn=N'StatementTextIsTruncated',@MaxCharacters=@MaxSqlTextZeichen
        , @TruncatedValueCount=@ColumnTruncatedCount OUTPUT,@LargestRequiredCharacters=@ColumnLargestCharacters OUTPUT;
    SELECT @TruncatedValueCount=@TruncatedValueCount+@ColumnTruncatedCount,
           @LargestRequiredCharacters=CASE WHEN @LargestRequiredCharacters IS NULL OR @ColumnLargestCharacters>@LargestRequiredCharacters THEN @ColumnLargestCharacters ELSE @LargestRequiredCharacters END;
    EXEC [monitor].[InternalProjectUnicodeTextColumn]
          @SourceTable=N'#PlanDetails_CandidatesOutput',@TextColumn=N'BatchText'
        , @CharactersColumn=N'BatchTextCharacters',@BytesColumn=N'BatchTextBytes'
        , @IsTruncatedColumn=N'BatchTextIsTruncated',@MaxCharacters=@MaxSqlTextZeichen
        , @TruncatedValueCount=@ColumnTruncatedCount OUTPUT,@LargestRequiredCharacters=@ColumnLargestCharacters OUTPUT;
    SELECT @TruncatedValueCount=@TruncatedValueCount+@ColumnTruncatedCount,
           @LargestRequiredCharacters=CASE WHEN @LargestRequiredCharacters IS NULL OR @ColumnLargestCharacters>@LargestRequiredCharacters THEN @ColumnLargestCharacters ELSE @LargestRequiredCharacters END;
    EXEC [monitor].[InternalEmitTruncationWarning]
          @TruncatedValueCount=@TruncatedValueCount,@ParameterName=N'@MaxSqlTextZeichen'
        , @ParameterValue=@MaxSqlTextZeichen,@LargestRequiredCharacters=@LargestRequiredCharacters
        , @PrintMeldungen=@PrintMeldungen;
    IF @ResultSetArtNormalisiert<>'NONE'
    BEGIN
        SELECT N'USP_PlanDetails' [ModuleName],@CollectionTimeUtc [CollectionTimeUtc],@StatusCode [StatusCode],@IsPartial [IsPartial],@RowCount [RowCount],@RequiredPermission [RequiredPermission],@ErrorNumber [ErrorNumber],@ErrorMessage [ErrorMessage],@Detail [Detail];
        IF @ResultSetArtNormalisiert='RAW'
        BEGIN
            SELECT * FROM [#PlanDetails_CandidatesOutput] ORDER BY [CandidateId];
            IF @MitPlanAttributes=1 SELECT * FROM [#PlanDetails_Attributes] ORDER BY [CandidateId],[AttributeName];
            IF @MitCompilePlan=1 OR @MitTextPlan=1 OR @MitLastActualPlan=1 OR @MitLivePlan=1 SELECT * FROM [#PlanDetails_Plans] ORDER BY [CandidateId],[SourceType];
        END
        ELSE
        BEGIN
            SELECT N'Plan-Kandidat' AS [Ergebnis],[CandidateId] AS [Kandidat],[SessionId] AS [Session],[RequestId] AS [Request],[SqlTextDatabaseName] AS [Datenbank],[QueryHash] AS [Query Hash],[QueryPlanHash] AS [Plan Hash],[ExecutionCount] AS [Ausführungen],[LastExecutionTime] AS [letzte Ausführung],[SessionId] AS [Session SQL],[StatementText] AS [Statement],[BatchText] AS [Batch] FROM [#PlanDetails_CandidatesOutput] ORDER BY [CandidateId];
            IF @MitPlanAttributes=1 SELECT N'Planattribut' AS [Ergebnis],[CandidateId] AS [Kandidat],[AttributeName] AS [Attribut],[AttributeValue] AS [Wert],[IsCacheKey] AS [Cache-Key] FROM [#PlanDetails_Attributes] ORDER BY [CandidateId],[AttributeName];
            IF @MitCompilePlan=1 OR @MitTextPlan=1 OR @MitLastActualPlan=1 OR @MitLivePlan=1 SELECT N'Planinhalt' AS [Ergebnis],[CandidateId] AS [Kandidat],[SourceType] AS [Quelle],[StatusCode] AS [Status],[DatabaseId] AS [Datenbank-ID],[ObjectId] AS [Objekt-ID],[ErrorMessage] AS [Hinweis],[QueryPlanXml] AS [Plan XML],[QueryPlanText] AS [Plan Text] FROM [#PlanDetails_Plans] ORDER BY [CandidateId],[SourceType];
        END;
    END;
    IF @JsonErzeugen=1
    BEGIN
        DECLARE @MetaJson nvarchar(max)=(SELECT N'PlanDetails' [resultName],1 [schemaVersion],@CollectionTimeUtc [generatedAtUtc],@StatusCode [statusCode],@IsPartial [isPartial],@RowCount [candidateCount],@ErrorNumber [errorNumber],@ErrorMessage [errorMessage] FOR JSON PATH,WITHOUT_ARRAY_WRAPPER,INCLUDE_NULL_VALUES);
        DECLARE @CandidatesJson nvarchar(max)=(SELECT * FROM [#PlanDetails_CandidatesOutput] ORDER BY [CandidateId] FOR JSON PATH,INCLUDE_NULL_VALUES),@AttributesJson nvarchar(max)=(SELECT * FROM [#PlanDetails_Attributes] ORDER BY [CandidateId],[AttributeName] FOR JSON PATH,INCLUDE_NULL_VALUES),@PlansJson nvarchar(max)=(SELECT [CandidateId],[SourceType],[StatusCode],[DatabaseId],[ObjectId],[IsEncrypted],CONVERT(nvarchar(max),[QueryPlanXml]) [QueryPlanXml],[QueryPlanText],[ErrorNumber],[ErrorMessage] FROM [#PlanDetails_Plans] ORDER BY [CandidateId],[SourceType] FOR JSON PATH,INCLUDE_NULL_VALUES);
        SET @Json=CONCAT(N'{"meta":',COALESCE(@MetaJson,N'{}'),N',"candidates":',COALESCE(@CandidatesJson,N'[]'),N',"attributes":',COALESCE(@AttributesJson,N'[]'),N',"plans":',COALESCE(@PlansJson,N'[]'),N',"warnings":[]}');
    END;
    IF @ConsoleResultRequested = 1
    BEGIN
        EXEC [monitor].[InternalEmitConsoleResult]
              @SourceTable=N'#PlanDetails_CandidatesOutput'
            , @ResultLabel=N'PlanDetails'
            , @EmptyMessage=N'Keine fachlichen Ergebnisse';
    END;
    IF @TableResultRequested = 1
    BEGIN
        DECLARE @TableResultName sysname,@TableTarget sysname,@TableSource sysname;
        DECLARE [TableResultCursor] CURSOR LOCAL FAST_FORWARD FOR
            SELECT [ResultName],[TargetTable] FROM [#PlanDetails_ResultTableMap] ORDER BY [ResultName];
        OPEN [TableResultCursor];
        FETCH NEXT FROM [TableResultCursor] INTO @TableResultName,@TableTarget;
        WHILE @@FETCH_STATUS=0
        BEGIN
            SET @TableSource=CASE @TableResultName
                WHEN N'candidates' THEN N'#PlanDetails_CandidatesOutput'
                WHEN N'attributes' THEN N'#PlanDetails_Attributes'
                WHEN N'plans' THEN N'#PlanDetails_Plans' END;
            EXEC [monitor].[InternalWriteResultTable]
                  @SourceTable=@TableSource,@TargetTable=@TableTarget,@ThrowOnError=1;
            FETCH NEXT FROM [TableResultCursor] INTO @TableResultName,@TableTarget;
        END;
        CLOSE [TableResultCursor];DEALLOCATE [TableResultCursor];
    END;
END;
GO
-- END SOURCE: Code/04_PlanCache/040_USP_PlanDetails.sql

-- BEGIN SOURCE: Code/04_PlanCache/041_PlanAnalysisProfile.sql
/*
===============================================================================
Objekt       : monitor.PlanAnalysisProfile
Version      : 1.0.0
Stand        : 2026-07-21
Typ          : Steuertabelle
Zweck        : Definiert generische Workloadprofile für die eigenständige und
               frameworkintegrierte Execution-Plan-Analyse.
Datenschutz  : Enthält ausschließlich generische Frameworkwerte. Lokale reale
               Zuordnungen werden nicht als Repositoryseed ausgeliefert.
===============================================================================
*/
IF NOT EXISTS
(
    SELECT 1
    FROM [sys].[tables] AS [t] WITH (NOLOCK)
    JOIN [sys].[schemas] AS [s] WITH (NOLOCK)
      ON [s].[schema_id]=[t].[schema_id]
    WHERE [s].[name]=N'monitor'
      AND [t].[name]=N'PlanAnalysisProfile'
)
BEGIN
    CREATE TABLE [monitor].[PlanAnalysisProfile]
    (
          [ProfileCode]        varchar(32)    NOT NULL
        , [Description]        nvarchar(1000) NOT NULL
        , [Priority]           smallint       NOT NULL
        , [IsEnabled]          bit            NOT NULL
            CONSTRAINT [DF_PlanAnalysisProfile_IsEnabled] DEFAULT (1)
        , [IsFrameworkDefault] bit            NOT NULL
            CONSTRAINT [DF_PlanAnalysisProfile_IsFrameworkDefault] DEFAULT (0)
        , [SeedVersion]        int            NOT NULL
            CONSTRAINT [DF_PlanAnalysisProfile_SeedVersion] DEFAULT (0)
        , [LastUpdatedUtc]     datetime2(0)   NOT NULL
            CONSTRAINT [DF_PlanAnalysisProfile_LastUpdatedUtc] DEFAULT (SYSUTCDATETIME())
        , CONSTRAINT [PK_PlanAnalysisProfile]
            PRIMARY KEY CLUSTERED ([ProfileCode])
        , CONSTRAINT [CK_PlanAnalysisProfile_Priority]
            CHECK ([Priority] BETWEEN 1 AND 32767)
    );
END;
GO

DECLARE @SeedVersion int=1;
DECLARE @Defaults TABLE
(
      [ProfileCode] varchar(32) NOT NULL PRIMARY KEY
    , [Description] nvarchar(1000) NOT NULL
    , [Priority] smallint NOT NULL
);

INSERT @Defaults([ProfileCode],[Description],[Priority])
VALUES
  ('LATENCY_SENSITIVE',N'Interaktive oder hochfrequente Zugriffe; je Ausführung und Wiederholungsrate werden stärker gewichtet.',100),
  ('BALANCED',N'Neutraler Frameworkstandard für gemischte Workloads ohne belastbare explizite Zuordnung.',200),
  ('THROUGHPUT',N'Mengen- und Durchsatzverarbeitung; absolute CPU-, I/O-, TempDB- und Datenmengen werden stärker gewichtet.',300),
  ('MAINTENANCE',N'Wartungs- und strukturverändernde Verarbeitung; große Scans und Sorts können fachlich erwartet sein.',400),
  ('UNKNOWN',N'Workloadprofil nicht belastbar bestimmbar; Findings bleiben konservativ und weisen die geringe Zuordnungssicherheit aus.',500);

UPDATE [p]
SET
      [p].[Description]=[d].[Description]
    , [p].[Priority]=[d].[Priority]
    , [p].[IsEnabled]=1
    , [p].[SeedVersion]=@SeedVersion
    , [p].[LastUpdatedUtc]=SYSUTCDATETIME()
FROM [monitor].[PlanAnalysisProfile] AS [p]
JOIN @Defaults AS [d]
  ON [d].[ProfileCode]=[p].[ProfileCode]
WHERE [p].[IsFrameworkDefault]=1
  AND [p].[SeedVersion]<@SeedVersion;

INSERT [monitor].[PlanAnalysisProfile]
(
      [ProfileCode],[Description],[Priority],[IsEnabled]
    , [IsFrameworkDefault],[SeedVersion]
)
SELECT [d].[ProfileCode],[d].[Description],[d].[Priority],1,1,@SeedVersion
FROM @Defaults AS [d]
WHERE NOT EXISTS
(
    SELECT 1
    FROM [monitor].[PlanAnalysisProfile] AS [p]
    WHERE [p].[ProfileCode]=[d].[ProfileCode]
);
GO
-- END SOURCE: Code/04_PlanCache/041_PlanAnalysisProfile.sql

-- BEGIN SOURCE: Code/04_PlanCache/042_PlanAnalysisRuleThreshold.sql
/*
===============================================================================
Objekt       : monitor.PlanAnalysisRuleThreshold
Version      : 1.0.0
Stand        : 2026-07-21
Typ          : Steuertabelle
Zweck        : Hält ausschließlich Datenwerte für plananalytische Schwellen.
               Die ausführbare Regellogik verbleibt in geprüftem T-SQL-Code.
Hinweis      : Alle ausgelieferten Werte sind Triageheuristiken und keine
               Microsoft-Grenzwerte oder automatische Tuninganweisung.
===============================================================================
*/
IF NOT EXISTS
(
    SELECT 1
    FROM [sys].[tables] AS [t] WITH (NOLOCK)
    JOIN [sys].[schemas] AS [s] WITH (NOLOCK)
      ON [s].[schema_id]=[t].[schema_id]
    WHERE [s].[name]=N'monitor'
      AND [t].[name]=N'PlanAnalysisRuleThreshold'
)
BEGIN
    CREATE TABLE [monitor].[PlanAnalysisRuleThreshold]
    (
          [RuleCode]                    varchar(100)  NOT NULL
        , [ProfileCode]                 varchar(32)   NOT NULL
        , [Severity]                    varchar(16)   NOT NULL
        , [IsEnabled]                   bit           NOT NULL
            CONSTRAINT [DF_PlanAnalysisRuleThreshold_IsEnabled] DEFAULT (1)
        , [MinRatio]                    decimal(19,6) NULL
        , [MaxRatio]                    decimal(19,6) NULL
        , [MinAbsoluteRows]             bigint        NULL
        , [MinRowsRead]                 bigint        NULL
        , [MinRowsNotReturned]          bigint        NULL
        , [MinRowsNotReturnedPercent]   decimal(9,4)  NULL
        , [MinExecutionCount]           bigint        NULL
        , [MinLogicalReadsPerExecution] bigint        NULL
        , [MinTotalLogicalReads]        bigint        NULL
        , [MinElapsedMs]                bigint        NULL
        , [MinCpuMs]                    bigint        NULL
        , [MinSpilledPages]             bigint        NULL
        , [MinMemoryKb]                 bigint        NULL
        , [MinServerMajorVersion]       tinyint       NULL
        , [MinCompatibilityLevel]       smallint      NULL
        , [RequiredEvidenceLevel]       varchar(32)   NULL
        , [AdditionalConfigurationJson] nvarchar(max) NULL
        , [IsFrameworkDefault]          bit           NOT NULL
            CONSTRAINT [DF_PlanAnalysisRuleThreshold_IsFrameworkDefault] DEFAULT (0)
        , [SeedVersion]                 int            NOT NULL
            CONSTRAINT [DF_PlanAnalysisRuleThreshold_SeedVersion] DEFAULT (0)
        , [LastUpdatedUtc]              datetime2(0)   NOT NULL
            CONSTRAINT [DF_PlanAnalysisRuleThreshold_LastUpdatedUtc] DEFAULT (SYSUTCDATETIME())
        , CONSTRAINT [PK_PlanAnalysisRuleThreshold]
            PRIMARY KEY CLUSTERED ([RuleCode],[ProfileCode],[Severity])
        , CONSTRAINT [FK_PlanAnalysisRuleThreshold_Profile]
            FOREIGN KEY ([ProfileCode])
            REFERENCES [monitor].[PlanAnalysisProfile]([ProfileCode])
        , CONSTRAINT [CK_PlanAnalysisRuleThreshold_Severity]
            CHECK ([Severity] IN ('INFO','LOW','MEDIUM','HIGH','CRITICAL'))
        , CONSTRAINT [CK_PlanAnalysisRuleThreshold_Json]
            CHECK ([AdditionalConfigurationJson] IS NULL OR ISJSON([AdditionalConfigurationJson])=1)
    );
END;
GO

DECLARE @SeedVersion int=1;
DECLARE @Defaults TABLE
(
      [RuleCode] varchar(100) NOT NULL
    , [ProfileCode] varchar(32) NOT NULL
    , [Severity] varchar(16) NOT NULL
    , [MinRatio] decimal(19,6) NULL
    , [MaxRatio] decimal(19,6) NULL
    , [MinAbsoluteRows] bigint NULL
    , [MinRowsRead] bigint NULL
    , [MinRowsNotReturned] bigint NULL
    , [MinRowsNotReturnedPercent] decimal(9,4) NULL
    , [MinExecutionCount] bigint NULL
    , [MinLogicalReadsPerExecution] bigint NULL
    , [MinTotalLogicalReads] bigint NULL
    , [MinElapsedMs] bigint NULL
    , [MinCpuMs] bigint NULL
    , [MinSpilledPages] bigint NULL
    , [MinMemoryKb] bigint NULL
    , [RequiredEvidenceLevel] varchar(32) NULL
    , [AdditionalConfigurationJson] nvarchar(max) NULL
    , PRIMARY KEY ([RuleCode],[ProfileCode],[Severity])
);

