    CREATE TABLE [#ExecutionPlanAnalysis_PredicateHistogramMappings]
    (
          [PredicateReferenceId] bigint NULL,[StatementOrdinal] int NULL,[NodeId] int NULL
        , [DatabaseName] sysname NULL,[SchemaName] sysname NULL,[ObjectName] sysname NULL,[ColumnName] sysname NULL
        , [StatisticsName] sysname NULL,[PredicateKind] varchar(40) NULL,[ValueSource] varchar(32) NULL
        , [MappingStatus] varchar(48) NULL,[MappingConfidence] varchar(16) NULL,[MatchedStepOrdinal] int NULL
        , [MatchesRangeHighKey] bit NULL,[IsBelowHistogram] bit NULL,[IsAboveHistogram] bit NULL
        , [SensitiveValueStatus] varchar(40) NULL
    );

    IF @OutputMode NOT IN ('CONSOLE','RAW','TABLE','NONE')
       OR @RequestedPlanSource NOT IN ('AUTO','COMPILE','LAST_ACTUAL')
       OR @Depth NOT IN ('SUMMARY','STANDARD','FULL')
       OR @RuleSet<>'DEFAULT'
       OR @MinSeverity NOT IN ('INFO','LOW','MEDIUM','HIGH','CRITICAL')
       OR @MitThreadRuntime NOT IN (0,1) OR @MitSqlText NOT IN (0,1)
       OR @PrivacyMode NOT IN ('DERIVED_ONLY','TOKENIZED','RAW','STRUCTURE_ONLY')
       OR @IdentifierMode NOT IN ('RAW','TOKENIZED','OMIT')
       OR @StatisticsMode NOT IN ('NONE','PLAN_ONLY','USED','RELEVANT','OBJECT_ALL')
       OR @HistogramMode NOT IN ('NONE','SUMMARY','STEPS')
       OR @MetadataMode NOT IN ('EVIDENCE_ONLY','CURRENT_SERVER')
       OR @MitPredicateHistogramMap NOT IN (0,1)
       OR @MaxOperatoren IS NULL OR @MaxOperatoren<1
       OR @MaxFindings IS NULL OR @MaxFindings<1
       OR @MaxStatistiken IS NULL OR @MaxStatistiken NOT BETWEEN 1 AND 1000
       OR @MaxHistogrammSchritte IS NULL OR @MaxHistogrammSchritte NOT BETWEEN 0 AND 200000
       OR @MaxDurationSeconds IS NULL OR @MaxDurationSeconds NOT BETWEEN 1 AND 3600
       OR @LockTimeoutMs IS NULL OR @LockTimeoutMs NOT BETWEEN 0 AND 60000
       OR @HighImpactConfirmed NOT IN (0,1)
       OR @JsonErzeugen NOT IN (0,1)
    BEGIN
        SELECT @StatusCodeOut='INVALID_PARAMETER',@IsPartialOut=1,
               @ErrorMessageOut=N'Ungültiger Modus-, Grenzwert-, Planquellen-, Ausgabe- oder Datenschutzparameter.';
    END;

    IF @StatusCodeOut='AVAILABLE'
       AND NULLIF(LTRIM(RTRIM(COALESCE(@SessionIds,N''))),N'') IS NOT NULL
    BEGIN
        IF EXISTS
           (
               SELECT 1
               FROM [monitor].[TVF_ParseBigintList](@SessionIds)
               WHERE [IsValid]<>1
                  OR [NumberValue] NOT BETWEEN 1 AND 32767
           )
           OR 1<>(SELECT COUNT(*) FROM [monitor].[TVF_ParseBigintList](@SessionIds))
        BEGIN
            SELECT @StatusCodeOut='INVALID_PARAMETER',@IsPartialOut=1,
                   @ErrorMessageOut=N'@SessionIds muss für diese Ein-Plan-Analyse genau eine gültige smallint-Session-ID enthalten.';
        END
        ELSE
        BEGIN
            SELECT @EffectiveSessionId=CONVERT(smallint,[NumberValue])
            FROM [monitor].[TVF_ParseBigintList](@SessionIds);
        END;
    END;

    DECLARE @PlanSourceGroupCount int=
          CASE WHEN @PlanXml IS NOT NULL THEN 1 ELSE 0 END
        + CASE WHEN @PlanHandle IS NOT NULL THEN 1 ELSE 0 END
        + CASE WHEN @EffectiveSessionId IS NOT NULL THEN 1 ELSE 0 END
        + CASE WHEN @QueryStoreDatabaseName IS NOT NULL OR @QueryStorePlanId IS NOT NULL THEN 1 ELSE 0 END;

    IF @StatusCodeOut='AVAILABLE' AND @PlanSourceGroupCount<>1
    BEGIN
        SELECT @StatusCodeOut='INVALID_PARAMETER',@IsPartialOut=1,
               @ErrorMessageOut=N'Genau eine Planquelle muss angegeben werden.';
    END;
    IF @StatusCodeOut='AVAILABLE'
       AND ((@QueryStoreDatabaseName IS NULL AND @QueryStorePlanId IS NOT NULL)
         OR (@QueryStoreDatabaseName IS NOT NULL AND @QueryStorePlanId IS NULL))
    BEGIN
        SELECT @StatusCodeOut='INVALID_PARAMETER',@IsPartialOut=1,
               @ErrorMessageOut=N'Query Store benötigt @QueryStoreDatabaseName und @QueryStorePlanId gemeinsam.';
    END;
    IF @StatusCodeOut='AVAILABLE' AND @PrivacyMode='RAW' AND @SensitiveDataConfirmed<>1
    BEGIN
        SELECT @StatusCodeOut='SENSITIVE_DATA_CONFIRMATION_REQUIRED',@IsPartialOut=1,
               @ErrorMessageOut=N'RAW-Parameter- oder Histogrammwerte benötigen @SensitiveDataConfirmed=1.';
    END;
    IF @StatusCodeOut='AVAILABLE' AND @MitSqlText=1 AND @SensitiveDataConfirmed<>1
    BEGIN
        SELECT @StatusCodeOut='SENSITIVE_DATA_CONFIRMATION_REQUIRED',@IsPartialOut=1,
               @ErrorMessageOut=N'StatementText kann Literale und proprietären SQL-Text enthalten. @MitSqlText=1 benötigt @SensitiveDataConfirmed=1.';
    END;
    IF @StatusCodeOut='AVAILABLE' AND @MetadataMode='CURRENT_SERVER' AND @QuellumgebungBestaetigt<>1
    BEGIN
        SELECT @StatusCodeOut='SOURCE_ENVIRONMENT_CONFIRMATION_REQUIRED',@IsPartialOut=1,
               @ErrorMessageOut=N'CURRENT_SERVER-Anreicherung benötigt @QuellumgebungBestaetigt=1.';
    END;

    IF @StatusCodeOut='AVAILABLE' AND @TableRequested=1
    BEGIN
        EXEC [monitor].[InternalPrepareResultTables]
              @ResultTablesJson=@ResultTablesJson
            , @AllowedResultNames=N'moduleStatus|capabilities|planDocuments|statements|operatorTree|operatorRuntime|operatorThreadRuntime|accessPaths|statisticsUsage|parametersAndVariants|parameters|planWarnings|optimizerContext|runtimeFeedback|queryStoreContext|feedbackAndVariants|memoryAndSpills|executionEvidence|histogramSummaries|histogramSteps|predicateHistogramMappings|findings'
            , @MappingTable=N'#ExecutionPlanAnalysis_TableMap'
            , @ThrowOnError=1;
        SET @OutputMode='NONE';
    END
    ELSE IF @StatusCodeOut='AVAILABLE' AND @ResultTablesJson IS NOT NULL
    BEGIN
        SELECT @StatusCodeOut='INVALID_PARAMETER',@IsPartialOut=1,
               @ErrorMessageOut=N'@ResultTablesJson ist ausschließlich mit @ResultSetArt=TABLE zulässig.';
    END;
    IF @ConsoleResultRequested=1 SET @OutputMode='NONE';

    /*
      Cachekontext wird je Aufruf genau einmal materialisiert. Ein
      USP_ShowplanAnalysis-Parent stellt seinen bereits gelesenen Kandidaten-
      Snapshot über eine lokale Temp-Tabelle bereit; ein direkter Planhandle-
      Aufruf verwendet einen gezielten Einzelread.
    */
    IF @StatusCodeOut='AVAILABLE' AND @PlanHandle IS NOT NULL
    BEGIN
        BEGIN TRY
            EXEC [sys].[sp_executesql]
                  N'INSERT [#ExecutionPlanAnalysis_SourceContext]
                    (
                          [AnalysisObjectId],[PlanHandle],[SourceCapturedAtUtc],[StatusCode]
                        , [DatabaseId],[SetOptions],[CompileUserId],[PlanGenerationNum]
                        , [CacheCreationTime],[CacheLastExecutionTime],[ExecutionCount]
                        , [CacheObjectType],[CacheObjectClass],[CacheUseCounts],[CacheRefCounts]
                        , [CacheSizeBytes],[CachePoolId],[EvidenceLimit]
                    )
                    SELECT
                          1,[PlanHandle],[SourceCapturedAtUtc],[StatusCode]
                        , [DatabaseId],[SetOptions],[CompileUserId],[PlanGenerationNum]
                        , [CacheCreationTime],[CacheLastExecutionTime],[ExecutionCount]
                        , [CacheObjectType],[CacheObjectClass],[CacheUseCounts],[CacheRefCounts]
                        , [CacheSizeBytes],[CachePoolId],[EvidenceLimit]
                    FROM [#ShowplanAnalysis_ExecutionPlanSourceContext]
                    WHERE [PlanHandle]=@RequestedPlanHandle;'
                , N'@RequestedPlanHandle varbinary(64)'
                , @RequestedPlanHandle=@PlanHandle;
        END TRY
        BEGIN CATCH
            IF ERROR_NUMBER()<>208
            BEGIN
                SET @IsPartialOut=1;
                IF @ErrorMessageOut IS NULL
                    SET @ErrorMessageOut=N'Der bereitgestellte Parent-Cachekontext konnte nicht übernommen werden.';
            END;
        END CATCH;

        IF NOT EXISTS
           (
               SELECT 1
               FROM [#ExecutionPlanAnalysis_SourceContext]
               WHERE [PlanHandle]=@PlanHandle
           )
        BEGIN TRY
            INSERT [#ExecutionPlanAnalysis_SourceContext]
            (
                  [AnalysisObjectId],[PlanHandle],[SourceCapturedAtUtc],[StatusCode]
                , [DatabaseId],[SetOptions],[CompileUserId],[PlanGenerationNum]
                , [CacheCreationTime],[CacheLastExecutionTime],[ExecutionCount]
                , [CacheObjectType],[CacheObjectClass],[CacheUseCounts],[CacheRefCounts]
                , [CacheSizeBytes],[CachePoolId],[EvidenceLimit]
            )
            SELECT
                  1,@PlanHandle,@Now
                , CASE WHEN [cp].[plan_handle] IS NULL THEN 'PLAN_CACHE_CONTEXT_UNAVAILABLE' ELSE 'AVAILABLE' END
                , [pa].[DatabaseId],[pa].[SetOptions],[pa].[CompileUserId]
                , [qs].[PlanGenerationNum],[qs].[CacheCreationTime],[qs].[CacheLastExecutionTime],[qs].[ExecutionCount]
                , [cp].[cacheobjtype],[cp].[objtype],[cp].[usecounts],[cp].[refcounts]
                , CONVERT(bigint,[cp].[size_in_bytes]),[cp].[pool_id]
                , N'Cachewerte sind eine flüchtige, nicht transaktional mit dem Plan-XML atomare Momentaufnahme.'
            FROM [sys].[dm_exec_cached_plans] AS [cp] WITH (NOLOCK)
            OUTER APPLY
            (
                SELECT
                      MAX([qs0].[plan_generation_num]) AS [PlanGenerationNum]
                    , MIN([qs0].[creation_time]) AS [CacheCreationTime]
                    , MAX([qs0].[last_execution_time]) AS [CacheLastExecutionTime]
                    , SUM([qs0].[execution_count]) AS [ExecutionCount]
                FROM [sys].[dm_exec_query_stats] AS [qs0] WITH (NOLOCK)
                WHERE [qs0].[plan_handle]=@PlanHandle
            ) AS [qs]
            OUTER APPLY
            (
                SELECT
                      MAX(CASE WHEN [a].[attribute]='dbid' THEN TRY_CONVERT(int,[a].[value]) END) AS [DatabaseId]
                    , MAX(CASE WHEN [a].[attribute]='set_options' THEN TRY_CONVERT(bigint,[a].[value]) END) AS [SetOptions]
                    , MAX(CASE WHEN [a].[attribute]='user_id' THEN TRY_CONVERT(int,[a].[value]) END) AS [CompileUserId]
                FROM [sys].[dm_exec_plan_attributes](@PlanHandle) AS [a]
            ) AS [pa]
            WHERE [cp].[plan_handle]=@PlanHandle;

            IF NOT EXISTS
               (
                   SELECT 1
                   FROM [#ExecutionPlanAnalysis_SourceContext]
                   WHERE [PlanHandle]=@PlanHandle
               )
                INSERT [#ExecutionPlanAnalysis_SourceContext]
                (
                      [AnalysisObjectId],[PlanHandle],[SourceCapturedAtUtc],[StatusCode]
                    , [EvidenceLimit]
                )
                VALUES
                (
                      1,@PlanHandle,@Now,'PLAN_CACHE_CONTEXT_UNAVAILABLE'
                    , N'Der Planhandle war beim gezielten Cachekontext-Read nicht mehr in sys.dm_exec_cached_plans sichtbar.'
                );
        END TRY
        BEGIN CATCH
            INSERT [#ExecutionPlanAnalysis_SourceContext]
            (
                  [AnalysisObjectId],[PlanHandle],[SourceCapturedAtUtc],[StatusCode]
                , [EvidenceLimit]
            )
            VALUES
            (
                  1,@PlanHandle,@Now
                , CASE WHEN ERROR_NUMBER() IN (229,371,262,297,300,916)
                       THEN 'DENIED_PERMISSION' ELSE 'ERROR_HANDLED' END
                , N'Der gezielte Cachekontext-Read ist fehlgeschlagen; die Plan-XML-Analyse bleibt davon getrennt.'
            );
            SET @IsPartialOut=1;
            IF @ErrorNumberOut IS NULL
                SELECT @ErrorNumberOut=ERROR_NUMBER(),@ErrorMessageOut=ERROR_MESSAGE();
        END CATCH;
    END;

    /* Planbeschaffung. Direkt übergebenes XML bleibt vollständig standalone. */
    IF @StatusCodeOut='AVAILABLE'
    BEGIN TRY
        IF @PlanXml IS NOT NULL
        BEGIN
            SET @EffectivePlanXml=@PlanXml;
            SET @EffectivePlanSource='IMPORTED';
            SET @RuntimeScope=CASE WHEN @PlanXml.exist('//*[local-name(.)="RunTimeCountersPerThread"]')=1
                                   THEN 'IMPORTED_ACTUAL' ELSE 'NONE' END;
        END
        ELSE IF @PlanHandle IS NOT NULL
        BEGIN
            IF @RequestedPlanSource IN ('AUTO','LAST_ACTUAL')
            BEGIN
                SELECT @EffectivePlanXml=[query_plan]
                FROM [sys].[dm_exec_query_plan_stats](@PlanHandle);
                IF @EffectivePlanXml IS NOT NULL
                BEGIN
                    SET @EffectivePlanSource='LAST_ACTUAL';
                    SET @RuntimeScope='LAST_COMPLETED_EXECUTION';
                END;
            END;
            IF @EffectivePlanXml IS NULL AND @RequestedPlanSource IN ('AUTO','COMPILE')
            BEGIN
                SELECT @EffectivePlanXml=[query_plan]
                FROM [sys].[dm_exec_query_plan](@PlanHandle);
                IF @EffectivePlanXml IS NOT NULL
                BEGIN
                    SET @EffectivePlanSource='COMPILE';
                    SET @RuntimeScope='NONE';
                END;
            END;
        END
        ELSE IF @EffectiveSessionId IS NOT NULL
        BEGIN
            DECLARE @RequestCount int;
            SELECT @RequestCount=COUNT(*)
            FROM [sys].[dm_exec_query_statistics_xml](@EffectiveSessionId)
            WHERE @RequestId IS NULL OR [request_id]=@RequestId;
            IF @RequestCount>1 AND @RequestId IS NULL
                THROW 51031,N'Die Sitzung besitzt mehrere aktive Requests; @RequestId ist erforderlich.',1;
            SELECT TOP (1)
                  @EffectivePlanXml=[query_plan]
                , @EffectiveRequestId=[request_id]
            FROM [sys].[dm_exec_query_statistics_xml](@EffectiveSessionId)
            WHERE @RequestId IS NULL OR [request_id]=@RequestId
            ORDER BY [request_id];
            IF @EffectivePlanXml IS NOT NULL
            BEGIN
                SET @EffectivePlanSource='CURRENT_ACTUAL';
                SET @RuntimeScope='CURRENT_PARTIAL_EXECUTION';
            END;
        END
        ELSE
        BEGIN
            DECLARE @QueryStoreVersionColumns nvarchar(max)=CASE
                WHEN @ServerMajorVersion>=16 THEN
                    N',[p].[has_compile_replay_script],[p].[is_optimized_plan_forcing_disabled],[p].[plan_type],[p].[plan_type_desc]'
                ELSE
                    N',CONVERT(bit,NULL),CONVERT(bit,NULL),CONVERT(int,NULL),CONVERT(nvarchar(120),NULL)'
                END;
            DECLARE @QueryStoreSql nvarchar(max)=N'USE '+QUOTENAME(@QueryStoreDatabaseName)+N';
INSERT [#ExecutionPlanAnalysis_QueryStorePlanSource]
(
      [AnalysisObjectId],[QueryStoreDatabaseName],[QueryStorePlanId],[QueryStoreQueryId]
    , [PlanGroupId],[EngineVersion],[CompatibilityLevel],[QueryPlanHash],[QueryPlanXml]
    , [IsTrivialPlan],[IsParallelPlan],[IsForcedPlan],[PlanForcingTypeDesc]
    , [ForceFailureCount],[LastForceFailureReason],[LastForceFailureReasonDesc]
    , [CountCompiles],[InitialCompileStartTime],[LastCompileStartTime],[LastExecutionTime]
    , [AvgCompileDurationUs],[LastCompileDurationUs],[ContextSettingsId],[ObjectId]
    , [QueryHash],[QueryParameterizationTypeDesc],[AvgOptimizeDurationUs],[AvgCompileMemoryKb]
    , [HasCompileReplayScript],[IsOptimizedPlanForcingDisabled],[PlanType],[PlanTypeDesc]
)
SELECT
      1,@QueryStoreDatabaseName,[p].[plan_id],[p].[query_id]
    , [p].[plan_group_id],[p].[engine_version],[p].[compatibility_level],[p].[query_plan_hash]
    , TRY_CONVERT(xml,[p].[query_plan])
    , [p].[is_trivial_plan],[p].[is_parallel_plan],[p].[is_forced_plan],[p].[plan_forcing_type_desc]
    , [p].[force_failure_count],[p].[last_force_failure_reason],[p].[last_force_failure_reason_desc]
    , [p].[count_compiles],[p].[initial_compile_start_time],[p].[last_compile_start_time],[p].[last_execution_time]
    , [p].[avg_compile_duration],[p].[last_compile_duration],[q].[context_settings_id],[q].[object_id]
    , [q].[query_hash],[q].[query_parameterization_type_desc],[q].[avg_optimize_duration],[q].[avg_compile_memory_kb]'
    +@QueryStoreVersionColumns+N'
FROM [sys].[query_store_plan] AS [p] WITH (NOLOCK)
JOIN [sys].[query_store_query] AS [q] WITH (NOLOCK)
  ON [q].[query_id]=[p].[query_id]
WHERE [p].[plan_id]=@PlanId;';
            EXEC [sys].[sp_executesql]
                  @QueryStoreSql
                , N'@PlanId bigint,@QueryStoreDatabaseName sysname'
                , @PlanId=@QueryStorePlanId
                , @QueryStoreDatabaseName=@QueryStoreDatabaseName;
            SELECT @EffectivePlanXml=[QueryPlanXml]
            FROM [#ExecutionPlanAnalysis_QueryStorePlanSource]
            WHERE [QueryStorePlanId]=@QueryStorePlanId;
            IF @EffectivePlanXml IS NOT NULL
            BEGIN
                SET @EffectivePlanSource='QUERY_STORE';
                SET @RuntimeScope='NONE';
            END;
        END;

        IF @EffectivePlanXml IS NULL
        BEGIN
            SELECT @StatusCodeOut='UNAVAILABLE_OBJECT',@IsPartialOut=1,
                   @ErrorMessageOut=N'Die angeforderte Planquelle lieferte kein Showplan-XML.';
        END;
    END TRY
    BEGIN CATCH
        SELECT @StatusCodeOut=CASE
                   WHEN ERROR_NUMBER()=569 AND @PlanHandle IS NOT NULL THEN 'UNAVAILABLE_OBJECT'
                   WHEN ERROR_NUMBER() IN (229,371,262,297,300,916) THEN 'DENIED_PERMISSION'
                   ELSE 'ERROR_HANDLED' END,
               @IsPartialOut=1,@ErrorNumberOut=ERROR_NUMBER(),@ErrorMessageOut=ERROR_MESSAGE();
    END CATCH;

    /*
      Eine angeforderte, aber nicht mehr verfügbare Quelle erhält eine eigene
      DIAG-003-Evidenzzeile. Dadurch bleibt PLAN_EVICTED beziehungsweise
      REQUEST_FINISHED von SQL-NULL und einem fehlenden XML-Attribut getrennt.
    */
    IF @EffectivePlanXml IS NULL
       AND @PlanSourceGroupCount=1
       AND @StatusCodeOut IN ('UNAVAILABLE_OBJECT','DENIED_PERMISSION','ERROR_HANDLED')
    BEGIN
        DECLARE @UnavailableValueStatus varchar(40)=CASE
            WHEN @StatusCodeOut='DENIED_PERMISSION' THEN 'DENIED_PERMISSION'
            WHEN @StatusCodeOut='ERROR_HANDLED' THEN 'ERROR_HANDLED'
            WHEN @EffectiveSessionId IS NOT NULL THEN 'REQUEST_FINISHED'
            WHEN @PlanHandle IS NOT NULL THEN 'PLAN_EVICTED'
            ELSE 'NOT_COLLECTED' END;
        DECLARE @AttemptedValueSource varchar(40)=CASE
            WHEN @EffectiveSessionId IS NOT NULL THEN 'LIVE_PLAN'
            WHEN @QueryStorePlanId IS NOT NULL THEN 'QUERY_STORE_PLAN'
            WHEN @PlanHandle IS NOT NULL AND @RequestedPlanSource='COMPILE' THEN 'COMPILE_PLAN'
            WHEN @PlanHandle IS NOT NULL AND @RequestedPlanSource='LAST_ACTUAL' THEN 'LAST_ACTUAL_PLAN'
            WHEN @PlanHandle IS NOT NULL THEN 'PLAN_CACHE_ATTEMPT'
            ELSE 'IMPORTED_PLAN' END;

        INSERT [#ExecutionPlanAnalysis_ParameterEvidence]
        (
              [CandidateId],[SessionId],[RequestId],[StatementOrdinal],[StatementId]
            , [StatementQueryHash],[StatementQueryPlanHash],[PlanHandle]
            , [QueryStoreDatabaseName],[QueryStorePlanId],[PlanDocumentHash]
            , [EvidenceKind],[ParameterName],[ParameterDataType]
            , [CompiledValuePresent],[RuntimeValuePresent]
            , [CompiledValueIsSqlNull],[RuntimeValueIsSqlNull]
            , [CompiledValue],[RuntimeValue],[CompiledValueToken],[RuntimeValueToken]
            , [CompiledValueLength],[RuntimeValueLength]
            , [CompiledValueStatus],[RuntimeValueStatus],[ValueStatus]
            , [ValueHandlingStatus],[ValueSource]
            , [SourceObservedAtUtc],[ValueCapturedAtUtc]
            , [IsCurrentExecution],[IsLastKnownExecution],[IsComplete],[EvidenceLimit]
        )
        VALUES
        (
              1,@EffectiveSessionId,@EffectiveRequestId,NULL,NULL,NULL,NULL,@PlanHandle
            , @QueryStoreDatabaseName,@QueryStorePlanId,NULL
            , 'SOURCE_STATUS',NULL,NULL,0,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL
            , 'NOT_COLLECTED','NOT_COLLECTED',@UnavailableValueStatus
            , CASE @PrivacyMode WHEN 'RAW' THEN 'AVAILABLE_RAW'
                   WHEN 'TOKENIZED' THEN 'TOKENIZED_CAPTURE_LOCAL'
                   WHEN 'STRUCTURE_ONLY' THEN 'OMITTED_STRUCTURE_ONLY'
                   ELSE 'OMITTED_DERIVED_ONLY' END
            , @AttemptedValueSource,@Now,NULL
            , CASE WHEN @EffectiveSessionId IS NOT NULL THEN CONVERT(bit,1) END
            , CASE WHEN @RequestedPlanSource='LAST_ACTUAL' THEN CONVERT(bit,1)
                   WHEN @RequestedPlanSource='COMPILE' OR @EffectiveSessionId IS NOT NULL THEN CONVERT(bit,0) END
            , 0
            , CASE @UnavailableValueStatus
                  WHEN 'PLAN_EVICTED' THEN N'Das angeforderte Planhandle war beim gezielten Abruf nicht mehr auflösbar.'
                  WHEN 'REQUEST_FINISHED' THEN N'Der angeforderte Request lieferte beim gezielten Live-Plan-Abruf keine laufende Ausführung mehr.'
                  WHEN 'DENIED_PERMISSION' THEN N'Die Planquelle war mit dem aktuellen Sicherheitskontext nicht lesbar.'
                  ELSE N'Die angeforderte Planquelle lieferte keine auswertbare Parameterevidenz.' END
        );
    END;

    IF @StatusCodeOut='AVAILABLE'
       AND (@Depth='FULL' OR @StatisticsMode IN ('RELEVANT','OBJECT_ALL') OR @HistogramMode='STEPS')
    BEGIN
        IF @HighImpactConfirmed<>1
        BEGIN
            SELECT @StatusCodeOut='HIGH_IMPACT_CONFIRMATION_REQUIRED',@IsPartialOut=1,
                   @ErrorMessageOut=N'Der angeforderte FULL-/breite Statistik-/Histogrammpfad benötigt @HighImpactConfirmed=1.';
        END;
        ELSE IF EXISTS
        (
            SELECT 1 FROM [sys].[procedures] AS [p] WITH (NOLOCK)
            JOIN [sys].[schemas] AS [s] WITH (NOLOCK) ON [s].[schema_id]=[p].[schema_id]
            WHERE [s].[name]=N'monitor' AND [p].[name]=N'InternalCheckAnalysisPath'
        )
        BEGIN
            DECLARE @GateStatus varchar(40),@GateMessage nvarchar(2048);
            EXEC [sys].[sp_executesql]
                  N'EXEC [monitor].[InternalCheckAnalysisPath]
                          @AnalysisClass=''SHOWPLAN_XML_DEEP'',
                          @HighImpactConfirmed=@Confirmed,
                          @StatusCode=@Status OUTPUT,
                          @ErrorMessage=@Message OUTPUT;'
                , N'@Confirmed bit,@Status varchar(40) OUTPUT,@Message nvarchar(2048) OUTPUT'
                , @Confirmed=@HighImpactConfirmed,@Status=@GateStatus OUTPUT,@Message=@GateMessage OUTPUT;
            IF @GateStatus<>'AVAILABLE'
                SELECT @StatusCodeOut=@GateStatus,@IsPartialOut=1,@ErrorMessageOut=@GateMessage;
        END;
    END;

    /* AUTO-Profil: explizite lokale Zuordnung, sonst BALANCED. */
    IF @StatusCodeOut='AVAILABLE'
    BEGIN
        IF @Profile='AUTO'
        BEGIN
            SELECT TOP (1) @Profile=[a].[ProfileCode]
            FROM [monitor].[PlanAnalysisProfileAssignment] AS [a] WITH (NOLOCK)
            JOIN [monitor].[PlanAnalysisProfile] AS [p] WITH (NOLOCK)
              ON [p].[ProfileCode]=[a].[ProfileCode] AND [p].[IsEnabled]=1
            WHERE [a].[IsEnabled]=1
              AND (@StatementId IS NULL OR [a].[StatementId] IS NULL OR [a].[StatementId]=@StatementId)
              AND (@StatementQueryHash IS NULL OR [a].[QueryHash] IS NULL OR [a].[QueryHash]=@StatementQueryHash)
              AND ([a].[QueryStoreQueryId] IS NULL)
              AND ([a].[DatabaseNamePattern] IS NULL OR @QueryStoreDatabaseName LIKE [a].[DatabaseNamePattern])
            ORDER BY [a].[Priority],[a].[AssignmentId];
            SET @Profile=COALESCE(@Profile,'BALANCED');
        END;
        IF NOT EXISTS(SELECT 1 FROM [monitor].[PlanAnalysisProfile] WHERE [ProfileCode]=@Profile AND [IsEnabled]=1)
            SET @Profile='BALANCED';
    END;

    /* Public contract: Jede externe oder intern erzeugte Evidenz wird vor der
       Analyse erneut normalisiert. Dadurch gelten Datenschutz-, Shape- und
       Versionsregeln auch für direkt übergebenes @EvidenzJson. */
    IF @StatusCodeOut='AVAILABLE'
    BEGIN
        DECLARE @EvidenceStatus varchar(40),@EvidencePartial bit,@EvidenceError int,@EvidenceMessage nvarchar(2048);
        EXEC [monitor].[USP_CreateExecutionEvidenceJson]
              @PlanXml=@EffectivePlanXml
            , @StatisticsIoText=@StatisticsIoText
            , @StatisticsTimeText=@StatisticsTimeText
            , @StatisticsLanguage=@StatisticsLanguage
            , @StatistikEvidenzModus=@StatisticsMode
            , @HistogrammModus=@HistogramMode
            , @MetadatenQuellenmodus=@MetadataMode
            , @QuellumgebungBestaetigt=@QuellumgebungBestaetigt
            , @EvidenzDatenschutzModus=@PrivacyMode
            , @IdentifierDatenschutzModus='RAW'
            , @SensitiveDataConfirmed=@SensitiveDataConfirmed
            , @MitPredicateHistogramMap=@MitPredicateHistogramMap
            , @StatementId=@StatementId
            , @ExistingEvidenceJson=@EvidenceForAnalysis
            , @MaxStatistiken=@MaxStatistiken
            , @MaxHistogrammSchritte=@MaxHistogrammSchritte
            , @LockTimeoutMs=@LockTimeoutMs
            , @HighImpactConfirmed=@HighImpactConfirmed
            , @RawTextHandling='HASH_ONLY'
            , @StrictValidation=1
            , @ResultSetArt='NONE'
            , @JsonErzeugen=1
            , @Json=@EvidenceForAnalysis OUTPUT
            , @PrintMeldungen=0
            , @StatusCodeOut=@EvidenceStatus OUTPUT
            , @IsPartialOut=@EvidencePartial OUTPUT
            , @ErrorNumberOut=@EvidenceError OUTPUT
            , @ErrorMessageOut=@EvidenceMessage OUTPUT;
        IF COALESCE(@EvidencePartial,0)=1 OR @EvidenceStatus='PARTIAL'
            SET @IsPartialOut=1;
        IF @EvidenceStatus NOT IN ('AVAILABLE','PARTIAL')
        BEGIN
            SET @IsPartialOut=1;
            IF @ErrorMessageOut IS NULL SET @ErrorMessageOut=CONCAT(N'Evidenzanreicherung: ',COALESCE(@EvidenceMessage,@EvidenceStatus));
        END;
    END;

    IF @StatusCodeOut='AVAILABLE'
    BEGIN
        DECLARE @AnalyzerStatus varchar(40),@AnalyzerPartial bit,@AnalyzerError int,@AnalyzerMessage nvarchar(2048);
        EXEC [monitor].[InternalAnalyzeExecutionPlan]
              @AnalysisObjectId=1
            , @PlanXml=@EffectivePlanXml
            , @PlanSource=@EffectivePlanSource
            , @RuntimeCounterScope=@RuntimeScope
            , @WorkloadProfile=@Profile
            , @MinSeverity=@MinSeverity
            , @EvidenceJson=@EvidenceForAnalysis
            , @MitThreadRuntime=@MitThreadRuntime
            , @EvidenzDatenschutzModus=@PrivacyMode
            , @IdentifierDatenschutzModus=@IdentifierMode
            , @SourceObservedAtUtc=@Now
            , @ParameterEvidenceSessionId=@EffectiveSessionId
            , @ParameterEvidenceRequestId=@EffectiveRequestId
            , @PlanHandle=@PlanHandle
            , @QueryStoreDatabaseName=@QueryStoreDatabaseName
            , @QueryStorePlanId=@QueryStorePlanId
            , @StatusCodeOut=@AnalyzerStatus OUTPUT
            , @IsPartialOut=@AnalyzerPartial OUTPUT
            , @ErrorNumberOut=@AnalyzerError OUTPUT
            , @ErrorMessageOut=@AnalyzerMessage OUTPUT;
        IF COALESCE(@AnalyzerPartial,0)=1 OR @AnalyzerStatus='PARTIAL'
            SET @IsPartialOut=1;
        IF @AnalyzerStatus<>'AVAILABLE'
        BEGIN
            SET @StatusCodeOut=@AnalyzerStatus;
            SET @IsPartialOut=1;
            SET @ErrorNumberOut=@AnalyzerError;
            SET @ErrorMessageOut=@AnalyzerMessage;
        END;
    END;

    /*
      DIAG-005: Query Store wird nur für die ausdrücklich angeforderte
      Query-Store-Planquelle gelesen. Plan, Query und Runtimeaggregation werden
      gezielt materialisiert; 2022+-Feedback, Hints und Varianten bleiben
      versionsadaptiv hinter Dynamic SQL. Querytexte werden nicht gelesen.
    */
    IF EXISTS(SELECT 1 FROM [#ExecutionPlanAnalysis_QueryStorePlanSource])
    BEGIN
        BEGIN TRY
            DECLARE @QueryStoreContextSql nvarchar(max)=N'USE '+QUOTENAME(@QueryStoreDatabaseName)+N';
INSERT [#ExecutionPlanAnalysis_QueryStoreContext]
(
      [AnalysisObjectId],[QueryStoreDatabaseName],[QueryStorePlanId],[QueryStoreQueryId]
    , [PlanGroupId],[EngineVersion],[CompatibilityLevel],[QueryPlanHash]
    , [IsTrivialPlan],[IsParallelPlan],[IsForcedPlan],[PlanForcingTypeDesc]
    , [ForceFailureCount],[LastForceFailureReason],[LastForceFailureReasonDesc]
    , [CountCompiles],[InitialCompileStartTime],[LastCompileStartTime],[LastExecutionTime]
    , [AvgCompileDurationUs],[LastCompileDurationUs],[ContextSettingsId],[ObjectId]
    , [QueryHash],[QueryParameterizationTypeDesc],[AvgOptimizeDurationUs],[AvgCompileMemoryKb]
    , [HasCompileReplayScript],[IsOptimizedPlanForcingDisabled],[PlanType],[PlanTypeDesc]
    , [RuntimeExecutionCount],[RuntimeLastExecutionTime],[AvgDurationUs],[AvgCpuTimeUs]
    , [AvgLogicalIoReads],[AvgLogicalIoWrites]
    , [QueryHintCount],[QueryHintFailureCount],[PersistedFeedbackCount],[VariantRelationCount]
    , [SourceObservedAtUtc],[IsCurrent],[IsLastKnown],[StatusCode],[EvidenceLimit]
)
SELECT
      [s].[AnalysisObjectId],[s].[QueryStoreDatabaseName],[s].[QueryStorePlanId],[s].[QueryStoreQueryId]
    , [s].[PlanGroupId],[s].[EngineVersion],[s].[CompatibilityLevel],[s].[QueryPlanHash]
    , [s].[IsTrivialPlan],[s].[IsParallelPlan],[s].[IsForcedPlan],[s].[PlanForcingTypeDesc]
    , [s].[ForceFailureCount],[s].[LastForceFailureReason],[s].[LastForceFailureReasonDesc]
    , [s].[CountCompiles],[s].[InitialCompileStartTime],[s].[LastCompileStartTime],[s].[LastExecutionTime]
    , [s].[AvgCompileDurationUs],[s].[LastCompileDurationUs],[s].[ContextSettingsId],[s].[ObjectId]
    , [s].[QueryHash],[s].[QueryParameterizationTypeDesc],[s].[AvgOptimizeDurationUs],[s].[AvgCompileMemoryKb]
    , [s].[HasCompileReplayScript],[s].[IsOptimizedPlanForcingDisabled],[s].[PlanType],[s].[PlanTypeDesc]
    , [r].[RuntimeExecutionCount],[r].[RuntimeLastExecutionTime]
    , [r].[AvgDurationUs],[r].[AvgCpuTimeUs],[r].[AvgLogicalIoReads],[r].[AvgLogicalIoWrites]
    , 0,0,0,0,@ObservedAtUtc,0,1,''AVAILABLE''
    , N''Query-Store-Werte sind persistierte Aggregate über das vorhandene Erfassungsfenster; Intervalle, Bereinigungen und Capture-Modus begrenzen Vergleiche.''
FROM [#ExecutionPlanAnalysis_QueryStorePlanSource] AS [s]
OUTER APPLY
(
    SELECT
          [RuntimeExecutionCount]=SUM(CONVERT(bigint,[rs].[count_executions]))
        , [RuntimeLastExecutionTime]=MAX([rs].[last_execution_time])
        , [AvgDurationUs]=CONVERT(decimal(38,4),
              SUM(CONVERT(decimal(38,8),[rs].[avg_duration])*CONVERT(decimal(38,8),[rs].[count_executions]))
              /NULLIF(SUM(CONVERT(decimal(38,8),[rs].[count_executions])),0))
        , [AvgCpuTimeUs]=CONVERT(decimal(38,4),
              SUM(CONVERT(decimal(38,8),[rs].[avg_cpu_time])*CONVERT(decimal(38,8),[rs].[count_executions]))
              /NULLIF(SUM(CONVERT(decimal(38,8),[rs].[count_executions])),0))
        , [AvgLogicalIoReads]=CONVERT(decimal(38,4),
              SUM(CONVERT(decimal(38,8),[rs].[avg_logical_io_reads])*CONVERT(decimal(38,8),[rs].[count_executions]))
              /NULLIF(SUM(CONVERT(decimal(38,8),[rs].[count_executions])),0))
        , [AvgLogicalIoWrites]=CONVERT(decimal(38,4),
              SUM(CONVERT(decimal(38,8),[rs].[avg_logical_io_writes])*CONVERT(decimal(38,8),[rs].[count_executions]))
              /NULLIF(SUM(CONVERT(decimal(38,8),[rs].[count_executions])),0))
    FROM [sys].[query_store_runtime_stats] AS [rs] WITH (NOLOCK)
    WHERE [rs].[plan_id]=[s].[QueryStorePlanId]
) AS [r];';
            EXEC [sys].[sp_executesql]
                  @QueryStoreContextSql
                , N'@ObservedAtUtc datetime2(3)'
                , @ObservedAtUtc=@Now;

            INSERT [#ExecutionPlanAnalysis_RuntimeFeedback]
            (
                  [AnalysisObjectId],[FeedbackType],[FeedbackState],[MetricName]
                , [ObservedValue],[BaselineValue],[MetricUnit],[RuntimeCounterScope]
                , [EvidenceSource],[SourceObservedAtUtc],[IsCurrent],[IsLastKnown]
                , [IsMeasured],[IsDerived],[StatusCode],[EvidenceLimit]
            )
            SELECT
                  [AnalysisObjectId],'QUERY_STORE_AGGREGATE','PERSISTED_AGGREGATE'
                , 'AVERAGE_DURATION_US',[AvgDurationUs],[AvgCpuTimeUs],'microseconds'
                , 'QUERY_STORE_AGGREGATE','QUERY_STORE_RUNTIME_STATS',[SourceObservedAtUtc]
                , 0,1,1,1,'AVAILABLE'
                , N'Die gewichteten Query-Store-Mittelwerte stammen aus dem sichtbaren Retentionfenster und sind keine einzelne aktuelle Ausführung.'
            FROM [#ExecutionPlanAnalysis_QueryStoreContext]
            WHERE [RuntimeExecutionCount] IS NOT NULL;

            IF @ServerMajorVersion>=16
            BEGIN
                DECLARE @QueryStoreFeedbackSql nvarchar(max)=N'USE '+QUOTENAME(@QueryStoreDatabaseName)+N';
INSERT [#ExecutionPlanAnalysis_FeedbackAndVariants]
(
      [AnalysisObjectId],[RecordType],[FeatureType],[QueryStorePlanId],[QueryStoreQueryId]
    , [FeatureState],[FeatureData],[FeatureDataToken],[FeatureDataLength],[DataHandlingStatus]
    , [EvidenceSource],[SourceObservedAtUtc],[IsCurrent],[IsLastKnown],[IsMeasured],[IsDerived]
    , [StatusCode],[EvidenceLimit]
)
SELECT
      1,''PERSISTED_FEEDBACK'',CONVERT(varchar(60),[f].[feature_desc])
    , [f].[plan_id],[s].[QueryStoreQueryId],CONVERT(nvarchar(128),[f].[state_desc])
    , CASE WHEN @EvidencePrivacyMode=''RAW'' AND @Confirmed=1 THEN [f].[feedback_data] END
    , CASE WHEN @EvidencePrivacyMode=''TOKENIZED'' AND [f].[feedback_data] IS NOT NULL
           THEN HASHBYTES(''SHA2_256'',CONVERT(varbinary(max),[f].[feedback_data])) END
    , DATALENGTH([f].[feedback_data])/2
    , CASE WHEN @EvidencePrivacyMode=''RAW'' AND @Confirmed=1 THEN ''AVAILABLE_RAW''
           WHEN @EvidencePrivacyMode=''TOKENIZED'' THEN ''TOKENIZED''
           WHEN @EvidencePrivacyMode=''STRUCTURE_ONLY'' THEN ''OMITTED_STRUCTURE_ONLY''
           ELSE ''OMITTED_DERIVED_ONLY'' END
    , ''QUERY_STORE_PLAN_FEEDBACK'',@ObservedAtUtc,0,1,1,0,''AVAILABLE''
    , N''Persistiertes Feedback ist versions-, zustands- und bereinigungsabhängig; FeatureData kann sensitive oder proprietäre Inhalte enthalten.''
FROM [sys].[query_store_plan_feedback] AS [f] WITH (NOLOCK)
JOIN [#ExecutionPlanAnalysis_QueryStorePlanSource] AS [s]
  ON [s].[QueryStorePlanId]=[f].[plan_id];

INSERT [#ExecutionPlanAnalysis_FeedbackAndVariants]
(
      [AnalysisObjectId],[RecordType],[FeatureType],[QueryStorePlanId],[QueryStoreQueryId]
    , [ParentQueryId],[DispatcherPlanId],[QueryVariantQueryId]
    , [FeatureState],[DataHandlingStatus],[EvidenceSource],[SourceObservedAtUtc]
    , [IsCurrent],[IsLastKnown],[IsMeasured],[IsDerived],[StatusCode],[EvidenceLimit]
)
SELECT
      1,''QUERY_VARIANT_RELATION'',''PARAMETER_SENSITIVE_PLAN''
    , [s].[QueryStorePlanId],[s].[QueryStoreQueryId]
    , [v].[parent_query_id],[v].[dispatcher_plan_id],[v].[query_variant_query_id]
    , N''PERSISTED_RELATION'',''NO_SENSITIVE_PAYLOAD'',''QUERY_STORE_QUERY_VARIANT'',@ObservedAtUtc
    , 0,1,1,0,''AVAILABLE''
    , N''Die Relation belegt Dispatcher und Queryvariante, nicht deren relative Leistungsqualität.''
FROM [sys].[query_store_query_variant] AS [v] WITH (NOLOCK)
JOIN [#ExecutionPlanAnalysis_QueryStorePlanSource] AS [s]
  ON [s].[QueryStoreQueryId] IN ([v].[query_variant_query_id],[v].[parent_query_id]);

INSERT [#ExecutionPlanAnalysis_FeedbackAndVariants]
(
      [AnalysisObjectId],[RecordType],[FeatureType],[QueryStorePlanId],[QueryStoreQueryId]
    , [FeatureState],[FeatureData],[FeatureDataToken],[FeatureDataLength],[DataHandlingStatus]
    , [EvidenceSource],[SourceObservedAtUtc],[IsCurrent],[IsLastKnown],[IsMeasured],[IsDerived]
    , [StatusCode],[EvidenceLimit]
)
SELECT
      1,''QUERY_STORE_HINT'',''QUERY_STORE_HINT'',[s].[QueryStorePlanId],[h].[query_id]
    , CASE WHEN COALESCE([h].[query_hint_failure_count],0)>0 THEN N''FAILURE_RECORDED'' ELSE N''CONFIGURED'' END
    , CASE WHEN @EvidencePrivacyMode=''RAW'' AND @Confirmed=1 THEN [h].[query_hint_text] END
    , CASE WHEN @EvidencePrivacyMode=''TOKENIZED'' AND [h].[query_hint_text] IS NOT NULL
           THEN HASHBYTES(''SHA2_256'',CONVERT(varbinary(max),[h].[query_hint_text])) END
    , DATALENGTH([h].[query_hint_text])/2
    , CASE WHEN @EvidencePrivacyMode=''RAW'' AND @Confirmed=1 THEN ''AVAILABLE_RAW''
           WHEN @EvidencePrivacyMode=''TOKENIZED'' THEN ''TOKENIZED''
           WHEN @EvidencePrivacyMode=''STRUCTURE_ONLY'' THEN ''OMITTED_STRUCTURE_ONLY''
           ELSE ''OMITTED_DERIVED_ONLY'' END
    , ''QUERY_STORE_QUERY_HINTS'',@ObservedAtUtc,0,1,1,0,''AVAILABLE''
    , N''Hinttext kann sensitive oder proprietäre Inhalte enthalten; die Zeile bewertet weder Korrektheit noch Nutzen des Hints.''
FROM [sys].[query_store_query_hints] AS [h] WITH (NOLOCK)
JOIN [#ExecutionPlanAnalysis_QueryStorePlanSource] AS [s]
  ON [s].[QueryStoreQueryId]=[h].[query_id];

UPDATE [q]
SET [QueryHintFailureCount]=COALESCE([h].[QueryHintFailureCount],0)
FROM [#ExecutionPlanAnalysis_QueryStoreContext] AS [q]
OUTER APPLY
(
    SELECT
          [QueryHintFailureCount]=SUM(CONVERT(bigint,[h0].[query_hint_failure_count]))
    FROM [sys].[query_store_query_hints] AS [h0] WITH (NOLOCK)
    JOIN [#ExecutionPlanAnalysis_QueryStorePlanSource] AS [s0]
      ON [s0].[QueryStoreQueryId]=[h0].[query_id]
    WHERE [s0].[AnalysisObjectId]=[q].[AnalysisObjectId]
) AS [h];';
                EXEC [sys].[sp_executesql]
                      @QueryStoreFeedbackSql
                    , N'@ObservedAtUtc datetime2(3),@EvidencePrivacyMode varchar(24),@Confirmed bit'
                    , @ObservedAtUtc=@Now,@EvidencePrivacyMode=@PrivacyMode,@Confirmed=@SensitiveDataConfirmed;

                IF NOT EXISTS
                   (
                       SELECT 1
                       FROM [#ExecutionPlanAnalysis_FeedbackAndVariants]
                       WHERE [EvidenceSource] IN
                             ('QUERY_STORE_PLAN_FEEDBACK','QUERY_STORE_QUERY_HINTS','QUERY_STORE_QUERY_VARIANT')
                   )
                    INSERT [#ExecutionPlanAnalysis_FeedbackAndVariants]
                    (
                          [AnalysisObjectId],[RecordType],[FeatureType],[FeatureState]
                        , [DataHandlingStatus],[EvidenceSource],[SourceObservedAtUtc]
                        , [IsCurrent],[IsLastKnown],[IsMeasured],[IsDerived]
                        , [StatusCode],[EvidenceLimit]
                    )
                    VALUES
                    (
                          1,'SOURCE_STATUS','QUERY_STORE_OPTIONAL_CONTEXT',N'NO_PERSISTED_ROWS'
                        , 'NO_SENSITIVE_PAYLOAD','QUERY_STORE_OPTIONAL_SOURCES',@Now
                        , 0,1,1,0,'AVAILABLE'
                        , N'Die unterstützten Query-Store-Feedback-, Hint- und Variantenquellen wurden gezielt gelesen und enthielten für den Plan keine Zeile.'
                    );
            END;
            ELSE
                INSERT [#ExecutionPlanAnalysis_FeedbackAndVariants]
                (
                      [AnalysisObjectId],[RecordType],[FeatureType],[FeatureState]
                    , [DataHandlingStatus],[EvidenceSource],[SourceObservedAtUtc]
                    , [IsCurrent],[IsLastKnown],[IsMeasured],[IsDerived]
                    , [StatusCode],[EvidenceLimit]
                )
                VALUES
                (
                      1,'SOURCE_STATUS','QUERY_STORE_OPTIONAL_CONTEXT',N'REQUIRES_SQL_SERVER_2022'
                    , 'NO_SENSITIVE_PAYLOAD','QUERY_STORE_OPTIONAL_SOURCES',@Now
                    , 0,1,0,0,'NOT_APPLICABLE'
                    , N'Persistiertes Planfeedback, Query-Store-Hints und Queryvarianten werden erst auf SQL Server 2022 oder neuer gelesen.'
                );

            UPDATE [q]
            SET
                  [QueryHintCount]=[a].[QueryHintCount]
                , [PersistedFeedbackCount]=[a].[PersistedFeedbackCount]
                , [VariantRelationCount]=[a].[VariantRelationCount]
            FROM [#ExecutionPlanAnalysis_QueryStoreContext] AS [q]
            CROSS APPLY
            (
                SELECT
                      [QueryHintCount]=COUNT(CASE WHEN [RecordType]='QUERY_STORE_HINT' THEN 1 END)
                    , [PersistedFeedbackCount]=COUNT(CASE WHEN [RecordType]='PERSISTED_FEEDBACK' THEN 1 END)
                    , [VariantRelationCount]=COUNT(CASE WHEN [RecordType]='QUERY_VARIANT_RELATION' THEN 1 END)
                FROM [#ExecutionPlanAnalysis_FeedbackAndVariants]
                WHERE [AnalysisObjectId]=[q].[AnalysisObjectId]
            ) AS [a];
        END TRY
        BEGIN CATCH
            SET @IsPartialOut=1;
            UPDATE [#ExecutionPlanAnalysis_QueryStoreContext]
            SET
                  [StatusCode]=CASE WHEN ERROR_NUMBER() IN (229,371,262,297,300,916)
                                    THEN 'DENIED_PERMISSION' ELSE 'PARTIAL' END
                , [EvidenceLimit]=N'Der Plan blieb analysierbar; zusätzliche Query-Store-Kontextquellen waren nicht vollständig verfügbar.'
            WHERE [AnalysisObjectId]=1;

            INSERT [#ExecutionPlanAnalysis_FeedbackAndVariants]
            (
                  [AnalysisObjectId],[RecordType],[FeatureType],[FeatureState]
                , [DataHandlingStatus],[EvidenceSource],[SourceObservedAtUtc]
                , [IsCurrent],[IsLastKnown],[IsMeasured],[IsDerived]
                , [StatusCode],[EvidenceLimit]
            )
            VALUES
            (
                  1,'SOURCE_STATUS','QUERY_STORE_OPTIONAL_CONTEXT',N'READ_FAILED'
                , 'NO_SENSITIVE_PAYLOAD','QUERY_STORE_OPTIONAL_SOURCES',@Now
                , 0,1,0,0
                , CASE WHEN ERROR_NUMBER() IN (229,371,262,297,300,916)
                       THEN 'DENIED_PERMISSION' ELSE 'PARTIAL' END
                , N'Der Plan blieb analysierbar; mindestens eine zusätzliche Query-Store-Kontextquelle war nicht vollständig verfügbar.'
            );

            INSERT [#ExecutionPlanAnalysis_QueryStoreContext]
            (
                  [AnalysisObjectId],[QueryStoreDatabaseName],[QueryStorePlanId]
                , [QueryHintCount],[QueryHintFailureCount],[PersistedFeedbackCount],[VariantRelationCount]
                , [SourceObservedAtUtc],[IsCurrent],[IsLastKnown],[StatusCode],[EvidenceLimit]
            )
            SELECT
                  1,@QueryStoreDatabaseName,@QueryStorePlanId,0,0,0,0,@Now,0,1
                , CASE WHEN ERROR_NUMBER() IN (229,371,262,297,300,916) THEN 'DENIED_PERMISSION' ELSE 'PARTIAL' END
                , N'Der Plan blieb analysierbar; zusätzliche Query-Store-Kontextquellen waren nicht vollständig verfügbar.'
            WHERE NOT EXISTS(SELECT 1 FROM [#ExecutionPlanAnalysis_QueryStoreContext]);
            IF @ErrorNumberOut IS NULL
                SELECT @ErrorNumberOut=ERROR_NUMBER(),@ErrorMessageOut=ERROR_MESSAGE();
        END CATCH;
    END
    ELSE
        INSERT [#ExecutionPlanAnalysis_QueryStoreContext]
        (
              [AnalysisObjectId],[QueryStoreDatabaseName],[QueryStorePlanId]
            , [QueryHintCount],[QueryHintFailureCount],[PersistedFeedbackCount],[VariantRelationCount]
            , [SourceObservedAtUtc],[IsCurrent],[IsLastKnown],[StatusCode],[EvidenceLimit]
        )
        VALUES
        (
              1,@QueryStoreDatabaseName,@QueryStorePlanId,0,0,0,0,@Now,0
            , CASE WHEN @QueryStorePlanId IS NOT NULL THEN 1 ELSE 0 END
            , CASE WHEN @QueryStorePlanId IS NULL THEN 'NOT_APPLICABLE'
                   WHEN @StatusCodeOut='DENIED_PERMISSION' THEN 'DENIED_PERMISSION'
                   ELSE 'NOT_COLLECTED' END
            , CASE WHEN @QueryStorePlanId IS NULL
                   THEN N'Für diese Planquelle wurde kein Query-Store-Plan angefordert.'
                   ELSE N'Die angeforderte Query-Store-Quelle lieferte keinen materialisierbaren Kontext.' END
        );

    /* Jede kanonische DIAG-005-Ausgabe besitzt auch bei Quellfehlern eine
       eindeutige Statuszeile. */
    IF NOT EXISTS(SELECT 1 FROM [#ExecutionPlanAnalysis_PlanWarnings])
        INSERT [#ExecutionPlanAnalysis_PlanWarnings]
        (
              [AnalysisObjectId],[WarningCode],[WarningCategory],[Severity],[EvidenceKind]
            , [EvidenceSource],[PlanSource],[SourceObservedAtUtc],[IsMeasured],[IsInferred]
            , [Detail],[FalsePositiveGuard],[StatusCode]
        )
        VALUES
        (
              1,'SOURCE_UNAVAILABLE','SOURCE_STATUS','INFO','SOURCE_STATUS'
            , 'PLAN_SOURCE',@EffectivePlanSource,@Now,0,0
            , N'Die Planquelle lieferte keine normalisierbare Warnungsevidenz.'
            , N'Ein Quellfehler darf nicht als warnungsfreier Plan interpretiert werden.'
            , CASE WHEN @StatusCodeOut='DENIED_PERMISSION' THEN 'DENIED_PERMISSION' ELSE 'NOT_COLLECTED' END
        );
    IF NOT EXISTS(SELECT 1 FROM [#ExecutionPlanAnalysis_OptimizerContext])
        INSERT [#ExecutionPlanAnalysis_OptimizerContext]
        (
              [AnalysisObjectId],[PlanSource],[RuntimeCounterScope],[SourceObservedAtUtc]
            , [EvidenceMeasurement],[StatusCode],[FalsePositiveGuard]
        )
        VALUES
        (
              1,@EffectivePlanSource,@RuntimeScope,@Now,'NOT_MEASURED'
            , CASE WHEN @StatusCodeOut='DENIED_PERMISSION' THEN 'DENIED_PERMISSION' ELSE 'NOT_COLLECTED' END
            , N'Fehlender Optimizerkontext darf nicht als optimale oder triviale Kompilierung interpretiert werden.'
        );
    IF NOT EXISTS(SELECT 1 FROM [#ExecutionPlanAnalysis_RuntimeFeedback])
        INSERT [#ExecutionPlanAnalysis_RuntimeFeedback]
        (
              [AnalysisObjectId],[FeedbackType],[RuntimeCounterScope],[EvidenceSource]
            , [SourceObservedAtUtc],[IsMeasured],[IsDerived],[StatusCode],[EvidenceLimit]
        )
        VALUES
        (
              1,'SOURCE_STATUS',@RuntimeScope,'PLAN_SOURCE',@Now,0,0
            , CASE WHEN @StatusCodeOut='DENIED_PERMISSION' THEN 'DENIED_PERMISSION' ELSE 'NOT_COLLECTED' END
            , N'Ohne Runtimeevidenz werden keine Laufzeitaussagen abgeleitet.'
        );
    IF NOT EXISTS(SELECT 1 FROM [#ExecutionPlanAnalysis_FeedbackAndVariants])
        INSERT [#ExecutionPlanAnalysis_FeedbackAndVariants]
        (
              [AnalysisObjectId],[RecordType],[FeatureType],[FeatureState]
            , [DataHandlingStatus],[EvidenceSource],[SourceObservedAtUtc]
            , [IsMeasured],[IsDerived],[StatusCode],[EvidenceLimit]
        )
        VALUES
        (
              1,'SOURCE_STATUS','SOURCE_UNAVAILABLE',N'NOT_COLLECTED'
            , 'NO_SENSITIVE_PAYLOAD','PLAN_SOURCE',@Now,0,0
            , CASE WHEN @StatusCodeOut='DENIED_PERMISSION' THEN 'DENIED_PERMISSION' ELSE 'NOT_COLLECTED' END
            , N'Ohne Plan- oder Katalogevidenz werden keine Feedback- oder Variantenmerkmale behauptet.'
        );

    /* Current-Statistics- und Histogrammteile aus normalisierter Evidenz ergänzen. */
    IF @EvidenceForAnalysis IS NOT NULL AND ISJSON(@EvidenceForAnalysis)=1
    BEGIN
        ;WITH [CurrentStats] AS
        (
            SELECT *
            FROM OPENJSON(@EvidenceForAnalysis,N'$.statistics.currentSnapshot')
            WITH
            (
                  [DatabaseName] sysname N'$.databaseName'
                , [SchemaName] sysname N'$.schemaName'
                , [ObjectName] sysname N'$.objectName'
                , [StatisticsName] sysname N'$.statisticsName'
                , [LastUpdated] datetime2(7) N'$.lastUpdated'
                , [Rows] bigint N'$.rows'
                , [RowsSampled] bigint N'$.rowsSampled'
                , [ModificationCounter] bigint N'$.modificationCounter'
                , [SamplePercent] decimal(19,6) N'$.samplePercent'
            )
        )
        UPDATE [u]
        SET
              [u].[CurrentLastUpdated]=[c].[LastUpdated]
            , [u].[CurrentRows]=[c].[Rows]
            , [u].[CurrentRowsSampled]=[c].[RowsSampled]
            , [u].[CurrentModificationCounter]=[c].[ModificationCounter]
            , [u].[CurrentSamplePercent]=[c].[SamplePercent]
            , [u].[StatisticsChangedSinceCompile]=CONVERT(bit,CASE
                  WHEN [u].[LastUpdateAtCompile] IS NULL OR [c].[LastUpdated] IS NULL THEN 0
                  WHEN [u].[LastUpdateAtCompile]<>[c].[LastUpdated] THEN 1 ELSE 0 END)
            , [u].[MetadataMatchStatus]='AVAILABLE'
        FROM [#ExecutionPlanAnalysis_StatisticsUsage] AS [u]
        JOIN [CurrentStats] AS [c]
          ON [c].[DatabaseName]=[u].[DatabaseName]
         AND [c].[SchemaName]=[u].[SchemaName]
         AND [c].[ObjectName]=[u].[ObjectName]
         AND [c].[StatisticsName]=[u].[StatisticsName];

        INSERT [#ExecutionPlanAnalysis_HistogramSummaries]
        SELECT *
        FROM OPENJSON(@EvidenceForAnalysis,N'$.statistics.histogramSummaries')
        WITH
        (
              [DatabaseName] sysname N'$.databaseName',[SchemaName] sysname N'$.schemaName'
            , [ObjectName] sysname N'$.objectName',[StatisticsName] sysname N'$.statisticsName'
            , [StatisticsId] int N'$.statisticsId',[LeadingColumnName] sysname N'$.leadingColumnName'
            , [HistogramSteps] int N'$.histogramSteps',[HistogramEstimatedRows] float N'$.histogramEstimatedRows'
            , [MaxEqualRows] float N'$.maxEqualRows',[MaxRangeRows] float N'$.maxRangeRows'
            , [MaxStepRows] float N'$.maxStepRows',[DominantStepPercent] decimal(19,6) N'$.dominantStepPercent'
            , [TailStepRows] float N'$.tailStepRows',[TailStepPercent] decimal(19,6) N'$.tailStepPercent'
            , [CollectionStatus] varchar(40) N'$.collectionStatus'
        );
        INSERT [#ExecutionPlanAnalysis_HistogramSteps]
        SELECT *
        FROM OPENJSON(@EvidenceForAnalysis,N'$.statistics.histogramSteps')
        WITH
        (
              [DatabaseName] sysname N'$.databaseName',[SchemaName] sysname N'$.schemaName'
            , [ObjectName] sysname N'$.objectName',[StatisticsName] sysname N'$.statisticsName'
            , [StatisticsId] int N'$.statisticsId',[LeadingColumnName] sysname N'$.leadingColumnName'
            , [StepOrdinal] int N'$.stepOrdinal',[RangeHighKey] nvarchar(4000) N'$.rangeHighKey'
            , [RangeHighKeyToken] varbinary(32) N'$.rangeHighKeyToken'
            , [RangeRows] float N'$.rangeRows',[EqualRows] float N'$.equalRows'
            , [DistinctRangeRows] bigint N'$.distinctRangeRows',[AverageRangeRows] float N'$.averageRangeRows'
            , [IsPredicateTarget] bit N'$.isPredicateTarget',[PredicateMatchCount] int N'$.predicateMatchCount'
            , [SensitiveValueStatus] varchar(40) N'$.sensitiveValueStatus'
        );
        INSERT [#ExecutionPlanAnalysis_PredicateHistogramMappings]
        SELECT *
        FROM OPENJSON(@EvidenceForAnalysis,N'$.predicateHistogramMappings')
        WITH
        (
              [PredicateReferenceId] bigint N'$.predicateReferenceId',[StatementOrdinal] int N'$.statementOrdinal'
            , [NodeId] int N'$.nodeId',[DatabaseName] sysname N'$.databaseName',[SchemaName] sysname N'$.schemaName'
            , [ObjectName] sysname N'$.objectName',[ColumnName] sysname N'$.columnName'
            , [StatisticsName] sysname N'$.statisticsName',[PredicateKind] varchar(40) N'$.predicateKind'
            , [ValueSource] varchar(32) N'$.valueSource',[MappingStatus] varchar(48) N'$.mappingStatus'
            , [MappingConfidence] varchar(16) N'$.mappingConfidence',[MatchedStepOrdinal] int N'$.matchedStepOrdinal'
            , [MatchesRangeHighKey] bit N'$.matchesRangeHighKey',[IsBelowHistogram] bit N'$.isBelowHistogram'
            , [IsAboveHistogram] bit N'$.isAboveHistogram',[SensitiveValueStatus] varchar(40) N'$.sensitiveValueStatus'
        );
    END;

    IF @StatementId IS NOT NULL
    BEGIN
        DELETE FROM [#ExecutionPlanAnalysis_PlanWarnings]
        WHERE [StatementOrdinal] IS NOT NULL AND ([StatementId]<>@StatementId OR [StatementId] IS NULL);
        DELETE FROM [#ExecutionPlanAnalysis_OptimizerContext]
        WHERE [StatementOrdinal] IS NOT NULL AND ([StatementId]<>@StatementId OR [StatementId] IS NULL);
        DELETE FROM [#ExecutionPlanAnalysis_RuntimeFeedback]
        WHERE [StatementOrdinal] IS NOT NULL AND ([StatementId]<>@StatementId OR [StatementId] IS NULL);
        DELETE FROM [#ExecutionPlanAnalysis_FeedbackAndVariants]
        WHERE [StatementOrdinal] IS NOT NULL AND ([StatementId]<>@StatementId OR [StatementId] IS NULL);
        DELETE FROM [#ExecutionPlanAnalysis_Findings] WHERE [StatementId]<>@StatementId OR [StatementId] IS NULL;
        DELETE FROM [#ExecutionPlanAnalysis_ExecutionEvidence] WHERE [StatementOrdinal] IS NOT NULL AND [StatementOrdinal] NOT IN
            (SELECT [StatementOrdinal] FROM [#ExecutionPlanAnalysis_Statements] WHERE [StatementId]=@StatementId);
        DELETE FROM [#ExecutionPlanAnalysis_MemoryAndSpills] WHERE [StatementId]<>@StatementId OR [StatementId] IS NULL;
        DELETE FROM [#ExecutionPlanAnalysis_Parameters] WHERE [StatementId]<>@StatementId OR [StatementId] IS NULL;
        DELETE FROM [#ExecutionPlanAnalysis_ParameterEvidence]
        WHERE [EvidenceKind]='PARAMETER'
          AND ([StatementId]<>@StatementId OR [StatementId] IS NULL);
        DELETE FROM [#ExecutionPlanAnalysis_StatisticsUsage] WHERE [StatementId]<>@StatementId OR [StatementId] IS NULL;
        DELETE FROM [#ExecutionPlanAnalysis_AccessPaths] WHERE [StatementId]<>@StatementId OR [StatementId] IS NULL;
        DELETE FROM [#ExecutionPlanAnalysis_OperatorThreadRuntime] WHERE [StatementId]<>@StatementId OR [StatementId] IS NULL;
        DELETE FROM [#ExecutionPlanAnalysis_OperatorRuntime] WHERE [StatementId]<>@StatementId OR [StatementId] IS NULL;
        DELETE FROM [#ExecutionPlanAnalysis_Operators] WHERE [StatementId]<>@StatementId OR [StatementId] IS NULL;
        DELETE FROM [#ExecutionPlanAnalysis_Statements] WHERE [StatementId]<>@StatementId OR [StatementId] IS NULL;
    END;

    IF @StatementQueryHash IS NOT NULL
    BEGIN
        DECLARE @QueryHashText nvarchar(130)=CONVERT(nvarchar(130),@StatementQueryHash,1);
        DELETE FROM [#ExecutionPlanAnalysis_PlanWarnings] WHERE [StatementOrdinal] IS NOT NULL AND [StatementOrdinal] NOT IN
            (SELECT [StatementOrdinal] FROM [#ExecutionPlanAnalysis_Statements] WHERE [StatementQueryHash]=@QueryHashText);
        DELETE FROM [#ExecutionPlanAnalysis_OptimizerContext] WHERE [StatementOrdinal] IS NOT NULL AND [StatementOrdinal] NOT IN
            (SELECT [StatementOrdinal] FROM [#ExecutionPlanAnalysis_Statements] WHERE [StatementQueryHash]=@QueryHashText);
        DELETE FROM [#ExecutionPlanAnalysis_RuntimeFeedback] WHERE [StatementOrdinal] IS NOT NULL AND [StatementOrdinal] NOT IN
            (SELECT [StatementOrdinal] FROM [#ExecutionPlanAnalysis_Statements] WHERE [StatementQueryHash]=@QueryHashText);
        DELETE FROM [#ExecutionPlanAnalysis_FeedbackAndVariants] WHERE [StatementOrdinal] IS NOT NULL AND [StatementOrdinal] NOT IN
            (SELECT [StatementOrdinal] FROM [#ExecutionPlanAnalysis_Statements] WHERE [StatementQueryHash]=@QueryHashText);
        DELETE FROM [#ExecutionPlanAnalysis_Findings] WHERE [StatementOrdinal] NOT IN
            (SELECT [StatementOrdinal] FROM [#ExecutionPlanAnalysis_Statements] WHERE [StatementQueryHash]=@QueryHashText);
        DELETE FROM [#ExecutionPlanAnalysis_MemoryAndSpills] WHERE [StatementOrdinal] NOT IN
            (SELECT [StatementOrdinal] FROM [#ExecutionPlanAnalysis_Statements] WHERE [StatementQueryHash]=@QueryHashText);
        DELETE FROM [#ExecutionPlanAnalysis_Parameters] WHERE [StatementOrdinal] NOT IN
            (SELECT [StatementOrdinal] FROM [#ExecutionPlanAnalysis_Statements] WHERE [StatementQueryHash]=@QueryHashText);
        DELETE FROM [#ExecutionPlanAnalysis_ParameterEvidence]
        WHERE [EvidenceKind]='PARAMETER'
          AND [StatementOrdinal] NOT IN
            (SELECT [StatementOrdinal] FROM [#ExecutionPlanAnalysis_Statements] WHERE [StatementQueryHash]=@QueryHashText);
        DELETE FROM [#ExecutionPlanAnalysis_StatisticsUsage] WHERE [StatementOrdinal] NOT IN
            (SELECT [StatementOrdinal] FROM [#ExecutionPlanAnalysis_Statements] WHERE [StatementQueryHash]=@QueryHashText);
        DELETE FROM [#ExecutionPlanAnalysis_AccessPaths] WHERE [StatementOrdinal] NOT IN
            (SELECT [StatementOrdinal] FROM [#ExecutionPlanAnalysis_Statements] WHERE [StatementQueryHash]=@QueryHashText);
        DELETE FROM [#ExecutionPlanAnalysis_OperatorThreadRuntime] WHERE [StatementOrdinal] NOT IN
            (SELECT [StatementOrdinal] FROM [#ExecutionPlanAnalysis_Statements] WHERE [StatementQueryHash]=@QueryHashText);
        DELETE FROM [#ExecutionPlanAnalysis_OperatorRuntime] WHERE [StatementOrdinal] NOT IN
            (SELECT [StatementOrdinal] FROM [#ExecutionPlanAnalysis_Statements] WHERE [StatementQueryHash]=@QueryHashText);
        DELETE FROM [#ExecutionPlanAnalysis_Operators] WHERE [StatementOrdinal] NOT IN
            (SELECT [StatementOrdinal] FROM [#ExecutionPlanAnalysis_Statements] WHERE [StatementQueryHash]=@QueryHashText);
        DELETE FROM [#ExecutionPlanAnalysis_Statements] WHERE [StatementQueryHash]<>@QueryHashText OR [StatementQueryHash] IS NULL;
    END;

    IF @StatementQueryPlanHash IS NOT NULL
    BEGIN
        DECLARE @QueryPlanHashText nvarchar(130)=CONVERT(nvarchar(130),@StatementQueryPlanHash,1);
        DELETE FROM [#ExecutionPlanAnalysis_PlanWarnings] WHERE [StatementOrdinal] IS NOT NULL AND [StatementOrdinal] NOT IN
            (SELECT [StatementOrdinal] FROM [#ExecutionPlanAnalysis_Statements] WHERE [StatementQueryPlanHash]=@QueryPlanHashText);
        DELETE FROM [#ExecutionPlanAnalysis_OptimizerContext] WHERE [StatementOrdinal] IS NOT NULL AND [StatementOrdinal] NOT IN
            (SELECT [StatementOrdinal] FROM [#ExecutionPlanAnalysis_Statements] WHERE [StatementQueryPlanHash]=@QueryPlanHashText);
        DELETE FROM [#ExecutionPlanAnalysis_RuntimeFeedback] WHERE [StatementOrdinal] IS NOT NULL AND [StatementOrdinal] NOT IN
            (SELECT [StatementOrdinal] FROM [#ExecutionPlanAnalysis_Statements] WHERE [StatementQueryPlanHash]=@QueryPlanHashText);
        DELETE FROM [#ExecutionPlanAnalysis_FeedbackAndVariants] WHERE [StatementOrdinal] IS NOT NULL AND [StatementOrdinal] NOT IN
            (SELECT [StatementOrdinal] FROM [#ExecutionPlanAnalysis_Statements] WHERE [StatementQueryPlanHash]=@QueryPlanHashText);
        DELETE FROM [#ExecutionPlanAnalysis_Findings] WHERE [StatementOrdinal] NOT IN
            (SELECT [StatementOrdinal] FROM [#ExecutionPlanAnalysis_Statements] WHERE [StatementQueryPlanHash]=@QueryPlanHashText);
        DELETE FROM [#ExecutionPlanAnalysis_MemoryAndSpills] WHERE [StatementOrdinal] NOT IN
            (SELECT [StatementOrdinal] FROM [#ExecutionPlanAnalysis_Statements] WHERE [StatementQueryPlanHash]=@QueryPlanHashText);
        DELETE FROM [#ExecutionPlanAnalysis_Parameters] WHERE [StatementOrdinal] NOT IN
            (SELECT [StatementOrdinal] FROM [#ExecutionPlanAnalysis_Statements] WHERE [StatementQueryPlanHash]=@QueryPlanHashText);
        DELETE FROM [#ExecutionPlanAnalysis_ParameterEvidence]
        WHERE [EvidenceKind]='PARAMETER'
          AND [StatementOrdinal] NOT IN
            (SELECT [StatementOrdinal] FROM [#ExecutionPlanAnalysis_Statements] WHERE [StatementQueryPlanHash]=@QueryPlanHashText);
        DELETE FROM [#ExecutionPlanAnalysis_StatisticsUsage] WHERE [StatementOrdinal] NOT IN
            (SELECT [StatementOrdinal] FROM [#ExecutionPlanAnalysis_Statements] WHERE [StatementQueryPlanHash]=@QueryPlanHashText);
        DELETE FROM [#ExecutionPlanAnalysis_AccessPaths] WHERE [StatementOrdinal] NOT IN
            (SELECT [StatementOrdinal] FROM [#ExecutionPlanAnalysis_Statements] WHERE [StatementQueryPlanHash]=@QueryPlanHashText);
        DELETE FROM [#ExecutionPlanAnalysis_OperatorThreadRuntime] WHERE [StatementOrdinal] NOT IN
            (SELECT [StatementOrdinal] FROM [#ExecutionPlanAnalysis_Statements] WHERE [StatementQueryPlanHash]=@QueryPlanHashText);
        DELETE FROM [#ExecutionPlanAnalysis_OperatorRuntime] WHERE [StatementOrdinal] NOT IN
            (SELECT [StatementOrdinal] FROM [#ExecutionPlanAnalysis_Statements] WHERE [StatementQueryPlanHash]=@QueryPlanHashText);
        DELETE FROM [#ExecutionPlanAnalysis_Operators] WHERE [StatementOrdinal] NOT IN
            (SELECT [StatementOrdinal] FROM [#ExecutionPlanAnalysis_Statements] WHERE [StatementQueryPlanHash]=@QueryPlanHashText);
        DELETE FROM [#ExecutionPlanAnalysis_Statements] WHERE [StatementQueryPlanHash]<>@QueryPlanHashText OR [StatementQueryPlanHash] IS NULL;
    END;

    IF @MitSqlText=0 UPDATE [#ExecutionPlanAnalysis_Statements] SET [StatementText]=NULL;

    /* Sensitive Histogrammwerte nochmals am öffentlichen Ausgaberand sichern.
       Der Evidence-Generator hat sie bereits normalisiert; diese Projektion ist
       bewusst Defense in Depth für spätere interne Integrationspfade. */
    IF @PrivacyMode<>'RAW'
        UPDATE [#ExecutionPlanAnalysis_HistogramSteps] SET [RangeHighKey]=NULL;
    IF @PrivacyMode<>'TOKENIZED'
        UPDATE [#ExecutionPlanAnalysis_HistogramSteps] SET [RangeHighKeyToken]=NULL;

    /* Histogramm- und Predicate-Identifier passieren unabhängig vom Modus
       immer diese Ausgaberandprojektion. Die fachliche Korrelation ist zu
       diesem Zeitpunkt abgeschlossen. */
    UPDATE [#ExecutionPlanAnalysis_HistogramSummaries]
    SET [DatabaseName]=CASE @IdentifierMode WHEN 'RAW' THEN [DatabaseName] WHEN 'TOKENIZED' THEN CONVERT(sysname,CONVERT(nvarchar(130),HASHBYTES('SHA2_256',@TokenSalt+CONVERT(varbinary(max),[DatabaseName])),1)) END,
        [SchemaName]=CASE @IdentifierMode WHEN 'RAW' THEN [SchemaName] WHEN 'TOKENIZED' THEN CONVERT(sysname,CONVERT(nvarchar(130),HASHBYTES('SHA2_256',@TokenSalt+CONVERT(varbinary(max),[SchemaName])),1)) END,
        [ObjectName]=CASE @IdentifierMode WHEN 'RAW' THEN [ObjectName] WHEN 'TOKENIZED' THEN CONVERT(sysname,CONVERT(nvarchar(130),HASHBYTES('SHA2_256',@TokenSalt+CONVERT(varbinary(max),[ObjectName])),1)) END,
        [StatisticsName]=CASE @IdentifierMode WHEN 'RAW' THEN [StatisticsName] WHEN 'TOKENIZED' THEN CONVERT(sysname,CONVERT(nvarchar(130),HASHBYTES('SHA2_256',@TokenSalt+CONVERT(varbinary(max),[StatisticsName])),1)) END,
        [LeadingColumnName]=CASE @IdentifierMode WHEN 'RAW' THEN [LeadingColumnName] WHEN 'TOKENIZED' THEN CONVERT(sysname,CONVERT(nvarchar(130),HASHBYTES('SHA2_256',@TokenSalt+CONVERT(varbinary(max),[LeadingColumnName])),1)) END;
    UPDATE [#ExecutionPlanAnalysis_HistogramSteps]
    SET [DatabaseName]=CASE @IdentifierMode WHEN 'RAW' THEN [DatabaseName] WHEN 'TOKENIZED' THEN CONVERT(sysname,CONVERT(nvarchar(130),HASHBYTES('SHA2_256',@TokenSalt+CONVERT(varbinary(max),[DatabaseName])),1)) END,
        [SchemaName]=CASE @IdentifierMode WHEN 'RAW' THEN [SchemaName] WHEN 'TOKENIZED' THEN CONVERT(sysname,CONVERT(nvarchar(130),HASHBYTES('SHA2_256',@TokenSalt+CONVERT(varbinary(max),[SchemaName])),1)) END,
        [ObjectName]=CASE @IdentifierMode WHEN 'RAW' THEN [ObjectName] WHEN 'TOKENIZED' THEN CONVERT(sysname,CONVERT(nvarchar(130),HASHBYTES('SHA2_256',@TokenSalt+CONVERT(varbinary(max),[ObjectName])),1)) END,
        [StatisticsName]=CASE @IdentifierMode WHEN 'RAW' THEN [StatisticsName] WHEN 'TOKENIZED' THEN CONVERT(sysname,CONVERT(nvarchar(130),HASHBYTES('SHA2_256',@TokenSalt+CONVERT(varbinary(max),[StatisticsName])),1)) END,
        [LeadingColumnName]=CASE @IdentifierMode WHEN 'RAW' THEN [LeadingColumnName] WHEN 'TOKENIZED' THEN CONVERT(sysname,CONVERT(nvarchar(130),HASHBYTES('SHA2_256',@TokenSalt+CONVERT(varbinary(max),[LeadingColumnName])),1)) END;
    UPDATE [#ExecutionPlanAnalysis_PredicateHistogramMappings]
    SET [DatabaseName]=CASE @IdentifierMode WHEN 'RAW' THEN [DatabaseName] WHEN 'TOKENIZED' THEN CONVERT(sysname,CONVERT(nvarchar(130),HASHBYTES('SHA2_256',@TokenSalt+CONVERT(varbinary(max),[DatabaseName])),1)) END,
        [SchemaName]=CASE @IdentifierMode WHEN 'RAW' THEN [SchemaName] WHEN 'TOKENIZED' THEN CONVERT(sysname,CONVERT(nvarchar(130),HASHBYTES('SHA2_256',@TokenSalt+CONVERT(varbinary(max),[SchemaName])),1)) END,
        [ObjectName]=CASE @IdentifierMode WHEN 'RAW' THEN [ObjectName] WHEN 'TOKENIZED' THEN CONVERT(sysname,CONVERT(nvarchar(130),HASHBYTES('SHA2_256',@TokenSalt+CONVERT(varbinary(max),[ObjectName])),1)) END,
        [ColumnName]=CASE @IdentifierMode WHEN 'RAW' THEN [ColumnName] WHEN 'TOKENIZED' THEN CONVERT(sysname,CONVERT(nvarchar(130),HASHBYTES('SHA2_256',@TokenSalt+CONVERT(varbinary(max),[ColumnName])),1)) END,
        [StatisticsName]=CASE @IdentifierMode WHEN 'RAW' THEN [StatisticsName] WHEN 'TOKENIZED' THEN CONVERT(sysname,CONVERT(nvarchar(130),HASHBYTES('SHA2_256',@TokenSalt+CONVERT(varbinary(max),[StatisticsName])),1)) END;

    /* Weitere Identifikatoren erst nach fachlicher Korrelation schützen. */
    IF @IdentifierMode IN ('TOKENIZED','OMIT')
    BEGIN
        UPDATE [#ExecutionPlanAnalysis_Operators]
        SET [ObjectDatabaseName]=CASE WHEN @IdentifierMode='TOKENIZED' AND [ObjectDatabaseName] IS NOT NULL THEN CONVERT(nvarchar(130),HASHBYTES('SHA2_256',@TokenSalt+CONVERT(varbinary(max),[ObjectDatabaseName])),1) END,
            [ObjectSchemaName]=CASE WHEN @IdentifierMode='TOKENIZED' AND [ObjectSchemaName] IS NOT NULL THEN CONVERT(nvarchar(130),HASHBYTES('SHA2_256',@TokenSalt+CONVERT(varbinary(max),[ObjectSchemaName])),1) END,
            [ObjectName]=CASE WHEN @IdentifierMode='TOKENIZED' AND [ObjectName] IS NOT NULL THEN CONVERT(nvarchar(130),HASHBYTES('SHA2_256',@TokenSalt+CONVERT(varbinary(max),[ObjectName])),1) END,
            [IndexName]=CASE WHEN @IdentifierMode='TOKENIZED' AND [IndexName] IS NOT NULL THEN CONVERT(nvarchar(130),HASHBYTES('SHA2_256',@TokenSalt+CONVERT(varbinary(max),[IndexName])),1) END;
        UPDATE [#ExecutionPlanAnalysis_AccessPaths]
        SET [DatabaseName]=CASE WHEN @IdentifierMode='TOKENIZED' AND [DatabaseName] IS NOT NULL THEN CONVERT(nvarchar(130),HASHBYTES('SHA2_256',@TokenSalt+CONVERT(varbinary(max),[DatabaseName])),1) END,
            [SchemaName]=CASE WHEN @IdentifierMode='TOKENIZED' AND [SchemaName] IS NOT NULL THEN CONVERT(nvarchar(130),HASHBYTES('SHA2_256',@TokenSalt+CONVERT(varbinary(max),[SchemaName])),1) END,
            [ObjectName]=CASE WHEN @IdentifierMode='TOKENIZED' AND [ObjectName] IS NOT NULL THEN CONVERT(nvarchar(130),HASHBYTES('SHA2_256',@TokenSalt+CONVERT(varbinary(max),[ObjectName])),1) END,
            [IndexName]=CASE WHEN @IdentifierMode='TOKENIZED' AND [IndexName] IS NOT NULL THEN CONVERT(nvarchar(130),HASHBYTES('SHA2_256',@TokenSalt+CONVERT(varbinary(max),[IndexName])),1) END;
        UPDATE [#ExecutionPlanAnalysis_StatisticsUsage]
        SET [DatabaseName]=CASE WHEN @IdentifierMode='TOKENIZED' AND [DatabaseName] IS NOT NULL THEN CONVERT(sysname,CONVERT(nvarchar(130),HASHBYTES('SHA2_256',@TokenSalt+CONVERT(varbinary(max),[DatabaseName])),1)) END,
            [SchemaName]=CASE WHEN @IdentifierMode='TOKENIZED' AND [SchemaName] IS NOT NULL THEN CONVERT(sysname,CONVERT(nvarchar(130),HASHBYTES('SHA2_256',@TokenSalt+CONVERT(varbinary(max),[SchemaName])),1)) END,
            [ObjectName]=CASE WHEN @IdentifierMode='TOKENIZED' AND [ObjectName] IS NOT NULL THEN CONVERT(sysname,CONVERT(nvarchar(130),HASHBYTES('SHA2_256',@TokenSalt+CONVERT(varbinary(max),[ObjectName])),1)) END,
            [StatisticsName]=CASE WHEN @IdentifierMode='TOKENIZED' AND [StatisticsName] IS NOT NULL THEN CONVERT(sysname,CONVERT(nvarchar(130),HASHBYTES('SHA2_256',@TokenSalt+CONVERT(varbinary(max),[StatisticsName])),1)) END;
        UPDATE [#ExecutionPlanAnalysis_Parameters]
        SET [ParameterName]=CASE WHEN @IdentifierMode='TOKENIZED' AND [ParameterName] IS NOT NULL THEN CONVERT(nvarchar(130),HASHBYTES('SHA2_256',@TokenSalt+CONVERT(varbinary(max),[ParameterName])),1) END;
        UPDATE [#ExecutionPlanAnalysis_ParameterEvidence]
        SET [ParameterName]=CASE WHEN @IdentifierMode='TOKENIZED' AND [ParameterName] IS NOT NULL THEN CONVERT(nvarchar(130),HASHBYTES('SHA2_256',@TokenSalt+CONVERT(varbinary(max),[ParameterName])),1) END,
            [QueryStoreDatabaseName]=CASE WHEN @IdentifierMode='TOKENIZED' AND [QueryStoreDatabaseName] IS NOT NULL THEN CONVERT(sysname,CONVERT(nvarchar(130),HASHBYTES('SHA2_256',@TokenSalt+CONVERT(varbinary(max),[QueryStoreDatabaseName])),1)) END;
        UPDATE [#ExecutionPlanAnalysis_QueryStoreContext]
        SET [QueryStoreDatabaseName]=CASE WHEN @IdentifierMode='TOKENIZED' AND [QueryStoreDatabaseName] IS NOT NULL
            THEN CONVERT(sysname,CONVERT(nvarchar(130),HASHBYTES('SHA2_256',@TokenSalt+CONVERT(varbinary(max),[QueryStoreDatabaseName])),1)) END;
    END;

    IF (SELECT COUNT(*) FROM [#ExecutionPlanAnalysis_Operators])>@MaxOperatoren
    BEGIN
        CREATE TABLE [#ExecutionPlanAnalysis_RetainedOperators]
        (
              [AnalysisObjectId] int NOT NULL
            , [StatementOrdinal] int NOT NULL
            , [NodeId] int NOT NULL
            , PRIMARY KEY ([AnalysisObjectId],[StatementOrdinal],[NodeId])
        );
        INSERT [#ExecutionPlanAnalysis_RetainedOperators]([AnalysisObjectId],[StatementOrdinal],[NodeId])
        SELECT TOP (@MaxOperatoren) [AnalysisObjectId],[StatementOrdinal],[NodeId]
        FROM [#ExecutionPlanAnalysis_Operators]
        ORDER BY [StatementOrdinal],[NodeId];

        DELETE [o]
        FROM [#ExecutionPlanAnalysis_Operators] AS [o]
        WHERE NOT EXISTS
        (
            SELECT 1 FROM [#ExecutionPlanAnalysis_RetainedOperators] AS [k]
            WHERE [k].[AnalysisObjectId]=[o].[AnalysisObjectId]
              AND [k].[StatementOrdinal]=[o].[StatementOrdinal]
              AND [k].[NodeId]=[o].[NodeId]
        );
        DELETE [r]
        FROM [#ExecutionPlanAnalysis_OperatorRuntime] AS [r]
        WHERE NOT EXISTS
        (
            SELECT 1 FROM [#ExecutionPlanAnalysis_RetainedOperators] AS [k]
            WHERE [k].[AnalysisObjectId]=[r].[AnalysisObjectId]
              AND [k].[StatementOrdinal]=[r].[StatementOrdinal]
              AND [k].[NodeId]=[r].[NodeId]
        );
        DELETE [r]
        FROM [#ExecutionPlanAnalysis_OperatorThreadRuntime] AS [r]
        WHERE NOT EXISTS
        (
            SELECT 1 FROM [#ExecutionPlanAnalysis_RetainedOperators] AS [k]
            WHERE [k].[AnalysisObjectId]=[r].[AnalysisObjectId]
              AND [k].[StatementOrdinal]=[r].[StatementOrdinal]
              AND [k].[NodeId]=[r].[NodeId]
        );
        DELETE [a]
        FROM [#ExecutionPlanAnalysis_AccessPaths] AS [a]
        WHERE [a].[NodeId] IS NOT NULL
          AND NOT EXISTS
        (
            SELECT 1 FROM [#ExecutionPlanAnalysis_RetainedOperators] AS [k]
            WHERE [k].[AnalysisObjectId]=[a].[AnalysisObjectId]
              AND [k].[StatementOrdinal]=[a].[StatementOrdinal]
              AND [k].[NodeId]=[a].[NodeId]
        );
        DELETE [m]
        FROM [#ExecutionPlanAnalysis_MemoryAndSpills] AS [m]
        WHERE [m].[NodeId] IS NOT NULL
          AND NOT EXISTS
        (
            SELECT 1 FROM [#ExecutionPlanAnalysis_RetainedOperators] AS [k]
            WHERE [k].[AnalysisObjectId]=[m].[AnalysisObjectId]
              AND [k].[StatementOrdinal]=[m].[StatementOrdinal]
              AND [k].[NodeId]=[m].[NodeId]
        );
        DELETE [f]
        FROM [#ExecutionPlanAnalysis_Findings] AS [f]
        WHERE [f].[NodeId] IS NOT NULL
          AND NOT EXISTS
        (
            SELECT 1 FROM [#ExecutionPlanAnalysis_RetainedOperators] AS [k]
            WHERE [k].[AnalysisObjectId]=[f].[AnalysisObjectId]
              AND [k].[StatementOrdinal]=[f].[StatementOrdinal]
              AND [k].[NodeId]=[f].[NodeId]
        );
        DELETE [w]
        FROM [#ExecutionPlanAnalysis_PlanWarnings] AS [w]
        WHERE [w].[NodeId] IS NOT NULL
          AND NOT EXISTS
        (
            SELECT 1 FROM [#ExecutionPlanAnalysis_RetainedOperators] AS [k]
            WHERE [k].[AnalysisObjectId]=[w].[AnalysisObjectId]
              AND [k].[StatementOrdinal]=[w].[StatementOrdinal]
              AND [k].[NodeId]=[w].[NodeId]
        );
        DELETE [r]
        FROM [#ExecutionPlanAnalysis_RuntimeFeedback] AS [r]
        WHERE [r].[NodeId] IS NOT NULL
          AND NOT EXISTS
        (
            SELECT 1 FROM [#ExecutionPlanAnalysis_RetainedOperators] AS [k]
            WHERE [k].[AnalysisObjectId]=[r].[AnalysisObjectId]
              AND [k].[StatementOrdinal]=[r].[StatementOrdinal]
              AND [k].[NodeId]=[r].[NodeId]
        );
        DELETE [v]
        FROM [#ExecutionPlanAnalysis_FeedbackAndVariants] AS [v]
        WHERE [v].[NodeId] IS NOT NULL
          AND NOT EXISTS
        (
            SELECT 1 FROM [#ExecutionPlanAnalysis_RetainedOperators] AS [k]
            WHERE [k].[AnalysisObjectId]=[v].[AnalysisObjectId]
              AND [k].[StatementOrdinal]=[v].[StatementOrdinal]
              AND [k].[NodeId]=[v].[NodeId]
        );
        SET @IsPartialOut=1;
        IF @StatusCodeOut='AVAILABLE' SET @StatusCodeOut='PARTIAL';
    END;
    IF (SELECT COUNT(*) FROM [#ExecutionPlanAnalysis_Findings])>@MaxFindings
    BEGIN
        DELETE [f]
        FROM [#ExecutionPlanAnalysis_Findings] AS [f]
        WHERE [f].[FindingOrdinal] NOT IN
        (
            SELECT TOP (@MaxFindings) [FindingOrdinal]
            FROM [#ExecutionPlanAnalysis_Findings]
            ORDER BY CASE [Severity] WHEN 'CRITICAL' THEN 1 WHEN 'HIGH' THEN 2 WHEN 'MEDIUM' THEN 3 WHEN 'LOW' THEN 4 ELSE 5 END,
                     [FindingOrdinal]
        );
        SET @IsPartialOut=1;
        IF @StatusCodeOut='AVAILABLE' SET @StatusCodeOut='PARTIAL';
    END;
    IF SYSUTCDATETIME()>@Deadline
    BEGIN
        SET @IsPartialOut=1;
        IF @StatusCodeOut='AVAILABLE' SET @StatusCodeOut='PARTIAL';
        IF @ErrorMessageOut IS NULL SET @ErrorMessageOut=N'Das kooperative Zeitbudget wurde während der Verarbeitung überschritten.';
    END;

    INSERT [#ExecutionPlanAnalysis_ModuleStatus]
    SELECT N'USP_ExecutionPlanAnalysis',@Now,@StatusCodeOut,@IsPartialOut,@EffectivePlanSource,@RuntimeScope,@Profile,
           (SELECT COUNT(*) FROM [#ExecutionPlanAnalysis_Statements]),(SELECT COUNT(*) FROM [#ExecutionPlanAnalysis_Operators]),(SELECT COUNT(*) FROM [#ExecutionPlanAnalysis_Findings]),
           @ErrorNumberOut,@ErrorMessageOut;

    IF @JsonErzeugen=1
    BEGIN
        DECLARE @MetaJson nvarchar(max)=(SELECT N'ExecutionPlanAnalysis' [resultName],3 [schemaVersion],@Now [generatedAtUtc],@StatusCodeOut [statusCode],@IsPartialOut [isPartial],@EffectivePlanSource [planSource],@RuntimeScope [runtimeCounterScope],@Profile [workloadProfile],@PrivacyMode [evidencePrivacyMode],@IdentifierMode [identifierPrivacyMode] FOR JSON PATH,WITHOUT_ARRAY_WRAPPER,INCLUDE_NULL_VALUES);
        DECLARE @CapabilitiesJson nvarchar(max)=(SELECT * FROM [#ExecutionPlanAnalysis_Capabilities] ORDER BY [FeatureCode] FOR JSON PATH,INCLUDE_NULL_VALUES);
        DECLARE @PlanJson nvarchar(max)=(SELECT * FROM [#ExecutionPlanAnalysis_PlanDocuments] FOR JSON PATH,INCLUDE_NULL_VALUES);
        DECLARE @StatementsJson nvarchar(max)=(SELECT * FROM [#ExecutionPlanAnalysis_Statements] ORDER BY [StatementOrdinal] FOR JSON PATH,INCLUDE_NULL_VALUES);
        DECLARE @OperatorsJson nvarchar(max)=(SELECT * FROM [#ExecutionPlanAnalysis_Operators] ORDER BY [StatementOrdinal],[NodeId] FOR JSON PATH,INCLUDE_NULL_VALUES);
        DECLARE @RuntimeJson nvarchar(max)=(SELECT * FROM [#ExecutionPlanAnalysis_OperatorRuntime] ORDER BY [StatementOrdinal],[NodeId] FOR JSON PATH,INCLUDE_NULL_VALUES);
        DECLARE @ThreadsJson nvarchar(max)=(SELECT * FROM [#ExecutionPlanAnalysis_OperatorThreadRuntime] ORDER BY [StatementOrdinal],[NodeId],[ThreadId] FOR JSON PATH,INCLUDE_NULL_VALUES);
        DECLARE @AccessJson nvarchar(max)=(SELECT * FROM [#ExecutionPlanAnalysis_AccessPaths] ORDER BY [StatementOrdinal],[NodeId] FOR JSON PATH,INCLUDE_NULL_VALUES);
        DECLARE @StatsJson nvarchar(max)=(SELECT * FROM [#ExecutionPlanAnalysis_StatisticsUsage] ORDER BY [StatementOrdinal],[StatisticsUsageOrdinal] FOR JSON PATH,INCLUDE_NULL_VALUES);
        DECLARE @ParametersJson nvarchar(max)=(SELECT * FROM [#ExecutionPlanAnalysis_Parameters] ORDER BY [StatementOrdinal],[ParameterName] FOR JSON PATH,INCLUDE_NULL_VALUES);
        DECLARE @ParameterEvidenceJson nvarchar(max)=(SELECT * FROM [#ExecutionPlanAnalysis_ParameterEvidence] ORDER BY [CandidateId],[StatementOrdinal],[EvidenceKind],[ParameterName] FOR JSON PATH,INCLUDE_NULL_VALUES);
        DECLARE @PlanWarningsJson nvarchar(max)=(SELECT * FROM [#ExecutionPlanAnalysis_PlanWarnings] ORDER BY [WarningOrdinal] FOR JSON PATH,INCLUDE_NULL_VALUES);
        DECLARE @OptimizerContextJson nvarchar(max)=(SELECT * FROM [#ExecutionPlanAnalysis_OptimizerContext] ORDER BY [StatementOrdinal] FOR JSON PATH,INCLUDE_NULL_VALUES);
        DECLARE @RuntimeFeedbackJson nvarchar(max)=(SELECT * FROM [#ExecutionPlanAnalysis_RuntimeFeedback] ORDER BY [FeedbackOrdinal] FOR JSON PATH,INCLUDE_NULL_VALUES);
        DECLARE @QueryStoreContextJson nvarchar(max)=(SELECT * FROM [#ExecutionPlanAnalysis_QueryStoreContext] ORDER BY [QueryStorePlanId] FOR JSON PATH,INCLUDE_NULL_VALUES);
        DECLARE @FeedbackAndVariantsJson nvarchar(max)=(SELECT * FROM [#ExecutionPlanAnalysis_FeedbackAndVariants] ORDER BY [RecordOrdinal] FOR JSON PATH,INCLUDE_NULL_VALUES);
        DECLARE @MemoryJson nvarchar(max)=(SELECT * FROM [#ExecutionPlanAnalysis_MemoryAndSpills] ORDER BY [StatementOrdinal],[NodeId],[RecordType] FOR JSON PATH,INCLUDE_NULL_VALUES);
        DECLARE @EvidenceJsonOut nvarchar(max)=(SELECT * FROM [#ExecutionPlanAnalysis_ExecutionEvidence] ORDER BY [StatementOrdinal],[EvidenceType],[MetricName] FOR JSON PATH,INCLUDE_NULL_VALUES);
        DECLARE @HistogramSummaryJson nvarchar(max)=(SELECT * FROM [#ExecutionPlanAnalysis_HistogramSummaries] FOR JSON PATH,INCLUDE_NULL_VALUES);
        DECLARE @HistogramStepsJson nvarchar(max)=(SELECT * FROM [#ExecutionPlanAnalysis_HistogramSteps] FOR JSON PATH,INCLUDE_NULL_VALUES);
        DECLARE @MappingsJson nvarchar(max)=(SELECT * FROM [#ExecutionPlanAnalysis_PredicateHistogramMappings] FOR JSON PATH,INCLUDE_NULL_VALUES);
        DECLARE @FindingsJson nvarchar(max)=(SELECT * FROM [#ExecutionPlanAnalysis_Findings] ORDER BY CASE [Severity] WHEN 'CRITICAL' THEN 1 WHEN 'HIGH' THEN 2 WHEN 'MEDIUM' THEN 3 WHEN 'LOW' THEN 4 ELSE 5 END,[FindingOrdinal] FOR JSON PATH,INCLUDE_NULL_VALUES);
        SET @Json=CONCAT(N'{"meta":',COALESCE(@MetaJson,N'{}'),N',"capabilities":',COALESCE(@CapabilitiesJson,N'[]'),N',"planDocuments":',COALESCE(@PlanJson,N'[]'),N',"statements":',COALESCE(@StatementsJson,N'[]'),N',"operatorTree":',COALESCE(@OperatorsJson,N'[]'),N',"operatorRuntime":',COALESCE(@RuntimeJson,N'[]'),N',"operatorThreadRuntime":',COALESCE(@ThreadsJson,N'[]'),N',"accessPaths":',COALESCE(@AccessJson,N'[]'),N',"statisticsUsage":',COALESCE(@StatsJson,N'[]'),N',"parametersAndVariants":',COALESCE(@ParametersJson,N'[]'),N',"parameters":',COALESCE(@ParameterEvidenceJson,N'[]'),N',"planWarnings":',COALESCE(@PlanWarningsJson,N'[]'),N',"optimizerContext":',COALESCE(@OptimizerContextJson,N'[]'),N',"runtimeFeedback":',COALESCE(@RuntimeFeedbackJson,N'[]'),N',"queryStoreContext":',COALESCE(@QueryStoreContextJson,N'[]'),N',"feedbackAndVariants":',COALESCE(@FeedbackAndVariantsJson,N'[]'),N',"memoryAndSpills":',COALESCE(@MemoryJson,N'[]'),N',"executionEvidence":',COALESCE(@EvidenceJsonOut,N'[]'),N',"histogramSummaries":',COALESCE(@HistogramSummaryJson,N'[]'),N',"histogramSteps":',COALESCE(@HistogramStepsJson,N'[]'),N',"predicateHistogramMappings":',COALESCE(@MappingsJson,N'[]'),N',"findings":',COALESCE(@FindingsJson,N'[]'),N'}');
    END;

    IF @OutputMode='RAW'
    BEGIN
        SELECT * FROM [#ExecutionPlanAnalysis_ModuleStatus];
        SELECT * FROM [#ExecutionPlanAnalysis_Capabilities] ORDER BY [FeatureCode];
        SELECT * FROM [#ExecutionPlanAnalysis_PlanDocuments];
        SELECT * FROM [#ExecutionPlanAnalysis_Statements] ORDER BY [StatementOrdinal];
        SELECT * FROM [#ExecutionPlanAnalysis_Operators] ORDER BY [StatementOrdinal],[NodeId];
        SELECT * FROM [#ExecutionPlanAnalysis_OperatorRuntime] ORDER BY [StatementOrdinal],[NodeId];
        SELECT * FROM [#ExecutionPlanAnalysis_OperatorThreadRuntime] ORDER BY [StatementOrdinal],[NodeId],[ThreadId];
        SELECT * FROM [#ExecutionPlanAnalysis_AccessPaths] ORDER BY [StatementOrdinal],[NodeId];
        SELECT * FROM [#ExecutionPlanAnalysis_StatisticsUsage] ORDER BY [StatementOrdinal],[StatisticsUsageOrdinal];
        SELECT * FROM [#ExecutionPlanAnalysis_Parameters] ORDER BY [StatementOrdinal],[ParameterName];
        SELECT * FROM [#ExecutionPlanAnalysis_ParameterEvidence] ORDER BY [CandidateId],[StatementOrdinal],[EvidenceKind],[ParameterName];
        SELECT * FROM [#ExecutionPlanAnalysis_PlanWarnings] ORDER BY [WarningOrdinal];
        SELECT * FROM [#ExecutionPlanAnalysis_OptimizerContext] ORDER BY [StatementOrdinal];
        SELECT * FROM [#ExecutionPlanAnalysis_RuntimeFeedback] ORDER BY [FeedbackOrdinal];
        SELECT * FROM [#ExecutionPlanAnalysis_QueryStoreContext] ORDER BY [QueryStorePlanId];
        SELECT * FROM [#ExecutionPlanAnalysis_FeedbackAndVariants] ORDER BY [RecordOrdinal];
        SELECT * FROM [#ExecutionPlanAnalysis_MemoryAndSpills] ORDER BY [StatementOrdinal],[NodeId],[RecordType];
        SELECT * FROM [#ExecutionPlanAnalysis_ExecutionEvidence] ORDER BY [StatementOrdinal],[EvidenceType],[MetricName];
        SELECT * FROM [#ExecutionPlanAnalysis_HistogramSummaries];
        SELECT * FROM [#ExecutionPlanAnalysis_HistogramSteps];
        SELECT * FROM [#ExecutionPlanAnalysis_PredicateHistogramMappings];
        SELECT * FROM [#ExecutionPlanAnalysis_Findings] ORDER BY CASE [Severity] WHEN 'CRITICAL' THEN 1 WHEN 'HIGH' THEN 2 WHEN 'MEDIUM' THEN 3 WHEN 'LOW' THEN 4 ELSE 5 END,[FindingOrdinal];
    END;

    IF @ConsoleResultRequested=1
        EXEC [monitor].[InternalEmitConsoleResult]
              @SourceTable=N'#ExecutionPlanAnalysis_Findings'
            , @ResultLabel=N'Execution Plan Finding'
            , @EmptyMessage=N'Keine Findings im gewählten Scope'
            , @StatusCode=@StatusCodeOut
            , @StatusMessage=@ErrorMessageOut;

    IF @TableRequested=1
    BEGIN
        DECLARE @ResultName sysname,@TargetTable sysname,@SourceTable sysname;
        DECLARE [OutputCursor] CURSOR LOCAL FAST_FORWARD FOR
            SELECT [ResultName],[TargetTable] FROM [#ExecutionPlanAnalysis_TableMap] ORDER BY [ResultName];
        OPEN [OutputCursor];
        FETCH NEXT FROM [OutputCursor] INTO @ResultName,@TargetTable;
        WHILE @@FETCH_STATUS=0
        BEGIN
            SET @SourceTable=CASE @ResultName
                WHEN N'moduleStatus' THEN N'#ExecutionPlanAnalysis_ModuleStatus'
                WHEN N'capabilities' THEN N'#ExecutionPlanAnalysis_Capabilities'
                WHEN N'planDocuments' THEN N'#ExecutionPlanAnalysis_PlanDocuments'
                WHEN N'statements' THEN N'#ExecutionPlanAnalysis_Statements'
                WHEN N'operatorTree' THEN N'#ExecutionPlanAnalysis_Operators'
                WHEN N'operatorRuntime' THEN N'#ExecutionPlanAnalysis_OperatorRuntime'
                WHEN N'operatorThreadRuntime' THEN N'#ExecutionPlanAnalysis_OperatorThreadRuntime'
                WHEN N'accessPaths' THEN N'#ExecutionPlanAnalysis_AccessPaths'
                WHEN N'statisticsUsage' THEN N'#ExecutionPlanAnalysis_StatisticsUsage'
                WHEN N'parametersAndVariants' THEN N'#ExecutionPlanAnalysis_Parameters'
                WHEN N'parameters' THEN N'#ExecutionPlanAnalysis_ParameterEvidence'
                WHEN N'planWarnings' THEN N'#ExecutionPlanAnalysis_PlanWarnings'
                WHEN N'optimizerContext' THEN N'#ExecutionPlanAnalysis_OptimizerContext'
                WHEN N'runtimeFeedback' THEN N'#ExecutionPlanAnalysis_RuntimeFeedback'
                WHEN N'queryStoreContext' THEN N'#ExecutionPlanAnalysis_QueryStoreContext'
                WHEN N'feedbackAndVariants' THEN N'#ExecutionPlanAnalysis_FeedbackAndVariants'
                WHEN N'memoryAndSpills' THEN N'#ExecutionPlanAnalysis_MemoryAndSpills'
                WHEN N'executionEvidence' THEN N'#ExecutionPlanAnalysis_ExecutionEvidence'
                WHEN N'histogramSummaries' THEN N'#ExecutionPlanAnalysis_HistogramSummaries'
                WHEN N'histogramSteps' THEN N'#ExecutionPlanAnalysis_HistogramSteps'
                WHEN N'predicateHistogramMappings' THEN N'#ExecutionPlanAnalysis_PredicateHistogramMappings'
                WHEN N'findings' THEN N'#ExecutionPlanAnalysis_Findings' END;
            EXEC [monitor].[InternalWriteResultTable]
                  @SourceTable=@SourceTable,@TargetTable=@TargetTable,@ThrowOnError=1;
            FETCH NEXT FROM [OutputCursor] INTO @ResultName,@TargetTable;
        END;
        CLOSE [OutputCursor];DEALLOCATE [OutputCursor];
    END;

    IF @PrintMeldungen=1 AND @StatusCodeOut NOT IN ('AVAILABLE')
    BEGIN
        DECLARE @Message nvarchar(2048)=FORMATMESSAGE(N'WARNUNG USP_ExecutionPlanAnalysis: %s - %s',@StatusCodeOut,COALESCE(@ErrorMessageOut,N'partielle Analyse'));
        RAISERROR(N'%s',10,1,@Message) WITH NOWAIT;
    END;
END;
GO
-- END SOURCE: Code/04_PlanCache/053_USP_ExecutionPlanAnalysis.sql

-- BEGIN SOURCE: Code/04_PlanCache/050_USP_ShowplanAnalysis.sql
/*
===============================================================================
Objekt       : monitor.USP_ShowplanAnalysis
Version      : 2.2.0
Stand        : 2026-07-23
Typ          : Stored Procedure
Zweck        : Selektiert begrenzt Plan-Cache-Kandidaten und verwendet je
               eindeutigem Planhandle die zentrale Execution-Plan-Analyse.
               Mehrere dm_exec_query_stats-Statements desselben Batchplans
               führen nicht mehr zu wiederholtem XML-Shredding.
SQL-Version  : SQL Server 2019 oder neuer.
Resultsets   : CONSOLE: findings. TABLE: parameters, DIAG-005-Kontext, findings.
               RAW: moduleStatus, planStatus, parameters, DIAG-005-Kontext, findings.
Berechtigung : VIEW SERVER STATE bzw. SQL Server 2022+
               VIEW SERVER PERFORMANCE STATE für Plan-Cache-Quellen.
===============================================================================
*/
CREATE OR ALTER PROCEDURE [monitor].[USP_ShowplanAnalysis]
      @PlanHandle                    varbinary(64)   = NULL
    , @QueryHash                     binary(8)       = NULL
    , @QueryPlanHash                 binary(8)       = NULL
    , @DatabaseNames                 nvarchar(max)   = NULL
    , @SystemdatenbankenEinbeziehen  bit             = 0
    , @DatabaseNamePattern           nvarchar(4000)  = NULL
    , @HighImpactConfirmed           bit             = 0
    , @TextPattern                   nvarchar(4000)  = NULL
    , @AnalyseModus                  varchar(16)      = 'GEZIELT'
    , @PlanQuelle                    varchar(16)      = 'AUTO'
    , @Sortierung                    varchar(32)      = 'CPU_TOTAL'
    , @MinExecutionCount             bigint          = 1
    , @MaxAnalyseobjekte             int             = 20
    , @MaxDurationSeconds            int             = 30
    , @MaxZeilen                     int             = 50000
    , @ParentQueryStatsSnapshot      bit             = 0
    , @WorkloadProfil                varchar(32)      = 'AUTO'
    , @MinSchweregrad                varchar(16)      = 'INFO'
    , @MitThreadRuntime              bit             = 0
    , @MitSqlText                    bit             = 0
    , @StatistikEvidenzModus         varchar(16)      = 'PLAN_ONLY'
    , @HistogrammModus               varchar(16)      = 'NONE'
    , @MetadatenQuellenmodus         varchar(16)      = 'EVIDENCE_ONLY'
    , @QuellumgebungBestaetigt       bit             = 0
    , @EvidenzDatenschutzModus       varchar(24)      = 'DERIVED_ONLY'
    , @IdentifierDatenschutzModus    varchar(16)      = 'RAW'
    , @SensitiveDataConfirmed        bit             = 0
    , @MaxStatistiken                int             = 100
    , @MaxHistogrammSchritte         int             = 20000
    , @ResultSetArt                  varchar(16)      = 'CONSOLE'
    , @ResultTablesJson              nvarchar(max)   = NULL
    , @JsonErzeugen                  bit             = 0
    , @Json                          nvarchar(max)   = NULL OUTPUT
    , @PrintMeldungen                bit             = 1
    , @Hilfe                         bit             = 0
AS
BEGIN
    SET NOCOUNT ON;
    SET LOCK_TIMEOUT 0;
    SET @Json=NULL;

    DECLARE @Now datetime2(3)=SYSUTCDATETIME();
    DECLARE @Deadline datetime2(3)=DATEADD(SECOND,@MaxDurationSeconds,@Now);
    DECLARE @OutputMode varchar(16)=UPPER(LTRIM(RTRIM(COALESCE(@ResultSetArt,''))));
    DECLARE @ConsoleResultRequested bit=CONVERT(bit,CASE WHEN @OutputMode='CONSOLE' THEN 1 ELSE 0 END);
    DECLARE @TableRequested bit=CONVERT(bit,CASE WHEN @OutputMode='TABLE' THEN 1 ELSE 0 END);
    DECLARE @Mode varchar(16)=UPPER(LTRIM(RTRIM(COALESCE(@AnalyseModus,'GEZIELT'))));
    DECLARE @Source varchar(16)=UPPER(LTRIM(RTRIM(COALESCE(@PlanQuelle,'AUTO'))));
    DECLARE @Order varchar(32)=UPPER(LTRIM(RTRIM(COALESCE(@Sortierung,'CPU_TOTAL'))));
    DECLARE @Limit bigint=CASE WHEN @MaxAnalyseobjekte IS NULL OR @MaxAnalyseobjekte=0 THEN CONVERT(bigint,9223372036854775807) ELSE @MaxAnalyseobjekte END;
    DECLARE @ResultLimit bigint=CASE WHEN @MaxZeilen IS NULL OR @MaxZeilen=0 THEN CONVERT(bigint,9223372036854775807) ELSE @MaxZeilen END;
    DECLARE @StatusCode varchar(40)='AVAILABLE',@IsPartial bit=0,@ErrorNumber int=NULL,@ErrorMessage nvarchar(2048)=NULL;
    DECLARE @ProcessedPlans int=0,@CandidateCount int=0;
    DECLARE @CrossDatabaseRequested bit=0;
    DECLARE @ChildAnalyseTiefe varchar(16)=CASE WHEN @Mode='VOLL' THEN 'FULL' ELSE 'STANDARD' END;
    DECLARE @ChildMaxRows int=CASE WHEN @MaxZeilen IS NULL OR @MaxZeilen=0 THEN 50000 WHEN @MaxZeilen>2147483647 THEN 2147483647 ELSE @MaxZeilen END;

    IF @Hilfe=1
    BEGIN
        PRINT N'monitor.USP_ShowplanAnalysis';
        PRINT N'Selektiert eindeutige Planhandles und verwendet monitor.USP_ExecutionPlanAnalysis als zentrale Analyse-Engine.';
        PRINT N'@AnalyseModus GEZIELT|VOLL. GEZIELT benötigt mindestens einen Plan-, Hash-, Datenbank- oder Textselektor.';
        PRINT N'@PlanQuelle AUTO|COMPILE|LAST_ACTUAL; @Sortierung CPU_TOTAL|ELAPSED_TOTAL|READS_TOTAL|EXECUTIONS|SPILLS_TOTAL|GRANT_MAX|LAST_EXECUTION.';
        PRINT N'@MaxAnalyseobjekte und @MaxZeilen: positive Grenze; NULL/0 unbegrenzt. Breite Pfade benötigen High-Impact-Bestätigung.';
        PRINT N'Die Datenschutz-, Statistik- und Histogrammparameter entsprechen USP_ExecutionPlanAnalysis.';
        PRINT N'TABLE/RAW/JSON aggregieren parameters sowie planWarnings, optimizerContext, runtimeFeedback, queryStoreContext, feedbackAndVariants und findings kandidatengenau.';
        RETURN;
    END;

    CREATE TABLE [#ShowplanAnalysis_TableMap]([ResultName] sysname NOT NULL,[TargetTable] sysname NOT NULL);
    CREATE TABLE [#ShowplanAnalysis_DatabaseCandidates]
    (
          [DatabaseId] int NOT NULL PRIMARY KEY,[DatabaseName] sysname NOT NULL
        , [StateDesc] nvarchar(60) NULL,[UserAccessDesc] nvarchar(60) NULL,[IsReadOnly] bit NULL
        , [CompatibilityLevel] tinyint NULL,[CollationName] sysname NULL,[RecoveryModelDesc] nvarchar(60) NULL
        , [IsSystemDatabase] bit NULL,[RequestedOrdinal] int NULL
    );
    CREATE TABLE [#ShowplanAnalysis_DatabaseCandidateWarnings]
    (
          [RequestedName] sysname NULL,[StatusCode] varchar(40) NOT NULL,[ErrorMessage] nvarchar(2048) NULL
    );
    CREATE TABLE [#ShowplanAnalysis_Candidates]
    (
          [CandidateId] int IDENTITY(1,1) NOT NULL PRIMARY KEY
        , [PlanHandle] varbinary(64) NOT NULL UNIQUE
        , [ExecutionCount] bigint NULL,[TotalWorkerTime] bigint NULL,[TotalElapsedTime] bigint NULL
        , [TotalLogicalReads] bigint NULL,[TotalSpills] bigint NULL,[MaxGrantKb] bigint NULL
        , [LastExecutionTime] datetime NULL
        , [DatabaseId] int NULL,[SetOptions] bigint NULL,[CompileUserId] int NULL
        , [PlanGenerationNum] bigint NULL,[CacheCreationTime] datetime NULL,[CacheLastExecutionTime] datetime NULL
        , [CacheObjectType] nvarchar(34) NULL,[CacheObjectClass] nvarchar(16) NULL
        , [CacheUseCounts] int NULL,[CacheRefCounts] int NULL,[CacheSizeBytes] bigint NULL,[CachePoolId] int NULL
    );
    CREATE TABLE [#ShowplanAnalysis_ExecutionPlanSourceContext]
    (
          [PlanHandle] varbinary(64) NOT NULL
        , [SourceCapturedAtUtc] datetime2(3) NOT NULL
        , [StatusCode] varchar(40) NOT NULL
        , [DatabaseId] int NULL,[SetOptions] bigint NULL,[CompileUserId] int NULL
        , [PlanGenerationNum] bigint NULL,[CacheCreationTime] datetime NULL,[CacheLastExecutionTime] datetime NULL
        , [ExecutionCount] bigint NULL,[CacheObjectType] nvarchar(34) NULL,[CacheObjectClass] nvarchar(16) NULL
        , [CacheUseCounts] int NULL,[CacheRefCounts] int NULL,[CacheSizeBytes] bigint NULL,[CachePoolId] int NULL
        , [EvidenceLimit] nvarchar(1000) NULL
        , PRIMARY KEY ([PlanHandle])
    );
    CREATE TABLE [#ShowplanAnalysis_PlanStatus]
    (
          [CandidateId] int NOT NULL,[PlanHandle] varbinary(64) NOT NULL,[StatusCode] varchar(40) NOT NULL
        , [IsPartial] bit NOT NULL,[PlanSource] varchar(24) NULL,[RuntimeCounterScope] varchar(32) NULL
        , [FindingCount] int NOT NULL,[ParseDurationMs] bigint NOT NULL,[ErrorNumber] int NULL,[ErrorMessage] nvarchar(2048) NULL
    );
    CREATE TABLE [#ShowplanAnalysis_Findings]
    (
          [CandidateId] int NOT NULL,[PlanHandle] varbinary(64) NOT NULL,[FindingOrdinal] bigint NOT NULL
        , [FindingCode] varchar(100) NOT NULL,[Category] varchar(40) NOT NULL,[Severity] varchar(16) NOT NULL
        , [Confidence] varchar(32) NOT NULL,[EvidenceLevel] varchar(40) NOT NULL
        , [StatementOrdinal] int NULL,[StatementId] int NULL,[NodeId] int NULL
        , [PhysicalOp] nvarchar(128) NULL,[LogicalOp] nvarchar(128) NULL
        , [MetricName] varchar(80) NULL,[MetricValue] decimal(38,4) NULL,[MetricUnit] nvarchar(40) NULL
        , [ThresholdValue] decimal(38,4) NULL,[ThresholdSource] varchar(80) NULL,[WorkloadProfile] varchar(32) NOT NULL
        , [Summary] nvarchar(1000) NOT NULL,[Evidence] nvarchar(2000) NOT NULL,[EvidenceLimit] nvarchar(2000) NOT NULL
        , [CounterEvidence] nvarchar(1000) NULL,[RecommendedNextCheck] nvarchar(1000) NOT NULL
    );
    CREATE TABLE [#ShowplanAnalysis_Parameters]
    (
          [CandidateId] int NOT NULL
        , [PlanHandle] varbinary(64) NOT NULL
        , [SessionId] smallint NULL
        , [RequestId] int NULL
        , [StatementOrdinal] int NULL
        , [StatementId] int NULL
        , [StatementQueryHash] nvarchar(130) NULL
        , [StatementQueryPlanHash] nvarchar(130) NULL
        , [QueryStoreDatabaseName] sysname NULL
        , [QueryStorePlanId] bigint NULL
        , [PlanDocumentHash] nvarchar(66) NULL
        , [EvidenceKind] varchar(24) NOT NULL
        , [ParameterName] nvarchar(256) NULL
        , [ParameterDataType] nvarchar(256) NULL
        , [CompiledValuePresent] bit NOT NULL
        , [RuntimeValuePresent] bit NOT NULL
        , [CompiledValueIsSqlNull] bit NULL
        , [RuntimeValueIsSqlNull] bit NULL
        , [CompiledValue] nvarchar(4000) NULL
        , [RuntimeValue] nvarchar(4000) NULL
        , [CompiledValueToken] nvarchar(66) NULL
        , [RuntimeValueToken] nvarchar(66) NULL
        , [CompiledValueLength] int NULL
        , [RuntimeValueLength] int NULL
        , [CompiledValueStatus] varchar(40) NOT NULL
        , [RuntimeValueStatus] varchar(40) NOT NULL
        , [ValueStatus] varchar(40) NOT NULL
        , [ValueHandlingStatus] varchar(40) NOT NULL
        , [ValueSource] varchar(40) NOT NULL
        , [SourceObservedAtUtc] datetime2(3) NOT NULL
        , [ValueCapturedAtUtc] datetime2(3) NULL
        , [IsCurrentExecution] bit NULL
        , [IsLastKnownExecution] bit NULL
        , [IsComplete] bit NOT NULL
        , [EvidenceLimit] nvarchar(1000) NULL
    );
    CREATE TABLE [#ShowplanAnalysis_PlanWarnings]
    (
          [CandidateId] int NOT NULL,[PlanHandle] varbinary(64) NOT NULL,[WarningOrdinal] bigint NOT NULL
        , [AnalysisObjectId] int NOT NULL,[StatementOrdinal] int NULL,[StatementId] int NULL,[NodeId] int NULL
        , [WarningCode] varchar(100) NOT NULL,[WarningCategory] varchar(40) NOT NULL,[Severity] varchar(16) NOT NULL
        , [EvidenceKind] varchar(40) NOT NULL,[EvidenceSource] varchar(40) NOT NULL,[PlanSource] varchar(24) NULL
        , [SourceObservedAtUtc] datetime2(3) NOT NULL,[IsCurrent] bit NULL,[IsLastKnown] bit NULL
        , [IsMeasured] bit NOT NULL,[IsInferred] bit NOT NULL,[MetricName] varchar(80) NULL
        , [MetricValue] decimal(38,4) NULL,[MetricUnit] nvarchar(40) NULL,[Detail] nvarchar(2000) NOT NULL
        , [FalsePositiveGuard] nvarchar(2000) NOT NULL,[StatusCode] varchar(40) NOT NULL
    );
    CREATE TABLE [#ShowplanAnalysis_OptimizerContext]
    (
          [CandidateId] int NOT NULL,[PlanHandle] varbinary(64) NOT NULL,[AnalysisObjectId] int NOT NULL
        , [StatementOrdinal] int NULL,[StatementId] int NULL,[PlanSource] varchar(24) NULL
        , [RuntimeCounterScope] varchar(32) NULL,[SourceObservedAtUtc] datetime2(3) NOT NULL
        , [IsCurrent] bit NULL,[IsLastKnown] bit NULL,[OptimizationLevel] nvarchar(128) NULL
        , [EarlyAbortReason] nvarchar(256) NULL,[CardinalityEstimationModelVersion] int NULL
        , [StatementSubTreeCost] decimal(38,8) NULL,[StatementEstimatedRows] decimal(38,4) NULL
        , [CompileTimeMs] bigint NULL,[CompileCpuMs] bigint NULL,[CompileMemoryKb] bigint NULL
        , [RetrievedFromCache] bit NULL,[NonParallelPlanReason] nvarchar(256) NULL,[PlanDegreeOfParallelism] int NULL
        , [PlanGenerationNum] bigint NULL,[CacheCreationTime] datetime NULL,[CacheLastExecutionTime] datetime NULL
        , [CacheExecutionCount] bigint NULL,[CacheObjectType] nvarchar(34) NULL,[CacheObjectClass] nvarchar(16) NULL
        , [CacheUseCounts] int NULL,[CacheRefCounts] int NULL,[CacheSizeBytes] bigint NULL,[CachePoolId] int NULL
        , [SetOptions] bigint NULL,[CompileUserId] int NULL,[DatabaseId] int NULL
        , [EvidenceMeasurement] varchar(40) NOT NULL,[StatusCode] varchar(40) NOT NULL
        , [FalsePositiveGuard] nvarchar(1000) NOT NULL
    );
    CREATE TABLE [#ShowplanAnalysis_RuntimeFeedback]
    (
          [CandidateId] int NOT NULL,[PlanHandle] varbinary(64) NOT NULL,[FeedbackOrdinal] bigint NOT NULL
        , [AnalysisObjectId] int NOT NULL,[StatementOrdinal] int NULL,[StatementId] int NULL,[NodeId] int NULL
        , [FeedbackType] varchar(40) NOT NULL,[FeedbackState] nvarchar(128) NULL,[MetricName] varchar(80) NULL
        , [ObservedValue] decimal(38,4) NULL,[BaselineValue] decimal(38,4) NULL,[DeltaRatio] decimal(38,8) NULL
        , [MetricUnit] nvarchar(40) NULL,[RuntimeCounterScope] varchar(32) NULL,[EvidenceSource] varchar(40) NOT NULL
        , [SourceObservedAtUtc] datetime2(3) NOT NULL,[IsCurrent] bit NULL,[IsLastKnown] bit NULL
        , [IsMeasured] bit NOT NULL,[IsDerived] bit NOT NULL,[StatusCode] varchar(40) NOT NULL
        , [EvidenceLimit] nvarchar(1000) NOT NULL
    );
    CREATE TABLE [#ShowplanAnalysis_QueryStoreContext]
    (
          [CandidateId] int NOT NULL,[PlanHandle] varbinary(64) NOT NULL,[AnalysisObjectId] int NOT NULL
        , [QueryStoreDatabaseName] sysname NULL,[QueryStorePlanId] bigint NULL,[QueryStoreQueryId] bigint NULL
        , [PlanGroupId] bigint NULL,[EngineVersion] nvarchar(32) NULL,[CompatibilityLevel] smallint NULL
        , [QueryPlanHash] binary(8) NULL,[IsTrivialPlan] bit NULL,[IsParallelPlan] bit NULL,[IsForcedPlan] bit NULL
        , [PlanForcingTypeDesc] nvarchar(60) NULL,[ForceFailureCount] bigint NULL
        , [LastForceFailureReason] int NULL,[LastForceFailureReasonDesc] nvarchar(128) NULL
        , [CountCompiles] bigint NULL,[InitialCompileStartTime] datetimeoffset(7) NULL
        , [LastCompileStartTime] datetimeoffset(7) NULL,[LastExecutionTime] datetimeoffset(7) NULL
        , [AvgCompileDurationUs] float NULL,[LastCompileDurationUs] bigint NULL,[ContextSettingsId] bigint NULL
        , [ObjectId] bigint NULL,[QueryHash] binary(8) NULL,[QueryParameterizationTypeDesc] nvarchar(60) NULL
        , [AvgOptimizeDurationUs] float NULL,[AvgCompileMemoryKb] float NULL,[HasCompileReplayScript] bit NULL
        , [IsOptimizedPlanForcingDisabled] bit NULL,[PlanType] int NULL,[PlanTypeDesc] nvarchar(120) NULL
        , [RuntimeExecutionCount] bigint NULL,[RuntimeLastExecutionTime] datetimeoffset(7) NULL
        , [AvgDurationUs] decimal(38,4) NULL,[AvgCpuTimeUs] decimal(38,4) NULL
        , [AvgLogicalIoReads] decimal(38,4) NULL,[AvgLogicalIoWrites] decimal(38,4) NULL
        , [QueryHintCount] int NOT NULL,[QueryHintFailureCount] bigint NOT NULL
        , [PersistedFeedbackCount] int NOT NULL,[VariantRelationCount] int NOT NULL
        , [SourceObservedAtUtc] datetime2(3) NOT NULL,[IsCurrent] bit NOT NULL,[IsLastKnown] bit NOT NULL
        , [StatusCode] varchar(40) NOT NULL,[EvidenceLimit] nvarchar(1000) NOT NULL
    );
    CREATE TABLE [#ShowplanAnalysis_FeedbackAndVariants]
    (
          [CandidateId] int NOT NULL,[PlanHandle] varbinary(64) NOT NULL,[RecordOrdinal] bigint NOT NULL
        , [AnalysisObjectId] int NOT NULL,[RecordType] varchar(40) NOT NULL,[FeatureType] varchar(60) NOT NULL
        , [StatementOrdinal] int NULL,[StatementId] int NULL,[NodeId] int NULL
        , [QueryStorePlanId] bigint NULL,[QueryStoreQueryId] bigint NULL,[ParentQueryId] bigint NULL
        , [DispatcherPlanId] bigint NULL,[QueryVariantQueryId] bigint NULL,[QueryVariantId] int NULL
        , [FeatureState] nvarchar(128) NULL,[FeatureData] nvarchar(max) NULL,[FeatureDataToken] varbinary(32) NULL
        , [FeatureDataLength] int NULL,[DataHandlingStatus] varchar(40) NOT NULL,[EvidenceSource] varchar(40) NOT NULL
        , [SourceObservedAtUtc] datetime2(3) NOT NULL,[IsCurrent] bit NULL,[IsLastKnown] bit NULL
        , [IsMeasured] bit NOT NULL,[IsDerived] bit NOT NULL,[StatusCode] varchar(40) NOT NULL
        , [EvidenceLimit] nvarchar(1000) NOT NULL
    );
    CREATE TABLE [#ShowplanAnalysis_Analyses]
    (
          [CandidateId] int NOT NULL PRIMARY KEY
        , [AnalysisJson] nvarchar(max) NULL
    );
    CREATE TABLE [#ShowplanAnalysis_ModuleStatus]
    (
          [ModuleName] sysname NOT NULL,[CollectionTimeUtc] datetime2(3) NOT NULL,[StatusCode] varchar(40) NOT NULL
        , [IsPartial] bit NOT NULL,[CandidateCount] int NOT NULL,[ProcessedPlanCount] int NOT NULL
        , [FindingCount] bigint NOT NULL,[ErrorNumber] int NULL,[ErrorMessage] nvarchar(2048) NULL
    );

    IF @OutputMode NOT IN ('CONSOLE','RAW','TABLE','NONE')
       OR @Mode NOT IN ('GEZIELT','VOLL') OR @Source NOT IN ('AUTO','COMPILE','LAST_ACTUAL')
       OR @Order NOT IN ('CPU_TOTAL','ELAPSED_TOTAL','READS_TOTAL','EXECUTIONS','SPILLS_TOTAL','GRANT_MAX','LAST_EXECUTION')
       OR @MaxAnalyseobjekte<0 OR @MaxZeilen<0 OR @MinExecutionCount<0
       OR @MaxDurationSeconds NOT BETWEEN 1 AND 3600 OR @ParentQueryStatsSnapshot NOT IN (0,1)
       OR @JsonErzeugen NOT IN (0,1)
    BEGIN
        SELECT @StatusCode='INVALID_PARAMETER',@IsPartial=1,@ErrorMessage=N'Ungültiger Modus-, Grenzwert-, Quell- oder Ausgabeparameter.';
    END;
    IF @StatusCode='AVAILABLE' AND @Mode='GEZIELT' AND @PlanHandle IS NULL AND @QueryHash IS NULL AND @QueryPlanHash IS NULL
       AND NULLIF(LTRIM(RTRIM(COALESCE(@DatabaseNames,N''))),N'') IS NULL
       AND @DatabaseNamePattern IS NULL AND @TextPattern IS NULL
    BEGIN
        SELECT @StatusCode='INVALID_PARAMETER',@IsPartial=1,@ErrorMessage=N'GEZIELT benötigt mindestens einen Selektor.';
    END;

    IF @StatusCode='AVAILABLE' AND @TableRequested=1
    BEGIN
        EXEC [monitor].[InternalPrepareResultTables]
              @ResultTablesJson=@ResultTablesJson
            , @AllowedResultNames=N'parameters|planWarnings|optimizerContext|runtimeFeedback|queryStoreContext|feedbackAndVariants|findings'
            , @MappingTable=N'#ShowplanAnalysis_TableMap'
            , @ThrowOnError=1;
        SET @OutputMode='NONE';
    END
    ELSE IF @StatusCode='AVAILABLE' AND @ResultTablesJson IS NOT NULL
    BEGIN
        SELECT @StatusCode='INVALID_PARAMETER',@IsPartial=1,@ErrorMessage=N'@ResultTablesJson ist ausschließlich mit TABLE zulässig.';
    END;
    IF @ConsoleResultRequested=1 SET @OutputMode='NONE';

    DECLARE @TextMode varchar(8),@TextValue nvarchar(4000),@TextFlags varchar(8),@TextValid bit;
    SELECT @TextMode=[PatternMode],@TextValue=[PatternValue],@TextFlags=[RegexFlags],@TextValid=[IsValid]
    FROM [monitor].[TVF_ParsePattern](@TextPattern);
    IF @StatusCode='AVAILABLE' AND @TextValid=0
        SELECT @StatusCode='INVALID_PARAMETER',@IsPartial=1,@ErrorMessage=N'@TextPattern ist ungültig.';
    IF @StatusCode='AVAILABLE' AND @TextMode IN ('REGEX','REGEXI')
       AND (TRY_CONVERT(int,SERVERPROPERTY(N'ProductMajorVersion'))<17
            OR NOT EXISTS(SELECT 1 FROM [sys].[databases] WITH (NOLOCK) WHERE [database_id]=DB_ID() AND [compatibility_level]>=170))
        SELECT @StatusCode='UNAVAILABLE_FEATURE',@IsPartial=1,@ErrorMessage=N'Regex benötigt SQL Server 2025 und Compatibility Level 170.';

    IF @StatusCode='AVAILABLE' AND @PlanHandle IS NULL
    BEGIN
        EXEC [monitor].[USP_PrepareDatabaseCandidates]
              @DatabaseNames=@DatabaseNames
            , @SystemdatenbankenEinbeziehen=@SystemdatenbankenEinbeziehen
            , @DatabaseNamePattern=@DatabaseNamePattern
            , @HighImpactConfirmed=@HighImpactConfirmed
            , @AnalysisClass='PLAN_CACHE_CURRENT'
            , @StatusCode=@StatusCode OUTPUT
            , @ErrorMessage=@ErrorMessage OUTPUT
            , @CrossDatabaseRequested=@CrossDatabaseRequested OUTPUT
            , @CandidateTable=N'#ShowplanAnalysis_DatabaseCandidates'
            , @WarningTable=N'#ShowplanAnalysis_DatabaseCandidateWarnings';
    END;

    IF @StatusCode='AVAILABLE' AND (@Mode='VOLL' OR @Limit>20)
    BEGIN
        EXEC [monitor].[InternalCheckAnalysisPath]
              @AnalysisClass='PLAN_CACHE_DEEP',@HighImpactConfirmed=@HighImpactConfirmed
            , @StatusCode=@StatusCode OUTPUT,@ErrorMessage=@ErrorMessage OUTPUT;
        IF @StatusCode='AVAILABLE'
            EXEC [monitor].[InternalCheckAnalysisPath]
                  @AnalysisClass='SHOWPLAN_XML_DEEP',@HighImpactConfirmed=@HighImpactConfirmed
                , @StatusCode=@StatusCode OUTPUT,@ErrorMessage=@ErrorMessage OUTPUT;
    END;

    IF @StatusCode='AVAILABLE'
    BEGIN TRY
        IF @PlanHandle IS NOT NULL
            INSERT [#ShowplanAnalysis_Candidates]([PlanHandle]) VALUES(@PlanHandle);
        ELSE
        BEGIN
            DECLARE @OrderExpression nvarchar(300)=CASE @Order
                WHEN 'CPU_TOTAL' THEN N'[qs].[TotalWorkerTime]'
                WHEN 'ELAPSED_TOTAL' THEN N'[qs].[TotalElapsedTime]'
                WHEN 'READS_TOTAL' THEN N'[qs].[TotalLogicalReads]'
                WHEN 'EXECUTIONS' THEN N'[qs].[ExecutionCount]'
                WHEN 'SPILLS_TOTAL' THEN N'[qs].[TotalSpills]'
                WHEN 'GRANT_MAX' THEN N'[qs].[MaxGrantKb]'
                WHEN 'LAST_EXECUTION' THEN N'DATEDIFF_BIG(MILLISECOND,''20000101'',[qs].[LastExecutionTime])' END;
            DECLARE @Sql nvarchar(max)=N'
;WITH [FilteredQueryStats] AS
(
    SELECT [qs].*
    FROM '+CASE WHEN @ParentQueryStatsSnapshot=1 THEN N'[#PlanCacheAnalysis_QueryStatsSnapshot]' ELSE N'[sys].[dm_exec_query_stats]' END+N' AS [qs] WITH (NOLOCK) '
                +CASE WHEN @TextMode IS NOT NULL THEN N'OUTER APPLY [sys].[dm_exec_sql_text]([qs].[sql_handle]) AS [st] ' ELSE N'' END+N'
    WHERE [qs].[execution_count]>=@MinExec
      AND (@QH IS NULL OR [qs].[query_hash]=@QH)
      AND (@QPH IS NULL OR [qs].[query_plan_hash]=@QPH) '
                +CASE WHEN @TextMode='LIKE' THEN N'AND [st].[text] COLLATE SQL_Latin1_General_CP1_CS_AS LIKE @TextValue COLLATE SQL_Latin1_General_CP1_CS_AS '
                      WHEN @TextMode IN ('REGEX','REGEXI') THEN N'AND REGEXP_LIKE([st].[text],@TextValue,@TextFlags) ' ELSE N'' END+N'
),
[QueryStatsByPlan] AS
(
    SELECT
          [plan_handle]
        , [ExecutionCount]=SUM([execution_count])
        , [TotalWorkerTime]=SUM([total_worker_time])
        , [TotalElapsedTime]=SUM([total_elapsed_time])
        , [TotalLogicalReads]=SUM([total_logical_reads])
        , [TotalSpills]=SUM([total_spills])
        , [MaxGrantKb]=MAX([max_grant_kb])
        , [LastExecutionTime]=MAX([last_execution_time])
        , [PlanGenerationNum]=MAX([plan_generation_num])
        , [CacheCreationTime]=MIN([creation_time])
    FROM [FilteredQueryStats]
    GROUP BY [plan_handle]
)
INSERT [#ShowplanAnalysis_Candidates]
(
      [PlanHandle],[ExecutionCount],[TotalWorkerTime],[TotalElapsedTime],[TotalLogicalReads]
    , [TotalSpills],[MaxGrantKb],[LastExecutionTime]
    , [DatabaseId],[SetOptions],[CompileUserId],[PlanGenerationNum]
    , [CacheCreationTime],[CacheLastExecutionTime],[CacheObjectType],[CacheObjectClass]
    , [CacheUseCounts],[CacheRefCounts],[CacheSizeBytes],[CachePoolId]
)
SELECT TOP (@TopRows)
      [qs].[plan_handle],[qs].[ExecutionCount],[qs].[TotalWorkerTime]
    , [qs].[TotalElapsedTime],[qs].[TotalLogicalReads],[qs].[TotalSpills]
    , [qs].[MaxGrantKb],[qs].[LastExecutionTime]
    , [pa].[DatabaseId],[pa].[SetOptions],[pa].[CompileUserId]
    , [qs].[PlanGenerationNum],[qs].[CacheCreationTime],[qs].[LastExecutionTime]
    , [cp].[cacheobjtype],[cp].[objtype],[cp].[usecounts],[cp].[refcounts]
    , CONVERT(bigint,[cp].[size_in_bytes]),[cp].[pool_id]
FROM [QueryStatsByPlan] AS [qs]
LEFT JOIN [sys].[dm_exec_cached_plans] AS [cp] WITH (NOLOCK)
  ON [cp].[plan_handle]=[qs].[plan_handle]
OUTER APPLY
(
    SELECT
          MAX(CASE WHEN [attribute]=''dbid'' THEN TRY_CONVERT(int,[value]) END) [DatabaseId]
        , MAX(CASE WHEN [attribute]=''set_options'' THEN TRY_CONVERT(bigint,[value]) END) [SetOptions]
        , MAX(CASE WHEN [attribute]=''user_id'' THEN TRY_CONVERT(int,[value]) END) [CompileUserId]
    FROM [sys].[dm_exec_plan_attributes]([qs].[plan_handle])
) AS [pa]
WHERE EXISTS
(
    SELECT 1
    FROM [#ShowplanAnalysis_DatabaseCandidates] AS [dc]
    WHERE [dc].[DatabaseId]=[pa].[DatabaseId]
)
ORDER BY '+@OrderExpression+N' DESC,[qs].[LastExecutionTime] DESC
OPTION (RECOMPILE,MAXDOP 1);';
            EXEC [sys].[sp_executesql]
                  @Sql
                , N'@TopRows bigint,@MinExec bigint,@QH binary(8),@QPH binary(8),@TextValue nvarchar(4000),@TextFlags varchar(8)'
                , @TopRows=@Limit,@MinExec=@MinExecutionCount,@QH=@QueryHash,@QPH=@QueryPlanHash
                , @TextValue=@TextValue,@TextFlags=@TextFlags;
        END;
        SELECT @CandidateCount=COUNT(*) FROM [#ShowplanAnalysis_Candidates];

        IF @PlanHandle IS NOT NULL
        BEGIN
            BEGIN TRY
                UPDATE [c]
                SET
                      [DatabaseId]=[a].[DatabaseId],[SetOptions]=[a].[SetOptions],[CompileUserId]=[a].[CompileUserId]
                    , [PlanGenerationNum]=[q].[PlanGenerationNum],[CacheCreationTime]=[q].[CacheCreationTime]
                    , [CacheLastExecutionTime]=[q].[CacheLastExecutionTime],[ExecutionCount]=[q].[ExecutionCount]
                    , [CacheObjectType]=[cp].[cacheobjtype],[CacheObjectClass]=[cp].[objtype]
                    , [CacheUseCounts]=[cp].[usecounts],[CacheRefCounts]=[cp].[refcounts]
                    , [CacheSizeBytes]=CONVERT(bigint,[cp].[size_in_bytes]),[CachePoolId]=[cp].[pool_id]
                FROM [#ShowplanAnalysis_Candidates] AS [c]
                LEFT JOIN [sys].[dm_exec_cached_plans] AS [cp] WITH (NOLOCK)
                  ON [cp].[plan_handle]=[c].[PlanHandle]
                OUTER APPLY
                (
                    SELECT
                          MAX([qs].[plan_generation_num]) [PlanGenerationNum]
                        , MIN([qs].[creation_time]) [CacheCreationTime]
                        , MAX([qs].[last_execution_time]) [CacheLastExecutionTime]
                        , SUM([qs].[execution_count]) [ExecutionCount]
                    FROM [sys].[dm_exec_query_stats] AS [qs] WITH (NOLOCK)
                    WHERE [qs].[plan_handle]=[c].[PlanHandle]
                ) AS [q]
                OUTER APPLY
                (
                    SELECT
                          MAX(CASE WHEN [attribute]='dbid' THEN TRY_CONVERT(int,[value]) END) [DatabaseId]
                        , MAX(CASE WHEN [attribute]='set_options' THEN TRY_CONVERT(bigint,[value]) END) [SetOptions]
                        , MAX(CASE WHEN [attribute]='user_id' THEN TRY_CONVERT(int,[value]) END) [CompileUserId]
                    FROM [sys].[dm_exec_plan_attributes]([c].[PlanHandle])
                ) AS [a];
            END TRY
            BEGIN CATCH
                /* Fehler 569 ist der erwartbare Race-Zustand eines inzwischen
                   ungültigen Planhandles. Der Child-Analyzer klassifiziert
                   den Plan selbst weiterhin als PLAN_EVICTED. */
                IF ERROR_NUMBER()<>569
                    THROW;
            END CATCH;
        END;

        INSERT [#ShowplanAnalysis_ExecutionPlanSourceContext]
        (
              [PlanHandle],[SourceCapturedAtUtc],[StatusCode],[DatabaseId],[SetOptions],[CompileUserId]
            , [PlanGenerationNum],[CacheCreationTime],[CacheLastExecutionTime],[ExecutionCount]
            , [CacheObjectType],[CacheObjectClass],[CacheUseCounts],[CacheRefCounts]
            , [CacheSizeBytes],[CachePoolId],[EvidenceLimit]
        )
        SELECT
              [PlanHandle],@Now
            , CASE WHEN [CacheObjectType] IS NULL THEN 'PLAN_CACHE_CONTEXT_UNAVAILABLE' ELSE 'AVAILABLE' END
            , [DatabaseId],[SetOptions],[CompileUserId],[PlanGenerationNum],[CacheCreationTime]
            , [CacheLastExecutionTime],[ExecutionCount],[CacheObjectType],[CacheObjectClass]
            , [CacheUseCounts],[CacheRefCounts],[CacheSizeBytes],[CachePoolId]
            , N'Der Cachekontext stammt aus demselben begrenzten Kandidatensnapshot; er ist flüchtig und nicht transaktional mit dem Plan-XML atomar.'
        FROM [#ShowplanAnalysis_Candidates];
    END TRY
    BEGIN CATCH
        SELECT @StatusCode=CASE WHEN ERROR_NUMBER() IN (229,371,262,297,300,916) THEN 'DENIED_PERMISSION' ELSE 'ERROR_HANDLED' END,
               @IsPartial=1,@ErrorNumber=ERROR_NUMBER(),@ErrorMessage=ERROR_MESSAGE();
    END CATCH;

    DECLARE @CandidateId int,@CurrentPlanHandle varbinary(64),@ChildJson nvarchar(max),@ChildStatus varchar(40),@ChildPartial bit,@ChildError int,@ChildMessage nvarchar(2048),@Started datetime2(3);
    DECLARE [PlanCursor] CURSOR LOCAL FAST_FORWARD FOR
        SELECT [CandidateId],[PlanHandle] FROM [#ShowplanAnalysis_Candidates] ORDER BY [CandidateId];
    IF @StatusCode='AVAILABLE'
    BEGIN
        OPEN [PlanCursor];
        FETCH NEXT FROM [PlanCursor] INTO @CandidateId,@CurrentPlanHandle;
        WHILE @@FETCH_STATUS=0
        BEGIN
            IF SYSUTCDATETIME()>=@Deadline
            BEGIN
                SELECT @StatusCode='PARTIAL',@IsPartial=1,@ErrorMessage=N'Das Zeitbudget wurde erreicht; weitere Pläne wurden nicht analysiert.';
                BREAK;
            END;
            SELECT @Started=SYSUTCDATETIME(),@ChildJson=NULL,@ChildStatus=NULL,@ChildPartial=NULL,@ChildError=NULL,@ChildMessage=NULL;
            BEGIN TRY
                EXEC [monitor].[USP_ExecutionPlanAnalysis]
                      @PlanHandle=@CurrentPlanHandle
                    , @PlanQuelle=@Source
                    , @StatementQueryHash=@QueryHash
                    , @StatementQueryPlanHash=@QueryPlanHash
                    , @AnalyseTiefe=@ChildAnalyseTiefe
                    , @WorkloadProfil=@WorkloadProfil
                    , @MinSchweregrad=@MinSchweregrad
                    , @MitThreadRuntime=@MitThreadRuntime
                    , @MitSqlText=@MitSqlText
                    , @StatistikEvidenzModus=@StatistikEvidenzModus
                    , @HistogrammModus=@HistogrammModus
                    , @MetadatenQuellenmodus=@MetadatenQuellenmodus
                    , @QuellumgebungBestaetigt=@QuellumgebungBestaetigt
                    , @EvidenzDatenschutzModus=@EvidenzDatenschutzModus
                    , @IdentifierDatenschutzModus=@IdentifierDatenschutzModus
                    , @SensitiveDataConfirmed=@SensitiveDataConfirmed
                    , @MaxOperatoren=@ChildMaxRows
                    , @MaxFindings=@ChildMaxRows
                    , @MaxStatistiken=@MaxStatistiken
                    , @MaxHistogrammSchritte=@MaxHistogrammSchritte
                    , @MaxDurationSeconds=@MaxDurationSeconds
                    , @HighImpactConfirmed=@HighImpactConfirmed
                    , @ResultSetArt='NONE'
                    , @JsonErzeugen=1
                    , @Json=@ChildJson OUTPUT
                    , @PrintMeldungen=0
                    , @StatusCodeOut=@ChildStatus OUTPUT
                    , @IsPartialOut=@ChildPartial OUTPUT
                    , @ErrorNumberOut=@ChildError OUTPUT
                    , @ErrorMessageOut=@ChildMessage OUTPUT;

                DECLARE @ChildPlanSource varchar(24)=NULL,@ChildRuntimeScope varchar(32)=NULL,@ChildFindingCount int=0;
                IF ISJSON(@ChildJson)=1
                BEGIN
                    SELECT
                          @ChildPlanSource=JSON_VALUE(@ChildJson,N'$.meta.planSource')
                        , @ChildRuntimeScope=JSON_VALUE(@ChildJson,N'$.meta.runtimeCounterScope')
                        , @ChildFindingCount=(SELECT COUNT(*) FROM OPENJSON(@ChildJson,N'$.findings'));
                END;

                INSERT [#ShowplanAnalysis_PlanStatus]
                SELECT @CandidateId,@CurrentPlanHandle,COALESCE(@ChildStatus,'STATUS_UNAVAILABLE'),COALESCE(@ChildPartial,1),
                       @ChildPlanSource,@ChildRuntimeScope,@ChildFindingCount,
                       DATEDIFF_BIG(MILLISECOND,@Started,SYSUTCDATETIME()),@ChildError,@ChildMessage;
                INSERT [#ShowplanAnalysis_Analyses] VALUES(@CandidateId,CASE WHEN ISJSON(@ChildJson)=1 THEN @ChildJson END);

                IF ISJSON(@ChildJson)=1
                BEGIN
                    INSERT [#ShowplanAnalysis_Findings]
                    (
                          [CandidateId],[PlanHandle],[FindingOrdinal],[FindingCode],[Category],[Severity],[Confidence],[EvidenceLevel]
                        , [StatementOrdinal],[StatementId],[NodeId],[PhysicalOp],[LogicalOp],[MetricName],[MetricValue],[MetricUnit]
                        , [ThresholdValue],[ThresholdSource],[WorkloadProfile],[Summary],[Evidence],[EvidenceLimit],[CounterEvidence],[RecommendedNextCheck]
                    )
                    SELECT @CandidateId,@CurrentPlanHandle,[FindingOrdinal],[FindingCode],[Category],[Severity],[Confidence],[EvidenceLevel]
                         , [StatementOrdinal],[StatementId],[NodeId],[PhysicalOp],[LogicalOp],[MetricName],[MetricValue],[MetricUnit]
                         , [ThresholdValue],[ThresholdSource],[WorkloadProfile],[Summary],[Evidence],[EvidenceLimit],[CounterEvidence],[RecommendedNextCheck]
                    FROM OPENJSON(@ChildJson,N'$.findings')
                    WITH
                    (
                          [FindingOrdinal] bigint N'$.FindingOrdinal',[FindingCode] varchar(100) N'$.FindingCode'
                        , [Category] varchar(40) N'$.Category',[Severity] varchar(16) N'$.Severity'
                        , [Confidence] varchar(32) N'$.Confidence',[EvidenceLevel] varchar(40) N'$.EvidenceLevel'
                        , [StatementOrdinal] int N'$.StatementOrdinal',[StatementId] int N'$.StatementId',[NodeId] int N'$.NodeId'
                        , [PhysicalOp] nvarchar(128) N'$.PhysicalOp',[LogicalOp] nvarchar(128) N'$.LogicalOp'
                        , [MetricName] varchar(80) N'$.MetricName',[MetricValue] decimal(38,4) N'$.MetricValue'
                        , [MetricUnit] nvarchar(40) N'$.MetricUnit',[ThresholdValue] decimal(38,4) N'$.ThresholdValue'
                        , [ThresholdSource] varchar(80) N'$.ThresholdSource',[WorkloadProfile] varchar(32) N'$.WorkloadProfile'
                        , [Summary] nvarchar(1000) N'$.Summary',[Evidence] nvarchar(2000) N'$.Evidence'
                        , [EvidenceLimit] nvarchar(2000) N'$.EvidenceLimit',[CounterEvidence] nvarchar(1000) N'$.CounterEvidence'
                        , [RecommendedNextCheck] nvarchar(1000) N'$.RecommendedNextCheck'
                    );

                    INSERT [#ShowplanAnalysis_Parameters]
                    (
                          [CandidateId],[PlanHandle],[SessionId],[RequestId]
                        , [StatementOrdinal],[StatementId],[StatementQueryHash],[StatementQueryPlanHash]
                        , [QueryStoreDatabaseName],[QueryStorePlanId],[PlanDocumentHash]
                        , [EvidenceKind],[ParameterName],[ParameterDataType]
                        , [CompiledValuePresent],[RuntimeValuePresent]
                        , [CompiledValueIsSqlNull],[RuntimeValueIsSqlNull]
                        , [CompiledValue],[RuntimeValue],[CompiledValueToken],[RuntimeValueToken]
                        , [CompiledValueLength],[RuntimeValueLength]
                        , [CompiledValueStatus],[RuntimeValueStatus],[ValueStatus]
                        , [ValueHandlingStatus],[ValueSource]
                        , [SourceObservedAtUtc],[ValueCapturedAtUtc]
                        , [IsCurrentExecution],[IsLastKnownExecution],[IsComplete],[EvidenceLimit]
                    )
                    SELECT
                          @CandidateId,@CurrentPlanHandle,[SessionId],[RequestId]
                        , [StatementOrdinal],[StatementId],[StatementQueryHash],[StatementQueryPlanHash]
                        , [QueryStoreDatabaseName],[QueryStorePlanId],[PlanDocumentHash]
                        , [EvidenceKind],[ParameterName],[ParameterDataType]
                        , [CompiledValuePresent],[RuntimeValuePresent]
                        , [CompiledValueIsSqlNull],[RuntimeValueIsSqlNull]
                        , [CompiledValue],[RuntimeValue],[CompiledValueToken],[RuntimeValueToken]
                        , [CompiledValueLength],[RuntimeValueLength]
                        , [CompiledValueStatus],[RuntimeValueStatus],[ValueStatus]
                        , [ValueHandlingStatus],[ValueSource]
                        , [SourceObservedAtUtc],[ValueCapturedAtUtc]
                        , [IsCurrentExecution],[IsLastKnownExecution],[IsComplete],[EvidenceLimit]
                    FROM OPENJSON(@ChildJson,N'$.parameters')
                    WITH
                    (
                          [SessionId] smallint N'$.SessionId'
                        , [RequestId] int N'$.RequestId'
                        , [StatementOrdinal] int N'$.StatementOrdinal'
                        , [StatementId] int N'$.StatementId'
                        , [StatementQueryHash] nvarchar(130) N'$.StatementQueryHash'
                        , [StatementQueryPlanHash] nvarchar(130) N'$.StatementQueryPlanHash'
                        , [QueryStoreDatabaseName] sysname N'$.QueryStoreDatabaseName'
                        , [QueryStorePlanId] bigint N'$.QueryStorePlanId'
                        , [PlanDocumentHash] nvarchar(66) N'$.PlanDocumentHash'
                        , [EvidenceKind] varchar(24) N'$.EvidenceKind'
                        , [ParameterName] nvarchar(256) N'$.ParameterName'
                        , [ParameterDataType] nvarchar(256) N'$.ParameterDataType'
                        , [CompiledValuePresent] bit N'$.CompiledValuePresent'
                        , [RuntimeValuePresent] bit N'$.RuntimeValuePresent'
                        , [CompiledValueIsSqlNull] bit N'$.CompiledValueIsSqlNull'
                        , [RuntimeValueIsSqlNull] bit N'$.RuntimeValueIsSqlNull'
                        , [CompiledValue] nvarchar(4000) N'$.CompiledValue'
                        , [RuntimeValue] nvarchar(4000) N'$.RuntimeValue'
                        , [CompiledValueToken] nvarchar(66) N'$.CompiledValueToken'
                        , [RuntimeValueToken] nvarchar(66) N'$.RuntimeValueToken'
                        , [CompiledValueLength] int N'$.CompiledValueLength'
                        , [RuntimeValueLength] int N'$.RuntimeValueLength'
                        , [CompiledValueStatus] varchar(40) N'$.CompiledValueStatus'
                        , [RuntimeValueStatus] varchar(40) N'$.RuntimeValueStatus'
                        , [ValueStatus] varchar(40) N'$.ValueStatus'
                        , [ValueHandlingStatus] varchar(40) N'$.ValueHandlingStatus'
                        , [ValueSource] varchar(40) N'$.ValueSource'
                        , [SourceObservedAtUtc] datetime2(3) N'$.SourceObservedAtUtc'
                        , [ValueCapturedAtUtc] datetime2(3) N'$.ValueCapturedAtUtc'
                        , [IsCurrentExecution] bit N'$.IsCurrentExecution'
                        , [IsLastKnownExecution] bit N'$.IsLastKnownExecution'
                        , [IsComplete] bit N'$.IsComplete'
                        , [EvidenceLimit] nvarchar(1000) N'$.EvidenceLimit'
                    );

                    INSERT [#ShowplanAnalysis_PlanWarnings]
                    SELECT
                          @CandidateId,@CurrentPlanHandle,[WarningOrdinal],[AnalysisObjectId]
                        , [StatementOrdinal],[StatementId],[NodeId],[WarningCode],[WarningCategory]
                        , [Severity],[EvidenceKind],[EvidenceSource],[PlanSource],[SourceObservedAtUtc]
                        , [IsCurrent],[IsLastKnown],[IsMeasured],[IsInferred],[MetricName],[MetricValue]
                        , [MetricUnit],[Detail],[FalsePositiveGuard],[StatusCode]
                    FROM OPENJSON(@ChildJson,N'$.planWarnings')
                    WITH
                    (
                          [WarningOrdinal] bigint N'$.WarningOrdinal',[AnalysisObjectId] int N'$.AnalysisObjectId'
                        , [StatementOrdinal] int N'$.StatementOrdinal',[StatementId] int N'$.StatementId',[NodeId] int N'$.NodeId'
                        , [WarningCode] varchar(100) N'$.WarningCode',[WarningCategory] varchar(40) N'$.WarningCategory'
                        , [Severity] varchar(16) N'$.Severity',[EvidenceKind] varchar(40) N'$.EvidenceKind'
                        , [EvidenceSource] varchar(40) N'$.EvidenceSource',[PlanSource] varchar(24) N'$.PlanSource'
                        , [SourceObservedAtUtc] datetime2(3) N'$.SourceObservedAtUtc'
                        , [IsCurrent] bit N'$.IsCurrent',[IsLastKnown] bit N'$.IsLastKnown'
                        , [IsMeasured] bit N'$.IsMeasured',[IsInferred] bit N'$.IsInferred'
                        , [MetricName] varchar(80) N'$.MetricName',[MetricValue] decimal(38,4) N'$.MetricValue'
                        , [MetricUnit] nvarchar(40) N'$.MetricUnit',[Detail] nvarchar(2000) N'$.Detail'
                        , [FalsePositiveGuard] nvarchar(2000) N'$.FalsePositiveGuard',[StatusCode] varchar(40) N'$.StatusCode'
                    );

                    INSERT [#ShowplanAnalysis_OptimizerContext]
                    SELECT
                          @CandidateId,@CurrentPlanHandle,[AnalysisObjectId],[StatementOrdinal],[StatementId]
                        , [PlanSource],[RuntimeCounterScope],[SourceObservedAtUtc],[IsCurrent],[IsLastKnown]
                        , [OptimizationLevel],[EarlyAbortReason],[CardinalityEstimationModelVersion]
                        , [StatementSubTreeCost],[StatementEstimatedRows],[CompileTimeMs],[CompileCpuMs],[CompileMemoryKb]
                        , [RetrievedFromCache],[NonParallelPlanReason],[PlanDegreeOfParallelism]
                        , [PlanGenerationNum],[CacheCreationTime],[CacheLastExecutionTime],[CacheExecutionCount]
                        , [CacheObjectType],[CacheObjectClass],[CacheUseCounts],[CacheRefCounts],[CacheSizeBytes],[CachePoolId]
                        , [SetOptions],[CompileUserId],[DatabaseId],[EvidenceMeasurement],[StatusCode],[FalsePositiveGuard]
                    FROM OPENJSON(@ChildJson,N'$.optimizerContext')
                    WITH
                    (
                          [AnalysisObjectId] int N'$.AnalysisObjectId',[StatementOrdinal] int N'$.StatementOrdinal'
                        , [StatementId] int N'$.StatementId',[PlanSource] varchar(24) N'$.PlanSource'
                        , [RuntimeCounterScope] varchar(32) N'$.RuntimeCounterScope'
                        , [SourceObservedAtUtc] datetime2(3) N'$.SourceObservedAtUtc'
                        , [IsCurrent] bit N'$.IsCurrent',[IsLastKnown] bit N'$.IsLastKnown'
                        , [OptimizationLevel] nvarchar(128) N'$.OptimizationLevel',[EarlyAbortReason] nvarchar(256) N'$.EarlyAbortReason'
                        , [CardinalityEstimationModelVersion] int N'$.CardinalityEstimationModelVersion'
                        , [StatementSubTreeCost] decimal(38,8) N'$.StatementSubTreeCost'
                        , [StatementEstimatedRows] decimal(38,4) N'$.StatementEstimatedRows'
                        , [CompileTimeMs] bigint N'$.CompileTimeMs',[CompileCpuMs] bigint N'$.CompileCpuMs'
                        , [CompileMemoryKb] bigint N'$.CompileMemoryKb',[RetrievedFromCache] bit N'$.RetrievedFromCache'
                        , [NonParallelPlanReason] nvarchar(256) N'$.NonParallelPlanReason'
                        , [PlanDegreeOfParallelism] int N'$.PlanDegreeOfParallelism'
                        , [PlanGenerationNum] bigint N'$.PlanGenerationNum',[CacheCreationTime] datetime N'$.CacheCreationTime'
                        , [CacheLastExecutionTime] datetime N'$.CacheLastExecutionTime',[CacheExecutionCount] bigint N'$.CacheExecutionCount'
                        , [CacheObjectType] nvarchar(34) N'$.CacheObjectType',[CacheObjectClass] nvarchar(16) N'$.CacheObjectClass'
                        , [CacheUseCounts] int N'$.CacheUseCounts',[CacheRefCounts] int N'$.CacheRefCounts'
                        , [CacheSizeBytes] bigint N'$.CacheSizeBytes',[CachePoolId] int N'$.CachePoolId'
                        , [SetOptions] bigint N'$.SetOptions',[CompileUserId] int N'$.CompileUserId',[DatabaseId] int N'$.DatabaseId'
                        , [EvidenceMeasurement] varchar(40) N'$.EvidenceMeasurement',[StatusCode] varchar(40) N'$.StatusCode'
                        , [FalsePositiveGuard] nvarchar(1000) N'$.FalsePositiveGuard'
                    );

                    INSERT [#ShowplanAnalysis_RuntimeFeedback]
                    SELECT
                          @CandidateId,@CurrentPlanHandle,[FeedbackOrdinal],[AnalysisObjectId]
                        , [StatementOrdinal],[StatementId],[NodeId],[FeedbackType],[FeedbackState]
                        , [MetricName],[ObservedValue],[BaselineValue],[DeltaRatio],[MetricUnit]
                        , [RuntimeCounterScope],[EvidenceSource],[SourceObservedAtUtc]
                        , [IsCurrent],[IsLastKnown],[IsMeasured],[IsDerived],[StatusCode],[EvidenceLimit]
                    FROM OPENJSON(@ChildJson,N'$.runtimeFeedback')
                    WITH
                    (
                          [FeedbackOrdinal] bigint N'$.FeedbackOrdinal',[AnalysisObjectId] int N'$.AnalysisObjectId'
                        , [StatementOrdinal] int N'$.StatementOrdinal',[StatementId] int N'$.StatementId',[NodeId] int N'$.NodeId'
                        , [FeedbackType] varchar(40) N'$.FeedbackType',[FeedbackState] nvarchar(128) N'$.FeedbackState'
                        , [MetricName] varchar(80) N'$.MetricName',[ObservedValue] decimal(38,4) N'$.ObservedValue'
                        , [BaselineValue] decimal(38,4) N'$.BaselineValue',[DeltaRatio] decimal(38,8) N'$.DeltaRatio'
                        , [MetricUnit] nvarchar(40) N'$.MetricUnit',[RuntimeCounterScope] varchar(32) N'$.RuntimeCounterScope'
                        , [EvidenceSource] varchar(40) N'$.EvidenceSource',[SourceObservedAtUtc] datetime2(3) N'$.SourceObservedAtUtc'
                        , [IsCurrent] bit N'$.IsCurrent',[IsLastKnown] bit N'$.IsLastKnown'
                        , [IsMeasured] bit N'$.IsMeasured',[IsDerived] bit N'$.IsDerived'
                        , [StatusCode] varchar(40) N'$.StatusCode',[EvidenceLimit] nvarchar(1000) N'$.EvidenceLimit'
                    );

                    INSERT [#ShowplanAnalysis_QueryStoreContext]
                    SELECT
                          @CandidateId,@CurrentPlanHandle,[AnalysisObjectId],[QueryStoreDatabaseName]
                        , [QueryStorePlanId],[QueryStoreQueryId],[PlanGroupId],[EngineVersion],[CompatibilityLevel]
                        , [QueryPlanHash],[IsTrivialPlan],[IsParallelPlan],[IsForcedPlan],[PlanForcingTypeDesc]
                        , [ForceFailureCount],[LastForceFailureReason],[LastForceFailureReasonDesc]
                        , [CountCompiles],[InitialCompileStartTime],[LastCompileStartTime],[LastExecutionTime]
                        , [AvgCompileDurationUs],[LastCompileDurationUs],[ContextSettingsId],[ObjectId],[QueryHash]
                        , [QueryParameterizationTypeDesc],[AvgOptimizeDurationUs],[AvgCompileMemoryKb]
                        , [HasCompileReplayScript],[IsOptimizedPlanForcingDisabled],[PlanType],[PlanTypeDesc]
                        , [RuntimeExecutionCount],[RuntimeLastExecutionTime],[AvgDurationUs],[AvgCpuTimeUs]
                        , [AvgLogicalIoReads],[AvgLogicalIoWrites],[QueryHintCount],[QueryHintFailureCount]
                        , [PersistedFeedbackCount],[VariantRelationCount],[SourceObservedAtUtc]
                        , [IsCurrent],[IsLastKnown],[StatusCode],[EvidenceLimit]
                    FROM OPENJSON(@ChildJson,N'$.queryStoreContext')
                    WITH
                    (
                          [AnalysisObjectId] int N'$.AnalysisObjectId',[QueryStoreDatabaseName] sysname N'$.QueryStoreDatabaseName'
                        , [QueryStorePlanId] bigint N'$.QueryStorePlanId',[QueryStoreQueryId] bigint N'$.QueryStoreQueryId'
                        , [PlanGroupId] bigint N'$.PlanGroupId',[EngineVersion] nvarchar(32) N'$.EngineVersion'
                        , [CompatibilityLevel] smallint N'$.CompatibilityLevel',[QueryPlanHash] binary(8) N'$.QueryPlanHash'
                        , [IsTrivialPlan] bit N'$.IsTrivialPlan',[IsParallelPlan] bit N'$.IsParallelPlan'
                        , [IsForcedPlan] bit N'$.IsForcedPlan',[PlanForcingTypeDesc] nvarchar(60) N'$.PlanForcingTypeDesc'
                        , [ForceFailureCount] bigint N'$.ForceFailureCount',[LastForceFailureReason] int N'$.LastForceFailureReason'
                        , [LastForceFailureReasonDesc] nvarchar(128) N'$.LastForceFailureReasonDesc'
                        , [CountCompiles] bigint N'$.CountCompiles',[InitialCompileStartTime] datetimeoffset(7) N'$.InitialCompileStartTime'
                        , [LastCompileStartTime] datetimeoffset(7) N'$.LastCompileStartTime'
                        , [LastExecutionTime] datetimeoffset(7) N'$.LastExecutionTime'
                        , [AvgCompileDurationUs] float N'$.AvgCompileDurationUs',[LastCompileDurationUs] bigint N'$.LastCompileDurationUs'
                        , [ContextSettingsId] bigint N'$.ContextSettingsId',[ObjectId] bigint N'$.ObjectId'
                        , [QueryHash] binary(8) N'$.QueryHash'
                        , [QueryParameterizationTypeDesc] nvarchar(60) N'$.QueryParameterizationTypeDesc'
                        , [AvgOptimizeDurationUs] float N'$.AvgOptimizeDurationUs',[AvgCompileMemoryKb] float N'$.AvgCompileMemoryKb'
                        , [HasCompileReplayScript] bit N'$.HasCompileReplayScript'
                        , [IsOptimizedPlanForcingDisabled] bit N'$.IsOptimizedPlanForcingDisabled'
                        , [PlanType] int N'$.PlanType',[PlanTypeDesc] nvarchar(120) N'$.PlanTypeDesc'
                        , [RuntimeExecutionCount] bigint N'$.RuntimeExecutionCount'
                        , [RuntimeLastExecutionTime] datetimeoffset(7) N'$.RuntimeLastExecutionTime'
                        , [AvgDurationUs] decimal(38,4) N'$.AvgDurationUs',[AvgCpuTimeUs] decimal(38,4) N'$.AvgCpuTimeUs'
                        , [AvgLogicalIoReads] decimal(38,4) N'$.AvgLogicalIoReads'
                        , [AvgLogicalIoWrites] decimal(38,4) N'$.AvgLogicalIoWrites'
                        , [QueryHintCount] int N'$.QueryHintCount',[QueryHintFailureCount] bigint N'$.QueryHintFailureCount'
                        , [PersistedFeedbackCount] int N'$.PersistedFeedbackCount',[VariantRelationCount] int N'$.VariantRelationCount'
                        , [SourceObservedAtUtc] datetime2(3) N'$.SourceObservedAtUtc'
                        , [IsCurrent] bit N'$.IsCurrent',[IsLastKnown] bit N'$.IsLastKnown'
                        , [StatusCode] varchar(40) N'$.StatusCode',[EvidenceLimit] nvarchar(1000) N'$.EvidenceLimit'
                    );

                    INSERT [#ShowplanAnalysis_FeedbackAndVariants]
                    SELECT
                          @CandidateId,@CurrentPlanHandle,[RecordOrdinal],[AnalysisObjectId],[RecordType],[FeatureType]
                        , [StatementOrdinal],[StatementId],[NodeId],[QueryStorePlanId],[QueryStoreQueryId]
                        , [ParentQueryId],[DispatcherPlanId],[QueryVariantQueryId],[QueryVariantId]
                        , [FeatureState],[FeatureData],[FeatureDataToken],[FeatureDataLength],[DataHandlingStatus]
                        , [EvidenceSource],[SourceObservedAtUtc],[IsCurrent],[IsLastKnown]
                        , [IsMeasured],[IsDerived],[StatusCode],[EvidenceLimit]
                    FROM OPENJSON(@ChildJson,N'$.feedbackAndVariants')
                    WITH
                    (
                          [RecordOrdinal] bigint N'$.RecordOrdinal',[AnalysisObjectId] int N'$.AnalysisObjectId'
                        , [RecordType] varchar(40) N'$.RecordType',[FeatureType] varchar(60) N'$.FeatureType'
                        , [StatementOrdinal] int N'$.StatementOrdinal',[StatementId] int N'$.StatementId',[NodeId] int N'$.NodeId'
                        , [QueryStorePlanId] bigint N'$.QueryStorePlanId',[QueryStoreQueryId] bigint N'$.QueryStoreQueryId'
                        , [ParentQueryId] bigint N'$.ParentQueryId',[DispatcherPlanId] bigint N'$.DispatcherPlanId'
                        , [QueryVariantQueryId] bigint N'$.QueryVariantQueryId',[QueryVariantId] int N'$.QueryVariantId'
                        , [FeatureState] nvarchar(128) N'$.FeatureState',[FeatureData] nvarchar(max) N'$.FeatureData'
                        , [FeatureDataToken] varbinary(32) N'$.FeatureDataToken',[FeatureDataLength] int N'$.FeatureDataLength'
                        , [DataHandlingStatus] varchar(40) N'$.DataHandlingStatus',[EvidenceSource] varchar(40) N'$.EvidenceSource'
                        , [SourceObservedAtUtc] datetime2(3) N'$.SourceObservedAtUtc'
                        , [IsCurrent] bit N'$.IsCurrent',[IsLastKnown] bit N'$.IsLastKnown'
                        , [IsMeasured] bit N'$.IsMeasured',[IsDerived] bit N'$.IsDerived'
                        , [StatusCode] varchar(40) N'$.StatusCode',[EvidenceLimit] nvarchar(1000) N'$.EvidenceLimit'
                    );
                END;
                SET @ProcessedPlans+=1;
                IF COALESCE(@ChildStatus,'STATUS_UNAVAILABLE')<>'AVAILABLE'
                BEGIN
                    SET @IsPartial=1;
                    IF @StatusCode='AVAILABLE' SET @StatusCode='PARTIAL';
                END;
            END TRY
            BEGIN CATCH
                INSERT [#ShowplanAnalysis_PlanStatus]
                VALUES(@CandidateId,@CurrentPlanHandle,'ERROR_HANDLED',1,NULL,NULL,0,DATEDIFF_BIG(MILLISECOND,@Started,SYSUTCDATETIME()),ERROR_NUMBER(),ERROR_MESSAGE());
                SET @IsPartial=1;
                IF @StatusCode='AVAILABLE' SET @StatusCode='PARTIAL';
                IF @ErrorNumber IS NULL BEGIN SET @ErrorNumber=ERROR_NUMBER(); SET @ErrorMessage=ERROR_MESSAGE(); END;
            END CATCH;
            IF (SELECT COUNT_BIG(*) FROM [#ShowplanAnalysis_Findings])>=@ResultLimit
            BEGIN
                SELECT @StatusCode='PARTIAL',@IsPartial=1,@ErrorMessage=N'Das Findinglimit wurde erreicht; weitere Pläne wurden nicht analysiert.';
                BREAK;
            END;
            FETCH NEXT FROM [PlanCursor] INTO @CandidateId,@CurrentPlanHandle;
        END;
        CLOSE [PlanCursor];DEALLOCATE [PlanCursor];
    END;

    IF @IsPartial=1 AND @StatusCode='AVAILABLE' SET @StatusCode='PARTIAL';
    INSERT [#ShowplanAnalysis_ModuleStatus]
    SELECT N'USP_ShowplanAnalysis',@Now,@StatusCode,@IsPartial,@CandidateCount,@ProcessedPlans,
           (SELECT COUNT_BIG(*) FROM [#ShowplanAnalysis_Findings]),@ErrorNumber,@ErrorMessage;

    IF @JsonErzeugen=1
    BEGIN
        DECLARE @Meta nvarchar(max)=(SELECT N'ShowplanAnalysis' [resultName],4 [schemaVersion],@Now [generatedAtUtc],@StatusCode [statusCode],@IsPartial [isPartial],@CandidateCount [candidateCount],@ProcessedPlans [processedPlanCount] FOR JSON PATH,WITHOUT_ARRAY_WRAPPER,INCLUDE_NULL_VALUES);
        DECLARE @PlanStatusJson nvarchar(max)=(SELECT * FROM [#ShowplanAnalysis_PlanStatus] ORDER BY [CandidateId] FOR JSON PATH,INCLUDE_NULL_VALUES);
        DECLARE @ParametersJson nvarchar(max)=(SELECT TOP (@ResultLimit) * FROM [#ShowplanAnalysis_Parameters] ORDER BY [CandidateId],[StatementOrdinal],[EvidenceKind],[ParameterName] FOR JSON PATH,INCLUDE_NULL_VALUES);
        DECLARE @PlanWarningsJson nvarchar(max)=(SELECT TOP (@ResultLimit) * FROM [#ShowplanAnalysis_PlanWarnings] ORDER BY [CandidateId],[WarningOrdinal] FOR JSON PATH,INCLUDE_NULL_VALUES);
        DECLARE @OptimizerContextJson nvarchar(max)=(SELECT TOP (@ResultLimit) * FROM [#ShowplanAnalysis_OptimizerContext] ORDER BY [CandidateId],[StatementOrdinal] FOR JSON PATH,INCLUDE_NULL_VALUES);
        DECLARE @RuntimeFeedbackJson nvarchar(max)=(SELECT TOP (@ResultLimit) * FROM [#ShowplanAnalysis_RuntimeFeedback] ORDER BY [CandidateId],[FeedbackOrdinal] FOR JSON PATH,INCLUDE_NULL_VALUES);
        DECLARE @QueryStoreContextJson nvarchar(max)=(SELECT TOP (@ResultLimit) * FROM [#ShowplanAnalysis_QueryStoreContext] ORDER BY [CandidateId],[QueryStorePlanId] FOR JSON PATH,INCLUDE_NULL_VALUES);
        DECLARE @FeedbackAndVariantsJson nvarchar(max)=(SELECT TOP (@ResultLimit) * FROM [#ShowplanAnalysis_FeedbackAndVariants] ORDER BY [CandidateId],[RecordOrdinal] FOR JSON PATH,INCLUDE_NULL_VALUES);
        DECLARE @FindingsJson nvarchar(max)=(SELECT TOP (@ResultLimit) * FROM [#ShowplanAnalysis_Findings] ORDER BY CASE [Severity] WHEN 'CRITICAL' THEN 1 WHEN 'HIGH' THEN 2 WHEN 'MEDIUM' THEN 3 WHEN 'LOW' THEN 4 ELSE 5 END,[CandidateId],[FindingOrdinal] FOR JSON PATH,INCLUDE_NULL_VALUES);
        DECLARE @AnalysesJson nvarchar(max)=N'[]';
        SELECT @AnalysesJson=COALESCE(N'['+STRING_AGG(CONVERT(nvarchar(max),[AnalysisJson]),N',') WITHIN GROUP (ORDER BY [CandidateId])+N']',N'[]')
        FROM [#ShowplanAnalysis_Analyses] WHERE ISJSON([AnalysisJson])=1;
        SET @Json=CONCAT(N'{"meta":',COALESCE(@Meta,N'{}'),N',"planStatus":',COALESCE(@PlanStatusJson,N'[]'),N',"parameters":',COALESCE(@ParametersJson,N'[]'),N',"planWarnings":',COALESCE(@PlanWarningsJson,N'[]'),N',"optimizerContext":',COALESCE(@OptimizerContextJson,N'[]'),N',"runtimeFeedback":',COALESCE(@RuntimeFeedbackJson,N'[]'),N',"queryStoreContext":',COALESCE(@QueryStoreContextJson,N'[]'),N',"feedbackAndVariants":',COALESCE(@FeedbackAndVariantsJson,N'[]'),N',"findings":',COALESCE(@FindingsJson,N'[]'),N',"analyses":',COALESCE(@AnalysesJson,N'[]'),N'}');
    END;

    IF @OutputMode='RAW'
    BEGIN
        SELECT * FROM [#ShowplanAnalysis_ModuleStatus];
        SELECT * FROM [#ShowplanAnalysis_PlanStatus] ORDER BY [CandidateId];
        SELECT TOP (@ResultLimit) * FROM [#ShowplanAnalysis_Parameters]
        ORDER BY [CandidateId],[StatementOrdinal],[EvidenceKind],[ParameterName];
        SELECT TOP (@ResultLimit) * FROM [#ShowplanAnalysis_PlanWarnings]
        ORDER BY [CandidateId],[WarningOrdinal];
        SELECT TOP (@ResultLimit) * FROM [#ShowplanAnalysis_OptimizerContext]
        ORDER BY [CandidateId],[StatementOrdinal];
        SELECT TOP (@ResultLimit) * FROM [#ShowplanAnalysis_RuntimeFeedback]
        ORDER BY [CandidateId],[FeedbackOrdinal];
        SELECT TOP (@ResultLimit) * FROM [#ShowplanAnalysis_QueryStoreContext]
        ORDER BY [CandidateId],[QueryStorePlanId];
        SELECT TOP (@ResultLimit) * FROM [#ShowplanAnalysis_FeedbackAndVariants]
        ORDER BY [CandidateId],[RecordOrdinal];
        SELECT TOP (@ResultLimit) * FROM [#ShowplanAnalysis_Findings]
        ORDER BY CASE [Severity] WHEN 'CRITICAL' THEN 1 WHEN 'HIGH' THEN 2 WHEN 'MEDIUM' THEN 3 WHEN 'LOW' THEN 4 ELSE 5 END,[CandidateId],[FindingOrdinal];
    END;
    IF @ConsoleResultRequested=1
        EXEC [monitor].[InternalEmitConsoleResult]
              @SourceTable=N'#ShowplanAnalysis_Findings',@ResultLabel=N'Showplan Finding'
            , @EmptyMessage=N'Keine Showplan-Findings im gewählten Scope'
            , @StatusCode=@StatusCode,@StatusMessage=@ErrorMessage;
    IF @TableRequested=1
    BEGIN
        DECLARE @ResultName sysname,@TargetTable sysname,@SourceTable sysname;
        DECLARE [ShowplanOutputCursor] CURSOR LOCAL FAST_FORWARD FOR
            SELECT [ResultName],[TargetTable]
            FROM [#ShowplanAnalysis_TableMap]
            ORDER BY [ResultName];
        OPEN [ShowplanOutputCursor];
        FETCH NEXT FROM [ShowplanOutputCursor] INTO @ResultName,@TargetTable;
        WHILE @@FETCH_STATUS=0
        BEGIN
            SET @SourceTable=CASE @ResultName
                WHEN N'parameters' THEN N'#ShowplanAnalysis_Parameters'
                WHEN N'planWarnings' THEN N'#ShowplanAnalysis_PlanWarnings'
                WHEN N'optimizerContext' THEN N'#ShowplanAnalysis_OptimizerContext'
                WHEN N'runtimeFeedback' THEN N'#ShowplanAnalysis_RuntimeFeedback'
                WHEN N'queryStoreContext' THEN N'#ShowplanAnalysis_QueryStoreContext'
                WHEN N'feedbackAndVariants' THEN N'#ShowplanAnalysis_FeedbackAndVariants'
                WHEN N'findings' THEN N'#ShowplanAnalysis_Findings' END;
            EXEC [monitor].[InternalWriteResultTable]
                  @SourceTable=@SourceTable,@TargetTable=@TargetTable,@ThrowOnError=1;
            FETCH NEXT FROM [ShowplanOutputCursor] INTO @ResultName,@TargetTable;
        END;
        CLOSE [ShowplanOutputCursor];
        DEALLOCATE [ShowplanOutputCursor];
    END;
    IF @PrintMeldungen=1 AND @StatusCode<>'AVAILABLE'
    BEGIN
        DECLARE @Message nvarchar(2048)=FORMATMESSAGE(N'WARNUNG USP_ShowplanAnalysis: %s - %s',@StatusCode,COALESCE(@ErrorMessage,N'partielle Analyse'));
        RAISERROR(N'%s',10,1,@Message) WITH NOWAIT;
    END;
END;
GO
-- END SOURCE: Code/04_PlanCache/050_USP_ShowplanAnalysis.sql

-- BEGIN SOURCE: Code/04_PlanCache/060_USP_PlanCacheAnalysis.sql
/*
===============================================================================
Objekt       : monitor.USP_PlanCacheAnalysis
Version      : 2.1.0
Stand        : 2026-07-19
Zweck        : Orchestriert Plan-Cache- und Showplan-Module mit einheitlichen
               Listen-, Pattern-, Limit- und Ausgabeparametern.
Änderungen   : 2.1.0 - dm_exec_query_stats bei mehreren Consumern einmalig
                         laufgebunden materialisiert und wiederverwendet.
               2.0.1 - IF/TRY/CATCH-Blöcke syntaktisch eindeutig strukturiert.
===============================================================================
*/
CREATE OR ALTER PROCEDURE [monitor].[USP_PlanCacheAnalysis]
      @MitQueryStats                    bit            = 1
    , @MitQueryHashAnalysis             bit            = 0
    , @MitPlanCacheHealth               bit            = 0
    , @MitShowplanAnalysis              bit            = 0
    , @DatabaseNames                    nvarchar(max)  = NULL
    , @SystemdatenbankenEinbeziehen     bit            = 0
    , @DatabaseNamePattern              nvarchar(4000) = NULL
    , @HighImpactConfirmed              bit            = 0
    , @QueryHash                        binary(8)      = NULL
    , @QueryPlanHash                    binary(8)      = NULL
    , @PlanHandle                       varbinary(64)  = NULL
    , @TextPattern                      nvarchar(4000) = NULL
    , @Sortierung                       varchar(32)    = 'CPU_TOTAL'
    , @AnalyseModus                     varchar(16)    = 'TOP'
    , @MaxZeilen                        int            = 100
    , @MaxAnalyseobjekte                int            = 20
    , @MaxDurationSeconds               int            = 30
    , @ResultSetArt                     varchar(16)    = 'CONSOLE'
    , @ResultTablesJson               nvarchar(max) = NULL
    , @JsonErzeugen                     bit            = 0
    , @Json                             nvarchar(max)  = NULL OUTPUT
    , @PrintMeldungen                   bit            = 1
    , @Hilfe                            bit            = 0
AS
BEGIN
    SET NOCOUNT ON;
    SET LOCK_TIMEOUT 0;
    SET @Json = NULL;

    DECLARE @OutputMode varchar(16) = UPPER(LTRIM(RTRIM(COALESCE(@ResultSetArt, ''))));
    DECLARE @TableResultRequested bit = CASE WHEN @OutputMode = 'TABLE' THEN 1 ELSE 0 END;
    DECLARE @ConsoleResultRequested bit = CASE WHEN @OutputMode = 'CONSOLE' THEN 1 ELSE 0 END;
    DECLARE @TableTarget sysname=NULL;
    IF @TableResultRequested=0 AND NULLIF(LTRIM(RTRIM(COALESCE(@ResultTablesJson,N''))),N'') IS NOT NULL THROW 51011,N'@ResultTablesJson ist ausschließlich mit @ResultSetArt=TABLE zulässig.',1;
    IF @TableResultRequested=1 EXEC [monitor].[InternalPrepareSingleResultTable] @ResultTablesJson=@ResultTablesJson,@ResultName=N'moduleStatus',@TargetTable=@TableTarget OUTPUT,@ThrowOnError=1;
    IF @TableResultRequested = 1 OR @ConsoleResultRequested = 1 SET @OutputMode = 'NONE';
    DECLARE @Mode varchar(16) = UPPER(LTRIM(RTRIM(COALESCE(@AnalyseModus, 'TOP'))));
    DECLARE @Now datetime2(3) = SYSUTCDATETIME();
    DECLARE @StatusCode varchar(40) = 'AVAILABLE';
    DECLARE @Detail nvarchar(2000) = N'Aktivierte Phase-3-Module werden nacheinander ausgeführt.';
    DECLARE @HealthMode varchar(16) = CASE WHEN @Mode = 'VOLL' THEN 'VOLL' ELSE 'SUMMARY' END;
    DECLARE @MitDbVerteilung bit = CASE WHEN @Mode = 'VOLL' THEN 1 ELSE 0 END;
    DECLARE @ShowplanMode varchar(16) = CASE WHEN @Mode = 'VOLL' THEN 'VOLL' ELSE 'GEZIELT' END;
    DECLARE @QueryStatsSnapshotConsumerCount tinyint =
        CONVERT(tinyint, CONVERT(tinyint,COALESCE(@MitQueryStats,0))
            + CONVERT(tinyint,COALESCE(@MitQueryHashAnalysis,0))
            + CASE WHEN @MitShowplanAnalysis=1 AND @PlanHandle IS NULL THEN 1 ELSE 0 END);
    DECLARE @QueryStatsSnapshotAvailable bit = 0;
    DECLARE @QueryStatsSnapshotAllowed bit = 1;
    DECLARE @ShowplanUsesQueryStatsSnapshot bit = 0;
    DECLARE @QueryStatsJson nvarchar(max);
    DECLARE @HashJson nvarchar(max);
    DECLARE @HealthJson nvarchar(max);
    DECLARE @ShowplanJson nvarchar(max);

    DECLARE @Errors TABLE
    (
          [ExecutionOrdinal] tinyint        NOT NULL
        , [ModuleName]       sysname        NOT NULL
        , [InvocationStatus] varchar(40)    NOT NULL
        , [ErrorNumber]      int            NULL
        , [ErrorMessage]     nvarchar(2048) NULL
    );
    CREATE TABLE [#PlanCacheAnalysis_QueryStatsSnapshot]
    (
          [sql_handle] varbinary(64) NULL
        , [statement_start_offset] int NULL
        , [statement_end_offset] int NULL
        , [plan_generation_num] bigint NULL
        , [plan_handle] varbinary(64) NULL
        , [creation_time] datetime NULL
        , [last_execution_time] datetime NULL
        , [execution_count] bigint NULL
        , [total_worker_time] bigint NULL
        , [last_worker_time] bigint NULL
        , [min_worker_time] bigint NULL
        , [max_worker_time] bigint NULL
        , [total_physical_reads] bigint NULL
        , [last_physical_reads] bigint NULL
        , [total_logical_writes] bigint NULL
        , [last_logical_writes] bigint NULL
        , [total_logical_reads] bigint NULL
        , [last_logical_reads] bigint NULL
        , [total_elapsed_time] bigint NULL
        , [last_elapsed_time] bigint NULL
        , [min_elapsed_time] bigint NULL
        , [max_elapsed_time] bigint NULL
        , [query_hash] binary(8) NULL
        , [query_plan_hash] binary(8) NULL
        , [total_rows] bigint NULL
        , [last_rows] bigint NULL
        , [min_rows] bigint NULL
        , [max_rows] bigint NULL
        , [last_dop] bigint NULL
        , [min_dop] bigint NULL
        , [max_dop] bigint NULL
        , [max_grant_kb] bigint NULL
        , [last_grant_kb] bigint NULL
        , [last_used_grant_kb] bigint NULL
        , [last_ideal_grant_kb] bigint NULL
        , [total_spills] bigint NULL
        , [last_spills] bigint NULL
    );

    IF @Hilfe = 1
    BEGIN
        PRINT N'monitor.USP_PlanCacheAnalysis';
        PRINT N'Datenbank- und Textfilter folgen den zentralen Listen-/Patternverträgen.';
        PRINT N'@ResultSetArt = RAW, CONSOLE, TABLE oder NONE; optional JSON über @Json OUTPUT.';
        RETURN;
    END;

    IF @MaxZeilen < 0
       OR @MaxAnalyseobjekte < 0

       OR @MaxDurationSeconds NOT BETWEEN 1 AND 3600
       OR @OutputMode NOT IN ('RAW', 'CONSOLE', 'NONE')
       OR @Mode NOT IN ('TOP', 'VOLL')
       OR (@MitQueryStats = 0 AND @MitQueryHashAnalysis = 0
           AND @MitPlanCacheHealth = 0 AND @MitShowplanAnalysis = 0)
    BEGIN
        SET @StatusCode = 'INVALID_PARAMETER';
        SET @Detail = N'Ungültiger Parameter oder kein Teilmodul aktiviert.';
    END;

    IF @StatusCode = 'AVAILABLE'
       AND @QueryStatsSnapshotConsumerCount >= 2
       AND
       (
           @QueryHash IS NULL
           OR @Mode = 'VOLL'
           OR @MaxZeilen IS NULL
           OR @MaxZeilen = 0
           OR @MaxZeilen > 1000
       )
    BEGIN
        EXEC [monitor].[InternalCheckAnalysisPath]
              @AnalysisClass='PLAN_CACHE_DEEP'
            , @HighImpactConfirmed=@HighImpactConfirmed
            , @StatusCode=@StatusCode OUTPUT
            , @ErrorMessage=@Detail OUTPUT;
        SET @QueryStatsSnapshotAllowed=CONVERT(bit,CASE WHEN @StatusCode='AVAILABLE' THEN 1 ELSE 0 END);
    END;

    IF @StatusCode = 'AVAILABLE'
       AND @QueryStatsSnapshotConsumerCount >= 2
       AND @QueryStatsSnapshotAllowed = 1
    BEGIN TRY
        INSERT [#PlanCacheAnalysis_QueryStatsSnapshot]
        SELECT
              [sql_handle], [statement_start_offset], [statement_end_offset], [plan_generation_num]
            , [plan_handle], [creation_time], [last_execution_time], [execution_count]
            , [total_worker_time], [last_worker_time], [min_worker_time], [max_worker_time]
            , [total_physical_reads], [last_physical_reads]
            , [total_logical_writes], [last_logical_writes]
            , [total_logical_reads], [last_logical_reads]
            , [total_elapsed_time], [last_elapsed_time], [min_elapsed_time], [max_elapsed_time]
            , [query_hash], [query_plan_hash]
            , [total_rows], [last_rows], [min_rows], [max_rows]
            , [last_dop], [min_dop], [max_dop]
            , [max_grant_kb], [last_grant_kb], [last_used_grant_kb], [last_ideal_grant_kb]
            , [total_spills], [last_spills]
        FROM [sys].[dm_exec_query_stats] WITH (NOLOCK)
        WHERE @QueryHash IS NULL OR [query_hash]=@QueryHash;

        SET @QueryStatsSnapshotAvailable = 1;
        SET @ShowplanUsesQueryStatsSnapshot = CASE WHEN @MitShowplanAnalysis=1 AND @PlanHandle IS NULL THEN 1 ELSE 0 END;
        SET @Detail = N'dm_exec_query_stats wurde einmalig für die aktivierten Consumer materialisiert.';
    END TRY
    BEGIN CATCH
        DELETE FROM [#PlanCacheAnalysis_QueryStatsSnapshot];
        SET @QueryStatsSnapshotAvailable = 0;
        SET @ShowplanUsesQueryStatsSnapshot = 0;
        SET @Detail = N'Der gemeinsame dm_exec_query_stats-Snapshot war nicht verfügbar; aktivierte Children lesen mit eigenem Fehlerstatus frisch.';
    END CATCH;

    IF @StatusCode = 'AVAILABLE' AND @MitQueryStats = 1
    BEGIN
        BEGIN TRY
            EXEC [monitor].[USP_QueryStats]
                  @DatabaseNames = @DatabaseNames
                , @SystemdatenbankenEinbeziehen = @SystemdatenbankenEinbeziehen
                , @DatabaseNamePattern = @DatabaseNamePattern,@HighImpactConfirmed=@HighImpactConfirmed

                , @QueryHash = @QueryHash
                , @QueryPlanHash = @QueryPlanHash
                , @PlanHandle = @PlanHandle
                , @TextPattern = @TextPattern
                , @Sortierung = @Sortierung
                , @AnalyseModus = @Mode
                , @MaxZeilen = @MaxZeilen
                , @ParentQueryStatsSnapshot = @QueryStatsSnapshotAvailable
                , @ResultSetArt = @OutputMode
                , @JsonErzeugen = @JsonErzeugen
                , @Json = @QueryStatsJson OUTPUT
                , @PrintMeldungen = @PrintMeldungen;

            INSERT @Errors VALUES (1, N'USP_QueryStats',
                CASE WHEN @QueryStatsSnapshotAvailable=1 THEN 'REUSED_PARENT_SNAPSHOT' ELSE 'EXECUTED' END, NULL, NULL);
        END TRY
        BEGIN CATCH
            INSERT @Errors VALUES (1, N'USP_QueryStats', 'ERROR_HANDLED', ERROR_NUMBER(), ERROR_MESSAGE());
        END CATCH;
    END;

    IF @StatusCode = 'AVAILABLE' AND @MitQueryHashAnalysis = 1
    BEGIN
        BEGIN TRY
            EXEC [monitor].[USP_QueryHashAnalysis]
                  @QueryHash = @QueryHash
                , @Sortierung = @Sortierung
                , @AnalyseModus = @Mode
                , @MaxZeilen = @MaxZeilen
                , @HighImpactConfirmed = @HighImpactConfirmed
                , @ParentQueryStatsSnapshot = @QueryStatsSnapshotAvailable
                , @ResultSetArt = @OutputMode
                , @JsonErzeugen = @JsonErzeugen
                , @Json = @HashJson OUTPUT
                , @PrintMeldungen = @PrintMeldungen;

            INSERT @Errors VALUES (2, N'USP_QueryHashAnalysis',
                CASE WHEN @QueryStatsSnapshotAvailable=1 THEN 'REUSED_PARENT_SNAPSHOT' ELSE 'EXECUTED' END, NULL, NULL);
        END TRY
        BEGIN CATCH
            INSERT @Errors VALUES (2, N'USP_QueryHashAnalysis', 'ERROR_HANDLED', ERROR_NUMBER(), ERROR_MESSAGE());
        END CATCH;
    END;

    IF @StatusCode = 'AVAILABLE' AND @MitPlanCacheHealth = 1
    BEGIN
        BEGIN TRY
            EXEC [monitor].[USP_PlanCacheHealth]
                  @AnalyseModus = @HealthMode
                , @MitDatenbankVerteilung = @MitDbVerteilung
                , @MaxZeilen = @MaxZeilen
                , @HighImpactConfirmed = @HighImpactConfirmed
                , @ResultSetArt = @OutputMode
                , @JsonErzeugen = @JsonErzeugen
                , @Json = @HealthJson OUTPUT
                , @PrintMeldungen = @PrintMeldungen;

            INSERT @Errors VALUES (3, N'USP_PlanCacheHealth', 'EXECUTED', NULL, NULL);
        END TRY
        BEGIN CATCH
            INSERT @Errors VALUES (3, N'USP_PlanCacheHealth', 'ERROR_HANDLED', ERROR_NUMBER(), ERROR_MESSAGE());
        END CATCH;
    END;

    IF @StatusCode = 'AVAILABLE' AND @MitShowplanAnalysis = 1
    BEGIN
        BEGIN TRY
            EXEC [monitor].[USP_ShowplanAnalysis]
                  @PlanHandle = @PlanHandle
                , @QueryHash = @QueryHash
                , @QueryPlanHash = @QueryPlanHash
                , @DatabaseNames = @DatabaseNames
                , @SystemdatenbankenEinbeziehen = @SystemdatenbankenEinbeziehen
                , @DatabaseNamePattern = @DatabaseNamePattern,@HighImpactConfirmed=@HighImpactConfirmed

                , @TextPattern = @TextPattern
                , @AnalyseModus = @ShowplanMode
                , @Sortierung = @Sortierung
                , @MaxAnalyseobjekte = @MaxAnalyseobjekte
                , @MaxZeilen = @MaxZeilen
                , @MaxDurationSeconds = @MaxDurationSeconds
                , @ParentQueryStatsSnapshot = @ShowplanUsesQueryStatsSnapshot
                , @ResultSetArt = @OutputMode
                , @JsonErzeugen = @JsonErzeugen
                , @Json = @ShowplanJson OUTPUT
                , @PrintMeldungen = @PrintMeldungen;

            INSERT @Errors VALUES (4, N'USP_ShowplanAnalysis',
                CASE WHEN @ShowplanUsesQueryStatsSnapshot=1 THEN 'REUSED_PARENT_SNAPSHOT' ELSE 'EXECUTED' END, NULL, NULL);
        END TRY
        BEGIN CATCH
            INSERT @Errors VALUES (4, N'USP_ShowplanAnalysis', 'ERROR_HANDLED', ERROR_NUMBER(), ERROR_MESSAGE());
        END CATCH;
    END;

    IF EXISTS (SELECT 1 FROM @Errors WHERE [InvocationStatus] NOT IN ('EXECUTED','REUSED_PARENT_SNAPSHOT'))
       AND @StatusCode = 'AVAILABLE'
    BEGIN
        SET @StatusCode = 'AVAILABLE_LIMITED';
    END;

    IF @OutputMode <> 'NONE'
    BEGIN
        SELECT
              N'USP_PlanCacheAnalysis' AS [ModuleName]
            , @Now                    AS [CollectionTimeUtc]
            , @StatusCode             AS [StatusCode]
            , CONVERT(bit, CASE WHEN @StatusCode = 'AVAILABLE' THEN 0 ELSE 1 END) AS [IsPartial]
            , @Detail                 AS [Detail];

        IF @OutputMode = 'RAW'
        BEGIN
            SELECT * FROM @Errors ORDER BY [ExecutionOrdinal];
        END
        ELSE
        BEGIN
            SELECT
                  N'Plan-Cache Teilmodul' AS [Ergebnis]
                , [ExecutionOrdinal]      AS [Reihenfolge]
                , [ModuleName]            AS [Modul]
                , [InvocationStatus]      AS [Status]
                , [ErrorMessage]          AS [Fehler]
            FROM @Errors
            ORDER BY [ExecutionOrdinal];
        END;
    END;

    IF @JsonErzeugen = 1
    BEGIN
        DECLARE @Meta nvarchar(max);
        DECLARE @Modules nvarchar(max);
        DECLARE @Warnings nvarchar(max);

        SELECT @Meta =
        (
            SELECT
                  N'PlanCacheAnalysis' AS [resultName]
                , 1                    AS [schemaVersion]
                , @Now                 AS [generatedAtUtc]
                , @StatusCode          AS [statusCode]
            FOR JSON PATH, WITHOUT_ARRAY_WRAPPER
        );

        SELECT @Modules =
        (
            SELECT *
            FROM @Errors
            ORDER BY [ExecutionOrdinal]
            FOR JSON PATH, INCLUDE_NULL_VALUES
        );

        SELECT @Warnings =
        (
            SELECT *
            FROM @Errors
            WHERE [InvocationStatus] NOT IN ('EXECUTED','REUSED_PARENT_SNAPSHOT')
            ORDER BY [ExecutionOrdinal]
            FOR JSON PATH, INCLUDE_NULL_VALUES
        );

        SET @Json = CONCAT
        (
              N'{"meta":', COALESCE(@Meta, N'{}')
            , N',"queryStats":', COALESCE(JSON_QUERY(@QueryStatsJson), N'null')
            , N',"queryHashes":', COALESCE(JSON_QUERY(@HashJson), N'null')
            , N',"planCacheHealth":', COALESCE(JSON_QUERY(@HealthJson), N'null')
            , N',"showplan":', COALESCE(JSON_QUERY(@ShowplanJson), N'null')
            , N',"modules":', COALESCE(@Modules, N'[]')
            , N',"warnings":', COALESCE(@Warnings, N'[]')
            , N'}'
        );
    END;
    IF @ConsoleResultRequested = 1
    BEGIN
        EXEC [monitor].[InternalEmitConsoleResult]
              @SourceTable=N'#PlanCacheAnalysis_MonitorTableResult'
            , @ResultLabel=N'PlanCacheAnalysis'
            , @EmptyMessage=N'Keine fachlichen Ergebnisse';
    END;
    IF @TableResultRequested = 1
    BEGIN
        SELECT * INTO [#PlanCacheAnalysis_MonitorTableResult] FROM @Errors;
        EXEC [monitor].[InternalWriteResultTable]
              @SourceTable = N'#PlanCacheAnalysis_MonitorTableResult'
            , @TargetTable=@TableTarget
            , @ThrowOnError = 1;
    END;
END;
GO
-- END SOURCE: Code/04_PlanCache/060_USP_PlanCacheAnalysis.sql

-- BEGIN SOURCE: Code/05_QueryStore/005_TVF_QueryStoreReplicaRoleInfo.sql
/*
===============================================================================
Objekt       : monitor.TVF_QueryStoreReplicaRoleInfo
Version      : 1.0.0
Stand        : 2026-07-27
Typ          : Inline Table-Valued Function
Zweck        : Ordnet Query-Store-replica role_type-Werte stabilen Rollen- und
               Scopeklassen zu, ohne versionsspezifische Kataloge zu referenzieren.
SQL-Version  : SQL Server 2019 oder neuer.
Eigenlast    : Konstante Projektion; keine Katalog- oder DMV-Zugriffe.
===============================================================================
*/
CREATE OR ALTER FUNCTION [monitor].[TVF_QueryStoreReplicaRoleInfo]
(
    @RoleType tinyint
)
RETURNS TABLE
AS
RETURN
(
    SELECT
          @RoleType AS [RoleType]
        , CONVERT(varchar(40),
            CASE @RoleType
                WHEN 1 THEN 'PRIMARY'
                WHEN 2 THEN 'SECONDARY'
                WHEN 3 THEN 'GEO_PRIMARY'
                WHEN 4 THEN 'GEO_SECONDARY'
                WHEN 5 THEN 'NAMED_REPLICA'
                WHEN NULL THEN 'UNKNOWN'
                ELSE CASE WHEN @RoleType > 5 THEN 'NAMED_REPLICA' ELSE 'UNKNOWN' END
            END) AS [RoleTypeDesc]
        , CONVERT(varchar(24),
            CASE
                WHEN @RoleType IN (1,3) THEN 'READ_WRITE_ROLE'
                WHEN @RoleType IN (2,4) OR @RoleType >= 5 THEN 'READ_ONLY_ROLE'
                ELSE 'UNKNOWN_ROLE'
            END) AS [RoleClass]
        , CONVERT(bit,CASE WHEN @RoleType IN (1,3) THEN 1 ELSE 0 END) AS [IsPrimaryRole]
        , CONVERT(bit,CASE WHEN @RoleType IN (2,4) OR @RoleType >= 5 THEN 1 ELSE 0 END) AS [IsSecondaryRole]
        , CONVERT(bit,CASE WHEN @RoleType >= 5 THEN 1 ELSE 0 END) AS [IsNamedReplica]
        , CONVERT(nvarchar(500),
            N'Rollenabbildung für sys.query_store_replicas.role_type; beobachtete Rollen sind keine aktuelle Erreichbarkeits- oder Healthaussage.') AS [EvidenceLimit]
);
GO
-- END SOURCE: Code/05_QueryStore/005_TVF_QueryStoreReplicaRoleInfo.sql

-- BEGIN SOURCE: Code/05_QueryStore/010_USP_QueryStoreStatus.sql
/*
===============================================================================
Objekt       : monitor.USP_QueryStoreStatus
Version      : 2.0.0
Stand        : 2026-07-15
Typ          : Stored Procedure
Zweck        : Prüft den Query-Store-Zustand je ausgewählter Quelldatenbank.
SQL-Version  : SQL Server 2019 oder neuer.
Datenquellen : monitor.TVF_DatabaseCandidates,
               monitor.TVF_ParseSqlNameList, monitor.TVF_ParsePattern,
               sys.database_query_store_options.
Parameter    : @QueryStoreDatabaseNames, @SystemdatenbankenEinbeziehen,
               @QueryStoreDatabaseNamePattern,
               @ResultSetArt, @JsonErzeugen, @Json OUTPUT,
               @PrintMeldungen, @Hilfe.
Semantik     : @QueryStoreDatabaseNames ist eine bracket-aware Pipe-Liste.
               NULL, N'' und Leerzeichen bedeuten keine Einschränkung.
               Die Datenbankauswahl wird nicht vorab begrenzt.
Ausgabe      : RAW, CONSOLE, TABLE oder NONE; optionales JSON mit meta,
               queryStoreStatus und warnings.
Berechtigung : SQL 2019 VIEW DATABASE STATE; SQL 2022+
               VIEW DATABASE PERFORMANCE STATE oder höher.
Eigenlast    : Sehr gering; eine Statuszeile je Datenbank.
Locking      : LOCK_TIMEOUT 0; keine Änderungen.
Änderungen   : 2.0.0 - @AlleDatenbanken entfernt; Listen-/Patternvertrag,
                         case-insensitive Steuerwerte und JSON eingeführt.
               1.0.0 - Erstfassung Phase 4.
===============================================================================
*/
CREATE OR ALTER PROCEDURE [monitor].[USP_QueryStoreStatus]
      @QueryStoreDatabaseNames         nvarchar(max)  = NULL
    , @SystemdatenbankenEinbeziehen    bit            = 0
    , @QueryStoreDatabaseNamePattern   nvarchar(4000) = NULL
    , @HighImpactConfirmed              bit            = 0
    , @ResultSetArt                    varchar(16)    = 'CONSOLE'
    , @ResultTablesJson               nvarchar(max) = NULL
    , @JsonErzeugen                    bit            = 0
    , @Json                            nvarchar(max)  = NULL OUTPUT
    , @PrintMeldungen                  bit            = 1
    , @Hilfe                           bit            = 0
AS
BEGIN
    SET NOCOUNT ON;
    SET @Json = NULL;

    DECLARE @ResultSetArtNormalisiert varchar(16) =
        UPPER(LTRIM(RTRIM(COALESCE(@ResultSetArt, ''))));
    DECLARE @TableResultRequested bit = CASE WHEN @ResultSetArtNormalisiert = 'TABLE' THEN 1 ELSE 0 END;
    DECLARE @ConsoleResultRequested bit = CASE WHEN @ResultSetArtNormalisiert = 'CONSOLE' THEN 1 ELSE 0 END;
    DECLARE @TableTarget sysname=NULL;
    IF @TableResultRequested=0 AND NULLIF(LTRIM(RTRIM(COALESCE(@ResultTablesJson,N''))),N'') IS NOT NULL THROW 51011,N'@ResultTablesJson ist ausschließlich mit @ResultSetArt=TABLE zulässig.',1;
    IF @TableResultRequested=1 EXEC [monitor].[InternalPrepareSingleResultTable] @ResultTablesJson=@ResultTablesJson,@ResultName=N'queryStoreStatus',@TargetTable=@TableTarget OUTPUT,@ThrowOnError=1;
    IF @TableResultRequested = 1 OR @ConsoleResultRequested = 1 SET @ResultSetArtNormalisiert = 'NONE';
    DECLARE @PatternMode varchar(8);
    DECLARE @PatternValue nvarchar(4000);
    DECLARE @RegexFlags varchar(8);
    DECLARE @PatternIsValid bit;

    SELECT
          @PatternMode = [PatternMode]
        , @PatternValue = [PatternValue]
        , @RegexFlags = [RegexFlags]
        , @PatternIsValid = [IsValid]
    FROM [monitor].[TVF_ParsePattern](@QueryStoreDatabaseNamePattern);

    IF @Hilfe = 1
    BEGIN
        PRINT N'monitor.USP_QueryStoreStatus';
        PRINT N'@QueryStoreDatabaseNames: konkreter Name oder Pipe-Liste; NULL/N'''' = alle zulässigen Datenbanken.';
        PRINT N'Beispiel: @QueryStoreDatabaseNames=N''[DeineDatenbank]|[BeispielDatenbankB]''.';
        PRINT N'@QueryStoreDatabaseNamePattern akzeptiert LIKE (Default/like:), regex: oder regexi:; Pattern und exakte Liste sind gegenseitig exklusiv.';
        PRINT N'Ohne Query-Store-Datenbankfilter werden alle sichtbaren Online-Benutzerdatenbanken verarbeitet.';
        PRINT N'@ResultSetArt=CONSOLE (Default)|RAW|TABLE|NONE wird case-insensitiv verarbeitet; @JsonErzeugen=1 setzt @Json OUTPUT.';
        RETURN;
    END;

    DECLARE @CollectionTimeUtc datetime2(3) = SYSUTCDATETIME();
    DECLARE @StatusCode varchar(40) = 'AVAILABLE';
    DECLARE @IsPartial bit = 0;
    DECLARE @ErrorNumber int = NULL;
    DECLARE @ErrorMessage nvarchar(2048) = NULL;
    DECLARE @Allowed bit = 1;
    DECLARE @Db sysname;
    DECLARE @Sql nvarchar(max);
    DECLARE @RowCount bigint = 0;
    DECLARE @DatabaseListCount int = 0;
    DECLARE @CrossDatabaseRequested bit = 0;
    DECLARE @MonitorPrintMessage nvarchar(2048);

    CREATE TABLE [#QueryStoreStatus_DatabaseCandidates]
    (
          [DatabaseId]         int            NOT NULL
        , [DatabaseName]       sysname        NOT NULL
        , [StateDesc]          nvarchar(60)   NULL
        , [UserAccessDesc]     nvarchar(60)   NULL
        , [IsReadOnly]         bit            NULL
        , [CompatibilityLevel] tinyint        NULL
        , [CollationName]      sysname        NULL
        , [RecoveryModelDesc]  nvarchar(60)   NULL
        , [IsSystemDatabase]   bit            NULL
        , [RequestedOrdinal]   int            NULL
    );

    CREATE TABLE [#QueryStoreStatus_Result]
    (
          [DatabaseId] int NULL
        , [DatabaseName] sysname NOT NULL
        , [DesiredState] smallint NULL
        , [DesiredStateDesc] nvarchar(60) NULL
        , [ActualState] smallint NULL
        , [ActualStateDesc] nvarchar(60) NULL
        , [ReadonlyReason] int NULL
        , [CurrentStorageSizeMb] bigint NULL
        , [MaxStorageSizeMb] bigint NULL
        , [StorageUsedPercent] decimal(9,2) NULL
        , [FlushIntervalSeconds] bigint NULL
        , [IntervalLengthMinutes] bigint NULL
        , [StaleQueryThresholdDays] bigint NULL
        , [MaxPlansPerQuery] bigint NULL
        , [QueryCaptureMode] smallint NULL
        , [QueryCaptureModeDesc] nvarchar(60) NULL
        , [SizeBasedCleanupMode] smallint NULL
        , [SizeBasedCleanupModeDesc] nvarchar(60) NULL
        , [WaitStatsCaptureMode] smallint NULL
        , [WaitStatsCaptureModeDesc] nvarchar(60) NULL
        , [CapturePolicyExecutionCount] int NULL
        , [CapturePolicyTotalCompileCpuTimeMs] bigint NULL
        , [CapturePolicyTotalExecutionCpuTimeMs] bigint NULL
        , [CapturePolicyStaleThresholdHours] int NULL
        , [IsEnabled] bit NULL
        , [IsWritable] bit NULL
        , [StatusHint] nvarchar(1000) NULL
    );

    CREATE TABLE [#QueryStoreStatus_Errors]
    (
          [DatabaseName] sysname NULL
        , [StatusCode] varchar(40) NOT NULL
        , [ErrorNumber] int NULL
        , [ErrorMessage] nvarchar(2048) NULL
    );

    IF @ResultSetArtNormalisiert NOT IN ('RAW', 'CONSOLE', 'NONE')
       OR @PatternIsValid = 0
    BEGIN
        SET @StatusCode = 'INVALID_PARAMETER';
        SET @ErrorMessage = N'Ungültiger Pattern-, Mengen- oder Ausgabeparameter.';
    END;

    IF @StatusCode = 'AVAILABLE'
    BEGIN
        EXEC [monitor].[USP_PrepareDatabaseCandidates]
              @DatabaseNames = @QueryStoreDatabaseNames
            , @SystemdatenbankenEinbeziehen = @SystemdatenbankenEinbeziehen
            , @DatabaseNamePattern = @QueryStoreDatabaseNamePattern,@HighImpactConfirmed=@HighImpactConfirmed

            , @AnalysisClass='QUERY_STORE_CURRENT'
            , @StatusCode = @StatusCode OUTPUT
            , @ErrorMessage = @ErrorMessage OUTPUT
            , @CrossDatabaseRequested = @CrossDatabaseRequested OUTPUT,@CandidateTable=N'#QueryStoreStatus_DatabaseCandidates';
    END;

    IF @StatusCode = 'AVAILABLE' AND @QueryStoreDatabaseNames IS NOT NULL
    BEGIN
        INSERT [#QueryStoreStatus_Errors]
        (
              [DatabaseName], [StatusCode], [ErrorNumber], [ErrorMessage]
        )
        SELECT
              [n].[NameValue]
            , 'DATABASE_NOT_FOUND'
            , NULL
            , N'Die explizit angeforderte Datenbank ist nicht online, nicht sichtbar oder nicht zugreifbar.'
        FROM [monitor].[TVF_ParseSqlNameList](@QueryStoreDatabaseNames) AS [n]
        WHERE [n].[IsValid] = 1
          AND NOT EXISTS
          (
              SELECT 1
              FROM [#QueryStoreStatus_DatabaseCandidates] AS [c]
              WHERE [c].[DatabaseName] COLLATE SQL_Latin1_General_CP1_CS_AS
                  = [n].[NameValue] COLLATE SQL_Latin1_General_CP1_CS_AS
          );

        IF EXISTS (SELECT 1 FROM [#QueryStoreStatus_Errors])
            SET @IsPartial = 1;
    END;

    SET LOCK_TIMEOUT 0;

    IF @StatusCode = 'AVAILABLE'
    BEGIN
        DECLARE [c] CURSOR LOCAL FAST_FORWARD FOR
            SELECT [DatabaseName]
            FROM [#QueryStoreStatus_DatabaseCandidates]
            ORDER BY COALESCE([RequestedOrdinal], [DatabaseId]), [DatabaseId];

        OPEN [c];
        FETCH NEXT FROM [c] INTO @Db;

        WHILE @@FETCH_STATUS = 0
        BEGIN
            BEGIN TRY
                SET @Sql = N'USE ' + QUOTENAME(@Db) + N';
INSERT [#QueryStoreStatus_Result]
SELECT
      DB_ID()
    , (SELECT [name] FROM [master].[sys].[databases] WITH (NOLOCK) WHERE [database_id] = DB_ID())
    , [desired_state]
    , [desired_state_desc]
    , [actual_state]
    , [actual_state_desc]
    , [readonly_reason]
    , [current_storage_size_mb]
    , [max_storage_size_mb]
    , CONVERT(decimal(9,2), 100.0 * [current_storage_size_mb] / NULLIF([max_storage_size_mb], 0))
    , [flush_interval_seconds]
    , [interval_length_minutes]
    , [stale_query_threshold_days]
    , [max_plans_per_query]
    , [query_capture_mode]
    , [query_capture_mode_desc]
    , [size_based_cleanup_mode]
    , [size_based_cleanup_mode_desc]
    , [wait_stats_capture_mode]
    , [wait_stats_capture_mode_desc]
    , [capture_policy_execution_count]
    , [capture_policy_total_compile_cpu_time_ms]
    , [capture_policy_total_execution_cpu_time_ms]
    , [capture_policy_stale_threshold_hours]
    , CONVERT(bit, CASE WHEN [actual_state] IN (1, 2, 4) THEN 1 ELSE 0 END)
    , CONVERT(bit, CASE WHEN [actual_state] = 2 THEN 1 ELSE 0 END)
    , CASE WHEN [actual_state] = 0 THEN N''Query Store ist OFF.''
           WHEN [actual_state] = 3 THEN N''Query Store meldet ERROR.''
           WHEN [desired_state] = 2 AND [actual_state] = 1
                THEN N''Query Store ist trotz gewünschtem READ_WRITE nur READ_ONLY; readonly_reason prüfen.''
           WHEN [max_storage_size_mb] > 0
            AND [current_storage_size_mb] * 100.0 / [max_storage_size_mb] >= 90
                THEN N''Speichernutzung liegt bei mindestens 90 Prozent.''
           ELSE N''Query Store ist lesbar.'' END
FROM [sys].[database_query_store_options] WITH (NOLOCK);';

                EXEC [sys].[sp_executesql] @Sql;
            END TRY
            BEGIN CATCH
                INSERT [#QueryStoreStatus_Errors]
                VALUES
                (
                      @Db
                    , CASE WHEN ERROR_NUMBER() IN (229,262,297,300,371,916) THEN 'DENIED_PERMISSION'
                           WHEN ERROR_NUMBER() = 1222 THEN 'TIMEOUT'
                           ELSE 'ERROR_HANDLED' END
                    , ERROR_NUMBER()
                    , ERROR_MESSAGE()
                );
                SET @IsPartial = 1;

                IF @PrintMeldungen = 1
                BEGIN
                    SET @MonitorPrintMessage = FORMATMESSAGE
                    (
                        N'WARNUNG USP_QueryStoreStatus [%s]: %s',
                        @Db,
                        ERROR_MESSAGE()
                    );
                    RAISERROR(N'%s', 10, 1, @MonitorPrintMessage) WITH NOWAIT;
                END;
            END CATCH;

            FETCH NEXT FROM [c] INTO @Db;
        END;

        CLOSE [c];
        DEALLOCATE [c];

        SELECT @RowCount = COUNT_BIG(*) FROM [#QueryStoreStatus_Result];

        IF @RowCount = 0
        BEGIN
            SET @StatusCode = CASE WHEN EXISTS
                 (SELECT 1 FROM [#QueryStoreStatus_Errors] WHERE [StatusCode] = 'DENIED_PERMISSION')
                 THEN 'DENIED_PERMISSION' ELSE 'DATABASE_UNAVAILABLE' END;
            SELECT TOP (1)
                  @ErrorNumber = [ErrorNumber]
                , @ErrorMessage = [ErrorMessage]
            FROM [#QueryStoreStatus_Errors]
            ORDER BY [DatabaseName];
        END
        ELSE IF @IsPartial = 1
            SET @StatusCode = 'AVAILABLE_LIMITED';
    END;

    IF @PrintMeldungen = 1
       AND @StatusCode NOT IN ('AVAILABLE', 'AVAILABLE_LIMITED')
    BEGIN
        SET @MonitorPrintMessage = FORMATMESSAGE
        (
            N'WARNUNG USP_QueryStoreStatus: %s - %s',
            @StatusCode,
            COALESCE(@ErrorMessage, N'Keine Details.')
        );
        RAISERROR(N'%s', 10, 1, @MonitorPrintMessage) WITH NOWAIT;
    END;

    IF @JsonErzeugen = 1
    BEGIN
        DECLARE @MetaJson nvarchar(max) =
        (
            SELECT
                  N'QueryStoreStatus' AS [resultName]
                , 1 AS [schemaVersion]
                , @CollectionTimeUtc AS [generatedAtUtc]
                , @StatusCode AS [statusCode]
                , @IsPartial AS [isPartial]
                , @RowCount AS [returnedRows]
                , @ErrorNumber AS [errorNumber]
                , @ErrorMessage AS [errorMessage]
            FOR JSON PATH, WITHOUT_ARRAY_WRAPPER, INCLUDE_NULL_VALUES
        );
        DECLARE @DataJson nvarchar(max) =
            (SELECT * FROM [#QueryStoreStatus_Result] ORDER BY [DatabaseId]
             FOR JSON PATH, INCLUDE_NULL_VALUES);
        DECLARE @WarningsJson nvarchar(max) =
            (SELECT [DatabaseName] AS [databaseName], [StatusCode] AS [code],
                    [ErrorNumber] AS [errorNumber], [ErrorMessage] AS [message]
             FROM [#QueryStoreStatus_Errors] ORDER BY [DatabaseName]
             FOR JSON PATH, INCLUDE_NULL_VALUES);

        SET @Json = CONCAT
        (
              N'{"meta":', COALESCE(@MetaJson, N'{}')
            , N',"queryStoreStatus":', COALESCE(@DataJson, N'[]')
            , N',"warnings":', COALESCE(@WarningsJson, N'[]')
            , N'}'
        );
    END;

    IF @ResultSetArtNormalisiert = 'RAW'
    BEGIN
        SELECT
              N'USP_QueryStoreStatus' AS [ModuleName]
            , @CollectionTimeUtc AS [CollectionTimeUtc]
            , @StatusCode AS [StatusCode]
            , @IsPartial AS [IsPartial]
            , @RowCount AS [RowCount]
            , CASE WHEN TRY_CONVERT(int, SERVERPROPERTY(N'ProductMajorVersion')) >= 16
                   THEN N'VIEW DATABASE PERFORMANCE STATE'
                   ELSE N'VIEW DATABASE STATE' END AS [RequiredPermission]
            , @ErrorNumber AS [ErrorNumber]
            , @ErrorMessage AS [ErrorMessage]
            , N'Read-only Query-Store-Statusprüfung.' AS [Detail];
        SELECT * FROM [#QueryStoreStatus_Result] ORDER BY [DatabaseId];
        SELECT * FROM [#QueryStoreStatus_Errors] ORDER BY [DatabaseName];
    END
    ELSE IF @ResultSetArtNormalisiert = 'CONSOLE'
    BEGIN
        SELECT
              N'Query Store Status' AS [Ergebnis]
            , @CollectionTimeUtc AS [Stand_UTC]
            , @StatusCode AS [Status]
            , @RowCount AS [Datenbanken]
            , @ErrorMessage AS [Hinweis];

        SELECT
              N'Query Store einer Datenbank' AS [Ergebnis]
            , [DatabaseName] AS [Datenbank]
            , [ActualStateDesc] AS [Ist_Status]
            , [DesiredStateDesc] AS [Soll_Status]
            , CONCAT(CONVERT(varchar(40), [CurrentStorageSizeMb]), N' MB') AS [Belegt]
            , CONCAT(CONVERT(varchar(40), [MaxStorageSizeMb]), N' MB') AS [Maximum]
            , CONCAT(CONVERT(varchar(40), [StorageUsedPercent]), N' %') AS [Belegung]
            , [QueryCaptureModeDesc] AS [Capture_Mode]
            , [WaitStatsCaptureModeDesc] AS [Wait_Stats]
            , [StatusHint] AS [Hinweis]
        FROM [#QueryStoreStatus_Result]
        ORDER BY [DatabaseId];

        SELECT
              N'Query-Store-Warnung' AS [Ergebnis]
            , [DatabaseName] AS [Datenbank]
            , [StatusCode] AS [Status]
            , [ErrorNumber] AS [Fehlernummer]
            , [ErrorMessage] AS [Meldung]
        FROM [#QueryStoreStatus_Errors]
        ORDER BY [DatabaseName];
    END;
    IF @ConsoleResultRequested = 1
    BEGIN
        EXEC [monitor].[InternalEmitConsoleResult]
              @SourceTable=N'#QueryStoreStatus_Result'
            , @ResultLabel=N'QueryStoreStatus'
            , @EmptyMessage=N'Keine fachlichen Ergebnisse';
    END;
    IF @TableResultRequested = 1
    BEGIN
        EXEC [monitor].[InternalWriteResultTable]
              @SourceTable = N'#QueryStoreStatus_Result'
            , @TargetTable=@TableTarget
            , @ThrowOnError = 1;
    END;
END;
GO
-- END SOURCE: Code/05_QueryStore/010_USP_QueryStoreStatus.sql

-- BEGIN SOURCE: Code/05_QueryStore/020_USP_QueryStoreRuntimeStats.sql
/*
===============================================================================
Objekt       : monitor.USP_QueryStoreRuntimeStats
Version      : 2.0.0
Stand        : 2026-07-15
Typ          : Stored Procedure
Zweck        : Liefert Query-Store-Runtime-Statistiken aus einer oder mehreren
               Query-Store-Quelldatenbanken mit exaktem globalem Top-N.
SQL-Version  : SQL Server 2019 oder neuer.
Quelldatenbanken: @QueryStoreDatabaseNames bracket-aware Pipe-Liste;
               NULL/N'' = alle zulässigen Datenbanken.
Referenzfilter: @ReferencedDatabaseNames beziehungsweise
               @ReferencedDatabaseNamePattern filtern auf Datenbanken, die in
               gespeicherten Showplans referenziert werden.
Pattern      : LIKE (Default/like:), regex:, regexi:. Regex benötigt SQL Server
               2025 und Compatibility Level 170 der jeweils ausgewerteten DB.
Top-N        : Je Quelldatenbank werden höchstens N+1 lokale Kandidaten gelesen;
               anschließend wird daraus das exakte globale Top N gebildet.
Ausgabe      : RAW, CONSOLE, TABLE oder NONE; optionales JSON mit meta, runtimeStats
               und warnings.
Änderungen   : 2.0.0 - Quell-/Referenzdatenbanken getrennt, @AlleDatenbanken
                         entfernt, globale Top-N-Logik, Pattern und JSON.
               1.0.0 - Erstfassung Phase 4.
===============================================================================
*/
CREATE OR ALTER PROCEDURE [monitor].[USP_QueryStoreRuntimeStats]
      @QueryStoreDatabaseNames          nvarchar(max)  = NULL
    , @QueryStoreDatabaseNamePattern    nvarchar(4000) = NULL
    , @HighImpactConfirmed              bit            = 0
    , @ReferencedDatabaseNames          nvarchar(max)  = NULL
    , @ReferencedDatabaseNamePattern    nvarchar(4000) = NULL
    , @QueryId                          bigint         = NULL
    , @QueryHash                        binary(8)      = NULL
    , @TextPattern                      nvarchar(4000) = NULL
    , @VonUtc                           datetime2(7)   = NULL
    , @BisUtc                           datetime2(7)   = NULL
    , @Sortierung                       varchar(32)    = 'CPU_TOTAL'
    , @AnalyseModus                     varchar(16)    = 'TOP'
    , @MaxZeilen                        int            = 100
    , @MitPlanXml                       bit            = 0
    , @MaxSqlTextZeichen                int            = 4000
    , @ResultSetArt                     varchar(16)    = 'CONSOLE'
    , @ResultTablesJson               nvarchar(max) = NULL
    , @JsonErzeugen                     bit            = 0
    , @Json                             nvarchar(max)  = NULL OUTPUT
    , @PrintMeldungen                   bit            = 1
    , @Hilfe                            bit            = 0
AS
BEGIN
    SET NOCOUNT ON;
    SET @Json = NULL;

    DECLARE @EffectiveMaxZeilen bigint =
        CASE WHEN @MaxZeilen IS NULL OR @MaxZeilen = 0
             THEN CONVERT(bigint, 9223372036854775807)
             WHEN @MaxZeilen > 0 THEN CONVERT(bigint, @MaxZeilen)
             ELSE CONVERT(bigint, 0) END;
    DECLARE @LocalCandidateRows bigint =
        CASE WHEN @MaxZeilen IS NULL OR @MaxZeilen = 0
             THEN CONVERT(bigint, 9223372036854775807)
             WHEN @MaxZeilen > 0 AND @MaxZeilen < 2147483647
             THEN CONVERT(bigint, @MaxZeilen) + 1
             WHEN @MaxZeilen > 0 THEN CONVERT(bigint, @MaxZeilen)
             ELSE CONVERT(bigint, 0) END;
    DECLARE @ResultSetArtNormalisiert varchar(16) =
        UPPER(LTRIM(RTRIM(COALESCE(@ResultSetArt, ''))));
    DECLARE @TableResultRequested bit = CASE WHEN @ResultSetArtNormalisiert = 'TABLE' THEN 1 ELSE 0 END;
    DECLARE @ConsoleResultRequested bit = CASE WHEN @ResultSetArtNormalisiert = 'CONSOLE' THEN 1 ELSE 0 END;
    DECLARE @TableTarget sysname=NULL;
    IF @TableResultRequested=0 AND NULLIF(LTRIM(RTRIM(COALESCE(@ResultTablesJson,N''))),N'') IS NOT NULL THROW 51011,N'@ResultTablesJson ist ausschließlich mit @ResultSetArt=TABLE zulässig.',1;
    IF @TableResultRequested=1 EXEC [monitor].[InternalPrepareSingleResultTable] @ResultTablesJson=@ResultTablesJson,@ResultName=N'runtimeStats',@TargetTable=@TableTarget OUTPUT,@ThrowOnError=1;
    IF @TableResultRequested = 1 OR @ConsoleResultRequested = 1 SET @ResultSetArtNormalisiert = 'NONE';
    SET @Sortierung = UPPER(LTRIM(RTRIM(COALESCE(@Sortierung, 'CPU_TOTAL'))));
    SET @AnalyseModus = UPPER(LTRIM(RTRIM(COALESCE(@AnalyseModus, 'TOP'))));

    DECLARE @TextPatternMode varchar(8);
    DECLARE @TextPatternValue nvarchar(4000);
    DECLARE @TextRegexFlags varchar(8);
    DECLARE @TextPatternIsValid bit;
    DECLARE @ReferencedPatternMode varchar(8);
    DECLARE @ReferencedPatternValue nvarchar(4000);
    DECLARE @ReferencedRegexFlags varchar(8);
    DECLARE @ReferencedPatternIsValid bit;

    SELECT
          @TextPatternMode = [PatternMode]
        , @TextPatternValue = [PatternValue]
        , @TextRegexFlags = [RegexFlags]
        , @TextPatternIsValid = [IsValid]
    FROM [monitor].[TVF_ParsePattern](@TextPattern);

    SELECT
          @ReferencedPatternMode = [PatternMode]
        , @ReferencedPatternValue = [PatternValue]
        , @ReferencedRegexFlags = [RegexFlags]
        , @ReferencedPatternIsValid = [IsValid]
    FROM [monitor].[TVF_ParsePattern](@ReferencedDatabaseNamePattern);

    IF @Hilfe = 1
    BEGIN
        PRINT N'monitor.USP_QueryStoreRuntimeStats';
        PRINT N'@QueryStoreDatabaseNames: exakter Name oder bracket-aware Pipe-Liste; NULL = alle; N'''' = keine Einschränkung.';
        PRINT N'@QueryStoreDatabaseNamePattern: alternatives LIKE-/Regex-Pattern für Quelldatenbanken.';
        PRINT N'@ReferencedDatabaseNames/@ReferencedDatabaseNamePattern: Filter auf in Showplans referenzierte Datenbanken; Deep-Analyse.';
        PRINT N'@TextPattern akzeptiert LIKE (Default/like:), regex: oder regexi:.';
        PRINT N'@Sortierung: CPU_TOTAL, DURATION_TOTAL, READS_TOTAL, WRITES_TOTAL, EXECUTIONS, MEMORY_MAX, TEMPDB_TOTAL, LOG_BYTES_TOTAL, LAST_EXECUTION.';
        PRINT N'@MaxZeilen ist global über alle Quelldatenbanken; NULL/0 = unbegrenzt.';
        PRINT N'@ResultSetArt=CONSOLE (Default)|RAW|TABLE|NONE case-insensitiv; @JsonErzeugen=1 setzt @Json OUTPUT.';
        RETURN;
    END;

    IF @BisUtc IS NULL SET @BisUtc = SYSUTCDATETIME();
    IF @VonUtc IS NULL SET @VonUtc = DATEADD(HOUR, -1, @BisUtc);

    DECLARE @CollectionTimeUtc datetime2(3) = SYSUTCDATETIME();
    DECLARE @StatusCode varchar(40) = 'AVAILABLE';
    DECLARE @IsPartial bit = 0;
    DECLARE @ErrorNumber int = NULL;
    DECLARE @ErrorMessage nvarchar(2048) = NULL;
    DECLARE @Allowed bit = 1;
    DECLARE @Db sysname;
    DECLARE @DbCompatibilityLevel tinyint;
    DECLARE @Sql nvarchar(max);
    DECLARE @Order sysname;
    DECLARE @CandidateRowCount bigint = 0;
    DECLARE @RowCount bigint = 0;
    DECLARE @HasMoreRows bit = 0;
    DECLARE @Deep bit = 0;
    DECLARE @CrossDatabaseRequested bit = 0;
    DECLARE @MonitorPrintMessage nvarchar(2048);
    DECLARE @TextPredicate nvarchar(max) = N'';
    DECLARE @ReferencedPredicate nvarchar(max) = N'';

    CREATE TABLE [#QueryStoreRuntimeStats_DatabaseCandidates]
    (
          [DatabaseId] int NOT NULL
        , [DatabaseName] sysname NOT NULL
        , [StateDesc] nvarchar(60) NULL
        , [UserAccessDesc] nvarchar(60) NULL
        , [IsReadOnly] bit NULL
        , [CompatibilityLevel] tinyint NULL
        , [CollationName] sysname NULL
        , [RecoveryModelDesc] nvarchar(60) NULL
        , [IsSystemDatabase] bit NULL
        , [RequestedOrdinal] int NULL
    );

    CREATE TABLE [#QueryStoreRuntimeStats_Result]
    (
          [QueryStoreDatabaseId] int NULL
        , [QueryStoreDatabaseName] sysname NOT NULL
        , [QueryId] bigint NOT NULL
        , [PlanId] bigint NOT NULL
        , [QueryHash] binary(8) NULL
        , [QueryPlanHash] binary(8) NULL
        , [ObjectId] bigint NULL
        , [ObjectName] nvarchar(517) NULL
        , [ExecutionTypeDesc] nvarchar(60) NULL
        , [FirstExecutionTimeUtc] datetimeoffset NULL
        , [LastExecutionTimeUtc] datetimeoffset NULL
        , [ExecutionCount] bigint NULL
        , [TotalDurationMs] decimal(38,3) NULL
        , [AverageDurationMs] decimal(38,3) NULL
        , [TotalCpuMs] decimal(38,3) NULL
        , [AverageCpuMs] decimal(38,3) NULL
        , [TotalLogicalReads] decimal(38,3) NULL
        , [AverageLogicalReads] decimal(38,3) NULL
        , [TotalLogicalWrites] decimal(38,3) NULL
        , [AverageLogicalWrites] decimal(38,3) NULL
        , [TotalPhysicalReads] decimal(38,3) NULL
        , [TotalMemoryGrantKb] decimal(38,3) NULL
        , [MaxMemoryGrantKb] decimal(38,3) NULL
        , [TotalRowCount] decimal(38,3) NULL
        , [TotalLogBytes] decimal(38,3) NULL
        , [TotalTempdbKb] decimal(38,3) NULL
        , [SourceType] varchar(32) NULL
        , [SourceObject] nvarchar(256) NULL
        , [CapturedAtUtc] datetime2(3) NULL
        , [EvidenceScope] varchar(40) NULL
        , [QuerySqlTextCharacters] bigint NULL
        , [QuerySqlTextBytes] bigint NULL
        , [QuerySqlTextIsTruncated] bit NULL
        , [QuerySqlText] nvarchar(max) NULL
        , [QueryPlanStatus] varchar(40) NULL
        , [QueryPlanCharacters] bigint NULL
        , [QueryPlanBytes] bigint NULL
        , [QueryPlan] xml NULL
        , [QueryPlanTextFallback] nvarchar(max) NULL
        , [EvidenceLimit] nvarchar(1000) NULL
    );

    CREATE TABLE [#QueryStoreRuntimeStats_Errors]
    (
          [DatabaseName] sysname NULL
        , [StatusCode] varchar(40) NOT NULL
        , [ErrorNumber] int NULL
        , [ErrorMessage] nvarchar(2048) NULL
    );

    SET @Order = CASE @Sortierung
        WHEN 'CPU_TOTAL' THEN N'TotalCpuMs'
        WHEN 'DURATION_TOTAL' THEN N'TotalDurationMs'
        WHEN 'READS_TOTAL' THEN N'TotalLogicalReads'
        WHEN 'WRITES_TOTAL' THEN N'TotalLogicalWrites'
        WHEN 'EXECUTIONS' THEN N'ExecutionCount'
        WHEN 'MEMORY_MAX' THEN N'MaxMemoryGrantKb'
        WHEN 'TEMPDB_TOTAL' THEN N'TotalTempdbKb'
        WHEN 'LOG_BYTES_TOTAL' THEN N'TotalLogBytes'
        WHEN 'LAST_EXECUTION' THEN N'LastExecutionTimeUtc'
    END;

    IF @AnalyseModus NOT IN ('TOP', 'VOLL')
       OR @Order IS NULL
       OR @MaxZeilen < 0

       OR @MaxSqlTextZeichen < 0
       OR @VonUtc >= @BisUtc
       OR @ResultSetArtNormalisiert NOT IN ('RAW', 'CONSOLE', 'NONE')
       OR @TextPatternIsValid = 0
       OR @ReferencedPatternIsValid = 0
       OR (@ReferencedDatabaseNames IS NOT NULL AND EXISTS
          (
              SELECT 1
              FROM [monitor].[TVF_ParseSqlNameList](@ReferencedDatabaseNames)
              WHERE [IsValid] = 0
          ))
       OR (@ReferencedDatabaseNames IS NOT NULL
           AND @ReferencedDatabaseNamePattern IS NOT NULL)
    BEGIN
        SET @StatusCode = 'INVALID_PARAMETER';
        SET @ErrorMessage = N'Ungültiger Parameter oder Zeitraum.';
    END;

    IF @StatusCode = 'AVAILABLE'
    BEGIN
        EXEC [monitor].[USP_PrepareDatabaseCandidates]
              @DatabaseNames = @QueryStoreDatabaseNames
            , @SystemdatenbankenEinbeziehen = 0
            , @DatabaseNamePattern = @QueryStoreDatabaseNamePattern,@HighImpactConfirmed=@HighImpactConfirmed

            , @AnalysisClass='QUERY_STORE_CURRENT'
            , @StatusCode = @StatusCode OUTPUT
            , @ErrorMessage = @ErrorMessage OUTPUT
            , @CrossDatabaseRequested = @CrossDatabaseRequested OUTPUT,@CandidateTable=N'#QueryStoreRuntimeStats_DatabaseCandidates';
    END;

    SET @Deep = CONVERT
    (
        bit,
        CASE WHEN @AnalyseModus = 'VOLL'
               OR @MitPlanXml = 1
               OR @EffectiveMaxZeilen > 1000
               OR DATEDIFF(HOUR, @VonUtc, @BisUtc) > 24
               OR @ReferencedDatabaseNames IS NOT NULL
               OR @ReferencedDatabaseNamePattern IS NOT NULL
               OR @TextPatternMode IN ('REGEX', 'REGEXI')
             THEN 1 ELSE 0 END
    );

    IF @StatusCode = 'AVAILABLE' AND @Deep = 1
    BEGIN
        EXEC [monitor].[InternalCheckAnalysisPath]
              @AnalysisClass='QUERY_STORE_DEEP'
            , @HighImpactConfirmed=@HighImpactConfirmed
            , @StatusCode=@StatusCode OUTPUT
            , @ErrorMessage=@ErrorMessage OUTPUT;
    END;

    IF @TextPatternMode = 'LIKE'
        SET @TextPredicate = N' AND [qt].[query_sql_text] COLLATE SQL_Latin1_General_CP1_CS_AS LIKE @TextPatternValue COLLATE SQL_Latin1_General_CP1_CS_AS';
    ELSE IF @TextPatternMode IN ('REGEX', 'REGEXI')
        SET @TextPredicate = N' AND REGEXP_LIKE([qt].[query_sql_text], @TextPatternValue, @TextRegexFlags)';

    IF @ReferencedDatabaseNames IS NOT NULL
        SET @ReferencedPredicate = N'
 AND EXISTS
 (
     SELECT 1
     FROM (SELECT CONVERT(xml, [p].[query_plan]) AS [PlanXml]) AS [px]
     CROSS APPLY [px].[PlanXml].nodes(''declare default element namespace "http://schemas.microsoft.com/sqlserver/2004/07/showplan"; //Object[@Database]'') AS [n]([ObjectNode])
     JOIN [monitor].[TVF_ParseSqlNameList](@ReferencedDatabaseNames) AS [rf]
       ON [rf].[IsValid] = 1
      AND [rf].[NameValue] COLLATE SQL_Latin1_General_CP1_CS_AS
        = PARSENAME([n].[ObjectNode].value(''@Database'', ''nvarchar(776)''), 1) COLLATE SQL_Latin1_General_CP1_CS_AS
 )';
    ELSE IF @ReferencedPatternMode = 'LIKE'
        SET @ReferencedPredicate = N'
 AND EXISTS
 (
     SELECT 1
     FROM (SELECT CONVERT(xml, [p].[query_plan]) AS [PlanXml]) AS [px]
     CROSS APPLY [px].[PlanXml].nodes(''declare default element namespace "http://schemas.microsoft.com/sqlserver/2004/07/showplan"; //Object[@Database]'') AS [n]([ObjectNode])
     WHERE PARSENAME([n].[ObjectNode].value(''@Database'', ''nvarchar(776)''), 1) COLLATE SQL_Latin1_General_CP1_CS_AS
           LIKE @ReferencedPatternValue COLLATE SQL_Latin1_General_CP1_CS_AS
 )';
    ELSE IF @ReferencedPatternMode IN ('REGEX', 'REGEXI')
        SET @ReferencedPredicate = N'
 AND EXISTS
 (
     SELECT 1
     FROM (SELECT CONVERT(xml, [p].[query_plan]) AS [PlanXml]) AS [px]
     CROSS APPLY [px].[PlanXml].nodes(''declare default element namespace "http://schemas.microsoft.com/sqlserver/2004/07/showplan"; //Object[@Database]'') AS [n]([ObjectNode])
     WHERE REGEXP_LIKE(PARSENAME([n].[ObjectNode].value(''@Database'', ''nvarchar(776)''), 1), @ReferencedPatternValue, @ReferencedRegexFlags)
 )';

    SET LOCK_TIMEOUT 0;

    IF @StatusCode = 'AVAILABLE'
    BEGIN
        DECLARE [c] CURSOR LOCAL FAST_FORWARD FOR
            SELECT [DatabaseName], [CompatibilityLevel]
            FROM [#QueryStoreRuntimeStats_DatabaseCandidates]
            ORDER BY COALESCE([RequestedOrdinal], [DatabaseId]), [DatabaseId];

        OPEN [c];
        FETCH NEXT FROM [c] INTO @Db, @DbCompatibilityLevel;

        WHILE @@FETCH_STATUS = 0
        BEGIN
            IF (@TextPatternMode IN ('REGEX', 'REGEXI')
                OR @ReferencedPatternMode IN ('REGEX', 'REGEXI'))
               AND
               (
                   TRY_CONVERT(int, SERVERPROPERTY(N'ProductMajorVersion')) < 17
                   OR @DbCompatibilityLevel < 170
               )
            BEGIN
                INSERT [#QueryStoreRuntimeStats_Errors]
                VALUES
                (
                      @Db
                    , 'UNAVAILABLE_FEATURE'
                    , NULL
                    , N'Regex benötigt SQL Server 2025 und Compatibility Level 170 in der Query-Store-Quelldatenbank.'
                );
                SET @IsPartial = 1;
            END
            ELSE
            BEGIN TRY
                SET @Sql = N'USE ' + QUOTENAME(@Db) + N';
IF EXISTS
(
    SELECT 1
    FROM [sys].[database_query_store_options] WITH (NOLOCK)
    WHERE [actual_state] IN (1, 2, 4)
)
BEGIN
    ;WITH [RI] AS
    (
        SELECT
              [rs].[plan_id]
            , [rs].[execution_type]
            , [rs].[execution_type_desc]
            , [rs].[runtime_stats_interval_id]
            , MIN([rs].[first_execution_time]) AS [first_execution_time]
            , MAX([rs].[last_execution_time]) AS [last_execution_time]
            , SUM([rs].[count_executions]) AS [count_executions]
            , SUM(CONVERT(float, [rs].[avg_duration]) * [rs].[count_executions]) AS [duration_weighted]
            , SUM(CONVERT(float, [rs].[avg_cpu_time]) * [rs].[count_executions]) AS [cpu_weighted]
            , SUM(CONVERT(float, [rs].[avg_logical_io_reads]) * [rs].[count_executions]) AS [reads_weighted]
            , SUM(CONVERT(float, [rs].[avg_logical_io_writes]) * [rs].[count_executions]) AS [writes_weighted]
            , SUM(CONVERT(float, [rs].[avg_physical_io_reads]) * [rs].[count_executions]) AS [physical_weighted]
            , SUM(CONVERT(float, [rs].[avg_query_max_used_memory]) * [rs].[count_executions]) AS [memory_weighted]
            , MAX(CONVERT(float, [rs].[max_query_max_used_memory])) AS [max_memory_pages]
            , SUM(CONVERT(float, [rs].[avg_rowcount]) * [rs].[count_executions]) AS [rows_weighted]
            , SUM(CONVERT(float, [rs].[avg_log_bytes_used]) * [rs].[count_executions]) AS [log_weighted]
            , SUM(CONVERT(float, [rs].[avg_tempdb_space_used]) * [rs].[count_executions]) AS [tempdb_weighted]
        FROM [sys].[query_store_runtime_stats] AS [rs] WITH (NOLOCK)
        JOIN [sys].[query_store_runtime_stats_interval] AS [rsi] WITH (NOLOCK)
          ON [rsi].[runtime_stats_interval_id] = [rs].[runtime_stats_interval_id]
        WHERE [rsi].[end_time] > @FromUtc
          AND [rsi].[start_time] < @ToUtc
        GROUP BY [rs].[plan_id], [rs].[execution_type],
                 [rs].[execution_type_desc], [rs].[runtime_stats_interval_id]
    ),
    [A] AS
    (
        SELECT
              [q].[query_id]
            , [p].[plan_id]
            , [q].[query_hash]
            , [p].[query_plan_hash]
            , [q].[object_id]
            , [RI].[execution_type_desc]
            , MIN([RI].[first_execution_time]) AS [first_execution_time]
            , MAX([RI].[last_execution_time]) AS [last_execution_time]
            , SUM([RI].[count_executions]) AS [executions]
            , SUM([RI].[duration_weighted]) AS [duration_weighted]
            , SUM([RI].[cpu_weighted]) AS [cpu_weighted]
            , SUM([RI].[reads_weighted]) AS [reads_weighted]
            , SUM([RI].[writes_weighted]) AS [writes_weighted]
            , SUM([RI].[physical_weighted]) AS [physical_weighted]
            , SUM([RI].[memory_weighted]) AS [memory_weighted]
            , MAX([RI].[max_memory_pages]) AS [max_memory_pages]
            , SUM([RI].[rows_weighted]) AS [rows_weighted]
            , SUM([RI].[log_weighted]) AS [log_weighted]
            , SUM([RI].[tempdb_weighted]) AS [tempdb_weighted]
            , [qt].[query_sql_text]
            , [p].[query_plan]
        FROM [RI]
        JOIN [sys].[query_store_plan] AS [p] WITH (NOLOCK)
          ON [p].[plan_id] = [RI].[plan_id]
        JOIN [sys].[query_store_query] AS [q] WITH (NOLOCK)
          ON [q].[query_id] = [p].[query_id]
        JOIN [sys].[query_store_query_text] AS [qt] WITH (NOLOCK)
          ON [qt].[query_text_id] = [q].[query_text_id]
        WHERE (@QueryId IS NULL OR [q].[query_id] = @QueryId)
          AND (@QueryHash IS NULL OR [q].[query_hash] = @QueryHash)' + @TextPredicate + @ReferencedPredicate + N'
        GROUP BY [q].[query_id], [p].[plan_id], [q].[query_hash],
                 [p].[query_plan_hash], [q].[object_id],
                 [RI].[execution_type_desc], [qt].[query_sql_text], [p].[query_plan]
    )
    INSERT [#QueryStoreRuntimeStats_Result]
    (
          [QueryStoreDatabaseId], [QueryStoreDatabaseName], [QueryId], [PlanId]
        , [QueryHash], [QueryPlanHash], [ObjectId], [ObjectName]
        , [ExecutionTypeDesc], [FirstExecutionTimeUtc], [LastExecutionTimeUtc]
        , [ExecutionCount], [TotalDurationMs], [AverageDurationMs]
        , [TotalCpuMs], [AverageCpuMs], [TotalLogicalReads]
        , [AverageLogicalReads], [TotalLogicalWrites], [AverageLogicalWrites]
        , [TotalPhysicalReads], [TotalMemoryGrantKb], [MaxMemoryGrantKb]
        , [TotalRowCount], [TotalLogBytes], [TotalTempdbKb]
        , [QuerySqlText], [QueryPlanTextFallback]
    )
    SELECT TOP (@TopRows)
          DB_ID()
        , (SELECT [name] FROM [master].[sys].[databases] WITH (NOLOCK) WHERE [database_id] = DB_ID())
        , [query_id]
        , [plan_id]
        , [query_hash]
        , [query_plan_hash]
        , [object_id]
        , CASE WHEN [A].[object_id] > 0
               THEN QUOTENAME([os].[name]) + N''.'' + QUOTENAME([oo].[name]) END
        , [execution_type_desc]
        , [first_execution_time]
        , [last_execution_time]
        , [executions]
        , CONVERT(decimal(38,3), [duration_weighted] / 1000.0)
        , CONVERT(decimal(38,3), [duration_weighted] / NULLIF([executions], 0) / 1000.0)
        , CONVERT(decimal(38,3), [cpu_weighted] / 1000.0)
        , CONVERT(decimal(38,3), [cpu_weighted] / NULLIF([executions], 0) / 1000.0)
        , CONVERT(decimal(38,3), [reads_weighted])
        , CONVERT(decimal(38,3), [reads_weighted] / NULLIF([executions], 0))
        , CONVERT(decimal(38,3), [writes_weighted])
        , CONVERT(decimal(38,3), [writes_weighted] / NULLIF([executions], 0))
        , CONVERT(decimal(38,3), [physical_weighted])
        , CONVERT(decimal(38,3), [memory_weighted] * 8.0)
        , CONVERT(decimal(38,3), [max_memory_pages] * 8.0)
        , CONVERT(decimal(38,3), [rows_weighted])
        , CONVERT(decimal(38,3), [log_weighted])
        , CONVERT(decimal(38,3), [tempdb_weighted] * 8.0)
        , [query_sql_text]
        , CASE WHEN @IncludePlan = 1 THEN [query_plan] END
    FROM [A]
    LEFT JOIN [sys].[objects] AS [oo] WITH (NOLOCK)
      ON [oo].[object_id] = [A].[object_id]
    LEFT JOIN [sys].[schemas] AS [os] WITH (NOLOCK)
      ON [os].[schema_id] = [oo].[schema_id]
    ORDER BY ' + QUOTENAME(@Order) + N' DESC, [last_execution_time] DESC;
END;';

                EXEC [sys].[sp_executesql]
                      @Sql
                    , N'@FromUtc datetime2(7), @ToUtc datetime2(7), @QueryId bigint,
                        @QueryHash binary(8), @TopRows bigint, @TextChars int,
                        @IncludePlan bit, @TextPatternValue nvarchar(4000),
                        @TextRegexFlags varchar(8), @ReferencedDatabaseNames nvarchar(max),
                        @ReferencedPatternValue nvarchar(4000), @ReferencedRegexFlags varchar(8)'
                    , @FromUtc = @VonUtc
                    , @ToUtc = @BisUtc
                    , @QueryId = @QueryId
                    , @QueryHash = @QueryHash
                    , @TopRows = @LocalCandidateRows
                    , @TextChars = @MaxSqlTextZeichen
                    , @IncludePlan = @MitPlanXml
                    , @TextPatternValue = @TextPatternValue
                    , @TextRegexFlags = @TextRegexFlags
                    , @ReferencedDatabaseNames = @ReferencedDatabaseNames
                    , @ReferencedPatternValue = @ReferencedPatternValue
                    , @ReferencedRegexFlags = @ReferencedRegexFlags;
            END TRY
            BEGIN CATCH
                INSERT [#QueryStoreRuntimeStats_Errors]
                VALUES
                (
                      @Db
                    , CASE WHEN ERROR_NUMBER() IN (229,262,297,300,371,916) THEN 'DENIED_PERMISSION'
                           WHEN ERROR_NUMBER() = 1222 THEN 'TIMEOUT'
                           ELSE 'ERROR_HANDLED' END
                    , ERROR_NUMBER()
                    , ERROR_MESSAGE()
                );
                SET @IsPartial = 1;

                IF @PrintMeldungen = 1
                BEGIN
                    SET @MonitorPrintMessage = FORMATMESSAGE
                    (
                        N'WARNUNG USP_QueryStoreRuntimeStats [%s]: %s',
                        @Db,
                        ERROR_MESSAGE()
                    );
                    RAISERROR(N'%s', 10, 1, @MonitorPrintMessage) WITH NOWAIT;
                END;
            END CATCH;

            FETCH NEXT FROM [c] INTO @Db, @DbCompatibilityLevel;
        END;

        CLOSE [c];
        DEALLOCATE [c];

        UPDATE [r]
        SET [SourceType]='QUERY_STORE',
            [SourceObject]=N'sys.query_store_runtime_stats|sys.query_store_plan|sys.query_store_query_text',
            [CapturedAtUtc]=@CollectionTimeUtc,
            [EvidenceScope]='DATABASE_QUERY_PLAN_INTERVAL',
            [QuerySqlTextCharacters]=[projection].[OriginalCharacters],
            [QuerySqlTextBytes]=[projection].[OriginalBytes],
            [QuerySqlTextIsTruncated]=[projection].[IsTruncated],
            [QuerySqlText]=[projection].[ProjectedValue],
            [QueryPlanStatus]=CASE WHEN @MitPlanXml=0 THEN 'NOT_REQUESTED' ELSE 'PENDING' END,
            [EvidenceLimit]=N'Query Store liefert aggregierte Intervallwerte und den gespeicherten Plan; keine aktuelle Einzelausführung und keine vollständigen Runtimeparameter.'
        FROM [#QueryStoreRuntimeStats_Result] AS [r]
        CROSS APPLY [monitor].[TVF_ProjectUnicodeText]([r].[QuerySqlText],@MaxSqlTextZeichen) AS [projection];

        DECLARE @PlanDatabaseId int,@PlanQueryId bigint,@PlanId bigint,@PlanText nvarchar(max);
        DECLARE @PlanXml xml,@PlanStatus varchar(40),@PlanErrorNumber int,@PlanErrorMessage nvarchar(2048);
        DECLARE [PlanCursor] CURSOR LOCAL FAST_FORWARD FOR
            SELECT [QueryStoreDatabaseId],[QueryId],[PlanId],[QueryPlanTextFallback]
            FROM [#QueryStoreRuntimeStats_Result]
            WHERE @MitPlanXml=1
            ORDER BY [QueryStoreDatabaseId],[QueryId],[PlanId];
        OPEN [PlanCursor];
        FETCH NEXT FROM [PlanCursor] INTO @PlanDatabaseId,@PlanQueryId,@PlanId,@PlanText;
        WHILE @@FETCH_STATUS=0
        BEGIN
            EXEC [monitor].[InternalParseXmlText]
                  @XmlText=@PlanText,@XmlValue=@PlanXml OUTPUT,@StatusCode=@PlanStatus OUTPUT,
                  @ErrorNumber=@PlanErrorNumber OUTPUT,@ErrorMessage=@PlanErrorMessage OUTPUT;
            UPDATE [#QueryStoreRuntimeStats_Result]
            SET [QueryPlanStatus]=@PlanStatus,
                [QueryPlanCharacters]=CASE WHEN @PlanText IS NULL THEN NULL ELSE CONVERT(bigint,LEN((@PlanText+NCHAR(1)) COLLATE Latin1_General_100_CI_AS_SC)-1) END,
                [QueryPlanBytes]=CONVERT(bigint,DATALENGTH(@PlanText)),
                [QueryPlan]=@PlanXml,
                [QueryPlanTextFallback]=CASE WHEN @PlanStatus IN('AVAILABLE','XML_EMPTY','SOURCE_NULL') THEN NULL ELSE @PlanText END
            WHERE [QueryStoreDatabaseId]=@PlanDatabaseId AND [QueryId]=@PlanQueryId AND [PlanId]=@PlanId;
            IF @PlanStatus IN('XML_INVALID','XML_UNAVAILABLE_LIMIT')
            BEGIN
                INSERT [#QueryStoreRuntimeStats_Errors]
                VALUES((SELECT TOP(1) [QueryStoreDatabaseName] FROM [#QueryStoreRuntimeStats_Result] WHERE [QueryStoreDatabaseId]=@PlanDatabaseId),@PlanStatus,@PlanErrorNumber,@PlanErrorMessage);
                SET @IsPartial=1;
            END;
            FETCH NEXT FROM [PlanCursor] INTO @PlanDatabaseId,@PlanQueryId,@PlanId,@PlanText;
        END;
        CLOSE [PlanCursor];
        DEALLOCATE [PlanCursor];

        DECLARE @TruncatedValueCount bigint=0,@LargestRequiredCharacters bigint=NULL;
        SELECT @TruncatedValueCount=COUNT_BIG(*),@LargestRequiredCharacters=MAX([QuerySqlTextCharacters])
        FROM [#QueryStoreRuntimeStats_Result]
        WHERE [QuerySqlTextIsTruncated]=1;
        EXEC [monitor].[InternalEmitTruncationWarning]
              @TruncatedValueCount=@TruncatedValueCount,@ParameterName=N'@MaxSqlTextZeichen',
              @ParameterValue=@MaxSqlTextZeichen,@LargestRequiredCharacters=@LargestRequiredCharacters,
              @PrintMeldungen=@PrintMeldungen;

        SELECT @CandidateRowCount = COUNT_BIG(*) FROM [#QueryStoreRuntimeStats_Result];
        SET @HasMoreRows = CONVERT(bit, CASE WHEN @CandidateRowCount > @EffectiveMaxZeilen THEN 1 ELSE 0 END);
        SET @RowCount = CASE WHEN @CandidateRowCount > @EffectiveMaxZeilen
                             THEN @EffectiveMaxZeilen ELSE @CandidateRowCount END;

        IF @RowCount = 0 AND EXISTS (SELECT 1 FROM [#QueryStoreRuntimeStats_Errors])
        BEGIN
            SET @StatusCode = 'AVAILABLE_LIMITED';
            SELECT TOP (1)
                  @ErrorNumber = [ErrorNumber]
                , @ErrorMessage = [ErrorMessage]
            FROM [#QueryStoreRuntimeStats_Errors]
            ORDER BY [DatabaseName];
        END
        ELSE IF @IsPartial = 1
            SET @StatusCode = 'AVAILABLE_LIMITED';
    END;

    IF @JsonErzeugen = 1
    BEGIN
        DECLARE @MetaJson nvarchar(max) =
        (
            SELECT
                  N'QueryStoreRuntimeStats' AS [resultName]
                , 1 AS [schemaVersion]
                , @CollectionTimeUtc AS [generatedAtUtc]
                , @StatusCode AS [statusCode]
                , @IsPartial AS [isPartial]
                , @MaxZeilen AS [requestedMaxRows]
                , @RowCount AS [returnedRows]
                , @HasMoreRows AS [resultLimited]
                , @HasMoreRows AS [hasMoreRows]
                , @VonUtc AS [fromUtc]
                , @BisUtc AS [toUtc]
                , @Sortierung AS [sort]
                , @ErrorNumber AS [errorNumber]
                , @ErrorMessage AS [errorMessage]
            FOR JSON PATH, WITHOUT_ARRAY_WRAPPER, INCLUDE_NULL_VALUES
        );
        DECLARE @DataJson nvarchar(max) =
        (
            SELECT *
            FROM
            (
                SELECT TOP (@EffectiveMaxZeilen)
                      [r].[QueryStoreDatabaseId],[r].[QueryStoreDatabaseName],[r].[QueryId],[r].[PlanId]
                    , [r].[QueryHash],[r].[QueryPlanHash],[r].[ObjectId],[r].[ObjectName]
                    , [r].[ExecutionTypeDesc],[r].[FirstExecutionTimeUtc],[r].[LastExecutionTimeUtc]
                    , [r].[ExecutionCount],[r].[TotalDurationMs],[r].[AverageDurationMs]
                    , [r].[TotalCpuMs],[r].[AverageCpuMs],[r].[TotalLogicalReads],[r].[AverageLogicalReads]
                    , [r].[TotalLogicalWrites],[r].[AverageLogicalWrites],[r].[TotalPhysicalReads]
                    , [r].[TotalMemoryGrantKb],[r].[MaxMemoryGrantKb],[r].[TotalRowCount]
                    , [r].[TotalLogBytes],[r].[TotalTempdbKb],[r].[SourceType],[r].[SourceObject]
                    , [r].[CapturedAtUtc],[r].[EvidenceScope],[r].[QuerySqlTextCharacters]
                    , [r].[QuerySqlTextBytes],[r].[QuerySqlTextIsTruncated],[r].[QuerySqlText]
                    , [r].[QueryPlanStatus],[r].[QueryPlanCharacters],[r].[QueryPlanBytes]
                    , CONVERT(nvarchar(max),[r].[QueryPlan]) AS [QueryPlan]
                    , [r].[QueryPlanTextFallback],[r].[EvidenceLimit]
                FROM [#QueryStoreRuntimeStats_Result] AS [r]
                ORDER BY
                      CASE WHEN @Sortierung = 'LAST_EXECUTION' THEN [LastExecutionTimeUtc] END DESC
                    , CASE WHEN @Sortierung = 'CPU_TOTAL' THEN [TotalCpuMs]
                           WHEN @Sortierung = 'DURATION_TOTAL' THEN [TotalDurationMs]
                           WHEN @Sortierung = 'READS_TOTAL' THEN [TotalLogicalReads]
                           WHEN @Sortierung = 'WRITES_TOTAL' THEN [TotalLogicalWrites]
                           WHEN @Sortierung = 'EXECUTIONS' THEN [ExecutionCount]
                           WHEN @Sortierung = 'MEMORY_MAX' THEN [MaxMemoryGrantKb]
                           WHEN @Sortierung = 'TEMPDB_TOTAL' THEN [TotalTempdbKb]
                           WHEN @Sortierung = 'LOG_BYTES_TOTAL' THEN [TotalLogBytes] END DESC
                    , [LastExecutionTimeUtc] DESC
                    , [QueryStoreDatabaseName]
                    , [QueryId]
                    , [PlanId]
            ) AS [x]
            FOR JSON PATH, INCLUDE_NULL_VALUES
        );
        DECLARE @WarningsJson nvarchar(max) =
            (SELECT [DatabaseName] AS [databaseName], [StatusCode] AS [code],
                    [ErrorNumber] AS [errorNumber], [ErrorMessage] AS [message]
             FROM [#QueryStoreRuntimeStats_Errors] ORDER BY [DatabaseName]
             FOR JSON PATH, INCLUDE_NULL_VALUES);

        SET @Json = CONCAT
        (
              N'{"meta":', COALESCE(@MetaJson, N'{}')
            , N',"runtimeStats":', COALESCE(@DataJson, N'[]')
            , N',"warnings":', COALESCE(@WarningsJson, N'[]')
            , N'}'
        );
    END;

    IF @ResultSetArtNormalisiert = 'RAW'
    BEGIN
        SELECT
              N'USP_QueryStoreRuntimeStats' AS [ModuleName]
            , @CollectionTimeUtc AS [CollectionTimeUtc]
            , @StatusCode AS [StatusCode]
            , @IsPartial AS [IsPartial]
            , @RowCount AS [RowCount]
            , @HasMoreRows AS [ResultLimited]
            , CASE WHEN TRY_CONVERT(int, SERVERPROPERTY(N'ProductMajorVersion')) >= 16
                   THEN N'VIEW DATABASE PERFORMANCE STATE'
                   ELSE N'VIEW DATABASE STATE' END AS [RequiredPermission]
            , @ErrorNumber AS [ErrorNumber]
            , @ErrorMessage AS [ErrorMessage]
            , CONCAT(N'Zeitraum UTC: ', CONVERT(nvarchar(30), @VonUtc, 126),
                     N' bis ', CONVERT(nvarchar(30), @BisUtc, 126),
                     N'; Deep=', @Deep) AS [Detail];

        SELECT TOP (@EffectiveMaxZeilen) [r].*
        FROM [#QueryStoreRuntimeStats_Result] AS [r]
        ORDER BY
              CASE WHEN @Sortierung = 'LAST_EXECUTION' THEN [LastExecutionTimeUtc] END DESC
            , CASE WHEN @Sortierung = 'CPU_TOTAL' THEN [TotalCpuMs]
                   WHEN @Sortierung = 'DURATION_TOTAL' THEN [TotalDurationMs]
                   WHEN @Sortierung = 'READS_TOTAL' THEN [TotalLogicalReads]
                   WHEN @Sortierung = 'WRITES_TOTAL' THEN [TotalLogicalWrites]
                   WHEN @Sortierung = 'EXECUTIONS' THEN [ExecutionCount]
                   WHEN @Sortierung = 'MEMORY_MAX' THEN [MaxMemoryGrantKb]
                   WHEN @Sortierung = 'TEMPDB_TOTAL' THEN [TotalTempdbKb]
                   WHEN @Sortierung = 'LOG_BYTES_TOTAL' THEN [TotalLogBytes] END DESC
            , [LastExecutionTimeUtc] DESC
            , [QueryStoreDatabaseName]
            , [QueryId]
            , [PlanId];

        SELECT * FROM [#QueryStoreRuntimeStats_Errors] ORDER BY [DatabaseName];
    END
    ELSE IF @ResultSetArtNormalisiert = 'CONSOLE'
    BEGIN
        SELECT
              N'Query Store Runtime Stats' AS [Ergebnis]
            , @CollectionTimeUtc AS [Stand_UTC]
            , @StatusCode AS [Status]
            , @RowCount AS [Zeilen]
            , @HasMoreRows AS [Ergebnis_begrenzt]
            , @VonUtc AS [Von_UTC]
            , @BisUtc AS [Bis_UTC]
            , @ErrorMessage AS [Hinweis];

        SELECT TOP (@EffectiveMaxZeilen)
              N'Query-Store-Abfrage' AS [Ergebnis]
            , [r].[QueryStoreDatabaseName] AS [QueryStore_Datenbank]
            , [r].[QueryId] AS [Query_ID]
            , [r].[PlanId] AS [Plan_ID]
            , [r].[ObjectName] AS [Objekt]
            , [r].[ExecutionTypeDesc] AS [Execution_Type]
            , [r].[ExecutionCount] AS [Ausführungen]
            , CONCAT(CONVERT(varchar(50), [r].[TotalCpuMs]), N' ms') AS [CPU_gesamt]
            , CONCAT(CONVERT(varchar(50), [r].[AverageCpuMs]), N' ms') AS [CPU_durchschnitt]
            , CONCAT(CONVERT(varchar(50), [r].[TotalDurationMs]), N' ms') AS [Dauer_gesamt]
            , CONCAT(CONVERT(varchar(50), [r].[AverageDurationMs]), N' ms') AS [Dauer_durchschnitt]
            , [r].[TotalLogicalReads] AS [Logical_Reads_gesamt]
            , [r].[AverageLogicalReads] AS [Logical_Reads_durchschnitt]

            , [r].[QueryId] AS [Query_ID_Memory]
            , CONCAT(CONVERT(varchar(50), [r].[MaxMemoryGrantKb] / 1024.0), N' MB') AS [Max_Memory_Grant]
            , CONCAT(CONVERT(varchar(50), [r].[TotalTempdbKb] / 1024.0), N' MB') AS [TempDB_gesamt]
            , [r].[LastExecutionTimeUtc] AS [Letzte_Ausführung_UTC]
            , [r].[QuerySqlText] AS [SQL_Text]
            , [r].[QueryPlan] AS [Query_Plan]
        FROM [#QueryStoreRuntimeStats_Result] AS [r]
        ORDER BY
              CASE WHEN @Sortierung = 'LAST_EXECUTION' THEN [LastExecutionTimeUtc] END DESC
            , CASE WHEN @Sortierung = 'CPU_TOTAL' THEN [TotalCpuMs]
                   WHEN @Sortierung = 'DURATION_TOTAL' THEN [TotalDurationMs]
                   WHEN @Sortierung = 'READS_TOTAL' THEN [TotalLogicalReads]
                   WHEN @Sortierung = 'WRITES_TOTAL' THEN [TotalLogicalWrites]
                   WHEN @Sortierung = 'EXECUTIONS' THEN [ExecutionCount]
                   WHEN @Sortierung = 'MEMORY_MAX' THEN [MaxMemoryGrantKb]
                   WHEN @Sortierung = 'TEMPDB_TOTAL' THEN [TotalTempdbKb]
                   WHEN @Sortierung = 'LOG_BYTES_TOTAL' THEN [TotalLogBytes] END DESC
            , [LastExecutionTimeUtc] DESC
            , [QueryStoreDatabaseName]
            , [QueryId]
            , [PlanId];

        SELECT
              N'Query-Store-Warnung' AS [Ergebnis]
            , [DatabaseName] AS [Datenbank]
            , [StatusCode] AS [Status]
            , [ErrorNumber] AS [Fehlernummer]
            , [ErrorMessage] AS [Meldung]
        FROM [#QueryStoreRuntimeStats_Errors]
        ORDER BY [DatabaseName];
    END;
    IF @ConsoleResultRequested = 1
    BEGIN
        EXEC [monitor].[InternalEmitConsoleResult]
              @SourceTable=N'#QueryStoreRuntimeStats_Result'
            , @ResultLabel=N'QueryStoreRuntimeStats'
            , @EmptyMessage=N'Keine fachlichen Ergebnisse';
    END;
    IF @TableResultRequested = 1
    BEGIN
        EXEC [monitor].[InternalWriteResultTable]
              @SourceTable = N'#QueryStoreRuntimeStats_Result'
            , @TargetTable=@TableTarget
            , @ThrowOnError = 1;
    END;
END;
GO
-- END SOURCE: Code/05_QueryStore/020_USP_QueryStoreRuntimeStats.sql

-- BEGIN SOURCE: Code/05_QueryStore/030_USP_QueryStoreWaitStats.sql
/*
===============================================================================
Objekt       : monitor.USP_QueryStoreWaitStats
Version      : 2.0.0
Stand        : 2026-07-15
Zweck        : Liefert Query-Store-Wait-Statistiken aus einer oder mehreren
               Quelldatenbanken mit einem exakten globalen Top-N über lokale
               N+1-Kandidaten. Ein optionaler Filter beschränkt die Ausgabe auf
               in Showplans referenzierte Datenbanken.
Ausgabe      : RAW, CONSOLE, TABLE oder NONE; optional JSON mit meta, waitStats,
               warnings. Steuerwerte werden case-insensitiv normalisiert.
===============================================================================
*/
CREATE OR ALTER PROCEDURE [monitor].[USP_QueryStoreWaitStats]
      @QueryStoreDatabaseNames          nvarchar(max)  = NULL
    , @QueryStoreDatabaseNamePattern    nvarchar(4000) = NULL
    , @HighImpactConfirmed              bit            = 0
    , @ReferencedDatabaseNames          nvarchar(max)  = NULL
    , @ReferencedDatabaseNamePattern    nvarchar(4000) = NULL
    , @QueryId                          bigint         = NULL
    , @QueryHash                        binary(8)      = NULL
    , @WaitCategory                     nvarchar(128)  = NULL
    , @VonUtc                           datetime2(7)   = NULL
    , @BisUtc                           datetime2(7)   = NULL
    , @AnalyseModus                     varchar(16)    = 'TOP'
    , @MaxZeilen                        int            = 100
    , @MaxSqlTextZeichen                int            = 4000
    , @ResultSetArt                     varchar(16)    = 'CONSOLE'
    , @ResultTablesJson               nvarchar(max) = NULL
    , @JsonErzeugen                     bit            = 0
    , @Json                             nvarchar(max)  = NULL OUTPUT
    , @PrintMeldungen                   bit            = 1
    , @Hilfe                            bit            = 0
AS
BEGIN
    SET NOCOUNT ON;
    SET @Json = NULL;
    SET @AnalyseModus = UPPER(LTRIM(RTRIM(COALESCE(@AnalyseModus, 'TOP'))));
    DECLARE @ResultSetArtNormalisiert varchar(16)=UPPER(LTRIM(RTRIM(COALESCE(@ResultSetArt,''))));
    DECLARE @TableResultRequested bit = CASE WHEN @ResultSetArtNormalisiert = 'TABLE' THEN 1 ELSE 0 END;
    DECLARE @ConsoleResultRequested bit = CASE WHEN @ResultSetArtNormalisiert = 'CONSOLE' THEN 1 ELSE 0 END;
    DECLARE @TableTarget sysname=NULL;
    IF @TableResultRequested=0 AND NULLIF(LTRIM(RTRIM(COALESCE(@ResultTablesJson,N''))),N'') IS NOT NULL THROW 51011,N'@ResultTablesJson ist ausschließlich mit @ResultSetArt=TABLE zulässig.',1;
    IF @TableResultRequested=1 EXEC [monitor].[InternalPrepareSingleResultTable] @ResultTablesJson=@ResultTablesJson,@ResultName=N'waitStats',@TargetTable=@TableTarget OUTPUT,@ThrowOnError=1;
    IF @TableResultRequested = 1 OR @ConsoleResultRequested = 1 SET @ResultSetArtNormalisiert = 'NONE';
    DECLARE @EffectiveMaxZeilen bigint=CASE WHEN @MaxZeilen IS NULL OR @MaxZeilen=0 THEN CONVERT(bigint,9223372036854775807) WHEN @MaxZeilen>0 THEN CONVERT(bigint,@MaxZeilen) ELSE 0 END;
    DECLARE @LocalRows bigint=CASE WHEN @MaxZeilen IS NULL OR @MaxZeilen=0 THEN CONVERT(bigint,9223372036854775807) WHEN @MaxZeilen<2147483647 THEN CONVERT(bigint,@MaxZeilen)+1 ELSE CONVERT(bigint,@MaxZeilen) END;
    IF @Hilfe=1
    BEGIN
        PRINT N'monitor.USP_QueryStoreWaitStats';
        PRINT N'@QueryStoreDatabaseNames: exakte bracket-aware Pipe-Liste; NULL=alle; N''''=keine Einschränkung.';
        PRINT N'@ReferencedDatabaseNames/Pattern: optionaler Showplan-Referenzfilter.';
        PRINT N'@MaxZeilen ist global; lokal werden N+1 Kandidaten je DB gelesen.';
        PRINT N'@ResultSetArt RAW|CONSOLE|TABLE|NONE; @JsonErzeugen=1 setzt @Json OUTPUT.';
        RETURN;
    END;
    IF @BisUtc IS NULL SET @BisUtc=SYSUTCDATETIME();
    IF @VonUtc IS NULL SET @VonUtc=DATEADD(HOUR,-1,@BisUtc);
    DECLARE @CollectionTimeUtc datetime2(3)=SYSUTCDATETIME(),@StatusCode varchar(40)='AVAILABLE',@IsPartial bit=0,@ErrorMessage nvarchar(2048)=NULL,@Allowed bit=1,@Db sysname,@DbCompat tinyint,@Sql nvarchar(max),@RowCount bigint=0,@HasMoreRows bit=0,@Cross bit=0,@Message nvarchar(2048);
    DECLARE @RefMode varchar(8),@RefValue nvarchar(4000),@RefFlags varchar(8),@RefValid bit,@RefPredicate nvarchar(max)=N'';
    SELECT @RefMode=[PatternMode],@RefValue=[PatternValue],@RefFlags=[RegexFlags],@RefValid=[IsValid] FROM [monitor].[TVF_ParsePattern](@ReferencedDatabaseNamePattern);
    CREATE TABLE [#QueryStoreWaitStats_DatabaseCandidates]([DatabaseId] int NOT NULL,[DatabaseName] sysname NOT NULL,[StateDesc] nvarchar(60),[UserAccessDesc] nvarchar(60),[IsReadOnly] bit,[CompatibilityLevel] tinyint,[CollationName] sysname,[RecoveryModelDesc] nvarchar(60),[IsSystemDatabase] bit,[RequestedOrdinal] int);
    CREATE TABLE [#QueryStoreWaitStats_Result]([QueryStoreDatabaseId] int,[QueryStoreDatabaseName] sysname,[QueryId] bigint,[PlanId] bigint,[QueryHash] binary(8),[QueryPlanHash] binary(8),[WaitCategory] tinyint,[WaitCategoryDesc] nvarchar(128),[ExecutionTypeDesc] nvarchar(128),[FirstIntervalStartUtc] datetimeoffset,[LastIntervalEndUtc] datetimeoffset,[RecordedRows] bigint,[TotalQueryWaitTimeMs] bigint,[AverageRecordedQueryWaitTimeMs] decimal(38,3),[MaxQueryWaitTimeMs] bigint,[QuerySqlText] nvarchar(max),[SourceType] varchar(32) NULL,[SourceObject] nvarchar(256) NULL,[CapturedAtUtc] datetime2(3) NULL,[EvidenceScope] varchar(40) NULL,[IsAggregated] bit NULL,[QuerySqlTextCharacters] bigint NULL,[QuerySqlTextBytes] bigint NULL,[QuerySqlTextIsTruncated] bit NOT NULL DEFAULT(0),[EvidenceLimit] nvarchar(1000) NULL);
    CREATE TABLE [#QueryStoreWaitStats_Errors]([DatabaseName] sysname,[StatusCode] varchar(40),[ErrorNumber] int NULL,[ErrorMessage] nvarchar(2048));
    IF @AnalyseModus NOT IN('TOP','VOLL') OR @MaxZeilen<0 OR @MaxSqlTextZeichen < 0 OR @VonUtc>=@BisUtc OR @ResultSetArtNormalisiert NOT IN('RAW','CONSOLE','NONE') OR @RefValid=0 OR (@ReferencedDatabaseNames IS NOT NULL AND @ReferencedDatabaseNamePattern IS NOT NULL) OR (@ReferencedDatabaseNames IS NOT NULL AND EXISTS(SELECT 1 FROM [monitor].[TVF_ParseSqlNameList](@ReferencedDatabaseNames) WHERE [IsValid]=0))
    BEGIN SET @StatusCode='INVALID_PARAMETER';SET @ErrorMessage=N'Ungültiger Parameter oder Zeitraum.';END;
    IF @StatusCode='AVAILABLE' EXEC [monitor].[USP_PrepareDatabaseCandidates] @DatabaseNames=@QueryStoreDatabaseNames,@SystemdatenbankenEinbeziehen=0,@DatabaseNamePattern=@QueryStoreDatabaseNamePattern,@HighImpactConfirmed=@HighImpactConfirmed,@AnalysisClass='QUERY_STORE_CURRENT',@StatusCode=@StatusCode OUTPUT,@ErrorMessage=@ErrorMessage OUTPUT,@CrossDatabaseRequested=@Cross OUTPUT,@CandidateTable=N'#QueryStoreWaitStats_DatabaseCandidates';
    IF @StatusCode='AVAILABLE' AND (@AnalyseModus='VOLL' OR @EffectiveMaxZeilen>1000 OR DATEDIFF(HOUR,@VonUtc,@BisUtc)>24 OR @ReferencedDatabaseNames IS NOT NULL OR @ReferencedDatabaseNamePattern IS NOT NULL)
        EXEC [monitor].[InternalCheckAnalysisPath] @AnalysisClass='QUERY_STORE_DEEP',@HighImpactConfirmed=@HighImpactConfirmed,@StatusCode=@StatusCode OUTPUT,@ErrorMessage=@ErrorMessage OUTPUT;
    IF @ReferencedDatabaseNames IS NOT NULL SET @RefPredicate=N' AND EXISTS(SELECT 1 FROM (SELECT CONVERT(xml,[p].[query_plan]) [PlanXml]) [px] CROSS APPLY [px].[PlanXml].nodes(''declare default element namespace "http://schemas.microsoft.com/sqlserver/2004/07/showplan"; //Object[@Database]'') [n]([x]) JOIN [monitor].[TVF_ParseSqlNameList](@ReferencedNames) [rf] ON [rf].[IsValid]=1 AND [rf].[NameValue] COLLATE SQL_Latin1_General_CP1_CS_AS=PARSENAME([n].[x].value(''@Database'',''nvarchar(776)''),1) COLLATE SQL_Latin1_General_CP1_CS_AS)';
    ELSE IF @RefMode='LIKE' SET @RefPredicate=N' AND EXISTS(SELECT 1 FROM (SELECT CONVERT(xml,[p].[query_plan]) [PlanXml]) [px] CROSS APPLY [px].[PlanXml].nodes(''declare default element namespace "http://schemas.microsoft.com/sqlserver/2004/07/showplan"; //Object[@Database]'') [n]([x]) WHERE PARSENAME([n].[x].value(''@Database'',''nvarchar(776)''),1) COLLATE SQL_Latin1_General_CP1_CS_AS LIKE @RefValue COLLATE SQL_Latin1_General_CP1_CS_AS)';
    ELSE IF @RefMode IN('REGEX','REGEXI') SET @RefPredicate=N' AND EXISTS(SELECT 1 FROM (SELECT CONVERT(xml,[p].[query_plan]) [PlanXml]) [px] CROSS APPLY [px].[PlanXml].nodes(''declare default element namespace "http://schemas.microsoft.com/sqlserver/2004/07/showplan"; //Object[@Database]'') [n]([x]) WHERE REGEXP_LIKE(PARSENAME([n].[x].value(''@Database'',''nvarchar(776)''),1),@RefValue,@RefFlags))';
    SET LOCK_TIMEOUT 0;
    IF @StatusCode='AVAILABLE'
    BEGIN
      DECLARE [c] CURSOR LOCAL FAST_FORWARD FOR SELECT [DatabaseName],[CompatibilityLevel] FROM [#QueryStoreWaitStats_DatabaseCandidates] ORDER BY COALESCE([RequestedOrdinal],[DatabaseId]),[DatabaseId];OPEN [c];FETCH NEXT FROM [c] INTO @Db,@DbCompat;
      WHILE @@FETCH_STATUS=0
      BEGIN
        IF @RefMode IN('REGEX','REGEXI') AND (TRY_CONVERT(int,SERVERPROPERTY(N'ProductMajorVersion'))<17 OR @DbCompat<170) BEGIN INSERT [#QueryStoreWaitStats_Errors] VALUES(@Db,'UNAVAILABLE_FEATURE',NULL,N'Regex benötigt SQL Server 2025 und Compatibility Level 170.');SET @IsPartial=1;END
        ELSE BEGIN TRY
          SET @Sql=N'USE '+QUOTENAME(@Db)+N';IF EXISTS(SELECT 1 FROM [sys].[database_query_store_options] WITH (NOLOCK) WHERE [actual_state] IN(1,2,4) AND [wait_stats_capture_mode]=1)
BEGIN
;WITH [W] AS
(
 SELECT [ws].[plan_id],[ws].[execution_type_desc],[ws].[wait_category],[ws].[wait_category_desc],MIN([i].[start_time]) [FirstStart],MAX([i].[end_time]) [LastEnd],COUNT_BIG(*) [RecordedRows],SUM([ws].[total_query_wait_time_ms]) [TotalWait],AVG(CONVERT(float,[ws].[avg_query_wait_time_ms])) [AverageWait],MAX([ws].[max_query_wait_time_ms]) [MaxWait]
 FROM [sys].[query_store_wait_stats] [ws] WITH (NOLOCK) JOIN [sys].[query_store_runtime_stats_interval] [i] WITH (NOLOCK) ON [i].[runtime_stats_interval_id]=[ws].[runtime_stats_interval_id]
 WHERE [i].[end_time]>@FromUtc AND [i].[start_time]<@ToUtc AND (@WaitCategory IS NULL OR [ws].[wait_category_desc]=@WaitCategory OR CONVERT(nvarchar(10),[ws].[wait_category])=@WaitCategory)
 GROUP BY [ws].[plan_id],[ws].[execution_type_desc],[ws].[wait_category],[ws].[wait_category_desc]
)
INSERT [#QueryStoreWaitStats_Result]([QueryStoreDatabaseId],[QueryStoreDatabaseName],[QueryId],[PlanId],[QueryHash],[QueryPlanHash],[WaitCategory],[WaitCategoryDesc],[ExecutionTypeDesc],[FirstIntervalStartUtc],[LastIntervalEndUtc],[RecordedRows],[TotalQueryWaitTimeMs],[AverageRecordedQueryWaitTimeMs],[MaxQueryWaitTimeMs],[QuerySqlText])
SELECT TOP(@TopRows) DB_ID(),(SELECT [name] FROM [master].[sys].[databases] WITH (NOLOCK) WHERE [database_id] = DB_ID()),[q].[query_id],[p].[plan_id],[q].[query_hash],[p].[query_plan_hash],[W].[wait_category],[W].[wait_category_desc],[W].[execution_type_desc],[W].[FirstStart],[W].[LastEnd],[W].[RecordedRows],[W].[TotalWait],CONVERT(decimal(38,3),[W].[AverageWait]),[W].[MaxWait],[qt].[query_sql_text]
FROM [W] JOIN [sys].[query_store_plan] [p] WITH (NOLOCK) ON [p].[plan_id]=[W].[plan_id] JOIN [sys].[query_store_query] [q] WITH (NOLOCK) ON [q].[query_id]=[p].[query_id] JOIN [sys].[query_store_query_text] [qt] WITH (NOLOCK) ON [qt].[query_text_id]=[q].[query_text_id]
WHERE (@QueryId IS NULL OR [q].[query_id]=@QueryId) AND (@QueryHash IS NULL OR [q].[query_hash]=@QueryHash)'+@RefPredicate+N'
ORDER BY [W].[TotalWait] DESC,[W].[LastEnd] DESC;
END;';
          EXEC [sys].[sp_executesql] @Sql,N'@FromUtc datetime2(7),@ToUtc datetime2(7),@WaitCategory nvarchar(128),@QueryId bigint,@QueryHash binary(8),@TopRows bigint,@TextChars int,@ReferencedNames nvarchar(max),@RefValue nvarchar(4000),@RefFlags varchar(8)',@VonUtc,@BisUtc,@WaitCategory,@QueryId,@QueryHash,@LocalRows,@MaxSqlTextZeichen,@ReferencedDatabaseNames,@RefValue,@RefFlags;
        END TRY BEGIN CATCH INSERT [#QueryStoreWaitStats_Errors] VALUES(@Db,CASE WHEN ERROR_NUMBER() IN(229,262,297,300,371,916) THEN 'DENIED_PERMISSION' WHEN ERROR_NUMBER()=1222 THEN 'TIMEOUT' ELSE 'ERROR_HANDLED' END,ERROR_NUMBER(),ERROR_MESSAGE());SET @IsPartial=1;IF @PrintMeldungen=1 BEGIN SET @Message=FORMATMESSAGE(N'WARNUNG USP_QueryStoreWaitStats [%s]: %s',@Db,ERROR_MESSAGE());RAISERROR(N'%s',10,1,@Message) WITH NOWAIT;END;END CATCH;
        FETCH NEXT FROM [c] INTO @Db,@DbCompat;
      END;CLOSE [c];DEALLOCATE [c];
    END;
    UPDATE [#QueryStoreWaitStats_Result]
    SET [SourceType]='QUERY_STORE',[SourceObject]=N'sys.query_store_wait_stats|sys.query_store_plan|sys.query_store_query_text',
        [CapturedAtUtc]=@CollectionTimeUtc,[EvidenceScope]='DATABASE_QUERY_PLAN_INTERVAL',[IsAggregated]=1,
        [EvidenceLimit]=N'Query-Store-Intervalaggregate; keine aktuelle Einzelausführung und keine vollständige Wait-Timeline.';
    DECLARE @TruncatedValueCount bigint=0,@LargestRequiredCharacters bigint=NULL;
    EXEC [monitor].[InternalProjectUnicodeTextColumn]
          @SourceTable=N'#QueryStoreWaitStats_Result',@TextColumn=N'QuerySqlText'
        , @CharactersColumn=N'QuerySqlTextCharacters',@BytesColumn=N'QuerySqlTextBytes'
        , @IsTruncatedColumn=N'QuerySqlTextIsTruncated',@MaxCharacters=@MaxSqlTextZeichen
        , @TruncatedValueCount=@TruncatedValueCount OUTPUT,@LargestRequiredCharacters=@LargestRequiredCharacters OUTPUT;
    EXEC [monitor].[InternalEmitTruncationWarning]
          @TruncatedValueCount=@TruncatedValueCount,@ParameterName=N'@MaxSqlTextZeichen'
        , @ParameterValue=@MaxSqlTextZeichen,@LargestRequiredCharacters=@LargestRequiredCharacters
        , @PrintMeldungen=@PrintMeldungen;
    SELECT @RowCount=COUNT_BIG(*) FROM [#QueryStoreWaitStats_Result];SET @HasMoreRows=CONVERT(bit,CASE WHEN @EffectiveMaxZeilen<9223372036854775807 AND @RowCount>@EffectiveMaxZeilen THEN 1 ELSE 0 END);IF @IsPartial=1 AND @StatusCode='AVAILABLE' SET @StatusCode='AVAILABLE_LIMITED';
    IF @ResultSetArtNormalisiert<>'NONE'
    BEGIN
      SELECT N'USP_QueryStoreWaitStats' [ModuleName],@CollectionTimeUtc [CollectionTimeUtc],@StatusCode [StatusCode],@IsPartial [IsPartial],CASE WHEN @RowCount>@EffectiveMaxZeilen THEN @EffectiveMaxZeilen ELSE @RowCount END [ReturnedRowCount],@HasMoreRows [HasMoreRows],@ErrorMessage [ErrorMessage];
      IF @ResultSetArtNormalisiert='RAW' SELECT TOP(@EffectiveMaxZeilen) * FROM [#QueryStoreWaitStats_Result] ORDER BY [TotalQueryWaitTimeMs] DESC,[LastIntervalEndUtc] DESC;
      ELSE SELECT TOP(@EffectiveMaxZeilen) N'Query-Store Wait' [Ergebnis],[QueryStoreDatabaseName] [Query-Store-Datenbank],[QueryId] [Query],[PlanId] [Plan],[WaitCategoryDesc] [Wait-Kategorie],CONCAT(CONVERT(varchar(30),CONVERT(decimal(19,2),[TotalQueryWaitTimeMs]/1000.0)),N' s') [Gesamte Wartezeit],[RecordedRows] [Messpunkte],[QueryStoreDatabaseName] [Quelle],[QuerySqlText] [SQL-Text] FROM [#QueryStoreWaitStats_Result] ORDER BY [TotalQueryWaitTimeMs] DESC,[LastIntervalEndUtc] DESC;
      SELECT * FROM [#QueryStoreWaitStats_Errors] ORDER BY [DatabaseName];
    END;
    IF @JsonErzeugen=1
    BEGIN
      DECLARE @Meta nvarchar(max)=(SELECT N'QueryStoreWaitStats' [resultName],1 [schemaVersion],@CollectionTimeUtc [generatedAtUtc],@StatusCode [statusCode],@MaxZeilen [requestedMaxRows],CASE WHEN @RowCount>@EffectiveMaxZeilen THEN @EffectiveMaxZeilen ELSE @RowCount END [returnedRows],@HasMoreRows [hasMoreRows] FOR JSON PATH,WITHOUT_ARRAY_WRAPPER,INCLUDE_NULL_VALUES);
      DECLARE @Data nvarchar(max)=(SELECT TOP(@EffectiveMaxZeilen) * FROM [#QueryStoreWaitStats_Result] ORDER BY [TotalQueryWaitTimeMs] DESC,[LastIntervalEndUtc] DESC FOR JSON PATH,INCLUDE_NULL_VALUES);
      DECLARE @Warnings nvarchar(max)=(SELECT * FROM [#QueryStoreWaitStats_Errors] ORDER BY [DatabaseName] FOR JSON PATH,INCLUDE_NULL_VALUES);
      SET @Json=CONCAT(N'{"meta":',COALESCE(@Meta,N'{}'),N',"waitStats":',COALESCE(@Data,N'[]'),N',"warnings":',COALESCE(@Warnings,N'[]'),N'}');
    END;
    IF @ConsoleResultRequested = 1
    BEGIN
        EXEC [monitor].[InternalEmitConsoleResult]
              @SourceTable=N'#QueryStoreWaitStats_Result'
            , @ResultLabel=N'QueryStoreWaitStats'
            , @EmptyMessage=N'Keine fachlichen Ergebnisse';
    END;
    IF @TableResultRequested = 1
    BEGIN
        EXEC [monitor].[InternalWriteResultTable]
              @SourceTable = N'#QueryStoreWaitStats_Result'
            , @TargetTable=@TableTarget
            , @ThrowOnError = 1;
    END;
END;
GO
