-- BEGIN SOURCE: Code/05_QueryStore/060_USP_QueryStoreForcedPlans.sql
/*
===============================================================================
Objekt       : monitor.USP_QueryStoreForcedPlans
Version      : 2.0.0
Stand        : 2026-07-15
Zweck        : Liefert erzwungene Query-Store-Pläne aus mehreren
               Quelldatenbanken mit globaler Top-N-Ausgabe und optionalem
               Referenzdatenbankfilter.
===============================================================================
*/
CREATE OR ALTER PROCEDURE [monitor].[USP_QueryStoreForcedPlans]
      @QueryStoreDatabaseNames          nvarchar(max)  = NULL
    , @QueryStoreDatabaseNamePattern    nvarchar(4000) = NULL
    , @HighImpactConfirmed              bit            = 0
    , @ReferencedDatabaseNames          nvarchar(max)  = NULL
    , @ReferencedDatabaseNamePattern    nvarchar(4000) = NULL
    , @QueryId                          bigint         = NULL
    , @NurMitFehler                     bit            = 0
    , @MitPlanXml                       bit            = 0
    , @MaxZeilen                        int            = 100
    , @MaxSqlTextZeichen                int            = 4000
    , @ResultSetArt                     varchar(16)    = 'CONSOLE'
    , @ResultTablesJson               nvarchar(max) = NULL
    , @JsonErzeugen                     bit            = 0
    , @Json                             nvarchar(max)  = NULL OUTPUT
    , @PrintMeldungen                   bit            = 1
    , @Hilfe                            bit            = 0
AS
BEGIN
 SET NOCOUNT ON;SET @Json=NULL;DECLARE @Out varchar(16)=UPPER(LTRIM(RTRIM(COALESCE(@ResultSetArt,'')))),@Limit bigint=CASE WHEN @MaxZeilen IS NULL OR @MaxZeilen=0 THEN CONVERT(bigint,9223372036854775807) WHEN @MaxZeilen>0 THEN @MaxZeilen ELSE 0 END,@Local bigint=CASE WHEN @MaxZeilen IS NULL OR @MaxZeilen=0 THEN CONVERT(bigint,9223372036854775807) WHEN @MaxZeilen<2147483647 THEN CONVERT(bigint,@MaxZeilen)+1 ELSE @MaxZeilen END;
    DECLARE @TableResultRequested bit = CASE WHEN @Out = 'TABLE' THEN 1 ELSE 0 END;
    DECLARE @ConsoleResultRequested bit = CASE WHEN @Out = 'CONSOLE' THEN 1 ELSE 0 END;
    DECLARE @TableTarget sysname=NULL;
    IF @TableResultRequested=0 AND NULLIF(LTRIM(RTRIM(COALESCE(@ResultTablesJson,N''))),N'') IS NOT NULL THROW 51011,N'@ResultTablesJson ist ausschließlich mit @ResultSetArt=TABLE zulässig.',1;
    IF @TableResultRequested=1 EXEC [monitor].[InternalPrepareSingleResultTable] @ResultTablesJson=@ResultTablesJson,@ResultName=N'forcedPlans',@TargetTable=@TableTarget OUTPUT,@ThrowOnError=1;
    IF @TableResultRequested = 1 OR @ConsoleResultRequested = 1 SET @Out = 'NONE';
 IF @Hilfe=1 BEGIN PRINT N'monitor.USP_QueryStoreForcedPlans';PRINT N'Quell-DB-Liste/Pattern, Referenz-DB-Liste/Pattern, RAW|CONSOLE|TABLE|NONE und JSON.';RETURN;END;
 DECLARE @Now datetime2(3)=SYSUTCDATETIME(),@Status varchar(40)='AVAILABLE',@Partial bit=0,@Error nvarchar(2048)=NULL,@Cross bit=0,@Allowed bit=1,@Db sysname,@Compat tinyint,@Sql nvarchar(max),@Count bigint=0,@HasMore bit=0,@Msg nvarchar(2048),@RefMode varchar(8),@RefValue nvarchar(4000),@RefFlags varchar(8),@RefValid bit,@RefPredicate nvarchar(max)=N'';
 SELECT @RefMode=[PatternMode],@RefValue=[PatternValue],@RefFlags=[RegexFlags],@RefValid=[IsValid] FROM [monitor].[TVF_ParsePattern](@ReferencedDatabaseNamePattern);
 CREATE TABLE [#QueryStoreForcedPlans_DatabaseCandidates]([DatabaseId] int NOT NULL,[DatabaseName] sysname NOT NULL,[StateDesc] nvarchar(60),[UserAccessDesc] nvarchar(60),[IsReadOnly] bit,[CompatibilityLevel] tinyint,[CollationName] sysname,[RecoveryModelDesc] nvarchar(60),[IsSystemDatabase] bit,[RequestedOrdinal] int);
 CREATE TABLE [#QueryStoreForcedPlans_Result]([QueryStoreDatabaseId] int,[QueryStoreDatabaseName] sysname,[QueryId] bigint,[PlanId] bigint,[QueryHash] binary(8),[QueryPlanHash] binary(8),[ObjectId] bigint NULL,[ObjectName] nvarchar(517) NULL,[IsForcedPlan] bit,[PlanForcingTypeDesc] nvarchar(60),[ForceFailureCount] bigint,[LastForceFailureReason] int,[LastForceFailureReasonDesc] nvarchar(128),[CountCompiles] bigint,[LastCompileStartTimeUtc] datetimeoffset,[LastExecutionTimeUtc] datetimeoffset,[EngineVersion] nvarchar(32),[CompatibilityLevel] smallint,[QuerySqlText] nvarchar(max),[QueryPlanTextFallback] nvarchar(max) NULL,[SourceType] varchar(32) NULL,[SourceObject] nvarchar(256) NULL,[CapturedAtUtc] datetime2(3) NULL,[EvidenceScope] varchar(40) NULL,[QuerySqlTextCharacters] bigint NULL,[QuerySqlTextBytes] bigint NULL,[QuerySqlTextIsTruncated] bit NULL,[QueryPlanStatus] varchar(40) NULL,[QueryPlanCharacters] bigint NULL,[QueryPlanBytes] bigint NULL,[QueryPlan] xml NULL,[EvidenceLimit] nvarchar(1000) NULL);
 CREATE TABLE [#QueryStoreForcedPlans_Errors]([DatabaseName] sysname,[StatusCode] varchar(40),[ErrorNumber] int NULL,[ErrorMessage] nvarchar(2048));
 IF @MaxZeilen<0 OR @MaxSqlTextZeichen < 0 OR @Out NOT IN('RAW','CONSOLE','NONE') OR @RefValid=0 OR (@ReferencedDatabaseNames IS NOT NULL AND @ReferencedDatabaseNamePattern IS NOT NULL) OR (@ReferencedDatabaseNames IS NOT NULL AND EXISTS(SELECT 1 FROM [monitor].[TVF_ParseSqlNameList](@ReferencedDatabaseNames) WHERE [IsValid]=0)) BEGIN SET @Status='INVALID_PARAMETER';SET @Error=N'Ungültiger Parameter.';END;
 IF @Status='AVAILABLE' EXEC [monitor].[USP_PrepareDatabaseCandidates] @DatabaseNames=@QueryStoreDatabaseNames,@SystemdatenbankenEinbeziehen=0,@DatabaseNamePattern=@QueryStoreDatabaseNamePattern,@HighImpactConfirmed=@HighImpactConfirmed,@AnalysisClass='QUERY_STORE_CURRENT',@StatusCode=@Status OUTPUT,@ErrorMessage=@Error OUTPUT,@CrossDatabaseRequested=@Cross OUTPUT,@CandidateTable=N'#QueryStoreForcedPlans_DatabaseCandidates';
 IF @Status='AVAILABLE' AND (@MitPlanXml=1 OR @Limit>1000 OR @ReferencedDatabaseNames IS NOT NULL OR @ReferencedDatabaseNamePattern IS NOT NULL) EXEC [monitor].[InternalCheckAnalysisPath] @AnalysisClass='QUERY_STORE_DEEP',@HighImpactConfirmed=@HighImpactConfirmed,@StatusCode=@Status OUTPUT,@ErrorMessage=@Error OUTPUT;
 IF @ReferencedDatabaseNames IS NOT NULL SET @RefPredicate=N' AND EXISTS(SELECT 1 FROM (SELECT CONVERT(xml,[p].[query_plan]) [PlanXml]) [px] CROSS APPLY [px].[PlanXml].nodes(''declare default element namespace "http://schemas.microsoft.com/sqlserver/2004/07/showplan"; //Object[@Database]'') [n]([x]) JOIN [monitor].[TVF_ParseSqlNameList](@ReferencedNames) [rf] ON [rf].[IsValid]=1 AND [rf].[NameValue] COLLATE SQL_Latin1_General_CP1_CS_AS=PARSENAME([n].[x].value(''@Database'',''nvarchar(776)''),1) COLLATE SQL_Latin1_General_CP1_CS_AS)';
 ELSE IF @RefMode='LIKE' SET @RefPredicate=N' AND EXISTS(SELECT 1 FROM (SELECT CONVERT(xml,[p].[query_plan]) [PlanXml]) [px] CROSS APPLY [px].[PlanXml].nodes(''declare default element namespace "http://schemas.microsoft.com/sqlserver/2004/07/showplan"; //Object[@Database]'') [n]([x]) WHERE PARSENAME([n].[x].value(''@Database'',''nvarchar(776)''),1) COLLATE SQL_Latin1_General_CP1_CS_AS LIKE @RefValue COLLATE SQL_Latin1_General_CP1_CS_AS)';
 ELSE IF @RefMode IN('REGEX','REGEXI') SET @RefPredicate=N' AND EXISTS(SELECT 1 FROM (SELECT CONVERT(xml,[p].[query_plan]) [PlanXml]) [px] CROSS APPLY [px].[PlanXml].nodes(''declare default element namespace "http://schemas.microsoft.com/sqlserver/2004/07/showplan"; //Object[@Database]'') [n]([x]) WHERE REGEXP_LIKE(PARSENAME([n].[x].value(''@Database'',''nvarchar(776)''),1),@RefValue,@RefFlags))';
 SET LOCK_TIMEOUT 0;
 IF @Status='AVAILABLE' BEGIN DECLARE [c] CURSOR LOCAL FAST_FORWARD FOR SELECT [DatabaseName],[CompatibilityLevel] FROM [#QueryStoreForcedPlans_DatabaseCandidates] ORDER BY COALESCE([RequestedOrdinal],[DatabaseId]),[DatabaseId];OPEN [c];FETCH NEXT FROM [c] INTO @Db,@Compat;WHILE @@FETCH_STATUS=0 BEGIN IF @RefMode IN('REGEX','REGEXI') AND (TRY_CONVERT(int,SERVERPROPERTY(N'ProductMajorVersion'))<17 OR @Compat<170) BEGIN INSERT [#QueryStoreForcedPlans_Errors] VALUES(@Db,'UNAVAILABLE_FEATURE',NULL,N'Regex benötigt SQL Server 2025 und Compatibility Level 170.');SET @Partial=1;END ELSE BEGIN TRY SET @Sql=N'USE '+QUOTENAME(@Db)+N';IF EXISTS(SELECT 1 FROM [sys].[database_query_store_options] WITH (NOLOCK) WHERE [actual_state] IN(1,2,4)) INSERT [#QueryStoreForcedPlans_Result] ([QueryStoreDatabaseId],[QueryStoreDatabaseName],[QueryId],[PlanId],[QueryHash],[QueryPlanHash],[ObjectId],[ObjectName],[IsForcedPlan],[PlanForcingTypeDesc],[ForceFailureCount],[LastForceFailureReason],[LastForceFailureReasonDesc],[CountCompiles],[LastCompileStartTimeUtc],[LastExecutionTimeUtc],[EngineVersion],[CompatibilityLevel],[QuerySqlText],[QueryPlanTextFallback]) SELECT TOP(@TopRows) DB_ID(),(SELECT [name] FROM [master].[sys].[databases] WITH (NOLOCK) WHERE [database_id] = DB_ID()),[q].[query_id],[p].[plan_id],[q].[query_hash],[p].[query_plan_hash],[q].[object_id],CASE WHEN [q].[object_id]>0 THEN QUOTENAME([os].[name])+N''.''+QUOTENAME([oo].[name]) END,[p].[is_forced_plan],[p].[plan_forcing_type_desc],[p].[force_failure_count],[p].[last_force_failure_reason],[p].[last_force_failure_reason_desc],[p].[count_compiles],[p].[last_compile_start_time],[p].[last_execution_time],[p].[engine_version],[p].[compatibility_level],[qt].[query_sql_text],CASE WHEN @IncludePlan=1 THEN [p].[query_plan] END FROM [sys].[query_store_plan] [p] WITH (NOLOCK) JOIN [sys].[query_store_query] [q] WITH (NOLOCK) ON [q].[query_id]=[p].[query_id] JOIN [sys].[query_store_query_text] [qt] WITH (NOLOCK) ON [qt].[query_text_id]=[q].[query_text_id] LEFT JOIN [sys].[objects] [oo] WITH (NOLOCK) ON [oo].[object_id]=[q].[object_id] LEFT JOIN [sys].[schemas] [os] WITH (NOLOCK) ON [os].[schema_id]=[oo].[schema_id] WHERE [p].[is_forced_plan]=1 AND (@QueryId IS NULL OR [q].[query_id]=@QueryId) AND (@OnlyErrors=0 OR [p].[force_failure_count]>0 OR [p].[last_force_failure_reason]<>0)'+@RefPredicate+N' ORDER BY CASE WHEN [p].[last_force_failure_reason]<>0 THEN 0 ELSE 1 END,[p].[last_execution_time] DESC;';EXEC [sys].[sp_executesql] @Sql,N'@TopRows bigint,@QueryId bigint,@OnlyErrors bit,@IncludePlan bit,@ReferencedNames nvarchar(max),@RefValue nvarchar(4000),@RefFlags varchar(8)',@Local,@QueryId,@NurMitFehler,@MitPlanXml,@ReferencedDatabaseNames,@RefValue,@RefFlags;END TRY BEGIN CATCH INSERT [#QueryStoreForcedPlans_Errors] VALUES(@Db,CASE WHEN ERROR_NUMBER() IN(229,262,297,300,371,916) THEN 'DENIED_PERMISSION' WHEN ERROR_NUMBER()=1222 THEN 'TIMEOUT' ELSE 'ERROR_HANDLED' END,ERROR_NUMBER(),ERROR_MESSAGE());SET @Partial=1;IF @PrintMeldungen=1 BEGIN SET @Msg=FORMATMESSAGE(N'WARNUNG USP_QueryStoreForcedPlans [%s]: %s',@Db,ERROR_MESSAGE());RAISERROR(N'%s',10,1,@Msg) WITH NOWAIT;END;END CATCH;FETCH NEXT FROM [c] INTO @Db,@Compat;END;CLOSE [c];DEALLOCATE [c];END;
 UPDATE [r] SET [SourceType]='QUERY_STORE',[SourceObject]=N'sys.query_store_plan|sys.query_store_query_text',[CapturedAtUtc]=@Now,[EvidenceScope]='DATABASE_QUERY_PLAN',[QuerySqlTextCharacters]=[p].[OriginalCharacters],[QuerySqlTextBytes]=[p].[OriginalBytes],[QuerySqlTextIsTruncated]=[p].[IsTruncated],[QuerySqlText]=[p].[ProjectedValue],[QueryPlanStatus]=CASE WHEN @MitPlanXml=0 THEN 'NOT_REQUESTED' ELSE 'PENDING' END,[EvidenceLimit]=N'Gespeicherter Query-Store-Plan und aggregierte Metadaten; kein aktueller Ausführungsplan.' FROM [#QueryStoreForcedPlans_Result] [r] CROSS APPLY [monitor].[TVF_ProjectUnicodeText]([r].[QuerySqlText],@MaxSqlTextZeichen) [p];
 DECLARE @PlanDb int,@PlanQuery bigint,@PlanIdLocal bigint,@PlanText nvarchar(max),@PlanXml xml,@PlanStatus varchar(40),@PlanErr int,@PlanMsg nvarchar(2048);DECLARE [pc] CURSOR LOCAL FAST_FORWARD FOR SELECT [QueryStoreDatabaseId],[QueryId],[PlanId],[QueryPlanTextFallback] FROM [#QueryStoreForcedPlans_Result] WHERE @MitPlanXml=1;OPEN [pc];FETCH NEXT FROM [pc] INTO @PlanDb,@PlanQuery,@PlanIdLocal,@PlanText;WHILE @@FETCH_STATUS=0 BEGIN EXEC [monitor].[InternalParseXmlText] @XmlText=@PlanText,@XmlValue=@PlanXml OUTPUT,@StatusCode=@PlanStatus OUTPUT,@ErrorNumber=@PlanErr OUTPUT,@ErrorMessage=@PlanMsg OUTPUT;UPDATE [#QueryStoreForcedPlans_Result] SET [QueryPlanStatus]=@PlanStatus,[QueryPlanCharacters]=CASE WHEN @PlanText IS NULL THEN NULL ELSE CONVERT(bigint,LEN((@PlanText+NCHAR(1)) COLLATE Latin1_General_100_CI_AS_SC)-1) END,[QueryPlanBytes]=CONVERT(bigint,DATALENGTH(@PlanText)),[QueryPlan]=@PlanXml,[QueryPlanTextFallback]=CASE WHEN @PlanStatus IN('AVAILABLE','XML_EMPTY','SOURCE_NULL') THEN NULL ELSE @PlanText END WHERE [QueryStoreDatabaseId]=@PlanDb AND [QueryId]=@PlanQuery AND [PlanId]=@PlanIdLocal;IF @PlanStatus IN('XML_INVALID','XML_UNAVAILABLE_LIMIT') BEGIN INSERT [#QueryStoreForcedPlans_Errors] VALUES((SELECT TOP(1) [QueryStoreDatabaseName] FROM [#QueryStoreForcedPlans_Result] WHERE [QueryStoreDatabaseId]=@PlanDb),@PlanStatus,@PlanErr,@PlanMsg);SET @Partial=1;END;FETCH NEXT FROM [pc] INTO @PlanDb,@PlanQuery,@PlanIdLocal,@PlanText;END;CLOSE [pc];DEALLOCATE [pc];
 DECLARE @TruncatedValueCount bigint=0,@LargestRequiredCharacters bigint=NULL;SELECT @TruncatedValueCount=COUNT_BIG(*),@LargestRequiredCharacters=MAX([QuerySqlTextCharacters]) FROM [#QueryStoreForcedPlans_Result] WHERE [QuerySqlTextIsTruncated]=1;EXEC [monitor].[InternalEmitTruncationWarning] @TruncatedValueCount=@TruncatedValueCount,@ParameterName=N'@MaxSqlTextZeichen',@ParameterValue=@MaxSqlTextZeichen,@LargestRequiredCharacters=@LargestRequiredCharacters,@PrintMeldungen=@PrintMeldungen;
 SELECT @Count=COUNT_BIG(*) FROM [#QueryStoreForcedPlans_Result];SET @HasMore=CONVERT(bit,CASE WHEN @Limit<9223372036854775807 AND @Count>@Limit THEN 1 ELSE 0 END);IF @Partial=1 AND @Status='AVAILABLE' SET @Status='AVAILABLE_LIMITED';
 IF @Out<>'NONE' BEGIN SELECT N'USP_QueryStoreForcedPlans' [ModuleName],@Now [CollectionTimeUtc],@Status [StatusCode],@Partial [IsPartial],CASE WHEN @Count>@Limit THEN @Limit ELSE @Count END [ReturnedRowCount],@HasMore [HasMoreRows],@Error [ErrorMessage];IF @Out='RAW' SELECT TOP(@Limit) * FROM [#QueryStoreForcedPlans_Result] ORDER BY CASE WHEN [LastForceFailureReason]<>0 THEN 0 ELSE 1 END,[LastExecutionTimeUtc] DESC;ELSE SELECT TOP(@Limit) N'Erzwungener Query-Store-Plan' [Ergebnis],[QueryStoreDatabaseName] [Query-Store-Datenbank],[QueryId] [Query],[PlanId] [Plan],[LastForceFailureReasonDesc] [letzter Fehler],[ForceFailureCount] [Fehleranzahl],[LastExecutionTimeUtc] [letzte Ausführung],[QueryStoreDatabaseName] [Quelle],[QuerySqlText] [SQL-Text],[QueryPlan] [Plan-XML] FROM [#QueryStoreForcedPlans_Result] ORDER BY CASE WHEN [LastForceFailureReason]<>0 THEN 0 ELSE 1 END,[LastExecutionTimeUtc] DESC;SELECT * FROM [#QueryStoreForcedPlans_Errors] ORDER BY [DatabaseName];END;
 IF @JsonErzeugen=1 BEGIN DECLARE @Meta nvarchar(max)=(SELECT N'QueryStoreForcedPlans' [resultName],2 [schemaVersion],@Now [generatedAtUtc],@Status [statusCode],@MaxZeilen [requestedMaxRows],CASE WHEN @Count>@Limit THEN @Limit ELSE @Count END [returnedRows],@HasMore [hasMoreRows] FOR JSON PATH,WITHOUT_ARRAY_WRAPPER,INCLUDE_NULL_VALUES),@Data nvarchar(max)=(SELECT TOP(@Limit) [QueryStoreDatabaseId],[QueryStoreDatabaseName],[QueryId],[PlanId],[QueryHash],[QueryPlanHash],[ObjectId],[ObjectName],[IsForcedPlan],[PlanForcingTypeDesc],[ForceFailureCount],[LastForceFailureReason],[LastForceFailureReasonDesc],[CountCompiles],[LastCompileStartTimeUtc],[LastExecutionTimeUtc],[EngineVersion],[CompatibilityLevel],[QuerySqlText],[QueryPlanTextFallback],[SourceType],[SourceObject],[CapturedAtUtc],[EvidenceScope],[QuerySqlTextCharacters],[QuerySqlTextBytes],[QuerySqlTextIsTruncated],[QueryPlanStatus],[QueryPlanCharacters],[QueryPlanBytes],CONVERT(nvarchar(max),[QueryPlan]) [QueryPlan],[EvidenceLimit] FROM [#QueryStoreForcedPlans_Result] ORDER BY CASE WHEN [LastForceFailureReason]<>0 THEN 0 ELSE 1 END,[LastExecutionTimeUtc] DESC FOR JSON PATH,INCLUDE_NULL_VALUES),@Warnings nvarchar(max)=(SELECT * FROM [#QueryStoreForcedPlans_Errors] ORDER BY [DatabaseName] FOR JSON PATH,INCLUDE_NULL_VALUES);SET @Json=CONCAT(N'{"meta":',COALESCE(@Meta,N'{}'),N',"forcedPlans":',COALESCE(@Data,N'[]'),N',"warnings":',COALESCE(@Warnings,N'[]'),N'}');END;
    IF @ConsoleResultRequested = 1
    BEGIN
        EXEC [monitor].[InternalEmitConsoleResult]
              @SourceTable=N'#QueryStoreForcedPlans_Result'
            , @ResultLabel=N'QueryStoreForcedPlans'
            , @EmptyMessage=N'Keine fachlichen Ergebnisse';
    END;
    IF @TableResultRequested = 1
    BEGIN
        EXEC [monitor].[InternalWriteResultTable]
              @SourceTable = N'#QueryStoreForcedPlans_Result'
            , @TargetTable=@TableTarget
            , @ThrowOnError = 1;
    END;
END;
GO
-- END SOURCE: Code/05_QueryStore/060_USP_QueryStoreForcedPlans.sql

-- BEGIN SOURCE: Code/05_QueryStore/070_USP_QueryStoreHints.sql
/*
===============================================================================
Objekt       : monitor.USP_QueryStoreHints
Version      : 2.0.0
Stand        : 2026-07-15
Zweck        : Liefert Query-Store-Hints aus einer oder mehreren
               Quelldatenbanken mit globaler Top-N-Ausgabe. Die Funktion ist
               ab SQL Server 2022 verfügbar.
===============================================================================
*/
CREATE OR ALTER PROCEDURE [monitor].[USP_QueryStoreHints]
      @QueryStoreDatabaseNames          nvarchar(max)  = NULL
    , @QueryStoreDatabaseNamePattern    nvarchar(4000) = NULL
    , @HighImpactConfirmed              bit            = 0
    , @QueryId                          bigint         = NULL
    , @NurMitFehler                     bit            = 0
    , @MaxZeilen                        int            = 100
    , @MaxSqlTextZeichen                int            = 4000
    , @ResultSetArt                     varchar(16)    = 'CONSOLE'
    , @ResultTablesJson               nvarchar(max) = NULL
    , @JsonErzeugen                     bit            = 0
    , @Json                             nvarchar(max)  = NULL OUTPUT
    , @PrintMeldungen                   bit            = 1
    , @Hilfe                            bit            = 0
AS
BEGIN
 SET NOCOUNT ON;SET @Json=NULL;DECLARE @Out varchar(16)=UPPER(LTRIM(RTRIM(COALESCE(@ResultSetArt,'')))),@Limit bigint=CASE WHEN @MaxZeilen IS NULL OR @MaxZeilen=0 THEN CONVERT(bigint,9223372036854775807) WHEN @MaxZeilen>0 THEN @MaxZeilen ELSE 0 END,@Local bigint=CASE WHEN @MaxZeilen IS NULL OR @MaxZeilen=0 THEN CONVERT(bigint,9223372036854775807) WHEN @MaxZeilen<2147483647 THEN CONVERT(bigint,@MaxZeilen)+1 ELSE @MaxZeilen END;
    DECLARE @TableResultRequested bit = CASE WHEN @Out = 'TABLE' THEN 1 ELSE 0 END;
    DECLARE @ConsoleResultRequested bit = CASE WHEN @Out = 'CONSOLE' THEN 1 ELSE 0 END;
    DECLARE @TableTarget sysname=NULL;
    IF @TableResultRequested=0 AND NULLIF(LTRIM(RTRIM(COALESCE(@ResultTablesJson,N''))),N'') IS NOT NULL THROW 51011,N'@ResultTablesJson ist ausschließlich mit @ResultSetArt=TABLE zulässig.',1;
    IF @TableResultRequested=1 EXEC [monitor].[InternalPrepareSingleResultTable] @ResultTablesJson=@ResultTablesJson,@ResultName=N'queryHints',@TargetTable=@TableTarget OUTPUT,@ThrowOnError=1;
    IF @TableResultRequested = 1 OR @ConsoleResultRequested = 1 SET @Out = 'NONE';
 IF @Hilfe=1 BEGIN PRINT N'monitor.USP_QueryStoreHints';PRINT N'Quell-DB-Liste/Pattern, globales @MaxZeilen, RAW|CONSOLE|TABLE|NONE und JSON.';RETURN;END;
 DECLARE @Now datetime2(3)=SYSUTCDATETIME(),@Status varchar(40)='AVAILABLE',@Partial bit=0,@Error nvarchar(2048)=NULL,@Cross bit=0,@Allowed bit=1,@Db sysname,@Sql nvarchar(max),@Count bigint=0,@HasMore bit=0,@Msg nvarchar(2048);
 CREATE TABLE [#QueryStoreHints_DatabaseCandidates]([DatabaseId] int NOT NULL,[DatabaseName] sysname COLLATE SQL_Latin1_General_CP1_CS_AS NOT NULL,[StateDesc] nvarchar(60) COLLATE SQL_Latin1_General_CP1_CS_AS,[UserAccessDesc] nvarchar(60) COLLATE SQL_Latin1_General_CP1_CS_AS,[IsReadOnly] bit,[CompatibilityLevel] tinyint,[CollationName] sysname COLLATE SQL_Latin1_General_CP1_CS_AS,[RecoveryModelDesc] nvarchar(60) COLLATE SQL_Latin1_General_CP1_CS_AS,[IsSystemDatabase] bit,[RequestedOrdinal] int);
 CREATE TABLE [#QueryStoreHints_Result]([QueryStoreDatabaseId] int,[QueryStoreDatabaseName] sysname COLLATE SQL_Latin1_General_CP1_CS_AS,[QueryHintId] bigint,[QueryId] bigint,[ReplicaGroupId] bigint,[QueryHash] binary(8),[QueryHintText] nvarchar(max) COLLATE SQL_Latin1_General_CP1_CS_AS,[LastQueryHintFailureReason] int,[LastQueryHintFailureReasonDesc] nvarchar(128) COLLATE SQL_Latin1_General_CP1_CS_AS,[QueryHintFailureCount] bigint,[Source] int,[SourceDesc] nvarchar(128) COLLATE SQL_Latin1_General_CP1_CS_AS,[QuerySqlText] nvarchar(max) COLLATE SQL_Latin1_General_CP1_CS_AS,[SourceType] varchar(32) COLLATE SQL_Latin1_General_CP1_CS_AS NULL,[SourceObject] nvarchar(256) COLLATE SQL_Latin1_General_CP1_CS_AS NULL,[CapturedAtUtc] datetime2(3) NULL,[EvidenceScope] varchar(40) COLLATE SQL_Latin1_General_CP1_CS_AS NULL,[IsCurrent] bit NULL,[QuerySqlTextCharacters] bigint NULL,[QuerySqlTextBytes] bigint NULL,[QuerySqlTextIsTruncated] bit NOT NULL DEFAULT(0),[EvidenceLimit] nvarchar(1000) COLLATE SQL_Latin1_General_CP1_CS_AS NULL);
 CREATE TABLE [#QueryStoreHints_Errors]([DatabaseName] sysname COLLATE SQL_Latin1_General_CP1_CS_AS,[StatusCode] varchar(40) COLLATE SQL_Latin1_General_CP1_CS_AS,[ErrorNumber] int NULL,[ErrorMessage] nvarchar(2048) COLLATE SQL_Latin1_General_CP1_CS_AS);
 IF TRY_CONVERT(int,SERVERPROPERTY(N'ProductMajorVersion'))<16 BEGIN SET @Status='UNAVAILABLE_VERSION';SET @Error=N'Query Store Hints sind erst ab SQL Server 2022 verfügbar.';END;
 IF @MaxZeilen<0 OR @MaxSqlTextZeichen < 0 OR @Out NOT IN('RAW','CONSOLE','NONE') BEGIN SET @Status='INVALID_PARAMETER';SET @Error=N'Ungültiger Parameter.';END;
 IF @Status='AVAILABLE' EXEC [monitor].[USP_PrepareDatabaseCandidates] @DatabaseNames=@QueryStoreDatabaseNames,@SystemdatenbankenEinbeziehen=0,@DatabaseNamePattern=@QueryStoreDatabaseNamePattern,@HighImpactConfirmed=@HighImpactConfirmed,@AnalysisClass='QUERY_STORE_CURRENT',@StatusCode=@Status OUTPUT,@ErrorMessage=@Error OUTPUT,@CrossDatabaseRequested=@Cross OUTPUT,@CandidateTable=N'#QueryStoreHints_DatabaseCandidates';
 IF @Status='AVAILABLE' AND @Limit>1000 EXEC [monitor].[InternalCheckAnalysisPath] @AnalysisClass='QUERY_STORE_DEEP',@HighImpactConfirmed=@HighImpactConfirmed,@StatusCode=@Status OUTPUT,@ErrorMessage=@Error OUTPUT;
 SET LOCK_TIMEOUT 0;
 IF @Status='AVAILABLE' BEGIN DECLARE [c] CURSOR LOCAL FAST_FORWARD FOR SELECT [DatabaseName] FROM [#QueryStoreHints_DatabaseCandidates] ORDER BY COALESCE([RequestedOrdinal],[DatabaseId]),[DatabaseId];OPEN [c];FETCH NEXT FROM [c] INTO @Db;WHILE @@FETCH_STATUS=0 BEGIN BEGIN TRY SET @Sql=N'USE '+QUOTENAME(@Db)+N';IF EXISTS(SELECT 1 FROM [sys].[all_objects] AS [o] WITH (NOLOCK) JOIN [sys].[schemas] AS [s] WITH (NOLOCK) ON [s].[schema_id]=[o].[schema_id] WHERE [s].[name]=N''sys'' AND [o].[name]=N''query_store_query_hints'') INSERT [#QueryStoreHints_Result]([QueryStoreDatabaseId],[QueryStoreDatabaseName],[QueryHintId],[QueryId],[ReplicaGroupId],[QueryHash],[QueryHintText],[LastQueryHintFailureReason],[LastQueryHintFailureReasonDesc],[QueryHintFailureCount],[Source],[SourceDesc],[QuerySqlText]) SELECT TOP(@TopRows) DB_ID(),(SELECT [name] FROM [master].[sys].[databases] WITH (NOLOCK) WHERE [database_id] = DB_ID()),[h].[query_hint_id],[h].[query_id],[h].[replica_group_id],[q].[query_hash],[h].[query_hint_text],[h].[last_query_hint_failure_reason],[h].[last_query_hint_failure_reason_desc],[h].[query_hint_failure_count],[h].[source],[h].[source_desc],[qt].[query_sql_text] FROM [sys].[query_store_query_hints] [h] WITH (NOLOCK) LEFT JOIN [sys].[query_store_query] [q] WITH (NOLOCK) ON [q].[query_id]=[h].[query_id] LEFT JOIN [sys].[query_store_query_text] [qt] WITH (NOLOCK) ON [qt].[query_text_id]=[q].[query_text_id] WHERE (@QueryId IS NULL OR [h].[query_id]=@QueryId) AND (@OnlyErrors=0 OR [h].[query_hint_failure_count]>0 OR [h].[last_query_hint_failure_reason]<>0) ORDER BY CASE WHEN [h].[last_query_hint_failure_reason]<>0 THEN 0 ELSE 1 END,[h].[query_hint_failure_count] DESC,[h].[query_hint_id];';EXEC [sys].[sp_executesql] @Sql,N'@TopRows bigint,@QueryId bigint,@OnlyErrors bit',@Local,@QueryId,@NurMitFehler;END TRY BEGIN CATCH INSERT [#QueryStoreHints_Errors] VALUES(@Db,CASE WHEN ERROR_NUMBER() IN(229,262,297,300,371,916) THEN 'DENIED_PERMISSION' WHEN ERROR_NUMBER()=1222 THEN 'TIMEOUT' WHEN ERROR_NUMBER() IN(207,208) THEN 'UNAVAILABLE_OBJECT' ELSE 'ERROR_HANDLED' END,ERROR_NUMBER(),ERROR_MESSAGE());SET @Partial=1;IF @PrintMeldungen=1 BEGIN SET @Msg=FORMATMESSAGE(N'WARNUNG USP_QueryStoreHints [%s]: %s',@Db,ERROR_MESSAGE());RAISERROR(N'%s',10,1,@Msg) WITH NOWAIT;END;END CATCH;FETCH NEXT FROM [c] INTO @Db;END;CLOSE [c];DEALLOCATE [c];END;
 UPDATE [#QueryStoreHints_Result]
 SET [SourceType]='QUERY_STORE',[SourceObject]=N'sys.query_store_query_hints|sys.query_store_query_text',
     [CapturedAtUtc]=@Now,[EvidenceScope]='DATABASE_QUERY_HINT',[IsCurrent]=1,
     [EvidenceLimit]=N'Aktueller gespeicherter Query-Store-Hintstatus; keine Aussage über die Wirksamkeit jeder zukünftigen Ausführung.';
 DECLARE @TruncatedValueCount bigint=0,@LargestRequiredCharacters bigint=NULL;
 EXEC [monitor].[InternalProjectUnicodeTextColumn] @SourceTable=N'#QueryStoreHints_Result',@TextColumn=N'QuerySqlText',@CharactersColumn=N'QuerySqlTextCharacters',@BytesColumn=N'QuerySqlTextBytes',@IsTruncatedColumn=N'QuerySqlTextIsTruncated',@MaxCharacters=@MaxSqlTextZeichen,@TruncatedValueCount=@TruncatedValueCount OUTPUT,@LargestRequiredCharacters=@LargestRequiredCharacters OUTPUT;
 EXEC [monitor].[InternalEmitTruncationWarning] @TruncatedValueCount=@TruncatedValueCount,@ParameterName=N'@MaxSqlTextZeichen',@ParameterValue=@MaxSqlTextZeichen,@LargestRequiredCharacters=@LargestRequiredCharacters,@PrintMeldungen=@PrintMeldungen;
 SELECT @Count=COUNT_BIG(*) FROM [#QueryStoreHints_Result];SET @HasMore=CONVERT(bit,CASE WHEN @Limit<9223372036854775807 AND @Count>@Limit THEN 1 ELSE 0 END);IF @Partial=1 AND @Status='AVAILABLE' SET @Status='AVAILABLE_LIMITED';
 IF @Out<>'NONE' BEGIN SELECT N'USP_QueryStoreHints' [ModuleName],@Now [CollectionTimeUtc],@Status [StatusCode],@Partial [IsPartial],CASE WHEN @Count>@Limit THEN @Limit ELSE @Count END [ReturnedRowCount],@HasMore [HasMoreRows],@Error [ErrorMessage];IF @Out='RAW' SELECT TOP(@Limit) * FROM [#QueryStoreHints_Result] ORDER BY CASE WHEN [LastQueryHintFailureReason]<>0 THEN 0 ELSE 1 END,[QueryHintFailureCount] DESC,[QueryHintId];ELSE SELECT TOP(@Limit) N'Query-Store Hint' [Ergebnis],[QueryStoreDatabaseName] [Query-Store-Datenbank],[QueryId] [Query],[QueryHintText] [Hint],[LastQueryHintFailureReasonDesc] [letzter Fehler],[QueryHintFailureCount] [Fehleranzahl],[QueryStoreDatabaseName] [Quelle],[QuerySqlText] [SQL-Text] FROM [#QueryStoreHints_Result] ORDER BY CASE WHEN [LastQueryHintFailureReason]<>0 THEN 0 ELSE 1 END,[QueryHintFailureCount] DESC,[QueryHintId];SELECT * FROM [#QueryStoreHints_Errors] ORDER BY [DatabaseName];END;
 IF @JsonErzeugen=1 BEGIN DECLARE @Meta nvarchar(max)=(SELECT N'QueryStoreHints' [resultName],1 [schemaVersion],@Now [generatedAtUtc],@Status [statusCode],@MaxZeilen [requestedMaxRows],CASE WHEN @Count>@Limit THEN @Limit ELSE @Count END [returnedRows],@HasMore [hasMoreRows] FOR JSON PATH,WITHOUT_ARRAY_WRAPPER,INCLUDE_NULL_VALUES),@Data nvarchar(max)=(SELECT TOP(@Limit) * FROM [#QueryStoreHints_Result] ORDER BY CASE WHEN [LastQueryHintFailureReason]<>0 THEN 0 ELSE 1 END,[QueryHintFailureCount] DESC,[QueryHintId] FOR JSON PATH,INCLUDE_NULL_VALUES),@Warnings nvarchar(max)=(SELECT * FROM [#QueryStoreHints_Errors] ORDER BY [DatabaseName] FOR JSON PATH,INCLUDE_NULL_VALUES);SET @Json=CONCAT(N'{"meta":',COALESCE(@Meta,N'{}'),N',"queryHints":',COALESCE(@Data,N'[]'),N',"warnings":',COALESCE(@Warnings,N'[]'),N'}');END;
    IF @ConsoleResultRequested = 1
    BEGIN
        EXEC [monitor].[InternalEmitConsoleResult]
              @SourceTable=N'#QueryStoreHints_Result'
            , @ResultLabel=N'QueryStoreHints'
            , @EmptyMessage=N'Keine fachlichen Ergebnisse';
    END;
    IF @TableResultRequested = 1
    BEGIN
        EXEC [monitor].[InternalWriteResultTable]
              @SourceTable = N'#QueryStoreHints_Result'
            , @TargetTable=@TableTarget
            , @ThrowOnError = 1;
    END;
END;
GO
-- END SOURCE: Code/05_QueryStore/070_USP_QueryStoreHints.sql

-- BEGIN SOURCE: Code/05_QueryStore/090_USP_IntelligentQueryProcessingAnalysis.sql
/*
===============================================================================
Objekt       : monitor.USP_IntelligentQueryProcessingAnalysis
Version      : 1.0.0
Stand        : 2026-07-17
Zweck        : Dokumentiert IQP-Voraussetzungen, Query-Store-Feedback,
               Query-Varianten und Automatic-Tuning-Evidenz je Datenbank.
Datenquellen : sys.database_query_store_options,
               sys.database_scoped_configurations,
               sys.query_store_query_variant,
               sys.query_store_plan_feedback,
               sys.database_automatic_tuning_options und
               sys.dm_db_tuning_recommendations.
Datenschutz  : Liest weder Query-Text noch Showplan, Objekt- oder Benutzerdaten.
Grenzen      : Vorhandene oder fehlende Feedbackzeilen beweisen weder Nutzen
               noch Fehler. Verfügbarkeit wird versionsadaptiv ausgewiesen.
===============================================================================
*/
CREATE OR ALTER PROCEDURE [monitor].[USP_IntelligentQueryProcessingAnalysis]
      @DatabaseNames                nvarchar(max)  = NULL
    , @SystemdatenbankenEinbeziehen bit            = 0
    , @DatabaseNamePattern          nvarchar(4000) = NULL
    , @HighImpactConfirmed              bit            = 0
    , @MaxZeilen                    int            = 1000
    , @ResultSetArt                 varchar(16)    = 'CONSOLE'
    , @ResultTablesJson               nvarchar(max) = NULL
    , @JsonErzeugen                 bit            = 0
    , @Json                         nvarchar(max)  = NULL OUTPUT
    , @PrintMeldungen               bit            = 1
    , @Hilfe                        bit            = 0
    , @StatusCodeOut                varchar(40)    = NULL OUTPUT
    , @IsPartialOut                 bit            = NULL OUTPUT
    , @ErrorNumberOut               int            = NULL OUTPUT
    , @ErrorMessageOut              nvarchar(2048) = NULL OUTPUT
AS
BEGIN
    SET NOCOUNT ON;
    SET @Json = NULL;

    DECLARE @OutputMode varchar(16) =
        UPPER(LTRIM(RTRIM(COALESCE(@ResultSetArt, ''))));
    DECLARE @TableResultRequested bit = CASE WHEN @OutputMode = 'TABLE' THEN 1 ELSE 0 END;
    DECLARE @ConsoleResultRequested bit = CASE WHEN @OutputMode = 'CONSOLE' THEN 1 ELSE 0 END;
    DECLARE @TableTarget sysname=NULL;
    IF @TableResultRequested=0 AND NULLIF(LTRIM(RTRIM(COALESCE(@ResultTablesJson,N''))),N'') IS NOT NULL THROW 51011,N'@ResultTablesJson ist ausschließlich mit @ResultSetArt=TABLE zulässig.',1;
    IF @TableResultRequested=1 EXEC [monitor].[InternalPrepareSingleResultTable] @ResultTablesJson=@ResultTablesJson,@ResultName=N'signals',@TargetTable=@TableTarget OUTPUT,@ThrowOnError=1;
    IF @TableResultRequested = 1 OR @ConsoleResultRequested = 1 SET @OutputMode = 'NONE';
    DECLARE @Limit bigint =
        CASE WHEN @MaxZeilen IS NULL OR @MaxZeilen = 0
             THEN CONVERT(bigint, 9223372036854775807)
             ELSE CONVERT(bigint, @MaxZeilen) END;

    IF @Hilfe = 1
    BEGIN
        PRINT N'monitor.USP_IntelligentQueryProcessingAnalysis';
        PRINT N'Liest nur IQP-Konfiguration und aggregierte Evidenz; niemals Query-Text oder Showplan.';
        PRINT N'@DatabaseNames: bracket-aware Pipe-Liste; N''''/NULL = keine Datenbankeinschränkung.';
        PRINT N'@MaxZeilen positiv; NULL/0 = unbegrenzt. @ResultSetArt=CONSOLE|RAW|TABLE|NONE; TABLE verwendet @ResultTablesJson.';
        RETURN;
    END;

    DECLARE @Now datetime2(3) = SYSUTCDATETIME();
    DECLARE @StatusCode varchar(40) = 'AVAILABLE';
    DECLARE @IsPartial bit = 0;
    DECLARE @ErrorNumber int = NULL;
    DECLARE @ErrorMessage nvarchar(2048) = NULL;
    DECLARE @CrossDatabaseRequested bit = 0;
    DECLARE @Db sysname;
    DECLARE @Sql nvarchar(max);
    DECLARE @ProductMajorVersion int = TRY_CONVERT(int, SERVERPROPERTY(N'ProductMajorVersion'));

    CREATE TABLE [#IntelligentQueryProcessingAnalysis_DatabaseCandidates]
    (
          [DatabaseId] int NOT NULL PRIMARY KEY
        , [DatabaseName] sysname NOT NULL
        , [StateDesc] nvarchar(60) NULL
        , [UserAccessDesc] nvarchar(60) NULL
        , [IsReadOnly] bit NULL
        , [CompatibilityLevel] tinyint NULL
        , [CollationName] sysname NULL
        , [RecoveryModelDesc] nvarchar(60) NULL
        , [IsSystemDatabase] bit NULL
        , [RequestedOrdinal] int NULL
    );

    CREATE TABLE [#IntelligentQueryProcessingAnalysis_DatabaseCandidateWarnings]
    (
          [RequestedName] sysname NULL
        , [StatusCode] varchar(40) NOT NULL
        , [ErrorMessage] nvarchar(2048) NULL
    );

    CREATE TABLE [#IntelligentQueryProcessingAnalysis_DatabaseState]
    (
          [DatabaseId] int NOT NULL
        , [DatabaseName] sysname NOT NULL
        , [CompatibilityLevel] tinyint NULL
        , [QueryStoreActualStateDesc] nvarchar(60) NULL
        , [QueryStoreDesiredStateDesc] nvarchar(60) NULL
        , [QueryStoreReadonlyReason] bigint NULL
        , [PspEligible] bit NOT NULL
        , [OppoEligible] bit NOT NULL
        , [FindingCode] varchar(80) NOT NULL
        , [FindingSeverity] varchar(16) NOT NULL
        , [EvidenceLimit] nvarchar(1000) NOT NULL
    );

    CREATE TABLE [#IntelligentQueryProcessingAnalysis_Configuration]
    (
          [DatabaseId] int NOT NULL
        , [DatabaseName] sysname NOT NULL
        , [ConfigurationName] sysname NOT NULL
        , [ConfigurationValue] nvarchar(4000) NULL
        , [IsValueDefault] bit NULL
    );

    CREATE TABLE [#IntelligentQueryProcessingAnalysis_AutomaticTuning]
    (
          [DatabaseId] int NOT NULL
        , [DatabaseName] sysname NOT NULL
        , [OptionName] nvarchar(60) NOT NULL
        , [DesiredStateDesc] nvarchar(60) NULL
        , [ActualStateDesc] nvarchar(60) NULL
        , [ReasonDesc] nvarchar(120) NULL
    );

    CREATE TABLE [#IntelligentQueryProcessingAnalysis_Signals]
    (
          [DatabaseId] int NOT NULL
        , [DatabaseName] sysname NOT NULL
        , [SignalCode] varchar(80) NOT NULL
        , [IsSourceAvailable] bit NOT NULL
        , [EvidenceCount] bigint NULL
        , [Interpretation] nvarchar(1000) NOT NULL
    );

    CREATE TABLE [#IntelligentQueryProcessingAnalysis_Errors]
    (
          [DatabaseName] sysname NULL
        , [StatusCode] varchar(40) NOT NULL
        , [ErrorNumber] int NULL
        , [ErrorMessage] nvarchar(2048) NULL
    );

    IF @MaxZeilen < 0
       OR @OutputMode NOT IN ('RAW', 'CONSOLE', 'NONE')
    BEGIN
        SELECT @StatusCode = 'INVALID_PARAMETER',
               @IsPartial = 1,
               @ErrorMessage = N'Ungültiger Datenbank-, Zeilen- oder Ausgabeparameter.';
    END;

    IF @StatusCode = 'AVAILABLE'
    BEGIN
        EXEC [monitor].[USP_PrepareDatabaseCandidates]
              @DatabaseNames = @DatabaseNames
            , @SystemdatenbankenEinbeziehen = @SystemdatenbankenEinbeziehen
            , @DatabaseNamePattern = @DatabaseNamePattern,@HighImpactConfirmed=@HighImpactConfirmed

            , @AnalysisClass = 'CATALOG_DEEP'
            , @StatusCode = @StatusCode OUTPUT
            , @ErrorMessage = @ErrorMessage OUTPUT
            , @CrossDatabaseRequested = @CrossDatabaseRequested OUTPUT,@CandidateTable=N'#IntelligentQueryProcessingAnalysis_DatabaseCandidates',@WarningTable=N'#IntelligentQueryProcessingAnalysis_DatabaseCandidateWarnings';
    END;

    SET LOCK_TIMEOUT 0;

    IF @StatusCode = 'AVAILABLE'
    BEGIN
        DECLARE [database_cursor] CURSOR LOCAL FAST_FORWARD FOR
            SELECT [DatabaseName]
            FROM [#IntelligentQueryProcessingAnalysis_DatabaseCandidates]
            ORDER BY COALESCE([RequestedOrdinal], [DatabaseId]), [DatabaseId];

        OPEN [database_cursor];
        FETCH NEXT FROM [database_cursor] INTO @Db;

        WHILE @@FETCH_STATUS = 0
        BEGIN
            BEGIN TRY
                SET @Sql = N'USE ' + QUOTENAME(@Db) + N';
DECLARE @DatabaseId int = DB_ID();
DECLARE @DatabaseName sysname = (SELECT [name] FROM [master].[sys].[databases] WITH (NOLOCK) WHERE [database_id] = DB_ID());
DECLARE @CompatibilityLevel tinyint =
    (SELECT [compatibility_level] FROM [sys].[databases] WITH (NOLOCK) WHERE [database_id] = DB_ID());
DECLARE @ActualStateDesc nvarchar(60) = NULL;
DECLARE @DesiredStateDesc nvarchar(60) = NULL;
DECLARE @ReadonlyReason bigint = NULL;

SELECT TOP (1)
      @ActualStateDesc = [actual_state_desc]
    , @DesiredStateDesc = [desired_state_desc]
    , @ReadonlyReason = [readonly_reason]
FROM [sys].[database_query_store_options] WITH (NOLOCK);

INSERT [#IntelligentQueryProcessingAnalysis_DatabaseState]
(
      [DatabaseId], [DatabaseName], [CompatibilityLevel]
    , [QueryStoreActualStateDesc], [QueryStoreDesiredStateDesc]
    , [QueryStoreReadonlyReason], [PspEligible], [OppoEligible]
    , [FindingCode], [FindingSeverity], [EvidenceLimit]
)
SELECT
      @DatabaseId, @DatabaseName, @CompatibilityLevel
    , @ActualStateDesc, @DesiredStateDesc, @ReadonlyReason
    , CONVERT(bit, CASE WHEN @ProductMajorVersion >= 16 AND @CompatibilityLevel >= 160 THEN 1 ELSE 0 END)
    , CONVERT(bit, CASE WHEN @ProductMajorVersion >= 17 AND @CompatibilityLevel >= 170 THEN 1 ELSE 0 END)
    , CASE WHEN COALESCE(@ActualStateDesc, N''OFF'') = N''OFF'' THEN ''QUERY_STORE_OFF''
           WHEN @ActualStateDesc = N''READ_ONLY'' AND @DesiredStateDesc = N''READ_WRITE'' THEN ''QUERY_STORE_READ_ONLY''
           WHEN @CompatibilityLevel < 150 THEN ''IQP_COMPATIBILITY_BELOW_150''
           ELSE ''IQP_EVIDENCE_AVAILABLE'' END
    , CASE WHEN COALESCE(@ActualStateDesc, N''OFF'') = N''OFF'' THEN ''HIGH''
           WHEN @ActualStateDesc = N''READ_ONLY'' AND @DesiredStateDesc = N''READ_WRITE'' THEN ''MEDIUM''
           ELSE ''INFO'' END
    , N''Feature-Eignung folgt Version und Compatibility Level; Evidenzmengen allein bewerten keine Wirksamkeit.'';

INSERT [#IntelligentQueryProcessingAnalysis_Configuration]
(
      [DatabaseId], [DatabaseName], [ConfigurationName]
    , [ConfigurationValue], [IsValueDefault]
)
SELECT
      @DatabaseId, @DatabaseName, [name]
    , CONVERT(nvarchar(4000), [value]), [is_value_default]
FROM [sys].[database_scoped_configurations] WITH (NOLOCK)
WHERE [name] IN
(
      N''PARAMETER_SENSITIVE_PLAN_OPTIMIZATION''
    , N''OPTIONAL_PARAMETER_OPTIMIZATION''
    , N''MEMORY_GRANT_FEEDBACK_PERSISTENCE''
    , N''MEMORY_GRANT_FEEDBACK_PERCENTILE_GRANT''
    , N''DOP_FEEDBACK''
    , N''CE_FEEDBACK''
    , N''BATCH_MODE_MEMORY_GRANT_FEEDBACK''
    , N''ROW_MODE_MEMORY_GRANT_FEEDBACK''
    , N''BATCH_MODE_ADAPTIVE_JOINS''
    , N''INTERLEAVED_EXECUTION_TVF''
    , N''DEFERRED_COMPILATION_TV''
);';

                IF @ProductMajorVersion >= 16
                BEGIN
                    SET @Sql += N'
    INSERT [#IntelligentQueryProcessingAnalysis_Signals]
    SELECT @DatabaseId, @DatabaseName, ''QUERY_VARIANTS'', 1, COUNT_BIG(*),
           N''Aggregierte PSP-/OPPO-Varianten; null Zeilen sind kein Fehlerbeweis.''
    FROM [sys].[query_store_query_variant] WITH (NOLOCK);

    INSERT [#IntelligentQueryProcessingAnalysis_Signals]
    SELECT @DatabaseId, @DatabaseName, ''PLAN_FEEDBACK'', 1, COUNT_BIG(*),
           N''Aggregierte CE-, Memory-Grant-, DOP- oder LAQ-Feedbackevidenz; keine Query-Texte.''
    FROM [sys].[query_store_plan_feedback] WITH (NOLOCK);';
                END
                ELSE
                BEGIN
                    SET @Sql += N'
INSERT [#IntelligentQueryProcessingAnalysis_Signals] VALUES
(@DatabaseId, @DatabaseName, ''QUERY_VARIANTS'', 0, NULL,
 N''Katalogsicht ist vor SQL Server 2022 nicht verfügbar.''),
(@DatabaseId, @DatabaseName, ''PLAN_FEEDBACK'', 0, NULL,
 N''Katalogsicht ist vor SQL Server 2022 nicht verfügbar.'');';
                END;

                SET @Sql += N'
    INSERT [#IntelligentQueryProcessingAnalysis_AutomaticTuning]
    (
          [DatabaseId], [DatabaseName], [OptionName]
        , [DesiredStateDesc], [ActualStateDesc], [ReasonDesc]
    )
    SELECT @DatabaseId, @DatabaseName, [name], [desired_state_desc],
           [actual_state_desc], [reason_desc]
    FROM [sys].[database_automatic_tuning_options] WITH (NOLOCK);

    INSERT [#IntelligentQueryProcessingAnalysis_Signals]
    SELECT @DatabaseId, @DatabaseName, ''TUNING_RECOMMENDATIONS'', 1, COUNT_BIG(*),
           N''Anzahl aktueller Automatic-Tuning-Empfehlungen; Details und SQL-Texte werden nicht gelesen.''
    FROM [sys].[dm_db_tuning_recommendations] WITH (NOLOCK);';

                EXEC [sys].[sp_executesql]
                      @Sql
                    , N'@ProductMajorVersion int'
                    , @ProductMajorVersion = @ProductMajorVersion;
            END TRY
            BEGIN CATCH
                INSERT [#IntelligentQueryProcessingAnalysis_Errors]
                VALUES
                (
                      @Db
                    , CASE WHEN ERROR_NUMBER() IN (229, 262, 297, 300, 371, 916)
                           THEN 'DENIED_PERMISSION' ELSE 'ERROR_HANDLED' END
                    , ERROR_NUMBER()
                    , ERROR_MESSAGE()
                );
                SET @IsPartial = 1;
            END CATCH;

            FETCH NEXT FROM [database_cursor] INTO @Db;
        END;

        CLOSE [database_cursor];
        DEALLOCATE [database_cursor];

        INSERT [#IntelligentQueryProcessingAnalysis_Errors]
        SELECT [RequestedName], [StatusCode], NULL, [ErrorMessage]
        FROM [#IntelligentQueryProcessingAnalysis_DatabaseCandidateWarnings];

        IF EXISTS (SELECT 1 FROM [#IntelligentQueryProcessingAnalysis_Errors])
            SET @IsPartial = 1;

        IF NOT EXISTS (SELECT 1 FROM [#IntelligentQueryProcessingAnalysis_DatabaseState])
        BEGIN
            SELECT @StatusCode = CASE WHEN EXISTS
                   (SELECT 1 FROM [#IntelligentQueryProcessingAnalysis_Errors] WHERE [StatusCode] = 'DENIED_PERMISSION')
                   THEN 'DENIED_PERMISSION' ELSE 'DATABASE_UNAVAILABLE' END,
                   @IsPartial = 1;
        END
        ELSE IF @IsPartial = 1
            SET @StatusCode = 'AVAILABLE_LIMITED';
        ELSE IF EXISTS
                (SELECT 1 FROM [#IntelligentQueryProcessingAnalysis_DatabaseState] WHERE [FindingCode] <> 'IQP_EVIDENCE_AVAILABLE')
            SET @StatusCode = 'AVAILABLE_WITH_FINDING';
    END;

    SELECT @StatusCodeOut = @StatusCode,
           @IsPartialOut = @IsPartial,
           @ErrorNumberOut = @ErrorNumber,
           @ErrorMessageOut = @ErrorMessage;

    IF @JsonErzeugen = 1
    BEGIN
        DECLARE @MetaJson nvarchar(max) =
        (
            SELECT N'IntelligentQueryProcessingAnalysis' AS [resultName],
                   1 AS [schemaVersion], @Now AS [generatedAtUtc],
                   @StatusCode AS [statusCode], @IsPartial AS [isPartial]
            FOR JSON PATH, WITHOUT_ARRAY_WRAPPER
        );
        DECLARE @StateJson nvarchar(max) =
            (SELECT TOP (@Limit) * FROM [#IntelligentQueryProcessingAnalysis_DatabaseState]
             ORDER BY [DatabaseId] FOR JSON PATH, INCLUDE_NULL_VALUES);
        DECLARE @ConfigurationJson nvarchar(max) =
            (SELECT TOP (@Limit) * FROM [#IntelligentQueryProcessingAnalysis_Configuration]
             ORDER BY [DatabaseId], [ConfigurationName]
             FOR JSON PATH, INCLUDE_NULL_VALUES);
        DECLARE @AutomaticTuningJson nvarchar(max) =
            (SELECT TOP (@Limit) * FROM [#IntelligentQueryProcessingAnalysis_AutomaticTuning]
             ORDER BY [DatabaseId], [OptionName]
             FOR JSON PATH, INCLUDE_NULL_VALUES);
        DECLARE @SignalsJson nvarchar(max) =
            (SELECT TOP (@Limit) * FROM [#IntelligentQueryProcessingAnalysis_Signals]
             ORDER BY [DatabaseId], [SignalCode]
             FOR JSON PATH, INCLUDE_NULL_VALUES);
        DECLARE @WarningsJson nvarchar(max) =
            (SELECT * FROM [#IntelligentQueryProcessingAnalysis_Errors] ORDER BY [DatabaseName]
             FOR JSON PATH, INCLUDE_NULL_VALUES);

        SET @Json = CONCAT
        (
              N'{"meta":', COALESCE(@MetaJson, N'{}')
            , N',"databaseState":', COALESCE(@StateJson, N'[]')
            , N',"configuration":', COALESCE(@ConfigurationJson, N'[]')
            , N',"automaticTuning":', COALESCE(@AutomaticTuningJson, N'[]')
            , N',"signals":', COALESCE(@SignalsJson, N'[]')
            , N',"warnings":', COALESCE(@WarningsJson, N'[]'), N'}'
        );
    END;

    IF @OutputMode = 'RAW'
    BEGIN
        SELECT N'USP_IntelligentQueryProcessingAnalysis' AS [ModuleName],
               @Now AS [CollectionTimeUtc], @StatusCode AS [StatusCode],
               @IsPartial AS [IsPartial], @ProductMajorVersion AS [ProductMajorVersion],
               @ErrorNumber AS [ErrorNumber], @ErrorMessage AS [ErrorMessage],
               N'Read-only; keine Query-Texte oder Showplans.' AS [Detail];
        SELECT TOP (@Limit) * FROM [#IntelligentQueryProcessingAnalysis_DatabaseState] ORDER BY [DatabaseId];
        SELECT TOP (@Limit) * FROM [#IntelligentQueryProcessingAnalysis_Configuration] ORDER BY [DatabaseId], [ConfigurationName];
        SELECT TOP (@Limit) * FROM [#IntelligentQueryProcessingAnalysis_AutomaticTuning] ORDER BY [DatabaseId], [OptionName];
        SELECT TOP (@Limit) * FROM [#IntelligentQueryProcessingAnalysis_Signals] ORDER BY [DatabaseId], [SignalCode];
        SELECT * FROM [#IntelligentQueryProcessingAnalysis_Errors] ORDER BY [DatabaseName];
    END
    ELSE IF @OutputMode = 'CONSOLE'
    BEGIN
        SELECT N'Intelligent Query Processing' AS [Ergebnis], @Now AS [Stand_UTC],
               @StatusCode AS [Status], @IsPartial AS [Teilweise],
               (SELECT COUNT_BIG(*) FROM [#IntelligentQueryProcessingAnalysis_DatabaseState]) AS [Datenbanken],
               N'Aggregierte Evidenz ohne Query-Text oder Showplan.' AS [Hinweis];

        SELECT TOP (@Limit)
               N'IQP-Datenbankstatus' AS [Ergebnis], [DatabaseName] AS [Datenbank],
               [CompatibilityLevel] AS [Compatibility_Level],
               [QueryStoreActualStateDesc] AS [Query_Store],
               [PspEligible] AS [PSP_geeignet], [OppoEligible] AS [OPPO_geeignet],
               [FindingCode] AS [Befund], [FindingSeverity] AS [Prioritaet],
               [EvidenceLimit] AS [Grenze]
        FROM [#IntelligentQueryProcessingAnalysis_DatabaseState]
        ORDER BY [DatabaseId];

        SELECT TOP (@Limit)
               N'IQP-Signal' AS [Ergebnis], [DatabaseName] AS [Datenbank],
               [SignalCode] AS [Signal], [IsSourceAvailable] AS [Quelle_verfuegbar],
               [EvidenceCount] AS [Anzahl], [Interpretation]
        FROM [#IntelligentQueryProcessingAnalysis_Signals]
        ORDER BY [DatabaseId], [SignalCode];

        SELECT N'IQP-Warnung' AS [Ergebnis], [DatabaseName] AS [Datenbank],
               [StatusCode] AS [Status], [ErrorNumber] AS [Fehlernummer],
               [ErrorMessage] AS [Meldung]
        FROM [#IntelligentQueryProcessingAnalysis_Errors]
        ORDER BY [DatabaseName];
    END;
    IF @ConsoleResultRequested = 1
    BEGIN
        EXEC [monitor].[InternalEmitConsoleResult]
              @SourceTable=N'#IntelligentQueryProcessingAnalysis_Signals'
            , @ResultLabel=N'IntelligentQueryProcessingAnalysis'
            , @EmptyMessage=N'Keine fachlichen Ergebnisse';
    END;
    IF @TableResultRequested = 1
    BEGIN
        EXEC [monitor].[InternalWriteResultTable]
              @SourceTable = N'#IntelligentQueryProcessingAnalysis_Signals'
            , @TargetTable=@TableTarget
            , @ThrowOnError = 1;
    END;
END;
GO
-- END SOURCE: Code/05_QueryStore/090_USP_IntelligentQueryProcessingAnalysis.sql

-- BEGIN SOURCE: Code/05_QueryStore/100_USP_QueryStoreReplicaAnalysis.sql
/*
===============================================================================
Objekt       : monitor.USP_QueryStoreReplicaAnalysis
Version      : 1.0.0
Stand        : 2026-07-27
Typ          : Stored Procedure
Zweck        : Trennt Query-Store-Laufzeit-, Wait- und Plan-Forcing-Evidenz
               nach replica_group_id und ordnet beobachtete Rollen zu.
SQL-Version  : SQL Server 2019 oder neuer; Replica-Kataloge ab SQL Server 2025.
Datenquellen : sys.database_query_store_options, sys.query_store_replicas,
               sys.query_store_runtime_stats, sys.query_store_wait_stats,
               sys.query_store_plan_forcing_locations.
Abgrenzung   : Keine Querytexte, Plan-XML, Hints, Identitäten oder Nutzdaten.
               Beobachtete Rollen sind historischer Query-Store-Kontext und
               keine aktuelle Verfügbarkeits-, Synchronitäts- oder Healthaussage.
Eigenlast    : LOW_MEDIUM. Jede unterstützte Quelle wird je Datenbank höchstens
               einmal gelesen; Zeitfenster, Datenbankscope und Zeilenlimit gelten.
Locking      : Konfigurierbarer LOCK_TIMEOUT; ursprünglicher Wert wird restauriert.
===============================================================================
*/
CREATE OR ALTER PROCEDURE [monitor].[USP_QueryStoreReplicaAnalysis]
      @QueryStoreDatabaseNames          nvarchar(max)  = NULL
    , @QueryStoreDatabaseNamePattern    nvarchar(4000) = NULL
    , @HighImpactConfirmed              bit            = 0
    , @ReplicaGroupIds                  nvarchar(max)  = NULL
    , @VonUtc                           datetime2(7)   = NULL
    , @BisUtc                           datetime2(7)   = NULL
    , @MaxZeilen                        int            = 200
    , @LockTimeoutMs                    int            = 0
    , @ResultSetArt                     varchar(16)    = 'CONSOLE'
    , @ResultTablesJson                 nvarchar(max)  = NULL
    , @JsonErzeugen                     bit            = 0
    , @Json                             nvarchar(max)  = NULL OUTPUT
    , @PrintMeldungen                   bit            = 1
    , @Hilfe                            bit            = 0
    , @StatusCodeOut                    varchar(40)    = NULL OUTPUT
    , @IsPartialOut                     bit            = NULL OUTPUT
    , @ErrorNumberOut                   int            = NULL OUTPUT
    , @ErrorMessageOut                  nvarchar(2048) = NULL OUTPUT
AS
BEGIN
    SET NOCOUNT ON;
    SET @Json=NULL;

    DECLARE @CapturedAtUtc datetime2(3)=SYSUTCDATETIME();
    DECLARE @ProductMajorVersion int=TRY_CONVERT(int,SERVERPROPERTY(N'ProductMajorVersion'));
    DECLARE @OutputMode varchar(16)=UPPER(LTRIM(RTRIM(COALESCE(@ResultSetArt,''))));
    DECLARE @ConsoleResultRequested bit=CONVERT(bit,CASE WHEN @OutputMode='CONSOLE' THEN 1 ELSE 0 END);
    IF @ConsoleResultRequested=1 SET @OutputMode='NONE';
    DECLARE @StatusCode varchar(40)='AVAILABLE';
    DECLARE @IsPartial bit=0;
    DECLARE @ErrorNumber int=NULL;
    DECLARE @ErrorMessage nvarchar(2048)=NULL;
    DECLARE @CrossDatabaseRequested bit=0;
    DECLARE @OriginalLockTimeout int=@@LOCK_TIMEOUT;
    DECLARE @LockTimeoutSql nvarchar(64);
    DECLARE @Limit bigint=CASE WHEN @MaxZeilen IS NULL OR @MaxZeilen=0
                               THEN CONVERT(bigint,9223372036854775807)
                               ELSE CONVERT(bigint,@MaxZeilen) END;
    DECLARE @LocalLimit bigint=CASE WHEN @MaxZeilen IS NULL OR @MaxZeilen=0
                                    THEN CONVERT(bigint,9223372036854775807)
                                    WHEN @MaxZeilen<2147483647 THEN CONVERT(bigint,@MaxZeilen)+1
                                    ELSE CONVERT(bigint,@MaxZeilen) END;

    IF @Hilfe=1
    BEGIN
        PRINT N'monitor.USP_QueryStoreReplicaAnalysis';
        PRINT N'Trennt Query-Store-Runtime-, Wait- und Forcing-Evidenz nach replica_group_id.';
        PRINT N'@ReplicaGroupIds akzeptiert numerische Pipe-, Beistrich- oder Strichpunktlisten.';
        PRINT N'@VonUtc/@BisUtc begrenzen Runtime- und Wait-Intervalle; Default ist die letzte Stunde.';
        PRINT N'SQL Server 2019/2022 liefern kontrolliert UNAVAILABLE_VERSION; versionsspezifische Quellen werden dort nicht referenziert.';
        PRINT N'@ResultSetArt=CONSOLE|RAW|TABLE|NONE; TABLE-Namen: moduleStatus, replicas, runtimeByReplica, waitsByReplica, forcingByReplica, sourceStatus, warnings.';
        RETURN;
    END;

    IF @BisUtc IS NULL SET @BisUtc=SYSUTCDATETIME();
    IF @VonUtc IS NULL SET @VonUtc=DATEADD(HOUR,-1,@BisUtc);

    CREATE TABLE [#QueryStoreReplicaAnalysis_ResultTableMap]
    (
          [ResultName] sysname COLLATE SQL_Latin1_General_CP1_CS_AS NOT NULL PRIMARY KEY
        , [TargetTable] sysname COLLATE SQL_Latin1_General_CP1_CS_AS NOT NULL UNIQUE
    );
    CREATE TABLE [#QueryStoreReplicaAnalysis_DatabaseCandidates]
    (
          [DatabaseId] int NOT NULL PRIMARY KEY
        , [DatabaseName] sysname COLLATE SQL_Latin1_General_CP1_CS_AS NOT NULL
        , [StateDesc] nvarchar(60) NULL
        , [UserAccessDesc] nvarchar(60) NULL
        , [IsReadOnly] bit NULL
        , [CompatibilityLevel] tinyint NULL
        , [CollationName] sysname NULL
        , [RecoveryModelDesc] nvarchar(60) NULL
        , [IsSystemDatabase] bit NULL
        , [RequestedOrdinal] int NULL
    );
    CREATE TABLE [#QueryStoreReplicaAnalysis_CandidateWarnings]
    (
          [RequestedName] sysname COLLATE SQL_Latin1_General_CP1_CS_AS NULL
        , [StatusCode] varchar(40) NOT NULL
        , [ErrorMessage] nvarchar(2048) NULL
    );
    CREATE TABLE [#QueryStoreReplicaAnalysis_ReplicaFilter]
    (
          [ItemOrdinal] int NOT NULL
        , [ReplicaGroupId] bigint NULL
        , [IsValid] bit NOT NULL
        , PRIMARY KEY([ItemOrdinal])
    );
    CREATE TABLE [#QueryStoreReplicaAnalysis_Replicas]
    (
          [CapturedAtUtc] datetime2(3) NOT NULL
        , [DatabaseId] int NOT NULL
        , [DatabaseName] sysname NOT NULL
        , [CurrentQueryStoreStateDesc] nvarchar(60) NULL
        , [CurrentConnectionRoleDesc] varchar(40) NOT NULL
        , [ReplicaGroupId] bigint NOT NULL
        , [RoleType] tinyint NULL
        , [RoleTypeDesc] varchar(40) NOT NULL
        , [RoleClass] varchar(24) NOT NULL
        , [ReplicaName] nvarchar(4000) NULL
        , [IsPrimaryRole] bit NOT NULL
        , [IsSecondaryRole] bit NOT NULL
        , [IsNamedReplica] bit NOT NULL
        , [StatusCode] varchar(40) NOT NULL
        , [EvidenceLimit] nvarchar(1000) NOT NULL
    );
    CREATE TABLE [#QueryStoreReplicaAnalysis_RuntimeByReplica]
    (
          [CapturedAtUtc] datetime2(3) NOT NULL
        , [DatabaseId] int NOT NULL
        , [DatabaseName] sysname NOT NULL
        , [CurrentConnectionRoleDesc] varchar(40) NOT NULL
        , [ReplicaGroupId] bigint NULL
        , [RoleType] tinyint NULL
        , [RoleTypeDesc] varchar(40) NOT NULL
        , [RoleClass] varchar(24) NOT NULL
        , [ReplicaName] nvarchar(4000) NULL
        , [MappingStatusCode] varchar(40) NOT NULL
        , [RecordedRows] bigint NOT NULL
        , [QueryCount] bigint NOT NULL
        , [PlanCount] bigint NOT NULL
        , [ExecutionCount] bigint NOT NULL
        , [FirstExecutionTimeUtc] datetimeoffset NULL
        , [LastExecutionTimeUtc] datetimeoffset NULL
        , [TotalDurationMs] decimal(38,3) NULL
        , [TotalCpuMs] decimal(38,3) NULL
        , [TotalLogicalReads] decimal(38,3) NULL
        , [TotalLogicalWrites] decimal(38,3) NULL
        , [EvidenceLimit] nvarchar(1000) NOT NULL
    );
    CREATE TABLE [#QueryStoreReplicaAnalysis_WaitsByReplica]
    (
          [CapturedAtUtc] datetime2(3) NOT NULL
        , [DatabaseId] int NOT NULL
        , [DatabaseName] sysname NOT NULL
        , [CurrentConnectionRoleDesc] varchar(40) NOT NULL
        , [ReplicaGroupId] bigint NULL
        , [RoleType] tinyint NULL
        , [RoleTypeDesc] varchar(40) NOT NULL
        , [RoleClass] varchar(24) NOT NULL
        , [ReplicaName] nvarchar(4000) NULL
        , [MappingStatusCode] varchar(40) NOT NULL
        , [ExecutionTypeDesc] nvarchar(128) NULL
        , [WaitCategory] tinyint NULL
        , [WaitCategoryDesc] nvarchar(128) NULL
        , [RecordedRows] bigint NOT NULL
        , [FirstIntervalStartUtc] datetimeoffset NULL
        , [LastIntervalEndUtc] datetimeoffset NULL
        , [TotalQueryWaitTimeMs] bigint NULL
        , [MaxQueryWaitTimeMs] bigint NULL
        , [EvidenceLimit] nvarchar(1000) NOT NULL
    );
    CREATE TABLE [#QueryStoreReplicaAnalysis_ForcingByReplica]
    (
          [CapturedAtUtc] datetime2(3) NOT NULL
        , [DatabaseId] int NOT NULL
        , [DatabaseName] sysname NOT NULL
        , [CurrentConnectionRoleDesc] varchar(40) NOT NULL
        , [ReplicaGroupId] bigint NULL
        , [RoleType] tinyint NULL
        , [RoleTypeDesc] varchar(40) NOT NULL
        , [RoleClass] varchar(24) NOT NULL
        , [ReplicaName] nvarchar(4000) NULL
        , [MappingStatusCode] varchar(40) NOT NULL
        , [ForcingLocationCount] bigint NOT NULL
        , [ForcedQueryCount] bigint NOT NULL
        , [ForcedPlanCount] bigint NOT NULL
        , [EvidenceLimit] nvarchar(1000) NOT NULL
    );
    CREATE TABLE [#QueryStoreReplicaAnalysis_SourceStatus]
    (
          [SourceOrdinal] int IDENTITY(1,1) NOT NULL PRIMARY KEY
        , [DatabaseId] int NULL
        , [DatabaseName] sysname NULL
        , [SourceName] sysname NOT NULL
        , [SourceObject] nvarchar(256) NOT NULL
        , [CapturedAtUtc] datetime2(3) NOT NULL
        , [StatusCode] varchar(40) NOT NULL
        , [IsPartial] bit NOT NULL
        , [ReturnedRowCount] bigint NOT NULL
        , [RequiredPermission] nvarchar(256) NULL
        , [ErrorNumber] int NULL
        , [ErrorMessage] nvarchar(2048) NULL
        , [EvidenceLimit] nvarchar(1000) NOT NULL
    );
    CREATE TABLE [#QueryStoreReplicaAnalysis_Warnings]
    (
          [WarningOrdinal] int IDENTITY(1,1) NOT NULL PRIMARY KEY
        , [DatabaseName] sysname NULL
        , [SourceName] sysname NOT NULL
        , [StatusCode] varchar(40) NOT NULL
        , [ErrorNumber] int NULL
        , [Message] nvarchar(2048) NOT NULL
    );
    CREATE TABLE [#QueryStoreReplicaAnalysis_ModuleStatus]
    (
          [ModuleName] sysname NOT NULL
        , [CapturedAtUtc] datetime2(3) NOT NULL
        , [StatusCode] varchar(40) NOT NULL
        , [IsPartial] bit NOT NULL
        , [ProductMajorVersion] int NULL
        , [CrossDatabaseRequested] bit NOT NULL
        , [DatabaseCount] int NOT NULL
        , [ReplicaRowCount] bigint NOT NULL
        , [RuntimeRowCount] bigint NOT NULL
        , [WaitRowCount] bigint NOT NULL
        , [ForcingRowCount] bigint NOT NULL
        , [HasMoreReplicaRows] bit NOT NULL
        , [HasMoreRuntimeRows] bit NOT NULL
        , [HasMoreWaitRows] bit NOT NULL
        , [HasMoreForcingRows] bit NOT NULL
        , [ErrorNumber] int NULL
        , [ErrorMessage] nvarchar(2048) NULL
    );

    IF @ReplicaGroupIds IS NOT NULL
    BEGIN
        INSERT [#QueryStoreReplicaAnalysis_ReplicaFilter]([ItemOrdinal],[ReplicaGroupId],[IsValid])
        SELECT [ItemOrdinal],[NumberValue],[IsValid]
        FROM [monitor].[TVF_ParseBigintList](@ReplicaGroupIds);
    END;

    IF @MaxZeilen<0 OR @LockTimeoutMs NOT BETWEEN 0 AND 60000
       OR @HighImpactConfirmed IS NULL OR @JsonErzeugen IS NULL OR @PrintMeldungen IS NULL
       OR @VonUtc>=@BisUtc OR @OutputMode NOT IN('CONSOLE','RAW','TABLE','NONE')
       OR (@OutputMode<>'TABLE' AND NULLIF(LTRIM(RTRIM(COALESCE(@ResultTablesJson,N''))),N'') IS NOT NULL)
       OR EXISTS(SELECT 1 FROM [#QueryStoreReplicaAnalysis_ReplicaFilter] WHERE [IsValid]=0)
    BEGIN
        SELECT @StatusCode='INVALID_PARAMETER',@IsPartial=1,
               @ErrorMessage=N'Ungültiger Zeitraum, Zeilen-, Replica-, Lock-Timeout- oder Ausgabeparameter.';
    END;

    IF @StatusCode='AVAILABLE' AND @OutputMode='TABLE'
        EXEC [monitor].[InternalPrepareResultTables]
              @ResultTablesJson=@ResultTablesJson
            , @AllowedResultNames=N'moduleStatus|replicas|runtimeByReplica|waitsByReplica|forcingByReplica|sourceStatus|warnings'
            , @MappingTable=N'#QueryStoreReplicaAnalysis_ResultTableMap'
            , @StatusCode=@StatusCode OUTPUT
            , @ErrorMessage=@ErrorMessage OUTPUT
            , @ThrowOnError=1;

    IF @StatusCode='AVAILABLE'
        EXEC [monitor].[USP_PrepareDatabaseCandidates]
              @DatabaseNames=@QueryStoreDatabaseNames
            , @SystemdatenbankenEinbeziehen=0
            , @DatabaseNamePattern=@QueryStoreDatabaseNamePattern
            , @HighImpactConfirmed=@HighImpactConfirmed
            , @AnalysisClass='QUERY_STORE_CURRENT'
            , @StatusCode=@StatusCode OUTPUT
            , @ErrorMessage=@ErrorMessage OUTPUT
            , @CrossDatabaseRequested=@CrossDatabaseRequested OUTPUT
            , @CandidateTable=N'#QueryStoreReplicaAnalysis_DatabaseCandidates'
            , @WarningTable=N'#QueryStoreReplicaAnalysis_CandidateWarnings';

    INSERT [#QueryStoreReplicaAnalysis_Warnings]([DatabaseName],[SourceName],[StatusCode],[ErrorNumber],[Message])
    SELECT [RequestedName],N'databaseCandidates',[StatusCode],NULL,COALESCE([ErrorMessage],N'Datenbankkandidat ist nicht verfügbar.')
    FROM [#QueryStoreReplicaAnalysis_CandidateWarnings];

    IF EXISTS(SELECT 1 FROM [#QueryStoreReplicaAnalysis_CandidateWarnings])
        SET @IsPartial=1;

    IF @StatusCode='AVAILABLE'
    BEGIN
        SET @LockTimeoutSql=N'SET LOCK_TIMEOUT '+CONVERT(nvarchar(20),@LockTimeoutMs)+N';';
        EXEC [sys].[sp_executesql] @LockTimeoutSql;

        DECLARE
              @DatabaseId int
            , @DatabaseName sysname
            , @ActualState smallint
            , @ActualStateDesc nvarchar(60)
            , @WaitStatsCaptureMode smallint
            , @CurrentIsPrimaryReplica int
            , @CurrentRoleDesc varchar(40)
            , @HasReplicaCatalog bit
            , @ReplicaCatalogSchemaValid bit
            , @RuntimeReplicaColumnValid bit
            , @WaitReplicaColumnValid bit
            , @HasForcingLocations bit
            , @ForcingSchemaValid bit
            , @ProbeSql nvarchar(max)
            , @ReplicaSql nvarchar(max)
            , @RuntimeSql nvarchar(max)
            , @WaitSql nvarchar(max)
            , @ForcingSql nvarchar(max)
            , @RowsBefore bigint
            , @RowsAfter bigint;

        DECLARE [DatabaseCursor] CURSOR LOCAL FAST_FORWARD FOR
            SELECT [DatabaseId],[DatabaseName]
            FROM [#QueryStoreReplicaAnalysis_DatabaseCandidates]
            ORDER BY COALESCE([RequestedOrdinal],[DatabaseId]),[DatabaseId];

        OPEN [DatabaseCursor];
        FETCH NEXT FROM [DatabaseCursor] INTO @DatabaseId,@DatabaseName;
        WHILE @@FETCH_STATUS=0
        BEGIN
            IF @ProductMajorVersion IS NULL OR @ProductMajorVersion<17
            BEGIN
                INSERT [#QueryStoreReplicaAnalysis_SourceStatus]
                ([DatabaseId],[DatabaseName],[SourceName],[SourceObject],[CapturedAtUtc],[StatusCode],[IsPartial],[ReturnedRowCount],[RequiredPermission],[ErrorNumber],[ErrorMessage],[EvidenceLimit])
                VALUES
                  (@DatabaseId,@DatabaseName,N'queryStoreOptions',N'sys.database_query_store_options',@CapturedAtUtc,'AVAILABLE',0,0,N'VIEW DATABASE STATE / VIEW DATABASE PERFORMANCE STATE',NULL,NULL,N'Die Basisoptionen bleiben versionsübergreifend verfügbar; der Replica-Slice referenziert sie vor SQL Server 2025 nicht erneut.')
                , (@DatabaseId,@DatabaseName,N'replicaCatalog',N'sys.query_store_replicas',@CapturedAtUtc,'UNAVAILABLE_VERSION',0,0,N'VIEW DATABASE PERFORMANCE STATE',NULL,NULL,N'Query Store für lesbare Secondaries und sys.query_store_replicas werden im freigegebenen Produktvertrag erst ab SQL Server 2025 ausgewertet.')
                , (@DatabaseId,@DatabaseName,N'runtimeByReplica',N'sys.query_store_runtime_stats.replica_group_id',@CapturedAtUtc,'UNAVAILABLE_VERSION',0,0,N'VIEW DATABASE PERFORMANCE STATE',NULL,NULL,N'Vor SQL Server 2025 wird keine Replica-Rollenaussage erzeugt.')
                , (@DatabaseId,@DatabaseName,N'waitsByReplica',N'sys.query_store_wait_stats.replica_group_id',@CapturedAtUtc,'UNAVAILABLE_VERSION',0,0,N'VIEW DATABASE PERFORMANCE STATE',NULL,NULL,N'Vor SQL Server 2025 wird keine Replica-Rollenaussage erzeugt.')
                , (@DatabaseId,@DatabaseName,N'forcingByReplica',N'sys.query_store_plan_forcing_locations',@CapturedAtUtc,'UNAVAILABLE_VERSION',0,0,N'VIEW DATABASE PERFORMANCE STATE',NULL,NULL,N'Replica-spezifische Plan-Forcing-Locations werden erst ab SQL Server 2025 ausgewertet.');
            END
            ELSE
            BEGIN
                SELECT @ActualState=NULL,@ActualStateDesc=NULL,@WaitStatsCaptureMode=NULL,
                       @CurrentIsPrimaryReplica=NULL,@HasReplicaCatalog=0,@ReplicaCatalogSchemaValid=0,
                       @RuntimeReplicaColumnValid=0,@WaitReplicaColumnValid=0,
                       @HasForcingLocations=0,@ForcingSchemaValid=0;

                SET @ProbeSql=N'USE '+QUOTENAME(@DatabaseName)+N';
SELECT TOP(1)
       @pActualState=[actual_state],
       @pActualStateDesc=[actual_state_desc],
       @pWaitStatsCaptureMode=[wait_stats_capture_mode]
FROM [sys].[database_query_store_options] WITH (NOLOCK);

SELECT @pCurrentIsPrimaryReplica=TRY_CONVERT(int,[sys].[fn_hadr_is_primary_replica](@pDatabaseName));

SELECT @pHasReplicaCatalog=CONVERT(bit,CASE WHEN EXISTS
(
    SELECT 1 FROM [sys].[all_objects] AS [o] WITH (NOLOCK)
    INNER JOIN [sys].[schemas] AS [s] WITH (NOLOCK) ON [s].[schema_id]=[o].[schema_id]
    WHERE [s].[name]=N''sys'' AND [o].[name]=N''query_store_replicas''
) THEN 1 ELSE 0 END);

SELECT @pReplicaCatalogSchemaValid=CONVERT(bit,CASE WHEN COUNT(DISTINCT [c].[name])=3 THEN 1 ELSE 0 END)
FROM [sys].[all_objects] AS [o] WITH (NOLOCK)
INNER JOIN [sys].[schemas] AS [s] WITH (NOLOCK) ON [s].[schema_id]=[o].[schema_id]
INNER JOIN [sys].[all_columns] AS [c] WITH (NOLOCK) ON [c].[object_id]=[o].[object_id]
WHERE [s].[name]=N''sys'' AND [o].[name]=N''query_store_replicas''
  AND [c].[name] IN(N''replica_group_id'',N''role_type'',N''replica_name'');

SELECT @pRuntimeReplicaColumnValid=CONVERT(bit,CASE WHEN EXISTS
(
    SELECT 1 FROM [sys].[all_objects] AS [o] WITH (NOLOCK)
    INNER JOIN [sys].[schemas] AS [s] WITH (NOLOCK) ON [s].[schema_id]=[o].[schema_id]
    INNER JOIN [sys].[all_columns] AS [c] WITH (NOLOCK) ON [c].[object_id]=[o].[object_id]
    WHERE [s].[name]=N''sys'' AND [o].[name]=N''query_store_runtime_stats'' AND [c].[name]=N''replica_group_id''
) THEN 1 ELSE 0 END);

SELECT @pWaitReplicaColumnValid=CONVERT(bit,CASE WHEN EXISTS
(
    SELECT 1 FROM [sys].[all_objects] AS [o] WITH (NOLOCK)
    INNER JOIN [sys].[schemas] AS [s] WITH (NOLOCK) ON [s].[schema_id]=[o].[schema_id]
    INNER JOIN [sys].[all_columns] AS [c] WITH (NOLOCK) ON [c].[object_id]=[o].[object_id]
    WHERE [s].[name]=N''sys'' AND [o].[name]=N''query_store_wait_stats'' AND [c].[name]=N''replica_group_id''
) THEN 1 ELSE 0 END);

SELECT @pHasForcingLocations=CONVERT(bit,CASE WHEN EXISTS
(
    SELECT 1 FROM [sys].[all_objects] AS [o] WITH (NOLOCK)
    INNER JOIN [sys].[schemas] AS [s] WITH (NOLOCK) ON [s].[schema_id]=[o].[schema_id]
    WHERE [s].[name]=N''sys'' AND [o].[name]=N''query_store_plan_forcing_locations''
) THEN 1 ELSE 0 END);

SELECT @pForcingSchemaValid=CONVERT(bit,CASE WHEN COUNT(DISTINCT [c].[name])=3 THEN 1 ELSE 0 END)
FROM [sys].[all_objects] AS [o] WITH (NOLOCK)
INNER JOIN [sys].[schemas] AS [s] WITH (NOLOCK) ON [s].[schema_id]=[o].[schema_id]
INNER JOIN [sys].[all_columns] AS [c] WITH (NOLOCK) ON [c].[object_id]=[o].[object_id]
WHERE [s].[name]=N''sys'' AND [o].[name]=N''query_store_plan_forcing_locations''
  AND [c].[name] IN(N''query_id'',N''plan_id'',N''replica_group_id'');';

                BEGIN TRY
                    EXEC [sys].[sp_executesql]
                          @ProbeSql
                        , N'@pDatabaseName sysname,@pActualState smallint OUTPUT,@pActualStateDesc nvarchar(60) OUTPUT,@pWaitStatsCaptureMode smallint OUTPUT,@pCurrentIsPrimaryReplica int OUTPUT,@pHasReplicaCatalog bit OUTPUT,@pReplicaCatalogSchemaValid bit OUTPUT,@pRuntimeReplicaColumnValid bit OUTPUT,@pWaitReplicaColumnValid bit OUTPUT,@pHasForcingLocations bit OUTPUT,@pForcingSchemaValid bit OUTPUT'
                        , @pDatabaseName=@DatabaseName
                        , @pActualState=@ActualState OUTPUT
                        , @pActualStateDesc=@ActualStateDesc OUTPUT
                        , @pWaitStatsCaptureMode=@WaitStatsCaptureMode OUTPUT
                        , @pCurrentIsPrimaryReplica=@CurrentIsPrimaryReplica OUTPUT
                        , @pHasReplicaCatalog=@HasReplicaCatalog OUTPUT
                        , @pReplicaCatalogSchemaValid=@ReplicaCatalogSchemaValid OUTPUT
                        , @pRuntimeReplicaColumnValid=@RuntimeReplicaColumnValid OUTPUT
                        , @pWaitReplicaColumnValid=@WaitReplicaColumnValid OUTPUT
                        , @pHasForcingLocations=@HasForcingLocations OUTPUT
                        , @pForcingSchemaValid=@ForcingSchemaValid OUTPUT;

                    SET @CurrentRoleDesc=CASE @CurrentIsPrimaryReplica WHEN 1 THEN 'PRIMARY' WHEN 0 THEN 'SECONDARY' ELSE 'NOT_IN_AG_OR_UNKNOWN' END;

                    INSERT [#QueryStoreReplicaAnalysis_SourceStatus]
                    ([DatabaseId],[DatabaseName],[SourceName],[SourceObject],[CapturedAtUtc],[StatusCode],[IsPartial],[ReturnedRowCount],[RequiredPermission],[ErrorNumber],[ErrorMessage],[EvidenceLimit])
                    VALUES
                    (@DatabaseId,@DatabaseName,N'queryStoreOptions',N'sys.database_query_store_options',@CapturedAtUtc,
                     CASE WHEN @ActualState IN(1,2,4) THEN 'AVAILABLE' WHEN @ActualState=3 THEN 'ERROR_STATE' ELSE 'FEATURE_DISABLED' END,
                     CONVERT(bit,CASE WHEN @ActualState=3 THEN 1 ELSE 0 END),1,N'VIEW DATABASE PERFORMANCE STATE',NULL,NULL,
                     CONCAT(N'actual_state_desc=',COALESCE(@ActualStateDesc,N'UNKNOWN'),N'; aktueller AG-Rollenhinweis=',@CurrentRoleDesc,N'.'));
                END TRY
                BEGIN CATCH
                    INSERT [#QueryStoreReplicaAnalysis_SourceStatus]
                    ([DatabaseId],[DatabaseName],[SourceName],[SourceObject],[CapturedAtUtc],[StatusCode],[IsPartial],[ReturnedRowCount],[RequiredPermission],[ErrorNumber],[ErrorMessage],[EvidenceLimit])
                    VALUES
                    (@DatabaseId,@DatabaseName,N'queryStoreOptions',N'sys.database_query_store_options',@CapturedAtUtc,
                     CASE WHEN ERROR_NUMBER() IN(229,262,297,300,371,916) THEN 'DENIED_PERMISSION' WHEN ERROR_NUMBER()=1222 THEN 'TIMEOUT' ELSE 'ERROR_HANDLED' END,
                     1,0,N'VIEW DATABASE PERFORMANCE STATE',ERROR_NUMBER(),ERROR_MESSAGE(),N'Die Capability- und Schemaprüfung ist fehlgeschlagen; versionsspezifische Quellen wurden nicht referenziert.');
                    INSERT [#QueryStoreReplicaAnalysis_Warnings]([DatabaseName],[SourceName],[StatusCode],[ErrorNumber],[Message])
                    VALUES(@DatabaseName,N'queryStoreOptions',
                           CASE WHEN ERROR_NUMBER() IN(229,262,297,300,371,916) THEN 'DENIED_PERMISSION' WHEN ERROR_NUMBER()=1222 THEN 'TIMEOUT' ELSE 'ERROR_HANDLED' END,
                           ERROR_NUMBER(),ERROR_MESSAGE());
                    SET @IsPartial=1;
                    SELECT @ActualState=NULL,@HasReplicaCatalog=0,@ReplicaCatalogSchemaValid=0,
                           @RuntimeReplicaColumnValid=0,@WaitReplicaColumnValid=0,@HasForcingLocations=0,@ForcingSchemaValid=0,
                           @CurrentRoleDesc='UNKNOWN';
                END CATCH;

                IF @ActualState IN(1,2,4) AND @HasReplicaCatalog=1 AND @ReplicaCatalogSchemaValid=1
                BEGIN
                    SELECT @RowsBefore=COUNT_BIG(*) FROM [#QueryStoreReplicaAnalysis_Replicas];
                    SET @ReplicaSql=N'USE '+QUOTENAME(@DatabaseName)+N';
INSERT [#QueryStoreReplicaAnalysis_Replicas]
([CapturedAtUtc],[DatabaseId],[DatabaseName],[CurrentQueryStoreStateDesc],[CurrentConnectionRoleDesc],
 [ReplicaGroupId],[RoleType],[RoleTypeDesc],[RoleClass],[ReplicaName],
 [IsPrimaryRole],[IsSecondaryRole],[IsNamedReplica],[StatusCode],[EvidenceLimit])
SELECT @pCapturedAtUtc,@pDatabaseId,@pDatabaseName,@pActualStateDesc,@pCurrentRoleDesc,
       [r].[replica_group_id],[r].[role_type],[m].[RoleTypeDesc],[m].[RoleClass],
       CONVERT(nvarchar(4000),[r].[replica_name]),
       [m].[IsPrimaryRole],[m].[IsSecondaryRole],[m].[IsNamedReplica],''AVAILABLE'',[m].[EvidenceLimit]
FROM [sys].[query_store_replicas] AS [r] WITH (NOLOCK)
CROSS APPLY [DeineDatenbank].[monitor].[TVF_QueryStoreReplicaRoleInfo]([r].[role_type]) AS [m]
WHERE NOT EXISTS(SELECT 1 FROM [#QueryStoreReplicaAnalysis_ReplicaFilter])
   OR EXISTS(SELECT 1 FROM [#QueryStoreReplicaAnalysis_ReplicaFilter] AS [f]
             WHERE [f].[IsValid]=1 AND [f].[ReplicaGroupId]=[r].[replica_group_id])
OPTION (MAXDOP 1,RECOMPILE);';
                    BEGIN TRY
                        EXEC [sys].[sp_executesql] @ReplicaSql,
                             N'@pCapturedAtUtc datetime2(3),@pDatabaseId int,@pDatabaseName sysname,@pActualStateDesc nvarchar(60),@pCurrentRoleDesc varchar(40)',
                             @CapturedAtUtc,@DatabaseId,@DatabaseName,@ActualStateDesc,@CurrentRoleDesc;
                        SELECT @RowsAfter=COUNT_BIG(*) FROM [#QueryStoreReplicaAnalysis_Replicas];
                        INSERT [#QueryStoreReplicaAnalysis_SourceStatus]
                        ([DatabaseId],[DatabaseName],[SourceName],[SourceObject],[CapturedAtUtc],[StatusCode],[IsPartial],[ReturnedRowCount],[RequiredPermission],[ErrorNumber],[ErrorMessage],[EvidenceLimit])
                        VALUES(@DatabaseId,@DatabaseName,N'replicaCatalog',N'sys.query_store_replicas',@CapturedAtUtc,
                               CASE WHEN @RowsAfter=@RowsBefore THEN 'EMPTY_VISIBLE_SCOPE' ELSE 'AVAILABLE' END,0,@RowsAfter-@RowsBefore,
                               N'VIEW DATABASE PERFORMANCE STATE',NULL,NULL,N'Eine Zeile beschreibt eine beobachtete Query-Store-Rolle. Failover kann mehrere historische Rollen erzeugen; dies ist keine aktuelle Healthaussage.');
                    END TRY
                    BEGIN CATCH
                        INSERT [#QueryStoreReplicaAnalysis_SourceStatus]
                        ([DatabaseId],[DatabaseName],[SourceName],[SourceObject],[CapturedAtUtc],[StatusCode],[IsPartial],[ReturnedRowCount],[RequiredPermission],[ErrorNumber],[ErrorMessage],[EvidenceLimit])
                        VALUES(@DatabaseId,@DatabaseName,N'replicaCatalog',N'sys.query_store_replicas',@CapturedAtUtc,
                               CASE WHEN ERROR_NUMBER() IN(229,262,297,300,371,916) THEN 'DENIED_PERMISSION' WHEN ERROR_NUMBER()=1222 THEN 'TIMEOUT' ELSE 'ERROR_HANDLED' END,
                               1,0,N'VIEW DATABASE PERFORMANCE STATE',ERROR_NUMBER(),ERROR_MESSAGE(),N'Der Replica-Katalogfehler ist auf diese Quelle begrenzt.');
                        INSERT [#QueryStoreReplicaAnalysis_Warnings]([DatabaseName],[SourceName],[StatusCode],[ErrorNumber],[Message])
                        VALUES(@DatabaseName,N'replicaCatalog','ERROR_HANDLED',ERROR_NUMBER(),ERROR_MESSAGE());
                        SET @IsPartial=1;
                    END CATCH;
                END
                ELSE
                BEGIN
                    INSERT [#QueryStoreReplicaAnalysis_SourceStatus]
                    ([DatabaseId],[DatabaseName],[SourceName],[SourceObject],[CapturedAtUtc],[StatusCode],[IsPartial],[ReturnedRowCount],[RequiredPermission],[ErrorNumber],[ErrorMessage],[EvidenceLimit])
                    VALUES(@DatabaseId,@DatabaseName,N'replicaCatalog',N'sys.query_store_replicas',@CapturedAtUtc,
                           CASE WHEN @ActualState NOT IN(1,2,4) THEN 'FEATURE_DISABLED'
                                WHEN @HasReplicaCatalog=0 THEN 'UNAVAILABLE_FEATURE' ELSE 'UNAVAILABLE_SCHEMA' END,
                           CONVERT(bit,CASE WHEN @ActualState IN(1,2,4) THEN 1 ELSE 0 END),0,N'VIEW DATABASE PERFORMANCE STATE',NULL,NULL,
                           N'Die Replicaquelle wird nur nach erfolgreicher Version-, Objekt- und Pflichtspaltenprüfung referenziert.');
                    IF @ActualState IN(1,2,4) SET @IsPartial=1;
                END;

                IF @ActualState IN(1,2,4) AND @RuntimeReplicaColumnValid=1
                BEGIN
                    SELECT @RowsBefore=COUNT_BIG(*) FROM [#QueryStoreReplicaAnalysis_RuntimeByReplica];
                    SET @RuntimeSql=N'USE '+QUOTENAME(@DatabaseName)+N';
;WITH [ReplicaMap] AS
(
    SELECT [replica_group_id],MIN([role_type]) AS [role_type],MAX(CONVERT(nvarchar(4000),[replica_name])) AS [replica_name]
    FROM [sys].[query_store_replicas] WITH (NOLOCK)
    GROUP BY [replica_group_id]
),
[R] AS
(
    SELECT [rs].[replica_group_id],COUNT_BIG(*) AS [RecordedRows],
           COUNT_BIG(DISTINCT [p].[query_id]) AS [QueryCount],
           COUNT_BIG(DISTINCT [rs].[plan_id]) AS [PlanCount],
           SUM(CONVERT(bigint,[rs].[count_executions])) AS [ExecutionCount],
           MIN([rs].[first_execution_time]) AS [FirstExecutionTime],
           MAX([rs].[last_execution_time]) AS [LastExecutionTime],
           SUM(CONVERT(float,[rs].[avg_duration])*[rs].[count_executions])/1000.0 AS [TotalDurationMs],
           SUM(CONVERT(float,[rs].[avg_cpu_time])*[rs].[count_executions])/1000.0 AS [TotalCpuMs],
           SUM(CONVERT(float,[rs].[avg_logical_io_reads])*[rs].[count_executions]) AS [TotalLogicalReads],
           SUM(CONVERT(float,[rs].[avg_logical_io_writes])*[rs].[count_executions]) AS [TotalLogicalWrites]
    FROM [sys].[query_store_runtime_stats] AS [rs] WITH (NOLOCK)
    INNER JOIN [sys].[query_store_runtime_stats_interval] AS [i] WITH (NOLOCK)
      ON [i].[runtime_stats_interval_id]=[rs].[runtime_stats_interval_id]
    INNER JOIN [sys].[query_store_plan] AS [p] WITH (NOLOCK) ON [p].[plan_id]=[rs].[plan_id]
    WHERE [i].[end_time]>@pFromUtc AND [i].[start_time]<@pToUtc
      AND (NOT EXISTS(SELECT 1 FROM [#QueryStoreReplicaAnalysis_ReplicaFilter])
           OR EXISTS(SELECT 1 FROM [#QueryStoreReplicaAnalysis_ReplicaFilter] AS [f]
                     WHERE [f].[IsValid]=1 AND [f].[ReplicaGroupId]=[rs].[replica_group_id]))
    GROUP BY [rs].[replica_group_id]
)
INSERT [#QueryStoreReplicaAnalysis_RuntimeByReplica]
([CapturedAtUtc],[DatabaseId],[DatabaseName],[CurrentConnectionRoleDesc],[ReplicaGroupId],
 [RoleType],[RoleTypeDesc],[RoleClass],[ReplicaName],[MappingStatusCode],
 [RecordedRows],[QueryCount],[PlanCount],[ExecutionCount],[FirstExecutionTimeUtc],[LastExecutionTimeUtc],
 [TotalDurationMs],[TotalCpuMs],[TotalLogicalReads],[TotalLogicalWrites],[EvidenceLimit])
SELECT @pCapturedAtUtc,@pDatabaseId,@pDatabaseName,@pCurrentRoleDesc,[R].[replica_group_id],
       [rm].[role_type],[mi].[RoleTypeDesc],[mi].[RoleClass],[rm].[replica_name],
       CASE WHEN [rm].[replica_group_id] IS NULL THEN ''REPLICA_METADATA_MISSING'' ELSE ''AVAILABLE'' END,
       [R].[RecordedRows],[R].[QueryCount],[R].[PlanCount],[R].[ExecutionCount],
       [R].[FirstExecutionTime],[R].[LastExecutionTime],
       CONVERT(decimal(38,3),[R].[TotalDurationMs]),CONVERT(decimal(38,3),[R].[TotalCpuMs]),
       CONVERT(decimal(38,3),[R].[TotalLogicalReads]),CONVERT(decimal(38,3),[R].[TotalLogicalWrites]),
       N''Intervallaggregate nach replica_group_id; keine aktuelle Einzelausführung, kein Querytext und keine Replikatsynchronitätsaussage.''
FROM [R]
LEFT JOIN [ReplicaMap] AS [rm] ON [rm].[replica_group_id]=[R].[replica_group_id]
CROSS APPLY [DeineDatenbank].[monitor].[TVF_QueryStoreReplicaRoleInfo]([rm].[role_type]) AS [mi]
OPTION (MAXDOP 1,RECOMPILE);';
                    BEGIN TRY
                        EXEC [sys].[sp_executesql] @RuntimeSql,
                             N'@pCapturedAtUtc datetime2(3),@pDatabaseId int,@pDatabaseName sysname,@pCurrentRoleDesc varchar(40),@pFromUtc datetime2(7),@pToUtc datetime2(7)',
                             @CapturedAtUtc,@DatabaseId,@DatabaseName,@CurrentRoleDesc,@VonUtc,@BisUtc;
                        SELECT @RowsAfter=COUNT_BIG(*) FROM [#QueryStoreReplicaAnalysis_RuntimeByReplica];
                        INSERT [#QueryStoreReplicaAnalysis_SourceStatus]
                        ([DatabaseId],[DatabaseName],[SourceName],[SourceObject],[CapturedAtUtc],[StatusCode],[IsPartial],[ReturnedRowCount],[RequiredPermission],[ErrorNumber],[ErrorMessage],[EvidenceLimit])
                        VALUES(@DatabaseId,@DatabaseName,N'runtimeByReplica',N'sys.query_store_runtime_stats.replica_group_id',@CapturedAtUtc,
                               CASE WHEN @RowsAfter=@RowsBefore THEN 'EMPTY_VISIBLE_SCOPE' ELSE 'AVAILABLE' END,0,@RowsAfter-@RowsBefore,
                               N'VIEW DATABASE PERFORMANCE STATE',NULL,NULL,N'Runtimewerte werden je replica_group_id getrennt und aus Query-Store-Intervallen gewichtet.');
                    END TRY
                    BEGIN CATCH
                        INSERT [#QueryStoreReplicaAnalysis_SourceStatus]
                        ([DatabaseId],[DatabaseName],[SourceName],[SourceObject],[CapturedAtUtc],[StatusCode],[IsPartial],[ReturnedRowCount],[RequiredPermission],[ErrorNumber],[ErrorMessage],[EvidenceLimit])
                        VALUES(@DatabaseId,@DatabaseName,N'runtimeByReplica',N'sys.query_store_runtime_stats.replica_group_id',@CapturedAtUtc,
                               CASE WHEN ERROR_NUMBER() IN(229,262,297,300,371,916) THEN 'DENIED_PERMISSION' WHEN ERROR_NUMBER()=1222 THEN 'TIMEOUT' ELSE 'ERROR_HANDLED' END,
                               1,0,N'VIEW DATABASE PERFORMANCE STATE',ERROR_NUMBER(),ERROR_MESSAGE(),N'Der Runtimefehler ist auf diese Quelle begrenzt.');
                        INSERT [#QueryStoreReplicaAnalysis_Warnings]([DatabaseName],[SourceName],[StatusCode],[ErrorNumber],[Message])
                        VALUES(@DatabaseName,N'runtimeByReplica','ERROR_HANDLED',ERROR_NUMBER(),ERROR_MESSAGE());
                        SET @IsPartial=1;
                    END CATCH;
                END
                ELSE
                BEGIN
                    INSERT [#QueryStoreReplicaAnalysis_SourceStatus]
                    ([DatabaseId],[DatabaseName],[SourceName],[SourceObject],[CapturedAtUtc],[StatusCode],[IsPartial],[ReturnedRowCount],[RequiredPermission],[ErrorNumber],[ErrorMessage],[EvidenceLimit])
                    VALUES(@DatabaseId,@DatabaseName,N'runtimeByReplica',N'sys.query_store_runtime_stats.replica_group_id',@CapturedAtUtc,
                           CASE WHEN @ActualState NOT IN(1,2,4) THEN 'FEATURE_DISABLED' ELSE 'UNAVAILABLE_SCHEMA' END,
                           CONVERT(bit,CASE WHEN @ActualState IN(1,2,4) THEN 1 ELSE 0 END),0,N'VIEW DATABASE PERFORMANCE STATE',NULL,NULL,N'Die Replica-Spalte wird erst nach Pflichtspaltenprüfung referenziert.');
                    IF @ActualState IN(1,2,4) SET @IsPartial=1;
                END;

                IF @ActualState IN(1,2,4) AND @WaitStatsCaptureMode=1 AND @WaitReplicaColumnValid=1
                BEGIN
                    SELECT @RowsBefore=COUNT_BIG(*) FROM [#QueryStoreReplicaAnalysis_WaitsByReplica];
                    SET @WaitSql=N'USE '+QUOTENAME(@DatabaseName)+N';
;WITH [ReplicaMap] AS
(
    SELECT [replica_group_id],MIN([role_type]) AS [role_type],MAX(CONVERT(nvarchar(4000),[replica_name])) AS [replica_name]
    FROM [sys].[query_store_replicas] WITH (NOLOCK)
    GROUP BY [replica_group_id]
),
[W] AS
(
    SELECT [ws].[replica_group_id],[ws].[execution_type_desc],[ws].[wait_category],[ws].[wait_category_desc],
           COUNT_BIG(*) AS [RecordedRows],MIN([i].[start_time]) AS [FirstStart],MAX([i].[end_time]) AS [LastEnd],
           SUM(CONVERT(bigint,[ws].[total_query_wait_time_ms])) AS [TotalWait],
           MAX(CONVERT(bigint,[ws].[max_query_wait_time_ms])) AS [MaxWait]
    FROM [sys].[query_store_wait_stats] AS [ws] WITH (NOLOCK)
    INNER JOIN [sys].[query_store_runtime_stats_interval] AS [i] WITH (NOLOCK)
      ON [i].[runtime_stats_interval_id]=[ws].[runtime_stats_interval_id]
    WHERE [i].[end_time]>@pFromUtc AND [i].[start_time]<@pToUtc
      AND (NOT EXISTS(SELECT 1 FROM [#QueryStoreReplicaAnalysis_ReplicaFilter])
           OR EXISTS(SELECT 1 FROM [#QueryStoreReplicaAnalysis_ReplicaFilter] AS [f]
                     WHERE [f].[IsValid]=1 AND [f].[ReplicaGroupId]=[ws].[replica_group_id]))
    GROUP BY [ws].[replica_group_id],[ws].[execution_type_desc],[ws].[wait_category],[ws].[wait_category_desc]
)
INSERT [#QueryStoreReplicaAnalysis_WaitsByReplica]
([CapturedAtUtc],[DatabaseId],[DatabaseName],[CurrentConnectionRoleDesc],[ReplicaGroupId],
 [RoleType],[RoleTypeDesc],[RoleClass],[ReplicaName],[MappingStatusCode],
 [ExecutionTypeDesc],[WaitCategory],[WaitCategoryDesc],[RecordedRows],
 [FirstIntervalStartUtc],[LastIntervalEndUtc],[TotalQueryWaitTimeMs],[MaxQueryWaitTimeMs],[EvidenceLimit])
SELECT TOP(@pLocalLimit) @pCapturedAtUtc,@pDatabaseId,@pDatabaseName,@pCurrentRoleDesc,[W].[replica_group_id],
       [rm].[role_type],[mi].[RoleTypeDesc],[mi].[RoleClass],[rm].[replica_name],
       CASE WHEN [rm].[replica_group_id] IS NULL THEN ''REPLICA_METADATA_MISSING'' ELSE ''AVAILABLE'' END,
       [W].[execution_type_desc],[W].[wait_category],[W].[wait_category_desc],[W].[RecordedRows],
       [W].[FirstStart],[W].[LastEnd],[W].[TotalWait],[W].[MaxWait],
       N''Wait-Intervalaggregate nach replica_group_id und Kategorie; keine vollständige Wait-Timeline oder aktuelle Taskzuordnung.''
FROM [W]
LEFT JOIN [ReplicaMap] AS [rm] ON [rm].[replica_group_id]=[W].[replica_group_id]
CROSS APPLY [DeineDatenbank].[monitor].[TVF_QueryStoreReplicaRoleInfo]([rm].[role_type]) AS [mi]
ORDER BY [W].[TotalWait] DESC,[W].[LastEnd] DESC
OPTION (MAXDOP 1,RECOMPILE);';
                    BEGIN TRY
                        EXEC [sys].[sp_executesql] @WaitSql,
                             N'@pCapturedAtUtc datetime2(3),@pDatabaseId int,@pDatabaseName sysname,@pCurrentRoleDesc varchar(40),@pFromUtc datetime2(7),@pToUtc datetime2(7),@pLocalLimit bigint',
                             @CapturedAtUtc,@DatabaseId,@DatabaseName,@CurrentRoleDesc,@VonUtc,@BisUtc,@LocalLimit;
                        SELECT @RowsAfter=COUNT_BIG(*) FROM [#QueryStoreReplicaAnalysis_WaitsByReplica];
                        INSERT [#QueryStoreReplicaAnalysis_SourceStatus]
                        ([DatabaseId],[DatabaseName],[SourceName],[SourceObject],[CapturedAtUtc],[StatusCode],[IsPartial],[ReturnedRowCount],[RequiredPermission],[ErrorNumber],[ErrorMessage],[EvidenceLimit])
                        VALUES(@DatabaseId,@DatabaseName,N'waitsByReplica',N'sys.query_store_wait_stats.replica_group_id',@CapturedAtUtc,
                               CASE WHEN @RowsAfter=@RowsBefore THEN 'EMPTY_VISIBLE_SCOPE' ELSE 'AVAILABLE' END,0,@RowsAfter-@RowsBefore,
                               N'VIEW DATABASE PERFORMANCE STATE',NULL,NULL,N'Waitwerte werden je replica_group_id, Ausführungstyp und Kategorie getrennt.');
                    END TRY
                    BEGIN CATCH
                        INSERT [#QueryStoreReplicaAnalysis_SourceStatus]
                        ([DatabaseId],[DatabaseName],[SourceName],[SourceObject],[CapturedAtUtc],[StatusCode],[IsPartial],[ReturnedRowCount],[RequiredPermission],[ErrorNumber],[ErrorMessage],[EvidenceLimit])
                        VALUES(@DatabaseId,@DatabaseName,N'waitsByReplica',N'sys.query_store_wait_stats.replica_group_id',@CapturedAtUtc,
                               CASE WHEN ERROR_NUMBER() IN(229,262,297,300,371,916) THEN 'DENIED_PERMISSION' WHEN ERROR_NUMBER()=1222 THEN 'TIMEOUT' ELSE 'ERROR_HANDLED' END,
                               1,0,N'VIEW DATABASE PERFORMANCE STATE',ERROR_NUMBER(),ERROR_MESSAGE(),N'Der Waitfehler ist auf diese Quelle begrenzt.');
                        INSERT [#QueryStoreReplicaAnalysis_Warnings]([DatabaseName],[SourceName],[StatusCode],[ErrorNumber],[Message])
                        VALUES(@DatabaseName,N'waitsByReplica','ERROR_HANDLED',ERROR_NUMBER(),ERROR_MESSAGE());
                        SET @IsPartial=1;
                    END CATCH;
                END
                ELSE
                BEGIN
                    INSERT [#QueryStoreReplicaAnalysis_SourceStatus]
                    ([DatabaseId],[DatabaseName],[SourceName],[SourceObject],[CapturedAtUtc],[StatusCode],[IsPartial],[ReturnedRowCount],[RequiredPermission],[ErrorNumber],[ErrorMessage],[EvidenceLimit])
                    VALUES(@DatabaseId,@DatabaseName,N'waitsByReplica',N'sys.query_store_wait_stats.replica_group_id',@CapturedAtUtc,
                           CASE WHEN @ActualState NOT IN(1,2,4) THEN 'FEATURE_DISABLED'
                                WHEN @WaitStatsCaptureMode<>1 THEN 'NOT_APPLICABLE'
                                ELSE 'UNAVAILABLE_SCHEMA' END,
                           CONVERT(bit,CASE WHEN @ActualState IN(1,2,4) AND @WaitStatsCaptureMode=1 THEN 1 ELSE 0 END),0,
                           N'VIEW DATABASE PERFORMANCE STATE',NULL,NULL,N'Wait-Capture und Pflichtspalte müssen verfügbar sein; fehlendes Wait-Capture ist kein Fehler.');
                    IF @ActualState IN(1,2,4) AND @WaitStatsCaptureMode=1 SET @IsPartial=1;
                END;

                IF @ActualState IN(1,2,4) AND @HasForcingLocations=1 AND @ForcingSchemaValid=1
                BEGIN
                    SELECT @RowsBefore=COUNT_BIG(*) FROM [#QueryStoreReplicaAnalysis_ForcingByReplica];
                    SET @ForcingSql=N'USE '+QUOTENAME(@DatabaseName)+N';
;WITH [ReplicaMap] AS
(
    SELECT [replica_group_id],MIN([role_type]) AS [role_type],MAX(CONVERT(nvarchar(4000),[replica_name])) AS [replica_name]
    FROM [sys].[query_store_replicas] WITH (NOLOCK)
    GROUP BY [replica_group_id]
),
[F] AS
(
    SELECT [pfl].[replica_group_id],COUNT_BIG(*) AS [LocationCount],
           COUNT_BIG(DISTINCT [pfl].[query_id]) AS [QueryCount],COUNT_BIG(DISTINCT [pfl].[plan_id]) AS [PlanCount]
    FROM [sys].[query_store_plan_forcing_locations] AS [pfl] WITH (NOLOCK)
    WHERE NOT EXISTS(SELECT 1 FROM [#QueryStoreReplicaAnalysis_ReplicaFilter])
       OR EXISTS(SELECT 1 FROM [#QueryStoreReplicaAnalysis_ReplicaFilter] AS [rf]
                 WHERE [rf].[IsValid]=1 AND [rf].[ReplicaGroupId]=[pfl].[replica_group_id])
    GROUP BY [pfl].[replica_group_id]
)
INSERT [#QueryStoreReplicaAnalysis_ForcingByReplica]
([CapturedAtUtc],[DatabaseId],[DatabaseName],[CurrentConnectionRoleDesc],[ReplicaGroupId],
 [RoleType],[RoleTypeDesc],[RoleClass],[ReplicaName],[MappingStatusCode],
 [ForcingLocationCount],[ForcedQueryCount],[ForcedPlanCount],[EvidenceLimit])
SELECT @pCapturedAtUtc,@pDatabaseId,@pDatabaseName,@pCurrentRoleDesc,[F].[replica_group_id],
       [rm].[role_type],[mi].[RoleTypeDesc],[mi].[RoleClass],[rm].[replica_name],
       CASE WHEN [rm].[replica_group_id] IS NULL THEN ''REPLICA_METADATA_MISSING'' ELSE ''AVAILABLE'' END,
       [F].[LocationCount],[F].[QueryCount],[F].[PlanCount],
       N''Replica-spezifische Forcing-Locations; keine Planwirkung, Regressionsursache oder Änderungsempfehlung.''
FROM [F]
LEFT JOIN [ReplicaMap] AS [rm] ON [rm].[replica_group_id]=[F].[replica_group_id]
CROSS APPLY [DeineDatenbank].[monitor].[TVF_QueryStoreReplicaRoleInfo]([rm].[role_type]) AS [mi]
OPTION (MAXDOP 1,RECOMPILE);';
                    BEGIN TRY
                        EXEC [sys].[sp_executesql] @ForcingSql,
                             N'@pCapturedAtUtc datetime2(3),@pDatabaseId int,@pDatabaseName sysname,@pCurrentRoleDesc varchar(40)',
                             @CapturedAtUtc,@DatabaseId,@DatabaseName,@CurrentRoleDesc;
                        SELECT @RowsAfter=COUNT_BIG(*) FROM [#QueryStoreReplicaAnalysis_ForcingByReplica];
                        INSERT [#QueryStoreReplicaAnalysis_SourceStatus]
                        ([DatabaseId],[DatabaseName],[SourceName],[SourceObject],[CapturedAtUtc],[StatusCode],[IsPartial],[ReturnedRowCount],[RequiredPermission],[ErrorNumber],[ErrorMessage],[EvidenceLimit])
                        VALUES(@DatabaseId,@DatabaseName,N'forcingByReplica',N'sys.query_store_plan_forcing_locations',@CapturedAtUtc,
                               CASE WHEN @RowsAfter=@RowsBefore THEN 'EMPTY_VISIBLE_SCOPE' ELSE 'AVAILABLE' END,0,@RowsAfter-@RowsBefore,
                               N'VIEW DATABASE PERFORMANCE STATE',NULL,NULL,N'Forcing-Locations werden nach replica_group_id getrennt und ausschließlich inventarisiert.');
                    END TRY
                    BEGIN CATCH
                        INSERT [#QueryStoreReplicaAnalysis_SourceStatus]
                        ([DatabaseId],[DatabaseName],[SourceName],[SourceObject],[CapturedAtUtc],[StatusCode],[IsPartial],[ReturnedRowCount],[RequiredPermission],[ErrorNumber],[ErrorMessage],[EvidenceLimit])
                        VALUES(@DatabaseId,@DatabaseName,N'forcingByReplica',N'sys.query_store_plan_forcing_locations',@CapturedAtUtc,
                               CASE WHEN ERROR_NUMBER() IN(229,262,297,300,371,916) THEN 'DENIED_PERMISSION' WHEN ERROR_NUMBER()=1222 THEN 'TIMEOUT' ELSE 'ERROR_HANDLED' END,
                               1,0,N'VIEW DATABASE PERFORMANCE STATE',ERROR_NUMBER(),ERROR_MESSAGE(),N'Der Forcingfehler ist auf diese Quelle begrenzt.');
                        INSERT [#QueryStoreReplicaAnalysis_Warnings]([DatabaseName],[SourceName],[StatusCode],[ErrorNumber],[Message])
                        VALUES(@DatabaseName,N'forcingByReplica','ERROR_HANDLED',ERROR_NUMBER(),ERROR_MESSAGE());
                        SET @IsPartial=1;
                    END CATCH;
                END
                ELSE
                BEGIN
                    INSERT [#QueryStoreReplicaAnalysis_SourceStatus]
                    ([DatabaseId],[DatabaseName],[SourceName],[SourceObject],[CapturedAtUtc],[StatusCode],[IsPartial],[ReturnedRowCount],[RequiredPermission],[ErrorNumber],[ErrorMessage],[EvidenceLimit])
                    VALUES(@DatabaseId,@DatabaseName,N'forcingByReplica',N'sys.query_store_plan_forcing_locations',@CapturedAtUtc,
                           CASE WHEN @ActualState NOT IN(1,2,4) THEN 'FEATURE_DISABLED'
                                WHEN @HasForcingLocations=0 THEN 'UNAVAILABLE_FEATURE' ELSE 'UNAVAILABLE_SCHEMA' END,
                           CONVERT(bit,CASE WHEN @ActualState IN(1,2,4) THEN 1 ELSE 0 END),0,N'VIEW DATABASE PERFORMANCE STATE',NULL,NULL,
                           N'Die Forcingquelle wird nur nach erfolgreicher Objekt- und Pflichtspaltenprüfung referenziert.');
                    IF @ActualState IN(1,2,4) SET @IsPartial=1;
                END;
            END;

            FETCH NEXT FROM [DatabaseCursor] INTO @DatabaseId,@DatabaseName;
        END;
        CLOSE [DatabaseCursor];
        DEALLOCATE [DatabaseCursor];

        SET @LockTimeoutSql=N'SET LOCK_TIMEOUT '+CONVERT(nvarchar(20),@OriginalLockTimeout)+N';';
        EXEC [sys].[sp_executesql] @LockTimeoutSql;
    END;

    DECLARE @ReplicaCandidateCount bigint=(SELECT COUNT_BIG(*) FROM [#QueryStoreReplicaAnalysis_Replicas]);
    DECLARE @RuntimeCandidateCount bigint=(SELECT COUNT_BIG(*) FROM [#QueryStoreReplicaAnalysis_RuntimeByReplica]);
    DECLARE @WaitCandidateCount bigint=(SELECT COUNT_BIG(*) FROM [#QueryStoreReplicaAnalysis_WaitsByReplica]);
    DECLARE @ForcingCandidateCount bigint=(SELECT COUNT_BIG(*) FROM [#QueryStoreReplicaAnalysis_ForcingByReplica]);
    DECLARE @HasMoreReplicaRows bit=CONVERT(bit,CASE WHEN @ReplicaCandidateCount>@Limit THEN 1 ELSE 0 END);
    DECLARE @HasMoreRuntimeRows bit=CONVERT(bit,CASE WHEN @RuntimeCandidateCount>@Limit THEN 1 ELSE 0 END);
    DECLARE @HasMoreWaitRows bit=CONVERT(bit,CASE WHEN @WaitCandidateCount>@Limit THEN 1 ELSE 0 END);
    DECLARE @HasMoreForcingRows bit=CONVERT(bit,CASE WHEN @ForcingCandidateCount>@Limit THEN 1 ELSE 0 END);

    IF @Limit<9223372036854775807
    BEGIN
        ;WITH [x] AS
        (SELECT *,ROW_NUMBER() OVER(ORDER BY [DatabaseId],[ReplicaGroupId],[RoleType]) AS [rn] FROM [#QueryStoreReplicaAnalysis_Replicas])
        DELETE FROM [x] WHERE [rn]>@Limit;
        ;WITH [x] AS
        (SELECT *,ROW_NUMBER() OVER(ORDER BY [TotalCpuMs] DESC,[LastExecutionTimeUtc] DESC,[DatabaseId],[ReplicaGroupId]) AS [rn] FROM [#QueryStoreReplicaAnalysis_RuntimeByReplica])
        DELETE FROM [x] WHERE [rn]>@Limit;
        ;WITH [x] AS
        (SELECT *,ROW_NUMBER() OVER(ORDER BY [TotalQueryWaitTimeMs] DESC,[LastIntervalEndUtc] DESC,[DatabaseId],[ReplicaGroupId]) AS [rn] FROM [#QueryStoreReplicaAnalysis_WaitsByReplica])
        DELETE FROM [x] WHERE [rn]>@Limit;
        ;WITH [x] AS
        (SELECT *,ROW_NUMBER() OVER(ORDER BY [ForcingLocationCount] DESC,[DatabaseId],[ReplicaGroupId]) AS [rn] FROM [#QueryStoreReplicaAnalysis_ForcingByReplica])
        DELETE FROM [x] WHERE [rn]>@Limit;
    END;

    IF @StatusCode='AVAILABLE'
    BEGIN
        IF @ProductMajorVersion IS NULL OR @ProductMajorVersion<17
            SET @StatusCode='UNAVAILABLE_VERSION';
        ELSE IF @IsPartial=1
            SET @StatusCode='AVAILABLE_LIMITED';
        ELSE IF NOT EXISTS(SELECT 1 FROM [#QueryStoreReplicaAnalysis_Replicas])
             AND NOT EXISTS(SELECT 1 FROM [#QueryStoreReplicaAnalysis_RuntimeByReplica])
             AND NOT EXISTS(SELECT 1 FROM [#QueryStoreReplicaAnalysis_WaitsByReplica])
             AND NOT EXISTS(SELECT 1 FROM [#QueryStoreReplicaAnalysis_ForcingByReplica])
            SET @StatusCode='NOT_APPLICABLE';
    END;

    IF EXISTS(SELECT 1 FROM [#QueryStoreReplicaAnalysis_RuntimeByReplica] WHERE [MappingStatusCode]<>'AVAILABLE')
       OR EXISTS(SELECT 1 FROM [#QueryStoreReplicaAnalysis_WaitsByReplica] WHERE [MappingStatusCode]<>'AVAILABLE')
       OR EXISTS(SELECT 1 FROM [#QueryStoreReplicaAnalysis_ForcingByReplica] WHERE [MappingStatusCode]<>'AVAILABLE')
    BEGIN
        IF @StatusCode='AVAILABLE' SET @StatusCode='AVAILABLE_LIMITED';
        SET @IsPartial=1;
        INSERT [#QueryStoreReplicaAnalysis_Warnings]([DatabaseName],[SourceName],[StatusCode],[ErrorNumber],[Message])
        SELECT DISTINCT [DatabaseName],N'replicaMapping','REPLICA_METADATA_MISSING',NULL,
               N'Mindestens eine replica_group_id besitzt keine sichtbare Zuordnung in sys.query_store_replicas; die Messwerte bleiben getrennt und werden nicht einer Rolle zugeschrieben.'
        FROM
        (
            SELECT [DatabaseName] FROM [#QueryStoreReplicaAnalysis_RuntimeByReplica] WHERE [MappingStatusCode]<>'AVAILABLE'
            UNION
            SELECT [DatabaseName] FROM [#QueryStoreReplicaAnalysis_WaitsByReplica] WHERE [MappingStatusCode]<>'AVAILABLE'
            UNION
            SELECT [DatabaseName] FROM [#QueryStoreReplicaAnalysis_ForcingByReplica] WHERE [MappingStatusCode]<>'AVAILABLE'
        ) AS [u];
    END;

    INSERT [#QueryStoreReplicaAnalysis_ModuleStatus]
    SELECT N'USP_QueryStoreReplicaAnalysis',@CapturedAtUtc,@StatusCode,@IsPartial,@ProductMajorVersion,
           @CrossDatabaseRequested,
           (SELECT COUNT(*) FROM [#QueryStoreReplicaAnalysis_DatabaseCandidates]),
           (SELECT COUNT_BIG(*) FROM [#QueryStoreReplicaAnalysis_Replicas]),
           (SELECT COUNT_BIG(*) FROM [#QueryStoreReplicaAnalysis_RuntimeByReplica]),
           (SELECT COUNT_BIG(*) FROM [#QueryStoreReplicaAnalysis_WaitsByReplica]),
           (SELECT COUNT_BIG(*) FROM [#QueryStoreReplicaAnalysis_ForcingByReplica]),
           @HasMoreReplicaRows,@HasMoreRuntimeRows,@HasMoreWaitRows,@HasMoreForcingRows,@ErrorNumber,@ErrorMessage;

    SELECT @StatusCodeOut=@StatusCode,@IsPartialOut=@IsPartial,@ErrorNumberOut=@ErrorNumber,@ErrorMessageOut=@ErrorMessage;

    IF @JsonErzeugen=1
    BEGIN
        DECLARE @MetaJson nvarchar(max)=
        (
            SELECT N'QueryStoreReplicaAnalysis' AS [resultName],1 AS [schemaVersion],
                   @CapturedAtUtc AS [generatedAtUtc],@StatusCode AS [statusCode],@IsPartial AS [isPartial],
                   @ProductMajorVersion AS [productMajorVersion],@VonUtc AS [fromUtc],@BisUtc AS [toUtc],
                   @MaxZeilen AS [requestedMaxRows],@HasMoreReplicaRows AS [hasMoreReplicaRows],
                   @HasMoreRuntimeRows AS [hasMoreRuntimeRows],@HasMoreWaitRows AS [hasMoreWaitRows],
                   @HasMoreForcingRows AS [hasMoreForcingRows]
            FOR JSON PATH,WITHOUT_ARRAY_WRAPPER,INCLUDE_NULL_VALUES
        );
        DECLARE @ModuleJson nvarchar(max)=(SELECT * FROM [#QueryStoreReplicaAnalysis_ModuleStatus] FOR JSON PATH,INCLUDE_NULL_VALUES);
        DECLARE @ReplicasJson nvarchar(max)=(SELECT * FROM [#QueryStoreReplicaAnalysis_Replicas] ORDER BY [DatabaseId],[ReplicaGroupId],[RoleType] FOR JSON PATH,INCLUDE_NULL_VALUES);
        DECLARE @RuntimeJson nvarchar(max)=(SELECT * FROM [#QueryStoreReplicaAnalysis_RuntimeByReplica] ORDER BY [TotalCpuMs] DESC,[LastExecutionTimeUtc] DESC FOR JSON PATH,INCLUDE_NULL_VALUES);
        DECLARE @WaitsJson nvarchar(max)=(SELECT * FROM [#QueryStoreReplicaAnalysis_WaitsByReplica] ORDER BY [TotalQueryWaitTimeMs] DESC,[LastIntervalEndUtc] DESC FOR JSON PATH,INCLUDE_NULL_VALUES);
        DECLARE @ForcingJson nvarchar(max)=(SELECT * FROM [#QueryStoreReplicaAnalysis_ForcingByReplica] ORDER BY [ForcingLocationCount] DESC,[DatabaseId],[ReplicaGroupId] FOR JSON PATH,INCLUDE_NULL_VALUES);
        DECLARE @SourcesJson nvarchar(max)=(SELECT * FROM [#QueryStoreReplicaAnalysis_SourceStatus] ORDER BY [SourceOrdinal] FOR JSON PATH,INCLUDE_NULL_VALUES);
        DECLARE @WarningsJson nvarchar(max)=(SELECT * FROM [#QueryStoreReplicaAnalysis_Warnings] ORDER BY [WarningOrdinal] FOR JSON PATH,INCLUDE_NULL_VALUES);
        SET @Json=CONCAT(N'{"meta":',COALESCE(@MetaJson,N'{}'),
                         N',"moduleStatus":',COALESCE(@ModuleJson,N'[]'),
                         N',"replicas":',COALESCE(@ReplicasJson,N'[]'),
                         N',"runtimeByReplica":',COALESCE(@RuntimeJson,N'[]'),
                         N',"waitsByReplica":',COALESCE(@WaitsJson,N'[]'),
                         N',"forcingByReplica":',COALESCE(@ForcingJson,N'[]'),
                         N',"sourceStatus":',COALESCE(@SourcesJson,N'[]'),
                         N',"warnings":',COALESCE(@WarningsJson,N'[]'),N'}');
    END;

    IF @ConsoleResultRequested=1
    BEGIN
        EXEC [monitor].[InternalEmitConsoleResult]
              @SourceTable=N'#QueryStoreReplicaAnalysis_ModuleStatus'
            , @ResultLabel=N'QueryStoreReplicaAnalysis'
            , @EmptyMessage=N'Keine Query-Store-Replica-Evidenz im sichtbaren Scope';
    END
    ELSE IF @OutputMode='RAW'
    BEGIN
        SELECT * FROM [#QueryStoreReplicaAnalysis_ModuleStatus];
        SELECT * FROM [#QueryStoreReplicaAnalysis_Replicas] ORDER BY [DatabaseId],[ReplicaGroupId],[RoleType];
        SELECT * FROM [#QueryStoreReplicaAnalysis_RuntimeByReplica] ORDER BY [TotalCpuMs] DESC,[LastExecutionTimeUtc] DESC;
        SELECT * FROM [#QueryStoreReplicaAnalysis_WaitsByReplica] ORDER BY [TotalQueryWaitTimeMs] DESC,[LastIntervalEndUtc] DESC;
        SELECT * FROM [#QueryStoreReplicaAnalysis_ForcingByReplica] ORDER BY [ForcingLocationCount] DESC,[DatabaseId],[ReplicaGroupId];
        SELECT * FROM [#QueryStoreReplicaAnalysis_SourceStatus] ORDER BY [SourceOrdinal];
        SELECT * FROM [#QueryStoreReplicaAnalysis_Warnings] ORDER BY [WarningOrdinal];
    END
    ELSE IF @OutputMode='TABLE'
    BEGIN
        DECLARE @TargetTable sysname;
        SELECT @TargetTable=[TargetTable] FROM [#QueryStoreReplicaAnalysis_ResultTableMap] WHERE [ResultName]=N'moduleStatus';
        IF @TargetTable IS NOT NULL EXEC [monitor].[InternalWriteResultTable] @SourceTable=N'#QueryStoreReplicaAnalysis_ModuleStatus',@TargetTable=@TargetTable,@ThrowOnError=1;
        SELECT @TargetTable=[TargetTable] FROM [#QueryStoreReplicaAnalysis_ResultTableMap] WHERE [ResultName]=N'replicas';
        IF @TargetTable IS NOT NULL EXEC [monitor].[InternalWriteResultTable] @SourceTable=N'#QueryStoreReplicaAnalysis_Replicas',@TargetTable=@TargetTable,@ThrowOnError=1;
        SELECT @TargetTable=[TargetTable] FROM [#QueryStoreReplicaAnalysis_ResultTableMap] WHERE [ResultName]=N'runtimeByReplica';
        IF @TargetTable IS NOT NULL EXEC [monitor].[InternalWriteResultTable] @SourceTable=N'#QueryStoreReplicaAnalysis_RuntimeByReplica',@TargetTable=@TargetTable,@ThrowOnError=1;
        SELECT @TargetTable=[TargetTable] FROM [#QueryStoreReplicaAnalysis_ResultTableMap] WHERE [ResultName]=N'waitsByReplica';
        IF @TargetTable IS NOT NULL EXEC [monitor].[InternalWriteResultTable] @SourceTable=N'#QueryStoreReplicaAnalysis_WaitsByReplica',@TargetTable=@TargetTable,@ThrowOnError=1;
        SELECT @TargetTable=[TargetTable] FROM [#QueryStoreReplicaAnalysis_ResultTableMap] WHERE [ResultName]=N'forcingByReplica';
        IF @TargetTable IS NOT NULL EXEC [monitor].[InternalWriteResultTable] @SourceTable=N'#QueryStoreReplicaAnalysis_ForcingByReplica',@TargetTable=@TargetTable,@ThrowOnError=1;
        SELECT @TargetTable=[TargetTable] FROM [#QueryStoreReplicaAnalysis_ResultTableMap] WHERE [ResultName]=N'sourceStatus';
        IF @TargetTable IS NOT NULL EXEC [monitor].[InternalWriteResultTable] @SourceTable=N'#QueryStoreReplicaAnalysis_SourceStatus',@TargetTable=@TargetTable,@ThrowOnError=1;
        SELECT @TargetTable=[TargetTable] FROM [#QueryStoreReplicaAnalysis_ResultTableMap] WHERE [ResultName]=N'warnings';
        IF @TargetTable IS NOT NULL EXEC [monitor].[InternalWriteResultTable] @SourceTable=N'#QueryStoreReplicaAnalysis_Warnings',@TargetTable=@TargetTable,@ThrowOnError=1;
    END;
END;
GO
-- END SOURCE: Code/05_QueryStore/100_USP_QueryStoreReplicaAnalysis.sql

-- BEGIN SOURCE: Code/05_QueryStore/080_USP_QueryStoreAnalysis.sql
/*
===============================================================================
Objekt       : monitor.USP_QueryStoreAnalysis
Version      : 2.2.0
Stand        : 2026-07-27
Zweck        : Orchestriert Query-Store-Module mit einheitlichem Quell- und
               Referenzdatenbankvertrag. JSON enthält benannte Modulobjekte.
Änderungen   : 2.2.0 - SQL25-005 Replica-Kontext als versionsadaptives Standardteilmodul.
                2.1.0 - IQP-Evidenz als kostenbewusstes opt-in Teilmodul.
               2.0.1 - IF/TRY/CATCH-Blöcke syntaktisch eindeutig strukturiert.
===============================================================================
*/
CREATE OR ALTER PROCEDURE [monitor].[USP_QueryStoreAnalysis]
      @QueryStoreDatabaseNames          nvarchar(max)  = NULL
    , @QueryStoreDatabaseNamePattern    nvarchar(4000) = NULL
    , @HighImpactConfirmed              bit            = 0
    , @ReferencedDatabaseNames          nvarchar(max)  = NULL
    , @ReferencedDatabaseNamePattern    nvarchar(4000) = NULL
    , @VonUtc                           datetime2(7)   = NULL
    , @BisUtc                           datetime2(7)   = NULL
    , @MitStatus                        bit            = 1
    , @MitRuntimeStats                  bit            = 1
    , @MitWaitStats                     bit            = 0
    , @MitPlanChanges                   bit            = 0
    , @MitRegressionen                  bit            = 0
    , @MitForcedPlans                   bit            = 0
    , @MitHints                         bit            = 0
    , @MitReplicaKontext                bit            = 1
    , @MitIQP                           bit            = 0
    , @MaxZeilen                        int            = 100
    , @ResultSetArt                     varchar(16)    = 'CONSOLE'
    , @ResultTablesJson               nvarchar(max) = NULL
    , @JsonErzeugen                     bit            = 0
    , @Json                             nvarchar(max)  = NULL OUTPUT
    , @PrintMeldungen                   bit            = 1
    , @Hilfe                            bit            = 0
AS
BEGIN
    SET NOCOUNT ON;
    SET LOCK_TIMEOUT 0;
    SET @Json = NULL;

    DECLARE @OutputMode varchar(16) = UPPER(LTRIM(RTRIM(COALESCE(@ResultSetArt, ''))));
    DECLARE @TableResultRequested bit = CASE WHEN @OutputMode = 'TABLE' THEN 1 ELSE 0 END;
    DECLARE @ConsoleResultRequested bit = CASE WHEN @OutputMode = 'CONSOLE' THEN 1 ELSE 0 END;
    DECLARE @TableTarget sysname=NULL;
    IF @TableResultRequested=0 AND NULLIF(LTRIM(RTRIM(COALESCE(@ResultTablesJson,N''))),N'') IS NOT NULL THROW 51011,N'@ResultTablesJson ist ausschließlich mit @ResultSetArt=TABLE zulässig.',1;
    IF @TableResultRequested=1 EXEC [monitor].[InternalPrepareSingleResultTable] @ResultTablesJson=@ResultTablesJson,@ResultName=N'moduleStatus',@TargetTable=@TableTarget OUTPUT,@ThrowOnError=1;
    IF @TableResultRequested = 1 OR @ConsoleResultRequested = 1 SET @OutputMode = 'NONE';
    DECLARE @Now datetime2(3) = SYSUTCDATETIME();
    DECLARE @StatusCode varchar(40) = 'AVAILABLE';
    DECLARE @StatusJson nvarchar(max);
    DECLARE @RuntimeJson nvarchar(max);
    DECLARE @WaitJson nvarchar(max);
    DECLARE @PlanJson nvarchar(max);
    DECLARE @RegressionJson nvarchar(max);
    DECLARE @ForcedJson nvarchar(max);
    DECLARE @HintsJson nvarchar(max);
    DECLARE @ReplicaJson nvarchar(max);
    DECLARE @ReplicaStatus varchar(40)=NULL;
    DECLARE @ReplicaPartial bit=NULL;
    DECLARE @ReplicaErrorNumber int=NULL;
    DECLARE @ReplicaErrorMessage nvarchar(2048)=NULL;
    DECLARE @IqpJson nvarchar(max);
    DECLARE @IqpStatus varchar(40) = NULL;
    DECLARE @IqpPartial bit = NULL;
    DECLARE @IqpErrorNumber int = NULL;
    DECLARE @IqpErrorMessage nvarchar(2048) = NULL;

    DECLARE @ModuleStatus TABLE
    (
          [ExecutionOrdinal] tinyint        NOT NULL
        , [ModuleName]       sysname        NOT NULL
        , [InvocationStatus] varchar(40)    NOT NULL
        , [ErrorNumber]      int            NULL
        , [ErrorMessage]     nvarchar(2048) NULL
    );

    IF @Hilfe = 1
    BEGIN
        PRINT N'monitor.USP_QueryStoreAnalysis';
        PRINT N'@QueryStoreDatabaseNames/Pattern bestimmen Query-Store-Quellen.';
        PRINT N'@ReferencedDatabaseNames/Pattern filtern in Showplans verwendete Datenbanken.';
        PRINT N'@MitReplicaKontext=1 ergänzt SQL25-005 mit rollengetrennter Query-Store-Evidenz; vor SQL Server 2025 kontrolliert UNAVAILABLE_VERSION.';
        PRINT N'@ResultSetArt = RAW, CONSOLE, TABLE oder NONE; optional JSON über @Json OUTPUT.';
        RETURN;
    END;

    IF @MaxZeilen < 0
       OR @OutputMode NOT IN ('RAW', 'CONSOLE', 'NONE')
       OR (@VonUtc IS NOT NULL AND @BisUtc IS NOT NULL AND @VonUtc > @BisUtc)
       OR (@MitStatus = 0 AND @MitRuntimeStats = 0 AND @MitWaitStats = 0
           AND @MitPlanChanges = 0 AND @MitRegressionen = 0
           AND @MitForcedPlans = 0 AND @MitHints = 0 AND @MitReplicaKontext = 0 AND @MitIQP = 0)
    BEGIN
        SET @StatusCode = 'INVALID_PARAMETER';
    END;

    IF @StatusCode = 'AVAILABLE' AND @MitStatus = 1
    BEGIN
        BEGIN TRY
            EXEC [monitor].[USP_QueryStoreStatus]
                  @QueryStoreDatabaseNames = @QueryStoreDatabaseNames
                , @QueryStoreDatabaseNamePattern = @QueryStoreDatabaseNamePattern,@HighImpactConfirmed=@HighImpactConfirmed

                , @ResultSetArt = @OutputMode
                , @JsonErzeugen = @JsonErzeugen
                , @Json = @StatusJson OUTPUT
                , @PrintMeldungen = @PrintMeldungen;

            INSERT @ModuleStatus VALUES (1, N'USP_QueryStoreStatus', 'EXECUTED', NULL, NULL);
        END TRY
        BEGIN CATCH
            INSERT @ModuleStatus VALUES (1, N'USP_QueryStoreStatus', 'ERROR_HANDLED', ERROR_NUMBER(), ERROR_MESSAGE());
        END CATCH;
    END;

    IF @StatusCode = 'AVAILABLE' AND @MitRuntimeStats = 1
    BEGIN
        BEGIN TRY
            EXEC [monitor].[USP_QueryStoreRuntimeStats]
                  @QueryStoreDatabaseNames = @QueryStoreDatabaseNames
                , @QueryStoreDatabaseNamePattern = @QueryStoreDatabaseNamePattern,@HighImpactConfirmed=@HighImpactConfirmed
                , @ReferencedDatabaseNames = @ReferencedDatabaseNames
                , @ReferencedDatabaseNamePattern = @ReferencedDatabaseNamePattern
                , @VonUtc = @VonUtc
                , @BisUtc = @BisUtc

                , @MaxZeilen = @MaxZeilen
                , @ResultSetArt = @OutputMode
                , @JsonErzeugen = @JsonErzeugen
                , @Json = @RuntimeJson OUTPUT
                , @PrintMeldungen = @PrintMeldungen;

            INSERT @ModuleStatus VALUES (2, N'USP_QueryStoreRuntimeStats', 'EXECUTED', NULL, NULL);
        END TRY
        BEGIN CATCH
            INSERT @ModuleStatus VALUES (2, N'USP_QueryStoreRuntimeStats', 'ERROR_HANDLED', ERROR_NUMBER(), ERROR_MESSAGE());
        END CATCH;
    END;

    IF @StatusCode = 'AVAILABLE' AND @MitWaitStats = 1
    BEGIN
        BEGIN TRY
            EXEC [monitor].[USP_QueryStoreWaitStats]
                  @QueryStoreDatabaseNames = @QueryStoreDatabaseNames
                , @QueryStoreDatabaseNamePattern = @QueryStoreDatabaseNamePattern,@HighImpactConfirmed=@HighImpactConfirmed
                , @ReferencedDatabaseNames = @ReferencedDatabaseNames
                , @ReferencedDatabaseNamePattern = @ReferencedDatabaseNamePattern
                , @VonUtc = @VonUtc
                , @BisUtc = @BisUtc

                , @MaxZeilen = @MaxZeilen
                , @ResultSetArt = @OutputMode
                , @JsonErzeugen = @JsonErzeugen
                , @Json = @WaitJson OUTPUT
                , @PrintMeldungen = @PrintMeldungen;

            INSERT @ModuleStatus VALUES (3, N'USP_QueryStoreWaitStats', 'EXECUTED', NULL, NULL);
        END TRY
        BEGIN CATCH
            INSERT @ModuleStatus VALUES (3, N'USP_QueryStoreWaitStats', 'ERROR_HANDLED', ERROR_NUMBER(), ERROR_MESSAGE());
        END CATCH;
    END;

    IF @StatusCode = 'AVAILABLE' AND @MitPlanChanges = 1
    BEGIN
        BEGIN TRY
            EXEC [monitor].[USP_QueryStorePlanChanges]
                  @QueryStoreDatabaseNames = @QueryStoreDatabaseNames
                , @QueryStoreDatabaseNamePattern = @QueryStoreDatabaseNamePattern,@HighImpactConfirmed=@HighImpactConfirmed
                , @ReferencedDatabaseNames = @ReferencedDatabaseNames
                , @ReferencedDatabaseNamePattern = @ReferencedDatabaseNamePattern
                , @VonUtc = @VonUtc

                , @MaxZeilen = @MaxZeilen
                , @ResultSetArt = @OutputMode
                , @JsonErzeugen = @JsonErzeugen
                , @Json = @PlanJson OUTPUT
                , @PrintMeldungen = @PrintMeldungen;

            INSERT @ModuleStatus VALUES (4, N'USP_QueryStorePlanChanges', 'EXECUTED', NULL, NULL);
        END TRY
        BEGIN CATCH
            INSERT @ModuleStatus VALUES (4, N'USP_QueryStorePlanChanges', 'ERROR_HANDLED', ERROR_NUMBER(), ERROR_MESSAGE());
        END CATCH;
    END;

    IF @StatusCode = 'AVAILABLE' AND @MitRegressionen = 1
    BEGIN
        BEGIN TRY
            EXEC [monitor].[USP_QueryStoreRegressions]
                  @QueryStoreDatabaseNames = @QueryStoreDatabaseNames
                , @QueryStoreDatabaseNamePattern = @QueryStoreDatabaseNamePattern,@HighImpactConfirmed=@HighImpactConfirmed
                , @ReferencedDatabaseNames = @ReferencedDatabaseNames
                , @ReferencedDatabaseNamePattern = @ReferencedDatabaseNamePattern
                , @VergleichVonUtc = @VonUtc
                , @VergleichBisUtc = @BisUtc

                , @MaxZeilen = @MaxZeilen
                , @ResultSetArt = @OutputMode
                , @JsonErzeugen = @JsonErzeugen
                , @Json = @RegressionJson OUTPUT
                , @PrintMeldungen = @PrintMeldungen;

            INSERT @ModuleStatus VALUES (5, N'USP_QueryStoreRegressions', 'EXECUTED', NULL, NULL);
        END TRY
        BEGIN CATCH
            INSERT @ModuleStatus VALUES (5, N'USP_QueryStoreRegressions', 'ERROR_HANDLED', ERROR_NUMBER(), ERROR_MESSAGE());
        END CATCH;
    END;

    IF @StatusCode = 'AVAILABLE' AND @MitForcedPlans = 1
    BEGIN
        BEGIN TRY
            EXEC [monitor].[USP_QueryStoreForcedPlans]
                  @QueryStoreDatabaseNames = @QueryStoreDatabaseNames
                , @QueryStoreDatabaseNamePattern = @QueryStoreDatabaseNamePattern,@HighImpactConfirmed=@HighImpactConfirmed
                , @ReferencedDatabaseNames = @ReferencedDatabaseNames
                , @ReferencedDatabaseNamePattern = @ReferencedDatabaseNamePattern

                , @MaxZeilen = @MaxZeilen
                , @ResultSetArt = @OutputMode
                , @JsonErzeugen = @JsonErzeugen
                , @Json = @ForcedJson OUTPUT
                , @PrintMeldungen = @PrintMeldungen;

            INSERT @ModuleStatus VALUES (6, N'USP_QueryStoreForcedPlans', 'EXECUTED', NULL, NULL);
        END TRY
        BEGIN CATCH
            INSERT @ModuleStatus VALUES (6, N'USP_QueryStoreForcedPlans', 'ERROR_HANDLED', ERROR_NUMBER(), ERROR_MESSAGE());
        END CATCH;
    END;

    IF @StatusCode = 'AVAILABLE' AND @MitHints = 1
    BEGIN
        BEGIN TRY
            EXEC [monitor].[USP_QueryStoreHints]
                  @QueryStoreDatabaseNames = @QueryStoreDatabaseNames
                , @QueryStoreDatabaseNamePattern = @QueryStoreDatabaseNamePattern,@HighImpactConfirmed=@HighImpactConfirmed

                , @MaxZeilen = @MaxZeilen
                , @ResultSetArt = @OutputMode
                , @JsonErzeugen = @JsonErzeugen
                , @Json = @HintsJson OUTPUT
                , @PrintMeldungen = @PrintMeldungen;

            INSERT @ModuleStatus VALUES (7, N'USP_QueryStoreHints', 'EXECUTED', NULL, NULL);
        END TRY
        BEGIN CATCH
            INSERT @ModuleStatus VALUES (7, N'USP_QueryStoreHints', 'ERROR_HANDLED', ERROR_NUMBER(), ERROR_MESSAGE());
        END CATCH;
    END;


    IF @StatusCode = 'AVAILABLE' AND @MitReplicaKontext = 1
    BEGIN
        BEGIN TRY
            EXEC [monitor].[USP_QueryStoreReplicaAnalysis]
                  @QueryStoreDatabaseNames = @QueryStoreDatabaseNames
                , @QueryStoreDatabaseNamePattern = @QueryStoreDatabaseNamePattern
                , @HighImpactConfirmed = @HighImpactConfirmed
                , @VonUtc = @VonUtc
                , @BisUtc = @BisUtc
                , @MaxZeilen = @MaxZeilen
                , @ResultSetArt = @OutputMode
                , @JsonErzeugen = @JsonErzeugen
                , @Json = @ReplicaJson OUTPUT
                , @PrintMeldungen = @PrintMeldungen
                , @StatusCodeOut = @ReplicaStatus OUTPUT
                , @IsPartialOut = @ReplicaPartial OUTPUT
                , @ErrorNumberOut = @ReplicaErrorNumber OUTPUT
                , @ErrorMessageOut = @ReplicaErrorMessage OUTPUT;

            INSERT @ModuleStatus VALUES
            (8, N'USP_QueryStoreReplicaAnalysis', COALESCE(@ReplicaStatus, 'ERROR_HANDLED'), @ReplicaErrorNumber, @ReplicaErrorMessage);
        END TRY
        BEGIN CATCH
            INSERT @ModuleStatus VALUES (8, N'USP_QueryStoreReplicaAnalysis', 'ERROR_HANDLED', ERROR_NUMBER(), ERROR_MESSAGE());
        END CATCH;
    END;

    IF @StatusCode = 'AVAILABLE' AND @MitIQP = 1
    BEGIN
        BEGIN TRY
            EXEC [monitor].[USP_IntelligentQueryProcessingAnalysis]
                  @DatabaseNames = @QueryStoreDatabaseNames
                , @DatabaseNamePattern = @QueryStoreDatabaseNamePattern,@HighImpactConfirmed=@HighImpactConfirmed

                , @MaxZeilen = @MaxZeilen
                , @ResultSetArt = @OutputMode
                , @JsonErzeugen = @JsonErzeugen
                , @Json = @IqpJson OUTPUT
                , @PrintMeldungen = @PrintMeldungen
                , @StatusCodeOut = @IqpStatus OUTPUT
                , @IsPartialOut = @IqpPartial OUTPUT
                , @ErrorNumberOut = @IqpErrorNumber OUTPUT
                , @ErrorMessageOut = @IqpErrorMessage OUTPUT;

            INSERT @ModuleStatus VALUES
            (9, N'USP_IntelligentQueryProcessingAnalysis', COALESCE(@IqpStatus, 'ERROR_HANDLED'), @IqpErrorNumber, @IqpErrorMessage);
        END TRY
        BEGIN CATCH
            INSERT @ModuleStatus VALUES (9, N'USP_IntelligentQueryProcessingAnalysis', 'ERROR_HANDLED', ERROR_NUMBER(), ERROR_MESSAGE());
        END CATCH;
    END;

    IF EXISTS (SELECT 1 FROM @ModuleStatus
               WHERE [InvocationStatus] NOT IN ('EXECUTED','AVAILABLE','AVAILABLE_WITH_FINDING','NOT_APPLICABLE','UNAVAILABLE_VERSION','UNAVAILABLE_FEATURE','FEATURE_DISABLED'))
       AND @StatusCode = 'AVAILABLE'
    BEGIN
        SET @StatusCode = 'AVAILABLE_LIMITED';
    END
    ELSE IF EXISTS (SELECT 1 FROM @ModuleStatus WHERE [InvocationStatus] = 'AVAILABLE_WITH_FINDING')
         AND @StatusCode = 'AVAILABLE'
        SET @StatusCode = 'AVAILABLE_WITH_FINDING';

    IF @OutputMode <> 'NONE'
    BEGIN
        SELECT
              N'USP_QueryStoreAnalysis' AS [ModuleName]
            , @Now                     AS [CollectionTimeUtc]
            , @StatusCode              AS [StatusCode]
            , CONVERT(bit, CASE WHEN @StatusCode IN ('AVAILABLE','AVAILABLE_WITH_FINDING') THEN 0 ELSE 1 END) AS [IsPartial]
            , (SELECT COUNT_BIG(*) FROM @ModuleStatus
               WHERE [InvocationStatus] NOT IN ('EXECUTED','AVAILABLE','AVAILABLE_WITH_FINDING','NOT_APPLICABLE','UNAVAILABLE_VERSION','UNAVAILABLE_FEATURE','FEATURE_DISABLED')) AS [ErrorCount]
            , N'Orchestrator; Teilmodule liefern eigene benannte Resultsets.' AS [Detail];

        IF @OutputMode = 'RAW'
        BEGIN
            SELECT * FROM @ModuleStatus ORDER BY [ExecutionOrdinal];
        END
        ELSE
        BEGIN
            SELECT
                  N'Query-Store Teilmodul' AS [Ergebnis]
                , [ExecutionOrdinal]       AS [Reihenfolge]
                , [ModuleName]             AS [Modul]
                , [InvocationStatus]       AS [Status]
                , [ErrorMessage]           AS [Fehler]
            FROM @ModuleStatus
            ORDER BY [ExecutionOrdinal];
        END;
    END;

    IF @JsonErzeugen = 1
    BEGIN
        DECLARE @Warnings nvarchar(max);
        DECLARE @Meta nvarchar(max);

        SELECT @Warnings =
        (
            SELECT *
            FROM @ModuleStatus
            WHERE [InvocationStatus] NOT IN ('EXECUTED','AVAILABLE','AVAILABLE_WITH_FINDING','NOT_APPLICABLE','UNAVAILABLE_VERSION','UNAVAILABLE_FEATURE','FEATURE_DISABLED')
            ORDER BY [ExecutionOrdinal]
            FOR JSON PATH, INCLUDE_NULL_VALUES
        );

        SELECT @Meta =
        (
            SELECT
                  N'QueryStoreAnalysis' AS [resultName]
                , 1                     AS [schemaVersion]
                , @Now                  AS [generatedAtUtc]
                , @StatusCode           AS [statusCode]
            FOR JSON PATH, WITHOUT_ARRAY_WRAPPER
        );

        SET @Json = CONCAT
        (
              N'{"meta":', COALESCE(@Meta, N'{}')
            , N',"status":', COALESCE(JSON_QUERY(@StatusJson), N'null')
            , N',"runtimeStats":', COALESCE(JSON_QUERY(@RuntimeJson), N'null')
            , N',"waitStats":', COALESCE(JSON_QUERY(@WaitJson), N'null')
            , N',"planChanges":', COALESCE(JSON_QUERY(@PlanJson), N'null')
            , N',"regressions":', COALESCE(JSON_QUERY(@RegressionJson), N'null')
            , N',"forcedPlans":', COALESCE(JSON_QUERY(@ForcedJson), N'null')
            , N',"queryHints":', COALESCE(JSON_QUERY(@HintsJson), N'null')
            , N',"replicaContext":', COALESCE(JSON_QUERY(@ReplicaJson), N'null')
            , N',"intelligentQueryProcessing":', COALESCE(JSON_QUERY(@IqpJson), N'null')
            , N',"warnings":', COALESCE(@Warnings, N'[]')
            , N'}'
        );
    END;
    IF @ConsoleResultRequested = 1
    BEGIN
        EXEC [monitor].[InternalEmitConsoleResult]
              @SourceTable=N'#QueryStoreAnalysis_MonitorTableResult'
            , @ResultLabel=N'QueryStoreAnalysis'
            , @EmptyMessage=N'Keine fachlichen Ergebnisse';
    END;
    IF @TableResultRequested = 1
    BEGIN
        SELECT * INTO [#QueryStoreAnalysis_MonitorTableResult] FROM @ModuleStatus;
        EXEC [monitor].[InternalWriteResultTable]
              @SourceTable = N'#QueryStoreAnalysis_MonitorTableResult'
            , @TargetTable=@TableTarget
            , @ThrowOnError = 1;
    END;
END;
GO
-- END SOURCE: Code/05_QueryStore/080_USP_QueryStoreAnalysis.sql

-- BEGIN SOURCE: Code/06_ExtendedEvents/010_USP_ExtendedEventsSessions.sql
/*
===============================================================================
Objekt       : monitor.USP_ExtendedEventsSessions
Version      : 1.0.2
Stand        : 2026-07-15
Typ          : Stored Procedure
Zweck        : Inventarisiert vorhandene serverweite Extended-Events-Sessions,
               deren Definitionen, Laufzeitstatus, Events, Actions, Targets und
               explizit konfigurierte Felder. Es werden keine Sessions erstellt,
               gestartet, gestoppt, geändert oder gelöscht.
SQL-Version  : SQL Server 2019 oder neuer.
Datenquellen : sys.server_event_sessions, sys.server_event_session_events,
               sys.server_event_session_actions, sys.server_event_session_targets,
               sys.server_event_session_fields, optional sys.dm_xe_sessions.
Parameter    : @SessionNameLike, @NurLaufend, @MitLaufzeitstatus, @MitEvents,
               @MitActions, @MitTargets, @MitFeldern, @MaxZeilen,
               @PrintMeldungen, @Hilfe.
Resultsets   : 1. Modulstatus. 2. Sessions. 3. Events. 4. Actions. 5. Targets.
               6. konfigurierte Felder. Nicht aktivierte Resultsets bleiben leer.
Berechtigung : SQL Server 2019 VIEW SERVER STATE; SQL Server 2022+ VIEW SERVER
               PERFORMANCE STATE oder höher. Das Framework vergibt keine Rechte.
Eigenlast    : Gering. Es werden nur Extended-Events-Katalogviews und optional
               sys.dm_xe_sessions gelesen. Targetdaten werden nicht gelesen.
Locking      : LOCK_TIMEOUT 0; keine Benutzerobjekte, keine Änderungen.
Partial      : Fehlende Berechtigungen liefern strukturierte Status- und leere
               Ergebnis-Resultsets; andere Framework-Module bleiben nutzbar.
Beispiele    : EXEC monitor.USP_ExtendedEventsSessions;
               EXEC monitor.USP_ExtendedEventsSessions @SessionNameLike=N'system_health';
               EXEC monitor.USP_ExtendedEventsSessions @Hilfe=1;
Änderungen   : 1.0.2 - total_target_memory wird nur bei nachgewiesener Spaltenverfügbarkeit gelesen; SQL Server 2019 liefert NULL.
               1.0.1 - Alias [ObjectType] für die sortierte Feldklassifikation ergänzt.
               1.0.0 - Erstfassung Phase 5.
===============================================================================
*/
CREATE OR ALTER PROCEDURE [monitor].[USP_ExtendedEventsSessions]
      @ExtendedEventSessionNames       nvarchar(max)  = NULL
    , @ExtendedEventSessionNamePattern nvarchar(4000) = NULL
    , @EventNames                      nvarchar(max)  = NULL
    , @EventNamePattern                nvarchar(4000) = NULL
    , @TargetNames                     nvarchar(max)  = NULL
    , @TargetNamePattern               nvarchar(4000) = NULL
    , @NurLaufend           bit           = 0
    , @MitLaufzeitstatus    bit           = 1
    , @MitEvents            bit           = 1
    , @MitActions           bit           = 1
    , @MitTargets           bit           = 1
    , @MitFeldern           bit           = 0
    , @MaxZeilen            int           = 5000
    , @ResultSetArt                   varchar(16)    = 'CONSOLE'
    , @ResultTablesJson               nvarchar(max) = NULL
    , @JsonErzeugen                   bit            = 0
    , @Json                            nvarchar(max)  = NULL OUTPUT
    , @PrintMeldungen       bit           = 1
    , @Hilfe                bit           = 0
AS
BEGIN
    SET NOCOUNT ON;
    SET @Json=NULL;
    DECLARE @ResultSetArtNormalisiert varchar(16)=UPPER(LTRIM(RTRIM(COALESCE(@ResultSetArt,''))));
    DECLARE @TableResultRequested bit = CASE WHEN @ResultSetArtNormalisiert = 'TABLE' THEN 1 ELSE 0 END;
    DECLARE @ConsoleResultRequested bit = CASE WHEN @ResultSetArtNormalisiert = 'CONSOLE' THEN 1 ELSE 0 END;
    DECLARE @TableTarget sysname=NULL;
    IF @TableResultRequested=0 AND NULLIF(LTRIM(RTRIM(COALESCE(@ResultTablesJson,N''))),N'') IS NOT NULL THROW 51011,N'@ResultTablesJson ist ausschließlich mit @ResultSetArt=TABLE zulässig.',1;
    IF @TableResultRequested=1 EXEC [monitor].[InternalPrepareSingleResultTable] @ResultTablesJson=@ResultTablesJson,@ResultName=N'sessions',@TargetTable=@TableTarget OUTPUT,@ThrowOnError=1;
    IF @TableResultRequested = 1 OR @ConsoleResultRequested = 1 SET @ResultSetArtNormalisiert = 'NONE';
    DECLARE @SessionPatternMode varchar(8),@SessionPatternValue nvarchar(4000),@SessionPatternFlags varchar(8),@SessionPatternValid bit;
    DECLARE @EventPatternMode varchar(8),@EventPatternValue nvarchar(4000),@EventPatternFlags varchar(8),@EventPatternValid bit;
    DECLARE @TargetPatternMode varchar(8),@TargetPatternValue nvarchar(4000),@TargetPatternFlags varchar(8),@TargetPatternValid bit;
    DECLARE @EffectiveMaxZeilen bigint = CASE WHEN @MaxZeilen IS NULL OR @MaxZeilen=0 THEN CONVERT(bigint,9223372036854775807) ELSE CONVERT(bigint,@MaxZeilen) END;
    DECLARE @MonitorPrintMessage nvarchar(2048);

    IF @Hilfe = 1
    BEGIN
        PRINT N'monitor.USP_ExtendedEventsSessions';
        PRINT N'@ExtendedEventSessionNames: bracket-aware Pipe-Liste; @ExtendedEventSessionNamePattern: LIKE/Regex-Pattern.';
        PRINT N'@NurLaufend bit=0: 1 zeigt nur aktuell laufende Sessions.';
        PRINT N'@MitLaufzeitstatus bit=1: ergänzt Laufzeitinformationen aus sys.dm_xe_sessions; liest keine Targetdaten.';
        PRINT N'@MitEvents bit=1: gibt konfigurierte Events aus.';
        PRINT N'@MitActions bit=1: gibt konfigurierte Actions aus.';
        PRINT N'@MitTargets bit=1: gibt konfigurierte Targets aus.';
        PRINT N'@MitFeldern bit=0: gibt explizit konfigurierte Event-/Targetfelder aus.';
        PRINT N'@MaxZeilen int=5000: positive Werte begrenzen jedes Detailresultset; NULL/0 = unbegrenzt.';
        PRINT N'@PrintMeldungen bit=1: Warnungen zusätzlich via RAISERROR Severity 10.';
        PRINT N'@Hilfe bit=0: 1 zeigt diese Hilfe und beendet die Procedure.';
        PRINT N'Die Procedure erstellt, startet, stoppt, ändert oder löscht keine Extended-Events-Session.';
        RETURN;
    END;

    DECLARE
        @CollectionTimeUtc datetime2(3) = SYSUTCDATETIME(),
        @StatusCode varchar(40) = 'AVAILABLE',
        @IsPartial bit = 0,
        @ErrorNumber int = NULL,
        @ErrorMessage nvarchar(2048) = NULL,
        @RowCount bigint = 0;

    CREATE TABLE [#ExtendedEventsSessions_SessionNameFilter]([NameValue] sysname NOT NULL PRIMARY KEY);
    CREATE TABLE [#ExtendedEventsSessions_EventNameFilter]([NameValue] sysname NOT NULL PRIMARY KEY);
    CREATE TABLE [#ExtendedEventsSessions_TargetNameFilter]([NameValue] sysname NOT NULL PRIMARY KEY);
    SELECT @SessionPatternMode=[PatternMode],@SessionPatternValue=[PatternValue],@SessionPatternFlags=[RegexFlags],@SessionPatternValid=[IsValid] FROM [monitor].[TVF_ParsePattern](@ExtendedEventSessionNamePattern);
    SELECT @EventPatternMode=[PatternMode],@EventPatternValue=[PatternValue],@EventPatternFlags=[RegexFlags],@EventPatternValid=[IsValid] FROM [monitor].[TVF_ParsePattern](@EventNamePattern);
    SELECT @TargetPatternMode=[PatternMode],@TargetPatternValue=[PatternValue],@TargetPatternFlags=[RegexFlags],@TargetPatternValid=[IsValid] FROM [monitor].[TVF_ParsePattern](@TargetNamePattern);
    IF @ExtendedEventSessionNames IS NOT NULL AND EXISTS(SELECT 1 FROM [monitor].[TVF_ParseSqlNameList](@ExtendedEventSessionNames) WHERE [IsValid]=0) SET @StatusCode='INVALID_PARAMETER';
    IF @EventNames IS NOT NULL AND EXISTS(SELECT 1 FROM [monitor].[TVF_ParseSqlNameList](@EventNames) WHERE [IsValid]=0) SET @StatusCode='INVALID_PARAMETER';
    IF @TargetNames IS NOT NULL AND EXISTS(SELECT 1 FROM [monitor].[TVF_ParseSqlNameList](@TargetNames) WHERE [IsValid]=0) SET @StatusCode='INVALID_PARAMETER';
    IF @SessionPatternValid=0 OR @EventPatternValid=0 OR @TargetPatternValid=0 OR (@ExtendedEventSessionNames IS NOT NULL AND @ExtendedEventSessionNamePattern IS NOT NULL) OR (@EventNames IS NOT NULL AND @EventNamePattern IS NOT NULL) OR (@TargetNames IS NOT NULL AND @TargetNamePattern IS NOT NULL) SET @StatusCode='INVALID_PARAMETER';
    IF @StatusCode='INVALID_PARAMETER' SET @ErrorMessage=N'Namensliste, Pattern oder gegenseitige Exklusivität ist ungültig.';
    IF @ExtendedEventSessionNames IS NOT NULL INSERT [#ExtendedEventsSessions_SessionNameFilter] SELECT [NameValue] FROM [monitor].[TVF_ParseSqlNameList](@ExtendedEventSessionNames) WHERE [IsValid]=1 GROUP BY [NameValue];
    IF @EventNames IS NOT NULL INSERT [#ExtendedEventsSessions_EventNameFilter] SELECT [NameValue] FROM [monitor].[TVF_ParseSqlNameList](@EventNames) WHERE [IsValid]=1 GROUP BY [NameValue];
    IF @TargetNames IS NOT NULL INSERT [#ExtendedEventsSessions_TargetNameFilter] SELECT [NameValue] FROM [monitor].[TVF_ParseSqlNameList](@TargetNames) WHERE [IsValid]=1 GROUP BY [NameValue];
    IF @StatusCode='AVAILABLE' AND (@SessionPatternMode IN('REGEX','REGEXI') OR @EventPatternMode IN('REGEX','REGEXI') OR @TargetPatternMode IN('REGEX','REGEXI')) AND (TRY_CONVERT(int,SERVERPROPERTY(N'ProductMajorVersion'))<17 OR NOT EXISTS(SELECT 1 FROM [master].[sys].[databases] [d] WITH(NOLOCK) WHERE [d].[database_id]=DB_ID() AND [d].[compatibility_level]>=170)) BEGIN SET @StatusCode='UNAVAILABLE_FEATURE';SET @ErrorMessage=N'Regex benötigt SQL Server 2025 und Compatibility Level 170.';END;

    CREATE TABLE [#ExtendedEventsSessions_Sessions]
    (
        [EventSessionId] int NOT NULL,
        [SessionName] sysname NOT NULL,
        [IsRunning] bit NOT NULL,
        [StartupState] bit NULL,
        [EventRetentionMode] nchar(1) NULL,
        [EventRetentionModeDesc] nvarchar(60) NULL,
        [MaxDispatchLatencyMilliseconds] int NULL,
        [MaxMemoryKb] int NULL,
        [MaxEventSizeKb] int NULL,
        [MemoryPartitionMode] nchar(1) NULL,
        [MemoryPartitionModeDesc] nvarchar(60) NULL,
        [TrackCausality] bit NULL,
        [RunningSince] datetime NULL,
        [PendingBuffers] int NULL,
        [TotalRegularBuffers] int NULL,
        [RegularBufferSizeBytes] bigint NULL,
        [TotalLargeBuffers] int NULL,
        [LargeBufferSizeBytes] bigint NULL,
        [TotalBufferSizeBytes] bigint NULL,
        [BufferPolicyDesc] nvarchar(256) NULL,
        [DroppedEventCount] int NULL,
        [DroppedBufferCount] int NULL,
        [BlockedEventFireTimeMilliseconds] int NULL,
        [LargestEventDroppedSizeBytes] int NULL,
        [BufferProcessedCount] bigint NULL,
        [BufferFullCount] bigint NULL,
        [TotalBytesGenerated] bigint NULL,
        [TotalTargetMemoryBytes] bigint NULL,
        [EventCount] int NULL,
        [TargetCount] int NULL,
        [ActionCount] int NULL,
        [HasRingBuffer] bit NULL,
        [HasEventFile] bit NULL
    );

    CREATE TABLE [#ExtendedEventsSessions_Events]
    (
        [SessionName] sysname NOT NULL,
        [EventId] int NOT NULL,
        [PackageName] sysname NOT NULL,
        [EventName] sysname NOT NULL,
        [Predicate] nvarchar(max) NULL
    );

    CREATE TABLE [#ExtendedEventsSessions_Actions]
    (
        [SessionName] sysname NOT NULL,
        [EventName] sysname NOT NULL,
        [ActionOrdinal] int NOT NULL,
        [PackageName] sysname NOT NULL,
        [ActionName] sysname NOT NULL
    );

    CREATE TABLE [#ExtendedEventsSessions_Targets]
    (
        [SessionName] sysname NOT NULL,
        [TargetId] int NOT NULL,
        [PackageName] sysname NOT NULL,
        [TargetName] sysname NOT NULL,
        [ConfiguredFileName] nvarchar(4000) NULL,
        [MaxFileSizeMb] bigint NULL,
        [MaxRolloverFiles] int NULL,
        [MaxMemoryKb] bigint NULL
    );

    CREATE TABLE [#ExtendedEventsSessions_Fields]
    (
        [SessionName] sysname NOT NULL,
        [ObjectType] varchar(16) NOT NULL,
        [ObjectId] int NOT NULL,
        [ObjectName] sysname NULL,
        [FieldName] sysname NOT NULL,
        [FieldValue] nvarchar(4000) NULL
    );

    IF @MaxZeilen<0 OR @ResultSetArtNormalisiert NOT IN('RAW','CONSOLE','NONE')
    BEGIN
        SET @StatusCode = 'INVALID_PARAMETER';
        SET @ErrorMessage = N'@MaxZeilen darf nicht negativ sein; NULL/0 bedeutet unbegrenzt.';
    END;

    SET LOCK_TIMEOUT 0;

    IF @StatusCode = 'AVAILABLE'
    BEGIN
        BEGIN TRY
            INSERT [#ExtendedEventsSessions_Sessions]
            (
                [EventSessionId], [SessionName], [IsRunning], [StartupState],
                [EventRetentionMode], [EventRetentionModeDesc],
                [MaxDispatchLatencyMilliseconds], [MaxMemoryKb], [MaxEventSizeKb],
                [MemoryPartitionMode], [MemoryPartitionModeDesc], [TrackCausality],
                [RunningSince], [PendingBuffers], [TotalRegularBuffers],
                [RegularBufferSizeBytes], [TotalLargeBuffers], [LargeBufferSizeBytes],
                [TotalBufferSizeBytes], [BufferPolicyDesc], [DroppedEventCount],
                [DroppedBufferCount], [BlockedEventFireTimeMilliseconds],
                [LargestEventDroppedSizeBytes], [BufferProcessedCount],
                [BufferFullCount], [TotalBytesGenerated], [TotalTargetMemoryBytes],
                [EventCount], [TargetCount], [ActionCount], [HasRingBuffer], [HasEventFile]
            )
            SELECT TOP (@EffectiveMaxZeilen)
                [s].[event_session_id],
                [s].[name],
                CONVERT(bit, CASE WHEN [r].[name] IS NULL THEN 0 ELSE 1 END),
                [s].[startup_state],
                [s].[event_retention_mode],
                [s].[event_retention_mode_desc],
                [s].[max_dispatch_latency],
                [s].[max_memory],
                [s].[max_event_size],
                [s].[memory_partition_mode],
                [s].[memory_partition_mode_desc],
                [s].[track_causality],
                CASE WHEN @MitLaufzeitstatus = 1 THEN [r].[create_time] END,
                CASE WHEN @MitLaufzeitstatus = 1 THEN [r].[pending_buffers] END,
                CASE WHEN @MitLaufzeitstatus = 1 THEN [r].[total_regular_buffers] END,
                CASE WHEN @MitLaufzeitstatus = 1 THEN [r].[regular_buffer_size] END,
                CASE WHEN @MitLaufzeitstatus = 1 THEN [r].[total_large_buffers] END,
                CASE WHEN @MitLaufzeitstatus = 1 THEN [r].[large_buffer_size] END,
                CASE WHEN @MitLaufzeitstatus = 1 THEN [r].[total_buffer_size] END,
                CASE WHEN @MitLaufzeitstatus = 1 THEN [r].[buffer_policy_desc] END,
                CASE WHEN @MitLaufzeitstatus = 1 THEN [r].[dropped_event_count] END,
                CASE WHEN @MitLaufzeitstatus = 1 THEN [r].[dropped_buffer_count] END,
                CASE WHEN @MitLaufzeitstatus = 1 THEN [r].[blocked_event_fire_time] END,
                CASE WHEN @MitLaufzeitstatus = 1 THEN [r].[largest_event_dropped_size] END,
                CASE WHEN @MitLaufzeitstatus = 1 THEN [r].[buffer_processed_count] END,
                CASE WHEN @MitLaufzeitstatus = 1 THEN [r].[buffer_full_count] END,
                CASE WHEN @MitLaufzeitstatus = 1 THEN [r].[total_bytes_generated] END,
                CAST(NULL AS bigint),
                [x].[EventCount],
                [x].[TargetCount],
                [x].[ActionCount],
                [x].[HasRingBuffer],
                [x].[HasEventFile]
            FROM [sys].[server_event_sessions] AS s WITH (NOLOCK)
            LEFT JOIN [sys].[dm_xe_sessions] AS r WITH (NOLOCK)
              ON @MitLaufzeitstatus = 1
             AND [r].[name] = [s].[name]
            OUTER APPLY
            (
                SELECT
                    (SELECT COUNT_BIG(*) FROM [sys].[server_event_session_events] AS e WITH (NOLOCK) WHERE [e].[event_session_id] = [s].[event_session_id]) AS [EventCount],
                    (SELECT COUNT_BIG(*) FROM [sys].[server_event_session_targets] AS t WITH (NOLOCK) WHERE [t].[event_session_id] = [s].[event_session_id]) AS [TargetCount],
                    (
                        SELECT COUNT_BIG(*)
                        FROM [sys].[server_event_session_actions] AS a WITH (NOLOCK)
                        WHERE [a].[event_session_id] = [s].[event_session_id]
                    ) AS [ActionCount],
                    CONVERT(bit, CASE WHEN EXISTS
                    (
                        SELECT 1 FROM [sys].[server_event_session_targets] AS t WITH (NOLOCK)
                        WHERE [t].[event_session_id] = [s].[event_session_id] AND [t].[name] = N'ring_buffer'
                    ) THEN 1 ELSE 0 END) AS [HasRingBuffer],
                    CONVERT(bit, CASE WHEN EXISTS
                    (
                        SELECT 1 FROM [sys].[server_event_session_targets] AS t WITH (NOLOCK)
                        WHERE [t].[event_session_id] = [s].[event_session_id] AND [t].[name] = N'event_file'
                    ) THEN 1 ELSE 0 END) AS [HasEventFile]
            ) AS x
            WHERE ((@ExtendedEventSessionNames IS NULL OR EXISTS(SELECT 1 FROM [#ExtendedEventsSessions_SessionNameFilter] [f] WHERE [f].[NameValue] COLLATE SQL_Latin1_General_CP1_CS_AS=[s].[name] COLLATE SQL_Latin1_General_CP1_CS_AS)) AND (@SessionPatternMode IN('NONE','REGEX','REGEXI') OR [s].[name] COLLATE SQL_Latin1_General_CP1_CS_AS LIKE @SessionPatternValue COLLATE SQL_Latin1_General_CP1_CS_AS))
              AND (@NurLaufend = 0 OR [r].[name] IS NOT NULL)
            ORDER BY [s].[name];

            IF @MitLaufzeitstatus = 1
               AND EXISTS
               (
                   SELECT 1
                   FROM [sys].[all_objects] AS [o] WITH (NOLOCK)
                   INNER JOIN [sys].[schemas] AS [sc] WITH (NOLOCK)
                       ON [sc].[schema_id]=[o].[schema_id]
                   INNER JOIN [sys].[all_columns] AS [c] WITH (NOLOCK)
                       ON [c].[object_id]=[o].[object_id]
                   WHERE [sc].[name]=N'sys'
                     AND [o].[name]=N'dm_xe_sessions'
                     AND [c].[name]=N'total_target_memory'
               )
            BEGIN
                DECLARE @TargetMemorySql nvarchar(max)=N'
UPDATE [s]
SET [TotalTargetMemoryBytes]=[r].[total_target_memory]
FROM [#ExtendedEventsSessions_Sessions] AS [s]
INNER JOIN [sys].[dm_xe_sessions] AS [r] WITH (NOLOCK)
    ON [r].[name]=[s].[SessionName];';
                EXEC [sys].[sp_executesql] @TargetMemorySql;
            END;

            SELECT @RowCount = COUNT_BIG(*) FROM [#ExtendedEventsSessions_Sessions];
        END TRY
        BEGIN CATCH
            SET @StatusCode = CASE
                                WHEN ERROR_NUMBER() IN (229, 262, 297, 300, 371) THEN 'DENIED_PERMISSION'
                                WHEN ERROR_NUMBER() = 1222 THEN 'TIMEOUT'
                                ELSE 'ERROR_HANDLED'
                              END;
            SET @ErrorNumber = ERROR_NUMBER();
            SET @ErrorMessage = ERROR_MESSAGE();
        END CATCH;
    END;

    IF @StatusCode = 'AVAILABLE' AND @MitEvents = 1
    BEGIN
        BEGIN TRY
            INSERT [#ExtendedEventsSessions_Events]([SessionName], [EventId], [PackageName], [EventName], [Predicate])
            SELECT TOP (@EffectiveMaxZeilen)
                [s].[name],
                [e].[event_id],
                [e].[package],
                [e].[name],
                [e].[predicate]
            FROM [sys].[server_event_session_events] AS e WITH (NOLOCK)
            JOIN [sys].[server_event_sessions] AS s WITH (NOLOCK)
              ON [s].[event_session_id] = [e].[event_session_id]
            WHERE ((@ExtendedEventSessionNames IS NULL OR EXISTS(SELECT 1 FROM [#ExtendedEventsSessions_SessionNameFilter] [f] WHERE [f].[NameValue] COLLATE SQL_Latin1_General_CP1_CS_AS=[s].[name] COLLATE SQL_Latin1_General_CP1_CS_AS)) AND (@SessionPatternMode IN('NONE','REGEX','REGEXI') OR [s].[name] COLLATE SQL_Latin1_General_CP1_CS_AS LIKE @SessionPatternValue COLLATE SQL_Latin1_General_CP1_CS_AS))
              AND (@NurLaufend = 0 OR EXISTS (SELECT 1 FROM [sys].[dm_xe_sessions] AS r WITH (NOLOCK) WHERE [r].[name] = [s].[name]))
            ORDER BY [s].[name], [e].[event_id];
        END TRY
        BEGIN CATCH
            SET @IsPartial = 1;
            IF @PrintMeldungen = 1
                BEGIN
    SET @MonitorPrintMessage = FORMATMESSAGE(N'WARNUNG USP_ExtendedEventsSessions Events: %s', ERROR_MESSAGE());
    RAISERROR(N'%s', 10, 1, @MonitorPrintMessage) WITH NOWAIT;
END;
        END CATCH;
    END;

    IF @StatusCode = 'AVAILABLE' AND @MitActions = 1
    BEGIN
        BEGIN TRY
            INSERT [#ExtendedEventsSessions_Actions]([SessionName], [EventName], [ActionOrdinal], [PackageName], [ActionName])
            SELECT TOP (@EffectiveMaxZeilen)
                [s].[name],
                [e].[name],
                CONVERT(int, ROW_NUMBER() OVER(PARTITION BY [s].[name],[e].[name] ORDER BY [a].[package],[a].[name])),
                [a].[package],
                [a].[name]
            FROM [sys].[server_event_session_actions] AS a WITH (NOLOCK)
            JOIN [sys].[server_event_sessions] AS s WITH (NOLOCK)
              ON [s].[event_session_id] = [a].[event_session_id]
            JOIN [sys].[server_event_session_events] AS e WITH (NOLOCK)
              ON [e].[event_session_id] = [a].[event_session_id]
             AND [e].[event_id] = [a].[event_id]
            WHERE ((@ExtendedEventSessionNames IS NULL OR EXISTS(SELECT 1 FROM [#ExtendedEventsSessions_SessionNameFilter] [f] WHERE [f].[NameValue] COLLATE SQL_Latin1_General_CP1_CS_AS=[s].[name] COLLATE SQL_Latin1_General_CP1_CS_AS)) AND (@SessionPatternMode IN('NONE','REGEX','REGEXI') OR [s].[name] COLLATE SQL_Latin1_General_CP1_CS_AS LIKE @SessionPatternValue COLLATE SQL_Latin1_General_CP1_CS_AS))
              AND (@NurLaufend = 0 OR EXISTS (SELECT 1 FROM [sys].[dm_xe_sessions] AS r WITH (NOLOCK) WHERE [r].[name] = [s].[name]))
            ORDER BY [s].[name], [e].[name], [a].[package], [a].[name];
        END TRY
        BEGIN CATCH
            SET @IsPartial = 1;
            IF @PrintMeldungen = 1
                BEGIN
    SET @MonitorPrintMessage = FORMATMESSAGE(N'WARNUNG USP_ExtendedEventsSessions Actions: %s', ERROR_MESSAGE());
    RAISERROR(N'%s', 10, 1, @MonitorPrintMessage) WITH NOWAIT;
END;
        END CATCH;
    END;

    IF @StatusCode = 'AVAILABLE' AND @MitTargets = 1
    BEGIN
        BEGIN TRY
            INSERT [#ExtendedEventsSessions_Targets]
            (
                [SessionName], [TargetId], [PackageName], [TargetName],
                [ConfiguredFileName], [MaxFileSizeMb], [MaxRolloverFiles], [MaxMemoryKb]
            )
            SELECT TOP (@EffectiveMaxZeilen)
                [s].[name],
                [t].[target_id],
                [t].[package],
                [t].[name],
                MAX(CASE WHEN [f].[name] = N'filename' THEN CONVERT(nvarchar(4000), [f].[value]) END),
                MAX(CASE WHEN [f].[name] = N'max_file_size' THEN TRY_CONVERT([bigint], [f].[value]) END),
                MAX(CASE WHEN [f].[name] = N'max_rollover_files' THEN TRY_CONVERT([int], [f].[value]) END),
                MAX(CASE WHEN [f].[name] = N'max_memory' THEN TRY_CONVERT([bigint], [f].[value]) END)
            FROM [sys].[server_event_session_targets] AS t WITH (NOLOCK)
            JOIN [sys].[server_event_sessions] AS s WITH (NOLOCK)
              ON [s].[event_session_id] = [t].[event_session_id]
            LEFT JOIN [sys].[server_event_session_fields] AS f WITH (NOLOCK)
              ON [f].[event_session_id] = [t].[event_session_id]
             AND [f].[object_id] = [t].[target_id]
            WHERE ((@ExtendedEventSessionNames IS NULL OR EXISTS(SELECT 1 FROM [#ExtendedEventsSessions_SessionNameFilter] [f] WHERE [f].[NameValue] COLLATE SQL_Latin1_General_CP1_CS_AS=[s].[name] COLLATE SQL_Latin1_General_CP1_CS_AS)) AND (@SessionPatternMode IN('NONE','REGEX','REGEXI') OR [s].[name] COLLATE SQL_Latin1_General_CP1_CS_AS LIKE @SessionPatternValue COLLATE SQL_Latin1_General_CP1_CS_AS))
              AND (@NurLaufend = 0 OR EXISTS (SELECT 1 FROM [sys].[dm_xe_sessions] AS r WITH (NOLOCK) WHERE [r].[name] = [s].[name]))
            GROUP BY [s].[name], [t].[target_id], [t].[package], [t].[name]
            ORDER BY [s].[name], [t].[target_id];
        END TRY
        BEGIN CATCH
            SET @IsPartial = 1;
            IF @PrintMeldungen = 1
                BEGIN
    SET @MonitorPrintMessage = FORMATMESSAGE(N'WARNUNG USP_ExtendedEventsSessions Targets: %s', ERROR_MESSAGE());
    RAISERROR(N'%s', 10, 1, @MonitorPrintMessage) WITH NOWAIT;
END;
        END CATCH;
    END;

    IF @StatusCode = 'AVAILABLE' AND @MitFeldern = 1
    BEGIN
        BEGIN TRY
            INSERT [#ExtendedEventsSessions_Fields]([SessionName], [ObjectType], [ObjectId], [ObjectName], [FieldName], [FieldValue])
            SELECT TOP (@EffectiveMaxZeilen)
                [s].[name],
                CASE WHEN [e].[event_id] IS NOT NULL THEN 'EVENT'
                     WHEN [t].[target_id] IS NOT NULL THEN 'TARGET'
                     ELSE 'UNKNOWN' END AS [ObjectType],
                [f].[object_id],
                COALESCE([e].[name], [t].[name]),
                [f].[name],
                CONVERT(nvarchar(4000), [f].[value])
            FROM [sys].[server_event_session_fields] AS f WITH (NOLOCK)
            JOIN [sys].[server_event_sessions] AS s WITH (NOLOCK)
              ON [s].[event_session_id] = [f].[event_session_id]
            LEFT JOIN [sys].[server_event_session_events] AS e WITH (NOLOCK)
              ON [e].[event_session_id] = [f].[event_session_id]
             AND [e].[event_id] = [f].[object_id]
            LEFT JOIN [sys].[server_event_session_targets] AS t WITH (NOLOCK)
              ON [t].[event_session_id] = [f].[event_session_id]
             AND [t].[target_id] = [f].[object_id]
            WHERE ((@ExtendedEventSessionNames IS NULL OR EXISTS(SELECT 1 FROM [#ExtendedEventsSessions_SessionNameFilter] [f] WHERE [f].[NameValue] COLLATE SQL_Latin1_General_CP1_CS_AS=[s].[name] COLLATE SQL_Latin1_General_CP1_CS_AS)) AND (@SessionPatternMode IN('NONE','REGEX','REGEXI') OR [s].[name] COLLATE SQL_Latin1_General_CP1_CS_AS LIKE @SessionPatternValue COLLATE SQL_Latin1_General_CP1_CS_AS))
              AND (@NurLaufend = 0 OR EXISTS (SELECT 1 FROM [sys].[dm_xe_sessions] AS r WITH (NOLOCK) WHERE [r].[name] = [s].[name]))
            ORDER BY
                [s].[name],
                CASE WHEN [e].[event_id] IS NOT NULL THEN 1
                     WHEN [t].[target_id] IS NOT NULL THEN 2
                     ELSE 3 END,
                [f].[object_id],
                [f].[name];
        END TRY
        BEGIN CATCH
            SET @IsPartial = 1;
            IF @PrintMeldungen = 1
                BEGIN
    SET @MonitorPrintMessage = FORMATMESSAGE(N'WARNUNG USP_ExtendedEventsSessions Felder: %s', ERROR_MESSAGE());
    RAISERROR(N'%s', 10, 1, @MonitorPrintMessage) WITH NOWAIT;
END;
        END CATCH;
    END;



    IF @StatusCode IN('AVAILABLE','AVAILABLE_LIMITED')
    BEGIN
        IF @EventNames IS NOT NULL
        BEGIN
            DELETE [e] FROM [#ExtendedEventsSessions_Events] [e] WHERE NOT EXISTS(SELECT 1 FROM [#ExtendedEventsSessions_EventNameFilter] [f] WHERE [f].[NameValue] COLLATE SQL_Latin1_General_CP1_CS_AS=[e].[EventName] COLLATE SQL_Latin1_General_CP1_CS_AS);
            DELETE [a] FROM [#ExtendedEventsSessions_Actions] [a] WHERE NOT EXISTS(SELECT 1 FROM [#ExtendedEventsSessions_EventNameFilter] [f] WHERE [f].[NameValue] COLLATE SQL_Latin1_General_CP1_CS_AS=[a].[EventName] COLLATE SQL_Latin1_General_CP1_CS_AS);
        END;
        IF @EventPatternMode='LIKE'
        BEGIN DELETE FROM [#ExtendedEventsSessions_Events] WHERE [EventName] COLLATE SQL_Latin1_General_CP1_CS_AS NOT LIKE @EventPatternValue COLLATE SQL_Latin1_General_CP1_CS_AS;DELETE FROM [#ExtendedEventsSessions_Actions] WHERE [EventName] COLLATE SQL_Latin1_General_CP1_CS_AS NOT LIKE @EventPatternValue COLLATE SQL_Latin1_General_CP1_CS_AS;END;
        IF @TargetNames IS NOT NULL DELETE [x] FROM [#ExtendedEventsSessions_Targets] [x] WHERE NOT EXISTS(SELECT 1 FROM [#ExtendedEventsSessions_TargetNameFilter] [f] WHERE [f].[NameValue] COLLATE SQL_Latin1_General_CP1_CS_AS=[x].[TargetName] COLLATE SQL_Latin1_General_CP1_CS_AS);
        IF @TargetPatternMode='LIKE' DELETE FROM [#ExtendedEventsSessions_Targets] WHERE [TargetName] COLLATE SQL_Latin1_General_CP1_CS_AS NOT LIKE @TargetPatternValue COLLATE SQL_Latin1_General_CP1_CS_AS;
        IF @SessionPatternMode IN('REGEX','REGEXI') OR @EventPatternMode IN('REGEX','REGEXI') OR @TargetPatternMode IN('REGEX','REGEXI')
        BEGIN
            DECLARE @FilterSql nvarchar(max)=N'';
            IF @SessionPatternMode IN('REGEX','REGEXI') SET @FilterSql+=N'DELETE FROM [#ExtendedEventsSessions_Fields] WHERE NOT REGEXP_LIKE([SessionName],@SP,@SF);DELETE FROM [#ExtendedEventsSessions_Targets] WHERE NOT REGEXP_LIKE([SessionName],@SP,@SF);DELETE FROM [#ExtendedEventsSessions_Actions] WHERE NOT REGEXP_LIKE([SessionName],@SP,@SF);DELETE FROM [#ExtendedEventsSessions_Events] WHERE NOT REGEXP_LIKE([SessionName],@SP,@SF);DELETE FROM [#ExtendedEventsSessions_Sessions] WHERE NOT REGEXP_LIKE([SessionName],@SP,@SF);';
            IF @EventPatternMode IN('REGEX','REGEXI') SET @FilterSql+=N'DELETE FROM [#ExtendedEventsSessions_Events] WHERE NOT REGEXP_LIKE([EventName],@EP,@EF);DELETE FROM [#ExtendedEventsSessions_Actions] WHERE NOT REGEXP_LIKE([EventName],@EP,@EF);';
            IF @TargetPatternMode IN('REGEX','REGEXI') SET @FilterSql+=N'DELETE FROM [#ExtendedEventsSessions_Targets] WHERE NOT REGEXP_LIKE([TargetName],@TP,@TF);';
            EXEC [sys].[sp_executesql] @FilterSql,N'@SP nvarchar(4000),@SF varchar(8),@EP nvarchar(4000),@EF varchar(8),@TP nvarchar(4000),@TF varchar(8)',@SP=@SessionPatternValue,@SF=@SessionPatternFlags,@EP=@EventPatternValue,@EF=@EventPatternFlags,@TP=@TargetPatternValue,@TF=@TargetPatternFlags;
        END;
        SELECT @RowCount=COUNT_BIG(*) FROM [#ExtendedEventsSessions_Sessions];
    END;

    IF @StatusCode = 'AVAILABLE' AND @IsPartial = 1
        SET @StatusCode = 'AVAILABLE_LIMITED';

    IF @PrintMeldungen = 1 AND @StatusCode NOT IN ('AVAILABLE', 'AVAILABLE_LIMITED')
        BEGIN
    SET @MonitorPrintMessage = FORMATMESSAGE(N'WARNUNG USP_ExtendedEventsSessions: %s - %s', @StatusCode, COALESCE(@ErrorMessage, N'Keine Details.'));
    RAISERROR(N'%s', 10, 1, @MonitorPrintMessage) WITH NOWAIT;
END;

    IF @ResultSetArtNormalisiert<>'NONE'
    BEGIN
        SELECT N'USP_ExtendedEventsSessions' AS [ModuleName],@CollectionTimeUtc AS [CollectionTimeUtc],@StatusCode AS [StatusCode],@IsPartial AS [IsPartial],@RowCount AS [RowCount],CASE WHEN TRY_CONVERT(int,SERVERPROPERTY(N'ProductMajorVersion'))>=16 THEN N'VIEW SERVER PERFORMANCE STATE' ELSE N'VIEW SERVER STATE' END AS [RequiredPermission],@ErrorNumber AS [ErrorNumber],@ErrorMessage AS [ErrorMessage],N'Nur Inventarisierung; keine Extended-Events-DDL und keine Targetdaten.' AS [Detail];
        IF @ResultSetArtNormalisiert='RAW'
        BEGIN SELECT * FROM [#ExtendedEventsSessions_Sessions] ORDER BY [SessionName];SELECT * FROM [#ExtendedEventsSessions_Events] ORDER BY [SessionName],[EventId];SELECT * FROM [#ExtendedEventsSessions_Actions] ORDER BY [SessionName],[EventName],[ActionOrdinal];SELECT * FROM [#ExtendedEventsSessions_Targets] ORDER BY [SessionName],[TargetId];SELECT * FROM [#ExtendedEventsSessions_Fields] ORDER BY [SessionName],[ObjectType],[ObjectId],[FieldName];END
        ELSE
        BEGIN SELECT N'Extended-Events Session' [Ergebnis],[SessionName] [Session],[IsRunning] [läuft],[StartupState] [Autostart],CONCAT(CONVERT(varchar(40),CONVERT(decimal(19,2),[MaxMemoryKb]/1024.0)),N' MB') [max. Speicher],[EventCount] [Events],[TargetCount] [Targets],[DroppedEventCount] [verworfene Events],[SessionName] [Session Details],[BufferPolicyDesc] [Buffer Policy] FROM [#ExtendedEventsSessions_Sessions] ORDER BY [SessionName];SELECT N'Extended-Events Event' [Ergebnis],[SessionName] [Session],[EventName] [Event],[PackageName] [Package],[Predicate] [Prädikat] FROM [#ExtendedEventsSessions_Events] ORDER BY [SessionName],[EventId];SELECT N'Extended-Events Action' [Ergebnis],[SessionName] [Session],[EventName] [Event],[ActionName] [Action],[PackageName] [Package] FROM [#ExtendedEventsSessions_Actions] ORDER BY [SessionName],[EventName],[ActionOrdinal];SELECT N'Extended-Events Target' [Ergebnis],[SessionName] [Session],[TargetName] [Target],[ConfiguredFileName] [Datei],[MaxFileSizeMb] [max. Datei MB],[MaxRolloverFiles] [Rollover-Dateien] FROM [#ExtendedEventsSessions_Targets] ORDER BY [SessionName],[TargetId];SELECT N'Extended-Events Feld' [Ergebnis],[SessionName] [Session],[ObjectType] [Objekttyp],[ObjectName] [Objekt],[FieldName] [Feld],[FieldValue] [Wert] FROM [#ExtendedEventsSessions_Fields] ORDER BY [SessionName],[ObjectType],[ObjectId],[FieldName];END;
    END;
    IF @JsonErzeugen=1
    BEGIN
        DECLARE @Meta nvarchar(max)=(SELECT N'ExtendedEventsSessions' [resultName],1 [schemaVersion],@CollectionTimeUtc [generatedAtUtc],@StatusCode [statusCode],@IsPartial [isPartial],@RowCount [sessionCount],@ErrorNumber [errorNumber],@ErrorMessage [errorMessage] FOR JSON PATH,WITHOUT_ARRAY_WRAPPER,INCLUDE_NULL_VALUES),@SessionsJson nvarchar(max)=(SELECT * FROM [#ExtendedEventsSessions_Sessions] ORDER BY [SessionName] FOR JSON PATH,INCLUDE_NULL_VALUES),@EventsJson nvarchar(max)=(SELECT * FROM [#ExtendedEventsSessions_Events] ORDER BY [SessionName],[EventId] FOR JSON PATH,INCLUDE_NULL_VALUES),@ActionsJson nvarchar(max)=(SELECT * FROM [#ExtendedEventsSessions_Actions] ORDER BY [SessionName],[EventName],[ActionOrdinal] FOR JSON PATH,INCLUDE_NULL_VALUES),@TargetsJson nvarchar(max)=(SELECT * FROM [#ExtendedEventsSessions_Targets] ORDER BY [SessionName],[TargetId] FOR JSON PATH,INCLUDE_NULL_VALUES),@FieldsJson nvarchar(max)=(SELECT * FROM [#ExtendedEventsSessions_Fields] ORDER BY [SessionName],[ObjectType],[ObjectId],[FieldName] FOR JSON PATH,INCLUDE_NULL_VALUES);
        SET @Json=CONCAT(N'{"meta":',COALESCE(@Meta,N'{}'),N',"sessions":',COALESCE(@SessionsJson,N'[]'),N',"events":',COALESCE(@EventsJson,N'[]'),N',"actions":',COALESCE(@ActionsJson,N'[]'),N',"targets":',COALESCE(@TargetsJson,N'[]'),N',"fields":',COALESCE(@FieldsJson,N'[]'),N',"warnings":[]}');
    END;
    IF @ConsoleResultRequested = 1
    BEGIN
        EXEC [monitor].[InternalEmitConsoleResult]
              @SourceTable=N'#ExtendedEventsSessions_Sessions'
            , @ResultLabel=N'ExtendedEventsSessions'
            , @EmptyMessage=N'Keine fachlichen Ergebnisse';
    END;
    IF @TableResultRequested = 1
    BEGIN
        EXEC [monitor].[InternalWriteResultTable]
              @SourceTable = N'#ExtendedEventsSessions_Sessions'
            , @TargetTable=@TableTarget
            , @ThrowOnError = 1;
    END;
END;
GO
-- END SOURCE: Code/06_ExtendedEvents/010_USP_ExtendedEventsSessions.sql

-- BEGIN SOURCE: Code/06_ExtendedEvents/020_USP_ExtendedEventsReadEvents.sql
SET QUOTED_IDENTIFIER ON;
GO

/*
===============================================================================
Objekt       : monitor.USP_ExtendedEventsReadEvents
Version      : 2.0.0
Stand        : 2026-07-15
Typ          : Stored Procedure
Zweck        : Liest Ereignisse aus einem bereits vorhandenen event_file- oder
               ring_buffer-Target. Die Procedure ist eine optionale Forensik-
               quelle und wird von keinem Standard-Current-State-Modul benötigt.
SQL-Version  : SQL Server 2019 oder neuer.
Datenquellen : sys.server_event_sessions/-targets/-fields,
               sys.fn_xe_file_target_read_file, optional sys.dm_xe_session_targets.
Parameter    : @ResolvedSourceExtendedEventSessionName, @Quelle, @FilePath, @EventNamePattern, @VonUtc,
               @BisUtc, @MaxZeilen, @MitEventXml, @BestaetigeTargetFlush,
               @PrintMeldungen, @Hilfe.
Resultsets   : 1. Modulstatus. 2. normalisierte Events. 3. Quell-/Fehlerstatus.
Berechtigung : SQL 2019 VIEW SERVER STATE; SQL 2022+ VIEW SERVER PERFORMANCE
               STATE beziehungsweise für Filezugriff ggf. VIEW DATABASE
               PERFORMANCE STATE. Zusätzlich muss SQL Server die Datei lesen können.
Eigenlast    : Abhängig von Anzahl und Größe der XEL-Dateien bzw. Ringbufferdaten.
               File-Lesen und XML-Konvertierung sind explizit Deep/opt-in.
Locking      : LOCK_TIMEOUT 0; keine Benutzerobjekte und keine Änderungen.
Nebenwirkung : Das Lesen von sys.dm_xe_session_targets kann einen Target-Flush
               auslösen und erfordert daher @BestaetigeTargetFlush=1.
Partial      : Fehlende Sessions, Targets, Dateien oder Rechte werden strukturiert
               gemeldet; andere Framework-Module bleiben funktionsfähig.
Beispiele    : EXEC monitor.USP_ExtendedEventsReadEvents
                   @ResolvedSourceExtendedEventSessionName=N'system_health', @Quelle='EVENT_FILE',
                   @EventNamePattern=N'xml_deadlock_report', @MaxZeilen=100;
               EXEC monitor.USP_ExtendedEventsReadEvents
                   @ResolvedSourceExtendedEventSessionName=N'system_health', @Quelle='RING_BUFFER',
                   @BestaetigeTargetFlush=1;
               EXEC monitor.USP_ExtendedEventsReadEvents @Hilfe=1;
Änderungen   : 1.0.0 - Erstfassung Phase 5.
===============================================================================
*/
CREATE OR ALTER PROCEDURE [monitor].[USP_ExtendedEventsReadEvents]
      @SourceExtendedEventSessionName nvarchar(258)         = N'system_health'
    , @Quelle                  varchar(20)     = 'EVENT_FILE'
    , @FilePath                nvarchar(4000)  = NULL
    , @EventNames              nvarchar(max)   = NULL
    , @EventNamePattern        nvarchar(4000)  = NULL
    , @VonUtc                  datetime2(7)    = NULL
    , @BisUtc                  datetime2(7)    = NULL
    , @MaxZeilen               int             = 1000
    , @MitEventXml             bit             = 1
    , @BestaetigeTargetFlush   bit             = 0
    , @HighImpactConfirmed     bit             = 0
    , @ResultSetArt                   varchar(16)    = 'CONSOLE'
    , @ResultTablesJson               nvarchar(max) = NULL
    , @JsonErzeugen                   bit            = 0
    , @Json                            nvarchar(max)  = NULL OUTPUT
    , @PrintMeldungen          bit             = 1
    , @Hilfe                   bit             = 0
AS
BEGIN
    SET NOCOUNT ON;
    SET @Json=NULL;
    DECLARE @ResultSetArtNormalisiert varchar(16)=UPPER(LTRIM(RTRIM(COALESCE(@ResultSetArt,''))));
    DECLARE @TableResultRequested bit = CASE WHEN @ResultSetArtNormalisiert = 'TABLE' THEN 1 ELSE 0 END;
    DECLARE @ConsoleResultRequested bit = CASE WHEN @ResultSetArtNormalisiert = 'CONSOLE' THEN 1 ELSE 0 END;
    DECLARE @TableTarget sysname=NULL;
    IF @TableResultRequested=0 AND NULLIF(LTRIM(RTRIM(COALESCE(@ResultTablesJson,N''))),N'') IS NOT NULL THROW 51011,N'@ResultTablesJson ist ausschließlich mit @ResultSetArt=TABLE zulässig.',1;
    IF @TableResultRequested=1 EXEC [monitor].[InternalPrepareSingleResultTable] @ResultTablesJson=@ResultTablesJson,@ResultName=N'events',@TargetTable=@TableTarget OUTPUT,@ThrowOnError=1;
    IF @TableResultRequested = 1 OR @ConsoleResultRequested = 1 SET @ResultSetArtNormalisiert = 'NONE';
    DECLARE @ResolvedSourceExtendedEventSessionName sysname=NULL;
    DECLARE @EventPatternMode varchar(8),@EventPatternValue nvarchar(4000),@EventPatternFlags varchar(8),@EventPatternValid bit;
    DECLARE @EffectiveMaxZeilen bigint = CASE WHEN @MaxZeilen IS NULL OR @MaxZeilen=0 THEN CONVERT(bigint,9223372036854775807) ELSE CONVERT(bigint,@MaxZeilen) END;
    DECLARE @MonitorPrintMessage nvarchar(2048);

    IF @Hilfe = 1
    BEGIN
        PRINT N'monitor.USP_ExtendedEventsReadEvents';
        PRINT N'@ResolvedSourceExtendedEventSessionName sysname=N''system_health'': vorhandene serverweite Extended-Events-Session.';
        PRINT N'@Quelle varchar(20)=''EVENT_FILE'': EVENT_FILE, RING_BUFFER oder AUTO. AUTO bevorzugt EVENT_FILE.';
        PRINT N'@FilePath nvarchar(4000)=NULL: optionaler XEL-Pfad oder URL; NULL leitet den event_file-Pfad aus der Sessiondefinition ab.';
        PRINT N'@EventNamePattern nvarchar(256)=NULL: LIKE-Filter auf den Eventnamen.';
        PRINT N'@VonUtc datetime2(7)=NULL; @BisUtc datetime2(7)=NULL: UTC-Zeitfenster.';
        PRINT N'@MaxZeilen int=1000: positive Werte begrenzen; NULL/0 = unbegrenzt.';
        PRINT N'@MitEventXml bit=1: 1 gibt das vollständige Event-XML aus; 0 reduziert Ergebnistransfer.';
        PRINT N'@BestaetigeTargetFlush bit=0: muss für RING_BUFFER 1 sein, da sys.dm_xe_session_targets einen Flush auslösen kann.';
        PRINT N'@PrintMeldungen bit=1: Warnungen via RAISERROR Severity 10; @Hilfe bit=0: 1 zeigt diese Hilfe.';
        PRINT N'Die Procedure verändert keine Extended-Events-Session und ist kein Bestandteil des Standardlaufs.';
        RETURN;
    END;

    IF @SourceExtendedEventSessionName IS NULL OR (SELECT COUNT_BIG(*) FROM [monitor].[TVF_ParseSqlNameList](@SourceExtendedEventSessionName) WHERE [IsValid]=1)<>1 OR EXISTS(SELECT 1 FROM [monitor].[TVF_ParseSqlNameList](@SourceExtendedEventSessionName) WHERE [IsValid]=0)
    BEGIN SET @ResolvedSourceExtendedEventSessionName=NULL;END
    ELSE SELECT @ResolvedSourceExtendedEventSessionName=MIN([NameValue]) FROM [monitor].[TVF_ParseSqlNameList](@SourceExtendedEventSessionName) WHERE [IsValid]=1;

    SELECT @EventPatternMode=[PatternMode],@EventPatternValue=[PatternValue],@EventPatternFlags=[RegexFlags],@EventPatternValid=[IsValid] FROM [monitor].[TVF_ParsePattern](@EventNamePattern);
    IF @EventNames IS NOT NULL AND EXISTS(SELECT 1 FROM [monitor].[TVF_ParseSqlNameList](@EventNames) WHERE [IsValid]=0) SET @EventPatternValid=0;

    DECLARE
        @CollectionTimeUtc datetime2(3) = SYSUTCDATETIME(),
        @StatusCode varchar(40) = 'AVAILABLE',
        @IsPartial bit = 0,
        @ErrorNumber int = NULL,
        @ErrorMessage nvarchar(2048) = NULL,
        @RowCount bigint = 0,
        @Allowed bit = 1,
        @ResolvedSource varchar(20) = UPPER(LTRIM(RTRIM(COALESCE(@Quelle, '')))),
        @ResolvedFilePath nvarchar(4000) = NULL,
        @ConfiguredFilePath nvarchar(4000) = NULL,
        @TargetData xml = NULL;

    CREATE TABLE [#ExtendedEventsReadEvents_Raw]
    (
        [SourceType] varchar(20) NOT NULL,
        [EventName] sysname NULL,
        [TimestampUtc] datetime2(7) NULL,
        [FileName] nvarchar(260) NULL,
        [FileOffset] bigint NULL,
        [EventXml] xml NULL
    );

    CREATE TABLE [#ExtendedEventsReadEvents_SourceStatus]
    (
        [SourceType] varchar(20) NULL,
        [SessionName] sysname NULL,
        [TargetName] sysname NULL,
        [ResolvedPath] nvarchar(4000) NULL,
        [StatusCode] varchar(40) NOT NULL,
        [ErrorNumber] int NULL,
        [ErrorMessage] nvarchar(2048) NULL,
        [Detail] nvarchar(1000) NULL
    );

    IF @ResolvedSourceExtendedEventSessionName IS NULL BEGIN SET @StatusCode='INVALID_PARAMETER';SET @ErrorMessage=N'@SourceExtendedEventSessionName muss genau einen gültigen, optional geklammerten sysname enthalten.';END;

    IF @ResolvedSource NOT IN ('EVENT_FILE', 'RING_BUFFER', 'AUTO')
    BEGIN
        SET @StatusCode = 'INVALID_PARAMETER';
        SET @ErrorMessage = N'@Quelle muss EVENT_FILE, RING_BUFFER oder AUTO sein.';
    END;

    IF @MaxZeilen<0 OR @ResultSetArtNormalisiert NOT IN('RAW','CONSOLE','NONE')
    BEGIN
        SET @StatusCode = 'INVALID_PARAMETER';
        SET @ErrorMessage = N'@MaxZeilen darf nicht negativ sein; NULL/0 bedeutet unbegrenzt.';
    END;

    IF @VonUtc IS NOT NULL AND @BisUtc IS NOT NULL AND @VonUtc >= @BisUtc
    BEGIN
        SET @StatusCode = 'INVALID_PARAMETER';
        SET @ErrorMessage = N'@VonUtc muss kleiner als @BisUtc sein.';
    END;

    IF @StatusCode = 'AVAILABLE'
        EXEC [monitor].[InternalCheckAnalysisPath] @AnalysisClass='EXTENDED_EVENTS_FORENSICS_DEEP',@HighImpactConfirmed=@HighImpactConfirmed,@StatusCode=@StatusCode OUTPUT,@ErrorMessage=@ErrorMessage OUTPUT;

    SET LOCK_TIMEOUT 0;

    IF @StatusCode = 'AVAILABLE'
    BEGIN
        BEGIN TRY
            SELECT @ConfiguredFilePath = MAX(CONVERT(nvarchar(4000), [f].[value]))
            FROM [sys].[server_event_sessions] AS s WITH (NOLOCK)
            JOIN [sys].[server_event_session_targets] AS t WITH (NOLOCK)
              ON [t].[event_session_id] = [s].[event_session_id]
             AND [t].[name] = N'event_file'
            LEFT JOIN [sys].[server_event_session_fields] AS f WITH (NOLOCK)
              ON [f].[event_session_id] = [t].[event_session_id]
             AND [f].[object_id] = [t].[target_id]
             AND [f].[name] = N'filename'
            WHERE [s].[name] = @ResolvedSourceExtendedEventSessionName;
        END TRY
        BEGIN CATCH
            SET @IsPartial = 1;
            INSERT [#ExtendedEventsReadEvents_SourceStatus] VALUES
            ('CATALOG', @ResolvedSourceExtendedEventSessionName, 'event_file', NULL,
             CASE WHEN ERROR_NUMBER() IN (229,262,297,300,371) THEN 'DENIED_PERMISSION' ELSE 'ERROR_HANDLED' END,
             ERROR_NUMBER(), ERROR_MESSAGE(), N'Der konfigurierte event_file-Pfad konnte nicht gelesen werden. Ein expliziter @FilePath kann weiterhin funktionieren.');
        END CATCH;

        IF @ResolvedSource = 'AUTO'
        BEGIN
            IF @FilePath IS NOT NULL OR @ConfiguredFilePath IS NOT NULL
                SET @ResolvedSource = 'EVENT_FILE';
            ELSE IF @BestaetigeTargetFlush = 1
                SET @ResolvedSource = 'RING_BUFFER';
            ELSE
            BEGIN
                SET @StatusCode = 'AVAILABLE_DISABLED';
                SET @ErrorMessage = N'AUTO fand keinen lesbaren event_file-Pfad; Ringbuffer wurde ohne @BestaetigeTargetFlush=1 nicht gelesen.';
            END;
        END;
    END;

    IF @StatusCode = 'AVAILABLE' AND @ResolvedSource = 'EVENT_FILE'
    BEGIN
        SET @ResolvedFilePath = COALESCE(NULLIF(@FilePath, N''), NULLIF(@ConfiguredFilePath, N''));

        IF @ResolvedFilePath IS NULL
        BEGIN
            SET @StatusCode = 'UNAVAILABLE_OBJECT';
            SET @ErrorMessage = N'Kein event_file-Pfad vorhanden. @FilePath angeben oder eine Session mit event_file-Target verwenden.';
            INSERT [#ExtendedEventsReadEvents_SourceStatus] VALUES('EVENT_FILE', @ResolvedSourceExtendedEventSessionName, 'event_file', NULL, @StatusCode, NULL, @ErrorMessage, N'Keine Datei gelesen.');
        END
        ELSE
        BEGIN
            IF (RIGHT(LOWER(@ResolvedFilePath), 4) = N'.xel')
                SET @ResolvedFilePath = LEFT(@ResolvedFilePath, LEN(@ResolvedFilePath) - 4) + N'*.xel';
            ELSE IF CHARINDEX(N'*', @ResolvedFilePath) = 0
                SET @ResolvedFilePath = @ResolvedFilePath + N'*.xel';

            BEGIN TRY
                INSERT [#ExtendedEventsReadEvents_Raw]([SourceType], [EventName], [TimestampUtc], [FileName], [FileOffset], [EventXml])
                SELECT TOP (@EffectiveMaxZeilen)
                    'EVENT_FILE',
                    [r].[object_name],
                    [r].[timestamp_utc],
                    [r].[file_name],
                    [r].[file_offset],
                    CONVERT([xml], [r].[event_data])
                FROM sys.fn_xe_file_target_read_file(@ResolvedFilePath, NULL, NULL, NULL) AS r
                WHERE ((@EventNames IS NULL OR EXISTS(SELECT 1 FROM [monitor].[TVF_ParseSqlNameList](@EventNames) [ef] WHERE [ef].[IsValid]=1 AND [ef].[NameValue] COLLATE SQL_Latin1_General_CP1_CS_AS=[r].[object_name] COLLATE SQL_Latin1_General_CP1_CS_AS)) AND (@EventPatternMode IN('NONE','REGEX','REGEXI') OR [r].[object_name] COLLATE SQL_Latin1_General_CP1_CS_AS LIKE @EventPatternValue COLLATE SQL_Latin1_General_CP1_CS_AS))
                  AND (@VonUtc IS NULL OR [r].[timestamp_utc] >= @VonUtc)
                  AND (@BisUtc IS NULL OR [r].[timestamp_utc] < @BisUtc)
                ORDER BY [r].[timestamp_utc] DESC, [r].[file_name] DESC, [r].[file_offset] DESC;

                INSERT [#ExtendedEventsReadEvents_SourceStatus] VALUES
                ('EVENT_FILE', @ResolvedSourceExtendedEventSessionName, 'event_file', @ResolvedFilePath, 'AVAILABLE', NULL, NULL,
                 N'XEL-Dateien wurden gelesen. Große oder viele Rollover-Dateien können trotz Ergebnislimit vollständig gescannt werden.');
            END TRY
            BEGIN CATCH
                SET @StatusCode = CASE
                                    WHEN ERROR_NUMBER() IN (229,262,297,300,371) THEN 'DENIED_PERMISSION'
                                    WHEN ERROR_NUMBER() = 1222 THEN 'TIMEOUT'
                                    WHEN ERROR_NUMBER() IN(6335,6336,6337) THEN 'XML_UNAVAILABLE_LIMIT'
                                    WHEN ERROR_NUMBER() BETWEEN 9400 AND 9431 THEN 'XML_INVALID'
                                    ELSE 'ERROR_HANDLED'
                                  END;
                SET @ErrorNumber = ERROR_NUMBER();
                SET @ErrorMessage = ERROR_MESSAGE();
                INSERT [#ExtendedEventsReadEvents_SourceStatus] VALUES('EVENT_FILE', @ResolvedSourceExtendedEventSessionName, 'event_file', @ResolvedFilePath, @StatusCode, @ErrorNumber, @ErrorMessage, N'Event-Datei konnte nicht gelesen werden.');
            END CATCH;
        END;
    END;

    IF @StatusCode = 'AVAILABLE' AND @ResolvedSource = 'RING_BUFFER'
    BEGIN
        IF @BestaetigeTargetFlush = 0
        BEGIN
            SET @StatusCode = 'AVAILABLE_DISABLED';
            SET @ErrorMessage = N'RING_BUFFER erfordert @BestaetigeTargetFlush=1.';
            INSERT [#ExtendedEventsReadEvents_SourceStatus] VALUES('RING_BUFFER', @ResolvedSourceExtendedEventSessionName, 'ring_buffer', NULL, @StatusCode, NULL, @ErrorMessage, N'sys.dm_xe_session_targets wurde nicht gelesen.');
        END
        ELSE
        BEGIN
            BEGIN TRY
                SELECT @TargetData = CONVERT([xml], [t].[target_data])
                FROM [sys].[dm_xe_session_targets] AS t WITH (NOLOCK)
                JOIN [sys].[dm_xe_sessions] AS s WITH (NOLOCK)
                  ON [s].[address] = [t].[event_session_address]
                WHERE [s].[name] = @ResolvedSourceExtendedEventSessionName
                  AND [t].[target_name] = N'ring_buffer';

                IF @TargetData IS NULL
                BEGIN
                    SET @StatusCode = 'UNAVAILABLE_OBJECT';
                    SET @ErrorMessage = N'Kein laufendes ring_buffer-Target mit lesbaren Targetdaten gefunden.';
                    INSERT [#ExtendedEventsReadEvents_SourceStatus] VALUES('RING_BUFFER', @ResolvedSourceExtendedEventSessionName, 'ring_buffer', NULL, @StatusCode, NULL, @ErrorMessage, N'Die Session ist möglicherweise gestoppt oder besitzt kein Ringbuffer-Target.');
                END
                ELSE
                BEGIN
                    INSERT [#ExtendedEventsReadEvents_Raw]([SourceType], [EventName], [TimestampUtc], [FileName], [FileOffset], [EventXml])
                    SELECT TOP (@EffectiveMaxZeilen)
                        'RING_BUFFER',
                        x.e.value('(@name)[1]', 'sysname'),
                        x.e.value('(@timestamp)[1]', 'datetime2(7)'),
                        NULL,
                        NULL,
                        x.e.query('.')
                    FROM @TargetData.nodes('/RingBufferTarget/event') AS [x]([e])
                    WHERE ((@EventNames IS NULL OR EXISTS(SELECT 1 FROM [monitor].[TVF_ParseSqlNameList](@EventNames) [ef] WHERE [ef].[IsValid]=1 AND [ef].[NameValue] COLLATE SQL_Latin1_General_CP1_CS_AS=x.e.value('(@name)[1]', 'sysname') COLLATE SQL_Latin1_General_CP1_CS_AS)) AND (@EventPatternMode IN('NONE','REGEX','REGEXI') OR x.e.value('(@name)[1]', 'sysname') COLLATE SQL_Latin1_General_CP1_CS_AS LIKE @EventPatternValue COLLATE SQL_Latin1_General_CP1_CS_AS))
                      AND (@VonUtc IS NULL OR x.e.value('(@timestamp)[1]', 'datetime2(7)') >= @VonUtc)
                      AND (@BisUtc IS NULL OR x.e.value('(@timestamp)[1]', 'datetime2(7)') < @BisUtc)
                    ORDER BY x.e.value('(@timestamp)[1]', 'datetime2(7)') DESC;

                    INSERT [#ExtendedEventsReadEvents_SourceStatus] VALUES
                    ('RING_BUFFER', @ResolvedSourceExtendedEventSessionName, 'ring_buffer', NULL, 'AVAILABLE', NULL, NULL,
                     N'sys.dm_xe_session_targets wurde bewusst gelesen; dies kann einen Target-Flush auslösen.');
                END;
            END TRY
            BEGIN CATCH
                SET @StatusCode = CASE
                                    WHEN ERROR_NUMBER() IN (229,262,297,300,371) THEN 'DENIED_PERMISSION'
                                    WHEN ERROR_NUMBER() = 1222 THEN 'TIMEOUT'
                                    WHEN ERROR_NUMBER() IN(6335,6336,6337) THEN 'XML_UNAVAILABLE_LIMIT'
                                    WHEN ERROR_NUMBER() BETWEEN 9400 AND 9431 THEN 'XML_INVALID'
                                    ELSE 'ERROR_HANDLED'
                                  END;
                SET @ErrorNumber = ERROR_NUMBER();
                SET @ErrorMessage = ERROR_MESSAGE();
                INSERT [#ExtendedEventsReadEvents_SourceStatus] VALUES('RING_BUFFER', @ResolvedSourceExtendedEventSessionName, 'ring_buffer', NULL, @StatusCode, @ErrorNumber, @ErrorMessage, N'Ringbuffer konnte nicht gelesen werden.');
            END CATCH;
        END;
    END;

    IF @StatusCode='AVAILABLE' AND (@EventPatternValid=0 OR (@EventNames IS NOT NULL AND @EventNamePattern IS NOT NULL)) BEGIN SET @StatusCode='INVALID_PARAMETER';SET @ErrorMessage=N'@EventNames oder @EventNamePattern ist ungültig.';END;
    IF @StatusCode='AVAILABLE' AND @EventPatternMode IN('REGEX','REGEXI')
    BEGIN
        IF TRY_CONVERT(int,SERVERPROPERTY(N'ProductMajorVersion'))<17 OR NOT EXISTS(SELECT 1 FROM [master].[sys].[databases] [d] WITH(NOLOCK) WHERE [d].[database_id]=DB_ID() AND [d].[compatibility_level]>=170) BEGIN SET @StatusCode='UNAVAILABLE_FEATURE';SET @ErrorMessage=N'Regex benötigt SQL Server 2025 und Compatibility Level 170.';END
        ELSE EXEC [sys].[sp_executesql] N'DELETE FROM [#ExtendedEventsReadEvents_Raw] WHERE NOT REGEXP_LIKE([EventName],@P,@F);',N'@P nvarchar(4000),@F varchar(8)',@P=@EventPatternValue,@F=@EventPatternFlags;
    END;

    SELECT @RowCount = COUNT_BIG(*) FROM [#ExtendedEventsReadEvents_Raw];

    IF @StatusCode = 'AVAILABLE' AND @RowCount = 0
    BEGIN
        SET @StatusCode = 'AVAILABLE_LIMITED';
        SET @IsPartial = 1;
        SET @ErrorMessage = COALESCE(@ErrorMessage, N'Die Quelle war lesbar, enthielt aber keine passenden Events im Filterfenster.');
    END;

    IF @IsPartial = 1 AND @StatusCode = 'AVAILABLE'
        SET @StatusCode = 'AVAILABLE_LIMITED';



    IF @PrintMeldungen = 1 AND @StatusCode NOT IN ('AVAILABLE', 'AVAILABLE_LIMITED')
        BEGIN
    SET @MonitorPrintMessage = FORMATMESSAGE(N'WARNUNG USP_ExtendedEventsReadEvents: %s - %s', @StatusCode, COALESCE(@ErrorMessage, N'Keine Details.'));
    RAISERROR(N'%s', 10, 1, @MonitorPrintMessage) WITH NOWAIT;
END;

    IF @ResultSetArtNormalisiert<>'NONE'
    BEGIN
        SELECT N'USP_ExtendedEventsReadEvents' [ModuleName],@CollectionTimeUtc [CollectionTimeUtc],@StatusCode [StatusCode],@IsPartial [IsPartial],@RowCount [RowCount],@ResolvedSource [ResolvedSource],@ErrorNumber [ErrorNumber],@ErrorMessage [ErrorMessage];
        IF @ResultSetArtNormalisiert='RAW'
        BEGIN SELECT [r].[SourceType],[r].[EventName],[r].[TimestampUtc],TRY_CONVERT(int,COALESCE([r].[EventXml].value('(/event/action[@name="database_id"]/value/text())[1]','nvarchar(32)'),[r].[EventXml].value('(/event/data[@name="database_id"]/value/text())[1]','nvarchar(32)'))) AS [DatabaseId],COALESCE([r].[EventXml].value('(/event/action[@name="database_name"]/value/text())[1]','nvarchar(256)'),[r].[EventXml].value('(/event/data[@name="database_name"]/value/text())[1]','nvarchar(256)')) AS [DatabaseName],TRY_CONVERT(int,COALESCE([r].[EventXml].value('(/event/action[@name="session_id"]/value/text())[1]','nvarchar(32)'),[r].[EventXml].value('(/event/data[@name="session_id"]/value/text())[1]','nvarchar(32)'))) AS [SessionId],[r].[EventXml].value('(/event/action[@name="client_app_name"]/value/text())[1]','nvarchar(512)') AS [ClientApplication],[r].[EventXml].value('(/event/action[@name="client_hostname"]/value/text())[1]','nvarchar(512)') AS [ClientHostName],COALESCE([r].[EventXml].value('(/event/action[@name="username"]/value/text())[1]','nvarchar(512)'),[r].[EventXml].value('(/event/action[@name="server_principal_name"]/value/text())[1]','nvarchar(512)')) AS [LoginName],COALESCE([r].[EventXml].value('(/event/action[@name="sql_text"]/value/text())[1]','nvarchar(4000)'),[r].[EventXml].value('(/event/data[@name="statement"]/value/text())[1]','nvarchar(4000)'),[r].[EventXml].value('(/event/data[@name="batch_text"]/value/text())[1]','nvarchar(4000)')) AS [SqlText],TRY_CONVERT(bigint,[r].[EventXml].value('(/event/data[@name="duration"]/value/text())[1]','nvarchar(64)')) AS [DurationRaw],TRY_CONVERT(int,[r].[EventXml].value('(/event/data[@name="error_number"]/value/text())[1]','nvarchar(32)')) AS [ErrorNumber],TRY_CONVERT(int,[r].[EventXml].value('(/event/data[@name="severity"]/value/text())[1]','nvarchar(32)')) AS [Severity],COALESCE([r].[EventXml].value('(/event/data[@name="wait_type"]/text/text())[1]','nvarchar(256)'),[r].[EventXml].value('(/event/data[@name="wait_type"]/value/text())[1]','nvarchar(256)')) AS [WaitType],[r].[EventXml].value('(/event/data[@name="resource_description"]/value/text())[1]','nvarchar(4000)') AS [ResourceDescription],[r].[FileName],[r].[FileOffset],CASE WHEN @MitEventXml=1 THEN [r].[EventXml] END AS [EventXml] FROM [#ExtendedEventsReadEvents_Raw] [r] ORDER BY [r].[TimestampUtc] DESC,[r].[FileName] DESC,[r].[FileOffset] DESC;SELECT * FROM [#ExtendedEventsReadEvents_SourceStatus] ORDER BY [SourceType],[TargetName];END
        ELSE
        BEGIN SELECT N'Extended-Events Event' [Ergebnis],[x].* FROM (SELECT [r].[SourceType],[r].[EventName],[r].[TimestampUtc],TRY_CONVERT(int,COALESCE([r].[EventXml].value('(/event/action[@name="database_id"]/value/text())[1]','nvarchar(32)'),[r].[EventXml].value('(/event/data[@name="database_id"]/value/text())[1]','nvarchar(32)'))) AS [DatabaseId],COALESCE([r].[EventXml].value('(/event/action[@name="database_name"]/value/text())[1]','nvarchar(256)'),[r].[EventXml].value('(/event/data[@name="database_name"]/value/text())[1]','nvarchar(256)')) AS [DatabaseName],TRY_CONVERT(int,COALESCE([r].[EventXml].value('(/event/action[@name="session_id"]/value/text())[1]','nvarchar(32)'),[r].[EventXml].value('(/event/data[@name="session_id"]/value/text())[1]','nvarchar(32)'))) AS [SessionId],[r].[EventXml].value('(/event/action[@name="client_app_name"]/value/text())[1]','nvarchar(512)') AS [ClientApplication],[r].[EventXml].value('(/event/action[@name="client_hostname"]/value/text())[1]','nvarchar(512)') AS [ClientHostName],COALESCE([r].[EventXml].value('(/event/action[@name="username"]/value/text())[1]','nvarchar(512)'),[r].[EventXml].value('(/event/action[@name="server_principal_name"]/value/text())[1]','nvarchar(512)')) AS [LoginName],COALESCE([r].[EventXml].value('(/event/action[@name="sql_text"]/value/text())[1]','nvarchar(4000)'),[r].[EventXml].value('(/event/data[@name="statement"]/value/text())[1]','nvarchar(4000)'),[r].[EventXml].value('(/event/data[@name="batch_text"]/value/text())[1]','nvarchar(4000)')) AS [SqlText],TRY_CONVERT(bigint,[r].[EventXml].value('(/event/data[@name="duration"]/value/text())[1]','nvarchar(64)')) AS [DurationRaw],TRY_CONVERT(int,[r].[EventXml].value('(/event/data[@name="error_number"]/value/text())[1]','nvarchar(32)')) AS [ErrorNumber],TRY_CONVERT(int,[r].[EventXml].value('(/event/data[@name="severity"]/value/text())[1]','nvarchar(32)')) AS [Severity],COALESCE([r].[EventXml].value('(/event/data[@name="wait_type"]/text/text())[1]','nvarchar(256)'),[r].[EventXml].value('(/event/data[@name="wait_type"]/value/text())[1]','nvarchar(256)')) AS [WaitType],[r].[EventXml].value('(/event/data[@name="resource_description"]/value/text())[1]','nvarchar(4000)') AS [ResourceDescription],[r].[FileName],[r].[FileOffset],CASE WHEN @MitEventXml=1 THEN [r].[EventXml] END AS [EventXml] FROM [#ExtendedEventsReadEvents_Raw] [r]) [x] ORDER BY [TimestampUtc] DESC,[FileName] DESC,[FileOffset] DESC;SELECT N'Extended-Events Quelle' [Ergebnis],[x].* FROM [#ExtendedEventsReadEvents_SourceStatus] [x] ORDER BY [SourceType],[TargetName];END;
    END;
    IF @JsonErzeugen=1
    BEGIN DECLARE @Meta nvarchar(max)=(SELECT N'ExtendedEventsReadEvents' [resultName],1 [schemaVersion],@CollectionTimeUtc [generatedAtUtc],@StatusCode [statusCode],@IsPartial [isPartial],@RowCount [returnedRows],@ResolvedSource [source],@ErrorNumber [errorNumber],@ErrorMessage [errorMessage] FOR JSON PATH,WITHOUT_ARRAY_WRAPPER,INCLUDE_NULL_VALUES),@EventsJson nvarchar(max)=(SELECT [r].[SourceType],[r].[EventName],[r].[TimestampUtc],TRY_CONVERT(int,COALESCE([r].[EventXml].value('(/event/action[@name="database_id"]/value/text())[1]','nvarchar(32)'),[r].[EventXml].value('(/event/data[@name="database_id"]/value/text())[1]','nvarchar(32)'))) AS [DatabaseId],COALESCE([r].[EventXml].value('(/event/action[@name="database_name"]/value/text())[1]','nvarchar(256)'),[r].[EventXml].value('(/event/data[@name="database_name"]/value/text())[1]','nvarchar(256)')) AS [DatabaseName],TRY_CONVERT(int,COALESCE([r].[EventXml].value('(/event/action[@name="session_id"]/value/text())[1]','nvarchar(32)'),[r].[EventXml].value('(/event/data[@name="session_id"]/value/text())[1]','nvarchar(32)'))) AS [SessionId],[r].[EventXml].value('(/event/action[@name="client_app_name"]/value/text())[1]','nvarchar(512)') AS [ClientApplication],[r].[EventXml].value('(/event/action[@name="client_hostname"]/value/text())[1]','nvarchar(512)') AS [ClientHostName],COALESCE([r].[EventXml].value('(/event/action[@name="username"]/value/text())[1]','nvarchar(512)'),[r].[EventXml].value('(/event/action[@name="server_principal_name"]/value/text())[1]','nvarchar(512)')) AS [LoginName],COALESCE([r].[EventXml].value('(/event/action[@name="sql_text"]/value/text())[1]','nvarchar(4000)'),[r].[EventXml].value('(/event/data[@name="statement"]/value/text())[1]','nvarchar(4000)'),[r].[EventXml].value('(/event/data[@name="batch_text"]/value/text())[1]','nvarchar(4000)')) AS [SqlText],TRY_CONVERT(bigint,[r].[EventXml].value('(/event/data[@name="duration"]/value/text())[1]','nvarchar(64)')) AS [DurationRaw],TRY_CONVERT(int,[r].[EventXml].value('(/event/data[@name="error_number"]/value/text())[1]','nvarchar(32)')) AS [ErrorNumber],TRY_CONVERT(int,[r].[EventXml].value('(/event/data[@name="severity"]/value/text())[1]','nvarchar(32)')) AS [Severity],COALESCE([r].[EventXml].value('(/event/data[@name="wait_type"]/text/text())[1]','nvarchar(256)'),[r].[EventXml].value('(/event/data[@name="wait_type"]/value/text())[1]','nvarchar(256)')) AS [WaitType],[r].[EventXml].value('(/event/data[@name="resource_description"]/value/text())[1]','nvarchar(4000)') AS [ResourceDescription],[r].[FileName],[r].[FileOffset],CASE WHEN @MitEventXml=1 THEN [r].[EventXml] END AS [EventXml] FROM [#ExtendedEventsReadEvents_Raw] [r] ORDER BY [r].[TimestampUtc] DESC,[r].[FileName] DESC,[r].[FileOffset] DESC FOR JSON PATH,INCLUDE_NULL_VALUES),@SourcesJson nvarchar(max)=(SELECT * FROM [#ExtendedEventsReadEvents_SourceStatus] ORDER BY [SourceType],[TargetName] FOR JSON PATH,INCLUDE_NULL_VALUES);SET @Json=CONCAT(N'{"meta":',COALESCE(@Meta,N'{}'),N',"events":',COALESCE(@EventsJson,N'[]'),N',"sources":',COALESCE(@SourcesJson,N'[]'),N',"warnings":[]}');END;
    IF @ConsoleResultRequested = 1
    BEGIN
        EXEC [monitor].[InternalEmitConsoleResult]
              @SourceTable=N'#ExtendedEventsReadEvents_Raw'
            , @ResultLabel=N'ExtendedEventsReadEvents'
            , @EmptyMessage=N'Keine fachlichen Ergebnisse';
    END;
    IF @TableResultRequested = 1
    BEGIN
        EXEC [monitor].[InternalWriteResultTable]
              @SourceTable = N'#ExtendedEventsReadEvents_Raw'
            , @TargetTable=@TableTarget
            , @ThrowOnError = 1;
    END;
END;
GO
-- END SOURCE: Code/06_ExtendedEvents/020_USP_ExtendedEventsReadEvents.sql

-- BEGIN SOURCE: Code/06_ExtendedEvents/030_USP_ExtendedEventsDeadlocks.sql
SET QUOTED_IDENTIFIER ON;
GO

/*
===============================================================================
Objekt       : monitor.USP_ExtendedEventsDeadlocks
Version      : 2.0.0
Stand        : 2026-07-15
Typ          : Stored Procedure
Zweck        : Liest bereits erfasste xml_deadlock_report-Ereignisse aus einer
               vorhandenen Extended-Events-Session und zerlegt Deadlockgraphen
               in Summary-, Victim-, Process- und Resource-Resultsets.
SQL-Version  : SQL Server 2019 oder neuer.
Datenquellen : system_health oder andere bestehende Session; event_file über
               sys.fn_xe_file_target_read_file, optional ring_buffer über
               sys.dm_xe_session_targets.
Parameter    : @ResolvedSourceExtendedEventSessionName, @Quelle, @FilePath, @VonUtc, @BisUtc, @MaxZeilen,
               @MitDeadlockXml, @MitProcessDetails, @MitResourceDetails,
               @BestaetigeTargetFlush, @PrintMeldungen, @Hilfe.
Resultsets   : 1. Modulstatus. 2. Deadlock-Summary. 3. Victims. 4. Processes.
               5. Resources. 6. Quellen-/Fehlerstatus.
Berechtigung : SQL 2019 VIEW SERVER STATE; SQL 2022+ VIEW SERVER PERFORMANCE
               STATE oder höher. Das Framework vergibt keine Rechte.
Eigenlast    : Event-Datei- und XML-abhängig; Maximalzahl und UTC-Filter werden
               vor der XML-Zerlegung angewandt. Trotzdem können XEL-Dateien
               vollständig gelesen werden müssen.
Locking      : LOCK_TIMEOUT 0; keine Benutzerobjekte und keine Änderungen.
Nebenwirkung : Ringbuffer-Lesen erfordert @BestaetigeTargetFlush=1, weil die
               Abfrage von sys.dm_xe_session_targets einen Flush auslösen kann.
Partial      : Fehlende Session, Target, Datei oder Rechte liefern Status statt
               Abbruch. Deadlockhistorie ist für den Framework-Core optional.
Beispiele    : EXEC monitor.USP_ExtendedEventsDeadlocks;
               EXEC monitor.USP_ExtendedEventsDeadlocks
                   @Quelle='RING_BUFFER', @BestaetigeTargetFlush=1;
               EXEC monitor.USP_ExtendedEventsDeadlocks @Hilfe=1;
Änderungen   : 1.0.0 - Erstfassung Phase 5.
===============================================================================
*/
CREATE OR ALTER PROCEDURE [monitor].[USP_ExtendedEventsDeadlocks]
      @SourceExtendedEventSessionName nvarchar(258)         = N'system_health'
    , @Quelle                  varchar(20)     = 'AUTO'
    , @FilePath                nvarchar(4000)  = NULL
    , @VonUtc                  datetime2(7)    = NULL
    , @BisUtc                  datetime2(7)    = NULL
    , @MaxZeilen               int             = 100
    , @MitDeadlockXml          bit             = 1
    , @MitProcessDetails       bit             = 1
    , @MitResourceDetails      bit             = 1
    , @BestaetigeTargetFlush   bit             = 0
    , @HighImpactConfirmed     bit             = 0
    , @ResultSetArt                   varchar(16)    = 'CONSOLE'
    , @ResultTablesJson               nvarchar(max) = NULL
    , @JsonErzeugen                   bit            = 0
    , @Json                            nvarchar(max)  = NULL OUTPUT
    , @PrintMeldungen          bit             = 1
    , @Hilfe                   bit             = 0
AS
BEGIN
    SET NOCOUNT ON;
    SET @Json=NULL;
    DECLARE @ResultSetArtNormalisiert varchar(16)=UPPER(LTRIM(RTRIM(COALESCE(@ResultSetArt,''))));
    DECLARE @TableResultRequested bit = CASE WHEN @ResultSetArtNormalisiert = 'TABLE' THEN 1 ELSE 0 END;
    DECLARE @ConsoleResultRequested bit = CASE WHEN @ResultSetArtNormalisiert = 'CONSOLE' THEN 1 ELSE 0 END;
    DECLARE @TableTarget sysname=NULL;
    IF @TableResultRequested=0 AND NULLIF(LTRIM(RTRIM(COALESCE(@ResultTablesJson,N''))),N'') IS NOT NULL THROW 51011,N'@ResultTablesJson ist ausschließlich mit @ResultSetArt=TABLE zulässig.',1;
    IF @TableResultRequested=1 EXEC [monitor].[InternalPrepareSingleResultTable] @ResultTablesJson=@ResultTablesJson,@ResultName=N'deadlocks',@TargetTable=@TableTarget OUTPUT,@ThrowOnError=1;
    IF @TableResultRequested = 1 OR @ConsoleResultRequested = 1 SET @ResultSetArtNormalisiert = 'NONE';
    DECLARE @ResolvedSourceExtendedEventSessionName sysname=NULL;
    DECLARE @EffectiveMaxZeilen bigint = CASE WHEN @MaxZeilen IS NULL OR @MaxZeilen=0 THEN CONVERT(bigint,9223372036854775807) ELSE CONVERT(bigint,@MaxZeilen) END;
    DECLARE @MonitorPrintMessage nvarchar(2048);

    IF @Hilfe = 1
    BEGIN
        PRINT N'monitor.USP_ExtendedEventsDeadlocks';
        PRINT N'@ResolvedSourceExtendedEventSessionName sysname=N''system_health'': vorhandene Session mit xml_deadlock_report.';
        PRINT N'@Quelle varchar(20)=''AUTO'': AUTO, EVENT_FILE oder RING_BUFFER; AUTO bevorzugt EVENT_FILE.';
        PRINT N'@FilePath nvarchar(4000)=NULL: expliziter XEL-Pfad/URL; NULL liest die Sessiondefinition.';
        PRINT N'@VonUtc datetime2(7)=NULL: NULL verwendet die letzten 24 Stunden; expliziter Wert erweitert/begrenzt das Fenster.';
        PRINT N'@BisUtc datetime2(7)=NULL: exklusive UTC-Obergrenze.';
        PRINT N'@MaxZeilen int=100: positive Werte begrenzen; NULL/0 = unbegrenzt.';
        PRINT N'@MitDeadlockXml bit=1: vollständiges Deadlock-XML im Summary-Resultset.';
        PRINT N'@MitProcessDetails bit=1: Prozessdetails; @MitResourceDetails bit=1: Ressourcen und Owner-/Waiter-XML.';
        PRINT N'@BestaetigeTargetFlush bit=0: für RING_BUFFER auf 1 setzen.';
        PRINT N'@PrintMeldungen bit=1: Warnungen Severity 10; @Hilfe bit=0: 1 zeigt diese Hilfe.';
        PRINT N'Es werden keine Extended-Events-Sessions oder Serveroptionen verändert.';
        RETURN;
    END;

    IF @SourceExtendedEventSessionName IS NULL OR (SELECT COUNT_BIG(*) FROM [monitor].[TVF_ParseSqlNameList](@SourceExtendedEventSessionName) WHERE [IsValid]=1)<>1 OR EXISTS(SELECT 1 FROM [monitor].[TVF_ParseSqlNameList](@SourceExtendedEventSessionName) WHERE [IsValid]=0)
    BEGIN SET @ResolvedSourceExtendedEventSessionName=NULL;END
    ELSE SELECT @ResolvedSourceExtendedEventSessionName=MIN([NameValue]) FROM [monitor].[TVF_ParseSqlNameList](@SourceExtendedEventSessionName) WHERE [IsValid]=1;

    DECLARE
        @CollectionTimeUtc datetime2(3) = SYSUTCDATETIME(),
        @StatusCode varchar(40) = 'AVAILABLE',
        @IsPartial bit = 0,
        @ErrorNumber int = NULL,
        @ErrorMessage nvarchar(2048) = NULL,
        @RowCount bigint = 0,
        @Allowed bit = 1,
        @ResolvedSource varchar(20) = UPPER(LTRIM(RTRIM(COALESCE(@Quelle, '')))),
        @ConfiguredFilePath nvarchar(4000) = NULL,
        @ResolvedFilePath nvarchar(4000) = NULL,
        @TargetData xml = NULL;

    IF @VonUtc IS NULL SET @VonUtc = DATEADD(HOUR, -24, SYSUTCDATETIME());

    CREATE TABLE [#ExtendedEventsDeadlocks_Raw]
    (
        [SourceType] varchar(20) COLLATE SQL_Latin1_General_CP1_CS_AS NOT NULL,
        [TimestampUtc] datetime2(7) NULL,
        [FileName] nvarchar(260) COLLATE SQL_Latin1_General_CP1_CS_AS NULL,
        [FileOffset] bigint NULL,
        [EventXml] xml NULL
    );

    CREATE TABLE [#ExtendedEventsDeadlocks_Deadlocks]
    (
        [DeadlockId] int IDENTITY(1,1) NOT NULL PRIMARY KEY,
        [SourceType] varchar(20) COLLATE SQL_Latin1_General_CP1_CS_AS NOT NULL,
        [DeadlockTimeUtc] datetime2(7) NULL,
        [FileName] nvarchar(260) COLLATE SQL_Latin1_General_CP1_CS_AS NULL,
        [FileOffset] bigint NULL,
        [DeadlockXml] xml NULL
    );

    CREATE TABLE [#ExtendedEventsDeadlocks_Victims]
    (
        [DeadlockId] int NOT NULL,
        [DeadlockTimeUtc] datetime2(7) NULL,
        [VictimProcessId] nvarchar(256) COLLATE SQL_Latin1_General_CP1_CS_AS NOT NULL,
        PRIMARY KEY(DeadlockId, VictimProcessId)
    );

    CREATE TABLE [#ExtendedEventsDeadlocks_SourceStatus]
    (
        [SourceType] varchar(20) COLLATE SQL_Latin1_General_CP1_CS_AS NULL,
        [SessionName] sysname COLLATE SQL_Latin1_General_CP1_CS_AS NULL,
        [ResolvedPath] nvarchar(4000) COLLATE SQL_Latin1_General_CP1_CS_AS NULL,
        [StatusCode] varchar(40) COLLATE SQL_Latin1_General_CP1_CS_AS NOT NULL,
        [ErrorNumber] int NULL,
        [ErrorMessage] nvarchar(2048) COLLATE SQL_Latin1_General_CP1_CS_AS NULL,
        [Detail] nvarchar(1000) COLLATE SQL_Latin1_General_CP1_CS_AS NULL
    );

    IF @ResolvedSourceExtendedEventSessionName IS NULL BEGIN SET @StatusCode='INVALID_PARAMETER';SET @ErrorMessage=N'@SourceExtendedEventSessionName muss genau einen gültigen, optional geklammerten sysname enthalten.';END;

    IF @ResolvedSource NOT IN ('AUTO','EVENT_FILE','RING_BUFFER')
    BEGIN SET @StatusCode='INVALID_PARAMETER'; SET @ErrorMessage=N'@Quelle muss AUTO, EVENT_FILE oder RING_BUFFER sein.'; END;
    IF @MaxZeilen<0 OR @ResultSetArtNormalisiert NOT IN('RAW','CONSOLE','NONE')
    BEGIN SET @StatusCode='INVALID_PARAMETER'; SET @ErrorMessage=N'@MaxZeilen darf nicht negativ sein; NULL/0 bedeutet unbegrenzt.'; END;
    IF @VonUtc IS NOT NULL AND @BisUtc IS NOT NULL AND @VonUtc >= @BisUtc
    BEGIN SET @StatusCode='INVALID_PARAMETER'; SET @ErrorMessage=N'@VonUtc muss kleiner als @BisUtc sein.'; END;

    IF @StatusCode='AVAILABLE'
        EXEC [monitor].[InternalCheckAnalysisPath] @AnalysisClass='EXTENDED_EVENTS_FORENSICS_DEEP',@HighImpactConfirmed=@HighImpactConfirmed,@StatusCode=@StatusCode OUTPUT,@ErrorMessage=@ErrorMessage OUTPUT;

    SET LOCK_TIMEOUT 0;

    IF @StatusCode='AVAILABLE'
    BEGIN
        BEGIN TRY
            SELECT @ConfiguredFilePath=MAX(CONVERT(nvarchar(4000),[f].[value]))
            FROM [sys].[server_event_sessions] AS s WITH (NOLOCK)
            JOIN [sys].[server_event_session_targets] AS t WITH (NOLOCK)
              ON [t].[event_session_id]=[s].[event_session_id] AND [t].[name]=N'event_file'
            LEFT JOIN [sys].[server_event_session_fields] AS f WITH (NOLOCK)
              ON [f].[event_session_id]=[t].[event_session_id] AND [f].[object_id]=[t].[target_id] AND [f].[name]=N'filename'
            WHERE [s].[name]=@ResolvedSourceExtendedEventSessionName;
        END TRY
        BEGIN CATCH
            SET @IsPartial=1;
            INSERT [#ExtendedEventsDeadlocks_SourceStatus] VALUES('CATALOG',@ResolvedSourceExtendedEventSessionName,NULL,
              CASE WHEN ERROR_NUMBER() IN(229,262,297,300,371) THEN 'DENIED_PERMISSION' ELSE 'ERROR_HANDLED' END,
              ERROR_NUMBER(),ERROR_MESSAGE(),N'Pfadermittlung fehlgeschlagen; ein expliziter @FilePath kann weiterhin verwendet werden.');
        END CATCH;

        IF @ResolvedSource='AUTO'
        BEGIN
            IF @FilePath IS NOT NULL OR @ConfiguredFilePath IS NOT NULL SET @ResolvedSource='EVENT_FILE';
            ELSE IF @BestaetigeTargetFlush=1 SET @ResolvedSource='RING_BUFFER';
            ELSE
            BEGIN SET @StatusCode='AVAILABLE_DISABLED'; SET @ErrorMessage=N'Kein event_file-Pfad; Ringbuffer ohne Bestätigung nicht gelesen.'; END;
        END;
    END;

    IF @StatusCode='AVAILABLE' AND @ResolvedSource='EVENT_FILE'
    BEGIN
        SET @ResolvedFilePath=COALESCE(NULLIF(@FilePath,N''),NULLIF(@ConfiguredFilePath,N''));
        IF @ResolvedFilePath IS NULL
        BEGIN
            SET @StatusCode='UNAVAILABLE_OBJECT'; SET @ErrorMessage=N'Kein event_file-Pfad verfügbar.';
            INSERT [#ExtendedEventsDeadlocks_SourceStatus] VALUES('EVENT_FILE',@ResolvedSourceExtendedEventSessionName,NULL,@StatusCode,NULL,@ErrorMessage,N'Keine XEL-Datei gelesen.');
        END
        ELSE
        BEGIN
            IF (RIGHT(LOWER(@ResolvedFilePath),4) = N'.xel')
                SET @ResolvedFilePath=LEFT(@ResolvedFilePath,LEN(@ResolvedFilePath)-4)+N'*.xel';
            ELSE IF CHARINDEX(N'*',@ResolvedFilePath)=0
                SET @ResolvedFilePath=@ResolvedFilePath+N'*.xel';

            BEGIN TRY
                INSERT [#ExtendedEventsDeadlocks_Raw]([SourceType],[TimestampUtc],[FileName],[FileOffset],[EventXml])
                SELECT TOP (@EffectiveMaxZeilen)
                    'EVENT_FILE',[r].[timestamp_utc],[r].[file_name],[r].[file_offset],CONVERT([xml],[r].[event_data])
                FROM sys.fn_xe_file_target_read_file(@ResolvedFilePath,NULL,NULL,NULL) AS r
                WHERE [r].[object_name]=N'xml_deadlock_report'
                  AND (@VonUtc IS NULL OR [r].[timestamp_utc]>=@VonUtc)
                  AND (@BisUtc IS NULL OR [r].[timestamp_utc]<@BisUtc)
                ORDER BY [r].[timestamp_utc] DESC,[r].[file_name] DESC,[r].[file_offset] DESC;
                INSERT [#ExtendedEventsDeadlocks_SourceStatus] VALUES('EVENT_FILE',@ResolvedSourceExtendedEventSessionName,@ResolvedFilePath,'AVAILABLE',NULL,NULL,N'xml_deadlock_report aus XEL gelesen.');
            END TRY
            BEGIN CATCH
                SET @StatusCode=CASE WHEN ERROR_NUMBER() IN(229,262,297,300,371) THEN 'DENIED_PERMISSION' WHEN ERROR_NUMBER()=1222 THEN 'TIMEOUT' WHEN ERROR_NUMBER() IN(6335,6336,6337) THEN 'XML_UNAVAILABLE_LIMIT' WHEN ERROR_NUMBER() BETWEEN 9400 AND 9431 THEN 'XML_INVALID' ELSE 'ERROR_HANDLED' END;
                SET @ErrorNumber=ERROR_NUMBER(); SET @ErrorMessage=ERROR_MESSAGE();
                INSERT [#ExtendedEventsDeadlocks_SourceStatus] VALUES('EVENT_FILE',@ResolvedSourceExtendedEventSessionName,@ResolvedFilePath,@StatusCode,@ErrorNumber,@ErrorMessage,N'XEL-Datei konnte nicht gelesen werden.');
            END CATCH;
        END;
    END;

    IF @StatusCode='AVAILABLE' AND @ResolvedSource='RING_BUFFER'
    BEGIN
        IF @BestaetigeTargetFlush=0
        BEGIN
            SET @StatusCode='AVAILABLE_DISABLED'; SET @ErrorMessage=N'RING_BUFFER erfordert @BestaetigeTargetFlush=1.';
            INSERT [#ExtendedEventsDeadlocks_SourceStatus] VALUES('RING_BUFFER',@ResolvedSourceExtendedEventSessionName,NULL,@StatusCode,NULL,@ErrorMessage,N'Targetdaten wurden nicht gelesen.');
        END
        ELSE
        BEGIN
            BEGIN TRY
                SELECT @TargetData=CONVERT([xml],[t].[target_data])
                FROM [sys].[dm_xe_session_targets] AS t WITH (NOLOCK)
                JOIN [sys].[dm_xe_sessions] AS s WITH (NOLOCK) ON [s].[address]=[t].[event_session_address]
                WHERE [s].[name]=@ResolvedSourceExtendedEventSessionName AND [t].[target_name]=N'ring_buffer';

                IF @TargetData IS NULL
                BEGIN
                    SET @StatusCode='UNAVAILABLE_OBJECT'; SET @ErrorMessage=N'Kein lesbares laufendes ring_buffer-Target gefunden.';
                    INSERT [#ExtendedEventsDeadlocks_SourceStatus] VALUES('RING_BUFFER',@ResolvedSourceExtendedEventSessionName,NULL,@StatusCode,NULL,@ErrorMessage,N'Session gestoppt oder Ringbuffer nicht vorhanden.');
                END
                ELSE
                BEGIN
                    INSERT [#ExtendedEventsDeadlocks_Raw]([SourceType],[TimestampUtc],[FileName],[FileOffset],[EventXml])
                    SELECT TOP (@EffectiveMaxZeilen)
                        'RING_BUFFER',x.e.value('(@timestamp)[1]','datetime2(7)'),NULL,NULL,x.e.query('.')
                    FROM @TargetData.nodes('/RingBufferTarget/event[@name="xml_deadlock_report"]') AS [x]([e])
                    WHERE (@VonUtc IS NULL OR x.e.value('(@timestamp)[1]','datetime2(7)')>=@VonUtc)
                      AND (@BisUtc IS NULL OR x.e.value('(@timestamp)[1]','datetime2(7)')<@BisUtc)
                    ORDER BY x.e.value('(@timestamp)[1]','datetime2(7)') DESC;
                    INSERT [#ExtendedEventsDeadlocks_SourceStatus] VALUES('RING_BUFFER',@ResolvedSourceExtendedEventSessionName,NULL,'AVAILABLE',NULL,NULL,N'Ringbuffer bewusst gelesen; Target-Flush ist möglich.');
                END;
            END TRY
            BEGIN CATCH
                SET @StatusCode=CASE WHEN ERROR_NUMBER() IN(229,262,297,300,371) THEN 'DENIED_PERMISSION' WHEN ERROR_NUMBER()=1222 THEN 'TIMEOUT' WHEN ERROR_NUMBER() IN(6335,6336,6337) THEN 'XML_UNAVAILABLE_LIMIT' WHEN ERROR_NUMBER() BETWEEN 9400 AND 9431 THEN 'XML_INVALID' ELSE 'ERROR_HANDLED' END;
                SET @ErrorNumber=ERROR_NUMBER(); SET @ErrorMessage=ERROR_MESSAGE();
                INSERT [#ExtendedEventsDeadlocks_SourceStatus] VALUES('RING_BUFFER',@ResolvedSourceExtendedEventSessionName,NULL,@StatusCode,@ErrorNumber,@ErrorMessage,N'Ringbuffer konnte nicht gelesen werden.');
            END CATCH;
        END;
    END;

    IF @StatusCode='AVAILABLE'
    BEGIN
        INSERT [#ExtendedEventsDeadlocks_Deadlocks]([SourceType],[DeadlockTimeUtc],[FileName],[FileOffset],[DeadlockXml])
        SELECT [SourceType],[TimestampUtc],[FileName],[FileOffset],
               EventXml.query('(/event/data[@name="xml_report"]/value/deadlock)[1]')
        FROM [#ExtendedEventsDeadlocks_Raw]
        WHERE EventXml.exist('/event/data[@name="xml_report"]/value/deadlock')=1;

        INSERT [#ExtendedEventsDeadlocks_Victims]([DeadlockId],[DeadlockTimeUtc],[VictimProcessId])
        SELECT [d].[DeadlockId],[d].[DeadlockTimeUtc],v.p.value('(@id)[1]','nvarchar(256)')
        FROM [#ExtendedEventsDeadlocks_Deadlocks] AS d
        CROSS APPLY d.DeadlockXml.nodes('/deadlock/victim-list/victimProcess') AS [v]([p]);

        SELECT @RowCount=COUNT_BIG(*) FROM [#ExtendedEventsDeadlocks_Deadlocks];
        IF @RowCount=0
        BEGIN
            SET @StatusCode='AVAILABLE_LIMITED'; SET @IsPartial=1;
            SET @ErrorMessage=N'Quelle lesbar, aber keine passenden Deadlockgraphen gefunden.';
        END;
    END;

    IF @IsPartial=1 AND @StatusCode='AVAILABLE' SET @StatusCode='AVAILABLE_LIMITED';


    IF @PrintMeldungen=1 AND @StatusCode NOT IN('AVAILABLE','AVAILABLE_LIMITED')
        BEGIN
    SET @MonitorPrintMessage = FORMATMESSAGE(N'WARNUNG USP_ExtendedEventsDeadlocks: %s - %s', @StatusCode, COALESCE(@ErrorMessage,N'Keine Details.'));
    RAISERROR(N'%s', 10, 1, @MonitorPrintMessage) WITH NOWAIT;
END;

    CREATE TABLE [#ExtendedEventsDeadlocks_DeadlockSummary]([DeadlockId] int,[SourceType] varchar(20) COLLATE SQL_Latin1_General_CP1_CS_AS,[DeadlockTimeUtc] datetime2(7),[FileName] nvarchar(260) COLLATE SQL_Latin1_General_CP1_CS_AS,[FileOffset] bigint,[VictimCount] int,[ProcessCount] int,[ResourceCount] int,[FirstDatabaseId] int NULL,[DeadlockXml] xml NULL);
    CREATE TABLE [#ExtendedEventsDeadlocks_DeadlockProcesses]([DeadlockId] int,[DeadlockTimeUtc] datetime2(7),[ProcessId] nvarchar(256) COLLATE SQL_Latin1_General_CP1_CS_AS,[IsVictim] bit,[SessionId] int NULL,[ExecutionContextId] int NULL,[ProcessStatus] nvarchar(128) COLLATE SQL_Latin1_General_CP1_CS_AS,[WaitResource] nvarchar(1024) COLLATE SQL_Latin1_General_CP1_CS_AS,[WaitTimeMs] bigint NULL,[LockMode] nvarchar(64) COLLATE SQL_Latin1_General_CP1_CS_AS,[TransactionName] nvarchar(256) COLLATE SQL_Latin1_General_CP1_CS_AS,[IsolationLevel] nvarchar(256) COLLATE SQL_Latin1_General_CP1_CS_AS,[DatabaseId] int NULL,[ClientApplication] nvarchar(512) COLLATE SQL_Latin1_General_CP1_CS_AS,[HostName] nvarchar(512) COLLATE SQL_Latin1_General_CP1_CS_AS,[LoginName] nvarchar(512) COLLATE SQL_Latin1_General_CP1_CS_AS,[HostProcessId] int NULL,[TransactionCount] int NULL,[LogUsed] bigint NULL,[InputBuffer] nvarchar(4000) COLLATE SQL_Latin1_General_CP1_CS_AS,[ProcessXml] xml NULL);
    CREATE TABLE [#ExtendedEventsDeadlocks_DeadlockResources]([DeadlockId] int,[DeadlockTimeUtc] datetime2(7),[ResourceType] sysname COLLATE SQL_Latin1_General_CP1_CS_AS,[DatabaseId] int NULL,[ObjectId] bigint NULL,[IndexId] bigint NULL,[AssociatedObjectId] bigint NULL,[ResourceId] nvarchar(512) COLLATE SQL_Latin1_General_CP1_CS_AS,[ResourceMode] nvarchar(64) COLLATE SQL_Latin1_General_CP1_CS_AS,[OwnerListXml] xml NULL,[WaiterListXml] xml NULL,[ResourceXml] xml NULL);
    INSERT [#ExtendedEventsDeadlocks_DeadlockSummary] SELECT [d].[DeadlockId],[d].[SourceType],[d].[DeadlockTimeUtc],[d].[FileName],[d].[FileOffset],[d].[DeadlockXml].value('count(/deadlock/victim-list/victimProcess)','int'),[d].[DeadlockXml].value('count(/deadlock/process-list/process)','int'),[d].[DeadlockXml].value('count(/deadlock/resource-list/*)','int'),TRY_CONVERT(int,[d].[DeadlockXml].value('(/deadlock/process-list/process[1]/@currentdb)[1]','nvarchar(32)')),CASE WHEN @MitDeadlockXml=1 THEN [d].[DeadlockXml] END FROM [#ExtendedEventsDeadlocks_Deadlocks] [d];
    IF @MitProcessDetails=1 INSERT [#ExtendedEventsDeadlocks_DeadlockProcesses] SELECT [d].[DeadlockId],[d].[DeadlockTimeUtc],[p].[n].value('(@id)[1]','nvarchar(256)'),CONVERT(bit,CASE WHEN [v].[VictimProcessId] IS NOT NULL THEN 1 ELSE 0 END),TRY_CONVERT(int,[p].[n].value('(@spid)[1]','nvarchar(32)')),TRY_CONVERT(int,[p].[n].value('(@ecid)[1]','nvarchar(32)')),[p].[n].value('(@status)[1]','nvarchar(128)'),[p].[n].value('(@waitresource)[1]','nvarchar(1024)'),TRY_CONVERT(bigint,[p].[n].value('(@waittime)[1]','nvarchar(64)')),[p].[n].value('(@lockMode)[1]','nvarchar(64)'),[p].[n].value('(@transactionname)[1]','nvarchar(256)'),[p].[n].value('(@isolationlevel)[1]','nvarchar(256)'),TRY_CONVERT(int,[p].[n].value('(@currentdb)[1]','nvarchar(32)')),[p].[n].value('(@clientapp)[1]','nvarchar(512)'),[p].[n].value('(@hostname)[1]','nvarchar(512)'),[p].[n].value('(@loginname)[1]','nvarchar(512)'),TRY_CONVERT(int,[p].[n].value('(@hostpid)[1]','nvarchar(32)')),TRY_CONVERT(int,[p].[n].value('(@trancount)[1]','nvarchar(32)')),TRY_CONVERT(bigint,[p].[n].value('(@logused)[1]','nvarchar(64)')),[p].[n].value('(inputbuf/text())[1]','nvarchar(4000)'),[p].[n].query('.') FROM [#ExtendedEventsDeadlocks_Deadlocks] [d] CROSS APPLY [d].[DeadlockXml].nodes('/deadlock/process-list/process') [p]([n]) LEFT JOIN [#ExtendedEventsDeadlocks_Victims] [v] ON [v].[DeadlockId]=[d].[DeadlockId] AND [v].[VictimProcessId]=[p].[n].value('(@id)[1]','nvarchar(256)');
    IF @MitResourceDetails=1 INSERT [#ExtendedEventsDeadlocks_DeadlockResources] SELECT [d].[DeadlockId],[d].[DeadlockTimeUtc],[r].[n].value('local-name(.)','sysname'),TRY_CONVERT(int,[r].[n].value('(@dbid)[1]','nvarchar(32)')),TRY_CONVERT(bigint,[r].[n].value('(@objectid)[1]','nvarchar(64)')),TRY_CONVERT(bigint,[r].[n].value('(@indexid)[1]','nvarchar(64)')),TRY_CONVERT(bigint,[r].[n].value('(@associatedObjectId)[1]','nvarchar(64)')),[r].[n].value('(@id)[1]','nvarchar(512)'),[r].[n].value('(@mode)[1]','nvarchar(64)'),[r].[n].query('(owner-list)[1]'),[r].[n].query('(waiter-list)[1]'),[r].[n].query('.') FROM [#ExtendedEventsDeadlocks_Deadlocks] [d] CROSS APPLY [d].[DeadlockXml].nodes('/deadlock/resource-list/*') [r]([n]);

    IF @ResultSetArtNormalisiert<>'NONE'
    BEGIN
      SELECT N'USP_ExtendedEventsDeadlocks' [ModuleName],@CollectionTimeUtc [CollectionTimeUtc],@StatusCode [StatusCode],@IsPartial [IsPartial],@RowCount [RowCount],@ResolvedSource [ResolvedSource],@ErrorNumber [ErrorNumber],@ErrorMessage [ErrorMessage];
      IF @ResultSetArtNormalisiert='RAW' BEGIN SELECT * FROM [#ExtendedEventsDeadlocks_DeadlockSummary] ORDER BY [DeadlockTimeUtc] DESC,[DeadlockId];SELECT * FROM [#ExtendedEventsDeadlocks_Victims] ORDER BY [DeadlockTimeUtc] DESC,[DeadlockId],[VictimProcessId];SELECT * FROM [#ExtendedEventsDeadlocks_DeadlockProcesses] ORDER BY [DeadlockTimeUtc] DESC,[DeadlockId],[SessionId],[ExecutionContextId];SELECT * FROM [#ExtendedEventsDeadlocks_DeadlockResources] ORDER BY [DeadlockTimeUtc] DESC,[DeadlockId],[ResourceType];SELECT * FROM [#ExtendedEventsDeadlocks_SourceStatus] ORDER BY [SourceType];END
      ELSE BEGIN SELECT N'Deadlock' [Ergebnis],[x].* FROM [#ExtendedEventsDeadlocks_DeadlockSummary] [x] ORDER BY [DeadlockTimeUtc] DESC,[DeadlockId];SELECT N'Deadlock Victim' [Ergebnis],[x].* FROM [#ExtendedEventsDeadlocks_Victims] [x] ORDER BY [DeadlockTimeUtc] DESC,[DeadlockId],[VictimProcessId];SELECT N'Deadlock Prozess' [Ergebnis],[DeadlockId] [Deadlock],[SessionId] [Session],[ExecutionContextId] [ECID],[IsVictim] [Victim],[WaitTimeMs] [Wait ms],[WaitResource] [Wait-Ressource],[LoginName] [Login],[HostName] [Host],[SessionId] [Session SQL],[InputBuffer] [SQL] FROM [#ExtendedEventsDeadlocks_DeadlockProcesses] ORDER BY [DeadlockTimeUtc] DESC,[DeadlockId],[SessionId],[ExecutionContextId];SELECT N'Deadlock Ressource' [Ergebnis],[x].* FROM [#ExtendedEventsDeadlocks_DeadlockResources] [x] ORDER BY [DeadlockTimeUtc] DESC,[DeadlockId],[ResourceType];SELECT N'Extended-Events Quelle' [Ergebnis],[x].* FROM [#ExtendedEventsDeadlocks_SourceStatus] [x] ORDER BY [SourceType];END;
    END;
    IF @JsonErzeugen=1 BEGIN DECLARE @Meta nvarchar(max)=(SELECT N'ExtendedEventsDeadlocks' [resultName],1 [schemaVersion],@CollectionTimeUtc [generatedAtUtc],@StatusCode [statusCode],@IsPartial [isPartial],@RowCount [returnedRows],@ResolvedSource [source],@ErrorNumber [errorNumber],@ErrorMessage [errorMessage] FOR JSON PATH,WITHOUT_ARRAY_WRAPPER,INCLUDE_NULL_VALUES),@D nvarchar(max)=(SELECT [DeadlockId],[SourceType],[DeadlockTimeUtc],[FileName],[FileOffset],[VictimCount],[ProcessCount],[ResourceCount],[FirstDatabaseId],CONVERT(nvarchar(max),[DeadlockXml]) [DeadlockXml] FROM [#ExtendedEventsDeadlocks_DeadlockSummary] ORDER BY [DeadlockTimeUtc] DESC,[DeadlockId] FOR JSON PATH,INCLUDE_NULL_VALUES),@V nvarchar(max)=(SELECT * FROM [#ExtendedEventsDeadlocks_Victims] ORDER BY [DeadlockTimeUtc] DESC,[DeadlockId],[VictimProcessId] FOR JSON PATH,INCLUDE_NULL_VALUES),@P nvarchar(max)=(SELECT [DeadlockId],[DeadlockTimeUtc],[ProcessId],[IsVictim],[SessionId],[ExecutionContextId],[ProcessStatus],[WaitResource],[WaitTimeMs],[LockMode],[TransactionName],[IsolationLevel],[DatabaseId],[ClientApplication],[HostName],[LoginName],[HostProcessId],[TransactionCount],[LogUsed],[InputBuffer],CONVERT(nvarchar(max),[ProcessXml]) [ProcessXml] FROM [#ExtendedEventsDeadlocks_DeadlockProcesses] ORDER BY [DeadlockTimeUtc] DESC,[DeadlockId],[SessionId],[ExecutionContextId] FOR JSON PATH,INCLUDE_NULL_VALUES),@R nvarchar(max)=(SELECT [DeadlockId],[DeadlockTimeUtc],[ResourceType],[DatabaseId],[ObjectId],[IndexId],[AssociatedObjectId],[ResourceId],[ResourceMode],CONVERT(nvarchar(max),[OwnerListXml]) [OwnerListXml],CONVERT(nvarchar(max),[WaiterListXml]) [WaiterListXml],CONVERT(nvarchar(max),[ResourceXml]) [ResourceXml] FROM [#ExtendedEventsDeadlocks_DeadlockResources] ORDER BY [DeadlockTimeUtc] DESC,[DeadlockId],[ResourceType] FOR JSON PATH,INCLUDE_NULL_VALUES),@S nvarchar(max)=(SELECT * FROM [#ExtendedEventsDeadlocks_SourceStatus] ORDER BY [SourceType] FOR JSON PATH,INCLUDE_NULL_VALUES);SET @Json=CONCAT(N'{"meta":',COALESCE(@Meta,N'{}'),N',"deadlocks":',COALESCE(@D,N'[]'),N',"victims":',COALESCE(@V,N'[]'),N',"processes":',COALESCE(@P,N'[]'),N',"resources":',COALESCE(@R,N'[]'),N',"sources":',COALESCE(@S,N'[]'),N',"warnings":[]}');END;
    IF @ConsoleResultRequested = 1
    BEGIN
        EXEC [monitor].[InternalEmitConsoleResult]
              @SourceTable=N'#ExtendedEventsDeadlocks_DeadlockSummary'
            , @ResultLabel=N'ExtendedEventsDeadlocks'
            , @EmptyMessage=N'Keine fachlichen Ergebnisse';
    END;
    IF @TableResultRequested = 1
    BEGIN
        EXEC [monitor].[InternalWriteResultTable]
              @SourceTable = N'#ExtendedEventsDeadlocks_DeadlockSummary'
            , @TargetTable=@TableTarget
            , @ThrowOnError = 1;
    END;
END;
GO
-- END SOURCE: Code/06_ExtendedEvents/030_USP_ExtendedEventsDeadlocks.sql

-- BEGIN SOURCE: Code/06_ExtendedEvents/040_USP_ExtendedEventsBlockedProcesses.sql
SET QUOTED_IDENTIFIER ON;
GO

/*
===============================================================================
Objekt       : monitor.USP_ExtendedEventsBlockedProcesses
Version      : 2.0.0
Stand        : 2026-07-15
Typ          : Stored Procedure
Zweck        : Liest bereits erfasste blocked_process_report-Ereignisse aus
               vorhandenen Extended-Events-Targets und zerlegt die Reports in
               Summary-, Blocked- und Blocking-Process-Resultsets.
SQL-Version  : SQL Server 2019 oder neuer.
Datenquellen : vorhandene serverweite XE-Session mit blocked_process_report,
               event_file oder optional ring_buffer; sys.configurations lesend.
Parameter    : @ResolvedSourceExtendedEventSessionName, @Quelle, @FilePath, @VonUtc, @BisUtc,
               @MaxZeilen, @MitReportXml, @MitProcessXml,
               @BestaetigeTargetFlush, @PrintMeldungen, @Hilfe.
Resultsets   : 1. Modulstatus. 2. Report-Summary. 3. blocked process.
               4. blocking process. 5. Quellen-/Fehlerstatus.
Berechtigung : SQL 2019 VIEW SERVER STATE; SQL 2022+ VIEW SERVER PERFORMANCE
               STATE oder höher. Das Framework vergibt keine Rechte.
Eigenlast    : Event-Datei- und XML-abhängig; begrenzte Ergebnismenge und
               Vorfilter vor XML-Zerlegung. XEL-Dateien können dennoch vollständig
               gelesen werden müssen.
Locking      : LOCK_TIMEOUT 0; keine Benutzerobjekte und keine Änderungen.
Nebenwirkung : Ringbuffer-Lesen erfordert @BestaetigeTargetFlush=1.
Voraussetzung: Reports existieren nur, wenn blocked process threshold und eine
               erfassende Session bereits außerhalb des Frameworks konfiguriert sind.
Partial      : Fehlende Konfiguration, Session, Datei oder Rechte werden als Status
               gemeldet und brechen andere Monitoring-Funktionen nicht ab.
Beispiele    : EXEC monitor.USP_ExtendedEventsBlockedProcesses;
               EXEC monitor.USP_ExtendedEventsBlockedProcesses
                   @ResolvedSourceExtendedEventSessionName=N'MeineBlockingSession', @Quelle='EVENT_FILE';
               EXEC monitor.USP_ExtendedEventsBlockedProcesses @Hilfe=1;
Änderungen   : 1.0.0 - Erstfassung Phase 5.
===============================================================================
*/
CREATE OR ALTER PROCEDURE [monitor].[USP_ExtendedEventsBlockedProcesses]
      @SourceExtendedEventSessionName nvarchar(258)         = NULL
    , @Quelle                  varchar(20)     = 'AUTO'
    , @FilePath                nvarchar(4000)  = NULL
    , @VonUtc                  datetime2(7)    = NULL
    , @BisUtc                  datetime2(7)    = NULL
    , @MaxZeilen              int             = 200
    , @MitReportXml            bit             = 1
    , @MitProcessXml           bit             = 0
    , @BestaetigeTargetFlush   bit             = 0
    , @HighImpactConfirmed     bit             = 0
    , @ResultSetArt                   varchar(16)    = 'CONSOLE'
    , @ResultTablesJson               nvarchar(max) = NULL
    , @JsonErzeugen                   bit            = 0
    , @Json                            nvarchar(max)  = NULL OUTPUT
    , @PrintMeldungen          bit             = 1
    , @Hilfe                   bit             = 0
AS
BEGIN
    SET NOCOUNT ON;
    SET @Json=NULL;
    DECLARE @ResultSetArtNormalisiert varchar(16)=UPPER(LTRIM(RTRIM(COALESCE(@ResultSetArt,''))));
    DECLARE @TableResultRequested bit = CASE WHEN @ResultSetArtNormalisiert = 'TABLE' THEN 1 ELSE 0 END;
    DECLARE @ConsoleResultRequested bit = CASE WHEN @ResultSetArtNormalisiert = 'CONSOLE' THEN 1 ELSE 0 END;
    DECLARE @TableTarget sysname=NULL;
    IF @TableResultRequested=0 AND NULLIF(LTRIM(RTRIM(COALESCE(@ResultTablesJson,N''))),N'') IS NOT NULL THROW 51011,N'@ResultTablesJson ist ausschließlich mit @ResultSetArt=TABLE zulässig.',1;
    IF @TableResultRequested=1 EXEC [monitor].[InternalPrepareSingleResultTable] @ResultTablesJson=@ResultTablesJson,@ResultName=N'reports',@TargetTable=@TableTarget OUTPUT,@ThrowOnError=1;
    IF @TableResultRequested = 1 OR @ConsoleResultRequested = 1 SET @ResultSetArtNormalisiert = 'NONE';
    DECLARE @ResolvedSourceExtendedEventSessionName sysname=NULL;
    DECLARE @EffectiveMaxZeilen bigint = CASE WHEN @MaxZeilen IS NULL OR @MaxZeilen=0 THEN CONVERT(bigint,9223372036854775807) ELSE CONVERT(bigint,@MaxZeilen) END;
    DECLARE @MonitorPrintMessage nvarchar(2048);

    IF @Hilfe=1
    BEGIN
        PRINT N'monitor.USP_ExtendedEventsBlockedProcesses';
        PRINT N'@ResolvedSourceExtendedEventSessionName sysname=NULL: konkrete vorhandene Session; NULL sucht eine Session mit blocked_process_report.';
        PRINT N'@Quelle varchar(20)=''AUTO'': AUTO, EVENT_FILE oder RING_BUFFER; AUTO bevorzugt EVENT_FILE.';
        PRINT N'@FilePath nvarchar(4000)=NULL: optionaler XEL-Pfad/URL; NULL liest die Sessiondefinition.';
        PRINT N'@VonUtc datetime2(7)=NULL: NULL verwendet letzte 24 Stunden; @BisUtc datetime2(7)=NULL: exklusive Obergrenze.';
        PRINT N'@MaxZeilen int=200: positive Werte begrenzen; NULL/0 = unbegrenzt.';
        PRINT N'@MitReportXml bit=1: vollständiges blocked-process-report XML im Summary.';
        PRINT N'@MitProcessXml bit=0: Prozess-XML in den Detailresultsets.';
        PRINT N'@BestaetigeTargetFlush bit=0: für RING_BUFFER auf 1 setzen.';
        PRINT N'@PrintMeldungen bit=1: Warnungen Severity 10; @Hilfe bit=0: 1 zeigt diese Hilfe.';
        PRINT N'Die Procedure ändert weder blocked process threshold noch Extended-Events-Sessions.';
        RETURN;
    END;

    IF @SourceExtendedEventSessionName IS NULL OR (SELECT COUNT_BIG(*) FROM [monitor].[TVF_ParseSqlNameList](@SourceExtendedEventSessionName) WHERE [IsValid]=1)<>1 OR EXISTS(SELECT 1 FROM [monitor].[TVF_ParseSqlNameList](@SourceExtendedEventSessionName) WHERE [IsValid]=0)
    BEGIN SET @ResolvedSourceExtendedEventSessionName=NULL;END
    ELSE SELECT @ResolvedSourceExtendedEventSessionName=MIN([NameValue]) FROM [monitor].[TVF_ParseSqlNameList](@SourceExtendedEventSessionName) WHERE [IsValid]=1;

    DECLARE
        @CollectionTimeUtc datetime2(3)=SYSUTCDATETIME(),
        @StatusCode varchar(40)='AVAILABLE',
        @IsPartial bit=0,
        @ErrorNumber int=NULL,
        @ErrorMessage nvarchar(2048)=NULL,
        @RowCount bigint=0,
        @Allowed bit=1,
        @ResolvedSource varchar(20)=UPPER(LTRIM(RTRIM(COALESCE(@Quelle,'')))),
        @ResolvedSessionName sysname=@ResolvedSourceExtendedEventSessionName,
        @ConfiguredFilePath nvarchar(4000)=NULL,
        @ResolvedFilePath nvarchar(4000)=NULL,
        @TargetData xml=NULL,
        @BlockedProcessThresholdSeconds int=NULL;

    IF @VonUtc IS NULL SET @VonUtc=DATEADD(HOUR,-24,SYSUTCDATETIME());

    CREATE TABLE [#ExtendedEventsBlockedProcesses_Raw]([SourceType] varchar(20) COLLATE SQL_Latin1_General_CP1_CS_AS NOT NULL,[TimestampUtc] datetime2(7) NULL,[FileName] nvarchar(260) COLLATE SQL_Latin1_General_CP1_CS_AS NULL,[FileOffset] bigint NULL,[EventXml] xml NULL);
    CREATE TABLE [#ExtendedEventsBlockedProcesses_Reports]
    (
        [ReportId] int IDENTITY(1,1) NOT NULL PRIMARY KEY,
        [SourceType] varchar(20) COLLATE SQL_Latin1_General_CP1_CS_AS NOT NULL,
        [ReportTimeUtc] datetime2(7) NULL,
        [FileName] nvarchar(260) COLLATE SQL_Latin1_General_CP1_CS_AS NULL,
        [FileOffset] bigint NULL,
        [ReportXml] xml NULL
    );
    CREATE TABLE [#ExtendedEventsBlockedProcesses_SourceStatus]
    (
        [SourceType] varchar(20) COLLATE SQL_Latin1_General_CP1_CS_AS NULL,[SessionName] sysname COLLATE SQL_Latin1_General_CP1_CS_AS NULL,[ResolvedPath] nvarchar(4000) COLLATE SQL_Latin1_General_CP1_CS_AS NULL,
        [StatusCode] varchar(40) COLLATE SQL_Latin1_General_CP1_CS_AS NOT NULL,[ErrorNumber] int NULL,[ErrorMessage] nvarchar(2048) COLLATE SQL_Latin1_General_CP1_CS_AS NULL,[Detail] nvarchar(1000) COLLATE SQL_Latin1_General_CP1_CS_AS NULL
    );

    IF @ResolvedSource NOT IN('AUTO','EVENT_FILE','RING_BUFFER')
    BEGIN SET @StatusCode='INVALID_PARAMETER';SET @ErrorMessage=N'@Quelle muss AUTO, EVENT_FILE oder RING_BUFFER sein.';END;
    IF @MaxZeilen<0 OR @ResultSetArtNormalisiert NOT IN('RAW','CONSOLE','NONE')
    BEGIN SET @StatusCode='INVALID_PARAMETER';SET @ErrorMessage=N'@MaxZeilen darf nicht negativ sein; NULL/0 bedeutet unbegrenzt.';END;
    IF @VonUtc IS NOT NULL AND @BisUtc IS NOT NULL AND @VonUtc>=@BisUtc
    BEGIN SET @StatusCode='INVALID_PARAMETER';SET @ErrorMessage=N'@VonUtc muss kleiner als @BisUtc sein.';END;

    IF @StatusCode='AVAILABLE'
        EXEC [monitor].[InternalCheckAnalysisPath] @AnalysisClass='EXTENDED_EVENTS_FORENSICS_DEEP',@HighImpactConfirmed=@HighImpactConfirmed,@StatusCode=@StatusCode OUTPUT,@ErrorMessage=@ErrorMessage OUTPUT;

    SET LOCK_TIMEOUT 0;

    IF @StatusCode='AVAILABLE'
    BEGIN
        BEGIN TRY
            SELECT @BlockedProcessThresholdSeconds=TRY_CONVERT([int],[value_in_use])
            FROM [sys].[configurations] WITH (NOLOCK) WHERE [name]=N'blocked process threshold (s)';
        END TRY
        BEGIN CATCH
            SET @IsPartial=1;
        END CATCH;

        BEGIN TRY
            IF @ResolvedSessionName IS NULL
            BEGIN
                SELECT TOP(1) @ResolvedSessionName=[s].[name]
                FROM [sys].[server_event_sessions] AS s WITH (NOLOCK)
                JOIN [sys].[server_event_session_events] AS e WITH (NOLOCK)
                  ON [e].[event_session_id]=[s].[event_session_id] AND [e].[name]=N'blocked_process_report'
                ORDER BY CASE WHEN EXISTS
                (
                    SELECT 1 FROM [sys].[server_event_session_targets] AS t WITH (NOLOCK)
                    WHERE [t].[event_session_id]=[s].[event_session_id] AND [t].[name]=N'event_file'
                ) THEN 0 ELSE 1 END,[s].[name];
            END;

            IF @ResolvedSessionName IS NOT NULL
            BEGIN
                SELECT @ConfiguredFilePath=MAX(CONVERT(nvarchar(4000),[f].[value]))
                FROM [sys].[server_event_sessions] AS s WITH (NOLOCK)
                JOIN [sys].[server_event_session_targets] AS t WITH (NOLOCK)
                  ON [t].[event_session_id]=[s].[event_session_id] AND [t].[name]=N'event_file'
                LEFT JOIN [sys].[server_event_session_fields] AS f WITH (NOLOCK)
                  ON [f].[event_session_id]=[t].[event_session_id] AND [f].[object_id]=[t].[target_id] AND [f].[name]=N'filename'
                WHERE [s].[name]=@ResolvedSessionName;
            END;
        END TRY
        BEGIN CATCH
            SET @IsPartial=1;
            INSERT [#ExtendedEventsBlockedProcesses_SourceStatus] VALUES('CATALOG',@ResolvedSessionName,NULL,
                CASE WHEN ERROR_NUMBER() IN(229,262,297,300,371) THEN 'DENIED_PERMISSION' ELSE 'ERROR_HANDLED' END,
                ERROR_NUMBER(),ERROR_MESSAGE(),N'Session- oder Pfadermittlung fehlgeschlagen.');
        END CATCH;

        IF @ResolvedSessionName IS NULL AND @FilePath IS NULL
        BEGIN
            SET @StatusCode='AVAILABLE_DISABLED';
            SET @ErrorMessage=N'Keine sichtbare Session mit blocked_process_report gefunden.';
            INSERT [#ExtendedEventsBlockedProcesses_SourceStatus] VALUES('CATALOG',NULL,NULL,@StatusCode,NULL,@ErrorMessage,
                CONCAT(N'blocked process threshold in use = ',COALESCE(CONVERT(nvarchar(20),@BlockedProcessThresholdSeconds),N'unbekannt'),N' Sekunden; das Framework ändert diese Einstellung nicht.'));
        END
        ELSE IF @ResolvedSource='AUTO'
        BEGIN
            IF @FilePath IS NOT NULL OR @ConfiguredFilePath IS NOT NULL SET @ResolvedSource='EVENT_FILE';
            ELSE IF @BestaetigeTargetFlush=1 SET @ResolvedSource='RING_BUFFER';
            ELSE BEGIN SET @StatusCode='AVAILABLE_DISABLED';SET @ErrorMessage=N'Kein event_file-Pfad; Ringbuffer ohne Bestätigung nicht gelesen.';END;
        END;
    END;

    IF @StatusCode='AVAILABLE' AND @ResolvedSource='EVENT_FILE'
    BEGIN
        SET @ResolvedFilePath=COALESCE(NULLIF(@FilePath,N''),NULLIF(@ConfiguredFilePath,N''));
        IF @ResolvedFilePath IS NULL
        BEGIN
            SET @StatusCode='UNAVAILABLE_OBJECT';SET @ErrorMessage=N'Kein event_file-Pfad verfügbar.';
            INSERT [#ExtendedEventsBlockedProcesses_SourceStatus] VALUES('EVENT_FILE',@ResolvedSessionName,NULL,@StatusCode,NULL,@ErrorMessage,N'Keine Datei gelesen.');
        END
        ELSE
        BEGIN
            IF (RIGHT(LOWER(@ResolvedFilePath),4) = N'.xel')
                SET @ResolvedFilePath=LEFT(@ResolvedFilePath,LEN(@ResolvedFilePath)-4)+N'*.xel';
            ELSE IF CHARINDEX(N'*',@ResolvedFilePath)=0
                SET @ResolvedFilePath=@ResolvedFilePath+N'*.xel';
            BEGIN TRY
                INSERT [#ExtendedEventsBlockedProcesses_Raw]
                SELECT TOP (@EffectiveMaxZeilen) 'EVENT_FILE',[r].[timestamp_utc],[r].[file_name],[r].[file_offset],CONVERT([xml],[r].[event_data])
                FROM sys.fn_xe_file_target_read_file(@ResolvedFilePath,NULL,NULL,NULL) AS r
                WHERE [r].[object_name]=N'blocked_process_report'
                  AND (@VonUtc IS NULL OR [r].[timestamp_utc]>=@VonUtc)
                  AND (@BisUtc IS NULL OR [r].[timestamp_utc]<@BisUtc)
                ORDER BY [r].[timestamp_utc] DESC,[r].[file_name] DESC,[r].[file_offset] DESC;
                INSERT [#ExtendedEventsBlockedProcesses_SourceStatus] VALUES('EVENT_FILE',@ResolvedSessionName,@ResolvedFilePath,'AVAILABLE',NULL,NULL,N'blocked_process_report aus XEL gelesen.');
            END TRY
            BEGIN CATCH
                SET @StatusCode=CASE WHEN ERROR_NUMBER() IN(229,262,297,300,371) THEN 'DENIED_PERMISSION' WHEN ERROR_NUMBER()=1222 THEN 'TIMEOUT' WHEN ERROR_NUMBER() IN(6335,6336,6337) THEN 'XML_UNAVAILABLE_LIMIT' WHEN ERROR_NUMBER() BETWEEN 9400 AND 9431 THEN 'XML_INVALID' ELSE 'ERROR_HANDLED' END;
                SET @ErrorNumber=ERROR_NUMBER();SET @ErrorMessage=ERROR_MESSAGE();
                INSERT [#ExtendedEventsBlockedProcesses_SourceStatus] VALUES('EVENT_FILE',@ResolvedSessionName,@ResolvedFilePath,@StatusCode,@ErrorNumber,@ErrorMessage,N'XEL-Datei konnte nicht gelesen werden.');
            END CATCH;
        END;
    END;

    IF @StatusCode='AVAILABLE' AND @ResolvedSource='RING_BUFFER'
    BEGIN
        IF @BestaetigeTargetFlush=0
        BEGIN
            SET @StatusCode='AVAILABLE_DISABLED';SET @ErrorMessage=N'RING_BUFFER erfordert @BestaetigeTargetFlush=1.';
            INSERT [#ExtendedEventsBlockedProcesses_SourceStatus] VALUES('RING_BUFFER',@ResolvedSessionName,NULL,@StatusCode,NULL,@ErrorMessage,N'Targetdaten nicht gelesen.');
        END
        ELSE
        BEGIN
            BEGIN TRY
                SELECT @TargetData=CONVERT([xml],[t].[target_data])
                FROM [sys].[dm_xe_session_targets] AS t WITH (NOLOCK)
                JOIN [sys].[dm_xe_sessions] AS s WITH (NOLOCK) ON [s].[address]=[t].[event_session_address]
                WHERE [s].[name]=@ResolvedSessionName AND [t].[target_name]=N'ring_buffer';
                IF @TargetData IS NULL
                BEGIN
                    SET @StatusCode='UNAVAILABLE_OBJECT';SET @ErrorMessage=N'Kein lesbares laufendes ring_buffer-Target gefunden.';
                    INSERT [#ExtendedEventsBlockedProcesses_SourceStatus] VALUES('RING_BUFFER',@ResolvedSessionName,NULL,@StatusCode,NULL,@ErrorMessage,N'Session gestoppt oder kein Ringbuffer.');
                END
                ELSE
                BEGIN
                    INSERT [#ExtendedEventsBlockedProcesses_Raw]
                    SELECT TOP (@EffectiveMaxZeilen) 'RING_BUFFER',x.e.value('(@timestamp)[1]','datetime2(7)'),NULL,NULL,x.e.query('.')
                    FROM @TargetData.nodes('/RingBufferTarget/event[@name="blocked_process_report"]') AS [x]([e])
                    WHERE (@VonUtc IS NULL OR x.e.value('(@timestamp)[1]','datetime2(7)')>=@VonUtc)
                      AND (@BisUtc IS NULL OR x.e.value('(@timestamp)[1]','datetime2(7)')<@BisUtc)
                    ORDER BY x.e.value('(@timestamp)[1]','datetime2(7)') DESC;
                    INSERT [#ExtendedEventsBlockedProcesses_SourceStatus] VALUES('RING_BUFFER',@ResolvedSessionName,NULL,'AVAILABLE',NULL,NULL,N'Ringbuffer bewusst gelesen; Target-Flush möglich.');
                END;
            END TRY
            BEGIN CATCH
                SET @StatusCode=CASE WHEN ERROR_NUMBER() IN(229,262,297,300,371) THEN 'DENIED_PERMISSION' WHEN ERROR_NUMBER()=1222 THEN 'TIMEOUT' WHEN ERROR_NUMBER() IN(6335,6336,6337) THEN 'XML_UNAVAILABLE_LIMIT' WHEN ERROR_NUMBER() BETWEEN 9400 AND 9431 THEN 'XML_INVALID' ELSE 'ERROR_HANDLED' END;
                SET @ErrorNumber=ERROR_NUMBER();SET @ErrorMessage=ERROR_MESSAGE();
                INSERT [#ExtendedEventsBlockedProcesses_SourceStatus] VALUES('RING_BUFFER',@ResolvedSessionName,NULL,@StatusCode,@ErrorNumber,@ErrorMessage,N'Ringbuffer konnte nicht gelesen werden.');
            END CATCH;
        END;
    END;

    IF @StatusCode='AVAILABLE'
    BEGIN
        INSERT [#ExtendedEventsBlockedProcesses_Reports]([SourceType],[ReportTimeUtc],[FileName],[FileOffset],[ReportXml])
        SELECT [SourceType],[TimestampUtc],[FileName],[FileOffset],
               EventXml.query('(/event/data[@name="blocked_process"]/value/blocked-process-report)[1]')
        FROM [#ExtendedEventsBlockedProcesses_Raw]
        WHERE EventXml.exist('/event/data[@name="blocked_process"]/value/blocked-process-report')=1;

        SELECT @RowCount=COUNT_BIG(*) FROM [#ExtendedEventsBlockedProcesses_Reports];
        IF @RowCount=0
        BEGIN SET @StatusCode='AVAILABLE_LIMITED';SET @IsPartial=1;SET @ErrorMessage=N'Quelle lesbar, aber keine passenden Blocked-Process-Reports gefunden.';END;
    END;

    IF @IsPartial=1 AND @StatusCode='AVAILABLE' SET @StatusCode='AVAILABLE_LIMITED';


    IF @PrintMeldungen=1 AND @StatusCode NOT IN('AVAILABLE','AVAILABLE_LIMITED')
        BEGIN
    SET @MonitorPrintMessage = FORMATMESSAGE(N'WARNUNG USP_ExtendedEventsBlockedProcesses: %s - %s', @StatusCode, COALESCE(@ErrorMessage,N'Keine Details.'));
    RAISERROR(N'%s', 10, 1, @MonitorPrintMessage) WITH NOWAIT;
END;

    CREATE TABLE [#ExtendedEventsBlockedProcesses_ReportSummary]([ReportId] int,[SourceType] varchar(20) COLLATE SQL_Latin1_General_CP1_CS_AS,[ReportTimeUtc] datetime2(7),[FileName] nvarchar(260) COLLATE SQL_Latin1_General_CP1_CS_AS,[FileOffset] bigint,[MonitorLoop] bigint NULL,[BlockedSessionId] int NULL,[BlockingSessionId] int NULL,[WaitTimeMs] bigint NULL,[DatabaseId] int NULL,[DatabaseName] nvarchar(256) COLLATE SQL_Latin1_General_CP1_CS_AS,[WaitResource] nvarchar(1024) COLLATE SQL_Latin1_General_CP1_CS_AS,[RequestedLockMode] nvarchar(64) COLLATE SQL_Latin1_General_CP1_CS_AS,[ReportXml] xml NULL);
    CREATE TABLE [#ExtendedEventsBlockedProcesses_BlockedProcesses]([ReportId] int,[ReportTimeUtc] datetime2(7),[SessionId] int NULL,[ExecutionContextId] int NULL,[ProcessStatus] nvarchar(128) COLLATE SQL_Latin1_General_CP1_CS_AS,[WaitResource] nvarchar(1024) COLLATE SQL_Latin1_General_CP1_CS_AS,[WaitTimeMs] bigint NULL,[LockMode] nvarchar(64) COLLATE SQL_Latin1_General_CP1_CS_AS,[DatabaseId] int NULL,[DatabaseName] nvarchar(256) COLLATE SQL_Latin1_General_CP1_CS_AS,[ClientApplication] nvarchar(512) COLLATE SQL_Latin1_General_CP1_CS_AS,[HostName] nvarchar(512) COLLATE SQL_Latin1_General_CP1_CS_AS,[LoginName] nvarchar(512) COLLATE SQL_Latin1_General_CP1_CS_AS,[InputBuffer] nvarchar(4000) COLLATE SQL_Latin1_General_CP1_CS_AS,[ProcessXml] xml NULL);
    CREATE TABLE [#ExtendedEventsBlockedProcesses_BlockingProcesses]([ReportId] int,[ReportTimeUtc] datetime2(7),[SessionId] int NULL,[ExecutionContextId] int NULL,[ProcessStatus] nvarchar(128) COLLATE SQL_Latin1_General_CP1_CS_AS,[WaitResource] nvarchar(1024) COLLATE SQL_Latin1_General_CP1_CS_AS,[WaitTimeMs] bigint NULL,[LockMode] nvarchar(64) COLLATE SQL_Latin1_General_CP1_CS_AS,[DatabaseId] int NULL,[DatabaseName] nvarchar(256) COLLATE SQL_Latin1_General_CP1_CS_AS,[ClientApplication] nvarchar(512) COLLATE SQL_Latin1_General_CP1_CS_AS,[HostName] nvarchar(512) COLLATE SQL_Latin1_General_CP1_CS_AS,[LoginName] nvarchar(512) COLLATE SQL_Latin1_General_CP1_CS_AS,[InputBuffer] nvarchar(4000) COLLATE SQL_Latin1_General_CP1_CS_AS,[ProcessXml] xml NULL);
    INSERT [#ExtendedEventsBlockedProcesses_ReportSummary] SELECT [r].[ReportId],[r].[SourceType],[r].[ReportTimeUtc],[r].[FileName],[r].[FileOffset],TRY_CONVERT(bigint,[r].[ReportXml].value('(/blocked-process-report/@monitorLoop)[1]','nvarchar(64)')),TRY_CONVERT(int,[r].[ReportXml].value('(/blocked-process-report/blocked-process/process/@spid)[1]','nvarchar(32)')),TRY_CONVERT(int,[r].[ReportXml].value('(/blocked-process-report/blocking-process/process/@spid)[1]','nvarchar(32)')),TRY_CONVERT(bigint,[r].[ReportXml].value('(/blocked-process-report/blocked-process/process/@waittime)[1]','nvarchar(64)')),TRY_CONVERT(int,[r].[ReportXml].value('(/blocked-process-report/blocked-process/process/@currentdb)[1]','nvarchar(32)')),[r].[ReportXml].value('(/blocked-process-report/blocked-process/process/@currentdbname)[1]','nvarchar(256)'),[r].[ReportXml].value('(/blocked-process-report/blocked-process/process/@waitresource)[1]','nvarchar(1024)'),[r].[ReportXml].value('(/blocked-process-report/blocked-process/process/@lockMode)[1]','nvarchar(64)'),CASE WHEN @MitReportXml=1 THEN [r].[ReportXml] END FROM [#ExtendedEventsBlockedProcesses_Reports] [r];
    INSERT [#ExtendedEventsBlockedProcesses_BlockedProcesses] SELECT [r].[ReportId],[r].[ReportTimeUtc],TRY_CONVERT(int,[p].[n].value('(@spid)[1]','nvarchar(32)')),TRY_CONVERT(int,[p].[n].value('(@ecid)[1]','nvarchar(32)')),[p].[n].value('(@status)[1]','nvarchar(128)'),[p].[n].value('(@waitresource)[1]','nvarchar(1024)'),TRY_CONVERT(bigint,[p].[n].value('(@waittime)[1]','nvarchar(64)')),[p].[n].value('(@lockMode)[1]','nvarchar(64)'),TRY_CONVERT(int,[p].[n].value('(@currentdb)[1]','nvarchar(32)')),[p].[n].value('(@currentdbname)[1]','nvarchar(256)'),[p].[n].value('(@clientapp)[1]','nvarchar(512)'),[p].[n].value('(@hostname)[1]','nvarchar(512)'),[p].[n].value('(@loginname)[1]','nvarchar(512)'),[p].[n].value('(inputbuf/text())[1]','nvarchar(4000)'),CASE WHEN @MitProcessXml=1 THEN [p].[n].query('.') END FROM [#ExtendedEventsBlockedProcesses_Reports] [r] CROSS APPLY [r].[ReportXml].nodes('/blocked-process-report/blocked-process/process') [p]([n]);
    INSERT [#ExtendedEventsBlockedProcesses_BlockingProcesses] SELECT [r].[ReportId],[r].[ReportTimeUtc],TRY_CONVERT(int,[p].[n].value('(@spid)[1]','nvarchar(32)')),TRY_CONVERT(int,[p].[n].value('(@ecid)[1]','nvarchar(32)')),[p].[n].value('(@status)[1]','nvarchar(128)'),[p].[n].value('(@waitresource)[1]','nvarchar(1024)'),TRY_CONVERT(bigint,[p].[n].value('(@waittime)[1]','nvarchar(64)')),[p].[n].value('(@lockMode)[1]','nvarchar(64)'),TRY_CONVERT(int,[p].[n].value('(@currentdb)[1]','nvarchar(32)')),[p].[n].value('(@currentdbname)[1]','nvarchar(256)'),[p].[n].value('(@clientapp)[1]','nvarchar(512)'),[p].[n].value('(@hostname)[1]','nvarchar(512)'),[p].[n].value('(@loginname)[1]','nvarchar(512)'),[p].[n].value('(inputbuf/text())[1]','nvarchar(4000)'),CASE WHEN @MitProcessXml=1 THEN [p].[n].query('.') END FROM [#ExtendedEventsBlockedProcesses_Reports] [r] CROSS APPLY [r].[ReportXml].nodes('/blocked-process-report/blocking-process/process') [p]([n]);
    IF @ResultSetArtNormalisiert<>'NONE'
    BEGIN SELECT N'USP_ExtendedEventsBlockedProcesses' [ModuleName],@CollectionTimeUtc [CollectionTimeUtc],@StatusCode [StatusCode],@IsPartial [IsPartial],@RowCount [RowCount],@ResolvedSessionName [SessionName],@ResolvedSource [ResolvedSource],@BlockedProcessThresholdSeconds [BlockedProcessThresholdSeconds],@ErrorNumber [ErrorNumber],@ErrorMessage [ErrorMessage];IF @ResultSetArtNormalisiert='RAW' BEGIN SELECT * FROM [#ExtendedEventsBlockedProcesses_ReportSummary] ORDER BY [ReportTimeUtc] DESC,[ReportId];SELECT * FROM [#ExtendedEventsBlockedProcesses_BlockedProcesses] ORDER BY [ReportTimeUtc] DESC,[ReportId];SELECT * FROM [#ExtendedEventsBlockedProcesses_BlockingProcesses] ORDER BY [ReportTimeUtc] DESC,[ReportId];SELECT * FROM [#ExtendedEventsBlockedProcesses_SourceStatus] ORDER BY [SourceType];END ELSE BEGIN SELECT N'Blocked Process Report' [Ergebnis],[x].* FROM [#ExtendedEventsBlockedProcesses_ReportSummary] [x] ORDER BY [ReportTimeUtc] DESC,[ReportId];SELECT N'Blockierter Prozess' [Ergebnis],[ReportId] [Report],[SessionId] [Session],[WaitTimeMs] [Wait ms],[WaitResource] [Wait-Ressource],[DatabaseName] [Datenbank],[LoginName] [Login],[HostName] [Host],[SessionId] [Session SQL],[InputBuffer] [SQL] FROM [#ExtendedEventsBlockedProcesses_BlockedProcesses] ORDER BY [ReportTimeUtc] DESC,[ReportId];SELECT N'Blockierender Prozess' [Ergebnis],[ReportId] [Report],[SessionId] [Session],[DatabaseName] [Datenbank],[LoginName] [Login],[HostName] [Host],[SessionId] [Session SQL],[InputBuffer] [SQL] FROM [#ExtendedEventsBlockedProcesses_BlockingProcesses] ORDER BY [ReportTimeUtc] DESC,[ReportId];SELECT N'Extended-Events Quelle' [Ergebnis],[x].* FROM [#ExtendedEventsBlockedProcesses_SourceStatus] [x] ORDER BY [SourceType];END;END;
    IF @JsonErzeugen=1 BEGIN DECLARE @Meta nvarchar(max)=(SELECT N'ExtendedEventsBlockedProcesses' [resultName],1 [schemaVersion],@CollectionTimeUtc [generatedAtUtc],@StatusCode [statusCode],@IsPartial [isPartial],@RowCount [returnedRows],@ResolvedSessionName [sessionName],@ResolvedSource [source],@BlockedProcessThresholdSeconds [blockedProcessThresholdSeconds],@ErrorNumber [errorNumber],@ErrorMessage [errorMessage] FOR JSON PATH,WITHOUT_ARRAY_WRAPPER,INCLUDE_NULL_VALUES),@R nvarchar(max)=(SELECT [ReportId],[SourceType],[ReportTimeUtc],[FileName],[FileOffset],[MonitorLoop],[BlockedSessionId],[BlockingSessionId],[WaitTimeMs],[DatabaseId],[DatabaseName],[WaitResource],[RequestedLockMode],CONVERT(nvarchar(max),[ReportXml]) [ReportXml] FROM [#ExtendedEventsBlockedProcesses_ReportSummary] ORDER BY [ReportTimeUtc] DESC,[ReportId] FOR JSON PATH,INCLUDE_NULL_VALUES),@B nvarchar(max)=(SELECT [ReportId],[ReportTimeUtc],[SessionId],[ExecutionContextId],[ProcessStatus],[WaitResource],[WaitTimeMs],[LockMode],[DatabaseId],[DatabaseName],[ClientApplication],[HostName],[LoginName],[InputBuffer],CONVERT(nvarchar(max),[ProcessXml]) [ProcessXml] FROM [#ExtendedEventsBlockedProcesses_BlockedProcesses] ORDER BY [ReportTimeUtc] DESC,[ReportId] FOR JSON PATH,INCLUDE_NULL_VALUES),@G nvarchar(max)=(SELECT [ReportId],[ReportTimeUtc],[SessionId],[ExecutionContextId],[ProcessStatus],[WaitResource],[WaitTimeMs],[LockMode],[DatabaseId],[DatabaseName],[ClientApplication],[HostName],[LoginName],[InputBuffer],CONVERT(nvarchar(max),[ProcessXml]) [ProcessXml] FROM [#ExtendedEventsBlockedProcesses_BlockingProcesses] ORDER BY [ReportTimeUtc] DESC,[ReportId] FOR JSON PATH,INCLUDE_NULL_VALUES),@S nvarchar(max)=(SELECT * FROM [#ExtendedEventsBlockedProcesses_SourceStatus] ORDER BY [SourceType] FOR JSON PATH,INCLUDE_NULL_VALUES);SET @Json=CONCAT(N'{"meta":',COALESCE(@Meta,N'{}'),N',"reports":',COALESCE(@R,N'[]'),N',"blockedProcesses":',COALESCE(@B,N'[]'),N',"blockingProcesses":',COALESCE(@G,N'[]'),N',"sources":',COALESCE(@S,N'[]'),N',"warnings":[]}');END;
    IF @ConsoleResultRequested = 1
    BEGIN
        EXEC [monitor].[InternalEmitConsoleResult]
              @SourceTable=N'#ExtendedEventsBlockedProcesses_ReportSummary'
            , @ResultLabel=N'ExtendedEventsBlockedProcesses'
            , @EmptyMessage=N'Keine fachlichen Ergebnisse';
    END;
    IF @TableResultRequested = 1
    BEGIN
        EXEC [monitor].[InternalWriteResultTable]
              @SourceTable = N'#ExtendedEventsBlockedProcesses_ReportSummary'
            , @TargetTable=@TableTarget
            , @ThrowOnError = 1;
    END;
END;
GO
-- END SOURCE: Code/06_ExtendedEvents/040_USP_ExtendedEventsBlockedProcesses.sql

-- BEGIN SOURCE: Code/06_ExtendedEvents/050_USP_ExtendedEventsTargetRuntime.sql
/*
===============================================================================
Objekt       : monitor.USP_ExtendedEventsTargetRuntime
Version      : 2.0.0
Stand        : 2026-07-15
Typ          : Stored Procedure
Zweck        : Liest Laufzeitmetriken bereits laufender Extended-Events-Targets
               wie execution_count, execution_duration_ms und bytes_written.
               Targetdaten können optional begrenzt ausgegeben werden.
SQL-Version  : SQL Server 2019 oder neuer.
Datenquellen : sys.dm_xe_sessions, sys.dm_xe_session_targets.
Parameter    : @ExtendedEventSessionNamePattern, @TargetNamePattern, @MitTargetData,
               @MaxTargetDataZeichen, @BestaetigeTargetFlush,
               @PrintMeldungen, @Hilfe.
Resultsets   : 1. Modulstatus. 2. Target-Laufzeitdaten.
Berechtigung : SQL 2019 VIEW SERVER STATE; SQL 2022+ VIEW SERVER PERFORMANCE
               STATE oder höher. Das Framework vergibt keine Rechte.
Eigenlast    : Normalerweise gering, kann aber durch große target_data-Inhalte
               sowie einen Target-Flush merkbar werden.
Locking      : LOCK_TIMEOUT 0; keine Benutzerobjekte und keine Änderungen.
Nebenwirkung : Das Lesen von sys.dm_xe_session_targets erzwingt laut Microsoft
               einen Flush gesammelter Sessiondaten zum Target. Daher ist eine
               explizite Bestätigung zwingend.
Partial      : Fehlende Rechte oder gestoppte Sessions werden strukturiert gemeldet.
Beispiele    : EXEC monitor.USP_ExtendedEventsTargetRuntime
                   @ExtendedEventSessionNamePattern=N'system_health', @BestaetigeTargetFlush=1;
               EXEC monitor.USP_ExtendedEventsTargetRuntime @Hilfe=1;
Änderungen   : 1.0.0 - Erstfassung Phase 5.
===============================================================================
*/
CREATE OR ALTER PROCEDURE [monitor].[USP_ExtendedEventsTargetRuntime]
      @ExtendedEventSessionNames       nvarchar(max)  = NULL
    , @ExtendedEventSessionNamePattern nvarchar(4000) = NULL
    , @TargetNames                     nvarchar(max)  = NULL
    , @TargetNamePattern               nvarchar(4000) = NULL
    , @MitTargetData           bit           = 0
    , @MaxTargetDataZeichen    int           = 4000
    , @BestaetigeTargetFlush   bit           = 0
    , @HighImpactConfirmed     bit           = 0
    , @ResultSetArt                   varchar(16)    = 'CONSOLE'
    , @ResultTablesJson               nvarchar(max) = NULL
    , @JsonErzeugen                   bit            = 0
    , @Json                            nvarchar(max)  = NULL OUTPUT
    , @PrintMeldungen          bit           = 1
    , @Hilfe                   bit           = 0
AS
BEGIN
    SET NOCOUNT ON;SET @Json=NULL;DECLARE @ResultSetArtNormalisiert varchar(16)=UPPER(LTRIM(RTRIM(COALESCE(@ResultSetArt,''))));
    DECLARE @TableResultRequested bit = CASE WHEN @ResultSetArtNormalisiert = 'TABLE' THEN 1 ELSE 0 END;
    DECLARE @ConsoleResultRequested bit = CASE WHEN @ResultSetArtNormalisiert = 'CONSOLE' THEN 1 ELSE 0 END;
    DECLARE @TableTarget sysname=NULL;
    IF @TableResultRequested=0 AND NULLIF(LTRIM(RTRIM(COALESCE(@ResultTablesJson,N''))),N'') IS NOT NULL THROW 51011,N'@ResultTablesJson ist ausschließlich mit @ResultSetArt=TABLE zulässig.',1;
    IF @TableResultRequested=1 EXEC [monitor].[InternalPrepareSingleResultTable] @ResultTablesJson=@ResultTablesJson,@ResultName=N'targets',@TargetTable=@TableTarget OUTPUT,@ThrowOnError=1;
    IF @TableResultRequested = 1 OR @ConsoleResultRequested = 1 SET @ResultSetArtNormalisiert = 'NONE';DECLARE @SessionMode varchar(8),@SessionValue nvarchar(4000),@SessionFlags varchar(8),@SessionValid bit,@TargetMode varchar(8),@TargetValue nvarchar(4000),@TargetFlags varchar(8),@TargetValid bit;
    DECLARE @MonitorPrintMessage nvarchar(2048);

    IF @Hilfe=1
    BEGIN
        PRINT N'monitor.USP_ExtendedEventsTargetRuntime';
        PRINT N'@ExtendedEventSessionNamePattern nvarchar(256)=NULL: LIKE-Filter auf laufende Sessionnamen.';
        PRINT N'@TargetNamePattern nvarchar(256)=NULL: LIKE-Filter auf Targetnamen.';
        PRINT N'@MitTargetData bit=0: 1 gibt target_data begrenzt als nvarchar aus.';
        PRINT N'@MaxTargetDataZeichen int=4000: positiver Wert begrenzt die Ausgabe; 0 liefert mit @MitTargetData=1 den vollständigen MAX-Wert.';
        PRINT N'@BestaetigeTargetFlush bit=0: muss 1 sein; sys.dm_xe_session_targets kann einen Target-Flush auslösen.';
        PRINT N'@PrintMeldungen bit=1: Warnungen Severity 10; @Hilfe bit=0: 1 zeigt diese Hilfe.';
        PRINT N'Es werden keine Sessions oder Targets verändert.';
        RETURN;
    END;

    DECLARE @CollectionTimeUtc datetime2(3)=SYSUTCDATETIME(),@StatusCode varchar(40)='AVAILABLE',
            @IsPartial bit=0,@ErrorNumber int=NULL,@ErrorMessage nvarchar(2048)=NULL,@RowCount bigint=0,
            @Allowed bit=1;

    SELECT @SessionMode=[PatternMode],@SessionValue=[PatternValue],@SessionFlags=[RegexFlags],@SessionValid=[IsValid] FROM [monitor].[TVF_ParsePattern](@ExtendedEventSessionNamePattern);
    SELECT @TargetMode=[PatternMode],@TargetValue=[PatternValue],@TargetFlags=[RegexFlags],@TargetValid=[IsValid] FROM [monitor].[TVF_ParsePattern](@TargetNamePattern);
    IF @SessionValid=0 OR @TargetValid=0 OR (@ExtendedEventSessionNames IS NOT NULL AND @ExtendedEventSessionNamePattern IS NOT NULL) OR (@TargetNames IS NOT NULL AND @TargetNamePattern IS NOT NULL) OR (@ExtendedEventSessionNames IS NOT NULL AND EXISTS(SELECT 1 FROM [monitor].[TVF_ParseSqlNameList](@ExtendedEventSessionNames) WHERE [IsValid]=0)) OR (@TargetNames IS NOT NULL AND EXISTS(SELECT 1 FROM [monitor].[TVF_ParseSqlNameList](@TargetNames) WHERE [IsValid]=0)) SET @StatusCode='INVALID_PARAMETER';
    CREATE TABLE [#ExtendedEventsTargetRuntime_Result]
    (
        [SourceType] varchar(32) NOT NULL,
        [SourceObject] nvarchar(256) NOT NULL,
        [CapturedAtUtc] datetime2(3) NOT NULL,
        [EvidenceScope] varchar(40) NOT NULL,
        [IsCurrent] bit NOT NULL,
        [IsCumulative] bit NOT NULL,
        [ValueStatus] varchar(40) NOT NULL,
        [SessionName] nvarchar(256) NOT NULL,
        [TargetName] nvarchar(60) NOT NULL,
        [SessionCreateTime] datetime NULL,
        [ExecutionCount] bigint NOT NULL,
        [ExecutionDurationMs] bigint NOT NULL,
        [BytesWritten] bigint NOT NULL,
        [TargetDataCharacters] bigint NULL,
        [TargetDataBytes] bigint NULL,
        [TargetDataIsTruncated] bit NOT NULL,
        [TargetDataStatus] varchar(40) NOT NULL,
        [TargetData] nvarchar(max) NULL
    );

    IF @MaxTargetDataZeichen < 0 OR @ResultSetArtNormalisiert NOT IN('RAW','CONSOLE','NONE')
    BEGIN SET @StatusCode='INVALID_PARAMETER';SET @ErrorMessage=N'@MaxTargetDataZeichen darf nicht negativ sein; 0 bedeutet unbegrenzt.';END;

    IF @StatusCode='AVAILABLE'
        EXEC [monitor].[InternalCheckAnalysisPath] @AnalysisClass='EXTENDED_EVENTS_FORENSICS_DEEP',@HighImpactConfirmed=@HighImpactConfirmed,@StatusCode=@StatusCode OUTPUT,@ErrorMessage=@ErrorMessage OUTPUT;

    IF @StatusCode='AVAILABLE' AND @BestaetigeTargetFlush=0
    BEGIN
        SET @StatusCode='AVAILABLE_DISABLED';
        SET @ErrorMessage=N'@BestaetigeTargetFlush=1 ist erforderlich. sys.dm_xe_session_targets wurde nicht gelesen.';
    END;

    SET LOCK_TIMEOUT 0;
    IF @StatusCode='AVAILABLE'
    BEGIN
        BEGIN TRY
            INSERT [#ExtendedEventsTargetRuntime_Result]
            SELECT
                'LIVE_DMV',N'sys.dm_xe_session_targets',@CollectionTimeUtc,'SERVER_XE_TARGET',
                CONVERT(bit,1),CONVERT(bit,1),'AVAILABLE',
                [s].[name],[t].[target_name],[s].[create_time],[t].[execution_count],[t].[execution_duration_ms],[t].[bytes_written],
                CASE WHEN @MitTargetData=1 THEN [projection].[OriginalCharacters] END,
                CASE WHEN @MitTargetData=1 THEN [projection].[OriginalBytes] END,
                CONVERT(bit,CASE WHEN @MitTargetData=1 THEN [projection].[IsTruncated] ELSE 0 END),
                CASE WHEN @MitTargetData=0 THEN 'NOT_REQUESTED'
                     WHEN [t].[target_data] IS NULL THEN 'SOURCE_NULL'
                     WHEN [projection].[IsTruncated]=1 THEN 'OUTPUT_VALUE_TRUNCATED'
                     ELSE 'AVAILABLE' END,
                CASE WHEN @MitTargetData=1 THEN [projection].[ProjectedValue] END
            FROM [sys].[dm_xe_session_targets] AS t WITH (NOLOCK)
            JOIN [sys].[dm_xe_sessions] AS s WITH (NOLOCK) ON [s].[address]=[t].[event_session_address]
            CROSS APPLY [monitor].[TVF_ProjectUnicodeText]
            (
                  CONVERT(nvarchar(max),[t].[target_data])
                , @MaxTargetDataZeichen
            ) AS [projection]
            WHERE ((@ExtendedEventSessionNames IS NULL OR EXISTS(SELECT 1 FROM [monitor].[TVF_ParseSqlNameList](@ExtendedEventSessionNames) [sf] WHERE [sf].[IsValid]=1 AND [sf].[NameValue] COLLATE SQL_Latin1_General_CP1_CS_AS=[s].[name] COLLATE SQL_Latin1_General_CP1_CS_AS)) AND (@SessionMode IN('NONE','REGEX','REGEXI') OR [s].[name] COLLATE SQL_Latin1_General_CP1_CS_AS LIKE @SessionValue COLLATE SQL_Latin1_General_CP1_CS_AS))
              AND ((@TargetNames IS NULL OR EXISTS(SELECT 1 FROM [monitor].[TVF_ParseSqlNameList](@TargetNames) [tf] WHERE [tf].[IsValid]=1 AND [tf].[NameValue] COLLATE SQL_Latin1_General_CP1_CS_AS=[t].[target_name] COLLATE SQL_Latin1_General_CP1_CS_AS)) AND (@TargetMode IN('NONE','REGEX','REGEXI') OR [t].[target_name] COLLATE SQL_Latin1_General_CP1_CS_AS LIKE @TargetValue COLLATE SQL_Latin1_General_CP1_CS_AS))
            ORDER BY [s].[name],[t].[target_name];
            SELECT @RowCount=COUNT_BIG(*) FROM [#ExtendedEventsTargetRuntime_Result];
            IF @RowCount=0
            BEGIN SET @StatusCode='AVAILABLE_LIMITED';SET @IsPartial=1;SET @ErrorMessage=N'Keine passenden laufenden Targets gefunden.';END;
        END TRY
        BEGIN CATCH
            SET @StatusCode=CASE WHEN ERROR_NUMBER() IN(229,262,297,300,371) THEN 'DENIED_PERMISSION' WHEN ERROR_NUMBER()=1222 THEN 'TIMEOUT' ELSE 'ERROR_HANDLED' END;
            SET @ErrorNumber=ERROR_NUMBER();SET @ErrorMessage=ERROR_MESSAGE();
        END CATCH;
    END;

    IF @StatusCode='AVAILABLE' AND (@SessionMode IN('REGEX','REGEXI') OR @TargetMode IN('REGEX','REGEXI'))
    BEGIN
      IF TRY_CONVERT(int,SERVERPROPERTY(N'ProductMajorVersion'))<17 OR NOT EXISTS(SELECT 1 FROM [master].[sys].[databases] [d] WITH(NOLOCK) WHERE [d].[database_id]=DB_ID() AND [d].[compatibility_level]>=170) BEGIN SET @StatusCode='UNAVAILABLE_FEATURE';SET @ErrorMessage=N'Regex benötigt SQL Server 2025 und Compatibility Level 170.';END
      ELSE BEGIN DECLARE @FilterSql nvarchar(max)=N'';IF @SessionMode IN('REGEX','REGEXI') SET @FilterSql+=N'DELETE FROM [#ExtendedEventsTargetRuntime_Result] WHERE NOT REGEXP_LIKE([SessionName],@SP,@SF);';IF @TargetMode IN('REGEX','REGEXI') SET @FilterSql+=N'DELETE FROM [#ExtendedEventsTargetRuntime_Result] WHERE NOT REGEXP_LIKE([TargetName],@TP,@TF);';EXEC [sys].[sp_executesql] @FilterSql,N'@SP nvarchar(4000),@SF varchar(8),@TP nvarchar(4000),@TF varchar(8)',@SP=@SessionValue,@SF=@SessionFlags,@TP=@TargetValue,@TF=@TargetFlags;END
    END;
    SELECT @RowCount=COUNT_BIG(*) FROM [#ExtendedEventsTargetRuntime_Result];
    DECLARE @TruncatedValueCount bigint=0,@LargestRequiredCharacters bigint=NULL;
    SELECT @TruncatedValueCount=COUNT_BIG(*),@LargestRequiredCharacters=MAX([TargetDataCharacters])
    FROM [#ExtendedEventsTargetRuntime_Result]
    WHERE [TargetDataIsTruncated]=1;
    EXEC [monitor].[InternalEmitTruncationWarning]
          @TruncatedValueCount=@TruncatedValueCount,@ParameterName=N'@MaxTargetDataZeichen'
        , @ParameterValue=@MaxTargetDataZeichen,@LargestRequiredCharacters=@LargestRequiredCharacters
        , @PrintMeldungen=@PrintMeldungen;
    IF @PrintMeldungen=1 AND @StatusCode NOT IN('AVAILABLE','AVAILABLE_LIMITED')
        BEGIN
    SET @MonitorPrintMessage = FORMATMESSAGE(N'WARNUNG USP_ExtendedEventsTargetRuntime: %s - %s', @StatusCode, COALESCE(@ErrorMessage,N'Keine Details.'));
    RAISERROR(N'%s', 10, 1, @MonitorPrintMessage) WITH NOWAIT;
END;

    IF @ResultSetArtNormalisiert<>'NONE' BEGIN SELECT N'USP_ExtendedEventsTargetRuntime' [ModuleName],@CollectionTimeUtc [CollectionTimeUtc],@StatusCode [StatusCode],@IsPartial [IsPartial],@ErrorNumber [ErrorNumber],@ErrorMessage [ErrorMessage];IF @ResultSetArtNormalisiert='RAW' SELECT * FROM [#ExtendedEventsTargetRuntime_Result] ORDER BY [SessionName],[TargetName];ELSE SELECT N'Extended-Events Target Runtime' [Ergebnis],[SessionName] [Session],[TargetName] [Target],[ExecutionCount] [Ausführungen],[ExecutionDurationMs] [Dauer ms],[TargetDataCharacters] [Targetdaten Zeichen],[TargetDataBytes] [Targetdaten Bytes],[TargetDataIsTruncated] [Targetdaten gekürzt],[TargetData] [Targetdaten] FROM [#ExtendedEventsTargetRuntime_Result] ORDER BY [SessionName],[TargetName];END;
    IF @JsonErzeugen=1 BEGIN DECLARE @Meta nvarchar(max)=(SELECT N'ExtendedEventsTargetRuntime' [resultName],2 [schemaVersion],@CollectionTimeUtc [generatedAtUtc],@StatusCode [statusCode],@IsPartial [isPartial],@ErrorNumber [errorNumber],@ErrorMessage [errorMessage] FOR JSON PATH,WITHOUT_ARRAY_WRAPPER,INCLUDE_NULL_VALUES),@Data nvarchar(max)=(SELECT * FROM [#ExtendedEventsTargetRuntime_Result] ORDER BY [SessionName],[TargetName] FOR JSON PATH,INCLUDE_NULL_VALUES),@Warnings nvarchar(max)=(SELECT 'OUTPUT_VALUE_TRUNCATED' [code],@TruncatedValueCount [truncatedValueCount],N'@MaxTargetDataZeichen' [parameterName],@MaxTargetDataZeichen [parameterValue],@LargestRequiredCharacters [largestRequiredCharacters] WHERE @TruncatedValueCount>0 FOR JSON PATH,INCLUDE_NULL_VALUES);SET @Json=CONCAT(N'{"meta":',COALESCE(@Meta,N'{}'),N',"targets":',COALESCE(@Data,N'[]'),N',"warnings":',COALESCE(@Warnings,N'[]'),N'}');END;
    IF @ConsoleResultRequested = 1
    BEGIN
        EXEC [monitor].[InternalEmitConsoleResult]
              @SourceTable=N'#ExtendedEventsTargetRuntime_Result'
            , @ResultLabel=N'ExtendedEventsTargetRuntime'
            , @EmptyMessage=N'Keine fachlichen Ergebnisse';
    END;
    IF @TableResultRequested = 1
    BEGIN
        EXEC [monitor].[InternalWriteResultTable]
              @SourceTable = N'#ExtendedEventsTargetRuntime_Result'
            , @TargetTable=@TableTarget
            , @ThrowOnError = 1;
    END;
END;
GO
-- END SOURCE: Code/06_ExtendedEvents/050_USP_ExtendedEventsTargetRuntime.sql

-- BEGIN SOURCE: Code/06_ExtendedEvents/060_USP_ExtendedEventsAnalysis.sql
/*
===============================================================================
Objekt       : monitor.USP_ExtendedEventsAnalysis
Version      : 2.0.1
Stand        : 2026-07-16
Zweck        : Orchestriert Extended-Events-Inventar und Forensik mit
               einheitlichem Ausgabe- und Namensvertrag.
Änderungen   : 2.0.1 - IF/TRY/CATCH-Blöcke syntaktisch eindeutig strukturiert.
===============================================================================
*/
CREATE OR ALTER PROCEDURE [monitor].[USP_ExtendedEventsAnalysis]
      @SourceExtendedEventSessionName nvarchar(258)  = N'system_health'
    , @ExtendedEventSessionNames       nvarchar(max)  = NULL
    , @ExtendedEventSessionNamePattern nvarchar(4000) = NULL
    , @EventNames                      nvarchar(max)  = NULL
    , @EventNamePattern                nvarchar(4000) = NULL
    , @TargetNames                     nvarchar(max)  = NULL
    , @TargetNamePattern               nvarchar(4000) = NULL
    , @Quelle                          varchar(20)    = 'AUTO'
    , @FilePath                        nvarchar(4000) = NULL
    , @VonUtc                          datetime2(7)   = NULL
    , @BisUtc                          datetime2(7)   = NULL
    , @MitSessionInventar              bit            = 1
    , @MitTargetRuntime                bit            = 0
    , @MitEvents                       bit            = 0
    , @MitDeadlocks                    bit            = 0
    , @MitBlockedProcesses             bit            = 0
    , @MaxZeilen                       int            = 100
    , @BestaetigeTargetFlush           bit            = 0
    , @HighImpactConfirmed             bit            = 0
    , @ResultSetArt                    varchar(16)    = 'CONSOLE'
    , @ResultTablesJson               nvarchar(max) = NULL
    , @JsonErzeugen                    bit            = 0
    , @Json                            nvarchar(max)  = NULL OUTPUT
    , @PrintMeldungen                  bit            = 1
    , @Hilfe                           bit            = 0
AS
BEGIN
    SET NOCOUNT ON;
    SET LOCK_TIMEOUT 0;
    SET @Json = NULL;

    DECLARE @OutputMode varchar(16) = UPPER(LTRIM(RTRIM(COALESCE(@ResultSetArt, ''))));
    DECLARE @TableResultRequested bit = CASE WHEN @OutputMode = 'TABLE' THEN 1 ELSE 0 END;
    DECLARE @ConsoleResultRequested bit = CASE WHEN @OutputMode = 'CONSOLE' THEN 1 ELSE 0 END;
    DECLARE @TableTarget sysname=NULL;
    IF @TableResultRequested=0 AND NULLIF(LTRIM(RTRIM(COALESCE(@ResultTablesJson,N''))),N'') IS NOT NULL THROW 51011,N'@ResultTablesJson ist ausschließlich mit @ResultSetArt=TABLE zulässig.',1;
    IF @TableResultRequested=1 EXEC [monitor].[InternalPrepareSingleResultTable] @ResultTablesJson=@ResultTablesJson,@ResultName=N'moduleStatus',@TargetTable=@TableTarget OUTPUT,@ThrowOnError=1;
    IF @TableResultRequested = 1 OR @ConsoleResultRequested = 1 SET @OutputMode = 'NONE';
    DECLARE @Source varchar(20) = UPPER(LTRIM(RTRIM(COALESCE(@Quelle, ''))));
    DECLARE @Now datetime2(3) = SYSUTCDATETIME();
    DECLARE @StatusCode varchar(40) = 'AVAILABLE';
    DECLARE @InventoryJson nvarchar(max);
    DECLARE @TargetJson nvarchar(max);
    DECLARE @EventsJson nvarchar(max);
    DECLARE @DeadlocksJson nvarchar(max);
    DECLARE @BlockedJson nvarchar(max);

    DECLARE @ModuleStatus TABLE
    (
          [ExecutionOrdinal] tinyint        NOT NULL
        , [ModuleName]       sysname        NOT NULL
        , [InvocationStatus] varchar(40)    NOT NULL
        , [ErrorNumber]      int            NULL
        , [ErrorMessage]     nvarchar(2048) NULL
    );

    IF @Hilfe = 1
    BEGIN
        PRINT N'monitor.USP_ExtendedEventsAnalysis';
        PRINT N'Inventarfilter sind listen-/patternfähig; die forensische Quellsession ist ein einzelner optional geklammerter Name.';
        PRINT N'@ResultSetArt = RAW, CONSOLE, TABLE oder NONE; optional JSON über @Json OUTPUT.';
        RETURN;
    END;

    IF @MaxZeilen < 0
       OR @OutputMode NOT IN ('RAW', 'CONSOLE', 'NONE')
       OR @Source NOT IN ('AUTO', 'EVENT_FILE', 'RING_BUFFER')
       OR (@VonUtc IS NOT NULL AND @BisUtc IS NOT NULL AND @VonUtc > @BisUtc)
       OR (@MitSessionInventar = 0 AND @MitTargetRuntime = 0 AND @MitEvents = 0
           AND @MitDeadlocks = 0 AND @MitBlockedProcesses = 0)
    BEGIN
        SET @StatusCode = 'INVALID_PARAMETER';
    END;

    IF @StatusCode = 'AVAILABLE' AND @MitSessionInventar = 1
    BEGIN
        BEGIN TRY
            EXEC [monitor].[USP_ExtendedEventsSessions]
                  @ExtendedEventSessionNames = @ExtendedEventSessionNames
                , @ExtendedEventSessionNamePattern = @ExtendedEventSessionNamePattern
                , @EventNames = @EventNames
                , @EventNamePattern = @EventNamePattern
                , @TargetNames = @TargetNames
                , @TargetNamePattern = @TargetNamePattern
                , @MaxZeilen = @MaxZeilen
                , @ResultSetArt = @OutputMode
                , @JsonErzeugen = @JsonErzeugen
                , @Json = @InventoryJson OUTPUT
                , @PrintMeldungen = @PrintMeldungen;

            INSERT @ModuleStatus VALUES (1, N'USP_ExtendedEventsSessions', 'EXECUTED', NULL, NULL);
        END TRY
        BEGIN CATCH
            INSERT @ModuleStatus VALUES (1, N'USP_ExtendedEventsSessions', 'ERROR_HANDLED', ERROR_NUMBER(), ERROR_MESSAGE());
        END CATCH;
    END;

    IF @StatusCode = 'AVAILABLE' AND @MitTargetRuntime = 1
    BEGIN
        BEGIN TRY
            EXEC [monitor].[USP_ExtendedEventsTargetRuntime]
                  @ExtendedEventSessionNames = @ExtendedEventSessionNames
                , @ExtendedEventSessionNamePattern = @ExtendedEventSessionNamePattern
                , @TargetNames = @TargetNames
                , @TargetNamePattern = @TargetNamePattern
                , @BestaetigeTargetFlush = @BestaetigeTargetFlush
                , @HighImpactConfirmed = @HighImpactConfirmed
                , @ResultSetArt = @OutputMode
                , @JsonErzeugen = @JsonErzeugen
                , @Json = @TargetJson OUTPUT
                , @PrintMeldungen = @PrintMeldungen;

            INSERT @ModuleStatus VALUES (2, N'USP_ExtendedEventsTargetRuntime', 'EXECUTED', NULL, NULL);
        END TRY
        BEGIN CATCH
            INSERT @ModuleStatus VALUES (2, N'USP_ExtendedEventsTargetRuntime', 'ERROR_HANDLED', ERROR_NUMBER(), ERROR_MESSAGE());
        END CATCH;
    END;

    IF @StatusCode = 'AVAILABLE' AND @MitEvents = 1
    BEGIN
        BEGIN TRY
            EXEC [monitor].[USP_ExtendedEventsReadEvents]
                  @SourceExtendedEventSessionName = @SourceExtendedEventSessionName
                , @Quelle = @Source
                , @FilePath = @FilePath
                , @EventNames = @EventNames
                , @EventNamePattern = @EventNamePattern
                , @VonUtc = @VonUtc
                , @BisUtc = @BisUtc
                , @MaxZeilen = @MaxZeilen
                , @BestaetigeTargetFlush = @BestaetigeTargetFlush
                , @HighImpactConfirmed = @HighImpactConfirmed
                , @ResultSetArt = @OutputMode
                , @JsonErzeugen = @JsonErzeugen
                , @Json = @EventsJson OUTPUT
                , @PrintMeldungen = @PrintMeldungen;

            INSERT @ModuleStatus VALUES (3, N'USP_ExtendedEventsReadEvents', 'EXECUTED', NULL, NULL);
        END TRY
        BEGIN CATCH
            INSERT @ModuleStatus VALUES (3, N'USP_ExtendedEventsReadEvents', 'ERROR_HANDLED', ERROR_NUMBER(), ERROR_MESSAGE());
        END CATCH;
    END;

    IF @StatusCode = 'AVAILABLE' AND @MitDeadlocks = 1
    BEGIN
        BEGIN TRY
            EXEC [monitor].[USP_ExtendedEventsDeadlocks]
                  @SourceExtendedEventSessionName = @SourceExtendedEventSessionName
                , @Quelle = @Source
                , @FilePath = @FilePath
                , @VonUtc = @VonUtc
                , @BisUtc = @BisUtc
                , @MaxZeilen = @MaxZeilen
                , @BestaetigeTargetFlush = @BestaetigeTargetFlush
                , @HighImpactConfirmed = @HighImpactConfirmed
                , @ResultSetArt = @OutputMode
                , @JsonErzeugen = @JsonErzeugen
                , @Json = @DeadlocksJson OUTPUT
                , @PrintMeldungen = @PrintMeldungen;

            INSERT @ModuleStatus VALUES (4, N'USP_ExtendedEventsDeadlocks', 'EXECUTED', NULL, NULL);
        END TRY
        BEGIN CATCH
            INSERT @ModuleStatus VALUES (4, N'USP_ExtendedEventsDeadlocks', 'ERROR_HANDLED', ERROR_NUMBER(), ERROR_MESSAGE());
        END CATCH;
    END;

    IF @StatusCode = 'AVAILABLE' AND @MitBlockedProcesses = 1
    BEGIN
        BEGIN TRY
            EXEC [monitor].[USP_ExtendedEventsBlockedProcesses]
                  @SourceExtendedEventSessionName = @SourceExtendedEventSessionName
                , @Quelle = @Source
                , @FilePath = @FilePath
                , @VonUtc = @VonUtc
                , @BisUtc = @BisUtc
                , @MaxZeilen = @MaxZeilen
                , @BestaetigeTargetFlush = @BestaetigeTargetFlush
                , @HighImpactConfirmed = @HighImpactConfirmed
                , @ResultSetArt = @OutputMode
                , @JsonErzeugen = @JsonErzeugen
                , @Json = @BlockedJson OUTPUT
                , @PrintMeldungen = @PrintMeldungen;

            INSERT @ModuleStatus VALUES (5, N'USP_ExtendedEventsBlockedProcesses', 'EXECUTED', NULL, NULL);
        END TRY
        BEGIN CATCH
            INSERT @ModuleStatus VALUES (5, N'USP_ExtendedEventsBlockedProcesses', 'ERROR_HANDLED', ERROR_NUMBER(), ERROR_MESSAGE());
        END CATCH;
    END;

    IF EXISTS (SELECT 1 FROM @ModuleStatus WHERE [InvocationStatus] <> 'EXECUTED')
       AND @StatusCode = 'AVAILABLE'
    BEGIN
        SET @StatusCode = 'AVAILABLE_LIMITED';
    END;

    IF @OutputMode <> 'NONE'
    BEGIN
        SELECT
              N'USP_ExtendedEventsAnalysis' AS [ModuleName]
            , @Now                         AS [CollectionTimeUtc]
            , @StatusCode                  AS [StatusCode]
            , CONVERT(bit, CASE WHEN @StatusCode = 'AVAILABLE' THEN 0 ELSE 1 END) AS [IsPartial]
            , (SELECT COUNT_BIG(*) FROM @ModuleStatus) AS [ModuleCount];

        IF @OutputMode = 'RAW'
        BEGIN
            SELECT * FROM @ModuleStatus ORDER BY [ExecutionOrdinal];
        END
        ELSE
        BEGIN
            SELECT
                  N'Extended-Events Teilmodul' AS [Ergebnis]
                , [ExecutionOrdinal]           AS [Reihenfolge]
                , [ModuleName]                 AS [Modul]
                , [InvocationStatus]           AS [Status]
                , [ErrorMessage]               AS [Fehler]
            FROM @ModuleStatus
            ORDER BY [ExecutionOrdinal];
        END;
    END;

    IF @JsonErzeugen = 1
    BEGIN
        DECLARE @Meta nvarchar(max);
        DECLARE @Warnings nvarchar(max);

        SELECT @Meta =
        (
            SELECT
                  N'ExtendedEventsAnalysis' AS [resultName]
                , 1                         AS [schemaVersion]
                , @Now                      AS [generatedAtUtc]
                , @StatusCode               AS [statusCode]
            FOR JSON PATH, WITHOUT_ARRAY_WRAPPER
        );

        SELECT @Warnings =
        (
            SELECT *
            FROM @ModuleStatus
            WHERE [InvocationStatus] <> 'EXECUTED'
            ORDER BY [ExecutionOrdinal]
            FOR JSON PATH, INCLUDE_NULL_VALUES
        );

        SET @Json = CONCAT
        (
              N'{"meta":', COALESCE(@Meta, N'{}')
            , N',"inventory":', COALESCE(JSON_QUERY(@InventoryJson), N'null')
            , N',"targetRuntime":', COALESCE(JSON_QUERY(@TargetJson), N'null')
            , N',"events":', COALESCE(JSON_QUERY(@EventsJson), N'null')
            , N',"deadlocks":', COALESCE(JSON_QUERY(@DeadlocksJson), N'null')
            , N',"blockedProcesses":', COALESCE(JSON_QUERY(@BlockedJson), N'null')
            , N',"warnings":', COALESCE(@Warnings, N'[]')
            , N'}'
        );
    END;
    IF @ConsoleResultRequested = 1
    BEGIN
        EXEC [monitor].[InternalEmitConsoleResult]
              @SourceTable=N'#ExtendedEventsAnalysis_MonitorTableResult'
            , @ResultLabel=N'ExtendedEventsAnalysis'
            , @EmptyMessage=N'Keine fachlichen Ergebnisse';
    END;
    IF @TableResultRequested = 1
    BEGIN
        SELECT * INTO [#ExtendedEventsAnalysis_MonitorTableResult] FROM @ModuleStatus;
        EXEC [monitor].[InternalWriteResultTable]
              @SourceTable = N'#ExtendedEventsAnalysis_MonitorTableResult'
            , @TargetTable=@TableTarget
            , @ThrowOnError = 1;
    END;
END;
GO
-- END SOURCE: Code/06_ExtendedEvents/060_USP_ExtendedEventsAnalysis.sql

-- BEGIN SOURCE: Code/07_Infrastructure/010_USP_AgentStatus.sql
/*
===============================================================================
Objekt       : monitor.USP_AgentStatus
Version      : 2.0.0
Stand        : 2026-07-15
Typ          : Stored Procedure
Zweck        : Ermittelt SQL-Server-Agent-Dienststatus, Agent-Startzeit und Basisinventar.
SQL-Version  : SQL Server 2019 oder neuer.
Datenquellen : sys.dm_server_services, msdb.dbo.syssessions, msdb.dbo.sysjobs
Parameter    : @ResultSetArt, @JsonErzeugen, @Json OUTPUT, @PrintMeldungen, @Hilfe
Resultsets   : RAW oder CONSOLE: Modulstatus und Agentstatus. NONE: keine Resultsets.
JSON         : meta, agentStatus.
Berechtigung : Nur lesender Zugriff. Das Framework vergibt keine Rechte.
Eigenlast    : Gering.
Locking      : LOCK_TIMEOUT 0; keine fachlichen Schreibzugriffe.
Änderungen   : 2.0.0 - Einheitlicher RAW/CONSOLE/NONE- und JSON-Vertrag.
               1.0.0 - Erstfassung Phase 6.
===============================================================================
*/
CREATE OR ALTER PROCEDURE [monitor].[USP_AgentStatus]
      @ResultSetArt   varchar(16)    = 'CONSOLE'
    , @ResultTablesJson               nvarchar(max) = NULL
    , @JsonErzeugen   bit            = 0
    , @Json           nvarchar(max)  = NULL OUTPUT
    , @PrintMeldungen bit            = 1
    , @Hilfe          bit            = 0
AS
BEGIN
    SET NOCOUNT ON;

    SET @Json = NULL;

    DECLARE @ResultSetArtNormalisiert varchar(16) =
        UPPER(LTRIM(RTRIM(COALESCE(@ResultSetArt, ''))));
    DECLARE @TableResultRequested bit = CASE WHEN @ResultSetArtNormalisiert = 'TABLE' THEN 1 ELSE 0 END;
    DECLARE @ConsoleResultRequested bit = CASE WHEN @ResultSetArtNormalisiert = 'CONSOLE' THEN 1 ELSE 0 END;
    DECLARE @TableTarget sysname=NULL;
    IF @TableResultRequested=0 AND NULLIF(LTRIM(RTRIM(COALESCE(@ResultTablesJson,N''))),N'') IS NOT NULL THROW 51011,N'@ResultTablesJson ist ausschließlich mit @ResultSetArt=TABLE zulässig.',1;
    IF @TableResultRequested=1 EXEC [monitor].[InternalPrepareSingleResultTable] @ResultTablesJson=@ResultTablesJson,@ResultName=N'agentStatus',@TargetTable=@TableTarget OUTPUT,@ThrowOnError=1;
    IF @TableResultRequested = 1 OR @ConsoleResultRequested = 1 SET @ResultSetArtNormalisiert = 'NONE';

    IF @Hilfe = 1
    BEGIN
        PRINT N'monitor.USP_AgentStatus';
        PRINT N'@ResultSetArt: CONSOLE (Default), RAW, TABLE oder NONE; der Steuerwert wird case-insensitiv verarbeitet.';
        PRINT N'@JsonErzeugen=1 setzt @Json OUTPUT mit meta und agentStatus.';
        PRINT N'@PrintMeldungen bit=1; @Hilfe bit=0.';
        PRINT N'Nur lesend; der SQL Server Agent wird weder gestartet noch gestoppt.';
        RETURN;
    END;

    DECLARE @CollectionTimeUtc datetime2(3) = SYSUTCDATETIME();
    DECLARE @StatusCode varchar(40) = 'AVAILABLE';
    DECLARE @IsPartial bit = 0;
    DECLARE @ErrorNumber int = NULL;
    DECLARE @ErrorMessage nvarchar(2048) = NULL;

    CREATE TABLE [#AgentStatus_AgentStatus]
    (
          [ServiceName]        nvarchar(256) NULL
        , [StartupTypeDesc]    nvarchar(60)  NULL
        , [StatusDesc]         nvarchar(60)  NULL
        , [ProcessId]          int           NULL
        , [LastStartupTime]    datetime2(3)  NULL
        , [AgentSessionId]     int           NULL
        , [JobCount]           int           NULL
        , [EnabledJobCount]    int           NULL
    );

    IF @ResultSetArtNormalisiert NOT IN ('RAW', 'CONSOLE', 'NONE')
    BEGIN
        SET @StatusCode = 'INVALID_PARAMETER';
        SET @IsPartial = 1;
        SET @ErrorMessage = N'@ResultSetArt muss CONSOLE, RAW, TABLE oder NONE enthalten.';
    END;

    SET LOCK_TIMEOUT 0;

    IF @StatusCode = 'AVAILABLE'
    BEGIN TRY
        INSERT [#AgentStatus_AgentStatus]
        (
              [ServiceName], [StartupTypeDesc], [StatusDesc], [ProcessId]
            , [LastStartupTime], [AgentSessionId], [JobCount], [EnabledJobCount]
        )
        SELECT TOP (1)
              [s].[servicename]
            , [s].[startup_type_desc]
            , [s].[status_desc]
            , [s].[process_id]
            , (SELECT MAX([agent_start_date]) FROM [msdb].[dbo].[syssessions] WITH (NOLOCK))
            , (SELECT MAX([session_id]) FROM [msdb].[dbo].[syssessions] WITH (NOLOCK))
            , (SELECT COUNT_BIG(*) FROM [msdb].[dbo].[sysjobs] WITH (NOLOCK))
            , (SELECT COUNT_BIG(*) FROM [msdb].[dbo].[sysjobs] WITH (NOLOCK) WHERE [enabled] = 1)
        FROM [sys].[dm_server_services] AS [s] WITH (NOLOCK)
        WHERE [s].[servicename] LIKE N'SQL Server Agent%'
        ORDER BY [s].[servicename];

        IF NOT EXISTS (SELECT 1 FROM [#AgentStatus_AgentStatus])
        BEGIN
            SET @StatusCode = 'UNAVAILABLE_FEATURE';
            SET @IsPartial = 1;
            SET @ErrorMessage = N'Kein sichtbarer SQL-Server-Agent-Dienst gefunden.';
        END;
    END TRY
    BEGIN CATCH
        SELECT
              @StatusCode = 'ERROR_HANDLED'
            , @IsPartial = 1
            , @ErrorNumber = ERROR_NUMBER()
            , @ErrorMessage = ERROR_MESSAGE();

        IF @PrintMeldungen = 1
            RAISERROR(N'Agentstatus konnte nicht vollständig gelesen werden: %s', 10, 1, @ErrorMessage) WITH NOWAIT;
    END CATCH;

    IF @ResultSetArtNormalisiert <> 'NONE'
    BEGIN
        SELECT
              @CollectionTimeUtc AS [CollectionTimeUtc]
            , CAST(N'monitor.USP_AgentStatus' AS nvarchar(256)) AS [ModuleName]
            , @StatusCode AS [StatusCode]
            , @IsPartial AS [IsPartial]
            , @ErrorNumber AS [ErrorNumber]
            , @ErrorMessage AS [ErrorMessage];

        IF @ResultSetArtNormalisiert = 'RAW'
        BEGIN
            SELECT
                  [ServiceName], [StartupTypeDesc], [StatusDesc], [ProcessId]
                , [LastStartupTime], [AgentSessionId], [JobCount], [EnabledJobCount]
            FROM [#AgentStatus_AgentStatus];
        END;
        ELSE
        BEGIN
            SELECT
                  N'SQL Server Agent' AS [Ergebnis]
                , [ServiceName] AS [Dienst]
                , [StartupTypeDesc] AS [Starttyp]
                , [StatusDesc] AS [Dienststatus]
                , [ProcessId] AS [Prozess-ID]
                , [LastStartupTime] AS [Letzter Agent-Start]
                , [AgentSessionId] AS [Agent-Session]
                , [JobCount] AS [Jobs gesamt]
                , [EnabledJobCount] AS [Aktive Jobs]
            FROM [#AgentStatus_AgentStatus];
        END;
    END;

    IF @JsonErzeugen = 1
    BEGIN
        DECLARE @MetaJson nvarchar(max) =
        (
            SELECT
                  N'AgentStatus' AS [resultName]
                , 1 AS [schemaVersion]
                , @CollectionTimeUtc AS [generatedAtUtc]
                , @StatusCode AS [statusCode]
                , @IsPartial AS [isPartial]
                , @ErrorNumber AS [errorNumber]
                , @ErrorMessage AS [errorMessage]
            FOR JSON PATH, WITHOUT_ARRAY_WRAPPER, INCLUDE_NULL_VALUES
        );

        DECLARE @DataJson nvarchar(max) =
        (
            SELECT
                  [ServiceName], [StartupTypeDesc], [StatusDesc], [ProcessId]
                , [LastStartupTime], [AgentSessionId], [JobCount], [EnabledJobCount]
            FROM [#AgentStatus_AgentStatus]
            FOR JSON PATH, INCLUDE_NULL_VALUES
        );

        SET @Json = CONCAT
        (
              N'{"meta":', COALESCE(@MetaJson, N'{}')
            , N',"agentStatus":', COALESCE(@DataJson, N'[]')
            , N'}'
        );
    END;
    IF @ConsoleResultRequested = 1
    BEGIN
        EXEC [monitor].[InternalEmitConsoleResult]
              @SourceTable=N'#AgentStatus_AgentStatus'
            , @ResultLabel=N'AgentStatus'
            , @EmptyMessage=N'Keine fachlichen Ergebnisse';
    END;
    IF @TableResultRequested = 1
    BEGIN
        EXEC [monitor].[InternalWriteResultTable]
              @SourceTable = N'#AgentStatus_AgentStatus'
            , @TargetTable=@TableTarget
            , @ThrowOnError = 1;
    END;
END;
GO
-- END SOURCE: Code/07_Infrastructure/010_USP_AgentStatus.sql

-- BEGIN SOURCE: Code/07_Infrastructure/020_USP_AgentJobs.sql
/*
===============================================================================
Objekt       : monitor.USP_AgentJobs
Version      : 2.0.0
Stand        : 2026-07-15
Typ          : Stored Procedure
Zweck        : Analysiert Agent-Jobs, Laufzeitstatus, letzte Ausführung, Fehler,
               Schedules und Owner.
SQL-Version  : SQL Server 2019 oder neuer.
Filter       : @JobNames als bracket-aware Pipe-Liste oder alternativ
               @JobNamePattern mit LIKE/regex/regexi.
Resultsets   : RAW oder CONSOLE: Modulstatus, Jobs, Jobsteps. NONE: keine.
JSON         : meta, jobs, steps.
Änderungen   : 2.0.0 - Mehrfachfilter, Patternvertrag und Ausgabeadapter.
               1.0.0 - Erstfassung Phase 6.
===============================================================================
*/
CREATE OR ALTER PROCEDURE [monitor].[USP_AgentJobs]
      @JobNames          nvarchar(max)  = NULL
    , @JobNamePattern    nvarchar(4000) = NULL
    , @NurProblematisch  bit            = 0
    , @LongRunningMinutes int           = 60
    , @MaxZeilen         int            = 2000
    , @ResultSetArt      varchar(16)    = 'CONSOLE'
    , @ResultTablesJson               nvarchar(max) = NULL
    , @JsonErzeugen      bit            = 0
    , @Json              nvarchar(max)  = NULL OUTPUT
    , @PrintMeldungen    bit            = 1
    , @Hilfe             bit            = 0
AS
BEGIN
    SET NOCOUNT ON;

    SET @Json = NULL;

    DECLARE @ResultSetArtNormalisiert varchar(16) = UPPER(LTRIM(RTRIM(COALESCE(@ResultSetArt, ''))));
    DECLARE @TableResultRequested bit = CASE WHEN @ResultSetArtNormalisiert = 'TABLE' THEN 1 ELSE 0 END;
    DECLARE @ConsoleResultRequested bit = CASE WHEN @ResultSetArtNormalisiert = 'CONSOLE' THEN 1 ELSE 0 END;
    DECLARE @TableTarget sysname=NULL;
    IF @TableResultRequested=0 AND NULLIF(LTRIM(RTRIM(COALESCE(@ResultTablesJson,N''))),N'') IS NOT NULL THROW 51011,N'@ResultTablesJson ist ausschließlich mit @ResultSetArt=TABLE zulässig.',1;
    IF @TableResultRequested=1 EXEC [monitor].[InternalPrepareSingleResultTable] @ResultTablesJson=@ResultTablesJson,@ResultName=N'jobs',@TargetTable=@TableTarget OUTPUT,@ThrowOnError=1;
    IF @TableResultRequested = 1 OR @ConsoleResultRequested = 1 SET @ResultSetArtNormalisiert = 'NONE';
    DECLARE @PatternMode varchar(8);
    DECLARE @PatternValue nvarchar(4000);
    DECLARE @RegexFlags varchar(8);
    DECLARE @PatternIsValid bit;
    DECLARE @EffectiveMaxZeilen bigint =
        CASE WHEN @MaxZeilen IS NULL OR @MaxZeilen = 0
             THEN CONVERT(bigint, 9223372036854775807)
             ELSE CONVERT(bigint, @MaxZeilen) END;

    SELECT
          @PatternMode = [PatternMode]
        , @PatternValue = [PatternValue]
        , @RegexFlags = [RegexFlags]
        , @PatternIsValid = [IsValid]
    FROM [monitor].[TVF_ParsePattern](@JobNamePattern);

    IF @Hilfe = 1
    BEGIN
        PRINT N'monitor.USP_AgentJobs';
        PRINT N'@JobNames: exakter Jobname oder bracket-aware Pipe-Liste, zum Beispiel N''[DWH Load]|[Index Maintenance]''.';
        PRINT N'@JobNamePattern: genau ein LIKE-/Regex-Pattern; exakte Liste und Pattern sind gegenseitig exklusiv.';
        PRINT N'@NurProblematisch bit=0; @LongRunningMinutes int=60.';
        PRINT N'@MaxZeilen: positive Werte begrenzen; NULL/0 = unbegrenzt.';
        PRINT N'@ResultSetArt=CONSOLE (Default)|RAW|TABLE|NONE case-insensitiv; @JsonErzeugen=1 setzt @Json OUTPUT.';
        RETURN;
    END;

    DECLARE @CollectionTimeUtc datetime2(3) = SYSUTCDATETIME();
    DECLARE @StatusCode varchar(40) = 'AVAILABLE';
    DECLARE @IsPartial bit = 0;
    DECLARE @ErrorNumber int = NULL;
    DECLARE @ErrorMessage nvarchar(2048) = NULL;

    CREATE TABLE [#AgentJobs_JobNameFilter]
    (
          [ItemOrdinal] int NOT NULL
        , [JobName] sysname COLLATE SQL_Latin1_General_CP1_CS_AS NOT NULL
        , CONSTRAINT [PK_JobNameFilter] PRIMARY KEY ([JobName])
    );

    CREATE TABLE [#AgentJobs_Jobs]
    (
          [JobId] uniqueidentifier
        , [JobName] sysname
        , [Enabled] bit
        , [OwnerName] sysname
        , [CategoryName] sysname
        , [IsRunning] bit
        , [RunStart] datetime
        , [RunningMinutes] int
        , [LastRunDateTime] datetime
        , [LastRunStatus] int
        , [LastRunStatusDesc] nvarchar(60)
        , [LastRunDurationSeconds] int
        , [LastMessage] nvarchar(4000)
        , [ScheduleCount] int
        , [EnabledScheduleCount] int
        , [StepCount] int
        , [ProblemCode] varchar(100)
    );

    CREATE TABLE [#AgentJobs_Steps]
    (
          [JobName] sysname
        , [StepId] int
        , [StepName] sysname
        , [Subsystem] nvarchar(40)
        , [LastRunOutcome] int
        , [LastRunOutcomeDesc] nvarchar(60)
        , [LastRunDateTime] datetime
        , [LastRunDurationSeconds] int
        , [LastRunRetries] int
        , [LastRunMessage] nvarchar(4000)
    );

    IF @JobNames IS NOT NULL
    BEGIN
        INSERT [#AgentJobs_JobNameFilter]([ItemOrdinal], [JobName])
        SELECT [ItemOrdinal], [NameValue]
        FROM [monitor].[TVF_ParseSqlNameList](@JobNames)
        WHERE [IsValid] = 1;
    END;

    IF @MaxZeilen < 0
       OR @LongRunningMinutes < 1
       OR @ResultSetArtNormalisiert NOT IN ('RAW', 'CONSOLE', 'NONE')
       OR @PatternIsValid = 0
       OR (@JobNames IS NOT NULL AND @JobNamePattern IS NOT NULL)
       OR (@JobNames IS NOT NULL AND EXISTS
          (SELECT 1 FROM [monitor].[TVF_ParseSqlNameList](@JobNames) WHERE [IsValid] = 0))
    BEGIN
        SET @StatusCode = 'INVALID_PARAMETER';
        SET @IsPartial = 1;
        SET @ErrorMessage = N'Ungültige Filter-, Grenzwert- oder Ausgabeparameter.';
    END;

    IF @StatusCode = 'AVAILABLE'
       AND @PatternMode IN ('REGEX', 'REGEXI')
       AND
       (
           TRY_CONVERT(int, SERVERPROPERTY(N'ProductMajorVersion')) < 17
           OR NOT EXISTS
              (
                  SELECT 1
                  FROM [master].[sys].[databases] AS [d] WITH (NOLOCK)
                  WHERE [d].[database_id] = DB_ID()
                    AND [d].[compatibility_level] >= 170
              )
       )
    BEGIN
        SET @StatusCode = 'UNAVAILABLE_FEATURE';
        SET @IsPartial = 1;
        SET @ErrorMessage = N'Regex benötigt SQL Server 2025 und Compatibility Level 170 für die Installationsdatenbank.';
    END;

    SET LOCK_TIMEOUT 0;

    IF @StatusCode = 'AVAILABLE'
    BEGIN TRY
        ;WITH [A] AS
        (
            SELECT [ja].*, ROW_NUMBER() OVER
                   (PARTITION BY [ja].[job_id] ORDER BY [ja].[session_id] DESC) AS [rn]
            FROM [msdb].[dbo].[sysjobactivity] AS [ja] WITH (NOLOCK)
        ),
        [H] AS
        (
            SELECT [h].*, ROW_NUMBER() OVER
                   (PARTITION BY [h].[job_id] ORDER BY [h].[instance_id] DESC) AS [rn]
            FROM [msdb].[dbo].[sysjobhistory] AS [h] WITH (NOLOCK)
            WHERE [h].[step_id] = 0
        ),
        [S] AS
        (
            SELECT
                  [js].[job_id]
                , COUNT_BIG(*) AS [ScheduleCount]
                , SUM(CASE WHEN [sc].[enabled] = 1 THEN 1 ELSE 0 END) AS [EnabledScheduleCount]
            FROM [msdb].[dbo].[sysjobschedules] AS [js] WITH (NOLOCK)
            JOIN [msdb].[dbo].[sysschedules] AS [sc] WITH (NOLOCK)
              ON [sc].[schedule_id] = [js].[schedule_id]
            GROUP BY [js].[job_id]
        )
        INSERT [#AgentJobs_Jobs]
        SELECT TOP (CASE WHEN @PatternMode IN ('REGEX', 'REGEXI') THEN CONVERT(bigint, 9223372036854775807) ELSE @EffectiveMaxZeilen END)
              [j].[job_id]
            , [j].[name]
            , [j].[enabled]
            , SUSER_SNAME([j].[owner_sid])
            , [c].[name]
            , CONVERT(bit, CASE WHEN [a].[start_execution_date] IS NOT NULL AND [a].[stop_execution_date] IS NULL THEN 1 ELSE 0 END)
            , [a].[start_execution_date]
            , CASE WHEN [a].[start_execution_date] IS NOT NULL AND [a].[stop_execution_date] IS NULL
                   THEN DATEDIFF(MINUTE, [a].[start_execution_date], GETDATE()) END
            , CASE WHEN [h].[run_date] > 0 THEN [msdb].[dbo].[agent_datetime]([h].[run_date], [h].[run_time]) END
            , [h].[run_status]
            , CASE [h].[run_status] WHEN 0 THEN N'FAILED' WHEN 1 THEN N'SUCCEEDED'
                   WHEN 2 THEN N'RETRY' WHEN 3 THEN N'CANCELED' WHEN 4 THEN N'IN_PROGRESS' END
            , ([h].[run_duration] / 10000) * 3600
              + (([h].[run_duration] % 10000) / 100) * 60
              + ([h].[run_duration] % 100)
            , [h].[message]
            , CONVERT(int, COALESCE([s].[ScheduleCount], 0))
            , CONVERT(int, COALESCE([s].[EnabledScheduleCount], 0))
            , (SELECT COUNT_BIG(*) FROM [msdb].[dbo].[sysjobsteps] AS [st] WITH (NOLOCK) WHERE [st].[job_id] = [j].[job_id])
            , CASE WHEN [j].[enabled] = 0 THEN 'DISABLED'
                   WHEN [a].[start_execution_date] IS NOT NULL AND [a].[stop_execution_date] IS NULL
                    AND DATEDIFF(MINUTE, [a].[start_execution_date], GETDATE()) >= @LongRunningMinutes THEN 'LONG_RUNNING'
                   WHEN [h].[run_status] = 0 THEN 'LAST_FAILED'
                   WHEN COALESCE([s].[ScheduleCount], 0) = 0 THEN 'NO_SCHEDULE'
                   WHEN COALESCE([s].[EnabledScheduleCount], 0) = 0 THEN 'NO_ENABLED_SCHEDULE' END
        FROM [msdb].[dbo].[sysjobs] AS [j] WITH (NOLOCK)
        LEFT JOIN [msdb].[dbo].[syscategories] AS [c] WITH (NOLOCK)
          ON [c].[category_id] = [j].[category_id]
        LEFT JOIN [A] AS [a] ON [a].[job_id] = [j].[job_id] AND [a].[rn] = 1
        LEFT JOIN [H] AS [h] ON [h].[job_id] = [j].[job_id] AND [h].[rn] = 1
        LEFT JOIN [S] AS [s] ON [s].[job_id] = [j].[job_id]
        WHERE
            (
                NOT EXISTS (SELECT 1 FROM [#AgentJobs_JobNameFilter])
                OR EXISTS
                   (
                       SELECT 1
                       FROM [#AgentJobs_JobNameFilter] AS [f]
                       WHERE [f].[JobName] = [j].[name] COLLATE SQL_Latin1_General_CP1_CS_AS
                   )
            )
          AND
            (
                @PatternMode IN ('NONE', 'REGEX', 'REGEXI')
                OR [j].[name] COLLATE SQL_Latin1_General_CP1_CS_AS
                   LIKE @PatternValue COLLATE SQL_Latin1_General_CP1_CS_AS
            )
          AND
            (
                @NurProblematisch = 0
                OR [j].[enabled] = 0
                OR [h].[run_status] = 0
                OR COALESCE([s].[ScheduleCount], 0) = 0
                OR COALESCE([s].[EnabledScheduleCount], 0) = 0
                OR ([a].[start_execution_date] IS NOT NULL AND [a].[stop_execution_date] IS NULL
                    AND DATEDIFF(MINUTE, [a].[start_execution_date], GETDATE()) >= @LongRunningMinutes)
            )
        ORDER BY
              CASE WHEN [a].[start_execution_date] IS NOT NULL AND [a].[stop_execution_date] IS NULL THEN 0 ELSE 1 END
            , [j].[name];

        IF @PatternMode IN ('REGEX', 'REGEXI')
        BEGIN
            DECLARE @RegexSql nvarchar(max) = N'DELETE [j]
FROM [#AgentJobs_Jobs] AS [j]
WHERE NOT REGEXP_LIKE([j].[JobName], @Pattern, @Flags);';

            EXEC [sys].[sp_executesql]
                  @RegexSql
                , N'@Pattern nvarchar(4000), @Flags varchar(8)'
                , @Pattern = @PatternValue
                , @Flags = @RegexFlags;
        END;

        IF @EffectiveMaxZeilen < 9223372036854775807
        BEGIN
            ;WITH [D] AS
            (
                SELECT
                      [JobId]
                    , ROW_NUMBER() OVER
                      (ORDER BY CASE WHEN [ProblemCode] IS NULL THEN 1 ELSE 0 END, [JobName]) AS [rn]
                FROM [#AgentJobs_Jobs]
            )
            DELETE [j]
            FROM [#AgentJobs_Jobs] AS [j]
            JOIN [D] AS [d] ON [d].[JobId] = [j].[JobId]
            WHERE [d].[rn] > @EffectiveMaxZeilen;
        END;

        ;WITH [SH] AS
        (
            SELECT [h].*, ROW_NUMBER() OVER
                   (PARTITION BY [h].[job_id], [h].[step_id] ORDER BY [h].[instance_id] DESC) AS [rn]
            FROM [msdb].[dbo].[sysjobhistory] AS [h] WITH (NOLOCK)
            WHERE [h].[step_id] > 0
        )
        INSERT [#AgentJobs_Steps]
        SELECT TOP (@EffectiveMaxZeilen)
              [j].[name], [st].[step_id], [st].[step_name], [st].[subsystem], [h].[run_status]
            , CASE [h].[run_status] WHEN 0 THEN N'FAILED' WHEN 1 THEN N'SUCCEEDED'
                   WHEN 2 THEN N'RETRY' WHEN 3 THEN N'CANCELED' WHEN 4 THEN N'IN_PROGRESS' END
            , CASE WHEN [h].[run_date] > 0 THEN [msdb].[dbo].[agent_datetime]([h].[run_date], [h].[run_time]) END
            , ([h].[run_duration] / 10000) * 3600
              + (([h].[run_duration] % 10000) / 100) * 60
              + ([h].[run_duration] % 100)
            , [h].[retries_attempted], [h].[message]
        FROM [msdb].[dbo].[sysjobsteps] AS [st] WITH (NOLOCK)
        JOIN [msdb].[dbo].[sysjobs] AS [j] WITH (NOLOCK) ON [j].[job_id] = [st].[job_id]
        JOIN [#AgentJobs_Jobs] AS [selected] ON [selected].[JobId] = [j].[job_id]
        LEFT JOIN [SH] AS [h]
          ON [h].[job_id] = [st].[job_id]
         AND [h].[step_id] = [st].[step_id]
         AND [h].[rn] = 1
        WHERE @NurProblematisch = 0 OR [h].[run_status] IN (0, 2, 3)
        ORDER BY [j].[name], [st].[step_id];
    END TRY
    BEGIN CATCH
        SELECT
              @StatusCode = 'ERROR_HANDLED'
            , @IsPartial = 1
            , @ErrorNumber = ERROR_NUMBER()
            , @ErrorMessage = ERROR_MESSAGE();

        IF @PrintMeldungen = 1
            RAISERROR(N'Agentjobs konnten nicht vollständig gelesen werden: %s', 10, 1, @ErrorMessage) WITH NOWAIT;
    END CATCH;

    IF @ResultSetArtNormalisiert <> 'NONE'
    BEGIN
        SELECT
              @CollectionTimeUtc AS [CollectionTimeUtc]
            , CAST(N'monitor.USP_AgentJobs' AS nvarchar(256)) AS [ModuleName]
            , @StatusCode AS [StatusCode]
            , @IsPartial AS [IsPartial]
            , @ErrorNumber AS [ErrorNumber]
            , @ErrorMessage AS [ErrorMessage];

        IF @ResultSetArtNormalisiert = 'RAW'
        BEGIN
            SELECT * FROM [#AgentJobs_Jobs] ORDER BY CASE WHEN [ProblemCode] IS NULL THEN 1 ELSE 0 END, [JobName];
            SELECT * FROM [#AgentJobs_Steps] ORDER BY [JobName], [StepId];
        END;
        ELSE
        BEGIN
            SELECT
                  N'SQL-Agent-Job' AS [Ergebnis]
                , [JobName] AS [Job]
                , [Enabled] AS [Aktiv]
                , [IsRunning] AS [Läuft]
                , CASE WHEN [RunningMinutes] IS NULL THEN NULL ELSE CONCAT([RunningMinutes], N' min') END AS [Aktuelle Laufzeit]
                , [LastRunStatusDesc] AS [Letzter Status]
                , CASE WHEN [LastRunDurationSeconds] IS NULL THEN NULL ELSE CONCAT([LastRunDurationSeconds], N' s') END AS [Letzte Laufzeit]
                , [ProblemCode] AS [Problem]
                , [OwnerName] AS [Owner]
                , [CategoryName] AS [Kategorie]
                , [ScheduleCount] AS [Schedules]
                , [EnabledScheduleCount] AS [Aktive Schedules]
                , [StepCount] AS [Steps]
                , [LastMessage] AS [Letzte Meldung]
            FROM [#AgentJobs_Jobs]
            ORDER BY CASE WHEN [ProblemCode] IS NULL THEN 1 ELSE 0 END, [JobName];

            SELECT
                  N'SQL-Agent-Jobstep' AS [Ergebnis]
                , [JobName] AS [Job]
                , [StepId] AS [Step]
                , [StepName] AS [Stepname]
                , [Subsystem]
                , [LastRunOutcomeDesc] AS [Letzter Status]
                , [LastRunDateTime] AS [Letzte Ausführung]
                , CASE WHEN [LastRunDurationSeconds] IS NULL THEN NULL ELSE CONCAT([LastRunDurationSeconds], N' s') END AS [Laufzeit]
                , [LastRunRetries] AS [Retries]
                , [LastRunMessage] AS [Meldung]
            FROM [#AgentJobs_Steps]
            ORDER BY [JobName], [StepId];
        END;
    END;

    IF @JsonErzeugen = 1
    BEGIN
        DECLARE @MetaJson nvarchar(max) =
        (
            SELECT
                  N'AgentJobs' AS [resultName]
                , 1 AS [schemaVersion]
                , @CollectionTimeUtc AS [generatedAtUtc]
                , @StatusCode AS [statusCode]
                , @IsPartial AS [isPartial]
                , @MaxZeilen AS [requestedMaxRows]
                , (SELECT COUNT_BIG(*) FROM [#AgentJobs_Jobs]) AS [jobCount]
                , (SELECT COUNT_BIG(*) FROM [#AgentJobs_Steps]) AS [stepCount]
                , @ErrorNumber AS [errorNumber]
                , @ErrorMessage AS [errorMessage]
            FOR JSON PATH, WITHOUT_ARRAY_WRAPPER, INCLUDE_NULL_VALUES
        );
        DECLARE @JobsJson nvarchar(max) =
            (SELECT * FROM [#AgentJobs_Jobs] ORDER BY CASE WHEN [ProblemCode] IS NULL THEN 1 ELSE 0 END, [JobName] FOR JSON PATH, INCLUDE_NULL_VALUES);
        DECLARE @StepsJson nvarchar(max) =
            (SELECT * FROM [#AgentJobs_Steps] ORDER BY [JobName], [StepId] FOR JSON PATH, INCLUDE_NULL_VALUES);

        SET @Json = CONCAT
        (
              N'{"meta":', COALESCE(@MetaJson, N'{}')
            , N',"jobs":', COALESCE(@JobsJson, N'[]')
            , N',"steps":', COALESCE(@StepsJson, N'[]')
            , N'}'
        );
    END;
    IF @ConsoleResultRequested = 1
    BEGIN
        EXEC [monitor].[InternalEmitConsoleResult]
              @SourceTable=N'#AgentJobs_Jobs'
            , @ResultLabel=N'AgentJobs'
            , @EmptyMessage=N'Keine fachlichen Ergebnisse';
    END;
    IF @TableResultRequested = 1
    BEGIN
        EXEC [monitor].[InternalWriteResultTable]
              @SourceTable = N'#AgentJobs_Jobs'
            , @TargetTable=@TableTarget
            , @ThrowOnError = 1;
    END;
END;
GO
-- END SOURCE: Code/07_Infrastructure/020_USP_AgentJobs.sql

-- BEGIN SOURCE: Code/07_Infrastructure/030_USP_ResourceGovernorAnalysis.sql
/*
===============================================================================
Objekt       : monitor.USP_ResourceGovernorAnalysis
Version      : 3.0.0
Stand        : 2026-07-23
Typ          : Stored Procedure
Zweck        : Trennt Resource-Governor-Konfiguration, Laufzeitkennzahlen und
               die SQL-Server-2025-TempDB-Governance je Workload Group.
SQL-Version  : SQL Server 2019 oder neuer; TempDB-Governance ab 2025 (17.x).
Datenquellen : sys.resource_governor_configuration,
               sys.dm_resource_governor_configuration,
               sys.resource_governor_resource_pools,
               sys.dm_resource_governor_resource_pools,
               sys.resource_governor_workload_groups,
               sys.dm_resource_governor_workload_groups,
               sys.dm_exec_sessions, master.sys.master_files.
Parameter    : @MitSessions, @MaxZeilen, @ResultSetArt, @ResultTablesJson,
               @JsonErzeugen, @Json OUTPUT, @PrintMeldungen, @Hilfe.
Resultsets   : configuration, resourcePools, workloadGroups, sessions,
               tempdbGovernance und warnings.
Berechtigung : Nur lesender Zugriff. Das Framework vergibt keine Rechte und
               ändert weder Resource Governor noch TempDB.
Eigenlast    : Gering bis mittel; jede fachliche Quelle höchstens einmal.
Locking      : LOCK_TIMEOUT 0 für Quellen; vorheriger Sessionwert wird
               auch nach TABLE- und CONSOLE-Ausgabe wiederhergestellt.
Änderungen   : 3.0.0 - SQL25-003: gespeicherte Limits, wirksames Limit,
                         aktuelle/Peak-Nutzung, Verletzungen und Resetgrenze.
===============================================================================
*/
CREATE OR ALTER PROCEDURE [monitor].[USP_ResourceGovernorAnalysis]
      @MitSessions       bit            = 1
    , @MaxZeilen         int            = 5000
    , @ResultSetArt      varchar(16)    = 'CONSOLE'
    , @ResultTablesJson  nvarchar(max)  = NULL
    , @JsonErzeugen      bit            = 0
    , @Json              nvarchar(max)  = NULL OUTPUT
    , @PrintMeldungen    bit            = 1
    , @Hilfe             bit            = 0
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @OriginalLockTimeout int=@@LOCK_TIMEOUT;
    DECLARE @RestoreLockTimeoutSql nvarchar(100);
    SET @Json=NULL;

    DECLARE @OutputMode varchar(16)=UPPER(LTRIM(RTRIM(COALESCE(@ResultSetArt,''))));
    DECLARE @TableResultRequested bit=CASE WHEN @OutputMode='TABLE' THEN 1 ELSE 0 END;
    DECLARE @ConsoleResultRequested bit=CASE WHEN @OutputMode='CONSOLE' THEN 1 ELSE 0 END;
    DECLARE @EffectiveMaxZeilen bigint=
        CASE WHEN @MaxZeilen IS NULL OR @MaxZeilen=0 THEN CONVERT(bigint,9223372036854775807)
             WHEN @MaxZeilen>0 THEN CONVERT(bigint,@MaxZeilen)
             ELSE CONVERT(bigint,0) END;

    IF @Hilfe=1
    BEGIN
        PRINT N'monitor.USP_ResourceGovernorAnalysis';
        PRINT N'@MitSessions bit=1: aktuelle Benutzersessions je Workload Group.';
        PRINT N'@MaxZeilen positiv = begrenzt; NULL/0 = unbegrenzt.';
        PRINT N'@ResultSetArt=CONSOLE (Default)|RAW|TABLE|NONE; JSON über @JsonErzeugen=1.';
        PRINT N'TABLE erlaubt configuration, resourcePools, workloadGroups, sessions und tempdbGovernance.';
        PRINT N'TempDB-Limits, Wirksamkeit, Nutzung, Peak und Verletzungen sind getrennte Evidenz.';
        PRINT N'Die Procedure führt weder ALTER RESOURCE GOVERNOR noch RECONFIGURE oder RESET STATISTICS aus.';
        RETURN;
    END;

    DECLARE @CollectionTimeUtc datetime2(3)=SYSUTCDATETIME();
    DECLARE @ProductMajorVersion int=TRY_CONVERT(int,SERVERPROPERTY(N'ProductMajorVersion'));
    DECLARE @StatusCode varchar(40)='AVAILABLE';
    DECLARE @IsPartial bit=0;
    DECLARE @ErrorNumber int=NULL;
    DECLARE @ErrorMessage nvarchar(2048)=NULL;
    DECLARE @Sql nvarchar(max);
    DECLARE @SourceStatus varchar(40);
    DECLARE @SourceErrorNumber int;
    DECLARE @SourceErrorMessage nvarchar(2048);
    DECLARE @TablePreflightStatus varchar(40);
    DECLARE @TablePreflightError nvarchar(2048);

    CREATE TABLE [#ResourceGovernorAnalysis_ResultTableMap]
    (
          [ResultName] sysname COLLATE SQL_Latin1_General_CP1_CS_AS NOT NULL PRIMARY KEY
        , [TargetTable] sysname COLLATE SQL_Latin1_General_CP1_CS_AS NOT NULL UNIQUE
    );

    CREATE TABLE [#ResourceGovernorAnalysis_Cfg]
    (
          [ClassifierFunctionId] int NULL
        , [IsEnabled] bit NULL
        , [ReconfigurationPending] bit NULL
        , [ClassifierFunctionName] nvarchar(517) NULL
    );

    CREATE TABLE [#ResourceGovernorAnalysis_SourcePoolCatalog]
    (
          [PoolId] int NOT NULL PRIMARY KEY
        , [PoolName] sysname NOT NULL
        , [MinCpuPercent] int NULL
        , [MaxCpuPercent] int NULL
        , [MinMemoryPercent] int NULL
        , [MaxMemoryPercent] int NULL
        , [CapCpuPercent] int NULL
        , [MinIopsPerVolume] int NULL
        , [MaxIopsPerVolume] int NULL
    );

    CREATE TABLE [#ResourceGovernorAnalysis_SourcePoolRuntime]
    (
          [PoolId] int NOT NULL PRIMARY KEY
        , [StatisticsStartTime] datetime NULL
        , [TotalCpuUsageMs] bigint NULL
        , [CacheMemoryKb] bigint NULL
        , [UsedMemoryKb] bigint NULL
        , [TargetMemoryKb] bigint NULL
        , [MaxMemoryKb] bigint NULL
        , [OutOfMemoryCount] bigint NULL
        , [ActiveMemgrantCount] int NULL
        , [PendingMemgrantCount] int NULL
    );

    CREATE TABLE [#ResourceGovernorAnalysis_SourceGroupCatalog]
    (
          [GroupId] int NOT NULL PRIMARY KEY
        , [GroupName] sysname NOT NULL
        , [PoolId] int NULL
        , [Importance] nvarchar(60) NULL
        , [RequestMaxMemoryGrantPercent] decimal(9,4) NULL
        , [RequestMaxCpuTimeSec] int NULL
        , [RequestMemoryGrantTimeoutSec] int NULL
        , [MaxDop] int NULL
        , [GroupMaxRequests] int NULL
        , [ConfiguredGroupMaxTempdbDataMb] decimal(19,2) NULL
        , [ConfiguredGroupMaxTempdbDataPercent] decimal(9,4) NULL
    );

    CREATE TABLE [#ResourceGovernorAnalysis_SourceGroupRuntime]
    (
          [GroupId] int NOT NULL PRIMARY KEY
        , [GroupName] sysname NOT NULL
        , [PoolId] int NULL
        , [StatisticsStartTime] datetime NULL
        , [EffectiveMaxDop] int NULL
        , [TotalRequestCount] bigint NULL
        , [TotalQueuedRequestCount] bigint NULL
        , [ActiveRequestCount] int NULL
        , [QueuedRequestCount] int NULL
        , [TotalReducedMemgrantCount] bigint NULL
        , [MaxRequestGrantMemoryKb] bigint NULL
        , [TotalCpuUsageMs] bigint NULL
        , [TotalLockWaitCount] bigint NULL
        , [TotalLockWaitTimeMs] bigint NULL
        , [TempdbDataSpaceKb] bigint NULL
        , [PeakTempdbDataSpaceKb] bigint NULL
        , [TotalTempdbDataLimitViolationCount] bigint NULL
    );

    CREATE TABLE [#ResourceGovernorAnalysis_SourceSessions]
    (
          [SessionId] int NOT NULL PRIMARY KEY
        , [LoginName] sysname NULL
        , [HostName] nvarchar(128) NULL
        , [ProgramName] nvarchar(128) NULL
        , [GroupId] int NULL
        , [Status] nvarchar(60) NULL
        , [CpuTimeMs] int NULL
        , [MemoryUsagePages] int NULL
        , [Reads] bigint NULL
        , [Writes] bigint NULL
        , [LogicalReads] bigint NULL
    );

    CREATE TABLE [#ResourceGovernorAnalysis_TempdbFiles]
    (
          [FileId] int NOT NULL PRIMARY KEY
        , [SizePages] bigint NOT NULL
        , [MaxSizePages] bigint NOT NULL
        , [GrowthPagesOrPercent] bigint NOT NULL
        , [IsPercentGrowth] bit NOT NULL
    );

    CREATE TABLE [#ResourceGovernorAnalysis_Pools]
    (
          [PoolId] int NOT NULL
        , [PoolName] sysname NOT NULL
        , [MinCpuPercent] int NULL
        , [MaxCpuPercent] int NULL
        , [MinMemoryPercent] int NULL
        , [MaxMemoryPercent] int NULL
        , [CapCpuPercent] int NULL
        , [MinIopsPerVolume] int NULL
        , [MaxIopsPerVolume] int NULL
        , [StatisticsStartTime] datetime NULL
        , [TotalCpuUsageMs] bigint NULL
        , [CacheMemoryMb] decimal(19,2) NULL
        , [UsedWorkspaceMemoryMb] decimal(19,2) NULL
        , [TargetWorkspaceMemoryMb] decimal(19,2) NULL
        , [MaxWorkspaceMemoryMb] decimal(19,2) NULL
        , [OutOfMemoryCount] bigint NULL
        , [ActiveMemgrantCount] int NULL
        , [PendingMemgrantCount] int NULL
        , [UsedOfTargetMemoryPercent] decimal(9,2) NULL
        , [UsedOfMaxMemoryPercent] decimal(9,2) NULL
    );

    CREATE TABLE [#ResourceGovernorAnalysis_Groups]
    (
          [GroupId] int NOT NULL
        , [GroupName] sysname NOT NULL
        , [PoolId] int NULL
        , [PoolName] sysname NULL
        , [Importance] nvarchar(60) NULL
        , [RequestMaxMemoryGrantPercent] decimal(9,4) NULL
        , [ConfiguredRequestMaxGrantMemoryMb] decimal(19,2) NULL
        , [TargetRequestMaxGrantMemoryMb] decimal(19,2) NULL
        , [HistoricalMaxRequestGrantMemoryMb] decimal(19,2) NULL
        , [RequestMaxCpuTimeSec] int NULL
        , [RequestMemoryGrantTimeoutSec] int NULL
        , [MaxDop] int NULL
        , [EffectiveMaxDop] int NULL
        , [GroupMaxRequests] int NULL
        , [TotalRequestCount] bigint NULL
        , [TotalQueuedRequestCount] bigint NULL
        , [ActiveRequestCount] int NULL
        , [QueuedRequestCount] int NULL
        , [TotalReducedMemgrantCount] bigint NULL
        , [TotalCpuUsageMs] bigint NULL
        , [TotalLockWaitCount] bigint NULL
        , [TotalLockWaitTimeMs] bigint NULL
    );

    CREATE TABLE [#ResourceGovernorAnalysis_Sessions]
    (
          [SessionId] int NOT NULL
        , [LoginName] sysname NULL
        , [HostName] nvarchar(128) NULL
        , [ProgramName] nvarchar(128) NULL
        , [GroupId] int NULL
        , [GroupName] sysname NULL
        , [PoolName] sysname NULL
        , [Status] nvarchar(60) NULL
        , [CpuTimeMs] int NULL
        , [MemoryUsagePages] int NULL
        , [MemoryUsageMb] decimal(19,2) NULL
        , [Reads] bigint NULL
        , [Writes] bigint NULL
        , [LogicalReads] bigint NULL
    );

    CREATE TABLE [#ResourceGovernorAnalysis_TempdbGovernance]
    (
          [GroupId] int NULL
        , [GroupName] sysname NULL
        , [PoolId] int NULL
        , [PoolName] sysname NULL
        , [ConfiguredGroupMaxTempdbDataMb] decimal(19,2) NULL
        , [ConfiguredGroupMaxTempdbDataPercent] decimal(9,4) NULL
        , [TempdbMaximumSizeMb] decimal(19,2) NULL
        , [EffectiveGroupMaxTempdbDataMb] decimal(19,2) NULL
        , [EffectiveLimitSource] varchar(40) NOT NULL
        , [IsPercentLimitEffective] bit NULL
        , [TempdbDataSpaceMb] decimal(19,2) NULL
        , [PeakTempdbDataSpaceMb] decimal(19,2) NULL
        , [EffectiveLimitUtilizationPercent] decimal(9,2) NULL
        , [TotalTempdbDataLimitViolationCount] bigint NULL
        , [HasRecordedLimitViolation] bit NULL
        , [StatisticsStartTime] datetime NULL
        , [IsResourceGovernorEnabled] bit NULL
        , [ReconfigurationPending] bit NULL
        , [SourceStatusCode] varchar(40) NOT NULL
        , [IsPartial] bit NOT NULL
        , [EvidenceLimit] nvarchar(1000) NULL
    );

    CREATE TABLE [#ResourceGovernorAnalysis_Warnings]
    (
          [WarningCode] varchar(40) NOT NULL
        , [ErrorNumber] int NULL
        , [WarningMessage] nvarchar(2048) NOT NULL
    );

    IF @MaxZeilen<0
       OR @MitSessions IS NULL
       OR @JsonErzeugen IS NULL
       OR @OutputMode NOT IN ('RAW','CONSOLE','TABLE','NONE')
       OR (@OutputMode<>'TABLE' AND NULLIF(LTRIM(RTRIM(COALESCE(@ResultTablesJson,N''))),N'') IS NOT NULL)
    BEGIN
        SET @StatusCode='INVALID_PARAMETER';
        SET @ErrorMessage=N'Ungültiger Parameter. @MaxZeilen darf nicht negativ sein; @ResultSetArt erlaubt CONSOLE, RAW, TABLE oder NONE.';
    END;

    IF @StatusCode='AVAILABLE' AND @TableResultRequested=1
    BEGIN
        EXEC [monitor].[InternalPrepareResultTables]
              @ResultTablesJson=@ResultTablesJson
            , @AllowedResultNames=N'configuration|resourcePools|workloadGroups|sessions|tempdbGovernance'
            , @MappingTable=N'#ResourceGovernorAnalysis_ResultTableMap'
            , @StatusCode=@TablePreflightStatus OUTPUT
            , @ErrorMessage=@TablePreflightError OUTPUT
            , @ThrowOnError=0;

        SET @RestoreLockTimeoutSql=N'SET LOCK_TIMEOUT '+CONVERT(nvarchar(20),@OriginalLockTimeout)+N';';
        EXEC [sys].[sp_executesql] @RestoreLockTimeoutSql;

        IF @TablePreflightStatus<>'AVAILABLE'
        BEGIN
            SET @StatusCode=@TablePreflightStatus;
            SET @ErrorMessage=@TablePreflightError;
        END;
    END;

    IF @StatusCode<>'AVAILABLE'
    BEGIN
        SET @RestoreLockTimeoutSql=N'SET LOCK_TIMEOUT '+CONVERT(nvarchar(20),@OriginalLockTimeout)+N';';
        EXEC [sys].[sp_executesql] @RestoreLockTimeoutSql;
        THROW 51011,@ErrorMessage,1;
    END;

    SET LOCK_TIMEOUT 0;

    DECLARE @CatalogTempdbColumnsValid bit=0;
    DECLARE @RuntimeTempdbColumnsValid bit=0;
    DECLARE @TempdbGovernanceStatus varchar(40)=
        CASE WHEN @ProductMajorVersion IS NULL OR @ProductMajorVersion<17
             THEN 'UNAVAILABLE_VERSION' ELSE 'AVAILABLE' END;
    DECLARE @TempdbGovernanceErrorNumber int=NULL;
    DECLARE @TempdbGovernanceErrorMessage nvarchar(2048)=NULL;
    DECLARE @TempdbMaximumSizeMb decimal(19,2)=NULL;
    DECLARE @TempdbFileStatus varchar(40)='NOT_APPLICABLE';
    DECLARE @TempdbFileErrorNumber int=NULL;
    DECLARE @TempdbFileErrorMessage nvarchar(2048)=NULL;

    IF @ProductMajorVersion>=17
    BEGIN TRY
        SELECT
              @CatalogTempdbColumnsValid=CONVERT
              (
                  bit,
                  CASE WHEN SUM(CASE WHEN [o].[name]=N'resource_governor_workload_groups'
                                      AND [c].[name] IN
                                          (N'group_max_tempdb_data_mb',N'group_max_tempdb_data_percent')
                                    THEN 1 ELSE 0 END)=2
                       THEN 1 ELSE 0 END
              )
            , @RuntimeTempdbColumnsValid=CONVERT
              (
                  bit,
                  CASE WHEN SUM(CASE WHEN [o].[name]=N'dm_resource_governor_workload_groups'
                                      AND [c].[name] IN
                                          (N'tempdb_data_space_kb',N'peak_tempdb_data_space_kb',
                                           N'total_tempdb_data_limit_violation_count')
                                    THEN 1 ELSE 0 END)=3
                       THEN 1 ELSE 0 END
              )
        FROM [sys].[all_columns] AS [c] WITH (NOLOCK)
        INNER JOIN [sys].[all_objects] AS [o] WITH (NOLOCK)
          ON [o].[object_id]=[c].[object_id]
        INNER JOIN [sys].[schemas] AS [s] WITH (NOLOCK)
          ON [s].[schema_id]=[o].[schema_id]
        WHERE [s].[name]=N'sys'
          AND [o].[name] IN
              (N'resource_governor_workload_groups',N'dm_resource_governor_workload_groups');

        IF @CatalogTempdbColumnsValid=0 OR @RuntimeTempdbColumnsValid=0
            SET @TempdbGovernanceStatus='UNAVAILABLE_SOURCE_SCHEMA';
    END TRY
    BEGIN CATCH
        SELECT
              @TempdbGovernanceStatus=CASE WHEN ERROR_NUMBER()=1222 THEN 'TIMEOUT'
                    WHEN ERROR_NUMBER() IN (229,262,297,300,371,916) THEN 'DENIED_PERMISSION'
                    ELSE 'ERROR_HANDLED' END
            , @TempdbGovernanceErrorNumber=ERROR_NUMBER()
            , @TempdbGovernanceErrorMessage=ERROR_MESSAGE();
    END CATCH;

    BEGIN TRY
        INSERT [#ResourceGovernorAnalysis_Cfg]
        (
              [ClassifierFunctionId],[IsEnabled],[ReconfigurationPending],[ClassifierFunctionName]
        )
        SELECT
              [stored].[classifier_function_id]
            , [stored].[is_enabled]
            , [effective].[is_reconfiguration_pending]
            , CASE
                  WHEN [stored].[classifier_function_id]=0 THEN NULL
                  WHEN [classifier_object].[object_id] IS NULL THEN N'<nicht sichtbar>'
                  ELSE QUOTENAME([classifier_schema].[name])+N'.'+QUOTENAME([classifier_object].[name])
              END
        FROM [sys].[resource_governor_configuration] AS [stored] WITH (NOLOCK)
        CROSS JOIN [sys].[dm_resource_governor_configuration] AS [effective] WITH (NOLOCK)
        LEFT JOIN [master].[sys].[objects] AS [classifier_object] WITH (NOLOCK)
          ON [classifier_object].[object_id]=[stored].[classifier_function_id]
        LEFT JOIN [master].[sys].[schemas] AS [classifier_schema] WITH (NOLOCK)
          ON [classifier_schema].[schema_id]=[classifier_object].[schema_id];
    END TRY
    BEGIN CATCH
        SELECT
              @SourceErrorNumber=ERROR_NUMBER()
            , @SourceErrorMessage=ERROR_MESSAGE()
            , @SourceStatus=CASE WHEN ERROR_NUMBER()=1222 THEN 'TIMEOUT'
                 WHEN ERROR_NUMBER() IN (229,262,297,300,371,916) THEN 'DENIED_PERMISSION'
                 ELSE 'ERROR_HANDLED' END;
        INSERT [#ResourceGovernorAnalysis_Warnings] VALUES(@SourceStatus,@SourceErrorNumber,@SourceErrorMessage);
        SELECT @StatusCode='AVAILABLE_LIMITED',@IsPartial=1;
        IF @ProductMajorVersion>=17 AND @TempdbGovernanceStatus='AVAILABLE'
            SELECT @TempdbGovernanceStatus=@SourceStatus,
                   @TempdbGovernanceErrorNumber=@SourceErrorNumber,
                   @TempdbGovernanceErrorMessage=@SourceErrorMessage;
    END CATCH;

    BEGIN TRY
        INSERT [#ResourceGovernorAnalysis_SourcePoolCatalog]
        SELECT
              [p].[pool_id],[p].[name],[p].[min_cpu_percent],[p].[max_cpu_percent]
            , [p].[min_memory_percent],[p].[max_memory_percent],[p].[cap_cpu_percent]
            , [p].[min_iops_per_volume],[p].[max_iops_per_volume]
        FROM [sys].[resource_governor_resource_pools] AS [p] WITH (NOLOCK);
    END TRY
    BEGIN CATCH
        SELECT @SourceErrorNumber=ERROR_NUMBER(),@SourceErrorMessage=ERROR_MESSAGE(),
               @SourceStatus=CASE WHEN ERROR_NUMBER()=1222 THEN 'TIMEOUT'
                    WHEN ERROR_NUMBER() IN (229,262,297,300,371,916) THEN 'DENIED_PERMISSION'
                    ELSE 'ERROR_HANDLED' END;
        INSERT [#ResourceGovernorAnalysis_Warnings] VALUES(@SourceStatus,@SourceErrorNumber,@SourceErrorMessage);
        SELECT @StatusCode='AVAILABLE_LIMITED',@IsPartial=1;
    END CATCH;

    BEGIN TRY
        INSERT [#ResourceGovernorAnalysis_SourcePoolRuntime]
        SELECT
              [p].[pool_id],[p].[statistics_start_time],[p].[total_cpu_usage_ms]
            , [p].[cache_memory_kb],[p].[used_memory_kb],[p].[target_memory_kb],[p].[max_memory_kb]
            , [p].[out_of_memory_count],[p].[active_memgrant_count],[p].[memgrant_waiter_count]
        FROM [sys].[dm_resource_governor_resource_pools] AS [p] WITH (NOLOCK);
    END TRY
    BEGIN CATCH
        SELECT @SourceErrorNumber=ERROR_NUMBER(),@SourceErrorMessage=ERROR_MESSAGE(),
               @SourceStatus=CASE WHEN ERROR_NUMBER()=1222 THEN 'TIMEOUT'
                    WHEN ERROR_NUMBER() IN (229,262,297,300,371,916) THEN 'DENIED_PERMISSION'
                    ELSE 'ERROR_HANDLED' END;
        INSERT [#ResourceGovernorAnalysis_Warnings] VALUES(@SourceStatus,@SourceErrorNumber,@SourceErrorMessage);
        SELECT @StatusCode='AVAILABLE_LIMITED',@IsPartial=1;
    END CATCH;

    BEGIN TRY
        DECLARE @CatalogTempdbProjection nvarchar(max)=
            CASE WHEN @ProductMajorVersion>=17 AND @CatalogTempdbColumnsValid=1
                 THEN N',CONVERT(decimal(19,2),[g].[group_max_tempdb_data_mb])
                         ,CONVERT(decimal(9,4),[g].[group_max_tempdb_data_percent])'
                 ELSE N',CONVERT(decimal(19,2),NULL),CONVERT(decimal(9,4),NULL)' END;
        SET @Sql=N'INSERT [#ResourceGovernorAnalysis_SourceGroupCatalog]
(
      [GroupId],[GroupName],[PoolId],[Importance],[RequestMaxMemoryGrantPercent]
    , [RequestMaxCpuTimeSec],[RequestMemoryGrantTimeoutSec],[MaxDop],[GroupMaxRequests]
    , [ConfiguredGroupMaxTempdbDataMb],[ConfiguredGroupMaxTempdbDataPercent]
)
SELECT
      [g].[group_id],[g].[name],[g].[pool_id],[g].[importance]
    , CONVERT(decimal(9,4),[g].[request_max_memory_grant_percent_numeric])
    , [g].[request_max_cpu_time_sec],[g].[request_memory_grant_timeout_sec]
    , [g].[max_dop],[g].[group_max_requests]'
    +@CatalogTempdbProjection+
N'
FROM [sys].[resource_governor_workload_groups] AS [g] WITH (NOLOCK);';
        EXEC [sys].[sp_executesql] @Sql;
    END TRY
    BEGIN CATCH
        SELECT @SourceErrorNumber=ERROR_NUMBER(),@SourceErrorMessage=ERROR_MESSAGE(),
               @SourceStatus=CASE WHEN ERROR_NUMBER()=1222 THEN 'TIMEOUT'
                    WHEN ERROR_NUMBER() IN (229,262,297,300,371,916) THEN 'DENIED_PERMISSION'
                    ELSE 'ERROR_HANDLED' END;
        INSERT [#ResourceGovernorAnalysis_Warnings] VALUES(@SourceStatus,@SourceErrorNumber,@SourceErrorMessage);
        SELECT @StatusCode='AVAILABLE_LIMITED',@IsPartial=1;
        IF @ProductMajorVersion>=17
            SELECT @TempdbGovernanceStatus=@SourceStatus,
                   @TempdbGovernanceErrorNumber=@SourceErrorNumber,
                   @TempdbGovernanceErrorMessage=@SourceErrorMessage;
    END CATCH;

    BEGIN TRY
        DECLARE @RuntimeTempdbProjection nvarchar(max)=
            CASE WHEN @ProductMajorVersion>=17 AND @RuntimeTempdbColumnsValid=1
                 THEN N',CONVERT(bigint,[g].[tempdb_data_space_kb])
                         ,CONVERT(bigint,[g].[peak_tempdb_data_space_kb])
                         ,CONVERT(bigint,[g].[total_tempdb_data_limit_violation_count])'
                 ELSE N',CONVERT(bigint,NULL),CONVERT(bigint,NULL),CONVERT(bigint,NULL)' END;
        SET @Sql=N'INSERT [#ResourceGovernorAnalysis_SourceGroupRuntime]
(
      [GroupId],[GroupName],[PoolId],[StatisticsStartTime],[EffectiveMaxDop]
    , [TotalRequestCount],[TotalQueuedRequestCount],[ActiveRequestCount],[QueuedRequestCount]
    , [TotalReducedMemgrantCount],[MaxRequestGrantMemoryKb],[TotalCpuUsageMs]
    , [TotalLockWaitCount],[TotalLockWaitTimeMs]
    , [TempdbDataSpaceKb],[PeakTempdbDataSpaceKb],[TotalTempdbDataLimitViolationCount]
)
SELECT
      [g].[group_id],[g].[name],[g].[pool_id],[g].[statistics_start_time],[g].[effective_max_dop]
    , [g].[total_request_count],[g].[total_queued_request_count]
    , [g].[active_request_count],[g].[queued_request_count]
    , [g].[total_reduced_memgrant_count],[g].[max_request_grant_memory_kb]
    , [g].[total_cpu_usage_ms],[g].[total_lock_wait_count],[g].[total_lock_wait_time_ms]'
    +@RuntimeTempdbProjection+
N'
FROM [sys].[dm_resource_governor_workload_groups] AS [g] WITH (NOLOCK);';
        EXEC [sys].[sp_executesql] @Sql;
    END TRY
    BEGIN CATCH
        SELECT @SourceErrorNumber=ERROR_NUMBER(),@SourceErrorMessage=ERROR_MESSAGE(),
               @SourceStatus=CASE WHEN ERROR_NUMBER()=1222 THEN 'TIMEOUT'
                    WHEN ERROR_NUMBER() IN (229,262,297,300,371,916) THEN 'DENIED_PERMISSION'
                    ELSE 'ERROR_HANDLED' END;
        INSERT [#ResourceGovernorAnalysis_Warnings] VALUES(@SourceStatus,@SourceErrorNumber,@SourceErrorMessage);
        SELECT @StatusCode='AVAILABLE_LIMITED',@IsPartial=1;
        IF @ProductMajorVersion>=17
            SELECT @TempdbGovernanceStatus=@SourceStatus,
                   @TempdbGovernanceErrorNumber=@SourceErrorNumber,
                   @TempdbGovernanceErrorMessage=@SourceErrorMessage;
    END CATCH;

    IF @MitSessions=1
    BEGIN TRY
        INSERT [#ResourceGovernorAnalysis_SourceSessions]
        SELECT TOP (@EffectiveMaxZeilen)
              [s].[session_id],[s].[login_name],[s].[host_name],[s].[program_name]
            , [s].[group_id],[s].[status],[s].[cpu_time],[s].[memory_usage]
            , [s].[reads],[s].[writes],[s].[logical_reads]
        FROM [sys].[dm_exec_sessions] AS [s] WITH (NOLOCK)
        WHERE [s].[is_user_process]=1
        ORDER BY [s].[cpu_time] DESC,[s].[session_id];
    END TRY
    BEGIN CATCH
        SELECT @SourceErrorNumber=ERROR_NUMBER(),@SourceErrorMessage=ERROR_MESSAGE(),
               @SourceStatus=CASE WHEN ERROR_NUMBER()=1222 THEN 'TIMEOUT'
                    WHEN ERROR_NUMBER() IN (229,262,297,300,371,916) THEN 'DENIED_PERMISSION'
                    ELSE 'ERROR_HANDLED' END;
        INSERT [#ResourceGovernorAnalysis_Warnings] VALUES(@SourceStatus,@SourceErrorNumber,@SourceErrorMessage);
        SELECT @StatusCode='AVAILABLE_LIMITED',@IsPartial=1;
    END CATCH;

    IF @ProductMajorVersion>=17
       AND @CatalogTempdbColumnsValid=1
       AND EXISTS
           (
               SELECT 1
               FROM [#ResourceGovernorAnalysis_SourceGroupCatalog]
               WHERE [ConfiguredGroupMaxTempdbDataMb] IS NULL
                 AND [ConfiguredGroupMaxTempdbDataPercent] IS NOT NULL
           )
    BEGIN
        SET @TempdbFileStatus='AVAILABLE';
        BEGIN TRY
            INSERT [#ResourceGovernorAnalysis_TempdbFiles]
            (
                  [FileId],[SizePages],[MaxSizePages],[GrowthPagesOrPercent],[IsPercentGrowth]
            )
            SELECT
                  [f].[file_id],CONVERT(bigint,[f].[size]),CONVERT(bigint,[f].[max_size])
                , CONVERT(bigint,[f].[growth]),[f].[is_percent_growth]
            FROM [master].[sys].[master_files] AS [f] WITH (NOLOCK)
            WHERE [f].[database_id]=2 AND [f].[type]=0;

            SELECT @TempdbMaximumSizeMb=
                CASE
                    WHEN COUNT_BIG(*)>0
                     AND
                     (
                         SUM(CASE WHEN [MaxSizePages]<>-1 AND [GrowthPagesOrPercent]>0 THEN 1 ELSE 0 END)=COUNT_BIG(*)
                         OR
                         SUM(CASE WHEN [MaxSizePages]=-1 AND [GrowthPagesOrPercent]=0 THEN 1 ELSE 0 END)=COUNT_BIG(*)
                     )
                    THEN CONVERT
                         (
                             decimal(19,2),
                             SUM(CASE WHEN [GrowthPagesOrPercent]=0 THEN [SizePages] ELSE [MaxSizePages] END)
                             *8.0/1024.0
                         )
                END
            FROM [#ResourceGovernorAnalysis_TempdbFiles];
        END TRY
        BEGIN CATCH
            SELECT
                  @TempdbFileErrorNumber=ERROR_NUMBER()
                , @TempdbFileErrorMessage=ERROR_MESSAGE()
                , @TempdbFileStatus=CASE WHEN ERROR_NUMBER()=1222 THEN 'TIMEOUT'
                      WHEN ERROR_NUMBER() IN (229,262,297,300,371,916) THEN 'DENIED_PERMISSION'
                      ELSE 'ERROR_HANDLED' END;
            INSERT [#ResourceGovernorAnalysis_Warnings]
            VALUES(@TempdbFileStatus,@TempdbFileErrorNumber,@TempdbFileErrorMessage);
        END CATCH;
    END;

    INSERT [#ResourceGovernorAnalysis_Pools]
    SELECT TOP (@EffectiveMaxZeilen)
          [p].[PoolId],[p].[PoolName],[p].[MinCpuPercent],[p].[MaxCpuPercent]
        , [p].[MinMemoryPercent],[p].[MaxMemoryPercent],[p].[CapCpuPercent]
        , [p].[MinIopsPerVolume],[p].[MaxIopsPerVolume],[d].[StatisticsStartTime]
        , [d].[TotalCpuUsageMs],CONVERT(decimal(19,2),[d].[CacheMemoryKb]/1024.0)
        , CONVERT(decimal(19,2),[d].[UsedMemoryKb]/1024.0)
        , CONVERT(decimal(19,2),[d].[TargetMemoryKb]/1024.0)
        , CONVERT(decimal(19,2),[d].[MaxMemoryKb]/1024.0)
        , [d].[OutOfMemoryCount],[d].[ActiveMemgrantCount],[d].[PendingMemgrantCount]
        , CONVERT(decimal(9,2),100.0*[d].[UsedMemoryKb]/NULLIF([d].[TargetMemoryKb],0))
        , CONVERT(decimal(9,2),100.0*[d].[UsedMemoryKb]/NULLIF([d].[MaxMemoryKb],0))
    FROM [#ResourceGovernorAnalysis_SourcePoolCatalog] AS [p]
    LEFT JOIN [#ResourceGovernorAnalysis_SourcePoolRuntime] AS [d]
      ON [d].[PoolId]=[p].[PoolId]
    ORDER BY [p].[PoolId];

    INSERT [#ResourceGovernorAnalysis_Groups]
    SELECT TOP (@EffectiveMaxZeilen)
          [g].[GroupId],[g].[GroupName],[g].[PoolId],[p].[PoolName],[g].[Importance]
        , [g].[RequestMaxMemoryGrantPercent]
        , CONVERT(decimal(19,2),CONVERT(decimal(38,4),[dp].[MaxMemoryKb])
          *CONVERT(decimal(38,4),[g].[RequestMaxMemoryGrantPercent])/100.0/1024.0)
        , CONVERT(decimal(19,2),CONVERT(decimal(38,4),[dp].[TargetMemoryKb])
          *CONVERT(decimal(38,4),[g].[RequestMaxMemoryGrantPercent])/100.0/1024.0)
        , CONVERT(decimal(19,2),[d].[MaxRequestGrantMemoryKb]/1024.0)
        , [g].[RequestMaxCpuTimeSec],[g].[RequestMemoryGrantTimeoutSec]
        , [g].[MaxDop],[d].[EffectiveMaxDop],[g].[GroupMaxRequests]
        , [d].[TotalRequestCount],[d].[TotalQueuedRequestCount]
        , [d].[ActiveRequestCount],[d].[QueuedRequestCount]
        , [d].[TotalReducedMemgrantCount],[d].[TotalCpuUsageMs]
        , [d].[TotalLockWaitCount],[d].[TotalLockWaitTimeMs]
    FROM [#ResourceGovernorAnalysis_SourceGroupCatalog] AS [g]
    LEFT JOIN [#ResourceGovernorAnalysis_SourceGroupRuntime] AS [d]
      ON [d].[GroupId]=[g].[GroupId]
    LEFT JOIN [#ResourceGovernorAnalysis_SourcePoolCatalog] AS [p]
      ON [p].[PoolId]=[g].[PoolId]
    LEFT JOIN [#ResourceGovernorAnalysis_SourcePoolRuntime] AS [dp]
      ON [dp].[PoolId]=[g].[PoolId]
    ORDER BY [g].[GroupId];

    INSERT [#ResourceGovernorAnalysis_Sessions]
    SELECT
          [s].[SessionId],[s].[LoginName],[s].[HostName],[s].[ProgramName]
        , [s].[GroupId],COALESCE([g].[GroupName],[d].[GroupName]),[p].[PoolName],[s].[Status]
        , [s].[CpuTimeMs],[s].[MemoryUsagePages]
        , CONVERT(decimal(19,2),[s].[MemoryUsagePages]*8.0/1024.0)
        , [s].[Reads],[s].[Writes],[s].[LogicalReads]
    FROM [#ResourceGovernorAnalysis_SourceSessions] AS [s]
    LEFT JOIN [#ResourceGovernorAnalysis_SourceGroupCatalog] AS [g]
      ON [g].[GroupId]=[s].[GroupId]
    LEFT JOIN [#ResourceGovernorAnalysis_SourceGroupRuntime] AS [d]
      ON [d].[GroupId]=[s].[GroupId]
    LEFT JOIN [#ResourceGovernorAnalysis_SourcePoolCatalog] AS [p]
      ON [p].[PoolId]=COALESCE([g].[PoolId],[d].[PoolId]);

    DECLARE @IsResourceGovernorEnabled bit=(SELECT TOP (1) [IsEnabled] FROM [#ResourceGovernorAnalysis_Cfg]);
    DECLARE @ReconfigurationPending bit=(SELECT TOP (1) [ReconfigurationPending] FROM [#ResourceGovernorAnalysis_Cfg]);

    INSERT [#ResourceGovernorAnalysis_TempdbGovernance]
    SELECT TOP (@EffectiveMaxZeilen)
          COALESCE([g].[GroupId],[d].[GroupId])
        , COALESCE([g].[GroupName],[d].[GroupName])
        , COALESCE([g].[PoolId],[d].[PoolId])
        , [p].[PoolName]
        , [g].[ConfiguredGroupMaxTempdbDataMb]
        , [g].[ConfiguredGroupMaxTempdbDataPercent]
        , @TempdbMaximumSizeMb
        , CONVERT
          (
              decimal(19,2),
              CASE
                  WHEN @TempdbGovernanceStatus<>'AVAILABLE' THEN NULL
                  WHEN [g].[ConfiguredGroupMaxTempdbDataMb] IS NULL
                   AND [g].[ConfiguredGroupMaxTempdbDataPercent] IS NULL THEN NULL
                  WHEN @ReconfigurationPending=1 OR COALESCE(@IsResourceGovernorEnabled,0)=0 THEN NULL
                  WHEN [g].[ConfiguredGroupMaxTempdbDataMb] IS NOT NULL
                      THEN [g].[ConfiguredGroupMaxTempdbDataMb]
                  WHEN @TempdbFileStatus<>'AVAILABLE' THEN NULL
                  WHEN @TempdbMaximumSizeMb IS NOT NULL
                      THEN [g].[ConfiguredGroupMaxTempdbDataPercent]*@TempdbMaximumSizeMb/100.0
              END
          )
        , CASE
              WHEN @TempdbGovernanceStatus<>'AVAILABLE' THEN 'UNAVAILABLE'
              WHEN [g].[ConfiguredGroupMaxTempdbDataMb] IS NULL
               AND [g].[ConfiguredGroupMaxTempdbDataPercent] IS NULL THEN 'NO_LIMIT_CONFIGURED'
              WHEN @ReconfigurationPending=1 THEN 'RECONFIGURATION_PENDING'
              WHEN COALESCE(@IsResourceGovernorEnabled,0)=0 THEN 'RESOURCE_GOVERNOR_DISABLED'
              WHEN [g].[ConfiguredGroupMaxTempdbDataMb] IS NOT NULL THEN 'FIXED_MB_EFFECTIVE'
              WHEN @TempdbFileStatus<>'AVAILABLE' THEN 'UNAVAILABLE'
              WHEN @TempdbMaximumSizeMb IS NOT NULL THEN 'PERCENT_EFFECTIVE'
              ELSE 'PERCENT_NOT_EFFECTIVE'
          END
        , CASE
              WHEN [g].[ConfiguredGroupMaxTempdbDataPercent] IS NULL THEN NULL
              WHEN [g].[ConfiguredGroupMaxTempdbDataMb] IS NOT NULL THEN CONVERT(bit,0)
              WHEN @ReconfigurationPending=1 OR COALESCE(@IsResourceGovernorEnabled,0)=0 THEN CONVERT(bit,0)
              WHEN @TempdbFileStatus<>'AVAILABLE' THEN NULL
              WHEN @TempdbMaximumSizeMb IS NOT NULL THEN CONVERT(bit,1)
              ELSE CONVERT(bit,0)
          END
        , CONVERT(decimal(19,2),[d].[TempdbDataSpaceKb]/1024.0)
        , CONVERT(decimal(19,2),[d].[PeakTempdbDataSpaceKb]/1024.0)
        , CONVERT
          (
              decimal(9,2),
              100.0*CONVERT(decimal(38,4),[d].[TempdbDataSpaceKb]/1024.0)
              /NULLIF
               (
                   CASE
                       WHEN @ReconfigurationPending=0 AND COALESCE(@IsResourceGovernorEnabled,0)=1
                        AND [g].[ConfiguredGroupMaxTempdbDataMb] IS NOT NULL
                           THEN [g].[ConfiguredGroupMaxTempdbDataMb]
                       WHEN @ReconfigurationPending=0 AND COALESCE(@IsResourceGovernorEnabled,0)=1
                        AND [g].[ConfiguredGroupMaxTempdbDataMb] IS NULL
                        AND @TempdbMaximumSizeMb IS NOT NULL
                           THEN [g].[ConfiguredGroupMaxTempdbDataPercent]*@TempdbMaximumSizeMb/100.0
                   END
               ,0)
          )
        , [d].[TotalTempdbDataLimitViolationCount]
        , CASE WHEN [d].[TotalTempdbDataLimitViolationCount] IS NULL THEN NULL
               WHEN [d].[TotalTempdbDataLimitViolationCount]>0 THEN CONVERT(bit,1)
               ELSE CONVERT(bit,0) END
        , [d].[StatisticsStartTime]
        , @IsResourceGovernorEnabled
        , @ReconfigurationPending
        , CASE
              WHEN @TempdbGovernanceStatus='AVAILABLE'
               AND [g].[ConfiguredGroupMaxTempdbDataMb] IS NULL
               AND [g].[ConfiguredGroupMaxTempdbDataPercent] IS NOT NULL
               AND @TempdbFileStatus<>'AVAILABLE'
                  THEN @TempdbFileStatus
              WHEN @TempdbGovernanceStatus='AVAILABLE'
               AND @ReconfigurationPending=1
               AND
                 (
                     [g].[ConfiguredGroupMaxTempdbDataMb] IS NOT NULL
                     OR [g].[ConfiguredGroupMaxTempdbDataPercent] IS NOT NULL
                 )
                  THEN 'AVAILABLE_LIMITED'
              ELSE @TempdbGovernanceStatus
          END
        , CONVERT
          (
              bit,
              CASE
                  WHEN @TempdbGovernanceStatus<>'AVAILABLE' THEN 1
                  WHEN [g].[ConfiguredGroupMaxTempdbDataMb] IS NULL
                   AND [g].[ConfiguredGroupMaxTempdbDataPercent] IS NOT NULL
                   AND @TempdbFileStatus<>'AVAILABLE' THEN 1
                  WHEN @ReconfigurationPending=1
                   AND
                     (
                         [g].[ConfiguredGroupMaxTempdbDataMb] IS NOT NULL
                         OR [g].[ConfiguredGroupMaxTempdbDataPercent] IS NOT NULL
                     )
                      THEN 1
                  ELSE 0
              END
          )
        , CASE
              WHEN @TempdbGovernanceStatus='UNAVAILABLE_VERSION'
                  THEN N'TempDB Resource Governance beginnt mit SQL Server 2025 (17.x).'
              WHEN @TempdbGovernanceStatus<>'AVAILABLE'
                  THEN COALESCE(@TempdbGovernanceErrorMessage,N'Die SQL-Server-2025-Quelle ist nicht vollständig verfügbar.')
              WHEN [g].[ConfiguredGroupMaxTempdbDataMb] IS NULL
               AND [g].[ConfiguredGroupMaxTempdbDataPercent] IS NOT NULL
               AND @TempdbFileStatus<>'AVAILABLE'
                  THEN COALESCE(@TempdbFileErrorMessage,N'Die TempDB-Dateikonfiguration ist im aktuellen Sicherheitskontext nicht auswertbar.')
              WHEN @ReconfigurationPending=1
                  THEN N'Die gespeicherte Konfiguration kann von der aktiven Konfiguration abweichen, bis RECONFIGURE abgeschlossen ist.'
              WHEN [g].[ConfiguredGroupMaxTempdbDataMb] IS NULL
               AND [g].[ConfiguredGroupMaxTempdbDataPercent] IS NOT NULL
               AND @TempdbMaximumSizeMb IS NULL
                  THEN N'Das gespeicherte Prozentlimit ist wegen der TempDB-Dateikonfiguration nicht wirksam.'
              ELSE N'Workload-Group-Zähler sind nicht direkt mit Sessionzählern addierbar; Version Store und TempDB-Log sind nicht umfasst.'
          END
    FROM [#ResourceGovernorAnalysis_SourceGroupCatalog] AS [g]
    FULL OUTER JOIN [#ResourceGovernorAnalysis_SourceGroupRuntime] AS [d]
      ON [d].[GroupId]=[g].[GroupId]
    LEFT JOIN [#ResourceGovernorAnalysis_SourcePoolCatalog] AS [p]
      ON [p].[PoolId]=COALESCE([g].[PoolId],[d].[PoolId])
    ORDER BY COALESCE([g].[GroupId],[d].[GroupId]);

    IF NOT EXISTS (SELECT 1 FROM [#ResourceGovernorAnalysis_TempdbGovernance])
    BEGIN
        INSERT [#ResourceGovernorAnalysis_TempdbGovernance]
        (
              [GroupId],[GroupName],[PoolId],[PoolName]
            , [ConfiguredGroupMaxTempdbDataMb],[ConfiguredGroupMaxTempdbDataPercent]
            , [TempdbMaximumSizeMb],[EffectiveGroupMaxTempdbDataMb]
            , [EffectiveLimitSource],[IsPercentLimitEffective]
            , [TempdbDataSpaceMb],[PeakTempdbDataSpaceMb],[EffectiveLimitUtilizationPercent]
            , [TotalTempdbDataLimitViolationCount],[HasRecordedLimitViolation]
            , [StatisticsStartTime],[IsResourceGovernorEnabled],[ReconfigurationPending]
            , [SourceStatusCode],[IsPartial],[EvidenceLimit]
        )
        VALUES
        (
              NULL,NULL,NULL,NULL,NULL,NULL,@TempdbMaximumSizeMb,NULL
            , 'UNAVAILABLE',NULL,NULL,NULL,NULL,NULL,NULL,NULL
            , @IsResourceGovernorEnabled,@ReconfigurationPending
            , CASE WHEN @TempdbGovernanceStatus='AVAILABLE'
                   THEN 'AVAILABLE_EMPTY_OR_RESTRICTED' ELSE @TempdbGovernanceStatus END
            , 1
            , COALESCE(@TempdbGovernanceErrorMessage,N'Keine sichtbare Workload Group war für die TempDB-Governance auswertbar.')
        );
    END;

    IF @ProductMajorVersion>=17
       AND EXISTS
           (
               SELECT 1
               FROM [#ResourceGovernorAnalysis_TempdbGovernance]
               WHERE [SourceStatusCode] NOT IN ('AVAILABLE','AVAILABLE_EMPTY_OR_RESTRICTED')
           )
    BEGIN
        SELECT @StatusCode='AVAILABLE_LIMITED',@IsPartial=1;
    END;

    IF @PrintMeldungen=1 AND @StatusCode<>'AVAILABLE'
    BEGIN
        DECLARE @PrintMessage nvarchar(2048)=FORMATMESSAGE
        (
            N'WARNUNG USP_ResourceGovernorAnalysis [%s]: %s',
            @StatusCode,
            COALESCE(@ErrorMessage,@TempdbGovernanceErrorMessage,N'Teilergebnis oder eingeschränkte Sicht.')
        );
        RAISERROR(N'%s',10,1,@PrintMessage) WITH NOWAIT;
    END;

    IF @JsonErzeugen=1
    BEGIN
        DECLARE @MetaJson nvarchar(max)=
        (
            SELECT
                  N'ResourceGovernorAnalysis' AS [resultName]
                , 2 AS [schemaVersion]
                , @CollectionTimeUtc AS [generatedAtUtc]
                , @StatusCode AS [statusCode]
                , @IsPartial AS [isPartial]
                , @ProductMajorVersion AS [productMajorVersion]
                , @MaxZeilen AS [requestedMaxRowsPerArray]
                , @ErrorNumber AS [errorNumber]
                , @ErrorMessage AS [errorMessage]
            FOR JSON PATH,WITHOUT_ARRAY_WRAPPER,INCLUDE_NULL_VALUES
        );
        DECLARE @CfgJson nvarchar(max)=
            (SELECT * FROM [#ResourceGovernorAnalysis_Cfg] FOR JSON PATH,INCLUDE_NULL_VALUES);
        DECLARE @PoolsJson nvarchar(max)=
            (SELECT * FROM [#ResourceGovernorAnalysis_Pools] ORDER BY [PoolId] FOR JSON PATH,INCLUDE_NULL_VALUES);
        DECLARE @GroupsJson nvarchar(max)=
            (SELECT * FROM [#ResourceGovernorAnalysis_Groups] ORDER BY [GroupId] FOR JSON PATH,INCLUDE_NULL_VALUES);
        DECLARE @TempdbGovernanceJson nvarchar(max)=
            (SELECT * FROM [#ResourceGovernorAnalysis_TempdbGovernance] ORDER BY [GroupId] FOR JSON PATH,INCLUDE_NULL_VALUES);
        DECLARE @SessionsJson nvarchar(max)=
            (SELECT * FROM [#ResourceGovernorAnalysis_Sessions] ORDER BY [CpuTimeMs] DESC,[SessionId] FOR JSON PATH,INCLUDE_NULL_VALUES);
        DECLARE @WarningsJson nvarchar(max)=
            (SELECT [WarningCode] AS [code],[ErrorNumber] AS [errorNumber],[WarningMessage] AS [message]
             FROM [#ResourceGovernorAnalysis_Warnings] FOR JSON PATH,INCLUDE_NULL_VALUES);
        SET @Json=CONCAT
        (
              N'{"meta":',COALESCE(@MetaJson,N'{}')
            , N',"configuration":',COALESCE(@CfgJson,N'[]')
            , N',"resourcePools":',COALESCE(@PoolsJson,N'[]')
            , N',"workloadGroups":',COALESCE(@GroupsJson,N'[]')
            , N',"tempdbGovernance":',COALESCE(@TempdbGovernanceJson,N'[]')
            , N',"sessions":',COALESCE(@SessionsJson,N'[]')
            , N',"warnings":',COALESCE(@WarningsJson,N'[]')
            , N'}'
        );
    END;

    IF @OutputMode='RAW'
    BEGIN
        SELECT
              @CollectionTimeUtc AS [CollectionTimeUtc]
            , CAST(N'monitor.USP_ResourceGovernorAnalysis' AS nvarchar(256)) AS [ModuleName]
            , @StatusCode AS [StatusCode],@IsPartial AS [IsPartial]
            , @ErrorNumber AS [ErrorNumber],@ErrorMessage AS [ErrorMessage];
        SELECT * FROM [#ResourceGovernorAnalysis_Cfg];
        SELECT * FROM [#ResourceGovernorAnalysis_Pools] ORDER BY [PoolId];
        SELECT * FROM [#ResourceGovernorAnalysis_Groups] ORDER BY [GroupId];
        SELECT * FROM [#ResourceGovernorAnalysis_TempdbGovernance] ORDER BY [GroupId];
        IF @MitSessions=1
            SELECT * FROM [#ResourceGovernorAnalysis_Sessions] ORDER BY [CpuTimeMs] DESC,[SessionId];
        SELECT * FROM [#ResourceGovernorAnalysis_Warnings] ORDER BY [WarningCode],[ErrorNumber];
    END;

    BEGIN TRY
        IF @ConsoleResultRequested=1
        BEGIN
            EXEC [monitor].[InternalEmitConsoleResult]
                  @SourceTable=N'#ResourceGovernorAnalysis_Cfg'
                , @ResultLabel=N'Resource-Governor-Konfiguration'
                , @EmptyMessage=N'Keine sichtbare Resource-Governor-Konfiguration';
            EXEC [monitor].[InternalEmitConsoleResult]
                  @SourceTable=N'#ResourceGovernorAnalysis_Pools'
                , @ResultLabel=N'Resource Pools'
                , @EmptyMessage=N'Keine sichtbaren Resource Pools';
            EXEC [monitor].[InternalEmitConsoleResult]
                  @SourceTable=N'#ResourceGovernorAnalysis_Groups'
                , @ResultLabel=N'Workload Groups'
                , @EmptyMessage=N'Keine sichtbaren Workload Groups';
            EXEC [monitor].[InternalEmitConsoleResult]
                  @SourceTable=N'#ResourceGovernorAnalysis_TempdbGovernance'
                , @ResultLabel=N'TempDB Resource Governance'
                , @EmptyMessage=N'Keine TempDB-Governance-Evidenz';
            IF @MitSessions=1
                EXEC [monitor].[InternalEmitConsoleResult]
                      @SourceTable=N'#ResourceGovernorAnalysis_Sessions'
                    , @ResultLabel=N'Resource-Governor-Sessions'
                    , @EmptyMessage=N'Keine sichtbaren Benutzersessions';
        END;

        IF @TableResultRequested=1
        BEGIN
            DECLARE @TableTarget sysname;
            SELECT @TableTarget=[TargetTable] FROM [#ResourceGovernorAnalysis_ResultTableMap] WHERE [ResultName]=N'configuration';
            IF @TableTarget IS NOT NULL
                EXEC [monitor].[InternalWriteResultTable] @SourceTable=N'#ResourceGovernorAnalysis_Cfg',@TargetTable=@TableTarget,@ThrowOnError=1;

            SET @TableTarget=NULL;
            SELECT @TableTarget=[TargetTable] FROM [#ResourceGovernorAnalysis_ResultTableMap] WHERE [ResultName]=N'resourcePools';
            IF @TableTarget IS NOT NULL
                EXEC [monitor].[InternalWriteResultTable] @SourceTable=N'#ResourceGovernorAnalysis_Pools',@TargetTable=@TableTarget,@ThrowOnError=1;

            SET @TableTarget=NULL;
            SELECT @TableTarget=[TargetTable] FROM [#ResourceGovernorAnalysis_ResultTableMap] WHERE [ResultName]=N'workloadGroups';
            IF @TableTarget IS NOT NULL
                EXEC [monitor].[InternalWriteResultTable] @SourceTable=N'#ResourceGovernorAnalysis_Groups',@TargetTable=@TableTarget,@ThrowOnError=1;

            SET @TableTarget=NULL;
            SELECT @TableTarget=[TargetTable] FROM [#ResourceGovernorAnalysis_ResultTableMap] WHERE [ResultName]=N'sessions';
            IF @TableTarget IS NOT NULL
                EXEC [monitor].[InternalWriteResultTable] @SourceTable=N'#ResourceGovernorAnalysis_Sessions',@TargetTable=@TableTarget,@ThrowOnError=1;

            SET @TableTarget=NULL;
            SELECT @TableTarget=[TargetTable] FROM [#ResourceGovernorAnalysis_ResultTableMap] WHERE [ResultName]=N'tempdbGovernance';
            IF @TableTarget IS NOT NULL
                EXEC [monitor].[InternalWriteResultTable] @SourceTable=N'#ResourceGovernorAnalysis_TempdbGovernance',@TargetTable=@TableTarget,@ThrowOnError=1;
        END;
    END TRY
    BEGIN CATCH
        SET @RestoreLockTimeoutSql=N'SET LOCK_TIMEOUT '+CONVERT(nvarchar(20),@OriginalLockTimeout)+N';';
        EXEC [sys].[sp_executesql] @RestoreLockTimeoutSql;
        THROW;
    END CATCH;

    SET @RestoreLockTimeoutSql=N'SET LOCK_TIMEOUT '+CONVERT(nvarchar(20),@OriginalLockTimeout)+N';';
    EXEC [sys].[sp_executesql] @RestoreLockTimeoutSql;
END;
GO
-- END SOURCE: Code/07_Infrastructure/030_USP_ResourceGovernorAnalysis.sql

-- BEGIN SOURCE: Code/07_Infrastructure/040_USP_AvailabilityGroups.sql
/*
===============================================================================
Objekt       : monitor.USP_AvailabilityGroups
Version      : 1.0.0
Stand        : 2026-07-14
Typ          : Stored Procedure
Zweck        : Analysiert Availability Groups, Replikate, Datenbanken, Listener, Routing sowie Send-/Redo-Queues und geschätzte Lags.
SQL-Version  : SQL Server 2019 oder neuer.
Datenquellen : sys.availability_groups, sys.availability_replicas, sys.dm_hadr_*, sys.availability_group_listeners
Parameter    : @MitRouting, @MaxZeilen, @PrintMeldungen, @Hilfe
Resultsets   : 1. Modulstatus. 2. Gruppen/Replikate. 3. Datenbanken/Queues. 4. Listener. 5. Routing.
Berechtigung : Nur lesender Zugriff auf die genannten Systemobjekte. Das
               Framework vergibt keine Rechte und ändert keine Konfiguration.
Eigenlast    : Mittel; reine HADR-Katalog- und DMV-Auswertung.
Locking      : LOCK_TIMEOUT 0; keine fachlichen Schreibzugriffe.
Partial      : Fehlende Features, Objekte oder Rechte werden strukturiert als
               Partial Result behandelt; andere Module bleiben ausführbar.
Änderungen   : 1.0.0 - Erstfassung Phase 6.
===============================================================================
*/
CREATE OR ALTER PROCEDURE [monitor].[USP_AvailabilityGroups]
      @MitRouting bit=1
    , @MaxZeilen int=5000
    , @ResultSetArt varchar(16)='CONSOLE'
    , @ResultTablesJson               nvarchar(max) = NULL
    , @JsonErzeugen bit=0
    , @Json nvarchar(max)=NULL OUTPUT
    , @PrintMeldungen bit=1
    , @Hilfe bit=0
AS
BEGIN
 SET NOCOUNT ON;
 SET @Json=NULL;
 DECLARE @ResultSetArtNormalisiert varchar(16)=UPPER(LTRIM(RTRIM(COALESCE(@ResultSetArt,''))));
    DECLARE @TableResultRequested bit = CASE WHEN @ResultSetArtNormalisiert = 'TABLE' THEN 1 ELSE 0 END;
    DECLARE @ConsoleResultRequested bit = CASE WHEN @ResultSetArtNormalisiert = 'CONSOLE' THEN 1 ELSE 0 END;
    DECLARE @TableTarget sysname=NULL;
    IF @TableResultRequested=0 AND NULLIF(LTRIM(RTRIM(COALESCE(@ResultTablesJson,N''))),N'') IS NOT NULL THROW 51011,N'@ResultTablesJson ist ausschließlich mit @ResultSetArt=TABLE zulässig.',1;
    IF @TableResultRequested=1 EXEC [monitor].[InternalPrepareSingleResultTable] @ResultTablesJson=@ResultTablesJson,@ResultName=N'replicas',@TargetTable=@TableTarget OUTPUT,@ThrowOnError=1;
    IF @TableResultRequested = 1 OR @ConsoleResultRequested = 1 SET @ResultSetArtNormalisiert = 'NONE';
    DECLARE @EffectiveMaxZeilen bigint = CASE WHEN @MaxZeilen IS NULL OR @MaxZeilen=0 THEN CONVERT(bigint,9223372036854775807) ELSE CONVERT(bigint,@MaxZeilen) END;
 IF @Hilfe=1 BEGIN PRINT N'monitor.USP_AvailabilityGroups'; PRINT N'@MitRouting bit=1; @MaxZeilen int=5000; @PrintMeldungen bit=1; @Hilfe bit=0.'; PRINT N'Die Procedure führt keine Failover-, Resume-, Suspend- oder Routingänderung aus.'; RETURN; END;
 DECLARE @CollectionTimeUtc datetime2(3)=SYSUTCDATETIME(),@StatusCode varchar(40)='AVAILABLE',@IsPartial bit=0,@ErrorNumber int=NULL,@ErrorMessage nvarchar(2048)=NULL;
 CREATE TABLE [#AvailabilityGroups_R]([AgName] sysname,[ReplicaServerName] nvarchar(256),[LocalReplica] bit,[RoleDesc] nvarchar(60),[OperationalStateDesc] nvarchar(60),[ConnectedStateDesc] nvarchar(60),[RecoveryHealthDesc] nvarchar(60),[SynchronizationHealthDesc] nvarchar(60),[AvailabilityModeDesc] nvarchar(60),[FailoverModeDesc] nvarchar(60),[SessionTimeout] int,[EndpointUrl] nvarchar(256),[PrimaryRoleAllowConnectionsDesc] nvarchar(60),[SecondaryRoleAllowConnectionsDesc] nvarchar(60),[ReadOnlyRoutingUrl] nvarchar(256));
 CREATE TABLE [#AvailabilityGroups_D]([AgName] sysname,[ReplicaServerName] nvarchar(256),[DatabaseName] sysname,[IsLocal] bit,[IsPrimaryReplica] bit,[SynchronizationStateDesc] nvarchar(60),[SynchronizationHealthDesc] nvarchar(60),[DatabaseStateDesc] nvarchar(60),[IsSuspended] bit,[SuspendReasonDesc] nvarchar(60),[LogSendQueueKb] bigint,[LogSendRateKbSec] bigint,[EstimatedSendSeconds] decimal(19,2),[RedoQueueKb] bigint,[RedoRateKbSec] bigint,[EstimatedRedoSeconds] decimal(19,2),[LastSentTime] datetime,[LastReceivedTime] datetime,[LastHardenedTime] datetime,[LastRedoneTime] datetime,[SecondaryLagSeconds] bigint);
 CREATE TABLE [#AvailabilityGroups_L]([AgName] sysname,[ListenerDnsName] nvarchar(256),[Port] int,[IsConformant] bit,[IpAddress] nvarchar(48),[IpSubnetMask] nvarchar(48),[NetworkSubnetIp] nvarchar(48),[NetworkSubnetPrefixLength] int,[StateDesc] nvarchar(60));
 CREATE TABLE [#AvailabilityGroups_Route]([AgName] sysname,[ReplicaServerName] nvarchar(256),[RoutingPriority] int,[ReadOnlyReplicaServerName] nvarchar(256));
 IF @MaxZeilen<0 SELECT @StatusCode='INVALID_PARAMETER',@ErrorMessage=N'@MaxZeilen darf nicht negativ sein; NULL/0 bedeutet unbegrenzt.';
 IF @ResultSetArtNormalisiert NOT IN ('RAW','CONSOLE','NONE') SELECT @StatusCode='INVALID_PARAMETER',@IsPartial=1,@ErrorMessage=N'@ResultSetArt muss CONSOLE, RAW, TABLE oder NONE enthalten.';
 SET LOCK_TIMEOUT 0;
 IF @StatusCode='AVAILABLE' BEGIN TRY
  IF SERVERPROPERTY('IsHadrEnabled')<>1 BEGIN SET @StatusCode='UNAVAILABLE_FEATURE'; SET @ErrorMessage=N'Always On Availability Groups ist nicht aktiviert.'; END
  ELSE BEGIN
   INSERT [#AvailabilityGroups_R] SELECT TOP (@EffectiveMaxZeilen) [ag].[name],[ar].[replica_server_name],[rs].[is_local],[rs].[role_desc],[rs].[operational_state_desc],[rs].[connected_state_desc],[rs].[recovery_health_desc],[rs].[synchronization_health_desc],[ar].[availability_mode_desc],[ar].[failover_mode_desc],[ar].[session_timeout],[ar].[endpoint_url],[ar].[primary_role_allow_connections_desc],[ar].[secondary_role_allow_connections_desc],[ar].[read_only_routing_url] FROM [sys].[availability_groups] ag WITH (NOLOCK) JOIN [sys].[availability_replicas] ar WITH (NOLOCK) ON [ar].[group_id]=[ag].[group_id] LEFT JOIN [sys].[dm_hadr_availability_replica_states] rs WITH (NOLOCK) ON [rs].[replica_id]=[ar].[replica_id] ORDER BY [ag].[name],[ar].[replica_server_name];
   INSERT [#AvailabilityGroups_D] SELECT TOP (@EffectiveMaxZeilen) [ag].[name],[ar].[replica_server_name],(SELECT [name] FROM [master].[sys].[databases] WITH (NOLOCK) WHERE [database_id] = [drs].[database_id]),[drs].[is_local],sys.fn_hadr_is_primary_replica((SELECT [name] FROM [master].[sys].[databases] WITH (NOLOCK) WHERE [database_id] = [drs].[database_id])),[drs].[synchronization_state_desc],[drs].[synchronization_health_desc],[drs].[database_state_desc],[drs].[is_suspended],[drs].[suspend_reason_desc],[drs].[log_send_queue_size],[drs].[log_send_rate],CONVERT(decimal(19,2),[drs].[log_send_queue_size]*1.0/NULLIF([drs].[log_send_rate],0)),[drs].[redo_queue_size],[drs].[redo_rate],CONVERT(decimal(19,2),[drs].[redo_queue_size]*1.0/NULLIF([drs].[redo_rate],0)),[drs].[last_sent_time],[drs].[last_received_time],[drs].[last_hardened_time],[drs].[last_redone_time],[drs].[secondary_lag_seconds] FROM [sys].[dm_hadr_database_replica_states] drs WITH (NOLOCK) JOIN [sys].[availability_replicas] ar WITH (NOLOCK) ON [ar].[replica_id]=[drs].[replica_id] JOIN [sys].[availability_groups] ag WITH (NOLOCK) ON [ag].[group_id]=[drs].[group_id] ORDER BY [ag].[name],(SELECT [name] FROM [master].[sys].[databases] WITH (NOLOCK) WHERE [database_id] = [drs].[database_id]),[ar].[replica_server_name];
   INSERT [#AvailabilityGroups_L] SELECT TOP (@EffectiveMaxZeilen) [ag].[name],[l].[dns_name],[l].[port],[l].[is_conformant],[ip].[ip_address],[ip].[ip_subnet_mask],[ip].[network_subnet_ip],[ip].[network_subnet_prefix_length],[ip].[state_desc] FROM [sys].[availability_group_listeners] l WITH (NOLOCK) JOIN [sys].[availability_groups] ag WITH (NOLOCK) ON [ag].[group_id]=[l].[group_id] LEFT JOIN [sys].[availability_group_listener_ip_addresses] ip WITH (NOLOCK) ON [ip].[listener_id]=[l].[listener_id] ORDER BY [ag].[name],[l].[dns_name],[ip].[ip_address];
   IF @MitRouting=1 INSERT [#AvailabilityGroups_Route] SELECT TOP (@EffectiveMaxZeilen) [ag].[name],[ar].[replica_server_name],[rl].[routing_priority],[ar2].[replica_server_name] FROM [sys].[availability_read_only_routing_lists] rl WITH (NOLOCK) JOIN [sys].[availability_replicas] ar WITH (NOLOCK) ON [ar].[replica_id]=[rl].[replica_id] JOIN [sys].[availability_replicas] ar2 WITH (NOLOCK) ON [ar2].[replica_id]=[rl].[read_only_replica_id] JOIN [sys].[availability_groups] ag WITH (NOLOCK) ON [ag].[group_id]=[ar].[group_id] ORDER BY [ag].[name],[ar].[replica_server_name],[rl].[routing_priority];
  END
 END TRY BEGIN CATCH SELECT @StatusCode='ERROR_HANDLED',@IsPartial=1,@ErrorNumber=ERROR_NUMBER(),@ErrorMessage=ERROR_MESSAGE(); IF @PrintMeldungen=1 RAISERROR(N'Availability Groups konnten nicht vollständig gelesen werden: %s',10,1,@ErrorMessage) WITH NOWAIT; END CATCH;

 IF @ResultSetArtNormalisiert<>'NONE'
 BEGIN
  SELECT @CollectionTimeUtc AS [CollectionTimeUtc],CAST(N'monitor.USP_AvailabilityGroups' AS nvarchar(256)) AS [ModuleName],@StatusCode AS [StatusCode],@IsPartial AS [IsPartial],@ErrorNumber AS [ErrorNumber],@ErrorMessage AS [ErrorMessage];
  IF @ResultSetArtNormalisiert='RAW'
  BEGIN
   SELECT * FROM [#AvailabilityGroups_R] ORDER BY [AgName],[ReplicaServerName];
   SELECT * FROM [#AvailabilityGroups_D] ORDER BY [AgName],[DatabaseName],[ReplicaServerName];
   SELECT * FROM [#AvailabilityGroups_L] ORDER BY [AgName],[ListenerDnsName],[IpAddress];
   SELECT * FROM [#AvailabilityGroups_Route] ORDER BY [AgName],[ReplicaServerName],[RoutingPriority];
  END
  ELSE
  BEGIN
   SELECT N'Availability-Group-Replikat' AS [Ergebnis],[x].* FROM [#AvailabilityGroups_R] AS [x] ORDER BY [AgName],[ReplicaServerName];
   SELECT N'Availability-Group-Datenbank' AS [Ergebnis],[x].*,CONCAT(CONVERT(decimal(19,2),[LogSendQueueKb]/1024.0),N' MB') AS [Send-Queue],CONCAT(CONVERT(decimal(19,2),[RedoQueueKb]/1024.0),N' MB') AS [Redo-Queue] FROM [#AvailabilityGroups_D] AS [x] ORDER BY [AgName],[DatabaseName],[ReplicaServerName];
   SELECT N'Availability-Group-Listener' AS [Ergebnis],[x].* FROM [#AvailabilityGroups_L] AS [x] ORDER BY [AgName],[ListenerDnsName],[IpAddress];
   SELECT N'Read-Only-Routing' AS [Ergebnis],[x].* FROM [#AvailabilityGroups_Route] AS [x] ORDER BY [AgName],[ReplicaServerName],[RoutingPriority];
  END
 END;
 IF @JsonErzeugen=1
 BEGIN
  DECLARE @MetaJson nvarchar(max)=(SELECT N'AvailabilityGroups' [resultName],1 [schemaVersion],@CollectionTimeUtc [generatedAtUtc],@StatusCode [statusCode],@IsPartial [isPartial],@ErrorNumber [errorNumber],@ErrorMessage [errorMessage] FOR JSON PATH,WITHOUT_ARRAY_WRAPPER,INCLUDE_NULL_VALUES);
  DECLARE @ReplicasJson nvarchar(max)=(SELECT * FROM [#AvailabilityGroups_R] ORDER BY [AgName],[ReplicaServerName] FOR JSON PATH,INCLUDE_NULL_VALUES);
  DECLARE @DatabasesJson nvarchar(max)=(SELECT * FROM [#AvailabilityGroups_D] ORDER BY [AgName],[DatabaseName],[ReplicaServerName] FOR JSON PATH,INCLUDE_NULL_VALUES);
  DECLARE @ListenersJson nvarchar(max)=(SELECT * FROM [#AvailabilityGroups_L] ORDER BY [AgName],[ListenerDnsName],[IpAddress] FOR JSON PATH,INCLUDE_NULL_VALUES);
  DECLARE @RoutingJson nvarchar(max)=(SELECT * FROM [#AvailabilityGroups_Route] ORDER BY [AgName],[ReplicaServerName],[RoutingPriority] FOR JSON PATH,INCLUDE_NULL_VALUES);
  SET @Json=CONCAT(N'{"meta":',COALESCE(@MetaJson,N'{}'),N',"replicas":',COALESCE(@ReplicasJson,N'[]'),N',"databases":',COALESCE(@DatabasesJson,N'[]'),N',"listeners":',COALESCE(@ListenersJson,N'[]'),N',"routing":',COALESCE(@RoutingJson,N'[]'),N'}');
 END;
    IF @ConsoleResultRequested = 1
    BEGIN
        EXEC [monitor].[InternalEmitConsoleResult]
              @SourceTable=N'#AvailabilityGroups_R'
            , @ResultLabel=N'AvailabilityGroups'
            , @EmptyMessage=N'Keine fachlichen Ergebnisse';
    END;
    IF @TableResultRequested = 1
    BEGIN
        EXEC [monitor].[InternalWriteResultTable]
              @SourceTable = N'#AvailabilityGroups_R'
            , @TargetTable=@TableTarget
            , @ThrowOnError = 1;
    END;
END;
GO
-- END SOURCE: Code/07_Infrastructure/040_USP_AvailabilityGroups.sql

-- BEGIN SOURCE: Code/07_Infrastructure/050_USP_BackupRecovery.sql
/*
===============================================================================
Objekt       : monitor.USP_BackupRecovery
Version      : 2.0.0
Stand        : 2026-07-15
Typ          : Stored Procedure
Zweck        : Bewertet Backup-Aktualität und Restore-Historie je ausgewählter
               sichtbarer Datenbank.
SQL-Version  : SQL Server 2019 oder neuer.
Filter       : @DatabaseNames als bracket-aware Pipe-Liste oder alternativ
               @DatabaseNamePattern mit LIKE/regex/regexi.
Resultsets   : RAW oder CONSOLE: Modulstatus, Datenbankstatus, Backup-Aktualität,
               Backup-Historie und Restore-Historie. NONE: keine Resultsets.
JSON         : meta, databaseStatus, freshness, backups, restores, warnings.
Änderungen   : 2.0.0 - Mehrfachfilter, Patternvertrag und Ausgabeadapter.
               1.0.0 - Erstfassung Phase 6.
===============================================================================
*/
CREATE OR ALTER PROCEDURE [monitor].[USP_BackupRecovery]
      @DatabaseNames                  nvarchar(max)  = NULL
    , @SystemdatenbankenEinbeziehen   bit            = 0
    , @DatabaseNamePattern            nvarchar(4000) = NULL
    , @HighImpactConfirmed              bit            = 0
    , @FullWarnHours                  int            = 48
    , @DiffWarnHours                  int            = 24
    , @LogWarnMinutes                 int            = 30
    , @MitRestoreHistory              bit            = 1
    , @MaxZeilen                      int            = 5000
    , @ResultSetArt                   varchar(16)    = 'CONSOLE'
    , @ResultTablesJson               nvarchar(max) = NULL
    , @JsonErzeugen                   bit            = 0
    , @Json                           nvarchar(max)  = NULL OUTPUT
    , @PrintMeldungen                 bit            = 1
    , @Hilfe                          bit            = 0
AS
BEGIN
    SET NOCOUNT ON;

    SET @Json = NULL;

    DECLARE @ResultSetArtNormalisiert varchar(16) = UPPER(LTRIM(RTRIM(COALESCE(@ResultSetArt, ''))));
    DECLARE @TableResultRequested bit = CASE WHEN @ResultSetArtNormalisiert = 'TABLE' THEN 1 ELSE 0 END;
    DECLARE @ConsoleResultRequested bit = CASE WHEN @ResultSetArtNormalisiert = 'CONSOLE' THEN 1 ELSE 0 END;
    DECLARE @TableTarget sysname=NULL;
    IF @TableResultRequested=0 AND NULLIF(LTRIM(RTRIM(COALESCE(@ResultTablesJson,N''))),N'') IS NOT NULL THROW 51011,N'@ResultTablesJson ist ausschließlich mit @ResultSetArt=TABLE zulässig.',1;
    IF @TableResultRequested=1 EXEC [monitor].[InternalPrepareSingleResultTable] @ResultTablesJson=@ResultTablesJson,@ResultName=N'freshness',@TargetTable=@TableTarget OUTPUT,@ThrowOnError=1;
    IF @TableResultRequested = 1 OR @ConsoleResultRequested = 1 SET @ResultSetArtNormalisiert = 'NONE';
    DECLARE @EffectiveMaxZeilen bigint =
        CASE WHEN @MaxZeilen IS NULL OR @MaxZeilen = 0
             THEN CONVERT(bigint, 9223372036854775807)
             ELSE CONVERT(bigint, @MaxZeilen) END;

    IF @Hilfe = 1
    BEGIN
        PRINT N'monitor.USP_BackupRecovery';
        PRINT N'@DatabaseNames: exakter Name oder bracket-aware Pipe-Liste; NULL = alle zulässigen Datenbanken.';
        PRINT N'@DatabaseNamePattern: alternatives LIKE-/Regex-Pattern; Liste und Pattern sind gegenseitig exklusiv.';
        PRINT N'Die Datenbankauswahl wird nicht vorab begrenzt.';
        PRINT N'@FullWarnHours=48; @DiffWarnHours=24; @LogWarnMinutes=30; @MitRestoreHistory=1.';
        PRINT N'@MaxZeilen: positive Werte begrenzen; NULL/0 = unbegrenzt.';
        PRINT N'@ResultSetArt=CONSOLE (Default)|RAW|TABLE|NONE case-insensitiv; @JsonErzeugen=1 setzt @Json OUTPUT.';
        RETURN;
    END;

    DECLARE @CollectionTimeUtc datetime2(3) = SYSUTCDATETIME();
    DECLARE @StatusCode varchar(40) = 'AVAILABLE';
    DECLARE @IsPartial bit = 0;
    DECLARE @ErrorNumber int = NULL;
    DECLARE @ErrorMessage nvarchar(2048) = NULL;
    DECLARE @CrossDatabaseRequested bit = 0;

    CREATE TABLE [#BackupRecovery_DatabaseCandidates]
    (
          [DatabaseId] int NOT NULL
        , [DatabaseName] sysname NOT NULL
        , [StateDesc] nvarchar(60) NULL
        , [UserAccessDesc] nvarchar(60) NULL
        , [IsReadOnly] bit NULL
        , [CompatibilityLevel] tinyint NULL
        , [CollationName] sysname NULL
        , [RecoveryModelDesc] nvarchar(60) NULL
        , [IsSystemDatabase] bit NULL
        , [RequestedOrdinal] int NULL
    );

    CREATE TABLE [#BackupRecovery_DatabaseCandidateWarnings]
    (
          [RequestedName] sysname NULL
        , [StatusCode] varchar(40) NOT NULL
        , [ErrorMessage] nvarchar(2048) NULL
    );

    CREATE TABLE [#BackupRecovery_Fresh]
    (
          [DatabaseName] sysname
        , [StateDesc] nvarchar(60)
        , [RecoveryModelDesc] nvarchar(60)
        , [LastFullFinish] datetime
        , [FullAgeMinutes] int
        , [LastDiffFinish] datetime
        , [DiffAgeMinutes] int
        , [LastLogFinish] datetime
        , [LogAgeMinutes] int
        , [LastCopyOnlyFullFinish] datetime
        , [BackupStatus] varchar(100)
    );

    CREATE TABLE [#BackupRecovery_Backups]
    (
          [DatabaseName] sysname
        , [BackupType] char(1)
        , [BackupTypeDesc] nvarchar(60)
        , [BackupStartDate] datetime
        , [BackupFinishDate] datetime
        , [DurationSeconds] int
        , [BackupSizeMb] decimal(19,2)
        , [CompressedSizeMb] decimal(19,2)
        , [IsCopyOnly] bit
        , [IsSnapshot] bit
        , [HasBackupChecksums] bit
        , [IsDamaged] bit
        , [MediaPath] nvarchar(4000)
    );

    CREATE TABLE [#BackupRecovery_Restores]
    (
          [DestinationDatabaseName] sysname
        , [RestoreDate] datetime
        , [UserName] sysname
        , [RestoreType] char(1)
        , [Replace] bit
        , [Recovery] bit
        , [Restart] bit
        , [SourceDatabaseName] sysname
        , [BackupFinishDate] datetime
    );

    IF @MaxZeilen < 0

       OR @FullWarnHours < 1
       OR @DiffWarnHours < 1
       OR @LogWarnMinutes < 1
       OR @ResultSetArtNormalisiert NOT IN ('RAW', 'CONSOLE', 'NONE')
    BEGIN
        SET @StatusCode = 'INVALID_PARAMETER';
        SET @IsPartial = 1;
        SET @ErrorMessage = N'Ungültige Grenzwert- oder Ausgabeparameter.';
    END;

    IF @StatusCode = 'AVAILABLE'
    BEGIN
        EXEC [monitor].[USP_PrepareDatabaseCandidates]
              @DatabaseNames = @DatabaseNames
            , @SystemdatenbankenEinbeziehen = @SystemdatenbankenEinbeziehen
            , @DatabaseNamePattern = @DatabaseNamePattern,@HighImpactConfirmed=@HighImpactConfirmed

            , @AnalysisClass = NULL
            , @StatusCode = @StatusCode OUTPUT
            , @ErrorMessage = @ErrorMessage OUTPUT
            , @CrossDatabaseRequested = @CrossDatabaseRequested OUTPUT,@CandidateTable=N'#BackupRecovery_DatabaseCandidates',@WarningTable=N'#BackupRecovery_DatabaseCandidateWarnings';
    END;

    IF @StatusCode <> 'AVAILABLE'
        SET @IsPartial = 1;

    SET LOCK_TIMEOUT 0;

    IF @StatusCode = 'AVAILABLE'
    BEGIN TRY
        ;WITH [LastBackups] AS
        (
            SELECT
                  [bs].[database_name]
                , MAX(CASE WHEN [bs].[type] = 'D' AND [bs].[is_copy_only] = 0 THEN [bs].[backup_finish_date] END) AS [FullFinish]
                , MAX(CASE WHEN [bs].[type] = 'I' THEN [bs].[backup_finish_date] END) AS [DiffFinish]
                , MAX(CASE WHEN [bs].[type] = 'L' THEN [bs].[backup_finish_date] END) AS [LogFinish]
                , MAX(CASE WHEN [bs].[type] = 'D' AND [bs].[is_copy_only] = 1 THEN [bs].[backup_finish_date] END) AS [CopyOnlyFinish]
            FROM [msdb].[dbo].[backupset] AS [bs] WITH (NOLOCK)
            JOIN [#BackupRecovery_DatabaseCandidates] AS [c]
              ON [c].[DatabaseName] COLLATE SQL_Latin1_General_CP1_CS_AS
               = [bs].[database_name] COLLATE SQL_Latin1_General_CP1_CS_AS
            GROUP BY [bs].[database_name]
        )
        INSERT [#BackupRecovery_Fresh]
        SELECT
              [c].[DatabaseName]
            , [c].[StateDesc]
            , [c].[RecoveryModelDesc]
            , [x].[FullFinish]
            , DATEDIFF(MINUTE, [x].[FullFinish], GETDATE())
            , [x].[DiffFinish]
            , DATEDIFF(MINUTE, [x].[DiffFinish], GETDATE())
            , [x].[LogFinish]
            , DATEDIFF(MINUTE, [x].[LogFinish], GETDATE())
            , [x].[CopyOnlyFinish]
            , CASE
                  WHEN [c].[DatabaseId] = 2 THEN 'TEMPDB_NO_BACKUP'
                  WHEN [x].[FullFinish] IS NULL THEN 'NO_FULL_BACKUP'
                  WHEN DATEDIFF(HOUR, [x].[FullFinish], GETDATE()) > @FullWarnHours THEN 'FULL_TOO_OLD'
                  WHEN [c].[RecoveryModelDesc] IN (N'FULL', N'BULK_LOGGED') AND [x].[LogFinish] IS NULL THEN 'NO_LOG_BACKUP'
                  WHEN [c].[RecoveryModelDesc] IN (N'FULL', N'BULK_LOGGED')
                   AND DATEDIFF(MINUTE, [x].[LogFinish], GETDATE()) > @LogWarnMinutes THEN 'LOG_TOO_OLD'
                  WHEN [x].[DiffFinish] IS NOT NULL
                   AND DATEDIFF(HOUR, [x].[DiffFinish], GETDATE()) > @DiffWarnHours THEN 'DIFF_OLD_INFORMATIONAL'
                  ELSE 'OK'
              END
        FROM [#BackupRecovery_DatabaseCandidates] AS [c]
        LEFT JOIN [LastBackups] AS [x]
          ON [x].[database_name] COLLATE SQL_Latin1_General_CP1_CS_AS
           = [c].[DatabaseName] COLLATE SQL_Latin1_General_CP1_CS_AS;

        INSERT [#BackupRecovery_Backups]
        SELECT TOP (@EffectiveMaxZeilen)
              [bs].[database_name]
            , [bs].[type]
            , CASE [bs].[type] WHEN 'D' THEN N'DATABASE' WHEN 'I' THEN N'DIFFERENTIAL'
                   WHEN 'L' THEN N'LOG' WHEN 'F' THEN N'FILE_OR_FILEGROUP'
                   WHEN 'G' THEN N'DIFF_FILE' WHEN 'P' THEN N'PARTIAL'
                   WHEN 'Q' THEN N'DIFF_PARTIAL' END
            , [bs].[backup_start_date]
            , [bs].[backup_finish_date]
            , DATEDIFF(SECOND, [bs].[backup_start_date], [bs].[backup_finish_date])
            , CONVERT(decimal(19,2), [bs].[backup_size] / 1048576.0)
            , CONVERT(decimal(19,2), [bs].[compressed_backup_size] / 1048576.0)
            , [bs].[is_copy_only]
            , CAST(NULL AS bit)
            , [bs].[has_backup_checksums]
            , [bs].[is_damaged]
            , [bmf].[physical_device_name]
        FROM [msdb].[dbo].[backupset] AS [bs] WITH (NOLOCK)
        JOIN [#BackupRecovery_DatabaseCandidates] AS [c]
          ON [c].[DatabaseName] COLLATE SQL_Latin1_General_CP1_CS_AS
           = [bs].[database_name] COLLATE SQL_Latin1_General_CP1_CS_AS
        LEFT JOIN [msdb].[dbo].[backupmediafamily] AS [bmf] WITH (NOLOCK)
          ON [bmf].[media_set_id] = [bs].[media_set_id]
        ORDER BY [bs].[backup_finish_date] DESC, [bs].[backup_set_id] DESC;

        IF @MitRestoreHistory = 1
        BEGIN
            INSERT [#BackupRecovery_Restores]
            SELECT TOP (@EffectiveMaxZeilen)
                  [rh].[destination_database_name]
                , [rh].[restore_date]
                , [rh].[user_name]
                , [rh].[restore_type]
                , [rh].[replace]
                , [rh].[recovery]
                , [rh].[restart]
                , [bs].[database_name]
                , [bs].[backup_finish_date]
            FROM [msdb].[dbo].[restorehistory] AS [rh] WITH (NOLOCK)
            JOIN [#BackupRecovery_DatabaseCandidates] AS [c]
              ON [c].[DatabaseName] COLLATE SQL_Latin1_General_CP1_CS_AS
               = [rh].[destination_database_name] COLLATE SQL_Latin1_General_CP1_CS_AS
            LEFT JOIN [msdb].[dbo].[backupset] AS [bs] WITH (NOLOCK)
              ON [bs].[backup_set_id] = [rh].[backup_set_id]
            ORDER BY [rh].[restore_date] DESC, [rh].[restore_history_id] DESC;
        END;

        IF EXISTS (SELECT 1 FROM [#BackupRecovery_DatabaseCandidateWarnings])
        BEGIN
            SET @StatusCode = 'AVAILABLE_LIMITED';
            SET @IsPartial = 1;
        END;
    END TRY
    BEGIN CATCH
        SELECT
              @StatusCode = 'ERROR_HANDLED'
            , @IsPartial = 1
            , @ErrorNumber = ERROR_NUMBER()
            , @ErrorMessage = ERROR_MESSAGE();

        IF @PrintMeldungen = 1
            RAISERROR(N'Backup-/Restore-Historie konnte nicht vollständig gelesen werden: %s', 10, 1, @ErrorMessage) WITH NOWAIT;
    END CATCH;

    IF @ResultSetArtNormalisiert <> 'NONE'
    BEGIN
        SELECT
              @CollectionTimeUtc AS [CollectionTimeUtc]
            , CAST(N'monitor.USP_BackupRecovery' AS nvarchar(256)) AS [ModuleName]
            , @StatusCode AS [StatusCode]
            , @IsPartial AS [IsPartial]
            , @ErrorNumber AS [ErrorNumber]
            , @ErrorMessage AS [ErrorMessage];

        SELECT
              [RequestedName], [StatusCode], [ErrorMessage]
        FROM [#BackupRecovery_DatabaseCandidateWarnings]
        ORDER BY [RequestedName];

        IF @ResultSetArtNormalisiert = 'RAW'
        BEGIN
            SELECT * FROM [#BackupRecovery_Fresh] ORDER BY CASE WHEN [BackupStatus] = 'OK' THEN 1 ELSE 0 END, [DatabaseName];
            SELECT * FROM [#BackupRecovery_Backups] ORDER BY [BackupFinishDate] DESC, [DatabaseName];
            SELECT * FROM [#BackupRecovery_Restores] ORDER BY [RestoreDate] DESC, [DestinationDatabaseName];
        END;
        ELSE
        BEGIN
            SELECT
                  N'Backup-Aktualität' AS [Ergebnis]
                , [DatabaseName] AS [Datenbank]
                , [RecoveryModelDesc] AS [Recovery Model]
                , [BackupStatus] AS [Bewertung]
                , [LastFullFinish] AS [Letztes Full]
                , CASE WHEN [FullAgeMinutes] IS NULL THEN NULL ELSE CONCAT([FullAgeMinutes], N' min') END AS [Full-Alter]
                , [LastDiffFinish] AS [Letztes Diff]
                , CASE WHEN [DiffAgeMinutes] IS NULL THEN NULL ELSE CONCAT([DiffAgeMinutes], N' min') END AS [Diff-Alter]
                , [LastLogFinish] AS [Letztes Log]
                , CASE WHEN [LogAgeMinutes] IS NULL THEN NULL ELSE CONCAT([LogAgeMinutes], N' min') END AS [Log-Alter]
            FROM [#BackupRecovery_Fresh]
            ORDER BY CASE WHEN [BackupStatus] = 'OK' THEN 1 ELSE 0 END, [DatabaseName];

            SELECT N'Backup-Historie' AS [Ergebnis], [x].* FROM [#BackupRecovery_Backups] AS [x] ORDER BY [BackupFinishDate] DESC, [DatabaseName];
            SELECT N'Restore-Historie' AS [Ergebnis], [x].* FROM [#BackupRecovery_Restores] AS [x] ORDER BY [RestoreDate] DESC, [DestinationDatabaseName];
        END;
    END;

    IF @JsonErzeugen = 1
    BEGIN
        DECLARE @MetaJson nvarchar(max) =
        (
            SELECT
                  N'BackupRecovery' AS [resultName]
                , 1 AS [schemaVersion]
                , @CollectionTimeUtc AS [generatedAtUtc]
                , @StatusCode AS [statusCode]
                , @IsPartial AS [isPartial]
                , @MaxZeilen AS [requestedMaxRows]
                , @ErrorNumber AS [errorNumber]
                , @ErrorMessage AS [errorMessage]
            FOR JSON PATH, WITHOUT_ARRAY_WRAPPER, INCLUDE_NULL_VALUES
        );
        DECLARE @FreshJson nvarchar(max) =
            (SELECT * FROM [#BackupRecovery_Fresh] ORDER BY CASE WHEN [BackupStatus] = 'OK' THEN 1 ELSE 0 END, [DatabaseName] FOR JSON PATH, INCLUDE_NULL_VALUES);
        DECLARE @BackupsJson nvarchar(max) =
            (SELECT * FROM [#BackupRecovery_Backups] ORDER BY [BackupFinishDate] DESC, [DatabaseName] FOR JSON PATH, INCLUDE_NULL_VALUES);
        DECLARE @RestoresJson nvarchar(max) =
            (SELECT * FROM [#BackupRecovery_Restores] ORDER BY [RestoreDate] DESC, [DestinationDatabaseName] FOR JSON PATH, INCLUDE_NULL_VALUES);
        DECLARE @WarningsJson nvarchar(max) =
            (SELECT * FROM [#BackupRecovery_DatabaseCandidateWarnings] ORDER BY [RequestedName] FOR JSON PATH, INCLUDE_NULL_VALUES);

        SET @Json = CONCAT
        (
              N'{"meta":', COALESCE(@MetaJson, N'{}')
            , N',"freshness":', COALESCE(@FreshJson, N'[]')
            , N',"backups":', COALESCE(@BackupsJson, N'[]')
            , N',"restores":', COALESCE(@RestoresJson, N'[]')
            , N',"warnings":', COALESCE(@WarningsJson, N'[]')
            , N'}'
        );
    END;
    IF @ConsoleResultRequested = 1
    BEGIN
        EXEC [monitor].[InternalEmitConsoleResult]
              @SourceTable=N'#BackupRecovery_Fresh'
            , @ResultLabel=N'BackupRecovery'
            , @EmptyMessage=N'Keine fachlichen Ergebnisse';
    END;
    IF @TableResultRequested = 1
    BEGIN
        EXEC [monitor].[InternalWriteResultTable]
              @SourceTable = N'#BackupRecovery_Fresh'
            , @TargetTable=@TableTarget
            , @ThrowOnError = 1;
    END;
END;
GO
-- END SOURCE: Code/07_Infrastructure/050_USP_BackupRecovery.sql

-- BEGIN SOURCE: Code/07_Infrastructure/060_USP_LogShippingStatus.sql
/*
===============================================================================
Objekt       : monitor.USP_LogShippingStatus
Version      : 1.0.1
Stand        : 2026-07-14
Typ          : Stored Procedure
Zweck        : Liest vorhandene Log-Shipping-Konfiguration und Monitorzustände für Primary- und Secondary-Datenbanken.
SQL-Version  : SQL Server 2019 oder neuer.
Datenquellen : msdb.dbo.log_shipping_primary_databases, log_shipping_monitor_primary, log_shipping_monitor_secondary, log_shipping_secondary_databases
Parameter    : @MaxZeilen, @PrintMeldungen, @Hilfe
Resultsets   : 1. Modulstatus. 2. Primary. 3. Secondary.
Berechtigung : Nur lesender Zugriff auf die genannten Systemobjekte. Das
               Framework vergibt keine Rechte und ändert keine Konfiguration.
Eigenlast    : Gering.
Locking      : LOCK_TIMEOUT 0; keine fachlichen Schreibzugriffe.
Partial      : Fehlende Features, Objekte oder Rechte werden strukturiert als
               Partial Result behandelt; andere Module bleiben ausführbar.
Änderungen   : 1.0.1 - Alertschwellen und History-Retention aus den
               Log-Shipping-Monitor-Tabellen gelesen.
               1.0.0 - Erstfassung Phase 6.
===============================================================================
*/
CREATE OR ALTER PROCEDURE [monitor].[USP_LogShippingStatus]
 @MaxZeilen int=5000,@ResultSetArt varchar(16)='CONSOLE'
    , @ResultTablesJson               nvarchar(max) = NULL
    , @JsonErzeugen bit=0,@Json nvarchar(max)=NULL OUTPUT,@PrintMeldungen bit=1,@Hilfe bit=0
AS
BEGIN
 SET NOCOUNT ON;
 SET @Json=NULL;
 DECLARE @ResultSetArtNormalisiert varchar(16)=UPPER(LTRIM(RTRIM(COALESCE(@ResultSetArt,''))));
    DECLARE @TableResultRequested bit = CASE WHEN @ResultSetArtNormalisiert = 'TABLE' THEN 1 ELSE 0 END;
    DECLARE @ConsoleResultRequested bit = CASE WHEN @ResultSetArtNormalisiert = 'CONSOLE' THEN 1 ELSE 0 END;
    DECLARE @TableTarget sysname=NULL;
    IF @TableResultRequested=0 AND NULLIF(LTRIM(RTRIM(COALESCE(@ResultTablesJson,N''))),N'') IS NOT NULL THROW 51011,N'@ResultTablesJson ist ausschließlich mit @ResultSetArt=TABLE zulässig.',1;
    IF @TableResultRequested=1 EXEC [monitor].[InternalPrepareSingleResultTable] @ResultTablesJson=@ResultTablesJson,@ResultName=N'primary',@TargetTable=@TableTarget OUTPUT,@ThrowOnError=1;
    IF @TableResultRequested = 1 OR @ConsoleResultRequested = 1 SET @ResultSetArtNormalisiert = 'NONE';
    DECLARE @EffectiveMaxZeilen bigint = CASE WHEN @MaxZeilen IS NULL OR @MaxZeilen=0 THEN CONVERT(bigint,9223372036854775807) ELSE CONVERT(bigint,@MaxZeilen) END;
 IF @Hilfe=1 BEGIN PRINT N'monitor.USP_LogShippingStatus'; PRINT N'@MaxZeilen int=5000: positive Werte begrenzen; NULL/0 = unbegrenzt; negative Werte sind ungültig. @PrintMeldungen bit=1; @Hilfe bit=0.'; RETURN; END;
 DECLARE @CollectionTimeUtc datetime2(3)=SYSUTCDATETIME(),@StatusCode varchar(40)='AVAILABLE',@IsPartial bit=0,@ErrorNumber int=NULL,@ErrorMessage nvarchar(2048)=NULL;
 IF @MaxZeilen<0 SELECT @StatusCode='INVALID_PARAMETER',@IsPartial=1,@ErrorMessage=N'@MaxZeilen darf nicht negativ sein; NULL/0 bedeutet unbegrenzt.';
 CREATE TABLE [#LogShippingStatus_P]([PrimaryServer] sysname,[PrimaryDatabase] sysname,[BackupDirectory] nvarchar(500),[BackupShare] nvarchar(500),[BackupRetentionPeriod] int,[BackupThreshold] int,[ThresholdAlertEnabled] bit,[LastBackupFile] nvarchar(500),[LastBackupDate] datetime,[BackupAgeMinutes] int,[LastBackupDateUtc] datetime,[HistoryRetentionPeriod] int);
 CREATE TABLE [#LogShippingStatus_S]([SecondaryServer] sysname,[SecondaryDatabase] sysname,[PrimaryServer] sysname,[PrimaryDatabase] sysname,[RestoreDelay] int,[RestoreThreshold] int,[ThresholdAlertEnabled] bit,[LastCopiedFile] nvarchar(500),[LastCopiedDate] datetime,[CopyAgeMinutes] int,[LastRestoredFile] nvarchar(500),[LastRestoredDate] datetime,[RestoreAgeMinutes] int,[LastRestoredLatency] int,[RestoreMode] int,[DisconnectUsers] bit);
 IF @ResultSetArtNormalisiert NOT IN ('RAW','CONSOLE','NONE') SELECT @StatusCode='INVALID_PARAMETER',@IsPartial=1,@ErrorMessage=N'@ResultSetArt muss CONSOLE, RAW, TABLE oder NONE enthalten.';
 SET LOCK_TIMEOUT 0;
 IF @StatusCode='AVAILABLE'
 BEGIN
  BEGIN TRY
  IF (SELECT COUNT(*)
      FROM [msdb].[sys].[tables] AS [t] WITH (NOLOCK)
      JOIN [msdb].[sys].[schemas] AS [s] WITH (NOLOCK)
        ON [s].[schema_id]=[t].[schema_id]
      WHERE [s].[name]=N'dbo'
        AND [t].[name] IN
            (N'log_shipping_primary_databases',N'log_shipping_monitor_primary',N'log_shipping_secondary_databases',N'log_shipping_monitor_secondary'))<>4
  BEGIN
   SET @StatusCode='UNAVAILABLE_FEATURE';
   SET @ErrorMessage=N'Erforderliche Log-Shipping-Konfigurations- oder Monitor-Tabellen sind nicht vorhanden.';
  END
  ELSE BEGIN
   INSERT [#LogShippingStatus_P]
   (
       [PrimaryServer], [PrimaryDatabase], [BackupDirectory], [BackupShare],
       [BackupRetentionPeriod], [BackupThreshold], [ThresholdAlertEnabled],
       [LastBackupFile], [LastBackupDate], [BackupAgeMinutes],
       [LastBackupDateUtc], [HistoryRetentionPeriod]
   )
   SELECT TOP (@EffectiveMaxZeilen)
       [mp].[primary_server], [p].[primary_database], [p].[backup_directory],
       [p].[backup_share], [p].[backup_retention_period], [mp].[backup_threshold],
       [mp].[threshold_alert_enabled], [mp].[last_backup_file],
       [mp].[last_backup_date], DATEDIFF(MINUTE, [mp].[last_backup_date], GETDATE()),
       [mp].[last_backup_date_utc], [mp].[history_retention_period]
   FROM [msdb].[dbo].[log_shipping_primary_databases] AS [p] WITH (NOLOCK)
   LEFT JOIN [msdb].[dbo].[log_shipping_monitor_primary] AS [mp] WITH (NOLOCK)
     ON [mp].[primary_id] = [p].[primary_id]
   ORDER BY [p].[primary_database];

   INSERT [#LogShippingStatus_S]
   (
       [SecondaryServer], [SecondaryDatabase], [PrimaryServer], [PrimaryDatabase],
       [RestoreDelay], [RestoreThreshold], [ThresholdAlertEnabled],
       [LastCopiedFile], [LastCopiedDate], [CopyAgeMinutes],
       [LastRestoredFile], [LastRestoredDate], [RestoreAgeMinutes],
       [LastRestoredLatency], [RestoreMode], [DisconnectUsers]
   )
   SELECT TOP (@EffectiveMaxZeilen)
       [ms].[secondary_server], [s].[secondary_database], [ms].[primary_server],
       [ms].[primary_database], [s].[restore_delay], [ms].[restore_threshold],
       [ms].[threshold_alert_enabled], [ms].[last_copied_file],
       [ms].[last_copied_date], DATEDIFF(MINUTE, [ms].[last_copied_date], GETDATE()),
       [ms].[last_restored_file], [ms].[last_restored_date],
       DATEDIFF(MINUTE, [ms].[last_restored_date], GETDATE()),
       [ms].[last_restored_latency], [s].[restore_mode], [s].[disconnect_users]
   FROM [msdb].[dbo].[log_shipping_secondary_databases] AS [s] WITH (NOLOCK)
   LEFT JOIN [msdb].[dbo].[log_shipping_monitor_secondary] AS [ms] WITH (NOLOCK)
     ON [ms].[secondary_id] = [s].[secondary_id]
   ORDER BY [s].[secondary_database];
  END
  END TRY BEGIN CATCH SELECT @StatusCode='ERROR_HANDLED',@IsPartial=1,@ErrorNumber=ERROR_NUMBER(),@ErrorMessage=ERROR_MESSAGE(); IF @PrintMeldungen=1 RAISERROR(N'Log Shipping konnte nicht vollständig gelesen werden: %s',10,1,@ErrorMessage) WITH NOWAIT; END CATCH;
 END;

 IF @ResultSetArtNormalisiert<>'NONE'
 BEGIN
  SELECT @CollectionTimeUtc AS [CollectionTimeUtc],CAST(N'monitor.USP_LogShippingStatus' AS nvarchar(256)) AS [ModuleName],@StatusCode AS [StatusCode],@IsPartial AS [IsPartial],@ErrorNumber AS [ErrorNumber],@ErrorMessage AS [ErrorMessage];
  IF @ResultSetArtNormalisiert='RAW'
  BEGIN SELECT * FROM [#LogShippingStatus_P] ORDER BY [PrimaryDatabase];SELECT * FROM [#LogShippingStatus_S] ORDER BY [SecondaryDatabase];END
  ELSE
  BEGIN
   SELECT N'Log-Shipping Primary' AS [Ergebnis],[x].*,CASE WHEN [BackupAgeMinutes] IS NULL THEN N'kein Zeitpunkt' ELSE CONCAT([BackupAgeMinutes],N' min') END AS [Backup-Alter] FROM [#LogShippingStatus_P] AS [x] ORDER BY [PrimaryDatabase];
   SELECT N'Log-Shipping Secondary' AS [Ergebnis],[x].*,CASE WHEN [RestoreAgeMinutes] IS NULL THEN N'kein Zeitpunkt' ELSE CONCAT([RestoreAgeMinutes],N' min') END AS [Restore-Alter] FROM [#LogShippingStatus_S] AS [x] ORDER BY [SecondaryDatabase];
  END
 END;
 IF @JsonErzeugen=1
 BEGIN
  DECLARE @MetaJson nvarchar(max)=(SELECT N'LogShippingStatus' [resultName],1 [schemaVersion],@CollectionTimeUtc [generatedAtUtc],@StatusCode [statusCode],@IsPartial [isPartial],@ErrorNumber [errorNumber],@ErrorMessage [errorMessage] FOR JSON PATH,WITHOUT_ARRAY_WRAPPER,INCLUDE_NULL_VALUES);
  DECLARE @PrimaryJson nvarchar(max)=(SELECT * FROM [#LogShippingStatus_P] ORDER BY [PrimaryDatabase] FOR JSON PATH,INCLUDE_NULL_VALUES);
  DECLARE @SecondaryJson nvarchar(max)=(SELECT * FROM [#LogShippingStatus_S] ORDER BY [SecondaryDatabase] FOR JSON PATH,INCLUDE_NULL_VALUES);
  SET @Json=CONCAT(N'{"meta":',COALESCE(@MetaJson,N'{}'),N',"primary":',COALESCE(@PrimaryJson,N'[]'),N',"secondary":',COALESCE(@SecondaryJson,N'[]'),N'}');
 END;
    IF @ConsoleResultRequested = 1
    BEGIN
        EXEC [monitor].[InternalEmitConsoleResult]
              @SourceTable=N'#LogShippingStatus_P'
            , @ResultLabel=N'LogShippingStatus'
            , @EmptyMessage=N'Keine fachlichen Ergebnisse';
    END;
    IF @TableResultRequested = 1
    BEGIN
        EXEC [monitor].[InternalWriteResultTable]
              @SourceTable = N'#LogShippingStatus_P'
            , @TargetTable=@TableTarget
            , @ThrowOnError = 1;
    END;
END;
GO
-- END SOURCE: Code/07_Infrastructure/060_USP_LogShippingStatus.sql

-- BEGIN SOURCE: Code/07_Infrastructure/070_USP_ReplicationStatus.sql
/*
===============================================================================
Objekt       : monitor.USP_ReplicationStatus
Version      : 1.1.0
Stand        : 2026-07-14
Typ          : Stored Procedure
Zweck        : Inventarisiert sichtbare Replication-Rollen, Publikationen, Subscriptions und Agentfehler.
SQL-Version  : SQL Server 2019 oder neuer.
Datenquellen : sys.databases, distribution.dbo.MSpublications/MSsubscriptions/MSdistribution_agents/MSrepl_errors, msdb Agent-Metadaten
Parameter    : @MitDistributionDetails, @MaxZeilen, @PrintMeldungen, @Hilfe
Resultsets   : 1. Modulstatus. 2. Server-/Datenbankrollen. 3. Publikationen. 4. Subscriptions. 5. Agentfehler.
Berechtigung : Nur lesender Zugriff auf die genannten Systemobjekte. Das
               Framework vergibt keine Rechte und ändert keine Konfiguration.
Eigenlast    : Mittel; optionale Distribution-DB-Auswertung.
Locking      : LOCK_TIMEOUT 0; keine fachlichen Schreibzugriffe.
Partial      : Fehlende Features, Objekte oder Rechte werden strukturiert als
               Partial Result behandelt; andere Module bleiben ausführbar.
Änderungen   : 1.1.0 - Negative @MaxZeilen-Werte werden vor Rechte- und
               Datenzugriffen strukturiert abgewiesen.
               1.0.0 - Erstfassung Phase 6.
===============================================================================
*/
CREATE OR ALTER PROCEDURE [monitor].[USP_ReplicationStatus]
 @MitDistributionDetails bit=0,@MaxZeilen int=5000,@HighImpactConfirmed bit=0,@ResultSetArt varchar(16)='CONSOLE'
    , @ResultTablesJson               nvarchar(max) = NULL
    , @JsonErzeugen bit=0,@Json nvarchar(max)=NULL OUTPUT,@PrintMeldungen bit=1,@Hilfe bit=0
AS
BEGIN
 SET NOCOUNT ON;
 SET @Json=NULL;
 DECLARE @ResultSetArtNormalisiert varchar(16)=UPPER(LTRIM(RTRIM(COALESCE(@ResultSetArt,''))));
    DECLARE @TableResultRequested bit = CASE WHEN @ResultSetArtNormalisiert = 'TABLE' THEN 1 ELSE 0 END;
    DECLARE @ConsoleResultRequested bit = CASE WHEN @ResultSetArtNormalisiert = 'CONSOLE' THEN 1 ELSE 0 END;
    DECLARE @TableTarget sysname=NULL;
    IF @TableResultRequested=0 AND NULLIF(LTRIM(RTRIM(COALESCE(@ResultTablesJson,N''))),N'') IS NOT NULL THROW 51011,N'@ResultTablesJson ist ausschließlich mit @ResultSetArt=TABLE zulässig.',1;
    IF @TableResultRequested=1 EXEC [monitor].[InternalPrepareSingleResultTable] @ResultTablesJson=@ResultTablesJson,@ResultName=N'databases',@TargetTable=@TableTarget OUTPUT,@ThrowOnError=1;
    IF @TableResultRequested = 1 OR @ConsoleResultRequested = 1 SET @ResultSetArtNormalisiert = 'NONE';
    DECLARE @EffectiveMaxZeilen bigint = CASE WHEN @MaxZeilen IS NULL OR @MaxZeilen=0 THEN CONVERT(bigint,9223372036854775807) ELSE CONVERT(bigint,@MaxZeilen) END;
 IF @Hilfe=1 BEGIN PRINT N'monitor.USP_ReplicationStatus'; PRINT N'@MitDistributionDetails bit=0: liest die konfigurierte Distribution-Datenbank.'; PRINT N'@MaxZeilen int=5000: positive Werte begrenzen; NULL/0 = unbegrenzt; negative Werte sind ungültig. @PrintMeldungen bit=1; @Hilfe bit=0.'; RETURN; END;
 DECLARE @CollectionTimeUtc datetime2(3)=SYSUTCDATETIME(),@StatusCode varchar(40)='AVAILABLE',@IsPartial bit=0,@ErrorNumber int=NULL,@ErrorMessage nvarchar(2048)=NULL,@DistDb sysname=NULL,@sql nvarchar(max),@Allowed bit=1;
 IF @MaxZeilen<0 SELECT @StatusCode='INVALID_PARAMETER',@IsPartial=1,@ErrorMessage=N'@MaxZeilen darf nicht negativ sein; NULL/0 bedeutet unbegrenzt.';
 CREATE TABLE [#ReplicationStatus_Db]([DatabaseName] sysname,[IsPublished] bit,[IsSubscribed] bit,[IsMergePublished] bit,[IsDistributor] bit);
 CREATE TABLE [#ReplicationStatus_Pub]([PublicationId] int,[PublisherDatabase] sysname,[PublicationName] sysname,[PublicationType] int,[ImmediateSync] bit,[AllowPush] bit,[AllowPull] bit,[Status] int);
 CREATE TABLE [#ReplicationStatus_Sub]([PublisherDatabase] sysname,[PublicationName] sysname,[SubscriberName] sysname,[SubscriberDatabase] sysname,[SubscriptionType] int,[Status] int,[AgentId] int,[LastAction] nvarchar(4000),[LastTimestamp] datetime);
 CREATE TABLE [#ReplicationStatus_Err]([ErrorId] int,[ErrorTime] datetime,[SourceName] nvarchar(100),[ErrorCode] int,[ErrorText] nvarchar(4000));
 IF @StatusCode='AVAILABLE' AND @MitDistributionDetails=1 EXEC [monitor].[InternalCheckAnalysisPath] @AnalysisClass='ENTERPRISE_TOPOLOGY_DEEP',@HighImpactConfirmed=@HighImpactConfirmed,@StatusCode=@StatusCode OUTPUT,@ErrorMessage=@ErrorMessage OUTPUT;
 IF @ResultSetArtNormalisiert NOT IN ('RAW','CONSOLE','NONE') SELECT @StatusCode='INVALID_PARAMETER',@IsPartial=1,@ErrorMessage=N'@ResultSetArt muss CONSOLE, RAW, TABLE oder NONE enthalten.';
 SET LOCK_TIMEOUT 0;
 IF @StatusCode='AVAILABLE' BEGIN TRY
  INSERT [#ReplicationStatus_Db] SELECT TOP (@EffectiveMaxZeilen) [name],[is_published],[is_subscribed],[is_merge_published],[is_distributor] FROM [sys].[databases] WITH (NOLOCK) WHERE [is_published]=1 OR [is_subscribed]=1 OR [is_merge_published]=1 OR [is_distributor]=1 ORDER BY [name];
  IF @MitDistributionDetails=1
  BEGIN
   SELECT TOP(1) @DistDb=[name] FROM [sys].[databases] WITH (NOLOCK) WHERE [is_distributor]=1 AND [state]=0;
   IF @DistDb IS NULL BEGIN SET @IsPartial=1; IF NOT EXISTS(SELECT 1 FROM [#ReplicationStatus_Db]) SET @StatusCode='UNAVAILABLE_FEATURE'; SET @ErrorMessage=N'Keine online sichtbare Distribution-Datenbank gefunden.'; END
   ELSE BEGIN
    SET @sql=N'IF EXISTS(SELECT 1 FROM '+QUOTENAME(@DistDb)+N'.[sys].[tables] AS [t] WITH (NOLOCK) JOIN '+QUOTENAME(@DistDb)+N'.[sys].[schemas] AS [sc] WITH (NOLOCK) ON [sc].[schema_id]=[t].[schema_id] WHERE [sc].[name]=N''dbo'' AND [t].[name]=N''MSpublications'') INSERT [#ReplicationStatus_Pub] ([PublicationId],[PublisherDatabase],[PublicationName],[PublicationType],[ImmediateSync],[AllowPush],[AllowPull],[Status]) SELECT TOP (@EffectiveMaxZeilen) [publication_id],[publisher_db],[publication],[publication_type],[immediate_sync],[allow_push],[allow_pull],[status] FROM '+QUOTENAME(@DistDb)+N'.[dbo].[MSpublications] WITH (NOLOCK) ORDER BY [publisher_db],[publication];';
    EXEC [sys].[sp_executesql] @sql,N'@EffectiveMaxZeilen bigint',@EffectiveMaxZeilen=@EffectiveMaxZeilen;
    SET @sql=N'IF EXISTS(SELECT 1 FROM '+QUOTENAME(@DistDb)+N'.[sys].[tables] AS [t] WITH (NOLOCK) JOIN '+QUOTENAME(@DistDb)+N'.[sys].[schemas] AS [sc] WITH (NOLOCK) ON [sc].[schema_id]=[t].[schema_id] WHERE [sc].[name]=N''dbo'' AND [t].[name]=N''MSsubscriptions'') INSERT [#ReplicationStatus_Sub] ([PublisherDatabase],[PublicationName],[SubscriberName],[SubscriberDatabase],[SubscriptionType],[Status],[AgentId],[LastAction],[LastTimestamp]) SELECT TOP (@EffectiveMaxZeilen) [s].[publisher_db],[p].[publication],[a].[subscriber_name],[s].[subscriber_db],[s].[subscription_type],[s].[status],[s].[agent_id],[h].[comments],[h].[time] FROM '+QUOTENAME(@DistDb)+N'.[dbo].[MSsubscriptions] AS [s] WITH (NOLOCK) LEFT JOIN '+QUOTENAME(@DistDb)+N'.[dbo].[MSpublications] AS [p] WITH (NOLOCK) ON [p].[publication_id]=[s].[publication_id] LEFT JOIN '+QUOTENAME(@DistDb)+N'.[dbo].[MSdistribution_agents] AS [a] WITH (NOLOCK) ON [a].[id]=[s].[agent_id] OUTER APPLY (SELECT TOP (1) [dh].[comments],[dh].[time] FROM '+QUOTENAME(@DistDb)+N'.[dbo].[MSdistribution_history] AS [dh] WITH (NOLOCK) WHERE [dh].[agent_id]=[s].[agent_id] ORDER BY [dh].[time] DESC) AS [h] ORDER BY [s].[publisher_db],[p].[publication];';
    EXEC [sys].[sp_executesql] @sql,N'@EffectiveMaxZeilen bigint',@EffectiveMaxZeilen=@EffectiveMaxZeilen;
    SET @sql=N'IF EXISTS(SELECT 1 FROM '+QUOTENAME(@DistDb)+N'.[sys].[tables] AS [t] WITH (NOLOCK) JOIN '+QUOTENAME(@DistDb)+N'.[sys].[schemas] AS [sc] WITH (NOLOCK) ON [sc].[schema_id]=[t].[schema_id] WHERE [sc].[name]=N''dbo'' AND [t].[name]=N''MSrepl_errors'') INSERT [#ReplicationStatus_Err] ([ErrorId],[ErrorTime],[SourceName],[ErrorCode],[ErrorText]) SELECT TOP (@EffectiveMaxZeilen) [id],[time],[source_name],[error_code],[error_text] FROM '+QUOTENAME(@DistDb)+N'.[dbo].[MSrepl_errors] WITH (NOLOCK) ORDER BY [time] DESC;';
    EXEC [sys].[sp_executesql] @sql,N'@EffectiveMaxZeilen bigint',@EffectiveMaxZeilen=@EffectiveMaxZeilen;
   END
  END
 END TRY BEGIN CATCH SELECT @StatusCode='ERROR_HANDLED',@IsPartial=1,@ErrorNumber=ERROR_NUMBER(),@ErrorMessage=ERROR_MESSAGE(); IF @PrintMeldungen=1 RAISERROR(N'Replication konnte nicht vollständig gelesen werden: %s',10,1,@ErrorMessage) WITH NOWAIT; END CATCH;

 IF @ResultSetArtNormalisiert<>'NONE'
 BEGIN
  SELECT @CollectionTimeUtc AS [CollectionTimeUtc],CAST(N'monitor.USP_ReplicationStatus' AS nvarchar(256)) AS [ModuleName],@StatusCode AS [StatusCode],@IsPartial AS [IsPartial],@ErrorNumber AS [ErrorNumber],@ErrorMessage AS [ErrorMessage];
  IF @ResultSetArtNormalisiert='RAW'
  BEGIN SELECT * FROM [#ReplicationStatus_Db] ORDER BY [DatabaseName];SELECT * FROM [#ReplicationStatus_Pub] ORDER BY [PublisherDatabase],[PublicationName];SELECT * FROM [#ReplicationStatus_Sub] ORDER BY [PublisherDatabase],[PublicationName];SELECT * FROM [#ReplicationStatus_Err] ORDER BY [ErrorTime] DESC;END
  ELSE
  BEGIN SELECT N'Replikations-Datenbank' [Ergebnis],[x].* FROM [#ReplicationStatus_Db] [x] ORDER BY [DatabaseName];SELECT N'Replikations-Publikation' [Ergebnis],[x].* FROM [#ReplicationStatus_Pub] [x] ORDER BY [PublisherDatabase],[PublicationName];SELECT N'Replikations-Subscription' [Ergebnis],[x].* FROM [#ReplicationStatus_Sub] [x] ORDER BY [PublisherDatabase],[PublicationName];SELECT N'Replikationsfehler' [Ergebnis],[x].* FROM [#ReplicationStatus_Err] [x] ORDER BY [ErrorTime] DESC;END
 END;
 IF @JsonErzeugen=1
 BEGIN
  DECLARE @MetaJson nvarchar(max)=(SELECT N'ReplicationStatus' [resultName],1 [schemaVersion],@CollectionTimeUtc [generatedAtUtc],@StatusCode [statusCode],@IsPartial [isPartial],@ErrorNumber [errorNumber],@ErrorMessage [errorMessage] FOR JSON PATH,WITHOUT_ARRAY_WRAPPER,INCLUDE_NULL_VALUES);
  DECLARE @DbJson nvarchar(max)=(SELECT * FROM [#ReplicationStatus_Db] ORDER BY [DatabaseName] FOR JSON PATH,INCLUDE_NULL_VALUES),@PubJson nvarchar(max)=(SELECT * FROM [#ReplicationStatus_Pub] ORDER BY [PublisherDatabase],[PublicationName] FOR JSON PATH,INCLUDE_NULL_VALUES),@SubJson nvarchar(max)=(SELECT * FROM [#ReplicationStatus_Sub] ORDER BY [PublisherDatabase],[PublicationName] FOR JSON PATH,INCLUDE_NULL_VALUES),@ErrJson nvarchar(max)=(SELECT * FROM [#ReplicationStatus_Err] ORDER BY [ErrorTime] DESC FOR JSON PATH,INCLUDE_NULL_VALUES);
  SET @Json=CONCAT(N'{"meta":',COALESCE(@MetaJson,N'{}'),N',"databases":',COALESCE(@DbJson,N'[]'),N',"publications":',COALESCE(@PubJson,N'[]'),N',"subscriptions":',COALESCE(@SubJson,N'[]'),N',"errors":',COALESCE(@ErrJson,N'[]'),N'}');
 END;
    IF @ConsoleResultRequested = 1
    BEGIN
        EXEC [monitor].[InternalEmitConsoleResult]
              @SourceTable=N'#ReplicationStatus_Db'
            , @ResultLabel=N'ReplicationStatus'
            , @EmptyMessage=N'Keine fachlichen Ergebnisse';
    END;
    IF @TableResultRequested = 1
    BEGIN
        EXEC [monitor].[InternalWriteResultTable]
              @SourceTable = N'#ReplicationStatus_Db'
            , @TargetTable=@TableTarget
            , @ThrowOnError = 1;
    END;
END;
GO
-- END SOURCE: Code/07_Infrastructure/070_USP_ReplicationStatus.sql

-- BEGIN SOURCE: Code/07_Infrastructure/080_USP_DataCaptureStatus.sql
/*
===============================================================================
Objekt       : monitor.USP_DataCaptureStatus
Version      : 2.0.0
Stand        : 2026-07-15
Typ          : Stored Procedure
Zweck        : Inventarisiert CDC und Change Tracking für eine bracket-aware
               Datenbankliste oder alle zulässigen Datenbanken.
SQL-Version  : SQL Server 2019 oder neuer.
Datenquellen : master.sys.databases, sys.change_tracking_databases,
               database-lokale sys.tables/sys.schemas/
               sys.change_tracking_tables/cdc.change_tables, msdb CDC-Jobs.
Parameter    : @DatabaseNames, @DatabaseNamePattern,
               @SystemdatenbankenEinbeziehen, @MaxZeilen,
               @ResultSetArt, @JsonErzeugen, @Json OUTPUT,
               @PrintMeldungen, @Hilfe.
Semantik     : @DatabaseNames=N'[Db1]|[Db2]'; NULL=alle zulässigen
               Datenbanken; N''=INVALID_PARAMETER. Exakte Liste und Pattern
               sind exklusiv. Die Datenbankauswahl wird nicht vorab begrenzt.
Ausgabe      : RAW/CONSOLE/NONE; JSON mit meta, databases, cdcTables,
               changeTrackingTables, cdcJobs und warnings.
Berechtigung : Cross-Database wird über CROSS_DATABASE_DEEP geprüft.
Eigenlast    : Mittel; lokale Kandidaten werden je Datenbank auf N+1 begrenzt,
               anschließend erfolgt ein globales TOP je fachlichem Resultset.
Locking      : LOCK_TIMEOUT 0; Systemkataloge READUNCOMMITTED.
Änderungen   : 2.0.0 - @AlleDatenbanken entfernt; Listen-/Patternvertrag,
                         globale Mengenbegrenzung und Ausgabevertrag ergänzt.
               1.0.0 - Erstfassung Phase 6.
===============================================================================
*/
CREATE OR ALTER PROCEDURE [monitor].[USP_DataCaptureStatus]
      @DatabaseNames                    nvarchar(max)  = NULL
    , @SystemdatenbankenEinbeziehen     bit            = 0
    , @DatabaseNamePattern              nvarchar(4000) = NULL
    , @HighImpactConfirmed              bit            = 0
    , @MaxZeilen                        int            = 10000
    , @ResultSetArt                     varchar(16)    = 'CONSOLE'
    , @ResultTablesJson               nvarchar(max) = NULL
    , @JsonErzeugen                     bit            = 0
    , @Json                             nvarchar(max)  = NULL OUTPUT
    , @PrintMeldungen                   bit            = 1
    , @Hilfe                            bit            = 0
AS
BEGIN
    SET NOCOUNT ON;
    SET @Json = NULL;
    SET LOCK_TIMEOUT 0;

    DECLARE @ResultSetArtNormalisiert varchar(16) = UPPER(LTRIM(RTRIM(COALESCE(@ResultSetArt, ''))));
    DECLARE @TableResultRequested bit = CASE WHEN @ResultSetArtNormalisiert = 'TABLE' THEN 1 ELSE 0 END;
    DECLARE @ConsoleResultRequested bit = CASE WHEN @ResultSetArtNormalisiert = 'CONSOLE' THEN 1 ELSE 0 END;
    DECLARE @TableTarget sysname=NULL;
    IF @TableResultRequested=0 AND NULLIF(LTRIM(RTRIM(COALESCE(@ResultTablesJson,N''))),N'') IS NOT NULL THROW 51011,N'@ResultTablesJson ist ausschließlich mit @ResultSetArt=TABLE zulässig.',1;
    IF @TableResultRequested=1 EXEC [monitor].[InternalPrepareSingleResultTable] @ResultTablesJson=@ResultTablesJson,@ResultName=N'databases',@TargetTable=@TableTarget OUTPUT,@ThrowOnError=1;
    IF @TableResultRequested = 1 OR @ConsoleResultRequested = 1 SET @ResultSetArtNormalisiert = 'NONE';
    DECLARE @EffectiveMaxZeilen bigint = CASE WHEN @MaxZeilen IS NULL OR @MaxZeilen = 0 THEN CONVERT(bigint, 9223372036854775807) WHEN @MaxZeilen > 0 THEN CONVERT(bigint, @MaxZeilen) ELSE CONVERT(bigint, 0) END;
    DECLARE @LocalCandidateRows bigint = CASE WHEN @MaxZeilen IS NULL OR @MaxZeilen = 0 THEN CONVERT(bigint, 9223372036854775807) WHEN @MaxZeilen BETWEEN 1 AND 2147483646 THEN CONVERT(bigint, @MaxZeilen) + 1 WHEN @MaxZeilen > 0 THEN CONVERT(bigint, @MaxZeilen) ELSE CONVERT(bigint, 0) END;
    DECLARE @MonitorPrintMessage nvarchar(2048);

    IF @Hilfe = 1
    BEGIN
        PRINT N'monitor.USP_DataCaptureStatus';
        PRINT N'@DatabaseNames=N''[Db1]|[Db2]''; NULL=alle; N'''' bedeutet keine Einschränkung.';
        PRINT N'@DatabaseNamePattern=like:...|regex:...|regexi:...; ein Pattern, keine Pipe-Liste.';
        PRINT N'Die Datenbankauswahl wird nicht vorab begrenzt; @MaxZeilen gilt global je fachlichem Resultset.';
        PRINT N'@ResultSetArt=CONSOLE (Default)|RAW|TABLE|NONE (case-insensitiv); @JsonErzeugen=1 erzeugt @Json OUTPUT.';
        RETURN;
    END;

    DECLARE @CollectionTimeUtc datetime2(3) = SYSUTCDATETIME();
    DECLARE @StatusCode varchar(40) = 'AVAILABLE';
    DECLARE @IsPartial bit = 0;
    DECLARE @ErrorNumber int = NULL;
    DECLARE @ErrorMessage nvarchar(2048) = NULL;
    DECLARE @CrossDatabaseRequested bit = 0;
    DECLARE @Db sysname;
    DECLARE @Sql nvarchar(max);

    CREATE TABLE [#DataCaptureStatus_DatabaseCandidates]
    (
          [DatabaseId] int NOT NULL
        , [DatabaseName] sysname COLLATE SQL_Latin1_General_CP1_CS_AS NOT NULL
        , [StateDesc] nvarchar(60) NULL
        , [UserAccessDesc] nvarchar(60) NULL
        , [IsReadOnly] bit NULL
        , [CompatibilityLevel] tinyint NULL
        , [CollationName] sysname NULL
        , [RecoveryModelDesc] nvarchar(60) NULL
        , [IsSystemDatabase] bit NULL
        , [RequestedOrdinal] int NULL
    );

    CREATE TABLE [#DataCaptureStatus_DatabaseCandidateWarnings]
    (
          [RequestedName] sysname COLLATE SQL_Latin1_General_CP1_CS_AS NULL
        , [StatusCode] varchar(40) NOT NULL
        , [ErrorMessage] nvarchar(2048) NOT NULL
    );

    CREATE TABLE [#DataCaptureStatus_Db]
    (
          [DatabaseName] sysname COLLATE SQL_Latin1_General_CP1_CS_AS NOT NULL
        , [StateDesc] nvarchar(60) NULL
        , [IsCdcEnabled] bit NULL
        , [IsChangeTrackingEnabled] bit NULL
        , [RetentionPeriod] bigint NULL
        , [RetentionPeriodUnitsDesc] nvarchar(60) NULL
        , [IsAutoCleanupOn] bit NULL
        , [CurrentCtVersion] bigint NULL
        , [StatusCode] varchar(40) NOT NULL
        , [ErrorMessage] nvarchar(2048) NULL
    );

    CREATE TABLE [#DataCaptureStatus_Cdc]
    (
          [DatabaseName] sysname COLLATE SQL_Latin1_General_CP1_CS_AS NOT NULL
        , [CaptureInstance] sysname NULL
        , [SourceSchema] sysname NULL
        , [SourceTable] sysname NULL
        , [ObjectId] int NULL
        , [StartLsn] binary(10) NULL
        , [SupportsNetChanges] bit NULL
        , [RoleName] sysname NULL
        , [IndexName] sysname NULL
        , [CreateDate] datetime NULL
        , [PartitionSwitch] bit NULL
    );

    CREATE TABLE [#DataCaptureStatus_Ct]
    (
          [DatabaseName] sysname COLLATE SQL_Latin1_General_CP1_CS_AS NOT NULL
        , [SchemaName] sysname NULL
        , [TableName] sysname NULL
        , [ObjectId] int NULL
        , [IsTrackColumnsUpdatedOn] bit NULL
        , [BeginVersion] bigint NULL
        , [CleanupVersion] bigint NULL
        , [MinValidVersion] bigint NULL
    );

    CREATE TABLE [#DataCaptureStatus_Jobs]
    (
          [DatabaseName] sysname COLLATE SQL_Latin1_General_CP1_CS_AS NOT NULL
        , [JobType] nvarchar(20) NULL
        , [JobName] sysname NULL
        , [Enabled] bit NULL
        , [LastRunOutcome] int NULL
        , [LastRunDateTime] datetime NULL
        , [LastMessage] nvarchar(4000) NULL
    );

    CREATE TABLE [#DataCaptureStatus_Warnings]
    (
          [DatabaseName] sysname COLLATE SQL_Latin1_General_CP1_CS_AS NULL
        , [SourceName] varchar(40) NOT NULL
        , [StatusCode] varchar(40) NOT NULL
        , [ErrorNumber] int NULL
        , [ErrorMessage] nvarchar(2048) NULL
    );

    IF @MaxZeilen < 0 OR @ResultSetArtNormalisiert NOT IN ('RAW', 'CONSOLE', 'NONE')
    BEGIN
        SET @StatusCode = 'INVALID_PARAMETER';
        SET @ErrorMessage = N'Ungültige Mengen- oder Ausgabeparameter.';
    END;

    IF @StatusCode = 'AVAILABLE'
    BEGIN
        EXEC [monitor].[USP_PrepareDatabaseCandidates]
              @DatabaseNames = @DatabaseNames
            , @SystemdatenbankenEinbeziehen = @SystemdatenbankenEinbeziehen
            , @DatabaseNamePattern = @DatabaseNamePattern,@HighImpactConfirmed=@HighImpactConfirmed

            , @AnalysisClass = 'HA_DR_CURRENT'
            , @StatusCode = @StatusCode OUTPUT
            , @ErrorMessage = @ErrorMessage OUTPUT
            , @CrossDatabaseRequested = @CrossDatabaseRequested OUTPUT,@CandidateTable=N'#DataCaptureStatus_DatabaseCandidates',@WarningTable=N'#DataCaptureStatus_DatabaseCandidateWarnings';
    END;

    IF @StatusCode = 'AVAILABLE'
    BEGIN
        DECLARE [DatabaseCursor] CURSOR LOCAL FAST_FORWARD FOR
        SELECT [DatabaseName]
        FROM [#DataCaptureStatus_DatabaseCandidates]
        WHERE [DatabaseName] <> N'tempdb'
        ORDER BY COALESCE([RequestedOrdinal], [DatabaseId]), [DatabaseId];

        OPEN [DatabaseCursor];
        FETCH NEXT FROM [DatabaseCursor] INTO @Db;

        WHILE @@FETCH_STATUS = 0
        BEGIN
            BEGIN TRY
                SET @Sql = N'USE ' + QUOTENAME(@Db) + N';
INSERT [#DataCaptureStatus_Db]
(
      [DatabaseName], [StateDesc], [IsCdcEnabled], [IsChangeTrackingEnabled]
    , [RetentionPeriod], [RetentionPeriodUnitsDesc], [IsAutoCleanupOn]
    , [CurrentCtVersion], [StatusCode], [ErrorMessage]
)
SELECT
      [d].[name]
    , [d].[state_desc]
    , [d].[is_cdc_enabled]
    , CONVERT(bit, CASE WHEN [ctd].[database_id] IS NULL THEN 0 ELSE 1 END)
    , [ctd].[retention_period]
    , [ctd].[retention_period_units_desc]
    , [ctd].[is_auto_cleanup_on]
    , CHANGE_TRACKING_CURRENT_VERSION()
    , ''AVAILABLE''
    , NULL
FROM [sys].[databases] AS [d] WITH (NOLOCK)
LEFT JOIN [sys].[change_tracking_databases] AS [ctd] WITH (NOLOCK)
  ON [ctd].[database_id] = [d].[database_id]
WHERE [d].[database_id] = DB_ID();

IF EXISTS
(
    SELECT 1
    FROM [sys].[tables] AS [t] WITH (NOLOCK)
    INNER JOIN [sys].[schemas] AS [s] WITH (NOLOCK)
      ON [s].[schema_id] = [t].[schema_id]
    WHERE [s].[name] = N''cdc'' AND [t].[name] = N''change_tables''
)
BEGIN
    EXEC(N''INSERT [#DataCaptureStatus_Cdc]
    SELECT TOP('' + CONVERT(nvarchar(30), @LocalRows) + N'')
          (SELECT [name] FROM [master].[sys].[databases] WITH (NOLOCK) WHERE [database_id] = DB_ID())
        , [ct].[capture_instance]
        , [s].[name]
        , [t].[name]
        , [ct].[source_object_id]
        , [ct].[start_lsn]
        , [ct].[supports_net_changes]
        , [ct].[role_name]
        , [ct].[index_name]
        , [ct].[create_date]
        , [ct].[partition_switch]
    FROM [cdc].[change_tables] AS [ct] WITH (NOLOCK)
    LEFT JOIN [sys].[tables] AS [t] WITH (NOLOCK)
      ON [t].[object_id] = [ct].[source_object_id]
    LEFT JOIN [sys].[schemas] AS [s] WITH (NOLOCK)
      ON [s].[schema_id] = [t].[schema_id]
    ORDER BY [ct].[capture_instance];'');
END;

INSERT [#DataCaptureStatus_Ct]
SELECT TOP (@LocalRows)
      (SELECT [name] FROM [master].[sys].[databases] WITH (NOLOCK) WHERE [database_id] = DB_ID())
    , [s].[name]
    , [t].[name]
    , [ct].[object_id]
    , [ct].[is_track_columns_updated_on]
    , [ct].[begin_version]
    , [ct].[cleanup_version]
    , CHANGE_TRACKING_MIN_VALID_VERSION([ct].[object_id])
FROM [sys].[change_tracking_tables] AS [ct] WITH (NOLOCK)
INNER JOIN [sys].[tables] AS [t] WITH (NOLOCK)
  ON [t].[object_id] = [ct].[object_id]
INNER JOIN [sys].[schemas] AS [s] WITH (NOLOCK)
  ON [s].[schema_id] = [t].[schema_id]
ORDER BY [s].[name], [t].[name];';

                EXEC [sys].[sp_executesql]
                      @Sql
                    , N'@LocalRows bigint'
                    , @LocalRows = @LocalCandidateRows;

                INSERT [#DataCaptureStatus_Jobs]
                SELECT TOP (@LocalCandidateRows)
                      @Db
                    , CASE WHEN [j].[name] LIKE N'cdc.' + @Db + N'_capture%' THEN N'CAPTURE' ELSE N'CLEANUP' END
                    , [j].[name]
                    , [j].[enabled]
                    , [h].[run_status]
                    , CASE WHEN [h].[run_date] > 0 THEN [msdb].[dbo].[agent_datetime]([h].[run_date], [h].[run_time]) END
                    , [h].[message]
                FROM [msdb].[dbo].[sysjobs] AS [j] WITH (NOLOCK)
                OUTER APPLY
                (
                    SELECT TOP (1) [x].[run_status], [x].[run_date], [x].[run_time], [x].[message]
                    FROM [msdb].[dbo].[sysjobhistory] AS [x] WITH (NOLOCK)
                    WHERE [x].[job_id] = [j].[job_id] AND [x].[step_id] = 0
                    ORDER BY [x].[instance_id] DESC
                ) AS [h]
                WHERE [j].[name] LIKE N'cdc.' + @Db + N'[_]%'
                ORDER BY [j].[name];
            END TRY
            BEGIN CATCH
                INSERT [#DataCaptureStatus_Db] VALUES(@Db, NULL, NULL, NULL, NULL, NULL, NULL, NULL,
                    CASE WHEN ERROR_NUMBER() IN (229,262,297,300,371,916) THEN 'DENIED_PERMISSION'
                         WHEN ERROR_NUMBER() = 1222 THEN 'TIMEOUT' ELSE 'ERROR_HANDLED' END,
                    ERROR_MESSAGE());
                INSERT [#DataCaptureStatus_Warnings] VALUES(@Db, 'DATABASE_CAPTURE',
                    CASE WHEN ERROR_NUMBER() IN (229,262,297,300,371,916) THEN 'DENIED_PERMISSION'
                         WHEN ERROR_NUMBER() = 1222 THEN 'TIMEOUT' ELSE 'ERROR_HANDLED' END,
                    ERROR_NUMBER(), ERROR_MESSAGE());
                SET @IsPartial = 1;
            END CATCH;

            FETCH NEXT FROM [DatabaseCursor] INTO @Db;
        END;

        CLOSE [DatabaseCursor];
        DEALLOCATE [DatabaseCursor];

        INSERT [#DataCaptureStatus_Warnings]([DatabaseName],[SourceName],[StatusCode],[ErrorNumber],[ErrorMessage])
        SELECT [RequestedName], 'DATABASE_SELECTION', [StatusCode], NULL, [ErrorMessage]
        FROM [#DataCaptureStatus_DatabaseCandidateWarnings];

        IF EXISTS(SELECT 1 FROM [#DataCaptureStatus_Warnings])
        BEGIN
            SET @StatusCode = CASE WHEN EXISTS(SELECT 1 FROM [#DataCaptureStatus_Db] WHERE [StatusCode] = 'AVAILABLE') THEN 'PARTIAL_RESULT' ELSE 'ERROR_HANDLED' END;
            SET @IsPartial = 1;
        END;
    END;

    IF @StatusCode <> 'AVAILABLE' AND @PrintMeldungen = 1
    BEGIN
        SET @MonitorPrintMessage = FORMATMESSAGE(N'WARNUNG USP_DataCaptureStatus %s: %s', @StatusCode, COALESCE(@ErrorMessage, N'Teilergebnis.'));
        RAISERROR(N'%s', 10, 1, @MonitorPrintMessage) WITH NOWAIT;
    END;

    IF @JsonErzeugen = 1
    BEGIN
        DECLARE @JsonMeta nvarchar(max) =
        (
            SELECT N'DataCaptureStatus' AS [resultName], 1 AS [schemaVersion],
                   @CollectionTimeUtc AS [generatedAtUtc], @StatusCode AS [statusCode],
                   @IsPartial AS [isPartial], @MaxZeilen AS [requestedMaxRows],
                   @ErrorNumber AS [errorNumber], @ErrorMessage AS [errorMessage]
            FOR JSON PATH, WITHOUT_ARRAY_WRAPPER, INCLUDE_NULL_VALUES
        );
        DECLARE @JsonDb nvarchar(max) = (SELECT * FROM [#DataCaptureStatus_Db] ORDER BY [DatabaseName] FOR JSON PATH, INCLUDE_NULL_VALUES);
        DECLARE @JsonCdc nvarchar(max) = (SELECT TOP (@EffectiveMaxZeilen) * FROM [#DataCaptureStatus_Cdc] ORDER BY [DatabaseName], [CaptureInstance] FOR JSON PATH, INCLUDE_NULL_VALUES);
        DECLARE @JsonCt nvarchar(max) = (SELECT TOP (@EffectiveMaxZeilen) * FROM [#DataCaptureStatus_Ct] ORDER BY [DatabaseName], [SchemaName], [TableName] FOR JSON PATH, INCLUDE_NULL_VALUES);
        DECLARE @JsonJobs nvarchar(max) = (SELECT TOP (@EffectiveMaxZeilen) * FROM [#DataCaptureStatus_Jobs] ORDER BY [DatabaseName], [JobType], [JobName] FOR JSON PATH, INCLUDE_NULL_VALUES);
        DECLARE @JsonWarnings nvarchar(max) = (SELECT * FROM [#DataCaptureStatus_Warnings] ORDER BY [DatabaseName], [SourceName] FOR JSON PATH, INCLUDE_NULL_VALUES);
        SET @Json = CONCAT(N'{"meta":', COALESCE(@JsonMeta,N'{}'), N',"databases":', COALESCE(@JsonDb,N'[]'), N',"cdcTables":', COALESCE(@JsonCdc,N'[]'), N',"changeTrackingTables":', COALESCE(@JsonCt,N'[]'), N',"cdcJobs":', COALESCE(@JsonJobs,N'[]'), N',"warnings":', COALESCE(@JsonWarnings,N'[]'), N'}');
    END;

    IF @ResultSetArtNormalisiert = 'RAW'
    BEGIN
        SELECT @CollectionTimeUtc AS [CollectionTimeUtc], N'monitor.USP_DataCaptureStatus' AS [ModuleName], @StatusCode AS [StatusCode], @IsPartial AS [IsPartial], @ErrorNumber AS [ErrorNumber], @ErrorMessage AS [ErrorMessage];
        SELECT * FROM [#DataCaptureStatus_Db] ORDER BY [DatabaseName];
        SELECT TOP (@EffectiveMaxZeilen) * FROM [#DataCaptureStatus_Cdc] ORDER BY [DatabaseName], [CaptureInstance];
        SELECT TOP (@EffectiveMaxZeilen) * FROM [#DataCaptureStatus_Ct] ORDER BY [DatabaseName], [SchemaName], [TableName];
        SELECT TOP (@EffectiveMaxZeilen) * FROM [#DataCaptureStatus_Jobs] ORDER BY [DatabaseName], [JobType], [JobName];
        SELECT * FROM [#DataCaptureStatus_Warnings] ORDER BY [DatabaseName], [SourceName];
    END
    ELSE IF @ResultSetArtNormalisiert = 'CONSOLE'
    BEGIN
        SELECT N'Data-Capture-Analyse' AS [Ergebnis], @CollectionTimeUtc AS [Stand_UTC], @StatusCode AS [Status], @IsPartial AS [Teilergebnis], @ErrorMessage AS [Hinweis];
        SELECT N'Datenbankstatus CDC/Change Tracking' AS [Ergebnis], [DatabaseName] AS [Datenbank], [IsCdcEnabled] AS [CDC_aktiv], [IsChangeTrackingEnabled] AS [Change_Tracking_aktiv], [RetentionPeriod] AS [Retention], [RetentionPeriodUnitsDesc] AS [Retention_Einheit], [IsAutoCleanupOn] AS [Auto_Cleanup], [CurrentCtVersion] AS [CT_Version], [StatusCode] AS [Status], [ErrorMessage] AS [Fehler] FROM [#DataCaptureStatus_Db] ORDER BY [DatabaseName];
        SELECT TOP (@EffectiveMaxZeilen) N'CDC-Tabelle' AS [Ergebnis], [DatabaseName] AS [Datenbank], [CaptureInstance] AS [Capture_Instance], [SourceSchema] AS [Schema], [SourceTable] AS [Tabelle], [SupportsNetChanges] AS [Net_Changes], [RoleName] AS [Rolle], [IndexName] AS [Index], [CreateDate] AS [Erstellt] FROM [#DataCaptureStatus_Cdc] ORDER BY [DatabaseName], [CaptureInstance];
        SELECT TOP (@EffectiveMaxZeilen) N'Change-Tracking-Tabelle' AS [Ergebnis], [DatabaseName] AS [Datenbank], [SchemaName] AS [Schema], [TableName] AS [Tabelle], [IsTrackColumnsUpdatedOn] AS [Spaltenänderungen_aufzeichnen], [BeginVersion] AS [Beginn_Version], [CleanupVersion] AS [Cleanup_Version], [MinValidVersion] AS [Min_gültige_Version] FROM [#DataCaptureStatus_Ct] ORDER BY [DatabaseName], [SchemaName], [TableName];
        SELECT TOP (@EffectiveMaxZeilen) N'CDC-Agentjob' AS [Ergebnis], [DatabaseName] AS [Datenbank], [JobType] AS [Job_Typ], [JobName] AS [Job], [Enabled] AS [Aktiv], [LastRunOutcome] AS [Letzter_Status], [LastRunDateTime] AS [Letzter_Lauf], [LastMessage] AS [Meldung] FROM [#DataCaptureStatus_Jobs] ORDER BY [DatabaseName], [JobType], [JobName];
        SELECT N'Data-Capture-Warnung' AS [Ergebnis], [DatabaseName] AS [Datenbank], [SourceName] AS [Quelle], [StatusCode] AS [Status], [ErrorNumber] AS [Fehlernummer], [ErrorMessage] AS [Fehlermeldung] FROM [#DataCaptureStatus_Warnings] ORDER BY [DatabaseName], [SourceName];
    END;
    IF @ConsoleResultRequested = 1
    BEGIN
        EXEC [monitor].[InternalEmitConsoleResult]
              @SourceTable=N'#DataCaptureStatus_Db'
            , @ResultLabel=N'DataCaptureStatus'
            , @EmptyMessage=N'Keine fachlichen Ergebnisse';
    END;
    IF @TableResultRequested = 1
    BEGIN
        EXEC [monitor].[InternalWriteResultTable]
              @SourceTable = N'#DataCaptureStatus_Db'
            , @TargetTable=@TableTarget
            , @ThrowOnError = 1;
    END;
END;
GO
-- END SOURCE: Code/07_Infrastructure/080_USP_DataCaptureStatus.sql

-- BEGIN SOURCE: Code/07_Infrastructure/100_USP_BackupChainAnalysis.sql
/*
===============================================================================
Objekt       : monitor.USP_BackupChainAnalysis
Version      : 1.0.0
Stand        : 2026-07-17
Zweck        : Bewertet Backupketten und Wiederherstellbarkeitsevidenz aus msdb.
Datenquellen : msdb.dbo.backupset und msdb.dbo.restorehistory.
Methodik     : Prüft Full-/Differentialbasis, Log-LSN-Übergänge,
               Recovery-Fork-Wechsel, Prüfsummen, Schadensflags und Restorebeleg.
Grenzen      : msdb-Historie kann bereinigt oder unvollständig sein. Nur ein
               erfolgreicher Test-Restore beweist die Wiederherstellbarkeit.
Datenschutz  : Liest keine Medienpfade, Benutzernamen oder Backupinhalte.
===============================================================================
*/
CREATE OR ALTER PROCEDURE [monitor].[USP_BackupChainAnalysis]
      @DatabaseNames                nvarchar(max)  = NULL
    , @SystemdatenbankenEinbeziehen bit            = 0
    , @DatabaseNamePattern          nvarchar(4000) = NULL
    , @HighImpactConfirmed              bit            = 0
    , @HistoryDays                  int            = 35
    , @MitRestoreEvidence           bit            = 1
    , @MaxZeilen                    int            = 1000
    , @ResultSetArt                 varchar(16)    = 'CONSOLE'
    , @ResultTablesJson               nvarchar(max) = NULL
    , @JsonErzeugen                 bit            = 0
    , @Json                         nvarchar(max)  = NULL OUTPUT
    , @PrintMeldungen               bit            = 1
    , @Hilfe                        bit            = 0
    , @StatusCodeOut                varchar(40)    = NULL OUTPUT
    , @IsPartialOut                 bit            = NULL OUTPUT
    , @ErrorNumberOut               int            = NULL OUTPUT
    , @ErrorMessageOut              nvarchar(2048) = NULL OUTPUT
AS
BEGIN
    SET NOCOUNT ON;
    SET @Json = NULL;

    DECLARE @OutputMode varchar(16) = UPPER(LTRIM(RTRIM(COALESCE(@ResultSetArt, ''))));
    DECLARE @TableResultRequested bit = CASE WHEN @OutputMode = 'TABLE' THEN 1 ELSE 0 END;
    DECLARE @ConsoleResultRequested bit = CASE WHEN @OutputMode = 'CONSOLE' THEN 1 ELSE 0 END;
    DECLARE @TableTarget sysname=NULL;
    IF @TableResultRequested=0 AND NULLIF(LTRIM(RTRIM(COALESCE(@ResultTablesJson,N''))),N'') IS NOT NULL THROW 51011,N'@ResultTablesJson ist ausschließlich mit @ResultSetArt=TABLE zulässig.',1;
    IF @TableResultRequested=1 EXEC [monitor].[InternalPrepareSingleResultTable] @ResultTablesJson=@ResultTablesJson,@ResultName=N'summary',@TargetTable=@TableTarget OUTPUT,@ThrowOnError=1;
    IF @TableResultRequested = 1 OR @ConsoleResultRequested = 1 SET @OutputMode = 'NONE';
    DECLARE @Limit bigint = CASE WHEN @MaxZeilen IS NULL OR @MaxZeilen = 0
                                 THEN CONVERT(bigint, 9223372036854775807)
                                 ELSE CONVERT(bigint, @MaxZeilen) END;

    IF @Hilfe = 1
    BEGIN
        PRINT N'monitor.USP_BackupChainAnalysis';
        PRINT N'Prüft ausschließlich msdb-Metadaten; Medienpfade und Benutzernamen werden nicht gelesen.';
        PRINT N'@DatabaseNames: bracket-aware Pipe-Liste; NULL = alle zulässigen Datenbanken.';
        PRINT N'@HistoryDays begrenzt die Kettenevidenz; der letzte nicht-copy-only Full wird zusätzlich einbezogen.';
        PRINT N'Nur ein erfolgreicher Test-Restore beweist Wiederherstellbarkeit.';
        RETURN;
    END;

    DECLARE @Now datetime2(3) = SYSUTCDATETIME();
    DECLARE @StatusCode varchar(40) = 'AVAILABLE';
    DECLARE @IsPartial bit = 0;
    DECLARE @ErrorNumber int = NULL;
    DECLARE @ErrorMessage nvarchar(2048) = NULL;
    DECLARE @CrossDatabaseRequested bit = 0;

    CREATE TABLE [#BackupChainAnalysis_DatabaseCandidates]
    (
          [DatabaseId] int NOT NULL PRIMARY KEY
        , [DatabaseName] sysname NOT NULL
        , [StateDesc] nvarchar(60) NULL
        , [UserAccessDesc] nvarchar(60) NULL
        , [IsReadOnly] bit NULL
        , [CompatibilityLevel] tinyint NULL
        , [CollationName] sysname NULL
        , [RecoveryModelDesc] nvarchar(60) NULL
        , [IsSystemDatabase] bit NULL
        , [RequestedOrdinal] int NULL
    );
    CREATE TABLE [#BackupChainAnalysis_DatabaseCandidateWarnings]
    (
          [RequestedName] sysname NULL
        , [StatusCode] varchar(40) NOT NULL
        , [ErrorMessage] nvarchar(2048) NULL
    );
    CREATE TABLE [#BackupChainAnalysis_Backups]
    (
          [DatabaseName] sysname NOT NULL
        , [BackupSetId] int NOT NULL
        , [BackupType] char(1) NOT NULL
        , [BackupTypeDesc] nvarchar(40) NOT NULL
        , [BackupStartDate] datetime NULL
        , [BackupFinishDate] datetime NULL
        , [FirstLsn] numeric(25,0) NULL
        , [LastLsn] numeric(25,0) NULL
        , [CheckpointLsn] numeric(25,0) NULL
        , [DatabaseBackupLsn] numeric(25,0) NULL
        , [DifferentialBaseLsn] numeric(25,0) NULL
        , [FirstRecoveryForkGuid] uniqueidentifier NULL
        , [LastRecoveryForkGuid] uniqueidentifier NULL
        , [IsCopyOnly] bit NULL
        , [HasBackupChecksums] bit NULL
        , [IsDamaged] bit NULL
        , [IsEncrypted] bit NULL
        , [PreviousLogLastLsn] numeric(25,0) NULL
        , [LogGapDetected] bit NOT NULL DEFAULT (0)
    );
    CREATE TABLE [#BackupChainAnalysis_Summary]
    (
          [DatabaseId] int NOT NULL
        , [DatabaseName] sysname NOT NULL
        , [RecoveryModelDesc] nvarchar(60) NULL
        , [LatestFullFinish] datetime NULL
        , [LatestMatchingDifferentialFinish] datetime NULL
        , [LatestLogFinish] datetime NULL
        , [LogBackupCountInWindow] bigint NOT NULL
        , [LogGapCountInWindow] bigint NOT NULL
        , [RecoveryForkTransitionCount] bigint NOT NULL
        , [DamagedBackupCount] bigint NOT NULL
        , [BackupWithoutChecksumCount] bigint NOT NULL
        , [LatestRestoreDate] datetime NULL
        , [FindingCode] varchar(100) NOT NULL
        , [FindingSeverity] varchar(16) NOT NULL
        , [EvidenceLimit] nvarchar(1000) NOT NULL
    );

    IF @HistoryDays < 1 OR @HistoryDays > 3650
       OR @MaxZeilen < 0 OR @OutputMode NOT IN ('RAW', 'CONSOLE', 'NONE')
    BEGIN
        SELECT @StatusCode = 'INVALID_PARAMETER', @IsPartial = 1,
               @ErrorMessage = N'Ungültiger Datenbank-, Historien-, Zeilen- oder Ausgabeparameter.';
    END;

    IF @StatusCode = 'AVAILABLE'
    BEGIN
        EXEC [monitor].[USP_PrepareDatabaseCandidates]
              @DatabaseNames = @DatabaseNames
            , @SystemdatenbankenEinbeziehen = @SystemdatenbankenEinbeziehen
            , @DatabaseNamePattern = @DatabaseNamePattern,@HighImpactConfirmed=@HighImpactConfirmed

            , @AnalysisClass = NULL
            , @StatusCode = @StatusCode OUTPUT
            , @ErrorMessage = @ErrorMessage OUTPUT
            , @CrossDatabaseRequested = @CrossDatabaseRequested OUTPUT,@CandidateTable=N'#BackupChainAnalysis_DatabaseCandidates',@WarningTable=N'#BackupChainAnalysis_DatabaseCandidateWarnings';
    END;

    SET LOCK_TIMEOUT 0;

    IF @StatusCode = 'AVAILABLE'
    BEGIN
        BEGIN TRY
            ;WITH [LatestFull] AS
            (
                SELECT [bs].[database_name], [bs].[backup_set_id] AS [BackupSetId],
                       ROW_NUMBER() OVER
                       (
                           PARTITION BY [bs].[database_name]
                           ORDER BY [bs].[backup_finish_date] DESC, [bs].[backup_set_id] DESC
                       ) AS [rn]
                FROM [msdb].[dbo].[backupset] AS [bs] WITH (NOLOCK)
                JOIN [#BackupChainAnalysis_DatabaseCandidates] AS [c]
                  ON [c].[DatabaseName] COLLATE SQL_Latin1_General_CP1_CS_AS
                   = [bs].[database_name] COLLATE SQL_Latin1_General_CP1_CS_AS
                WHERE [bs].[type] = 'D' AND [bs].[is_copy_only] = 0
            ),
            [Selected] AS
            (
                SELECT [bs].*
                FROM [msdb].[dbo].[backupset] AS [bs] WITH (NOLOCK)
                JOIN [#BackupChainAnalysis_DatabaseCandidates] AS [c]
                  ON [c].[DatabaseName] COLLATE SQL_Latin1_General_CP1_CS_AS
                   = [bs].[database_name] COLLATE SQL_Latin1_General_CP1_CS_AS
                LEFT JOIN [LatestFull] AS [f]
                  ON [f].[database_name] COLLATE SQL_Latin1_General_CP1_CS_AS
                   = [bs].[database_name] COLLATE SQL_Latin1_General_CP1_CS_AS
                 AND [f].[rn] = 1
                WHERE [bs].[type] IN ('D', 'I', 'L')
                  AND ([bs].[backup_finish_date] >= DATEADD(DAY, -@HistoryDays, GETDATE())
                       OR [bs].[backup_set_id] = [f].[BackupSetId])
            ),
            [WithPreviousLog] AS
            (
                SELECT [s].*,
                       CASE WHEN [s].[type] = 'L'
                            THEN LAG(CASE WHEN [s].[type] = 'L' THEN [s].[last_lsn] END)
                                 OVER (PARTITION BY [s].[database_name], [s].[type]
                                       ORDER BY [s].[backup_start_date], [s].[backup_set_id]) END AS [PreviousLogLastLsn]
                FROM [Selected] AS [s]
            )
            INSERT [#BackupChainAnalysis_Backups]
            (
                  [DatabaseName], [BackupSetId], [BackupType], [BackupTypeDesc]
                , [BackupStartDate], [BackupFinishDate], [FirstLsn], [LastLsn]
                , [CheckpointLsn], [DatabaseBackupLsn], [DifferentialBaseLsn]
                , [FirstRecoveryForkGuid], [LastRecoveryForkGuid]
                , [IsCopyOnly], [HasBackupChecksums], [IsDamaged], [IsEncrypted]
                , [PreviousLogLastLsn], [LogGapDetected]
            )
            SELECT
                  [database_name], [backup_set_id], [type]
                , CASE [type] WHEN 'D' THEN N'FULL' WHEN 'I' THEN N'DIFFERENTIAL' ELSE N'LOG' END
                , [backup_start_date], [backup_finish_date], [first_lsn], [last_lsn]
                , [checkpoint_lsn], [database_backup_lsn], [differential_base_lsn]
                , [first_recovery_fork_guid], [last_recovery_fork_guid]
                , [is_copy_only], [has_backup_checksums], [is_damaged]
                , CONVERT(bit, CASE WHEN [key_algorithm] IS NULL THEN 0 ELSE 1 END)
                , [PreviousLogLastLsn]
                , CONVERT(bit, CASE WHEN [type] = 'L' AND [PreviousLogLastLsn] IS NOT NULL
                                      AND [first_lsn] > [PreviousLogLastLsn] THEN 1 ELSE 0 END)
            FROM [WithPreviousLog];

            ;WITH [LatestFull] AS
            (
                SELECT [b].*, ROW_NUMBER() OVER
                       (PARTITION BY [DatabaseName] ORDER BY [BackupFinishDate] DESC, [BackupSetId] DESC) AS [rn]
                FROM [#BackupChainAnalysis_Backups] AS [b]
                WHERE [BackupType] = 'D' AND [IsCopyOnly] = 0
            ),
            [LatestMatchingDiff] AS
            (
                SELECT [d].[DatabaseName], MAX([d].[BackupFinishDate]) AS [FinishDate]
                FROM [#BackupChainAnalysis_Backups] AS [d]
                JOIN [LatestFull] AS [f]
                  ON [f].[DatabaseName] = [d].[DatabaseName] AND [f].[rn] = 1
                 AND [d].[DifferentialBaseLsn] = [f].[CheckpointLsn]
                WHERE [d].[BackupType] = 'I'
                  AND [d].[BackupFinishDate] >= [f].[BackupFinishDate]
                GROUP BY [d].[DatabaseName]
            ),
            [Forks] AS
            (
                SELECT [x].[DatabaseName],
                       SUM(CONVERT(bigint, CASE WHEN [x].[PreviousFork] IS NOT NULL
                                                AND [x].[LastRecoveryForkGuid] <> [x].[PreviousFork]
                                               THEN 1 ELSE 0 END)) AS [Transitions]
                FROM
                (
                    SELECT [b].[DatabaseName], [b].[LastRecoveryForkGuid],
                           LAG([b].[LastRecoveryForkGuid]) OVER
                           (PARTITION BY [b].[DatabaseName]
                            ORDER BY [b].[BackupStartDate], [b].[BackupSetId]) AS [PreviousFork]
                    FROM [#BackupChainAnalysis_Backups] AS [b]
                ) AS [x]
                GROUP BY [x].[DatabaseName]
            ),
            [RestoreEvidence] AS
            (
                SELECT [rh].[destination_database_name] AS [DatabaseName],
                       MAX([rh].[restore_date]) AS [LatestRestoreDate]
                FROM [msdb].[dbo].[restorehistory] AS [rh] WITH (NOLOCK)
                JOIN [#BackupChainAnalysis_DatabaseCandidates] AS [c]
                  ON [c].[DatabaseName] COLLATE SQL_Latin1_General_CP1_CS_AS
                   = [rh].[destination_database_name] COLLATE SQL_Latin1_General_CP1_CS_AS
                WHERE @MitRestoreEvidence = 1
                GROUP BY [rh].[destination_database_name]
            ),
            [Aggregated] AS
            (
                SELECT [c].[DatabaseId], [c].[DatabaseName], [c].[RecoveryModelDesc],
                       MAX(CASE WHEN [f].[rn] = 1 THEN [f].[BackupFinishDate] END) AS [LatestFullFinish],
                       MAX([d].[FinishDate]) AS [LatestDiffFinish],
                       MAX(CASE WHEN [b].[BackupType] = 'L' THEN [b].[BackupFinishDate] END) AS [LatestLogFinish],
                       SUM(CONVERT(bigint, CASE WHEN [b].[BackupType] = 'L' THEN 1 ELSE 0 END)) AS [LogCount],
                       SUM(CONVERT(bigint, CASE WHEN [b].[LogGapDetected] = 1 THEN 1 ELSE 0 END)) AS [GapCount],
                       MAX(COALESCE([k].[Transitions], 0)) AS [ForkTransitions],
                       SUM(CONVERT(bigint, CASE WHEN [b].[IsDamaged] = 1 THEN 1 ELSE 0 END)) AS [DamagedCount],
                       SUM(CONVERT(bigint, CASE WHEN [b].[BackupSetId] IS NOT NULL
                                                AND COALESCE([b].[HasBackupChecksums], 0) = 0
                                               THEN 1 ELSE 0 END)) AS [NoChecksumCount],
                       MAX([r].[LatestRestoreDate]) AS [LatestRestoreDate]
                FROM [#BackupChainAnalysis_DatabaseCandidates] AS [c]
                LEFT JOIN [#BackupChainAnalysis_Backups] AS [b] ON [b].[DatabaseName] = [c].[DatabaseName]
                LEFT JOIN [LatestFull] AS [f] ON [f].[DatabaseName] = [c].[DatabaseName] AND [f].[rn] = 1
                LEFT JOIN [LatestMatchingDiff] AS [d] ON [d].[DatabaseName] = [c].[DatabaseName]
                LEFT JOIN [Forks] AS [k] ON [k].[DatabaseName] = [c].[DatabaseName]
                LEFT JOIN [RestoreEvidence] AS [r] ON [r].[DatabaseName] COLLATE SQL_Latin1_General_CP1_CS_AS
                                                   = [c].[DatabaseName] COLLATE SQL_Latin1_General_CP1_CS_AS
                GROUP BY [c].[DatabaseId], [c].[DatabaseName], [c].[RecoveryModelDesc]
            )
            INSERT [#BackupChainAnalysis_Summary]
            SELECT
                  [DatabaseId], [DatabaseName], [RecoveryModelDesc]
                , [LatestFullFinish], [LatestDiffFinish], [LatestLogFinish]
                , COALESCE([LogCount], 0), COALESCE([GapCount], 0), COALESCE([ForkTransitions], 0)
                , COALESCE([DamagedCount], 0), COALESCE([NoChecksumCount], 0), [LatestRestoreDate]
                , CASE WHEN [DatabaseId] = 2 THEN 'TEMPDB_NOT_APPLICABLE'
                       WHEN [LatestFullFinish] IS NULL THEN 'FULL_BACKUP_EVIDENCE_MISSING'
                       WHEN [DamagedCount] > 0 THEN 'DAMAGED_BACKUP_METADATA'
                       WHEN [GapCount] > 0 THEN 'LOG_CHAIN_GAP_IN_VISIBLE_HISTORY'
                       WHEN [RecoveryModelDesc] IN (N'FULL', N'BULK_LOGGED') AND [LatestLogFinish] IS NULL
                            THEN 'LOG_BACKUP_EVIDENCE_MISSING'
                       WHEN [NoChecksumCount] > 0 THEN 'BACKUP_WITHOUT_CHECKSUM_IN_VISIBLE_HISTORY'
                       WHEN @MitRestoreEvidence = 1 AND [LatestRestoreDate] IS NULL THEN 'RESTORE_EVIDENCE_MISSING'
                       ELSE 'CHAIN_METADATA_CONSISTENT' END
                , CASE WHEN [DatabaseId] = 2 THEN 'INFO'
                       WHEN [LatestFullFinish] IS NULL OR [DamagedCount] > 0 OR [GapCount] > 0 THEN 'HIGH'
                       WHEN ([RecoveryModelDesc] IN (N'FULL', N'BULK_LOGGED') AND [LatestLogFinish] IS NULL)
                         OR [NoChecksumCount] > 0 THEN 'MEDIUM' ELSE 'INFO' END
                , CONCAT(N'msdb-Sichtfenster ', @HistoryDays,
                         N' Tage; bereinigte Historie kann scheinbare Lücken erzeugen. Test-Restore bleibt erforderlich.')
            FROM [Aggregated];

            IF EXISTS (SELECT 1 FROM [#BackupChainAnalysis_DatabaseCandidateWarnings])
                SELECT @StatusCode = 'AVAILABLE_LIMITED', @IsPartial = 1;
            ELSE IF EXISTS
                    (SELECT 1 FROM [#BackupChainAnalysis_Summary]
                     WHERE [FindingCode] NOT IN ('CHAIN_METADATA_CONSISTENT', 'TEMPDB_NOT_APPLICABLE'))
                SET @StatusCode = 'AVAILABLE_WITH_FINDING';
        END TRY
        BEGIN CATCH
            SELECT @StatusCode = CASE WHEN ERROR_NUMBER() IN (229, 371, 916)
                                      THEN 'DENIED_PERMISSION' ELSE 'ERROR_HANDLED' END,
                   @IsPartial = 1, @ErrorNumber = ERROR_NUMBER(), @ErrorMessage = ERROR_MESSAGE();
        END CATCH;
    END;

    SELECT @StatusCodeOut = @StatusCode, @IsPartialOut = @IsPartial,
           @ErrorNumberOut = @ErrorNumber, @ErrorMessageOut = @ErrorMessage;

    IF @JsonErzeugen = 1
    BEGIN
        DECLARE @MetaJson nvarchar(max) =
            (SELECT N'BackupChainAnalysis' AS [resultName], 1 AS [schemaVersion],
                    @Now AS [generatedAtUtc], @StatusCode AS [statusCode], @IsPartial AS [isPartial],
                    @HistoryDays AS [historyDays]
             FOR JSON PATH, WITHOUT_ARRAY_WRAPPER);
        DECLARE @SummaryJson nvarchar(max) =
            (SELECT TOP (@Limit) * FROM [#BackupChainAnalysis_Summary] ORDER BY [DatabaseId]
             FOR JSON PATH, INCLUDE_NULL_VALUES);
        DECLARE @BackupJson nvarchar(max) =
            (SELECT TOP (@Limit) * FROM [#BackupChainAnalysis_Backups]
             ORDER BY [BackupFinishDate] DESC, [BackupSetId] DESC
             FOR JSON PATH, INCLUDE_NULL_VALUES);
        DECLARE @WarningJson nvarchar(max) =
            (SELECT * FROM [#BackupChainAnalysis_DatabaseCandidateWarnings] ORDER BY [RequestedName]
             FOR JSON PATH, INCLUDE_NULL_VALUES);
        SET @Json = CONCAT(N'{"meta":', COALESCE(@MetaJson, N'{}'),
                           N',"summary":', COALESCE(@SummaryJson, N'[]'),
                           N',"backups":', COALESCE(@BackupJson, N'[]'),
                           N',"warnings":', COALESCE(@WarningJson, N'[]'), N'}');
    END;

    IF @OutputMode = 'RAW'
    BEGIN
        SELECT N'USP_BackupChainAnalysis' AS [ModuleName], @Now AS [CollectionTimeUtc],
               @StatusCode AS [StatusCode], @IsPartial AS [IsPartial], @HistoryDays AS [HistoryDays],
               @ErrorNumber AS [ErrorNumber], @ErrorMessage AS [ErrorMessage],
               N'msdb-Metadaten; Test-Restore erforderlich.' AS [Detail];
        SELECT TOP (@Limit) * FROM [#BackupChainAnalysis_Summary] ORDER BY [DatabaseId];
        SELECT TOP (@Limit) * FROM [#BackupChainAnalysis_Backups]
        ORDER BY [BackupFinishDate] DESC, [BackupSetId] DESC;
        SELECT * FROM [#BackupChainAnalysis_DatabaseCandidateWarnings] ORDER BY [RequestedName];
    END
    ELSE IF @OutputMode = 'CONSOLE'
    BEGIN
        SELECT N'Backupketten' AS [Ergebnis], @Now AS [Stand_UTC], @StatusCode AS [Status],
               @HistoryDays AS [Historie_Tage], @ErrorMessage AS [Hinweis];
        SELECT TOP (@Limit) N'Wiederherstellbarkeitsevidenz' AS [Ergebnis],
               [DatabaseName] AS [Datenbank], [RecoveryModelDesc] AS [Recovery_Model],
               [LatestFullFinish] AS [Letztes_Full],
               [LatestMatchingDifferentialFinish] AS [Passendes_Differential],
               [LatestLogFinish] AS [Letztes_Log], [LogGapCountInWindow] AS [Log_Luecken],
               [RecoveryForkTransitionCount] AS [Fork_Wechsel],
               [DamagedBackupCount] AS [Beschaedigte_Backups],
               [BackupWithoutChecksumCount] AS [Ohne_Checksum],
               [LatestRestoreDate] AS [Letzter_Restorebeleg],
               [FindingCode] AS [Befund], [FindingSeverity] AS [Prioritaet], [EvidenceLimit] AS [Grenze]
        FROM [#BackupChainAnalysis_Summary]
        ORDER BY CASE [FindingSeverity] WHEN 'HIGH' THEN 1 WHEN 'MEDIUM' THEN 2 ELSE 3 END, [DatabaseId];
        SELECT N'Backupketten-Warnung' AS [Ergebnis], [RequestedName] AS [Datenbank],
               [StatusCode] AS [Status], [ErrorMessage] AS [Meldung]
        FROM [#BackupChainAnalysis_DatabaseCandidateWarnings] ORDER BY [RequestedName];
    END;
    IF @ConsoleResultRequested = 1
    BEGIN
        EXEC [monitor].[InternalEmitConsoleResult]
              @SourceTable=N'#BackupChainAnalysis_Summary'
            , @ResultLabel=N'BackupChainAnalysis'
            , @EmptyMessage=N'Keine fachlichen Ergebnisse';
    END;
    IF @TableResultRequested = 1
    BEGIN
        EXEC [monitor].[InternalWriteResultTable]
              @SourceTable = N'#BackupChainAnalysis_Summary'
            , @TargetTable=@TableTarget
            , @ThrowOnError = 1;
    END;
END;
GO
-- END SOURCE: Code/07_Infrastructure/100_USP_BackupChainAnalysis.sql

-- BEGIN SOURCE: Code/07_Infrastructure/110_USP_AvailabilityDeepAnalysis.sql
/*
===============================================================================
Objekt       : monitor.USP_AvailabilityDeepAnalysis
Version      : 1.1.0
Stand        : 2026-07-18
Zweck        : Vertieft Always-On-Evidenz um Replikazustand, Warteschlangen,
               Clusterquorum, Seeding und automatische Seitenreparatur.
Datenquellen : sys.availability_groups, sys.availability_replicas,
               sys.dm_hadr_availability_replica_states,
               sys.dm_hadr_database_replica_states, sys.dm_hadr_cluster,
               sys.dm_hadr_cluster_members, optional sys.dm_hadr_cluster_networks,
               sys.dm_hadr_physical_seeding_stats und sys.dm_hadr_auto_page_repair.
Methodik     : Datenbank- und Seedingzustände werden über dieselben reinen
               Interpretationsfunktionen klassifiziert, die auch der
               deterministische Laufzeitvertrag verwendet.
Grenzen      : Momentaufnahme; Netzpfad, Clusterlog und Betriebssystemereignisse
               sind nicht enthalten. Keine Failover- oder Konfigurationsaktion.
===============================================================================
*/
CREATE OR ALTER PROCEDURE [monitor].[USP_AvailabilityDeepAnalysis]
      @QueueWarnMb              bigint          = 1024
    , @SecondaryLagWarnSeconds  int             = 60
    , @MitClusterNetzwerken     bit             = 0
    , @MaxZeilen                int             = 1000
    , @ResultSetArt             varchar(16)     = 'CONSOLE'
    , @ResultTablesJson               nvarchar(max) = NULL
    , @JsonErzeugen             bit             = 0
    , @Json                     nvarchar(max)   = NULL OUTPUT
    , @PrintMeldungen           bit             = 1
    , @Hilfe                    bit             = 0
    , @StatusCodeOut            varchar(40)     = NULL OUTPUT
    , @IsPartialOut             bit             = NULL OUTPUT
    , @ErrorNumberOut           int             = NULL OUTPUT
    , @ErrorMessageOut          nvarchar(2048)  = NULL OUTPUT
AS
BEGIN
    SET NOCOUNT ON;
    SET LOCK_TIMEOUT 0;
    SET @Json = NULL;

    DECLARE @OutputMode varchar(16) = UPPER(LTRIM(RTRIM(COALESCE(@ResultSetArt, ''))));
    DECLARE @TableResultRequested bit = CASE WHEN @OutputMode = 'TABLE' THEN 1 ELSE 0 END;
    DECLARE @ConsoleResultRequested bit = CASE WHEN @OutputMode = 'CONSOLE' THEN 1 ELSE 0 END;
    DECLARE @TableTarget sysname=NULL;
    IF @TableResultRequested=0 AND NULLIF(LTRIM(RTRIM(COALESCE(@ResultTablesJson,N''))),N'') IS NOT NULL THROW 51011,N'@ResultTablesJson ist ausschließlich mit @ResultSetArt=TABLE zulässig.',1;
    IF @TableResultRequested=1 EXEC [monitor].[InternalPrepareSingleResultTable] @ResultTablesJson=@ResultTablesJson,@ResultName=N'replicas',@TargetTable=@TableTarget OUTPUT,@ThrowOnError=1;
    IF @TableResultRequested = 1 OR @ConsoleResultRequested = 1 SET @OutputMode = 'NONE';
    DECLARE @Limit bigint = CASE WHEN @MaxZeilen IS NULL OR @MaxZeilen = 0
                                 THEN CONVERT(bigint, 9223372036854775807)
                                 ELSE CONVERT(bigint, @MaxZeilen) END;

    IF @Hilfe = 1
    BEGIN
        PRINT N'monitor.USP_AvailabilityDeepAnalysis';
        PRINT N'Die Procedure liefert eine rein lesende Always-On-Momentaufnahme und löst weder ein Failover noch eine Konfigurationsänderung aus.';
        PRINT N'@QueueWarnMb und @SecondaryLagWarnSeconds sind Sichtungsgrenzen, keine universellen SLOs.';
        PRINT N'@MitClusterNetzwerken=0; Netzwerkdetails sind opt-in.';
        RETURN;
    END;

    DECLARE @Now datetime2(3) = SYSUTCDATETIME();
    DECLARE @StatusCode varchar(40) = 'AVAILABLE';
    DECLARE @IsPartial bit = 0;
    DECLARE @ErrorNumber int = NULL;
    DECLARE @ErrorMessage nvarchar(2048) = NULL;
    DECLARE @ProductMajorVersion int = TRY_CONVERT(int, SERVERPROPERTY(N'ProductMajorVersion'));

    CREATE TABLE [#AvailabilityDeepAnalysis_Cluster]
    (
          [ClusterName] nvarchar(128) NULL
        , [QuorumTypeDesc] nvarchar(60) NULL
        , [QuorumStateDesc] nvarchar(60) NULL
        , [FindingCode] varchar(80) NOT NULL
    );
    CREATE TABLE [#AvailabilityDeepAnalysis_Members]
    (
          [MemberName] nvarchar(256) NULL
        , [MemberTypeDesc] nvarchar(60) NULL
        , [MemberStateDesc] nvarchar(60) NULL
        , [NumberOfQuorumVotes] int NULL
    );
    CREATE TABLE [#AvailabilityDeepAnalysis_Networks]
    (
          [MemberName] nvarchar(128) NULL
        , [NetworkSubnetIp] nvarchar(48) NULL
        , [NetworkSubnetPrefixLength] int NULL
        , [IsPublic] bit NULL
        , [IsIpv4] bit NULL
    );
    CREATE TABLE [#AvailabilityDeepAnalysis_Replicas]
    (
          [AvailabilityGroupName] sysname NULL
        , [ReplicaServerName] nvarchar(256) NULL
        , [IsLocal] bit NULL
        , [RoleDesc] nvarchar(60) NULL
        , [OperationalStateDesc] nvarchar(60) NULL
        , [ConnectedStateDesc] nvarchar(60) NULL
        , [SynchronizationHealthDesc] nvarchar(60) NULL
        , [AvailabilityModeDesc] nvarchar(60) NULL
        , [FailoverModeDesc] nvarchar(60) NULL
        , [SeedingModeDesc] nvarchar(60) NULL
        , [FindingCode] varchar(80) NOT NULL
    );
    CREATE TABLE [#AvailabilityDeepAnalysis_Databases]
    (
          [AvailabilityGroupName] sysname NULL
        , [ReplicaServerName] nvarchar(256) NULL
        , [DatabaseId] int NULL
        , [DatabaseName] sysname NULL
        , [IsLocal] bit NULL
        , [SynchronizationStateDesc] nvarchar(60) NULL
        , [SynchronizationHealthDesc] nvarchar(60) NULL
        , [DatabaseStateDesc] nvarchar(60) NULL
        , [IsSuspended] bit NULL
        , [SuspendReasonDesc] nvarchar(60) NULL
        , [LogSendQueueSizeKb] bigint NULL
        , [RedoQueueSizeKb] bigint NULL
        , [SecondaryLagSeconds] bigint NULL
        , [LastCommitTime] datetime NULL
        , [FindingCode] varchar(100) NOT NULL
        , [FindingSeverity] varchar(16) NOT NULL
    );
    CREATE TABLE [#AvailabilityDeepAnalysis_Seeding]
    (
          [RemoteMachineName] nvarchar(256) NULL
        , [RoleDesc] nvarchar(60) NULL
        , [DatabaseName] sysname NULL
        , [CurrentStateDesc] nvarchar(60) NULL
        , [FailureCode] int NULL
        , [TransferredSizeBytes] bigint NULL
        , [DatabaseSizeBytes] bigint NULL
        , [TransferRateBytesPerSecond] bigint NULL
        , [StartTimeUtc] datetime NULL
        , [EndTimeUtc] datetime NULL
        , [EstimateTimeCompleteUtc] datetime NULL
        , [ProgressPercent] decimal(9,4) NULL
        , [RemainingBytes] bigint NULL
        , [FindingCode] varchar(100) NOT NULL
        , [FindingSeverity] varchar(16) NOT NULL
    );
    CREATE TABLE [#AvailabilityDeepAnalysis_PageRepair]
    (
          [DatabaseId] int NULL
        , [DatabaseName] sysname NULL
        , [FileId] int NULL
        , [PageId] bigint NULL
        , [ErrorType] int NULL
        , [PageStatus] int NULL
        , [ModificationTime] datetime NULL
        , [FindingCode] varchar(80) NOT NULL
    );

    IF @QueueWarnMb IS NULL OR @SecondaryLagWarnSeconds IS NULL
       OR @QueueWarnMb < 0 OR @SecondaryLagWarnSeconds < 0 OR @MaxZeilen < 0
       OR @OutputMode NOT IN ('RAW', 'CONSOLE', 'NONE')
    BEGIN
        SELECT @StatusCode = 'INVALID_PARAMETER', @IsPartial = 1,
               @ErrorMessage = N'Ungültiger Queue-, Lag-, Zeilen- oder Ausgabeparameter.';
    END
    ELSE IF COALESCE(TRY_CONVERT(int, SERVERPROPERTY(N'IsHadrEnabled')), 0) <> 1
    BEGIN
        SELECT @StatusCode = 'NOT_APPLICABLE',
               @ErrorMessage = N'Always On Availability Groups ist auf dieser Instanz nicht aktiviert.';
    END;

    IF @StatusCode = 'AVAILABLE'
    BEGIN
        BEGIN TRY
            INSERT [#AvailabilityDeepAnalysis_Cluster]
            SELECT [cluster_name], [quorum_type_desc], [quorum_state_desc],
                   CASE WHEN [quorum_state_desc] = N'NORMAL_QUORUM'
                        THEN 'QUORUM_STATE_NORMAL' ELSE 'QUORUM_STATE_REVIEW' END
            FROM [sys].[dm_hadr_cluster] WITH (NOLOCK);

            IF NOT EXISTS (SELECT 1 FROM [#AvailabilityDeepAnalysis_Cluster])
                INSERT [#AvailabilityDeepAnalysis_Cluster]
                VALUES (NULL, NULL, NULL, 'QUORUM_STATE_NOT_VISIBLE');

            INSERT [#AvailabilityDeepAnalysis_Members]
            SELECT [member_name], [member_type_desc], [member_state_desc], [number_of_quorum_votes]
            FROM [sys].[dm_hadr_cluster_members] WITH (NOLOCK);

            IF @MitClusterNetzwerken = 1
            BEGIN
                INSERT [#AvailabilityDeepAnalysis_Networks]
                SELECT [member_name], [network_subnet_ip], [network_subnet_prefix_length], [is_public], [is_ipv4]
                FROM [sys].[dm_hadr_cluster_networks] WITH (NOLOCK);
            END;

            INSERT [#AvailabilityDeepAnalysis_Replicas]
            SELECT
                  [ag].[name], [ar].[replica_server_name], [rs].[is_local], [rs].[role_desc]
                , [rs].[operational_state_desc], [rs].[connected_state_desc]
                , [rs].[synchronization_health_desc], [ar].[availability_mode_desc]
                , [ar].[failover_mode_desc], [ar].[seeding_mode_desc]
                , CASE WHEN [rs].[connected_state_desc] = N'DISCONNECTED' THEN 'REPLICA_DISCONNECTED'
                       WHEN [rs].[synchronization_health_desc] = N'NOT_HEALTHY' THEN 'REPLICA_NOT_HEALTHY'
                       WHEN [rs].[operational_state_desc] NOT IN (N'ONLINE', N'PENDING_FAILOVER')
                            AND [rs].[operational_state_desc] IS NOT NULL THEN 'REPLICA_OPERATIONAL_STATE_REVIEW'
                       ELSE 'REPLICA_STATE_ACCEPTABLE' END
            FROM [sys].[availability_groups] AS [ag] WITH (NOLOCK)
            JOIN [sys].[availability_replicas] AS [ar] WITH (NOLOCK) ON [ar].[group_id] = [ag].[group_id]
            LEFT JOIN [sys].[dm_hadr_availability_replica_states] AS [rs] WITH (NOLOCK)
              ON [rs].[group_id] = [ar].[group_id] AND [rs].[replica_id] = [ar].[replica_id];

            INSERT [#AvailabilityDeepAnalysis_Databases]
            SELECT
                  [ag].[name], [ar].[replica_server_name], [drs].[database_id], (SELECT [name] FROM [master].[sys].[databases] WITH (NOLOCK) WHERE [database_id] = [drs].[database_id])
                , [drs].[is_local], [drs].[synchronization_state_desc]
                , [drs].[synchronization_health_desc], [drs].[database_state_desc]
                , [drs].[is_suspended], [drs].[suspend_reason_desc]
                , [drs].[log_send_queue_size], [drs].[redo_queue_size]
                , [drs].[secondary_lag_seconds], [drs].[last_commit_time]
                , [state].[FindingCode], [state].[FindingSeverity]
            FROM [sys].[dm_hadr_database_replica_states] AS [drs] WITH (NOLOCK)
            JOIN [sys].[availability_groups] AS [ag] WITH (NOLOCK) ON [ag].[group_id] = [drs].[group_id]
            JOIN [sys].[availability_replicas] AS [ar] WITH (NOLOCK)
              ON [ar].[group_id] = [drs].[group_id] AND [ar].[replica_id] = [drs].[replica_id]
            CROSS APPLY [monitor].[TVF_InterpretAvailabilityDatabaseState]
            (
                  [drs].[is_suspended], [drs].[synchronization_health_desc]
                , [drs].[synchronization_state_desc], [drs].[log_send_queue_size]
                , [drs].[redo_queue_size], [drs].[secondary_lag_seconds]
                , @QueueWarnMb, @SecondaryLagWarnSeconds
            ) AS [state];

            INSERT [#AvailabilityDeepAnalysis_Seeding]
            SELECT
                  [ps].[remote_machine_name], [ps].[role_desc], [ps].[local_database_name], [ps].[internal_state_desc]
                , [ps].[failure_code], [ps].[transferred_size_bytes], [ps].[database_size_bytes]
                , [ps].[transfer_rate_bytes_per_second], CONVERT(datetime,[ps].[start_time_utc])
                , CONVERT(datetime,[ps].[end_time_utc]), CONVERT(datetime,[ps].[estimate_time_complete_utc])
                , [state].[ProgressPercent], [state].[RemainingBytes]
                , [state].[FindingCode], [state].[FindingSeverity]
            FROM [sys].[dm_hadr_physical_seeding_stats] AS [ps] WITH (NOLOCK)
            CROSS APPLY [monitor].[TVF_InterpretAvailabilitySeedingState]
            (
                  [ps].[failure_code], [ps].[transferred_size_bytes], [ps].[database_size_bytes]
                , [ps].[transfer_rate_bytes_per_second], CONVERT(datetime,[ps].[end_time_utc])
            ) AS [state];

            INSERT [#AvailabilityDeepAnalysis_PageRepair]
            SELECT [pr].[database_id], [d].[name], [pr].[file_id], [pr].[page_id], [pr].[error_type]
                 , [pr].[page_status], [pr].[modification_time]
                 , CASE WHEN [pr].[page_status] = 5 THEN 'PAGE_REPAIR_SUCCEEDED'
                        ELSE 'PAGE_REPAIR_PENDING_OR_FAILED' END
            FROM [sys].[dm_hadr_auto_page_repair] AS [pr] WITH (NOLOCK)
            LEFT JOIN [master].[sys].[databases] AS [d] WITH (NOLOCK)
              ON [d].[database_id]=[pr].[database_id];

            IF EXISTS
               (
                   SELECT 1 FROM [#AvailabilityDeepAnalysis_Cluster] WHERE [FindingCode] <> 'QUORUM_STATE_NORMAL'
                   UNION ALL
                   SELECT 1 FROM [#AvailabilityDeepAnalysis_Replicas] WHERE [FindingCode] <> 'REPLICA_STATE_ACCEPTABLE'
                   UNION ALL
                   SELECT 1 FROM [#AvailabilityDeepAnalysis_Databases] WHERE [FindingCode] <> 'DATABASE_STATE_ACCEPTABLE'
                   UNION ALL
                   SELECT 1 FROM [#AvailabilityDeepAnalysis_Seeding] WHERE [FindingSeverity] <> 'INFO'
                   UNION ALL
                   SELECT 1 FROM [#AvailabilityDeepAnalysis_PageRepair] WHERE [FindingCode] <> 'PAGE_REPAIR_SUCCEEDED'
               )
                SET @StatusCode = 'AVAILABLE_WITH_FINDING';
        END TRY
        BEGIN CATCH
            SELECT @StatusCode = CASE WHEN ERROR_NUMBER() IN (229, 297, 300, 371)
                                      THEN 'DENIED_PERMISSION' ELSE 'ERROR_HANDLED' END,
                   @IsPartial = 1, @ErrorNumber = ERROR_NUMBER(), @ErrorMessage = ERROR_MESSAGE();
        END CATCH;
    END;

    SELECT @StatusCodeOut = @StatusCode, @IsPartialOut = @IsPartial,
           @ErrorNumberOut = @ErrorNumber, @ErrorMessageOut = @ErrorMessage;

    IF @JsonErzeugen = 1
    BEGIN
        DECLARE @MetaJson nvarchar(max) =
            (SELECT N'AvailabilityDeepAnalysis' AS [resultName], 1 AS [schemaVersion],
                    @Now AS [generatedAtUtc], @StatusCode AS [statusCode], @IsPartial AS [isPartial],
                    @QueueWarnMb AS [queueWarnMb], @SecondaryLagWarnSeconds AS [secondaryLagWarnSeconds],
                    @ProductMajorVersion AS [productMajorVersion]
             FOR JSON PATH, WITHOUT_ARRAY_WRAPPER, INCLUDE_NULL_VALUES);
        DECLARE @ClusterJson nvarchar(max) = (SELECT * FROM [#AvailabilityDeepAnalysis_Cluster] FOR JSON PATH, INCLUDE_NULL_VALUES);
        DECLARE @MemberJson nvarchar(max) =
            (SELECT TOP (@Limit) * FROM [#AvailabilityDeepAnalysis_Members] ORDER BY [MemberName] FOR JSON PATH, INCLUDE_NULL_VALUES);
        DECLARE @NetworkJson nvarchar(max) =
            (SELECT TOP (@Limit) * FROM [#AvailabilityDeepAnalysis_Networks] ORDER BY [MemberName], [NetworkSubnetIp] FOR JSON PATH, INCLUDE_NULL_VALUES);
        DECLARE @ReplicaJson nvarchar(max) =
            (SELECT TOP (@Limit) * FROM [#AvailabilityDeepAnalysis_Replicas] ORDER BY [AvailabilityGroupName], [ReplicaServerName]
             FOR JSON PATH, INCLUDE_NULL_VALUES);
        DECLARE @DatabaseJson nvarchar(max) =
            (SELECT TOP (@Limit) * FROM [#AvailabilityDeepAnalysis_Databases]
             ORDER BY CASE [FindingSeverity] WHEN 'HIGH' THEN 1 WHEN 'MEDIUM' THEN 2 ELSE 3 END,
                      [AvailabilityGroupName], [DatabaseName]
             FOR JSON PATH, INCLUDE_NULL_VALUES);
        DECLARE @SeedingJson nvarchar(max) =
            (SELECT TOP (@Limit) * FROM [#AvailabilityDeepAnalysis_Seeding]
             ORDER BY CASE [FindingSeverity] WHEN 'HIGH' THEN 1 WHEN 'MEDIUM' THEN 2 ELSE 3 END,
                      [StartTimeUtc] DESC
             FOR JSON PATH, INCLUDE_NULL_VALUES);
        DECLARE @RepairJson nvarchar(max) =
            (SELECT TOP (@Limit) * FROM [#AvailabilityDeepAnalysis_PageRepair] ORDER BY [ModificationTime] DESC FOR JSON PATH, INCLUDE_NULL_VALUES);
        SET @Json = CONCAT(N'{"meta":', COALESCE(@MetaJson, N'{}'),
                           N',"cluster":', COALESCE(@ClusterJson, N'[]'),
                           N',"members":', COALESCE(@MemberJson, N'[]'),
                           N',"networks":', COALESCE(@NetworkJson, N'[]'),
                           N',"replicas":', COALESCE(@ReplicaJson, N'[]'),
                           N',"databases":', COALESCE(@DatabaseJson, N'[]'),
                           N',"seeding":', COALESCE(@SeedingJson, N'[]'),
                           N',"pageRepair":', COALESCE(@RepairJson, N'[]'), N'}');
    END;

    IF @OutputMode = 'RAW'
    BEGIN
        SELECT N'USP_AvailabilityDeepAnalysis' AS [ModuleName], @Now AS [CollectionTimeUtc],
               @StatusCode AS [StatusCode], @IsPartial AS [IsPartial],
               @ErrorNumber AS [ErrorNumber], @ErrorMessage AS [ErrorMessage],
               N'Read-only Always-On-Momentaufnahme.' AS [Detail];
        SELECT * FROM [#AvailabilityDeepAnalysis_Cluster];
        SELECT TOP (@Limit) * FROM [#AvailabilityDeepAnalysis_Members] ORDER BY [MemberName];
        SELECT TOP (@Limit) * FROM [#AvailabilityDeepAnalysis_Networks] ORDER BY [MemberName], [NetworkSubnetIp];
        SELECT TOP (@Limit) * FROM [#AvailabilityDeepAnalysis_Replicas] ORDER BY [AvailabilityGroupName], [ReplicaServerName];
        SELECT TOP (@Limit) * FROM [#AvailabilityDeepAnalysis_Databases]
        ORDER BY CASE [FindingSeverity] WHEN 'HIGH' THEN 1 WHEN 'MEDIUM' THEN 2 ELSE 3 END,
                 [AvailabilityGroupName], [DatabaseName];
        SELECT TOP (@Limit) * FROM [#AvailabilityDeepAnalysis_Seeding]
        ORDER BY CASE [FindingSeverity] WHEN 'HIGH' THEN 1 WHEN 'MEDIUM' THEN 2 ELSE 3 END,
                 [StartTimeUtc] DESC;
        SELECT TOP (@Limit) * FROM [#AvailabilityDeepAnalysis_PageRepair] ORDER BY [ModificationTime] DESC;
    END
    ELSE IF @OutputMode = 'CONSOLE'
    BEGIN
        SELECT N'Always On Deep Analysis' AS [Ergebnis], @Now AS [Stand_UTC],
               @StatusCode AS [Status], @IsPartial AS [Teilweise], @ErrorMessage AS [Hinweis];
        SELECT N'Clusterquorum' AS [Ergebnis], [ClusterName] AS [Cluster],
               [QuorumTypeDesc] AS [Quorum_Typ], [QuorumStateDesc] AS [Quorum_Status], [FindingCode] AS [Befund]
        FROM [#AvailabilityDeepAnalysis_Cluster];
        SELECT TOP (@Limit) N'AG-Datenbank' AS [Ergebnis], [AvailabilityGroupName] AS [AG],
               [ReplicaServerName] AS [Replikat], [DatabaseName] AS [Datenbank],
               [SynchronizationStateDesc] AS [Synchronisation],
               [SynchronizationHealthDesc] AS [Gesundheit], [IsSuspended] AS [Suspendiert],
               [LogSendQueueSizeKb] AS [Log_Send_Queue_KB], [RedoQueueSizeKb] AS [Redo_Queue_KB],
               [SecondaryLagSeconds] AS [Lag_Sekunden], [FindingCode] AS [Befund],
               [FindingSeverity] AS [Prioritaet]
        FROM [#AvailabilityDeepAnalysis_Databases]
        ORDER BY CASE [FindingSeverity] WHEN 'HIGH' THEN 1 WHEN 'MEDIUM' THEN 2 ELSE 3 END,
                 [AvailabilityGroupName], [DatabaseName];
        SELECT TOP (@Limit) N'AG-Seeding' AS [Ergebnis], [RemoteMachineName] AS [Remote_Knoten],
               [DatabaseName] AS [Datenbank], [CurrentStateDesc] AS [Status],
               [FailureCode] AS [Fehlercode], [TransferRateBytesPerSecond] AS [Bytes_pro_Sekunde],
               [ProgressPercent] AS [Fortschritt_Prozent], [RemainingBytes] AS [Verbleibende_Bytes],
               [EstimateTimeCompleteUtc] AS [Geschaetztes_Ende_UTC], [FindingCode] AS [Befund],
               [FindingSeverity] AS [Prioritaet], [StartTimeUtc] AS [Start_UTC], [EndTimeUtc] AS [Ende_UTC]
        FROM [#AvailabilityDeepAnalysis_Seeding]
        ORDER BY CASE [FindingSeverity] WHEN 'HIGH' THEN 1 WHEN 'MEDIUM' THEN 2 ELSE 3 END,
                 [StartTimeUtc] DESC;
    END;
    IF @ConsoleResultRequested = 1
    BEGIN
        EXEC [monitor].[InternalEmitConsoleResult]
              @SourceTable=N'#AvailabilityDeepAnalysis_Replicas'
            , @ResultLabel=N'AvailabilityDeepAnalysis'
            , @EmptyMessage=N'Keine fachlichen Ergebnisse';
    END;
    IF @TableResultRequested = 1
    BEGIN
        EXEC [monitor].[InternalWriteResultTable]
              @SourceTable = N'#AvailabilityDeepAnalysis_Replicas'
            , @TargetTable=@TableTarget
            , @ThrowOnError = 1;
    END;
END;
GO
-- END SOURCE: Code/07_Infrastructure/110_USP_AvailabilityDeepAnalysis.sql

-- BEGIN SOURCE: Code/07_Infrastructure/120_USP_AgentMonitoringAnalysis.sql
/*
===============================================================================
Objekt       : monitor.USP_AgentMonitoringAnalysis
Version      : 1.1.0
Stand        : 2026-07-18
Zweck        : Prüft SQL-Agent-/Alert-/Operator-/Job- und Database-Mail-Evidenz.
Datenquellen : sys.dm_server_services, msdb.dbo.sysalerts,
               msdb.dbo.sysoperators, msdb.dbo.sysnotifications,
               msdb.dbo.sysjobs, msdb.dbo.sysjobschedules,
               msdb.dbo.sysschedules, msdb.dbo.sysjobhistory und
               msdb.dbo.sysmail_allitems.
Methodik     : Alert-Routing, Jobzustand und aggregierter Mailstatus werden über
               dieselben reinen Interpretationsfunktionen klassifiziert, die
               der deterministische Laufzeitvertrag verwendet.
Datenschutz  : Liest keine Mailadressen, Empfänger, Betreffzeilen,
               Jobschrittbefehle oder Fehlermeldungstexte.
Grenzen      : Fehlende Standardalarme sind ein Prüfauftrag; externe
               Monitoringwege können die Alarmierung anderweitig abdecken.
===============================================================================
*/
CREATE OR ALTER PROCEDURE [monitor].[USP_AgentMonitoringAnalysis]
      @HistoryHours       int             = 24
    , @MitJobStatus       bit             = 1
    , @MitDatabaseMail    bit             = 1
    , @MaxZeilen          int             = 1000
    , @ResultSetArt       varchar(16)     = 'CONSOLE'
    , @ResultTablesJson               nvarchar(max) = NULL
    , @JsonErzeugen       bit             = 0
    , @Json               nvarchar(max)   = NULL OUTPUT
    , @PrintMeldungen     bit             = 1
    , @Hilfe              bit             = 0
    , @StatusCodeOut      varchar(40)     = NULL OUTPUT
    , @IsPartialOut       bit             = NULL OUTPUT
    , @ErrorNumberOut     int             = NULL OUTPUT
    , @ErrorMessageOut    nvarchar(2048)  = NULL OUTPUT
AS
BEGIN
    SET NOCOUNT ON;
    SET LOCK_TIMEOUT 0;
    SET @Json = NULL;

    DECLARE @OutputMode varchar(16) = UPPER(LTRIM(RTRIM(COALESCE(@ResultSetArt, ''))));
    DECLARE @TableResultRequested bit = CASE WHEN @OutputMode = 'TABLE' THEN 1 ELSE 0 END;
    DECLARE @ConsoleResultRequested bit = CASE WHEN @OutputMode = 'CONSOLE' THEN 1 ELSE 0 END;
    DECLARE @TableTarget sysname=NULL;
    IF @TableResultRequested=0 AND NULLIF(LTRIM(RTRIM(COALESCE(@ResultTablesJson,N''))),N'') IS NOT NULL THROW 51011,N'@ResultTablesJson ist ausschließlich mit @ResultSetArt=TABLE zulässig.',1;
    IF @TableResultRequested=1 EXEC [monitor].[InternalPrepareSingleResultTable] @ResultTablesJson=@ResultTablesJson,@ResultName=N'findings',@TargetTable=@TableTarget OUTPUT,@ThrowOnError=1;
    IF @TableResultRequested = 1 OR @ConsoleResultRequested = 1 SET @OutputMode = 'NONE';
    DECLARE @Limit bigint = CASE WHEN @MaxZeilen IS NULL OR @MaxZeilen = 0
                                 THEN CONVERT(bigint, 9223372036854775807)
                                 ELSE CONVERT(bigint, @MaxZeilen) END;

    IF @Hilfe = 1
    BEGIN
        PRINT N'monitor.USP_AgentMonitoringAnalysis';
        PRINT N'Prüft Alarmierungs- und Jobmetadaten, liest aber keine Mailadressen, Empfänger oder Jobschrittbefehle.';
        PRINT N'Fehlende SQL-Agent-Alarme können durch externes Monitoring kompensiert sein.';
        PRINT N'@HistoryHours=24; @MaxZeilen positiv, NULL/0 = unbegrenzt.';
        RETURN;
    END;

    DECLARE @Now datetime2(3) = SYSUTCDATETIME();
    DECLARE @CutoffLocal datetime = CASE WHEN @HistoryHours IS NULL THEN NULL ELSE DATEADD(HOUR, -@HistoryHours, GETDATE()) END;
    DECLARE @StatusCode varchar(40) = 'AVAILABLE';
    DECLARE @IsPartial bit = 0;
    DECLARE @ErrorNumber int = NULL;
    DECLARE @ErrorMessage nvarchar(2048) = NULL;

    CREATE TABLE [#AgentMonitoringAnalysis_Services]
    (
          [ServiceName] nvarchar(256) NULL
        , [StatusDesc] nvarchar(60) NULL
        , [StartupTypeDesc] nvarchar(60) NULL
        , [LastStartupTime] datetimeoffset(7) NULL
        , [FindingCode] varchar(80) NOT NULL
    );
    CREATE TABLE [#AgentMonitoringAnalysis_Findings]
    (
          [Category] varchar(40) NOT NULL
        , [FindingCode] varchar(100) NOT NULL
        , [Severity] varchar(16) NOT NULL
        , [ScopeType] nvarchar(40) NOT NULL
        , [ScopeName] nvarchar(256) NULL
        , [MetricValue] bigint NULL
        , [Evidence] nvarchar(1000) NOT NULL
        , [EvidenceLimit] nvarchar(1000) NOT NULL
    );
    CREATE TABLE [#AgentMonitoringAnalysis_Jobs]
    (
          [JobId] uniqueidentifier NOT NULL
        , [JobName] sysname NOT NULL
        , [IsEnabled] tinyint NOT NULL
        , [LatestRunDateTime] datetime NULL
        , [LatestRunStatus] int NULL
        , [LatestRunDuration] int NULL
        , [ScheduleCount] bigint NOT NULL
        , [EnabledScheduleCount] bigint NOT NULL
        , [FindingCode] varchar(100) NOT NULL
        , [FindingSeverity] varchar(16) NOT NULL
    );
    CREATE TABLE [#AgentMonitoringAnalysis_Mail]
    (
          [SentStatus] varchar(8) NULL
        , [ItemCount] bigint NOT NULL
        , [OldestRequestDate] datetime NULL
        , [NewestRequestDate] datetime NULL
    );

    IF @HistoryHours IS NULL OR @HistoryHours < 1 OR @HistoryHours > 8760 OR @MaxZeilen < 0
       OR @OutputMode NOT IN ('RAW', 'CONSOLE', 'NONE')
    BEGIN
        SELECT @StatusCode = 'INVALID_PARAMETER', @IsPartial = 1,
               @ErrorMessage = N'Ungültiger Historien-, Zeilen- oder Ausgabeparameter.';
    END;

    IF @StatusCode = 'AVAILABLE'
    BEGIN
        BEGIN TRY
            INSERT [#AgentMonitoringAnalysis_Services]
            SELECT [servicename], [status_desc], [startup_type_desc], [last_startup_time],
                   CASE WHEN [status_desc] = N'Running' THEN 'AGENT_SERVICE_RUNNING'
                        ELSE 'AGENT_SERVICE_NOT_RUNNING' END
            FROM [sys].[dm_server_services] WITH (NOLOCK)
            WHERE [servicename] LIKE N'SQL Server Agent%';
        END TRY
        BEGIN CATCH
            SELECT @IsPartial = 1, @ErrorNumber = ERROR_NUMBER(),
                   @ErrorMessage = CONCAT(N'Dienststatus nicht lesbar: ', ERROR_MESSAGE());
        END CATCH;

        BEGIN TRY
            ;WITH [RequiredAlerts] AS
            (
                SELECT 'MESSAGE_823' AS [Code], 823 AS [MessageId], 0 AS [Severity]
                UNION ALL SELECT 'MESSAGE_824', 824, 0
                UNION ALL SELECT 'MESSAGE_825', 825, 0
                UNION ALL SELECT CONCAT('SEVERITY_', [n]), 0, [n]
                FROM (VALUES (19),(20),(21),(22),(23),(24),(25)) AS [v]([n])
            )
            INSERT [#AgentMonitoringAnalysis_Findings]
            SELECT
                  'ALERT_COVERAGE', 'REQUIRED_AGENT_ALERT_MISSING', 'HIGH', N'ALERT_REQUIREMENT'
                , [r].[Code], NULL
                , CONCAT(N'Kein aktivierter SQL-Agent-Alert für message_id=', [r].[MessageId],
                         N' beziehungsweise severity=', [r].[Severity], N' gefunden.')
                , N'Externe Alarmierung kann die Anforderung erfüllen; Monitoringarchitektur vor Anlage eines Alerts prüfen.'
            FROM [RequiredAlerts] AS [r]
            WHERE NOT EXISTS
            (
                SELECT 1 FROM [msdb].[dbo].[sysalerts] AS [a] WITH (NOLOCK)
                WHERE [a].[enabled] = 1
                  AND (([r].[MessageId] > 0 AND [a].[message_id] = [r].[MessageId])
                    OR ([r].[Severity] > 0 AND [a].[severity] = [r].[Severity]))
            );

            INSERT [#AgentMonitoringAnalysis_Findings]
            SELECT
                  'ALERT_ROUTING', [route].[FindingCode], [route].[FindingSeverity], N'ALERT', [a].[name]
                , CONVERT(bigint, [a].[occurrence_count])
                , N'Aktivierter Alert besitzt weder Operatorbenachrichtigung noch Jobaktion.'
                , N'Externe Weiterleitung und absichtlich rein protokollierende Alerts separat prüfen.'
            FROM [msdb].[dbo].[sysalerts] AS [a] WITH (NOLOCK)
            OUTER APPLY
            (
                SELECT [NotificationCount]=COUNT_BIG(*)
                FROM [msdb].[dbo].[sysnotifications] AS [n] WITH (NOLOCK)
                WHERE [n].[alert_id]=[a].[id]
            ) AS [notifications]
            CROSS APPLY [monitor].[TVF_InterpretAgentAlertRoute]
            (
                  CONVERT(bit,[a].[enabled])
                , CONVERT(bit,CASE WHEN [a].[job_id]<>CONVERT(uniqueidentifier,'00000000-0000-0000-0000-000000000000') THEN 1 ELSE 0 END)
                , [notifications].[NotificationCount]
            ) AS [route]
            WHERE [route].[FindingCode]='ENABLED_ALERT_WITHOUT_ACTION';

            INSERT [#AgentMonitoringAnalysis_Findings]
            SELECT
                  'ALERT_ROUTING', 'ALERT_TARGET_OPERATOR_DISABLED', 'HIGH', N'OPERATOR', [o].[name]
                , COUNT_BIG(*)
                , N'Mindestens ein aktivierter Alert verweist auf einen deaktivierten Operator.'
                , N'Externe Zustellung und Bereitschaftsmodell separat prüfen; Adressdaten werden nicht gelesen.'
            FROM [msdb].[dbo].[sysoperators] AS [o] WITH (NOLOCK)
            JOIN [msdb].[dbo].[sysnotifications] AS [n] WITH (NOLOCK) ON [n].[operator_id] = [o].[id]
            JOIN [msdb].[dbo].[sysalerts] AS [a] WITH (NOLOCK) ON [a].[id] = [n].[alert_id]
            WHERE [a].[enabled] = 1 AND [o].[enabled] = 0
            GROUP BY [o].[name];

            INSERT [#AgentMonitoringAnalysis_Findings]
            SELECT
                  'ALERT_ACTIVITY', 'ALERT_OCCURRED_IN_WINDOW', 'MEDIUM', N'ALERT', [a].[name]
                , CONVERT(bigint, [a].[occurrence_count])
                , N'Der Alert besitzt eine Auftretenshistorie; Meldungstext wird nicht gelesen.'
                , N'occurrence_count kann seit einem früheren Reset kumulativ sein; Zeitstempel und externes Monitoring korrelieren.'
            FROM [msdb].[dbo].[sysalerts] AS [a] WITH (NOLOCK)
            WHERE [a].[enabled] = 1 AND [a].[occurrence_count] > 0
              AND [a].[last_occurrence_date] > 0
              AND [msdb].[dbo].[agent_datetime]
                  ([a].[last_occurrence_date], [a].[last_occurrence_time]) >= @CutoffLocal;
        END TRY
        BEGIN CATCH
            SELECT @IsPartial = 1;
            IF @ErrorNumber IS NULL
                SELECT @ErrorNumber = ERROR_NUMBER(),
                       @ErrorMessage = CONCAT(N'Alert-/Operatorstatus nicht lesbar: ', ERROR_MESSAGE());
        END CATCH;

        IF @MitJobStatus = 1
        BEGIN
            BEGIN TRY
                ;WITH [LatestOutcome] AS
                (
                    SELECT [h].[job_id], [h].[run_status], [h].[run_duration],
                           [msdb].[dbo].[agent_datetime]([h].[run_date], [h].[run_time]) AS [RunDateTime],
                           ROW_NUMBER() OVER
                           (PARTITION BY [h].[job_id] ORDER BY [h].[instance_id] DESC) AS [rn]
                    FROM [msdb].[dbo].[sysjobhistory] AS [h] WITH (NOLOCK)
                    WHERE [h].[step_id] = 0 AND [h].[run_date] > 0
                ),
                [Schedules] AS
                (
                    SELECT [js].[job_id], COUNT_BIG(*) AS [ScheduleCount],
                           SUM(CONVERT(bigint, CASE WHEN [s].[enabled] = 1 THEN 1 ELSE 0 END)) AS [EnabledCount]
                    FROM [msdb].[dbo].[sysjobschedules] AS [js] WITH (NOLOCK)
                    JOIN [msdb].[dbo].[sysschedules] AS [s] WITH (NOLOCK) ON [s].[schedule_id] = [js].[schedule_id]
                    GROUP BY [js].[job_id]
                )
                INSERT [#AgentMonitoringAnalysis_Jobs]
                SELECT
                      [j].[job_id], [j].[name], [j].[enabled], [o].[RunDateTime], [o].[run_status]
                    , [o].[run_duration], COALESCE([s].[ScheduleCount], 0), COALESCE([s].[EnabledCount], 0)
                    , [state].[FindingCode], [state].[FindingSeverity]
                FROM [msdb].[dbo].[sysjobs] AS [j] WITH (NOLOCK)
                LEFT JOIN [LatestOutcome] AS [o] ON [o].[job_id] = [j].[job_id] AND [o].[rn] = 1
                LEFT JOIN [Schedules] AS [s] ON [s].[job_id] = [j].[job_id]
                CROSS APPLY [monitor].[TVF_InterpretAgentJobState]
                (
                      [j].[enabled], [o].[run_status], [o].[RunDateTime], @CutoffLocal
                    , COALESCE([s].[ScheduleCount],0), COALESCE([s].[EnabledCount],0)
                ) AS [state];
            END TRY
            BEGIN CATCH
                SELECT @IsPartial = 1;
                IF @ErrorNumber IS NULL
                    SELECT @ErrorNumber = ERROR_NUMBER(),
                           @ErrorMessage = CONCAT(N'Jobstatus nicht lesbar: ', ERROR_MESSAGE());
            END CATCH;
        END;

        IF @MitDatabaseMail = 1
        BEGIN
            BEGIN TRY
                INSERT [#AgentMonitoringAnalysis_Mail]
                SELECT [sent_status], COUNT_BIG(*), MIN([send_request_date]), MAX([send_request_date])
                FROM [msdb].[dbo].[sysmail_allitems] WITH (NOLOCK)
                WHERE [send_request_date] >= @CutoffLocal
                GROUP BY [sent_status];
            END TRY
            BEGIN CATCH
                SELECT @IsPartial = 1;
                IF @ErrorNumber IS NULL
                    SELECT @ErrorNumber = ERROR_NUMBER(),
                           @ErrorMessage = CONCAT(N'Database-Mail-Status nicht lesbar: ', ERROR_MESSAGE());
            END CATCH;
        END;

        INSERT [#AgentMonitoringAnalysis_Findings]
        SELECT 'JOB_ACTIVITY', [FindingCode], [FindingSeverity],
               N'JOB', [JobName], NULL,
               CONCAT(N'Letzter Status=', COALESCE(CONVERT(nvarchar(20), [LatestRunStatus]), N'NULL'),
                      N'; Schedules=', [ScheduleCount], N'; aktive Schedules=', [EnabledScheduleCount], N'.'),
               N'On-demand Jobs und externe Scheduler können einen fehlenden SQL-Agent-Zeitplan erklären.'
        FROM [#AgentMonitoringAnalysis_Jobs]
        WHERE [FindingCode] <> 'JOB_STATE_INFORMATIONAL';

        INSERT [#AgentMonitoringAnalysis_Findings]
        SELECT 'DATABASE_MAIL', [state].[FindingCode], [state].[FindingSeverity],
               N'MAIL_STATUS', [m].[SentStatus], [m].[ItemCount],
               CONCAT(N'Database-Mail-Elemente mit Status ', [m].[SentStatus], N' im Sichtfenster.'),
               N'Empfänger, Betreff und Nachrichtentext werden bewusst nicht gelesen; Mailserver separat prüfen.'
        FROM [#AgentMonitoringAnalysis_Mail] AS [m]
        CROSS APPLY [monitor].[TVF_InterpretDatabaseMailStatus]([m].[SentStatus]) AS [state]
        WHERE [state].[FindingSeverity] IN ('HIGH','MEDIUM');

        IF @IsPartial = 1
            SET @StatusCode = 'AVAILABLE_LIMITED';
        ELSE IF EXISTS
                (
                    SELECT 1 FROM [#AgentMonitoringAnalysis_Findings] WHERE [Severity] IN ('HIGH', 'MEDIUM')
                    UNION ALL
                    SELECT 1 FROM [#AgentMonitoringAnalysis_Services] WHERE [FindingCode] = 'AGENT_SERVICE_NOT_RUNNING'
                )
            SET @StatusCode = 'AVAILABLE_WITH_FINDING';
    END;

    SELECT @StatusCodeOut = @StatusCode, @IsPartialOut = @IsPartial,
           @ErrorNumberOut = @ErrorNumber, @ErrorMessageOut = @ErrorMessage;

    IF @JsonErzeugen = 1
    BEGIN
        DECLARE @MetaJson nvarchar(max) =
            (SELECT N'AgentMonitoringAnalysis' AS [resultName], 1 AS [schemaVersion],
                    @Now AS [generatedAtUtc], @StatusCode AS [statusCode], @IsPartial AS [isPartial],
                    @HistoryHours AS [historyHours]
             FOR JSON PATH, WITHOUT_ARRAY_WRAPPER);
        DECLARE @ServicesJson nvarchar(max) = (SELECT * FROM [#AgentMonitoringAnalysis_Services] FOR JSON PATH, INCLUDE_NULL_VALUES);
        DECLARE @FindingsJson nvarchar(max) =
            (SELECT TOP (@Limit) * FROM [#AgentMonitoringAnalysis_Findings]
             ORDER BY CASE [Severity] WHEN 'HIGH' THEN 1 WHEN 'MEDIUM' THEN 2 ELSE 3 END,
                      [Category], [ScopeName] FOR JSON PATH, INCLUDE_NULL_VALUES);
        DECLARE @JobsJson nvarchar(max) =
            (SELECT TOP (@Limit) * FROM [#AgentMonitoringAnalysis_Jobs] ORDER BY [JobName] FOR JSON PATH, INCLUDE_NULL_VALUES);
        DECLARE @MailJson nvarchar(max) =
            (SELECT * FROM [#AgentMonitoringAnalysis_Mail] ORDER BY [SentStatus] FOR JSON PATH, INCLUDE_NULL_VALUES);
        SET @Json = CONCAT(N'{"meta":', COALESCE(@MetaJson, N'{}'),
                           N',"services":', COALESCE(@ServicesJson, N'[]'),
                           N',"findings":', COALESCE(@FindingsJson, N'[]'),
                           N',"jobs":', COALESCE(@JobsJson, N'[]'),
                           N',"mailStatus":', COALESCE(@MailJson, N'[]'), N'}');
    END;

    IF @OutputMode = 'RAW'
    BEGIN
        SELECT N'USP_AgentMonitoringAnalysis' AS [ModuleName], @Now AS [CollectionTimeUtc],
               @StatusCode AS [StatusCode], @IsPartial AS [IsPartial],
               @ErrorNumber AS [ErrorNumber], @ErrorMessage AS [ErrorMessage],
               N'Keine Adressen, Empfänger, Jobbefehle oder Nachrichtentexte gelesen.' AS [Detail];
        SELECT * FROM [#AgentMonitoringAnalysis_Services];
        SELECT TOP (@Limit) * FROM [#AgentMonitoringAnalysis_Findings]
        ORDER BY CASE [Severity] WHEN 'HIGH' THEN 1 WHEN 'MEDIUM' THEN 2 ELSE 3 END,
                 [Category], [ScopeName];
        SELECT TOP (@Limit) * FROM [#AgentMonitoringAnalysis_Jobs] ORDER BY [JobName];
        SELECT * FROM [#AgentMonitoringAnalysis_Mail] ORDER BY [SentStatus];
    END
    ELSE IF @OutputMode = 'CONSOLE'
    BEGIN
        SELECT N'Agent- und Alert-Monitoring' AS [Ergebnis], @Now AS [Stand_UTC],
               @StatusCode AS [Status], @IsPartial AS [Teilweise], @ErrorMessage AS [Hinweis];
        SELECT N'SQL-Agent-Dienst' AS [Ergebnis], [ServiceName] AS [Dienst],
               [StatusDesc] AS [Status], [StartupTypeDesc] AS [Starttyp],
               [LastStartupTime] AS [Letzter_Start], [FindingCode] AS [Befund]
        FROM [#AgentMonitoringAnalysis_Services];
        SELECT TOP (@Limit) N'Monitoring-Befund' AS [Ergebnis], [Category] AS [Kategorie],
               [ScopeType] AS [Bereichstyp], [ScopeName] AS [Bereich],
               [FindingCode] AS [Befund], [Severity] AS [Prioritaet],
               [MetricValue] AS [Messwert], [Evidence] AS [Evidenz], [EvidenceLimit] AS [Grenze]
        FROM [#AgentMonitoringAnalysis_Findings]
        ORDER BY CASE [Severity] WHEN 'HIGH' THEN 1 WHEN 'MEDIUM' THEN 2 ELSE 3 END,
                 [Category], [ScopeName];
    END;
    IF @ConsoleResultRequested = 1
    BEGIN
        EXEC [monitor].[InternalEmitConsoleResult]
              @SourceTable=N'#AgentMonitoringAnalysis_Findings'
            , @ResultLabel=N'AgentMonitoringAnalysis'
            , @EmptyMessage=N'Keine fachlichen Ergebnisse';
    END;
    IF @TableResultRequested = 1
    BEGIN
        EXEC [monitor].[InternalWriteResultTable]
              @SourceTable = N'#AgentMonitoringAnalysis_Findings'
            , @TargetTable=@TableTarget
            , @ThrowOnError = 1;
    END;
END;
GO
-- END SOURCE: Code/07_Infrastructure/120_USP_AgentMonitoringAnalysis.sql

-- BEGIN SOURCE: Code/07_Infrastructure/130_USP_MaintenanceOperations.sql
/*
===============================================================================
Objekt       : monitor.USP_MaintenanceOperations
Version      : 1.0.0
Stand        : 2026-07-18
Zweck        : Liefert eine korrelierte, rein lesende Sicht auf laufende
               Wartungsanforderungen, resumierbare Indexoperationen, ADR/PVS
               und explizit gewählte Jobs.
Datenschutz  : Liest keine SQL-Texte, Jobschritte, Befehle, Meldungen, Konten,
               Clientdaten, Wait-Ressourcen oder Objektdefinitionen.
Grenzen      : Dauer und Pausenzustand sind Kontext, kein automatischer Defekt.
               Die Prozedur setzt nichts fort, bricht nichts ab und beendet nichts.
===============================================================================
*/
CREATE OR ALTER PROCEDURE [monitor].[USP_MaintenanceOperations]
      @DatabaseNames                       nvarchar(max)  = NULL
    , @SystemdatenbankenEinbeziehen        bit            = 0
    , @DatabaseNamePattern                 nvarchar(4000) = NULL
    , @HighImpactConfirmed              bit            = 0
    , @JobNames                            nvarchar(max)  = NULL
    , @JobNamePattern                      nvarchar(4000) = NULL
    , @NurProblematisch                    bit            = 0
    , @ResumablePausedWarnMinutes          int            = 60
    , @BlockedWarnMs                       bigint         = 5000
    , @PvsWarnMb                           decimal(19,2)  = 1024
    , @AbortedTransactionsWarnCount        bigint         = 1
    , @MaxZeilen                           int            = 1000
    , @LockTimeoutMs                       int            = 0
    , @ResultSetArt                        varchar(16)    = 'CONSOLE'
    , @ResultTablesJson               nvarchar(max) = NULL
    , @JsonErzeugen                        bit            = 0
    , @Json                                nvarchar(max)  = NULL OUTPUT
    , @PrintMeldungen                      bit            = 1
    , @Hilfe                               bit            = 0
    , @StatusCodeOut                       varchar(40)    = NULL OUTPUT
    , @IsPartialOut                        bit            = NULL OUTPUT
    , @ErrorNumberOut                      int            = NULL OUTPUT
    , @ErrorMessageOut                     nvarchar(2048) = NULL OUTPUT
AS
BEGIN
    SET NOCOUNT ON;
    SET @Json=NULL;

    DECLARE @Now datetime2(3)=SYSUTCDATETIME();
    DECLARE @OutputMode varchar(16)=UPPER(LTRIM(RTRIM(COALESCE(@ResultSetArt,''))));
    DECLARE @TableResultRequested bit = CASE WHEN @OutputMode = 'TABLE' THEN 1 ELSE 0 END;
    DECLARE @ConsoleResultRequested bit = CASE WHEN @OutputMode = 'CONSOLE' THEN 1 ELSE 0 END;
    DECLARE @TableTarget sysname=NULL;
    IF @TableResultRequested=0 AND NULLIF(LTRIM(RTRIM(COALESCE(@ResultTablesJson,N''))),N'') IS NOT NULL THROW 51011,N'@ResultTablesJson ist ausschließlich mit @ResultSetArt=TABLE zulässig.',1;
    IF @TableResultRequested=1 EXEC [monitor].[InternalPrepareSingleResultTable] @ResultTablesJson=@ResultTablesJson,@ResultName=N'resumableOperations',@TargetTable=@TableTarget OUTPUT,@ThrowOnError=1;
    IF @TableResultRequested = 1 OR @ConsoleResultRequested = 1 SET @OutputMode = 'NONE';
    DECLARE @Limit bigint=CASE WHEN @MaxZeilen IS NULL OR @MaxZeilen=0
                               THEN CONVERT(bigint,9223372036854775807)
                               ELSE CONVERT(bigint,@MaxZeilen) END;
    DECLARE @Major int=TRY_CONVERT(int,SERVERPROPERTY('ProductMajorVersion'));
    DECLARE @StatusCode varchar(40)='AVAILABLE';
    DECLARE @IsPartial bit=0;
    DECLARE @ErrorNumber int=NULL;
    DECLARE @ErrorMessage nvarchar(2048)=NULL;
    DECLARE @CrossDatabaseRequested bit=0;
    DECLARE @JobPatternMode varchar(8),@JobPatternValue nvarchar(4000),@JobPatternIsValid bit;
    SELECT @JobPatternMode=[PatternMode],@JobPatternValue=[PatternValue],@JobPatternIsValid=[IsValid]
    FROM [monitor].[TVF_ParsePattern](@JobNamePattern);
    DECLARE @JobFilterRequested bit=CONVERT(bit,CASE WHEN NULLIF(LTRIM(RTRIM(@JobNames)),N'') IS NOT NULL
                                                      OR NULLIF(LTRIM(RTRIM(@JobNamePattern)),N'') IS NOT NULL
                                                     THEN 1 ELSE 0 END);

    IF @Hilfe=1
    BEGIN
        PRINT N'monitor.USP_MaintenanceOperations';
        PRINT N'Die Procedure liefert eine korrelierte, rein lesende Sicht auf Wartungsrequests, resumierbare Indexoperationen, ADR/PVS und explizit gefilterte Agent-Jobs.';
        PRINT N'Ohne @JobNames oder @JobNamePattern werden weder Jobnamen noch Jobaktivitaet gelesen; JobNamePattern ist ein LIKE-Pattern.';
        PRINT N'Keine SQL-Texte, Jobschritte, Befehlsinhalte, Meldungen, Konten, Clientdaten oder Wait-Ressourcen werden gelesen.';
        RETURN;
    END;

    CREATE TABLE [#MaintenanceOperations_DatabaseCandidates]
    (
          [DatabaseId] int NOT NULL PRIMARY KEY,[DatabaseName] sysname NOT NULL,[StateDesc] nvarchar(60) NULL
        , [UserAccessDesc] nvarchar(60) NULL,[IsReadOnly] bit NULL,[CompatibilityLevel] tinyint NULL
        , [CollationName] sysname NULL,[RecoveryModelDesc] nvarchar(60) NULL,[IsSystemDatabase] bit NULL
        , [RequestedOrdinal] int NULL
    );
    CREATE TABLE [#MaintenanceOperations_DatabaseCandidateWarnings]
    (
          [RequestedName] sysname NULL,[StatusCode] varchar(40) NOT NULL,[ErrorMessage] nvarchar(2048) NULL
    );
    CREATE TABLE [#MaintenanceOperations_SourceStatus]
    (
          [SourceName] nvarchar(128) NOT NULL PRIMARY KEY,[StatusCode] varchar(40) NOT NULL
        , [IsPartial] bit NOT NULL,[Detail] nvarchar(1000) NOT NULL
    );
    CREATE TABLE [#MaintenanceOperations_Resumable]
    (
          [DatabaseId] int NOT NULL,[DatabaseName] sysname NOT NULL,[SchemaName] sysname NULL
        , [ObjectName] sysname NULL,[IndexName] sysname NULL,[PartitionNumber] int NULL
        , [StateDesc] nvarchar(60) NULL,[StartTime] datetime NULL,[LastPauseTime] datetime NULL
        , [TotalExecutionTimeMinutes] bigint NULL,[PercentComplete] real NULL,[PageCount] bigint NULL
        , [FindingCode] varchar(100) NOT NULL,[FindingSeverity] varchar(16) NOT NULL
        , [EvidenceLimit] nvarchar(1000) NOT NULL
    );
    CREATE TABLE [#MaintenanceOperations_Requests]
    (
          [SessionId] smallint NOT NULL,[RequestId] int NOT NULL,[DatabaseId] int NULL,[DatabaseName] sysname NULL
        , [Command] nvarchar(60) NULL,[Status] nvarchar(30) NULL,[StartTime] datetime NULL
        , [ElapsedMs] int NULL,[PercentComplete] real NULL,[EstimatedCompletionMs] bigint NULL
        , [BlockingSessionId] smallint NULL,[WaitType] nvarchar(120) NULL,[WaitTimeMs] int NULL
        , [Reads] bigint NULL,[Writes] bigint NULL,[IsResumable] bit NULL
        , [FindingCode] varchar(100) NOT NULL,[FindingSeverity] varchar(16) NOT NULL
        , [EvidenceLimit] nvarchar(1000) NOT NULL
    );
    CREATE TABLE [#MaintenanceOperations_Pvs]
    (
          [DatabaseId] int NOT NULL,[DatabaseName] sysname NOT NULL,[AdrEnabled] bit NOT NULL
        , [PvsSizeMb] decimal(19,2) NULL,[OnlineIndexPvsSizeMb] decimal(19,2) NULL
        , [CurrentAbortedTransactionCount] bigint NULL
        , [FindingCode] varchar(100) NOT NULL,[FindingSeverity] varchar(16) NOT NULL
        , [EvidenceLimit] nvarchar(1000) NOT NULL
    );
    CREATE TABLE [#MaintenanceOperations_Jobs]
    (
          [JobName] sysname NOT NULL,[StartExecutionDate] datetime NULL,[StopExecutionDate] datetime NULL
        , [IsRunning] bit NOT NULL,[FindingCode] varchar(100) NOT NULL,[FindingSeverity] varchar(16) NOT NULL
        , [EvidenceLimit] nvarchar(1000) NOT NULL
    );

    IF @MaxZeilen<0 OR @LockTimeoutMs<0
       OR @ResumablePausedWarnMinutes<1 OR @ResumablePausedWarnMinutes>525600
       OR @BlockedWarnMs<0 OR @PvsWarnMb<0 OR @AbortedTransactionsWarnCount<0
       OR @JobPatternIsValid=0 OR (@JobNames IS NOT NULL AND @JobNamePattern IS NOT NULL)
       OR @OutputMode NOT IN ('RAW','CONSOLE','NONE')
    BEGIN
        SELECT @StatusCode='INVALID_PARAMETER',@IsPartial=1,
               @ErrorMessage=N'Ungueltiger Grenzwert, Datenbank-, Zeilen- oder Ausgabeparameter.';
    END;
    IF @StatusCode='AVAILABLE' AND @JobPatternMode IN ('REGEX','REGEXI')
    BEGIN
        SELECT @StatusCode='UNAVAILABLE_FEATURE',@IsPartial=1,
               @ErrorMessage=N'Dieses Metadatenmodul unterstuetzt fuer Jobnamen exakte Listen und LIKE-Pattern; Regex wird nicht ausgefuehrt.';
    END;
    IF @StatusCode='AVAILABLE' AND @JobNames IS NOT NULL
       AND EXISTS(SELECT 1 FROM [monitor].[TVF_ParseStringList](@JobNames) WHERE [IsValid]=0)
    BEGIN
        SELECT @StatusCode='INVALID_PARAMETER',@IsPartial=1,
               @ErrorMessage=N'@JobNames enthaelt mindestens einen ungueltigen Listenwert.';
    END;

    IF @StatusCode='AVAILABLE'
    BEGIN
        EXEC [monitor].[USP_PrepareDatabaseCandidates]
              @DatabaseNames=@DatabaseNames,@SystemdatenbankenEinbeziehen=@SystemdatenbankenEinbeziehen
            , @DatabaseNamePattern=@DatabaseNamePattern,@HighImpactConfirmed=@HighImpactConfirmed,@AnalysisClass=NULL
            , @StatusCode=@StatusCode OUTPUT,@ErrorMessage=@ErrorMessage OUTPUT
            , @CrossDatabaseRequested=@CrossDatabaseRequested OUTPUT,@CandidateTable=N'#MaintenanceOperations_DatabaseCandidates',@WarningTable=N'#MaintenanceOperations_DatabaseCandidateWarnings';
    END;

    SET LOCK_TIMEOUT 0;

    IF @StatusCode='AVAILABLE'
    BEGIN
        BEGIN TRY
            DECLARE @DatabaseId int,@DatabaseName sysname,@Sql nvarchar(max);
            DECLARE [database_cursor] CURSOR LOCAL FAST_FORWARD FOR
                SELECT [DatabaseId],[DatabaseName] FROM [#MaintenanceOperations_DatabaseCandidates]
                WHERE [StateDesc]=N'ONLINE' AND [DatabaseId]<>2 ORDER BY [DatabaseId];
            OPEN [database_cursor];
            FETCH NEXT FROM [database_cursor] INTO @DatabaseId,@DatabaseName;
            WHILE @@FETCH_STATUS=0
            BEGIN
                BEGIN TRY
                    SET @Sql=N'SET LOCK_TIMEOUT '+CONVERT(nvarchar(11),@LockTimeoutMs)+N'; INSERT [#MaintenanceOperations_Resumable] '
                        +N'([DatabaseId],[DatabaseName],[SchemaName],[ObjectName],[IndexName],[PartitionNumber],[StateDesc],'
                        +N'[StartTime],[LastPauseTime],[TotalExecutionTimeMinutes],[PercentComplete],[PageCount],'
                        +N'[FindingCode],[FindingSeverity],[EvidenceLimit]) '
                        +N'SELECT @pDatabaseId,@pDatabaseName,[s].[name],[t].[name],COALESCE([i].[name],[r].[name]),'
                        +N'[r].[partition_number],[r].[state_desc],[r].[start_time],[r].[last_pause_time],'
                        +N'[r].[total_execution_time],[r].[percent_complete],[r].[page_count],'
                        +N'CASE WHEN [r].[state_desc]=N''PAUSED'' AND COALESCE([r].[last_pause_time],[r].[start_time])<DATEADD(MINUTE,-@pWarnMinutes,GETDATE()) '
                        +N'THEN ''RESUMABLE_OPERATION_PAUSED_LONG'' WHEN [r].[state_desc]=N''PAUSED'' THEN ''RESUMABLE_OPERATION_PAUSED'' '
                        +N'ELSE ''RESUMABLE_OPERATION_ACTIVE'' END,'
                        +N'CASE WHEN [r].[state_desc]=N''PAUSED'' AND COALESCE([r].[last_pause_time],[r].[start_time])<DATEADD(MINUTE,-@pWarnMinutes,GETDATE()) '
                        +N'THEN ''MEDIUM'' ELSE ''INFO'' END,'
                        +N'N''Ein Pausenzustand kann beabsichtigt sein; keine automatische RESUME- oder ABORT-Aktion.'' '
                        +N'FROM '+QUOTENAME(@DatabaseName)+N'.[sys].[index_resumable_operations] AS [r] WITH (NOLOCK) '
                        +N'LEFT JOIN '+QUOTENAME(@DatabaseName)+N'.[sys].[tables] AS [t] WITH (NOLOCK) ON [t].[object_id]=[r].[object_id] '
                        +N'LEFT JOIN '+QUOTENAME(@DatabaseName)+N'.[sys].[schemas] AS [s] WITH (NOLOCK) ON [s].[schema_id]=[t].[schema_id] '
                        +N'LEFT JOIN '+QUOTENAME(@DatabaseName)+N'.[sys].[indexes] AS [i] WITH (NOLOCK) '
                        +N'ON [i].[object_id]=[r].[object_id] AND [i].[index_id]=[r].[index_id];';
                    EXEC [sys].[sp_executesql] @Sql,
                         N'@pDatabaseId int,@pDatabaseName sysname,@pWarnMinutes int',
                         @pDatabaseId=@DatabaseId,@pDatabaseName=@DatabaseName,@pWarnMinutes=@ResumablePausedWarnMinutes;
                END TRY
                BEGIN CATCH
                    SET @IsPartial=1;
                    INSERT [#MaintenanceOperations_DatabaseCandidateWarnings] VALUES
                    (@DatabaseName,CASE WHEN ERROR_NUMBER() IN (229,371,916) THEN 'DENIED_PERMISSION' ELSE 'ERROR_HANDLED' END,
                     N'Resumierbare Indexoperationen waren fuer diese Datenbank nicht lesbar.');
                END CATCH;
                FETCH NEXT FROM [database_cursor] INTO @DatabaseId,@DatabaseName;
            END;
            CLOSE [database_cursor];
            DEALLOCATE [database_cursor];
            INSERT [#MaintenanceOperations_SourceStatus] VALUES
            (N'sys.index_resumable_operations','AVAILABLE',@IsPartial,
             N'Resumierbare Indexoperationen ohne SQL-Text; pausierte Operationen werden niemals automatisch veraendert.');
        END TRY
        BEGIN CATCH
            IF CURSOR_STATUS('local','database_cursor')>=0 CLOSE [database_cursor];
            IF CURSOR_STATUS('local','database_cursor')>-3 DEALLOCATE [database_cursor];
            INSERT [#MaintenanceOperations_SourceStatus] VALUES
            (N'sys.index_resumable_operations','ERROR_HANDLED',1,N'Die datenbanklokale Abfrage wurde abgefangen.');
            SELECT @IsPartial=1,@ErrorNumber=ERROR_NUMBER(),@ErrorMessage=ERROR_MESSAGE();
        END CATCH;

        BEGIN TRY
            INSERT [#MaintenanceOperations_Requests]
            SELECT [r].[session_id],[r].[request_id],[r].[database_id],[d].[DatabaseName],
                   [r].[command],[r].[status],[r].[start_time],[r].[total_elapsed_time],[r].[percent_complete],
                   [r].[estimated_completion_time],[r].[blocking_session_id],[r].[wait_type],[r].[wait_time],
                   [r].[reads],[r].[writes],[r].[is_resumable],
                   CASE WHEN [r].[blocking_session_id]>0 AND [r].[wait_time]>=@BlockedWarnMs
                        THEN 'MAINTENANCE_REQUEST_BLOCKED' WHEN [r].[command] LIKE N'ROLLBACK%'
                        THEN 'ROLLBACK_IN_PROGRESS' ELSE 'MAINTENANCE_REQUEST_ACTIVE' END,
                   CASE WHEN [r].[blocking_session_id]>0 AND [r].[wait_time]>=@BlockedWarnMs THEN 'MEDIUM' ELSE 'INFO' END,
                   N'Fortschritt und Restzeit sind Engine-Schaetzwerte; SQL-Text, Handles, Konten, Clients und Wait-Ressourcen bleiben ausgeschlossen.'
            FROM [sys].[dm_exec_requests] AS [r] WITH (NOLOCK)
            LEFT JOIN [#MaintenanceOperations_DatabaseCandidates] AS [d] ON [d].[DatabaseId]=[r].[database_id]
            WHERE [r].[session_id]<>@@SPID
              AND ([r].[database_id] IN (SELECT [DatabaseId] FROM [#MaintenanceOperations_DatabaseCandidates]) OR [r].[database_id] IS NULL)
              AND ([r].[command] LIKE N'ALTER INDEX%'
                OR [r].[command] LIKE N'DBCC%'
                OR [r].[command] LIKE N'BACKUP%'
                OR [r].[command] LIKE N'RESTORE%'
                OR [r].[command] LIKE N'ROLLBACK%');
            INSERT [#MaintenanceOperations_SourceStatus] VALUES
            (N'sys.dm_exec_requests','AVAILABLE',0,
             N'Nur technische Request-, Fortschritts-, Blockierungs- und IO-Zaehler; keine Identitaets-, Client- oder SQL-Daten.');
        END TRY
        BEGIN CATCH
            INSERT [#MaintenanceOperations_SourceStatus] VALUES
            (N'sys.dm_exec_requests',CASE WHEN ERROR_NUMBER() IN (229,371) THEN 'DENIED_PERMISSION' ELSE 'ERROR_HANDLED' END,1,
             N'Laufende Wartungsrequests waren nicht lesbar; die uebrigen Quellen werden weiter ausgewertet.');
            SELECT @IsPartial=1,@ErrorNumber=ERROR_NUMBER(),@ErrorMessage=ERROR_MESSAGE();
        END CATCH;

        INSERT [#MaintenanceOperations_Pvs]
        ([DatabaseId],[DatabaseName],[AdrEnabled],[PvsSizeMb],[OnlineIndexPvsSizeMb],
         [CurrentAbortedTransactionCount],
         [FindingCode],[FindingSeverity],[EvidenceLimit])
        SELECT [c].[DatabaseId],[c].[DatabaseName],[d].[is_accelerated_database_recovery_on],NULL,NULL,NULL,
               CASE WHEN [d].[is_accelerated_database_recovery_on]=1 THEN 'ADR_ENABLED_PVS_DETAIL_PENDING' ELSE 'ADR_NOT_ENABLED' END,
               'INFO',N'ADR/PVS-Zaehler sind Zeitpunktwerte und beweisen allein keine Bereinigungsstoerung.'
        FROM [#MaintenanceOperations_DatabaseCandidates] AS [c]
        JOIN [sys].[databases] AS [d] WITH (NOLOCK) ON [d].[database_id]=[c].[DatabaseId];

        IF @Major>=16
        BEGIN
          BEGIN TRY
            SET @Sql=N'SET LOCK_TIMEOUT '+CONVERT(nvarchar(11),@LockTimeoutMs)+N'; UPDATE [p] SET '
                +N'[PvsSizeMb]=CONVERT(decimal(19,2),[s].[persistent_version_store_size_kb]/1024.0),'
                +N'[OnlineIndexPvsSizeMb]=CONVERT(decimal(19,2),[s].[online_index_version_store_size_kb]/1024.0),'
                +N'[CurrentAbortedTransactionCount]=[s].[current_aborted_transaction_count] '
                +N'FROM [#MaintenanceOperations_Pvs] AS [p] JOIN [sys].[dm_tran_persistent_version_store_stats] AS [s] WITH (NOLOCK) '
                +N'ON [s].[database_id]=[p].[DatabaseId];';
            EXEC [sys].[sp_executesql] @Sql;

            UPDATE [p]
            SET [FindingCode]=CASE
                    WHEN [PvsSizeMb]>=@PvsWarnMb AND [CurrentAbortedTransactionCount]>=@AbortedTransactionsWarnCount
                        THEN 'PVS_LARGE_WITH_ABORTED_TRANSACTIONS'
                    WHEN [PvsSizeMb]>=@PvsWarnMb THEN 'PVS_SIZE_THRESHOLD_REACHED'
                    WHEN [CurrentAbortedTransactionCount]>=@AbortedTransactionsWarnCount
                        THEN 'ABORTED_TRANSACTIONS_VISIBLE' ELSE 'PVS_WITHIN_THRESHOLDS' END,
                [FindingSeverity]=CASE WHEN [PvsSizeMb]>=@PvsWarnMb
                                        OR [CurrentAbortedTransactionCount]>=@AbortedTransactionsWarnCount
                                       THEN 'MEDIUM' ELSE 'INFO' END
            FROM [#MaintenanceOperations_Pvs] AS [p] WHERE [AdrEnabled]=1;
            INSERT [#MaintenanceOperations_SourceStatus] VALUES
            (N'sys.dm_tran_persistent_version_store_stats','AVAILABLE',0,
             N'Aggregierte ADR/PVS-Zaehler; Verfuegbarkeit wird fuer SQL Server 2022 oder neuer geprueft.');
          END TRY
          BEGIN CATCH
            INSERT [#MaintenanceOperations_SourceStatus] VALUES
            (N'sys.dm_tran_persistent_version_store_stats',CASE WHEN ERROR_NUMBER() IN (229,371) THEN 'DENIED_PERMISSION' ELSE 'ERROR_HANDLED' END,1,
             N'ADR/PVS-Detailzaehler waren nicht lesbar; ADR-Konfiguration bleibt sichtbar.');
            SELECT @IsPartial=1,@ErrorNumber=ERROR_NUMBER(),@ErrorMessage=ERROR_MESSAGE();
          END CATCH;
        END
        ELSE
        BEGIN
            INSERT [#MaintenanceOperations_SourceStatus] VALUES
            (N'sys.dm_tran_persistent_version_store_stats','UNAVAILABLE_VERSION',1,
             N'Der stabile Detailvertrag dieses Moduls beginnt mit SQL Server 2022; SQL Server 2019 liefert nur den ADR-Kontext.');
        END;

        IF @JobFilterRequested=1
        BEGIN
          BEGIN TRY
            ;WITH [CurrentAgentSession] AS
            (
                SELECT MAX([session_id]) AS [session_id] FROM [msdb].[dbo].[syssessions] WITH (NOLOCK)
            )
            INSERT [#MaintenanceOperations_Jobs]
            SELECT [j].[name],[a].[start_execution_date],[a].[stop_execution_date],
                   CONVERT(bit,CASE WHEN [a].[start_execution_date] IS NOT NULL AND [a].[stop_execution_date] IS NULL THEN 1 ELSE 0 END),
                   'SELECTED_JOB_STATE','INFO',
                   N'Nur explizit gefilterter Jobname und Laufstatus; keine Owner, Schritte, Befehle oder Meldungen.'
            FROM [msdb].[dbo].[sysjobs] AS [j] WITH (NOLOCK)
            LEFT JOIN [CurrentAgentSession] AS [s] ON 1=1
            LEFT JOIN [msdb].[dbo].[sysjobactivity] AS [a] WITH (NOLOCK)
              ON [a].[session_id]=[s].[session_id] AND [a].[job_id]=[j].[job_id]
            WHERE (@JobNames IS NULL OR EXISTS
                  (SELECT 1 FROM [monitor].[TVF_ParseStringList](@JobNames) AS [f]
                   WHERE [f].[IsValid]=1 AND [f].[StringValue]=[j].[name] COLLATE SQL_Latin1_General_CP1_CS_AS))
              AND (@JobPatternMode='NONE' OR [j].[name] COLLATE SQL_Latin1_General_CP1_CS_AS LIKE @JobPatternValue COLLATE SQL_Latin1_General_CP1_CS_AS);

            IF (SELECT COUNT_BIG(*) FROM [#MaintenanceOperations_Jobs] WHERE [IsRunning]=1)>1
                UPDATE [#MaintenanceOperations_Jobs] SET [FindingCode]='SELECTED_JOBS_OVERLAP',[FindingSeverity]='MEDIUM'
                WHERE [IsRunning]=1;

            INSERT [#MaintenanceOperations_SourceStatus] VALUES
            (N'msdb.dbo.sysjobs + msdb.dbo.sysjobactivity','AVAILABLE',0,
             N'Jobquelle wurde nur wegen eines expliziten Namens- oder Patternfilters gelesen.');
          END TRY
          BEGIN CATCH
            INSERT [#MaintenanceOperations_SourceStatus] VALUES
            (N'msdb.dbo.sysjobs + msdb.dbo.sysjobactivity',CASE WHEN ERROR_NUMBER() IN (229,371,916) THEN 'DENIED_PERMISSION' ELSE 'ERROR_HANDLED' END,1,
             N'Explizit angeforderte Jobaktivitaet war nicht lesbar; keine Jobdetails wurden ersatzweise gelesen.');
            SELECT @IsPartial=1,@ErrorNumber=ERROR_NUMBER(),@ErrorMessage=ERROR_MESSAGE();
          END CATCH;
        END
        ELSE
        BEGIN
            INSERT [#MaintenanceOperations_SourceStatus] VALUES
            (N'msdb.dbo.sysjobs + msdb.dbo.sysjobactivity','NOT_REQUESTED',0,
             N'Ohne expliziten Jobfilter werden Jobnamen und Jobaktivitaet nicht gelesen.');
        END;

        IF EXISTS(SELECT 1 FROM [#MaintenanceOperations_SourceStatus] WHERE [IsPartial]=1)
            SELECT @StatusCode='AVAILABLE_LIMITED',@IsPartial=1;
        ELSE IF EXISTS(SELECT 1 FROM [#MaintenanceOperations_Resumable] WHERE [FindingSeverity] IN ('HIGH','MEDIUM'))
             OR EXISTS(SELECT 1 FROM [#MaintenanceOperations_Requests] WHERE [FindingSeverity] IN ('HIGH','MEDIUM'))
             OR EXISTS(SELECT 1 FROM [#MaintenanceOperations_Pvs] WHERE [FindingSeverity] IN ('HIGH','MEDIUM'))
             OR EXISTS(SELECT 1 FROM [#MaintenanceOperations_Jobs] WHERE [FindingSeverity] IN ('HIGH','MEDIUM'))
            SET @StatusCode='AVAILABLE_WITH_FINDING';
    END;

    SELECT @StatusCodeOut=@StatusCode,@IsPartialOut=@IsPartial,
           @ErrorNumberOut=@ErrorNumber,@ErrorMessageOut=@ErrorMessage;

    IF @JsonErzeugen=1
    BEGIN
        DECLARE @MetaJson nvarchar(max)=(SELECT N'MaintenanceOperations' AS [resultName],1 AS [schemaVersion],
            @Now AS [generatedAtUtc],@StatusCode AS [statusCode],@IsPartial AS [isPartial],@Major AS [productMajorVersion]
            FOR JSON PATH,WITHOUT_ARRAY_WRAPPER);
        DECLARE @ResumableJson nvarchar(max)=(SELECT TOP (@Limit) * FROM [#MaintenanceOperations_Resumable]
            WHERE @NurProblematisch=0 OR [FindingSeverity] IN ('HIGH','MEDIUM')
            ORDER BY CASE [FindingSeverity] WHEN 'HIGH' THEN 1 WHEN 'MEDIUM' THEN 2 ELSE 3 END,[DatabaseId],[StartTime]
            FOR JSON PATH,INCLUDE_NULL_VALUES);
        DECLARE @RequestJson nvarchar(max)=(SELECT TOP (@Limit) * FROM [#MaintenanceOperations_Requests]
            WHERE @NurProblematisch=0 OR [FindingSeverity] IN ('HIGH','MEDIUM')
            ORDER BY CASE [FindingSeverity] WHEN 'HIGH' THEN 1 WHEN 'MEDIUM' THEN 2 ELSE 3 END,[ElapsedMs] DESC
            FOR JSON PATH,INCLUDE_NULL_VALUES);
        DECLARE @PvsJson nvarchar(max)=(SELECT TOP (@Limit) * FROM [#MaintenanceOperations_Pvs]
            WHERE @NurProblematisch=0 OR [FindingSeverity] IN ('HIGH','MEDIUM') ORDER BY [DatabaseId]
            FOR JSON PATH,INCLUDE_NULL_VALUES);
        DECLARE @JobJson nvarchar(max)=(SELECT TOP (@Limit) * FROM [#MaintenanceOperations_Jobs]
            WHERE @NurProblematisch=0 OR [FindingSeverity] IN ('HIGH','MEDIUM') ORDER BY [JobName]
            FOR JSON PATH,INCLUDE_NULL_VALUES);
        DECLARE @SourceJson nvarchar(max)=(SELECT * FROM [#MaintenanceOperations_SourceStatus] ORDER BY [SourceName] FOR JSON PATH,INCLUDE_NULL_VALUES);
        SET @Json=CONCAT(N'{"meta":',COALESCE(@MetaJson,N'{}'),N',"resumableOperations":',COALESCE(@ResumableJson,N'[]'),
            N',"requests":',COALESCE(@RequestJson,N'[]'),N',"pvs":',COALESCE(@PvsJson,N'[]'),
            N',"jobs":',COALESCE(@JobJson,N'[]'),N',"sources":',COALESCE(@SourceJson,N'[]'),N'}');
    END;

    IF @OutputMode='RAW'
    BEGIN
        SELECT N'USP_MaintenanceOperations' AS [ModuleName],@Now AS [CollectionTimeUtc],@StatusCode AS [StatusCode],
               @IsPartial AS [IsPartial],@Major AS [ProductMajorVersion],@ErrorNumber AS [ErrorNumber],@ErrorMessage AS [ErrorMessage];
        SELECT TOP (@Limit) * FROM [#MaintenanceOperations_Resumable] WHERE @NurProblematisch=0 OR [FindingSeverity] IN ('HIGH','MEDIUM');
        SELECT TOP (@Limit) * FROM [#MaintenanceOperations_Requests] WHERE @NurProblematisch=0 OR [FindingSeverity] IN ('HIGH','MEDIUM');
        SELECT TOP (@Limit) * FROM [#MaintenanceOperations_Pvs] WHERE @NurProblematisch=0 OR [FindingSeverity] IN ('HIGH','MEDIUM');
        SELECT TOP (@Limit) * FROM [#MaintenanceOperations_Jobs] WHERE @NurProblematisch=0 OR [FindingSeverity] IN ('HIGH','MEDIUM');
        SELECT * FROM [#MaintenanceOperations_SourceStatus] ORDER BY [SourceName];
        SELECT * FROM [#MaintenanceOperations_DatabaseCandidateWarnings] ORDER BY [RequestedName];
    END
    ELSE IF @OutputMode='CONSOLE'
    BEGIN
        SELECT N'Wartungsoperationen' AS [Ergebnis],@Now AS [Stand_UTC],@StatusCode AS [Status],
               @IsPartial AS [Teilweise],@ErrorMessage AS [Hinweis];
        SELECT TOP (@Limit) N'Resumierbare Indexoperation' AS [Ergebnis],[DatabaseName] AS [Datenbank],
               [SchemaName] AS [Schema],[ObjectName] AS [Objekt],[IndexName] AS [Index],[StateDesc] AS [Status],
               [PercentComplete] AS [Fortschritt_Prozent],[LastPauseTime] AS [Letzte_Pause],
               [FindingCode] AS [Befund],[FindingSeverity] AS [Prioritaet],[EvidenceLimit] AS [Evidenzgrenze]
        FROM [#MaintenanceOperations_Resumable] WHERE @NurProblematisch=0 OR [FindingSeverity] IN ('HIGH','MEDIUM');
        SELECT TOP (@Limit) N'Laufender Wartungsrequest' AS [Ergebnis],[SessionId] AS [Session_ID],
               [DatabaseName] AS [Datenbank],[Command] AS [Operation],[Status],[ElapsedMs] AS [Dauer_ms],
               [PercentComplete] AS [Fortschritt_Prozent],[BlockingSessionId] AS [Blockiert_durch],
               [WaitType] AS [Wait_Typ],[FindingCode] AS [Befund],[FindingSeverity] AS [Prioritaet]
        FROM [#MaintenanceOperations_Requests] WHERE @NurProblematisch=0 OR [FindingSeverity] IN ('HIGH','MEDIUM');
        SELECT TOP (@Limit) N'ADR und PVS' AS [Ergebnis],[DatabaseName] AS [Datenbank],[AdrEnabled] AS [ADR_Aktiv],
               [PvsSizeMb] AS [PVS_MB],[OnlineIndexPvsSizeMb] AS [Online_Index_PVS_MB],
               [CurrentAbortedTransactionCount] AS [Abgebrochene_Transaktionen],
               [FindingCode] AS [Befund],[FindingSeverity] AS [Prioritaet],[EvidenceLimit] AS [Evidenzgrenze]
        FROM [#MaintenanceOperations_Pvs] WHERE @NurProblematisch=0 OR [FindingSeverity] IN ('HIGH','MEDIUM');
        SELECT TOP (@Limit) N'Explizit gewaehlter Job' AS [Ergebnis],[JobName] AS [Job],
               [StartExecutionDate] AS [Start],[IsRunning] AS [Laeuft],[FindingCode] AS [Befund],
               [FindingSeverity] AS [Prioritaet],[EvidenceLimit] AS [Evidenzgrenze]
        FROM [#MaintenanceOperations_Jobs] WHERE @NurProblematisch=0 OR [FindingSeverity] IN ('HIGH','MEDIUM');
        SELECT N'Quellenstatus' AS [Ergebnis],[SourceName] AS [Quelle],[StatusCode] AS [Status],[Detail] AS [Hinweis]
        FROM [#MaintenanceOperations_SourceStatus] ORDER BY [SourceName];
    END;
    IF @ConsoleResultRequested = 1
    BEGIN
        EXEC [monitor].[InternalEmitConsoleResult]
              @SourceTable=N'#MaintenanceOperations_Resumable'
            , @ResultLabel=N'MaintenanceOperations'
            , @EmptyMessage=N'Keine fachlichen Ergebnisse';
    END;
    IF @TableResultRequested = 1
    BEGIN
        EXEC [monitor].[InternalWriteResultTable]
              @SourceTable = N'#MaintenanceOperations_Resumable'
            , @TargetTable=@TableTarget
            , @ThrowOnError = 1;
    END;
END;
GO
-- END SOURCE: Code/07_Infrastructure/130_USP_MaintenanceOperations.sql

-- BEGIN SOURCE: Code/07_Infrastructure/140_USP_ErrorLogAnalysis.sql
/*
===============================================================================
Objekt       : monitor.USP_ErrorLogAnalysis
Version      : 1.0.0
Stand        : 2026-07-21
Zweck        : Liest SQL-Server- und optional Agent-Errorlogs über dokumentierte
               sp_readerrorlog-Filter in Kategorien, Summary und Source-Status.
Default      : Aktuelles SQL-Server-Log, letzte 24 Stunden Serverlokalzeit,
               kuratierte High-Signal-Filter, kein Meldungsvolltext.
Grenzen      : sp_readerrorlog besitzt keinen dokumentierten Zeitparameter.
               Deshalb wird serverseitig nach Keywords und anschließend nach
               LogDate begrenzt. Sehr große Treffer werden AVAILABLE_LIMITED.
Nebenwirkung : Kein Logwechsel, keine Konfiguration, keine Persistenz.
Datenschutz  : Meldungstext und ProcessInfo nur opt-in; Laufzeitausgabe darf
               reale Diagnosewerte enthalten, Repositoryartefakte niemals.
===============================================================================
*/
CREATE OR ALTER PROCEDURE [monitor].[USP_ErrorLogAnalysis]
      @AgentEinbeziehen          bit             = 0
    , @MaxArchivNummer           tinyint         = 0
    , @SeitServerlokalzeit       datetime2(3)    = NULL
    , @Suchtext1                 nvarchar(4000)  = NULL
    , @Suchtext2                 nvarchar(4000)  = NULL
    , @MeldungstextEinbeziehen   bit             = 0
    , @MaxMeldungszeichen        int             = 4000
    , @MaxQuellzeilen            int             = 10000
    , @MaxZeilen                 int             = 1000
    , @ResultSetArt              varchar(16)     = 'CONSOLE'
    , @ResultTablesJson          nvarchar(max)   = NULL
    , @JsonErzeugen              bit             = 0
    , @Json                       nvarchar(max)   = NULL OUTPUT
    , @PrintMeldungen            bit             = 1
    , @Hilfe                     bit             = 0
    , @StatusCodeOut             varchar(40)     = NULL OUTPUT
    , @IsPartialOut              bit             = NULL OUTPUT
    , @ErrorNumberOut            int             = NULL OUTPUT
    , @ErrorMessageOut           nvarchar(2048)  = NULL OUTPUT
AS
BEGIN
    SET NOCOUNT ON;
    SET @Json=NULL;

    DECLARE @CapturedAtUtc datetime2(3)=SYSUTCDATETIME();
    DECLARE @EffectiveSince datetime2(3)=COALESCE(@SeitServerlokalzeit,DATEADD(HOUR,-24,CONVERT(datetime2(3),SYSDATETIME())));
    DECLARE @OutputMode varchar(16)=UPPER(LTRIM(RTRIM(COALESCE(@ResultSetArt,''))));
    DECLARE @ConsoleResultRequested bit=CASE WHEN UPPER(LTRIM(RTRIM(COALESCE(@ResultSetArt,''))))='CONSOLE' THEN 1 ELSE 0 END;
    DECLARE @StatusCode varchar(40)='AVAILABLE';
    DECLARE @IsPartial bit=0;
    DECLARE @ErrorNumber int=NULL;
    DECLARE @ErrorMessage nvarchar(2048)=NULL;
    DECLARE @Limit bigint=CASE WHEN @MaxZeilen IS NULL OR @MaxZeilen=0 THEN CONVERT(bigint,9223372036854775807) ELSE CONVERT(bigint,@MaxZeilen) END;
    DECLARE @SourceLimit bigint=CASE WHEN @MaxQuellzeilen IS NULL OR @MaxQuellzeilen=0 THEN CONVERT(bigint,9223372036854775807) ELSE CONVERT(bigint,@MaxQuellzeilen) END;
    DECLARE @SourceCandidateLimit bigint=@SourceLimit;

    IF @Hilfe=1
    BEGIN
        PRINT N'monitor.USP_ErrorLogAnalysis';
        PRINT N'Standardmäßig liest die Procedure das aktuelle SQL-Server-Errorlog für die letzten 24 Stunden in der vom Errorlog gelieferten Serverlokalzeit und erstellt eine kategorisierte Zusammenfassung.';
        PRINT N'@MaxArchivNummer=0 liest nur das aktuelle Log; höhere Werte lesen Archive 0..n. Kein Logwechsel wird ausgeführt.';
        PRINT N'@Suchtext1/@Suchtext2 ersetzen die kuratierten Defaultfilter durch einen benutzerdefinierten dokumentierten sp_readerrorlog-Filter.';
        PRINT N'@MeldungstextEinbeziehen=1 aktiviert Details. @MaxMeldungszeichen=0 ist unbegrenzt; Kürzung erzeugt genau eine Warning.';
        PRINT N'@MaxQuellzeilen begrenzt materialisierte Treffer; 0 ist explizit unbegrenzt. Sehr große Logs können trotz Keywordfilter Last erzeugen.';
        PRINT N'@ResultSetArt=CONSOLE|RAW|TABLE|NONE; TABLE-Namen: moduleStatus, summary, details, sourceStatus, warnings.';
        RETURN;
    END;

    CREATE TABLE [#ErrorLogAnalysis_ResultTableMap]
    (
          [ResultName] sysname COLLATE SQL_Latin1_General_CP1_CS_AS NOT NULL PRIMARY KEY
        , [TargetTable] sysname COLLATE SQL_Latin1_General_CP1_CS_AS NOT NULL UNIQUE
    );
    CREATE TABLE [#ErrorLogAnalysis_SearchRules]
    (
          [RuleOrdinal] int IDENTITY(1,1) NOT NULL PRIMARY KEY
        , [ProductCode] int NOT NULL
        , [RuleCategory] varchar(80) NOT NULL
        , [SearchText1] nvarchar(4000) NULL
        , [SearchText2] nvarchar(4000) NULL
    );
    CREATE TABLE [#ErrorLogAnalysis_ReadBuffer]
    (
          [LogDate] datetime NULL
        , [ProcessInfo] nvarchar(50) NULL
        , [MessageText] nvarchar(max) NULL
    );
    CREATE TABLE [#ErrorLogAnalysis_Events]
    (
          [EventOrdinal] bigint IDENTITY(1,1) NOT NULL PRIMARY KEY
        , [ProductCode] int NOT NULL
        , [ProductName] varchar(32) NOT NULL
        , [ArchiveNumber] int NOT NULL
        , [RuleCategory] varchar(80) NOT NULL
        , [LogDateServerLocal] datetime NOT NULL
        , [ProcessInfo] nvarchar(50) NULL
        , [MessageText] nvarchar(max) NOT NULL
        , [MessageHash] binary(32) NOT NULL
    );
    CREATE INDEX [IX_ErrorLog_Events_Time] ON [#ErrorLogAnalysis_Events]([LogDateServerLocal],[ProductCode],[ArchiveNumber]);
    CREATE TABLE [#ErrorLogAnalysis_SourceStatus]
    (
          [SourceOrdinal] int IDENTITY(1,1) NOT NULL PRIMARY KEY
        , [ProductName] varchar(32) NOT NULL
        , [ArchiveNumber] int NOT NULL
        , [RuleCategory] varchar(80) NOT NULL
        , [SourceObject] nvarchar(256) NOT NULL
        , [CapturedAtUtc] datetime2(3) NOT NULL
        , [StatusCode] varchar(40) NOT NULL
        , [IsPartial] bit NOT NULL
        , [ReadRowCount] bigint NOT NULL
        , [AcceptedRowCount] bigint NOT NULL
        , [ErrorNumber] int NULL
        , [ErrorMessage] nvarchar(2048) NULL
        , [EvidenceLimit] nvarchar(1000) NOT NULL
    );
    CREATE TABLE [#ErrorLogAnalysis_Classified]
    (
          [EventOrdinal] bigint NOT NULL PRIMARY KEY
        , [ProductName] varchar(32) NOT NULL
        , [ArchiveNumber] int NOT NULL
        , [Category] varchar(80) NOT NULL
        , [LogDateServerLocal] datetime NOT NULL
        , [ProcessInfo] nvarchar(50) NULL
        , [MessageText] nvarchar(max) NOT NULL
    );
    CREATE TABLE [#ErrorLogAnalysis_Summary]
    (
          [ProductName] varchar(32) NOT NULL
        , [Category] varchar(80) NOT NULL
        , [EventCount] bigint NOT NULL
        , [FirstOccurrenceServerLocal] datetime NOT NULL
        , [LastOccurrenceServerLocal] datetime NOT NULL
        , [ArchiveCount] int NOT NULL
        , [HighestArchiveNumber] int NOT NULL
        , [TimeSemantics] varchar(64) NOT NULL
        , [FindingCode] varchar(80) NOT NULL
        , [EvidenceLimit] nvarchar(1000) NOT NULL
    );
    CREATE TABLE [#ErrorLogAnalysis_Details]
    (
          [ProductName] varchar(32) NOT NULL
        , [ArchiveNumber] int NOT NULL
        , [Category] varchar(80) NOT NULL
        , [LogDateServerLocal] datetime NOT NULL
        , [TimeSemantics] varchar(64) NOT NULL
        , [ProcessInfo] nvarchar(50) NULL
        , [MessageCharacters] bigint NULL
        , [MessageBytes] bigint NULL
        , [MessageIsTruncated] bit NOT NULL
        , [MessageText] nvarchar(max) NULL
    );
    CREATE TABLE [#ErrorLogAnalysis_Warnings]
    (
          [WarningOrdinal] int IDENTITY(1,1) NOT NULL PRIMARY KEY
        , [SourceName] sysname NOT NULL
        , [StatusCode] varchar(40) NOT NULL
        , [ErrorNumber] int NULL
        , [Message] nvarchar(2048) NOT NULL
    );
    CREATE TABLE [#ErrorLogAnalysis_ModuleStatus]
    (
          [ModuleName] sysname NOT NULL
        , [CapturedAtUtc] datetime2(3) NOT NULL
        , [SinceServerLocalTime] datetime2(3) NOT NULL
        , [StatusCode] varchar(40) NOT NULL
        , [IsPartial] bit NOT NULL
        , [AgentRequested] bit NOT NULL
        , [HighestArchiveRequested] tinyint NOT NULL
        , [SourceRowLimit] int NULL
        , [AcceptedSourceRows] bigint NOT NULL
        , [SummaryRowCount] bigint NOT NULL
        , [DetailRowCount] bigint NOT NULL
        , [HasMoreSourceRows] bit NOT NULL
        , [HasMoreDetailRows] bit NOT NULL
        , [ErrorNumber] int NULL
        , [ErrorMessage] nvarchar(2048) NULL
    );

    IF @AgentEinbeziehen IS NULL OR @MeldungstextEinbeziehen IS NULL OR @JsonErzeugen IS NULL OR @PrintMeldungen IS NULL
       OR @MaxArchivNummer IS NULL OR @MaxArchivNummer>20
       OR @MaxMeldungszeichen IS NULL OR @MaxMeldungszeichen<0 OR @MaxQuellzeilen<0 OR @MaxZeilen<0
       OR @OutputMode NOT IN('CONSOLE','RAW','TABLE','NONE')
       OR (@Suchtext1 IS NULL AND @Suchtext2 IS NOT NULL)
       OR (@Suchtext1 IS NOT NULL AND NULLIF(LTRIM(RTRIM(@Suchtext1)),N'') IS NULL)
       OR (@Suchtext2 IS NOT NULL AND NULLIF(LTRIM(RTRIM(@Suchtext2)),N'') IS NULL)
       OR (@OutputMode<>'TABLE' AND NULLIF(LTRIM(RTRIM(COALESCE(@ResultTablesJson,N''))),N'') IS NOT NULL)
    BEGIN
        SELECT @StatusCode='INVALID_PARAMETER',@IsPartial=1,
               @ErrorMessage=N'Ungültiger Archiv-, Zeit-, Such-, Text-, Zeilen- oder Ausgabeparameter.';
    END;

    IF @StatusCode='AVAILABLE' AND @OutputMode='TABLE'
        EXEC [monitor].[InternalPrepareResultTables]
              @ResultTablesJson=@ResultTablesJson
            , @AllowedResultNames=N'moduleStatus|summary|details|sourceStatus|warnings'
            , @MappingTable=N'#ErrorLogAnalysis_ResultTableMap'
            , @StatusCode=@StatusCode OUTPUT
            , @ErrorMessage=@ErrorMessage OUTPUT
            , @ThrowOnError=1;

    IF @StatusCode='AVAILABLE'
    BEGIN
        IF @Suchtext1 IS NOT NULL
        BEGIN
            INSERT [#ErrorLogAnalysis_SearchRules]([ProductCode],[RuleCategory],[SearchText1],[SearchText2])
            VALUES(1,'CUSTOM_FILTER',@Suchtext1,@Suchtext2);
            IF @AgentEinbeziehen=1
                INSERT [#ErrorLogAnalysis_SearchRules]([ProductCode],[RuleCategory],[SearchText1],[SearchText2])
                VALUES(2,'CUSTOM_FILTER',@Suchtext1,@Suchtext2);
        END
        ELSE
        BEGIN
            INSERT [#ErrorLogAnalysis_SearchRules]([ProductCode],[RuleCategory],[SearchText1],[SearchText2])
            VALUES
              (1,'IO_ERROR',N'Error: 823',NULL),(1,'IO_ERROR',N'Error: 824',NULL),(1,'IO_ERROR',N'Error: 825',NULL)
            , (1,'LONG_IO',N'taking longer than 15 seconds',NULL)
            , (1,'BACKUP_RESTORE',N'Backup',N'failed'),(1,'BACKUP_RESTORE',N'Restore',N'failed')
            , (1,'CACHE_FLUSH',N'cachestore flush',NULL),(1,'CACHE_FLUSH',N'FlushCache',NULL)
            , (1,'AUTOGROWTH',N'Autogrow',NULL)
            , (1,'DUMP_ASSERTION',N'Stack Dump',NULL),(1,'DUMP_ASSERTION',N'Assertion',NULL)
            , (1,'LOGIN_CONNECTIVITY',N'Login failed',NULL),(1,'LOGIN_CONNECTIVITY',N'17830',NULL)
            , (1,'REPLICATION',N'Replication',N'failed'),(1,'LOG_SHIPPING',N'Log Shipping',N'failed');
            IF @AgentEinbeziehen=1
                INSERT [#ErrorLogAnalysis_SearchRules]([ProductCode],[RuleCategory],[SearchText1],[SearchText2])
                VALUES(2,'AGENT_ERROR',N'failed',NULL),(2,'AGENT_ERROR',N'error',NULL);
        END;
    END;

    SET LOCK_TIMEOUT 0;

    DECLARE @ProductCode int,@RuleCategory varchar(80),@Search1 nvarchar(4000),@Search2 nvarchar(4000);
    DECLARE @ArchiveNumber int,@CurrentAccepted bigint,@Remaining bigint,@ReadRows bigint,@AcceptedRows bigint;
    DECLARE @HasMoreSourceRows bit=0;

    IF @StatusCode='AVAILABLE'
    BEGIN
        DECLARE [RuleCursor] CURSOR LOCAL FAST_FORWARD FOR
            SELECT [ProductCode],[RuleCategory],[SearchText1],[SearchText2]
            FROM [#ErrorLogAnalysis_SearchRules] ORDER BY [ProductCode],[RuleOrdinal];
        OPEN [RuleCursor]; FETCH NEXT FROM [RuleCursor] INTO @ProductCode,@RuleCategory,@Search1,@Search2;
        WHILE @@FETCH_STATUS=0
        BEGIN
            SET @ArchiveNumber=0;
            WHILE @ArchiveNumber<=@MaxArchivNummer
            BEGIN
                SELECT @CurrentAccepted=COUNT_BIG(*) FROM [#ErrorLogAnalysis_Events];
                IF @CurrentAccepted>=@SourceCandidateLimit
                BEGIN
                    SET @HasMoreSourceRows=1;
                    INSERT [#ErrorLogAnalysis_SourceStatus]
                    VALUES(CASE @ProductCode WHEN 1 THEN 'SQL_SERVER' ELSE 'SQL_AGENT' END,@ArchiveNumber,@RuleCategory,N'master.sys.sp_readerrorlog',@CapturedAtUtc,
                           'NOT_EXECUTED_ROW_LIMIT',1,0,0,NULL,N'@MaxQuellzeilen wurde vor diesem Filter erreicht.',
                           N'Weitere Filter/Archive wurden nicht gelesen; der Gesamtbefund ist partiell.');
                END
                ELSE
                BEGIN
                    TRUNCATE TABLE [#ErrorLogAnalysis_ReadBuffer];
                    BEGIN TRY
                        INSERT [#ErrorLogAnalysis_ReadBuffer]([LogDate],[ProcessInfo],[MessageText])
                        EXEC [master].[sys].[sp_readerrorlog] @ArchiveNumber,@ProductCode,@Search1,@Search2;
                        SELECT @ReadRows=COUNT_BIG(*) FROM [#ErrorLogAnalysis_ReadBuffer] WHERE [LogDate]>=@EffectiveSince;
                        SET @Remaining=CASE WHEN @SourceCandidateLimit=9223372036854775807 THEN @SourceCandidateLimit ELSE @SourceCandidateLimit-@CurrentAccepted END;

                        INSERT [#ErrorLogAnalysis_Events]([ProductCode],[ProductName],[ArchiveNumber],[RuleCategory],[LogDateServerLocal],[ProcessInfo],[MessageText],[MessageHash])
                        SELECT TOP(@Remaining) @ProductCode,CASE @ProductCode WHEN 1 THEN 'SQL_SERVER' ELSE 'SQL_AGENT' END,
                               @ArchiveNumber,@RuleCategory,[b].[LogDate],[b].[ProcessInfo],[b].[MessageText],HASHBYTES('SHA2_256',[b].[MessageText])
                        FROM [#ErrorLogAnalysis_ReadBuffer] AS [b]
                        WHERE [b].[LogDate]>=@EffectiveSince AND [b].[MessageText] IS NOT NULL
                          AND NOT EXISTS
                          (
                              SELECT 1 FROM [#ErrorLogAnalysis_Events] AS [e]
                              WHERE [e].[ProductCode]=@ProductCode AND [e].[ArchiveNumber]=@ArchiveNumber
                                AND [e].[LogDateServerLocal]=[b].[LogDate]
                                AND ISNULL([e].[ProcessInfo],N'')=ISNULL([b].[ProcessInfo],N'')
                                AND [e].[MessageHash]=HASHBYTES('SHA2_256',[b].[MessageText])
                          )
                        ORDER BY [b].[LogDate] DESC;
                        SET @AcceptedRows=@@ROWCOUNT;
                        IF @ReadRows>@Remaining SET @HasMoreSourceRows=1;
                        INSERT [#ErrorLogAnalysis_SourceStatus]
                        VALUES(CASE @ProductCode WHEN 1 THEN 'SQL_SERVER' ELSE 'SQL_AGENT' END,@ArchiveNumber,@RuleCategory,N'master.sys.sp_readerrorlog',@CapturedAtUtc,
                               CASE WHEN @ReadRows>@Remaining THEN 'AVAILABLE_LIMITED' ELSE 'AVAILABLE' END,
                               CONVERT(bit,CASE WHEN @ReadRows>@Remaining THEN 1 ELSE 0 END),@ReadRows,@AcceptedRows,NULL,NULL,
                               N'Dokumentierter Keywordfilter im gewählten Archiv; LogDate wird danach als Serverlokalzeit begrenzt. Doppelte Treffer mehrerer Regeln werden entfernt.');
                    END TRY
                    BEGIN CATCH
                        INSERT [#ErrorLogAnalysis_SourceStatus]
                        VALUES(CASE @ProductCode WHEN 1 THEN 'SQL_SERVER' ELSE 'SQL_AGENT' END,@ArchiveNumber,@RuleCategory,N'master.sys.sp_readerrorlog',@CapturedAtUtc,
                               CASE WHEN ERROR_NUMBER() IN(229,262,297,300,371) THEN 'DENIED_PERMISSION' WHEN ERROR_NUMBER()=1222 THEN 'TIMEOUT' ELSE 'ERROR_HANDLED' END,
                               1,0,0,ERROR_NUMBER(),ERROR_MESSAGE(),N'Andere Filter und Archive werden weiter verarbeitet.');
                    END CATCH;
                END;
                SET @ArchiveNumber+=1;
            END;
            FETCH NEXT FROM [RuleCursor] INTO @ProductCode,@RuleCategory,@Search1,@Search2;
        END;
        CLOSE [RuleCursor]; DEALLOCATE [RuleCursor];
    END;

    INSERT [#ErrorLogAnalysis_Classified]
    SELECT [EventOrdinal],[ProductName],[ArchiveNumber],[classification].[Category],
           [LogDateServerLocal],[ProcessInfo],[MessageText]
    FROM [#ErrorLogAnalysis_Events]
    CROSS APPLY [monitor].[TVF_ClassifyErrorLogEvent]([ProductName],[RuleCategory],[MessageText]) AS [classification];

    INSERT [#ErrorLogAnalysis_Summary]
    SELECT [ProductName],[Category],COUNT_BIG(*),MIN([LogDateServerLocal]),MAX([LogDateServerLocal]),
           COUNT(DISTINCT [ArchiveNumber]),MAX([ArchiveNumber]),'SERVER_LOCAL_TIME_FROM_ERRORLOG','EVENT_CATEGORY_REVIEW',
           N'Keywordgefilterte Errorlog-Evidenz. Häufigkeit und Zeitnähe erhöhen Relevanz, beweisen aber ohne korrelierte Engine-, OS-, Storage- oder Workloaddaten keine Ursache.'
    FROM [#ErrorLogAnalysis_Classified]
    GROUP BY [ProductName],[Category];

    IF @MeldungstextEinbeziehen=1
        INSERT [#ErrorLogAnalysis_Details]
        SELECT [c].[ProductName],[c].[ArchiveNumber],[c].[Category],[c].[LogDateServerLocal],
               'SERVER_LOCAL_TIME_FROM_ERRORLOG',[c].[ProcessInfo],
               [p].[OriginalCharacters],[p].[OriginalBytes],[p].[IsTruncated],[p].[ProjectedValue]
        FROM [#ErrorLogAnalysis_Classified] AS [c]
        CROSS APPLY [monitor].[TVF_ProjectUnicodeText]([c].[MessageText],@MaxMeldungszeichen) AS [p];

    INSERT [#ErrorLogAnalysis_Warnings]([SourceName],[StatusCode],[ErrorNumber],[Message])
    SELECT N'sp_readerrorlog',[StatusCode],[ErrorNumber],COALESCE([ErrorMessage],N'Quelle oder Teilquelle nicht vollständig gelesen.')
    FROM [#ErrorLogAnalysis_SourceStatus] WHERE [IsPartial]=1;

    IF @HasMoreSourceRows=1 AND NOT EXISTS(SELECT 1 FROM [#ErrorLogAnalysis_Warnings] WHERE [StatusCode]='SOURCE_ROW_LIMIT')
        INSERT [#ErrorLogAnalysis_Warnings]([SourceName],[StatusCode],[ErrorNumber],[Message])
        VALUES(N'sp_readerrorlog','SOURCE_ROW_LIMIT',NULL,N'@MaxQuellzeilen begrenzt die materialisierte Errorlog-Evidenz; Summary und Details sind partiell.');

    IF @StatusCode='AVAILABLE' AND NOT EXISTS(SELECT 1 FROM [#ErrorLogAnalysis_SourceStatus] WHERE [StatusCode]='AVAILABLE')
       AND EXISTS(SELECT 1 FROM [#ErrorLogAnalysis_SourceStatus] WHERE [IsPartial]=1)
    BEGIN
        SELECT TOP(1) @StatusCode=[StatusCode],@ErrorNumber=[ErrorNumber],@ErrorMessage=[ErrorMessage],@IsPartial=1
        FROM [#ErrorLogAnalysis_SourceStatus] WHERE [IsPartial]=1 ORDER BY [SourceOrdinal];
    END;
    ELSE IF @StatusCode='AVAILABLE' AND EXISTS(SELECT 1 FROM [#ErrorLogAnalysis_SourceStatus] WHERE [IsPartial]=1)
        SELECT @StatusCode='AVAILABLE_LIMITED',@IsPartial=1;

    IF @StatusCode NOT IN('AVAILABLE','AVAILABLE_LIMITED') SET @IsPartial=1;
    IF @ErrorMessage IS NULL
        SELECT TOP(1) @ErrorNumber=[ErrorNumber],@ErrorMessage=[Message]
        FROM [#ErrorLogAnalysis_Warnings] ORDER BY [WarningOrdinal];

    DECLARE @AcceptedSourceRows bigint=(SELECT COUNT_BIG(*) FROM [#ErrorLogAnalysis_Classified]);
    DECLARE @SummaryRows bigint=(SELECT COUNT_BIG(*) FROM [#ErrorLogAnalysis_Summary]);
    DECLARE @DetailRows bigint=(SELECT COUNT_BIG(*) FROM [#ErrorLogAnalysis_Details]);
    INSERT [#ErrorLogAnalysis_ModuleStatus]
    VALUES(N'USP_ErrorLogAnalysis',@CapturedAtUtc,@EffectiveSince,@StatusCode,@IsPartial,@AgentEinbeziehen,@MaxArchivNummer,
           @MaxQuellzeilen,@AcceptedSourceRows,@SummaryRows,
           CASE WHEN @DetailRows>@Limit THEN @Limit ELSE @DetailRows END,@HasMoreSourceRows,
           CONVERT(bit,CASE WHEN @Limit<9223372036854775807 AND @DetailRows>@Limit THEN 1 ELSE 0 END),
           @ErrorNumber,@ErrorMessage);

    IF @JsonErzeugen=1
    BEGIN
        DECLARE @MetaJson nvarchar(max)=(SELECT N'ErrorLogAnalysis' [resultName],1 [schemaVersion],@CapturedAtUtc [generatedAtUtc],@EffectiveSince [sinceServerLocalTime],N'SERVER_LOCAL_TIME_FROM_ERRORLOG' [timeSemantics],@StatusCode [statusCode],@IsPartial [isPartial],@MeldungstextEinbeziehen [messageTextIncluded],@ErrorNumber [errorNumber],@ErrorMessage [errorMessage] FOR JSON PATH,WITHOUT_ARRAY_WRAPPER,INCLUDE_NULL_VALUES);
        DECLARE @SummaryJson nvarchar(max)=(SELECT * FROM [#ErrorLogAnalysis_Summary] ORDER BY [LastOccurrenceServerLocal] DESC,[ProductName],[Category] FOR JSON PATH,INCLUDE_NULL_VALUES);
        DECLARE @DetailsJson nvarchar(max)=(SELECT TOP(@Limit) * FROM [#ErrorLogAnalysis_Details] ORDER BY [LogDateServerLocal] DESC,[ProductName],[ArchiveNumber],[Category] FOR JSON PATH,INCLUDE_NULL_VALUES);
        DECLARE @SourceJson nvarchar(max)=(SELECT * FROM [#ErrorLogAnalysis_SourceStatus] ORDER BY [SourceOrdinal] FOR JSON PATH,INCLUDE_NULL_VALUES);
        DECLARE @WarningsJson nvarchar(max)=(SELECT * FROM [#ErrorLogAnalysis_Warnings] ORDER BY [WarningOrdinal] FOR JSON PATH,INCLUDE_NULL_VALUES);
        SET @Json=CONCAT(N'{"meta":',COALESCE(@MetaJson,N'{}'),N',"summary":',COALESCE(@SummaryJson,N'[]'),N',"details":',COALESCE(@DetailsJson,N'[]'),N',"sourceStatus":',COALESCE(@SourceJson,N'[]'),N',"warnings":',COALESCE(@WarningsJson,N'[]'),N'}');
    END;

    IF @ConsoleResultRequested=1
        EXEC [monitor].[InternalEmitConsoleResult] @SourceTable=N'#ErrorLogAnalysis_Summary',@ResultLabel=N'Errorlog-Kategorien',@EmptyMessage=N'Keine Treffer in Zeit-, Archiv- und Keyword-Scope';
    ELSE IF @OutputMode='RAW'
    BEGIN
        SELECT * FROM [#ErrorLogAnalysis_ModuleStatus];
        SELECT * FROM [#ErrorLogAnalysis_Summary] ORDER BY [LastOccurrenceServerLocal] DESC,[ProductName],[Category];
        SELECT TOP(@Limit) * FROM [#ErrorLogAnalysis_Details] ORDER BY [LogDateServerLocal] DESC,[ProductName],[ArchiveNumber],[Category];
        SELECT * FROM [#ErrorLogAnalysis_SourceStatus] ORDER BY [SourceOrdinal];
        SELECT * FROM [#ErrorLogAnalysis_Warnings] ORDER BY [WarningOrdinal];
    END
    ELSE IF @OutputMode='TABLE'
    BEGIN
        DECLARE @ResultName sysname,@TargetTable sysname,@SourceTable sysname;
        DECLARE [ResultCursor] CURSOR LOCAL FAST_FORWARD FOR SELECT [ResultName],[TargetTable] FROM [#ErrorLogAnalysis_ResultTableMap] ORDER BY [ResultName];
        OPEN [ResultCursor]; FETCH NEXT FROM [ResultCursor] INTO @ResultName,@TargetTable;
        WHILE @@FETCH_STATUS=0
        BEGIN
            SET @SourceTable=CASE @ResultName WHEN N'moduleStatus' THEN N'#ErrorLogAnalysis_ModuleStatus' WHEN N'summary' THEN N'#ErrorLogAnalysis_Summary' WHEN N'details' THEN N'#ErrorLogAnalysis_Details' WHEN N'sourceStatus' THEN N'#ErrorLogAnalysis_SourceStatus' WHEN N'warnings' THEN N'#ErrorLogAnalysis_Warnings' END;
            EXEC [monitor].[InternalWriteResultTable] @SourceTable=@SourceTable,@TargetTable=@TargetTable,@ThrowOnError=1;
            FETCH NEXT FROM [ResultCursor] INTO @ResultName,@TargetTable;
        END;
        CLOSE [ResultCursor]; DEALLOCATE [ResultCursor];
    END;

    IF @MeldungstextEinbeziehen=1
    BEGIN
        DECLARE @TruncatedCount bigint=(SELECT COUNT_BIG(*) FROM [#ErrorLogAnalysis_Details] WHERE [MessageIsTruncated]=1);
        DECLARE @LargestRequired bigint=(SELECT MAX([MessageCharacters]) FROM [#ErrorLogAnalysis_Details] WHERE [MessageIsTruncated]=1);
        EXEC [monitor].[InternalEmitTruncationWarning] @TruncatedValueCount=@TruncatedCount,@ParameterName=N'@MaxMeldungszeichen',@ParameterValue=@MaxMeldungszeichen,@LargestRequiredCharacters=@LargestRequired,@PrintMeldungen=@PrintMeldungen;
    END;

    IF @PrintMeldungen=1 AND @StatusCode<>'AVAILABLE'
    BEGIN
        DECLARE @PrintMessage nvarchar(2048)=LEFT(CONCAT(N'USP_ErrorLogAnalysis: ',@StatusCode,N'. ',COALESCE(@ErrorMessage,N'Siehe warnings-Resultset.')),2048);
        RAISERROR(N'%s',10,1,@PrintMessage) WITH NOWAIT;
    END;
    SELECT @StatusCodeOut=@StatusCode,@IsPartialOut=@IsPartial,@ErrorNumberOut=@ErrorNumber,@ErrorMessageOut=@ErrorMessage;
END;
GO
-- END SOURCE: Code/07_Infrastructure/140_USP_ErrorLogAnalysis.sql

-- BEGIN SOURCE: Code/07_Infrastructure/090_USP_InfrastructureAnalysis.sql
/*
===============================================================================
Objekt       : monitor.USP_InfrastructureAnalysis
Version      : 2.1.0
Stand        : 2026-07-17
Typ          : Stored Procedure
Zweck        : Orchestriert die Phase-6-Module fehlertolerant.
SQL-Version  : SQL Server 2019 oder neuer.
Datenbankscope: @DatabaseNames ist eine bracket-aware Pipe-Liste; NULL bedeutet
               alle zulässigen Datenbanken. @DatabaseNamePattern ist alternativ.
Resultsets   : Je aktiviertem Modul RAW oder CONSOLE sowie Modulstatus;
               NONE unterdrückt alle fachlichen Resultsets.
JSON         : meta und benannte Modulobjekte agent, agentJobs,
               resourceGovernor, availabilityGroups, backupRecovery,
               logShipping, replication, dataCapture sowie warnings.
Berechtigung : Das Framework vergibt keine Rechte und ändert keine Konfiguration.
Änderungen   : 2.1.0 - Backupketten, tiefe AG- und Agent-Monitoring-Evidenz
                         als opt-in Teilmodule ergänzt.
               2.0.0 - @AlleDatenbanken entfernt; einheitlicher Datenbankscope,
                         Ausgabeadapter und JSON-Orchestrierung.
===============================================================================
*/
CREATE OR ALTER PROCEDURE [monitor].[USP_InfrastructureAnalysis]
      @MitAgent                       bit            = 1
    , @MitAgentJobs                   bit            = 1
    , @MitResourceGovernor            bit            = 1
    , @MitAvailabilityGroups          bit            = 1
    , @MitBackupRecovery              bit            = 1
    , @MitLogShipping                 bit            = 1
    , @MitReplication                 bit            = 1
    , @MitDataCapture                 bit            = 1
    , @MitReplicationDetails          bit            = 0
    , @MitBackupChain                 bit            = 0
    , @MitAvailabilityDeep            bit            = 0
    , @MitAgentMonitoring             bit            = 0
    , @DatabaseNames                  nvarchar(max)  = NULL
    , @SystemdatenbankenEinbeziehen   bit            = 0
    , @DatabaseNamePattern            nvarchar(4000) = NULL
    , @HighImpactConfirmed              bit            = 0
    , @MaxZeilen                      int            = 2000
    , @ResultSetArt                   varchar(16)    = 'CONSOLE'
    , @ResultTablesJson               nvarchar(max) = NULL
    , @JsonErzeugen                   bit            = 0
    , @Json                           nvarchar(max)  = NULL OUTPUT
    , @PrintMeldungen                 bit            = 1
    , @Hilfe                          bit            = 0
AS
BEGIN
    SET NOCOUNT ON;
    SET LOCK_TIMEOUT 0;

    SET @Json = NULL;

    DECLARE @ResultSetArtNormalisiert varchar(16) = UPPER(LTRIM(RTRIM(COALESCE(@ResultSetArt, ''))));
    DECLARE @TableResultRequested bit = CASE WHEN @ResultSetArtNormalisiert = 'TABLE' THEN 1 ELSE 0 END;
    DECLARE @ConsoleResultRequested bit = CASE WHEN @ResultSetArtNormalisiert = 'CONSOLE' THEN 1 ELSE 0 END;
    DECLARE @TableTarget sysname=NULL;
    IF @TableResultRequested=0 AND NULLIF(LTRIM(RTRIM(COALESCE(@ResultTablesJson,N''))),N'') IS NOT NULL THROW 51011,N'@ResultTablesJson ist ausschließlich mit @ResultSetArt=TABLE zulässig.',1;
    IF @TableResultRequested=1 EXEC [monitor].[InternalPrepareSingleResultTable] @ResultTablesJson=@ResultTablesJson,@ResultName=N'moduleStatus',@TargetTable=@TableTarget OUTPUT,@ThrowOnError=1;
    IF @TableResultRequested = 1 OR @ConsoleResultRequested = 1 SET @ResultSetArtNormalisiert = 'NONE';
    DECLARE @CollectionTimeUtc datetime2(3) = SYSUTCDATETIME();

    IF @Hilfe = 1
    BEGIN
        PRINT N'monitor.USP_InfrastructureAnalysis';
        PRINT N'Die Modulschalter steuern die bestehenden Module sowie die optionalen Vertiefungen @MitBackupChain, @MitAvailabilityDeep und @MitAgentMonitoring.';
        PRINT N'@DatabaseNames: exakter Name oder bracket-aware Pipe-Liste; NULL = alle zulässigen Datenbanken.';
        PRINT N'@DatabaseNamePattern: alternatives LIKE-/Regex-Pattern; exakte Liste und Pattern sind gegenseitig exklusiv.';
        PRINT N'@MaxZeilen: positive Werte begrenzen; NULL/0 = unbegrenzt; negative Werte sind ungültig.';
        PRINT N'@ResultSetArt=CONSOLE (Default)|RAW|TABLE|NONE case-insensitiv; @JsonErzeugen=1 setzt @Json OUTPUT.';
        RETURN;
    END;

    CREATE TABLE [#InfrastructureAnalysis_ModuleStatus]
    (
          [ModuleName] sysname NOT NULL
        , [StatusCode] varchar(40) NOT NULL
        , [ErrorNumber] int NULL
        , [ErrorMessage] nvarchar(2048) NULL
    );

    DECLARE @AgentJson nvarchar(max) = NULL;
    DECLARE @AgentJobsJson nvarchar(max) = NULL;
    DECLARE @ResourceGovernorJson nvarchar(max) = NULL;
    DECLARE @AvailabilityGroupsJson nvarchar(max) = NULL;
    DECLARE @BackupRecoveryJson nvarchar(max) = NULL;
    DECLARE @LogShippingJson nvarchar(max) = NULL;
    DECLARE @ReplicationJson nvarchar(max) = NULL;
    DECLARE @DataCaptureJson nvarchar(max) = NULL;
    DECLARE @BackupChainJson nvarchar(max) = NULL;
    DECLARE @AvailabilityDeepJson nvarchar(max) = NULL;
    DECLARE @AgentMonitoringJson nvarchar(max) = NULL;
    DECLARE @ChildStatus varchar(40) = NULL;
    DECLARE @ChildPartial bit = NULL;
    DECLARE @ChildErrorNumber int = NULL;
    DECLARE @ChildErrorMessage nvarchar(2048) = NULL;

    IF @MaxZeilen < 0
       OR @ResultSetArtNormalisiert NOT IN ('RAW', 'CONSOLE', 'NONE')
       OR (@DatabaseNames IS NOT NULL AND @DatabaseNamePattern IS NOT NULL)
    BEGIN
        INSERT [#InfrastructureAnalysis_ModuleStatus]
        VALUES
        (
              N'USP_InfrastructureAnalysis'
            , 'INVALID_PARAMETER'
            , NULL
            , N'Ungültige Scope-, Grenzwert- oder Ausgabeparameter.'
        );
    END;
    ELSE
    BEGIN
        IF @MitAgent = 1
        BEGIN TRY
            EXEC [monitor].[USP_AgentStatus]
                  @ResultSetArt = @ResultSetArtNormalisiert
                , @JsonErzeugen = @JsonErzeugen
                , @Json = @AgentJson OUTPUT
                , @PrintMeldungen = @PrintMeldungen;
            INSERT [#InfrastructureAnalysis_ModuleStatus] VALUES (N'USP_AgentStatus', 'EXECUTED', NULL, NULL);
        END TRY
        BEGIN CATCH
            INSERT [#InfrastructureAnalysis_ModuleStatus] VALUES (N'USP_AgentStatus', 'ERROR_HANDLED', ERROR_NUMBER(), ERROR_MESSAGE());
        END CATCH;

        IF @MitAgentJobs = 1
        BEGIN TRY
            EXEC [monitor].[USP_AgentJobs]
                  @MaxZeilen = @MaxZeilen
                , @ResultSetArt = @ResultSetArtNormalisiert
                , @JsonErzeugen = @JsonErzeugen
                , @Json = @AgentJobsJson OUTPUT
                , @PrintMeldungen = @PrintMeldungen;
            INSERT [#InfrastructureAnalysis_ModuleStatus] VALUES (N'USP_AgentJobs', 'EXECUTED', NULL, NULL);
        END TRY
        BEGIN CATCH
            INSERT [#InfrastructureAnalysis_ModuleStatus] VALUES (N'USP_AgentJobs', 'ERROR_HANDLED', ERROR_NUMBER(), ERROR_MESSAGE());
        END CATCH;

        IF @MitResourceGovernor = 1
        BEGIN TRY
            EXEC [monitor].[USP_ResourceGovernorAnalysis]
                  @MaxZeilen = @MaxZeilen
                , @ResultSetArt = @ResultSetArtNormalisiert
                , @JsonErzeugen = @JsonErzeugen
                , @Json = @ResourceGovernorJson OUTPUT
                , @PrintMeldungen = @PrintMeldungen;
            INSERT [#InfrastructureAnalysis_ModuleStatus] VALUES (N'USP_ResourceGovernorAnalysis', 'EXECUTED', NULL, NULL);
        END TRY
        BEGIN CATCH
            INSERT [#InfrastructureAnalysis_ModuleStatus] VALUES (N'USP_ResourceGovernorAnalysis', 'ERROR_HANDLED', ERROR_NUMBER(), ERROR_MESSAGE());
        END CATCH;

        IF @MitAvailabilityGroups = 1
        BEGIN TRY
            EXEC [monitor].[USP_AvailabilityGroups]
                  @MaxZeilen = @MaxZeilen
                , @ResultSetArt = @ResultSetArtNormalisiert
                , @JsonErzeugen = @JsonErzeugen
                , @Json = @AvailabilityGroupsJson OUTPUT
                , @PrintMeldungen = @PrintMeldungen;
            INSERT [#InfrastructureAnalysis_ModuleStatus] VALUES (N'USP_AvailabilityGroups', 'EXECUTED', NULL, NULL);
        END TRY
        BEGIN CATCH
            INSERT [#InfrastructureAnalysis_ModuleStatus] VALUES (N'USP_AvailabilityGroups', 'ERROR_HANDLED', ERROR_NUMBER(), ERROR_MESSAGE());
        END CATCH;

        IF @MitBackupRecovery = 1
        BEGIN TRY
            EXEC [monitor].[USP_BackupRecovery]
                  @DatabaseNames = @DatabaseNames
                , @SystemdatenbankenEinbeziehen = @SystemdatenbankenEinbeziehen
                , @DatabaseNamePattern = @DatabaseNamePattern,@HighImpactConfirmed=@HighImpactConfirmed

                , @MaxZeilen = @MaxZeilen
                , @ResultSetArt = @ResultSetArtNormalisiert
                , @JsonErzeugen = @JsonErzeugen
                , @Json = @BackupRecoveryJson OUTPUT
                , @PrintMeldungen = @PrintMeldungen;
            INSERT [#InfrastructureAnalysis_ModuleStatus] VALUES (N'USP_BackupRecovery', 'EXECUTED', NULL, NULL);
        END TRY
        BEGIN CATCH
            INSERT [#InfrastructureAnalysis_ModuleStatus] VALUES (N'USP_BackupRecovery', 'ERROR_HANDLED', ERROR_NUMBER(), ERROR_MESSAGE());
        END CATCH;

        IF @MitLogShipping = 1
        BEGIN TRY
            EXEC [monitor].[USP_LogShippingStatus]
                  @MaxZeilen = @MaxZeilen
                , @ResultSetArt = @ResultSetArtNormalisiert
                , @JsonErzeugen = @JsonErzeugen
                , @Json = @LogShippingJson OUTPUT
                , @PrintMeldungen = @PrintMeldungen;
            INSERT [#InfrastructureAnalysis_ModuleStatus] VALUES (N'USP_LogShippingStatus', 'EXECUTED', NULL, NULL);
        END TRY
        BEGIN CATCH
            INSERT [#InfrastructureAnalysis_ModuleStatus] VALUES (N'USP_LogShippingStatus', 'ERROR_HANDLED', ERROR_NUMBER(), ERROR_MESSAGE());
        END CATCH;

        IF @MitReplication = 1
        BEGIN TRY
            EXEC [monitor].[USP_ReplicationStatus]
                  @MitDistributionDetails = @MitReplicationDetails
                , @MaxZeilen = @MaxZeilen
                , @HighImpactConfirmed = @HighImpactConfirmed
                , @ResultSetArt = @ResultSetArtNormalisiert
                , @JsonErzeugen = @JsonErzeugen
                , @Json = @ReplicationJson OUTPUT
                , @PrintMeldungen = @PrintMeldungen;
            INSERT [#InfrastructureAnalysis_ModuleStatus] VALUES (N'USP_ReplicationStatus', 'EXECUTED', NULL, NULL);
        END TRY
        BEGIN CATCH
            INSERT [#InfrastructureAnalysis_ModuleStatus] VALUES (N'USP_ReplicationStatus', 'ERROR_HANDLED', ERROR_NUMBER(), ERROR_MESSAGE());
        END CATCH;

        IF @MitDataCapture = 1
        BEGIN TRY
            EXEC [monitor].[USP_DataCaptureStatus]
                  @DatabaseNames = @DatabaseNames
                , @SystemdatenbankenEinbeziehen = @SystemdatenbankenEinbeziehen
                , @DatabaseNamePattern = @DatabaseNamePattern,@HighImpactConfirmed=@HighImpactConfirmed

                , @MaxZeilen = @MaxZeilen
                , @ResultSetArt = @ResultSetArtNormalisiert
                , @JsonErzeugen = @JsonErzeugen
                , @Json = @DataCaptureJson OUTPUT
                , @PrintMeldungen = @PrintMeldungen;
            INSERT [#InfrastructureAnalysis_ModuleStatus] VALUES (N'USP_DataCaptureStatus', 'EXECUTED', NULL, NULL);
        END TRY
        BEGIN CATCH
            INSERT [#InfrastructureAnalysis_ModuleStatus] VALUES (N'USP_DataCaptureStatus', 'ERROR_HANDLED', ERROR_NUMBER(), ERROR_MESSAGE());
        END CATCH;

        IF @MitBackupChain = 1
        BEGIN TRY
            SELECT @ChildStatus = NULL, @ChildPartial = NULL, @ChildErrorNumber = NULL, @ChildErrorMessage = NULL;
            EXEC [monitor].[USP_BackupChainAnalysis]
                  @DatabaseNames = @DatabaseNames
                , @SystemdatenbankenEinbeziehen = @SystemdatenbankenEinbeziehen
                , @DatabaseNamePattern = @DatabaseNamePattern,@HighImpactConfirmed=@HighImpactConfirmed

                , @MaxZeilen = @MaxZeilen
                , @ResultSetArt = @ResultSetArtNormalisiert
                , @JsonErzeugen = @JsonErzeugen
                , @Json = @BackupChainJson OUTPUT
                , @PrintMeldungen = @PrintMeldungen
                , @StatusCodeOut = @ChildStatus OUTPUT, @IsPartialOut = @ChildPartial OUTPUT
                , @ErrorNumberOut = @ChildErrorNumber OUTPUT, @ErrorMessageOut = @ChildErrorMessage OUTPUT;
            INSERT [#InfrastructureAnalysis_ModuleStatus] VALUES
            (N'USP_BackupChainAnalysis', COALESCE(@ChildStatus, 'ERROR_HANDLED'), @ChildErrorNumber, @ChildErrorMessage);
        END TRY
        BEGIN CATCH
            INSERT [#InfrastructureAnalysis_ModuleStatus] VALUES (N'USP_BackupChainAnalysis', 'ERROR_HANDLED', ERROR_NUMBER(), ERROR_MESSAGE());
        END CATCH;

        IF @MitAvailabilityDeep = 1
        BEGIN TRY
            SELECT @ChildStatus = NULL, @ChildPartial = NULL, @ChildErrorNumber = NULL, @ChildErrorMessage = NULL;
            EXEC [monitor].[USP_AvailabilityDeepAnalysis]
                  @MaxZeilen = @MaxZeilen
                , @ResultSetArt = @ResultSetArtNormalisiert
                , @JsonErzeugen = @JsonErzeugen
                , @Json = @AvailabilityDeepJson OUTPUT
                , @PrintMeldungen = @PrintMeldungen
                , @StatusCodeOut = @ChildStatus OUTPUT, @IsPartialOut = @ChildPartial OUTPUT
                , @ErrorNumberOut = @ChildErrorNumber OUTPUT, @ErrorMessageOut = @ChildErrorMessage OUTPUT;
            INSERT [#InfrastructureAnalysis_ModuleStatus] VALUES
            (N'USP_AvailabilityDeepAnalysis', COALESCE(@ChildStatus, 'ERROR_HANDLED'), @ChildErrorNumber, @ChildErrorMessage);
        END TRY
        BEGIN CATCH
            INSERT [#InfrastructureAnalysis_ModuleStatus] VALUES (N'USP_AvailabilityDeepAnalysis', 'ERROR_HANDLED', ERROR_NUMBER(), ERROR_MESSAGE());
        END CATCH;

        IF @MitAgentMonitoring = 1
        BEGIN TRY
            SELECT @ChildStatus = NULL, @ChildPartial = NULL, @ChildErrorNumber = NULL, @ChildErrorMessage = NULL;
            EXEC [monitor].[USP_AgentMonitoringAnalysis]
                  @MaxZeilen = @MaxZeilen
                , @ResultSetArt = @ResultSetArtNormalisiert
                , @JsonErzeugen = @JsonErzeugen
                , @Json = @AgentMonitoringJson OUTPUT
                , @PrintMeldungen = @PrintMeldungen
                , @StatusCodeOut = @ChildStatus OUTPUT, @IsPartialOut = @ChildPartial OUTPUT
                , @ErrorNumberOut = @ChildErrorNumber OUTPUT, @ErrorMessageOut = @ChildErrorMessage OUTPUT;
            INSERT [#InfrastructureAnalysis_ModuleStatus] VALUES
            (N'USP_AgentMonitoringAnalysis', COALESCE(@ChildStatus, 'ERROR_HANDLED'), @ChildErrorNumber, @ChildErrorMessage);
        END TRY
        BEGIN CATCH
            INSERT [#InfrastructureAnalysis_ModuleStatus] VALUES (N'USP_AgentMonitoringAnalysis', 'ERROR_HANDLED', ERROR_NUMBER(), ERROR_MESSAGE());
        END CATCH;
    END;

    DECLARE @OverallStatus varchar(40) =
        CASE WHEN EXISTS
                  (SELECT 1 FROM [#InfrastructureAnalysis_ModuleStatus]
                   WHERE [StatusCode] NOT IN ('EXECUTED','AVAILABLE','AVAILABLE_WITH_FINDING','NOT_APPLICABLE'))
             THEN 'AVAILABLE_LIMITED'
             WHEN EXISTS (SELECT 1 FROM [#InfrastructureAnalysis_ModuleStatus] WHERE [StatusCode] = 'AVAILABLE_WITH_FINDING')
             THEN 'AVAILABLE_WITH_FINDING'
             ELSE 'AVAILABLE' END;
    DECLARE @IsPartial bit = CONVERT(bit,
        CASE WHEN EXISTS
             (SELECT 1 FROM [#InfrastructureAnalysis_ModuleStatus]
              WHERE [StatusCode] NOT IN ('EXECUTED','AVAILABLE','AVAILABLE_WITH_FINDING','NOT_APPLICABLE'))
             THEN 1 ELSE 0 END);

    IF @ResultSetArtNormalisiert <> 'NONE'
    BEGIN
        SELECT
              @CollectionTimeUtc AS [CollectionTimeUtc]
            , CAST(N'monitor.USP_InfrastructureAnalysis' AS nvarchar(256)) AS [ModuleName]
            , @OverallStatus AS [StatusCode]
            , @IsPartial AS [IsPartial]
            , CONVERT(bigint, (SELECT COUNT_BIG(*) FROM [#InfrastructureAnalysis_ModuleStatus])) AS [ModuleCount]
            , CONVERT(bigint, (SELECT COUNT_BIG(*) FROM [#InfrastructureAnalysis_ModuleStatus]
                               WHERE [StatusCode] NOT IN ('EXECUTED','AVAILABLE','AVAILABLE_WITH_FINDING','NOT_APPLICABLE'))) AS [ProblemModuleCount];

        IF @ResultSetArtNormalisiert = 'RAW'
        BEGIN
            SELECT [ModuleName], [StatusCode], [ErrorNumber], [ErrorMessage]
            FROM [#InfrastructureAnalysis_ModuleStatus]
            ORDER BY [ModuleName];
        END;
        ELSE
        BEGIN
            SELECT
                  N'Infrastruktur-Modul' AS [Ergebnis]
                , [ModuleName] AS [Modul]
                , [StatusCode] AS [Status]
                , [ErrorNumber] AS [Fehlernummer]
                , [ErrorMessage] AS [Fehlermeldung]
            FROM [#InfrastructureAnalysis_ModuleStatus]
            ORDER BY [ModuleName];
        END;
    END;

    IF @JsonErzeugen = 1
    BEGIN
        DECLARE @MetaJson nvarchar(max) =
        (
            SELECT
                  N'InfrastructureAnalysis' AS [resultName]
                , 1 AS [schemaVersion]
                , @CollectionTimeUtc AS [generatedAtUtc]
                , @OverallStatus AS [statusCode]
                , @IsPartial AS [isPartial]
                , @MaxZeilen AS [requestedMaxRows]
            FOR JSON PATH, WITHOUT_ARRAY_WRAPPER, INCLUDE_NULL_VALUES
        );
        DECLARE @WarningsJson nvarchar(max) =
            (SELECT * FROM [#InfrastructureAnalysis_ModuleStatus]
             WHERE [StatusCode] NOT IN ('EXECUTED','AVAILABLE','AVAILABLE_WITH_FINDING','NOT_APPLICABLE')
             ORDER BY [ModuleName] FOR JSON PATH, INCLUDE_NULL_VALUES);

        SET @Json = CONCAT
        (
              N'{"meta":', COALESCE(@MetaJson, N'{}')
            , N',"agent":', COALESCE(JSON_QUERY(@AgentJson), N'null')
            , N',"agentJobs":', COALESCE(JSON_QUERY(@AgentJobsJson), N'null')
            , N',"resourceGovernor":', COALESCE(JSON_QUERY(@ResourceGovernorJson), N'null')
            , N',"availabilityGroups":', COALESCE(JSON_QUERY(@AvailabilityGroupsJson), N'null')
            , N',"backupRecovery":', COALESCE(JSON_QUERY(@BackupRecoveryJson), N'null')
            , N',"logShipping":', COALESCE(JSON_QUERY(@LogShippingJson), N'null')
            , N',"replication":', COALESCE(JSON_QUERY(@ReplicationJson), N'null')
            , N',"dataCapture":', COALESCE(JSON_QUERY(@DataCaptureJson), N'null')
            , N',"backupChain":', COALESCE(JSON_QUERY(@BackupChainJson), N'null')
            , N',"availabilityDeep":', COALESCE(JSON_QUERY(@AvailabilityDeepJson), N'null')
            , N',"agentMonitoring":', COALESCE(JSON_QUERY(@AgentMonitoringJson), N'null')
            , N',"warnings":', COALESCE(@WarningsJson, N'[]')
            , N'}'
        );
    END;
    IF @ConsoleResultRequested = 1
    BEGIN
        EXEC [monitor].[InternalEmitConsoleResult]
              @SourceTable=N'#InfrastructureAnalysis_ModuleStatus'
            , @ResultLabel=N'InfrastructureAnalysis'
            , @EmptyMessage=N'Keine fachlichen Ergebnisse';
    END;
    IF @TableResultRequested = 1
    BEGIN
        EXEC [monitor].[InternalWriteResultTable]
              @SourceTable = N'#InfrastructureAnalysis_ModuleStatus'
            , @TargetTable=@TableTarget
            , @ThrowOnError = 1;
    END;
END;
GO
-- END SOURCE: Code/07_Infrastructure/090_USP_InfrastructureAnalysis.sql

-- BEGIN SOURCE: Code/08_ServerHealth/010_USP_ServerCpuTopology.sql
/*
===============================================================================
Objekt       : monitor.USP_ServerCpuTopology
Version      : 2.0.0
Stand        : 2026-07-15
Zweck        : Liefert die CPU-, Scheduler- und NUMA-Topologie mit der
               momentanen Schedulerlast.
Datenquellen : sys.dm_os_sys_info, sys.dm_os_schedulers, sys.dm_os_nodes
Vertrag      : Resultset 1 ist immer Modulstatus; @ResultSetArt=NONE unterdrückt Resultsets; RAW und CONSOLE liefern unterschiedliche Projektionen. Optional JSON.
===============================================================================
*/

CREATE OR ALTER PROCEDURE [monitor].[USP_ServerCpuTopology]
 @PrintMeldungen bit=1,@Hilfe bit=0,@ResultSetArt varchar(16)='CONSOLE'
    , @ResultTablesJson               nvarchar(max) = NULL
    , @JsonErzeugen bit=0,@Json nvarchar(max)=NULL OUTPUT,
 @StatusCodeOut varchar(40)=NULL OUTPUT,@IsPartialOut bit=NULL OUTPUT,@ErrorNumberOut int=NULL OUTPUT,@ErrorMessageOut nvarchar(2048)=NULL OUTPUT
AS
BEGIN
 SET NOCOUNT ON;SET @Json=NULL;DECLARE @ResultSetArtNormalisiert varchar(16)=UPPER(LTRIM(RTRIM(COALESCE(@ResultSetArt,''))));
    DECLARE @TableResultRequested bit = CASE WHEN @ResultSetArtNormalisiert = 'TABLE' THEN 1 ELSE 0 END;
    DECLARE @ConsoleResultRequested bit = CASE WHEN @ResultSetArtNormalisiert = 'CONSOLE' THEN 1 ELSE 0 END;
    DECLARE @TableTarget sysname=NULL;
    IF @TableResultRequested=0 AND NULLIF(LTRIM(RTRIM(COALESCE(@ResultTablesJson,N''))),N'') IS NOT NULL THROW 51011,N'@ResultTablesJson ist ausschließlich mit @ResultSetArt=TABLE zulässig.',1;
    IF @TableResultRequested=1 EXEC [monitor].[InternalPrepareSingleResultTable] @ResultTablesJson=@ResultTablesJson,@ResultName=N'cpuTopology',@TargetTable=@TableTarget OUTPUT,@ThrowOnError=1;
    IF @TableResultRequested = 1 OR @ConsoleResultRequested = 1 SET @ResultSetArtNormalisiert = 'NONE'; IF @Hilfe=1 BEGIN PRINT N'monitor.USP_ServerCpuTopology';RETURN;END;
 DECLARE @T datetime2(3)=SYSUTCDATETIME(),@S varchar(40)='AVAILABLE',@P bit=0,@E int=NULL,@M nvarchar(2048)=NULL;
 IF @ResultSetArtNormalisiert NOT IN('RAW','CONSOLE','NONE') SELECT @S='INVALID_PARAMETER',@P=1,@M=N'@ResultSetArt muss CONSOLE, RAW, TABLE oder NONE enthalten.';
 CREATE TABLE [#ServerCpuTopology_I]([cpu_count] int,[scheduler_count] int,[hyperthread_ratio] int,[socket_count] int,[cores_per_socket] int,[numa_node_count] int,[softnuma_configuration_desc] nvarchar(60),[sqlserver_start_time] datetime,[affinity_type_desc] nvarchar(60));
 CREATE TABLE [#ServerCpuTopology_Sch]([parent_node_id] int,[status] nvarchar(60),[SchedulerCount] bigint,[VisibleOnlineSchedulers] bigint,[OnlineSchedulers] bigint,[CurrentTasks] bigint,[RunnableTasks] bigint,[ActiveWorkers] bigint,[LoadFactor] bigint,[Finding] varchar(40));
 CREATE TABLE [#ServerCpuTopology_N]([node_id] int,[node_state_desc] nvarchar(60),[memory_node_id] int,[online_scheduler_count] int,[idle_scheduler_count] int,[active_worker_count] int,[avg_load_balance] bigint);
 SET LOCK_TIMEOUT 0;
 BEGIN TRY
  INSERT [#ServerCpuTopology_I] SELECT [cpu_count],[scheduler_count],[hyperthread_ratio],[socket_count],[cores_per_socket],[numa_node_count],[softnuma_configuration_desc],[sqlserver_start_time],[affinity_type_desc] FROM [sys].[dm_os_sys_info] WITH (NOLOCK);
  INSERT [#ServerCpuTopology_Sch] SELECT [parent_node_id],[status],COUNT_BIG(*),SUM(CONVERT(bigint,CASE WHEN [status]='VISIBLE ONLINE' THEN 1 ELSE 0 END)),SUM(CONVERT(bigint,[is_online])),SUM(CONVERT(bigint,[current_tasks_count])),SUM(CONVERT(bigint,[runnable_tasks_count])),SUM(CONVERT(bigint,[active_workers_count])),SUM(CONVERT(bigint,[load_factor])),
   CASE WHEN SUM([runnable_tasks_count])>0 THEN 'RUNNABLE_TASKS_PRESENT' WHEN SUM(CASE WHEN [status]='VISIBLE ONLINE' THEN 1 ELSE 0 END)=0 THEN 'NO_VISIBLE_SCHEDULER' ELSE 'OK_SNAPSHOT' END
  FROM [sys].[dm_os_schedulers] WITH (NOLOCK) WHERE [scheduler_id]<1048576 GROUP BY [parent_node_id],[status];
  INSERT [#ServerCpuTopology_N] SELECT [node_id],[node_state_desc],[memory_node_id],[online_scheduler_count],[idle_scheduler_count],[active_worker_count],[avg_load_balance] FROM [sys].[dm_os_nodes] WITH (NOLOCK) WHERE [node_state_desc]<>'ONLINE DAC';
 END TRY BEGIN CATCH SELECT @S=CASE WHEN ERROR_NUMBER() IN(229,297,300,371) THEN 'DENIED_PERMISSION' WHEN ERROR_NUMBER()=1222 THEN 'TIMEOUT' ELSE 'ERROR_HANDLED' END,@P=1,@E=ERROR_NUMBER(),@M=ERROR_MESSAGE(); END CATCH;
  SELECT @StatusCodeOut=@S,@IsPartialOut=@P,@ErrorNumberOut=@E,@ErrorMessageOut=@M;
 IF @PrintMeldungen=1 AND @S<>'AVAILABLE' RAISERROR(N'USP_ServerCpuTopology: %s',10,1,@M) WITH NOWAIT;
 IF @ResultSetArtNormalisiert<>'NONE' BEGIN SELECT CAST('2.0' AS varchar(16)) [ContractVersion],@T [CollectionTimeUtc],N'monitor.USP_ServerCpuTopology' [ModuleName],@S [StatusCode],@P [IsPartial],@E [ErrorNumber],@M [ErrorMessage];IF @ResultSetArtNormalisiert='RAW' BEGIN SELECT * FROM [#ServerCpuTopology_I] ;SELECT * FROM [#ServerCpuTopology_Sch] ORDER BY [parent_node_id],[status];SELECT * FROM [#ServerCpuTopology_N] ORDER BY [node_id]; END ELSE BEGIN SELECT N'cpuTopology' [Ergebnis],[x].* FROM [#ServerCpuTopology_I] [x] ;SELECT N'schedulers' [Ergebnis],[x].* FROM [#ServerCpuTopology_Sch] [x] ORDER BY [parent_node_id],[status];SELECT N'numaNodes' [Ergebnis],[x].* FROM [#ServerCpuTopology_N] [x] ORDER BY [node_id]; END;END;
 IF @JsonErzeugen=1 BEGIN DECLARE @Meta nvarchar(max)=(SELECT N'ServerCpuTopology' [resultName],1 [schemaVersion],@T [generatedAtUtc],@S [statusCode],@P [isPartial],@E [errorNumber],@M [errorMessage] FOR JSON PATH,WITHOUT_ARRAY_WRAPPER,INCLUDE_NULL_VALUES),@J0 nvarchar(max)=(SELECT * FROM [#ServerCpuTopology_I]  FOR JSON PATH,INCLUDE_NULL_VALUES),@J1 nvarchar(max)=(SELECT * FROM [#ServerCpuTopology_Sch] ORDER BY [parent_node_id],[status] FOR JSON PATH,INCLUDE_NULL_VALUES),@J2 nvarchar(max)=(SELECT * FROM [#ServerCpuTopology_N] ORDER BY [node_id] FOR JSON PATH,INCLUDE_NULL_VALUES);SET @Json=CONCAT(N'{"meta":',COALESCE(@Meta,N'{}'),N',"cpuTopology":',COALESCE(@J0,N'[]'),N',"schedulers":',COALESCE(@J1,N'[]'),N',"numaNodes":',COALESCE(@J2,N'[]'),N',"warnings":[]}');END;
    IF @ConsoleResultRequested = 1
    BEGIN
        EXEC [monitor].[InternalEmitConsoleResult]
              @SourceTable=N'#ServerCpuTopology_I'
            , @ResultLabel=N'ServerCpuTopology'
            , @EmptyMessage=N'Keine fachlichen Ergebnisse';
    END;
    IF @TableResultRequested = 1
    BEGIN
        EXEC [monitor].[InternalWriteResultTable]
              @SourceTable = N'#ServerCpuTopology_I'
            , @TargetTable=@TableTarget
            , @ThrowOnError = 1;
    END;
END;
GO
-- END SOURCE: Code/08_ServerHealth/010_USP_ServerCpuTopology.sql

-- BEGIN SOURCE: Code/08_ServerHealth/020_USP_ServerNuma.sql
/*
===============================================================================
Objekt       : monitor.USP_ServerNuma
Version      : 2.0.0
Stand        : 2026-07-15
Zweck        : Liefert die NUMA- und Soft-NUMA-Verteilung, den Scheduler-Skew
               und die Memory Nodes.
Datenquellen : sys.dm_os_nodes, sys.dm_os_schedulers, sys.dm_os_memory_nodes
Vertrag      : Resultset 1 ist immer Modulstatus; @ResultSetArt=NONE unterdrückt Resultsets; RAW und CONSOLE liefern unterschiedliche Projektionen. Optional JSON.
===============================================================================
*/

CREATE OR ALTER PROCEDURE [monitor].[USP_ServerNuma]
 @PrintMeldungen bit=1,@Hilfe bit=0,@ResultSetArt varchar(16)='CONSOLE'
    , @ResultTablesJson               nvarchar(max) = NULL
    , @JsonErzeugen bit=0,@Json nvarchar(max)=NULL OUTPUT,
 @StatusCodeOut varchar(40)=NULL OUTPUT,@IsPartialOut bit=NULL OUTPUT,@ErrorNumberOut int=NULL OUTPUT,@ErrorMessageOut nvarchar(2048)=NULL OUTPUT
AS
BEGIN
 SET NOCOUNT ON;SET @Json=NULL;DECLARE @ResultSetArtNormalisiert varchar(16)=UPPER(LTRIM(RTRIM(COALESCE(@ResultSetArt,''))));
    DECLARE @TableResultRequested bit = CASE WHEN @ResultSetArtNormalisiert = 'TABLE' THEN 1 ELSE 0 END;
    DECLARE @ConsoleResultRequested bit = CASE WHEN @ResultSetArtNormalisiert = 'CONSOLE' THEN 1 ELSE 0 END;
    DECLARE @TableTarget sysname=NULL;
    IF @TableResultRequested=0 AND NULLIF(LTRIM(RTRIM(COALESCE(@ResultTablesJson,N''))),N'') IS NOT NULL THROW 51011,N'@ResultTablesJson ist ausschließlich mit @ResultSetArt=TABLE zulässig.',1;
    IF @TableResultRequested=1 EXEC [monitor].[InternalPrepareSingleResultTable] @ResultTablesJson=@ResultTablesJson,@ResultName=N'numaNodes',@TargetTable=@TableTarget OUTPUT,@ThrowOnError=1;
    IF @TableResultRequested = 1 OR @ConsoleResultRequested = 1 SET @ResultSetArtNormalisiert = 'NONE';IF @Hilfe=1 BEGIN PRINT N'monitor.USP_ServerNuma';RETURN;END;
 DECLARE @T datetime2(3)=SYSUTCDATETIME(),@S varchar(40)='AVAILABLE',@P bit=0,@E int=NULL,@M nvarchar(2048)=NULL;
 IF @ResultSetArtNormalisiert NOT IN('RAW','CONSOLE','NONE') SELECT @S='INVALID_PARAMETER',@P=1,@M=N'@ResultSetArt muss CONSOLE, RAW, TABLE oder NONE enthalten.';
 CREATE TABLE [#ServerNuma_N]([node_id] int,[node_state_desc] nvarchar(60),[memory_node_id] int,[online_scheduler_count] int,[idle_scheduler_count] int,[active_worker_count] int,[avg_load_balance] bigint,[SchedulerCount] bigint,[VisibleOnline] bigint,[CurrentTasks] bigint,[RunnableTasks] bigint,[ActiveWorkers] bigint,[LoadFactor] bigint,[RunnablePerScheduler] decimal(19,4),[Finding] varchar(50));
 CREATE TABLE [#ServerNuma_MN]([memory_node_id] int,[virtual_address_space_reserved_kb] bigint,[virtual_address_space_committed_kb] bigint,[locked_page_allocations_kb] bigint,[pages_kb] bigint,[shared_memory_reserved_kb] bigint,[shared_memory_committed_kb] bigint);
 SET LOCK_TIMEOUT 0;
 BEGIN TRY
  ;WITH X AS(SELECT [parent_node_id],COUNT_BIG(*)[SchedulerCount],SUM(CONVERT(bigint,CASE WHEN [status]='VISIBLE ONLINE' THEN 1 ELSE 0 END))[VisibleOnline],SUM(CONVERT(bigint,[current_tasks_count]))[CurrentTasks],SUM(CONVERT(bigint,[runnable_tasks_count]))[RunnableTasks],SUM(CONVERT(bigint,[active_workers_count]))[ActiveWorkers],SUM(CONVERT(bigint,[load_factor]))[LoadFactor] FROM [sys].[dm_os_schedulers] WITH (NOLOCK) WHERE [scheduler_id]<1048576 GROUP BY [parent_node_id])
  INSERT [#ServerNuma_N] SELECT [n].[node_id],[n].[node_state_desc],[n].[memory_node_id],[n].[online_scheduler_count],[n].[idle_scheduler_count],[n].[active_worker_count],[n].[avg_load_balance],[x].[SchedulerCount],[x].[VisibleOnline],[x].[CurrentTasks],[x].[RunnableTasks],[x].[ActiveWorkers],[x].[LoadFactor],
   CONVERT(decimal(19,4),1.0*[x].[RunnableTasks]/NULLIF([x].[VisibleOnline],0)),CASE WHEN [n].[node_state_desc] NOT LIKE 'ONLINE%' THEN 'NODE_NOT_ONLINE' WHEN [x].[RunnableTasks]>0 THEN 'RUNNABLE_TASKS_PRESENT' ELSE 'OK_SNAPSHOT' END
  FROM [sys].[dm_os_nodes] n WITH (NOLOCK) LEFT JOIN [X] x ON [x].[parent_node_id]=[n].[node_id] WHERE [n].[node_state_desc]<>'ONLINE DAC';
  INSERT [#ServerNuma_MN] SELECT [memory_node_id],[virtual_address_space_reserved_kb],[virtual_address_space_committed_kb],[locked_page_allocations_kb],[pages_kb],[shared_memory_reserved_kb],[shared_memory_committed_kb] FROM [sys].[dm_os_memory_nodes] WITH (NOLOCK) WHERE [memory_node_id]<64;
 END TRY BEGIN CATCH SELECT @S=CASE WHEN ERROR_NUMBER() IN(229,297,300,371) THEN 'DENIED_PERMISSION' WHEN ERROR_NUMBER()=1222 THEN 'TIMEOUT' ELSE 'ERROR_HANDLED' END,@P=1,@E=ERROR_NUMBER(),@M=ERROR_MESSAGE(); END CATCH;
 SELECT @StatusCodeOut=@S,@IsPartialOut=@P,@ErrorNumberOut=@E,@ErrorMessageOut=@M;
 IF @PrintMeldungen=1 AND @S<>'AVAILABLE' RAISERROR(N'USP_ServerNuma: %s',10,1,@M) WITH NOWAIT;
 IF @ResultSetArtNormalisiert<>'NONE' BEGIN SELECT CAST('2.0' AS varchar(16)) [ContractVersion],@T [CollectionTimeUtc],N'monitor.USP_ServerNuma' [ModuleName],@S [StatusCode],@P [IsPartial],@E [ErrorNumber],@M [ErrorMessage];IF @ResultSetArtNormalisiert='RAW' BEGIN SELECT * FROM [#ServerNuma_N] ORDER BY [node_id];SELECT * FROM [#ServerNuma_MN] ORDER BY [memory_node_id]; END ELSE BEGIN SELECT N'numaNodes' [Ergebnis],[x].* FROM [#ServerNuma_N] [x] ORDER BY [node_id];SELECT N'memoryNodes' [Ergebnis],[x].* FROM [#ServerNuma_MN] [x] ORDER BY [memory_node_id]; END;END;
 IF @JsonErzeugen=1 BEGIN DECLARE @Meta nvarchar(max)=(SELECT N'ServerNuma' [resultName],1 [schemaVersion],@T [generatedAtUtc],@S [statusCode],@P [isPartial],@E [errorNumber],@M [errorMessage] FOR JSON PATH,WITHOUT_ARRAY_WRAPPER,INCLUDE_NULL_VALUES),@J0 nvarchar(max)=(SELECT * FROM [#ServerNuma_N] ORDER BY [node_id] FOR JSON PATH,INCLUDE_NULL_VALUES),@J1 nvarchar(max)=(SELECT * FROM [#ServerNuma_MN] ORDER BY [memory_node_id] FOR JSON PATH,INCLUDE_NULL_VALUES);SET @Json=CONCAT(N'{"meta":',COALESCE(@Meta,N'{}'),N',"numaNodes":',COALESCE(@J0,N'[]'),N',"memoryNodes":',COALESCE(@J1,N'[]'),N',"warnings":[]}');END;
    IF @ConsoleResultRequested = 1
    BEGIN
        EXEC [monitor].[InternalEmitConsoleResult]
              @SourceTable=N'#ServerNuma_N'
            , @ResultLabel=N'ServerNuma'
            , @EmptyMessage=N'Keine fachlichen Ergebnisse';
    END;
    IF @TableResultRequested = 1
    BEGIN
        EXEC [monitor].[InternalWriteResultTable]
              @SourceTable = N'#ServerNuma_N'
            , @TargetTable=@TableTarget
            , @ThrowOnError = 1;
    END;
END;
GO
-- END SOURCE: Code/08_ServerHealth/020_USP_ServerNuma.sql

-- BEGIN SOURCE: Code/08_ServerHealth/030_USP_ServerMemory.sql
/*
===============================================================================
Objekt       : monitor.USP_ServerMemory
Version      : 2.0.0
Stand        : 2026-07-15
Zweck        : Liefert Angaben zu Betriebssystem-, Prozess- und SQL-Speicher,
               Memory Model, Clerks und Grants.
Datenquellen : sys.dm_os_sys_memory, sys.dm_os_process_memory, sys.dm_os_sys_info, sys.configurations, sys.dm_os_memory_clerks, sys.dm_exec_query_memory_grants
Vertrag      : Resultset 1 ist immer Modulstatus; @ResultSetArt=NONE unterdrückt Resultsets; RAW und CONSOLE liefern unterschiedliche Projektionen. Optional JSON.
===============================================================================
*/

CREATE OR ALTER PROCEDURE [monitor].[USP_ServerMemory]
 @MaxZeilen int=100,@PrintMeldungen bit=1,@Hilfe bit=0,@ResultSetArt varchar(16)='CONSOLE'
    , @ResultTablesJson               nvarchar(max) = NULL
    , @JsonErzeugen bit=0,@Json nvarchar(max)=NULL OUTPUT,
 @StatusCodeOut varchar(40)=NULL OUTPUT,@IsPartialOut bit=NULL OUTPUT,@ErrorNumberOut int=NULL OUTPUT,@ErrorMessageOut nvarchar(2048)=NULL OUTPUT
AS
BEGIN
 SET NOCOUNT ON;SET @Json=NULL;DECLARE @ResultSetArtNormalisiert varchar(16)=UPPER(LTRIM(RTRIM(COALESCE(@ResultSetArt,''))));
    DECLARE @TableResultRequested bit = CASE WHEN @ResultSetArtNormalisiert = 'TABLE' THEN 1 ELSE 0 END;
    DECLARE @ConsoleResultRequested bit = CASE WHEN @ResultSetArtNormalisiert = 'CONSOLE' THEN 1 ELSE 0 END;
    DECLARE @TableTarget sysname=NULL;
    IF @TableResultRequested=0 AND NULLIF(LTRIM(RTRIM(COALESCE(@ResultTablesJson,N''))),N'') IS NOT NULL THROW 51011,N'@ResultTablesJson ist ausschließlich mit @ResultSetArt=TABLE zulässig.',1;
    IF @TableResultRequested=1 EXEC [monitor].[InternalPrepareSingleResultTable] @ResultTablesJson=@ResultTablesJson,@ResultName=N'summary',@TargetTable=@TableTarget OUTPUT,@ThrowOnError=1;
    IF @TableResultRequested = 1 OR @ConsoleResultRequested = 1 SET @ResultSetArtNormalisiert = 'NONE';
    DECLARE @EffectiveMaxZeilen bigint = CASE WHEN @MaxZeilen IS NULL OR @MaxZeilen=0 THEN CONVERT(bigint,9223372036854775807) ELSE CONVERT(bigint,@MaxZeilen) END;IF @Hilfe=1 BEGIN PRINT N'monitor.USP_ServerMemory @MaxZeilen=100';RETURN;END;
 DECLARE @T datetime2(3)=SYSUTCDATETIME(),@S varchar(40)='AVAILABLE',@P bit=0,@E int=NULL,@M nvarchar(2048)=NULL;
 IF @ResultSetArtNormalisiert NOT IN('RAW','CONSOLE','NONE') SELECT @S='INVALID_PARAMETER',@P=1,@M=N'@ResultSetArt muss CONSOLE, RAW, TABLE oder NONE enthalten.';
 CREATE TABLE [#ServerMemory_Summary]([total_physical_memory_kb] bigint,[available_physical_memory_kb] bigint,[system_memory_state_desc] nvarchar(256),[physical_memory_in_use_kb] bigint,[locked_page_allocations_kb] bigint,[large_page_allocations_kb] bigint,[process_physical_memory_low] bit,[process_virtual_memory_low] bit,[committed_kb] bigint,[committed_target_kb] bigint,[visible_target_kb] bigint,[sql_memory_model_desc] nvarchar(60),[min_server_memory_mb] bigint,[max_server_memory_mb] bigint,[LPIMAssessment] varchar(50),[MemoryFinding] varchar(60));
 CREATE TABLE [#ServerMemory_C]([type] nvarchar(60),[pages_kb] bigint,[virtual_memory_committed_kb] bigint,[awe_allocated_kb] bigint,[shared_memory_committed_kb] bigint);
 CREATE TABLE [#ServerMemory_G]([ActiveOrWaitingGrants] bigint,[RequestedMemoryKb] bigint,[GrantedMemoryKb] bigint,[UsedMemoryKb] bigint,[WaitingGrantCount] bigint);
 IF @MaxZeilen<0 SELECT @S='INVALID_PARAMETER',@P=1,@M=N'@MaxZeilen darf nicht negativ sein; NULL/0 bedeutet unbegrenzt.';
 ELSE BEGIN SET LOCK_TIMEOUT 0;BEGIN TRY
  INSERT [#ServerMemory_Summary]
  SELECT [sm].[total_physical_memory_kb],[sm].[available_physical_memory_kb],[sm].[system_memory_state_desc],[pm].[physical_memory_in_use_kb],[pm].[locked_page_allocations_kb],[pm].[large_page_allocations_kb],[pm].[process_physical_memory_low],[pm].[process_virtual_memory_low],[si].[committed_kb],[si].[committed_target_kb],[si].[visible_target_kb],[si].[sql_memory_model_desc],
    MIN(CASE WHEN [c].[name]='min server memory (MB)' THEN CONVERT(bigint,[c].[value_in_use]) END),MAX(CASE WHEN [c].[name]='max server memory (MB)' THEN CONVERT(bigint,[c].[value_in_use]) END),
    CASE WHEN [si].[sql_memory_model_desc] LIKE '%LOCK%' OR [pm].[locked_page_allocations_kb]>0 THEN 'LOCKED_PAGES_IN_USE_OR_MODEL' ELSE 'LPIM_NOT_CONFIRMED_BY_RUNTIME' END,
    CASE WHEN [pm].[process_physical_memory_low]=1 OR [pm].[process_virtual_memory_low]=1 THEN 'PROCESS_MEMORY_LOW' WHEN [si].[committed_target_kb]<[si].[committed_kb] THEN 'TARGET_BELOW_COMMITTED' WHEN [sm].[available_physical_memory_kb]<1048576 THEN 'LOW_OS_FREE_MEMORY_REVIEW' ELSE 'OK_SNAPSHOT' END
  FROM [sys].[dm_os_sys_memory] sm WITH (NOLOCK) CROSS JOIN [sys].[dm_os_process_memory] pm WITH (NOLOCK) CROSS JOIN [sys].[dm_os_sys_info] si WITH (NOLOCK) CROSS JOIN [sys].[configurations] c WITH (NOLOCK)
  WHERE [c].[name] IN('min server memory (MB)','max server memory (MB)') GROUP BY [sm].[total_physical_memory_kb],[sm].[available_physical_memory_kb],[sm].[system_memory_state_desc],[pm].[physical_memory_in_use_kb],[pm].[locked_page_allocations_kb],[pm].[large_page_allocations_kb],[pm].[process_physical_memory_low],[pm].[process_virtual_memory_low],[si].[committed_kb],[si].[committed_target_kb],[si].[visible_target_kb],[si].[sql_memory_model_desc];
  INSERT [#ServerMemory_C] SELECT TOP (@EffectiveMaxZeilen)[type],SUM([pages_kb]),SUM([virtual_memory_committed_kb]),SUM([awe_allocated_kb]),SUM([shared_memory_committed_kb]) FROM [sys].[dm_os_memory_clerks] WITH (NOLOCK) GROUP BY [type] ORDER BY SUM([pages_kb])+SUM([virtual_memory_committed_kb])DESC OPTION(MAXDOP 1);
  INSERT [#ServerMemory_G] SELECT COUNT_BIG(*),SUM(CONVERT(bigint,[requested_memory_kb])),SUM(CONVERT(bigint,[granted_memory_kb])),SUM(CONVERT(bigint,[used_memory_kb])),SUM(CONVERT(bigint,CASE WHEN [grant_time] IS NULL THEN 1 ELSE 0 END)) FROM [sys].[dm_exec_query_memory_grants] WITH (NOLOCK);
 END TRY BEGIN CATCH SELECT @S=CASE WHEN ERROR_NUMBER()IN(229,297,300,371)THEN'DENIED_PERMISSION'WHEN ERROR_NUMBER()=1222 THEN'TIMEOUT'ELSE'ERROR_HANDLED'END,@P=1,@E=ERROR_NUMBER(),@M=ERROR_MESSAGE();END CATCH;END;
 SELECT @StatusCodeOut=@S,@IsPartialOut=@P,@ErrorNumberOut=@E,@ErrorMessageOut=@M;IF @PrintMeldungen=1 AND @S<>'AVAILABLE'RAISERROR(N'USP_ServerMemory: %s',10,1,@M) WITH NOWAIT;
 IF @ResultSetArtNormalisiert<>'NONE' BEGIN SELECT CAST('2.0' AS varchar(16)) [ContractVersion],@T [CollectionTimeUtc],N'monitor.USP_ServerMemory' [ModuleName],@S [StatusCode],@P [IsPartial],@E [ErrorNumber],@M [ErrorMessage];IF @ResultSetArtNormalisiert='RAW' BEGIN SELECT * FROM [#ServerMemory_Summary] ;SELECT * FROM [#ServerMemory_C] ORDER BY [pages_kb] DESC;SELECT * FROM [#ServerMemory_G] ; END ELSE BEGIN SELECT N'summary' [Ergebnis],[x].* FROM [#ServerMemory_Summary] [x] ;SELECT N'memoryClerks' [Ergebnis],[x].* FROM [#ServerMemory_C] [x] ORDER BY [pages_kb] DESC;SELECT N'memoryGrants' [Ergebnis],[x].* FROM [#ServerMemory_G] [x] ; END;END;
 IF @JsonErzeugen=1 BEGIN DECLARE @Meta nvarchar(max)=(SELECT N'ServerMemory' [resultName],1 [schemaVersion],@T [generatedAtUtc],@S [statusCode],@P [isPartial],@E [errorNumber],@M [errorMessage] FOR JSON PATH,WITHOUT_ARRAY_WRAPPER,INCLUDE_NULL_VALUES),@J0 nvarchar(max)=(SELECT * FROM [#ServerMemory_Summary]  FOR JSON PATH,INCLUDE_NULL_VALUES),@J1 nvarchar(max)=(SELECT * FROM [#ServerMemory_C] ORDER BY [pages_kb] DESC FOR JSON PATH,INCLUDE_NULL_VALUES),@J2 nvarchar(max)=(SELECT * FROM [#ServerMemory_G]  FOR JSON PATH,INCLUDE_NULL_VALUES);SET @Json=CONCAT(N'{"meta":',COALESCE(@Meta,N'{}'),N',"summary":',COALESCE(@J0,N'[]'),N',"memoryClerks":',COALESCE(@J1,N'[]'),N',"memoryGrants":',COALESCE(@J2,N'[]'),N',"warnings":[]}');END;
    IF @ConsoleResultRequested = 1
    BEGIN
        EXEC [monitor].[InternalEmitConsoleResult]
              @SourceTable=N'#ServerMemory_Summary'
            , @ResultLabel=N'ServerMemory'
            , @EmptyMessage=N'Keine fachlichen Ergebnisse';
    END;
    IF @TableResultRequested = 1
    BEGIN
        EXEC [monitor].[InternalWriteResultTable]
              @SourceTable = N'#ServerMemory_Summary'
            , @TargetTable=@TableTarget
            , @ThrowOnError = 1;
    END;
END;
GO
-- END SOURCE: Code/08_ServerHealth/030_USP_ServerMemory.sql

-- BEGIN SOURCE: Code/08_ServerHealth/040_USP_TempDBConfiguration.sql
/*
===============================================================================
Objekt       : monitor.USP_TempDBConfiguration
Version      : 2.0.0
Stand        : 2026-07-15
Zweck        : Analysiert TempDB-Dateien, Größenverteilung, Growth und
               Konfiguration. Ein früherer CTE-Laufzeitfehler ist behoben.
Datenquellen : tempdb.sys.database_files, sys.configurations
Vertrag      : Resultset 1 ist immer Modulstatus; @ResultSetArt=NONE unterdrückt Resultsets; RAW und CONSOLE liefern unterschiedliche Projektionen. Optional JSON.
===============================================================================
*/

CREATE OR ALTER PROCEDURE [monitor].[USP_TempDBConfiguration]
 @PrintMeldungen bit=1,@Hilfe bit=0,@ResultSetArt varchar(16)='CONSOLE'
    , @ResultTablesJson               nvarchar(max) = NULL
    , @JsonErzeugen bit=0,@Json nvarchar(max)=NULL OUTPUT,
 @StatusCodeOut varchar(40)=NULL OUTPUT,@IsPartialOut bit=NULL OUTPUT,@ErrorNumberOut int=NULL OUTPUT,@ErrorMessageOut nvarchar(2048)=NULL OUTPUT
AS
BEGIN
 SET NOCOUNT ON;SET @Json=NULL;DECLARE @ResultSetArtNormalisiert varchar(16)=UPPER(LTRIM(RTRIM(COALESCE(@ResultSetArt,''))));
    DECLARE @TableResultRequested bit = CASE WHEN @ResultSetArtNormalisiert = 'TABLE' THEN 1 ELSE 0 END;
    DECLARE @ConsoleResultRequested bit = CASE WHEN @ResultSetArtNormalisiert = 'CONSOLE' THEN 1 ELSE 0 END;
    DECLARE @TableTarget sysname=NULL;
    IF @TableResultRequested=0 AND NULLIF(LTRIM(RTRIM(COALESCE(@ResultTablesJson,N''))),N'') IS NOT NULL THROW 51011,N'@ResultTablesJson ist ausschließlich mit @ResultSetArt=TABLE zulässig.',1;
    IF @TableResultRequested=1 EXEC [monitor].[InternalPrepareSingleResultTable] @ResultTablesJson=@ResultTablesJson,@ResultName=N'files',@TargetTable=@TableTarget OUTPUT,@ThrowOnError=1;
    IF @TableResultRequested = 1 OR @ConsoleResultRequested = 1 SET @ResultSetArtNormalisiert = 'NONE';IF @Hilfe=1 BEGIN PRINT N'monitor.USP_TempDBConfiguration';RETURN;END;
 DECLARE @T datetime2(3)=SYSUTCDATETIME(),@S varchar(40)='AVAILABLE',@P bit=0,@E int=NULL,@M nvarchar(2048)=NULL;
 IF @ResultSetArtNormalisiert NOT IN('RAW','CONSOLE','NONE') SELECT @S='INVALID_PARAMETER',@P=1,@M=N'@ResultSetArt muss CONSOLE, RAW, TABLE oder NONE enthalten.';
 CREATE TABLE [#TempDBConfiguration_F]([file_id] int,[name] sysname,[type_desc] nvarchar(60),[physical_name] nvarchar(260),[SizeMb] decimal(19,2),[GrowthValue] decimal(19,2),[GrowthType] varchar(10),[max_size] int,[is_percent_growth] bit);
 CREATE TABLE [#TempDBConfiguration_Cfg]([name] nvarchar(128),[value_in_use] sql_variant);
 SET LOCK_TIMEOUT 0;BEGIN TRY
  INSERT [#TempDBConfiguration_F] SELECT [file_id],[name],[type_desc],[physical_name],CONVERT(decimal(19,2),[size]*8.0/1024),CONVERT(decimal(19,2),CASE WHEN [is_percent_growth]=1 THEN [growth] ELSE [growth]*8.0/1024 END),CASE WHEN [is_percent_growth]=1 THEN'PERCENT'ELSE'MB'END,[max_size],[is_percent_growth] FROM [tempdb].[sys].[database_files] WITH (NOLOCK);
  INSERT [#TempDBConfiguration_Cfg] SELECT [name],[value_in_use] FROM [sys].[configurations] WITH (NOLOCK) WHERE [name] IN('tempdb metadata memory-optimized','tempdb deferred drop','mixed page allocation');
 END TRY BEGIN CATCH SELECT @S=CASE WHEN ERROR_NUMBER()IN(229,297,300,371,916)THEN'DENIED_PERMISSION'WHEN ERROR_NUMBER()=1222 THEN'TIMEOUT'ELSE'ERROR_HANDLED'END,@P=1,@E=ERROR_NUMBER(),@M=ERROR_MESSAGE();END CATCH;
 SELECT @StatusCodeOut=@S,@IsPartialOut=@P,@ErrorNumberOut=@E,@ErrorMessageOut=@M;IF @PrintMeldungen=1 AND @S<>'AVAILABLE'RAISERROR(N'USP_TempDBConfiguration: %s',10,1,@M) WITH NOWAIT;
 IF @ResultSetArtNormalisiert<>'NONE' BEGIN SELECT CAST('2.0' AS varchar(16)) [ContractVersion],@T [CollectionTimeUtc],N'monitor.USP_TempDBConfiguration' [ModuleName],@S [StatusCode],@P [IsPartial],@E [ErrorNumber],@M [ErrorMessage];IF @ResultSetArtNormalisiert='RAW' BEGIN SELECT * FROM [#TempDBConfiguration_F] ORDER BY [file_id];SELECT * FROM [#TempDBConfiguration_Cfg] ORDER BY [name]; END ELSE BEGIN SELECT N'files' [Ergebnis],[x].* FROM [#TempDBConfiguration_F] [x] ORDER BY [file_id];SELECT N'configuration' [Ergebnis],[x].* FROM [#TempDBConfiguration_Cfg] [x] ORDER BY [name]; END;END;
 IF @JsonErzeugen=1 BEGIN DECLARE @Meta nvarchar(max)=(SELECT N'TempDBConfiguration' [resultName],1 [schemaVersion],@T [generatedAtUtc],@S [statusCode],@P [isPartial],@E [errorNumber],@M [errorMessage] FOR JSON PATH,WITHOUT_ARRAY_WRAPPER,INCLUDE_NULL_VALUES),@J0 nvarchar(max)=(SELECT * FROM [#TempDBConfiguration_F] ORDER BY [file_id] FOR JSON PATH,INCLUDE_NULL_VALUES),@J1 nvarchar(max)=(SELECT [name],CONVERT(nvarchar(4000),[value_in_use]) [value_in_use] FROM [#TempDBConfiguration_Cfg] ORDER BY [name] FOR JSON PATH,INCLUDE_NULL_VALUES);SET @Json=CONCAT(N'{"meta":',COALESCE(@Meta,N'{}'),N',"files":',COALESCE(@J0,N'[]'),N',"configuration":',COALESCE(@J1,N'[]'),N',"warnings":[]}');END;
    IF @ConsoleResultRequested = 1
    BEGIN
        EXEC [monitor].[InternalEmitConsoleResult]
              @SourceTable=N'#TempDBConfiguration_F'
            , @ResultLabel=N'TempDBConfiguration'
            , @EmptyMessage=N'Keine fachlichen Ergebnisse';
    END;
    IF @TableResultRequested = 1
    BEGIN
        EXEC [monitor].[InternalWriteResultTable]
              @SourceTable = N'#TempDBConfiguration_F'
            , @TargetTable=@TableTarget
            , @ThrowOnError = 1;
    END;
END;
GO
-- END SOURCE: Code/08_ServerHealth/040_USP_TempDBConfiguration.sql

-- BEGIN SOURCE: Code/08_ServerHealth/050_USP_ServerConfiguration.sql
/*
===============================================================================
Objekt       : monitor.USP_ServerConfiguration
Version      : 2.0.0
Stand        : 2026-07-15
Zweck        : Liefert die zentrale Serverkonfiguration mit kontextabhängigen
               Review-Hinweisen.
Datenquellen : sys.configurations, sys.dm_os_sys_info
Vertrag      : Resultset 1 ist immer Modulstatus; @ResultSetArt=NONE unterdrückt Resultsets; RAW und CONSOLE liefern unterschiedliche Projektionen. Optional JSON.
===============================================================================
*/

CREATE OR ALTER PROCEDURE [monitor].[USP_ServerConfiguration]
 @NurKernparameter bit=1,@PrintMeldungen bit=1,@Hilfe bit=0,@ResultSetArt varchar(16)='CONSOLE'
    , @ResultTablesJson               nvarchar(max) = NULL
    , @JsonErzeugen bit=0,@Json nvarchar(max)=NULL OUTPUT,
 @StatusCodeOut varchar(40)=NULL OUTPUT,@IsPartialOut bit=NULL OUTPUT,@ErrorNumberOut int=NULL OUTPUT,@ErrorMessageOut nvarchar(2048)=NULL OUTPUT
AS
BEGIN
 SET NOCOUNT ON;SET @Json=NULL;DECLARE @ResultSetArtNormalisiert varchar(16)=UPPER(LTRIM(RTRIM(COALESCE(@ResultSetArt,''))));
    DECLARE @TableResultRequested bit = CASE WHEN @ResultSetArtNormalisiert = 'TABLE' THEN 1 ELSE 0 END;
    DECLARE @ConsoleResultRequested bit = CASE WHEN @ResultSetArtNormalisiert = 'CONSOLE' THEN 1 ELSE 0 END;
    DECLARE @TableTarget sysname=NULL;
    IF @TableResultRequested=0 AND NULLIF(LTRIM(RTRIM(COALESCE(@ResultTablesJson,N''))),N'') IS NOT NULL THROW 51011,N'@ResultTablesJson ist ausschließlich mit @ResultSetArt=TABLE zulässig.',1;
    IF @TableResultRequested=1 EXEC [monitor].[InternalPrepareSingleResultTable] @ResultTablesJson=@ResultTablesJson,@ResultName=N'configuration',@TargetTable=@TableTarget OUTPUT,@ThrowOnError=1;
    IF @TableResultRequested = 1 OR @ConsoleResultRequested = 1 SET @ResultSetArtNormalisiert = 'NONE';IF @Hilfe=1 BEGIN PRINT N'monitor.USP_ServerConfiguration';RETURN;END;
 DECLARE @T datetime2(3)=SYSUTCDATETIME(),@S varchar(40)='AVAILABLE',@P bit=0,@E int=NULL,@M nvarchar(2048)=NULL,@Schedulers int=NULL;
 IF @ResultSetArtNormalisiert NOT IN('RAW','CONSOLE','NONE') SELECT @S='INVALID_PARAMETER',@P=1,@M=N'@ResultSetArt muss CONSOLE, RAW, TABLE oder NONE enthalten.';
 CREATE TABLE [#ServerConfiguration_C]([configuration_id] int,[name] nvarchar(128),[minimum] sql_variant,[maximum] sql_variant,[ConfiguredValue] sql_variant,[RunningValue] sql_variant,[is_dynamic] bit,[is_advanced] bit,[Finding] varchar(60),[Interpretation] nvarchar(1000));
 SET LOCK_TIMEOUT 0;BEGIN TRY
  SELECT @Schedulers=[scheduler_count] FROM [sys].[dm_os_sys_info] WITH (NOLOCK);
  INSERT [#ServerConfiguration_C] SELECT [configuration_id],[name],[minimum],[maximum],[value],[value_in_use],[is_dynamic],[is_advanced],
   CASE WHEN [value]<>[value_in_use] THEN'RECONFIGURE_OR_RESTART_PENDING' WHEN [name]='cost threshold for parallelism'AND CONVERT(int,[value_in_use])<=5 THEN'LOW_DEFAULT_REVIEW' WHEN [name]='max server memory (MB)'AND CONVERT(bigint,[value_in_use])>=2147483647 THEN'UNBOUNDED_MEMORY_REVIEW' WHEN [name] IN('xp_cmdshell','Ole Automation Procedures')AND CONVERT(int,[value_in_use])=1 THEN'SECURITY_REVIEW' ELSE'OK_OR_CONTEXT_DEPENDENT'END,
   CASE WHEN [name]='max degree of parallelism'THEN CONCAT(N'0 bedeutet automatische Nutzung bis zur Enginegrenze; gegen NUMA, Scheduleranzahl ',@Schedulers,N', Workload und Parallelism-Waits bewerten.') WHEN [name]='cost threshold for parallelism'THEN N'Der Standardwert 5 ist häufig nur ein Ausgangspunkt; Änderungen ausschließlich workloadbasiert.' WHEN [name]='max server memory (MB)'THEN N'OS-, Agent-, SSIS-/ETL- und sonstige Prozessreserve berücksichtigen.' ELSE N'Kontext-, Sicherheits- und Herstelleranforderungen prüfen; keine automatische Änderung.'END
  FROM [sys].[configurations] WITH (NOLOCK) WHERE @NurKernparameter=0 OR [name] IN('max degree of parallelism','cost threshold for parallelism','max server memory (MB)','min server memory (MB)','optimize for ad hoc workloads','backup compression default','remote admin connections','contained database authentication','clr enabled','clr strict security','xp_cmdshell','Ole Automation Procedures','external scripts enabled','blocked process threshold (s)','query wait (s)','affinity mask','affinity64 mask');
 END TRY BEGIN CATCH SELECT @S=CASE WHEN ERROR_NUMBER()IN(229,297,300,371)THEN'DENIED_PERMISSION'WHEN ERROR_NUMBER()=1222 THEN'TIMEOUT'ELSE'ERROR_HANDLED'END,@P=1,@E=ERROR_NUMBER(),@M=ERROR_MESSAGE();END CATCH;
 SELECT @StatusCodeOut=@S,@IsPartialOut=@P,@ErrorNumberOut=@E,@ErrorMessageOut=@M;IF @PrintMeldungen=1 AND @S<>'AVAILABLE'RAISERROR(N'USP_ServerConfiguration: %s',10,1,@M) WITH NOWAIT;
 IF @ResultSetArtNormalisiert<>'NONE' BEGIN SELECT CAST('2.0' AS varchar(16)) [ContractVersion],@T [CollectionTimeUtc],N'monitor.USP_ServerConfiguration' [ModuleName],@S [StatusCode],@P [IsPartial],@E [ErrorNumber],@M [ErrorMessage];IF @ResultSetArtNormalisiert='RAW' BEGIN SELECT * FROM [#ServerConfiguration_C] ORDER BY [name]; END ELSE BEGIN SELECT N'configuration' [Ergebnis],[x].* FROM [#ServerConfiguration_C] [x] ORDER BY [name]; END;END;
 IF @JsonErzeugen=1 BEGIN DECLARE @Meta nvarchar(max)=(SELECT N'ServerConfiguration' [resultName],1 [schemaVersion],@T [generatedAtUtc],@S [statusCode],@P [isPartial],@E [errorNumber],@M [errorMessage] FOR JSON PATH,WITHOUT_ARRAY_WRAPPER,INCLUDE_NULL_VALUES),@J0 nvarchar(max)=(SELECT [configuration_id],[name],CONVERT(nvarchar(4000),[minimum]) [minimum],CONVERT(nvarchar(4000),[maximum]) [maximum],CONVERT(nvarchar(4000),[ConfiguredValue]) [ConfiguredValue],CONVERT(nvarchar(4000),[RunningValue]) [RunningValue],[is_dynamic],[is_advanced],[Finding],[Interpretation] FROM [#ServerConfiguration_C] ORDER BY [name] FOR JSON PATH,INCLUDE_NULL_VALUES);SET @Json=CONCAT(N'{"meta":',COALESCE(@Meta,N'{}'),N',"configuration":',COALESCE(@J0,N'[]'),N',"warnings":[]}');END;
    IF @ConsoleResultRequested = 1
    BEGIN
        EXEC [monitor].[InternalEmitConsoleResult]
              @SourceTable=N'#ServerConfiguration_C'
            , @ResultLabel=N'ServerConfiguration'
            , @EmptyMessage=N'Keine fachlichen Ergebnisse';
    END;
    IF @TableResultRequested = 1
    BEGIN
        EXEC [monitor].[InternalWriteResultTable]
              @SourceTable = N'#ServerConfiguration_C'
            , @TargetTable=@TableTarget
            , @ThrowOnError = 1;
    END;
END;
GO
-- END SOURCE: Code/08_ServerHealth/050_USP_ServerConfiguration.sql

-- BEGIN SOURCE: Code/08_ServerHealth/060_USP_TraceFlags.sql
/*
===============================================================================
Objekt       : monitor.USP_TraceFlags
Version      : 2.0.0
Stand        : 2026-07-15
Zweck        : Liefert globale und sitzungsbezogene Trace Flags, ohne deren
               Zustand zu ändern.
Datenquellen : DBCC TRACESTATUS
Vertrag      : Resultset 1 ist immer Modulstatus; @ResultSetArt=NONE unterdrückt Resultsets; RAW und CONSOLE liefern unterschiedliche Projektionen. Optional JSON.
===============================================================================
*/

CREATE OR ALTER PROCEDURE [monitor].[USP_TraceFlags]
 @PrintMeldungen bit=1,@Hilfe bit=0,@ResultSetArt varchar(16)='CONSOLE'
    , @ResultTablesJson               nvarchar(max) = NULL
    , @JsonErzeugen bit=0,@Json nvarchar(max)=NULL OUTPUT,
 @StatusCodeOut varchar(40)=NULL OUTPUT,@IsPartialOut bit=NULL OUTPUT,@ErrorNumberOut int=NULL OUTPUT,@ErrorMessageOut nvarchar(2048)=NULL OUTPUT
AS
BEGIN
 SET NOCOUNT ON;SET @Json=NULL;DECLARE @ResultSetArtNormalisiert varchar(16)=UPPER(LTRIM(RTRIM(COALESCE(@ResultSetArt,''))));
    DECLARE @TableResultRequested bit = CASE WHEN @ResultSetArtNormalisiert = 'TABLE' THEN 1 ELSE 0 END;
    DECLARE @ConsoleResultRequested bit = CASE WHEN @ResultSetArtNormalisiert = 'CONSOLE' THEN 1 ELSE 0 END;
    DECLARE @TableTarget sysname=NULL;
    IF @TableResultRequested=0 AND NULLIF(LTRIM(RTRIM(COALESCE(@ResultTablesJson,N''))),N'') IS NOT NULL THROW 51011,N'@ResultTablesJson ist ausschließlich mit @ResultSetArt=TABLE zulässig.',1;
    IF @TableResultRequested=1 EXEC [monitor].[InternalPrepareSingleResultTable] @ResultTablesJson=@ResultTablesJson,@ResultName=N'traceFlags',@TargetTable=@TableTarget OUTPUT,@ThrowOnError=1;
    IF @TableResultRequested = 1 OR @ConsoleResultRequested = 1 SET @ResultSetArtNormalisiert = 'NONE';IF @Hilfe=1 BEGIN PRINT N'monitor.USP_TraceFlags';RETURN;END;
 DECLARE @T datetime2(3)=SYSUTCDATETIME(),@S varchar(40)='AVAILABLE',@P bit=0,@E int=NULL,@M nvarchar(2048)=NULL;
 IF @ResultSetArtNormalisiert NOT IN('RAW','CONSOLE','NONE') SELECT @S='INVALID_PARAMETER',@P=1,@M=N'@ResultSetArt muss CONSOLE, RAW, TABLE oder NONE enthalten.';
 CREATE TABLE [#TraceFlags_X]([TraceFlag] int,[Status] int,[GlobalFlag] int,[SessionFlag] int);
 SET LOCK_TIMEOUT 0;BEGIN TRY INSERT [#TraceFlags_X] EXEC(N'DBCC TRACESTATUS(-1) WITH NO_INFOMSGS;');END TRY BEGIN CATCH SELECT @S=CASE WHEN ERROR_NUMBER()IN(229,297,300,371)THEN'DENIED_PERMISSION'ELSE'ERROR_HANDLED'END,@P=1,@E=ERROR_NUMBER(),@M=ERROR_MESSAGE();END CATCH;
 SELECT @StatusCodeOut=@S,@IsPartialOut=@P,@ErrorNumberOut=@E,@ErrorMessageOut=@M;IF @PrintMeldungen=1 AND @S<>'AVAILABLE'RAISERROR(N'USP_TraceFlags: %s',10,1,@M) WITH NOWAIT;
 IF @ResultSetArtNormalisiert<>'NONE' BEGIN SELECT CAST('2.0' AS varchar(16)) [ContractVersion],@T [CollectionTimeUtc],N'monitor.USP_TraceFlags' [ModuleName],@S [StatusCode],@P [IsPartial],@E [ErrorNumber],@M [ErrorMessage];IF @ResultSetArtNormalisiert='RAW' BEGIN SELECT * FROM [#TraceFlags_X] ORDER BY [TraceFlag]; END ELSE BEGIN SELECT N'traceFlags' [Ergebnis],[x].* FROM [#TraceFlags_X] [x] ORDER BY [TraceFlag]; END;END;
 IF @JsonErzeugen=1 BEGIN DECLARE @Meta nvarchar(max)=(SELECT N'TraceFlags' [resultName],1 [schemaVersion],@T [generatedAtUtc],@S [statusCode],@P [isPartial],@E [errorNumber],@M [errorMessage] FOR JSON PATH,WITHOUT_ARRAY_WRAPPER,INCLUDE_NULL_VALUES),@J0 nvarchar(max)=(SELECT * FROM [#TraceFlags_X] ORDER BY [TraceFlag] FOR JSON PATH,INCLUDE_NULL_VALUES);SET @Json=CONCAT(N'{"meta":',COALESCE(@Meta,N'{}'),N',"traceFlags":',COALESCE(@J0,N'[]'),N',"warnings":[]}');END;
    IF @ConsoleResultRequested = 1
    BEGIN
        EXEC [monitor].[InternalEmitConsoleResult]
              @SourceTable=N'#TraceFlags_X'
            , @ResultLabel=N'TraceFlags'
            , @EmptyMessage=N'Keine fachlichen Ergebnisse';
    END;
    IF @TableResultRequested = 1
    BEGIN
        EXEC [monitor].[InternalWriteResultTable]
              @SourceTable = N'#TraceFlags_X'
            , @TargetTable=@TableTarget
            , @ThrowOnError = 1;
    END;
END;
GO
-- END SOURCE: Code/08_ServerHealth/060_USP_TraceFlags.sql

-- BEGIN SOURCE: Code/08_ServerHealth/070_USP_StartupParameters.sql
/*
===============================================================================
Objekt       : monitor.USP_StartupParameters
Version      : 2.0.0
Stand        : 2026-07-15
Zweck        : Liefert Startparameter und Registry-basierte Dienstparameter
               einschließlich eines Plattformhinweises.
Datenquellen : sys.dm_server_registry
Vertrag      : Resultset 1 ist immer Modulstatus; @ResultSetArt=NONE unterdrückt Resultsets; RAW und CONSOLE liefern unterschiedliche Projektionen. Optional JSON.
===============================================================================
*/

CREATE OR ALTER PROCEDURE [monitor].[USP_StartupParameters]
 @PrintMeldungen bit=1,@Hilfe bit=0,@ResultSetArt varchar(16)='CONSOLE'
    , @ResultTablesJson               nvarchar(max) = NULL
    , @JsonErzeugen bit=0,@Json nvarchar(max)=NULL OUTPUT,
 @StatusCodeOut varchar(40)=NULL OUTPUT,@IsPartialOut bit=NULL OUTPUT,@ErrorNumberOut int=NULL OUTPUT,@ErrorMessageOut nvarchar(2048)=NULL OUTPUT
AS
BEGIN
 SET NOCOUNT ON;SET @Json=NULL;DECLARE @ResultSetArtNormalisiert varchar(16)=UPPER(LTRIM(RTRIM(COALESCE(@ResultSetArt,''))));
    DECLARE @TableResultRequested bit = CASE WHEN @ResultSetArtNormalisiert = 'TABLE' THEN 1 ELSE 0 END;
    DECLARE @ConsoleResultRequested bit = CASE WHEN @ResultSetArtNormalisiert = 'CONSOLE' THEN 1 ELSE 0 END;
    DECLARE @TableTarget sysname=NULL;
    IF @TableResultRequested=0 AND NULLIF(LTRIM(RTRIM(COALESCE(@ResultTablesJson,N''))),N'') IS NOT NULL THROW 51011,N'@ResultTablesJson ist ausschließlich mit @ResultSetArt=TABLE zulässig.',1;
    IF @TableResultRequested=1 EXEC [monitor].[InternalPrepareSingleResultTable] @ResultTablesJson=@ResultTablesJson,@ResultName=N'startupParameters',@TargetTable=@TableTarget OUTPUT,@ThrowOnError=1;
    IF @TableResultRequested = 1 OR @ConsoleResultRequested = 1 SET @ResultSetArtNormalisiert = 'NONE';IF @Hilfe=1 BEGIN PRINT N'monitor.USP_StartupParameters';RETURN;END;
 DECLARE @T datetime2(3)=SYSUTCDATETIME(),@S varchar(40)='AVAILABLE',@P bit=0,@E int=NULL,@M nvarchar(2048)=NULL,@Platform nvarchar(60)=NULL;
 IF @ResultSetArtNormalisiert NOT IN('RAW','CONSOLE','NONE') SELECT @S='INVALID_PARAMETER',@P=1,@M=N'@ResultSetArt muss CONSOLE, RAW, TABLE oder NONE enthalten.';
 CREATE TABLE [#StartupParameters_X]([registry_key] nvarchar(512),[value_name] nvarchar(256),[value_data] nvarchar(2048),[ParameterType] varchar(40));
 BEGIN TRY SELECT TOP(1)@Platform=[host_platform] FROM [sys].[dm_os_host_info] WITH (NOLOCK);END TRY BEGIN CATCH END CATCH;
 IF NOT EXISTS(SELECT 1 FROM [master].[sys].[all_objects] AS [o] WITH (NOLOCK) JOIN [master].[sys].[schemas] AS [s] WITH (NOLOCK) ON [s].[schema_id]=[o].[schema_id] WHERE [s].[name]=N'sys' AND [o].[name]=N'dm_server_registry') SELECT @S=CASE WHEN @Platform=N'Linux'THEN'UNAVAILABLE_PLATFORM'ELSE'UNAVAILABLE_OBJECT'END,@P=1,@M=N'sys.dm_server_registry ist nicht verfügbar; Startparameter können auf dieser Plattform/Version nicht über diese Quelle gelesen werden.';
 ELSE BEGIN SET LOCK_TIMEOUT 0;BEGIN TRY INSERT [#StartupParameters_X] SELECT [registry_key],[value_name],CONVERT(nvarchar(2048),[value_data]),CASE WHEN CONVERT(nvarchar(2048),[value_data])LIKE'-T%'OR CONVERT(nvarchar(2048),[value_data])LIKE'-t%'THEN'TRACE_FLAG'WHEN CONVERT(nvarchar(2048),[value_data])LIKE'-d%'THEN'MASTER_DATA_PATH'WHEN CONVERT(nvarchar(2048),[value_data])LIKE'-l%'THEN'MASTER_LOG_PATH'WHEN CONVERT(nvarchar(2048),[value_data])LIKE'-e%'THEN'ERRORLOG_PATH'ELSE'OTHER'END FROM [sys].[dm_server_registry] WITH (NOLOCK) WHERE [value_name] LIKE'SQLArg%'OR [value_name] IN('ImagePath','ObjectName');END TRY BEGIN CATCH SELECT @S=CASE WHEN ERROR_NUMBER()IN(229,297,300,371)THEN'DENIED_PERMISSION'ELSE'ERROR_HANDLED'END,@P=1,@E=ERROR_NUMBER(),@M=ERROR_MESSAGE();END CATCH;END;
 SELECT @StatusCodeOut=@S,@IsPartialOut=@P,@ErrorNumberOut=@E,@ErrorMessageOut=@M;IF @PrintMeldungen=1 AND @S<>'AVAILABLE'RAISERROR(N'USP_StartupParameters: %s',10,1,@M) WITH NOWAIT;
 IF @ResultSetArtNormalisiert<>'NONE' BEGIN SELECT CAST('2.0' AS varchar(16)) [ContractVersion],@T [CollectionTimeUtc],N'monitor.USP_StartupParameters' [ModuleName],@S [StatusCode],@P [IsPartial],@E [ErrorNumber],@M [ErrorMessage];IF @ResultSetArtNormalisiert='RAW' BEGIN SELECT * FROM [#StartupParameters_X] ORDER BY [registry_key],[value_name]; END ELSE BEGIN SELECT N'startupParameters' [Ergebnis],[x].* FROM [#StartupParameters_X] [x] ORDER BY [registry_key],[value_name]; END;END;
 IF @JsonErzeugen=1 BEGIN DECLARE @Meta nvarchar(max)=(SELECT N'StartupParameters' [resultName],1 [schemaVersion],@T [generatedAtUtc],@S [statusCode],@P [isPartial],@E [errorNumber],@M [errorMessage] FOR JSON PATH,WITHOUT_ARRAY_WRAPPER,INCLUDE_NULL_VALUES),@J0 nvarchar(max)=(SELECT * FROM [#StartupParameters_X] ORDER BY [registry_key],[value_name] FOR JSON PATH,INCLUDE_NULL_VALUES);SET @Json=CONCAT(N'{"meta":',COALESCE(@Meta,N'{}'),N',"startupParameters":',COALESCE(@J0,N'[]'),N',"warnings":[]}');END;
    IF @ConsoleResultRequested = 1
    BEGIN
        EXEC [monitor].[InternalEmitConsoleResult]
              @SourceTable=N'#StartupParameters_X'
            , @ResultLabel=N'StartupParameters'
            , @EmptyMessage=N'Keine fachlichen Ergebnisse';
    END;
    IF @TableResultRequested = 1
    BEGIN
        EXEC [monitor].[InternalWriteResultTable]
              @SourceTable = N'#StartupParameters_X'
            , @TargetTable=@TableTarget
            , @ThrowOnError = 1;
    END;
END;
GO
-- END SOURCE: Code/08_ServerHealth/070_USP_StartupParameters.sql

-- BEGIN SOURCE: Code/08_ServerHealth/080_USP_OSInformation.sql
/*
===============================================================================
Objekt       : monitor.USP_OSInformation
Version      : 2.0.0
Stand        : 2026-07-15
Zweck        : Liefert Host-, Speicher-, Prozess- und Dienstinformationen. Jede
               optionale Quelle besitzt eine eigene Fehlergrenze.
Datenquellen : sys.dm_os_host_info, sys.dm_os_sys_memory, sys.dm_os_process_memory, sys.dm_server_services
Vertrag      : Resultset 1 ist immer Modulstatus; @ResultSetArt=NONE unterdrückt Resultsets; RAW und CONSOLE liefern unterschiedliche Projektionen. Optional JSON.
===============================================================================
*/

CREATE OR ALTER PROCEDURE [monitor].[USP_OSInformation]
 @PrintMeldungen bit=1,@Hilfe bit=0,@ResultSetArt varchar(16)='CONSOLE'
    , @ResultTablesJson               nvarchar(max) = NULL
    , @JsonErzeugen bit=0,@Json nvarchar(max)=NULL OUTPUT,
 @StatusCodeOut varchar(40)=NULL OUTPUT,@IsPartialOut bit=NULL OUTPUT,@ErrorNumberOut int=NULL OUTPUT,@ErrorMessageOut nvarchar(2048)=NULL OUTPUT
AS
BEGIN
 SET NOCOUNT ON;SET @Json=NULL;DECLARE @ResultSetArtNormalisiert varchar(16)=UPPER(LTRIM(RTRIM(COALESCE(@ResultSetArt,''))));
    DECLARE @TableResultRequested bit = CASE WHEN @ResultSetArtNormalisiert = 'TABLE' THEN 1 ELSE 0 END;
    DECLARE @ConsoleResultRequested bit = CASE WHEN @ResultSetArtNormalisiert = 'CONSOLE' THEN 1 ELSE 0 END;
    DECLARE @TableTarget sysname=NULL;
    IF @TableResultRequested=0 AND NULLIF(LTRIM(RTRIM(COALESCE(@ResultTablesJson,N''))),N'') IS NOT NULL THROW 51011,N'@ResultTablesJson ist ausschließlich mit @ResultSetArt=TABLE zulässig.',1;
    IF @TableResultRequested=1 EXEC [monitor].[InternalPrepareSingleResultTable] @ResultTablesJson=@ResultTablesJson,@ResultName=N'host',@TargetTable=@TableTarget OUTPUT,@ThrowOnError=1;
    IF @TableResultRequested = 1 OR @ConsoleResultRequested = 1 SET @ResultSetArtNormalisiert = 'NONE';
    DECLARE @MonitorPrintMessage nvarchar(2048);IF @Hilfe=1 BEGIN PRINT N'monitor.USP_OSInformation';RETURN;END;
 DECLARE @T datetime2(3)=SYSUTCDATETIME(),@S varchar(40)='AVAILABLE',@P bit=0,@E int=NULL,@M nvarchar(2048)=NULL;
 IF @ResultSetArtNormalisiert NOT IN('RAW','CONSOLE','NONE') SELECT @S='INVALID_PARAMETER',@P=1,@M=N'@ResultSetArt muss CONSOLE, RAW, TABLE oder NONE enthalten.';
 CREATE TABLE [#OSInformation_Src]([SourceName] sysname,[StatusCode] varchar(40),[ErrorNumber] int NULL,[ErrorMessage] nvarchar(2048)NULL);
 CREATE TABLE [#OSInformation_H]([host_platform] nvarchar(60),[host_distribution] nvarchar(256),[host_release] nvarchar(256),[host_service_pack_level] nvarchar(256),[host_sku] int,[os_language_version] int);
 CREATE TABLE [#OSInformation_SM]([total_physical_memory_kb] bigint,[available_physical_memory_kb] bigint,[total_page_file_kb] bigint,[available_page_file_kb] bigint,[system_memory_state_desc] nvarchar(256));
 CREATE TABLE [#OSInformation_PM]([physical_memory_in_use_kb] bigint,[locked_page_allocations_kb] bigint,[large_page_allocations_kb] bigint,[process_physical_memory_low] bit,[process_virtual_memory_low] bit);
 CREATE TABLE [#OSInformation_Svc]([servicename] nvarchar(256),[startup_type_desc] nvarchar(60),[status_desc] nvarchar(60),[process_id] int,[last_startup_time] datetime2 NULL,[service_account] nvarchar(256),[instant_file_initialization_enabled] nvarchar(10));
 SET LOCK_TIMEOUT 0;
 BEGIN TRY INSERT [#OSInformation_H] SELECT [host_platform],[host_distribution],[host_release],[host_service_pack_level],[host_sku],[os_language_version] FROM [sys].[dm_os_host_info] WITH (NOLOCK);INSERT [#OSInformation_Src] VALUES(N'sys.dm_os_host_info','AVAILABLE',NULL,NULL);END TRY BEGIN CATCH INSERT [#OSInformation_Src] VALUES(N'sys.dm_os_host_info',CASE WHEN ERROR_NUMBER()IN(229,297,300,371)THEN'DENIED_PERMISSION'ELSE'ERROR_HANDLED'END,ERROR_NUMBER(),ERROR_MESSAGE());END CATCH;
 BEGIN TRY INSERT [#OSInformation_SM] SELECT [total_physical_memory_kb],[available_physical_memory_kb],[total_page_file_kb],[available_page_file_kb],[system_memory_state_desc] FROM [sys].[dm_os_sys_memory] WITH (NOLOCK);INSERT [#OSInformation_Src] VALUES(N'sys.dm_os_sys_memory','AVAILABLE',NULL,NULL);END TRY BEGIN CATCH INSERT [#OSInformation_Src] VALUES(N'sys.dm_os_sys_memory',CASE WHEN ERROR_NUMBER()IN(229,297,300,371)THEN'DENIED_PERMISSION'ELSE'ERROR_HANDLED'END,ERROR_NUMBER(),ERROR_MESSAGE());END CATCH;
 BEGIN TRY INSERT [#OSInformation_PM] SELECT [physical_memory_in_use_kb],[locked_page_allocations_kb],[large_page_allocations_kb],[process_physical_memory_low],[process_virtual_memory_low] FROM [sys].[dm_os_process_memory] WITH (NOLOCK);INSERT [#OSInformation_Src] VALUES(N'sys.dm_os_process_memory','AVAILABLE',NULL,NULL);END TRY BEGIN CATCH INSERT [#OSInformation_Src] VALUES(N'sys.dm_os_process_memory',CASE WHEN ERROR_NUMBER()IN(229,297,300,371)THEN'DENIED_PERMISSION'ELSE'ERROR_HANDLED'END,ERROR_NUMBER(),ERROR_MESSAGE());END CATCH;
 BEGIN TRY INSERT [#OSInformation_Svc] SELECT [servicename],[startup_type_desc],[status_desc],[process_id],[last_startup_time],[service_account],CONVERT(nvarchar(10),[instant_file_initialization_enabled])FROM [sys].[dm_server_services] WITH (NOLOCK);INSERT [#OSInformation_Src] VALUES(N'sys.dm_server_services','AVAILABLE',NULL,NULL);END TRY BEGIN CATCH INSERT [#OSInformation_Src] VALUES(N'sys.dm_server_services',CASE WHEN ERROR_NUMBER()IN(229,297,300,371)THEN'DENIED_PERMISSION'ELSE'ERROR_HANDLED'END,ERROR_NUMBER(),ERROR_MESSAGE());END CATCH;

 IF EXISTS(SELECT 1 FROM [#OSInformation_Src] WHERE [StatusCode]<>'AVAILABLE') SELECT @P=1,@S=CASE WHEN EXISTS(SELECT 1 FROM [#OSInformation_Src] WHERE [StatusCode]='AVAILABLE')THEN'PARTIAL'ELSE(SELECT TOP(1)[StatusCode] FROM [#OSInformation_Src] WHERE [StatusCode]<>'AVAILABLE')END,@E=(SELECT TOP(1)[ErrorNumber] FROM [#OSInformation_Src] WHERE [StatusCode]<>'AVAILABLE'),@M=(SELECT TOP(1)[ErrorMessage] FROM [#OSInformation_Src] WHERE [StatusCode]<>'AVAILABLE');
 SELECT @StatusCodeOut=@S,@IsPartialOut=@P,@ErrorNumberOut=@E,@ErrorMessageOut=@M;IF @PrintMeldungen=1 AND @S<>'AVAILABLE'BEGIN
    SET @MonitorPrintMessage = FORMATMESSAGE(N'USP_OSInformation: %s', COALESCE(@M,N'eine Quelle nicht verfügbar'));
    RAISERROR(N'%s', 10, 1, @MonitorPrintMessage) WITH NOWAIT;
END;
 IF @ResultSetArtNormalisiert<>'NONE' BEGIN SELECT CAST('2.0' AS varchar(16)) [ContractVersion],@T [CollectionTimeUtc],N'monitor.USP_OSInformation' [ModuleName],@S [StatusCode],@P [IsPartial],@E [ErrorNumber],@M [ErrorMessage];IF @ResultSetArtNormalisiert='RAW' BEGIN SELECT * FROM [#OSInformation_Src] ORDER BY [SourceName];SELECT * FROM [#OSInformation_H] ;SELECT * FROM [#OSInformation_SM] ;SELECT * FROM [#OSInformation_PM] ;SELECT * FROM [#OSInformation_Svc] ORDER BY [servicename]; END ELSE BEGIN SELECT N'sources' [Ergebnis],[x].* FROM [#OSInformation_Src] [x] ORDER BY [SourceName];SELECT N'host' [Ergebnis],[x].* FROM [#OSInformation_H] [x] ;SELECT N'systemMemory' [Ergebnis],[x].* FROM [#OSInformation_SM] [x] ;SELECT N'processMemory' [Ergebnis],[x].* FROM [#OSInformation_PM] [x] ;SELECT N'services' [Ergebnis],[x].* FROM [#OSInformation_Svc] [x] ORDER BY [servicename]; END;END;
 IF @JsonErzeugen=1 BEGIN DECLARE @Meta nvarchar(max)=(SELECT N'OSInformation' [resultName],1 [schemaVersion],@T [generatedAtUtc],@S [statusCode],@P [isPartial],@E [errorNumber],@M [errorMessage] FOR JSON PATH,WITHOUT_ARRAY_WRAPPER,INCLUDE_NULL_VALUES),@J0 nvarchar(max)=(SELECT * FROM [#OSInformation_Src] ORDER BY [SourceName] FOR JSON PATH,INCLUDE_NULL_VALUES),@J1 nvarchar(max)=(SELECT * FROM [#OSInformation_H]  FOR JSON PATH,INCLUDE_NULL_VALUES),@J2 nvarchar(max)=(SELECT * FROM [#OSInformation_SM]  FOR JSON PATH,INCLUDE_NULL_VALUES),@J3 nvarchar(max)=(SELECT * FROM [#OSInformation_PM]  FOR JSON PATH,INCLUDE_NULL_VALUES),@J4 nvarchar(max)=(SELECT * FROM [#OSInformation_Svc] ORDER BY [servicename] FOR JSON PATH,INCLUDE_NULL_VALUES);SET @Json=CONCAT(N'{"meta":',COALESCE(@Meta,N'{}'),N',"sources":',COALESCE(@J0,N'[]'),N',"host":',COALESCE(@J1,N'[]'),N',"systemMemory":',COALESCE(@J2,N'[]'),N',"processMemory":',COALESCE(@J3,N'[]'),N',"services":',COALESCE(@J4,N'[]'),N',"warnings":[]}');END;
    IF @ConsoleResultRequested = 1
    BEGIN
        EXEC [monitor].[InternalEmitConsoleResult]
              @SourceTable=N'#OSInformation_H'
            , @ResultLabel=N'OSInformation'
            , @EmptyMessage=N'Keine fachlichen Ergebnisse';
    END;
    IF @TableResultRequested = 1
    BEGIN
        EXEC [monitor].[InternalWriteResultTable]
              @SourceTable = N'#OSInformation_H'
            , @TargetTable=@TableTarget
            , @ThrowOnError = 1;
    END;
END;
GO
-- END SOURCE: Code/08_ServerHealth/080_USP_OSInformation.sql

-- BEGIN SOURCE: Code/08_ServerHealth/090_USP_ServerSecurityConfiguration.sql
/*
===============================================================================
Objekt       : monitor.USP_ServerSecurityConfiguration
Version      : 2.0.1
Stand        : 2026-07-15
Zweck        : Liest die Sicherheits- und Dienstkonfiguration, ohne sie zu
               verändern.
Datenquellen : sys.configurations, sys.dm_server_services, SERVERPROPERTY
Vertrag      : Resultset 1 ist immer Modulstatus; @ResultSetArt=NONE unterdrückt
               Resultsets und liefert Status ausschließlich über OUTPUT-Parameter.
===============================================================================
*/

CREATE OR ALTER PROCEDURE [monitor].[USP_ServerSecurityConfiguration]
    @PrintMeldungen  bit = 1,
    @Hilfe           bit = 0,
    @ResultSetArt    varchar(16) = 'CONSOLE'
    , @ResultTablesJson               nvarchar(max) = NULL
    , @JsonErzeugen    bit = 0,
    @Json             nvarchar(max) = NULL OUTPUT,
    @StatusCodeOut   varchar(40) = NULL OUTPUT,
    @IsPartialOut    bit = NULL OUTPUT,
    @ErrorNumberOut  int = NULL OUTPUT,
    @ErrorMessageOut nvarchar(2048) = NULL OUTPUT
AS
BEGIN
    SET NOCOUNT ON;SET @Json=NULL;DECLARE @ResultSetArtNormalisiert varchar(16)=UPPER(LTRIM(RTRIM(COALESCE(@ResultSetArt,''))));
    DECLARE @TableResultRequested bit = CASE WHEN @ResultSetArtNormalisiert = 'TABLE' THEN 1 ELSE 0 END;
    DECLARE @ConsoleResultRequested bit = CASE WHEN @ResultSetArtNormalisiert = 'CONSOLE' THEN 1 ELSE 0 END;
    DECLARE @TableTarget sysname=NULL;
    IF @TableResultRequested=0 AND NULLIF(LTRIM(RTRIM(COALESCE(@ResultTablesJson,N''))),N'') IS NOT NULL THROW 51011,N'@ResultTablesJson ist ausschließlich mit @ResultSetArt=TABLE zulässig.',1;
    IF @TableResultRequested=1 EXEC [monitor].[InternalPrepareSingleResultTable] @ResultTablesJson=@ResultTablesJson,@ResultName=N'configuration',@TargetTable=@TableTarget OUTPUT,@ThrowOnError=1;
    IF @TableResultRequested = 1 OR @ConsoleResultRequested = 1 SET @ResultSetArtNormalisiert = 'NONE';
    DECLARE @MonitorPrintMessage nvarchar(2048);

    IF @Hilfe = 1
    BEGIN
        PRINT N'monitor.USP_ServerSecurityConfiguration';
        RETURN;
    END;

    DECLARE
        @CollectionTimeUtc datetime2(3) = SYSUTCDATETIME(),
        @StatusCode        varchar(40) = 'AVAILABLE',
        @IsPartial         bit = 0,
        @ErrorNumber       int = NULL,
        @ErrorMessage      nvarchar(2048) = NULL;

    IF @ResultSetArtNormalisiert NOT IN('RAW','CONSOLE','NONE') BEGIN SET @StatusCode='INVALID_PARAMETER';SET @IsPartial=1;SET @ErrorMessage=N'@ResultSetArt muss CONSOLE, RAW, TABLE oder NONE enthalten.';END;

    CREATE TABLE [#ServerSecurityConfiguration_SourceStatus]
    (
        [SourceName]   sysname        NOT NULL,
        [StatusCode]   varchar(40)    NOT NULL,
        [ErrorNumber]  int            NULL,
        [ErrorMessage] nvarchar(2048) NULL
    );

    CREATE TABLE [#ServerSecurityConfiguration_Configuration]
    (
        [ConfigurationName] nvarchar(128) NOT NULL,
        [ConfiguredValue]   sql_variant   NULL,
        [RunningValue]      sql_variant   NULL,
        [Finding]           varchar(60)   NOT NULL
    );

    CREATE TABLE [#ServerSecurityConfiguration_Services]
    (
        [ServiceName]                      nvarchar(256) NULL,
        [ServiceAccount]                   nvarchar(256) NULL,
        [StartupTypeDescription]           nvarchar(60)  NULL,
        [StatusDescription]                nvarchar(60)  NULL,
        [InstantFileInitializationEnabled] nvarchar(10)  NULL,
        [InstantFileInitializationFinding] varchar(40)   NOT NULL
    );

    CREATE TABLE [#ServerSecurityConfiguration_Properties]
    (
        [MachineName]                 sysname       NULL,
        [ServerName]                  sysname       NULL,
        [Edition]                     nvarchar(128) NULL,
        [IsWindowsAuthenticationOnly] int           NULL,
        [CallerIsSysadmin]            int           NULL
    );

    SET LOCK_TIMEOUT 0;

    BEGIN TRY
        INSERT [#ServerSecurityConfiguration_Configuration]
        (
            [ConfigurationName],
            [ConfiguredValue],
            [RunningValue],
            [Finding]
        )
        SELECT
            [c].[name],
            [c].[value],
            [c].[value_in_use],
            CASE
                WHEN [c].[name] = N'xp_cmdshell'
                     AND CONVERT(int, [c].[value_in_use]) = 1
                    THEN 'XPCMDSHELL_ENABLED'
                WHEN [c].[name] = N'Ole Automation Procedures'
                     AND CONVERT(int, [c].[value_in_use]) = 1
                    THEN 'OLE_AUTOMATION_ENABLED'
                WHEN [c].[name] = N'clr strict security'
                     AND CONVERT(int, [c].[value_in_use]) = 0
                    THEN 'CLR_STRICT_SECURITY_OFF'
                WHEN [c].[name] = N'external scripts enabled'
                     AND CONVERT(int, [c].[value_in_use]) = 1
                    THEN 'EXTERNAL_SCRIPTS_ENABLED'
                ELSE 'OK_OR_CONTEXT_DEPENDENT'
            END
        FROM [sys].[configurations] AS c WITH (NOLOCK)
        WHERE [c].[name] IN
        (
            N'xp_cmdshell',
            N'Ole Automation Procedures',
            N'clr enabled',
            N'clr strict security',
            N'external scripts enabled',
            N'remote admin connections',
            N'contained database authentication'
        );

        INSERT [#ServerSecurityConfiguration_SourceStatus] VALUES
            (N'sys.configurations', 'AVAILABLE', NULL, NULL);
    END TRY
    BEGIN CATCH
        INSERT [#ServerSecurityConfiguration_SourceStatus] VALUES
        (
            N'sys.configurations',
            CASE
                WHEN ERROR_NUMBER() IN (229, 297, 300, 371) THEN 'DENIED_PERMISSION'
                WHEN ERROR_NUMBER() = 1222 THEN 'TIMEOUT'
                ELSE 'ERROR_HANDLED'
            END,
            ERROR_NUMBER(),
            ERROR_MESSAGE()
        );
    END CATCH;

    BEGIN TRY
        INSERT [#ServerSecurityConfiguration_Services]
        (
            [ServiceName],
            [ServiceAccount],
            [StartupTypeDescription],
            [StatusDescription],
            [InstantFileInitializationEnabled],
            [InstantFileInitializationFinding]
        )
        SELECT
            [s].[servicename],
            [s].[service_account],
            [s].[startup_type_desc],
            [s].[status_desc],
            CONVERT(nvarchar(10), [s].[instant_file_initialization_enabled]),
            CASE
                WHEN CONVERT(nvarchar(10), [s].[instant_file_initialization_enabled]) = N'Y'
                    THEN 'IFI_ENABLED'
                ELSE 'IFI_NOT_CONFIRMED'
            END
        FROM [sys].[dm_server_services] AS s WITH (NOLOCK);

        INSERT [#ServerSecurityConfiguration_SourceStatus] VALUES
            (N'sys.dm_server_services', 'AVAILABLE', NULL, NULL);
    END TRY
    BEGIN CATCH
        INSERT [#ServerSecurityConfiguration_SourceStatus] VALUES
        (
            N'sys.dm_server_services',
            CASE
                WHEN ERROR_NUMBER() IN (229, 297, 300, 371) THEN 'DENIED_PERMISSION'
                WHEN ERROR_NUMBER() = 1222 THEN 'TIMEOUT'
                ELSE 'ERROR_HANDLED'
            END,
            ERROR_NUMBER(),
            ERROR_MESSAGE()
        );
    END CATCH;

    BEGIN TRY
        INSERT [#ServerSecurityConfiguration_Properties]
        (
            [MachineName],
            [ServerName],
            [Edition],
            [IsWindowsAuthenticationOnly],
            [CallerIsSysadmin]
        )
        SELECT
            CONVERT(sysname, SERVERPROPERTY(N'MachineName')),
            CONVERT(sysname, SERVERPROPERTY(N'ServerName')),
            CONVERT(nvarchar(128), SERVERPROPERTY(N'Edition')),
            CONVERT(int, SERVERPROPERTY(N'IsIntegratedSecurityOnly')),
            CONVERT(int, IS_SRVROLEMEMBER(N'sysadmin'));

        INSERT [#ServerSecurityConfiguration_SourceStatus] VALUES
            (N'SERVERPROPERTY', 'AVAILABLE', NULL, NULL);
    END TRY
    BEGIN CATCH
        INSERT [#ServerSecurityConfiguration_SourceStatus] VALUES
        (
            N'SERVERPROPERTY',
            'ERROR_HANDLED',
            ERROR_NUMBER(),
            ERROR_MESSAGE()
        );
    END CATCH;



    IF EXISTS
    (
        SELECT 1
        FROM [#ServerSecurityConfiguration_SourceStatus] AS s
        WHERE [s].[StatusCode] <> 'AVAILABLE'
    )
    BEGIN
        SELECT
            @IsPartial = 1,
            @StatusCode = CASE
                WHEN EXISTS
                (
                    SELECT 1
                    FROM [#ServerSecurityConfiguration_SourceStatus] AS s
                    WHERE [s].[StatusCode] = 'AVAILABLE'
                )
                    THEN 'PARTIAL'
                ELSE
                (
                    SELECT TOP (1) [s].[StatusCode]
                    FROM [#ServerSecurityConfiguration_SourceStatus] AS s
                    WHERE [s].[StatusCode] <> 'AVAILABLE'
                    ORDER BY [s].[SourceName]
                )
            END,
            @ErrorNumber =
            (
                SELECT TOP (1) [s].[ErrorNumber]
                FROM [#ServerSecurityConfiguration_SourceStatus] AS s
                WHERE [s].[StatusCode] <> 'AVAILABLE'
                ORDER BY [s].[SourceName]
            ),
            @ErrorMessage =
            (
                SELECT TOP (1) [s].[ErrorMessage]
                FROM [#ServerSecurityConfiguration_SourceStatus] AS s
                WHERE [s].[StatusCode] <> 'AVAILABLE'
                ORDER BY [s].[SourceName]
            );
    END;

    SELECT
        @StatusCodeOut = @StatusCode,
        @IsPartialOut = @IsPartial,
        @ErrorNumberOut = @ErrorNumber,
        @ErrorMessageOut = @ErrorMessage;

    IF @PrintMeldungen = 1
       AND @StatusCode <> 'AVAILABLE'
    BEGIN
        BEGIN
    SET @MonitorPrintMessage = FORMATMESSAGE(N'USP_ServerSecurityConfiguration: %s', COALESCE(@ErrorMessage, N'eine Quelle ist nicht verfügbar'));
    RAISERROR(N'%s', 10, 1, @MonitorPrintMessage) WITH NOWAIT;
END;
    END;

    IF @ResultSetArtNormalisiert<>'NONE'
    BEGIN
      SELECT CAST('2.0' AS varchar(16)) [ContractVersion],@CollectionTimeUtc [CollectionTimeUtc],N'monitor.USP_ServerSecurityConfiguration' [ModuleName],@StatusCode [StatusCode],@IsPartial [IsPartial],@ErrorNumber [ErrorNumber],@ErrorMessage [ErrorMessage];
      IF @ResultSetArtNormalisiert='RAW' BEGIN SELECT * FROM [#ServerSecurityConfiguration_SourceStatus] ORDER BY [SourceName];SELECT * FROM [#ServerSecurityConfiguration_Configuration] ORDER BY [ConfigurationName];SELECT * FROM [#ServerSecurityConfiguration_Services] ORDER BY [ServiceName];SELECT * FROM [#ServerSecurityConfiguration_Properties];END
      ELSE BEGIN SELECT N'Sicherheitsquelle' [Ergebnis],[x].* FROM [#ServerSecurityConfiguration_SourceStatus] [x] ORDER BY [SourceName];SELECT N'Sicherheitskonfiguration' [Ergebnis],[ConfigurationName] [Einstellung],CONVERT(nvarchar(4000),[ConfiguredValue]) [konfiguriert],CONVERT(nvarchar(4000),[RunningValue]) [aktiv],[Finding] [Bewertung] FROM [#ServerSecurityConfiguration_Configuration] ORDER BY [ConfigurationName];SELECT N'SQL-Dienst' [Ergebnis],[x].* FROM [#ServerSecurityConfiguration_Services] [x] ORDER BY [ServiceName];SELECT N'Server-Eigenschaft' [Ergebnis],[x].* FROM [#ServerSecurityConfiguration_Properties] [x];END;
    END;
    IF @JsonErzeugen=1 BEGIN DECLARE @Meta nvarchar(max)=(SELECT N'ServerSecurityConfiguration' [resultName],1 [schemaVersion],@CollectionTimeUtc [generatedAtUtc],@StatusCode [statusCode],@IsPartial [isPartial],@ErrorNumber [errorNumber],@ErrorMessage [errorMessage] FOR JSON PATH,WITHOUT_ARRAY_WRAPPER,INCLUDE_NULL_VALUES),@Sources nvarchar(max)=(SELECT * FROM [#ServerSecurityConfiguration_SourceStatus] ORDER BY [SourceName] FOR JSON PATH,INCLUDE_NULL_VALUES),@Cfg nvarchar(max)=(SELECT [ConfigurationName],CONVERT(nvarchar(4000),[ConfiguredValue]) [ConfiguredValue],CONVERT(nvarchar(4000),[RunningValue]) [RunningValue],[Finding] FROM [#ServerSecurityConfiguration_Configuration] ORDER BY [ConfigurationName] FOR JSON PATH,INCLUDE_NULL_VALUES),@Services nvarchar(max)=(SELECT * FROM [#ServerSecurityConfiguration_Services] ORDER BY [ServiceName] FOR JSON PATH,INCLUDE_NULL_VALUES),@Props nvarchar(max)=(SELECT * FROM [#ServerSecurityConfiguration_Properties] FOR JSON PATH,INCLUDE_NULL_VALUES);SET @Json=CONCAT(N'{"meta":',COALESCE(@Meta,N'{}'),N',"sources":',COALESCE(@Sources,N'[]'),N',"configuration":',COALESCE(@Cfg,N'[]'),N',"services":',COALESCE(@Services,N'[]'),N',"properties":',COALESCE(@Props,N'[]'),N',"warnings":[]}');END;
    IF @ConsoleResultRequested = 1
    BEGIN
        EXEC [monitor].[InternalEmitConsoleResult]
              @SourceTable=N'#ServerSecurityConfiguration_Configuration'
            , @ResultLabel=N'ServerSecurityConfiguration'
            , @EmptyMessage=N'Keine fachlichen Ergebnisse';
    END;
    IF @TableResultRequested = 1
    BEGIN
        EXEC [monitor].[InternalWriteResultTable]
              @SourceTable = N'#ServerSecurityConfiguration_Configuration'
            , @TargetTable=@TableTarget
            , @ThrowOnError = 1;
    END;
END;
GO
-- END SOURCE: Code/08_ServerHealth/090_USP_ServerSecurityConfiguration.sql

-- BEGIN SOURCE: Code/08_ServerHealth/110_USP_DatabaseIntegrityAnalysis.sql
/*
===============================================================================
Objekt       : monitor.USP_DatabaseIntegrityAnalysis
Version      : 1.0.2
Stand        : 2026-07-18
Zweck        : Liefert korrelierte, rein lesende Integritätsevidenz je
               Datenbank.
Datenquellen : master.sys.databases, DATABASEPROPERTYEX,
               msdb.dbo.suspect_pages, msdb.dbo.backupset,
               sys.dm_hadr_auto_page_repair und optional sys.dm_db_page_info.
Grenzen      : Leere Indikatoren beweisen keine Integrität. Die Procedure führt
               weder DBCC CHECKDB noch Restore, Reparatur oder Konfiguration aus.
Kosten       : Metadaten LOW; gezielte Seitenauflösung MEDIUM und opt-in.
===============================================================================
*/
CREATE OR ALTER PROCEDURE [monitor].[USP_DatabaseIntegrityAnalysis]
      @DatabaseNames                nvarchar(max)  = NULL
    , @SystemdatenbankenEinbeziehen bit            = 0
    , @DatabaseNamePattern          nvarchar(4000) = NULL
    , @HighImpactConfirmed              bit            = 0
    , @CheckdbWarnHours             int            = 168
    , @BackupHistoryDays            int            = 35
    , @MitPageDetails               bit            = 0
    , @MaxZeilen                    int            = 1000
    , @ResultSetArt                 varchar(16)    = 'CONSOLE'
    , @ResultTablesJson               nvarchar(max) = NULL
    , @JsonErzeugen                 bit            = 0
    , @Json                         nvarchar(max)  = NULL OUTPUT
    , @PrintMeldungen               bit            = 1
    , @Hilfe                        bit            = 0
    , @StatusCodeOut                varchar(40)    = NULL OUTPUT
    , @IsPartialOut                 bit            = NULL OUTPUT
    , @ErrorNumberOut               int            = NULL OUTPUT
    , @ErrorMessageOut              nvarchar(2048) = NULL OUTPUT
AS
BEGIN
    SET NOCOUNT ON;
    SET @Json = NULL;

    DECLARE @OutputMode varchar(16) =
        UPPER(LTRIM(RTRIM(COALESCE(@ResultSetArt, ''))));
    DECLARE @TableResultRequested bit = CASE WHEN @OutputMode = 'TABLE' THEN 1 ELSE 0 END;
    DECLARE @ConsoleResultRequested bit = CASE WHEN @OutputMode = 'CONSOLE' THEN 1 ELSE 0 END;
    DECLARE @TableTarget sysname=NULL;
    IF @TableResultRequested=0 AND NULLIF(LTRIM(RTRIM(COALESCE(@ResultTablesJson,N''))),N'') IS NOT NULL THROW 51011,N'@ResultTablesJson ist ausschließlich mit @ResultSetArt=TABLE zulässig.',1;
    IF @TableResultRequested=1 EXEC [monitor].[InternalPrepareSingleResultTable] @ResultTablesJson=@ResultTablesJson,@ResultName=N'integrity',@TargetTable=@TableTarget OUTPUT,@ThrowOnError=1;
    IF @TableResultRequested = 1 OR @ConsoleResultRequested = 1 SET @OutputMode = 'NONE';
    DECLARE @Limit bigint =
        CASE WHEN @MaxZeilen IS NULL OR @MaxZeilen = 0
             THEN CONVERT(bigint, 9223372036854775807)
             ELSE CONVERT(bigint, @MaxZeilen) END;

    IF @Hilfe = 1
    BEGIN
        PRINT N'monitor.USP_DatabaseIntegrityAnalysis';
        PRINT N'Die Procedure liefert rein lesende Evidenz und führt weder DBCC CHECKDB noch Restore oder Reparatur aus.';
        PRINT N'@DatabaseNames: bracket-aware Pipe-Liste; N''''/NULL = keine Datenbankeinschränkung.';
        PRINT N'@CheckdbWarnHours=168; @MitPageDetails=0 löst verdächtige Seiten nicht auf.';
        PRINT N'@BackupHistoryDays=35 begrenzt die Backupmetadaten-Evidenz.';
        PRINT N'@MaxZeilen positiv; NULL/0 = unbegrenzt. @ResultSetArt=CONSOLE|RAW|TABLE|NONE; TABLE verwendet @ResultTablesJson.';
        RETURN;
    END;

    DECLARE @Now datetime2(3) = SYSUTCDATETIME();
    DECLARE @StatusCode varchar(40) = 'AVAILABLE';
    DECLARE @IsPartial bit = 0;
    DECLARE @ErrorNumber int = NULL;
    DECLARE @ErrorMessage nvarchar(2048) = NULL;
    DECLARE @MonitorPrintMessage nvarchar(2048) = NULL;
    DECLARE @CrossDatabaseRequested bit = 0;
    DECLARE @RequiredServerPermission sysname =
        CASE WHEN TRY_CONVERT(int, SERVERPROPERTY(N'ProductMajorVersion')) >= 16
             THEN N'VIEW SERVER PERFORMANCE STATE' ELSE N'VIEW SERVER STATE' END;
    DECLARE @HasRequiredServerPermission bit =
        CASE WHEN IS_SRVROLEMEMBER(N'sysadmin') = 1 THEN 1
             ELSE COALESCE(HAS_PERMS_BY_NAME(NULL, N'SERVER', @RequiredServerPermission), 0) END;

    CREATE TABLE [#DatabaseIntegrityAnalysis_DatabaseCandidates]
    (
          [DatabaseId] int NOT NULL PRIMARY KEY
        , [DatabaseName] sysname NOT NULL
        , [StateDesc] nvarchar(60) NULL
        , [UserAccessDesc] nvarchar(60) NULL
        , [IsReadOnly] bit NULL
        , [CompatibilityLevel] tinyint NULL
        , [CollationName] sysname NULL
        , [RecoveryModelDesc] nvarchar(60) NULL
        , [IsSystemDatabase] bit NULL
        , [RequestedOrdinal] int NULL
    );

    CREATE TABLE [#DatabaseIntegrityAnalysis_DatabaseCandidateWarnings]
    (
          [RequestedName] sysname NULL
        , [StatusCode] varchar(40) NOT NULL
        , [ErrorMessage] nvarchar(2048) NULL
    );

    CREATE TABLE [#DatabaseIntegrityAnalysis_Suspect]
    (
          [DatabaseId] int NOT NULL
        , [FileId] int NOT NULL
        , [PageId] bigint NOT NULL
        , [EventType] int NOT NULL
        , [ErrorCount] int NULL
        , [LastUpdateDate] datetime NULL
    );

    CREATE TABLE [#DatabaseIntegrityAnalysis_HadrRepair]
    (
          [DatabaseId] int NOT NULL
        , [FileId] int NOT NULL
        , [PageId] bigint NOT NULL
        , [ErrorType] int NULL
        , [PageStatus] int NULL
        , [ModificationTime] datetime NULL
    );

    CREATE TABLE [#DatabaseIntegrityAnalysis_Integrity]
    (
          [DatabaseId] int NOT NULL
        , [DatabaseName] sysname NOT NULL
        , [StateDesc] nvarchar(60) NULL
        , [PageVerifyOptionDesc] nvarchar(60) NULL
        , [LastGoodCheckDbTime] datetime2(3) NULL
        , [CheckdbAgeHours] bigint NULL
        , [SuspectPageCount] bigint NOT NULL
        , [LatestSuspectPageUtc] datetime NULL
        , [DamagedBackupCount] bigint NOT NULL
        , [BackupWithoutChecksumCount] bigint NOT NULL
        , [HadrPageRepairCount] bigint NOT NULL
        , [HadrPageRepairPendingCount] bigint NOT NULL
        , [FindingCode] varchar(80) NOT NULL
        , [EvidenceLimit] nvarchar(1000) NOT NULL
    );

    CREATE TABLE [#DatabaseIntegrityAnalysis_PageDetails]
    (
          [DatabaseName] sysname NULL
        , [FileId] int NULL
        , [PageId] bigint NULL
        , [EventType] int NULL
        , [LastUpdateDate] datetime NULL
        , [ObjectId] int NULL
        , [IndexId] int NULL
        , [PartitionId] bigint NULL
        , [PageTypeDesc] nvarchar(64) NULL
        , [AllocUnitId] bigint NULL
    );

    IF @CheckdbWarnHours < 1
       OR @BackupHistoryDays < 1
       OR @BackupHistoryDays > 3650
       OR @MaxZeilen < 0
       OR @OutputMode NOT IN ('RAW', 'CONSOLE', 'NONE')
    BEGIN
        SELECT @StatusCode = 'INVALID_PARAMETER',
               @IsPartial = 1,
               @ErrorMessage = N'Ungültige Datenbank-, Zeit-, Zeilen- oder Ausgabeparameter.';
    END;

    IF @StatusCode = 'AVAILABLE'
       AND @HasRequiredServerPermission = 0
    BEGIN
        SELECT @IsPartial = 1,
               @ErrorMessage = CONCAT(N'Für vollständige serverweite Integritätsevidenz fehlt ',
                                      @RequiredServerPermission, N'.');
    END;

    IF @StatusCode = 'AVAILABLE'
    BEGIN
        EXEC [monitor].[USP_PrepareDatabaseCandidates]
              @DatabaseNames = @DatabaseNames
            , @SystemdatenbankenEinbeziehen = @SystemdatenbankenEinbeziehen
            , @DatabaseNamePattern = @DatabaseNamePattern,@HighImpactConfirmed=@HighImpactConfirmed

            , @AnalysisClass = 'HA_DR_CURRENT'
            , @StatusCode = @StatusCode OUTPUT
            , @ErrorMessage = @ErrorMessage OUTPUT
            , @CrossDatabaseRequested = @CrossDatabaseRequested OUTPUT,@CandidateTable=N'#DatabaseIntegrityAnalysis_DatabaseCandidates',@WarningTable=N'#DatabaseIntegrityAnalysis_DatabaseCandidateWarnings';
    END;

    SET LOCK_TIMEOUT 0;

    IF @StatusCode = 'AVAILABLE'
    BEGIN
        BEGIN TRY
            INSERT [#DatabaseIntegrityAnalysis_Suspect]
            (
                  [DatabaseId], [FileId], [PageId], [EventType]
                , [ErrorCount], [LastUpdateDate]
            )
            SELECT
                  [sp].[database_id], [sp].[file_id], [sp].[page_id]
                , [sp].[event_type], [sp].[error_count], [sp].[last_update_date]
            FROM [msdb].[dbo].[suspect_pages] AS [sp] WITH (NOLOCK)
            JOIN [#DatabaseIntegrityAnalysis_DatabaseCandidates] AS [c]
              ON [c].[DatabaseId] = [sp].[database_id];
        END TRY
        BEGIN CATCH
            SELECT @IsPartial = 1,
                   @ErrorNumber = ERROR_NUMBER(),
                   @ErrorMessage = CONCAT(N'suspect_pages nicht lesbar: ', ERROR_MESSAGE());
        END CATCH;

        BEGIN TRY
            INSERT [#DatabaseIntegrityAnalysis_HadrRepair]
            (
                  [DatabaseId], [FileId], [PageId], [ErrorType]
                , [PageStatus], [ModificationTime]
            )
            SELECT
                  [r].[database_id], [r].[file_id], [r].[page_id]
                , [r].[error_type], [r].[page_status], [r].[modification_time]
            FROM [sys].[dm_hadr_auto_page_repair] AS [r] WITH (NOLOCK)
            JOIN [#DatabaseIntegrityAnalysis_DatabaseCandidates] AS [c]
              ON [c].[DatabaseId] = [r].[database_id];
        END TRY
        BEGIN CATCH
            SET @IsPartial = 1;
            IF @ErrorNumber IS NULL
            BEGIN
                SELECT @ErrorNumber = ERROR_NUMBER(),
                       @ErrorMessage = CONCAT(N'HADR-Seitenreparaturstatus nicht lesbar: ', ERROR_MESSAGE());
            END;
        END CATCH;

        BEGIN TRY
            ;WITH [BackupEvidence] AS
            (
                SELECT
                      [bs].[database_name]
                    , SUM(CONVERT(bigint, CASE WHEN [bs].[is_damaged] = 1 THEN 1 ELSE 0 END)) AS [DamagedCount]
                    , SUM(CONVERT(bigint, CASE WHEN COALESCE([bs].[has_backup_checksums], 0) = 0 THEN 1 ELSE 0 END)) AS [NoChecksumCount]
                FROM [msdb].[dbo].[backupset] AS [bs] WITH (NOLOCK)
                JOIN [#DatabaseIntegrityAnalysis_DatabaseCandidates] AS [c]
                  ON [c].[DatabaseName] COLLATE SQL_Latin1_General_CP1_CS_AS
                   = [bs].[database_name] COLLATE SQL_Latin1_General_CP1_CS_AS
                WHERE [bs].[backup_finish_date] >= DATEADD(DAY, -@BackupHistoryDays, GETDATE())
                GROUP BY [bs].[database_name]
            ),
            [SuspectEvidence] AS
            (
                SELECT [DatabaseId], COUNT_BIG(*) AS [PageCount],
                       MAX([LastUpdateDate]) AS [LatestDate]
                FROM [#DatabaseIntegrityAnalysis_Suspect]
                GROUP BY [DatabaseId]
            ),
            [RepairEvidence] AS
            (
                SELECT [DatabaseId], COUNT_BIG(*) AS [RepairCount],
                       SUM(CONVERT(bigint, CASE WHEN [PageStatus] <> 5 THEN 1 ELSE 0 END)) AS [PendingCount]
                FROM [#DatabaseIntegrityAnalysis_HadrRepair]
                GROUP BY [DatabaseId]
            )
            INSERT [#DatabaseIntegrityAnalysis_Integrity]
            SELECT
                  [c].[DatabaseId]
                , [c].[DatabaseName]
                , [c].[StateDesc]
                , [d].[page_verify_option_desc]
                , CONVERT(datetime2(3), NULL)
                , CONVERT(int, NULL)
                , COALESCE([s].[PageCount], 0)
                , [s].[LatestDate]
                , COALESCE([b].[DamagedCount], 0)
                , COALESCE([b].[NoChecksumCount], 0)
                , COALESCE([r].[RepairCount], 0)
                , COALESCE([r].[PendingCount], 0)
                , CASE
                      WHEN COALESCE([s].[PageCount], 0) > 0 THEN 'SUSPECT_PAGES_PRESENT'
                      WHEN COALESCE([b].[DamagedCount], 0) > 0 THEN 'DAMAGED_BACKUP_METADATA'
                      WHEN COALESCE([r].[PendingCount], 0) > 0 THEN 'HADR_PAGE_REPAIR_PENDING'
                      WHEN [d].[page_verify_option_desc] <> N'CHECKSUM' THEN 'PAGE_VERIFY_NOT_CHECKSUM'
                      WHEN COALESCE([b].[NoChecksumCount], 0) > 0 THEN 'BACKUP_WITHOUT_CHECKSUM_IN_VISIBLE_HISTORY'
                      ELSE 'CHECKDB_EVIDENCE_UNAVAILABLE'
                  END
                , CONCAT(N'Diese Metadaten sind Indizien; Backupmetadaten-Sichtfenster ', @BackupHistoryDays,
                         N' Tage. LastGoodCheckDbTime wird bewusst nicht über DATABASEPROPERTYEX gelesen, ',
                         N'da diese Metadatenfunktion blockieren kann. Auch CHECKDB_EVIDENCE_UNAVAILABLE ',
                         N'beweist weder logische noch physische Integrität.')
            FROM [#DatabaseIntegrityAnalysis_DatabaseCandidates] AS [c]
            JOIN [master].[sys].[databases] AS [d] WITH (NOLOCK)
              ON [d].[database_id] = [c].[DatabaseId]
            LEFT JOIN [BackupEvidence] AS [b]
              ON [b].[database_name] COLLATE SQL_Latin1_General_CP1_CS_AS
               = [c].[DatabaseName] COLLATE SQL_Latin1_General_CP1_CS_AS
            LEFT JOIN [SuspectEvidence] AS [s]
              ON [s].[DatabaseId] = [c].[DatabaseId]
            LEFT JOIN [RepairEvidence] AS [r]
              ON [r].[DatabaseId] = [c].[DatabaseId];
        END TRY
        BEGIN CATCH
            SELECT @StatusCode =
                       CASE WHEN ERROR_NUMBER() IN (229, 262, 297, 300, 371)
                            THEN 'DENIED_PERMISSION' ELSE 'ERROR_HANDLED' END,
                   @IsPartial = 1,
                   @ErrorNumber = ERROR_NUMBER(),
                   @ErrorMessage = ERROR_MESSAGE();
        END CATCH;
    END;

    IF @StatusCode = 'AVAILABLE' AND @MitPageDetails = 1
    BEGIN
        BEGIN TRY
            INSERT [#DatabaseIntegrityAnalysis_PageDetails]
            SELECT TOP (@Limit)
                  [c].[DatabaseName]
                , [s].[FileId]
                , [s].[PageId]
                , [s].[EventType]
                , [s].[LastUpdateDate]
                , [p].[object_id]
                , [p].[index_id]
                , [p].[partition_id]
                , [p].[page_type_desc]
                , [p].[alloc_unit_id]
            FROM [#DatabaseIntegrityAnalysis_Suspect] AS [s]
            JOIN [#DatabaseIntegrityAnalysis_DatabaseCandidates] AS [c]
              ON [c].[DatabaseId] = [s].[DatabaseId]
            OUTER APPLY [sys].[dm_db_page_info]
            (
                  [s].[DatabaseId], [s].[FileId], [s].[PageId], 'LIMITED'
            ) AS [p]
            ORDER BY [s].[LastUpdateDate] DESC, [s].[DatabaseId], [s].[FileId], [s].[PageId];
        END TRY
        BEGIN CATCH
            SET @IsPartial = 1;
            IF @ErrorNumber IS NULL
            BEGIN
                SELECT @ErrorNumber = ERROR_NUMBER(),
                       @ErrorMessage = CONCAT(N'Seitenmetadaten nicht lesbar: ', ERROR_MESSAGE());
            END;
        END CATCH;
    END;

    IF @StatusCode = 'AVAILABLE'
       AND (@IsPartial = 1 OR EXISTS (SELECT 1 FROM [#DatabaseIntegrityAnalysis_DatabaseCandidateWarnings]))
        SET @StatusCode = 'AVAILABLE_LIMITED';
    ELSE IF @StatusCode = 'AVAILABLE'
        AND EXISTS (SELECT 1 FROM [#DatabaseIntegrityAnalysis_Integrity] WHERE [FindingCode] <> 'NO_INDICATOR_FOUND')
        SET @StatusCode = 'AVAILABLE_WITH_FINDING';

    SELECT @StatusCodeOut = @StatusCode,
           @IsPartialOut = @IsPartial,
           @ErrorNumberOut = @ErrorNumber,
           @ErrorMessageOut = @ErrorMessage;

    IF @PrintMeldungen = 1 AND @StatusCode <> 'AVAILABLE'
    BEGIN
        SET @MonitorPrintMessage = COALESCE(@ErrorMessage, CONVERT(nvarchar(2048), @StatusCode));
        RAISERROR(N'USP_DatabaseIntegrityAnalysis: %s', 10, 1, @MonitorPrintMessage) WITH NOWAIT;
    END;

    IF @OutputMode <> 'NONE'
    BEGIN
        SELECT
              CAST('1.0' AS varchar(16)) AS [ContractVersion]
            , @Now AS [CollectionTimeUtc]
            , N'monitor.USP_DatabaseIntegrityAnalysis' AS [ModuleName]
            , @StatusCode AS [StatusCode]
            , @IsPartial AS [IsPartial]
            , @ErrorNumber AS [ErrorNumber]
            , @ErrorMessage AS [ErrorMessage];

        IF @OutputMode = 'RAW'
        BEGIN
            SELECT * FROM [#DatabaseIntegrityAnalysis_Integrity]
            ORDER BY CASE WHEN [FindingCode] = 'NO_INDICATOR_FOUND' THEN 1 ELSE 0 END,
                     [DatabaseName];
            SELECT * FROM [#DatabaseIntegrityAnalysis_PageDetails]
            ORDER BY [LastUpdateDate] DESC, [DatabaseName], [FileId], [PageId];
            SELECT * FROM [#DatabaseIntegrityAnalysis_DatabaseCandidateWarnings] ORDER BY [RequestedName];
        END
        ELSE
        BEGIN
            SELECT
                  N'Integritätsevidenz' AS [Ergebnis]
                , [DatabaseName] AS [Datenbank]
                , [FindingCode] AS [Bewertung]
                , [PageVerifyOptionDesc] AS [Page Verify]
                , [LastGoodCheckDbTime] AS [Letzter erfolgreicher CHECKDB-Nachweis]
                , [CheckdbAgeHours] AS [Nachweisalter Stunden]
                , [SuspectPageCount] AS [Verdächtige Seiten]
                , [DamagedBackupCount] AS [Beschädigte Backupmetadaten]
                , [BackupWithoutChecksumCount] AS [Backups ohne Checksum]
                , [HadrPageRepairPendingCount] AS [Offene HADR-Seitenreparaturen]
                , [EvidenceLimit] AS [Aussagegrenze]
            FROM [#DatabaseIntegrityAnalysis_Integrity]
            ORDER BY CASE WHEN [FindingCode] = 'NO_INDICATOR_FOUND' THEN 1 ELSE 0 END,
                     [DatabaseName];

            SELECT N'Seitenmetadaten' AS [Ergebnis], [p].*
            FROM [#DatabaseIntegrityAnalysis_PageDetails] AS [p]
            ORDER BY [LastUpdateDate] DESC, [DatabaseName], [FileId], [PageId];
        END;
    END;

    IF @JsonErzeugen = 1
    BEGIN
        DECLARE @MetaJson nvarchar(max) =
        (
            SELECT N'DatabaseIntegrityAnalysis' AS [resultName], 1 AS [schemaVersion],
                   @Now AS [generatedAtUtc], @StatusCode AS [statusCode],
                   @IsPartial AS [isPartial], @ErrorNumber AS [errorNumber],
                   @ErrorMessage AS [errorMessage]
            FOR JSON PATH, WITHOUT_ARRAY_WRAPPER, INCLUDE_NULL_VALUES
        );
        DECLARE @IntegrityJson nvarchar(max) =
            (SELECT * FROM [#DatabaseIntegrityAnalysis_Integrity] ORDER BY [DatabaseName] FOR JSON PATH, INCLUDE_NULL_VALUES);
        DECLARE @PagesJson nvarchar(max) =
            (SELECT * FROM [#DatabaseIntegrityAnalysis_PageDetails] ORDER BY [LastUpdateDate] DESC FOR JSON PATH, INCLUDE_NULL_VALUES);
        DECLARE @WarningsJson nvarchar(max) =
            (SELECT * FROM [#DatabaseIntegrityAnalysis_DatabaseCandidateWarnings] ORDER BY [RequestedName] FOR JSON PATH, INCLUDE_NULL_VALUES);

        SET @Json = CONCAT
        (
              N'{"meta":', COALESCE(@MetaJson, N'{}')
            , N',"integrity":', COALESCE(@IntegrityJson, N'[]')
            , N',"pageDetails":', COALESCE(@PagesJson, N'[]')
            , N',"warnings":', COALESCE(@WarningsJson, N'[]')
            , N'}'
        );
    END;
    IF @ConsoleResultRequested = 1
    BEGIN
        EXEC [monitor].[InternalEmitConsoleResult]
              @SourceTable=N'#DatabaseIntegrityAnalysis_Integrity'
            , @ResultLabel=N'DatabaseIntegrityAnalysis'
            , @EmptyMessage=N'Keine fachlichen Ergebnisse';
    END;
    IF @TableResultRequested = 1
    BEGIN
        EXEC [monitor].[InternalWriteResultTable]
              @SourceTable = N'#DatabaseIntegrityAnalysis_Integrity'
            , @TargetTable=@TableTarget
            , @ThrowOnError = 1;
    END;
END;
GO
-- END SOURCE: Code/08_ServerHealth/110_USP_DatabaseIntegrityAnalysis.sql

-- BEGIN SOURCE: Code/08_ServerHealth/120_USP_DatabaseCapacityAnalysis.sql
/*
===============================================================================
Objekt       : monitor.USP_DatabaseCapacityAnalysis
Version      : 1.0.1
Stand        : 2026-07-18
Zweck        : Trennt Datei- und Volumefreiraum und bewertet das nächste
               Autogrowth je ausgewählter Datenbank.
Datenquellen : sys.database_files, FILEPROPERTY, sys.dm_os_volume_stats.
Grenzen      : Eine Zeit-bis-voll-Prognose wird ohne persistente Historie nicht
               erzeugt. Alle Bewertungen sind Momentaufnahmen.
Nebenwirkung : rein lesend; keine Datei- oder Datenbankänderung.
===============================================================================
*/
CREATE OR ALTER PROCEDURE [monitor].[USP_DatabaseCapacityAnalysis]
      @DatabaseNames                nvarchar(max)  = NULL
    , @SystemdatenbankenEinbeziehen bit            = 0
    , @DatabaseNamePattern          nvarchar(4000) = NULL
    , @HighImpactConfirmed              bit            = 0
    , @MinVolumeFreePercent         decimal(9,2)   = 10.00
    , @NurProblematisch             bit            = 0
    , @MaxZeilen                    int            = 1000
    , @ResultSetArt                 varchar(16)    = 'CONSOLE'
    , @ResultTablesJson               nvarchar(max) = NULL
    , @JsonErzeugen                 bit            = 0
    , @Json                         nvarchar(max)  = NULL OUTPUT
    , @PrintMeldungen               bit            = 1
    , @Hilfe                        bit            = 0
    , @StatusCodeOut                varchar(40)    = NULL OUTPUT
    , @IsPartialOut                 bit            = NULL OUTPUT
    , @ErrorNumberOut               int            = NULL OUTPUT
    , @ErrorMessageOut              nvarchar(2048) = NULL OUTPUT
AS
BEGIN
    SET NOCOUNT ON;
    SET @Json = NULL;

    DECLARE @OutputMode varchar(16) =
        UPPER(LTRIM(RTRIM(COALESCE(@ResultSetArt, ''))));
    DECLARE @TableResultRequested bit = CASE WHEN @OutputMode = 'TABLE' THEN 1 ELSE 0 END;
    DECLARE @ConsoleResultRequested bit = CASE WHEN @OutputMode = 'CONSOLE' THEN 1 ELSE 0 END;
    DECLARE @TableTarget sysname=NULL;
    IF @TableResultRequested=0 AND NULLIF(LTRIM(RTRIM(COALESCE(@ResultTablesJson,N''))),N'') IS NOT NULL THROW 51011,N'@ResultTablesJson ist ausschließlich mit @ResultSetArt=TABLE zulässig.',1;
    IF @TableResultRequested=1 EXEC [monitor].[InternalPrepareSingleResultTable] @ResultTablesJson=@ResultTablesJson,@ResultName=N'capacity',@TargetTable=@TableTarget OUTPUT,@ThrowOnError=1;
    IF @TableResultRequested = 1 OR @ConsoleResultRequested = 1 SET @OutputMode = 'NONE';
    DECLARE @Limit bigint =
        CASE WHEN @MaxZeilen IS NULL OR @MaxZeilen = 0
             THEN CONVERT(bigint, 9223372036854775807)
             ELSE CONVERT(bigint, @MaxZeilen) END;

    IF @Hilfe = 1
    BEGIN
        PRINT N'monitor.USP_DatabaseCapacityAnalysis';
        PRINT N'Trennt Dateifreiraum und Volumefreiraum; erzeugt ohne Historie keine Zeit-bis-voll-Prognose.';
        PRINT N'@DatabaseNames: bracket-aware Pipe-Liste; N''''/NULL = keine Datenbankeinschränkung.';
        PRINT N'@MinVolumeFreePercent=10; @NurProblematisch=0; @MaxZeilen NULL/0 = unbegrenzt.';
        RETURN;
    END;

    DECLARE @Now datetime2(3) = SYSUTCDATETIME();
    DECLARE @StatusCode varchar(40) = 'AVAILABLE';
    DECLARE @IsPartial bit = 0;
    DECLARE @ErrorNumber int = NULL;
    DECLARE @ErrorMessage nvarchar(2048) = NULL;
    DECLARE @MonitorPrintMessage nvarchar(2048) = NULL;
    DECLARE @CrossDatabaseRequested bit = 0;
    DECLARE @RequiredServerPermission sysname =
        CASE WHEN TRY_CONVERT(int, SERVERPROPERTY(N'ProductMajorVersion')) >= 16
             THEN N'VIEW SERVER PERFORMANCE STATE' ELSE N'VIEW SERVER STATE' END;
    DECLARE @HasRequiredServerPermission bit =
        CASE WHEN IS_SRVROLEMEMBER(N'sysadmin') = 1 THEN 1
             ELSE COALESCE(HAS_PERMS_BY_NAME(NULL, N'SERVER', @RequiredServerPermission), 0) END;

    CREATE TABLE [#DatabaseCapacityAnalysis_DatabaseCandidates]
    (
          [DatabaseId] int NOT NULL PRIMARY KEY
        , [DatabaseName] sysname NOT NULL
        , [StateDesc] nvarchar(60) NULL
        , [UserAccessDesc] nvarchar(60) NULL
        , [IsReadOnly] bit NULL
        , [CompatibilityLevel] tinyint NULL
        , [CollationName] sysname NULL
        , [RecoveryModelDesc] nvarchar(60) NULL
        , [IsSystemDatabase] bit NULL
        , [RequestedOrdinal] int NULL
    );

    CREATE TABLE [#DatabaseCapacityAnalysis_DatabaseCandidateWarnings]
    (
          [RequestedName] sysname NULL
        , [StatusCode] varchar(40) NOT NULL
        , [ErrorMessage] nvarchar(2048) NULL
    );

    CREATE TABLE [#DatabaseCapacityAnalysis_Capacity]
    (
          [DatabaseId] int NULL
        , [DatabaseName] sysname NULL
        , [FileId] int NULL
        , [LogicalFileName] sysname NULL
        , [FileTypeDesc] nvarchar(60) NULL
        , [PhysicalName] nvarchar(260) NULL
        , [FileSizeMb] decimal(19,2) NULL
        , [UsedInFileMb] decimal(19,2) NULL
        , [FreeInFileMb] decimal(19,2) NULL
        , [FreeInFilePercent] decimal(9,2) NULL
        , [GrowthDescription] nvarchar(80) NULL
        , [NextGrowthMb] decimal(19,2) NULL
        , [MaxSizeMb] decimal(19,2) NULL
        , [VolumeMountPoint] nvarchar(512) NULL
        , [LogicalVolumeName] nvarchar(512) NULL
        , [VolumeTotalMb] decimal(19,2) NULL
        , [VolumeAvailableMb] decimal(19,2) NULL
        , [VolumeFreePercent] decimal(9,2) NULL
        , [FindingCode] varchar(80) NULL
        , [EvidenceLimit] nvarchar(500) NOT NULL
    );

    IF @MaxZeilen < 0
       OR @MinVolumeFreePercent < 0
       OR @MinVolumeFreePercent > 100
       OR @OutputMode NOT IN ('RAW', 'CONSOLE', 'NONE')
    BEGIN
        SELECT @StatusCode = 'INVALID_PARAMETER',
               @IsPartial = 1,
               @ErrorMessage = N'Ungültige Datenbank-, Prozent-, Zeilen- oder Ausgabeparameter.';
    END;

    IF @StatusCode = 'AVAILABLE'
       AND @HasRequiredServerPermission = 0
    BEGIN
        SELECT @IsPartial = 1,
               @ErrorMessage = CONCAT(N'Für vollständige serverweite Volumenevidenz fehlt ',
                                      @RequiredServerPermission, N'.');
    END;

    IF @StatusCode = 'AVAILABLE'
    BEGIN
        EXEC [monitor].[USP_PrepareDatabaseCandidates]
              @DatabaseNames = @DatabaseNames
            , @SystemdatenbankenEinbeziehen = @SystemdatenbankenEinbeziehen
            , @DatabaseNamePattern = @DatabaseNamePattern,@HighImpactConfirmed=@HighImpactConfirmed

            , @AnalysisClass = 'SERVER_HEALTH_CURRENT'
            , @StatusCode = @StatusCode OUTPUT
            , @ErrorMessage = @ErrorMessage OUTPUT
            , @CrossDatabaseRequested = @CrossDatabaseRequested OUTPUT,@CandidateTable=N'#DatabaseCapacityAnalysis_DatabaseCandidates',@WarningTable=N'#DatabaseCapacityAnalysis_DatabaseCandidateWarnings';
    END;

    SET LOCK_TIMEOUT 0;

    IF @StatusCode = 'AVAILABLE'
    BEGIN
        DECLARE @DatabaseId int;
        DECLARE @DatabaseName sysname;
        DECLARE @Sql nvarchar(max);

        DECLARE [DatabaseCursor] CURSOR LOCAL FAST_FORWARD FOR
            SELECT [DatabaseId], [DatabaseName]
            FROM [#DatabaseCapacityAnalysis_DatabaseCandidates]
            ORDER BY COALESCE([RequestedOrdinal], [DatabaseId]), [DatabaseId];

        OPEN [DatabaseCursor];
        FETCH NEXT FROM [DatabaseCursor] INTO @DatabaseId, @DatabaseName;
        WHILE @@FETCH_STATUS = 0
        BEGIN
            BEGIN TRY
                SET @Sql = N'USE ' + QUOTENAME(@DatabaseName) + N';
INSERT [#DatabaseCapacityAnalysis_Capacity]
(
      [DatabaseId], [DatabaseName], [FileId], [LogicalFileName]
    , [FileTypeDesc], [PhysicalName], [FileSizeMb], [UsedInFileMb]
    , [FreeInFileMb], [FreeInFilePercent], [GrowthDescription]
    , [NextGrowthMb], [MaxSizeMb], [VolumeMountPoint], [LogicalVolumeName]
    , [VolumeTotalMb], [VolumeAvailableMb], [VolumeFreePercent]
    , [FindingCode], [EvidenceLimit]
)
SELECT
      DB_ID(), (SELECT [name] FROM [master].[sys].[databases] WITH (NOLOCK) WHERE [database_id] = DB_ID()), [f].[file_id], [f].[name], [f].[type_desc], [f].[physical_name]
    , CONVERT(decimal(19,2), [f].[size] * 8.0 / 1024.0)
    , CONVERT(decimal(19,2), COALESCE(FILEPROPERTY([f].[name], ''SpaceUsed''), 0) * 8.0 / 1024.0)
    , CONVERT(decimal(19,2), ([f].[size] - COALESCE(FILEPROPERTY([f].[name], ''SpaceUsed''), 0)) * 8.0 / 1024.0)
    , CONVERT(decimal(9,2), 100.0 * ([f].[size] - COALESCE(FILEPROPERTY([f].[name], ''SpaceUsed''), 0)) / NULLIF([f].[size], 0))
    , CASE WHEN [f].[growth] = 0 THEN N''DISABLED''
           WHEN [f].[is_percent_growth] = 1 THEN CONCAT([f].[growth], N'' percent'')
           ELSE CONCAT(CONVERT(decimal(19,2), [f].[growth] * 8.0 / 1024.0), N'' MB'') END
    , CASE WHEN [f].[growth] = 0 THEN NULL
           WHEN [f].[is_percent_growth] = 1
               THEN CONVERT(decimal(19,2), CEILING([f].[size] * [f].[growth] / 100.0) * 8.0 / 1024.0)
           ELSE CONVERT(decimal(19,2), [f].[growth] * 8.0 / 1024.0) END
    , CASE WHEN [f].[max_size] = -1 THEN NULL
           ELSE CONVERT(decimal(19,2), [f].[max_size] * 8.0 / 1024.0) END
    , [v].[volume_mount_point], [v].[logical_volume_name]
    , CONVERT(decimal(19,2), [v].[total_bytes] / 1048576.0)
    , CONVERT(decimal(19,2), [v].[available_bytes] / 1048576.0)
    , CONVERT(decimal(9,2), 100.0 * [v].[available_bytes] / NULLIF([v].[total_bytes], 0))
    , CASE
          WHEN [f].[growth] = 0 THEN ''GROWTH_DISABLED''
          WHEN [f].[max_size] <> -1 AND [f].[size] >= [f].[max_size] THEN ''FILE_MAX_SIZE_REACHED''
          WHEN [v].[available_bytes] IS NOT NULL
           AND (CASE WHEN [f].[is_percent_growth] = 1
                     THEN CEILING([f].[size] * [f].[growth] / 100.0) * 8192.0
                     ELSE [f].[growth] * 8192.0 END) > [v].[available_bytes]
              THEN ''NEXT_GROWTH_EXCEEDS_VOLUME_FREE''
          WHEN [v].[total_bytes] > 0
           AND 100.0 * [v].[available_bytes] / [v].[total_bytes] < @pMinVolumeFreePercent
              THEN ''LOW_VOLUME_FREE_PERCENT''
          WHEN [f].[is_percent_growth] = 1 THEN ''PERCENT_GROWTH_REVIEW''
          ELSE ''NO_CAPACITY_INDICATOR''
      END
    , N''Momentaufnahme; ohne persistente Messpunkte wird keine Zeit-bis-voll-Prognose erzeugt.''
FROM [sys].[database_files] AS [f] WITH (NOLOCK)
OUTER APPLY [sys].[dm_os_volume_stats](DB_ID(), [f].[file_id]) AS [v];';

                EXEC [sys].[sp_executesql]
                      @Sql
                    , N'@pMinVolumeFreePercent decimal(9,2)'
                    , @pMinVolumeFreePercent = @MinVolumeFreePercent;
            END TRY
            BEGIN CATCH
                SET @IsPartial = 1;
                INSERT [#DatabaseCapacityAnalysis_DatabaseCandidateWarnings]
                VALUES
                (
                      @DatabaseName
                    , CASE WHEN ERROR_NUMBER() IN (229, 262, 297, 300, 371)
                           THEN 'DENIED_PERMISSION' ELSE 'ERROR_HANDLED' END
                    , ERROR_MESSAGE()
                );
            END CATCH;

            FETCH NEXT FROM [DatabaseCursor] INTO @DatabaseId, @DatabaseName;
        END;
        CLOSE [DatabaseCursor];
        DEALLOCATE [DatabaseCursor];
    END;

    IF @StatusCode = 'AVAILABLE'
       AND (@IsPartial = 1 OR EXISTS (SELECT 1 FROM [#DatabaseCapacityAnalysis_DatabaseCandidateWarnings]))
        SET @StatusCode = 'AVAILABLE_LIMITED';
    ELSE IF @StatusCode = 'AVAILABLE'
        AND EXISTS (SELECT 1 FROM [#DatabaseCapacityAnalysis_Capacity] WHERE [FindingCode] <> 'NO_CAPACITY_INDICATOR')
        SET @StatusCode = 'AVAILABLE_WITH_FINDING';

    SELECT @StatusCodeOut = @StatusCode,
           @IsPartialOut = @IsPartial,
           @ErrorNumberOut = @ErrorNumber,
           @ErrorMessageOut = @ErrorMessage;

    IF @PrintMeldungen = 1 AND @StatusCode <> 'AVAILABLE'
    BEGIN
        SET @MonitorPrintMessage = COALESCE(@ErrorMessage, CONVERT(nvarchar(2048), @StatusCode));
        RAISERROR(N'USP_DatabaseCapacityAnalysis: %s', 10, 1, @MonitorPrintMessage) WITH NOWAIT;
    END;

    IF @OutputMode <> 'NONE'
    BEGIN
        SELECT CAST('1.0' AS varchar(16)) AS [ContractVersion], @Now AS [CollectionTimeUtc],
               N'monitor.USP_DatabaseCapacityAnalysis' AS [ModuleName],
               @StatusCode AS [StatusCode], @IsPartial AS [IsPartial],
               @ErrorNumber AS [ErrorNumber], @ErrorMessage AS [ErrorMessage];

        IF @OutputMode = 'RAW'
        BEGIN
            SELECT TOP (@Limit) *
            FROM [#DatabaseCapacityAnalysis_Capacity]
            WHERE @NurProblematisch = 0 OR [FindingCode] <> 'NO_CAPACITY_INDICATOR'
            ORDER BY CASE WHEN [FindingCode] = 'NO_CAPACITY_INDICATOR' THEN 1 ELSE 0 END,
                     [VolumeFreePercent], [DatabaseName], [FileId];
            SELECT * FROM [#DatabaseCapacityAnalysis_DatabaseCandidateWarnings] ORDER BY [RequestedName];
        END
        ELSE
        BEGIN
            SELECT TOP (@Limit)
                  N'Kapazität' AS [Ergebnis]
                , [DatabaseName] AS [Datenbank]
                , [LogicalFileName] AS [Datei]
                , [FileTypeDesc] AS [Typ]
                , [FindingCode] AS [Bewertung]
                , [FileSizeMb] AS [Dateigröße MB]
                , [FreeInFileMb] AS [Frei in Datei MB]
                , [GrowthDescription] AS [Wachstum]
                , [NextGrowthMb] AS [Nächstes Wachstum MB]
                , [VolumeAvailableMb] AS [Frei auf Volume MB]
                , [VolumeFreePercent] AS [Frei auf Volume Prozent]
                , [VolumeMountPoint] AS [Volume]
                , [EvidenceLimit] AS [Aussagegrenze]
            FROM [#DatabaseCapacityAnalysis_Capacity]
            WHERE @NurProblematisch = 0 OR [FindingCode] <> 'NO_CAPACITY_INDICATOR'
            ORDER BY CASE WHEN [FindingCode] = 'NO_CAPACITY_INDICATOR' THEN 1 ELSE 0 END,
                     [VolumeFreePercent], [DatabaseName], [FileId];
        END;
    END;

    IF @JsonErzeugen = 1
    BEGIN
        DECLARE @MetaJson nvarchar(max) =
        (
            SELECT N'DatabaseCapacityAnalysis' AS [resultName], 1 AS [schemaVersion],
                   @Now AS [generatedAtUtc], @StatusCode AS [statusCode],
                   @IsPartial AS [isPartial], @ErrorNumber AS [errorNumber],
                   @ErrorMessage AS [errorMessage]
            FOR JSON PATH, WITHOUT_ARRAY_WRAPPER, INCLUDE_NULL_VALUES
        );
        DECLARE @CapacityJson nvarchar(max) =
        (
            SELECT TOP (@Limit) *
            FROM [#DatabaseCapacityAnalysis_Capacity]
            WHERE @NurProblematisch = 0 OR [FindingCode] <> 'NO_CAPACITY_INDICATOR'
            ORDER BY CASE WHEN [FindingCode] = 'NO_CAPACITY_INDICATOR' THEN 1 ELSE 0 END,
                     [VolumeFreePercent], [DatabaseName], [FileId]
            FOR JSON PATH, INCLUDE_NULL_VALUES
        );
        DECLARE @WarningsJson nvarchar(max) =
            (SELECT * FROM [#DatabaseCapacityAnalysis_DatabaseCandidateWarnings] ORDER BY [RequestedName] FOR JSON PATH, INCLUDE_NULL_VALUES);

        SET @Json = CONCAT
        (
              N'{"meta":', COALESCE(@MetaJson, N'{}')
            , N',"capacity":', COALESCE(@CapacityJson, N'[]')
            , N',"warnings":', COALESCE(@WarningsJson, N'[]')
            , N'}'
        );
    END;
    IF @ConsoleResultRequested = 1
    BEGIN
        EXEC [monitor].[InternalEmitConsoleResult]
              @SourceTable=N'#DatabaseCapacityAnalysis_Capacity'
            , @ResultLabel=N'DatabaseCapacityAnalysis'
            , @EmptyMessage=N'Keine fachlichen Ergebnisse';
    END;
    IF @TableResultRequested = 1
    BEGIN
        EXEC [monitor].[InternalWriteResultTable]
              @SourceTable = N'#DatabaseCapacityAnalysis_Capacity'
            , @TargetTable=@TableTarget
            , @ThrowOnError = 1;
    END;
END;
GO
-- END SOURCE: Code/08_ServerHealth/120_USP_DatabaseCapacityAnalysis.sql

-- BEGIN SOURCE: Code/08_ServerHealth/130_USP_PerformanceCounters.sql
/*
===============================================================================
Objekt       : monitor.USP_PerformanceCounters
Version      : 1.1.0
Stand        : 2026-07-18
Zweck        : Typisiert SQL-Server-Performance-Counter als Snapshot, Rate,
               Fraction oder nicht automatisch interpretierbaren Rohwert.
Datenquellen : sys.dm_os_performance_counters, sys.dm_os_sys_info.
Grenzen      : Universelle Alarmgrenzen werden nicht behauptet. Rate-Counter
               benötigen ein Sample; Counterreset wird als solcher markiert.
Nebenwirkung : Optionales WAITFOR für 1 bis 60 Sekunden; keine Persistenz.
===============================================================================
*/
CREATE OR ALTER PROCEDURE [monitor].[USP_PerformanceCounters]
      @ObjectNames       nvarchar(max)  = NULL
    , @CounterNames      nvarchar(max)  = NULL
    , @SampleSeconds     tinyint         = 0
    , @MaxZeilen         int             = 1000
    , @ResultSetArt      varchar(16)     = 'CONSOLE'
    , @ResultTablesJson               nvarchar(max) = NULL
    , @JsonErzeugen      bit             = 0
    , @Json              nvarchar(max)   = NULL OUTPUT
    , @PrintMeldungen    bit             = 1
    , @Hilfe             bit             = 0
    , @StatusCodeOut     varchar(40)     = NULL OUTPUT
    , @IsPartialOut      bit             = NULL OUTPUT
    , @ErrorNumberOut    int             = NULL OUTPUT
    , @ErrorMessageOut   nvarchar(2048)  = NULL OUTPUT
AS
BEGIN
    SET NOCOUNT ON;
    SET @Json = NULL;

    DECLARE @OutputMode varchar(16) =
        UPPER(LTRIM(RTRIM(COALESCE(@ResultSetArt, ''))));
    DECLARE @TableResultRequested bit = CASE WHEN @OutputMode = 'TABLE' THEN 1 ELSE 0 END;
    DECLARE @ConsoleResultRequested bit = CASE WHEN @OutputMode = 'CONSOLE' THEN 1 ELSE 0 END;
    DECLARE @TableTarget sysname=NULL;
    IF @TableResultRequested=0 AND NULLIF(LTRIM(RTRIM(COALESCE(@ResultTablesJson,N''))),N'') IS NOT NULL THROW 51011,N'@ResultTablesJson ist ausschließlich mit @ResultSetArt=TABLE zulässig.',1;
    IF @TableResultRequested=1 EXEC [monitor].[InternalPrepareSingleResultTable] @ResultTablesJson=@ResultTablesJson,@ResultName=N'counters',@TargetTable=@TableTarget OUTPUT,@ThrowOnError=1;
    IF @TableResultRequested = 1 OR @ConsoleResultRequested = 1 SET @OutputMode = 'NONE';
    DECLARE @Limit bigint =
        CASE WHEN @MaxZeilen IS NULL OR @MaxZeilen = 0
             THEN CONVERT(bigint, 9223372036854775807)
             ELSE CONVERT(bigint, @MaxZeilen) END;

    IF @Hilfe = 1
    BEGIN
        PRINT N'monitor.USP_PerformanceCounters';
        PRINT N'@ObjectNames und @CounterNames: optionale bracket-aware Pipe-Listen mit exakten Namen.';
        PRINT N'@SampleSeconds=0 liefert Roh-Snapshots; 1..60 berechnet unterstützte Raten und Quotienten aus Deltas.';
        PRINT N'Countertyp, Basiswert, Samplezeit und SQL-Startzeit werden immer mitgeführt.';
        PRINT N'Nicht unterstützte cntr_type-Werte werden als RAW_UNINTERPRETED gekennzeichnet.';
        RETURN;
    END;

    DECLARE @Now datetime2(3) = SYSUTCDATETIME();
    DECLARE @SampleStartUtc datetime2(7) = SYSUTCDATETIME();
    DECLARE @SampleEndUtc datetime2(7);
    DECLARE @SqlServerStartTime datetime2(3);
    DECLARE @StatusCode varchar(40) = 'AVAILABLE';
    DECLARE @IsPartial bit = 0;
    DECLARE @ErrorNumber int = NULL;
    DECLARE @ErrorMessage nvarchar(2048) = NULL;
    DECLARE @MonitorPrintMessage nvarchar(2048) = NULL;
    DECLARE @Delay char(8);

    CREATE TABLE [#PerformanceCounters_Before]
    (
          [ObjectName] nvarchar(128) NOT NULL
        , [CounterName] nvarchar(128) NOT NULL
        , [InstanceName] nvarchar(128) NOT NULL
        , [CounterValue] bigint NOT NULL
        , [CounterType] int NOT NULL
        , PRIMARY KEY ([ObjectName], [CounterName], [InstanceName], [CounterType])
    );

    CREATE TABLE [#PerformanceCounters_After]
    (
          [ObjectName] nvarchar(128) NOT NULL
        , [CounterName] nvarchar(128) NOT NULL
        , [InstanceName] nvarchar(128) NOT NULL
        , [CounterValue] bigint NOT NULL
        , [CounterType] int NOT NULL
        , PRIMARY KEY ([ObjectName], [CounterName], [InstanceName], [CounterType])
    );

    CREATE TABLE [#PerformanceCounters_Result]
    (
          [ObjectName] nvarchar(128) NOT NULL
        , [CounterName] nvarchar(128) NOT NULL
        , [InstanceName] nvarchar(128) NOT NULL
        , [CounterType] int NOT NULL
        , [Interpretation] varchar(40) NOT NULL
        , [MetricValue] decimal(38,6) NULL
        , [MetricUnit] varchar(40) NOT NULL
        , [BeforeValue] bigint NULL
        , [AfterValue] bigint NOT NULL
        , [BaseBeforeValue] bigint NULL
        , [BaseAfterValue] bigint NULL
        , [DeltaValue] bigint NULL
        , [BaseDeltaValue] bigint NULL
        , [SampleSeconds] decimal(19,6) NULL
        , [SqlServerStartTime] datetime2(3) NULL
        , [FindingCode] varchar(80) NOT NULL
    );

    IF @MaxZeilen < 0
       OR @SampleSeconds > 60
       OR @OutputMode NOT IN ('RAW', 'CONSOLE', 'NONE')
       OR (@ObjectNames IS NOT NULL AND EXISTS
          (SELECT 1 FROM [monitor].[TVF_ParseStringList](@ObjectNames) WHERE [IsValid] = 0))
       OR (@CounterNames IS NOT NULL AND EXISTS
          (SELECT 1 FROM [monitor].[TVF_ParseStringList](@CounterNames) WHERE [IsValid] = 0))
    BEGIN
        SELECT @StatusCode = 'INVALID_PARAMETER',
               @IsPartial = 1,
               @ErrorMessage = N'Ungültige Listen-, Sample-, Zeilen- oder Ausgabeparameter.';
    END;

    SET LOCK_TIMEOUT 0;

    IF @StatusCode = 'AVAILABLE'
    BEGIN TRY
        SELECT @SqlServerStartTime = TRY_CONVERT(datetime2(3), [sqlserver_start_time])
        FROM [sys].[dm_os_sys_info] WITH (NOLOCK);

        INSERT [#PerformanceCounters_Before]
        SELECT DISTINCT RTRIM([object_name]), RTRIM([counter_name]), RTRIM([instance_name]), [cntr_value], [cntr_type]
        FROM [sys].[dm_os_performance_counters] WITH (NOLOCK)
        WHERE
            (@ObjectNames IS NULL OR EXISTS
             (
                 SELECT 1
                 FROM [monitor].[TVF_ParseStringList](@ObjectNames) AS [o]
                 WHERE [o].[IsValid] = 1
                   AND [o].[StringValue] COLLATE SQL_Latin1_General_CP1_CS_AS
                     = [object_name] COLLATE SQL_Latin1_General_CP1_CS_AS
             ))
        AND (@CounterNames IS NULL OR EXISTS
             (
                 SELECT 1
                 FROM [monitor].[TVF_ParseStringList](@CounterNames) AS [n]
                 WHERE [n].[IsValid] = 1
                   AND [n].[StringValue] COLLATE SQL_Latin1_General_CP1_CS_AS
                     = [counter_name] COLLATE SQL_Latin1_General_CP1_CS_AS
             )
             OR EXISTS
             (
                 SELECT 1
                 FROM [monitor].[TVF_ParseStringList](@CounterNames) AS [n]
                 WHERE [n].[IsValid] = 1
                   AND CONCAT([n].[StringValue], N' base') COLLATE SQL_Latin1_General_CP1_CI_AS
                     = RTRIM([counter_name]) COLLATE SQL_Latin1_General_CP1_CI_AS
             ));

        IF NOT EXISTS (SELECT 1 FROM [#PerformanceCounters_Before])
        BEGIN
            SELECT @StatusCode = 'UNAVAILABLE_OBJECT',
                   @IsPartial = 1,
                   @ErrorMessage = N'sys.dm_os_performance_counters liefert keine aktivierten Counter.';
        END;

        IF @SampleSeconds > 0
        BEGIN
            SET @Delay = CONVERT(char(8),
                DATEADD(SECOND, @SampleSeconds, CONVERT(time(0), '00:00:00')), 108);
            WAITFOR DELAY @Delay;
        END;

        SET @SampleEndUtc = SYSUTCDATETIME();

        INSERT [#PerformanceCounters_After]
        SELECT DISTINCT RTRIM([p].[object_name]), RTRIM([p].[counter_name]), RTRIM([p].[instance_name]),
               [p].[cntr_value], [p].[cntr_type]
        FROM [sys].[dm_os_performance_counters] AS [p] WITH (NOLOCK)
        JOIN [#PerformanceCounters_Before] AS [b]
         ON [b].[ObjectName] = [p].[object_name]
         AND [b].[CounterName] = [p].[counter_name]
         AND [b].[InstanceName] = [p].[instance_name]
         AND [b].[CounterType] = [p].[cntr_type];

        INSERT [#PerformanceCounters_Result]
        SELECT
              [a].[ObjectName]
            , [a].[CounterName]
            , [a].[InstanceName]
            , [a].[CounterType]
            , [i].[Interpretation]
            , [i].[MetricValue]
            , [i].[MetricUnit]
            , [b].[CounterValue]
            , [a].[CounterValue]
            , [baseBefore].[CounterValue]
            , [baseAfter].[CounterValue]
            , TRY_CONVERT(bigint, CONVERT(decimal(38,0), [a].[CounterValue])
                                 - CONVERT(decimal(38,0), [b].[CounterValue]))
            , TRY_CONVERT(bigint, CONVERT(decimal(38,0), [baseAfter].[CounterValue])
                                 - CONVERT(decimal(38,0), [baseBefore].[CounterValue]))
            , CONVERT(decimal(19,6),
                DATEDIFF_BIG(MICROSECOND, @SampleStartUtc, @SampleEndUtc) / 1000000.0)
            , @SqlServerStartTime
            , [i].[FindingCode]
        FROM [#PerformanceCounters_After] AS [a]
        JOIN [#PerformanceCounters_Before] AS [b]
         ON [b].[ObjectName] = [a].[ObjectName]
         AND [b].[CounterName] = [a].[CounterName]
         AND [b].[InstanceName] = [a].[InstanceName]
         AND [b].[CounterType] = [a].[CounterType]
        LEFT JOIN [#PerformanceCounters_Before] AS [baseBefore]
          ON [baseBefore].[ObjectName] = [a].[ObjectName]
         AND [baseBefore].[InstanceName] = [a].[InstanceName]
         AND [baseBefore].[CounterName] COLLATE SQL_Latin1_General_CP1_CI_AS =
             CONVERT(nvarchar(128), CONCAT(RTRIM([a].[CounterName]), N' base'))
             COLLATE SQL_Latin1_General_CP1_CI_AS
         AND [baseBefore].[CounterType] IN (1073939458, 1073939712)
        LEFT JOIN [#PerformanceCounters_After] AS [baseAfter]
          ON [baseAfter].[ObjectName] = [a].[ObjectName]
         AND [baseAfter].[InstanceName] = [a].[InstanceName]
         AND [baseAfter].[CounterName] COLLATE SQL_Latin1_General_CP1_CI_AS =
             CONVERT(nvarchar(128), CONCAT(RTRIM([a].[CounterName]), N' base'))
             COLLATE SQL_Latin1_General_CP1_CI_AS
         AND [baseAfter].[CounterType] IN (1073939458, 1073939712)
        CROSS APPLY [monitor].[TVF_InterpretPerformanceCounter]
        (
              [a].[CounterType]
            , [b].[CounterValue]
            , [a].[CounterValue]
            , [baseBefore].[CounterValue]
            , [baseAfter].[CounterValue]
            , CASE WHEN @SampleSeconds = 0 THEN CONVERT(decimal(19,6), 0)
                   ELSE CONVERT(decimal(19,6),
                        DATEDIFF_BIG(MICROSECOND, @SampleStartUtc, @SampleEndUtc) / 1000000.0) END
        ) AS [i]
        WHERE [a].[CounterType] NOT IN (1073939458, 1073939712);

        IF NOT EXISTS (SELECT 1 FROM [#PerformanceCounters_Result])
        BEGIN
            SELECT @StatusCode = 'UNAVAILABLE_OBJECT',
                   @IsPartial = 1,
                   @ErrorMessage = N'Es stehen keine auswertbaren Performance-Counter-Zeilen bereit.';
        END;
    END TRY
    BEGIN CATCH
        SELECT @StatusCode =
                   CASE WHEN ERROR_NUMBER() IN (229, 262, 297, 300, 371)
                        THEN 'DENIED_PERMISSION' ELSE 'ERROR_HANDLED' END,
               @IsPartial = 1,
               @ErrorNumber = ERROR_NUMBER(),
               @ErrorMessage = ERROR_MESSAGE();
    END CATCH;

    SELECT @StatusCodeOut = @StatusCode,
           @IsPartialOut = @IsPartial,
           @ErrorNumberOut = @ErrorNumber,
           @ErrorMessageOut = @ErrorMessage;

    IF @PrintMeldungen = 1 AND @StatusCode <> 'AVAILABLE'
    BEGIN
        SET @MonitorPrintMessage = COALESCE(@ErrorMessage, CONVERT(nvarchar(2048), @StatusCode));
        RAISERROR(N'USP_PerformanceCounters: %s', 10, 1, @MonitorPrintMessage) WITH NOWAIT;
    END;

    IF @OutputMode <> 'NONE'
    BEGIN
        SELECT CAST('1.0' AS varchar(16)) AS [ContractVersion], @Now AS [CollectionTimeUtc],
               N'monitor.USP_PerformanceCounters' AS [ModuleName],
               @StatusCode AS [StatusCode], @IsPartial AS [IsPartial],
               @ErrorNumber AS [ErrorNumber], @ErrorMessage AS [ErrorMessage],
               @SampleStartUtc AS [SampleStartUtc], @SampleEndUtc AS [SampleEndUtc],
               @SqlServerStartTime AS [SqlServerStartTime];

        IF @OutputMode = 'RAW'
        BEGIN
            SELECT TOP (@Limit) *
            FROM [#PerformanceCounters_Result]
            ORDER BY [ObjectName], [CounterName], [InstanceName];
        END
        ELSE
        BEGIN
            SELECT TOP (@Limit)
                  N'Performance Counter' AS [Ergebnis]
                , [ObjectName] AS [Objekt]
                , [CounterName] AS [Counter]
                , [InstanceName] AS [Instanz]
                , [MetricValue] AS [Wert]
                , [MetricUnit] AS [Einheit]
                , [Interpretation] AS [Interpretation]
                , [CounterType] AS [Countertyp]
                , [FindingCode] AS [Bewertung]
                , [SampleSeconds] AS [Sample Sekunden]
            FROM [#PerformanceCounters_Result]
            ORDER BY [ObjectName], [CounterName], [InstanceName];
        END;
    END;

    IF @JsonErzeugen = 1
    BEGIN
        DECLARE @MetaJson nvarchar(max) =
        (
            SELECT N'PerformanceCounters' AS [resultName], 1 AS [schemaVersion],
                   @Now AS [generatedAtUtc], @StatusCode AS [statusCode],
                   @IsPartial AS [isPartial], @SampleStartUtc AS [sampleStartUtc],
                   @SampleEndUtc AS [sampleEndUtc], @SqlServerStartTime AS [sqlServerStartTime],
                   @ErrorNumber AS [errorNumber], @ErrorMessage AS [errorMessage]
            FOR JSON PATH, WITHOUT_ARRAY_WRAPPER, INCLUDE_NULL_VALUES
        );
        DECLARE @CountersJson nvarchar(max) =
        (
            SELECT TOP (@Limit) *
            FROM [#PerformanceCounters_Result]
            ORDER BY [ObjectName], [CounterName], [InstanceName]
            FOR JSON PATH, INCLUDE_NULL_VALUES
        );
        SET @Json = CONCAT
        (
              N'{"meta":', COALESCE(@MetaJson, N'{}')
            , N',"counters":', COALESCE(@CountersJson, N'[]')
            , N',"warnings":[]}'
        );
    END;
    IF @ConsoleResultRequested = 1
    BEGIN
        EXEC [monitor].[InternalEmitConsoleResult]
              @SourceTable=N'#PerformanceCounters_Result'
            , @ResultLabel=N'PerformanceCounters'
            , @EmptyMessage=N'Keine fachlichen Ergebnisse';
    END;
    IF @TableResultRequested = 1
    BEGIN
        EXEC [monitor].[InternalWriteResultTable]
              @SourceTable = N'#PerformanceCounters_Result'
            , @TargetTable=@TableTarget
            , @ThrowOnError = 1;
    END;
END;
GO
-- END SOURCE: Code/08_ServerHealth/130_USP_PerformanceCounters.sql

-- BEGIN SOURCE: Code/08_ServerHealth/140_USP_CriticalEngineEvents.sql
SET QUOTED_IDENTIFIER ON;
GO

/*
===============================================================================
Objekt       : monitor.USP_CriticalEngineEvents
Version      : 1.0.0
Stand        : 2026-07-17
Zweck        : Liest kritische Engine-Evidenz aus einem vorhandenen
               system_health-Eventfile und optional einmalig aus
               sys.sp_server_diagnostics.
Nebenwirkung : Keine XE- oder Serveränderung. Eventfiles werden nur gelesen.
               sp_server_diagnostics läuft ausschließlich als One-Shot.
Eigenlast    : Eventfile-Lesen MEDIUM und begrenzt; XML-Transfer opt-in.
===============================================================================
*/
CREATE OR ALTER PROCEDURE [monitor].[USP_CriticalEngineEvents]
      @SourceExtendedEventSessionName nvarchar(258) = N'system_health'
    , @FilePath                        nvarchar(4000) = NULL
    , @VonUtc                          datetime2(7)   = NULL
    , @BisUtc                          datetime2(7)   = NULL
    , @MinErrorSeverity                tinyint         = 20
    , @MitSystemHealth                 bit             = 1
    , @MitServerDiagnostics            bit             = 0
    , @MitEventXml                     bit             = 0
    , @MaxZeilen                       int             = 500
    , @ResultSetArt                    varchar(16)     = 'CONSOLE'
    , @ResultTablesJson               nvarchar(max) = NULL
    , @JsonErzeugen                    bit             = 0
    , @Json                            nvarchar(max)   = NULL OUTPUT
    , @PrintMeldungen                  bit             = 1
    , @Hilfe                           bit             = 0
    , @StatusCodeOut                   varchar(40)     = NULL OUTPUT
    , @IsPartialOut                    bit             = NULL OUTPUT
    , @ErrorNumberOut                  int             = NULL OUTPUT
    , @ErrorMessageOut                 nvarchar(2048)  = NULL OUTPUT
AS
BEGIN
    SET NOCOUNT ON;
    SET @Json = NULL;

    DECLARE @OutputMode varchar(16) =
        UPPER(LTRIM(RTRIM(COALESCE(@ResultSetArt, ''))));
    DECLARE @TableResultRequested bit = CASE WHEN @OutputMode = 'TABLE' THEN 1 ELSE 0 END;
    DECLARE @ConsoleResultRequested bit = CASE WHEN @OutputMode = 'CONSOLE' THEN 1 ELSE 0 END;
    DECLARE @TableTarget sysname=NULL;
    IF @TableResultRequested=0 AND NULLIF(LTRIM(RTRIM(COALESCE(@ResultTablesJson,N''))),N'') IS NOT NULL THROW 51011,N'@ResultTablesJson ist ausschließlich mit @ResultSetArt=TABLE zulässig.',1;
    IF @TableResultRequested=1 EXEC [monitor].[InternalPrepareSingleResultTable] @ResultTablesJson=@ResultTablesJson,@ResultName=N'events',@TargetTable=@TableTarget OUTPUT,@ThrowOnError=1;
    IF @TableResultRequested = 1 OR @ConsoleResultRequested = 1 SET @OutputMode = 'NONE';
    DECLARE @Limit bigint =
        CASE WHEN @MaxZeilen IS NULL OR @MaxZeilen = 0
             THEN CONVERT(bigint, 9223372036854775807)
             ELSE CONVERT(bigint, @MaxZeilen) END;
    DECLARE @SessionName sysname = NULL;

    IF @Hilfe = 1
    BEGIN
        PRINT N'monitor.USP_CriticalEngineEvents';
        PRINT N'@MitSystemHealth=1 liest nur vorhandene event_file-Targets; keine XE-Änderung.';
        PRINT N'@MitServerDiagnostics=0; 1 führt sys.sp_server_diagnostics einmalig ohne Repeat-Modus aus.';
        PRINT N'@MitEventXml=0 reduziert den Transfer; Runtime-Inhalte werden nicht persistiert.';
        PRINT N'@MinErrorSeverity=20; @VonUtc/@BisUtc begrenzen das Eventzeitfenster.';
        RETURN;
    END;

    IF @SourceExtendedEventSessionName IS NOT NULL
       AND (SELECT COUNT_BIG(*)
            FROM [monitor].[TVF_ParseSqlNameList](@SourceExtendedEventSessionName)
            WHERE [IsValid] = 1) = 1
       AND NOT EXISTS
           (SELECT 1
            FROM [monitor].[TVF_ParseSqlNameList](@SourceExtendedEventSessionName)
            WHERE [IsValid] = 0)
        SELECT @SessionName = MIN([NameValue])
        FROM [monitor].[TVF_ParseSqlNameList](@SourceExtendedEventSessionName)
        WHERE [IsValid] = 1;

    DECLARE @Now datetime2(3) = SYSUTCDATETIME();
    DECLARE @StatusCode varchar(40) = 'AVAILABLE';
    DECLARE @IsPartial bit = 0;
    DECLARE @ErrorNumber int = NULL;
    DECLARE @ErrorMessage nvarchar(2048) = NULL;
    DECLARE @MonitorPrintMessage nvarchar(2048) = NULL;
    DECLARE @ConfiguredFilePath nvarchar(4000) = NULL;
    DECLARE @ResolvedFilePath nvarchar(4000) = NULL;

    CREATE TABLE [#CriticalEngineEvents_Events]
    (
          [TimestampUtc] datetime2(7) NULL
        , [EventName] sysname NULL
        , [ErrorNumber] int NULL
        , [Severity] int NULL
        , [ComponentName] sysname NULL
        , [StateDesc] sysname NULL
        , [MessageText] nvarchar(4000) NULL
        , [FindingCode] varchar(100) NOT NULL
        , [EventXml] xml NULL
    );

    CREATE TABLE [#CriticalEngineEvents_Diagnostics]
    (
          [CreateTime] datetime NULL
        , [ComponentType] sysname NULL
        , [ComponentName] sysname NULL
        , [State] int NULL
        , [StateDesc] sysname NULL
        , [Data] xml NULL
    );

    CREATE TABLE [#CriticalEngineEvents_SourceStatus]
    (
          [SourceName] nvarchar(128) NOT NULL
        , [StatusCode] varchar(40) NOT NULL
        , [ErrorNumber] int NULL
        , [ErrorMessage] nvarchar(2048) NULL
        , [Detail] nvarchar(1000) NULL
    );

    IF @SessionName IS NULL
       OR @MaxZeilen < 0
       OR @MinErrorSeverity > 25
       OR (@VonUtc IS NOT NULL AND @BisUtc IS NOT NULL AND @VonUtc >= @BisUtc)
       OR (@MitSystemHealth = 0 AND @MitServerDiagnostics = 0)
       OR @OutputMode NOT IN ('RAW', 'CONSOLE', 'NONE')
    BEGIN
        SELECT @StatusCode = 'INVALID_PARAMETER',
               @IsPartial = 1,
               @ErrorMessage = N'Ungültige Session-, Zeit-, Severity-, Modul-, Zeilen- oder Ausgabeparameter.';
    END;

    SET LOCK_TIMEOUT 0;

    IF @StatusCode = 'AVAILABLE' AND @MitSystemHealth = 1
    BEGIN
        BEGIN TRY
            SELECT @ConfiguredFilePath = MAX(CONVERT(nvarchar(4000), [f].[value]))
            FROM [sys].[server_event_sessions] AS [s] WITH (NOLOCK)
            JOIN [sys].[server_event_session_targets] AS [t] WITH (NOLOCK)
              ON [t].[event_session_id] = [s].[event_session_id]
             AND [t].[name] = N'event_file'
            LEFT JOIN [sys].[server_event_session_fields] AS [f] WITH (NOLOCK)
              ON [f].[event_session_id] = [t].[event_session_id]
             AND [f].[object_id] = [t].[target_id]
             AND [f].[name] = N'filename'
            WHERE [s].[name] = @SessionName;

            SET @ResolvedFilePath = COALESCE(NULLIF(@FilePath, N''), NULLIF(@ConfiguredFilePath, N''));

            IF @ResolvedFilePath IS NULL
            BEGIN
                SET @IsPartial = 1;
                INSERT [#CriticalEngineEvents_SourceStatus]
                VALUES
                (
                      N'system_health event_file', 'UNAVAILABLE_OBJECT', NULL, NULL
                    , N'Kein lesbarer event_file-Pfad vorhanden; es wurde kein Ringbuffer gelesen.'
                );
            END
            ELSE
            BEGIN
                IF RIGHT(LOWER(@ResolvedFilePath), 4) = N'.xel'
                    SET @ResolvedFilePath =
                        LEFT(@ResolvedFilePath, LEN(@ResolvedFilePath) - 4) + N'*.xel';
                ELSE IF CHARINDEX(N'*', @ResolvedFilePath) = 0
                    SET @ResolvedFilePath = @ResolvedFilePath + N'*.xel';

                ;WITH [RawEvents] AS
                (
                    SELECT TOP (@Limit)
                          [r].[timestamp_utc] AS [TimestampUtc]
                        , [r].[object_name] AS [EventName]
                        , CONVERT(xml, [r].[event_data]) AS [EventXml]
                    FROM [sys].[fn_xe_file_target_read_file]
                         (@ResolvedFilePath, NULL, NULL, NULL) AS [r]
                    WHERE [r].[object_name] IN
                    (
                          N'error_reported'
                        , N'scheduler_monitor_non_yielding_ring_buffer_recorded'
                        , N'scheduler_monitor_non_yielding_iocp_ring_buffer_recorded'
                        , N'scheduler_monitor_stalled_dispatcher_ring_buffer_recorded'
                        , N'sp_server_diagnostics_component_result'
                        , N'memory_broker_ring_buffer_recorded'
                        , N'resource_monitor_ring_buffer_recorded'
                        , N'connectivity_ring_buffer_recorded'
                        , N'xml_deadlock_report'
                    )
                      AND (@VonUtc IS NULL OR [r].[timestamp_utc] >= @VonUtc)
                      AND (@BisUtc IS NULL OR [r].[timestamp_utc] < @BisUtc)
                    ORDER BY [r].[timestamp_utc] DESC, [r].[file_name] DESC, [r].[file_offset] DESC
                ),
                [Parsed] AS
                (
                    SELECT
                          [TimestampUtc], [EventName], [EventXml]
                        , [EventXml].value('(event/data[@name="error_number"]/value/text())[1]', 'int') AS [ErrorNumber]
                        , [EventXml].value('(event/data[@name="severity"]/value/text())[1]', 'int') AS [Severity]
                        , [EventXml].value('(event/data[@name="component_name"]/value/text())[1]', 'sysname') AS [ComponentName]
                        , [EventXml].value('(event/data[@name="state_desc"]/value/text())[1]', 'sysname') AS [StateDesc]
                        , [EventXml].value('(event/data[@name="message"]/value/text())[1]', 'nvarchar(4000)') AS [MessageText]
                    FROM [RawEvents]
                    WHERE [EventXml] IS NOT NULL
                )
                INSERT [#CriticalEngineEvents_Events]
                SELECT
                      [TimestampUtc], [EventName], [ErrorNumber], [Severity]
                    , [ComponentName], [StateDesc], [MessageText]
                    , CASE
                          WHEN [EventName] LIKE N'scheduler_monitor_non_yielding%' THEN 'NON_YIELDING_SCHEDULER'
                          WHEN [EventName] = N'scheduler_monitor_stalled_dispatcher_ring_buffer_recorded' THEN 'STALLED_DISPATCHER'
                          WHEN [EventName] = N'error_reported' THEN 'SEVERE_ERROR_REPORTED'
                          WHEN [EventName] = N'sp_server_diagnostics_component_result'
                           AND LOWER(COALESCE([StateDesc], N'')) IN (N'warning', N'error')
                              THEN 'SERVER_DIAGNOSTICS_WARNING_OR_ERROR'
                          WHEN [EventName] IN
                               (N'memory_broker_ring_buffer_recorded', N'resource_monitor_ring_buffer_recorded')
                              THEN 'MEMORY_OR_RESOURCE_MONITOR_EVENT'
                          WHEN [EventName] = N'connectivity_ring_buffer_recorded' THEN 'CONNECTIVITY_EVENT'
                          WHEN [EventName] = N'xml_deadlock_report' THEN 'DEADLOCK_EVENT'
                          ELSE 'CRITICAL_EVENT_REVIEW'
                      END
                    , CASE WHEN @MitEventXml = 1 THEN [EventXml] END
                FROM [Parsed]
                WHERE [EventName] <> N'error_reported'
                   OR COALESCE([Severity], 0) >= @MinErrorSeverity
                   OR [ErrorNumber] IN (701, 802, 823, 824, 825, 832, 833, 8645, 8651, 17803);

                INSERT [#CriticalEngineEvents_SourceStatus]
                VALUES
                (
                      N'system_health event_file', 'AVAILABLE', NULL, NULL
                    , N'Vorhandene Eventfiles wurden begrenzt und rein lesend ausgewertet.'
                );
            END;
        END TRY
        BEGIN CATCH
            SET @IsPartial = 1;
            INSERT [#CriticalEngineEvents_SourceStatus]
            VALUES
            (
                  N'system_health event_file'
                , CASE WHEN ERROR_NUMBER() IN (229, 262, 297, 300, 371) THEN 'DENIED_PERMISSION'
                       WHEN ERROR_NUMBER() IN(6335,6336,6337) THEN 'XML_UNAVAILABLE_LIMIT'
                       WHEN ERROR_NUMBER() BETWEEN 9400 AND 9431 THEN 'XML_INVALID'
                       ELSE 'ERROR_HANDLED' END
                , ERROR_NUMBER(), ERROR_MESSAGE()
                , N'Das Eventfile konnte nicht ausgewertet werden; andere Quellen bleiben verfügbar.'
            );
        END CATCH;
    END;

    IF @StatusCode = 'AVAILABLE' AND @MitServerDiagnostics = 1
    BEGIN
        BEGIN TRY
            INSERT [#CriticalEngineEvents_Diagnostics]
            EXEC [sys].[sp_server_diagnostics] 0;

            INSERT [#CriticalEngineEvents_SourceStatus]
            VALUES
            (
                  N'sp_server_diagnostics', 'AVAILABLE', NULL, NULL
                , N'One-Shot-Aufruf ohne Repeat-Modus; vollständige Daten können mindestens fünf Sekunden benötigen.'
            );
        END TRY
        BEGIN CATCH
            SET @IsPartial = 1;
            INSERT [#CriticalEngineEvents_SourceStatus]
            VALUES
            (
                  N'sp_server_diagnostics'
                , CASE WHEN ERROR_NUMBER() IN (229, 262, 297, 300, 371)
                       THEN 'DENIED_PERMISSION' ELSE 'ERROR_HANDLED' END
                , ERROR_NUMBER(), ERROR_MESSAGE()
                , N'One-Shot-Diagnose nicht verfügbar; kein Wiederholungsmodus gestartet.'
            );
        END CATCH;
    END;

    IF @StatusCode = 'AVAILABLE'
       AND (@IsPartial = 1 OR EXISTS
           (SELECT 1 FROM [#CriticalEngineEvents_SourceStatus] WHERE [StatusCode] <> 'AVAILABLE'))
        SET @StatusCode = 'AVAILABLE_LIMITED';
    ELSE IF @StatusCode = 'AVAILABLE'
        AND EXISTS (SELECT 1 FROM [#CriticalEngineEvents_Events])
        SET @StatusCode = 'AVAILABLE_WITH_FINDING';

    SELECT @StatusCodeOut = @StatusCode,
           @IsPartialOut = @IsPartial,
           @ErrorNumberOut = @ErrorNumber,
           @ErrorMessageOut = @ErrorMessage;

    IF @PrintMeldungen = 1 AND @StatusCode <> 'AVAILABLE'
    BEGIN
        SET @MonitorPrintMessage = COALESCE(@ErrorMessage, CONVERT(nvarchar(2048), @StatusCode));
        RAISERROR(N'USP_CriticalEngineEvents: %s', 10, 1, @MonitorPrintMessage) WITH NOWAIT;
    END;

    IF @OutputMode <> 'NONE'
    BEGIN
        SELECT CAST('1.0' AS varchar(16)) AS [ContractVersion], @Now AS [CollectionTimeUtc],
               N'monitor.USP_CriticalEngineEvents' AS [ModuleName],
               @StatusCode AS [StatusCode], @IsPartial AS [IsPartial],
               @ErrorNumber AS [ErrorNumber], @ErrorMessage AS [ErrorMessage];

        IF @OutputMode = 'RAW'
        BEGIN
            SELECT * FROM [#CriticalEngineEvents_Events] ORDER BY [TimestampUtc] DESC, [EventName];
            SELECT * FROM [#CriticalEngineEvents_Diagnostics] ORDER BY [CreateTime], [ComponentName];
            SELECT * FROM [#CriticalEngineEvents_SourceStatus] ORDER BY [SourceName];
        END
        ELSE
        BEGIN
            SELECT
                  N'Kritisches Engine-Ereignis' AS [Ergebnis]
                , [TimestampUtc] AS [Zeit UTC]
                , [FindingCode] AS [Bewertung]
                , [EventName] AS [Event]
                , [ErrorNumber] AS [Fehlernummer]
                , [Severity] AS [Severity]
                , [ComponentName] AS [Komponente]
                , [StateDesc] AS [Zustand]
                , [MessageText] AS [Meldung]
                , [EventXml] AS [Event XML]
            FROM [#CriticalEngineEvents_Events]
            ORDER BY [TimestampUtc] DESC, [EventName];

            SELECT
                  N'Server Diagnostics' AS [Ergebnis]
                , [CreateTime] AS [Zeit]
                , [ComponentType] AS [Komponententyp]
                , [ComponentName] AS [Komponente]
                , [StateDesc] AS [Zustand]
                , CASE WHEN @MitEventXml = 1 THEN [Data] END AS [Daten XML]
            FROM [#CriticalEngineEvents_Diagnostics]
            ORDER BY [CreateTime], [ComponentName];
        END;
    END;

    IF @JsonErzeugen = 1
    BEGIN
        DECLARE @MetaJson nvarchar(max) =
        (
            SELECT N'CriticalEngineEvents' AS [resultName], 1 AS [schemaVersion],
                   @Now AS [generatedAtUtc], @StatusCode AS [statusCode],
                   @IsPartial AS [isPartial], @ErrorNumber AS [errorNumber],
                   @ErrorMessage AS [errorMessage]
            FOR JSON PATH, WITHOUT_ARRAY_WRAPPER, INCLUDE_NULL_VALUES
        );
        DECLARE @EventsJson nvarchar(max) =
            (SELECT * FROM [#CriticalEngineEvents_Events] ORDER BY [TimestampUtc] DESC FOR JSON PATH, INCLUDE_NULL_VALUES);
        DECLARE @DiagnosticsJson nvarchar(max) =
            (SELECT [CreateTime], [ComponentType], [ComponentName], [State], [StateDesc],
                    CASE WHEN @MitEventXml = 1 THEN [Data] END AS [Data]
             FROM [#CriticalEngineEvents_Diagnostics] ORDER BY [CreateTime], [ComponentName]
             FOR JSON PATH, INCLUDE_NULL_VALUES);
        DECLARE @SourcesJson nvarchar(max) =
            (SELECT * FROM [#CriticalEngineEvents_SourceStatus] ORDER BY [SourceName] FOR JSON PATH, INCLUDE_NULL_VALUES);

        SET @Json = CONCAT
        (
              N'{"meta":', COALESCE(@MetaJson, N'{}')
            , N',"events":', COALESCE(@EventsJson, N'[]')
            , N',"serverDiagnostics":', COALESCE(@DiagnosticsJson, N'[]')
            , N',"sources":', COALESCE(@SourcesJson, N'[]')
            , N',"warnings":[]}'
        );
    END;
    IF @ConsoleResultRequested = 1
    BEGIN
        EXEC [monitor].[InternalEmitConsoleResult]
              @SourceTable=N'#CriticalEngineEvents_Events'
            , @ResultLabel=N'CriticalEngineEvents'
            , @EmptyMessage=N'Keine fachlichen Ergebnisse';
    END;
    IF @TableResultRequested = 1
    BEGIN
        EXEC [monitor].[InternalWriteResultTable]
              @SourceTable = N'#CriticalEngineEvents_Events'
            , @TargetTable=@TableTarget
            , @ThrowOnError = 1;
    END;
END;
GO
-- END SOURCE: Code/08_ServerHealth/140_USP_CriticalEngineEvents.sql

-- BEGIN SOURCE: Code/08_ServerHealth/150_USP_InternalContentionAnalysis.sql
/*
===============================================================================
Objekt       : monitor.USP_InternalContentionAnalysis
Version      : 1.0.0
Stand        : 2026-07-17
Zweck        : Misst Latch-/Spinlock-Deltas und aktuelle Hot-Page-Wartevorgänge.
Datenquellen : sys.dm_os_latch_stats, sys.dm_os_spinlock_stats,
               sys.dm_exec_requests, sys.dm_os_sys_info und optional
               sys.dm_db_page_info.
Methodik     : @SampleSeconds>0 liefert ein Intervall-Delta. Bei 0 werden
               kumulative Werte seit SQL-Server-Start eindeutig gekennzeichnet.
Grenzen      : Korrelation ist Evidenz, keine automatische Ursachenfeststellung.
===============================================================================
*/
CREATE OR ALTER PROCEDURE [monitor].[USP_InternalContentionAnalysis]
      @SampleSeconds     tinyint        = 5
    , @MitSpinlocks      bit            = 1
    , @MitHotPages       bit            = 1
    , @MitPageDetails    bit            = 0
    , @MaxZeilen         int            = 100
    , @ResultSetArt      varchar(16)    = 'CONSOLE'
    , @ResultTablesJson               nvarchar(max) = NULL
    , @JsonErzeugen      bit            = 0
    , @Json              nvarchar(max)  = NULL OUTPUT
    , @PrintMeldungen    bit            = 1
    , @Hilfe             bit            = 0
    , @StatusCodeOut     varchar(40)    = NULL OUTPUT
    , @IsPartialOut      bit            = NULL OUTPUT
    , @ErrorNumberOut    int            = NULL OUTPUT
    , @ErrorMessageOut   nvarchar(2048) = NULL OUTPUT
AS
BEGIN
    SET NOCOUNT ON;
    SET LOCK_TIMEOUT 0;
    SET @Json = NULL;

    DECLARE @OutputMode varchar(16) = UPPER(LTRIM(RTRIM(COALESCE(@ResultSetArt, ''))));
    DECLARE @TableResultRequested bit = CASE WHEN @OutputMode = 'TABLE' THEN 1 ELSE 0 END;
    DECLARE @ConsoleResultRequested bit = CASE WHEN @OutputMode = 'CONSOLE' THEN 1 ELSE 0 END;
    DECLARE @TableTarget sysname=NULL;
    IF @TableResultRequested=0 AND NULLIF(LTRIM(RTRIM(COALESCE(@ResultTablesJson,N''))),N'') IS NOT NULL THROW 51011,N'@ResultTablesJson ist ausschließlich mit @ResultSetArt=TABLE zulässig.',1;
    IF @TableResultRequested=1 EXEC [monitor].[InternalPrepareSingleResultTable] @ResultTablesJson=@ResultTablesJson,@ResultName=N'latches',@TargetTable=@TableTarget OUTPUT,@ThrowOnError=1;
    IF @TableResultRequested = 1 OR @ConsoleResultRequested = 1 SET @OutputMode = 'NONE';
    DECLARE @Limit bigint = CASE WHEN @MaxZeilen IS NULL OR @MaxZeilen = 0
                                 THEN CONVERT(bigint, 9223372036854775807)
                                 ELSE CONVERT(bigint, @MaxZeilen) END;

    IF @Hilfe = 1
    BEGIN
        PRINT N'monitor.USP_InternalContentionAnalysis';
        PRINT N'@SampleSeconds=0..60; 0 zeigt kumulative Werte, >0 misst Deltas.';
        PRINT N'@MitPageDetails=1 löst ausschließlich aktuell wartende Seiten über sys.dm_db_page_info auf.';
        PRINT N'@MaxZeilen positiv; NULL/0 = unbegrenzt. @ResultSetArt=CONSOLE|RAW|TABLE|NONE; TABLE verwendet @ResultTablesJson.';
        RETURN;
    END;

    DECLARE @Now datetime2(3) = SYSUTCDATETIME();
    DECLARE @SampleStartUtc datetime2(3) = @Now;
    DECLARE @SampleEndUtc datetime2(3) = @Now;
    DECLARE @SqlServerStartTime datetime2(3) = NULL;
    DECLARE @ActualSampleSeconds decimal(19,6) = 0;
    DECLARE @StatusCode varchar(40) = 'AVAILABLE';
    DECLARE @IsPartial bit = 0;
    DECLARE @ErrorNumber int = NULL;
    DECLARE @ErrorMessage nvarchar(2048) = NULL;
    DECLARE @Delay varchar(8);

    CREATE TABLE [#InternalContentionAnalysis_LatchStart]
    (
          [LatchClass] nvarchar(120) NOT NULL
        , [WaitingRequestsCount] bigint NOT NULL
        , [WaitTimeMs] bigint NOT NULL
        , [MaxWaitTimeMs] bigint NOT NULL
    );
    CREATE TABLE [#InternalContentionAnalysis_LatchEnd]
    (
          [LatchClass] nvarchar(120) NOT NULL
        , [WaitingRequestsCount] bigint NOT NULL
        , [WaitTimeMs] bigint NOT NULL
        , [MaxWaitTimeMs] bigint NOT NULL
    );
    CREATE TABLE [#InternalContentionAnalysis_SpinStart]
    (
          [SpinlockName] nvarchar(256) NOT NULL
        , [Collisions] bigint NOT NULL
        , [Spins] bigint NOT NULL
        , [SleepTime] bigint NOT NULL
        , [Backoffs] bigint NOT NULL
    );
    CREATE TABLE [#InternalContentionAnalysis_SpinEnd]
    (
          [SpinlockName] nvarchar(256) NOT NULL
        , [Collisions] bigint NOT NULL
        , [Spins] bigint NOT NULL
        , [SleepTime] bigint NOT NULL
        , [Backoffs] bigint NOT NULL
    );
    CREATE TABLE [#InternalContentionAnalysis_LatchResult]
    (
          [LatchClass] nvarchar(120) NOT NULL
        , [MeasurementKind] varchar(30) NOT NULL
        , [WaitingRequests] bigint NULL
        , [WaitTimeMs] bigint NULL
        , [MaxObservedWaitTimeMs] bigint NULL
        , [WaitsPerSecond] decimal(19,4) NULL
        , [WaitMsPerSecond] decimal(19,4) NULL
        , [CounterResetDetected] bit NOT NULL
    );
    CREATE TABLE [#InternalContentionAnalysis_SpinResult]
    (
          [SpinlockName] nvarchar(256) NOT NULL
        , [MeasurementKind] varchar(30) NOT NULL
        , [Collisions] bigint NULL
        , [Spins] bigint NULL
        , [SleepTime] bigint NULL
        , [Backoffs] bigint NULL
        , [CollisionsPerSecond] decimal(19,4) NULL
        , [BackoffsPerSecond] decimal(19,4) NULL
        , [CounterResetDetected] bit NOT NULL
    );
    CREATE TABLE [#InternalContentionAnalysis_HotPages]
    (
          [SessionId] smallint NOT NULL
        , [DatabaseId] int NULL
        , [DatabaseName] sysname NULL
        , [WaitType] nvarchar(60) NULL
        , [WaitTimeMs] int NULL
        , [WaitResource] nvarchar(256) NULL
        , [FileId] int NULL
        , [PageId] bigint NULL
        , [PageTypeDesc] nvarchar(64) NULL
        , [ObjectId] int NULL
        , [IndexId] int NULL
    );

    IF @SampleSeconds > 60
       OR @MaxZeilen < 0
       OR @OutputMode NOT IN ('RAW', 'CONSOLE', 'NONE')
       OR (@MitPageDetails = 1 AND @MitHotPages = 0)
    BEGIN
        SELECT @StatusCode = 'INVALID_PARAMETER', @IsPartial = 1,
               @ErrorMessage = N'Ungültiger Sample-, Zeilen-, Detail- oder Ausgabeparameter.';
    END;

    IF @StatusCode = 'AVAILABLE'
    BEGIN
        BEGIN TRY
            SELECT @SqlServerStartTime = [sqlserver_start_time]
            FROM [sys].[dm_os_sys_info] WITH (NOLOCK);

            INSERT [#InternalContentionAnalysis_LatchStart]
            SELECT [latch_class], [waiting_requests_count], [wait_time_ms], [max_wait_time_ms]
            FROM [sys].[dm_os_latch_stats] WITH (NOLOCK);

            IF @MitSpinlocks = 1
            BEGIN
                INSERT [#InternalContentionAnalysis_SpinStart]
                SELECT [name], [collisions], [spins], [sleep_time], [backoffs]
                FROM [sys].[dm_os_spinlock_stats] WITH (NOLOCK);
            END;

            SET @SampleStartUtc = SYSUTCDATETIME();
            IF @SampleSeconds > 0
            BEGIN
                SET @Delay = CONVERT(varchar(8),
                    DATEADD(SECOND,@SampleSeconds,CONVERT(datetime,'19000101')),108);
                WAITFOR DELAY @Delay;
            END;
            SET @SampleEndUtc = SYSUTCDATETIME();
            SET @ActualSampleSeconds = CONVERT
            (
                decimal(19,6),
                DATEDIFF_BIG(MICROSECOND, @SampleStartUtc, @SampleEndUtc) / 1000000.0
            );

            INSERT [#InternalContentionAnalysis_LatchEnd]
            SELECT [latch_class], [waiting_requests_count], [wait_time_ms], [max_wait_time_ms]
            FROM [sys].[dm_os_latch_stats] WITH (NOLOCK);

            IF @MitSpinlocks = 1
            BEGIN
                INSERT [#InternalContentionAnalysis_SpinEnd]
                SELECT [name], [collisions], [spins], [sleep_time], [backoffs]
                FROM [sys].[dm_os_spinlock_stats] WITH (NOLOCK);
            END;

            ;WITH [LatchStart] AS
            (
                SELECT [LatchClass],SUM([WaitingRequestsCount]) AS [WaitingRequestsCount],
                       SUM([WaitTimeMs]) AS [WaitTimeMs],MAX([MaxWaitTimeMs]) AS [MaxWaitTimeMs]
                FROM [#InternalContentionAnalysis_LatchStart] GROUP BY [LatchClass]
            ),
            [LatchEnd] AS
            (
                SELECT [LatchClass],SUM([WaitingRequestsCount]) AS [WaitingRequestsCount],
                       SUM([WaitTimeMs]) AS [WaitTimeMs],MAX([MaxWaitTimeMs]) AS [MaxWaitTimeMs]
                FROM [#InternalContentionAnalysis_LatchEnd] GROUP BY [LatchClass]
            )
            INSERT [#InternalContentionAnalysis_LatchResult]
            SELECT
                  [e].[LatchClass]
                , CASE WHEN @SampleSeconds = 0 THEN 'CUMULATIVE_SINCE_START' ELSE 'SAMPLE_DELTA' END
                , [Waiting].[CounterValue]
                , [WaitTime].[CounterValue]
                , [e].[MaxWaitTimeMs]
                , [Waiting].[RatePerSecond]
                , [WaitTime].[RatePerSecond]
                , CONVERT(bit,CASE WHEN [Waiting].[CounterResetDetected]=1
                                      OR [WaitTime].[CounterResetDetected]=1 THEN 1 ELSE 0 END)
            FROM [LatchEnd] AS [e]
            JOIN [LatchStart] AS [s] ON [s].[LatchClass] = [e].[LatchClass]
            CROSS APPLY [monitor].[TVF_InterpretContentionCounter]
            ([s].[WaitingRequestsCount],[e].[WaitingRequestsCount],@SampleSeconds,@ActualSampleSeconds) AS [Waiting]
            CROSS APPLY [monitor].[TVF_InterpretContentionCounter]
            ([s].[WaitTimeMs],[e].[WaitTimeMs],@SampleSeconds,@ActualSampleSeconds) AS [WaitTime]
            WHERE (@SampleSeconds = 0 AND [e].[WaitTimeMs] > 0)
               OR (@SampleSeconds > 0 AND ([e].[WaitTimeMs] <> [s].[WaitTimeMs]
                                           OR [e].[WaitingRequestsCount] <> [s].[WaitingRequestsCount]));

            IF @MitSpinlocks = 1
            BEGIN
                ;WITH [SpinStart] AS
                (
                    SELECT [SpinlockName],SUM([Collisions]) AS [Collisions],SUM([Spins]) AS [Spins],
                           SUM([SleepTime]) AS [SleepTime],SUM([Backoffs]) AS [Backoffs]
                    FROM [#InternalContentionAnalysis_SpinStart] GROUP BY [SpinlockName]
                ),
                [SpinEnd] AS
                (
                    SELECT [SpinlockName],SUM([Collisions]) AS [Collisions],SUM([Spins]) AS [Spins],
                           SUM([SleepTime]) AS [SleepTime],SUM([Backoffs]) AS [Backoffs]
                    FROM [#InternalContentionAnalysis_SpinEnd] GROUP BY [SpinlockName]
                )
                INSERT [#InternalContentionAnalysis_SpinResult]
                SELECT
                      [e].[SpinlockName]
                    , CASE WHEN @SampleSeconds = 0 THEN 'CUMULATIVE_SINCE_START' ELSE 'SAMPLE_DELTA' END
                    , [Collision].[CounterValue]
                    , [Spin].[CounterValue]
                    , [Sleep].[CounterValue]
                    , [Backoff].[CounterValue]
                    , [Collision].[RatePerSecond]
                    , [Backoff].[RatePerSecond]
                    , CONVERT(bit,CASE WHEN [Collision].[CounterResetDetected]=1
                                           OR [Spin].[CounterResetDetected]=1
                                           OR [Sleep].[CounterResetDetected]=1
                                           OR [Backoff].[CounterResetDetected]=1 THEN 1 ELSE 0 END)
                FROM [SpinEnd] AS [e]
                JOIN [SpinStart] AS [s] ON [s].[SpinlockName] = [e].[SpinlockName]
                CROSS APPLY [monitor].[TVF_InterpretContentionCounter]
                ([s].[Collisions],[e].[Collisions],@SampleSeconds,@ActualSampleSeconds) AS [Collision]
                CROSS APPLY [monitor].[TVF_InterpretContentionCounter]
                ([s].[Spins],[e].[Spins],@SampleSeconds,@ActualSampleSeconds) AS [Spin]
                CROSS APPLY [monitor].[TVF_InterpretContentionCounter]
                ([s].[SleepTime],[e].[SleepTime],@SampleSeconds,@ActualSampleSeconds) AS [Sleep]
                CROSS APPLY [monitor].[TVF_InterpretContentionCounter]
                ([s].[Backoffs],[e].[Backoffs],@SampleSeconds,@ActualSampleSeconds) AS [Backoff]
                WHERE (@SampleSeconds = 0 AND [e].[Collisions] > 0)
                   OR (@SampleSeconds > 0 AND ([e].[Collisions] <> [s].[Collisions]
                                               OR [e].[Spins] <> [s].[Spins]
                                               OR [e].[SleepTime] <> [s].[SleepTime]
                                               OR [e].[Backoffs] <> [s].[Backoffs]));
            END;

            IF @MitHotPages = 1
            BEGIN
                INSERT [#InternalContentionAnalysis_HotPages]
                (
                      [SessionId], [DatabaseId], [DatabaseName], [WaitType]
                    , [WaitTimeMs], [WaitResource], [FileId], [PageId]
                )
                SELECT
                      [r].[session_id], [r].[database_id], (SELECT [name] FROM [master].[sys].[databases] WITH (NOLOCK) WHERE [database_id] = [r].[database_id])
                    , [r].[wait_type], [r].[wait_time], [r].[wait_resource]
                    , TRY_CONVERT(int, PARSENAME(REPLACE([r].[wait_resource], N':', N'.'), 2))
                    , TRY_CONVERT(bigint, PARSENAME(REPLACE([r].[wait_resource], N':', N'.'), 1))
                FROM [sys].[dm_exec_requests] AS [r] WITH (NOLOCK)
                WHERE [r].[session_id] <> @@SPID
                  AND ([r].[wait_type] LIKE N'PAGELATCH%'
                       OR [r].[wait_type] LIKE N'PAGEIOLATCH%');

                IF @MitPageDetails = 1
                BEGIN
                    UPDATE [h]
                    SET [PageTypeDesc] = [p].[page_type_desc],
                        [ObjectId] = [p].[object_id],
                        [IndexId] = [p].[index_id]
                    FROM [#InternalContentionAnalysis_HotPages] AS [h]
                    OUTER APPLY [sys].[dm_db_page_info]
                    ([h].[DatabaseId], [h].[FileId], [h].[PageId], 'LIMITED') AS [p]
                    WHERE [h].[DatabaseId] IS NOT NULL
                      AND [h].[FileId] IS NOT NULL
                      AND [h].[PageId] IS NOT NULL;
                END;
            END;
        END TRY
        BEGIN CATCH
            SELECT @StatusCode = CASE WHEN ERROR_NUMBER() IN (229, 297, 300, 371)
                                      THEN 'DENIED_PERMISSION' ELSE 'ERROR_HANDLED' END,
                   @IsPartial = 1, @ErrorNumber = ERROR_NUMBER(),
                   @ErrorMessage = ERROR_MESSAGE();
        END CATCH;
    END;

    IF @StatusCode = 'AVAILABLE'
       AND EXISTS
           (
               SELECT 1 FROM [#InternalContentionAnalysis_LatchResult] WHERE [CounterResetDetected] = 1
               UNION ALL
               SELECT 1 FROM [#InternalContentionAnalysis_SpinResult] WHERE [CounterResetDetected] = 1
               UNION ALL
               SELECT 1 FROM [#InternalContentionAnalysis_HotPages]
           )
        SET @StatusCode = 'AVAILABLE_WITH_FINDING';

    SELECT @StatusCodeOut = @StatusCode, @IsPartialOut = @IsPartial,
           @ErrorNumberOut = @ErrorNumber, @ErrorMessageOut = @ErrorMessage;

    IF @JsonErzeugen = 1
    BEGIN
        DECLARE @MetaJson nvarchar(max) =
            (SELECT N'InternalContentionAnalysis' AS [resultName], 1 AS [schemaVersion],
                    @Now AS [generatedAtUtc], @StatusCode AS [statusCode], @IsPartial AS [isPartial],
                    @SampleSeconds AS [requestedSampleSeconds], @ActualSampleSeconds AS [actualSampleSeconds],
                    @SqlServerStartTime AS [sqlServerStartTime]
             FOR JSON PATH, WITHOUT_ARRAY_WRAPPER, INCLUDE_NULL_VALUES);
        DECLARE @LatchJson nvarchar(max) =
            (SELECT TOP (@Limit) * FROM [#InternalContentionAnalysis_LatchResult]
             ORDER BY [WaitTimeMs] DESC, [LatchClass] FOR JSON PATH, INCLUDE_NULL_VALUES);
        DECLARE @SpinJson nvarchar(max) =
            (SELECT TOP (@Limit) * FROM [#InternalContentionAnalysis_SpinResult]
             ORDER BY [Collisions] DESC, [SpinlockName] FOR JSON PATH, INCLUDE_NULL_VALUES);
        DECLARE @HotJson nvarchar(max) =
            (SELECT TOP (@Limit) * FROM [#InternalContentionAnalysis_HotPages]
             ORDER BY [WaitTimeMs] DESC, [SessionId] FOR JSON PATH, INCLUDE_NULL_VALUES);
        SET @Json = CONCAT(N'{"meta":', COALESCE(@MetaJson, N'{}'),
                           N',"latches":', COALESCE(@LatchJson, N'[]'),
                           N',"spinlocks":', COALESCE(@SpinJson, N'[]'),
                           N',"hotPages":', COALESCE(@HotJson, N'[]'), N'}');
    END;

    IF @OutputMode = 'RAW'
    BEGIN
        SELECT N'USP_InternalContentionAnalysis' AS [ModuleName], @Now AS [CollectionTimeUtc],
               @StatusCode AS [StatusCode], @IsPartial AS [IsPartial],
               @SampleSeconds AS [RequestedSampleSeconds], @ActualSampleSeconds AS [ActualSampleSeconds],
               @SqlServerStartTime AS [SqlServerStartTime],
               @ErrorNumber AS [ErrorNumber], @ErrorMessage AS [ErrorMessage],
               N'Intervalldeltas bei SampleSeconds>0; sonst kumulativ seit Serverstart.' AS [Detail];
        SELECT TOP (@Limit) * FROM [#InternalContentionAnalysis_LatchResult] ORDER BY [WaitTimeMs] DESC, [LatchClass];
        SELECT TOP (@Limit) * FROM [#InternalContentionAnalysis_SpinResult] ORDER BY [Collisions] DESC, [SpinlockName];
        SELECT TOP (@Limit) * FROM [#InternalContentionAnalysis_HotPages] ORDER BY [WaitTimeMs] DESC, [SessionId];
    END
    ELSE IF @OutputMode = 'CONSOLE'
    BEGIN
        SELECT N'Interne Contention' AS [Ergebnis], @Now AS [Stand_UTC], @StatusCode AS [Status],
               @SampleSeconds AS [Angeforderte_Messdauer_Sekunden],
               @ActualSampleSeconds AS [Tatsaechliche_Messdauer_Sekunden],
               CASE WHEN @SampleSeconds = 0 THEN N'Kumulativ seit Serverstart' ELSE N'Intervall-Delta' END AS [Messart],
               @ErrorMessage AS [Hinweis];
        SELECT TOP (@Limit) N'Latch' AS [Ergebnis], [LatchClass] AS [Klasse],
               [WaitingRequests] AS [Wartevorgaenge], [WaitTimeMs] AS [Wartezeit_ms],
               [WaitsPerSecond] AS [Wartevorgaenge_pro_s], [WaitMsPerSecond] AS [Wartezeit_ms_pro_s],
               [CounterResetDetected] AS [Reset_erkannt]
        FROM [#InternalContentionAnalysis_LatchResult] ORDER BY [WaitTimeMs] DESC, [LatchClass];
        SELECT TOP (@Limit) N'Spinlock' AS [Ergebnis], [SpinlockName] AS [Name],
               [Collisions], [Backoffs], [CollisionsPerSecond] AS [Kollisionen_pro_s],
               [BackoffsPerSecond] AS [Backoffs_pro_s], [CounterResetDetected] AS [Reset_erkannt]
        FROM [#InternalContentionAnalysis_SpinResult] ORDER BY [Collisions] DESC, [SpinlockName];
        SELECT TOP (@Limit) N'Hot Page' AS [Ergebnis], [SessionId] AS [Session_ID],
               [DatabaseName] AS [Datenbank], [WaitType] AS [Wait_Typ], [WaitTimeMs] AS [Wartezeit_ms],
               [FileId] AS [Datei_ID], [PageId] AS [Seiten_ID], [PageTypeDesc] AS [Seitentyp],
               [ObjectId] AS [Objekt_ID], [IndexId] AS [Index_ID]
        FROM [#InternalContentionAnalysis_HotPages] ORDER BY [WaitTimeMs] DESC, [SessionId];
    END;
    IF @ConsoleResultRequested = 1
    BEGIN
        EXEC [monitor].[InternalEmitConsoleResult]
              @SourceTable=N'#InternalContentionAnalysis_LatchResult'
            , @ResultLabel=N'InternalContentionAnalysis'
            , @EmptyMessage=N'Keine fachlichen Ergebnisse';
    END;
    IF @TableResultRequested = 1
    BEGIN
        EXEC [monitor].[InternalWriteResultTable]
              @SourceTable = N'#InternalContentionAnalysis_LatchResult'
            , @TargetTable=@TableTarget
            , @ThrowOnError = 1;
    END;
END;
GO
-- END SOURCE: Code/08_ServerHealth/150_USP_InternalContentionAnalysis.sql

-- BEGIN SOURCE: Code/08_ServerHealth/160_USP_BufferPoolAnalysis.sql
/*
===============================================================================
Objekt       : monitor.USP_BufferPoolAnalysis
Version      : 1.0.0
Stand        : 2026-07-17
Zweck        : Liefert eine korrelierte Momentaufnahme von Prozess-,
               Betriebssystem-, Resource-Semaphore-, Memory-Clerk- und
               Buffer-Pool-Evidenz.
Datenquellen : sys.dm_os_process_memory, sys.dm_os_sys_memory,
               sys.dm_exec_query_resource_semaphores,
               sys.dm_os_memory_clerks und optional sys.dm_os_buffer_descriptors.
Kosten       : Basis LOW; Buffer-Pool-Verteilung kann auf großen Instanzen HIGH
               sein und ist deshalb standardmäßig deaktiviert.
Grenzen      : Eine Momentaufnahme beweist keinen Trend und berechnet keine
               automatische max-server-memory-Empfehlung.
===============================================================================
*/
CREATE OR ALTER PROCEDURE [monitor].[USP_BufferPoolAnalysis]
      @MitMemoryClerks          bit            = 1
    , @MitBufferPoolVerteilung  bit            = 0
    , @MaxZeilen                int            = 100
    , @ResultSetArt             varchar(16)    = 'CONSOLE'
    , @ResultTablesJson               nvarchar(max) = NULL
    , @JsonErzeugen             bit            = 0
    , @Json                     nvarchar(max)  = NULL OUTPUT
    , @PrintMeldungen           bit            = 1
    , @Hilfe                    bit            = 0
    , @StatusCodeOut            varchar(40)    = NULL OUTPUT
    , @IsPartialOut             bit            = NULL OUTPUT
    , @ErrorNumberOut           int            = NULL OUTPUT
    , @ErrorMessageOut          nvarchar(2048) = NULL OUTPUT
AS
BEGIN
    SET NOCOUNT ON;
    SET LOCK_TIMEOUT 0;
    SET @Json = NULL;

    DECLARE @OutputMode varchar(16) = UPPER(LTRIM(RTRIM(COALESCE(@ResultSetArt, ''))));
    DECLARE @TableResultRequested bit = CASE WHEN @OutputMode = 'TABLE' THEN 1 ELSE 0 END;
    DECLARE @ConsoleResultRequested bit = CASE WHEN @OutputMode = 'CONSOLE' THEN 1 ELSE 0 END;
    DECLARE @TableTarget sysname=NULL;
    IF @TableResultRequested=0 AND NULLIF(LTRIM(RTRIM(COALESCE(@ResultTablesJson,N''))),N'') IS NOT NULL THROW 51011,N'@ResultTablesJson ist ausschließlich mit @ResultSetArt=TABLE zulässig.',1;
    IF @TableResultRequested=1 EXEC [monitor].[InternalPrepareSingleResultTable] @ResultTablesJson=@ResultTablesJson,@ResultName=N'memory',@TargetTable=@TableTarget OUTPUT,@ThrowOnError=1;
    IF @TableResultRequested = 1 OR @ConsoleResultRequested = 1 SET @OutputMode = 'NONE';
    DECLARE @Limit bigint = CASE WHEN @MaxZeilen IS NULL OR @MaxZeilen = 0
                                 THEN CONVERT(bigint, 9223372036854775807)
                                 ELSE CONVERT(bigint, @MaxZeilen) END;

    IF @Hilfe = 1
    BEGIN
        PRINT N'monitor.USP_BufferPoolAnalysis';
        PRINT N'Die Procedure liefert eine korrelierte Momentaufnahme, aber keine Trend- oder Konfigurationsempfehlung.';
        PRINT N'@MitBufferPoolVerteilung=0 ist der sichere Standard; 1 scannt sys.dm_os_buffer_descriptors.';
        PRINT N'@MaxZeilen positiv; NULL/0 = unbegrenzt. @ResultSetArt=CONSOLE|RAW|TABLE|NONE; TABLE verwendet @ResultTablesJson.';
        RETURN;
    END;

    DECLARE @Now datetime2(3) = SYSUTCDATETIME();
    DECLARE @StatusCode varchar(40) = 'AVAILABLE';
    DECLARE @IsPartial bit = 0;
    DECLARE @ErrorNumber int = NULL;
    DECLARE @ErrorMessage nvarchar(2048) = NULL;

    CREATE TABLE [#BufferPoolAnalysis_MemorySnapshot]
    (
          [PhysicalMemoryInUseKb] bigint NULL
        , [LockedPageAllocationsKb] bigint NULL
        , [LargePageAllocationsKb] bigint NULL
        , [MemoryUtilizationPercent] int NULL
        , [AvailableCommitLimitKb] bigint NULL
        , [ProcessPhysicalMemoryLow] bit NULL
        , [ProcessVirtualMemoryLow] bit NULL
        , [TotalPhysicalMemoryKb] bigint NULL
        , [AvailablePhysicalMemoryKb] bigint NULL
        , [AvailablePhysicalMemoryPercent] decimal(9,2) NULL
        , [SystemMemoryStateDesc] nvarchar(256) NULL
        , [FindingCode] varchar(80) NOT NULL
        , [FindingSeverity] varchar(16) NOT NULL
        , [EvidenceLimit] nvarchar(1000) NOT NULL
    );
    CREATE TABLE [#BufferPoolAnalysis_ResourceSemaphores]
    (
          [PoolId] int NULL
        , [ResourceSemaphoreId] smallint NULL
        , [TotalMemoryKb] bigint NULL
        , [AvailableMemoryKb] bigint NULL
        , [GrantedMemoryKb] bigint NULL
        , [UsedMemoryKb] bigint NULL
        , [GranteeCount] int NULL
        , [WaiterCount] int NULL
        , [TimeoutErrorCount] bigint NULL
        , [ForcedGrantCount] bigint NULL
    );
    CREATE TABLE [#BufferPoolAnalysis_MemoryClerks]
    (
          [ClerkType] nvarchar(60) NOT NULL
        , [PagesKb] bigint NULL
        , [VirtualMemoryReservedKb] bigint NULL
        , [VirtualMemoryCommittedKb] bigint NULL
        , [LockedOrAweKb] bigint NULL
        , [ClerkCount] bigint NOT NULL
    );
    CREATE TABLE [#BufferPoolAnalysis_BufferPool]
    (
          [DatabaseId] int NOT NULL
        , [DatabaseName] sysname NULL
        , [CachedPages] bigint NOT NULL
        , [CachedSizeMb] decimal(19,2) NOT NULL
        , [DirtyPages] bigint NOT NULL
        , [DirtySizeMb] decimal(19,2) NOT NULL
        , [FreeSpaceMb] decimal(19,2) NOT NULL
        , [NumaNodeCount] bigint NOT NULL
    );

    IF @MaxZeilen < 0 OR @OutputMode NOT IN ('RAW', 'CONSOLE', 'NONE')
    BEGIN
        SELECT @StatusCode = 'INVALID_PARAMETER', @IsPartial = 1,
               @ErrorMessage = N'Ungültiger Zeilen- oder Ausgabeparameter.';
    END;

    IF @StatusCode = 'AVAILABLE'
    BEGIN
        BEGIN TRY
            INSERT [#BufferPoolAnalysis_MemorySnapshot]
            SELECT
                  [p].[physical_memory_in_use_kb]
                , [p].[locked_page_allocations_kb]
                , [p].[large_page_allocations_kb]
                , [p].[memory_utilization_percentage]
                , [p].[available_commit_limit_kb]
                , [p].[process_physical_memory_low]
                , [p].[process_virtual_memory_low]
                , [s].[total_physical_memory_kb]
                , [s].[available_physical_memory_kb]
                , CONVERT(decimal(9,2), 100.0 * [s].[available_physical_memory_kb]
                  / NULLIF([s].[total_physical_memory_kb], 0))
                , [s].[system_memory_state_desc]
                , CASE WHEN [p].[process_physical_memory_low] = 1 THEN 'PROCESS_PHYSICAL_MEMORY_LOW'
                       WHEN [p].[process_virtual_memory_low] = 1 THEN 'PROCESS_VIRTUAL_MEMORY_LOW'
                       WHEN [s].[available_physical_memory_kb] * 100.0
                            / NULLIF([s].[total_physical_memory_kb], 0) < 5 THEN 'OS_AVAILABLE_MEMORY_BELOW_5_PERCENT'
                       ELSE 'NO_MEMORY_PRESSURE_FLAG' END
                , CASE WHEN [p].[process_physical_memory_low] = 1
                            OR [p].[process_virtual_memory_low] = 1 THEN 'HIGH'
                       WHEN [s].[available_physical_memory_kb] * 100.0
                            / NULLIF([s].[total_physical_memory_kb], 0) < 5 THEN 'MEDIUM'
                       ELSE 'INFO' END
                , N'Momentaufnahme; Verlauf, andere Prozesse und Betriebssystemgrenzen separat prüfen.'
            FROM [sys].[dm_os_process_memory] AS [p] WITH (NOLOCK)
            CROSS JOIN [sys].[dm_os_sys_memory] AS [s] WITH (NOLOCK);

            INSERT [#BufferPoolAnalysis_ResourceSemaphores]
            SELECT
                  [pool_id], [resource_semaphore_id], [total_memory_kb]
                , [available_memory_kb], [granted_memory_kb], [used_memory_kb]
                , [grantee_count], [waiter_count], [timeout_error_count]
                , [forced_grant_count]
            FROM [sys].[dm_exec_query_resource_semaphores] WITH (NOLOCK);
        END TRY
        BEGIN CATCH
            SELECT @StatusCode = CASE WHEN ERROR_NUMBER() IN (229, 297, 300, 371)
                                      THEN 'DENIED_PERMISSION' ELSE 'ERROR_HANDLED' END,
                   @IsPartial = 1, @ErrorNumber = ERROR_NUMBER(), @ErrorMessage = ERROR_MESSAGE();
        END CATCH;

        IF @StatusCode IN ('AVAILABLE', 'AVAILABLE_LIMITED') AND @MitMemoryClerks = 1
        BEGIN
            BEGIN TRY
                INSERT [#BufferPoolAnalysis_MemoryClerks]
                SELECT
                      [type], SUM(CONVERT(bigint, [pages_kb]))
                    , SUM(CONVERT(bigint, [virtual_memory_reserved_kb]))
                    , SUM(CONVERT(bigint, [virtual_memory_committed_kb]))
                    , SUM(CONVERT(bigint, [awe_allocated_kb]))
                      + SUM(CONVERT(bigint, [shared_memory_committed_kb]))
                    , COUNT_BIG(*)
                FROM [sys].[dm_os_memory_clerks] WITH (NOLOCK)
                GROUP BY [type];
            END TRY
            BEGIN CATCH
                SELECT @IsPartial = 1, @StatusCode = 'AVAILABLE_LIMITED';
                IF @ErrorNumber IS NULL
                    SELECT @ErrorNumber = ERROR_NUMBER(),
                           @ErrorMessage = CONCAT(N'Memory Clerks nicht lesbar: ', ERROR_MESSAGE());
            END CATCH;
        END;

        IF @StatusCode IN ('AVAILABLE', 'AVAILABLE_LIMITED') AND @MitBufferPoolVerteilung = 1
        BEGIN
            BEGIN TRY
                INSERT [#BufferPoolAnalysis_BufferPool]
                SELECT
                      [b].[database_id], [d].[name], COUNT_BIG(*)
                    , CONVERT(decimal(19,2), COUNT_BIG(*) * 8.0 / 1024.0)
                    , SUM(CONVERT(bigint, CASE WHEN [is_modified] = 1 THEN 1 ELSE 0 END))
                    , CONVERT(decimal(19,2),
                      SUM(CONVERT(bigint, CASE WHEN [is_modified] = 1 THEN 1 ELSE 0 END)) * 8.0 / 1024.0)
                    , CONVERT(decimal(19,2), SUM(CONVERT(bigint, [free_space_in_bytes])) / 1048576.0)
                    , COUNT_BIG(DISTINCT [numa_node])
                FROM [sys].[dm_os_buffer_descriptors] AS [b] WITH (NOLOCK)
                LEFT JOIN [master].[sys].[databases] AS [d] WITH (NOLOCK)
                  ON [d].[database_id]=[b].[database_id]
                GROUP BY [b].[database_id],[d].[name];
            END TRY
            BEGIN CATCH
                SELECT @IsPartial = 1, @StatusCode = 'AVAILABLE_LIMITED';
                IF @ErrorNumber IS NULL
                    SELECT @ErrorNumber = ERROR_NUMBER(),
                           @ErrorMessage = CONCAT(N'Buffer-Pool-Verteilung nicht lesbar: ', ERROR_MESSAGE());
            END CATCH;
        END;

        IF (EXISTS (SELECT 1 FROM [#BufferPoolAnalysis_ResourceSemaphores] WHERE [WaiterCount] > 0)
            OR EXISTS (SELECT 1 FROM [#BufferPoolAnalysis_MemorySnapshot] WHERE [FindingCode] <> 'NO_MEMORY_PRESSURE_FLAG'))
           AND @StatusCode = 'AVAILABLE'
            SET @StatusCode = 'AVAILABLE_WITH_FINDING';
    END;

    SELECT @StatusCodeOut = @StatusCode, @IsPartialOut = @IsPartial,
           @ErrorNumberOut = @ErrorNumber, @ErrorMessageOut = @ErrorMessage;

    IF @JsonErzeugen = 1
    BEGIN
        DECLARE @MetaJson nvarchar(max) =
            (SELECT N'BufferPoolAnalysis' AS [resultName], 1 AS [schemaVersion],
                    @Now AS [generatedAtUtc], @StatusCode AS [statusCode], @IsPartial AS [isPartial],
                    @MitBufferPoolVerteilung AS [bufferPoolDistributionCollected]
             FOR JSON PATH, WITHOUT_ARRAY_WRAPPER);
        DECLARE @SnapshotJson nvarchar(max) =
            (SELECT * FROM [#BufferPoolAnalysis_MemorySnapshot] FOR JSON PATH, INCLUDE_NULL_VALUES);
        DECLARE @SemaphoreJson nvarchar(max) =
            (SELECT TOP (@Limit) * FROM [#BufferPoolAnalysis_ResourceSemaphores]
             ORDER BY [WaiterCount] DESC, [PoolId], [ResourceSemaphoreId]
             FOR JSON PATH, INCLUDE_NULL_VALUES);
        DECLARE @ClerkJson nvarchar(max) =
            (SELECT TOP (@Limit) * FROM [#BufferPoolAnalysis_MemoryClerks]
             ORDER BY [PagesKb] DESC, [ClerkType] FOR JSON PATH, INCLUDE_NULL_VALUES);
        DECLARE @BufferJson nvarchar(max) =
            (SELECT TOP (@Limit) * FROM [#BufferPoolAnalysis_BufferPool]
             ORDER BY [CachedPages] DESC, [DatabaseId] FOR JSON PATH, INCLUDE_NULL_VALUES);
        SET @Json = CONCAT(N'{"meta":', COALESCE(@MetaJson, N'{}'),
                           N',"memory":', COALESCE(@SnapshotJson, N'[]'),
                           N',"resourceSemaphores":', COALESCE(@SemaphoreJson, N'[]'),
                           N',"memoryClerks":', COALESCE(@ClerkJson, N'[]'),
                           N',"bufferPool":', COALESCE(@BufferJson, N'[]'), N'}');
    END;

    IF @OutputMode = 'RAW'
    BEGIN
        SELECT N'USP_BufferPoolAnalysis' AS [ModuleName], @Now AS [CollectionTimeUtc],
               @StatusCode AS [StatusCode], @IsPartial AS [IsPartial],
               @MitBufferPoolVerteilung AS [BufferPoolDistributionCollected],
               @ErrorNumber AS [ErrorNumber], @ErrorMessage AS [ErrorMessage],
               N'Momentaufnahme; Buffer-Pool-Scan ist opt-in.' AS [Detail];
        SELECT * FROM [#BufferPoolAnalysis_MemorySnapshot];
        SELECT TOP (@Limit) * FROM [#BufferPoolAnalysis_ResourceSemaphores]
        ORDER BY [WaiterCount] DESC, [PoolId], [ResourceSemaphoreId];
        SELECT TOP (@Limit) * FROM [#BufferPoolAnalysis_MemoryClerks] ORDER BY [PagesKb] DESC, [ClerkType];
        SELECT TOP (@Limit) * FROM [#BufferPoolAnalysis_BufferPool] ORDER BY [CachedPages] DESC, [DatabaseId];
    END
    ELSE IF @OutputMode = 'CONSOLE'
    BEGIN
        SELECT N'Buffer Pool und Speicherdruck' AS [Ergebnis], @Now AS [Stand_UTC],
               @StatusCode AS [Status], @IsPartial AS [Teilweise], @ErrorMessage AS [Hinweis];
        SELECT N'Speichermomentaufnahme' AS [Ergebnis], [PhysicalMemoryInUseKb] AS [SQL_Physisch_KB],
               [AvailablePhysicalMemoryKb] AS [OS_Verfuegbar_KB],
               [AvailablePhysicalMemoryPercent] AS [OS_Verfuegbar_Prozent],
               [ProcessPhysicalMemoryLow] AS [SQL_Physisch_Niedrig],
               [ProcessVirtualMemoryLow] AS [SQL_Virtuell_Niedrig],
               [FindingCode] AS [Befund], [FindingSeverity] AS [Prioritaet], [EvidenceLimit] AS [Grenze]
        FROM [#BufferPoolAnalysis_MemorySnapshot];
        SELECT TOP (@Limit) N'Resource Semaphore' AS [Ergebnis], [PoolId] AS [Pool_ID],
               [ResourceSemaphoreId] AS [Semaphore_ID], [AvailableMemoryKb] AS [Verfuegbar_KB],
               [GrantedMemoryKb] AS [Zugewiesen_KB], [GranteeCount] AS [Zuteilungen],
               [WaiterCount] AS [Wartende], [TimeoutErrorCount] AS [Timeouts]
        FROM [#BufferPoolAnalysis_ResourceSemaphores]
        ORDER BY [WaiterCount] DESC, [PoolId], [ResourceSemaphoreId];
        SELECT TOP (@Limit) N'Memory Clerk' AS [Ergebnis], [ClerkType] AS [Typ],
               [PagesKb] AS [Pages_KB], [VirtualMemoryCommittedKb] AS [Virtuell_Committed_KB],
               [LockedOrAweKb] AS [Locked_oder_AWE_KB], [ClerkCount] AS [Instanzen]
        FROM [#BufferPoolAnalysis_MemoryClerks] ORDER BY [PagesKb] DESC, [ClerkType];
        SELECT TOP (@Limit) N'Buffer-Pool-Verteilung' AS [Ergebnis], [DatabaseName] AS [Datenbank],
               [CachedSizeMb] AS [Cache_MB], [DirtySizeMb] AS [Dirty_MB],
               [FreeSpaceMb] AS [Freiraum_in_Seiten_MB], [NumaNodeCount] AS [NUMA_Nodes]
        FROM [#BufferPoolAnalysis_BufferPool] ORDER BY [CachedPages] DESC, [DatabaseId];
    END;
    IF @ConsoleResultRequested = 1
    BEGIN
        EXEC [monitor].[InternalEmitConsoleResult]
              @SourceTable=N'#BufferPoolAnalysis_MemorySnapshot'
            , @ResultLabel=N'BufferPoolAnalysis'
            , @EmptyMessage=N'Keine fachlichen Ergebnisse';
    END;
    IF @TableResultRequested = 1
    BEGIN
        EXEC [monitor].[InternalWriteResultTable]
              @SourceTable = N'#BufferPoolAnalysis_MemorySnapshot'
            , @TargetTable=@TableTarget
            , @ThrowOnError = 1;
    END;
END;
GO
-- END SOURCE: Code/08_ServerHealth/160_USP_BufferPoolAnalysis.sql

-- BEGIN SOURCE: Code/08_ServerHealth/170_USP_DiagnosticFindings.sql
/*
===============================================================================
Objekt       : monitor.USP_DiagnosticFindings
Version      : 1.2.0
Stand        : 2026-07-19
Zweck        : Aggregiert normalisierte Befunde aus den zuvor implementierten
               Spezialfallmodulen über deren JSON-Ausgabeverträge.
Abhängigkeit : DatabaseIntegrityAnalysis, DatabaseCapacityAnalysis,
               BufferPoolAnalysis, BackupChainAnalysis,
               AvailabilityDeepAnalysis, AgentMonitoringAnalysis sowie opt-in
               SchemaDesignAnalysis, StatisticsDistributionAnalysis,
               IntelligentQueryProcessingAnalysis und InternalContentionAnalysis.
Methodik     : Kindmodule laufen mit @ResultSetArt=NONE. Innerhalb eines
               Orchestratoraufrufs können kontextgleiche Parent-Ergebnisse
               wiederverwendet werden; sonst werden Quellen frisch gelesen.
               Der Aggregator liest nur definierte JSON-Felder und übernimmt
               keine freien SQL-, Mail-, Plan-, Pfad- oder Meldungstexte.
Grenzen      : Priorität ist Triage, keine automatische Ursachenfeststellung.
               Kein READPAST; unvollständige Child-Evidenz bleibt sichtbar.
===============================================================================
*/
CREATE OR ALTER PROCEDURE [monitor].[USP_DiagnosticFindings]
      @DatabaseNames                nvarchar(max)  = NULL
    , @SystemdatenbankenEinbeziehen bit            = 0
    , @DatabaseNamePattern          nvarchar(4000) = NULL
    , @HighImpactConfirmed              bit            = 0
    , @MitIntegritaet               bit            = 1
    , @MitKapazitaet                bit            = 1
    , @MitSpeicher                  bit            = 1
    , @MitBackupketten              bit            = 1
    , @MitAvailability              bit            = 1
    , @MitAgentMonitoring           bit            = 1
    , @MitSchemaDesign              bit            = 0
    , @MitStatistikverteilung       bit            = 0
    , @MitIQP                       bit            = 0
    , @MitContention                bit            = 0
    , @ContentionSampleSeconds      tinyint         = 5
    , @ContentionMinWaitMs          bigint          = 1000
    , @ParentIntegrityJson          nvarchar(max)   = NULL
    , @ParentCapacityJson           nvarchar(max)   = NULL
    , @ParentBufferPoolJson         nvarchar(max)   = NULL
    , @NurAbPrioritaet              varchar(16)     = 'INFO'
    , @MaxZeilen                    int             = 1000
    , @ResultSetArt                 varchar(16)     = 'CONSOLE'
    , @ResultTablesJson               nvarchar(max) = NULL
    , @JsonErzeugen                 bit             = 0
    , @Json                         nvarchar(max)   = NULL OUTPUT
    , @PrintMeldungen               bit             = 1
    , @Hilfe                        bit             = 0
    , @StatusCodeOut                varchar(40)     = NULL OUTPUT
    , @IsPartialOut                 bit             = NULL OUTPUT
    , @ErrorNumberOut               int             = NULL OUTPUT
    , @ErrorMessageOut              nvarchar(2048)  = NULL OUTPUT
AS
BEGIN
    SET NOCOUNT ON;
    SET LOCK_TIMEOUT 0;
    SET @Json = NULL;

    DECLARE @OutputMode varchar(16) = UPPER(LTRIM(RTRIM(COALESCE(@ResultSetArt, ''))));
    DECLARE @TableResultRequested bit = CASE WHEN @OutputMode = 'TABLE' THEN 1 ELSE 0 END;
    DECLARE @ConsoleResultRequested bit = CASE WHEN @OutputMode = 'CONSOLE' THEN 1 ELSE 0 END;
    DECLARE @TableTarget sysname=NULL;
    IF @TableResultRequested=0 AND NULLIF(LTRIM(RTRIM(COALESCE(@ResultTablesJson,N''))),N'') IS NOT NULL THROW 51011,N'@ResultTablesJson ist ausschließlich mit @ResultSetArt=TABLE zulässig.',1;
    IF @TableResultRequested=1 EXEC [monitor].[InternalPrepareSingleResultTable] @ResultTablesJson=@ResultTablesJson,@ResultName=N'findings',@TargetTable=@TableTarget OUTPUT,@ThrowOnError=1;
    IF @TableResultRequested = 1 OR @ConsoleResultRequested = 1 SET @OutputMode = 'NONE';
    DECLARE @MinimumSeverity varchar(16) = UPPER(LTRIM(RTRIM(COALESCE(@NurAbPrioritaet, ''))));
    DECLARE @Limit bigint = CASE WHEN @MaxZeilen IS NULL OR @MaxZeilen = 0
                                 THEN CONVERT(bigint, 9223372036854775807)
                                 ELSE CONVERT(bigint, @MaxZeilen) END;

    IF @Hilfe = 1
    BEGIN
        PRINT N'monitor.USP_DiagnosticFindings';
        PRINT N'Aggregiert Befunde aus den Spezialfallmodulen; verändert keine Konfiguration und maskiert keine Resultsets.';
        PRINT N'Kostenintensive Schema-, Statistikverteilungs-, IQP- und Contention-Module sind standardmäßig deaktiviert.';
        PRINT N'@NurAbPrioritaet=INFO|LOW|MEDIUM|HIGH; @MaxZeilen positiv, NULL/0 = unbegrenzt.';
        PRINT N'@Parent...Json dient ausschließlich der Wiederverwendung bereits erhobener Ergebnisse innerhalb eines Orchestratoraufrufs; NULL liest frisch.';
        RETURN;
    END;

    DECLARE @Now datetime2(3) = SYSUTCDATETIME();
    DECLARE @StatusCode varchar(40) = 'AVAILABLE';
    DECLARE @IsPartial bit = 0;
    DECLARE @ErrorNumber int = NULL;
    DECLARE @ErrorMessage nvarchar(2048) = NULL;
    DECLARE @CurrentCompatibilityLevel int =
        (SELECT [compatibility_level] FROM [sys].[databases] WITH (NOLOCK) WHERE [database_id] = DB_ID());

    DECLARE @IntegrityJson nvarchar(max) = @ParentIntegrityJson;
    DECLARE @CapacityJson nvarchar(max) = @ParentCapacityJson;
    DECLARE @MemoryJson nvarchar(max) = @ParentBufferPoolJson;
    DECLARE @BackupJson nvarchar(max) = NULL;
    DECLARE @AvailabilityJson nvarchar(max) = NULL;
    DECLARE @AgentJson nvarchar(max) = NULL;
    DECLARE @SchemaJson nvarchar(max) = NULL;
    DECLARE @StatisticsDistributionJson nvarchar(max) = NULL;
    DECLARE @IqpJson nvarchar(max) = NULL;
    DECLARE @ContentionJson nvarchar(max) = NULL;
    DECLARE @ChildStatus varchar(40);
    DECLARE @ChildPartial bit;
    DECLARE @ChildErrorNumber int;
    DECLARE @ChildErrorMessage nvarchar(2048);

    DECLARE @ModuleStatus TABLE
    (
          [ExecutionOrdinal] tinyint NOT NULL
        , [ModuleName] sysname NOT NULL
        , [InvocationStatus] varchar(40) NOT NULL
        , [EvidenceStatus] varchar(40) NULL
        , [IsPartial] bit NULL
        , [ErrorNumber] int NULL
        , [ErrorMessage] nvarchar(2048) NULL
    );
    CREATE TABLE [#DiagnosticFindings_Findings]
    (
          [FindingOrdinal] bigint IDENTITY(1,1) NOT NULL
        , [SourceModule] sysname NOT NULL
        , [Category] varchar(60) NOT NULL
        , [Severity] varchar(16) NOT NULL
        , [Confidence] varchar(16) NOT NULL
        , [ScopeType] nvarchar(60) NOT NULL
        , [ScopeName] nvarchar(512) NULL
        , [FindingCode] varchar(120) NOT NULL
        , [EvidenceMetric] decimal(38,4) NULL
        , [Evidence] nvarchar(1000) NOT NULL
        , [EvidenceLimit] nvarchar(1000) NOT NULL
        , [RecommendedNextCheck] nvarchar(1000) NOT NULL
    );

    IF @MaxZeilen < 0 OR @ContentionSampleSeconds > 60
       OR @ContentionMinWaitMs < 0
       OR @OutputMode NOT IN ('RAW', 'CONSOLE', 'NONE')
       OR @MinimumSeverity NOT IN ('INFO', 'LOW', 'MEDIUM', 'HIGH')
       OR (@ParentIntegrityJson IS NOT NULL AND ISJSON(@ParentIntegrityJson)<>1)
       OR (@ParentCapacityJson IS NOT NULL AND ISJSON(@ParentCapacityJson)<>1)
       OR (@ParentBufferPoolJson IS NOT NULL AND ISJSON(@ParentBufferPoolJson)<>1)
       OR (@MitIntegritaet = 0 AND @MitKapazitaet = 0 AND @MitSpeicher = 0
           AND @MitBackupketten = 0 AND @MitAvailability = 0 AND @MitAgentMonitoring = 0
           AND @MitSchemaDesign = 0 AND @MitStatistikverteilung = 0
           AND @MitIQP = 0 AND @MitContention = 0)
    BEGIN
        SELECT @StatusCode = 'INVALID_PARAMETER', @IsPartial = 1,
               @ErrorMessage = N'Ungültiger Modul-, Datenbank-, Sample-, Prioritäts-, Zeilen- oder Ausgabeparameter.';
    END
    ELSE IF (@ParentIntegrityJson IS NOT NULL
             AND (COALESCE(JSON_VALUE(@ParentIntegrityJson,'$.meta.resultName'),'')<>'DatabaseIntegrityAnalysis'
                  OR COALESCE(TRY_CONVERT(int,JSON_VALUE(@ParentIntegrityJson,'$.meta.schemaVersion')),0)<>1))
         OR (@ParentCapacityJson IS NOT NULL
             AND (COALESCE(JSON_VALUE(@ParentCapacityJson,'$.meta.resultName'),'')<>'DatabaseCapacityAnalysis'
                  OR COALESCE(TRY_CONVERT(int,JSON_VALUE(@ParentCapacityJson,'$.meta.schemaVersion')),0)<>1))
         OR (@ParentBufferPoolJson IS NOT NULL
             AND (COALESCE(JSON_VALUE(@ParentBufferPoolJson,'$.meta.resultName'),'')<>'BufferPoolAnalysis'
                  OR COALESCE(TRY_CONVERT(int,JSON_VALUE(@ParentBufferPoolJson,'$.meta.schemaVersion')),0)<>1))
    BEGIN
        SELECT @StatusCode = 'INVALID_PARAMETER', @IsPartial = 1,
               @ErrorMessage = N'Ein Parent-Ergebnis entspricht nicht dem erwarteten JSON-Vertrag.';
    END
    ELSE IF @CurrentCompatibilityLevel < 130
    BEGIN
        SELECT @StatusCode = 'UNAVAILABLE_FEATURE', @IsPartial = 1,
               @ErrorMessage = N'Die Befundaggregation benötigt Compatibility Level 130 oder höher für OPENJSON.';
    END;

    IF @StatusCode = 'AVAILABLE' AND @MitIntegritaet = 1
    BEGIN
        IF @ParentIntegrityJson IS NOT NULL
        BEGIN
            SELECT @ChildStatus=JSON_VALUE(@IntegrityJson,'$.meta.statusCode'),
                   @ChildPartial=CASE JSON_VALUE(@IntegrityJson,'$.meta.isPartial')
                                      WHEN 'true' THEN 1 WHEN 'false' THEN 0
                                      ELSE COALESCE(TRY_CONVERT(bit,JSON_VALUE(@IntegrityJson,'$.meta.isPartial')),1) END,
                   @ChildErrorNumber=TRY_CONVERT(int,JSON_VALUE(@IntegrityJson,'$.meta.errorNumber')),
                   @ChildErrorMessage=JSON_VALUE(@IntegrityJson,'$.meta.errorMessage');
            INSERT @ModuleStatus VALUES (1,N'USP_DatabaseIntegrityAnalysis','REUSED_PARENT_RESULT',@ChildStatus,@ChildPartial,@ChildErrorNumber,@ChildErrorMessage);
        END
        ELSE
        BEGIN
            BEGIN TRY
                SELECT @ChildStatus = NULL, @ChildPartial = NULL, @ChildErrorNumber = NULL, @ChildErrorMessage = NULL;
                EXEC [monitor].[USP_DatabaseIntegrityAnalysis]
                      @DatabaseNames = @DatabaseNames, @SystemdatenbankenEinbeziehen = @SystemdatenbankenEinbeziehen
                    , @DatabaseNamePattern = @DatabaseNamePattern,@HighImpactConfirmed=@HighImpactConfirmed
                    , @MitPageDetails = 0, @MaxZeilen = @MaxZeilen, @ResultSetArt = 'NONE'
                    , @JsonErzeugen = 1, @Json = @IntegrityJson OUTPUT, @PrintMeldungen = @PrintMeldungen
                    , @StatusCodeOut = @ChildStatus OUTPUT, @IsPartialOut = @ChildPartial OUTPUT
                    , @ErrorNumberOut = @ChildErrorNumber OUTPUT, @ErrorMessageOut = @ChildErrorMessage OUTPUT;
                INSERT @ModuleStatus VALUES (1, N'USP_DatabaseIntegrityAnalysis', 'EXECUTED', @ChildStatus, @ChildPartial, @ChildErrorNumber, @ChildErrorMessage);
            END TRY
            BEGIN CATCH
                INSERT @ModuleStatus VALUES (1, N'USP_DatabaseIntegrityAnalysis', 'ERROR_HANDLED', NULL, 1, ERROR_NUMBER(), ERROR_MESSAGE());
            END CATCH;
        END;
    END;

    IF @StatusCode = 'AVAILABLE' AND @MitKapazitaet = 1
    BEGIN
        IF @ParentCapacityJson IS NOT NULL
        BEGIN
            SELECT @ChildStatus=JSON_VALUE(@CapacityJson,'$.meta.statusCode'),
                   @ChildPartial=CASE JSON_VALUE(@CapacityJson,'$.meta.isPartial')
                                      WHEN 'true' THEN 1 WHEN 'false' THEN 0
                                      ELSE COALESCE(TRY_CONVERT(bit,JSON_VALUE(@CapacityJson,'$.meta.isPartial')),1) END,
                   @ChildErrorNumber=TRY_CONVERT(int,JSON_VALUE(@CapacityJson,'$.meta.errorNumber')),
                   @ChildErrorMessage=JSON_VALUE(@CapacityJson,'$.meta.errorMessage');
            INSERT @ModuleStatus VALUES (2,N'USP_DatabaseCapacityAnalysis','REUSED_PARENT_RESULT',@ChildStatus,@ChildPartial,@ChildErrorNumber,@ChildErrorMessage);
        END
        ELSE
        BEGIN
            BEGIN TRY
                SELECT @ChildStatus = NULL, @ChildPartial = NULL, @ChildErrorNumber = NULL, @ChildErrorMessage = NULL;
                EXEC [monitor].[USP_DatabaseCapacityAnalysis]
                      @DatabaseNames = @DatabaseNames, @SystemdatenbankenEinbeziehen = @SystemdatenbankenEinbeziehen
                    , @DatabaseNamePattern = @DatabaseNamePattern,@HighImpactConfirmed=@HighImpactConfirmed
                    , @NurProblematisch = 0, @MaxZeilen = @MaxZeilen, @ResultSetArt = 'NONE'
                    , @JsonErzeugen = 1, @Json = @CapacityJson OUTPUT, @PrintMeldungen = @PrintMeldungen
                    , @StatusCodeOut = @ChildStatus OUTPUT, @IsPartialOut = @ChildPartial OUTPUT
                    , @ErrorNumberOut = @ChildErrorNumber OUTPUT, @ErrorMessageOut = @ChildErrorMessage OUTPUT;
                INSERT @ModuleStatus VALUES (2, N'USP_DatabaseCapacityAnalysis', 'EXECUTED', @ChildStatus, @ChildPartial, @ChildErrorNumber, @ChildErrorMessage);
            END TRY
            BEGIN CATCH
                INSERT @ModuleStatus VALUES (2, N'USP_DatabaseCapacityAnalysis', 'ERROR_HANDLED', NULL, 1, ERROR_NUMBER(), ERROR_MESSAGE());
            END CATCH;
        END;
    END;

    IF @StatusCode = 'AVAILABLE' AND @MitSpeicher = 1
    BEGIN
        IF @ParentBufferPoolJson IS NOT NULL
        BEGIN
            SELECT @ChildStatus=JSON_VALUE(@MemoryJson,'$.meta.statusCode'),
                   @ChildPartial=CASE JSON_VALUE(@MemoryJson,'$.meta.isPartial')
                                      WHEN 'true' THEN 1 WHEN 'false' THEN 0
                                      ELSE COALESCE(TRY_CONVERT(bit,JSON_VALUE(@MemoryJson,'$.meta.isPartial')),1) END,
                   @ChildErrorNumber=TRY_CONVERT(int,JSON_VALUE(@MemoryJson,'$.meta.errorNumber')),
                   @ChildErrorMessage=JSON_VALUE(@MemoryJson,'$.meta.errorMessage');
            INSERT @ModuleStatus VALUES (3,N'USP_BufferPoolAnalysis','REUSED_PARENT_RESULT',@ChildStatus,@ChildPartial,@ChildErrorNumber,@ChildErrorMessage);
        END
        ELSE
        BEGIN
            BEGIN TRY
                SELECT @ChildStatus = NULL, @ChildPartial = NULL, @ChildErrorNumber = NULL, @ChildErrorMessage = NULL;
                EXEC [monitor].[USP_BufferPoolAnalysis]
                      @MitMemoryClerks = 0, @MitBufferPoolVerteilung = 0, @MaxZeilen = @MaxZeilen
                    , @ResultSetArt = 'NONE', @JsonErzeugen = 1, @Json = @MemoryJson OUTPUT
                    , @PrintMeldungen = @PrintMeldungen, @StatusCodeOut = @ChildStatus OUTPUT
                    , @IsPartialOut = @ChildPartial OUTPUT, @ErrorNumberOut = @ChildErrorNumber OUTPUT
                    , @ErrorMessageOut = @ChildErrorMessage OUTPUT;
                INSERT @ModuleStatus VALUES (3, N'USP_BufferPoolAnalysis', 'EXECUTED', @ChildStatus, @ChildPartial, @ChildErrorNumber, @ChildErrorMessage);
            END TRY
            BEGIN CATCH
                INSERT @ModuleStatus VALUES (3, N'USP_BufferPoolAnalysis', 'ERROR_HANDLED', NULL, 1, ERROR_NUMBER(), ERROR_MESSAGE());
            END CATCH;
        END;
    END;

    IF @StatusCode = 'AVAILABLE' AND @MitBackupketten = 1
    BEGIN
        BEGIN TRY
            SELECT @ChildStatus = NULL, @ChildPartial = NULL, @ChildErrorNumber = NULL, @ChildErrorMessage = NULL;
            EXEC [monitor].[USP_BackupChainAnalysis]
                  @DatabaseNames = @DatabaseNames, @SystemdatenbankenEinbeziehen = @SystemdatenbankenEinbeziehen
                , @DatabaseNamePattern = @DatabaseNamePattern,@HighImpactConfirmed=@HighImpactConfirmed
                , @MaxZeilen = @MaxZeilen, @ResultSetArt = 'NONE', @JsonErzeugen = 1, @Json = @BackupJson OUTPUT
                , @PrintMeldungen = @PrintMeldungen, @StatusCodeOut = @ChildStatus OUTPUT
                , @IsPartialOut = @ChildPartial OUTPUT, @ErrorNumberOut = @ChildErrorNumber OUTPUT
                , @ErrorMessageOut = @ChildErrorMessage OUTPUT;
            INSERT @ModuleStatus VALUES (4, N'USP_BackupChainAnalysis', 'EXECUTED', @ChildStatus, @ChildPartial, @ChildErrorNumber, @ChildErrorMessage);
        END TRY
        BEGIN CATCH
            INSERT @ModuleStatus VALUES (4, N'USP_BackupChainAnalysis', 'ERROR_HANDLED', NULL, 1, ERROR_NUMBER(), ERROR_MESSAGE());
        END CATCH;
    END;

    IF @StatusCode = 'AVAILABLE' AND @MitAvailability = 1
    BEGIN
        BEGIN TRY
            SELECT @ChildStatus = NULL, @ChildPartial = NULL, @ChildErrorNumber = NULL, @ChildErrorMessage = NULL;
            EXEC [monitor].[USP_AvailabilityDeepAnalysis]
                  @MitClusterNetzwerken = 0, @MaxZeilen = @MaxZeilen, @ResultSetArt = 'NONE'
                , @JsonErzeugen = 1, @Json = @AvailabilityJson OUTPUT, @PrintMeldungen = @PrintMeldungen
                , @StatusCodeOut = @ChildStatus OUTPUT, @IsPartialOut = @ChildPartial OUTPUT
                , @ErrorNumberOut = @ChildErrorNumber OUTPUT, @ErrorMessageOut = @ChildErrorMessage OUTPUT;
            INSERT @ModuleStatus VALUES (5, N'USP_AvailabilityDeepAnalysis', 'EXECUTED', @ChildStatus, @ChildPartial, @ChildErrorNumber, @ChildErrorMessage);
        END TRY
        BEGIN CATCH
            INSERT @ModuleStatus VALUES (5, N'USP_AvailabilityDeepAnalysis', 'ERROR_HANDLED', NULL, 1, ERROR_NUMBER(), ERROR_MESSAGE());
        END CATCH;
    END;

    IF @StatusCode = 'AVAILABLE' AND @MitAgentMonitoring = 1
    BEGIN
        BEGIN TRY
            SELECT @ChildStatus = NULL, @ChildPartial = NULL, @ChildErrorNumber = NULL, @ChildErrorMessage = NULL;
            EXEC [monitor].[USP_AgentMonitoringAnalysis]
                  @MaxZeilen = @MaxZeilen, @ResultSetArt = 'NONE', @JsonErzeugen = 1, @Json = @AgentJson OUTPUT
                , @PrintMeldungen = @PrintMeldungen, @StatusCodeOut = @ChildStatus OUTPUT
                , @IsPartialOut = @ChildPartial OUTPUT, @ErrorNumberOut = @ChildErrorNumber OUTPUT
                , @ErrorMessageOut = @ChildErrorMessage OUTPUT;
            INSERT @ModuleStatus VALUES (6, N'USP_AgentMonitoringAnalysis', 'EXECUTED', @ChildStatus, @ChildPartial, @ChildErrorNumber, @ChildErrorMessage);
        END TRY
        BEGIN CATCH
            INSERT @ModuleStatus VALUES (6, N'USP_AgentMonitoringAnalysis', 'ERROR_HANDLED', NULL, 1, ERROR_NUMBER(), ERROR_MESSAGE());
        END CATCH;
    END;

    IF @StatusCode = 'AVAILABLE' AND @MitSchemaDesign = 1
    BEGIN
        BEGIN TRY
            SELECT @ChildStatus = NULL, @ChildPartial = NULL, @ChildErrorNumber = NULL, @ChildErrorMessage = NULL;
            EXEC [monitor].[USP_SchemaDesignAnalysis]
                  @DatabaseNames = @DatabaseNames, @SystemdatenbankenEinbeziehen = @SystemdatenbankenEinbeziehen
                , @DatabaseNamePattern = @DatabaseNamePattern,@HighImpactConfirmed=@HighImpactConfirmed
                , @MaxZeilen = @MaxZeilen, @ResultSetArt = 'NONE', @JsonErzeugen = 1, @Json = @SchemaJson OUTPUT
                , @PrintMeldungen = @PrintMeldungen, @StatusCodeOut = @ChildStatus OUTPUT
                , @IsPartialOut = @ChildPartial OUTPUT, @ErrorNumberOut = @ChildErrorNumber OUTPUT
                , @ErrorMessageOut = @ChildErrorMessage OUTPUT;
            INSERT @ModuleStatus VALUES (7, N'USP_SchemaDesignAnalysis', 'EXECUTED', @ChildStatus, @ChildPartial, @ChildErrorNumber, @ChildErrorMessage);
        END TRY
        BEGIN CATCH
            INSERT @ModuleStatus VALUES (7, N'USP_SchemaDesignAnalysis', 'ERROR_HANDLED', NULL, 1, ERROR_NUMBER(), ERROR_MESSAGE());
        END CATCH;
    END;

    IF @StatusCode = 'AVAILABLE' AND @MitStatistikverteilung = 1
    BEGIN
        BEGIN TRY
            SELECT @ChildStatus = NULL, @ChildPartial = NULL, @ChildErrorNumber = NULL, @ChildErrorMessage = NULL;
            EXEC [monitor].[USP_StatisticsDistributionAnalysis]
                  @DatabaseNames = @DatabaseNames, @SystemdatenbankenEinbeziehen = @SystemdatenbankenEinbeziehen
                , @DatabaseNamePattern = @DatabaseNamePattern,@HighImpactConfirmed=@HighImpactConfirmed, @AnalyseModus = 'VOLL'
                , @MaxZeilen = @MaxZeilen
                , @ResultSetArt = 'NONE', @JsonErzeugen = 1, @Json = @StatisticsDistributionJson OUTPUT
                , @PrintMeldungen = @PrintMeldungen, @StatusCodeOut = @ChildStatus OUTPUT
                , @IsPartialOut = @ChildPartial OUTPUT, @ErrorNumberOut = @ChildErrorNumber OUTPUT
                , @ErrorMessageOut = @ChildErrorMessage OUTPUT;
            INSERT @ModuleStatus VALUES (8, N'USP_StatisticsDistributionAnalysis', 'EXECUTED', @ChildStatus, @ChildPartial, @ChildErrorNumber, @ChildErrorMessage);
        END TRY
        BEGIN CATCH
            INSERT @ModuleStatus VALUES (8, N'USP_StatisticsDistributionAnalysis', 'ERROR_HANDLED', NULL, 1, ERROR_NUMBER(), ERROR_MESSAGE());
        END CATCH;
    END;

    IF @StatusCode = 'AVAILABLE' AND @MitIQP = 1
    BEGIN
        BEGIN TRY
            SELECT @ChildStatus = NULL, @ChildPartial = NULL, @ChildErrorNumber = NULL, @ChildErrorMessage = NULL;
            EXEC [monitor].[USP_IntelligentQueryProcessingAnalysis]
                  @DatabaseNames = @DatabaseNames, @SystemdatenbankenEinbeziehen = @SystemdatenbankenEinbeziehen
                , @DatabaseNamePattern = @DatabaseNamePattern,@HighImpactConfirmed=@HighImpactConfirmed
                , @MaxZeilen = @MaxZeilen, @ResultSetArt = 'NONE', @JsonErzeugen = 1, @Json = @IqpJson OUTPUT
                , @PrintMeldungen = @PrintMeldungen, @StatusCodeOut = @ChildStatus OUTPUT
                , @IsPartialOut = @ChildPartial OUTPUT, @ErrorNumberOut = @ChildErrorNumber OUTPUT
                , @ErrorMessageOut = @ChildErrorMessage OUTPUT;
            INSERT @ModuleStatus VALUES (9, N'USP_IntelligentQueryProcessingAnalysis', 'EXECUTED', @ChildStatus, @ChildPartial, @ChildErrorNumber, @ChildErrorMessage);
        END TRY
        BEGIN CATCH
            INSERT @ModuleStatus VALUES (9, N'USP_IntelligentQueryProcessingAnalysis', 'ERROR_HANDLED', NULL, 1, ERROR_NUMBER(), ERROR_MESSAGE());
        END CATCH;
    END;

    IF @StatusCode = 'AVAILABLE' AND @MitContention = 1
    BEGIN
        BEGIN TRY
            SELECT @ChildStatus = NULL, @ChildPartial = NULL, @ChildErrorNumber = NULL, @ChildErrorMessage = NULL;
            EXEC [monitor].[USP_InternalContentionAnalysis]
                  @SampleSeconds = @ContentionSampleSeconds, @MitSpinlocks = 1, @MitHotPages = 1
                , @MitPageDetails = 0, @MaxZeilen = @MaxZeilen, @ResultSetArt = 'NONE'
                , @JsonErzeugen = 1, @Json = @ContentionJson OUTPUT, @PrintMeldungen = @PrintMeldungen
                , @StatusCodeOut = @ChildStatus OUTPUT, @IsPartialOut = @ChildPartial OUTPUT
                , @ErrorNumberOut = @ChildErrorNumber OUTPUT, @ErrorMessageOut = @ChildErrorMessage OUTPUT;
            INSERT @ModuleStatus VALUES (10, N'USP_InternalContentionAnalysis', 'EXECUTED', @ChildStatus, @ChildPartial, @ChildErrorNumber, @ChildErrorMessage);
        END TRY
        BEGIN CATCH
            INSERT @ModuleStatus VALUES (10, N'USP_InternalContentionAnalysis', 'ERROR_HANDLED', NULL, 1, ERROR_NUMBER(), ERROR_MESSAGE());
        END CATCH;
    END;

    IF @StatusCode = 'AVAILABLE'
    BEGIN
        DECLARE @ParseSql nvarchar(max) = N'
INSERT [#DiagnosticFindings_Findings] ([SourceModule],[Category],[Severity],[Confidence],[ScopeType],[ScopeName],[FindingCode],[EvidenceMetric],[Evidence],[EvidenceLimit],[RecommendedNextCheck])
SELECT N''USP_DatabaseIntegrityAnalysis'', ''INTEGRITY'',
       CASE WHEN [FindingCode] IN (''SUSPECT_PAGES_PRESENT'',''DAMAGED_BACKUP_METADATA'',''HADR_PAGE_REPAIR_PENDING'') THEN ''HIGH''
            WHEN [FindingCode] IN (''CHECKDB_EVIDENCE_MISSING'',''CHECKDB_EVIDENCE_OLD'') THEN ''MEDIUM'' ELSE ''LOW'' END,
       ''HIGH'', N''DATABASE'', [DatabaseName], [FindingCode],
       CONVERT(decimal(38,4), CASE WHEN [SuspectPageCount] > 0 THEN [SuspectPageCount]
                                  WHEN [DamagedBackupCount] > 0 THEN [DamagedBackupCount]
                                  ELSE [CheckdbAgeHours] END),
       CONCAT(N''Suspect pages='', [SuspectPageCount], N''; damaged backups='', [DamagedBackupCount],
              N''; CHECKDB age hours='', COALESCE(CONVERT(nvarchar(40), [CheckdbAgeHours]), N''NULL''), N''.''),
       [EvidenceLimit], N''CHECKDB-/Backup-/Seitenreparaturevidenz kontrolliert verifizieren.''
FROM OPENJSON(COALESCE(@Integrity, N''{}''), ''$.integrity'') WITH
([DatabaseName] sysname, [FindingCode] varchar(80), [SuspectPageCount] bigint,
 [DamagedBackupCount] bigint, [CheckdbAgeHours] bigint, [EvidenceLimit] nvarchar(1000))
WHERE [FindingCode] <> ''NO_INDICATOR_FOUND'';

INSERT [#DiagnosticFindings_Findings] ([SourceModule],[Category],[Severity],[Confidence],[ScopeType],[ScopeName],[FindingCode],[EvidenceMetric],[Evidence],[EvidenceLimit],[RecommendedNextCheck])
SELECT N''USP_DatabaseCapacityAnalysis'', ''CAPACITY'',
       CASE WHEN [FindingCode] IN (''FILE_MAX_SIZE_REACHED'',''NEXT_GROWTH_EXCEEDS_VOLUME_FREE'') THEN ''HIGH'' ELSE ''MEDIUM'' END,
       ''HIGH'', N''DATABASE_FILE'', CONCAT([DatabaseName], N''/'', [LogicalFileName]), [FindingCode],
       CONVERT(decimal(38,4), [VolumeFreePercent]),
       CONCAT(N''file free MB='', [FreeInFileMb], N''; volume free MB='', [VolumeAvailableMb],
              N''; next growth MB='', COALESCE(CONVERT(nvarchar(40), [NextGrowthMb]), N''NULL''), N''.''),
       [EvidenceLimit], N''Datei-, Volume- und Growth-Konfiguration gemeinsam prüfen; ohne Historie keine Zeit-bis-voll-Prognose.''
FROM OPENJSON(COALESCE(@Capacity, N''{}''), ''$.capacity'') WITH
([DatabaseName] sysname, [LogicalFileName] sysname, [FreeInFileMb] decimal(19,2),
 [VolumeAvailableMb] decimal(19,2), [VolumeFreePercent] decimal(9,2), [NextGrowthMb] decimal(19,2),
 [FindingCode] varchar(80), [EvidenceLimit] nvarchar(1000))
WHERE [FindingCode] <> ''NO_CAPACITY_INDICATOR'';

INSERT [#DiagnosticFindings_Findings] ([SourceModule],[Category],[Severity],[Confidence],[ScopeType],[ScopeName],[FindingCode],[EvidenceMetric],[Evidence],[EvidenceLimit],[RecommendedNextCheck])
SELECT N''USP_BufferPoolAnalysis'', ''MEMORY'', [FindingSeverity], ''HIGH'', N''INSTANCE'', NULL,
       [FindingCode], CONVERT(decimal(38,4), [AvailablePhysicalMemoryPercent]),
       CONCAT(N''OS available percent='', [AvailablePhysicalMemoryPercent],
              N''; process physical low='', [ProcessPhysicalMemoryLow],
              N''; process virtual low='', [ProcessVirtualMemoryLow], N''.''),
       [EvidenceLimit], N''Mit Verlauf, Resource Semaphores, anderen Prozessen und OS-Grenzen korrelieren.''
FROM OPENJSON(COALESCE(@Memory, N''{}''), ''$.memory'') WITH
([FindingCode] varchar(80), [FindingSeverity] varchar(16), [AvailablePhysicalMemoryPercent] decimal(9,2),
 [ProcessPhysicalMemoryLow] bit, [ProcessVirtualMemoryLow] bit, [EvidenceLimit] nvarchar(1000))
WHERE [FindingCode] <> ''NO_MEMORY_PRESSURE_FLAG'';

INSERT [#DiagnosticFindings_Findings] ([SourceModule],[Category],[Severity],[Confidence],[ScopeType],[ScopeName],[FindingCode],[EvidenceMetric],[Evidence],[EvidenceLimit],[RecommendedNextCheck])
SELECT N''USP_BufferPoolAnalysis'', ''MEMORY_GRANTS'', ''HIGH'', ''HIGH'', N''RESOURCE_SEMAPHORE'',
       CONCAT(N''pool='', [PoolId], N''; semaphore='', [ResourceSemaphoreId]), ''MEMORY_GRANT_WAITERS_PRESENT'',
       CONVERT(decimal(38,4), [WaiterCount]),
       CONCAT(N''waiters='', [WaiterCount], N''; available KB='', [AvailableMemoryKb], N''; granted KB='', [GrantedMemoryKb], N''.''),
       N''Momentaufnahme; kurzzeitige Wartende sind nicht automatisch ein dauerhaftes Kapazitätsproblem.'',
       N''Memory-Grant-Verlauf, Workload und Resource-Governor-Pool korrelieren.''
FROM OPENJSON(COALESCE(@Memory, N''{}''), ''$.resourceSemaphores'') WITH
([PoolId] int, [ResourceSemaphoreId] int, [AvailableMemoryKb] bigint, [GrantedMemoryKb] bigint, [WaiterCount] int)
WHERE [WaiterCount] > 0;

INSERT [#DiagnosticFindings_Findings] ([SourceModule],[Category],[Severity],[Confidence],[ScopeType],[ScopeName],[FindingCode],[EvidenceMetric],[Evidence],[EvidenceLimit],[RecommendedNextCheck])
SELECT N''USP_BackupChainAnalysis'', ''RECOVERABILITY'', [FindingSeverity], ''MEDIUM'', N''DATABASE'', [DatabaseName],
       [FindingCode], CONVERT(decimal(38,4), [LogGapCountInWindow]),
       CONCAT(N''log gaps='', [LogGapCountInWindow], N''; damaged='', [DamagedBackupCount],
              N''; without checksum='', [BackupWithoutChecksumCount], N''.''),
       [EvidenceLimit], N''Backuphistorie und Medien prüfen; Wiederherstellbarkeit durch kontrollierten Test-Restore belegen.''
FROM OPENJSON(COALESCE(@Backup, N''{}''), ''$.summary'') WITH
([DatabaseName] sysname, [FindingCode] varchar(100), [FindingSeverity] varchar(16),
 [LogGapCountInWindow] bigint, [DamagedBackupCount] bigint, [BackupWithoutChecksumCount] bigint,
 [EvidenceLimit] nvarchar(1000))
WHERE [FindingCode] NOT IN (''CHAIN_METADATA_CONSISTENT'',''TEMPDB_NOT_APPLICABLE'');

INSERT [#DiagnosticFindings_Findings] ([SourceModule],[Category],[Severity],[Confidence],[ScopeType],[ScopeName],[FindingCode],[EvidenceMetric],[Evidence],[EvidenceLimit],[RecommendedNextCheck])
SELECT N''USP_AvailabilityDeepAnalysis'', ''AVAILABILITY'', [FindingSeverity], ''HIGH'', N''AG_DATABASE'',
       CONCAT([AvailabilityGroupName], N''/'', [DatabaseName]), [FindingCode],
       CONVERT(decimal(38,4), COALESCE([SecondaryLagSeconds], [LogSendQueueSizeKb], [RedoQueueSizeKb])),
       CONCAT(N''log send queue KB='', [LogSendQueueSizeKb], N''; redo queue KB='', [RedoQueueSizeKb],
              N''; lag seconds='', [SecondaryLagSeconds], N''; suspended='', [IsSuspended], N''.''),
       N''Momentaufnahme; Queuegröße und Lag benötigen Verlauf und Rate.'',
       N''Replikazustand, Datenbewegung, Netzwerk und Clusterereignisse korrelieren.''
FROM OPENJSON(COALESCE(@Availability, N''{}''), ''$.databases'') WITH
([AvailabilityGroupName] sysname, [DatabaseName] sysname, [FindingCode] varchar(100),
 [FindingSeverity] varchar(16), [SecondaryLagSeconds] bigint, [LogSendQueueSizeKb] bigint,
 [RedoQueueSizeKb] bigint, [IsSuspended] bit)
WHERE [FindingCode] <> ''DATABASE_STATE_ACCEPTABLE'';

INSERT [#DiagnosticFindings_Findings] ([SourceModule],[Category],[Severity],[Confidence],[ScopeType],[ScopeName],[FindingCode],[EvidenceMetric],[Evidence],[EvidenceLimit],[RecommendedNextCheck])
SELECT N''USP_AvailabilityDeepAnalysis'', ''AVAILABILITY'',
       CASE WHEN [FindingCode] = ''QUORUM_STATE_NOT_VISIBLE'' THEN ''HIGH'' ELSE ''MEDIUM'' END,
       ''MEDIUM'', N''CLUSTER'', NULL, [FindingCode], NULL,
       CONCAT(N''quorum state='', COALESCE([QuorumStateDesc], N''NOT_VISIBLE''), N''.''),
       N''Cluster-DMV-Evidenz kann auf Linux- oder Read-Scale-Ausprägungen interne beziehungsweise nicht anwendbare Werte zeigen.'',
       N''Clusterquorum und Plattformzustand außerhalb der SQL-Instanz verifizieren.''
FROM OPENJSON(COALESCE(@Availability, N''{}''), ''$.cluster'') WITH
([QuorumStateDesc] nvarchar(60), [FindingCode] varchar(80))
WHERE [FindingCode] <> ''QUORUM_STATE_NORMAL'';

INSERT [#DiagnosticFindings_Findings] ([SourceModule],[Category],[Severity],[Confidence],[ScopeType],[ScopeName],[FindingCode],[EvidenceMetric],[Evidence],[EvidenceLimit],[RecommendedNextCheck])
SELECT N''USP_AvailabilityDeepAnalysis'', ''AVAILABILITY'', ''HIGH'', ''HIGH'', N''AG_REPLICA'',
       CONCAT([AvailabilityGroupName], N''/'', [ReplicaServerName]), [FindingCode], NULL,
       CONCAT(N''role='', COALESCE([RoleDesc], N''NULL''), N''; connection='', COALESCE([ConnectedStateDesc], N''NULL''),
              N''; health='', COALESCE([SynchronizationHealthDesc], N''NULL''), N''.''),
       N''Momentaufnahme; Remote-Replikazustände können vom lokalen Sichtpunkt unvollständig sein.'',
       N''Endpoint, Netzwerk, Replikarolle und Clusterereignisse korrelieren.''
FROM OPENJSON(COALESCE(@Availability, N''{}''), ''$.replicas'') WITH
([AvailabilityGroupName] sysname, [ReplicaServerName] nvarchar(256), [RoleDesc] nvarchar(60),
 [ConnectedStateDesc] nvarchar(60), [SynchronizationHealthDesc] nvarchar(60), [FindingCode] varchar(80))
WHERE [FindingCode] <> ''REPLICA_STATE_ACCEPTABLE'';

INSERT [#DiagnosticFindings_Findings] ([SourceModule],[Category],[Severity],[Confidence],[ScopeType],[ScopeName],[FindingCode],[EvidenceMetric],[Evidence],[EvidenceLimit],[RecommendedNextCheck])
SELECT N''USP_AvailabilityDeepAnalysis'', ''AVAILABILITY'', ''HIGH'', ''HIGH'', N''DATABASE'',
       [DatabaseName], [FindingCode], CONVERT(decimal(38,4), [PageStatus]),
       CONCAT(N''page repair status='', COALESCE(CONVERT(nvarchar(20), [PageStatus]), N''NULL''),
              N''; error type='', COALESCE(CONVERT(nvarchar(20), [ErrorType]), N''NULL''), N''.''),
       N''Automatische Seitenreparatur ist Einzelevidenz und ersetzt keine Integritätsprüfung.'',
       N''Seitenreparatur-, suspect_pages-, CHECKDB- und Backup-Evidenz gemeinsam prüfen.''
FROM OPENJSON(COALESCE(@Availability, N''{}''), ''$.pageRepair'') WITH
([DatabaseName] sysname, [ErrorType] int, [PageStatus] int, [FindingCode] varchar(80))
WHERE [FindingCode] <> ''PAGE_REPAIR_SUCCEEDED'';

INSERT [#DiagnosticFindings_Findings] ([SourceModule],[Category],[Severity],[Confidence],[ScopeType],[ScopeName],[FindingCode],[EvidenceMetric],[Evidence],[EvidenceLimit],[RecommendedNextCheck])
SELECT N''USP_AvailabilityDeepAnalysis'', ''AVAILABILITY'', ''HIGH'', ''MEDIUM'', N''DATABASE'',
       [DatabaseName], ''PHYSICAL_SEEDING_FAILURE'', CONVERT(decimal(38,4), [FailureCode]),
       CONCAT(N''seeding state='', COALESCE([CurrentStateDesc], N''NULL''),
              N''; failure code='', [FailureCode], N''.''),
       N''Die DMV zeigt nur aktuell aufbewahrte Seeding-Evidenz.'',
       N''Seedingstatus, Endpoint, Berechtigungen, Speicher und Netzwerk prüfen.''
FROM OPENJSON(COALESCE(@Availability, N''{}''), ''$.seeding'') WITH
([DatabaseName] sysname, [CurrentStateDesc] nvarchar(60), [FailureCode] int)
WHERE COALESCE([FailureCode], 0) <> 0;

INSERT [#DiagnosticFindings_Findings] ([SourceModule],[Category],[Severity],[Confidence],[ScopeType],[ScopeName],[FindingCode],[EvidenceMetric],[Evidence],[EvidenceLimit],[RecommendedNextCheck])
SELECT N''USP_AgentMonitoringAnalysis'', ''MONITORING'', [Severity], ''MEDIUM'', [ScopeType], [ScopeName],
       [FindingCode], CONVERT(decimal(38,4), [MetricValue]), [Evidence], [EvidenceLimit],
       N''SQL-Agent-Konfiguration mit externem Monitoring und Betriebsprozess abgleichen.''
FROM OPENJSON(COALESCE(@Agent, N''{}''), ''$.findings'') WITH
([Severity] varchar(16), [ScopeType] nvarchar(60), [ScopeName] nvarchar(256), [FindingCode] varchar(100),
 [MetricValue] bigint, [Evidence] nvarchar(1000), [EvidenceLimit] nvarchar(1000));

INSERT [#DiagnosticFindings_Findings] ([SourceModule],[Category],[Severity],[Confidence],[ScopeType],[ScopeName],[FindingCode],[EvidenceMetric],[Evidence],[EvidenceLimit],[RecommendedNextCheck])
SELECT N''USP_SchemaDesignAnalysis'', ''SCHEMA_DESIGN'', [Severity], ''HIGH'', [ObjectType],
       CONCAT([DatabaseName], N''/'', COALESCE([SchemaName] + N''.'', N''''), [ObjectName]),
       [FindingCode], [MetricValue], [Evidence], [EvidenceLimit],
       N''Workload, Abhängigkeiten und Änderungsrisiko vor DDL separat verifizieren.''
FROM OPENJSON(COALESCE(@Schema, N''{}''), ''$.findings'') WITH
([DatabaseName] sysname, [Severity] varchar(16), [ObjectType] nvarchar(60), [SchemaName] sysname,
 [ObjectName] sysname, [FindingCode] varchar(100), [MetricValue] decimal(38,4),
 [Evidence] nvarchar(1000), [EvidenceLimit] nvarchar(1000));

INSERT [#DiagnosticFindings_Findings] ([SourceModule],[Category],[Severity],[Confidence],[ScopeType],[ScopeName],[FindingCode],[EvidenceMetric],[Evidence],[EvidenceLimit],[RecommendedNextCheck])
SELECT N''USP_StatisticsDistributionAnalysis'', ''STATISTICS_DISTRIBUTION'', [Severity], [Confidence], N''STATISTICS'',
       CONCAT([DatabaseName],N''/'',[SchemaName],N''.'',[ObjectName],N''/'',[StatisticsName]),
       [FindingCode],[MetricValue],[Evidence],[EvidenceLimit],[RecommendedNextCheck]
FROM OPENJSON(COALESCE(@StatisticsDistribution, N''{}''), ''$.findings'') WITH
([DatabaseName] sysname, [SchemaName] sysname, [ObjectName] sysname, [StatisticsName] sysname,
 [Severity] varchar(16), [Confidence] varchar(16), [FindingCode] varchar(120),
 [MetricValue] decimal(38,4), [Evidence] nvarchar(1000), [EvidenceLimit] nvarchar(1000),
 [RecommendedNextCheck] nvarchar(1000));

INSERT [#DiagnosticFindings_Findings] ([SourceModule],[Category],[Severity],[Confidence],[ScopeType],[ScopeName],[FindingCode],[EvidenceMetric],[Evidence],[EvidenceLimit],[RecommendedNextCheck])
SELECT N''USP_IntelligentQueryProcessingAnalysis'', ''IQP'', [FindingSeverity], ''HIGH'', N''DATABASE'',
       [DatabaseName], [FindingCode], CONVERT(decimal(38,4), [CompatibilityLevel]),
       CONCAT(N''compatibility level='', [CompatibilityLevel], N''; query store='', [QueryStoreActualStateDesc], N''.''),
       [EvidenceLimit], N''Query-Store-Zustand und beabsichtigtes Compatibility Level prüfen.''
FROM OPENJSON(COALESCE(@Iqp, N''{}''), ''$.databaseState'') WITH
([DatabaseName] sysname, [CompatibilityLevel] int, [QueryStoreActualStateDesc] nvarchar(60),
 [FindingCode] varchar(80), [FindingSeverity] varchar(16), [EvidenceLimit] nvarchar(1000))
WHERE [FindingCode] <> ''IQP_EVIDENCE_AVAILABLE'';

INSERT [#DiagnosticFindings_Findings] ([SourceModule],[Category],[Severity],[Confidence],[ScopeType],[ScopeName],[FindingCode],[EvidenceMetric],[Evidence],[EvidenceLimit],[RecommendedNextCheck])
SELECT N''USP_InternalContentionAnalysis'', ''INTERNAL_CONTENTION'', ''MEDIUM'', ''MEDIUM'', N''LATCH'',
       [LatchClass], ''LATCH_WAIT_DELTA_REVIEW'', CONVERT(decimal(38,4), [WaitTimeMs]),
       CONCAT(N''wait time ms='', [WaitTimeMs], N''; waiting requests='', [WaitingRequests], N''; measurement='', [MeasurementKind], N''.''),
       N''Latchklasse und kurzes Intervall sind noch keine Ursachenfeststellung.'',
       N''Messung wiederholen und mit Workload, Waits und Hot Pages korrelieren.''
FROM OPENJSON(COALESCE(@Contention, N''{}''), ''$.latches'') WITH
([LatchClass] nvarchar(120), [MeasurementKind] varchar(30), [WaitingRequests] bigint, [WaitTimeMs] bigint)
WHERE [WaitTimeMs] >= @ContentionMinWaitMs;';

        BEGIN TRY
            EXEC [sys].[sp_executesql]
                  @ParseSql
                , N'@Integrity nvarchar(max), @Capacity nvarchar(max), @Memory nvarchar(max),
                    @Backup nvarchar(max), @Availability nvarchar(max), @Agent nvarchar(max),
                    @Schema nvarchar(max), @StatisticsDistribution nvarchar(max), @Iqp nvarchar(max), @Contention nvarchar(max),
                    @ContentionMinWaitMs bigint'
                , @Integrity = @IntegrityJson, @Capacity = @CapacityJson, @Memory = @MemoryJson
                , @Backup = @BackupJson, @Availability = @AvailabilityJson, @Agent = @AgentJson
                , @Schema = @SchemaJson, @StatisticsDistribution = @StatisticsDistributionJson
                , @Iqp = @IqpJson, @Contention = @ContentionJson
                , @ContentionMinWaitMs = @ContentionMinWaitMs;
        END TRY
        BEGIN CATCH
            INSERT @ModuleStatus VALUES (11, N'JSON_EVIDENCE_AGGREGATION', 'ERROR_HANDLED', NULL, 1, ERROR_NUMBER(), ERROR_MESSAGE());
        END CATCH;

        IF EXISTS
        (
            SELECT 1 FROM @ModuleStatus
            WHERE [InvocationStatus] NOT IN ('EXECUTED','REUSED_PARENT_RESULT')
               OR COALESCE([IsPartial], 0) = 1
               OR [EvidenceStatus] IN ('DENIED_PERMISSION','ERROR_HANDLED','DATABASE_UNAVAILABLE','UNAVAILABLE_FEATURE')
        )
        BEGIN
            SELECT @StatusCode = 'AVAILABLE_LIMITED', @IsPartial = 1;
            SELECT TOP (1) @ErrorNumber = [ErrorNumber], @ErrorMessage = [ErrorMessage]
            FROM @ModuleStatus
            WHERE [InvocationStatus] NOT IN ('EXECUTED','REUSED_PARENT_RESULT') OR COALESCE([IsPartial], 0) = 1
            ORDER BY [ExecutionOrdinal];
        END
        ELSE IF EXISTS (SELECT 1 FROM [#DiagnosticFindings_Findings])
            SET @StatusCode = 'AVAILABLE_WITH_FINDING';
    END;

    SELECT @StatusCodeOut = @StatusCode, @IsPartialOut = @IsPartial,
           @ErrorNumberOut = @ErrorNumber, @ErrorMessageOut = @ErrorMessage;

    IF @JsonErzeugen = 1
    BEGIN
        DECLARE @MetaJson nvarchar(max) =
            (SELECT N'DiagnosticFindings' AS [resultName], 1 AS [schemaVersion], @Now AS [generatedAtUtc],
                    @StatusCode AS [statusCode], @IsPartial AS [isPartial], @MinimumSeverity AS [minimumSeverity],
                    (SELECT COUNT_BIG(*) FROM [#DiagnosticFindings_Findings]) AS [totalFindingCount],
                    (SELECT COUNT_BIG(*) FROM [#DiagnosticFindings_Findings]
                     WHERE CASE [Severity] WHEN 'HIGH' THEN 4 WHEN 'MEDIUM' THEN 3 WHEN 'LOW' THEN 2 ELSE 1 END
                           >= CASE @MinimumSeverity WHEN 'HIGH' THEN 4 WHEN 'MEDIUM' THEN 3 WHEN 'LOW' THEN 2 ELSE 1 END)
                    AS [returnedFindingCount]
             FOR JSON PATH, WITHOUT_ARRAY_WRAPPER);
        DECLARE @FindingsJson nvarchar(max) =
            (SELECT TOP (@Limit) * FROM [#DiagnosticFindings_Findings]
             WHERE CASE [Severity] WHEN 'HIGH' THEN 4 WHEN 'MEDIUM' THEN 3 WHEN 'LOW' THEN 2 ELSE 1 END
                   >= CASE @MinimumSeverity WHEN 'HIGH' THEN 4 WHEN 'MEDIUM' THEN 3 WHEN 'LOW' THEN 2 ELSE 1 END
             ORDER BY CASE [Severity] WHEN 'HIGH' THEN 1 WHEN 'MEDIUM' THEN 2 WHEN 'LOW' THEN 3 ELSE 4 END,
                      [FindingOrdinal] FOR JSON PATH, INCLUDE_NULL_VALUES);
        DECLARE @ModulesJson nvarchar(max) =
            (SELECT * FROM @ModuleStatus ORDER BY [ExecutionOrdinal] FOR JSON PATH, INCLUDE_NULL_VALUES);
        SET @Json = CONCAT(N'{"meta":', COALESCE(@MetaJson, N'{}'),
                           N',"findings":', COALESCE(@FindingsJson, N'[]'),
                           N',"modules":', COALESCE(@ModulesJson, N'[]'), N'}');
    END;

    IF @OutputMode = 'RAW'
    BEGIN
        SELECT N'USP_DiagnosticFindings' AS [ModuleName], @Now AS [CollectionTimeUtc],
               @StatusCode AS [StatusCode], @IsPartial AS [IsPartial],
               (SELECT COUNT_BIG(*) FROM [#DiagnosticFindings_Findings]) AS [FindingCount],
               @ErrorNumber AS [ErrorNumber], @ErrorMessage AS [ErrorMessage],
               N'Normalisierte Triage über Kindmodul-Evidenz; keine automatische Ursachenfeststellung.' AS [Detail];
        SELECT TOP (@Limit) * FROM [#DiagnosticFindings_Findings]
        WHERE CASE [Severity] WHEN 'HIGH' THEN 4 WHEN 'MEDIUM' THEN 3 WHEN 'LOW' THEN 2 ELSE 1 END
              >= CASE @MinimumSeverity WHEN 'HIGH' THEN 4 WHEN 'MEDIUM' THEN 3 WHEN 'LOW' THEN 2 ELSE 1 END
        ORDER BY CASE [Severity] WHEN 'HIGH' THEN 1 WHEN 'MEDIUM' THEN 2 WHEN 'LOW' THEN 3 ELSE 4 END,
                 [FindingOrdinal];
        SELECT * FROM @ModuleStatus ORDER BY [ExecutionOrdinal];
    END
    ELSE IF @OutputMode = 'CONSOLE'
    BEGIN
        SELECT N'Diagnostische Befunde' AS [Ergebnis], @Now AS [Stand_UTC], @StatusCode AS [Status],
               @MinimumSeverity AS [Mindestprioritaet], (SELECT COUNT_BIG(*) FROM [#DiagnosticFindings_Findings]) AS [Befunde_gesamt],
               @ErrorMessage AS [Hinweis];
        SELECT TOP (@Limit) N'Diagnostischer Befund' AS [Ergebnis], [Severity] AS [Prioritaet],
               [Confidence] AS [Konfidenz], [Category] AS [Kategorie], [ScopeType] AS [Bereichstyp],
               [ScopeName] AS [Bereich], [FindingCode] AS [Befund], [EvidenceMetric] AS [Messwert],
               [Evidence] AS [Evidenz], [EvidenceLimit] AS [Grenze], [RecommendedNextCheck] AS [Naechste_Pruefung]
        FROM [#DiagnosticFindings_Findings]
        WHERE CASE [Severity] WHEN 'HIGH' THEN 4 WHEN 'MEDIUM' THEN 3 WHEN 'LOW' THEN 2 ELSE 1 END
              >= CASE @MinimumSeverity WHEN 'HIGH' THEN 4 WHEN 'MEDIUM' THEN 3 WHEN 'LOW' THEN 2 ELSE 1 END
        ORDER BY CASE [Severity] WHEN 'HIGH' THEN 1 WHEN 'MEDIUM' THEN 2 WHEN 'LOW' THEN 3 ELSE 4 END,
                 [FindingOrdinal];
        SELECT N'Befund-Quellmodul' AS [Ergebnis], [ExecutionOrdinal] AS [Reihenfolge],
               [ModuleName] AS [Modul], [InvocationStatus] AS [Aufrufstatus],
               [EvidenceStatus] AS [Evidenzstatus], [IsPartial] AS [Teilweise], [ErrorMessage] AS [Fehler]
        FROM @ModuleStatus ORDER BY [ExecutionOrdinal];
    END;
    IF @ConsoleResultRequested = 1
    BEGIN
        EXEC [monitor].[InternalEmitConsoleResult]
              @SourceTable=N'#DiagnosticFindings_Findings'
            , @ResultLabel=N'DiagnosticFindings'
            , @EmptyMessage=N'Keine fachlichen Ergebnisse';
    END;
    IF @TableResultRequested = 1
    BEGIN
        EXEC [monitor].[InternalWriteResultTable]
              @SourceTable = N'#DiagnosticFindings_Findings'
            , @TargetTable=@TableTarget
            , @ThrowOnError = 1;
    END;
END;
GO
-- END SOURCE: Code/08_ServerHealth/170_USP_DiagnosticFindings.sql

-- BEGIN SOURCE: Code/08_ServerHealth/180_USP_WorkerPressureAnalysis.sql
/*
===============================================================================
Objekt       : monitor.USP_WorkerPressureAnalysis
Version      : 1.0.0
Stand        : 2026-07-21
Zweck        : Korreliert Worker-Verfügbarkeit, Scheduler-Queues, THREADPOOL,
               Blocking und begrenzte laufende Requests in einem kurzen Sample.
Zeitvertrag  : Zwei Schedulerbeobachtungen bei @SampleSeconds>0; Worker, Waits
               und Requests sind flüchtige Snapshots am Sampleende.
Abgrenzung   : work_queue_count bedeutet fehlenden Worker; runnable_tasks_count
               bedeutet CPU-Warteschlange. Kein Befund empfiehlt automatisch
               eine Änderung von max worker threads.
Eigenlast    : Ein aggregierter Scan von dm_os_workers sowie kleine Scheduler-,
               Wait- und Request-Snapshots; keine SQL- oder Plantexte.
===============================================================================
*/
CREATE OR ALTER PROCEDURE [monitor].[USP_WorkerPressureAnalysis]
      @SampleSeconds       tinyint         = 1
    , @MinRequestElapsedMs int             = 5000
    , @MaxZeilen           int             = 1000
    , @ResultSetArt        varchar(16)     = 'CONSOLE'
    , @ResultTablesJson    nvarchar(max)   = NULL
    , @JsonErzeugen        bit             = 0
    , @Json                nvarchar(max)   = NULL OUTPUT
    , @PrintMeldungen      bit             = 1
    , @Hilfe               bit             = 0
    , @StatusCodeOut       varchar(40)     = NULL OUTPUT
    , @IsPartialOut        bit             = NULL OUTPUT
    , @ErrorNumberOut      int             = NULL OUTPUT
    , @ErrorMessageOut     nvarchar(2048)  = NULL OUTPUT
AS
BEGIN
    SET NOCOUNT ON;
    SET @Json=NULL;

    DECLARE @CapturedAtUtc datetime2(3)=SYSUTCDATETIME();
    DECLARE @SampleStartUtc datetime2(3)=SYSUTCDATETIME();
    DECLARE @SampleEndUtc datetime2(3)=NULL;
    DECLARE @OutputMode varchar(16)=UPPER(LTRIM(RTRIM(COALESCE(@ResultSetArt,''))));
    DECLARE @ConsoleResultRequested bit=CASE WHEN UPPER(LTRIM(RTRIM(COALESCE(@ResultSetArt,''))))='CONSOLE' THEN 1 ELSE 0 END;
    DECLARE @StatusCode varchar(40)='AVAILABLE';
    DECLARE @IsPartial bit=0;
    DECLARE @ErrorNumber int=NULL;
    DECLARE @ErrorMessage nvarchar(2048)=NULL;
    DECLARE @Limit bigint=CASE WHEN @MaxZeilen IS NULL OR @MaxZeilen=0 THEN CONVERT(bigint,9223372036854775807) ELSE CONVERT(bigint,@MaxZeilen) END;
    DECLARE @CandidateLimit bigint=CASE WHEN @MaxZeilen IS NULL OR @MaxZeilen=0 THEN CONVERT(bigint,9223372036854775807) WHEN @MaxZeilen BETWEEN 1 AND 2147483646 THEN CONVERT(bigint,@MaxZeilen)+1 ELSE CONVERT(bigint,@MaxZeilen) END;
    DECLARE @Delay char(8);

    IF @Hilfe=1
    BEGIN
        PRINT N'monitor.USP_WorkerPressureAnalysis';
        PRINT N'@SampleSeconds=0 liefert einen Snapshot; 1..60 liefert Scheduler-Deltas und einen Snapshot am Sampleende.';
        PRINT N'@MinRequestElapsedMs begrenzt den Requestkontext; SQL-, Plan-, Login-, Host- und Programmnamen werden nicht gelesen.';
        PRINT N'work_queue_count/THREADPOOL zeigen Workerbedarf; runnable_tasks_count zeigt CPU-Warteschlange.';
        PRINT N'Kein Einzelindikator rechtfertigt automatisch eine Änderung von max worker threads.';
        PRINT N'@ResultSetArt=CONSOLE|RAW|TABLE|NONE; TABLE-Namen: moduleStatus, summary, schedulers, waits, requests, sourceStatus, warnings.';
        RETURN;
    END;

    CREATE TABLE [#WorkerPressureAnalysis_ResultTableMap]
    (
          [ResultName] sysname COLLATE SQL_Latin1_General_CP1_CS_AS NOT NULL PRIMARY KEY
        , [TargetTable] sysname COLLATE SQL_Latin1_General_CP1_CS_AS NOT NULL UNIQUE
    );

    CREATE TABLE [#WorkerPressureAnalysis_SchedulerBefore]
    (
          [SchedulerAddress] varbinary(8) NOT NULL PRIMARY KEY
        , [SchedulerId] int NOT NULL
        , [ParentNodeId] int NOT NULL
        , [CpuId] smallint NOT NULL
        , [Status] nvarchar(60) NOT NULL
        , [CurrentTasks] int NOT NULL
        , [RunnableTasks] int NOT NULL
        , [CurrentWorkers] int NOT NULL
        , [ActiveWorkers] int NOT NULL
        , [WorkQueueCount] bigint NOT NULL
        , [PendingDiskIoCount] int NOT NULL
        , [ContextSwitches] int NOT NULL
        , [YieldCount] int NOT NULL
        , [TotalCpuUsageMs] bigint NOT NULL
        , [TotalSchedulerDelayMs] bigint NOT NULL
        , [FailedToCreateWorker] bit NULL
        , [IdealWorkersLimit] int NULL
    );

    CREATE TABLE [#WorkerPressureAnalysis_SchedulerAfter]
    (
          [SchedulerAddress] varbinary(8) NOT NULL PRIMARY KEY
        , [SchedulerId] int NOT NULL
        , [ParentNodeId] int NOT NULL
        , [CpuId] smallint NOT NULL
        , [Status] nvarchar(60) NOT NULL
        , [CurrentTasks] int NOT NULL
        , [RunnableTasks] int NOT NULL
        , [CurrentWorkers] int NOT NULL
        , [ActiveWorkers] int NOT NULL
        , [WorkQueueCount] bigint NOT NULL
        , [PendingDiskIoCount] int NOT NULL
        , [ContextSwitches] int NOT NULL
        , [YieldCount] int NOT NULL
        , [TotalCpuUsageMs] bigint NOT NULL
        , [TotalSchedulerDelayMs] bigint NOT NULL
        , [FailedToCreateWorker] bit NULL
        , [IdealWorkersLimit] int NULL
    );

    CREATE TABLE [#WorkerPressureAnalysis_Workers]
    (
          [SchedulerAddress] varbinary(8) NOT NULL PRIMARY KEY
        , [WorkerCount] int NOT NULL
        , [RunningWorkers] int NOT NULL
        , [RunnableWorkers] int NOT NULL
        , [SuspendedWorkers] int NOT NULL
        , [PreemptiveWorkers] int NOT NULL
        , [SickWorkers] int NOT NULL
    );

    CREATE TABLE [#WorkerPressureAnalysis_Schedulers]
    (
          [SchedulerId] int NOT NULL
        , [ParentNodeId] int NOT NULL
        , [CpuId] smallint NOT NULL
        , [Status] nvarchar(60) NOT NULL
        , [SampleSeconds] decimal(19,6) NOT NULL
        , [CurrentTasks] int NOT NULL
        , [RunnableTasks] int NOT NULL
        , [CurrentWorkers] int NOT NULL
        , [ActiveWorkers] int NOT NULL
        , [WorkQueueCount] bigint NOT NULL
        , [PendingDiskIoCount] int NOT NULL
        , [WorkerCountFromWorkerDmv] int NULL
        , [RunningWorkers] int NULL
        , [RunnableWorkers] int NULL
        , [SuspendedWorkers] int NULL
        , [PreemptiveWorkers] int NULL
        , [SickWorkers] int NULL
        , [WorkQueueDelta] bigint NULL
        , [RunnableTasksDelta] int NULL
        , [CurrentWorkersDelta] int NULL
        , [ActiveWorkersDelta] int NULL
        , [ContextSwitchDelta] bigint NULL
        , [YieldDelta] bigint NULL
        , [CpuUsageDeltaMs] bigint NULL
        , [SchedulerDelayDeltaMs] bigint NULL
        , [CounterResetDetected] bit NOT NULL
        , [FailedToCreateWorker] bit NULL
        , [IdealWorkersLimit] int NULL
        , [FindingCode] varchar(80) NOT NULL
        , [EvidenceLimit] nvarchar(1000) NOT NULL
    );

    CREATE TABLE [#WorkerPressureAnalysis_Waits]
    (
          [WaitType] nvarchar(60) NOT NULL
        , [WaitingTaskCount] bigint NOT NULL
        , [MaxWaitDurationMs] bigint NOT NULL
        , [BlockedTaskCount] bigint NOT NULL
        , [FindingCode] varchar(80) NOT NULL
    );

    CREATE TABLE [#WorkerPressureAnalysis_Requests]
    (
          [SessionId] smallint NOT NULL
        , [RequestId] int NOT NULL
        , [SchedulerId] int NULL
        , [RequestStatus] nvarchar(30) NOT NULL
        , [Command] nvarchar(32) NOT NULL
        , [ElapsedMs] int NOT NULL
        , [CpuMs] int NOT NULL
        , [LogicalReads] bigint NOT NULL
        , [Reads] bigint NOT NULL
        , [Writes] bigint NOT NULL
        , [Dop] smallint NULL
        , [BlockingSessionId] smallint NULL
        , [WaitType] nvarchar(60) NULL
        , [WaitTimeMs] int NOT NULL
        , [ContextReason] varchar(80) NOT NULL
        , PRIMARY KEY([SessionId],[RequestId])
    );

    CREATE TABLE [#WorkerPressureAnalysis_Summary]
    (
          [CapturedAtUtc] datetime2(3) NOT NULL
        , [SampleStartUtc] datetime2(3) NOT NULL
        , [SampleEndUtc] datetime2(3) NOT NULL
        , [SampleSeconds] decimal(19,6) NOT NULL
        , [VisibleOnlineSchedulers] int NULL
        , [ConfiguredMaxWorkerThreads] int NULL
        , [EffectiveMaxWorkers] int NULL
        , [CurrentWorkerCount] int NULL
        , [AvailableWorkerCapacity] int NULL
        , [WorkerOccupancyPercent] decimal(9,2) NULL
        , [TotalWorkQueueCount] bigint NULL
        , [TotalRunnableTasks] bigint NULL
        , [MaxWorkQueuePerScheduler] bigint NULL
        , [MaxRunnablePerScheduler] int NULL
        , [ThreadpoolWaitingTaskCount] bigint NULL
        , [BlockingRequestCount] bigint NULL
        , [LongRequestCount] bigint NULL
        , [FailedToCreateWorkerSchedulers] int NULL
        , [FindingCode] varchar(80) NOT NULL
        , [Interpretation] nvarchar(1000) NOT NULL
    );

    CREATE TABLE [#WorkerPressureAnalysis_SourceStatus]
    (
          [SourceOrdinal] int NOT NULL PRIMARY KEY
        , [SourceName] sysname NOT NULL
        , [SourceObject] nvarchar(256) NOT NULL
        , [CapturedAtUtc] datetime2(3) NOT NULL
        , [StatusCode] varchar(40) NOT NULL
        , [IsPartial] bit NOT NULL
        , [ReturnedRowCount] bigint NOT NULL
        , [ErrorNumber] int NULL
        , [ErrorMessage] nvarchar(2048) NULL
        , [EvidenceLimit] nvarchar(1000) NOT NULL
    );

    CREATE TABLE [#WorkerPressureAnalysis_Warnings]
    (
          [WarningOrdinal] int IDENTITY(1,1) NOT NULL
        , [SourceName] sysname NOT NULL
        , [StatusCode] varchar(40) NOT NULL
        , [ErrorNumber] int NULL
        , [Message] nvarchar(2048) NOT NULL
    );

    CREATE TABLE [#WorkerPressureAnalysis_ModuleStatus]
    (
          [ModuleName] sysname NOT NULL
        , [CapturedAtUtc] datetime2(3) NOT NULL
        , [StatusCode] varchar(40) NOT NULL
        , [IsPartial] bit NOT NULL
        , [SampleSeconds] tinyint NOT NULL
        , [ReturnedSchedulerRows] bigint NOT NULL
        , [ReturnedRequestRows] bigint NOT NULL
        , [HasMoreRequestRows] bit NOT NULL
        , [ErrorNumber] int NULL
        , [ErrorMessage] nvarchar(2048) NULL
    );

    IF @SampleSeconds IS NULL OR @SampleSeconds>60
       OR @MinRequestElapsedMs IS NULL OR @MinRequestElapsedMs<0 OR @MaxZeilen<0
       OR @JsonErzeugen IS NULL OR @PrintMeldungen IS NULL
       OR @OutputMode NOT IN('CONSOLE','RAW','TABLE','NONE')
       OR (@OutputMode<>'TABLE' AND NULLIF(LTRIM(RTRIM(COALESCE(@ResultTablesJson,N''))),N'') IS NOT NULL)
    BEGIN
        SELECT @StatusCode='INVALID_PARAMETER',@IsPartial=1,
               @ErrorMessage=N'Ungültiger Sample-, Request-, Zeilen- oder Ausgabeparameter.';
    END;

    IF @StatusCode='AVAILABLE' AND @OutputMode='TABLE'
        EXEC [monitor].[InternalPrepareResultTables]
              @ResultTablesJson=@ResultTablesJson
            , @AllowedResultNames=N'moduleStatus|summary|schedulers|waits|requests|sourceStatus|warnings'
            , @MappingTable=N'#WorkerPressureAnalysis_ResultTableMap'
            , @StatusCode=@StatusCode OUTPUT
            , @ErrorMessage=@ErrorMessage OUTPUT
            , @ThrowOnError=1;

    SET LOCK_TIMEOUT 0;

    DECLARE @SchedulerStatus varchar(40)='NOT_EXECUTED',@SchedulerError int=NULL,@SchedulerMessage nvarchar(2048)=NULL;
    DECLARE @WorkerStatus varchar(40)='NOT_EXECUTED',@WorkerError int=NULL,@WorkerMessage nvarchar(2048)=NULL;
    DECLARE @WaitStatus varchar(40)='NOT_EXECUTED',@WaitError int=NULL,@WaitMessage nvarchar(2048)=NULL;
    DECLARE @RequestStatus varchar(40)='NOT_EXECUTED',@RequestError int=NULL,@RequestMessage nvarchar(2048)=NULL;
    DECLARE @EffectiveMaxWorkers int=NULL,@ConfiguredMaxWorkers int=NULL,@SchedulerCount int=NULL;

    IF @StatusCode='AVAILABLE'
    BEGIN TRY
        SELECT @EffectiveMaxWorkers=[max_workers_count],@SchedulerCount=[scheduler_count]
        FROM [sys].[dm_os_sys_info] WITH (NOLOCK);
        SELECT @ConfiguredMaxWorkers=TRY_CONVERT(int,[value_in_use])
        FROM [sys].[configurations] WITH (NOLOCK)
        WHERE [name]=N'max worker threads';

        INSERT [#WorkerPressureAnalysis_SchedulerBefore]
        SELECT [scheduler_address],[scheduler_id],[parent_node_id],[cpu_id],[status],
               [current_tasks_count],[runnable_tasks_count],[current_workers_count],
               [active_workers_count],[work_queue_count],[pending_disk_io_count],
               [context_switches_count],[yield_count],[total_cpu_usage_ms],
               [total_scheduler_delay_ms],[failed_to_create_worker],[ideal_workers_limit]
        FROM [sys].[dm_os_schedulers] WITH (NOLOCK)
        WHERE [scheduler_id]<1048576 AND [status]=N'VISIBLE ONLINE';

        IF @SampleSeconds>0
        BEGIN
            SET @Delay=CONVERT(char(8),DATEADD(SECOND,@SampleSeconds,CONVERT(time(0),'00:00:00')),108);
            WAITFOR DELAY @Delay;
            INSERT [#WorkerPressureAnalysis_SchedulerAfter]
            SELECT [scheduler_address],[scheduler_id],[parent_node_id],[cpu_id],[status],
                   [current_tasks_count],[runnable_tasks_count],[current_workers_count],
                   [active_workers_count],[work_queue_count],[pending_disk_io_count],
                   [context_switches_count],[yield_count],[total_cpu_usage_ms],
                   [total_scheduler_delay_ms],[failed_to_create_worker],[ideal_workers_limit]
            FROM [sys].[dm_os_schedulers] WITH (NOLOCK)
            WHERE [scheduler_id]<1048576 AND [status]=N'VISIBLE ONLINE';
        END
        ELSE
            INSERT [#WorkerPressureAnalysis_SchedulerAfter] SELECT * FROM [#WorkerPressureAnalysis_SchedulerBefore];

        SET @SampleEndUtc=SYSUTCDATETIME();
        SET @SchedulerStatus='AVAILABLE';
    END TRY
    BEGIN CATCH
        SELECT @SchedulerStatus=CASE WHEN ERROR_NUMBER() IN(229,262,297,300,371) THEN 'DENIED_PERMISSION' WHEN ERROR_NUMBER()=1222 THEN 'TIMEOUT' ELSE 'ERROR_HANDLED' END,
               @SchedulerError=ERROR_NUMBER(),@SchedulerMessage=ERROR_MESSAGE();
    END CATCH;

    IF @SampleEndUtc IS NULL SET @SampleEndUtc=SYSUTCDATETIME();

    IF @StatusCode='AVAILABLE'
    BEGIN TRY
        INSERT [#WorkerPressureAnalysis_Workers]
        SELECT [scheduler_address],TRY_CONVERT(int,COUNT_BIG(*)),
               TRY_CONVERT(int,SUM(CASE WHEN [state]=N'RUNNING' THEN 1 ELSE 0 END)),
               TRY_CONVERT(int,SUM(CASE WHEN [state]=N'RUNNABLE' THEN 1 ELSE 0 END)),
               TRY_CONVERT(int,SUM(CASE WHEN [state]=N'SUSPENDED' THEN 1 ELSE 0 END)),
               TRY_CONVERT(int,SUM(CASE WHEN [is_preemptive]=1 THEN 1 ELSE 0 END)),
               TRY_CONVERT(int,SUM(CASE WHEN [is_sick]=1 THEN 1 ELSE 0 END))
        FROM [sys].[dm_os_workers] WITH (NOLOCK)
        GROUP BY [scheduler_address];
        SET @WorkerStatus='AVAILABLE';
    END TRY
    BEGIN CATCH
        SELECT @WorkerStatus=CASE WHEN ERROR_NUMBER() IN(229,262,297,300,371) THEN 'DENIED_PERMISSION' WHEN ERROR_NUMBER()=1222 THEN 'TIMEOUT' ELSE 'ERROR_HANDLED' END,
               @WorkerError=ERROR_NUMBER(),@WorkerMessage=ERROR_MESSAGE();
    END CATCH;

    IF @StatusCode='AVAILABLE'
    BEGIN TRY
        INSERT [#WorkerPressureAnalysis_Waits]
        SELECT [wait_type],COUNT_BIG(*),MAX([wait_duration_ms]),
               SUM(CONVERT(bigint,CASE WHEN [blocking_session_id] IS NULL OR [blocking_session_id]=0 THEN 0 ELSE 1 END)),
               CASE WHEN [wait_type]=N'THREADPOOL' THEN 'THREADPOOL_WAIT_VISIBLE' ELSE 'CORRELATED_WAIT_CONTEXT' END
        FROM [sys].[dm_os_waiting_tasks] WITH (NOLOCK)
        WHERE [wait_type]=N'THREADPOOL'
        GROUP BY [wait_type];
        SET @WaitStatus='AVAILABLE';
    END TRY
    BEGIN CATCH
        SELECT @WaitStatus=CASE WHEN ERROR_NUMBER() IN(229,262,297,300,371) THEN 'DENIED_PERMISSION' WHEN ERROR_NUMBER()=1222 THEN 'TIMEOUT' ELSE 'ERROR_HANDLED' END,
               @WaitError=ERROR_NUMBER(),@WaitMessage=ERROR_MESSAGE();
    END CATCH;

    IF @StatusCode='AVAILABLE'
    BEGIN TRY
        INSERT [#WorkerPressureAnalysis_Requests]
        SELECT TOP(@CandidateLimit) [session_id],[request_id],[scheduler_id],[status],[command],
               [total_elapsed_time],[cpu_time],[logical_reads],[reads],[writes],[dop],
               NULLIF([blocking_session_id],0),[wait_type],[wait_time],
               CASE WHEN [wait_type]=N'THREADPOOL' THEN 'THREADPOOL'
                    WHEN [blocking_session_id]<>0 THEN 'BLOCKED_REQUEST'
                    ELSE 'LONG_RUNNING_REQUEST' END
        FROM [sys].[dm_exec_requests] WITH (NOLOCK)
        WHERE [session_id]<>@@SPID
          AND ([wait_type]=N'THREADPOOL' OR [blocking_session_id]<>0 OR [total_elapsed_time]>=@MinRequestElapsedMs)
        ORDER BY CASE WHEN [wait_type]=N'THREADPOOL' THEN 0 WHEN [blocking_session_id]<>0 THEN 1 ELSE 2 END,
                 [total_elapsed_time] DESC,[session_id],[request_id];
        SET @RequestStatus='AVAILABLE';
    END TRY
    BEGIN CATCH
        SELECT @RequestStatus=CASE WHEN ERROR_NUMBER() IN(229,262,297,300,371) THEN 'DENIED_PERMISSION' WHEN ERROR_NUMBER()=1222 THEN 'TIMEOUT' ELSE 'ERROR_HANDLED' END,
               @RequestError=ERROR_NUMBER(),@RequestMessage=ERROR_MESSAGE();
    END CATCH;

    IF @SchedulerStatus='AVAILABLE'
    BEGIN
        INSERT [#WorkerPressureAnalysis_Schedulers]
        SELECT [a].[SchedulerId],[a].[ParentNodeId],[a].[CpuId],[a].[Status],
               CONVERT(decimal(19,6),DATEDIFF_BIG(MICROSECOND,@SampleStartUtc,@SampleEndUtc)/1000000.0),
               [a].[CurrentTasks],[a].[RunnableTasks],[a].[CurrentWorkers],[a].[ActiveWorkers],
               [a].[WorkQueueCount],[a].[PendingDiskIoCount],[w].[WorkerCount],[w].[RunningWorkers],
               [w].[RunnableWorkers],[w].[SuspendedWorkers],[w].[PreemptiveWorkers],[w].[SickWorkers],
               CASE WHEN @SampleSeconds>0 THEN [a].[WorkQueueCount]-[b].[WorkQueueCount] END,
               CASE WHEN @SampleSeconds>0 THEN [a].[RunnableTasks]-[b].[RunnableTasks] END,
               CASE WHEN @SampleSeconds>0 THEN [a].[CurrentWorkers]-[b].[CurrentWorkers] END,
               CASE WHEN @SampleSeconds>0 THEN [a].[ActiveWorkers]-[b].[ActiveWorkers] END,
               CASE WHEN @SampleSeconds>0 AND [a].[ContextSwitches]>=[b].[ContextSwitches]
                    THEN CONVERT(bigint,[a].[ContextSwitches])-CONVERT(bigint,[b].[ContextSwitches]) END,
               CASE WHEN @SampleSeconds>0 AND [a].[YieldCount]>=[b].[YieldCount]
                    THEN CONVERT(bigint,[a].[YieldCount])-CONVERT(bigint,[b].[YieldCount]) END,
               CASE WHEN @SampleSeconds>0 AND [a].[TotalCpuUsageMs]>=[b].[TotalCpuUsageMs]
                    THEN [a].[TotalCpuUsageMs]-[b].[TotalCpuUsageMs] END,
               CASE WHEN @SampleSeconds>0 AND [a].[TotalSchedulerDelayMs]>=[b].[TotalSchedulerDelayMs]
                    THEN [a].[TotalSchedulerDelayMs]-[b].[TotalSchedulerDelayMs] END,
               CONVERT(bit,CASE WHEN @SampleSeconds>0 AND
                    ([a].[ContextSwitches]<[b].[ContextSwitches] OR [a].[YieldCount]<[b].[YieldCount]
                     OR [a].[TotalCpuUsageMs]<[b].[TotalCpuUsageMs]
                     OR [a].[TotalSchedulerDelayMs]<[b].[TotalSchedulerDelayMs]) THEN 1 ELSE 0 END),
               [a].[FailedToCreateWorker],[a].[IdealWorkersLimit],
               CASE WHEN [a].[WorkQueueCount]>0 THEN 'WORKER_QUEUE_VISIBLE'
                    WHEN [a].[RunnableTasks]>0 THEN 'RUNNABLE_CPU_QUEUE_VISIBLE'
                    WHEN [a].[FailedToCreateWorker]=1 THEN 'WORKER_CREATION_FAILED'
                    ELSE 'NO_QUEUE_VISIBLE_IN_SAMPLE' END,
               N'Flüchtiger Schedulerzustand. work_queue_count und runnable_tasks_count haben verschiedene Bedeutungen; ein Snapshot beweist weder Dauer noch Ursache.'
        FROM [#WorkerPressureAnalysis_SchedulerAfter] AS [a]
        LEFT JOIN [#WorkerPressureAnalysis_SchedulerBefore] AS [b] ON [b].[SchedulerAddress]=[a].[SchedulerAddress]
        LEFT JOIN [#WorkerPressureAnalysis_Workers] AS [w] ON [w].[SchedulerAddress]=[a].[SchedulerAddress];
    END;

    DECLARE @CurrentWorkerCount int=(SELECT SUM([WorkerCount]) FROM [#WorkerPressureAnalysis_Workers]);
    DECLARE @AvailableWorkerCapacity int=CASE WHEN @EffectiveMaxWorkers IS NULL OR @CurrentWorkerCount IS NULL THEN NULL WHEN @EffectiveMaxWorkers>@CurrentWorkerCount THEN @EffectiveMaxWorkers-@CurrentWorkerCount ELSE 0 END;
    DECLARE @WorkQueue bigint=(SELECT SUM([WorkQueueCount]) FROM [#WorkerPressureAnalysis_Schedulers]);
    DECLARE @Runnable bigint=(SELECT SUM(CONVERT(bigint,[RunnableTasks])) FROM [#WorkerPressureAnalysis_Schedulers]);
    DECLARE @Threadpool bigint=COALESCE((SELECT SUM([WaitingTaskCount]) FROM [#WorkerPressureAnalysis_Waits] WHERE [WaitType]=N'THREADPOOL'),0);
    DECLARE @Blocking bigint=(SELECT COUNT_BIG(*) FROM [#WorkerPressureAnalysis_Requests] WHERE [BlockingSessionId] IS NOT NULL);
    DECLARE @LongRequests bigint=(SELECT COUNT_BIG(*) FROM [#WorkerPressureAnalysis_Requests] WHERE [ElapsedMs]>=@MinRequestElapsedMs);

    INSERT [#WorkerPressureAnalysis_Summary]
    SELECT @CapturedAtUtc,@SampleStartUtc,@SampleEndUtc,
           CONVERT(decimal(19,6),DATEDIFF_BIG(MICROSECOND,@SampleStartUtc,@SampleEndUtc)/1000000.0),
           (SELECT COUNT(*) FROM [#WorkerPressureAnalysis_Schedulers]),@ConfiguredMaxWorkers,@EffectiveMaxWorkers,@CurrentWorkerCount,@AvailableWorkerCapacity,
           CONVERT(decimal(9,2),100.0*@CurrentWorkerCount/NULLIF(@EffectiveMaxWorkers,0)),
           @WorkQueue,@Runnable,(SELECT MAX([WorkQueueCount]) FROM [#WorkerPressureAnalysis_Schedulers]),
           (SELECT MAX([RunnableTasks]) FROM [#WorkerPressureAnalysis_Schedulers]),@Threadpool,@Blocking,@LongRequests,
           (SELECT COUNT(*) FROM [#WorkerPressureAnalysis_Schedulers] WHERE [FailedToCreateWorker]=1),
           CASE WHEN COALESCE(@WorkQueue,0)>0 OR @Threadpool>0 THEN 'WORKER_QUEUE_PRESSURE_VISIBLE'
                WHEN COALESCE(@Runnable,0)>0 THEN 'CPU_RUNNABLE_QUEUE_VISIBLE'
                ELSE 'NO_WORKER_PRESSURE_VISIBLE_IN_SAMPLE' END,
           CASE WHEN COALESCE(@WorkQueue,0)>0 OR @Threadpool>0
                THEN N'Workerbedarf ist sichtbar. Blocking, lange Requests, Parallelität und Ressourcenengpässe prüfen; max worker threads nicht aus diesem Einzelindikator ändern.'
                WHEN COALESCE(@Runnable,0)>0
                THEN N'Runnable Tasks warten auf Schedulerzeit. CPU, teure Pläne, Reads und Parallelität prüfen; dies ist kein THREADPOOL-Nachweis.'
                ELSE N'Das begrenzte Sample zeigt keinen Worker-Queue-Druck. Andere Zeitpunkte und längere Trends bleiben unbewertet.' END;

    INSERT [#WorkerPressureAnalysis_SourceStatus]
    VALUES
      (1,N'schedulers',N'sys.dm_os_schedulers|sys.dm_os_sys_info|sys.configurations',@CapturedAtUtc,@SchedulerStatus,CONVERT(bit,CASE WHEN @SchedulerStatus='AVAILABLE' THEN 0 ELSE 1 END),(SELECT COUNT_BIG(*) FROM [#WorkerPressureAnalysis_Schedulers]),@SchedulerError,@SchedulerMessage,N'Zwei Beobachtungen nur bei @SampleSeconds>0; Counter können beim Engine-Neustart zurückgesetzt werden.'),
      (2,N'workers',N'sys.dm_os_workers',@CapturedAtUtc,@WorkerStatus,CONVERT(bit,CASE WHEN @WorkerStatus='AVAILABLE' THEN 0 ELSE 1 END),(SELECT COUNT_BIG(*) FROM [#WorkerPressureAnalysis_Workers]),@WorkerError,@WorkerMessage,N'Ein vollständiger Worker-DMV-Scan wird sofort je Scheduler aggregiert; kein Workerdetail wird ausgegeben.'),
      (3,N'waits',N'sys.dm_os_waiting_tasks',@CapturedAtUtc,@WaitStatus,CONVERT(bit,CASE WHEN @WaitStatus='AVAILABLE' THEN 0 ELSE 1 END),(SELECT COUNT_BIG(*) FROM [#WorkerPressureAnalysis_Waits]),@WaitError,@WaitMessage,N'Flüchtiger THREADPOOL-Waitsnapshot; fehlende Zeilen beweisen keine Abwesenheit zu anderen Zeitpunkten.'),
      (4,N'requests',N'sys.dm_exec_requests',@CapturedAtUtc,@RequestStatus,CONVERT(bit,CASE WHEN @RequestStatus='AVAILABLE' THEN 0 ELSE 1 END),(SELECT COUNT_BIG(*) FROM [#WorkerPressureAnalysis_Requests]),@RequestError,@RequestMessage,N'Begrenzter aktueller Kontext ohne SQL-, Plan-, Login-, Host- oder Programmnamen.');

    INSERT [#WorkerPressureAnalysis_Warnings]([SourceName],[StatusCode],[ErrorNumber],[Message])
    SELECT [SourceName],[StatusCode],[ErrorNumber],COALESCE([ErrorMessage],N'Quelle nicht verfügbar.')
    FROM [#WorkerPressureAnalysis_SourceStatus]
    WHERE [IsPartial]=1;

    IF @StatusCode='AVAILABLE'
    BEGIN
        IF @SchedulerStatus<>'AVAILABLE'
            SELECT @StatusCode=@SchedulerStatus,@IsPartial=1,@ErrorNumber=@SchedulerError,@ErrorMessage=@SchedulerMessage;
        ELSE IF EXISTS(SELECT 1 FROM [#WorkerPressureAnalysis_SourceStatus] WHERE [IsPartial]=1)
            SELECT @StatusCode='AVAILABLE_LIMITED',@IsPartial=1;
    END;

    IF @ErrorMessage IS NULL
        SELECT TOP(1) @ErrorNumber=[ErrorNumber],@ErrorMessage=[Message]
        FROM [#WorkerPressureAnalysis_Warnings] ORDER BY [WarningOrdinal];

    DECLARE @RequestRows bigint=(SELECT COUNT_BIG(*) FROM [#WorkerPressureAnalysis_Requests]);
    INSERT [#WorkerPressureAnalysis_ModuleStatus]
    VALUES(N'USP_WorkerPressureAnalysis',@CapturedAtUtc,@StatusCode,@IsPartial,@SampleSeconds,
           (SELECT COUNT_BIG(*) FROM [#WorkerPressureAnalysis_Schedulers]),
           CASE WHEN @RequestRows>@Limit THEN @Limit ELSE @RequestRows END,
           CONVERT(bit,CASE WHEN @Limit<9223372036854775807 AND @RequestRows>@Limit THEN 1 ELSE 0 END),
           @ErrorNumber,@ErrorMessage);

    IF @JsonErzeugen=1
    BEGIN
        DECLARE @MetaJson nvarchar(max)=(SELECT N'WorkerPressureAnalysis' [resultName],1 [schemaVersion],@CapturedAtUtc [generatedAtUtc],@StatusCode [statusCode],@IsPartial [isPartial],@ErrorNumber [errorNumber],@ErrorMessage [errorMessage] FOR JSON PATH,WITHOUT_ARRAY_WRAPPER,INCLUDE_NULL_VALUES);
        DECLARE @SummaryJson nvarchar(max)=(SELECT * FROM [#WorkerPressureAnalysis_Summary] FOR JSON PATH,INCLUDE_NULL_VALUES);
        DECLARE @SchedulersJson nvarchar(max)=(SELECT * FROM [#WorkerPressureAnalysis_Schedulers] ORDER BY [SchedulerId] FOR JSON PATH,INCLUDE_NULL_VALUES);
        DECLARE @WaitsJson nvarchar(max)=(SELECT * FROM [#WorkerPressureAnalysis_Waits] ORDER BY [WaitingTaskCount] DESC,[WaitType] FOR JSON PATH,INCLUDE_NULL_VALUES);
        DECLARE @RequestsJson nvarchar(max)=(SELECT TOP(@Limit) * FROM [#WorkerPressureAnalysis_Requests] ORDER BY CASE [ContextReason] WHEN 'THREADPOOL' THEN 0 WHEN 'BLOCKED_REQUEST' THEN 1 ELSE 2 END,[ElapsedMs] DESC,[SessionId],[RequestId] FOR JSON PATH,INCLUDE_NULL_VALUES);
        DECLARE @SourceJson nvarchar(max)=(SELECT * FROM [#WorkerPressureAnalysis_SourceStatus] ORDER BY [SourceOrdinal] FOR JSON PATH,INCLUDE_NULL_VALUES);
        DECLARE @WarningsJson nvarchar(max)=(SELECT * FROM [#WorkerPressureAnalysis_Warnings] ORDER BY [WarningOrdinal] FOR JSON PATH,INCLUDE_NULL_VALUES);
        SET @Json=CONCAT(N'{"meta":',COALESCE(@MetaJson,N'{}'),N',"summary":',COALESCE(@SummaryJson,N'[]'),N',"schedulers":',COALESCE(@SchedulersJson,N'[]'),N',"waits":',COALESCE(@WaitsJson,N'[]'),N',"requests":',COALESCE(@RequestsJson,N'[]'),N',"sourceStatus":',COALESCE(@SourceJson,N'[]'),N',"warnings":',COALESCE(@WarningsJson,N'[]'),N'}');
    END;

    IF @ConsoleResultRequested=1
        EXEC [monitor].[InternalEmitConsoleResult] @SourceTable=N'#WorkerPressureAnalysis_Summary',@ResultLabel=N'Worker- und Scheduler-Druck',@EmptyMessage=N'Keine Worker-Evidenz verfügbar';
    ELSE IF @OutputMode='RAW'
    BEGIN
        SELECT * FROM [#WorkerPressureAnalysis_ModuleStatus];
        SELECT * FROM [#WorkerPressureAnalysis_Summary];
        SELECT * FROM [#WorkerPressureAnalysis_Schedulers] ORDER BY [SchedulerId];
        SELECT * FROM [#WorkerPressureAnalysis_Waits] ORDER BY [WaitingTaskCount] DESC,[WaitType];
        SELECT TOP(@Limit) * FROM [#WorkerPressureAnalysis_Requests] ORDER BY CASE [ContextReason] WHEN 'THREADPOOL' THEN 0 WHEN 'BLOCKED_REQUEST' THEN 1 ELSE 2 END,[ElapsedMs] DESC,[SessionId],[RequestId];
        SELECT * FROM [#WorkerPressureAnalysis_SourceStatus] ORDER BY [SourceOrdinal];
        SELECT * FROM [#WorkerPressureAnalysis_Warnings] ORDER BY [WarningOrdinal];
    END
    ELSE IF @OutputMode='TABLE'
    BEGIN
        DECLARE @ResultName sysname,@TargetTable sysname,@SourceTable sysname;
        DECLARE [ResultCursor] CURSOR LOCAL FAST_FORWARD FOR SELECT [ResultName],[TargetTable] FROM [#WorkerPressureAnalysis_ResultTableMap] ORDER BY [ResultName];
        OPEN [ResultCursor]; FETCH NEXT FROM [ResultCursor] INTO @ResultName,@TargetTable;
        WHILE @@FETCH_STATUS=0
        BEGIN
            SET @SourceTable=CASE @ResultName WHEN N'moduleStatus' THEN N'#WorkerPressureAnalysis_ModuleStatus' WHEN N'summary' THEN N'#WorkerPressureAnalysis_Summary' WHEN N'schedulers' THEN N'#WorkerPressureAnalysis_Schedulers' WHEN N'waits' THEN N'#WorkerPressureAnalysis_Waits' WHEN N'requests' THEN N'#WorkerPressureAnalysis_Requests' WHEN N'sourceStatus' THEN N'#WorkerPressureAnalysis_SourceStatus' WHEN N'warnings' THEN N'#WorkerPressureAnalysis_Warnings' END;
            EXEC [monitor].[InternalWriteResultTable] @SourceTable=@SourceTable,@TargetTable=@TargetTable,@ThrowOnError=1;
            FETCH NEXT FROM [ResultCursor] INTO @ResultName,@TargetTable;
        END;
        CLOSE [ResultCursor]; DEALLOCATE [ResultCursor];
    END;

    IF @PrintMeldungen=1 AND @StatusCode<>'AVAILABLE'
    BEGIN
        DECLARE @PrintMessage nvarchar(2048)=LEFT(CONCAT(N'USP_WorkerPressureAnalysis: ',@StatusCode,N'. ',COALESCE(@ErrorMessage,N'Siehe warnings-Resultset.')),2048);
        RAISERROR(N'%s',10,1,@PrintMessage) WITH NOWAIT;
    END;

    SELECT @StatusCodeOut=@StatusCode,@IsPartialOut=@IsPartial,@ErrorNumberOut=@ErrorNumber,@ErrorMessageOut=@ErrorMessage;
END;
GO
-- END SOURCE: Code/08_ServerHealth/180_USP_WorkerPressureAnalysis.sql

-- BEGIN SOURCE: Code/08_ServerHealth/190_USP_DatabaseConfigurationAnalysis.sql
/*
===============================================================================
Objekt       : monitor.USP_DatabaseConfigurationAnalysis
Version      : 1.0.0
Stand        : 2026-07-21
Zweck        : Inventarisiert sichtbare Datenbankoptionen, Database Scoped
               Configurations und Query-Store-Einstellungen und trennt lokale
               Variation von Abweichungen gegen ein explizites Sollprofil.
Profil       : JSON-Array aus settingScope, settingName und expectedValue.
               Ohne Profil wird ausschließlich lokale Variation ausgewiesen.
Abgrenzung   : Variation oder Profilabweichung ist ein Review-Befund, keine
               universelle Fehlkonfiguration und keine automatische DDL-Anweisung.
Eigenlast    : Serverkatalog einmal; je sichtbarer Datenbank zwei kleine
               Katalogabfragen mit LOCK_TIMEOUT 0 und isoliertem Partialstatus.
===============================================================================
*/
CREATE OR ALTER PROCEDURE [monitor].[USP_DatabaseConfigurationAnalysis]
      @DatabaseNames                  nvarchar(max)  = NULL
    , @SystemdatenbankenEinbeziehen   bit            = 0
    , @DatabaseNamePattern            nvarchar(4000) = NULL
    , @ProfileJson                    nvarchar(max)  = NULL
    , @MaxZeilen                      int            = 2000
    , @ResultSetArt                   varchar(16)    = 'CONSOLE'
    , @ResultTablesJson               nvarchar(max)  = NULL
    , @JsonErzeugen                   bit            = 0
    , @Json                           nvarchar(max)  = NULL OUTPUT
    , @PrintMeldungen                 bit            = 1
    , @Hilfe                          bit            = 0
    , @StatusCodeOut                  varchar(40)    = NULL OUTPUT
    , @IsPartialOut                   bit            = NULL OUTPUT
    , @ErrorNumberOut                 int            = NULL OUTPUT
    , @ErrorMessageOut                nvarchar(2048) = NULL OUTPUT
AS
BEGIN
    SET NOCOUNT ON;
    SET @Json=NULL;

    DECLARE @CapturedAtUtc datetime2(3)=SYSUTCDATETIME();
    DECLARE @OutputMode varchar(16)=UPPER(LTRIM(RTRIM(COALESCE(@ResultSetArt,''))));
    DECLARE @ConsoleResultRequested bit=CASE WHEN UPPER(LTRIM(RTRIM(COALESCE(@ResultSetArt,''))))='CONSOLE' THEN 1 ELSE 0 END;
    DECLARE @StatusCode varchar(40)='AVAILABLE';
    DECLARE @IsPartial bit=0;
    DECLARE @ErrorNumber int=NULL;
    DECLARE @ErrorMessage nvarchar(2048)=NULL;
    DECLARE @CrossDatabaseRequested bit=0;
    DECLARE @Limit bigint=CASE WHEN @MaxZeilen IS NULL OR @MaxZeilen=0 THEN CONVERT(bigint,9223372036854775807) ELSE CONVERT(bigint,@MaxZeilen) END;

    IF @Hilfe=1
    BEGIN
        PRINT N'monitor.USP_DatabaseConfigurationAnalysis';
        PRINT N'Ohne Filter werden alle sichtbaren, online befindlichen Benutzerdatenbanken lokal verglichen.';
        PRINT N'@ProfileJson ist optional: [{"settingScope":"DATABASE|SCOPED|QUERY_STORE","settingName":"...","expectedValue":"..."}].';
        PRINT N'Ohne Profil bedeutet drift ausschließlich lokale Variation; mit Profil werden zusätzlich PROFILE_MISMATCH-Zeilen erzeugt.';
        PRINT N'RCSI, Parameterisierung, Statistik- und andere Optionen bleiben workloadabhängig; kein Befund ändert Konfiguration.';
        PRINT N'@ResultSetArt=CONSOLE|RAW|TABLE|NONE; TABLE-Namen: moduleStatus, settings, drift, profile, sourceStatus, warnings.';
        RETURN;
    END;

    CREATE TABLE [#DatabaseConfigurationAnalysis_ResultTableMap]
    (
          [ResultName] sysname COLLATE SQL_Latin1_General_CP1_CS_AS NOT NULL PRIMARY KEY
        , [TargetTable] sysname COLLATE SQL_Latin1_General_CP1_CS_AS NOT NULL UNIQUE
    );
    CREATE TABLE [#DatabaseConfigurationAnalysis_DatabaseCandidates]
    (
          [DatabaseId] int NOT NULL PRIMARY KEY
        , [DatabaseName] sysname COLLATE SQL_Latin1_General_CP1_CS_AS NOT NULL
        , [StateDesc] nvarchar(60) NULL
        , [UserAccessDesc] nvarchar(60) NULL
        , [IsReadOnly] bit NULL
        , [CompatibilityLevel] tinyint NULL
        , [CollationName] sysname NULL
        , [RecoveryModelDesc] nvarchar(60) NULL
        , [IsSystemDatabase] bit NULL
        , [RequestedOrdinal] int NULL
    );
    CREATE TABLE [#DatabaseConfigurationAnalysis_CandidateWarnings]
    (
          [RequestedName] sysname COLLATE SQL_Latin1_General_CP1_CS_AS NULL
        , [StatusCode] varchar(40) NOT NULL
        , [ErrorMessage] nvarchar(2048) NULL
    );
    CREATE TABLE [#DatabaseConfigurationAnalysis_Profile]
    (
          [ProfileOrdinal] int NOT NULL PRIMARY KEY
        , [SettingScope] varchar(32) NOT NULL
        , [SettingName] nvarchar(128) NOT NULL
        , [ExpectedValue] nvarchar(4000) NOT NULL
    );
    CREATE TABLE [#DatabaseConfigurationAnalysis_Settings]
    (
          [CapturedAtUtc] datetime2(3) NOT NULL
        , [DatabaseId] int NOT NULL
        , [DatabaseName] sysname NOT NULL
        , [SettingScope] varchar(32) NOT NULL
        , [SettingName] nvarchar(128) NOT NULL
        , [ActualValue] nvarchar(4000) NULL
        , [SecondaryValue] nvarchar(4000) NULL
        , [IsDefault] bit NULL
        , [SourceObject] nvarchar(256) NOT NULL
        , [SourceStatus] varchar(40) NOT NULL
        , [EvidenceLimit] nvarchar(1000) NOT NULL
    );
    CREATE INDEX [IX_DatabaseConfiguration_Settings]
      ON [#DatabaseConfigurationAnalysis_Settings]([SettingScope],[SettingName],[DatabaseId]);
    CREATE TABLE [#DatabaseConfigurationAnalysis_Drift]
    (
          [CapturedAtUtc] datetime2(3) NOT NULL
        , [DriftType] varchar(32) NOT NULL
        , [DatabaseId] int NULL
        , [DatabaseName] sysname NULL
        , [SettingScope] varchar(32) NOT NULL
        , [SettingName] nvarchar(128) NOT NULL
        , [ActualValue] nvarchar(4000) NULL
        , [ReferenceValue] nvarchar(4000) NULL
        , [MatchingDatabaseCount] int NULL
        , [ComparedDatabaseCount] int NOT NULL
        , [FindingCode] varchar(80) NOT NULL
        , [EvidenceLimit] nvarchar(1000) NOT NULL
    );
    CREATE TABLE [#DatabaseConfigurationAnalysis_SourceStatus]
    (
          [SourceOrdinal] int IDENTITY(1,1) NOT NULL PRIMARY KEY
        , [DatabaseId] int NULL
        , [DatabaseName] sysname NULL
        , [SourceName] sysname NOT NULL
        , [SourceObject] nvarchar(256) NOT NULL
        , [CapturedAtUtc] datetime2(3) NOT NULL
        , [StatusCode] varchar(40) NOT NULL
        , [IsPartial] bit NOT NULL
        , [ReturnedRowCount] bigint NOT NULL
        , [ErrorNumber] int NULL
        , [ErrorMessage] nvarchar(2048) NULL
        , [EvidenceLimit] nvarchar(1000) NOT NULL
    );
    CREATE TABLE [#DatabaseConfigurationAnalysis_Warnings]
    (
          [WarningOrdinal] int IDENTITY(1,1) NOT NULL PRIMARY KEY
        , [DatabaseName] sysname NULL
        , [SourceName] sysname NOT NULL
        , [StatusCode] varchar(40) NOT NULL
        , [ErrorNumber] int NULL
        , [Message] nvarchar(2048) NOT NULL
    );
    CREATE TABLE [#DatabaseConfigurationAnalysis_ModuleStatus]
    (
          [ModuleName] sysname NOT NULL
        , [CapturedAtUtc] datetime2(3) NOT NULL
        , [StatusCode] varchar(40) NOT NULL
        , [IsPartial] bit NOT NULL
        , [CrossDatabaseRequested] bit NOT NULL
        , [DatabaseCount] int NOT NULL
        , [SettingRowCount] bigint NOT NULL
        , [DriftRowCount] bigint NOT NULL
        , [ProfileEntryCount] int NOT NULL
        , [HasMoreSettingRows] bit NOT NULL
        , [HasMoreDriftRows] bit NOT NULL
        , [ErrorNumber] int NULL
        , [ErrorMessage] nvarchar(2048) NULL
    );

    IF @MaxZeilen<0 OR @SystemdatenbankenEinbeziehen IS NULL OR @JsonErzeugen IS NULL OR @PrintMeldungen IS NULL
       OR @OutputMode NOT IN('CONSOLE','RAW','TABLE','NONE')
       OR (@DatabaseNames IS NOT NULL AND @DatabaseNamePattern IS NOT NULL)
       OR (@OutputMode<>'TABLE' AND NULLIF(LTRIM(RTRIM(COALESCE(@ResultTablesJson,N''))),N'') IS NOT NULL)
       OR (@ProfileJson IS NOT NULL AND
           (ISJSON(@ProfileJson)<>1 OR LEFT(LTRIM(@ProfileJson),1)<>N'['))
    BEGIN
        SELECT @StatusCode='INVALID_PARAMETER',@IsPartial=1,
               @ErrorMessage=N'Ungültiger Filter-, Profil-, Zeilen- oder Ausgabeparameter.';
    END;

    IF @StatusCode='AVAILABLE' AND @ProfileJson IS NOT NULL
    BEGIN
        BEGIN TRY
            INSERT [#DatabaseConfigurationAnalysis_Profile]([ProfileOrdinal],[SettingScope],[SettingName],[ExpectedValue])
            SELECT TRY_CONVERT(int,[j].[key])+1,UPPER(LTRIM(RTRIM([p].[SettingScope]))),
                   LTRIM(RTRIM([p].[SettingName])),[p].[ExpectedValue]
            FROM OPENJSON(@ProfileJson) AS [j]
            CROSS APPLY OPENJSON([j].[value])
            WITH
            (
                  [SettingScope] varchar(32) '$.settingScope'
                , [SettingName] nvarchar(128) '$.settingName'
                , [ExpectedValue] nvarchar(4000) '$.expectedValue'
            ) AS [p];
        END TRY
        BEGIN CATCH
            SELECT @StatusCode='INVALID_PARAMETER',@IsPartial=1,
                   @ErrorNumber=ERROR_NUMBER(),
                   @ErrorMessage=N'@ProfileJson enthält keinen gültigen Arrayeintrag.';
        END CATCH;

        IF @StatusCode='AVAILABLE' AND
           (NOT EXISTS(SELECT 1 FROM [#DatabaseConfigurationAnalysis_Profile])
           OR EXISTS
              (
                  SELECT 1 FROM [#DatabaseConfigurationAnalysis_Profile]
                  WHERE [SettingScope] NOT IN('DATABASE','SCOPED','QUERY_STORE')
                     OR NULLIF([SettingName],N'') IS NULL OR [ExpectedValue] IS NULL
              )
           OR EXISTS
              (
                  SELECT [SettingScope],[SettingName]
                  FROM [#DatabaseConfigurationAnalysis_Profile]
                  GROUP BY [SettingScope],[SettingName]
                  HAVING COUNT_BIG(*)>1
              ))
            SELECT @StatusCode='INVALID_PARAMETER',@IsPartial=1,
                   @ErrorMessage=N'@ProfileJson muss ein nicht leeres Array eindeutiger DATABASE-, SCOPED- oder QUERY_STORE-Einträge sein.';
    END;

    IF @StatusCode='AVAILABLE' AND @OutputMode='TABLE'
        EXEC [monitor].[InternalPrepareResultTables]
              @ResultTablesJson=@ResultTablesJson
            , @AllowedResultNames=N'moduleStatus|settings|drift|profile|sourceStatus|warnings'
            , @MappingTable=N'#DatabaseConfigurationAnalysis_ResultTableMap'
            , @StatusCode=@StatusCode OUTPUT
            , @ErrorMessage=@ErrorMessage OUTPUT
            , @ThrowOnError=1;

    IF @StatusCode='AVAILABLE'
        EXEC [monitor].[USP_PrepareDatabaseCandidates]
              @DatabaseNames=@DatabaseNames
            , @SystemdatenbankenEinbeziehen=@SystemdatenbankenEinbeziehen
            , @DatabaseNamePattern=@DatabaseNamePattern
            , @AnalysisClass='STANDARD_CURRENT'
            , @StatusCode=@StatusCode OUTPUT
            , @ErrorMessage=@ErrorMessage OUTPUT
            , @CrossDatabaseRequested=@CrossDatabaseRequested OUTPUT
            , @CandidateTable=N'#DatabaseConfigurationAnalysis_DatabaseCandidates'
            , @WarningTable=N'#DatabaseConfigurationAnalysis_CandidateWarnings';

    SET LOCK_TIMEOUT 0;

    IF @StatusCode='AVAILABLE'
    BEGIN TRY
        INSERT [#DatabaseConfigurationAnalysis_Settings]
        SELECT @CapturedAtUtc,[d].[database_id],[d].[name],'DATABASE',[v].[SettingName],[v].[ActualValue],NULL,NULL,
               N'master.sys.databases','AVAILABLE',
               N'Sichtbarer aktueller Serverkatalogzustand; Wertunterschiede sind ohne Workload- und Betriebsprofil keine Fehlkonfiguration.'
        FROM [master].[sys].[databases] AS [d] WITH (NOLOCK)
        INNER JOIN [#DatabaseConfigurationAnalysis_DatabaseCandidates] AS [c] ON [c].[DatabaseId]=[d].[database_id]
        CROSS APPLY
        (
            VALUES
              (CONVERT(nvarchar(128),N'COMPATIBILITY_LEVEL'),CONVERT(nvarchar(4000),[d].[compatibility_level]))
            , (N'COLLATION',CONVERT(nvarchar(4000),[d].[collation_name]))
            , (N'RECOVERY_MODEL',CONVERT(nvarchar(4000),[d].[recovery_model_desc]))
            , (N'PAGE_VERIFY',CONVERT(nvarchar(4000),[d].[page_verify_option_desc]))
            , (N'AUTO_CLOSE',CASE [d].[is_auto_close_on] WHEN 1 THEN N'ON' ELSE N'OFF' END)
            , (N'AUTO_SHRINK',CASE [d].[is_auto_shrink_on] WHEN 1 THEN N'ON' ELSE N'OFF' END)
            , (N'AUTO_CREATE_STATS',CASE [d].[is_auto_create_stats_on] WHEN 1 THEN N'ON' ELSE N'OFF' END)
            , (N'AUTO_UPDATE_STATS',CASE [d].[is_auto_update_stats_on] WHEN 1 THEN N'ON' ELSE N'OFF' END)
            , (N'AUTO_UPDATE_STATS_ASYNC',CASE [d].[is_auto_update_stats_async_on] WHEN 1 THEN N'ON' ELSE N'OFF' END)
            , (N'READ_COMMITTED_SNAPSHOT',CASE [d].[is_read_committed_snapshot_on] WHEN 1 THEN N'ON' ELSE N'OFF' END)
            , (N'SNAPSHOT_ISOLATION',CONVERT(nvarchar(4000),[d].[snapshot_isolation_state_desc]))
            , (N'PARAMETERIZATION',CASE [d].[is_parameterization_forced] WHEN 1 THEN N'FORCED' ELSE N'SIMPLE' END)
            , (N'QUERY_STORE',CASE [d].[is_query_store_on] WHEN 1 THEN N'ON' ELSE N'OFF' END)
            , (N'ACCELERATED_DATABASE_RECOVERY',CASE [d].[is_accelerated_database_recovery_on] WHEN 1 THEN N'ON' ELSE N'OFF' END)
        ) AS [v]([SettingName],[ActualValue]);

        INSERT [#DatabaseConfigurationAnalysis_SourceStatus]
        SELECT [DatabaseId],[DatabaseName],N'databaseOptions',N'master.sys.databases',@CapturedAtUtc,'AVAILABLE',0,
               (SELECT COUNT_BIG(*) FROM [#DatabaseConfigurationAnalysis_Settings] AS [s] WHERE [s].[DatabaseId]=[c].[DatabaseId] AND [s].[SettingScope]='DATABASE'),
               NULL,NULL,N'Ein Katalogsnapshot; nicht sichtbare Datenbanken fehlen und einzelne Optionen bleiben workloadabhängig.'
        FROM [#DatabaseConfigurationAnalysis_DatabaseCandidates] AS [c];
    END TRY
    BEGIN CATCH
        INSERT [#DatabaseConfigurationAnalysis_SourceStatus]
        VALUES(NULL,NULL,N'databaseOptions',N'master.sys.databases',@CapturedAtUtc,
               CASE WHEN ERROR_NUMBER() IN(229,262,297,300,371,916) THEN 'DENIED_PERMISSION' WHEN ERROR_NUMBER()=1222 THEN 'TIMEOUT' ELSE 'ERROR_HANDLED' END,
               1,0,ERROR_NUMBER(),ERROR_MESSAGE(),N'Datenbanklokale Quellen können unabhängig davon teilweise verfügbar bleiben.');
    END CATCH;

    IF @StatusCode='AVAILABLE' AND EXISTS
    (
        SELECT 1
        FROM [master].[sys].[all_columns] AS [ac] WITH (NOLOCK)
        INNER JOIN [master].[sys].[all_objects] AS [ao] WITH (NOLOCK) ON [ao].[object_id]=[ac].[object_id]
        INNER JOIN [master].[sys].[schemas] AS [s] WITH (NOLOCK) ON [s].[schema_id]=[ao].[schema_id]
        WHERE [s].[name]=N'sys' AND [ao].[name]=N'databases' AND [ac].[name]=N'is_optimized_locking_on'
    )
    BEGIN TRY
        EXEC [sys].[sp_executesql]
            N'INSERT [#DatabaseConfigurationAnalysis_Settings]
              SELECT @CapturedAtUtc,[d].[database_id],[d].[name],''DATABASE'',N''OPTIMIZED_LOCKING'',
                     CASE [d].[is_optimized_locking_on] WHEN 1 THEN N''ON'' ELSE N''OFF'' END,NULL,NULL,
                     N''master.sys.databases'',''AVAILABLE'',
                     N''Versionsabhängiger sichtbarer Katalogzustand; Aktivierung ist ohne Workloadkontext keine automatische Empfehlung.''
              FROM [master].[sys].[databases] AS [d] WITH (NOLOCK)
              INNER JOIN [#DatabaseConfigurationAnalysis_DatabaseCandidates] AS [c] ON [c].[DatabaseId]=[d].[database_id];',
            N'@CapturedAtUtc datetime2(3)',@CapturedAtUtc=@CapturedAtUtc;
    END TRY
    BEGIN CATCH
        INSERT [#DatabaseConfigurationAnalysis_Warnings]([DatabaseName],[SourceName],[StatusCode],[ErrorNumber],[Message])
        VALUES(NULL,N'databaseOptions',CASE WHEN ERROR_NUMBER()=1222 THEN 'TIMEOUT' ELSE 'ERROR_HANDLED' END,ERROR_NUMBER(),ERROR_MESSAGE());
    END CATCH;

    IF @StatusCode='AVAILABLE'
    BEGIN
        DECLARE @DatabaseId int,@DatabaseName sysname,@Sql nvarchar(max);
        DECLARE [DatabaseCursor] CURSOR LOCAL FAST_FORWARD FOR
            SELECT [DatabaseId],[DatabaseName]
            FROM [#DatabaseConfigurationAnalysis_DatabaseCandidates]
            ORDER BY COALESCE([RequestedOrdinal],[DatabaseId]),[DatabaseId];
        OPEN [DatabaseCursor]; FETCH NEXT FROM [DatabaseCursor] INTO @DatabaseId,@DatabaseName;
        WHILE @@FETCH_STATUS=0
        BEGIN
            SET @Sql=N'
            BEGIN TRY
                INSERT [#DatabaseConfigurationAnalysis_Settings]
                SELECT @CapturedAtUtc,@DatabaseId,@DatabaseName,''SCOPED'',CONVERT(nvarchar(128),[name]),
                       CONVERT(nvarchar(4000),[value]),CONVERT(nvarchar(4000),[value_for_secondary]),[is_value_default],
                       N''sys.database_scoped_configurations'',''AVAILABLE'',
                       N''Datenbanklokaler Katalogzustand; Wert, Secondary-Wert und Defaultstatus werden getrennt erhalten.''
                FROM '+QUOTENAME(@DatabaseName)+N'.[sys].[database_scoped_configurations] WITH (NOLOCK);
                DECLARE @ScopedRows bigint=@@ROWCOUNT;
                INSERT [#DatabaseConfigurationAnalysis_SourceStatus]
                VALUES(@DatabaseId,@DatabaseName,N''scopedConfigurations'',N''sys.database_scoped_configurations'',@CapturedAtUtc,''AVAILABLE'',0,@ScopedRows,NULL,NULL,
                       N''Eine Zeile je verfügbarer Scoped Configuration; Einstellungen können versionsabhängig hinzukommen.'');
            END TRY
            BEGIN CATCH
                INSERT [#DatabaseConfigurationAnalysis_SourceStatus]
                VALUES(@DatabaseId,@DatabaseName,N''scopedConfigurations'',N''sys.database_scoped_configurations'',@CapturedAtUtc,
                       CASE WHEN ERROR_NUMBER() IN(229,262,297,300,371,916) THEN ''DENIED_PERMISSION'' WHEN ERROR_NUMBER()=1222 THEN ''TIMEOUT'' ELSE ''ERROR_HANDLED'' END,
                       1,0,ERROR_NUMBER(),ERROR_MESSAGE(),N''Andere Datenbanken und Quellen werden weiter verarbeitet.'');
            END CATCH;
            BEGIN TRY
                INSERT [#DatabaseConfigurationAnalysis_Settings]
                SELECT @CapturedAtUtc,@DatabaseId,@DatabaseName,''QUERY_STORE'',[v].[SettingName],[v].[ActualValue],NULL,NULL,
                       N''sys.database_query_store_options'',''AVAILABLE'',
                       N''Aktueller Query-Store-Konfigurations- und Zustandswert; gewünschter und tatsächlicher Zustand sind getrennt zu bewerten.''
                FROM '+QUOTENAME(@DatabaseName)+N'.[sys].[database_query_store_options] AS [q] WITH (NOLOCK)
                CROSS APPLY
                (VALUES
                    (CONVERT(nvarchar(128),N''DESIRED_STATE''),CONVERT(nvarchar(4000),[q].[desired_state_desc])),
                    (N''ACTUAL_STATE'',CONVERT(nvarchar(4000),[q].[actual_state_desc])),
                    (N''READONLY_REASON'',CONVERT(nvarchar(4000),[q].[readonly_reason])),
                    (N''CURRENT_STORAGE_SIZE_MB'',CONVERT(nvarchar(4000),[q].[current_storage_size_mb])),
                    (N''MAX_STORAGE_SIZE_MB'',CONVERT(nvarchar(4000),[q].[max_storage_size_mb])),
                    (N''STALE_QUERY_THRESHOLD_DAYS'',CONVERT(nvarchar(4000),[q].[stale_query_threshold_days])),
                    (N''FLUSH_INTERVAL_SECONDS'',CONVERT(nvarchar(4000),[q].[flush_interval_seconds])),
                    (N''INTERVAL_LENGTH_MINUTES'',CONVERT(nvarchar(4000),[q].[interval_length_minutes])),
                    (N''QUERY_CAPTURE_MODE'',CONVERT(nvarchar(4000),[q].[query_capture_mode_desc])),
                    (N''SIZE_BASED_CLEANUP_MODE'',CONVERT(nvarchar(4000),[q].[size_based_cleanup_mode_desc])),
                    (N''WAIT_STATS_CAPTURE_MODE'',CONVERT(nvarchar(4000),[q].[wait_stats_capture_mode_desc]))
                ) AS [v]([SettingName],[ActualValue]);
                DECLARE @QueryStoreRows bigint=@@ROWCOUNT;
                INSERT [#DatabaseConfigurationAnalysis_SourceStatus]
                VALUES(@DatabaseId,@DatabaseName,N''queryStoreOptions'',N''sys.database_query_store_options'',@CapturedAtUtc,''AVAILABLE'',0,@QueryStoreRows,NULL,NULL,
                       N''Konfiguration und aktueller Zustand; Query-Store-Inhalt und Workloadwirkung werden nicht gelesen.'');
            END TRY
            BEGIN CATCH
                INSERT [#DatabaseConfigurationAnalysis_SourceStatus]
                VALUES(@DatabaseId,@DatabaseName,N''queryStoreOptions'',N''sys.database_query_store_options'',@CapturedAtUtc,
                       CASE WHEN ERROR_NUMBER() IN(229,262,297,300,371,916) THEN ''DENIED_PERMISSION'' WHEN ERROR_NUMBER()=1222 THEN ''TIMEOUT'' ELSE ''ERROR_HANDLED'' END,
                       1,0,ERROR_NUMBER(),ERROR_MESSAGE(),N''Andere Datenbanken und Quellen werden weiter verarbeitet.'');
            END CATCH;';
            BEGIN TRY
                EXEC [sys].[sp_executesql] @Sql,
                     N'@DatabaseId int,@DatabaseName sysname,@CapturedAtUtc datetime2(3)',
                     @DatabaseId=@DatabaseId,@DatabaseName=@DatabaseName,@CapturedAtUtc=@CapturedAtUtc;
            END TRY
            BEGIN CATCH
                INSERT [#DatabaseConfigurationAnalysis_SourceStatus]
                VALUES(@DatabaseId,@DatabaseName,N'databaseLocalCatalogs',N'sys.database_scoped_configurations|sys.database_query_store_options',@CapturedAtUtc,
                       CASE WHEN ERROR_NUMBER() IN(229,262,297,300,371,916) THEN 'DENIED_PERMISSION' WHEN ERROR_NUMBER()=1222 THEN 'TIMEOUT' ELSE 'ERROR_HANDLED' END,
                       1,0,ERROR_NUMBER(),ERROR_MESSAGE(),N'Dynamische Kompilierungs- oder Zustandsänderung; andere Datenbanken werden weiter verarbeitet.');
            END CATCH;
            FETCH NEXT FROM [DatabaseCursor] INTO @DatabaseId,@DatabaseName;
        END;
        CLOSE [DatabaseCursor]; DEALLOCATE [DatabaseCursor];
    END;

    IF @StatusCode='AVAILABLE'
    BEGIN
        ;WITH [ValueCounts] AS
        (
            SELECT [SettingScope],[SettingName],[ActualValue],COUNT(*) AS [ValueDatabaseCount]
            FROM [#DatabaseConfigurationAnalysis_Settings]
            GROUP BY [SettingScope],[SettingName],[ActualValue]
        ),
        [RankedValues] AS
        (
            SELECT [SettingScope],[SettingName],[ActualValue],[ValueDatabaseCount],
                   SUM([ValueDatabaseCount]) OVER(PARTITION BY [SettingScope],[SettingName]) AS [ComparedDatabaseCount],
                   ROW_NUMBER() OVER(PARTITION BY [SettingScope],[SettingName] ORDER BY [ValueDatabaseCount] DESC,[ActualValue]) AS [ReferenceRank],
                   COUNT(*) OVER(PARTITION BY [SettingScope],[SettingName]) AS [DistinctValueCount]
            FROM [ValueCounts]
        ),
        [ReferenceValues] AS
        (
            SELECT [SettingScope],[SettingName],[ActualValue] AS [ReferenceValue],[ValueDatabaseCount],[ComparedDatabaseCount]
            FROM [RankedValues] WHERE [ReferenceRank]=1 AND [DistinctValueCount]>1
        )
        INSERT [#DatabaseConfigurationAnalysis_Drift]
        SELECT @CapturedAtUtc,'LOCAL_VARIATION',[s].[DatabaseId],[s].[DatabaseName],[s].[SettingScope],[s].[SettingName],
               [s].[ActualValue],[r].[ReferenceValue],[vc].[ValueDatabaseCount],[r].[ComparedDatabaseCount],
               'LOCAL_CONFIGURATION_VARIATION',
               N'Der häufigste sichtbare Wert ist nur eine lokale Vergleichsreferenz und kein Sollwert; Gleichstand wird deterministisch nach Wert aufgelöst.'
        FROM [#DatabaseConfigurationAnalysis_Settings] AS [s]
        INNER JOIN [ReferenceValues] AS [r] ON [r].[SettingScope]=[s].[SettingScope] AND [r].[SettingName]=[s].[SettingName]
        INNER JOIN [ValueCounts] AS [vc] ON [vc].[SettingScope]=[s].[SettingScope] AND [vc].[SettingName]=[s].[SettingName]
                                        AND ISNULL([vc].[ActualValue],N'<NULL>')=ISNULL([s].[ActualValue],N'<NULL>')
        WHERE ISNULL([s].[ActualValue],N'<NULL>') COLLATE SQL_Latin1_General_CP1_CI_AS
             <>ISNULL([r].[ReferenceValue],N'<NULL>') COLLATE SQL_Latin1_General_CP1_CI_AS;

        INSERT [#DatabaseConfigurationAnalysis_Drift]
        SELECT @CapturedAtUtc,'PROFILE_MISMATCH',[s].[DatabaseId],[s].[DatabaseName],[s].[SettingScope],[s].[SettingName],
               [s].[ActualValue],[p].[ExpectedValue],NULL,1,'EXPLICIT_PROFILE_MISMATCH',
               N'Explizit geliefertes Sollprofil; der Befund ist eine Abweichung, aber ohne Change-Freigabe keine Änderungsanweisung.'
        FROM [#DatabaseConfigurationAnalysis_Settings] AS [s]
        INNER JOIN [#DatabaseConfigurationAnalysis_Profile] AS [p]
          ON [p].[SettingScope]=[s].[SettingScope]
         AND [p].[SettingName] COLLATE SQL_Latin1_General_CP1_CI_AS=[s].[SettingName] COLLATE SQL_Latin1_General_CP1_CI_AS
        WHERE ISNULL([s].[ActualValue],N'<NULL>') COLLATE SQL_Latin1_General_CP1_CI_AS
             <>ISNULL([p].[ExpectedValue],N'<NULL>') COLLATE SQL_Latin1_General_CP1_CI_AS;

        INSERT [#DatabaseConfigurationAnalysis_Warnings]([DatabaseName],[SourceName],[StatusCode],[ErrorNumber],[Message])
        SELECT NULL,N'profile','PROFILE_SETTING_NOT_VISIBLE',NULL,
               CONCAT(N'Profileintrag nicht in sichtbarer Evidenz gefunden: ',[p].[SettingScope],N'/',[p].[SettingName],N'.')
        FROM [#DatabaseConfigurationAnalysis_Profile] AS [p]
        WHERE NOT EXISTS
        (
            SELECT 1 FROM [#DatabaseConfigurationAnalysis_Settings] AS [s]
            WHERE [s].[SettingScope]=[p].[SettingScope]
              AND [s].[SettingName] COLLATE SQL_Latin1_General_CP1_CI_AS=[p].[SettingName] COLLATE SQL_Latin1_General_CP1_CI_AS
        );
    END;

    INSERT [#DatabaseConfigurationAnalysis_Warnings]([DatabaseName],[SourceName],[StatusCode],[ErrorNumber],[Message])
    SELECT [DatabaseName],[SourceName],[StatusCode],[ErrorNumber],COALESCE([ErrorMessage],N'Quelle nicht verfügbar.')
    FROM [#DatabaseConfigurationAnalysis_SourceStatus] WHERE [IsPartial]=1;
    INSERT [#DatabaseConfigurationAnalysis_Warnings]([DatabaseName],[SourceName],[StatusCode],[ErrorNumber],[Message])
    SELECT [RequestedName],N'databaseCandidates',[StatusCode],NULL,COALESCE([ErrorMessage],N'Datenbank nicht verarbeitet.')
    FROM [#DatabaseConfigurationAnalysis_CandidateWarnings];

    IF @StatusCode='AVAILABLE' AND EXISTS(SELECT 1 FROM [#DatabaseConfigurationAnalysis_Warnings] WHERE [StatusCode] NOT IN('PROFILE_SETTING_NOT_VISIBLE'))
        SELECT @StatusCode='AVAILABLE_LIMITED',@IsPartial=1;

    IF @StatusCode NOT IN('AVAILABLE','AVAILABLE_LIMITED')
        SET @IsPartial=1;

    SELECT TOP(1) @ErrorNumber=[ErrorNumber],@ErrorMessage=[Message]
    FROM [#DatabaseConfigurationAnalysis_Warnings]
    WHERE [StatusCode] NOT IN('PROFILE_SETTING_NOT_VISIBLE')
    ORDER BY [WarningOrdinal];

    DECLARE @SettingRows bigint=(SELECT COUNT_BIG(*) FROM [#DatabaseConfigurationAnalysis_Settings]);
    DECLARE @DriftRows bigint=(SELECT COUNT_BIG(*) FROM [#DatabaseConfigurationAnalysis_Drift]);
    INSERT [#DatabaseConfigurationAnalysis_ModuleStatus]
    VALUES(N'USP_DatabaseConfigurationAnalysis',@CapturedAtUtc,@StatusCode,@IsPartial,@CrossDatabaseRequested,
           (SELECT COUNT(*) FROM [#DatabaseConfigurationAnalysis_DatabaseCandidates]),
           CASE WHEN @SettingRows>@Limit THEN @Limit ELSE @SettingRows END,
           CASE WHEN @DriftRows>@Limit THEN @Limit ELSE @DriftRows END,
           (SELECT COUNT(*) FROM [#DatabaseConfigurationAnalysis_Profile]),
           CONVERT(bit,CASE WHEN @Limit<9223372036854775807 AND @SettingRows>@Limit THEN 1 ELSE 0 END),
           CONVERT(bit,CASE WHEN @Limit<9223372036854775807 AND @DriftRows>@Limit THEN 1 ELSE 0 END),
           @ErrorNumber,@ErrorMessage);

    IF @JsonErzeugen=1
    BEGIN
        DECLARE @MetaJson nvarchar(max)=(SELECT N'DatabaseConfigurationAnalysis' [resultName],1 [schemaVersion],@CapturedAtUtc [generatedAtUtc],@StatusCode [statusCode],@IsPartial [isPartial],CASE WHEN @ProfileJson IS NULL THEN 'LOCAL_COMPARISON' ELSE 'LOCAL_AND_EXPLICIT_PROFILE' END [comparisonMode],@ErrorNumber [errorNumber],@ErrorMessage [errorMessage] FOR JSON PATH,WITHOUT_ARRAY_WRAPPER,INCLUDE_NULL_VALUES);
        DECLARE @SettingsJson nvarchar(max)=(SELECT TOP(@Limit) * FROM [#DatabaseConfigurationAnalysis_Settings] ORDER BY [DatabaseName],[SettingScope],[SettingName] FOR JSON PATH,INCLUDE_NULL_VALUES);
        DECLARE @DriftJson nvarchar(max)=(SELECT TOP(@Limit) * FROM [#DatabaseConfigurationAnalysis_Drift] ORDER BY [DriftType],[SettingScope],[SettingName],[DatabaseName] FOR JSON PATH,INCLUDE_NULL_VALUES);
        DECLARE @ProfileOutputJson nvarchar(max)=(SELECT * FROM [#DatabaseConfigurationAnalysis_Profile] ORDER BY [ProfileOrdinal] FOR JSON PATH,INCLUDE_NULL_VALUES);
        DECLARE @SourceJson nvarchar(max)=(SELECT * FROM [#DatabaseConfigurationAnalysis_SourceStatus] ORDER BY [SourceOrdinal] FOR JSON PATH,INCLUDE_NULL_VALUES);
        DECLARE @WarningsJson nvarchar(max)=(SELECT * FROM [#DatabaseConfigurationAnalysis_Warnings] ORDER BY [WarningOrdinal] FOR JSON PATH,INCLUDE_NULL_VALUES);
        SET @Json=CONCAT(N'{"meta":',COALESCE(@MetaJson,N'{}'),N',"settings":',COALESCE(@SettingsJson,N'[]'),N',"drift":',COALESCE(@DriftJson,N'[]'),N',"profile":',COALESCE(@ProfileOutputJson,N'[]'),N',"sourceStatus":',COALESCE(@SourceJson,N'[]'),N',"warnings":',COALESCE(@WarningsJson,N'[]'),N'}');
    END;

    IF @ConsoleResultRequested=1
        EXEC [monitor].[InternalEmitConsoleResult] @SourceTable=N'#DatabaseConfigurationAnalysis_Drift',@ResultLabel=N'Datenbankkonfiguration und Drift',@EmptyMessage=N'Keine lokale Variation oder Profilabweichung sichtbar';
    ELSE IF @OutputMode='RAW'
    BEGIN
        SELECT * FROM [#DatabaseConfigurationAnalysis_ModuleStatus];
        SELECT TOP(@Limit) * FROM [#DatabaseConfigurationAnalysis_Settings] ORDER BY [DatabaseName],[SettingScope],[SettingName];
        SELECT TOP(@Limit) * FROM [#DatabaseConfigurationAnalysis_Drift] ORDER BY [DriftType],[SettingScope],[SettingName],[DatabaseName];
        SELECT * FROM [#DatabaseConfigurationAnalysis_Profile] ORDER BY [ProfileOrdinal];
        SELECT * FROM [#DatabaseConfigurationAnalysis_SourceStatus] ORDER BY [SourceOrdinal];
        SELECT * FROM [#DatabaseConfigurationAnalysis_Warnings] ORDER BY [WarningOrdinal];
    END
    ELSE IF @OutputMode='TABLE'
    BEGIN
        DECLARE @ResultName sysname,@TargetTable sysname,@SourceTable sysname;
        DECLARE [ResultCursor] CURSOR LOCAL FAST_FORWARD FOR SELECT [ResultName],[TargetTable] FROM [#DatabaseConfigurationAnalysis_ResultTableMap] ORDER BY [ResultName];
        OPEN [ResultCursor]; FETCH NEXT FROM [ResultCursor] INTO @ResultName,@TargetTable;
        WHILE @@FETCH_STATUS=0
        BEGIN
            SET @SourceTable=CASE @ResultName WHEN N'moduleStatus' THEN N'#DatabaseConfigurationAnalysis_ModuleStatus' WHEN N'settings' THEN N'#DatabaseConfigurationAnalysis_Settings' WHEN N'drift' THEN N'#DatabaseConfigurationAnalysis_Drift' WHEN N'profile' THEN N'#DatabaseConfigurationAnalysis_Profile' WHEN N'sourceStatus' THEN N'#DatabaseConfigurationAnalysis_SourceStatus' WHEN N'warnings' THEN N'#DatabaseConfigurationAnalysis_Warnings' END;
            EXEC [monitor].[InternalWriteResultTable] @SourceTable=@SourceTable,@TargetTable=@TargetTable,@ThrowOnError=1;
            FETCH NEXT FROM [ResultCursor] INTO @ResultName,@TargetTable;
        END;
        CLOSE [ResultCursor]; DEALLOCATE [ResultCursor];
    END;

    IF @PrintMeldungen=1 AND @StatusCode<>'AVAILABLE'
    BEGIN
        DECLARE @PrintMessage nvarchar(2048)=LEFT(CONCAT(N'USP_DatabaseConfigurationAnalysis: ',@StatusCode,N'. ',COALESCE(@ErrorMessage,N'Siehe warnings-Resultset.')),2048);
        RAISERROR(N'%s',10,1,@PrintMessage) WITH NOWAIT;
    END;
    SELECT @StatusCodeOut=@StatusCode,@IsPartialOut=@IsPartial,@ErrorNumberOut=@ErrorNumber,@ErrorMessageOut=@ErrorMessage;
END;
GO
-- END SOURCE: Code/08_ServerHealth/190_USP_DatabaseConfigurationAnalysis.sql

-- BEGIN SOURCE: Code/08_ServerHealth/200_USP_DatabasePortabilityAnalysis.sql
/* OPS-006: read-only portability evidence; no automatic DDL. */
CREATE OR ALTER PROCEDURE [monitor].[USP_DatabasePortabilityAnalysis]
      @DatabaseNames   nvarchar(max)  = NULL
    , @MaxZeilen       int            = 2000
    , @ResultSetArt    varchar(16)    = 'CONSOLE'
    , @ResultTablesJson nvarchar(max) = NULL
    , @JsonErzeugen    bit            = 0
    , @Json            nvarchar(max)  = NULL OUTPUT
    , @PrintMeldungen  bit            = 1
    , @Hilfe           bit            = 0
    , @StatusCodeOut   varchar(40)    = NULL OUTPUT
    , @IsPartialOut    bit            = NULL OUTPUT
    , @ErrorNumberOut  int            = NULL OUTPUT
    , @ErrorMessageOut nvarchar(2048) = NULL OUTPUT
AS
BEGIN
    SET NOCOUNT ON;
    SET @Json = NULL;
    DECLARE @Status varchar(40) = 'AVAILABLE', @Partial bit = 0;
    DECLARE @ErrorNumber int = NULL, @ErrorMessage nvarchar(2048) = NULL;
    DECLARE @Mode varchar(16) = UPPER(LTRIM(RTRIM(COALESCE(@ResultSetArt,''))));

    IF @Hilfe = 1
    BEGIN
        PRINT N'monitor.USP_DatabasePortabilityAnalysis';
        PRINT N'Inventarisiert persistierte Edition-Features und uncontained dependencies sichtbarer Datenbanken.';
        PRINT N'Es wird keine DDL erzeugt oder ausgeführt. @ResultSetArt=CONSOLE|RAW|NONE.';
        RETURN;
    END;
    DECLARE @PreviousLockTimeout int=@@LOCK_TIMEOUT,@RestoreLockTimeoutSql nvarchar(100); SET LOCK_TIMEOUT 0;
    DECLARE @TableResultRequested bit=CASE WHEN @Mode='TABLE' THEN 1 ELSE 0 END,@ConsoleResultRequested bit=CASE WHEN @Mode='CONSOLE' THEN 1 ELSE 0 END,@TableTarget sysname=NULL;
    IF @TableResultRequested=0 AND NULLIF(LTRIM(RTRIM(COALESCE(@ResultTablesJson,N''))),N'') IS NOT NULL THROW 51011,N'@ResultTablesJson ist ausschließlich mit @ResultSetArt=TABLE zulässig.',1;
    IF @TableResultRequested=1 BEGIN EXEC [monitor].[InternalPrepareSingleResultTable] @ResultTablesJson=@ResultTablesJson,@ResultName=N'portability',@TargetTable=@TableTarget OUTPUT,@ThrowOnError=1; END;
    IF @TableResultRequested=1 OR @ConsoleResultRequested=1 SET @Mode='NONE';

    CREATE TABLE [#DatabasePortabilityAnalysis_Portability]
    (
          [DatabaseName] sysname COLLATE SQL_Latin1_General_CP1_CS_AS NOT NULL
        , [EvidenceType] varchar(40) COLLATE SQL_Latin1_General_CP1_CS_AS NOT NULL
        , [FeatureName] nvarchar(256) COLLATE SQL_Latin1_General_CP1_CS_AS NULL
        , [FeatureType] nvarchar(256) COLLATE SQL_Latin1_General_CP1_CS_AS NULL
        , [StatementType] nvarchar(256) COLLATE SQL_Latin1_General_CP1_CS_AS NULL
        , [SourceObject] nvarchar(256) COLLATE SQL_Latin1_General_CP1_CS_AS NOT NULL
        , [StatusCode] varchar(40) COLLATE SQL_Latin1_General_CP1_CS_AS NOT NULL
        , [EvidenceLimit] nvarchar(1000) COLLATE SQL_Latin1_General_CP1_CS_AS NOT NULL
    );

    DECLARE @EffectiveDatabaseNames nvarchar(max)=
        CASE WHEN NULLIF(LTRIM(RTRIM(COALESCE(@DatabaseNames,N''))),N'') IS NULL THEN NULL ELSE @DatabaseNames END;
    DECLARE @RequestedDatabaseCount int=0,@UnavailableDatabaseCount int=0;
    CREATE TABLE [#DatabasePortabilityAnalysis_Requested]
    (
          [NameValue] sysname COLLATE SQL_Latin1_General_CP1_CS_AS NULL
        , [IsValid] bit NOT NULL
    );
    IF @EffectiveDatabaseNames IS NOT NULL
        INSERT [#DatabasePortabilityAnalysis_Requested]([NameValue],[IsValid])
        SELECT [NameValue],[IsValid] FROM [monitor].[TVF_ParseSqlNameList](@EffectiveDatabaseNames);
    SELECT @RequestedDatabaseCount=COUNT(*)
    FROM [#DatabasePortabilityAnalysis_Requested]
    WHERE [IsValid]=1;

    IF @MaxZeilen < 0 OR @Mode NOT IN ('CONSOLE','RAW','NONE')
        SELECT @Status='INVALID_PARAMETER', @Partial=1,
               @ErrorMessage=N'Ungültiger Zeilen- oder Ausgabeparameter.';
    ELSE IF @EffectiveDatabaseNames IS NOT NULL
         AND
         (
             @RequestedDatabaseCount=0
             OR EXISTS(SELECT 1 FROM [#DatabasePortabilityAnalysis_Requested] WHERE [IsValid]=0)
             OR EXISTS
                (
                    SELECT [NameValue]
                    FROM [#DatabasePortabilityAnalysis_Requested]
                    WHERE [IsValid]=1
                    GROUP BY [NameValue]
                    HAVING COUNT_BIG(*)>1
                )
         )
        SELECT @Status='INVALID_PARAMETER',@Partial=1,
               @ErrorMessage=N'@DatabaseNames enthält ungültige oder doppelte einteilige Datenbanknamen.';

    IF @Status = 'AVAILABLE'
    BEGIN
        DECLARE @Db sysname, @Sql nvarchar(max);
        DECLARE [dbs] CURSOR LOCAL FAST_FORWARD FOR
            SELECT [name]
            FROM [sys].[databases] AS [d] WITH (NOLOCK)
            WHERE [d].[state] = 0 AND [d].[database_id] > 4
              AND HAS_DBACCESS([d].[name]) = 1
              AND
              (
                  @EffectiveDatabaseNames IS NULL
                  OR EXISTS
                     (
                         SELECT 1
                         FROM [#DatabasePortabilityAnalysis_Requested] AS [r]
                         WHERE [r].[IsValid]=1
                           AND [r].[NameValue]=[d].[name] COLLATE SQL_Latin1_General_CP1_CS_AS
                     )
              )
            ORDER BY [d].[name];
        OPEN [dbs]; FETCH NEXT FROM [dbs] INTO @Db;
        WHILE @@FETCH_STATUS = 0
        BEGIN
            BEGIN TRY
                SET @Sql = N'
INSERT [#DatabasePortabilityAnalysis_Portability]
SELECT @Db, ''PERSISTED_SKU_FEATURE'', [feature_name], NULL, NULL,
       N''sys.dm_db_persisted_sku_features'', ''AVAILABLE'',
       N''Persistiertes Feature ist ein Migrationshinweis; Zielunterstützung separat prüfen.''
FROM ' + QUOTENAME(@Db) + N'.[sys].[dm_db_persisted_sku_features];';
                EXEC [sys].[sp_executesql] @Sql, N'@Db sysname', @Db=@Db;
            END TRY
            BEGIN CATCH
                INSERT [#DatabasePortabilityAnalysis_Portability]
                VALUES (@Db,'SOURCE_STATUS',NULL,NULL,NULL,N'sys.dm_db_persisted_sku_features',
                        CASE WHEN ERROR_NUMBER() IN (229,371) THEN 'DENIED_PERMISSION'
                             WHEN ERROR_NUMBER() IN (207,208) THEN 'UNSUPPORTED_SOURCE'
                             WHEN ERROR_NUMBER()=1222 THEN 'LOCK_TIMEOUT'
                             ELSE 'SOURCE_UNAVAILABLE' END,
                        CONCAT(N'Fehler ',ERROR_NUMBER(),N': ',LEFT(ERROR_MESSAGE(),800)));
                SET @Partial=1;
            END CATCH;
            BEGIN TRY
                SET @Sql = N'
INSERT [#DatabasePortabilityAnalysis_Portability]
SELECT @Db, ''UNCONTAINED_ENTITY'', [feature_name], [feature_type_name], [statement_type],
       N''sys.dm_db_uncontained_entities'', ''AVAILABLE'',
       N''Metadatenfund ohne automatische Umschreibung oder DDL-Anweisung.''
FROM ' + QUOTENAME(@Db) + N'.[sys].[dm_db_uncontained_entities];';
                EXEC [sys].[sp_executesql] @Sql, N'@Db sysname', @Db=@Db;
            END TRY
            BEGIN CATCH
                INSERT [#DatabasePortabilityAnalysis_Portability]
                VALUES (@Db,'SOURCE_STATUS',NULL,NULL,NULL,N'sys.dm_db_uncontained_entities',
                        CASE WHEN ERROR_NUMBER() IN (229,371) THEN 'DENIED_PERMISSION'
                             WHEN ERROR_NUMBER() IN (207,208) THEN 'UNSUPPORTED_SOURCE'
                             WHEN ERROR_NUMBER()=1222 THEN 'LOCK_TIMEOUT'
                             ELSE 'SOURCE_UNAVAILABLE' END,
                        CONCAT(N'Fehler ',ERROR_NUMBER(),N': ',LEFT(ERROR_MESSAGE(),800)));
                SET @Partial=1;
            END CATCH;
            FETCH NEXT FROM [dbs] INTO @Db;
        END;
        CLOSE [dbs]; DEALLOCATE [dbs];
        IF @EffectiveDatabaseNames IS NOT NULL
            SELECT @UnavailableDatabaseCount=COUNT(*)
            FROM [#DatabasePortabilityAnalysis_Requested] AS [r]
            WHERE [r].[IsValid]=1
              AND NOT EXISTS
                  (
                      SELECT 1
                      FROM [sys].[databases] AS [d] WITH (NOLOCK)
                      WHERE [d].[state]=0
                        AND [d].[database_id]>4
                        AND HAS_DBACCESS([d].[name])=1
                        AND [d].[name] COLLATE SQL_Latin1_General_CP1_CS_AS=[r].[NameValue]
                  );
        IF @UnavailableDatabaseCount=@RequestedDatabaseCount AND @RequestedDatabaseCount>0
            SELECT @Status='NOT_FOUND', @Partial=1, @ErrorMessage=N'Keine angeforderte Benutzerdatenbank ist online und sichtbar.';
        ELSE IF @UnavailableDatabaseCount>0
            SELECT @Status='AVAILABLE_LIMITED',@Partial=1,@ErrorMessage=N'Mindestens eine angeforderte Benutzerdatenbank ist nicht online oder nicht sichtbar.';
        ELSE IF NOT EXISTS(SELECT 1 FROM [#DatabasePortabilityAnalysis_Portability])
            SET @Status='AVAILABLE_EMPTY';
        ELSE IF @Partial=1 SET @Status='AVAILABLE_LIMITED';
    END;

    IF @JsonErzeugen=1
        SELECT @Json=COALESCE((SELECT TOP (CASE WHEN @MaxZeilen=0 THEN 2147483647 ELSE @MaxZeilen END) *
                      FROM [#DatabasePortabilityAnalysis_Portability] ORDER BY [DatabaseName],[EvidenceType],[FeatureName] FOR JSON PATH),N'[]');
    IF @Mode IN('CONSOLE','RAW')
    BEGIN
        SELECT @Status AS [StatusCode],@Partial AS [IsPartial],COUNT_BIG(*) AS [EvidenceRows],
               @ErrorMessage AS [ErrorMessage] FROM [#DatabasePortabilityAnalysis_Portability];
        SELECT TOP (CASE WHEN @MaxZeilen=0 THEN 2147483647 ELSE @MaxZeilen END) *
        FROM [#DatabasePortabilityAnalysis_Portability] ORDER BY [DatabaseName],[EvidenceType],[FeatureName];
    END;
    IF @PrintMeldungen=1 AND @Mode='NONE' PRINT CONCAT(N'Status: ',@Status);
    IF @ConsoleResultRequested=1 EXEC [monitor].[InternalEmitConsoleResult] @SourceTable=N'#DatabasePortabilityAnalysis_Portability',@ResultLabel=N'portability',@EmptyMessage=N'Keine Portabilitätsevidenz im sichtbaren Scope';
    IF @TableResultRequested=1 EXEC [monitor].[InternalWriteResultTable] @SourceTable=N'#DatabasePortabilityAnalysis_Portability',@TargetTable=@TableTarget,@ThrowOnError=1;
    SET @RestoreLockTimeoutSql=N'SET LOCK_TIMEOUT '+CONVERT(nvarchar(20),@PreviousLockTimeout)+N';'; EXEC [sys].[sp_executesql] @RestoreLockTimeoutSql; SELECT @StatusCodeOut=@Status,@IsPartialOut=@Partial,@ErrorNumberOut=@ErrorNumber,@ErrorMessageOut=@ErrorMessage;
END;
GO
-- END SOURCE: Code/08_ServerHealth/200_USP_DatabasePortabilityAnalysis.sql

-- BEGIN SOURCE: Code/08_ServerHealth/210_USP_MsdbHealthAnalysis.sql
/* OPS-008: bounded msdb history and size inventory; never deletes history. */
CREATE OR ALTER PROCEDURE [monitor].[USP_MsdbHealthAnalysis]
      @MaxZeilen       int            = 2000
    , @ResultSetArt    varchar(16)    = 'CONSOLE'
    , @ResultTablesJson nvarchar(max) = NULL
    , @JsonErzeugen    bit            = 0
    , @Json            nvarchar(max)  = NULL OUTPUT
    , @PrintMeldungen  bit            = 1
    , @Hilfe           bit            = 0
    , @StatusCodeOut   varchar(40)    = NULL OUTPUT
    , @IsPartialOut    bit            = NULL OUTPUT
    , @ErrorNumberOut  int            = NULL OUTPUT
    , @ErrorMessageOut nvarchar(2048) = NULL OUTPUT
AS
BEGIN
    SET NOCOUNT ON; SET @Json=NULL;
    DECLARE @Status varchar(40)='AVAILABLE',@Partial bit=0,@Mode varchar(16)=UPPER(LTRIM(RTRIM(COALESCE(@ResultSetArt,''))));
    DECLARE @ErrorNumber int=NULL,@ErrorMessage nvarchar(2048)=NULL;
    IF @Hilfe=1 BEGIN PRINT N'monitor.USP_MsdbHealthAnalysis'; PRINT N'Inventarisiert msdb-Größe und sichtbare Historien; führt keine Bereinigung aus.'; RETURN; END;
    DECLARE @PreviousLockTimeout int = @@LOCK_TIMEOUT, @RestoreLockTimeoutSql nvarchar(100);
    SET LOCK_TIMEOUT 0;
    DECLARE @TableResultRequested bit=CASE WHEN @Mode='TABLE' THEN 1 ELSE 0 END,@ConsoleResultRequested bit=CASE WHEN @Mode='CONSOLE' THEN 1 ELSE 0 END,@TableTarget sysname=NULL;
    IF @TableResultRequested=0 AND NULLIF(LTRIM(RTRIM(COALESCE(@ResultTablesJson,N''))),N'') IS NOT NULL THROW 51011,N'@ResultTablesJson ist ausschließlich mit @ResultSetArt=TABLE zulässig.',1;
    IF @TableResultRequested=1 BEGIN EXEC [monitor].[InternalPrepareSingleResultTable] @ResultTablesJson=@ResultTablesJson,@ResultName=N'msdbHealth',@TargetTable=@TableTarget OUTPUT,@ThrowOnError=1; END;
    IF @TableResultRequested=1 OR @ConsoleResultRequested=1 SET @Mode='NONE';
    CREATE TABLE [#MsdbHealthAnalysis_Health]
    (
          [Area] varchar(40) COLLATE SQL_Latin1_General_CP1_CS_AS NOT NULL,[SourceObject] nvarchar(256) COLLATE SQL_Latin1_General_CP1_CS_AS NOT NULL
        , [RowCount] bigint NULL,[OldestUtc] datetime2(3) NULL,[NewestUtc] datetime2(3) NULL
        , [SizeMb] decimal(19,2) NULL,[StatusCode] varchar(40) COLLATE SQL_Latin1_General_CP1_CS_AS NOT NULL
        , [EvidenceLimit] nvarchar(1000) COLLATE SQL_Latin1_General_CP1_CS_AS NOT NULL
    );
    IF @MaxZeilen<0 OR @Mode NOT IN('CONSOLE','RAW','NONE') SELECT @Status='INVALID_PARAMETER',@Partial=1,@ErrorMessage=N'Ungültiger Parameter.';
    IF @Status='AVAILABLE' AND NOT EXISTS (SELECT 1 FROM [sys].[databases] WITH (NOLOCK) WHERE [database_id]=4)
        SELECT @Status='UNSUPPORTED',@Partial=1,@ErrorMessage=N'msdb ist nicht verfügbar.';
    IF @Status='AVAILABLE'
    BEGIN
        INSERT [#MsdbHealthAnalysis_Health]
        SELECT 'DATABASE_SIZE',N'master.sys.master_files',NULL,NULL,NULL,
               CONVERT(decimal(19,2),SUM(CONVERT(bigint,[size]))*8.0/1024.0),'AVAILABLE',
               N'Aktuelle Dateigröße; kein Wachstums- oder freier Speicherplatznachweis.'
        FROM [sys].[master_files] WITH (NOLOCK) WHERE [database_id]=4;
        DECLARE @Defs TABLE
        (
              [Area] varchar(40) COLLATE SQL_Latin1_General_CP1_CS_AS
            , [ObjectName] sysname COLLATE SQL_Latin1_General_CP1_CS_AS
            , [DateColumn] sysname COLLATE SQL_Latin1_General_CP1_CS_AS NULL
        );
        INSERT @Defs VALUES
          ('BACKUP_HISTORY','backupset','backup_finish_date'),('RESTORE_HISTORY','restorehistory','restore_date'),
          ('AGENT_HISTORY','sysjobhistory',NULL),('DATABASE_MAIL','sysmail_allitems','send_request_date'),
          ('MAINTENANCE_PLAN','sysmaintplan_log','start_time');
        DECLARE @Area varchar(40),@Obj sysname,@Date sysname,@Sql nvarchar(max),@Source nvarchar(256);
        DECLARE [d] CURSOR LOCAL FAST_FORWARD FOR SELECT [Area],[ObjectName],[DateColumn] FROM @Defs;
        OPEN [d]; FETCH NEXT FROM [d] INTO @Area,@Obj,@Date;
        WHILE @@FETCH_STATUS=0
        BEGIN
            IF NOT EXISTS
            (
                SELECT 1
                FROM [msdb].[sys].[objects] AS [o] WITH (NOLOCK)
                INNER JOIN [msdb].[sys].[schemas] AS [s] WITH (NOLOCK) ON [s].[schema_id]=[o].[schema_id]
                WHERE [s].[name] COLLATE SQL_Latin1_General_CP1_CS_AS=N'dbo'
                  AND [o].[name] COLLATE SQL_Latin1_General_CP1_CS_AS=@Obj COLLATE SQL_Latin1_General_CP1_CS_AS
                  AND [o].[type] COLLATE SQL_Latin1_General_CP1_CS_AS=N'U'
            )
                INSERT [#MsdbHealthAnalysis_Health] VALUES(@Area,N'msdb.dbo.'+@Obj,NULL,NULL,NULL,NULL,'UNSUPPORTED',N'Quelle ist auf dieser Instanz nicht vorhanden.');
            ELSE BEGIN TRY
                SET @Source=N'msdb.dbo.'+@Obj;
                SET @Sql=N'INSERT [#MsdbHealthAnalysis_Health] SELECT @Area,@Source,COUNT_BIG(*),' +
                    CASE WHEN @Date IS NULL THEN N'NULL,NULL' ELSE N'MIN('+QUOTENAME(@Date)+N'),MAX('+QUOTENAME(@Date)+N')' END +
                    N',NULL,''AVAILABLE'',N''Retentionbewertung ist kontextabhängig; es wird nichts gelöscht.'' FROM [msdb].[dbo].'+QUOTENAME(@Obj)+N' WITH (NOLOCK);';
                EXEC [sys].[sp_executesql] @Sql,N'@Area varchar(40),@Source nvarchar(256)',@Area,@Source;
            END TRY BEGIN CATCH
                INSERT [#MsdbHealthAnalysis_Health] VALUES(@Area,N'msdb.dbo.'+@Obj,NULL,NULL,NULL,NULL,'SOURCE_UNAVAILABLE',CONCAT(N'Fehler ',ERROR_NUMBER(),N': ',LEFT(ERROR_MESSAGE(),800)));
                SET @Partial=1;
            END CATCH;
            FETCH NEXT FROM [d] INTO @Area,@Obj,@Date;
        END; CLOSE [d]; DEALLOCATE [d];
        IF @Partial=1 SET @Status='AVAILABLE_LIMITED';
    END;
    IF @JsonErzeugen=1 SELECT @Json=COALESCE((SELECT TOP(CASE WHEN @MaxZeilen=0 THEN 2147483647 ELSE @MaxZeilen END)* FROM [#MsdbHealthAnalysis_Health] ORDER BY [Area] FOR JSON PATH),N'[]');
    IF @Mode IN('CONSOLE','RAW') BEGIN SELECT @Status [StatusCode],@Partial [IsPartial],COUNT_BIG(*) [EvidenceRows],@ErrorMessage [ErrorMessage] FROM [#MsdbHealthAnalysis_Health]; SELECT TOP(CASE WHEN @MaxZeilen=0 THEN 2147483647 ELSE @MaxZeilen END)* FROM [#MsdbHealthAnalysis_Health] ORDER BY [Area]; END;
    IF @PrintMeldungen=1 AND @Mode='NONE' PRINT CONCAT(N'Status: ',@Status);
    IF @ConsoleResultRequested=1 EXEC [monitor].[InternalEmitConsoleResult] @SourceTable=N'#MsdbHealthAnalysis_Health',@ResultLabel=N'msdbHealth',@EmptyMessage=N'Keine msdb-Health-Evidenz im sichtbaren Scope';
    IF @TableResultRequested=1 EXEC [monitor].[InternalWriteResultTable] @SourceTable=N'#MsdbHealthAnalysis_Health',@TargetTable=@TableTarget,@ThrowOnError=1;
    SELECT @StatusCodeOut=@Status,@IsPartialOut=@Partial,@ErrorNumberOut=@ErrorNumber,@ErrorMessageOut=@ErrorMessage;
    SET @RestoreLockTimeoutSql=N'SET LOCK_TIMEOUT '+CONVERT(nvarchar(20),@PreviousLockTimeout)+N';';
    EXEC [sys].[sp_executesql] @RestoreLockTimeoutSql;
END;
GO
-- END SOURCE: Code/08_ServerHealth/210_USP_MsdbHealthAnalysis.sql

-- BEGIN SOURCE: Code/08_ServerHealth/220_USP_LinkedServerAnalysis.sql
/* OPS-005: local inventory by default; connectivity is explicit double opt-in. */
CREATE OR ALTER PROCEDURE [monitor].[USP_LinkedServerAnalysis]
      @ConnectivityTestEnabled bit            = 0
    , @HighImpactConfirmed     bit            = 0
    , @MaxZeilen               int            = 2000
    , @ResultSetArt            varchar(16)    = 'CONSOLE'
    , @ResultTablesJson        nvarchar(max)  = NULL
    , @JsonErzeugen            bit            = 0
    , @Json                    nvarchar(max)  = NULL OUTPUT
    , @PrintMeldungen          bit            = 1
    , @Hilfe                   bit            = 0
    , @StatusCodeOut           varchar(40)    = NULL OUTPUT
    , @IsPartialOut            bit            = NULL OUTPUT
    , @ErrorNumberOut          int            = NULL OUTPUT
    , @ErrorMessageOut         nvarchar(2048) = NULL OUTPUT
AS
BEGIN
    SET NOCOUNT ON; SET @Json=NULL;
    DECLARE @Status varchar(40)='AVAILABLE',@Partial bit=0,@Mode varchar(16)=UPPER(LTRIM(RTRIM(COALESCE(@ResultSetArt,''))));
    DECLARE @ErrorNumber int=NULL,@ErrorMessage nvarchar(2048)=NULL,@ServerStatusCode varchar(40)=N'SOURCE_UNAVAILABLE';
    IF @Hilfe=1 BEGIN PRINT N'monitor.USP_LinkedServerAnalysis'; PRINT N'Default ist lokales Inventar. Remote-Test nur mit @ConnectivityTestEnabled=1 und @HighImpactConfirmed=1.'; RETURN; END;
    DECLARE @PreviousLockTimeout int = @@LOCK_TIMEOUT, @RestoreLockTimeoutSql nvarchar(100);
    SET LOCK_TIMEOUT 0;
    DECLARE @TableResultRequested bit=CASE WHEN @Mode='TABLE' THEN 1 ELSE 0 END,@ConsoleResultRequested bit=CASE WHEN @Mode='CONSOLE' THEN 1 ELSE 0 END,@TableTarget sysname=NULL;
    IF @TableResultRequested=0 AND NULLIF(LTRIM(RTRIM(COALESCE(@ResultTablesJson,N''))),N'') IS NOT NULL THROW 51011,N'@ResultTablesJson ist ausschließlich mit @ResultSetArt=TABLE zulässig.',1;
    IF @TableResultRequested=1 BEGIN EXEC [monitor].[InternalPrepareSingleResultTable] @ResultTablesJson=@ResultTablesJson,@ResultName=N'linkedServers',@TargetTable=@TableTarget OUTPUT,@ThrowOnError=1; END;
    IF @TableResultRequested=1 OR @ConsoleResultRequested=1 SET @Mode='NONE';
    CREATE TABLE [#LinkedServerAnalysis_Linked]
    (
      [ServerName] sysname COLLATE SQL_Latin1_General_CP1_CS_AS NOT NULL,[Product] nvarchar(128) COLLATE SQL_Latin1_General_CP1_CS_AS NULL,[Provider] nvarchar(128) COLLATE SQL_Latin1_General_CP1_CS_AS NULL,
      [IsDataAccessEnabled] bit NULL,[IsRpcOutEnabled] bit NULL,[IsCollationCompatible] bit NULL,
      [ConnectivityStatus] varchar(40) COLLATE SQL_Latin1_General_CP1_CS_AS NOT NULL,[StatusCode] varchar(40) COLLATE SQL_Latin1_General_CP1_CS_AS NOT NULL,[EvidenceLimit] nvarchar(1000) COLLATE SQL_Latin1_General_CP1_CS_AS NOT NULL
    );
    IF @MaxZeilen<0 OR @Mode NOT IN('CONSOLE','RAW','NONE') OR @ConnectivityTestEnabled IS NULL OR @HighImpactConfirmed IS NULL
      SELECT @Status='INVALID_PARAMETER',@Partial=1,@ErrorMessage=N'Ungültiger Parameter.';
    IF @Status='AVAILABLE'
    BEGIN
      INSERT [#LinkedServerAnalysis_Linked]
      SELECT [name],[product],[provider],[is_data_access_enabled],[is_rpc_out_enabled],[is_collation_compatible],
             CASE WHEN @ConnectivityTestEnabled=0 THEN 'NOT_EXECUTED' WHEN @HighImpactConfirmed=0 THEN 'AUTHORIZATION_REQUIRED' ELSE 'PENDING' END,
             'AVAILABLE',N'Endpunkt und Datenquelle werden nicht ausgegeben; Erreichbarkeit ist ohne opt-in unbekannt.'
      FROM [sys].[servers] WITH (NOLOCK) WHERE [is_linked]=1;
      IF @ConnectivityTestEnabled=1 AND @HighImpactConfirmed=0 SELECT @Status='AUTHORIZATION_REQUIRED',@Partial=1,@ErrorMessage=N'Remotezugriff benötigt @HighImpactConfirmed=1.';
      IF @ConnectivityTestEnabled=1 AND @HighImpactConfirmed=1
      BEGIN
        DECLARE @Server sysname;
        DECLARE [s] CURSOR LOCAL FAST_FORWARD FOR SELECT [ServerName] FROM [#LinkedServerAnalysis_Linked];
        OPEN [s]; FETCH NEXT FROM [s] INTO @Server;
        WHILE @@FETCH_STATUS=0 BEGIN
          BEGIN TRY
            EXEC [master].[dbo].[sp_testlinkedserver] @servername=@Server;
            UPDATE [#LinkedServerAnalysis_Linked]
               SET [ConnectivityStatus]='SUCCEEDED'
             WHERE [ServerName]=@Server COLLATE SQL_Latin1_General_CP1_CS_AS;
          END TRY
          BEGIN CATCH
            SET @ErrorNumber=ERROR_NUMBER();
            SET @ErrorMessage=ERROR_MESSAGE();
            IF @ErrorNumber=229
                SET @ServerStatusCode=N'DENIED_PERMISSION';
            ELSE IF @ErrorNumber IN(-2,1222) OR @ErrorMessage LIKE N'%Timeout%' OR @ErrorMessage LIKE N'%timeout%'
                SET @ServerStatusCode=N'SOURCE_TIMEOUT';
            ELSE
                SET @ServerStatusCode=N'SOURCE_UNAVAILABLE';
            UPDATE [#LinkedServerAnalysis_Linked]
               SET [ConnectivityStatus]='FAILED',[StatusCode]=@ServerStatusCode,[EvidenceLimit]=CONCAT(N'Remote-Testfehler ',@ErrorNumber,N': ',LEFT(@ErrorMessage,800))
             WHERE [ServerName]=@Server COLLATE SQL_Latin1_General_CP1_CS_AS;
            SET @Partial=1;
          END CATCH;
          FETCH NEXT FROM [s] INTO @Server;
        END; CLOSE [s]; DEALLOCATE [s];
      END;
      IF NOT EXISTS(SELECT 1 FROM [#LinkedServerAnalysis_Linked]) SET @Status='AVAILABLE_EMPTY'; ELSE IF @Partial=1 AND @Status='AVAILABLE' SET @Status='AVAILABLE_LIMITED';
    END;
    IF @JsonErzeugen=1 SELECT @Json=COALESCE((SELECT TOP(CASE WHEN @MaxZeilen=0 THEN 2147483647 ELSE @MaxZeilen END)* FROM [#LinkedServerAnalysis_Linked] ORDER BY [ServerName] FOR JSON PATH),N'[]');
    IF @Mode IN('CONSOLE','RAW') BEGIN SELECT @Status [StatusCode],@Partial [IsPartial],COUNT_BIG(*) [LinkedServerCount],@ErrorMessage [ErrorMessage] FROM [#LinkedServerAnalysis_Linked]; SELECT TOP(CASE WHEN @MaxZeilen=0 THEN 2147483647 ELSE @MaxZeilen END)* FROM [#LinkedServerAnalysis_Linked] ORDER BY [ServerName]; SELECT [wait_type],[waiting_tasks_count],[wait_time_ms] FROM [sys].[dm_os_wait_stats] WITH (NOLOCK) WHERE [wait_type] LIKE 'OLEDB%' OR [wait_type] LIKE 'REMOTE%' ORDER BY [wait_time_ms] DESC; END;
    IF @PrintMeldungen=1 AND @Mode='NONE' PRINT CONCAT(N'Status: ',@Status);
    IF @ConsoleResultRequested=1 EXEC [monitor].[InternalEmitConsoleResult] @SourceTable=N'#LinkedServerAnalysis_Linked',@ResultLabel=N'linkedServers',@EmptyMessage=N'Keine verknüpften Server im sichtbaren Scope';
    IF @TableResultRequested=1 EXEC [monitor].[InternalWriteResultTable] @SourceTable=N'#LinkedServerAnalysis_Linked',@TargetTable=@TableTarget,@ThrowOnError=1;
    SELECT @StatusCodeOut=@Status,@IsPartialOut=@Partial,@ErrorNumberOut=@ErrorNumber,@ErrorMessageOut=@ErrorMessage;
    SET @RestoreLockTimeoutSql=N'SET LOCK_TIMEOUT '+CONVERT(nvarchar(20),@PreviousLockTimeout)+N';';
    EXEC [sys].[sp_executesql] @RestoreLockTimeoutSql;
END;
GO
-- END SOURCE: Code/08_ServerHealth/220_USP_LinkedServerAnalysis.sql

-- BEGIN SOURCE: Code/08_ServerHealth/230_USP_SystemDatabaseObjectInventory.sql
/* OPS-009: visible user-object inventory in master, model and msdb; no DDL. */
CREATE OR ALTER PROCEDURE [monitor].[USP_SystemDatabaseObjectInventory]
      @MaxZeilen int=2000,@ResultSetArt varchar(16)='CONSOLE',@ResultTablesJson nvarchar(max)=NULL,@JsonErzeugen bit=0,@Json nvarchar(max)=NULL OUTPUT,
      @PrintMeldungen bit=1,@Hilfe bit=0,@StatusCodeOut varchar(40)=NULL OUTPUT,@IsPartialOut bit=NULL OUTPUT,
      @ErrorNumberOut int=NULL OUTPUT,@ErrorMessageOut nvarchar(2048)=NULL OUTPUT
AS
BEGIN
 SET NOCOUNT ON; SET @Json=NULL;
 DECLARE @Status varchar(40)='AVAILABLE',@Partial bit=0,@Mode varchar(16)=UPPER(LTRIM(RTRIM(COALESCE(@ResultSetArt,''))));
 DECLARE @ErrorNumber int=NULL,@ErrorMessage nvarchar(2048)=NULL;
 IF @Hilfe=1 BEGIN PRINT N'monitor.USP_SystemDatabaseObjectInventory'; PRINT N'Inventarisiert sichtbare Benutzerobjekte in master, model und msdb; keine DDL-Aktion.'; RETURN; END;
 DECLARE @PreviousLockTimeout int = @@LOCK_TIMEOUT, @RestoreLockTimeoutSql nvarchar(100);
 SET LOCK_TIMEOUT 0;
 DECLARE @TableResultRequested bit=CASE WHEN @Mode='TABLE' THEN 1 ELSE 0 END,@ConsoleResultRequested bit=CASE WHEN @Mode='CONSOLE' THEN 1 ELSE 0 END,@TableTarget sysname=NULL;
 IF @TableResultRequested=0 AND NULLIF(LTRIM(RTRIM(COALESCE(@ResultTablesJson,N''))),N'') IS NOT NULL THROW 51011,N'@ResultTablesJson ist ausschließlich mit @ResultSetArt=TABLE zulässig.',1;
 IF @TableResultRequested=1 BEGIN EXEC [monitor].[InternalPrepareSingleResultTable] @ResultTablesJson=@ResultTablesJson,@ResultName=N'systemDatabaseObjects',@TargetTable=@TableTarget OUTPUT,@ThrowOnError=1; END;
 IF @TableResultRequested=1 OR @ConsoleResultRequested=1 SET @Mode='NONE';
 CREATE TABLE [#SystemDatabaseObjectInventory_Objects]
 (
      [DatabaseName] sysname COLLATE SQL_Latin1_General_CP1_CS_AS NULL
    , [SchemaName] sysname COLLATE SQL_Latin1_General_CP1_CS_AS NULL
    , [ObjectName] sysname COLLATE SQL_Latin1_General_CP1_CS_AS NULL
    , [ObjectType] nvarchar(60) COLLATE SQL_Latin1_General_CP1_CS_AS NULL
    , [CreateDate] datetime NULL
    , [ModifyDate] datetime NULL
    , [StatusCode] varchar(40) COLLATE SQL_Latin1_General_CP1_CS_AS NULL
    , [EvidenceLimit] nvarchar(1000) COLLATE SQL_Latin1_General_CP1_CS_AS NULL
 );
 IF @MaxZeilen<0 OR @Mode NOT IN('CONSOLE','RAW','NONE') SELECT @Status='INVALID_PARAMETER',@Partial=1,@ErrorMessage=N'Ungültiger Parameter.';
 IF @Status='AVAILABLE' BEGIN
  DECLARE @Db sysname,@Sql nvarchar(max); DECLARE [d] CURSOR LOCAL FAST_FORWARD FOR SELECT [name] FROM [sys].[databases] WITH (NOLOCK) WHERE [database_id] IN(1,3,4) AND [state]=0;
  OPEN [d]; FETCH NEXT FROM [d] INTO @Db; WHILE @@FETCH_STATUS=0 BEGIN
   IF COALESCE(HAS_DBACCESS(@Db),0)<>1 BEGIN INSERT [#SystemDatabaseObjectInventory_Objects] VALUES(@Db,NULL,NULL,NULL,NULL,NULL,'DENIED_PERMISSION',N'Die Systemdatenbank ist für den aktuellen Sicherheitskontext nicht zugänglich.'); SET @Partial=1; END
   ELSE BEGIN TRY SET @Sql=N'INSERT [#SystemDatabaseObjectInventory_Objects] SELECT @Db,[s].[name],[o].[name],[o].[type_desc],[o].[create_date],[o].[modify_date],''AVAILABLE'',N''Sichtbares Inventar; Bewertung benötigt Objektverantwortung und Betriebszweck.'' FROM '+QUOTENAME(@Db)+N'.[sys].[objects] [o] WITH (NOLOCK) JOIN '+QUOTENAME(@Db)+N'.[sys].[schemas] [s] WITH (NOLOCK) ON [s].[schema_id]=[o].[schema_id] WHERE [o].[is_ms_shipped]=0 AND [o].[type] NOT IN(''S'',''IT'');'; EXEC [sys].[sp_executesql] @Sql,N'@Db sysname',@Db; END TRY
   BEGIN CATCH INSERT [#SystemDatabaseObjectInventory_Objects] VALUES(@Db,NULL,NULL,NULL,NULL,NULL,CASE WHEN ERROR_NUMBER() IN (229,371,916) THEN 'DENIED_PERMISSION' ELSE 'SOURCE_UNAVAILABLE' END,CONCAT(N'Fehler ',ERROR_NUMBER(),N': ',LEFT(ERROR_MESSAGE(),800))); SET @Partial=1; END CATCH;
   FETCH NEXT FROM [d] INTO @Db; END; CLOSE [d]; DEALLOCATE [d]; IF NOT EXISTS(SELECT 1 FROM [#SystemDatabaseObjectInventory_Objects]) SET @Status='AVAILABLE_EMPTY'; ELSE IF @Partial=1 SET @Status='AVAILABLE_LIMITED';
 END;
 IF @JsonErzeugen=1 SELECT @Json=COALESCE((SELECT TOP(CASE WHEN @MaxZeilen=0 THEN 2147483647 ELSE @MaxZeilen END)* FROM [#SystemDatabaseObjectInventory_Objects] ORDER BY [DatabaseName],[SchemaName],[ObjectName] FOR JSON PATH),N'[]');
 IF @Mode IN('CONSOLE','RAW') BEGIN SELECT @Status [StatusCode],@Partial [IsPartial],COUNT_BIG(*) [ObjectCount],@ErrorMessage [ErrorMessage] FROM [#SystemDatabaseObjectInventory_Objects]; SELECT TOP(CASE WHEN @MaxZeilen=0 THEN 2147483647 ELSE @MaxZeilen END)* FROM [#SystemDatabaseObjectInventory_Objects] ORDER BY [DatabaseName],[SchemaName],[ObjectName]; END;
 IF @PrintMeldungen=1 AND @Mode='NONE' PRINT CONCAT(N'Status: ',@Status);
 IF @ConsoleResultRequested=1 EXEC [monitor].[InternalEmitConsoleResult] @SourceTable=N'#SystemDatabaseObjectInventory_Objects',@ResultLabel=N'systemDatabaseObjects',@EmptyMessage=N'Keine sichtbaren Benutzerobjekte in Systemdatenbanken';
 IF @TableResultRequested=1 EXEC [monitor].[InternalWriteResultTable] @SourceTable=N'#SystemDatabaseObjectInventory_Objects',@TargetTable=@TableTarget,@ThrowOnError=1;
 SELECT @StatusCodeOut=@Status,@IsPartialOut=@Partial,@ErrorNumberOut=@ErrorNumber,@ErrorMessageOut=@ErrorMessage;
 SET @RestoreLockTimeoutSql=N'SET LOCK_TIMEOUT '+CONVERT(nvarchar(20),@PreviousLockTimeout)+N';'; EXEC [sys].[sp_executesql] @RestoreLockTimeoutSql;
END;
GO
-- END SOURCE: Code/08_ServerHealth/230_USP_SystemDatabaseObjectInventory.sql

-- BEGIN SOURCE: Code/08_ServerHealth/240_USP_AuditConfigurationAnalysis.sql
/*
===============================================================================
Objekt       : monitor.USP_AuditConfigurationAnalysis
Version      : 1.0.0
Stand        : 2026-09-19
Zweck        : Inventarisiert die sichtbare SQL-Server-Auditkonfiguration und
               deren zur Laufzeit gemeldeten Zustand.
Datenquellen : sys.server_audits, sys.server_audit_specifications,
               sys.server_audit_specification_details,
               sys.database_audit_specifications,
               sys.database_audit_specification_details, optional
               sys.dm_server_audit_status.
Datenschutz  : Liest weder Auditdateien noch Auditlog-Payloads, Dateipfade,
               Ereignisinhalte oder überwachte Nutzdaten.
Nebenwirkung : Read-only. Es werden keine Auditobjekte erstellt, gestartet,
               gestoppt, geändert oder gelöscht.
===============================================================================
*/
CREATE OR ALTER PROCEDURE [monitor].[USP_AuditConfigurationAnalysis]
      @DatabaseNames                nvarchar(max) = NULL
    , @SystemdatenbankenEinbeziehen bit           = 0
    , @DatabaseNamePattern          nvarchar(4000)= NULL
    , @HighImpactConfirmed          bit           = 0
    , @AuditNames                   nvarchar(max) = NULL
    , @AuditNamePattern             nvarchar(4000)= NULL
    , @NurProblematisch             bit           = 0
    , @MaxZeilen                    int           = 1000
    , @LockTimeoutMs                int           = 0
    , @ResultSetArt                 varchar(16)   = 'CONSOLE'
    , @ResultTablesJson             nvarchar(max) = NULL
    , @JsonErzeugen                 bit           = 0
    , @Json                         nvarchar(max) = NULL OUTPUT
    , @PrintMeldungen               bit           = 1
    , @Hilfe                        bit           = 0
    , @StatusCodeOut                varchar(40)   = NULL OUTPUT
    , @IsPartialOut                 bit           = NULL OUTPUT
    , @ErrorNumberOut               int           = NULL OUTPUT
    , @ErrorMessageOut              nvarchar(2048)= NULL OUTPUT
AS
BEGIN
    SET NOCOUNT ON;
    SET @Json=NULL;

    DECLARE @Now datetime2(3)=SYSUTCDATETIME();
    DECLARE @OutputMode varchar(16)=UPPER(LTRIM(RTRIM(COALESCE(@ResultSetArt,''))));
    DECLARE @TableRequested bit=CASE WHEN @OutputMode='TABLE' THEN 1 ELSE 0 END;
    DECLARE @ConsoleResultRequested bit=CASE WHEN @OutputMode='CONSOLE' THEN 1 ELSE 0 END;
    DECLARE @Limit bigint=CASE WHEN @MaxZeilen IS NULL OR @MaxZeilen=0 THEN CONVERT(bigint,9223372036854775807) ELSE CONVERT(bigint,@MaxZeilen) END;
    DECLARE @StatusCode varchar(40)='AVAILABLE',@IsPartial bit=0,@ErrorNumber int=NULL,@ErrorMessage nvarchar(2048)=NULL,@CrossDatabaseRequested bit=0;
    DECLARE @AuditPatternMode varchar(8),@AuditPatternValue nvarchar(4000),@AuditPatternFlags varchar(8),@AuditPatternValid bit;

    IF @Hilfe=1
    BEGIN
        PRINT N'monitor.USP_AuditConfigurationAnalysis';
        PRINT N'Inventarisiert sichtbare Audit-, Spezifikations- und Runtime-Metadaten; Auditlog-Payloads, Dateipfade und Ereignisinhalte bleiben ausgeschlossen.';
        PRINT N'@DatabaseNames und @AuditNames verwenden bracket-aware Pipe-Listen; die Patternparameter unterstützen LIKE.';
        PRINT N'@MaxZeilen begrenzt jedes Fachresultset; NULL oder 0 bedeutet unbegrenzt.';
        PRINT N'TABLE erwartet Zuordnungen für audits, serverSpecifications, databaseSpecifications, sourceStatus oder warnings.';
        RETURN;
    END;

    CREATE TABLE [#AuditConfigurationAnalysis_ResultTables]([ResultName] sysname NOT NULL,[TargetTable] sysname NOT NULL);
    IF @TableRequested=1
        EXEC [monitor].[InternalPrepareResultTables] @ResultTablesJson=@ResultTablesJson,
             @AllowedResultNames=N'audits|serverSpecifications|databaseSpecifications|sourceStatus|warnings',
             @MappingTable=N'#AuditConfigurationAnalysis_ResultTables',@ThrowOnError=1;
    IF @TableRequested=1 OR @ConsoleResultRequested=1 SET @OutputMode='NONE';

    CREATE TABLE [#AuditConfigurationAnalysis_DatabaseCandidates]
    (
        [DatabaseId] int NOT NULL PRIMARY KEY,[DatabaseName] sysname COLLATE SQL_Latin1_General_CP1_CS_AS NOT NULL,
        [StateDesc] nvarchar(60) NULL,[UserAccessDesc] nvarchar(60) NULL,[IsReadOnly] bit NULL,[CompatibilityLevel] tinyint NULL,
        [CollationName] sysname NULL,[RecoveryModelDesc] nvarchar(60) NULL,[IsSystemDatabase] bit NULL,[RequestedOrdinal] int NULL
    );
    CREATE TABLE [#AuditConfigurationAnalysis_DatabaseWarnings]([RequestedName] sysname NULL,[StatusCode] varchar(40) NOT NULL,[ErrorMessage] nvarchar(2048) NULL);
    CREATE TABLE [#AuditConfigurationAnalysis_AuditFilter]([NameValue] sysname COLLATE SQL_Latin1_General_CP1_CS_AS NOT NULL PRIMARY KEY);
    CREATE TABLE [#AuditConfigurationAnalysis_Audits]
    (
        [AuditId] uniqueidentifier NOT NULL PRIMARY KEY,[AuditName] sysname COLLATE SQL_Latin1_General_CP1_CS_AS NOT NULL,
        [AuditTargetType] nvarchar(60) NULL,[OnFailure] nvarchar(60) NULL,[QueueDelayMilliseconds] int NULL,
        [IsEnabled] bit NULL,[RuntimeStatus] nvarchar(60) NULL,[RuntimeStatusTime] datetime NULL,
        [ServerSpecificationCount] bigint NULL,[DatabaseSpecificationCount] bigint NULL,[FindingCode] varchar(64) NOT NULL,[FindingSeverity] varchar(16) NOT NULL,
        [EvidenceLimit] nvarchar(1000) NOT NULL
    );
    CREATE TABLE [#AuditConfigurationAnalysis_ServerSpecifications]
    (
        [SpecificationId] int NOT NULL PRIMARY KEY,[SpecificationName] sysname COLLATE SQL_Latin1_General_CP1_CS_AS NOT NULL,
        [AuditId] uniqueidentifier NULL,[AuditName] sysname NULL,[IsEnabled] bit NULL,[ActionCount] bigint NULL,
        [HasAllServerScope] bit NULL,[FindingCode] varchar(64) NOT NULL,[FindingSeverity] varchar(16) NOT NULL,[EvidenceLimit] nvarchar(1000) NOT NULL
    );
    CREATE TABLE [#AuditConfigurationAnalysis_DatabaseSpecifications]
    (
        [DatabaseId] int NOT NULL,[DatabaseName] sysname COLLATE SQL_Latin1_General_CP1_CS_AS NOT NULL,
        [SpecificationId] int NOT NULL,[SpecificationName] sysname COLLATE SQL_Latin1_General_CP1_CS_AS NOT NULL,
        [AuditId] uniqueidentifier NULL,[AuditName] sysname NULL,[IsEnabled] bit NULL,[ActionCount] bigint NULL,
        [HasAllDatabaseScope] bit NULL,[FindingCode] varchar(64) NOT NULL,[FindingSeverity] varchar(16) NOT NULL,[EvidenceLimit] nvarchar(1000) NOT NULL,
        PRIMARY KEY([DatabaseId],[SpecificationId])
    );
    CREATE TABLE [#AuditConfigurationAnalysis_SourceStatus]
    (
        [SourceName] nvarchar(160) NOT NULL PRIMARY KEY,[StatusCode] varchar(40) NOT NULL,[IsPartial] bit NOT NULL,
        [ReturnedRowCount] bigint NULL,[Detail] nvarchar(1000) NOT NULL
    );
    CREATE TABLE [#AuditConfigurationAnalysis_Warnings]
    (
        [WarningScope] varchar(32) NOT NULL,[DatabaseName] sysname NULL,[AuditName] sysname NULL,
        [WarningCode] varchar(64) NOT NULL,[WarningSeverity] varchar(16) NOT NULL,[Detail] nvarchar(1000) NOT NULL
    );

    SELECT @AuditPatternMode=[PatternMode],@AuditPatternValue=[PatternValue],@AuditPatternFlags=[RegexFlags],@AuditPatternValid=[IsValid]
    FROM [monitor].[TVF_ParsePattern](@AuditNamePattern);
    IF @MaxZeilen<0 OR @LockTimeoutMs<0 OR @OutputMode NOT IN('RAW','CONSOLE','NONE')
       OR @AuditPatternValid=0 OR @AuditPatternMode IN('REGEX','REGEXI')
       OR (@AuditNames IS NOT NULL AND @AuditNamePattern IS NOT NULL)
       OR (@AuditNames IS NOT NULL AND EXISTS(SELECT 1 FROM [monitor].[TVF_ParseSqlNameList](@AuditNames) WHERE [IsValid]=0))
        SELECT @StatusCode='INVALID_PARAMETER',@IsPartial=1,@ErrorMessage=N'Ungueltiger Ausgabe-, Limit-, Auditnamen- oder Patternparameter. Regex wird von dieser Procedure nicht unterstuetzt.';

    IF @AuditNames IS NOT NULL
        INSERT [#AuditConfigurationAnalysis_AuditFilter]([NameValue])
        SELECT [NameValue] FROM [monitor].[TVF_ParseSqlNameList](@AuditNames) WHERE [IsValid]=1 GROUP BY [NameValue];

    IF @StatusCode='AVAILABLE'
        EXEC [monitor].[USP_PrepareDatabaseCandidates]
              @DatabaseNames=@DatabaseNames,@SystemdatenbankenEinbeziehen=@SystemdatenbankenEinbeziehen,
              @DatabaseNamePattern=@DatabaseNamePattern,@HighImpactConfirmed=@HighImpactConfirmed,@AnalysisClass=NULL,
              @StatusCode=@StatusCode OUTPUT,@ErrorMessage=@ErrorMessage OUTPUT,@CrossDatabaseRequested=@CrossDatabaseRequested OUTPUT,
              @CandidateTable=N'#AuditConfigurationAnalysis_DatabaseCandidates',@WarningTable=N'#AuditConfigurationAnalysis_DatabaseWarnings';

    SET LOCK_TIMEOUT 0;
    IF @StatusCode='AVAILABLE'
    BEGIN
        BEGIN TRY
            INSERT [#AuditConfigurationAnalysis_Audits]
            ([AuditId],[AuditName],[AuditTargetType],[OnFailure],[QueueDelayMilliseconds],[IsEnabled],[RuntimeStatus],[RuntimeStatusTime],[ServerSpecificationCount],[DatabaseSpecificationCount],[FindingCode],[FindingSeverity],[EvidenceLimit])
            SELECT [a].[audit_guid],[a].[name],[a].[type_desc],[a].[on_failure_desc],[a].[queue_delay],[a].[is_state_enabled],
                   [r].[status_desc],[r].[status_time],
                   (SELECT COUNT_BIG(*) FROM [sys].[server_audit_specifications] [ss] WITH(NOLOCK) WHERE [ss].[audit_guid]=[a].[audit_guid]),
                   NULL,
                   CASE WHEN [a].[is_state_enabled]=0 THEN 'AUDIT_DISABLED' WHEN [r].[status_desc] IS NOT NULL AND [r].[status_desc] NOT IN(N'STARTED',N'RUNNING') THEN 'AUDIT_RUNTIME_NOT_STARTED' ELSE 'AUDIT_CONFIGURED' END,
                   CASE WHEN [a].[is_state_enabled]=0 THEN 'MEDIUM' WHEN [r].[status_desc] IS NOT NULL AND [r].[status_desc] NOT IN(N'STARTED',N'RUNNING') THEN 'MEDIUM' ELSE 'INFO' END,
                   N'Auditziele, Dateipfade und Auditereignisse werden nicht gelesen oder ausgegeben.'
            FROM [sys].[server_audits] [a] WITH(NOLOCK)
            LEFT JOIN [sys].[dm_server_audit_status] [r] WITH(NOLOCK) ON [r].[audit_id]=[a].[audit_id]
            WHERE (@AuditNames IS NULL OR EXISTS(SELECT 1 FROM [#AuditConfigurationAnalysis_AuditFilter] [f] WHERE [f].[NameValue]=[a].[name] COLLATE SQL_Latin1_General_CP1_CS_AS))
              AND (@AuditPatternMode IN('NONE','REGEX','REGEXI') OR [a].[name] COLLATE SQL_Latin1_General_CP1_CS_AS LIKE @AuditPatternValue COLLATE SQL_Latin1_General_CP1_CS_AS);
            INSERT [#AuditConfigurationAnalysis_SourceStatus] VALUES(N'sys.server_audits + sys.dm_server_audit_status','AVAILABLE',0,@@ROWCOUNT,N'Konfiguration und sichtbarer Runtimezustand; keine Auditpayloads oder Pfade.');
        END TRY
        BEGIN CATCH
            INSERT [#AuditConfigurationAnalysis_SourceStatus] VALUES(N'sys.server_audits + sys.dm_server_audit_status',CASE WHEN ERROR_NUMBER() IN(229,297,300,371,15562) THEN 'DENIED_PERMISSION' ELSE 'ERROR_HANDLED' END,1,NULL,N'Auditkonfiguration oder Runtimezustand war nicht vollstaendig lesbar.');
            SELECT @IsPartial=1,@ErrorNumber=ERROR_NUMBER(),@ErrorMessage=ERROR_MESSAGE();
        END CATCH;

        BEGIN TRY
            INSERT [#AuditConfigurationAnalysis_ServerSpecifications]
            ([SpecificationId],[SpecificationName],[AuditId],[AuditName],[IsEnabled],[ActionCount],[HasAllServerScope],[FindingCode],[FindingSeverity],[EvidenceLimit])
            SELECT [s].[server_specification_id],[s].[name],[s].[audit_guid],[a].[name],[s].[is_state_enabled],COUNT_BIG([d].[audit_action_id]),
                   CONVERT(bit,MAX(CASE WHEN [d].[audit_action_name] LIKE N'%ALL SERVER%' THEN 1 ELSE 0 END)),
                   CASE WHEN [s].[is_state_enabled]=0 THEN 'SERVER_SPECIFICATION_DISABLED' WHEN COUNT_BIG([d].[audit_action_id])=0 THEN 'SERVER_SPECIFICATION_WITHOUT_ACTION' ELSE 'SERVER_SPECIFICATION_CONFIGURED' END,
                   CASE WHEN [s].[is_state_enabled]=0 OR COUNT_BIG([d].[audit_action_id])=0 THEN 'MEDIUM' ELSE 'INFO' END,
                   N'Nur Aktionsanzahl und Scopehinweis; keine Auditereignisse oder ueberwachten Nutzdaten.'
            FROM [sys].[server_audit_specifications] [s] WITH(NOLOCK)
            LEFT JOIN [sys].[server_audits] [a] WITH(NOLOCK) ON [a].[audit_guid]=[s].[audit_guid]
            LEFT JOIN [sys].[server_audit_specification_details] [d] WITH(NOLOCK) ON [d].[server_specification_id]=[s].[server_specification_id]
            WHERE @AuditNames IS NULL OR EXISTS(SELECT 1 FROM [#AuditConfigurationAnalysis_AuditFilter] [f] WHERE [f].[NameValue]=[a].[name] COLLATE SQL_Latin1_General_CP1_CS_AS)
            GROUP BY [s].[server_specification_id],[s].[name],[s].[audit_guid],[a].[name],[s].[is_state_enabled];
            INSERT [#AuditConfigurationAnalysis_SourceStatus] VALUES(N'sys.server_audit_specifications + sys.server_audit_specification_details','AVAILABLE',0,@@ROWCOUNT,N'Serverseitige Spezifikationsmetadaten werden aggregiert; Detailaktionen werden nicht ausgegeben.');
        END TRY
        BEGIN CATCH
            INSERT [#AuditConfigurationAnalysis_SourceStatus] VALUES(N'sys.server_audit_specifications + sys.server_audit_specification_details',CASE WHEN ERROR_NUMBER() IN(229,297,300,371,15562) THEN 'DENIED_PERMISSION' ELSE 'ERROR_HANDLED' END,1,NULL,N'Serverseitige Spezifikationsmetadaten waren nicht vollstaendig lesbar.');
            SELECT @IsPartial=1,@ErrorNumber=COALESCE(@ErrorNumber,ERROR_NUMBER()),@ErrorMessage=COALESCE(@ErrorMessage,ERROR_MESSAGE());
        END CATCH;

        DECLARE @DatabaseId int,@DatabaseName sysname,@Sql nvarchar(max),@HasAuditNames bit=CASE WHEN @AuditNames IS NULL THEN 0 ELSE 1 END;
        DECLARE [audit_database_cursor] CURSOR LOCAL FAST_FORWARD FOR
            SELECT [DatabaseId],[DatabaseName] FROM [#AuditConfigurationAnalysis_DatabaseCandidates] WHERE [StateDesc]=N'ONLINE' ORDER BY [DatabaseId];
        OPEN [audit_database_cursor]; FETCH NEXT FROM [audit_database_cursor] INTO @DatabaseId,@DatabaseName;
        WHILE @@FETCH_STATUS=0
        BEGIN
            BEGIN TRY
                SET @Sql=N'INSERT [#AuditConfigurationAnalysis_DatabaseSpecifications]([DatabaseId],[DatabaseName],[SpecificationId],[SpecificationName],[AuditId],[AuditName],[IsEnabled],[ActionCount],[HasAllDatabaseScope],[FindingCode],[FindingSeverity],[EvidenceLimit])
                SELECT @pDatabaseId,@pDatabaseName,[s].[database_specification_id],[s].[name],[s].[audit_guid],[a].[name],[s].[is_state_enabled],COUNT_BIG([d].[audit_action_id]),CONVERT(bit,MAX(CASE WHEN [d].[audit_action_name] LIKE N''%ALL DATABASE%'' THEN 1 ELSE 0 END)),
                CASE WHEN [s].[is_state_enabled]=0 THEN ''DATABASE_SPECIFICATION_DISABLED'' WHEN COUNT_BIG([d].[audit_action_id])=0 THEN ''DATABASE_SPECIFICATION_WITHOUT_ACTION'' ELSE ''DATABASE_SPECIFICATION_CONFIGURED'' END,
                CASE WHEN [s].[is_state_enabled]=0 OR COUNT_BIG([d].[audit_action_id])=0 THEN ''MEDIUM'' ELSE ''INFO'' END,N''Nur Aktionsanzahl und Scopehinweis; keine Auditereignisse oder ueberwachten Nutzdaten.''
                FROM '+QUOTENAME(@DatabaseName)+N'.[sys].[database_audit_specifications] [s] WITH(NOLOCK)
                LEFT JOIN [sys].[server_audits] [a] WITH(NOLOCK) ON [a].[audit_guid]=[s].[audit_guid]
                LEFT JOIN '+QUOTENAME(@DatabaseName)+N'.[sys].[database_audit_specification_details] [d] WITH(NOLOCK) ON [d].[database_specification_id]=[s].[database_specification_id]
                WHERE (@pAuditNames=0 OR EXISTS(SELECT 1 FROM [#AuditConfigurationAnalysis_AuditFilter] [f] WHERE [f].[NameValue]=[a].[name] COLLATE SQL_Latin1_General_CP1_CS_AS))
                GROUP BY [s].[database_specification_id],[s].[name],[s].[audit_guid],[a].[name],[s].[is_state_enabled];';
                EXEC [sys].[sp_executesql] @Sql,N'@pDatabaseId int,@pDatabaseName sysname,@pAuditNames bit',@pDatabaseId=@DatabaseId,@pDatabaseName=@DatabaseName,@pAuditNames=@HasAuditNames;
            END TRY
            BEGIN CATCH
                SET @IsPartial=1;
                INSERT [#AuditConfigurationAnalysis_DatabaseWarnings] VALUES(@DatabaseName,CASE WHEN ERROR_NUMBER() IN(229,297,300,371,916,15562) THEN 'DENIED_PERMISSION' ELSE 'ERROR_HANDLED' END,N'Datenbank-Auditspezifikationen waren fuer diese Datenbank nicht lesbar.');
            END CATCH;
            FETCH NEXT FROM [audit_database_cursor] INTO @DatabaseId,@DatabaseName;
        END;
        CLOSE [audit_database_cursor]; DEALLOCATE [audit_database_cursor];
        INSERT [#AuditConfigurationAnalysis_SourceStatus]
        SELECT N'sys.database_audit_specifications + sys.database_audit_specification_details',CASE WHEN @IsPartial=1 THEN 'AVAILABLE_LIMITED' ELSE 'AVAILABLE' END,@IsPartial,COUNT_BIG(*),N'Datenbanklokale Spezifikationsmetadaten werden je sichtbarer Online-Datenbank isoliert gelesen.'
        FROM [#AuditConfigurationAnalysis_DatabaseSpecifications];

        UPDATE [a] SET [DatabaseSpecificationCount]=[x].[CountValue]
        FROM [#AuditConfigurationAnalysis_Audits] [a]
        OUTER APPLY(SELECT COUNT_BIG(*) [CountValue] FROM [#AuditConfigurationAnalysis_DatabaseSpecifications] [d] WHERE [d].[AuditId]=[a].[AuditId]) [x];
        INSERT [#AuditConfigurationAnalysis_Warnings]
        SELECT 'AUDIT',NULL,[AuditName],[FindingCode],[FindingSeverity],[EvidenceLimit] FROM [#AuditConfigurationAnalysis_Audits] WHERE [FindingSeverity]<>'INFO'
        UNION ALL SELECT 'SERVER_SPECIFICATION',NULL,[AuditName],[FindingCode],[FindingSeverity],[EvidenceLimit] FROM [#AuditConfigurationAnalysis_ServerSpecifications] WHERE [FindingSeverity]<>'INFO'
        UNION ALL SELECT 'DATABASE_SPECIFICATION',[DatabaseName],[AuditName],[FindingCode],[FindingSeverity],[EvidenceLimit] FROM [#AuditConfigurationAnalysis_DatabaseSpecifications] WHERE [FindingSeverity]<>'INFO';

        IF EXISTS(SELECT 1 FROM [#AuditConfigurationAnalysis_SourceStatus] WHERE [IsPartial]=1) SELECT @StatusCode='AVAILABLE_LIMITED',@IsPartial=1;
        ELSE IF EXISTS(SELECT 1 FROM [#AuditConfigurationAnalysis_Warnings] WHERE [WarningSeverity]='MEDIUM') SET @StatusCode='AVAILABLE_WITH_FINDING';
    END;

    SELECT @StatusCodeOut=@StatusCode,@IsPartialOut=@IsPartial,@ErrorNumberOut=@ErrorNumber,@ErrorMessageOut=@ErrorMessage;
    IF @JsonErzeugen=1
    BEGIN
        DECLARE @Meta nvarchar(max)=(SELECT N'AuditConfigurationAnalysis' [resultName],1 [schemaVersion],@Now [generatedAtUtc],@StatusCode [statusCode],@IsPartial [isPartial],@CrossDatabaseRequested [crossDatabaseRequested] FOR JSON PATH,WITHOUT_ARRAY_WRAPPER,INCLUDE_NULL_VALUES);
        SET @Json=CONCAT(N'{"meta":',COALESCE(@Meta,N'{}'),N',"audits":',COALESCE((SELECT TOP(@Limit) * FROM [#AuditConfigurationAnalysis_Audits] WHERE @NurProblematisch=0 OR [FindingSeverity]<>'INFO' ORDER BY [AuditName] FOR JSON PATH,INCLUDE_NULL_VALUES),N'[]'),N',"serverSpecifications":',COALESCE((SELECT TOP(@Limit) * FROM [#AuditConfigurationAnalysis_ServerSpecifications] WHERE @NurProblematisch=0 OR [FindingSeverity]<>'INFO' ORDER BY [SpecificationName] FOR JSON PATH,INCLUDE_NULL_VALUES),N'[]'),N',"databaseSpecifications":',COALESCE((SELECT TOP(@Limit) * FROM [#AuditConfigurationAnalysis_DatabaseSpecifications] WHERE @NurProblematisch=0 OR [FindingSeverity]<>'INFO' ORDER BY [DatabaseName],[SpecificationName] FOR JSON PATH,INCLUDE_NULL_VALUES),N'[]'),N',"sourceStatus":',COALESCE((SELECT * FROM [#AuditConfigurationAnalysis_SourceStatus] ORDER BY [SourceName] FOR JSON PATH,INCLUDE_NULL_VALUES),N'[]'),N',"warnings":',COALESCE((SELECT * FROM [#AuditConfigurationAnalysis_Warnings] ORDER BY [WarningScope],[DatabaseName],[AuditName] FOR JSON PATH,INCLUDE_NULL_VALUES),N'[]'),N'}');
    END;
    IF @OutputMode='RAW'
    BEGIN
        SELECT N'USP_AuditConfigurationAnalysis' [ModuleName],@Now [CollectionTimeUtc],@StatusCode [StatusCode],@IsPartial [IsPartial],@ErrorNumber [ErrorNumber],@ErrorMessage [ErrorMessage];
        SELECT TOP(@Limit) * FROM [#AuditConfigurationAnalysis_Audits] WHERE @NurProblematisch=0 OR [FindingSeverity]<>'INFO' ORDER BY [AuditName];
        SELECT TOP(@Limit) * FROM [#AuditConfigurationAnalysis_ServerSpecifications] WHERE @NurProblematisch=0 OR [FindingSeverity]<>'INFO' ORDER BY [SpecificationName];
        SELECT TOP(@Limit) * FROM [#AuditConfigurationAnalysis_DatabaseSpecifications] WHERE @NurProblematisch=0 OR [FindingSeverity]<>'INFO' ORDER BY [DatabaseName],[SpecificationName];
        SELECT * FROM [#AuditConfigurationAnalysis_SourceStatus] ORDER BY [SourceName]; SELECT * FROM [#AuditConfigurationAnalysis_Warnings] ORDER BY [WarningScope],[DatabaseName],[AuditName];
    END
    ELSE IF @OutputMode='CONSOLE'
    BEGIN
        SELECT N'Auditkonfiguration' [Ergebnis],@Now [Stand_UTC],@StatusCode [Status],@IsPartial [Teilweise],@ErrorMessage [Hinweis];
        SELECT TOP(@Limit) N'Audit' [Ergebnis],[AuditName] [Audit],[AuditTargetType] [Zieltyp],[IsEnabled] [Aktiv],[RuntimeStatus] [Runtime_Status],[ServerSpecificationCount] [Server_Spezifikationen],[DatabaseSpecificationCount] [Datenbank_Spezifikationen],[FindingCode] [Befund],[FindingSeverity] [Prioritaet],[EvidenceLimit] [Evidenzgrenze] FROM [#AuditConfigurationAnalysis_Audits] WHERE @NurProblematisch=0 OR [FindingSeverity]<>'INFO' ORDER BY [AuditName];
        SELECT TOP(@Limit) N'Server-Auditspezifikation' [Ergebnis],[SpecificationName] [Spezifikation],[AuditName] [Audit],[IsEnabled] [Aktiv],[ActionCount] [Aktionsanzahl],[FindingCode] [Befund],[FindingSeverity] [Prioritaet] FROM [#AuditConfigurationAnalysis_ServerSpecifications] WHERE @NurProblematisch=0 OR [FindingSeverity]<>'INFO' ORDER BY [SpecificationName];
        SELECT TOP(@Limit) N'Datenbank-Auditspezifikation' [Ergebnis],[DatabaseName] [Datenbank],[SpecificationName] [Spezifikation],[AuditName] [Audit],[IsEnabled] [Aktiv],[ActionCount] [Aktionsanzahl],[FindingCode] [Befund],[FindingSeverity] [Prioritaet] FROM [#AuditConfigurationAnalysis_DatabaseSpecifications] WHERE @NurProblematisch=0 OR [FindingSeverity]<>'INFO' ORDER BY [DatabaseName],[SpecificationName];
        SELECT N'Quellenstatus' [Ergebnis],[SourceName] [Quelle],[StatusCode] [Status],[IsPartial] [Teilweise],[Detail] [Hinweis] FROM [#AuditConfigurationAnalysis_SourceStatus] ORDER BY [SourceName];
        SELECT N'Warnung' [Ergebnis],[WarningScope] [Scope],[DatabaseName] [Datenbank],[AuditName] [Audit],[WarningCode] [Code],[WarningSeverity] [Prioritaet],[Detail] [Hinweis] FROM [#AuditConfigurationAnalysis_Warnings] ORDER BY [WarningScope],[DatabaseName],[AuditName];
    END;
    IF @ConsoleResultRequested=1 EXEC [monitor].[InternalEmitConsoleResult] @SourceTable=N'#AuditConfigurationAnalysis_Audits',@ResultLabel=N'AuditConfigurationAnalysis',@EmptyMessage=N'Keine sichtbaren Auditkonfigurationen';
    IF @TableRequested=1
    BEGIN
        DECLARE @ResultName sysname,@TargetTable sysname,@SourceTable sysname;
        DECLARE [audit_table_cursor] CURSOR LOCAL FAST_FORWARD FOR SELECT [ResultName],[TargetTable] FROM [#AuditConfigurationAnalysis_ResultTables] ORDER BY [ResultName];
        OPEN [audit_table_cursor]; FETCH NEXT FROM [audit_table_cursor] INTO @ResultName,@TargetTable;
        WHILE @@FETCH_STATUS=0
        BEGIN
            SET @SourceTable=CASE @ResultName WHEN N'audits' THEN N'#AuditConfigurationAnalysis_Audits' WHEN N'serverSpecifications' THEN N'#AuditConfigurationAnalysis_ServerSpecifications' WHEN N'databaseSpecifications' THEN N'#AuditConfigurationAnalysis_DatabaseSpecifications' WHEN N'sourceStatus' THEN N'#AuditConfigurationAnalysis_SourceStatus' ELSE N'#AuditConfigurationAnalysis_Warnings' END;
            EXEC [monitor].[InternalWriteResultTable] @SourceTable=@SourceTable,@TargetTable=@TargetTable,@ThrowOnError=1;
            FETCH NEXT FROM [audit_table_cursor] INTO @ResultName,@TargetTable;
        END;
        CLOSE [audit_table_cursor]; DEALLOCATE [audit_table_cursor];
    END;
END;
GO
-- END SOURCE: Code/08_ServerHealth/240_USP_AuditConfigurationAnalysis.sql

-- BEGIN SOURCE: Code/08_ServerHealth/100_USP_ServerHealthAnalysis.sql
/*
===============================================================================
Objekt       : monitor.USP_ServerHealthAnalysis
Version      : 3.2.0
Stand        : 2026-07-19
Zweck        : Orchestriert alle Server-Health-Module. RAW/CONSOLE werden an
               Child-Module weitergereicht; JSON enthält benannte Modulobjekte.
Änderungen   : 3.2.0 - Bereits erhobene Integritäts-, Kapazitäts- und
                         Buffer-Pool-Ergebnisse im Findings-Child wiederverwendet.
               3.1.0 - Spezialfallmodule und normalisierte Befunde als opt-in.
               3.0.1 - IF/TRY/CATCH-Blöcke syntaktisch eindeutig strukturiert;
                         Child-Statusvariablen vor jedem Aufruf zurückgesetzt.
===============================================================================
*/
CREATE OR ALTER PROCEDURE [monitor].[USP_ServerHealthAnalysis]
      @MitCpu           bit           = 1
    , @MitNuma          bit           = 1
    , @MitMemory        bit           = 1
    , @MitTempDB        bit           = 1
    , @MitConfiguration bit           = 1
    , @MitTraceFlags    bit           = 1
    , @MitStartup       bit           = 1
    , @MitOS            bit           = 1
    , @MitSecurity      bit           = 1
    , @MitIntegritaet   bit           = 0
    , @MitKapazitaet    bit           = 0
    , @MitPerformanceCounters bit      = 0
    , @MitCriticalEvents bit           = 0
    , @MitContention    bit           = 0
    , @MitBufferPool    bit           = 0
    , @MitFindings      bit           = 0
    , @DatabaseNames    nvarchar(max) = NULL
    , @SystemdatenbankenEinbeziehen bit = 0
    , @DatabaseNamePattern nvarchar(4000) = NULL
    , @HighImpactConfirmed              bit            = 0
    , @MaxZeilen        int           = 100
    , @ResultSetArt     varchar(16)   = 'CONSOLE'
    , @ResultTablesJson               nvarchar(max) = NULL
    , @JsonErzeugen     bit           = 0
    , @Json             nvarchar(max) = NULL OUTPUT
    , @PrintMeldungen   bit           = 1
    , @Hilfe            bit           = 0
AS
BEGIN
    SET NOCOUNT ON;
    SET LOCK_TIMEOUT 0;
    SET @Json = NULL;

    DECLARE @OutputMode varchar(16) = UPPER(LTRIM(RTRIM(COALESCE(@ResultSetArt, ''))));
    DECLARE @TableResultRequested bit = CASE WHEN @OutputMode = 'TABLE' THEN 1 ELSE 0 END;
    DECLARE @ConsoleResultRequested bit = CASE WHEN @OutputMode = 'CONSOLE' THEN 1 ELSE 0 END;
    DECLARE @TableTarget sysname=NULL;
    IF @TableResultRequested=0 AND NULLIF(LTRIM(RTRIM(COALESCE(@ResultTablesJson,N''))),N'') IS NOT NULL THROW 51011,N'@ResultTablesJson ist ausschließlich mit @ResultSetArt=TABLE zulässig.',1;
    IF @TableResultRequested=1 EXEC [monitor].[InternalPrepareSingleResultTable] @ResultTablesJson=@ResultTablesJson,@ResultName=N'moduleStatus',@TargetTable=@TableTarget OUTPUT,@ThrowOnError=1;
    IF @TableResultRequested = 1 OR @ConsoleResultRequested = 1 SET @OutputMode = 'NONE';
    DECLARE @ChildJsonRequested bit = CASE WHEN @JsonErzeugen=1 OR @MitFindings=1 THEN 1 ELSE 0 END;
    DECLARE @Now datetime2(3) = SYSUTCDATETIME();
    DECLARE @OverallStatus varchar(40) = 'AVAILABLE';
    DECLARE @ChildStatus varchar(40);
    DECLARE @ChildPartial bit;
    DECLARE @ChildErrorNumber int;
    DECLARE @ChildErrorMessage nvarchar(2048);
    DECLARE @CpuJson nvarchar(max);
    DECLARE @NumaJson nvarchar(max);
    DECLARE @MemoryJson nvarchar(max);
    DECLARE @TempDbJson nvarchar(max);
    DECLARE @ConfigurationJson nvarchar(max);
    DECLARE @TraceFlagsJson nvarchar(max);
    DECLARE @StartupJson nvarchar(max);
    DECLARE @OsJson nvarchar(max);
    DECLARE @SecurityJson nvarchar(max);
    DECLARE @IntegrityJson nvarchar(max);
    DECLARE @CapacityJson nvarchar(max);
    DECLARE @CountersJson nvarchar(max);
    DECLARE @CriticalEventsJson nvarchar(max);
    DECLARE @ContentionJson nvarchar(max);
    DECLARE @BufferPoolJson nvarchar(max);
    DECLARE @FindingsJson nvarchar(max);

    CREATE TABLE [#ServerHealthAnalysis_ModuleStatus]
    (
          [Ordinal]      tinyint        NOT NULL
        , [ModuleName]   sysname        NOT NULL
        , [StatusCode]   varchar(40)    NOT NULL
        , [IsPartial]    bit            NOT NULL
        , [ErrorNumber]  int            NULL
        , [ErrorMessage] nvarchar(2048) NULL
    );

    IF @Hilfe = 1
    BEGIN
        PRINT N'monitor.USP_ServerHealthAnalysis';
        PRINT N'@ResultSetArt = RAW, CONSOLE, TABLE oder NONE; optional JSON mit benannten Modulobjekten.';
        RETURN;
    END;

    IF @MaxZeilen < 0
       OR @OutputMode NOT IN ('RAW', 'CONSOLE', 'NONE')
       OR (@MitCpu = 0 AND @MitNuma = 0 AND @MitMemory = 0 AND @MitTempDB = 0
           AND @MitConfiguration = 0 AND @MitTraceFlags = 0 AND @MitStartup = 0
           AND @MitOS = 0 AND @MitSecurity = 0 AND @MitIntegritaet = 0
           AND @MitKapazitaet = 0 AND @MitPerformanceCounters = 0
           AND @MitCriticalEvents = 0 AND @MitContention = 0
           AND @MitBufferPool = 0 AND @MitFindings = 0)
    BEGIN
        SET @OverallStatus = 'INVALID_PARAMETER';
    END;

    IF @OverallStatus = 'AVAILABLE' AND @MitCpu = 1
    BEGIN
        SELECT @ChildStatus = NULL, @ChildPartial = NULL, @ChildErrorNumber = NULL, @ChildErrorMessage = NULL;
        BEGIN TRY
            EXEC [monitor].[USP_ServerCpuTopology]
                  @ResultSetArt = @OutputMode
                , @JsonErzeugen = @JsonErzeugen
                , @Json = @CpuJson OUTPUT
                , @PrintMeldungen = @PrintMeldungen
                , @StatusCodeOut = @ChildStatus OUTPUT
                , @IsPartialOut = @ChildPartial OUTPUT
                , @ErrorNumberOut = @ChildErrorNumber OUTPUT
                , @ErrorMessageOut = @ChildErrorMessage OUTPUT;
        END TRY
        BEGIN CATCH
            SELECT @ChildStatus = 'ERROR_HANDLED', @ChildPartial = 1,
                   @ChildErrorNumber = ERROR_NUMBER(), @ChildErrorMessage = ERROR_MESSAGE();
        END CATCH;
        INSERT [#ServerHealthAnalysis_ModuleStatus] VALUES
        (1, N'USP_ServerCpuTopology', COALESCE(@ChildStatus, 'ERROR_HANDLED'), COALESCE(@ChildPartial, 1), @ChildErrorNumber, @ChildErrorMessage);
    END;

    IF @OverallStatus = 'AVAILABLE' AND @MitNuma = 1
    BEGIN
        SELECT @ChildStatus = NULL, @ChildPartial = NULL, @ChildErrorNumber = NULL, @ChildErrorMessage = NULL;
        BEGIN TRY
            EXEC [monitor].[USP_ServerNuma]
                  @ResultSetArt = @OutputMode
                , @JsonErzeugen = @JsonErzeugen
                , @Json = @NumaJson OUTPUT
                , @PrintMeldungen = @PrintMeldungen
                , @StatusCodeOut = @ChildStatus OUTPUT
                , @IsPartialOut = @ChildPartial OUTPUT
                , @ErrorNumberOut = @ChildErrorNumber OUTPUT
                , @ErrorMessageOut = @ChildErrorMessage OUTPUT;
        END TRY
        BEGIN CATCH
            SELECT @ChildStatus = 'ERROR_HANDLED', @ChildPartial = 1,
                   @ChildErrorNumber = ERROR_NUMBER(), @ChildErrorMessage = ERROR_MESSAGE();
        END CATCH;
        INSERT [#ServerHealthAnalysis_ModuleStatus] VALUES
        (2, N'USP_ServerNuma', COALESCE(@ChildStatus, 'ERROR_HANDLED'), COALESCE(@ChildPartial, 1), @ChildErrorNumber, @ChildErrorMessage);
    END;

    IF @OverallStatus = 'AVAILABLE' AND @MitMemory = 1
    BEGIN
        SELECT @ChildStatus = NULL, @ChildPartial = NULL, @ChildErrorNumber = NULL, @ChildErrorMessage = NULL;
        BEGIN TRY
            EXEC [monitor].[USP_ServerMemory]
                  @MaxZeilen = @MaxZeilen
                , @ResultSetArt = @OutputMode
                , @JsonErzeugen = @JsonErzeugen
                , @Json = @MemoryJson OUTPUT
                , @PrintMeldungen = @PrintMeldungen
                , @StatusCodeOut = @ChildStatus OUTPUT
                , @IsPartialOut = @ChildPartial OUTPUT
                , @ErrorNumberOut = @ChildErrorNumber OUTPUT
                , @ErrorMessageOut = @ChildErrorMessage OUTPUT;
        END TRY
        BEGIN CATCH
            SELECT @ChildStatus = 'ERROR_HANDLED', @ChildPartial = 1,
                   @ChildErrorNumber = ERROR_NUMBER(), @ChildErrorMessage = ERROR_MESSAGE();
        END CATCH;
        INSERT [#ServerHealthAnalysis_ModuleStatus] VALUES
        (3, N'USP_ServerMemory', COALESCE(@ChildStatus, 'ERROR_HANDLED'), COALESCE(@ChildPartial, 1), @ChildErrorNumber, @ChildErrorMessage);
    END;

    IF @OverallStatus = 'AVAILABLE' AND @MitTempDB = 1
    BEGIN
        SELECT @ChildStatus = NULL, @ChildPartial = NULL, @ChildErrorNumber = NULL, @ChildErrorMessage = NULL;
        BEGIN TRY
            EXEC [monitor].[USP_TempDBConfiguration]
                  @ResultSetArt = @OutputMode
                , @JsonErzeugen = @JsonErzeugen
                , @Json = @TempDbJson OUTPUT
                , @PrintMeldungen = @PrintMeldungen
                , @StatusCodeOut = @ChildStatus OUTPUT
                , @IsPartialOut = @ChildPartial OUTPUT
                , @ErrorNumberOut = @ChildErrorNumber OUTPUT
                , @ErrorMessageOut = @ChildErrorMessage OUTPUT;
        END TRY
        BEGIN CATCH
            SELECT @ChildStatus = 'ERROR_HANDLED', @ChildPartial = 1,
                   @ChildErrorNumber = ERROR_NUMBER(), @ChildErrorMessage = ERROR_MESSAGE();
        END CATCH;
        INSERT [#ServerHealthAnalysis_ModuleStatus] VALUES
        (4, N'USP_TempDBConfiguration', COALESCE(@ChildStatus, 'ERROR_HANDLED'), COALESCE(@ChildPartial, 1), @ChildErrorNumber, @ChildErrorMessage);
    END;

    IF @OverallStatus = 'AVAILABLE' AND @MitConfiguration = 1
    BEGIN
        SELECT @ChildStatus = NULL, @ChildPartial = NULL, @ChildErrorNumber = NULL, @ChildErrorMessage = NULL;
        BEGIN TRY
            EXEC [monitor].[USP_ServerConfiguration]
                  @ResultSetArt = @OutputMode
                , @JsonErzeugen = @JsonErzeugen
                , @Json = @ConfigurationJson OUTPUT
                , @PrintMeldungen = @PrintMeldungen
                , @StatusCodeOut = @ChildStatus OUTPUT
                , @IsPartialOut = @ChildPartial OUTPUT
                , @ErrorNumberOut = @ChildErrorNumber OUTPUT
                , @ErrorMessageOut = @ChildErrorMessage OUTPUT;
        END TRY
        BEGIN CATCH
            SELECT @ChildStatus = 'ERROR_HANDLED', @ChildPartial = 1,
                   @ChildErrorNumber = ERROR_NUMBER(), @ChildErrorMessage = ERROR_MESSAGE();
        END CATCH;
        INSERT [#ServerHealthAnalysis_ModuleStatus] VALUES
        (5, N'USP_ServerConfiguration', COALESCE(@ChildStatus, 'ERROR_HANDLED'), COALESCE(@ChildPartial, 1), @ChildErrorNumber, @ChildErrorMessage);
    END;

    IF @OverallStatus = 'AVAILABLE' AND @MitTraceFlags = 1
    BEGIN
        SELECT @ChildStatus = NULL, @ChildPartial = NULL, @ChildErrorNumber = NULL, @ChildErrorMessage = NULL;
        BEGIN TRY
            EXEC [monitor].[USP_TraceFlags]
                  @ResultSetArt = @OutputMode
                , @JsonErzeugen = @JsonErzeugen
                , @Json = @TraceFlagsJson OUTPUT
                , @PrintMeldungen = @PrintMeldungen
                , @StatusCodeOut = @ChildStatus OUTPUT
                , @IsPartialOut = @ChildPartial OUTPUT
                , @ErrorNumberOut = @ChildErrorNumber OUTPUT
                , @ErrorMessageOut = @ChildErrorMessage OUTPUT;
        END TRY
        BEGIN CATCH
            SELECT @ChildStatus = 'ERROR_HANDLED', @ChildPartial = 1,
                   @ChildErrorNumber = ERROR_NUMBER(), @ChildErrorMessage = ERROR_MESSAGE();
        END CATCH;
