-- BEGIN SOURCE: Code/09_VersionAdaptive/015_USP_ServerVersionInformation.sql
/*
===============================================================================
Objekt       : monitor.USP_ServerVersionInformation
Version      : 1.0.0
Stand        : 2026-07-21
Typ          : Stored Procedure
Zweck        : Liefert Instanzversion, Offline-Buildbewertung, Lifecycle,
               Featureflags und optional sichtbaren Datenbank-Kompatibilitäts-
               kontext mit expliziter Provenienz und Evidenzgrenzen.
SQL-Version  : SQL Server 2019 oder neuer.
Datenquellen : SERVERPROPERTY, sys.dm_os_sys_info, sys.dm_os_host_info,
               master.sys.databases sowie monitor.SqlServer*Catalog.
Eigenlast    : Gering; kein Plan-Cache-, Query-Store- oder Benutzerdatenzugriff.
Datenschutz  : Normale Ausgabe enthält keine Server-, Host-, Instanz-, Konto-
               oder Pfadidentität. Datenbanknamen erscheinen nur im explizit
               aktivierten Kompatibilitätsresultset.
Grenze       : Offline-Katalog; kein Vulnerability-, Neustart-, Lizenz- oder
               betrieblicher Freigabenachweis.
===============================================================================
*/
CREATE OR ALTER PROCEDURE [monitor].[USP_ServerVersionInformation]
      @MitDatenbankKompatibilitaet bit            = 0
    , @DatabaseNames                nvarchar(max)  = NULL
    , @DatabaseNamePattern          nvarchar(4000) = NULL
    , @SystemdatenbankenEinbeziehen bit            = 0
    , @MaxZeilen                    int            = 2000
    , @ResultSetArt                 varchar(16)    = 'CONSOLE'
    , @ResultTablesJson             nvarchar(max)  = NULL
    , @JsonErzeugen                 bit            = 0
    , @Json                         nvarchar(max)  = NULL OUTPUT
    , @PrintMeldungen               bit            = 1
    , @Hilfe                        bit            = 0
    , @StatusCodeOut                varchar(40)    = NULL OUTPUT
    , @IsPartialOut                 bit            = NULL OUTPUT
    , @ErrorNumberOut               int            = NULL OUTPUT
    , @ErrorMessageOut              nvarchar(2048) = NULL OUTPUT
AS
BEGIN
    SET NOCOUNT ON;
    SET @Json=NULL;

    DECLARE @CapturedAtUtc datetime2(3)=SYSUTCDATETIME();
    DECLARE @OutputMode varchar(16)=UPPER(LTRIM(RTRIM(COALESCE(@ResultSetArt,''))));
    DECLARE @ConsoleResultRequested bit=CASE WHEN UPPER(LTRIM(RTRIM(COALESCE(@ResultSetArt,''))))='CONSOLE' THEN 1 ELSE 0 END;
    DECLARE @StatusCode varchar(40)='AVAILABLE';
    DECLARE @IsPartial bit=0;
    DECLARE @ErrorNumber int=NULL;
    DECLARE @ErrorMessage nvarchar(2048)=NULL;
    DECLARE @Limit bigint=CASE WHEN @MaxZeilen IS NULL OR @MaxZeilen=0
                               THEN CONVERT(bigint,9223372036854775807)
                               ELSE CONVERT(bigint,@MaxZeilen) END;

    IF @Hilfe=1
    BEGIN
        PRINT N'monitor.USP_ServerVersionInformation';
        PRINT N'Die Procedure führt eine leichte Offline-Bewertung von Instanzversion, Buildzweig und Microsoft-Lifecycle durch.';
        PRINT N'@MitDatenbankKompatibilitaet bit=0: 1 ergänzt sichtbare Datenbanken; Namen werden nur in diesem expliziten Resultset ausgegeben.';
        PRINT N'@DatabaseNames und @DatabaseNamePattern sind alternative Filter; Systemdatenbanken benötigen @SystemdatenbankenEinbeziehen=1.';
        PRINT N'@MaxZeilen int=2000: positive Werte begrenzen Datenbankzeilen; NULL/0 bedeutet unbegrenzt.';
        PRINT N'@ResultSetArt=CONSOLE|RAW|TABLE|NONE; TABLE verwendet benannte Ziele in @ResultTablesJson.';
        PRINT N'Der Offline-Katalog beweist weder vollständige Security-Patches noch Verwundbarkeit, Neustartbedarf oder betriebliche Freigabe.';
        RETURN;
    END;

    CREATE TABLE [#ServerVersionInformation_ResultTableMap]
    (
          [ResultName] sysname COLLATE SQL_Latin1_General_CP1_CS_AS NOT NULL
        , [TargetTable] sysname COLLATE SQL_Latin1_General_CP1_CS_AS NOT NULL
    );
    CREATE TABLE [#ServerVersionInformation_DatabaseCandidates]
    (
          [DatabaseId] int NOT NULL
        , [DatabaseName] sysname NOT NULL
        , [StateDesc] nvarchar(60) NULL
        , [UserAccessDesc] nvarchar(60) NULL
        , [IsReadOnly] bit NULL
        , [CompatibilityLevel] tinyint NULL
        , [CollationName] sysname NULL
        , [RecoveryModelDesc] nvarchar(60) NULL
        , [IsSystemDatabase] bit NULL
        , [RequestedOrdinal] int NULL
    );
    CREATE TABLE [#ServerVersionInformation_CandidateWarnings]
    (
          [RequestedName] sysname COLLATE SQL_Latin1_General_CP1_CS_AS NULL
        , [StatusCode] varchar(40) NOT NULL
        , [ErrorMessage] nvarchar(2048) NOT NULL
    );
    CREATE TABLE [#ServerVersionInformation_ServerVersion]
    (
          [SourceType] varchar(32) NOT NULL
        , [SourceObject] nvarchar(256) NOT NULL
        , [CapturedAtUtc] datetime2(3) NOT NULL
        , [EvidenceScope] varchar(40) NOT NULL
        , [IsCurrent] bit NOT NULL
        , [StatusCode] varchar(40) NOT NULL
        , [ProductVersion] varchar(32) NULL
        , [ProductMajorVersion] int NULL
        , [ProductMinorVersion] int NULL
        , [ProductBuild] int NULL
        , [ProductRevision] int NULL
        , [ProductLevel] nvarchar(128) NULL
        , [ProductUpdateLevel] nvarchar(128) NULL
        , [ProductUpdateReference] nvarchar(128) NULL
        , [ProductBuildType] nvarchar(128) NULL
        , [ResourceVersion] nvarchar(128) NULL
        , [ResourceLastUpdateDateTime] datetime NULL
        , [BuildClrVersion] nvarchar(128) NULL
        , [Edition] nvarchar(128) NULL
        , [EditionId] bigint NULL
        , [EngineEdition] int NULL
        , [EngineClass] varchar(40) NULL
        , [HostPlatform] nvarchar(256) NULL
        , [HostDistribution] nvarchar(256) NULL
        , [HostRelease] nvarchar(256) NULL
        , [HostServicePackLevel] nvarchar(256) NULL
        , [HostSku] int NULL
        , [OsLanguageVersion] int NULL
        , [SqlServerStartTimeUtc] datetime NULL
        , [UptimeMilliseconds] bigint NULL
        , [ProcessId] int NULL
        , [IsClustered] bit NULL
        , [IsHadrEnabled] bit NULL
        , [HadrManagerStatus] int NULL
        , [IsLocalDb] bit NULL
        , [ServerCollation] sysname NULL
        , [TempDbCollation] sysname NULL
        , [EvidenceLimit] nvarchar(1000) NOT NULL
    );
    CREATE TABLE [#ServerVersionInformation_BuildAssessment]
    (
          [SourceType] varchar(32) NOT NULL
        , [SourceObject] nvarchar(256) NOT NULL
        , [CapturedAtUtc] datetime2(3) NOT NULL
        , [EvidenceScope] varchar(40) NOT NULL
        , [AssessmentStatus] varchar(40) NOT NULL
        , [CatalogFreshnessStatus] varchar(40) NOT NULL
        , [ProductVersion] varchar(32) NULL
        , [KnownReleaseName] nvarchar(64) NULL
        , [ServicingBranch] varchar(16) NULL
        , [KnowledgeBaseNumber] varchar(16) NULL
        , [ReleaseDate] date NULL
        , [IsSecurityRelease] bit NULL
        , [LatestKnownBuildInBranch] varchar(32) NULL
        , [LatestKnownBuildForMajor] varchar(32) NULL
        , [CatalogAsOfDate] date NULL
        , [BuildOverviewUrl] nvarchar(512) NULL
        , [KnowledgeBaseUrl] nvarchar(512) NULL
        , [EvidenceLimit] nvarchar(1000) NOT NULL
    );
    CREATE TABLE [#ServerVersionInformation_Lifecycle]
    (
          [SourceType] varchar(32) NOT NULL
        , [SourceObject] nvarchar(256) NOT NULL
        , [CapturedAtUtc] datetime2(3) NOT NULL
        , [EvidenceScope] varchar(40) NOT NULL
        , [LifecycleStatus] varchar(40) NOT NULL
        , [ProductMajorVersion] int NULL
        , [ProductName] nvarchar(64) NULL
        , [StartDate] date NULL
        , [MainstreamEndDate] date NULL
        , [ExtendedEndDate] date NULL
        , [LifecyclePolicy] varchar(32) NULL
        , [CatalogAsOfDate] date NULL
        , [LifecycleUrl] nvarchar(512) NULL
        , [EvidenceLimit] nvarchar(1000) NOT NULL
    );
    CREATE TABLE [#ServerVersionInformation_InstanceFeatures]
    (
          [SourceType] varchar(32) NOT NULL
        , [SourceObject] nvarchar(256) NOT NULL
        , [CapturedAtUtc] datetime2(3) NOT NULL
        , [EvidenceScope] varchar(40) NOT NULL
        , [FeatureName] sysname NOT NULL
        , [FeatureValue] int NULL
        , [ValueStatus] varchar(40) NOT NULL
        , [EvidenceLimit] nvarchar(1000) NOT NULL
    );
    CREATE TABLE [#ServerVersionInformation_DatabaseCompatibility]
    (
          [SourceType] varchar(32) NOT NULL
        , [SourceObject] nvarchar(256) NOT NULL
        , [CapturedAtUtc] datetime2(3) NOT NULL
        , [EvidenceScope] varchar(40) NOT NULL
        , [IsCurrent] bit NOT NULL
        , [StatusCode] varchar(40) NOT NULL
        , [DatabaseId] int NOT NULL
        , [DatabaseName] sysname NOT NULL
        , [CompatibilityLevel] tinyint NULL
        , [CollationName] sysname NULL
        , [StateDesc] nvarchar(60) NULL
        , [IsReadOnly] bit NULL
        , [IsSystemDatabase] bit NULL
        , [EvidenceLimit] nvarchar(1000) NOT NULL
    );
    CREATE TABLE [#ServerVersionInformation_References]
    (
          [ReferenceType] varchar(40) NOT NULL
        , [ProductMajorVersion] int NULL
        , [Title] nvarchar(256) NOT NULL
        , [Url] nvarchar(512) NOT NULL
        , [CatalogAsOfDate] date NOT NULL
    );
    CREATE TABLE [#ServerVersionInformation_Warnings]
    (
          [WarningOrdinal] bigint IDENTITY(1,1) NOT NULL
        , [SourceType] varchar(32) NOT NULL
        , [SourceObject] nvarchar(256) NOT NULL
        , [CapturedAtUtc] datetime2(3) NOT NULL
        , [StatusCode] varchar(40) NOT NULL
        , [IsPartial] bit NOT NULL
        , [ErrorNumber] int NULL
        , [Message] nvarchar(2048) NOT NULL
        , [EvidenceLimit] nvarchar(1000) NOT NULL
    );
    CREATE TABLE [#ServerVersionInformation_Console]
    (
          [Build] varchar(32) NULL
        , [Release] nvarchar(64) NULL
        , [ServicingBranch] varchar(16) NULL
        , [BuildStatus] varchar(40) NULL
        , [CatalogStatus] varchar(40) NULL
        , [LifecycleStatus] varchar(40) NULL
        , [MainstreamEndDate] date NULL
        , [ExtendedEndDate] date NULL
        , [LatestKnownBuildInBranch] varchar(32) NULL
        , [BuildOverviewUrl] nvarchar(512) NULL
        , [ModuleStatus] varchar(40) NOT NULL
        , [IsPartial] bit NOT NULL
    );

    SET LOCK_TIMEOUT 0;

    IF @MitDatenbankKompatibilitaet IS NULL OR @SystemdatenbankenEinbeziehen IS NULL
       OR @JsonErzeugen IS NULL OR @PrintMeldungen IS NULL
       OR @MaxZeilen<0 OR @OutputMode NOT IN('CONSOLE','RAW','TABLE','NONE')
       OR (@MitDatenbankKompatibilitaet=0 AND (@DatabaseNames IS NOT NULL OR @DatabaseNamePattern IS NOT NULL))
       OR (@DatabaseNames IS NOT NULL AND @DatabaseNamePattern IS NOT NULL)
       OR (@OutputMode<>'TABLE' AND NULLIF(LTRIM(RTRIM(COALESCE(@ResultTablesJson,N''))),N'') IS NOT NULL)
    BEGIN
        SELECT @StatusCode='INVALID_PARAMETER',@IsPartial=1,
               @ErrorMessage=N'Ungültiger Bit-, Zeilen-, Filter- oder Ausgabeparameter.';
    END;

    IF @StatusCode='AVAILABLE' AND @OutputMode='TABLE'
    BEGIN
        EXEC [monitor].[InternalPrepareResultTables]
              @ResultTablesJson=@ResultTablesJson
            , @AllowedResultNames=N'serverVersion|buildAssessment|lifecycle|instanceFeatures|databaseCompatibility|references|warnings'
            , @MappingTable=N'#ServerVersionInformation_ResultTableMap'
            , @StatusCode=@StatusCode OUTPUT
            , @ErrorMessage=@ErrorMessage OUTPUT
            , @ThrowOnError=1;
    END;

    IF @StatusCode='AVAILABLE'
    BEGIN
        INSERT [#ServerVersionInformation_ServerVersion]
        SELECT
              'SERVERPROPERTY',N'SERVERPROPERTY',@CapturedAtUtc,'INSTANCE',CONVERT(bit,1),'AVAILABLE'
            , CONVERT(varchar(32),SERVERPROPERTY(N'ProductVersion'))
            , TRY_CONVERT(int,SERVERPROPERTY(N'ProductMajorVersion'))
            , TRY_CONVERT(int,SERVERPROPERTY(N'ProductMinorVersion'))
            , TRY_CONVERT(int,SERVERPROPERTY(N'ProductBuild'))
            , TRY_CONVERT(int,PARSENAME(CONVERT(varchar(32),SERVERPROPERTY(N'ProductVersion')),1))
            , CONVERT(nvarchar(128),SERVERPROPERTY(N'ProductLevel'))
            , CONVERT(nvarchar(128),SERVERPROPERTY(N'ProductUpdateLevel'))
            , CONVERT(nvarchar(128),SERVERPROPERTY(N'ProductUpdateReference'))
            , CONVERT(nvarchar(128),SERVERPROPERTY(N'ProductBuildType'))
            , CONVERT(nvarchar(128),SERVERPROPERTY(N'ResourceVersion'))
            , TRY_CONVERT(datetime,SERVERPROPERTY(N'ResourceLastUpdateDateTime'))
            , CONVERT(nvarchar(128),SERVERPROPERTY(N'BuildClrVersion'))
            , CONVERT(nvarchar(128),SERVERPROPERTY(N'Edition'))
            , TRY_CONVERT(bigint,SERVERPROPERTY(N'EditionID'))
            , TRY_CONVERT(int,SERVERPROPERTY(N'EngineEdition'))
            , CASE TRY_CONVERT(int,SERVERPROPERTY(N'EngineEdition'))
                  WHEN 2 THEN 'STANDARD_CLASS' WHEN 3 THEN 'ENTERPRISE_CLASS'
                  WHEN 4 THEN 'EXPRESS_CLASS' WHEN 5 THEN 'AZURE_SQL_DATABASE'
                  WHEN 6 THEN 'SYNAPSE' WHEN 8 THEN 'AZURE_SQL_MI'
                  WHEN 9 THEN 'AZURE_SQL_EDGE' WHEN 11 THEN 'FABRIC_OR_SERVERLESS'
                  WHEN 12 THEN 'FABRIC_SQL_DATABASE' ELSE 'UNKNOWN_ENGINE_CLASS' END
            , NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL
            , TRY_CONVERT(int,SERVERPROPERTY(N'ProcessID'))
            , TRY_CONVERT(bit,SERVERPROPERTY(N'IsClustered'))
            , TRY_CONVERT(bit,SERVERPROPERTY(N'IsHadrEnabled'))
            , TRY_CONVERT(int,SERVERPROPERTY(N'HadrManagerStatus'))
            , TRY_CONVERT(bit,SERVERPROPERTY(N'IsLocalDB'))
            , CONVERT(sysname,SERVERPROPERTY(N'Collation'))
            , (SELECT [d].[collation_name] FROM [master].[sys].[databases] AS [d] WITH (NOLOCK) WHERE [d].[database_id]=2)
            , N'Direkte Instanzeigenschaften und leichter OS-Kontext; keine Serveridentität, Pfade, Konten oder Lizenzbehauptung.';

        BEGIN TRY
            UPDATE [v]
            SET [HostPlatform]=[h].[host_platform],
                [HostDistribution]=[h].[host_distribution],
                [HostRelease]=[h].[host_release],
                [HostServicePackLevel]=[h].[host_service_pack_level],
                [HostSku]=[h].[host_sku],
                [OsLanguageVersion]=[h].[os_language_version],
                [SqlServerStartTimeUtc]=[o].[sqlserver_start_time],
                [UptimeMilliseconds]=[o].[ms_ticks]
            FROM [#ServerVersionInformation_ServerVersion] AS [v]
            CROSS JOIN [sys].[dm_os_host_info] AS [h] WITH (NOLOCK)
            CROSS JOIN [sys].[dm_os_sys_info] AS [o] WITH (NOLOCK);
        END TRY
        BEGIN CATCH
            INSERT [#ServerVersionInformation_Warnings]
            SELECT 'LIVE_DMV',N'sys.dm_os_host_info|sys.dm_os_sys_info',@CapturedAtUtc,
                   CASE WHEN ERROR_NUMBER() IN(229,262,297,300,371) THEN 'DENIED_PERMISSION' ELSE 'ERROR_HANDLED' END,
                   CONVERT(bit,1),ERROR_NUMBER(),ERROR_MESSAGE(),
                   N'SERVERPROPERTY- und Offline-Katalogevidenz bleiben verfügbar; OS- und Startzeitkontext fehlt.';
            SET @IsPartial=1;
        END CATCH;

        INSERT [#ServerVersionInformation_BuildAssessment]
        SELECT
              'OFFLINE_CATALOG',N'monitor.SqlServerBuildCatalog',@CapturedAtUtc,'INSTANCE_BUILD'
            , CASE WHEN [v].[ProductLevel] LIKE N'CTP%' THEN 'PREVIEW_BUILD'
                   WHEN [v].[ProductBuildType]='OD' THEN 'ON_DEMAND_BUILD'
                   WHEN [exact].[BuildVersion] IS NOT NULL AND [exact].[IsLatestInBranch]=1 THEN 'EXACT_MATCH'
                   WHEN [exact].[BuildVersion] IS NOT NULL THEN 'OLDER_KNOWN_BUILD'
                   WHEN [latestMajor].[BuildVersion] IS NULL THEN 'UNKNOWN_BUILD'
                   WHEN [v].[ProductBuild]>[latestMajor].[BuildNumber]
                     OR ([v].[ProductBuild]=[latestMajor].[BuildNumber] AND [v].[ProductRevision]>[latestMajor].[RevisionNumber])
                     THEN 'BUILD_NEWER_THAN_OFFLINE_CATALOG'
                   ELSE 'UNKNOWN_BUILD' END
            , CASE WHEN DATEDIFF(DAY,[catalog].[CatalogAsOfDate],CONVERT(date,@CapturedAtUtc))>120 THEN 'CATALOG_STALE' ELSE 'CATALOG_CURRENT' END
            , [v].[ProductVersion],[exact].[ReleaseName],[exact].[ServicingBranch]
            , [exact].[KnowledgeBaseNumber],[exact].[ReleaseDate],[exact].[IsSecurityRelease]
            , [latestBranch].[BuildVersion],[latestMajor].[BuildVersion],[catalog].[CatalogAsOfDate]
            , COALESCE([exact].[BuildOverviewUrl],[latestMajor].[BuildOverviewUrl])
            , [exact].[KnowledgeBaseUrl]
            , N'Offline-Einordnung nach exakter Buildnummer und dokumentiertem Servicing-Zweig; kein Vulnerability-, Patchvollständigkeits-, Neustart- oder Freigabenachweis.'
        FROM [#ServerVersionInformation_ServerVersion] AS [v]
        LEFT JOIN [monitor].[SqlServerBuildCatalog] AS [exact] WITH (NOLOCK)
          ON [exact].[BuildVersion]=[v].[ProductVersion]
        OUTER APPLY
        (
            SELECT TOP(1) [c].[BuildVersion],[c].[BuildNumber],[c].[RevisionNumber],[c].[BuildOverviewUrl]
            FROM [monitor].[SqlServerBuildCatalog] AS [c] WITH (NOLOCK)
            WHERE [c].[ProductMajorVersion]=[v].[ProductMajorVersion]
            ORDER BY [c].[BuildNumber] DESC,[c].[RevisionNumber] DESC
        ) AS [latestMajor]
        OUTER APPLY
        (
            SELECT TOP(1) [c].[BuildVersion]
            FROM [monitor].[SqlServerBuildCatalog] AS [c] WITH (NOLOCK)
            WHERE [c].[ProductMajorVersion]=[v].[ProductMajorVersion]
              AND [c].[ServicingBranch]=[exact].[ServicingBranch]
              AND [c].[IsLatestInBranch]=1
            ORDER BY [c].[BuildNumber] DESC,[c].[RevisionNumber] DESC
        ) AS [latestBranch]
        OUTER APPLY
        (
            SELECT MAX([c].[CatalogAsOfDate]) AS [CatalogAsOfDate]
            FROM [monitor].[SqlServerBuildCatalog] AS [c] WITH (NOLOCK)
            WHERE [c].[ProductMajorVersion]=[v].[ProductMajorVersion]
        ) AS [catalog];

        INSERT [#ServerVersionInformation_Lifecycle]
        SELECT
              'OFFLINE_CATALOG',N'monitor.SqlServerLifecycleCatalog',@CapturedAtUtc,'PRODUCT_MAJOR_VERSION'
            , CASE WHEN [l].[ProductMajorVersion] IS NULL THEN 'UNKNOWN_LIFECYCLE'
                   WHEN CONVERT(date,@CapturedAtUtc)<[l].[StartDate] THEN 'NOT_YET_STARTED'
                   WHEN CONVERT(date,@CapturedAtUtc)<=[l].[MainstreamEndDate] THEN 'MAINSTREAM_SUPPORT'
                   WHEN CONVERT(date,@CapturedAtUtc)<=[l].[ExtendedEndDate] THEN 'EXTENDED_SUPPORT'
                   ELSE 'OUT_OF_SUPPORT' END
            , [v].[ProductMajorVersion],[l].[ProductName],[l].[StartDate]
            , [l].[MainstreamEndDate],[l].[ExtendedEndDate],[l].[LifecyclePolicy]
            , [l].[CatalogAsOfDate],[l].[LifecycleUrl]
            , N'Produktweiter Microsoft-Lifecycle; editions-, ESU-, Plattform- und organisationsspezifische Supportverträge bleiben unbewertet.'
        FROM [#ServerVersionInformation_ServerVersion] AS [v]
        LEFT JOIN [monitor].[SqlServerLifecycleCatalog] AS [l] WITH (NOLOCK)
          ON [l].[ProductMajorVersion]=[v].[ProductMajorVersion];

        INSERT [#ServerVersionInformation_InstanceFeatures]
        SELECT 'SERVERPROPERTY',N'SERVERPROPERTY',@CapturedAtUtc,'INSTANCE_FEATURE',
               [f].[FeatureName],[f].[FeatureValue],
               CASE WHEN [f].[FeatureValue] IS NULL THEN 'UNAVAILABLE_OR_NOT_APPLICABLE' ELSE 'AVAILABLE' END,
               N'SERVERPROPERTY-Flag; Installation oder Konfiguration beweist keine aktuelle Nutzung und keinen fehlerfreien Zustand.'
        FROM
        (
            VALUES
              (CONVERT(sysname,N'IsClustered'),TRY_CONVERT(int,SERVERPROPERTY(N'IsClustered')))
            , (CONVERT(sysname,N'IsHadrEnabled'),TRY_CONVERT(int,SERVERPROPERTY(N'IsHadrEnabled')))
            , (CONVERT(sysname,N'HadrManagerStatus'),TRY_CONVERT(int,SERVERPROPERTY(N'HadrManagerStatus')))
            , (CONVERT(sysname,N'IsLocalDB'),TRY_CONVERT(int,SERVERPROPERTY(N'IsLocalDB')))
            , (CONVERT(sysname,N'IsFullTextInstalled'),TRY_CONVERT(int,SERVERPROPERTY(N'IsFullTextInstalled')))
            , (CONVERT(sysname,N'IsPolyBaseInstalled'),TRY_CONVERT(int,SERVERPROPERTY(N'IsPolyBaseInstalled')))
            , (CONVERT(sysname,N'IsXTPSupported'),TRY_CONVERT(int,SERVERPROPERTY(N'IsXTPSupported')))
            , (CONVERT(sysname,N'IsAdvancedAnalyticsInstalled'),TRY_CONVERT(int,SERVERPROPERTY(N'IsAdvancedAnalyticsInstalled')))
            , (CONVERT(sysname,N'IsTempDbMetadataMemoryOptimized'),TRY_CONVERT(int,SERVERPROPERTY(N'IsTempDbMetadataMemoryOptimized')))
        ) AS [f]([FeatureName],[FeatureValue]);

        INSERT [#ServerVersionInformation_References]
        VALUES
          ('LATEST_UPDATES',NULL,N'Latest updates and version history for SQL Server',N'https://learn.microsoft.com/en-us/troubleshoot/sql/releases/download-and-install-latest-updates','2026-07-21')
        , ('SERVERPROPERTY',NULL,N'SERVERPROPERTY (Transact-SQL)',N'https://learn.microsoft.com/en-us/sql/t-sql/functions/serverproperty-transact-sql','2026-07-21')
        , ('BUILD_OVERVIEW',15,N'SQL Server 2019 build versions',N'https://learn.microsoft.com/en-us/troubleshoot/sql/releases/sqlserver-2019/build-versions','2026-07-21')
        , ('BUILD_OVERVIEW',16,N'SQL Server 2022 build versions',N'https://learn.microsoft.com/en-us/troubleshoot/sql/releases/sqlserver-2022/build-versions','2026-07-21')
        , ('BUILD_OVERVIEW',17,N'SQL Server 2025 build versions',N'https://learn.microsoft.com/en-us/troubleshoot/sql/releases/sqlserver-2025/build-versions','2026-07-21');

        IF EXISTS
        (
            SELECT 1 FROM [#ServerVersionInformation_BuildAssessment]
            WHERE [AssessmentStatus] NOT IN('EXACT_MATCH','OLDER_KNOWN_BUILD')
               OR [CatalogFreshnessStatus]='CATALOG_STALE'
        )
            INSERT [#ServerVersionInformation_Warnings]
            SELECT 'OFFLINE_CATALOG',N'monitor.SqlServerBuildCatalog',@CapturedAtUtc,
                   [AssessmentStatus],CONVERT(bit,0),NULL,
                   N'Die Buildnummer ist nicht als aktueller exakter Katalogtreffer einordenbar; die verlinkte Microsoft-Buildübersicht ist vor einer Patchentscheidung zu prüfen.',
                   [EvidenceLimit]
            FROM [#ServerVersionInformation_BuildAssessment]
            WHERE [AssessmentStatus] NOT IN('EXACT_MATCH','OLDER_KNOWN_BUILD')
               OR [CatalogFreshnessStatus]='CATALOG_STALE';

        IF @MitDatenbankKompatibilitaet=1
        BEGIN
            DECLARE @CrossDatabaseRequested bit=0;
            EXEC [monitor].[USP_PrepareDatabaseCandidates]
                  @DatabaseNames=@DatabaseNames
                , @SystemdatenbankenEinbeziehen=@SystemdatenbankenEinbeziehen
                , @DatabaseNamePattern=@DatabaseNamePattern
                , @AnalysisClass='STANDARD_CURRENT'
                , @StatusCode=@StatusCode OUTPUT
                , @ErrorMessage=@ErrorMessage OUTPUT
                , @CrossDatabaseRequested=@CrossDatabaseRequested OUTPUT
                , @CandidateTable=N'#ServerVersionInformation_DatabaseCandidates'
                , @WarningTable=N'#ServerVersionInformation_CandidateWarnings';

            INSERT [#ServerVersionInformation_DatabaseCompatibility]
            SELECT TOP(@Limit) 'SYSTEM_CATALOG',N'master.sys.databases',@CapturedAtUtc,'VISIBLE_DATABASE',
                   CONVERT(bit,1),'AVAILABLE',[DatabaseId],[DatabaseName],[CompatibilityLevel],
                   [CollationName],[StateDesc],[IsReadOnly],[IsSystemDatabase],
                   N'Sichtbarer aktueller Katalogzustand; keine datenbanklokale Abfrage und keine Aussage zur Workload-Eignung des Compatibility Levels.'
            FROM [#ServerVersionInformation_DatabaseCandidates]
            ORDER BY COALESCE([RequestedOrdinal],[DatabaseId]),[DatabaseId];

            INSERT [#ServerVersionInformation_Warnings]
            SELECT 'SYSTEM_CATALOG',N'master.sys.databases',@CapturedAtUtc,[StatusCode],
                   CONVERT(bit,1),NULL,[ErrorMessage],
                   N'Explizit angeforderter Datenbankkontext war nicht sichtbar, nicht zugreifbar oder ohne Opt-in ausgeschlossen.'
            FROM [#ServerVersionInformation_CandidateWarnings];
        END;
    END;

    IF EXISTS(SELECT 1 FROM [#ServerVersionInformation_Warnings] WHERE [IsPartial]=1)
    BEGIN
        SET @IsPartial=1;
        IF @StatusCode='AVAILABLE' SET @StatusCode='AVAILABLE_LIMITED';
    END;

    SELECT TOP(1) @ErrorNumber=COALESCE(@ErrorNumber,[ErrorNumber]),
                  @ErrorMessage=COALESCE(@ErrorMessage,[Message])
    FROM [#ServerVersionInformation_Warnings]
    WHERE [IsPartial]=1
    ORDER BY [WarningOrdinal];

    IF @JsonErzeugen=1
    BEGIN
        DECLARE @MetaJson nvarchar(max)=(SELECT N'ServerVersionInformation' [resultName],1 [schemaVersion],@CapturedAtUtc [generatedAtUtc],@StatusCode [statusCode],@IsPartial [isPartial],@ErrorNumber [errorNumber],@ErrorMessage [errorMessage] FOR JSON PATH,WITHOUT_ARRAY_WRAPPER,INCLUDE_NULL_VALUES);
        DECLARE @ServerJson nvarchar(max)=(SELECT * FROM [#ServerVersionInformation_ServerVersion] FOR JSON PATH,INCLUDE_NULL_VALUES);
        DECLARE @BuildJson nvarchar(max)=(SELECT * FROM [#ServerVersionInformation_BuildAssessment] FOR JSON PATH,INCLUDE_NULL_VALUES);
        DECLARE @LifecycleJson nvarchar(max)=(SELECT * FROM [#ServerVersionInformation_Lifecycle] FOR JSON PATH,INCLUDE_NULL_VALUES);
        DECLARE @FeaturesJson nvarchar(max)=(SELECT * FROM [#ServerVersionInformation_InstanceFeatures] ORDER BY [FeatureName] FOR JSON PATH,INCLUDE_NULL_VALUES);
        DECLARE @DatabasesJson nvarchar(max)=(SELECT TOP(@Limit) * FROM [#ServerVersionInformation_DatabaseCompatibility] ORDER BY [DatabaseName] FOR JSON PATH,INCLUDE_NULL_VALUES);
        DECLARE @ReferencesJson nvarchar(max)=(SELECT * FROM [#ServerVersionInformation_References] ORDER BY [ReferenceType],[ProductMajorVersion] FOR JSON PATH,INCLUDE_NULL_VALUES);
        DECLARE @WarningsJson nvarchar(max)=(SELECT * FROM [#ServerVersionInformation_Warnings] ORDER BY [WarningOrdinal] FOR JSON PATH,INCLUDE_NULL_VALUES);
        SET @Json=CONCAT(N'{"meta":',COALESCE(@MetaJson,N'{}'),N',"serverVersion":',COALESCE(@ServerJson,N'[]'),N',"buildAssessment":',COALESCE(@BuildJson,N'[]'),N',"lifecycle":',COALESCE(@LifecycleJson,N'[]'),N',"instanceFeatures":',COALESCE(@FeaturesJson,N'[]'),N',"databaseCompatibility":',COALESCE(@DatabasesJson,N'[]'),N',"references":',COALESCE(@ReferencesJson,N'[]'),N',"warnings":',COALESCE(@WarningsJson,N'[]'),N'}');
    END;

    IF @ConsoleResultRequested=1
    BEGIN
        INSERT [#ServerVersionInformation_Console]
        SELECT [b].[ProductVersion],[b].[KnownReleaseName],[b].[ServicingBranch],
               [b].[AssessmentStatus],[b].[CatalogFreshnessStatus],
               [l].[LifecycleStatus],[l].[MainstreamEndDate],[l].[ExtendedEndDate],
               [b].[LatestKnownBuildInBranch],[b].[BuildOverviewUrl],
               @StatusCode,@IsPartial
        FROM [#ServerVersionInformation_BuildAssessment] AS [b]
        CROSS JOIN [#ServerVersionInformation_Lifecycle] AS [l];

        EXEC [monitor].[InternalEmitConsoleResult]
              @SourceTable=N'#ServerVersionInformation_Console'
            , @ResultLabel=N'Serverversion'
            , @EmptyMessage=N'Keine Serverversionsinformation';
    END
    ELSE IF @OutputMode='RAW'
    BEGIN
        SELECT * FROM [#ServerVersionInformation_ServerVersion];
        SELECT * FROM [#ServerVersionInformation_BuildAssessment];
        SELECT * FROM [#ServerVersionInformation_Lifecycle];
        SELECT * FROM [#ServerVersionInformation_InstanceFeatures] ORDER BY [FeatureName];
        SELECT TOP(@Limit) * FROM [#ServerVersionInformation_DatabaseCompatibility] ORDER BY [DatabaseName];
        SELECT * FROM [#ServerVersionInformation_References] ORDER BY [ReferenceType],[ProductMajorVersion];
        SELECT * FROM [#ServerVersionInformation_Warnings] ORDER BY [WarningOrdinal];
    END
    ELSE IF @OutputMode='TABLE'
    BEGIN
        DECLARE @TargetTable sysname;
        DECLARE [ResultCursor] CURSOR LOCAL FAST_FORWARD FOR
            SELECT [ResultName],[TargetTable]
            FROM [#ServerVersionInformation_ResultTableMap]
            ORDER BY [ResultName];
        DECLARE @ResultName sysname;
        OPEN [ResultCursor];
        FETCH NEXT FROM [ResultCursor] INTO @ResultName,@TargetTable;
        WHILE @@FETCH_STATUS=0
        BEGIN
            DECLARE @SourceTable sysname=CASE @ResultName
                WHEN N'serverVersion' THEN N'#ServerVersionInformation_ServerVersion'
                WHEN N'buildAssessment' THEN N'#ServerVersionInformation_BuildAssessment'
                WHEN N'lifecycle' THEN N'#ServerVersionInformation_Lifecycle'
                WHEN N'instanceFeatures' THEN N'#ServerVersionInformation_InstanceFeatures'
                WHEN N'databaseCompatibility' THEN N'#ServerVersionInformation_DatabaseCompatibility'
                WHEN N'references' THEN N'#ServerVersionInformation_References'
                WHEN N'warnings' THEN N'#ServerVersionInformation_Warnings' END;
            EXEC [monitor].[InternalWriteResultTable]
                  @SourceTable=@SourceTable,@TargetTable=@TargetTable,@ThrowOnError=1;
            FETCH NEXT FROM [ResultCursor] INTO @ResultName,@TargetTable;
        END;
        CLOSE [ResultCursor];
        DEALLOCATE [ResultCursor];
    END;

    IF @PrintMeldungen=1 AND @StatusCode NOT IN('AVAILABLE')
    BEGIN
        DECLARE @PrintMessage nvarchar(2048)=LEFT(CONCAT(N'USP_ServerVersionInformation: ',@StatusCode,N'. ',COALESCE(@ErrorMessage,N'Siehe warnings-Resultset.')),2048);
        RAISERROR(N'%s',10,1,@PrintMessage) WITH NOWAIT;
    END;

    SELECT @StatusCodeOut=@StatusCode,@IsPartialOut=@IsPartial,
           @ErrorNumberOut=@ErrorNumber,@ErrorMessageOut=@ErrorMessage;
END;
GO
-- END SOURCE: Code/09_VersionAdaptive/015_USP_ServerVersionInformation.sql

-- BEGIN SOURCE: Code/09_VersionAdaptive/020_USP_SpecialFeatureInventory.sql
/*
===============================================================================
Objekt       : monitor.USP_SpecialFeatureInventory
Version      : 1.2.0
Stand        : 2026-07-23
Typ          : Stored Procedure
Zweck        : Inventarisiert leichtgewichtig die im sichtbaren Metadatenscope
               genutzten oder lediglich konfigurierten SQL-Server-
               Spezialfeatures und verweist auf passende Deep-Dive-Module.
SQL-Version  : SQL Server 2019 oder neuer.
Datenquellen : Datenbank- und Objektkataloge für In-Memory OLTP, Temporal,
               Service Broker, Full-Text, Data Capture, Verschlüsselung, CLR,
               External Tables/Runtimes, FILESTREAM, Graph, Spatial, XML,
               native JSON-/Vector-Typen und benutzerdefinierte Typen.
Abgrenzung   : Das Ergebnis ist ein Nutzungsinventar, kein Gesundheitsurteil.
               Nicht sichtbare Metadaten können zu Nullzählungen führen.
               Externe Locations, Credentials, Service-Broker-Payloads,
               CLR-Binaries und Moduldefinitionen werden nicht gelesen.
Kosten       : LOW. Ausschließlich aggregierte Systemkatalogabfragen; keine
               Benutzertabellen-, Payload-, Definitions- oder Datenscans.
Locking      : Der angeforderte LOCK_TIMEOUT gilt für die Katalogpfade; der
               vorherige Sessionwert wird vor der Ausgabe wiederhergestellt.
Änderungen   : 1.2.0 - Native-JSON-Erkennung auf das implementierte
                         JSON-Indexinventar in USP_ObjectInventory geroutet.
===============================================================================
*/
CREATE OR ALTER PROCEDURE [monitor].[USP_SpecialFeatureInventory]
      @DatabaseNames                    nvarchar(max)  = NULL
    , @SystemdatenbankenEinbeziehen     bit            = 0
    , @DatabaseNamePattern              nvarchar(4000) = NULL
    , @HighImpactConfirmed              bit            = 0
    , @NurErkannteFeatures              bit            = 0
    , @MaxZeilen                        int            = 2000
    , @LockTimeoutMs                    int            = 0
    , @ResultSetArt                     varchar(16)     = 'CONSOLE'
    , @ResultTablesJson               nvarchar(max) = NULL
    , @JsonErzeugen                     bit            = 0
    , @Json                             nvarchar(max)   = NULL OUTPUT
    , @PrintMeldungen                   bit            = 1
    , @Hilfe                            bit            = 0
    , @StatusCodeOut                    varchar(40)     = NULL OUTPUT
    , @IsPartialOut                     bit            = NULL OUTPUT
    , @ErrorNumberOut                   int            = NULL OUTPUT
    , @ErrorMessageOut                  nvarchar(2048)  = NULL OUTPUT
AS
BEGIN
    SET NOCOUNT ON;
    SET @Json = NULL;
    DECLARE @OriginalLockTimeout int=@@LOCK_TIMEOUT;
    DECLARE @LockTimeoutSql nvarchar(64);

    DECLARE @OutputMode varchar(16)=UPPER(LTRIM(RTRIM(COALESCE(@ResultSetArt,''))));
    DECLARE @TableResultRequested bit = CASE WHEN @OutputMode = 'TABLE' THEN 1 ELSE 0 END;
    DECLARE @ConsoleResultRequested bit = CASE WHEN @OutputMode = 'CONSOLE' THEN 1 ELSE 0 END;
    DECLARE @TableTarget sysname=NULL;
    IF @TableResultRequested=0 AND NULLIF(LTRIM(RTRIM(COALESCE(@ResultTablesJson,N''))),N'') IS NOT NULL THROW 51011,N'@ResultTablesJson ist ausschließlich mit @ResultSetArt=TABLE zulässig.',1;
    IF @TableResultRequested=1 EXEC [monitor].[InternalPrepareSingleResultTable] @ResultTablesJson=@ResultTablesJson,@ResultName=N'features',@TargetTable=@TableTarget OUTPUT,@ThrowOnError=1;
    IF @TableResultRequested = 1 OR @ConsoleResultRequested = 1 SET @OutputMode = 'NONE';
    DECLARE @Now datetime2(3)=SYSUTCDATETIME();
    DECLARE @Major int=TRY_CONVERT(int,SERVERPROPERTY(N'ProductMajorVersion'));
    DECLARE @StatusCode varchar(40)='AVAILABLE';
    DECLARE @IsPartial bit=0;
    DECLARE @ErrorNumber int=NULL;
    DECLARE @ErrorMessage nvarchar(2048)=NULL;
    DECLARE @PrintMessage nvarchar(2048);
    DECLARE @Limit bigint=CASE WHEN @MaxZeilen IS NULL OR @MaxZeilen=0
                               THEN CONVERT(bigint,9223372036854775807)
                               WHEN @MaxZeilen<0 THEN CONVERT(bigint,0)
                               ELSE CONVERT(bigint,@MaxZeilen) END;
    DECLARE @ExternalScriptsConfigured bit=NULL;
    DECLARE @ExternalScriptsConfigurationAvailable bit=1;

    IF @Hilfe=1
    BEGIN
        PRINT N'monitor.USP_SpecialFeatureInventory';
        PRINT N'Die Procedure führt eine leichtgewichtige Nutzungsinventur sichtbarer Spezialfeature-Metadaten durch und gibt kein Gesundheitsurteil ab.';
        PRINT N'@DatabaseNames=N''[Db1]|[Db2]''; NULL=alle; N'''' bedeutet keine Einschränkung. Pattern separat.';
        PRINT N'@NurErkannteFeatures=1 unterdrückt NOT_DETECTED_VISIBLE_SCOPE und UNAVAILABLE_VERSION in der Ausgabe.';
        PRINT N'Die Datenbankauswahl wird nicht vorab begrenzt; ein positiver Wert in @MaxZeilen begrenzt die Ausgaben, während NULL oder 0 keine Begrenzung setzt.';
        PRINT N'@ResultSetArt=CONSOLE|RAW|TABLE|NONE; TABLE verwendet @ResultTablesJson; @JsonErzeugen=1 erzeugt @Json OUTPUT.';
        PRINT N'Keine externen Locations, Credentials, Payloads, CLR-Binaries oder Moduldefinitionen werden gelesen.';
        PRINT N'Für native JSON-Spalten verweist das Inventar auf USP_ObjectInventory; dort werden capability-adaptiv JSON-Index- und Pfadmetadaten gelesen, jedoch keine JSON-Dokumentwerte.';
        RETURN;
    END;

    IF @SystemdatenbankenEinbeziehen IS NULL OR @NurErkannteFeatures IS NULL
       OR @JsonErzeugen IS NULL OR @PrintMeldungen IS NULL
 OR @MaxZeilen<0
       OR @LockTimeoutMs IS NULL OR @LockTimeoutMs NOT BETWEEN 0 AND 60000
       OR @OutputMode NOT IN ('RAW','CONSOLE','NONE')
    BEGIN
        SELECT @StatusCode='INVALID_PARAMETER',@IsPartial=1,
               @ErrorMessage=N'Ungültiger Bit-, Mengen-, Lock-Timeout- oder Ausgabeparameter.';
    END;

    IF @StatusCode='AVAILABLE'
    BEGIN
        SET @LockTimeoutSql=N'SET LOCK_TIMEOUT '+CONVERT(nvarchar(20),@LockTimeoutMs)+N';';
        EXEC [sys].[sp_executesql] @LockTimeoutSql;
    END;

    BEGIN TRY
        SELECT @ExternalScriptsConfigured=CONVERT(bit,[value_in_use])
        FROM [sys].[configurations] WITH (NOLOCK)
        WHERE [name]=N'external scripts enabled';
    END TRY
    BEGIN CATCH
        SET @ExternalScriptsConfigured=NULL;
        SET @ExternalScriptsConfigurationAvailable=0;
    END CATCH;

    CREATE TABLE [#SpecialFeatureInventory_DatabaseCandidates]
    (
          [DatabaseId] int NOT NULL
        , [DatabaseName] sysname COLLATE SQL_Latin1_General_CP1_CS_AS NOT NULL
        , [StateDesc] nvarchar(60) NULL
        , [UserAccessDesc] nvarchar(60) NULL
        , [IsReadOnly] bit NULL
        , [CompatibilityLevel] tinyint NULL
        , [CollationName] sysname NULL
        , [RecoveryModelDesc] nvarchar(60) NULL
        , [IsSystemDatabase] bit NULL
        , [RequestedOrdinal] int NULL
    );
    CREATE TABLE [#SpecialFeatureInventory_DatabaseCandidateWarnings]
    (
          [RequestedName] sysname COLLATE SQL_Latin1_General_CP1_CS_AS NULL
        , [StatusCode] varchar(40) NOT NULL
        , [ErrorMessage] nvarchar(2048) NOT NULL
    );
    CREATE TABLE [#SpecialFeatureInventory_DatabaseStatus]
    (
          [DatabaseName] sysname COLLATE SQL_Latin1_General_CP1_CS_AS NULL
        , [StatusCode] varchar(40) NOT NULL
        , [IsPartial] bit NOT NULL
        , [FeatureRows] bigint NOT NULL
        , [DetectedFeatureRows] bigint NOT NULL
        , [ErrorNumber] int NULL
        , [ErrorMessage] nvarchar(2048) NULL
        , [Detail] nvarchar(1000) NULL
    );
    CREATE TABLE [#SpecialFeatureInventory_FeatureInventory]
    (
          [DatabaseName] sysname COLLATE SQL_Latin1_General_CP1_CS_AS NOT NULL
        , [FeatureCode] varchar(64) NOT NULL
        , [FeatureFamily] nvarchar(120) NOT NULL
        , [DetectionStatus] varchar(40) NOT NULL
        , [DetectedItemCount] bigint NULL
        , [ConfigurationState] nvarchar(120) NULL
        , [SourceObjects] nvarchar(1000) NOT NULL
        , [RecommendedModule] sysname NULL
        , [RecommendedModuleStatus] varchar(40) NOT NULL
        , [EvidenceLimit] nvarchar(1000) NOT NULL
    );

    DECLARE @CrossDatabaseRequested bit=0;
    IF @StatusCode='AVAILABLE'
    BEGIN
        EXEC [monitor].[USP_PrepareDatabaseCandidates]
              @DatabaseNames=@DatabaseNames
            , @SystemdatenbankenEinbeziehen=@SystemdatenbankenEinbeziehen
            , @DatabaseNamePattern=@DatabaseNamePattern,@HighImpactConfirmed=@HighImpactConfirmed

            , @AnalysisClass=NULL
            , @StatusCode=@StatusCode OUTPUT
            , @ErrorMessage=@ErrorMessage OUTPUT
            , @CrossDatabaseRequested=@CrossDatabaseRequested OUTPUT,@CandidateTable=N'#SpecialFeatureInventory_DatabaseCandidates',@WarningTable=N'#SpecialFeatureInventory_DatabaseCandidateWarnings';
    END;

    INSERT [#SpecialFeatureInventory_DatabaseStatus]
    ([DatabaseName],[StatusCode],[IsPartial],[FeatureRows],[DetectedFeatureRows],[ErrorNumber],[ErrorMessage],[Detail])
    SELECT [DatabaseName],'AVAILABLE',0,0,0,NULL,NULL,
           N'Aggregierte, sichtbare Katalogmetadaten; eine Nullzählung beweist keine Feature-Abwesenheit.'
    FROM [#SpecialFeatureInventory_DatabaseCandidates];

    INSERT [#SpecialFeatureInventory_DatabaseStatus]
    ([DatabaseName],[StatusCode],[IsPartial],[FeatureRows],[DetectedFeatureRows],[ErrorNumber],[ErrorMessage],[Detail])
    SELECT [RequestedName],[StatusCode],1,0,0,NULL,[ErrorMessage],N'Explizit angeforderte Datenbank nicht auswertbar.'
    FROM [#SpecialFeatureInventory_DatabaseCandidateWarnings];

    IF @StatusCode='AVAILABLE' AND NOT EXISTS(SELECT 1 FROM [#SpecialFeatureInventory_DatabaseCandidates])
    BEGIN
        SET @StatusCode='NOT_APPLICABLE';
        SET @ErrorMessage=N'Keine auswertbare Datenbank im gewählten Scope.';
    END;

    IF @StatusCode='AVAILABLE'
    BEGIN
        DECLARE @DbName sysname,@Sql nvarchar(max);
        DECLARE [DatabaseCursor] CURSOR LOCAL FAST_FORWARD FOR
            SELECT [DatabaseName]
            FROM [#SpecialFeatureInventory_DatabaseCandidates]
            ORDER BY COALESCE([RequestedOrdinal],[DatabaseId]),[DatabaseId];
        OPEN [DatabaseCursor];
        FETCH NEXT FROM [DatabaseCursor] INTO @DbName;

        WHILE @@FETCH_STATUS=0
        BEGIN
            BEGIN TRY
                SET @Sql=N'SET LOCK_TIMEOUT '+CONVERT(nvarchar(11),@LockTimeoutMs)+N'; USE '+QUOTENAME(@DbName)+N';
DECLARE @MemoryOptimized bigint=0,@Temporal bigint=0,@Broker bigint=0,@FullText bigint=0;
DECLARE @ChangeTracking bigint=0,@Cdc bigint=0,@Encryption bigint=0,@Clr bigint=0;
DECLARE @ExternalTables bigint=0,@ExternalRuntime bigint=0,@FileStream bigint=0,@Graph bigint=0;
DECLARE @Spatial bigint=0,@Xml bigint=0,@NativeJson bigint=0,@Vector bigint=0,@UserTypes bigint=0;
DECLARE @BrokerEnabled bit=0,@CdcEnabled bit=0,@Encrypted bit=0;

SELECT @BrokerEnabled=COALESCE([is_broker_enabled],0),
       @CdcEnabled=COALESCE([is_cdc_enabled],0),
       @Encrypted=COALESCE([is_encrypted],0)
FROM [sys].[databases] WITH (NOLOCK)
WHERE [database_id]=DB_ID();

SELECT @MemoryOptimized=COUNT_BIG(*)
FROM [sys].[tables] WITH (NOLOCK)
WHERE [is_ms_shipped]=0 AND [is_memory_optimized]=1;
SELECT @MemoryOptimized=@MemoryOptimized+COUNT_BIG(*)
FROM [sys].[filegroups] WITH (NOLOCK)
WHERE [type]=''FX'';

SELECT @Temporal=COUNT_BIG(*)
FROM [sys].[tables] WITH (NOLOCK)
WHERE [is_ms_shipped]=0 AND [temporal_type]=2;

SELECT @Broker=COUNT_BIG(*)
FROM [sys].[service_queues] WITH (NOLOCK)
WHERE [is_ms_shipped]=0;
SELECT @Broker=@Broker+COUNT_BIG(*)
FROM [sys].[services] [svc] WITH (NOLOCK)
JOIN [sys].[service_queues] [q] WITH (NOLOCK) ON [q].[object_id]=[svc].[service_queue_id]
WHERE [q].[is_ms_shipped]=0;
SET @Broker=@Broker+CONVERT(bigint,@BrokerEnabled);

SELECT @FullText=COUNT_BIG(*) FROM [sys].[fulltext_catalogs] WITH (NOLOCK);
SELECT @FullText=@FullText+COUNT_BIG(*) FROM [sys].[fulltext_indexes] WITH (NOLOCK);

SELECT @ChangeTracking=COUNT_BIG(*) FROM [sys].[change_tracking_tables] WITH (NOLOCK);
SELECT @ChangeTracking=@ChangeTracking+COUNT_BIG(*)
FROM [sys].[change_tracking_databases] WITH (NOLOCK)
WHERE [database_id]=DB_ID();

SELECT @Cdc=COUNT_BIG(*)
FROM [sys].[tables] WITH (NOLOCK)
WHERE [is_ms_shipped]=0 AND [is_tracked_by_cdc]=1;
SET @Cdc=@Cdc+CONVERT(bigint,@CdcEnabled);

SELECT @Encryption=COUNT_BIG(*)
FROM [sys].[columns] [c] WITH (NOLOCK)
JOIN [sys].[objects] [o] WITH (NOLOCK) ON [o].[object_id]=[c].[object_id]
WHERE [o].[is_ms_shipped]=0 AND [c].[encryption_type] IS NOT NULL;
SELECT @Encryption=@Encryption+COUNT_BIG(*) FROM [sys].[column_master_keys] WITH (NOLOCK);
SELECT @Encryption=@Encryption+COUNT_BIG(*) FROM [sys].[column_encryption_keys] WITH (NOLOCK);
SET @Encryption=@Encryption+CONVERT(bigint,@Encrypted);

SELECT @Clr=COUNT_BIG(*)
FROM [sys].[assemblies] WITH (NOLOCK)
WHERE [is_user_defined]=1;

SELECT @ExternalTables=COUNT_BIG(*) FROM [sys].[external_tables] WITH (NOLOCK);
SELECT @ExternalTables=@ExternalTables+COUNT_BIG(*) FROM [sys].[external_data_sources] WITH (NOLOCK);

SELECT @ExternalRuntime=COUNT_BIG(*) FROM [sys].[external_languages] WITH (NOLOCK);
SELECT @ExternalRuntime=@ExternalRuntime+COUNT_BIG(*) FROM [sys].[external_libraries] WITH (NOLOCK);

SELECT @FileStream=COUNT_BIG(*)
FROM [sys].[columns] [c] WITH (NOLOCK)
JOIN [sys].[objects] [o] WITH (NOLOCK) ON [o].[object_id]=[c].[object_id]
WHERE [o].[is_ms_shipped]=0 AND [c].[is_filestream]=1;
SELECT @FileStream=@FileStream+COUNT_BIG(*)
FROM [sys].[tables] WITH (NOLOCK)
WHERE [is_ms_shipped]=0 AND [is_filetable]=1;

SELECT @Graph=COUNT_BIG(*)
FROM [sys].[tables] WITH (NOLOCK)
WHERE [is_ms_shipped]=0 AND ([is_node]=1 OR [is_edge]=1);

SELECT @Spatial=COUNT_BIG(*)
FROM [sys].[columns] [c] WITH (NOLOCK)
JOIN [sys].[objects] [o] WITH (NOLOCK) ON [o].[object_id]=[c].[object_id]
JOIN [sys].[types] [t] WITH (NOLOCK) ON [t].[user_type_id]=[c].[user_type_id]
WHERE [o].[is_ms_shipped]=0 AND [o].[type] IN (''U'',''V'') AND [t].[name] IN (N''geometry'',N''geography'');

SELECT @Xml=COUNT_BIG(*)
FROM [sys].[columns] [c] WITH (NOLOCK)
JOIN [sys].[objects] [o] WITH (NOLOCK) ON [o].[object_id]=[c].[object_id]
JOIN [sys].[types] [t] WITH (NOLOCK) ON [t].[user_type_id]=[c].[user_type_id]
WHERE [o].[is_ms_shipped]=0 AND [o].[type] IN (''U'',''V'') AND [t].[name]=N''xml'';
SELECT @Xml=@Xml+COUNT_BIG(*) FROM [sys].[xml_indexes] WITH (NOLOCK);

SELECT @NativeJson=COUNT_BIG(*)
FROM [sys].[columns] [c] WITH (NOLOCK)
JOIN [sys].[objects] [o] WITH (NOLOCK) ON [o].[object_id]=[c].[object_id]
JOIN [sys].[types] [t] WITH (NOLOCK) ON [t].[user_type_id]=[c].[user_type_id]
WHERE [o].[is_ms_shipped]=0 AND [o].[type] IN (''U'',''V'')
  AND [t].[name]=N''json'' AND [t].[is_user_defined]=0;

SELECT @Vector=COUNT_BIG(*)
FROM [sys].[columns] [c] WITH (NOLOCK)
JOIN [sys].[objects] [o] WITH (NOLOCK) ON [o].[object_id]=[c].[object_id]
JOIN [sys].[types] [t] WITH (NOLOCK) ON [t].[user_type_id]=[c].[user_type_id]
WHERE [o].[is_ms_shipped]=0 AND [o].[type] IN (''U'',''V'')
  AND [t].[name]=N''vector'' AND [t].[is_user_defined]=0;

SELECT @UserTypes=COUNT_BIG(*)
FROM [sys].[types] WITH (NOLOCK)
WHERE [is_user_defined]=1;

INSERT [#SpecialFeatureInventory_FeatureInventory]
([DatabaseName],[FeatureCode],[FeatureFamily],[DetectionStatus],[DetectedItemCount],[ConfigurationState],[SourceObjects],[RecommendedModule],[RecommendedModuleStatus],[EvidenceLimit])
VALUES
((SELECT [name] FROM [master].[sys].[databases] WITH (NOLOCK) WHERE [database_id] = DB_ID()),''IN_MEMORY_OLTP'',N''In-Memory OLTP'',CASE WHEN @MemoryOptimized>0 THEN ''DETECTED'' ELSE ''NOT_DETECTED_VISIBLE_SCOPE'' END,@MemoryOptimized,NULL,N''sys.tables|sys.filegroups'',N''USP_InMemoryOltpAnalysis'',''IMPLEMENTED'',N''Gezählt werden sichtbare memory-optimized Tabellen und XTP-Dateigruppen; Zustand und Speicherverbrauch sind erst im getrennten Deep-Dive-Modul bewertet.''),
((SELECT [name] FROM [master].[sys].[databases] WITH (NOLOCK) WHERE [database_id] = DB_ID()),''TEMPORAL'',N''Temporal Tables'',CASE WHEN @Temporal>0 THEN ''DETECTED'' ELSE ''NOT_DETECTED_VISIBLE_SCOPE'' END,@Temporal,NULL,N''sys.tables'',N''USP_TemporalAnalysis'',''IMPLEMENTED'',N''Gezählt werden sichtbare systemversionierte Current-Tabellen; Zuordnung, Retention, approximative Kapazität und Indexbaseline liegen im getrennten Deep-Dive-Modul, nicht jedoch ein Nachweis der Zeilenkonsistenz.''),
((SELECT [name] FROM [master].[sys].[databases] WITH (NOLOCK) WHERE [database_id] = DB_ID()),''SERVICE_BROKER'',N''Service Broker'',CASE WHEN @Broker>0 THEN ''DETECTED'' ELSE ''NOT_DETECTED_VISIBLE_SCOPE'' END,@Broker,CASE WHEN @BrokerEnabled=1 THEN N''ENABLED'' ELSE N''DISABLED'' END,N''sys.databases|sys.service_queues|sys.services'',N''USP_ServiceBrokerAnalysis'',''IMPLEMENTED'',N''Broker-Aktivierung und sichtbare Objekte werden gezählt; Queue-Schalter, approximative Kapazität, Aktivierungs-DMVs, Transmission und Conversation-Zustände liegen im getrennten Deep-Dive-Modul, Nachrichtenkörper bleiben ausgeschlossen.''),
((SELECT [name] FROM [master].[sys].[databases] WITH (NOLOCK) WHERE [database_id] = DB_ID()),''FULL_TEXT'',N''Full-Text'',CASE WHEN @FullText>0 THEN ''DETECTED'' ELSE ''NOT_DETECTED_VISIBLE_SCOPE'' END,@FullText,NULL,N''sys.fulltext_catalogs|sys.fulltext_indexes'',N''USP_FullTextAnalysis'',''IMPLEMENTED'',N''Kataloge und Indizes werden gezählt; isolierte Population-, Batch-, Fragment-, Semantik- und serverweite Laufzeitevidenz liegt im getrennten Deep-Dive-Modul, Inhalte und Crawl-Logs bleiben ausgeschlossen.''),
((SELECT [name] FROM [master].[sys].[databases] WITH (NOLOCK) WHERE [database_id] = DB_ID()),''CHANGE_TRACKING'',N''Change Tracking'',CASE WHEN @ChangeTracking>0 THEN ''DETECTED'' ELSE ''NOT_DETECTED_VISIBLE_SCOPE'' END,@ChangeTracking,NULL,N''sys.change_tracking_databases|sys.change_tracking_tables'',N''USP_DataCaptureDeepAnalysis'',''IMPLEMENTED'',N''Datenbank- und Tabellenmetadaten werden gezählt; das Deep-Dive-Modul bewertet MinValidVersion nur gegen einen explizit gelieferten Consumer-Wasserstand.''),
((SELECT [name] FROM [master].[sys].[databases] WITH (NOLOCK) WHERE [database_id] = DB_ID()),''CDC'',N''Change Data Capture'',CASE WHEN @Cdc>0 THEN ''DETECTED'' ELSE ''NOT_DETECTED_VISIBLE_SCOPE'' END,@Cdc,CASE WHEN @CdcEnabled=1 THEN N''ENABLED'' ELSE N''DISABLED'' END,N''sys.databases|sys.tables'',N''USP_DataCaptureDeepAnalysis'',''IMPLEMENTED'',N''CDC-Aktivierung und sichtbare erfasste Tabellen werden gezählt; isolierte Scan-, Fehler-, Job- und Cleanup-Evidenz liegt im Deep-Dive-Modul.''),
((SELECT [name] FROM [master].[sys].[databases] WITH (NOLOCK) WHERE [database_id] = DB_ID()),''ENCRYPTION'',N''Encryption'',CASE WHEN @Encryption>0 THEN ''DETECTED'' ELSE ''NOT_DETECTED_VISIBLE_SCOPE'' END,@Encryption,CASE WHEN @Encrypted=1 THEN N''DATABASE_ENCRYPTED'' ELSE N''DATABASE_NOT_ENCRYPTED'' END,N''sys.databases|sys.columns|sys.column_master_keys|sys.column_encryption_keys'',N''USP_EncryptionAnalysis'',''IMPLEMENTED'',N''TDE-Flag, verschlüsselte Spalten und Schlüsselmetadaten werden gezählt; Secrets, Schlüsselmaterial und geschützte Werte werden nicht gelesen.''),
((SELECT [name] FROM [master].[sys].[databases] WITH (NOLOCK) WHERE [database_id] = DB_ID()),''CLR'',N''CLR'',CASE WHEN @Clr>0 THEN ''DETECTED'' ELSE ''NOT_DETECTED_VISIBLE_SCOPE'' END,@Clr,NULL,N''sys.assemblies'',N''USP_ClrAnalysis'',''IMPLEMENTED'',N''Nur benutzerdefinierte Assemblyzeilen werden gezählt; Assemblyname, CLR-Identität, Binary und Moduldefinitionen werden nicht ausgegeben.''),
((SELECT [name] FROM [master].[sys].[databases] WITH (NOLOCK) WHERE [database_id] = DB_ID()),''EXTERNAL_TABLES'',N''External Tables und Data Sources'',CASE WHEN @ExternalTables>0 THEN ''DETECTED'' ELSE ''NOT_DETECTED_VISIBLE_SCOPE'' END,@ExternalTables,NULL,N''sys.external_tables|sys.external_data_sources'',NULL,''NOT_PLANNED'',N''Objektzahlen werden aggregiert; Locations, Connection Options, Credentials und Remote-Namen werden nicht gelesen.''),
((SELECT [name] FROM [master].[sys].[databases] WITH (NOLOCK) WHERE [database_id] = DB_ID()),''EXTERNAL_RUNTIME'',N''External Languages und Libraries'',CASE WHEN @ExternalRuntime>0 THEN ''DETECTED'' ELSE ''NOT_DETECTED_VISIBLE_SCOPE'' END,@ExternalRuntime,NULL,N''sys.external_languages|sys.external_libraries'',N''USP_ExternalRuntimeAnalysis'',''IMPLEMENTED'',N''Nur aggregierte Katalogzeilen; Namen, Dateien, Pfade, Besitzer und Libraryinhalte werden nicht gelesen.''),
((SELECT [name] FROM [master].[sys].[databases] WITH (NOLOCK) WHERE [database_id] = DB_ID()),''EXTERNAL_SCRIPTS'',N''External Scripts Configuration'',CASE WHEN @pExternalScriptsConfigured=1 THEN ''CONFIGURED_ONLY'' WHEN @pExternalScriptsConfigured=0 THEN ''NOT_DETECTED_VISIBLE_SCOPE'' ELSE ''SOURCE_UNAVAILABLE'' END,NULL,CASE WHEN @pExternalScriptsConfigured=1 THEN N''ENABLED'' WHEN @pExternalScriptsConfigured=0 THEN N''DISABLED'' ELSE N''UNKNOWN'' END,N''sys.configurations'',N''USP_ExternalRuntimeAnalysis'',''IMPLEMENTED'',N''Die Serverkonfiguration beweist keine tatsächliche Skriptausführung; Moduldefinitionen und Laufzeithistorie werden nicht durchsucht.''),
((SELECT [name] FROM [master].[sys].[databases] WITH (NOLOCK) WHERE [database_id] = DB_ID()),''FILESTREAM_FILETABLE'',N''FILESTREAM und FileTable'',CASE WHEN @FileStream>0 THEN ''DETECTED'' ELSE ''NOT_DETECTED_VISIBLE_SCOPE'' END,@FileStream,NULL,N''sys.columns|sys.tables'',NULL,''NOT_PLANNED'',N''Sichtbare FILESTREAM-Spalten und FileTables werden gezählt; Dateipfade und Inhalte werden nicht gelesen.''),
((SELECT [name] FROM [master].[sys].[databases] WITH (NOLOCK) WHERE [database_id] = DB_ID()),''GRAPH'',N''Graph'',CASE WHEN @Graph>0 THEN ''DETECTED'' ELSE ''NOT_DETECTED_VISIBLE_SCOPE'' END,@Graph,NULL,N''sys.tables'',NULL,''NOT_PLANNED'',N''Sichtbare Node- und Edge-Tabellen werden gezählt; Daten und Graphqualität sind nicht bewertet.''),
((SELECT [name] FROM [master].[sys].[databases] WITH (NOLOCK) WHERE [database_id] = DB_ID()),''SPATIAL'',N''Spatial'',CASE WHEN @Spatial>0 THEN ''DETECTED'' ELSE ''NOT_DETECTED_VISIBLE_SCOPE'' END,@Spatial,NULL,N''sys.columns|sys.types'',NULL,''NOT_PLANNED'',N''Sichtbare geometry-/geography-Spalten werden gezählt; räumliche Daten und Indizes sind nicht bewertet.''),
((SELECT [name] FROM [master].[sys].[databases] WITH (NOLOCK) WHERE [database_id] = DB_ID()),''XML'',N''XML'',CASE WHEN @Xml>0 THEN ''DETECTED'' ELSE ''NOT_DETECTED_VISIBLE_SCOPE'' END,@Xml,NULL,N''sys.columns|sys.types|sys.xml_indexes'',NULL,''NOT_PLANNED'',N''Sichtbare XML-Spalten und XML-Indizes werden gezählt; XML-Inhalte und Schema-Definitionen werden nicht gelesen.''),
((SELECT [name] FROM [master].[sys].[databases] WITH (NOLOCK) WHERE [database_id] = DB_ID()),''JSON_NATIVE'',N''Native JSON'',CASE WHEN @pMajor IS NULL THEN ''SOURCE_UNAVAILABLE'' WHEN @pMajor<17 THEN ''UNAVAILABLE_VERSION'' WHEN @NativeJson>0 THEN ''DETECTED'' ELSE ''NOT_DETECTED_VISIBLE_SCOPE'' END,@NativeJson,NULL,N''sys.columns|sys.types'',N''USP_ObjectInventory'',''IMPLEMENTED'',N''Erkannt wird nur der native JSON-Systemtyp ab SQL Server 2025; JSON in Zeichenketten oder Moduldefinitionen ist katalogseitig nicht zuverlässig inventarisierbar. Sichtbare JSON-Indizes und SQL/JSON-Pfade werden im ObjectInventory getrennt inventarisiert.''),
((SELECT [name] FROM [master].[sys].[databases] WITH (NOLOCK) WHERE [database_id] = DB_ID()),''VECTOR'',N''Vector'',CASE WHEN @pMajor IS NULL THEN ''SOURCE_UNAVAILABLE'' WHEN @pMajor<17 THEN ''UNAVAILABLE_VERSION'' WHEN @Vector>0 THEN ''DETECTED'' ELSE ''NOT_DETECTED_VISIBLE_SCOPE'' END,@Vector,NULL,N''sys.columns|sys.types'',N''USP_VectorIndexAnalysis'',''IMPLEMENTED'',N''Erkannt werden sichtbare Spalten des nativen Vector-Systemtyps; Inhalte und Indexgesundheit sind nicht bewertet. Für sichtbare Vector-Indizes steht die capability-adaptive Laufzeitanalyse bereit.''),
((SELECT [name] FROM [master].[sys].[databases] WITH (NOLOCK) WHERE [database_id] = DB_ID()),''USER_DEFINED_TYPES'',N''User-defined Types'',CASE WHEN @UserTypes>0 THEN ''DETECTED'' ELSE ''NOT_DETECTED_VISIBLE_SCOPE'' END,@UserTypes,NULL,N''sys.types'',NULL,''NOT_PLANNED'',N''Benutzerdefinierte Typzeilen werden aggregiert; Typnamen, Definitionen, Besitzer und Assemblydetails werden nicht ausgegeben.'');';

                EXEC [sys].[sp_executesql]
                      @Sql
                    , N'@pMajor int,@pExternalScriptsConfigured bit'
                    , @pMajor=@Major
                    , @pExternalScriptsConfigured=@ExternalScriptsConfigured;

                UPDATE [#SpecialFeatureInventory_DatabaseStatus]
                SET [FeatureRows]=(SELECT COUNT_BIG(*) FROM [#SpecialFeatureInventory_FeatureInventory] [f] WHERE [f].[DatabaseName]=@DbName),
                    [DetectedFeatureRows]=(SELECT COUNT_BIG(*) FROM [#SpecialFeatureInventory_FeatureInventory] [f]
                                           WHERE [f].[DatabaseName]=@DbName
                                             AND [f].[DetectionStatus] IN ('DETECTED','CONFIGURED_ONLY'))
                WHERE [DatabaseName]=@DbName;
            END TRY
            BEGIN CATCH
                UPDATE [#SpecialFeatureInventory_DatabaseStatus]
                SET [StatusCode]=CASE WHEN ERROR_NUMBER() IN (229,262,297,300,371,916) THEN 'DENIED_PERMISSION'
                                      WHEN ERROR_NUMBER()=1222 THEN 'TIMEOUT'
                                      WHEN ERROR_NUMBER() IN (207,208) THEN 'UNAVAILABLE_OBJECT'
                                      ELSE 'ERROR_HANDLED' END,
                    [IsPartial]=1,[ErrorNumber]=ERROR_NUMBER(),[ErrorMessage]=ERROR_MESSAGE(),
                    [Detail]=N'Featureinventur für diese Datenbank fehlgeschlagen; andere Datenbanken bleiben erhalten.'
                WHERE [DatabaseName]=@DbName;
            END CATCH;

            FETCH NEXT FROM [DatabaseCursor] INTO @DbName;
        END;
        CLOSE [DatabaseCursor];
        DEALLOCATE [DatabaseCursor];
    END;

    IF EXISTS(SELECT 1 FROM [#SpecialFeatureInventory_DatabaseStatus] WHERE [StatusCode]<>'AVAILABLE')
    BEGIN
        SET @IsPartial=1;
        IF EXISTS(SELECT 1 FROM [#SpecialFeatureInventory_FeatureInventory])
            SET @StatusCode='AVAILABLE_LIMITED';
        ELSE
            SELECT TOP (1) @StatusCode=[StatusCode],@ErrorNumber=[ErrorNumber],@ErrorMessage=[ErrorMessage]
            FROM [#SpecialFeatureInventory_DatabaseStatus]
            WHERE [StatusCode]<>'AVAILABLE'
            ORDER BY [DatabaseName];
    END;

    IF @ExternalScriptsConfigurationAvailable=0 AND EXISTS(SELECT 1 FROM [#SpecialFeatureInventory_FeatureInventory])
    BEGIN
        SET @IsPartial=1;
        IF @StatusCode='AVAILABLE' SET @StatusCode='AVAILABLE_LIMITED';
        IF @ErrorMessage IS NULL
            SET @ErrorMessage=N'Die Serverkonfiguration für External Scripts war nicht lesbar; übrige Featurezeilen bleiben erhalten.';
    END;

    IF NOT EXISTS(SELECT 1 FROM [#SpecialFeatureInventory_DatabaseStatus]) AND @StatusCode<>'AVAILABLE'
        INSERT [#SpecialFeatureInventory_DatabaseStatus]
        VALUES(NULL,@StatusCode,1,0,0,@ErrorNumber,@ErrorMessage,N'Keine Featureinventur ausgeführt.');

    SELECT @StatusCodeOut=@StatusCode,@IsPartialOut=@IsPartial,
           @ErrorNumberOut=@ErrorNumber,@ErrorMessageOut=@ErrorMessage;

    IF @PrintMeldungen=1 AND @StatusCode NOT IN ('AVAILABLE','NOT_APPLICABLE')
    BEGIN
        SET @PrintMessage=FORMATMESSAGE(N'WARNUNG USP_SpecialFeatureInventory %s: %s',
                         @StatusCode,COALESCE(@ErrorMessage,N'Teilergebnis oder Evidenzlücke.'));
        RAISERROR(N'%s',10,1,@PrintMessage) WITH NOWAIT;
    END;

    SET @LockTimeoutSql=N'SET LOCK_TIMEOUT '+CONVERT(nvarchar(20),@OriginalLockTimeout)+N';';
    EXEC [sys].[sp_executesql] @LockTimeoutSql;

    IF @JsonErzeugen=1
    BEGIN
        DECLARE @MetaJson nvarchar(max)=
            (SELECT N'SpecialFeatureInventory' [resultName],1 [schemaVersion],@Now [generatedAtUtc],
                    @StatusCode [statusCode],@IsPartial [isPartial],@Major [productMajorVersion],
                    @NurErkannteFeatures [detectedOnly],
                    (SELECT COUNT_BIG(*) FROM [#SpecialFeatureInventory_FeatureInventory]) [featureRowCount],
                    (SELECT COUNT_BIG(*) FROM [#SpecialFeatureInventory_FeatureInventory]
                     WHERE [DetectionStatus] IN ('DETECTED','CONFIGURED_ONLY')) [detectedFeatureRowCount]
             FOR JSON PATH,WITHOUT_ARRAY_WRAPPER,INCLUDE_NULL_VALUES);
        DECLARE @DatabaseJson nvarchar(max)=
            (SELECT * FROM [#SpecialFeatureInventory_DatabaseStatus] ORDER BY [DatabaseName] FOR JSON PATH,INCLUDE_NULL_VALUES);
        DECLARE @FeatureJson nvarchar(max)=
            (SELECT TOP (@Limit) *
             FROM [#SpecialFeatureInventory_FeatureInventory]
             WHERE @NurErkannteFeatures=0 OR [DetectionStatus] IN ('DETECTED','CONFIGURED_ONLY')
             ORDER BY [DatabaseName],[FeatureCode]
             FOR JSON PATH,INCLUDE_NULL_VALUES);
        SET @Json=CONCAT(N'{"meta":',COALESCE(@MetaJson,N'{}'),
                         N',"databaseStatus":',COALESCE(@DatabaseJson,N'[]'),
                         N',"features":',COALESCE(@FeatureJson,N'[]'),N'}');
    END;

    IF @OutputMode='RAW'
    BEGIN
        SELECT N'USP_SpecialFeatureInventory' [ModuleName],@Now [CollectionTimeUtc],
               @StatusCode [StatusCode],@IsPartial [IsPartial],@Major [ProductMajorVersion],
               (SELECT COUNT_BIG(*) FROM [#SpecialFeatureInventory_FeatureInventory]) [FeatureRowCount],
               (SELECT COUNT_BIG(*) FROM [#SpecialFeatureInventory_FeatureInventory]
                WHERE [DetectionStatus] IN ('DETECTED','CONFIGURED_ONLY')) [DetectedFeatureRowCount],
               @ErrorNumber [ErrorNumber],@ErrorMessage [ErrorMessage],
               N'Nutzungsinventar sichtbarer Metadaten; kein Gesundheitsurteil.' [Detail];
        SELECT * FROM [#SpecialFeatureInventory_DatabaseStatus] ORDER BY [DatabaseName];
        SELECT TOP (@Limit) *
        FROM [#SpecialFeatureInventory_FeatureInventory]
        WHERE @NurErkannteFeatures=0 OR [DetectionStatus] IN ('DETECTED','CONFIGURED_ONLY')
        ORDER BY [DatabaseName],[FeatureCode];
    END
    ELSE IF @OutputMode='CONSOLE'
    BEGIN
        SELECT N'Spezialfeature-Inventur' [Ergebnis],@Now [Stand_UTC],@StatusCode [Status],
               @IsPartial [Teilergebnis],@Major [Major_Version],
               (SELECT COUNT_BIG(*) FROM [#SpecialFeatureInventory_FeatureInventory]
                WHERE [DetectionStatus] IN ('DETECTED','CONFIGURED_ONLY')) [Erkannte_Featurezeilen],
               @ErrorMessage [Hinweis];
        SELECT N'Datenbankstatus Spezialfeature-Inventur' [Ergebnis],
               [DatabaseName] [Datenbank],[StatusCode] [Status],[FeatureRows] [Featurezeilen],
               [DetectedFeatureRows] [Erkannt],[IsPartial] [Teilweise],[Detail] [Hinweis]
        FROM [#SpecialFeatureInventory_DatabaseStatus]
        ORDER BY [DatabaseName];
        SELECT TOP (@Limit) N'Spezialfeature' [Ergebnis],
               [DatabaseName] [Datenbank],[FeatureCode] [Featurecode],[FeatureFamily] [Featurefamilie],
               [DetectionStatus] [Erkennungsstatus],[DetectedItemCount] [Erkannte_Elemente],
               [ConfigurationState] [Konfiguration],[RecommendedModule] [Empfohlenes_Modul],
               [RecommendedModuleStatus] [Modulstatus],[EvidenceLimit] [Aussagegrenze]
        FROM [#SpecialFeatureInventory_FeatureInventory]
        WHERE @NurErkannteFeatures=0 OR [DetectionStatus] IN ('DETECTED','CONFIGURED_ONLY')
        ORDER BY [DatabaseName],[FeatureCode];
    END;
    IF @ConsoleResultRequested = 1
    BEGIN
        EXEC [monitor].[InternalEmitConsoleResult]
              @SourceTable=N'#SpecialFeatureInventory_FeatureInventory'
            , @ResultLabel=N'SpecialFeatureInventory'
            , @EmptyMessage=N'Keine fachlichen Ergebnisse';
    END;
    IF @TableResultRequested = 1
    BEGIN
        EXEC [monitor].[InternalWriteResultTable]
              @SourceTable = N'#SpecialFeatureInventory_FeatureInventory'
            , @TargetTable=@TableTarget
            , @ThrowOnError = 1;
    END;
END;
GO
-- END SOURCE: Code/09_VersionAdaptive/020_USP_SpecialFeatureInventory.sql

-- BEGIN SOURCE: Code/09_VersionAdaptive/030_USP_InMemoryOltpAnalysis.sql
/*
===============================================================================
Objekt       : monitor.USP_InMemoryOltpAnalysis
Version      : 1.0.0
Stand        : 2026-07-17
Typ          : Stored Procedure
Zweck        : Analysiert sichtbare In-Memory-OLTP-Konfiguration und isolierte
               Laufzeitevidenz zu Speicher, Hashindizes, Checkpoint-Dateien,
               aktiven Transaktionen und Resource-Governor-Pools.
SQL-Version  : SQL Server 2019 oder neuer.
Datenquellen : sys.tables, sys.table_types, sys.filegroups, sys.hash_indexes,
               sys.dm_db_xtp_table_memory_stats,
               sys.dm_db_xtp_memory_consumers,
               sys.dm_db_xtp_hash_index_stats (opt-in),
               sys.dm_db_xtp_checkpoint_files, sys.dm_db_xtp_transactions,
               sys.databases und sys.dm_resource_governor_resource_pools.
Methodik     : Jede DMV-Quelle wird separat best effort ausgewertet. Fehlende
               Rechte oder Quellen verwerfen andere zugängliche Evidenz nicht.
Grenzen      : Momentaufnahmen und heuristische Prüfhinweise sind kein Beweis
               für Speicherknappheit, fehlerhafte Bucket-Zahlen, Log-Stau oder
               Transaktionsprobleme. Keine DDL-, Daten- oder Definitionsscans.
Kosten       : MEDIUM; Hashindex-Laufzeitstatistik HIGH_OPT_IN, da die DMV nach
               Herstellerdokumentation vollständige Tabellen scannen kann.
===============================================================================
*/
CREATE OR ALTER PROCEDURE [monitor].[USP_InMemoryOltpAnalysis]
      @DatabaseNames                    nvarchar(max)  = NULL
    , @SystemdatenbankenEinbeziehen     bit            = 0
    , @DatabaseNamePattern              nvarchar(4000) = NULL
    , @HighImpactConfirmed              bit            = 0
    , @SchemaNames                      nvarchar(max)  = NULL
    , @SchemaNamePattern                nvarchar(4000) = NULL
    , @ObjectNames                      nvarchar(max)  = NULL
    , @ObjectNamePattern                nvarchar(4000) = NULL
    , @FullObjectNames                  nvarchar(max)  = NULL
    , @MitHashIndexStats                bit            = 0
    , @NurProblematisch                 bit            = 0
    , @MinTableMemoryMb                 decimal(19,2)  = 1024
    , @HashAvgChainWarn                 decimal(19,4)  = 10
    , @HashMaxChainWarn                 bigint         = 100
    , @HashMinEmptyBucketPercent        decimal(9,4)   = 10
    , @WaitingCheckpointWarnMb          decimal(19,2)  = 1024
    , @ActiveTransactionWarnCount       int            = 100
    , @PoolUsedWarnPercent              decimal(9,4)   = 80
    , @MaxZeilen                        int            = 2000
    , @LockTimeoutMs                    int            = 0
    , @ResultSetArt                     varchar(16)     = 'CONSOLE'
    , @ResultTablesJson               nvarchar(max) = NULL
    , @JsonErzeugen                     bit            = 0
    , @Json                             nvarchar(max)   = NULL OUTPUT
    , @PrintMeldungen                   bit            = 1
    , @Hilfe                            bit            = 0
    , @StatusCodeOut                    varchar(40)     = NULL OUTPUT
    , @IsPartialOut                     bit            = NULL OUTPUT
    , @ErrorNumberOut                   int            = NULL OUTPUT
    , @ErrorMessageOut                  nvarchar(2048)  = NULL OUTPUT
AS
BEGIN
    SET NOCOUNT ON;
    SET LOCK_TIMEOUT 0;
    SET @Json=NULL;

    DECLARE @Now datetime2(3)=SYSUTCDATETIME();
    DECLARE @Major int=TRY_CONVERT(int,SERVERPROPERTY(N'ProductMajorVersion'));
    DECLARE @OutputMode varchar(16)=UPPER(LTRIM(RTRIM(COALESCE(@ResultSetArt,''))));
    DECLARE @TableResultRequested bit = CASE WHEN @OutputMode = 'TABLE' THEN 1 ELSE 0 END;
    DECLARE @ConsoleResultRequested bit = CASE WHEN @OutputMode = 'CONSOLE' THEN 1 ELSE 0 END;
    DECLARE @TableTarget sysname=NULL;
    IF @TableResultRequested=0 AND NULLIF(LTRIM(RTRIM(COALESCE(@ResultTablesJson,N''))),N'') IS NOT NULL THROW 51011,N'@ResultTablesJson ist ausschließlich mit @ResultSetArt=TABLE zulässig.',1;
    IF @TableResultRequested=1 EXEC [monitor].[InternalPrepareSingleResultTable] @ResultTablesJson=@ResultTablesJson,@ResultName=N'findings',@TargetTable=@TableTarget OUTPUT,@ThrowOnError=1;
    IF @TableResultRequested = 1 OR @ConsoleResultRequested = 1 SET @OutputMode = 'NONE';
    DECLARE @StatusCode varchar(40)='AVAILABLE';
    DECLARE @IsPartial bit=0;
    DECLARE @ErrorNumber int=NULL;
    DECLARE @ErrorMessage nvarchar(2048)=NULL;
    DECLARE @PrintMessage nvarchar(2048)=NULL;
    DECLARE @Limit bigint=CASE WHEN @MaxZeilen IS NULL OR @MaxZeilen=0
                               THEN CONVERT(bigint,9223372036854775807)
                               ELSE CONVERT(bigint,@MaxZeilen) END;

    IF @Hilfe=1
    BEGIN
        PRINT N'monitor.USP_InMemoryOltpAnalysis';
        PRINT N'Die Procedure führt eine rein lesende Tiefenanalyse sichtbarer In-Memory-OLTP-Metadaten und isolierter Laufzeitquellen durch.';
        PRINT N'@MitHashIndexStats=1 aktiviert eine potenziell teure vollständige Hashindex-DMV-Auswertung und benötigt CATALOG_DEEP.';
        PRINT N'Exakte Namenslisten und Pattern derselben Eigenschaft sind gegenseitig exklusiv; Pattern: LIKE, regex: oder regexi:.';
        PRINT N'Grenzwerte erzeugen Prüfhinweise, keine automatische DDL- oder Kapazitätsempfehlung.';
        PRINT N'@ResultSetArt=CONSOLE|RAW|TABLE|NONE; TABLE verwendet @ResultTablesJson; @JsonErzeugen=1 erzeugt @Json OUTPUT.';
        PRINT N'Es werden keine Benutzertabellendaten, Moduldefinitionen, SQL-Texte, Transaktions-IDs oder Checkpoint-Dateipfade gelesen.';
        RETURN;
    END;

    IF @SystemdatenbankenEinbeziehen IS NULL OR @MitHashIndexStats IS NULL
       OR @NurProblematisch IS NULL OR @JsonErzeugen IS NULL OR @PrintMeldungen IS NULL
       OR @MinTableMemoryMb IS NULL OR @MinTableMemoryMb<0
       OR @HashAvgChainWarn IS NULL OR @HashAvgChainWarn<1 OR @HashAvgChainWarn>100000
       OR @HashMaxChainWarn IS NULL OR @HashMaxChainWarn<1
       OR @HashMinEmptyBucketPercent IS NULL OR @HashMinEmptyBucketPercent<0 OR @HashMinEmptyBucketPercent>100
       OR @WaitingCheckpointWarnMb IS NULL OR @WaitingCheckpointWarnMb<0
       OR @ActiveTransactionWarnCount IS NULL OR @ActiveTransactionWarnCount<1
       OR @PoolUsedWarnPercent IS NULL OR @PoolUsedWarnPercent<0 OR @PoolUsedWarnPercent>100
 OR @MaxZeilen<0
       OR @LockTimeoutMs IS NULL OR @LockTimeoutMs NOT BETWEEN 0 AND 60000
       OR @OutputMode NOT IN('CONSOLE','RAW','NONE')
    BEGIN
        SELECT @StatusCode='INVALID_PARAMETER',@IsPartial=1,
               @ErrorMessage=N'Ungültiger Bit-, Grenzwert-, Mengen-, Lock-Timeout- oder Ausgabeparameter.';
    END;

    DECLARE @SchemaPatternMode varchar(8),@SchemaPatternValue nvarchar(4000),@SchemaRegexFlags varchar(8),@SchemaPatternValid bit;
    DECLARE @ObjectPatternMode varchar(8),@ObjectPatternValue nvarchar(4000),@ObjectRegexFlags varchar(8),@ObjectPatternValid bit;
    SELECT @SchemaPatternMode=[PatternMode],@SchemaPatternValue=[PatternValue],@SchemaRegexFlags=[RegexFlags],@SchemaPatternValid=[IsValid]
    FROM [monitor].[TVF_ParsePattern](@SchemaNamePattern);
    SELECT @ObjectPatternMode=[PatternMode],@ObjectPatternValue=[PatternValue],@ObjectRegexFlags=[RegexFlags],@ObjectPatternValid=[IsValid]
    FROM [monitor].[TVF_ParsePattern](@ObjectNamePattern);

    IF @StatusCode='AVAILABLE'
       AND (@SchemaPatternValid=0 OR @ObjectPatternValid=0
            OR (@SchemaNames IS NOT NULL AND @SchemaNamePattern IS NOT NULL)
            OR (@ObjectNames IS NOT NULL AND @ObjectNamePattern IS NOT NULL))
    BEGIN
        SELECT @StatusCode='INVALID_PARAMETER',@IsPartial=1,
               @ErrorMessage=N'Pattern ungültig oder exakte Liste und Pattern derselben Eigenschaft gleichzeitig angegeben.';
    END;

    IF @StatusCode='AVAILABLE'
       AND (@SchemaPatternMode IN('REGEX','REGEXI') OR @ObjectPatternMode IN('REGEX','REGEXI'))
       AND COALESCE(@Major,0)<17
    BEGIN
        SELECT @StatusCode='UNAVAILABLE_VERSION',@IsPartial=1,
               @ErrorMessage=N'Regex-Pattern benötigen SQL Server 2025 oder neuer und Compatibility Level 170.';
    END;

    CREATE TABLE [#InMemoryOltpAnalysis_NameFilters]
    (
          [FilterType] varchar(20) COLLATE SQL_Latin1_General_CP1_CS_AS NOT NULL
        , [ItemOrdinal] int NOT NULL
        , [NameValue] sysname COLLATE SQL_Latin1_General_CP1_CS_AS NULL
        , [DatabaseName] sysname COLLATE SQL_Latin1_General_CP1_CS_AS NULL
        , [SchemaName] sysname COLLATE SQL_Latin1_General_CP1_CS_AS NULL
        , [ObjectName] sysname COLLATE SQL_Latin1_General_CP1_CS_AS NULL
    );
    CREATE TABLE [#InMemoryOltpAnalysis_DatabaseCandidates]
    (
          [DatabaseId] int NOT NULL
        , [DatabaseName] sysname NOT NULL
        , [StateDesc] nvarchar(60) NULL
        , [UserAccessDesc] nvarchar(60) NULL
        , [IsReadOnly] bit NULL
        , [CompatibilityLevel] tinyint NULL
        , [CollationName] sysname NULL
        , [RecoveryModelDesc] nvarchar(60) NULL
        , [IsSystemDatabase] bit NULL
        , [RequestedOrdinal] int NULL
    );
    CREATE TABLE [#InMemoryOltpAnalysis_DatabaseCandidateWarnings]
    (
          [RequestedName] sysname COLLATE SQL_Latin1_General_CP1_CS_AS NULL
        , [StatusCode] varchar(40) NOT NULL
        , [ErrorMessage] nvarchar(2048) NOT NULL
    );
    CREATE TABLE [#InMemoryOltpAnalysis_FeatureScope]
    (
          [DatabaseName] sysname NOT NULL PRIMARY KEY
        , [MemoryOptimizedTableCount] bigint NOT NULL
        , [MemoryOptimizedTableTypeCount] bigint NOT NULL
        , [MemoryOptimizedFilegroupCount] bigint NOT NULL
    );
    CREATE TABLE [#InMemoryOltpAnalysis_DatabaseStatus]
    (
          [DatabaseName] sysname NULL
        , [StatusCode] varchar(40) NOT NULL
        , [IsPartial] bit NOT NULL
        , [MemoryOptimizedTableCount] bigint NOT NULL
        , [MemoryOptimizedTableTypeCount] bigint NOT NULL
        , [MemoryOptimizedFilegroupCount] bigint NOT NULL
        , [SourceFailureCount] int NOT NULL
        , [FindingCount] bigint NOT NULL
        , [RequiredPermission] nvarchar(256) NULL
        , [ErrorNumber] int NULL
        , [ErrorMessage] nvarchar(2048) NULL
        , [Detail] nvarchar(2000) NULL
    );
    CREATE TABLE [#InMemoryOltpAnalysis_SourceStatus]
    (
          [DatabaseName] sysname NULL
        , [SourceCode] varchar(64) NOT NULL
        , [StatusCode] varchar(40) NOT NULL
        , [IsPartial] bit NOT NULL
        , [RowCount] bigint NOT NULL
        , [RequiredPermission] nvarchar(256) NULL
        , [ErrorNumber] int NULL
        , [ErrorMessage] nvarchar(2048) NULL
        , [Detail] nvarchar(2000) NULL
    );
    CREATE TABLE [#InMemoryOltpAnalysis_TableMemory]
    (
          [DatabaseName] sysname NOT NULL
        , [SchemaName] sysname NOT NULL
        , [TableName] sysname NOT NULL
        , [ObjectId] int NOT NULL
        , [DurabilityDesc] nvarchar(60) NULL
        , [TableAllocatedMb] decimal(19,2) NULL
        , [TableUsedMb] decimal(19,2) NULL
        , [IndexAllocatedMb] decimal(19,2) NULL
        , [IndexUsedMb] decimal(19,2) NULL
        , [TotalAllocatedMb] decimal(19,2) NULL
        , [TotalUsedMb] decimal(19,2) NULL
        , [UsedPercent] decimal(9,4) NULL
        , [Severity] varchar(16) NOT NULL
        , [FindingCode] varchar(120) NULL
        , [EvidenceLimit] nvarchar(1000) NOT NULL
    );
    CREATE TABLE [#InMemoryOltpAnalysis_HashIndex]
    (
          [DatabaseName] sysname NOT NULL
        , [SchemaName] sysname NOT NULL
        , [TableName] sysname NOT NULL
        , [IndexName] sysname NOT NULL
        , [ObjectId] int NOT NULL
        , [IndexId] int NOT NULL
        , [ConfiguredBucketCount] bigint NULL
        , [TotalBucketCount] bigint NULL
        , [EmptyBucketCount] bigint NULL
        , [EmptyBucketPercent] decimal(9,4) NULL
        , [AverageChainLength] decimal(19,4) NULL
        , [MaxChainLength] bigint NULL
        , [RuntimeStatsStatus] varchar(40) NOT NULL
        , [Severity] varchar(16) NOT NULL
        , [FindingCode] varchar(120) NULL
        , [EvidenceLimit] nvarchar(1000) NOT NULL
    );
    CREATE TABLE [#InMemoryOltpAnalysis_MemoryConsumer]
    (
          [DatabaseName] sysname NOT NULL
        , [MemoryConsumerType] int NULL
        , [MemoryConsumerDesc] nvarchar(256) NULL
        , [ConsumerCount] bigint NOT NULL
        , [AllocationCount] bigint NULL
        , [AllocatedMb] decimal(19,2) NULL
        , [UsedMb] decimal(19,2) NULL
        , [UsedPercent] decimal(9,4) NULL
        , [EvidenceLimit] nvarchar(1000) NOT NULL
    );
    CREATE TABLE [#InMemoryOltpAnalysis_Checkpoint]
    (
          [DatabaseName] sysname NOT NULL
        , [FileType] int NULL
        , [FileTypeDesc] nvarchar(60) NULL
        , [State] int NULL
        , [StateDesc] nvarchar(60) NULL
        , [FileCount] bigint NOT NULL
        , [FileSizeMb] decimal(19,2) NULL
        , [FileUsedMb] decimal(19,2) NULL
        , [LogicalRowCount] bigint NULL
        , [Severity] varchar(16) NOT NULL
        , [FindingCode] varchar(120) NULL
        , [EvidenceLimit] nvarchar(1000) NOT NULL
    );
    CREATE TABLE [#InMemoryOltpAnalysis_Transaction]
    (
          [DatabaseName] sysname NOT NULL
        , [TransactionState] int NULL
        , [TransactionStateDesc] nvarchar(60) NOT NULL
        , [ResultDesc] nvarchar(256) NULL
        , [TransactionCount] bigint NOT NULL
        , [Severity] varchar(16) NOT NULL
        , [FindingCode] varchar(120) NULL
        , [EvidenceLimit] nvarchar(1000) NOT NULL
    );
    CREATE TABLE [#InMemoryOltpAnalysis_ResourcePool]
    (
          [DatabaseName] sysname NOT NULL
        , [ResourcePoolId] int NULL
        , [ResourcePoolName] sysname NULL
        , [IsDefaultOrUnbound] bit NOT NULL
        , [DatabasesUsingPool] bigint NULL
        , [MinMemoryPercent] int NULL
        , [MaxMemoryPercent] int NULL
        , [MaxMemoryMb] decimal(19,2) NULL
        , [TargetMemoryMb] decimal(19,2) NULL
        , [UsedMemoryMb] decimal(19,2) NULL
        , [UsedPercentOfTarget] decimal(9,4) NULL
        , [OutOfMemoryCount] bigint NULL
        , [Severity] varchar(16) NOT NULL
        , [FindingCode] varchar(120) NULL
        , [EvidenceLimit] nvarchar(1000) NOT NULL
    );
    CREATE TABLE [#InMemoryOltpAnalysis_Findings]
    (
          [FindingOrdinal] bigint IDENTITY(1,1) NOT NULL
        , [DatabaseName] sysname NULL
        , [SchemaName] sysname NULL
        , [ObjectName] sysname NULL
        , [IndexName] sysname NULL
        , [Severity] varchar(16) NOT NULL
        , [Confidence] varchar(16) NOT NULL
        , [FindingCode] varchar(120) NOT NULL
        , [MetricName] varchar(80) NOT NULL
        , [MetricValue] decimal(38,4) NULL
        , [ThresholdValue] decimal(38,4) NULL
        , [Evidence] nvarchar(1000) NOT NULL
        , [EvidenceLimit] nvarchar(1000) NOT NULL
        , [RecommendedNextCheck] nvarchar(1000) NOT NULL
    );

    IF @StatusCode='AVAILABLE'
    BEGIN
        EXEC [monitor].[USP_PrepareNameFilters]
              @SchemaNames=@SchemaNames
            , @ObjectNames=@ObjectNames
            , @FullObjectNames=@FullObjectNames
            , @IndexNames=NULL
            , @StatisticsNames=NULL
            , @ColumnNames=NULL
            , @StatusCode=@StatusCode OUTPUT
            , @ErrorMessage=@ErrorMessage OUTPUT,@FilterTable=N'#InMemoryOltpAnalysis_NameFilters';
        IF @StatusCode<>'AVAILABLE' SET @IsPartial=1;
    END;

    DECLARE @CrossDatabaseRequested bit=0;
    IF @StatusCode='AVAILABLE'
    BEGIN
        EXEC [monitor].[USP_PrepareDatabaseCandidates]
              @DatabaseNames=@DatabaseNames
            , @SystemdatenbankenEinbeziehen=@SystemdatenbankenEinbeziehen
            , @DatabaseNamePattern=@DatabaseNamePattern,@HighImpactConfirmed=@HighImpactConfirmed

            , @AnalysisClass='OBJECT_ANALYSIS_CURRENT'
            , @StatusCode=@StatusCode OUTPUT
            , @ErrorMessage=@ErrorMessage OUTPUT
            , @CrossDatabaseRequested=@CrossDatabaseRequested OUTPUT,@CandidateTable=N'#InMemoryOltpAnalysis_DatabaseCandidates',@WarningTable=N'#InMemoryOltpAnalysis_DatabaseCandidateWarnings';
        IF @StatusCode<>'AVAILABLE' SET @IsPartial=1;
    END;

    INSERT [#InMemoryOltpAnalysis_DatabaseStatus]
    ([DatabaseName],[StatusCode],[IsPartial],[MemoryOptimizedTableCount],[MemoryOptimizedTableTypeCount],
     [MemoryOptimizedFilegroupCount],[SourceFailureCount],[FindingCount],[Detail])
    SELECT [DatabaseName],'PENDING',0,0,0,0,0,0,
           N'Feature-Gate und Quellen werden datenbankweise best effort ausgewertet.'
    FROM [#InMemoryOltpAnalysis_DatabaseCandidates];

    INSERT [#InMemoryOltpAnalysis_DatabaseStatus]
    ([DatabaseName],[StatusCode],[IsPartial],[MemoryOptimizedTableCount],[MemoryOptimizedTableTypeCount],
     [MemoryOptimizedFilegroupCount],[SourceFailureCount],[FindingCount],[ErrorMessage],[Detail])
    SELECT [RequestedName],[StatusCode],1,0,0,0,1,0,[ErrorMessage],N'Explizit angeforderte Datenbank nicht auswertbar.'
    FROM [#InMemoryOltpAnalysis_DatabaseCandidateWarnings];

    IF @StatusCode='AVAILABLE' AND NOT EXISTS(SELECT 1 FROM [#InMemoryOltpAnalysis_DatabaseCandidates])
    BEGIN
        SELECT @StatusCode='NOT_APPLICABLE',@ErrorMessage=N'Keine auswertbare Datenbank im gewählten Scope.';
    END;

    IF @StatusCode='AVAILABLE' AND @MitHashIndexStats=1
        EXEC [monitor].[InternalCheckAnalysisPath]
              @AnalysisClass='CATALOG_DEEP'
            , @HighImpactConfirmed=@HighImpactConfirmed
            , @StatusCode=@StatusCode OUTPUT
            , @ErrorMessage=@ErrorMessage OUTPUT;
    DECLARE @HashStatsAllowed bit=CONVERT(bit,CASE WHEN @StatusCode='AVAILABLE' THEN 1 ELSE 0 END);

    DECLARE @SchemaPredicate nvarchar(max)=
        N' AND (NOT EXISTS(SELECT 1 FROM [#InMemoryOltpAnalysis_NameFilters] WHERE [FilterType]=''SCHEMA'') OR EXISTS(SELECT 1 FROM [#InMemoryOltpAnalysis_NameFilters] [f] WHERE [f].[FilterType]=''SCHEMA'' AND [f].[NameValue]=[s].[name] COLLATE SQL_Latin1_General_CP1_CS_AS))';
    DECLARE @ObjectPredicate nvarchar(max)=
        N' AND (NOT EXISTS(SELECT 1 FROM [#InMemoryOltpAnalysis_NameFilters] WHERE [FilterType]=''OBJECT'') OR EXISTS(SELECT 1 FROM [#InMemoryOltpAnalysis_NameFilters] [f] WHERE [f].[FilterType]=''OBJECT'' AND [f].[NameValue]=[t].[name] COLLATE SQL_Latin1_General_CP1_CS_AS))';
    DECLARE @FullObjectPredicate nvarchar(max)=
        N' AND (NOT EXISTS(SELECT 1 FROM [#InMemoryOltpAnalysis_NameFilters] WHERE [FilterType]=''FULL_OBJECT'') OR EXISTS(SELECT 1 FROM [#InMemoryOltpAnalysis_NameFilters] [f] WHERE [f].[FilterType]=''FULL_OBJECT'' AND ([f].[DatabaseName] IS NULL OR [f].[DatabaseName]=@pDatabaseName COLLATE SQL_Latin1_General_CP1_CS_AS) AND ([f].[SchemaName] IS NULL OR [f].[SchemaName]=[s].[name] COLLATE SQL_Latin1_General_CP1_CS_AS) AND [f].[ObjectName]=[t].[name] COLLATE SQL_Latin1_General_CP1_CS_AS))';
    IF @SchemaPatternMode='LIKE'
        SET @SchemaPredicate+=N' AND [s].[name] COLLATE SQL_Latin1_General_CP1_CS_AS LIKE N'''+REPLACE(@SchemaPatternValue,N'''',N'''''')+N''' COLLATE SQL_Latin1_General_CP1_CS_AS';
    IF @SchemaPatternMode IN('REGEX','REGEXI')
        SET @SchemaPredicate+=N' AND REGEXP_LIKE([s].[name],N'''+REPLACE(@SchemaPatternValue,N'''',N'''''')+N''','''+@SchemaRegexFlags+N''')';
    IF @ObjectPatternMode='LIKE'
        SET @ObjectPredicate+=N' AND [t].[name] COLLATE SQL_Latin1_General_CP1_CS_AS LIKE N'''+REPLACE(@ObjectPatternValue,N'''',N'''''')+N''' COLLATE SQL_Latin1_General_CP1_CS_AS';
    IF @ObjectPatternMode IN('REGEX','REGEXI')
        SET @ObjectPredicate+=N' AND REGEXP_LIKE([t].[name],N'''+REPLACE(@ObjectPatternValue,N'''',N'''''')+N''','''+@ObjectRegexFlags+N''')';

    IF @StatusCode='AVAILABLE'
    BEGIN
        DECLARE @DbName sysname,@CompatibilityLevel int,@Sql nvarchar(max),@Rows bigint;
        DECLARE [DatabaseCursor] CURSOR LOCAL FAST_FORWARD FOR
            SELECT [DatabaseName],[CompatibilityLevel]
            FROM [#InMemoryOltpAnalysis_DatabaseCandidates]
            ORDER BY COALESCE([RequestedOrdinal],[DatabaseId]),[DatabaseId];
        OPEN [DatabaseCursor];
        FETCH NEXT FROM [DatabaseCursor] INTO @DbName,@CompatibilityLevel;

        WHILE @@FETCH_STATUS=0
        BEGIN
            IF (@SchemaPatternMode IN('REGEX','REGEXI') OR @ObjectPatternMode IN('REGEX','REGEXI'))
               AND COALESCE(@CompatibilityLevel,0)<170
            BEGIN
                UPDATE [#InMemoryOltpAnalysis_DatabaseStatus]
                SET [StatusCode]='UNAVAILABLE_FEATURE',[IsPartial]=1,[SourceFailureCount]=1,
                    [ErrorMessage]=N'Regex-Pattern benötigen Compatibility Level 170.',
                    [Detail]=N'Für diese Datenbank wurde wegen inkompatiblem Patternvertrag keine Analyse ausgeführt.'
                WHERE [DatabaseName]=@DbName;
                INSERT [#InMemoryOltpAnalysis_SourceStatus]
                VALUES(@DbName,'FILTER_CONTRACT','UNAVAILABLE_FEATURE',1,0,NULL,NULL,
                       N'Regex-Pattern benötigen Compatibility Level 170.',N'Keine Quellenabfrage ausgeführt.');
                FETCH NEXT FROM [DatabaseCursor] INTO @DbName,@CompatibilityLevel;
                CONTINUE;
            END;

            BEGIN TRY
                SET @Sql=N'SET LOCK_TIMEOUT '+CONVERT(nvarchar(11),@LockTimeoutMs)+N'; USE '+QUOTENAME(@DbName)+N';
INSERT [#InMemoryOltpAnalysis_FeatureScope]([DatabaseName],[MemoryOptimizedTableCount],[MemoryOptimizedTableTypeCount],[MemoryOptimizedFilegroupCount])
SELECT @pDatabaseName,
       (SELECT COUNT_BIG(*) FROM [sys].[tables] WITH (NOLOCK) WHERE [is_ms_shipped]=0 AND [is_memory_optimized]=1),
       (SELECT COUNT_BIG(*) FROM [sys].[table_types] WITH (NOLOCK) WHERE [is_memory_optimized]=1),
       (SELECT COUNT_BIG(*) FROM [sys].[filegroups] WITH (NOLOCK) WHERE [type]=''FX'');
SET @pRows=@@ROWCOUNT;';
                SET @Rows=0;
                EXEC [sys].[sp_executesql] @Sql,N'@pDatabaseName sysname,@pRows bigint OUTPUT',@pDatabaseName=@DbName,@pRows=@Rows OUTPUT;
                INSERT [#InMemoryOltpAnalysis_SourceStatus]
                VALUES(@DbName,'XTP_FEATURE_GATE','AVAILABLE',0,@Rows,N'Katalogsicht auf sichtbare Datenbankmetadaten',NULL,NULL,
                       N'Tabellen, Tabellentypen und MEMORY_OPTIMIZED_DATA-Dateigruppe; keine Nutzdaten.');
                UPDATE [ds]
                SET [MemoryOptimizedTableCount]=[fs].[MemoryOptimizedTableCount],
                    [MemoryOptimizedTableTypeCount]=[fs].[MemoryOptimizedTableTypeCount],
                    [MemoryOptimizedFilegroupCount]=[fs].[MemoryOptimizedFilegroupCount]
                FROM [#InMemoryOltpAnalysis_DatabaseStatus] [ds]
                JOIN [#InMemoryOltpAnalysis_FeatureScope] [fs] ON [fs].[DatabaseName]=[ds].[DatabaseName]
                WHERE [ds].[DatabaseName]=@DbName;
            END TRY
            BEGIN CATCH
                INSERT [#InMemoryOltpAnalysis_SourceStatus]
                VALUES(@DbName,'XTP_FEATURE_GATE','ERROR_HANDLED',1,0,N'Katalogsicht auf sichtbare Datenbankmetadaten',
                       ERROR_NUMBER(),ERROR_MESSAGE(),N'Feature-Sichtbarkeit konnte nicht bestimmt werden.');
                UPDATE [#InMemoryOltpAnalysis_DatabaseStatus]
                SET [StatusCode]='ERROR_HANDLED',[IsPartial]=1,[SourceFailureCount]=[SourceFailureCount]+1,
                    [ErrorNumber]=ERROR_NUMBER(),[ErrorMessage]=ERROR_MESSAGE(),
                    [Detail]=N'Feature-Gate fehlgeschlagen; keine belastbare Anwendbarkeitsaussage.'
                WHERE [DatabaseName]=@DbName;
            END CATCH;

            IF NOT EXISTS(SELECT 1 FROM [#InMemoryOltpAnalysis_FeatureScope] WHERE [DatabaseName]=@DbName)
            BEGIN
                FETCH NEXT FROM [DatabaseCursor] INTO @DbName,@CompatibilityLevel;
                CONTINUE;
            END;

            IF EXISTS
            (
                SELECT 1 FROM [#InMemoryOltpAnalysis_FeatureScope]
                WHERE [DatabaseName]=@DbName
                  AND [MemoryOptimizedTableCount]+[MemoryOptimizedTableTypeCount]+[MemoryOptimizedFilegroupCount]=0
            )
            BEGIN
                UPDATE [#InMemoryOltpAnalysis_DatabaseStatus]
                SET [StatusCode]='NOT_APPLICABLE_VISIBLE_SCOPE',[IsPartial]=0,
                    [Detail]=N'Im sichtbaren Katalogscope wurde keine In-Memory-OLTP-Nutzung oder MEMORY_OPTIMIZED_DATA-Dateigruppe erkannt; dies beweist keine vollständige Abwesenheit.'
                WHERE [DatabaseName]=@DbName;
                INSERT [#InMemoryOltpAnalysis_SourceStatus]
                SELECT @DbName,[SourceCode],'NOT_APPLICABLE',0,0,[RequiredPermission],NULL,NULL,
                       N'Quelle wegen negativem sichtbaren Feature-Gate nicht aufgerufen.'
                FROM (VALUES
                      ('XTP_TABLE_MEMORY',N'VIEW DATABASE STATE; SQL Server 2022+: VIEW DATABASE PERFORMANCE STATE'),
                      ('XTP_MEMORY_CONSUMERS',N'VIEW DATABASE STATE; SQL Server 2022+: VIEW DATABASE PERFORMANCE STATE'),
                      ('XTP_HASH_INDEX_CATALOG',N'Katalogsicht auf sichtbare Hashindizes'),
                      ('XTP_HASH_INDEX_STATS',N'VIEW DATABASE STATE; SQL Server 2022+: VIEW DATABASE PERFORMANCE STATE'),
                      ('XTP_CHECKPOINT_FILES',N'VIEW DATABASE STATE; SQL Server 2022+: VIEW DATABASE PERFORMANCE STATE'),
                      ('XTP_TRANSACTIONS',N'VIEW DATABASE STATE; SQL Server 2022+: VIEW DATABASE PERFORMANCE STATE'),
                      ('RESOURCE_POOL_MEMORY',N'VIEW SERVER STATE; SQL Server 2022+: VIEW SERVER PERFORMANCE STATE'))
                     [x]([SourceCode],[RequiredPermission]);
                FETCH NEXT FROM [DatabaseCursor] INTO @DbName,@CompatibilityLevel;
                CONTINUE;
            END;

            BEGIN TRY
                SET @Sql=N'SET LOCK_TIMEOUT '+CONVERT(nvarchar(11),@LockTimeoutMs)+N'; USE '+QUOTENAME(@DbName)+N';
INSERT [#InMemoryOltpAnalysis_TableMemory]
SELECT @pDatabaseName,[s].[name],[t].[name],[t].[object_id],[t].[durability_desc],
       CONVERT(decimal(19,2),[m].[memory_allocated_for_table_kb]/1024.0),
       CONVERT(decimal(19,2),[m].[memory_used_by_table_kb]/1024.0),
       CONVERT(decimal(19,2),[m].[memory_allocated_for_indexes_kb]/1024.0),
       CONVERT(decimal(19,2),[m].[memory_used_by_indexes_kb]/1024.0),
       CONVERT(decimal(19,2),([m].[memory_allocated_for_table_kb]+[m].[memory_allocated_for_indexes_kb])/1024.0),
       CONVERT(decimal(19,2),([m].[memory_used_by_table_kb]+[m].[memory_used_by_indexes_kb])/1024.0),
       CONVERT(decimal(9,4),100.0*([m].[memory_used_by_table_kb]+[m].[memory_used_by_indexes_kb])/
          NULLIF([m].[memory_allocated_for_table_kb]+[m].[memory_allocated_for_indexes_kb],0)),
       CASE WHEN ([m].[memory_used_by_table_kb]+[m].[memory_used_by_indexes_kb])/1024.0>=@pMinTableMemoryMb THEN ''INFO'' ELSE ''NONE'' END,
       CASE WHEN ([m].[memory_used_by_table_kb]+[m].[memory_used_by_indexes_kb])/1024.0>=@pMinTableMemoryMb THEN ''LARGE_MEMORY_CONSUMER_CONTEXT'' END,
       N''Tabellenspeicher ist eine Momentaufnahme und beweist weder Pooldruck noch zukünftigen Kapazitätsbedarf.''
FROM [sys].[dm_db_xtp_table_memory_stats] [m] WITH (NOLOCK)
JOIN [sys].[tables] [t] WITH (NOLOCK) ON [t].[object_id]=[m].[object_id]
JOIN [sys].[schemas] [s] WITH (NOLOCK) ON [s].[schema_id]=[t].[schema_id]
WHERE [t].[is_ms_shipped]=0'+@SchemaPredicate+@ObjectPredicate+@FullObjectPredicate+N';
SET @pRows=@@ROWCOUNT;';
                SET @Rows=0;
                EXEC [sys].[sp_executesql] @Sql,
                     N'@pDatabaseName sysname,@pRows bigint OUTPUT,@pMinTableMemoryMb decimal(19,2)',
                     @pDatabaseName=@DbName,@pRows=@Rows OUTPUT,@pMinTableMemoryMb=@MinTableMemoryMb;
                INSERT [#InMemoryOltpAnalysis_SourceStatus]
                VALUES(@DbName,'XTP_TABLE_MEMORY','AVAILABLE',0,@Rows,
                       N'VIEW DATABASE STATE; SQL Server 2022+: VIEW DATABASE PERFORMANCE STATE',NULL,NULL,
                       N'Sichtbare speicheroptimierte Tabellen; Nullzeilen können auch aus Filtern oder Metadatensichtbarkeit folgen.');
            END TRY
            BEGIN CATCH
                INSERT [#InMemoryOltpAnalysis_SourceStatus]
                VALUES(@DbName,'XTP_TABLE_MEMORY','ERROR_HANDLED',1,0,
                       N'VIEW DATABASE STATE; SQL Server 2022+: VIEW DATABASE PERFORMANCE STATE',
                       ERROR_NUMBER(),ERROR_MESSAGE(),N'Andere XTP-Quellen werden fortgesetzt.');
            END CATCH;

            BEGIN TRY
                SET @Sql=N'SET LOCK_TIMEOUT '+CONVERT(nvarchar(11),@LockTimeoutMs)+N'; USE '+QUOTENAME(@DbName)+N';
INSERT [#InMemoryOltpAnalysis_MemoryConsumer]
SELECT @pDatabaseName,[memory_consumer_type],[memory_consumer_desc],COUNT_BIG(*),SUM(CONVERT(bigint,[allocation_count])),
       CONVERT(decimal(19,2),SUM(CONVERT(decimal(38,2),[allocated_bytes]))/1048576.0),
       CONVERT(decimal(19,2),SUM(CONVERT(decimal(38,2),[used_bytes]))/1048576.0),
       CONVERT(decimal(9,4),100.0*SUM(CONVERT(decimal(38,2),[used_bytes]))/NULLIF(SUM(CONVERT(decimal(38,2),[allocated_bytes])),0)),
       N''Aggregat nach Consumer-Typ; Typ 0 wird als reine Aggregationszeile ausgelassen und eine Datenbankzuordnung einzelner Verbraucher wird nicht behauptet.''
FROM [sys].[dm_db_xtp_memory_consumers] WITH (NOLOCK)
WHERE [memory_consumer_type]<>0
GROUP BY [memory_consumer_type],[memory_consumer_desc];
SET @pRows=@@ROWCOUNT;';
                SET @Rows=0;
                EXEC [sys].[sp_executesql] @Sql,N'@pDatabaseName sysname,@pRows bigint OUTPUT',@pDatabaseName=@DbName,@pRows=@Rows OUTPUT;
                INSERT [#InMemoryOltpAnalysis_SourceStatus]
                VALUES(@DbName,'XTP_MEMORY_CONSUMERS','AVAILABLE',0,@Rows,
                       N'VIEW DATABASE STATE; SQL Server 2022+: VIEW DATABASE PERFORMANCE STATE',NULL,NULL,
                       N'Aggregierte Consumer-Typen ohne Objekt-, Session- oder Transaktionsidentifikatoren.');
            END TRY
            BEGIN CATCH
                INSERT [#InMemoryOltpAnalysis_SourceStatus]
                VALUES(@DbName,'XTP_MEMORY_CONSUMERS','ERROR_HANDLED',1,0,
                       N'VIEW DATABASE STATE; SQL Server 2022+: VIEW DATABASE PERFORMANCE STATE',
                       ERROR_NUMBER(),ERROR_MESSAGE(),N'Andere XTP-Quellen werden fortgesetzt.');
            END CATCH;

            BEGIN TRY
                SET @Sql=N'SET LOCK_TIMEOUT '+CONVERT(nvarchar(11),@LockTimeoutMs)+N'; USE '+QUOTENAME(@DbName)+N';
INSERT [#InMemoryOltpAnalysis_HashIndex]
SELECT @pDatabaseName,[s].[name],[t].[name],[i].[name],[t].[object_id],[i].[index_id],
       CONVERT(bigint,[i].[bucket_count]),NULL,NULL,NULL,NULL,NULL,
       ''NOT_REQUESTED'',''NONE'',NULL,
       N''Konfigurierte Bucket-Zahl ohne Laufzeitketten; daraus allein folgt keine Fehlkonfiguration.''
FROM [sys].[hash_indexes] [i] WITH (NOLOCK)
JOIN [sys].[tables] [t] WITH (NOLOCK) ON [t].[object_id]=[i].[object_id]
JOIN [sys].[schemas] [s] WITH (NOLOCK) ON [s].[schema_id]=[t].[schema_id]
WHERE [t].[is_ms_shipped]=0'+@SchemaPredicate+@ObjectPredicate+@FullObjectPredicate+N';
SET @pRows=@@ROWCOUNT;';
                SET @Rows=0;
                EXEC [sys].[sp_executesql] @Sql,N'@pDatabaseName sysname,@pRows bigint OUTPUT',@pDatabaseName=@DbName,@pRows=@Rows OUTPUT;
                INSERT [#InMemoryOltpAnalysis_SourceStatus]
                VALUES(@DbName,'XTP_HASH_INDEX_CATALOG','AVAILABLE',0,@Rows,N'Katalogsicht auf sichtbare Hashindizes',NULL,NULL,
                       N'Nur konfigurierte Bucket-Zahl; keine Benutzerdaten oder Schlüsselwerte.');
            END TRY
            BEGIN CATCH
                INSERT [#InMemoryOltpAnalysis_SourceStatus]
                VALUES(@DbName,'XTP_HASH_INDEX_CATALOG','ERROR_HANDLED',1,0,N'Katalogsicht auf sichtbare Hashindizes',
                       ERROR_NUMBER(),ERROR_MESSAGE(),N'Andere XTP-Quellen werden fortgesetzt.');
            END CATCH;

            IF @MitHashIndexStats=0
            BEGIN
                INSERT [#InMemoryOltpAnalysis_SourceStatus]
                VALUES(@DbName,'XTP_HASH_INDEX_STATS','NOT_REQUESTED',0,0,
                       N'VIEW DATABASE STATE; SQL Server 2022+: VIEW DATABASE PERFORMANCE STATE',NULL,NULL,
                       N'Bewusst nicht ausgeführt: Die DMV kann vollständige Tabellen scannen.');
            END
            ELSE IF @HashStatsAllowed=0
            BEGIN
                UPDATE [#InMemoryOltpAnalysis_HashIndex]
                SET [RuntimeStatsStatus]='DENIED_GROUP'
                WHERE [DatabaseName]=@DbName AND [RuntimeStatsStatus]='NOT_REQUESTED';
                INSERT [#InMemoryOltpAnalysis_SourceStatus]
                VALUES(@DbName,'XTP_HASH_INDEX_STATS','DENIED_GROUP',1,0,
                       N'CATALOG_DEEP und VIEW DATABASE STATE; SQL Server 2022+: VIEW DATABASE PERFORMANCE STATE',NULL,
                       N'CATALOG_DEEP ist nicht freigegeben.',N'Basisevidenz bleibt verfügbar; Laufzeitketten wurden nicht gelesen.');
            END
            ELSE
            BEGIN TRY
                SET @Sql=N'SET LOCK_TIMEOUT '+CONVERT(nvarchar(11),@LockTimeoutMs)+N'; USE '+QUOTENAME(@DbName)+N';
UPDATE [h]
SET [TotalBucketCount]=[x].[total_bucket_count],
    [EmptyBucketCount]=[x].[empty_bucket_count],
    [EmptyBucketPercent]=CONVERT(decimal(9,4),100.0*[x].[empty_bucket_count]/NULLIF([x].[total_bucket_count],0)),
    [AverageChainLength]=CONVERT(decimal(19,4),[x].[avg_chain_length]),
    [MaxChainLength]=[x].[max_chain_length],
    [RuntimeStatsStatus]=''AVAILABLE''
FROM [#InMemoryOltpAnalysis_HashIndex] [h]
JOIN [sys].[dm_db_xtp_hash_index_stats] [x] WITH (NOLOCK)
  ON [x].[object_id]=[h].[ObjectId] AND [x].[index_id]=[h].[IndexId]
WHERE [h].[DatabaseName]=@pDatabaseName;
SET @pRows=@@ROWCOUNT;';
                SET @Rows=0;
                EXEC [sys].[sp_executesql] @Sql,N'@pDatabaseName sysname,@pRows bigint OUTPUT',@pDatabaseName=@DbName,@pRows=@Rows OUTPUT;
                UPDATE [#InMemoryOltpAnalysis_HashIndex]
                SET [RuntimeStatsStatus]='NO_RUNTIME_ROW'
                WHERE [DatabaseName]=@DbName AND [RuntimeStatsStatus]='NOT_REQUESTED';
                INSERT [#InMemoryOltpAnalysis_SourceStatus]
                VALUES(@DbName,'XTP_HASH_INDEX_STATS','AVAILABLE',0,@Rows,
                       N'CATALOG_DEEP und VIEW DATABASE STATE; SQL Server 2022+: VIEW DATABASE PERFORMANCE STATE',NULL,NULL,
                       N'Opt-in-Laufzeitketten; die DMV kann vollständige Tabellen scannen.');
            END TRY
            BEGIN CATCH
                UPDATE [#InMemoryOltpAnalysis_HashIndex]
                SET [RuntimeStatsStatus]='ERROR_HANDLED'
                WHERE [DatabaseName]=@DbName AND [RuntimeStatsStatus]='NOT_REQUESTED';
                INSERT [#InMemoryOltpAnalysis_SourceStatus]
                VALUES(@DbName,'XTP_HASH_INDEX_STATS','ERROR_HANDLED',1,0,
                       N'CATALOG_DEEP und VIEW DATABASE STATE; SQL Server 2022+: VIEW DATABASE PERFORMANCE STATE',
                       ERROR_NUMBER(),ERROR_MESSAGE(),N'Basisevidenz bleibt verfügbar; Laufzeitketten fehlen.');
            END CATCH;

            BEGIN TRY
                SET @Sql=N'SET LOCK_TIMEOUT '+CONVERT(nvarchar(11),@LockTimeoutMs)+N'; USE '+QUOTENAME(@DbName)+N';
INSERT [#InMemoryOltpAnalysis_Checkpoint]
SELECT @pDatabaseName,[file_type],[file_type_desc],[state],[state_desc],COUNT_BIG(*),
       CONVERT(decimal(19,2),SUM(CONVERT(decimal(38,2),[file_size_in_bytes]))/1048576.0),
       CONVERT(decimal(19,2),SUM(CONVERT(decimal(38,2),[file_size_used_in_bytes]))/1048576.0),
       SUM(CONVERT(bigint,[logical_row_count])),
       CASE WHEN [state]=8 AND SUM(CONVERT(decimal(38,2),[file_size_in_bytes]))/1048576.0>=@pWarnMb THEN ''WARN'' ELSE ''NONE'' END,
       CASE WHEN [state]=8 AND SUM(CONVERT(decimal(38,2),[file_size_in_bytes]))/1048576.0>=@pWarnMb THEN ''WAITING_LOG_TRUNCATION_REVIEW'' END,
       N''State 8 kann transient sein; Momentaufnahme ohne Verlauf, Log-Reuse-Wait oder Merge-Fortschritt. Keine Dateipfade oder GUIDs ausgegeben.''
FROM [sys].[dm_db_xtp_checkpoint_files] WITH (NOLOCK)
GROUP BY [file_type],[file_type_desc],[state],[state_desc];
SET @pRows=@@ROWCOUNT;';
                SET @Rows=0;
                EXEC [sys].[sp_executesql] @Sql,N'@pDatabaseName sysname,@pRows bigint OUTPUT,@pWarnMb decimal(19,2)',
                     @pDatabaseName=@DbName,@pRows=@Rows OUTPUT,@pWarnMb=@WaitingCheckpointWarnMb;
                INSERT [#InMemoryOltpAnalysis_SourceStatus]
                VALUES(@DbName,'XTP_CHECKPOINT_FILES','AVAILABLE',0,@Rows,
                       N'VIEW DATABASE STATE; SQL Server 2022+: VIEW DATABASE PERFORMANCE STATE',NULL,NULL,
                       N'Aggregat nach Dateiart und Zustand; keine relativen Pfade oder Container-GUIDs.');
            END TRY
            BEGIN CATCH
                INSERT [#InMemoryOltpAnalysis_SourceStatus]
                VALUES(@DbName,'XTP_CHECKPOINT_FILES','ERROR_HANDLED',1,0,
                       N'VIEW DATABASE STATE; SQL Server 2022+: VIEW DATABASE PERFORMANCE STATE',
                       ERROR_NUMBER(),ERROR_MESSAGE(),N'Andere XTP-Quellen werden fortgesetzt.');
            END CATCH;

            BEGIN TRY
                SET @Sql=N'SET LOCK_TIMEOUT '+CONVERT(nvarchar(11),@LockTimeoutMs)+N'; USE '+QUOTENAME(@DbName)+N';
INSERT [#InMemoryOltpAnalysis_Transaction]
SELECT @pDatabaseName,[state],
       CASE [state] WHEN 0 THEN N''ACTIVE'' WHEN 1 THEN N''COMMITTED'' WHEN 2 THEN N''ABORTED'' WHEN 3 THEN N''VALIDATING'' ELSE N''UNKNOWN'' END,
       [result_desc],COUNT_BIG(*),
       CASE WHEN [state] IN(0,3) AND COUNT_BIG(*)>=@pWarnCount THEN ''WARN'' ELSE ''NONE'' END,
       CASE WHEN [state] IN(0,3) AND COUNT_BIG(*)>=@pWarnCount THEN ''ACTIVE_TRANSACTION_VOLUME_REVIEW'' END,
       N''Aggregierte Momentaufnahme ohne Startzeit, Dauer, Session-, Benutzer- oder Transaktionsidentifikatoren.''
FROM [sys].[dm_db_xtp_transactions] WITH (NOLOCK)
GROUP BY [state],[result_desc];
SET @pRows=@@ROWCOUNT;';
                SET @Rows=0;
                EXEC [sys].[sp_executesql] @Sql,N'@pDatabaseName sysname,@pRows bigint OUTPUT,@pWarnCount int',
                     @pDatabaseName=@DbName,@pRows=@Rows OUTPUT,@pWarnCount=@ActiveTransactionWarnCount;
                INSERT [#InMemoryOltpAnalysis_SourceStatus]
                VALUES(@DbName,'XTP_TRANSACTIONS','AVAILABLE',0,@Rows,
                       N'VIEW DATABASE STATE; SQL Server 2022+: VIEW DATABASE PERFORMANCE STATE',NULL,NULL,
                       N'Aggregat nach Status und Ergebnis; keine Session-, Benutzer- oder Transaktionsidentifikatoren.');
            END TRY
            BEGIN CATCH
                INSERT [#InMemoryOltpAnalysis_SourceStatus]
                VALUES(@DbName,'XTP_TRANSACTIONS','ERROR_HANDLED',1,0,
                       N'VIEW DATABASE STATE; SQL Server 2022+: VIEW DATABASE PERFORMANCE STATE',
                       ERROR_NUMBER(),ERROR_MESSAGE(),N'Andere XTP-Quellen werden fortgesetzt.');
            END CATCH;

            FETCH NEXT FROM [DatabaseCursor] INTO @DbName,@CompatibilityLevel;
        END;
        CLOSE [DatabaseCursor];
        DEALLOCATE [DatabaseCursor];

        BEGIN TRY
            ;WITH [PoolUse] AS
            (
                SELECT [resource_pool_id],COUNT_BIG(*) AS [DatabaseCount]
                FROM [sys].[databases] WITH (NOLOCK)
                GROUP BY [resource_pool_id]
            )
            INSERT [#InMemoryOltpAnalysis_ResourcePool]
            SELECT [fs].[DatabaseName],[d].[resource_pool_id],[p].[name],
                   CONVERT(bit,CASE WHEN COALESCE([d].[resource_pool_id],2)=2 THEN 1 ELSE 0 END),
                   [u].[DatabaseCount],[p].[min_memory_percent],[p].[max_memory_percent],
                   CONVERT(decimal(19,2),[p].[max_memory_kb]/1024.0),
                   CONVERT(decimal(19,2),[p].[target_memory_kb]/1024.0),
                   CONVERT(decimal(19,2),[p].[used_memory_kb]/1024.0),
                   CONVERT(decimal(9,4),100.0*[p].[used_memory_kb]/NULLIF([p].[target_memory_kb],0)),
                   [p].[out_of_memory_count],
                   CASE WHEN COALESCE([d].[resource_pool_id],2)<>2
                             AND (COALESCE([p].[out_of_memory_count],0)>0
                                  OR 100.0*[p].[used_memory_kb]/NULLIF([p].[target_memory_kb],0)>=@PoolUsedWarnPercent)
                        THEN 'WARN' ELSE 'INFO' END,
                   CASE WHEN COALESCE([d].[resource_pool_id],2)=2 THEN 'SHARED_DEFAULT_POOL_CONTEXT'
                        WHEN COALESCE([p].[out_of_memory_count],0)>0 THEN 'POOL_OUT_OF_MEMORY_RECORDED'
                        WHEN 100.0*[p].[used_memory_kb]/NULLIF([p].[target_memory_kb],0)>=@PoolUsedWarnPercent THEN 'POOL_MEMORY_PRESSURE_REVIEW'
                        ELSE 'RESOURCE_POOL_CONTEXT' END,
                   N'Poolwerte sind eine Servermomentaufnahme. Der Defaultpool erlaubt keine belastbare Datenbankzuordnung; auch benannte Pools können von mehreren Datenbanken geteilt werden.'
            FROM [#InMemoryOltpAnalysis_FeatureScope] [fs]
            JOIN [sys].[databases] [d] WITH (NOLOCK) ON [d].[name]=[fs].[DatabaseName]
            LEFT JOIN [sys].[dm_resource_governor_resource_pools] [p] WITH (NOLOCK) ON [p].[pool_id]=COALESCE([d].[resource_pool_id],2)
            LEFT JOIN [PoolUse] [u] ON [u].[resource_pool_id]=[d].[resource_pool_id]
            WHERE [fs].[MemoryOptimizedTableCount]+[fs].[MemoryOptimizedTableTypeCount]+[fs].[MemoryOptimizedFilegroupCount]>0;

            INSERT [#InMemoryOltpAnalysis_SourceStatus]
            SELECT [fs].[DatabaseName],'RESOURCE_POOL_MEMORY','AVAILABLE',0,
                   COUNT_BIG([p].[DatabaseName]),N'VIEW SERVER STATE; SQL Server 2022+: VIEW SERVER PERFORMANCE STATE',NULL,NULL,
                   N'Poolweite Momentaufnahme; keine datenbankgenaue Speicherattribution.'
            FROM [#InMemoryOltpAnalysis_FeatureScope] [fs]
            LEFT JOIN [#InMemoryOltpAnalysis_ResourcePool] [p] ON [p].[DatabaseName]=[fs].[DatabaseName]
            WHERE [fs].[MemoryOptimizedTableCount]+[fs].[MemoryOptimizedTableTypeCount]+[fs].[MemoryOptimizedFilegroupCount]>0
            GROUP BY [fs].[DatabaseName];
        END TRY
        BEGIN CATCH
            INSERT [#InMemoryOltpAnalysis_SourceStatus]
            SELECT [DatabaseName],'RESOURCE_POOL_MEMORY','ERROR_HANDLED',1,0,
                   N'VIEW SERVER STATE; SQL Server 2022+: VIEW SERVER PERFORMANCE STATE',
                   ERROR_NUMBER(),ERROR_MESSAGE(),N'XTP-Datenbankquellen bleiben verfügbar.'
            FROM [#InMemoryOltpAnalysis_FeatureScope]
            WHERE [MemoryOptimizedTableCount]+[MemoryOptimizedTableTypeCount]+[MemoryOptimizedFilegroupCount]>0;
        END CATCH;
    END;

    UPDATE [#InMemoryOltpAnalysis_HashIndex]
    SET [Severity]=CASE
          WHEN [RuntimeStatsStatus]<>'AVAILABLE' THEN 'NONE'
          WHEN [AverageChainLength]>@HashAvgChainWarn OR [MaxChainLength]>=@HashMaxChainWarn
               OR [EmptyBucketPercent]<@HashMinEmptyBucketPercent THEN 'WARN'
          ELSE 'NONE' END,
        [FindingCode]=CASE
          WHEN [RuntimeStatsStatus]<>'AVAILABLE' THEN NULL
          WHEN [AverageChainLength]>@HashAvgChainWarn AND [EmptyBucketPercent]>=@HashMinEmptyBucketPercent THEN 'HASH_DUPLICATE_OR_SKEW_REVIEW'
          WHEN [AverageChainLength]>@HashAvgChainWarn AND [EmptyBucketPercent]<@HashMinEmptyBucketPercent THEN 'HASH_BUCKET_COUNT_REVIEW'
          WHEN [MaxChainLength]>=@HashMaxChainWarn THEN 'HASH_MAX_CHAIN_REVIEW'
          WHEN [EmptyBucketPercent]<@HashMinEmptyBucketPercent THEN 'LOW_EMPTY_BUCKET_PERCENT_REVIEW'
          ELSE NULL END,
        [EvidenceLimit]=CASE
          WHEN [RuntimeStatsStatus]='AVAILABLE' THEN N'Bucket- und Kettenwerte sind Momentaufnahmen. Lange Ketten können durch Bucket-Anzahl, Duplikate oder Datenverteilung entstehen; daraus folgt keine automatische DDL.'
          ELSE [EvidenceLimit] END;

    INSERT [#InMemoryOltpAnalysis_Findings]
    ([DatabaseName],[SchemaName],[ObjectName],[IndexName],[Severity],[Confidence],[FindingCode],
     [MetricName],[MetricValue],[ThresholdValue],[Evidence],[EvidenceLimit],[RecommendedNextCheck])
    SELECT [DatabaseName],[SchemaName],[TableName],NULL,'INFO','MEDIUM',[FindingCode],
           'TOTAL_USED_MB',[TotalUsedMb],@MinTableMemoryMb,
           N'Die speicheroptimierte Tabelle überschreitet den konfigurierten Kontextgrenzwert.',[EvidenceLimit],
           N'Poolbindung, Gesamt-XTP-Speicher, Wachstum und Workloadverlauf gemeinsam prüfen.'
    FROM [#InMemoryOltpAnalysis_TableMemory]
    WHERE [FindingCode]='LARGE_MEMORY_CONSUMER_CONTEXT';

    INSERT [#InMemoryOltpAnalysis_Findings]
    ([DatabaseName],[SchemaName],[ObjectName],[IndexName],[Severity],[Confidence],[FindingCode],
     [MetricName],[MetricValue],[ThresholdValue],[Evidence],[EvidenceLimit],[RecommendedNextCheck])
    SELECT [DatabaseName],[SchemaName],[TableName],[IndexName],'WARN','MEDIUM',[FindingCode],
           CASE WHEN [FindingCode]='LOW_EMPTY_BUCKET_PERCENT_REVIEW' THEN 'EMPTY_BUCKET_PERCENT'
                WHEN [FindingCode]='HASH_MAX_CHAIN_REVIEW' THEN 'MAX_CHAIN_LENGTH'
                ELSE 'AVERAGE_CHAIN_LENGTH' END,
           CASE WHEN [FindingCode]='LOW_EMPTY_BUCKET_PERCENT_REVIEW' THEN [EmptyBucketPercent]
                WHEN [FindingCode]='HASH_MAX_CHAIN_REVIEW' THEN [MaxChainLength]
                ELSE [AverageChainLength] END,
           CASE WHEN [FindingCode]='LOW_EMPTY_BUCKET_PERCENT_REVIEW' THEN @HashMinEmptyBucketPercent
                WHEN [FindingCode]='HASH_MAX_CHAIN_REVIEW' THEN @HashMaxChainWarn
                ELSE @HashAvgChainWarn END,
           N'Die opt-in Hashindex-Momentaufnahme überschreitet mindestens einen konfigurierten Prüfgrenzwert.',[EvidenceLimit],
           N'Bucket-Leeranteil, mittlere und maximale Kettenlänge, Duplikate sowie Abfrageprädikate zusammen prüfen; keine automatische DDL ableiten.'
    FROM [#InMemoryOltpAnalysis_HashIndex]
    WHERE [Severity]='WARN';

    INSERT [#InMemoryOltpAnalysis_Findings]
    ([DatabaseName],[Severity],[Confidence],[FindingCode],[MetricName],[MetricValue],[ThresholdValue],
     [Evidence],[EvidenceLimit],[RecommendedNextCheck])
    SELECT [DatabaseName],'WARN','LOW',[FindingCode],'CHECKPOINT_FILE_SIZE_MB',[FileSizeMb],@WaitingCheckpointWarnMb,
           N'Checkpoint-Dateien im Zustand WAITING FOR LOG TRUNCATION überschreiten den konfigurierten Momentaufnahmegrenzwert.',[EvidenceLimit],
           N'Wiederholte Messung, log_reuse_wait_desc, Log-Backupkette und Merge-Fortschritt korrelieren.'
    FROM [#InMemoryOltpAnalysis_Checkpoint] WHERE [Severity]='WARN';

    INSERT [#InMemoryOltpAnalysis_Findings]
    ([DatabaseName],[Severity],[Confidence],[FindingCode],[MetricName],[MetricValue],[ThresholdValue],
     [Evidence],[EvidenceLimit],[RecommendedNextCheck])
    SELECT [DatabaseName],'WARN','LOW',[FindingCode],'ACTIVE_OR_VALIDATING_TRANSACTION_COUNT',[TransactionCount],@ActiveTransactionWarnCount,
           N'Aktive oder validierende XTP-Transaktionen überschreiten den konfigurierten Momentaufnahmegrenzwert.',[EvidenceLimit],
           N'Über Zeit wiederholen und mit zulässiger Laufzeit-, Konflikt- und Workload-Evidenz korrelieren.'
    FROM [#InMemoryOltpAnalysis_Transaction] WHERE [Severity]='WARN';

    INSERT [#InMemoryOltpAnalysis_Findings]
    ([DatabaseName],[Severity],[Confidence],[FindingCode],[MetricName],[MetricValue],[ThresholdValue],
     [Evidence],[EvidenceLimit],[RecommendedNextCheck])
    SELECT [DatabaseName],'WARN','MEDIUM',[FindingCode],
           CASE WHEN [FindingCode]='POOL_OUT_OF_MEMORY_RECORDED' THEN 'OUT_OF_MEMORY_COUNT' ELSE 'POOL_USED_PERCENT_OF_TARGET' END,
           CASE WHEN [FindingCode]='POOL_OUT_OF_MEMORY_RECORDED' THEN [OutOfMemoryCount] ELSE [UsedPercentOfTarget] END,
           CASE WHEN [FindingCode]='POOL_OUT_OF_MEMORY_RECORDED' THEN 0 ELSE @PoolUsedWarnPercent END,
           N'Der zugeordnete oder gemeinsame Resource-Governor-Pool zeigt einen konfigurierten Druckindikator.',[EvidenceLimit],
           N'Poolfreigaben, geteilte Nutzung, Serverspeicher und Zeitverlauf prüfen; keine datenbankgenaue Attribution aus dem Poolwert ableiten.'
    FROM [#InMemoryOltpAnalysis_ResourcePool] WHERE [Severity]='WARN';

    INSERT [#InMemoryOltpAnalysis_Findings]
    ([DatabaseName],[Severity],[Confidence],[FindingCode],[MetricName],[Evidence],[EvidenceLimit],[RecommendedNextCheck])
    SELECT [DatabaseName],'WARN','HIGH','XTP_EVIDENCE_GAP',[SourceCode],
           COALESCE([ErrorMessage],N'Die angeforderte Quelle ist nicht verfügbar.'),
           [Detail],N'Berechtigung, Featureverfügbarkeit und Analysis-Class-Policy prüfen; andere Resultsets bleiben gültig.'
    FROM [#InMemoryOltpAnalysis_SourceStatus]
    WHERE [IsPartial]=1;

    UPDATE [ds]
    SET [SourceFailureCount]=[x].[FailureCount],
        [IsPartial]=CONVERT(bit,CASE WHEN [x].[FailureCount]>0 THEN 1 ELSE 0 END),
        [FindingCount]=[f].[FindingCount],
        [StatusCode]=CASE WHEN [ds].[StatusCode] IN('NOT_APPLICABLE_VISIBLE_SCOPE','UNAVAILABLE_FEATURE','ERROR_HANDLED') THEN [ds].[StatusCode]
                          WHEN [x].[FailureCount]>0 THEN 'AVAILABLE_LIMITED'
                          WHEN [f].[WarnCount]>0 THEN 'AVAILABLE_WITH_FINDING'
                          ELSE 'AVAILABLE' END,
        [Detail]=CASE WHEN [ds].[StatusCode]='PENDING' AND [x].[FailureCount]>0 THEN N'Mindestens eine isolierte Quelle fehlt; zugängliche Teilergebnisse bleiben erhalten.'
                      WHEN [ds].[StatusCode]='PENDING' AND [f].[WarnCount]>0 THEN N'Mindestens ein konfigurierter Prüfhinweis liegt vor; kein automatisches Gesundheitsurteil.'
                      WHEN [ds].[StatusCode]='PENDING' THEN N'Kein konfigurierter Warnindikator in der zugänglichen Momentaufnahme; dies beweist keinen fehlerfreien Zustand.'
                      ELSE [ds].[Detail] END
    FROM [#InMemoryOltpAnalysis_DatabaseStatus] [ds]
    OUTER APPLY
    (
        SELECT COUNT_BIG(*) AS [FailureCount]
        FROM [#InMemoryOltpAnalysis_SourceStatus] [ss]
        WHERE [ss].[DatabaseName]=[ds].[DatabaseName] AND [ss].[IsPartial]=1
    ) [x]
    OUTER APPLY
    (
        SELECT COUNT_BIG(*) AS [FindingCount],
               COALESCE(SUM(CASE WHEN [ff].[Severity]='WARN' THEN CONVERT(bigint,1) ELSE CONVERT(bigint,0) END),0) AS [WarnCount]
        FROM [#InMemoryOltpAnalysis_Findings] [ff]
        WHERE [ff].[DatabaseName]=[ds].[DatabaseName]
    ) [f];

    IF @StatusCode='AVAILABLE'
    BEGIN
        IF EXISTS(SELECT 1 FROM [#InMemoryOltpAnalysis_DatabaseStatus] WHERE [IsPartial]=1)
            SELECT @StatusCode='AVAILABLE_LIMITED',@IsPartial=1;
        ELSE IF EXISTS(SELECT 1 FROM [#InMemoryOltpAnalysis_Findings] WHERE [Severity]='WARN')
            SET @StatusCode='AVAILABLE_WITH_FINDING';
        ELSE IF NOT EXISTS
        (
            SELECT 1 FROM [#InMemoryOltpAnalysis_FeatureScope]
            WHERE [MemoryOptimizedTableCount]+[MemoryOptimizedTableTypeCount]+[MemoryOptimizedFilegroupCount]>0
        )
            SET @StatusCode='NOT_APPLICABLE';
    END;

    SELECT @ErrorNumber=COALESCE(@ErrorNumber,MIN([ErrorNumber])),
           @ErrorMessage=COALESCE(@ErrorMessage,MIN([ErrorMessage]))
    FROM [#InMemoryOltpAnalysis_SourceStatus]
    WHERE [IsPartial]=1;

    IF @JsonErzeugen=1
    BEGIN
        SELECT @Json=(
            SELECT
                JSON_QUERY((SELECT N'USP_InMemoryOltpAnalysis' AS [module],@Now AS [collectedAtUtc],@StatusCode AS [statusCode],@IsPartial AS [isPartial],@ErrorNumber AS [errorNumber],@ErrorMessage AS [errorMessage] FOR JSON PATH,WITHOUT_ARRAY_WRAPPER)) AS [meta],
                JSON_QUERY(COALESCE((SELECT * FROM [#InMemoryOltpAnalysis_DatabaseStatus] ORDER BY [DatabaseName] FOR JSON PATH),N'[]')) AS [databaseStatus],
                JSON_QUERY(COALESCE((SELECT * FROM [#InMemoryOltpAnalysis_SourceStatus] ORDER BY [DatabaseName],[SourceCode] FOR JSON PATH),N'[]')) AS [sourceStatus],
                JSON_QUERY(COALESCE((SELECT TOP(@Limit) * FROM [#InMemoryOltpAnalysis_Findings] WHERE @NurProblematisch=0 OR [Severity]='WARN' ORDER BY CASE [Severity] WHEN 'WARN' THEN 1 ELSE 2 END,[FindingOrdinal] FOR JSON PATH),N'[]')) AS [findings],
                JSON_QUERY(COALESCE((SELECT TOP(@Limit) * FROM [#InMemoryOltpAnalysis_TableMemory] WHERE @NurProblematisch=0 OR [Severity]='WARN' ORDER BY [TotalUsedMb] DESC,[DatabaseName],[SchemaName],[TableName] FOR JSON PATH),N'[]')) AS [tableMemory],
                JSON_QUERY(COALESCE((SELECT TOP(@Limit) * FROM [#InMemoryOltpAnalysis_HashIndex] WHERE @NurProblematisch=0 OR [Severity]='WARN' ORDER BY CASE [Severity] WHEN 'WARN' THEN 1 ELSE 2 END,[DatabaseName],[SchemaName],[TableName],[IndexName] FOR JSON PATH),N'[]')) AS [hashIndexes],
                JSON_QUERY(COALESCE((SELECT TOP(@Limit) * FROM [#InMemoryOltpAnalysis_MemoryConsumer] WHERE @NurProblematisch=0 ORDER BY [UsedMb] DESC,[DatabaseName] FOR JSON PATH),N'[]')) AS [memoryConsumers],
                JSON_QUERY(COALESCE((SELECT TOP(@Limit) * FROM [#InMemoryOltpAnalysis_Checkpoint] WHERE @NurProblematisch=0 OR [Severity]='WARN' ORDER BY CASE [Severity] WHEN 'WARN' THEN 1 ELSE 2 END,[DatabaseName],[State],[FileType] FOR JSON PATH),N'[]')) AS [checkpointFiles],
                JSON_QUERY(COALESCE((SELECT TOP(@Limit) * FROM [#InMemoryOltpAnalysis_Transaction] WHERE @NurProblematisch=0 OR [Severity]='WARN' ORDER BY CASE [Severity] WHEN 'WARN' THEN 1 ELSE 2 END,[DatabaseName],[TransactionState] FOR JSON PATH),N'[]')) AS [transactions],
                JSON_QUERY(COALESCE((SELECT TOP(@Limit) * FROM [#InMemoryOltpAnalysis_ResourcePool] WHERE @NurProblematisch=0 OR [Severity]='WARN' ORDER BY CASE [Severity] WHEN 'WARN' THEN 1 ELSE 2 END,[DatabaseName] FOR JSON PATH),N'[]')) AS [resourcePools]
            FOR JSON PATH,WITHOUT_ARRAY_WRAPPER);
    END;

    IF @OutputMode<>'NONE'
    BEGIN
        SELECT N'USP_InMemoryOltpAnalysis' AS [Module],@Now AS [CollectedAtUtc],@StatusCode AS [StatusCode],
               @IsPartial AS [IsPartial],@ErrorNumber AS [ErrorNumber],@ErrorMessage AS [ErrorMessage],
               N'Momentaufnahme und Prüfhinweise; keine automatische DDL-, Daten- oder Gesundheitsentscheidung.' AS [Detail];
        SELECT * FROM [#InMemoryOltpAnalysis_DatabaseStatus] ORDER BY [DatabaseName];
        SELECT * FROM [#InMemoryOltpAnalysis_SourceStatus] ORDER BY [DatabaseName],[SourceCode];
        SELECT TOP(@Limit) * FROM [#InMemoryOltpAnalysis_Findings]
        WHERE @NurProblematisch=0 OR [Severity]='WARN'
        ORDER BY CASE [Severity] WHEN 'WARN' THEN 1 ELSE 2 END,[FindingOrdinal];
        SELECT TOP(@Limit) * FROM [#InMemoryOltpAnalysis_TableMemory]
        WHERE @NurProblematisch=0 OR [Severity]='WARN'
        ORDER BY [TotalUsedMb] DESC,[DatabaseName],[SchemaName],[TableName];
        SELECT TOP(@Limit) * FROM [#InMemoryOltpAnalysis_HashIndex]
        WHERE @NurProblematisch=0 OR [Severity]='WARN'
        ORDER BY CASE [Severity] WHEN 'WARN' THEN 1 ELSE 2 END,[DatabaseName],[SchemaName],[TableName],[IndexName];
        SELECT TOP(@Limit) * FROM [#InMemoryOltpAnalysis_MemoryConsumer]
        WHERE @NurProblematisch=0
        ORDER BY [UsedMb] DESC,[DatabaseName];
        SELECT TOP(@Limit) * FROM [#InMemoryOltpAnalysis_Checkpoint]
        WHERE @NurProblematisch=0 OR [Severity]='WARN'
        ORDER BY CASE [Severity] WHEN 'WARN' THEN 1 ELSE 2 END,[DatabaseName],[State],[FileType];
        SELECT TOP(@Limit) * FROM [#InMemoryOltpAnalysis_Transaction]
        WHERE @NurProblematisch=0 OR [Severity]='WARN'
        ORDER BY CASE [Severity] WHEN 'WARN' THEN 1 ELSE 2 END,[DatabaseName],[TransactionState];
        SELECT TOP(@Limit) * FROM [#InMemoryOltpAnalysis_ResourcePool]
        WHERE @NurProblematisch=0 OR [Severity]='WARN'
        ORDER BY CASE [Severity] WHEN 'WARN' THEN 1 ELSE 2 END,[DatabaseName];
    END;

    IF @PrintMeldungen=1 AND @StatusCode NOT IN('AVAILABLE','NOT_APPLICABLE')
    BEGIN
        SET @PrintMessage=LEFT(CONCAT(N'USP_InMemoryOltpAnalysis: ',@StatusCode,N'. ',COALESCE(@ErrorMessage,N'Siehe strukturierte Quellenstatus.')),2048);
        RAISERROR(N'%s',10,1,@PrintMessage) WITH NOWAIT;
    END;

    SELECT @StatusCodeOut=@StatusCode,@IsPartialOut=@IsPartial,
           @ErrorNumberOut=@ErrorNumber,@ErrorMessageOut=@ErrorMessage;
    IF @ConsoleResultRequested = 1
    BEGIN
        EXEC [monitor].[InternalEmitConsoleResult]
              @SourceTable=N'#InMemoryOltpAnalysis_Findings'
            , @ResultLabel=N'InMemoryOltpAnalysis'
            , @EmptyMessage=N'Keine fachlichen Ergebnisse';
    END;
    IF @TableResultRequested = 1
    BEGIN
        EXEC [monitor].[InternalWriteResultTable]
              @SourceTable = N'#InMemoryOltpAnalysis_Findings'
            , @TargetTable=@TableTarget
            , @ThrowOnError = 1;
    END;
END;
GO
-- END SOURCE: Code/09_VersionAdaptive/030_USP_InMemoryOltpAnalysis.sql

-- BEGIN SOURCE: Code/09_VersionAdaptive/040_USP_TemporalAnalysis.sql
/*
===============================================================================
Objekt       : monitor.USP_TemporalAnalysis
Version      : 1.0.0
Stand        : 2026-07-17
Typ          : Stored Procedure
Zweck        : Analysiert sichtbare systemversionierte Temporal Tables,
               Retention-Konfiguration, ungefähre Kapazität und die
               Perioden-Indexabdeckung ihrer History-Tabellen.
SQL-Version  : SQL Server 2019 oder neuer.
Datenquellen : sys.tables, sys.schemas, sys.periods, sys.columns, sys.databases,
               sys.indexes, sys.index_columns und sys.dm_db_partition_stats.
Methodik     : Feature-Gate und jede abhängige Quelle werden datenbankweise
               best effort ausgewertet. Fehlende Rechte verwerfen andere
               zugängliche Evidenz nicht.
Grenzen      : Keine Zeilen aus aktuellen oder historischen Benutzertabellen,
               keine DBCC-Prüfung und keine DDL. Katalog- und Größenmetadaten
               beweisen weder Periodenüberlappungsfreiheit noch erfolgreichen
               Cleanup. Nach SYSTEM_VERSIONING=OFF getrennte Tabellen sind ohne
               erhaltene Zuordnung nicht zuverlässig als ehemaliges Paar
               erkennbar.
Kosten       : MEDIUM; Katalogabfragen und approximative Partitionsstatistik.
===============================================================================
*/
CREATE OR ALTER PROCEDURE [monitor].[USP_TemporalAnalysis]
      @DatabaseNames                    nvarchar(max)  = NULL
    , @SystemdatenbankenEinbeziehen     bit            = 0
    , @DatabaseNamePattern              nvarchar(4000) = NULL
    , @HighImpactConfirmed              bit            = 0
    , @SchemaNames                      nvarchar(max)  = NULL
    , @SchemaNamePattern                nvarchar(4000) = NULL
    , @ObjectNames                      nvarchar(max)  = NULL
    , @ObjectNamePattern                nvarchar(4000) = NULL
    , @FullObjectNames                  nvarchar(max)  = NULL
    , @NurProblematisch                 bit            = 0
    , @HistorySizeWarnMb                decimal(19,2)  = 10240
    , @HistoryRowsWarn                  bigint         = 10000000
    , @HistoryToCurrentRatioWarn        decimal(19,4)  = 10
    , @MinHistoryMbForRatioWarn         decimal(19,2)  = 100
    , @MaxZeilen                        int            = 2000
    , @LockTimeoutMs                    int            = 0
    , @ResultSetArt                     varchar(16)     = 'CONSOLE'
    , @ResultTablesJson               nvarchar(max) = NULL
    , @JsonErzeugen                     bit            = 0
    , @Json                             nvarchar(max)   = NULL OUTPUT
    , @PrintMeldungen                   bit            = 1
    , @Hilfe                            bit            = 0
    , @StatusCodeOut                    varchar(40)     = NULL OUTPUT
    , @IsPartialOut                     bit            = NULL OUTPUT
    , @ErrorNumberOut                   int            = NULL OUTPUT
    , @ErrorMessageOut                  nvarchar(2048)  = NULL OUTPUT
AS
BEGIN
    SET NOCOUNT ON;
    SET @Json=NULL;

    DECLARE @Now datetime2(3)=SYSUTCDATETIME();
    DECLARE @Major int=TRY_CONVERT(int,SERVERPROPERTY(N'ProductMajorVersion'));
    DECLARE @OutputMode varchar(16)=UPPER(LTRIM(RTRIM(COALESCE(@ResultSetArt,''))));
    DECLARE @TableResultRequested bit = CASE WHEN @OutputMode = 'TABLE' THEN 1 ELSE 0 END;
    DECLARE @ConsoleResultRequested bit = CASE WHEN @OutputMode = 'CONSOLE' THEN 1 ELSE 0 END;
    DECLARE @TableTarget sysname=NULL;
    IF @TableResultRequested=0 AND NULLIF(LTRIM(RTRIM(COALESCE(@ResultTablesJson,N''))),N'') IS NOT NULL THROW 51011,N'@ResultTablesJson ist ausschließlich mit @ResultSetArt=TABLE zulässig.',1;
    IF @TableResultRequested=1 EXEC [monitor].[InternalPrepareSingleResultTable] @ResultTablesJson=@ResultTablesJson,@ResultName=N'findings',@TargetTable=@TableTarget OUTPUT,@ThrowOnError=1;
    IF @TableResultRequested = 1 OR @ConsoleResultRequested = 1 SET @OutputMode = 'NONE';
    DECLARE @StatusCode varchar(40)='AVAILABLE';
    DECLARE @IsPartial bit=0;
    DECLARE @ErrorNumber int=NULL;
    DECLARE @ErrorMessage nvarchar(2048)=NULL;
    DECLARE @PrintMessage nvarchar(2048)=NULL;
    DECLARE @Limit bigint=CASE WHEN @MaxZeilen IS NULL OR @MaxZeilen=0
                               THEN CONVERT(bigint,9223372036854775807)
                               ELSE CONVERT(bigint,@MaxZeilen) END;

    IF @Hilfe=1
    BEGIN
        PRINT N'monitor.USP_TemporalAnalysis';
        PRINT N'Die Procedure führt eine rein lesende Tiefenanalyse sichtbarer systemversionierter Temporal Tables und zugeordneter History-Tabellen durch.';
        PRINT N'Geprüft werden Katalogzuordnung, Periodenmetadaten, Retention-Schalter, approximative Größe/Zeilen und History-Indexreihenfolge End/Start.';
        PRINT N'Exakte Namenslisten und Pattern derselben Eigenschaft sind gegenseitig exklusiv; Pattern: LIKE, regex: oder regexi:.';
        PRINT N'Grenzwerte erzeugen Prüfkontext, keine automatische Retention-, DDL- oder Kapazitätsentscheidung.';
        PRINT N'@ResultSetArt=CONSOLE|RAW|TABLE|NONE; TABLE verwendet @ResultTablesJson; @JsonErzeugen=1 erzeugt @Json OUTPUT.';
        PRINT N'Es werden keine Zeilen aus aktuellen oder historischen Benutzertabellen gelesen und keine zeitliche Datenkonsistenz behauptet.';
        RETURN;
    END;

    IF @SystemdatenbankenEinbeziehen IS NULL OR @NurProblematisch IS NULL
       OR @JsonErzeugen IS NULL OR @PrintMeldungen IS NULL
       OR @HistorySizeWarnMb IS NULL OR @HistorySizeWarnMb<0
       OR @HistoryRowsWarn IS NULL OR @HistoryRowsWarn<0
       OR @HistoryToCurrentRatioWarn IS NULL OR @HistoryToCurrentRatioWarn<=0
       OR @MinHistoryMbForRatioWarn IS NULL OR @MinHistoryMbForRatioWarn<0

       OR @MaxZeilen IS NULL OR @MaxZeilen<0
       OR @LockTimeoutMs IS NULL OR @LockTimeoutMs NOT BETWEEN 0 AND 60000
       OR @OutputMode NOT IN('CONSOLE','RAW','NONE')
    BEGIN
        SELECT @StatusCode='INVALID_PARAMETER',@IsPartial=1,
               @ErrorMessage=N'Ungültiger Bit-, Grenzwert-, Mengen-, Lock-Timeout- oder Ausgabeparameter.';
    END;

    DECLARE @SchemaPatternMode varchar(8),@SchemaPatternValue nvarchar(4000),@SchemaRegexFlags varchar(8),@SchemaPatternValid bit;
    DECLARE @ObjectPatternMode varchar(8),@ObjectPatternValue nvarchar(4000),@ObjectRegexFlags varchar(8),@ObjectPatternValid bit;
    SELECT @SchemaPatternMode=[PatternMode],@SchemaPatternValue=[PatternValue],@SchemaRegexFlags=[RegexFlags],@SchemaPatternValid=[IsValid]
    FROM [monitor].[TVF_ParsePattern](@SchemaNamePattern);
    SELECT @ObjectPatternMode=[PatternMode],@ObjectPatternValue=[PatternValue],@ObjectRegexFlags=[RegexFlags],@ObjectPatternValid=[IsValid]
    FROM [monitor].[TVF_ParsePattern](@ObjectNamePattern);

    IF @StatusCode='AVAILABLE'
       AND (@SchemaPatternValid=0 OR @ObjectPatternValid=0
            OR (@SchemaNames IS NOT NULL AND @SchemaNamePattern IS NOT NULL)
            OR (@ObjectNames IS NOT NULL AND @ObjectNamePattern IS NOT NULL))
    BEGIN
        SELECT @StatusCode='INVALID_PARAMETER',@IsPartial=1,
               @ErrorMessage=N'Pattern ungültig oder exakte Liste und Pattern derselben Eigenschaft gleichzeitig angegeben.';
    END;

    IF @StatusCode='AVAILABLE'
       AND (@SchemaPatternMode IN('REGEX','REGEXI') OR @ObjectPatternMode IN('REGEX','REGEXI'))
       AND COALESCE(@Major,0)<17
    BEGIN
        SELECT @StatusCode='UNAVAILABLE_VERSION',@IsPartial=1,
               @ErrorMessage=N'Regex-Pattern benötigen SQL Server 2025 oder neuer und Compatibility Level 170.';
    END;

    CREATE TABLE [#TemporalAnalysis_NameFilters]
    (
          [FilterType] varchar(20) COLLATE SQL_Latin1_General_CP1_CS_AS NOT NULL
        , [ItemOrdinal] int NOT NULL
        , [NameValue] sysname COLLATE SQL_Latin1_General_CP1_CS_AS NULL
        , [DatabaseName] sysname COLLATE SQL_Latin1_General_CP1_CS_AS NULL
        , [SchemaName] sysname COLLATE SQL_Latin1_General_CP1_CS_AS NULL
        , [ObjectName] sysname COLLATE SQL_Latin1_General_CP1_CS_AS NULL
    );
    CREATE TABLE [#TemporalAnalysis_DatabaseCandidates]
    (
          [DatabaseId] int NOT NULL
        , [DatabaseName] sysname NOT NULL
        , [StateDesc] nvarchar(60) NULL
        , [UserAccessDesc] nvarchar(60) NULL
        , [IsReadOnly] bit NULL
        , [CompatibilityLevel] tinyint NULL
        , [CollationName] sysname NULL
        , [RecoveryModelDesc] nvarchar(60) NULL
        , [IsSystemDatabase] bit NULL
        , [RequestedOrdinal] int NULL
    );
    CREATE TABLE [#TemporalAnalysis_DatabaseCandidateWarnings]
    (
          [RequestedName] sysname COLLATE SQL_Latin1_General_CP1_CS_AS NULL
        , [StatusCode] varchar(40) NOT NULL
        , [ErrorMessage] nvarchar(2048) NOT NULL
    );
    CREATE TABLE [#TemporalAnalysis_FeatureScope]
    (
          [DatabaseName] sysname NOT NULL PRIMARY KEY
        , [TemporalTableCount] bigint NOT NULL
        , [HistoryTableCount] bigint NOT NULL
    );
    CREATE TABLE [#TemporalAnalysis_DatabaseStatus]
    (
          [DatabaseName] sysname NULL
        , [StatusCode] varchar(40) NOT NULL
        , [IsPartial] bit NOT NULL
        , [TemporalTableCount] bigint NOT NULL
        , [HistoryTableCount] bigint NOT NULL
        , [SourceFailureCount] int NOT NULL
        , [FindingCount] bigint NOT NULL
        , [RequiredPermission] nvarchar(256) NULL
        , [ErrorNumber] int NULL
        , [ErrorMessage] nvarchar(2048) NULL
        , [Detail] nvarchar(2000) NULL
    );
    CREATE TABLE [#TemporalAnalysis_SourceStatus]
    (
          [DatabaseName] sysname NULL
        , [SourceCode] varchar(64) NOT NULL
        , [StatusCode] varchar(40) NOT NULL
        , [IsPartial] bit NOT NULL
        , [RowCount] bigint NOT NULL
        , [RequiredPermission] nvarchar(256) NULL
        , [ErrorNumber] int NULL
        , [ErrorMessage] nvarchar(2048) NULL
        , [Detail] nvarchar(2000) NULL
    );
    CREATE TABLE [#TemporalAnalysis_TemporalTable]
    (
          [DatabaseName] sysname NOT NULL
        , [CurrentSchemaName] sysname NOT NULL
        , [CurrentTableName] sysname NOT NULL
        , [CurrentObjectId] int NOT NULL
        , [HistorySchemaName] sysname NULL
        , [HistoryTableName] sysname NULL
        , [HistoryObjectId] int NULL
        , [PeriodStartColumnName] sysname NULL
        , [PeriodEndColumnName] sysname NULL
        , [PeriodStartIsHidden] bit NULL
        , [PeriodEndIsHidden] bit NULL
        , [CurrentIsMemoryOptimized] bit NOT NULL
        , [CurrentDurabilityDesc] nvarchar(60) NULL
        , [DatabaseRetentionEnabled] bit NULL
        , [HistoryRetentionPeriod] int NULL
        , [HistoryRetentionUnitDesc] nvarchar(10) NULL
        , [RetentionMode] varchar(16) NOT NULL
        , [CurrentRowsApprox] bigint NULL
        , [HistoryRowsApprox] bigint NULL
        , [CurrentReservedMb] decimal(19,2) NULL
        , [CurrentUsedMb] decimal(19,2) NULL
        , [HistoryReservedMb] decimal(19,2) NULL
        , [HistoryUsedMb] decimal(19,2) NULL
        , [HistoryToCurrentRowRatio] decimal(19,4) NULL
        , [HistoryIndexCount] int NULL
        , [HasPeriodLeadingHistoryIndex] bit NULL
        , [AssessmentStatus] varchar(32) NOT NULL
        , [EvidenceLimit] nvarchar(1000) NOT NULL
        , PRIMARY KEY ([DatabaseName],[CurrentObjectId])
    );
    CREATE TABLE [#TemporalAnalysis_HistoryIndex]
    (
          [DatabaseName] sysname NOT NULL
        , [CurrentSchemaName] sysname NOT NULL
        , [CurrentTableName] sysname NOT NULL
        , [HistorySchemaName] sysname NOT NULL
        , [HistoryTableName] sysname NOT NULL
        , [IndexName] sysname NULL
        , [IndexId] int NOT NULL
        , [IndexTypeDesc] nvarchar(60) NOT NULL
        , [IsUnique] bit NOT NULL
        , [IsDisabled] bit NOT NULL
        , [FirstKeyColumnName] sysname NULL
        , [SecondKeyColumnName] sysname NULL
        , [IsPeriodLeadingIndex] bit NOT NULL
        , [EvidenceLimit] nvarchar(1000) NOT NULL
    );
    CREATE TABLE [#TemporalAnalysis_Findings]
    (
          [FindingOrdinal] bigint IDENTITY(1,1) NOT NULL
        , [DatabaseName] sysname NULL
        , [SchemaName] sysname NULL
        , [ObjectName] sysname NULL
        , [HistorySchemaName] sysname NULL
        , [HistoryTableName] sysname NULL
        , [Severity] varchar(16) NOT NULL
        , [Confidence] varchar(16) NOT NULL
        , [FindingCode] varchar(120) NOT NULL
        , [MetricName] varchar(80) NOT NULL
        , [MetricValue] decimal(38,4) NULL
        , [ThresholdValue] decimal(38,4) NULL
        , [Evidence] nvarchar(1000) NOT NULL
        , [EvidenceLimit] nvarchar(1000) NOT NULL
        , [RecommendedNextCheck] nvarchar(1000) NOT NULL
    );

    -- Lokale TempDB-DDL soll nicht an einer flüchtigen Metadatenkollision mit
    -- dem für fachliche Quellen gewünschten NOWAIT-Vertrag scheitern. Erst
    -- nach vollständiger Materialisierung der Arbeitsstrukturen wird NOWAIT
    -- für die leichten Framework-/Katalogzugriffe aktiviert. Die isolierten
    -- datenbanklokalen Child-Batches verwenden weiterhin @LockTimeoutMs.
    SET LOCK_TIMEOUT 0;

    IF @StatusCode='AVAILABLE'
    BEGIN
        EXEC [monitor].[USP_PrepareNameFilters]
              @SchemaNames=@SchemaNames
            , @ObjectNames=@ObjectNames
            , @FullObjectNames=@FullObjectNames
            , @IndexNames=NULL
            , @StatisticsNames=NULL
            , @ColumnNames=NULL
            , @StatusCode=@StatusCode OUTPUT
            , @ErrorMessage=@ErrorMessage OUTPUT,@FilterTable=N'#TemporalAnalysis_NameFilters';
        IF @StatusCode<>'AVAILABLE' SET @IsPartial=1;
    END;

    DECLARE @CrossDatabaseRequested bit=0;
    IF @StatusCode='AVAILABLE'
    BEGIN
        EXEC [monitor].[USP_PrepareDatabaseCandidates]
              @DatabaseNames=@DatabaseNames
            , @SystemdatenbankenEinbeziehen=@SystemdatenbankenEinbeziehen
            , @DatabaseNamePattern=@DatabaseNamePattern,@HighImpactConfirmed=@HighImpactConfirmed

            , @AnalysisClass='CATALOG_DEEP'
            , @StatusCode=@StatusCode OUTPUT
            , @ErrorMessage=@ErrorMessage OUTPUT
            , @CrossDatabaseRequested=@CrossDatabaseRequested OUTPUT,@CandidateTable=N'#TemporalAnalysis_DatabaseCandidates',@WarningTable=N'#TemporalAnalysis_DatabaseCandidateWarnings';
        IF @StatusCode<>'AVAILABLE' SET @IsPartial=1;
    END;

    INSERT [#TemporalAnalysis_DatabaseStatus]
    ([DatabaseName],[StatusCode],[IsPartial],[TemporalTableCount],[HistoryTableCount],
     [SourceFailureCount],[FindingCount],[Detail])
    SELECT [DatabaseName],'PENDING',0,0,0,0,0,
           N'Feature-Gate und Temporal-Quellen werden datenbankweise best effort ausgewertet.'
    FROM [#TemporalAnalysis_DatabaseCandidates];

    INSERT [#TemporalAnalysis_DatabaseStatus]
    ([DatabaseName],[StatusCode],[IsPartial],[TemporalTableCount],[HistoryTableCount],
     [SourceFailureCount],[FindingCount],[ErrorMessage],[Detail])
    SELECT [RequestedName],[StatusCode],1,0,0,1,0,[ErrorMessage],N'Explizit angeforderte Datenbank nicht auswertbar.'
    FROM [#TemporalAnalysis_DatabaseCandidateWarnings];

    IF @StatusCode='AVAILABLE' AND NOT EXISTS(SELECT 1 FROM [#TemporalAnalysis_DatabaseCandidates])
    BEGIN
        SELECT @StatusCode='NOT_APPLICABLE',@ErrorMessage=N'Keine auswertbare Datenbank im gewählten Scope.';
    END;

    DECLARE @SchemaPredicate nvarchar(max)=
        N' AND (NOT EXISTS(SELECT 1 FROM [#TemporalAnalysis_NameFilters] WHERE [FilterType]=''SCHEMA'') OR EXISTS(SELECT 1 FROM [#TemporalAnalysis_NameFilters] [f] WHERE [f].[FilterType]=''SCHEMA'' AND [f].[NameValue]=[s].[name] COLLATE SQL_Latin1_General_CP1_CS_AS))';
    DECLARE @ObjectPredicate nvarchar(max)=
        N' AND (NOT EXISTS(SELECT 1 FROM [#TemporalAnalysis_NameFilters] WHERE [FilterType]=''OBJECT'') OR EXISTS(SELECT 1 FROM [#TemporalAnalysis_NameFilters] [f] WHERE [f].[FilterType]=''OBJECT'' AND [f].[NameValue]=[t].[name] COLLATE SQL_Latin1_General_CP1_CS_AS))';
    DECLARE @FullObjectPredicate nvarchar(max)=
        N' AND (NOT EXISTS(SELECT 1 FROM [#TemporalAnalysis_NameFilters] WHERE [FilterType]=''FULL_OBJECT'') OR EXISTS(SELECT 1 FROM [#TemporalAnalysis_NameFilters] [f] WHERE [f].[FilterType]=''FULL_OBJECT'' AND ([f].[DatabaseName] IS NULL OR [f].[DatabaseName]=@pDatabaseName COLLATE SQL_Latin1_General_CP1_CS_AS) AND ([f].[SchemaName] IS NULL OR [f].[SchemaName]=[s].[name] COLLATE SQL_Latin1_General_CP1_CS_AS) AND [f].[ObjectName]=[t].[name] COLLATE SQL_Latin1_General_CP1_CS_AS))';
    IF @SchemaPatternMode='LIKE'
        SET @SchemaPredicate+=N' AND [s].[name] COLLATE SQL_Latin1_General_CP1_CS_AS LIKE N'''+REPLACE(@SchemaPatternValue,N'''',N'''''')+N''' COLLATE SQL_Latin1_General_CP1_CS_AS';
    IF @SchemaPatternMode IN('REGEX','REGEXI')
        SET @SchemaPredicate+=N' AND REGEXP_LIKE([s].[name],N'''+REPLACE(@SchemaPatternValue,N'''',N'''''')+N''','''+@SchemaRegexFlags+N''')';
    IF @ObjectPatternMode='LIKE'
        SET @ObjectPredicate+=N' AND [t].[name] COLLATE SQL_Latin1_General_CP1_CS_AS LIKE N'''+REPLACE(@ObjectPatternValue,N'''',N'''''')+N''' COLLATE SQL_Latin1_General_CP1_CS_AS';
    IF @ObjectPatternMode IN('REGEX','REGEXI')
        SET @ObjectPredicate+=N' AND REGEXP_LIKE([t].[name],N'''+REPLACE(@ObjectPatternValue,N'''',N'''''')+N''','''+@ObjectRegexFlags+N''')';

    IF @StatusCode='AVAILABLE'
    BEGIN
        DECLARE @DbName sysname,@CompatibilityLevel int,@Sql nvarchar(max),@Rows bigint;
        DECLARE [DatabaseCursor] CURSOR LOCAL FAST_FORWARD FOR
            SELECT [DatabaseName],[CompatibilityLevel]
            FROM [#TemporalAnalysis_DatabaseCandidates]
            ORDER BY COALESCE([RequestedOrdinal],[DatabaseId]),[DatabaseId];
        OPEN [DatabaseCursor];
        FETCH NEXT FROM [DatabaseCursor] INTO @DbName,@CompatibilityLevel;

        WHILE @@FETCH_STATUS=0
        BEGIN
            IF (@SchemaPatternMode IN('REGEX','REGEXI') OR @ObjectPatternMode IN('REGEX','REGEXI'))
               AND COALESCE(@CompatibilityLevel,0)<170
            BEGIN
                UPDATE [#TemporalAnalysis_DatabaseStatus]
                SET [StatusCode]='UNAVAILABLE_FEATURE',[IsPartial]=1,[SourceFailureCount]=1,
                    [ErrorMessage]=N'Regex-Pattern benötigen Compatibility Level 170.',
                    [Detail]=N'Für diese Datenbank wurde wegen inkompatiblem Patternvertrag keine Analyse ausgeführt.'
                WHERE [DatabaseName]=@DbName;
                INSERT [#TemporalAnalysis_SourceStatus]
                VALUES(@DbName,'FILTER_CONTRACT','UNAVAILABLE_FEATURE',1,0,NULL,NULL,
                       N'Regex-Pattern benötigen Compatibility Level 170.',N'Keine Quellenabfrage ausgeführt.');
                FETCH NEXT FROM [DatabaseCursor] INTO @DbName,@CompatibilityLevel;
                CONTINUE;
            END;

            BEGIN TRY
                SET @Sql=N'SET LOCK_TIMEOUT '+CONVERT(nvarchar(11),@LockTimeoutMs)+N'; USE '+QUOTENAME(@DbName)+N';
INSERT [#TemporalAnalysis_FeatureScope]([DatabaseName],[TemporalTableCount],[HistoryTableCount])
SELECT @pDatabaseName,
       COALESCE(SUM(CASE WHEN [temporal_type]=2 THEN CONVERT(bigint,1) ELSE CONVERT(bigint,0) END),0),
       COALESCE(SUM(CASE WHEN [temporal_type]=1 THEN CONVERT(bigint,1) ELSE CONVERT(bigint,0) END),0)
FROM [sys].[tables] WITH (NOLOCK)
WHERE [is_ms_shipped]=0;
SET @pRows=@@ROWCOUNT;';
                SET @Rows=0;
                EXEC [sys].[sp_executesql] @Sql,N'@pDatabaseName sysname,@pRows bigint OUTPUT',
                     @pDatabaseName=@DbName,@pRows=@Rows OUTPUT;
                INSERT [#TemporalAnalysis_SourceStatus]
                VALUES(@DbName,'TEMPORAL_FEATURE_GATE','AVAILABLE',0,@Rows,
                       N'Katalogsicht auf sichtbare Datenbankmetadaten',NULL,NULL,
                       N'Zählt sichtbare aktuelle Temporal- und zugeordnete History-Tabellen; keine Nutzdaten.');
                UPDATE [ds]
                SET [TemporalTableCount]=[fs].[TemporalTableCount],
                    [HistoryTableCount]=[fs].[HistoryTableCount]
                FROM [#TemporalAnalysis_DatabaseStatus] [ds]
                JOIN [#TemporalAnalysis_FeatureScope] [fs] ON [fs].[DatabaseName]=[ds].[DatabaseName]
                WHERE [ds].[DatabaseName]=@DbName;
            END TRY
            BEGIN CATCH
                INSERT [#TemporalAnalysis_SourceStatus]
                VALUES(@DbName,'TEMPORAL_FEATURE_GATE','ERROR_HANDLED',1,0,
                       N'Katalogsicht auf sichtbare Datenbankmetadaten',ERROR_NUMBER(),ERROR_MESSAGE(),
                       N'Feature-Sichtbarkeit konnte nicht bestimmt werden.');
                UPDATE [#TemporalAnalysis_DatabaseStatus]
                SET [StatusCode]='ERROR_HANDLED',[IsPartial]=1,[SourceFailureCount]=[SourceFailureCount]+1,
                    [ErrorNumber]=ERROR_NUMBER(),[ErrorMessage]=ERROR_MESSAGE(),
                    [Detail]=N'Feature-Gate fehlgeschlagen; keine belastbare Anwendbarkeitsaussage.'
                WHERE [DatabaseName]=@DbName;
            END CATCH;

            IF NOT EXISTS(SELECT 1 FROM [#TemporalAnalysis_FeatureScope] WHERE [DatabaseName]=@DbName)
            BEGIN
                FETCH NEXT FROM [DatabaseCursor] INTO @DbName,@CompatibilityLevel;
                CONTINUE;
            END;

            IF EXISTS
            (
                SELECT 1 FROM [#TemporalAnalysis_FeatureScope]
                WHERE [DatabaseName]=@DbName AND [TemporalTableCount]=0
            )
            BEGIN
                UPDATE [#TemporalAnalysis_DatabaseStatus]
                SET [StatusCode]='NOT_APPLICABLE_VISIBLE_SCOPE',[IsPartial]=0,
                    [Detail]=N'Im sichtbaren Katalogscope wurde keine aktive systemversionierte Temporal Table erkannt; dies beweist keine vollständige Abwesenheit und erkennt keine früher getrennten Tabellenpaare.'
                WHERE [DatabaseName]=@DbName;
                INSERT [#TemporalAnalysis_SourceStatus]
                SELECT @DbName,[SourceCode],'NOT_APPLICABLE',0,0,[RequiredPermission],NULL,NULL,
                       N'Quelle wegen negativem sichtbaren Feature-Gate nicht aufgerufen.'
                FROM (VALUES
                      ('TEMPORAL_CATALOG',N'Katalogsicht auf sichtbare Tabellen, Perioden und Spalten'),
                      ('TEMPORAL_CAPACITY',N'VIEW DATABASE STATE und VIEW DEFINITION; SQL Server 2022+: VIEW DATABASE PERFORMANCE STATE und VIEW SECURITY DEFINITION'),
                      ('TEMPORAL_HISTORY_INDEX',N'Katalogsicht auf sichtbare Indizes und Indexspalten'))
                     [x]([SourceCode],[RequiredPermission]);
                FETCH NEXT FROM [DatabaseCursor] INTO @DbName,@CompatibilityLevel;
                CONTINUE;
            END;

            BEGIN TRY
                SET @Sql=N'SET LOCK_TIMEOUT '+CONVERT(nvarchar(11),@LockTimeoutMs)+N'; USE '+QUOTENAME(@DbName)+N';
INSERT [#TemporalAnalysis_TemporalTable]
([DatabaseName],[CurrentSchemaName],[CurrentTableName],[CurrentObjectId],
 [HistorySchemaName],[HistoryTableName],[HistoryObjectId],
 [PeriodStartColumnName],[PeriodEndColumnName],[PeriodStartIsHidden],[PeriodEndIsHidden],
 [CurrentIsMemoryOptimized],[CurrentDurabilityDesc],[DatabaseRetentionEnabled],
 [HistoryRetentionPeriod],[HistoryRetentionUnitDesc],[RetentionMode],
 [AssessmentStatus],[EvidenceLimit])
SELECT @pDatabaseName,[s].[name],[t].[name],[t].[object_id],
       [hs].[name],[h].[name],[t].[history_table_id],
       [pcStart].[name],[pcEnd].[name],[pcStart].[is_hidden],[pcEnd].[is_hidden],
       [t].[is_memory_optimized],[t].[durability_desc],[d].[is_temporal_history_retention_enabled],
       [t].[history_retention_period],[t].[history_retention_period_unit_desc],
       CASE WHEN [t].[history_retention_period_unit]=-1 THEN ''INFINITE''
            WHEN [t].[history_retention_period] IS NULL THEN ''UNAVAILABLE'' ELSE ''FINITE'' END,
       ''AVAILABLE'',
       N''Katalog- und Konfigurationsevidenz beweist keine Zeilenkonsistenz, Cleanup-Ausführung oder vollständige Metadatensichtbarkeit.''
FROM [sys].[tables] [t] WITH (NOLOCK)
JOIN [sys].[schemas] [s] WITH (NOLOCK) ON [s].[schema_id]=[t].[schema_id]
LEFT JOIN [sys].[tables] [h] WITH (NOLOCK) ON [h].[object_id]=[t].[history_table_id]
LEFT JOIN [sys].[schemas] [hs] WITH (NOLOCK) ON [hs].[schema_id]=[h].[schema_id]
LEFT JOIN [sys].[periods] [p] WITH (NOLOCK) ON [p].[object_id]=[t].[object_id] AND [p].[period_type]=1
LEFT JOIN [sys].[columns] [pcStart] WITH (NOLOCK) ON [pcStart].[object_id]=[p].[object_id] AND [pcStart].[column_id]=[p].[start_column_id]
LEFT JOIN [sys].[columns] [pcEnd] WITH (NOLOCK) ON [pcEnd].[object_id]=[p].[object_id] AND [pcEnd].[column_id]=[p].[end_column_id]
OUTER APPLY
(
    SELECT [is_temporal_history_retention_enabled]
    FROM [sys].[databases] WITH (NOLOCK)
    WHERE [database_id]=DB_ID()
) [d]
WHERE [t].[is_ms_shipped]=0 AND [t].[temporal_type]=2'+@SchemaPredicate+@ObjectPredicate+@FullObjectPredicate+N';
SET @pRows=@@ROWCOUNT;';
                SET @Rows=0;
                EXEC [sys].[sp_executesql] @Sql,N'@pDatabaseName sysname,@pRows bigint OUTPUT',
                     @pDatabaseName=@DbName,@pRows=@Rows OUTPUT;
                INSERT [#TemporalAnalysis_SourceStatus]
                VALUES(@DbName,'TEMPORAL_CATALOG','AVAILABLE',0,@Rows,
                       N'Katalogsicht auf sichtbare Tabellen, Perioden und Spalten',NULL,NULL,
                       N'Aktive Zuordnung, Periodenspalten und Retention-Konfiguration; Nullzeilen können aus Filtern oder Metadatensichtbarkeit folgen.');
            END TRY
            BEGIN CATCH
                INSERT [#TemporalAnalysis_SourceStatus]
                VALUES(@DbName,'TEMPORAL_CATALOG','ERROR_HANDLED',1,0,
                       N'Katalogsicht auf sichtbare Tabellen, Perioden und Spalten',ERROR_NUMBER(),ERROR_MESSAGE(),
                       N'Kapazitäts- und Indexquellen benötigen die Katalogzuordnung und werden für diese Datenbank ausgelassen.');
            END CATCH;

            IF EXISTS
            (
                SELECT 1 FROM [#TemporalAnalysis_SourceStatus]
                WHERE [DatabaseName]=@DbName AND [SourceCode]='TEMPORAL_CATALOG' AND [IsPartial]=1
            )
            BEGIN
                INSERT [#TemporalAnalysis_SourceStatus]
                VALUES
                (@DbName,'TEMPORAL_CAPACITY','UNAVAILABLE_DEPENDENCY',1,0,
                 N'VIEW DATABASE STATE und VIEW DEFINITION; SQL Server 2022+: VIEW DATABASE PERFORMANCE STATE und VIEW SECURITY DEFINITION',
                 NULL,N'TEMPORAL_CATALOG ist nicht verfügbar.',N'Keine Partitionsstatistik ohne belastbare Objektzuordnung.'),
                (@DbName,'TEMPORAL_HISTORY_INDEX','UNAVAILABLE_DEPENDENCY',1,0,
                 N'Katalogsicht auf sichtbare Indizes und Indexspalten',NULL,
                 N'TEMPORAL_CATALOG ist nicht verfügbar.',N'Keine Indexbewertung ohne belastbare Perioden- und History-Zuordnung.');
                FETCH NEXT FROM [DatabaseCursor] INTO @DbName,@CompatibilityLevel;
                CONTINUE;
            END;

            BEGIN TRY
                SET @Sql=N'SET LOCK_TIMEOUT '+CONVERT(nvarchar(11),@LockTimeoutMs)+N'; USE '+QUOTENAME(@DbName)+N';
UPDATE [tt]
SET [CurrentRowsApprox]=[c].[RowCountApprox],
    [CurrentReservedMb]=[c].[ReservedMb],
    [CurrentUsedMb]=[c].[UsedMb],
    [HistoryRowsApprox]=[h].[RowCountApprox],
    [HistoryReservedMb]=[h].[ReservedMb],
    [HistoryUsedMb]=[h].[UsedMb],
    [HistoryToCurrentRowRatio]=CASE WHEN [tt].[CurrentIsMemoryOptimized]=0 AND [c].[RowCountApprox]>0
                                    THEN CONVERT(decimal(19,4),CONVERT(decimal(38,4),[h].[RowCountApprox])/[c].[RowCountApprox]) END
FROM [#TemporalAnalysis_TemporalTable] [tt]
OUTER APPLY
(
    SELECT SUM(CASE WHEN [index_id] IN(0,1) THEN CONVERT(bigint,[row_count]) END) AS [RowCountApprox],
           CONVERT(decimal(19,2),SUM(CONVERT(decimal(38,2),[reserved_page_count]))*8.0/1024.0) AS [ReservedMb],
           CONVERT(decimal(19,2),SUM(CONVERT(decimal(38,2),[used_page_count]))*8.0/1024.0) AS [UsedMb]
    FROM [sys].[dm_db_partition_stats] WITH (NOLOCK)
    WHERE [object_id]=[tt].[CurrentObjectId]
) [c]
OUTER APPLY
(
    SELECT SUM(CASE WHEN [index_id] IN(0,1) THEN CONVERT(bigint,[row_count]) END) AS [RowCountApprox],
           CONVERT(decimal(19,2),SUM(CONVERT(decimal(38,2),[reserved_page_count]))*8.0/1024.0) AS [ReservedMb],
           CONVERT(decimal(19,2),SUM(CONVERT(decimal(38,2),[used_page_count]))*8.0/1024.0) AS [UsedMb]
    FROM [sys].[dm_db_partition_stats] WITH (NOLOCK)
    WHERE [object_id]=[tt].[HistoryObjectId]
) [h]
WHERE [tt].[DatabaseName]=@pDatabaseName;
SET @pRows=@@ROWCOUNT;';
                SET @Rows=0;
                EXEC [sys].[sp_executesql] @Sql,N'@pDatabaseName sysname,@pRows bigint OUTPUT',
                     @pDatabaseName=@DbName,@pRows=@Rows OUTPUT;
                INSERT [#TemporalAnalysis_SourceStatus]
                VALUES(@DbName,'TEMPORAL_CAPACITY','AVAILABLE',0,@Rows,
                       N'VIEW DATABASE STATE und VIEW DEFINITION; SQL Server 2022+: VIEW DATABASE PERFORMANCE STATE und VIEW SECURITY DEFINITION',NULL,NULL,
                       N'Approximative Zeilen und Seiten aller Indizes; keine Tabellenzeilen. Current-Ratio wird für speicheroptimierte aktuelle Tabellen nicht behauptet.');
            END TRY
            BEGIN CATCH
                INSERT [#TemporalAnalysis_SourceStatus]
                VALUES(@DbName,'TEMPORAL_CAPACITY','ERROR_HANDLED',1,0,
                       N'VIEW DATABASE STATE und VIEW DEFINITION; SQL Server 2022+: VIEW DATABASE PERFORMANCE STATE und VIEW SECURITY DEFINITION',
                       ERROR_NUMBER(),ERROR_MESSAGE(),N'Katalog- und Indexevidenz bleiben verfügbar.');
            END CATCH;

            BEGIN TRY
                SET @Sql=N'SET LOCK_TIMEOUT '+CONVERT(nvarchar(11),@LockTimeoutMs)+N'; USE '+QUOTENAME(@DbName)+N';
INSERT [#TemporalAnalysis_HistoryIndex]
SELECT [tt].[DatabaseName],[tt].[CurrentSchemaName],[tt].[CurrentTableName],
       [tt].[HistorySchemaName],[tt].[HistoryTableName],[i].[name],[i].[index_id],[i].[type_desc],
       [i].[is_unique],[i].[is_disabled],[k].[FirstKeyColumnName],[k].[SecondKeyColumnName],
       CONVERT(bit,CASE WHEN [i].[type] IN(1,2) AND [i].[is_disabled]=0
                            AND [k].[FirstKeyColumnName]=[tt].[PeriodEndColumnName]
                            AND [k].[SecondKeyColumnName]=[tt].[PeriodStartColumnName]
                        THEN 1 ELSE 0 END),
       N''Bewertet nur die dokumentierte führende Schlüsselreihenfolge Periodenende/Periodenstart; keine Workload-, Selektivitäts- oder Plananalyse.''
FROM [#TemporalAnalysis_TemporalTable] [tt]
JOIN [sys].[indexes] [i] WITH (NOLOCK)
  ON [i].[object_id]=[tt].[HistoryObjectId] AND [i].[index_id]>0 AND [i].[is_hypothetical]=0
OUTER APPLY
(
    SELECT MAX(CASE WHEN [ic].[key_ordinal]=1 THEN [c].[name] END) AS [FirstKeyColumnName],
           MAX(CASE WHEN [ic].[key_ordinal]=2 THEN [c].[name] END) AS [SecondKeyColumnName]
    FROM [sys].[index_columns] [ic] WITH (NOLOCK)
    JOIN [sys].[columns] [c] WITH (NOLOCK)
      ON [c].[object_id]=[ic].[object_id] AND [c].[column_id]=[ic].[column_id]
    WHERE [ic].[object_id]=[i].[object_id] AND [ic].[index_id]=[i].[index_id]
) [k]
WHERE [tt].[DatabaseName]=@pDatabaseName
  AND [tt].[HistorySchemaName] IS NOT NULL AND [tt].[HistoryTableName] IS NOT NULL;
SET @pRows=@@ROWCOUNT;

UPDATE [tt]
SET [HistoryIndexCount]=[x].[IndexCount],
    [HasPeriodLeadingHistoryIndex]=[x].[HasPeriodLeading]
FROM [#TemporalAnalysis_TemporalTable] [tt]
OUTER APPLY
(
    SELECT COUNT(*) AS [IndexCount],
           CONVERT(bit,COALESCE(MAX(CONVERT(tinyint,[hi].[IsPeriodLeadingIndex])),0)) AS [HasPeriodLeading]
    FROM [#TemporalAnalysis_HistoryIndex] [hi]
    WHERE [hi].[DatabaseName]=[tt].[DatabaseName]
      AND [hi].[CurrentSchemaName]=[tt].[CurrentSchemaName]
      AND [hi].[CurrentTableName]=[tt].[CurrentTableName]
) [x]
WHERE [tt].[DatabaseName]=@pDatabaseName;';
                SET @Rows=0;
                EXEC [sys].[sp_executesql] @Sql,N'@pDatabaseName sysname,@pRows bigint OUTPUT',
                     @pDatabaseName=@DbName,@pRows=@Rows OUTPUT;
                INSERT [#TemporalAnalysis_SourceStatus]
                VALUES(@DbName,'TEMPORAL_HISTORY_INDEX','AVAILABLE',0,@Rows,
                       N'Katalogsicht auf sichtbare Indizes und Indexspalten',NULL,NULL,
                       N'Indexmetadaten ohne Schlüsselwerte; bewertet ausschließlich eine dokumentierte Baseline, keine endgültige Indexeignung.');
            END TRY
            BEGIN CATCH
                INSERT [#TemporalAnalysis_SourceStatus]
                VALUES(@DbName,'TEMPORAL_HISTORY_INDEX','ERROR_HANDLED',1,0,
                       N'Katalogsicht auf sichtbare Indizes und Indexspalten',ERROR_NUMBER(),ERROR_MESSAGE(),
                       N'Katalog- und Kapazitätsevidenz bleiben verfügbar.');
            END CATCH;

            FETCH NEXT FROM [DatabaseCursor] INTO @DbName,@CompatibilityLevel;
        END;
        CLOSE [DatabaseCursor];
        DEALLOCATE [DatabaseCursor];
    END;

    INSERT [#TemporalAnalysis_Findings]
    ([DatabaseName],[SchemaName],[ObjectName],[HistorySchemaName],[HistoryTableName],
     [Severity],[Confidence],[FindingCode],[MetricName],[MetricValue],[ThresholdValue],
     [Evidence],[EvidenceLimit],[RecommendedNextCheck])
    SELECT [DatabaseName],[CurrentSchemaName],[CurrentTableName],[HistorySchemaName],[HistoryTableName],
           'WARN','HIGH','HISTORY_TABLE_NOT_VISIBLE','HISTORY_OBJECT_VISIBLE',0,1,
           N'Die aktive Temporal-Metadatenzeile enthält keine vollständig sichtbare zugeordnete History-Tabelle.',
           [EvidenceLimit],
           N'Metadatensichtbarkeit und Berechtigungen prüfen; erst danach eine strukturelle Abweichung untersuchen.'
    FROM [#TemporalAnalysis_TemporalTable]
    WHERE [HistoryObjectId] IS NULL OR [HistorySchemaName] IS NULL OR [HistoryTableName] IS NULL;

    INSERT [#TemporalAnalysis_Findings]
    ([DatabaseName],[SchemaName],[ObjectName],[HistorySchemaName],[HistoryTableName],
     [Severity],[Confidence],[FindingCode],[MetricName],[MetricValue],[ThresholdValue],
     [Evidence],[EvidenceLimit],[RecommendedNextCheck])
    SELECT [DatabaseName],[CurrentSchemaName],[CurrentTableName],[HistorySchemaName],[HistoryTableName],
           'WARN','HIGH','PERIOD_METADATA_INCOMPLETE','PERIOD_COLUMNS_VISIBLE',
           CONVERT(decimal(38,4),CASE WHEN [PeriodStartColumnName] IS NOT NULL THEN 1 ELSE 0 END+
                                      CASE WHEN [PeriodEndColumnName] IS NOT NULL THEN 1 ELSE 0 END),2,
           N'Für die sichtbare aktive Temporal Table sind Start- und Endspalte des SYSTEM_TIME-Periods nicht vollständig sichtbar.',
           [EvidenceLimit],
           N'Metadatensichtbarkeit und sys.periods/sys.columns-Zuordnung prüfen; keine Dateninkonsistenz daraus ableiten.'
    FROM [#TemporalAnalysis_TemporalTable]
    WHERE [PeriodStartColumnName] IS NULL OR [PeriodEndColumnName] IS NULL;

    INSERT [#TemporalAnalysis_Findings]
    ([DatabaseName],[SchemaName],[ObjectName],[HistorySchemaName],[HistoryTableName],
     [Severity],[Confidence],[FindingCode],[MetricName],[MetricValue],[ThresholdValue],
     [Evidence],[EvidenceLimit],[RecommendedNextCheck])
    SELECT [DatabaseName],[CurrentSchemaName],[CurrentTableName],[HistorySchemaName],[HistoryTableName],
           'WARN','HIGH','RETENTION_CONFIGURED_DATABASE_CLEANUP_DISABLED','DATABASE_RETENTION_ENABLED',
           CONVERT(decimal(38,4),[DatabaseRetentionEnabled]),1,
           N'Eine endliche History-Retention ist konfiguriert, der datenbankweite automatische Temporal-Cleanup ist jedoch nicht aktiviert.',
           N'Der Schalter zeigt Konfiguration, nicht Ausführung, Fortschritt oder Löschberechtigung des Hintergrundtasks.',
           N'Datenbankoption, Restore-Historie und Cleanup-Fortschritt mit freigegebener Laufzeitevidenz prüfen.'
    FROM [#TemporalAnalysis_TemporalTable]
    WHERE [RetentionMode]='FINITE' AND [DatabaseRetentionEnabled]=0;

    INSERT [#TemporalAnalysis_Findings]
    ([DatabaseName],[SchemaName],[ObjectName],[HistorySchemaName],[HistoryTableName],
     [Severity],[Confidence],[FindingCode],[MetricName],[MetricValue],[ThresholdValue],
     [Evidence],[EvidenceLimit],[RecommendedNextCheck])
    SELECT [DatabaseName],[CurrentSchemaName],[CurrentTableName],[HistorySchemaName],[HistoryTableName],
           'WARN','MEDIUM','HISTORY_PERIOD_INDEX_REVIEW','PERIOD_LEADING_HISTORY_INDEX',
           CONVERT(decimal(38,4),COALESCE([HasPeriodLeadingHistoryIndex],0)),1,
           N'Kein aktiver sichtbarer B-Tree-History-Index beginnt mit Periodenende und Periodenstart.',
           N'Die dokumentierte Baseline ist kein universelles Workload-Optimum; Columnstore, Partitionierung, Schreiblast und konkrete Pläne bleiben unbewertet.',
           N'History-Workload und vorhandene Indexstrategie prüfen; DDL nur nach messbarer Plan- und Wartungsbewertung ableiten.'
    FROM [#TemporalAnalysis_TemporalTable]
    WHERE [HistoryObjectId] IS NOT NULL
      AND [HistorySchemaName] IS NOT NULL AND [HistoryTableName] IS NOT NULL
      AND [PeriodStartColumnName] IS NOT NULL AND [PeriodEndColumnName] IS NOT NULL
      AND COALESCE([HasPeriodLeadingHistoryIndex],0)=0
      AND EXISTS
          (SELECT 1 FROM [#TemporalAnalysis_SourceStatus] [ss]
           WHERE [ss].[DatabaseName]=[#TemporalAnalysis_TemporalTable].[DatabaseName]
             AND [ss].[SourceCode]='TEMPORAL_HISTORY_INDEX' AND [ss].[IsPartial]=0);

    INSERT [#TemporalAnalysis_Findings]
    ([DatabaseName],[SchemaName],[ObjectName],[HistorySchemaName],[HistoryTableName],
     [Severity],[Confidence],[FindingCode],[MetricName],[MetricValue],[ThresholdValue],
     [Evidence],[EvidenceLimit],[RecommendedNextCheck])
    SELECT [DatabaseName],[CurrentSchemaName],[CurrentTableName],[HistorySchemaName],[HistoryTableName],
           'INFO','MEDIUM','LARGE_HISTORY_SIZE_CONTEXT','HISTORY_RESERVED_MB',[HistoryReservedMb],@HistorySizeWarnMb,
           N'Die approximative reservierte History-Größe überschreitet den konfigurierten Kontextgrenzwert.',
           N'Pages sind approximativ und enthalten Tabellen- sowie Indexspeicher; Größe allein ist kein Fehler.',
           N'Wachstumsverlauf, Retentionsziel, Kompression, Partitionierung und Abfragebedarf gemeinsam bewerten.'
    FROM [#TemporalAnalysis_TemporalTable]
    WHERE [HistoryReservedMb]>=@HistorySizeWarnMb;

    INSERT [#TemporalAnalysis_Findings]
    ([DatabaseName],[SchemaName],[ObjectName],[HistorySchemaName],[HistoryTableName],
     [Severity],[Confidence],[FindingCode],[MetricName],[MetricValue],[ThresholdValue],
     [Evidence],[EvidenceLimit],[RecommendedNextCheck])
    SELECT [DatabaseName],[CurrentSchemaName],[CurrentTableName],[HistorySchemaName],[HistoryTableName],
           'INFO','MEDIUM','LARGE_HISTORY_ROW_CONTEXT','HISTORY_ROWS_APPROX',[HistoryRowsApprox],@HistoryRowsWarn,
           N'Die approximative History-Zeilenzahl überschreitet den konfigurierten Kontextgrenzwert.',
           N'row_count ist approximativ; Zeilenvolumen allein beweist weder Cleanup-Rückstand noch Kapazitätsdruck.',
           N'Wiederholte Messungen, Änderungsrate, Retentionsziel und Speichertrend korrelieren.'
    FROM [#TemporalAnalysis_TemporalTable]
    WHERE [HistoryRowsApprox]>=@HistoryRowsWarn;

    INSERT [#TemporalAnalysis_Findings]
    ([DatabaseName],[SchemaName],[ObjectName],[HistorySchemaName],[HistoryTableName],
     [Severity],[Confidence],[FindingCode],[MetricName],[MetricValue],[ThresholdValue],
     [Evidence],[EvidenceLimit],[RecommendedNextCheck])
    SELECT [DatabaseName],[CurrentSchemaName],[CurrentTableName],[HistorySchemaName],[HistoryTableName],
           'INFO','LOW','HISTORY_TO_CURRENT_RATIO_CONTEXT','HISTORY_TO_CURRENT_ROW_RATIO',
           [HistoryToCurrentRowRatio],@HistoryToCurrentRatioWarn,
           N'Das approximative Verhältnis History zu Current überschreitet den konfigurierten Kontextgrenzwert.',
           N'Das Verhältnis ist für leere/kleine oder speicheroptimierte Current-Tabellen nicht belastbar und sagt nichts über fachlich zulässige Historientiefe aus.',
           N'Retentionsanforderung, Änderungsrate, Alter der History und Zeitverlauf prüfen.'
    FROM [#TemporalAnalysis_TemporalTable]
    WHERE [HistoryReservedMb]>=@MinHistoryMbForRatioWarn
      AND [HistoryToCurrentRowRatio]>=@HistoryToCurrentRatioWarn;

    INSERT [#TemporalAnalysis_Findings]
    ([DatabaseName],[Severity],[Confidence],[FindingCode],[MetricName],[Evidence],[EvidenceLimit],[RecommendedNextCheck])
    SELECT [DatabaseName],'WARN','HIGH','TEMPORAL_EVIDENCE_GAP',[SourceCode],
           COALESCE([ErrorMessage],N'Die angeforderte Quelle ist nicht verfügbar.'),
           [Detail],N'Berechtigung, Featureverfügbarkeit und Abhängigkeiten prüfen; andere Resultsets bleiben gültig.'
    FROM [#TemporalAnalysis_SourceStatus]
    WHERE [IsPartial]=1;

    UPDATE [tt]
    SET [AssessmentStatus]=CASE WHEN EXISTS
        (SELECT 1 FROM [#TemporalAnalysis_Findings] [f]
         WHERE [f].[DatabaseName]=[tt].[DatabaseName]
           AND [f].[SchemaName]=[tt].[CurrentSchemaName]
           AND [f].[ObjectName]=[tt].[CurrentTableName]
           AND [f].[Severity]='WARN') THEN 'REVIEW' ELSE 'AVAILABLE' END
    FROM [#TemporalAnalysis_TemporalTable] AS [tt];

    UPDATE [ds]
    SET [SourceFailureCount]=[x].[FailureCount],
        [IsPartial]=CONVERT(bit,CASE WHEN [x].[FailureCount]>0 THEN 1 ELSE 0 END),
        [FindingCount]=[f].[FindingCount],
        [StatusCode]=CASE WHEN [ds].[StatusCode] IN('NOT_APPLICABLE_VISIBLE_SCOPE','UNAVAILABLE_FEATURE','ERROR_HANDLED') THEN [ds].[StatusCode]
                          WHEN [x].[FailureCount]>0 THEN 'AVAILABLE_LIMITED'
                          WHEN [f].[WarnCount]>0 THEN 'AVAILABLE_WITH_FINDING'
                          ELSE 'AVAILABLE' END,
        [Detail]=CASE WHEN [ds].[StatusCode]='PENDING' AND [x].[FailureCount]>0 THEN N'Mindestens eine isolierte Quelle fehlt; zugängliche Teilergebnisse bleiben erhalten.'
                      WHEN [ds].[StatusCode]='PENDING' AND [f].[WarnCount]>0 THEN N'Mindestens ein konfigurierter Prüfhinweis liegt vor; kein automatisches Gesundheitsurteil.'
                      WHEN [ds].[StatusCode]='PENDING' THEN N'Kein konfigurierter Warnindikator in der zugänglichen Metadatenaufnahme; dies beweist weder Datenkonsistenz noch erfolgreichen Cleanup.'
                      ELSE [ds].[Detail] END
    FROM [#TemporalAnalysis_DatabaseStatus] [ds]
    OUTER APPLY
    (
        SELECT COUNT_BIG(*) AS [FailureCount]
        FROM [#TemporalAnalysis_SourceStatus] [ss]
        WHERE [ss].[DatabaseName]=[ds].[DatabaseName] AND [ss].[IsPartial]=1
    ) [x]
    OUTER APPLY
    (
        SELECT COUNT_BIG(*) AS [FindingCount],
               COALESCE(SUM(CASE WHEN [ff].[Severity]='WARN' THEN CONVERT(bigint,1) ELSE CONVERT(bigint,0) END),0) AS [WarnCount]
        FROM [#TemporalAnalysis_Findings] [ff]
        WHERE [ff].[DatabaseName]=[ds].[DatabaseName]
    ) [f];

    IF @StatusCode='AVAILABLE'
    BEGIN
        IF EXISTS(SELECT 1 FROM [#TemporalAnalysis_DatabaseStatus] WHERE [IsPartial]=1)
            SELECT @StatusCode='AVAILABLE_LIMITED',@IsPartial=1;
        ELSE IF EXISTS(SELECT 1 FROM [#TemporalAnalysis_Findings] WHERE [Severity]='WARN')
            SET @StatusCode='AVAILABLE_WITH_FINDING';
        ELSE IF NOT EXISTS(SELECT 1 FROM [#TemporalAnalysis_FeatureScope] WHERE [TemporalTableCount]>0)
            SET @StatusCode='NOT_APPLICABLE';
    END;

    SELECT @ErrorNumber=COALESCE(@ErrorNumber,MIN([ErrorNumber])),
           @ErrorMessage=COALESCE(@ErrorMessage,MIN([ErrorMessage]))
    FROM [#TemporalAnalysis_SourceStatus]
    WHERE [IsPartial]=1;

    IF @JsonErzeugen=1
    BEGIN
        SELECT @Json=(
            SELECT
                JSON_QUERY((SELECT N'USP_TemporalAnalysis' AS [module],@Now AS [collectedAtUtc],@StatusCode AS [statusCode],@IsPartial AS [isPartial],@ErrorNumber AS [errorNumber],@ErrorMessage AS [errorMessage] FOR JSON PATH,WITHOUT_ARRAY_WRAPPER)) AS [meta],
                JSON_QUERY(COALESCE((SELECT * FROM [#TemporalAnalysis_DatabaseStatus] ORDER BY [DatabaseName] FOR JSON PATH),N'[]')) AS [databaseStatus],
                JSON_QUERY(COALESCE((SELECT * FROM [#TemporalAnalysis_SourceStatus] ORDER BY [DatabaseName],[SourceCode] FOR JSON PATH),N'[]')) AS [sourceStatus],
                JSON_QUERY(COALESCE((SELECT TOP(@Limit) * FROM [#TemporalAnalysis_Findings] WHERE @NurProblematisch=0 OR [Severity]='WARN' ORDER BY CASE [Severity] WHEN 'WARN' THEN 1 ELSE 2 END,[FindingOrdinal] FOR JSON PATH),N'[]')) AS [findings],
                JSON_QUERY(COALESCE((SELECT TOP(@Limit) * FROM [#TemporalAnalysis_TemporalTable] WHERE @NurProblematisch=0 OR [AssessmentStatus]='REVIEW' ORDER BY CASE [AssessmentStatus] WHEN 'REVIEW' THEN 1 ELSE 2 END,[HistoryReservedMb] DESC,[DatabaseName],[CurrentSchemaName],[CurrentTableName] FOR JSON PATH),N'[]')) AS [temporalTables],
                JSON_QUERY(COALESCE((SELECT TOP(@Limit) [hi].* FROM [#TemporalAnalysis_HistoryIndex] [hi] WHERE @NurProblematisch=0 OR EXISTS(SELECT 1 FROM [#TemporalAnalysis_TemporalTable] [tt] WHERE [tt].[DatabaseName]=[hi].[DatabaseName] AND [tt].[CurrentSchemaName]=[hi].[CurrentSchemaName] AND [tt].[CurrentTableName]=[hi].[CurrentTableName] AND [tt].[AssessmentStatus]='REVIEW') ORDER BY [hi].[DatabaseName],[hi].[CurrentSchemaName],[hi].[CurrentTableName],[hi].[IndexId] FOR JSON PATH),N'[]')) AS [historyIndexes]
            FOR JSON PATH,WITHOUT_ARRAY_WRAPPER);
    END;

    IF @OutputMode<>'NONE'
    BEGIN
        SELECT N'USP_TemporalAnalysis' AS [Module],@Now AS [CollectedAtUtc],@StatusCode AS [StatusCode],
               @IsPartial AS [IsPartial],@ErrorNumber AS [ErrorNumber],@ErrorMessage AS [ErrorMessage],
               N'Read-only Metadatenaufnahme; keine Benutzertabellenzeilen, DBCC-, Cleanup- oder DDL-Ausführung.' AS [Detail];
        SELECT * FROM [#TemporalAnalysis_DatabaseStatus] ORDER BY [DatabaseName];
        SELECT * FROM [#TemporalAnalysis_SourceStatus] ORDER BY [DatabaseName],[SourceCode];
        SELECT TOP(@Limit) * FROM [#TemporalAnalysis_Findings]
        WHERE @NurProblematisch=0 OR [Severity]='WARN'
        ORDER BY CASE [Severity] WHEN 'WARN' THEN 1 ELSE 2 END,[FindingOrdinal];
        SELECT TOP(@Limit) * FROM [#TemporalAnalysis_TemporalTable]
        WHERE @NurProblematisch=0 OR [AssessmentStatus]='REVIEW'
        ORDER BY CASE [AssessmentStatus] WHEN 'REVIEW' THEN 1 ELSE 2 END,
                 [HistoryReservedMb] DESC,[DatabaseName],[CurrentSchemaName],[CurrentTableName];
        SELECT TOP(@Limit) [hi].* FROM [#TemporalAnalysis_HistoryIndex] [hi]
        WHERE @NurProblematisch=0 OR EXISTS
              (SELECT 1 FROM [#TemporalAnalysis_TemporalTable] [tt]
               WHERE [tt].[DatabaseName]=[hi].[DatabaseName]
                 AND [tt].[CurrentSchemaName]=[hi].[CurrentSchemaName]
                 AND [tt].[CurrentTableName]=[hi].[CurrentTableName]
                 AND [tt].[AssessmentStatus]='REVIEW')
        ORDER BY [hi].[DatabaseName],[hi].[CurrentSchemaName],[hi].[CurrentTableName],[hi].[IndexId];
    END;

    IF @PrintMeldungen=1 AND @StatusCode NOT IN('AVAILABLE','NOT_APPLICABLE')
    BEGIN
        SET @PrintMessage=LEFT(CONCAT(N'USP_TemporalAnalysis: ',@StatusCode,N'. ',COALESCE(@ErrorMessage,N'Siehe strukturierte Quellenstatus.')),2048);
        RAISERROR(N'%s',10,1,@PrintMessage) WITH NOWAIT;
    END;

    SELECT @StatusCodeOut=@StatusCode,@IsPartialOut=@IsPartial,
           @ErrorNumberOut=@ErrorNumber,@ErrorMessageOut=@ErrorMessage;
    IF @ConsoleResultRequested = 1
    BEGIN
        EXEC [monitor].[InternalEmitConsoleResult]
              @SourceTable=N'#TemporalAnalysis_Findings'
            , @ResultLabel=N'TemporalAnalysis'
            , @EmptyMessage=N'Keine fachlichen Ergebnisse';
    END;
    IF @TableResultRequested = 1
    BEGIN
        EXEC [monitor].[InternalWriteResultTable]
              @SourceTable = N'#TemporalAnalysis_Findings'
            , @TargetTable=@TableTarget
            , @ThrowOnError = 1;
    END;
END;
GO
-- END SOURCE: Code/09_VersionAdaptive/040_USP_TemporalAnalysis.sql

-- BEGIN SOURCE: Code/09_VersionAdaptive/050_USP_ServiceBrokerAnalysis.sql
/*
===============================================================================
Objekt       : monitor.USP_ServiceBrokerAnalysis
Version      : 1.0.0
Stand        : 2026-07-18
Typ          : Stored Procedure
Zweck        : Analysiert sichtbare Service-Broker-Konfiguration, Queue-
               Kapazität, interne Aktivierung, Transmission-Rückstand und
               aggregierte Conversation-Zustände.
SQL-Version  : SQL Server 2019 oder neuer.
Datenquellen : sys.databases, sys.service_queues, sys.services,
               sys.dm_db_partition_stats, sys.dm_broker_queue_monitors,
               sys.dm_broker_activated_tasks, sys.transmission_queue und
               sys.conversation_endpoints.
Methodik     : Feature-Gate und jede abhängige Quelle werden datenbankweise
               best effort ausgewertet. Fehlende Rechte verwerfen andere
               zugängliche Evidenz nicht.
Grenzen      : Keine Queue-Nutzdaten, keine Nachrichtenkörper, kein RECEIVE,
               keine Queue-Änderung und kein END CONVERSATION. Deaktivierte
               Queues, alte Einträge und DMV-Zustände sind Prüfhinweise; sie
               beweisen weder eine Poison Message noch deren Ursache.
Kosten       : MEDIUM; Kataloge, aggregierte Broker-Laufzeitmetadaten und
               approximative Partitionsstatistik.
===============================================================================
*/
CREATE OR ALTER PROCEDURE [monitor].[USP_ServiceBrokerAnalysis]
      @DatabaseNames                    nvarchar(max)  = NULL
    , @SystemdatenbankenEinbeziehen     bit            = 0
    , @DatabaseNamePattern              nvarchar(4000) = NULL
    , @HighImpactConfirmed              bit            = 0
    , @SchemaNames                      nvarchar(max)  = NULL
    , @SchemaNamePattern                nvarchar(4000) = NULL
    , @ObjectNames                      nvarchar(max)  = NULL
    , @ObjectNamePattern                nvarchar(4000) = NULL
    , @FullObjectNames                  nvarchar(max)  = NULL
    , @NurProblematisch                 bit            = 0
    , @TransmissionAgeWarnMinutes       bigint         = 60
    , @TransmissionRowsWarn             bigint         = 1000
    , @QueueRowsWarn                    bigint         = 10000
    , @ActivationSilenceWarnMinutes     bigint         = 60
    , @ConversationRowsWarn             bigint         = 100000
    , @MaxZeilen                        int            = 2000
    , @LockTimeoutMs                    int            = 0
    , @ResultSetArt                     varchar(16)     = 'CONSOLE'
    , @ResultTablesJson               nvarchar(max) = NULL
    , @JsonErzeugen                     bit            = 0
    , @Json                             nvarchar(max)   = NULL OUTPUT
    , @PrintMeldungen                   bit            = 1
    , @Hilfe                            bit            = 0
    , @StatusCodeOut                    varchar(40)     = NULL OUTPUT
    , @IsPartialOut                     bit            = NULL OUTPUT
    , @ErrorNumberOut                   int            = NULL OUTPUT
    , @ErrorMessageOut                  nvarchar(2048)  = NULL OUTPUT
AS
BEGIN
    SET NOCOUNT ON;
    SET LOCK_TIMEOUT 0;
    SET @Json=NULL;

    DECLARE @Now datetime2(3)=SYSUTCDATETIME();
    DECLARE @Major int=TRY_CONVERT(int,SERVERPROPERTY(N'ProductMajorVersion'));
    DECLARE @OutputMode varchar(16)=UPPER(LTRIM(RTRIM(COALESCE(@ResultSetArt,''))));
    DECLARE @TableResultRequested bit = CASE WHEN @OutputMode = 'TABLE' THEN 1 ELSE 0 END;
    DECLARE @ConsoleResultRequested bit = CASE WHEN @OutputMode = 'CONSOLE' THEN 1 ELSE 0 END;
    DECLARE @TableTarget sysname=NULL;
    IF @TableResultRequested=0 AND NULLIF(LTRIM(RTRIM(COALESCE(@ResultTablesJson,N''))),N'') IS NOT NULL THROW 51011,N'@ResultTablesJson ist ausschließlich mit @ResultSetArt=TABLE zulässig.',1;
    IF @TableResultRequested=1 EXEC [monitor].[InternalPrepareSingleResultTable] @ResultTablesJson=@ResultTablesJson,@ResultName=N'findings',@TargetTable=@TableTarget OUTPUT,@ThrowOnError=1;
    IF @TableResultRequested = 1 OR @ConsoleResultRequested = 1 SET @OutputMode = 'NONE';
    DECLARE @StatusCode varchar(40)='AVAILABLE';
    DECLARE @IsPartial bit=0;
    DECLARE @ErrorNumber int=NULL;
    DECLARE @ErrorMessage nvarchar(2048)=NULL;
    DECLARE @PrintMessage nvarchar(2048)=NULL;
    DECLARE @Limit bigint=CASE WHEN @MaxZeilen IS NULL OR @MaxZeilen=0
                               THEN CONVERT(bigint,9223372036854775807)
                               ELSE CONVERT(bigint,@MaxZeilen) END;

    IF @Hilfe=1
    BEGIN
        PRINT N'monitor.USP_ServiceBrokerAnalysis';
        PRINT N'Die Procedure führt eine rein lesende Tiefenanalyse sichtbarer Service-Broker-Konfiguration und aggregierter Laufzeitmetadaten durch.';
        PRINT N'Geprüft werden Queue-Schalter, approximative Queue-Zeilen, Aktivierungs-DMVs, Transmission-Alter und Conversation-Zustände.';
        PRINT N'Exakte Namenslisten und Pattern beziehen sich auf Queue-Schema und Queue-Name; Pattern: LIKE, regex: oder regexi:.';
        PRINT N'Grenzwerte erzeugen Prüfkontext und keine automatische Betriebs-, Routing- oder Bereinigungsentscheidung.';
        PRINT N'@ResultSetArt=CONSOLE|RAW|TABLE|NONE; TABLE verwendet @ResultTablesJson; @JsonErzeugen=1 erzeugt @Json OUTPUT.';
        PRINT N'Es werden keine Queue-Nutzdaten oder Nachrichtenkörper gelesen und keine Broker-Objekte verändert.';
        RETURN;
    END;

    IF @SystemdatenbankenEinbeziehen IS NULL OR @NurProblematisch IS NULL
       OR @JsonErzeugen IS NULL OR @PrintMeldungen IS NULL
       OR @TransmissionAgeWarnMinutes IS NULL OR @TransmissionAgeWarnMinutes<0
       OR @TransmissionRowsWarn IS NULL OR @TransmissionRowsWarn<0
       OR @QueueRowsWarn IS NULL OR @QueueRowsWarn<0
       OR @ActivationSilenceWarnMinutes IS NULL OR @ActivationSilenceWarnMinutes<0
       OR @ConversationRowsWarn IS NULL OR @ConversationRowsWarn<0

       OR @MaxZeilen IS NULL OR @MaxZeilen<0
       OR @LockTimeoutMs IS NULL OR @LockTimeoutMs NOT BETWEEN 0 AND 60000
       OR @OutputMode NOT IN('CONSOLE','RAW','NONE')
    BEGIN
        SELECT @StatusCode='INVALID_PARAMETER',@IsPartial=1,
               @ErrorMessage=N'Ungültiger Bit-, Grenzwert-, Mengen-, Lock-Timeout- oder Ausgabeparameter.';
    END;

    DECLARE @SchemaPatternMode varchar(8),@SchemaPatternValue nvarchar(4000),@SchemaRegexFlags varchar(8),@SchemaPatternValid bit;
    DECLARE @ObjectPatternMode varchar(8),@ObjectPatternValue nvarchar(4000),@ObjectRegexFlags varchar(8),@ObjectPatternValid bit;
    SELECT @SchemaPatternMode=[PatternMode],@SchemaPatternValue=[PatternValue],@SchemaRegexFlags=[RegexFlags],@SchemaPatternValid=[IsValid]
    FROM [monitor].[TVF_ParsePattern](@SchemaNamePattern);
    SELECT @ObjectPatternMode=[PatternMode],@ObjectPatternValue=[PatternValue],@ObjectRegexFlags=[RegexFlags],@ObjectPatternValid=[IsValid]
    FROM [monitor].[TVF_ParsePattern](@ObjectNamePattern);

    IF @StatusCode='AVAILABLE'
       AND (@SchemaPatternValid=0 OR @ObjectPatternValid=0
            OR (@SchemaNames IS NOT NULL AND @SchemaNamePattern IS NOT NULL)
            OR (@ObjectNames IS NOT NULL AND @ObjectNamePattern IS NOT NULL))
    BEGIN
        SELECT @StatusCode='INVALID_PARAMETER',@IsPartial=1,
               @ErrorMessage=N'Pattern ungültig oder exakte Liste und Pattern derselben Eigenschaft gleichzeitig angegeben.';
    END;

    IF @StatusCode='AVAILABLE'
       AND (@SchemaPatternMode IN('REGEX','REGEXI') OR @ObjectPatternMode IN('REGEX','REGEXI'))
       AND COALESCE(@Major,0)<17
    BEGIN
        SELECT @StatusCode='UNAVAILABLE_VERSION',@IsPartial=1,
               @ErrorMessage=N'Regex-Pattern benötigen SQL Server 2025 oder neuer und Compatibility Level 170.';
    END;

    CREATE TABLE [#ServiceBrokerAnalysis_NameFilters]
    (
          [FilterType] varchar(20) COLLATE SQL_Latin1_General_CP1_CS_AS NOT NULL
        , [ItemOrdinal] int NOT NULL
        , [NameValue] sysname COLLATE SQL_Latin1_General_CP1_CS_AS NULL
        , [DatabaseName] sysname COLLATE SQL_Latin1_General_CP1_CS_AS NULL
        , [SchemaName] sysname COLLATE SQL_Latin1_General_CP1_CS_AS NULL
        , [ObjectName] sysname COLLATE SQL_Latin1_General_CP1_CS_AS NULL
    );
    CREATE TABLE [#ServiceBrokerAnalysis_DatabaseCandidates]
    (
          [DatabaseId] int NOT NULL
        , [DatabaseName] sysname NOT NULL
        , [StateDesc] nvarchar(60) NULL
        , [UserAccessDesc] nvarchar(60) NULL
        , [IsReadOnly] bit NULL
        , [CompatibilityLevel] tinyint NULL
        , [CollationName] sysname NULL
        , [RecoveryModelDesc] nvarchar(60) NULL
        , [IsSystemDatabase] bit NULL
        , [RequestedOrdinal] int NULL
    );
    CREATE TABLE [#ServiceBrokerAnalysis_DatabaseCandidateWarnings]
    (
          [RequestedName] sysname COLLATE SQL_Latin1_General_CP1_CS_AS NULL
        , [StatusCode] varchar(40) NOT NULL
        , [ErrorMessage] nvarchar(2048) NOT NULL
    );
    CREATE TABLE [#ServiceBrokerAnalysis_FeatureScope]
    (
          [DatabaseName] sysname NOT NULL PRIMARY KEY
        , [IsBrokerEnabled] bit NOT NULL
        , [UserQueueCount] bigint NOT NULL
        , [UserServiceCount] bigint NOT NULL
    );
    CREATE TABLE [#ServiceBrokerAnalysis_DatabaseStatus]
    (
          [DatabaseName] sysname NULL
        , [StatusCode] varchar(40) NOT NULL
        , [IsPartial] bit NOT NULL
        , [IsBrokerEnabled] bit NULL
        , [UserQueueCount] bigint NOT NULL
        , [UserServiceCount] bigint NOT NULL
        , [TransmissionMessageCount] bigint NOT NULL
        , [ConversationEndpointCount] bigint NOT NULL
        , [SourceFailureCount] int NOT NULL
        , [FindingCount] bigint NOT NULL
        , [RequiredPermission] nvarchar(256) NULL
        , [ErrorNumber] int NULL
        , [ErrorMessage] nvarchar(2048) NULL
        , [Detail] nvarchar(2000) NULL
    );
    CREATE TABLE [#ServiceBrokerAnalysis_SourceStatus]
    (
          [DatabaseName] sysname NULL
        , [SourceCode] varchar(64) NOT NULL
        , [StatusCode] varchar(40) NOT NULL
        , [IsPartial] bit NOT NULL
        , [RowCount] bigint NOT NULL
        , [RequiredPermission] nvarchar(256) NULL
        , [ErrorNumber] int NULL
        , [ErrorMessage] nvarchar(2048) NULL
        , [Detail] nvarchar(2000) NULL
    );
    CREATE TABLE [#ServiceBrokerAnalysis_Queue]
    (
          [DatabaseName] sysname NOT NULL
        , [SchemaName] sysname NOT NULL
        , [QueueName] sysname NOT NULL
        , [QueueObjectId] int NOT NULL
        , [ServiceCount] int NOT NULL
        , [IsBrokerEnabled] bit NOT NULL
        , [IsActivationEnabled] bit NOT NULL
        , [IsReceiveEnabled] bit NOT NULL
        , [IsEnqueueEnabled] bit NOT NULL
        , [IsRetentionEnabled] bit NOT NULL
        , [IsPoisonMessageHandlingEnabled] bit NOT NULL
        , [MaxReaders] smallint NULL
        , [ActivationProcedure] nvarchar(776) NULL
        , [ExecuteAsPrincipalId] int NULL
        , [QueueRowsApprox] bigint NULL
        , [QueueReservedMb] decimal(19,2) NULL
        , [QueueUsedMb] decimal(19,2) NULL
        , [QueueMonitorState] nvarchar(32) NULL
        , [LastEmptyRowsetTime] datetime NULL
        , [LastActivatedTime] datetime NULL
        , [TasksWaiting] int NULL
        , [ActivatedTaskCount] int NULL
        , [AssessmentStatus] varchar(32) NOT NULL
        , [EvidenceLimit] nvarchar(1000) NOT NULL
        , PRIMARY KEY ([DatabaseName],[QueueObjectId])
    );
    CREATE TABLE [#ServiceBrokerAnalysis_TransmissionGroup]
    (
          [DatabaseName] sysname NOT NULL
        , [FromServiceName] nvarchar(256) NULL
        , [ToServiceName] nvarchar(256) NULL
        , [ToBrokerInstance] nvarchar(128) NULL
        , [ServiceContractName] nvarchar(256) NULL
        , [MessageTypeName] nvarchar(256) NULL
        , [TransmissionStatus] nvarchar(4000) NULL
        , [MessageCount] bigint NOT NULL
        , [ConversationErrorMessageCount] bigint NOT NULL
        , [EndDialogMessageCount] bigint NOT NULL
        , [OldestEnqueueTimeUtc] datetime NULL
        , [NewestEnqueueTimeUtc] datetime NULL
        , [OldestAgeMinutes] bigint NULL
        , [EvidenceLimit] nvarchar(1000) NOT NULL
    );
    CREATE TABLE [#ServiceBrokerAnalysis_ConversationState]
    (
          [DatabaseName] sysname NOT NULL
        , [StateCode] char(2) NOT NULL
        , [StateDescription] nvarchar(60) NULL
        , [IsInitiator] bit NOT NULL
        , [IsSystem] bit NOT NULL
        , [EndpointCount] bigint NOT NULL
        , [ExpiredLifetimeCount] bigint NOT NULL
        , [EarliestLifetimeUtc] datetime NULL
        , [EarliestSecurityTimestampUtc] datetime NULL
        , [EvidenceLimit] nvarchar(1000) NOT NULL
    );
    CREATE TABLE [#ServiceBrokerAnalysis_Findings]
    (
          [FindingOrdinal] bigint IDENTITY(1,1) NOT NULL
        , [DatabaseName] sysname NULL
        , [SchemaName] sysname NULL
        , [ObjectName] sysname NULL
        , [Severity] varchar(16) NOT NULL
        , [Confidence] varchar(16) NOT NULL
        , [FindingCode] varchar(120) NOT NULL
        , [MetricName] varchar(80) NOT NULL
        , [MetricValue] decimal(38,4) NULL
        , [ThresholdValue] decimal(38,4) NULL
        , [Evidence] nvarchar(1000) NOT NULL
        , [EvidenceLimit] nvarchar(1000) NOT NULL
        , [RecommendedNextCheck] nvarchar(1000) NOT NULL
    );

    IF @StatusCode='AVAILABLE'
    BEGIN
        EXEC [monitor].[USP_PrepareNameFilters]
              @SchemaNames=@SchemaNames
            , @ObjectNames=@ObjectNames
            , @FullObjectNames=@FullObjectNames
            , @IndexNames=NULL
            , @StatisticsNames=NULL
            , @ColumnNames=NULL
            , @StatusCode=@StatusCode OUTPUT
            , @ErrorMessage=@ErrorMessage OUTPUT,@FilterTable=N'#ServiceBrokerAnalysis_NameFilters';
        IF @StatusCode<>'AVAILABLE' SET @IsPartial=1;
    END;

    DECLARE @CrossDatabaseRequested bit=0;
    IF @StatusCode='AVAILABLE'
    BEGIN
        EXEC [monitor].[USP_PrepareDatabaseCandidates]
              @DatabaseNames=@DatabaseNames
            , @SystemdatenbankenEinbeziehen=@SystemdatenbankenEinbeziehen
            , @DatabaseNamePattern=@DatabaseNamePattern,@HighImpactConfirmed=@HighImpactConfirmed

            , @AnalysisClass='CATALOG_DEEP'
            , @StatusCode=@StatusCode OUTPUT
            , @ErrorMessage=@ErrorMessage OUTPUT
            , @CrossDatabaseRequested=@CrossDatabaseRequested OUTPUT,@CandidateTable=N'#ServiceBrokerAnalysis_DatabaseCandidates',@WarningTable=N'#ServiceBrokerAnalysis_DatabaseCandidateWarnings';
        IF @StatusCode<>'AVAILABLE' SET @IsPartial=1;
    END;

    INSERT [#ServiceBrokerAnalysis_DatabaseStatus]
    ([DatabaseName],[StatusCode],[IsPartial],[IsBrokerEnabled],[UserQueueCount],[UserServiceCount],
     [TransmissionMessageCount],[ConversationEndpointCount],[SourceFailureCount],[FindingCount],[Detail])
    SELECT [DatabaseName],'PENDING',0,NULL,0,0,0,0,0,0,
           N'Feature-Gate und Service-Broker-Quellen werden datenbankweise best effort ausgewertet.'
    FROM [#ServiceBrokerAnalysis_DatabaseCandidates];

    INSERT [#ServiceBrokerAnalysis_DatabaseStatus]
    ([DatabaseName],[StatusCode],[IsPartial],[IsBrokerEnabled],[UserQueueCount],[UserServiceCount],
     [TransmissionMessageCount],[ConversationEndpointCount],[SourceFailureCount],[FindingCount],[ErrorMessage],[Detail])
    SELECT [RequestedName],[StatusCode],1,NULL,0,0,0,0,1,0,[ErrorMessage],N'Explizit angeforderte Datenbank nicht auswertbar.'
    FROM [#ServiceBrokerAnalysis_DatabaseCandidateWarnings];

    IF @StatusCode='AVAILABLE' AND NOT EXISTS(SELECT 1 FROM [#ServiceBrokerAnalysis_DatabaseCandidates])
    BEGIN
        SELECT @StatusCode='NOT_APPLICABLE',@ErrorMessage=N'Keine auswertbare Datenbank im gewählten Scope.';
    END;

    DECLARE @SchemaPredicate nvarchar(max)=
        N' AND (NOT EXISTS(SELECT 1 FROM [#ServiceBrokerAnalysis_NameFilters] WHERE [FilterType]=''SCHEMA'') OR EXISTS(SELECT 1 FROM [#ServiceBrokerAnalysis_NameFilters] [f] WHERE [f].[FilterType]=''SCHEMA'' AND [f].[NameValue]=[s].[name] COLLATE SQL_Latin1_General_CP1_CS_AS))';
    DECLARE @ObjectPredicate nvarchar(max)=
        N' AND (NOT EXISTS(SELECT 1 FROM [#ServiceBrokerAnalysis_NameFilters] WHERE [FilterType]=''OBJECT'') OR EXISTS(SELECT 1 FROM [#ServiceBrokerAnalysis_NameFilters] [f] WHERE [f].[FilterType]=''OBJECT'' AND [f].[NameValue]=[t].[name] COLLATE SQL_Latin1_General_CP1_CS_AS))';
    DECLARE @FullObjectPredicate nvarchar(max)=
        N' AND (NOT EXISTS(SELECT 1 FROM [#ServiceBrokerAnalysis_NameFilters] WHERE [FilterType]=''FULL_OBJECT'') OR EXISTS(SELECT 1 FROM [#ServiceBrokerAnalysis_NameFilters] [f] WHERE [f].[FilterType]=''FULL_OBJECT'' AND ([f].[DatabaseName] IS NULL OR [f].[DatabaseName]=@pDatabaseName COLLATE SQL_Latin1_General_CP1_CS_AS) AND ([f].[SchemaName] IS NULL OR [f].[SchemaName]=[s].[name] COLLATE SQL_Latin1_General_CP1_CS_AS) AND [f].[ObjectName]=[t].[name] COLLATE SQL_Latin1_General_CP1_CS_AS))';
    IF @SchemaPatternMode='LIKE'
        SET @SchemaPredicate+=N' AND [s].[name] COLLATE SQL_Latin1_General_CP1_CS_AS LIKE N'''+REPLACE(@SchemaPatternValue,N'''',N'''''')+N''' COLLATE SQL_Latin1_General_CP1_CS_AS';
    IF @SchemaPatternMode IN('REGEX','REGEXI')
        SET @SchemaPredicate+=N' AND REGEXP_LIKE([s].[name],N'''+REPLACE(@SchemaPatternValue,N'''',N'''''')+N''','''+@SchemaRegexFlags+N''')';
    IF @ObjectPatternMode='LIKE'
        SET @ObjectPredicate+=N' AND [t].[name] COLLATE SQL_Latin1_General_CP1_CS_AS LIKE N'''+REPLACE(@ObjectPatternValue,N'''',N'''''')+N''' COLLATE SQL_Latin1_General_CP1_CS_AS';
    IF @ObjectPatternMode IN('REGEX','REGEXI')
        SET @ObjectPredicate+=N' AND REGEXP_LIKE([t].[name],N'''+REPLACE(@ObjectPatternValue,N'''',N'''''')+N''','''+@ObjectRegexFlags+N''')';

    IF @StatusCode='AVAILABLE'
    BEGIN
        DECLARE @DbName sysname,@CompatibilityLevel int,@Sql nvarchar(max),@Rows bigint;
        DECLARE [DatabaseCursor] CURSOR LOCAL FAST_FORWARD FOR
            SELECT [DatabaseName],[CompatibilityLevel]
            FROM [#ServiceBrokerAnalysis_DatabaseCandidates]
            ORDER BY COALESCE([RequestedOrdinal],[DatabaseId]),[DatabaseId];
        OPEN [DatabaseCursor];
        FETCH NEXT FROM [DatabaseCursor] INTO @DbName,@CompatibilityLevel;

        WHILE @@FETCH_STATUS=0
        BEGIN
            IF (@SchemaPatternMode IN('REGEX','REGEXI') OR @ObjectPatternMode IN('REGEX','REGEXI'))
               AND COALESCE(@CompatibilityLevel,0)<170
            BEGIN
                UPDATE [#ServiceBrokerAnalysis_DatabaseStatus]
                SET [StatusCode]='UNAVAILABLE_FEATURE',[IsPartial]=1,[SourceFailureCount]=1,
                    [ErrorMessage]=N'Regex-Pattern benötigen Compatibility Level 170.',
                    [Detail]=N'Für diese Datenbank wurde wegen inkompatiblem Patternvertrag keine Analyse ausgeführt.'
                WHERE [DatabaseName]=@DbName;
                INSERT [#ServiceBrokerAnalysis_SourceStatus]
                VALUES(@DbName,'FILTER_CONTRACT','UNAVAILABLE_FEATURE',1,0,NULL,NULL,
                       N'Regex-Pattern benötigen Compatibility Level 170.',N'Keine Quellenabfrage ausgeführt.');
                FETCH NEXT FROM [DatabaseCursor] INTO @DbName,@CompatibilityLevel;
                CONTINUE;
            END;

            BEGIN TRY
                SET @Sql=N'SET LOCK_TIMEOUT '+CONVERT(nvarchar(11),@LockTimeoutMs)+N'; USE '+QUOTENAME(@DbName)+N';
INSERT [#ServiceBrokerAnalysis_FeatureScope]([DatabaseName],[IsBrokerEnabled],[UserQueueCount],[UserServiceCount])
SELECT @pDatabaseName,CONVERT(bit,[d].[is_broker_enabled]),[q].[QueueCount],[svc].[ServiceCount]
FROM [sys].[databases] [d] WITH (NOLOCK)
CROSS APPLY
(
    SELECT COUNT_BIG(*) AS [QueueCount]
    FROM [sys].[service_queues] WITH (NOLOCK)
    WHERE [is_ms_shipped]=0
) [q]
CROSS APPLY
(
    SELECT COUNT_BIG(*) AS [ServiceCount]
    FROM [sys].[services] [x] WITH (NOLOCK)
    JOIN [sys].[service_queues] [sq] WITH (NOLOCK) ON [sq].[object_id]=[x].[service_queue_id]
    WHERE [sq].[is_ms_shipped]=0
) [svc]
WHERE [d].[database_id]=DB_ID();
SET @pRows=@@ROWCOUNT;';
                SET @Rows=0;
                EXEC [sys].[sp_executesql] @Sql,N'@pDatabaseName sysname,@pRows bigint OUTPUT',
                     @pDatabaseName=@DbName,@pRows=@Rows OUTPUT;
                INSERT [#ServiceBrokerAnalysis_SourceStatus]
                VALUES(@DbName,'BROKER_FEATURE_GATE','AVAILABLE',0,@Rows,
                       N'Katalogsicht auf sichtbare Datenbank- und Broker-Metadaten',NULL,NULL,
                       N'Prüft Datenbankschalter und sichtbare nicht ausgelieferte Queues/Services; Nullzählungen beweisen bei eingeschränkter Metadatensichtbarkeit keine Abwesenheit.');
                UPDATE [ds]
                SET [IsBrokerEnabled]=[fs].[IsBrokerEnabled],
                    [UserQueueCount]=[fs].[UserQueueCount],
                    [UserServiceCount]=[fs].[UserServiceCount]
                FROM [#ServiceBrokerAnalysis_DatabaseStatus] [ds]
                JOIN [#ServiceBrokerAnalysis_FeatureScope] [fs] ON [fs].[DatabaseName]=[ds].[DatabaseName]
                WHERE [ds].[DatabaseName]=@DbName;
            END TRY
            BEGIN CATCH
                INSERT [#ServiceBrokerAnalysis_SourceStatus]
                VALUES(@DbName,'BROKER_FEATURE_GATE','ERROR_HANDLED',1,0,
                       N'Katalogsicht auf sichtbare Datenbank- und Broker-Metadaten',ERROR_NUMBER(),ERROR_MESSAGE(),
                       N'Feature-Sichtbarkeit konnte nicht bestimmt werden.');
                UPDATE [#ServiceBrokerAnalysis_DatabaseStatus]
                SET [StatusCode]='ERROR_HANDLED',[IsPartial]=1,[SourceFailureCount]=[SourceFailureCount]+1,
                    [ErrorNumber]=ERROR_NUMBER(),[ErrorMessage]=ERROR_MESSAGE(),
                    [Detail]=N'Feature-Gate fehlgeschlagen; keine belastbare Anwendbarkeitsaussage.'
                WHERE [DatabaseName]=@DbName;
            END CATCH;

            IF NOT EXISTS(SELECT 1 FROM [#ServiceBrokerAnalysis_FeatureScope] WHERE [DatabaseName]=@DbName)
            BEGIN
                FETCH NEXT FROM [DatabaseCursor] INTO @DbName,@CompatibilityLevel;
                CONTINUE;
            END;

            IF EXISTS
            (
                SELECT 1 FROM [#ServiceBrokerAnalysis_FeatureScope]
                WHERE [DatabaseName]=@DbName AND [IsBrokerEnabled]=0
                  AND [UserQueueCount]=0 AND [UserServiceCount]=0
            )
            BEGIN
                UPDATE [#ServiceBrokerAnalysis_DatabaseStatus]
                SET [StatusCode]='NOT_APPLICABLE_VISIBLE_SCOPE',[IsPartial]=0,
                    [Detail]=N'Service Broker ist deaktiviert und im sichtbaren Katalogscope wurden keine benutzerdefinierten Queues oder Services erkannt; dies beweist bei eingeschränkter Metadatensichtbarkeit keine vollständige Abwesenheit.'
                WHERE [DatabaseName]=@DbName;
                INSERT [#ServiceBrokerAnalysis_SourceStatus]
                SELECT @DbName,[SourceCode],'NOT_APPLICABLE',0,0,[RequiredPermission],NULL,NULL,
                       N'Quelle wegen negativem sichtbaren Feature-Gate nicht aufgerufen.'
                FROM (VALUES
                      ('BROKER_QUEUE_CATALOG',N'Katalogsicht auf sichtbare Broker-Queues und Services'),
                      ('BROKER_QUEUE_CAPACITY',N'VIEW DATABASE STATE und VIEW DEFINITION; SQL Server 2022+: VIEW DATABASE PERFORMANCE STATE und VIEW SECURITY DEFINITION'),
                      ('BROKER_QUEUE_MONITOR',N'SQL Server 2019: VIEW SERVER STATE; SQL Server 2022+: VIEW SERVER PERFORMANCE STATE'),
                      ('BROKER_ACTIVATED_TASKS',N'SQL Server 2019: VIEW SERVER STATE; SQL Server 2022+: VIEW SERVER PERFORMANCE STATE'),
                      ('BROKER_TRANSMISSION',N'Katalogsicht auf sys.transmission_queue'),
                      ('BROKER_CONVERSATION',N'Katalogsicht auf sys.conversation_endpoints'))
                     [x]([SourceCode],[RequiredPermission]);
                FETCH NEXT FROM [DatabaseCursor] INTO @DbName,@CompatibilityLevel;
                CONTINUE;
            END;

            BEGIN TRY
                SET @Sql=N'SET LOCK_TIMEOUT '+CONVERT(nvarchar(11),@LockTimeoutMs)+N'; USE '+QUOTENAME(@DbName)+N';
INSERT [#ServiceBrokerAnalysis_Queue]
([DatabaseName],[SchemaName],[QueueName],[QueueObjectId],[ServiceCount],[IsBrokerEnabled],
 [IsActivationEnabled],[IsReceiveEnabled],[IsEnqueueEnabled],[IsRetentionEnabled],
 [IsPoisonMessageHandlingEnabled],[MaxReaders],[ActivationProcedure],[ExecuteAsPrincipalId],
 [AssessmentStatus],[EvidenceLimit])
SELECT @pDatabaseName,[s].[name],[t].[name],[t].[object_id],CONVERT(int,[svc].[ServiceCount]),
       CONVERT(bit,[d].[is_broker_enabled]),[t].[is_activation_enabled],[t].[is_receive_enabled],
       [t].[is_enqueue_enabled],[t].[is_retention_enabled],[t].[is_poison_message_handling_enabled],
       [t].[max_readers],[t].[activation_procedure],[t].[execute_as_principal_id],''AVAILABLE'',
       N''Queue-Kataloge und Aktivierungsmetadaten beweisen weder erfolgreiche Verarbeitung noch die Ursache eines deaktivierten Zustands.''
FROM [sys].[service_queues] [t] WITH (NOLOCK)
JOIN [sys].[schemas] [s] WITH (NOLOCK) ON [s].[schema_id]=[t].[schema_id]
OUTER APPLY
(
    SELECT COUNT_BIG(*) AS [ServiceCount]
    FROM [sys].[services] [x] WITH (NOLOCK)
    WHERE [x].[service_queue_id]=[t].[object_id]
) [svc]
CROSS APPLY
(
    SELECT [is_broker_enabled]
    FROM [sys].[databases] WITH (NOLOCK)
    WHERE [database_id]=DB_ID()
) [d]
WHERE [t].[is_ms_shipped]=0'+@SchemaPredicate+@ObjectPredicate+@FullObjectPredicate+N';
SET @pRows=@@ROWCOUNT;';
                SET @Rows=0;
