    CREATE TABLE [#DataCaptureDeepAnalysis_Findings]
    (
          [FindingOrdinal] bigint IDENTITY(1,1) NOT NULL
        , [DatabaseName] sysname NULL
        , [SchemaName] sysname NULL
        , [ObjectName] sysname NULL
        , [Severity] varchar(16) NOT NULL
        , [Confidence] varchar(16) NOT NULL
        , [FindingCode] varchar(120) NOT NULL
        , [MetricName] varchar(80) NOT NULL
        , [MetricValue] decimal(38,4) NULL
        , [ThresholdValue] decimal(38,4) NULL
        , [Evidence] nvarchar(1000) NOT NULL
        , [EvidenceLimit] nvarchar(1000) NOT NULL
        , [RecommendedNextCheck] nvarchar(1000) NOT NULL
    );

    IF @StatusCode='AVAILABLE'
    BEGIN
        EXEC [monitor].[USP_PrepareNameFilters]
              @SchemaNames=@SchemaNames
            , @ObjectNames=@ObjectNames
            , @FullObjectNames=@FullObjectNames
            , @IndexNames=NULL
            , @StatisticsNames=NULL
            , @ColumnNames=NULL
            , @StatusCode=@StatusCode OUTPUT
            , @ErrorMessage=@ErrorMessage OUTPUT,@FilterTable=N'#DataCaptureDeepAnalysis_NameFilters';
        IF @StatusCode<>'AVAILABLE' SET @IsPartial=1;
    END;

    DECLARE @CrossDatabaseRequested bit=0;
    IF @StatusCode='AVAILABLE'
    BEGIN
        EXEC [monitor].[USP_PrepareDatabaseCandidates]
              @DatabaseNames=@DatabaseNames
            , @SystemdatenbankenEinbeziehen=@SystemdatenbankenEinbeziehen
            , @DatabaseNamePattern=@DatabaseNamePattern,@HighImpactConfirmed=@HighImpactConfirmed

            , @AnalysisClass='CATALOG_DEEP'
            , @StatusCode=@StatusCode OUTPUT
            , @ErrorMessage=@ErrorMessage OUTPUT
            , @CrossDatabaseRequested=@CrossDatabaseRequested OUTPUT,@CandidateTable=N'#DataCaptureDeepAnalysis_DatabaseCandidates',@WarningTable=N'#DataCaptureDeepAnalysis_DatabaseCandidateWarnings';
        IF @StatusCode<>'AVAILABLE' SET @IsPartial=1;
    END;

    IF @StatusCode='AVAILABLE' AND @ChangeTrackingClientVersion IS NOT NULL
       AND (SELECT COUNT_BIG(*) FROM [#DataCaptureDeepAnalysis_DatabaseCandidates])<>1
    BEGIN
        SELECT @StatusCode='INVALID_PARAMETER',@IsPartial=1,
               @ErrorMessage=N'@ChangeTrackingClientVersion ist datenbankspezifisch und darf nur mit genau einer ausgewaehlten Datenbank verwendet werden.';
    END;

    INSERT [#DataCaptureDeepAnalysis_DatabaseStatus]
    ([DatabaseName],[StatusCode],[IsPartial],[CtTableCount],[CdcCaptureInstanceCount],
     [FindingCount],[SourceFailureCount],[Detail])
    SELECT [DatabaseName],CASE WHEN @StatusCode='AVAILABLE' THEN 'PENDING' ELSE @StatusCode END,
           CASE WHEN @StatusCode='AVAILABLE' THEN 0 ELSE 1 END,0,0,0,
           CASE WHEN @StatusCode='AVAILABLE' THEN 0 ELSE 1 END,
           CASE WHEN @StatusCode='AVAILABLE'
                THEN N'Feature-Gate und Data-Capture-Quellen werden datenbankweise best effort ausgewertet.'
                ELSE @ErrorMessage END
    FROM [#DataCaptureDeepAnalysis_DatabaseCandidates];

    INSERT [#DataCaptureDeepAnalysis_DatabaseStatus]
    ([DatabaseName],[StatusCode],[IsPartial],[CtTableCount],[CdcCaptureInstanceCount],
     [FindingCount],[SourceFailureCount],[ErrorMessage],[Detail])
    SELECT [RequestedName],[StatusCode],1,0,0,0,1,[ErrorMessage],N'Explizit angeforderte Datenbank nicht auswertbar.'
    FROM [#DataCaptureDeepAnalysis_DatabaseCandidateWarnings];

    IF @StatusCode='AVAILABLE' AND NOT EXISTS(SELECT 1 FROM [#DataCaptureDeepAnalysis_DatabaseCandidates])
        SELECT @StatusCode='NOT_APPLICABLE',@ErrorMessage=N'Keine auswertbare Datenbank im gewaehlten Scope.';

    DECLARE @SchemaPredicate nvarchar(max)=
        N' AND (NOT EXISTS(SELECT 1 FROM [#DataCaptureDeepAnalysis_NameFilters] WHERE [FilterType]=''SCHEMA'') OR EXISTS(SELECT 1 FROM [#DataCaptureDeepAnalysis_NameFilters] [f] WHERE [f].[FilterType]=''SCHEMA'' AND [f].[NameValue]=[s].[name] COLLATE SQL_Latin1_General_CP1_CS_AS))';
    DECLARE @ObjectPredicate nvarchar(max)=
        N' AND (NOT EXISTS(SELECT 1 FROM [#DataCaptureDeepAnalysis_NameFilters] WHERE [FilterType]=''OBJECT'') OR EXISTS(SELECT 1 FROM [#DataCaptureDeepAnalysis_NameFilters] [f] WHERE [f].[FilterType]=''OBJECT'' AND [f].[NameValue]=[t].[name] COLLATE SQL_Latin1_General_CP1_CS_AS))';
    DECLARE @FullObjectPredicate nvarchar(max)=
        N' AND (NOT EXISTS(SELECT 1 FROM [#DataCaptureDeepAnalysis_NameFilters] WHERE [FilterType]=''FULL_OBJECT'') OR EXISTS(SELECT 1 FROM [#DataCaptureDeepAnalysis_NameFilters] [f] WHERE [f].[FilterType]=''FULL_OBJECT'' AND ([f].[DatabaseName] IS NULL OR [f].[DatabaseName]=@pDatabaseName COLLATE SQL_Latin1_General_CP1_CS_AS) AND ([f].[SchemaName] IS NULL OR [f].[SchemaName]=[s].[name] COLLATE SQL_Latin1_General_CP1_CS_AS) AND [f].[ObjectName]=[t].[name] COLLATE SQL_Latin1_General_CP1_CS_AS))';
    IF @SchemaPatternMode='LIKE'
        SET @SchemaPredicate+=N' AND [s].[name] COLLATE SQL_Latin1_General_CP1_CS_AS LIKE N'''+REPLACE(@SchemaPatternValue,N'''',N'''''')+N''' COLLATE SQL_Latin1_General_CP1_CS_AS';
    IF @SchemaPatternMode IN('REGEX','REGEXI')
        SET @SchemaPredicate+=N' AND REGEXP_LIKE([s].[name],N'''+REPLACE(@SchemaPatternValue,N'''',N'''''')+N''','''+@SchemaRegexFlags+N''')';
    IF @ObjectPatternMode='LIKE'
        SET @ObjectPredicate+=N' AND [t].[name] COLLATE SQL_Latin1_General_CP1_CS_AS LIKE N'''+REPLACE(@ObjectPatternValue,N'''',N'''''')+N''' COLLATE SQL_Latin1_General_CP1_CS_AS';
    IF @ObjectPatternMode IN('REGEX','REGEXI')
        SET @ObjectPredicate+=N' AND REGEXP_LIKE([t].[name],N'''+REPLACE(@ObjectPatternValue,N'''',N'''''')+N''','''+@ObjectRegexFlags+N''')';

    IF @StatusCode='AVAILABLE'
    BEGIN
        DECLARE @DbName sysname,@CompatibilityLevel int,@Sql nvarchar(max),@Rows bigint,@HasCdcCatalog bit,@CdcCount bigint;
        DECLARE [DatabaseCursor] CURSOR LOCAL FAST_FORWARD FOR
            SELECT [DatabaseName],[CompatibilityLevel]
            FROM [#DataCaptureDeepAnalysis_DatabaseCandidates]
            ORDER BY COALESCE([RequestedOrdinal],[DatabaseId]),[DatabaseId];
        OPEN [DatabaseCursor];
        FETCH NEXT FROM [DatabaseCursor] INTO @DbName,@CompatibilityLevel;

        WHILE @@FETCH_STATUS=0
        BEGIN
            IF (@SchemaPatternMode IN('REGEX','REGEXI') OR @ObjectPatternMode IN('REGEX','REGEXI'))
               AND COALESCE(@CompatibilityLevel,0)<170
            BEGIN
                UPDATE [#DataCaptureDeepAnalysis_DatabaseStatus]
                SET [StatusCode]='UNAVAILABLE_FEATURE',[IsPartial]=1,[SourceFailureCount]=1,
                    [ErrorMessage]=N'Regex-Pattern benoetigen Compatibility Level 170.',
                    [Detail]=N'Fuer diese Datenbank wurde wegen inkompatiblem Patternvertrag keine Analyse ausgefuehrt.'
                WHERE [DatabaseName]=@DbName;
                INSERT [#DataCaptureDeepAnalysis_SourceStatus]
                VALUES(@DbName,'FILTER_CONTRACT','UNAVAILABLE_FEATURE',1,0,NULL,NULL,
                       N'Regex-Pattern benoetigen Compatibility Level 170.',N'Keine Quellenabfrage ausgefuehrt.');
                FETCH NEXT FROM [DatabaseCursor] INTO @DbName,@CompatibilityLevel;
                CONTINUE;
            END;

            BEGIN TRY
                SET @Sql=N'SET LOCK_TIMEOUT '+CONVERT(nvarchar(11),@LockTimeoutMs)+N'; USE '+QUOTENAME(@DbName)+N';
INSERT [#DataCaptureDeepAnalysis_FeatureScope]
([DatabaseName],[IsChangeTrackingEnabled],[CurrentCtVersion],[CtRetentionPeriod],[CtRetentionUnit],
 [IsCtAutoCleanupOn],[CtTableCount],[IsCdcEnabled],[CdcCaptureInstanceCount],
 [IsPublished],[IsSubscribed],[IsMergePublished],[IsDistributor])
SELECT @pDatabaseName,CONVERT(bit,CASE WHEN [ctd].[database_id] IS NULL THEN 0 ELSE 1 END),
       CHANGE_TRACKING_CURRENT_VERSION(),[ctd].[retention_period],[ctd].[retention_period_units_desc],
       [ctd].[is_auto_cleanup_on],
       (SELECT COUNT_BIG(*) FROM [sys].[change_tracking_tables] WITH (NOLOCK)),
       [d].[is_cdc_enabled],0,[d].[is_published],[d].[is_subscribed],
       [d].[is_merge_published],[d].[is_distributor]
FROM [sys].[databases] [d] WITH (NOLOCK)
LEFT JOIN [sys].[change_tracking_databases] [ctd] WITH (NOLOCK)
  ON [ctd].[database_id]=[d].[database_id]
WHERE [d].[database_id]=DB_ID();
SELECT @pHasCdcCatalog=CONVERT(bit,CASE WHEN EXISTS(SELECT 1 FROM [sys].[tables] AS [t] WITH (NOLOCK) JOIN [sys].[schemas] AS [s] WITH (NOLOCK) ON [s].[schema_id]=[t].[schema_id] WHERE [s].[name]=N''cdc'' AND [t].[name]=N''change_tables'') THEN 1 ELSE 0 END);
SET @pRows=@@ROWCOUNT;';
                SELECT @Rows=0,@HasCdcCatalog=0;
                EXEC [sys].[sp_executesql] @Sql,
                     N'@pDatabaseName sysname,@pHasCdcCatalog bit OUTPUT,@pRows bigint OUTPUT',
                     @pDatabaseName=@DbName,@pHasCdcCatalog=@HasCdcCatalog OUTPUT,@pRows=@Rows OUTPUT;
                INSERT [#DataCaptureDeepAnalysis_SourceStatus]
                VALUES(@DbName,'DATA_CAPTURE_FEATURE_GATE','AVAILABLE',0,@Rows,N'Katalogsicht',NULL,NULL,
                       N'Zaehlt sichtbare Feature- und Katalogmetadaten; Nullzaehlungen beweisen bei eingeschraenkter Sichtbarkeit keine Abwesenheit.');
            END TRY
            BEGIN CATCH
                INSERT [#DataCaptureDeepAnalysis_SourceStatus]
                VALUES(@DbName,'DATA_CAPTURE_FEATURE_GATE','ERROR_HANDLED',1,0,N'Katalogsicht',ERROR_NUMBER(),ERROR_MESSAGE(),
                       N'Feature-Gate fehlgeschlagen; keine belastbare Anwendbarkeitsaussage.');
                UPDATE [#DataCaptureDeepAnalysis_DatabaseStatus]
                SET [StatusCode]='ERROR_HANDLED',[IsPartial]=1,[SourceFailureCount]=[SourceFailureCount]+1,
                    [ErrorNumber]=ERROR_NUMBER(),[ErrorMessage]=ERROR_MESSAGE(),
                    [Detail]=N'Feature-Gate fehlgeschlagen; zugaengliche andere Datenbanken bleiben erhalten.'
                WHERE [DatabaseName]=@DbName;
            END CATCH;

            IF NOT EXISTS(SELECT 1 FROM [#DataCaptureDeepAnalysis_FeatureScope] WHERE [DatabaseName]=@DbName)
            BEGIN
                FETCH NEXT FROM [DatabaseCursor] INTO @DbName,@CompatibilityLevel;
                CONTINUE;
            END;

            BEGIN TRY
                SET @Sql=N'SET LOCK_TIMEOUT '+CONVERT(nvarchar(11),@LockTimeoutMs)+N'; USE '+QUOTENAME(@DbName)+N';
INSERT [#DataCaptureDeepAnalysis_ChangeTrackingTable]
([DatabaseName],[SchemaName],[TableName],[TableObjectId],[IsTrackColumnsUpdatedOn],
 [BeginVersion],[CleanupVersion],[MinValidVersion],[CurrentVersion],[ClientVersion],
 [AssessmentStatus],[EvidenceLimit])
SELECT @pDatabaseName,[s].[name],[t].[name],[ct].[object_id],[ct].[is_track_columns_updated_on],
       [ct].[begin_version],[ct].[cleanup_version],CHANGE_TRACKING_MIN_VALID_VERSION([ct].[object_id]),
       CHANGE_TRACKING_CURRENT_VERSION(),@pClientVersion,''AVAILABLE'',
       N''MinValidVersion ist tabellenspezifisch. Nur der Vergleich mit einem echten Client-Wasserstand kann Synchronisationsverlust belegen.''
FROM [sys].[change_tracking_tables] [ct] WITH (NOLOCK)
JOIN [sys].[tables] [t] WITH (NOLOCK) ON [t].[object_id]=[ct].[object_id]
JOIN [sys].[schemas] [s] WITH (NOLOCK) ON [s].[schema_id]=[t].[schema_id]
WHERE 1=1'+@SchemaPredicate+@ObjectPredicate+@FullObjectPredicate+N';
SET @pRows=@@ROWCOUNT;';
                SET @Rows=0;
                EXEC [sys].[sp_executesql] @Sql,
                     N'@pDatabaseName sysname,@pClientVersion bigint,@pRows bigint OUTPUT',
                     @pDatabaseName=@DbName,@pClientVersion=@ChangeTrackingClientVersion,@pRows=@Rows OUTPUT;
                INSERT [#DataCaptureDeepAnalysis_SourceStatus]
                VALUES(@DbName,'CHANGE_TRACKING_TABLES','AVAILABLE',0,@Rows,N'Katalogsicht',NULL,NULL,
                       N'Es werden ausschliesslich CT-Katalogversionen und keine Aenderungszeilen gelesen.');
            END TRY
            BEGIN CATCH
                INSERT [#DataCaptureDeepAnalysis_SourceStatus]
                VALUES(@DbName,'CHANGE_TRACKING_TABLES','ERROR_HANDLED',1,0,N'Katalogsicht',ERROR_NUMBER(),ERROR_MESSAGE(),
                       N'CT-Tabellenevidenz konnte nicht gelesen werden.');
            END CATCH;

            IF @HasCdcCatalog=1
            BEGIN
                BEGIN TRY
                    SET @Sql=N'SET LOCK_TIMEOUT '+CONVERT(nvarchar(11),@LockTimeoutMs)+N'; USE '+QUOTENAME(@DbName)+N';
INSERT [#DataCaptureDeepAnalysis_CdcCaptureInstance]
([DatabaseName],[CaptureInstance],[SourceSchema],[SourceTable],[SourceObjectId],
 [SupportsNetChanges],[HasDropPending],[CreateDate],[OldestAvailableTimeUtc],
 [OldestAvailableAgeMinutes],[AssessmentStatus],[EvidenceLimit])
SELECT @pDatabaseName,[ct].[capture_instance],[s].[name],[t].[name],[ct].[source_object_id],
       [ct].[supports_net_changes],[ct].[has_drop_pending],[ct].[create_date],
       [x].[OldestTime],DATEDIFF_BIG(MINUTE,[x].[OldestTime],@pNow),''AVAILABLE'',
       N''Das Alter des aeltesten verfuegbaren LSN wird gegen die Cleanup-Retention nur heuristisch bewertet; ruhige Systeme und Cleanup-Timing begrenzen die Aussage.''
FROM [cdc].[change_tables] [ct] WITH (NOLOCK)
LEFT JOIN [sys].[tables] [t] WITH (NOLOCK) ON [t].[object_id]=[ct].[source_object_id]
LEFT JOIN [sys].[schemas] [s] WITH (NOLOCK) ON [s].[schema_id]=[t].[schema_id]
OUTER APPLY
(
    SELECT [sys].[fn_cdc_map_lsn_to_time]([sys].[fn_cdc_get_min_lsn]([ct].[capture_instance])) AS [OldestTime]
) [x]
WHERE 1=1'+@SchemaPredicate+@ObjectPredicate+@FullObjectPredicate+N';
SET @pRows=@@ROWCOUNT;
SELECT @pCdcCount=COUNT_BIG(*) FROM [cdc].[change_tables] WITH (NOLOCK);';
                    SELECT @Rows=0,@CdcCount=0;
                    EXEC [sys].[sp_executesql] @Sql,
                         N'@pDatabaseName sysname,@pNow datetime2(3),@pCdcCount bigint OUTPUT,@pRows bigint OUTPUT',
                         @pDatabaseName=@DbName,@pNow=@Now,@pCdcCount=@CdcCount OUTPUT,@pRows=@Rows OUTPUT;
                    UPDATE [#DataCaptureDeepAnalysis_FeatureScope] SET [CdcCaptureInstanceCount]=@CdcCount WHERE [DatabaseName]=@DbName;
                    INSERT [#DataCaptureDeepAnalysis_SourceStatus]
                    VALUES(@DbName,'CDC_CAPTURE_INSTANCES','AVAILABLE',0,@Rows,N'Katalogsicht auf CDC-Metadaten',NULL,NULL,
                           N'Es werden Capture-Konfiguration und LSN-Zeitgrenzen, aber keine Change-Table-Zeilen gelesen.');
                END TRY
                BEGIN CATCH
                    INSERT [#DataCaptureDeepAnalysis_SourceStatus]
                    VALUES(@DbName,'CDC_CAPTURE_INSTANCES','ERROR_HANDLED',1,0,N'Katalogsicht auf CDC-Metadaten',ERROR_NUMBER(),ERROR_MESSAGE(),
                           N'CDC-Capture-Instanzen oder ihre Zeitgrenzen konnten nicht gelesen werden.');
                END CATCH;
            END
            ELSE
                INSERT [#DataCaptureDeepAnalysis_SourceStatus]
                VALUES(@DbName,'CDC_CAPTURE_INSTANCES','NOT_APPLICABLE',0,0,N'Katalogsicht auf CDC-Metadaten',NULL,NULL,
                       N'cdc.change_tables ist im sichtbaren Datenbankkontext nicht vorhanden.');

            IF EXISTS(SELECT 1 FROM [#DataCaptureDeepAnalysis_FeatureScope] WHERE [DatabaseName]=@DbName AND [IsCdcEnabled]=1)
            BEGIN
                BEGIN TRY
                    SET @Sql=N'SET LOCK_TIMEOUT '+CONVERT(nvarchar(11),@LockTimeoutMs)+N'; USE '+QUOTENAME(@DbName)+N';
INSERT [#DataCaptureDeepAnalysis_CdcScanSession]
([DatabaseName],[SessionId],[StartTimeUtc],[EndTimeUtc],[ScanPhase],[ErrorCount],
 [LastCommitTimeUtc],[LastCommitCdcTimeUtc],[LatencySeconds],
 [EmptyScanCount],[FailedSessionsCount],[AssessmentStatus],[EvidenceLimit])
SELECT @pDatabaseName,[session_id],[start_time],[end_time],[scan_phase],[error_count],
       [last_commit_time],[last_commit_cdc_time],[latency],
       [empty_scan_count],[failed_sessions_count],''AVAILABLE'',
       N''CDC-Scan-DMVs enthalten nur einen Neustart-/Failover-abhaengigen Ausschnitt; auf einer AG-Sekundaerreplik kann die Quelle leer sein.''
FROM [sys].[dm_cdc_log_scan_sessions] WITH (NOLOCK)
WHERE [session_id]=0 OR [session_id]=(SELECT MAX([session_id]) FROM [sys].[dm_cdc_log_scan_sessions] WITH (NOLOCK));
SET @pRows=@@ROWCOUNT;';
                    SET @Rows=0;
                    EXEC [sys].[sp_executesql] @Sql,N'@pDatabaseName sysname,@pRows bigint OUTPUT',
                         @pDatabaseName=@DbName,@pRows=@Rows OUTPUT;
                    INSERT [#DataCaptureDeepAnalysis_SourceStatus]
                    VALUES(@DbName,'CDC_LOG_SCAN_SESSIONS','AVAILABLE',0,@Rows,
                           N'VIEW DATABASE STATE; SQL Server 2022+ quellenabhaengige Datenbankberechtigung',NULL,NULL,
                           N'Aggregatzeile und neueste Sitzung; DMV wird bei Neustart oder Failover zurueckgesetzt.');
                END TRY
                BEGIN CATCH
                    INSERT [#DataCaptureDeepAnalysis_SourceStatus]
                    VALUES(@DbName,'CDC_LOG_SCAN_SESSIONS','ERROR_HANDLED',1,0,
                           N'VIEW DATABASE STATE; SQL Server 2022+ quellenabhaengige Datenbankberechtigung',ERROR_NUMBER(),ERROR_MESSAGE(),
                           N'CDC-Scan-Evidenz fehlt; andere Quellen bleiben gueltig.');
                END CATCH;

                BEGIN TRY
                    SET @Sql=N'SET LOCK_TIMEOUT '+CONVERT(nvarchar(11),@LockTimeoutMs)+N'; USE '+QUOTENAME(@DbName)+N';
INSERT [#DataCaptureDeepAnalysis_CdcErrorGroup]
([DatabaseName],[ErrorNumber],[ErrorSeverity],[PhaseNumber],[ErrorCount],
 [FirstErrorTimeUtc],[LastErrorTimeUtc],[EvidenceLimit])
SELECT @pDatabaseName,[error_number],[error_severity],[phase_number],COUNT_BIG(*),MIN([entry_time]),MAX([entry_time]),
       N''CDC-Fehler-DMV enthaelt nur die letzten Sitzungen seit Neustart; Meldungstext und LSN-Werte werden nicht ausgegeben.''
FROM [sys].[dm_cdc_errors] WITH (NOLOCK)
WHERE [entry_time]>=DATEADD(HOUR,-@pLookback,@pNow)
GROUP BY [error_number],[error_severity],[phase_number];
SET @pRows=@@ROWCOUNT;';
                    SET @Rows=0;
                    EXEC [sys].[sp_executesql] @Sql,
                         N'@pDatabaseName sysname,@pLookback int,@pNow datetime2(3),@pRows bigint OUTPUT',
                         @pDatabaseName=@DbName,@pLookback=@ErrorLookbackHours,@pNow=@Now,@pRows=@Rows OUTPUT;
                    INSERT [#DataCaptureDeepAnalysis_SourceStatus]
                    VALUES(@DbName,'CDC_ERRORS','AVAILABLE',0,@Rows,
                           N'SQL Server 2019: VIEW DATABASE STATE; SQL Server 2022+: VIEW DATABASE PERFORMANCE STATE',NULL,NULL,
                           N'Fehler werden nach Nummer, Schweregrad und Phase aggregiert; keine Meldungstexte oder LSNs.');
                END TRY
                BEGIN CATCH
                    INSERT [#DataCaptureDeepAnalysis_SourceStatus]
                    VALUES(@DbName,'CDC_ERRORS','ERROR_HANDLED',1,0,
                           N'SQL Server 2019: VIEW DATABASE STATE; SQL Server 2022+: VIEW DATABASE PERFORMANCE STATE',ERROR_NUMBER(),ERROR_MESSAGE(),
                           N'CDC-Fehlerevidenz fehlt; andere Quellen bleiben gueltig.');
                END CATCH;
            END
            ELSE
            BEGIN
                INSERT [#DataCaptureDeepAnalysis_SourceStatus]
                VALUES
                (@DbName,'CDC_LOG_SCAN_SESSIONS','NOT_APPLICABLE',0,0,N'VIEW DATABASE STATE',NULL,NULL,N'CDC ist laut sichtbarem Feature-Gate nicht aktiviert.'),
                (@DbName,'CDC_ERRORS','NOT_APPLICABLE',0,0,N'VIEW DATABASE STATE',NULL,NULL,N'CDC ist laut sichtbarem Feature-Gate nicht aktiviert.');
            END;

            IF EXISTS(SELECT 1 FROM [#DataCaptureDeepAnalysis_FeatureScope] WHERE [DatabaseName]=@DbName AND [IsCdcEnabled]=1)
            BEGIN
                BEGIN TRY
                    SET @Sql=N'SET LOCK_TIMEOUT '+CONVERT(nvarchar(11),@LockTimeoutMs)+N';
SELECT @pRows=0;
IF EXISTS(SELECT 1 FROM [msdb].[sys].[tables] AS [t] WITH (NOLOCK) JOIN [msdb].[sys].[schemas] AS [s] WITH (NOLOCK) ON [s].[schema_id]=[t].[schema_id] WHERE [s].[name]=N''dbo'' AND [t].[name]=N''cdc_jobs'')
BEGIN
    INSERT [#DataCaptureDeepAnalysis_CdcJob]
    ([DatabaseName],[JobType],[IsEnabled],[LastRunOutcome],[LastRunTimeUtc],
     [MaxTrans],[MaxScans],[IsContinuous],[PollingIntervalSeconds],[RetentionMinutes],
     [DeleteThreshold],[AssessmentStatus],[EvidenceLimit])
    SELECT @pDatabaseName,[cj].[job_type],[j].[enabled],[h].[run_status],
           CASE WHEN [h].[run_date]>0 THEN [msdb].[dbo].[agent_datetime]([h].[run_date],[h].[run_time]) END,
           [cj].[maxtrans],[cj].[maxscans],[cj].[continuous],[cj].[pollinginterval],
           [cj].[retention],[cj].[threshold],''AVAILABLE'',
           N''Jobkonfiguration und letzter Jobausgang sind keine lueckenlose Capture- oder Cleanup-Historie.''
    FROM [msdb].[dbo].[cdc_jobs] [cj] WITH (NOLOCK)
    LEFT JOIN [msdb].[dbo].[sysjobs] [j] WITH (NOLOCK) ON [j].[job_id]=[cj].[job_id]
    OUTER APPLY
    (
        SELECT TOP(1) [x].[run_status],[x].[run_date],[x].[run_time]
        FROM [msdb].[dbo].[sysjobhistory] [x] WITH (NOLOCK)
        WHERE [x].[job_id]=[cj].[job_id] AND [x].[step_id]=0
        ORDER BY [x].[instance_id] DESC
    ) [h]
    WHERE [cj].[database_id]=(SELECT [database_id] FROM [master].[sys].[databases] WITH (NOLOCK) WHERE [name]=@pDatabaseName);
    SET @pRows=@@ROWCOUNT;
END;
';
                    SET @Rows=0;
                    EXEC [sys].[sp_executesql] @Sql,N'@pDatabaseName sysname,@pRows bigint OUTPUT',
                         @pDatabaseName=@DbName,@pRows=@Rows OUTPUT;
                    UPDATE [ci]
                    SET [CleanupRetentionMinutes]=[j].[RetentionMinutes]
                    FROM [#DataCaptureDeepAnalysis_CdcCaptureInstance] [ci]
                    CROSS APPLY
                    (
                        SELECT MAX([RetentionMinutes]) AS [RetentionMinutes]
                        FROM [#DataCaptureDeepAnalysis_CdcJob]
                        WHERE [DatabaseName]=@DbName AND [JobType]=N'cleanup'
                    ) [j]
                    WHERE [ci].[DatabaseName]=@DbName;
                    INSERT [#DataCaptureDeepAnalysis_SourceStatus]
                    VALUES(@DbName,'CDC_JOBS','AVAILABLE',0,@Rows,N'Lesesicht auf msdb CDC- und Agent-Metadaten',NULL,NULL,
                           N'Jobnamen, Owner, Schritte, Commands, Proxies und Anmeldeinformationen werden nicht ausgegeben.');
                END TRY
                BEGIN CATCH
                    INSERT [#DataCaptureDeepAnalysis_SourceStatus]
                    VALUES(@DbName,'CDC_JOBS','ERROR_HANDLED',1,0,N'Lesesicht auf msdb CDC- und Agent-Metadaten',ERROR_NUMBER(),ERROR_MESSAGE(),
                           N'CDC-Jobevidenz fehlt; andere Quellen bleiben gueltig.');
                END CATCH;
            END
            ELSE
                INSERT [#DataCaptureDeepAnalysis_SourceStatus]
                VALUES(@DbName,'CDC_JOBS','NOT_APPLICABLE',0,0,N'Lesesicht auf msdb CDC- und Agent-Metadaten',NULL,NULL,
                       N'CDC ist laut sichtbarem Feature-Gate nicht aktiviert.');

            FETCH NEXT FROM [DatabaseCursor] INTO @DbName,@CompatibilityLevel;
        END;

        CLOSE [DatabaseCursor];
        DEALLOCATE [DatabaseCursor];
    END;

    DECLARE @DistributionDatabase sysname=NULL;
    DECLARE @ReplicationScopeDetected bit=CONVERT(bit,CASE WHEN EXISTS
    (
        SELECT 1 FROM [#DataCaptureDeepAnalysis_FeatureScope]
        WHERE [IsPublished]=1 OR [IsSubscribed]=1 OR [IsMergePublished]=1 OR [IsDistributor]=1
    ) THEN 1 ELSE 0 END);
    DECLARE @ReplicationAllowed bit=0;

    IF @ReplicationScopeDetected=1
    BEGIN
        SELECT @ReplicationAllowed=[IsAllowed]
        FROM [monitor].[VW_AnalyseAccessCurrent]
        WHERE [AnalysisClass]='ENTERPRISE_TOPOLOGY_DEEP';

        IF COALESCE(@ReplicationAllowed,0)=0
            INSERT [#DataCaptureDeepAnalysis_SourceStatus]
            VALUES(NULL,'REPLICATION_POLICY','DENIED_GROUP',1,0,N'ENTERPRISE_TOPOLOGY_DEEP',NULL,
                   N'Die lokale Replikations-Tiefenanalyse ist fuer den aktuellen Login nicht freigegeben.',
                   N'Die Topologie bleibt unbeobachtet; dies ist kein gesunder Befund.');
        ELSE
        BEGIN TRY
                IF EXISTS(SELECT 1 FROM [msdb].[sys].[tables] AS [t] WITH (NOLOCK) JOIN [msdb].[sys].[schemas] AS [s] WITH (NOLOCK) ON [s].[schema_id]=[t].[schema_id] WHERE [s].[name]=N'dbo' AND [t].[name]=N'MSdistributiondbs')
                    INSERT [#DataCaptureDeepAnalysis_DistributionDatabase]([DatabaseName])
                    SELECT DISTINCT [name]
                    FROM [msdb].[dbo].[MSdistributiondbs] WITH (NOLOCK)
                    WHERE EXISTS(SELECT 1 FROM [master].[sys].[databases] AS [d] WITH (NOLOCK) WHERE [d].[name]=[MSdistributiondbs].[name]);
            INSERT [#DataCaptureDeepAnalysis_SourceStatus]
            VALUES(NULL,'REPLICATION_DISTRIBUTOR_DISCOVERY','AVAILABLE',0,
                   (SELECT COUNT_BIG(*) FROM [#DataCaptureDeepAnalysis_DistributionDatabase]),
                   N'Lesesicht auf msdb Replikationsmetadaten',NULL,NULL,
                   CASE WHEN NOT EXISTS(SELECT 1 FROM [#DataCaptureDeepAnalysis_DistributionDatabase])
                        THEN N'Keine lokal registrierte Distribution-Datenbank sichtbar; Remote- oder Berechtigungsgrenzen werden datenbankbezogen bewertet.'
                        ELSE N'Lokal registrierte Distribution-Datenbanken sind sichtbar; nur lokale aggregierte Metadaten werden gelesen.' END);
        END TRY
        BEGIN CATCH
            INSERT [#DataCaptureDeepAnalysis_SourceStatus]
            VALUES(NULL,'REPLICATION_DISTRIBUTOR_DISCOVERY','ERROR_HANDLED',1,0,
                   N'Lesesicht auf msdb Replikationsmetadaten',ERROR_NUMBER(),ERROR_MESSAGE(),
                   N'Distributor-Topologie ist nicht belastbar bestimmbar; dies ist kein gesunder Befund.');
        END CATCH;
    END;
    ELSE
        INSERT [#DataCaptureDeepAnalysis_SourceStatus]
        VALUES(NULL,'REPLICATION_DISTRIBUTOR_DISCOVERY','NOT_APPLICABLE',0,0,
               N'ENTERPRISE_TOPOLOGY_DEEP und Lesesicht auf msdb Replikationsmetadaten',NULL,NULL,
               N'Keine Replikationsrolle im sichtbaren ausgewaehlten Datenbankscope erkannt.');

    IF EXISTS(SELECT 1 FROM [#DataCaptureDeepAnalysis_DistributionDatabase])
    BEGIN
        DECLARE [DistributionDatabaseCursor] CURSOR LOCAL FAST_FORWARD FOR
            SELECT [DatabaseName] FROM [#DataCaptureDeepAnalysis_DistributionDatabase] ORDER BY [DatabaseName];
        OPEN [DistributionDatabaseCursor];
        FETCH NEXT FROM [DistributionDatabaseCursor] INTO @DistributionDatabase;

        WHILE @@FETCH_STATUS=0
        BEGIN
        BEGIN TRY
            SET @Sql=N'SET LOCK_TIMEOUT '+CONVERT(nvarchar(11),@LockTimeoutMs)+N'; USE '+QUOTENAME(@DistributionDatabase)+N';
IF (SELECT COUNT(*) FROM [sys].[tables] AS [t] WITH (NOLOCK) JOIN [sys].[schemas] AS [s] WITH (NOLOCK) ON [s].[schema_id]=[t].[schema_id] WHERE [s].[name]=N''dbo'' AND [t].[name] IN (N''MSdistribution_agents'',N''MSdistribution_history'',N''MSdistribution_status'',N''MSsubscriptions''))<>4
    ;THROW 54020,N''Erforderliche lokale Distribution-Metadaten fehlen.'',1;
INSERT [#DataCaptureDeepAnalysis_ReplicationAgent]
([AgentType],[DistributionDatabase],[AgentId],[PublisherDatabase],[PublicationName],[SubscriberName],
 [SubscriberDatabase],[RunStatus],[LastHistoryTimeUtc],[DurationSeconds],
 [DeliveryLatencyMs],[PendingCommandCount],[DeliveredCommandCount],
 [InactiveSubscriptionCount],[LastHistoryAgeMinutes],[AssessmentStatus],[EvidenceLimit])
SELECT ''DISTRIBUTION'',@pDistributionDatabase,[a].[id],[a].[publisher_db],[a].[publication],[a].[subscriber_name],
       [a].[subscriber_db],[h].[runstatus],[h].[time],[h].[duration],[h].[delivery_latency],
       [p].[PendingCommands],[h].[delivered_commands],[s].[InactiveSubscriptions],
       DATEDIFF_BIG(MINUTE,[h].[time],@pNow),''AVAILABLE'',
       N''Undelivered commands sind ein lokaler Distributor-Snapshot. Idle ist ohne Rueckstand kein Fehler; History ist keine lueckenlose Zeitreihe.''
FROM [dbo].[MSdistribution_agents] [a] WITH (NOLOCK)
OUTER APPLY
(
    SELECT TOP(1) [x].[runstatus],[x].[time],[x].[duration],[x].[delivery_latency],[x].[delivered_commands]
    FROM [dbo].[MSdistribution_history] [x] WITH (NOLOCK)
    WHERE [x].[agent_id]=[a].[id]
    ORDER BY [x].[time] DESC
) [h]
OUTER APPLY
(
    SELECT SUM(CONVERT(bigint,[x].[UndelivCmdsInDistDB])) AS [PendingCommands]
    FROM [dbo].[MSdistribution_status] [x] WITH (NOLOCK)
    WHERE [x].[agent_id]=[a].[id]
) [p]
OUTER APPLY
(
    SELECT COUNT_BIG(*) AS [InactiveSubscriptions]
    FROM [dbo].[MSsubscriptions] [x] WITH (NOLOCK)
    WHERE [x].[agent_id]=[a].[id] AND [x].[status]<>2
) [s]
WHERE EXISTS
(
    SELECT 1 FROM [#DataCaptureDeepAnalysis_FeatureScope] [fs]
    WHERE [fs].[DatabaseName]=[a].[publisher_db] COLLATE SQL_Latin1_General_CP1_CS_AS
       OR [fs].[DatabaseName]=[a].[subscriber_db] COLLATE SQL_Latin1_General_CP1_CS_AS
       OR [fs].[IsDistributor]=1
);
SET @pRows=@@ROWCOUNT;';
            SET @Rows=0;
            EXEC [sys].[sp_executesql] @Sql,N'@pDistributionDatabase sysname,@pNow datetime2(3),@pRows bigint OUTPUT',
                 @pDistributionDatabase=@DistributionDatabase,@pNow=@Now,@pRows=@Rows OUTPUT;
            INSERT [#DataCaptureDeepAnalysis_SourceStatus]
            VALUES(NULL,'REPLICATION_DISTRIBUTION_AGENTS','AVAILABLE',0,@Rows,N'Lesesicht auf lokale Distribution-Datenbank',NULL,NULL,
                   N'Keine Replikationsbefehle, Sequenznummern, Kommentare, Job-Commands oder Sicherheitsprofile werden gelesen.');
        END TRY
        BEGIN CATCH
            INSERT [#DataCaptureDeepAnalysis_SourceStatus]
            VALUES(NULL,'REPLICATION_DISTRIBUTION_AGENTS','ERROR_HANDLED',1,0,N'Lesesicht auf lokale Distribution-Datenbank',ERROR_NUMBER(),ERROR_MESSAGE(),
                   N'Distribution-Agent-, Rueckstands- oder Historienevidenz fehlt.');
        END CATCH;

        BEGIN TRY
            SET @Sql=N'SET LOCK_TIMEOUT '+CONVERT(nvarchar(11),@LockTimeoutMs)+N'; USE '+QUOTENAME(@DistributionDatabase)+N';
IF (SELECT COUNT(*) FROM [sys].[tables] AS [t] WITH (NOLOCK) JOIN [sys].[schemas] AS [s] WITH (NOLOCK) ON [s].[schema_id]=[t].[schema_id] WHERE [s].[name]=N''dbo'' AND [t].[name] IN (N''MSlogreader_agents'',N''MSlogreader_history''))<>2
    ;THROW 54021,N''Erforderliche lokale Log-Reader-Metadaten fehlen.'',1;
INSERT [#DataCaptureDeepAnalysis_ReplicationAgent]
([AgentType],[DistributionDatabase],[AgentId],[PublisherDatabase],[PublicationName],[RunStatus],
 [LastHistoryTimeUtc],[DurationSeconds],[DeliveryLatencyMs],[DeliveredCommandCount],
 [LastHistoryAgeMinutes],[AssessmentStatus],[EvidenceLimit])
SELECT ''LOG_READER'',@pDistributionDatabase,[a].[id],[a].[publisher_db],[a].[publication],[h].[runstatus],
       [h].[time],[h].[duration],[h].[delivery_latency],[h].[delivered_commands],
       DATEDIFF_BIG(MINUTE,[h].[time],@pNow),''AVAILABLE'',
       N''Log-Reader-History ist eine lokale, bereinigbare Verlaufstabelle; einzelne Zustandszeilen beweisen keine dauerhafte Stoerung.''
FROM [dbo].[MSlogreader_agents] [a] WITH (NOLOCK)
OUTER APPLY
(
    SELECT TOP(1) [x].[runstatus],[x].[time],[x].[duration],[x].[delivery_latency],[x].[delivered_commands]
    FROM [dbo].[MSlogreader_history] [x] WITH (NOLOCK)
    WHERE [x].[agent_id]=[a].[id]
    ORDER BY [x].[time] DESC
) [h]
WHERE EXISTS
(
    SELECT 1 FROM [#DataCaptureDeepAnalysis_FeatureScope] [fs]
    WHERE [fs].[DatabaseName]=[a].[publisher_db] COLLATE SQL_Latin1_General_CP1_CS_AS
       OR [fs].[IsDistributor]=1
);
SET @pRows=@@ROWCOUNT;';
            SET @Rows=0;
            EXEC [sys].[sp_executesql] @Sql,N'@pDistributionDatabase sysname,@pNow datetime2(3),@pRows bigint OUTPUT',
                 @pDistributionDatabase=@DistributionDatabase,@pNow=@Now,@pRows=@Rows OUTPUT;
            INSERT [#DataCaptureDeepAnalysis_SourceStatus]
            VALUES(NULL,'REPLICATION_LOG_READER_AGENTS','AVAILABLE',0,@Rows,N'Lesesicht auf lokale Distribution-Datenbank',NULL,NULL,
                   N'Agent- und Historienmetadaten ohne Login-, Passwort-, Command-, Kommentar- oder Sequenzdaten.');
        END TRY
        BEGIN CATCH
            INSERT [#DataCaptureDeepAnalysis_SourceStatus]
            VALUES(NULL,'REPLICATION_LOG_READER_AGENTS','ERROR_HANDLED',1,0,N'Lesesicht auf lokale Distribution-Datenbank',ERROR_NUMBER(),ERROR_MESSAGE(),
                   N'Log-Reader-Agent- oder Historienevidenz fehlt.');
        END CATCH;

        BEGIN TRY
            SET @Sql=N'SET LOCK_TIMEOUT '+CONVERT(nvarchar(11),@LockTimeoutMs)+N'; USE '+QUOTENAME(@DistributionDatabase)+N';
IF (SELECT COUNT(*) FROM [sys].[tables] AS [t] WITH (NOLOCK) JOIN [sys].[schemas] AS [s] WITH (NOLOCK) ON [s].[schema_id]=[t].[schema_id] WHERE [s].[name]=N''dbo'' AND [t].[name] IN (N''MSmerge_agents'',N''MSmerge_sessions''))<>2
    ;THROW 54022,N''Erforderliche lokale Merge-Metadaten fehlen.'',1;
INSERT [#DataCaptureDeepAnalysis_ReplicationAgent]
([AgentType],[DistributionDatabase],[AgentId],[PublisherDatabase],[PublicationName],[SubscriberName],
 [SubscriberDatabase],[RunStatus],[LastHistoryTimeUtc],[DurationSeconds],
 [ConflictCount],[RetryCount],[LastHistoryAgeMinutes],[AssessmentStatus],[EvidenceLimit])
SELECT ''MERGE'',@pDistributionDatabase,[a].[id],[a].[publisher_db],[a].[publication],[a].[subscriber_name],
       [a].[subscriber_db],[h].[runstatus],[h].[end_time],[h].[duration],
       COALESCE([h].[upload_conflicts],0)+COALESCE([h].[download_conflicts],0),
       COALESCE([h].[upload_rows_retried],0)+COALESCE([h].[download_rows_retried],0),
       DATEDIFF_BIG(MINUTE,[h].[end_time],@pNow),''AVAILABLE'',
       N''Merge-Sessions sind lokale, bereinigbare Historie; Konflikt- und Retry-Zaehler benoetigen Publication- und Workload-Kontext.''
FROM [dbo].[MSmerge_agents] [a] WITH (NOLOCK)
OUTER APPLY
(
    SELECT TOP(1) [x].[runstatus],[x].[end_time],[x].[duration],
           [x].[upload_conflicts],[x].[download_conflicts],[x].[upload_rows_retried],[x].[download_rows_retried]
    FROM [dbo].[MSmerge_sessions] [x] WITH (NOLOCK)
    WHERE [x].[agent_id]=[a].[id]
    ORDER BY [x].[start_time] DESC
) [h]
WHERE EXISTS
(
    SELECT 1 FROM [#DataCaptureDeepAnalysis_FeatureScope] [fs]
    WHERE [fs].[DatabaseName]=[a].[publisher_db] COLLATE SQL_Latin1_General_CP1_CS_AS
       OR [fs].[DatabaseName]=[a].[subscriber_db] COLLATE SQL_Latin1_General_CP1_CS_AS
       OR [fs].[IsDistributor]=1
);
SET @pRows=@@ROWCOUNT;';
            SET @Rows=0;
            EXEC [sys].[sp_executesql] @Sql,N'@pDistributionDatabase sysname,@pNow datetime2(3),@pRows bigint OUTPUT',
                 @pDistributionDatabase=@DistributionDatabase,@pNow=@Now,@pRows=@Rows OUTPUT;
            INSERT [#DataCaptureDeepAnalysis_SourceStatus]
            VALUES(NULL,'REPLICATION_MERGE_AGENTS','AVAILABLE',0,@Rows,N'Lesesicht auf lokale Distribution-Datenbank',NULL,NULL,
                   N'Keine Zeilenkonflikte, Resolver-Nutzdaten, Agent-Credentials oder Job-Commands werden gelesen.');
        END TRY
        BEGIN CATCH
            INSERT [#DataCaptureDeepAnalysis_SourceStatus]
            VALUES(NULL,'REPLICATION_MERGE_AGENTS','ERROR_HANDLED',1,0,N'Lesesicht auf lokale Distribution-Datenbank',ERROR_NUMBER(),ERROR_MESSAGE(),
                   N'Merge-Agent- oder Sessionevidenz fehlt.');
        END CATCH;

        BEGIN TRY
            SET @Sql=N'SET LOCK_TIMEOUT '+CONVERT(nvarchar(11),@LockTimeoutMs)+N'; USE '+QUOTENAME(@DistributionDatabase)+N';
IF NOT EXISTS(SELECT 1 FROM [sys].[tables] AS [t] WITH (NOLOCK) JOIN [sys].[schemas] AS [s] WITH (NOLOCK) ON [s].[schema_id]=[t].[schema_id] WHERE [s].[name]=N''dbo'' AND [t].[name]=N''MSrepl_errors'')
    ;THROW 54023,N''Lokale Replikationsfehlertabelle fehlt.'',1;
INSERT [#DataCaptureDeepAnalysis_ReplicationErrorGroup]
([DistributionDatabase],[ErrorCode],[ErrorCount],[FirstErrorTimeUtc],[LastErrorTimeUtc],[EvidenceLimit])
SELECT @pDistributionDatabase,[error_code],COUNT_BIG(*),MIN([time]),MAX([time]),
       N''Replikationsfehler werden nur nach Code und Zeit aggregiert; Quellname, Fehlertext, Command und Sequenznummern bleiben ausgeschlossen.''
FROM [dbo].[MSrepl_errors] WITH (NOLOCK)
WHERE [time]>=DATEADD(HOUR,-@pLookback,@pNow)
GROUP BY [error_code];
SET @pRows=@@ROWCOUNT;';
            SET @Rows=0;
            EXEC [sys].[sp_executesql] @Sql,N'@pDistributionDatabase sysname,@pLookback int,@pNow datetime2(3),@pRows bigint OUTPUT',
                 @pDistributionDatabase=@DistributionDatabase,@pLookback=@ErrorLookbackHours,@pNow=@Now,@pRows=@Rows OUTPUT;
            INSERT [#DataCaptureDeepAnalysis_SourceStatus]
            VALUES(NULL,'REPLICATION_ERRORS','AVAILABLE',0,@Rows,N'Lesesicht auf lokale Distribution-Datenbank',NULL,NULL,
                   N'Nur Fehlercode, Anzahl und Zeitgrenzen werden ausgegeben.');
        END TRY
        BEGIN CATCH
            INSERT [#DataCaptureDeepAnalysis_SourceStatus]
            VALUES(NULL,'REPLICATION_ERRORS','ERROR_HANDLED',1,0,N'Lesesicht auf lokale Distribution-Datenbank',ERROR_NUMBER(),ERROR_MESSAGE(),
                   N'Aggregierte lokale Replikationsfehlerevidenz fehlt.');
        END CATCH;

            FETCH NEXT FROM [DistributionDatabaseCursor] INTO @DistributionDatabase;
        END;

        CLOSE [DistributionDatabaseCursor];
        DEALLOCATE [DistributionDatabaseCursor];
    END
    ELSE
    BEGIN
        INSERT [#DataCaptureDeepAnalysis_SourceStatus]
        VALUES
        (NULL,'REPLICATION_DISTRIBUTION_AGENTS','NOT_APPLICABLE',0,0,N'Lesesicht auf lokale Distribution-Datenbank',NULL,NULL,N'Lokale Distribution nicht aufgerufen oder nicht sichtbar; Discovery- und Policy-Status beachten.'),
        (NULL,'REPLICATION_LOG_READER_AGENTS','NOT_APPLICABLE',0,0,N'Lesesicht auf lokale Distribution-Datenbank',NULL,NULL,N'Lokale Distribution nicht aufgerufen oder nicht sichtbar; Discovery- und Policy-Status beachten.'),
        (NULL,'REPLICATION_MERGE_AGENTS','NOT_APPLICABLE',0,0,N'Lesesicht auf lokale Distribution-Datenbank',NULL,NULL,N'Lokale Distribution nicht aufgerufen oder nicht sichtbar; Discovery- und Policy-Status beachten.'),
        (NULL,'REPLICATION_ERRORS','NOT_APPLICABLE',0,0,N'Lesesicht auf lokale Distribution-Datenbank',NULL,NULL,N'Lokale Distribution nicht aufgerufen oder nicht sichtbar; Discovery- und Policy-Status beachten.');
    END;

    UPDATE [ds]
    SET [IsChangeTrackingEnabled]=[fs].[IsChangeTrackingEnabled],
        [CtTableCount]=[fs].[CtTableCount],
        [IsCdcEnabled]=[fs].[IsCdcEnabled],
        [CdcCaptureInstanceCount]=[fs].[CdcCaptureInstanceCount],
        [HasReplicationRole]=CONVERT(bit,CASE WHEN [fs].[IsPublished]=1 OR [fs].[IsSubscribed]=1
                                                  OR [fs].[IsMergePublished]=1 OR [fs].[IsDistributor]=1
                                             THEN 1 ELSE 0 END)
    FROM [#DataCaptureDeepAnalysis_DatabaseStatus] [ds]
    JOIN [#DataCaptureDeepAnalysis_FeatureScope] [fs] ON [fs].[DatabaseName]=[ds].[DatabaseName];

    INSERT [#DataCaptureDeepAnalysis_Findings]
    ([DatabaseName],[Severity],[Confidence],[FindingCode],[MetricName],[Evidence],[EvidenceLimit],[RecommendedNextCheck])
    SELECT [DatabaseName],'INFO','HIGH','CT_CLIENT_WATERMARK_NOT_SUPPLIED','CLIENT_VERSION',
           N'Change Tracking ist sichtbar, aber es wurde kein Client-Wasserstand geliefert; ein Synchronisationsverlust kann daher nicht bewertet werden.',
           N'MinValidVersion allein belegt keinen betroffenen Client. Verschiedene Consumer koennen unterschiedliche Wasserstaende besitzen.',
           N'Pro Consumer dessen zuletzt erfolgreich bestaetigte Synchronisationsversion kontrolliert als @ChangeTrackingClientVersion pruefen.'
    FROM [#DataCaptureDeepAnalysis_FeatureScope]
    WHERE [IsChangeTrackingEnabled]=1 AND @ChangeTrackingClientVersion IS NULL;

    INSERT [#DataCaptureDeepAnalysis_Findings]
    ([DatabaseName],[SchemaName],[ObjectName],[Severity],[Confidence],[FindingCode],[MetricName],[MetricValue],[ThresholdValue],
     [Evidence],[EvidenceLimit],[RecommendedNextCheck])
    SELECT [DatabaseName],[SchemaName],[TableName],'WARN','HIGH','CT_CLIENT_REINITIALIZATION_REQUIRED','CLIENT_VERSION',
           [ClientVersion],[MinValidVersion],
           N'Der gelieferte Client-Wasserstand liegt unter der minimal gueltigen Version dieser Change-Tracking-Tabelle.',
           [EvidenceLimit],N'Consumer fuer diese Tabelle kontrolliert reinitialisieren; keine inkrementelle Enumeration ab dem ungueltigen Wasserstand fortsetzen.'
    FROM [#DataCaptureDeepAnalysis_ChangeTrackingTable]
    WHERE [ClientVersion] IS NOT NULL AND [MinValidVersion] IS NOT NULL AND [ClientVersion]<[MinValidVersion];

    INSERT [#DataCaptureDeepAnalysis_Findings]
    ([DatabaseName],[SchemaName],[ObjectName],[Severity],[Confidence],[FindingCode],[MetricName],[MetricValue],[ThresholdValue],
     [Evidence],[EvidenceLimit],[RecommendedNextCheck])
    SELECT [DatabaseName],[SchemaName],[TableName],'WARN','HIGH','CT_CLIENT_VERSION_IN_FUTURE','CLIENT_VERSION',
           [ClientVersion],[CurrentVersion],N'Der gelieferte Client-Wasserstand liegt ueber der aktuellen Datenbankversion.',
           [EvidenceLimit],N'Consumer-Zustand, Datenbankzuordnung und Persistenz des Wasserstands korrigieren, bevor synchronisiert wird.'
    FROM [#DataCaptureDeepAnalysis_ChangeTrackingTable]
    WHERE [ClientVersion] IS NOT NULL AND [CurrentVersion] IS NOT NULL AND [ClientVersion]>[CurrentVersion];

    INSERT [#DataCaptureDeepAnalysis_Findings]
    ([DatabaseName],[Severity],[Confidence],[FindingCode],[MetricName],[MetricValue],[ThresholdValue],
     [Evidence],[EvidenceLimit],[RecommendedNextCheck])
    SELECT [DatabaseName],'INFO','HIGH','CT_AUTO_CLEANUP_DISABLED','AUTO_CLEANUP_ON',0,1,
           N'Change-Tracking-Auto-Cleanup ist deaktiviert.',
           N'Dies kann absichtliche Konfiguration sein und ist ohne Speicher- und Betriebsziel kein Fehler.',
           N'Retention-, Speicher- und Consumer-Anforderungen pruefen; keine automatische Konfigurationsaenderung ausfuehren.'
    FROM [#DataCaptureDeepAnalysis_FeatureScope]
    WHERE [IsChangeTrackingEnabled]=1 AND [IsCtAutoCleanupOn]=0;

    INSERT [#DataCaptureDeepAnalysis_Findings]
    ([DatabaseName],[SchemaName],[ObjectName],[Severity],[Confidence],[FindingCode],[MetricName],[MetricValue],[ThresholdValue],
     [Evidence],[EvidenceLimit],[RecommendedNextCheck])
    SELECT [DatabaseName],[SourceSchema],COALESCE([SourceTable],[CaptureInstance]),'WARN','HIGH','CDC_CAPTURE_INSTANCE_DROP_PENDING','HAS_DROP_PENDING',1,0,
           N'Die CDC-Capture-Instanz ist als drop-pending markiert.',[EvidenceLimit],
           N'CDC-DDL-Historie, lang laufende Capture-/Cleanup-Aktivitaet und den beabsichtigten Instanzlebenszyklus in der Laufzeitumgebung pruefen.'
    FROM [#DataCaptureDeepAnalysis_CdcCaptureInstance]
    WHERE [HasDropPending]=1;

    INSERT [#DataCaptureDeepAnalysis_Findings]
    ([DatabaseName],[Severity],[Confidence],[FindingCode],[MetricName],[MetricValue],[ThresholdValue],
     [Evidence],[EvidenceLimit],[RecommendedNextCheck])
    SELECT [fs].[DatabaseName],'WARN','HIGH','CDC_CAPTURE_JOB_MISSING_OR_DISABLED','ENABLED_CAPTURE_JOB_COUNT',
           COALESCE([j].[EnabledCount],0),1,N'CDC ist mit sichtbarer Capture-Instanz aktiviert, aber kein aktivierter Capture-Job ist sichtbar.',
           N'Bei alternativer Plattform- oder Hochverfuegbarkeitssteuerung kann die Jobinterpretation abweichen; fehlende Rechte koennen Sichtbarkeit begrenzen.',
           N'CDC-Betriebsmodus und Agentjob in der Laufzeitumgebung pruefen; keine automatische Jobaenderung ausfuehren.'
    FROM [#DataCaptureDeepAnalysis_FeatureScope] [fs]
    OUTER APPLY
    (
        SELECT SUM(CASE WHEN [IsEnabled]=1 THEN CONVERT(bigint,1) ELSE CONVERT(bigint,0) END) AS [EnabledCount]
        FROM [#DataCaptureDeepAnalysis_CdcJob] WHERE [DatabaseName]=[fs].[DatabaseName] AND [JobType]=N'capture'
    ) [j]
    WHERE [fs].[IsCdcEnabled]=1 AND [fs].[CdcCaptureInstanceCount]>0 AND COALESCE([j].[EnabledCount],0)=0
      AND EXISTS(SELECT 1 FROM [#DataCaptureDeepAnalysis_SourceStatus] WHERE [DatabaseName]=[fs].[DatabaseName] AND [SourceCode]='CDC_JOBS' AND [StatusCode]='AVAILABLE');

    INSERT [#DataCaptureDeepAnalysis_Findings]
    ([DatabaseName],[Severity],[Confidence],[FindingCode],[MetricName],[MetricValue],[ThresholdValue],
     [Evidence],[EvidenceLimit],[RecommendedNextCheck])
    SELECT [fs].[DatabaseName],'WARN','HIGH','CDC_CLEANUP_JOB_MISSING_OR_DISABLED','ENABLED_CLEANUP_JOB_COUNT',
           COALESCE([j].[EnabledCount],0),1,N'CDC ist mit sichtbarer Capture-Instanz aktiviert, aber kein aktivierter Cleanup-Job ist sichtbar.',
           N'Alternative Plattformsteuerung und eingeschraenkte msdb-Sichtbarkeit koennen die Jobinterpretation begrenzen.',
           N'Cleanup-Betriebsmodus und Retention in der Laufzeitumgebung pruefen; keine automatische Bereinigung starten.'
    FROM [#DataCaptureDeepAnalysis_FeatureScope] [fs]
    OUTER APPLY
    (
        SELECT SUM(CASE WHEN [IsEnabled]=1 THEN CONVERT(bigint,1) ELSE CONVERT(bigint,0) END) AS [EnabledCount]
        FROM [#DataCaptureDeepAnalysis_CdcJob] WHERE [DatabaseName]=[fs].[DatabaseName] AND [JobType]=N'cleanup'
    ) [j]
    WHERE [fs].[IsCdcEnabled]=1 AND [fs].[CdcCaptureInstanceCount]>0 AND COALESCE([j].[EnabledCount],0)=0
      AND EXISTS(SELECT 1 FROM [#DataCaptureDeepAnalysis_SourceStatus] WHERE [DatabaseName]=[fs].[DatabaseName] AND [SourceCode]='CDC_JOBS' AND [StatusCode]='AVAILABLE');

    INSERT [#DataCaptureDeepAnalysis_Findings]
    ([DatabaseName],[Severity],[Confidence],[FindingCode],[MetricName],[MetricValue],[ThresholdValue],
     [Evidence],[EvidenceLimit],[RecommendedNextCheck])
    SELECT [s].[DatabaseName],CASE WHEN COALESCE([j].[IsContinuous],1)=1 THEN 'WARN' ELSE 'INFO' END,
           CASE WHEN COALESCE([j].[IsContinuous],1)=1 THEN 'MEDIUM' ELSE 'LOW' END,
           CASE WHEN COALESCE([j].[IsContinuous],1)=1 THEN 'CDC_CAPTURE_LATENCY_HIGH' ELSE 'CDC_SCHEDULED_CAPTURE_LATENCY_CONTEXT' END,
           'LATENCY_SECONDS',[s].[LatencySeconds],@CdcLatencyWarnSeconds,
           N'Die aggregierte CDC-Scan-Latenz ueberschreitet den konfigurierten Grenzwert.',[s].[EvidenceLimit],
           N'Wiederholt messen und Capture-Modus, Polling, Logaktivitaet, Agentstatus sowie Ressourcen korrelieren.'
    FROM [#DataCaptureDeepAnalysis_CdcScanSession] [s]
    OUTER APPLY
    (
        SELECT TOP(1) [IsContinuous] FROM [#DataCaptureDeepAnalysis_CdcJob]
        WHERE [DatabaseName]=[s].[DatabaseName] AND [JobType]=N'capture'
    ) [j]
    WHERE [s].[SessionId]=0 AND [s].[LatencySeconds]>=@CdcLatencyWarnSeconds;

    INSERT [#DataCaptureDeepAnalysis_Findings]
    ([DatabaseName],[Severity],[Confidence],[FindingCode],[MetricName],[MetricValue],[ThresholdValue],
     [Evidence],[EvidenceLimit],[RecommendedNextCheck])
    SELECT [DatabaseName],'WARN','MEDIUM','CDC_SCAN_FAILURES_VISIBLE','FAILED_SESSION_COUNT',
           [FailedSessionsCount],0,N'Die aggregierte CDC-Scan-DMV meldet fehlgeschlagene Sitzungen.',[EvidenceLimit],
           N'Neueste CDC-Fehlergruppe, Agentjobausgang und freigegebene Laufzeitlogs korrelieren; DMV-Resetgrenze beachten.'
    FROM [#DataCaptureDeepAnalysis_CdcScanSession]
    WHERE [SessionId]=0 AND COALESCE([FailedSessionsCount],0)>0;

    INSERT [#DataCaptureDeepAnalysis_Findings]
    ([DatabaseName],[Severity],[Confidence],[FindingCode],[MetricName],[MetricValue],[ThresholdValue],
     [Evidence],[EvidenceLimit],[RecommendedNextCheck])
    SELECT [DatabaseName],'WARN','HIGH','CDC_ERRORS_IN_LOOKBACK','ERROR_COUNT',SUM([ErrorCount]),0,
           N'Die CDC-Fehler-DMV enthaelt Fehler im konfigurierten Rueckblick.',MIN([EvidenceLimit]),
           N'Fehlernummern und Phasen mit Agentstatus und geschuetzten Laufzeitlogs korrelieren; keine Fehlermeldung in Repositoryartefakte kopieren.'
    FROM [#DataCaptureDeepAnalysis_CdcErrorGroup]
    GROUP BY [DatabaseName];

    INSERT [#DataCaptureDeepAnalysis_Findings]
    ([DatabaseName],[SchemaName],[ObjectName],[Severity],[Confidence],[FindingCode],[MetricName],[MetricValue],[ThresholdValue],
     [Evidence],[EvidenceLimit],[RecommendedNextCheck])
    SELECT [DatabaseName],[SourceSchema],COALESCE([SourceTable],[CaptureInstance]),'WARN','LOW','CDC_OLDEST_AVAILABLE_EXCEEDS_RETENTION','OLDEST_AVAILABLE_AGE_MINUTES',
           [OldestAvailableAgeMinutes],[CleanupRetentionMinutes]+@CdcCleanupGraceMinutes,
           N'Die aelteste verfuegbare CDC-Zeitgrenze liegt jenseits von Retention plus Toleranz.',[EvidenceLimit],
           N'Cleanup-Jobverlauf, Logaktivitaet und wiederholte LSN-Zeitgrenzen pruefen; keine automatische Loeschung ausfuehren.'
    FROM [#DataCaptureDeepAnalysis_CdcCaptureInstance]
    WHERE [CleanupRetentionMinutes] IS NOT NULL AND [OldestAvailableAgeMinutes]>[CleanupRetentionMinutes]+@CdcCleanupGraceMinutes;

    INSERT [#DataCaptureDeepAnalysis_Findings]
    ([DatabaseName],[Severity],[Confidence],[FindingCode],[MetricName],[MetricValue],[ThresholdValue],
     [Evidence],[EvidenceLimit],[RecommendedNextCheck])
    SELECT [DatabaseName],'WARN','HIGH','REPLICATION_TOPOLOGY_NOT_LOCALLY_OBSERVABLE','LOCAL_DISTRIBUTOR_VISIBLE',0,1,
           N'Die Datenbank besitzt eine sichtbare Replikationsrolle, aber keine lokale Distribution-Datenbank ist erreichbar.',
           N'Ein Remote Distributor oder fehlende Rechte verhindern lokale Agent-, Rueckstands- und Fehleraussagen; dies ist kein Gesundheitsnachweis.',
           N'Diagnose am Distributor mit freigegebenem Zugriff ausfuehren und die Evidenz ausschliesslich in der Laufzeitumgebung korrelieren.'
    FROM [#DataCaptureDeepAnalysis_FeatureScope]
    WHERE ([IsPublished]=1 OR [IsSubscribed]=1 OR [IsMergePublished]=1 OR [IsDistributor]=1)
      AND NOT EXISTS(SELECT 1 FROM [#DataCaptureDeepAnalysis_DistributionDatabase]);

    INSERT [#DataCaptureDeepAnalysis_Findings]
    ([DatabaseName],[ObjectName],[Severity],[Confidence],[FindingCode],[MetricName],[MetricValue],[ThresholdValue],
     [Evidence],[EvidenceLimit],[RecommendedNextCheck])
    SELECT [PublisherDatabase],[PublicationName],'WARN','HIGH','REPLICATION_PENDING_COMMANDS_HIGH','PENDING_COMMAND_COUNT',
           [PendingCommandCount],@ReplicationPendingCommandWarn,
           N'Der lokale Distributor meldet einen Rueckstand oberhalb des konfigurierten Grenzwerts.',[EvidenceLimit],
           N'Rueckstand und Delivery-Rate wiederholt messen sowie Agentstatus, Subscriber-Erreichbarkeit und Ressourcen korrelieren.'
    FROM [#DataCaptureDeepAnalysis_ReplicationAgent]
    WHERE [AgentType]='DISTRIBUTION' AND [PendingCommandCount]>=@ReplicationPendingCommandWarn;

    INSERT [#DataCaptureDeepAnalysis_Findings]
    ([DatabaseName],[ObjectName],[Severity],[Confidence],[FindingCode],[MetricName],[MetricValue],[ThresholdValue],
     [Evidence],[EvidenceLimit],[RecommendedNextCheck])
    SELECT [PublisherDatabase],[PublicationName],'WARN','MEDIUM','REPLICATION_AGENT_FAILED_OR_RETRYING','RUN_STATUS',
           [RunStatus],4,N'Der neueste lokale Agent-Historienstatus ist Retry oder Fail.',[EvidenceLimit],
           N'Neueste Fehlercodes, Jobausgang und geschuetzte Laufzeitlogs korrelieren; ein einzelner Status beweist keine dauerhafte Stoerung.'
    FROM [#DataCaptureDeepAnalysis_ReplicationAgent]
    WHERE [RunStatus] IN(5,6);

    INSERT [#DataCaptureDeepAnalysis_Findings]
    ([DatabaseName],[ObjectName],[Severity],[Confidence],[FindingCode],[MetricName],[MetricValue],[ThresholdValue],
     [Evidence],[EvidenceLimit],[RecommendedNextCheck])
    SELECT [PublisherDatabase],[PublicationName],'WARN','MEDIUM','REPLICATION_DELIVERY_LATENCY_HIGH','DELIVERY_LATENCY_SECONDS',
           CONVERT(decimal(38,4),[DeliveryLatencyMs])/1000.0,@ReplicationLatencyWarnSeconds,
           N'Die lokale Agenthistorie meldet eine Delivery-Latenz oberhalb des konfigurierten Grenzwerts.',[EvidenceLimit],
           N'Mehrere Messpunkte und den passenden Agenttyp mit Rueckstand, Delivery-Rate, Netzwerk und Subscriber-Ressourcen korrelieren.'
    FROM [#DataCaptureDeepAnalysis_ReplicationAgent]
    WHERE CONVERT(decimal(38,4),[DeliveryLatencyMs])/1000.0>=@ReplicationLatencyWarnSeconds;

    INSERT [#DataCaptureDeepAnalysis_Findings]
    ([DatabaseName],[ObjectName],[Severity],[Confidence],[FindingCode],[MetricName],[MetricValue],[ThresholdValue],
     [Evidence],[EvidenceLimit],[RecommendedNextCheck])
    SELECT [PublisherDatabase],[PublicationName],'WARN','MEDIUM','REPLICATION_INACTIVE_SUBSCRIPTION_REVIEW','INACTIVE_SUBSCRIPTION_COUNT',
           [InactiveSubscriptionCount],0,
           N'Mindestens eine lokale Subscription-Zeile des Distribution Agents ist nicht aktiv.',[EvidenceLimit],
           N'Initialisierung, Subscription-Status und Agentfehler pruefen; dieser Indikator allein beweist keine erforderliche Reinitialisierung.'
    FROM [#DataCaptureDeepAnalysis_ReplicationAgent]
    WHERE COALESCE([InactiveSubscriptionCount],0)>0;

    INSERT [#DataCaptureDeepAnalysis_Findings]
    ([DatabaseName],[ObjectName],[Severity],[Confidence],[FindingCode],[MetricName],[MetricValue],[ThresholdValue],
     [Evidence],[EvidenceLimit],[RecommendedNextCheck])
    SELECT [PublisherDatabase],[PublicationName],'WARN','LOW','REPLICATION_AGENT_STALE_WITH_BACKLOG','LAST_HISTORY_AGE_MINUTES',
           [LastHistoryAgeMinutes],@ReplicationAgentStaleWarnMinutes,
           N'Die letzte Agenthistorie ist alt und zugleich ist ein lokaler Rueckstand sichtbar.',[EvidenceLimit],
           N'Agentjob und neue Historienzeilen pruefen. Idle oder seltene Zeitplaene ohne Rueckstand sind ausdruecklich kein Fehler.'
    FROM [#DataCaptureDeepAnalysis_ReplicationAgent]
    WHERE [AgentType]='DISTRIBUTION' AND [LastHistoryAgeMinutes]>=@ReplicationAgentStaleWarnMinutes
      AND COALESCE([PendingCommandCount],0)>0;

    INSERT [#DataCaptureDeepAnalysis_Findings]
    ([DatabaseName],[ObjectName],[Severity],[Confidence],[FindingCode],[MetricName],[MetricValue],[ThresholdValue],
     [Evidence],[EvidenceLimit],[RecommendedNextCheck])
    SELECT [PublisherDatabase],[PublicationName],'WARN','MEDIUM','MERGE_CONFLICT_OR_RETRY_VISIBLE','CONFLICT_AND_RETRY_COUNT',
           COALESCE([ConflictCount],0)+COALESCE([RetryCount],0),0,
           N'Die neueste lokale Merge-Session meldet Konflikte oder Retries.',[EvidenceLimit],
           N'Publication-Regeln, Resolver und freigegebene Laufzeitevidenz pruefen; keine Konfliktzeilen in Repositoryartefakte uebernehmen.'
    FROM [#DataCaptureDeepAnalysis_ReplicationAgent]
    WHERE [AgentType]='MERGE' AND COALESCE([ConflictCount],0)+COALESCE([RetryCount],0)>0;

    INSERT [#DataCaptureDeepAnalysis_Findings]
    ([Severity],[Confidence],[FindingCode],[MetricName],[MetricValue],[ThresholdValue],
     [Evidence],[EvidenceLimit],[RecommendedNextCheck])
    SELECT 'WARN','HIGH','REPLICATION_ERRORS_IN_LOOKBACK','ERROR_COUNT',SUM([ErrorCount]),0,
           N'Die lokale Distribution-Datenbank enthaelt Replikationsfehler im konfigurierten Rueckblick.',MIN([EvidenceLimit]),
           N'Fehlercodes mit Agenten und geschuetzten Laufzeitlogs korrelieren; Fehlertexte oder Commands nicht persistieren.'
    FROM [#DataCaptureDeepAnalysis_ReplicationErrorGroup]
    HAVING SUM([ErrorCount])>0;

    INSERT [#DataCaptureDeepAnalysis_Findings]
    ([DatabaseName],[Severity],[Confidence],[FindingCode],[MetricName],[Evidence],[EvidenceLimit],[RecommendedNextCheck])
    SELECT [DatabaseName],'WARN','HIGH','DATA_CAPTURE_EVIDENCE_GAP',[SourceCode],
           COALESCE([ErrorMessage],N'Die angeforderte Quelle ist nicht verfuegbar.'),[Detail],
           N'Berechtigung, Featureverfuegbarkeit und Topologie pruefen; andere Resultsets bleiben gueltig.'
    FROM [#DataCaptureDeepAnalysis_SourceStatus]
    WHERE [IsPartial]=1 AND [DatabaseName] IS NOT NULL;

    INSERT [#DataCaptureDeepAnalysis_Findings]
    ([Severity],[Confidence],[FindingCode],[MetricName],[Evidence],[EvidenceLimit],[RecommendedNextCheck])
    SELECT 'WARN','HIGH','REPLICATION_EVIDENCE_GAP',[SourceCode],
           COALESCE([ErrorMessage],N'Die lokale Replikationsquelle ist nicht verfuegbar.'),[Detail],
           N'Berechtigung und Distributor-Topologie pruefen; eine Quellenluecke niemals als gesunden Zustand behandeln.'
    FROM [#DataCaptureDeepAnalysis_SourceStatus]
    WHERE [IsPartial]=1 AND [DatabaseName] IS NULL;

    UPDATE [x]
    SET [AssessmentStatus]=CASE WHEN EXISTS
        (SELECT 1 FROM [#DataCaptureDeepAnalysis_Findings] [f]
         WHERE [f].[DatabaseName]=[x].[DatabaseName]
           AND [f].[SchemaName]=[x].[SchemaName]
           AND [f].[ObjectName]=[x].[TableName]
           AND [f].[Severity]='WARN') THEN 'REVIEW' ELSE 'AVAILABLE' END
    FROM [#DataCaptureDeepAnalysis_ChangeTrackingTable] [x];

    UPDATE [x]
    SET [AssessmentStatus]=CASE WHEN EXISTS
        (SELECT 1 FROM [#DataCaptureDeepAnalysis_Findings] [f]
         WHERE [f].[DatabaseName]=[x].[DatabaseName]
           AND ([f].[ObjectName]=[x].[SourceTable] OR [f].[ObjectName]=[x].[CaptureInstance])
           AND [f].[Severity]='WARN') THEN 'REVIEW' ELSE 'AVAILABLE' END
    FROM [#DataCaptureDeepAnalysis_CdcCaptureInstance] [x];

    UPDATE [x]
    SET [AssessmentStatus]=CASE WHEN EXISTS
        (SELECT 1 FROM [#DataCaptureDeepAnalysis_Findings] [f]
         WHERE ([f].[DatabaseName]=[x].[PublisherDatabase] OR [f].[DatabaseName] IS NULL)
           AND ([f].[ObjectName]=[x].[PublicationName] OR [f].[ObjectName] IS NULL)
           AND [f].[Severity]='WARN') THEN 'REVIEW' ELSE 'AVAILABLE' END
    FROM [#DataCaptureDeepAnalysis_ReplicationAgent] [x];

    UPDATE [ds]
    SET [SourceFailureCount]=[x].[FailureCount]+CASE WHEN [ds].[HasReplicationRole]=1 THEN [g].[GlobalFailureCount] ELSE 0 END,
        [IsPartial]=CONVERT(bit,CASE WHEN [x].[FailureCount]+CASE WHEN [ds].[HasReplicationRole]=1 THEN [g].[GlobalFailureCount] ELSE 0 END>0 THEN 1 ELSE 0 END),
        [ErrorNumber]=COALESCE([ds].[ErrorNumber],[x].[ErrorNumber],CASE WHEN [ds].[HasReplicationRole]=1 THEN [g].[ErrorNumber] END),
        [ErrorMessage]=COALESCE([ds].[ErrorMessage],[x].[ErrorMessage],CASE WHEN [ds].[HasReplicationRole]=1 THEN [g].[ErrorMessage] END),
        [FindingCount]=[f].[FindingCount],
        [StatusCode]=CASE WHEN [ds].[StatusCode] IN('UNAVAILABLE_FEATURE','ERROR_HANDLED') THEN [ds].[StatusCode]
                          WHEN COALESCE([ds].[IsChangeTrackingEnabled],0)=0 AND COALESCE([ds].[IsCdcEnabled],0)=0 AND COALESCE([ds].[HasReplicationRole],0)=0 THEN 'NOT_APPLICABLE_VISIBLE_SCOPE'
                          WHEN [x].[FailureCount]+CASE WHEN [ds].[HasReplicationRole]=1 THEN [g].[GlobalFailureCount] ELSE 0 END>0 THEN 'AVAILABLE_LIMITED'
                          WHEN [f].[WarnCount]>0 THEN 'AVAILABLE_WITH_FINDING'
                          ELSE 'AVAILABLE' END,
        [Detail]=CASE WHEN COALESCE([ds].[IsChangeTrackingEnabled],0)=0 AND COALESCE([ds].[IsCdcEnabled],0)=0 AND COALESCE([ds].[HasReplicationRole],0)=0
                          THEN N'Keine der drei Funktionen im sichtbaren Scope erkannt; eingeschraenkte Metadatensichtbarkeit kann Abwesenheit nicht beweisen.'
                      WHEN [x].[FailureCount]+CASE WHEN [ds].[HasReplicationRole]=1 THEN [g].[GlobalFailureCount] ELSE 0 END>0
                          THEN N'Mindestens eine isolierte Quelle fehlt; zugaengliche Teilergebnisse bleiben erhalten.'
                      WHEN [f].[WarnCount]>0
                          THEN N'Mindestens ein Pruefhinweis liegt vor; kein automatisches Gesundheitsurteil.'
                      ELSE N'Kein konfigurierter Warnindikator in der zugaenglichen Momentaufnahme; dies beweist keine fehlerfreie Verarbeitung.' END
    FROM [#DataCaptureDeepAnalysis_DatabaseStatus] [ds]
    OUTER APPLY
    (
        SELECT CONVERT(int,COUNT_BIG(*)) AS [FailureCount],MIN([ss].[ErrorNumber]) AS [ErrorNumber],MIN([ss].[ErrorMessage]) AS [ErrorMessage]
        FROM [#DataCaptureDeepAnalysis_SourceStatus] [ss]
        WHERE [ss].[DatabaseName]=[ds].[DatabaseName] AND [ss].[IsPartial]=1
    ) [x]
    CROSS APPLY
    (
        SELECT CONVERT(int,COUNT_BIG(*)) AS [GlobalFailureCount],MIN([ss].[ErrorNumber]) AS [ErrorNumber],MIN([ss].[ErrorMessage]) AS [ErrorMessage]
        FROM [#DataCaptureDeepAnalysis_SourceStatus] [ss]
        WHERE [ss].[DatabaseName] IS NULL AND [ss].[IsPartial]=1
    ) [g]
    OUTER APPLY
    (
        SELECT COUNT_BIG(*) AS [FindingCount],
               COALESCE(SUM(CASE WHEN [ff].[Severity]='WARN' THEN CONVERT(bigint,1) ELSE CONVERT(bigint,0) END),0) AS [WarnCount]
        FROM [#DataCaptureDeepAnalysis_Findings] [ff]
        WHERE [ff].[DatabaseName]=[ds].[DatabaseName]
           OR ([ff].[DatabaseName] IS NULL AND [ds].[HasReplicationRole]=1)
    ) [f];

    IF @StatusCode='AVAILABLE'
    BEGIN
        IF EXISTS(SELECT 1 FROM [#DataCaptureDeepAnalysis_DatabaseStatus] WHERE [IsPartial]=1)
            SELECT @StatusCode='AVAILABLE_LIMITED',@IsPartial=1;
        ELSE IF EXISTS(SELECT 1 FROM [#DataCaptureDeepAnalysis_Findings] WHERE [Severity]='WARN')
            SET @StatusCode='AVAILABLE_WITH_FINDING';
        ELSE IF NOT EXISTS
            (SELECT 1 FROM [#DataCaptureDeepAnalysis_FeatureScope]
             WHERE [IsChangeTrackingEnabled]=1 OR [IsCdcEnabled]=1 OR [IsPublished]=1
                OR [IsSubscribed]=1 OR [IsMergePublished]=1 OR [IsDistributor]=1)
            SET @StatusCode='NOT_APPLICABLE';
    END;

    SELECT @ErrorNumber=COALESCE(@ErrorNumber,MIN([ErrorNumber])),
           @ErrorMessage=COALESCE(@ErrorMessage,MIN([ErrorMessage]))
    FROM [#DataCaptureDeepAnalysis_SourceStatus]
    WHERE [IsPartial]=1;

    IF @JsonErzeugen=1
    BEGIN
        SELECT @Json=(
            SELECT
                JSON_QUERY((SELECT N'USP_DataCaptureDeepAnalysis' AS [module],@Now AS [collectedAtUtc],@StatusCode AS [statusCode],@IsPartial AS [isPartial],@ErrorNumber AS [errorNumber],@ErrorMessage AS [errorMessage] FOR JSON PATH,WITHOUT_ARRAY_WRAPPER)) AS [meta],
                JSON_QUERY(COALESCE((SELECT * FROM [#DataCaptureDeepAnalysis_DatabaseStatus] ORDER BY [DatabaseName] FOR JSON PATH),N'[]')) AS [databaseStatus],
                JSON_QUERY(COALESCE((SELECT * FROM [#DataCaptureDeepAnalysis_SourceStatus] ORDER BY [DatabaseName],[SourceCode] FOR JSON PATH),N'[]')) AS [sourceStatus],
                JSON_QUERY(COALESCE((SELECT TOP(@Limit) * FROM [#DataCaptureDeepAnalysis_Findings] WHERE @NurProblematisch=0 OR [Severity]='WARN' ORDER BY CASE [Severity] WHEN 'WARN' THEN 1 ELSE 2 END,[FindingOrdinal] FOR JSON PATH),N'[]')) AS [findings],
                JSON_QUERY(COALESCE((SELECT TOP(@Limit) * FROM [#DataCaptureDeepAnalysis_ChangeTrackingTable] WHERE @NurProblematisch=0 OR [AssessmentStatus]='REVIEW' ORDER BY CASE [AssessmentStatus] WHEN 'REVIEW' THEN 1 ELSE 2 END,[DatabaseName],[SchemaName],[TableName] FOR JSON PATH),N'[]')) AS [changeTrackingTables],
                JSON_QUERY(COALESCE((SELECT TOP(@Limit) * FROM [#DataCaptureDeepAnalysis_CdcCaptureInstance] WHERE @NurProblematisch=0 OR [AssessmentStatus]='REVIEW' ORDER BY CASE [AssessmentStatus] WHEN 'REVIEW' THEN 1 ELSE 2 END,[DatabaseName],[CaptureInstance] FOR JSON PATH),N'[]')) AS [cdcCaptureInstances],
                JSON_QUERY(COALESCE((SELECT TOP(@Limit) * FROM [#DataCaptureDeepAnalysis_CdcScanSession] ORDER BY [DatabaseName],[SessionId] FOR JSON PATH),N'[]')) AS [cdcScanSessions],
                JSON_QUERY(COALESCE((SELECT TOP(@Limit) * FROM [#DataCaptureDeepAnalysis_CdcErrorGroup] ORDER BY [LastErrorTimeUtc] DESC,[DatabaseName],[ErrorNumber] FOR JSON PATH),N'[]')) AS [cdcErrors],
                JSON_QUERY(COALESCE((SELECT TOP(@Limit) * FROM [#DataCaptureDeepAnalysis_CdcJob] ORDER BY [DatabaseName],[JobType] FOR JSON PATH),N'[]')) AS [cdcJobs],
                JSON_QUERY(COALESCE((SELECT TOP(@Limit) * FROM [#DataCaptureDeepAnalysis_ReplicationAgent] WHERE @NurProblematisch=0 OR [AssessmentStatus]='REVIEW' ORDER BY CASE [AssessmentStatus] WHEN 'REVIEW' THEN 1 ELSE 2 END,[DistributionDatabase],[AgentType],[PublisherDatabase],[PublicationName],[AgentId] FOR JSON PATH),N'[]')) AS [replicationAgents],
                JSON_QUERY(COALESCE((SELECT TOP(@Limit) * FROM [#DataCaptureDeepAnalysis_ReplicationErrorGroup] ORDER BY [LastErrorTimeUtc] DESC,[DistributionDatabase],[ErrorCode] FOR JSON PATH),N'[]')) AS [replicationErrors]
            FOR JSON PATH,WITHOUT_ARRAY_WRAPPER);
    END;

    IF @OutputMode<>'NONE'
    BEGIN
        SELECT N'USP_DataCaptureDeepAnalysis' AS [Module],@Now AS [CollectedAtUtc],@StatusCode AS [StatusCode],
               @IsPartial AS [IsPartial],@ErrorNumber AS [ErrorNumber],@ErrorMessage AS [ErrorMessage],
               N'Read-only Metadatenaufnahme; keine Change-Zeilen, Replikationsbefehle, Credentials, Agent-Commands oder Aenderungen.' AS [Detail];
        SELECT * FROM [#DataCaptureDeepAnalysis_DatabaseStatus] ORDER BY [DatabaseName];
        SELECT * FROM [#DataCaptureDeepAnalysis_SourceStatus] ORDER BY [DatabaseName],[SourceCode];
        SELECT TOP(@Limit) * FROM [#DataCaptureDeepAnalysis_Findings]
        WHERE @NurProblematisch=0 OR [Severity]='WARN'
        ORDER BY CASE [Severity] WHEN 'WARN' THEN 1 ELSE 2 END,[FindingOrdinal];
        SELECT TOP(@Limit) * FROM [#DataCaptureDeepAnalysis_ChangeTrackingTable]
        WHERE @NurProblematisch=0 OR [AssessmentStatus]='REVIEW'
        ORDER BY CASE [AssessmentStatus] WHEN 'REVIEW' THEN 1 ELSE 2 END,[DatabaseName],[SchemaName],[TableName];
        SELECT TOP(@Limit) * FROM [#DataCaptureDeepAnalysis_CdcCaptureInstance]
        WHERE @NurProblematisch=0 OR [AssessmentStatus]='REVIEW'
        ORDER BY CASE [AssessmentStatus] WHEN 'REVIEW' THEN 1 ELSE 2 END,[DatabaseName],[CaptureInstance];
        SELECT TOP(@Limit) * FROM [#DataCaptureDeepAnalysis_CdcScanSession] ORDER BY [DatabaseName],[SessionId];
        SELECT TOP(@Limit) * FROM [#DataCaptureDeepAnalysis_CdcErrorGroup] ORDER BY [LastErrorTimeUtc] DESC,[DatabaseName],[ErrorNumber];
        SELECT TOP(@Limit) * FROM [#DataCaptureDeepAnalysis_CdcJob] ORDER BY [DatabaseName],[JobType];
        SELECT TOP(@Limit) * FROM [#DataCaptureDeepAnalysis_ReplicationAgent]
        WHERE @NurProblematisch=0 OR [AssessmentStatus]='REVIEW'
        ORDER BY CASE [AssessmentStatus] WHEN 'REVIEW' THEN 1 ELSE 2 END,[DistributionDatabase],[AgentType],[PublisherDatabase],[PublicationName],[AgentId];
        SELECT TOP(@Limit) * FROM [#DataCaptureDeepAnalysis_ReplicationErrorGroup] ORDER BY [LastErrorTimeUtc] DESC,[DistributionDatabase],[ErrorCode];
    END;

    IF @PrintMeldungen=1 AND @StatusCode NOT IN('AVAILABLE','NOT_APPLICABLE')
    BEGIN
        SET @PrintMessage=LEFT(CONCAT(N'USP_DataCaptureDeepAnalysis: ',@StatusCode,N'. ',COALESCE(@ErrorMessage,N'Siehe strukturierte Quellenstatus.')),2048);
        RAISERROR(N'%s',10,1,@PrintMessage) WITH NOWAIT;
    END;

    SELECT @StatusCodeOut=@StatusCode,@IsPartialOut=@IsPartial,
           @ErrorNumberOut=@ErrorNumber,@ErrorMessageOut=@ErrorMessage;
    IF @ConsoleResultRequested = 1
    BEGIN
        EXEC [monitor].[InternalEmitConsoleResult]
              @SourceTable=N'#DataCaptureDeepAnalysis_Findings'
            , @ResultLabel=N'DataCaptureDeepAnalysis'
            , @EmptyMessage=N'Keine fachlichen Ergebnisse';
    END;
    IF @TableResultRequested = 1
    BEGIN
        EXEC [monitor].[InternalWriteResultTable]
              @SourceTable = N'#DataCaptureDeepAnalysis_Findings'
            , @TargetTable=@TableTarget
            , @ThrowOnError = 1;
    END;
END;
GO
-- END SOURCE: Code/09_VersionAdaptive/070_USP_DataCaptureDeepAnalysis.sql

-- BEGIN SOURCE: Code/09_VersionAdaptive/080_USP_EncryptionAnalysis.sql
/*
===============================================================================
Objekt       : monitor.USP_EncryptionAnalysis
Version      : 1.0.0
Stand        : 2026-07-18
Zweck        : Bewertet den sichtbaren Lebenszyklus von TDE, Schutzertifikaten,
               expliziter Backupverschluesselung, Always Encrypted und Ledger.
Methodik     : Read-only Metadatenanalyse mit je Quelle isolierter Fehlergrenze.
Datenschutz  : Liest keine Schluesselpfade, Thumbprints, verschluesselten Werte,
               Backupmedien, SQL-Texte, Konten oder privaten Schluessel.
Grenzen      : Metadaten und lokale Zertifikat-Backuphistorie beweisen weder den
               Besitz externer Schluesselkopien noch die Wiederherstellbarkeit.
===============================================================================
*/
CREATE OR ALTER PROCEDURE [monitor].[USP_EncryptionAnalysis]
      @DatabaseNames                              nvarchar(max)  = NULL
    , @SystemdatenbankenEinbeziehen               bit            = 0
    , @DatabaseNamePattern                        nvarchar(4000) = NULL
    , @HighImpactConfirmed              bit            = 0
    , @NurProblematisch                           bit            = 0
    , @TdeTransitionWarnMinutes                   int            = 60
    , @CertificateExpiryWarnDays                  int            = 90
    , @ExpliziteBackupverschluesselungErwartet    bit            = 0
    , @BackupLookbackDays                         int            = 35
    , @MaxZeilen                                  int            = 1000
    , @LockTimeoutMs                              int            = 0
    , @ResultSetArt                               varchar(16)    = 'CONSOLE'
    , @ResultTablesJson               nvarchar(max) = NULL
    , @JsonErzeugen                               bit            = 0
    , @Json                                       nvarchar(max)  = NULL OUTPUT
    , @PrintMeldungen                             bit            = 1
    , @Hilfe                                      bit            = 0
    , @StatusCodeOut                              varchar(40)    = NULL OUTPUT
    , @IsPartialOut                               bit            = NULL OUTPUT
    , @ErrorNumberOut                             int            = NULL OUTPUT
    , @ErrorMessageOut                            nvarchar(2048) = NULL OUTPUT
AS
BEGIN
    SET NOCOUNT ON;
    SET @Json = NULL;

    DECLARE @Now datetime2(3)=SYSUTCDATETIME();
    DECLARE @OutputMode varchar(16)=UPPER(LTRIM(RTRIM(COALESCE(@ResultSetArt,''))));
    DECLARE @TableResultRequested bit = CASE WHEN @OutputMode = 'TABLE' THEN 1 ELSE 0 END;
    DECLARE @ConsoleResultRequested bit = CASE WHEN @OutputMode = 'CONSOLE' THEN 1 ELSE 0 END;
    DECLARE @TableTarget sysname=NULL;
    IF @TableResultRequested=0 AND NULLIF(LTRIM(RTRIM(COALESCE(@ResultTablesJson,N''))),N'') IS NOT NULL THROW 51011,N'@ResultTablesJson ist ausschließlich mit @ResultSetArt=TABLE zulässig.',1;
    IF @TableResultRequested=1 EXEC [monitor].[InternalPrepareSingleResultTable] @ResultTablesJson=@ResultTablesJson,@ResultName=N'databases',@TargetTable=@TableTarget OUTPUT,@ThrowOnError=1;
    IF @TableResultRequested = 1 OR @ConsoleResultRequested = 1 SET @OutputMode = 'NONE';
    DECLARE @Limit bigint=CASE WHEN @MaxZeilen IS NULL OR @MaxZeilen=0
                               THEN CONVERT(bigint,9223372036854775807)
                               ELSE CONVERT(bigint,@MaxZeilen) END;
    DECLARE @Major int=TRY_CONVERT(int,SERVERPROPERTY('ProductMajorVersion'));
    DECLARE @StatusCode varchar(40)='AVAILABLE';
    DECLARE @IsPartial bit=0;
    DECLARE @ErrorNumber int=NULL;
    DECLARE @ErrorMessage nvarchar(2048)=NULL;
    DECLARE @CrossDatabaseRequested bit=0;

    IF @Hilfe=1
    BEGIN
        PRINT N'monitor.USP_EncryptionAnalysis';
        PRINT N'Bewertet TDE, Zertifikatlebenszyklus, explizite Backupverschluesselung sowie aggregierte Always-Encrypted- und Ledger-Metadaten.';
        PRINT N'Es werden keine Schlüsselpfade, Thumbprints, verschlüsselten Werte, Backupmedien, Konten oder privaten Schlüssel gelesen.';
        PRINT N'Ein Zertifikat ohne lokale Backuphistorie ist nur ein Hinweis; ein externer Export kann trotzdem existieren.';
        RETURN;
    END;

    CREATE TABLE [#EncryptionAnalysis_DatabaseCandidates]
    (
          [DatabaseId] int NOT NULL PRIMARY KEY
        , [DatabaseName] sysname NOT NULL
        , [StateDesc] nvarchar(60) NULL
        , [UserAccessDesc] nvarchar(60) NULL
        , [IsReadOnly] bit NULL
        , [CompatibilityLevel] tinyint NULL
        , [CollationName] sysname NULL
        , [RecoveryModelDesc] nvarchar(60) NULL
        , [IsSystemDatabase] bit NULL
        , [RequestedOrdinal] int NULL
    );
    CREATE TABLE [#EncryptionAnalysis_DatabaseCandidateWarnings]
    (
          [RequestedName] sysname NULL
        , [StatusCode] varchar(40) NOT NULL
        , [ErrorMessage] nvarchar(2048) NULL
    );
    CREATE TABLE [#EncryptionAnalysis_SourceStatus]
    (
          [SourceName] nvarchar(128) NOT NULL PRIMARY KEY
        , [StatusCode] varchar(40) NOT NULL
        , [IsPartial] bit NOT NULL
        , [Detail] nvarchar(1000) NOT NULL
    );
    CREATE TABLE [#EncryptionAnalysis_Encryption]
    (
          [DatabaseId] int NOT NULL PRIMARY KEY
        , [DatabaseName] sysname NOT NULL
        , [IsEncrypted] bit NULL
        , [EncryptionState] int NULL
        , [EncryptionStateDesc] nvarchar(60) NULL
        , [PercentComplete] real NULL
        , [EncryptionScanState] int NULL
        , [EncryptionScanStateDesc] nvarchar(60) NULL
        , [EncryptionScanModifyDate] datetime NULL
        , [KeyAlgorithm] nvarchar(32) NULL
        , [KeyLength] int NULL
        , [EncryptorType] nvarchar(32) NULL
        , [ProtectorName] sysname NULL
        , [ProtectorExpiryDate] datetime NULL
        , [ProtectorPrivateKeyLastBackupDate] datetime NULL
        , [LatestFullBackupFinishDate] datetime NULL
        , [LatestFullBackupExplicitlyEncrypted] bit NULL
        , [LatestFullBackupAlgorithm] nvarchar(32) NULL
        , [LatestFullBackupEncryptorType] nvarchar(32) NULL
        , [ColumnMasterKeyCount] bigint NULL
        , [ColumnEncryptionKeyCount] bigint NULL
        , [EncryptedColumnCount] bigint NULL
        , [LedgerTableCount] bigint NULL
        , [FindingCode] varchar(100) NULL
        , [FindingSeverity] varchar(16) NULL
        , [EvidenceLimit] nvarchar(1000) NULL
    );

    IF @MaxZeilen<0 OR @LockTimeoutMs<0
       OR @TdeTransitionWarnMinutes<1 OR @TdeTransitionWarnMinutes>525600
       OR @CertificateExpiryWarnDays<1 OR @CertificateExpiryWarnDays>36500
       OR @BackupLookbackDays<1 OR @BackupLookbackDays>3650
       OR @OutputMode NOT IN ('RAW','CONSOLE','NONE')
    BEGIN
        SELECT @StatusCode='INVALID_PARAMETER',@IsPartial=1,
               @ErrorMessage=N'Ungueltiger Grenzwert, Datenbank-, Zeilen- oder Ausgabeparameter.';
    END;

    IF @StatusCode='AVAILABLE'
    BEGIN
        EXEC [monitor].[USP_PrepareDatabaseCandidates]
              @DatabaseNames=@DatabaseNames
            , @SystemdatenbankenEinbeziehen=@SystemdatenbankenEinbeziehen
            , @DatabaseNamePattern=@DatabaseNamePattern,@HighImpactConfirmed=@HighImpactConfirmed

            , @AnalysisClass=NULL
            , @StatusCode=@StatusCode OUTPUT
            , @ErrorMessage=@ErrorMessage OUTPUT
            , @CrossDatabaseRequested=@CrossDatabaseRequested OUTPUT,@CandidateTable=N'#EncryptionAnalysis_DatabaseCandidates',@WarningTable=N'#EncryptionAnalysis_DatabaseCandidateWarnings';
    END;

    SET LOCK_TIMEOUT 0;

    INSERT [#EncryptionAnalysis_Encryption]([DatabaseId],[DatabaseName],[IsEncrypted],[FindingCode],[FindingSeverity],[EvidenceLimit])
    SELECT [DatabaseId],[DatabaseName],NULL,'SOURCE_PENDING','INFO',
           N'Read-only Metadaten; Schluesselbesitz und Wiederherstellbarkeit werden nicht bewiesen.'
    FROM [#EncryptionAnalysis_DatabaseCandidates];

    IF @StatusCode='AVAILABLE'
    BEGIN
        BEGIN TRY
            UPDATE [e]
            SET [IsEncrypted]=[d].[is_encrypted],
                [EncryptionState]=[k].[encryption_state],
                [EncryptionStateDesc]=CASE [k].[encryption_state]
                    WHEN 0 THEN N'NO_DATABASE_KEY' WHEN 1 THEN N'UNENCRYPTED'
                    WHEN 2 THEN N'ENCRYPTION_IN_PROGRESS' WHEN 3 THEN N'ENCRYPTED'
                    WHEN 4 THEN N'KEY_CHANGE_IN_PROGRESS' WHEN 5 THEN N'DECRYPTION_IN_PROGRESS'
                    WHEN 6 THEN N'PROTECTION_CHANGE_IN_PROGRESS' END,
                [PercentComplete]=[k].[percent_complete],
                [EncryptionScanState]=[k].[encryption_scan_state],
                [EncryptionScanStateDesc]=CASE [k].[encryption_scan_state]
                    WHEN 0 THEN N'NONE' WHEN 1 THEN N'RUNNING' WHEN 2 THEN N'SUSPENDED'
                    WHEN 3 THEN N'ABORTED' WHEN 4 THEN N'COMPLETE' END,
                [EncryptionScanModifyDate]=[k].[encryption_scan_modify_date],
                [KeyAlgorithm]=[k].[key_algorithm],
                [KeyLength]=[k].[key_length],
                [EncryptorType]=[k].[encryptor_type],
                [ProtectorName]=[c].[name],
                [ProtectorExpiryDate]=[c].[expiry_date],
                [ProtectorPrivateKeyLastBackupDate]=[c].[pvt_key_last_backup_date]
            FROM [#EncryptionAnalysis_Encryption] AS [e]
            JOIN [sys].[databases] AS [d] WITH (NOLOCK) ON [d].[database_id]=[e].[DatabaseId]
            LEFT JOIN [sys].[dm_database_encryption_keys] AS [k] WITH (NOLOCK) ON [k].[database_id]=[e].[DatabaseId]
            LEFT JOIN [master].[sys].[certificates] AS [c] WITH (NOLOCK)
              ON [k].[encryptor_type]=N'CERTIFICATE' AND [c].[thumbprint]=[k].[encryptor_thumbprint];

            INSERT [#EncryptionAnalysis_SourceStatus] VALUES
            (N'sys.dm_database_encryption_keys + master.sys.certificates','AVAILABLE',0,
             N'TDE-Zustand und sichtbare Zertifikatmetadaten gelesen; Thumbprints und Schluesselmaterial werden nicht ausgegeben.');
        END TRY
        BEGIN CATCH
            INSERT [#EncryptionAnalysis_SourceStatus] VALUES
            (N'sys.dm_database_encryption_keys + master.sys.certificates',
             CASE WHEN ERROR_NUMBER() IN (229,371,916) THEN 'DENIED_PERMISSION' ELSE 'ERROR_HANDLED' END,1,
             N'TDE- oder Zertifikatmetadaten waren nicht vollstaendig lesbar; die uebrigen Quellen werden weiter ausgewertet.');
            SELECT @IsPartial=1,@ErrorNumber=ERROR_NUMBER(),@ErrorMessage=ERROR_MESSAGE();
        END CATCH;

        BEGIN TRY
            ;WITH [LatestFull] AS
            (
                SELECT [bs].[database_name],[bs].[backup_finish_date],[bs].[key_algorithm],[bs].[encryptor_type],
                       ROW_NUMBER() OVER(PARTITION BY [bs].[database_name]
                                         ORDER BY [bs].[backup_finish_date] DESC,[bs].[backup_set_id] DESC) AS [rn]
                FROM [msdb].[dbo].[backupset] AS [bs] WITH (NOLOCK)
                JOIN [#EncryptionAnalysis_DatabaseCandidates] AS [d]
                  ON [d].[DatabaseName] COLLATE SQL_Latin1_General_CP1_CS_AS
                   = [bs].[database_name] COLLATE SQL_Latin1_General_CP1_CS_AS
                WHERE [bs].[type]='D' AND [bs].[is_copy_only]=0
                  AND [bs].[backup_finish_date]>=DATEADD(DAY,-@BackupLookbackDays,GETDATE())
            )
            UPDATE [e]
            SET [LatestFullBackupFinishDate]=[b].[backup_finish_date],
                [LatestFullBackupExplicitlyEncrypted]=CONVERT(bit,CASE WHEN [b].[key_algorithm] IS NULL THEN 0 ELSE 1 END),
                [LatestFullBackupAlgorithm]=[b].[key_algorithm],
                [LatestFullBackupEncryptorType]=[b].[encryptor_type]
            FROM [#EncryptionAnalysis_Encryption] AS [e]
            JOIN [LatestFull] AS [b]
              ON [b].[rn]=1
             AND [b].[database_name] COLLATE SQL_Latin1_General_CP1_CS_AS
               = [e].[DatabaseName] COLLATE SQL_Latin1_General_CP1_CS_AS;

            INSERT [#EncryptionAnalysis_SourceStatus] VALUES
            (N'msdb.dbo.backupset','AVAILABLE',0,
             N'Nur Zeitpunkt und Verschluesselungsart des letzten Full-Backups im Sichtfenster; keine Medien-, Konto- oder Serverdaten.');
        END TRY
        BEGIN CATCH
            INSERT [#EncryptionAnalysis_SourceStatus] VALUES
            (N'msdb.dbo.backupset',CASE WHEN ERROR_NUMBER() IN (229,371,916) THEN 'DENIED_PERMISSION' ELSE 'ERROR_HANDLED' END,1,
             N'Backupverschluesselungsmetadaten waren nicht lesbar; andere Quellen bleiben auswertbar.');
            SELECT @IsPartial=1,@ErrorNumber=ERROR_NUMBER(),@ErrorMessage=ERROR_MESSAGE();
        END CATCH;

        BEGIN TRY
            DECLARE @DatabaseId int,@DatabaseName sysname,@Sql nvarchar(max);
            DECLARE [database_cursor] CURSOR LOCAL FAST_FORWARD FOR
                SELECT [DatabaseId],[DatabaseName] FROM [#EncryptionAnalysis_DatabaseCandidates]
                WHERE [StateDesc]=N'ONLINE' AND [DatabaseId]<>2 ORDER BY [DatabaseId];
            OPEN [database_cursor];
            FETCH NEXT FROM [database_cursor] INTO @DatabaseId,@DatabaseName;
            WHILE @@FETCH_STATUS=0
            BEGIN
                BEGIN TRY
                    SET @Sql=N'SET LOCK_TIMEOUT '+CONVERT(nvarchar(11),@LockTimeoutMs)+N'; UPDATE [e] SET '
                        +N'[ColumnMasterKeyCount]=(SELECT COUNT_BIG(*) FROM '+QUOTENAME(@DatabaseName)+N'.[sys].[column_master_keys] WITH (NOLOCK)),'
                        +N'[ColumnEncryptionKeyCount]=(SELECT COUNT_BIG(*) FROM '+QUOTENAME(@DatabaseName)+N'.[sys].[column_encryption_keys] WITH (NOLOCK)),'
                        +N'[EncryptedColumnCount]=(SELECT COUNT_BIG(*) FROM '+QUOTENAME(@DatabaseName)+N'.[sys].[columns] WITH (NOLOCK) WHERE [encryption_type] IS NOT NULL)'
                        +CASE WHEN @Major>=16 THEN
                          N',[LedgerTableCount]=(SELECT COUNT_BIG(*) FROM '+QUOTENAME(@DatabaseName)+N'.[sys].[tables] WITH (NOLOCK) WHERE [ledger_type]<>0)'
                          ELSE N',[LedgerTableCount]=NULL' END
                        +N' FROM [#EncryptionAnalysis_Encryption] AS [e] WHERE [e].[DatabaseId]=@pDatabaseId;';
                    EXEC [sys].[sp_executesql] @Sql,N'@pDatabaseId int',@pDatabaseId=@DatabaseId;
                END TRY
                BEGIN CATCH
                    SET @IsPartial=1;
                    IF NOT EXISTS(SELECT 1 FROM [#EncryptionAnalysis_DatabaseCandidateWarnings] WHERE [RequestedName]=@DatabaseName)
                        INSERT [#EncryptionAnalysis_DatabaseCandidateWarnings] VALUES
                        (@DatabaseName,CASE WHEN ERROR_NUMBER() IN (229,371,916) THEN 'DENIED_PERMISSION' ELSE 'ERROR_HANDLED' END,
                         N'Aggregierte Always-Encrypted- oder Ledger-Metadaten waren fuer diese Datenbank nicht lesbar.');
                END CATCH;
                FETCH NEXT FROM [database_cursor] INTO @DatabaseId,@DatabaseName;
            END;
            CLOSE [database_cursor];
            DEALLOCATE [database_cursor];

            INSERT [#EncryptionAnalysis_SourceStatus] VALUES
            (N'sys.column_master_keys + sys.column_encryption_keys + sys.columns + sys.tables','AVAILABLE',@IsPartial,
             CASE WHEN @Major>=16 THEN N'Nur aggregierte Objektanzahlen; keine Schluesselpfade, Signaturen, Werte oder Objektnamen.'
                  ELSE N'Nur aggregierte Always-Encrypted-Anzahlen; Ledger ist vor SQL Server 2022 nicht verfuegbar.' END);
        END TRY
        BEGIN CATCH
            IF CURSOR_STATUS('local','database_cursor')>=0 CLOSE [database_cursor];
            IF CURSOR_STATUS('local','database_cursor')>-3 DEALLOCATE [database_cursor];
            INSERT [#EncryptionAnalysis_SourceStatus] VALUES
            (N'sys.column_master_keys + sys.column_encryption_keys + sys.columns + sys.tables','ERROR_HANDLED',1,
             N'Die datenbanklokale Aggregation wurde abgefangen; TDE- und Backupquellen bleiben auswertbar.');
            SELECT @IsPartial=1,@ErrorNumber=ERROR_NUMBER(),@ErrorMessage=ERROR_MESSAGE();
        END CATCH;

        UPDATE [e]
        SET [FindingCode]=CASE
                WHEN [EncryptionScanState]=3 THEN 'TDE_SCAN_ABORTED'
                WHEN [EncryptionScanState]=2 THEN 'TDE_SCAN_SUSPENDED'
                WHEN [EncryptionState] IN (2,4,5,6)
                 AND [EncryptionScanModifyDate]<DATEADD(MINUTE,-@TdeTransitionWarnMinutes,SYSUTCDATETIME())
                    THEN 'TDE_TRANSITION_LONG_RUNNING'
                WHEN [IsEncrypted]=1 AND [EncryptorType]=N'CERTIFICATE' AND [ProtectorName] IS NULL
                    THEN 'TDE_PROTECTOR_NOT_VISIBLE'
                WHEN [IsEncrypted]=1 AND [ProtectorExpiryDate]<DATEADD(DAY,@CertificateExpiryWarnDays,GETDATE())
                    THEN 'TDE_CERTIFICATE_EXPIRY_WINDOW'
                WHEN [IsEncrypted]=1 AND [EncryptorType]=N'CERTIFICATE' AND [ProtectorPrivateKeyLastBackupDate] IS NULL
                    THEN 'LOCAL_CERTIFICATE_EXPORT_EVIDENCE_MISSING'
                WHEN @ExpliziteBackupverschluesselungErwartet=1
                 AND [LatestFullBackupFinishDate] IS NULL THEN 'FULL_BACKUP_EVIDENCE_MISSING'
                WHEN @ExpliziteBackupverschluesselungErwartet=1
                 AND [LatestFullBackupExplicitlyEncrypted]=0 THEN 'EXPLICIT_BACKUP_ENCRYPTION_MISSING'
                WHEN [IsEncrypted]=1 THEN 'TDE_METADATA_CONSISTENT'
                ELSE 'DATABASE_NOT_TDE_ENCRYPTED' END,
            [FindingSeverity]=CASE
                WHEN [EncryptionScanState] IN (2,3) THEN 'HIGH'
                WHEN [EncryptionState] IN (2,4,5,6)
                 AND [EncryptionScanModifyDate]<DATEADD(MINUTE,-@TdeTransitionWarnMinutes,SYSUTCDATETIME()) THEN 'MEDIUM'
                WHEN [IsEncrypted]=1 AND [EncryptorType]=N'CERTIFICATE' AND [ProtectorName] IS NULL THEN 'MEDIUM'
                WHEN [IsEncrypted]=1 AND [ProtectorExpiryDate]<DATEADD(DAY,@CertificateExpiryWarnDays,GETDATE()) THEN 'MEDIUM'
                WHEN @ExpliziteBackupverschluesselungErwartet=1
                 AND ([LatestFullBackupFinishDate] IS NULL OR [LatestFullBackupExplicitlyEncrypted]=0) THEN 'MEDIUM'
                ELSE 'INFO' END,
            [EvidenceLimit]=CASE
                WHEN [IsEncrypted]=1 AND [EncryptorType]=N'CERTIFICATE' AND [ProtectorPrivateKeyLastBackupDate] IS NULL
                    THEN N'Kein lokaler Exportzeitpunkt sichtbar; externe Schluesselkopien koennen dennoch existieren.'
                WHEN @ExpliziteBackupverschluesselungErwartet=1
                    THEN N'TDE und explizite Backupverschluesselung sind getrennte Schutzmechanismen; ein Test-Restore bleibt erforderlich.'
                ELSE N'Read-only Metadaten; Schluesselbesitz und Wiederherstellbarkeit werden nicht bewiesen.' END
        FROM [#EncryptionAnalysis_Encryption] AS [e];

        IF EXISTS(SELECT 1 FROM [#EncryptionAnalysis_SourceStatus] WHERE [IsPartial]=1)
            SELECT @StatusCode='AVAILABLE_LIMITED',@IsPartial=1;
        ELSE IF EXISTS(SELECT 1 FROM [#EncryptionAnalysis_Encryption]
                       WHERE [FindingSeverity] IN ('HIGH','MEDIUM'))
            SET @StatusCode='AVAILABLE_WITH_FINDING';
    END;

    SELECT @StatusCodeOut=@StatusCode,@IsPartialOut=@IsPartial,
           @ErrorNumberOut=@ErrorNumber,@ErrorMessageOut=@ErrorMessage;

    IF @JsonErzeugen=1
    BEGIN
        DECLARE @MetaJson nvarchar(max)=(SELECT N'EncryptionAnalysis' AS [resultName],1 AS [schemaVersion],
            @Now AS [generatedAtUtc],@StatusCode AS [statusCode],@IsPartial AS [isPartial],@Major AS [productMajorVersion]
            FOR JSON PATH,WITHOUT_ARRAY_WRAPPER);
        DECLARE @DataJson nvarchar(max)=(SELECT TOP (@Limit) * FROM [#EncryptionAnalysis_Encryption]
            WHERE @NurProblematisch=0 OR [FindingSeverity] IN ('HIGH','MEDIUM')
            ORDER BY CASE [FindingSeverity] WHEN 'HIGH' THEN 1 WHEN 'MEDIUM' THEN 2 ELSE 3 END,[DatabaseId]
            FOR JSON PATH,INCLUDE_NULL_VALUES);
        DECLARE @SourceJson nvarchar(max)=(SELECT * FROM [#EncryptionAnalysis_SourceStatus] ORDER BY [SourceName]
            FOR JSON PATH,INCLUDE_NULL_VALUES);
        DECLARE @WarningJson nvarchar(max)=(SELECT * FROM [#EncryptionAnalysis_DatabaseCandidateWarnings] ORDER BY [RequestedName]
            FOR JSON PATH,INCLUDE_NULL_VALUES);
        SET @Json=CONCAT(N'{"meta":',COALESCE(@MetaJson,N'{}'),N',"databases":',COALESCE(@DataJson,N'[]'),
                         N',"sources":',COALESCE(@SourceJson,N'[]'),N',"warnings":',COALESCE(@WarningJson,N'[]'),N'}');
    END;

    IF @OutputMode='RAW'
    BEGIN
        SELECT N'USP_EncryptionAnalysis' AS [ModuleName],@Now AS [CollectionTimeUtc],@StatusCode AS [StatusCode],
               @IsPartial AS [IsPartial],@Major AS [ProductMajorVersion],@ErrorNumber AS [ErrorNumber],@ErrorMessage AS [ErrorMessage];
        SELECT TOP (@Limit) * FROM [#EncryptionAnalysis_Encryption]
        WHERE @NurProblematisch=0 OR [FindingSeverity] IN ('HIGH','MEDIUM')
        ORDER BY CASE [FindingSeverity] WHEN 'HIGH' THEN 1 WHEN 'MEDIUM' THEN 2 ELSE 3 END,[DatabaseId];
        SELECT * FROM [#EncryptionAnalysis_SourceStatus] ORDER BY [SourceName];
        SELECT * FROM [#EncryptionAnalysis_DatabaseCandidateWarnings] ORDER BY [RequestedName];
    END
    ELSE IF @OutputMode='CONSOLE'
    BEGIN
        SELECT N'Verschluesselungsanalyse' AS [Ergebnis],@Now AS [Stand_UTC],@StatusCode AS [Status],
               @IsPartial AS [Teilweise],@ErrorMessage AS [Hinweis];
        SELECT TOP (@Limit) N'Verschluesselung' AS [Ergebnis],[DatabaseName] AS [Datenbank],
               [IsEncrypted] AS [TDE_Aktiv],[EncryptionStateDesc] AS [TDE_Status],
               [EncryptionScanStateDesc] AS [Scan_Status],[PercentComplete] AS [Fortschritt_Prozent],
               [ProtectorName] AS [Schutzobjekt],[ProtectorExpiryDate] AS [Ablaufdatum],
               [LatestFullBackupFinishDate] AS [Letztes_Full],
               [LatestFullBackupExplicitlyEncrypted] AS [Full_Explizit_Verschluesselt],
               [ColumnMasterKeyCount] AS [Column_Master_Keys],[ColumnEncryptionKeyCount] AS [Column_Encryption_Keys],
               [EncryptedColumnCount] AS [Verschluesselte_Spalten],[LedgerTableCount] AS [Ledger_Tabellen],
               [FindingCode] AS [Befund],[FindingSeverity] AS [Prioritaet],[EvidenceLimit] AS [Evidenzgrenze]
        FROM [#EncryptionAnalysis_Encryption]
        WHERE @NurProblematisch=0 OR [FindingSeverity] IN ('HIGH','MEDIUM')
        ORDER BY CASE [FindingSeverity] WHEN 'HIGH' THEN 1 WHEN 'MEDIUM' THEN 2 ELSE 3 END,[DatabaseId];
        SELECT N'Quellenstatus' AS [Ergebnis],[SourceName] AS [Quelle],[StatusCode] AS [Status],[Detail] AS [Hinweis]
        FROM [#EncryptionAnalysis_SourceStatus] ORDER BY [SourceName];
        SELECT N'Datenbankwarnung' AS [Ergebnis],[RequestedName] AS [Datenbank],[StatusCode] AS [Status],[ErrorMessage] AS [Meldung]
        FROM [#EncryptionAnalysis_DatabaseCandidateWarnings] ORDER BY [RequestedName];
    END;
    IF @ConsoleResultRequested = 1
    BEGIN
        EXEC [monitor].[InternalEmitConsoleResult]
              @SourceTable=N'#EncryptionAnalysis_Encryption'
            , @ResultLabel=N'EncryptionAnalysis'
            , @EmptyMessage=N'Keine fachlichen Ergebnisse';
    END;
    IF @TableResultRequested = 1
    BEGIN
        EXEC [monitor].[InternalWriteResultTable]
              @SourceTable = N'#EncryptionAnalysis_Encryption'
            , @TargetTable=@TableTarget
            , @ThrowOnError = 1;
    END;
END;
GO
-- END SOURCE: Code/09_VersionAdaptive/080_USP_EncryptionAnalysis.sql

-- BEGIN SOURCE: Code/09_VersionAdaptive/090_USP_ExternalRuntimeAnalysis.sql
/*
===============================================================================
Objekt       : monitor.USP_ExternalRuntimeAnalysis
Version      : 1.0.0
Stand        : 2026-07-22
Typ          : Stored Procedure
Zweck        : Analysiert Konfiguration, registrierte Sprachen und Libraries,
               aktive External-Script-Requests, External Resource Pools sowie
               kumulative Runtime- und Performance-Counter-Evidenz.
SQL-Version  : SQL Server 2019 oder neuer.
Datenquellen : SERVERPROPERTY, sys.configurations, sys.dm_server_services,
               sys.external_languages, sys.external_language_files,
               sys.external_libraries, sys.external_library_files,
               sys.dm_external_script_requests, sys.dm_exec_requests,
               sys.dm_exec_sessions,
               sys.dm_external_script_execution_stats,
               sys.dm_resource_governor_external_resource_pools und
               sys.dm_os_performance_counters.
Datenschutz  : Liest keine Scripttexte, Parameter, Environment Variables,
               Binärinhalte oder Dateipfade. Konten und Clientkontext werden
               ausschließlich mit @MitSitzungskontext=1 ausgegeben.
Methodik     : Jede optionale Quelle wird einmal je Messpunkt materialisiert.
               Ein Sample verwendet ein gemeinsames Intervall und verwirft
               Deltas bei Reset, Zählerrückgang oder Poolversionswechsel.
Grenzen      : Registrierung und Konfiguration beweisen weder Installation
               noch Startfähigkeit einer konkreten Runtime. Request-CPU ist
               Engine-Evidenz und enthält keine belegte externe Prozess-CPU.
Kosten       : MEDIUM; optionales Sampling wartet höchstens 60 Sekunden.
Nebenwirkung : Rein lesend; führt kein externes Script aus und ändert weder
               Launchpad-, Resource-Governor- noch Serverkonfiguration.
===============================================================================
*/
CREATE OR ALTER PROCEDURE [monitor].[USP_ExternalRuntimeAnalysis]
      @DatabaseNames                    nvarchar(max)  = NULL
    , @SystemdatenbankenEinbeziehen     bit            = 0
    , @DatabaseNamePattern              nvarchar(4000) = NULL
    , @HighImpactConfirmed              bit            = 0
    , @LanguageNames                    nvarchar(max)  = NULL
    , @LanguageNamePattern              nvarchar(4000) = NULL
    , @SampleSeconds                    tinyint         = 0
    , @MitDateimetadaten                bit             = 0
    , @MitBerechtigungsanalyse          bit             = 0
    , @MitSitzungskontext               bit             = 0
    , @NurProblematisch                 bit             = 0
    , @MaxZeilen                        int             = 100
    , @LockTimeoutMs                    int             = 0
    , @ResultSetArt                     varchar(16)     = 'CONSOLE'
    , @ResultTablesJson                 nvarchar(max)   = NULL
    , @JsonErzeugen                     bit             = 0
    , @Json                             nvarchar(max)   = NULL OUTPUT
    , @PrintMeldungen                   bit             = 1
    , @Hilfe                            bit             = 0
    , @StatusCodeOut                    varchar(40)     = NULL OUTPUT
    , @IsPartialOut                     bit             = NULL OUTPUT
    , @ErrorNumberOut                   int             = NULL OUTPUT
    , @ErrorMessageOut                  nvarchar(2048)  = NULL OUTPUT
AS
BEGIN
    SET NOCOUNT ON;
    SET @Json=NULL;

    DECLARE @OriginalLockTimeout int=@@LOCK_TIMEOUT;
    DECLARE @LockTimeoutSql nvarchar(100);
    DECLARE @Now datetime2(3)=SYSUTCDATETIME();
    DECLARE @MeasurementStartUtc datetime2(3)=NULL,@MeasurementEndUtc datetime2(3)=NULL;
    DECLARE @Major int=TRY_CONVERT(int,SERVERPROPERTY(N'ProductMajorVersion'));
    DECLARE @HostPlatform nvarchar(60)=TRY_CONVERT(nvarchar(60),SERVERPROPERTY(N'HostPlatform'));
    DECLARE @OutputModeRequested varchar(16)=UPPER(LTRIM(RTRIM(COALESCE(@ResultSetArt,''))));
    DECLARE @OutputMode varchar(16)=@OutputModeRequested;
    DECLARE @TableResultRequested bit=CONVERT(bit,CASE WHEN @OutputModeRequested='TABLE' THEN 1 ELSE 0 END);
    DECLARE @ConsoleResultRequested bit=CONVERT(bit,CASE WHEN @OutputModeRequested='CONSOLE' THEN 1 ELSE 0 END);
    DECLARE @TableTarget sysname=NULL;
    DECLARE @StatusCode varchar(40)='AVAILABLE',@IsPartial bit=0;
    DECLARE @ErrorNumber int=NULL,@ErrorMessage nvarchar(2048)=NULL,@PrintMessage nvarchar(2048)=NULL;
    DECLARE @Limit bigint=CASE WHEN @MaxZeilen IS NULL OR @MaxZeilen=0
                               THEN CONVERT(bigint,9223372036854775807)
                               ELSE CONVERT(bigint,@MaxZeilen) END;
    DECLARE @RequiredPerformancePermission nvarchar(128)=CASE WHEN COALESCE(@Major,0)>=16 THEN N'VIEW SERVER PERFORMANCE STATE' ELSE N'VIEW SERVER STATE' END;
    DECLARE @RequiredServicePermission nvarchar(128)=CASE WHEN COALESCE(@Major,0)>=16 THEN N'VIEW SERVER SECURITY STATE' ELSE N'VIEW SERVER STATE' END;

    IF @Hilfe=1
    BEGIN
        PRINT N'monitor.USP_ExternalRuntimeAnalysis';
        PRINT N'Die Procedure analysiert External Languages, Libraries, aktive External-Script-Requests, External Resource Pools und Runtime-Counter, ohne externen Code auszuführen.';
        PRINT N'@SampleSeconds=0 liefert Momentaufnahmen; Werte von 1 bis 60 erzeugen ein gemeinsames Deltafenster für Pools, Execution Stats und Performance Counter.';
        PRINT N'@MitDateimetadaten=1 liest ausschließlich Dateiname und Plattform, niemals Inhalt, Parameter, Environment Variables oder Pfade.';
        PRINT N'@MitBerechtigungsanalyse=1 ergänzt sichtbare Ownernamen und benötigt den CATALOG_DEEP-Pfad sowie @HighImpactConfirmed=1.';
        PRINT N'@MitSitzungskontext=1 ergänzt Login, Host, Clientprogramm und External Worker Account; die Standardausgabe lässt diese Identitäten aus.';
        PRINT N'@ResultSetArt=CONSOLE|RAW|TABLE|NONE; TABLE schreibt das primäre Resultset findings über @ResultTablesJson.';
        RETURN;
    END;

    IF @OutputModeRequested NOT IN('CONSOLE','RAW','TABLE','NONE')
        SELECT @StatusCode='INVALID_PARAMETER',@IsPartial=1,@ErrorMessage=N'@ResultSetArt muss CONSOLE, RAW, TABLE oder NONE sein.';
    IF @TableResultRequested=0 AND NULLIF(LTRIM(RTRIM(COALESCE(@ResultTablesJson,N''))),N'') IS NOT NULL
        THROW 51011,N'@ResultTablesJson ist ausschließlich mit @ResultSetArt=TABLE zulässig.',1;
    IF @TableResultRequested=1
        EXEC [monitor].[InternalPrepareSingleResultTable]
              @ResultTablesJson=@ResultTablesJson
            , @ResultName=N'findings'
            , @TargetTable=@TableTarget OUTPUT
            , @ThrowOnError=1;
    IF @TableResultRequested=1 OR @ConsoleResultRequested=1 SET @OutputMode='NONE';

    IF @StatusCode='AVAILABLE'
       AND (@SystemdatenbankenEinbeziehen IS NULL OR @HighImpactConfirmed IS NULL
            OR @MitDateimetadaten IS NULL OR @MitBerechtigungsanalyse IS NULL
            OR @MitSitzungskontext IS NULL OR @NurProblematisch IS NULL
            OR @JsonErzeugen IS NULL OR @PrintMeldungen IS NULL
            OR @SampleSeconds IS NULL OR @SampleSeconds>60
            OR @MaxZeilen IS NULL OR @MaxZeilen<0
            OR @LockTimeoutMs IS NULL OR @LockTimeoutMs NOT BETWEEN 0 AND 60000)
        SELECT @StatusCode='INVALID_PARAMETER',@IsPartial=1,@ErrorMessage=N'Ungültiger Bit-, Sample-, Zeilen- oder Lock-Timeout-Parameter.';

    CREATE TABLE [#ExternalRuntimeAnalysis_DatabaseCandidates]
    (
          [DatabaseId] int NOT NULL PRIMARY KEY
        , [DatabaseName] sysname NOT NULL
        , [StateDesc] nvarchar(60) NULL
        , [UserAccessDesc] nvarchar(60) NULL
        , [IsReadOnly] bit NULL
        , [CompatibilityLevel] tinyint NULL
        , [CollationName] sysname NULL
        , [RecoveryModelDesc] nvarchar(60) NULL
        , [IsSystemDatabase] bit NULL
        , [RequestedOrdinal] int NULL
    );
    CREATE TABLE [#ExternalRuntimeAnalysis_DatabaseCandidateWarnings]
    (
          [RequestedName] sysname NULL
        , [StatusCode] varchar(40) NOT NULL
        , [ErrorMessage] nvarchar(2048) NULL
    );
    CREATE TABLE [#ExternalRuntimeAnalysis_LanguageFilters]
    (
          [ItemOrdinal] int NOT NULL
        , [LanguageName] sysname COLLATE SQL_Latin1_General_CP1_CS_AS NOT NULL
        , PRIMARY KEY ([LanguageName])
    );
    CREATE TABLE [#ExternalRuntimeAnalysis_Configuration]
    (
          [CollectedAtUtc] datetime2(3) NOT NULL
        , [ProductMajorVersion] int NULL
        , [HostPlatform] nvarchar(60) NULL
        , [IsAdvancedAnalyticsInstalled] int NULL
        , [ExternalScriptsConfiguredValue] int NULL
        , [ExternalScriptsValueInUse] int NULL
        , [LaunchpadServiceCount] int NULL
        , [LaunchpadRunningCount] int NULL
        , [LaunchpadStatus] varchar(40) NOT NULL
        , [RequiredPerformancePermission] nvarchar(128) NOT NULL
        , [RequiredServicePermission] nvarchar(128) NOT NULL
        , [EvidenceLimit] nvarchar(1000) NOT NULL
    );
    CREATE TABLE [#ExternalRuntimeAnalysis_DatabaseStatus]
    (
          [DatabaseName] sysname NULL
        , [StatusCode] varchar(40) NOT NULL
        , [IsPartial] bit NOT NULL
        , [LanguageCount] bigint NOT NULL
        , [LibraryCount] bigint NOT NULL
        , [SourceFailureCount] int NOT NULL
        , [ErrorNumber] int NULL
        , [ErrorMessage] nvarchar(2048) NULL
        , [EvidenceLimit] nvarchar(1000) NOT NULL
    );
    CREATE TABLE [#ExternalRuntimeAnalysis_SourceStatus]
    (
          [DatabaseName] sysname NULL
        , [SourceCode] varchar(80) NOT NULL
        , [StatusCode] varchar(40) NOT NULL
        , [IsPartial] bit NOT NULL
        , [RowCount] bigint NOT NULL
        , [RequiredPermission] nvarchar(256) NULL
        , [ReadAtUtc] datetime2(3) NOT NULL
        , [ErrorNumber] int NULL
        , [ErrorMessage] nvarchar(2048) NULL
        , [EvidenceLimit] nvarchar(1000) NOT NULL
    );
    CREATE TABLE [#ExternalRuntimeAnalysis_Languages]
    (
          [DatabaseName] sysname NOT NULL
        , [ExternalLanguageId] int NOT NULL
        , [LanguageName] sysname NOT NULL
        , [CreateDate] datetime2 NULL
        , [OwnerName] sysname NULL
        , [FileName] sysname NULL
        , [FilePlatformDesc] nvarchar(60) NULL
        , [FileMetadataStatus] varchar(40) NOT NULL
        , [AssessmentStatus] varchar(40) NOT NULL
        , [EvidenceLimit] nvarchar(1000) NOT NULL
    );
    CREATE TABLE [#ExternalRuntimeAnalysis_Libraries]
    (
          [DatabaseName] sysname NOT NULL
        , [ExternalLibraryId] int NOT NULL
        , [LibraryName] sysname NOT NULL
        , [LanguageName] sysname NULL
        , [ScopeDesc] varchar(7) NULL
        , [OwnerName] sysname NULL
        , [FilePlatformDesc] nvarchar(60) NULL
        , [FileMetadataStatus] varchar(40) NOT NULL
        , [AssessmentStatus] varchar(40) NOT NULL
        , [EvidenceLimit] nvarchar(1000) NOT NULL
    );
    CREATE TABLE [#ExternalRuntimeAnalysis_ActiveRequests]
    (
          [ExternalScriptRequestId] uniqueidentifier NOT NULL
        , [LanguageName] nvarchar(128) NULL
        , [DegreeOfParallelism] int NULL
        , [SessionId] smallint NULL
        , [RequestId] int NULL
        , [DatabaseName] sysname NULL
        , [RequestStatus] nvarchar(30) NULL
        , [Command] nvarchar(32) NULL
        , [BlockingSessionId] smallint NULL
        , [WaitType] nvarchar(60) NULL
        , [WaitTimeMs] int NULL
        , [ElapsedTimeMs] int NULL
        , [EngineCpuTimeMs] int NULL
        , [Reads] bigint NULL
        , [LogicalReads] bigint NULL
        , [Writes] bigint NULL
        , [LoginName] sysname NULL
        , [HostName] nvarchar(128) NULL
        , [ProgramName] nvarchar(128) NULL
        , [ExternalWorkerAccount] nvarchar(256) NULL
        , [EvidenceLimit] nvarchar(1000) NOT NULL
    );
    CREATE TABLE [#ExternalRuntimeAnalysis_PoolSamples]
    (
          [SamplePoint] char(2) NOT NULL
        , [ReadAtUtc] datetime2(3) NOT NULL
        , [ExternalPoolId] int NOT NULL
        , [PoolName] sysname NOT NULL
        , [PoolVersion] int NULL
        , [MaxCpuPercent] int NULL
        , [MaxProcesses] int NULL
        , [MaxMemoryPercent] int NULL
        , [StatisticsStartTime] datetime NULL
        , [PeakMemoryKb] bigint NULL
        , [WriteIoCount] bigint NULL
        , [ReadIoCount] bigint NULL
        , [TotalCpuKernelMs] bigint NULL
        , [TotalCpuUserMs] bigint NULL
        , [ActiveProcessesCount] int NULL
    );
    CREATE TABLE [#ExternalRuntimeAnalysis_ExternalPools]
    (
          [ExternalPoolId] int NOT NULL
        , [PoolName] sysname NOT NULL
        , [MaxCpuPercent] int NULL
        , [MaxProcesses] int NULL
        , [MaxMemoryPercent] int NULL
        , [StatisticsStartTime] datetime NULL
        , [PeakMemoryKb] bigint NULL
        , [ActiveProcessesCount] int NULL
        , [SampleSeconds] decimal(19,6) NULL
        , [CpuKernelDelta] bigint NULL
        , [CpuUserDelta] bigint NULL
        , [ReadIoDelta] bigint NULL
        , [WriteIoDelta] bigint NULL
        , [DeltaStatus] varchar(40) NOT NULL
        , [EvidenceLimit] nvarchar(1000) NOT NULL
    );
    CREATE TABLE [#ExternalRuntimeAnalysis_ExecutionStatSamples]
    (
          [SamplePoint] char(2) NOT NULL
        , [ReadAtUtc] datetime2(3) NOT NULL
        , [LanguageName] nvarchar(128) NOT NULL
        , [CounterName] nvarchar(256) NOT NULL
        , [CounterValue] bigint NOT NULL
    );
    CREATE TABLE [#ExternalRuntimeAnalysis_ExecutionStats]
    (
          [LanguageName] nvarchar(128) NOT NULL
        , [CounterName] nvarchar(256) NOT NULL
        , [CounterValue] bigint NOT NULL
        , [CounterDelta] bigint NULL
        , [DeltaStatus] varchar(40) NOT NULL
        , [EvidenceLimit] nvarchar(1000) NOT NULL
    );
    CREATE TABLE [#ExternalRuntimeAnalysis_CounterSamples]
    (
          [SamplePoint] char(2) NOT NULL
        , [ReadAtUtc] datetime2(3) NOT NULL
        , [CounterName] nvarchar(128) NOT NULL
        , [InstanceName] nvarchar(128) NOT NULL
        , [CounterType] int NOT NULL
        , [CounterValue] bigint NOT NULL
    );
    CREATE TABLE [#ExternalRuntimeAnalysis_PerformanceCounters]
    (
          [CounterName] nvarchar(128) NOT NULL
        , [InstanceName] nvarchar(128) NOT NULL
        , [CounterType] int NOT NULL
        , [CounterValue] bigint NOT NULL
        , [CounterDelta] bigint NULL
        , [DeltaStatus] varchar(40) NOT NULL
        , [Interpretation] varchar(40) NOT NULL
        , [MetricValue] decimal(38,6) NULL
        , [MetricUnit] varchar(40) NOT NULL
        , [FindingCode] varchar(80) NOT NULL
        , [EvidenceLimit] nvarchar(1000) NOT NULL
    );
    CREATE TABLE [#ExternalRuntimeAnalysis_Findings]
    (
          [FindingOrdinal] bigint IDENTITY(1,1) NOT NULL PRIMARY KEY
        , [DatabaseName] sysname NULL
        , [ObjectType] varchar(40) NOT NULL
        , [ObjectName] nvarchar(512) NULL
        , [Severity] varchar(16) NOT NULL
        , [Confidence] varchar(16) NOT NULL
        , [FindingCode] varchar(120) NOT NULL
        , [MetricName] varchar(80) NULL
        , [MetricValue] decimal(38,4) NULL
        , [ThresholdValue] decimal(38,4) NULL
        , [Evidence] nvarchar(1000) NOT NULL
        , [EvidenceLimit] nvarchar(1000) NOT NULL
        , [RecommendedNextCheck] nvarchar(1000) NOT NULL
    );
    CREATE TABLE [#ExternalRuntimeAnalysis_Warnings]
    (
          [WarningCode] varchar(120) NOT NULL
        , [Detail] nvarchar(1000) NOT NULL
        , [EvidenceLimit] nvarchar(1000) NOT NULL
    );

    BEGIN TRY
        DECLARE @LanguagePatternMode varchar(8),@LanguagePatternValue nvarchar(4000),@LanguageRegexFlags varchar(8),@LanguagePatternValid bit;
        SELECT @LanguagePatternMode=[PatternMode],@LanguagePatternValue=[PatternValue],
               @LanguageRegexFlags=[RegexFlags],@LanguagePatternValid=[IsValid]
        FROM [monitor].[TVF_ParsePattern](@LanguageNamePattern);

        IF @StatusCode='AVAILABLE'
           AND (@LanguagePatternValid=0 OR (@LanguageNames IS NOT NULL AND @LanguageNamePattern IS NOT NULL))
            SELECT @StatusCode='INVALID_PARAMETER',@IsPartial=1,@ErrorMessage=N'@LanguageNamePattern ist ungültig oder wurde zusammen mit @LanguageNames angegeben.';
        IF @StatusCode='AVAILABLE' AND @LanguagePatternMode IN('REGEX','REGEXI')
           AND
           (
               COALESCE(@Major,0)<17
               OR NOT EXISTS
                  (
                      SELECT 1
                      FROM [master].[sys].[databases] [d] WITH (NOLOCK)
                      WHERE [d].[database_id]=DB_ID() AND [d].[compatibility_level]>=170
                  )
           )
            SELECT @StatusCode='UNAVAILABLE_FEATURE',@IsPartial=1,@ErrorMessage=N'Regex-Pattern benötigen SQL Server 2025 und Compatibility Level 170 in der Frameworkdatenbank.';

        IF @StatusCode='AVAILABLE'
        BEGIN
            INSERT [#ExternalRuntimeAnalysis_LanguageFilters]([ItemOrdinal],[LanguageName])
            SELECT [ItemOrdinal],[NameValue]
            FROM [monitor].[TVF_ParseSqlNameList](@LanguageNames)
            WHERE [IsValid]=1;
            IF EXISTS(SELECT 1 FROM [monitor].[TVF_ParseSqlNameList](@LanguageNames) WHERE [IsValid]=0)
                SELECT @StatusCode='INVALID_PARAMETER',@IsPartial=1,@ErrorMessage=N'@LanguageNames enthält mindestens einen ungültigen SQL-Namen.';
        END;

        IF @StatusCode='AVAILABLE' AND @MitBerechtigungsanalyse=1
        BEGIN
            EXEC [monitor].[InternalCheckAnalysisPath]
                  @AnalysisClass='CATALOG_DEEP'
                , @HighImpactConfirmed=@HighImpactConfirmed
                , @StatusCode=@StatusCode OUTPUT
                , @ErrorMessage=@ErrorMessage OUTPUT;
            IF @StatusCode<>'AVAILABLE' SET @IsPartial=1;
        END;

        DECLARE @CrossDatabaseRequested bit=0;
        IF @StatusCode='AVAILABLE'
        BEGIN
            EXEC [monitor].[USP_PrepareDatabaseCandidates]
                  @DatabaseNames=@DatabaseNames
                , @SystemdatenbankenEinbeziehen=@SystemdatenbankenEinbeziehen
                , @DatabaseNamePattern=@DatabaseNamePattern
                , @HighImpactConfirmed=@HighImpactConfirmed
                , @AnalysisClass='EXTERNAL_RUNTIME_CURRENT'
                , @StatusCode=@StatusCode OUTPUT
                , @ErrorMessage=@ErrorMessage OUTPUT
                , @CrossDatabaseRequested=@CrossDatabaseRequested OUTPUT
                , @CandidateTable=N'#ExternalRuntimeAnalysis_DatabaseCandidates'
                , @WarningTable=N'#ExternalRuntimeAnalysis_DatabaseCandidateWarnings';
            IF @StatusCode<>'AVAILABLE' SET @IsPartial=1;
        END;

        INSERT [#ExternalRuntimeAnalysis_DatabaseStatus]
        ([DatabaseName],[StatusCode],[IsPartial],[LanguageCount],[LibraryCount],[SourceFailureCount],[EvidenceLimit])
        SELECT [DatabaseName],'PENDING',0,0,0,0,N'Sichtbare Datenbankkataloge; fehlende Metadatenrechte können zu Unterzählung führen.'
        FROM [#ExternalRuntimeAnalysis_DatabaseCandidates];
        INSERT [#ExternalRuntimeAnalysis_DatabaseStatus]
        ([DatabaseName],[StatusCode],[IsPartial],[LanguageCount],[LibraryCount],[SourceFailureCount],[ErrorMessage],[EvidenceLimit])
        SELECT [RequestedName],[StatusCode],1,0,0,1,[ErrorMessage],N'Explizit angeforderte Datenbank war nicht auswertbar.'
        FROM [#ExternalRuntimeAnalysis_DatabaseCandidateWarnings];

        SET @LockTimeoutSql=N'SET LOCK_TIMEOUT '+CONVERT(nvarchar(20),@LockTimeoutMs)+N';';
        EXEC [sys].[sp_executesql] @LockTimeoutSql;

        IF @StatusCode='AVAILABLE'
        BEGIN
            INSERT [#ExternalRuntimeAnalysis_Configuration]
            ([CollectedAtUtc],[ProductMajorVersion],[HostPlatform],[IsAdvancedAnalyticsInstalled],
             [ExternalScriptsConfiguredValue],[ExternalScriptsValueInUse],[LaunchpadServiceCount],
             [LaunchpadRunningCount],[LaunchpadStatus],[RequiredPerformancePermission],
             [RequiredServicePermission],[EvidenceLimit])
            SELECT @Now,@Major,@HostPlatform,
                   TRY_CONVERT(int,SERVERPROPERTY(N'IsAdvancedAnalyticsInstalled')),
                   MAX(CASE WHEN [name]=N'external scripts enabled' THEN TRY_CONVERT(int,[value]) END),
                   MAX(CASE WHEN [name]=N'external scripts enabled' THEN TRY_CONVERT(int,[value_in_use]) END),
                   NULL,NULL,'SOURCE_PENDING',@RequiredPerformancePermission,@RequiredServicePermission,
                   N'Konfiguration, Installationsproperty und Servicestatus sind getrennte Evidenz und beweisen keine Runtime-Startfähigkeit.'
            FROM [sys].[configurations] WITH (NOLOCK)
            WHERE [name]=N'external scripts enabled';
            INSERT [#ExternalRuntimeAnalysis_SourceStatus]
            VALUES(NULL,'SERVER_CONFIGURATION','AVAILABLE',0,1,N'VIEW SERVER STATE beziehungsweise Metadatensichtbarkeit',SYSUTCDATETIME(),NULL,NULL,
                   N'Nur external scripts enabled und SERVERPROPERTY(IsAdvancedAnalyticsInstalled).');

            BEGIN TRY
                DECLARE @LaunchpadServiceCount int,@LaunchpadRunningCount int;
                SELECT @LaunchpadServiceCount=COUNT_BIG(*),
                       @LaunchpadRunningCount=COALESCE(SUM(CASE WHEN [status]=4 THEN 1 ELSE 0 END),0)
                FROM [sys].[dm_server_services] WITH (NOLOCK)
                WHERE [servicename] LIKE N'%Launchpad%';
                UPDATE [#ExternalRuntimeAnalysis_Configuration]
                SET [LaunchpadServiceCount]=@LaunchpadServiceCount,
                    [LaunchpadRunningCount]=@LaunchpadRunningCount,
                    [LaunchpadStatus]=CASE WHEN @LaunchpadServiceCount=0 THEN 'NOT_VISIBLE'
                                           WHEN @LaunchpadRunningCount=@LaunchpadServiceCount THEN 'RUNNING'
                                           WHEN @LaunchpadRunningCount=0 THEN 'STOPPED'
                                           ELSE 'PARTIALLY_RUNNING' END;
                INSERT [#ExternalRuntimeAnalysis_SourceStatus]
                VALUES(NULL,'LAUNCHPAD_SERVICE','AVAILABLE',0,@LaunchpadServiceCount,@RequiredServicePermission,SYSUTCDATETIME(),NULL,NULL,
                       N'Nur aggregierter Launchpad-Servicezustand; Dienstkonto, Pfad und Instanzname werden nicht ausgegeben.');
            END TRY
            BEGIN CATCH
                UPDATE [#ExternalRuntimeAnalysis_Configuration] SET [LaunchpadStatus]='SOURCE_UNAVAILABLE';
                INSERT [#ExternalRuntimeAnalysis_SourceStatus]
                VALUES(NULL,'LAUNCHPAD_SERVICE',CASE WHEN ERROR_NUMBER() IN(229,297,300,371,916) THEN 'DENIED_PERMISSION' ELSE 'ERROR_HANDLED' END,1,0,
                       @RequiredServicePermission,SYSUTCDATETIME(),ERROR_NUMBER(),ERROR_MESSAGE(),N'Launchpad-Status konnte nicht gelesen werden; andere Evidenz bleibt gültig.');
            END CATCH;
        END;

        DECLARE @Db sysname,@CompatibilityLevel int,@Sql nvarchar(max),@Rows bigint;
        DECLARE @LanguagePredicate nvarchar(max)=
            N' AND (NOT EXISTS(SELECT 1 FROM [#ExternalRuntimeAnalysis_LanguageFilters]) OR EXISTS(SELECT 1 FROM [#ExternalRuntimeAnalysis_LanguageFilters] [f] WHERE [f].[LanguageName]=[el].[language] COLLATE SQL_Latin1_General_CP1_CS_AS))';
        DECLARE @LibraryLanguagePredicate nvarchar(max)=
            N' AND (NOT EXISTS(SELECT 1 FROM [#ExternalRuntimeAnalysis_LanguageFilters]) OR EXISTS(SELECT 1 FROM [#ExternalRuntimeAnalysis_LanguageFilters] [f] WHERE [f].[LanguageName]=[lib].[language] COLLATE SQL_Latin1_General_CP1_CS_AS))';
        IF @LanguagePatternMode='LIKE'
        BEGIN
            SET @LanguagePredicate+=N' AND [el].[language] COLLATE SQL_Latin1_General_CP1_CS_AS LIKE @pPattern COLLATE SQL_Latin1_General_CP1_CS_AS';
            SET @LibraryLanguagePredicate+=N' AND [lib].[language] COLLATE SQL_Latin1_General_CP1_CS_AS LIKE @pPattern COLLATE SQL_Latin1_General_CP1_CS_AS';
        END;
        IF @LanguagePatternMode IN('REGEX','REGEXI')
        BEGIN
            SET @LanguagePredicate+=N' AND REGEXP_LIKE([el].[language],@pPattern,@pRegexFlags)';
            SET @LibraryLanguagePredicate+=N' AND REGEXP_LIKE([lib].[language],@pPattern,@pRegexFlags)';
        END;

        IF @StatusCode='AVAILABLE'
        BEGIN
            DECLARE [DatabaseCursor] CURSOR LOCAL FAST_FORWARD FOR
                SELECT [DatabaseName],[CompatibilityLevel]
                FROM [#ExternalRuntimeAnalysis_DatabaseCandidates]
                ORDER BY COALESCE([RequestedOrdinal],[DatabaseId]),[DatabaseId];
            OPEN [DatabaseCursor];
            FETCH NEXT FROM [DatabaseCursor] INTO @Db,@CompatibilityLevel;
            WHILE @@FETCH_STATUS=0
            BEGIN
                IF @LanguagePatternMode IN('REGEX','REGEXI') AND COALESCE(@CompatibilityLevel,0)<170
                BEGIN
                    UPDATE [#ExternalRuntimeAnalysis_DatabaseStatus]
                    SET [StatusCode]='UNAVAILABLE_FEATURE',[IsPartial]=1,[SourceFailureCount]=[SourceFailureCount]+1,
                        [ErrorMessage]=N'Regex-Pattern benötigen Compatibility Level 170.'
                    WHERE [DatabaseName]=@Db;
                    INSERT [#ExternalRuntimeAnalysis_SourceStatus]
                    VALUES(@Db,'FILTER_CONTRACT','UNAVAILABLE_FEATURE',1,0,N'Compatibility Level 170',SYSUTCDATETIME(),NULL,N'Regex-Pattern nicht ausführbar.',N'Keine Katalogquelle wurde für diese Datenbank gelesen.');
                    FETCH NEXT FROM [DatabaseCursor] INTO @Db,@CompatibilityLevel;
                    CONTINUE;
                END;

                BEGIN TRY
                    SET @Sql=N'USE '+QUOTENAME(@Db)+N';
INSERT [#ExternalRuntimeAnalysis_Languages]
([DatabaseName],[ExternalLanguageId],[LanguageName],[CreateDate],[OwnerName],[FileName],[FilePlatformDesc],[FileMetadataStatus],[AssessmentStatus],[EvidenceLimit])
SELECT @pDatabaseName,[el].[external_language_id],[el].[language],[el].[create_date],'
 + CASE WHEN @MitBerechtigungsanalyse=1 THEN N'[dp].[name]' ELSE N'CONVERT(sysname,NULL)' END + N',
       NULL,NULL,'+CASE WHEN @MitDateimetadaten=1 THEN N'''PENDING''' ELSE N'''NOT_REQUESTED''' END+N',
       ''REGISTERED_STARTABILITY_UNVERIFIED'',
       N''Registrierung beweist weder installierte Runtime noch erfolgreiche Initialisierung.''
FROM [sys].[external_languages] [el] WITH (NOLOCK) '
 + CASE WHEN @MitBerechtigungsanalyse=1 THEN N'LEFT JOIN [sys].[database_principals] [dp] WITH (NOLOCK) ON [dp].[principal_id]=[el].[principal_id] ' ELSE N'' END
 + N'WHERE 1=1 '+@LanguagePredicate+N'; SET @pRows=@@ROWCOUNT;';
                    SET @Rows=0;
                    EXEC [sys].[sp_executesql] @Sql,
                         N'@pDatabaseName sysname,@pPattern nvarchar(4000),@pRegexFlags varchar(8),@pRows bigint OUTPUT',
                         @pDatabaseName=@Db,@pPattern=@LanguagePatternValue,@pRegexFlags=@LanguageRegexFlags,@pRows=@Rows OUTPUT;
                    INSERT [#ExternalRuntimeAnalysis_SourceStatus]
                    VALUES(@Db,'EXTERNAL_LANGUAGES','AVAILABLE',0,@Rows,N'Metadatensichtbarkeit',SYSUTCDATETIME(),NULL,NULL,N'Keine Binärinhalte, Parameter oder Environment Variables.');
                END TRY
                BEGIN CATCH
                    INSERT [#ExternalRuntimeAnalysis_SourceStatus]
                    VALUES(@Db,'EXTERNAL_LANGUAGES',CASE WHEN ERROR_NUMBER()=1222 THEN 'LOCK_TIMEOUT' WHEN ERROR_NUMBER() IN(229,297,300,371,916) THEN 'DENIED_PERMISSION' WHEN ERROR_NUMBER() IN(207,208) THEN 'SOURCE_UNAVAILABLE' ELSE 'ERROR_HANDLED' END,1,0,N'Metadatensichtbarkeit',SYSUTCDATETIME(),ERROR_NUMBER(),ERROR_MESSAGE(),N'Sprachenkatalog isoliert fehlgeschlagen.');
                END CATCH;

                IF @MitDateimetadaten=1
                BEGIN TRY
                    SET @Sql=N'USE '+QUOTENAME(@Db)+N';
INSERT [#ExternalRuntimeAnalysis_Languages]
([DatabaseName],[ExternalLanguageId],[LanguageName],[CreateDate],[OwnerName],[FileName],[FilePlatformDesc],[FileMetadataStatus],[AssessmentStatus],[EvidenceLimit])
SELECT @pDatabaseName,[el].[external_language_id],[el].[language],[el].[create_date],'
 + CASE WHEN @MitBerechtigungsanalyse=1 THEN N'[dp].[name]' ELSE N'CONVERT(sysname,NULL)' END + N',
       [elf].[file_name],[elf].[platform_desc],''AVAILABLE'',''REGISTERED_STARTABILITY_UNVERIFIED'',
       N''Nur Dateiname und Plattform; content, parameters und environment_variables sind ausgeschlossen.''
FROM [sys].[external_languages] [el] WITH (NOLOCK)
JOIN [sys].[external_language_files] [elf] WITH (NOLOCK) ON [elf].[external_language_id]=[el].[external_language_id] '
 + CASE WHEN @MitBerechtigungsanalyse=1 THEN N'LEFT JOIN [sys].[database_principals] [dp] WITH (NOLOCK) ON [dp].[principal_id]=[el].[principal_id] ' ELSE N'' END
 + N'WHERE 1=1 '+@LanguagePredicate+N';
SET @pRows=@@ROWCOUNT;
DELETE [base] FROM [#ExternalRuntimeAnalysis_Languages] [base]
WHERE [base].[DatabaseName]=@pDatabaseName AND [base].[FileMetadataStatus]=''PENDING''
  AND EXISTS(SELECT 1 FROM [#ExternalRuntimeAnalysis_Languages] [f]
             WHERE [f].[DatabaseName]=[base].[DatabaseName] AND [f].[ExternalLanguageId]=[base].[ExternalLanguageId]
               AND [f].[FileMetadataStatus]=''AVAILABLE'');
UPDATE [#ExternalRuntimeAnalysis_Languages] SET [FileMetadataStatus]=''NO_FILE_ROW_VISIBLE''
WHERE [DatabaseName]=@pDatabaseName AND [FileMetadataStatus]=''PENDING'';';
                    SET @Rows=0;
                    EXEC [sys].[sp_executesql] @Sql,
                         N'@pDatabaseName sysname,@pPattern nvarchar(4000),@pRegexFlags varchar(8),@pRows bigint OUTPUT',
                         @pDatabaseName=@Db,@pPattern=@LanguagePatternValue,@pRegexFlags=@LanguageRegexFlags,@pRows=@Rows OUTPUT;
                    INSERT [#ExternalRuntimeAnalysis_SourceStatus]
                    VALUES(@Db,'EXTERNAL_LANGUAGE_FILES','AVAILABLE',0,@Rows,N'Metadatensichtbarkeit',SYSUTCDATETIME(),NULL,NULL,N'content, parameters und environment_variables werden nicht referenziert.');
                END TRY
                BEGIN CATCH
                    UPDATE [#ExternalRuntimeAnalysis_Languages] SET [FileMetadataStatus]='ERROR_HANDLED'
                    WHERE [DatabaseName]=@Db AND [FileMetadataStatus]='PENDING';
                    INSERT [#ExternalRuntimeAnalysis_SourceStatus]
                    VALUES(@Db,'EXTERNAL_LANGUAGE_FILES',CASE WHEN ERROR_NUMBER()=1222 THEN 'LOCK_TIMEOUT' WHEN ERROR_NUMBER() IN(229,297,300,371,916) THEN 'DENIED_PERMISSION' WHEN ERROR_NUMBER() IN(207,208) THEN 'SOURCE_UNAVAILABLE' ELSE 'ERROR_HANDLED' END,1,0,N'Metadatensichtbarkeit',SYSUTCDATETIME(),ERROR_NUMBER(),ERROR_MESSAGE(),N'Dateimetadaten isoliert fehlgeschlagen; Sprachzeilen bleiben erhalten.');
                END CATCH;

                BEGIN TRY
                    SET @Sql=N'USE '+QUOTENAME(@Db)+N';
INSERT [#ExternalRuntimeAnalysis_Libraries]
([DatabaseName],[ExternalLibraryId],[LibraryName],[LanguageName],[ScopeDesc],[OwnerName],[FilePlatformDesc],[FileMetadataStatus],[AssessmentStatus],[EvidenceLimit])
SELECT @pDatabaseName,[lib].[external_library_id],[lib].[name],[lib].[language],[lib].[scope_desc],'
 + CASE WHEN @MitBerechtigungsanalyse=1 THEN N'[dp].[name]' ELSE N'CONVERT(sysname,NULL)' END + N',
       NULL,'+CASE WHEN @MitDateimetadaten=1 THEN N'''PENDING''' ELSE N'''NOT_REQUESTED''' END+N',
       ''REGISTERED_STARTABILITY_UNVERIFIED'',
       N''Libraryregistrierung beweist weder Packageinstallation außerhalb des Katalogs noch erfolgreiche Ausführung.''
FROM [sys].[external_libraries] [lib] WITH (NOLOCK) '
 + CASE WHEN @MitBerechtigungsanalyse=1 THEN N'LEFT JOIN [sys].[database_principals] [dp] WITH (NOLOCK) ON [dp].[principal_id]=[lib].[principal_id] ' ELSE N'' END
 + N'WHERE 1=1 '+@LibraryLanguagePredicate+N'; SET @pRows=@@ROWCOUNT;';
                    SET @Rows=0;
                    EXEC [sys].[sp_executesql] @Sql,
                         N'@pDatabaseName sysname,@pPattern nvarchar(4000),@pRegexFlags varchar(8),@pRows bigint OUTPUT',
                         @pDatabaseName=@Db,@pPattern=@LanguagePatternValue,@pRegexFlags=@LanguageRegexFlags,@pRows=@Rows OUTPUT;
                    INSERT [#ExternalRuntimeAnalysis_SourceStatus]
                    VALUES(@Db,'EXTERNAL_LIBRARIES','AVAILABLE',0,@Rows,N'Metadatensichtbarkeit',SYSUTCDATETIME(),NULL,NULL,N'Libraryinhalt wird nicht gelesen.');
                END TRY
                BEGIN CATCH
                    INSERT [#ExternalRuntimeAnalysis_SourceStatus]
                    VALUES(@Db,'EXTERNAL_LIBRARIES',CASE WHEN ERROR_NUMBER()=1222 THEN 'LOCK_TIMEOUT' WHEN ERROR_NUMBER() IN(229,297,300,371,916) THEN 'DENIED_PERMISSION' WHEN ERROR_NUMBER() IN(207,208) THEN 'SOURCE_UNAVAILABLE' ELSE 'ERROR_HANDLED' END,1,0,N'Metadatensichtbarkeit',SYSUTCDATETIME(),ERROR_NUMBER(),ERROR_MESSAGE(),N'Librarykatalog isoliert fehlgeschlagen.');
                END CATCH;

                IF @MitDateimetadaten=1
                BEGIN TRY
                    SET @Sql=N'USE '+QUOTENAME(@Db)+N';
INSERT [#ExternalRuntimeAnalysis_Libraries]
([DatabaseName],[ExternalLibraryId],[LibraryName],[LanguageName],[ScopeDesc],[OwnerName],[FilePlatformDesc],[FileMetadataStatus],[AssessmentStatus],[EvidenceLimit])
SELECT @pDatabaseName,[lib].[external_library_id],[lib].[name],[lib].[language],[lib].[scope_desc],'
 + CASE WHEN @MitBerechtigungsanalyse=1 THEN N'[dp].[name]' ELSE N'CONVERT(sysname,NULL)' END + N',
       [lf].[platform_desc],''AVAILABLE'',''REGISTERED_STARTABILITY_UNVERIFIED'',
       N''Nur Plattformmetadaten; content ist ausgeschlossen.''
FROM [sys].[external_libraries] [lib] WITH (NOLOCK)
JOIN [sys].[external_library_files] [lf] WITH (NOLOCK) ON [lf].[external_library_id]=[lib].[external_library_id] '
 + CASE WHEN @MitBerechtigungsanalyse=1 THEN N'LEFT JOIN [sys].[database_principals] [dp] WITH (NOLOCK) ON [dp].[principal_id]=[lib].[principal_id] ' ELSE N'' END
 + N'WHERE 1=1 '+@LibraryLanguagePredicate+N';
SET @pRows=@@ROWCOUNT;
DELETE [base] FROM [#ExternalRuntimeAnalysis_Libraries] [base]
WHERE [base].[DatabaseName]=@pDatabaseName AND [base].[FileMetadataStatus]=''PENDING''
  AND EXISTS(SELECT 1 FROM [#ExternalRuntimeAnalysis_Libraries] [f]
             WHERE [f].[DatabaseName]=[base].[DatabaseName] AND [f].[ExternalLibraryId]=[base].[ExternalLibraryId]
               AND [f].[FileMetadataStatus]=''AVAILABLE'');
UPDATE [#ExternalRuntimeAnalysis_Libraries] SET [FileMetadataStatus]=''NO_FILE_ROW_VISIBLE''
WHERE [DatabaseName]=@pDatabaseName AND [FileMetadataStatus]=''PENDING'';';
                    SET @Rows=0;
                    EXEC [sys].[sp_executesql] @Sql,
                         N'@pDatabaseName sysname,@pPattern nvarchar(4000),@pRegexFlags varchar(8),@pRows bigint OUTPUT',
                         @pDatabaseName=@Db,@pPattern=@LanguagePatternValue,@pRegexFlags=@LanguageRegexFlags,@pRows=@Rows OUTPUT;
                    INSERT [#ExternalRuntimeAnalysis_SourceStatus]
                    VALUES(@Db,'EXTERNAL_LIBRARY_FILES','AVAILABLE',0,@Rows,N'Metadatensichtbarkeit',SYSUTCDATETIME(),NULL,NULL,N'content wird nicht referenziert.');
                END TRY
                BEGIN CATCH
                    UPDATE [#ExternalRuntimeAnalysis_Libraries] SET [FileMetadataStatus]='ERROR_HANDLED'
                    WHERE [DatabaseName]=@Db AND [FileMetadataStatus]='PENDING';
                    INSERT [#ExternalRuntimeAnalysis_SourceStatus]
                    VALUES(@Db,'EXTERNAL_LIBRARY_FILES',CASE WHEN ERROR_NUMBER()=1222 THEN 'LOCK_TIMEOUT' WHEN ERROR_NUMBER() IN(229,297,300,371,916) THEN 'DENIED_PERMISSION' WHEN ERROR_NUMBER() IN(207,208) THEN 'SOURCE_UNAVAILABLE' ELSE 'ERROR_HANDLED' END,1,0,N'Metadatensichtbarkeit',SYSUTCDATETIME(),ERROR_NUMBER(),ERROR_MESSAGE(),N'Library-Dateimetadaten isoliert fehlgeschlagen.');
                END CATCH;

                UPDATE [ds]
                SET [LanguageCount]=(SELECT COUNT_BIG(DISTINCT [ExternalLanguageId]) FROM [#ExternalRuntimeAnalysis_Languages] [l] WHERE [l].[DatabaseName]=[ds].[DatabaseName]),
                    [LibraryCount]=(SELECT COUNT_BIG(DISTINCT [ExternalLibraryId]) FROM [#ExternalRuntimeAnalysis_Libraries] [l] WHERE [l].[DatabaseName]=[ds].[DatabaseName])
                FROM [#ExternalRuntimeAnalysis_DatabaseStatus] [ds]
                WHERE [ds].[DatabaseName]=@Db;

                FETCH NEXT FROM [DatabaseCursor] INTO @Db,@CompatibilityLevel;
            END;
            CLOSE [DatabaseCursor]; DEALLOCATE [DatabaseCursor];
        END;

        DECLARE @RuntimeLanguagePredicate nvarchar(max)=
            N' AND (NOT EXISTS(SELECT 1 FROM [#ExternalRuntimeAnalysis_LanguageFilters]) OR EXISTS(SELECT 1 FROM [#ExternalRuntimeAnalysis_LanguageFilters] [f] WHERE [f].[LanguageName]=[er].[language] COLLATE SQL_Latin1_General_CP1_CS_AS))';
        DECLARE @StatsLanguagePredicate nvarchar(max)=
            N' AND (NOT EXISTS(SELECT 1 FROM [#ExternalRuntimeAnalysis_LanguageFilters]) OR EXISTS(SELECT 1 FROM [#ExternalRuntimeAnalysis_LanguageFilters] [f] WHERE [f].[LanguageName]=[es].[language] COLLATE SQL_Latin1_General_CP1_CS_AS))';
        IF @LanguagePatternMode='LIKE'
        BEGIN
            SET @RuntimeLanguagePredicate+=N' AND [er].[language] COLLATE SQL_Latin1_General_CP1_CS_AS LIKE @pPattern COLLATE SQL_Latin1_General_CP1_CS_AS';
            SET @StatsLanguagePredicate+=N' AND [es].[language] COLLATE SQL_Latin1_General_CP1_CS_AS LIKE @pPattern COLLATE SQL_Latin1_General_CP1_CS_AS';
        END;
        IF @LanguagePatternMode IN('REGEX','REGEXI')
        BEGIN
            SET @RuntimeLanguagePredicate+=N' AND REGEXP_LIKE([er].[language],@pPattern,@pRegexFlags)';
            SET @StatsLanguagePredicate+=N' AND REGEXP_LIKE([es].[language],@pPattern,@pRegexFlags)';
        END;

        IF @StatusCode='AVAILABLE'
        BEGIN
            BEGIN TRY
                SET @Sql=N'INSERT [#ExternalRuntimeAnalysis_ActiveRequests]
([ExternalScriptRequestId],[LanguageName],[DegreeOfParallelism],[SessionId],[RequestId],[DatabaseName],[RequestStatus],[Command],
 [BlockingSessionId],[WaitType],[WaitTimeMs],[ElapsedTimeMs],[EngineCpuTimeMs],[Reads],[LogicalReads],[Writes],
 [LoginName],[HostName],[ProgramName],[ExternalWorkerAccount],[EvidenceLimit])
SELECT [er].[external_script_request_id],[er].[language],[er].[degree_of_parallelism],
       [r].[session_id],[r].[request_id],[d].[name],[r].[status],[r].[command],[r].[blocking_session_id],
       [r].[wait_type],[r].[wait_time],[r].[total_elapsed_time],[r].[cpu_time],[r].[reads],[r].[logical_reads],[r].[writes],'
 + CASE WHEN @MitSitzungskontext=1 THEN N'[s].[login_name],[s].[host_name],[s].[program_name],[er].[external_user_name]' ELSE N'NULL,NULL,NULL,NULL' END + N',
       N''Aktive Momentaufnahme; Engine-CPU enthält keine belegte externe Prozess-CPU und abgeschlossene Requests fehlen.''
FROM [sys].[dm_external_script_requests] [er] WITH (NOLOCK)
LEFT JOIN [sys].[dm_exec_requests] [r] WITH (NOLOCK) ON [r].[external_script_request_id]=[er].[external_script_request_id]
LEFT JOIN [sys].[dm_exec_sessions] [s] WITH (NOLOCK) ON [s].[session_id]=[r].[session_id]
LEFT JOIN [sys].[databases] [d] WITH (NOLOCK) ON [d].[database_id]=COALESCE([r].[database_id],[s].[database_id])
WHERE 1=1 '+@RuntimeLanguagePredicate+N'
  AND (COALESCE([r].[database_id],[s].[database_id]) IS NULL
       OR EXISTS(SELECT 1 FROM [#ExternalRuntimeAnalysis_DatabaseCandidates] [c]
                 WHERE [c].[DatabaseId]=COALESCE([r].[database_id],[s].[database_id]))); SET @pRows=@@ROWCOUNT;';
                SET @Rows=0;
                EXEC [sys].[sp_executesql] @Sql,
                     N'@pPattern nvarchar(4000),@pRegexFlags varchar(8),@pRows bigint OUTPUT',
                     @pPattern=@LanguagePatternValue,@pRegexFlags=@LanguageRegexFlags,@pRows=@Rows OUTPUT;
                INSERT [#ExternalRuntimeAnalysis_SourceStatus]
                VALUES(NULL,'ACTIVE_EXTERNAL_REQUESTS','AVAILABLE',0,@Rows,@RequiredPerformancePermission,SYSUTCDATETIME(),NULL,NULL,N'Dokumentierter Join über external_script_request_id; keine Script- oder Batchtexte.');
            END TRY
            BEGIN CATCH
                INSERT [#ExternalRuntimeAnalysis_SourceStatus]
                VALUES(NULL,'ACTIVE_EXTERNAL_REQUESTS',CASE WHEN ERROR_NUMBER() IN(229,297,300,371,916) THEN 'DENIED_PERMISSION' WHEN ERROR_NUMBER() IN(207,208) THEN 'SOURCE_UNAVAILABLE' ELSE 'ERROR_HANDLED' END,1,0,@RequiredPerformancePermission,SYSUTCDATETIME(),ERROR_NUMBER(),ERROR_MESSAGE(),N'Aktive Requests isoliert fehlgeschlagen.');
            END CATCH;

            SET @MeasurementStartUtc=SYSUTCDATETIME();
            BEGIN TRY
                INSERT [#ExternalRuntimeAnalysis_PoolSamples]
                SELECT 'T1',SYSUTCDATETIME(),[external_pool_id],[name],[pool_version],[max_cpu_percent],[max_processes],[max_memory_percent],
                       [statistics_start_time],[peak_memory_kb],[write_io_count],[read_io_count],[total_cpu_kernel_ms],[total_cpu_user_ms],[active_processes_count]
                FROM [sys].[dm_resource_governor_external_resource_pools] WITH (NOLOCK);
                INSERT [#ExternalRuntimeAnalysis_SourceStatus]
                VALUES(NULL,'EXTERNAL_POOLS_T1','AVAILABLE',0,@@ROWCOUNT,@RequiredPerformancePermission,SYSUTCDATETIME(),NULL,NULL,N'Kumulative Poolwerte; Linux-Einheiten benötigen die dokumentierte Plattformgegenprüfung.');
            END TRY
            BEGIN CATCH
                INSERT [#ExternalRuntimeAnalysis_SourceStatus]
                VALUES(NULL,'EXTERNAL_POOLS_T1',CASE WHEN ERROR_NUMBER() IN(229,297,300,371,916) THEN 'DENIED_PERMISSION' WHEN ERROR_NUMBER() IN(207,208) THEN 'SOURCE_UNAVAILABLE' ELSE 'ERROR_HANDLED' END,1,0,@RequiredPerformancePermission,SYSUTCDATETIME(),ERROR_NUMBER(),ERROR_MESSAGE(),N'Poolquelle isoliert fehlgeschlagen.');
            END CATCH;

            BEGIN TRY
                SET @Sql=N'INSERT [#ExternalRuntimeAnalysis_ExecutionStatSamples]
SELECT ''T1'',SYSUTCDATETIME(),[es].[language],[es].[counter_name],CONVERT(bigint,[es].[counter_value])
FROM [sys].[dm_external_script_execution_stats] [es] WITH (NOLOCK)
WHERE 1=1 '+@StatsLanguagePredicate+N'; SET @pRows=@@ROWCOUNT;';
                SET @Rows=0;
                EXEC [sys].[sp_executesql] @Sql,N'@pPattern nvarchar(4000),@pRegexFlags varchar(8),@pRows bigint OUTPUT',
                     @pPattern=@LanguagePatternValue,@pRegexFlags=@LanguageRegexFlags,@pRows=@Rows OUTPUT;
                INSERT [#ExternalRuntimeAnalysis_SourceStatus]
                VALUES(NULL,'EXECUTION_STATS_T1','AVAILABLE',0,@Rows,@RequiredPerformancePermission,SYSUTCDATETIME(),NULL,NULL,N'Featuretelemetrie registrierter Funktionen; keine allgemeine Script-Ausführungshistorie.');
            END TRY
            BEGIN CATCH
                INSERT [#ExternalRuntimeAnalysis_SourceStatus]
                VALUES(NULL,'EXECUTION_STATS_T1',CASE WHEN ERROR_NUMBER() IN(229,297,300,371,916) THEN 'DENIED_PERMISSION' WHEN ERROR_NUMBER() IN(207,208) THEN 'SOURCE_UNAVAILABLE' ELSE 'ERROR_HANDLED' END,1,0,@RequiredPerformancePermission,SYSUTCDATETIME(),ERROR_NUMBER(),ERROR_MESSAGE(),N'Execution-Stats-Quelle isoliert fehlgeschlagen.');
            END CATCH;

            BEGIN TRY
                INSERT [#ExternalRuntimeAnalysis_CounterSamples]
                SELECT 'T1',SYSUTCDATETIME(),[counter_name],[instance_name],[cntr_type],[cntr_value]
                FROM [sys].[dm_os_performance_counters] WITH (NOLOCK)
                WHERE [object_name] LIKE N'%External Scripts%';
                INSERT [#ExternalRuntimeAnalysis_SourceStatus]
                VALUES(NULL,'EXTERNAL_COUNTERS_T1','AVAILABLE',0,@@ROWCOUNT,@RequiredPerformancePermission,SYSUTCDATETIME(),NULL,NULL,N'Originale SQL-Server-Counterwerte; cntr_type steuert die Interpretation.');
            END TRY
            BEGIN CATCH
                INSERT [#ExternalRuntimeAnalysis_SourceStatus]
                VALUES(NULL,'EXTERNAL_COUNTERS_T1',CASE WHEN ERROR_NUMBER() IN(229,297,300,371,916) THEN 'DENIED_PERMISSION' ELSE 'ERROR_HANDLED' END,1,0,@RequiredPerformancePermission,SYSUTCDATETIME(),ERROR_NUMBER(),ERROR_MESSAGE(),N'Performance-Counter-Quelle isoliert fehlgeschlagen.');
            END CATCH;

            IF @SampleSeconds>0
            BEGIN
                DECLARE @Delay char(8)=CONVERT(char(8),DATEADD(SECOND,@SampleSeconds,CONVERT(datetime,'19000101',112)),108);
                WAITFOR DELAY @Delay;

                BEGIN TRY
                    INSERT [#ExternalRuntimeAnalysis_PoolSamples]
                    SELECT 'T2',SYSUTCDATETIME(),[external_pool_id],[name],[pool_version],[max_cpu_percent],[max_processes],[max_memory_percent],
                           [statistics_start_time],[peak_memory_kb],[write_io_count],[read_io_count],[total_cpu_kernel_ms],[total_cpu_user_ms],[active_processes_count]
                    FROM [sys].[dm_resource_governor_external_resource_pools] WITH (NOLOCK);
                    INSERT [#ExternalRuntimeAnalysis_SourceStatus]
                    VALUES(NULL,'EXTERNAL_POOLS_T2','AVAILABLE',0,@@ROWCOUNT,@RequiredPerformancePermission,SYSUTCDATETIME(),NULL,NULL,N'Zweiter Messpunkt desselben Samplefensters.');
                END TRY
                BEGIN CATCH
                    INSERT [#ExternalRuntimeAnalysis_SourceStatus]
                    VALUES(NULL,'EXTERNAL_POOLS_T2',CASE WHEN ERROR_NUMBER() IN(229,297,300,371,916) THEN 'DENIED_PERMISSION' WHEN ERROR_NUMBER() IN(207,208) THEN 'SOURCE_UNAVAILABLE' ELSE 'ERROR_HANDLED' END,1,0,@RequiredPerformancePermission,SYSUTCDATETIME(),ERROR_NUMBER(),ERROR_MESSAGE(),N'Zweiter Poolmesspunkt isoliert fehlgeschlagen.');
                END CATCH;

                BEGIN TRY
                    SET @Sql=N'INSERT [#ExternalRuntimeAnalysis_ExecutionStatSamples]
SELECT ''T2'',SYSUTCDATETIME(),[es].[language],[es].[counter_name],CONVERT(bigint,[es].[counter_value])
FROM [sys].[dm_external_script_execution_stats] [es] WITH (NOLOCK)
WHERE 1=1 '+@StatsLanguagePredicate+N'; SET @pRows=@@ROWCOUNT;';
                    SET @Rows=0;
                    EXEC [sys].[sp_executesql] @Sql,N'@pPattern nvarchar(4000),@pRegexFlags varchar(8),@pRows bigint OUTPUT',
                         @pPattern=@LanguagePatternValue,@pRegexFlags=@LanguageRegexFlags,@pRows=@Rows OUTPUT;
                    INSERT [#ExternalRuntimeAnalysis_SourceStatus]
                    VALUES(NULL,'EXECUTION_STATS_T2','AVAILABLE',0,@Rows,@RequiredPerformancePermission,SYSUTCDATETIME(),NULL,NULL,N'Zweiter Messpunkt der persistenten Featuretelemetrie.');
                END TRY
                BEGIN CATCH
                    INSERT [#ExternalRuntimeAnalysis_SourceStatus]
                    VALUES(NULL,'EXECUTION_STATS_T2',CASE WHEN ERROR_NUMBER() IN(229,297,300,371,916) THEN 'DENIED_PERMISSION' WHEN ERROR_NUMBER() IN(207,208) THEN 'SOURCE_UNAVAILABLE' ELSE 'ERROR_HANDLED' END,1,0,@RequiredPerformancePermission,SYSUTCDATETIME(),ERROR_NUMBER(),ERROR_MESSAGE(),N'Zweiter Execution-Stats-Messpunkt isoliert fehlgeschlagen.');
                END CATCH;

                BEGIN TRY
                    INSERT [#ExternalRuntimeAnalysis_CounterSamples]
                    SELECT 'T2',SYSUTCDATETIME(),[counter_name],[instance_name],[cntr_type],[cntr_value]
                    FROM [sys].[dm_os_performance_counters] WITH (NOLOCK)
                    WHERE [object_name] LIKE N'%External Scripts%';
                    INSERT [#ExternalRuntimeAnalysis_SourceStatus]
                    VALUES(NULL,'EXTERNAL_COUNTERS_T2','AVAILABLE',0,@@ROWCOUNT,@RequiredPerformancePermission,SYSUTCDATETIME(),NULL,NULL,N'Zweiter Messpunkt desselben Samplefensters.');
                END TRY
                BEGIN CATCH
                    INSERT [#ExternalRuntimeAnalysis_SourceStatus]
                    VALUES(NULL,'EXTERNAL_COUNTERS_T2',CASE WHEN ERROR_NUMBER() IN(229,297,300,371,916) THEN 'DENIED_PERMISSION' ELSE 'ERROR_HANDLED' END,1,0,@RequiredPerformancePermission,SYSUTCDATETIME(),ERROR_NUMBER(),ERROR_MESSAGE(),N'Zweiter Countermesspunkt isoliert fehlgeschlagen.');
                END CATCH;
            END;
            SET @MeasurementEndUtc=SYSUTCDATETIME();
        END;

        INSERT [#ExternalRuntimeAnalysis_ExternalPools]
        SELECT [a].[ExternalPoolId],[a].[PoolName],COALESCE([b].[MaxCpuPercent],[a].[MaxCpuPercent]),
               COALESCE([b].[MaxProcesses],[a].[MaxProcesses]),COALESCE([b].[MaxMemoryPercent],[a].[MaxMemoryPercent]),
               COALESCE([b].[StatisticsStartTime],[a].[StatisticsStartTime]),COALESCE([b].[PeakMemoryKb],[a].[PeakMemoryKb]),
               COALESCE([b].[ActiveProcessesCount],[a].[ActiveProcessesCount]),
               CONVERT(decimal(19,6),CASE WHEN @SampleSeconds>0 THEN DATEDIFF_BIG(MICROSECOND,[a].[ReadAtUtc],[b].[ReadAtUtc])/1000000.0 END),
               CASE WHEN [b].[ExternalPoolId] IS NOT NULL AND [a].[StatisticsStartTime]=[b].[StatisticsStartTime]
                          AND [a].[PoolVersion]=[b].[PoolVersion] AND [b].[TotalCpuKernelMs]>=[a].[TotalCpuKernelMs]
                    THEN [b].[TotalCpuKernelMs]-[a].[TotalCpuKernelMs] END,
               CASE WHEN [b].[ExternalPoolId] IS NOT NULL AND [a].[StatisticsStartTime]=[b].[StatisticsStartTime]
                          AND [a].[PoolVersion]=[b].[PoolVersion] AND [b].[TotalCpuUserMs]>=[a].[TotalCpuUserMs]
                    THEN [b].[TotalCpuUserMs]-[a].[TotalCpuUserMs] END,
               CASE WHEN [b].[ExternalPoolId] IS NOT NULL AND [a].[StatisticsStartTime]=[b].[StatisticsStartTime]
                          AND [a].[PoolVersion]=[b].[PoolVersion] AND [b].[ReadIoCount]>=[a].[ReadIoCount]
                    THEN [b].[ReadIoCount]-[a].[ReadIoCount] END,
               CASE WHEN [b].[ExternalPoolId] IS NOT NULL AND [a].[StatisticsStartTime]=[b].[StatisticsStartTime]
                          AND [a].[PoolVersion]=[b].[PoolVersion] AND [b].[WriteIoCount]>=[a].[WriteIoCount]
                    THEN [b].[WriteIoCount]-[a].[WriteIoCount] END,
               CASE WHEN @SampleSeconds=0 THEN 'NOT_SAMPLED'
                    WHEN [b].[ExternalPoolId] IS NULL THEN 'T2_UNAVAILABLE'
                    WHEN [a].[StatisticsStartTime]<>[b].[StatisticsStartTime] OR [a].[PoolVersion]<>[b].[PoolVersion] THEN 'RESET_BOUNDARY'
                    WHEN [b].[TotalCpuKernelMs]<[a].[TotalCpuKernelMs] OR [b].[TotalCpuUserMs]<[a].[TotalCpuUserMs]
                      OR [b].[ReadIoCount]<[a].[ReadIoCount] OR [b].[WriteIoCount]<[a].[WriteIoCount] THEN 'RESET_BOUNDARY'
                    ELSE 'DELTA_AVAILABLE' END,
               CASE WHEN UPPER(COALESCE(@HostPlatform,N''))='LINUX'
                    THEN N'Linux bezieht Poolwerte aus cgroups; die herstellerdokumentierte Einheitenabweichung ist vor plattformübergreifenden Vergleichen zu berücksichtigen.'
                    ELSE N'Kumulative Poolwerte gelten seit statistics_start_time; Deltas werden nur innerhalb derselben Resetepoche berechnet.' END
        FROM [#ExternalRuntimeAnalysis_PoolSamples] [a]
        LEFT JOIN [#ExternalRuntimeAnalysis_PoolSamples] [b]
          ON [b].[SamplePoint]='T2' AND [b].[ExternalPoolId]=[a].[ExternalPoolId]
        WHERE [a].[SamplePoint]='T1';

        INSERT [#ExternalRuntimeAnalysis_ExecutionStats]
        SELECT [a].[LanguageName],[a].[CounterName],COALESCE([b].[CounterValue],[a].[CounterValue]),
               CASE WHEN [b].[CounterValue]>=[a].[CounterValue] THEN [b].[CounterValue]-[a].[CounterValue] END,
               CASE WHEN @SampleSeconds=0 THEN 'NOT_SAMPLED' WHEN [b].[CounterName] IS NULL THEN 'T2_UNAVAILABLE'
                    WHEN [b].[CounterValue]<[a].[CounterValue] THEN 'RESET_BOUNDARY' ELSE 'DELTA_AVAILABLE' END,
               N'Die Werte erfassen registrierte Featurefunktionen und sind keine vollständige Historie beliebiger Scripts oder Packages.'
        FROM [#ExternalRuntimeAnalysis_ExecutionStatSamples] [a]
        LEFT JOIN [#ExternalRuntimeAnalysis_ExecutionStatSamples] [b]
          ON [b].[SamplePoint]='T2' AND [b].[LanguageName]=[a].[LanguageName] AND [b].[CounterName]=[a].[CounterName]
        WHERE [a].[SamplePoint]='T1';

        INSERT [#ExternalRuntimeAnalysis_PerformanceCounters]
        SELECT [a].[CounterName],[a].[InstanceName],[a].[CounterType],COALESCE([b].[CounterValue],[a].[CounterValue]),
               CASE WHEN @SampleSeconds>0 AND [b].[CounterValue]>=[a].[CounterValue]
                    THEN [b].[CounterValue]-[a].[CounterValue] END,
               CASE WHEN @SampleSeconds=0 THEN 'NOT_SAMPLED'
                    WHEN [b].[CounterName] IS NULL THEN 'T2_UNAVAILABLE'
                    WHEN [b].[CounterValue]<[a].[CounterValue] THEN 'RESET_BOUNDARY'
                    ELSE 'DELTA_AVAILABLE' END,
               [i].[Interpretation],[i].[MetricValue],[i].[MetricUnit],[i].[FindingCode],
               N'Counterinterpretation basiert auf cntr_type; bei fehlendem zweiten Messpunkt bleibt eine Deltaaussage aus.'
        FROM [#ExternalRuntimeAnalysis_CounterSamples] [a]
        LEFT JOIN [#ExternalRuntimeAnalysis_CounterSamples] [b]
          ON [b].[SamplePoint]='T2' AND [b].[CounterName]=[a].[CounterName]
         AND [b].[InstanceName]=[a].[InstanceName] AND [b].[CounterType]=[a].[CounterType]
        CROSS APPLY [monitor].[TVF_InterpretPerformanceCounter]
        (
              [a].[CounterType],[a].[CounterValue],COALESCE([b].[CounterValue],[a].[CounterValue])
            , NULL,NULL
            , CONVERT(decimal(19,6),CASE WHEN @SampleSeconds>0 THEN DATEDIFF_BIG(MICROSECOND,[a].[ReadAtUtc],[b].[ReadAtUtc])/1000000.0 ELSE 0 END)
        ) [i]
        WHERE [a].[SamplePoint]='T1';

        INSERT [#ExternalRuntimeAnalysis_Findings]
        ([DatabaseName],[ObjectType],[ObjectName],[Severity],[Confidence],[FindingCode],[MetricName],[MetricValue],[ThresholdValue],[Evidence],[EvidenceLimit],[RecommendedNextCheck])
        SELECT NULL,'SERVER_CONFIGURATION',NULL,'WARN','HIGH','EXTERNAL_SCRIPTS_ENABLED_WITHOUT_INSTALLED_FEATURE_EVIDENCE',
               'IsAdvancedAnalyticsInstalled',[IsAdvancedAnalyticsInstalled],1,
               N'external scripts enabled ist aktiv, SERVERPROPERTY(IsAdvancedAnalyticsInstalled) liefert jedoch nicht 1.',
               N'Die Property beweist keine konkrete Runtimeinstallation; der Widerspruch ist eine Konfigurationsprüfung.',
               N'Installationsumfang und Launchpad-Konfiguration auf dem Host getrennt prüfen.'
        FROM [#ExternalRuntimeAnalysis_Configuration]
        WHERE [ExternalScriptsValueInUse]=1 AND COALESCE([IsAdvancedAnalyticsInstalled],0)<>1;

        INSERT [#ExternalRuntimeAnalysis_Findings]
        SELECT NULL,'LAUNCHPAD',NULL,'WARN','HIGH','LAUNCHPAD_NOT_RUNNING',
               'LaunchpadRunningCount',[LaunchpadRunningCount],[LaunchpadServiceCount],
               N'External Scripts ist aktiv, aber keine sichtbare Launchpad-Servicezeile ist im Status Running.',
               N'Der Befund setzt eine erfolgreich gelesene Servicequelle voraus; er führt keinen Starttest aus.',
               N'Servicezustand, Event Log und externe Extensibility Logs auf dem Host prüfen.'
        FROM [#ExternalRuntimeAnalysis_Configuration]
        WHERE [ExternalScriptsValueInUse]=1 AND [LaunchpadStatus] IN('NOT_VISIBLE','STOPPED','PARTIALLY_RUNNING');

        INSERT [#ExternalRuntimeAnalysis_Findings]
        SELECT [x].[DatabaseName],'DATABASE_REGISTRATION',NULL,'WARN','HIGH','REGISTERED_RUNTIME_WHILE_EXTERNAL_SCRIPTS_DISABLED',
               'RegisteredObjectCount',[x].[RegisteredObjectCount],1,
               N'Mindestens eine External Language oder Library ist sichtbar, während external scripts enabled nicht aktiv ist.',
               N'Registrierung beweist keine frühere oder aktuelle erfolgreiche Ausführung.',
               N'Prüfen, ob die Deaktivierung beabsichtigt ist und ob die registrierten Objekte noch benötigt werden.'
        FROM
        (
            SELECT [r].[DatabaseName],COUNT_BIG(*) AS [RegisteredObjectCount]
            FROM
            (
                SELECT DISTINCT [DatabaseName],'LANGUAGE' AS [ObjectType],[ExternalLanguageId] AS [ObjectId]
                FROM [#ExternalRuntimeAnalysis_Languages]
                UNION ALL
                SELECT DISTINCT [DatabaseName],'LIBRARY',[ExternalLibraryId]
                FROM [#ExternalRuntimeAnalysis_Libraries]
            ) [r]
            GROUP BY [r].[DatabaseName]
        ) [x]
        CROSS JOIN [#ExternalRuntimeAnalysis_Configuration] [c]
        WHERE COALESCE([c].[ExternalScriptsValueInUse],0)=0;

        INSERT [#ExternalRuntimeAnalysis_Findings]
        SELECT [DatabaseName],'EXTERNAL_LANGUAGE',[LanguageName],'WARN','HIGH','LANGUAGE_FILE_PLATFORM_MISMATCH',
               'PlatformMismatch',1,0,
               CONCAT(N'Die registrierte Dateiplattform ',[FilePlatformDesc],N' stimmt nicht mit HostPlatform ',COALESCE(@HostPlatform,N'<unbekannt>'),N' überein.'),
               N'Nur die registrierte Plattformmetadatenzeile wird verglichen; Binärinhalt und reale Ladefähigkeit bleiben ungeprüft.',
               N'Language-Extension-Paket und plattformspezifische Registrierung prüfen.'
        FROM [#ExternalRuntimeAnalysis_Languages]
        WHERE [FileMetadataStatus]='AVAILABLE' AND [FilePlatformDesc] IS NOT NULL
          AND UPPER([FilePlatformDesc])<>UPPER(COALESCE(@HostPlatform,N''));

        INSERT [#ExternalRuntimeAnalysis_Findings]
        SELECT [DatabaseName],'ACTIVE_REQUEST',CONVERT(nvarchar(36),[ExternalScriptRequestId]),'WARN','HIGH','ACTIVE_EXTERNAL_REQUEST_BLOCKED',
               'BlockingSessionId',[BlockingSessionId],0,
               CONCAT(N'Der aktive External-Script-Request ist durch Session ',CONVERT(nvarchar(20),[BlockingSessionId]),N' geblockt.'),
               N'Momentaufnahme; der Blockingzustand kann unmittelbar wechseln.',
               N'USP_CurrentBlocking für die vollständige Blockerkette ausführen.'
        FROM [#ExternalRuntimeAnalysis_ActiveRequests]
        WHERE COALESCE([BlockingSessionId],0)>0;

        INSERT [#ExternalRuntimeAnalysis_Findings]
        SELECT NULL,'EXTERNAL_POOL',[PoolName],'WARN','HIGH','EXTERNAL_POOL_PROCESS_LIMIT_REACHED',
               'ActiveProcessesCount',[ActiveProcessesCount],[MaxProcesses],
               N'Die aktive Prozesszahl erreicht oder überschreitet das konfigurierte, von null verschiedene max_processes.',
               N'Ein einzelner Messpunkt beweist keine anhaltende Sättigung; max_processes=0 bedeutet unbegrenzt.',
               N'Wiederholt messen und Warteschlangen, Laufzeiten sowie Resource-Governor-Zuordnung prüfen.'
        FROM [#ExternalRuntimeAnalysis_ExternalPools]
        WHERE COALESCE([MaxProcesses],0)>0 AND [ActiveProcessesCount]>=[MaxProcesses];

        INSERT [#ExternalRuntimeAnalysis_Findings]
        SELECT NULL,'PERFORMANCE_COUNTER',[CounterName],'WARN','HIGH','EXTERNAL_SCRIPT_EXECUTION_ERRORS_IN_SAMPLE',
               'CounterDelta',[CounterDelta],0,
               N'Der Counter Execution Errors ist im gültigen Samplefenster gestiegen.',
               N'Der Counter schließt laut Herstellerdokumentation nicht alle R- oder Python-Fehler ein und enthält keine Fehlerursache.',
               N'Errorlog, vorhandene Extended Events und externe Launchpad-Logs im gleichen Zeitfenster prüfen.'
        FROM [#ExternalRuntimeAnalysis_PerformanceCounters]
        WHERE [CounterName]=N'Execution Errors' AND [CounterDelta]>0
          AND [DeltaStatus]='DELTA_AVAILABLE';

        INSERT [#ExternalRuntimeAnalysis_Findings]
        SELECT [DatabaseName],'EXTERNAL_LANGUAGE',[LanguageName],'INFO','MEDIUM','REGISTERED_RUNTIME_STARTABILITY_UNVERIFIED',
               NULL,NULL,NULL,
               N'Die Language Extension ist im Datenbankkatalog registriert.',
               N'Die Analyse führt keinen externen Code aus; Installation, Abhängigkeiten und Startfähigkeit bleiben daher unverifiziert.',
               N'Installations- und Betriebsnachweise der konkreten Runtime außerhalb dieses T-SQL-Moduls prüfen.'
        FROM [#ExternalRuntimeAnalysis_Languages]
        WHERE [FileName] IS NULL OR [FileMetadataStatus]<>'AVAILABLE';

        IF UPPER(COALESCE(@HostPlatform,N''))='LINUX'
            INSERT [#ExternalRuntimeAnalysis_Warnings]
            VALUES('LINUX_EXTERNAL_POOL_UNIT_CONTRACT',N'External-Pool-Statistiken werden auf Linux aus cgroups bezogen; dokumentierte Einheitenabweichungen verhindern ungeprüfte plattformübergreifende Vergleiche.',N'Rohwerte und Deltas bleiben sichtbar, werden aber nicht pauschal als KB-, I/O- oder Millisekunden-SLA klassifiziert.');
        INSERT [#ExternalRuntimeAnalysis_Warnings]
        VALUES('EXECUTION_STATS_SCOPE',N'sys.dm_external_script_execution_stats erfasst registrierte Featurefunktionen und keine allgemeine Historie beliebiger Scripts.',N'Ein fehlender Zähler beweist weder fehlende Runtimeaktivität noch fehlerfreie Ausführung.');

        UPDATE [ds]
        SET [SourceFailureCount]=(SELECT COUNT(*) FROM [#ExternalRuntimeAnalysis_SourceStatus] [ss] WHERE [ss].[DatabaseName]=[ds].[DatabaseName] AND [ss].[IsPartial]=1),
            [IsPartial]=CONVERT(bit,CASE WHEN EXISTS(SELECT 1 FROM [#ExternalRuntimeAnalysis_SourceStatus] [ss] WHERE [ss].[DatabaseName]=[ds].[DatabaseName] AND [ss].[IsPartial]=1) THEN 1 ELSE 0 END),
            [StatusCode]=CASE WHEN EXISTS(SELECT 1 FROM [#ExternalRuntimeAnalysis_SourceStatus] [ss] WHERE [ss].[DatabaseName]=[ds].[DatabaseName] AND [ss].[IsPartial]=1) THEN 'AVAILABLE_LIMITED'
                              WHEN [LanguageCount]+[LibraryCount]=0 THEN 'NOT_APPLICABLE_VISIBLE_SCOPE' ELSE 'AVAILABLE' END
        FROM [#ExternalRuntimeAnalysis_DatabaseStatus] [ds]
        WHERE [StatusCode]='PENDING';

        IF @StatusCode='AVAILABLE'
        BEGIN
            IF EXISTS(SELECT 1 FROM [#ExternalRuntimeAnalysis_SourceStatus] WHERE [IsPartial]=1)
                SELECT @StatusCode='AVAILABLE_LIMITED',@IsPartial=1;
            ELSE IF EXISTS(SELECT 1 FROM [#ExternalRuntimeAnalysis_Findings] WHERE [Severity]='WARN')
                SET @StatusCode='AVAILABLE_WITH_FINDING';
            ELSE IF EXISTS(SELECT 1 FROM [#ExternalRuntimeAnalysis_Configuration] WHERE COALESCE([ExternalScriptsValueInUse],0)=0)
                SET @StatusCode=CASE WHEN EXISTS(SELECT 1 FROM [#ExternalRuntimeAnalysis_Languages]) OR EXISTS(SELECT 1 FROM [#ExternalRuntimeAnalysis_Libraries]) OR EXISTS(SELECT 1 FROM [#ExternalRuntimeAnalysis_ExecutionStats]) THEN 'FEATURE_DISABLED' ELSE 'NOT_APPLICABLE' END;
        END;

        SELECT @ErrorNumber=COALESCE(@ErrorNumber,MIN([ErrorNumber])),@ErrorMessage=COALESCE(@ErrorMessage,MIN([ErrorMessage]))
        FROM [#ExternalRuntimeAnalysis_SourceStatus] WHERE [IsPartial]=1;

        IF @MaxZeilen>0 AND
           (
               (SELECT COUNT_BIG(*) FROM [#ExternalRuntimeAnalysis_Findings] WHERE @NurProblematisch=0 OR [Severity]='WARN')>@Limit
            OR (SELECT COUNT_BIG(*) FROM [#ExternalRuntimeAnalysis_Languages])>@Limit
            OR (SELECT COUNT_BIG(*) FROM [#ExternalRuntimeAnalysis_Libraries])>@Limit
            OR (SELECT COUNT_BIG(*) FROM [#ExternalRuntimeAnalysis_ActiveRequests])>@Limit
            OR (SELECT COUNT_BIG(*) FROM [#ExternalRuntimeAnalysis_ExecutionStats])>@Limit
            OR (SELECT COUNT_BIG(*) FROM [#ExternalRuntimeAnalysis_PerformanceCounters])>@Limit
           )
        BEGIN
            INSERT [#ExternalRuntimeAnalysis_Warnings]
            VALUES('RESULTSET_TRUNCATED',N'Mindestens ein fachliches Resultset enthält mehr Zeilen als @MaxZeilen und wird erst nach globaler Sortierung begrenzt.',N'@MaxZeilen=0 liefert alle materialisierten Zeilen.');
            IF @PrintMeldungen=1 RAISERROR(N'RESULTSET_TRUNCATED: Verwenden Sie @MaxZeilen=0 oder einen höheren Wert für die vollständige Ausgabe.',10,1) WITH NOWAIT;
        END;

        IF @JsonErzeugen=1
        BEGIN
            SELECT @Json=(
                SELECT
                    JSON_QUERY((SELECT N'USP_ExternalRuntimeAnalysis' AS [module],@Now AS [collectedAtUtc],@MeasurementStartUtc AS [measurementStartUtc],@MeasurementEndUtc AS [measurementEndUtc],@StatusCode AS [statusCode],@IsPartial AS [isPartial],@ErrorNumber AS [errorNumber],@ErrorMessage AS [errorMessage] FOR JSON PATH,WITHOUT_ARRAY_WRAPPER)) AS [meta],
                    JSON_QUERY(COALESCE((SELECT * FROM [#ExternalRuntimeAnalysis_Configuration] FOR JSON PATH),N'[]')) AS [configuration],
                    JSON_QUERY(COALESCE((SELECT * FROM [#ExternalRuntimeAnalysis_DatabaseStatus] ORDER BY [DatabaseName] FOR JSON PATH),N'[]')) AS [databaseStatus],
                    JSON_QUERY(COALESCE((SELECT * FROM [#ExternalRuntimeAnalysis_SourceStatus] ORDER BY [DatabaseName],[SourceCode],[ReadAtUtc] FOR JSON PATH),N'[]')) AS [sourceStatus],
                    JSON_QUERY(COALESCE((SELECT TOP(@Limit) * FROM [#ExternalRuntimeAnalysis_Findings] WHERE @NurProblematisch=0 OR [Severity]='WARN' ORDER BY CASE [Severity] WHEN 'WARN' THEN 1 ELSE 2 END,[FindingOrdinal] FOR JSON PATH),N'[]')) AS [findings],
                    JSON_QUERY(COALESCE((SELECT TOP(@Limit) * FROM [#ExternalRuntimeAnalysis_Languages] ORDER BY [DatabaseName],[LanguageName],[FileName] FOR JSON PATH),N'[]')) AS [languages],
                    JSON_QUERY(COALESCE((SELECT TOP(@Limit) * FROM [#ExternalRuntimeAnalysis_Libraries] ORDER BY [DatabaseName],[LanguageName],[LibraryName] FOR JSON PATH),N'[]')) AS [libraries],
                    JSON_QUERY(COALESCE((SELECT TOP(@Limit) * FROM [#ExternalRuntimeAnalysis_ActiveRequests] ORDER BY [WaitTimeMs] DESC,[SessionId] FOR JSON PATH),N'[]')) AS [activeRequests],
                    JSON_QUERY(COALESCE((SELECT TOP(@Limit) * FROM [#ExternalRuntimeAnalysis_ExternalPools] ORDER BY [ActiveProcessesCount] DESC,[PoolName] FOR JSON PATH),N'[]')) AS [externalPools],
                    JSON_QUERY(COALESCE((SELECT TOP(@Limit) * FROM [#ExternalRuntimeAnalysis_ExecutionStats] ORDER BY [LanguageName],[CounterName] FOR JSON PATH),N'[]')) AS [executionStats],
                    JSON_QUERY(COALESCE((SELECT TOP(@Limit) * FROM [#ExternalRuntimeAnalysis_PerformanceCounters] ORDER BY [CounterName],[InstanceName] FOR JSON PATH),N'[]')) AS [performanceCounters],
                    JSON_QUERY(COALESCE((SELECT * FROM [#ExternalRuntimeAnalysis_Warnings] ORDER BY [WarningCode] FOR JSON PATH),N'[]')) AS [warnings]
                FOR JSON PATH,WITHOUT_ARRAY_WRAPPER);
        END;

        IF @OutputMode='RAW'
        BEGIN
            SELECT N'USP_ExternalRuntimeAnalysis' AS [Module],@Now AS [CollectedAtUtc],@MeasurementStartUtc AS [MeasurementStartUtc],@MeasurementEndUtc AS [MeasurementEndUtc],@StatusCode AS [StatusCode],@IsPartial AS [IsPartial],@ErrorNumber AS [ErrorNumber],@ErrorMessage AS [ErrorMessage],N'Read-only External-Runtime-Evidenz; keine Scripttexte, Parameter, Environment Variables, Binärinhalte oder Testausführung.' AS [EvidenceLimit];
            SELECT * FROM [#ExternalRuntimeAnalysis_Configuration];
            SELECT * FROM [#ExternalRuntimeAnalysis_DatabaseStatus] ORDER BY [DatabaseName];
            SELECT * FROM [#ExternalRuntimeAnalysis_SourceStatus] ORDER BY [DatabaseName],[SourceCode],[ReadAtUtc];
            SELECT TOP(@Limit) * FROM [#ExternalRuntimeAnalysis_Findings] WHERE @NurProblematisch=0 OR [Severity]='WARN' ORDER BY CASE [Severity] WHEN 'WARN' THEN 1 ELSE 2 END,[FindingOrdinal];
            SELECT TOP(@Limit) * FROM [#ExternalRuntimeAnalysis_Languages] ORDER BY [DatabaseName],[LanguageName],[FileName];
            SELECT TOP(@Limit) * FROM [#ExternalRuntimeAnalysis_Libraries] ORDER BY [DatabaseName],[LanguageName],[LibraryName];
            SELECT TOP(@Limit) * FROM [#ExternalRuntimeAnalysis_ActiveRequests] ORDER BY [WaitTimeMs] DESC,[SessionId];
            SELECT TOP(@Limit) * FROM [#ExternalRuntimeAnalysis_ExternalPools] ORDER BY [ActiveProcessesCount] DESC,[PoolName];
            SELECT TOP(@Limit) * FROM [#ExternalRuntimeAnalysis_ExecutionStats] ORDER BY [LanguageName],[CounterName];
            SELECT TOP(@Limit) * FROM [#ExternalRuntimeAnalysis_PerformanceCounters] ORDER BY [CounterName],[InstanceName];
            SELECT * FROM [#ExternalRuntimeAnalysis_Warnings] ORDER BY [WarningCode];
        END;
    END TRY
    BEGIN CATCH
        SELECT @StatusCode=CASE WHEN ERROR_NUMBER()=1222 THEN 'LOCK_TIMEOUT' ELSE 'ERROR_HANDLED' END,
               @IsPartial=1,@ErrorNumber=ERROR_NUMBER(),@ErrorMessage=ERROR_MESSAGE();
    END CATCH;

    SET @LockTimeoutSql=N'SET LOCK_TIMEOUT '+CONVERT(nvarchar(20),@OriginalLockTimeout)+N';';
    EXEC [sys].[sp_executesql] @LockTimeoutSql;

    IF @PrintMeldungen=1 AND @StatusCode NOT IN('AVAILABLE','NOT_APPLICABLE')
    BEGIN
        SET @PrintMessage=LEFT(CONCAT(N'USP_ExternalRuntimeAnalysis: ',@StatusCode,N'. ',COALESCE(@ErrorMessage,N'Siehe strukturierte Quellenstatus.')),2048);
        RAISERROR(N'%s',10,1,@PrintMessage) WITH NOWAIT;
    END;

    SELECT @StatusCodeOut=@StatusCode,@IsPartialOut=@IsPartial,@ErrorNumberOut=@ErrorNumber,@ErrorMessageOut=@ErrorMessage;
    IF @ConsoleResultRequested=1
        EXEC [monitor].[InternalEmitConsoleResult]
              @SourceTable=N'#ExternalRuntimeAnalysis_Findings'
            , @ResultLabel=N'ExternalRuntimeAnalysis'
            , @EmptyMessage=N'Keine External-Runtime-Findings im gewählten Scope';
    IF @TableResultRequested=1
        EXEC [monitor].[InternalWriteResultTable]
              @SourceTable=N'#ExternalRuntimeAnalysis_Findings'
            , @TargetTable=@TableTarget
            , @ThrowOnError=1;
END;
GO
-- END SOURCE: Code/09_VersionAdaptive/090_USP_ExternalRuntimeAnalysis.sql

-- BEGIN SOURCE: Code/09_VersionAdaptive/100_USP_ClrAnalysis.sql
/*
===============================================================================
Objekt       : monitor.USP_ClrAnalysis
Version      : 1.0.0
Stand        : 2026-07-22
Typ          : Stored Procedure
Zweck        : Analysiert SQL-CLR-Konfiguration, benutzerdefinierte Assemblies,
               Module, Abhängigkeiten, Host Properties, AppDomains, geladene
               Assemblies, CLR Tasks, aktive Requests, Speicher und Counter.
SQL-Version  : SQL Server 2019 oder neuer.
Datenquellen : sys.configurations, sys.databases, sys.assemblies,
               sys.assembly_modules, sys.assembly_references,
               sys.assembly_types, sys.dm_clr_properties,
               sys.dm_clr_appdomains, sys.dm_clr_loaded_assemblies,
               sys.dm_clr_tasks, sys.dm_os_tasks, sys.dm_exec_requests,
               sys.dm_exec_sessions, sys.dm_os_memory_clerks,
               sys.dm_os_performance_counters und optional
               sys.trusted_assemblies.
Datenschutz  : Liest keine Assembly-Binärinhalte, Hashes, Moduldefinitionen,
               SQL-Texte oder Pläne. Principal- und Sitzungskontext sind
               getrennte Opt-ins.
Methodik     : Jede Server-DMV wird einmal je Messpunkt materialisiert.
               Geladene Assemblies werden über AppDomain-Datenbank und
               assembly_id vorsichtig mit sichtbaren Katalogzeilen verbunden.
Grenzen      : assembly_id ist nur innerhalb einer Datenbank eindeutig. Ohne
               Binärhash ist keine exakte Zuordnung zu trusted assemblies
               möglich; die Analyse behauptet daher keinen Trustnachweis.
Kosten       : MEDIUM; Modul- und Dependency-Kataloge skalieren mit der Zahl
               sichtbarer CLR-Objekte. Sampling wartet höchstens 60 Sekunden.
Nebenwirkung : Rein lesend; aktiviert CLR nicht und lädt keine Assembly.
===============================================================================
*/
CREATE OR ALTER PROCEDURE [monitor].[USP_ClrAnalysis]
      @DatabaseNames                    nvarchar(max)  = NULL
    , @SystemdatenbankenEinbeziehen     bit            = 0
    , @DatabaseNamePattern              nvarchar(4000) = NULL
    , @HighImpactConfirmed              bit            = 0
    , @AssemblyNames                    nvarchar(max)  = NULL
    , @AssemblyNamePattern              nvarchar(4000) = NULL
    , @SampleSeconds                    tinyint         = 0
    , @MitModulzuordnung                bit             = 1
    , @MitBerechtigungsanalyse          bit             = 0
    , @MitSitzungskontext               bit             = 0
    , @NurProblematisch                 bit             = 0
    , @MaxZeilen                        int             = 100
    , @LockTimeoutMs                    int             = 0
    , @ResultSetArt                     varchar(16)     = 'CONSOLE'
    , @ResultTablesJson                 nvarchar(max)   = NULL
    , @JsonErzeugen                     bit             = 0
    , @Json                             nvarchar(max)   = NULL OUTPUT
    , @PrintMeldungen                   bit             = 1
    , @Hilfe                            bit             = 0
    , @StatusCodeOut                    varchar(40)     = NULL OUTPUT
    , @IsPartialOut                     bit             = NULL OUTPUT
    , @ErrorNumberOut                   int             = NULL OUTPUT
    , @ErrorMessageOut                  nvarchar(2048)  = NULL OUTPUT
AS
BEGIN
    SET NOCOUNT ON;
    SET @Json=NULL;

    DECLARE @OriginalLockTimeout int=@@LOCK_TIMEOUT;
    DECLARE @LockTimeoutSql nvarchar(100);
    DECLARE @Now datetime2(3)=SYSUTCDATETIME();
    DECLARE @MeasurementStartUtc datetime2(3)=NULL,@MeasurementEndUtc datetime2(3)=NULL;
    DECLARE @Major int=TRY_CONVERT(int,SERVERPROPERTY(N'ProductMajorVersion'));
    DECLARE @HostPlatform nvarchar(60)=TRY_CONVERT(nvarchar(60),SERVERPROPERTY(N'HostPlatform'));
    DECLARE @OutputModeRequested varchar(16)=UPPER(LTRIM(RTRIM(COALESCE(@ResultSetArt,''))));
    DECLARE @OutputMode varchar(16)=@OutputModeRequested;
    DECLARE @TableResultRequested bit=CONVERT(bit,CASE WHEN @OutputModeRequested='TABLE' THEN 1 ELSE 0 END);
    DECLARE @ConsoleResultRequested bit=CONVERT(bit,CASE WHEN @OutputModeRequested='CONSOLE' THEN 1 ELSE 0 END);
    DECLARE @TableTarget sysname=NULL;
    DECLARE @StatusCode varchar(40)='AVAILABLE',@IsPartial bit=0;
    DECLARE @ErrorNumber int=NULL,@ErrorMessage nvarchar(2048)=NULL,@PrintMessage nvarchar(2048)=NULL;
    DECLARE @Limit bigint=CASE WHEN @MaxZeilen IS NULL OR @MaxZeilen=0
                               THEN CONVERT(bigint,9223372036854775807)
                               ELSE CONVERT(bigint,@MaxZeilen) END;
    DECLARE @RequiredPerformancePermission nvarchar(128)=CASE WHEN COALESCE(@Major,0)>=16 THEN N'VIEW SERVER PERFORMANCE STATE' ELSE N'VIEW SERVER STATE' END;

    IF @Hilfe=1
    BEGIN
        PRINT N'monitor.USP_ClrAnalysis';
        PRINT N'Die Procedure analysiert ausschließlich SQL CLR; die out-of-process C# Language Extension gehört zu USP_ExternalRuntimeAnalysis.';
        PRINT N'@MitModulzuordnung=1 liest sichtbare CLR-Module, Assemblyreferenzen und CLR-Typen ohne Moduldefinitionen oder Binärinhalte.';
        PRINT N'@MitBerechtigungsanalyse=1 ergänzt sichtbare Owner- und EXECUTE-AS-Principals sowie die Anzahl trusted assemblies; ein Hashabgleich bleibt ausgeschlossen.';
        PRINT N'@MitSitzungskontext=1 ergänzt Login, Host und Clientprogramm für aktive Managed-Code-Requests.';
        PRINT N'@SampleSeconds=0 liefert Counter-Momentaufnahmen; Werte von 1 bis 60 erzeugen ein Counter-Deltafenster.';
        PRINT N'@ResultSetArt=CONSOLE|RAW|TABLE|NONE; TABLE schreibt das primäre Resultset findings über @ResultTablesJson.';
        RETURN;
    END;

    IF @OutputModeRequested NOT IN('CONSOLE','RAW','TABLE','NONE')
        SELECT @StatusCode='INVALID_PARAMETER',@IsPartial=1,@ErrorMessage=N'@ResultSetArt muss CONSOLE, RAW, TABLE oder NONE sein.';
    IF @TableResultRequested=0 AND NULLIF(LTRIM(RTRIM(COALESCE(@ResultTablesJson,N''))),N'') IS NOT NULL
        THROW 51011,N'@ResultTablesJson ist ausschließlich mit @ResultSetArt=TABLE zulässig.',1;
    IF @TableResultRequested=1
        EXEC [monitor].[InternalPrepareSingleResultTable]
              @ResultTablesJson=@ResultTablesJson
            , @ResultName=N'findings'
            , @TargetTable=@TableTarget OUTPUT
            , @ThrowOnError=1;
    IF @TableResultRequested=1 OR @ConsoleResultRequested=1 SET @OutputMode='NONE';

    IF @StatusCode='AVAILABLE'
       AND (@SystemdatenbankenEinbeziehen IS NULL OR @HighImpactConfirmed IS NULL
            OR @MitModulzuordnung IS NULL OR @MitBerechtigungsanalyse IS NULL
            OR @MitSitzungskontext IS NULL OR @NurProblematisch IS NULL
            OR @JsonErzeugen IS NULL OR @PrintMeldungen IS NULL
            OR @SampleSeconds IS NULL OR @SampleSeconds>60
            OR @MaxZeilen IS NULL OR @MaxZeilen<0
            OR @LockTimeoutMs IS NULL OR @LockTimeoutMs NOT BETWEEN 0 AND 60000)
        SELECT @StatusCode='INVALID_PARAMETER',@IsPartial=1,@ErrorMessage=N'Ungültiger Bit-, Sample-, Zeilen- oder Lock-Timeout-Parameter.';

    CREATE TABLE [#ClrAnalysis_DatabaseCandidates]
    (
          [DatabaseId] int NOT NULL PRIMARY KEY
        , [DatabaseName] sysname NOT NULL
        , [StateDesc] nvarchar(60) NULL
        , [UserAccessDesc] nvarchar(60) NULL
        , [IsReadOnly] bit NULL
        , [CompatibilityLevel] tinyint NULL
        , [CollationName] sysname NULL
        , [RecoveryModelDesc] nvarchar(60) NULL
        , [IsSystemDatabase] bit NULL
        , [RequestedOrdinal] int NULL
    );
    CREATE TABLE [#ClrAnalysis_DatabaseCandidateWarnings]
    (
          [RequestedName] sysname NULL
        , [StatusCode] varchar(40) NOT NULL
        , [ErrorMessage] nvarchar(2048) NULL
    );
    CREATE TABLE [#ClrAnalysis_AssemblyFilters]
    (
          [ItemOrdinal] int NOT NULL
        , [AssemblyName] sysname COLLATE SQL_Latin1_General_CP1_CS_AS NOT NULL
        , PRIMARY KEY ([AssemblyName])
    );
    CREATE TABLE [#ClrAnalysis_Configuration]
    (
          [CollectedAtUtc] datetime2(3) NOT NULL
        , [ProductMajorVersion] int NULL
        , [HostPlatform] nvarchar(60) NULL
        , [ClrEnabledConfiguredValue] int NULL
        , [ClrEnabledValueInUse] int NULL
        , [ClrStrictSecurityConfiguredValue] int NULL
        , [ClrStrictSecurityValueInUse] int NULL
        , [LightweightPoolingConfiguredValue] int NULL
        , [LightweightPoolingValueInUse] int NULL
        , [TrustedAssemblyCount] bigint NULL
        , [TrustedAssemblyStatus] varchar(40) NOT NULL
        , [RequiredPerformancePermission] nvarchar(128) NOT NULL
        , [EvidenceLimit] nvarchar(1000) NOT NULL
    );
    CREATE TABLE [#ClrAnalysis_DatabaseStatus]
    (
          [DatabaseId] int NULL
        , [DatabaseName] sysname NULL
        , [StatusCode] varchar(40) NOT NULL
        , [IsPartial] bit NOT NULL
        , [IsTrustworthyOn] bit NULL
        , [AssemblyCount] bigint NOT NULL
        , [HighPermissionAssemblyCount] bigint NOT NULL
        , [ModuleCount] bigint NOT NULL
        , [SourceFailureCount] int NOT NULL
        , [ErrorNumber] int NULL
        , [ErrorMessage] nvarchar(2048) NULL
        , [EvidenceLimit] nvarchar(1000) NOT NULL
    );
    CREATE TABLE [#ClrAnalysis_SourceStatus]
    (
          [DatabaseName] sysname NULL
        , [SourceCode] varchar(80) NOT NULL
        , [StatusCode] varchar(40) NOT NULL
        , [IsPartial] bit NOT NULL
        , [RowCount] bigint NOT NULL
        , [RequiredPermission] nvarchar(256) NULL
        , [ReadAtUtc] datetime2(3) NOT NULL
        , [ErrorNumber] int NULL
        , [ErrorMessage] nvarchar(2048) NULL
        , [EvidenceLimit] nvarchar(1000) NOT NULL
    );
    CREATE TABLE [#ClrAnalysis_Assemblies]
    (
          [DatabaseId] int NOT NULL
        , [DatabaseName] sysname NOT NULL
        , [AssemblyId] int NOT NULL
        , [AssemblyName] sysname NOT NULL
        , [ClrName] nvarchar(4000) NULL
        , [PermissionSetDesc] nvarchar(60) NULL
        , [IsVisible] bit NULL
        , [CreateDate] datetime NULL
        , [ModifyDate] datetime NULL
        , [OwnerName] sysname NULL
        , [IsLoaded] bit NOT NULL
        , [LastVisibleLoadTime] datetime NULL
        , [TrustVerificationStatus] varchar(40) NOT NULL
        , [EvidenceLimit] nvarchar(1000) NOT NULL
    );
    CREATE TABLE [#ClrAnalysis_AssemblyModules]
    (
          [DatabaseName] sysname NOT NULL
        , [SchemaName] sysname NOT NULL
        , [ObjectName] sysname NOT NULL
        , [ObjectType] char(2) NOT NULL
        , [ObjectTypeDesc] nvarchar(60) NULL
        , [AssemblyName] sysname NOT NULL
        , [AssemblyClass] sysname NULL
        , [AssemblyMethod] sysname NULL
        , [ExecuteAsPrincipal] sysname NULL
        , [EvidenceLimit] nvarchar(1000) NOT NULL
    );
    CREATE TABLE [#ClrAnalysis_AssemblyDependencies]
    (
          [DatabaseName] sysname NOT NULL
        , [DependencyKind] varchar(40) NOT NULL
        , [AssemblyName] sysname NOT NULL
        , [ReferencedAssemblyName] sysname NULL
        , [SchemaName] sysname NULL
        , [TypeName] sysname NULL
        , [AssemblyClass] sysname NULL
        , [EvidenceLimit] nvarchar(1000) NOT NULL
    );
    CREATE TABLE [#ClrAnalysis_Properties]
    (
          [PropertyName] nvarchar(128) NOT NULL
        , [PropertyValue] nvarchar(128) NULL
        , [EvidenceLimit] nvarchar(1000) NOT NULL
    );
    CREATE TABLE [#ClrAnalysis_AppDomains]
    (
          [AppDomainAddress] varbinary(8) NOT NULL
        , [AppDomainId] int NULL
        , [CreationTime] datetime NULL
        , [DatabaseId] int NULL
        , [DatabaseName] sysname NULL
        , [State] nvarchar(128) NULL
        , [StrongRefCount] int NULL
        , [WeakRefCount] int NULL
        , [Cost] int NULL
        , [Value] int NULL
        , [TotalProcessorTimeMs] bigint NULL
        , [TotalAllocatedMemoryKb] bigint NULL
        , [SurvivedMemoryKb] bigint NULL
        , [EvidenceLimit] nvarchar(1000) NOT NULL
    );
    CREATE TABLE [#ClrAnalysis_LoadedAssemblies]
    (
          [AppDomainAddress] varbinary(8) NOT NULL
        , [AssemblyId] int NOT NULL
        , [LoadTime] datetime NULL
        , [DatabaseId] int NULL
        , [DatabaseName] sysname NULL
        , [AppDomainId] int NULL
        , [AssemblyName] sysname NULL
        , [MappingStatus] varchar(40) NOT NULL
        , [EvidenceLimit] nvarchar(1000) NOT NULL
    );
    CREATE TABLE [#ClrAnalysis_Tasks]
    (
          [TaskAddress] varbinary(8) NOT NULL
        , [SosTaskAddress] varbinary(8) NULL
        , [AppDomainAddress] varbinary(8) NULL
        , [DatabaseName] sysname NULL
        , [AppDomainId] int NULL
        , [TaskState] nvarchar(128) NULL
        , [AbortState] nvarchar(128) NULL
        , [TaskType] nvarchar(128) NULL
        , [AffinityCount] int NULL
        , [ForcedYieldCount] int NULL
        , [SessionId] smallint NULL
        , [RequestId] int NULL
        , [MappingStatus] varchar(40) NOT NULL
        , [EvidenceLimit] nvarchar(1000) NOT NULL
    );
    CREATE TABLE [#ClrAnalysis_ActiveRequests]
    (
          [SessionId] smallint NOT NULL
        , [RequestId] int NOT NULL
        , [DatabaseName] sysname NULL
        , [RequestStatus] nvarchar(30) NULL
        , [Command] nvarchar(32) NULL
        , [BlockingSessionId] smallint NULL
        , [WaitType] nvarchar(60) NULL
        , [WaitTimeMs] int NULL
        , [ElapsedTimeMs] int NULL
        , [CpuTimeMs] int NULL
        , [Reads] bigint NULL
        , [LogicalReads] bigint NULL
        , [Writes] bigint NULL
        , [LoginName] sysname NULL
        , [HostName] nvarchar(128) NULL
        , [ProgramName] nvarchar(128) NULL
        , [EvidenceLimit] nvarchar(1000) NOT NULL
    );
    CREATE TABLE [#ClrAnalysis_Memory]
    (
          [MemoryClerkType] nvarchar(60) NOT NULL
        , [ClerkCount] bigint NOT NULL
        , [PagesKb] bigint NULL
        , [VirtualMemoryReservedKb] bigint NULL
        , [VirtualMemoryCommittedKb] bigint NULL
        , [SharedMemoryReservedKb] bigint NULL
        , [SharedMemoryCommittedKb] bigint NULL
        , [EvidenceLimit] nvarchar(1000) NOT NULL
    );
    CREATE TABLE [#ClrAnalysis_CounterSamples]
    (
          [SamplePoint] char(2) NOT NULL
        , [ReadAtUtc] datetime2(3) NOT NULL
        , [CounterName] nvarchar(128) NOT NULL
        , [InstanceName] nvarchar(128) NOT NULL
        , [CounterType] int NOT NULL
        , [CounterValue] bigint NOT NULL
    );
    CREATE TABLE [#ClrAnalysis_PerformanceCounters]
    (
          [CounterName] nvarchar(128) NOT NULL
        , [InstanceName] nvarchar(128) NOT NULL
        , [CounterType] int NOT NULL
        , [CounterValue] bigint NOT NULL
        , [Interpretation] varchar(40) NOT NULL
        , [MetricValue] decimal(38,6) NULL
        , [MetricUnit] varchar(40) NOT NULL
        , [FindingCode] varchar(80) NOT NULL
        , [EvidenceLimit] nvarchar(1000) NOT NULL
    );
    CREATE TABLE [#ClrAnalysis_Findings]
    (
          [FindingOrdinal] bigint IDENTITY(1,1) NOT NULL PRIMARY KEY
        , [DatabaseName] sysname NULL
        , [ObjectType] varchar(40) NOT NULL
        , [ObjectName] nvarchar(512) NULL
        , [Severity] varchar(16) NOT NULL
        , [Confidence] varchar(16) NOT NULL
        , [FindingCode] varchar(120) NOT NULL
        , [MetricName] varchar(80) NULL
        , [MetricValue] decimal(38,4) NULL
        , [ThresholdValue] decimal(38,4) NULL
        , [Evidence] nvarchar(1000) NOT NULL
        , [EvidenceLimit] nvarchar(1000) NOT NULL
        , [RecommendedNextCheck] nvarchar(1000) NOT NULL
    );
    CREATE TABLE [#ClrAnalysis_Warnings]
    (
          [WarningCode] varchar(120) NOT NULL
        , [Detail] nvarchar(1000) NOT NULL
        , [EvidenceLimit] nvarchar(1000) NOT NULL
    );

    BEGIN TRY
        DECLARE @AssemblyPatternMode varchar(8),@AssemblyPatternValue nvarchar(4000),@AssemblyRegexFlags varchar(8),@AssemblyPatternValid bit;
        SELECT @AssemblyPatternMode=[PatternMode],@AssemblyPatternValue=[PatternValue],
               @AssemblyRegexFlags=[RegexFlags],@AssemblyPatternValid=[IsValid]
        FROM [monitor].[TVF_ParsePattern](@AssemblyNamePattern);
        IF @StatusCode='AVAILABLE'
           AND (@AssemblyPatternValid=0 OR (@AssemblyNames IS NOT NULL AND @AssemblyNamePattern IS NOT NULL))
            SELECT @StatusCode='INVALID_PARAMETER',@IsPartial=1,@ErrorMessage=N'@AssemblyNamePattern ist ungültig oder wurde zusammen mit @AssemblyNames angegeben.';
        IF @StatusCode='AVAILABLE' AND @AssemblyPatternMode IN('REGEX','REGEXI')
           AND
           (
               COALESCE(@Major,0)<17
               OR NOT EXISTS
                  (
                      SELECT 1
                      FROM [master].[sys].[databases] [d] WITH (NOLOCK)
                      WHERE [d].[database_id]=DB_ID() AND [d].[compatibility_level]>=170
                  )
           )
            SELECT @StatusCode='UNAVAILABLE_FEATURE',@IsPartial=1,@ErrorMessage=N'Regex-Pattern benötigen SQL Server 2025 und Compatibility Level 170 in der Frameworkdatenbank.';

        IF @StatusCode='AVAILABLE'
        BEGIN
            INSERT [#ClrAnalysis_AssemblyFilters]([ItemOrdinal],[AssemblyName])
            SELECT [ItemOrdinal],[NameValue]
            FROM [monitor].[TVF_ParseSqlNameList](@AssemblyNames)
            WHERE [IsValid]=1;
            IF EXISTS(SELECT 1 FROM [monitor].[TVF_ParseSqlNameList](@AssemblyNames) WHERE [IsValid]=0)
                SELECT @StatusCode='INVALID_PARAMETER',@IsPartial=1,@ErrorMessage=N'@AssemblyNames enthält mindestens einen ungültigen SQL-Namen.';
        END;

        IF @StatusCode='AVAILABLE' AND @MitBerechtigungsanalyse=1
        BEGIN
            EXEC [monitor].[InternalCheckAnalysisPath]
                  @AnalysisClass='CATALOG_DEEP'
                , @HighImpactConfirmed=@HighImpactConfirmed
                , @StatusCode=@StatusCode OUTPUT
                , @ErrorMessage=@ErrorMessage OUTPUT;
            IF @StatusCode<>'AVAILABLE' SET @IsPartial=1;
        END;

        DECLARE @CrossDatabaseRequested bit=0;
        IF @StatusCode='AVAILABLE'
        BEGIN
            EXEC [monitor].[USP_PrepareDatabaseCandidates]
                  @DatabaseNames=@DatabaseNames
                , @SystemdatenbankenEinbeziehen=@SystemdatenbankenEinbeziehen
                , @DatabaseNamePattern=@DatabaseNamePattern
                , @HighImpactConfirmed=@HighImpactConfirmed
                , @AnalysisClass='CLR_CURRENT'
                , @StatusCode=@StatusCode OUTPUT
                , @ErrorMessage=@ErrorMessage OUTPUT
                , @CrossDatabaseRequested=@CrossDatabaseRequested OUTPUT
                , @CandidateTable=N'#ClrAnalysis_DatabaseCandidates'
                , @WarningTable=N'#ClrAnalysis_DatabaseCandidateWarnings';
            IF @StatusCode<>'AVAILABLE' SET @IsPartial=1;
        END;

        INSERT [#ClrAnalysis_DatabaseStatus]
        ([DatabaseId],[DatabaseName],[StatusCode],[IsPartial],[IsTrustworthyOn],[AssemblyCount],[HighPermissionAssemblyCount],[ModuleCount],[SourceFailureCount],[EvidenceLimit])
        SELECT [c].[DatabaseId],[c].[DatabaseName],'PENDING',0,[d].[is_trustworthy_on],0,0,0,0,
               N'Sichtbare Katalogmetadaten; fehlende Metadata Visibility kann Assemblies oder Module ausblenden.'
        FROM [#ClrAnalysis_DatabaseCandidates] [c]
        LEFT JOIN [sys].[databases] [d] WITH (NOLOCK) ON [d].[database_id]=[c].[DatabaseId];
        INSERT [#ClrAnalysis_DatabaseStatus]
        ([DatabaseId],[DatabaseName],[StatusCode],[IsPartial],[IsTrustworthyOn],[AssemblyCount],[HighPermissionAssemblyCount],[ModuleCount],[SourceFailureCount],[ErrorMessage],[EvidenceLimit])
        SELECT NULL,[RequestedName],[StatusCode],1,NULL,0,0,0,1,[ErrorMessage],N'Explizit angeforderte Datenbank war nicht auswertbar.'
        FROM [#ClrAnalysis_DatabaseCandidateWarnings];

        SET @LockTimeoutSql=N'SET LOCK_TIMEOUT '+CONVERT(nvarchar(20),@LockTimeoutMs)+N';';
        EXEC [sys].[sp_executesql] @LockTimeoutSql;

        IF @StatusCode='AVAILABLE'
        BEGIN
            INSERT [#ClrAnalysis_Configuration]
            ([CollectedAtUtc],[ProductMajorVersion],[HostPlatform],[ClrEnabledConfiguredValue],[ClrEnabledValueInUse],
             [ClrStrictSecurityConfiguredValue],[ClrStrictSecurityValueInUse],[LightweightPoolingConfiguredValue],
             [LightweightPoolingValueInUse],[TrustedAssemblyCount],[TrustedAssemblyStatus],[RequiredPerformancePermission],[EvidenceLimit])
            SELECT @Now,@Major,@HostPlatform,
                   MAX(CASE WHEN [name]=N'clr enabled' THEN TRY_CONVERT(int,[value]) END),
                   MAX(CASE WHEN [name]=N'clr enabled' THEN TRY_CONVERT(int,[value_in_use]) END),
                   MAX(CASE WHEN [name]=N'clr strict security' THEN TRY_CONVERT(int,[value]) END),
                   MAX(CASE WHEN [name]=N'clr strict security' THEN TRY_CONVERT(int,[value_in_use]) END),
                   MAX(CASE WHEN [name]=N'lightweight pooling' THEN TRY_CONVERT(int,[value]) END),
                   MAX(CASE WHEN [name]=N'lightweight pooling' THEN TRY_CONVERT(int,[value_in_use]) END),
                   NULL,CASE WHEN @MitBerechtigungsanalyse=1 THEN 'PENDING' ELSE 'NOT_REQUESTED' END,
                   @RequiredPerformancePermission,
                   N'Konfigurationswerte und Hostzustand sind getrennte Evidenz; CLR Host Properties beweisen nicht, dass Benutzer-CLR aktiviert ist.'
            FROM [sys].[configurations] WITH (NOLOCK)
            WHERE [name] IN(N'clr enabled',N'clr strict security',N'lightweight pooling');
            INSERT [#ClrAnalysis_SourceStatus]
            VALUES(NULL,'CLR_CONFIGURATION','AVAILABLE',0,1,N'VIEW SERVER STATE beziehungsweise Metadatensichtbarkeit',SYSUTCDATETIME(),NULL,NULL,N'Nur drei dokumentierte Konfigurationsoptionen.');

            IF @MitBerechtigungsanalyse=1
            BEGIN TRY
                DECLARE @TrustedCount bigint;
                SELECT @TrustedCount=COUNT_BIG(*) FROM [sys].[trusted_assemblies] WITH (NOLOCK);
                UPDATE [#ClrAnalysis_Configuration] SET [TrustedAssemblyCount]=@TrustedCount,[TrustedAssemblyStatus]='COUNT_AVAILABLE';
                INSERT [#ClrAnalysis_SourceStatus]
                VALUES(NULL,'TRUSTED_ASSEMBLIES','AVAILABLE',0,@TrustedCount,N'VIEW SERVER STATE beziehungsweise Metadatensichtbarkeit',SYSUTCDATETIME(),NULL,NULL,N'Nur Zeilenanzahl; Hash und description werden nicht gelesen.');
            END TRY
            BEGIN CATCH
                UPDATE [#ClrAnalysis_Configuration] SET [TrustedAssemblyStatus]='SOURCE_UNAVAILABLE';
                INSERT [#ClrAnalysis_SourceStatus]
                VALUES(NULL,'TRUSTED_ASSEMBLIES',CASE WHEN ERROR_NUMBER() IN(229,297,300,371,916) THEN 'DENIED_PERMISSION' ELSE 'ERROR_HANDLED' END,1,0,N'VIEW SERVER STATE beziehungsweise Metadatensichtbarkeit',SYSUTCDATETIME(),ERROR_NUMBER(),ERROR_MESSAGE(),N'Trust-List-Zählung isoliert fehlgeschlagen.');
            END CATCH;

            BEGIN TRY
                INSERT [#ClrAnalysis_Properties]
                SELECT [name],[value],N'Directory- und sonstige Pfadproperties sind bewusst ausgeschlossen; Hostzustand ist kein Nachweis für clr enabled.'
                FROM [sys].[dm_clr_properties] WITH (NOLOCK)
                WHERE [name] IN(N'state',N'version');
                INSERT [#ClrAnalysis_SourceStatus]
                VALUES(NULL,'CLR_PROPERTIES','AVAILABLE',0,@@ROWCOUNT,@RequiredPerformancePermission,SYSUTCDATETIME(),NULL,NULL,N'Nur state und version; Installationsverzeichnis wird nicht gelesen.');
            END TRY
            BEGIN CATCH
                INSERT [#ClrAnalysis_SourceStatus]
                VALUES(NULL,'CLR_PROPERTIES',CASE WHEN ERROR_NUMBER() IN(229,297,300,371,916) THEN 'DENIED_PERMISSION' ELSE 'ERROR_HANDLED' END,1,0,@RequiredPerformancePermission,SYSUTCDATETIME(),ERROR_NUMBER(),ERROR_MESSAGE(),N'CLR Host Properties isoliert fehlgeschlagen.');
            END CATCH;

            BEGIN TRY
                INSERT [#ClrAnalysis_AppDomains]
                SELECT [a].[appdomain_address],[a].[appdomain_id],[a].[creation_time],[a].[db_id],[d].[name],[a].[state],
                       [a].[strong_refcount],[a].[weak_refcount],[a].[cost],[a].[value],[a].[total_processor_time_ms],
                       [a].[total_allocated_memory_kb],[a].[survived_memory_kb],
                       N'AppDomain-Momentaufnahme; creation_time ist wegen Caching nicht der Zeitpunkt einer konkreten CLR-Ausführung.'
                FROM [sys].[dm_clr_appdomains] [a] WITH (NOLOCK)
                LEFT JOIN [sys].[databases] [d] WITH (NOLOCK) ON [d].[database_id]=[a].[db_id]
                WHERE EXISTS(SELECT 1 FROM [#ClrAnalysis_DatabaseCandidates] [c] WHERE [c].[DatabaseId]=[a].[db_id]);
                INSERT [#ClrAnalysis_SourceStatus]
                VALUES(NULL,'CLR_APPDOMAINS','AVAILABLE',0,@@ROWCOUNT,@RequiredPerformancePermission,SYSUTCDATETIME(),NULL,NULL,N'AppDomain-Name und User-ID werden nicht ausgegeben.');
            END TRY
            BEGIN CATCH
                INSERT [#ClrAnalysis_SourceStatus]
                VALUES(NULL,'CLR_APPDOMAINS',CASE WHEN ERROR_NUMBER() IN(229,297,300,371,916) THEN 'DENIED_PERMISSION' ELSE 'ERROR_HANDLED' END,1,0,@RequiredPerformancePermission,SYSUTCDATETIME(),ERROR_NUMBER(),ERROR_MESSAGE(),N'AppDomainquelle isoliert fehlgeschlagen.');
            END CATCH;

            BEGIN TRY
                INSERT [#ClrAnalysis_LoadedAssemblies]
                SELECT [l].[appdomain_address],[l].[assembly_id],[l].[load_time],
                       [a].[DatabaseId],[a].[DatabaseName],[a].[AppDomainId],NULL,'CATALOG_PENDING',
                       N'assembly_id wird nur zusammen mit der über AppDomain ermittelten Datenbank korreliert.'
                FROM [sys].[dm_clr_loaded_assemblies] [l] WITH (NOLOCK)
                JOIN [#ClrAnalysis_AppDomains] [a] ON [a].[AppDomainAddress]=[l].[appdomain_address];
                INSERT [#ClrAnalysis_SourceStatus]
                VALUES(NULL,'CLR_LOADED_ASSEMBLIES','AVAILABLE',0,@@ROWCOUNT,@RequiredPerformancePermission,SYSUTCDATETIME(),NULL,NULL,N'Server-DMV; Datenbankkontext wird ausschließlich über AppDomain korreliert.');
            END TRY
            BEGIN CATCH
                INSERT [#ClrAnalysis_SourceStatus]
                VALUES(NULL,'CLR_LOADED_ASSEMBLIES',CASE WHEN ERROR_NUMBER() IN(229,297,300,371,916) THEN 'DENIED_PERMISSION' ELSE 'ERROR_HANDLED' END,1,0,@RequiredPerformancePermission,SYSUTCDATETIME(),ERROR_NUMBER(),ERROR_MESSAGE(),N'Loaded-Assembly-Quelle isoliert fehlgeschlagen.');
            END CATCH;

            BEGIN TRY
                INSERT [#ClrAnalysis_Tasks]
                SELECT [t].[task_address],[t].[sos_task_address],[t].[appdomain_address],
                       [a].[DatabaseName],[a].[AppDomainId],[t].[state],[t].[abort_state],[t].[type],
                       [t].[affinity_count],[t].[forced_yield_count],[ot].[session_id],[ot].[request_id],
                       CASE WHEN [ot].[task_address] IS NULL THEN 'REQUEST_UNMAPPED' ELSE 'REQUEST_MAPPED' END,
                       N'Best-effort-Korrelation von sos_task_address zu sys.dm_os_tasks.task_address; ein CLR Task ist keine Aufrufhistorie.'
                FROM [sys].[dm_clr_tasks] [t] WITH (NOLOCK)
                LEFT JOIN [#ClrAnalysis_AppDomains] [a] ON [a].[AppDomainAddress]=[t].[appdomain_address]
                LEFT JOIN [sys].[dm_os_tasks] [ot] WITH (NOLOCK) ON [ot].[task_address]=[t].[sos_task_address]
                WHERE [a].[AppDomainAddress] IS NOT NULL;
                INSERT [#ClrAnalysis_SourceStatus]
                VALUES(NULL,'CLR_TASKS','AVAILABLE',0,@@ROWCOUNT,@RequiredPerformancePermission,SYSUTCDATETIME(),NULL,NULL,N'Adressen dienen nur der Laufzeitkorrelation; keine SQL-Texte oder Pläne.');
            END TRY
            BEGIN CATCH
                INSERT [#ClrAnalysis_SourceStatus]
                VALUES(NULL,'CLR_TASKS',CASE WHEN ERROR_NUMBER() IN(229,297,300,371,916) THEN 'DENIED_PERMISSION' ELSE 'ERROR_HANDLED' END,1,0,@RequiredPerformancePermission,SYSUTCDATETIME(),ERROR_NUMBER(),ERROR_MESSAGE(),N'CLR-Task-Quelle isoliert fehlgeschlagen.');
            END CATCH;

            BEGIN TRY
                INSERT [#ClrAnalysis_ActiveRequests]
                SELECT [r].[session_id],[r].[request_id],[d].[name],[r].[status],[r].[command],[r].[blocking_session_id],
                       [r].[wait_type],[r].[wait_time],[r].[total_elapsed_time],[r].[cpu_time],[r].[reads],[r].[logical_reads],[r].[writes],
                       CASE WHEN @MitSitzungskontext=1 THEN [s].[login_name] END,
                       CASE WHEN @MitSitzungskontext=1 THEN [s].[host_name] END,
                       CASE WHEN @MitSitzungskontext=1 THEN [s].[program_name] END,
                       N'Aktive Request-Momentaufnahme; executing_managed_code ist keine Historie und beweist keine bestimmte Assemblymethode.'
                FROM [sys].[dm_exec_requests] [r] WITH (NOLOCK)
                LEFT JOIN [sys].[dm_exec_sessions] [s] WITH (NOLOCK) ON [s].[session_id]=[r].[session_id]
                LEFT JOIN [sys].[databases] [d] WITH (NOLOCK) ON [d].[database_id]=[r].[database_id]
                WHERE [r].[executing_managed_code]=1
                  AND EXISTS(SELECT 1 FROM [#ClrAnalysis_DatabaseCandidates] [c] WHERE [c].[DatabaseId]=[r].[database_id]);
                INSERT [#ClrAnalysis_SourceStatus]
                VALUES(NULL,'MANAGED_CODE_REQUESTS','AVAILABLE',0,@@ROWCOUNT,@RequiredPerformancePermission,SYSUTCDATETIME(),NULL,NULL,N'Kein Batchtext, SQL-Text oder Plan.');
            END TRY
            BEGIN CATCH
                INSERT [#ClrAnalysis_SourceStatus]
                VALUES(NULL,'MANAGED_CODE_REQUESTS',CASE WHEN ERROR_NUMBER() IN(229,297,300,371,916) THEN 'DENIED_PERMISSION' ELSE 'ERROR_HANDLED' END,1,0,@RequiredPerformancePermission,SYSUTCDATETIME(),ERROR_NUMBER(),ERROR_MESSAGE(),N'Managed-Code-Requestquelle isoliert fehlgeschlagen.');
            END CATCH;

            BEGIN TRY
                INSERT [#ClrAnalysis_Memory]
                SELECT [type],COUNT_BIG(*),SUM(CONVERT(bigint,[pages_kb])),SUM(CONVERT(bigint,[virtual_memory_reserved_kb])),
                       SUM(CONVERT(bigint,[virtual_memory_committed_kb])),SUM(CONVERT(bigint,[shared_memory_reserved_kb])),
                       SUM(CONVERT(bigint,[shared_memory_committed_kb])),
                       N'Aktuelle Memory-Clerk-Aggregation; hohe Werte werden ohne Workloadbaseline nicht pauschal als Fehler klassifiziert.'
                FROM [sys].[dm_os_memory_clerks] WITH (NOLOCK)
                WHERE [type] IN(N'MEMORYCLERK_SQLCLR',N'MEMORYCLERK_SQLCLRASSEMBLY')
                GROUP BY [type];
                INSERT [#ClrAnalysis_SourceStatus]
                VALUES(NULL,'CLR_MEMORY_CLERKS','AVAILABLE',0,@@ROWCOUNT,@RequiredPerformancePermission,SYSUTCDATETIME(),NULL,NULL,N'Nur aggregierte CLR-Clerks; keine Speicheradressen.');
            END TRY
            BEGIN CATCH
                INSERT [#ClrAnalysis_SourceStatus]
                VALUES(NULL,'CLR_MEMORY_CLERKS',CASE WHEN ERROR_NUMBER() IN(229,297,300,371,916) THEN 'DENIED_PERMISSION' ELSE 'ERROR_HANDLED' END,1,0,@RequiredPerformancePermission,SYSUTCDATETIME(),ERROR_NUMBER(),ERROR_MESSAGE(),N'Memory-Clerk-Quelle isoliert fehlgeschlagen.');
            END CATCH;

            SET @MeasurementStartUtc=SYSUTCDATETIME();
            BEGIN TRY
                INSERT [#ClrAnalysis_CounterSamples]
                SELECT 'T1',SYSUTCDATETIME(),[counter_name],[instance_name],[cntr_type],[cntr_value]
                FROM [sys].[dm_os_performance_counters] WITH (NOLOCK)
                WHERE [object_name] LIKE N'%:CLR%';
                INSERT [#ClrAnalysis_SourceStatus]
                VALUES(NULL,'CLR_COUNTERS_T1','AVAILABLE',0,@@ROWCOUNT,@RequiredPerformancePermission,SYSUTCDATETIME(),NULL,NULL,N'Originale SQL-Server-Counterwerte; cntr_type steuert die Interpretation.');
            END TRY
            BEGIN CATCH
                INSERT [#ClrAnalysis_SourceStatus]
                VALUES(NULL,'CLR_COUNTERS_T1',CASE WHEN ERROR_NUMBER() IN(229,297,300,371,916) THEN 'DENIED_PERMISSION' ELSE 'ERROR_HANDLED' END,1,0,@RequiredPerformancePermission,SYSUTCDATETIME(),ERROR_NUMBER(),ERROR_MESSAGE(),N'CLR-Counterquelle isoliert fehlgeschlagen.');
            END CATCH;

            IF @SampleSeconds>0
            BEGIN
                DECLARE @Delay char(8)=CONVERT(char(8),DATEADD(SECOND,@SampleSeconds,CONVERT(datetime,'19000101',112)),108);
                WAITFOR DELAY @Delay;
                BEGIN TRY
                    INSERT [#ClrAnalysis_CounterSamples]
                    SELECT 'T2',SYSUTCDATETIME(),[counter_name],[instance_name],[cntr_type],[cntr_value]
                    FROM [sys].[dm_os_performance_counters] WITH (NOLOCK)
                    WHERE [object_name] LIKE N'%:CLR%';
                    INSERT [#ClrAnalysis_SourceStatus]
                    VALUES(NULL,'CLR_COUNTERS_T2','AVAILABLE',0,@@ROWCOUNT,@RequiredPerformancePermission,SYSUTCDATETIME(),NULL,NULL,N'Zweiter Messpunkt desselben Samplefensters.');
                END TRY
                BEGIN CATCH
                    INSERT [#ClrAnalysis_SourceStatus]
                    VALUES(NULL,'CLR_COUNTERS_T2',CASE WHEN ERROR_NUMBER() IN(229,297,300,371,916) THEN 'DENIED_PERMISSION' ELSE 'ERROR_HANDLED' END,1,0,@RequiredPerformancePermission,SYSUTCDATETIME(),ERROR_NUMBER(),ERROR_MESSAGE(),N'Zweiter CLR-Countermesspunkt isoliert fehlgeschlagen.');
                END CATCH;
            END;
            SET @MeasurementEndUtc=SYSUTCDATETIME();
        END;

        DECLARE @AssemblyPredicate nvarchar(max)=
            N' AND (NOT EXISTS(SELECT 1 FROM [#ClrAnalysis_AssemblyFilters]) OR EXISTS(SELECT 1 FROM [#ClrAnalysis_AssemblyFilters] [f] WHERE [f].[AssemblyName]=[a].[name] COLLATE SQL_Latin1_General_CP1_CS_AS))';
        IF @AssemblyPatternMode='LIKE'
            SET @AssemblyPredicate+=N' AND [a].[name] COLLATE SQL_Latin1_General_CP1_CS_AS LIKE @pPattern COLLATE SQL_Latin1_General_CP1_CS_AS';
        IF @AssemblyPatternMode IN('REGEX','REGEXI')
            SET @AssemblyPredicate+=N' AND REGEXP_LIKE([a].[name],@pPattern,@pRegexFlags)';

        DECLARE @Db sysname,@DbId int,@CompatibilityLevel int,@Sql nvarchar(max),@Rows bigint;
        IF @StatusCode='AVAILABLE'
        BEGIN
            DECLARE [DatabaseCursor] CURSOR LOCAL FAST_FORWARD FOR
                SELECT [DatabaseName],[DatabaseId],[CompatibilityLevel]
                FROM [#ClrAnalysis_DatabaseCandidates]
                ORDER BY COALESCE([RequestedOrdinal],[DatabaseId]),[DatabaseId];
            OPEN [DatabaseCursor]; FETCH NEXT FROM [DatabaseCursor] INTO @Db,@DbId,@CompatibilityLevel;
            WHILE @@FETCH_STATUS=0
            BEGIN
                IF @AssemblyPatternMode IN('REGEX','REGEXI') AND COALESCE(@CompatibilityLevel,0)<170
                BEGIN
                    UPDATE [#ClrAnalysis_DatabaseStatus]
                    SET [StatusCode]='UNAVAILABLE_FEATURE',[IsPartial]=1,[SourceFailureCount]=[SourceFailureCount]+1,
                        [ErrorMessage]=N'Regex-Pattern benötigen Compatibility Level 170.'
                    WHERE [DatabaseName]=@Db;
                    INSERT [#ClrAnalysis_SourceStatus]
                    VALUES(@Db,'FILTER_CONTRACT','UNAVAILABLE_FEATURE',1,0,N'Compatibility Level 170',SYSUTCDATETIME(),NULL,N'Regex-Pattern nicht ausführbar.',N'Keine CLR-Katalogquelle wurde für diese Datenbank gelesen.');
                    FETCH NEXT FROM [DatabaseCursor] INTO @Db,@DbId,@CompatibilityLevel;
                    CONTINUE;
                END;

                BEGIN TRY
                    SET @Sql=N'USE '+QUOTENAME(@Db)+N';
INSERT [#ClrAnalysis_Assemblies]
([DatabaseId],[DatabaseName],[AssemblyId],[AssemblyName],[ClrName],[PermissionSetDesc],[IsVisible],[CreateDate],[ModifyDate],[OwnerName],[IsLoaded],[LastVisibleLoadTime],[TrustVerificationStatus],[EvidenceLimit])
SELECT @pDatabaseId,@pDatabaseName,[a].[assembly_id],[a].[name],[a].[clr_name],[a].[permission_set_desc],[a].[is_visible],[a].[create_date],[a].[modify_date],'
 + CASE WHEN @MitBerechtigungsanalyse=1 THEN N'[dp].[name]' ELSE N'CONVERT(sysname,NULL)' END + N',
       0,NULL,''NOT_EVALUATED_BINARY_EXCLUDED'',
       N''Benutzerdefinierte Assemblymetadaten; sys.assembly_files.content und Hashwerte sind ausgeschlossen.''
FROM [sys].[assemblies] [a] WITH (NOLOCK) '
 + CASE WHEN @MitBerechtigungsanalyse=1 THEN N'LEFT JOIN [sys].[database_principals] [dp] WITH (NOLOCK) ON [dp].[principal_id]=[a].[principal_id] ' ELSE N'' END
 + N'WHERE [a].[is_user_defined]=1 '+@AssemblyPredicate+N'; SET @pRows=@@ROWCOUNT;';
                    SET @Rows=0;
                    EXEC [sys].[sp_executesql] @Sql,
                         N'@pDatabaseId int,@pDatabaseName sysname,@pPattern nvarchar(4000),@pRegexFlags varchar(8),@pRows bigint OUTPUT',
                         @pDatabaseId=@DbId,@pDatabaseName=@Db,@pPattern=@AssemblyPatternValue,@pRegexFlags=@AssemblyRegexFlags,@pRows=@Rows OUTPUT;
                    INSERT [#ClrAnalysis_SourceStatus]
                    VALUES(@Db,'CLR_ASSEMBLIES','AVAILABLE',0,@Rows,N'Metadatensichtbarkeit',SYSUTCDATETIME(),NULL,NULL,N'Keine Binärinhalte oder Hashes.');
                END TRY
                BEGIN CATCH
                    INSERT [#ClrAnalysis_SourceStatus]
                    VALUES(@Db,'CLR_ASSEMBLIES',CASE WHEN ERROR_NUMBER()=1222 THEN 'LOCK_TIMEOUT' WHEN ERROR_NUMBER() IN(229,297,300,371,916) THEN 'DENIED_PERMISSION' ELSE 'ERROR_HANDLED' END,1,0,N'Metadatensichtbarkeit',SYSUTCDATETIME(),ERROR_NUMBER(),ERROR_MESSAGE(),N'Assemblykatalog isoliert fehlgeschlagen.');
                END CATCH;

                IF @MitModulzuordnung=1
                BEGIN
                    BEGIN TRY
                        SET @Sql=N'USE '+QUOTENAME(@Db)+N';
INSERT [#ClrAnalysis_AssemblyModules]
([DatabaseName],[SchemaName],[ObjectName],[ObjectType],[ObjectTypeDesc],[AssemblyName],[AssemblyClass],[AssemblyMethod],[ExecuteAsPrincipal],[EvidenceLimit])
SELECT @pDatabaseName,[s].[name],[o].[name],[o].[type],[o].[type_desc],[a].[name],[am].[assembly_class],[am].[assembly_method],'
 + CASE WHEN @MitBerechtigungsanalyse=1 THEN N'[dp].[name]' ELSE N'CONVERT(sysname,NULL)' END + N',
       N''Objekt- und Implementierungsmetadaten ohne Moduldefinition oder SQL-Text.''
FROM [sys].[assembly_modules] [am] WITH (NOLOCK)
JOIN [sys].[objects] [o] WITH (NOLOCK) ON [o].[object_id]=[am].[object_id]
JOIN [sys].[schemas] [s] WITH (NOLOCK) ON [s].[schema_id]=[o].[schema_id]
JOIN [sys].[assemblies] [a] WITH (NOLOCK) ON [a].[assembly_id]=[am].[assembly_id] '
 + CASE WHEN @MitBerechtigungsanalyse=1 THEN N'LEFT JOIN [sys].[database_principals] [dp] WITH (NOLOCK) ON [dp].[principal_id]=[am].[execute_as_principal_id] ' ELSE N'' END
 + N'WHERE [a].[is_user_defined]=1 '+@AssemblyPredicate+N'; SET @pRows=@@ROWCOUNT;';
                        SET @Rows=0;
                        EXEC [sys].[sp_executesql] @Sql,N'@pDatabaseName sysname,@pPattern nvarchar(4000),@pRegexFlags varchar(8),@pRows bigint OUTPUT',
                             @pDatabaseName=@Db,@pPattern=@AssemblyPatternValue,@pRegexFlags=@AssemblyRegexFlags,@pRows=@Rows OUTPUT;
                        INSERT [#ClrAnalysis_SourceStatus]
                        VALUES(@Db,'CLR_ASSEMBLY_MODULES','AVAILABLE',0,@Rows,N'Metadatensichtbarkeit',SYSUTCDATETIME(),NULL,NULL,N'Keine Moduldefinitionen.');
                    END TRY
                    BEGIN CATCH
                        INSERT [#ClrAnalysis_SourceStatus]
                        VALUES(@Db,'CLR_ASSEMBLY_MODULES',CASE WHEN ERROR_NUMBER()=1222 THEN 'LOCK_TIMEOUT' WHEN ERROR_NUMBER() IN(229,297,300,371,916) THEN 'DENIED_PERMISSION' ELSE 'ERROR_HANDLED' END,1,0,N'Metadatensichtbarkeit',SYSUTCDATETIME(),ERROR_NUMBER(),ERROR_MESSAGE(),N'Modulkatalog isoliert fehlgeschlagen.');
                    END CATCH;

                    BEGIN TRY
                        SET @Sql=N'USE '+QUOTENAME(@Db)+N';
INSERT [#ClrAnalysis_AssemblyDependencies]
([DatabaseName],[DependencyKind],[AssemblyName],[ReferencedAssemblyName],[SchemaName],[TypeName],[AssemblyClass],[EvidenceLimit])
SELECT @pDatabaseName,''ASSEMBLY_REFERENCE'',[a].[name],[ra].[name],NULL,NULL,NULL,
       N''Direkte Assemblyreferenz; rekursive oder binäre Abhängigkeiten werden nicht aufgelöst.''
FROM [sys].[assembly_references] [ar] WITH (NOLOCK)
JOIN [sys].[assemblies] [a] WITH (NOLOCK) ON [a].[assembly_id]=[ar].[assembly_id]
JOIN [sys].[assemblies] [ra] WITH (NOLOCK) ON [ra].[assembly_id]=[ar].[referenced_assembly_id]
WHERE [a].[is_user_defined]=1 '+@AssemblyPredicate+N'
UNION ALL
SELECT @pDatabaseName,''ASSEMBLY_TYPE'',[a].[name],NULL,[s].[name],[at].[name],[at].[assembly_class],
       N''Sichtbarer CLR-Typ; assembly_qualified_name und Binärinhalt sind ausgeschlossen.''
FROM [sys].[assembly_types] [at] WITH (NOLOCK)
JOIN [sys].[schemas] [s] WITH (NOLOCK) ON [s].[schema_id]=[at].[schema_id]
JOIN [sys].[assemblies] [a] WITH (NOLOCK) ON [a].[assembly_id]=[at].[assembly_id]
WHERE [a].[is_user_defined]=1 '+@AssemblyPredicate+N'; SET @pRows=@@ROWCOUNT;';
                        SET @Rows=0;
                        EXEC [sys].[sp_executesql] @Sql,N'@pDatabaseName sysname,@pPattern nvarchar(4000),@pRegexFlags varchar(8),@pRows bigint OUTPUT',
                             @pDatabaseName=@Db,@pPattern=@AssemblyPatternValue,@pRegexFlags=@AssemblyRegexFlags,@pRows=@Rows OUTPUT;
                        INSERT [#ClrAnalysis_SourceStatus]
                        VALUES(@Db,'CLR_ASSEMBLY_DEPENDENCIES','AVAILABLE',0,@Rows,N'Metadatensichtbarkeit',SYSUTCDATETIME(),NULL,NULL,N'Direkte Referenzen und CLR-Typen; keine Binaryanalyse.');
                    END TRY
                    BEGIN CATCH
                        INSERT [#ClrAnalysis_SourceStatus]
                        VALUES(@Db,'CLR_ASSEMBLY_DEPENDENCIES',CASE WHEN ERROR_NUMBER()=1222 THEN 'LOCK_TIMEOUT' WHEN ERROR_NUMBER() IN(229,297,300,371,916) THEN 'DENIED_PERMISSION' ELSE 'ERROR_HANDLED' END,1,0,N'Metadatensichtbarkeit',SYSUTCDATETIME(),ERROR_NUMBER(),ERROR_MESSAGE(),N'Dependency-Katalog isoliert fehlgeschlagen.');
                    END CATCH;
                END;

                UPDATE [ds]
                SET [AssemblyCount]=(SELECT COUNT_BIG(*) FROM [#ClrAnalysis_Assemblies] [a] WHERE [a].[DatabaseName]=[ds].[DatabaseName]),
                    [HighPermissionAssemblyCount]=(SELECT COUNT_BIG(*) FROM [#ClrAnalysis_Assemblies] [a] WHERE [a].[DatabaseName]=[ds].[DatabaseName] AND [a].[PermissionSetDesc] IN(N'EXTERNAL_ACCESS',N'UNSAFE_ACCESS')),
                    [ModuleCount]=(SELECT COUNT_BIG(*) FROM [#ClrAnalysis_AssemblyModules] [m] WHERE [m].[DatabaseName]=[ds].[DatabaseName])
                FROM [#ClrAnalysis_DatabaseStatus] [ds] WHERE [ds].[DatabaseName]=@Db;

                FETCH NEXT FROM [DatabaseCursor] INTO @Db,@DbId,@CompatibilityLevel;
            END;
            CLOSE [DatabaseCursor]; DEALLOCATE [DatabaseCursor];
        END;

        UPDATE [l]
        SET [AssemblyName]=[a].[AssemblyName],[MappingStatus]='CATALOG_MAPPED'
        FROM [#ClrAnalysis_LoadedAssemblies] [l]
        JOIN [#ClrAnalysis_Assemblies] [a] ON [a].[DatabaseId]=[l].[DatabaseId] AND [a].[AssemblyId]=[l].[AssemblyId];
        UPDATE [a]
        SET [IsLoaded]=1,[LastVisibleLoadTime]=[x].[LoadTime]
        FROM [#ClrAnalysis_Assemblies] [a]
        CROSS APPLY
        (
            SELECT MAX([l].[LoadTime]) AS [LoadTime]
            FROM [#ClrAnalysis_LoadedAssemblies] [l]
            WHERE [l].[DatabaseId]=[a].[DatabaseId] AND [l].[AssemblyId]=[a].[AssemblyId]
        ) [x]
        WHERE [x].[LoadTime] IS NOT NULL;

        INSERT [#ClrAnalysis_PerformanceCounters]
        SELECT [a].[CounterName],[a].[InstanceName],[a].[CounterType],COALESCE([b].[CounterValue],[a].[CounterValue]),
               [i].[Interpretation],[i].[MetricValue],[i].[MetricUnit],[i].[FindingCode],
               N'Counterinterpretation basiert auf cntr_type; CLR Execution ist kumulative Laufzeit und keine per-Request-Zuordnung.'
        FROM [#ClrAnalysis_CounterSamples] [a]
        LEFT JOIN [#ClrAnalysis_CounterSamples] [b]
          ON [b].[SamplePoint]='T2' AND [b].[CounterName]=[a].[CounterName]
         AND [b].[InstanceName]=[a].[InstanceName] AND [b].[CounterType]=[a].[CounterType]
        CROSS APPLY [monitor].[TVF_InterpretPerformanceCounter]
        (
              [a].[CounterType],[a].[CounterValue],COALESCE([b].[CounterValue],[a].[CounterValue])
            , NULL,NULL
            , CONVERT(decimal(19,6),CASE WHEN @SampleSeconds>0 THEN DATEDIFF_BIG(MICROSECOND,[a].[ReadAtUtc],[b].[ReadAtUtc])/1000000.0 ELSE 0 END)
        ) [i]
        WHERE [a].[SamplePoint]='T1';

        INSERT [#ClrAnalysis_Findings]
        ([DatabaseName],[ObjectType],[ObjectName],[Severity],[Confidence],[FindingCode],[MetricName],[MetricValue],[ThresholdValue],[Evidence],[EvidenceLimit],[RecommendedNextCheck])
        SELECT NULL,'SERVER_CONFIGURATION',NULL,'WARN','HIGH','CLR_STRICT_SECURITY_DISABLED',
               'ClrStrictSecurityValueInUse',[ClrStrictSecurityValueInUse],1,
               N'clr strict security ist deaktiviert.',
               N'Der Befund bewertet die dokumentierte Sicherheitsoption; er beweist keine konkrete Ausnutzbarkeit einer Assembly.',
               N'Assemblysignierung, trusted assemblies, Permission Sets und dokumentierte Migrationsgründe prüfen.'
        FROM [#ClrAnalysis_Configuration]
        WHERE COALESCE([ClrStrictSecurityValueInUse],0)=0;

        INSERT [#ClrAnalysis_Findings]
        SELECT NULL,'SERVER_CONFIGURATION',NULL,'WARN','HIGH','CLR_LIGHTWEIGHT_POOLING_CONFLICT',
               'LightweightPoolingValueInUse',[LightweightPoolingValueInUse],0,
               N'clr enabled und lightweight pooling sind gleichzeitig aktiv.',
               N'SQL CLR wird nach Herstellerdokumentation unter lightweight pooling nicht unterstützt.',
               N'Eine der beiden Optionen nach Change-Control deaktivieren; dieses Analysemodul ändert keine Konfiguration.'
        FROM [#ClrAnalysis_Configuration]
        WHERE [ClrEnabledValueInUse]=1 AND [LightweightPoolingValueInUse]=1;

        INSERT [#ClrAnalysis_Findings]
        SELECT [a].[DatabaseName],'ASSEMBLY',[a].[AssemblyName],'WARN','HIGH','USER_ASSEMBLY_WHILE_CLR_DISABLED',
               'ClrEnabledValueInUse',[c].[ClrEnabledValueInUse],1,
               N'Eine benutzerdefinierte Assembly ist sichtbar, während clr enabled nicht aktiv ist.',
               N'Die Katalogzeile beweist keine aktuell geladene oder ausgeführte Assembly.',
               N'Prüfen, ob die Assembly noch benötigt wird oder CLR beabsichtigt deaktiviert ist.'
        FROM [#ClrAnalysis_Assemblies] [a]
        CROSS JOIN [#ClrAnalysis_Configuration] [c]
        WHERE COALESCE([c].[ClrEnabledValueInUse],0)=0;

        INSERT [#ClrAnalysis_Findings]
        SELECT [DatabaseName],'ASSEMBLY',[AssemblyName],'WARN','HIGH','UNSUPPORTED_CLR_PERMISSION_SET_ON_LINUX',
               'PermissionSet',CASE [PermissionSetDesc] WHEN N'EXTERNAL_ACCESS' THEN 2 WHEN N'UNSAFE_ACCESS' THEN 3 END,1,
               CONCAT(N'Die Assembly verwendet ',[PermissionSetDesc],N' auf SQL Server unter Linux.'),
               N'EXTERNAL_ACCESS und UNSAFE sind für SQL CLR unter Linux nicht unterstützt; die Analyse lädt die Assembly nicht.',
               N'Zielplattform, Permission Set und externe Abhängigkeiten vor Deployment oder Failover prüfen.'
        FROM [#ClrAnalysis_Assemblies]
        WHERE UPPER(COALESCE(@HostPlatform,N''))='LINUX' AND [PermissionSetDesc] IN(N'EXTERNAL_ACCESS',N'UNSAFE_ACCESS');

        INSERT [#ClrAnalysis_Findings]
        SELECT [a].[DatabaseName],'ASSEMBLY',[a].[AssemblyName],'WARN','HIGH','TRUSTWORTHY_DATABASE_WITH_HIGH_PERMISSION_ASSEMBLY',
               'IsTrustworthyOn',[ds].[IsTrustworthyOn],0,
               CONCAT(N'Die Datenbank ist TRUSTWORTHY ON und enthält eine Assembly mit Permission Set ',[a].[PermissionSetDesc],N'.'),
               N'Der Befund beweist keine Privilege Escalation; Owner-, Signatur- und Trustkontext sind separat zu prüfen.',
               N'Datenbankowner, Signaturen, trusted assemblies und erforderlichen Permission Set prüfen.'
        FROM [#ClrAnalysis_Assemblies] [a]
        JOIN [#ClrAnalysis_DatabaseStatus] [ds] ON [ds].[DatabaseName]=[a].[DatabaseName]
        WHERE [ds].[IsTrustworthyOn]=1 AND [a].[PermissionSetDesc] IN(N'EXTERNAL_ACCESS',N'UNSAFE_ACCESS');

        INSERT [#ClrAnalysis_Findings]
        SELECT [DatabaseName],'ASSEMBLY',[AssemblyName],'INFO','HIGH','ASSEMBLY_TRUST_MAPPING_NOT_VERIFIED',
               NULL,NULL,NULL,
               N'Die exakte Zuordnung dieser Assembly zur serverweiten Trust List wurde nicht geprüft.',
               N'Ein belastbarer Abgleich benötigt den SHA2_512-Hash des Assembly-Binärinhalts; dieser Privacy- und Kostenpfad ist ausgeschlossen.',
               N'Bei Security-Review den Hashabgleich kontrolliert außerhalb des Standardpfads durchführen.'
        FROM [#ClrAnalysis_Assemblies]
        WHERE [PermissionSetDesc] IN(N'EXTERNAL_ACCESS',N'UNSAFE_ACCESS');

        INSERT [#ClrAnalysis_Findings]
        SELECT NULL,'CLR_HOST',N'state','WARN','HIGH','CLR_HOST_INITIALIZATION_FAILED',
               NULL,NULL,NULL,
               CONCAT(N'Der CLR Host meldet den Zustand ',[PropertyValue],N'.'),
               N'sys.dm_clr_properties beschreibt den Hostzustand, nicht die Aktivierung von Benutzer-CLR.',
               N'SQL Server Errorlog, Memory Pressure und Hostinitialisierung prüfen.'
        FROM [#ClrAnalysis_Properties]
        WHERE [PropertyName]=N'state' AND [PropertyValue] LIKE N'%permanently failed%';

        INSERT [#ClrAnalysis_Findings]
        SELECT [DatabaseName],'ACTIVE_REQUEST',CONCAT(CONVERT(nvarchar(20),[SessionId]),N':',CONVERT(nvarchar(20),[RequestId])),
               'WARN','HIGH','ACTIVE_MANAGED_CODE_REQUEST_BLOCKED','BlockingSessionId',[BlockingSessionId],0,
               CONCAT(N'Der aktive Managed-Code-Request ist durch Session ',CONVERT(nvarchar(20),[BlockingSessionId]),N' geblockt.'),
               N'Momentaufnahme; executing_managed_code identifiziert keine bestimmte Assemblymethode.',
               N'USP_CurrentBlocking für die vollständige Blockerkette ausführen.'
        FROM [#ClrAnalysis_ActiveRequests]
        WHERE COALESCE([BlockingSessionId],0)>0;

        INSERT [#ClrAnalysis_Findings]
        SELECT [DatabaseName],'CLR_TASK',CONVERT(nvarchar(34),[TaskAddress],1),'INFO','MEDIUM','CLR_TASK_REQUEST_UNMAPPED',
               'ForcedYieldCount',[ForcedYieldCount],NULL,
               N'Ein aktueller CLR Task konnte nicht zu einem sichtbaren sys.dm_os_tasks-Request gemappt werden.',
               N'Task- und Requestlebenszeiten können zwischen den DMV-Lesezeitpunkten wechseln; fehlende Zuordnung ist kein Fehlerbeweis.',
               N'Bei wiederholtem Auftreten CLR Tasks, AppDomainzustand und aktuelle Requests gemeinsam erfassen.'
        FROM [#ClrAnalysis_Tasks]
        WHERE [MappingStatus]='REQUEST_UNMAPPED';

        INSERT [#ClrAnalysis_Findings]
        SELECT [DatabaseName],'LOADED_ASSEMBLY',CONVERT(nvarchar(20),[AssemblyId]),'INFO','LOW','LOADED_ASSEMBLY_CATALOG_UNMAPPED',
               NULL,NULL,NULL,
               N'Eine geladene Assembly-DMV-Zeile konnte keiner sichtbaren benutzerdefinierten Assembly im AppDomain-Datenbankkontext zugeordnet werden.',
               N'Systemassembly, Metadatensichtbarkeit, Filter oder zwischenzeitlicher Unload können die Zuordnung verhindern.',
               N'Filter und Metadatenrechte prüfen; keine globale Zuordnung nur über assembly_id vornehmen.'
        FROM [#ClrAnalysis_LoadedAssemblies]
        WHERE [MappingStatus]<>'CATALOG_MAPPED';

        INSERT [#ClrAnalysis_Warnings]
        VALUES('ASSEMBLY_TRUST_HASH_EXCLUDED',N'Die Analyse liest weder sys.assembly_files.content noch Trusted-Assembly-Hashes und kann deshalb keinen Assembly-zu-Trust-List-Nachweis erzeugen.',N'Die Anzahl trusted assemblies ist bei Opt-in nur serverweite Kontextevidenz.');
        IF UPPER(COALESCE(@HostPlatform,N''))='LINUX'
            INSERT [#ClrAnalysis_Warnings]
            VALUES('LINUX_CLR_PLATFORM_LIMIT',N'SQL CLR unter Linux unterstützt nur SAFE Assemblies; Assembly-Builds müssen weiterhin auf .NET Framework basieren.',N'Die Analyse führt keinen Lade- oder Ausführungstest durch.');

        UPDATE [ds]
        SET [SourceFailureCount]=(SELECT COUNT(*) FROM [#ClrAnalysis_SourceStatus] [ss] WHERE [ss].[DatabaseName]=[ds].[DatabaseName] AND [ss].[IsPartial]=1),
            [IsPartial]=CONVERT(bit,CASE WHEN EXISTS(SELECT 1 FROM [#ClrAnalysis_SourceStatus] [ss] WHERE [ss].[DatabaseName]=[ds].[DatabaseName] AND [ss].[IsPartial]=1) THEN 1 ELSE 0 END),
            [StatusCode]=CASE WHEN EXISTS(SELECT 1 FROM [#ClrAnalysis_SourceStatus] [ss] WHERE [ss].[DatabaseName]=[ds].[DatabaseName] AND [ss].[IsPartial]=1) THEN 'AVAILABLE_LIMITED'
                              WHEN [AssemblyCount]=0 THEN 'NOT_APPLICABLE_VISIBLE_SCOPE' ELSE 'AVAILABLE' END
        FROM [#ClrAnalysis_DatabaseStatus] [ds]
        WHERE [StatusCode]='PENDING';

        IF @StatusCode='AVAILABLE'
        BEGIN
            IF EXISTS(SELECT 1 FROM [#ClrAnalysis_SourceStatus] WHERE [IsPartial]=1)
                SELECT @StatusCode='AVAILABLE_LIMITED',@IsPartial=1;
            ELSE IF EXISTS(SELECT 1 FROM [#ClrAnalysis_Findings] WHERE [Severity]='WARN')
                SET @StatusCode='AVAILABLE_WITH_FINDING';
            ELSE IF EXISTS(SELECT 1 FROM [#ClrAnalysis_Configuration] WHERE COALESCE([ClrEnabledValueInUse],0)=0)
                 AND NOT EXISTS(SELECT 1 FROM [#ClrAnalysis_Assemblies])
                SET @StatusCode='NOT_APPLICABLE';
            ELSE IF EXISTS(SELECT 1 FROM [#ClrAnalysis_Configuration] WHERE COALESCE([ClrEnabledValueInUse],0)=0)
                SET @StatusCode='FEATURE_DISABLED';
        END;

        SELECT @ErrorNumber=COALESCE(@ErrorNumber,MIN([ErrorNumber])),@ErrorMessage=COALESCE(@ErrorMessage,MIN([ErrorMessage]))
        FROM [#ClrAnalysis_SourceStatus] WHERE [IsPartial]=1;

        IF @MaxZeilen>0 AND
           (
               (SELECT COUNT_BIG(*) FROM [#ClrAnalysis_Findings] WHERE @NurProblematisch=0 OR [Severity]='WARN')>@Limit
            OR (SELECT COUNT_BIG(*) FROM [#ClrAnalysis_Assemblies])>@Limit
            OR (SELECT COUNT_BIG(*) FROM [#ClrAnalysis_AssemblyModules])>@Limit
            OR (SELECT COUNT_BIG(*) FROM [#ClrAnalysis_AssemblyDependencies])>@Limit
            OR (SELECT COUNT_BIG(*) FROM [#ClrAnalysis_AppDomains])>@Limit
            OR (SELECT COUNT_BIG(*) FROM [#ClrAnalysis_LoadedAssemblies])>@Limit
            OR (SELECT COUNT_BIG(*) FROM [#ClrAnalysis_Tasks])>@Limit
           )
        BEGIN
            INSERT [#ClrAnalysis_Warnings]
            VALUES('RESULTSET_TRUNCATED',N'Mindestens ein fachliches Resultset enthält mehr Zeilen als @MaxZeilen und wird erst nach globaler Sortierung begrenzt.',N'@MaxZeilen=0 liefert alle materialisierten Zeilen.');
            IF @PrintMeldungen=1 RAISERROR(N'RESULTSET_TRUNCATED: Verwenden Sie @MaxZeilen=0 oder einen höheren Wert für die vollständige Ausgabe.',10,1) WITH NOWAIT;
        END;

        IF @JsonErzeugen=1
        BEGIN
            SELECT @Json=(
                SELECT
                    JSON_QUERY((SELECT N'USP_ClrAnalysis' AS [module],@Now AS [collectedAtUtc],@MeasurementStartUtc AS [measurementStartUtc],@MeasurementEndUtc AS [measurementEndUtc],@StatusCode AS [statusCode],@IsPartial AS [isPartial],@ErrorNumber AS [errorNumber],@ErrorMessage AS [errorMessage] FOR JSON PATH,WITHOUT_ARRAY_WRAPPER)) AS [meta],
                    JSON_QUERY(COALESCE((SELECT * FROM [#ClrAnalysis_Configuration] FOR JSON PATH),N'[]')) AS [configuration],
                    JSON_QUERY(COALESCE((SELECT * FROM [#ClrAnalysis_DatabaseStatus] ORDER BY [DatabaseName] FOR JSON PATH),N'[]')) AS [databaseStatus],
                    JSON_QUERY(COALESCE((SELECT * FROM [#ClrAnalysis_SourceStatus] ORDER BY [DatabaseName],[SourceCode],[ReadAtUtc] FOR JSON PATH),N'[]')) AS [sourceStatus],
                    JSON_QUERY(COALESCE((SELECT TOP(@Limit) * FROM [#ClrAnalysis_Findings] WHERE @NurProblematisch=0 OR [Severity]='WARN' ORDER BY CASE [Severity] WHEN 'WARN' THEN 1 ELSE 2 END,[FindingOrdinal] FOR JSON PATH),N'[]')) AS [findings],
                    JSON_QUERY(COALESCE((SELECT TOP(@Limit) * FROM [#ClrAnalysis_Assemblies] ORDER BY [DatabaseName],[AssemblyName] FOR JSON PATH),N'[]')) AS [assemblies],
                    JSON_QUERY(COALESCE((SELECT TOP(@Limit) * FROM [#ClrAnalysis_AssemblyModules] ORDER BY [DatabaseName],[SchemaName],[ObjectName] FOR JSON PATH),N'[]')) AS [assemblyModules],
                    JSON_QUERY(COALESCE((SELECT TOP(@Limit) * FROM [#ClrAnalysis_AssemblyDependencies] ORDER BY [DatabaseName],[AssemblyName],[DependencyKind] FOR JSON PATH),N'[]')) AS [assemblyDependencies],
                    JSON_QUERY(COALESCE((SELECT * FROM [#ClrAnalysis_Properties] ORDER BY [PropertyName] FOR JSON PATH),N'[]')) AS [clrProperties],
                    JSON_QUERY(COALESCE((SELECT TOP(@Limit) * FROM [#ClrAnalysis_AppDomains] ORDER BY [TotalProcessorTimeMs] DESC,[DatabaseName],[AppDomainId] FOR JSON PATH),N'[]')) AS [appDomains],
                    JSON_QUERY(COALESCE((SELECT TOP(@Limit) * FROM [#ClrAnalysis_LoadedAssemblies] ORDER BY [LoadTime] DESC,[DatabaseName],[AssemblyName] FOR JSON PATH),N'[]')) AS [loadedAssemblies],
                    JSON_QUERY(COALESCE((SELECT TOP(@Limit) * FROM [#ClrAnalysis_Tasks] ORDER BY [ForcedYieldCount] DESC,[DatabaseName] FOR JSON PATH),N'[]')) AS [clrTasks],
                    JSON_QUERY(COALESCE((SELECT TOP(@Limit) * FROM [#ClrAnalysis_ActiveRequests] ORDER BY [WaitTimeMs] DESC,[SessionId],[RequestId] FOR JSON PATH),N'[]')) AS [activeRequests],
                    JSON_QUERY(COALESCE((SELECT TOP(@Limit) * FROM [#ClrAnalysis_Memory] ORDER BY [PagesKb] DESC,[MemoryClerkType] FOR JSON PATH),N'[]')) AS [memory],
                    JSON_QUERY(COALESCE((SELECT TOP(@Limit) * FROM [#ClrAnalysis_PerformanceCounters] ORDER BY [CounterName],[InstanceName] FOR JSON PATH),N'[]')) AS [performanceCounters],
                    JSON_QUERY(COALESCE((SELECT * FROM [#ClrAnalysis_Warnings] ORDER BY [WarningCode] FOR JSON PATH),N'[]')) AS [warnings]
                FOR JSON PATH,WITHOUT_ARRAY_WRAPPER);
        END;

        IF @OutputMode='RAW'
        BEGIN
            SELECT N'USP_ClrAnalysis' AS [Module],@Now AS [CollectedAtUtc],@MeasurementStartUtc AS [MeasurementStartUtc],@MeasurementEndUtc AS [MeasurementEndUtc],@StatusCode AS [StatusCode],@IsPartial AS [IsPartial],@ErrorNumber AS [ErrorNumber],@ErrorMessage AS [ErrorMessage],N'Read-only SQL-CLR-Evidenz; keine Assembly-Binaries, Hashes, Moduldefinitionen, SQL-Texte, Pläne oder Testausführung.' AS [EvidenceLimit];
            SELECT * FROM [#ClrAnalysis_Configuration];
            SELECT * FROM [#ClrAnalysis_DatabaseStatus] ORDER BY [DatabaseName];
            SELECT * FROM [#ClrAnalysis_SourceStatus] ORDER BY [DatabaseName],[SourceCode],[ReadAtUtc];
            SELECT TOP(@Limit) * FROM [#ClrAnalysis_Findings] WHERE @NurProblematisch=0 OR [Severity]='WARN' ORDER BY CASE [Severity] WHEN 'WARN' THEN 1 ELSE 2 END,[FindingOrdinal];
            SELECT TOP(@Limit) * FROM [#ClrAnalysis_Assemblies] ORDER BY [DatabaseName],[AssemblyName];
            SELECT TOP(@Limit) * FROM [#ClrAnalysis_AssemblyModules] ORDER BY [DatabaseName],[SchemaName],[ObjectName];
            SELECT TOP(@Limit) * FROM [#ClrAnalysis_AssemblyDependencies] ORDER BY [DatabaseName],[AssemblyName],[DependencyKind];
            SELECT * FROM [#ClrAnalysis_Properties] ORDER BY [PropertyName];
            SELECT TOP(@Limit) * FROM [#ClrAnalysis_AppDomains] ORDER BY [TotalProcessorTimeMs] DESC,[DatabaseName],[AppDomainId];
            SELECT TOP(@Limit) * FROM [#ClrAnalysis_LoadedAssemblies] ORDER BY [LoadTime] DESC,[DatabaseName],[AssemblyName];
            SELECT TOP(@Limit) * FROM [#ClrAnalysis_Tasks] ORDER BY [ForcedYieldCount] DESC,[DatabaseName];
            SELECT TOP(@Limit) * FROM [#ClrAnalysis_ActiveRequests] ORDER BY [WaitTimeMs] DESC,[SessionId],[RequestId];
            SELECT TOP(@Limit) * FROM [#ClrAnalysis_Memory] ORDER BY [PagesKb] DESC,[MemoryClerkType];
            SELECT TOP(@Limit) * FROM [#ClrAnalysis_PerformanceCounters] ORDER BY [CounterName],[InstanceName];
            SELECT * FROM [#ClrAnalysis_Warnings] ORDER BY [WarningCode];
        END;
    END TRY
    BEGIN CATCH
        SELECT @StatusCode=CASE WHEN ERROR_NUMBER()=1222 THEN 'LOCK_TIMEOUT' ELSE 'ERROR_HANDLED' END,
               @IsPartial=1,@ErrorNumber=ERROR_NUMBER(),@ErrorMessage=ERROR_MESSAGE();
    END CATCH;

    SET @LockTimeoutSql=N'SET LOCK_TIMEOUT '+CONVERT(nvarchar(20),@OriginalLockTimeout)+N';';
    EXEC [sys].[sp_executesql] @LockTimeoutSql;

    IF @PrintMeldungen=1 AND @StatusCode NOT IN('AVAILABLE','NOT_APPLICABLE')
    BEGIN
        SET @PrintMessage=LEFT(CONCAT(N'USP_ClrAnalysis: ',@StatusCode,N'. ',COALESCE(@ErrorMessage,N'Siehe strukturierte Quellenstatus.')),2048);
        RAISERROR(N'%s',10,1,@PrintMessage) WITH NOWAIT;
    END;
    SELECT @StatusCodeOut=@StatusCode,@IsPartialOut=@IsPartial,@ErrorNumberOut=@ErrorNumber,@ErrorMessageOut=@ErrorMessage;
    IF @ConsoleResultRequested=1
        EXEC [monitor].[InternalEmitConsoleResult]
              @SourceTable=N'#ClrAnalysis_Findings'
            , @ResultLabel=N'ClrAnalysis'
            , @EmptyMessage=N'Keine SQL-CLR-Findings im gewählten Scope';
    IF @TableResultRequested=1
        EXEC [monitor].[InternalWriteResultTable]
              @SourceTable=N'#ClrAnalysis_Findings'
            , @TargetTable=@TableTarget
            , @ThrowOnError=1;
END;
GO
-- END SOURCE: Code/09_VersionAdaptive/100_USP_ClrAnalysis.sql

-- BEGIN SOURCE: Code/09_VersionAdaptive/500_USP_FrameworkUsageFromQueryStore.sql
/*
===============================================================================
Objekt       : monitor.USP_FrameworkUsageFromQueryStore
Version      : 2.0.0
Stand        : 2026-07-26
Typ          : Stored Procedure
Zweck        : Ermittelt aus dem Query Store der Frameworkdatenbank, welche
               monitor-Procedures tatsächlich ausgeführt wurden und welche
               aggregierte Laufzeit-, CPU-, I/O- und Plan-Evidenz vorliegt.
SQL-Version  : SQL Server 2019 oder neuer.
Datenquellen : sys.database_query_store_options, sys.query_store_query,
               sys.query_store_plan, sys.query_store_runtime_stats,
               sys.objects und sys.schemas. Jede Quelle wird je Aufruf höchstens
               einmal logisch gelesen.
Abgrenzung   : Keine eigene Erfassung, keine Query-Store-Konfigurationsänderung,
               kein Flush, kein Cleanup und keine Benutzerattribution. Fehlende
               Query-Store-Zeilen beweisen nicht, dass eine Procedure nie lief.
Kosten       : LOW_TO_MEDIUM. Die Aggregation ist nach Zeitraum und Ausgabezahl
               begrenzbar; der Query Store muss dennoch die passenden Intervalle
               und Pläne auswerten.
===============================================================================
*/
CREATE OR ALTER PROCEDURE [monitor].[USP_FrameworkUsageFromQueryStore]
      @MaxZeilen          int            = 100
    , @MinAusfuehrungen   bigint         = 1
    , @ZeitraumTage       int            = NULL
    , @LockTimeoutMs      int            = 0
    , @ResultSetArt       varchar(16)    = 'CONSOLE'
    , @ResultTablesJson   nvarchar(max)  = NULL
    , @JsonErzeugen       bit            = 0
    , @Json               nvarchar(max)  = NULL OUTPUT
    , @PrintMeldungen     bit            = 1
    , @Hilfe              bit            = 0
    , @StatusCodeOut      varchar(40)    = NULL OUTPUT
    , @IsPartialOut       bit            = NULL OUTPUT
    , @ErrorNumberOut     int            = NULL OUTPUT
    , @ErrorMessageOut    nvarchar(2048) = NULL OUTPUT
AS
BEGIN
    SET NOCOUNT ON;
    SET @Json = NULL;

    DECLARE @CapturedAtUtc datetime2(3) = SYSUTCDATETIME();
    DECLARE @OutputMode varchar(16) = UPPER(LTRIM(RTRIM(COALESCE(@ResultSetArt,''))));
    DECLARE @ConsoleResultRequested bit = CASE WHEN @OutputMode='CONSOLE' THEN 1 ELSE 0 END;
    DECLARE @StatusCode varchar(40) = 'AVAILABLE';
    DECLARE @IsPartial bit = 0;
    DECLARE @ErrorNumber int = NULL;
    DECLARE @ErrorMessage nvarchar(2048) = NULL;
    DECLARE @OriginalLockTimeout int = @@LOCK_TIMEOUT;
    DECLARE @LockTimeoutSql nvarchar(64);
    DECLARE @Limit bigint = CASE
        WHEN @MaxZeilen IS NULL OR @MaxZeilen=0 THEN CONVERT(bigint,9223372036854775807)
        ELSE CONVERT(bigint,@MaxZeilen)
    END;
    DECLARE @FetchLimit bigint;
    DECLARE @CutoffUtc datetimeoffset(7) = NULL;
    DECLARE @QueryStoreActualState smallint = NULL;
    DECLARE @QueryStoreActualStateDesc nvarchar(60) = NULL;
    DECLARE @QueryStoreReadonlyReason bigint = NULL;
    DECLARE @OptionsReadable bit = 0;
    DECLARE @HasMoreRows bit = 0;
    DECLARE @ReturnedRowCount bigint = 0;

    IF @Hilfe=1
    BEGIN
        PRINT N'monitor.USP_FrameworkUsageFromQueryStore';
        PRINT N'Liest ausschließlich vorhandene Query-Store-Evidenz der Frameworkdatenbank.';
        PRINT N'@ZeitraumTage=NULL oder 0 verwendet den gesamten sichtbaren Query-Store-Zeitraum.';
        PRINT N'@MinAusfuehrungen muss mindestens 1 sein; @MaxZeilen=NULL oder 0 bedeutet unbegrenzt.';
        PRINT N'Gewichtete Mittelwerte verwenden count_executions als Gewicht je Runtime-Stats-Intervall.';
        PRINT N'@ResultSetArt=CONSOLE|RAW|TABLE|NONE; TABLE-Namen: moduleStatus, usage, sourceStatus, warnings.';
        PRINT N'JSON wird nur mit @JsonErzeugen=1 erzeugt. Die Procedure ändert keine Query-Store-Einstellung.';
        RETURN;
    END;

    CREATE TABLE [#FrameworkUsage_ResultTableMap]
    (
          [ResultName] sysname COLLATE SQL_Latin1_General_CP1_CS_AS NOT NULL PRIMARY KEY
        , [TargetTable] sysname COLLATE SQL_Latin1_General_CP1_CS_AS NOT NULL UNIQUE
    );

    CREATE TABLE [#FrameworkUsage_ModuleStatus]
    (
          [ModuleName] sysname NOT NULL
        , [CapturedAtUtc] datetime2(3) NOT NULL
        , [StatusCode] varchar(40) NOT NULL
        , [IsPartial] bit NOT NULL
        , [QueryStoreActualStateDesc] nvarchar(60) NULL
        , [QueryStoreReadonlyReason] bigint NULL
        , [RequestedWindowDays] int NULL
        , [MinimumExecutions] bigint NOT NULL
        , [ReturnedRowCount] bigint NOT NULL
        , [HasMoreRows] bit NOT NULL
        , [ErrorNumber] int NULL
        , [ErrorMessage] nvarchar(2048) NULL
    );

    CREATE TABLE [#FrameworkUsage_UsageCandidates]
    (
          [RowOrdinal] bigint IDENTITY(1,1) NOT NULL PRIMARY KEY
        , [ProcedureName] sysname NOT NULL
        , [ExecutionCount] bigint NOT NULL
        , [LastExecutionTime] datetimeoffset(7) NULL
        , [AvgDurationMs] decimal(19,3) NULL
        , [AvgCpuMs] decimal(19,3) NULL
        , [AvgLogicalReads] decimal(19,2) NULL
        , [AvgMemoryGrantKB] decimal(19,2) NULL
        , [PlanCount] bigint NOT NULL
        , [QueryCount] bigint NOT NULL
        , [FirstSeen] datetimeoffset(7) NULL
        , [LastSeen] datetimeoffset(7) NULL
    );

    CREATE TABLE [#FrameworkUsage_Usage]
    (
          [ProcedureName] sysname NOT NULL
        , [ExecutionCount] bigint NOT NULL
        , [LastExecutionTime] datetimeoffset(7) NULL
        , [AvgDurationMs] decimal(19,3) NULL
        , [AvgCpuMs] decimal(19,3) NULL
        , [AvgLogicalReads] decimal(19,2) NULL
        , [AvgMemoryGrantKB] decimal(19,2) NULL
        , [PlanCount] bigint NOT NULL
        , [QueryCount] bigint NOT NULL
        , [FirstSeen] datetimeoffset(7) NULL
        , [LastSeen] datetimeoffset(7) NULL
        , PRIMARY KEY ([ProcedureName])
    );

    CREATE TABLE [#FrameworkUsage_SourceStatus]
    (
          [SourceOrdinal] int IDENTITY(1,1) NOT NULL PRIMARY KEY
        , [SourceName] sysname NOT NULL
        , [SourceObject] nvarchar(256) NOT NULL
        , [CapturedAtUtc] datetime2(3) NOT NULL
        , [StatusCode] varchar(40) NOT NULL
        , [IsPartial] bit NOT NULL
        , [ReturnedRowCount] bigint NOT NULL
        , [RequiredPermission] nvarchar(256) NULL
        , [ErrorNumber] int NULL
        , [ErrorMessage] nvarchar(2048) NULL
        , [EvidenceLimit] nvarchar(1000) NOT NULL
    );

    CREATE TABLE [#FrameworkUsage_Warnings]
    (
          [WarningOrdinal] int IDENTITY(1,1) NOT NULL PRIMARY KEY
        , [SourceName] sysname NOT NULL
        , [StatusCode] varchar(40) NOT NULL
        , [ErrorNumber] int NULL
        , [Message] nvarchar(2048) NOT NULL
    );

    IF @MaxZeilen<0
       OR @MinAusfuehrungen IS NULL OR @MinAusfuehrungen<1
       OR @ZeitraumTage<0 OR @ZeitraumTage>365000
       OR @LockTimeoutMs IS NULL OR @LockTimeoutMs NOT BETWEEN 0 AND 60000
       OR @JsonErzeugen IS NULL OR @PrintMeldungen IS NULL
       OR @OutputMode NOT IN('CONSOLE','RAW','TABLE','NONE')
       OR (@OutputMode<>'TABLE' AND NULLIF(LTRIM(RTRIM(COALESCE(@ResultTablesJson,N''))),N'') IS NOT NULL)
    BEGIN
        SELECT
              @StatusCode='INVALID_PARAMETER'
            , @IsPartial=1
            , @ErrorMessage=N'Parameter ungültig. Erlaubt sind @MaxZeilen>=0 oder NULL, @MinAusfuehrungen>=1, @ZeitraumTage zwischen 0 und 365000 oder NULL, @LockTimeoutMs zwischen 0 und 60000 sowie @ResultSetArt=CONSOLE|RAW|TABLE|NONE.';

        INSERT [#FrameworkUsage_SourceStatus]
        (
            [SourceName],[SourceObject],[CapturedAtUtc],[StatusCode],[IsPartial],
            [ReturnedRowCount],[RequiredPermission],[ErrorNumber],[ErrorMessage],[EvidenceLimit]
        )
        VALUES
        (
            N'parameterValidation',N'procedure parameters',@CapturedAtUtc,@StatusCode,1,
            0,NULL,NULL,@ErrorMessage,N'Es wurde keine fachliche Query-Store-Quelle gelesen.'
        );
        GOTO Finalize;
    END;

    IF @OutputMode='TABLE'
    BEGIN
        EXEC [monitor].[InternalPrepareResultTables]
              @ResultTablesJson=@ResultTablesJson
            , @AllowedResultNames=N'moduleStatus|usage|sourceStatus|warnings'
            , @MappingTable=N'#FrameworkUsage_ResultTableMap'
            , @ThrowOnError=1;
    END;

    SET @FetchLimit = CASE
        WHEN @Limit=9223372036854775807 THEN @Limit
        ELSE @Limit+1
    END;

    IF COALESCE(@ZeitraumTage,0)>0
        SET @CutoffUtc=DATEADD(DAY,-@ZeitraumTage,CONVERT(datetimeoffset(7),SYSUTCDATETIME()));

    SET @LockTimeoutSql=N'SET LOCK_TIMEOUT '+CONVERT(nvarchar(20),@LockTimeoutMs)+N';';
    EXEC [sys].[sp_executesql] @LockTimeoutSql;

    BEGIN TRY
        SELECT TOP(1)
              @QueryStoreActualState=TRY_CONVERT(smallint,[actual_state])
            , @QueryStoreActualStateDesc=TRY_CONVERT(nvarchar(60),[actual_state_desc])
            , @QueryStoreReadonlyReason=TRY_CONVERT(bigint,[readonly_reason])
        FROM [sys].[database_query_store_options] WITH (NOLOCK);

        SET @OptionsReadable=1;

        INSERT [#FrameworkUsage_SourceStatus]
        (
            [SourceName],[SourceObject],[CapturedAtUtc],[StatusCode],[IsPartial],
            [ReturnedRowCount],[RequiredPermission],[ErrorNumber],[ErrorMessage],[EvidenceLimit]
        )
        VALUES
        (
            N'queryStoreOptions',N'sys.database_query_store_options',@CapturedAtUtc,
            CASE WHEN @QueryStoreActualState IN(1,2) THEN 'AVAILABLE' ELSE 'UNAVAILABLE_FEATURE' END,
            0,1,N'Query-Store-Metadatensichtbarkeit',NULL,NULL,
            N'Der Zustand beschreibt nur die Lesbarkeit des Query Store zum Erfassungszeitpunkt.'
        );
    END TRY
    BEGIN CATCH
        SELECT
              @StatusCode=CASE WHEN ERROR_NUMBER() IN(229,297,300,371) THEN 'DENIED_PERMISSION' ELSE 'ERROR_HANDLED' END
            , @IsPartial=1
            , @ErrorNumber=ERROR_NUMBER()
            , @ErrorMessage=ERROR_MESSAGE();

        INSERT [#FrameworkUsage_SourceStatus]
        (
            [SourceName],[SourceObject],[CapturedAtUtc],[StatusCode],[IsPartial],
            [ReturnedRowCount],[RequiredPermission],[ErrorNumber],[ErrorMessage],[EvidenceLimit]
        )
        VALUES
        (
            N'queryStoreOptions',N'sys.database_query_store_options',@CapturedAtUtc,@StatusCode,1,
            0,N'Query-Store-Metadatensichtbarkeit',@ErrorNumber,@ErrorMessage,
            N'Ohne lesbaren Query-Store-Zustand wird keine Laufzeitaggregation begonnen.'
        );

        INSERT [#FrameworkUsage_Warnings]([SourceName],[StatusCode],[ErrorNumber],[Message])
        VALUES(N'queryStoreOptions',@StatusCode,@ErrorNumber,COALESCE(@ErrorMessage,N'Query-Store-Zustand nicht lesbar.'));
    END CATCH;

    IF @OptionsReadable=0
    BEGIN
        INSERT [#FrameworkUsage_SourceStatus]
        (
            [SourceName],[SourceObject],[CapturedAtUtc],[StatusCode],[IsPartial],
            [ReturnedRowCount],[RequiredPermission],[ErrorNumber],[ErrorMessage],[EvidenceLimit]
        )
        VALUES
        (
            N'frameworkUsage',N'sys.query_store_query + sys.query_store_plan + sys.query_store_runtime_stats',
            @CapturedAtUtc,'NOT_EXECUTED',1,0,N'Query-Store-Lesesichtbarkeit',NULL,NULL,
            N'Der Laufzeitpfad wurde wegen der nicht lesbaren Vorabquelle nicht ausgeführt.'
        );
        GOTO Finalize;
    END;

    IF @QueryStoreActualState NOT IN(1,2)
    BEGIN
        SELECT
              @StatusCode='UNAVAILABLE_FEATURE'
            , @IsPartial=0
            , @ErrorMessage=N'Query Store ist nicht lesbar aktiv. Die Procedure ändert keine Datenbankoption.';

        INSERT [#FrameworkUsage_SourceStatus]
        (
            [SourceName],[SourceObject],[CapturedAtUtc],[StatusCode],[IsPartial],
            [ReturnedRowCount],[RequiredPermission],[ErrorNumber],[ErrorMessage],[EvidenceLimit]
        )
        VALUES
        (
            N'frameworkUsage',N'sys.query_store_query + sys.query_store_plan + sys.query_store_runtime_stats',
            @CapturedAtUtc,'NOT_EXECUTED',0,0,N'Query-Store-Lesesichtbarkeit',NULL,@ErrorMessage,
            N'Ein deaktivierter oder fehlerhafter Query Store besitzt keine auswertbare Laufzeitevidenz.'
        );

        INSERT [#FrameworkUsage_Warnings]([SourceName],[StatusCode],[ErrorNumber],[Message])
        VALUES(N'frameworkUsage',@StatusCode,NULL,@ErrorMessage);
        GOTO Finalize;
    END;

    BEGIN TRY
        ;WITH [FrameworkQueries] AS
        (
            SELECT
                  [o].[name] COLLATE SQL_Latin1_General_CP1_CS_AS AS [ProcedureName]
                , [q].[query_id]
            FROM [sys].[query_store_query] AS [q] WITH (NOLOCK)
            INNER JOIN [sys].[objects] AS [o] WITH (NOLOCK)
                ON [o].[object_id]=[q].[object_id]
            INNER JOIN [sys].[schemas] AS [s] WITH (NOLOCK)
                ON [s].[schema_id]=[o].[schema_id]
            WHERE [s].[name]=N'monitor' COLLATE SQL_Latin1_General_CP1_CS_AS
              AND [o].[type]='P'
        ),
        [Aggregated] AS
        (
            SELECT
                  [fq].[ProcedureName]
                , SUM(CONVERT(bigint,[rs].[count_executions])) AS [ExecutionCount]
                , MAX(CONVERT(datetimeoffset(7),[rs].[last_execution_time])) AS [LastExecutionTime]
                , CONVERT(decimal(19,3),
                    SUM(CONVERT(float,[rs].[avg_duration])*CONVERT(float,[rs].[count_executions]))
                    / NULLIF(SUM(CONVERT(float,[rs].[count_executions])),0.0) / 1000.0) AS [AvgDurationMs]
                , CONVERT(decimal(19,3),
                    SUM(CONVERT(float,[rs].[avg_cpu_time])*CONVERT(float,[rs].[count_executions]))
                    / NULLIF(SUM(CONVERT(float,[rs].[count_executions])),0.0) / 1000.0) AS [AvgCpuMs]
                , CONVERT(decimal(19,2),
                    SUM(CONVERT(float,[rs].[avg_logical_io_reads])*CONVERT(float,[rs].[count_executions]))
                    / NULLIF(SUM(CONVERT(float,[rs].[count_executions])),0.0)) AS [AvgLogicalReads]
                , CONVERT(decimal(19,2),
                    SUM(CONVERT(float,[rs].[avg_query_max_used_memory])*8.0*CONVERT(float,[rs].[count_executions]))
                    / NULLIF(SUM(CONVERT(float,[rs].[count_executions])),0.0)) AS [AvgMemoryGrantKB]
                , CONVERT(bigint,COUNT(DISTINCT [p].[plan_id])) AS [PlanCount]
                , CONVERT(bigint,COUNT(DISTINCT [fq].[query_id])) AS [QueryCount]
                , MIN(CONVERT(datetimeoffset(7),[rs].[first_execution_time])) AS [FirstSeen]
                , MAX(CONVERT(datetimeoffset(7),[rs].[last_execution_time])) AS [LastSeen]
            FROM [FrameworkQueries] AS [fq]
            INNER JOIN [sys].[query_store_plan] AS [p] WITH (NOLOCK)
                ON [p].[query_id]=[fq].[query_id]
            INNER JOIN [sys].[query_store_runtime_stats] AS [rs] WITH (NOLOCK)
                ON [rs].[plan_id]=[p].[plan_id]
            WHERE @CutoffUtc IS NULL
               OR [rs].[last_execution_time]>=@CutoffUtc
            GROUP BY [fq].[ProcedureName]
            HAVING SUM(CONVERT(bigint,[rs].[count_executions]))>=@MinAusfuehrungen
        )
        INSERT [#FrameworkUsage_UsageCandidates]
        (
            [ProcedureName],[ExecutionCount],[LastExecutionTime],[AvgDurationMs],
            [AvgCpuMs],[AvgLogicalReads],[AvgMemoryGrantKB],[PlanCount],[QueryCount],
            [FirstSeen],[LastSeen]
        )
        SELECT TOP(@FetchLimit)
              [ProcedureName],[ExecutionCount],[LastExecutionTime],[AvgDurationMs]
            , [AvgCpuMs],[AvgLogicalReads],[AvgMemoryGrantKB],[PlanCount],[QueryCount]
            , [FirstSeen],[LastSeen]
        FROM [Aggregated]
        ORDER BY [ExecutionCount] DESC,[ProcedureName];

        IF @Limit<9223372036854775807
           AND EXISTS(SELECT 1 FROM [#FrameworkUsage_UsageCandidates] WHERE [RowOrdinal]>@Limit)
            SET @HasMoreRows=1;

        INSERT [#FrameworkUsage_Usage]
        (
            [ProcedureName],[ExecutionCount],[LastExecutionTime],[AvgDurationMs],
            [AvgCpuMs],[AvgLogicalReads],[AvgMemoryGrantKB],[PlanCount],[QueryCount],
            [FirstSeen],[LastSeen]
        )
        SELECT
              [ProcedureName],[ExecutionCount],[LastExecutionTime],[AvgDurationMs]
            , [AvgCpuMs],[AvgLogicalReads],[AvgMemoryGrantKB],[PlanCount],[QueryCount]
            , [FirstSeen],[LastSeen]
        FROM [#FrameworkUsage_UsageCandidates]
        WHERE [RowOrdinal]<=@Limit;

        SET @ReturnedRowCount=(SELECT COUNT_BIG(*) FROM [#FrameworkUsage_Usage]);
        SET @StatusCode=CASE WHEN @ReturnedRowCount=0 THEN 'AVAILABLE_EMPTY' ELSE 'AVAILABLE' END;

        INSERT [#FrameworkUsage_SourceStatus]
        (
            [SourceName],[SourceObject],[CapturedAtUtc],[StatusCode],[IsPartial],
            [ReturnedRowCount],[RequiredPermission],[ErrorNumber],[ErrorMessage],[EvidenceLimit]
        )
        VALUES
        (
            N'frameworkUsage',N'sys.query_store_query + sys.query_store_plan + sys.query_store_runtime_stats',
            @CapturedAtUtc,@StatusCode,0,@ReturnedRowCount,
            N'Query-Store-Lesesichtbarkeit',NULL,NULL,
            N'Query-Store-Retention, Capture Mode, Cleanup, Flushzeitpunkt und Metadatensichtbarkeit begrenzen die Aussage. Mittelwerte sind nach Ausführungsanzahl gewichtete Intervallaggregate.'
        );
    END TRY
    BEGIN CATCH
        SELECT
              @StatusCode=CASE WHEN ERROR_NUMBER() IN(229,297,300,371) THEN 'DENIED_PERMISSION' ELSE 'ERROR_HANDLED' END
            , @IsPartial=1
            , @ErrorNumber=ERROR_NUMBER()
            , @ErrorMessage=ERROR_MESSAGE();

        INSERT [#FrameworkUsage_SourceStatus]
        (
            [SourceName],[SourceObject],[CapturedAtUtc],[StatusCode],[IsPartial],
            [ReturnedRowCount],[RequiredPermission],[ErrorNumber],[ErrorMessage],[EvidenceLimit]
        )
        VALUES
        (
            N'frameworkUsage',N'sys.query_store_query + sys.query_store_plan + sys.query_store_runtime_stats',
            @CapturedAtUtc,@StatusCode,1,0,N'Query-Store-Lesesichtbarkeit',@ErrorNumber,@ErrorMessage,
            N'Die Laufzeitaggregation wurde kontrolliert abgebrochen; keine eigene Erfassung oder Konfigurationsänderung wurde ausgeführt.'
        );

        INSERT [#FrameworkUsage_Warnings]([SourceName],[StatusCode],[ErrorNumber],[Message])
        VALUES(N'frameworkUsage',@StatusCode,@ErrorNumber,COALESCE(@ErrorMessage,N'Query-Store-Aggregation fehlgeschlagen.'));
    END CATCH;

Finalize:
    SET @ReturnedRowCount=(SELECT COUNT_BIG(*) FROM [#FrameworkUsage_Usage]);

    IF @ErrorMessage IS NULL
       AND @StatusCode NOT IN('AVAILABLE','AVAILABLE_EMPTY')
    BEGIN
        SELECT TOP(1)
              @ErrorNumber=COALESCE(@ErrorNumber,[ErrorNumber])
            , @ErrorMessage=[Message]
        FROM [#FrameworkUsage_Warnings]
        ORDER BY [WarningOrdinal];
    END;

    INSERT [#FrameworkUsage_ModuleStatus]
    (
        [ModuleName],[CapturedAtUtc],[StatusCode],[IsPartial],
        [QueryStoreActualStateDesc],[QueryStoreReadonlyReason],[RequestedWindowDays],
        [MinimumExecutions],[ReturnedRowCount],[HasMoreRows],[ErrorNumber],[ErrorMessage]
    )
    VALUES
    (
        N'USP_FrameworkUsageFromQueryStore',@CapturedAtUtc,@StatusCode,@IsPartial,
        @QueryStoreActualStateDesc,@QueryStoreReadonlyReason,NULLIF(@ZeitraumTage,0),
        COALESCE(@MinAusfuehrungen,0),@ReturnedRowCount,@HasMoreRows,@ErrorNumber,@ErrorMessage
    );

    IF @JsonErzeugen=1
    BEGIN
        DECLARE @MetaJson nvarchar(max)=
        (
            SELECT
                  N'FrameworkUsageFromQueryStore' AS [resultName]
                , 1 AS [schemaVersion]
                , @CapturedAtUtc AS [generatedAtUtc]
                , @StatusCode AS [statusCode]
                , @IsPartial AS [isPartial]
                , @QueryStoreActualStateDesc AS [queryStoreActualStateDesc]
                , @QueryStoreReadonlyReason AS [queryStoreReadonlyReason]
                , NULLIF(@ZeitraumTage,0) AS [requestedWindowDays]
                , @MinAusfuehrungen AS [minimumExecutions]
                , @ReturnedRowCount AS [returnedRowCount]
                , @HasMoreRows AS [hasMoreRows]
                , @ErrorNumber AS [errorNumber]
                , @ErrorMessage AS [errorMessage]
            FOR JSON PATH,WITHOUT_ARRAY_WRAPPER,INCLUDE_NULL_VALUES
        );
        DECLARE @UsageJson nvarchar(max)=
        (
            SELECT *
            FROM [#FrameworkUsage_Usage]
            ORDER BY [ExecutionCount] DESC,[ProcedureName]
            FOR JSON PATH,INCLUDE_NULL_VALUES
        );
        DECLARE @SourceStatusJson nvarchar(max)=
        (
            SELECT *
            FROM [#FrameworkUsage_SourceStatus]
            ORDER BY [SourceOrdinal]
            FOR JSON PATH,INCLUDE_NULL_VALUES
        );
        DECLARE @WarningsJson nvarchar(max)=
        (
            SELECT *
            FROM [#FrameworkUsage_Warnings]
            ORDER BY [WarningOrdinal]
            FOR JSON PATH,INCLUDE_NULL_VALUES
        );
        SET @Json=CONCAT
        (
              N'{"meta":',COALESCE(@MetaJson,N'{}')
            , N',"usage":',COALESCE(@UsageJson,N'[]')
            , N',"sourceStatus":',COALESCE(@SourceStatusJson,N'[]')
            , N',"warnings":',COALESCE(@WarningsJson,N'[]')
            , N'}'
        );
    END;

    SET @LockTimeoutSql=N'SET LOCK_TIMEOUT '+CONVERT(nvarchar(20),@OriginalLockTimeout)+N';';
    EXEC [sys].[sp_executesql] @LockTimeoutSql;

    IF @ConsoleResultRequested=1
    BEGIN
        EXEC [monitor].[InternalEmitConsoleResult]
              @SourceTable=N'#FrameworkUsage_Usage'
            , @ResultLabel=N'Framework-Nutzung aus Query Store'
            , @EmptyMessage=N'Keine sichtbare Framework-Nutzung im gewählten Query-Store-Scope';
    END
    ELSE IF @OutputMode='RAW'
    BEGIN
        SELECT * FROM [#FrameworkUsage_ModuleStatus];
        SELECT * FROM [#FrameworkUsage_Usage] ORDER BY [ExecutionCount] DESC,[ProcedureName];
        SELECT * FROM [#FrameworkUsage_SourceStatus] ORDER BY [SourceOrdinal];
        SELECT * FROM [#FrameworkUsage_Warnings] ORDER BY [WarningOrdinal];
    END
    ELSE IF @OutputMode='TABLE'
    BEGIN
        DECLARE @ResultName sysname,@TargetTable sysname,@SourceTable sysname;
        DECLARE [ResultCursor] CURSOR LOCAL FAST_FORWARD FOR
            SELECT [ResultName],[TargetTable]
            FROM [#FrameworkUsage_ResultTableMap]
            ORDER BY [ResultName];
        OPEN [ResultCursor];
        FETCH NEXT FROM [ResultCursor] INTO @ResultName,@TargetTable;
        WHILE @@FETCH_STATUS=0
        BEGIN
            SET @SourceTable=CASE @ResultName
                WHEN N'moduleStatus' THEN N'#FrameworkUsage_ModuleStatus'
                WHEN N'usage' THEN N'#FrameworkUsage_Usage'
                WHEN N'sourceStatus' THEN N'#FrameworkUsage_SourceStatus'
                WHEN N'warnings' THEN N'#FrameworkUsage_Warnings' END;
            EXEC [monitor].[InternalWriteResultTable]
                  @SourceTable=@SourceTable
                , @TargetTable=@TargetTable
                , @ThrowOnError=1;
            FETCH NEXT FROM [ResultCursor] INTO @ResultName,@TargetTable;
        END;
        CLOSE [ResultCursor];
        DEALLOCATE [ResultCursor];
    END;

    IF @PrintMeldungen=1
       AND @StatusCode NOT IN('AVAILABLE','AVAILABLE_EMPTY')
    BEGIN
        DECLARE @PrintMessage nvarchar(2048)=LEFT
        (
            CONCAT(N'USP_FrameworkUsageFromQueryStore: ',@StatusCode,N'. ',
                   COALESCE(@ErrorMessage,N'Siehe sourceStatus und warnings.')),
            2048
        );
        RAISERROR(N'%s',10,1,@PrintMessage) WITH NOWAIT;
    END;

    SELECT
          @StatusCodeOut=@StatusCode
        , @IsPartialOut=@IsPartial
        , @ErrorNumberOut=@ErrorNumber
        , @ErrorMessageOut=@ErrorMessage;
END;
GO
-- END SOURCE: Code/09_VersionAdaptive/500_USP_FrameworkUsageFromQueryStore.sql
